local addonName, addonTable = ...

addonTable.questData['de'] = {
[1] = {title = "The \"Chow\" Quest (123)aa", objective = "Kill Kobold Vermin, 2 of em.$Tpunk;!  Kill Kobold Vermin, 2 of em. NEW TEST AGAINDer folgende Zauber wird auf euch gewirkt:\n\n", description = "$Tpunk;!  Kill Kobold Vermin, 2 of em. NEW TEST AGAINDer folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nJahr des Huhns\n\nIhr bekommt:\n\n"},
[2] = {title = "Klaue von Scharfkralle", objective = "Bringt die Klaue von Scharfkralle zu Senani Thunderheart im Splintertreeposten in Ashenvale.", description = "Der mächtige Hippogryph Scharfkralle wurde getötet und die Klaue der erschlagenen Bestie dient als Beweis für Euren Sieg. Senani Thunderheart im Splintertreeposten wird zum Beweis Eurer Tat sicher gern diese Trophäe sehen wollen.", progress = "Ja, <Klasse>, ich habe Eure Ankunft bereits gespürt. Habt Ihr weitere Neuigkeiten von Eurer Jagd zu berichten?", completion = "Wirklich beeindruckend, &lt;Name&gt;... Die Klaue von Scharfkralle dürfte nicht einfach zu bekommen gewesen sein. Die Jagd in Ashenvale läuft gut für Euch!\n\nScharfkralle hat über lange Zeit hinweg die Peons aus den Holzfällerlagern entlang seinem Weg terrorisiert, wenn diese versuchten, hierher zum Splintertreeposten zu gelangen. Zweifelsohne werden viele begeisterte Lieder über Eure Tapferkeit an den Lagerfeuern und in den Holzfällerlagern überall in Ashenvale erschallen, sobald man davon hört, dass Ihr es wart, der die Bestie bezwungen hat.", rewards = "Ihr bekommt:\n\n"},
[5] = {title = "Jitters' knurrender Magen", objective = "Sprecht mit Küchenchef Grual.", description = "Ich verstecke mich jetzt schon seit Wochen in dieser Geisterstadt, und die ganze Zeit habe ich nichts gegessen außer Maden und Unkraut! Ich brauche was Anständiges zum Essen, und ich werde mich nicht lumpen lassen.\n\nBringt mir ein Festessen, und ich bezahle Euch gut dafür.\n\nIch habe gehört, dass Küchenchef Grual aus der Taverne Zum roten Raben in Dunkelhain ganz ausgezeichnete schwärzliche Krebsküchlein macht...", progress = nil, completion = "Ihr braucht einige Krebsküchlein, wie? Na ja, ich könnte Euch vielleicht ein paar machen.", rewards = "Ihr bekommt:\n\n"},
[6] = {title = "Kopfgeld auf Garrick Padfoot", objective = "Tötet Garrick Padfoot und bringt seinen Kopf zu Deputy Willem in der Nähe der Abtei von Nordhain.", description = "Garrick Padfoot, ein Dieb und Halsabschneider, der schon seit Wochen unseren Bauern und Händlern das Leben schwer macht, ist bei einem Schuppen in der Nähe der Weinberge gesehen worden. Die Weinberge liegen im Osten der Abtei, auf der anderen Seite der Brücke. Bringt mir den Kopf des Schurken und verdient Euch das Kopfgeld, das auf ihn ausgesetzt ist!\n\nDoch seht Euch vor, <Name>. Garrick hat eine Bande von Rohlingen um sich versammelt, also werdet Ihr nicht leicht an ihn herankommen.", progress = "Habt Ihr Garricks Schuppen gefunden? Sind wir diesen Schurken endlich los?", completion = "Ha, Ihr habt ihn erwischt! Ihr habt ganz Elwynn einen großen Dienst erwiesen und Euch ein schönes Kopfgeld verdient!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchmale HoseMehrlagige TunikaFähnrich-Umhang\n\nIhr bekommt außerdem:\n\n"},
[7] = {title = "Säuberung im Koboldlager", objective = "Tötet 10 von dem Koboldgezücht und kehrt dann zu Marshal McBride zurück.", description = "Eure erste Aufgabe ist eine Säuberung, <Name>. Ein Koboldklan hat sich in den Wäldern im Norden eingenistet. Begebt Euch dorthin und bekämpft das Koboldgezücht, das Ihr dort finden werdet. Dezimiert es, damit wir die Kobolde eines Tages gänzlich aus Nordhain vertreiben können.", progress = nil, completion = "Gut gemacht, Bürger. Diese Kobolde sind Diebe und Feiglinge, aber wenn sie in Massen auftreten, dann sind sie doch eine Gefahr für uns. Und die Menschen von Stormwind können nun wirklich keine weitere Gefahr gebrauchen.\n\nHabt meinen Dank dafür, dass Ihr sie besiegtet!", rewards = "Ihr bekommt:\n\n"},
[8] = {title = "Ein Schurkenhandel", objective = "Liefert den unscheinbaren Brief bei Gastwirtin Renee in Tirisfal ab.", description = "Heda, Kamerad! Wollt Ihr nicht einem jungen Mann, der mehr als seinen Teil an hirnlosen Zombies und Spinnen umgelegt hat, einen Gefallen tun?\n\nIch hab hier einen Brief, der muss nach Brill... zu so einer Gastwirtin namens Renee Irgendwas. Ist eigentlich völlig egal, wie sie mit Nachnamen heißt.\n\nNa egal, jedenfalls ist es ein netter kleiner Ort, wo lauter Opfer der Seuche wohnen, die versuchen, sich irgendwie durchs Leben zu schlagen. Und es wäre ein toller Ort für Euch, an dem Ihr Euch ausruhen könnt, falls das mal nötig wird. Ihr solltet Euch den wirklich mal anseh'n - macht es, und ich bezahl Euch auch noch gut dafür.", progress = "Ja? Ja? Was ist?\n\nFür ein Volk von Wesen, die unter Wasser nicht atmen müssen, haben sie schon einen sehr gesunden Appetit. Fühlt Euch ganz wie zu Hause, fühlt Euch ganz wie zu Hause. Ich heiße Renee, falls Ihr irgendetwas braucht.", completion = "Ach? Ein Brief? Wie schön! Ich warte schon seit langem darauf, wieder einmal etwas von meiner lieben alten Mutter in Deathknell zu hören. Sie ist ja eine so wunderbare Person! Ich frage mich, wie die Gute so zurechtkommt.\n\nWas? Zu fröhlich? Ihr kauft mir das nicht ab, wie?\n\nNa, dann verschwindet. Es geht Euch sowieso rein gar nichts an, von wem dieser Brief ist. Na los! Verschwindet schon!\n\nKommt wieder, sobald Ihr 'n bisschen Geld habt, das Ihr ausgeben könnt, Faulenzer.\n\nSonst kommt Ihr als Nächstes noch her und wollt Euch nach einem langen Tag des Abenteuerns hier ausruhen oder so'n Quark.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWaldpilzkappeErfrischendes Quellwasser\n\nIhr bekommt außerdem:\n\n"},
[9] = {title = "Tod auf den Feldern", objective = "Bauer Saldean möchte, dass Ihr 20 Erntebehüter tötet.", description = "Jetzt seht Euch nur an, was aus diesem Ort geworden ist! In dieser Gegend lebten einst ehrbare Bauersleute. Die verdammten Diebe haben sie alle vertrieben. Aber mich nicht! Jetzt sieht es allerdings so aus, als hätten einige Erntebehüter sich in den Feldern breit gemacht.\n\nWenn Ihr Euch dem gewachsen fühlt, dann geht hinaus und tötet dort draußen 20 von ihnen. Wenn Ihr fertig seid, kommt zurück und holt Euch Eure Bezahlung ab. Und wenn Ihr alle in meinem Feld erwischt habt, dann räumt auch in den angrenzenden Feldern auf.", progress = "Ah, wie ich sehe, seid Ihr wieder da! Ich hoffe doch sehr, dass Ihr fleißig wart und die Felder von diesen Erntebehütern gesäubert habt. Habt Ihr schon 20 getötet?", completion = "Gute Arbeit, mein Freund. Ihr habt Euch Eure Bezahlung redlich verdient. Wer weiß, vielleicht wird Westfall ja wieder aufblühen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHose des ErntearbeitersRobe des Erntearbeiters\n\nIhr bekommt außerdem:\n\n"},
[10] = {title = "Die Erlösung von Scrimshank", objective = "Erforscht das Schicksal von Unterfeldmesser Scrimshank und bringt entweder ihn oder seine Feldmesserausrüstung nach Gadgetzan zum Leitenden Feldmesser Fizzledowser.", description = "Oh, das ist einfach schrecklich! Ich habe meinen besten Gehilfen, Unterfeldmesser Scrimshank, in die Wüste südöstlich von hier geschickt. Das ist ein Gebiet, das wir die Klaffende Schlucht nennen. Nun ja, er wird vermisst und in seinem letzten Bericht sprach er davon, dass es dort, wo er war, noch mehr dieser komischen Viecher gäbe. Könnte es sein, dass sie sich jetzt in zwei großen Gebieten der Wüste eingenistet haben?\n\nBegebt Euch bitte für mich zur Klaffenden Schlucht und sucht nach Scrimshank! Das... oder findet wenigstens seine Feldmesserausrüstung. Ich fürchte, das ist alles, was von dem Armen übrig geblieben ist.", progress = "Nun, was habt Ihr für Neuigkeiten? Ihr seht aus, als hättet Ihr einiges durchgemacht... ist Scrimshank am Leben?", completion = "Er war ein guter Goblin, der junge Scrimshank. Hoffen wir, dass sein Ableben durch das, was er mit seiner Feldmesserausrüstung aufzeichnen konnte, nicht umsonst war.\n\nEs scheint als wären wir mit diesen Viechern in eine ziemlich unangenehme Lage geraten. Sie sind viel zu gerissen und unsere bisherigen Forschungen deuten an, dass sie sich möglicherweise sogar unter dem kontrollierenden Einfluss eines Dritten befinden! Wenn das stimmt, ist das nicht nur für Gadgetzan ein schlechtes Zeichen, sondern für die ganze Wüste!", rewards = "Ihr bekommt:\n\n"},
[11] = {title = "Kopfgeld auf die Flusspfotengnolle", objective = "Bringt Deputy Rainer in der Kaserne 8 bemalte Gnoll-Armbinden.", description = "Gnolle, brutale Wesen, die in dieser Gegend nichts zu suchen haben, sind entlang der Grenzen des Waldes von Elwynn gesehen worden. Ein großes Rudel, viel zu viele, als dass wir allein mit ihnen fertig werden könnten, hat sich in den Wäldern südlich von jenem Wachturm dort eingenistet. Eine weitere Gruppe hat sich im Gebiet nahe des Steinhügelsees im Osten eingenistet.\n\nDie Armee von Stormwind wird jeden belobigen, der dabei hilft, die Gnolle zu töten. Bringt mir ihre bemalten Gnoll-Armbinden als Beweis für Eure Tat.", progress = "Seid gegrüßt, <Name>. Wart Ihr Gnolle töten?", completion = "Wie ich sehe, wart Ihr fleißig! Habt Dank, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMiliz-RundschildStraßenjungen-Hose\n\nIhr bekommt außerdem:\n\n"},
[12] = {title = "Die Volksmiliz", objective = "Gryan Stoutmantle möchte, dass Ihr 15 Fallensteller der Defias und 15 Schmuggler der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", description = "Die Volksmiliz hat nur ein einziges Ziel: Westfall zu verteidigen und den Frieden in dieses Land zurückzubringen. Doch leider muss der Frieden nur allzu oft mit Blut bezahlt werden. \n\nEiner meiner Späher hat uns Kunde davon gebracht, dass eine Fallenstellerbande der Defias hier in der Nähe verheerende Schäden anrichtet. Mir liegen Berichte vor, dass einige Fallensteller der Defias in der Nähe des Jangoschachts im Nordwesten gesichtet wurden, ebenso bei Molsens Hof und bei Furlbrows Kürbishof. Wenn Ihr unseren Reihen beizutreten wünscht, dann erschlagt 15 Fallensteller der Defias und 15 Schmuggler der Defias und kehrt zu mir zurück.", progress = "Vielleicht habe ich mich nicht klar genug ausgedrückt, Kandidat. Um Euren Wert als Diener der Volksmiliz und Diener des Lichtes zu beweisen, müsst Ihr 15 Fallensteller der Defias und 15 Schmuggler der Defias erschlagen und zu mir zurückkehren, sobald Ihr dies getan habt.", completion = "Gut gemacht, &lt;Name&gt;. Mein Späher hat Eure tapferen Taten beobachtet. Bis jetzt bewährt Ihr Euch recht gut.", rewards = "Ihr bekommt:\n\n"},
[13] = {title = "Die Volksmiliz", objective = "Gryan Stoutmantle möchte, dass Ihr 15 Plünderer der Defias und 15 Ausplünderer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", description = "Eine Bande heimtückischer Plünderer der Defias ist dabei gesehen worden, wie sie den Goldküstensteinbruch, Moonbrook und Alexstons Bauernhof ausplünderten. Die Volksmiliz kann ein solches Verhalten nicht hinnehmen. Macht Euch unverzüglich auf den Weg, <Name>, und zeigt, dass das Licht in Westfall zugegen ist.\n\nDer Goldküstensteinbruch befindet sich in der Nähe der Küste, westlich vom Turm. Im nächsten Schritt Eurer Ausbildung müsst Ihr 15 dieser üblen Plünderer der Defias und 15 Ausplünderer der Defias töten.", progress = "Wir haben jetzt keine Zeit für Geschwätz, <Name>! Die Plünderer der Defias hindern die Bewohner von Westfall daran, den Frieden und Wohlstand zu genießen, den diese verdient haben. Tötet unbedingt mindestens 15 Plünderer der Defias und 15 Ausplünderer der Defias. Das wird ihnen die deutliche Botschaft vermitteln, dass wir Verderbnis hier nicht tolerieren.", completion = "Ihr habt Euren Wert für die Volksmiliz durch die tapferen Taten bewiesen, die Ihr bisher vollbracht habt.", rewards = "Ihr bekommt:\n\n"},
[14] = {title = "Die Volksmiliz", objective = "Gryan Stoutmantle möchte, dass Ihr 15 Straßenräuber der Defias, 5 Pfadpirscher der Defias und 5 Knöchelhauer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt.", description = "Einige Defias konnten wir bislang nicht erwischen. Mein bester Späher berichtet, dass diese Defias in der ganzen Gegend auf Raubzug gehen und schon bis Süd-Westfall gekommen sind. Wir glauben, dass sie sich in den Dolchhügeln versteckt halten und dort ihren nächsten Schachzug planen. Schaltet diese Verbrecher im Namen der Volksmiliz aus.", progress = "Es ist jetzt nicht die Zeit für müßiges Geplauder, <Name>. Wenn Ihr Euch der Volksmiliz noch immer beweisen wollt, so müsst Ihr die Defias töten, von denen ich Euch zuvor berichtete. Kehrt zu mir zurück, wenn Ihr Eure Pflicht erfüllt habt.", completion = "Als ich Lordaeron, dieses besudelte Land, verließ, fand ich hier, in meiner Heimat, schlimme Zustände vor. Doch es besteht noch Hoffnung für Westfall. Wie Ihr durch Euren Heldenmut im Kampfe bewiesen habt, dient Ihr ganz offensichtlich ehrenvoll unserer Sache. Mit großem Stolz berufe ich Euch in die Volksmiliz ein. Möge das Licht über Euch leuchten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchneide der VolksmilizFaust der VolksmilizFunke der Volksmiliz\n\nIhr bekommt außerdem:\n\n"},
[15] = {title = "Überprüfung der Echokammmine", objective = "Tötet 10 Koboldtagelöhner und erstattet dann Marshal McBride Euren Bericht.", description = "Wie mir meine Späher mitteilen, ist das Koboldproblem größer als wir dachten, <Name>. Eine Gruppe Koboldtagelöhner hat ihr Lager in der Nähe der Echokammmine im Norden aufgeschlagen.\n\nBegebt Euch zu der Mine und entfernt die Kobolde. Wir wissen, dass sich mindestens 10 von ihnen dort aufhalten. Tötet sie, seht nach, ob dort noch mehr von ihnen sind, kommt dann zu mir zurück und erstattet Bericht.", progress = nil, completion = "Es gefällt mir gar nicht, dass sich so viele Kobolde in unserer Mine herumtreiben. Das bedeutet nichts Gutes. Hier, nehmt dies als Bezahlung und sprecht mich wieder an, sobald Ihr dazu bereit seid. Denn ich möchte, dass Ihr noch einmal in die Minen zurückkehrt.", rewards = "Ihr bekommt:\n\n"},
[16] = {title = "Etwas zu trinken für Gerard", objective = "Es macht durstig, das Land zu bestellen, und ich bin immer auf der Suche nach erfrischendem Quellwasser.\n\nWenn Ihr welches habt, dann mache ich einen Tauschhandel mit Euch.", description = nil, progress = "Es macht durstig, das Land zu bestellen, und ich bin immer auf der Suche nach erfrischendem Quellwasser.\n\nWenn Ihr welches habt, dann mache ich einen Tauschhandel mit Euch.", completion = "Danke, &lt;Name&gt;! Und kommt jederzeit wieder, wenn Ihr noch einen Handel machen wollt.", rewards = "Ihr bekommt:\n\nGlänzender roter Apfel"},
[17] = {title = "Reagenzsuche in Uldaman", objective = "Bringt zwölf magenta Funguskappen nach Thelsamar zu Ghak Healtouch.", description = "Ich habe von einer neu entdeckten Pflanze gehört, den magenta Funguskappen. Sie wachsen in Büscheln tief drinnen in der Uldaman-Grabungsstätte; vielleicht kann man sie auch anderswo finden, aber bisher ist das der einzige mir bekannte Ort, an dem sie gedeihen. Ich möchte ihren potenziellen Nutzen für die Alchimie erforschen und dafür brauche ich Euch.\n\nFindet die magenta Funguskappen-Büschel und bringt mir ein Dutzend Kappen. Aber seid gewarnt - die Pflanzen stoßen vielleicht Giftsporen aus, wenn man sie anstößt.\n\nWenn Ihr das für mich tut, dann braue ich Euch einen Schwung von meinem berühmten Regenerierungselixier!", progress = "Habt Ihr die magenta Funguskappen bekommen, die ich für meine alchimistische Arbeit benötige? Keine Kappen - keine Belohnung!", completion = "Gut gemacht, &lt;Name&gt;, Ihr habt Euren Wert abermals bewiesen! Die Pilzkappen werden wahrlich ein interessantes Studienobjekt sein!\n\nUnd nun genießt, wie versprochen, eine Kostprobe meines wirksamen Regenerierungsgebräus aus meinem persönlichen Vorrat...\n\nFalls Ihr ein geübter Alchimist seid, ergeben sich für uns vielleicht noch weitere Geschäfte. Ungeachtet dessen danke ich Euch für Eure Hilfe!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nRegenerationstrank"},
[18] = {title = "Bruderschaft der Diebe", objective = "Bringt 12 rote Sackleinenkopftücher zu Deputy Willem in der Nähe der Abtei von Nordhain.", description = "Seit kurzem treibt sich eine neue Diebesbande in Nordhain herum. Sie nennen sich die \"Bruderschaft der Defias\" und sind auf der anderen Seite des Flusses im Osten gesehen worden.\n\nIch weiß nicht genau, was sie vorhaben, aber ich bin mir sicher, es ist nichts Gutes! Bringt mir die Kopftücher, die sie tragen, und ich werde Euch mit einer Waffe belohnen.", progress = "Habt Ihr schon diese Kopftücher für mich zusammenbekommen?", completion = "Ah, wie ich sehe, seid Ihr zurück und habt Kopftücher dabei. Die Armee von Stormwind weiß Eure Hilfe zu schätzen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMilizdolchMilizhammerMilizkurzschwertMiliz-KriegshammerMilizsstecken\n\nIhr bekommt außerdem:\n\n"},
[19] = {title = "Tharil'zun", objective = "Bringt den Kopf von Tharil'zun ins Rotkammgebirge zu Marshal Marris.", description = "Zwischen hier und Burg Steinwacht legen Kundschafter und Renegaten der Blackrock ständig Hinterhalte. Der Anführer der Kundschafter heißt Tharil'zun und diesen Orc wollen wir haben. Bringt mir den Kopf von Tharil'zun!", progress = "Die Blackrockorcs setzen uns noch immer stark unter Druck. Aber habt Ihr uns wenigstens von Tharil'zun befreit?", completion = "Tharil'zun war ein bösartiger, verschlagener Orc. Gut gemacht! Ich bin sicher, er war nicht leicht zu besiegen. Hier ist Eure Belohnung, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFeuergehärteter RundschildOrc-Zermalmer\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[20] = {title = "Bedrohung durch die Blackrock", objective = "Bringt 10 kampferprobte Äxte nach Seenhain zu Marshal Marris.", description = "Die Orcs des Blackrockklans haben die brennende Steppe verlassen und Burg Steinwacht im Norden besetzt. Von dort aus ziehen sie marodierend durch das Gebiet nördlich von Seenhain, so dass dessen Bewohner sich nicht mehr aus der Stadt wagen und dort eingesperrt sind wie Vieh in einem zu engen Pferch.\n\nHelft uns, diese Bedrohung von Seenhain zu nehmen! Tötet diese Orcs der Blackrock und bringt mir 10 ihrer kampferprobten Äxte zum Beweis.\n\nUnd obwohl die Blackrocks uns vor allem aus dem Norden bedrohen, haben wir auch gehört, dass sich noch weitere in der südöstlichen Ecke des Rotkammgebirges aufhalten. Wenn Ihr dort welche findet, solltet Ihr die auch jagen.", progress = "Na, habt Ihr Orcs erschlagen, <Name>? Dann zeigt es mir.", completion = "Gut, jetzt sind es wesentlich weniger Orcs, um die wir uns sorgen müssen, danke.", rewards = "Ihr bekommt:\n\n"},
[21] = {title = "Scharmützel in der Echokammmine", objective = "Tötet 12 Koboldhilfsarbeiter und kehrt dann zu Marshal McBride in der Abtei von Nordhain zurück.", description = "Eure Untersuchungen beweisen, dass die Echokammmine gesäubert werden muss. Kehrt in die Mine zurück und helft dabei, sie von den Kobolden zu befreien.\n\nIhr dürft keine Zeit verlieren, <Name>. Je länger die Kobolde sich ungehindert in der Mine aufhalten können, umso festere Wurzeln fassen sie in Nordhain.", progress = "Ich weiß, das es ein blutiges Geschäft ist, <Name>, aber die Sicherheit von Nordhain hängt davon ab. Seid Ihr bereit, mir Bericht zu erstatten?", completion = "Und wieder habt Ihr Euch meinen Respekt und die Dankbarkeit der Armee von Stormwind verdient. Vielleicht gibt es in der Mine noch immer Kobolde, doch ich werde andere schicken, um gegen sie zu kämpfen. Für Euch haben wir andere Aufgaben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAusstatter-GürtelAusstatter-StiefelAusstatter-Handschuhe\n\nIhr bekommt außerdem:\n\n"},
[22] = {title = "Pastete aus Geiferzahnleber", objective = "Salma Saldean braucht 8 Geiferzahnlebern für ihre Pastete aus Geiferzahnleber.", description = "Die Zwiebeln sind geschält, der Knoblauch ist gehackt, der Rosmarin ist zerstoßen, die Kruste ist gebacken, das Dillkraut ist gewiegt und die Sauce steht auf dem Herd. Jetzt brauche ich für meine berühmte Fleischpastete nur noch 8 Geiferzahnlebern!", progress = "Ich brauche für meine berühmte Fleischpastete nichts weiter als 8 Geiferzahnlebern!", completion = "Die sind genau richtig, &lt;Name&gt;! Vielen herzlichen Dank. Heute abend werden Bauer Saldean und ich königlich speisen. Und hier ist auch etwas für Euch, für Eure harte Arbeit. Bei mir muss kein &lt;Klasse&gt; hungern.", rewards = "Ihr bekommt:\n\nPastete aus GeiferzahnleberRezept: Pastete aus Geiferzahnleber"},
[23] = {title = "Ursangus' Tatze", objective = "Bringt Ursangus' Tatze zu Senani Thunderheart im Splintertreeposten in Ashenvale.", description = "Die Tatze des mächtigen Bären Ursangus stellt die Trophäe für diesen Teil der Jagd in Ashenvale dar. Auf der Tatze befindet sich ein kleines Halbmond-Emblem; die Bedeutung dieses Emblems bleibt jedoch ein Geheimnis.\n\nDie Tatze soll zu Senani Thunderheart im Splintertreeposten gebracht werden, um zu beweisen, dass Ihr das mächtige Tier besiegt und diesen Teil der Jagd abgeschlossen habt.", progress = "Ah... <Name>... ich habe gerade an Euch gedacht! Wie geht es mit der Jagd voran?", completion = "Ah, die Tatze von Ursangus! Euer Geschick ist beeindruckend, &lt;Klasse&gt;, denn er soll etliche Leute getötet haben. Der Halbmond auf seiner Tatze ist zweifelsohne ein Zeichen, dass er von den Nachtelfen ausgebildet wurde, die in Ashenvale herumschleichen. Ursangus ist... war einer der mächtigsten Bären, die Ihr in dieser Gegend finden konntet. Solch eine Kreatur besiegt zu haben, ist ein Beweis Eurer Willenskraft und Eures Mutes.\n\nEure Vorfahren wären stolz auf Euch!", rewards = "Ihr bekommt:\n\n"},
[24] = {title = "Schattumbras Kopf", objective = "Bringt Schattumbras Kopf zu Senani Thunderheart im Splintertreeposten in Ashenvale.", description = "Der einstmals so flinke Schattumbra liegt jetzt regungslos vor Euch und der Sieg ist Euer. Der Kopf des erschlagenen Nachtsäblers ist eine passende Trophäe für diesen Kampf. Senani Thunderheart im Splintertreeposten wird eine solche Trophäe sehen wollen, um Euch den Erfolg in diesem Teil der Jagd in Ashenvale anzurechnen.", progress = "Seid mir erneut gegrüßt, <Name>! Seid Ihr gekommen, um mir einen Beweis Eurer Jagd vorzulegen?", completion = "Ein Sieg für &lt;Name&gt; in der Jagd von Ashenvale! Gut gemacht... der Kopf von Schattumbra ist eine passende Trophäe für solch einen beeindruckenden Kampf, keine Frage.\n\nSchattumbras Wildheit war im ganzen Außenposten hier bekannt. Jede Reise nach Westen, insbesondere wenn man zu Fuß versuchte den Zoramstrand zu erreichen, war ob des Tigers von Gefahr überschattet. Dank Euch hat diese Gefahr jetzt ein Ende.", rewards = "Ihr bekommt:\n\n"},
[25] = {title = "Stillstand am Steinkrallenpfad", objective = "Erledigt 12 beschmutzte Wasserelementare am Mystralsee östlich vom Steinkrallenpfad und südwestlich vom Splintertreeposten.\n\nErkundet den Pavillon am Mystralsee, der den nahen Außenposten der Allianz überblickt.\n\nKehrt zu Mastok Wrilehiss im Splintertreeposten in Ashenvale zurück.", description = "Wenn Ihr Euch nützlich machen wollt, warum unternehmt Ihr dann nicht etwas wegen der Situation am Steinkrallenpfad?\n\nDer Güterverkehr zwischen Ashenvale und dem Steinkrallengebirge steht still, weil der See zum Leben erwacht ist und alles angreift, was ihm zu nahe kommt... und das bedeutet, jeden auf dem Pfad. Noch weitaus nützlicher als einfach nur die Wasserelementare zu unterjochen, wäre es, wenn jemand den Pavillon auf dem Mystralsee auskundschaften würde... der, von dem aus man einen guten Blick auf den dortigen Außenposten der Allianz hat.\n\nNa, wollt Ihr Euch nützlich machen?", progress = nil, completion = "Ja, ich habe gehört, dass jemand den See auseinander genommen hat wie ein Staubteufel, der durch das Brachland tobt. So wie es klingt, können wir vielleicht außerdem einen Beobachtungsposten da draußen einrichten, um unsere Freunde von der Allianz im Auge zu behalten. Zumindest wenn wir kein Aufsehen erregen...\n\nEs scheint, als hättet Ihr Euch letzten Endes als ziemlich nützlich erwiesen. Die Transporte zwischen hier und dem Steinkrallengebirge sollten jetzt weniger Probleme haben. Nehmt dies - Ihr habt es Euch verdient.", rewards = "Ihr bekommt:\n\n"},
[26] = {title = "Eine wertvolle Lektion", objective = "Sprecht mit Dendrite Starblaze im Dorf Nighthaven in Moonglade.", description = "<Name>, ich habe Euren Fortschritt mit großem Genuss verfolgt. Ihr entwickelt Euch definitiv zu einem wertvollen Beschützer der Natur.\n\nEs ist an der Zeit für Euch, mehr über einen der diversen Tieraspekte zu lernen, in die wir uns dank Cenarius' Segen verwandeln können... einen, der Euch die Beherrschung des Wassers ermöglicht. Dazu müsst Ihr zum Dorf Nighthaven in Moonglade reisen und mit Dendrite Starblaze vom Zirkel des Cenarius sprechen. Er wird Euch weiter anleiten.", progress = nil, completion = "Seid gegrüßt, junger &lt;Klasse&gt;. Es ist an der Zeit für Euch, unsere Wassergestalt kennen zu lernen. Dabei handelt es sich um eine Gestalt, die es Euch ermöglicht, Euch frei und beliebig lange durchs Wasser zu bewegen. Ihr werdet diesen Aspekt als ein nützliches Werkzeug und einen Segen empfinden... aber man muss sich ihn verdienen, bevor man ihn meistern kann.\n\nIhr werdet Euch dafür zwei Prüfungen stellen. Die Erste wird Eure Fähigkeit prüfen, unter Druck im Wasser zu arbeiten. Die Zweite wird Eure Entschlossenheit prüfen, die Aspekte der Form als solche zu verstehen.\n\nMacht Euch bereit, denn die Zeit der Prüfung ist gekommen.", rewards = "Ihr bekommt:\n\n"},
[27] = {title = "Eine wertvolle Lektion", objective = "Sprecht mit Dendrite Starblaze im Dorf Nighthaven in Moonglade.", description = "<Name>, ich habe Euren Fortschritt mit großem Genuss verfolgt. Ihr entwickelt Euch definitiv zu einem wertvollen Beschützer der Natur.\n\nEs ist an der Zeit für Euch, mehr über einen der diversen Tieraspekte zu lernen, in die wir uns dank Cenarius' Segen verwandeln können... einen, der Euch die Beherrschung des Wassers ermöglicht. Dazu müsst Ihr zum Dorf Nighthaven in Moonglade reisen und mit Dendrite Starblaze vom Zirkel des Cenarius sprechen. Er wird Euch weiter anleiten.", progress = nil, completion = "Seid gegrüßt, junger &lt;Klasse&gt;. Es ist an der Zeit für Euch, unsere Wassergestalt kennen zu lernen. Dabei handelt es sich um eine Gestalt, die es Euch ermöglicht, Euch frei und beliebig lange durchs Wasser zu bewegen. Ihr werdet diesen Aspekt als ein nützliches Werkzeug und einen Segen empfinden... aber man muss sich ihn verdienen, bevor man ihn meistern kann.\n\nIhr werdet Euch dafür zwei Prüfungen stellen. Die Erste wird Eure Fähigkeit prüfen, unter Druck im Wasser zu arbeiten. Die Zweite wird Eure Entschlossenheit prüfen, die Aspekte der Form als solche zu verstehen.\n\nMacht Euch bereit, denn die Zeit der Prüfung ist gekommen.", rewards = "Ihr bekommt:\n\n"},
[28] = {title = "Prüfung des Sees", objective = "Sucht ein Schreinschmuckstück im Elune'ara See und bringt es zum Schrein von Remulos im Nordwesten von Moonglade. Wenn Ihr dort seid, benutzt das Schrein-Schmuckstück.\n\nIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen.", description = "Als Eure erste Prüfung müsst Ihr in den Tiefen des Elune'ara Sees nach einem Schreinschmuckstück suchen. Es zerfällt schnell, daher solltet Ihr Euch mit größter Eile zum Schrein von Remulos begeben. Benutzt das Schmuckstück am Schrein und sprecht dann dort mit Tajarri; sie ist eine der vertrauenswürdigsten Aufseherinnen von Moonglade.\n\nIhr habt nur eine gewisse Zeitspanne für diese Aufgabe zur Verfügung, und Ihr könntet in Konkurrenz zu anderen Druiden stehen, die ebenfalls nach Schmuckstücken suchen. Geistiges wie körperliches Geschick wird für Euren Erfolg unabdingbar sein.\n\nViel Glück, <Name>.", progress = "Um die Prüfung des Sees abzuschließen, müsst Ihr das Schreinschmuckstück im Umkreis des Schreines benutzen. Solange Ihr das nicht getan habt, bleibt Eure Prüfung unvollständig und Ihr riskiert einen Fehlschlag.", completion = "Na so was, es sieht so aus, als hätte erneut ein &lt;Klasse&gt; die Prüfung des Sees erfolgreich abgeschlossen! Gut gemacht... sehr gut.\n\nWie ich schon sagte ist mein Name Tajarri. Es ist meine Pflicht und mein Privileg, Moonglade und insbesondere diesem Schrein als Aufseherin zu dienen. Bewahrer Remulos leitet den Zirkel des Cenarius in seinem Bemühen an, das Gleichgewicht der Natur zu bewahren, und dieser Schrein dient als ständiges Zeichen der Anerkennung dessen. Indem Ihr das Schmuckstück hier benutzt habt, dient es als eine anerkennende Geste für die Wichtigkeit dieses Ortes im Zirkel.", rewards = "Ihr bekommt:\n\n"},
[29] = {title = "Prüfung des Sees", objective = "Sucht ein Schreinschmuckstück im Elune'ara See und bringt es zum Schrein von Remulos im Nordwesten von Moonglade. Wenn Ihr dort seid, benutzt das Schrein-Schmuckstück.\n\nIhr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen.", description = "Als Eure erste Prüfung müsst Ihr in den Tiefen des Elune'ara Sees nach einem Schreinschmuckstück suchen. Es zerfällt schnell, daher solltet Ihr Euch mit größter Eile zum Schrein von Remulos begeben. Benutzt das Schmuckstück am Schrein und sprecht dann dort mit Tajarri; sie ist eine der vertrauenswürdigsten Aufseherinnen von Moonglade.\n\nIhr habt nur eine gewisse Zeitspanne für diese Aufgabe zur Verfügung, und Ihr könntet in Konkurrenz zu anderen Druiden stehen, die ebenfalls nach Schmuckstücken suchen. Geistiges wie körperliches Geschick wird für Euren Erfolg unabdingbar sein.\n\nViel Glück, <Name>.", progress = "Um die Prüfung des Sees abzuschließen, müsst Ihr das Schreinschmuckstück im Umkreis des Schreines benutzen. Solange Ihr das nicht getan habt, bleibt Eure Prüfung unvollständig und Ihr riskiert einen Fehlschlag.", completion = "Na so was, es sieht so aus, als hätte erneut ein &lt;Klasse&gt; die Prüfung des Sees erfolgreich abgeschlossen! Gut gemacht... sehr gut.\n\nWie ich schon sagte ist mein Name Tajarri. Es ist meine Pflicht und mein Privileg, Moonglade und insbesondere diesem Schrein als Aufseherin zu dienen. Bewahrer Remulos leitet den Zirkel des Cenarius in seinem Bemühen an, das Gleichgewicht der Natur zu bewahren, und dieser Schrein dient als ständiges Zeichen der Anerkennung dessen. Indem Ihr das Schmuckstück hier benutzt habt, dient es als eine anerkennende Geste für die Wichtigkeit dieses Ortes im Zirkel.", rewards = "Ihr bekommt:\n\n"},
[30] = {title = "Prüfung des Seelöwen", objective = "Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserausdauer. Sprecht mit den Einwohnern von Moonglade, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.\n\nFormt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.\n\nBringt den zusammengefügten Anhänger zu Dendrite Starblaze nach Nighthaven in Moonglade.", description = "Für die zweite Prüfung benötigt Ihr die zwei Hälften, aus denen der Anhänger des Seelöwen besteht. Die eine Hälfte bezieht ihre Kraft aus der Beweglichkeit des Seelöwen-Aspektes beim Gleiten durchs Wasser; die andere Hälfte bezieht ihre Kraft aus der unglaublichen Ausdauer des Seelöwen-Aspektes. Druiden bedienen sich dieser beiden Eigenschaften gleichermaßen, um den Aspekt ihrer Wassergestalt zu verkörpern.\n\nSprecht mit den Bewohnern von Moonglade, um herauszufinden, wo sich die Teile befinden könnten, und bringt beide hierher, um sie miteinander zu vereinen. Bringt den Anhänger zu Dendrite Starblaze, wenn Ihr ihn geschaffen habt.", progress = "Habt Ihr Euren Anhänger geschaffen, auf dass ich ihn mir ansehen kann, <Name>? Falls Ihr Hilfe beim Aufspüren der Teile braucht, bittet am besten die örtliche Bevölkerung um Hinweise. Ihr werdet dabei nicht nur finden, was Ihr sucht, sondern habt außerdem noch einen guten Grund, dieses wunderbare und heilige Tal zu erforschen.", completion = "Ihr habt die Prüfung des Seelöwen erfolgreich beendet, &lt;Name&gt;... Glückwunsch.\n\nJede Teilaufgabe bei der Beschaffung des Anhängers zeigt, dass man sowohl Beweglichkeit als auch Ausdauer benötigt, um in Harmonie mit dem agieren zu können, was Ihr unter Wasser tun wollt. Keine der Eigenschaften kann ohne die andere existieren, und beide können nicht erreicht werden ohne Euren Willen, den Aspekt des Seelöwen in Euch aufzunehmen.\n\nMerkt Euch diese Lektionen gut und verlasst Euch auf sie, wenn Ihr Eure Wassergestalt erworben habt.", rewards = "Ihr bekommt:\n\n"},
[31] = {title = "Wassergestalt", objective = "Kehrt nach Thunder Bluff zurück und zeigt Turak Runetotem den Anhänger des Seelöwen.", description = "Ihr habt die notwendigen Lektionen gemeistert, die alle jungen Druiden lernen, bevor sie einen Wasseraspekt annehmen können. Kehrt jetzt zu Eurem Lehrer Turak Runetotem nach Thunder Bluff zurück. Zeigt ihm Euren Anhänger und beweist ihm damit, dass Ihr bereit seid zu lernen, was er Euch lehren kann. Er wird Eure Ausbildung abschließen und Euch ermöglichen, eins mit dem Wasser zu werden.\n\nAuf Wiedersehen. Wir werden uns wieder sprechen.", progress = "Eure Rückkehr nach Thunder Bluff kommt nicht überraschend, doch ich werde einen Beweis dafür benötigen, dass Ihr die Lektionen in Moonglade gelernt habt, bevor ich Euch Eure Wassergestalt lehre.\n\nHabt Ihr den Anhänger des Seelöwen?", completion = "Sehr beeindruckend, &lt;Name&gt;. Eure Vorfahren wären erfreut über Euren Fortschritt! Ihr seid bereit, Eure Wassergestalt zu erlernen, und ich habe das Vergnügen, sie Euch zu lehren.\n\nAußerdem übergebe ich Euch als Anerkennung Eurer Leistungen während der beiden Prüfungen diesen Gegenstand. Ich hoffe, Ihr werdet ihn als eine wertvolle Ergänzung Eurer Ausrüstung als Beschützer der Natur und Bewahrer des Gleichgewichts ansehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWassergestalt\n\nIhr bekommt:\n\nWassermann-Gürtel"},
[32] = {title = "Aufstieg der Silithid", objective = "Bringt den Bericht nach Orgrimmar zu Zilzibin Drumlore.", description = "Hier ist Euer Bericht. Ihr solltet damit zu jemandem gehen, der ausreichend Kenntnis von solchen Dingen hat.\n\nIch kenne da einen Troll-Gelehrten mit Namen Zilzibin Drumlore. Er hat viel Zeit mit dem Studium der Lebensformen verbracht, die in der Ökologie von Azeroth einzigartig sind, und er ist noch dazu Historiker! Wenn Euch jemand helfen soll herauszufinden, was genau diese Bedrohung ausmacht, und wie sie zu stoppen ist, gebt ihm diesen Bericht. Hilfe können wir gar nicht genug haben.\n\nZil lebt in einem Haus auf der zweiten Ebene der Gasse in Orgrimmar.", progress = "Es tut mir Leid, ich kenne Euch nicht... aber so wie es aussieht, habt Ihr zumindest schon von mir gehört. Nun, wie kann ich Euch helfen? Habt Ihr etwas für mich?", completion = "Dieser Bericht... Ich habe mich schon zuvor mit diesen Bestien beschäftigt. Fizzledowser hat gut daran getan, dies und Euch zu mir zu schicken.\n\nDiese Kreaturen werden die Tanariswüste schnell verzehren; sie stellen so ziemlich die größte Bedrohung dar, der wir uns je gegenübersehen werden. Macht Euch mit diesem Namen vertraut, &lt;Name&gt;: Silithid. Die hier erwähnten Insekten sind die Silithid und sie sind das Werkzeug einer der größten Bedrohungen, der sich die Horde und die Allianz gegenübersehen.\n\nWenn wir nur früher schon klug genug gewesen wären, das zu verstehen.", rewards = "Ihr bekommt:\n\n"},
[33] = {title = "Wölfe an der Grenze", objective = "Bringt Eagan Peltskinner, den Ihr vor der Abtei von Nordshire findet, 8 Stücke zähes Wolfsfleisch.", description = "Ich hasse diese grässlichen Waldwölfe! Aber Wolfsteaks esse ich für mein Leben gern. Bringt mir zähes Wolfsfleisch, dann gebe ich Euch etwas dafür, das Euch von Nutzen sein wird.\n\nzähes Wolfsfleisch bekommt Ihr, wenn Ihr die Waldwölfe und jungen Wölfe jagt, die in Nordhain durch das Land streifen.", progress = "He, <Name>, Ich kriege langsam Hunger. Habt Ihr das zähe Wolfsfleisch bekommen?", completion = "Ihr wart aber fleißig! Ich kann es kaum erwarten, dieses Wolfsfleisch aufs Feuer zu bringen.\n\nIch habe hier ein paar Sachen, die Euch vielleicht gefallen könnten - greift zu!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWeiche fellgefütterte SchuheWolfhaut-Armschienen\n\nIhr bekommt außerdem:\n\n"},
[34] = {title = "Ein ungebetener Gast", objective = "Martie Jainrose aus Seenhain möchte, dass Ihr Stopfwanst tötet. Bringt ihr den Hauer des Ebers zum Beweis.", description = "Mein Garten ist schon wieder zertrampelt und verwüstet worden. Und ich weiß genau, was für ein Tier das getan hat. Das war dieser elende Eber, der, den Marshal Marris seit einer Weile immer \"Stopfwanst\" nennt.\n\nJetzt kann ich die Narzissen erst nächsten Herbst wieder anpflanzen. Hin! Alle hin, und das nur wegen diesem einen gefährlichen Eber. Bereitet dieser Plage ein Ende! Zeigt mir seinen Hauer und ich werde Euch nur zu gern belohnen. Die meiste Zeit scheint er damit zu verbringen, in den Feldern südwestlich von Seenhain nach Futter zu suchen, doch gelegentlich verirrt er sich auch hierher und in meinen Garten.", progress = "Treibt Stopfwanst noch immer sein Unwesen, oder ist es Euch gelungen, Seenhain ein für alle Mal von dieser Plage zu befreien?", completion = "Endlich hat die Bedrohung ein Ende! Ich danke Euch, &lt;Name&gt;, Ihr habt mir einen großen Dienst erwiesen. Dieses Jahr wird mein Garten herrlich blühen!", rewards = "Ihr bekommt:\n\nScharlachroter Begonienstrauß"},
[35] = {title = "Weitere Sorgen", objective = "Marshal Dughan möchte, dass Ihr mit Wache Thomas sprecht.", description = "Falls Ihr befürchtet, dass die Gerüchte über das Auftauchen von Murlocs wahr sein könnten, dann tut das Folgende: Begebt Euch zur östlichen Elwynn-Brücke und sprecht mit Wache Thomas. Er ist seit einer Woche an der Brücke stationiert und wird deswegen wissen, wie es in der Gegend aussieht.\n\nBringt mir seinen Bericht.", progress = nil, completion = "Ja, es haben sich Murlocs in und an den Flüssen und Bächen des östlichen Elwynn niedergelassen. Wir wissen nicht, warum sie hergekommen sind, aber sie sind aggressiv und zumindest halbintelligent.", rewards = "Ihr bekommt:\n\n"},
[36] = {title = "Westfall-Eintopf", objective = "Verna Furlbrow möchte, dass Ihr ihr Rezept für Westfall-Eintopf bei Salma Saldean abliefert.", description = "Ich hätte nie gedacht, dass jemals der Tag kommen würde, an dem ich den Hof verlasse. Aber in den Feldern wimmelt es nur so von Dieben und es ist hier für uns viel zu gefährlich geworden. Sobald Bauer Furlbrow den Wagen repariert hat, machen wir uns auf den Weg. \n\nKönntet Ihr mir vielleicht einen Gefallen tun? Ich schreibe Euch schnell mein Rezept für Westfall-Eintopf auf. Seid so nett und bringt es Salma Saldean; sie wohnt auf dem Hof dort hinten. Ihr findet den Hof der Saldeans gleich hinter der Gabelung der Straße.", progress = "Ich werde die Verna Furlbrow sehr vermissen! Ich nehme nicht an, dass Ihr ihr auf dem Weg hierher begegnet seid?", completion = "Die Verna ist immer so ein liebes Mädchen gewesen! Wir werden sie hier in Westfall vermissen, aber ganz ehrlich und nur unter uns, sie ist ja eigentlich ein Stadtkind und deswegen wird sie sich in Stormwind pudelwohl fühlen. Aber genug getratscht! Jetzt können wir Westfall-Eintopf kochen!", rewards = "Ihr bekommt:\n\n"},
[37] = {title = "Suche nach den vermissten Wachen", objective = "Wache Thomas möchte, dass Ihr den Fluss in Richtung Norden nach Rolf und Malakai, den beiden vermissten Wachen, absucht.", description = "Vor ein paar Tagen haben wir zwei Wachen, Rolf und Malakai, losgeschickt, damit sie entlang des Flusses Nachforschungen anstellen, aber bisher sind sie noch nicht zurückgekehrt. Damit ich meinen Bericht fertig schreiben kann, muss ich wissen, was den beiden Männern zugestoßen ist.\n\nSucht den Fluss in Richtung Norden ab und seht zu, dass Ihr die Wachen findet... oder ihre Überreste...", progress = nil, completion = "Vom Leichnam selbst ist nicht mehr viel zu erkennen. Doch in der Nähe findet Ihr ein Medallion, in das die Worte \"Malakai Stone, Soldat\" eingeprägt sind.", rewards = "Ihr bekommt:\n\n"},
[38] = {title = "Westfall-Eintopf", objective = "Salma Saldean möchte 3 Stücke sehniges Geierfleisch, 3 Geiferzahnschnauzen, 3 Murlocaugen und 3 Okraschoten.", description = "Wollt Ihr mir dabei helfen, Westfall-Eintopf zu kochen? Dann bringt mir die folgenden Zutaten: \n\n 3 Stücke sehniges Geierfleisch\n 3 Geiferzahnschnauzen \n 3 Murlocaugen \n 3 Okraschoten", progress = "Dann bringt mir die folgenden Zutaten: \n\n 3 Stücke sehniges Geierfleisch\n 3 Geiferzahnschnauzen \n 3 Murlocaugen \n 3 Okraschoten", completion = "Das Okra wird die Brühe schön eindicken. Und jetzt geben wir nur noch das sehnige Geierfleisch, ein paar Murlocaugen und diese leckeren Geiferzahnschnauzen dazu. Und fertig! Ich möchte, dass Ihr für all Eure Hilfe den ersten Schwung Westfall-Eintopf bekommt, &lt;Name&gt;. Hier, nehmt!", rewards = "Ihr bekommt:\n\nWestfall-EintopfRezept: Westfall-EintopfSalmas TopfhandschuheScharfes Küchenmesser"},
[39] = {title = "Zustellung von Thomas' Bericht", objective = "Erstattet Marshal Dughan in Goldhain Bericht.", description = "Berichtet Marshal Dughan, dass Malakai und Rolf ums Leben gekommen sind, und teilt ihm auch mit, dass wir die Murlocs in Ost-Elwynn mit unserer derzeitigen Truppenstärke hier nicht unter Kontrolle halten können.\n\nIch weiß, dass wir nicht viele überzählige Männer haben, aber vielleicht findet Dughan ja doch jemanden.", progress = nil, completion = "Hmm... das sind beunruhigende Neuigkeiten. Unsere Reihen sind ohnehin schon ausgedünnt, und dass wir jetzt auch noch Rolf und Malakai verloren haben, macht die Lage noch schlimmer.\n\nWenn sich die Dinge nicht bald ändern, dann wird in ein paar Tagen sogar Goldhain umkämpft sein.", rewards = "Ihr bekommt:\n\n"},
[40] = {title = "Gefahr aus dem Wasser", objective = "Remy \"Zweifach\" möchte, dass Ihr in Goldhain mit Marshal Dughan sprecht.", description = "Eine neue Gefahr bedroht den Wald von Elwynn, <Name>! Murlocs kommen die Bäche und Flüsse im östlichen Elwynn hinaufgeschwommen, vertreiben die Fische und greifen einfache Leute an!\n\nIch habe Marshal Dughan bereits gewarnt, aber der macht sich größere Sorgen wegen der Gnolle und der Banditen. Er ist nicht überzeugt davon, dass die Murlocs eine Gefahr darstellen.\n\nBitte sprecht mit Dughan, <Name>, und bringt ihn dazu, dass er Verstärkung in den Osten schickt!", progress = nil, completion = "Ja, ich habe mit Remy darüber gesprochen. Er ist ein guter Händler und ich respektiere ihn, aber alle Berichte von Murlocs im Osten waren bisher bestenfalls bruchstückhaft.\n\nIch nehme Eure Sorgen zur Kenntnis, aber solange ich nicht einen zuverlässigen Bericht aus berufener militärischer Quelle erhalte, der bestätigt, dass die Murlocs tatsächlich eine Bedrohung darstellen, können wir es uns nicht leisten, weitere Soldaten nach Osten zu schicken.", rewards = "Ihr bekommt:\n\n"},
[45] = {title = "Rolfs Schicksal", objective = "Durchsucht das Murlocdorf nach Rolf - oder nach Anzeichen für seinen Tod.", description = "Als Ihr die Gegend weiter absucht, findet Ihr die Abdrücke von Füßen mit Schwimmhäuten, die entlang dem Ufer des Steinhügelsees nach Osten führen. In der Ferne könnt Ihr im Osten gerade noch so ein Murlocdorf ausmachen.\n\nVielleicht fand Rolfs Leben dort sein Ende...", progress = nil, completion = "Um den Hals trägt der Leichnam ein Medaillon aus Metall, auf dem die Worte \"Rolf Hartford, Soldat\" stehen.", rewards = "Ihr bekommt:\n\n"},
[46] = {title = "Kopfgeld auf die Murlocs", objective = "Bringt 8 zerrissene Murlocflossen zu Wache Thomas, den ihr an der östlichen Elwynn-Brücke findet.", description = "Die Armee von Stormwind hat ein Kopfgeld auf die Murloclauerer und Murlocfutterwühler ausgesetzt, die sich in Elwynn herumtreiben. Erlegt sie und bringt mir ihre zerrissenen Murlocflossen, dann wird die Armee von Stormwind Euch ansehnlich belohnen\n\nDie Murlocs haben am Steinhügelsee nördlich von hier ein Dorf errichtet und ein weiteres ihrer Dörfer befindet sich im Süden, wo der Fluss sich teilt.", progress = "Wie läuft die Jagd, <Name>?", completion = "Habt Ihr die Flossen? Ausgezeichnet! Marshal Dughan ist besorgt wegen der Murlocbedrohung in Ost-Elwynn und ich würde ihm gern berichten können, dass wir die Lage langsam unter Kontrolle bekommen.\n\nMit Euren Taten habt Ihr uns dabei geholfen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLanges BajonettRobuste MetallkeuleEingeschliffenes Schwert\n\nIhr bekommt außerdem:\n\n"},
[47] = {title = "Tauschhandel mit Goldstaub", objective = "Bringt 10 Einheiten Goldstaub nach Goldhain zu Remy \"Zweifach\". Goldstaub findet Ihr bei den Kobolden im Wald von Elwynn.", description = "Manchmal haben die Kobolde in dieser Gegend Goldstaub dabei. Das Zeug könnte ich wirklich gut gebrauchen. Bringt mir etwas davon und ich mache Euch den besten Preis in der Stadt... den besten Preis in der Stadt!\n\nDie Kobolde halten sich in der Tiefenschachtmine im Süden und im Bereich der Jaspismine im Nordosten auf.", progress = "Psst! Habt Ihr den Goldstaub für mich... für mich?", completion = "Danke für den Goldstaub, &lt;Name&gt;. Hier habt Ihr Euer Geld und hier habt Ihr noch eine kleine... Zugabe von Freunden von mir. Das könnte Euch vielleicht noch nützlich werden... nützlich werden.", rewards = "Ihr bekommt:\n\nTasche mit Murmeln"},
[48] = {title = "Goldbrauner Samt", objective = "Bringt Grimbooze Donnerbräu Wasser von der Heiligen Quelle.", description = "Weit im Süden, wo die Lianen sich ranken,\nLiegt versteckt ein Brunnen, in dem fast versanken\nDie wertvollen Wasser, so rein und so helle - \nBringt mir Wasser von der Heiligen Quelle.", progress = "Hicks und Hurra, Wollt Ihr's nochma'?\n\nWeit im Süden, wo die Lianen sich ranken,\nLiegt versteckt ein Brunnen, in dem sie fast versanken\nDie wertvollen Wasser, so rein und so helle - \nBringt mir Wasser von der Heiligen Quelle.", completion = "Hicks und Hurra!", rewards = "Ihr bekommt:\n\n"},
[49] = {title = "Goldbrauner Samt", objective = "Grimbooze Donnerbräu möchte einen Sack Gerste, einen Sack Roggen und einen Sack Korn haben.", description = "Lang schon vermiss ich die Lieb meines Lebens,\nGoldbraun und samtig, doch noch wart ich vergebens.\nBringt mir, dann vergeht jeder Zorn,\nJe einen Sack Gerste, Roggen und Korn.", progress = "Nochma'? Na klar!\n\nLang schon vermiss ich die Lieb meines Lebens,\nGoldbraun und samtig, doch noch wart ich vergebens.\nBringt mir, dann vergeht jeder Zorn,\nJe einen Sack Gerste, Roggen und Korn.", completion = "Hicks und Hurra!", rewards = "Ihr bekommt:\n\n"},
[50] = {title = "Goldbrauner Samt", objective = "Grimbooze Donnerbräu braucht Echtsilber.", description = "Die Maische anrühren, das ist mein Wille,\nDoch fehlt mir dann auch noch eine Destille.\nFür diese brauch ich ein starkes Metall - \nBringt mir Echtsilber, das ist gut in dem Fall!", progress = "Wollt Ihr's noch mal hören? Dann lasst Euch nicht stören!\n\nDie Maische anrühren, das ist mein Wille,\nDoch fehlt mir dann auch noch eine Destille\nFür diese brauch ich ein starkes Metall\nBringt mir Echtsilber, das ist gut in dem Fall!", completion = "Hicks und Hurra!", rewards = "Ihr bekommt:\n\n"},
[51] = {title = "Goldbrauner Samt", objective = "Bringt Grimbooze Donnerbräu den Ast eines Bergahorns.", description = "Noch ist er nicht fertig, doch schon frisch gebrannt,\nJetzt wird als Nächstes der Meiler bemannt,\nUm den Whisky zu filtern. Drum bringt mir den Ast\nEines Bergahorns - wenn Ihr könnt, ohne Rast!", progress = "Soll ich's noch mal sagen? Ihr müsst mich nur fragen!\n\nNoch ist er nicht fertig, doch schon fertig gebrannt.\nJetzt wird als Nächstes der Meiler bemannt, \nUm den Whisky zu filtern. Drum bringt mir den Ast\nEines Bergahorns - wenn Ihr könnt, ohne Rast!", completion = "Hicks und Hurra!", rewards = "Ihr bekommt:\n\n"},
[52] = {title = "Grenzschutz", objective = "Tötet 8 Streuner und 5 junge Waldbären und kehrt dann zu Wache Thomas an der östlichen Elwynn-Brücke zurück.", description = "Seid gegrüßt, <Name>. Je weiter wir uns von Goldhain entfernen, umso reizbarer sind die wilden Tiere. Und das Holzfällerlager des Osttals wird beinahe ständig von Wölfen und Bären angegriffen.\n\nWir könnten hier draußen wirklich Eure Hilfe gebrauchen.", progress = "Habt Ihr die Wölfe und Bären schon getötet, von denen ich sprach?", completion = "Vielen Dank für Eure Hilfe, &lt;Name&gt;. Im Wald muss es irgendetwas geben, das die Tiere so angriffslustig macht.\n\nWas auch immer es sein mag, ich hoffe, es bleibt dort!", rewards = "Ihr bekommt:\n\nGeringer Heiltrank"},
[53] = {title = "Goldbrauner Samt", objective = "Bringt Grimbooze Donnerbräu ein verkohltes Eichenbündel.", description = "Das Getränk, das ich braue, das reine und klare,\nWird goldbraun und samtig im Laufe der Jahre.\nDoch ehe er fertig, der Whisky, der weiche,\nBraucht's noch ein Fass aus verkohlter Eiche.", progress = "Soll ich's noch mal singen? Ihr müsst mich nicht zwingen!\n\nDas Getränk, das ich braue, das reine und klare,\nWird goldbraun und samtig im Laufe der Jahre.\nDoch ehe er fertig, der Whisky, der weiche,\nBraucht's noch ein Fass aus verkohlter Eiche.", completion = "Im Fasse gealtert, gefiltert durch Kohle,\nRinnt er durch die Kehle zu jedermanns Wohle.\nSo lasset uns trinken und prosten mit dem Gebräu.\nAuf Euch und auf mich, Grimbooze Donnerbräu!", rewards = "Ihr bekommt:\n\nDonnerbräus Stiefelflachmann"},
[54] = {title = "Meldung in Goldhain", objective = "Liefert Marshal McBrides Unterlagen bei Marshal Dughan in Goldhain ab.", description = "<Name>, Ihr habt bewiesen, dass Ihr als <Klasse> Euch um die Sicherheit von Nordhain sorgt. Nun erhaltet Ihr die Aufgabe, Euch auch dem Schutz des umliegenden Waldes von Elwynn zu widmen.\n\nWenn Ihr Euch dieser Aufgabe stellen wollt, dann nehmt diese Papiere, die bei Marshal Dughan in Goldhain abgeliefert werden müssen. Goldhain liegt an der südlichen Straße, hinter den Grenztoren.", progress = "Ihr bringt Nachricht von McBride? Im Vergleich zum Wald von Elwynn ist Nordhain das reinste Paradies. Wir wollen doch mal sehen, was Marshal McBride so zu berichten hat...\n\nGebt mir doch bitte seine Papiere.", completion = "Oha, hier steht, dass Ihr in den Rang des kommissarisch ernannten Deputys der Marshals von Stormwind erhoben worden seid. Herzlichen Glückwunsch.\n\nUnd viel Erfolg bei der Arbeit - Elwynn sicher zu machen ist kein Spaziergang, zumal der größte Teil der Armee sonstwo zugange ist und sonstwas für irgendwelche Adligen macht!\n\nEs ist schon schwer, in diesen dunklen Zeiten den Überblick über die Politik zu behalten...", rewards = "Ihr bekommt:\n\nPikenmannschild"},
[55] = {title = "Morbent Fel", objective = "Verwendet Morbents Bann gegen Morbent Fel, tötet Morbent Fel und bringt Morbents Bann anschließend zu Sven in dessen Lager zurück.", description = "Morbent Fel hält sich in seinem Unterschlupf verborgen, dem Haus, das hoch oben auf dem Hügel im Osten über dem Friedhof von Rabenflucht thront. Doch seine Zeit in diesem Land neigt sich dem Ende entgegen...\n\nSetzt Morbents Bann gegen ihn ein. Das wird seine schützenden Zauber machtlos machen.\n\nErschlagt ihn. Erschlagt ihn und errettet uns von seiner Verderbtheit. Werdet zum Instrument meiner Rache und damit <zum Helden/zur Heldin> des Dämmerwalds!", progress = "Ist Morbent Fel geschlagen?!", completion = "Morbent Fel ist besiegt. Die dunklen Reiter sind immer noch frei, aber das, worauf ich wider besseres Wissen gehofft hatte, ist zumindest zu einem kleinen Teil eingetreten.\n\nIhr habt das Unmögliche vollbracht und Eure Taten werden auf alle Zeit in der Überlieferung des Dämmerwalds weiterleben.\n\nGeht, &lt;Name&gt;. Und vielleicht bringt Euch das Schicksal eines Tages zurück zu mir...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nNachtwachen-PantalonsUmhang des WachhauptmannsGlanzmetallhelmkappe\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\nFackel der heiligen Flamme"},
[56] = {title = "Die Nachtwache", objective = "Kommandantin Althea Ebonlocke aus Dunkelhain möchte, dass Ihr 8 Skelettkrieger und 6 Skelettmagier tötet.", description = "Als Kommandantin der Nachtwache habe ich geschworen, die Bürger von Dunkelhain zu beschützen. Stormwind hat alle offiziell ernannten Wachen von ihren Posten hier abgezogen; damit sind wir uns selbst überlassen.\n\nWenn Ihr glaubt, der Aufgabe gewachsen zu sein, könnten wir Eure Hilfe wirklich gebrauchen! Helft der Nachtwache und wagt Euch in den Friedhof \"Stille Gärten\", der ein Stückchen südlich von Dunkelhain liegt. Tötet dort 8 Skelettkieger und 6 Skelettmagier. Der Bedrohung durch die Untoten muss ein Ende gemacht werden!", progress = "Wie ich sehe, seid Ihr zurück, <Name>. Wenn Ihr Euch für die Nachtwache als nützlich erweisen wollt, dann kehrt zu mir zurück, sobald Ihr 8 Skelettkrieger und 6 Skelettmagier getötet habt.", completion = "Ausgezeichnet, &lt;Name&gt;. Für Eure Dienste an ganz Dunkelhain sollt Ihr gut belohnt werden.", rewards = "Ihr bekommt:\n\n"},
[57] = {title = "Die Nachtwache", objective = "Kommandantin Althea Ebonlocke aus Dunkelhain möchte, dass Ihr 15 Skelettsatanskreaturen und 15 Skelettschrecken tötet.", description = "Ich habe berichtet bekommen, dass im Wald eine wahre Untotenplage ausgebrochen ist, <Name>. Wenn Ihr Euch der Aufgabe gewachsen fühlt, dann macht Euch auf den Weg zum Friedhof von Rabenflucht und erschlagt 15 dieser abscheulichen Skelettsatanskreaturen und 15 Skelettschrecken. Außerdem sollen im Friedhof \"Stille Gärten\", der sich ein Stückchen südlich von Dunkelhain befindet, Skelette gesehen worden sein. Die Untoten müssen aus dem Dämmerwald vertrieben werden!", progress = nil, completion = "Die Bewohner von Dunkelhain sind Euch zu Dank verpflichtet, &lt;Name&gt;. Ihr habt bewiesen, dass Ihr der Nachtwache ein wertvoller Verbündeter seid.", rewards = "Ihr bekommt:\n\n"},
[58] = {title = "Die Nachtwache", objective = "Kommandantin Althea Ebonlocke aus Dunkelhain möchte, dass Ihr im östlichen Mausoleum von Rabenflucht 20 Seuchenverbreiter tötet.", description = "Die Lage in Rabenflucht ist noch immer sehr bedenklich. Die Sicherheit von Dunkelhain liegt in Euren Händen, <Name>. Ich habe einfach nicht genug Behüter, um die Sicherheit in der Stadt zu gewährleisten. Deswegen müsst Ihr Euch erneut nach Rabenflucht aufmachen und das östliche Mausoleum von den Seuchenverbreitern säubern, die sich dort breit gemacht haben. Tötet 20 von ihnen!", progress = nil, completion = "Im Namen der Bewohner von Dunkelhain und als Anführerin der Nachtwache danke ich Euch, &lt;Name&gt;, für Euren Mut und Eure Hingabe. Möge das Licht über all Euren Wegen leuchten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchultergürtel der NachtwacheKöcher der NachtwacheRupfensack der Nachtwache\n\nIhr bekommt außerdem:\n\n"},
[59] = {title = "Rüstung aus Tuch und aus Leder", objective = "Gebt Sara Timberlain den Rüstungsgutschein der Armee von Stormwind.", description = "Als Dank für Eure Gewitztheit und Euren Mut gebe ich Euch hier einen Gutschein, den Ihr gegen ein Rüstungsteil eintauschen könnt. Bringt den Gutschein ins Holzfällerlager des Osttals zu Sara Timberlain. Wenn Ihr ihr den Gutschein gebt, dann stellt sie die Rüstung für Euch her. Und wenn Ihr sie habt, tragt sie zur Verteidigung von Elwynn, <Name>.\n\nIhr findet das Holzfällerlager des Osttals im Osten jenseits von Wache Thomas' Posten.", progress = "Ich bin von der Armee von Stormwind beauftragt, ihre Soldaten mit Rüstung aus Tuch und aus Leder auszustatten.\n\nWenn Ihr einen Gutschein für mich habt, dann stelle ich gern etwas für Euch her.", completion = "Ja, einen solchen Gutschein meinte ich. Danke! Bitte sucht Euch das Stück aus, das Ihr möchtet.\n\nIch wünsche Euch viel Glück auf Eurem Weg als &lt;Klasse&gt;. Und möge diese Rüstung Euch gute Dienste leisten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGut vernähte RobeGeflickte Hose\n\nIhr bekommt außerdem:\n\n"},
[60] = {title = "Koboldkerzen", objective = "Bringt 8 große Kerzen nach Goldhain zu William Pestle.", description = "Guten Tag, <werter Herr/werte Dame>! Hättet Ihr einen Moment Zeit für mich?\n\nMein Bruder und ich führen in Stormwind eine Apotheke und ich bin hier, weil ich große Kerzen suche, ihres Wachses wegen. Könnt Ihr mir vielleicht helfen?\n\nGroße Kerzen könnt Ihr von Kobolden bekommen - und ich habe Gerüchte gehört, dass Kobolde sich in den Minen von Elwynn eingenistet haben: in der Tiefenschachtmine im Süden und in der Jaspismine im Osten. Ich schlage vor, dass Ihr Euch an einem dieser Orte auf die Suche nach Kerzen begebt.", progress = "Habt Ihr schon die Kerzen gesammelt?", completion = "Ihr habt wohl eifrig Kobolde gejagt, hmm? Danke für die Kerzen, &lt;Name&gt;. Hier habt Ihr Eure Belohnung.", rewards = "Ihr bekommt:\n\nGlimmender Wachsstecken"},
[61] = {title = "Lieferung nach Stormwind", objective = "Bringt Williams Lieferung in den Handelsdistrikt von Stormwind zu Morgan Pestle.", description = "In Stormwind wartet mein Bruder Morgan auf die Lieferung der Kerzen. Ich habe selbst nicht die Zeit, um mich auf die Reise zu begeben, aber wenn Ihr ihm die Lieferung überbringen wollt, so wird er Euch gut bezahlen.\n\nIch habe die Kerzen schon fertig verpackt. Ihr findet Morgan in unserem Geschäft im Handelsdistrikt von Stormwind. Es heißt Pestles Apotheke.", progress = "Ah, eine Lieferung von meinem Bruder? Ausgezeichnet! Heute ist mir das Glück wirklich gewogen!", completion = "Hier habt Ihr Eure Bezahlung. Und wenn Ihr schon einmal hier seid, schaut Euch ruhig um! Ich bin sicher, dass wir den einen oder anderen Trank oder sonst irgendetwas haben, dass Euch von Nutzen wäre.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nExplosive RaketeOil of OlafElixier der Löwenstärke\n\nIhr bekommt außerdem:\n\n"},
[62] = {title = "Die Tiefenschachtmine", objective = "Erforscht die Tiefenschachtmine und kehrt dann nach Goldhain zu Marshal Dughan zurück.", description = "Die Mine in Nordhain ist nicht die einzige, mit der es Probleme gibt. Berichten zufolge ist auch die Tiefenschachtmine im Wald von Elwynn zu einem Tummelplatz für Kobolde geworden.\n\nErforscht die Mine, bestätigt diese Berichte und kehrt dann zu mir zurück. Die Mine liegt fast genau südlich von Goldhain, zwischen den Höfen der Stonefields und der Maclures.", progress = "Was gibt es zu berichten, <Name>? Seid Ihr in der Tiefenschachtmine gewesen?", completion = "Das sind allerdings schlechte Nachrichten. Was kommt als Nächstes, Drachen?!? Wir werden wohl unsere Patrouillen rund um die Mine verstärken müssen. Habt Dank für Eure Bemühungen, &lt;Name&gt;. Und wartet einen Moment... Ich habe vielleicht noch eine andere Aufgabe für Euch.", rewards = "Ihr bekommt:\n\n"},
[63] = {title = "Ruf des Wassers", objective = "Besiegt die verderbte Wassermanifestation und legt die Armschienen der verderbten Manifestation und die verbleibenden Tropfen reinsten Wassers im Silberwald auf die Kohlenpfanne von Everfount.", description = "An der Küste des Silberwalds befindet sich westlich des Grabmals ein Schrein, der von der Seuche besudelt ist. Die Geister dort sprechen nicht länger zu unserem Volk und es ist jetzt an Euch, die Manifestation dort zu besiegen und den Teich zu säubern.\n\nNehmt die Armschienen des Elementars und gebt sie zusammen mit den verbleibenden Tropfen von Brines Trank in die Kohlenpfanne. Das sollte ausreichen, um einen reinen Geist zu beschwören, mit dem Ihr kommunizieren könnt.\n\nBringt mir einen Beweis dafür, dass Ihr die Tat vollbracht habt, dann belohne ich Euch mit Eurem Totem.", progress = "Die Kohlenpfanne wirft immer noch das Licht der Umgebung zurück und die Flammen flackern leise, als Ihr näher herantretet.\n\nDie in diesen Bergen vorherrschende Verderbnis scheint sich hier noch nicht ausgebreitet zu haben und abgesehen von den fehlenden Komponenten scheint die Kohlenpfanne bereit dafür zu sein, dass jemand das Ritual zur Beschwörung einer gesäuberten Wassermanifestation durchführt.", completion = "Ihr legt die Armschienen des Elementars auf die Kohlenpfanne, dann gießt Ihr die verbleibenden Tropfen von Brines Trank in die Flammen. Die Flüssigkeit knistert, als sie mit den Flammen in Berührung kommt, und Ihr beginnt, die einfachen Worte zu rezitieren, die Islen Euch gelehrt hat...", rewards = "Ihr bekommt:\n\n"},
[64] = {title = "Das vergessene Erbstück", objective = "Bauer Furlbrow möchte, dass Ihr seine Taschenuhr holt. Sie befindet sich im Kleiderschrank des Bauernhauses auf der Kürbisfarm im Westen.", description = "Es war fürchterlich! Verna hat mich aufgeweckt, als sie draußen auf dem Feld so einen Radau gehört hat. Das ganze Feld war voller Rowdys! Wir sind in solcher Eile aufgebrochen und da hab ich vergessen, meine Taschenuhr einzupacken. Die Uhr hat mir Vernas Vater an unserem Hochzeitstag geschenkt und es wird mir fast schlecht, wenn ich dran denke, dass diese Diebe sie jetzt haben. Ich hab die Taschenuhr im Kleiderschrank in unserem Haus liegen lassen. Haltet nach dem Kürbisfeld im Westen Ausschau, dann kommt Ihr zu unserem Hof - Ihr könnt ihn gar nicht verfehlen. Wenn Ihr mir meine Uhr wiederbringen würdet, wäre ich Euch sehr dankbar.", progress = "Ich nehm nicht an, dass Ihr meine Uhr gekriegt habt, oder?", completion = "Meine Uhr! Oh, danke, danke vielmals, werter Herr! \n\nWir sind nur arme Bauern und wir haben unser Land verloren, aber nehmt doch bitte dies als Zeichen unseres Dankes.", rewards = "Ihr bekommt:\n\nFrisch gebackenes BrotEiskalte Milch"},
[65] = {title = "Die Bruderschaft der Defias", objective = "Gryan Stoutmantle möchte, dass Ihr in Seenhain mit Wiley sprecht.", description = "Die Bruderschaft der Defias nennt sich die Bande von Schuften, von der die braven Leute von Westfall aus dem Land vertrieben werden. Ihr müsst für mich diese Bande bespitzeln. Wir müssen erfahren, wer der Kopf der Gruppe ist und wo sie ihr Versteck hat. In Seenhain findet Ihr im Gasthaus einen Schurken namens Wiley, der mir noch einen Gefallen schuldet.\n\nBegebt Euch nach Seenhain im Rotkammgebirge, östlich von Elwynn, und findet heraus, was Ihr könnt.", progress = nil, completion = "So, Stoutmantle hat Euch geschickt, hm? Na ja, dem schulde ich noch was.", rewards = "Ihr bekommt:\n\n"},
[66] = {title = "Die Legende von Stalvan", objective = "Sucht Amtmann Daltry im Rathaus von Dunkelhain auf.", description = "Letzte Nacht verspürte ich in meinem Geist eine schreckliche Erschütterung. Ich wusste, dass sich meine Enkelin Alyssa in großer Gefahr befand. Ich befragte die Karten und aus ihnen starrte mich die Fratze des Todes höhnisch an.\n\nIch begab mich auf eine lange Reise durch eine dunkle Trance und schließlich gelang es mir, einen Hinweis auf dieses schreckliche Geheimnis zu erhaschen. Ein Name erschloss sich mir, der Name Stalvan.\n\nSucht den Amtmann im Rathaus auf und schaut, ob Ihr nicht mehr über diese Person herausfinden könnt. Ich fürchte um unser aller Leben.", progress = nil, completion = "Madame Eva hat Euch also geschickt...", rewards = "Ihr bekommt:\n\n"},
[67] = {title = "Die Legende von Stalvan", objective = "Begebt Euch zur Schule in Moonbrook und bringt Amtmann Daltry alle neuen Informationen über Stalvan Mistmantle.", description = "Stalvan, hm? Lasst mich im Stadtverzeichnis nachsehen.\n\nStalvan... Stalvan... mal sehen. Ah, hier ist es! Ich habe hier einen Eintrag über einen gewissen Stalvan Mistmantle. Die letzte bekannte Adresse ist die Schule in Moonbrook. Liebe Güte, das nenne ich veraltet!\n\nWürdet Ihr mir einen Gefallen tun? Falls Ihr zufällig nach Moonbrook kommt, dann lasst es mich wissen, wenn Ihr an neue Informationen über diese Person geraten solltet. Ich habe meine Unterlagen gern auf dem neuesten Stand.", progress = nil, completion = "Quietschend öffnet sich die alte Schließkiste...", rewards = "Ihr bekommt:\n\n"},
[68] = {title = "Die Legende von Stalvan", objective = "Bringt Amtmann Daltry den verstaubten, nie abgeschickten Brief.", description = "In der alten Schließkiste findet Ihr einen verstaubten, nie abgeschickten Brief.", progress = "Ah, ich erinnere mich an Euch. Ihr hattet Euch doch nach diesem Stalvan erkundigt. Habt Ihr gefunden, wonach Ihr gesucht hattet?", completion = "Interessant. Also hat sich der Bursche doch einige Zeit lang in Moonbrook aufgehalten. Es ist etwas seltsam, dass der Brief nie zugestellt wurde. Nun, wie dem auch sei, ich werde das Verzeichnis aktualisieren.", rewards = "Ihr bekommt:\n\n"},
[69] = {title = "Die Legende von Stalvan", objective = "Begebt Euch zum Gasthaus Zur Höhle des Löwen und fragt dort nach, ob jemand schon einmal den Namen Stalvan gehört hat.", description = "Ach du liebes bisschen! Das ist mir beim ersten Mal ja glatt entgangen! Hier im Verzeichnis steht beim Eintrag für diesen Stalvan direkt unter der ersten Adresse noch eine weitere, die zum Teil durchgestrichen ist. Es scheint, als wäre er zum Gasthaus Zur Höhle des Löwen drüben in Goldhain unterwegs gewesen. Vielleicht solltet Ihr dort nachfragen, <Name>.", progress = nil, completion = "Stalvan? Kommt mir irgendwie bekannt vor...", rewards = "Ihr bekommt:\n\n"},
[70] = {title = "Die Legende von Stalvan", objective = "Holt Stalvans niemals zugestellten Brief aus der Truhe und liefert ihn im Kanaldistrikt von Stormwind ab.", description = "Den Namen Stalvan hab ich schon mal gehört... Ach, jetzt fällt's mir wieder ein.\n\nVor vielen Jahren betrat an einem stürmischen Abend ein Bote dieses Haus, der Unterkunft für die Nacht suchte. Es war noch nicht ganz Mitternacht, da kam der Mann schreiend die Treppe heruntergerannt. Er war bleich wie der Tod vor Angst. Nur mit seinem Nachtgewand bekleidet verschwand er im Regen.\n\nIn der Eile vergaß er seine Briefe in der Truhe oben und kam nie zurück, um sie abzuholen. Es ist ein Brief dabei von diesem Stalvan, den Ihr erwähntet, adressiert an den Kanaldistrikt in Stormwind. Ihr dürft ihn gern haben.", progress = "Was habt'n Ihr da, hm? Lasst mich das mal sehen...", completion = "Ihr habt vielleicht Nerven, dass Ihr das hierher bringt.", rewards = "Ihr bekommt:\n\n"},
[71] = {title = "Meldung an Thomas", objective = "Bringt die Medaillons von Rolf und Malakai zu Wache Thomas an die östliche Elwynn-Brücke.", description = "Nun habt Ihr beide Medaillons. Bringt sie an die Brücke zu Wache Thomas, damit er erfährt, welches Schicksal seine beiden Kameraden erlitten haben.", progress = "Hallo, <Name>. Habt Ihr herausgefunden, was aus Rolf und Malakai geworden ist?", completion = "Damit bestätigt Ihr meine Befürchtungen, &lt;Name&gt;. Die Murlocs sind eine Bedrohung, die wir nicht länger ignorieren können.", rewards = "Ihr bekommt:\n\n"},
[72] = {title = "Die Legende von Stalvan", objective = "Durchsucht die verpackten Besitztümer nach Hinweisen.", description = "Mein Vater war der Verwalter des Besitzes, lange bevor ich es wurde. Nach dem Massaker war er derjenige, der das Blut aufwischen und aufräumen musste. Aber das tut nichts zur Sache.\n\nDie letzten Gelder aus dem Flintridge-Fonds sind versiegt und jetzt müssen die letzten Stücke aus dem Familienbesitz versteigert werden. Daran sind nur diese Steuereintreiber schuld. Aber wenn Ihr wirklich dringend mehr erfahren wollt, dann dürft Ihr diesen Kram hier gern durchsehen. Wer weiß, was Ihr findet.", progress = nil, completion = "Langsam schiebt Ihr den Deckel von der Kiste...", rewards = "Ihr bekommt:\n\n"},
[74] = {title = "Die Legende von Stalvan", objective = "Die zerrissene Tagebuchseite, die Ihr gefunden habt, gibt Euch den nächsten Hinweis.", description = "In der Kiste findet Ihr verschiedene Dinge: muffige Erbstücke, ein Familienportrait, einige Jagdtrophäen und ein paar alte Bücher. Fast schon am Boden der Kiste findet Ihr unter einer Keramikvase eine zerrissene Tagebuchseite.", progress = "Was habt Ihr denn da? Ich kann es nicht sehen. Ich habe sehr schwache Augen. Gebt es mir bitte in die Hand.", completion = "Ich kann kaum lesen, was da steht, aber die Handschrift erinnert mich an etwas, das ich mal gesehen habe, bevor meine Sehkraft so nachgelassen hat.", rewards = "Ihr bekommt:\n\n"},
[75] = {title = "Die Legende von Stalvan", objective = "Marshal Haggard möchte, dass Ihr in der Kiste oben nach der verblassten Tagebuchseite sucht.", description = "Als ich hier eingezogen bin, stand oben schon eine Truhe mit Pergamenten darin. Kurz nach meinem Einzug habe ich sie mir einmal angesehen, aber bald darauf konnte ich nur noch verschwommen sehen und da hab ich's dann gelassen. \n\nTut einem alten, halb blinden Mann einen Gefallen und seht Euch selbst mal in der Kiste oben um, ob Ihr vielleicht etwas findet, das Euch bei Eurer Suche nach diesem Stalvan weiterhelfen kann. Ich bin mir ziemlich sicher, dass da eine verblasste Tagebuchseite dabei ist, die Euch interessieren müsste. Bringt sie mir und ich werde sehen, was ich tun kann, um Euch zu helfen.", progress = "Habt Ihr die Seite gefunden, von der ich sprach, <Name>?", completion = "Da ist sie ja!", rewards = "Ihr bekommt:\n\n"},
[76] = {title = "Die Jaspismine", objective = "Erforscht die Jaspismine und kehrt dann nach Goldhain zu Marshal Dughan zurück, um ihm Bericht zu erstatten.", description = "Dank Euch wissen wir jetzt, dass Kobolde sich in der Tiefenschachtmine eingenistet haben. Jetzt brauchen wir noch einen Späher, der die weiter entfernte Jaspismine untersucht.\n\nErforscht die Jaspismine und bestätigt mir, ob sich dort tatsächlich Kobolde aufhalten. Die Mine erreicht Ihr, indem Ihr der Straße nach Osten folgt, bis Ihr zum Turm von Azora kommt. Wenn Ihr Euch am Turm nach Norden wendet, dann findet Ihr die Mine im Vorgebirge.", progress = "Seid gegrüßt, <Name>. Was habt Ihr zu berichten? Habt Ihr die Jaspismine ausgekundschaftet?", completion = "Kobolde in der Jaspismine, sagt Ihr? Verflucht noch eins! Die Lage wird von Minute zu Minute schlimmer!\n\nVielen Dank für Euren Bericht, &lt;Name&gt;. Aber ich wünschte mir, Ihr hättet bessere Nachrichten gebracht.", rewards = "Ihr bekommt:\n\n"},
[77] = {title = "Eine schwierige Situation", objective = "Holt 10 Flaschen Hinterland-Honigwelle aus den Kisten, die sich rund um den verlassenen Stützpunkt der Horde in Skulk Rock befinden.", description = "Ich besitze Originalverpackungsmaterial für die Welle, die Dran Droffers will. Ich werde Euch dabei helfen, die Welle für Maltons ungehobelten Vater zu verpacken... für einen Unkostenbeitrag in Höhe zweier weiterer Flaschen besagter Welle. Sie befinden sich in Kisten, die Ihr in dem verlassenen Stützpunkt der Horde in der Nähe von Skulk Rock findet.\n\nDas heißt, dass es eine anstrengende Aufgabe wird. Ihr werdet bei den Ruinen stinkende Brühschleimer und Brühschlammer vorfinden; angeblich werden sie von einer Art Oberbrühschlammer geführt. Beschafft trotzdem die Welle und kehrt hierher zu mir zurück, um sie zu verpacken.", progress = "Ich nehme an, Eure Ankunft in unserem Lager dient der Lieferung der Wellenflaschen, die wichtiger Bestandteil der anstehenden Aufgabe sind, nicht wahr?", completion = "Das habt Ihr hervorragend gemacht, &lt;Name&gt;! Ich bin froh, dass Ihr genug Voraussicht gezeigt und das Bouquet der Welle nicht verletzt habt. Es gibt nichts Schlimmeres, als wenn das Bouquet der Welle unnötig erschüttert wird.\n\nEs dauert einen Moment, die Magie um diese wertvolle Fracht zu wirken. Eigentlich ist ja gar keine Magie im Spiel; ich habe einfach nur einige leere Verpackungen für Hinterland-Honigwelle. Unser kleiner Trick wird diese Flaschen in einen alkoholischen Schatz von hohem Alter verwandeln.\n\nNun denn - auf dass es großartiger Schnaps werde!", rewards = "Ihr bekommt:\n\n"},
[78] = {title = "Die Legende von Stalvan", objective = "Bringt die verblasste Tagebuchseite zu Schankwart Smitts.", description = "Ich kenne jemanden, der Euch vielleicht helfen könnte. Damals, als ich noch die Wachen von Stormwind kommandierte, haben wir immer in der Taverne Zum roten Raben in Dunkelhain gesessen und etwas getrunken. Smitts, der Gastwirt dort, kannte sich mit den örtlichen Lehren ziemlich gut aus. Zeigt ihm diese Seite, mal sehen, was er dazu zu sagen hat.", progress = "Marshal Haggard hat Euch geschickt? Warum habt Ihr das nicht gleich gesagt? \n\nAch ja, der gute alte Haggard. Der arme Kerl wird über kurz oder lang stockblind werden. Aber egal, zeigt mir mal, was Ihr da habt.", completion = "Beim Licht! Aber sicher erkenne ich die Handschrift.", rewards = "Ihr bekommt:\n\n"},
[79] = {title = "Die Legende von Stalvan", objective = "Bringt Kommandant Ebonlocke die schlammverschmierte Seite.", description = "Ich habe die Geschichten um diesen Stalvan jahrelang verfolgt. Als vor ein paar Jahren diese Adligen, die hier zu Besuch waren, ermordet wurden, hab ich Haggard bei seinen Nachforschungen begleitet. Ich habe damals diese schlammverschmierten Seiten gefunden, aber es ist uns nie gelungen, die Handschrift mit diesem Verrückten in den Wäldern in Verbindung zu bringen. Eure Spur der Beweise zeigt aber, dass er schuldig ist. Bringt dies sofort zu Kommandant Ebonlocke und sagt ihr, was Ihr entdeckt habt!", progress = "Nun, <Klasse>, ich hoffe, das, was Ihr mir da bringt, taugt auch etwas. Zeigt es mir und erzählt mir, was es damit auf sich hat. Aber beeilt Euch ein bisschen, beim Licht! Denn die Verteidigung von Dunkelhain ist mein wichtigstes Anliegen; ich habe einfach nicht die Zeit, mich bei meinen Ermittlungen in Sackgassen zu stürzen!", completion = "Ihr habt Euch ja richtiggehend als Detektiv betätigt, und das als &lt;Klasse&gt;. Respekt!", rewards = "Ihr bekommt:\n\nEine blutbefleckte Tagebuchseite"},
[80] = {title = "Die Legende von Stalvan", objective = "Zeigt Amtmann Daltry die blutbefleckte Tagebuchseite.", description = "Ich beobachte diesen Widerling Stalvan jetzt schon eine ganze Weile. Aber wenn diese Seite tatsächlich von seiner Hand geschrieben wurde, dann beweist das seine Schuld ohne den letzten Zweifel.\n\nSo lange, wie Amtmann Daltry das Stadtverzeichnis jetzt schon verwaltet, ist er ein wahrer Experte darin geworden, Handschriften zu identifizieren. Zeigt ihm diese Seite und stellt fest, ob die Schrift dieselbe ist wie diejenige der Unterschrift im Verzeichnis.", progress = "Ihr seid ja schon wieder da, <Name>! Was gibt es diesmal?", completion = "Aber ja! Die Handschrift auf dieser Seite ist tatsächlich dieselbe wie die der Unterschriften im Verzeichnis.", rewards = "Ihr bekommt:\n\n"},
[81] = {title = "Wellenlieferung", objective = "Liefert das Fass nach Orgrimmar an Dran Droffers.", description = "Ich habe zusätzliche Vorsichtsmaßnahmen getroffen und nicht nur Drans verpackte Welle in dem Fass sicher untergebracht, sondern auch die zusätzlichen Wellenflaschen, die er klaut. Auch wenn ich nicht viel von Dran halte, so gibt es doch nichts Schlimmeres als ein durchgeschütteltes Wellenbouquet. Bitte, bitte, keine Ursache.\n\nBringt jetzt Euer Fass zu Dran Droffers in seinem Kramladen in Orgrimmar. Entbietet meine besten Grüße bitte auch Malton und lasst ihn wissen, dass uns sein Besuch eine große Ehre wäre, falls es ihn jemals nach einem feinen Getränk und noch feineren Trinkkumpanen gelüstet.", progress = "Wenn Ihr nicht hier seid, um etwas zu kaufen, und auch nicht, um etwas abzuliefern, dann verschwendet Ihr meine Zeit! Es wäre für Euch besser, Ihr hättet diese Welle!", completion = "Tja, dann schauen wir mal, was in diesem Fass ist!\n\nJa, ja, sieht aus als wäre alles da. Hier ist Euer Unkostenbeitrag für das Paket, Ihr habt gute Arbeit geleistet. Ich werde das Fünffache der Unkosten herausholen, wenn ich das Zeug an die Taverne verkaufe! Har, har!\n\nDiese zusätzlichen Flaschen Hinterland-Honigwelle werde ich für eine besondere Gelegenheit aufbewahren. Ich werde am besten etwas davon mit Champagner vermischt trinken. Ich nenne das... Champelle.", rewards = "Ihr bekommt:\n\n"},
[82] = {title = "Erkundung des Giftigen Unterschlupfes", objective = "Bringt fünf Centipaarinsektenteile vom Giftigen Unterschlupf nach Gadgetzan zum Alchimisten Pestlezugg.", description = "Tja, diese Berichte über die Käfer... wir wissen, dass sie die Teiche trocken legen, die sich dort befanden, wo sich der Giftige Unterschlupf befindet. Was wir NICHT wissen, ist, na ja, alles andere.\n\nWir müssen als Erstes herausfinden, wer unser Feind ist! Begebt Euch bitte in den Giftigen Unterschlupf und besorgt ein paar Stücke dieser Tierwesen. Holt fünf der dortigen Centipaar und bringt sie dem Alchimisten Pestlezugg zur Untersuchung. Wenn er sich damit beschäftigt, werden wir schon herausfinden, worum es sich handelt!", progress = "Ihr seid Unterfeldmesser <Name>, nicht wahr? Macht schnell, denn wir befinden uns hier in einer schrecklichen Lage! Habt Ihr die Insektenteile, wie Fizzledowser gesagt hat?!", completion = "Gute Arbeit... ich werde jetzt mit der Analyse dieser Dinger beginnen! Eines kann ich Euch aber direkt sagen... es handelt sich hier um keine mir bekannte Insektenform. Es scheint fast so, als würden diese Käfer von einer fremden Macht kontrolliert oder so was.\n\nIhr müsst auf der Stelle mit Fizzledowser sprechen; anscheinend gibt es einen Notfall, bei dem er Eure Hilfe benötigt. Ich bin mir nicht sicher, aber ich glaube, es geht um weitere Käfer in der Tanariswüste!", rewards = "Ihr bekommt:\n\n"},
[83] = {title = "Rote Leinenwaren", objective = "Bringt 6 rote Leinenkopftücher ins Holzfällerlager des Osttals zu Sara Timberlain.", description = "Die Mitglieder der Defias in Nordhain tragen Masken aus Sackleinen, die Masken der Defias in Elwynn dagegen sind aus gutem Leinen, aus dem ich Qualitätsleinenwaren herstellen kann.\n\nBringt mir rote Leinenkopftücher, dann stelle ich daraus etwas für Euch her.\n\nDie Mitglieder der Defias haben Lager, die sich über ganz Elwynn verteilen.", progress = "Ich habe fast kein Leinen mehr, <Name>. Bringt Ihr mir welches?", completion = "Ah ja, das sind schöne Kopftücher, obwohl der Stoff ein wenig rau ist...\n\nHier, bitte schön!", rewards = "Ihr bekommt:\n\nRotes LeinenhemdRote Leinenschärpe"},
[84] = {title = "Zurück zu Billy", objective = "Bringt die Schweinebauchpastete zu Billy Maclure in den Weinbergen der Maclures.", description = "Hier, bitte schön. Und wenn Ihr Billy die Pastete gebt, dann sagt ihm, ich hoffe, er erstickt daran!", progress = "Aaah... Ich bin am Verhungern! Habt Ihr die Pastete für mich, <Name>?", completion = "Mmmm, lecker! Diese Pastete ist perfekt!\n\nIch glaube, langsam kommt mein Gedächtnis wieder...", rewards = "Ihr bekommt:\n\n"},
[85] = {title = "Die verlorene Halskette", objective = "Sprecht mit Billy Maclure.", description = "Ich habe meine Halskette verloren und ich glaube, dieser Tunichtgut Billy Maclure hat sie genommen! Normalerweise treibt er sich immer wie eine kleine Ratte in den Weinbergen der Maclures östlich von hier herum. \n\nBringt mir meine Halskette zurück, wenn Ihr das Herz einer alten Witwe erfreuen wollt.", progress = nil, completion = "Ihr habt was verloren? Also ich hab keine Kette genommen, denn ich bin kein Dieb!\n\nIch weiß vielleicht, wer's war, aber... &lt;grins&gt;... ich hab einfach zu viel Hunger, um drauf zu kommen.", rewards = "Ihr bekommt:\n\n"},
[86] = {title = "Pastete für Billy", objective = "Bringt 4 Brocken Eberfleisch zu Tantchen Bernice Stonefield auf den Hof der Stonefields.", description = "Wenn ich 'ne Pastete kriegen würde, dann könnte ich Euch vielleicht sagen, wer die Kette hat. Ach, und wisst Ihr was? Diese alte Dame Bernice auf dem anderen Hof da macht ganz tolle Schweinebauchpasteten. \n\nWenn Ihr ihr ein paar Brocken Eberfleisch von den Ebern bringt, die immer um unsere Höfe herumstromern, und ihr sagt, dass es für einen guten Zweck ist, dann backt sie Euch vielleicht eine Pastete.", progress = "Ich halte es nicht für richtig, den frechen Jungen, der meine Kette überhaupt erst gestohlen hat, dafür auch noch zu füttern, aber wenn es sein muss, damit ich mein Eigentum wiederbekomme, dann soll es eben so sein.\n\nHabt Ihr das Eberfleisch?", completion = "Das Fleisch von wilden Ebern ist zwar zäh, aber wenn man es lange genug köcheln lässt, dann wird eine ganz vorzügliche Pastete daraus!", rewards = "Ihr bekommt:\n\n"},
[87] = {title = "Goldzahn", objective = "Bringt Berenices Halskette auf den Hof der Stonefields zu \"Tantchen\" Berenice Stonefield.", description = "Ich hab in der Nähe von der Tiefenschachtmine gespielt und da hab ich, glaub ich, die Kette von der alten Dame fallen ge... äääh, gesehen. Fragt mich nicht, wie die dahin gekommen ist, ich war's nicht!\n\nNa egal, jedenfalls hab ich diesen großen Kobold gesehen, der hatte einen Goldzahn und der hat die Kette aufgehoben und ist in die Mine gerannt. Wenn Ihr diesen Kobold findet, dann findet Ihr auch die Halskette, ehrlich! Ich schwör's!", progress = "Hallo, <Name>. Habt Ihr meine Halskette gefunden?", completion = "Oh, Ihr habt sie tatsächlich gefunden! Danke, danke, mein Lieber!\n\nHier, nehmt dies. Es hat meinem Mann gehört und er sagte immer, dass es Glück brächte. Wenn er es doch nur auf seinem letzten Feldzug nicht vergessen hätte! *schnief*", rewards = "Ihr bekommt:\n\nMit Löwen bedruckte Handschuhe"},
[88] = {title = "Prinzessin muss sterben!", objective = "Tötet Prinzessin, nehmt ihr Halsband an Euch und bringt es zu Mutter Stonefield auf den Hof der Stonefields.", description = "Die Brackwells haben ein Schwein, eine Sau namens Prinzessin, die schon viele Preise gewonnen hat. Dass dieses Tier so riesig geworden ist, das kommt nur daher, dass es immer hier herübergeschlichen kommt und mein Gemüse frisst!\n\nUnd deswegen muss Prinzessin sterben, bevor sie wieder unsere Felder heimsucht! Bringt mir ihr Halsband zum Beweis, dass Ihr die Sau abgestochen habt, dann gebe ich Euch etwas, das Euch für Euren Aufwand entschädigt.\n\nIhr findet Prinzessin normalerweise bei Brackwells Kürbisbeet, noch hinter dem Hof der Maclures und von dort aus im Osten gesehen. Ich hoffe, Ihr erwischt die Sau, bevor sie wieder hungrig wird und hierher kommt!", progress = "Habt Ihr sie schon gesehen? Habt Ihr sie erwischt?", completion = "Welch ein Glück! Dieses Schwein war schon so groß, dass es bestimmt bald unsere gesamte Ernte gefressen hätte! Ich danke Euch, &lt;Name&gt;.\n\nNun, könnt Ihr mit einem dieser Dinge hier etwas anfangen?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWettergegerbte StiefelMessingbeschlagene ArmschienenBauern-Stiefel\n\nIhr bekommt außerdem:\n\n"},
[89] = {title = "Die Immerruhbrücke", objective = "Bringt 5 Eisenspitzen und 5 Eisennieten nach Seenhain zu Großknecht Oslow.", description = "Während der letzten Invasion der Orcs waren wir gezwungen, unser Eisen einzuschmelzen, um Kugeln, Schwerter und Rüstungen herzustellen. Wir haben Stormwind benachrichtigt, dass wir eine neue Lieferung Materialien benötigen. Aber eine Bande von Rotkammgnollen hat die Karawane überfallen und sich dann in die Hügel hinter Seenhain zurückgezogen.\n\nJetzt gehen uns langsam die Vorräte aus, die wir brauchen, um die Brücke wieder aufzubauen. Wenn Ihr mir 5 Eisenspitzen und 5 Eisennieten bringt, <Name>, dann sollt Ihr dafür belohnt werden. \n\nUnd jetzt an die Arbeit!", progress = "Diese Brücke wird sich nicht selber bauen! Also wo sind diese Eisenspitzen und Eisennieten?", completion = "Gute Arbeit, &lt;Name&gt;. Dieses Material wird den Brückenbau ganz enorm beschleunigen. Die kleine Schönheit hier wird im Handumdrehen repariert sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHose des SchmiedsBrückenarbeiter-HandschuheReithandschuhe\n\nIhr bekommt außerdem:\n\n"},
[90] = {title = "Gewürzter Wolfskebab", objective = "Beschafft Euch 10 magere Wolfflanken und Würzkräuter aus Stormwind und kehrt dann zu Küchenchef Grual nach Dunkelhain zurück.", description = "Gewürzter Wolfskebab ist eine Spezialität des Hauses! Natürlich kann ich Euch welchen machen. Aber ich brauche erst die Zutaten dafür. Bringt mir 10 magere Wolfflanken sowie Würzkräuter aus Stormwind. Hier im Wald streifen so viele Wölfe herum, da werdet Ihr kein Problem haben, an die Wolfflanken zu kommen, da bin ich mir sicher. Und für die Kräuter sucht ihr am besten Felicia Gump in ihrem Blumenladen im Kanaldistrikt von Stormwind auf.", progress = "Habt Ihr die 10 mageren Wolfflanken schon zusammen? Und was ist mit den Kräutern von Felicia aus Stormwind?", completion = "Gut gemacht, &lt;Name&gt;! Ich wünsche Euch guten Appetit bei dieser echten Spezialität, dem gewürzten Wolfskebab!", rewards = "Ihr bekommt:\n\nGewürzter WolfskebabRezept: Gewürzter Wolfskebab"},
[91] = {title = "Das Gesetz des Solomon", objective = "Bringt 10 Schattenfellanhänger ins Rathaus von Seenhain zu Büttel Conacher.", description = "Ein Feind Stormwinds hat sich im östlichen Vorläufer des Rotkammgebirges niedergelassen. Dieser verderbte Schurke bedient sich des Übernatürlichen, um unsere Stadt und ihre Einwohner in Angst und Schrecken zu versetzen. Er betreibt sein übles Geschäft unter dem Namen Morganth.\n\nMorganth kontrolliert jetzt den Schattenfellklan. Die Gnolle tun alles, was er ihnen befiehlt. Wie es das Gesetz von Seenhain vorsieht, steht auf die Unterstützung eines im Königreich gesuchten Verbrechers die Todesstrafe.\n\nDiese abscheulichen Gnolle verdienen den Tod!\n\nGebt 10 Schattenfellanhänger bei mir ab, dann erhaltet Ihr eine Belohnung.", progress = "Gebt 10 Schattenfellanhänger bei mir ab, dann erhaltet Ihr eine Belohnung.", completion = "Das Gericht von Seenhain weiß Euren Einsatz für die Gerechtigkeit zu schätzen, &lt;Name&gt;. Indem Ihr die Gesetze des Königreichs durchgesetzt habt, habt Ihr auch der Gerechtigkeit in diesem Land einen Sieg verschafft.", rewards = "Ihr bekommt:\n\n"},
[92] = {title = "Rotkammgulasch", objective = "Küchenchefin Breanna aus Seenhain möchte 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch.", description = "Ich würde liebend gern Rotkammgulasch für Euch kochen. Aber es gibt da ein kleines Problem. Erst kürzlich musste ich während des Orcaufstands eine ganze Brigade von Soldaten der Armee von Stormwind verpflegen. Jetzt ist meine Vorratskammer leer. Aber wenn Ihr mir die Zutaten besorgt, dann mache ich das gern für Euch.\n\nBringt mir einfach 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch.", progress = "Ich brauche immer noch 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch.", completion = "Gut gemacht, &lt;Name&gt;. Und so schöne Exemplare noch dazu! Dafür bekommt Ihr hier auch die köstliche Spezialität, die als Rotkammgulasch bekannt ist!", rewards = "Ihr bekommt:\n\nRotkammgulaschRezept: Rotkammgulasch"},
[93] = {title = "Schwärzliche Krebsküchlein", objective = "Beschafft 6 klebrige Spinnenbeine und bringt sie nach Dunkelhain zu Küchenchef Grual.", description = "Ich verrate Euch ein kleines Geheimnis: Schwärzliche \"Krebs\"-Küchlein werden eigentlich aus Spinnenbeinen gemacht! Ich weiß, das ist irgendwie eklig, aber die Küchlein schmecken lecker, ein bisschen scharf und eignen sich ganz ausgezeichnet zum Knabbern. Wenn Ihr mir einige klebrige Spinnenbeine bringt, dann zaubere ich euch ein paar.\n\nIch habe gehört, dass sich Giftweberspinnen ausgezeichnet dafür eignen - sie haben ihr Nest im Norden, zwischen dem Vorgebirge und dem Fluss.", progress = "Seid gegrüßt, <Name>. Habt Ihr die klebrigen Spinnenbeine schon zusammen?", completion = "Ah ja, da habt Ihr ja ein paar nette Beinchen eingesammelt! So, jetzt muss ich die nur noch mit meiner hochgeheimen Gewürzmischung würzen - wehe, Ihr schaut! - und sie dann noch ein bisschen in der Pfanne braten...\n\nDie schwärzlichen Krebsküchlein sind meine Spezialität, deswegen verrate ich das Rezept nicht. Aber hier habt Ihr das Rezept für ein Gericht, das fast genauso gut schmeckt.", rewards = "Ihr bekommt:\n\nRezept: Klebriger Spinnenkuchen"},
[94] = {title = "Ein wachsames Auge", objective = "Bringt die Glyphe von Azora zur Löwenstatue in der Nähe des Turms von Ilgalar im Rotkammgebirge.", description = "Mein Widersacher Morganth ist ein böser Magier von großer Macht, der im Turm von Ilgalar im Rotkammgebirge lebt. Ich habe eine Methode entwickelt, mit der ich ihn ausspionieren kann: Mit dem Auge von Azora ist es mir möglich, ihn von weitem zu sehen.\n\nDoch um seine Gedanken zu erforschen... ja, dazu benötige ich noch weitere Hilfe.\n\nWenn Ihr gewillt seid, dies zu tun, dann bringt meine Glyphe von Azora zum Turm von Ilgalar. Legt sie auf die Löwenstatue in der Nähe des Turms.\n\nSobald dieses getan ist, wird die Macht von Azora mir Visionen von Morganths zukünftigen Plänen gewähren.", progress = "Die Löwenstatue steht schon seit Jahrzehnten hier und bewacht einsam und allein den berüchtigten Turm von Ilgalar.\n\nAm Sockel der Statue befindet sich eine Vertiefung, wo ein Edelstein oder eine Glyphe eingesetzt werden könnte...", completion = "Ihr legt die Glyphe von Azora auf den Stein. Auf magische Weise verbindet die Glyphe sich mit der Statue - und als dies geschehen ist, hört Ihr plötzlich Theocritus' Stimme aus ihr ertönen:\n\nSeid Euch meiner Dankbarkeit gewiss, &lt;Name&gt;, mein junger Freund. Ihr habt jetzt die Möglichkeit, durch diese Glyphe mit mir zu sprechen - es ist gut möglich, dass ich in Zukunft weitere Aufgaben für Euch habe. Aber erst muss ich die Gedanken meines Widersachers studieren.", rewards = "Ihr bekommt:\n\n"},
[95] = {title = "Svens Rache", objective = "Begebt Euch zu Svens Hof und findet heraus, was hinter dem alten Baumstumpf vergraben wurde.", description = "Früher arbeitete ich auf einem der Höfe im Südosten... bis einmal in meiner Abwesenheit Dunkle Reiter vom Gebirgspass der Totenwinde herunterkamen, meinen Hof überfielen und meine Familie abschlachteten.\n\nAls ich zurückkehrte, sah ich eine schattenhafte Gestalt, die sich bei meiner Scheune herumtrieb und dort etwas vergrub. Er floh, ehe ich ihn erreichen konnte, und ich hatte keine Zeit, mich mit ihm aufzuhalten, da ich den Dunklen Reitern dicht auf den Fersen war. Und so habe ich nie entdeckt, was die Gestalt dort versteckte.\n\nWenn Ihr herausfinden könntet, was jene schattenhafte Gestalt dort vergrub, dann wäre ich Euch dankbar. Das Versteck befindet sich hinter dem alten Baumstumpf in der Nähe meiner Scheune.", progress = nil, completion = "Ihr seht einen Haufen eilig aufgeschütteter Erde: Es scheint, als habe jemand etwas verstecken wollen und nicht viel Zeit gehabt, um dies zu tun.", rewards = "Ihr bekommt:\n\n"},
[96] = {title = "Ruf des Wassers", objective = "Bringt den Splitter des Wassers in das Brachland zu Islen Waterseer.", description = "Nehmt Splitter. Nehmt Splitter und gebt Leben.\n\nGebt Leben und versteht. Versteht, Wasser ist Leben... Verderbnis beendet Leben.\n\nIhr schützt und gebt Leben mit der Macht des Wassers.", progress = "Ihr seid zurückgekehrt. Ausgezeichnet!\n\nWie war Eure Reise nach Silberwald? Wart Ihr lange unterwegs?\n\nEs ist schwer für mich, festzustellen, ob Ihr Erfolg hattet oder nicht, denn ein so großer Teil des Landes ist bereits verderbt. Der Gestank der Verderbnis legt sich über alles Gute, das Ihr dort getan haben mögt. Doch die kleinen Erfolge sind manchmal genauso wichtig wie die großen. Die Läuterung des Wassers war höchst bedeutsam für Euch, nein, für alle Schamanen.", completion = "Dies ist der Beweis, um den ich Euch gebeten hatte. Ihr habt Eure Sache gut gemacht, &lt;Name&gt;.\n\nIch freue mich, dass ich die Erste bin, die Euch gratuliert, und dass ich Euch dies geben kann - Euer Wassertotem.\n\nVerwendet es klug - und viel Glück.\n\nBis zu Eurer nächsten Prüfung wird es noch eine Weile dauern, also lernt Eure Lektionen sorgfältig bis dahin. Reines Wasser kann nicht nur Verletzten das Leben zurückgeben, sondern hat auch andere vielfältige Wirkungen. Ich schlage vor, Ihr sucht einen Schamanenlehrer auf, wenn Ihr die Zeit dafür habt. Dort könnt Ihr vielleicht noch weitere Zauber lernen.", rewards = "Ihr erlernt:\n\nTotem des heilenden Flusses\n\nDer folgende Zauber wird auf euch gewirkt:\n\nTotem des heilenden Flusses\n\nIhr bekommt außerdem:\n\nWassertotem"},
[97] = {title = "Die Legende von Stalvan", objective = "Berichtet Kommandant Ebonlocke die Neuigkeiten.", description = "Kommandant Ebonlocke muss unverzüglich erfahren, dass die Handschriften identisch sind, <Name>! Ihr Verdacht hat sich also bestätigt.", progress = nil, completion = "Ich wusste es! Gute Arbeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[98] = {title = "Die Legende von Stalvan", objective = "Tötet Stalvan Mistmantle und zeigt Madame Eva den Ring seiner Familie.", description = "Stalvan Mistmantle hat ein Leben der Verworfenheit gelebt und unschuldige Opfer starben von seiner Hand. Zweifellos hat er noch zahllose andere Verbrechen begangen und nun wird Dunkelhain von diesem Wahnsinnigen bedroht. Das Licht allein weiß, welche schmutzigen Pläne er jetzt ausheckt. Deswegen brauche ich Eure Hilfe, <Klasse>. Begebt Euch zu seiner Hütte ein kleines Stück nördlich der Stadt und schaltet Stalvan ein für alle Mal aus.\n\nSobald die Tat vollbracht ist, begebt Euch zu Madame Eva und zeigt Ihr den Ring seiner Familie. Schließlich war es ihre Vorahnung, die zu dieser entsetzlichen Entdeckung führte. Doch jetzt kann ganz Dunkelhain dank ihr wieder ruhiger schlafen.", progress = "Ja, <Name>?", completion = "Ich weiß es bereits, &lt;Name&gt;: Stalvan ist tot. Ich spürte, wie eine Woge der Hoffnung durch den verseuchten Wald ging. Nun ist der Dämmerwald für alle Zeiten von Stalvans Blutdurst befreit. Meine Freude wird getrübt durch den Gedanken an all diejenigen, die diesem schrecklichen Monster zum Opfer gefallen sind. Doch wie dem auch sei. Ihr, &lt;Klasse&gt;, seid mutig und geschickt und ich danke Euch.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSichel der unglückseligen GeisterRing der unglückseligen Geister\n\nIhr bekommt außerdem:\n\n"},
[99] = {title = "Arugals Torheit", objective = "Bringt Dalar Dawnweaver 6 Pyrewood-Fesseln zum Grabmal.", description = "Je mehr ich über Arugals Magie erfahre, umso mehr wächst meine Verachtung für diesen jämmerlichen Narren. Bald werde ich meine Studien zu seiner so genannten 'Arznei' beendet haben.\n\nMein Wissen wird vollständig sein, sobald ich herausgefunden habe, welche Verzauberung die seltsamen Zustände in Pyrewood verursacht. Tagsüber scheinen die Arbeiter dort ganz gewöhnliche Menschen zu sein. Doch sobald die Sonne untergeht, verwandeln sich die Dorfbewohner in Moonrage-Worgs.\n\nIch muss Energie aus den verzauberten Fesseln ziehen, die Arugal auf sie gewirkt hat. Bringt mir 6 verzauberte Pyrewood-Fesseln, <Name>.", progress = "Habt Ihr die Pyrewood-Fesseln schon sichergestellt, <Name>?", completion = "Euere Hartnäckigkeit ist lobenswert. Dank des Wissens, das zu beschaffen Ihr mir geholfen habt, wird Arugal untergehen und seine leichtsinnige Magie zunichte gemacht werden. Meinen Beifall, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBaumspalterKnochenmahlerstößelGlutstecken\n\nDer folgende Zauber wird auf euch gewirkt:\n\nArkane Intelligenz\n\nIhr bekommt außerdem:\n\n"},
[100] = {title = "Ruf des Wassers", objective = "Sprecht mit der schwachen Wassermanifestation im Silberwald.", description = "Noch während die Zauberformel, die Ihr gesprochen habt, verhallt, zuckt ein Meer von Lichtern um Euch herum auf. Das Zischen der Wassertropfen, die mit den Flammen in Berührung kommen, lässt nach und Eure überreizten Sinne spüren, wie die verderbten Geister in Eurer Nähe vernichtet werden.", progress = nil, completion = "Dank Euch. Dank den Schamanen.\n\nDie Verderbnis weicht, aber das Leben schwindet weiter. Es ist an den Schamanen, Leben zu schützen.", rewards = nil},
[101] = {title = "Das Totem des Gegenschlages", objective = "Bringt 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift nach Dunkelhain zu Madame Eva.", description = "Nun, da übernatürliche Mächte den Wald durchziehen, besteht ganz zweifellos die Notwendigkeit, sich zu schützen, <Name>. Leise flüstern mir die Winde von einer großen Gefahr, die auf Euch lauert und der Ihr Euch in nicht allzu ferner Zukunft gegenübersehen werdet.\n\nAuch ein tapferer <Klasse> wie Ihr sollte sich schützen. Falls Ihr dies wünscht, so bringt mir 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift. Dann stelle ich Euch ein Totem des Gegenschlages her und belege es mit einem Zauber, durch den es all denjenigen schadet, die gegen Euch Gewalt anwenden wollen.", progress = "Bringt 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift nach Dunkelhain zu Madame Eva. Ich werde Euch ein Totem des Gegenschlages herstellen und es mit einem Zauber belegen, durch den es all denjenigen schadet, die gegen Euch Gewalt anwenden wollen.", completion = "Das war sehr klug von Euch, &lt;Name&gt;. Dieses Totem des Gegenschlages wird Euch gegen das Böse beschützen, das in ganz Azeroth und darüber hinaus lauert. Wenn Ihr Euch bedroht fühlt, dann haltet dieses Totem hoch und fühlt Euch von seiner magischen Aura getröstet. Seid tapfer, edler &lt;Klasse&gt;. Ihr werdet allen Mut brauchen, den Ihr aufbringen könnt, denn ich sehe viel Blutvergießen in Eurer Zukunft.", rewards = "Ihr bekommt:\n\nTotem des Gegenschlages"},
[102] = {title = "Auf Patrouille durch Westfall", objective = "Bringt 8 Gnolltatzen auf die Späherkuppe zu Captain Danuvin.", description = "Stormwind hat uns im Stich gelassen. Der üble Gestank der Verderbtheit weht über die Ebenen von Westfall. Dies war und ist mein Heimatland und ich werde die Bürger, die sich zum Bleiben entschlossen haben, nicht verlassen. Wir, die wir früher Bauern waren, werden Widerstand leisten.\n\nEure Aufgabe, so Ihr sie denn annehmt, wird es sein, im Grasland von Westfall auf Patrouille zu gehen. Spürt die widerwärtigen Gnolle auf, die augenscheinlich mit den Dieben aus den Todesminen zusammenarbeiten, und tötet sie. Bringt mir 8 Gnolltatzen und ich werde Euren Mut zu belohnen wissen.", progress = "Habt Ihr bereits 8 Tatzen dieser verräterischen Gnolle erlangt?", completion = "Gut gemacht, &lt;Name&gt;. Wenn tapfere Abenteurer wie Ihr selbst weiter Seite an Seite mit der Volksmiliz kämpfen, ist es durchaus möglich, dass Westfall wieder zu der reichen Kornkammer werden könnte, die es einmal war. Bitte nehmt dies in Anerkennung Eurer unermüdlichen Anstrengungen entgegen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGürtel der VolksmilizArmschienen der Volksmiliz\n\nIhr bekommt außerdem:\n\n"},
[103] = {title = "Bewahrer der Flamme", objective = "Bringt 5 Fläschchen Öl zu Captain Grayson beim Leuchtturm von Westfall.", description = "Die Nacht, in der die Familie des Leuchtturmwärters starb, war schrecklich. Hilflos musste ich mit ansehen, wie Old Murk-Eye den Angriff befehligte. Doch was geschehen ist, ist geschehen. Nun sorge ich mich vor allem um das Leben der Seeleute, die das große Meer besegeln und deren Schiffe den trügerischen Felsen vor der Küste gefährlich nahe kommen. Da hier niemand mehr lebt, der die Flamme bewacht, obliegt die Verantwortung nun mir.\n\nHelft mir dabei, die Fackel am Leuchten zu erhalten, und bringt mir 5 Fläschchen Öl von den Erntemonstern.", progress = "Ohne Öl wird die Flamme nicht lange brennen, <Name>.", completion = "Ein Hoch auf Eure Tapferkeit, &lt;Klasse&gt;. Die Felsen entlang der Küste von Westfall werden dank Eurer harten Arbeit wieder hell erleuchtet sein. Die Fackel wird viele Leben retten, solange sie weiterbrennt.\n\nAn eben diesem Strand starb ich einen sinnlosen Tod. Jetzt, nach meinem Tod, ist es meine Bürde, sicherzustellen, dass niemand anderes dasselbe Schicksal erleiden muss.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchwacher ManatrankSchwacher Heiltrank\n\nIhr bekommt außerdem:\n\nRolle der IntelligenzRolle der Ausdauer"},
[104] = {title = "Bedrohung an der Küste", objective = "Bringt Captain Grayson am Leuchtturm von Westfall eine Schuppe von Old Murk-Eye.", description = "Als ich auf den Felsen mein Leben aushauchte, hatte ich keine Ahnung, was das Leben nach dem Tode für mich bereithalten würde. In jener Nacht war der Leuchtturm erloschen, weil Old Murk-Eye die Familie des Leuchtturmwärters vertrieben hatte. Die Familie kehrte zurück und zündete die Flamme wieder an, doch Old Murk-Eye brachte die willensschwächeren Murlocs dazu, den Leuchtturm noch einmal mit ihm zusammen anzugreifen. Beim zweiten Mal hatte die Familie nicht so viel Glück. Vor meinen Augen starben sie alle, ohne sich wehren zu können.\n\nTötet Old Murk-Eye, wenn Ihr ihn am Ufer seht, und bringt mir eine seiner Schuppen, dann werdet Ihr eine Belohnung erhalten.", progress = "Habt Ihr der Bedrohung namens Old Murk-Eye schon den Garaus gemacht? Er ist gesehen worden, wie er an der Küste von Westfall umherstreifte.\n\nKehrt zu mir zurück, sobald das garstige Ungeheuer tot ist.", completion = "Also ist Murk-Eye, dieser garstige Heide, endlich tot. Gut gemacht, &lt;Name&gt;. Durch Eure Hand ist ein Leben beendet worden, doch vielleicht wurden gerade durch diese Tat viele weitere Leben gerettet. So gefährlich das große Meer auch ist, diese Nacht wird es dank Eurer heldenhaften Tat ein wenig sicherer sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGraysons FackelRundschild der MeereZauberstab des Fackelscheins\n\nIhr bekommt außerdem:\n\n"},
[105] = {title = "Weh dir, Andorhal", objective = "Bringt den Splitter von Arajs Phylakterium zu Hochexekutor Derrington ins Bollwerk in den westlichen Pestländern.", description = "Endlich ist die Zeit gekommen Andorhal anzugreifen und den Lich, der die Stadt kontrolliert, zu vertreiben.\n\nDer Lich - Araj der Zerstörer - herrscht von innerhalb der Ruinen der Stadt aus. Er wird von zahlreichen Angehörigen der Geißel bewacht, die über die Überreste des Stadtzentrums wachen, auch sein Gefolge an Leibwächtern ist ausgezeichnet. Ihr werdet einige Verbündete brauchen, um auch nur einen Hauch von einer Chance zu haben, sich ihm gegenüber stellen zu können.\n\nVernichtet Araj, <Name>, und bringt mir einen Splitter seines Phylakteriums als Beweis!", progress = "Ihr habt Euren Auftrag erhalten, <Name>. Habt Ihr einen Splitter vom Phylakterium des Lichs als Beweis, dass die Tat vollbracht ist?", completion = "Ihr habt es geschafft! Araj... der Lich ist endlich besiegt!\n\nIhr habt der Horde heute einen gewaltigen Dienst erwiesen, &lt;Name&gt;. Eure Tapferkeit und Hartnäckigkeit sind ein Beispiel dafür, was es heißt, ein wahrer Held zu sein. Bitte - nehmt dies als ein Zeichen für alle, die Euch sehen, auf dass sie wissen, dass Ihr für die Horde einen unsterblichen Sieg errungen habt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nMal der Resolution"},
[106] = {title = "Junge Liebende", objective = "Gebt Tommy Joe StonefieldMaybells Liebesbrief.", description = "Oh, ein Fluch lastet auf mir! Mein Herz gehört Tommy Joe Stonefield, aber unsere Familien sind aufs Ärgste miteinander verfeindet. Daher kann ich mich nicht mit ihm treffen, obwohl ich mich doch so sehr danach sehne, sein geliebtes Gesicht zu sehen!\n\nBitte nehmt diesen Brief und gebt ihn Tommy Joe. Normalerweise hält er sich am Fluss im Westen des Hofs der Stonefields auf, das ist auch von hier aus genau westlich.", progress = "Was habt Ihr? Maybell ist der einzige Lichtstrahl in meinem trüben Leben. Schnell, lasst mich ihren Brief sehen!", completion = "Ach! Ich kann es nicht ertragen, dass wir getrennt sind. Ich muss sie unbedingt sehen!", rewards = "Ihr bekommt:\n\n"},
[107] = {title = "Nachricht an William", objective = "Bringt Oma Stonefields Nachricht zu William Pestle.", description = "Ich möchte wetten, William Pestle hat einen Trank, der unsere beiden Liebenden zusammenbringen kann.\n\nHier, bringt William diese Nachricht. Er wohnt im Gasthaus Zur Höhle des Löwen in Goldhain.", progress = "Ihr habt da eine Nachricht von \"Oma\" Stonefield, hm? Ich habe Mildred schon seit Jahren nicht mehr gesehen! Ich frage mich, was so wichtig ist, dass sie mir schreibt...", completion = "Maybell und Tommy Joe, diese armen Kinder, haben mein ganzes Mitgefühl. Ich kann mich noch gut daran erinnern, wie ich mich einst fühlte, als ich selbst noch jung und verliebt war...\n\nEs muss doch etwas geben, das ich tun kann, um ihnen zu helfen! Lasst mich einen Moment nachdenken...", rewards = "Ihr bekommt:\n\n"},
[109] = {title = "Meldung bei Gryan Stoutmantle", objective = "Sprecht mit Gryan Stoutmantle. Normalerweise findet man ihn im Steinturm auf der Späherkuppe, ein kleines Stückchen von der Straße weg, mitten in Westfall.", description = "Es scheint mir, <Klasse>, als hättet Ihr schon etliche Kämpfe überstanden. Falls Ihr das noch nicht getan habt, solltet Ihr Euch bei Gryan Stoutmantle melden. Er ist der Anführer der Volksmiliz, die es sich zur Aufgabe gemacht hat, das Ackerland von Westfall zu beschützen. Ich möchte wetten, er könnte Eure Hilfe gebrauchen. Normalerweise findet man ihn im Steinturm auf der Späherkuppe, ein kleines Stückchen von der Straße weg, mitten in Westfall.", progress = nil, completion = "Ah, mein Freund hat Euch also zu mir geschickt? Wie nett. \n\nNun, das Königshaus von Stormwind hat unsere Sache aufgegeben. Jetzt ist es an der Volksmiliz, das Land von der Verderbnis zu befreien. Wenn Euch unsere Sache interessiert, so würde ich Eure Fertigkeit im Kampf gern im Namen der Freiheit einsetzen.", rewards = "Ihr bekommt:\n\n"},
[110] = {title = "Insektenteil-Analyse", objective = "Begebt Euch nach Gadgetzan zu Alchimist Pestlezugg und erkundigt Euch nach der Analyse der Insektenteile.", description = "Ich werde einige Zeit brauchen, um Scrimshanks Feldmesserausrüstung durchzusehen... und seine persönlichen Angelegenheiten zu regeln. Mein Bauch sagt mir, dass dies nicht der letzte Verlust ist, den wir durch die Käfer hinnehmen müssen.\n\nGeht bitte zu Alchimist Pestlezugg, um zu sehen, ob er etwas mit den Insektenteilen anfangen konnte, die wir ihm geschickt haben. Wenn sie fertig sind, bringt sie mir.", progress = nil, completion = "Ja, ich habe die Ergebnisse direkt vor mir. Sie sind... gelinde gesagt, beunruhigend.\n\nUnser Anfangsverdacht, dass die Käfer durch eine äußere Macht kontrolliert werden, war wohl richtig. Falls das zutrifft, dann haben wir es nicht nur mit einer sehr starken unbekannten Macht zu tun, sondern auch noch mit einer bösartigen. Diese Käfer wurden in absolut verheerende Wesen verwandelt. Ich habe so etwas noch nie gesehen.", rewards = "Ihr bekommt:\n\n"},
[111] = {title = "Gespräch mit Oma", objective = "Sprecht mit Oma Stonefield.", description = "Bitte sprecht mit meiner Großmutter, <Name>. Wenn irgendjemand einen Weg weiß, wie ich mit Maybell zusammen sein kann, dann ist sie das.\n\nIhr findet sie in unserem Haus, östlich von hier.", progress = nil, completion = "Solange die Feindschaft zwischen unseren Familien besteht, sehe ich keine gemeinsame Zukunft für Tommy Joe und Maybell... Aber vielleicht können wir sie ja wenigstens für kurze Zeit zusammenbringen.\n\nHmm, was kann man da machen...", rewards = "Ihr bekommt:\n\n"},
[112] = {title = "Die Suche nach dem Tang", objective = "Bringt 4 Kristalltangwedel nach Goldhain zu William Pestle.", description = "Ich könnte einen Unsichtbarkeitsschnaps für Maybell brauen, damit sie sich aus den Weinbergen der Maclures fortstehlen und Tommy Joe sehen kann. Aber um den Schnaps herzustellen, brauche ich etwas Kristalltang.\n\nDieser Tang wächst zwar normalerweise im Meer, aber manchmal wird er auch von den Murlocs gesammelt. Geht und schaut, ob die Murlocs am Kristallsee welchen haben. Der Kristallsee liegt ein kleines Stück östlich von Goldhain.", progress = "Habt Ihr den Kristalltang? Ich bin mir sicher, Maybell kann es kaum erwarten, zu ihrem Verehrer zu kommen.", completion = "Ihr habt den Tang bekommen. Ausgezeichnet! Wartet noch einen kleinen Moment, während ich den Trank braue...", rewards = "Ihr bekommt:\n\n"},
[113] = {title = "Insektenteil-Analyse", objective = "Bringt den Bericht nach Gadgetzan zum Leitenden Feldmesser Fizzledowser. Lasst Euch von ihm eine Kopie des Berichts geben, wie Alchimist Pestlezugg gefordert hat.", description = "Der Leitende Feldmesser Fizzledowser muss diesen Bericht sofort sehen. Eigentlich muss jeder, der lesen kann, diesen Bericht sehen. Wir stehen einer großen und ernsten Bedrohung gegenüber, die nicht nur Tanaris und Gadgetzan, sondern das ganze südliche Kalimdor betrifft, wenn wir nichts unternehmen. Möglicherweise ist sogar ganz Azeroth gefährdet. Dieses Ding macht nicht den Eindruck, als würde es das Interesse verlieren.\n\nLasst Fizzledowser ein Duplikat des Berichts anfertigen, den Ihr dann an Eure Verbündeten verteilen könnt. Jeder muss von dieser Bedrohung erfahren!", progress = "Na, Unterfeldmesser <Name>, hat der alte Pestlezugg diesen Bericht schon fertig?", completion = "Vielen Dank für die Überbringung des Berichts, Unterfeldmesser &lt;Name&gt;, hier ist Eure Bezahlung für den gewissenhaften Dienst an der Gadgetzan Water Company.\n\nIch bin zwar normalerweise nicht begeistert von dem Gedanken, unsere wertvollen Informationen einfach so an diejenigen weiterzugeben, die anderenfalls gutes Geld dafür bezahlen würden, aber ich kenne Pestlezugg jetzt schon etliche Jahre. Wenn er empfiehlt, jeden darüber zu informieren, dann soll es so sein. Gebt mir einen Augenblick und ich werde Euch eine Kopie erstellen.", rewards = "Ihr bekommt:\n\n"},
[114] = {title = "Die Flucht", objective = "Bringt Maybell Maclure den Unsichtbarkeitsschnaps.", description = "Bringt der jungen Maybell diesen Unsichtbarkeitsschnaps. Seine Wirkung sollte so lange anhalten, dass sie Tommy Joe besuchen kann.", progress = "Habt Ihr Tommy Lee meinen Brief überbracht? Was hat er gesagt?", completion = "Ach du liebe Zeit! Ich fühle mich schuldig, weil ich meine Familie täuschen muss, aber meine Gefühle für Tommy Joe sind einfach zu stark. Ich kann sie nicht ignorieren.\n\nIch danke Euch, &lt;Name&gt;. Ich werde den Schnaps trinken, sobald ich eine Möglichkeit dazu habe, und mich zu meinem Liebsten schleichen.\n\nUnd Ihr... bitte nehmt dies.", rewards = "Ihr bekommt:\n\nSchwacher Heiltrank"},
[115] = {title = "Schattenmagie", objective = "Bringt 3 Mitternachtskugeln nach Seenhain zu Marshal Marris.", description = "Von den Orcs des Blackrockklans wurden zur Unterstützung ihrer Angriffe auf das Rotkammgebirge Schattenzauberer rekrutiert, die von einer dunklen Macht erfüllte Vorrichtungen mit sich führten - Mitternachtskugeln. Diese Kugeln haben den Verteidigern vom Rotkammgebirge schwere Verluste zugefügt und es ist von äußerster Wichtigkeit, dass wir diese dämonbesudelten Gegenstände aus dem Konflikt entfernen.\n\nDurchsucht erschlagene Schattenzauberer der Blackrock nach Mitternachtskugeln und bringt sie mir. Ich werde die Kugeln dann vernichten lassen, denn ohne sie wäre die Welt ein wesentlich besserer Ort.", progress = "Wie verläuft Euer Kampf gegen die Schattenzauberer? Habt Ihr die Mitternachtskugeln gefunden?", completion = "Ich danke Euch, &lt;Name&gt;. Ich werde diese Kugeln umgehend ihrer Beseitigung zuführen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[116] = {title = "Trockene Zeiten", objective = "Barkeeper Daniels aus Seenhain braucht ein Fässchen Donnerbräu Lagerbier, ein Fässlein Merlot, eine Flasche Fusel und einen Schlauch mit süßem Rum.", description = "Mir werden hier gerade die Vorräte knapp, <Name>. Alle Flaschen sind fast leer, und die letzte Schnapslieferung hätte schon längst hier eintreffen sollen. Die Orcinvasion ist einfach die Hölle.\n\nVielleicht könnt Ihr Euch ja für mich an die Arbeit machen?\n\nIhr müsst für mich bei Grimbooze Donnerbräu in den Westfall-Hügeln ein Fässchen Donnerbräu Lagerbier besorgen, ebenso ein Fässlein Merlot aus Stormwind, eine Flasche Fusel aus Dunkelhain und einen Schlauch mit süßem Rum aus Goldhain. Bringt mir all diese Dinge, dann werde ich dafür sorgen, dass Ihr belohnt werdet.", progress = "Ihr müsst für mich bei Grimbooze Donnerbräu in den Westfall-Hügeln ein Fässchen Donnerbräu Lagerbier besorgen, ebenso ein Fässlein Merlot aus Stormwind, eine Flasche Fusel aus Dunkelhain und einen Schlauch süßen Rum aus Goldhain. Bringt mir all diese Dinge, dann werde ich dafür sorgen, dass Ihr belohnt werdet.", completion = "Sehr gute Arbeit, &lt;Name&gt;! Ich weiß sehr wohl, welch weite Wege Ihr zurücklegen musstet, um diese beeindruckende Batterie an geistigen Getränken zu beschaffen. Aber meine Kunden haben endlich wieder Grund zur Zufriedenheit. \n\nMeine Frau ist eine ausgezeichnete Näherin. Bitte nehmt als Dank für Eure Dienste diesen von ihr gefertigten Umhang an.", rewards = "Ihr bekommt:\n\nFein gewebter UmhangEin mit Münzen prall gefüllter Geldbeutel"},
[117] = {title = "Donnerbräu", objective = "Bringt Grimbooze Donnerbräu 5 Hopfen, damit er sein besonderes Bier brauen kann.", description = "Ihr müsst eilen, <mein Freund/Madame>, sollt nicht ruhen, noch rasten, \nDenn für unser Lagerbier lohnt sich's zu hasten. \nEs schmeckt allen Männern, es schmeckt allen Frauen - \nDoch ich brauche noch Hopfen, um das Bier zu brauen.", progress = "Ihr müsst Euch jetzt eilen, sollt nicht ruhen, noch rasten, \ndenn für unser Lagerbier lohnt sich's zu hasten.\nEs schmeckt allen Männern, es schmeckt allen Frauen, \ndoch ich brauche noch Hopfen, um das Bier zu brauen.", completion = "Malz und Hefe, Gerste und Hopfen \nUnd unser Bier wird zum edelsten Tropfen. \nIhr braucht nicht zu bitten, ich geb Euch das Gebräu: \nHier habt Ihr Lagerbier vom alten Donnerbräu!", rewards = "Ihr bekommt:\n\nFässchen Donnerbräu"},
[118] = {title = "Der Preis für Hufeisen", objective = "Bringt Verners Nachricht zu Schmied Argus nach Goldhain.", description = "Ich habe so viel Eisen dafür verwenden müssen, die Wachen von Stormwind auszurüsten, dass ich nicht mehr genug Eisen übrig habe, um die Pferde im Stall zu beschlagen!\n\nBringt diese Nachricht zu Schmied Argus nach Goldhain. Darin erkläre ich ihm mein Problem und bitte ihn um eine Lieferung Hufeisen.", progress = "Wie meint Ihr? Verner hat Euch geschickt, sagt Ihr? Na, dann gebt mir seine Nachricht. Und SPRECHT LAUTER!", completion = "Hehe, der alte Verner braucht also ein paar Hufeisen, wie?", rewards = "Ihr bekommt:\n\n"},
[119] = {title = "Zurück zu Verner", objective = "Kehrt zu Verner Osgood ins Rotkammgebirge zurück. Gebt ihm die Kiste mit Hufeisen.", description = "Gut, er soll seine 50 Hufeisen haben.\n\nHier sind sie, schön in eine Kiste verpackt und bereit zum Abmarsch. Sagt Verner, dass es ein Vergnügen war, mit ihm Geschäfte zu machen, und sagt ihm, dass er unbedingt die Nachricht lesen soll, die ich ihm an die Kiste geheftet habe!", progress = "Oh, gut, Ihr seid zurück! Habt Ihr die Hufeisen bekommen?", completion = "Vielen Dank, das hilft mir wirklich weiter.\n\nAber was haben wir denn da? Der Kiste liegt eine Nachricht bei, die hat wohl Argus mitgeschickt... WAS? Argus will, dass ich ihn BEZAHLE? Pah!\n\nNa gut, jedenfalls danke für Eure Hilfe, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[120] = {title = "Botschaft nach Stormwind", objective = "Magistrat Solomon hat Euch einen Bericht übergeben, der bei General Marcus Jonathan in Stormwind abgeliefert werden muss. Der Richter möchte, dass Ihr zu ihm zurückkehrt, sobald Ihr die Nachricht zugestellt habt.", description = "Wir leben in schwierigen Zeiten, <Klasse>. Unsere Ortschaft ist einer ständigen Belagerung ausgesetzt. Wenn wir keine Verstärkung bekommen, ist unsere Niederlage so gut wie besiegelt. Die Botschaft, die ich Euch nun anvertrauen werde, ist von äußerster Wichtigkeit. Bringt diesen Bericht unverzüglich zu General Marcus Jonathan nach Stormwind. Sobald Ihr die Nachricht abgeliefert habt, kehrt umgehend zu mir zurück und überbringt mir alle Neuigkeiten, ganz gleich, ob gut oder schlecht. \n\nDoch nun eilt!", progress = "Was bringt Ihr mir da?", completion = "Rührt Euch, &lt;Klasse&gt;.\n\nMagistrat Solomon ist ein guter Anführer, und seine Worte haben großes Gewicht für mich. Ich werde um eine Audienz beim König ersuchen und ihm die Lage verdeutlichen. Versichert dem guten Richter, dass er sich der Unterstützung der Armee von Stormwind gewiss sein kann. Ich werde Verstärkung entsenden, sobald Seine Majestät den Befehl dazu gibt.", rewards = "Ihr bekommt:\n\n"},
[121] = {title = "Botschaft nach Stormwind", objective = "Bringt General Marcus Jonathans Antwortschreiben nach Seenhain zu Magistrat Solomon.", description = "Während ich auf Antwort vom König warte, möchte ich, dass Ihr diesen Brief zu Magistrat Solomon bringt. \n\nWeggetreten, <Klasse>!", progress = "Sendet der General Nachricht? Ist Verstärkung unterwegs?", completion = "Ich danke Euch für die Zeit, die Ihr aufgewendet habt, &lt;Klasse&gt;. Für Eure Dienste an Seenhain und Stormwind belohne ich Euch mit diesen Münzen.\n\nWenn Ihr mich jetzt entschuldigen wollt, diese Depesche stellt mich vor ein gewisses Rätsel. Irgendetwas stimmt in unserem Königreich nicht. Ich fürchte, dies ist erst der Anfang des Kampfes, nicht dessen Ende.", rewards = "Ihr bekommt:\n\n"},
[122] = {title = "Bauchschuppen", objective = "Sammelt 6 Welpenbauchschuppen von schwarzen Großdrachenwelpen ein und bringt sie ins Rotkammgebirge zu Verner Osgood.", description = "Ich brauche einige Bauchschuppen von schwarzen Großdrachenwelpen, damit ich die Hufeisen bezahlen kann, die Argus mir aus Goldhain geschickt hat. Wenn Ihr mir 6 solcher Schuppen besorgt, dann kann ich mit einem Teil davon Argus bezahlen - und habe dann immer noch einen Rest übrig, aus dem ich etwas für Euch herstellen kann.\n\nSchwarze Großdrachenwelpen fliegen häufig über das Gebiet südlich von Seenhain, aber sie wandern auch gern herum. Haltet einfach die Augen offen und jagt sie, wenn Ihr sie seht.", progress = "Ich weiß, dass dieser Gierhals Argus jemanden schicken wird, um die Schuppen für ihn einzutreiben, wenn ich sie ihm nicht bald von mir aus gebe. Habt Ihr die Schuppen schon gefunden?", completion = "Danke! So werde ich meine Schulden Argus gegenüber los.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchwarzwelpenstiefelSchwarzwelpenhandschuhe\n\nIhr bekommt außerdem:\n\n"},
[123] = {title = "Der Sammler", objective = "Begebt Euch zu Marshal Dughan nach Goldhain und gebt ihm den Zeitplan des Sammlers.", description = "Bei der Notiz handelt es sich um eine Tabelle mit Daten und Zeiten, zu denen jemand, der in der Notiz nur als \"der Sammler\" bezeichnet wird, je eine Lieferung Gold aus den Minen des Waldes von Elwynn erhalten soll.\n\nAus dem Plan geht hervor, dass sich der Sammler anscheinend in der Nähe vom Brackwell-Kürbisbeet in Ost-Elwynn aufhält.\n\nDas klingt, als sei es wichtig. Ihr solltet Marshal Dughan in Goldhain davon berichten.", progress = "Was?!? Schon seit Monaten arbeiten unsere Leute nicht mehr in den Minen von Elwynn!\n\nZeigt mir mal diese Notiz, die Ihr da habt...", completion = "Hm... Ich habe von diesem \"Sammler\" schon gehört, aber ich weiß nicht, für wen er arbeitet. Vielen Dank für diesen Zeitplan. Er wird uns dabei helfen, das Rätsel zu lösen.", rewards = "Ihr bekommt:\n\n"},
[124] = {title = "Das Bellen der Gnolle", objective = "Tötet 10 Schläger der Rotkammgnolle und 8 Mystiker der Rotkammgnolle und kehrt anschließend zu Verner Osgood zurück.", description = "Als ob Orc-Angriffe nicht genug wären! Jetzt schleichen auch noch Gnoll-Schläger und Gnoll-Mystiker auf dem Hügelkamm nördlich von meinem Stall herum und fallen meine Pferde an, wenn diese sich auch nur etwas zu weit vom Stall entfernen...\n\nWenn Ihr diese Gnolle beseitigen könntet, wären meine Pferde und ich Euch sehr dankbar.", progress = "Meine Pferde sind immer noch nervös und nachts höre ich immer noch dieses verfluchte Wolfsgeheul. Bitte tut etwas gegen diese Gnolle, <Name>!", completion = "Danke für all Eure Hilfe, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[125] = {title = "Die verlorenen Werkzeuge", objective = "Großknecht Oslow aus Seenhain möchte, dass Ihr seinen Werkzeugkasten vom Grunde des Immerruhsees heraufholt.", description = "Ich könnte hier wirklich etwas Hilfe gebrauchen, <Name>. Jetzt, wo die Stadt belagert wird, bekommen wir hier nur schwer Nachschub. Meine Werkzeuge sollten mit dem Karren von Goldhain aus angeliefert werden, aber die Brücke wurde in die Luft gejagt. Also legten wir die Werkzeuge in ein Boot, aber die Orcs beschossen es mit einem Katapult und trafen auch noch. Na, und bei meinem Pech ist mein Werkzeugkasten natürlich geradewegs bis auf den Grund des Sees gesunken.\n\nWenn Ihr mir meinen Werkzeugkasten wiederbeschafft, <Name>, dann soll es Euer Schaden nicht sein.", progress = "Habt Ihr meine Werkzeuge finden können?", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;! Ich hätte nie gedacht, dass ich diese Werkzeuge jemals wiedersehen würde.", rewards = "Ihr bekommt:\n\nMittleres Rüstungsset"},
[126] = {title = "Geheul in den Hügeln", objective = "Bringt Jaulers Tatze nach Seenhain zu Verner Osgood.", description = "Die Gnolle sind immer noch da draußen, <Name>. Ich kann sie bellen hören, wenn sie in den Hügeln oberhalb von Seenhain jagen. Und das Geheul eines Gnolls ist lauter als das aller anderen - das von Jauler, ihrem Anführer.\n\nTötet Jauler und vertreibt sein Rudel in alle vier Winde! Bringt mir seine Tatze zum Beweis.\n\nAber seid vorsichtig! Dieser Gnoll ist nicht umsonst der Anführer seines Rudels. Er ist kein einfacher Köter...", progress = "Jauler ist gefährlich, <Name>. Wenn Ihr Euch ihm noch nicht gewachsen fühlt, dann verstehe ich das.", completion = "Nochmals danke für Eure Hilfe. Die Armee von Stormwind ist so sehr mit den Orcs beschäftigt, dass sie nicht genügend Truppen hat, um das Rotkammgebirge vor kleineren Bedrohungen wie den Gnollen zu beschützen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRing des eisernen WillensGoldene Milizstiefel\n\nIhr bekommt außerdem:\n\n"},
[127] = {title = "Fischhandel", objective = "Bringt 10 gefleckte Sonnenfische nach Seenhain zu Dockmeister Baren.", description = "Der Immerruhsee ist für seinen gefleckten Sonnenfisch berühmt. Die Nachfrage nach diesen Fischen ist enorm hoch - und ich habe bald keine mehr vorrätig!\n\nBringt mir 10 Stück, dann werden wir uns schon handelseinig werden. Und wenn Ihr nicht selbst angeln möchtet oder könnt - na ja, vielleicht bekommt Ihr die Fische ja von den Murlocs!", progress = "Ihr habt wohl'n paar Sonnenfische für mich, hm?", completion = "Schön, mit Euch Geschäfte zu machen, Kumpel!", rewards = "Ihr bekommt:\n\nMurlocflossensuppeRezept: MurlocflossensuppeLebertran"},
[128] = {title = "Kopfgeld auf die Blackrocks", objective = "Tötet 15 Helden der Blackrock, dann erhaltet Ihr von Wache Howe aus Seenhain eine Belohnung.", description = "Der Blackrockklan muss vernichtet werden. Der Feind ist in unser Land eingedrungen. Diese Berge unterliegen der Oberhoheit des Königs von Stormwind. Aus bestimmten Quellen haben wir erfahren können, dass die Anführer jeder Einheit im Klan \"Helden\" genannt werden. Ihr findet sie in ihrem Lager im Norden, ein kleines Stück westlich von der Straße, die in die brennende Steppe führt.\n\nMagistrat Solomon möchte diese garstigen Bestien tot sehen. Erschlagt 15 Helden der Blackrock und kehrt zu mir zurück.", progress = nil, completion = "Wie ich sehe, habt Ihr tapfer gegen den Blackrockklan gekämpft, &lt;Klasse&gt;. Ihr habt unserem Ort wahrlich einen großen Dienst erwiesen.", rewards = "Ihr bekommt:\n\n"},
[129] = {title = "Ein geschenktes Mittagessen", objective = "Bringt Parkers Mittagessen zu Wache Parker. Er ist auf der Straße nach Dunkelhain auf Patrouille.", description = "Könntet Ihr mir einen Gefallen tun? Ich habe für Wache Parker ein Mittagessen gemacht, aber er ist gerade auf Patrouille unterwegs... Er ist groß und stark und noch dazu eine Wache von Stormwind, also kann er auf sich selbst aufpassen, aber ich bin nur eine kleine Stadtbewohnerin - für mich ist das da draußen viel zu gefährlich!\n\nWenn Ihr ihm also sein Mittagessen bringt und anschließend wieder herkommt, dann bekommt Ihr auch ein Mittagessen von mir - umsonst! Parker patrouilliert die Straße, die in den Dämmerwald führt.", progress = "So, Darcy hat mir ein Mittagessen geschickt, wie? Sie hat wirklich ein gutes Herz. Na, dann mal her damit!", completion = "Vielen Dank, das Essen hatte ich jetzt wirklich nötig. Seenhain gegen die Orcs und Gnolle zu beschützen strengt ganz schön an.", rewards = "Ihr bekommt:\n\n"},
[130] = {title = "Besuch im Kräuterladen", objective = "Sprecht mit der Kräuterkundigen des Rotkammgebirges, Martie Jainrose.", description = "Könnt Ihr Darcy ein paar Blumen von mir bringen, wenn Ihr wieder zu ihr geht? Die Blumen bekommt Ihr im Kräuterladen von Seenhain, am westlichen Ende des Ortes.\n\nAber wenn Ihr die Blumen holt, dann sagt Martie, der Kräuterkundigen, nicht, für wen sie bestimmt sind oder wer Euch beauftragt hat, ja?", progress = nil, completion = "Ihr braucht einen Blumenstrauß? Ihr seid noch nicht sehr lange in der Stadt - habt Ihr Euch etwa schon eine Liebste angelacht?\n\nIch weiß, es gehört sich nicht, so neugierig zu sein, aber ich finde es einfach schön, dass Liebe in der Luft liegt... vor allem in gefährlichen Zeiten wie diesen.", rewards = "Ihr bekommt:\n\n"},
[131] = {title = "Narzissen für eine Dame", objective = "Gebt Darcy den Narzissenstrauß.", description = "Hier habt Ihr Euren Blumenstrauß. Ich habe Narzissen für Euch ausgesucht. Narzissen sind meine Lieblingsblumen.", progress = "Da seid Ihr ja wieder, <Name>. Hat Parker das Mittagessen geschmeckt, das ich ihm geschickt habe?", completion = "Die Blumen sind wunderschön! Ich kann es kaum erwarten, sie ins Wasser zu stellen.\n\nAber wartet mal... das sind ja die Lieblingsblumen von Martie! Parker hat Euch doch wohl nicht etwa zu diesem missgünstigen Drachen geschickt, um die Blumen zu besorgen! Ihr habt ihr doch hoffentlich nicht gesagt, für wen die waren, oder? Falls doch, dann würde es mich nicht wundern, falls Martie die Blumen irgendwie vergiftet hätte.\n\nAber da könnt Ihr ja nichts dafür. Vielen Dank - und hier habt Ihr auch Euer Essen.", rewards = "Ihr bekommt:\n\nSautierter Sonnenfisch"},
[132] = {title = "Die Bruderschaft der Defias", objective = "Bringt Wileys Nachricht nach Westfall zu Gryan Stoutmantle.", description = "Was ich Euch jetzt erzähle, könnte mich das Leben kosten. Die Bande der Defias plant irgendwas Großes. Das Letzte, was ich gehört habe, war, dass sie mit unterschiedlichen Gnollen, Kobolden und sogar Goblins zusammenarbeiten.\n\nBringt Stoutmantle diese Nachricht. Darin steht alles, was ich zu dem Thema sagen kann.", progress = "Schön, dass Ihr zurück seid, <Name>. Was hatte Wiley zu seiner Verteidigung zu sagen?", completion = "Pah! Ich hätte den Halunken verfaulen lassen sollen, als ich die Chance dazu hatte. Aber diese Informationen sind von äußerster Wichtigkeit. Gute Arbeit.", rewards = "Ihr bekommt:\n\n"},
[133] = {title = "Ein Ghulbildnis", objective = "Sammelt 7 Ghulrippen und bringt sie zu Calvinius in seiner Hütte.", description = "Ich wohne so weit weg von der Stadt und dem Schutz, den sie bietet, dass es ein Wunder ist, dass die Ghuls und die wandelnden Toten mich noch nicht aufgefressen haben! Tatsächlich hat erst gestern ein Rudel Knochenkauer gegen die Wände meines Hauses gehämmert.\n\nIch möchte ein Bildnis herstellen - eine Art \"Vogelscheuche\", nur für Ghuls. Dafür brauche ich ein paar Ghulrippen. Die bekommt Ihr von Fleischfressern, Knochenkauern, Hirnfressern, Verfaulten und Seuchenverbreitern.\n\nWenn Ihr mir die Rippen beschafft, bezahle ich Euch in barer Münze.", progress = "Ich glaube, hinter dem Haus treibt sich ein Rudel Ghule herum - je schneller ich das Bildnis aufstelle, desto besser! Habt Ihr die Ghulrippen für mich?", completion = "Ah, danke! Die sind genau richtig für mein Vorhaben.", rewards = "Ihr bekommt:\n\n"},
[134] = {title = "Ogerdiebe", objective = "Bringt Calvinius' Kiste zu Calvinius.", description = "Vor ein paar Wochen wurde ich von einer Bande Ogern angegriffen, als ich draußen Kräuter sammelte, ziemlich weit von meinem Haus entfernt. Ich lief davon und musste eine Kiste mit wertvollen Werkzeugen und Kräutern zurücklassen.\n\nNachdem sie mich vertrieben hatten, stolzierten die Oger zurück zum Ogerhort im südlichen Dämmerwald. Ich bin mir sicher, dass meine Kiste irgendwo in der Nähe des Hügels sein muss.\n\nBitte, <Name>, beschafft mir diese Kiste wieder, denn sie fehlt mir sehr.", progress = "Habt Ihr meine Kiste? Wenn ja, dann gebt sie mir schnell, ich bitte Euch!", completion = "Dank dem Toten- ähm, ich danke EUCH, &lt;Name&gt;! Ihr habt Euch Eure Belohnung mehr als verdient.\n\nAha! Oh Glück! Glückliche Nächte können kommen!", rewards = "Ihr bekommt:\n\n"},
[135] = {title = "Die Bruderschaft der Defias", objective = "Bringt Wileys Nachricht nach Stormwind zu Mathias Shaw.", description = "Ich möchte zu gern wissen, was Wiley meinte, als er die Steinmetze erwähnte. Vielleicht ist ihm da nur etwas rausgerutscht. Könnten die Defias irgendwas mit den Steinmetzen zu tun haben? Nur ein Mann weiß das mit Sicherheit: Mathias Shaw, Kopf von SI:7. Zeigt ihm Wileys Nachricht und stellt fest, ob er noch etwas zu diesem immer verzwickter werdenden Rätsel beitragen kann. Falls Ihr Probleme habt, Shaw zu finden, seht in der Kaserne in der Altstadt nach.", progress = "Was wollt Ihr von mir? Ich bin ein viel beschäftigter Mann...", completion = "Diese Angelegenheit ist vermutlich komplizierter, als Stoutmantle ahnt.", rewards = "Ihr bekommt:\n\n"},
[136] = {title = "Käpt'n Sanders Versteckter Schatz", objective = "Findet Käpt'n Sanders Schließkiste und durchsucht sie, um den nächsten Hinweis zu erhalten.", description = "Wenn Ihr das hier lesen tut, dann heißt das, dass der alte Käpt'n Sander in den Fluten begraben is'. Also tut mein Schatz jetz' Euch gehör'n, Ihr braucht bloß den Hinweisen folgen. \n\nErst müsst Ihr ma' meine Schließkiste finden. Wahrscheinlich is' die jetz' da an der Westküste von Westfall in der Nähe von dem Schiffswrack schon halb im Sand verschwunden. 's gibt da an der Küste massig Schiffswracks, aber bloß einen rostigen Anker. Wenn Ihr den Anker finden tut, dann habt Ihr auch meine Schließkiste gefunden. Da müsst ihr reingucken, denn da steht der nächste Hinweis drin.", progress = nil, completion = "Langsam und quietschend öffnet sich die Schließkiste. Erst scheint es, als bestünde ihr Inhalt allein aus Wasser und Sand. Aber halt! Ein kleiner Krebs huscht heraus, der einen Hinweis auf den Schatz in seinen Scheren trägt!", rewards = "Ihr bekommt:\n\n"},
[138] = {title = "Käpt'n Sanders versteckter Schatz", objective = "Findet das alte Fass in der Nähe des verfallenen Kamins und durchsucht es nach Eurem nächsten Hinweis.\n\nBereitgestellter Gegenstand: \n", description = "Der Hinweis auf den Schatz lautet folgendermaßen: Gut gemacht, Kumpel! Jetz' müsst Ihr Euch imma nach Ost'n halten. Östlich von der Straße die Steilhänge hoch. Schaut Euch nach so 'nem ollen verfallenen Kamin nahe bei der Straße um. Dort findet Ihr'n altes Fass mit Eurem nächsten Hinweis drin.", progress = nil, completion = "Gut gemacht! Das war der nächste Schritt auf der Schatzsuche.", rewards = "Ihr bekommt:\n\n"},
[139] = {title = "Käpt'n Sanders Versteckter Schatz", objective = "Durchsucht den leeren Henkelkrug neben der Windmühle nach dem nächsten Hinweis.\n\nBereitgestellter Gegenstand: \n", description = "Als Ihr das Fass durchsucht, findet Ihr ein weiteres Stück Pergament. Darauf steht: Also, von dem Fass dort müsst Ihr Euch nach Norden halten tun. Un' dann geht Ihr immer der Nase nach schnurstracks geradeaus, bis Ihr den leeren Henkelkrug sehen tut, der da irgendwo bei so 'ner einzeln stehenden Windmühle oben auf dem Steilhang über dem Meer liegt. Wenn Ihr Euch bei dem Henkelkrug umguckt, dann findet Ihr vielleicht sogar, was Ihr sucht.", progress = nil, completion = "Ihr seid bei Eurer Schatzsuche auf dem richtigen Weg!", rewards = "Ihr bekommt:\n\n"},
[140] = {title = "Käpt'n Sanders Versteckter Schatz", objective = "Findet Käpt'n Sanders Truhe und öffnet sie. Darin befindet sich Eure Belohnung.\n\nBereitgestellter Gegenstand: \n", description = "Und tatsächlich, ganz unten, fast am Boden des alten Henkelkruges findet sich der nächste Hinweis auf Sanders Schatz. An manchen Stellen ist die Tinte verwischt und das Papier riecht nach Whisky, aber zum Teil kann man den Text noch lesen: Jetz', wo Ihr mein'n alten Whiskykrug gefunden habt, habt Ihr den Schatz schon so gut wie in der Tasche. Von der Flasche aus müsst Ihr Euch einfach nach Westen halten und runter zum Strand geh'n. Und dann heißt es schwimmen! Schwimmt schnurstracks nach Westen, bis Ihr an der Insel seid, da wo meine Schatztruhe drauf is'!", progress = nil, completion = "Die Scharniere der alten Truhe sind rostig, aber sie funktionieren noch. Ihr brecht die Truhe auf und nehmt die Beute heraus.\n\nHerzlichen Glückwunsch!", rewards = "Ihr bekommt:\n\nSilberbarrenKäpt'n Sanders HemdKäpt'n Sanders SchärpeKäpt'n Sanders Beutetasche"},
[141] = {title = "Die Bruderschaft der Defias", objective = "Bringt Shaws Bericht nach Westfall zu Gryan Stoutmantle.", description = "Die Gilde der Steinmetze wurde von einem Mann namens Edwin van Cleef geführt. Van Cleef war dafür verantwortlich, dass Stormwind wieder aufgebaut wurde, nachdem die Orcs es im Ersten Krieg dem Boden gleichgemacht hatten. Anscheinend waren van Cleef und seine Leute nicht zufrieden damit, wie der König sie behandelte, nachdem der Wiederaufbau vollendet war. Das könnte den einen oder anderen Sachverhalt erklären.\n\nIch habe Eurem Meister in Westfall einen ausführlicheren Bericht geschrieben. Bringt ihn sofort zu ihm!", progress = "Konnte Meister Shaw etwas Licht auf die Dinge werfen?", completion = "Edwin van Cleef... dieser Name ist mir wohl bekannt. Ein so talentierter und fleißiger Mann soll zu einem solchen Schurken geworden sein?... Der Gedanke erschreckt mich und ich brauche weitere Beweise, ehe ich das glaube.", rewards = "Ihr bekommt:\n\n"},
[142] = {title = "Die Bruderschaft der Defias", objective = "Spürt den Boten der Defias in Westfall auf und bringt die Nachricht, die er bei sich hat, zu Stoutmantle.", description = "Wir müssen herausfinden, wo genau sich das Versteck der Defias befindet. <Name>, meine Späher berichten mir, dass ein Bote der Defias auf der Straße zwischen Moonbrook, dem Goldküstensteinbruch und dem Jangoschacht gesehen worden ist. Ich möchte, dass Ihr ihn fangt. Wenn er Widerstand leistet, tötet ihn und bringt mir alles, was er bei sich trägt.", progress = "Habt Ihr irgendetwas erfahren können, <Name>? Habt Ihr den Boten gefunden?", completion = "Dies beweist allerdings eindeutig, dass van Cleef das Kommando hat. Jetzt müssen wir nur noch herausfinden, wo die Bande der Defias sich versteckt hält.\n\nWährend Ihr fort wart, gab es hier einen Glücksfall. Wir haben einen Dieb gefasst, der Saldeans Wagen stehlen wollte. Er hat versprochen, uns zu dem Versteck zu führen, wenn wir im Gegenzug sein Leben verschonen. Ich möchte, dass Ihr den Verräter schützt, damit er uns das Versteck zeigen kann. Kehrt zu mir zurück, sobald Ihr den Ort gefunden habt.", rewards = "Ihr bekommt:\n\n"},
[143] = {title = "Botschaft nach Westfall", objective = "Magistrat Solomon möchte, dass Ihr sein Hilfegesuch nach Westfall zu Gryan Stoutmantle bringt.", description = "Irgendetwas stimmt mit der Armee von Stormwind nicht. Sie hätte längst mit einem größeren Aufgebot hier sein müssen. Doch Zeit ist ein Luxus, den wir nicht haben. Ich werde nicht dabeistehen und tatenlos zusehen, wie die Bewohner von Seenhain ihr Leben geben. Nein. Ich muss versuchen, von anderer Stelle her Hilfe zu gewinnen. Ich habe gehört, dass sich in Westfall eine Volksmiliz gebildet hat.\n\nBringt dieses Hilfegesuch ihrem Anführer, Gryan Stoutmantle. Vielleicht können Stoutmantles Männer uns hier unterstützen, bis der König Verstärkung schickt.", progress = "Seid gegrüßt, <Klasse>! Welcher Anlass führt Euch zur Volksmiliz?", completion = "Werter Bote, Ihr habt Eurem Meister wohl gedient.", rewards = "Ihr bekommt:\n\n"},
[144] = {title = "Botschaft nach Westfall", objective = "Kehrt mit Gryan Stoutmantles Antwort zu Magistrat Solomon zurück.", description = "Es schmerzt mich, Magistrat Solomons Schreiben zu lesen. Offensichtlich hat er von dem Krieg, der hier in Westfall tobt, keine Ahnung. Sonst wäre er nicht so naiv, Hilfe von der Miliz zu erwarten. Wenn Stormwind nicht auch uns im Stich gelassen hätte, dann hätte es keinen Grund gegeben, die Miliz ins Leben zu rufen.\n\nBringt Eurem Herrn im Rotkammgebirge diese Antwort, <Klasse>. Und lasst ihn wissen, dass mir das Herz schwer wird, wenn ich an all die tapferen Leute denke, die ihr Leben verloren haben.", progress = "Dürfen wir die Volksmiliz bald erwarten? Lassen Lord Stoutmantles Nachrichten Gutes erhoffen?", completion = "Ich muss schon sagen, dies klingt überhaupt nicht gut. Ich wusste nicht, dass die Lage, in der Stoutmantle sich befindet, der unseren hier in Seenhain nicht unähnlich ist. Was kann nur so wichtig sein, dass es die Armee von Stormwind davon abhält, dem Volk, das sie beschützen soll, zu Hilfe zu eilen? Aber ich sollte nicht laut grübeln.\n\nHier, Bote. Nehmt diese Münzen als Bezahlung für Eure Verdienste um die Stadt entgegen. Es wäre möglich, dass ich Eure Hilfe ein weiteres Mal benötige.", rewards = "Ihr bekommt:\n\n"},
[145] = {title = "Botschaft nach Dunkelhain", objective = "Magistrat Solomon möchte, dass Ihr einen Brief zu Lord Ebonlocke nach Dunkelhain bringt.", description = "Ein weiteres Mal brauche ich Eure Hilfe. Ich habe an Lord Ebonlocke geschrieben und ihn gebeten, seine gut ausgebildete Nachtwache hierher zu schicken, damit diese bei der Verteidigung von Seenhain hilft. Es ist von ausnehmender Wichtigkeit, dass diese Nachricht ihn so bald wie möglich erreicht. Doch Ihr müsst äußerste Vorsicht walten lassen. Ebonlocke ist der Bürgermeister von Dunkelhain, und das liegt im Herzen des Dämmerwalds. Entfernt Euch nicht von der Straße.", progress = "Es scheint mir, als wäret Ihr weit gereist, <Klasse>. Was ist Euer Begehr hier in Dunkelhain?", completion = "Ich danke Euch, dass Ihr die lange Reise hierher unternommen habt. Dies sind wirklich wichtige Informationen.", rewards = "Ihr bekommt:\n\n"},
[146] = {title = "Botschaft nach Dunkelhain", objective = "Kehrt mit Lord Ebonlockes Antwortschreiben zu Magistrat Solomon zurück.", description = "Wenn mir Magistrat Solomon nicht persönlich bekannt wäre, würde ich sagen, der Mann hat den Verstand verloren. Die Nachtwache nach Seenhain schicken, weil Stormwind die Hilfe verweigert? Die Nachtwache wurde gegründet, weil Stormwind uns verließ, als diese elende Magie langsam das Land überzog. Wenn ich meine Nachtwache jetzt fortschicke, dann würde diese Stadt vom Bösen überrannt werden, noch ehe die Wachen den Waldrand erreicht hätten.\n\nBringt Eurem Meister in Seenhain dieses Antwortschreiben.", progress = "Ah, gut, Ihr seid von Eurem Botengang zurück. Kann ich den Marshal informieren, dass die Nachtwache von Dunkelhain hierher unterwegs ist?", completion = "Beim Licht! Die Armee von Stormwind hat sich aus Westfall zurückgezogen und die Wache beschützt Dunkelhain nicht mehr? Hier ist Verrat im Spiel. Wie konnte dies geschehen? \n\nDoch ich vergaß, Euch für Eure Dienste zu belohnen, &lt;Klasse&gt;. Hier habt Ihr einige Münzen. Und nun entschuldigt mich. Etwas stimmt nicht in Stormwind und ich muss der Sache auf den Grund gehen.", rewards = "Ihr bekommt:\n\n"},
[147] = {title = "Menschenjagd", objective = "Findet den \"Sammler\" und tötet ihn, dann kehrt mit dem Ring des Sammlers zu Marshal Dughan zurück.", description = "Wenn der \"Sammler\" Gold aus unseren Minen entnimmt, dann bestiehlt er das Königreich! Führt den Sammler seiner gerechten Strafe zu und bringt mir den Ring, der in dem Abholplan, den Ihr mir gegeben habt, erwähnt wurde.\n\nIm Abholplan steht, dass der Sammler sich am Brackwell-Kürbisbeet versteckt hält. Dort solltet Ihr nach ihm suchen.", progress = "Habt Ihr den Sammler gefunden? Konntet Ihr herausfinden, für wen er arbeitet?", completion = "Ihr habt ihn gefunden? Gut gemacht, &lt;Name&gt;. Der wird in den Minen von Elwynn nichts mehr \"einsammeln\"!\n\nUnd dieser Ring, den Ihr gefunden habt, ist auch sehr interessant. Es ist ein Gildenring der alten Steinmetzgilde aus Stormwind. Warum hat ein nichtswürdiger Dieb den Ring einer Handwerkergilde in seinem Besitz und warum treibt die Bruderschaft der Defias Geld aus unseren Minen ein?\n\nDas sind schwierige Fragen, und ich hoffe nur, wir werden eines Tages die Antworten darauf finden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nStormwindkettenpanzerhandschuheElastischer Handgelenksschutz\n\nIhr bekommt außerdem:\n\n"},
[148] = {title = "Lieferung aus Dunkelhain", objective = "Sprecht mit Madame Eva.", description = "Ach, was soll ich armer, alter Mann nur machen? Ich brauche einige Vorräte aus Dunkelhain, aber das Dorf ist so weit weg und ich bin so alt und schwach... ich würde die Reise niemals überstehen.\n\nKönnt Ihr nach Dunkelhain reisen und mir etwas Geisterhaarfaden mitbringen? Den bekommt Ihr im Haus von Madame Eva am Dorfplatz von Dunkelhain.", progress = nil, completion = "So, Ihr braucht also Geisterhaarfaden, hm? Ich habe leider keinen mehr auf Lager, aber ich kann Euch welchen herstellen - wenn Ihr mir das Geisterhaar besorgt.", rewards = "Ihr bekommt:\n\n"},
[149] = {title = "Geisterhaarfaden", objective = "Bringt der blinden Mary den spektralen Kamm.", description = "Es gibt da einen armen, traurigen Geist, die blinde Mary, die in einem alten Bauernhaus in den Hügeln südlich von Dunkelhain spukt.\n\nHier, nehmt diesen spektralen Kamm und bittet die blinde Mary, sich die Haare zu kämmen. Bringt mir anschließend den Kamm zurück, dann entnehme ich ihm das Geisterhaar, das ich für den Faden brauche.\n\nUnd seht Euch vor, denn in der Nähe dieses Hauses lauern üble Dinge...", progress = "<Schluchz> Oh bitte, seht mich nicht an! Ich habe mir diese Augen mit meinen eigenen Händen herausgerissen, aber Euren Blick kann ich immer noch spüren!\n\nIch sehe grauenhaft aus! Grauenhaft! Ich flehe Euch an, wendet Euren Blick ab!", completion = "Was ist das? Ein Kamm? Er ist wunderschön! Und er gleitet durch mein Haar, als wäre es nicht so entsetzlich verklebt und strähnig, wie es ist.\n\nAch, wenn ich doch nur einen Spiegel hätte...", rewards = "Ihr bekommt:\n\n"},
[150] = {title = "Murlocwilderer", objective = "Bringt 8 Murlocflossen nach Seenhain zu Dockmeister Baren.", description = "Die Murlocs werden zu einem Problem. Große Gruppen der Fischwesen werfen entlang der Ufer des Immerruhsees Anker und fischen, was das Zeug hält! Sie müssen verschwinden, ehe sie den ganzen See leer gefischt haben.\n\nGeht Murlocs jagen! Bringt mir 8 ihrer Flossen, dann habe ich vielleicht etwas für Euch...", progress = "Habt Ihr die Flossen? Sputet Euch - diese Murlocs müssen vom See vertrieben werden!", completion = "Gut gemacht, &lt;Name&gt;. Ich hoffe, diese Murlocs haben Euch nicht zu viele Schwierigkeiten bereitet.\n\nEs ist seltsam, dass man sie so weit vom Meer entfernt sieht. Ich frage mich, ob sie hier sind, weil sie vor etwas davonlaufen...", rewards = "Ihr bekommt:\n\nZwergische Angelrute"},
[151] = {title = "Die arme Graumähne", objective = "Verna Furlbrow in Westfall möchte, dass Ihr ihr 8 Hände voll Hafer bringt.", description = "Die arme Graumähne! Das arme Pferd ist völlig entkräftet nach all der Arbeit, die wir ihm aufgebürdet haben. Ich habe es gefüttert, ehe wir den Hof verließen, aber wir haben natürlich nicht damit gerechnet, dass uns der Wagen kaputtgehen würde. Wenn Ihr der Stute ein paar Hände voll Hafer vom Feld bringen könntet, wäre ich Euch dankbar.\n\nIch wette, es lässt sich rund um die Höfe in Westfall etwas Hafer finden; Ihr müsst nur diesen entsetzlichen Maschinen aus dem Weg gehen, die hier alles übernommen haben. Es gibt einige Höfe südwestlich von hier.", progress = "Graumähne kann sich kaum noch auf den Beinen halten. Habt Ihr zufällig etwas Hafer für sie finden können?", completion = "Vielen herzlichen Dank, &lt;Name&gt;! Da wird sich die gute Graumähne aber freuen!", rewards = "Ihr bekommt:\n\nGraumähnes DeckeGraumähnes Futtersack"},
[152] = {title = "Ärger an der Küste", objective = "Tötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel sowie 7 Küstenläufer und kehrt dann zu Captain Grayson beim Leuchtturm von Westfall zurück.", description = "Die vielen Schiffswracks entlang der Küste sind Euch ja vermutlich schon aufgefallen. Das große Meer ist überaus tückisch. Die Küste von Westfall muss freigehalten werden, damit die Seeleute sicher sind, wenn sie unsere Ufer erreichen. Aber die Murlocs sind ein Problem.\n\nTötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel und 7 Küstenläufer, dann sorge ich dafür, dass Ihr belohnt werdet.", progress = "Tötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel und 7 Küstenläufer, dann sorge ich dafür, dass Ihr belohnt werdet.", completion = "Gut gemacht, &lt;Name&gt;. Ihr habt ein ziemliches Talent für den Kampf. Dank Euch ist die Küste Westfalls jetzt sicherer als zuvor.", rewards = "Ihr bekommt:\n\n"},
[153] = {title = "Rote Lederkopftücher", objective = "Bringt 15 rote Lederkopftücher auf die Späherkuppe zu Späher Galiaan.", description = "Die Defias sind ständig in Bewegung. Ich überwache ihre Aktivitäten jetzt schon seit einiger Zeit. Und dabei habe ich festgestellt, dass viele Bandenmitglieder an den roten Lederkopftüchern zu erkennen sind, die sie tragen.\n\nBringt mir 15 dieser Kopftücher, dann werde ich dafür sorgen, dass Ihr belohnt werdet.", progress = "Bringt mir 15 rote Lederkopftücher, ich werde Euch gut dafür bezahlen.", completion = "Gute Arbeit, &lt;Volk&gt;. Bitte nehmt einen dieser Gegenstände als Bezahlung für Eure harte Arbeit an.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVolksmiliz-UmhangSchienbeinschützer der VolksmilizGamaschen der Volksmiliz\n\nIhr bekommt außerdem:\n\n"},
[154] = {title = "Rückkehr mit dem Kamm", objective = "Bringt den Geisterhaarkamm zu Madame Eva nach Dunkelhain.", description = "NEIN!!!!!\n\nNehmt ihn weg, nehmt diesen Kamm weg!\n\nIch bin ein Monster und niemand wird mich jemals wieder für schön halten!", progress = "Ich kann spüren, dass Ihr die blinde Mary getroffen habt. Habt Ihr auch meinen Kamm?", completion = "Damit kann ich eine Rolle Geisterhaarfaden herstellen und es bleiben sogar noch einige Haare übrig. Hier habt Ihr einige Münzen für diese zusätzlichen Haare.", rewards = "Ihr bekommt:\n\n"},
[155] = {title = "Die Bruderschaft der Defias", objective = "Eskortiert den Verräter der Defias zum Geheimversteck der Defiasbruderschaft. Sobald der Verräter der Defias Euch gezeigt hat, wo sich van Cleef und seine Männer aufhalten, kehrt Ihr mit der Information zu Gryan Stoutmantle zurück.", description = "Stoutmantle denkt also wirklich, ein <Volk> wie Ihr könne mich beschützen? Tja, Ihr werdet wohl reichen müssen. Bringt am besten ein paar Freunde mit. \n\nIhr wisst ja, wie's läuft, oder? Ihr haltet mir den Rücken frei und ich bringe Euch zum Versteck der Defias. Aber Ihr solltet besser in meiner Nähe bleiben, denn die Bande der Defias will jetzt meinen Kopf. Wenn die mich mit Euch sehen, werden sie versuchen, mich umzubringen.\n\nSagt mir einfach Bescheid, wenn Ihr und irgendwelche Freunde, die Ihr noch zusammentrommeln könnt, bereit seid loszuziehen.", progress = nil, completion = "Ganz ausgezeichnet, &lt;Name&gt;! Jetzt, wo wir wissen, wo er sich versteckt, gehört van Cleef so gut wie uns.", rewards = "Ihr bekommt:\n\n"},
[156] = {title = "Das Sammeln von Faulblüten", objective = "Sammelt 8 Faulblüten und bringt sie nach Dunkelhain zu Schankwart Smitts.", description = "Wenn Ihr mir ein paar Faulblüten bringt, dann kann ich Euch einen Kessel Zombiesaft brauen.\n\nFaulblüten wachsen an seltsamen Orten. Vor allem, habe ich gehört, findet man sie in den Schädeln von Skelettschrecken und Skelettsatanskreaturen - nicht, dass ich selbst schon mal nah genug dran war, um nachzusehen!\n\nDer Friedhof von Rabenflucht und die stillen Gärten sind voll von diesen Skeletten. Wenn Ihr die auf Eurer Suche nach den Faulblüten auch noch dezimiert, dann schlagt Ihr zwei Fliegen mit einer Klappe, und ganz Dunkelhain wäre Euch dankbar.", progress = "Hallo, <Name>. Habt Ihr die Faulblüten für mich?", completion = "Oh gut, Ihr habt die Faulblüten bekommen. Und ich werde Althea Ebonlocke von der Nachtwache erzählen, dass Ihr etliche Skelette getötet habt.\n\nDie Bevölkerung von Dunkelhain zu beschützen, stellt für die Nachtwache eine schwere Aufgabe dar und das Wissen, dass es auch andere gibt, die die Flut der Unwesen einzudämmen helfen, ist für sie eine willkommene Nachricht.", rewards = "Ihr bekommt:\n\n"},
[157] = {title = "Abliefern des Fadens", objective = "Bringt Calvinius den Geisterhaarfaden in seine Hütte nördlich des Friedhofs von Rabenflucht.", description = "Hier ist Euer Faden, <Name>. Man kann tausend Dinge damit machen, zum Beispiel böse Geister binden oder unbelebte Gegenstände mit Leben erfüllen.", progress = "Ich brauche den Geisterhaarfaden, um ihn quer über meine Tür und meine Fenster zu spannen. Das hält unliebsame Geister fern. Habt Ihr ihn für mich besorgt?", completion = "Wunderbar! Das ist gerade richtig...\n\nHier, bitte, mein guter &lt;Name&gt;, nehmt dies als Bezahlung für Eure ehrenhafte Tat.", rewards = "Ihr bekommt:\n\n"},
[158] = {title = "Zombiesaft", objective = "Sprecht mit Schankwart Smitts.", description = "Ich brauche eine Flasche eines bestimmten Schnapses, und zwar Zombiesaft. Schankwart Smitts aus der Taverne Zum roten Raben in Dunkelhain sollte welchen haben.\n\nUnd bitte sputet Euch, <Name>. Die Nächte sind kalt und ich brauche den Schnaps, um meine Adern wieder mit Feuer zu erfüllen!", progress = nil, completion = "Ihr braucht etwas Zombiesaft, wie? Hmm, das Zeug ist ziemlich stark - ich werde nicht oft danach gefragt.", rewards = "Ihr bekommt:\n\n"},
[159] = {title = "Saftlieferung", objective = "Bringt Calvinius den Zombiesaft in seine Hütte.", description = "Hier habt Ihr Euren Zombiesaft...\n\n... aber passt mir mit dem Zeug auf. Es ist stark genug, um die Toten zu erwecken!", progress = "Ich brauche den Zombiesaft, um mich in diesen dunklen, kalten Nächten warm zu halten. Habt Ihr ihn für mich besorgt?", completion = "Seid tausendmal bedankt, &lt;Name&gt;! Ihr erwärmt das Herz eines alten Mannes mit Eurer Naiv... ääh... mit Eurer Freundlichkeit!\n\nHier, bitte schön, mein Freund, nehmt dies als ein Zeichen meiner Dankbarkeit.", rewards = "Ihr bekommt:\n\n"},
[160] = {title = "Ein Brief für den Bürgermeister", objective = "Bringt Calvinius' Brief zu Ello Ebonlocke, dem Bürgermeister von Dunkelhain.", description = "Bringt diese Nachricht zu Ello Ebonlocke, dem Bürgermeister von Dunkelhain.\n\nEr und ich sind alte Freunde, und wenn er den Zettel liest und herausfindet, was Ihr für mich getan habt... dann freut er sich bestimmt genauso sehr, wie ich das tue! Hahahaha!", progress = "Calvinius...? Ich kenne niemanden dieses Namens. Ihr sagt, Ihr habt einen Brief für mich von diesem Calvinius?\n\nNa, dann lasst mal sehen...", completion = "&lt;Ello sieht sich den Brief an...&gt;\n\nWas für eine Sprache ist das? Sie sieht uralt aus... ich kann sie nicht lesen.", rewards = "Ihr bekommt:\n\n"},
[161] = {title = "Eine dunkle Bedrohung", objective = "Chefingenieur Hinderweir möchte, dass Ihr das sonderbar riechende Pulver nach Dun Modr zu Ashlan Stonesmirk, dem Sprengstoffexperten, bringt.", description = "Falls mein Verdacht sich bestätigt, ist dies eine Art Sprengpulver. Es muss von einem Sprengstoffexperten analysiert werden, damit wir genau wissen, mit was wir es hier zu tun haben. Ashlan Stonesmirk wurde dem Regiment zugeteilt, das Dun Modr und den Thandol-Übergang bewachen soll. Ihr müsst für mich eine schwierige und gefahrvolle Reise auf Euch nehmen, <Name>.\n\nReist durch das Algaz-Tor, folgt der Straße durch das Sumpfland und sucht Stonesmirk in Dun Modr auf. Folgt meinem Rat: Bleibt auf den Straßen und lasst Euch nicht zum Anhalten bewegen!", progress = "Habt Ihr was gesagt, Jungchen? Ich kann nix hören außer dem verdammten Dröhnen in den Ohren. Sagt mal, was habt Ihr denn da?", completion = "Ah ja, also da hat der Olle Hinderweir verdammt Recht, dass er sich Sorgen macht.", rewards = "Ihr bekommt:\n\n"},
[162] = {title = "Aufstieg der Silithid", objective = "Bringt den Insektenanalysebericht nach Darnassus zu Gracina Spiritmight.", description = "Ihr solltet mit diesem Bericht zu jemandem gehen, der ausreichend Kenntnis von solchen Dingen hat.\n\nIch kenne da diese Nachtelfen-Gelehrte namens Gracina Spiritmight. Sie hat viel Zeit mit dem Studium der Lebensformen verbracht, die in der Ökologie von Azeroth einzigartig sind, und sie ist noch dazu Historikerin! Wenn Euch jemand dabei helfen soll herauszufinden, was genau diese Bedrohung ausmacht, und noch viel wichtiger, wie sie zu stoppen ist, gebt ihr den Bericht. Wir werden die Hilfe brauchen.\n\nDas Letzte, was ich hörte, war, dass sie im Tempel des Mondes in Darnassus lebt.", progress = "Friede und Gelassenheit sei mit Euch, Fremdling. Warum habt Ihr mich heute aufgesucht?", completion = "Dieser Bericht... wir Nachtelfen kennen den Schrecken, der hier erwähnt wird. Fizzledowser hat gut daran getan, dies und Euch zu mir zu schicken.\n\nDiese Kreaturen werden die Tanariswüste schnell verzehren; sie stellen so ziemlich die größte Bedrohung dar, der wir uns je gegenübersehen werden. Macht Euch mit diesem Namen vertraut, &lt;Name&gt;: Silithid. Die hier erwähnten Insekten sind die Silithid und sie sind das Werkzeug einer der größten Bedrohungen, der sich die Horde und die Allianz gegenübersehen.\n\nWenn wir nur früher schon klug genug gewesen wären, das zu verstehen.", rewards = "Ihr bekommt:\n\n"},
[163] = {title = "Rabenflucht", objective = "Findet heraus, was in Rabenflucht umgeht.", description = "Irgendetwas stimmt nicht in Rabenflucht, <Name>. Calor schwört, dass jemand - oder etwas - in den Gebäuden dort umgeht. Zwei Nächte in Folge hat er jetzt schon gesehen, wie sich die Schatten bewegten, und in der Nacht vorher habe er Licht in einem der Fenster gesehen, sagte er.\n\nWenn Euch, wie Ihr sagt, die Sicherheit des Dämmerwalds am Herzen liegt, dann findet heraus, welches Monster in Rabenflucht umgeht.", progress = nil, completion = "Nein! Bitte tötet mich nicht! Ich bin's doch nur... Jitters! Sie sind überall... Ich kann ihnen nicht entkommen! Monster in Rabenflucht? N-n-n-nein... das kann gar nicht sein. Nur der harmlose Jitters.", rewards = "Ihr bekommt:\n\n"},
[164] = {title = "Lieferung an Sven", objective = "Liefert die Vorräte an Sven.", description = "Kennt Ihr Sven? Das ist mal ein Mann, der das Werk des Lichtes vollbringt! Er und seine Anhänger haben ein Lager am nordwestlichen Rand des Dämmerwalds.\n\nLeider sind sie so wenige, dass noch nicht einmal ein einziger Mann abkömmlich ist, um Vorräte aus der Stadt zu holen. Würdet Ihr diese Vorräte bei ihm abliefern?", progress = "Ihr seht ziemlich robust aus, <Klasse>. Wollt Ihr Euch unserem Kampf anschließen?", completion = "Diese Vorräte werden sich als äußerst nützlich erweisen. Wir wissen die Hilfe der Familie Carevin stets zu schätzen. Hier habt Ihr etwas für Eure Mühe.", rewards = "Ihr bekommt:\n\n"},
[165] = {title = "Der Einsiedler", objective = "Schaut in der Nähe des Friedhofs von Rabenflucht nach dem alten Mann in der Hütte.", description = "Es gab einmal einen alten Mann, der recht häufig in die Stadt kam, um Vorräte einzukaufen, aber ich habe ihn jetzt schon ziemlich lange nicht mehr gesehen. Er lebt draußen in einer Hütte, von der aus man den Friedhof von Rabenflucht überblicken kann, wenn ich mich recht erinnere. Vielleicht solltet Ihr einmal nachsehen gehen, ob dort alles in Ordnung ist.", progress = nil, completion = "Elaine Carevin? Hehe, ja, aber natürlich... die Carevins.\n\nDoch, doch, es ist alles in Ordnung, aber es ist inzwischen ziemlich schwer für mich, in die Stadt zu kommen. Die Straßen sind gefährlich und ich werde nicht jünger. Vielleicht könntet Ihr ja einem alten Mann ein paar Gefallen tun?", rewards = "Ihr bekommt:\n\n"},
[166] = {title = "Die Bruderschaft der Defias", objective = "Tötet Edwin van Cleef und bringt seinen Kopf zu Gryan Stoutmantle.", description = "Jetzt gibt es für Euch nur noch eine Aufgabe zu erledigen. Edwin van Cleef muss getötet werden. Zwar stimmt es mich traurig, einen Menschen zum Tode zu verurteilen, doch es ist zum Besten des Volkes von Westfall, wenn van Cleef ein für alle Mal aus dem Verkehr gezogen wird. Bringt mir den Kopf des Schurken, sobald die Tat getan ist.", progress = "Wie läuft die Jagd auf Edwin van Cleef?", completion = "Euer Mut ist bemerkenswert, &lt;Name&gt;. Die Volksmiliz dankt Euch für Eure Verdienste um das Volk von Westfall. Van Cleefs Tod bedeutet den Anfang vom Ende für die Bruderschaft der Defias. Hoffentlich wird schon bald wieder Frieden auf den Ebenen unseres schönen Landes herrschen.\n\nIch ziehe den Hut vor Euch, werter Herr!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWestfall-GaloschenTunika von WestfallStab von Westfall\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[167] = {title = "Oh Bruder...", objective = "Bringt Großknecht Thistlenettles Forscherliga-Abzeichen nach Stormwind zu Wilder Thistlenettle.", description = "Wir waren tief unten in einer großen Mine in Westfall, deren Eingang unter einer Scheune in Moonbrook versteckt lag. Keine Ahnung, wo dieses elende Diebesgesindel herkam. Egal, jedenfalls stürzte der Minentunnel über uns ein. Ich hab's nach draußen geschafft, aber die anderen ... na ja ... von den anderen hat seither niemand mehr etwas gehört.\n\nIhr seht aus, als könntet Ihr vielleicht etwas mehr Glück haben, wenn Ihr dort hineingeht. Wenn Ihr nach meinem Bruder suchen könntet, wäre ich Euch dankbar. Er trug immer sein Forscherliga-Abzeichen bei sich. Wenn Ihr ihn selbst nicht finden könnt, dann würde zumindest das Abzeichen mir etwas Seelenfrieden verschaffen.", progress = "Habt Ihr ein Lebenszeichen von meinem Bruder finden können? Besteht Hoffnung nach all dieser Zeit?", completion = "Also haben meine Befürchtungen sich bestätigt. Mein armer Bruder... Nun, ich danke Euch dafür, dass Ihr dieses Rätsel gelöst habt, selbst wenn die Lösung eine traurige war.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nRächer des Minenarbeiters"},
[168] = {title = "Die Suche nach Andenken", objective = "Beschafft 4 Gewerkschaftsausweise und bringt sie nach Stormwind zu Wilder Thistlenettle.", description = "Viele meiner Freunde starben an jenem schrecklichen Tag, als der Minentunnel einstürzte. Wenn Eure Abenteuer Euch in jenen Abschnitt der Mine in Moonbrook führen sollten, dann haltet doch bitte die Augen offen nach jedem Zeichen, anhand dessen man sie identifizieren könnte. Wenn Ihr zum Beispiel ihre Gewerkschaftsausweise finden solltet, so bringt sie mir, dann sehe ich zu, dass ihre Familien informiert werden und damit wenigstens eine Art Schlussstrich unter diesen schrecklichen Unfall ziehen können.", progress = "Konntet Ihr einige der Gewerkschaftsausweise meiner alten Kameraden wiederfinden?", completion = "Danke, dass Ihr die Ausweise beschafft habt, &lt;Name&gt;. Eure Anstrengungen helfen dabei, dass die Toten nach dieser schrecklichen Tragödie ihren Frieden finden. Ich werde dafür sorgen, dass die Familien benachrichtigt werden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nStiefel des TunnelgräbersVerstaubte Bergbau-Handschuhe\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[169] = {title = "GESUCHT: Gath'Ilzogg", objective = "Erledigt Gath'llzogg und bringt seinen Kopf zu Magistrat Solomon in Seenhain, um die Belohnung zu erhalten.", description = "Gesucht! Gath'llzogg, Rädelsführer hinter den Angriffen der Blackrock auf Burg Steinwacht und den Überfällen auf die Ortschaft Seenhain. \n\nGath'llzogg ist äußerst gefährlich. Berichten zufolge hat er sich in der kürzlich eroberten Burg eingenistet und plant dort die weiteren Verbrechen des Blackrockklans gegen die menschliche Bevölkerung. Die Orcplage muss um jeden Preis eingedämmt werden. Der tapferen Seele, die Magistrat Solomon den Kopf von Gath'llzogg übergeben kann, winkt eine großzügige Belohnung.", progress = "Was bringt Ihr mir da, <Volk>?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Gath'llzogg führte diese Bestien in die Schlacht und war für den Tod vieler unschuldiger Menschen verantwortlich. Nun haben wir uns gerächt. Dies ist der erste Schritt zur Wiedereroberung der Burg für das Königreich Stormwind!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[170] = {title = "Eine neue Bedrohung", objective = "Balir Frosthammer möchte, dass Ihr 6 Troggs der Felsenkiefer und 6 bullige Troggs der Felsenkiefer tötet.", description = "Ich hoffe, Ihr seid hier, um uns zu helfen, <Klasse>. Nach dem letzten Angriff der Troggs können wir alle Hilfe gebrauchen, die wir kriegen können.\n\nIch habe gehört, die kleinen Biester sind überall im ganzen Land aufgetaucht, und wie es scheint, ist das Coldridge-Tal keine Ausnahme. Sie sind kreuz und quer in den Hügeln im Südosten und in der Nähe des gefrorenen Sees gesehen worden.\n\nUnd das ist noch nicht alles. Vor ein paar Nächten haben sie unser Lager im Westen angegriffen und überrannt! \n\nWir haben hier zu wenig Leute, <Jungchen/Mädel>, und wir brauchen ein paar starke Arme, die dabei helfen, die Troggs zurückzutreiben.", progress = "Zähe kleine Biester, was?", completion = "Wenn die Probleme, die wir hier haben, ein Hinweis darauf sind, was anderswo in unserem Land passiert, dann - bei Magnis Bart! - stehen uns Schwierigkeiten ins Haus! Ich kann nur hoffen, dass der König und der Senat etwas gegen die Bedrohung durch die Troggs unternehmen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBärenschalRustikaler GürtelSchneestiefel\n\nIhr bekommt außerdem:\n\n"},
[171] = {title = "Tageseltern der Allianz", objective = "Bringt Euren Schützling in das Waisenhaus von Stormwind zurück, indem Ihr die Pfeife des menschlichen Waisenkindes an Waisenmatrone Nightingale im Kathedralenviertel übergebt.", description = "Ihr wart die ganze Zeit so gut zu mir, <Name>. Nie hätte ich erwartet, während der Kinderwoche soviel Spaß zu haben! Danke schön. Ich versuche über das, was mir und den anderen passiert ist, nicht traurig zu sein - meine Freunde sagten immer, ich solle über allem Bösen stehen, das in der Welt passiert. Weißt du was? Wenn ich groß bin, möchte ich genauso ein Held sein wie du!\n\nEs macht mich zwar traurig, aber leider muss ich jetzt nach Hause gehen. Lass uns zur Matrone zurückgehen und ihr erzählen was für ein wunderbarer Mensch du bist!", progress = "Es ist schön Euch wiederzusehen, <Name>. Habt Ihr die Euch auferlegten Pflichten, für die Ihr Euch während der Kinderwoche freiwillig gemeldet habt, sorgfältig erfüllt?", completion = "Möge der Himmel Euch segnen, &lt;Name&gt;. Ihr habt für Randis mehr getan, als es jemand anderem je in den Sinn gekommen wäre. Vielen Dank - Ihr seid ein funkelnder Stern am Himmel der Allianz.\n\nBitte besucht uns mal wieder, wenn Ihr etwas Zeit habt. Ich weiß, dass Randis sich sehr freuen würde, genauso wie ich.\n\nRandis hatte so viel Spaß mit Euch, &lt;Name&gt;. Er hat mich gebeten Euch eines seiner Lieblingstierchen zu geben, damit Ihr Euch stets an ihn erinnert.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchweinehalsbandRattenkäfigSchildkrötenkisteGriesgrams Bestechungsgeld\n\nIhr bekommt außerdem:\n\n"},
[172] = {title = "Die Kinderwoche", objective = "Benutzt die Pfeife des orcischen Waisenkindes um während der Kinderwoche mit Eurem Schützling zu sprechen.\n\nBereitgestellter Gegenstand: \n", description = "Ihr wollt uns tatsächlich hier im Waisenhaus zur Hand gehen? Seid gesegnet, Freund. Eure Unterstützung in der Kinderwoche ist für uns von unschätzbarem Wert.\n\nNehmt diese Pfeife. Sie kann sieben Tage lang verwendet werden - über die ganze Dauer der Kinderwoche hinweg. Durch Benutzung der Pfeife, könnt Ihr mit dem Waisenkind sprechen, auf das Ihr aufpasst. Verwendet sie erneut, um das Kind wieder zu entlassen.\n\nDas Kind ist schon ganz aufgeregt und freut sich darauf Euch kennenzulernen. Worauf wartet Ihr noch <Name>, benutzt die Pfeife und trefft Euren Schützling.", progress = nil, completion = "Zug-zug! Mein Name ist Grunz und ich vermute du suchst nach mir? Ihr seid ein Abenteurer, genauso wie meine Mama und mein Papa. Meine Matrone sagt immer, dass sie ehrenhaft in der Schlacht gefallen sind. Ich bin so glücklich Euch zu treffen!\n\nHoffentlich erleben wir zusammen viele lustige Sachen. Es gibt so viele Sachen, die ich gerne einmal machen würde und die Matrone hat gesagt, dass Ihr diese Woche so etwas wie mein großer Bruder seid. Das finde ich toll!", rewards = nil},
[173] = {title = "Worgs in den Wäldern", objective = "Tötet für Calor aus Dunkelhain 6 Schattenwirker der Nachtheuler.", description = "Es scheint, als würden dunkle Dinge unaufhaltsam in den Dämmerwald gezogen. Meister Carevin hat sich der Aufgabe verschrieben, das Böse und die Ketzerei zu vertreiben. Dank unserer Anstrengungen lebt das Volk von Dunkelhain in Sicherheit.\n\nIhr glaubt, Ihr seid würdig, Euch unserer Gruppe anzuschließen?\n\nEinst dachte ich wie Ihr. Die Selbstzufriedenheit der Wache hatte mich meiner Illusionen beraubt und so schloss ich mich Meister Carevin an. Wenn Ihr Euch beweisen möchtet, so kann dies nicht durch Worte geschehen.\n\nMesst Eure Fertigkeiten an den Schattenwirkern der Nachtheuler im Schattenhain und im verlassenen Obstgarten.", progress = nil, completion = "Ich bin beeindruckt, &lt;Name&gt;. Es scheint, als wäret Ihr durchaus fähig, Euch im Kampf zu behaupten. Vielleicht können wir ja eine Aufgabe für Euch finden, die jemanden mit Euren Fähigkeiten etwas mehr herausfordert.\n\nAber es ist schon eigenartig... Es ist, als seien die Worgs plötzlich aus dem Nichts erschienen. Aber es sind ja in letzter Zeit so viele seltsame Kreaturen in unser Land gekommen, da sind auch die Worgs vermutlich nur eine unserer vielen Sorgen.", rewards = "Ihr bekommt:\n\n"},
[174] = {title = "Der Blick zu den Sternen", objective = "Viktori Prism'Antras aus Dunkelhain möchte, dass Ihr ihm eine Bronzeröhre bringt.", description = "Mein Freund Cog, der Gnom, hat mir versprochen, mir beim Bau eines Gerätes zu helfen, mit dem ich in die Sterne blicken kann. Jenseits der Magie existiert eine Wahrheit, mit deren Hilfe sich die seltsame Verwandlung des Waldes erklären lässt.\n\nBringt mir eine Bronzeröhre, die von einem geschickten Ingenieur hergestellt wurde. Wenn man nach Cogs Blaupause geht, ist das der erste Schritt.", progress = "Habt Ihr bereits einen geschickten Ingenieur gefunden, der eine Bronzeröhre fertigen kann?", completion = "Diese Röhre ist perfekt, &lt;Name&gt;. Das war der erste Schritt!", rewards = "Ihr bekommt:\n\n"},
[175] = {title = "Der Blick zu den Sternen", objective = "Findet Mary und überredet sie, einen Gegenstand mit reflektierender Oberfläche zu Viktoris Projekt beizusteuern.", description = "Laut Cogs Blaupause brauche ich jetzt etwas, mit dem Licht reflektiert werden kann. Ich erinnere mich an eine Frau namens Mary, die hier in der Gegend eine gewisse Bekanntheit erlangte, weil sie immer einen Handspiegel bei sich trug. Vielleicht könnt Ihr diese Mary aufspüren und sie fragen, ob sie ihn uns für unser Vorhaben vielleicht leiht, weil wir ja eine reflektierende Oberfläche brauchen... Ich glaube, sie wohnte früher im südlichen Dämmerwald...", progress = nil, completion = "Doch, ja, ich besaß früher einen Handspiegel.", rewards = "Ihr bekommt:\n\n"},
[176] = {title = "GESUCHT: \"Hogger\"", objective = "Erschlagt den Gnoll Hogger und bringt seine gewaltige Gnoll-Klaue zu Marshal Dughan.", description = "Gesucht: Hogger\n\nEin riesiger Gnoll, Hogger, streunt im südwestlichen Elwynn durch den Wald. Er hat bislang alle Versuche, ihn zu fangen, vereiteln können.\n\nDie Armee von Stormwind hat ein großzügiges Kopfgeld auf den Gnoll ausgesetzt. Kopfgeldjäger, die sich die Belohnung verdienen möchten, sollten einen Beweis für Hoggers Tod bei Marshal Dughan in Goldhain vorlegen.", progress = "Ja, Hogger stellt für mich und meine Männer schon seit längerem ein echtes Problem dar. Habt Ihr mir etwas über die Bestie zu berichten?", completion = "Ha! Gut gemacht! Ich hatte schon befürchtet, niemand würde diesem Monster den Garaus machen!\n\nHier, bitte schön, &lt;Name&gt;. Und danke - dieser Gnoll hat mir Kopfschmerzen vom Ausmaß der Blackrockspitze verursacht!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFußsoldatentunikaGamaschen der Wache von StormwindAusbalancierter Kampfstecken\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[177] = {title = "Der Blick zu den Sternen", objective = "Nehmt dem irrsinnigen Ghul den Handspiegel der blinden Mary ab und gebt ihn Viktori in Dunkelhain.", description = "Der Handspiegel war eines meiner wertvollsten Besitztümer bis zu... dem Vorfall. Danach warf ich den Spiegel hinter der Scheune fort. Es gab da einen irrsinnigen Ghul, der sich früher dort hinten herumgetrieben hat. Vielleicht hat der ihn aufgehoben und mitgenommen. Gerüchten zufolge haust die teuflische Bestie im Friedhof \"Stille Gärten\".", progress = "Ich habe Cog die Anfänge unseres Sternenschaugerätes gezeigt. Er war schwer beeindruckt. Habt Ihr zufällig einen Reflektor finden können?", completion = "Ganz phantastisch! Dies ist geradezu perfekt geeignet. Vielen Dank!", rewards = "Ihr bekommt:\n\n"},
[178] = {title = "Wiederbeschaffung für Theocritus", objective = "Bringt den verblassten Schattenfellanhänger zu Theocritus, dem Magier.", description = "<Ihr hört eine körperlose Stimme:>\n\nIhr müsst nicht erschrecken. Ich bin Theocritus, Hochmagier des Turms von Azora im Wald von Elwynn. Der Anhänger, den Ihr in Händen haltet, ist ein Mittel zur Kommunikation zwischen den Schattenfellgnollen und Morganth, ihrem Meister.\n\nNach langen Monaten der Forschung glaube ich, dass nun auch ich durch diese Anhänger kommunizieren kann. Wenn Ihr diese Nachricht hören könnt, dann war mein Zauber erfolgreich.\n\nBringt mir diesen Anhänger und ich werde Euch für Eure Dienste belohnen.", progress = "Ich habe durch einen Anhänger zu Euch gesprochen, sagt Ihr? Hmm... gebt ihn mir, damit ich ihn studieren kann.", completion = "Seid Euch meiner Dankbarkeit gewiss, &lt;Name&gt;. Schon vor Wochen sandte ich die Nachricht zu den Schattenfellanhängern aus und hatte bereits an einen Fehlschlag geglaubt. Doch es scheint, als habe der Zauber nach einer erheblichen Verzögerung doch zumindest einige Anhänger erreicht.\n\nMit der Zeit hoffe ich zu lernen, wie man auch einen Angriff durch die Anhänger leiten und damit alle Schattenfellgnolle, die einen solchen Anhänger tragen, bewegungsunfähig machen kann.\n\nDoch bevor dies möglich sein wird, sind leider noch viele Stunden der Forschung vonnöten, fürchte ich.", rewards = "Ihr bekommt:\n\nWiederherstellender Balsam"},
[179] = {title = "Zwergenausstatter", objective = "Sten Stoutarm hätte gern 8 Stücke zähes Wolfsfleisch.", description = "Was haben wir denn hier? Ihr seht aus, als könntet Ihr was brauchen, was Euch die Hände warm hält, hm?\n\nIch sag Euch, was da helfen würde: ein paar schöne, warme Handschuhe. Und weil ich so ein netter Kerl bin, geb ich Euch doch gern so ein Paar. Unter einer Bedingung, versteht sich.\n\nIhr müsst mir etwas Wolfsfleisch besorgen. Ist doch 'n guter Handel, oder? Ihr bringt mir etwas Wolfsfleisch und ich sorge dafür, dass Ihr Euch keine Frostbeulen an den Fingern holt. Na, was sagt Ihr?", progress = "Haben Euch die Wölfe Probleme gemacht? Vielleicht solltet Ihr den Klauen und Zähnen und dem, was da sonst noch so alles kratzt und beißt, ausweichen, hm?", completion = "Ah! Großartig. Das Wolfsfleisch ist gerade richtig. Ach, keine Sorge, &lt;Name&gt;, ich vergess doch meinen Teil der Abmachung nicht! Hier, davon sollte Euch eins passen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHandschuhe des HasenjägersHandschuhe des WolfsjägersHandschuhe des Eberjägers\n\nIhr bekommt außerdem:\n\n"},
[180] = {title = "GESUCHT: Lieutenant Fangor", objective = "Tötet Lieutenant Fangor und kehrt mit seiner Tatze zu Magistrat Solomon nach Seenhain zurück.", description = "Gesucht: Lieutenant Fangor\n\nBekannter Anführer des Gnollklans der Schattenfelle; arbeitet für Morganth, den Feind der Stadt und des Königreiches. Auf Geheiß von Magistrat Solomon wird der Tod dieses üblen Verräters an Stormwind gewünscht. Zeigt dem Magistraten seine Tatze zum Beweis, dass er tot ist.", progress = "Welche Neuigkeiten bringt Ihr vor dieses Gericht?", completion = "Der üble Lieutenant Fangor ist also tot? Endlich sind wir diese abscheuliche Kreatur los. Ihr seid sehr tapfer, &lt;Klasse&gt;. Die Stadt Seenhain dankt Euch für Eure Hilfe.", rewards = "Ihr bekommt:\n\n"},
[181] = {title = "Der Blick zu den Sternen", objective = "Findet Zzarc'Vul im südlichen Ogerhort des Dämmerwalds und bringt sein Monokel zu Viktori nach Dunkelhain.", description = "Jetzt brauchen wir nur noch einen weiteren Gegenstand, um das Gerät fertig zu stellen. Laut Cogs Blaupause wird eine Linse oder etwas in der Art benötigt. Die einzige Linse, von der ich weiß, dass sie groß genug wäre, wird sehr schwierig zu beschaffen sein.\n\nEs gibt da einen Oger namens Zzarc'Vul, der im Ogerhort im Süden des Dämmerwalds haust. Wenn Ihr könnt, bringt mir sein Monokel, dann werde ich das als unsere Linse verwenden.", progress = "Konntet Ihr Zzarc'Vul überzeugen, uns sein Monokel für unser Experiment zu leihen?", completion = "Endlich! Das Sternenschaugerät ist vollendet! Danke, &lt;Name&gt;. Jetzt kann ich meine Forschungen fortsetzen...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTierkreishandschuheGürtel der Sterne\n\nIhr bekommt außerdem:\n\n"},
[182] = {title = "Die Trollhöhle", objective = "Grelin Whitebeard möchte, dass Ihr 14 Trollwelpen der Frostmane tötet.", description = "Mein Bruder Senir und ich wurden in unterschiedliche Ecken von Dun Morogh entsandt, um dort die von den Trollen ausgehende Gefahr zu untersuchen. Der Senat hat mit den Troggs bereits alle Hände voll zu tun, deswegen kann er keinen weiteren Ärger gebrauchen.\n\nNach allem, was ich gesehen habe, ist die Position der Trolle hier im Coldridgetal nicht sonderlich gut - sie sind vor allem in der südlichen Höhle zu finden. Ich würde sagen, die Armee brauchen wir nicht. Einige starke Arme sollten mehr als ausreichend sein.\n\nMöchtet Ihr vielleicht mithelfen? Ich bin ermächtigt, Euch für Eure Dienste eine Entschädigung anzubieten.", progress = "Nach allem, was ich gehört habe, kommen diese Trolle aus dem Frostmaneklan. Leider weiß ich nicht viel mehr über sie, das Euch in irgendeiner Form helfen könnte, <Name>.", completion = "Aargh! Diese vom Licht verbrannten Trolle!\n\n&lt;Er atmet tief durch und scheint sich zu beruhigen... ein bisschen zumindest.&gt;\n\nIn der Nacht hat eine Gruppe Trolle mein Tagebuch gestohlen! Ich hätte es besser wissen müssen. Was vertraue ich auch meinem nichtsnutzigen Lehrl...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAnvilmar-HandaxtAnvilmar-HammerAnvilmar-MesserAnvilmar-Vorschlaghammer\n\nIhr bekommt außerdem:\n\nHeilkraut"},
[183] = {title = "Der Eberjäger", objective = "Talin Keeneye möchte, dass Ihr 12 kleine Klippeneber tötet.", description = "Es geht doch nichts über einen Tag auf der Eberjagd, wie?\n\nNa ja, hier im Coldridgetal gibt es so viele Eber, dass es fast schon keinen Spaß mehr macht. Man muss sie gar nicht mehr reizen. Sie sind schon aggressiv und angriffslustig, ohne dass man nachhilft. Um genau zu sein, streifen in letzter Zeit so viele Eber durch die Gegend, dass es gefährlich für mich geworden ist, auf die Jagd zu gehen.\n\nIch mach's kurz: Wenn Ihr mir dabei helfen könntet, einige der Eber zu töten, dann würde ich das zu schätzen wissen.", progress = "Wie läuft die Jagd?", completion = "Ausgezeichnet! Dann kann ich ja jetzt meine... etwas gemächlichere... Jagd wieder aufnehmen. Ich danke Euch, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZwergische StoffkniehoseZwergische Lederhose\n\nIhr bekommt außerdem:\n\n"},
[184] = {title = "Furlbrows Urkunde", objective = "Bringt Furlbrows Besitzurkunde zu Bauer Furlbrow.", description = "Dies ist eine Besitzurkunde für ein Stück Ackerland in Westfall. Es ist von einem gewissen Theodore Furlbrow und seiner Frau Verna unterzeichnet. Auf der Rückseite der Besitzurkunde stehen ein paar hastig hingekritzelte Worte:\n\n\"Wir haben Furlbrow etwas bearbeitet und ihm seine Besitzurkunde abgeluchst. Wäre vielleicht ganz nützlich, wenn Ihr Euch auch so eine fälschen wolltet.\n\nUm die Furlbrows müssen wir uns jedenfalls keine Sorgen machen. Zuletzt sah ich sie kurz hinter Westfall in einem Wagen mit gebrochener Achse.\"\n\nIhr denkt, die Furlbrows hätten ihre Besitzurkunde vielleicht gern zurück ...", progress = "Ihr habt die Besitzurkunde meines Hofes? Wie schön! Einige Grobiane haben sie vor etlichen Tagen gestohlen... Ich dachte schon, ich würde sie nie wieder sehen!\n\nBitte, gebt sie mir. Wir sind auf dem Weg, Westfall zu verlassen, und so schnell werden wir nicht wiederkommen, aber wenn, dann werden wir diese Dokumente brauchen.", completion = "Vielen, vielen Dank, &lt;Name&gt;! Wie schon gesagt, diese Gegend ist kein Ort mehr für ehrliche Leute, aber wenn die Dinge besser werden sollten, dann können wir mit dieser Besitzurkunde unser Land zurückfordern.\n\nIch habe nicht viel, was ich Euch anbieten kann, aber hier: Nehmt das.", rewards = "Ihr bekommt:\n\nReife WassermeloneKleiner Kürbis"},
[185] = {title = "Beherrschen der Tigerjagd", objective = "Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 junge Schlingendorntiger tötet.", description = "Als ich noch ein kleines Mädchen war, brachte mein Vater mir die Kunst der Tigerjagd bei.\n\nIhr werdet feststellen, dass die jungen Katzen sich wesentlich leichter aufspüren und töten lassen. Deswegen fangen wir auch klein an. Man findet die jungen Tiger oftmals in der Nähe des Expeditionslagers.\n\nÜbt Euch im Fährtenlesen und seht zu, ob Ihr nicht einige der Wildtiere zur Strecke bringen könnt.", progress = "Ich kann Euch nicht mit gutem Gewissen weiter ausbilden, <Name>, solange Ihr nicht bewiesen habt, dass Ihr die jüngsten Tiger erlegen könnt.", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Ihr seid jetzt bereit, Euch anderen Dingen zu widmen.", rewards = "Ihr bekommt:\n\n"},
[186] = {title = "Beherrschen der Tigerjagd", objective = "Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 Schlingendorntiger tötet.", description = "Ihr macht Fortschritte, <Klasse>. Jetzt lasst uns sehen, wie Ihr Euch gegen die ausgewachsenen Katzen anstellt. Tötet diesmal 10 Schlingendorntiger.", progress = nil, completion = "Ich bin beeindruckt, &lt;Klasse&gt;. Ihr kommt recht gut voran.", rewards = "Ihr bekommt:\n\n"},
[187] = {title = "Beherrschen der Tigerjagd", objective = "Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 alte Schlingendorntiger tötet.", description = "Jetzt werde ich den Einsatz erhöhen und Eure Fähigkeiten wirklich prüfen. Beweist mir, dass Ihr 10 alte Schlingendorntiger töten könnt. Wenn Ihr das schafft, dann seid Ihr bereit für Eure letzte Herausforderung, ehe ich Euch in Meister Nesingwarys Gegenwart <zum Meisterjäger/zur Meisterjägerin> ernenne.\n\nNicht nur sind die alten Schlingendorntiger am schwierigsten zu finden, sie sind auch am schwierigsten zu besiegen.", progress = nil, completion = "Sehr eindrucksvoll. Ich glaube, Ihr seid fast so weit.", rewards = "Ihr bekommt:\n\n"},
[188] = {title = "Beherrschen der Tigerjagd", objective = "Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr Sin'Dall tötet und mit ihrer Tatze zurückkehrt.", description = "Hier ist die letzte Aufgabe, die ich Euch auferlegen werde. Wir sind schon seit Wochen einer schwer zu fassenden Tigerin auf der Spur. Wir nennen das Tier Sin'Dall. Vielleicht gelingt Euch ja, was noch kein <Volk> vor Euch geschafft hat: Spürt Sin'Dall auf und bringt sie zur Strecke. Bringt mir ihre Tatze zum Beweis für Eure Leistung.\n\nAber die Tigerin aufzuspüren, wird nicht leicht sein.", progress = "Wie läuft die Jagd auf Sin'Dall?", completion = "Äußerst beeindruckend, das muss ich schon sagen! Ihr seid wahrlich ein Meisterjäger, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nTigerjäger-Handschuhe"},
[189] = {title = "Ohren der Bloodscalp", objective = "Verschafft Euch 15 Ohren der Bloodscalp und bringt sie Kebok in Booty Bay.", description = "Verdammte Trolle! Sie haben im Dschungel schon etliche unserer Agenten getötet und ich habe bereits einige meiner besten Wachen in Scharmützeln mit ihnen verloren. Was das alles kostet! Wie soll ich das nur Baron Revilgaz erklären?\n\nEntschieden handeln... Denk nach, Kebok... Du bist auf den Posten, den du heute hast, nicht durch Rumsitzen gekommen... Ha, ich hab's! Ihr... <Name>, richtig? Ihr helft mir doch, oder? Es gibt auch Geld zu verdienen!\n\nFolgender Handel... Ihr bringt mir die Ohren von 15 Trollen der Bloodscalp und ich bezahle Euch gut dafür.", progress = "Ihr wart erfolgreich, hoffe ich. Die sind wirklich überall, diese Trolle. Widerliche Kerle.\n\nAch ja, da fällt mir was ein! Sagt es unbedingt auch all Euren Freunden weiter, ja? Wir können viel Hilfe gebrauchen!", completion = "Oh, ausgezeichnet, ganz ausgezeichnet. Das sollte helfen, für den Anfang zumindest...\n\n&lt;Seine Stimme wird leiser und er murmelt irgendetwas von Gewinnspannen und Kosten.&gt;\n\nWas denn? Seid Ihr immer noch da? Belohnung? Oh, ja, richtig... natürlich, hier, nehmt dies... das sollte mehr als genug sein.", rewards = "Ihr bekommt:\n\nGoblin-Angelrute"},
[190] = {title = "Beherrschen der Pantherjagd", objective = "Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 junge Panther tötet.", description = "Wenn Ihr zusammen mit dieser Elitegruppe, die Hemet zusammengestellt hat, an der Jagd teilnehmen wollt, dann müsst Ihr erst beweisen, dass Ihr <ein fähiger Pantherjäger/eine fähige Pantherjägerin> seid. Aber wir fangen ganz einfach an, keine Sorge. Schauen wir mal, wie Ihr Euch beim Töten von 10 jungen Panthern anstellt.\n\nDie Tiere aufzuspüren ist nur die halbe Miete.", progress = "En echter Pantherjäger wäre jetzt da draußen und würde seiner Beute nachstellen. Zeigt etwas Engagement, <Klasse>, und macht, dass Ihr wieder ins Feld kommt.", completion = "Das war ein guter Anfang, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[191] = {title = "Beherrschen der Pantherjagd", objective = "Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 Panther tötet.", description = "Jetzt seid Ihr bereit, Euch an einen Gegner zu wagen, der eine Nummer schwieriger ist. Wenn Ihr Euch wirklich als würdig erweisen wollt, mit solchen Leuten wie den Großwildjägern zu verkehren, dann müsst Ihr beweisen, dass Ihr 10 Panther töten könnt.\n\nDiese Bestien sind schon etwas zäher. Die lassen sich nicht so leicht erlegen wie die Jungtiere, mit denen Ihr Euch bis jetzt abgegeben habt.", progress = "Geht und tötet 10 Panther! Zeigt uns, aus welchem Holz Ihr geschnitzt seid!", completion = "Das habt Ihr perfekt durchgeführt, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[192] = {title = "Beherrschen der Pantherjagd", objective = "Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 Schattentatzenpanther tötet.", description = "Jetzt kommt der schwierige Teil. Ein echter Pantherjäger beweist seine Fähigkeiten damit, dass er Schattentatzenpanther erlegt, die tödlichsten Vertreter ihrer Art im ganzen Schlingendorntal. Beweist uns, dass Ihr 10 dieser Bestien zur Strecke bringen könnt.\n\nUnd wenn Ihr glaubt, die seien schwer aufzuspüren, dann wartet nur, bis Ihr versucht, eine von ihnen zu erlegen...", progress = "Was macht Ihr denn hier, <Name>? Ihr solltet durch das Unterholz kriechen und versuchen, 10 Schattentatzenpanther zu töten! Ich dachte, Ihr hieltet Euch für einen Großwildjäger?", completion = "Ihr habt Eure Sache gut gemacht, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[193] = {title = "Beherrschen der Pantherjagd", objective = "Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr ihm den Fangzahn von Bhag'thera bringt.", description = "Ihr habt schon fast bewiesen, dass Ihr die Kunst der Pantherjagd meisterlich versteht. Schon seit längerem pirscht ein Panther namens Bhag'thera durch den Dschungel. Bis jetzt ist er unserer Jagdgesellschaft immer ausgewichen. Seht zu, ob es Euch mit Euren Fähigkeiten gelingt, den großen Bhag'thera zu töten.\n\nBringt mir den Fangzahn von Bhag'thera, dann habt Ihr Euch meinen Respekt redlich verdient!", progress = "Bhag'thera ist oft so gut wie unauffindbar. Wie läuft die Jagd?", completion = "Der große Bhag'thera ist also tot! Meinen Beifall, &lt;Name&gt;. Ihr seid wahrlich ein großer &lt;Klasse&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nPantherjäger-Gamaschen"},
[194] = {title = "Beherrschen der Raptorenjagd", objective = "Hemet Nesingwary möchte, dass Ihr 10 Schlingendornraptoren tötet.", description = "Soso, Ihr glaubt also, Eure Jagdfertigkeiten sind erstklassig? Das lässt sich ganz leicht feststellen. Zieht hinaus in den Dschungel und tötet 10 Schlingendornraptoren. Dann werden wir ja sehen, wie gut Ihr als Großwildjäger wirklich seid.\n\nUnd nein, ich werde Euch nicht sagen, wo Ihr sie finden könnt! Die Viecher aufzuspüren ist Teil der Aufgabe.", progress = nil, completion = "Sehr schön gemacht, alter Junge!", rewards = "Ihr bekommt:\n\n"},
[195] = {title = "Beherrschen der Raptorenjagd", objective = "Hemet Nesingwary möchte, dass Ihr 10 Schmetterschwanzraptoren tötet.", description = "Jetzt machen wir die Herausforderung ein wenig schwieriger und schauen mal, ob Ihr dem gewachsen seid. Begebt Euch in den Dschungel und erlegt 10 dieser elenden Schmetterschwanzraptoren. Zeigt uns, was Ihr so drauf habt!", progress = nil, completion = "Ja, so bekommt man die eine oder andere Jagdtrophäe zusammen, die man sich zu Hause über den Kamin hängen kann! Das war eine gute Jagd, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[196] = {title = "Beherrschen der Raptorenjagd", objective = "Hemet Nesingwary möchte, dass Ihr 10 Dschungelpirscher tötet.", description = "Mal sehen, wie Ihr mit der nächsten Herausforderung fertig werdet. Dort draußen treibt sich eine sehr scheue Art von Raptoren herum. Wir nennen sie Dschungelpirscher. Sie sind sehr viel schwieriger aufzuspüren und zu erlegen als die anderen Arten, an denen Ihr Euch bisher versucht habt. Tötet 10 Dschungelpirscher, dann verrate ich Euch, wie Ihr zu einem noch besseren Jagderlebnis kommt.", progress = nil, completion = "Hoho! Sieh an, wir haben hier einen wahren Raptorentöter! Sehr schön gemacht, alter Junge!", rewards = "Ihr bekommt:\n\n"},
[197] = {title = "Beherrschen der Raptorenjagd", objective = "Hemet Nesingwary möchte, dass Ihr Tethis tötet, einen schwer fassbaren, gefährlichen Raptoren des Schlingendorntals.", description = "Da Ihr Euch im Dschungel als so tatkräftig erwiesen habt, lasst mich Euch von einem wilden Raptor erzählen, den sogar ich nicht erlegen konnte. Ajeck hier nennt diesen verschlagenen Raptor Tethis.\n\nWenn Ihr Euch als <wahrer Meister/wahre Meisterin> erweisen wollt, dann erlegt Tethis und bringt mir seine Kralle. Es wäre eine Leistung, die bisher noch keinem anderen Großwildjäger gelungen ist.", progress = "Wie läuft die Jagd auf Tethis? Ihr habt sie wohl den ganzen Weg bis hierher ins Lager verfolgt, wie?", completion = "Meister &lt;Name&gt;, der Raptorentöter!\n\nKlingt gar nicht schlecht, wie?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nRaptorjägertunika"},
[198] = {title = "Vorräte für den Gefreiten Thorsen", objective = "Liefert die verschiedenen Goblin-Vorräte bei dem Gefreiten Thorsen ab.", description = "Hmm. Ja, es gibt tatsächlich etwas, das Ihr tun könntet. Lieutenant Doren und seine Leute oben im Norden warten auf ihre turnusmäßige Vorratslieferung von uns.\n\nDie Vorräte wurden noch nicht bei ihnen abgeliefert und jetzt, wo die Trolle ständig angreifen, brauche ich jemanden, der das erledigt. Dorens Lager liegt im Nordwesten der Straße, dort, wo man vom Dämmerwald aus ins Schlingendorntal kommt. Gebt die Vorräte dem Gefreiten Thorsen. Wenn er nicht im Lager ist, dann patrouilliert er südlich davon. Er wird sie in Empfang nehmen und verstauen.\n\nAber dass eines klar ist: Wenn Ihr versagt, dann müsst Ihr mir Ersatz leisten.", progress = "Ja? Was wollt Ihr? Oh, Vorräte von den Goblins. Seltsam, dass ein <Volk> das Paket abliefert, normalerweise schicken sie einen ihrer eigenen Leute. Na, egal. Ihr habt die doch wohl hoffentlich nicht angefasst? Gut, gut... Wir wollen ja nicht, dass unseren Minen irgendwas passiert, oh nein.", completion = "Mit diesen Landminen können wir uns gegen diese Bestie Kurzen und seine Männer verteidigen. Danke, dass Ihr sie uns gebracht habt. Wenn Ihr noch weitere Arbeit möchtet, dann kann ich vermutlich etwas finden, was Ihr tun könntet. Dann müsstet Ihr Euch auch nicht mit diesen Goblins abgeben, wie?", rewards = "Ihr bekommt:\n\n"},
[199] = {title = "Eine dunkle Bedrohung", objective = "Kehrt zu Chefingenieur Hinderweir zurück und zeigt ihm den Hinweis, den Ihr entdeckt habt.", description = "Ihr nehmt eine Probe von dem sonderbar riechenden Pulver.", progress = "Habt Ihr irgendwelche Hinweise finden können, <Name>?", completion = "Diese Entdeckung ist alarmierend und das ist noch milde ausgedrückt!", rewards = "Ihr bekommt:\n\n"},
[200] = {title = "Buchmacher Herod", objective = "Findet Buchhalter Herods Aufzeichnungen.", description = "Wenn Kurzen Thorsens Geheimnis kennt, dann haben wir einen Spion in unseren Reihen. Wir müssen herausfinden, wie das Geheimnis verraten werden konnte!\n\nThorsens Kontaktperson in Kurzens Lager war der Buchhalter Herod. Herod ist Kurzens Nachschuboffizier und weiß alles über den Betrieb in Kurzens Truppenlager. Wenn Ihr Herods Unterlagen oder Aufzeichnungen beschaffen könntet, dann finden wir vielleicht heraus, wie Thorsen entdeckt werden konnte.\n\nAls wir noch unter Kurzen dienten, war das Büro des Buchhalters im oberen Stock des einzigen zweistöckigen Gebäudes im Lager. Seine Aufzeichnungen sind vermutlich immer noch dort zu finden.", progress = nil, completion = "Dies sind Buchhalter Herods Notizen und Aufzeichnungen.\n\nDarunter befinden sich: eine Liste mit Vorräten, die hier gelagert werden, Materialanforderungen von Colonel Kurzen sowie verschiedenste Briefe und Korrespondenz.", rewards = "Ihr bekommt:\n\n"},
[201] = {title = "Untersuchung des Lagers", objective = "Lokalisiert das Jägerlager und teilt dann Krazek in Booty Bay mit, wo es sich befindet.", description = "Ich habe Berichte gehört, nach denen eine Gruppe von Jägern ihr Lager flussaufwärts vom Bergbaucamp der Venture Company am Nazferitisee aufgeschlagen hat. Das wäre mir normalerweise völlig egal, aber ich habe gehört, dass Hemet Nesingwary einer der Jäger dort sein soll. Das ist zwar absolut unwahrscheinlich, aber... na ja, er hat sehr gute Beziehungen, wenn Ihr wisst, was ich meine, und man kann nie vorsichtig genug sein.\n\nWollt Ihr nicht hin und Euch das Lager einmal anschauen, <Name>, und sehen, was die vorhaben?", progress = nil, completion = "Hmmm, dann waren die Informationen, die ich hatte, also wieder einmal richtig, wie meistens. Interessant. Na, ich denke nicht, dass die Jäger für unsere Unternehmung eine Bedrohung oder einen Störfaktor darstellen, aber vielleicht haben sie ja Bedarf an einigen unserer ausgezeichneten Produkte. Hmmm...", rewards = "Ihr bekommt:\n\n"},
[202] = {title = "Colonel Kurzen", objective = "Tötet 6 von Kurzens Elitesoldaten, 4 von Kurzens Stabschefs und bringt Kurzens Kopf ins Rebellenlager zu Lieutenant Doren.", description = "Ihr habt Euren Wert wieder und wieder unter Beweis gestellt und Euer Einfallsreichtum scheint sich mit dem von Kurzen selbst messen zu können. Ihr könntet die Rettung für unseren Rebellentrupp sein... falls Ihr Euch gegen Kurzen stellen und siegen könnt!\n\nEr erteilt die Befehle an seine Männer von tief aus dem Vorratslager heraus. Ihr müsst Euch Zutritt zu dieser Höhle verschaffen, an seinen Verteidigern vorbei, und dann Kurzen und seinen Führungsoffizieren gegenübertreten.\n\nLebt wohl, <Name>. All meine Hoffnung, ebenso das Schicksal meiner Männer, ruht in Euren Händen.", progress = "Wage ich zu hoffen, dass Kurzen und seine Verteidiger tot sind, <Name>?", completion = "Ich hatte den Berichten nicht glauben wollen, hatte kaum zu hoffen gewagt, aber Ihr bringt uns jetzt den Beweis... Kurzen und seine Führungsoffiziere sind tot. Ihr habt uns gerettet!\n\nIn diesem Dschungel wimmelt es nur so von den unterschiedlichsten Gefahren, doch keine von ihnen verfügt über die unbarmherzige Intelligenz, die Kurzen eigen war. Jetzt, wo er nicht mehr ist, können wir alle aufatmen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nSchrapnellblaster"},
[203] = {title = "Die zweite Rebellion", objective = "Tötet 15 von Kurzens Dschungelkämpfern.\n\nKehrt ins Rebellenlager zu Sergeant Yohwa zurück.", description = "Wir kämpfen einen aussichtslosen Kampf gegen Colonel Kurzen. Nicht nur, dass der Mann ein brillanter Taktiker ist, seine Männer sind uns auch noch zahlenmäßig mindestens 10 zu 1 überlegen! Um überleben zu können, müssen wir seine eigenen, auf Heimlichkeit basierenden Taktiken gegen ihn anwenden.\n\nBetretet sein Lager im Osten und tötet seine Leute. So viele Ihr könnt. Und verschwindet wieder, bevor seine Verstärkung Euch in die Zange nehmen kann.", progress = "Ich hoffe, Ihr wart erfolgreich, <Name>. Ohne Eure Hilfe können wir gegen Kurzen nicht lange durchhalten.", completion = "Gut gemacht. Der Verlust dieser Dschungelkämpfer wird den Druck, dem unser Lager ausgesetzt ist, etwas verringern.\n\nAber wollt Ihr Euch immer noch mit uns zusammentun, jetzt, wo Ihr einen Vorgeschmack darauf bekommen habt, was für einer Streitmacht wir uns gegenübersehen?", rewards = "Ihr bekommt:\n\n"},
[204] = {title = "Schlechte Medizin", objective = "Bringt Sergeant Yohwa im Rebellenlager 7 Dschungelarzneien und 1 Giftfarnextrakt.", description = "Um überhaupt eine Chance gegen Kurzen zu haben, müssen wir ihm die Möglichkeiten beschneiden, seine Truppen zu heilen. Er hat um sich eine große Anzahl an Medizinmännern versammelt, die seine Streitkräfte mit Dschungelarzneien heilen und unsere Kämpfer mit Giftfarnextrakt vergiften.\n\nWir brauchen dieses Arzneien, um unsere eigenen Leute zu heilen, und wir brauchen eine Probe dieser Extrakte, damit wir sie untersuchen und unser eigenen Arzneien herstellen können. Sucht in Kurzens Truppenlager nach beidem: Seine Medizinmänner haben die Arzneien und die Extrakte werden vermutlich irgendwo in den Vorratskästen im Lager verstaut sein.", progress = "Ich warte auf die Arzneien und den Extrakt, <Name>.", completion = "Gut gemacht, &lt;Name&gt;. Dank dieser Arzneien werden mehr von uns am Leben bleiben und weiterkämpfen können. Und mit dem Extrakt können wir unsere eigenen Arzneien herstellen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPalmwedel-MantelGuerillaspaltbeil\n\nIhr bekommt außerdem:\n\n"},
[205] = {title = "Troll-Hexerei", objective = "Bringt Bruder Nimetz 4 Fetische der Skullsplitter ins Rebellenlager.", description = "Während ich die Legenden studiere, die Ihr beschafft habt, sammelt bitte für mich die Gerätschaften der bösen Trollmagie. Begebt Euch in das Gebiet der Skullsplittertrolle, eines zweiten Stammes weit entfernt im Süden, und beschafft Euch dort Fetische der Skullsplitter von ihren Hexendoktoren und Mystikern.", progress = "Habt Ihr die Fetische bekommen, <Name>? Vielleicht liegt ja in ihnen das Geheimnis von Kurzens Entartung verborgen... Ich muss es wissen!", completion = "Vielen Dank. Ich werde diese Fetische studieren und sehen, ob sie vielleicht das Geheimnis von Kurzens Wandlung zum Bösen in sich tragen.", rewards = "Ihr bekommt:\n\n"},
[206] = {title = "Mai'Zoth", objective = "Bringt das Gedankenauge zu Bruder Nimetz ins Rebellenlager.", description = "Kurzen mag vielleicht tot sein, doch das, was ihn zum Bösen trieb, ist noch am Leben! Mittels meiner Studien habe ich Folgendes entdeckt: Ein Ogermagier namens Mai'Zoth lebt in einem Ogerhort in den östlichen Bergen des Schlingendorntals. Gerüchten zufolge wendet er Magie an, mit deren Hilfe er in die Gedanken anderer eindringen und diese kontrollieren kann, und ich bin mir sicher, dass er es war, der Kurzen verderbt hat.\n\nBleibt Mai'Zoth am Leben, dann beeinflusst er vielleicht noch andere und vielleicht würde dann sogar ein zweiter Kurzen entstehen.\n\nTötet ihn und bringt mir sein Gedankenauge, das Artefakt, mit dem er andere Wesen verderbt.", progress = "Ich gebe Euch meinen Segen mit auf den Weg. Denn nur Mai'Zoths Bösartigkeit kommt seiner Stärke gleich.", completion = "Ah! Ihr habt es geschafft! Ihr seid ein mächtiger Verbündeter des Guten;, &lt;Name&gt;. Möge Eure Kraft niemals schwinden!\n\nIch werde dieses Gedankenauge studieren und versuchen herauszufinden, ob es vielleicht für die Sache des Guten verwendet werden kann. Wenn nicht... dann muss es zerstört werden.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nGelassenheitskugel"},
[207] = {title = "Das Geheimnis um Kurzen", objective = "Findet die 4 Schrifttafeln und bringt ihre Legenden zu Bruder Nimetz zurück.", description = "Colonel Kurzen war einst ein großer, ein edler Mann - ich muss herausfinden, wie es zu seiner Entartung kommen konnte! Es ist möglich, dass er dem Einfluss von Trollmagie unterliegt. Um diesen Verdacht zu bestätigen, muss ich einige ihrer Legenden studieren.\n\nIn den Trollruinen des Schlingendorntals liegen 4 Schrifttafeln versteckt. Ich muss wissen, was auf diesen Tafeln geschrieben steht! Schreibt die Zeichen ab, die Ihr auf den Tafeln findet, und bringt mir die Abschriften.\n\nDie erste Schrifttafel befindet sich in den Ruinen von Bal'lal, die zweite im finsteren Riff und die dritte und vierte Schrifttafel findet Ihr in den Ruinen von Zul'Kunda.", progress = "<Name>! Habt Ihr die Troll-Legenden? Ich muss ihre Geheimnisse erfahren!", completion = "Ich danke Euch, &lt;Name&gt;. Ich werde diese Legenden studieren und versuchen herauszufinden, ob es eine Verbindung gibt zwischen den Trollen und dem Bösen, das Colonel Kurzen befallen hat.", rewards = "Ihr bekommt:\n\n"},
[208] = {title = "Großwildjagd", objective = "Hemet Nesingwary möchte, dass Ihr ihm den Kopf von König Bangalash, dem großen weißen Tiger, bringt.", description = "<Name>, Ihr seid <ein Jäger, der/eine Jägerin> die; unserer Gesellschaft wahrlich würdig ist. Von den Schlachtfeldern von Lordaeron bis in den tiefsten Dschungel hinein habe ich selten jemanden gesehen, der so geschickt mit den Waffen umgegangen ist wie Ihr.\n\nIhr habt die furchterregende Sin'Dall, den schwer fassbaren Bag'thera und die tückische Tethis erlegt. Doch die wahre Trophäe ist der Kopf von König Bangalash. Dieser weiße Tiger ist der Grund, warum ich hier bin. Ich habe schon seit geraumer Zeit ein Auge auf ihn geworfen. Wenn Ihr König Bangalash tötet, dann steht ein für alle Mal fest, dass Euer jägerisches Können von niemandem übertroffen wird.", progress = "Ah, wie ich sehe, seid Ihr zurück, alter Junge. Auch mich hat König Bangalash schon oft dazu gebracht, dass ich auf Händen und Füßen ins Lager zurückgekrochen kam. Haltet durch.", completion = "Verdammt gut gemacht! Ausgezeichnet! Glückwunsch, &lt;Name&gt;! Ihr wart erfolgreich, wo andere versagt haben.\n\nIch fühle mich geehrt, dass Ihr ein Teil unserer großartigen Jagdgesellschaft hier seid. Niemand wird jemals Euer Können in Bezug auf das Jagen und Fährtenlesen in Frage stellen!\n\nEuch gebührt Beifall, sage ich! Beifall!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMeisterjägerbogenMeisterjäger-Gewehr\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[209] = {title = "Hauer der Skullsplitter", objective = "Besorgt 18 Hauer der Skullsplitter und bringt sie zu Kebok.", description = "Es ist teuer und anstrengend, genug Tiger zu töten, um damit den Bedarf an Tigerzähnen für den Export auf die Inseln in den südlichen Meeren decken zu können. Glücklicherweise haben wir eine gewisse Technik entwickelt, mit deren Hilfe wir aus einfachem hornähnlichen Material nicht nachweisbare Fälschungen herstellen können.\n\nErstaunlicherweise eignen sich die Hauer von Skullsplittertrollen dafür am besten.\n\nUnd bevor Ihr irgendwas sagt - was der Käufer nicht weiß, macht ihn nicht heiß, hab ich nicht Recht? Bringt mir so viele Hauer wie möglich, damit wir mit der monatlichen Lieferung anfangen können!", progress = "Zähe Biester, was? Also, habt Ihr was für mich? Tut mir ja Leid, dass ich so ungeduldig bin, aber die Sache ist mir ein ziemlicher Dorn im Auge, solange sie nicht erledigt ist. Also?", completion = "Ah, gute Arbeit, gute Arbeit! Bäh, Ihr hättet sie ja wohl doch ein bisschen sorgfältiger säubern können, vor allem das... Na, egal, ganz egal! Ich danke Euch, &lt;Name&gt;, unsere Unternehmung wird dank Eurer Hilfe zweifellos ihren Ausstoß und ihre Produktivität steigern können! Gut, gut, und nun zu anderen Angelegenheiten...", rewards = "Ihr bekommt:\n\n"},
[210] = {title = "Kochen mit Krazek", objective = "Bringt Krazeks Spezialtopf zu Krazek, dem Goblin.", description = "Meistens bin ich es, der hier im Lager kocht. Und das war auch immer ganz schön viel Arbeit, bis ich von einem Goblin-Händler in Booty Bay einen mechanischen Kochtopf gekauft habe. Der Topf ist einfach unglaublich. Er hat mir unzählige Stunden Arbeit erspart - bis er kaputtgegangen ist!\n\nKönnt Ihr den Topf dem Goblin zurückbringen, damit er ihn mir repariert? Der Händler heißt Krazek.", progress = "Hallo! Ihr habt etwas für mich?", completion = "Ah ja, das ist einer von Krazeks Spezialtöpfen! Eine geniale Erfindung, aber bisweilen bricht eine Feder oder das Getriebe gerät aus dem Tritt oder so was in der Art. Lasst mich mal sehen, was mit dem hier los ist...\n\nAha! Die Dampfbeschickungsvorrichtung ist völlig verrostet, die Gelenkdichtung ist rissig und dem Fobulator fehlen Zähne. Es wundert mich, dass der Topf in diesem Zustand überhaupt irgendetwas kochen konnte!\n\nOb ich ihn reparieren kann? Natürlich kann ich ihn reparieren!\n\nAber das kostet. So etwas kostet immer, oh ja...", rewards = "Ihr bekommt:\n\n"},
[211] = {title = "Weh dir, Andorhal", objective = "Bringt den Splitter von Arajs Phylakterium zu Kommandant Ashlam Valorfist auf der Chillwindspitze in den westlichen Pestländern.", description = "Endlich ist die Zeit gekommen, Andorhal anzugreifen und den Lich, der die Stadt kontrolliert, zu vertreiben.\n\nIhr habt vielleicht einen Beschwörungskristall in den von Euch markierten Wachtürmen bemerkt. Wir glauben, dass diese dem Lich die Kraft geben, die er zur Kontrolle der Stadt benötigt. Ihr müsst alle vier ausschalten. Wird einer davon zerstört, dürfte das zweifellos weitere Truppen des Lichs auf den Plan rufen. Wenn alle vier vernichtet wurden, dürfte der Lich selbst auftauchen, um das Herz der Stadt zu verteidigen.\n\nVernichtet den Lich, <Name>, und bringt mir einen Splitter seines Phylakteriums als Beweis!", progress = "Ihr habt Euren Auftrag erhalten, <Name>. Habt Ihr einen Splitter vom Phylakterium des Lichs als Beweis, dass die Tat vollbracht ist?", completion = "Ihr habt es geschafft! Araj... der Lich ist endlich besiegt!\n\nIhr habt der Allianz heute einen gewaltigen Dienst erwiesen, &lt;Name&gt;. Eure Tapferkeit und Hartnäckigkeit sind ein Beispiel dafür, was es heißt, ein wahrer Held zu sein. Bitte - nehmt dies als ein Zeichen für alle, die Euch sehen, auf dass sie wissen, dass Ihr für die Allianz einen unsterblichen Sieg errungen habt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nMal der Resolution"},
[212] = {title = "Eine kalte Mahlzeit", objective = "Tötet einen Kaltaugenbasilisken, beschafft Euch einen gekühlten Basiliskenschenkel und bringt ihn Angus Stern im Blauen Eremiten.\n\n<Um diese Aufgabe erfolgreich abschließen zu können, dürft Ihr Euren Geist nicht freigeben.>", description = "Eines meiner berühmtesten Gerichte ist gekühlter Basilisk an Limonenvinaigrette. Das Problem ist nur: Das Fleisch lässt sich unmöglich frisch halten und ich muss das Gericht heute Abend anlässlich des Geburtstags eines Edelmannes servieren!\n\nWenn Ihr mir also schnell einen gekühlten Basiliskenschenkel von einem frisch getöteten Kaltaugenbasilisken bringen könnt, dann schulde ich Euch ein Festessen, das eines Königs würdig wäre!\n\nKaltaugenbasilisken streifen durch die Stranddünen im Nordwesten des Schlingendorntals, also habt Ihr eine lange Reise vor Euch. Und macht schnell!", progress = "<Name>! Habt Ihr den Schenkel? Ich muss bald anfangen, ihn zuzubereiten, sonst ist das ganze Bankett ruiniert!", completion = "Ah ja, der eignet sich prächtig! Vielen, vielen Dank!\n\nWenn Ihr mich jetzt entschuldigen wollt, ich muss diesen Schenkel hacken, marinieren und für das Bankett garnieren.", rewards = "Ihr bekommt:\n\n"},
[213] = {title = "Feindliche Übernahme", objective = "Beschafft 8 gerommelte Kristalle und bringt sie nach Booty Bay zu Kebok.", description = "Diesmal ist er zu weit gegangen! Schlimm genug, dass Gelriz dabei ist, die von den Handelsfürsten eingesetzten Moguln rauszudrängen, jetzt versucht er auch noch, den berüchtigtsten aller Piraten mit hineinzubringen!\n\nDas lässt Revilgaz sich nicht bieten und er hat mir aufgetragen, das Problem auf meine Weise zu lösen.\n\nWas meine Weise ist? Diebstahl, ganz einfach. Die Geologen der Venture Company zeigen ein auffälliges Interesse an den seltsamen blauen Kristallen, die sie bisweilen in den Minen finden. Bringt mir einige Proben dieser Steine von den Geologen; es ist mir völlig egal, was Ihr tun müsst, um an sie heranzukommen.", progress = "Ich brauche diese Steine, <Name>, egal, zu welchen Mitteln Ihr greift! Tut es einfach und erspart mir die Details!\n\nWas zählt, ist das Ergebnis, <Name>, nicht mehr und nicht weniger.", completion = "Faszinierend. Dass die Kristalle mit dieser Methode gerommelt wurden, kann nur bedeuten, dass die Company sie als eine Art Treibstoff oder Katalysator verwenden will. Viel mehr als das weiß ich auch nicht. Wir werden Proben davon zu Oberchemiker Gigglefont schicken müssen.", rewards = "Ihr bekommt:\n\nEdelsteinbesetzte Handschuhe"},
[214] = {title = "Rote Seidenkopftücher", objective = "Späherin Riell am Turm auf der Späherkuppe möchte, dass Ihr ihr 10 rote Seidenkopftücher bringt.", description = "Es ist kein Geheimnis, dass das Markenzeichen der Defiasbande ihre roten Kopftücher sind. Aber wir haben herausgefunden, dass das Material, aus dem diese Kopftücher gemacht sind, den Rang des Bandenmitglieds bezeichnet.\n\nJetzt, wo wir das wissen, möchte ich, dass Ihr so viele hochrangige Mitglieder der Defias eliminiert, wie Ihr könnt. Die Bandenmitglieder mit der höchsten Position findet Ihr zweifellos in van Cleefs Geheimversteck. Wenn Ihr fertig seid, bringt mir 10 rote Seidenkopftücher zum Beweis, dass sie tot sind, dann werde ich Euch belohnen. Viel Glück, <Name>.", progress = "Habt Ihr unser Land etwas sicherer vor der Defiasbande gemacht? Wenn ja, dann zeigt mir 10 rote Seidenkopftücher zum Beweis.", completion = "Gut gemacht, &lt;Name&gt;! Im Namen der Volksmiliz verneige ich mich vor Euch angesichts Eures Einsatzes. Bald schon werden wir, mit der Hilfe von tapferen Leuten wie Euch, dieses Land seinen Bewohnern zurückgeben können.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRobuste KurzklingeKunstvoll geschnitzter DolchDurchstechende Axt\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[215] = {title = "Geheimnisse im Dschungel", objective = "Sprecht im Rebellenlager mit Lieutenant Doren.", description = "Danke, dass Ihr mich gerettet habt, <Name>. Ich weiß, wie es aussieht, aber lasst mich bitte erklären!\n\nIch hatte von Lieutenant Doren den Auftrag erhalten, mich wieder Kurzens Männern anzuschließen. Ich sollte sie ausspionieren und den Rebellen Informationen bringen, die sie bitter benötigen. Was Ihr hier miterlebt habt, war das, was ich für meine Chance hielt, Kurzens Truppenlager zu infiltrieren. Ich habe mich geirrt und ich muss Euch nochmals danken, dass Ihr mich gerettet habt.\n\nDiese Mission war streng geheim, Ihr dürft also niemandem davon erzählen. Aber wenn Ihr mit Doren sprecht, dann wird der Euch alles erklären.", progress = nil, completion = "Ja, es stimmt, was Thorsen Euch erzählt hat. Ihr müsst das absolut vertraulich behandeln. Einst waren wir Rebellen Colonel Kurzen bis zum Äußersten ergeben. Aber Kurzen erwies sich als so verderbt, dass unsere Loyalität ihm gegenüber sich in Zorn verwandelte. Wenn es bekannt würde, dass Gefreiter Thorsen kürzlich Verbindung zu Kurzens Männern hatte, dann würden wir ihn eines schönen Morgens mit durchgeschnittener Kehle vorfinden.\n\nMeines Wissens nach hatten nur Sergeant Yohwa, Thorsen und ich selbst Kenntnis von Thorsens Auftrag. Aber es muss noch eine weitere Person geben. Einen Verräter.", rewards = "Ihr bekommt:\n\n"},
[216] = {title = "Hart auf hart", objective = "Schaltet 12 Rächer der Distelfelle und 12 Schamanen der Distelfelle aus. Man findet sie am häufigsten östlich vom Zoramstrand im Distelfelllager. Wenn das erledigt ist, kehrt zu Karang Amakkar in den Zoram'gar-Außenposten in Ashenvale zurück.", description = "Die Distelfellfurbolgs bedrohen unsere Expansion! Das Lager der Distelfelle östlich von uns blockiert den Weg zwischen uns hier und dem Splintertreeposten. Dieser Weg würde das Dorf Astranaar umgehen; ohne ihn überlassen wir der Allianz eine zusätzliche Möglichkeit der Ausbreitung.\n\n<Name>, wir dürfen keine Lücke in unseren Expansionspfaden erlauben!\n\nBegebt Euch ins Distelfelllager und dünnt die Furbolgs etwas aus. Ihr werdet für diese Aufgabe entschädigt werden, aber noch viel wichtiger ist, dass Ihr Eure Pflicht der Horde gegenüber tun werdet.", progress = "Habt Ihr den Kampf zu den Distelfellen getragen? Mit einem freien Weg zwischen unseren Stützpunkten erhöhen sich unsere Chancen erheblich, ganz Ashenvale für uns zu beanspruchen.", completion = "Gut gemacht, &lt;Klasse&gt;, gut gemacht! Ich werde weiterhin Truppen aussenden, um die Population der Furbolgs niedrig zu halten, aber ich kann auf mindestens einen weiteren Pfad zählen, der frei von Verstrickungen der Allianz ist. Die Eroberung von Ashenvale durch die Horde ist jetzt in vollem Gang!\n\nIhr habt Euch heute Eure Bezahlung verdient. Ich ziehe den Hut vor Euch!", rewards = "Ihr bekommt:\n\n"},
[217] = {title = "Verteidigung der Länder des Königs", objective = "Tötet den Anführer der Troggs, Grawmug, sowie seine beiden Wachen, Knirscher und Muskelprotz, und erstattet dann Captain Rugelfuss im südlichen Wachturm Bericht.", description = "<Name>, unsere Späher haben den Anführer des jüngsten Eindringens der Troggs ermitteln können. Es scheint, als folgten diese Bestien am Loch Modan einem Häuptling namens Grawmug. Grawmug wird jedoch aufs Schwerste bewacht. Zwei seiner Elitewachen, Knirscher und Muskelprotz, weichen nie von seiner Seite.\n\nWenn Ihr Euch dem gewachsen fühlt, <Name>, dann möchte ich, dass Ihr das Attentat auf Grawmug und seine beiden Schläger anführt. Wenn die Führungsriege der Troggs tot ist, dann haben wir vielleicht eine Chance, diese Bestien wieder unter die Erde zu treiben.", progress = "Grawmug und seine beiden Wachen, Knirscher und Muskelprotz, sind noch immer am Leben. Eure Mission ist nicht beendet, solange noch einer der drei am Leben ist. Das Zwergenreich zählt auf Euch, <Name>!", completion = "Ganz ausgezeichnet, &lt;Name&gt;! Ihr habt wieder Hoffnung an den Loch Modan gebracht. Jetzt, wo Grawmug tot ist, besteht eine größere Chance, dass die Troggs aus unserem Land vertrieben werden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGrenzer-KniehosenZwergischer VerteidigerGlücks-Beinkleider\n\nIhr bekommt außerdem:\n\n"},
[218] = {title = "Das gestohlene Tagebuch", objective = "Grelin Whitebeard möchte, dass Ihr Grik'nir den Kalten tötet und ihm sein Tagebuch wiederbeschafft.", description = "Mein Tagebuch! Sie haben es in die Höhle gebracht. Der, der es hatte, war ein großer Kerl mit seltsamen Zeichen auf der Haut und im Gesicht. Viel mehr konnte ich leider nicht sehen.\n\nIhr hattet ja mit den Trollen Erfolg, vielleicht könntet Ihr es mir wiederbeschaffen?", progress = "<Name>! Glück gehabt?", completion = "Großartig, &lt;Name&gt;! Vielen Dank, dass Ihr mein Notizbuch zurückgeholt habt. Nun, es scheint, als sei das Trollproblem hier im Coldridgetal unter Kontrolle und als müssten wir uns nicht allzu viele Sorgen machen.\n\nNachdem ich meinem Bericht den letzten Schliff gegeben habe, werde ich jemanden brauchen, der ihn meinem Bruder Senir bringt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZwergisches ViereckschildGlatter Wanderstab\n\nIhr bekommt außerdem:\n\n"},
[219] = {title = "Vermisst", objective = "Beschützt Corporal Keeshan auf dem Rückweg ins Rotkammgebirge.", description = "Freunde der Allianz! Endlich!\n\nHelft... bitte... \n\nDas Letzte, an das ich mich erinnere, ist, dass diese abscheulichen Orcs unser Regiment überwältigten. Die meisten Männer wurden getötet; ich selbst erhielt einen Schlag an den Kopf und alles wurde schwarz. Jetzt werde ich in dieser Höhle gefangen gehalten. Bitte helft mir; ich bin schwer verletzt.\n\nIch brauche Hilfe auf dem Weg zurück in die Stadt... bitte... Ihr seid meine letzte Hoffnung...", progress = "Ja?", completion = "Ihr habt dem Königreich gut gedient, &lt;Klasse&gt;. Danke, dass Ihr Corporal Keeshan bei seiner Flucht vor den gefürchteten Orcs des Blackrockklans geholfen habt. Eure tapferen Taten an diesem Tag sollen nicht unbelohnt bleiben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRobe von SolomonKettenmantel des DeputysKnochenbeschlagenes Leder\n\nIhr bekommt außerdem:\n\n"},
[220] = {title = "Ruf des Wassers", objective = "Bringt die Phiole mit reinstem Wasser in das Brachland zu Islen Waterseer.", description = "Islen hat noch eine weitere Aufgabe für Euch, ehe Ihr zur Belohnung Euer nächstes Totem erhaltet. Die Phiole mit Wasser, die ich Euch gegeben habe, wird für diese Aufgabe gebraucht, um was auch immer es sich dabei handeln mag.\n\nGeht nun und sucht sie auf. Wir werden uns eines Tages wieder begegnen.", progress = "Da seid Ihr ja wieder, <Name>. Ihr seht gut aus.\n\nWas führt Euch schon so bald zu mir zurück?", completion = "Ah, eine Phiole mit Wasser, von Brine geschaffen und gesegnet und von keinem Geringeren eingesammelt als Euch selbst.\n\nDie Flüssigkeit in dieser Phiole ist das wichtigste Element, um ein Sapta für Euch herzustellen, doch sie findet auch für eine weitere Aufgabe Verwendung.\n\nMit dem Sapta, das ich für Euch herstelle, solltet Ihr die Wassergeister am Schrein im Silberwald, südlich von Undercity, sehen. Was die verbleibenden Tropfen betrifft, nun, zu den verbleibenden Tropfen sage ich Euch etwas, sobald Ihr glaubt, dass Ihr bereit seid.\n\nSeid Ihr auf eine weitere Reise vorbereitet, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\nWassersapta"},
[221] = {title = "Worgs in den Wäldern", objective = "Tötet für Calor aus Dunkelhain 12 Dunkelläufer der Nachtheuler.", description = "Habt Ihr vielleicht schon festgestellt, dass einige größere Worgs zusammen mit den Schattenwirkern im Wald herumziehen? Nach allem, was wir wissen, machen diese Dunkelläufer den Großteil der Worg-Population aus.\n\nAuf meinen Wanderungen habe ich außerdem festgestellt, dass sie in den verlassenen Obsthain im Südwesten der Stadt eingefallen sind. Diese Worgs sind etwas zäher als die Letzten, denen Ihr begegnet seid.\n\nAlso seht Euch vor.", progress = "Schon zurück, <Name>? Ich hoffe, Ihr seid nicht gekommen, um mir zu sagen, dass Ihr aufgegeben habt?", completion = "Gegen die Dunkelläufer habt Ihr Euch gut geschlagen, &lt;Name&gt;. Aber es scheint, als sei ihre Zahl schier unerschöpflich. Ganz gleich, wie viele wir töten, es schießen immer mehr aus dem Boden, um ihre Reihen wieder zu schließen.\n\nWelche böse Macht zieht sie nur hierher? Warum sind sie gekommen, um unser unglückliches Land zu plagen?\n\nDoch ich vertraue auf Meister Carevin. Zweifellos wird er der Sache auf den Grund kommen.", rewards = "Ihr bekommt:\n\n"},
[222] = {title = "Worgs in den Wäldern", objective = "Tötet für Calor aus Dunkelhain einige Worgs, und zwar 8 Faulreißer der Nachtheuler und 8 besudelte Nachtheuler.", description = "Eure früheren Leistungen haben mich überzeugt, dass Ihr in der Lage seid, Euch mit den zähesten Worgs zu messen, die sich in den Wäldern eingenistet haben.\n\nVon all den Worgs, die plötzlich hier zu finden sind, haben sich die Faulreißer und die Besudelten als die gefährlichsten herausgestellt. Sie haben sich in der Nähe einiger Höhlen und in der Mine im Süden niedergelassen.\n\nNoch aus weiter Entfernung sieht man die Lichter ihrer Feuer...", progress = "Furchterregende Biester, nicht wahr? Doch fürchtet Euch nicht, <Name>, die, die für das Licht kämpfen, werden niemals fallen!", completion = "Ich will ganz ehrlich mit Euch sein, &lt;Name&gt;. Ich hatte nicht geglaubt, dass Ihr so weit kommen würdet. Aber ganz offensichtlich seid Ihr als &lt;Klasse&gt; nicht zu unterschätzen. Und wenn Ihr Euch ganz offiziell Meister Carevins Sache anschließen wollt, dann verfasse ich gern ein Empfehlungsschreiben für Euch.", rewards = "Ihr bekommt:\n\n"},
[223] = {title = "Worgs in den Wäldern", objective = "Bringt Calors Notiz zu Jonathan Carevin.", description = "Hier, bitte schön, <Name>. Bringt Meister Carevin diese Nachricht.\n\n<Schnell zieht er ein Stück verblasstes Pergament hervor und reicht es Euch.>\n\nNoch ein paar mehr wie Ihr, dann sind wir bald mehr Kämpfer als die Nachtwache! Vielleicht können wir dann das Werk vollenden, an dem wir wenigen uns heute noch vergebens abmühen.", progress = "Ja, was wollt Ihr? Macht schnell, es gibt wichtige Dinge, um die ich mich kümmern muss.", completion = "Vergebt mir den kühlen Empfang, &lt;Name&gt;, aber wie Ihr sicher sehen könnt, bin ich ein viel beschäftigter Mann. Ganz offensichtlich habt Ihr Calor beeindruckt - ich kann Euch versichern, das ist eine beachtliche Leistung - und er hat Euch seine Empfehlung ausgesprochen.\n\nEs sind äußerst üble Gestalten unterwegs, &lt;Name&gt;, und wir können die Hilfe von jedem gebrauchen, der seinen Wert bewiesen hat. Wir kämpfen gegen Dämonen, die Untoten und alle, die ihnen Hilfe gewähren. Seid wachsam, seid auf der Hut und traut niemandem, der unserer Sache nicht unterstützt.\n\nRuhm unter dem Licht!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGlaubens-UmhangSchild des Glaubens\n\nIhr bekommt außerdem:\n\nGeweihter Zauberstab"},
[224] = {title = "Verteidigung der Länder des Königs", objective = "Gebirgsjäger Cobbleflint vom südlichen Wachturm möchte, dass Ihr 10 Stonesplitter-Troggs und 10 Stonesplitter-Späher tötet.", description = "Wir müssen den Loch beschützen, <Name>! Jetzt, wo so viele der Soldaten des Königs tapfer auf weit entfernten Schlachtfeldern kämpfen, sind wir nahe davor, an der Heimatfront überwältigt zu werden. Aus jedem Spalt graben sich Troggs an die Oberfläche! Die Trogg-Plage stellt für Ironforge die größte Gefahr dar. Diese widerwärtigen Mutanten müssen vernichtet werden.\n\nIhr, <tapferer Abenteurer/tapfere Abenteurerin>, müsst Euch für uns hinauswagen und der Bedrohung durch die Troggs ein Ende bereiten. Erschlagt 10 Stonesplitter-Troggs und 10 Stonesplitter-Späher und erstattet dann wieder Bericht.", progress = "Der Loch Modan wird belagert, <Name>! Wir sind auf jedes einsatzfähige Mitglied der Allianz angewiesen. Habt Ihr schon 10 Stonesplitter-Troggs und 10 Stonesplitter-Späher getötet?", completion = "Gut gemacht, &lt;Name&gt;! Ihr habt auf dem Schlachtfeld verblüffenden Mut bewiesen. Mit Leistungen wie den Euren werden wir unseren Krieg gegen die Troggs gewinnen. Ihr habt König Magni gut gedient.\n\nWenn Ihr glaubt, dass Ihr gerade für solche Abenteuer gut geeignet seid, dann würde ich vorschlagen, Ihr sprecht mit Gebirgsjäger Gravelgaw. Der Captain hat ihn auf eine harte Patrouille geschickt, bei der er bestimmt Hilfe gebrauchen kann. Meldet Euch bei Gravelgaw; er ist im Turm gleich beim Eingang.", rewards = "Ihr bekommt:\n\nPikanter Dalarankäse"},
[225] = {title = "Das verwitterte Grab", objective = "Sprecht in Dunkelhain mit Sirra Von'Indi.", description = "Auf dem verwitterten Grabstein steht einfach:\n\nMORGAN LADIMORE\n\n<Als Ihr den Ort weiter untersucht, stellt Ihr fest, dass die Erde über dem Grab kürzlich umgegraben wurde und dass ein guter Teil der Erde entfernt worden zu sein scheint...>", progress = nil, completion = "Morgan Ladimore?\n\nAber ja, natürlich. Seine Geschichte ist lang und traurig. Ich kannte ihn gut, ehe er in den Krieg zog, doch das war das letzte Mal, dass ich ihn gesehen habe. Er war ein guter und edler Mann, doch es nahm ein böses Ende mit ihm.\n\nEinen Moment, ich glaube, ich habe hier etwas, das Euch die Geschichte besser erzählen kann als meine eigene Erinnerung...", rewards = "Ihr bekommt:\n\n"},
[226] = {title = "Wölfe auf den Fersen", objective = "Tötet 12 verhungernde Terrorwölfe und 8 tollwütige Terrorwölfe und kehrt dann zu Lars in Svens Lager an der westlichen Grenze des Dämmerwalds zurück.", description = "Sven und mir stehen jetzt gefährliche Tage ins Haus, wo doch der Totenbeschwörer im Osten sitzt und all das. Und weil wir hier draußen allein sind, müssen wir auch selbst jagen, wenn wir etwas essen wollen. Es kommt mir so vor, als würden jedes Mal, wenn ich mit etwas Fleisch zum Lager zurückgehe, verhungernde oder tollwütige Terrorwölfe aus dem Wald kommen, die auch etwas abhaben möchten. Ja, eines steht fest, das Leben hier draußen ist gefährlich!\n\nAber wenn Ihr einige der Wölfe für uns erledigen könntet, dann wäre das Leben für uns etwas leichter. Meist streunen sie nördlich und östlich von hier herum, in der Nähe des Flusses.", progress = "Seid Ihr immer noch auf der Wolfsjagd?", completion = "Oh, gut. Ihr habt das Rudel ganz schön reduziert. Und nachdem uns diese Wölfe jetzt nicht mehr an den Fersen hängen, können wir uns wieder damit beschäftigen, wie wir mit Morbent Fel fertig werden.\n\nHier, nehmt ein paar von diesen Blitzstrahlbündeln. Sie werden in der Stadt hergestellt und Sven hat etliche davon geschenkt bekommen, um ihn in seiner Sache zu unterstützen.", rewards = "Ihr bekommt:\n\nBlitzstrahlbündel"},
[227] = {title = "Morgan Ladimore", objective = "Sprecht in Dunkelhain mit Kommandantin Althea Ebonlocke.", description = "<Er sucht in den Regalen und kommt mit einem ledergebundenen Buch zurück.>\n\nWenn Ihr mehr wissen wollt, dann fragt Althea. Sie ist diejenige, die in letzter Zeit von dem... Ärger... mit ihm am meisten mitbekommen hat.", progress = nil, completion = "Morgan Ladimore? Nie gehört.\n\nOh, Ihr meint Mor'Ladim! Dann nehme ich an, Ihr kennt die Geschichte nicht?\n\nNun gut, ich gebe Euch die Kurzfassung. Im Dämmerwald wandert seit einiger Zeit ein wandelnder Untoter namens Mor'Ladim herum. Nach allem, was wir herausfinden konnten, scheint dies der untote Körper von Morgan Ladimore zu sein, von dem Ihr offenbar gehört habt. Er bereitet uns alle möglichen Probleme, greift patrouillierende Wachmänner an und tötet Leute.\n\n&lt;Sie mustert Euch prüfend.&gt;\n\nIhr seht mir fähig genug aus; vielleicht könnt Ihr ihn ja zur letzten Ruhe betten.", rewards = "Ihr bekommt:\n\nDie Geschichte von Morgan Ladimore"},
[228] = {title = "Mor'Ladim", objective = "Tötet Mor'Ladim und bringt seinen Schädel nach Dunkelhain zu Kommandantin Althea Ebonlocke.", description = "Meine Späher berichten mir, dass Mor'Ladim durch den ganzen Dämmerwald wandert und auf dem Friedhof einen seltsamen, gewundenen Weg einschlägt. Wir haben ihn hinter dem Haus auf dem Hügel begraben, wisst Ihr, wo das ist?\n\nEs gibt nichts, was ich tun könnte, um Euch zu helfen, aber ich wünsche Euch viel Glück.", progress = "Ich kann es verstehen, wenn Ihr Probleme mit ihm habt, <Name>. Wir haben einige unserer besten Behüter an Mor'Ladim verloren.", completion = "Ihr habt ihn getötet? Das ist eine beachtliche Leistung, &lt;Name&gt;! Im Namen der Bewohner von Dunkelhain und im Namen der Nachtwache danke ich Euch.\n\nÄh, da wäre allerdings noch eine kleine Sache...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[229] = {title = "Die überlebende Tochter", objective = "Sprecht in Dunkelhain mit Behüterin Sarah Ladimore.", description = "Ich hätte Euch dies schon früher sagen sollen...\n\nWie soll ich sagen...\n\nMorgan dachte zwar, dass seine ganze Familie umgekommen sei, aber seine Tochter Sarah Ladimore lebt noch: Sie ist jetzt eine Behüterin. Die... Umstände... , unter denen ihr Vater zu Tode gekommen ist, haben sie immer sehr aufgewühlt. Vielleicht könntet Ihr zu ihr gehen und ihr mitteilen, was geschehen ist.", progress = nil, completion = "Ja? Mein Vater...\n\n&lt;Sie schlägt die Augen nieder.&gt;\n\nIch wünschte... ich wünschte, es gäbe etwas, das ich für ihn hätte tun können... Wenn ich nur mit ihm gesprochen hätte, ehe er...", rewards = "Ihr bekommt:\n\n"},
[230] = {title = "Svens Lager", objective = "Bringt das Buch von Svens Hof zu Sven.", description = "Als Ihr durch den Haufen wühlt, findet Ihr ein kleines, schmutzbeflecktes Buch.\n\nDas Buch hat keinen Titel, aber... es enthält Informationen, die Sven bestimmt interessieren.", progress = "Ihr habt was gefunden? Bitte zeigt es mir...", completion = "&lt;Sven liest in dem Buch, dann schlägt er es heftig zu.&gt;\n\nDie schattenhafte Gestalt, die ich sah, war Zeuge, wie meine Familie um's Leben kam! Es gibt da etliche Fragen, die ich diesem Mann gern stellen würde... wenn ich nur wüsste, wer er ist!", rewards = "Ihr bekommt:\n\n"},
[231] = {title = "Die Liebe einer Tochter", objective = "Bringt Sarah Ladimores Ring zu Morgan Ladimores Grab.", description = "Hier, nehmt dies und legt es auf sein Grab. Vielleicht... vielleicht weiß er dann irgendwie, dass es mir gut geht und dass keiner von uns ihn für das verantwortlich macht, was geschehen ist.\n\n<Jetzt hat sie Tränen in den Augen, als sie einen Ring von der rechten Hand zieht und ihn Euch übergibt.>\n\nUnd... danke, <Name>.", progress = "Lasst mich in Ruhe...", completion = "&lt;Eine geisterhafte Stimme ertönt im Wind.&gt;\n\nIst das...? Sarah? Kann es sein? Ist sie tatsächlich noch am Leben? Die Last fällt von meinen Schultern...\n\n&lt;Name&gt;. Nehmt Archeus, mein Schwert. Jetzt, wo meine Seele ihren Frieden findet, brauche ich es nicht mehr. Es wurde geschmiedet, um Gutes zu tun, und obgleich ich selbst mich als unwürdig erwiesen habe, es zu tragen, werdet vielleicht Ihr das Licht durch es verbreiten.\n\nLys, meine Liebste...", rewards = "Ihr bekommt:\n\nArcheus"},
[232] = {title = "Kurierdienst für Apothekerin Zinge", objective = "Bringt die Bestellung nach Undercity zu Alessandro Luca.", description = "Die Königliche Apothekenvereinigung benötigt Eure Hilfe. Hört gut zu und wir können beide von meinem Plan profitieren.\n\nApotheker Keever im nächsten Raum mag... begabt sein..., aber seine Forschungen könnten Früchte tragen, wenn sie von einem gewandten Forscher... oder einer gewandten Forscherin verfolgt würden. Zum Glück bin ich eine solche Forscherin. Bringt diese Bestellung zu Alessandro Luca, dem Eigentümer von Blaumond Dies-und-Das. Er wird Euch ein Testset geben. Wenn Ihr es habt, bringt es zu mir zurück und ich werde Euch Eure Aufgabe im Detail erläutern.", progress = "Ja, womit kann ich Euch helfen? Seid Ihr hier, um Geschäfte im Namen der Königlichen Apothekenvereinigung zu machen oder seid Ihr nur hergekommen, um meinen Tag zu verschönern?", completion = "Ah, Zinge benötigt ein Set, was? Es betrübt mich, dass Zinge mich nicht mit ihrem holden Anblick selbst beehrt.\n\nNun gut, ich werde Euch ein Set beschaffen.", rewards = "Ihr bekommt:\n\n"},
[233] = {title = "Postbeförderung im Coldridgetal", objective = "Liefert den Stapel Briefe bei Talin Keeneye ab.", description = "Hm, ich nehme nicht an, dass Ihr mir einen Gefallen tun würdet, <Jungchen/Mädchen>? Heute kam ein Stapel Briefe durch den Pass, aber ich habe nicht die Zeit, sie weiterzuleiten.\n\nSie sind alle an Talin Keeneye adressiert. Ihr findet ihn ein Stück entlang der Straße im Westen. Er hat sein Lager am gefrorenen See aufgeschlagen.\n\nWas meint Ihr?", progress = "Ja? Habt Ihr etwas für mich?", completion = "Danke, ich warte schon seit geraumer Zeit auf diese Briefe.\n\nLeider sind sie aber nicht alle für mich. Dieser Brief ist an Grelin Whitebeard adressiert. Er hält sich nicht allzu weit entfernt auf, wenn Ihr ihm den Brief bringen möchtet.", rewards = "Ihr bekommt:\n\n"},
[234] = {title = "Postbeförderung im Coldridgetal", objective = "Liefert den Brief bei Grelin Whitebeard ab.", description = "Wenn ich mich recht erinnere, hat Grelin sein Lager im Südosten, ein Stück die Straße hinunter. Ich bin sicher, er wartet schon sehnsüchtig auf seine Post.", progress = "Kann ich Euch behilflich sein?", completion = "Ah, ausgezeichnet. Es ist schon eine Weile her, dass ich Nachricht aus Ironforge hatte.", rewards = "Ihr bekommt:\n\n"},
[235] = {title = "Die Jagd in Ashenvale", objective = "Sprecht mit Seneni Thunderheart im Splintertreeposten in Ashenvale.", description = "Achtung, junge Abenteurer! Die Wildnis von Ashenvale erwartet Euch!\n\nDie Horde hat eine starke Präsenz in den Ländern nördlich des Brachlandes aufgebaut. Unsere beiden Außenposten - der Splintertreeposten und der Zoramstrandposten - wollen der Horde zu Ruhm gereichen! Diejenigen, die sich beweisen möchten, sollten dort nach Anleitung suchen. Wichtiger Hinweis: Senani Thunderheart im Splintertreeposten, direkt nördlich des Brachlandes, sucht Abenteurer, die an einer großen Jagd in Ashenvale teilnehmen wollen!", progress = nil, completion = "Willkommen an der neuen Grenze, &lt;Name&gt;. Ashenvale ist ein Land der unbegrenzten Möglichkeiten, eines, in dem jemand Eurer Art, &lt;Klasse&gt;, jede Menge Gelegenheiten finden wird, seinen Mumm unter Beweis zu stellen. Schaut Euch hier im Außenposten um und begebt Euch auf jeden Fall auch einmal hinaus zum Zoramstrand, denn die Horde hat dort noch einen weiteren Außenposten.\n\nEure Anwesenheit hier sagt mir, dass Ihr gekommen seid, um mehr über die Jagd zu lernen. Hört mir genau zu, und ich werde euch gern mitteilen, was Ihr wissen müsst.", rewards = "Ihr bekommt:\n\n"},
[236] = {title = "Verwüster auftanken", objective = "Belagerungsmeister Starkhand in der Tausendwinterfestung möchte, dass Ihr zum Flammenkessel geht und den Hordlern dort 10 Stück Immerglut abnehmt.", description = "<Name>! Wurde auch langsam Zeit, dass Ihr auftaucht. Die Schlacht mag vielleicht zu Ende sein, doch wir müssen uns noch immer auf die nächste vorbereiten. Reist zum Flammenkessel im südöstlichen Teil von Tausendwinter und holt mehrere Stück Immerglut.\n\nDie Glutstücke werden mit Kohle vermengt, um Treibstoff für die Verwüster und Belagerungsmaschinen zu liefern.\n\nOh, eins noch: Falls Ihr zufällig Anhänger der Horde im Flammenkessel sehen solltet, dann zögert nicht, tötet sie und nehmt ihre Glutstücke. Wir können nicht zulassen, dass sie in der nächsten Schlacht im Vorteil sind.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[237] = {title = "Verteidigung der Länder des Königs", objective = "Gebirgsjäger Gravelgaw im südlichen Wachturm möchte, dass Ihr 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher tötet und ihm anschließend Bericht erstattet.", description = "Gebirgsjäger Cobbleflint hat nur Gutes über Euch zu berichten gehabt, <Volk>. Daher werde ich Euch eine Mission von äußerster Wichtigkeit anvertrauen. Wir müssen den Druck auf die eindringenden Trogg-Streitkräfte aufrechterhalten, bis unsere Brüder, die Zwerge, von der Front der Allianz zurückkehren.\n\nBegebt Euch in die südlichen Hügel und tötet 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher. Eure Angriffe werden uns etwas Zeit verschaffen. Erstattet Bericht, sobald Ihr die Aufgabe erfüllt habt.", progress = "Wir brauchen mehr Zeit, <Volk>. Ihr habt den Befehl, 10 Stonesplitter-Schädelhauer und 10 Stonesplitter-Seher zu töten. Setzt den Feind unter Druck, bis wir Verstärkung erhalten. Jetzt ist nicht die Zeit für Müßiggang.", completion = "Ihr habt Eure Mission gut erfüllt, &lt;Volk&gt;. Der König selbst wäre stolz auf Euch.\n\nDie Verstärkung, die uns versprochen war, ist jedoch nie angekommen. Anscheinend ist die Front der Allianz getränkt von dem roten Blut unserer gefallenen Brüder. Die Nachricht von diesen Verlusten hinterlässt einen bitteren Nachgeschmack. Doch wir dürfen nicht zulassen, dass ihr Tod vergeblich war. In diesen finsteren Zeiten müssen wir zusammenstehen und den Ruhm der Allianz wieder aufleben lassen.\n\nSprecht wegen Eurer nächsten Aufgabe mit Gebirgsjäger Wallbang. Wir brauchen Euch jetzt mehr als je zuvor.", rewards = "Ihr bekommt:\n\nGeringer Heiltrank"},
[238] = {title = "Kurierdienst für Apothekerin Zinge", objective = "Bringt das Feldprobenset nach Undercity zu Apothekerin Zinge.", description = "Das Set ist fertig, <Name>. Die Apothekerin Zinge wird es zweifellos so schnell wie möglich haben wollen. Bringt es ihr ohne Verzögerung und lasst sie wissen, dass ich die Kosten für das Set mit auf die Rechnung der Gesellschaft schreiben werde. Richtet ihr bitte außerdem meine wärmsten Grüße aus.\n\nAlso los, steht nicht einfach so rum. So ist nun mal das Leben eines einfachen Kuriers, stimmt's?", progress = "Ja, ich denke, Luca ist genauso beunruhigt wie Ihr. Aber es macht keinen Unterschied - gebt mir das Feldprobenset. Ich muss daran einige Veränderungen vornehmen, damit eine Suche nach den geeigneten Grundmaterialien möglich ist.\n\nIhr habt das Set doch, nicht wahr?", completion = "Gut - es freut mich, mit jemandem zu arbeiten, der darauf achtet, nicht meine Zeit zu verschwenden.\n\nNachdem ich einige Veränderungen an diesem Set vorgenommen habe, könnt Ihr euch auf den Weg machen. Ihr werdet damit einige wichtige Daten für die Aufgabe sammeln, die vor uns liegt.\n\nEs dauert nur einen Augenblick, um diese Veränderungen abzuschließen. Während Ihr wartet, solltet Ihr vielleicht schon einmal darüber nachdenken, was Ihr in die Wüste mitnehmen wollt.\n\nJa, ich sagte \"Wüste\".", rewards = "Ihr bekommt:\n\n"},
[239] = {title = "Hilfe für die Weststromgarnison", objective = "Begebt Euch zur Weststromgarnison und sprecht mit Deputy Rainer.", description = "Die Garnison an unserer westlichen Grenze berichtet von steigenden Aktivitäten der Gnolle und der Diebe. Sie bitten uns um die Entsendung weiterer Soldaten aus Stormwind... aber wir können einfach keine entbehren!\n\nWenn Ihr helfen könntet - wir könnten die Hilfe wirklich gebrauchen. Geht, sprecht mit Deputy Rainer in der Weststromgarnison und fragt ihn, was getan werden muss.\n\nDie Garnison liegt an der Straße im Westen. Wenn Ihr die Brücke über den kleinen Bach überquert habt, liegt sie auf der rechten Seite.", progress = nil, completion = "Marshal Dughan hat Euch geschickt, wie? Ihr seid zwar nicht in der Armee, aber wenn Dughan Euch geschickt hat, dann soll mir das recht sein.\n\nUnsere Lage hier ist, um es gelinde auszudrücken, angespannt. Ich hoffe, Ihr könnt ein wenig aushelfen.", rewards = "Ihr bekommt:\n\n"},
[240] = {title = "Rückkehr zu Jitters", objective = "Kehrt mit den schwärzlichen Krebsküchlein zu Jitters zurück.", description = "Und voilà - \"Krebs\"-Küchlein à la Grual!", progress = "Da seid Ihr ja, <Name>! Habt Ihr mein Essen gebracht?", completion = "Ah! Danke, &lt;Name&gt;. Die waren jetzt genau richtig!\n\nUnd hier, bitte gestattet, dass ich Euch dafür bezahle!", rewards = "Ihr bekommt:\n\n"},
[243] = {title = "Auf ins Feld", objective = "Sprecht in Gadgetzan mit Chefingenieur Bilgewhizzle über eine Kraftquelle für das Testset.\n\nBereitgestellter Gegenstand: \n", description = "Ihr werdet Euch in die Tanariswüste begeben und die Gewebebeschaffenheit der Basilisken, Skorpiden und Hyänen testen, die dort heimisch sind. Beschafft Gewebeproben und untersucht sie mit dem Testset; Ihr müsst davon ausgehen, dass eine Reihe der Proben unnütz sind. Ich benötige von jeder Kreaturenart acht akzeptable Proben.\n\nAußerdem verfügen die Goblins von Gadgetzan über eine Kraftquelle, die mit dieser Art von modifiziertem Set verwendet werden muss. Sprecht mit Chefingenieur Bilgewhizzle und erwerbt eine für das Set.\n\nKehrt erst zu mir zurück, wenn Ihr erfolgreich wart.", progress = nil, completion = "Ah, unsere Kraftquellen vom Typ 4711-FTZ! Normalerweise verwenden wir sie, um Brunnen anzutreiben, aber DANK DER WIDERWÄRTIGEN NOMADEN haben wir im Moment einen Überfluss an Kraftquellen.\n\nNatürlich kann ich Euch eine Kraftquelle für jedes beliebige schändliche Wissenschaftsexperiment besorgen, das Ihr vor mir zu verstecken sucht. Aber das kostet Euch etwas, &lt;Volk&gt;. In Gadgetzan gibt es nichts umsonst.", rewards = "Ihr bekommt:\n\n"},
[244] = {title = "Eindringende Gnolle", objective = "Erstattet Deputy Feldon Bericht.", description = "Seid gegrüßt, <Klasse>. Meine Aufgabe ist es, auf diesem Stück Straße zu patrouillieren. Obwohl die Straße im Augenblick sicher ist, habe ich nördlich und östlich von hier einige Lager von Gnollen gesehen.\n\nSeenhain muss erfahren, dass die Gnollstreitkräfte sich sammeln! Meldet Euch bei Deputy Feldon in Seenhain und berichtet ihm von den Gnollen. Wenn Ihr dies tut, dann wird Feldon Euch bestimmt den Sold eines Spähers zahlen.\n\nGewöhnlich inspiziert Feldon das Gebiet südlich der Brücke nach Seenhain.", progress = nil, completion = "Rotkammgnolle so nah an Elwynn? Es ist möglich, dass sie kurz vor einem Einfall in unsere Heimat stehen. Bald werden die Bewohner von Seenhain nicht die einzigen Menschen sein, die belagert werden!\n\nHier ist Euer Lohn, auch wenn Ihr uns schlechte Nachrichten bringt. Und es kommt auch noch zu einem schlechten Zeitpunkt, denn wir sind nicht gut dafür gerüstet.", rewards = "Ihr bekommt:\n\n"},
[245] = {title = "Gefahr auf acht Beinen", objective = "Erledigt 15 Zwerggiftweberspinnen und meldet Euch dann wieder bei Behüter Dodds im Dämmerwald.", description = "Seid gegrüßt, <Klasse>. Vielleicht habt Ihr die Spinnen gesehen, die die Grenze im Westen überrannt haben? Mit den achtbeinigen Monstern werden wir nicht fertig und der Kommandant hat nicht genug Leute, um sie so weit weg von Dunkelhain einsetzen zu können.\n\nIch bitte Euch wirklich nur sehr ungern darum, aber Ihr seht aus, als könntet Ihr mit ihnen fertig werden. Ich kann Euch keine großen Schätze versprechen, aber ich kann Euch belohnen, wenn Ihr dabei helft, die dreckigen Biester auszurotten.\n\nAch, ein Ratschlag noch: Weicht ihrem Gift aus, wenn Ihr könnt.", progress = "Ihr solltet vorsichtig sein, wenn Ihr Euch mit den Spinnen anlegt. Ich habe einige meiner Männer an sie verloren, und glaubt mir, es ist kein schöner Anblick, wenn jemand kopfüber in ihren Netzen hängt, nachdem das Gift angefangen hat, ihn aufzuweichen.\n\nEs wäre mir gar nicht recht, wenn eines der Viecher Euch zum Frühstück verspeisen würde.", completion = "Ah! Ihr seid zurück. Und Ihr seht gar nicht sonderlich angeschlagen aus, scheint mir. Natürlich ist die Nachtwache dankbar für Eure Arbeit, &lt;Name&gt;, und ich hatte Euch ja auch eine Belohnung versprochen. Hier bitte.", rewards = "Ihr bekommt:\n\nNachtwache-Stulpen"},
[246] = {title = "Einschätzung der Gefahr", objective = "Tötet 10 Bastarde der Rotkammgnolle und 6 Wilderer der Rotkammgnolle und meldet Euch anschließend wieder bei Deputy Feldon in Seenhain.", description = "Wir können keinen der Männer hier entbehren, aber mit diesen Gnollen, von denen Ihr mir berichtet habt, muss etwas passieren.\n\nSpäht das südliche Rotkammgebirge nach Gnollen aus. Bedrängt sie, tötet so viele Ihr könnt und erstattet mir dann Bericht über ihre Anzahl. Gebt mir auch eine Einschätzung der Gefahr, die sie darstellen. Möglicherweise findet Ihr Lager dieser Gnolle entlang der südlichen Straße im Rotkammgebirge.\n\nTut dies für die Armee von Stormwind, <Name>, und Ihr erhaltet eine Belohnung.", progress = "Bitte entschuldigt, <Name>, aber wir haben hier jede Menge zu tun. Wenn Ihr nichts zu berichten habt, dann muss ich meine Aufmerksamkeit anderen Dingen zuwenden.", completion = "&lt;Deputy Feldon hört sich Euren Bericht an.&gt;\n\nDann lagert dort eine beachtliche Streitmacht Gnolle und nach dem, was Ihr mir erzählt habt, sind sie auch zäh. Es kann nicht leicht für Euch gewesen sein, diese Informationen zu beschaffen.\n\nHier, bitte schön, &lt;Name&gt;. Wir danken Euch für Eure Hilfe.\n\nUnd falls Ihr es noch nicht getan habt, sprecht in Seenhain auch mit Marshal Marris und Magistrat Solomon. Unsere Situation wird immer verzweifelter - die beiden werden Euch brauchen können, da bin ich mir sicher.", rewards = "Ihr bekommt:\n\n"},
[247] = {title = "Die Jagd ist abgeschlossen", objective = "<Name>, Ihr habt alle drei Tiere erschlagen, um die es bei der Jagd in Ashenvale geht. Ihr habt mir angemessene Beweise von ihrem Tod gebracht; es gibt keinen Zweifel an Eurer Kraft und Eurer Hartnäckigkeit. Das Blut eines Jägers fließt durch Eure Adern, und Ihr solltet dafür belohnt werden!\n\nBitte, nehmt dieses Schmuckstück als Zeichen unserer Anerkennung ob Eurer mächtigen Taten, die Ihr heute für die Horde in Ashenvale vollbracht habt. Mögen Eure Vorfahren über Euch wachen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWildjäger-Umhang"},
[248] = {title = "Weitere Beobachtungen", objective = "Steigt in den unversehrten Wachturm neben der Burg Steinwacht hinauf.\n\nFindet einen passenden Behälter für die Glyphe von Azora und legt diese dort ab.", description = "Seit einer Weile schon beobachte ich den Turm von Ilgalar und ich habe herausgefunden, dass Morganth im Konflikt mit den Orcs von Burg Steinwacht liegt. Den Grund für ihren Streit kenne ich nicht, aber vielleicht könnt Ihr mir ja dabei helfen, diesem Rätsel auf die Spur zu kommen.\n\nNehmt eine weitere Glyphe von Azora und begebt Euch dann auf die Spitze des unversehrten Wachturms neben der Burg Steinwacht.\n\nFindet einen passenden Gegenstand, auf dem Ihr die Glyphe ablegen könnt. Eine Truhe oder ein Krug - irgendein Ort, an dem die Glyphe nicht auffällt - ist für meine Zwecke geeignet.", progress = "Dieser Krug war einmal mit übel riechendem Schnaps gefüllt. Jetzt liegt er leer und vergessen auf ein paar Fässern.", completion = "Dies ist ein passendes Gefäß für die Glyphe von Azora, sodass Theocritus in den Geist der Bewohner von Burg Steinwacht eindringen kann.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[249] = {title = "Morganth", objective = "Besiegt Morganth.\n\nBringt seinen Schattenanhänger zu Theocritus am Turm von Azora im Wald von Elwynn.", description = "Nach langen Beobachtungen habe ich jetzt Morganths Pläne durchschaut.\n\nEr sucht nach der Sense von Elune... und vielleicht hat er sie bereits gefunden! Wenn dem so ist, dann werden das Rotkammgebirge und das Königreich Stormwind schon bald seine dunkle Macht zu spüren bekommen.\n\nIch selbst bin leider nicht bereit, mich gegen Morganth zu stellen, doch ich fürchte, er muss genau jetzt aufgehalten werden. Daher müsst Ihr Euch Zutritt zum Turm von Ilgalar verschaffen und Morganth entgegentreten.\n\nBesiegt ihn und bringt mir seinen Schattenanhänger. Wenn Ihr dies vermögt, dann schuldet das Königreich Euch viel.", progress = "Sputet Euch, <Name>, ehe meine Befürchtungen sich bewahrheiten und Morganths Macht sich ausweitet!", completion = "Ihr habt Eure Sache gut gemacht, &lt;Name&gt;. Die Niederlage des Hexenmeisters Morganth hat Stormwind vor einer großen Gefahr bewahrt.\n\nDemütig biete ich Euch diese Belohnung an. Und ich würde Euch Frieden wünschen, wenn dies friedliche Zeiten wären.\n\nDoch stattdessen wünsche ich Euch Glück für die Aufgaben, die vor Euch liegen, und Sieg in den Kämpfen, die Ihr bestehen müsst.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nRosen-Mantel"},
[250] = {title = "Eine dunkle Bedrohung", objective = "Untersucht den Bereich um die östliche Dammrampe und bringt Chefingenieur Hinderweir einen Hinweis, der Auskunft darüber geben könnte, was die Dunkeleisenzwerge vorhaben.", description = "Den Sternen sei Dank, jemand sorgt sich um den Damm. Erst die Zerstörung des Thandol-Übergangs, dann die Plünderung von Dun Modr! Ich hege keinerlei Zweifel, dass der Damm das Ziel des nächsten Anschlags der Dunkeleisenzwerge sein wird. Der größte Teil meiner Sicherheitsleute wurde an die Front der Allianz versetzt, einschließlich meines besten Kontrolleurs.\n\nUnd deswegen brauche ich Euch, <Name>. Ich habe einige Pioniere der Dunkeleisenzwerge gesehen, die an der östlichen Rampe des Damms herumlungerten. Untersucht den Bereich und bringt einen Hinweis zurück.", progress = nil, completion = "Das verdächtig aussehende Fass enthält ein sonderbar riechendes Pulver.", rewards = "Ihr bekommt:\n\n"},
[251] = {title = "Übersetzung von Calvinius' Notiz", objective = "Bringt den Brief an Ello zu Sirra Von'Indi.", description = "Bringt den Zettel, den Ihr mir gabt, zu Sirra Von'Indi. Er ist sehr gelehrt und kennt viele Sprachen und alte Künste - wenn überhaupt jemand diese Nachricht übersetzen kann, dann ist er das.", progress = "Eine Nachricht von Calvinius, dem Einsiedler, wie? Ich kenne ihn nicht persönlich, aber wenn er draußen am Friedhof lebt, dann weiß ich, dass sein Gehirn verfault sein muss!", completion = "&lt;Sirra beginnt, die Notiz zu übersetzen.&gt;", rewards = "Ihr bekommt:\n\n"},
[252] = {title = "Übersetzung für Ello", objective = "Bringt Lord Ello Ebonlocke den übersetzten Brief.", description = "Oh je! Wenn das, was hier steht, wahr ist, dann hat Calvinius etwas... Unsägliches getan.\n\nBringt die übersetzte Notiz besser schnell zu Ello zurück.\n\nBeeilt Euch, denn ich fürchte, Unheil rollt bereits auf unsere Stadt zu...", progress = "Ah, ist die Notiz fertig übersetzt? Bitte, zeigt sie mir...", completion = "&lt;Ello liest den Brief und wird kreidebleich. Dann sieht er Euch an.&gt;\n\nIhr mögt Calvinius vielleicht aus Freundlichkeit geholfen haben. Doch dank Eurer Taten ist unsere Stadt verloren.\n\n&lt;Ello versinkt in Gedanken...&gt;", rewards = "Ihr bekommt:\n\nÜbersetzter Brief des Einbalsamierers"},
[253] = {title = "Braut des Einbalsamierers", objective = "Findet Elizas Grab. Beschafft das Herz des Einbalsamierers, das sie in sich trägt, und kehrt zu Ello Ebonlocke zurück.", description = "Der Einbalsamierer... diesen Namen kennen wir aus einer Geschichte, die wir unseren Kindern erzählen. Er war ein freundlicher Alchimist, den der Tod seiner Frau Eliza in den Wahnsinn trieb. Er wollte sie wiederbeleben und so wandte er schwarze Magie an und pflanzte sein eigenes Herz in die Brust seiner toten Gattin ein.\n\nDies stellte Eliza wieder her, doch nun war sie verflucht... ein unstillbarer Hunger auf Menschenfleisch hatte sich ihrer bemächtigt und der Einbalsamierer musste sie in ihrem Grab liegen lassen.\n\nSeine Macht ruht in seinem Herzen. Findet das Grab seiner Frau, holt sein Herz und bringt es mir, solange es noch schlägt. Wenn Ihr dies tut, wird seine Macht gebrochen sein.", progress = "Habt Ihr Elizas Grab schon gefunden? Habt Ihr das Herz des Einbalsamierers?", completion = "Ihr habt es geschafft! Dank der ihm innewohnenden Magie ist das Herz gegen das Böse des Einbalsamierers gefeit und stellt somit einen mächtigen Schutz für die Stadt Dunkelhain dar.\n\nIhr habt unserem Volk einen großen Dienst erwiesen, &lt;Name&gt;. Euer Name wird für alle Zeit in unseren Annalen verzeichnet sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nMantel der EhreWappen von Dunkelhain"},
[254] = {title = "Graben in der Erde", objective = "Ihr schaufelt die nicht allzu feste Erde über dem Grab weg... und findet die Überreste eines Sarges.\n\nAus dem Sarg ist das Vibrieren und Kratzen von zu Klauen verformten Fingern zu spüren und das Knirschen verfaulter Zähne zu hören...\n\nWerdet Ihr den Sarg öffnen und das Herz des Einbalsamierers bergen?", description = nil, progress = nil, completion = nil, rewards = nil},
[255] = {title = "Söldner", objective = "Magistrat Bluntnose aus Thelsamar hat Euch angeheuert, um 4 Oger der Mo'grosh, 4 Schläger der Mo'grosh und 4 Vollstrecker der Mo'grosh zu töten.", description = "Zwei Monate! Zwei Monate, nur um dann aus Ironforge zu hören zu bekommen, dass eine Handvoll Soldaten zu unserer Verteidigung abgestellt wird, und zwei weitere Monate, bis sie ankommen! Schlimm genug, dass unsere Stadt ohne Schutz ist, aber die Ausgrabung und der Damm - der Damm! - sind ebenfalls allen Angriffen schutzlos ausgesetzt.\n\nIch habe also keine Wahl, scheint mir. Ich brauche gedungene Kämpfer.\n\nWie steht es mit Euch? Ihr seht mir tüchtig aus, <Klasse>. Eine Gruppe Oger hat im Nordosten des Sees ihr Lager aufgeschlagen. Vielleicht könntet Ihr ein paar weitere Kämpfer rekrutieren und uns dabei helfen, die Bedrohung für unsere Stadt zu beseitigen?", progress = nil, completion = "Ah, das sind ausgezeichnete Neuigkeiten! Ich selbst und die Bewohner von Thelsamar wissen Eure Mühen außerordentlich zu schätzen. Und was noch besser ist: Wenn wir in der Lage sind, das Ogerproblem zu lösen, dann können wir unsere Aufmerksamkeit endlich auf diese vom Licht verlassenen Troggs richten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[256] = {title = "GESUCHT: Chok'sul", objective = "Tötet Chok'sul und bringt Magistrat Bluntnose seinen Kopf.", description = "Auf Befehl des Magistrats von Thelsamar:\n\nDer Tod von Chok'sul, dem Oger und mutmasslichen Anführer und Kopf hinter den Angriffen auf die Stadt Thelsamar, den Stonewroughtdamm und die Ausgrabungsstätte, wird unter allen Umständen gewünscht. Es darf zu jedem Mittel gegriffen werden, das notwendig ist.\n\nEine Barentschädigung kommt zur Auszahlung, wenn der Magistrat einen Beweis für Chok'suls Tod erhält.\n\nZuletzt wurde Chok'sul am Ogerlager im nordöstlichen Teil von Loch Modan gesehen.", progress = "Ja? Kann ich Euch behilflich sein?", completion = "Pfui! Was ist das denn? Und warum bringt Ihr...\n\nVerdammt! Kann es sein? Da verbrenn mich doch das Licht; ist das der Kopf dieses verdammten Ogers? Da habt Ihr vielleicht einen Fang gemacht! Hier, nehmt diese Belohnung, zusammen mit meinem Dank und dem der Bewohner von Thelsamar.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHaltbare KettenschulternKimbra-Stiefel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\nSchwacher Kanalisierungsring"},
[257] = {title = "Das Prahlen eines Jägers", objective = "Tötet 6 Bergbussarde und kehrt innerhalb von 15 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück.", description = "Ihr glaubt wohl, Ihr könnt Euch mit Daryl dem Kühnen messen, hm? Das will ich auch nicht hoffen! Aber Ihr dürft es natürlich gern versuchen, wenn Ihr denn meint... Hier habt Ihr eine Herausforderung, der Ihr bestimmt nicht gewachsen seid. Also nehmt's nicht zu schwer, wenn Ihr damit nicht fertig werdet.\n\nEin Schwarm Bussarde nistet hier am Loch Modan. Warum versucht Ihr nicht, einige von denen zu erledigen? Ich sag Euch was. Wenn Ihr meine Herausforderung annehmt und es Euch in 15 Minuten gelingt, dann gebe ich Euch meinen Bogen oder mein Gewehr.\n\n<Er mustert Euch abschätzig.>\n\nScheint ja nicht, als ob Ihr viel zu verlieren hättet.", progress = "Kein Glück gehabt? Macht Euch nix draus, Pupserer...\n\nNicht jeder kann so gut sein wie ich.", completion = "Wie jetzt, Ihr hattet Erfolg?\n\nGlaubt mir, Eisenberndama, das sollte Euch nicht zu Kopf steigen. Denn jeder milchgesichtige Junge mit einem Bogen hätte so... kleine Exemplare töten können. Und ich hoffe, es hat Euch nicht zu viel Spaß gemacht, die Bussarde zu erschießen. Wir wollen doch nicht, dass sie aussterben! \n\nAch so, ähhhm... Es soll keiner sagen, dass Daryl der Kühne sein Wort nicht hält.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDaryls JagdbogenDaryls Jagdgewehr\n\nIhr bekommt außerdem:\n\n"},
[258] = {title = "Die Herausforderung eines Jägers", objective = "Tötet 5 alte Bergeber und kehrt innerhalb von 12 Minuten zu Daryl dem Jüngling in die Weitschreiter-Lodge zurück.", description = "<Name>ath, stimmt's? Ich seh schon, Ihr platzt fast vor Stolz, dass Ihr den ersten Test bestanden habt. Aber ich hab Euch ja auch schon gesagt, dass das keine große Tat war.\n\nIhr solltet Euch mal an der Eberjagd versuchen. Glaubt mir, das sind andere Eber als im Coldridgetal, also solltet Ihr Euch vorsehen. Diesmal gebe ich Euch nur 12 Minuten.\n\nSeid nicht zu traurig, wenn Ihr versagt. Ich würde Euch das Hemd geben, das ich am Leibe trage, wenn Ihr es schaffen würdet!\n\nHabe ich Euch schon mal erzählt, wie ich an meine berühmte Narbe gekommen bin? Nein? Also, das war vor zwei Jahren...", progress = "Es ist ganz normal, dass man sich selbst bemitleidet, wenn man sich vor jemandem blamiert, der so viel jünger ist als man selbst. Macht Euch nichts draus, Rinovaah...\n\nWie? Hab ich mir Euren Namen falsch gemerkt?", completion = "Ihr seht etwas mitgenommen aus. Die Eber haben Euch wohl ein paar Schwierigkeiten gemacht, wie? Keine Sorge, ich verrate es auch keinem, dass Ihr versagt habt; ich kann mir vorstellen, wie schwer es für Euch sein muss, auch ohne dass sich die Leute über Euch das Maul zerreißen.\n\nOh! Ihr habt es geschafft? Ihr habt die Eber getötet? Ich... also... na ja, das überrascht mich nicht! Jedes Kind hätte das - Wette?\n\nWas für eine Wette?", rewards = "Ihr bekommt:\n\nFeines StoffhemdDaryls Kurzschwert"},
[261] = {title = "Auf dem Scharlachroten Pfad", objective = "Vernichtet 30 untote Verheerer und kehrt dann zu Bruder Anton auf die Nijelspitze zurück.", description = "Ich werde offen mit Euch sein. Wir sind im Krieg mit der Geißel. Sie ist ein Übel, das unser Volk verdirbt und unser Land infiziert. Sie muss aufgehalten werden, bevor sie uns übermannt und unsere Welt mit Schatten überzieht. Wir vom Scharlachroten Kreuzzug haben geschworen, die Geißel mit Leib und Seele zu bekämpfen.\n\nWenn Ihr auf unserer Seite steht, dann nehmt Euren Mut zusammen und beweist Eure Zugehörigkeit - zerstört die untoten Verheerer von Desolace im südlich gelegenen Tal der Knochen.\n\nTut dies, und der Kreuzzug wird Euch mit offenen Armen aufnehmen.", progress = "Die Geißel gewinnt mit jedem Tag an Stärke. Wenn Ihr ihren Vormarsch wirklich aufhalten wollt, dann beweist es mir.", completion = "Ihr habt Eure Entschlossenheit bewiesen, und der scharlachrote Kreuzzug lobt Euch dafür.\n\nWenn Ihr nicht vor rechtschaffenem Gemetzel zurückschreckt, dann ist Euer Pfad vielleicht der unsrige...", rewards = "Ihr bekommt:\n\n"},
[262] = {title = "Die Schattengestalt", objective = "Nehmt das Buch, das Ihr auf Svens Hof gefunden habt, und zeigt es den Einwohnern von Dunkelhain.", description = "Ich muss wissen, wen ich in der Nacht, in der meine Familie ermordet wurde, in den Schatten habe herumschleichen sehen.\n\nBitte, <Name>, Ihr habt euren Einfallsreichtum bereits bewiesen. Bitte findet diese schattenhafte Gestalt. Ich muss wissen, was sie für Geheimnisse kennt!\n\nIch habe keine Hinweise, die Ihr nicht bereits hättet, aber hier - nehmt das Buch, das Ihr auf meinem Hof gefunden habt. Vielleicht können einige Stadtbewohner das Buch mit seinem Besitzer in Verbindung bringen.", progress = "Wenn Ihr einen Gegenstand von der Schattengestalt habt, nach der Ihr sucht, dann zeigt ihn mir. Ich kann vielleicht etwas über seinen Besitzer erspüren.", completion = "Hmm... Jemand hatte dieses Buch erst vor kurzem in der Hand, jemand, der von Rache getrieben wird. Allerdings sind die daran verbliebenen Eindrücke, oder zumindest die Eindrücke von seinem ursprünglichen Besitzer, sehr schwach.\n\nIch kann jedoch sagen, dass der ursprüngliche Besitzer dieses Buches kein Einheimischer von Dunkelhain ist.", rewards = "Ihr bekommt:\n\n"},
[263] = {title = "Verteidigung der Länder des Königs", objective = "Gebirgsjäger Wallbang im südlichen Wachturm möchte, dass Ihr 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs tötet.", description = "Die Gebirgsjäger sagen mir, dass Ihr recht tapfer und fähig seid, <Name>. Ein <Volk> wie Ihr wird hier draußen gebraucht. Wir bekommen das Trogg-Problem einfach nicht unter Kontrolle. Die Reserve wurde zur Front gerufen, und wir sind hier auf uns allein gestellt. Aber jetzt seid ja Ihr hier, ein erfahrener <Klasse>, also wollen wir doch mal sehen, was Ihr ausrichten könnt.\n\nZieht los und tötet 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs. Wir werden sehen, ob Ihr Eurem Ruf gerecht werdet, <Trogg-Töter/Trogg-Töterin>.", progress = "Schon wieder zurück? Nur für den Fall, dass ich mich nicht klar ausgedrückt habe: Ihr müsst 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs töten, <Name>. Und jetzt schnappt sie Euch, Trogg-Töter!", completion = "Ich wusste schon, als ich Euch zum ersten Mal erblickte, &lt;Name&gt;, dass Ihr Ironforge stolz machen würdet. Ihr habt König Magni gut gedient. Jetzt, wo Ihr Euch als so zuverlässige Hilfe für das Königreich erwiesen habt, solltet Ihr vielleicht mit dem Captain reden, um zu sehen, ob er Euch mehr Details anvertraut.\n\nIch ziehe den Hut vor Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nGrober Wetzstein"},
[264] = {title = "Bis dass der Tod uns scheidet", objective = "Legt Clarices Anhänger auf Yurivs Grab in Silberwald.", description = "Dreckiger Abschaum! Lässt mich wegen seinem verdammten Kreuzzug hier sitzen. Nur, weil \"das Licht das Wichtigste ist, was wir gegen die Bedrohung durch die Untoten besitzen\".\n\nUnd was ist mit seinen Kindern?! Was ist mit MIR?! Nacht für Nacht hab ich hier gesessen und geduldig auf ihn gewartet ... hab immer den zweiten Platz hinter seiner verfluchten Pflicht eingenommen!\n\nTja, hier könnt Ihr sehen, was Euch \"Gerechtigkeit\" einbringt, <Name>! Er ist tot, und ich ertrage genau das, was er aufzuhalten versuchte!\n\nNehmt diesen Plunder und legt ihn auf seine Gruft in dem Grabmal. Ich will nichts mehr damit zu tun haben ... oder mit ihm!", progress = "Der Stein fühlt sich kalt an, wurde aber offensichtlich zweckentfremdet. Überall liegt Abfall herum; Scharten und Risse überziehen das Relief auf dem Sarg; und das Gestrüpp ringsherum hat schon begonnen, die Stätte zu überwuchern.\n\nNiemand kümmert es, wer hier begraben liegt, am allerwenigsten etwaige Opfer der Seuche.", completion = "Ihr legt den wertlosen Anhänger auf das Grab, und der darin eingelassene Edelstein scheint merklich zu verblassen.\n\nAls Ihr aufsteht, um zu gehen, seht Ihr auf den Anhänger herab. Er liegt leblos über den Händen des Reliefs, das in die Oberseite des Sarges eingehauen ist. Eure Gedanken werden kurz unterbrochen, als ein steifer, kalter Windhauch über das Grabmal weht. Für einen Moment ist alles um Euch herum still.", rewards = "Ihr bekommt:\n\n"},
[265] = {title = "Die Schattensuche geht weiter", objective = "Überprüft, ob andere Einwohner Hinweise auf die schattenhafte Gestalt haben.", description = "Hier habt Ihr Euer Buch zurück, <Name>, und viel Glück noch bei Eurer Suche. Vielleicht können Euch ja andere in der Stadt mehr Hinweise geben, wenn Ihr sie fragt.\n\nIch habe jedenfalls noch einen für Euch - obwohl der Autor dieses Buches in Dunkelhain fremd ist, wurde das Buch selbst hier gekauft.", progress = "Manchmal verkaufe ich leere Bücher an Gelehrte oder Magier oder an irgendwen, der ein Tagebuch führen möchte.\n\nIch kann mich gut an jeden erinnern, dem ich in den letzten paar Monaten ein Buch verkauft habe...", completion = "Ach ja. Ich habe dieses Buch vor einem Monat an eine zwielichtige Type verkauft. Er hat mir seinen Namen nicht gesagt, aber er war ein nervöser, hektischer Kerl, der laufend über seine Schulter sah.\n\nIch hoffe, das hilft Euch weiter...", rewards = "Ihr bekommt:\n\n"},
[266] = {title = "Nachforschungen im Gasthaus", objective = "Sucht im Gasthaus nach Hinweisen auf die schattenhafte Gestalt.", description = "Hier habt Ihr Euer Buch zurück, und noch viel Glück bei Euren Nachforschungen.\n\nVielleicht wollt Ihr Eure Suche auf das Gasthaus ausweiten. Wenn die Person, die Ihr sucht, einige Zeit hier in der Stadt verbracht hat, dann hat sie dort vielleicht jemand gesehen.", progress = "Der Rote Rabe läuft nicht mehr so gut wie früher, aber hier kommen immer noch Reisende durch.\n\nWenn Ihr mir die Person beschreibt, nach der Ihr sucht, dann erinnere ich mich vielleicht an sie.", completion = "Oh ja, ich erinnere mich an dieses Buch. Sein Besitzer mietete sich hier für ein paar Tage ein und verbrachte die Abende schreibend an der Bar.\n\nEr verließ die Stadt überhastet und brummelte dabei etwas darüber, dass er gejagt würde von... irgendetwas. Als ich ihn das letzte Mal sah, verließ er die Stadt in Richtung Westen, auf der Suche nach einem neuen Versteck.\n\nDer erste Ort, in dem er landen würde, wäre Rabenflucht.", rewards = "Ihr bekommt:\n\n"},
[267] = {title = "Die Bedrohung durch die Troggs", objective = "Bringt Captain Rugelfuss im südlichen Wachturm 8 Trogg-Steinzähne.", description = "<Klasse>, Ihr seid Euch vielleicht nicht unbedingt der Bedrohung durch die Troggs bewusst, die ihren Schatten über das Land der Zwerge wirft. Nachdem die Reserve von Ironforge zur Front der Allianz gerufen wurde, bleibt uns nur ein Bruchteil der Verteidigungskräfte, die nötig wären, um dieses Land zu schützen. Meinem Regiment wurde aufgetragen, über das Tor hier zu wachen, und wir können unseren Posten aufgrund der Gefahr einer Invasion nicht verlassen.\n\nEs muss aber etwas Druck auf diese verdammten Troggs ausgeübt werden, die in den Hügeln lauern. Wenn Ihr Euch dem gewachsen fühlt, startet einen Angriff auf die Troggs. Bringt mir 8 Trogg-Steinzähne als Beweis.", progress = "Könnt Ihr mir 8 Trogg-Steinzähne zeigen? Wenn nicht, dann habt Ihr immer noch etwas zu erledigen, <Name>.", completion = "Ich bin ziemlich beeindruckt, &lt;Name&gt;. Ihr habt dem Volk der Zwerge einen großen Dienst erwiesen, indem Ihr unser Land verteidigt habt. Selbst König Magni Bronzebeard wäre stolz auf Euch!", rewards = "Ihr bekommt:\n\n"},
[268] = {title = "Rückkehr zu Sven", objective = "Kehrt mit Jitters' vollständigem Tagebuch zu Sven zurück.", description = "Das Buch, das Ihr gefunden habt, war nur zur Hälfte fertig geschrieben. Ich musste es auf Svens Hof zurücklassen, als ich hierher floh... \n\nHier. Nehmt mein vollständiges Tagebuch und bringt es zu Sven. Es beschreibt wesentlich genauer, was auf seinem Hof passierte.\n\nObwohl dieses Tagebuch in den letzten Wochen meine einzige Gesellschaft war, gebe ich es gern auf, wenn ich mir dadurch erspare, Sven und seiner Wut zu begegnen.", progress = "Habt Ihr herausgefunden, wer die Schattengestalt war?", completion = "Dieses Tagebuch macht mir vieles klar und zeigt mir den Weg, den ich gegen die dunklen Reiter zu gehen habe! Ich habe diese Reiter im Dämmerwald und im Gespräch mit dem Zauberer Morbent Fel am verlassenen Gut gesehen.", rewards = "Ihr bekommt:\n\n"},
[269] = {title = "Auf der Suche nach Weisheit", objective = "Gebt Bischof Farthing in Stormwind Jitters' vollständiges Tagebuch.", description = "Geht nach Stormwind und sprecht dort mit Bischof Farthing in der Kathedrale des Lichts. Gebt ihm Jitters' Tagebuch und sagt ihm, dass Ihr vorhabt, Euch Morbent Fel zu stellen.\n\nAuch wenn Stormwind Dunkelhain aufgegeben hat, ist Farthing doch eine gute Seele und sehr weise. Er könnte Euch bei Eurem Versuch, uns zu retten, behilflich sein.\n\nEure Mission ist gefahrvoll, aber beeilt Euch dennoch, <Name>. Mit jeder verstreichenden Stunde verfinstern sich die Schatten über dem Dämmerwald mehr und mehr.", progress = "Ruht Euch erst einmal aus, Bruder. Ich sehe Euch an, dass Ihr weit gereist seid und eine schwere Bürde tragt. Könnt Ihr mir erzählen, was diesen dunklen Schatten über Euch wirft?", completion = "&lt;Nachdem er das Tagebuch gelesen und Eure Absichten erfahren hat... &gt;\n\nEine böse Besudelung hat im ohnehin bereits belagerten Dämmerwald Fuß gefasst. Ich danke dem Licht, dass wir einen Helden wie Euch haben, der sich ihm stellen will.\n\nAber zuerst müsst Ihr Euch auf die kommenden Strapazen vorbereiten... denn der Totenbeschwörer Morbent Fel ist ungeheuer mächtig, und er hat dunkle Verzauberungen auf sich selbst gewirkt, um sich vor körperlichen Angriffen zu schützen. Wenn Ihr ihn besiegen wollt, werdet Ihr eine Waffe benötigen, die gegen diese Schutzzauber gefeit ist.", rewards = "Ihr bekommt:\n\n"},
[270] = {title = "Die verlorene Flotte", objective = "Geht zum Hafen von Menethil im Sumpfland und sprecht mit Glorin Steelbrow.", description = "Vor vielen Jahren sank die dritte Flotte von Kul'Tiras vor der Küste des Sumpflandes, einem Moorgebiet nördlich des Zwergenkönigreichs von Ironforge. Auf einem der Schiffe befand sich eine Ladung Lichtgeschmiedetes Eisen.\n\nDieses Metall ist wertvoll für uns, da Gegenstände, die daraus gefertigt werden, mit heiliger Wahrheit zuschlagen. Wenn Ihr Morbent Fel entgegentreten wollt, dann werdet Ihr eine solche Waffe brauchen.\n\nGeht zum Hafen von Menethil und sprecht mit meinem zwergischen Kollegen Glorin Steelbrow. Wenn dieses verlorene Metall überhaupt gefunden werden kann, dann weiß er, wo man danach suchen muss.", progress = nil, completion = "Lichtgeschmiedetes Eisen ist ein wertvolles Metall, aber es scheint, als hättet Ihr eine schreckliche Aufgabe vor Euch. Ihr seid weit gereist, Bruder. Mit Glück findet Ihr aber gerade das, was Ihr sucht!\n\nUnd falls Ihr das Eisen findet: Ich kenne da jemanden, der es zu einer Waffe gegen den Totenbeschwörer im Dämmerwald, von dem Ihr redet, formen kann.", rewards = "Ihr bekommt:\n\n"},
[271] = {title = "Vyrins Rache", objective = "Tötet Old Sooty und zeigt Daryl dem Jüngling in der Weitschreiter-Lodge dann Euer Werk.", description = "Ihr seid nicht zufällig daran interessiert, es unserem ach so kühnen Kühnen ein wenig heimzuzahlen? Es schmerzt mich, das zu sagen, aber Daryl hat ein gewisses Talent.\n\nVor einem Jahr war ein großer Bär das Ziel der Weitschreiter-Lodge, aber keiner der Jäger hatte Glück mit ihm. Also dachte sich Daryl, er könnte sich mal an ihm versuchen. Das einzige, was er nach seinem Versuch vorweisen konnte, war die hässliche Narbe über seinem Auge.\n\nErlegt den Bären und ich bin mir sicher, dass sogar Daryl mal sprachlos wäre.\n\nDer Bär, Old Sooty, hält sich irgendwo in der Nähe seines Baus in den Hügeln über Thelsamar auf.", progress = "Ah, <Name>! Schon wieder hier? Zweifelsohne wart Ihr wieder auf der Jagd! Keine Sorge, es ist nicht schlimm, wenn Ihr ein paar Rückschläge einstecken müsst, davon werdet Ihr auf lange Sicht nur besser.\n\n... viel schlechter könntet Ihr ja sowieso nicht mehr werden...", completion = "Äh... was ist das da? Ein Bärenschädel, wie es aussieht.\n\n&lt;Er fährt unbewusst mit einem Finger an seiner Narbe entlang&gt;\n\nNun, das ist eine ziemlich interessante Beute, die Ihr da habt. Kann eigentlich nicht der Bär von damals sein...\n\n&lt;Seine Stimme verliert sich, und er fängt sichtbar an zu zittern.&gt;\n\nOh, nehmt das weg, nehmt es weg! Schafft dieses grausige Ding hier raus!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[272] = {title = "Prüfung des Seelöwen", objective = "Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserausdauer. Sprecht mit den Einwohnern von Moonglade, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.\n\nFormt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.\n\nBringt den zusammengefügten Anhänger zu Dendrite Starblaze nach Nighthaven in Moonglade.", description = "Für die zweite Prüfung benötigt Ihr die zwei Hälften, aus denen der Anhänger des Seelöwen besteht. Die eine Hälfte bezieht ihre Kraft aus der Beweglichkeit des Seelöwen-Aspektes beim Gleiten durchs Wasser; die andere Hälfte bezieht ihre Kraft aus der unglaublichen Ausdauer des Seelöwen-Aspektes. Druiden bedienen sich dieser beiden Eigenschaften gleichermaßen, um den Aspekt ihrer Wassergestalt zu verkörpern.\n\nSprecht mit den Bewohnern von Moonglade, um herauszufinden, wo sich die Teile befinden könnten, und bringt beide hierher, um sie miteinander zu vereinen. Bringt den Anhänger zu Dendrite Starblaze, wenn Ihr ihn geschaffen habt.", progress = "Habt Ihr Euren Anhänger geschaffen, auf dass ich ihn mir ansehen kann, <Name>? Falls Ihr Hilfe beim Aufspüren der Teile braucht, bittet am besten die örtliche Bevölkerung um Hinweise. Ihr werdet dabei nicht nur finden, was Ihr sucht, sondern habt außerdem noch einen guten Grund, dieses wunderbare und heilige Tal zu erforschen.", completion = "Ihr habt die Prüfung des Seelöwen erfolgreich beendet, &lt;Name&gt;... Glückwunsch.\n\nJede Teilaufgabe bei der Beschaffung des Anhängers zeigt, dass man sowohl Beweglichkeit als auch Ausdauer benötigt, um in Harmonie mit dem agieren zu können, was Ihr unter Wasser tun wollt. Keine der Eigenschaften kann ohne die andere existieren, und beide können nicht erreicht werden ohne Euren Willen, den Aspekt des Seelöwen in Euch aufzunehmen.\n\nMerkt Euch diese Lektionen gut und verlasst Euch auf sie, wenn Ihr Eure Wassergestalt erworben habt.", rewards = "Ihr bekommt:\n\n"},
[273] = {title = "Nachschub für die Ausgrabungsstätte", objective = "Sprecht mit Huldar.", description = "Es ist noch nicht zu spät, Ihr könnt gern losziehen und Huldar suchen. Er kann noch nicht sehr weit gekommen sein, denn so stark sie auch sein mögen, können Miran und Saean dennoch nicht allzu schnell laufen, wenn sie mit diesen Fässern vollgepackt sind.\n\nSie nehmen die übliche Route zur Ausgrabungsstätte, südwärts aus der Stadt raus und dann an der Krümmung des Lochs entlang.\n\nIhr solltet keine Probleme haben, sie zu finden, solange sie nicht bereits dort angekommen sind.", progress = nil, completion = "Hmpf, es wird mehr als einen Überfall durch die Dunkeleisenzwerge brauchen, um die Lieferungen zu stoppen!\n\nAber Saean... Ich hätte nie vermutet, dass er einer ihrer Sympathisanten ist. Wir arbeiten schon seit fast einem Jahr mit ihm zusammen... vielleicht habe ich die Anzeichen übersehen.\n\nNun ja, darüber werde ich später nachdenken.", rewards = "Ihr bekommt:\n\n"},
[274] = {title = "Eine dunkle Bedrohung", objective = "Ashlan Stonesmirk möchte, dass Ihr zum Chefingenieur Hinderweir zurückkehrt und ihn von der neuen Entdeckung in Kenntnis setzt.", description = "Dies ist kein gewöhnliches Sprengpulver. Seht diese winzigen Silberkristalle. Und der eindeutige Geruch! Es ist sonnenklar, dass es sich hier um Zephyriumpulver handelt. Zephyrium an sich ist harmlos. Aber wenn es nass wird, könnte es ganz Ironforge aus dem Berg sprengen.\n\nDie chemische Reaktion kann entschärft werden, indem man vier Komponenten mischt: Lauerergift, einen zerstoßenen Kristall der Mo'grosh, eine Krokiliskenträne und diese Entschärfungspaste. Jetzt geht und erklärt es Hinderweir, ehe es zu spät ist!", progress = "Was bringt Ihr da von Ashlan?", completion = "Eine Entschärfungspaste? Für Zephyrium? Oh Himmel!", rewards = "Ihr bekommt:\n\n"},
[275] = {title = "Schwärendes Land", objective = "Tötet 12 Moorkrabbler und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück.", description = "Ich weiß nicht warum, aber irgendetwas schwärt im Sumpfland. Moorkrabbler haben sich dort ausgebreitet. Sie sind wie kranke, fiebrige Blasen auf dem Land, und um das Fieber zu besiegen, müssen sie erledigt und dem Sumpf wieder zugeführt werden.\n\nDie Moorkrabbler watscheln mitten in den Wasserwegen des Sumpflandes herum.", progress = "Das Sumpfland weint noch, und die Moorkrabbler wüten noch. Kommt zurück, wenn Eure Aufgabe erledigt ist.", completion = "Das Leiden des Landes wurde durch Eure Taten gemildert, und dafür werde ich Euch belohnen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFen-BewahrerrobeWaldkettenpanzerPhytoklinge\n\nIhr bekommt außerdem:\n\n"},
[276] = {title = "Stapfende Pfoten", objective = "Tötet 15 Gnolle der Moosfelle sowie 10 Bastarde der Moosfelle und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück.", description = "Die Moosfellgnolle lebten viele Jahre friedlich im Sumpfland, aber in letzter Zeit wächst ihre Anzahl. Ihre Füße trampeln die Büsche und Blumen des Moores platt, und ihre garstigen Äxte schlagen zu viel Holz für ihre Feuer.\n\nSie befinden sich nicht mehr im Gleichgewicht mit dem Land. Wenn das Sumpfland überleben soll, müssen die Gnolle dezimiert werden.\n\nTötet 15 Gnolle der Moosfelle und 10 Bastarde der Moosfelle. Jagt sie im Süden, nahe dem Zwergentor von Algaz. Wenn Ihr das getan habt, kehrt zu mir zurück.", progress = "Eure Aufgabe steht noch an, junger <Klasse>.", completion = "Indem Ihr die Anzahl der Gnolle verringert habt, habt Ihr Euch um das Wohlergehen des Sumpflandes gekümmert. Obwohl mein Vertrauen in Euer Volk in der Vergangenheit belastet wurde, &lt;Volk&gt;, kann es vielleicht doch noch wieder hergestellt werden.", rewards = "Ihr bekommt:\n\n"},
[277] = {title = "Feuer-Tabu", objective = "Bringt Rethiel dem Sumpfhüter 9 kunstlose Feuersteine.", description = "Die Moosfelle fällen die Bäume des Sumpflandes und verwenden das Fleisch der Bäume, um sich mit Feuer zu wärmen. Ich werde diesen Schmerz nicht länger ertragen!\n\nEntledigt die Moosfelle ihrer kunstlosen Feuersteine, der Werkzeuge, die sie zum Feuermachen verwenden. Die meisten Moosfelle tragen diese Feuersteine bei sich, ausgenommen die kleineren Gnolle der Moosfelle und Bastarde der Moosfelle.", progress = "Habt Ihr die Feuermach-Werkzeuge der Gnolle?", completion = "... Danke. Ich werde diese Feuersteine zertrümmern und ins Meer werfen, auf dass sie nie wieder dazu verwendet werden können, lebendiges Holz zu verbrennen.", rewards = "Ihr bekommt:\n\nSchwammerl"},
[278] = {title = "Eine dunkle Bedrohung", objective = "Chefingenieur Hinderweir möchte, dass Ihr Lauerergift, einen Kristall der Mo'grosh und eine Krokiliskenträne besorgt.", description = "Fangt gleich damit an, die Stoffe zum Entschärfen zusammenzusuchen, <Name>. Lauerergift kann von den im Loch Modan heimischen Spinnen gewonnen werden. Krokiliskentränen findet man ebenfalls hier im Loch. Ein Kristall der Mo'grosh hingegen dürfte sehr schwierig zu bekommen sein. Die Oger im Nordosten bauen sie ab, aber die Kristalle sind ein sehr seltener Rohstoff.\n\nWir müssen einen Angriff der Dunkeleisenzwerge abwehren können! Kommt zurück, wenn Ihr alle erforderlichen Dinge zusammenhabt, und ich werde die Mixtur vorbereiten.", progress = "Habt Ihr die benötigten Dinge? Die Zeit drängt!!", completion = "Gerade rechtzeitig, &lt;Name&gt;!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[279] = {title = "Klauen aus der Tiefe", objective = "Tötet 12 Murlocs der Blaukiemen.\n\nErschlagt Gobbler und nehmt Euch seinen Kopf.\n\nBringt Gobblers Kopf zu Karl Boran in den Hafen von Menethil", description = "Murlocs kriechen aus den tiefen Wassern und bauen ihre Dörfer entlang der Küste. Sie überfallen unsere Fischer und Händler und müssen aufgehalten werden.\n\nEiner dieser Murlocs, Gobbler, streift mit den anderen Murlocs der Blaukiemen umher und plündert die Händler entlang der Straße aus, wobei sie sich danach immer in die Sicherheit der nahegelegenen Hütten zurückziehen. Unsere Händler sind in Gefahr, und wir sind bereit, für ihre Sicherheit zu zahlen.\n\nGobbler strolcht in der kleinen Bucht nördlich von hier herum. Findet ihn, erschlagt seine Artgenossen und bringt mir seinen Kopf.", progress = "Unsere Händler werden nicht sicher sein, bis wir Gobbler und diese Murlocs losgeworden sind.", completion = "Ah, gut gemacht, &lt;Name&gt;.\n\nBitte nehmt dies als Bezahlung für die Erfüllung Eures Vertrages mit der Handelsmarine.", rewards = "Ihr bekommt:\n\n"},
[280] = {title = "Eine dunkle Bedrohung", objective = "Chefingenieur Hinderweir will, dass Ihr zum Fuß des Dammes hinunterschwimmt, das Pulverfässchen ausfindig macht und die Entschärfungsmixtur hineinrührt, um eine Explosion zu verhindern.", description = "Heute habe ich einige Aufrührer der Dunkeleisenzwerge gesehen, die mit einem Fässchen in Richtung Damm geschwommen sind. Es waren keine Gebirgsjäger zur Hand, um sie aufzuhalten! Ich fürchte, sie haben das Zephyrium am Fuße des Dammes deponiert, und es könnte jede Minute hochgehen! Lasst mich diese ganzen Zutaten zur Entschärfungsmixtur zusammenmischen. Na bitte!\n\nIhr müsst jetzt diese Mixtur mitnehmen und in das Fässchen einrühren, bevor es zu spät ist! Beeilt Euch!", progress = "Der Deckel des Fässchens schraubt sich langsam ab.", completion = "Das Fässchen zischt ein wenig, als sich die Entschärfungsmixtur darin löst.", rewards = "Ihr bekommt:\n\n"},
[281] = {title = "Waren-Wiederbeschaffung", objective = "Durchsucht die Kisten und Fässer in den Murloclagern an der Küste.", description = "Vor nicht allzu langer Zeit wurde ein Handelsschiff, die Blind Princess, von Murlocs überfallen. Obwohl das Schiff unversehrt entkam, wurde ein Großteil seiner Fracht von den Kreaturen über Bord gezogen, darunter eine äußerst wertvolle Statuette von Terenas Menethil. Wir möchten, dass die Statuette geborgen wird.\n\nDurchsucht die Hütten der Murloc an der Küste nach Kisten, Fässern und anderen Spuren von verlorener Fracht. Findet die Menethil-Statuette und bringt sie mir wieder.", progress = nil, completion = "Diese Kiste ist mit klauenartigen Kratzern übersät und zeigt Spuren eines Wasserschadens. Das Aufbrechen enthüllt durchnässtes und verfaultes Stroh, als wäre etwas Wertvolles in dieser Kiste aufbewahrt worden. Ihr durchwühlt das Stroh...\n\n... und findet einen Arm voll rot gefärbter Flaschen.", rewards = "Ihr bekommt:\n\nHeiltrank"},
[282] = {title = "Senirs Beobachtungen", objective = "Sprecht mit Gebirgsjäger Thalos.", description = "Ich hatte ursprünglich vor, meinen Lehrling mit meinem Bericht zu meinem Bruder Senir zu schicken, aber ich würde mich viel besser fühlen, wenn er in etwas... verlässlicheren Händen wäre. Natürlich nur, wenn es Euch nichts ausmacht?\n\nHmm... Ihr müsstet den Tunnel nehmen, um nach Kharanos zu gelangen.\n\nSprecht mit Gebirgsjäger Thalos, bevor Ihr durch den Tunnel geht. Er ist mittlerweile vollständig von den Troggs überrannt.\n\nFolgt der Straße zurück nach Anvilmar und geht dann weiter nach Osten zum Tunnel. Thalos ist ganz in seiner Nähe stationiert.", progress = "Seid gegrüßt! Seid vorsichtig, <Name>, der Tunnel nach Dun Morogh ist mit Troggs verseucht und nicht sicher zu bereisen.\n\nWenn Ihr keine eiligen Geschäfte in Dun Morogh zu erledigen habt, möchte ich Euch bitten, hier in Anvilmar zu bleiben, bis der Tunnel wieder sicherer ist.", completion = "Hm, nun gut, wenn Whitebeard Euch mit wichtigen Geschäften nach Dun Morogh schickt, kann ich Euch ja schlecht aufhalten, oder?\n\nLasst mich Euch wenigstens ein paar Ratschläge und Anweisungen geben.", rewards = "Ihr bekommt:\n\n"},
[283] = {title = "Eine dunkle Bedrohung", objective = "Die Entschärfungsmixtur scheint gewirkt zu haben. Kehrt zu Chefingenieur Hinderweir zurück und berichtet ihm die guten Neuigkeiten.", description = "Das Fässchen zischt ein wenig.", progress = nil, completion = "Vielen, vielen Dank, &lt;Name&gt;! Ihr habt den Stonewroughtdamm gerettet! Ohne Eure Hilfe hätten die Terroristen der Dunkeleisenzwerge bestimmt für den Untergang dieses mächtigen Wahrzeichens gesorgt. Mit Eurer Tapferkeit habt Ihr das Königreich und die Allianz stolz gemacht, &lt;Klasse&gt;.\n\nDer Damm ist wieder sicher ... zumindest vorläufig ...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZwergischer BaumhackerDornenklinge\n\nIhr bekommt außerdem:\n\n"},
[284] = {title = "Die Suche geht weiter", objective = "Sucht nach der Menethil-Statuette.", description = "Ihr durchsucht gründlich diese Ansammlung von Murlochütten, findet aber keine Spur von der Menethil-Statuette.\n\nVielleicht gibt es in einer der beiden nahe gelegenen Hütten im Norden und Nordosten mehr Hinweise.", progress = nil, completion = "Dieses Fass ist weitgehend unberührt. Als Ihr es öffnet...\n\n... schlägt Euch der stechende Geruch von Käse entgegen. Er ist etwas feucht, aber immer noch schmackhaft!", rewards = "Ihr bekommt:\n\nZwergenmild"},
[285] = {title = "Suche in weiteren Hütten", objective = "Sucht weiter in den Hütten der Murlocs nach der Menethil-Statuette.", description = "Dieses Grüppchen Murlochütten offenbart auch nach einer gründlichen Überprüfung nichts.\n\n... Aber Ihr seid Euch sicher, dass der nächste Anhaltspunkt, den Ihr findet, nützlich sein wird.\n\nEine der Hütten nördlich von hier muss die Menethil-Statuette enthalten!", progress = nil, completion = "Dieses Fass ist unter Schlamm und Gras halb begraben...", rewards = "Ihr bekommt:\n\n"},
[286] = {title = "Rückgabe der Statuette", objective = "Bringt Karl Boran die Menethil-Statuette.", description = "Nachdem Ihr das Fass aus dem Dreck gezogen und geöffnet habt, findet Ihr eine in dünnes Stroh eingepackte, silbrige Figur. Sie stellt einen jungen, langhaarigen Paladin mit erhobenem Hammer dar.\n\nDies kann nur die Menethil-Statuette sein! Ihr müsst sie nun zu Karl Boran in den Hafen von Menethil zurückbringen.", progress = "Habt Ihr die Statuette?", completion = "Der Kapitän der Blind Princess wird erleichtert sein zu hören, dass seine kostbare Fracht geborgen wurde. Ihr habt Euch diesen Lohn durch die geleisteten Dienste wohl verdient.\n\nEs tut gut, verlässliche Leute wie Euch zu kennen, insbesondere in so beschwerlichen Zeiten wie diesen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRute des EiszapfensMatrosen-Stiefel\n\nIhr bekommt außerdem:\n\n"},
[287] = {title = "Höhle der Frostmane", objective = "Erforscht die Höhle der Frostmane und tötet 5 Kopfjäger der Frostmane für Senir Whitebeard in Kharanos.", description = "Ich bin mit meinem Bericht etwas im Rückstand und könnte Eure Hilfe brauchen, <Name>. Ich habe gerade herausgefunden, wo sich die Trolle verschanzt haben, aber ich habe so viele Trolle gesehen, dass ich mich nicht getraut habe, hineinzugehen.\n\nWas ich von Euch möchte, ist Folgendes: Geht runter zur Höhle, schaut Euch ein wenig darin um, tötet ein paar Trolle und kommt dann wieder hierher zurück.\n\nNehmt die Straße nach Norden, raus aus Kharanos. Sobald Ihr an der Brücke ankommt, folgt dem zugefrorenen Fluss westwärts, bis Ihr den Iceflowsee erreicht. Am linken Ufer werdet Ihr Brewnall vorfinden. Die Höhle liegt südwestlich des Dorfes.", progress = nil, completion = "Ah, &lt;Name&gt;! Ich hätte nicht gedacht, dass Ihr Probleme hättet, dorthin zu finden. Meine Richtungsangaben sind vortrefflich, wisst Ihr...\n\nLasst mich gerade noch schnell meinen Bericht fertig stellen.\n\n\n\nHier! Nun, haha, ja, das ist jetzt wirklich lustig... Kann ich davon ausgehen, &lt;Name&gt;, dass es Euch nichts ausmachen würde, mir einen letzten Gefallen zu tun?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWarme WinterrobeStein-Rundschild\n\nIhr bekommt außerdem:\n\n"},
[288] = {title = "Die Dritte Flotte", objective = "Spendiert dem ersten Maat Fitzsimmons einen Krug Met.", description = "Ich war einst erster Maat auf der HERRIN DER MEERE, einem Linienschiff der dritten Flotte von Kul Tiras, der verlorenen Flotte. Verloren deshalb, weil die Flotte auf ihrer letzten Reise von roten Großdrachen angegriffen wurde. Großdrachen, die von Orcs beherrscht wurden!\n\nWir hatten keine Chance gegen das Drachenfeuer... und unsere Flotte ging just vor dieser Küste hier brennend unter. Ich bin der einzige Überlebende von diesen armen Schiffen.\n\n... Oh, mir brummt der Schädel! Ich werde einen frischen Drink brauchen, wenn ich mit diesem Kater klarkommen und meine Geschichte fortsetzen soll.", progress = "Oh, ich bin so furchtbar durstig! Wollt Ihr diesem armen, mitleiderregenden Trottel nicht einen Drink spendieren?", completion = "Ah! Das ist genau das richtige und lockert die Zunge. Danke, Kumpel!", rewards = "Ihr bekommt:\n\n"},
[289] = {title = "Die verfluchte Crew", objective = "Vernichtet 13 verfluchte Seeleute, 5 verfluchte Matrosen und den ersten Maat Snellig. Bringt Snelligs Schnupftabakdose zum ersten Maat Fitzsimmons im Hafen von Menethil.", description = "<Gestärkt setzt Fitzsimmons seine Geschichte fort...>\n\nIch bin der einzige Überlebende der unglückseligen dritten Flotte von Kul Tiras, die vor der Küste im Norden vernichtet wurde. Aber obwohl ich das einzige Mitglied der Flotte bin, das noch atmet, bin ich nicht der einzige, der noch herumläuft! Denn auf einem unserer Schiffe war ein großer und schrecklicher Schatz versteckt, und dessen unheimliche Macht hält die Seelen meiner Brüder in den verrottenden Wracks gefangen.\n\nWenn Ihr allerdings einige meiner Brüder befreien könnt, könnt Ihr vielleicht auch den Fluch brechen, der auf ihnen lastet.", progress = "Ich kann manchmal in meinen Träumen das unselige Stöhnen meiner Brüder hören! Bitte, guter Herr, befreit sie von ihren Fesseln und lasst ihre Schreie verstummen.", completion = "Ich danke Euch, &lt;Name&gt;. Und den Dank meiner verfluchten Brüder habt Ihr ebenfalls.", rewards = "Ihr bekommt:\n\n"},
[290] = {title = "Brechen des Fluchs", objective = "Besorgt den Geldkassettenschlüssel der INTREPID von Kapitän Halyndor.\n\nVerwendet den Schlüssel, um die Geldkassette der INTREPID zu öffnen.", description = "Um den Fluch zu brechen und alle meine Brüder zu befreien, müsst Ihr das... Ding... das auf meinem Schiff verstaut ist, bergen und reinigen! Ich weiß nicht, was es war, aber ich weiß, dass es sicher in der Geldkassette des Schiffs verwahrt wurde, zu dem nur Kapitän Halyndor den Schlüssel hatte.\n\nMein alter Kapitän erscheint mir immer noch in meinen Träumen. Ich bin mir sicher, dass er auf meinem untergegangenen Schiff, der INTREPID, herumläuft. Besorgt Euch den Schlüssel von ihm und öffnet damit die Geldkassette der INTREPID.\n\nAnschließend, wenn Ihr das verfluchte Ding habt, bringt es zu Glorin Steelbrow, dem Priester, hier in der Stadt.", progress = "Diese Truhe ist sicher verschlossen.", completion = "Der Schlüssel ist verrostet, passt aber einwandfrei ins Schloss.", rewards = "Ihr bekommt:\n\n"},
[291] = {title = "Die Berichte", objective = "Überbringt Senator Barin Redstone in Ironforge Senirs Bericht.", description = "Wunderbar! Überbringt Senator Barin Redstone meinen Bericht. Er ist ein missmutiger Geselle, also stört Euch nicht an seinem wenig sonnigen Gemüt. Er ist in Ironforge, in der Halle, in der König Magni Hof hält.\n\nIhr kennt den Weg nach Ironforge nicht? Nehmt die Straße aus Kharanos heraus nach Norden, überquert die Brücke und folgt dann der Straße nach Osten den Berghang hinauf. Einige große Banner flankieren diese Straße.\n\nAch ja, und könntet Ihr es vielleicht vermeiden, zu erwähnen, dass Ihr mir geholfen habt? Ich kann die ja nicht glauben lassen, ich würde hier draußen nicht hart arbeiten, nicht wahr?", progress = "Hmm... Es scheint, als würden meine Wachen neuerdings jeden Bittsteller durchlassen. Nun, was wollt Ihr? Fasst Euch kurz.", completion = "&lt;Er überfliegt das Dokument.&gt;\n\nVollmacht des KÖNIGS!? Hat Magni jetzt völlig den Verstand verloren? Und dieser schändliche Whitebeard... hat die Dinge selbst in die Hand genommen, was? Der Senat wird nicht erfreut sein, hiervon zu hören, nicht das kleinste bisschen.\n\nWas, Ihr seid immer noch hier? Geht, bevor ich die Wachen rufe!", rewards = "Ihr bekommt:\n\n"},
[292] = {title = "Das Auge von Paleth", objective = "Bringt Glorin Steelbrow das verfluchte Auge von Paleth.", description = "In der offenen Truhe erblickt Ihr eine geschwärzte Kugel, die in einem gruseligen Licht pulsiert. Dies ist der Schatz, von dem Fitzsimmons gesprochen hat: ein verfluchtes Auge von Paleth.\n\nBringt das verfluchte Auge von Paleth zum Zwergen-Priester Glorin Steelbrow im Hafen von Menethil. Fragt ihn, wie man den Fluch des Auges brechen kann.", progress = "Dieser Säufer Fitzsimmons hat Euch zu mir geschickt? Nun, Ihr könnt ihm sagen, dass ich kein Ale übrig habe. Er wird wohl jemand anderes anbetteln müssen!", completion = "Ein Auge von Paleth? Erstaunlich! Hmm... irgendetwas stimmt nicht mit diesem hier. Ihr habt es auf einem der Schiffswracks gefunden? Das erklärt einiges! Allerdings... wusste ich gar nicht, dass sie in der dritten Flotte ein solches Auge hatten... \n\nKein Wunder, dass Fitzsimmons so verängstigt war. Ein verfluchtes Auge von Paleth ist kein Grund zur Fröhlichkeit.", rewards = "Ihr bekommt:\n\n"},
[293] = {title = "Die Reinigung des Auges", objective = "Bringt Erzbischof Benedictus das verfluchte Auge von Paleth. Ihr findet Benedictus in der Kathedrale des Lichts, in der Stadt Stormwind.", description = "Ich kann den Fluch nicht von dem Auge von Paleth nehmen. Die Augen wurden von Menschen-Priestern hergestellt, daher werdet Ihr nach Stormwind gehen müssen, um jemanden zu finden, der Euch helfen kann. Sprecht mit Erzbischof Benedictus. Er steht der Kathedrale des Lichts in Stormwind vor. Er kann helfen.\n\nDas hoffe ich jedenfalls, um euretwillen.", progress = "Was habt Ihr da für eine Kugel? Sie sieht so... befleckt aus.", completion = "Ein Auge von Paleth. Aber dieses hat viel Leid gesehen... es muss Zeuge einer schrecklichen, grauenhaften Tragödie gewesen sein.\n\nLasst es mich reinigen, denn die Augen wurden geschaffen, um hell zu erstrahlen, und ihre Kräfte können sehr gefährlich sein, wenn sie wie dieses hier besudelt sind.", rewards = "Ihr bekommt:\n\nAuge von Paleth"},
[294] = {title = "Ormers Rache", objective = "Ormer Ironbraid von der Whelgars Ausgrabungsstätte möchte, dass Ihr 10 scheckige Kreischer und 10 scheckige Raptoren tötet.", description = "Die Lage ist ernst, soviel ist sicher. Als wir diese Knochen freigelegt haben, hat das die Raptoren angelockt. Diese dreckigen Bestien haben meine Brüder getötet und mich, Merrin und den armen Ausgrabungsleiter hier festgesetzt.\n\nHelft mit, das Sumpfland von diesen Raptoren zu säubern, <Name>. Scheckige Raptoren und Scheckige Kreischer befinden sich direkt westlich der Klippe hier. Tötet jeweils 10, wenn Ihr könnt.\n\nDas wäre ein guter Anfang für die Rache, die ich mir für sie ausgedacht habe.", progress = "Tötet 10 Scheckige Raptoren und 10 Scheckige Kreischer, <Name>. Meine Mitarbeiter hatten das Schicksal nicht verdient, das ihnen zuteil wurde. Es ist an der Zeit, die Rechnung zu begleichen.", completion = "Töten ist ein schmutziges Geschäft, aber Ihr habt Eure Sache gut gemacht, &lt;Name&gt;. Wenn ich nicht dazu verpflichtet wäre, hier beim Ausgrabungsleiter und Merrin zu bleiben, würde ich an Eurer Seite da unten Blut vergießen.", rewards = "Ihr bekommt:\n\n"},
[295] = {title = "Ormers Rache", objective = "Ormer Ironbraid möchte, dass Ihr 10 scheckige Sensenklauen- und 10 scheckige Scharfzahnraptoren tötet und dann zu ihm zu Whelgars Ausgrabungsstätte zurückkommt.", description = "Es ist an der Zeit, diese abscheulichen Raptoren ihren Blutdurst bereuen zu lassen. Gleich da unten gibt es Dutzende von scheckigen Sensenklauen- und Scharfzahnraptoren. Lasst diese scheußlichen Kreaturen bezahlen, indem Ihr 10 von jeder Sorte erschlagt.", progress = nil, completion = "Ihr habt beim Aufräumen unter diesen Raptoren phantastische Arbeit geleistet, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[296] = {title = "Ormers Rache", objective = "Ormer Ironbraid von der Whelgars Ausgrabungsstätte möchte, dass Ihr Sarlatan tötet und mit einer seiner Krallen zu ihm zurückkehrt, sobald Ihr die Aufgabe erledigt habt.", description = "Während Ihr da unten wart, ist mir aufgefallen, dass eines der Biester aus der Menge herausstach. Es war größer und bedrohlicher. Ich könnte wetten, das ist derjenige, der die anderen hierher geführt hat und für die Störung der Ausgrabungsstätte verantwortlich ist.\n\nIch erbitte eine letzte Aufgabe von Euch, <Name>. Sorgt dafür, dass Sarlatan seine gerechte Strafe erhält. Und wenn man die Schwere seiner Verbrechen bedenkt, bedeutet Gerechtigkeit in diesem Falle den Tod! Bringt mir eine seiner Krallen als Beweis, dass er tot ist.", progress = "Ist Sarlatan tot? Seid Ihr dem Andenken der Gefallenen gerecht geworden?", completion = "Danke, &lt;Name&gt;. Eure Anstrengungen hier werden nicht in Vergessenheit geraten. Viele unschuldige Zwerge starben an dieser Stätte, während sie einfach nur ihrer Arbeit nachgingen. Die Rache, die Ihr über diese bösen Kreaturen gebracht habt, sollte dafür sorgen, dass sie es sich zweimal überlegen, bevor sie je wieder König Magnis Untertanen angreifen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRaptor-ExRaptorbannrüstungAusgrabungsrute\n\nIhr bekommt außerdem:\n\nRezept: Seltsam schmeckendes Omelett"},
[297] = {title = "Götzen sammeln", objective = "Bringt Magmar Fellhew 8 verzierte Steingötzen.", description = "Vor einer Weile, kurz bevor die Troggs in der Stätte auftauchten, hatten wir eine große Anzahl seltsame, verzierte Götzen gefunden. Leider hatten wir keine Gelegenheit, sie zu untersuchen, denn kurz nach ihrer Entdeckung haben uns die Troggs aus den Ruinen verjagt. Und diese Götzen haben eine seltsame Wirkung auf die Troggs. Sie verfallen dadurch in Raserei!\n\nBringt mir 8 Götzen - ich möchte sie studieren, und ich will sie nicht mehr in den Händen der Troggs sehen. Ihr könnt die Götzen bei den Troggs finden, die die Stätte heimsuchen.", progress = "Habt Ihr die Götzen? Wir müssen sie studieren und Ironforge von unseren Ergebnissen berichten!", completion = "Ihr habt sie! Gut gemacht, &lt;Name&gt;!\n\nUnd Ihr seht nicht einmal besonders angeschlagen aus, trotz all der wild gewordenen Troggs. Ich werde Euch im Auge behalten... Ihr seid viel versprechend.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZwergischer FlammensteckenTrogg-SchnitzlerThelsamaraxt\n\nIhr bekommt außerdem:\n\n"},
[298] = {title = "Bericht über den Fortschritt der Ausgrabungen", objective = "Bringt Ironbands Fortschrittsbericht zu Jern Hornhelm in Thelsamar.", description = "Ich muss einen Fortschrittsbericht nach Thelsamar schicken - einen Fortschrittsbericht und eine Neufassung meiner Anfrage nach mehr Sprengpulver! Hier ist der Bericht. Bringt ihn Jern Hornhelm. Er ist unser örtlicher Kontaktmann in Thelsamar.\n\nKeine schwierige Aufgabe, aber sie muss erledigt werden.", progress = "Oh, ein Fortschrittsbericht von der Stätte? Sehr gut!", completion = "Pah! Ironband hat Probleme mit den Troggs. Ich frage mich, ob er das Sprengpulver will, um ihm bei seinen Ausgrabungen zu helfen oder um ihn bei seinen Bemühungen gegen die Trogg-Bestien zu unterstützen...\n\nNun ja, so oder so ist das gute Pulver sinnvoll eingesetzt!\n\nEs ist allerdings etwas seltsam, dass ich ihm vor ein paar Wochen eine Menge Sprengpulver geschickt habe. Ich frage mich ja, wo das hingekommen ist...", rewards = "Ihr bekommt:\n\n"},
[299] = {title = "Enthüllung der Vergangenheit", objective = "Ausgrabungsleiter Whelgar wünscht, dass Ihr die Ausgrabungsstätte nach den 4 fehlenden Tafel-Fragmenten durchkämmt, Ados, Modr, Golm und Neru.", description = "Kurz vor der Invasion habe ich eine große Schrifttafel gefunden, die man den Goazstein nennt. Der übersetzte Text reißt an 4 Stellen ab. Der Text spricht von einem \"göttlichen Plan\" und einer \"schicksalhaften Prophezeiung\".\n\nIch fürchte, uns läuft die Zeit davon. Ich bin zu alt, um hinunterzugehen und diesen Bestien zu trotzen. Aber Ihr seid stark.\n\nDurchkämmt die Ausgrabungsstätte und sucht die 4 fehlenden Tafelfragmente: Ados, Modr, Golm und Neru. Sucht sie in alten Artefakten oder dort, wo das Erdreich locker ist. Bringt sie mir, auf dass ich damit beginnen kann, ihre Geheimnisse zu enträtseln!", progress = "Habt Ihr die vier Fragmente bereits gefunden, <Name>? Ados, Modr, Golm und Neru...", completion = "Ah, der Goazstein ist vollständig! Ausgezeichnete Arbeit, &lt;Name&gt;. Wirklich ausgezeichnete Arbeit. Jetzt kann ich mit der kniffligen Übersetzung dieser Titanenschrift weitermachen. Ich kann bereits neue Worte erkennen! Hmm... es heißt hier \"Alte Götter... angekettet unter dem Land\". Dies ist der Anfang von etwas Epischem.", rewards = "Ihr bekommt:\n\nSeidenmantel von Gamn"},
[301] = {title = "Meldung in Ironforge", objective = "Bringt Ironbands Fortschrittsbericht zu Ausgrabungsleiter Stormpike.", description = "Wir werden eine Bewilligung brauchen, um Ironband mehr Sprengpulver zu beschaffen. Ihr müsst seinen Bericht zum Hauptquartier der Forscherliga in Ironforge bringen.\n\nHier ist der Bericht. Gebt ihn Ausgrabungsleiter Stormpike und vergesst nicht, Euch zu ducken, nachdem Ihr ihn abgeliefert habt. Stormpike ist ein Hitzkopf, und es wird ihn nicht erfreuen, wenn er von Ironbands langsamem Vorankommen an der Ausgrabungsstätte hört.\n\nIhr findet Stormpike in der Versammlungshalle der Forscher.", progress = "Wir Stormpikes lassen uns nicht gern von unbedeutenden Angelegenheiten stören, <Klasse>. Ich hoffe, Ihr bringt Neuigkeiten, die meine Aufmerksamkeit verdienen.", completion = "Verflucht sei Ironband! Ich habe ihm schon vor Wochen eine Ladung Sprengpulver geschickt, aber er erwähnt es nicht mal in diesem Bericht.\n\nAlso... wo ist das Sprengpulver hin?!?", rewards = "Ihr bekommt:\n\n"},
[302] = {title = "Pulver für Ironband", objective = "Sprecht in Thelsamar mit Jern Hornhelm.", description = "Wenn Ironband immer noch Sprengpulver braucht, dann, bei Magni, soll er es haben! Ich habe die Bewilligung bereits mit einem Boten nach Thelsamar zu Jern Hornhelm vorausgeschickt. Er wird das Pulver und andere Vorräte zum Transport zu Ironband bereitstellen.\n\nAch, und noch was: Ich will, dass Ihr persönlich dafür Sorge tragt, dass diese Pulverlieferung ihren Bestimmungsort erreicht. Die letzte kam nicht an, also haltet Euren Verstand wach und Eure Augen offen.", progress = nil, completion = "Was? Stormpike will, dass Ihr die Lieferung persönlich zu Ironband bringt?\n\nIch... denke, das geht in Ordnung, aber das Problem ist, dass ich Huldar bereits mit den Trägern Miran und Saean losgeschickt habe. Ihr habt sie gerade verpasst, sie sind vor einer kurzen Weile erst aufgebrochen.", rewards = "Ihr bekommt:\n\n"},
[303] = {title = "Der Dunkeleisenkrieg", objective = "Motley Garmason in Dun Modr möchte, dass Ihr 15 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge tötet.", description = "Der Krieg tobt daheim ebenso wie in der Fremde. Während mächtige Zwergenkrieger im Namen der Allianz in weit abgelegenen Gegenden ihr Leben lassen, fallen unsere eigenen Gebiete den bösen Taten der Dunkeleisenzwerge zum Opfer. Sie haben den Thandol-Übergang verwüstet. Dun Modr fiel kurz darauf.\n\nIhr müsst Kräfte sammeln und die Front zurückdrängen. Wenn Ihr 15 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge töten könnt, dann kommen die Reserven vielleicht rechtzeitig, um den Vormarsch zu beenden.\n\nUnd jetzt beeilt Euch!", progress = "Roggo konnte keinen Kontakt zu den Reserven herstellen. Wir müssen offensiven Druck auf dieses Lager der Dunkeleisenzwerge ausüben, <Klasse>. Und jetzt geht wieder da raus und erfüllt Eure Pflicht König Magni gegenüber!", completion = "Ihr habt Eure Befehle gut ausgeführt, &lt;Klasse&gt;. Ihr habt bewiesen, dass Ihr ein tapferer Soldat und loyaler Diener König Magnis' seid, und dafür bewundere ich Euch. Durch den Druck, den Ihr auf das Lager der Dunkeleisenzwerge ausgeübt habt, haben wir jetzt eine Chance, sie für immer aus unseren Landen zu vertreiben... wenn nur die verdammte Reserve endlich auftauchen würde...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[304] = {title = "Eine grausige Aufgabe", objective = "Tötet Balgaras den Niederträchtigen und bringt Longbraid dem Grimmigen vor Dun Modr sein Ohr.", description = "Viele meiner Soldaten fielen in der Schlacht von Dun Modr. Mein eigener Bruder kam um, als die Westbrücke über dem Thandol-Übergang zerstört wurde. Jawohl, die Dunkeleisenzwerge sind eine teuflische Brut. Soweit Roggo das in Erfahrung bringen konnte, ist der Anführer dieses Verbrecherpacks im Sumpfland ein Hexenmeister namens Balgaras der Niederträchtige. Er ist allerdings ein ziemlicher Feigling. Er kommandiert seine Soldaten herum, bleibt aber selbst im Hintergrund, jegliche Gefahr meidend.\n\nWenn Ihr diesen rückgratlosen Abschaum finden könnt, erschlagt ihn und bringt mir sein Ohr. Ich werde Euch dafür entlohnen, <Klasse>.", progress = "Konntet Ihr Balgaras den Niederträchtigen schon aufspüren, <Klasse>? Er weicht uns schon eine ganze Weile aus.", completion = "Balgaras der Niederträchtige ist endlich tot. Wenn sein Tod auch die vielen unschuldigen Zwerge nicht zurückbringt, die sinnlos durch seine Hand starben, so wird dies doch zum Seelenfrieden derer beitragen, die überlebt haben. Nachdem Balgaras nun tot ist, sollte es ein Leichtes sein, mit dem restlichen Dunkeleisenpack fertig zu werden. Jetzt müssen wir den Abschaum auslöschen, bevor ein neuer Anführer in diese Gegend entsandt wird.\n\nIhr habt Eure Sache gut gemacht, &lt;Klasse&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGoldlöwenschildGelassenheitsring\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[305] = {title = "Auf der Suche nach dem Ausgrabungstrupp", objective = "Tarrel Rockweaver möchte, dass Ihr zur Ausgrabungsstätte reist und dort Kontakt mit Merrin Rockweaver aufnehmt.", description = "Wie schön, Ihr müsst der Späher sein, den Longbraid zu schicken versprach. Ihr könnt Euch nicht vorstellen, wie besorgt ich war.\n\nMeine Frau, Merrin, hat mir im letzten Monat jede Woche Briefe geschickt. Sie gehört zum Whelgar-Ausgrabungstrupp. Aber es sind fast zwei Wochen seit unserem letzten Briefwechsel vergangen. Irgendetwas ist bestimmt schief gelaufen!\n\nLongbraid versprach, dass er einen Späher schicken würde, der sich dort mal umsieht, wenn wir nicht bald etwas vom Trupp hören. Ich nehme mal an, dieser Späher seid Ihr, <Name>. Findet Merrin in der Ausgrabungsstätte im Osten!", progress = nil, completion = "Oh, dank sei den Himmeln, dass Ihr hier seid!", rewards = "Ihr bekommt:\n\n"},
[306] = {title = "Auf der Suche nach dem Ausgrabungstrupp", objective = "Kehrt mit Merrins Nachricht zu Tarrel Rockweaver zurück.", description = "Es war grauenhaft! Wir hatten einige seltene Artefakte enthüllt und fingen an, welche von diesen großen Knochen zu finden.\n\nBevor wir wussten, wie uns geschah, überrannten diese Scheckigen Raptoren die Ausgrabungsstätte. Viele ließen ihr Leben.\n\nOrmer hier rettete - ganz tapfer - den Ausgrabungsleiter und mich. Er verteidigte uns, während wir Schutz suchten. Jetzt sind wir gefangen. Und unsere harte Arbeit liegt in Trümmern.\n\nHier, nehmt diese Nachricht mit zurück zu meinem süßen Tarrel. Sie wird ihm die Situation klarmachen.", progress = "Habt Ihr Merrin gefunden? Hat sie eine Nachricht geschickt?", completion = "Welch grausige Neuigkeiten! Immerhin haben 3 von ihnen überlebt. Doch wann wird das Töten endlich aufhören? Ich sehne mich nach dem Tag, an dem König Magnis Untertanen ohne Angst leben können.", rewards = "Ihr bekommt:\n\n"},
[307] = {title = "Schmutzige Pfoten", objective = "Geht zur Silberbachmine und sucht 4 Sätze Bergarbeiter-Ausstattung zusammen.\n\nKehrt dann zu Gebirgsjäger Stormpike zurück.", description = "Die Silberbachmine im Osten hat sich schon vor langer Zeit erschöpft. Sie wurde vom Bund der Bergarbeiter in ein Lagerhaus umgewandelt, aber jetzt sind dort Kobolde eingezogen und befingern mit ihren schmutzigen Pfoten gute zwergische Werkzeuge!\n\nWir werden dieses Ungeziefer noch früh genug ausmerzen, aber der Bund wünscht, dass jemand ihre Gerätschaften aus der Mine schafft, bevor wir Krieger da reinstürmen und was kaputtmachen. Das wird ein harter Abstieg – Ihr solltet vielleicht Unterstützung mitnehmen.\n\nDie Ausstattung wird in Kisten des Bergarbeiterbunds über die Mine verteilt aufbewahrt. Viel Glück.", progress = "Habt Ihr die Bergarbeiter-Ausstattung, <Name>?", completion = "Habt Ihr da drin viele Kobolde gesehen? Ich kann den Befehl, sie aus der Mine zu werfen, kaum erwarten. Der Gedanke daran, wie ihre schmutzigen Hände in unserer Mine herumkratzen, verursacht mir Bauchschmerzen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nEisenherzkettenhemdRobe des BewahrersEisenplattenrundschild\n\nIhr bekommt außerdem:\n\n"},
[308] = {title = "Jarvens Ablenkung", objective = "Hmpf! Hier steht so viel Alkohol herum, aber ich habe strikte Befehle, ihn nicht anzurühren. Wenn ich nur einen Schluck unseres Donnerbiers bekommen könnte... das würde meinen Verstand anregen, ehrlich!", description = nil, progress = "Hmpf! Hier steht so viel Alkohol herum, aber ich habe strikte Befehle, ihn nicht anzurühren. Wenn ich nur einen Schluck unseres Donnerbiers bekommen könnte... das würde meinen Verstand anregen, ehrlich!", completion = "Für mich? Ihr seid ein wahrer Held, &lt;Name&gt;!", rewards = nil},
[309] = {title = "Beschützen der Fracht", objective = "Stellt sicher, dass sowohl Miran als auch seine Warenlieferung sicher an der Ausgrabungsstätte ankommen und setzt dann Ausgrabungsleiter Ironband davon in Kenntnis.", description = "Bereit zum Aufbruch, <Name>?\n\nAls Erstes müssen wir dieses Pulver zu Ironband bringen. Für mich allein wäre es zu viel zu tragen und diese Gegend kann gefährlich werden - und wer weiß, was diese Dunkeleisenzwerge noch für mich bereithalten?\n\nIch werde mich viel besser fühlen, wenn Ihr mitkommt.", progress = nil, completion = "Oh, gelobt sei das Licht, dass das Pulver hier ist. Allerdings bringt Ihr auch Besorgnis erregende Neuigkeiten. Wenn ich nur daran denke, dass die Dunkeleisenzwerge Sympathisanten haben, die solches Material für ihre heimtückischen Pläne beschaffen können.\n\nDoch das ist eine Angelegenheit, um die sich jemand anderes zu gegebener Zeit kümmern muss. Ich muss dieses Pulver einer guten Verwendung zuführen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGroßknecht-GürtelMatschstampfer\n\nIhr bekommt außerdem:\n\n"},
[310] = {title = "Bittere Rivalen", objective = "Vertauscht im Keller der Brauerei Donnerbräu in Kharanos ein Fass Donnerbier mit einem Fass Gerstenbräu.", description = "Ich muss zugeben, diese Donnerbräus stellen ein paar gute Getränke her. Aber sie müssen noch lernen, dass ihres nicht das einzige ordentliche Gebräu ist! Vielleicht könnt Ihr mir helfen, ihnen diese Lehre zu erteilen...\n\nHier, nehmt dieses Fass mit Gerstenbräu. Schleicht Euch in den Keller der Brauerei Donnerbräu in Kharanos und vertauscht es mit einem ihrer Fässer Donnerbier. Dann werden wir ja sehen, ob ihre Kundschaft mein Gebräu lieber mag als ihres!\n\nAch ja, und falls die Fässer bewacht sein sollten, müsstet Ihr eventuell den Wächter irgendwie ablenken...", progress = "Die Datumsangabe auf diesem Fass legt nahe, dass es demnächst angestochen werden wird.", completion = "Schnell stellt Ihr Marleths Fass voll Gerstenbräu zwischen die Fässer der Brauerei Donnerbräu.", rewards = "Ihr bekommt:\n\n"},
[311] = {title = "Rückkehr zu Marleth", objective = "Bringt Marleth Gerstenbräu in Brewnall das Fass mit Donnerbier.", description = "Nachdem Ihr ein Fass von Marleths Gerstenbräu im Keller der Brauerei Donnerbräu abgestellt habt, schnappt Ihr Euch zum Beweis ein Fass Donnerbier...", progress = "Habt Ihr den Austausch vollzogen?", completion = "Nicht schlecht, &lt;Name&gt;! War es schwierig, an der Wache vorbeizukommen?\n\nEgal - vielen Dank, und wenn Ihr jemals ein Starkbier mit Pepp haben wollt, denkt an die Gerstenbräus!", rewards = "Ihr bekommt:\n\n"},
[312] = {title = "Tundra MacGranns gestohlene Vorräte", objective = "Holt Tundra MacGranns Trockenfleisch aus dem gestohlenen Fleisch-Spind in der Höhle von Eisbart dem Alten.", description = "Ich hatte einen Monatsvorrat Trockenfleisch gesalzen und für die kalte Jahreszeit weggeschlossen. Weggeschlossen deshalb, damit die Bären nicht rankommen! Aber während ich unterwegs auf der Jagd war, hat sich diese Bestie, Eisbart der Alte, mit meinem Fleisch-Spind davongemacht. Er wird allerdings nicht durch das Thorium kommen. Ich wiederum werde verhungern, wenn ich mein Fleisch nicht wiederbekomme.\n\nIhr seht verstohlener aus als ich. Vielleicht könnt Ihr meinen Vorrat wiederbeschaffen? Ich würde es mit meinem steifen Bein niemals schnell genug in die Höhle hinein und wieder heraus schaffen.", progress = "Habt Ihr es geschafft, an den Inhalt meines Fleisch-Spindes ranzukommen, <Name>?", completion = "Was für eine gute Seele Ihr doch seid, &lt;Name&gt;! Dank Eurer Tapferkeit werde ich nicht hungern müssen, wenn in der kalten Jahreszeit die Schneestürme toben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchmiedeeiserne ArmschienenWollfäustlinge\n\nIhr bekommt außerdem:\n\n"},
[313] = {title = "Der altgediente Bau", objective = "Sammelt 8 Wendigomähnen und bringt sie Pilot Stonegear.", description = "Nicht jeder ist dazu geschaffen, eine Belagerungsmaschine zu fahren. Dazu braucht man eine eiserne Hand und Nerven aus Stahl... zum Glück besitze ich beides! Wie steht's mit Euch? Wie groß ist euer Talent? Wollt Ihr es mir nicht zeigen?\n\nWie auch immer... ich versuche gerade, meine Maschine, Trollplow, etwas gemütlicher zu machen. Wie wäre es, wenn Ihr mir einen Haufen Wendigomähnen aus dem altgedienten Bau westlich von Kharanos besorgt? Diese Mähnen könnten einen tollen Teppich für das Innendeck abgeben!", progress = "He, <Name>. Wart Ihr schon im altgedienten Bau? Diese Wendigos können ziemlich heftig sein.", completion = "Oh ja, diese Mähnen sind genau richtig! Ihr zeigt viel Schneid, &lt;Klasse&gt; - ich wette, man kann noch viele großartige Taten von Euch erwarten.", rewards = "Ihr bekommt:\n\n"},
[314] = {title = "Die Herde beschützen", objective = "Rudra Amberstill möchte, dass Ihr Vagash erschlagt und einen seiner Fangzähne zu ihr auf die Widder-Ranch bringt.", description = "Wir haben mitten in der Nacht die Schreie gehört. Heute morgen fehlten der Herde dann tatsächlich zwei Widder. Diese heimtückische Bestie, Vagash genannt, hat sich über unsere Existenzgrundlage hergemacht. Da der Großteil von König Magnis Armee irgendwo in weit entfernten Landen an der Seite der Allianz kämpft, ist niemand mehr da, der Vagash in Schach halten könnte.\n\nVielleicht seid Ihr tapfer genug, die Bestie aufzuspüren und zu erschlagen. Bringt mir einen Fangzahn der Bestie, und ich werde Euch belohnen. Vagash lauert direkt oberhalb der Ranch hier, aber seid gewarnt, die Bestie ist tödlich.", progress = "Vagash terrorisiert immer noch die Herde! Bitte helft uns, indem Ihr die elende Bestie umbringt.", completion = "Sehr gut gemacht! Veron wird begeistert sein, wenn er die gute Nachricht vernimmt. Vagash zu töten, kann keine leichte Aufgabe gewesen sein. Ich schätze, Ihr werdet eines Tages Seite an Seite mit König Magnis Mannen an der Allianzfront kämpfen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRancher-BeinkleiderWeiche LedertunikaColdridge-Hammer\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[315] = {title = "Das Perfekte Starkbier", objective = "Bringt Rejold Gerstenbräu in Brewnall 6 Schimmerkräuter.", description = "Ich bin von einem Vorhaben besessen, dem Vorhaben, das perfekte Starkbier herzustellen. Ich weiß, dass ich es schaffen kann - das Brauen liegt mir im Blut. Ich muss nur das richtige Rezept finden...\n\nWeit oben in den Bergen im Osten bauen die Trolle der Frostmane eine Pflanze an, Schimmerkraut genannt. Sie verwenden sie in ihren seltsamen Stammesritualen. Wir Zwerge haben bisher keine wirkliche Verwendung dafür gefunden, aber sie hat einen einzigartigen Geschmack... und ich möchte damit in meinen Gebräuen herumexperimentieren.\n\nBesorgt mir etwas Schimmerkraut von den Sehern der Frostmane oder klaut es aus den Schimmerkrautkörben der Trolle.", progress = "Habt Ihr das Schimmerkraut? Ich habe eine Fuhre Starkbier so gut wie braufertig und möchte das Kraut versuchsweise in diese Mischung mit hineinwerfen.", completion = "Großartig! Ich kann es kaum erwarten, sie in einigen meiner Rezepte auszuprobieren. Ich glaube, in ein bestimmtes würde es wunderbar hineinpassen...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZiegenfell-UmhangEfeuband-Armschienen\n\nIhr bekommt außerdem:\n\n"},
[317] = {title = "Vorräte für Jetsteam", objective = "Sammelt 4 Brocken Eberfleisch und 2 dicke Bärenfelle und liefert sie bei Pilot Bellowfiz in Steelgrills Depot ab.", description = "Ich bereite mich gerade darauf vor, eine Mission für die Belagerungsbrigade in Angriff zu nehmen. Sie wird ziemlich lange dauern, und ich muss Jetsteam mit Vorräten für einen ganzen Monat beladen. Könntet Ihr also nicht, während Steelgrill an meinem Panzer arbeitet, ein wenig für mich auf die Jagd gehen?\n\nIch werde ein paar Pelze als Bettzeug und etwas Eberfleisch zum Essen brauchen. Ihr könnt das Fleisch von Ebern und die Pelze von Bären erbeuten... Ihr findet beide in den Schneefeldern südlich des altgedienten Baus.", progress = "Die Vorbereitungen laufen gut. Wie geht es mit der Jagd voran?", completion = "Bei Magnis Bart, Ihr habt wirklich ganz schön viel gejagt!! Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[318] = {title = "Immerschimmer", objective = "Besorgt von Rejold Gerstenbräu in Brewnall ein Fässlein Immerschimmer.", description = "Rejold Gerstenbräu experimentiert mit seinen Gebräuen. Ein paar davon schmecken gut, einige schlecht, und einige... nun, einige hauen selbst den stärksten Zwerg um.\n\nEr lebt in Brewnall, westlich von Kharanos, und ich will Immerschimmer, eines seiner Getränke. Es wird mich warmhalten, während ich in der Kälte unterwegs bin.\n\nAußerdem brennt das gesegnete Zeug so heiß, dass ich es in Jetsteams Brennofen kippen kann, um einen Energieschub zu erzeugen! Diese nette Taktik hat mich schon aus mehr als einer haarigen Situation gerettet.", progress = nil, completion = "Bellowfiz braucht etwas von meinem Immerschimmer? Hm... in Ordnung.", rewards = "Ihr bekommt:\n\n"},
[319] = {title = "Ein Gefallen für etwas Immerschimmer", objective = "Tötet 6 Eisklauenbären, 8 alte Klippeneber sowie 8 Schneeleoparden und kehrt dann zu Rejold Gerstenbräu nach Brewnall zurück.", description = "Ich habe ein Fässlein mit Immerschimmer zur Hand, aber... könnt Ihr mir einen Gefallen tun? Brewnall könnte ein wenig Hilfe gebrauchen gegen die wilden Tiere, die die nahegelegenen Schneefelder durchstreifen. Manchmal kommen sie sehr nah.\n\nWir haben keine Angst vor diesen Bären und Katzen und Ebern - kein Zwerg, der etwas auf sich hält, hätte das - aber wenn Ihr Euch für uns um diese Tiere kümmern könntet, hätten wir mehr Zeit für unser Handwerk und unsere Braukunst.", progress = "Habt Ihr Euch um die wilden Tiere gekümmert?", completion = "Danke, &lt;Name&gt;. Es wird angenehm sein, unser Handwerk auszuüben, ohne ständig irgendwelches Knurren und Schnauben vor dem Dorf zu hören.", rewards = "Ihr bekommt:\n\n"},
[320] = {title = "Rückkehr zu Bellowfiz", objective = "Gebt Pilot Bellowfiz in Steelgrills Depot das Fässlein mit Immerschimmer.", description = "Hier habt Ihr Euer Fässlein mit Immerschimmer, <Name>. Und wie gesagt, vielen Dank für die Jagd kürzlich.", progress = "Habt Ihr den Immerschimmer bekommen können?", completion = "Ja, das ist genau richtig. Ich denke, ich werde gleich mal eine Flasche aufmachen und einen Schluck zu mir nehmen...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nScharfe AxtKnorriger KurzstabCampingmesser\n\nIhr bekommt außerdem:\n\n"},
[321] = {title = "Lichtgeschmiedetes Eisen", objective = "Durchsucht das Wrack der FLYING OSPREY im Sumpfland.", description = "Diese Schiffswracks hier vor der Küste sind die verlorene dritte Flotte von Kul'Tiras, die während des letzten großen Krieges von roten Drachen verbrannt und versenkt wurde.\n\nDie Flotte stammte aus Lordaeron, bis auf ein Schiff, einen elfischen Zerstörer: die Flying Osprey. Es transportierte eine Ladung Lichtgeschmiedetes Eisen und schloss sich der dritten Flotte aus Sicherheitsgründen an. Welche Ironie, dass es von denselben Drachen versenkt wurde... \n\nGenug Geschichte. Die Flying Osprey liegt südlich vom Hafen von Menethil auf Grund. Wenn Ihr das Lichtgeschmiedetes Eisen darin finden könnt, bringt es zu mir.", progress = nil, completion = "Diese Truhe ist vollgesogen und seitlich aufgebrochen. Viele Klauenspuren verunstalten sowohl die Innen- wie auch die Außenseite der Truhe... als hätten Murlocs sie durchsucht und ihren Schatz gestohlen.\n\nDoch ganz tief in der Truhe versteckt findet sich ein einzelner Lichtschmiedeblock. Dummerweise werden noch viele weitere benötigt, wenn man genug Metall zusammenbekommen möchte, um eine Waffe daraus zu fertigen.", rewards = "Ihr bekommt:\n\nLichtschmiedeblock"},
[322] = {title = "Gesegnete Waffe", objective = "Bringt Grimand Elmore in Stormwind die Kiste mit Lichtschmiedeblöcken.", description = "Im Zwergendistrikt von Stormwind gibt es einen zwergischen Waffenschmied, der Lichtgeschmiedetes Eisen verarbeiten kann. Er heißt Grimand Elmore.\n\nIch habe das von Euch gefundene Eisen in eine Kiste gepackt. Bringt sie zu Grimand und erzählt ihm Eure Geschichte. Ich bin mir sicher, er wird jemandem, der auf einem Kreuzzug wie dem Euren ist, gefällig sein und Euch eine Waffe schmieden - eine Waffe, vor der sich sogar Morbent Fel fürchten wird.", progress = "Wie kann ich Euch behilflich sein, <Klasse>?", completion = "Das ist eine ganz schöne Geschichte, die Ihr da erzählt. Und dann habt Ihr auch noch Lichtgeschmiedetes Eisen! Ich habe seit Jahren nicht mehr mit dieser Art Eisen gearbeitet. Es wird mir eine Ehre sein, es erneut zu formen. Und Ihr müsst später mit der Geschichte Eurer Schlacht gegen den Totenbeschwörer zurückkehren.\n\nAber wir greifen den Dingen vor. Erstmal kümmen wir uns um Eure Waffe gegen Morbent Fel...", rewards = "Ihr bekommt:\n\n"},
[323] = {title = "Bewährungsprobe", objective = "Vernichtet 15 Skeletträuber, 3 Skelettheiler sowie 3 Skelettwärter und kehrt danach zu Sven zurück.", description = "Morbent Fel ist ein Totenbeschwörer und ein Verbündeter der dunklen Reiter. Ich würde Euch ja erlauben, Euch der Macht von Morbent Fel entgegenzustellen, aber ich werde Euch erst gegen diese widerwärtige Satanskreatur kämpfen lassen, wenn ich Eure wahre Stärke kenne.\n\nIhr habt mir Eure Tapferkeit bereits bewiesen, aber wenn Ihr dem Totenbeschwörer wirklich trotzen wollt, dann beweist Euer Geschick zuerst an seinen Dienern.", progress = "Kämpft hart, <Name>. Und verzweifelt nicht, denn die Verzweiflung ist die größte Waffe des Bösen.", completion = "Euer Kampfgeschick, &lt;Name&gt;, steht außer Frage. Eure Entschlossenheit könnte uns tatsächlich das Ende von Morbent Fel erleben lassen!", rewards = "Ihr bekommt:\n\n"},
[324] = {title = "Die verlorenen Blöcke", objective = "Sammelt 5 Lichtschmiedeblöcke und kehrt dann zu Glorin Steelbrow im Sumpfland zurück.", description = "Nachdem Ihr den einzelnen Lichtschmiedeblock aus der voll gelaufenen Kiste genommen habt, ist Euch klar, dass die Murlocs wohl den Rest gestohlen haben. Jagt die Murlocräuber in der Nähe des Wracks der Flying Osprey, um an das verloren gegangene Lichtgeschmiedetes Eisen zu kommen.", progress = "Habt Ihr das Lichtgeschmiedetes Eisen gefunden, das Ihr braucht?", completion = "Ah, Ihr habt es bekommen! Jetzt lasst uns dieses Lichtgeschmiedetes Eisen in eine nützliche Form hämmern, hm?", rewards = "Ihr bekommt:\n\n"},
[325] = {title = "Bewaffnet und bereit", objective = "Bringt Morbents Bann zu Sven im Dämmerwald.", description = "Hier ist die Waffe gegen die Satanskreatur, von der Ihr spracht. Ihr seid bestens vorbereitet, <Name>. Viel Glück, und ich freue mich schon darauf, von Eurer Ruhmestat zu hören!", progress = "Hallo, <Name>. Ihr wart nicht allzu lange weg, aber ich sehe ein Feuer in Euren Augen, das dort vorher noch nicht leuchtete.", completion = "Ah, das wird Sicherheit gegen die Satanskreatur Morbent Fel geben! Gut gemacht!\n\nIhr seid bereit. Morbent Fel wird fallen.", rewards = "Ihr bekommt:\n\n"},
[328] = {title = "Der versteckte Schlüssel", objective = "Verwendet den kleinen Messingschlüssel, um Buchhalter Herods Geldkassette zu öffnen.", description = "In den Berichten wird kein Wort über den Gefreiten Thorsen verloren, jedoch im Einband eines von Herods Geschäftsbüchern findet sich ein kleiner Messingschlüssel.\n\nUnd nach genauerem Studium seiner Notizen finden sich in den verschiedenen Dokumenten einige Verweise auf eine \"sichere Geldkassette\". Die Geldkassette befindet sich irgendwo innerhalb des Vorratslagers - des Höhlenkomplexes weiter hinten in Kurzens Truppenlager.\n\nWenn diese sichere Geldkassette gefunden wird und der kleine Messingschlüssel ihn öffnen kann, dann kann das Geheimnis um Thorsens Entdeckung vielleicht offenbart werden.", progress = "Die Geldkassette ist erstaunlich groß, mit Bronze beschlagen, sehr stabil gebaut und sehr schwer.", completion = "Als Ihr die Geldkassette öffnet, wird klar, dass dies der Ort ist, an dem Herod seine wertvolleren Münzen und Gegenstände aufbewahrt.", rewards = "Ihr bekommt:\n\nBuchmacherszepter"},
[329] = {title = "Der entlarvte Spion", objective = "Bringt die schlammverschmierte Notiz zu Lieutenant Doren im Rebellen-Lager.", description = "Unter den Wertgegenständen in der Geldkassette befindet sich eine schlammverschmierte, gekritzelte Notiz. Wenn sie auch kaum lesbar ist, so scheint es, als wäre es eine Abhandlung über den Gefreiten Thorsen. Sie beschreibt ausführlich seine Patrouillenrouten, mit wem er so spricht und wie er seine Zeit bei den Rebellen verbringt. Sie ist nur mit einem einzelnen Buchstaben unterschrieben: -M.\n\nDennoch muss, wer auch immer diese Notiz verfasst hat, stets in Thorsens Nähe gewesen sein. Wer auch immer diese Notiz verfasst hat, ist der Verräter im Rebellen-Lager.", progress = "Habt Ihr herausgefunden, wer von Thorsens Geheimnis wusste? Gibt es einen Verräter unter uns?", completion = "Danke, &lt;Name&gt;. Diese Notiz ist der Hinweis, den wir brauchen, um den Verräter aufzustöbern!", rewards = "Ihr bekommt:\n\n"},
[330] = {title = "Patrouillen-Pläne", objective = "Sprecht mit Corporal Sethman.", description = "Die Notiz, die Ihr mir gegeben habt, ist mit einem \"-M\" unterzeichnet... Ich weiß nicht, was das heißen könnte.\n\nAber... die Notiz sagt auch aus, dass diese Person letzte Woche die gleichen Patrouillenrouten wie Thorsen hatte. Also muss, wer auch immer mit Thorsen letzte Woche auf Patrouille war, der Verräter sein!\n\nGeht zu Corporal Sethman. Er kümmert sich um die Patrouillenpläne und wird Euch sagen können, wer mit Thorsen unterwegs war.", progress = nil, completion = "Oh, klar kann ich das für Euch überprüfen. Mal sehen... letzte Woche war es... \n\n... nun, es war Gefreiter Merle, der mit Thorsen eingeteilt war. Sie hatten die gesamte letzte Woche die gleichen Patrouillenzeiten.", rewards = "Ihr bekommt:\n\n"},
[331] = {title = "Meldung bei Doren", objective = "Sprecht mit Lieutenant Doren.", description = "Wollte Lieutenant Doren, dass Ihr Euch mit diesen Patrouillen-Informationen wieder bei ihm meldet?", progress = nil, completion = "Es schmerzt mich, herauszufinden, dass es Merle war, der uns verraten hat. Er war immer ein tapferer Soldat, und ich dachte, sein Herz sei rein. Aber es ist eine große Erleichterung, dass Ihr ihn entlarvt habt - mit einem Spion wie ihm unter uns... würden wir Colonel Kurzen nicht lange standhalten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDschungelwandler-SandalenFrostmetallschulterstücke\n\nIhr bekommt außerdem:\n\n"},
[332] = {title = "Weinladen-Werbung", objective = "Geht zum Weingut Gallina und gebt Suzetta Gallina den Wein-Gutschein, um eine kostenlose Flasche Wein zu erhalten.", description = "Wenn Ihr Euch mit irgendwem über Weine unterhaltet, werdet Ihr erfahren, dass wir Gallinas die besten Weine in ganz Stormwind verkaufen. Wir sind auch nicht weit weg, immer noch innerhalb des Handelsdistrikts entlang der herrlichen Kanäle der Stadt.\n\nHier, nehmt dieses Flugblatt. Bringt es meiner Schwester Suzetta in unseren Laden, und Ihr erhaltet eine Gratis-Flasche unseres berühmten Pinot Noir. Ihr werdet es nicht bereuen!", progress = "Seid gegrüßt und fühlt Euch willkommen, edler Herr. Habt Ihr schon einmal einen unserer ausgezeichneten Weine versucht?", completion = "Ah, Ihr wart also bei Renato? Na dann, hier, bitte, werter Herr. Eine Flasche unseres außergewöhnlichen Pinot Noir. Ihr werdet nirgendwo in Azeroth etwas Vergleichbares finden.", rewards = "Ihr bekommt:\n\nFlasche Dalaran Noir"},
[333] = {title = "Harlan braucht Nachschub", objective = "Geht zur Schneiderei und Anpasserei am Kanal und bringt Rema SchneiderHarlan Bagleys Kleidungs-Auftrag.", description = "Wir hatten hier in der letzten Zeit viel Betrieb. Es scheint so, als wollte wirklich jeder Rüstungen und robuste Kleidung kaufen. Als würden alle eine kalte, harte Jahreszeit erwarten... \n\nAber das sind alles Zukunftssorgen. Meine heutige Sorge ist eher, dass mir die gestrickten Kleidungsstücke ausgehen. Ich brauche eine weitere Fuhre von unserem Lieferanten.\n\nWenn Ihr diesen Auftrag zu Rema Schneider in die Schneiderei und Anpasserei am Kanal bringen könntet, währe ich Euch sehr dankbar.", progress = "Ihr bringt Nachricht von Herrn Bagley?", completion = "Hier steht, dass Harlans Geschäfte florieren. Das sind gute Neuigkeiten, aber ich frage mich, wozu die Leute all diese Rüstungen brauchen. Ich habe nichts von einem Krieg gehört... gibt es da etwas, was uns die Adligen nicht erzählen?\n\nNun gut, danke, dass Ihr die Anfrage überbracht habt. Hier ist Eure Bezahlung, und ich werde dafür sorgen, dass Harlan seine Lieferung erhält.", rewards = "Ihr bekommt:\n\n"},
[334] = {title = "Eine Lieferung für Thurman", objective = "Geht zum Konfektionsgeschäft Larson im Magierviertel von Stormwind und gebt Thurman Schneider sein Nähkästchen.", description = "Mein Sohn Thurman ist Lehrling beim Konfektionsgeschäft Larson im Magierviertel. Er hatte es heute etwas eilig und vergaß seine Schere und Nadeln. Ich weiß, ein großer <Klasse> wie Ihr hat bestimmt wichtige Aufgaben zu erledigen, aber ohne sein Handwerkszeug kann er seine Lehrarbeiten nicht erledigen!\n\nBitte, <Name>. Könnt Ihr meinem Sohn sein Nähkästchen vorbeibringen? Das Konfektionsgeschäft Larson ist einer von zwei Kleiderläden im Magierviertel - es ist das, das etwas weiter drin liegt, ganz in der Nähe des Magierturms.", progress = "Seid Ihr hier, um Kleidung zu kaufen?", completion = "Oh, verflucht! Ich dachte, wenn ich mein Nähzeug vergesse, muss ich heute nicht arbeiten. Ich schätze, jetzt muss ich den Larsons beim Nähen helfen... \n\nNa ja. Ich denke, das Vergnügen muss wohl noch etwas warten.", rewards = "Ihr bekommt:\n\n"},
[335] = {title = "Ein nobles Bräu", objective = "Zardeth Blackclaw möchte, dass Ihr ihm eine Tilloaträne aus Dunkelhain und eine Bisamwurzel aus dem Sumpfland bringt.", description = "Lord Wishock sorgt im Oberhaus ganz schön für Unruhe. Er wurde auf unseren kleinen \"Betrieb\" hier unten aufmerksam gemacht und propagiert jetzt eine genaue Untersuchung. Ich habe einen Plan, um Wishock... zu beschäftigen... aber ich benötige Eure Hilfe. \n\nEs gibt eine Blume, die in Stalvans Garten in den Außenbezirken von Dunkelhain wächst. Diese kleine weiße Blume ist als Tilloaträne bekannt. Ich werde außerdem eine Bisamwurzel brauchen, die man nur am Fuße des Wasserfalls tief unter dem Stonewroughtdamm im Sumpfland findet.", progress = "Wishock wird bald genug Unterstützung haben, um uns jede Menge Ärger zu machen. Habt Ihr es endlich geschafft, Euch die Tilloaträne oder die Bisamwurzel anzueignen?", completion = "Ganz exzellent! Dies sind wirklich sehr schöne Exemplare!", rewards = "Ihr bekommt:\n\n"},
[336] = {title = "Ein nobles Bräu", objective = "Bringt Lord Wishock in der Halle der Bittsteller das Blackclaw-Starkbier.", description = "Lord Wishock hat, wie alle Menschen, seine Schwächen. Bei seiner handelt es sich um eine Vorliebe für alkoholische Getränke. Seine Scheinheiligkeit ist verblüffend. Dieser spießige Trottel verbringt seine Tage damit zu versuchen, unsere kleine \"Taverne\" schließen zu lassen, während er seine Nächte im Obergeschoss zubringt und dabei Rechnungen anschreiben lässt, die er niemals bezahlt. Na, mal sehen, wie Wishock dieses besondere Gebräu schmeckt, das ich für ihn vorbereitet habe: Blackclaw-Starkbier. Es haut ziemlich rein, <Name>.\n\nBringt es ihm und seht, wie es ihm schmeckt. Höchstwahrscheinlich treibt sich der alte Trottel in der Halle der Bittsteller herum.", progress = "Seht Ihr nicht, dass ich beschäftigt bin? Meine Worte müssen gehört werden! Ich bin sehr wichtig für die Zukunft dieses Königreichs!\n\nOh... was habt Ihr denn da? Na, das sieht doch nach einem erfrischenden Getränk aus...", completion = "Ah, danke, dass Ihr mir dieses lecker aussehende Starkbier gebracht habt, Diener. Hier habt Ihr eine Kupfermünze. Und jetzt verschwindet aus meinem Blickfeld und lasst mich mein Getränk genießen.", rewards = "Ihr bekommt:\n\n"},
[337] = {title = "Ein altes Geschichtsbuch", objective = "Bringt das Buch: \"Die Geschichte von Stormwind\" in die Bibliothek von Stormwind zurück.", description = "Obwohl der Einband dieses Buches von Kratzern überzogen und von Schmutz verkrustet ist, kann man auf dem Buchrücken noch immer die Worte \"Die Geschichte von Stormwind\" lesen. Wenn man das Buch aufmacht, kann man das Siegel der Bibliothek von Stormwind erkennen, das deutlich auf der ersten Seite prangt.\n\nEs sieht so aus, als hätte jemand dieses Buch ausgeliehen, aber nie zurückgegeben.", progress = "Oh! Was ist denn das für ein altes Buch, was Ihr da habt? Kann ich es mal sehen?", completion = "Ach du liebe Güte! Dieses Buch hat zuletzt in diesen Regalen gelegen, noch bevor Stormwind vor vielen Jahren wieder aufgebaut wurde. Es muss natürlich restauriert werden, denn es ist in einem üblen Zustand, aber es wäre mir eine Ehre, es in unsere Sammlung seltener Bücher aufzunehmen.\n\nDanke, werter Herr. Bitte nehmt dies als Bezahlung dafür an, dass Ihr das Buch zurückgebracht habt.", rewards = "Ihr bekommt:\n\n"},
[338] = {title = "Die Grünen Hügel des Schlingendorntals", objective = "Sammelt die fehlenden Seiten des Manuskripts von \"Die Grünen Hügel des Schlingendorntals”. Wenn alle vier Kapitel vollständig sind, bringt sie zu Barnil zurück.", description = "Meister Nesingwary wird furchtbar wütend sein, wenn er das herausfindet!\n\nEr vertraute mir das Manuskript für seinen Roman, \"Die Grünen Hügel des Schlingendorntals\", zum Korrekturlesen an. Es lief auch alles glatt, aber dann wehte ein großer Windstoß durch das Lager und hat die Seiten überall verteilt.\n\nIch konnte die meisten Seiten wieder zusammensuchen, aber viele sind noch über den halben Dschungel verstreut. Sammelt die Seiten, mit denen man die vier Kapitel vervollständigen kann.\n\nIch werde Euch helfen, sie zu ordnen. Bringt mir die Kapitel zurück, wenn Ihr alle vier beisammen habt.", progress = "Habt Ihr die Kapitel bereits zusammengefügt, <Name>?", completion = "Ihr habt mir sicherlich einen Haufen Ärger erspart, &lt;Name&gt;! Ich kann Euch gar nicht genug danken. Es dürfte nun nicht mehr lange dauern, bis man Meister Nesingwarys Buch in Bibliotheken überall auf der Welt finden wird.", rewards = "Ihr bekommt:\n\nDschungel-StiefelDickes RüstungssetÜberragender Heiltrank"},
[339] = {title = "Kapitel I", objective = "Bringt Barnil Stonepot die Seiten 1, 4, 6 und 8 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals”, um Kapitel I zu vervollständigen.", description = "Kapitel I war ziemlich fesselnd! Meister Nesingwary baut den Hintergrund der Geschichte auf und erwähnt seine Jagdgefährten, mich eingeschlossen! \n\nAber das tut gerade nichts zur Sache. Lasst mich mal sehen, welche Seiten noch fehlen. So wie es aussieht sind die Seiten 1, 4, 6 und 8 immer noch irgendwo da draußen im Dschungel!", progress = "Ich nehme nicht an, dass Ihr es geschafft habt, die Seiten 1, 4, 6 und 8 aufzuspüren? Uns fehlen nur diese vier, um Kapitel I wieder zusammenzusetzen.", completion = "Endlich! Kapitel I ist vollständig!", rewards = "Ihr bekommt:\n\nDie Grünen Hügel des Schlingendorntals - Kapitel I"},
[340] = {title = "Kapitel II", objective = "Bringt Barnil Stonepot die Seiten 10, 11, 14 und 16 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals\", um Kapitel II zu vervollständigen.", description = "Kapitel II war voll gestopft mit aufregenden Geschichten von der Panther- und Tigerjagd. Ich könnte mir dafür in den Hintern treten, dass ich die Seiten habe davonfliegen lassen. \n\n Es sieht aus, als hätte ich alle Seiten wiedergefunden, bis auf die Seiten 10, 11, 14 und 16.", progress = "Wir brauchen immer noch die Seiten 10, 11, 14 und 16, um Kapitel II zu vollenden, <Name>.", completion = "Kapitel II ist endlich vollständig! Gut gemacht!", rewards = "Ihr bekommt:\n\nDie Grünen Hügel des Schlingendorntals - Kapitel II"},
[341] = {title = "Kapitel III", objective = "Bringt Barnil Stonepot die Seiten 18, 20, 21 und 24 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals”, um Kapitel III zu vervollständigen.", description = "Kapitel III gefiel mir am besten. Es erzählt von Sire Erlgadins und Lady Rouacks erstem Blattschuss mit einem Zwergen-Gewehr. Und am Ende von Kapitel III, Mann, solche eine Spannung! \n\nWenn ich das richtig sehe, brauchen wir noch die Seiten 18, 20, 21 und 24, um das Kapitel fertig zu stellen. Diese Seiten sind irgendwo da draußen...", progress = "Hattet Ihr Glück mit den Seiten 18, 20, 21 oder 24? Das sind die einzigen, die wir brauchen, um Kapitel III zusammenzusetzen.", completion = "Puh! Gute Arbeit, &lt;Name&gt;. Kapitel III ist jetzt wieder beisammen!", rewards = "Ihr bekommt:\n\nDie Grünen Hügel des Schlingendorntals - Kapitel III"},
[342] = {title = "Kapitel IV", objective = "Bringt Barnil Stonepot die Seiten 25, 26 und 27 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals\", um Kapitel IV zu vervollständigen.", description = "Ah, Kapitel IV; Das große Finale! Und was für ein Ende es war! \n\nUns fehlen nur drei Seiten aus diesem Kapitel. Wir brauchen die Seiten 25, 26 und 27, um Kapitel IV wieder zusammenzusetzen.", progress = "<Name>, wir brauchen nur drei Seiten, um Kapitel IV fertig zu stellen. Habt Ihr mittlerweile die Seiten 25, 26 oder 27?", completion = "Phantastisch! Jetzt haben wir Kapitel IV fertig!", rewards = "Ihr bekommt:\n\nDie Grünen Hügel des Schlingendorntals - Kapitel IV"},
[343] = {title = "Reden über Kraft", objective = "Geht in die königliche Bibliothek der Feste von Stormwind und sprecht mit Milton Sheaf. Er kann das Buch über Metallurgie für Euch finden, das Bruder Kristoff für seine Rede benötigt.", description = "Ich werde eine Rede über die Kraft des Geistes halten, und ich würde dazu gern einige Auszüge aus einem bestimmten Buch über Metallurgie zitieren - \"Belastbarkeit von Eisen\". Eine Abschrift dieses Buches dürfte sich in der königlichen Bibliothek der Burg Stormwind finden. Könnt Ihr es für mich holen? Wenn dem so ist, dann mögen die Segnungen des Lichts mit Euch sein!\n\nDie königliche Bibliothek ist sehr groß, aber der oberste Bibliothekar, Milton Sheaf, kennt jedes Regal, als wäre es sein eigenes Kind. Sprecht mit ihm, und er wird Euch das Buch holen.", progress = nil, completion = "Metallurgie? Oh ja, wir haben viele Bücher über dieses Thema, und wir helfen Bruder Kristoff gern mit seiner Rede! Nun sagt... welches Buch genau war das noch gleich, das der gute Bruder benötigt?", rewards = "Ihr bekommt:\n\n"},
[344] = {title = "Bruder Paxton", objective = "Sprecht mit Bruder Paxton in der Abtei von Nordhain.", description = "Belastbarkeit von Eisen? Ja, ich kenne das Buch. Ziemlich gut, vor einigen Jahrzehnten von dem Zwergenminenarbeiter Margulf Blaggon geschrieben. Er verbrachte den Großteil seines Lebens tief in den Bergen von Khaz Modan, Erze schürfend. Kluger Kerl!\n\nAber wo war ich doch gleich? Ach ja, die \"Belastbarkeit von Eisen\"! Ich fürchte, das Buch wurde in die Abtei von Nordhain verlegt. Der Verwalter der Bibliothek der Abtei, Bruder Paxton, wollte eine Kopie des Buches für seine eigenen Regale anfertigen.\n\nDas war allerdings vor Monaten. Ich frage mich, warum er so lange dafür braucht...", progress = nil, completion = "Herr Sheaf möchte wissen, wo sein Buch ist? Nun, das ist etwas peinlich. Ich habe das Buch, aber ich bin immer noch dabei, es abzuschreiben und daher noch nicht wirklich bereit, das Original wieder herzugeben.", rewards = "Ihr bekommt:\n\n"},
[345] = {title = "Tinten-Zutaten", objective = "Sprecht mit Großknecht Oslow in Seenhain und fragt ihn nach Rethbaneisenerz.", description = "Ich will meine Abschrift von \"Belastbarkeit von Eisen\" schon länger fertig stellen, aber... \n\nNun, ich stelle für die Bücher, die ich abschreibe, meine Tinte selbst her, versteht Ihr? Es handelt sich um mein eigenes Rezept. Sie verläuft nicht, sie schmiert nicht und sie trocknet sehr schnell. Dummerweise trocknet sie ein wenig zu schnell! Meine letzte Portion ist ausgetrocknet, bevor ich die Abschrift beenden konnte, und ich hatte bisher keine Gelegenheit, mehr Tinte herzustellen!\n\nUm mehr herzustellen, benötige ich Rethbaneisenerz aus dem Rotkammgebirge. Großknecht Oslow in Seenhain ist mein üblicher Lieferant.", progress = nil, completion = "Ihr braucht was?? Vielleicht ist es Euch nicht aufgefallen, aber wir sind damit beschäftigt, Seenhains Verteidigungsanlagen zu befestigen und die Schäden von den letzten Orcangriffen zu reparieren. Wenn Ihr Rethbaneisenerz braucht, dann müsst Ihr es Euch schon selbst holen!", rewards = "Ihr bekommt:\n\n"},
[346] = {title = "Rückkehr zu Kristoff", objective = "Kehrt zu Bruder Kristoff auf den Kathedralenplatz zurück. Gebt ihm das Buch: \"Belastbarkeit von Eisen\".", description = "Nachdem ich jetzt mit der Abschrift fertig bin, könnt Ihr das Original von \"Belastbarkeit von Eisen\" haben. Ich danke Euch für Eure Geduld, und wenn Ihr Milton seht, bitte sagt ihm, die lange Verzögerung täte mir Leid.", progress = "Konntet Ihr das Buch finden?", completion = "Das ist es! Danke, &lt;Name&gt;. Möge das Licht Euren Körper und Eure Seele hell erleuchten!", rewards = "Ihr bekommt:\n\nWanderungs-Stiefel"},
[347] = {title = "Rethbanerz", objective = "Sammelt 5 Fuhren Rethbanerz und bringt sie Bruder Paxton in der Bibliothek von Nordhain.", description = "Rethbanerz wurde nach dem Mann benannt, der es als Erster entdeckt hat, Bart Rethban. Wenn es geschmolzen wird, ist es nicht so stark wie Eisen, aber sein Erz hat eine dunkle, glatte Farbe, die einige Schreiber in ihren Farbtinten verwenden. Man kann es in den Rethbanhöhlen nördlich von hier finden.\n\nWir haben normalerweise etwas davon auf Lager, aber wir sind zu sehr damit beschäftigt, uns auf Orcangriffe vorzubereiten, als dass wir welches sammeln könnten. Und nur so nebenbei... In den Rethbanhöhlen leben jetzt Rotkammgnolle und deren Zwangsarbeiter bauen das Erz selbst ab.\n\nWenn Ihr also welches benötigt, müsst Ihr es Euch selbst besorgen.", progress = "Habt Ihr das Rethbanerz?", completion = "Oh, prächtig! Ich kann dieses Erz verwenden, um meine Farbtinte herzustellen, und kann dann die Abschrift von \"Belastbarkeit von Eisen\" fertig stellen.\n\nDanke, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[348] = {title = "Schlingendornfieber", objective = "Sucht Hexendoktor Unbagwa und lasst ihn Mokk den Wilden beschwören. Bringt das Herz von Mokk zu Fin Fizracket.", description = "Krank... so... furchtbar k-k-krank... \n\n... habe mich mit Schlingendornfieber angesteckt... tödliches V-v-virus... \n\n... einziges Heilmittel... wäre... wäre es... das Herz von M-m-m-mokk dem Wilden zu essen... schwer zu fassendes, weißes Wildtier... \n\n... Hexendoktor Unbagwa... Einziger, der es b-b-beschwören kann...\n\n... sucht Unbagwa... versteckte Höhle am südlichen Kap...\n\n... schnell... sterbe... sterbe...", progress = "... Mutter?\n\n... so kalt... \n\n... ich fahre hinab in den wirbelnden Nether... h-h-h-halt mich fest, Mutter...", completion = "... fühle die Kraft zurückkehren... \n\nWo bin ich? Booty Bay? Ach du meine Güte! Ich hatte einen seltsamen Traum... \n\n... die Schwäche hat mich nicht vollständig verlassen...", rewards = "Ihr bekommt:\n\nMedizindecke"},
[349] = {title = "Schlingendornfieber", objective = "temp text 02 - log", description = "temp text 02 - description", progress = "Hexendoktor Unbagwa wissen, was Mokk der Wilde mögen. Ja, ja!\n\nIch sprechen mit Geistern und lassen ihn herkommen, tue ich.\n\nAber andere Gorillabiester mögen Geistersprechen auch. Ihr beschützen Hexendoktor Unbagwa und ich lassen ihn herkommen.\n\nHexendoktor Unbagwa will erst etwas. Ihr bringen 10 Gorillafangzähne und ich fangen an Geistersprechen.", completion = "Hexendoktor Unbagwa gefallen Gorillafangzähne! Für Euch, ich reden mit Geistern. Lassen Mokk den Wilden kommen.\n\nIhr aber beschützen Hexendoktor Unbagwa vor anderen Gorillabiestern, oder kein Mokk für Euch!", rewards = nil},
[350] = {title = "Auf einen alten Freund verlassen", objective = "Sprecht mit Elling Trias in Stormwind.", description = "Marzon würde ein Mitglied der Defias kontaktieren und er hat Verbindungen zu Lescovar... \n\nDa van Cleef und Thredd tot sind, wäre es schwierig, einen Richtspruch gegen Lescovar zu erwirken, denn Eure Beweise sind wertlos ohne deren Zeugnis. Und dabei wird noch nicht einmal die Tatsache berücksichtigt, dass Lescovar ja ein Adliger ist und viele Beziehungen hat. Das stellt ihn gewissermaßen über das Gesetz.\n\nWir werden weitere Hilfe benötigen. Ich tu das nur äußerst ungern, aber ich kenne jemanden, der uns helfen wird. Ihr findet Trias im Handelsdistrikt der Stadt.", progress = nil, completion = "Macht Ihr Witze? Shaw bittet mich erneut um Hilfe? Der hat Nerven...\n\nDie Bruderschaft der Defias, sagt Ihr? Tja, Ihr seid wirklich der Überbringer wunderbarer Neuigkeiten, was? Als Nächstes werdet Ihr mir erzählen, dass Deathwing noch am Leben sei und die Stadt angreift.\n\nNa gut, erzählt mir alles von Anfang an. Und lasst nichts aus, was Euch vielleicht nicht wichtig erscheint. Ich muss alles wissen.", rewards = "Ihr bekommt:\n\n"},
[351] = {title = "Findet OOX-17/TN!", objective = "Bringt das Notsignal zum Leitroboter von Oglethorpe.", description = "Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zu Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.\n\n\"Mein Name ist Oglethorpe und mein Leitroboter ist verloren gegangen! Ich würde Euch belohnen, wenn Ihr ihn aufspürt! Bringt dem Roboter bitte diesen Signalgeber. Hervorragend, jetzt habe ich die Koordinaten für Euch berechnet! Er ist in der Nähe der Klaffenden Schlucht in Tanaris abgestürzt!\"", progress = "Ihr habt anscheinend das Wrack eines... Robothuhns entdeckt... Aus dem Ei erklingt wieder die rasselnde Stimme:\n\n\"Ja, hervorragende Arbeit! Das ist tatsächlich mein Leitroboter, aber meine Sensoren zeigen an, dass er Starthilfe benötigt, bevor er zur Reparatur nach Booty Bay zurückfliegen kann. Bitte legt den Signalgeber in den Rover. Der Signalgeber wird den Rest übernehmen!\"", completion = "Ihr legt das Ei... das Notsignal... in das Huhn... den Leitroboter.\n\nAus dem Roboter ertönt ein Brummen und Surren, als er versucht aufzustehen. Nachdem der Roboter zum Leben erwacht ist, ertönt die Stimme von Oglethorpe ein weiteres Mal, diesmal aus dem Inneren des Roboters:\n\n\"OOX-17/TN funktioniert endlich, aber es sind umfangreiche Reparaturen erforderlich! Er ist zu schwer, als dass Ihr ihn tragen könntet... aber ich glaube, ich habe eine Idee. Könntet Ihr noch etwas auf ihn aufpassen?\"", rewards = "Ihr bekommt:\n\n"},
[353] = {title = "Stormpikes Lieferung", objective = "Bringt das Päckchen für Stormpike zu Gebirgsjäger Stormpike am Loch Modan.", description = "Die Stormpikes sind ein geachteter Zwergenklan und bekannt für ihren feinen und kritischen Geschmack. Daher ist es nicht verwunderlich, dass Gringer Stormpike, ein Gebirgsjäger aus Ironforge, mich beauftragte, ihm eine Waffe zu schmieden.\n\nDie Waffe ist fertig, aber... Gebirgsjäger Stormpike ist weit weg, am fernen Loch Modan. Wenn Ihr ohnehin vorhabt, nordwärts zu reisen, könntet Ihr ihm dieses Päckchen überbringen?\n\nMeine letzte Nachricht von Gebirgsjäger Stormpike besagte, dass er im nördlichen Wachturm des Loch Modan stationiert ist.", progress = "Ihr seid den ganzen weiten Weg von Stormwind gekommen? Ich habe gehört, es wird da unten in den Menschenlanden dank herumlaufender Briganten und Orcs etwas brenzlig. An einem solchen Ort kann ein <Klasse> sich perfekt beweisen!", completion = "Aha! Grimand hat also endlich meine Axt fertig gestellt! Ich kann es kaum erwarten, sie an einigen Troggs und Kobolden auszuprobieren!\n\nVielen Dank, &lt;Name&gt;. Ihr habt für diese Lieferung eine weite Strecke zurückgelegt. Hier habt Ihr ein paar Münzen für eure Bemühungen.", rewards = "Ihr bekommt:\n\n"},
[354] = {title = "Todesfälle in der Familie", objective = "Bringt Coleman Farthing in Brill Gregors Überreste, Nissas Überreste und Thurmans Überreste.", description = "Die Familie Agamand war die wohlhabendste in Tirisfal. Ich habe früher in ihrer Mühle gearbeitet... vor der Seuche.\n\nAls die Geißel das erste Mal auftauchte, befestigten die Agamands ihre Heimstatt und überredeten ihre Angestellten zu bleiben und bei der Verteidigung zu helfen. Wir waren Narren, aber wir waren loyale Narren.\n\nDie Agamands haben uns in ihrem Stolz zum Untod verdammt. Und heute sind sie Diener der Geißel!\n\nDient den Verlassenen, indem Ihr die Agamands besiegt, die der Seuche zum Opfer fielen. Dient mir, indem Ihr mir ihre Überreste bringt.", progress = "Habt Ihr die sterblichen Überreste der Agamands? Sind diese verfluchten Bestien endlich vernichtet?", completion = "Rache hat einen süßen Geschmack, findet Ihr nicht? Als Ihr die Agamands vernichtet habt, habt Ihr da irgendeinen Hinweis auf einen freien Willen in ihnen bemerkt? Ich hoffe es. Ich hoffe, sie hatten Angst, bevor sie in die Vergessenheit zerschlagen wurden.\n\nDas ist eine närrische Hoffnung, ich weiß. Aber es ist dennoch eine Hoffnung, die ich hege.", rewards = "Ihr bekommt:\n\n"},
[355] = {title = "Gespräch mit Sevren", objective = "Sprecht mit Magistrat Sevren in Brill.", description = "Ihr habt mir die Überreste der Agamands gegeben und meinen Rachedurst gestillt. Aber Agamands Mühlen sind eine Bedrohung für alle Verlassenen, nicht nur für mich.\n\nIch habe mit Magistrat Sevren über Eure Heldentaten gegen die Agamands geredet, und er wünscht, mit Euch zu sprechen.", progress = nil, completion = "Coleman erzählt Gutes über Euch, &lt;Name&gt;, wenn er von Euren erfolgreichen Vorstößen in Agamands Mühlen spricht.\n\nDie Verlassenen brauchen Eure Talente erneut...", rewards = "Ihr bekommt:\n\n"},
[356] = {title = "Patrouille zur Rückendeckung", objective = "Tötet 8 blutende Schrecken und 8 wandernde Geister und meldet Euch dann wieder bei Linnea in ihrem Lager.", description = "Die Verteidiger auf dem Bollwerk, die Tirisfal vor den Pestländern schützen, sind immer wachsam. Aber manchmal schafft es die Geißel, an ihnen vorbeizuschlüpfen.\n\nUnser Erfolg am Bollwerk hängt an einer Ein-Fronten-Schlacht - wir können keinen Angriff von hinten zulassen, und noch weniger können wir zulassen, dass die Versorgungslinie unserer Verteidiger unterbrochen wird.\n\nUnterstützt das Bollwerk. Patrouilliert ostwärts und erschlagt alle Untoten, die Ihr findet. Seid auf Balnirs Bauernhof im Osten besonders gründlich. Es hat sich zu einem Zufluchtsort für eindringende Untote entwickelt.", progress = "Habt Ihr einen Bericht von Eurer Patrouille?", completion = "Sehr gut. Eure Anstrengungen helfen sehr dabei, die Geißel in Schach zu halten. Meinem Vorgesetzten, Exekutor Zygand, wird eine Empfehlung zugehen.", rewards = "Ihr bekommt:\n\n"},
[357] = {title = "Die Identität des Lichs", objective = "Bringt das Zauberbuch des Lichs zu Bethor Iceshard in Undercity.", description = "Es gibt einen Lich, der auf einer Insel im Blendwassersee im Norden haust. Obwohl er ein Verlassener mit freiem Willen ist, glaubt er, dass alle anderen Untoten Sklaven der Geißel sind, und hetzt seine Diener auf jeden, der sich ihm nähert.\n\nAber da er ein Verlassener ist, wird die Königin ihn haben wollen. Und wenn er in der Totenbeschwörung bewandert ist, dann wäre sein Wissen... recht nützlich für uns.\n\nUm etwas über seine Identität und sein Können herauszufinden, muss ich mir sein Zauberbuch ansehen. Stehlt Euch in sein Lager, verschafft es Euch und kehrt dann zu mir zurück.", progress = "<Name>, habt Ihr das Buch beschafft?", completion = "Sehr gut, &lt;Name&gt;. Ich werde dieses Buch studieren und die Identität des Lichs herausfinden. Ihr habt Eurer Königin gut gedient.\n\n\n\nErstaunlich! Das Buch, das Ihr besorgt habt, gehört keinem Geringeren als Gunther Arcanus!\n\nGunther war ein bewanderter Totenbeschwörer im Leben; er und ich waren Freunde und Waffengefährten, vor der Seuche. Und nach diesem Buch zu urteilen, wurde er im Tode noch mächtiger.\n\nSeine Fähigkeiten wären ein großer Segen für uns.", rewards = "Ihr bekommt:\n\n"},
[358] = {title = "Grabräuber", objective = "Tötet Grabräuber der Moderfelle und Bastarde der Moderfelle. \n\nBringt Magistrat Sevren in Brill 8 Einbalsamierungssekrete.", description = "Die Massengräber südwestlich von Garrens Schlupfwinkel weiter im Norden wurden geschaffen, um der... eindrucksvollen... Anzahl Todesfälle gerecht zu werden, die Tirisfal erlitt, als die Seuche zum ersten Mal über uns kam. \n\nDen Toten in diesen Gräbern blieb der Untod bisher erspart, aber die Geißel schickt jetzt Moderfellgnolle, um die Leichen einzusammeln, um sie zur Verstärkung ihrer Armeen einzusetzen. Das können wir nicht zulassen!\n\nIhr habt zweierlei Aufgaben: Erschlagt die Moderfelle am Massengrab und in Garrens Schlupfwinkel und nehmt Euch von ihnen das Einbalsamierungssekret, das ihnen Leben verleiht.", progress = "Ist Eure Aufgabe abgeschlossen? Habt Ihr diese Hundeviecher vernichtet und sie ihres Sekrets beraubt?", completion = "Meisterlich erledigt, &lt;Name&gt;. Die Geißel irrt sich, wenn sie denkt, dass sie diese Leichen gegen uns verwenden könnte, und die Flüssigkeit, die Ihr von den  der Moderfellsklaven gesammelt habt, wird von unseren Apothekern untersucht werden. Vielleicht enthält sie Geheimnisse, die wir gegen sie verwenden können.\n\nWie gesagt, gut gemacht. Aber unser Kampf geht weiter, und dieser Konflikt wird Euch sicher noch mehr Möglichkeiten bieten, den Verlassenen Euren Wert zu beweisen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKaltstahlstulpenZombiehaut-Stiefel\n\nIhr bekommt außerdem:\n\n"},
[359] = {title = "Verlassenen-Pflichten", objective = "Sprecht mit Todeswache Linnea.", description = "Ich brauche einen aktuellen Bericht von unserem Außenposten der Todeswache im Osten.\n\nIch muss wissen, ob mehr Streitkräfte der Geißel am Bollwerk vorbei und nach Tirisfal herein geschlichen sind. Unsere Wachsamkeit an der Grenze zu den Pestländern muss aufrechterhalten werden - wir können die Geißel hier nicht stärker Fuß fassen lassen!\n\nReist südwärts die Straße entlang und biegt an der Gabelung nach Osten zum Außenposten ab. Sprecht mit Todeswache Linnea. Sie hat die Informationen, die ich benötige.", progress = nil, completion = "Magistrat Sevren will einen Bericht? Nun gut: Die Verteidiger auf dem Bollwerk halten den Großteil der Geißel in Schach, aber gelegentlich schlüpfen ein paar durch. \n\nWir haben sporadisch Aktivitäten der Geißel östlich dieses Postens gesichtet, und diese häufen sich um Balnirs Bauernhof.", rewards = "Ihr bekommt:\n\n"},
[360] = {title = "Rückkehr zum Magistrat", objective = "Kehrt zu Magistrat Sevren nach Brill zurück.", description = "Kehrt jetzt zu Magistrat Sevren mit den Informationen zurück, die ich euch gegeben habe. Er wird sie so schnell wie möglich haben wollen, also sputet Euch.\n\nUnd solltet Ihr unterwegs welche von der Geißel sehen, schaltet sie aus - wir können sie nicht unbehelligt durch unser Land spazieren lassen.", progress = nil, completion = "Es ist beunruhigend zu hören, dass die Geißel am Bollwerk vorbeischlüpft. Der Lichkönig und seine Diener greifen uns unaufhörlich an.\n\nAber wir werden nicht nachgeben. Er wird nicht noch einmal von uns Besitz ergreifen!", rewards = "Ihr bekommt:\n\n"},
[361] = {title = "Ein nie zugestellter Brief", objective = "Findet Yvette Farthing und bringt Ihr den Brief von Thurman Agamand.", description = "Dies ist ein Brief, der von Thurman, dem ältesten Sohn von Gregor Agamand, geschrieben wurde. Er ist an Yvette Farthing adressiert, aber er scheint nicht bei ihr angekommen zu sein...", progress = "Ja?", completion = "Oh... mein armer Thurman! Ich habe ihn angefleht, Agamands Mühlen mit mir und meinem Vater zu verlassen, aber seine Familienbande waren zu stark! Und ich habe es genau gewusst! Ich wusste einfach, dass Brand ihm Böses wollte! Oh, verflucht seien diese Seuche und die Geißel!\n\n&lt;Yvettes Gesicht glättet sich und wird dann kalt.&gt;\n\nAber Selbstvorwürfe sind etwas für die Schwachen. Als eine Verlassene habe ich neue Ziele, und Liebe ist keines davon. Ich danke Euch, dass Ihr diesen Brief überbracht habt, denn ich hatte mich schon gefragt, was mit meiner alten Liebe geschehen war.\n\nDoch dieses Leben ist vorüber. Auf ewig.", rewards = "Ihr bekommt:\n\n"},
[362] = {title = "Die Spuk-Mühle", objective = "Erschlagt Devlin Agamand und bringt Devlins Überreste zu Coleman Farthing nach Brill.", description = "Devlin Agamand war der jüngere von zwei Söhnen der Familie Agamand und im Leben hätten sie unterschiedlicher nicht sein können. Thurman war groß und sanft, während sein jüngerer Bruder schwach und scharfzüngig war.\n\nAls Agamands Mühlen der Seuche anheim fielen, war ich nicht überrascht zu hören, dass Devlin ihr schnell erlag. Sein verrücktes Gebrabbel kann man heute noch nahe der Straße hören, die zu Agamands Mühlen führt.\n\nIch sammle die Überreste der Agamands und ich möchte den armen Devlin. Findet ihn, vernichtet ihn und bringt mir seine Knochen.", progress = "Habt Ihr Devlin gefunden?", completion = "Danke. Devlins Knochen werden eine gute Trophäe abgeben.\n\nWenn mein kaltes Herz überhaupt Wärme finden kann, dann in dem Wissen, dass die Agamands vernichtet sind. Sie haben mich und meine Familie im Stich gelassen, als die Seuche kam - jetzt schwöre ich, dass ich ihre Überreste unter meiner Sohle zermalmen werde!", rewards = "Ihr bekommt:\n\n"},
[363] = {title = "Unsanftes Erwachen", objective = "Sprecht mit Schattenpriester Sarvis.", description = "Wurde auch Zeit, dass Ihr aufwacht. Wir wollten Euch gerade mit den anderen ins Feuer werfen, aber es sieht so aus, als hättet Ihr es geschafft.\n\nIch bin Mordo, der Verwalter der Deathknell-Gruft. Und Ihr seid kein Sklave des Lichkönigs mehr.\n\nSprecht mit Schattenpriester Sarvis in der Kapelle am Fuße des Hügels, er wird Euch mehr über das erzählen, was Ihr wissen müsst.", progress = nil, completion = "Noch einer der wandelnden Toten, hm? Muss ein ziemlicher Schock gewesen sein, so in der Gruft aufzuwachen, wo es nur Kälte und Mordo gab, um Euch zu begrüßen... \n\nIch sehe Verwirrung in Eurem Gesicht. Lasst mich mal versuchen, Euch unsere... Situation... zu erklären.\n\nWir wurden durch unsere neue Anführerin, Lady Sylvanas, von der Kontrolle durch den Lichkönig befreit. Die dunkle Fürstin führt uns in unserem Krieg gegen die verhasste Geißel und die Bastionen der Menschheit, die jeden unserer Schritte verfolgen.", rewards = "Ihr bekommt:\n\n"},
[364] = {title = "Die Hirnlosen", objective = "Schattenpriester Sarvis will, dass Ihr 8 hirnlose Zombies und 8 elende Zombies tötet.", description = "Wir Verlassenen liegen im Krieg mit der Geißel, der Armee des Lichkönigs: durch Nekromantie erweckte Armeen von Untoten, grausige Bestien des Nordens und gepeinigte Schreckgespenster.\n\nDer nördliche Teil des Dorfes wurde von den Hirnlosen überrannt, und diese müssen vernichtet werden. Vernichtet sie, zeigt ihnen keine Gnade, auch wenn sie unsere früheren Brüder und Schwestern gewesen sein mögen. Die Gefallenen sind nichts als Sklaven des Lichkönigs.", progress = nil, completion = "Es ist schade, dass die Geißel nicht bei uns eingegliedert werden kann, denn ihre große Zahl wäre in den kommenden Schlachten sehr nützlich.\n\nDoch sie werden sich uns nicht anschließen, und daher haben wir keine andere Wahl, als sie zu vernichten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFlachshandschuheRamponierter Umhang\n\nIhr bekommt außerdem:\n\n"},
[365] = {title = "Felder des Kummers", objective = "Stehlt 10 Kürbisse vom Gehöft im Westen, direkt nördlich von Deathknell und bringt sie zu Apotheker Johann nach Brill.", description = "Was haben wir denn hier? Ihr seht wie ein Neuling aus, <Klasse>. Wenn Ihr darauf hofft, Euch der dunklen Fürstin zu beweisen, dann müsst Ihr die Gebräuche der Verlassenen erlernen.\n\nIm Westen werdet Ihr einen Hof vorfinden. Menschen suchen das Land heim wie Schimmel eine verrottende Leiche. Und um es noch schlimmer zu machen, patrouilliert ganz in der Nähe der Scharlachrote Kreuzzug von seinem Turm aus. Erteilt diesem Abschaum eine Lektion und stehlt 10 ihrer kostbaren Kürbisse.\n\nSobald Ihr 10 beisammen habt, bringt sie zu Apotheker Johaan nach Brill.", progress = "Todeswache Simmer ließ mich wissen, dass Ihr mich mit einigen dringend benötigten Reagenzien versorgen würdet. Habt Ihr bereits 10 Kürbisse gesammelt, <Name>?", completion = "Ihr habt Eure Befehle gut ausgeführt, &lt;Klasse&gt;. Ihr habt Euch als eine echte Hilfe für die Armee der dunklen Fürstin erwiesen.", rewards = "Ihr bekommt:\n\n"},
[366] = {title = "Rückgabe des Buches", objective = "Bringt Gunthers Zauberbuch zu ihm auf die \"Gunthers Zufluchtsort\" genannte Insel zurück.", description = "Vor langer Zeit waren Gunther und ich, wie auch der jetzt der Geißel dienende Totenbeschörer Thule Rabenklaue, Freunde und Schüler beim Kirin Tor, einer Magiergesellschaft in Dalaran.\n\nGunther und ich fielen beide der Seuche anheim, aber ich dachte, er wäre entweder tot geblieben oder für die Armee des Lichkönigs erweckt worden. Es tut gut zu wissen, dass er frei ist.\n\nWir müssen ihn für uns gewinnen. Ich habe einen Zauber auf dieses Buch gelegt, der ihm, sobald er ihn sieht, zeigen wird, dass ich ebenfalls frei vom Einfluss des Lichkönigs bin. Ich hoffe, dass er sich uns anschließt, wenn er das erfährt.", progress = "Eure Meister sind Narren, Euch hierher zu entsenden, denn ich werde niemals wieder ein Sklave der Geißel sein!", completion = "Mein Buch?!? Also wart Ihr der Dieb, der es stahl!\n\nDoch... was ist das für eine neue Verzauberung darauf... Bethor? Er ist in Lordaeron?\n\nWenn es ihn immer noch gibt, dann konnte er sich vielleicht ebenfalls dem Zugriff des Lichkönigs entziehen...", rewards = "Ihr bekommt:\n\n"},
[367] = {title = "Eine neue Seuche", objective = "Apotheker Johaan in der Stadt Brill möchte, dass Ihr 5 Phiolen Schattenhundblut sammelt.", description = "Lady Sylvanas hat sich an die königliche Apothekervereinigung gewandt. Die dunkle Fürstin glaubt, dass unser Wissen, gepaart mit der neuentdeckten Magie, der Schlüssel zu Arthas' Untergang sein wird. Sie hat uns aufgefordert, eine neue Seuche zusammenzubrauen, eine Seuche, tödlicher als jedes Leiden in ganz Azeroth. Diese neue Krankheit wird Arthas' Armee der Geißel ins Verderben stürzen.\n\nMeine Studien zeigen, dass das Blut von Bestien der Schlüssel sein könnte. Bringt mir 5 Phiolen Schattenhundblut, damit ich meine Theorie ausprobieren kann.", progress = "Habt Ihr 5 Phiolen Schattenhundblut gesammelt, <Name>? Die Zeit drängt!", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;, und ich danke Euch für Eure Mühen.", rewards = "Ihr bekommt:\n\nSchwacher Trollbluttrank"},
[368] = {title = "Eine neue Seuche", objective = "Apotheker Johaan in der Stadt Brill benötigt 5 Finsterflossenschuppen von den Murlocs in Tirisfal.", description = "Während Ihr unterwegs wart und Proben für mich gesammelt habt, haben meine Experimente ergeben, dass noch weitere Reagenzien benötigt werden, wenn sich diese Krankheit ordentlich ausbreiten soll. Ein paar unglückliche Opfer zu vergiften, ist eine Kleinigkeit. Eine ganze Welt erkranken zu lassen, erweist sich als etwas komplizierter.\n\nIch werde 5 Finsterflossenschuppen von den Murlocs in der Umgebung brauchen. Ihr findet die Kreaturen entlang der Küste im Norden oder Westen von hier.", progress = "<Name>, habt Ihr 5 Finsterflossenschuppen von den Murlocs beschaffen können?", completion = "Die Schuppen sind perfekt, &lt;Name&gt;. Genau das, was ich für dieses Gebräu brauche.", rewards = "Ihr bekommt:\n\nSchlummersand"},
[369] = {title = "Eine neue Seuche", objective = "Apotheker Johaan in der Stadt Brill möchte, dass Ihr ihm 4 Proben vom Gift eines heimtückischen Nachtwebers bringt.", description = "Während Ihr sammeln wart, habe ich einen alten Text in einem meiner Bücher entdeckt, der darauf hindeutet, dass eine uralte Seuche Tausende unschuldiger Opfer ausgelöscht hat. Man fand später heraus, dass der tödliche Erreger im Gift der Nachtweberspinnen erhalten blieb.\n\nBringt mir etwas Gift eines heimtückischen Nachtwebers, um dieses Experiment abzuschließen. Ich möchte sehen, ob das ansteckende Element des Giftes mit meinem neuen Gebräu harmoniert. Gerüchten zufolge leben die Spinnen im östlichen Tirisfal.", progress = "Habt Ihr endlich etwas Gift eines heimtückischen Nachtwebers, <Name>? Das ist die letzte Komponente, die mir fehlt, um mein Experiment zu testen.", completion = "Ah, dieses Gift wird genau richtig sein, &lt;Name&gt;. Alles andere wurde bereits mit meinem Gebräu verkocht. Jetzt bin ich endlich so weit, diesen neuen tödlichen Erreger auszuprobieren!", rewards = "Ihr bekommt:\n\nLehrlingsschärpe"},
[370] = {title = "Im Krieg mit dem Scharlachroten Kreuzzug", objective = "Exekutor Zygand in Brill möchte, dass Ihr Captain Perrine, 3 Scharlachrote Zeloten und 3 Scharlachrote Missionare tötet.", description = "Die strategischen Dokumente von Exekutor Arren enthalten alle Angaben, die wir brauchen, um die menschliche Plage aus den Ländern zu tilgen. Nach diesen Informationen hat der Scharlachrote Kreuzzug Captain Perrine mit einer Brigade dem verfallenen Turm südwestlich von Brill zugeteilt.\n\nTötet Perrine, sowie 3 Zeloten und 3 Missionare und erstattet mir dann Meldung.", progress = nil, completion = "Perrines Tod wird die dunkle Fürstin zweifelsohne zufrieden stellen. Ihr habt Eure Befehle gut ausgeführt, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"},
[371] = {title = "Krieg mit dem Scharlachroten Kreuzzug", objective = "Exekutor Zygand in Brill hat Euch damit beauftragt, Captain Vachon und 5 Scharlachrote Ordensmitglieder zu erschlagen.", description = "Wir befinden uns noch immer im Krieg, und der Scharlachrote Kreuzzug gewinnt an Stärke. Der Bericht, den mir Exekutor Arren schickte, zeigt auf, dass die Scharlachroten Kreuzzügler ihre Überfälle von dem verfallenen Turm im südöstlichen Tirisfal, nahe Balnirs Bauernhof, unter dem Kommando von Captain Vachon ausgeführt haben.\n\nTötet Vachon, zusammen mit 5 Scharlachroten Ordensmitgliedern. Das sollte sich als vernichtender Schlag für den Kreuzzug erweisen!", progress = nil, completion = "Captain Vachons Tod wird den Vormarsch des Scharlachroten Kreuzzugs in Tirisfal deutlich verlangsamen. Aber es lauern noch andere Gefahren.", rewards = "Ihr bekommt:\n\n"},
[372] = {title = "Krieg mit dem Scharlachroten Kreuzzug", objective = "Exekutor Zygand in der Stadt Brill möchte, dass Ihr Captain Melrache und seine beiden Leibwachen ermordet.", description = "Scharlachrote Kreuzzügler haben vom verfallenen Turm im nördlichen Tirisfal, hinter Faols Ruheplatz, Überfälle ausgeführt. Nach den Informationen, die wir haben, führt ein unbarmherziger Kommandant mit Namen Captain Melrache diese bösartige Truppe an.\n\nIch vertraue Euch eine besondere und gefahrvolle Mission an. Erschlagt Melrache und seine beiden Leibwachen im Namen der dunklen Fürstin.", progress = nil, completion = "Das habt Ihr sehr gut gemacht, &lt;Klasse&gt;. Dank unnachgiebiger Krieger wie Euch, die im Namen der Verlassenen Siege davontragen, ist unser Volk einen Schritt näher dran, Arthas ein für alle Mal zu besiegen. Ich habe ein gutes Gefühl bei Euch, Kamerad.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZeremonielles MesserSchlagkriegsbeil\n\nIhr bekommt außerdem:\n\n"},
[373] = {title = "Der nie verschickte Brief", objective = "Bringt den Brief nach Stormwind zum Stadtarchitekten Baros Alexston.", description = "Als Ihr Edwin van Cleef durchsucht, findet Ihr unter anderem einen nie verschickten Brief. Er ist adressiert an \"Baros Alexston, Stadtarchitekt von Stormwind, Rathaus, Kathedralenplatz\".\n\nEr scheint erst vor kurzem geschrieben und versiegelt worden zu sein.", progress = "Ja? Kann ich Euch irgendwie helfen?", completion = "Edwin van Cleef, sagt Ihr? Mit einem Brief von meiner toten Großmutter hätte ich eher gerechnet... Ihr habt ihn also getötet? Verzeiht, wenn ich das sage, aber ich bin etwas überrascht. Er war ein unvergleichlicher Krieger in seinen jungen Jahren. Lasst mich mal sehen, weswegen er mir nach so vielen Jahren auf einmal schreiben muss.\n\n&lt;Baros überfliegt den Brief.&gt;\n\nEdwin... Die Jahre haben dich offensichtlich kein bisschen verändert, immer noch der alte Idealist und Romantiker. Es kümmert ihn nicht, wen er verletzt, &lt;Name&gt;. Die Rache hat ihn verzehrt. Allerdings weiß ich nicht, ob ich ihm daraus einen Vorwurf machen kann.", rewards = "Ihr bekommt:\n\n"},
[374] = {title = "Beweise des Ablebens", objective = "Bringt Todeswache Burgess in Brill 10 scharlachrote Insignienringe.", description = "Exekutor Zygand sagt mir, dass Ihr Scharlachrote Kreuzzügler töten wart. In Tirisfal wimmelt es nur so von denen.\n\nVarimathras, Offizier der dunklen Fürstin, kümmert sich persönlich darum, dass der Abschaum Azeroths, die Menschen, völlig ausgelöscht wird. Hier in Tirisfal stehen wir einer besonders lästigen Menschenbrut gegenüber: dem Scharlachroten Kreuzzug.\n\nBegebt Euch hinaus und führt eine Offensive gegen den Scharlachroten Kreuzzug, <Klasse>. Bringt mir 10 scharlachrote Insignienringe zum Beweis Eurer Loyalität Varimathras und der dunklen Fürstin gegenüber.", progress = "Habt Ihr bereits 10 scharlachrote Insignienringe gesammelt, <Klasse>?", completion = "Varimathras wäre stolz. Ihr dient Euren Anführern gut, &lt;Klasse&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZombiehaut-ArmschienenSchnallengürtelVernetzte Handschuhe\n\nIhr bekommt außerdem:\n\n"},
[375] = {title = "Die Kälte des Todes", objective = "Bringt Gretchen Dedmar in Brill fünf Nachtsaugerpelze und etwas groben Faden.", description = "Es ist jetzt so kalt. Die Seuche des Untodes kriecht durch meine Adern wie eine eisige Schlange. Ich werde bald den Hirnlosen Zustand erreichen. Doch auch ein besiegeltes Schicksal wird mich nicht davon abhalten, unserer dunklen Fürstin zu dienen. Als der Ruf ertönte, nähte ich Leichensäcke für die gefallenen Soldaten von Sylvanas' mächtiger Armee.\n\nJetzt zittern meine Hände vor lauter Kälte. Wenn Ihr mir fünf Nachtsaugerpelze und etwas groben Faden bringen würdet, könnte ich mir eine Decke nähen. Helft mir, <Name>, auf dass ich der Sache weiter dienen kann.", progress = "Habt Ihr schon fünf Nachtsaugerpelze und etwas groben Faden, <Name>?", completion = "Ich weiß Eure Mühen zu schätzen, &lt;Name&gt;. Möge Sylvanas Eure Tapferkeit eines Tages anerkennen...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAdepten-UmhangNäh-Handschuhe\n\nIhr bekommt außerdem:\n\n"},
[376] = {title = "Die Verdammten", objective = "Novize Elreth benötigt 6 Aasfressertatzen und 6 Nachtsaugerflügel.", description = "Meine Pflichten umfassen, die verwundeten Krieger zu versorgen, Rüstung und Kleidung zu schneidern und Schattenpriester Sarvis in jeder erdenklichen Weise zu unterstützen.\n\nEs sieht so aus, als würdet Ihr ebenfalls in seine Dienste aufgenommen... wahrscheinlich um die Hirnlosen zu jagen, wie ich ihn kenne. Tja, wenn Ihr dabei in einem Stück bleiben wollt - und ich bezweifle nicht, dass Ihr das wollt -, dann kann ich Euch vielleicht helfen. Mir gehen die Tatzen und Flügel aus, und wenn Ihr mir einige davon bringt, besorge ich Euch eine Rüstung. Ihr werdet im Norden eine Menge Wölfe und Fledermäuse finden.", progress = "Bemüht Euch, unverletzt zu bleiben, bis ich Euch irgendeine Rüstung besorgt habe.", completion = "Danke, &lt;Name&gt;. Diese Rüstung sollte Euch etwas helfen.\n\nHoffentlich hilft sie Euch mehr als ihrem letzten Träger...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFlachs-ArmschienenAlter Ledergürtel\n\nIhr bekommt außerdem:\n\n"},
[377] = {title = "Verbrechen und Strafe", objective = "Ratsherr Millstipe von Dunkelhain will, dass Ihr ihm die Hand von Dextren Ward bringt.", description = "Als wäre die Vernachlässigung der Einwohner des Dämmerwalds nicht schlimm genug, nein, die jüngste Entscheidung des Oberhauses, Dextren Ward in Stormwind ins Gefängnis zu werfen, anstatt den Schurken - wie durch Lord Ebonlockes Urteil gefordert - zu enthaupten, ist ein Schlag ins Gesicht für den Rat von Dunkelhain.\n\nWard wurde dabei erwischt, wie er Leichen aus dem Friedhof an Morbent Fel verkaufte, ein Verbrechen, auf das der Tod steht. Und dennoch fordert Stormwind seine Gefangensetzung.\n\nErmordet Ward im Verlies von Stormwind - bringt mir seine Hand - und ich werde Euch belohnen.", progress = "So lange einem Leichenschänder wie Dextren Ward erlaubt wird, weiterzuleben, ist das Verrat an der Gerechtigkeit. Kehrt zu mir zurück, sobald Lord Ebonlockes Todesurteil an diesem Entweiher Ward vollstreckt wurde. Wir werden für die Familien der Toten den Schlussstrich ziehen, den sie verdienen und, noch wichtiger, dem Oberhaus in Stormwind eine klare Botschaft senden.", completion = "Dextren Ward hat also endlich für seine Verbrechen an der Menschheit bezahlt? Ich wünsche diesem Abschaum eine gute Reise. Und meinen Beifall an Euch, mein Freund! Ihr habt nicht nur den Familien der Toten den Seelenfrieden gebracht, den sie verdienen, sondern auch eine klare Botschaft an diese korrupten Bürokraten im Oberhaus geschickt. Stormwind muss sich der Probleme der Leute aus dem Dämmerwald annehmen, oder wir werden uns von ihrer Tyrannei befreien.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBotschafter-StiefelPanzergamaschen von Dunkelhain\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[378] = {title = "Tief empfundener Zorn", objective = "Motley Garmason in Dun Modr verlangt Kam Deepfurys Kopf.", description = "Ihr habt Eure Loyalität zu König Magni bewiesen, <Klasse>. Und Euer Hass auf den Dunkeleisenabschaum ist genau so groß wie mein eigener.\n\nEs gibt da eine Aufgabe, die ich selbst beenden möchte, aber ich bin durch meine Ehre verpflichtet, bei Longbraid zu bleiben. Jedoch hat Roggo Informationen gesammelt, die belegen, dass Kam Deepfury einer der Verschwörer beim Angriff auf den Thandol-Übergang war. Durch Deepfurys Pläne verlor Longbraid seine Sippe.\n\nDeepfury wird aus politischen Gründen im Verlies von Stormwind festgehalten. Ich will ihn tot sehen, <Name>. Für Longbraid! Bringt mir seinen Kopf!", progress = "Ich werde nicht zulassen, dass närrische Menschen-Bürokratie zwergischen Angelegenheiten in die Quere kommt, <Name>. Kam Deepfury ist erwiesenermaßen einer der Verschwörer des Angriffs auf den Thandol-Übergang. König Magnis gute Gefolgsleute ließen dank Deepfurys Verrat ihr Leben. Den Menschen mag es genug sein, Deepfury im Verlies verrotten zu lassen, aber ich werde nicht mehr ruhig schlafen, bis Deepfury erschlagen ist.", completion = "Kam Deepfury hat also endlich herausgefunden, wie es ist, den Tod selbst zu erfahren? Gut. Geschieht dem feigen Dunkeleisenabschaum recht. Ihr habt Eure Sache gut gemacht, &lt;Klasse&gt;. Die Gefallenen des Angriffs auf den Thandol-Übergang waren nur Opfer in einer Welt voller Krieg und Unfrieden. Ihre Familien werden Frieden in dem Wissen finden, dass Deepfury die Strafe erhielt, die er verdiente. Der Tod von Longbraids Bruder wurde gerächt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGürtel der RechtfertigungKopfberster\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[379] = {title = "Durstlöscher", objective = "Bringt Chefingenieur Bilgewhizzle in Gadgetzan 5 Wasserbeutel eines Wüstenläufers.", description = "Ihr möchtet eine Kraftquelle. Da kann ich Euch helfen. Wisst Ihr, was ich möchte? Ich möchte etwas zu Trinken! Bringt mir fünf Wasserbeutel eines Wüstenläufers und ich werde Euch die 4711-FTZ geben.\n\nUnd jetzt... ratet einmal, wo Ihr solche Wasserbeutel finden könnt! Warum geht Ihr nicht zu einem der Wüstenläufernomaden östlich von hier und bittet ihn um einen? Lasst mich wissen, ob das klappt.", progress = "Na, haben die Nomanden Euch die Wasserbeutel \"freiwillig\" gegeben?", completion = "Hervorragend, die Kraftquelle gehört Euch. Vorsicht, sie wurde nicht für die Verwendung mit wissenschaftlichen Geräten wie diesen entwickelt. Ihr habt also nur begrenzt Zeit, bevor die von Euch gesammelten Daten auf Nimmerwiedersehen verschwinden!\n\nWenn Ihr alles gesammelt habt, was für das, was auch immer es sei, nötig ist, dann bringt sie zu mir und ich werde sie richtig ausschalten. Ihr habt höchstens zwei Stunden Zeit, um alles zu erledigen, was Ihr vorhabt.\n\nFalls Ihr es in dieser Zeit nicht schafft, kann ich Euch aber eine weitere Kraftquelle für einen neuen Versuch verkaufen. Ihr habt richtig gehört - \"verkaufen\"!", rewards = "Ihr bekommt:\n\nKraftquelle, Modell 4711-FTZ"},
[380] = {title = "Nachtweber", objective = "Exekutor Arren will, dass Ihr 10 junge Nachtweber und 8 Nachtweber tötet.", description = "Eine unserer größten Schwierigkeiten besteht darin, die Rohstoffe zu besorgen, die wir zum Überleben brauchen. Gold war schon zu Hochzeiten der Macht der Allianz selten.\n\nEs gibt eine Goldmine im Nordwesten, die von Spinnen überrannt wurde. Wir brauchen das Gold dieser Mine, aber wir können es ja schlecht holen, während die Spinnen darin herumkrabbeln. Ich habe nicht viel Personal übrig für diese Aufgabe, also müssen wir sie Schritt für Schritt lösen.\n\nBegebt Euch dorthin und schaut mal, was Ihr für uns ausrichten könnt, <Name>.", progress = "Hütet Euch vor dem Gift dieser Spinnen, <Name>. Wenn Ihr ein scharfes Brennen verspürt, solltet Ihr vielleicht jemanden danach sehen lassen.", completion = "Hmm, nun ja, es ist ein Anfang. Es wird ein paar Wochen oder Monate dauern, das Ungeziefer gänzlich auszumerzen. Danach müssen wir mit ein paar Fackeln da runtergehen und die Netze niederbrennen.\n\nIhr habt Eure Pflicht gut erfüllt, &lt;Name&gt;, und ich bin mir sicher, ich finde noch etwas anderes für Euch zu tun.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFlachswesteUnverwüstliche PanzerwesteZombiehaut-Gamaschen\n\nIhr bekommt außerdem:\n\n"},
[381] = {title = "Der Scharlachrote Kreuzzug", objective = "Bringt Exekutor Arren insgesamt 12 scharlachrote Armbinden von scharlachroten Konvertiten und scharlachroten Initianden.", description = "Ihr werdet erfreut sein zu hören, dass wir anscheinend Fortschritte in der Mine machen. Der Dank dafür gebührt zu einem nicht unerheblichen Maß Euren Bemühungen. Nun können wir uns anderen Belangen zuwenden.\n\nMeine Späher haben berichtet, dass eine Abteilung des Scharlachroten Kreuzzugs südöstlich von hier ein Lager errichtet. Der Scharlachrote Kreuzzug ist eine verabscheuungswürdige Organisation, die uns jagt, und sie wird nicht ruhen, ehe nicht alle Untoten - ganz gleich, ob Teil der Geißel des Lichkönigs oder nicht - vernichtet sind. Wir müssen ihnen zuvorkommen!\n\nSeid vorsichtig, denn der unheilige Eifer dieser Leute macht sie zu gefährlichen Gegnern.", progress = "Diese Narren... Sie schaufeln sich fröhlich ihre eigenen Gräber.", completion = "Wenn sie nur auf die Stimme der Vernunft hören würden, hm, &lt;Name&gt;? Vielleicht könnten wir sie dazu bringen, sich mit uns zu einem vernünftigen Gespräch zusammenzusetzen... ha!\n\nVom Licht geblendete Narren.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDolch der VerlassenenSchlägel der VerlassenenKurzschwert der VerlassenenBastardschwert der Verlassenen\n\nIhr bekommt außerdem:\n\nErfrischendes Quellwasser"},
[382] = {title = "Der Rote Bote", objective = "Tötet Meven Korgal, den Boten, im Lager der Kreuzzügler und kehrt danach mit allen Informationen, die Ihr findet, zu Exekutor Arren zurück.", description = "Berichte meiner Vorgesetzten in Brill weisen darauf hin, dass ein Agent des Scharlachroten Kreuzzugs vom Scharlachroten Kloster hierher nach Deathknell entsendet wurde. Nach diesen Berichten führt dieser Bote wichtige Informationen mit sich. Ich kann nicht mit Einzelheiten dienen, aber was auch immer es ist, wir müssen es haben!\n\nIhr seid die qualifizierteste Person, die ich darauf ansetzen kann, <Name>. Findet diesen Boten und bringt mir alle Informationen, die er bei sich trägt.", progress = "Wie läuft es mit Eurem Auftrag, <Name>?", completion = "Hmmm... Mal sehen, was Ihr da habt... \n\n&lt;Er fängt an, die von Euch beschafften Dokumente durchzublättern.&gt;\n\nNachrichten von ihren Aktionen gegen uns... Wertlos. Spähberichte... Neue Befehle wie \"Baut das Lager nahe der verfallenen Stadt weiter auf...\". Nichts, was wir nicht bereits wüssten... Ah... was haben wir denn hier? Eine Karte, auf der die derzeitigen Posten einiger ihrer Kommandanten und Agenten verzeichnet sind. Damit lässt sich etwas anfangen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nStab des ExekutorsTodeswachen-Rundschild\n\nIhr bekommt außerdem:\n\n"},
[383] = {title = "Entscheidende Informationen", objective = "Bringt die Dokumente des Scharlachroten Kreuzzugs zu Exekutor Zygand nach Brill.", description = "Das muss zu meinem Vorgesetzten, Exekutor Zygand, nach Brill gebracht werden. Mit diesen Informationen können wir dem Scharlachroten Kreuzzug einen entscheidenden Schlag versetzen. Eure Dienste waren hier in Deathknell nützlich, aber ich benötige jemanden, der dies zu Zygand bringt, und ich denke, er wird angemessenere Arbeiten für Euch finden. \n\nNehmt die Straße nach Norden, hinaus aus Deathknell. Kurz nachdem Ihr nach Tirisfal hineinkommt, trefft Ihr auf eine Kreuzung. Nehmt die Abzweigung nach Osten und behaltet diese Richtung dann bei. Ihr werdet unterwegs am Coldhearth-Anwesen vorbeikommen.", progress = "Ja, was wollt Ihr?", completion = "Ja, das ist sehr gut. Diese Informationen zu beschaffen, war gute Arbeit, &lt;Name&gt;. Hmm... Die Namen der Offiziere in Tirisfal... \n\nStellt Euch nur vor, welchen Schlag wir der Moral dieser verfluchten Fanatiker verpassen könnten, wenn wir es schaffen, all ihre Anführer auf einen Schlag zu töten.", rewards = "Ihr bekommt:\n\n"},
[384] = {title = "Eberrippchen in Biersauce", objective = "Ragnar Donnerbräu in Kharanos benötigt 6 Klippeneberrippchen und einen Krug Rhapsody-Malzbier.", description = "Meine Tavernengäste mögen nichts so sehr wie meine Eberrippchen in Biersauce. Das einzige Problem dabei ist, dass der ortsansässige Fallensteller, der mich bisher mit den Zutaten versorgt hat, in die Armee des Königs eingetreten ist, um im Krieg an der Allianzfront zu helfen. \n\nVielleicht könnt Ihr mir helfen? Wenn Ihr mir sechs Klippeneberrippchen bringt und ein Rhapsody-Malzbier von der Taverne hier besorgt, bekommt Ihr das Familienrezept für meine berühmten Eberrippchen in Biersauce, und nicht zu vergessen natürlich eine Kostprobe! Das Geheimnis liegt im Malz!", progress = "Ich werde sechs Klippeneberrippchen und einen Krug Rhapsody-Malzbier benötigen, <Name>.", completion = "Das Malzbier ist gebraut, die Wildschweine sind abgestochen\nDoch bevor das letzte Wort gesprochen\nWerden wir um dieses leckere Essen\nDer Eberrippchen in Biersauce\nUns erst im Kampfe messen!", rewards = "Ihr bekommt:\n\nEberrippchen in BiersauceRezept: Eberrippchen in Biersauce"},
[385] = {title = "Krokiliskenjagd", objective = "Besorgt 5 Stücke Krokiliskenfleisch und 6 Krokiliskenhäute für Marek Ironheart in der Weitschreiter-Lodge.", description = "So manchen Jäger zieht es an den Loch Modan, um unsere berühmten Kroks zu erlegen. Irgendein Händler sucht immer Krokiliskenhäute für seine Kleidungsstücke oder Rüstungen und es gibt auch einige Leute, denen ihr Fleisch mundet.\n\nWir handeln ein wenig damit, aber nicht wirklich viel, denn die Krokilisken sind wild und haben sich auf den Inseln im Loch verschanzt. Aber ich will Euch nicht davon abbringen, denn es ist ein unvergessliches Erlebnis, mit den Kiefern der Bestien zu ringen.\n\nAch ja, das eine Mal damals...", progress = "Hab ich Euch eigentlich erzählt, wie ich damals beinahe meine Hand an einen der Kroks verloren hätte? Ein übles Viech war das, mit Zähnen wie Messer. Aber ich hatte Glück... Hab dem Monster mit meinem Messer das Maul gestopft. Ich habe das Messer sogar noch irgendwo herumliegen...", completion = "Na, wenn das nicht ein paar Prachtexemplare sind, die Ihr da gesammelt habt, &lt;Name&gt;. Für hochwertiges Material gibt es selbstverständlich auch eine ordentliche Bezahlung.", rewards = "Ihr bekommt:\n\nRezept: KrokiliskensteakUnverwüstliches Cape"},
[386] = {title = "Verbrechen lohnt sich nicht", objective = "Bringt Wache Berton in Seenhain den Kopf von Targorr dem Schrecklichen.", description = "Targorr der Schreckliche diente als oberster Exekutor unter Gath'llzogg. Er ging grausam vor, selbst nach den Standards der dreckigen Orcs. Menschen, die tapfer gekämpft hatten, um das Königreich zu verteidigen, wurden nur zu seiner Belustigung gefoltert. Heute wird er im Verlies von Stormwind gefangen gehalten und wurde zum Tode verurteilt. Dennoch stimmt irgendetwas nicht. Einer dieser bürokratischen Adeligen hat seine Exekution ausgesetzt. Ich bin mir sicher, hier wird eine Schandtat geplant.\n\nMacht Targorr dem Schrecklichen ein Ende, <Name>. Reist zum Verlies und enthauptet ihn, bevor man uns überlistet.", progress = "Wart Ihr bereits in Stormwind, im Verlies? Ich fürchte, dass das falsche Spiel, das Targorr den Schrecklichen so lange am Leben erhalten hat, ihm irgendwann seine Freiheit wiederbringen wird. Er wurde zum Tode verurteilt, <Name>, nicht dazu, als Schachfigur in den politischen Plänen irgendeines Adeligen missbraucht zu werden.", completion = "Targorr den Schrecklichen hat endlich sein Schicksal ereilt. Es freut mich jedenfalls, zu hören, dass diese Bestie jetzt weiß, wie es ist, selbst im ewigen Griff des Todes zu stecken. Ihr habt Eure Sache gut gemacht, &lt;Name&gt;. Manchmal kann wahre Gerechtigkeit nur außerhalb des Gerichtssaales und der Kurzsichtigkeit der Politik gefunden werden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLucinen-LangschwertGehärteter Wurzelstab\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[387] = {title = "Niederschlagung des Aufstandes", objective = "Aufseher Thelwater aus Stormwind will, dass Ihr im Verlies 10 gefangene Defias, 8 eingekerkerte Defias und 8 Aufrührer der Defias tötet.", description = "Der Aufstand muss niedergeschlagen werden! Ich brauche Eure Hilfe. Wenn jemand mitbekommt, dass das Gefängnis überrannt wurde, verliere ich meinen Job! Solch übles Spiel habe ich noch nie erlebt. Aber was jetzt zählt ist, die Gefangenen zur Sicherheit Stormwinds niederzuringen.\n\nDie Strafe für Auflehnung lautet Tod. Tötet einige dieser Abweichler! Das sollte die Angelegenheit wieder unter Kontrolle bringen.", progress = "Das Verlies ist immer noch besetzt! Diesen Defiasratten muss endlich klargemacht werden, dass ihre Taten nicht toleriert werden. Und jetzt geht wieder da runter und zeigt Stärke!", completion = "Eure Bemühungen im Verlies waren tapfer, &lt;Name&gt;. Es ist offensichtlich, dass dieses Problem etwas über unserer beider Fähigkeiten liegt. Aber ihr habt Eure Sache gut gemacht, und dafür bin ich Euch dankbar.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[388] = {title = "Die Farbe von Blut", objective = "Nikova Raskol von Stormwind will, dass Ihr 10 rote Wollkopftücher für sie sammelt.", description = "Verbitterung fließt wie ein kalter Fluss durch meine Adern. Mein Enkel, Mac, war so ein guter Junge. Gerade mal 14 Jahre alt. Als die Armee an die Front geschickt wurde, griff Mac zu den Waffen, um die Stadt zu verteidigen. Er war eine Wache im Verlies, wo diese elenden Defias eingesperrt sind. Mac wies ein paar der Gefangenen dafür zurecht, dass sie ihre Wolldecken zerrissen, um Schals daraus zu machen, die ein Symbol ihrer Bande darstellen. Dafür wurde Mac hinterhältig erstochen.\n\nIch will Rache. Bringt mir 10 ihrer kostbaren Wollkopftücher. Sie haben die Farbe von Blut.", progress = "Wie ich sehe, seid Ihr wieder zurück, <Klasse>. Habt Ihr bereits 10 rote Wollkopftücher der Defias von diesem Abschaum im Verlies gesammelt?", completion = "Diese Kopfwickel - diese schmutzigen Wahrzeichen der Korruption - sind es also, wofür mein Mac sterben musste? Was für eine Verschwendung. Welch tragisches Opfer. \n\nDoch leider kann ich nicht in die Vergangenheit zurückkehren. Wisset jedoch, &lt;Name&gt;, dass Ihr meiner Familie mit Euren Taten Gerechtigkeit verschafft habt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[389] = {title = "Bazil Thredd", objective = "Sprecht mit Aufseher Thelwater im Verlies.", description = "Van Cleef und ich waren beide Mitglieder der Steinmetzgilde. Unser Hauptprojekt war der Wiederaufbau Stormwinds nach dem Krieg.\n\nAls wir unsere Aufgabe erfüllt hatten, wurden wir betrogen. Die Adligen verweigerten uns die Bezahlung für unsere Arbeit. Einigen der älteren Steinmetze wurden Posten in der Regierung angeboten, aber van Cleef lehnte aus Loyalität zu den übrigen Steinmetzen ab. Er führte eine Revolte an und verließ, Rache schwörend, die Stadt.\n\nSein Helfer, Bazil Thredd, könnte vielleicht mehr über van Cleefs Pläne wissen. Er wird im Verlies gefangen gehalten.", progress = nil, completion = "Was, beim Licht, wollt Ihr? Könnt Ihr nicht sehen, dass wir hier in einer Krisensituation sind?\n\nBazil Thredd?! Warum solltet Ihr mit diesem Bastard sprechen wollen? Woher soll ich wissen, ob Ihr nicht einer seiner Spießgesellen seid, der herkam, um ihm bei seinem verdammten Aufstand zu helfen? Wenn die verfluchten Zellen nicht alle offen wären, würde ich Euch für eine Weile in eine davon werfen!", rewards = "Ihr bekommt:\n\n"},
[391] = {title = "Aufstand im Verlies", objective = "Tötet Bazil Thredd und bringt seinen Kopf mit zurück zu Aufseher Thelwater im Verlies.", description = "Lasst uns eine Sache klarstellen, <Name>: Ich traue Euch nicht. Aber wie die Sache im Moment aussieht, werdet Ihr ohnehin keinen Unterschied machen.\n\nAlso wird das folgendermaßen ablaufen: Geht da runter und redet mit Thredd. Wenn Ihr wirklich auf unserer Seite seid, dann eliminiert ihn und bringt mir seinen Kopf, wenn Ihr fertig seid. Und falls sich herausstellt, dass Ihr auf seiner Seite seid und nicht herauskommt... werdet Ihr zusammen mit dem Rest dieser Würmer sterben, wenn wir Euch finden.", progress = "Entweder bringt Ihr mir Thredds Kopf oder ich nehme mir den Euren, kapiert, <Name>?", completion = "Jetzt, wo Thredd sie nicht mehr anführen kann, ist der Aufstand hoffentlich eher unter Kontrolle zu bringen... Wir werden sehen.\n\nIch muss gestehen, dass ich nach einer halben Stunde kaum mehr erwartete, dass Ihr wieder herauskommen würdet, aber ich habe Euch wohl falsch eingeschätzt.\n\nIch nehme daher mal an, dass Ihr nicht viele nützliche Informationen aus ihm herausbekommen habt. Aber ich weiß bereits das eine oder andere über Thredds Aktivitäten, das für Euch von Interesse sein könnte.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[392] = {title = "Der seltsame Besucher", objective = "Bringt die versiegelte Beschreibung von Thredds Besucher nach Stormwind zu Baros Alexston.", description = "In den ersten Jahren von Thredds Gefangenschaft bekam er niemals Besuch. Ich ging davon aus, dass er für die Bruderschaft keinen Nutzen mehr hatte und sie ihn daher fallen ließ.\n\nAber vor einigen Monaten hat sich das alles geändert; er bekam regelmäßig Besuch ... einmal, manchmal sogar zweimal pro Woche. Es war ein seltsamer Mann, so ein ruhiger Typ. Ich hatte da so meinen Verdacht, aber alle seine Papiere waren in Ordnung.\n\nLaut seinen Dokumenten war sein Name Maelik; hier habt Ihr seine Beschreibung. Ich glaube nicht, dass er noch einmal kommen wird, um Thredd zu besuchen.", progress = "Ja, <Name>? Was habt Ihr gefunden?", completion = "Hmm. Maelik? Nein, der Name sagt mir nichts und auch nicht diese Beschreibung. Aber es könnte ein jeder sein! Ein früherer Steinmetz, einer von der Bruderschaft der Defias... Wenn er allerdings tatsächlich so viele Verbindungen hat, wie Thelwater andeutet, dann erkennt ihn vielleicht jemand anderes. Lasst mich nachdenken.", rewards = "Ihr bekommt:\n\n"},
[393] = {title = "Schatten der Vergangenheit", objective = "Bringt die versiegelte Beschreibung von Thredds Besucher nach Stormwind zu Meister Mathias Shaw.", description = "Ich habe wirklich keine Ahnung, <Name>. Aber es gibt da jemand anderen, der Euch vielleicht helfen kann, und wie es der Zufall so will, schuldet dieser Jemand mir einen Gefallen, weil... egal, das brauchen wir jetzt nicht zu vertiefen. Ihr könnt Meister Mathias Shaw vom SI:7 in der Kaserne in der Altstadt finden. Shaw hat seine Finger in den meisten zwielichtigen oder heimlichen Geschäften der Stadt.\n\nWenn also jemand etwas weiß, dann er.", progress = "Seid gegrüßt. Wie kann ich Euch zu Diensten sein, <Klasse>?", completion = "Was? Was ist das? Ja, ich glaube, ich weiß, wer dieser Mann ist, aber sein Name ist nicht Maelik. Auftragsmörder tragen viele Namen und viele Masken und lassen sie hinter sich, sobald sie ihren Nutzen verloren haben. Ein anderer Name, den dieser Mann benutzt, ist Marzon, obwohl auch das sicherlich nicht sein wirklicher Name ist.\n\nNichtsdestotrotz ist er ein Auftragsmörder, und ich weiß eine ganze Menge über ihn.\n\nMarzon arbeitet derzeit für Lord Gregor Lescovar, einen Lord mit zweifelhaftem Ruf, selbst gemessen am korrupten Adel von Stormwind.", rewards = "Ihr bekommt:\n\n"},
[394] = {title = "Der Kopf des Ganzen", objective = "Sprecht mit Mathias Shaw in Stormwind.", description = "Sucht Shaw in der Altstadt. Teilt ihm mit, dass Ihr Euch um die Bedrohung durch Lescovar gekümmert habt, und berichtet ihm von Eurer Beteiligung an den Plänen des Lords gegen die Stadt. Ich bin sicher, er wird stolz sein, einen weiteren Helden unter den Bürgern Stormwinds zu haben.\n\nEr wird Euch ganz bestimmt zu einem Treffen mit dem Prinzen oder einem anderen Adligen schicken. Lasst Euch das nicht zu Kopfe steigen, <Name>. Die Adligen können noch so sehr glauben, dass sie die Stadt beherrschen, aber einige Dinge bleiben für die im Dunklen.", progress = nil, completion = "Er ist also tot? Ihr wart schnell mit der Vollstreckung des Urteils, &lt;Name&gt;. Ich bete zum Licht, dass ich niemals Euer Ziel sein möge!\n\n\n\nDas war nicht als Kritik zu verstehen, &lt;Name&gt;. Wie könnte es auch, wo ich doch der Meister aller Auftragsmörder bin? In Wahrheit habt Ihr den Einwohnern von Stormwind einen großen Dienst erwiesen und dafür danke ich Euch.", rewards = "Ihr bekommt:\n\n"},
[395] = {title = "Das Ende der Bruderschaft", objective = "Sprecht mit Baros Alexston in Stormwind.", description = "Ach, das hätte ich fast vergessen. Alexston kam vorbei, als Ihr unterwegs wart, und wünschte mit Euch zu sprechen. Zweifellos möchte er den Adligen über die Ränkespiele der Defiasbruderschaft berichten.\n\nEin kleiner Rat, <Name>: Sollte Euch jemand fragen, würde ich zwar alle Details offen legen, aber dabei nicht erwähnen, dass es Eure Hand war, die Lescovar erschlug. Vertraut mir. Ich... kenne mich aus... mit solchen Dingen.\n\nUnd was Trias angeht, nun, sprecht mit niemandem über ihn... niemals... wenn Ihr es vermeiden könnt.", progress = nil, completion = "Es ist schön, Euch zu sehen, &lt;Name&gt;. Wie ich hörte, wurde Lord Gregor Lescovar vor kurzem tot aufgefunden.\n\nEs sieht also so aus, als wäret Ihr mit Eurer Mission erfolgreich gewesen. Ihr könnt Euch meines Dankes dafür gewiss sein, dass Ihr mich und viele andere vor van Cleefs Rache bewahrt habt.", rewards = "Ihr bekommt:\n\n"},
[396] = {title = "Eine Audienz beim König", objective = "Liefert Baros AlexstonsBericht über die Bruderschaft der Defias bei König Varian Wrynn in der Burg Stormwind ab.", description = "Ich habe einen Bericht an den König vorbereitet. Und Ihr sollt sein Überbringer sein, zusammen mit einer Auflistung Eurer Ergebnisse. Macht Euch keine Sorgen, er wird Euch zweifellos für die Erfüllung Eurer Pflicht gegenüber den Leuten von Stormwind loben.\n\nEure Audienz findet in Kürze statt, also solltet Ihr Euch besser beeilen, denn es ist schon ein Stück Weges bis zur Burg Stormwind.", progress = "<Name>, richtig? Baros Alexston informierte mich über Euer Kommen. Ich muss sagen, ich bin sehr an Euren Ausführungen interessiert.", completion = "Ihr verdient Lob für die Dienste, die Ihr Stormwind erwiesen habt, &lt;Name&gt;. Wenn van Cleef in seinen Machenschaften erfolgreich gewesen wäre, hätte er dem Königreich zweifellos bedeutenden Schaden zugefügt - etwas, das wir natürlich vermeiden müssen.\n\nNehmt dies, &lt;Klasse&gt;, als Zeichen der Dankbarkeit des Königs. Ich bin nur betrübt, dass er es Euch nicht selbst überreichen kann, aber er ist in diplomatischer Mission unterwegs und wird für eine Weile nicht zurückkehren.", rewards = "Ihr bekommt:\n\nSiegel von Wrynn"},
[397] = {title = "Ihr habt uns gut gedient", objective = "Sprecht mit Zggi, dem Diener von Zardeth von den Blackclaw, um Eure Belohnung zu erhalten.", description = "Wie ich höre, hat Lord Wishock sein Getränk genossen. \n\nIhr habt uns gut gedient, <Name>. Die Hexenmeister von Stormwind werden nun, dank Euch, ohne Störung ihrem Tagewerk nachgehen können. Ich habe ein besonderes Geschenk vorbereitet, um Euch für Eure Mühen zu entlohnen. Sprecht mit meinem Diener, Zggi, um Eure Belohnung zu erhalten.", progress = nil, completion = "Meister sagt, gib &lt;Name&gt; Geschenk. Zggi will schönes Geschenk behalten, aber Zggi zu klug, Meister zu verraten.", rewards = "Ihr bekommt:\n\nSchreckensmagierhut"},
[398] = {title = "GESUCHT: Madenauge", objective = "Tötet Madenauge und kehrt dann mit seiner Tatze zu Exekutor Zygand nach Brill zurück, um eine Belohnung zu erhalten.", description = "Gesucht: Madenauge!\n\nDie selbst für einen Gnoll außerordentlich niederträchtige Kreatur wurde für ihre Verbrechen an den Verlassenen zum Tode verurteilt. Dieser verabscheuungswürdige Verbrecher hat Leichen für die Armee des Lichkönigs gestohlen. Madenauge wurde zuletzt gesehen, als er die Gegend nahe Garrens Schlupfwinkel nördlich von Brill plünderte.\n\nDie Stadt Brill bietet hiermit eine Belohnung für die fähige Seele, die die Exekution durchführt. Zeigt Exekutor Zygand die Tatze des Verbrechers, wenn die Tat getan ist.\n\nGnade ist etwas für die Schwachen.", progress = "Ja?", completion = "Madenauges abscheuliche Taten wurden endlich gerächt. Vielleicht sind Eure mutigen Taten eine klare Botschaft an die, die unserem Volk Leid zufügen wollen. Ich danke Euch im Namen der Stadt Brill, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMessingschuppenhoseTillers Weste\n\nIhr bekommt außerdem:\n\n"},
[399] = {title = "Ein bescheidener Anfang", objective = "Begebt Euch zu Baros Alexstons Haus in Westfall und sucht nach seinem Kompass. Übergebt ihm diesen dann am Kathedralenplatz von Stormwind.", description = "Es kommt mir so vor, als wäre es ewig her, dass ich als Junge in Westfall auf dem Hof gearbeitet habe. Man sagt ja, man kann niemals in der Zeit zurückgehen, und es stimmt wohl. In meinem Fall trifft das sogar gleich doppelt zu, denn das Heim meiner Familie wurde niedergebrannt und von Dieben besetzt.\n\nIch habe mit meinem Vater über den Verbleib einiger meiner Habseligkeiten gesprochen, darunter mein erster Kompass. Er konnte sie nicht retten. Allerdings meint er auch, dass sie auf dem Hof versteckt sein müssten.\n\nIhr findet den Alexstons Bauernhof westlich der Späherkuppe. Könntet Ihr vielleicht dorthin gehen und mir meinen Kompass wiederbringen?", progress = "<Name>! Hattet Ihr Glück?", completion = "Oh, ich danke Euch, &lt;Name&gt;! Er hat zwar keinen praktischen Nutzen für mich, aber sein sentimentaler Wert... Ich muss wohl nicht betonen, wie dankbar ich bin, dass Ihr mir dies zurückgebracht habt... unter Einsatz Eures Lebens, ganz zu schweigen von der Zeit, die der lange Weg bis hinunter nach Westfall in Anspruch nahm. Habt Dank, und nehmt dies als ein Zeichen meiner Anerkennung.", rewards = "Ihr bekommt:\n\n"},
[400] = {title = "Werkzeuge für Steelgrill", objective = "Liefert Beldin Steelgrill seine Werkzeuge.", description = "Beldin Steelgrill ist der Besitzer der örtlichen Maschinenschlosserei, und er ist der beste Monteur von Belagerungsmaschinen, den es gibt! Allerdings geht er nicht sehr gnädig mit seinen Werkzeugen um. Ich schwöre Euch, er macht bald mehr Bogenlichtschraubenschlüssel kaputt, als wir ihm liefern können!\n\nWir haben gerade seine letzte Werkzeugbestellung fertig. Wenn Ihr sie ihm anliefert, wird er sich sicherlich erkenntlich zeigen.\n\nSein Geschäft, Steelgrills Depot, liegt etwas nordöstlich von Kharanos. Und nebenbei, es handelt sich dort um einen örtlichen Treffpunkt für die Veteranen unter den Piloten der Belagerungsmaschinen, also hört Euch ruhig ein wenig um, während Ihr dort seid.", progress = "Hm? Ihr seht etwas zu jung aus für einen Piloten der Belagerungsmaschinen. Aber egal... Braucht Ihr eine Reparatur?\n\nDann zieht eine Nummer und macht es Euch bequem. Ich arbeite gerade an ein paar Maschinen und werde wenigstens einige Tage lang keine Zeit für weitere Aufträge haben.\n\nOder seid Ihr wegen etwas anderem hier... ?", completion = "Ihr habt meine Werkzeuge? Gut gemacht, Junge, gut gemacht! Ich habe gerade vor einer Stunde meine letzte Zahnratsche zerbrochen, und ich brauche eine, um die Reparatur an Pilot Stonegears Belagerungsmaschine abzuschließen. Gut, dass Ihr diese Werkzeuge hierher geschafft habt, &lt;Name&gt;.\n\nHier, nehmt diese Münzen, für Eure Hilfe.", rewards = "Ihr bekommt:\n\n"},
[401] = {title = "Wartet, bis Sirra fertig ist", objective = "Wartet einen Moment und sprecht dann erneut mit Sirra Von'Indi.", description = "Ich bin fast mit der Übersetzung dieser Notiz fertig. Wenn Ihr in ein paar Minuten wiederkommt, dürfte ich fertig sein.", progress = nil, completion = "So, hier haben wir's. Übersetzt heißt es... \n\n&lt;Die Luft wird schwerer, als würde sich ein dicker, schwarzer Mantel über das Land legen... &gt;", rewards = "Ihr bekommt:\n\n"},
[402] = {title = "Sirra ist beschäftigt", objective = "Schaut später noch einmal nach, ob Sirra immer noch beschäftigt ist.Tut mir leid, aber bei dem Zustand, in dem die Stadt sich derzeit befindet, gibt es leider andere Dinge, die meine Aufmerksamkeit erfordern. Vielleicht kann ich diese Übersetzung später beenden, falls wir überleben.", description = "Tut mir leid, aber bei dem Zustand, in dem die Stadt sich derzeit befindet, gibt es leider andere Dinge, die meine Aufmerksamkeit erfordern. Vielleicht kann ich diese Übersetzung später beenden, falls wir überleben.", progress = nil, completion = nil, rewards = nil},
[403] = {title = "Das bewachte Fass mit Donnerbier", objective = "Dieses Fass Bier wird von Jarven Donnerbräu bewacht. Solange er im Keller ist, kann man sich nicht an den Fässern zu schaffen machen.", description = nil, progress = nil, completion = nil, rewards = nil},
[404] = {title = "Eine eitrige Aufgabe", objective = "Bringt Todeswache Dillinger in Brill 7 eitrige Klauen.", description = "Teile der Geißel sind nach und nach in Tirisfal eingedrungen und suchen die Gegend westlich von Brill heim, nahe der alten Brücke.\n\nGeht dorthin und schlagt die Faulenden Toten und Verheerten Kadaver zurück, die Ihr dort vorfindet. Zerstreut ihre Knochen und bringt uns ihre eitrigen Klauen, dann werden die Todeswachen Euch entlohnen.", progress = "Habt Ihr die Aufgabe erledigt, die ich Euch auftrug? Habt Ihr die eitrigen Klauen?", completion = "Gut gemacht. Schade, dass ich nicht dabei war, um Euch zuzusehen, wie Ihr diese Untoten zu Brei geschlagen habt.", rewards = "Ihr bekommt:\n\n"},
[405] = {title = "Der abtrünnige Lich", objective = "Zeigt Bethor Iceshard in Undercity Sevrens Befehle.", description = "Bethor Iceshard, ein hochrangiger und mächtiger Magier aus Undercity im Süden, befiehlt mir, ihm einen Agenten zu schicken, der seinen Wert gegen die Geißel bereits bewiesen hat. Ihr, <Name>, werdet dieser Agent sein.\n\nZeigt Bethor diese Befehle. Er wird Euch daraufhin über Eure Mission aufklären. Ich kenne keine Details, aber es hat etwas damit zu tun, einen eigenwilligen Lich zu rekrutieren. Und es wird gefährlich sein.\n\nAlso macht Euch bereit, <Klasse>. Ihr dürft nicht scheitern.\n\nIhr dürftet Bethor im Magieviertel von Undercity finden.", progress = "Seid gegrüßt. Entweder wisst Ihr nicht, wer ich bin, oder Ihr habt dringliche Geschäfte mit mir zu erledigen.\n\nDenn würde beides nicht zutreffen, wärt Ihr nicht töricht genug, mich zu stören...", completion = "Ah, Ihr seid der Agent, den Magistrat Sevren schickt. Also sind Eure Geschäfte mit mir tatsächlich wichtig.\n\nIch gehe davon aus, dass Sevren jemanden ausgewählt hat, der meiner Aufgabe gewachsen ist... aber wir werden sehen.", rewards = "Ihr bekommt:\n\n"},
[407] = {title = "Felder des Kummers", objective = "Bringt den getränkten Kürbis zum gefangenen Scharlachroten Zeloten, der im Keller der Taverne Zur Galgenschlinge gefangen gehalten wird.", description = "Harmlose Kürbisse, oder? Zumindest sehen sie so aus. Wenn wir Arthas' Vormarsch im Norden und die menschliche Plage im Süden stoppen wollen, müssen wir alle Möglichkeiten unseres untoten Daseins nutzen.\n\nMit etwas Einfallsreichtum wird sogar aus einem einfachen Kürbis ein Agent für unsere dunkle Fürstin. Dieser Kürbis wird sich, wenn nach meiner jüngsten Formel behandelt, als eine besondere Leckerei erweisen.\n\nEs wurde schon wieder ein Scharlachroter Zelot gefangen genommen, der derzeit im Keller der Taverne Zur Galgenschlinge gefangen gehalten wird. Bringt dem Trottel diesen Kürbis.", progress = "Bleibt mir vom Leibe, bösartige und unheilige Kreatur! Möge das Licht mich beschützen! Der Scharlachrote Kreuzzug wird Azeroth von Eurer... \n\n... oh, Moment mal. Ist das etwas zu essen für mich? Ich bin so was von hungrig...", completion = "Beim Licht! Endlich etwas zu essen! Süßer, leckerer Kürbis...", rewards = "Ihr bekommt:\n\n"},
[408] = {title = "Die Familiengruft", objective = "Tötet 8 Klagende Vorfahren und 8 Faulende Vorfahren.\n\nTötet Captain Dargol und bringt seinen Schädel zu Magistrat Sevren nach Brill.", description = "Die Gegend um Agamands Mühlen hat sich zu einem Außenposten der Geißel entwickelt. Am stärksten sind sie in der Gruft der Familie Agamand, wo ihr örtlicher militärischer Anführer, ein Skelett namens Captain Dargol, sein Hauptquartier hat. Er hat die Vorfahren der Agamands durch Nekromantie wiedererweckt und hat vor, sie gegen uns einzusetzen.\n\nDies darf nicht geschehen, und Ihr müsst es verhindern. Reist zur Gruft der Familie Agamand und besiegt die erweckten Vorfahren der Agamands.\n\nUnd bringt mir den Schädel von Captain Dargol.", progress = "Zeit ist ein Luxus, den wir uns nicht leisten können, <Name>. Mit jeder Stunde, die verstreicht, festigt sich der Griff der Geißel um Tirisfal.", completion = "Eure Taten verpassten der Geißel einen merklichen Schlag. Und Euer Sieg wird nicht unbemerkt bleiben - weder von den Verlassenen, noch von unseren Feinden.\n\nKämpft weiter, wie wir alle, &lt;Name&gt;, und eines Tages werden wir den Lichkönig daselbst aus Azeroth vertreiben!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDunkelholzstabKnochenknacker\n\nIhr bekommt außerdem:\n\n"},
[409] = {title = "Treuebeweis", objective = "Beschafft Euch eine Kerze des Heranlockens.\n\nBeschwört Lillith Nefara und tötet sie.\n\nKehrt zu Gunther auf seiner Insel zurück.", description = "Ihr behauptet, Ihr wärt nicht dem Willen des Lichkönigs unterworfen, und die Verzauberung, die Bethor auf mein Buch legte, untermauert dies. Aber bevor ich Euch glaube, muss ich den Beweis haben, dass Ihr der Geißel feindlich gegenübersteht.\n\nEs gibt einen alten, blutigen Altar kurz vor der Südküste dieser Insel. Er wird von einer mächtigen Dienerin der Geißel, Lillith Nefara, verwendet.\n\nNehmt eine Kerze des Heranlockens aus dieser Kiste hier. Entzündet sie auf dem Altar, und Lillith wird erwachen. Vernichtet Lillith, und ich werde Euch glauben, dass Ihr ein Gegner des Lichkönigs seid.", progress = nil, completion = "Ihr habt Lillith Nefara getötet und damit bewiesen, dass Ihr ein Feind der Geißel seid. Unglaublich.\n\nIch glaubte, der einzige Untote mit freiem Willen zu sein, aber Ihr habt mir gezeigt, dass es andere gibt, die der Kontrolle des Lichkönigs getrotzt haben.", rewards = "Ihr bekommt:\n\n"},
[410] = {title = "Der Schlummernde Schatten", objective = "Dies ist ein alter, abgewetzter, blutiger Tisch.", description = nil, progress = "Dies ist ein alter, abgewetzter, blutiger Tisch.", completion = "Ihr platziert die Kerze des Heranlockens auf dem Tisch und entzündet sie...", rewards = nil},
[411] = {title = "Die Rückkehr des abtrünnigen Lichs", objective = "Bringt den Netheredelstein zu Bethor Iceshard nach Undercity.", description = "Bringt meinem alten Kameraden Bethor diesen Netheredelstein. Er wird uns ermöglichen, miteinander zu kommunizieren... und ich habe ihm eine Menge zu erzählen.", progress = "Habt Ihr Gunthers Buch zurückgebracht? Hat er geantwortet?", completion = "Ihr habt ihn dazu gebracht, sich uns anzuschließen! Ihr habt den Verlassenen einen großen Dienst erwiesen, &lt;Name&gt;. Die dunkle Fürstin wird das erfahren.", rewards = "Ihr bekommt:\n\nKnochenrundschild"},
[412] = {title = "Operation Rekombobulationsgerät", objective = "Bringt Razzle Sprysprocket in Kharanos 8 Restabilisationszahnräder und 8 gyromechanische Getriebeteile.", description = "Nach genauerer Analyse der Situation in Gnomeregan sieht es so aus, als hätten wir nicht nur dabei versagt, die Troggs auszulöschen, sondern als hätten wir dabei auch noch einen Großteil des Volkes der Gnome in schreckliche, hirnlose, bösartige Lepragnome verwandelt.\n\nOzzie und ich haben vor, den schrecklichen Lepraeffekt mit unserer jüngsten Erfindung wieder rückgängig zu machen: der Rekombobulator. Die Maschine ist beinahe fertig, aber wir brauchen dringend einige Restabilisationszahnräder und gyromechanische Getriebeteile. Besorgt uns ein paar davon bei den Lepragnomen drüben in Gnomeregan.", progress = "Der Rekombobulator wird laufen wie geschmiert, sobald wir ausreichend Restabilisationszahnräder und gyromechanische Getriebeteile haben.", completion = "Diese gyromechanischen Getriebeteile und Restabilisationszahnräder stimmen genau mit Ozzies Bauplan für das Rekombobulationsgerät überein. Sobald ich jetzt etwas Hydroschmiermittel auf die inneren Verbrennungskolben gebe, die Kurbelratsche justiere und die Zähflüssigkeit des Electrogumgels erhöhe, wird das gnomische Volk wieder wie neu sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFahr-HandschuheÖlbefleckter Umhang\n\nIhr bekommt außerdem:\n\n"},
[413] = {title = "Schimmerstarkbier", objective = "Bringt das Fass mit Schimmerstarkbier zu Gebirgsjäger Gerstenbräu.", description = "Ich möchte, dass mein Bruder Wellart mein neues Schimmerstarkbier ausprobiert. Er ist Gebirgsjäger und im südlichen Wachturm stationiert, einem von zwei Türmen an der Grenze zum Loch Modan.\n\nEr mag vielleicht kein Bierbrauer sein wie der Rest von uns Gerstenbräus, aber er trinkt gern mal einen, und ich bin mir sicher, er wird dies hier mögen.\n\nKönnt Ihr ihm dieses Fass Schimmerstarkbier für mich bringen?", progress = "Hallo, <Klasse>! Na, welche Geschäfte treiben Euch den weiten Weg bis nach hier draußen?\n\nHoffentlich etwas Aufregendes. Ich hatte seit Tagen keinen ordentlichen Kampf mehr, und dieses Fass Bier ist so gut wie leer...", completion = "&lt;Gebirgsjäger Gerstenbräu probiert das Schimmerstarkbier... &gt;\n\nOh, wow! Dieses Zeug treibt einem wirklich Glanz in die Augen. Ich fühle mich, als könnte ich im Dunkeln sehen!", rewards = "Ihr bekommt:\n\n"},
[414] = {title = "Starkbier für Kadrell", objective = "Bringt das Fässlein mit Schimmerstarkbier zu Gebirgsjäger Kadrell.", description = "Ich habe inzwischen mehr von diesem Schimmerstarkbier getrunken, das mein Bruder gebraut hat - das ist großartiges Zeug! Ein Gebirgsjägerkumpel von mir muss das mal probieren. Er heißt Kadrell und patrouilliert normalerweise entlang der Straße durch Thelsamar beim Loch Modan.\n\nUm nach Thelsamar zu gelangen, müsst Ihr südostwärts durch den Tunnel gehen und dann nach Nordosten abbiegen, wenn der Pfad auf eine Straße trifft. Dieser Straße folgt Ihr direkt bis nach Thelsamar.\n\nGebt Gebirgsjäger Kadrell dieses Fässlein Schimmerstarkbier und schaut mal, was er davon hält!", progress = "Seid gegrüßt, <Klasse>, und willkommen in Thelsamar!", completion = "Und jetzt lasst mich mal versuchen... \n\nBeim Barte Magnis! Dieses Zeug haut einem die Birne weg! Und macht dabei die Gliedmaßen so leicht.\n\nIch fühle mich, als könnte ich fliegen!", rewards = "Ihr bekommt:\n\n"},
[415] = {title = "Rejolds neues Gebräu", objective = "Sprecht mit Rejold Gerstenbräu.", description = "Rejold Gerstenbräu aus Brewnall hat nach Euch gefragt.\n\nEr möchte mit Euch über ein neues Getränk reden, das er gebraut hat... er sagte etwas davon, dass Ihr ihm vielleicht dabei helfen könntet. Vielleicht wollt Ihr also wieder nach Brewnall zurückkehren, um herauszufinden, worum es geht.\n\nEs könnte etwas Freibier für Euch drin sein...", progress = nil, completion = "&lt;Name&gt;! Erinnert Ihr Euch an das Schimmerkraut, das Ihr mir gebracht habt? Nun, ich habe es in einigen der Rezepte, an denen ich zuletzt gearbeitet habe, ausprobiert, und eines davon gelang einfach großartig!\n\nHier, versucht es und sagt mir, was Ihr davon haltet...", rewards = "Ihr bekommt:\n\nBecher mit Schimmerstarkbier"},
[416] = {title = "Rattenfang", objective = "Bringt Gebirgsjäger Kadrell in Thelsamar 12 Tunnelrattenohren.", description = "Wir haben im Westen ein Problem mit einer echten Plage. Kobolde der Tunnelratten sind ins Vorgebirge eingedrungen, haben dort ihre Baue eingerichtet und verdrecken unser Land mit ihrem Abfall!\n\nWir wollen, dass sie ausgelöscht werden. Jagt sie, bringt mir ihre Ohren und kassiert das Kopfgeld.\n\nIhr findet die Kobolde der Tunnelratten und ihre Baue westlich von Thelsamar überall über den Berghang verteilt.", progress = "Seid gegrüßt, <Name>. Wie steht es mit der Rattenjagd?", completion = "Igitt! Als ich diese Ohren verlangte, hatte ich keine Ahnung, dass sie so schrecklich stinken würden.\n\nHier ist Eure Belohnung, &lt;Name&gt;. Gut gemacht.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBrandbalg-ArmschienenChevaliers-Stiefel\n\nIhr bekommt außerdem:\n\n"},
[417] = {title = "Pilotenrache", objective = "Tötet Marterklaue.\n\nBringt Pilot Hammerfoot die räudige Klaue des Bären und Hildelves Tagebuch.", description = "Hildelve schrieb in sein Tagebuch, dass er von Marterklaue, einem \"gewaltigen Eisklauenbären\", angegriffen wurde. Er hat die Bestie verjagt, aber nicht, ohne vorher übel zugerichtet zu werden.\n\nWenn man sich den Zustand von Hildelves Leiche so ansieht, muss Marterklaue später wiedergekommen sein und ihn getötet haben.\n\nJedenfalls schrieb Hildelve in sein Tagebuch einen letzten Wunsch:\n\nRache an Marterklaue.", progress = "Hallo, <Name>. Wisst Ihr etwas über den Verbleib meines Freundes Hildelve?", completion = "Das sind traurige Neuigkeiten, denn Hildelve war ein guter Freund. Ich wünschte, ich hätte dort mit Euch sein können, als Ihr die Bestie Marterklaue gefunden habt!\n\nDanke, &lt;Name&gt;. Eure Tat wird den Piloten der Belagerungsbrigade von Ironforge in Erinnerung bleiben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHandwerkerdolchKompakter Hammer\n\nIhr bekommt außerdem:\n\n"},
[418] = {title = "Thelsamar-Blutwurst", objective = "Bringt Vidra Hearthstove in Thelsamar 3 Stück Bärenfleisch, 3 Portionen Ebergedärme und 3 Portionen Spinnensekret.", description = "Es gibt hier in Thelsamar immer genug Mäuler zu stopfen, mit all den Kindern, die ein und aus gehen, und den Arbeitern von den Ausgrabungsstätten, die nach einem arbeitsreichen Tag hereinkommen. Wir sind berühmt für unsere Blutwurst, Ihr habt sie nicht zufällig schon einmal probiert?\n\nNein? Nun, hierzulande muss man für seine Mahlzeiten arbeiten, und glaubt nur nicht, dass Ihr eine Ausnahme seid, nur weil Ihr ein toller <Klasse> seid.\n\nIch brauche Bärenfleisch, Ebergedärme für die Pelle und Spinnensekret als Würzmittel. Bringt mir das alles und überlasst dann Vidra das Kochen!", progress = "Ich bin so weit, dass ich mit dem Kochen anfangen könnte; habt Ihr die Zutaten?", completion = "Vertraut mir, es ist schwerer als es aussieht, aber... \n\nAch, ich habe bisher noch nie jemanden getroffen, der sich sehr für die Herstellung von Würsten interessiert hat, aber ich werde Euch für alle Fälle dennoch das Rezept geben. Hier, und denkt immer daran, sie zu essen, solange sie frisch sind!", rewards = "Ihr bekommt:\n\nBlutwurstRezept: Blutwurst"},
[419] = {title = "Der vermisste Pilot", objective = "Findet Pilot Hildelve.", description = "Mein Freund Mori Hildelve, ebenfalls ein Pilot der Belagerungsmaschinen, hat sich in den Hügeln verirrt. Wir haben nach einem seltenen Erz gesucht, das man für hochwertiges Sprengpulver benötigt, und während unserer Suche hat er seine Maschine einen steilen Hügel hinaufgefahren und sie dabei kaputt gemacht!\n\nImmer noch überzeugt davon, dass es in diesen Bergen Erz gibt, hat er mich beauftragt, unsere Maschinen zu bewachen, während er zu Fuß weitersuchen wollte.\n\nDas ist jetzt mehrere Tage her, und ich habe in den Hügeln des Nachts das Knurren von Raubtieren gehört. Mori ist ein zäher Bursche, aber ich mache mir Sorgen.\n\nBitte, <Name>. Sucht ihn.", progress = nil, completion = "Hier liegt die Leiche eines Zwergs - zerfetzt, gefroren und von Aasfressern blankgefressen. Seine Hand umklammert ein Buch, das die grob hingekritzelten Aufzeichnungen von Mori Hildelve enthält. Um ihn gehüllt, nach wie vor in sehr gutem Zustand, ist eine Brigadiersweste.\n\nAn diesem grausigen Ort muss der Pilot der Belagerungsmaschinen sein Ende gefunden haben.", rewards = "Ihr bekommt:\n\nBelagerungsbrigadenweste"},
[420] = {title = "Senirs Beobachtungen", objective = "Überbringt Senir Whitebeard in Kharanos Grelins Bericht.", description = "Die Troggs im Tunnel sind extrem feindselig und scheinen nicht zu zögern, durch den Tunnel reisende Leute anzugreifen. Ihr seid aber offenbar hart genug im Nehmen, also solltet ihr wahrscheinlich sicher sein.\n\nEine Wegbeschreibung? Wenn Ihr mit Senir sprechen wollt, findet Ihr ihn in Kharanos.\n\nArbeitet Euch durch den Tunnel und folgt einfach weiter der Straße, wenn Ihr auf der anderen Seite herauskommt, denn sie führt direkt nach Kharanos.", progress = "Wie geht es Euch? Wollt Ihr vielleicht etwas mit mir trinken? Es gibt in der Kälte sonst nichts zu tun.", completion = "Was ist das? Ah, der Bericht meines Bruders. Hmm... \n\nIch habe ihm gesagt, er soll den Namen des Königs nur dezent einsetzen, aber er wollte ja nicht auf mich hören. Es kann nicht schaden, schätze ich, aber es werden sich auf alle Fälle einige im Senat die Haare raufen. Nicht, dass die diese Rauferei nicht mal nötig hätten! Ha!\n\nNichtsdestotrotz heißt das wohl, dass ich meinen Bericht ebenfalls nach Ironforge schicken sollte, aber ich muss zugeben, dass ich etwas im Rückstand bin. Verdammte Kälte.\n\nIch dürfte später etwas Arbeit für Euch haben, wenn Ihr Interesse habt.", rewards = "Ihr bekommt:\n\n"},
[421] = {title = "Wertbeweis", objective = "Dalar Dawnweaver auf dem Grabmal will, dass Ihr 5 Moonrage-Weißskalps tötet.", description = "Lady Sylvanas hat Varimathras damit beauftragt, die Gebiete der Menschen und Zwerge im Süden zu erobern.\n\nAber dieser Idiot Arugal - ein Scharlatan aus Dalaran und heutzutage eine verfluchte Kreatur der Burg Shadowfang - hat auf verantwortungslose Weise mit seiner Magie den strategischen Stützpunkt des Silberwaldes verheert.\n\nIch brauche einen geschickten Kämpfer, der dabei hilft, die Suppe auszulöffeln, die Arugal uns eingebrockt hat. Beweist Euch mir, indem Ihr 5 Moonrage-Weißskalps tötet. Man findet die elenden Bestien oft nur ein kleines Stück abseits der Straße, am Fuße des Hügels dort unten.", progress = nil, completion = "Ihr habt mir gut gedient, &lt;Klasse&gt;. Mir ist klar, dass Ihr mir eine wertvolle Hilfe sein werdet, wenn ich beginne, den Silberwald von Arugals Fluch zu befreien.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nArkane Intelligenz\n\nIhr bekommt:\n\n"},
[422] = {title = "Arugals Torheit", objective = "Beschafft Dalar Dawnweaver auf dem Grabmal die Arznei des Arugal.", description = "Wie Arugal in die Kirin Tor aufgenommen wurde, ist mir schleierhaft. Seine Zauberkunst schien so billig wie schlecht nachgemachter Schmuck.\n\nAm wichtigsten ist es erst einmal, herauszufinden, welche Art von Magie Arugal genau verwendet hat, damit ich sie gegen ihn verwenden und den Silberwald für die dunkle Fürstin einnehmen kann.\n\nArugal hielt sich zuerst auf der Weizenfarm etwas nördlich der Brücke auf. Einer der Todespirscher berichtete, dass er einige Zauberbücher gesehen hätte, sie aber nicht beschaffen konnte. Beschafft mir den Zauber namens 'Arznei des Arugal' aus diesen Büchern.", progress = "Bevor ich weiß, womit wir es hier genau zu tun haben, <Klasse>, muss ich den Zauber untersuchen, der als 'Arznei des Arugal' bekannt ist. Bringt ihn mir umgehend, oder ich bin gezwungen, mir einen geeigneteren Diener zu suchen.", completion = "Das ist genau der Zauber, den ich suchte, &lt;Klasse&gt;. Wenn Eure Hingabe an die Sache der dunklen Fürstin weiterhin so ungetrübt bleibt, werdet Ihr eine große Zukunft unter den Verlassenen haben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nArkane Intelligenz\n\nIhr bekommt:\n\n"},
[423] = {title = "Arugals Torheit", objective = "Bringt Dalar Dawnweaver am Grabmal 6 Nimmersattfesseln und 3 Dunkelseelenfesseln.", description = "Bei der Untersuchung von Arugals Arbeit haben sich meine schlimmsten Befürchtungen bestätigt. Der alte Taugenichts war nicht einmal qualifiziert genug, um die Nachttöpfe in Dalaran zu leeren, davon, die Kirin Tor in ihrer schwersten Stunde zu repräsentieren, ganz zu schweigen. Narren!\n\nArugal benutzte verzauberte Gegenstände, um seine schwache Magie zu verstärken. Ich muss diese Gegenstände selbst untersuchen. Zieht los und erschlagt so lange Moonrage-Nimmersatts und Moonrage-Dunkelseelen, bis Ihr genug ihrer verzauberten Fesseln für meine Nachforschungen gesammelt habt. Man hat diese üblen Kreaturen im Norden und Osten gesehen.", progress = "Ich brauche 6 Nimmersattfesseln und 3 Dunkelseelenfesseln, bevor ich die Situation einschätzen und eine endgültige Lösung für Arugal ersinnen kann. Und jetzt kommt meiner Aufforderung nach und erschlagt Moonrage-Nimmersatts und Moonrage-Dunkelseelen, bis Ihr habt, was ich brauche.", completion = "Ich hoffe, ich kann aus dieser kleinen Auswahl genug Energie ziehen. Vielleicht hätte ich Euch mehr Fesseln holen lassen sollen.\n\nNichtsdestotrotz habt Ihr großes Geschick darin bewiesen, diese zu sammeln, &lt;Klasse&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nArkane Intelligenz\n\nIhr bekommt:\n\n"},
[424] = {title = "Arugals Torheit", objective = "Tötet Grimson den Blassen und bringt seinen Kopf zu Dalar Dawnweaver auf das Grabmal.", description = "Ich werde tatsächlich länger brauchen, als ich gedacht hätte, die dunklen Geheimnisse hinter den Verzauberungen, die Arugal verwendete, zu entdecken.\n\nIn der Zwischenzeit müsst Ihr Euch um ein kleines Problem kümmern, das unsere Dunkelpirscher entdeckt haben. Es sieht so aus, als hätte Arugal seiner Magie erlaubt, sich bis zur Tiefenfelsmine in den Hügeln im Südosten auszubreiten.\n\nDiese Mine wäre eine ziemlich nützliche Ressource für Varimathras' Vormarsch.\n\nIch will, dass Ihr Grimson den Blassen, den besudelten Großknecht der Mine, enthauptet. Mit seinem Tod sollte die Mine uns gehören.", progress = "Ist Grimson der Blasse erschlagen? Varimathras wird nicht gerade glücklich sein, wenn wir seine Wünsche ignorieren.", completion = "Wunderbar. Die Mine wird unseren Truppen hervorragende Rohstoffe liefern, wenn wir uns im Silberwald und nach Azeroth hinein ausbreiten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nArkane Intelligenz\n\nIhr bekommt:\n\n"},
[425] = {title = "Ivar der Verfaulte", objective = "Tötet Ivar den Verfaulten und bringt Ivars Kopf zu Rane Yorick auf dem Ivar-Feld.", description = "Mein Bruder Quinn und ich wurden beauftragt, den Silberwald auszukundschaften und Hochexekutor Hadrec Bericht zu erstatten. Aber wir kamen nicht weit - als wir über diese Farm gingen, wurden wir von einem Ghul namens Ivar der Verfaulte angegriffen.\n\nWir entkamen Ivar, aber er verletzte Quinn schwer. Dank des Trankes, den Ihr ihm gegeben habt, heilt er, aber Ivar könnte wiederkommen, bevor Quinn sich erholt hat.\n\nTötet Ivar, damit Quinn genug Zeit hat, sich zu regenerieren. Ivar hält sich üblicherweise in dem Schuppen da drüben auf und wartet darauf, dass meine Wachsamkeit nachlässt.", progress = "Habt Ihr Ivar den Verfaulten getötet? Wenn Ihr es nicht für mich und meinen Bruder tun wollt, dann tut es für die Verlassenen.", completion = "Ah, habt Dank. Ihr habt meine Anerkennung, &lt;Name&gt;.\n\nUnd ich werde Euch in dem Bericht an meine Vorgesetzten erwähnen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesteppte ArmschienenVerwitterter Gürtel\n\nIhr bekommt außerdem:\n\n"},
[426] = {title = "Die überrannte Mühle", objective = "Sammelt 5 schartige Rippen sowie 3 geschwärzte Schädel und kehrt dann zu Todeswache Dillinger nach Brill zurück.", description = "Die Geißel versucht, bei Agamands Mühlen einen Stützpunkt zu errichten. Wenn ihnen das gelingt, können sie weitere Angriffe innerhalb von Tirisfal unternehmen.\n\nEs wurden klare Befehle erteilt. Die Diener der Geißel in den Mühlen müssen vernichtet werden.\n\nGeht zu den Mühlen. Sammelt schartige Rippen von klappernden Skelettsoldaten und Trümmerschädelsoldaten sowie geschwärzte Schädel von dunklen Skelettmagiern.\n\nUm zu den Mühlen zu gelangen, folgt der Straße westwärts. Nachdem Ihr die Brücke überquert habt, nehmt die erste Abzweigung nach Norden und folgt diesem Weg. Wenn Ihr die Windmühlen seht, beginnt die Schlacht.", progress = "Unser Krieg gegen die Geißel dauert noch immer an, <Name>. Tut das Eurige und werft diese verfluchten, hirnlosen Untoten wieder zurück in die Pestländer!", completion = "Eure Bemühungen im Krieg sind spürbar, &lt;Name&gt;. Ich werde Euch nicht für etwas Notwendiges danken, aber die Todeswachen von Tirisfal werden sich Eures Namens erinnern.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGruftwandler-StiefelFeste Stoffbeinkleider\n\nIhr bekommt außerdem:\n\n"},
[427] = {title = "Im Krieg mit dem Scharlachroten Kreuzzug", objective = "Exekutor Zygand von Brill verlangt, dass Ihr 10 Scharlachrote Krieger tötet.", description = "Die Dokumente, die Exekutor Arren uns zur Verfügung stellte, verschaffen uns genau die Atempause, die wir in unserem Kampf gegen den Scharlachroten Kreuzzug benötigen. Wir kennen jetzt dessen genaue Aufenthaltsorte überall in Tirisfal.\n\nAber leider haben die Todeswachen noch ganz andere Sorgen. Die Armee des Lichkönigs wächst jede Nacht an. Wir benötigen jemanden, der wie Ihr gern \"Initiative\" zeigt, um den Scharlachroten Kreuzzug ins Grab zu bringen.\n\nBeweist mir, dass Ihr der dunklen Fürstin dienen könnt, indem Ihr nach Westen zum Turm hinter Sollidens Bauernhof reist und dort 10 Scharlachrote Krieger erschlagt.", progress = nil, completion = "Wunderbar, &lt;Klasse&gt;. Euer Geschick in der Kriegskunst ist nicht zu leugnen.", rewards = "Ihr bekommt:\n\n"},
[428] = {title = "Die verlorenen Todespirscher", objective = "Findet die Todespirscher Quinn und Rane Yorick.", description = "Vor einigen Wochen wurden zwei unserer Todespirscher, Rane und Quinn Yorick, auf eine Aufklärungsmission durch den nördlichen Silberwald geschickt. Wir haben nichts mehr von ihnen gehört.\n\nSie könnten der Geißel zum Opfer gefallen sein, doch wenn dem so ist, will ich es bestätigt wissen. Findet diese Todespirscher.\n\nIhre erste Aufgabe war es, die Bauernhöfe im nördlichen Silberwald auszukundschaften. Ihr solltet dort mit Eurer Suche beginnen.", progress = nil, completion = "Ihr habt uns gefunden! Und das keinen Moment zu früh...", rewards = "Ihr bekommt:\n\n"},
[429] = {title = "Wilde Herzen", objective = "Sammelt 6 verfärbte Worgherzen und bringt sie zu Apotheker Renferrel auf dem Grabmal.", description = "Mein Bruder Quinn wurde von dem Ghul Ivar dem Verfaulten schwer verletzt, und ich glaube nicht, dass er ohne magische Hilfe wieder vollständig genesen wird. Auch wenn ich kein Apotheker bin, so weiß ich doch, dass unsere Apotheker Heiltränke aus verfärbten Worgherzen herstellen können.\n\nSammelt einige solcher Herzen und bringt sie zu Apotheker Renferrel am Grabmal im Süden. Kommt dann mit dem Trank hierher zurück.\n\nZwischen hier und Maldens Obsthain im Osten werdet Ihr jede Menge Worgs vorfinden.", progress = "Meine Zeit ist knapp, <Klasse>, denn die dunkle Fürstin hat mich mit einer wichtigen Aufgabe betraut.", completion = "&lt;Renferrel nimmt die Herzen entgegen.&gt;\n\nEs ist beunruhigend zu hören, dass unsere Todespirscher ihren Auftrag nicht erfüllt haben.\n\nHoffen wir, dass solche Fehlschläge die Ausnahme sind.\n\nIch werde Euch den Trank gleich geben, aber hier habt Ihr erst einmal sein Rezept - falls diese Todespirscher wieder einmal Hilfe benötigen, könnt Ihr sie ihnen vielleicht selbst verabreichen.", rewards = "Ihr bekommt:\n\nRezept: Verfärbter HeiltrankVerfärbter Heiltrank"},
[430] = {title = "Rückkehr zu Quinn", objective = "Bringt Quinn Yorick auf dem Ivar-Feld, nördlich des Grabmals, Quinns Trank.", description = "Hier habt Ihr den Trank, mit dem Ihr Quinn Yoricks Erholung beschleunigen könnt.\n\nWenn Ihr mich jetzt entschuldigen mögt, ich habe wirklich wichtige Dinge zu erledigen...", progress = "Meine Schwester sagte mir, Ihr wäret hier, um uns zu helfen. Stimmt das?", completion = "&lt;Quinn nimmt den Trank und trinkt ihn.&gt;\n\nJa, ich kann spüren, wie er wirkt. Ich werde bald wieder reisen können.\n\nIhr habt mir einen großen Gefallen getan, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[431] = {title = "Kerze des Heranlockens", objective = "Ihr schnappt Euch eine der Kerzen und verstaut sie in Eurem Rucksack.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKerze des Heranlockens"},
[432] = {title = "Diese verfluchten Troggs!", objective = "Tötet für Großknecht Stonebrow im Gol'Bolar Steinbruch 6 Schädelhauer der Felsenkiefer.", description = "Diese vom Licht verfluchten Troggs verwandeln meinen Arbeitsplatz in eine Ruine. Schaut Euch das an, da geht schon wieder ein Pulverfass hoch.\n\nOh, ich wünschte ich könnte da runtergehen und allen einzeln ihre dürren Hälse umdrehen! Ich will sie alle töten!\n\nDas kann nicht gut für meine Gesundheit sein, all dieser Stress und diese Wut... Was haben sie mir gelassen? Nichts!\n\nIch würde sie persönlich umbringen, aber ich ziele nicht mehr so gut wie früher. Geht in den Steinbruch und tötet einige dieser dreckigen Mistviecher! Ich werde Euch bezahlen! Hauptsache, Ihr verletzt sie, tötet sie!", progress = "Das macht mich dermaßen wütend! Grrr...", completion = "Nun, jetzt geht es mir schon etwas besser... \n\nAber ich werde mich erst wieder richtig freuen können, wenn sie alle tot sind! Restlos alle!", rewards = "Ihr bekommt:\n\n"},
[433] = {title = "Im Dienste des Volkes", objective = "Tötet für Senator Mehr Stonehallow im Gol'Bolar Steinbruch 10 Knochenknacker der Felsenkiefer.", description = "Als Mitglied des Senats und der Forscherliga habe ich mir vorgenommen, mich um den Teil der Trogg-Plage zu kümmern, die unser Land heimsucht.\n\nSie haben den Gol'Bolar Steinbruch wirklich ziemlich verwüstet, und das ohne erkennbaren Grund. Als wir tiefer in die Erde hineingruben, strömten sie heraus, zerstörten unsere Ausrüstung und verjagten die Minenarbeiter. Wir können nicht viel mehr tun, als das ganze Pack auszulöschen, alles wieder aufzubauen und dann wieder an die Arbeit zu gehen.\n\nWenn Ihr mir mit den Troggs helft, werde ich Euch gern für Eure Zeit, die Ihr dafür opfert, entschädigen.", progress = "Wenn wir die Troggs vom Gol'Bolar Steinbruch entfernen können, wäre das der Erste von vielen Schritten, die wir unternehmen müssen, um uns von dieser Bedrohung zu befreien.", completion = "Das ist ein Anfang. Hoffentlich können wir ihn nutzen und einige Gebirgsjäger hineinschicken, um das Gebiet zu sichern. Dann können wir damit anfangen, unsere Infrastruktur wieder aufzubauen und unsere Minenarbeiter wieder an die Arbeit schicken.\n\nDanke für Eure Unterstützung, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[434] = {title = "Der Angriff!", objective = "Bleibt im Garten, bis Lord Gregor Lescovar und Marzon die Stille Klinge ihr Gespräch beendet haben. Schaltet sie danach beide aus, bevor Ihr nach Stormwind zu Elling Trias zurückkehrt.", description = "Nachdem ich dem Spionagebot die Verkleidung angelegt habe, begibt er sich hinein, um mit Lescovar zu sprechen. Die Wachen sollten ihn ohne Probleme durchlassen.\n\nWährend Ihr Material für mich gesammelt habt, habe ich Marzon darüber informiert, dass es für ihn und Lescovar an der Zeit sei, sich wieder zu treffen. Ich habe sogar einige falsche Informationen verlautbaren lassen.\n\nLescovar wird seine Wachen wegschicken und hier draußen im Garten auf Marzon warten. Tretet in Aktion, wenn Ihr etwas über die Defias hört. Ihr müsst sie beide eliminieren. Kapiert?\n\nWenn Ihr das erledigt habt, sprecht Ihr mit Trias.", progress = nil, completion = "Es ist also vollbracht? Gut. Ich danke Euch vielmals für Eure Diskretion, &lt;Name&gt;. Ihr habt Euch in mehr als einer Hinsicht als würdig erwiesen. Ich werde Euch und Euren Aufstieg innerhalb der Allianz ganz bestimmt im Auge behalten.\n\nAchtet darauf, dass Ihr Eure Finger nicht schmutzig macht.", rewards = "Ihr bekommt:\n\n"},
[435] = {title = "Eskorte für Erland", objective = "Begleitet Erland durch die Wölfe hindurch zu Rane Yorick.", description = "Die Wölfe da draußen wollen nicht abhauen, und jedesmal, wenn ich einen Schritt aus der Tür mache, schauen sie mich böse an. Sie müssen unglaublich hungrig sein, wenn sie mich für essenswert halten.\n\nIch muss mich bei meiner Kampfgefährtin, Todespirscherin Rane Yorick, melden. Und um zu Rane zu kommen, brauche ich Hilfe gegen diese Wölfe.\n\nBitte begleitet mich! Ach ja, da draußen sind eine Menge Wölfe, wir hätten also eine bessere Chance, wenn Ihr Freunde dabei hättet, die ebenfalls helfen können...", progress = nil, completion = "Danke für die Hilfe, &lt;Name&gt;. Ich hatte befürchtet, Erland wäre den Gefahren des Silberwaldes erlegen. Aber dank Eurer Hilfe war dem offensichtlich nicht so.", rewards = "Ihr bekommt:\n\nTodespirscherkurzschwert"},
[436] = {title = "Ironbands Ausgrabungsstätte", objective = "Sprecht mit Forscher Fellhew.", description = "Ausgrabungsleiter Ironband leitet die Ausgrabung einiger alter Ruinen östlich des Sees. Er hat zuletzt wenig Fortschritte gemacht, besonders, wenn man all den Nachschub bedenkt, den wir ihm geschickt haben.\n\nIronband ist ein bodenständiger, ehrlicher Zwerg, der gern Resultate sieht, und daher mache ich mir Sorgen, dass da irgendwelche Kräfte gegen ihn arbeiten.\n\nGeht zu Ironbands Ausgrabungsstätte und sprecht mit Magmar Fellhew. Er kümmert sich um die Einzelheiten an der Stätte und wird wissen, warum es so langsam voran geht.\n\nUm zur Ausgrabungsstätte zu gelangen, müsst Ihr um die Südspitze des Sees herum und dann nach Osten gehen.", progress = nil, completion = "Jern will wissen, was uns aufhält, hm?\n\nIronband verfasst gerade seinen jüngsten Fortschrittsbericht mit allen Details, aber ich kann Euch Folgendes sagen:\n\nEs sind die Troggs!", rewards = "Ihr bekommt:\n\n"},
[437] = {title = "Das Todesfeld", objective = "Tötet Gnolle der Moderfelle auf dem Todesfeld.\n\nSobald Nachtseele auftaucht, tötet sie ebenfalls.\n\nBringt Nachtseeles Essenz zu Hochexekutor Hadrec auf das Grabmal.", description = "Unsere ursprünglichen Spähberichte über den Silberwald zeigen, dass die Moderfelle auf einer alten Farm im Norden, nahe dem Todesfeld, einen Stützpunkt haben. Wir haben kleine Angriffe auf sie gestartet, aber jedesmal werden sie von der Banshee Nachtseele unterstützt, die ihre Magie einsetzt, um unsere Truppen in die Flucht zu schlagen.\n\nWir wollen Nachtseele vernichtet sehen.\n\nGeht ins Todesfeld und greift die Moderfelle an. Falls Ihr Nachtseele nicht seht, tötet so lange Moderfellgnolle, bis sie auftaucht, und besiegt sie dann.\n\nIhre Essenz wird zu Staub zerfallen. Bringt mir diesen Staub als Beweis.", progress = "Habt Ihr Nachtseele besiegt, <Name>? Unser Erfolg im Kampf gegen die Moderfelle hängt von ihrer Vernichtung ab!", completion = "Ich habe von Eurem erfolgreichen Überfall auf die Moderfellgnolle gehört, &lt;Name&gt;, und diese Essenz ist der Beweis für Nachtseeles Tod.\n\nDie Geißel hat heute an Boden verloren. Euer Ansehen bei den Verlassenen ist gestiegen.", rewards = "Ihr bekommt:\n\nAufklärer-Stiefel"},
[438] = {title = "Die verfallene Fähre", objective = "Geht zur verfallenen Fähre.\n\nSucht nach dem Grund, warum die Geißel dort ist.", description = "<Name>, wir haben ein neues Nest der Geißel entdeckt: Die verfallene Fähre. Die Fähre liegt östlich des Grabmals und wird von Moderfellgnollen und anderen Untoten schwer bewacht.\n\nEs muss einen Grund dafür geben, warum die Geißel dieses Gebiet besetzt hat. Geht zur verfallenen Fähre und findet heraus, warum die Geißel sich dort aufhält.", progress = nil, completion = "In diesem Boot ist ein Haufen eingewickelter Leichen aufgestapelt. Und wenn man nach Osten über den Lordameresee schaut, kann man gegenüber auf der Insel Fenris ein Dock sehen.\n\nDas Schicksal muss diese Toten auf der Insel Fenris ereilt haben.", rewards = "Ihr bekommt:\n\n"},
[439] = {title = "Auf den Spuren der Moderfelle", objective = "Bringt Deliahs Ring zu Hochexekutor Hadrec auf das Grabmal.", description = "Aus den Leichen ragt eine nicht eingewickelte Hand heraus. Es handelt sich um die Hand einer Frau, von der Seuche pockennarbig, aber relativ frisch. \n\nAn der Hand befindet sich ein Ring. Als Ihr den Ring entfernt und untersucht, entdeckt Ihr eine Gravur:\n\n\"Für Deliah\".", progress = "<Name>. Ihr kehrt zurück; darf ich also annehmen, dass Eure Nachforschungen Früchte trugen?", completion = "Ihr sagt, dieser Ring wurde von einer erst kürzlich getöteten Frau getragen?\n\nDie einzige nahe gelegene Quelle für solch einen Körper wären die Massengräber in Tirisfal. Die Moderfellgnolle müssen die Leichen wohl zur Insel Fenris bringen!", rewards = "Ihr bekommt:\n\n"},
[440] = {title = "Der gravierte Ring", objective = "Bringt Deliahs Ring zu Magistrat Sevren nach Brill.", description = "Wenn Ihr den Ehemann oder Geliebten finden wollt, der Deliah ihren Ring gab... dann sprecht mit Magistrat Sevren in Brill. Er sollte alle Dokumente über die jüngsten Todesfälle haben und wird mit etwas Glück herausfinden können, wer Deliah ist.\n\nAber ich würde meine Hoffnungen nicht zu hoch stecken. Wer auch immer ihr den Ring gab, ist wahrscheinlich tot. Oder, wenn er untot ist, kümmert Deliah ihn wahrscheinlich nicht mehr.", progress = "Hallo, <Name>. Was führt Euch nach Brill zurück?", completion = "Vor nicht allzu langer Zeit lebte in Brill eine Deliah. Sie wurde im Massengrab beigesetzt, aber wenn das, was Ihr sagt, zutrifft, dann müssen die Moderfellgnolle ihre Leiche gestohlen und in den Silberwald gebracht haben.\n\nDie Moderfelle müssen, wie alle Teile der Geißel, vernichtet werden. Ich vertraue darauf, dass Ihr darauf hinarbeitet.", rewards = "Ihr bekommt:\n\n"},
[441] = {title = "Raleigh und Undercity", objective = "Bringt Deliahs Ring zu Raleigh.", description = "Deliah hatte einen Ehemann, Raleigh, der nun in Undercity sein Zuhause hat. Wenn die Deliah, die in Brill wohnte, die ist, der dieser Ring gehörte, dann wird es Raleigh wissen.\n\nRaleigh ist im Handwerksviertel von Undercity.", progress = "Kenne ich Euch?", completion = "Ja, dieser Ring gehörte meiner Frau. Ihr Schicksal war das all derer, die diese harten Zeiten nicht überstehen. Ihr Tod bedeutet mir nichts, genauso wenig wie die Geschichte, die Ihr von der Entwendung ihrer Leiche erzählt.\n\nSolche Gefühle sind vor langer Zeit in mir erloschen. Doch ein Verlangen brennt immer noch in meinem toten Herzen, &lt;Name&gt;.\n\nDas Verlangen nach Rache.", rewards = "Ihr bekommt:\n\n"},
[442] = {title = "Sturm auf die Insel Fenris", objective = "Bringt Hochexekutor Hadrec auf dem Grabmal Thules Kopf.", description = "Es ist an der Zeit, den Standort der Geißel im Silberwald zu stürmen: die Insel Fenris.\n\nIhr müsst Euch noch einmal auf diese Insel begeben und Thule Rabenklaue vernichten. Ich will seinen Kopf!\n\nDiese Mission ist so gefahrvoll, wie sie entscheidend ist, <Name>. Ihr dürft nicht scheitern.", progress = "Der Geißel darf nicht gestattet werden, im Silberwald zu bleiben, <Name>. Kommt zu mir zurück, wenn Ihr den Beweis für Thules Tod habt.", completion = "Der Tod von Thule Rabenklaue war kein unwichtiges Ereignis, &lt;Name&gt;. Renferrel sagt mir, dass die Energien, die frei wurden, als Ihr Thule vernichtet habt, bis zum Grabmal zu spüren waren.\n\nDie Nachricht von Euren Taten verbreitet sich bei den Verlassenen wie ein Lauffeuer. Euer Wert für uns wächst unaufhörlich.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHohe Robe des SchiedsrichtersKrallenschlag\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[443] = {title = "Moderfellsekret", objective = "Bringt 8 Flaschen Moderfellsekret zu Apotheker Renferrel auf das Grabmal.", description = "Bevor wir einen Angriff auf die Insel Fenris starten können, müssen wir erst herausfinden, wer hinter den Moderfellgnollen steht. Unsere Apotheker glauben, ihr Ursprung liegt in der seltsamen Flüssigkeit, die durch ihre Körper fließt.\n\nGeht zur Insel Fenris, östlich der verfallenen Fähre, und sammelt Moderfellsekret von den Gnollen dort. Bringt es zu Apotheker Renferrel, draußen vor dem Grabmal.", progress = "Habt Ihr das Moderfellsekret, <Name>?", completion = "Sehr gut. Dieses Sekret wird uns dabei helfen, die Natur der Moderfelle zu verstehen, und könnte uns ihre Schwächen aufzeigen... \n\n... sofern sie welche haben.", rewards = "Ihr bekommt:\n\n"},
[444] = {title = "Die Ursprünge der Moderfelle", objective = "Bringt die Sekretprobe zu Bethor Iceshard nach Undercity.", description = "Ich habe das Sekret, das Ihr mir gebracht habt, in seine Grundbestandteile aufgelöst. Meine Ergebnisse sind nicht sehr aufschlussreich, aber ich konnte ermitteln, dass Hexenmeister- und Totenbeschwörermagie zur Herstellung des Sekrets verwendet wurden.\n\nWährend ich weiter das Sekret untersuche, möchte ich, dass Ihr eine Probe davon zu Bethor Iceshard nach Undercity bringt. Bethor ist kein Apotheker, aber sein Wissen von der Magie könnte uns helfen, das Geheimnis um die Moderfelle zu lüften.\n\nGeht. Ihr dürftet Bethor im Magieviertel von Undercity finden.", progress = "Meine Studien erfordern große Konzentration. Ich will also hoffen, dass Euer Besuch von Bedeutung ist.", completion = "Diese Substanz ist mit mächtigen Zaubern versetzt, von denen ich einige seit einer langen, langen Zeit nicht mehr gesehen habe... \n\nEinen Moment - ich muss einen Erkenntniszauber sprechen...", rewards = "Ihr bekommt:\n\n"},
[445] = {title = "Lieferung in den Silberwald", objective = "Bringt Apotheker Johaans Erkenntnisse zu Apotheker Renferrel im Silberwald.", description = "Zeit ist ein Luxus, den sich diejenigen, die für Lady Sylvanas arbeiten, nicht leisten können. Aber das wisst Ihr inzwischen sicher selbst.\n\nAls Mitglied der königlichen Apothekervereinigung ist es meine Pflicht, mein Wissen mit meinen Kollegen zu teilen, auf dass unsere gemeinsamen Bemühungen der dunklen Fürstin eines Tages die neue Seuche bescheren werden, die sie so ersehnt.\n\nBringt diese Erkenntnisse zu Apotheker Renferrel, der beim Grabmal im Silberwald stationiert ist. Folgt der Straße von Brill aus nach Süden. Geht dann nach Undercity südwestwärts.", progress = "Was wollt Ihr von mir, <Klasse>?", completion = "Ah, wie zuvorkommend von Apotheker Johaan, mir seine Nachforschungen zu schicken. Dank der ganzen jüngsten Entwicklungen hier im Silberwald hätte ich beinahe die Erkenntnisse vergessen, die aus Lordaeron und Tirisfal kommen. Das erinnert mich daran, dass ich diese Proben umgehend zur Nekropole losschicken muss.\n\nIhr müsst meine Abschweifungen entschuldigen. Verlängert Euren Aufenthalt im Silberwald ein wenig, &lt;Name&gt;. Ein kräftiger &lt;Klasse&gt; wie Ihr wäre hier durchaus von Nutzen.", rewards = "Ihr bekommt:\n\n"},
[446] = {title = "Thule Rabenklaue", objective = "Bringt Bethors Spruchrolle zu Apotheker Renferrel auf das Silberwald-Grabmal.", description = "Dieses Sekret wurde von einem alten Kollegen von mir hergestellt: Thule Rabenklaue. Vor dem großen Krieg war er ein junger, aufstrebender Magier, aber als der Lichkönig immer mächtiger wurde, verriet er seine Brüder und verbündete sich mit der Geißel.\n\nIch hätte nicht gedacht, dass er noch lebt, geschweige denn, dass er die Moderfelle bei ihren Vorstößen gegen uns anführt.\n\nIch kenne viele seiner Zauber und kann dabei helfen, einen Trank zu brauen, der ihnen entgegenwirkt. Nehmt diese Spruchrolle mit zurück zu Apotheker Renferrel. Auf ihr stehen die Beschwörungsformeln, die man für den Trank braucht.", progress = "Seid gegrüßt, <Name>. Was hat Bethor gesagt?", completion = "Diese Schriftrolle ist voll mächtiger Magie. Ich habe noch nie solche Kräfte in einem Trank verwendet... Es wird eine mächtige Mixtur sein und dürfte Euch wertvolle Dienste leisten, wenn Ihr Thule in seiner Festung auf der Insel Fenris angreift.", rewards = "Ihr bekommt:\n\nBethors Trank"},
[447] = {title = "Rezept für den Tod", objective = "Sammelt 6 Herzen von ergrauten Bären und 6 Proben Huschendes Blut und bringt diese zu Meisterapotheker Faranell nach Undercity.", description = "Arthas hat Truppen von schier endloser Zahl. Doch mit einer neuen Seuche könnten wir sowohl die Armee der Geißel als auch das menschliche Ungeziefer ein für alle Mal auslöschen.\n\nMeine Studien haben bewiesen, dass Spinnenblut, vermischt mit einem aus dem Herzen eines ergrauten Bären gewonnenen Toxin, zu einem tödlichen Elixier wird. Sammelt Proben von den Spinnen im Huschdunkel im Nordwesten und von den Bären, die im Silberwald umherstreifen. Bringt diese Reagenzien zu Meisterapotheker Faranell von der königlichen Apothekervereinigung in Undercity.", progress = "Seid gegrüßt, <Klasse>. Was wollt Ihr von der königlichen Apothekervereinigung?", completion = "Wie gut, dass Apotheker Renferrel Euch zu mir geschickt hat, &lt;Name&gt;. Diese Proben werden sich als durchaus nützlich für unsere Zwecke erweisen. Ich werde gleich damit anfangen, ihre toxischen und verseuchenden Eigenschaften zu untersuchen.", rewards = "Ihr bekommt:\n\nSengginwurzel"},
[448] = {title = "Meldung bei Hadrec", objective = "Meldet Euch bei Hochexekutor Hadrec auf dem Grabmal.", description = "Bevor Ihr einen Angriff auf die Insel Fenris unternehmt, meldet Euch bei Hochexekutor Hadrec. Er könnte zusätzliche Informationen oder Ausrüstung haben, die Ihr brauchen werdet.", progress = nil, completion = "Wenn das, was Bethor sagt, wahr ist, dann stellt Thule Rabenklaue eine Macht dar, um die sich jemand kümmern muss, und zwar bald.\n\nUm Euch bei dieser Aufgabe zu helfen, könnt Ihr Euch an unserem Arsenal hier bedienen...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGrober GewichtssteinGrober Wetzstein\n\nIhr bekommt außerdem:\n\nMittleres Rüstungsset"},
[449] = {title = "Der Bericht der Todespirscher", objective = "Bringt den Todespirscherbericht zu Hochexekutor Hadrec auf das Grabmal.", description = "Auch wenn Quinns Wunden heilen, möchte ich doch unseren Bericht so schnell wie möglich zu Hochexekutor Hadrec bringen. Er enthält Informationen, die für die Besetzung des Silberwaldes durch die Verlassenen von höchster Wichtigkeit sind.", progress = "Habt Ihr herausgefunden, was den Todespirschern zustieß?", completion = "Ich hatte nicht mit einem solchen Ausmaß an Aktivitäten der Geißel im Silberwald gerechnet, geschweige denn mit den Problemen, die unsere Todespirscher bei ihren Erkundungsversuchen hatten.\n\nEure Hilfe für unsere Todespirscher war unschätzbar, &lt;Name&gt;. Dafür erhaltet Ihr eine Belobigung.", rewards = "Ihr bekommt:\n\n"},
[450] = {title = "Rezept für den Tod", objective = "Bergt Apotheker Berards Tagebuch aus Pyrewood und bringt es zu Apotheker Renferrel auf das Grabmal.", description = "Ihr könnt der königlichen Apothekervereinigung noch weiter zu Diensten sein, <Name>.\n\nAls Arugal seine elenden Zauber über den Wald gelegt hat, verfluchte er eines unserer viel versprechendsten Mitglieder, Apotheker Berard. Als hirnloser Diener von Arugal ist Berard jetzt für uns nutzlos. Aber seine Erkenntnisse könnten sich als wertvoll erweisen. Er untersuchte eine längst vergessene Seuche, die vor Ewigkeiten einmal alles Leben im Lordameresee getötet hat.\n\nBergt Berards Tagebuch aus seinem Studierzimmer im Gasthaus von Pyrewood und bringt es zu Apotheker Renferrel.", progress = "Wie ich sehe, seid Ihr wieder zurück, <Name>.", completion = "Apotheker Berards Tagebuch! Ihr seid wirklich recht tapfer, &lt;Name&gt;. Jetzt lasst uns mal sehen, was Berard vorhatte, bevor er wahnsinnig wurde...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[451] = {title = "Rezept für den Tod", objective = "Bringt 6 Proben Seeschleicher-Moos, 6 Proben Seekrabbler-Moos und einen verhärteten Tumor zu Meisterapotheker Faranell nach Undercity.", description = "Laut Berards Tagebuch könnte sich das Moos von Seeschleichern und Seekrabblern bei unserer Suche nach einer neuen Seuche als nützlich erweisen. Diese Bestien leben auf den Inseln im Lordameresee im Osten.\n\nEr erwähnt außerdem einen sehr seltenen verhärteten Tumor, den er bei einem Finsterflossenmurloc entdeckte. Anscheinend war der Tumor so selten, dass Berard nur einen einzigen auftreiben konnte.\n\nSammelt Proben von diesem Moos sowie von dem seltenen verhärteten Tumor und bringt beides zu Meisterapotheker Faranell nach Undercity.", progress = "Was führt Euch nach Undercity zurück, <Name>?", completion = "Was für ein Schlag für die königliche Apothekervereinigung, Berard zu verlieren. Aber dank Eurer harten Arbeit und Apotheker Renferrels gewissenhaften Nachforschungen werden Berards Studien dennoch der dunklen Fürstin in ihrer Misere helfen können.\n\nWir stehen hier kurz vor einer großen Entdeckung, &lt;Name&gt;. Wärt Ihr nicht so in der Kriegskunst erfahren, würde ich versuchen, Euch als Mitglied für die Vereinigung anzuwerben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nNachtschimmergebräuSäurefester Umhang\n\nIhr bekommt außerdem:\n\nElixier der schwachen SeelenstärkeHurtigkeitstrank"},
[452] = {title = "Der Pyrewood-Überfall", objective = "Helft Todespirscher Faerleia, den Rat von Pyrewood zu töten.", description = "Ihr kommt gerade rechtzeitig, <Name>!\n\nDer Rat von Pyrewood wird jeden Moment zurückkehren. Arugal muss sich in der Burg um andere Dinge kümmern. Er benutzt den Rat als reine Schachfiguren, um die hirnlosen Diener von Pyrewood unter seiner Kontrolle zu halten. Aber ich glaube, dass die Söhne von Arugal sich ohne die Führung durch den Rat von Pyrewood gegen ihren Meister stellen werden.\n\nIch werde nicht allein mit ihnen allen fertig. Ihr müsst mir helfen. Gemeinsam können wir den Rat für Lady Sylvanas zerschlagen.", progress = nil, completion = "Ihr habt wie ein wahrer Jünger der dunklen Fürstin gekämpft, &lt;Name&gt;. Nachdem der Rat nun tot ist, können wir vielleicht ein für alle Mal die Kontrolle über diesen Ort erlangen und Arugal aus der Burg Shadowfang vertreiben. Ich ziehe den Hut vor Euch!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFaerleias SchildGedehnte LederbeinkleiderMystikerschal\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[453] = {title = "Auf der Suche nach der Schattengestalt", objective = "Findet die Schattengestalt. Eure Hinweise:\n\nEr stammt nicht aus Dunkelhain.\n\nEr ist eine nervöse, hektische Person.\n\nEr verließ Dunkelhain und ging nach Westen.", description = "Viel Glück, <Name>. Ich hoffe, Ihr könnt den Kerl finden, und dass er dann noch am Leben ist.\n\nWenn er die Sicherheit von Dunkelhain hinter sich gelassen hat, könnte er leicht Wildtieren zum Opfer gefallen sein.", progress = "Wer seid Ihr?? Lasst mich in Ruhe!", completion = "&lt;Jitters seufzt... &gt;\n\nJa, ich bin der Autor dieses Buches. Ihr habt mich letztendlich dann doch gefunden, wie?\n\nNun, wenn Ihr dieses Tagebuch gelesen habt... dann wisst Ihr gerade mal die Hälfte!", rewards = "Ihr bekommt:\n\n"},
[454] = {title = "Nach dem Hinterhalt", objective = "Sprecht mit Miran.", description = "Wir hatten vor dieser... Geschichte die Pulverfässer in mehreren Fuhren transportiert. Jetzt müssen wir die Arbeit aufteilen. Miran nimmt die Fässer, und ich passe auf die anderen auf.\n\nIch fühle mich nicht wohl dabei, Miran den Rest der Fracht ganz allein transportieren zu lassen. Vielleicht könntet Ihr ihn auf seiner nächsten Tour begleiten, wenn er fertig zur Abreise ist?", progress = nil, completion = "Hallo, &lt;Klasse&gt;.\n\nIhr werdet mich zur Ausgrabungsstätte begleiten? Das hört man gern... Wer weiß, was die Dunkeleisenzwerge nach Saean und seinen Spießgesellen noch alles auf Lager haben?\n\nWie auch immer, lasst mich nur noch einige letzte Kontrollen durchführen. Sprecht wieder mit mir, wenn Ihr abreisefertig seid.", rewards = "Ihr bekommt:\n\n"},
[455] = {title = "Der Algaz-Spießrutenlauf", objective = "Durchquert Dun Algaz.\n\nTötet 8 Späher der Dragonmaw und 6 Grunzer der Dragonmaw.\n\nMeldet Euch bei Valstag Ironjaw im Hafen von Menethil.", description = "Orcs vom Dragonmawklan haben im Sumpfland eine Zufluchtstätte. Und jetzt haben sie sich nach Dun Algaz ausgebreitet. Wir können nicht zulassen, dass sie ihren Einfluss auf dieses Gebiet behalten, sonst wird der Loch Modan vom Hafen von Menethil, unserer Hafenfestung im Sumpfland, abgeschnitten.\n\nBrecht durch Dun Algaz in das dahinterliegende Sumpfland durch und tötet dabei ein paar Orcs. Meldet Euch bei Valstag Ironjaw im Hafen von Menethil.\n\nNach Menethil kommt Ihr, indem Ihr Dun Algaz durchquert, anschließend nordwärts der Straße folgt und Euch dann an der Biegung westwärts haltet.\n\nWir verlassen uns auf Euch, <Name>. Ihr dürft nicht scheitern.", progress = nil, completion = "Euer Bericht enthält viele schlechte Nachrichten!\n\nIch weiß, dass die Dragonmaw verstärkt nach Algaz hineindrängen. Normalerweise verstecken sich die Dragonmaw nur oben in den Hügeln. Was sie dazu gebracht hat, nach Algaz hineinzuströmen, ist immer noch ein Rätsel... \n\nDanke, &lt;Name&gt;. Und wir werden wahrscheinlich Eure Hilfe wünschen, wenn es darum geht, sich um diese Orcs zu kümmern.", rewards = "Ihr bekommt:\n\n"},
[456] = {title = "Das Gleichgewicht der Natur", objective = "Tötet 7 junge Nachtsäbler sowie 4 junge Disteleber und kehrt dann zu Konservator Ilthalaine zurück.", description = "Seid gegrüßt, <Name>. Ich bin Konservator Ilthalaine. Meine Aufgabe in Shadowglen ist es, für den Erhalt des Gleichgewichts der Natur zu sorgen.\n\nDie Frühjahrsniederschläge waren dieses Jahr besonders heftig, was dafür sorgte, dass einige Tiere des Waldes gediehen, während andere darunter litten.\n\nUnglücklicherweise sind die Bestände an Nachtsäblern und Distelebern zu stark angewachsen. Shadowglen kann nur eine gewisse Menge Futter für diese Tiere erzeugen. Zieht los, <Klasse>, und dünnt die Eber- und die Säblerpopulation etwas aus, auf dass die Harmonie der Natur erhalten bleibt.", progress = nil, completion = "Ihr habt Eure Pflichten gut erfüllt, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAusbildungshandschuhe zum BogenschießenStammblatt-Armschienen\n\nIhr bekommt außerdem:\n\n"},
[457] = {title = "Das Gleichgewicht der Natur", objective = "Konservator Ilthalaine verlangt von Euch, 7 räudige Nachtsäbler und 7 Disteleber zu töten.", description = "Die Jungbestände einiger Kreaturen hier im Shadowglen auszudünnen, war ein guter Anfang, <Name>, aber es gibt immer noch etwas zu tun.\n\nDie Ressourcen des Waldes werden sich zu schnell erschöpfen, wenn sich niemand um das Problem kümmert. Mutter Naturs Wildtiere zu töten, ist ein notwendiges Übel zum Besten von allen, die sich das Land teilen. Begebt Euch in den Wald und erschlagt im Namen des Gleichgewichts räudige Nachtsäbler und Disteleber.", progress = nil, completion = "Ihr habt Eure Hingabe an die Natur deutlich bewiesen, &lt;Name&gt;. Ein junger &lt;Klasse&gt; wie Ihr hat eine viel versprechende Zukunft vor sich.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDrapierter UmhangGeschwärzter Ledergürtel\n\nIhr bekommt außerdem:\n\n"},
[458] = {title = "Die Beschützerin des Waldlandes", objective = "Sucht die Dryade, die als Tarindrella bekannt ist.", description = "Was ein Glück, dass Ihr hier seid, <Klasse>. Vom Wispern der Waldgeister wurden mir seltsame Neuigkeiten zugetragen.\n\nDie geheimnisvolle Beschützerin des Waldlandes, Tarindrella, ist nach Shadowglen zurückgekehrt. Jahrelang war die Gegenwart der Dryade in den Wäldern Kalimdors nicht zu spüren. Sicherlich stimmt irgendetwas nicht, wenn sie jetzt wieder in diese Gegend zurückgekommen ist.\n\nSucht Tarindrella und findet heraus, was sie in unseren Hain führt. Eine der Schildwachen berichtete, sie südwestlich von Aldrassil gesehen zu haben.", progress = nil, completion = "Es sieht so aus, als hättet Ihr mich gefunden, junger &lt;Volk&gt;. Melithar ist ein weiser Druide, wenn er Euch geschickt hat.", rewards = "Ihr bekommt:\n\n"},
[459] = {title = "Die Beschützerin des Waldlandes", objective = "Sammelt 8 Stücke Teufelsmoos und bringt sie zu Tarindrella.", description = "Etwas Böses braut sich im Wald von Teldrassil zusammen. Schaut Euch die Hügel an, in denen die friedlichen Furbolgs früher hausten. Sie haben ihre Heime verlassen und sammeln sich unter dem Banner des Knarzklauenstamms.\n\nNur die Verderbtheit des bösartigen Teufelsmooses könnte eine solche Wandlung geschehen lassen. Die Grells und Grellkin suchen die Gegend heim und bedrohen die Einwohner von Shadowglen. \n\nSpürt diese Grells und Grellkins auf, <Name>, und überzeugt Euch, ob sie wirklich unter dem Einfluss des bösartigen Teufelsmooses stehen.", progress = "Bestätigt meinen Verdacht, <Name>. Bringt mir 8 Stücke Teufelsmoos.", completion = "Der Dienst, den Ihr den Lebewesen in Shadowglen erwiesen habt, ist eine Belohnung wert, &lt;Name&gt;.\n\nLeider habt Ihr aber dennoch meine Befürchtungen bestätigt. Wenn die Grells von dem Teufelsmoos besudelt wurden, dann ist kaum auszudenken, was aus den Furbolgs des Knarzklauenstamms geworden ist, die einst hier lebten.\n\nSolltet Ihr Euch jemals in Dolonaar wiederfinden, &lt;Klasse&gt;, sucht den klugen Druiden Athridas Bearmantle auf. Er teilt unsere Sorge um das Wohlergehen des Waldes.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBaldachin-GamaschenFährtenleserstiefelRanken-Handschuhe\n\nIhr bekommt außerdem:\n\nHeilkraut"},
[460] = {title = "In Stücken begraben", objective = "Bringt Alarics Kopf zu seinem Grab.", description = "Ihr seht nicht aus wie ein Moderfell. Gut. Ich hatte die Hoffnung schon aufgegeben...\n\nMein Name ist Alaric und ich war einst Thules oberster Diener und Leibwächter. Er nutzte seine Magie, um mich vor der Pest des Untodes zu \"schützen\", ein schöner Schutz... denn sein Zauber bürdete mir ein Unleben auf, dem ich nicht entrinnen kann. Und nachdem er diese verfluchten  der Moderfellgnolle erschaffen hatte, hat Thule mich geköpft... und meinen Kopf den Gnollen zum Spielen gegeben!\n\nBitte, bringt mich zu meinem Körper. Ich glaube, die Gnolle haben ihn hier in der Burg Fenris, nahe den Stallungen, in einem namenlosen Grab verscharrt.", progress = "Dieses Grab wurde in aller Eile gebuddelt.", completion = "Danke, &lt;Name&gt;. Ich hatte schon befürchtet, die Gnolle hätten meinen Körper zerstört. Gut zu wissen, dass dem nicht so ist.", rewards = "Ihr bekommt:\n\n"},
[461] = {title = "Die versteckte Nische", objective = "Bringt Alaric zur versteckten Nische.", description = "Ich kenne eine versteckte Nische in der Burg, die einen Gegenstand enthält, der für Thule und seine alten Kollegen sehr wichtig ist. Außerdem enthält sie noch etwas, das Ihr nützlich finden könntet. Bringt mich dorthin!\n\nDie Nische ist im Südwestturm der Burg, hinter einem staubigen Regal.\n\nNehmt meinen Körper mit, aber lasst die Stiefel hier. Die haben mir sowieso nie richtig gepasst.", progress = "Hier ist es! Bringt mich etwas näher heran...", completion = "Na bitte, sie ist offen. Lasst mich hier. Ich habe die besten Jahre meines Lebens in dieser Burg verbracht, und der Gedanke daran, in diesen Mauern zu ruhen, wirkt tröstlich.\n\nAchtet darauf, die Nische ordentlich zu schließen - ich möchte nicht von diesen Moderfellen gefunden werden.\n\nOh, und nehmt dies. Ihr habt es Euch verdient.", rewards = "Ihr bekommt:\n\n"},
[463] = {title = "Der Sumpfhüter", objective = "Findet den Sumpfhüter.", description = "Ihr habt vom Sumpfhüter gehört? Ihr sucht doch nicht etwa nach ihm, oder? Nun, ich behaupte ja, Ihr seid verrückt, wenn dem so ist, aber wer bin ich, dass ich <einen Narren/eine Närrin> davon abhalte, in den Tod zu gehen?\n\nFalls Ihr ihn sucht - hmmm, ich habe gehört, er sei in den Marschen, ostwärts von dort, wo die Straße nach Dun Modr abzweigt. Er lungert dort bei den Kroks und Schlimmerem herum!\n\nAch, und lasst Euer Geld besser hier. Ihr werdet es dort, wo Ihr hingeht, nicht brauchen... und Ihr wollt doch sicher nicht, dass der alte Grünling sich an Eurem Gold einen Zahn ausbricht, wenn er Euch mittendurch beißt.", progress = nil, completion = "Die Wurzeln und Farne sagen Gutes über Euch, Kleiner. Obwohl ich viele Namen habe, höre ich doch nur auf wenige. Aber Ihr mögt mich Rethiel nennen.\n\nUnd Ihr müsst mir lauschen... denn dieses Land leidet an eiternden Wunden, und ich betraue Euch damit, sie zu heilen.", rewards = "Ihr bekommt:\n\n"},
[464] = {title = "Kriegsflaggen", objective = "Bringt Captain Stoutfist 8 Kriegsflaggen der Dragonmaw.", description = "Der orcische Dragonmawklan war am Ende des zweiten Krieges so gut wie vernichtet, nachdem sie die Kontrolle über ihre Schoßtierchen, die roten Drachen, verloren hatten. Die Drachen waren nicht sehr freundlich zu ihren früheren Herren und machten gnadenlos Jagd auf die Dragonmaw. Die wenigen, die überlebten, flohen aus Grim Batol in die Berge östlich von Whelgars Ausgrabungsstätte.\n\nJetzt haben sie an Stärke gewonnen und besitzen ein Lager nordöstlich von Menethil.\n\nWir wollen, dass Ihr dieses Lager angreift. Sammelt und bringt mir ihre Kriegsflaggen als Beweis.", progress = "Habt Ihr das Lager der Dragonmaw angegriffen?", completion = "Gut gekämpft, &lt;Name&gt;. Die Dragonmaw sind keine solche Bedrohung mehr wie zu den Zeiten, als sie noch Drachen unter sich hatten, aber sie sind dennoch harte Gegner.\n\nDie Dragonmaw werden angeführt von Nek'rosh, Sohn von Nekros, der vor vielen Jahren der Anführer der Dragonmaw war. Nekros verwendete mächtige Magie, um die roten Drachen zu bändigen, aber als ihn diese Magie im Stich ließ ... waren die Drachen nicht glücklich.\n\nNekros wurde getötet, und sein Sohn hat Rache an den Drachen geschworen, die seinen Vater erschlugen.", rewards = "Ihr bekommt:\n\n"},
[465] = {title = "Nek'roshs Schachzug", objective = "Zerstört die Katapulte der Dragonmaw.", description = "Während Ihr die Dragonmaw bekämpft habt, haben wir mehr über deren Pläne herausgefunden.\n\nNek'rosh hat Katapulte gebaut und beabsichtigt, Menethil zu belagern! Und dank der Kämpfe in Dun Algaz sind wir effektiv von Verstärkungen abgeschnitten!\n\nIhr müsst diese Katapulte zerstören. Sie befinden sich im Lager der Dragonmaw.\n\nHier, nehmt diesen Zunder. Kämpft Euch zu den Katapulten durch und lasst sie mit dem Zunder in Flammen aufgehen.\n\nUnd nachdem Ihr das getan habt, findet und tötet Nek'rosh. Wir müssen dieser Dragonmawbestie den Kopf abschlagen.", progress = "Ihr seht das erste Katapult vor Euch. Wollt Ihr es entzünden?", completion = "Ihr legt etwas von dem Zunder auf das Katapult und schlagt dann einen Funken darauf.\n\nFlammen schlagen hervor und breiten sich schnell aus!", rewards = "Ihr bekommt:\n\n"},
[466] = {title = "Auf der Suche nach Pyrophor", objective = "Bringt 6 Ladungen Pyrophorerz zu Pilot Stonegear nach Dun Morogh.", description = "Ich habe gehört, im Sumpfland wurde in einer Höhle nordwestlich vom Algaz-Tor ein seltenes Erz namens Pyrophor gefunden. Pyrophor ist instabil und schwer anzuwenden, ohne sich dabei selbst in die Luft zu sprengen, aber ich bin mir sicher, wenn man es auf die richtige Art und Weise verhüttet, könnte man daraus Kanonenkugeln mit einer ziemlichen Durchschlagskraft herstellen.\n\nBesorgt mir Pyrophorerz und ich finde jemanden, der mutig genug ist, damit zu experimentieren.\n\nOh, und um dieses Erz aus einer Ader zu schürfen, müsst Ihr Euch mit Bergbau auskennen. Wenn dem nicht so ist, dann... nehmt einen Freund mit in diese Höhle, der es tut!", progress = "Wo ist denn das Erz, <Name>?!", completion = "Ihr habt das Erz! Gut gemacht, &lt;Name&gt;! Ich werde sofort jemanden damit arbeiten lassen. Wollen wir hoffen, dass er sich dabei nicht in die Luft sprengt!", rewards = "Ihr bekommt:\n\nBierbefleckte Handschuhe"},
[467] = {title = "Stonegears Suche", objective = "Sprecht mit Pilot Stonegear.", description = "Pilot Stonegear liebt seine Belagerungsmaschine, wie jeder Pilot es auch sollte! Und er ist immer begierig, neue Wege zu finden, die Feuerkraft seines Panzers zu vergrößern!\n\nEr hat Gerüchte über ein seltenes Erz gehört und sucht jetzt nach jemandem, der es für ihn auftreibt. Wenn es Euch also in den Fingern juckt, dann sucht Stonegear in Steelgrills Depot in Dun Morogh auf und schaut mal, was er will.", progress = nil, completion = "Hallo &lt;Name&gt;. Ihr seid hier wegen des Auftrags, den ich habe, hm? Es tut gut zu sehen, dass Ihr ein junger &lt;Volk&gt; seid, dessen Blut bei der Aussicht auf Abenteuer in Wallung gerät.", rewards = "Ihr bekommt:\n\n"},
[468] = {title = "Meldung bei Gebirgsjäger Rockgar", objective = "Sprecht mit Gebirgsjäger Rockgar.", description = "Gebirgsjäger Rockgar sucht nach Freiwilligen für eine Mission durch Dun Algaz und in das Sumpfland hinein. \n\nWenn Ihr also Lust habt, Euch Eure Stiefel in dieser sumpfigen Gegend im Norden schmutzig zu machen, dann sprecht mit Rockgar in Dun Algaz. Dun Algaz liegt weiter die Straße entlang im Norden, hinter dem Wachturm.", progress = nil, completion = "Hallo, &lt;Klasse&gt;! Ihr seid wegen der Spähmission hier, stimmt's? Sehr gut!\n\nIch hoffe, Eure Ausrüstung ist in gutem Zustand, denn aus dieser \"Späh\"-Mission ist ein... größerer Schlamassel geworden.", rewards = "Ihr bekommt:\n\n"},
[469] = {title = "Tägliche Lieferung", objective = "Liefert das Bündel Krokiliskenhäute bei dem Gerber James Halloran im Hafen von Menethil ab.", description = "Seid gegrüßt!\n\nIhr seid nicht zufällig in Richtung Menethil unterwegs? Falls nicht, würde ich Euch empfehlen, dort Halt zu machen, denn es ist ein guter Ort, um Waren zu kaufen oder etwas trinken zu gehen und sich auszuruhen.\n\nTja, wenn Ihr also zufälligerweise in diese Richtung unterwegs seid, dann habt Ihr doch sicher nichts dagegen, dieses Bündel Krokiliskenhäute zu James Halloran, dem Gerber, zu bringen?\n\nIch würde es ja selbst tun, aber meine Frau ist in letzter Zeit ziemlich launisch, und ich würde es gern so lange wie möglich aufschieben, ihr zu begegnen.", progress = "Guten Tag auch, <Klasse>. Kann ich Euch für ein Paar Stiefel interessieren? Vielleicht einige frisch gegerbte Häute?", completion = "Hmm, das ist von Einar, oder? Er hat mir schon seit bald einer Woche seine Häute nicht mehr persönlich geliefert. Er hat sicher wieder Ärger mit seiner Frau!\n\nVielleicht lasse ich meine Frau mal mit Sida sprechen...", rewards = "Ihr bekommt:\n\n"},
[470] = {title = "Stochern im Brühschlamm", objective = "Einer der Brühschlammer bei Ironbeards Grabmal hat Sidas Tasche. Bergt sie und bringt sie ihr zurück in den Hafen von Menethil.", description = "Bei meinem wöchentlichen Besuch an Ironbeards Grabmal wurde ich von grässlichen, triefenden Brühschlammern angegriffen! Natürlich geriet ich in Panik.\n\nIch habe meine Tasche nach einem geworfen, aber das zeigte keinerlei Wirkung! Der Brühschlammer saugte sie einfach auf... Glücklicherweise gab mir das genug Zeit wegzulaufen.\n\nDie schlechte Nachricht ist, dass ich dringend den Inhalt meiner Tasche benötige!\n\nIch weiß nicht, nach welchem Brühschlammer ich meine Tasche geworfen habe; sie sehen alle gleich aus! Ironbeards Grabmal liegt nordöstlich von hier, in der Nähe von Dun Modr. Ich danke Euch wirklich sehr!", progress = "Habt Ihr meine Tasche gefunden?", completion = "Oh, danke sehr, &lt;Name&gt;! Ich hatte schon befürchtet, sie wäre für immer verloren!\n\n\n\nHm, ich kann damit nicht mehr viel anfangen, aber wenn Ihr sie sauber macht, könnt Ihr sie bestimmt noch gebrauchen.", rewards = "Ihr bekommt:\n\nBrühschlammbedeckte Tasche"},
[471] = {title = "Lehrlingspflichten", objective = "Sammelt 6 riesige Krokiliskenhäute und bringt sie zu James Halloran in den Hafen von Menethil.", description = "Ich habe meinen Lehrling in die Marschen geschickt, um einige unserer berühmten riesigen Sumpflandkrokilisken zu häuten. Als er nicht zurückkam, bin ich losgezogen, um ihn zu suchen... Sagen wir einfach, es war kein schöner Anblick.\n\nDie Schwester sagt, er könnte durchkommen, aber derweil brauche ich immer noch meine Häute!\n\nUnd wenn Ihr noch ein paar von den Monstern töten wollt, hätte ich nichts dagegen, nach allem, was sie getan haben. Ihr findet die Kroks, wenn Ihr die Küste entlang nach Norden geht, hinter den Hütten der Murlocs.", progress = "Mein Lehrling ist wie ein Sohn für mich. Wird hart für ihn sein, sein Leben mit nur einem Bein zu fristen.\n\nAh, <Name>, wie läuft's? Habt Ihr meine Häute?", completion = "Hmm... Ihr habt nicht zufällig Lust, bei mir in die Lehre zu gehen?\n\nHa! Nein, war nur ein Witz. Ihr seid sowieso viel zu alt. Außerdem - nach Eurem Aussehen zu urteilen, habt Ihr wahrscheinlich andere Ambitionen im Leben. Dennoch habt Ihr da ein paar feine Häute besorgt und ich werde damit etwas anfangen können.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFormbare KettengamaschenWiderstandsfähiger Poncho\n\nIhr bekommt außerdem:\n\nRezept: Krokiliskengumbo"},
[472] = {title = "Der Fall von Dun Modr", objective = "Sucht nahe der Stadt von Dun Modr nach Longbraid.", description = "Dun Modr ist an die Dunkeleisenzwerge gefallen!\n\nMeine Wunden sind schwer, <Klasse>. Ein Großteil meines Regiments wurde getötet! Diese Rohlinge der Dunkeleisenzwerge haben uns angegriffen, bevor wir uns nach dem Überfall auf den Thandol-Übergang wieder sammeln konnten.\n\nUnser Anführer, Longbraid, blies zum Rückzug. Als wir die Stadt verließen, wurde ich von einer verirrten Axt in den Rücken getroffen und alles wurde schwarz um mich.\n\nIch wachte hier in Menethil auf, aber ich fürchte um meine Kameraden. Ich hege allerdings noch Hoffnung. Vielleicht ist Longbraid noch am Leben! Seht nach, ob Ihr ihn in der Nähe von Dun Modr finden könnt, <Volk>!", progress = nil, completion = "Welcher mutige &lt;Klasse&gt; bringt Kunde aus Menethil? Ah, &lt;Name&gt; werdet Ihr genannt.\n\nIhr bringt Hoffnung in eine hoffnungslose Situation. Gut zu wissen, dass der junge Harlo überlebt hat. Auf der Flucht wurde ihm eine ernste Wunde zugefügt. Wir hatten kaum die Zeit, ihn auf dem Rücken des letzten überlebenden Reittiers unseres Regiments fortzuschicken.\n\nAber wir sind hier in einer gefährlichen Lage. Dun Modr ist gefallen, und wir sind nur ein Schatten des großen Regiments, das wir einmal waren.", rewards = "Ihr bekommt:\n\n"},
[473] = {title = "Meldung bei Captain Stoutfist", objective = "Sprecht mit Captain Stoutfist.", description = "<Name>. Der Dragonmawklan der Orcs zeigt nicht nur in Algaz Stärke. Captain Stoutfist wünscht mit denen zu sprechen, die Hilfe gegen diese Orcs anbieten wollen. Er ist in der Burg, im Kriegsraum.", progress = nil, completion = "&lt;Name&gt;. Valstag klärte mich über Eure bisherigen Erfolge mit den Orcs des Dragonmawklans in Dun Algaz auf. Ihr seid ein &lt;Volk&gt; von Wert.\n\nUnd ich habe eine Aufgabe für Euch.", rewards = "Ihr bekommt:\n\n"},
[474] = {title = "Sieg über Nek'rosh", objective = "Tötet Häuptling Nek'rosh.\n\nBringt Nek'roshs Kopf zu Captain Stoutfist.", description = "Jetzt, nachdem die Katapulte abgebrannt wurden, sucht und tötet Häuptling Nek'rosh.", progress = "Habt Ihr Nek'rosh getötet?", completion = "Saubere Arbeit, &lt;Name&gt;. Ihr habt den Orcs vom Dragonmawklan einen deutlichen Schlag verpasst. Vielleicht erholen sie sich nie wieder davon. Außerdem hat die Zerstörung dieser Katapulte den Hafen von Menethil gesichert.\n\nIhr seid ein vorzüglicher &lt;Volk&gt;, und das Königreich von Ironforge belohnt die, die ihm gut dienen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAltes KriegsschwertWalzenschnitter\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[475] = {title = "Ein beunruhigender Wind", objective = "Sucht Gaerolas Talvethren im Dorf Starbreeze auf.", description = "Ein beunruhigender Wind weht durch den Wald.\n\nGaerolas Talvethren dient den schlafenden Druiden der Kralle in den Grabhügeln von Ban'ethil als Großer Aufseher. Seine Pflicht als auserwählter Beschützer der Schlafenden ist es, deren Sicherheit zu gewährleisten, auf dass sie ihrem Pakt mit Ysera gerecht werden.\n\nAber es gab länger keine Nachricht von Gaerolas, und ich werde etwas nervös. Reist nach Osten, zum Dorf Starbreeze, und bringt mir einen Bericht von Gaerolas, auf dass ich meine Sorgen begraben kann, da ich weiß, dass meine träumenden Brüder sicher schlummern.", progress = nil, completion = "Dank sei den Waldgeistern, dass Ihr hier seid! Ich wusste, Athridas würde die Probleme spüren und Hilfe schicken.", rewards = "Ihr bekommt:\n\n"},
[476] = {title = "Die Verderbnis der Knarzklauen", objective = "Kehrt zu Athridas Bearmantle nach Dolanaar zurück.", description = "Der Knarzklauenstamm ist verderbt worden!\n\nDie einstmals friedliebenden Furbolgs haben sich gegen die Beschützer des Waldes gewandt. Sie haben mich hinterrücks überfallen, als ich auf dem Weg zum Grabhügel von Ban'ethil war und liefen weiter, um Starbreeze zu plündern. Ursal der Raufer, ihr Häuptling, benutzt die bösen Mächte des Teufelsmooses, um sie wahnsinnig werden zu lassen.\n\nMeine Wunden sind zu schwer, ich kann nicht zu Athridas zurückkehren und ihm diese schlimme Nachricht überbringen. Junger <Klasse>, diese Aufgabe bleibt Euch überlassen. Wir können nur hoffen, dass die verrückten Knarzklauen noch nicht bis nach Ban'ethil vorgedrungen sind!", progress = nil, completion = "Bei den Sternen! Dies ist wirklich sehr furchterregend!", rewards = "Ihr bekommt:\n\n"},
[477] = {title = "Grenzübergänge", objective = "Holt den Inhalt einer der Kisten von den Hexern aus Dalaran. Ihr findet Pyrewood im Süden.", description = "Wie Ihr vielleicht bereits wisst, die Stadt Ambermill ist weiterhin eine Quelle der menschlichen Opposition, die nötige Unterstützung erhalten sie meist durch die Hexer von Dalaran.\n\nIch weiß nicht, wie ihr Plan aussieht, aber ihr Interesse an einem Hinterwäldler-Dorf wie Ambermill zeigt mir, dass es von größerer Bedeutung sein muss.\n\nVon Hillsbrad aus haben sie wagenweise Kisten geliefert. Viele dieser Vorräte werden in ein kleines Camp nördlich von Pyrewood gebracht. Bringt mir den Inhalt einer dieser Kisten.", progress = nil, completion = "&lt;Als Ihr den Kistendeckel aufstemmt, findet Ihr eine Anzahl sorgfältig verpackter Objekte. Oben auf der Kiste liegt ein Bündel vergilbter Landkarten, auf denen anscheinend der Silberwald und andere Teile von West-Lordaeron abgebildet sind.\n\nUnter den Landkarten liegt ein geheimnisvoll aussehender magischer Anhänger.&gt;", rewards = "Ihr bekommt:\n\n"},
[478] = {title = "Karten und Runen", objective = "Bringt den seltsamen Anhänger zu Schattenpriester Allister in dem Grabmal.", description = "<Schnell entnehmt Ihr den Anhänger aus der Kiste und setzt den Deckel wieder auf.>", progress = "Habt Ihr etwas Nützliches erfahren, <Name>?", completion = "Karten und diesen... Anhänger, hm? Interessant.\n\nEs ist offensichtlich, dass die Hexer von Dalaran sich aus einem bestimmten Grund für Ambermill interessieren, aber ihr Ziel ist mir bislang noch verborgen.\n\nVielleicht weiß Dalar etwas über ihren Zweck.", rewards = "Ihr bekommt:\n\n"},
[479] = {title = "Ambermill-Nachforschungen", objective = "Beschafft 8 Anhänger aus Dalaran für Schattenpriester Allister beim Grabmal.", description = "Dalar versucht die Quelle für die Zaubereien der Hexer zu finden. In der Zwischenzeit müssen wir ihren Fortschritt mit allen Mitteln aufhalten...\n\nAlle Herbeizauberer, Magier und Beschützer tragen mit Sicherheit ihre Anhänger. Nehmt sie ihnen ab und bringt sie hierher.\n\nFolgt der Hauptstraße in südlicher Richtung und nehmt dann die östliche Abzweigung nach Ambermill.", progress = "Wir müssen uns eilen, ihr Plan darf keinerlei Früchte tragen, oder wir können unsere Herrschaft über den Silberwald verlieren.", completion = "Dalar hat herausgefunden, dass trotz des Rückschlags das Wirken schon weit fortgeschritten ist.\n\nEin sehr mächtiger Hexer leitet die magische Energie. Er muss schnellstmöglich aufgehalten werden.", rewards = "Ihr bekommt:\n\n"},
[480] = {title = "Der Wirker", objective = "Tötet den Erzmagier von Dalaran und bringt seinen Stab zu Schattenpriester Allister in dem Grabmal.", description = "Ein Erzmagier von großer Macht leitet die Reaktivierung des Leyenergieknotens. Angesichts ihres Fortschritts liegt unsere einzige Hoffnung, sie noch aufzuhalten, darin, ihn zu töten. Das ist eine schwierige Tat, denn ohne Zweifel wird er von anderen Magiern und Wärtern beschützt.\n\nIhr müsst ihn schnellstens erledigen. Bringt mir seinen Stab, sobald er tot ist. Geht jetzt.", progress = "Schnell, die Zeit ist knapp, <Name>!", completion = "Die Magie der Hexer löst sich auf und die Leyenergien kehren in ihren Ruhezustand zurück. &lt;Name&gt;, Eure Bemühungen waren erfolgreich. Wir haben unseren Feinden einen mächtigen Schlag versetzt, wie auch den übermächtigen Hexern von Dalaran.\n\nDennoch müssen wir weiterhin wachsam sein, da wir wissen, dass die Quelle der Energie so nahe liegt... Für die Zukunft müssen Pläne gemacht werden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nCeraniumruteTarntunika\n\nIhr bekommt außerdem:\n\n"},
[481] = {title = "Dalars Analyse", objective = "Bringt den mit Runen gravierten Anhänger zu Dalar Dawnweaver in dem Grabmal.", description = "Bringt den Anhänger zu Dalar Dawnweaver, vielleicht kann er Licht in das Dunkel der Hexerpläne bringen.", progress = "Ja, <Klasse>? Was ist?", completion = "Interessant, weitere Machenschaften der Kirin Tor, wie es scheint. Dies ist ein mächtiges Artefakt. Es wurde häufig von mächtigen Hexern der Kirin Tor benutzt, um magische Energien zu kanalisieren.\n\nDie Anzahl, die sie davon nach Ambermill bringen, sagt mir, dass sie ein Projekt großen Ausmaßes durchführen wollen.\n\nIch werde versuchen, ihre Schilde zu durchdringen und ihre Absicht zu ermitteln.", rewards = "Ihr bekommt:\n\n"},
[482] = {title = "Dalaran Absichten", objective = "Sprecht mit dem Schattenpriester Allister in dem Grabmal.", description = "Natürlich! Wie konnte ich das vergessen?\n\nAmbermill war einer der Orte, die von den Kirin Tor gekennzeichnet wurden, weil dort ein ruhender Leyenergieknoten liegt. Mit Sicherheit haben die Hexer vor, diesen Knoten wiederzuerwecken und seine Energien für etwas Größeres zu nutzen.\n\nDas dürfen wir nicht zulassen...\n\nUm die Leyenergien des Gebietes zu aktivieren, bedarf es einer großen Macht. Wir können sie aufhalten, indem wir die Anhänger der Hexer an uns nehmen.\n\nBringt diese Information zu Allister, er wird dann über das weitere Vorgehen entscheiden.", progress = nil, completion = "Ihr bringt schlechte Neuigkeiten, &lt;Name&gt;. Sollte Dalar recht behalten - und ich habe keinerlei Grund, dies zu bezweifeln - müssen wir schnell handeln.\n\nIch muss unseren Angriffsplan mit ihm beraten. In der Zwischenzeit müssen wir ihr Weiterkommen aufhalten.", rewards = "Ihr bekommt:\n\n"},
[483] = {title = "Die Relikte des Erwachens", objective = "Bringt die Relikte des Erwachens zu Athridas Bearmantle nach Dolanaar.", description = "Eindringlinge der Knarzklauen wurden beim Überfall im Westen des Ban'ethil-Grabhügels gesehen.\n\nWenn wir ihnen nicht zur Hilfe kommen, werden die schlummernden Druiden auf ewig im Smaragdgrünen Traum gefangen gehalten, vollkommen ahnungslos ihrem Schicksal ausgeliefert. Das empfindliche Ritual des Großen Schlafes kann ohne die Relikte des Erwachens nicht unterbrochen werden.\n\nReist zum Höhlenbau und bringt den Rabenkrallentalisman, den schwarzen Federkiel, den Saphir des Himmels sowie die Rune des Nistens herbei. Die Druiden bewahren sie in heiligen Truhen auf. Bringt sie zu mir, damit ich das Weck-Ritual vorbereiten kann.", progress = "<Name>, die entführten Druiden der Kralle werden auf ewig im Smaragdgrünen Traum gefangen gehalten, wenn wir die Relikte des Erwachens nicht aus dem Grabhügel von Ban'ethil im Westen herbringen können.\n\nJede Minute, die wir zögern, bringt ihr Schicksal einen Schritt näher an die ewige Verdammnis.", completion = "Ihr hattet Erfolg, junger &lt;Klasse&gt;! Gut gemacht. Und gerade rechtzeitig, wie ich hinzufügen möchte.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRindenpanzergamaschenSchneidwurzelstab\n\nIhr bekommt außerdem:\n\n"},
[484] = {title = "Häute junger Krokilisken", objective = "Besorgt Euch 4 Häute junger Krokilisken für James Halloran im Hafen von Menethil.", description = "Ich bin James Halloran, der Gerber. Meine gegerbten Krokiliskenhäute sind nah und fern begehrt, Lieferungen gehen per Schiff zu allen Häfen der Welt.\n\nHabt Ihr Einar getroffen? Er ist einer der Jäger, die mir Krokiliskenhäute bringen.\n\nMir fehlen zurzeit weichere Häute, wie die von jungen Krokilisken.\n\nDa ich bald keine mehr habe, bin ich bereit, Euch einen Spitzenpreis für einen Stapel der Häute zu bezahlen. Ihr könnt die jungen Kroks in den Marschen gleich außerhalb der Stadt finden.", progress = "<Name>, nicht wahr? Habt Ihr meine Häute?", completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Die Qualität dieser Häute ist superb. Ich muss so bald wie möglich mit dem Gerben dieser Häute beginnen. Oh, bevor ich jedoch damit anfangen kann, habe ich noch eine andere Aufgabe zu erledigen. Ich denke, dass Ihr sie übernehmen könnt.", rewards = "Ihr bekommt:\n\n"},
[485] = {title = "Sucht OOX-09/HL!", objective = "Bringt das Notsignal zu Oglethorpes Leitroboter an der Quelle des Flusses im Hinterland, nahe Skulk Rock.", description = "Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zu Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.\n\n\"Mein Name ist Oglethorpe Obnoticus und mein Leitroboter ist abgestürzt! Ich werde Euch belohnen, wenn Ihr ihn aufspürt. Bringt dem Roboter bitte diesen Signalgeber!\"\n\n\"Ich habe jetzt die Koordinaten des Roboters für Euch berechnet. Er ist in der Nähe von Skulk Rock abgestürzt, dort, wo der Fluss entspringt!\"", progress = "Ihr habt anscheinend das Wrack eines... Robothuhns entdeckt... Aus dem Ei erklingt wieder die rasselnde Stimme:\n\n\"Ja, hervorragende Arbeit! Das ist tatsächlich mein Leitroboter, aber meine Sensoren zeigen an, dass er Starthilfe benötigt, bevor er zur Reparatur nach Booty Bay zurückfliegen kann. Bitte legt den Signalgeber in den Rover. Der Signalgeber wird den Rest übernehmen!\"", completion = "Ihr legt das Ei... das Notsignal... in das Huhn... den Leitroboter.\n\nAus dem Roboter ertönt ein Brummen und Surren, als er versucht aufzustehen. Nachdem der Roboter zum Leben erwacht ist, ertönt die Stimme von Oglethorpe ein weiteres Mal, diesmal aus dem Inneren des Roboters:\n\n\"OOX-09/HL funktioniert endlich, aber es sind umfangreiche Reparaturen erforderlich! Er ist zu schwer, als dass Ihr ihn tragen könntet... aber ich glaube, ich habe eine Idee. Könntet Ihr noch etwas auf ihn aufpassen?\"", rewards = "Ihr bekommt:\n\n"},
[486] = {title = "Ursal der Raufer", objective = "Tötet Ursal den Raufer und kehrt zu Athridas Bearmantle nach Dolanaar zurück.", description = "Jetzt ist die Zeit gekommen, die Druiden der Kralle zu retten. <Name>, sollten wir jetzt versagen, sind sie für immer im Schlaf verloren.\n\nIch werde die Relikte des Erwachens vorbereiten und das Ritual durchführen. Damit meine Arbeit Wirkung zeigen kann, muss die verfluchte Bestie, die für diese schreckliche Situation verantwortlich ist, getötet werden. Erst dann ist das Ritual vollkommen.\n\nEs war Ursal der Raufer, der sich in die Berufung unserer Brüder eingemischt hat, und er ist es auch, der nun bezahlen muss, damit sie befreit werden können. Begebt Euch nach Südwesten zur Höhle der Knarzklauen und erschlagt ihn.", progress = nil, completion = "&lt;Name&gt;, Ihr habt Euch als ein zutiefst würdiger und geschickter &lt;Klasse&gt; erwiesen. Ein &lt;Volk&gt;, welcher dem Pfad der Ehre so sicher folgt wie Ihr, findet mit Sicherheit großen Ruhm in dieser Welt.\n\nMögen die Waldgeister Euch auf all Euren Wegen beschützen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerteidigeraxtDornwurzkeule\n\nIhr bekommt außerdem:\n\n"},
[487] = {title = "Die Straße nach Darnassus", objective = "Erschlagt 6 Wegelagerer der Knarzklauen und kehrt zu Schildwache Amara Nightwalker außerhalb Dolanaars zurück.", description = "Die Straße nach Darnassus muss sicher bleiben. Reisende, die von Dolanaar nach Darnassus fuhren, haben von ruchlosen Angriffen der verderbten Furbolgs des Knarzklauenstammes berichtet.\n\nJeden Tag gelangen auf diesem Weg wichtige Nachrichten und auch Waren von und nach Darnassus. Es darf einfach nicht sein, dass eine schurkische Bande von Heiden alle terrorisiert.\n\n<Klasse>, bewaffnet Euch im Namen des Heiligen Waldes. Ihr Bau liegt irgendwo unterhalb dieser Position. Erschlagt 6 Wegelagerer der Knarzklauen und berichtet mir dann.", progress = "Die Straße ist noch immer nicht sicher, <Klasse>. Kehrt um und erschlagt 6 Wegelagerer der Knarzklauen und kommt zu mir zurück.", completion = "Ihr habt den guten Leuten von Dolanaar und Darnassus gute Dienste geleistet, tapferer &lt;Klasse&gt;. Als Mitglied der Schildwache von Teldrassil beglückwünsche ich Euch zu Euren Bemühungen.", rewards = "Ihr bekommt:\n\n"},
[488] = {title = "Zenns Aufträge", objective = "Bringt Zenn Foulhoof außerhalb von Dolanaar 3 Nachtsäblerfangzähne, 3 Strigideulenfedern und 3 Streifen Waldweberspinnenseide.", description = "Ihr seid bereit zu arbeiten, wie ich sehe. Ihr habt Glück, denn es vergeht kein Tag, an dem ich mir nicht wünschte, ein junger <Klasse> wäre hier, der mir zur Hand geht.\n\nIhr seht, <Name> , ich kann Euch zu Eurem Glück verhelfen und mit Dingen versorgen, von denen Ihr nie zu träumen wagtet. Damit dies jedoch geschieht, müsst Ihr mir gewisse Dinge beschaffen.\n\nMeine Angelegenheiten im Wald erfordern oft gewisse... Reagenzien. Bringt mir 3 Nachtsäbler-Fangzähne, 3 Strigideulenfedern und 3 Streifen Waldweberspinnenseide.\n\nDas soll unser kleines Geheimnis bleiben, <Volk>.", progress = "Ihr wart also ein fleißiges Bienchen, <Name>? Ich habe darauf gewartet, dass Ihr mir das bringt, was ich benötige.", completion = "Ha ha! Wirklich hervorragend.\n\nWer hätte jemals gedacht, dass ein &lt;Volk&gt; mir, Zenn Foulhoof, meine Wünsche erfüllen würde? Selbst ich hätte es nicht geglaubt. Aber so geht es nun mal... unsere so geliebte Welt ist doch voller Überraschungen.\n\nEin Hoch auf die Naiven und Gutgläubigen!", rewards = "Ihr bekommt:\n\nAbgespaltene Voodooklaue"},
[489] = {title = "Sucht Befreiung!", objective = "Sammelt 3 Teufelszapfen und gebt sie Zenn Foulhoof außerhalb von Dolanaar.", description = "Der Rat des Waldes hat die Meldung erhalten, dass Ihr Zenn Foulhoof behilflich gewesen seid. Der Satyr ist ein Feind des Waldes. Als <Volk> müsstet Ihr eigentlich mehr Verstand haben, als den Wald zu entweihen, indem Ihr Kreaturen der Natur tötet.\n\nIhr müsst Eure Ehre in den Augen des Rates wiederherstellen, wenn Ihr weiterhin ein Freund von Teldrassil bleiben wollt.\n\nErteilt Foulhoof eine Lektion, dann habt ihr Eure Schuld beglichen. Teufelszapfen sind verderbte Samen, die von Bäumen fallen. Sie sondern grünen Rauch ab.\n\nGebt Foulhoof einige davon. Er wird denken, dass Ihr ihm eine harmlose Leckerei gebracht habt.", progress = "Was habt Ihr für mich, <Name>? Eine leckere kleine Zwischenmahlzeit, nehme ich an?", completion = "Wie nett von einem &lt;Volk&gt;! Ich wusste, dass Ihr nützlich sein würdet!", rewards = "Ihr bekommt:\n\n"},
[491] = {title = "Zauberstab an Bethor", objective = "Bringt den gewebten Zauberstab zu Bethor Iceshard in das Magieviertel von Undercity.", description = "Thule erzählte mir einmal, dass er und zwei Kollegen vor langer Zeit einen magischen Zauberstab herstellten, der aus den Lehrlingszauberstäben zusammengewoben wurde, den jeder Magier besaß. Dieser Zauberstab war ein Symbol ihrer Freundschaft, und obwohl Thule ihn hinterher verachtete, konnte er sich doch weder davon trennen noch ihn den anderen überlassen. Also stahl er den Zauberstab und versteckte ihn in Burg Fenris.\n\nHier. Bringt den Zauberstab zu Bethor Iceshard, einem Freund von Thule aus vergangenen Zeiten. Ich bin sicher, er möchte ihn haben.", progress = "<Name>. Habt Ihr Thule Rabenklaue besiegt?", completion = "... was ist das? Thule hatte unseren gewebten Zauberstab? Ich dachte, er sei verloren, als unsere Freundschaft zerbrach und er sich auf die Seite des Lichkönigs stellte!\n\nEr kann seine Macht nie verwendet haben, denn das hätte ich gespürt. Und es ist gut, dass er ihn nicht benutzt hat...\n\nDies ist ein wunderbarer Fund. &lt;Name&gt;, Ihr habt meinen Dank und sollt belohnt werden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBedruckte BeinkleiderUnverwüstliche PanzerhandschuheSägemesser\n\nIhr bekommt außerdem:\n\n"},
[492] = {title = "Eine neue Seuche", objective = "Bringt Johaans Spezialgetränk zum gefangenen Gebirgsjäger.", description = "Berichten der Todeswachen zufolge wurde gerade ein weiterer dieser dummen Zwergen-Gebirgsjäger gefangen genommen. Die Todeswächter benutzen gern den Keller der Taverne Zur Galgenschlinge als Übergangszelle, bis man sich \"richtig\" um die Gefangenen kümmern kann.\n\nWarum... kümmert... Ihr Euch nicht um den gefangenen Gebirgsjäger und schaut, wie er das Spezialgetränk verträgt, das ich für ihn gemacht habe? Das ist nur ein kleiner Eindruck dessen, was die dunkle Fürstin für den Rest von Azeroth geplant hat.", progress = "Hätte ich nur mein getreues Gewehr bei mir, wärt Ihr so gut wie tot, <Klasse>. Wartet nur, bis die Dampfpanzerbrigade eintrifft, um mich zu retten!", completion = "Ah, endlich, etwas zu trinken. Das ist zwar sicherlich kein Rhapsody-Malz, aber zum jetzigen Zeitpunkt ist mir alles recht, um meine Kehle anzufeuchten.", rewards = "Ihr bekommt:\n\n"},
[493] = {title = "Reise in das Vorgebirge von Hillsbrad", objective = "Bringt die Funde von Apotheker Renferrel zu Apotheker Lydon nach Tarrens Mühle im Vorgebirge von Hillsbrad.", description = "Die Königliche Apothekervereinigung steht unter enormem Druck seitens der dunklen Fürstin, eine neue Seuche zu entwickeln. Wir arbeiten sehr hart und haben bereits einige Fortschritte gemacht. Wir denken, dass der Erfolg sich umso schneller einstellen wird, wenn wir innerhalb der Vereinigung Informationen austauschen.\n\nAus diesem Grunde möchte ich, dass Ihr meine letzten Funde an Apotheker Lydon in Tarrens Mühle überbringt, einem kleinen Städtchen, das sich im Vorgebirge von Hillsbrad befindet. Die Reise wird sehr lange dauern.\n\nBegebt Euch Richtung Süden und bleibt auf den Straßen. Beachtet die Schilder auf das Genaueste!", progress = "Habt Ihr etwas für mich?", completion = "Ah, wie wunderbar. Ich habe den größten Respekt vor Apotheker Renferrel. Ich brenne darauf, seine Arbeiten zu studieren.", rewards = "Ihr bekommt:\n\n"},
[494] = {title = "Zeit zum Zuschlagen", objective = "Reist nach Tarrens Mühle, um die Nachricht von Todespirscherin Lesh an Hochexekutorin Darthalia zu überbringen.", description = "Schweigt und passt auf, <Klasse>.\n\nIch wurde an diesen Ort geschickt, um die Stadt Hillsbrad zu sondieren. Es handelt sich um eine Aufklärungsmission. Dabei ist von äußerster Wichtigkeit, dass Ihr sofort die Hochexekutorin Darthalia in Tarrens Mühle benachrichtigt. Bestellt ihr, ich, Todespirscherin Lesh, lasse ihr folgende Nachricht ausrichten:\n\n\"Der Schrei des Raben locket vom Westen her.\"\n\nFolgt der Straße gen Osten und beachtet die Schilder genau. Nun aber schnell! Macht Euch auf den Weg nach Tarrens Mühle. Es ist Eile geboten!", progress = nil, completion = "Der Schrei des Raben locket vom Westen her?\n\nWas für superbe Neuigkeiten! Hillsbrad ist reif für den Angriff. Jetzt können wir unseren Zerstörungsplan durchführen. Das wird Varimathras erfreuen.", rewards = "Ihr bekommt:\n\n"},
[495] = {title = "Die Krone des Willens", objective = "Meldet Euch bei Melisara in Tarrens Mühle im Vorgebirge von Hillsbrad.", description = "Mug'Thol und seine Ogerkriegsmeute wurde nach Alterac geschickt, um die Krone des Willens für Lady Sylvanas zu holen. Anstatt sie zurückzubringen, hat der Idiot allerdings versucht, sie aufzusetzen... Oger können wohl einfach keinen Dingen widerstehen, die glitzern und schimmern, nehme ich an.\n\nSeine stümperhaften Aktionen sind allerdings zu einem Problem geworden. Die Krone des Willens hat ihm geholfen, der Besessenheit zu widerstehen, die ihm auferlegt wurde, damit er Lady Sylvanas dient.\n\nDie dunkle Fürstin möchte ein Exempel statuieren. Begebt Euch nach Tarrens Mühle in Hillsbrad und meldet Euch bei Melisara, meinem dortigen Offizier.", progress = nil, completion = "Ihr wurdet von Shalindra geschickt? Nun gut, Ihr werdet sehen, dass ich nicht viel Zeit mit Geplauder verplempere.\n\nMug'Thol ist ein Ärgernis und wir werden uns um ihn kümmern, schnell, gründlich und ohne Zwischenfälle.", rewards = "Ihr bekommt:\n\n"},
[496] = {title = "Elixier des Leidens", objective = "Apotheker Lydon aus Tarrens Mühle möchte 10 Graubärzungen und etwas Krabblersekret.", description = "Ah, und wieder ein ekelhafter Tag in Tarrens Mühle. Diese ganze gesunde Luft verdirbt mir gründlich die Laune, <Name>.\n\nJe schneller wir die Menschen hier erkranken lassen können, desto besser. Ich habe intensive Studien über mögliche tödliche Zutaten für meine Gebräue durchgeführt, aber ich habe nicht die Zeit, sie alle zu sammeln.\n\nWenn Ihr Euch nützlich machen wollt, dann besorgt mir Folgendes: 10 Graubärzungen sowie das sehr seltene und schwer zu findende Krabblersekret. Bären und Krabbler könnt Ihr gleich außerhalb von Tarrens Mühle finden.", progress = "Wie ich sehe, seid Ihr zurück. Ich hoffe, Ihr konntet mir die Zutaten beschaffen, die ich benötige. Diese Todesfreien Tage machen mich immer so trübsinnig.", completion = "Diese Exemplare sind perfekt. Nun, &lt;Name&gt;, Ihr habt es vollbracht, mir eine winzigkleine Freude an einem weiteren dieser elendiglichen Tage zu machen. Ich weiß Eure Bemühungen zu schätzen.", rewards = "Ihr bekommt:\n\n"},
[498] = {title = "Die Rettung", objective = "Krusk in Tarrens Mühle braucht Euch, um Drull und Tog'thar aus der Burg Durnholde zu befreien.", description = "Ich und einige andere Krieger wurden vom Kriegshäuptling geschickt, um ein Objekt aus Durnholde zu holen und dieses so genannte Syndikat zu untersuchen.\n\nAls wir nach Durnholde kamen, um uns umzusehen, wurden wir von einer großen Anzahl der Menschen überrascht. Wir haben mutig gekämpft, aber allein ihre Anzahl war so überwältigend groß, um uns zu besiegen. Sie haben einige von uns als Gefangene genommen, aber ich konnte entkommen.\n\nDurnholde befindet sich nicht weit südöstlich von uns, nur über den Fluss. Drull und Tog'thar werden dort gefangen gehalten, Ihr müsst sie retten.", progress = nil, completion = "Die Menschen wollten also unsere Krieger zu Sklaven machen, wie? Wir werden es ihnen zeigen!\n\nEs scheint, als hätten sie Gol'dir, unseren Anführer, an einen anderen Ort gebracht. Wir müssen ihn finden und befreien. Aber wir haben im Moment keine Ahnung, wo er sich befindet ...\n\nSobald wir eine Spur haben, werde ich Euch mit Sicherheit benachrichtigen, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGrunzerwesteOrc-Kriegskette\n\nIhr bekommt außerdem:\n\nRezept: Großes Bärensteak"},
[499] = {title = "Elixier des Leidens", objective = "Gebt Umpi das Elixier des Leidens", description = "Es wird einen Moment dauern, diese Komponenten zu vermengen, damit ein, wie ich es nenne, Elixier des Leidens entsteht.\n\nDann mal los! Ah, es gibt doch nichts Schöneres in diesem elendiglichen Vorgebirge, als ein wenig Leiden in die Welt zu bringen.\n\nLasst uns mal überprüfen, ob unser kleiner Trank auch seine gewünschte Wirkung hat.\n\nGebt meiner Assistentin Umpi einen kleinen Schluck von dem, was die dunkle Fürstin sowohl für Menschen als auch für die Geißel geplant hat.", progress = "Quaaaaak!", completion = "Quak!", rewards = "Ihr bekommt:\n\n"},
[500] = {title = "Crushridge-Kopfgeld", objective = "Sammelt 9 schmutzige Knöchelknochen von Crushridge-Ogern im Alteracgebirge. Bringt sie zu Marshal Redpath in Southshore.", description = "Die Crushridge-Oger haben einen Ogerhort im Alteracgebirge nahe der verfallenen Stadt Alterac gebaut. Meine Späher berichteten mir, dass sie auch die Ruinen da erobert haben.\n\nWir dürfen aber nicht zulassen, dass sie sich da fest einnisten. Falls sie sich dort zu sicher fühlen, werden sie bestimmt ins Vorgebirge eindringen und wären dann praktisch vor unserer Haustür!\n\nBegebt Euch nach Norden in das Alteracgebirge auf Ogerjagd. Bringt mir die schmutzigen Knöchelknochen, die sie tragen, und Ihr habt Euch ein hübsches Kopfgeld verdient.", progress = "<Name>, immer noch auf Ogerjagd? Habt Ihr die Knöchelknochen, die Ihr laut meinem Befehl sammeln solltet?", completion = "Sehr gut, &lt;Name&gt;. Ihr müsst Euch durch eine ganze Schiffsladung Oger gehackt haben, um diese Anzahl Knöchelknochen zu erhalten.\n\nDas sollte sie uns vom Halse halten. Zumindest für eine kleine Weile.", rewards = "Ihr bekommt:\n\n"},
[501] = {title = "Elixier der Schmerzen", objective = "Bringt 10 Phiolen mit Berglöwenblut zu Apotheker Lydon in Tarrens Mühle.", description = "Oh, <Name>..., in Hillsbrad blühen die Blumen und die Luft ist so klar und rein. Ich muss in diesem ganzen Elend baden. Ich sehe aus meinem verdreckten Fenster und sehne den Tag herbei, an dem unsere neue Seuche dieser Welt ihren wohlverdienten Tod bringt.\n\nSo gern ich auch den ganzen Tag hier herumsitzen und mit Grübeln verbringen würde, meine Pflicht gegenüber der dunklen Fürstin ruft mich. Würdet Ihr mir helfen? Meine Forschungen führen mich zu der Annahme, dass sich aus Berglöwenblut ein vorzüglicher Todestrank herstellen lässt. Bringt mir etwas davon, dann können wir ein bisschen Spaß haben.", progress = "Ich erinnere mich an Euch, <Name>. Ihr wolltet mir dabei helfen mein neuestes Elixier zu brauen. Das Blut brauche ich, um den Einwohnern von Hillsbrad mein höchsteigenes, hausgemachtes Spezial-Elend zu präsentieren.", completion = "Wunderbare Sammlung, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHandschuhe der MuskelkraftStampfer-StiefelFeuerwandler-Stiefel\n\nIhr bekommt außerdem:\n\nRezept: Scharfe Löwenkoteletts"},
[502] = {title = "Elixier der Schmerzen", objective = "Füttert Stanley mit dem Elixier der Schmerzen.", description = "Ah, es geht doch nichts über den Geruch von frischem Blut im Vorgebirge!\n\nDann lasst uns eine Prise davon und ein wenig hiervon vermischen - und der einzig wahre Spaß kann beginnen! Die Kreation aus diesem Blut möchte ich Elixier der Schmerzen nennen. Wenn meine Berechnungen korrekt sind, sollte dieses Gebräu der Anfang von etwas Wunderbarem für Lady Sylvanas sein. Aber wir müssen erst mal einen Testlauf machen.\n\nBringt dieses Elixier zum nördlichen Hof in den Feldern von Hillsbrad im Südwesten. Lasst uns sehen, wie Stanley, dem kleinen Hund von Bauer Ray, dieses 'Leckerli' so schmeckt.", progress = "Wuff?", completion = "Ihr schüttet etwas von dem Elixier in Eure Hand und haltet es vor Stanleys Schnauze.", rewards = "Ihr bekommt:\n\n"},
[503] = {title = "Gol'dir", objective = "Befreit Gol'dir und kehrt dann zu Krusk in Tarrens Mühle zurück.", description = "Soweit ich das aus den Dokumenten, die Ihr herbrachtet, ersehen kann, wird Gol'dir in einem großen Syndikatsstützpunkt im Norden festgehalten, höchstwahrscheinlich im Alteracgebirge. Er ist schon zu lange dort gefangen und muss endlich befreit werden.", progress = "Gebt mir den Schlüssel, <Klasse>, ich werde das Schloss selbst aufschließen.", completion = "Danke, &lt;Name&gt;. Laut Befehl des Kriegshäuptlings hatte ich die Führung der Expedition von Durotar, aber wie Ihr sehen könnt, lief es nicht ganz so wie eigentlich geplant. Sie haben mich in dieser Stadt gefangen gehalten, mich gezwungen zu arbeiten, ich musste Lasten tragen, graben...\n\nWas ich erlitten habe, ist jedoch unwichtig. Ich habe wichtige Informationen, die Ihr dem jetzigen Anführer unserer Gruppe überbringen müsst.", rewards = "Ihr bekommt:\n\n"},
[504] = {title = "Crushridge-Kriegstreiber", objective = "Erschlagt 15 Crushridge-Kriegstreiber und kehrt dann zu Marshal Redpath in Southshore zurück.", description = "Nun, da Ihr die Bekanntschaft der Crushbridge-Oger gemacht habt, möchte ich, dass Ihr ihnen so richtig zeigt, was eine Harke ist...\n\nGeht zu den Ruinen von Alterac und sucht die Crushridge-Kriegstreiber. Ihr sollt eine große Anzahl von ihnen erschlagen - das ist der einzige Weg, um diese Schläger von dem Gebiet der Allianz fern zu halten.", progress = nil, completion = "Sehr gut. Hier ist Eure Belohnung.\n\nAls Ihr diese Kriegstreiber gesehen habt, konntet Ihr sehen, wie es um die Stadt von Alterac bestellt ist? Ich nehme an, nicht sehr gut. Oger sind nicht gerade für ihre Reinlichkeit bekannt.\n\nDank Eurer Bemühungen werden sie sich wohl jetzt von Southshore fern halten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBrennender SpanLunarrundschild\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[505] = {title = "Auftragsmörder des Syndikats", objective = "Tötet 12 Schleicher des Syndikats und 8 Diebe des Syndikats, kehrt dann zurück zu Magistrat Henry Maleb nach Southshore.", description = "Ich bin der neue Magistrat von Southshore. Ich wurde erst kürzlich ernannt, nachdem der vorherige Magistrat ermordet worden ist. Die Mörder wurden nie gefunden, aber unsere Nachforschungen haben ergeben, dass sie höchstwahrscheinlich vom Syndikat angeworben wurden - einer Gruppe von Dieben, angeführt von schurkischen Edlen des jetzt gefallenen Königsreichs von Alterac.\n\nDas Syndikat hat ein Lager nördlich von Tarrens Mühle, das von der Horde besetzt ist, und unsere neuesten Hinweise führen genau in dieses Lager. Erschlagt die Syndikatsmitglieder, die Ihr dort vorfindet.", progress = nil, completion = "Danke, &lt;Name&gt;. Ein Teil dieser Bande dürfte zwar noch immer hier herumlungern, aber wir hoffen, dass einige der Diebe und Schleicher, die Ihr erschlagen habt, für den Tod des letzten Magistraten verantwortlich waren. Doch selbst wenn dem nicht so wäre, stellt das Syndikat auf jeden Fall eine Besudelung dieses Landes dar und ist ein Schandfleck für das gesamte Volk der Menschen. \n\nSouthshore wird ihren Tod begrüßen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKreuzfahrer-GürtelIsolierte Weisenhandschuhe\n\nIhr bekommt außerdem:\n\n"},
[506] = {title = "Blackmoores Vermächtnis", objective = "Bringt die von Gol'dir gesammelten Informationen zu Krusk in Tarrens Mühle.", description = "Vor ein oder zwei Tagen erhielt ich Besuch vom Anführer dieses Syndikats. Sein Name war Aliden Perenolde und er nannte sich selbst Lord dieses Landes. Er vertraute mir seine Pläne an, die Orcs, die sich gegen ihn gewandt hatten, zu Sklaven zu machen, genau wie es einst auch sein Vater und Mentor, der geächtete Blackmoore, geplant hatte.\n\nAber viel wichtiger war, dass er seine Geliebte mitbrachte, ein zartes Mädchen namens Elysa. Um ihren Hals trug sie den Anhänger, den der Kriegshäuptling als sein Eigen wünscht.\n\nGeht jetzt, ich gehe meine eigenen Wege, nachdem ich meine Geschäfte hier erledigt habe.", progress = nil, completion = "Diese überheblichen Menschen haben vielleicht Nerven! Wir werden ihnen zeigen, dass die Orcs sich ihrem Willen niemals unterwerfen werden!\n\nDas wird nun unsere Mission, zusätzlich zur Bergung des Schmuckstücks, das der Kriegshäuptling zu haben wünscht. Es scheint, als würde das Erfüllen der einen Mission gleichzeitig die Erfüllung der anderen bedeuten.", rewards = "Ihr bekommt:\n\n"},
[507] = {title = "Lord Aliden Perenolde", objective = "Tötet Lord Aliden Perenolde und befragt seine Geliebte Elysa nach Tarethas Anhänger.", description = "Es ist unumstritten, dass Perenolde getötet werden und seine Verderbtheit ausgelöscht werden muss. Sein Herrenhaus liegt weit nördlich von hier, an den Ufern des Lordameresees. <Name>, tut Eure Pflicht, holt danach den Anhänger, den der Kriegshäuptling zu haben wünscht, und kehrt dann hierher zurück.", progress = "W-was wollt Ihr?", completion = "Nein, nein, bitte tut mir nichts! Ich wollte Eurem Volk niemals Schaden zufügen, er hat mich gegen meinen Willen genommen! Ich flehe Euch an... verschont mich!", rewards = "Ihr bekommt:\n\n"},
[508] = {title = "Tarethas Geschenk", objective = "Bringt Tarethas Anhänger zu Krusk nach Tarrens Mühle.", description = "Den Anhänger? Aber natürlich könnt Ihr ihn haben... Nehmt ihn! Nichts soll mich an ihn erinnern... nur bitte geht, bitte geht in Frieden...", progress = "Ihr seid zurückgekehrt, <Name>. Habt Ihr einen Erfolg zu vermelden?", completion = "Es ist schon merkwürdig, dass der Kriegshäuptling so viel Aufwand um so ein kleines Ding macht. Ich behaupte nicht, dass ich ihn verstehe, aber ich folge ihm, egal wie seine Befehle lauten. Ihr habt gute Arbeit geleistet, &lt;Name&gt;, der Kriegshäuptling wird über Euren Erfolg erfreut sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMantis-StiefelBriganten-Schulterstücke\n\nIhr bekommt außerdem:\n\n"},
[509] = {title = "Elixier der Pein", objective = "Bringt 6 Morastschnauzenkappen zu Apotheker Lydon in Tarrens Mühle.", description = "Ein neuer Tag, ein neues Elixier. Wenn ich was zu sagen hätte, würde ich diese lächerlichen Menschen und die Geißel die Sache einfach unter sich ausmachen lassen. Sie scheinen ohnehin absolut darauf versessen zu sein, sich gegenseitig umzubringen.\n\nAber leider hat es sich unsere dunkle Fürstin in den Kopf gesetzt, das Ganze ein wenig zu beschleunigen. Also warum diese düsteren Tage nicht dazu nutzen und hier ein wenig Tod und Krankheit verbreiten?\n\n<Name>, das ist mein Plan: Ihr macht Euch auf den Weg zur Nethander-Siedlung. Das ist südlich von Tarrens Mühle und östlich des Flusses und Southshore. Sammelt in den Feldern dort 6 Morastschnauzenkappen für mein nächstes Elixier.", progress = "Hattet Ihr Erfolg in der Nethander-Siedlung?", completion = "Ah, der fürchterliche Gestank von Morastschnauzenkappen. Wenigstens sind diese dreckigen Gnolls für etwas gut.", rewards = "Ihr bekommt:\n\nHurtigkeitstrankHeiltrank"},
[510] = {title = "Furchteinflößende Pläne", objective = "Bringt die furchteinflößenden Pläne zu Magistrat Henry Maleb nach Southshore.", description = "Unter diesen Dokumenten befindet sich eine Liste der benötigten Vorräte. Das sind unter anderem ganz banale Dinge (Nahrung, Waffen, Kleidung) wie auch etwas exotischere Ausrüstungsgegenstände (Masken, Öl, Gift).\n\nAber am auffälligsten ist die Dringlichkeit dieses Auftrags - diese Vorräte werden schnellstens benötigt, um eine Unternehmung zu starten, die in dem Dokument als 'wichtige Mission gegen Southshore' beschrieben wird.", progress = "<Name>, Ihr seht so besorgt aus. Möchtet Ihr mir etwas mitteilen?", completion = "&lt;Maleb liest die Dokumente.&gt;\n\nDas ist wirklich sehr beunruhigend, &lt;Name&gt;. Aus den Informationen in diesen Dokumenten und aus früheren Aktionen des Syndikats geht hervor, dass diese Bande von Halsabschneidern Southshore den Krieg erklärt hat.", rewards = "Ihr bekommt:\n\n"},
[511] = {title = "Verschlüsselter Brief", objective = "Bringt den verschlüsselten Brief zum Meister der Lehren Dibbs nach Southshore.", description = "Einer der Briefe auf diesem Tisch ist verschlüsselt und nicht zu ergründen.", progress = "Ja, werter Herr? Was gibt es denn?", completion = "Was ist dies? Wartet einen Moment... lasst es mich genauer betrachten.\n\n...\n\nHm, ich habe diese Form der Verschlüsselung niemals gesehen, aber ich muss zugeben, dass mein Wissen auf diesem Gebiet bei weitem nicht vollständig ist.", rewards = "Ihr bekommt:\n\n"},
[512] = {title = "Tod der Edlen", objective = "Bringt 7 Alteracsiegelringe zu Magistrat Henry Maleb nach Southshore.", description = "Ich fürchte, die Führung, die hinter dem Syndikat steht, will Southshore unbedingt ruinieren. Wir müssen diese Anführer mit aller Kraft schlagen, bevor sie ihre Pläne in die Tat umsetzen können.\n\nGeht zu den Ruinen von Strahnbrad, im Alteracgebirge im Norden. Wir glauben, dass das Syndikat dieses Gebiet als Hauptquartier benutzt.\n\nWir wissen, dass diese Bande von Halsabschneidern von ehemaligen Adligen von Alterac angeführt wird. Sie mögen sich als normale Agenten des Syndikats verkleiden, aber wenn Ihr sie tötet, werdet Ihr einen Edlen an dem Siegelring erkennen, den er trägt.\n\nBringt mir diese Siegelringe.", progress = "Habt Ihr das Syndikat gejagt? Habt Ihr die Ringe?", completion = "Wird das Syndikat seiner Adligen beraubt, geht auch seine Fähigkeit verloren, entschlossen zu handeln, und übrig bleibt nur eine Bande von Abschaum.\n\nIhr habt Eurer Allianz gut gedient, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[513] = {title = "Elixier der Pein", objective = "Bringt das Morastschnauzengemisch zu Meisterapotheker Faranell in Undercity.", description = "Gerade dachte ich noch, ein weiterer Tag ohne jegliches Amüsement, und da kommt Ihr und bringt diese wunderbaren Morastschnauzenkappen.\n\nZuerst werde ich sie zu einem feinen Gemisch zusammenrühren. Dann werden wir Meisterapotheker Faranell in Undercity benötigen, damit er seine Paste des Verfalls hinzufügt, und dann geht der Spaß erst richtig los!\n\nHier, <Name>, nehmt dieses Morastschnauzengemisch und bringt es schnell zu Meister Faranell.", progress = "Könnt Ihr nicht sehen, <Klasse>, dass ich beschäftigt bin? Die dunkle Fürstin besteht auf einer neuen Pest, bevor die Vorhut der Geißel aus Northrend uns überwältigt. Und dann noch die menschliche Bedrohung aus dem Süden. Meine Zeit ist im Augenblick sehr wertvoll. Es ist hoffentlich von Bedeutung!", completion = "Apotheker Lydon hat Euch geschickt? Warum habt Ihr das nicht gleich gesagt!\n\nTrotz seiner etwas düsteren Einstellung ist Apotheker Lydon doch eines unserer hingebungsvollsten und geschicktesten Mitglieder.\n\nDer Gute schickt mir Morastschnauzengemisch! Nun weiß ich, was unser Freund in Hillsbrad vorhat. Und mir gefällt seine Denkweise. Die dunkle Fürstin wäre äußerst beeindruckt von dem Fortschritt, den er in Richtung neue Seuche macht.", rewards = "Ihr bekommt:\n\n"},
[514] = {title = "Brief an Stormpike", objective = "Bringt den geschickt verschlüsselten Brief zu Ausgrabungsleiter Stormpike nach Ironforge.", description = "Ich habe einen Kollegen in Ironforge, der bei der Entschlüsselung dieses Briefes behilflich sein kann. Begebt Euch zur Bibliothek in der Halle der Forscher in Ironforge und sprecht mit Ausgrabungsleiter Stormpike. Richtet ihm aus, dass ich Euch geschickt habe, und zeigt ihm diesen Brief. Wenn es jemanden nördlich der Blackrockspitze gibt, der das hier lesen kann, dann ist er das.", progress = "Dibbs aus Southshore hat Euch also geschickt? Wie geht’s dem alten Bücherwurm?", completion = "Ah, eine Verschlüsselung! Eine meiner Spezialitäten. Lasst mich mal sehen...", rewards = "Ihr bekommt:\n\n"},
[515] = {title = "Elixier der Pein", objective = "Bringt die Morastschnauzenmixtur, einen starken Trollbluttrank, 5 Säbelflossenschuppen und 5 Fetzenflossenaugen zu Apotheker Lydon nach Tarrens Mühle.", description = "Ein Morastschnauzengemisch? Das ist wirklich brillant! Warum ist mir das nicht eingefallen?\n\nLasst mich meine Paste des Verfalls diesem Teufelsgebräu hinzufügen.\n\nDamit die verunreinigenden Agenzien in dieser Morastschnauzenmixtur aktiviert werden, benötigt Lydon starken Trollbluttrank, sowie einige Säbelflossenschuppen und Fetzenflossenaugen von der Südküste Hillsbrads. Er wird wissen, was zu tun ist, sobald Ihr alle Reagenzien zusammengetragen habt. Ich kann es kaum abwarten zu erfahren, wie sein Experiment ablaufen wird!", progress = "Ich bin ja so froh, dass Ihr wieder da seid, <Name>. Ich habe mich hier entsetzlich gelangweilt. Hier gab es ja nichts Unterhaltsameres zu tun, als Umpi zu vergiften und krank zu machen und sie dann wiederzubeleben... und das immer und immer und immer wieder.\n\nWie war Eure Reise nach Undercity? Hattet Ihr ein bisschen Glück und konntet ein paar Menschen auf dem Weg dorthin umbringen?", completion = "Die Aufregung dieses Experiments macht mich ganz schwummerig! Ihr wart so eine große Hilfe, &lt;Name&gt;. Zusammen werden wir Krankheit und Tod in diesem Land verbreiten!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHochapotheker-UmhangMeditative Schärpe\n\nIhr bekommt außerdem:\n\n"},
[516] = {title = "Beren's Peril", objective = "Findet zuerst Beren's Peril, tötet 6 Zwangsarbeiter von Rabenklaue sowie 6 Wächter von Rabenklaue und kehrt dann zu Schattenpriester Allister in das Grabmal zurück.", description = "Ich habe Berichte erhalten, dass eine Gruppe Untoter sich zusammenrottet, um einen Angriff gegen uns vorzubereiten. Mit diesen Informationen können wir den Spieß umdrehen und sie zuerst angreifen, damit wäre ihr Plan erledigt.\n\nLeider sind meine Informationen gelinde gesagt unvollständig. Laut Bericht verstecken sie sich an einem Ort, der als Beren's Peril bekannt ist. Ihr genauer Standort ist unbekannt, aber es scheint eine Höhle in den Hügeln zu sein, nahe einem Nest der Hexer von Dalaran.\n\nIch vertraue auf Euren Einfallsreichtum. Findet sie und macht alles dem Erdboden gleich.", progress = nil, completion = "Wenn unsere Späher und Agenten weiterhin solch wertvolle Informationen beibringen, dauert es nicht mehr lange, bis wir die Geißel des Lichkönigs aus unserem Land vertrieben haben.", rewards = "Ihr bekommt:\n\nZauberstab des Verfalls"},
[517] = {title = "Elixier der Pein", objective = "Bringt ein Fässchen mit Shindigger-Starkbier zu Apotheker Lydon nach Tarrens Mühle.", description = "Das neue Elixier ist endlich bereit für einen Test. Aber warum solch eine vollkommene, höchst ansteckende Seuche an einen einfachen Frosch oder Hund verschwenden? Wir sollten uns in Lady Sylvanas Namen eine kleine Freude erlauben.\n\nGeht nach Dun Garok. Ihr kennt doch die Kasernen, in denen diese widerlichen kleinen Zwerge umhersausen. Ihr stehlt ein Fässchen Shindigger-Starkbier für mich. Sobald ich dieses Fässchen habe, können wir beide, Ihr und ich, eine kleine Party feiern, <Name>.", progress = "Manchmal wird mir hier in Tarrens Mühle so elendiglich langweilig, dass ich am liebsten einen Krug Formaldehyd öffnen möchte und sein liebliches Aroma durch die Luft ziehen ließe. Umpi wird dann aber immer so nervös.\n\nKonntet Ihr ein Fässchen von den Zwergen besorgen? Wenn ich auch nur noch einen Tag länger dieses Elixier anstarren muss, ohne es benutzen zu können, dann schreie ich.", completion = "Endlich! Dann können wir ja anfangen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[518] = {title = "Die Krone des Willens", objective = "Tötet 14 Crushridge-Raufer für Melisara in Tarrens Mühle.", description = "Mug'Thol und seine Crushridge-Oger haben die Ruinen von Alterac überrannt. Ihm eine schwere Strafe zukommen zu lassen, ohne die Anzahl der Oger zu verringern, wird nicht einfach sein.\n\nWir machen sie erst weich und sehen dann weiter.\n\nVerstanden? Gut. Dann geht.", progress = nil, completion = "Der Schnee leuchtet rot von Ogerblut, aber wir dürfen unsere Bemühungen nicht einstellen, ehe nicht der Geist und die Zahl der Crushridge zermalmt und in den Dreck und Schnee getreten worden ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[519] = {title = "Die Krone des Willens", objective = "Tötet Targ, Muckrake und Glommus und bringt ihre Köpfe zu Melisara nach Tarrens Mühle.", description = "Targ, Muckrake und Glommus sind Mug’Thols Offiziere. Sie sind ihm loyal ergeben, aber wer weiß schon, was einen Oger loyal sein lässt.\n\nBringt mir ihre Köpfe, <Name>, und dann muss nur noch Mug'Thols Kopf, mitsamt Krone, rollen.", progress = "Ich will ihre Köpfe, <Name>, keine Entschuldigungen.", completion = "... und ich dachte Oger röchen so schon ekelhaft genug.\n\nWenn Ihr mir Mug'Thols Kopf bringt, werde ich alle vier auf Stangen oberhalb Alteracs aufstellen lassen. Ein passendes Denkmal für alle diejenigen, die sich den Wünschen der dunklen Fürstin entgegenstellen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[520] = {title = "Die Krone des Willens", objective = "Tötet Mug'Thol und bringt seinen Kopf mit der Krone des Willens zu Melisara nach Tarrens Mühle.", description = "Nun, da Mug'Thols Offiziere tot sind, muss nur noch Mug'Thol selbst getötet und die Krone des Willens wieder zurückgebracht werden. Ich bin mir ziemlich sicher, dass er sie nur äußerst unwillig wieder hergeben wird. Außerdem wird er Euch wahrscheinlich bereits erwarten, in Anbetracht des... Ablebens... seiner Kumpanen.\n\nFindet Mug'Thol und bringt mir seinen Kopf und die Krone. Der Crushridge-Widerstand wird damit beendet sein.", progress = "Drei Köpfe habe ich, einen vierten brauch ich noch. Das wird Mug'Thols sein, oder es wird der Eure, <Name>. Das ist ein Versprechen.", completion = "Ihr habt Eure Pflicht gut erledigt, &lt;Name&gt;. Mug'Thols Kopf wird die höchste Spitze der Ruinen von Alterac verzieren und die Todeswache wird die Überbleibsel der Crushridge in den Boden stampfen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[521] = {title = "Die Krone des Willens", objective = "Bringt die Krone des Willens zu Sharlindra in Undercity.", description = "Es bleibt nur noch, die Krone des Willens zu Sharlindra nach Undercity zu bringen. Sie wird dafür sorgen, dass sie an Lady Sylvanas weitergeleitet wird. Ich warne Euch, auch nur daran zu denken, sie für Eure eigenen Zwecke zu verwenden, <Name>, Mug'Thols Schicksal sollte Beispiel genug sein.", progress = "Ja? Habt Ihr etwas zu berichten?", completion = "Das ist also das Relikt, das der Oger benutzte, um den Willen der dunklen Fürstin zu unterlaufen...\n\nSeltsam, dass etwas so Einfaches so eine große Macht ausüben kann. Und dazu noch in solch ungeschickte Hände fiel. Gut gemacht, &lt;Name&gt;, ich werde die Krone Lady Sylvanas überbringen und dafür sorgen, dass sie von Eurem Verdienst hört.", rewards = "Ihr bekommt:\n\nAstraler Talisman"},
[522] = {title = "Auftragsmördervertrag", objective = "Bringt den Auftragsmörder-Vertrag zu Magistrat Maleb nach Southshore.", description = "Dies ist ein Vertrag für die Ermordung des Magistrats Henry Maleb. Er wurde mit einem unverwechselbaren Siegelring in rotem Wachs gestempelt und versiegelt.", progress = "Ihr seid ja vollkommen außer Atem! Habt Ihr etwas zu berichten?", completion = "&lt;Maleb inspiziert den Vertrag.&gt;\n\nDas erklärt den letzten Angriff auf Southshore. Das Syndikat ist bestimmt auch hinter mir her, so wie hinter dem letzten Magistraten!", rewards = "Ihr bekommt:\n\n"},
[523] = {title = "Ableben des Barons", objective = "Bringt den Kopf von Baron Vardus zu Magistrat Maleb nach Southshore.", description = "Der Vertrag, den Ihr gebracht habt, wurde von Baron Vardus unterschrieben, einem Edlen aus dem ehemaligen Königreich von Alterac, und jemand der bekannt ist für seine Kaltherzigkeit und brutale Vorgehensweisen. Es überrascht mich nicht, dass jemand wie der Baron dahinter steckt.\n\nFindet diesen Mann. Findet ihn und führt ihn seiner gerechten Strafe zu. Er befindet sich sicherlich irgendwo in den Schlupfwinkeln des Syndikats - vielleicht in den Ruinen von Strahnbrad oder irgendwo in dem Tal im Norden davon.", progress = "Baron Vardus kann doch nicht im Ernst glauben, dass er ungestraft seine Rohlinge gegen Southshore aussenden kann. Ich will seinen Kopf!", completion = "Ich danke Euch, &lt;Name&gt;. Jetzt kann ich ein wenig ruhiger schlafen, da ich weiß, dass dieser Schurke auf ewig schlafen wird.", rewards = "Ihr bekommt:\n\n"},
[524] = {title = "Elixier der Pein", objective = "Stellt das besudelte Fässchen auf den Teppich für die gefangenen Bauern.", description = "Nebenan halten die Todeswachen einige Bauern als Geiseln gefangen. Hochexekutorin Darthalia hatte vermutet, dass sich einer der Militärstrategen aus Stormwind unter ihnen versteckte. Anscheinend wurde dieser Militärstratege gestern Nacht tot in den Pestländern gefunden. Darthalia denkt ja immer so nett an mich und hat entschieden, dass die Gefangenen mir zu überlassen sind.\n\nIch denke, es ist höchste Zeit, dass wir für diese Bauern eine kleine Party schmeißen. Hört sich doch nach einer tollen Zeit an!\n\nStellt dieses besudelte Fässchen auf den Teppich in ihrem Zimmer. Seuchenbräu für alle!", progress = "Ein muffiger Geruch steigt von dem Teppich empor.", completion = "Ihr stellt das besudelte Fässchen auf dem verstaubten Teppich ab.", rewards = "Ihr bekommt:\n\n"},
[525] = {title = "Weitere Geheimnisse", objective = "Bringt den entschlüsselten Brief zu Magistrat Maleb nach Southshore.", description = "Ich habe den Brief dechiffriert, aber ich weiß nicht, was ich davon halten soll. Ihr habt ihn unter Dieben im Vorgebirge von Alterac gefunden? Sehr seltsam...\n\nIhr solltet ihn zum Magistrat nach Southshore bringen. Auch wenn dieser Brief geheimnisvoll klingt, seine Stadt liegt Alterac am nächsten, wenn eine Bedrohung sich zusammenbraut, dann sollte gerade er davon erfahren.", progress = "<Name>. Seid Ihr erneut durch die Vorgebirge und Berge gereist? Was für Neuigkeiten bringt Ihr mir?", completion = "&lt;Maleb liest den Brief.&gt;\n\nDas ist ein übersetzter Brief, den Ihr in einem Lager des Syndikats gefunden habt? Dieser Brief wurde nicht von einem Dieb geschrieben, und auch nicht von einem Edlen aus Alterac.\n\nEs scheint, als hätte das Syndikat Verbindung zu einer anderen Macht und allein bei dem Gedanken, welche es sein könnte, fährt es mir kalt den Rücken hinab.", rewards = "Ihr bekommt:\n\n"},
[526] = {title = "Lichtschmiedeblöcke", objective = "Sammelt 5 Lichtschmiedeblöcke und kehrt dann zu Glorin Steelbrow im Sumpfland zurück.", description = "Ihr mögt zwar einen Lichtschmiedeblock in dieser Truhe gefunden haben, aber das reicht nicht aus, um irgendetwas von Nutzen daraus zu schmieden.\n\nIhr solltet zurückgehen und nach weiteren suchen. Vielleicht tragen die Murlocs in der Nähe des Schiffswracks Lichtschmiedeblöcke mit sich herum.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[527] = {title = "Kampf um Hillsbrad", objective = "Tötet 6 Landarbeiter von Hillsbrad, 6 Bauern von Hillsbrad, Bauer Ray und Bauer Getz und meldet Euch dann wieder bei Darthalia in Tarrens Mühle.", description = "Steht gefälligst stramm, wenn Ihr mit mir sprecht, <Klasse>.\n\nIch stehe unter direktem Kommando von Varimathras. Wir sollen der menschlichen Plage Einhalt gebieten, bis unsere Apotheker eine neue Pest entwickeln können.\n\nUnseren Informationen zufolge bietet Hillsbrad einen guten Angriffspunkt. Eure erste Aufgabe ist darauf gerichtet, die Nahrungsversorgung und Infrastruktur zu unterbrechen.\n\nBegebt Euch nach Westen. Überfallt die nördlichsten Höfe der Felder von Hillsbrad. Und stellt sicher, dass die Landeigner, Bauer Ray und Bauer Getz, ebenfalls exekutiert werden.", progress = nil, completion = "Rührt Euch, &lt;Klasse&gt;. Ihr seid vom Kampf zurückgekehrt, wie ich sehe. Meine Quellen besagen, dass Ihr Euch an der Front in Hillsbrad tapfer geschlagen habt.", rewards = "Ihr bekommt:\n\n"},
[528] = {title = "Kampf um Hillsbrad", objective = "Tötet 15 Arbeiter von Hillsbrad und erstattet Bericht bei Darthalia in Tarrens Mühle.", description = "Die Berichte vom Angriff auf die nördlichen Höfe haben die Stadtbevölkerung in Panik versetzt. Vorzüglich.\n\nUnsere Todespirscher melden, dass Arbeiter in die Felder ins südliche Hillsbrad flüchten. Diese Narren glauben doch tatsächlich, dass sie sich in den Obsthainen verstecken und so ihrer Verdammnis entkommen können.\n\nBeweist ihnen das Gegenteil, <Name>. Kehrt zu den Feldern von Hillsbrad zurück und macht die feigen Arbeiter ausfindig. Vernichtet sie im Namen der dunklen Fürstin.\n\nWeggetreten!", progress = nil, completion = "Die Schlinge um Hillsbrad zieht sich zu. Der Kampf läuft gut.", rewards = "Ihr bekommt:\n\n"},
[529] = {title = "Kampf um Hillsbrad", objective = "Tötet Schmied Verringtan und 4 Schmiedelehrlinge von Hillsbrad.\n\nBesorgt eine Eisenlieferung und erstattet Bericht bei Darthalia in Tarrens Mühle.", description = "Die Menschen in Hillsbrad leisten unerwarteten Widerstand. Das Problem scheint darin zu bestehen, dass die Bewohner durch den örtlichen Schmied mit Waffen versorgt werden. Wir müssen alle Versorgungsmöglichkeiten abschneiden.\n\nEure Aufgabe ist es, Schmied Verringtan zu eliminieren. Tötet auch gleich seine Lehrlinge. Wenn Ihr schon dort seid, bringt auch gleich eine Eisenlieferung aus ihrem Vorratslager mit zurück. Nach der Eroberung von Hillsbrad werden diese Vorräte uns gelegen kommen, wenn wir mit der Verwüstung von Southshore beginnen.", progress = "Konntet Ihr Eure Befehle ausführen, <Klasse>? Konntet Ihr Verringtan und seine Assistenten loswerden? Und wo ist diese Eisenlieferung?", completion = "Mission erfüllt, &lt;Klasse&gt;. Und auf sehr geschickte Weise, wie ich hinzufügen möchte.", rewards = "Ihr bekommt:\n\n"},
[530] = {title = "Rache eines Ehemanns", objective = "Tötet Valdred Moray.\n\nBringt seine Hände zu Raleigh Andrean nach Undercity.", description = "Valdred, einst ein guter Freund von mir, ist der Mörder meiner Frau. Auch wenn ich keine Trauer empfinden kann, so sehne ich mich doch nach Rache. Wenn Ihr Valdred tötet und mir seine verfluchten Hände bringt, werde ich Euch belohnen.\n\nDas Letzte, was ich hörte, war, dass er sich im südlichen Silberwald beim Greymane-Wall aufhält und in das Königreich von Gilneas flüchten will.", progress = "Habt Ihr diese Hände, <Name>?", completion = "Ah, sehr gut. Diese Hände haben meine Frau, Deliah, getötet. Mein einziger Gedanke war Rache für ihren Tod, und Ihr wart das Instrument für diese Rache.\n\nHier, nehmt den Ring, den Ihr früher zurückbrachtet. Deliah ist für mich schon so lange tot, ihr Ring ist ein Schmuckstück, das ich nicht länger haben möchte. An seiner Statt werde ich diese Hände als Erinnerung an den Verrat meines Freundes behalten.", rewards = "Ihr bekommt:\n\nRing der Verachtung"},
[531] = {title = "Vyrins Rache", objective = "Bringt Old Sootys Kopf zu Vyrin Swiftwind in die Weitschreiter-Lodge.", description = "Licht! Bringt solche Dinge nicht in die Lodge... das ist unhygienisch, unaussprechlich, un... un... unhygienisch!\n\nBringt es bitte einfach nur raus hier, ja? Niemand will Eure kleine blutige Trophäe sehen, nu wirklich nicht!", progress = "Sehr gute Arbeit, <Name>! Wir habens ihm wirklich gezeigt! Hier, gebt mir den Kopf, ich werde mich darum kümmern.", completion = "Danke für Eure Hilfe bei meinem kleinen Plan, &lt;Name&gt;. Seit Monaten wollte ich es diesem hochnäsigen, eingebildeten Jungen schon heimzahlen und ich würde meinen, es hat so richtig gut geklappt! Hier, nehmt das, Ihr habt es Euch verdient.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nJagdmunitionssackJagdköcher\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[532] = {title = "Kampf um Hillsbrad", objective = "Tötet Magistrat Burnside und 5 Ratsherren von Hillsbrad. Zerstört die Proklamation von Hillsbrad. Stehlt das Stadtregister von Hillsbrad. Meldet Euch danach bei Darthalia in Tarrens Mühle.", description = "Hillsbrad ist ein einziges Chaos und wir sind der Meinung, dass die Stadt bald fallen wird. Nichtsdestotrotz müssen wir weiterhin an unserer Ruchlosigkeit festhalten bis der menschliche Abschaum ein für alle Mal von diesem Vorgebirge verschwunden ist.\n\nTrotz ihrer überwältigenden Verluste sammeln die Menschen sich weiterhin um ihre Führungskraft und kämpfen weiter. Wir müssen ihren Anführer, Magistrat Burnside eliminieren und mit ihm den ganzen Stadtrat. Zerstört ihr heißgeliebtes politisches Dokument, die Proklamation von Hillsbrad, gleich mit. Und wenn Ihr schon dabei seid, stehlt das Stadtregister.", progress = "Welche Neuigkeiten habt Ihr?", completion = "Neuigkeiten über Eure Ruhmestaten in Hillsbrad reisen schnell. Ihr habt Eure Sache gut gemacht, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"},
[533] = {title = "Unterwanderung", objective = "Holt Informationen über Gol'dirs Aufenthaltsort für Krusk in Tarrens Mühle ein.", description = "Endlich haben wir eine Spur und können nach Hinweisen auf Gol'dirs Aufenthaltsort suchen. Die Menschen haben ihn immer wieder umquartiert, aber wir konnten unsere Suche einengen und konzentrieren uns jetzt auf das große Syndikatlager nördlich von hier.\n\nBegebt Euch dorthin, <Name>, und beschafft alle Informationen, an die Ihr herankommen könnt.", progress = "Habt Ihr etwas erfahren können? Ich fürchte, dass Gol'dirs Aussichten von Tag zu Tag schlechter werden...", completion = "Endlich wissen wir, wo Gol'dir festgehalten wird. Das betreffende Lager befindet sich nicht allzu weit entfernt von hier. Es bleibt zu hoffen, dass sie nicht so gut vorbereitet sind wie damals, als sie uns das erste Mal gefangen nahmen.", rewards = "Ihr bekommt:\n\n"},
[535] = {title = "Valik", objective = "Bringt einen Becher mit Southshore-Starkbier zu Valik in das Lager des Syndikats.", description = "Arrrgh... Verletzt, sterbend und den Feind direkt vor Augen...\n\nDa Ihr mich ja sowieso töten werdet, könntet Ihr mir da vielleicht zuvor ein Southshore-Starkbier bringen - Euresgleichen trinkt doch auch, oder? - und ich werde Euch sagen, was Ihr wissen wollt.", progress = "Habt Ihr mir etwas zu trinken gebracht, oder seid Ihr nur hier, um Eure Arbeit zu Ende zu führen?", completion = "In Anbetracht meines baldigen Todes möchte ich nur sagen, dass das hier das Süßeste ist, was ich jemals geschmeckt habe... Hier, nehmt das, wenn ich erst tot bin, nützt es mir sowieso nichts mehr.\n\nAlso, macht schon!", rewards = "Ihr bekommt:\n\nSchreiben des Syndikats"},
[536] = {title = "Die Küste entlang", objective = "Tötet 10 Gezeitenjäger der Fetzenflossen und 10 Orakel der Fetzenflossen für Lieutenant Farren Orinelle in Southshore.", description = "Von der Stadtwache von Stormwind nach Southshore versetzt, eine Stadt, die man gleich wieder verlassen sollte... wie's aussieht. Der Gestank vom Hafen Tag und Nacht.\n\nGanz zu schweigen vom alten Redpath... Will, dass ich mich um die Murlocs kümmere. Ha! \n\nKann mich kaum aufraffen, die Unterschlüpfe dieser übergroßen Fische unten am Weststrand aufzusuchen. Wenn Ihr für mich gehen und Euch um sie kümmern würdet, wäre ich Euch sehr dankbar.", progress = nil, completion = "Ich hoffe, das reicht aus, um Redpath davon zu überzeugen, dass ich - ha! - seine Befehle ausgeführt und Southshore von der schrecklichen und furchterregenden Bedrohung der Murlocs befreit habe. Denn es gibt ja auch nichts Schlimmeres als die Bedrohung seitens übergroßer Fische!", rewards = "Ihr bekommt:\n\n"},
[537] = {title = "Der Dunkle Rat", objective = "Tötet 4 Schattenmagier der Arguswacht.\n\nBringt den Kopf von Nagaz zu Magistrat Maleb nach Southshore.", description = "Der Brief, den Ihr mir gebracht habt, wurde von einem Wesen geschrieben, das sich selbst Nagaz nennt, ein Mitglied der Arguswacht. Ich weiß nicht, was diese Arguswacht ist, aber wenn sie mit dem Syndikat zusammenarbeiten, dann sind sie eine Bedrohung.\n\nIch möchte, dass Ihr Nagaz und die Schattenmagier der Arguswacht, die in diesem Brief erwähnt werden, findet. Ihr sollt sie finden und dann töten.\n\nSucht im Oberland, wo das Syndikat am stärksten ist. Es liegt nördlich von Strahnbrad.\n\nMit etwas Glück könnt Ihr die Abgesandten der Arguswacht dort finden.", progress = "Konntet Ihr die Abgesandten der Arguswacht finden?", completion = "Gut gemacht, &lt;Name&gt;. Die Arguswacht sollte unserer Meinung nach nicht unbedingt die Gruppe sein, die das Syndikat leiten sollte.\n\nUnd auch wenn Ihr ihren Anführer hier getötet habt, diente Nagaz doch auch nur jemand anderem. Die Arguswacht ist möglicherweise im ganzen Kontinent von Azeroth verbreitet.\n\nOder sogar in der ganzen Welt.", rewards = "Ihr bekommt:\n\n"},
[538] = {title = "Southshore", objective = "Sprecht mit dem Meister der Lehren Dibbs in Southshore.", description = "<Name>. Wenn Ihr einer langen Reise nicht abgeneigt seid, dann habe ich eine neue Aufgabe für Euch, Stormwind erneut bei der Bestückung seiner Bibliothek behilflich zu sein.\n\nDas alte Königreich von Alterac ist nach dem großen Krieg gefallen und es besaß eine umfangreiche Büchersammlung. Es ist eine große Tragödie, dass die Stadt verfallen ist, aber es ist weitaus tragischer, dass all ihr Wissen verloren geht! Wir müssen retten, was zu retten ist.\n\nSouthshore liegt den Ruinen von Alterac am nächsten. Begebt Euch dorthin und sprecht mit dem Meister der Lehren Dibbs. Er kann Euch den Weg zu den Ruinen erklären und welche Bücher dort zu finden sind.", progress = nil, completion = "Ah ja, ich erinnere mich an Milton. Ein Bücherwurm, ganz ohne Zweifel. Der Gute.\n\nUnd er hat Recht. In den Ruinen von Alterac liegt immer noch ein großer Wissenschatz, der möglicherweise für immer verloren geht!\n\nIn Alterac leben jetzt Oger, und die zeigen kein großes Interesse an höherer Bildung.", rewards = "Ihr bekommt:\n\n"},
[539] = {title = "Kampf um Hillsbrad", objective = "Tötet Großknecht Bonds sowie 10 Minenarbeiter von Hillsbrad und erstattet Bericht bei Darthalia in Tarrens Mühle.", description = "Das Stadtregister von Hillsbrad deutet an, dass der Azurschacht unter der Kontrolle der Allianz steht. Außerdem ist die Mine eine erstklassige Quelle für Eisenerz für die Waffenkammern der Allianz.\n\nAuch wenn wir der Stadt von Hillsbrad einen entscheidenden Schlag versetzen konnten, unterstützt und beschützt die Allianz den Azurschacht immer noch aufs Äußerste.\n\nDie Mine liegt genau im Süden von Hillsbrad. Begebt Euch dorthin und tötet den Großknecht, einen Menschen namens Bonds. Tötet auch gleich seine Minenarbeiter. Das sollte der Allianz ein deutliches Zeichen setzen.", progress = "Ihr hattet den direkten Befehl, den Azurschacht anzugreifen. Ihr solltet besser gute Gründe für Euer Verbleiben in Tarrens Mühle haben, oder ich werde Euch wegen Verrates köpfen lassen.", completion = "Die dunkle Fürstin wird erfreut sein, eine neue Mine ihr Eigen zu nennen, mit der sie ihre Soldaten bewaffnen kann.", rewards = "Ihr bekommt:\n\n"},
[540] = {title = "Wissen bewahren", objective = "Bringt 5 geborgene Folianten und das abgenutzte Lederbuch, das 'Der Arm von Gri'lek' enthält, zum Meister der Lehren Dibbs nach Southshore.", description = "Diese barbarischen Oger haben sich in den Ruinen von Alterac ausgebreitet und es schüttelt mich bei dem Gedanken, was sie mit den wertvollen Büchern dort anstellen könnten. Ihr müsst retten, was immer Ihr könnt!\n\nGeht zu den Ruinen von Alterac und sucht dort nach Folianten, die die Oger gestohlen haben. Nehmt, was immer Ihr finden könnt, und bringt alles zu mir, aber sucht insbesondere ein ganz bestimmtes Buch: Der Arm von Gri'lek. Es enthält alte Trolllehren, die ich erlernen muss. Die Ruinen von Alterac waren der letzte bekannte Ort, an dem es ein intaktes Exemplar dieses Buches geben soll.", progress = "Ich wünschte, ich könnte ebenfalls die Ruinen absuchen, aber ich befürchte meine Knochen werden mich beim Bergsteigen nicht halten können. Wie dem auch sei, wie geht Eure Wissensjagd voran, <Name>?", completion = "Oh, Ihr habt sie schon! Wie wunderbar! Ich muss sofort mit dem Studium des Arms von Gri'lek beginnen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[541] = {title = "Kampf um Hillsbrad", objective = "Begebt Euch nach Dun Garok, tötet 10 Gebirgsjäger, 8 Scharfschützen, 4 Priester sowie Captain Eisenberg und erstattet danach Bericht bei Darthalia in Tarrens Mühle.", description = "Zwerge helfen Menschen? Diese verdammten, dreckigen kleinen Bestien.\n\nWir werden die Stärke dieser so genannten Allianz testen. Wir werden ja sehen, wie sehr diese kleinen Wadenbeißer den Menschen noch helfen wollen, nachdem sie unseren Zorn zu spüren bekommen haben. Wir wissen ganz genau, wo sie in diesem Gebiet ihre Hochburg haben.\n\nSie haben eine Kaserne namens Dun Garok im südöstlichen Hillsbrad entlang des Thoradin-Walls errichtet. Die letzte Order in diesem Kampf ist die Belagerung von Dun Garok, <Klasse>. Captain Eisenberg, ihr Anführer muss sterben.", progress = nil, completion = "Eure Taten auf dem Schlachtfeld sind des höchsten Lobes wert.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[542] = {title = "Rückkehr zu Milton", objective = "Bringt die Folianten von Alterac zu Milton Sheaf nach Stormwind.", description = "Ich werde einige Zeit benötigen, um das Buch Der Arm von Gri'lek zu studieren, das Ihr mir gebracht habt. Ich bin sicher, Milton kann es kaum erwarten, die anderen geborgenen Bücher in die Sammlung von Stormwind zu integrieren.\n\nHier sind die Bücher, die Ihr aus den Ruinen von Alterac mitgebracht habt, verpackt und katalogisiert. Bringt sie zu Milton Sheaf in Stormwind und ich versichere Euch, dass er sehr dankbar sein wird.", progress = "<Name>, Ihr seid zurück! Wie lief Euer Ausflug nach Alterac? Habt Ihr etwas mit zurückgebracht?", completion = "Meine Güte! Seht Euch das an! Ich kann kaum glauben, dass sie die Zerstörung von Alterac überstehen konnten. Und dann noch all diese Oger!\n\nDanke, &lt;Name&gt;. Ich danke Euch wirklich sehr! Ihr wart dabei behilflich, menschliches Wissen zu bewahren, und Ihr tragt zur Größe der Königlichen Bibliothek von Stormwind bei.", rewards = "Ihr bekommt:\n\n"},
[543] = {title = "Die Perenolde-Tiara", objective = "Bringt die Perenolde-Tiara zu Remington Ridgewell nach Stormwind.", description = "Die Perenolde-Tiara ist ein altes Erbstück der \"Edlen\" von Perenolde - der Herrscherfamilie von Alterac, bevor das Königreich verfiel. Es heißt, dass sie von Meisterjuwelieren in Ironforge hergestellt und mit den schönsten Smaragden besetzt wurde.\n\nAls Alterac zerstört wurde, ging die Tiara verloren, aber Gerüchten zufolge soll ein Ogermagier, Grel'borg der Horter, die Tiara gefunden haben und jetzt in den Ruinen von Alterac auf der Suche nach weiteren Schätzen umherwandern.\n\nWir möchten, dass Ihr die Tiara für uns beschafft.", progress = "Willkommen, <Name>. Bitte versucht, nicht auf meine Hosenmanschetten zu treten. Dieses Gewand ist gerade neu geschneidert worden.", completion = "Ah, dies ist superb. Natürlich muss sie erst gereinigt werden, aber Ihr habt Euch wirklich übertroffen, &lt;Name&gt;. Ich werde veranlassen, dass jemand die Tiara vorbereitet und sie schnellstens in unserer Sammlung aufstellt.\n\nIhr werdet mir sicherlich zustimmen, dass unsere Dankbarkeit genauso groß ist, wie unsere Sammlung.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[544] = {title = "Gefängnis-Einbruch", objective = "Findet diese Verräter, sammelt ihre Artefakte ein und kehrt dann zu Magus Voidglare nach Tarrens Mühle zurück.", description = "Eigentlich kam ich zu Forschungszwecken nach Tarrens Mühle, aber jetzt muss ich eine Krise verhindern. Wisst Ihr, vier Verlassene sind vor einigen Monaten aus Undercity geflohen. Sie haben ihren Brüdern den Rücken zugekehrt, aber was viel schlimmer ist... sie haben die dunkle Fürstin bestohlen.\n\nDiese Diebe sind in ein gesichertes Gewölbe eingebrochen und haben vier Artefakte gestohlen; Gegenstände, die unsere Apotheker für bestimmte Studien benötigen. Sylvanas will, dass diese Artefakte zurückgebracht werden.\n\nDie Diebe sind aus Undercity nach Dalaran geflohen und diese Hexer haben sie in Quarantäne in das Lordamere-Internierungslager gesteckt.", progress = "Habt Ihr die Diebe gefunden? Und was wichtiger ist, habt Ihr das gefunden, was sie gestohlen haben?", completion = "Ihr habt den Verlassenen einen großen Dienst erwiesen, &lt;Name&gt;. Diese Artefakte wurden schmerzlichst vermisst.\n\nUnd es ist gut zu hören, dass Kegan und die anderen Verräter ihre gerechte Strafe gefunden haben.", rewards = "Ihr bekommt:\n\n"},
[545] = {title = "Patrouillen von Dalaran", objective = "Tötet 6 Beschwörer von Dalaran sowie 12 Elementarsklaven und kehrt dann zu Magus Voidglare nach Tarrens Mühle zurück.", description = "Die Hexer von Dalaran haben eine riesige, magische Kuppel um ihren Stadtkern errichtet. Einige glauben, dass es zum Schutz gegen die Gewalt unserer Zeit gemacht wurde, andere wiederum sagen, dass sie einfach Ruhe zum Studieren und Pläneschmieden haben wollen.\n\nMir persönlich ist der Grund egal. Aber mir ist nicht egal, dass die verfallenen Vororte der Stadt, die außerhalb der Kuppel liegen, möglicherweise wertvolle magische Schätze beherbergen.\n\nAber dieses Gebiet wird von den Hexern und ihren Elementarsklaven patrouilliert.\n\nAlso jagt sie und kehrt erst zurück, wenn ihre Anzahl einigermaßen reduziert worden ist.", progress = nil, completion = "Sehr gut. Diese Ruinen sollten jetzt sicher genug für eine Suche sein, vorausgesetzt, man ist vorsichtig.\n\nIch danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[546] = {title = "Andenken des Todes", objective = "Todeswache Samsa aus Tarrens Mühle will 30 menschliche Schädel aus Hillsbrad.", description = "Ich habe gehört, Ihr wurdet von Darthalia eingezogen, um Krieg gegen die Menschen von Hillsbrad zu führen. Ich bin ganz grün vor Neid...\n\nIhr habt den ganzen Spaß... Menschen erschlagen, die Stadt plündern, Unschuldige terrorisieren..., und ich stecke hier fest und darf in Tarrens Mühle Wache schieben.\n\nVielleicht habt Ihr ja etwas Mitleid mit einer alten Todeswache wie mir? Wisst Ihr, ich sammle nämlich menschliche Schädel. Und Ihr werdet eine recht lange Zeit gegen Menschen kämpfen. Bringt mir im Verlauf Eures langen Kampfes 30 Schädel, und ich werde Euch für Eure Mühe entlohnen.", progress = "<Name>, das Glückskind kehrt also zurück? Wie viele Menschen habt Ihr heute getötet? Hunderte, hoffe ich doch!\n\nHabt Ihr ein paar Schädel für mich?", completion = "Wundervolle Schädel! So wunderschön! Ich bin Euch was schuldig, versprochen, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nSchädelring"},
[547] = {title = "Humberts Schwert", objective = "Bringt das Schwert von Todeswache Humbert aus Dun Garok zu ihm nach Tarrens Mühle zurück.", description = "Hochexekutorin Darthalia hat mich hergeschickt, um Dun Garok aus der Ferne zu beobachten. Ich hatte mein Lager gerade außer Sichtweite aufgeschlagen. Am Morgen, als ich Wasser kochen wollte, ging ich Feuerholz sammeln.\n\nAls ich ins Lager zurückkam, entdeckte ich, dass meine Ausrüstung verschwunden war.\n\nAnscheinend waren ein paar Zwergenspäher von Dun Garok vorbeigekommen und hatten alles mitgenommen. Ich brauche mein Schwert! Wenn Ihr es für mich zurückholen könntet, wäre ich Euch sehr dankbar. So viele Zwerge hier... es wird ganz schön schwierig sein, den kleinen dreckigen Dieb zu finden, der es gestohlen hat.", progress = "Konntet Ihr mein Schwert zurückholen, <Name>? Hochexekutorin Darthalia wird mich an den Dachbalken aufhängen, wenn sie etwas von meiner Dummheit erfährt.", completion = "Ihr habt es gefunden!\n\nAh, ich fühl mich so vollständig, jetzt wo mein wunderbares Schwert wieder in meiner Hand ist. Ich danke Euch vielmals!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRippenbrustplatteSöldnergamaschen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[549] = {title = "GESUCHT: Syndikatspersonal", objective = "Tötet 10 Schurken des Syndikats und 10 Wachmänner des Syndikats. Kehrt danach zu Hochexekutorin Darthalia nach Tarrens Mühle zurück.", description = "In Lady Sylvanas Namen sollen alle Mitglieder der Organisation, die sich das Syndikat nennt, getötet werden. Diejenigen, die bereits gefangen genommen wurden, werden gemeinschaftlich hingerichtet. Wir wissen, dass sie sich im Moment in den Ruinen der Burg Durnholde im Südosten von Tarrens Mühle sammeln.\n\nFür alle diejenigen, die Beweise ihrer Taten zu Hochexekutorin Darthalia bringen, ist eine reiche Belohnung ausgesetzt.", progress = nil, completion = "Exzellent, &lt;Klasse&gt;. Wenn Ihr so weitermacht, wird die Syndikatsplage schon bald der Vergangenheit dieses Landes angehören.", rewards = "Ihr bekommt:\n\n"},
[550] = {title = "Kampf um Hillsbrad", objective = "Bringt Darthalias versiegelte Belobigung zu Varimathras nach Undercity.", description = "Da Ihr mit solcher Verbissenheit und Ehre in der Schlacht von Hillsbrad gekämpft habt, habe ich für Euch diese Belobigung geschrieben, in der Eure Heldentaten im Kampf angemessen gerühmt werden, sodass das Oberkommando sie anerkennt.\n\nBringt die versiegelte Belobigung zu Varimathras nach Undercity. Geht erhobenen Hauptes, <Klasse>.", progress = "Was führt Euch den ganzen Weg vom Schlachtfeld nach Undercity, <Klasse>?", completion = "Ihr seid also der berüchtigte &lt;Klasse&gt;, der einen solch entscheidenden Schlag gegen die Allianzkräfte im Vorgebirge von Hillsbrad geführt hat... Die Nachricht Eurer glorreichen Taten kam schnell bis nach Undercity.\n\nIhr habt eine schöne Zukunft in den Rängen der dunklen Fürstin vor Euch, wenn Ihr weiterhin solche Führungskraft und solch ein Geschick in der Schlacht zeigt.\n\nWährend unsere größte Bedrohung die Geißelarmee des Lichkönigs ist, die von Norden her einmarschiert, behindert das \"Menschenproblem\" weiterhin unsere Schlachtpläne. Ihr jedoch habt uns gezeigt, dass Menschen tatsächlich besiegt werden können.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHeilige Begräbnis-BeinkleiderTotenschädelschildRunenverzierte Dunkelklinge\n\nIhr bekommt außerdem:\n\nBand von Undercity"},
[551] = {title = "Das Verhexte Pergament", objective = "Bringt den verschlüsselten Brief zum Meister der Lehren Dibbs nach Southshore.", description = "Dieses Pergament ist mit einer Verzauberung versehen, die es unlesbar macht. Nur ein Wort oben am Blattanfang ist lesbar:\n\n\n Nagaz\n\n", progress = "Oh. Ihr habt etwas für mich, auf das ich einen Blick werfen soll? Ein Teil der Lehren, die Ihr oben in den Bergen gesammelt habt, wie ich hoffe...", completion = "Weitere verschlüsselte Notizen?\n\nIch wünschte ich hätte das Talent, um all diese seltsamen Schriften entziffern zu können, die jetzt von Alterac hereinkommen. Aber leider verfüge ich nicht über das passende Wissen.", rewards = "Ihr bekommt:\n\n"},
[552] = {title = "Helculars Rache", objective = "Holt Helculars Rute von dem Yeti und bringt sie zu Novize Thaivand nach Tarrens Mühle zurück.", description = "Meister Helcular hatte seine Transformation in einen Lich fast vollständig abgeschlossen, als ein menschlicher Lynch-Mob seinen rituellen Unterschlupf in den Hügeln entdeckte und ihn brutal ermordete. Was die Angelegenheit noch schlimmer macht, ist, dass sie seinen Leichnam auf dem Friedhof von Southshore begraben haben.\n\nDiese Missachtung eines großen Hexers ist einfach nicht akzeptabel. Als sein Lehrling werde ich dafür sorgen, dass der Regen der Rache auf Southshore fallen wird.\n\nAber zuerst benötigen wir Helculars Rute. Yetis befinden sich jetzt in seinem rituellen Unterschlupf. Bestimmt hat sich eine dieser Bestien die Rute angeeignet.", progress = "Habt Ihr Helculars Rute bereits gefunden? Es gibt in dieser Gegend so viele Yetis, dass es bestimmt schwierig sein wird, sie aufzufinden. Aber wir müssen sie erst haben, bevor wir weitermachen können.", completion = "Ihr habt sie gefunden! Vorzüglich, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[553] = {title = "Helculars Rache", objective = "Ladet die Rute von Helcular mit der Macht der Flamme von Azel, der Flamme von Veraz und der Flamme von Uzel auf.\n\nStoßt die aufgeladene Rute in Helculars Grab in Southshore.", description = "Hier, nehmt die Rute von Helcular. Ihr werdet sie brauchen.\n\nHelcular stellte 3 zeremonielle Scheiterhaufen als Teil seines mächtigsten Zaubers auf. Die Flamme von Azel und die Flamme von Veraz liegen in den Vorgebirgshöhlen. Die Flamme von Uzel liegt in einer Höhle über diesen Höhlen, weiter nördlich in den Bergen.\n\nDie Rute von Helcular muss mit jeder der drei Flammen aufgeladen werden. Sobald das Ritual abgeschlossen ist, stoßt Ihr die Rute in Helculars Grab in Southshore, der streng bewachten Menschen-Stadt im Süden. Die Rache wird unser sein!", progress = "Helculars Grab brodelt vor mystischer Energie.", completion = "Ein großes Grollen steigt vom Boden herauf.", rewards = "Ihr bekommt:\n\n"},
[554] = {title = "Stormpikes Entschlüsselung", objective = "Bringt das verhexte Pergament zu Ausgrabungsleiter Stormpike nach Ironforge.", description = "Ausgrabungsleiter Stormpike ist ein Meister der Dechiffrierung und Entschlüsselung. Wenn Ihr das Pergament, das Ihr gefunden habt, zu ihm bringt, kann er mit etwas Glück herausfinden, was darin steht. Im Moment studiert Stormpike im Ausgrabungsleiter-Hauptquartier in Ironforge.\n\nWenn Ihr ihn seht, richtet ihm aus, dass Ihr mit mir gesprochen habt, - ich habe ihm in letzter Zeit einiges zu tun gegeben.", progress = "Noch mehr Unterbrechungen?\n\nAh, dieses Pergament ist mit einem sehr verzwickten, fein gewobenen Zauber umhüllt. Natürlich kann ich ihn entwirren, aber das wird seine Zeit dauern. Und meine Zeit ist mir sehr kostbar...\n\nVielleicht kaufe ich es Euch einfach ab?", completion = "Eine weise Entscheidung. Ich glaube nicht, dass es noch einen weiteren Gelehrten außer mir selbst gibt, der die Fähigkeit hat, diese Schriftrolle zu übersetzen. Und falls sein Inhalt sich als interessant erweisen sollte, keine Angst. Ich werde nach Euch schicken.", rewards = "Ihr bekommt:\n\n"},
[555] = {title = "Milde Schildkrötensuppe", objective = "Bringt 10 Stücke Schildkrötenfleisch und einige feine Gewürze zu Küchenchef Jessen nach Southshore.", description = "Wenn es etwas Wissenswertes über Southshore gibt, dann dass wir hier die beste Küche nördlich von Stormwind haben!\n\nNehmt als Beispiel nur mal mein Rezept für Schildkrötensuppe. Ich habe Leute getroffen, die sogar von Dunkelhain hergekommen sind, nur um eine Schüssel voll davon zu kosten. Da wir gerade davon sprechen, in letzter Zeit konnte ich keine mehr kochen. Ich bin früher selbst bis kurz hinter Dalaran an den Lordameresee gereist, um Schnappkiefer zu jagen, aber das ist jetzt zu gefährlich. Wenn Ihr mir etwas Schildkrötenfleisch von den Schnappkiefern aus dem Norden bringt und dazu noch feine Gewürze, dann werd ich eine kochen!", progress = "Hattet Ihr Erfolg bei der Suche nach den Zutaten? Ich sag Euch, dieses Gebiet ist nicht mehr der friedliche Ort, der er einst war. Wenn nur diese Aufstände niemals stattgefunden hätten...", completion = "Das wird allen sehr gefallen: Die milde Schildkrötensuppe von Küchenchef Jessen ist wieder auf dem Menüplan!", rewards = "Ihr bekommt:\n\nRezept: Milde SchildkrötensuppeMilde Schildkrötensuppe"},
[556] = {title = "Steinmarken", objective = "Bringt 10 abgenutzte Steinmarken zu Bewahrer Bel'varil nach Tarrens Mühle.", description = "Ein bemerkenswertes Talent der Hexer von Dalaran ist ihre Vertrautheit mit den Elementaren: mächtige Kreaturen aus anderen Dimensionen. Die Hexer benutzen magische Marken als Mittel, diese Elementare zu kontrollieren. Magus Voidglare hätte gern einige dieser Marken, damit er sie studieren kann.\n\nBegebt Euch auf das Gebiet der Hexer von Dalaran, westlich von Hillsbrad, und sammelt die Marken ein.\n\nJeder Einwohner von Dalaran hat solche Marken, aber ich schlage vor, dass Ihr im Internierungslager auf die Suche geht. Dort ist es sicherer als in Dalaran selbst.", progress = "Habt Ihr die abgenutzten Steinmarken, <Name>? Der Magus kann es kaum erwarten, ihren Geheimnissen auf den Grund zu gehen.", completion = "Diese eignen sich wunderbar. Obwohl es scheint, als sei ihre Magie verblasst, ist es wohl am besten, wenn der Magus seine ersten Experimente an solch trägen Exemplaren wie diesen hier durchführt.\n\nIch danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[557] = {title = "Armschienen der Bindung", objective = "Bringt 4 Armschienen der Erdbindung zu Bewahrer Bel'varil nach Tarrens Mühle.", description = "Der Magus wird die Steinmarken, die Ihr gesammelt habt, einige Zeit lang intensiv untersuchen, aber ich weiß, dass er später mit Bestimmtheit auch Exemplare ihrer Gegenstücke haben will: Armschienen der Bindung. Diese befinden sich an den Handgelenken von echten Elementaren und binden sie in die Dienste der Magier.\n\nMacht Jagd auf Elementare in den Ruinen von Dalaran und sammelt ihre Armschienen der Erdbindung, und der Magus wird sehr erfreut sein.", progress = "Hallo, <Name>. Elementare sind eine schwere Beute, aber Ihr seid dieser Aufgabe gewachsen. Habt Ihr die Armschienen der Bindung?", completion = "Ihr habt sie gefunden. Ich hoffe, dass die Elementare, von denen Ihr diese Schienen habt, auch einverstanden waren...\n\nHmm... es scheint, dass mit dem Tod nicht nur mein Herz aufhörte zu schlagen, auch mein komisches Talent ist dabei draufgegangen.\n\nIch danke Euch, &lt;Name&gt;. Ihr habt dem Magus einen guten Dienst erwiesen und damit auch der dunklen Fürstin.", rewards = "Ihr bekommt:\n\n"},
[558] = {title = "Jainas Autogramm", objective = "Reist nach Theramore und versucht für Euren Schützling ein Autogramm von Lady Jaina Proudmoore zu ergattern.", description = "Ich habe gehört, dass Lady Jaina Proudmoore aus Theramore eine der größten Heldinnen ist, die die Allianz je gesehen hat. Wenn ich mal groß bin, möchte ich auch ein Held der Allianz werden!\n\nKennst du Jaina, <Name>? Tust du mir einen gefallen? Kriege ich ein Autogramm von ihr? Ich weiß gar nicht, wie ich sie ansprechen soll, und wahrscheinlich ist sie sowieso viel zu beschäftigt, um mich zu beachten... aber was ist mit dir? Du bist doch genau wie sie ein Abenteurer! Dir gibt sie bestimmt ein Autogramm!\n\nBitte, <Name>. Bitte...", progress = "Eines Tages möchte ich ein Held wie Jaina sein!", completion = "WOW! Du hast wirklich ein Autogramm von Lady Jaina für mich bekommen! Vielen, vielen Dank! Und wow... das ist ja sogar eine persönliche Nachricht für mich drauf! Ich wusste doch, dass sie total cool ist und vielleicht kann ich ihr eines Tages selber danken... wenn ich auch ein Held der Allianz bin!\n\nDu bist einfach der Beste, &lt;Name&gt;. Danke, dass du dich so um mich kümmerst.", rewards = "Ihr bekommt:\n\n"},
[559] = {title = "Farrens Beweis", objective = "Sammelt 10 Murlocköpfe von den Murlocs am Weststrand für Lieutenant Farren Orinelle in Southshore.", description = "Was haltet Ihr davon, <Name>? Redpath war nicht zufrieden mit den ganzen Murlocs, die wir getötet haben - seid nur nicht so bescheiden, Ihr wart ja auch dran beteiligt. Jetzt verlangt er von mir, dass ich ihren Tod beweise und kalte, schleimige Murlocköpfe abhacke und sie ihm bringe, um seine Anerkennung zu erlangen.", progress = "Habt Ihr die Köpfe für mich besorgt, <Name>?", completion = "Oh liebes Licht... die tropfen ja auf den Boden.\n\nIch kann diese Dinger ja nicht anfassen. Fische, gut und schön, aber wenn sie Beine kriegen und herumlaufen... Hab seit Wochen keinen Fisch gegessen, und ich sag Euch, in Southshore heißt das, dass man nicht viel isst.", rewards = "Ihr bekommt:\n\n"},
[560] = {title = "Farrens Beweis", objective = "Bringt den Sack mit den Murlocköpfen zu Marshal Redpath nach Southshore.", description = "Wisst Ihr, <Name>, ich würde die Köpfe am liebsten gar nicht anfassen... Da Ihr sie nun schon mal angefasst habt, würde es Euch sehr viel ausmachen, sie zu Redpath zu bringen?", progress = "Seid gegrüßt, Bürger. Seid Ihr gekommen, um bei der Aufrechterhaltung der Sicherheit von Southshore behilflich zu sein?", completion = "Ihr seid Farrens Junge für alles, wie?\n\nWenn Ihr Farren beim Sammeln dieser Köpfe behilflich wart, dann vielen Dank. Southshore braucht eifrige Arbeiter und große Bemühungen um seinen Schutz aufrechtzuerhalten.", rewards = "Ihr bekommt:\n\n"},
[561] = {title = "Farrens Beweis", objective = "Sprecht mit Lieutenant Farren Orinelle in Southshore.", description = "Bitte informiert Lieuntenant Orinelle über meinen Wunsch, er möge seine Aufmerksamkeit erneut auf die Nagaplage am Oststrand richten. Sobald er Resultate erzielt hat, soll er persönlich bei mir Bericht erstatten.", progress = nil, completion = "Die Naga, wie? Redpath muss gerade dieselben Informationen erhalten haben wie ich... Ha! Er will 'ne Beförderung und ich darf mich dafür abrackern, kommt gar nicht in Frage. Lasst es mich erklären.", rewards = "Ihr bekommt:\n\n"},
[562] = {title = "Stormwind Ho!", objective = "Tötet 10 Küstenjäger der Säbelflossen und 10 Sirenen der Säbelflossen für Lieutenant Farren Orinelle in Southshore.", description = "Mein ehemaliger Mentor bei der Stadtwache von Stormwind hat mir eine Nachricht zukommen lassen, dass sich das Oberkommando der Allianz langsam Sorgen macht um die Bedrohung, die von den Naga ausgeht. Er hat gehört, dass es gute Aussichten auf eine Beförderung - oder zumindest Versetzung - für jeden gibt, der sich in dieser Angelegenheit als hilfreich erweist.\n\nEs gibt da nur ein winzigkleines Problem... Ich schaff die Naga nicht, <Name>. Klar, ich kann eine Kneipenschlägerei auflösen, oder einen aggressiven Bettler wegschaffen, aber die Naga sind einfach zu viel für mich. Ihr müsst mir helfen, <Name>!", progress = "Ich hab einen Brief fertig für Major Samuelson in Stormwind. Ich brauche nur noch die Ergebnisse.", completion = "Jetzt wo die Naga hier in Southshore erledigt sind, bin ich so gut wie weg hier. Ich werde Stormwind wiedersehen... und aus diesem Licht-verlassenen Hafen wegkommen.", rewards = "Ihr bekommt:\n\nFischausnehmer"},
[563] = {title = "Versetzungen", objective = "Bringt Farrens Bericht zu Major Samuelson in die Burg Stormwind.", description = "Es dürfte kein Problem sein, meinen Bericht zu beachten. Der neue Captain der Wachen, Major Samuelson, war mein Mentor, während ich in Stormwind stationiert war. Der Bericht sollte ihm mehr als genug Grund geben, mich wieder in die Stadt zu versetzen. Aber ich brauche Euch, damit Ihr meinen Bericht zu ihm bringt... der alte Redpath soll nichts davon mitkriegen.", progress = "Seid gegrüßt, Bürger. Kann die Stadtwache von Stormwind Euch behilflich sein?", completion = "Was ist das? Ah... da hat mein aufmerksamer Schüler sich wohl des Nagaproblems in Southshore angenommen. Ich danke Euch für das Überbringen, ich werde das auf jeden Fall berücksichtigen, wenn ich im nächsten Monat die Personalversetzungen überprüfe.", rewards = "Ihr bekommt:\n\n"},
[564] = {title = "Teure Bedrohung", objective = "Darren Malvew aus Southshore will, dass Ihr 8 Berglöwen und 10 titanische Berglöwen tötet.", description = "Nix macht mich wütender als wenn ich diese schönen Pferdchen verlieren tu. Und glaubt's mir, wir hab'n 'ne ganze Menge verloren, an die eklichen untoten Unholde, das verdammte Syndikatsgesocks und all die anderen tunichgute Schurken, die hier so rumlaufen tun.\n\nAber ich schwör beim Grab von mein alten Opa, 'ne größere Gefahr für uns're Pferdchen als die vonne Berglöwen in Alterac tut's nich' geben tun. Komm' alle Nase lang vonne Berge runner und machen mir dat Leben schwer.\n\nUnd Ihr seid also 'n Held? Dann geht mal und tut was dagegen unternehm' tun!", progress = nil, completion = "Na das sin' ma' gute Neuichkeiten! Hätt' ich mir gleich 'n richtichen Kriechshelden ranholen soll'n, der sich um die Viecher kümmern tut. Euer Pappa wär ja so stolz auf Euch, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchafhirten-GurtSchafhirten-Handschuhe\n\nIhr bekommt außerdem:\n\nRezept: Schmackhaftes LöwensteakSchmackhaftes Löwensteak"},
[565] = {title = "Bartolos Yetifellumhang", objective = "Bringt Bartolo Ginsetti in Southshore einen Wollstoffballen, einen Umhang des Hügelwächters, feinen Faden und 10 Haufen Yetifell.", description = "Ich, der große Bartolo, werde für Euch den weltberühmten, allianzweit bekannten Yetifellumhang anfertigen.\n\nIch wette mit Euch: Auch wenn Ihr die ganze Welt bereist, findet Ihr keinen besseren Umhang. Oh, wartet mal, was ist das, kleiner <Volk>? \"Bartolo, es gibt keinen feineren Umhang!\" Ja, ja! Das habe ich schon öfter gehört.\n\nBartolo benötigt einen Wollstoffballen, einen Umhang des Hügelwächters von einem geschickten Lederer, feinen Faden und natürlich Yetifell. Bringt mir diese Dinge und Ihr werdet ein glücklicher Kunde!", progress = "Ihr seid also zum großartigen Bartolo zurückgekehrt. Seid Ihr vielleicht schon fertig mit dem Sammeln der Dinge, die für Euren Yetifellumhang benötigt werden? Oder vielleicht möchtet Ihr Euch ein wenig an meiner Großartigkeit, der Großartigkeit des großen Bartolo sonnen!", completion = "Jetzt ist die Zeit für den großen Bartolo gekommen, seine Magie zu wirken! Ich brauche keinen Hexer-Stab und keine Magier-Rute! Denn ich, der große Bartolo, kann mit einer einfachen Nadel und Faden Magie wirken!", rewards = "Ihr bekommt:\n\nYetifell-Umhang"},
[566] = {title = "GESUCHT: Baron Vardus", objective = "Tötet Baron Vardus und bringt seinen Kopf zu Hochexekutorin Darthalia in Tarrens Mühle.", description = "Laut Befehl der Hochexekutorin Darthalia wird der unter dem Namen Baron Vardus bekannte Mensch wegen Verbrechen gegen die Verlassenen gesucht. Vardus ist bekannt als hochrangiges Mitglied der Organisation, die sich das Syndikat nennt.\n\nZuletzt wurde er im Oberland des Alteracgebirges im Norden von Tarrens Mühle gesehen.\n\nEr soll getötet werden. Für den Erhalt der Belohnung müssen Beweise seines Todes zu Hochexekutorin Darthalia gebracht werden.", progress = "Ah, <Name>. Seid Ihr vielleicht gekommen, um das Kopfgeld einzuholen, das auf den Kopf von Baron Vardus ausgesetzt wurde?", completion = "Ihr seid sehr produktiv, &lt;Name&gt;. Mit dem Tod von Baron Vardus sinkt auch die Zahl der Syndikatsanführer. Ihr Widerstand wird nur noch ein kurzlebiges Ärgernis sein.", rewards = "Ihr bekommt:\n\nInfernorobe"},
[567] = {title = "Gefährlich!", objective = "Hochexekutorin Darthalia in Tarrens Mühle hat ein Kopfgeld auf Amtmann Horrace Whitesteed, Bürger Wilkes, Minenarbeiter Hackett und Bäuerin Kalaba ausgesetzt.", description = "Gefährlich!\n\nDie folgenden Menschen aus Hillsbrad werden als gefährlich erachtet. Ein Kopfgeld ist von Hochexekutorin Darthalia auf sie ausgesetzt worden.\n\nAmtmann Horatio Whitesteed. Gesucht wegen Mordes an Todeswache Toma.\n\nBürger Wilkes. Gesucht wegen Mordes an Apotheker Eli.\n\nMinenarbeiter Hackett. Gesucht wegen Mordes an Todespirscher Fry.\n\nBäuerin Kalaba. Gesucht wegen hinterhältigem Überfall auf Vorräte von Undercity.\n\nJeder dieser Feinde hat sich versteckt und wird nur sehr schwer zu finden sein. Auf die Nachricht ihres Todes wird eine Belohnung gewährt.", progress = nil, completion = "Ihr seid ein sehr geschickter Kopfgeldjäger, &lt;Klasse&gt;. Gut gemacht.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPlünderbogenWachpostenrundschildVerkohlter Zauberstab\n\nIhr bekommt außerdem:\n\nKapuzenkutte"},
[568] = {title = "Die Verteidigung von Grom'gol", objective = "Kommandant Aggro'gosh vom Basislager von Grom'gol will, dass Ihr 15 Schmetterschwanzraptoren tötet.", description = "Throm-ka, <Klasse>!\n\nEure Ankunft in Grom'Gol kommt wahrlich zur rechten Zeit. Als Kommandant des Kriegshäuptlingsstützpunkts hier im Dschungel bin ich durch meine Ehre gebunden und verpflichtet, die Sicherheit aller Mitglieder der Horde zu gewährleisten. Unsere Aufgabe, eine sichere Versorgungskette nach Stonard zu gewährleisten wird durch einige der örtlichen Einwohner schwer behindert.\n\nIch gebe Euch den Auftrag, die Raptorpopulation außerhalb Grom'gols zu reduzieren. Sobald Ihr nennenswerte Fortschritt erzielt habt, erstattet mir Bericht und Ihr erhaltet einen neuen Auftrag.", progress = nil, completion = "Ihr habt Eure Pflicht ehrenhaft erfüllt, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"},
[569] = {title = "Die Verteidigung von Grom'gol", objective = "Kommandant Aggro'gosh vom Basislager von Grom'gol will, dass Ihr 10 Ogerschläger und 5 Ogerhexendoktoren tötet.", description = "Als wir in diesem Dschungel ankamen, hatten wir nicht vor, die hier ansässigen Stämme zu bekämpfen. Unsere Mission, Stonard zu versorgen, hat höchste Priorität. Aber es gibt Komplikationen. Eine hier ansässige Gruppe von Ogern hat die Ruinen von Mizjah im Südosten von Grom'gol besetzt. Trotz unserer Warnungen überfallen sie weiterhin unsere Nachschubkarawanen.\n\nIch beauftrage Euch hiermit, Euch mit diesen unkooperativen Ogern auseinander zu setzen.\n\nReist zu den Ruinen und versucht, sie aus diesem Gebiet zu vertreiben. Das sollte ihnen zumindest ein eindeutiges Zeichen setzen.", progress = nil, completion = "Gut gemacht. Ihr habt dem Kriegshäuptling ehrenhaft gedient.", rewards = "Ihr bekommt:\n\nRundschild von Grom'gol"},
[570] = {title = "Mok'Thardins Verzauberung", objective = "Scharfseher Mok'thardin im Basislager von Grom'gol will 8 Schattentatzenkrallen und einen makellosen Tigerinnenfangzahn.", description = "Die Macht der Dschungelmagie muss erkannt und kann dann von der Horde genutzt werden. Meine Rituale waren bislang erfolgreich. Ich kann sehr mächtige Verzauberungen wirken. Für Euch, mutiger <Klasse>, werde ich einen wirklich ganz besonderen Gegenstand herstellen.\n\nBringt mir einige Schattentatzenpantherkrallen und den Fangzahn einer Tigerin. Es darf aber nicht irgendein Fangzahn sein. Er muss sich in einem makellosen Zustand befinden.\n\nDiese Bestien lauern im gesamten Dschungel, aber Ihr könnt einige ganz in der Nähe finden. Überquert den Fluss von den Mizjah-Ruinen aus in südöstlicher Richtung.", progress = "Was für Neuigkeiten bringt Ihr mir?", completion = "Ihr habt eine sehr gute Kenntnis des Dschungels, &lt;Name&gt;. Diese Exemplare eignen sich perfekt. Ich werde den Geistern dafür danken, dass sie diese edlen Kreaturen für die Sache der Horde geopfert haben.", rewards = "Ihr bekommt:\n\n"},
[571] = {title = "Mok'Thardins Verzauberung", objective = "Bringt die Sehne eines alten Gorillas zu Scharfseher Mok'thardin nach Grom'gol.", description = "Was ich nun von Euch benötige, ist sehr schwer zu bekommen.\n\nIch benötige ein magisches Band, um all diese Federn, Krallen und den makellosen Fangzahn zu befestigen. Nur die Sehne eines alten Gorillas ist dazu geeignet.\n\nEine solche könnt Ihr nur von einem alten Nebeltalgorilla bekommen. Sie sind oft auf Nahrungssuche im Osten von Booty Bay.\n\nDie Sehne muss in vollkommenem Zustand sein. Ihr werdet wahrscheinlich mehrere Tiere töten müssen, bis Ihr genau das erhaltet, was ich benötige, aber das ist es in jedem Fall wert.", progress = "War das Glück auf Eurer Seite, <Name>? Konntet Ihr die Sehne eines alten Gorillas bekommen, <Name>?", completion = "Eine wirklich ideale Sehne, &lt;Name&gt;. Eure Bemühungen werden sich bald bezahlt machen.", rewards = "Ihr bekommt:\n\n"},
[572] = {title = "Mok'Thardins Verzauberung", objective = "Bringt 10 Dschungelpirscherfedern zu Scharfseher Mok'thardin nach Grom'gol.", description = "Die Dinge, die Ihr von den katzenartigen Bestien des Tales gesammelt habt, sind nur die erste Voraussetzung für einen machtvoll verzauberten Gegenstand. Diese Dschungelornamente, in Verbindung mit meinem Schamanenritual, werden Euch mit einem äußerst nützlichen Werkzeug versehen, mit dessen Hilfe Ihr der Horde und dem Kriegshäuptling beistehen könnt.\n\nAber jetzt müsst Ihr für mich einige Dschungelpirscherfedern sammeln. Für gewöhnlich tragen die Bestien diese Federn an ihren Armbändern. Ihr findet einen Stamm dieser Raptoren direkt südlich von Grom'gol, nicht weit von der großen Arena.", progress = "Sind Eure Bemühungen von Erfolg gekrönt?", completion = "Vorzüglich. Ich werde sie sofort vorbereiten.", rewards = "Ihr bekommt:\n\n"},
[573] = {title = "Mok'Thardins Verzauberung", objective = "Scharfseher Mok'thardin von Grom'gol benötigt Wasser der Heiligen Quelle. Er will auch, dass Ihr 10 Forscher der Naga tötet.", description = "Es fehlt nun nur noch ein Reagenz, um die Verzauberung zu vervollständigen.\n\nIm Süden, nahe der Westküste, liegt ein Heiliger Quell, hoch über den Steilhängen. Dieser Quell ist das Objekt großer Konflikte zwischen religiösen und mystischen Gelehrten. Jede einzelne Gruppe in Azeroth vertritt die Auffassung, dass das Quellwasser nur für das eigene Volk göttlich gemacht wurde.\n\nMeine letzte Aufgabe für Euch: Bringt mir Wasser der Heiligen Quelle. Aber ich warne Euch: Eine Expedition von Forschern der Naga ist auf dem Weg zu der Quelle. Mit ihnen müsst Ihr Euch ebenfalls befassen.", progress = "Ich bin fast so weit, die Verzauberung abzuschließen. Habt Ihr meinen Auftrag erfüllt?", completion = "Mit diesem heiligen Quellwasser ist der zeremonielle Halsschmuck bereit zur Verzauberung.\n\nTragt ihn mit Stolz, &lt;Name&gt;, im Namen des Kriegshäuptlings und zur Verteidigung der mächtigen Horde.", rewards = "Ihr bekommt:\n\nHalsschmuck des Hochschamanen"},
[574] = {title = "Spezialtruppe", objective = "Tötet 10 von Kurzens Kommandosoldaten und 6 von Kurzens Kopfschrumpfer.\n\nErstattet Bericht bei Lieutenant Doren im Rebellenlager.", description = "Nun, da viele von seinen regulären Truppen gefallen sind, müsst Ihr es mit seinen hochtrainierten Streitkräften aufnehmen. Wenn sie nicht in der Wildnis unsere Rebellensoldaten erschlagen, kann man sie tief innerhalb von Kurzens Truppenlager finden, in einer Höhle, die sie das Vorratslager nennen.\n\nIch kenne einige von Kurzens Truppen persönlich und weiß, dass sie geschickt, loyal und grausam sind. Dies ist keine einfache Aufgabe, mit der ich Euch betraue, <Name>.\n\nNachdem Ihr sie besiegt habt, meldet Euch bei Lieutenant Doren, meinem befehlshabenden Offizier. Er wird Euren Bericht aus erster Hand haben wollen.", progress = "Sergeant Yohwa sagte mir, dass Ihr geschickt und mutig seid, <Klasse>. Habt Ihr etwas zu berichten?", completion = "&lt;Name&gt;. Sergeant Yohwa vertraute Euren Fähigkeiten, und ich vertraue ihr. Die Niederlage, die Ihr Kurzens Streitkräften beigebracht habt, ist fast mehr als wir zu hoffen wagten. Ich hatte befürchtet, dass wir Rebellen allein stünden, und allein hätten wir es nie mit der Genialität des Colonels aufnehmen können.\n\nVielleicht können wir immer noch auf unser Überleben hoffen.", rewards = "Ihr bekommt:\n\n"},
[575] = {title = "Angebot und Nachfrage", objective = "Bringt 2 große Flusskrokiliskenhäute zu Drizzlik nach Booty Bay.", description = "Der beste Ledermacher der südlichen Meere und der Alten wie der Neuen Welt. So nennen sie mich. Mich! Drizzlik! Der beste Le... ähem. Nun ja.\n\nMeine Lederwaren sind nah und fern als absolut vorzüglich bekannt, erste Wahl der wahren Kenner!\n\nGerade habe ich eine Bestellung von Direktor Riddlevox vom Tüftlerverband über ein Dutzend seiner Lieblingsstiefel aus der Exzelsiorlinie erhalten. Unsere Verkaufsschlager, ehrlich gesagt.\n\nFür die Grundform benötige ich Krokiliskenhäute von den Kroks entlang des Flusses im Norden des Schlingendorntals.", progress = "Meine Ausrüstung ist startklar, <Name>, ich warte nur noch auf die Häute. Wir wollen Riddlevox ja nicht warten lassen.\n\nEs ist für niemanden gut, wenn der Cheferfinder des Tüftlerverbands unzufrieden ist.", completion = "Diese Häute sollen genügen. Ihre Qualität ist nicht allzu wichtig, da sie ja nur die innere Schicht der Stiefel bilden, aber sie sollten schon bequem sein.\n\nWenn sie ein bisschen zu steif sind, verwende ich ein wenig Tigerblut, um sie aufzuweichen. Kleines Betriebsgeheimnis, wisst Ihr?", rewards = "Ihr bekommt:\n\n"},
[576] = {title = "Ein Auge offen halten", objective = "Dizzy One-Eye in Booty Bay möchte, dass Ihr sein Auge von den Blutsegelbukanieren zurückholt.", description = "Haltet ein! Wer da?\n\nGrrr, ich bin so gut wie nutzlos ohne mein verzaubertes Spezialauge. Als ob es nich' schon schlimm genug is', dass ich meine Augen im Kampf verlor'n hab! Aber zum Glück haben wir in Menethil angelegt und ein reisender Hexer hat 'n Spezial-Glasauge verzaubert, mit dem ich wieder was sehen kann.\n\nGestern Nacht hab'n mir aber 'n paar von den Blutsegelbukanier'n auf'm Weg nach Haus aufgelauert. Die ham mir doch echt mein Auge geklaut! Scheint, als hätt'n die Burschen Booty Bay gefunden.\n\nKönnt'er 'nem alten Seebären helfen und mir mein Auge zurückholen?", progress = "Ahoi, Kumpel! Kann zwar nich' sehen, aber kann Euch schon über'n halben Hafen hinwech riechen.\n\nKönnte mein Auge wirklich gut gebrauchen. D'r Käpt'n wird mich wohl kielholen, wenn er rausfindet, dass mein Glubscher in die Hände der dreckigen Blutsegelbukaniere gefallen is'.\n\nWozu is'n Ausguck gut, wenn er nix sieht? Das Krähennest war mein Zuhause... ohne meine Augen kann ich von Glück sagen, wenn ich die Bilge schrubbn darf.", completion = "Da brat mir doch einer 'nen Storch! Ihr habt mein wunderbares Auge gefunden! Lass uns mal gucken, ob's noch passt.\n\n&lt;Name&gt; ho! Kinners, ich kann sehen!!", rewards = "Ihr bekommt:\n\nCape der dunklen Wogen"},
[577] = {title = "Etwas Zusammenbau benötigt", objective = "Bringt 5 Schnappkieferkrokiliskenhäute zu Drizzlik nach Booty Bay.", description = "Nun, ich habe die Grundform der Stiefel so weit und sie werden auch sehr gut, aber die Häute, die Ihr mir brachtet, werden leider nicht für die inneren Schichten ausreichen.\n\n\"Was sollen wir tun, Drizzlik?\" Diese Frage brennt Euch zweifelsohne auf den Lippen, und Ihr habt wirklich Glück, dass Ihr mit Drizzlik sprecht, denn er wird Euch genauestens erklären, was wir zu tun gedenken!\n\nDie inneren Schichten sieht sowieso nie jemand, also werden wir uns zum Ausfüllen der Stiefel einige der billigeren, dickeren Häute der Krokos holen, die um den Nazferitisee leben.", progress = "Drizzliks Exzelsiorlederstiefel, feinste Handwerksarbeit, Stiefel aus 100 Prozent Salzwasserkrokiliskenhaut von höchster Qualität. Es gibt nichts Besseres!\n\nSo eine tolle Beschreibung sucht ihresgleichen, was?\n\nOder habt Ihr vielleicht schon diese Häute für mich?", completion = "Meine Stiefel... sie sind 'n bisschen wie Würstchen, &lt;Name&gt;. Sehen gut aus und schmecken auch so. Ich sag Euch, dass sie mit dem allerbesten Fleisch und feinsten Zutaten gefüllt sind und Ihr esst sie und Ihr liebt sie.\n\nEs ist sicherer - und schmackhafter -, wenn Ihr mir einfach nur traut und nicht allzu viele Fragen stellt, was wirklich drin ist.", rewards = "Ihr bekommt:\n\n"},
[578] = {title = "Der Stein der Gezeiten", objective = "Findet die Spukinsel für Baron Revilgaz in Booty Bay.", description = "Wenn es wirklich einen Goblinmagier und Wasserelementare gibt, die auf dieser Insel ihr Unwesen treiben, dann heißt das, dass der Stein der Gezeiten wirklich mir gehören kann!\n\nIch will, dass Ihr diese Spukinsel findet und herausfindet, wie es dort zugeht. Oh, und falls Ihr mehr über den Stein der Gezeiten herausfinden wollt, bringt diesen Schein zur Bibliothek von Stormwind, sie sollten dort ein Exemplar des Buches für Euch finden, in dem ich zuerst von der Legende gelesen habe.\n\nSollte es möglich sein, dass Gazban wirklich den Stein gefunden hat...?", progress = nil, completion = "Also waren die Geschichten wirklich wahr! Unglaublich!\n\nAllerdings werden wir uns einen Weg überlegen müssen, wie wir den Fluch des Steins der Gezeiten besiegen können, sollten wir ihn bergen können. Der Fluch ist was für Magiebewanderte, also muss einer dieser Hexer uns behilflich sein.", rewards = "Ihr bekommt:\n\n"},
[579] = {title = "Bibliothek von Stormwind", objective = "König Anduin betrachtet Lernen als sehr wichtig und hat daher Geld zur Verfügung gestellt, damit verschiedene Folianten und Schriften kopiert und für die Öffentlichkeit zugänglich gemacht werden können. Es ist ganz einfach. Ihr bringt mir einen Bibliotheksschein, und ich gebe Euch ein Exemplar eines der verfügbaren Bücher.", description = nil, progress = "König Anduin betrachtet Lernen als sehr wichtig und hat daher Geld zur Verfügung gestellt, damit verschiedene Folianten und Schriften kopiert und für die Öffentlichkeit zugänglich gemacht werden können. Es ist ganz einfach. Ihr bringt mir einen Bibliotheksschein, und ich gebe Euch ein Exemplar eines der verfügbaren Bücher.", completion = "Interessiert Euch einer dieser Titel, &lt;Name&gt;?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDie Geschichte von Morgan LadimoreLegenden der Gurubashi, Band 3"},
[580] = {title = "Whiskey Slim's verlorener Grog", objective = "Whiskey Slim in Booty Bay möchte, dass Ihr ihm die Flaschen Pupellyverbos-Portwein bringt, die er verloren hat.", description = "Wir waren dabei, uns tüchtig einen hinter die Binde zu gießen, konnten 's Hinterland schon sehen. Dachten schon, die See wollte uns ganz und gar verschlingen.\n\nOl' Slim weiß alles über flüssigen Mut! Der Käpt'n hatte eine Kiste mit Pupellyverbos-Portwein, den wir auf'm Weg nach Stormwind von 'nem Freibeuter geholt hatten.\n\nAls der Sturm uns dann vom Hinterland aus getroffen hat, bin ich also in den Grog rein. Große Welle kam und hat die Flaschen über Bord gespült. Der Käpt'n wird mich bestimmt mit der Katze streicheln, wenn Ihr mir nich' helft, die wieder zurückzubringen!", progress = "So ein Mist! Ich hab schon fast nix mehr zum Saufen da! Der Käpt'n wird bald Anker werfen und Ol' Slim is' trocken wie die Tanariswüste. Und wenn er dann merkt, dass sein Portwein verschwunden is'... Schietkram!", completion = "Nee, isses denn wahr! Ihr habt den Grog vom Käpt'n gefunden!\n\nIch schuld' Euch was, aber wirklich!\n\nSieht aus, als würd' sich ein Sturm zusammenbrau'n da draußen. Vielleicht mach ich's mir einfach hier drin mit einer der Flaschen gemütlich und warte, bis er vorbeigezogen is ...", rewards = "Ihr bekommt:\n\nRumsey-Rum"},
[581] = {title = "Die Suche nach Yenniku", objective = "Bringt 9 Hauer der Bloodscalp zu Nimboya in das Basislager von Grom'gol.", description = "Unheil droht. Unheil für den jüngsten Sohn meines Häuptlings, Yenniku. Der Sitte unseres Volkes nach wurde er den Gurubashitrollen von Zul'Gurub gegeben, aber nachdem mein Stamm, der Darkspearstamm, mit dem Orc Thrall gegangen ist, war der arme Yenniku für uns verloren. Ich wurde aus dem fernen Orgrimmar zurück ins Schlingendorntal geschickt, um nach dem Sohn meines Häuptlings zu suchen.\n\nUnd ich glaube, dass der Bloodscalpstamm ihn hat.\n\nWenn Ihr mir helfen wollt, dann jagt die Bloodscalps. Ihr könnt sie im Norden finden. Sammelt ihre Hauer und kehrt zu mir zurück.", progress = "<Klasse>. Zeigt mir, dass Ihr Beute von dem Bloodscalpstamm gemacht habt.\n\nZeigt mir Eure Trophäen.", completion = "Das sind gute Hauer, &lt;Name&gt;. Ihr habt bewiesen, dass Ihr stark genug seid, um die Bloodscalps zu jagen.\n\nDas ist gut, denn die Jagd auf sie ist für Euch noch nicht vorbei.", rewards = "Ihr bekommt:\n\n"},
[582] = {title = "Kopfjägerei", objective = "Bringt 20 Schrumpfköpfe zu Nimboya in das Basislager von Grom'gol.", description = "Wir müssen herausfinden, ob Yenniku tot ist.\n\nErschlagt die Kopfjäger der Bloodscalp und nehmt ihnen ihre Schrumpfköpfe ab. Ihr müsst viele, viele Köpfe sammeln und ich werde sie überprüfen, um sicherzugehen, dass Yennikus Kopf nicht dabei ist.\n\nSollte Yenniku von den Bloodscalps getötet worden sein, möge ein Fluch für 600 Jahre auf den Geist ihres Häuptlings, Gan'zulah, kommen!\n\nGeh, <Name>. Viele Kopfjäger könnt Ihr bei den Ruinen von Zuuldaia und Zul'Kunda an der Küste im Norden finden.", progress = "<Name>. Ich fürchte um den Sohn unseres Häuptlings. Habt Ihr die Schrumpfköpfe, sodass ich sie untersuchen kann?", completion = "Ich danke Euch, &lt;Name&gt;. Ich werde sie sogleich untersuchen, um sicherzugehen, dass der arme Yenniku der Axt der Kopfjäger entgangen ist.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nManschetten der DarkspearArmsplinte der Darkspear\n\nIhr bekommt außerdem:\n\n"},
[583] = {title = "Willkommen im Dschungel", objective = "Sprecht mit Hemet Nesingwary.", description = "Willkommen im Schlingendorntal!\n\nIhr seid es Euch vielleicht nicht bewusst, aber der Zwerg dort drüben ist der wunderbare Hemet Nesingwary, weitbekannter Kriegsheld der Allianz und Meistergroßwildjäger. Er ist nicht gerade sehr bekannt dafür, dass er Fremde in seinem Lager sehr mag, aber Ihr seht aus, als hättet Ihr schon das eine oder andere Abenteuer erlebt, <Klasse>.\n\nDa er selbst ein erfahrener Kriegsveteran ist, hat Meister Nesingwary eine Schwäche für andere Helden.\n\nGeht und sprecht mit ihm. Vielleicht kann er Euch einige Ratschläge für die Jagd mitgeben.", progress = nil, completion = "Sehr erfreut Eure Bekanntschaft zu machen, &lt;Name&gt;. Hab hier in der Gegend schon lange keinen Eurer Sorte mehr gesehen, &lt;Klasse&gt;.\n\nIch habe mich nur aus einem Grund auf diese Expedition begeben: Ich will eine große und scheue Bestie jagen. Da ich erkennen kann, dass Ihr eine Art Held seid, bin ich willens, Euch an der Jagd zu beteiligen. Ihr müsst Euch zunächst jedoch beweisen.\n\nIch werde Euch lehren, wie man Raptoren tötet. Ajeck wird Euch mit der Tigerjagd vertraut machen. Und Sire Erlgadin ist ein Meister, wenn es um das Aufspüren eines Panthers geht.\n\nBeweist mir Eure Geschicklichkeit und Ihr dürft mit auf die große Jagd.", rewards = "Ihr bekommt:\n\n"},
[584] = {title = "Köpfe des Bloodscalpklans", objective = "Bringt Gan'zulahs Kopf und Nezzlioks Kopf zum blubbernden Kessel im Basislager von Grom'gol.", description = "Yenniku war nicht unter den Köpfen, der Großen Schlange sei Dank. Aber wir sind noch weit entfernt davon, ihn zu finden.\n\nWir müssen die Wahrheit herausfinden, und ich fürchte, dass nur der Häuptling der Bloodscalp und sein Hexendoktor sie kennen. Sie sind Feinde des Darkspearstammes und werden nicht freiwillig reden, also müssen wir die Wahrheit von ihren toten Lippen erzwingen!\n\nBringt mir die Köpfe von Gan'zulah und Nezzliok dem Düsteren und legt sie in diesen Kessel.\n\nSie halten sich in den Tiefen von Zul'Kunda auf. Bringt ihre Köpfe... wir werden sie schon zum Sprechen bringen.", progress = "Die grünliche Brühe im Kessel blubbert.", completion = "Ihr legt die Köpfe von Gan'zulah und Nezzliok in den Kessel...", rewards = "Ihr bekommt:\n\n"},
[585] = {title = "Mit Nezzliok sprechen", objective = "Bringt eine Balia'mah-Trophäe, eine Ziata'jai-Trophäe und eine Zul'Mamwe-Trophäe zum blubbernden Kessel im Basislager von Grom'gol.", description = "<Der Kopf von Nezzliok spricht.>\n\nEs stimmt. Ich weiß, wo das Kind der Darkspears hingebracht wurde. Ihr habt mich besiegt und meinen Geist gebunden, aber ohne Gegenleistung sage ich nichts!\n\nDie Bloodscalps streiten mit den Skullsplitters. Um mein Wohlwollen zu erhalten, stehlt 3 der Trophäenschädel von den Skullsplittern und legt sie hierher zu uns, sodass mein Geist im Nether Sklaven zur Verfügung hat. Ein Schädel muss aus ihrem Trophäenstapel in Balia'mah, der zweite von Ziata'jai und der dritte von Zul'Mamwe stammen.", progress = "Ich erwarte die Schädel...", completion = "Ja. Diese werden mir gute Dienste leisten. Wenn mein Geist befreit wurde, werde ich mit drei guten Dienern in das Nether eintreten!\n\nIhr seid eine Zierde Eures Klans, &lt;Volk&gt;, und Ihr habt mich beschwichtigt.", rewards = "Ihr bekommt:\n\n"},
[586] = {title = "Mit Gan'zulah sprechen", objective = "Tötet 8 Jäger der Skullsplitter, 6 Kopfjäger der Skullsplitter und 4 Berserker der Skullsplitter.\n\nBringt die zerbrochene Rüstung von Ana'thek zum blubbernden Kessel in das Basislager von Grom'gol.", description = "<Der Kopf von Gan'zulah spricht.>\n\nVerflucht seid Ihr! Und auch Eure Vorfahren!\n\nNur Blut und Rache können meine Wut beschwichtigen; wenn das Euer Wunsch ist, dann... tut Folgendes:\n\nWerft Euch in das Herz der Skullsplitter im Osten. Erschlagt die schrecklichsten unter ihnen, und wenn Ihr überleben solltet... dann tretet gegen ihren Häuptling, Ana'thek den Grausamen, an. Ha! Bringt mir seine zerschmetterte Rüstung, wenn Ihr es vermögt!\n\nMöge er Eure Glieder ausreißen und Euch der Fäulnis ausliefern und den Geiern zum Fraß vorwerfen.", progress = "Obwohl mein eigenes Fleisch von meinem Schädel fällt, kann ich Eure Furcht immer noch riechen.\n\nHa! Ihr werdet meine Aufgabe niemals erfüllen...", completion = "Ich will es nicht glauben, aber ich kann Eure Tat nicht verleugnen. Und meine Wut lässt nach, nun, da Ana'thek besiegt ist. \n\nEure Macht wird Euch zu großen Taten treiben, &lt;Name&gt;. Aber eines Tages... werde ich Euch im Nether wiedersehen und wir werden erneut unsere Kräfte messen.\n\nIch werde Euch erwarten.", rewards = "Ihr bekommt:\n\n"},
[587] = {title = "Auf dem Schnupftabak", objective = "Deeg in Booty Bay möchte, dass Ihr ihm 15 Teile Schnupftabak bringt.", description = "Ah, das Leben auf See. Ich sag nicht, dass es das wahre Leben ist, aber es ist mein Leben.\n\nWenn ich in den Hafen komme, such ich mir eine gute Flasche Grog und sehr guten Schnupftabak. Schlechte Angewohnheiten, ich weiß, aber irgendein Laster muss'n Pirat ja nun mal haben , nich?\n\nAlso könnt Ihr Euch vielleicht vorstellen, wie niedergeschlagen ich war, als ich herausfand, dass der Kräuterkundige nichts von dem Zeug mehr da hatte. Erzählte mir, dass seine Lieferung von den verdammten Räubern der Blutsegelbukaniere geklaut worden ist.\n\nIch wette, ein furchtloser <Klasse> wie Ihr könnte sie überreden, die Ware zu teilen, nich?", progress = "Glück mit den Waren, Kumpel?", completion = "Klasse gemacht, &lt;Name&gt;! Und gerade noch rechtzeitig, bevor ich wieder Anker lichten muss! Kann Euch gar nicht genug danken, alter Freund.", rewards = "Ihr bekommt:\n\n"},
[588] = {title = "Yennikus Schicksal", objective = "Sprecht mit Kin'weelay.", description = "<Nezzliok spricht>\n\nIhr habt mich und meinen Häuptling beschwichtigt, also werde ich Euch verraten, was Ihr zu wissen wünscht...\n\nDer junge Yenniku ist für seinen Klan verloren.\n\nEr wurde von dem Hexendoktor Zanzil, dem Ausgestoßenen, verschleppt. Sein Körper und sein Geist werden jetzt durch Zanzil kontrolliert und nur eine mächtige Magie kann ihn wieder befreien.\n\nEine Magie, über die Ihr nicht verfügt, <Klasse>.\n\nMöglicherweise können Eure Verbündeten bei den Darkspear Euch etwas Hoffnung auf Yennikus Rettung bieten. Aber dies bezweifle ich.", progress = nil, completion = "Zanzil der Ausgestoßene??\n\nWenn Yenniku von diesem Troll festgehalten wird, einem bösartigen und mächtigen Hexendoktor, dann fürchte ich, dass nur ein kleines bisschen Hoffnung bleibt. Eine schwache Hoffnung. Ungefähr so groß wie ein winziges Insekt.\n\nAber es ist immer noch eine Hoffnung.", rewards = "Ihr bekommt:\n\n"},
[589] = {title = "Die singenden Kristalle", objective = "Bringt 3 pulsierende blaue Splitter zu Kin'weelay in das Basislager von Grom'gol.", description = "Die Legenden berichten von einem Juwel, das tief im Herzen des Schlingendorntals versteckt liegt. Wir nennen es das Gedankenauge. Es verfügt über große Macht. Wenn Ihr dieses Auge finden könnt, dann können wir es vielleicht nutzen, um den verlorenen Yenniku aus der Dunkelheit zurückzubringen.\n\nIch werde mit den Geistern des Dschungels beraten, um das Gedankenauge zu finden. Während ich das tue, geht Ihr in die Kristalladermine, die sich südöstlich von hier befindet, und sammelt pulsierende blaue Splitter von den Eisenkieferbasilisken. Die Splitter gibt es nur sehr selten, aber wir benötigen ihre Magie, um das Gedankenauge unserem Willen zu unterwerfen.", progress = "Habt Ihr die Splitter, <Name>? Ich brauche sie für mein letztes Ritual, nachdem wir das Gedankenauge erhalten haben.", completion = "Ihr habt Eure Sache gut gemacht, &lt;Name&gt;. Diese Splitter haben eine gute Form. Ich kann bereits hören, wie sie zu mir singen.\n\nUnd während Ihr fort wart, sprach ich mit den Geistern des Dschungels. Ich weiß, wo sich das Gedankenauge befindet...\n\n... und auch, wer es bewacht.", rewards = "Ihr bekommt:\n\n"},
[590] = {title = "Ein Schurkenhandel", objective = "Besiegt Calvin Montague in Deathknell.", description = "Was?\n\nWas?!\n\nIhr wollt Geld? Ich schulde Euch kein Geld.\n\nBrief? Was für ein Brief? Oh, Ihr wollt also kämpfen? Nun, gut Kumpel... dann lasst uns anfangen! Schulde Euch Geld...", progress = nil, completion = "Unglaublich! Was für ein Talent!\n\nIch dachte, Ihr wärt eine leichte Beute, &lt;Name&gt;. Habt mich gut geschlagen.\n\nHier das Geld, das ich versprochen habe... nicht so viel, wie ich eigentlich sagte. Das kommt daher, dass ich damals schon gelogen hab.", rewards = "Ihr bekommt:\n\n"},
[591] = {title = "Das Gedankenauge", objective = "Bringt das Gedankenauge zu Kin'weelay in das Basislager von Grom'gol.", description = "Das Gedankenauge befindet sich bei einem Ogermagier, in den Tiefen des Ogerhügels der Mosh'Ogg östlich von hier. Sein Name ist Mai'Zoth. Ich kenne ihn noch von der Zeit, als sich die Darkspears im Schlingendorntal aufhielten - er ist bösartig und seine Magie ist stark.\n\nUnd wenn er im Besitz des Gedankenauges ist, dann ist seine Magie noch stärker.\n\nIhr müsst gegen Mai'Zoth antreten und ihm das Gedankenauge abnehmen. Es ist eine gefährliche Aufgabe, aber es ist die einzige Hoffnung, die wir haben, Yenniku zu retten.", progress = "Seid gegrüßt, <Name>. Die Geister lobpreisen Euren Mut, aber sie sagen mir nichts von Eurem Kampf gegen Mai'Zoth.\n\nHabt Ihr das Auge?", completion = "Ihr habt das Auge bekommen! Eure Macht hat das Zeug zur Legende, &lt;Name&gt;!\n\nUnd da Ihr im Besitz des Auges seid, müsst Ihr Mai'Zoth besiegt und ihn ins Nether geschickt haben. Darum wollten die Geister zuvor nicht von ihm sprechen.\n\nEs ist gut, dass er diese Welt des Fleisches und der Knochen verlassen hat, aber nun, da er im Reich der Geister wandelt... fürchte ich, wird er dort erneut die Macht ergreifen.\n\nAber darum sorge ich mich ein anderes Mal. Jetzt muss ich erst ein Ritual durchführen, um uns das Gedankenauge zu Willen zu machen...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[592] = {title = "Yennikus Rettung", objective = "Bringt den gefüllten Seelenedelstein zu Nimboya.", description = "Ich habe das Gedankenauge in einen Seelenedelstein umgeformt. Somit hat er zweierlei Zwecke: Erst verwendet Ihr ihn, um Yenniku zu betäuben, und sobald er betäubt ist, legt Ihr den Seelenedelstein auf seinen Kopf, um seine Seele einzufangen.\n\nDann bringt Ihr den Edelstein zu Nimboya.\n\nYenniku ist bei Zanzil dem Ausgestoßenen, in den Ruinen von Aboraz, entlang des Kristallufers am fernen Kap des Schlingendorntals.", progress = "<Name>. Kin'weelay sagte mir, er habe Euch ausgesandt, Yenniku zu finden.\n\nIst es wahr? Habt Ihr ihn?", completion = "Ihr habt es geschafft! Ihr konntet Yenniku vom Willen Zanzils trennen und so die Mission erfüllen, die ich kurz vorm Scheitern sah.\n\nUnser Stamm wird Euren Namen in Liedern ehren, &lt;Name&gt;, und wir werden Eure Geschichte in Stein ritzen, so dass sie auf ewig leben wird.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nNimboyas mystischer StabMedaille des Mutes\n\nIhr bekommt außerdem:\n\n"},
[593] = {title = "Den Seelenedelstein füllen", objective = "Yenniku steht betäubt vor Euch, sein Geist an einem anderen Ort...", description = nil, progress = "Yenniku steht betäubt vor Euch, sein Geist an einem anderen Ort...", completion = "Ihr legt den Seelenedelstein auf seine Stirn. Er erzittert, als seine Seele eingesaugt und sein Körper als hirnlose Hülle leer hinterlassen wird.", rewards = "Ihr bekommt:\n\nGefüllter Seelenedelstein"},
[594] = {title = "Flaschenpost", objective = "Findet den Schreiber dieser Flaschenpost.", description = "In der Notiz steht Folgendes in recht guter Handschrift:\n\nAn alle, die mir helfen können:\n\nBitte, ich benötige dringend Hilfe. Ein großer Blaumähnengorilla hält mich auf einer Insel in den südlichen Meeren gefangen.\n\nDie Sternbilder am Nachthimmel sind mir nicht vertraut und von Dschungelbäumen verdeckt, aber an klaren Tagen kann ich die wilden Ufer im Nordwesten erkennen und im Südwesten etwas, das große Segelschiffe sein könnten.\n\nIch flehe Euch an, mein möglicher Retter, bitte helft mir.", progress = nil, completion = "Seid Ihr gekommen, mich zu befreien?", rewards = "Ihr bekommt:\n\n"},
[595] = {title = "Die Blutsegelbukaniere", objective = "Erster Maat Crazz will, dass Ihr die Bucht nördlich von Booty Bay überprüft.", description = "Ihr scheint ja sehr erpicht auf Arbeit zu sein, Kumpel. Bin nicht sicher, warum eine Landratte wie Ihr, <Volk>, und ein <Klasse> noch dazu, den Schwarzmeerräubern Hilfe anbietet, aber ich werd Euch nicht fortschicken.\n\nUnser Schiff hat gerade hier in Booty Bay angedockt und es heißt, dass unsere Rivalen - diese verdammten, dreckigen Blutsegelbukaniere - sich im gesamten Süden des Schlingendorntals herumtreiben.\n\nMeine Jungs sind aber zu beschäftigt, sich einen anzusaufen und Mädchen nachzugaffen! Was ich brauch, ist ein Späher.\n\nBegebt Euch zur Bucht im Norden von Booty Bay an der ungezähmten Küste und schaut, was Ihr so findet.", progress = nil, completion = "Oben auf dem Fass findet Ihr eine Karte mit einigen hastig geschriebenen Worten und einigen Münzen.", rewards = "Ihr bekommt:\n\n"},
[596] = {title = "Blutige Knochenhalskette", objective = "Bringt 25 blutige Knochenhalsketten zu Kin'weelay in das Basislager von Grom'gol.", description = "Ich wurde nach Grom'gol geschickt, um Nimboya auf seiner Suche zu begleiten, aber... Ich habe meine eigenen Gründe, hier zu sein.\n\nDer Bloodscalpstamm ist der Feind unseres Stammes. Wenn wir Trophäen unserer Feinde sammeln, erhalten wir Macht über sie. Ihr könnt unserem Stamm behilflich sein, indem Ihr unsere Feinde jagt.\n\nSie leben im Norden. Erschlagt die Trolle der Bloodscalp und nehmt ihre blutigen Knochenhalsketten mit. Wenn Ihr viele davon sammelt, wird Eure Belohnung groß sein.", progress = "Eines Tages werden die Bloodscalps von den Darkspears zertreten werden! Habt Ihr die Halsketten unseres verdammten Feindes?", completion = "Ah, sehr gut. Ich werde sie kochen und absaugen und der Geist ihrer Besitzer wird immer schwächer werden, während ich ihre Halsketten zu Brei zermalme!\n\nHier, &lt;Name&gt;. Dies begleicht meine Schuld bei Euch.", rewards = "Ihr bekommt:\n\nBlutknochenband"},
[597] = {title = "Die Blutsegelbukaniere", objective = "Berichtet dem ersten Maat Crazz in Booty Bay von Euren Funden.", description = "Die Karte zeigt Booty Bay mit einem roten \"X\" genau an dem Punkt, wo Ihr gerade steht.\n\nDer hingekritzelte Text lautet:\n\n\"Leute, errichtet ein Lager an dieser Stelle und verhaltet euch schön unauffällig. Wartet auf das Signal vom südlichen Kommandoposten, bevor ihr angreift. Wenn sich jemand euch nähert, tötet ihr ihn.\"", progress = nil, completion = "Natürlich erinnere ich mich an Euch, &lt;Klasse&gt;. Zurück vom Ausspähen, wie ich sehe...", rewards = "Ihr bekommt:\n\n"},
[598] = {title = "Spaltknochenhalskette", objective = "Bringt 25 Spaltknochenhalsketten zu Kin'weelay in das Basislager von Grom'gol.", description = "Nun, da Ihr Bloodskalp-Trophäen gesammelt habt, habe ich eine weitere Aufgabe für Euch. Der Skullsplitterstamm der Trolle lebt im Südwesten und wir bekämpfen sie schon seit Jahren. Obwohl keine Darkspears mehr im Schlingendorntal leben, sind wir immer noch dem Konflikt mit den Skullsplittern verpflichtet.\n\nAlso, jagt sie. Sammelt ihre Spaltknochenhalsketten und kehrt zu mir zurück. Helft uns in unserem Krieg und Ihr werdet die Freundschaft der Darkspears erlangen.", progress = "Die Skullsplitter werden den Tag verdammen, an dem sie uns den Krieg erklärten! Ist Eure Aufgabe erfüllt?", completion = "Eure Stärke muss groß sein, dass Ihr diese Halsketten erringen konntet, &lt;Name&gt;. Ihr vernichtet die Skullsplitter wie ein Basilisk, der junge Schösslinge in den Boden tritt!\n\nEure Taten sind uns ein Segen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchuhe der DarkspearStiefel der Darkspear\n\nIhr bekommt außerdem:\n\n"},
[599] = {title = "Die Blutsegelbukaniere", objective = "Erstattet Flottenmeister Seehorn Bericht über den geplanten Angriff der Blutsegelbukaniere.", description = "Neee, isses denn wahr! Also planen die Blutsegelbukaniere einen Angriff auf Booty Bay? Diese Schurken haben vielleicht Nerven. Booty Bay wird immer von den Schwarzmeerräubern beherrscht werden!\n\nDas ist ein größeres Unterfangen als ich dachte. Erstattet Flottenmeister Seehorn sofort Bericht über alles, was Ihr erfahren habt! Der alte Seebär ist irgendwo in der Stadt...", progress = nil, completion = "Blutsegelbukaniere wollen Booty Bay angreifen? Da können sie sich doch gleich die Aussichtsklippen runterstürzen. Aber egal, Ihr habt meiner Flotte von Schwadroneuren einen großen Dienst erwiesen, indem Ihr mir diese Information zugetragen habt. Die Schwarzmeerräuber danken Euch.", rewards = "Ihr bekommt:\n\n"},
[600] = {title = "Venture Company-Bergbau", objective = "Bringt 10 singende blaue Kristalle zu Crank Fizzlebub nach Booty Bay.", description = "Die Venture Company hat ein paar Sachen im Schlingendorntal am Laufen, die hart arbeitende Goblins, wie ich es einer bin, davon abhalten, ehrliches Gold zu verdienen. Bitte, Ihr müsst mir helfen!\n\nDie Venture Company betreibt einen Stollen in der Nähe der Kristalladermine im Norden. Sie kommen nicht in die Mine hinein wegen der ganzen Basilisken, aber trotzdem sind sie in der Lage, singende Kristalle aus den umgebenden Hügeln herauszugraben.\n\nNehmt ihnen die Kristalle ab und zeigt ihnen, dass sie im Dschungel nichts zu melden haben.\n\nUnd... ähm... bringt mir diese Kristalle als Beweis!", progress = "Habt Ihr diese Kristalle?? Ich brauche sie!!\n\nIch meine... ich brauche Gewissheit, dass die böse Venture Company im Schlingendorntal an Boden verliert. Weil, wisst Ihr, wir ehrlichen Leute müssen auch leben!", completion = "Großartig! Wunderbar! Dafür krieg ich einen Haufen!\n\nDie Venture Company hat sich den falschen Dschungel für die Minen ausgesucht, nicht wahr? Es würde uns allen besser gehen, wenn sie hier verschwänden.\n\nIch danke Euch, &lt;Name&gt;. Ihr habt heute eine gute Tat getan.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGoblin-AnzünderSilberspaten\n\nIhr bekommt außerdem:\n\n"},
[601] = {title = "Wasserelementare", objective = "Holt 6 Wasserelementararmschienen für Baron Revilgaz in Booty Bay.", description = "Die Wasserelementare wurden ohne Zweifel von Gazban, dem Goblinhexer beschworen, von dem man behauptet, er habe den Stein der Gezeiten entdeckt. Wie Ihr vielleicht wisst, verflucht der Stein der Gezeiten seinen Träger, sodass er ständig zwischen Sein und Nicht-Sein wandelt.\n\nVielleicht können wir einen Weg finden, dem Fluch entgegenzuwirken. Ein Magier von Dalaran kann die magischen Überreste einer der Armschienen des Wasserelementars für uns analysieren. Ihr müsst wieder zurück zur Insel und einige Exemplare davon herbringen.", progress = "Hattet Ihr Glück, <Name>?", completion = "Hmm, ich bin nicht geeignet, diese Armschienen zu untersuchen, um zu sehen, ob sie von Nutzen sind, aber ich bin sicher, dass zumindest ein Teil uns nützlich sein wird. Bringt sie nach Dalaran und lasst einen Magier einen Blick darauf werfen.\n\nSchließlich kann ich Booty Bay nicht einfach so verlassen, nur um mit einem dieser nervigen alten Magier ein Schwätzchen zu halten.\n\nNicht, dass ich mir Sorgen machte, irgendjemand könnte sich in der Zwischenzeit zum neuen Baron machen. Wer Revilgaz verärgert, lebt nicht mehr lang genug, um davon zu erzählen.", rewards = "Ihr bekommt:\n\n"},
[602] = {title = "Magische Analyse", objective = "Bringt die Wasserelementararmschienen nach Dalaran zu Erzmagier Ansirem Runeweaver.", description = "Wie ich gehört habe, sind die Magier von Dalaran sehr damit beschäftigt, ihre zerstörte Stadt wieder aufzubauen. Ich bin aber trotzdem sicher, dass Ihr einen finden könnt, der sich etwas Zeit für diese Armschienen nehmen wird. Denn wenn ich etwas über Magier weiß, dann, dass sie einem magischen Rätsel einfach nicht widerstehen können.\n\nNehmt diese Tasche mit Wasserelementararmschienen und findet heraus, ob sie in irgendeinem Zusammenhang mit dem Fluch des Steins stehen. Sucht vor allem nach dem Erzmagier Ansirem Runeweaver. Ich hatte schon zuvor mit ihm zu tun und er verfügt über unglaubliches Wissen.", progress = "Wenn Ihr mich entschuldigt, ich bin im Moment sehr beschäftigt.", completion = "Der Stein der Gezeiten? Äußerst interessant. Es mag Euch überraschen zu erfahren, dass ich vor vielen Jahren einen Folianten geschrieben habe, der sich mit den Legenden des Reiches der Gurubashi beschäftigt. Ich weiß einiges über den Stein.\n\nZumindest an einer dieser Armschienen scheinen ein wenig magische Überreste zu haften, die ich analysieren kann.\n\nDann lasst uns mal sehen, was ich so sehen kann...", rewards = "Ihr bekommt:\n\n"},
[603] = {title = "Ansirems Schlüssel", objective = "Sprecht mit Catelyn in Booty Bay.", description = "Der Magier, der im Besitz dieses Steins ist, verstärkt seine Macht durch ein Zentrum... eine Art Altar. Ihr solltet in der Lage sein, dies zu unterbrechen, indem Ihr es überwältigt.\n\nWie es der Zufall will, weiß ich auch genau womit: ein alter Dolch, ein weiteres Trollrelikt. Es gibt da nur ein... winzigkleines Problem.\n\nWisst Ihr, ich fand den Dolch auf einer Forschungsreise im Schlingendorntal, aber ich gab ihn meiner eigenwilligen Tochter, Catelyn, die mir nach Booty Bay weglief, um Piratin zu werden.", progress = nil, completion = "Mein Dolch? Was seid Ihr denn für ein Komiker?\n\nWas? Soll ich Euch die ganze Geschichte noch einmal erzählen, wie ich vom besten Messerkämpfer in Booty Bay zur Witzfigur der ganzen Piratenschaft wurde?\n\nIch habe einen Messerkampf gegen einen dieser Blutsegelbukaniere verloren - eine echte Bande von Bastarden! -, und er nahm meine Klinge als Beute.\n\nAls könnte ich nur mit Beleidigungen und meiner scharfen Zunge ausgestattet, noch irgendwas bei Messerkämpfen werden.", rewards = "Ihr bekommt:\n\n"},
[604] = {title = "Die Blutsegelbukaniere", objective = "Flottenmeister Seehorn in Booty Bay will, dass Ihr 10 Schwadroneure der Blutsegelbukaniere tötet und die Blutsegelkarten sowie die Blutsegelbefehle zurückbringt.", description = "Crazz lobt Eure Hingabe an die Schwarzmeerräuber in hohen Tönen. Ich werde Euch mit einer Mission betrauen, die für die Flotte von höchster Bedeutsamkeit ist.\n\nBespitzelt den so genannten südlichen Kommandoposten, den die Blutsegelbukaniere an den wilden Ufern aufgebaut haben. Überfallt das Lager. Bringt mir ihre Karten zusammen mit ihren schriftlichen Befehlen. Wir werden ganz genau herausfinden, was dieser Abschaum so vorhat.", progress = "Ahoi, <Name>. Welche Neuigkeiten bringt Ihr aus dem Lager der Blutsegelbukaniere im Süden?", completion = "Perfekt, &lt;Name&gt;. Jetzt, da wir ihren Plan kennen, ist das Ganze nur noch eine Frage der Zeit.\n\nUnd wenn ich nur dran denke, dass diese Trottel ganz in der Nähe des Capes vor Anker gegangen sind...", rewards = "Ihr bekommt:\n\n"},
[605] = {title = "Singende blaue Splitter", objective = "Bringt 10 singende Kristallsplitter zu Crank Fizzlebub.", description = "Die singenden Kristalle gibt es nur im Schlingendorntal und sie sind für gewisse Gruppierungen äußerst wertvoll. Ich kann diese Kristalle bewegen, aber die verfluchte Venture Company macht es einem ehrlichen Unternehmer wie mir fast unmöglich, überhaupt welche zu sammeln.\n\nIch würde Euch gern anheuern.\n\nDie Basilisken des Schlingendorntals essen die Kristalle. Dadurch erhalten sie ihre harte Haut und manchmal können Kristalle von ordentlicher Qualität von den Häuten abgesammelt werden.\n\nIhr könnt sie von jedem Basilisken sammeln, aber die nicht ganz so bösartigen leben an der Küste südlich von Zul'Kunda, im Norden.", progress = nil, completion = "Aha! Diese eignen sich wunderbar, &lt;Name&gt;. Und wie wunderbar!\n\nHier ist Euer Anteil, und... es war mir eine Freude, mit Euch Geschäfte zu machen.", rewards = "Ihr bekommt:\n\n"},
[606] = {title = "Zitterhand Angst einjagen", objective = "Bringt 5 Nebeltalinnereien zu \"Zitterhand\" Phillipe nach Booty Bay.", description = "Wenn ich etwas nicht leiden kann, dann sind das Leute, die ihre Spielschulden nicht bezahlen! Und es gibt 'ne Menge Leute, die mir was schulden. Ob Ihr mir wohl beim Eintreiben helfen könnt?\n\nDa ist zuerst mal \"Zitterhand\" Phillipe unten bei den Docks. Er schuldet mir eine Menge nach dem Spiel letzte Woche und ich will mein Geld jetzt! Aber um da dranzukommen, müssen wir ihm gehörig Angst einjagen.\n\nVerlasst die Stadt und jagt alte Nebeltalgorillas. Sucht Euch ein paar nette Innereien heraus und bringt sie zu Zitterhand. Sagt ihm ja nicht, dass sie von einem Tier stammen, er soll ruhig das Schlimmste annehmen.", progress = "He! Den Blick, den Ihr mir da zuwerft, mag ich gar nicht, Sire.", completion = "Igitt! Wo habt Ihr das denn her? Nein, sagt es mir lieber nicht. Ich will es gar nicht wissen!\n\nWer hat Euch geschickt? Seewolf?", rewards = "Ihr bekommt:\n\n"},
[607] = {title = "Rückkehr zu MacKinley", objective = "Bringt Zitterhands Bezahlung zu \"Seewolf\" MacKinley.", description = "Hier, nehmt diesen Beutel und gebt ihn Seewolf. Und sagt ihm, dass ich ihm alles zurückzahlen wollte! Ich schwöre!!\n\nIch hab nur ein bisschen viel getrunken und mich verlaufen, und... Ihr wisst ja, wie es so geht. Er wird es verstehen - Ihr müsst nicht erst grob werden!", progress = "Hallo hallo, <Name>. Habt Ihr Zitterhands Bezahlung bekommen?", completion = "He he, gut gemacht. Und als Ihr Zitterhand die Innereien gezeigt habt, wie stark hat er da gezittert?\n\nHa! Er ist so leicht zu durchschauen. Wenn ich mit ihm Karten spiele, kann ich einfach nur gewinnen!\n\nIch danke Euch für Eure Hilfe, &lt;Name&gt;. Nun ist es Zeit, dass Ihr Eure Bezahlung erhaltet...", rewards = "Ihr bekommt:\n\n"},
[608] = {title = "Die Blutsegelbukaniere", objective = "Flottenmeister Seehorn in Booty Bay will, dass Ihr Kapitän Stillwasser, Käpt'n Kielhol und Flottenmeister Firallon tötet.", description = "Dieser verdammte Firallon! Könnte kein Boot in einem Stück über den Kristallsee bringen, ganz zu schweigen eine ganze Flotte gegen uns führen.\n\nDie Blutsegelbukaniere werden für ihre Sorglosigkeit teuer bezahlen. Jetzt, da wir ihren Angriffsplan kennen, können wir unseren Gegenschlag starten, bevor sie überhaupt merken, was los ist.\n\nAber warum sollten wir die ganze Flotte schicken, wenn eine mutige Gruppe von Abenteurern das auch allein schaffen kann? <Name>, nehmt einige von Euren geschicktesten Kameraden zu Firallons Ankerplatz und tötet die Führungskräfte der Blutsegelbukaniere. Ihre Flotte wird bald danach sinken ...", progress = "Wo liegt das Problem, <Name>? Wir müssen angreifen bevor die Blutsegelbukaniere es tun!", completion = "Ah, was für ein wunderbarer Tag für die Schwarzmeerräuber! Ein dreifaches Hurra für Euch, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nSchwarzmeertunika"},
[609] = {title = "Voodooschulden", objective = "Bringt Maurys Klumpfuß, Jon-Jons goldenes Handfernrohr und Chuckys gewaltigen Ring zu \"Seewolf\" MacKinley in Booty Bay.", description = "Meine Liste wird kürzer, aber da sind immer noch Leute, die mir was schulden.\n\nAls Nächste haben wir da Maury \"Klumpfuß\" Wilkins, Jon-Jon die Krähe und Chucky \"Zehn Daumen\".\n\nDie Schulden dieser räudigen Hunde stehen schon seit Monaten aus und ich dachte schon, dass sie die Stadt verlassen hätten, nur um nicht zahlen zu müssen! Später hab ich gehört, dass sie jetzt verflucht und verhext sind und in den Dschungelruinen ihr Unwesen treiben. Aber ihr Schicksal ist mir ziemlich egal - ich will nur, was mir zusteht!\n\nSie halten sich in den Ruinen von Aboraz und den Ruinen von Jubuwal nordöstlich von hier auf. Sucht sie und holt das Geld.", progress = "<Name>, habt Ihr diese drei Hunde gefunden? Habt Ihr ihre Wertsachen eingesammelt?", completion = "Großartig! Dafür krieg ich einen guten Preis, ganz besonders für das, was sich in Maurys Fuß befindet! Vielen Dank, &lt;Name&gt;!\n\nHoffentlich haben die drei ihre Lektion gelernt: Wettet nicht auf was, das Ihr Euch nicht leisten könnt, zu verlieren.\n\nVielleicht ist es für sie ja schon zu spät, aber... sie sollten vorsichtig bei der Wahl sein, mit wem sie spielen.", rewards = "Ihr bekommt:\n\n"},
[610] = {title = "Schönling Duncan", objective = "Holt Catelyns Dolch von \"Schönling\" Duncan.", description = "Mein VATER hat Euch geschickt? Dachte, der alte Knacker hätte mich mittlerweile aufgegeben.\n\nEs war ja nicht unbedingt sein Fehler, dass ich weggerannt bin, er hätte einfach nicht erwarten dürfen, dass ich Lust auf ein langweiliges Leben hab, alte muffige Bücher lese und mich mit grauhaarigen, steifen, hochnäsigen Magiern abgebe!\n\nWenn Ihr meinen Dolch braucht, müsst Ihr ihn von \"Schönling\" Duncan wiederholen, einem der Blutsegelbukaniere. Rammt einfach was zwischen seine Schultern und er wird ihn sicherlich sofort rausrücken.", progress = "Ich bin noch nie besiegt worden, wisst Ihr, <Name>? Natürlich hab ich ein paar Schnitte abgekriegt, kein Messerkampf ohne so was, aber er hat mir einfach an den Kopf gehauen und weg war ich. Als ich wieder zu mir kam, war meine Klinge weg.\n\nObwohl mein Spitzname es anders vermuten lässt, brauche ich dennoch ein Messer zum kämpfen, und für mich muss es einfach dieses sein.", completion = "Ihr habt Duncan geschlagen? Scheint, als wärt Ihr nicht ganz so grün hinter den Ohren, wie Ihr es bei einem ersten Blick vermuten lasst.\n\nIch denke mal, dass es auch bedeutet, dass ich Euch in der nächsten Zeit besser nicht zu einem Kampf herausfordern sollte!", rewards = "Ihr bekommt:\n\n"},
[611] = {title = "Der Fluch der Gezeiten", objective = "Zerstört den Altar der Gezeiten mit Catelyns Klinge, tötet Gazban und bringt dann den Stein der Gezeiten sowie Catelyns Klinge zurück zu Baron Revilgaz.", description = "Ihr sucht also nach einer Art Altar? Nun, ich bin zwar kein Experte für Trollruinen wie mein Vater, aber ich habe von einer versunkenen Trollstadt nah bei der Insel gehört, die Ihr sucht. Vielleicht solltet Ihr dort mal suchen.\n\nIhr habt mein Messer für mich wiedergeholt, also könnt Ihr es Euch auch borgen... Ich will es aber wiederhaben, wenn Ihr fertig seid!", progress = "Habt Ihr den Stein der Gezeiten für mich mitgebracht, <Name>? Ich habe schon ein wenig Platz gemacht und einen schönen Aufsteller dafür besorgt.", completion = "Erstaunlich! Der Stein der Gezeiten! Er wird einen ganz besonderen Platz in meiner Sammlung alter Troll-Artefakte erhalten. Habt Ihr gesehen, dass es fast so aussieht, als seien die Gezeiten unter seiner Oberfläche gefangen? Wie wundersam!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nRobe des Kristallwassers"},
[613] = {title = "Maurys Fuß aufbrechen", objective = "Bringt Maurys Schlüssel zu \"Seewolf\" MacKinley in Booty Bay.", description = "Verflucht noch eins! Dieser Blödmann Maury hat ein Schloss an seinem Fuß befestigt und ich kann es nicht öffnen! Seine Beute ist in dem Fuß, und das sind seine Schulden!\n\nWir müssen den Schlüssel finden, dann kriegen wir auch das Schloss auf. Maury hat mit den Ogern der Mosh'Ogg gespielt, in ihrem Hügel im Nordosten. Als er noch lebte, erzählte er mir, dass sie ihn das letzte Mal von dort verjagt hätten, weil er zu viel gewonnen habe. Vielleicht haben die Oger ja seinen Schlüssel.\n\nWenn sie ihn haben sollten, müsstet Ihr eine ganze Menge von ihnen beseitigen, bevor Ihr den richtigen findet.", progress = "Ahoi, <Name>! Habt Ihr Maurys Schlüssel schon gefunden?", completion = "Ihr habt ihn gefunden! Vielen vielen Dank, &lt;Name&gt;. Ihr wart mir eine große Hilfe!\n\nHier, nehmt das, Ihr habt es Euch verdient!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nSammelplatte"},
[614] = {title = "Die Truhe des Kapitäns", objective = "Bringt Smotts' Truhe zu Hecklebury Smotts nach Booty Bay.", description = "Früher hab ich ein Schiff von hier bis ganz nach Ratchet, in Kalimdor gesegelt. Ich war ein erfolgreicher Kapitän mit einem einwandfreien Ruf.\n\nBis...\n\nDiese verfluchten Meeresriesen mich ruinierten! Sie haben mein Schiff zerschmettert, meine Crew umgebracht und mich in ein Rettungsboot nach Booty Bay gesteckt. Einer dieser Riesen, Gorlash, hat meine Kapitänstruhe gestohlen. Er sagte, er wolle sie als Schnupftabakdose. Diese Dreistigkeit!\n\nIch habe gehört, dass Gorlash an der Küste östlich von hier sein Unwesen treibt. Findet ihn und bringt mir meine Truhe zurück! Tut das, und Ihr habt Euch die Dankbarkeit eines Kapitäns verdient!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nBlutbandarmschienen"},
[615] = {title = "Der Entersäbel des Kapitäns", objective = "Sprecht mit Sprogger.Nachdem ich mein Schiff an diese Riesen verlor, kaufte ich mir ein neues. Ich hab es SMOTTS' REVENGE genannt, Vorräte gekauft, eine Crew angeheuert und Segel gesetzt, um diese Schurken ausfindig zu machen. Ich habe sie auch gefunden, aber... sie haben mich besiegt. Sie haben die SMOTTS' REVENGE zerschmettert, meine zweite Crew umgebracht und mich in einem weiteren Rettungsboot ausgesetzt.\n\nDieses Mal hat ein anderer Riese, Negolash, meinen Entersäbel gestohlen.\n\nStellt Euch Negolash und bringt mir meinen Entersäbel!\n\nSprecht mit Sprogger. Er war mein Smutje auf der SMOTTS' REVENGE und hat den letzten Angriff überlebt. Er kann Euch helfen, den Riesen zu finden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Nachdem ich mein Schiff an diese Riesen verlor, kaufte ich mir ein neues. Ich hab es SMOTTS' REVENGE genannt, Vorräte gekauft, eine Crew angeheuert und Segel gesetzt, um diese Schurken ausfindig zu machen. Ich habe sie auch gefunden, aber... sie haben mich besiegt. Sie haben die SMOTTS' REVENGE zerschmettert, meine zweite Crew umgebracht und mich in einem weiteren Rettungsboot ausgesetzt.\n\nDieses Mal hat ein anderer Riese, Negolash, meinen Entersäbel gestohlen.\n\nStellt Euch Negolash und bringt mir meinen Entersäbel!\n\nSprecht mit Sprogger. Er war mein Smutje auf der SMOTTS' REVENGE und hat den letzten Angriff überlebt. Er kann Euch helfen, den Riesen zu finden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[616] = {title = "Die Spukinsel", objective = "Sprecht mit Baron Revilgaz in Booty Bay.", description = "Für Baron Revilgaz höre ich mich immer nach Gerüchten von seltsamen und ungewöhnlichen Dingen in Booty Bay und im Schlingendorntal um. Normalerweise gebe ich ja nicht viel auf Geistergeschichten, aber ich habe ein paar Seeleute in der Taverne über eine Insel nahe der Küste reden hören, auf der es spuken soll. Sie erzählten von Wasserelementaren und einem rasenden Goblingeist.\n\nWenn Ihr mit Revilgaz sprechen solltet, erzählt Ihr ihm davon?", progress = nil, completion = "Interessant. Ich meine, vor einiger Zeit ein Buch gelesen zu haben, das nahe legte...\n\nAh, ja natürlich, es war eine Trolllegende. Wenn das, was Krazek berichtet, wahr sein sollte, dann werde ich vielleicht bald den Stein der Gezeiten meiner Sammlung von alten Artefakten und Relikten hinzufügen können.", rewards = "Ihr bekommt:\n\n"},
[617] = {title = "Bündelweise Akiris", objective = "Bringt 10 Stängel Akirisschilfrohr zu Freibeuter Bloads nach Booty Bay.", description = "Sucht'er Arbeit, <Name>? Hab vielleicht was für Euch, wenn'er Euch was traut.\n\nMein Freund Groy verdient sich dumm un' dämlich mit dem Verkauf von dem Zeuch, das die Naga Akirisschilfrohr nennen: is' so 'ne Art wertvolles Meeresschilfrohr. Bin nich' sicher, für was es gut is', aber er bezahlt gut für Bündel von dem Zeuch.\n\nWenn Ihr mir 10 Stängel von dem Zeuch bringt, sind wa im Geschäft. Die Naga wurden zuletzt am Strand nördlich von hier gesehen.", progress = "Wenn 'er mit mir keine Geschäfte machen wollt, dann verschwindet, <Name>.", completion = "Gut gemacht, &lt;Name&gt;. 10 Stängel Akirisschilfrohr waren wohl keine Herausforderung für Euch, oder? Nix gegen die Naga, aber es muss ja jeder schließlich sehen, wie er zurechtkommt.", rewards = "Ihr bekommt:\n\nVersengerschärpe"},
[618] = {title = "Negolash entgegentreten", objective = "Bringt 10 gegrillte Bussardflügel und 5 Flaschen Dschungelrankenwein zu Käpt'n Smotts Rettungsboot.\n\nTötet Negolash und bringt Smotts' Entersäbel zu Captain Smotts ins Schlingendorntal.", description = "Negolash ist ein hungriger Riese.\n\nAls die Riesen unser Schiff zerstörten, ging Negolash schnurstracks in meine Kombüse. Er hatte keinen Appetit auf die Crew wie die anderen Riesen. Negolash wollte Wein... und meine gegrillten Bussardflügel. Die sind meine Spezialität. Für das Rezept musste ich bis ins Ödland reisen!\n\nWenn Ihr den Riesen anlocken wollt, dann besorgt Euch etwas Wein und einen Haufen Bussardflügel. Legt sie in unser altes Rettungsboot, an der Küste südöstlich von hier. Sobald Negolash das Essen riecht, wird er bestimmt kommen!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nSmotts' Kompass"},
[619] = {title = "Negolash anlocken", objective = "Dies ist ein verlassenes Rettungsboot. An seiner Seite stehen in zerkratzten, verblassten Buchstaben die Worte:\n\n\"Smotts' Revenge\"", description = nil, progress = "Dies ist ein verlassenes Rettungsboot. An seiner Seite stehen in zerkratzten, verblassten Buchstaben die Worte:\n\n\"Smotts' Revenge\"", completion = "Ihr legt Essen und Getränke hinein...", rewards = nil},
[620] = {title = "Die Schärpe mit Monogramm", objective = "Bringt die Schärpe mit Monogramm zu ihrem Besitzer zurück.", description = "Auf dem Saum dieser feinen Schärpe sind die Buchstaben \"HS\" eingestickt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[621] = {title = "Zanzils Geheimnis", objective = "Bringt 12 Proben von Zanzils Mixtur zu Crank Fizzlebub nach Booty Bay.", description = "Zanzil der Ausgestoßene hält sich mit seinen Anhängern in den Ruinen von Aboraz und Jubuwai auf, nordöstlich von Booty Bay. Sein Stamm hat ihn verbannt. Warum? Nun...\n\nZanzil hat eine Methode, den Geist von anderen zu beugen, und seine Anführer fürchten ihn. Er benutzt eine Mixtur von Dschungelpflanzen, die den Willen seiner Anhänger unterdrücken und ihre Körper stärken.\n\nSeine Mixtur könnte sehr wertvoll für diejenigen sein, die andere zu kontrollieren wünschen.\n\nBringt mir Proben seiner Mixtur und ich werde einen Nutzen für sie finden.", progress = "Habt Ihr die Proben von Zanzils Mixtur??", completion = "Ah, sehr gut! Hier ist Eure Bezahlung.\n\nUnd hier noch ein kleiner Zuschuss... für Eure Verschwiegenheit.", rewards = "Ihr bekommt:\n\nGürtel der Verderbnis"},
[622] = {title = "Rückkehr zu Corporal Kaleb", objective = "Bringt Krazeks reparierten Topf zu Corporal Kaleb im Rebellenlager.", description = "Während Ihr fort wart, habe ich den Topf, den Ihr mir brachtet, repariert. Ich habe sogar noch eine zusätzlich Dampfpfeife angebracht, und seht mal! Da ist ein neues Hackbeil am Boden, das kann Beinknochen durchtrennen.\n\nJa, ja, Krazeks Spezialtopf weiß, was Köche wünschen! Sein Besitzer wird bestimmt erfreut sein.", progress = "Hallo, <Name>. Seid Ihr bis Booty Bay gekommen? Hat der Goblin Krazek meinen Topf repariert??", completion = "Er ist wieder heile! Das ist toll, jetzt kann ich endlich mit dem Abendessen anfangen! Ich danke Euch vielmals, &lt;Name&gt;.\n\nIch hoffe, es erging Euch gut in Booty Bay. Dort kann es ganz schön rau hergehen, und... ich habe Gerüchte gehört, dass die Goblins manchmal betrunkene Seeleute in ihre Sklavenboote zerren...\n\n... wo sie gezwungen werden, wer weiß wo hinzusegeln und wer weiß was zu tun...", rewards = "Ihr bekommt:\n\nKappe der Harmonie"},
[623] = {title = "Bündelweise Akiris", objective = "Bringt ein Bündel Akirisschilfrohr zu Freibeuter Groy nach Theramore.", description = "Ach ja, <Name>, fein dass Ihr hier seid. Während Eurer Abwesenheit hab ich 'ne Nachricht von Groy gekricht. Er sachte, dass er mit der letzt'n Lieferung sehr zufrieden war und dass 'n Kunde von ihm noch mehr von dem Zeuch hab'n will und das sofort.\n\nIch fahr erst inner Woche wieder nach Theramore, aber wenner den Weg nich' scheut, dann könnter auch gleich das Zeuch für mich mitnehmen.\n\nAbenteuerlustich? Wissen tut er ja, wo die Marschen von Dustwallow sin', nich'? Ich wär aber vorsichtich, Theramore kann gefährlich sein, wenn man inne falschen Kreise kommt.", progress = "Waas?", completion = "Was?! Ich habe Besseres zu tun, als mit Euresgleichen zu reden, &lt;Klasse&gt;. Entweder es springt was für mich raus, oder Ihr verschwindet aus meinem Gesichtskreis.\n\nHä? Bloads hat Euch geschickt, hm? Nun, was habt'er denn für mich?\n\n\n\nNicht schlecht, gar nicht mal so schlecht. Ein weiteres Bündel wird meinen Kunden sehr glücklich machen.\n\nIch nehme an, Eure nächste Frage ist die nach dem Geld, nich, &lt;Klasse&gt;? Kann ja gar nich' anders!\n\nHier, nehmt diese Münzen und noch'n Ratschlag: Runter von meinen Docks.", rewards = "Ihr bekommt:\n\n"},
[624] = {title = "Cortellos Rätsel", objective = "Löst das Rätsel!", description = "Eine Brücke verziert und stark frequentiert\nUnter ihr werdet Ihr finden was Euch sehnlichst erwartet\nManche nennen es Hinweis andere Tipp\nEs liegt östlich der Schlucht der Totenwinde und südlich vom Rotkammgebirge\nFür unendliche Zeit genau dort wird es liegen\nIn den Sümpfen des Elends sich für immer wiegen\n", progress = nil, completion = "Das durchnässte Pergament enthält den nächsten Hinweis...", rewards = "Ihr bekommt:\n\n"},
[625] = {title = "Cortellos Rätsel", objective = "Löst das Rätsel!", description = "Im fernen Kalimdor wartet ein Land\nDie Hoffnung hielt dort den Gefahren nicht stand\nDas Wetter östlich des Brachlandes ist harsch\nDunkel und Tod droh'n in der Dustwallowmarsch\nDoch in einer Höhle, Richtung Südwest\nLiegt ein Hinweis für alle, die wagen den Test.", progress = nil, completion = "Ihr findet eine modrige Rolle.", rewards = "Ihr bekommt:\n\n"},
[626] = {title = "Cortellos Rätsel", objective = "Löst das Rätsel!", description = "Nach Lordaeron! Schwerer Aufruhr dort wütet\nSoldatenmut wird mit dem Tode vergütet\nSucht Euren Weg durch den Aufstand dort\nund Eure Such' ist beendet an einem Ort\nAm Fuße der großen Fälle, entlang der Küste im Hinterland\nIm Wasser dort tief unten, nehmt Ihr Euren Schatz in die Hand!", progress = nil, completion = "Ihr öffnet die Truhe und findet...", rewards = "Ihr bekommt:\n\nForscherknappsack"},
[627] = {title = "Gefallen für Krazek", objective = "Bringt 4 Ladungen geringes Blutsteinerz zu Krazek nach Booty Bay.", description = "Es gibt eine Berghöhle in der Schlucht der Trockenstoppel, weit im Norden des Arathihochlands. In dieser Höhle findet sich ein seltenes Erz: Blutstein. Der Blutstein in dieser Höhle ist zwar nicht von höchster Qualität, aber auch Blutstein von minderer Qualität ist wertvoll... für diejenigen, die wissen, wie er zu nutzen ist.\n\nIch hätte gerne etwas davon.\n\nIch werde Euren Spezialtopf reparieren, aber während ich daran arbeite, möchte ich, dass Ihr mir einige Blutsteinproben bringt. Bringt mir genügend und Ihr erhaltet einen Bonus.\n\nOh, und falls Ihr nicht wisst, wie man ihn abbaut... findet jemanden, der es kann!", progress = "Hallo, <Name>. Hattet Ihr Glück mit dem Blutstein?", completion = "Ah, wunderbar! Dass war ein großer Gefallen, den Ihr mir erwiesen habt.\n\nHier ist Euer Lohn...", rewards = "Ihr bekommt:\n\n"},
[628] = {title = "Exzelsior", objective = "Bringt die Haut eines alten Krokilisken zu Drizzlik nach Booty Bay.", description = "Die Innenseiten sind fertig gestellt, jetzt fehlt nur noch die äußere Schicht. Dafür verwende ich nur die besten Häute der alten Krokilisken. Sie sind widerstandsfähiger und eine bessere Leinwand - wenn Ihr es so nennen wollt - für die Muster und Akzente, die Drizzliks Exzelsiorlinie ausmachen.\n\nEs ist allerdings äußerst schwierig, diese vollkommene Haut zu finden; die Einzige, die meinen Plänen gerecht wird, ist die eines alten Salzwasserkrokilisken. Die Alten kommen nur heraus, um die anderen Salzwasserkroks zu verteidigen, also werdet Ihr wahrscheinlich einige töten müssen, um einen von der Sorte herauszulocken.", progress = "Irgendwo habe ich gelesen, dass die Salzwasserkrokilisken langsam aussterben... schlecht für mein Geschäft, was?\n\nEgal, ich hoffe, Ihr habt die Haut eines alten Salzwasserkrokilisken für mich!", completion = "Großartig! Dank Eurer Hilfe habe ich diese Bestellung fertig und kann sie mit dem nächsten Schiff zu Direktor Riddlevox nach Undermine abschicken. Sogar noch vor der Frist!\n\nFür all Eure harte Arbeit, hier, ich habe einige zusätzlich gemacht, nehmt Euch ein Paar. Geht auf Drizzliks Rechnung.\n\nUnd denkt dran, nirgends gibt es Stiefel, die so fein, wie Stiefel von Drizzliks Exzelsiorlinie ganz allein!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nExzelsiorstiefel"},
[629] = {title = "Das finstere Riff", objective = "Bringt 1 Schrifttafel-Splitter zu Kin'weelay in das Basislager von Grom'gol.", description = "Vor langer Zeit, als ein großes Beben die Welt erschütterte, versank eine alte Trollstadt in den Wassern der ungezähmten Küste im Nordwesten. Wir nennen diesen Ort das finstere Riff, denn Murlocs bewohnen jetzt die Ruinen der Stadt und greifen jeden an, der sich ihnen nähert.\n\nIn diesen alten Ruinen liegt eine alte Schrifttafel, die die uralte Geschichte von Gri'lek erzählt, einem Helden der Trolllegenden. Diese Geschichte ist dem Darkspearstamm heilig und auch wenn die Tafel zu groß ist, um sie zu bewegen, so möchte ich doch einen Splitter davon, damit ich ihn in unserer neuen Heimat in Orgrimmar in einen Schrein legen kann.", progress = "Ich warte auf den Schrifttafel-Splitter, <Name>.", completion = "Das ist gut. Wenn ich nach Orgrimmar zurückkehre, werde ich diesen Splitter an einen geheiligten Ort legen. Er wird uns an die Macht und Ehre von Gri'lek erinnern.\n\nIch danke Euch, &lt;Name&gt;. Eure Taten sind ein Zeichen wachsender Freundschaft mit dem Darkspearstamm.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[630] = {title = "Flaschenpost", objective = "Erschlagt König Mukla und kehrt mit dem Schlüssel zu Prinzessin Poobah zurück, um sie zu befreien.", description = "<Name>, ich setze meine ganze Hoffnung in Euch und jeden, den Ihr gewinnen könnt, um mich zu befreien. Der große Blaumähnenkönig Mukla hat mich gefangen genommen. Er befehligt die Bestien dieser Insel und sie halten mich mit Hilfe dieser Kette gegen meinen Willen hier fest. Wenn Ihr ihn töten und den Schlüssel für diese Fessel finden könnt, stehe ich tief in Eurer Schuld.\n\nIch habe ihn oft auf der südöstlichen Seite der Insel gehört, aber bitte seid vorsichtig: Man darf ihn nicht unterschätzen.", progress = "Ich danke meinen Vorfahren, dass mir jemand zu Hilfe gekommen ist. Habt Ihr den Schlüssel, der mich befreien kann?", completion = "&lt;Name&gt;, Ihr habt mich vor großer Schande bewahrt. Wenn es in meiner Macht stünde, würde ich Euch einen Platz in meinem Stamm anbieten. Alles, was ich Euch zur Zeit anbieten kann, ist jedoch nur diese Marke für den Mut und die edle Gesinnung, die Ihr bewiesen habt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nPoobahs Nasenring"},
[631] = {title = "Der Thandol-Übergang", objective = "Rhag Garmason will, dass Ihr Ol' Rustlocke findet.", description = "Eine enorme Explosion donnerte durch die Hügel hinweg. 's war furchtbar, sag ich Euch!\n\nGute Soldaten starben bei der Verteidigung des Thandol-Übergangs. Longbraid sagt, wir werden uns noch an den Dunkeleisenzwergen rächen.\n\nAber wir befinden uns in einer Welt voller Schmerz, und Verstärkung ist noch lange nicht in Sicht. Longbraid hat Ol' Rustlocke als Späher zur östlichen Brücke geschickt, um rauszufinden, ob wir sie sichern können.\n\nDas ist aber schon Tage her. Und jetzt, wo Dun Modr belagert wird, haben wir nicht genug Leute, um nach ihm zu suchen.\n\nVielleicht könnt Ihr ihn finden...", progress = nil, completion = "Ihr durchsucht den winzigen Zwergenleichnam. Auf dem Helm könnt Ihr die deutlich eingravierten Buchstaben lesen: Ebenezer Rustlocke.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[632] = {title = "Der Thandol-Übergang", objective = "Meldet Euch bei Rhag Garmason zurück und zeigt ihm das Pergament, das Ihr bei Rustlockes Leichnam gefunden habt.", description = "Es sieht ganz so aus, als sei der arme Ol' Rustlocke in einen Hinterhalt der Dunkeleisenzwerge geraten. Ihr bemerkt ein Pergament neben seinen geballten Fäusten.\n\nErstattet Rhag Garmason Eure traurigen Neuigkeiten und zeigt ihm, was Ihr gefunden habt.", progress = "Gibt es Spuren von Ol' Rustlocke, <Name>?", completion = "Oh weh, das sind wirklich schlechte Nachrichten.", rewards = "Ihr bekommt:\n\n"},
[633] = {title = "Der Thandol-Übergang", objective = "Zerstört den Sprengstoffbehälter", description = "Um Himmelswillen, nein! Armer Rustlocke. Das ist wirklich eine fürchterliche Tragödie.\n\nSein Tod darf nicht vergebens sein. Das Pergament, das Ihr entdeckt habt, zeigt an, dass Kam Deepfury, der hinter dem eigentlichen Angriff steckt, dafür gesorgt hat, dass ein Behälter mit Sprengstoff hinter dem Thandol-Übergang im Arathihochland versteckt wurde.\n\nWenn dieser Sprengstoff  zur Brücke gelangt, wird unsere Hauptversorgungsverbindung in den Norden gekapp! Der Behälter muss zerstört werden, <Name>! Kehrt zu mir zurück, wenn Ihr Eure Mission erfüllt habt.\n\nIhr seid unsere einzige Hoffnung.", progress = "Der Behälter mit Sprengstoff muss zerstört werden!", completion = "Die letzte Brücke ist gerettet! Ihr habt König Magni und dem Volk von Khaz Modan einen großen Dienst erwiesen.\n\nJetzt können wir so lange durchhalten, bis Verstärkung kommt...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZwergenwachen-UmhangSumpflandbeinkleider\n\nIhr bekommt außerdem:\n\n"},
[634] = {title = "Hilfegesuch an die Allianz", objective = "Macht Captain Nials bei der Zuflucht ausfindig.", description = "Ich bitte Euch noch um einen kleinen Gefallen, <Klasse>. Wir erwarten die Reserven von Ironforge. Roggo hat jedoch von einem Lager der Allianz im Norden des Arathihochlands bei der Zuflucht erfahren.\n\nReist dorthin und macht Captain Nials ausfindig. Fragt den guten Captain, ob die Allianz einige Soldaten erübrigen kann, die uns behilflich sein können, Dun Modr und den Thandol-Übergang zurückzuerobern.", progress = nil, completion = "Longbraid und seine mutigen Soldaten haben mein ehrliches Mitgefühl und Beileid. Die Nachricht von der Tragödie am Thandol-Übergang und der Fall von Dun Modr lastet schwer auf meinem Herzen.\n\nAber Stromgarde ist gefallen! Darum befinden wir uns hier bei der Zuflucht. Wir müssen uns der Wiedereroberung unserer eigenen großen Stadt stellen.\n\nEhre und Pflicht verlangen von uns, dass wir das Hochland nicht verlassen, bis erneut das mächtige Banner des Königs über Stromgarde weht. Ich werde Longbraid Nachricht geben, dass er auf sich allein gestellt ist ...", rewards = "Ihr bekommt:\n\n"},
[635] = {title = "Kristall in den Bergen", objective = "Findet den Kristall aus Eurer Vision.\n\nBereitgestellter Gegenstand: \n", description = "Dieser Splitter pulsiert während Ihr ihn haltet...\n\nIhr habt das Gefühl, als ob ein Bitten vom Splitter ausgeht, als ob jemand versucht, mit Euch zu kommunizieren, jemand, der verzweifelt Eure Hilfe sucht.\n\nVor Eurem inneren Auge erscheint eine Vision - die nördlichen Berge von Arathi und ein blitzender Kristall, der dort aus dem Boden ragt.\n\nIhr spürt, wie es Euch dorthin zieht.", progress = nil, completion = "Dieser Kristall pulsiert, als ob in ihm eine lebende Kraft gefangen ist.", rewards = "Ihr bekommt:\n\n"},
[637] = {title = "Sully Balloos Brief", objective = "Bringt Sully Balloos Brief zu Sara Balloo.", description = "Der durchnässte und zerrissene Umschlag löst sich in Euren Händen auf und Euch bleiben nur einige Seiten eines Briefes, der mit viel Mühe geschrieben wurde.\n\nDer Brief ist adressiert an eine Mrs. Sara Balloo in Ironforge und beginnt mit den Worten, \"Meine liebe Sara ...\".", progress = "Ihr seht aus, als wäret Ihr weit gereist und hättet viel Aufruhr in Eurem Leben erlebt, <Klasse>. Diese Zeit, in der wir leben, ist eine Prüfung für die Seele. Was für Neuigkeiten bringt Ihr denn nun?", completion = "Ihr sagt, Ihr habt meinen Sully unter den eiskalten Wassern gesehen? Sagt, dass das nicht wahr ist!\n\nLasst mich lesen, was er geschrieben hat...", rewards = "Ihr bekommt:\n\n"},
[638] = {title = "Trollbane", objective = "Reist nach Hammerfall im Arathihochland und sprecht mit Zengu.", description = "Da Thoras Trollbane tot ist und Stromgarde in Schutt und Asche liegt, hat Vol'jin Anweisungen gegeben, dass wir alles tun sollen, um das legendäre Schwert Trol'kalar den menschlichen Händen zu entreißen, auf dass wir es in zukünftigen Kämpfen gegen die Trolle von Zul'Gurub nutzen können.\n\nZengu, einer unserer erfahrenen Jäger, wurde nach Hammerfall im Nordosten des Arathihochlands entsandt, um seine Beschaffung zu leiten.", progress = nil, completion = "Wie geht‘s denn so, &lt;Klasse&gt;? Die Aufgabe, die Vol'jin uns gestellt hat, wird nicht leicht sein, und jegliche Hilfe, die Ihr uns bieten könnt, ist nicht nur sehr willkommen, sondern auch vonöten.", rewards = "Ihr bekommt:\n\n"},
[639] = {title = "Siegelzeichen von Strom", objective = "Holt das Siegelzeichen von Strom für Zengu in Hammerfall.", description = "In den alten Zeiten kämpften Trolle gegen das Arathorianische Reich und unseren geschicktesten Feind, Lord Ignaeus von Strom, genannt Trollbane. Er ritt in die Schlacht und schwenkte dabei sein Schwert Trol'kalar - was in ihrer alten Sprache Trolltöter heißt.\n\nAber jetzt sind die Söhne von Trollbane geschwächt, ihre Festung ist dem Verfall preisgegeben.\n\nDas Schwert wird von mehreren Siegelzeichen beschützt, die unter den Überlebenden von Stromgarde verteilt wurden. Wir müssen sie alle bekommen.\n\nDas Erste wurde von dem Syndikat mitgenommen, einer ihrer Männer in Stromgarde sollte es haben.", progress = "Habt Ihr das erste Siegelzeichen bereits gefunden? Höchstwahrscheinlich trägt es einer der Agenten des Syndikats in Stromgarde bei sich.", completion = "Exzellent, Mann. Unsere Suche der Siegelzeichen, die wir sammeln müssen, um Trol'kalar aus Trollbanes Grabmal an uns zu nehmen, hat damit einen guten Anfang genommen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[640] = {title = "Das zerbrochene Siegelzeichen", objective = "Holt die 11 Siegelzeichen-Fragmente von den Verteidigern in Stromgarde und bringt sie zu Tor'gan in Hammerfall.", description = "Thoras Trollbanes Grabmal wird durch drei Siegelzeichen beschützt - das Erste davon habt Ihr dem Syndikat entwendet. Es wird allerdings schwieriger sein, an die anderen beiden heranzukommen, da sie sich bei der Miliz von Stromgarde befinden und diese sich gut verschanzt hat.\n\nDas Siegelzeichen von Thoradin wurde von Thoras' Sohn, Galen, in 11 Teile aufgeteilt und unter den Verteidigern von Stromgarde verteilt. Holt die Stücke und bringt sie zu Tor'gan, dem Trollschamanen, er kann sie wieder zum vollständigen Siegelzeichen binden.", progress = "Throm-ka, <Klasse>. Zengu sagte mir, dass Ihr meine Hilfe bräuchtet?", completion = "Ah, ich soll für Euch dieses Siegelzeichen zusammenfügen? Das sollte nicht allzu schwer sein... alle Teile scheinen vorhanden zu sein und die magische Struktur müsste sich leicht wieder herstellen lassen.\n\nIhr solltet vielleicht besser Eure Augen schließen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[641] = {title = "Siegelzeichen des Thoradin", objective = "Bringt das wiederhergestellte Siegelzeichen von Thoradin zu Zengu in Hammerfall.", description = "Die Rekonstruktion ließ sich problemlos durchführen. Das Siegelzeichen kann nun benutzt werden, um das Siegel auf Trollbanes Grabmal aufzuschließen. Bringt es zu Zengu, er hat ohne Zweifel weitere Aufgaben, die Ihr erfüllen müsst.", progress = "<Name>! Habt Ihr das zweite Siegelzeichen?", completion = "Wir haben unsere Aufgabe, Trol'kalar aus Trollbanes Grabmal an uns zu nehmen, zur Hälfte erfüllt. Wir sind nicht ganz sicher, wo sich das dritte Siegelzeichen befindet, da seine Bewacher allem Anschein nach viel in Arathi umherreisen, aber ich bin der festen Überzeugung, dass Ihr in der Lage seid, es aufzuspüren.", rewards = "Ihr bekommt:\n\n"},
[642] = {title = "Die gefangene Prinzessin", objective = "Sammelt 12 Körner von Myzrael und bringt sie zu den regenbogenfarbenen Splittern in der Schlucht der Trockenstoppel.", description = "Mein Name ist Myzrael. Ich bin eine Prinzessin der Erde und meine Häscher, die Riesen, halten mich tief unterhalb des Arathihochlandes fest. Diese Kristallsplitter sind meine einzige Möglichkeit, mit der oberen Welt zu sprechen.\n\nBitte helft mir! Kobolde der Trockenstoppel, die Verbündete der Riesen sind, haben einen Splitter wie diesen hier in ihrer Schlucht im Osten. Um die Gruppe zu aktivieren, müsst Ihr die Körner von Myzrael von den Kobolden holen und sie an der Gruppe anwenden.\n\nIch flehe Euch an, <Name>, helft mir!", progress = "Diese Gruppe von Splittern sieht den Splittern von Myzrael sehr ähnlich. Aber durch sie pulsiert kein Gefühl der Sicherheit.", completion = "Ah! Ihr habt diese Splitter aktiviert! Ich fühle mich schon mehr wie ich selbst!\n\nAber weh mir, ich bin immer noch weit davon entfernt, frei zu sein...", rewards = "Ihr bekommt:\n\n"},
[643] = {title = "Siegelzeichen von Arathor", objective = "Holt das Siegelzeichen von Arathor und bringt es Zengu in Hammerfall.", description = "Obwohl man kaum behaupten kann, dass sie Stromgarde kontrollieren, geschweige denn das gesamte Arathihochland, marschiert der menschliche Prinz trotzdem mit den Überbleibseln seiner Kavallerie durch das Land. Ich versteh ja nicht, warum er das tut, aber wer versteht schon, wie Menschen ticken, hm?\n\nWas auch immer seine Gründe sein mögen, er hat eines der Siegelzeichen Lieutenant Heldenruf, dem Anführer seiner Kavallerie übergeben. Findet ihn und bringt mir sein Siegelzeichen zurück.", progress = "Heldenruf wird nicht so leicht zu finden sein, <Name>. Zu Pferd kann er weite Strecken schnell zurücklegen. Dessen ungeachtet müssen wir dieses Siegelzeichen haben.", completion = "Ihren Anführer der Kavallerie zu verlieren, wird den Verteidigern von Stromgarde einen schweren Schlag versetzen. Und was noch besser ist, es bedeutet, dass wir nur noch ein Siegelzeichen davon entfernt sind, Trol'kalar unser Eigen nennen zu können.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[644] = {title = "Siegelzeichen von Trollbane", objective = "Tötet Prinz Galen Trollbane und bringt das Siegelzeichen von Trollbane zu Zengu in Hammerfall.", description = "Das letzte Siegelzeichen, das benötigt wird, um das Siegel auf dem Grabmal von Thoras Trollbane zu öffnen, wird von seinem Sohn höchstpersönlich aufbewahrt. Er hält sich tief innerhalb Stromgardes auf, in einer Kapelle in den von der Miliz bewachten Distrikten. Prinz Galen wird gut bewacht und da er selbst ein ausgezeichneter Krieger ist, wird diese Aufgabe wahrscheinlich die schwierigste sein.", progress = "Ihr seid zurückgekehrt, <Name>. Ist die Linie des Ignaeus Trollbane zerbrochen?", completion = "Was für ein Tag, &lt;Klasse&gt;. Das Blut der Trollbane wird nicht länger mein Volk verfolgen und die Siegelzeichen, die wir brauchen, um Trol'kalar an uns zu nehmen, befinden sich allesamt in unserem Besitz. Bald schon, sehr bald, werden wir gegen die verhassten Trolle von Zul'Gurub losschlagen können.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[645] = {title = "Trol'kalar", objective = "Holt Trol'kalar aus Trollbanes Grabmal in Stromgarde.", description = "Was ist das? Die vier Siegelzeichen haben sich zu einem Siegelzeichen zusammengefügt. Ohne Zweifel ist dieses in der Lage, die Schutzzeichen zu zerbrechen, die sich auf Trollbanes Grabmal befinden.\n\nTrollbanes sterbliche Überreste sind im Sanktum hinter der Kapelle in Stromgarde zur Ruhe gebettet worden. Holt Trol'kalar.", progress = "Gravuren auf dem Stein auf der Oberseite von Trollbanes Grabmal zeichnen genau die glühenden Linien des Siegelzeichens von Ignaeus nach...", completion = "Nachdem die Linien auf dem Stein auf der Oberseite von Trollbanes Grabmal genau den glühenden Linien des Siegelzeichens von Ignaeus angeglichen wurden, wird das Siegelzeichen von einem Lichtblitz eingehüllt und das legendäre Schwert Trol'kalar wird aus der Umklammerung der steinernen Hand freigegeben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[646] = {title = "Trol'kalar", objective = "Bringt Trol'kalar zu Zengu nach Hammerfall.", description = "Das Licht verglüht langsam, das Schwert Trol'kalar, das sich in einer steinernen Scheide befindet, ist freigegeben.", progress = "<Name>! Habt Ihr das Schwert geholt?", completion = "Generation um Generation haben die Streitkräfte von Strom und Arathor die Trolle vernichtet. Jetzt ist ihre größte Waffe in unseren Händen. Unsere winzigen Fortschritte in den dampfenden Wäldern von Zul'Gurub gehören der Vergangenheit an.\n\nIhr wart eine große Hilfe, &lt;Name&gt;, und die Trolle der Darkspear stehen tief in Eurer Schuld.\n\nIch werde sicherstellen, dass das Schwert zu Nimboya in Grom'gol gebracht wird.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBlutverschmierte RüstungGrubenkämpferschild\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[647] = {title = "MacKreels Fusel", objective = "Bringt MacKreels Fusel zu Braumeister Bilger nach Southshore.", description = "Was hab ich gestern gesoffen! Longbraid würde mich sofort köpfen, wenn er wüsste, dass ich während meiner Wache eingepennt bin.\n\nMein Schädel brummt vielleicht. Fühlt sich an, als wäre eine ganze Brigade von Belagerungsmaschinen drübergerollt, dieses Gerumpel.\n\nOh weh, so spät schon! Hab Braumeister Bilger in Southshore versprochen, dass ich meine Schulden mit ein wenig Fusel bei ihm bezahlen würde.\n\nUnd ich hab nur noch 15 Minuten! Könntet Ihr ihm diese Lieferung nicht bringen, bitte? Und beeilt Euch!", progress = "Na, wie läufts denn, <Volk>?", completion = "Es geht doch nichts über Foggy MacKreels Fusel, der einem an kalten Tagen so richtig das Herz wärmt. Und ich dachte schon, der kleine Scheißer würde wieder mal mit der Bezahlung auf sich warten lassen. Ich danke Euch, Freund! Vielen herzlichen Dank!", rewards = "Ihr bekommt:\n\n"},
[648] = {title = "Rettet OOX-17/TN!", objective = "Eskortiert OOX-17/TN nach Steamwheedle und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay.", description = "Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms:\n\n\"Ich muss OOX-17/TN an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann. Er hat eine eingebaute Tarnvorrichtung, aber ich brauche etwas Zeit, um sie von hier aus wieder funktionstüchtig zu machen. Ihr müsst den Roboter von seinem derzeitigen Standort nach, sagen wir, Steamwheedle bringen! Das sollte der perfekte Ort für mein Vorhaben sein, und bis Ihr dort seid, sollte ich auch alles vorbereitet haben und online gehen können.\"\n\n\"Eskortiert ihn sicher bis zum Hafen und kommt dann zu mir nach Booty Bay! Oglethorpe Obnoticus - Ende!\"", progress = nil, completion = "Oh, IHR seid also der großartige Retter von OOX-17/TN! Ich kann Euch gar nicht sagen, wie dankbar ich für Eure Hilfe bin! Die Entwicklung meiner Serie von Leitrobotern ist noch nicht abgeschlossen, aber Eure Rettungsaktion hat mir ungezählte Stunden Bauzeit erspart, sowie ebenso viele Goldstücke an Kosten für eine Neukonstruktion!\n\nBitte sucht Euch einen von diesen Gegenständen hier aus. Hoffentlich könnt Ihr einen davon gebrauchen. Ich danke Euch nochmals für Eure großzügige Hilfe, meine Roboter und ich stehen tief in Eurer Schuld!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nOptomatischer DeflektorThermotastische Eieruhr\n\nIhr bekommt außerdem:\n\n"},
[649] = {title = "Bergung der Welle", objective = "Sprecht mit Malton Droffers in Orgrimmar.", description = "Ich habe eine kleine Bergungsaktion für Euch, und falls Ihr ein Liebhaber von feiner Welle seid, so wie ich, dann werdet Ihr diese Aufgabe lieben. Welle!\n\nDas ist ein Getränk, Schafskopf.\n\nEin verlassener Außenposten der Horde verfügt über ein Lager mit Hinterland-Honigwelle aus der Zeit, als sie noch im Geschäft waren. Solch feine Welle bekommt Ihr sonst nirgendwo! Einer von Maltons Strohmännern weiß Bescheid, also begebt Ihr Euch dorthin und bringt mir eine Kiste verpackter Welle und zwei für meine eigene Sammlung! Sprecht mit Malton, er wird Euch die Einzelheiten mitteilen.", progress = nil, completion = "Ach ja, wegen der Welle, die mein Vater möchte! Er will die Welle an eine Taverne hier in Orgrimmar verkaufen, aber wir würden mehr Geld bekommen, wenn sie sich in der Originalverpackung befinden würde. Ich kenne da jemanden, der das machen kann, und er befindet sich im Hinterland, wo auch die Welle ist. Aber er ist, ähm, ein Hochelf.\n\nNa ja, er ist ein guter Hochelf, da er kein Anhänger der Allianz ist. Na ja, er ist weniger ein guter Hochelf als ein betrunkener Hochelf. Er liebt und ich meine LIEBT den Alkohol.", rewards = "Ihr bekommt:\n\n"},
[650] = {title = "Bergung der Welle", objective = "Sprecht mit Gilveradin Sunchaser; sein Lager befindet sich im Hinterland.", description = "Der Elf, mit dem Ihr sprechen müsst, ist Gilveradin Sunchaser. Er erkennt jeden Wein, mit Jahrgang und allem, allein am Geruch! Er kann die Welle verpacken, die wir benötigen, daher müsst Ihr mit ihm sprechen. Sechs Flaschen müssen verpackt werden, zwei für meinen Vater, und so viele wie er selbst will... und glaubt mir, er wird welche wollen. Wenn Ihr die Welle verpackt habt und auch die zwei Flaschen für meinen Vater, dann kommt hierher zurück!\n\nGilveradins Lager befindet sich in der Nähe einer Hochelf-Lodge im Hinterland, und diese Hochelfen führen nichts Gutes im Schilde. Glaubt mir.", progress = nil, completion = "Ah, Ihr kennt also Malton? Er ist ein alter Saufkumpan von mir. Seht, ich habe etwas gefunden, das die Grenzen künstlicher Verträge und Allianzen überspringt - Alkohol. Wenn wir alle unseren Durst an seinen glückseligen Qualitäten löschen würden, würden wir uns spirituell an einem viel besseren Ort befinden.\n\nAber etwas sagt mir, dass Euer Besuch hier nicht dem Zweck dient, etwas über die erlösenden Werte des Alkohols zu erfahren, nicht wahr?", rewards = "Ihr bekommt:\n\n"},
[651] = {title = "Steine der Bindung", objective = "Holt den brennenden Schlüssel, den Wappenschlüssel und den donnernden Schlüssel vom Stein der westlichen Bindung, dem Stein der östlichen Bindung und dem Stein der äußeren Bindung.", description = "Vier Steine der Bindung sind in ganz Arathi verteilt. Diese Steine halten mich unter der Erde fest.\n\nUm sie zu öffnen, müsst Ihr den stärksten öffnen: den Stein der inneren Bindung. Um das tun zu können, müsst Ihr Schlüssel von den drei Übrigen sammeln.\n\nDiese Steine werden von Wächtern bewacht, aber wenn Ihr es geschickt anstellt oder Glück habt, findet Ihr vielleicht einen Weg, sie auszuschalten.", progress = "Dies ist der Stein der inneren Bindung. Er ist der stärkste der Bindungs-Steine und muss erst aufgeschlossen werden, damit die anderen sich öffnen.", completion = "&lt;Myzrael spricht durch den Stein.&gt;\n\nIhr habt es geschafft! Ihr habt die Steine der Bindung geöffnet! Ich fühle, wie meine Fesseln sich lösen und die Freiheit immer näher rückt.\n\nIhr seid ein edelmütiger &lt;Klasse&gt;, &lt;Name&gt;. Mein Retter!", rewards = "Ihr bekommt:\n\n"},
[652] = {title = "Den Hauptstein zerbrechen", objective = "Findet und tötet Fozruk. Bringt die Rute der Ordnung zum Hauptstein im Arathihochland.", description = "Das Öffnen der Steine der Bindung hat den Großteil meiner Fesseln gelöst, aber ein Schloss hält mich immer noch gefangen. Es ist der Hauptstein, den Ihr in diesem Kreis von Steinen sehen könnt. Und der Schlüssel wird von einem meiner Häscher bewahrt, dem Steinbehüter Fozruk.\n\nIhr müsst diesen Schlüssel, den die Steinbehüter die Rute der Ordnung nennen, von Fozruk in Besitz nehmen und mit ihm den Hauptstein öffnen.\n\n<Name>, Ihr habt schon so viel für mich getan. Nur noch eine kleine Hilfe... und meine Dankbarkeit wird die Erde in ihren Grundfesten erschüttern!", progress = "Der Hauptstein ist mit einer enormen geomantischen Energie aufgeladen.", completion = "Ihr platziert die Rute im Hauptstein. Und fühlt unter Euch eine Erschütterung...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[653] = {title = "Myzraels Verbündete", objective = "Sprecht mit Gerrig Bonegrip im düsteren Viertel von Ironforge.", description = "<Myzrael spricht.>\n\nFrei! ICH BIN FREI! Ich bin frei und kann meine Kräfte sammeln, verborgen vor denen, die mich gefangen nahmen. Denn wenn ich mich ihnen jetzt stellen müsste, würden sie mich sicherlich überwältigen und erneut einkerkern.\n\nAber bald werde ich mich den Riesen stellen und sie werden es bitter bereuen, mich als Gefangenen gehalten zu haben!\n\nIhr seid ein edelmütiger Verbündeter, <Name>. Ich werde Eure Hilfe bald wieder benötigen. Wenn ich bereit bin, müsst Ihr mich an die Oberfläche beschwören.\n\nSprecht mit Gerrig Bonegrip. Er befindet sich in Ironforge in einem Geschäft im düsteren Viertel. Er weiß, wie ich beschworen werden kann.", progress = nil, completion = "Die Fürstin sagte mir, dass Ihr kommen würdet, &lt;Klasse&gt;. Ihr seid in meiner Hütte willkommen, denn Ihr dient einem höheren Ziel, genau wie ich selbst.", rewards = "Ihr bekommt:\n\n"},
[654] = {title = "Tanaris-Feldproben", objective = "Sammelt akzeptable Proben von 8 Basilisken, 8 Hyänen und 8 Skorpionen. Bringt das Testset zurück nach Gadgetzan zu Chefingenieur Bilgewhizzle, bevor die Kraftquelle erschöpft ist.", description = "Nach Aktivierung der Kraftquelle beginnt das Feldtestset zu glühen und zu vibrieren. Es scheint, als würde es funktionieren wie geplant.\n\nLaut Chefingenieur Bilgewhizzle habt Ihr zwei Stunden Zeit, um die benötigten Daten in der Tanariswüste zu sammeln. Falls Ihr sie nicht innerhalb von zwei Stunden sammelt, gehen alle Daten verloren und Ihr müsst eine weitere Kraftquelle von ihm erstehen.\n\nKehrt zu ihm zurück, wenn Ihr Eure Aufgabe erfüllt habt.", progress = "Na, habt Ihr alles bekommen, was Ihr benötigt? Falls Ihr es nicht geschafft habt und die Kraftquelle erschöpft ist, ist alles im Inneren ruiniert und Ihr müsst wieder von vorn beginnen.\n\nHey, erwartet von mir kein Mitgefühl; mich interessiert nur, ob die Gadgetzan Water Company Profit macht, und wenn das bedeutet, dass ich Euch Kraftquellen verkaufe, bis wir es uns leisten können, Wasser von den eisigen Quellen von Dun Morogh zu importieren, dann sei es so!", completion = "Also gut, ich benötige nur einen Moment, um die Kraftquelle zu entfernen. Danach könnt Ihr damit machen, was Ihr wollt, ohne Euch darum sorgen zu müssen, dass Ihr die Daten im Inneren verliert.", rewards = "Ihr bekommt:\n\n"},
[655] = {title = "Hammerfall", objective = "Sprecht mit Tor'gan in Hammerfall.", description = "Ich erinnere mich, als wär es gestern gewesen... So viele Jahre ohne Hoffnung, mit Holz und Stahl, die mich an diesen fürchterlichen Ort banden. Und dann endlich, endlich! Da war der Kriegshäuptling. Doomhammer in seiner Mitternachtsrüstung, sein Kriegshammer hoch erhoben.\n\nEs war... zu schrecklich... Dass der Schlag eines Feiglings unseren größten Helden niederschlagen konnte. Er kam von hinten angestürmt auf seinem Pferd und dann rammte er seine Lanze einfach durch ihn hindurch... Ich fiel auf die Knie. Welche Hoffnung gab es noch? Welche Hoffnung gibt es noch...", progress = nil, completion = "Ach, Ihr sprecht von Gor'mul. Ja, von dem, was er so erzählt, scheint es, als hätte er sich niemals ganz vom Tod Doomhammers erholt.\n\nGor'mul war Gefangener hier als Thrall und Orgrimm um die Befreiung des Lagers kämpften, aber als die Erde bebte und unsere Brüder entkamen, blieb er hier zurück. Er wanderte jahrelang allein und verloren ohne Richtung oder Hoffnung umher, bis wir zurückkamen, um uns hier in Hammerfall eine Heimat aufzubauen.", rewards = "Ihr bekommt:\n\n"},
[656] = {title = "Beschwören der Prinzessin", objective = "Geht zu den Splittern von Myzrael, beschwört und besiegt sie.\n\nSammelt ihre geisterhaften Fesseln, und bindet diese an die Splitter von Myzrael.", description = "Ihr müsst Myzrael besiegen, bevor ihre Kraft größer wird. Wenn Ihr es nicht tut, wird sie ihre Häscher herausfordern, sobald sie genug Stärke gesammelt hat! Einige glauben zwar, dass man sie kontrollieren könnte, aber wenn sie kontrolliert werden kann, warum haben die Riesen sie dann überhaupt in Fesseln gelegt?\n\nSeltsame Logik, nicht?\n\nUm sie zu besiegen, beschwört sie bei den Splittern von Myzrael, wo Ihr zuerst mit ihr spracht. Besiegt sie und sammelt ihre geisterhaften Fesseln ein. Bindet diese dann an die Splitter von Myzrael.\n\nTut das, und sie wird erneut gefangen sein.", progress = "Die Splitter von Myzrael sind jetzt seltsam ruhig.", completion = "Als die geisterhaften Fesseln um die Splitter gelegt werden, ist von tief unten ein unmenschliches Heulen zu hören. Dem Heulen folgt ein Brüllen.\n\nDie Splitter von Myzrael rufen nicht mehr das gleiche Gefühl von Wärme und Sicherheit hervor, wie es zuvor der Fall war. Jetzt pulsieren sie mit einer offenen Bedrohung... als ob das, was sich unterhalb befindet, der Oberfläche Böses will.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nPulsierender Kristallinsplitter"},
[657] = {title = "Hinweise auf eine neue Seuche?", objective = "Sprecht mit Kinelory.", description = "<Quae beginnt, den Ordner durchzusehen.>\n\nDas IST interessant. Es scheint, als habe Apotheker Jorell an einigen tödlichen Experimenten hier in Go'Shek gearbeitet. Bin nicht sicher, was das mit Hillsbrad zu tun hat, aber Phin würde es nicht gefallen, wenn wir das einfach so laufen ließen.\n\nWährend Ihr fort wart, hatten wir ein Zusammentreffen mit ein paar Orcs und ich bin nicht in der geeigneten Verfassung, um Kinelory zu helfen. Wenn Ihr es vermögt ... Sie wird Schutz gut gebrauchen können, wenn sie zum Hof geht, um zu stehlen, was Jorell noch nicht nach Tarrens Mühle geschickt hat.", progress = nil, completion = "Wenn es Phin was hilft, zerquetsche ich jeden Einzelnen der Verlassenen höchstpersönlich. Seit der Seuche hat er so viel für uns getan. Niemand von uns hätte gedacht, dass wir noch mal Familie oder Freunde wiedersehen würden.\n\nWenn Ihr fertig seid, gebt mir Bescheid. Dann können wir sofort beginnen.", rewards = nil},
[658] = {title = "Hinweise auf eine neue Seuche?", objective = "Findet den Kurier der Verlassenen und bringt den versiegelten Ordner zu Quae in der Nähe von Go'Sheks Hof.", description = "Phin hat Euch also geschickt, um nach uns zu sehen? Wundert mich nicht - er macht sich zu viele Sorgen.\n\nWir beobachten den Hof seit Tagen, und Kin sagt, es sei noch gar nicht so lange her, dass sie einen Kurier aus dem kleinen Haus da südlich hat kommen sehen.\n\nSie erzählt viel, aber ich kann ihrem Instinkt immer trauen, wenn wir uns auf gefährlichem Terrain befinden.\n\nIhr seid nicht zufällig ein geschickter Fährtenleser, oder? Wir glauben, dass der Kurier Notizen nach Tarrens Mühle bringen könnte. Wenn wir diese Dokumente in die Hände bekommen könnten, könnten wir vielleicht Näheres über die Vorgänge in Hillsbrad erfahren.", progress = "Wir danken für Eure Hilfe bei der Suche nach diesem Kurier, <Name>.\n\nWährend Ihr fort wart, konnte Kin einen Apotheker beobachten, der aus demselben Haus südlich von hier herauskam. Ich bin ziemlich sicher, dass sie nichts Gutes im Schilde führen - aber ich brauche Beweise, bevor wir unüberlegt einfach drauflos hauen.\n\nHattet Ihr Glück?", completion = "Exzellent! \n\nDann lasst uns mal sehen, was das alles soll...", rewards = "Ihr bekommt:\n\n"},
[659] = {title = "Hinweise auf eine neue Seuche?", objective = "Findet Quae und Kinelory in der Nähe von Go'Sheks Hof im Arathihochland.", description = "Seid mir gegrüßt, <Name>. Ich bin der Anführer einer Abenteurergruppe, die die seltsamen Vorgänge in diesem Gebiet untersucht.\n\nMein Cousin in Hillsbrad musste letztens seinen Hund Stanley einschläfern lassen, weil das Tier seltsamerweise auf eine immense Größe heranwuchs und jeden bösartig angegriffen hat, der ihm näher kam.\n\nIch glaube, dass die Untoten darin verwickelt sind, und wir suchen nach Anzeichen, die das bestätigen.\n\nZwei meiner Kameraden, Quae und Kinelory, haben sich zur Go'Sheks Hof im Arathihochland aufgemacht und haben seit Tagen nichts von sich hören lassen. Könntet Ihr sie für mich finden? Ich mache mir langsam Sorgen.", progress = nil, completion = "Versucht so leise wie möglich zu sein, Reisender.\n\nOrcs mögen es gar nicht, wenn sie bespitzelt werden, und auf dieser Farm ist mehr los als der erste Anblick es vermuten lässt.", rewards = "Ihr bekommt:\n\n"},
[660] = {title = "Hinweise auf eine neue Seuche?", objective = "Beschützt Kinelory bis sie zu Quae zurückkehrt.", description = "Nun gut, <Name>. Bereit, wenn Ihr es seid.\n\nSollen wir?", progress = "Die Zeit der Gespräche ist vorbei. Wenn Euch die Bewohner von Hillsbrad auch nur das Geringste bedeuten, dann beschützt Ihr Kinelory.", completion = "Ihr habt uns einen großen Dienst erwiesen, &lt;Name&gt;. Danke.\n\nIch hoffe, Kin hat Euch da unten nicht zu sehr auf Trab gehalten. Sie ist sehr freundlich, aber sie kann genauso tödlich sein, wenn Ihr sie zum Feind habt.", rewards = "Ihr bekommt:\n\n"},
[661] = {title = "Hinweise auf eine neue Seuche?", objective = "Findet Phin Odelic in Southshore.", description = "Kinelory sah nach einer Nacht in der Taverne schon schlechter aus als jetzt. Ihr habt sie offensichtlich sehr gut beschützt.\n\nDiese Gegenstände, die sie von der Farm mitgebracht hat, sollten Phin zumindest einen Anhaltspunkt davon geben, was in Arathi so vor sich geht. Wir werden hier noch ein Weilchen bleiben, nur um sicherzugehen, dass nach Eurem Angriff kein Gegenschlag kommt. Wärt Ihr bereit, nach Southshore zurückzukehren und mit Phin zu sprechen?", progress = nil, completion = "Also geht's den beiden Unruhestiftern doch gut? Haha, es freut mich, das zu hören. Ich danke Euch, dass Ihr mir von ihrem Aufenthaltsort und Status berichtet habt - es freut mich sehr, dass sie noch am Leben sind, die beiden sind als Freunde und Reisegefährten praktisch unersetzlich.\n\nAber ... es ist wichtiger, dass ich Euch richtig für Eure Hilfe danke. Hier, nehmt dies, zusammen mit dem Dank meiner Gruppe.\n\nMit ein wenig Glück können wir herausfinden, was die Verlassenen vorhaben und dem ein Ende bereiten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDustfall-RobenGamaschen des leichten Schritts\n\nIhr bekommt außerdem:\n\n"},
[662] = {title = "Tiefsee-Bergung", objective = "Der erste Maat Nilzlix will, dass Ihr die Karten und Logbücher von der TOLLEN MINNA und der SILBERGEIST zurückholt.", description = "O'Breen führte die Schiffe in die Bucht. Wir waren ziemlich sicher, dass der Schatz dort zu finden sei. Die HARBINGER konnte noch sicher andocken, aber als die TOLLE MINNA und die SILBERGEIST näher kamen, senkte sich der Meeresspiegel plötzlich ab. So was Seltsames hab ich mein Lebtag nich' gesehn!\n\nDiese beiden Schiffe sind auf irgendetwas aufgelaufen... eine Art Tempel im Riff. Sie sind irre schnell gesunken, eine echte Tragödie.\n\nWir müssen ihre Logbücher und auch ihre Karten wiederbekommen, bevor wir hier wieder weg sind. Wir dürfen diese Informationen nicht einfach für neugierige Augen zurücklassen.", progress = "Wie läuft die Suche und Bergungsmission, <Name>? Diese Karten und Logbücher von der TOLLEN MINNA und der SILBERGEIST brauchen wir wirklich.\n\nWenn die Informationen aus diesen Quellen in Feindeshand gelangen, lässt Flottenmeister Seehorn uns über die Planke laufen.\n\nDas heißt, natürlich nur, wenn wir jemals aus diesem Schlamassel rauskommen...", completion = "Dass diese Informationen gesichert sind, wird das Kommando in Booty Bay etwas beruhigen. Gut gemacht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSchwarzmeerhammer"},
[663] = {title = "Land Ho!", objective = "Sprecht mit Kapitän O'Breen in der Faldirbucht.", description = "Lolo sieht was Winziges, es ist ein <Volk>! Immerzu Ausschau halten, ja, ja, das tut Lolo!\n\nWillkommen in der Faldirbucht. Kapitän O'Breen hat gesagt, dass wir nur für ein paar Stunden hier wären. Grad lang genug, um den Schatz einzusammeln und zurück nach Booty Bay zu segeln.\n\nAber Lolo denkt, dass wir noch sehr lange hier bleiben werden. Wir haben die anderen beiden Schiffe von unserer Formation verloren. Die arme SILBERGEIST und die arme TOLLE MINNA. Sie ruhen jetzt auf dem Grund des Meeres!\n\nLolo schlägt vor, dass Ihr mit Kapitän O'Breen sprecht, wenn Ihr länger hier bleiben wollt.", progress = nil, completion = "Ahoi, Kumpel.\n\n's war fürchterlich. Seehorn wird mir mein Schiff nehmen, wenn er rausfindet, was los war.\n\nEiner der Apparate des Professors zeigte an, dass der verlorene Schatz in der Nähe dieser Bucht zu finden sei. Ich hab die HARBINGER anlegen lassen und der SILBERGEIST und der TOLLEN MINNA signalisiert, das Gleiche zu tun.\n\nDann rumpelte das Meer. Die Tide senkte sich ab und die beiden Schiffe krachten in das Riff.\n\nEs ist nicht nur ein Riff. Da unten ist etwas...\n\nHelft meiner Crew und Ihr werdet reich belohnt.", rewards = "Ihr bekommt:\n\n"},
[664] = {title = "Ertrunkene Trauer", objective = "Captain Steelgut in der Faldirbucht will, dass Ihr 10 Räuber der Säbelflossen und 3 Zauberhexerinnen der Säbelflossen tötet.", description = "Grr, 's ist ein elendes Leben. Ich sollte in meinem nassen Grab liegen und nicht hier am Feuer sitzen und frische Luft atmen.\n\nDie Crew hat ihr Bestes gegeben um meine wunderschöne TOLLE MINNA zu retten. Gesegnet seien die Jungs, gesegnet ihre Herzen.\n\nO'Breen hat es sicher ans Ufer geschafft, aber wir hatten nicht so viel Glück. Das Meer sank einfach auf uns herab, ich schwöre es!\n\nIn der einen Sekunde lagen wir auf dem Wasser und in der nächsten stürmte das Wasser auf uns ein. Und diese Bestien! Haben alle Überlebenden getötet. Elender Nagaabschaum. Mir gingen die Lichter aus und ich kam hier oben wieder zu mir, gerettet.\n\nIch will diese Biester tot sehen.", progress = nil, completion = "Ihr habt da draußen gute Arbeit geleistet, &lt;Name&gt;.\n\nDieser Abschaum hat bekommen, was er verdient. Auch wenn nichts auf der Welt mir jemals mein Schiff oder meine Crew zurückbringen wird, der Tod der Naga tröstet mich ein wenig.", rewards = "Ihr bekommt:\n\nSeewolf-Handschuhe"},
[665] = {title = "Versunkener Schatz", objective = "Begleitet Professor Phizzlethorpe zur Höhle und zurück.", description = "Da wir jetzt richtige Schwarzmeerräuber sind, ist es nun unsere Aufgabe, Herrn O'Breen bei der Suche nach dem verlorenen Elfenschatz behilflich zu sein.\n\nEs ist fast unmöglich, die Edelsteine ohne Hilfe im dunklen Meer zu finden. Der Doktor hat eine Schutzbrille konstruiert, die dabei hilft. Er muss die Schutzbrille mit der Energie aufladen, die von dem verzauberten Stein in der Höhle auf dem Hügel dort ausgeht.\n\nAber die Höhle ist verflucht! Sobald wir uns ihr nähern, werden wir überfallen. Wenn Ihr mich verteidigt, kann ich die Energie vom Stein in die Schutzbrille leiten.", progress = "Jetzt ist nicht die Zeit zum Reden! Die Schutzbrille muss mit der Kraft des Steins aufgeladen werden!", completion = "Jetzt funktioniert die Schutzbrille perfekt! Gut gemacht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[666] = {title = "Versunkener Schatz", objective = "Doktor Draxlegauge in der Faldirbucht will, dass Ihr 10 Elfen-Edelsteine einsammelt und die Edelsteinjagdschutzbrille zurückgebt, sobald Ihr fertig seid.", description = "Der Schatz befand sich so lange auf dem Meeresboden, dass die Edelsteine von einer dicken Kalkschicht umgeben sind. Aber die Macht, die in dieser Schutzbrille gefangen ist, wird Euch ermöglichen, sie leicht zu finden.\n\nEin wenig gnomischer Einfallsreichtum ist schon was Schönes!\n\nAlso nehmt Euch die Edelsteinjagdschutzbrille, <Name>, und versucht, ein wenig vom verlorenen Schatz für Kapitän O'Breen einzusammeln.\n\nIch würde ja selbst hinuntertauchen, aber... ähem... ich, nun ich muss mich um äußerst wichtige wissenschaftliche Dinge kümmern, oben auf dem sicheren, trockenen Land... ähem, ja.", progress = "Wie lief es mit der Schutzbrille? Hat alles korrekt funktioniert? Änderungen können durchgeführt werden, falls es notwendig ist.\n\nOh, und ich brauche die Schutzbrille zurück, wenn Ihr fertig seid. Ich bin sicher, Kapitän O'Breen wird sie später für verschiedene Dinge gut gebrauchen können.", completion = "Absolut superb, &lt;Name&gt;. Der Kapitän wird sehr erfreut sein! Und wartet nur, bis Flottenmeister Seehorn davon erfährt!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGnomen-SchrumpferServomechanischer Vorschlaghammer\n\nIhr bekommt außerdem:\n\n"},
[667] = {title = "Tod von unten", objective = "Beschützt Shakes O'Breen während des Angriffs.", description = "Das ist übel. Es scheint, als ob die Säbelflossen sich zum Angriff sammeln.\n\nNaga sind bekannt für ihre Ruchlosigkeit im Kampf. Sie werden so lange angreifen, bis ich tot bin.\n\nIch schätze mein eigenes Leben nicht höher als das meiner Crew, aber Ihr müsst helfen, mich zu verteidigen. Die Crew ist nicht in der Lage, ohne meine Kenntnisse des Meeres nach Booty Bay zurückzufinden.\n\nDie Naga werden vom Meer her kommen. Ihr müsst mit mir hier oben bleiben, um den Angriff abzuwehren. Bemannt die Kanone und treibt sie zurück.\n\nSeid Ihr bereit, <Name>?", progress = nil, completion = "Wir haben den Angriff überlebt!\n\nOhne Euch hätten wir es nicht geschafft, &lt;Name&gt;.\n\nSobald die Flut kommt, werden wir hier wegsegeln. Wenn Ihr nicht ein so viel versprechender Held wärt, würde ich Euch einen Platz in meiner Crew anbieten. Aber ich seh schon, Ihr habt Größeres vor.\n\nAuch wenn Ihr nur ein schwacher &lt;Volk&gt; seid...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKaltwasserringSeefeuerband\n\nIhr bekommt außerdem:\n\n"},
[668] = {title = "Versunkener Schatz", objective = "Bringt die Elfen-Edelsteine zu Kapitän O'Breen.", description = "Wir sollten Kapitän O'Breen nicht warten lassen. Er wird diese Edelsteine sofort sehen wollen. Darum sind wir ja schließlich hier!\n\nUnd nach ein paar Wochen Zusammenleben mit diesen Piraten sind der Professor und ich zum Schluss gekommen, dass es ganz und gar nicht gut für unsere Gesundheit ist, wenn sie denken, dass wir uns ihre Schätze einverleiben wollen.\n\nHier, <Name>, bringt das zu O'Breen.", progress = "Ahoi, <Klasse>. Was führt Euch auf die Brücke?", completion = "Also haben die kleinen Gnome doch bewiesen, dass sie was wert sind? Wusste ich doch, dass wir diese Wadenbeißer nicht umsonst behalten haben!", rewards = "Ihr bekommt:\n\n"},
[669] = {title = "Versunkener Schatz", objective = "Bringt die Probe zu Flottenmeister Seehorn nach Booty Bay.", description = "Flottenmeister Seehorn will über unseren Fund sofort informiert werden.\n\nAber, wie Ihr selbst sehen könnt, sind wir nicht unbedingt in der Lage, von hier wegzukommen. Es ist nicht nur der zu niedrige Wasserstand, sondern auch diese verdammten Viecher, die wir gestört haben, und die jetzt jede unserer Bewegungen aufs Genaueste beobachten.\n\nIhr könnt den Schwarzmeerräubern einen sehr großen Dienst erweisen, wenn Ihr Flottenmeister Seehorn in Booty Bay davon in Kenntnis setzen könntet, dass wir den Schatz gefunden haben und dabei sind, weitere Steine zu bergen. Bringt ihm diese Probe zum Beweis.", progress = "Was führt Euch nach Booty Bay, <Klasse>?", completion = "Ah, der gute alte Shakes O'Breen schafft es doch immer! Ich wusste, dass er der richtige Kapitän für diese Mission war!", rewards = "Ihr bekommt:\n\n"},
[670] = {title = "Versunkener Schatz", objective = "Bringt Seehorns Brief zu Kapitän O'Breen im Arathihochland.", description = "Sagt, <Name>, Ihr seht aus wie jemand, der einem Abenteuer nicht abgeneigt ist. Meine Flotte liegt hier in Booty Bay fest, bis wir unsere Vorräte auffüllen können.\n\nHier und auch außerhalb braut sich so einiges zusammen und ich muss ein paar äußerst geheime Nachrichten an Shakes O'Breen übermitteln, der vor der Arathi-Küste festsitzt.\n\nKann ich auf Euch vertrauen, dass Ihr diese Nachricht sicher und unberührt überbringt?", progress = "War Seehorn beeindruckt? Ich wette mit Euch, sein Grinsen reichte von Booty Bay bis Ratchet.", completion = "Ich danke Euch, dass Ihr eine solch lange und gefährliche Reise auf Euch genommen habt. Die Dankbarkeit der Schwarzmeerräuber ist Euch sicher.", rewards = "Ihr bekommt:\n\n"},
[671] = {title = "Elende Magien", objective = "Holt 10 Blutsteinamulette für Tor'gan in Hammerfall.", description = "Ich fühlte etwas Fremdes in der Luft... ein Gefühl, das mein Blut köcheln lässt. Ich hatte auch schon einen Verdacht. Ich bin ausgezogen, um die Quelle meiner Unruhe aufzuspüren, und im Northfold-Anwesen im Westen fand ich restliche Spuren einer Dämonenbeschwörung. Als ich näher kam, begann mein Blut zu sieden und die Wut in mir wuchs.\n\nAuf dem Boden entdeckte ich ein Blutsteinamulett, das bei Dämonenbeschwörungen als Hilfe benutzt wird. Das Amulett, das ich fand, war jedoch entleert. Ich benötige ein weiteres, um es zu untersuchen, aber ich wage nicht, zum Anwesen zurückzukehren. Könnt Ihr mir ein paar bringen?", progress = "Ich habe immer noch einstmals verfluchtes Blut in meinen Adern, <Name>. Wenn jemand... etwas Dämonen beschwört, muss das beendet werden.", completion = "Ich werde einige Zeit brauchen, bis ich die wahren Absichten des Syndikats enthüllen kann, aber ihre offensichtliche Verbindung zur dunklen, dämonischen Magie beunruhigt mich sehr. Ich werde Euch Nachricht geben, sobald ich mehr weiß.", rewards = "Ihr bekommt:\n\n"},
[672] = {title = "Mut machen", objective = "Bringt 10 Hochlandraptorenaugen von Hochlandschreitern und Hochlandhauern zu Tor'gan in Hammerfall.", description = "Wir haben versucht, es ihm gemütlich zu machen, ihn aufzumuntern, haben ihm Geschichten erzählt von unserer mächtigen Stadt in Orgrimmar in Kalimdor, aber nichts, gar nichts hat ihn berührt.\n\nGeschichten von unserem jungen Kriegshäuptling, Thrall, der die Rüstung und den Hammer von Orgrim trägt... aber vielleicht... Vielleicht! Eine kleine Demonstration von unserer neu gefundenen Schamanen-Magie könnte ihm neue Hoffnung geben. Einen Versuch ist es wert!\n\nEin kleines Objekt könnten wir für ihn machen, ja... Bringt mir ein paar Raptoraugen und ich werde sehen, was ich tun kann.", progress = "Ich werde ein Amulett herstellen, das Gor'mul ein wenig Raptorenkraft verleiht. Vielleicht kann das ein kleines Feuer in ihm entfachen...", completion = "Exzellent. Die Geister der Raptoren, die uns diese Augen gaben, werden dem Träger dieses Amuletts Kraft verleihen.", rewards = "Ihr bekommt:\n\n"},
[673] = {title = "Elende Magien", objective = "Bergt Marez Cowls Blutsteinkugel und bringt sie zu Tor'gan in Hammerfall.", description = "Ich habe keinerlei Zweifel, dass ein mächtiger Hexenmeister sich innerhalb der Mauern Stromgardes aufhält. Von Zeit zu Zeit hat dieser Hexenmeister mit Hilfe eines arkanen magischen Relikts abscheuliche Dämonen in großer Zahl herbeibeschworen. Wir müssen ihm die Quelle seiner Energie nehmen.\n\nSucht den Hexenmeister und tötet ihn. Bringt mir alle magischen Objekte, die Ihr bei ihm finden könnt, und ich werde die geeigneten Schritte unternehmen, sie zu zerstören, damit ihre Macht nicht mehr dazu benutzt wird, dieses Land weiterhin zu besudeln.", progress = "Das Brennen in meinem Blut... es wird mit jedem Tag stärker. Der Hexenmeister muss aufgehalten werden.", completion = "Meine rastlosen Nächte werden sich in einen friedvollen Schlummer wandeln, sobald ich diese Kugel zerstört habe. Danke, &lt;Name&gt;. Es ist eine eiskalte Erinnerung an die grausame Macht, die die Dämonen über die Orcs hatten, bevor Hellscream uns von ihrem Fluch befreit hat.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWeiße DrachenhautkappeStrahlende Silber-Armschienen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[674] = {title = "Mut machen", objective = "Gebt das Raptorkrallen-Amulett an Gor'mul.", description = "Hier, übergebt dieses Amulett Gor'mul und beobachtet, ob die Kraft der Raptoren das Feuer des Kriegers, das einst in seinen Adern brannte, erneut erwecken kann.", progress = "Welche Hoffnung gibt es noch, wenn der Mächtigste der Mächtigen durch die Hand eines Feiglings erschlagen werden kann? Welche Hoffnung, sagt es mir?", completion = "Was ist dies? Polierte Knochen. Was soll ich mit polierten Knochen anfangen? Wird so ein Tand die Horde wieder zu ihrem alten Ruhm führen?", rewards = "Ihr bekommt:\n\n"},
[675] = {title = "Mut machen", objective = "Sprecht mit Tor'gan.", description = "<Gor'mul wirft das Amulett zu Boden.>\n\nTor'gans hat Euch geschickt, oder? Pah! Warum er mir gegenüber Gnade empfindet, geht über meinen Verstand. Gnade wurde mir verweigert, als es mir nicht vergönnt war, mit meinem Kriegshäuptling im Kampf zu sterben. Das Schicksal hat mir einen harten Schlag versetzt ...", progress = nil, completion = "Wie ich sehe, hat es nicht funktioniert. Nichtsdestotrotz glaube ich, dass die Vorführung der Schamanen-Macht Gor'mul schließlich doch wieder zu seinem ehemals stolzen Selbst zurückführen kann. Die Macht des Amuletts war einfach nicht stark genug, um ihn von unserer wiedergefundenen Macht zu überzeugen.", rewards = "Ihr bekommt:\n\n"},
[676] = {title = "Der Hammer kann fallen", objective = "Tötet 8 Oger der Felsfäuste und 10 Vollstrecker der Felsfäuste und sucht dann Drum Fel im Außenposten von Hammerfall im Arathihochland auf.", description = "Schwächlinge... alle miteinander. Ihr da, <Klasse>, was schaut Ihr so dämlich? Denkt wohl, Ihr seid was Besonderes, was? Wollt Ihr's nicht mal beweisen?\n\nDer Außenposten von Hammerfall in Arathi wird angegriffen. Wenn wir der Besatzung nicht bald Hilfe schicken, steht ihr Ableben unmittelbar bevor.\n\nAber bevor Ihr jetzt einfach losrennt, möchtet Ihr vielleicht Eure Fähigkeiten erst testen. Nordöstlich von Stromgarde in Arathi befindet sich ein Ogerhort, der von den Felsfaustogern bewohnt wird. Wenn Ihr die Oger und Vollstrecker dort in den Griff bekommt, erstattet Drum Fel in Hammerfall Bericht.", progress = nil, completion = "Ihr denkt also, Ihr seid stark genug, um Hammerfall zu helfen? So sei es denn.\n\nTallow hat Euch zu dem Ogerhort geschickt, weil er entweder hoffte, dass Ihr dort umkommt, oder denkt, dass Ihr stark genug seid, um uns zu helfen. Auf jeden Fall seid Ihr jetzt hier, und ich benötige dringend mehr Soldaten in unserem Kampf gegen die ständigen Angriffe.\n\nWenn Ihr länger in Hammerfall bleiben wollt, dann ruht Euch ein wenig aus und meldet Euch wieder bei mir, wenn Ihr bereit seid. Ihr werdet noch mehr als genug Gelegenheit zum Kämpfen haben.", rewards = "Ihr bekommt:\n\n"},
[677] = {title = "Zu den Waffen", objective = "Erschlagt 10 Axtwerfer der Witherbark, 10 Kopfjäger und 8 Hexendoktoren und kehrt zu Drum Fel im Außenposten von Hammerfall zurück.", description = "Die Trolle der Witherbark und die Felsfaustoger von Arathi arbeiten zusammen daran, uns von diesem Land zu vertreiben, aber unser Schicksal liegt weder in ihren noch in irgendwessen anderen Händen. Wir werden sie erledigen und ihnen zeigen, dass dies auch unsere Heimat ist. \n\nDie Trolle haben sich von uns abgewandt, die Oger würden uns als Nahrung und Bettvorleger benutzen, wenn wir es zuließen - das darf nicht sein.\n\nWir werden unseren Angriff auf die Trolle der Witherbark südlich von hier beginnen. Erschlagt sie in Scharen und kehrt erst zurück, wenn ihre Lager dick mit Blut bedeckt sind.", progress = nil, completion = "Die Zeichen des Krieges sind auf Eurer Kleidung und Schweiß tropft von Euren Brauen. Das ist gut, sogar sehr gut.", rewards = "Ihr bekommt:\n\n"},
[678] = {title = "Zu den Waffen", objective = "Tötet 10 Schläger der Felsfäuste und 4 Magi der Felsfäuste und sucht dann Drum Fel im Außenposten von Hammerfall auf.", description = "Eure Kraft ist offensichtlich, <Name>. Dann zeigt mal, wie Ihr Euch mit echten Feinden schlagt.\n\nDie Felsfaustoger haben einen Unterschlupf südwestlich von hier, Richtung der Zwergenbrücke, und, wenn ich mich nicht täusche, werden die Raufer und Magi dort eine etwas größere Herausforderung darstellen - für uns waren sie das bislang zumindest.\n\nErschlagt so viele wie Ihr irgend könnt und kommt persönlich zu mir, wenn Ihr erfolgreich seid, oder erscheint mir als Geist, wenn Ihr versagt. Ich werde Eure Beharrlichkeit in der Schlacht in jedem Falle preisen.", progress = nil, completion = "Ihr seid ebenso stark wie ein Kodo und Eure Kampfeslust macht Eurem Volk alle Ehre.", rewards = "Ihr bekommt:\n\n"},
[679] = {title = "Zu den Waffen", objective = "Tötet 15 Schamanen der Felsfäuste und 10 Lords der Felsfäuste und kehrt zu Drum Fel im Außenposten von Hammerfall im Arathihochland zurück.", description = "Der Kopf der Bestie kann abgetrennt werden... mit einem mächtigen Schlag, <Name>. Ihr habt alle Zeichen dafür gezeigt, dass Ihr in der Lage seid, uns mit diesem letzten mächtigen Schlag zu helfen. Die Anführer dieser Angriffe haben ihren Unterschlupf innerhalb der Ruinen von Stromgarde gewählt, einem grellen Symbol menschlicher Schwachheit.\n\nFindet und erschlagt diese Lords der Felsfäuste und ihre speichelleckenden Schamanen, die versuchen, uns aus diesem Land zu vertreiben.", progress = nil, completion = "Euer Volk kann stolz auf Euch sein, &lt;Name&gt;. Die Bedrohung konnte um ein Vielfaches verringert werden und ich bin überzeugt, dass wir uns hier im Hochland bald sehr heimisch fühlen werden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchweigsamer JägerSchädelspalter\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[680] = {title = "Die echte Bedrohung", objective = "Erschlagt Or'Kalar und bringt seinen Kopf zu Korin Fel in den Außenposten von Hammerfall.", description = "Ihr seid meinem Gemahl ein treuer Diener, <Klasse>, aber er weiß nicht, warum Hammerfall angegriffen wird.\n\nOr'Kalar, Mugh'thols Helfer in Stromgarde hasst meinen Gemahl aufs Äußerste, und er wünscht sich nichts mehr, als ihn tot zu sehen, da mein Gemahl ihn vor Jahren einmal besiegte.\n\nDie Vorzeichen verrieten mir, dass Or'Kalar eine Falle für meinen Gemahl ausgelegt hat. Aus diesem Grund habe ich Hinweise auf den Aufenthaltsort des Ogers vor ihm versteckt.\n\nMein Gemahl wird Hals über Kopf losschlagen, sobald er vom Aufenthaltsort des Ogers erfährt, und ich wollte Eure Hilfe bei der Tötung der Kreatur erbitten.", progress = "Ihr werdet Or'Kalar nahe dem Turm von Arathor finden. Sein Tod bedeutet das Ende der Angriffe auf Hammerfall und Schutz für das Leben meines Gemahls.\n\nIch sehe in Euren Augen, dass Ihr mich für schwach haltet - vielleicht sogar für unehrenhaft -, weil ich geschwiegen habe. Eines Tages werdet auch Ihr lernen, was es heißt, so zu lieben, wie ich es tue. Vielleicht werdet Ihr dann eine etwas andere Art von Stärke und Ehre verstehen können.\n\nAber bis dahin, tut, um was ich Euch bitte, und erschlagt Or'Kalar.", completion = "Ihr habt mir einen großen Dienst erwiesen, &lt;Name&gt;. Denn wisset, dass durch Eure Taten das Leben meines Gemahls und die Sicherheit von Hammerfall für einen weiteren Tag gewährleistet wurden. Bitte nehmt das als Belohnung für Euren Mut.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nNebelhauchkiltSchwert von Hammerfall\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[681] = {title = "Northfold-Anwesen", objective = "Tötet 10 Straßenräuber des Syndikats und 6 Söldner des Syndikats.\n\nKehrt zu Captain Nials bei der Zuflucht zurück.", description = "Wir kämpfen einen Kampf um Stromgarde, und wir verlieren ihn. Die Oger, das Syndikat und wir haben unsere einst große Stadt geteilt und jede Fraktion bekämpft die andere bis zu einem blutigen Unentschieden.\n\nAber unsere Streitkräfte schwinden, während unsere Feinde immer stärker werden.\n\nWir brauchen Hilfe aus der Stadt Southshore, aber Vorräte sind nur schwer zu bekommen, solange das Syndikat das Gebiet zwischen uns kontrolliert.\n\nBegebt Euch zum Syndikatsstützpunkt im Northfold-Anwesen und tötet sie alle. Dann wird der Druck auf unsere Versorgungszüge ein wenig nachlassen und ein größerer Teil wird durchkommen.", progress = "<Name>, mit jeder Stunde wird unsere Kontrolle über Stromgarde schwächer. Ihr müsst Euch beeilen, anderenfalls wird unsere Stadt gewiss fallen.", completion = "Sehr gut, &lt;Name&gt;. Mit dem Tod dieser Syndikatsmitglieder sollte es leichter werden, Vorräte aus Southshore zu erhalten.\n\nVielleicht besteht für unsere Sache ja noch Hoffnung.", rewards = "Ihr bekommt:\n\n"},
[682] = {title = "Abzeichen von Stromgarde", objective = "Bringt Abzeichen von Stromgarde zu Captain Nials bei der Zuflucht.", description = "Das Syndikat in Stromgarde bekämpft das Kontingent unserer Miliz dort. Um diesen Pöbel dazu zu bringen, sich mit unseren disziplinierteren Streitkräften zu schlagen, haben die Syndikatsanführer ein Kopfgeld auf unsere Soldaten ausgesetzt und belohnen jedes Abzeichen von Stromgarde, das toten Milizleuten abgenommen wurde, mit Gold.\n\nWir wollen diese Abzeichen zurück - wir dürfen es diesen Halsabschneidern nicht erlauben, Trophäen von unseren mutigen Gefallenen zu rauben!\n\nBegebt Euch in das vom Syndikat kontrollierte Gebiet von Stromgarde und jagt ihnen unsere Abzeichen ab.", progress = "Konntet Ihr Abzeichen von Stromgarde finden, <Name>? Das Syndikat muss begreifen, dass sie mit unseren Toten keinen Profit machen können.", completion = "Ich danke Euch, &lt;Name&gt;. Wir werden die Familien dieser getöteten Soldaten davon in Kenntnis setzen, dass sie im Kampf gefallen sind.\n\nEs ist bestimmt furchtbar, so eine grausame Nachricht zu erhalten, aber es ist allemal besser, als wenn das Schicksal einer geliebten Person für immer ungewiss bleibt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nKavalleriegamaschen von Stromgarde"},
[683] = {title = "Sara Balloos Hilfegesuch", objective = "Bringt Sara Balloos Notiz zu König Magni Bronzebeard von Ironforge.", description = "<Name>, ich habe nur eine kleine Bitte an Euch.\n\nBringt diese Mitteilung, die ich vorbereitet habe, zu unserem großen Monarchen von Ironforge, König Magni Bronzebeard. Es ist fast lächerlich, diese kleine Aufgabe von Euch zu verlangen, von jemandem, der für die Sache der Allianz bislang eine so große Unterstützung war.\n\nAber in meinem von Trauer übermannten Zustand vor den König zu treten, wäre meinem Anliegen nicht im Geringsten dienlich. Das versteht Ihr sicher.", progress = "Ihr seid also <Name>, der <Klasse>? Neuigkeiten über Eure Hilfe gegenüber der Allianz sind weit gereist, wisst Ihr?\n\nIn welcher Angelegenheit tretet Ihr heute vor mich?", completion = "Es wird nur einen Augenblick dauern, um diesen Brief zu überfliegen...", rewards = "Ihr bekommt:\n\n"},
[684] = {title = "GESUCHT: Marez Cowl", objective = "Bringt Marez' Kopf zu Captain Nials bei der Zuflucht.", description = "Es wurde ein Kopfgeld auf Marez Cowl ausgesetzt, einer hochrangigen Beraterin und Agentin des Syndikats. Sie wurde zuletzt in dem vom Syndikat kontrollierten Gebiet von Stromgarde gesehen.\n\nDas Kopfgeld kann von Captain Nials abgeholt werden.\n\nIch warne Euch: Marez ist eine geschickte und gerissene Hexenmeisterin und bekannt dafür, dass sie sich mit Dämonen abgibt. Bei ihrer Verfolgung ist äußerste Vorsicht geboten.", progress = "Seid gegrüßt, <Klasse>. Kommt Ihr, um Bericht zu erstatten?", completion = "Ihr habt Marez Cowl erledigt? Gut gemacht, &lt;Name&gt;. Wirklich gute Arbeit!\n\nMarez bedrohte unsere Verteidiger von Stromgarde und es wurde gemunkelt, dass sie Abgesandte zwischen dem Syndikat und einer anderen, dunkleren Macht war. Wir sind froh, dass sie nicht länger ihre Kräfte gegen uns einsetzen kann.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nArkane runenverzierte Armschienen"},
[685] = {title = "GESUCHT: Falkenstein und Otto", objective = "Bringt Ottos und Falkensteins Köpfe zu Captain Nials bei der Zuflucht.", description = "Die Miliz von Stromgarde hat Kopfgelder auf Lord Falkenstein und seine Leibwache Otto ausgesetzt. Falkenstein zeichnet für die Bemühungen des Syndikats im Arathihochland verantwortlich und sein Tod wäre eine erhebliche Störung dieser Bemühungen.\n\nSeine Leibwache Otto ist zwar kein strategisch wichtiges Ziel, aber er ist ein starker Gegner und hat Dutzende unserer Verteidiger auf dem Gewissen.\n\nIhre Kopfgelder können bei Captain Nials abgeholt werden.", progress = "Hallo. Kommt Ihr, um Bericht zu erstatten?", completion = "Falkenstein und Otto? Wunderbar!\n\nHier ist Eure Belohnung, &lt;Name&gt;. Ich freue mich, sie auszuzahlen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRute des KummersKriegsreiter-Armschienen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[686] = {title = "Ehrerbietung von einem König", objective = "König Magni Bronzebeard will, dass Ihr mit Großsteinmetz Marblesten sprecht.", description = "Ich erwarte nicht, dass Zwerge wie die gute Frau Balloo es verstehen, warum so ein Krieg für das größere Wohl unseres Volkes ertragen werden muss. Der Verlust ihres Gemahls und der Verlust jedes einzelnen Zwerges, der im Namen der Allianz kämpft, lastet schwer auf meiner Seele.\n\nAuch wenn ich nicht in der Lage bin, ihren Gemahl aus dem wirbelnden Nether zurückzuholen, so kann ich ihm doch meine Ehrerbietung erweisen. \n\nIch werde einen Gedenkstein für Sully Balloo bei Großsteinmetz Marblesten in Auftrag geben.\n\nBenachrichtigt ihn sofort, <Klasse>. Ihr werdet die Durchführung meines Auftrags beaufsichtigen.", progress = nil, completion = "Also, König Magni Bronzebeard hat Euch höchstpersönlich vorbeigeschickt?\n\nMeine Güte! Dann muss es wichtig sein!", rewards = "Ihr bekommt:\n\n"},
[687] = {title = "Theldurin der Verirrte", objective = "Findet Theldurin den Verirrten.", description = "Theldurin der Verirrte war einst ein Mitglied unseres Ordens, dem Twilight-Hammer. Aber er wurde verrückt und hat unsere Lehren verdammt. Bevor er uns davonlief, hat er die Rolle von Myzrael gestohlen! Wir konnten ihn nicht einfangen, aber Gerüchte besagen, dass er sich im Ödland versteckt, sabbelnd und wahnsinnig.\n\nIhr müsst die Rolle finden, denn nur so könnt Ihr die Fürstin zu uns zurückbringen. Und dafür müsst Ihr Theldurin finden.", progress = nil, completion = "Hallo. Hallo, hallo hallo hallo hallo HALLO!\n\nTut mir Leid - Moment, nein, stimmt gar nicht! Seid nicht unhöflich!\n\nOh nein... das war verrücktes Geschwätz.\n\nAllerdings... verrückt zu sein, ist manchmal mein einziger Trost.", rewards = "Ihr bekommt:\n\n"},
[688] = {title = "Myzraels Verbündete", objective = "Sprecht mit Zaruk in Hammerfall.", description = "<Myzrael spricht.>\n\nFrei! ICH BIN FREI! Ich bin frei und kann meine Kräfte sammeln, verborgen vor denen, die mich gefangen nahmen. Denn wenn ich mich ihnen jetzt stellen müsste, würden sie mich sicherlich überwältigen und erneut einsperren.\n\nAber bald werde ich mich den Riesen stellen und sie werden es bitter bereuen, mich als Gefangene gehalten zu haben!\n\nIhr seid ein edelmütiger Verbündeter, <Name>. Ich werde Eure Hilfe bald wieder benötigen. Wenn ich bereit bin, werdet Ihr mich an die Oberfläche beschwören müssen.\n\nSprecht mit Zaruk in Hammerfall. Er weiß, wie ich beschworen werden kann.", progress = nil, completion = "Willkommen, &lt;Klasse&gt;. Die Fürstin hat mich von Eurem Kommen unterrichtet, und wenn wir sie zurück an die Oberfläche bringen wollen, dann haben wir viel zu besprechen.", rewards = "Ihr bekommt:\n\n"},
[689] = {title = "Ehrerbietung von einem König", objective = "Großsteinmetz Marblesten aus Ironforge will 5 Stücke Alteracgranit.", description = "Unser guter König will also, dass wir einen Gedenkstein zu Ehren eines Soldaten mit Namen Sully Balloo errichten? Und Ihr sagt, dass der arme Kerl bei der Tragödie am Thandol-Übergang gestorben sei?\n\nBah, wird denn jemals Frieden auf Azeroth herrschen?\n\nWie dem auch sei, ein Auftrag vom König hat die allerhöchste Priorität. Und um ein wahrhaft episches und bleibendes Werk zu schaffen, will ich mit dem besten Stein arbeiten, der verfügbar ist. Begebt Euch nach Darrow Hill in Hillsbrad und besorgt mir etwas Alteracgranit.", progress = "<Name>, <Name>, <Name>! Sagt mir, dass Ihr genügend Alteracgranit beschafft habt, damit ich mein Meisterwerk zu Ehren von Sully Balloo beginnen kann.", completion = "Perfekt! Besser als ich es mir vorstellen konnte!\n\nUnd ich habe ziemlich viel Phantasie, wisst Ihr...", rewards = "Ihr bekommt:\n\n"},
[690] = {title = "Malins Gesuch", objective = "Sucht Skuerto bei der Zuflucht im Arathihochland auf.", description = "Seid gegrüßt, <Name>. Ihr seht aus wie ein Abenteurer und ich habe eine Aufgabe, die erledigt werden muss.\n\nErzmagus Trelane, mein früherer Meister, ist vor nicht allzu langer Zeit aus Stromgarde im Arathihochland geflohen und er hat mich gebeten, bei der Wiederbeschaffung einiger Gegenstände, die er zurückließ, behilflich zu sein.\n\nDie Stadt wird belagert und er hat versucht, den Turm von Arathor zu verteidigen, aber ohne Erfolg. Ich habe bereits Agenten im Hochland, aber sie haben mich gebeten, weitere Hilfe zu schicken. Seid Ihr interessiert?", progress = nil, completion = "Malin hat Euch also geschickt? Is' mir egal, ob Muradin von den Toten auferstanden ist und Euch auf'm Drachen hergeflogen hat. Ich hab zu tun! Redet mit Kryten, wenn Ihr was braucht.", rewards = "Ihr bekommt:\n\n"},
[691] = {title = "Das Gewicht in Gold wert", objective = "Sucht für Lehrling Kryten bei der Zuflucht 10 Hauer der Witherbark, 4 Medizinbeutel der Witherbark und 1 Schattenjägermesser.", description = "Erzmagier Malin schickte Skuerto und mich hierher, um für ihn ein paar Reagenzien zu besorgen. Ich hatte keine Ahnung, wie ich die Gegenstände beschaffen sollte, aber da Ihr jetzt hier seid, hat sich mein Problem wohl gelöst.\n\nIch brauche Folgendes: Hauer der Witherbark, Medizinbeutel der Witherbark und ein Schattenjägermesser.\n\nKönntet Ihr mir das besorgen? Die Witherbark leben südöstlich von Arathi.", progress = "Habt Ihr schon Glück gehabt, <Name>?\n\n\n\nWenn meine Forschungen richtig sind, sollten die Hauer von einem Troll der Witherbark stammen. Ich brauche die Medizinbeutel von Hexendoktoren der Witherbark und die stärksten ihrer Schattenjäger sollten die Spezialmesser bei sich tragen, die sie erhalten, nachdem sie die Aufnahmeriten absolviert haben. Welche Schattenjäger ein solches Messer besitzten, könnt Ihr nur herausfinden, wenn Ihr gegen sie kämpft.", completion = "Unglaublich! Jetzt durchschaue ich, warum Malin Euch gebeten hat, sich uns anzuschließen - das habt Ihr wahrlich sehr gut gemacht!\n\nWenn das so weitergeht, können Skuerto und ich im Handumdrehen nach Stormwind zurückkehren.\n\nIch glaube, mein Zwergengefährte ist aus der Halle der Felsfäuste zurück; sprecht mit ihm, wenn Ihr bereit seid.\n\nScheint so, als hätte er eine kleine Balgerei mit den Ogern gehabt. Erwähnt das ihm gegenüber aber nicht, er ist sehr sensibel, was Kritik an seinen Späherfertigkeiten angeht.", rewards = "Ihr bekommt:\n\n"},
[692] = {title = "Die verlorenen Fragmente", objective = "Bringt Theldurin dem Verirrten das zerrissene Rollenfragment, das zerknüllte Rollenfragment und das angesengte Rollenfragment.", description = "Die Rolle von Myzrael... die Rolle von Myzrael?! Die wollt Ihr doch wohl nicht haben! Ihre Magie kann Myzrael an die Oberwelt locken, und wenn Ihr das tut, sind wir alle in Gefahr!\n\nOder... vielleicht ist es schon zu spät. Vielleicht ist sie schon frei. Vielleicht sammelt sie nur ihre Kraft, bevor sie sich auf uns stürzt. Wenn es so ist, BRAUCHT Ihr die Rolle!\n\nZu dumm, dass sie zerstört wurde. Wütende Elementare haben sie gestohlen und kämpfen jetzt um die Fragmente.\n\nWenn Ihr diese Fragmente jedoch sammeln könntet, können wir sie vielleicht wieder zusammensetzen...", progress = "Habt Ihr die Fragmente gefunden?!? Ihr braucht die Rolle von Myzrael, wenn Ihr sie wieder einsperren wollt, bevor es zu spät ist!", completion = "Ah, Ihr habt sie gefunden! Gut gemacht, &lt;Name&gt;! Das könnte die einzige Chance sein, die wir gegen das Böse von Myzrael haben!\n\nLasst mich nur kurz meine Schrott-Ratsche suchen und schauen, ob ich diese Fragmente wieder anfügen kann...", rewards = "Ihr bekommt:\n\n"},
[693] = {title = "Zauberstab gegen Faust", objective = "Sucht Trelanes Zauberstab der Herbeirufung und bringt ihn Skuerto bei der Zuflucht.", description = "He, <Name>. Tut mir Leid, dass ich früher Euch gegenüber so kurz angebunden war... und nein, das sollte jetzt kein Wortspiel sein.\n\nIch habe herausgefunden, wo Trelanes erster Gegenstand gelandet ist: Kor'gresh in der Halle der Felsfäuste hat ihn. Und so wie er seinen Leuten die Hölle heiß gemacht hat, damit sie nicht aus der Reihe tanzen, muss er wohl kurz davor sein herauszufinden, wie man seine gesamte Macht nutzen kann.\n\nDie Halle der Felsfäuste liegt südlich von hier und östlich vom Thandol-Übergang. Findet diesen Oger und holt den Zauberstab.\n\nWährend Ihr weg seid, werde ich versuchen herauszufinden, was wir wegen Stromgarde unternehmen können.", progress = "Unser Ziel ist der Zauberstab, <Name>. Konzentriert Euch vorerst nur darauf.", completion = "Genial, &lt;Name&gt;. Einen Gegenstand haben wir, fehlen nur noch drei, laut meiner Liste. Die anderen drei Gegenstände befinden sich alle in Stromgarde.\n\nRuht Euch eine Weile aus, damit Ihr wieder zu Kräften kommt - die nächste Phase meines Plans erfordert etwas mehr Zeit und Mühe. Kommt wieder zu mir, wenn Ihr etwas Warmes im Bauch und Euch ausgeruht habt.", rewards = "Ihr bekommt:\n\n"},
[694] = {title = "Trelanes Verteidigung", objective = "Sucht einen azurblauen Achat und bringt ihn Lehrling Kryten bei der Zuflucht.", description = "Na, erholt?\n\nDas hier ist der nächste Schritt: Um den Turm von Arathor in Stromgarde herum wimmelt es nur so von Ogern. Wir müssen die Verteidigungsanlagen des Turms aktivieren, wenn wir eine Chance gegen sie haben und es lebend zu den Gegenständen schaffen wollen. Dazu brauchen wir ein paar Edelsteine, an denen die Schamanen der Felsfäuste Gefallen gefunden haben. Sie nahmen die aus dem Turm, aber sie werden nicht mehr lang in ihrem Besitz bleiben.\n\nHolt einen dieser Edelsteine und bringt ihn Kryten - er kennt den Zauber, mit dem man sie verzaubern kann, sodass sie wie ein Schlüssel funktionieren.", progress = "Da seid Ihr ja wieder, <Name>. Habt Ihr schon einen azurblauen Achat gefunden?", completion = "Ihr erstaunt mich, &lt;Name&gt;. Gut gemacht.\n\nGebt mir einen Moment Zeit, um den richtigen Zauber auf den Edelstein zu wirken, dann ist alles bereit.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[695] = {title = "Des Lehrlings Verzauberung", objective = "Sprecht mit Skuerto.\n\nBereitgestellter Gegenstand: \n", description = "Bitte sehr, <Name>. Der Edelstein muss nur gegen einen der Sockel nahe dem Fuß des Turms gepresst werden, um dessen Verteidigung zu aktivieren. Benutzt ihn, wenn Ihr bereit seid, den Turm zu betreten und nach den restlichen Gegenständen Trelanes zu suchen. \n\nViel Glück. Ich warte hier im Lager auf Eure Rückkehr. Oh, und sprecht mit Skuerto, bevor Ihr geht. Er gibt Euch die restlichen Details, die Ihr braucht.", progress = nil, completion = "Gut, gut.\n\nWenn es sonst keine Verzögerungen gibt, wie wär's, wenn wir jetzt aufbrechen?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[696] = {title = "Angriff auf den Turm", objective = "Sucht Trelanes Phylakterium, Trelanes Kugel und Trelanes Glutachat und bringt ihn Skuerto bei der Zuflucht.", description = "Danach müsst Ihr suchen: Trelanes Phylakterium, Trelanes Kugel, Trelanes Glutachat.\n\nAlle drei Dinge sollten sich innerhalb des Turms in Truhen befinden und es sollte Euch keine Schwierigkeiten bereiten, diese Truhen selbst zu öffnen; Ihr müsst Euch nur vor den Ogern in Acht nehmen.\n\nDie Verteidigungen des Turms kümmern sich nicht selbstständig um die Oger, Ihr müsst Eure Waffen jederzeit griffbereit haben. Wenn diese Oger herausfinden, dass Ihr dort seid, um sie zu bestehlen, werden sie Euch in die Mangel nehmen.\n\nSeid vorsichtig - und viel Glück.", progress = "Wenn Ihr das tut, wird Malin sicherlich mehr als zufrieden mit Euch sein.", completion = "Malin hätte niemanden bitten können, uns zu helfen, der fähiger wäre als Ihr, &lt;Name&gt;. Ihr habt hervorragende Arbeit geleistet!\n\nEr wird sich freuen zu sehen, was für ein überwältigender Erfolg unsere Mission geworden ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[697] = {title = "Malins Gesuch", objective = "Bringt dem Erzmagier Malin im Magierviertel von Stormwind den versiegelten Brief.", description = "Bringt diesen Brief nach Stormwind und lasst Malin wissen, dass Kryten und ich bald wieder zu Hause sind. Ich zweifle nicht daran, dass er Euch reichlich für Eure Hilfe uns gegenüber belohnen wird, <Name>.\n\nSichere Reise.", progress = "Ja? Ihr kommt mir irgendwie bekannt vor. Entschuldigt bitte, aber sind wir uns schon mal begegnet? Ich bin so beschäftigt, dass ich manchmal den Überblick verliere.", completion = "&lt;Erzmagier Malin öffnet den Brief und seine Augen weiten sich.&gt;\n\nBeim Licht, Ihr habt es geschafft! Wie wunderbar. Trelane wird hocherfreut sein. Ich bin sicher, Kryten und Skuerto sind ebenso aufgeregt wie ich, dass sie endlich auf dem Rückweg nach Stormwind sind.\n\nDanke, &lt;Name&gt;. Bitte, nehmt dies hier, es soll Euch auf Euren Reisen helfen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWachsamkeits-RundschildSchwingenstiefel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[698] = {title = "Mangelnde Reserven", objective = "Bringt Tok'Kar in den Sümpfen des Elends 8 Stück unverarbeitete Sägezahnflanken.", description = "Ich versuche, einige Vorräte für unseren Außenposten in der Nähe des Strandes im Osten zusammenzutragen - Tok'Kar tut, was er kann, aber neben dem Dienst als Wache und Kochen für seine Soldaten ist nicht mehr viel Zeit übrig vom Tag.\n\nWann immer sie können, kochen sie dort mit Begeisterung Sägezahnfleisch, aber ich hatte einfach keine Zeit, ihnen eine neue Ladung rüberzuschicken. Würdet Ihr mir da aushelfen?\n\nDie jungen Sägezähne sind nicht so schmackhaft wie die älteren, macht also einen Bogen um sie; gebt ihnen ein oder zwei Jahre, um zur vollen Größe heranzuwachsen.", progress = "Lok-Tar, <Klasse>. Das Risiko einer Reise durch die Sümpfe nimmt man nicht leichtfertig auf sich. Sehr mutig von Euch, Euren Mut gerade hier auf die Probe zu stellen.", completion = "Ah! Großartig. Frisches Fleisch für unsere Feier heute Abend. Danke, &lt;Name&gt;.\n\nIhr habt dazu beigetragen, die Nächte hier erträglicher zu machen. Das Feuer brennt hell und unsere Mägen werden wohl gefüllt sein.\n\nWas für eine angenehme Überraschung, die Ihr uns da gebracht habt; Dar mag zwar nicht gerade der attraktivste Orc sein, den man je gesehen hat, aber dafür ist seine Einstellung besser als sein Ruf.", rewards = "Ihr bekommt:\n\n"},
[699] = {title = "Mangelnde Reserven", objective = "Bringt Tok'Kar in den Sümpfen des Elends 6 Sägezahnschnapperklauen.", description = "Man hat uns wegen der Murlocplage entlang der Küste hier stationiert, um andere vor Gefahren jeglicher Art, die Stonard bedrohen könnten, zu beschützen - oder zu warnen, falls deren Streitkräfte zu groß werden. Das gibt uns nicht viel Zeit, um auszuruhen, und wir könnten weitere Hilfe Eurerseits gebrauchen, wenn Ihr gewillt seid.\n\nDie Sägezahnschnapperklauen geben erstklassige Waffen ab, wenn sie richtig vorbereitet werden. Bringt mir ein paar ihrer Klauen, dann werde ich zusehen, dass Ihr eine unserer Waffen als Dank für das Frischfleisch und die angenehme Gesellschaft bekommt.", progress = "Guter Met, ein warmes Feuer, eine Armee von Orcs, ein Arsenal von Waffen... das ist alles, was wir hier draußen entlang der Küste brauchen. Ich bedauere nicht, dass ich hier draußen bin und Stonard bewache, aber es wäre nett, wenn wir eines Tages mal einen Bau oder zumindest einen Turm hätten.", completion = "Wie schön zu sehen, dass Ihr lebt und wohlauf seid, &lt;Name&gt;.\n\nDiese Klauen eignen sich bestens. Je mehr Waffen wir zur Verfügung haben, um uns gegen Angreifer zu verteidigen, desto besser für uns.\n\nIch fange sobald wie möglich mit der Fertigung Eurer Waffe an. Ich werde nicht lange brauchen. Ich habe ein ziemliches Geschick dafür entwickelt und die Herstellung geht mir schnell von der Hand.", rewards = "Ihr bekommt:\n\n"},
[700] = {title = "Ehrerbietung von einem König", objective = "Erstattet Meldung an König Magni Bronzebeard.", description = "Ah, welch edle Steine doch aus Lordaeron kommen. Was für eine Schande, dass in diesem Land ein solches Chaos herrscht.\n\nAber der Gedenkstein ist sehr schön geworden! Ich glaube, der König wird damit sehr zufrieden sein.\n\nWürdet Ihr so gütig sein und Seiner Majestät eine Nachricht senden, dass der Gedenkstein wie gefordert fertig gestellt wurde?", progress = nil, completion = "Der Granit ist im Vergleich zum Lebenswerk eines großen Zwergs nur ein kleiner Ausdruck der Wertschätzung. Kein Zwerg kann jedoch ewig auf diesem Planeten wandeln.\n\nHoffen wir nur, dass der Gedenkstein eine Mahnung an all jene ist, die in Zukunft das große Azeroth betreten. Wir dürfen nie vergessen, dass es mutige Soldaten wie Sully Balloo waren, die so tapfer ihr Leben gaben, denen wir das alles verdanken.", rewards = "Ihr bekommt:\n\nGedenkring von Ironforge"},
[701] = {title = "Arglist des Raptors", objective = "Besorgt für Tor'gan 12 Raptorherzen von Hochlandfleischpirschern.", description = "Mit ein paar weiteren Dingen kann ich einen Gegenstand schaffen, der Gor'mul mit der Magie der Arglist des Raptors erfüllt! Wenn ihn die Macht des Raptors durchströmt, wird Gor'mul unsere neue Macht erkennen und den Krieger neu entdecken, der in ihm schlummert!\n\nUm den Gegenstand und den Zauber zu schaffen, werden Raptorherzen benötigt.", progress = "All meine Vorbereitungen sind getroffen, jetzt brauche ich nur noch die Raptorherzen.", completion = "Ja, die eignen sich hervorragend. Ich werde die Macht und den Geist der Raptoren hier auf diese Kugel übertragen. Diese Kugel wird Gor'mul die feurige Kraft und Intelligenz des Raptors verleihen.", rewards = "Ihr bekommt:\n\n"},
[702] = {title = "Arglist des Raptors", objective = "Gebt Gor'mulTor'gans Kugel.", description = "Nehmt diese Kugel und nutzt ihre Energie, um Gor'mul die Essenz des Raptors zu spenden. Sie wird seinen Geist erfrischen und ihm einen neuen Lebensinhalt geben. Sobald er wieder normal ist, können wir ihn über die aktuelle Situation der Horde informieren und wir werden einen großen Krieger bei unseren unaufhörlichen Kämpfen an unserer Seite haben.", progress = "Ihr seid wieder da? Was könnte ich mir mehr wünschen, als ein bisschen mehr Mitleid von Tor'gan?\n\nWas bringt Ihr mir diesmal? Vielleicht ein Stück knallbunte Schnur? Oder ein langes Seil, mit dem ich meinem Elend ein Ende setzen könnte...", completion = "Wenigstens bringt Ihr mir diesmal etwas Interessantes. Eine seltsame Macht geht davon aus...", rewards = "Ihr bekommt:\n\n"},
[703] = {title = "Gegrillte Bussardflügel", objective = "Bringt Rigglefuzz 4 Bussardflügel.", description = "Oh ja, meine gegrillten Bussardflügel sind ein Renner! Die Sauce ist gehaltvoll und das Fleisch würzig. Und der Duft lockt alle hungrigen Mäuler in einem Umkreis von Meilen an!\n\nIch habe alles, was ich brauche, um eine Menge zu kochen. Alles... außer Bussardflügel!\n\nWenn Ihr etwas davon haben möchtet, besorgt mir Bussardflügel. Bringt Ihr mir genügend davon, gebe ich Euch vielleicht sogar das Rezept dafür!", progress = "Hallo, <Name>. Bringt Ihr mir die Flügel?", completion = "Ah, ich fange gleich mit der Zubereitung der Flügel an. Ich kann sie schon förmlich schmecken!\n\nUnd hier habt Ihr das Rezept, falls Ihr sie einmal selbst zubereiten wollt!", rewards = "Ihr bekommt:\n\nGegrillter BussardflügelRezept: Gegrillter Bussardflügel"},
[704] = {title = "Agmonds Schicksal", objective = "Bringt Ausgrabungsleiter Ironband am Loch Modan 4 verzierte Steinurnen.", description = "Der letzte Bericht, den ich von Agmond erhalten habe, ist sehr beunruhigend, umso mehr, da er jetzt tot ist! Er erwähnte, dass seine Buddler an der Grabungsstätte vor Uldaman \"uralte Urnen\" entdeckt hätten. Ich fürchte, dass die dort gefundenen Urnen die Troggs erzürnt haben, ebenso wie die Götzen, die ich dort fand.\n\nIch möchte, dass Ihr uns die Urnen bringt, damit wir sie untersuchen können. Geht zur Grabungsstätte Uldaman, sammelt die Urnen ein und kehrt dann zu mir zurück.", progress = "Habt Ihr die Urnen gefunden, <Name>? Wir müssen herausfinden, welche Verbindung zwischen ihnen und den Troggs besteht!", completion = "Gut gemacht! Mit Glück und Geschick werden wir herausfinden, welche Verbindung zwischen den Troggs und diesen uralten Artefakten besteht. \n\nIhr habt den Ausgrabungsleitern einen großen Dienst erwiesen, &lt;Name&gt;. Eure Bemühungen werden wir Euch nicht vergessen! Und Agmond ebenso wenig.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nAusgrabungsleiter-Handschuhe"},
[705] = {title = "Perlentauchen", objective = "Bringt Rigglefuzz im Ödland 9 blaue Perlen.", description = "Das Ödland ist eine unwirtliche Gegend voller heimtückischer Raubtiere und dreister Aasfresser. Unheimlich, besonders für einen so kleinen Goblin. Ich muss gewitzt sein, wenn ich überleben möchte!\n\nIch kenne das Rezept für Blitzstrahlbomben. Die benutze ich, um wilde Tiere zu verjagen. Leider geht mir langsam eine der Zutaten aus: zu Pulver zermahlene blaue Perlen. Bringt mir welche, dann soll es Euer Schaden nicht sein.\n\nHe, und ich hoffe, Ihr habt gute Stiefel an. Die blauen Perlen, die ich brauche, stammen von Muscheln am finsteren Riff.\n\nGenau, dem finsteren Riff im Schlingendorntal!", progress = "Habt Ihr meine Perlen? Ich habe fast keine Blitzstrahlbomben mehr!", completion = "Die eignen sich hervorragend! Ich muss sie nur noch zu Pulver zermahlen... dann mit einem bisschen hiervon und einem bisschen davon vermischen.\n\nObacht, Aasfresser! Bald trifft euch der Blitzstrahl!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBlitzgewehrBlitzzauberstab\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\nBlitzstrahlbombe"},
[706] = {title = "Feuerverzauberungen", objective = "Besorgt Sigrun Ironhew ein Schwarzdrachenherz.", description = "Als Lehrling Feranor Steeltoes habe ich seine Spezialtechnik erlernt, wie man feurige Verzauberungen auf Waffen wirkt. Als ich das letzte Mal von ihm hörte, arbeitete er mit einer Jägergruppe in einer Schmiede, oben in Lordaeron.\n\nIch kann Euch nicht viel darüber sagen, an was genau er dort arbeitete, nur dass dazu Blut eines noch schlagenden Herzens eines seltenen Schwarzdrachen-Welpen nötig ist. Ohne Neuigkeiten aus Ironforge habe ich nicht viel zu tun. Wenn Ihr mir ein Herz eines Welpen aus der Lethlorklamm bringt, zeige ich Euch meine Fertigkeiten!", progress = "Wie läuft die Jagd, <Klasse>?", completion = "Ah ja, ausgezeichnet. Damit können Eure Waffen mit sengender Hitze zuschlagen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nFeuerverzauberung"},
[707] = {title = "Ironband sucht Euch!", objective = "Sprecht auf Ironbands Ausgrabungsstätte am Loch Modan mit Ausgrabungsleiter Ironband.", description = "<Name>. Ich habe Berichte von Ausgrabungsleiter Ironband von der Ausgrabungsstätte am Loch Modan erhalten - er braucht jemanden, der ihm die Rennerei auf einer unserer anderen Ausgrabungen abnimmt.\n\nIch habe keine weiteren Details, aber wenn Ihr Euch ein bisschen die Füße vertreten wollt, dann sprecht mit Ironband.", progress = nil, completion = "Stormpike hat Euch also hergeschickt, was? Gut.\n\nIch habe eine große Aufgabe für Euch...", rewards = "Ihr bekommt:\n\n"},
[708] = {title = "Der Flugschreiber", objective = "Bringt den zerfressenen Flugschreiber in die Halle der Waffen in Ironforge.", description = "Die Oberfläche dieses metallenen Flugschreibers ist stark angegriffen, so, als hätte man ihn in Säure getaucht... er muss lange im Magen des Riesenkondors gelegen haben.\n\nIhr dreht die Kiste um und entdeckt ein Symbol, das in den Boden eingeprägt ist. Unter dem Symbol stehen folgende Wörter:\n\n\"Motor Nr. 19 - Belagerungsbrigade von Ironforge\"Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[709] = {title = "Lösung der Verdammnis", objective = "Bringt Theldurin dem Verirrten die Schrifttafel von Ryun'eh.", description = "Oh je! Oh je! Unheil naht! Hört auf mich! Unheil!\n\nNein, ich darf nicht darüber sprechen... darf nicht ihre Namen aussprechen, sie könnten mich hören! Aber wenn wir mehr über sie lernen, ja, mehr... dann könnten wir vielleicht lernen, wie man sie aufhalten kann!\n\nVielleicht.\n\nGeht nach Uldaman. Nein! Ich hab's gesagt! Ihr müsst... die Schrifttafel von... Ryun'eh finden. Ja, findet sie! Und bringt mich nicht dazu, diesen Namen noch einmal auszusprechen!\n\nSie ist verborgen an diesem Ort, in einer uralten Truhe. Da ist sie versteckt... in einer Truhe, die gefertigt wurde, lang bevor Zwerge solche Werke vollbrachten.", progress = "Habt Ihr die Schrifttafel gefunden? Sie enthält bestimmt Geheimnisse! Geheimnisse, die uns retten können!", completion = "Oh, das Glück ist uns hold! Danke! Wir sind gerettet!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nVerdammnisverkünder-Robe"},
[710] = {title = "Element-Studie: Fels", objective = "Sucht 10 kleine Felssplitter und bringt sie Lotwil Veriatus im Ödland.", description = "Ich habe die Arbeit an meinem neuesten Projekt hier im Ödland erst mal eingestellt: meine Fesseln der Elementarbindung.\n\nWenn sie vollendet sind, werden Magier noch mächtigere Elementare beschwören und sie in noch größerer Zahl nutzen können. Ich brauche zunächst kleine Felssplitter, um einige meiner neuesten Angriffszauber und ein paar der Dingsdas zu testen, die ich zusammengebastelt habe.\n\nDie Splitter kann man leicht von den kleinen Felselementaren westlich von hier sammeln. Würdet Ihr mir ein paar bringen?", progress = "Dieses Gebiet eignet sich perfekt für - könntet Ihr das einen Moment festhalten? Ja, genau so, parallel zum Normalvektor. Also, wo war ich... Richtig. Perfekt, um mein neuestes Projekt zu testen. Die Rohstoffe, das offene Gelände... was könnte sich ein intelligenter und erleuchteter Fachmann der Technik sonst noch wünschen?", completion = "Die eignen sich bestens, &lt;Name&gt;. Danke. Hmm, ein bisschen mehr Sand als ich erwartet hatte. Muss den Reibungskoeffizienten anpassen. Nein, Sekunde; das sollte sich mit dem Frostöl ausgleichen lassen.", rewards = "Ihr bekommt:\n\n"},
[711] = {title = "Element-Studie: Fels", objective = "Bringt Lotwil Veriatus im Ödland 3 große Steinplatten.", description = "Ihr habt Euch als fähiger erwiesen als all meine Lehrlinge zusammen, <Name>.\n\nFür die nächsten Aktionen ist etwas mehr Krafteinsatz erforderlich. Wenn Ihr vorsichtig genug seid, könnt Ihr bei Felselementaren große Steinplatten finden. Ihre Körper sind kräftiger und größer und deshalb kommt man bei ihnen eher an Teile heran, die groß genug für meine Tests sind. Ihr findet sie weiter westlich von hier oder südöstlich entlang des Gebirgsrandes.\n\nLasst Euch Zeit, ich brauche eine Weile, um diese kleineren Stücke zu testen, die Ihr mir gebracht habt.", progress = "Ich bin hoch erfreut, <Name>. Meine Zauber haben auf die kleineren Stücke gewirkt, wie ich voraussagte. Falls dieses Experiment so erfolgreich ist, wie ich voraussehe, dann werden die Elementare, die ich beherrschen kann, alles andere, was ich bislang beschworen habe, in den Schatten stellen.", completion = "Einfach erstaunlich, &lt;Name&gt;! Ich hätte gedacht, man würde mindestens ein halbes Dutzend Tauren benötigen, um das alles hierher zu schleppen.", rewards = "Ihr bekommt:\n\n"},
[712] = {title = "Element-Studie: Fels", objective = "Bringt Lotwil Veriatus im Ödland 5 Armschienen der Steinbindung.", description = "<Name>, ich brauche noch ein weiteres Teil von den Elementaren hier im Ödland: die Armschienen der Steinbindung von den großen Felselementaren. Meinen Berechnungen nach sollten diese Armschienen ausreichen, um die Kraft meiner Fesseln zu beurteilen.\n\nBei meinen Wahrsageversuchen über die großen Felselementare sah ich eine Gruppe von ihnen südwestlich von hier, in der Nähe von ein paar Ogern, wenn ich mich recht erinnere.\n\nBringt mir 5 ihrer Armschienen, damit ich ein paar in Reserve habe. Servo ist berüchtigt dafür, meine Reagenzien und Forschungen zu verlegen.", progress = "Die Steinplatten, die Ihr mir gebracht habt, waren ideal, <Name>. Lucien wird die restlichen nach Kharanos zurückbringen, wenn wir hier fertig sind. Sie könnten sich später noch als nützlich erweisen.\n\nSie würden sich zum Beispiel gut eignen, um einen praktischen kleinen Bunker zu bauen, sobald ich mit einem fachübergreifenden Feldversuch an hoch wirksamem Sprengstoff beginne...", completion = "&lt;Name&gt;, habt Ihr jemals darüber nachgedacht, Forschungsassistent zu werden? Nein? Ich weiß wirklich nicht, wie ich ohne Eure Fähigkeiten hier auskommen soll. Intelligenz, Neugier und Kraft - alles zusammengeschnürt in einem Paket.", rewards = "Ihr bekommt:\n\n"},
[713] = {title = "Kühlaufsätze setzen sich durch", objective = "Sucht Frostöl und bringt es Lotwil Veriatus im Ödland.", description = "Lasst mich Euch etwas über Frostöl erzählen: Nichts kann einen Motor oder ein Getriebe besser vor Überhitzung schützen.\n\nSeine Kühleigenschaften sind außerordentlich und seine Langlebigkeit als Schmiermittel ist ohnegleichen. Aber das ist nicht alles: Es trägt auch dazu bei, die Verzauberung magischer Gegenstände zu erhalten.\n\nIch brauche eine Phiole davon, um die magische Kapazität meiner Fesseln zu erhöhen und sie mächtig genug zu machen, um unseren beschworenen Freund davon abzuhalten, uns alle umzubringen.\n\nBro'kin, einer meiner Goblin-Freunde, kann Euch lehren, wie man es herstellt. Er wohnt in Alterac.", progress = "Habt Ihr das Öl schon gefunden, das ich benötige? Es würde mir sehr helfen, wenn Ihr mir etwas davon bringen würdet.", completion = "Toll! Das dürfte das perfekte Kühlmittel für meine neuen Armschienen sein. Wenn diese Verzauberung nicht mindestens ein Jahrhundert hält, schenke ich all meine Habseligkeiten Servo.\n\nAlle Magier der Vereinigung werden vor Ehrfurcht erstarren, wenn ich damit fertig bin, &lt;Name&gt;. Wartet's nur ab.", rewards = "Ihr bekommt:\n\n"},
[714] = {title = "Gyro... Was?", objective = "Bringt Lotwil Veriatus im Ödland einen Gyrochronatom.", description = "Ihr habt Eure Arbeit überdurchschnittlich gut gemacht, <Name>.\n\n<Lotwil ist offensichtlich durch seine Arbeit abgelenkt.>\n\nFalls wir uns in Kharanos jemals wiedersehen, scheut Euch nicht, zu mir zu kommen und nach Arbeit zu fragen.\n\nUpps! Schnell, nehmt das... ja, das da. Danke.\n\nJetzt brauche ich nur noch eines. Es ist ein kleines Teil, aber leider ziemlich ausschlaggebend: ein Gyrochronatom.\n\nWenn Ihr irgendwo einen auftreiben und mir bringen würdet, könnte ich das hier fertig stellen.", progress = "Ja, ja, ja. Nur einen Moment.\n\n<Lotwil setzt seine Arbeit an irgendeiner Art von Apparat fort.>", completion = "HA!\n\n&lt;Lotwil schnappt sich das Gyrochronatom von Euch.&gt;\n\nPerfekt... so gut wie fertig. Nein, ehrlich. Ich BIN jetzt fast fertig. Dieses Projekt hat oberste Priorität... im Moment. Lasst mich das hier noch an die richtige Stelle stecken, und Ihr könnt selbst sehen, wobei Ihr mir geholfen habt. Es wird nur noch ein paar Minuten dauern... vielleicht... möglicherweise etwas länger. Na gut, vielleicht sehr viel länger. Wir werden ja sehen...", rewards = "Ihr bekommt:\n\n"},
[715] = {title = "Flüssigstein", objective = "Bringt Lucien Tosselwrench im Ödland einen Heiltrank und einen geringen Unsichtbarkeitstrank.", description = "Ich glaube, die Gegenstände, die Ihr Lotwil besorgt habt, werden unsere geringste Sorge sein, <Name>. Andererseits habt Ihr Euch in den Wissenschaften, die Lotwil so heilig sind, mehr als talentiert gezeigt; also wie wäre es, wenn Ihr jetzt mir ein bisschen helft?\n\nIch brauche einen Unsichtbarkeitstrank und einen Heiltrank; beides könnte sich als nützlich erweisen, sobald er erst mit seinem Ding angefangen hat.\n\nDafür gebe ich Euch dieses Rezept für einen Trank, den ich entwickelt habe, als ich noch bei Lotwil in die Lehre ging. Er basiert auf einigen der Forschungen, die er hier im Ödland durchführte.", progress = "Er ist bald fertig. Wie sieht es denn bei Euch aus?", completion = "JA!\n\nIch meine, danke, &lt;Name&gt;. Sie werden bei Reisen durchs Ödland sehr hilfreich sein.", rewards = "Ihr bekommt:\n\nRezept: Geringer SteinschildtrankGeringer Steinschildtrank"},
[716] = {title = "Stein ist besser als Stoff", objective = "Bringt Lucien Tosselwrench im Ödland einige gemusterte bronzene Armschienen.", description = "Ich weiß, wie knickerig Lotwil sein kann, <Name>, also lasst mich etwas als Belohnung für all Eure Mühen fertigen. Vielleicht kann es Euch sogar vor der Scheußlichkeit schützen, die Lotwil gerade erfindet.\n\nIch habe alle zusätzlichen Steine verarbeitet, die Ihr für ihn gesammelt hattet, und kann Euch ein paar hübsche Armschienen machen, die Ihr möglicherweise gebrauchen könnt. Sie sind natürlich verzaubert.\n\nIch brauche nur noch gemusterte bronzene Armschienen, die ein Schmied hergestellt hat, um die fertig zu stellen, die ich für Euch mache.", progress = "Ich würde nicht zu lang warten, um mir diese Armschienen zu holen, <Name>.\n\nWer weiß, was als Nächstes passieren wird?", completion = "Bitte sehr, &lt;Name&gt;. Probiert sie mal an.", rewards = "Ihr bekommt:\n\nVerzauberte Steinstoffarmschienen"},
[717] = {title = "Erdbeben", objective = "Benutzt das Zeichen der Erde, um die Amethyst-, Opal- und Diamantsäulen zu aktivieren und die Runensteine zu holen.\n\nLegt die Runensteine auf das Siegel der Erde, um Schattenbringer und Hematus zu befreien.\n\nTötet sie und bringt dann Garek Schattenbringers Bindung, Hematus' Ketten und das Zeichen der Erde.", description = "Es ist offensichtlich, dass wir nicht mehr gewährleisten können, Schattenbringer und Hematus noch länger in Lethlor festzuhalten. Die schwarzen Großdrachen haben sich dort niedergelassen, und dass es den Ogern gelungen ist, das Zeichen zu stehlen, weist darauf hin, dass drastischere Maßnahmen ergriffen werden müssen.\n\nDas Gefängnis der Drachen wird von drei Runensteinen gebildet, die man nur mit Hilfe des Zeichens der Erde wegnehmen kann. Diese Runensteine können dann dazu verwendet werden, das Siegel zu zerbrechen, das sie gefangen hält.\n\n<Name>... sorgt dafür, dass sie süß träumen... für immer.", progress = "Starke Magie und Mächte haben die Drachen so lange Zeit gefangen gehalten, aber wir dürfen keinesfalls zulassen, dass Schattenbringer und Hematus irgendwie freikommen.", completion = "Die Kirin Tor müssen sich keine Sorgen wegen der Gefangenen von Lethlor machen. Ich werde zurückkehren und meinem Meister von diesem Erfolg berichten. Krasus wird zweifellos erfreut sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLohenwindbrustplattePrismaschuppenhalsbergeKriegsgeschmiedete BrustplatteGedankenexplosion-Medaillon\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[718] = {title = "Illusionen", objective = "Holt die Nachschubkiste für Sigrun Ironhew.", description = "Wir hatten es so eilig, die Ausgrabungsstätte von Uldaman zu verlassen, dass wir uns gezwungen sahen, unterwegs viele Wagen und Nachschubkisten zurückzulassen. Die Oger von Camp Kosh haben sich auf unsere zurückgelassene Ausrüstung gestürzt wie Geier auf faulende Kadaver. Riechen auch nicht besser. Als die Kadaver, meine ich.\n\nWie dem auch sei, sie haben sich den Wagen mit unseren Waffen und anderem Zeug geschnappt und deshalb - tja, es ist ein bisschen peinlich - konnten wir uns nichts zum Essen beschaffen.\n\nWir stecken echt ganz schön in der Klemme. Könnt Ihr uns vielleicht helfen?", progress = "Die Wüste ist für einen Hungrigen ein schlechter Ort, mein Freund, das könnt Ihr mir glauben.\n\nHe... was ist denn das da drüben...", completion = "Vielen Dank, &lt;Name&gt;. Während Ihr fort wart, habe ich, äh... einen Mund voll Sand gegessen. Es...\n\nAch, genug davon; wir ziehen aus und besorgen uns heute Abend etwas zu essen. Wir werden wie Könige speisen!", rewards = "Ihr bekommt:\n\n"},
[719] = {title = "Ein Zwerg und sein Werkzeug", objective = "Sucht Ryedols Glückshacke und bringt sie Ausgrabungsleiter Ryedol in der Hammertoe-Grabungsstätte.", description = "He, <Name>. Seid lieber vorsichtig. Es sind Dunkeleisenzwerge in der Nähe - scheinen vom Schattenschmiedeklan zu sein.\n\nSie haben gerade die Ausgrabungsstätte angegriffen, auf der ich arbeite - haben fast alle dort umgebracht, darunter meinen Boss Hammertoe. Ich bin gerade noch lebendig weggekommen.\n\nDie Stätte liegt nördlich von hier und ich versuche, mir einen Plan auszudenken, wie wir einen Teil unserer Vorräte zurückbekommen könnten, insbesondere meine Glückshacke.\n\nMeint Ihr, Ihr könntet mir ein bisschen helfen? Einer von diesen verdammten Dunkeleisenzwergen muss meine Hacke haben! Es könnte jeder von denen sein.", progress = "Keine Ahnung, wonach die Zwerge der Schattenschmiede suchen, aber die hatten definitiv einen Grund.", completion = "Ihr seid mein Retter, &lt;Klasse&gt;. Ich bin ja so froh, dass endlich mal jemand den Zwergen der Schattenschmiede gezeigt, was eine Harke ist. Danke für Eure Hilfe.", rewards = "Ihr bekommt:\n\nRyedols Hammer"},
[720] = {title = "Ein Hoffnungsschimmer", objective = "Sucht Ausgrabungsleiter Ryedol und teilt ihm mit, dass Hammertoe Grez noch am Leben ist.", description = "<Text wurde mit Kreide auf die Karte gekritzelt.>\n\n\"Ryedol, \nSie bringen mich nach Uldaman. Schickt Hilfe.\n- Hammertoe\"", progress = nil, completion = "Hammertoe lebt?! Das ist ja wunderbar, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[721] = {title = "Ein Hoffnungsschimmer", objective = "Sucht in Uldaman nach Hammertoe Grez.", description = "<Name>, geht Ihr ihn suchen? Sucht Ihr Hammertoe in Uldaman?\n\nWenn diese dreckigen Zwerge der Schattenschmiede ihn als Geisel genommen haben, um herauszubekommen, was er über die Titanenausgrabungen weiß, könnte ganz Ironforge in großer Gefahr sein.\n\nSeit langer Zeit schon trachten die Dunkeleisenzwerge nach Magie, um noch mächtigere Golems zu erschaffen. Hammertoe hatte dasselbe vor, aber natürlich nur, um sie aufzuhalten.\n\nVielleicht lassen sie ihn am Leben, bis sie herausbekommen haben, was er weiß; Ihr müsst Euch beeilen, wenn Ihr ihn retten wollt!", progress = nil, completion = "Ja? Tut mir Leid... (((hustet))) Fühl mich so schwach. Könnt Ihr 'n bisschen näher kommen, &lt;Klasse&gt;?\n\nRyedol schickt Euch? Muradin sei gelobt, dieser Junge hat doch mehr auf dem Kasten als ich dachte. (((hustet)))", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[722] = {title = "Amulett der Geheimnisse", objective = "Sucht Hammertoes Amulett und bringt es ihm nach Uldaman.", description = "Ihr seid mutig... (((hustet))) dass Ihr Euch wegen mir nach Uldaman wagt, <Klasse>.\n\nWenn Ihr wirklich hier seid, um dem... ollen Hammertoe zu helfen, dann... (((hustet)))... müsst Ihr nach... meinem Amulett suchen.\n\nGrubenschatten hat es... Magregan Grubenschatten. Muss hier irgendwo sein... in den Ruinen, das ist sicher. Das Amulett wird sie... (((hustet)))... genau zu den Rollen führen, wenn sie keiner aufhält. Es ist an Euch, <Name>. Bitte... holt das Amulett.\n\nDie Rollen werden es den Dunkeleisenzwergen ermöglichen, noch mächtigere Golems zu erschaffen. Ich weiß es einfach. Spür's in meinen Knochen.", progress = "Der Schattenschmiedeklan... <hustet>... ist gefährlich. Seid vorsichtig. <hustet>... Ihr müsst das Amulett finden.", completion = "Ha! (((hustet)))\n\nAh, ich wusste, dass Ihr mein Amulett finden würdet, &lt;Name&gt;.\n\n(((keucht))) Sehr gut, wirklich, &lt;Name&gt;. (((hustet)))", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[723] = {title = "Ein Funken Hoffnung", objective = "Bringt Ausgrabungsleiter Ryedol im Ödland Hammertoes Amulett.", description = "<Hammertoe fasst an seine Wunden und braucht einen Moment, um sich zu sammeln, bevor er weiterspricht.>\n\nFindet Ryedol, <Name>. Bringt ihm mein Amulett. <hustet> Er... <hustet>... wird wissen, was zu tun ist; er weiß, dass ich nach den Wurzeln unseres Volks suchte, und er... <hustet>... weiß, dass es meine Aufgabe war, den Schattenschmiedeklan aufzuhalten. Sie dürfen die Rollen nicht finden... <hustet>", progress = "Ich würde sagen, dass war ein öder Tag, aber das hier ist das Ödland. Jeder Tag ist öde.", completion = "Hammertoes Amulett? Ich glaube, ich war besserer Stimmung, als ich noch dachte, er sei tot. Es jetzt endgültig zu wissen, macht den Schmerz noch schlimmer. Das Amulett war sein Lebenswerk. Sein Tod soll nicht umsonst gewesen sein.", rewards = "Ihr bekommt:\n\n"},
[724] = {title = "Ein Funken Hoffnung", objective = "Bringt Historiker Karnik in Ironforge Hammertoes Amulett.", description = "Okay, okay... Wer könnte wissen, was zu tun ist?\n\nHistoriker Karnik! Genau!\n\nEr lebt in Ironforge. Er kann helfen. Er und Hammertoe haben zusammengearbeitet, um in Uldaman nach den verschollenen Artefakten zu suchen.\n\nSchätze, die Zwerge der Schattenschmiede haben rausgefunden, dass die beiden mehr wussten, als sie sagten.\n\nErzählt Karnik, was mit Hammertoe geschehen ist, und gebt ihm das Amulett - er wird Euch dann sagen, was als Nächstes zu tun ist.", progress = "Ah, ja. Wieder ein Reisender, der nach etwas von den Zwergen sucht.\n\nSire, es tut mir wirklich Leid, aber ich habe jetzt keine Zeit, sinnlose Fragen zu beantworten.", completion = "Oh! Ja, das ist eine ganz andere Sache. Ihr habt vielleicht noch nicht die Schwere dieser Angelegenheit erkannt, was?\n\nIch bin zutiefst erschüttert über Hammertoes Ableben, aber wenn er Euch mit seinem Amulett zu mir geschickt hat, dann wusste er genau, was auf dem Spiel steht.\n\nWir werden später noch Zeit haben, seinen Tod zu betrauern.\n\nLasst mich Euch einen der Gründe zeigen, warum dieses Amulett so wertvoll ist.", rewards = "Ihr bekommt:\n\n"},
[725] = {title = "Kunde über die Bedrohung breitet sich aus", objective = "Sucht Berater Belgrum und gebt ihm die Notiz.", description = "<Name>, lauft los und findet so schnell wie möglich Berater Belgrum; sagt ihm, was Ihr gesehen habt, und fragt ihn, wie wir weiter vorgehen sollen. Diese Notiz wird ihm alles Weitere erklären.\n\nIn der Zwischenzeit werde ich mir die Zeit nehmen, um mit Hammertoes Geist zu sprechen. Vielleicht weiß er etwas, das uns helfen könnte, die Aktivitäten der Zwerge der Schattenschmiede hier im Ödland zu unterbinden. Wir können nur beten.", progress = "Hmm? Ja, <Klasse>.", completion = "Ah, eine Nachricht von Historiker Karnik. Exzellent.\n\nFür ihn habe ich immer Zeit.\n\n&lt;Berater Belgrum öffnet die Notiz und beginnt zu lesen.&gt;", rewards = "Ihr bekommt:\n\n"},
[726] = {title = "Kunde über die Bedrohung breitet sich aus", objective = "Sprecht mit Historiker Karnik.", description = "<Berater Belgrum erreicht das Ende der Notiz und für einen Moment weiten sich seine Augen.>\n\nAch, das sind schlimme Nachrichten.\n\n<Name>, bitte kehrt zu Historiker Karnik zurück und sagt ihm, dass er im Auftrag des Königs schnell und entschlossen gemäß dieser Information handeln soll. Er muss die Aktivitäten der Zwerge der Schattenschmiede im Ödland unterbinden.", progress = nil, completion = "Ihr behandelt diese Angelegenheit mit einer Dringlichkeit, die der des Königs in nichts nachsteht, &lt;Name&gt;.\n\nAlso gut. Ich weiß, wie wir die Zwerge der Schattenschmiede in die Knie zwingen können.\n\nWir können ihre Unternehmungen in Uldaman verlangsamen, wenn wir sie an ihrem Operationsstützpunkt schlagen: der Festung Angor.", rewards = "Ihr bekommt:\n\n"},
[727] = {title = "Auf nach Ironforge zu 'Yagyins Zusammenstellung'", objective = "Gebt Gerrig Bonegrip im düsteren Viertel von Ironforge das Siegelzeichen des Hammers.", description = "Die Schrifttafel erklärt vieles. Aber nicht genug! Nicht annähernd genug!\n\nEs gibt ein Buch, eine Zusammenstellung, die Yagyin vor Unzeiten verfasst hat. Die... Leute, vor denen ich geflohen bin... bewahren dieses Buch an vielen verschiedenen Orten auf. Und die höchstgebildeten von ihnen studieren es. Es enthält riesiges Wissen. Wissen, das uns beschützen kann!\n\nGeht zu Gerrig Bonegrip. Er befindet sich in Ironforge in einem Geschäft im düsteren Viertel. Zeigt ihm dieses Siegelzeichen, dann wird er Euch für einen der ihren halten. Fragt ihn nach 'Yagyins Zusammenstellung'... und bringt sie mir!", progress = "Hallo. Willkommen in meinem Laden, aber passt auf, was Ihr berührt.\n\nWissen kann manchmal tödlich sein.", completion = "Oh. Seid gegrüßt, Bruder.\n\nUnd gelobt die Bewohner der Tiefe.", rewards = "Ihr bekommt:\n\n"},
[728] = {title = "Auf nach Undercity zu 'Yagyins Zusammenstellung'", objective = "Bringt dem Bewahrer Bel'dugur in Undercity das Siegelzeichen des Hammers.", description = "Die Schrifttafel erklärt vieles. Aber nicht genug! Nicht annähernd genug!\n\nEs gibt ein Buch, eine Zusammenstellung, die Yagyin vor Unzeiten verfasst hat. Die... Leute, vor denen ich geflohen bin... bewahren dieses Buch an vielen verschiedenen Orten auf. Und die höchstgebildeten von ihnen studieren es. Es enthält riesiges Wissen. Wissen, das uns beschützen kann!\n\nSucht den Bewahrer Bel'dugur in Undercity von Lordaeron auf. Zeigt ihm dieses Siegelzeichen, dann wird er Euch für einen der ihren halten. Fragt ihn nach 'Yagyins Zusammenstellung'... und bringt sie mir!", progress = "Ah, Ihr seid ein besonders eifriger <Klasse>, wie ich sehe. Seid Ihr hier, um aus meiner Sammlung zu lernen? Gut!\n\nAber seid gewarnt: Genau wie Wissen den Starken Macht verleiht... treibt es die Schwachen in den Wahnsinn.", completion = "Seid diskret mit Euren Zeichen, &lt;Klasse&gt;. Manche werden Euch die Rechtschaffenheit Eures Anliegens nicht abnehmen.\n\nUnd es gibt einige, die gern Zeuge unseres Versagens wären, würden sie von uns wissen.\n\nWir müssen immer vorsichtig sein. Und wachsam. Und geduldig.", rewards = "Ihr bekommt:\n\n"},
[729] = {title = "Der geistesabwesende Ausgrabungsleiter", objective = "Reist nach Süden und seht nach Ausgrabungsleiter Remtravel.", description = "Was war es doch für eine Ehre, als Meister Greywhisker mir auftrug, unter der Führung des großen Ausgrabungsleiters Remtravel zu arbeiten. Jeder an der Akademie in Ironforge kannte Remtravels großartige Entdeckungen.\n\nAber der Ausgrabungsleiter ist sich nicht so recht ... ähm ... bewusst ... was um ihn herum so vor sich geht.\n\nWir hatten Hinweise auf eine große Kultur entdeckt. Schreckliche Golems brachen aus dem Boden hervor und überrannten die Grabungsstätte. Remtravel schien gar nichts bemerkt zu haben. Ich rannte nach Auberdine, um Hilfe zu holen.\n\nBitte reist nach Süden und seht nach, ob es dem Ausgrabungsleiter gut geht!", progress = nil, completion = "Hollee, seid Ihr das? Ich brauche jemanden, der mir hilft, diesen Stein zu bearbeiten. Gebt mir meinen Handfeger, ich glaube, ich sehe was.\n\nHe, Ihr seid gar nicht Hollee! Ihr habt nicht zufällig meinen Handfeger gesehen?\n\nIst ja jetzt auch egal! Ich habe denen von der Liga versprochen, das rätselhafte Fossil zu schicken, das ich gefunden habe. Wo ist Hollee nur wieder hin?\n\nEs gibt noch so viel zu tun! Also wo ist jetzt dieses rätselhafte Fossil ... und mein Feger ... und Hollee ...\n\nUnd wer seid Ihr ... Ist ja auch egal, Hauptsache, Ihr seid hier, um mir zu helfen.\n\nLasst es mich wissen, wenn Ihr bereit seid zu suchen.", rewards = "Ihr bekommt:\n\n"},
[730] = {title = "Ärger in Dunkelküste?", objective = "Reist nach Auberdine und sucht nach Hinweisen auf das Zwergenausgrabungsteam.", description = "Wie schön, ein <Klasse>, der an den großartigen archäologischen Wundern unserer Welt interessiert ist.\n\nOftmals wird unser Wirken von unseren Freunden der Allianz nur als reines Hobby abgetan. Aber was viele nicht einsehen wollen ist, dass die jüngsten Entdeckungen in Khaz Modan bewiesen haben, dass eine große und mächtige Kraft ganz Azeroth bedroht, von Lordaeron bis nach Kalimdor.\n\nIch bin höchst besorgt um meine Mannschaft, die ich nach Dunkelküste geschickt habe. Meine Leute haben seit Wochen nichts mehr von sich hören lassen.\n\nReist nach Auberdine und sucht nach Hinweisen auf ihren Aufenthaltsort.", progress = nil, completion = "Ich bin ja so froh, dass Chefarchäologe Greywhisker nach uns schicken ließ...", rewards = "Ihr bekommt:\n\n"},
[731] = {title = "Der geistesabwesende Ausgrabungsleiter", objective = "Beschützt Ausgrabungsleiter Remtravel, während er nach dem rätselhaften Fossil sucht, und kehrt dann zur Archäologin Hollee in Auberdine zurück.", description = "Also dann, Hollee... ach ja, richtig, Ihr seid ja gar nicht Hollee. Wo ist Hollee?\n\nPah, das ist ja jetzt auch nebensächlich. Wir müssen diesen Handfeger finden... Ich meine, das rätselhafte Fossil! Wir müssen dieses Fossil finden. Die Forscherliga in Darnassus wird ein paar Hinweise darauf haben wollen, was ich hier die ganze Zeit getrieben habe.\n\nLasst es mich wissen, wenn Ihr bereit seid, dann machen wir uns auf die Jagd nach diesem Feger... Ich meine, Fossil! Wir sollten irgendeine Niederschrift finden, damit die Liga zufrieden ist.\n\nAlso, seid Ihr so weit?", progress = nil, completion = "Den Sternen sei Dank, Ausgrabungsleiter Remtravel ist in Sicherheit! Ich sagte Euch doch, dass er etwas geistesabwesend ist. Nicht zu fassen, dass er darauf bestanden hat, trotz all dieser schrecklichen Kreaturen, die dort herumschleichen, zu bleiben.", rewards = "Ihr bekommt:\n\n"},
[732] = {title = "Erdbeben", objective = "Beschafft für Garek das Zeichen der Erde.", description = "Ich habe von Sigrun gehört, dass Ihr ihm eine große Hilfe gewesen seid. Vielleicht darf ich Eure Hilfe ja auch in Anspruch nehmen. Mein Meister, Krasus von den Kirin Tor, hat mich hergeschickt, um die Probleme zu lösen, die sich in der Lethlorklamm zusammenbrauen.\n\nIch darf nicht preisgeben, was genau meine Mission ist oder was ich unternehmen soll, aber seid versichert, dass es von großer Wichtigkeit ist.\n\nEine Bande nomadisierender Oger, die gelegentlich in der Nähe vom Camp Boff gesichtet wurden, hat einen Gegenstand gestohlen, das so genannte \"Zeichen der Erde\", und ich muss es wiederhaben. Bringt es mir und ich verrate Euch mehr.", progress = "Die nomadisierende Ogerbande zieht von einem ihrer Lager im Ödland zum nächsten, die Hitze, die von der trockenen Erde aufsteigt, und die wirbelnden Winde erschweren es, ihren Spuren zu folgen. Ich habe gehört, dass sie gelegentlich durch das Camp Boff reisen. Falls Ihr nicht so recht weiter wisst, könnt Ihr ja mal dort suchen.", completion = "Das sind wahrlich gute Neuigkeiten, dass Ihr mir das Zeichen bringt, &lt;Name&gt;. Das Zeichen der Erde wurde von den Dunkeleisenzwergen der Festung Angor geschaffen, um zwei unbarmherzige Deathwing-Lieutenants, die Zwillinge Schattenbringer und Hematus, zu binden.", rewards = "Ihr bekommt:\n\n"},
[733] = {title = "Schnorrerei", objective = "Bringt Sigrun 7 Teile Metallschrott.", description = "Es wird hier ganz schön haarig werden, wenn es mir nicht gelingt, Material aufzutreiben, um ein paar Verteidigungslinien und andere Notwendigkeiten zu konstruieren. Mir ist aufgefallen, dass die Oger in diesem Gebiet über jede Menge Metallschrott verfügen. Vielleicht sind die Geschichten über Belagerungsmaschinen im Ödland doch gar nicht so weit hergeholt...\n\nWie dem auch sei, die Ausgrabungsleiter machen sich langsam Sorgen um die Lage in unserem kleinen Lager, deshalb würde ich gern, sobald es geht, mit der Arbeit beginnen.\n\nDas Hauptlager der Oger liegt bei der Staubspeiergrotte, eine ordentliche Strecke von hier aus Richtung Westen.", progress = "Tja, ich hab mich mit dem begnügt, was ich bekommen habe... aber es war nicht viel. Habt Ihr noch mehr Vorräte gefunden?", completion = "Es ist ein Anfang, &lt;Name&gt;, und es muss reichen, bis wir etwas aus Ironforge oder von der Forscherliga hören.\n\nWenn ich jetzt nur noch etwas Salz für mein Kühlfass finden würde...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSalbacschildEisenfersenstiefel\n\nIhr bekommt außerdem:\n\n"},
[734] = {title = "Das wird schwierig", objective = "Sprecht im Ödland mit Lucien Tosselwrench.", description = "Wunderbar, wunderbar.\n\n<Lotwil sieht Euch einen Moment lang an, bevor er sich wieder seinen Fesseln zuwendet.>\n\nSprecht mit Lucien, <Name>. Ich brauche ein Zahnrad Nr. 5. Bringt es mir bitte, ja?", progress = nil, completion = "Ein Zahnrad Nr. 5, oh? Tja, das sieht nicht gut aus.", rewards = nil},
[735] = {title = "Der Stern, die Hand und das Herz", objective = "Bringt Gerrig Bonegrip in Ironforge die Gegenstände in Bonegrips Notiz.", description = "Yagyins Zusammenstellung', eh? Wollt Ihr vielleicht irgendwo eine neue Ortsgruppe aufbauen? Egal, es steht mir nicht zu, Euch das zu fragen.\n\nIch werde Euch helfen, weil ich ein Exemplar davon besitze, das ich entbehren kann. Und eine Hand wäscht die andere, stimmt's? Daher werden wir groß.\n\nIch brauche drei mächtige Gegenstände. Bringt sie mir, dann gebe ich Euch die Zusammenstellung.\n\nIch werde ihre Namen nicht nennen. Man könnte uns belauschen. Aber wartet, ich schreibe sie auf.", progress = "Habt Ihr die Relikte, um die ich gebeten habe?", completion = "Ihr seid sehr einfallsreich, &lt;Klasse&gt;. Wenn es wirklich Euer Begehr ist, ein neues Kapitel über unseren Orden zu beginnen, dann glaube ich, dass es Euch gut gelingen wird.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[736] = {title = "Der Stern, die Hand und das Herz", objective = "Bringt dem Bewahrer Bel'dugur in Undercity die Gegenstände von Bel'dugurs Notiz.", description = "Ihr braucht 'Yagyins Zusammenstellung'? Dann wollt Ihr also eine neue Herde sammeln? Natürlich... und natürlich werde ich Euch helfen, <Bruder/Schwester>.\n\nAber Ihr müsst mir auch helfen.\n\nIch brauche drei mächtige Gegenstände. Bringt sie mir, dann gehört die Zusammenstellung Euch.\n\nIch darf die Namen dieser Gegenstände nicht aussprechen, aber ich werde sie aufschreiben.\n\nBringt mir die Gegenstände, die auf dieser Liste stehen. Wenn Ihr das schafft, seid Ihr wahrlich würdig, ein eigenes Kapitel über unseren Orden zu beginnen.", progress = "Wie läuft Eure Mission, <Klasse>?", completion = "Ich bin beeindruckt! Ihr verfügt über große Fertigkeiten oder großes Glück, dass Ihr diese Relikte erlangt habt. So oder so, Ihr seid eine Bereicherung für uns.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[737] = {title = "Verbotenes Wissen", objective = "Bringt Theldurin 'Yagyins Zusammenstellung'.", description = "Ich habe die Zusammenstellung für Euch, <Name>. Ich muss Euch wohl nicht sagen, dass Ihr sie sorgfältig behandeln solltet. Und dass Ihr sie nicht in unfreundliche Hände gelangen lassen solltet. \n\nDieses Buch enthält viele Wahrheiten...\n\n... und die Wahrheit kann manchmal wehtun.", progress = "Ho! Ihr wart aber lange fort. Habt Ihr die Zusammenstellung?", completion = "Ihr habt sie! Oh, ein Hoffnungsschimmer!\n\nEure Bemühungen könnten uns retten, &lt;Name&gt;. Man sollte Euch ein Denkmal errichten! Einen Schrein sollte man bauen! Möge Euer Name gelobt sein, bis Eure Enkel selbst Enkel haben!\n\nEs sei denn... SIE sind frei und steigen an die Oberfläche. Wenn das geschieht, könnt Ihr das mit Kindern gleich vergessen.\n\nWenn SIE frei sind, dann sind wir alle Futter für die Würmer.", rewards = "Ihr bekommt:\n\nSchädel der drohenden Verdammnis"},
[738] = {title = "Sucht Agmond", objective = "Sucht Agmond.", description = "Ausgrabungsleiter Agmond hatte die Verantwortung über unsere Ausgrabungsstätten im Ödland, im Südwesten. Ich sagte \"hatte\", weil... also, ich habe schon seit Wochen nichts mehr von ihm gehört. Ich möchte, dass Ihr Agmond sucht, damit er mir Bericht erstatten kann.\n\nZuletzt hörte ich, dass sich Agmond in der südlichsten Grabungsstätte im Ödland aufhalten würde - einer winzigen Unternehmung hinter der Festung Angor. Ich würde dort mit der Suche beginnen.", progress = nil, completion = "Dieses Skelett, das müssen die traurigen Überreste Agmonds sein. Sein Körper ist zerschlagen und zerschmettert, die Knochen sind blankgenagt.", rewards = "Ihr bekommt:\n\nZerfetzter Ausgrabungsleiter-GürtelJadeGolderz"},
[739] = {title = "Murdaloc", objective = "Tötet Agmonds Mörder Murdaloc.\n\nTötet 12 Knochenknacker der Steingrufttroggs.\n\nErstattet Ausgrabungsleiter Ironband am Loch Modan Bericht.", description = "Agmonds Spuren führen nach Westen. Anhand der Blutspuren auf den Felsen und im Sand ist unschwer zu erraten, dass sich der Zwerg ein ganzes Stück weit geschleppt haben muss.\n\nUnd hier ist er dann gestorben.\n\nBei näherer Betrachtung ist das Wort \"Murdaloc\" erkennbar, das grob aus Sandsteinen des Ödlands zusammengestückelt wurde.\n\nDirekt neben Agmonds toter Hand.", progress = nil, completion = "Das sind ernüchternde Neuigkeiten, &lt;Name&gt;. Aber Agmond hatte einen starken Arm und einen erbarmungslosen Schlag mit seinem Hammer und sein Schädel war so dick wie kein anderer! Er wurde zwar von diesen verfluchten Troggs getötet, aber ich bin mir sicher, dass er eine Menge von ihnen mit in den Tod genommen hat.", rewards = "Ihr bekommt:\n\nFelspulverisierer"},
[741] = {title = "Der geistesabwesende Ausgrabungsleiter", objective = "Bringt dem Chefarchäologen Greywhisker in Darnassus das rätselhafte Fossil.", description = "Der Ausgrabungsleiter will also das geheimnisvolle Fossil zur Forscherliga nach Darnassus schicken? Es schmeckt mir gar nicht, Dunkelküste ohne ihn zu verlassen.\n\nHier, <Name>, bringt Ihr dem Chefarchäologen Greywhisker in Darnassus das rätselhafte Fossil.", progress = "Was kann ich für Euch tun, <Volk>?", completion = "Oha! Überlassen wir es Ausgrabungsleiter Remtravel, etwas über dieses Fundstück herauszufinden!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHammerfaust-HandschuheWindfilzhandschuheReliktjäger-Gürtel\n\nIhr bekommt außerdem:\n\n"},
[742] = {title = "Die Jagd in Ashenvale", objective = "Sprecht mit Seneni Thunderheart im Splintertreeposten in Ashenvale.", description = "Achtung, junge Abenteurer! Die Wildnis von Ashenvale erwartet Euch!\n\nDie Horde hat eine starke Präsenz in den Ländern nördlich des Brachlandes aufgebaut. Unsere beiden Außenposten - der Splintertreeposten und der Zoramstrandposten - wollen der Horde zu Ruhm gereichen! Diejenigen, die sich beweisen möchten, sollten dort nach Anleitung suchen. Wichtiger Hinweis: Senani Thunderheart im Splintertreeposten, direkt nördlich des Brachlandes, sucht Abenteurer, die an einer großen Jagd in Ashenvale teilnehmen wollen!", progress = nil, completion = "Willkommen an der neuen Grenze, &lt;Name&gt;. Ashenvale ist ein Land der unbegrenzten Möglichkeiten, eines, in dem jemand Eurer Art, &lt;Klasse&gt;, jede Menge Gelegenheiten finden wird, seinen Mumm unter Beweis zu stellen. Schaut Euch hier im Außenposten um und begebt Euch auf jeden Fall auch einmal hinaus zum Zoramstrand, denn die Horde hat dort noch einen weiteren Außenposten.\n\nEure Anwesenheit hier sagt mir, dass Ihr gekommen seid, um mehr über die Jagd zu lernen. Hört mir genau zu, und ich werde euch gern mitteilen, was Ihr wissen müsst.", rewards = "Ihr bekommt:\n\n"},
[743] = {title = "Windfuriengefahr", objective = "Bringt Ruul Eagletalon in Bloodhoof 8 Windfurienkrallen.", description = "Danke, dass Ihr Euch die Zeit genommen habt, mit mir zu sprechen, <Name>. Ich bin Ruul, Krieger und Lehrer.\n\nIhr habt offensichtlich ein Alter erreicht, in dem Ihr Euch auf Eure Aufgaben vorbereiten müsst, wenn Ihr auf Abenteuer weit außerhalb von Mulgore aus seid.\n\nWenn Ihr Eure Kraft erproben möchtet, versucht Euch zuerst an den Windfurienharpyien im Südosten. Sie treiben sich an den Bergrändern fernab der Straße herum.\n\nSie gehören mit zu unseren natürlichen Feinden hier in Mulgore und sind gut geeignet, um Eure Fertigkeiten einzuschätzen.", progress = "Die Windfurien sind tödliche Feinde. Ihre Kampfkraft wird nur von ihrer Gier nach Frischfleisch übertroffen.", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Ihr scheint gut vorbereitet zu sein, um weiterzureisen. Mögt Ihr stets Rückenwind haben.", rewards = "Ihr bekommt:\n\n"},
[744] = {title = "Vorbereitungen auf die Zeremonie", objective = "Sammelt 6 azurblaue und 6 bronzene Federn und bringt sie Eyahn Eagletalon in Thunder Bluff.", description = "<Name>, mein Bruder wird schon bald vor Häuptling Bloodhoof treten und es ist mir eine Ehre, einen Kopfputz für ihn anfertigen zu dürfen.\n\nIch möchte Euch um einen Gefallen bitten, während ich die letzten dieser Lederriemen gerbe. Ich habe keine Zeit mehr, um genügend Federn zu suchen, und ich habe mich gefragt, ob Ihr wohl noch ein paar für mich sammeln würdet?\n\nIhr könnt Federn in der richtigen Größe bei den Harpyien finden, die ganz weit im Norden und nordwestlich von Thunder Bluff leben. Ich brauche nur 6 azurblaue und 6 bronzene Federn, um die Ausführung zu vervollständigen.", progress = "Der Kopfputz wird bestimmt ein wunderbares Geschenk für meinen Bruder werden.", completion = "Danke für Eure Hilfe, &lt;Name&gt;.\n\nMein Part für die Zeremonie zu Ehren meines Bruders ist fast abgeschlossen. Jetzt muss ich ihm nur noch diesen Kopfputz geben und an der Zeremonie teilnehmen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGebundener HarnischStammeskriegerschild\n\nIhr bekommt außerdem:\n\n"},
[745] = {title = "Gemeinsame Nutzung des Landes", objective = "Tötet 10 Gerber der Bleichmähnen, 8 Kürschner der Bleichmähnen und 5 Wilderer der Bleichmähnen und kehrt dann zu Baine Bloodhoof in Bloodhoof zurück.", description = "Viele Konflikte verwunden dieses Land, <Name>. Ich hoffe, dass Ihr nicht so viele wie ich ertragen müsst. Es gibt nur einen, bei dem ich um Eure Mithilfe bitten möchte. Er wird Euch deutlich machen, wie schrecklich sogar eine kleine Bedrohung für das Land sein kann, wenn man sie ignoriert.\n\nBleichmähnengnolle haben sich südlich von Bloodhoof in einer Höhle im Westen niedergelassen. Sie missachten unsere Versuche, mit ihnen zu kommunizieren, und vernichten ungezügelt die Tierwelt Mulgores.\n\nWorte allein genügen nicht mehr als Antwort.", progress = nil, completion = "Es ist gut, dass Ihr meine Aufgabe so ernst genommen habt, &lt;Name&gt;. Respekt vor dem Land und seinen Kreaturen ist wichtig. Tod und Leben bilden einen Kreis... eine Notwendigkeit. Das eine kann nicht ohne das andere existieren. Nehmt Euch einen Moment Zeit, um darüber nachzudenken, und vergesst es niemals.", rewards = "Ihr bekommt:\n\nBlitzkügelchen"},
[746] = {title = "Zwergen-Buddelei", objective = "Sammelt 5 Ausgrabungsleiterhacken ein.\n\nZerschlagt die Ausgrabungsleiterhacken in einer Schmiede, um zerbrochene Werkzeuge zu erhalten.\n\nBringt Baine Bloodhoof in Bloodhoof 5 zerbrochene Werkzeuge.", description = "Im Nordwesten bereiten Zwerge eine Grabungsstätte vor. Sie glauben, dass Geheimnisse in der Erde verborgen seien, und das stimmt auch; dies ist jedoch kein Grund, das Land bei der Suche nach diesen Lehren auszuhöhlen und zu besudeln.\n\nSammelt die Grabwerkzeuge der Zwerge ein, zerstört sie und kehrt mit den zerbrochenen Werkzeugen der Zwerge zu mir zurück.\n\nIhr könnt die Werkzeuge in einer Schmiede zerschlagen. Ihr findet eine in Thunder Bluff, aber jede Schmiede, sogar eine Schmiede im Zwergenlager, eignet sich dazu.", progress = "Hallo, <Name>. Habt Ihr die zerbrochenen Werkzeuge? Die Graberei der Zwerge wird die Kodos von Mulgore wütend machen. Diese Besudelung muss aufhören!", completion = "Danke, &lt;Name&gt;. Das wird die Wildtiere von Mulgore beruhigen. Und, so die Geister gewillt sind, es wird die Zwerge lehren, dass die Aushöhlung des Landes nicht der Weg zu Wissen ist.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerstärkte BindungenGrobgehauene Kodogamaschen\n\nIhr bekommt außerdem:\n\n"},
[747] = {title = "Die Jagd beginnt", objective = "Grull Hawkwind im Camp Narache möchte, dass Ihr ihm 7 Ebenenschreiterfedern und 7 Stücke Ebenenschreiterfleisch bringt.", description = "Ihr seht viel versprechend aus, und ich denke, Ihr werdet Euch dem Stamm gegenüber beweisen. Vielleicht wird man Euch eines Tages in der großen Stadt Thunder Bluff willkommen heißen. Bevor das jedoch möglich ist, müsst Ihr Euch meinem Vater, Häuptling Hawkwind, beweisen.\n\nWir hier oben auf der Red Cloud Mesa sind stolz auf unsere hervorragenden Jagdfertigkeiten. Tauren jagen aus Notwendigkeit und als sportlichen Wettkampf. Unsere Fleischvorräte gehen zur Neige und wir brauchen Federn, um Kleidung herzustellen. Jagt die in der Nähe herumwandernden Ebenenschreiter und beweist Euch, indem Ihr für Nachschub für das Dorf sorgt.", progress = "Den Stamm mit Fleisch und Federn zu versorgen, das ist der erste Schritt, Euch dem Häuptling als Jäger zu beweisen.", completion = "Die &lt;Volk&gt; von Narache danken Euch, &lt;Name&gt;. Das war sehr vielversprechend.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nNomadengürtelBemalte Kettenhandschuhe\n\nIhr bekommt außerdem:\n\n"},
[748] = {title = "Vergiftetes Wasser", objective = "Bringt Mull Thunderhorn in Bloodhoof 6 Präriewolftatzen und 4 Ebenenschreiterkrallen.", description = "Goblins und ihre Gefolgsleute haben unsere heiligen Wasserbrunnen besudelt! Das dürfen wir nicht zulassen.\n\nUm alle Brunnen zu säubern, muss ich ein Säuberungstotem herstellen und Ihr müsst dieses Totem dann zu den Brunnen bringen und ein Säuberungsritual durchführen.\n\nZuerst werden wir ein Säuberungstotem für den Wasserbrunnen von Winterhoof herstellen. Dabei muss uns das Land behilflich sein. Jagt Präriewölfe wegen ihrer Tatzen und erwachsene Ebenenschreiter wegen ihrer Krallen. Sie sind im Südwesten zu finden.\n\nKehrt mit den Tatzen und Krallen zu mir zurück, <Name>.", progress = "Habt Ihr die Tatzen und die Krallen, <Name>?", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Ich werde ihre Macht jetzt an ein Totem der Säuberung binden.", rewards = "Ihr bekommt:\n\n"},
[749] = {title = "Die überfallene Karawane", objective = "Morin Cloudstalker möchte, dass Ihr den Inhalt einer Nachschubkiste der überfallenen Karawane untersucht.", description = "Vor ein paar Tagen haben wir am Nordufer des Stonebullsees eine bewachte Karawane der Venture Company entdeckt. Wir haben bei früheren Kämpfen mit ihnen zwei unserer Leute verloren, deshalb haben wir mit der Karawane kurzen Prozess gemacht.\n\nWir haben ihre Nachschubkisten zurückgelassen, weil wir dachten, unsere Fackeln würden alles Wertvolle zerstören, aber da man in der Nähe der ausgebrannten Wagen Bergungstrupps der Venture Company gesichtet hat, haben wir uns wohl geirrt.\n\nWürdet Ihr zur Karawane gehen und den Inhalt der Kisten untersuchen?", progress = nil, completion = "Die Kiste ist auf allen Seiten mit dem Zeichen der Bergbaugesellschaft Venture Company versehen. Die sorgfältig auf eine Seite des Kartons gedruckten Notizen geben an, dass der Inhalt zur Weiterverarbeitung in einer ihrer zentralen Fabriken gedacht ist.", rewards = "Ihr bekommt:\n\n"},
[750] = {title = "Die Jagd geht weiter", objective = "Grull Hawkwind im Camp Narache möchte, dass Ihr ihm 10 Bergpumapelze bringt.", description = "Ein Tauren, der in der Fertigkeit des Jagens bewandert ist, weiß, dass seine Beute nicht nur eine Trophäe ist. Die Wildtiere der Ebenen versorgen uns mit allem, was wir zum Überleben brauchen. Ihr würdet die Ältesten ziemlich beeindrucken, wenn Ihr ein paar hochgeschätzte Bergpumapelze erjagen würdet. Ihr findet die Wildtiere in den Hügeln im Süden.\n\nUnsere Kinder brauchen Kleidung und unsere Zelte müssen repariert werden.", progress = "Wenn Ihr für den Stamm Pelze besorgt, werde ich meinem Vater, Häuptling Hawkwind, von Euren großzügigen Taten berichten.", completion = "Die &lt;Volk&gt; von Narache danken Euch, &lt;Name&gt;. Eines Tages wird man Euch in Thunder Bluff bestimmt wegen Eurer Jagdfertigkeiten verehren.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nNomadenarmschienenBemalter Kettengürtel\n\nIhr bekommt außerdem:\n\n"},
[751] = {title = "Die überfallene Karawane", objective = "Bringt Morin Cloudstalker in der Nähe von Bloodhoof die Dokumente der Venture Company.", description = "Als Ihr den Deckel der Kiste aufstemmt, findet Ihr sie vollgestopft mit einem Sortiment aus Erzen und Mineralien, weitere Beweise für den Bergbau der Venture Company in Mulgore. Oben auf dem Erz und den Mineralien liegt ein fest verschnürtes Bündel Papiere, das Ihr an Euch nehmt.\n\nVom Vorgebirge im Osten her könnt Ihr schwach Arbeitsgeräusche hören und Ihr seht Rauch von einem großen Feuer aufsteigen.", progress = "Grüße, <Name>. Habt Ihr etwas Neues über die Pläne und Vorhaben der Venture Company in unserer Heimat erfahren?\n\nWenn sie vorhaben, unser Land so wie andere davor auszuplündern, werden die Kundschafter dem schnellstens ein Ende setzen.", completion = "Es scheint wirklich so, als wollte die Venture Company versuchen, unsere natürlichen Rohstoffe zu rauben. Gut, dass wir es endgültig wissen, und jetzt müssen wir wohl etwas dagegen unternehmen.", rewards = "Ihr bekommt:\n\n"},
[752] = {title = "Eine bescheidene Bitte", objective = "Häuptling Hawkwind möchte, dass Ihr seine Mutter beim Brunnen südöstlich vom Camp Narache sucht.", description = "Alle Mitglieder des Stammes teilen die Harmonie des Lebens miteinander. Wir leben und arbeiten zusammen.\n\nMit der Verpflichtung, füreinander da zu sein, haben wir eine große Verantwortung übernommen. Ich habe eine bescheidene Bitte an Euch.\n\nMeine Mutter ist heute Morgen fortgegangen, um Wasser aus dem Brunnen südöstlich von Narache zu holen. Das ist jetzt schon eine Weile her. Würdet Ihr wohl an meiner Stelle nach ihr sehen, während ich mich hier um Stammesangelegenheiten kümmere?", progress = nil, completion = "Ihr seid so weit gereist, nur um einer alten Frau zu helfen? So, so, Ihr glaubt, ich brauche einen Bewahrer?", rewards = "Ihr bekommt:\n\n"},
[753] = {title = "Eine bescheidene Bitte", objective = "Holt eine Wasserkanne vom Wasserbrunnen.\n\nBringt die Kanne Häuptling Hawkwind im Camp Narache, das nordwestlich des Wasserbrunnens liegt.", description = "Ich habe in meinem Leben so viele Pfade beschritten und meinen alten Beinen mangelt es an der Energie, die sie einst hatten. Ich kann aber immer noch meine Pflichten innerhalb des Stammes erfüllen. Manchmal braucht eine alte Frau eben nur etwas länger dafür.\n\nAber Ihr scheint mir ein eifriger <Klasse> zu sein. Wir sollten Eure jugendliche Vitalität auf die Probe stellen. Holt eine Wasserkanne vom Brunnen und bringt sie meinem Sohn, dem Häuptling im Camp Narache.\n\nVergesst nicht, dass selbst die bescheidenste Tat die Anerkennung der Ahnen finden kann.", progress = "Ihr seht aus, als wärt Ihr gerade erst aus den Ebenen zurückgekehrt. Habt Ihr etwas von Großmutter Hawkwind gehört?", completion = "Ihr habt diese Kanne wohl auf Großmutters Bitte hin zurückgetragen.\n\nEure Bereitschaft anderen zu helfen und für die &lt;Volk&gt; im Camp Narache zu sorgen, lässt mich glauben, dass die &lt;Volk&gt; in Thunder Bluff eines Tages stolz auf Euch sein können.", rewards = "Ihr bekommt:\n\n"},
[754] = {title = "Säuberung von Winterhoof", objective = "Benutzt das Säuberungstotem von Winterhoof beim Wasserbrunnen von Winterhoof und kehrt dann zu Mull Thunderhorn zurück.", description = "Ich habe das Totem angefertigt, um den Wasserbrunnen von Winterhoof zu säubern. Jetzt müsst Ihr es zum Brunnen bringen und ein Säuberungsritual durchführen. Ihr findet ihn im Südosten, bewacht von elenden Goblins!\n\nDas wird keine leichte Aufgabe, aber Ihr müsst es tun, wenn wir jemals wieder sein Wasser trinken sollen.\n\nViel Glück, <Name>.", progress = "Schiebt es nicht auf, <Name>. Die Besudelung des Winterhoof-Brunnens muss beseitigt werden!", completion = "Die Nachricht von Eurer Tat hat mich soeben erreicht - die Tiere im Umkreis des Brunnens trinken bereits wieder gierig daraus.\n\nIhr habt dem Land einen großen Dienst erwiesen, &lt;Name&gt;. Und Ihr habt dem Volk der &lt;Volk&gt; einen großen Dienst erwiesen.", rewards = "Ihr bekommt:\n\n"},
[755] = {title = "Riten der Erdenmutter", objective = "Begebt Euch zu Seher Graytongue, der in den Hügeln direkt südlich des Lagers Narache lebt.", description = "Eure Bereitschaft, für die Tauren von Narache eine bescheidene Bitte zu erfüllen, und Euer Eifer zu lernen sind edle Charakterzüge, <Name>. Ich weiß, eines Tages wird man in Thunder Bluff von Euch als einer bedeutenden Person sprechen, <Klasse>.\n\nBevor es so weit ist, müsst Ihr jedoch die Riten der Erdenmutter bestehen, derer es drei gibt.\n\nDie erste Prüfung ist der Ritus der Kraft. Begebt Euch zu Seher Graytongue und sagt ihm, dass Häuptling Hawkwind Euch schickt.\n\nIhr findet die Behausung des Sehers direkt südlich des Lagers Narache in den Hügeln verborgen.", progress = nil, completion = "Häuptling Hawkwind hat Euch geschickt? Die Riten der Erdenmutter zu bestehen ist keine leichte Aufgabe...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMal der Wildnis\n\nIhr bekommt:\n\n"},
[756] = {title = "Thunderhorn-Totem", objective = "Bringt Mull Thunderhorn 6 Pirscherklauen und 6 Pumaklauen.", description = "Um das Säuberungstotem von Thunderhorn zu schaffen, benötigt Ihr die Klauen der Raubtiere der Mulgoreebene. Jagt Präriepirscher wegen ihrer Pirscherklauen und Flachlandpumas wegen ihrer Pumaklauen und kehrt dann zu mir zurück.\n\nIhr findet die Präriepirscher und Flachlandpumas im Osten und Westen.", progress = "Habt Ihr die Klauen, um die ich bat, <Name>? Die Besudelung des Wasserbrunnens von Thunderhorn nimmt stündlich zu!", completion = "Danke, &lt;Name&gt;. Die Reinheit, mit der diese Wildtiere jagen, ist für die Schaffung des nächsten Säuberungstotems äußerst wichtig.\n\nDie Goblins werden niemals lernen, dass es einen Unterschied macht, ob man das Land bekämpft oder ob man im Einklang mit ihm lebt.", rewards = "Ihr bekommt:\n\n"},
[757] = {title = "Ritus der Kraft", objective = "Tötet die Borstennacken in der Dornrankenklamm und bringt Häuptling Hawkwind im Camp Narache 12 Gürtel der Borstennacken.", description = "Die Riten der Erdenmutter sind die Schritte, die ein junger Tauren gehen muss, um sich in Thunder Bluff Respekt zu verschaffen.\n\nIhr müsst zuerst den Ritus der Kraft bestehen. Bei dieser Prüfung müsst Ihr Euren Mut beweisen, indem Ihr Feinde des Stammes tötet.\n\nDer Borstennackenstamm aus der Dornrankenklamm im Osten ist in unser Stammesterritorium eingedrungen. Sie überfallen unsere Jägergruppen und rauben in der Dunkelheit unsere Dörfer aus.\n\nZeigt Euren Wagemut, indem Ihr diese Bösewichte zur Strecke bringt und dem Häuptling des Lagers Narache ihre Gürtel zum Beweis Eurer Taten vorlegt.", progress = "Habt Ihr den Ritus der Kraft schon absolviert, <Name>? Ich verlange einen Beweis für Euren Wagemut gegenüber den Feinden unseres Stammes, den Borstennacken.", completion = "Ihr habt die erste Prüfung der Riten der Erdenmutter bestanden. Der Stamm wird stolz auf Euch sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSteinstreitkolbenSteintomahawkSchnippelmesserÄltestenkrückstockKriegerheldenaxt\n\nIhr bekommt außerdem:\n\n"},
[758] = {title = "Säuberung von Thunderhorn", objective = "Benutzt dasSäuberungstotem von Thunderhorn beim Wasserbrunnen von Thunderhorn und kehrt dann zu Mull zurück.", description = "Das Totem ist bereit, <Name>. Und wiederum ist es Eure Aufgabe, das Ritual der Säuberung durchzuführen.\n\nGeht zum Wasserbrunnen von Thunderhorn nördlich des Dorfes und benutzt das Säuberungstotem von Thunderhorn bei Eurem Ritual. Kehrt danach zu mir zurück.\n\nMögen Euch die Geister leiten.", progress = "Der Wasserbrunnen von Thunderhorn ist immer noch besudelt, <Name>. Bitte, Ihr müsst das Ritual durchführen!", completion = "Die Vorfahren des Thunderhornklans haben in einem Traum zu mir gesprochen und Eure Handlungen in der Nähe ihres Brunnens gepriesen.\n\nSie möchten hiermit ihrer Dankbarkeit Ausdruck verleihen...", rewards = "Ihr bekommt:\n\nThunderhorn-Umhang"},
[759] = {title = "Wildmane-Totem", objective = "Bringt Mull Thunderhorn in Bloodhoof 8 Präriealphazähne.", description = "Es gibt nur noch einen Wasserbrunnen, der gesäubert werden muss; er trägt den Namen des Wildmaneklans. Damit dieser Brunnen wieder rein wird, muss das Land die Zähne eines wilden Raubtiers opfern, die eines Präriewolfalphatiers. Findet die Alphatiere im Norden und kehrt dann zu mir zurück, wenn Ihr Eure Jagd beendet habt.\n\nAlphatiere streifen oft am Fuße unserer mächtigen Stadt Thunder Bluff umher.", progress = "<Name>. Habt Ihr die Zähne, um die ich gebeten habe?", completion = "Sehr gut, &lt;Name&gt;. Ich kann das Opfer fühlen, das das Land gebracht hat, und mein Geist ist erfüllt von Traurigkeit und Stolz.", rewards = "Ihr bekommt:\n\n"},
[760] = {title = "Säuberung von Wildmane", objective = "Benutzt das Säuberungstotem von Wildmane beim Wasserbrunnen von Wildmane und kehrt dann zu Mull Thunderhorn zurück.", description = "Die Geister sprechen von Eurer Säuberung der Wasserbrunnen von Winterhoof und Thunderhorn, junger <Name>. Das Totem von Wildmane ist fertig und die letzte Aufgabe erwartet Euch.\n\nDer Wasserbrunnen von Wildmane liegt nördlich von Thunder Bluff. Führt das Ritual durch! Heilt das Land vom Gift der Goblins! Lasst das Wasser wieder klar und rein fließen!", progress = nil, completion = "Ihr habt es geschafft. Ihr habt die Brunnen gesäubert und unser Land geheilt. Ganz Bloodhoof dankt Euch, &lt;Name&gt;.\n\nMöge der Wind Kunde von Euren Taten in alle Welt tragen und mögen die Wasser von Mulgore bis in alle Ewigkeit rein sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZeremonieller TomahawkTraumbeobachter-Stab\n\nIhr bekommt außerdem:\n\n"},
[761] = {title = "Sturzfliegerjagd", objective = "Bringt Harken Windtotem in Bloodhoof 8 Trophäen-Sturzfliegerkiele.", description = "Der Sturzflieger ist ein gewitzter Vogel, der schwer zu finden und zu jagen ist. Eine Sammlung Sturzfliegerkiele ist ein Zeichen der Geschicklichkeit und Entschlossenheit eines Jägers.\n\nWenn Ihr gewillt seid, diese Aufgabe anzunehmen, zieht in die Ebene hinaus und jagt die Sturzflieger.\n\nBringt mir ihre Kiele und macht Eurem Klan Ehre.\n\nSturzflieger findet man überall in Mulgore, aber Ihr müsst sehr scharfe Augen haben, um sie zu entdecken, und Ihr braucht flinke Hufe, um sie zu fangen.", progress = "Habt Ihr die Sturzflieger gefunden, <Name>? Habt Ihr ihre Federkiele?", completion = "Ich weiß, dass es nicht leicht war, an diese Federkiele heranzukommen, &lt;Name&gt;. Ihr habt damit bewiesen, dass Ihr ein würdiger &lt;Klasse&gt; seid. Es ist gut, Euch hier in Bloodhoof zu haben.", rewards = "Ihr bekommt:\n\n"},
[762] = {title = "Ein Botschafter des Bösen", objective = "Tötet den Botschafter Infernus in der Festung Angor und bringt Berater Belgrum in Ironforge einen Beweis seines Tod.", description = "Ragnaros persönlich schickte den Gesandten Infernus zur Festung Angor, damit er dort die Suche der Zwerge der Schattenschmiede nach in Uldaman verschollenen Artefakten organisiert.\n\nUnser Volk hat bereits einen enormen Verlust erlitten, aber in letzter Zeit hat sich die Lage offensichtlich noch verschlimmert. Ich wage kaum zu schätzen, wie viele Artefakte sie finden und gegen Ironforge einsetzen könnten.\n\nUnser Ziel ist einfach, <Klasse>. Kehrt ins Ödland zurück und beseitigt den Botschafter Infernus. Sobald die Bedrohung aus der Welt geschafft ist, kehrt mit einem Beweis Eures Sieges zu Berater Belgrum zurück.\n\nEs liegt jetzt in Euren Händen.", progress = "Zeit ist hier entscheidend, <Name>. Ragnaros wird nicht abwarten, bis wir uns vorbereitet haben.", completion = "&lt;Name&gt;, es besteht kein Zweifel an Eurem Engagement für Ironforge und das Volk der Zwerge. Ich danke Euch für Eure Hilfe in dieser Angelegenheit.\n\nIch werde den Historiker Karnik wissen lassen, dass Ihr Erfolg hattet, und ich werde auch veranlassen, dass so bald wie möglich Hilfe ins Ödland geschickt wird, um die Ausgrabungsstätte zurückzuerobern. Nochmals danke.\n\nBevor Ihr geht, habe ich jedoch noch eine Bitte im Namen von König Bronzebeard an Euch.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nSchwert des Zwergenkapitäns"},
[763] = {title = "Riten der Erdenmutter", objective = "Bringt Baine Bloodhoof in Bloodhoof Hawkwinds Totem. Folgt der Straße, die aus dem Camp Narache herausführt.", description = "Damit Ihr die Riten der Erdenmutter fortsetzen könnt, müsst Ihr noch zwei weitere Prüfungen bestehen. Es ist an der Zeit, Eure Erfahrungen zu erweitern, <Name>.\n\nReist nach Bloodhoof und sprecht mit Häuptling Baine Bloodhoof, dem Sohn von Cairne. Dort könnt Ihr Eure Reise fortsetzen und Euch die Anerkennung der Ältesten von Thunder Bluff verdienen.\n\nBringt Baine dieses Totem. Er wird meine Schnitzereien erkennen und Euch helfen.\n\nFolgt der Straße, die aus dem Camp Narache herausführt, und beeilt Euch. Schweift nicht von der Straße ab, Ihr  könntet Euch sonst verirren.", progress = "Was führt Euch in mein Dorf, <Klasse>?", completion = "Eine Nachricht von meinem guten Freund Häuptling Hawkwind! Ah, seine Schnitzereien sagen mir, dass Ihr von besonderer Art seid.", rewards = "Ihr bekommt:\n\n"},
[764] = {title = "Die Venture Company", objective = "Tötet für Morin Cloudstalker in der Nähe von Bloodhoof 14 Tagelöhner der Venture Co. und 6 Vorsteher der Venture Co.", description = "Das erklärt auch die Aufstockung von Angestellten und Ausrüstung der Venture Company, die wir in Mulgore gesehen haben. Diese Goblins... ihre Firma wächst viel zu schnell, als dass es gut für sie wäre. Es heißt doch, zeigt man einem Goblin etwas, kann man gleich im Hintergrund die Registrierkasse klingeln hören.\n\nGierige kleine Teufel. Bedauerlich für ihre geschäftlichen Vorhaben, aber wir Tauren können es nicht zulassen, dass sie ihre Arbeiten hier in unserem Land durchführen. Begebt Euch zu ihrer Mine nordöstlich der überfallenen Karawane und schickt ihnen eine Nachricht.", progress = "Der Venture Company wurden die Bergbaurechte hier in Mulgore verweigert, aber es scheint so, als würde sie ein Nein als Antwort nicht akzeptieren. Wir <Volk> neigen jedoch nicht zu Haarspaltereien und wir haben andere Wege, unsere Nachricht klar rüberzubringen.", completion = "Ich glaube nicht, dass man dieses Signal fehldeuten oder ignorieren kann, oder? Die Venture Company wird die &lt;Volk&gt; nicht mehr auf die leichte Schulter nehmen oder so arrogant sein zu glauben, dass wir ihren Diebstahl der natürlichen Rohstoffe um uns herum einfach so widerstandslos hinnehmen.", rewards = "Ihr bekommt:\n\n"},
[765] = {title = "Vorsteher Fizsprocket", objective = "Tötet Vorsteher Fizsprocket und bringt Morin Cloudstalker in der Nähe von Bloodhoof dessen Klemmbrett.", description = "Laut der Dokumente, die Ihr von der Karawane geborgen habt, hat die Venture Company viele Pläne parat, um zu versuchen, uns von unserem Land hier zu vertreiben und damit freie Bahn zur Plünderung des Landes zu haben.\n\nIch bin entsetzt und es stößt mich ab, auf welches Niveau man sich herablassen kann, um seine Ziele durchzusetzen; ich will, dass der führende Kopf hinter ihren Plänen vernichtet wird. Er heißt Vorsteher Fizsprocket, Ihr findet ihn in der Mine der Venture Co. östlich der überfallenen Karawane. Bringt mir sein Klemmbrett, vielleicht finden wir damit ja etwas Nützliches heraus.", progress = "Ich koche vor Wut, wenn ich an all die Gräueltaten denke, die die Venture Company um des Profits Willen an uns begehen würde.", completion = "Die Nachricht vom Tod des Bösewichts Fizsprocket hat meine Wut etwas abgekühlt. Ich werde seine persönlichen Habseligkeiten durchsehen, um herauszufinden, ob es weitere Informationen über die Zukunftspläne der Venture Company gibt. Vielen Dank für Eure Bemühungen, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKompaktes StreitmesserGoblin-Zerkracher\n\nIhr bekommt außerdem:\n\n"},
[766] = {title = "Mazzranache", objective = "Bringt Maur Raincaller in Bloodhoof ein Herz eines Präriewolfs, einen Knochen eines Flachlandpumas, eine Schuppe eines Ebenenschreiters und einen Muskelmagen eines Sturzfliegers.", description = "Mein Großvater erzählte mir Geschichten von seinen Kämpfen gegen einen Schreiter namens Mazzranache. Er erzählte mir von seinen dämonischen roten Augen, rasiermesserscharfen Krallen und seinem giftigen Biss.\n\nWie der Zufall so spielt, stieß ich auf einer meiner Reisen durch die Ebene auf ihn und trug eine üble Bisswunde an meiner Schulter davon. Er war so Furcht erregend wie ihn mein Großvater beschrieben hatte. Ich werde ein paar nur sehr schwer zu findende Körperteile von Tieren benötigen, um die Infektion durch seinen Biss zu säubern: ein Herz eines Präriewolfs, einen Knochen eines Flachlandpumas, eine Schuppe eines Ebenenschreiters und einen Muskelmagen eines Sturzfliegers.\n\nSchnell, Zeit ist hier entscheidend.", progress = "Mein Fieber wird immer schlimmer und ich merke, wie ich langsam in schreckliche Alpträume abgleite... Ich hätte wissen müssen, dass ich keine Bestie bewältigen kann, die selbst mein Großvater nicht besiegen konnte...\n\nHabt Ihr die Zutaten für die Arznei? Ich fürchte, wenn ich die Infektion nicht bald säubere, wird das mein Ende sein.", completion = "Ah, danke, &lt;Name&gt;. Mit den Dingen, die Ihr mir gebracht habt, kann ich die Arznei herstellen, mit der ich die Ausbreitung der Infektion unterbinden und die Krankheit endgültig heilen kann. Ich schulde Euch meinen lebenslangen Dank.\n\nAber ich werde nie diesen schrillen Schrei vergessen, als sich Mazzranache auf mich stürzte, diese Explosion von Farben, als sich sein Schnabel senkte ...\n\nSeid vorsichtig auf Euren Reisen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nStiefel des KlippenläufersHandgelenksschützer des Ebenenjägers\n\nIhr bekommt außerdem:\n\n"},
[767] = {title = "Ritus der Sicht", objective = "Sprecht in Bloodhoof mit Zarlman Two-Moons.", description = "Der Ritus der Sicht, einer der Riten der Erdenmutter, wird Euch helfen, den Respekt der Ältesten von Thunder Bluff zu erlangen.\n\nUnser Volk hat gelernt, dass das Land unser allerheiligster Versorger ist. Um am Ritus der Sicht teilzunehmen, müsst Ihr mit dem geistigen Anführer des Dorfes sprechen, Zarlman Two-Moons.", progress = nil, completion = "Ich wusste, dass Ihr mich aufsuchen würdet, &lt;Klasse&gt;. Ich erkenne immer, wenn jemand versuchen möchte, die Riten der Erdenmutter zu bestehen.", rewards = "Ihr bekommt:\n\n"},
[768] = {title = "Leder sammeln", objective = "Bringt Veren Tallstrider in Thunder Bluff 12 Stücke leichtes Leder.", description = "Seid gegrüßt. Ihr habt so einen Glanz in den Augen; Ihr brennt darauf, in die Ebene zurückzukehren, um zu jagen. Möget Ihr Eurem Klan Ehre machen!\n\nIch arbeite mit den Häuten von Wildtieren und fertige daraus Kleidung und Rüstung für die Leute von Thunder Bluff.\n\nWenn Ihr Wildtiere jagt und mir ihre Häute bringt, fertige ich Euch etwas daraus.", progress = "Hallo. Wart Ihr auf der Jagd? Habt Ihr Häute für mich?", completion = "Ah, das sind aber besonders hübsche Stücke. Daraus kann ich feine Lederwaren herstellen.\n\nHier, &lt;Name&gt;. Nehmt das dafür...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTierhaut-GürtelDoppellagige Handschuhe\n\nIhr bekommt außerdem:\n\n"},
[769] = {title = "Kodobalgtasche", objective = "Bringt Veren Tallstrider in Thunder Bluff 4 Einheiten leichtes Leder und 4 grobe Fäden.", description = "Die Kodowildtiere von Mulgore sind stark und robust - Charaktereigenschaften, die wir sehr schätzen. Wenn Ihr in der Lederverarbeitung bewandert seid und wissen möchtet, wie man eine Kodobalgtasche fertigt, bringt mir die Materialien, die ich für mein Handwerk brauche.\n\nDann teile ich mein Wissen mit Euch.", progress = "Habt Ihr meine Materialien, <Name>?", completion = "Ah, gut. Danke, &lt;Name&gt;. Mein Herz springt vor Stolz, dass Ihr so am Lederverarbeitungshandwerk interessiert seid.", rewards = "Ihr bekommt:\n\nMuster: Kodobalgtasche"},
[770] = {title = "Der Dämonennarbenumhang", objective = "Sucht jemanden, der etwas über Geistheuler weiß.\n\nBereitgestellter Gegenstand: \n", description = "Der struppige Balg von Geistheuler trägt immer noch die schreckliche Wunde, die der Wolf im Kampf gegen die Brennende Legion davongetragen hat.\n\nVielleicht weiß jemand in Bloodhoof, wie Geistheuler starb...", progress = nil, completion = "Ich kann meinen alten Augen kaum glauben! Ihr habt den großen Wolf Geistheuler besiegt? Respekt, Respekt, &lt;Klasse&gt;, und das in Euren jungen Jahren! Ihr seid ein ganz außergewöhnlicher Jäger!\n\nLasst mich Euch etwas anbieten. Meine Tage des Jagens sind vorüber, aber ich würde mich geehrt fühlen, wenn Ihr mit einer meiner Waffen auf die Jagd gehen würdet.\n\nMöge sie ihr Ziel nie verfehlen und Euch Ruhm einbringen.\n\nUnd hoffen wir, dass Geistheulers Geist endlich Frieden gefunden hat.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSkorns HammerSkorns Gewehr\n\nIhr bekommt außerdem:\n\n"},
[771] = {title = "Ritus der Sicht", objective = "Sammelt 2 Quellsteine und 2 Bernsteinkörner und bringt sie Zarlman Two-Moons in Bloodhoof.", description = "Um den Ritus der Sicht zu bestehen, müsst Ihr die Zutaten sammeln, die für das Wasser der Seher benötigt werden:\n\nIch brauche Quellsteine, die man in der Nähe von Wasserbrunnen in Mulgore findet. Diese kombiniere ich mit Bernsteinkorn, das von den mächtigen Bäumen in unserem Land fällt.\n\nDiese Reagenzien enthalten magische Elemente, und wenn sie erhitzt und vor dem Stammesfeuer verzehrt werden, bekommt man eine Vision. Folgt ihr, dann wird sie Euch zum nächsten Schritt dieser heiligen Suche führen.", progress = "Sobald Ihr genügend Quellsteine bei den Wasserbrunnen und Bernsteinkörner unter den Bäumen gesammelt habt, bereite ich das Wasser der Seher für Euch zu.", completion = "Wie ich sehe, habt Ihr das Sammeln von unserem heiligen Land gelernt, &lt;Name&gt;. Es wird nur einen Augenblick dauern, bis ich das Wasser der Seher gebraut habe.", rewards = "Ihr bekommt:\n\n"},
[772] = {title = "Ritus der Sicht", objective = "Trinkt vor dem Stammesfeuer in Bloodhoof das Wasser der Seher und folgt der Vision, sobald sie erscheint.\n\nBereitgestellter Gegenstand: \n", description = "Hier ist es nun, das Wasser der Seher.\n\nWenn Ihr bereit seid, trinkt das Wasser in der Nähe des Stammesfeuers. Nachdem Ihr das heilige Wasser getrunken habt, wird es einen Moment dauern, bis die Vision vor dem Feuer erscheint.\n\nDann liegt es bei Euch, ihr zu Eurer Bestimmung zu folgen ...", progress = nil, completion = "Habt keine Angst, &lt;Name&gt;. Ihr habt den Ritus der Sicht erfolgreich bestanden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRegenwandler-StiefelSonnengebleichter Umhang\n\nDer folgende Zauber wird auf euch gewirkt:\n\nMal der Wildnis\n\nIhr bekommt außerdem:\n\n"},
[773] = {title = "Ritus der Weisheit", objective = "Reist von Thunder Bluff gen Osten zu den Teufelsfelsen und sprecht mit dem Vorfahrengeist.", description = "Um die Anerkennung der Ältesten von Thunder Bluff zu verdienen, müsst Ihr als Nächstes den Ritus der Weisheit absolvieren.\n\nJetzt, da Ihr den Ritus der Sicht bestanden habt, geben Euch die Vorfahrengeister der Teufelsfelsen den Segen unserer Vorfahren. Nur jene, die von dem Wasser der Seher getrunken haben, können diesen Segen erhalten.\n\nReist von Thunder Bluff gen Osten zu den Teufelsfelsen und sprecht mit dem Vorfahrengeist, <Name>.", progress = nil, completion = "Ihr habt in Eurem Verlangen, die Riten der Erdenmutter zu bestehen, großen Eifer erkennen lassen, &lt;Name&gt;.\n\nWir, die Vorfahrengeister, repräsentieren die mächtigen &lt;Volk&gt;, die mutig ihr Leben gaben, um das Fundament unserer großen Stadt Thunder Bluff zu legen und zu beschützen. Hiermit gebe ich die Pflicht des Schutzes an Euch weiter.\n\nIhr habt den Ritus der Weisheit bestanden, &lt;Klasse&gt;. Betretet Thunder Bluff mit Stolz.", rewards = "Ihr bekommt:\n\n"},
[775] = {title = "Reise nach Thunder Bluff", objective = "Sprecht in Thunder Bluff mit Cairne Bloodhoof.", description = "Jetzt wird man Euch in unserer großen Stadt verehren. Ein <Volk>, der würdig ist, die Riten der Erdenmutter abzuschließen, hat diese Ehre verdient.\n\nFür Eure letzte Aufgabe sucht unseren edlen Anführer Cairne Bloodhoof auf, der auf der höchsten Mesa in Thunder Bluff residiert.", progress = nil, completion = "Grüße, &lt;Klasse&gt;. Wie ich sehe, habt Ihr den Weg zu meiner Türschwelle gefunden.", rewards = "Ihr bekommt:\n\n"},
[776] = {title = "Riten der Erdenmutter", objective = "Cairne Bloodhoof in Thunder Bluff möchte, dass Ihr ihm das Horn von Arra'chea bringt.", description = "Ihr habt die Riten der Erdenmutter absolviert und Euch einen Platz in Thunder Bluff verdient.\n\nUm den Platz zu verteidigen, den Ihr Euch so hart erarbeitet habt, müsst Ihr allerdings auch weiterhin Euren Wert für unser Volk beweisen.\n\nWir sind Jäger, <Name>. Unten in Mulgore gibt es einen mächtigen Kodo namens Arra'chea. Zeigt mir Euer Können im Fährtenlesen und Jagen, indem Ihr mir das Horn von Arra'chea bringt.", progress = "Seid Ihr Arra'chea schon auf der Spur?", completion = "Gut gemacht! Das ist ein feines Jagdergebnis.\n\nIch werde einen Sammeltrupp losschicken, der den Kadaver holt, damit wir Balg und Fleisch bergen können.\n\nIhr habt unserem Volk einen großen Dienst erwiesen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nKodojäger-Gamaschen"},
[777] = {title = "Das wird schwierig", objective = "Bringt Lotwil Veriatus ein Zahnrad Nr. 5.", description = "Bitte sehr, das ist für Euch.\n\nIch werde hier drüben sein... in Deckung.\n\nGesellt Euch ruhig zu mir.", progress = "<Ohne von seinen Fesseln aufzusehen, streckt Lotwil seine Hand aus, seine Finger zucken ungeduldig.>\n\nDas Zahnrad, <Name>, das Zahnrad!", completion = "Ah, perfekt. Tretet zurück und seht, wie ich Geschichte schreibe!\n\n&lt;Lotwil setzt fieberhaft seine Arbeit fort.&gt;", rewards = nil},
[778] = {title = "Das wird schwierig", objective = "Besiegt den Fam'retor-Wächter und bringt Lotwils Fesseln der Elementarbindung zu Lotwil Veriatus zurück.", description = "Haha! Fertig! Die Fesseln sind fertig!\n\nDer Moment ist gekommen, Lucien. Der Moment ist gekommen, Servo!\n\nSeid Ihr bereit, Zeuge der perfekten Verschmelzung von Alchimie, Ingenieurskunst und des Arkanen zu werden, <Name>?\n\nIch werde jetzt einen mächtigen Elementar beschwören. Das ist heute ein Bahn brechender Tag für uns alle.", progress = "Mit diesem Resultat hatte ich eigentlich nicht gerechnet. Würdet Ihr mir wohl meine Fesseln zurückbringen?", completion = "Danke, &lt;Name&gt;. Das war wirklich eine Feuerprobe, nicht wahr?\n\nIch bin mir nicht sicher, was da schief gegangen sein könnte. Nur gut, dass meine Magie die Kreatur wieder in ihre Heimatebene zurückschicken konnte.\n\nEin kleines Zeichen meiner Anerkennung all Eurer harten Arbeit ...", rewards = "Ihr bekommt:\n\nSchicke Stoppuhr"},
[779] = {title = "Siegel der Erde", objective = "Hier liegt das Siegel der Erde, mit drei eingelassenen Nischen für den Amethystrunenstein, den Opalrunenstein und den Diamantrunenstein.", description = nil, progress = "Hier liegt das Siegel der Erde, mit drei eingelassenen Nischen für den Amethystrunenstein, den Opalrunenstein und den Diamantrunenstein.", completion = "Als Ihr die Runensteine in die entsprechenden Aussparungen legt, wird die Erde von einem heftigen Beben erschüttert und das Siegel bricht.", rewards = nil},
[780] = {title = "Die Kampfeber", objective = "Grull Hawkwind im Camp Narache möchte, dass Ihr für ihn Kampfeber tötet und ihm 8 Kampfeberschnauzen und 8 Kampfeberflanken bringt.", description = "Die Kampfeber der Dornrankenklamm im Osten sind in unser Stammesjagdterritorium eingedrungen. Sie wurden von den Borstennackenstachelebern, mit denen wir uns im Krieg befinden, abgerichtet, niederträchtig zu sein.\n\nTötet diese elenden Kreaturen und bringt mir ein paar ihrer Schnauzen und Flanken, damit wir daraus einen Eintopf für unsere Jungen zubereiten können.", progress = "Die Aggressivität der Kampfeber nimmt weiter zu. Habt Ihr ihnen einen deutlichen Warnschuss verpasst und mir ein paar Schnauzen und Flanken mitgebracht?", completion = "Sehr eindrucksvoll. Diese Zutaten werden einen feinen Eintopf ergeben und der Verlust dieser Eber sollte für die elenden Borstennacken eine ordentliche Lektion sein.", rewards = "Ihr bekommt:\n\nNomadenwesteZäher Brocken Brot"},
[781] = {title = "Angriff auf Camp Narache", objective = "Bringt Häuptling Hawkwind im Camp Narache die Angriffspläne der Borstennacken.", description = "Nachdem Ihr die Karte sorgfältig studiert habt, erkennt Ihr, dass Eure Entdeckung die geheimen Pläne des Grimmhauer-Kriegshäuptlings für eine ausgedehnte Belagerung des Lagers Narache sind.\n\nHäuptling Hawkwind wird diese Informationen sicherlich gut gebrauchen können!", progress = "Ihr seht besorgt aus, <Name>. Welche Neuigkeiten bringt Ihr?", completion = "Das ist in der Tat sehr beunruhigend! Aber durch diese Informationen können wir all unsere Brüder in Bloodhoof aufrufen, uns bei der Abwehr des Angriffs zu helfen. Ihr habt das Leben vieler &lt;Volk&gt; gerettet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nDickrindenrundschild"},
[782] = {title = "Zerbrochene Allianzen", objective = "Tötet Tho'grun und bringt Gorn in Kargath das Zeichen der Erde.", description = "Durch die Allianz der Horde mit dem Großdrachen Deathwing während des zweiten Krieges wissen wir, dass zwei ihrer Offiziere, Schattenbringer und Hematus, in der Lethlorklamm weit im Osten eingesperrt sind. Wir müssen unsere verderbten Verbündeten von damals zum Stillschweigen bringen, um die Ehre der Horde wiederherzustellen!\n\nWir hatten Tho'grun und seine Gruppe Ogersöldner angeheuert, damit sie uns helfen, das Zeichen der Erde in die Hände zu bekommen, ein Schlüssel, mit dem das Gefängnis des Drachen geöffnet werden kann. Tho'grun hat uns jedoch verraten, uns überrumpelt und ihn sich selbst angeeignet. Begebt Euch zum Camp Boff und holt ihn zurück!", progress = "Tho'gruns Verrat... wen wundert es da noch, dass die Oger nicht mehr der Horde angehören? Ich bin froh, dass er tot und das Zeichen der Erde wieder da ist.\n\nFalls Ihr ihn noch erledigt habt, dann verschwendet keine Zeit und geht zum Camp Boff. Es befindet sich südöstlich von Kargath.", completion = "Tho'grun ist tot, seine Leiche blank genagt von den Wüstenwinden und Aas fressenden Bussarden und die Oger sind demoralisiert. Es ist zwar nur ein kleiner Sieg, aber er wird zu einem größeren führen.\n\nDas Zeichen der Erde befindet sich jetzt in unserem Besitz und wir können das Gefängnis der Schwarzdrachen in Lethlor öffnen. Wir werden sie aus einer endlosen Gefangenschaft befreien, ungeachtet ihres Verdammnisses!", rewards = "Ihr bekommt:\n\n"},
[783] = {title = "Die Bedrohung von innen", objective = "Sprecht mit Marshal McBride.", description = "Ich hoffe, Ihr habt Euren Gürtel festgezurrt, <Klasse>, denn es gibt hier in Nordhain viel Arbeit.\n\nUnd ich meine damit nicht Landarbeit.\n\nDie Wachen von Stormwind haben alle Hände voll zu tun, um den Frieden zu bewahren; viele von uns weilen in fernen Ländern und viele Bedrohungen rücken immer näher. Deshalb rekrutieren wir jeden, der gewillt ist, seine Heimat zu verteidigen. Und die Allianz.\n\nFalls Ihr hier seid, um dem Aufruf zu folgen, sprecht mit meinem Vorgesetzten, Marshal McBride. Er ist in der Abtei hinter mir.", progress = nil, completion = "Ah, gut. Noch ein Freiwilliger. Es kommen viele davon in letzter Zeit.\n\nHoffentlich sind es genug.\n\nDas Menschenland wird von außerhalb bedroht und große Teile unserer Streitkräfte wurden ins Ausland beordert. Das lässt Raum für verderbte und gesetzlose Gruppen, die sich innerhalb unserer Grenzen ausbreiten können.\n\nWir kämpfen hier gleich an mehreren Fronten, &lt;Name&gt;. Stellt Euch auf eine lange Kampagne ein.", rewards = "Ihr bekommt:\n\n"},
[784] = {title = "Vernichtet die Verräter", objective = "Tötet 10 Matrosen von Kul Tiras, 8 Marinesoldaten von Kul Tiras sowie Lieutenant Benedict und kehrt dann zu Gar'Thok in Klingenhügel zurück.", description = "Angeführt von Admiral Proudmoore drangen die Menschen von Kul Tiras nach Durotar vor und brachen damit den Pakt, den der Kriegshäuptling vor Jahren mit Jaina Proudmoore geschlossen hatte, um Archimonde zu besiegen.\n\nDie Menschen-Aggressoren wurden zurückgeschlagen und Burg Tiragarde fiel. Kürzlich jedoch hat die Reserve des Admirals unter der Führung von Lieutenant Benedict die Burg zurückerobert und stellt erneut eine Bedrohung für unser Heimatland dar. Diese Menschen haben keinen Respekt vor Diplomatie.\n\nBeweist Eure Ehre und reist gen Süden zur Burg Tiragarde, um die Menschen-Eindringlinge zu eliminieren.", progress = "Ihr habt Eure Befehle, <Name>. Die Sicherheit Durotars ist in Gefahr. Erledigt die vor Euch liegende Aufgabe oder lasst aus Scham den Kopf hängen.\n\nZeigt, dass Ihr Ehre besitzt, und besiegt die Menschen auf Burg Tiragarde.", completion = "Die Kunde über Euren Mut verbreitet sich schnell, &lt;Klasse&gt;. In Orgrimmar wird man noch lange die Legende Eures Sieges auf Burg Tiragarde erzählen.", rewards = "Ihr bekommt:\n\n"},
[785] = {title = "Eine strategische Allianz", objective = "Sucht Lar Prowltusk an der Westflanke von Sen'jin auf.Thrall ist ein äußerst weiser und edler Anführer. Seine Beharrlichkeit auf dem Schlachtfeld wird nur von seinem diplomatischen Feingefühl übertroffen.\n\nDie Trolle der Darkspear haben sich als unschätzbare Verbündete für die Orcs erwiesen. Wir haben aus Loyalität und Ehrgefühl einen Schutzpakt mit ihnen geschlossen.\n\nDer Kriegshäuptling hat Befehle ausgegeben, dafür zu sorgen, dass unsere Darkspearfreunde in Sen'jin nicht unmittelbar in Gefahr sind. Einer ihrer verlässlichsten Späher, Lar Prowltusk, hat ein wachsames Auge auf ihre Westflanke.\n\nSucht Lar und unterstützt ihn notwendigenfalls.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Thrall ist ein äußerst weiser und edler Anführer. Seine Beharrlichkeit auf dem Schlachtfeld wird nur von seinem diplomatischen Feingefühl übertroffen.\n\nDie Trolle der Darkspear haben sich als unschätzbare Verbündete für die Orcs erwiesen. Wir haben aus Loyalität und Ehrgefühl einen Schutzpakt mit ihnen geschlossen.\n\nDer Kriegshäuptling hat Befehle ausgegeben, dafür zu sorgen, dass unsere Darkspearfreunde in Sen'jin nicht unmittelbar in Gefahr sind. Einer ihrer verlässlichsten Späher, Lar Prowltusk, hat ein wachsames Auge auf ihre Westflanke.\n\nSucht Lar und unterstützt ihn notwendigenfalls.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[786] = {title = "Vereitelung der Kolkaraggression", objective = "Lar Prowltusk außerhalb von Sen'jin möchte, dass Ihr die 3 Sets der Angriffspläne zerstört, die innerhalb der Kolkarklippe verwahrt werden.", description = "Sprecht leiser, <Klasse>. Die Zentauren der Kolkar liegen gleich hinter jener Kuppe im Westen der Kolkarklippe.\n\nWährend ihres Angriffs letzte Nacht schlich ich mich in ihr Dorf und fand heraus, dass diese dreckigen Bestien einen dreistufigen Angriff auf die Trolle und Orcs von Durotar geplant hatten.\n\nIhre Invasion muss verhindert werden. Vielleicht könnt Ihr die Streitmacht zusammenziehen, die nötig ist, um die Kolkarklippe zu unterwandern und deren Angriffspläne zu vernichten.\n\nZuletzt sah ich, dass Sie sich auf drei ihrer Anführer verteilten.", progress = "Die Zentauren haben bewiesen, dass sie für die Horde eine andauernde Plage darstellen. Ihre Absichten, unsere Heimat zu belagern, dürfen nicht einfach so hingenommen werden.", completion = "Die Horde würde einen Angriff der Kolkarzentauren sicherlich überstehen. Aber wenn wir einen solchen Angriff verhindern, ersparen wir unnötiges Blutvergießen unter unseren mächtigen Kriegern.\n\nUnd so sicher wie es Sand in der Wüste von Tanaris gibt, wissen wir, dass Blut vergossen werden wird, bevor diese schwierigen Zeiten hinter uns liegen.\n\nIhr habt unserem Volk gut gedient, &lt;Klasse&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErfahrener Kämpfer-UmhangSchwere Kordel-Armschienen\n\nIhr bekommt außerdem:\n\n"},
[787] = {title = "Die neue Horde", objective = "Meldet Euch bei Gornek beim Höhlenbau.Throm-ka, <Klasse>. Ich bin Eitrigg, von Thrall beauftragt, die Ausbildung der Rekruten zu beaufsichtigen.\n\nDie Horde ist nicht mehr das, was sie einmal war. Es gab eine Zeit, da ich die Horde verließ, enttäuscht durch den wachsenden Einfluss der machthungrigen Marionetten der Brennenden Legion. Während meines Exils wurde ich von einer Gruppe Menschen gefangen genommen, aber dann von dem Kriegshäuptling gerettet. Er erzählte mir von seiner Vision einer Horde, frei von dämonischen Einflüssen, von den Schamanen geleitet, und so kehrte ich zurück.\n\nGornek wird weitere Anweisungen für Euch haben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Throm-ka, <Klasse>. Ich bin Eitrigg, von Thrall beauftragt, die Ausbildung der Rekruten zu beaufsichtigen.\n\nDie Horde ist nicht mehr das, was sie einmal war. Es gab eine Zeit, da ich die Horde verließ, enttäuscht durch den wachsenden Einfluss der machthungrigen Marionetten der Brennenden Legion. Während meines Exils wurde ich von einer Gruppe Menschen gefangen genommen, aber dann von dem Kriegshäuptling gerettet. Er erzählte mir von seiner Vision einer Horde, frei von dämonischen Einflüssen, von den Schamanen geleitet, und so kehrte ich zurück.\n\nGornek wird weitere Anweisungen für Euch haben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[788] = {title = "Scharfe Zähne", objective = "Tötet 10 scheckige Eber und kehrt dann zu Gornek beim Höhlenbau zurück.", description = "Als Erstes werden wir Euer Rückgrat etwas kräftigen. Ich könnte Euch ins Brachland schicken, um Kodos zu jagen, aber mal ehrlich, lebend seid Ihr uns nützlicher als tot.\n\nIch glaube, die scheckigen Eber nördlich von hier wären genau das Richtige für Euch.", progress = nil, completion = "Hmmm, nicht schlecht, &lt;Name&gt;. Aber bildet Euch nur nichts darauf ein... Ihr werdet in Eurem Leben noch gegen ganz andere Gegner als Eber kämpfen müssen.\n\nWie dem auch sei, Ihr habt Euch gut gehalten und Eure nächste Aufgabe wird es sein, einen erheblich gefährlicheren Gegner zu bekämpfen, also braucht Ihr etwas zusätzlichen Schutz.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWeiche WollstiefelKampferprobte Lederhandschuhe\n\nIhr bekommt außerdem:\n\n"},
[789] = {title = "Stich des Skorpiden", objective = "Bringt 10 Skorpidarbeiterschwänze zu Gornek im Höhlenbau.", description = "Sowohl mächtige Krieger als auch tollpatschige Anfänger fallen dem Giftstachel der Skorpiden zum Opfer. Nordwestlich von hier findet Ihr eine größere Ansammlung Skorpiden. Bringt mir 10 ihrer Schwänze als Beweis für Eure Leistungsfähigkeit im Kampf.\n\nDas Gegengift für ihren Stich wird aus genau dem Gift, das aus ihren Stacheln extrahiert wurde, gewonnen. Wir haben immer einen großen Vorrat an Gegengift für dieses Skorpidgift, um Grünschnäbel wie Euch damit zu heilen...\n\nAber Ihr werdet das doch bestimmt nicht brauchen, oder?", progress = "Der Knochenpanzer eines Skorpiden ist nicht so dick, dass sich ein kräftiger und entschlossener Krieger davon abschrecken lässt. Schlagt fest und ohne Zögern zu, dann sollten sich die Skorpide als leichte Beute erweisen.", completion = "Es gibt eine wichtige Lektion, die Ihr bei Euren Kämpfen gegen Skorpide gelernt haben solltet. Nicht nur die größten, sondern auch die kleinsten Gegner können Euch zum Verhängnis werden. In einem erbitterten Kampf kann Euch alles Mögliche das Genick brechen.\n\nIch kann Euch nichts weiter beibringen, &lt;Name&gt;. Ihr habt Euch sehr gut entwickelt und ich werde Eure Fortschritte mit Interesse verfolgen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWeicher WollgürtelKampferprobtes Cape\n\nIhr bekommt außerdem:\n\n"},
[790] = {title = "Sarkoth", objective = "Tötet Sarkoth und bringt seine Klaue zu Hana'zua.", description = "<Klasse>! Ich dachte schon, ich müsste hier draußen sterben und niemand würde es bemerken. Auf der Jagd nach den Skorpiden des Tals stieß ich auf ein besonders heimtückisches Exemplar. Ich stürzte mich auf ihn und konnte einer seiner Klauen einen ordentlichen Draufschlag versetzen, bevor sie sich um mein Bein schloss.\n\nIch hatte jedoch nicht mit seinem Stecher gerechnet, den er tief in meine Brust trieb, mit dem er mein Fleisch zerschnitt und mir einen großen Blutverlust verursachte. Bitte, Ihr müsst den Skorpid für mich töten! Meine Ehre darf nicht besudelt werden! Da oben auf dem Plateau im Süden habe ich gegen ihn gekämpft.", progress = "Ah... mein Vater sagte immer, aus mir würde nie etwas werden. Ich fürchte, so, wie ich hier unter dem Baum liege, während mein Leben mir zwischen den Fingern zerrinnt, sieht es aus, als hätte er Recht gehabt.\n\nIch wünsche mir nur, mit dem Wissen sterben zu können, dass mein letzter Feind in diesem Leben tot ist.", completion = "Mein Schlag war nicht stark genug, um ihn zu töten, aber wenn ich mir den Schaden ansehe, den ich verursacht habe, macht es mich doch ein bisschen stolz. Mit diesem bisschen Stolz muss ich mich zufrieden geben, wenn ich sterbe; doch in diesem Licht betrachtet, erfüllt mich die kurze Liste meiner im Leben erreichten Leistungen mit Wut.", rewards = "Ihr bekommt:\n\n"},
[791] = {title = "Akzeptiert Euer Schicksal", objective = "Furl Scornbrow im Wachturm von Klingenhügel möchte 8 Segeltuchreste haben.", description = "Das Alter hat mich nutzlos für die Schlacht gemacht. Jetzt mache ich mich eben auf andere Weise nützlich.\n\nVon diesem Aussichtspunkt aus achte ich auf Eindringlinge. Während unsere Kraft hier zunimmt, muss ich mein Signalhorn immer seltener benutzen.\n\nUm mir die Zeit zu vertreiben, fertige ich Dinge an, die den jüngeren und fähigeren Kriegern bei der Verteidigung unserer Heimat helfen können.\n\nFür Euch könnte ich eine Tasche für Eure Habseligkeiten anfertigen. Falls ein solcher Gegenstand Euch nützlich sein könnte, bringt mir etwas Segeltuch, ein Material, das unter Menschen und Zentauren verbreitet ist.", progress = "Als wir in diesem Land Pionierarbeit leisteten, kämpfte ich stolz an der Seite des Kriegshäuptlings. Meine Haut ist mit Narben von Kämpfen übersät.\n\nDie Ehre der Horde wurde durch meine Axt und meinen Kampfschrei während des Besiegens von Archimonde gefestigt, als die unheilige Allianz mit den Menschen und Elfen aus der Not heraus geschlossen wurde.\n\nAber meine Stellung als Wachmann und Versorger hat meinem Leben einen neuen Sinn gegeben.", completion = "Ausgezeichnet, &lt;Name&gt;. Jeder gute &lt;Klasse&gt; wird für diese Tasche auf dem Schlachtfeld eine Verwendung finden.\n\nIch salutiere vor Eurer Schlagkraft und Bereitschaft, im Namen der Horde zu sterben!", rewards = "Ihr bekommt:\n\nHandgefertigte Ledertasche"},
[792] = {title = "Üble Familiare", objective = "Tötet 12 üble Familiare.\n\nKehrt dann zu Zureetha Fargaze beim Höhlenbau zurück.", description = "Ich denke, das Tal der Prüfungen wird Euch viel lehren, <Klasse>.\n\nMan hat mich eigentlich ins Tal geschickt, um Euch anzuleiten, aber ich habe dort eine sich ausbreitende Besudelung entdeckt...\n\nEine Gruppe, die sich die 'Burning Blade' nennt, hat hier im Tal der Prüfungen einen Koven für ihre Mitglieder. Sie lungern im Nordosten in einer Höhle herum und ihre üblen Familiare kriechen daraus hervor, um Chaos anzurichten.\n\nAls erste Aktion gegen die Burning Blade bitte ich Euch, diese Familiare zu vernichten. Tötet so viele Ihr könnt, und falls Ihr überlebt, kehrt zu mir zurück.", progress = nil, completion = "Das habt Ihr gut gemacht, &lt;Name&gt;.\n\nDie elenden Familiare waren zwar nur Schoßtiere der dunkleren Mächte der Burning Blade, aber Euer Sieg über sie lässt mich ahnen, dass noch größere Taten folgen werden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPrimitive KeulePrimitive HandklingePrimitives KriegsbeilPrimitiver Wanderstecken\n\nIhr bekommt außerdem:\n\n"},
[793] = {title = "Zerbrochene Allianzen", objective = "Benutzt das Zeichen der Erde, um die Säulen aus Diamant, Opal und Amethyst zu aktivieren und die Runensteine zu holen.\n\nLegt die Runensteine auf das Siegel der Erde, um Schattenbringer und Hematus zu befreien.\n\nTötet sie und bringt dann Gorn Schattenbringers Bindung, Hematus' Ketten und das Zeichen der Erde.", description = "Das Siegel der Erde wird von drei Runensteinen gebildet, die in der Lethlorklamm auf Säulen aus Diamant, Opal und Amethyst liegen. Ihr könnt die Runensteine mit Hilfe des Zeichens der Erde entfernen und so das Siegel der Erde brechen.\n\nSeid jedoch vorsichtig, <Name>, die Schwarzdrachen Schattenbringer und Hematus sollte man nicht unterschätzen. Tötet sie und kehrt mit ihren Bindungen zu mir zurück.\n\nUm die Klamm zu erreichen, müsst Ihr in den östlichsten Teil des Ödlandes reisen. Lasst jedoch Vorsicht walten, da die Klamm zahllose Drachen beherbergt.", progress = "Es gibt nur wenige Feinde, die tödlicher als Großdrachen sind, und es gab nur wenige Großdrachen, die so unerbittlich kämpften wie Schattenbringer und Hematus.", completion = "Der schwarze Drachenschwarm ist weiter mit den abtrünnigen Orcs der Blackrock verbündet, und beide müssen entweder zur Einsicht gebracht oder ausgelöscht werden. Da Schattenbringer und Hematus tot sind, können wir unsere Aufmerksamkeit westwärts auf die Blackrockspitze richten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLohenwindbrustplattePrismaschuppenhalsbergeKriegsgeschmiedete BrustplatteGedankenexplosion-Medaillon\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[794] = {title = "Medaillon der Burning Blade", objective = "Bringt Zureetha Fargaze beim Höhlenbau das Medaillon der Burning Blade.", description = "Durch meine hellseherischen Kräfte weiß ich, dass im Koven der Burning Blade ein Gegenstand der Macht verborgen ist, der durch Bestien und schwarze Magie bewacht wird.\n\nEr wird das Medaillon der Burning Blade genannt und Eure nächste Aufgabe besteht darin, es zu finden und aus dem Koven zu entfernen.\n\nSeid jedoch vorsichtig, denn das Medaillon könnte im Besitz eines Agenten der Burning Blade sein, und falls dem so ist, ist die Macht dieses Agenten weitaus stärker als die der Familiare, auf die Ihr bereits gestoßen seid.\n\nGeht, <Name>. Ihr findet den Koven in einer Höhle im Norden und Westen.", progress = "Ist Euer Auftrag beendet, <Name>? Habt Ihr das Medaillon der Burning Blade?", completion = "Ihr habt es! Gut gemacht!\n\nEure Bemühungen im Koven der Burning Blade sind der Schlüssel für die Ausrottung dieses Kults im Tal der Prüfungen. Ich fürchte jedoch, dass sie in unserem Land noch mehr vorhaben.\n\nNoch sind wir sie nicht endgültig los.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nStaubbedeckte GamaschenGezackte KettenwesteZerfetzte Hose\n\nIhr bekommt außerdem:\n\nSchwacher Heiltrank"},
[795] = {title = "Siegel der Erde", objective = "Hier liegt das Siegel der Erde, mit drei eingelassenen Nischen für den Amethystrunenstein, den Opalrunenstein und den Diamantrunenstein.", description = nil, progress = "Hier liegt das Siegel der Erde, mit drei eingelassenen Nischen für den Amethystrunenstein, den Opalrunenstein und den Diamantrunenstein.", completion = "Als Ihr die Runensteine in die entsprechenden Aussparungen legt, wird die Erde von einem heftigen Beben erschüttert und das Siegel bricht.", rewards = nil},
[804] = {title = "Sarkoth", objective = "Informiert Gornek beim Höhlenbau über Hana'zuas Notlage.", description = "Was Ihr für mich getan habt, gibt mir Zuversicht. Ich darf nicht einfach so gehen! Ich muss durchhalten!\n\nOhne Hilfe schaffe ich jedoch den Weg zurück zum Höhlenbau nicht. Bitte, <Name>, kehrt zum Höhlenbau zurück und berichtet Gornek von meiner Lage. Vielleicht kann er mir helfen.", progress = nil, completion = "Eurer Beschreibung der Bestie nach bin ich mir sicher, dass es sich um Sarkoth handelt! Kein Wunder, dass Hana'zua damit überfordert war. Wir werden ihm sofort Hilfe schicken, also macht Euch keine Gedanken mehr um Hana'zuas Notlage.\n\nIch muss jedoch sagen, dass ich zutiefst beeindruckt bin zu hören, dass Ihr Sarkoth besiegt habt. Das ist eine Leistung, auf die Ihr stolz sein könnt, &lt;Name&gt;. Und dass Ihr für die Ehre eines Fremden kämpft, obwohl Ihr doch mit anderen Dingen beschäftigt seid, trägt nur zu Eurer eigenen Ehre bei.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWeiche WollwesteKampferprobte Kettengamaschen\n\nIhr bekommt außerdem:\n\n"},
[805] = {title = "Bericht erstatten in Sen'jin", objective = "Sprecht mit Meister Gadrin in Sen'jin.", description = "Eure Prüfungen durch die Burning Blade sind beendet... jedenfalls hier im Tal. Ich möchte aber, dass Ihr von Euren Funden berichtet.\n\nBegebt Euch in das Trolldorf Sen'jin und sucht nach Meister Gadrin. Sen'jin liegt östlich hinter dem Tal und dann geht es an der Weggabelung nach rechts.\n\nBerichtet Gadrin von den Burning Blade und dass sie das Tal der Prüfungen erreicht haben. Bringt von ihm in Erfahrung, ob sie Sen'jin schon erreicht haben.\n\nGeht, <Name>, und beeilt Euch. Ich fürchte, dass das Böse, das wir im Koven der Burning Blade entdeckt haben, nur der Vorbote eines viel größeren Übels ist...", progress = nil, completion = "Hm... Euer Bericht kommt zu einem schlechten Zeitpunkt. Die Burning Blade wurden hier in Sen'jin noch nicht gesehen, aber das Böse ist vor der Küste auf den Echoinseln auf fruchtbaren Boden gefallen.\n\nDie Orcs sind Freunde der Darkspeartrolle. Ehrenhafte Freunde. Wir wollen den Orcs helfen, aber... wir benötigen ebenfalls Hilfe.", rewards = "Ihr bekommt:\n\n"},
[806] = {title = "Dunkle Stürme", objective = "Bringt Fizzles Klaue zu Orgnil Soulscar in Klingenhügel.", description = "Wir können den Burning Blade nicht erlauben, in Durotar Fuß zu fassen! Wir müssen sie vernichten, bevor das Böse zu schwären beginnt!\n\nIch habe selbst Nachforschungen unternommen und herausgefunden, dass ein Hexenmeister der Burning Blade, der Goblin Fizzle Dunkelsturm, nahe dem Donnergrat im Nordwesten kampiert. Er und seine Kultdiener verbreiten dort Chaos.\n\nSucht und besiegt Fizzle und bringt mir seine Klaue!", progress = "Habt Ihr Fizzle gefunden, <Name>? Er und der Rest der Burning Blade müssen von unserem Land vertrieben werden!", completion = "Aha! Ihr habt ihn!\n\nIhr macht Eurem Klan alle Ehre, &lt;Name&gt;. Und dank Euch ist Durotar jetzt von einem weiteren Agenten des Bösen befreit.", rewards = "Ihr bekommt:\n\nTigerbalg-Stiefel"},
[808] = {title = "Minshinas Schädel", objective = "Holt Minshinas Schädel aus dem Kreis der Macht auf den Echoinseln.\n\nBringt ihn Meister Gadrin in Sen'jin.", description = "Ich höre die Stimme meines Bruders Minshina, der in meinen Träumen zu mir spricht.\n\nEr wurde von Zalazane, dem Hexenmeister auf den Echoinseln im Osten, gefangen genommen. Und er ist tot.\n\nAber der Tod bedeutet nicht Freiheit für meinen Bruder. Minshinas Geist ist durch Zalazanes Magie in seinem eigenen Schädel gefangen. In meinen Träumen sehe ich ihn zusammen mit weiteren Schädeln in einem Kreis der Macht auf der Größten der Echoinseln. Solange er dort bleibt, ist die Seele meines Bruders verdammt.\n\nBitte, <Name>. Sucht den Kreis und bringt Minshinas Schädel zurück. Bringt ihn mir.\n\nBefreit ihn!", progress = "Habt Ihr den Schädel meines Bruders, <Name>? Ist er endlich frei?", completion = "Danke, &lt;Name&gt;. Ihr habt Minshina gerettet. Ihr habt den Geist meines Bruders aus der Sklaverei befreit!", rewards = "Ihr bekommt:\n\nSchwach leuchtender Schädel"},
[809] = {title = "Ak'Zeloth", objective = "Sprecht im Brachland mit Ak'Zeloth.", description = "Seit dem letzten großen Krieg, in dem die Brennende Legion besiegt wurde, suche ich nach den Quellen dämonischer Verderbnis innerhalb der Orc-Gesellschaft. Das Halsband, das Ihr mir brachtet, bestätigt meine Befürchtungen.\n\nEs gehört den Burning Blade, einem Kult, der sich um einen Gegenstand dämonischer Macht schart. Er wird 'Dämonensaat' genannt und im Brachland hoch über dem Glutnebelgipfel aufbewahrt. Er muss zerstört werden!\n\nGeht zum Farwatch-Posten an der Grenze zum Brachland im Westen und sprecht dort mit meinem Assistenten Ak'Zeloth. Er wird Euch weitere Anweisungen geben.", progress = nil, completion = "Neeru wünscht also, dass die Dämonensaat zerstört wird? Seltsam...\n\nWohlan denn. Wenn er möchte, dass die Saat verschwindet, dann werde ich Euch erklären, wie man sie entfernt.", rewards = "Ihr bekommt:\n\n"},
[812] = {title = "Heilmittel benötigt", objective = "Sucht Kor'ghan in Orgrimmar und besorgt das Siechstachelgegengift. Bringt das Gegengift dann zu Rhinag an der nordwestlichen Grenze von Durotar.", description = "<Name>, Ihr hättet den Zeitpunkt nicht besser wählen können. Ich hoffe nur, dass ich Euch auch zu Eurer Eile beglückwünschen kann.\n\nWährend eines Kampfes mit ein paar Siechstachelskorpiden war ich unvorsichtig und ich wurde von einem von ihnen heftig gestochen. Während wir uns unterhalten, spüre ich, wie sein Gift mich schwächt. Bei dieser Geschwindigkeit bleibt mir vielleicht noch eine Stunde zu leben. Aber selbst dazu brauche ich Eure Hilfe...\n\nKor'ghan in Orgrimmar weiß, wie man das Gegengift herstellt. Sucht ihn... und zwar schnell, <Name>. Ich werde nicht mehr lange durchhalten. Er sollte sich in der Kluft der Schatten befinden.", progress = "Ich bin fast froh, dass ich in meinem jetzigen Zustand nicht nach Sen'jin zurückkehren kann. Man würde dort sicherlich über meine Schwäche und Dummheit spotten.", completion = "&lt;Name&gt;, Ihr habt mir das Leben gerettet. Danke.\n\nBitte nehmt das hier; ich hoffe, es kann Euch auf Euren Reisen behilflich sein, wenn nicht sogar ein bisschen Geld einbringen. Wie Ihr sagtet, werde ich es wohl in nächster Zeit nicht benötigen. Kor'ghan wird mir noch weitere seiner Rituale auferlegen, bevor ich mich bewiesen habe. Noch mehr Eber töten, noch mehr Skorpidschwänze sammeln...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAngriffs-RundschildLeichte Skorpidrüstung\n\nIhr bekommt außerdem:\n\n"},
[813] = {title = "Suche nach dem Gegengift", objective = "Bringt Kor'ghan in Orgrimmar 4 Giftbeutel eines Siechstachelskorpiden.", description = "Siechstachelskorpide sind eine der tödlichsten Skorpidarten in ganz Durotar. Es war dumm von Rhinag, sie zu jagen, ohne etwas von dem Gegengift mit sich zu führen, aber momentan ist eine ordentliche Standpauke das Letzte, was er benötigt.\n\nBringt mir ein paar Giftbeutel von den Siechstachelskorpiden in der Nähe des Eingangs nach Orgrimmar, dann stelle ich ein Gegengift für ihn her.\n\nBeeilt Euch, <Name>. Einer der Unseren braucht Eure Hilfe.", progress = "Denkt daran, es spielt keine Rolle, welche Kreatur Ihr jagt, aber Ihr tätet gut daran, sie vorher zu studieren und ihre Verhaltensweisen zu kennen. Dieses Wissen könnte Euch das Leben retten.", completion = "Hier habt Ihr das Gegengift, &lt;Name&gt;. Bringt es so schnell wie möglich Rhinag und seid vorsichtig.", rewards = "Ihr bekommt:\n\nSiechstachelgegengift"},
[815] = {title = "Zerbrecht ein paar Eier", objective = "Bringt dem Koch Torka in Klingenhügel 3 Schwanzpeitscher-Eier.", description = "Pah! Jetzt hätte ich doch beinahe vergessen, Frühstück zu machen.\n\n<Name>, setzt Euch in Bewegung und bringt mir ein paar Schwanzpeitschereier. Ich brauche mindestens drei davon, wenn ich genug für die morgige Mahlzeit haben möchte.\n\nDie Blutkrallenschwanzpeitscher können ganz schön wild sein und beschützen ihre Eier bis in den Tod. Manchmal vergraben sie ihre Eier allerdings zu tief in der Erde, um sie sicher ausgraben zu können, aber reist doch zu den Echoinseln südöstlich von Sen'jin, dort findet man sie gewöhnlich überall auf den Inseln verteilt.", progress = "Frühstück, Mittagessen, Abendbrot! Wen kümmert's schon, welche Mahlzeit dran ist? Sie müssen trotzdem von jemandem zubereitet werden - und dieser Jemand bin ich!", completion = "Ihr mögt zwar schwach sein, aber wenigstens seid Ihr nicht ungeschickt, &lt;Name&gt;.\n\nHier, nehmt das und verschwindet. Ich muss Essen machen.", rewards = "Ihr bekommt:\n\nZäher Brocken BrotZähes Stockfleisch"},
[816] = {title = "Verloren, aber nicht vergessen", objective = "Bringt Misha Tor'kren auf dem Bauernhof nordwestlich von Klingenhügel einen Hinweis auf Krons Schicksal.", description = "<Name>, bitte, könnt Ihr mir helfen? Mein Sohn Kron ist vor Tagen auf die Jagd gegangen und immer noch nicht zurück. Er wollte nach Westen in Richtung des Brachlandes, um dort am Ufer des Südstroms Krokilisken zu jagen. Ich fürchte das Schlimmste.\n\nSo stark wie er ist, hat ihn sein starrköpfiger Stolz doch immer wieder in Schwierigkeiten gebracht. Ich habe ihn gewarnt, dass die Krokilisken mächtig und heimtückisch sind. Er wurde wütend und stürmte davon.\n\nFalls Ihr ihn nicht finden könnt, so bringt mir doch wenigstens einen Hinweis darauf, was aus ihm geworden ist ... und wenn Ihr dazu jedem einzelnen Krokilisken an den Ufern des Südstroms den Bauch aufschlitzen müsst.", progress = "Ich bete, dass Kron zu mir zurückkehrt, aber ich bin mir fast sicher, dass ich weiß, was mit ihm geschehen ist.", completion = "Oh, mein Sohn... mein wunderbarer Sohn.\n\nDie Ungewissheit über das Schicksal meines Sohns hat mich gequält, seit er weggegangen ist. Da ich jetzt weiß, was mit ihm geschehen ist, kann ich vielleicht endlich beginnen zu trauern.\n\nDanke, &lt;Name&gt;. Bitte, nehmt dies hier. Ich wollte es Kron bei seiner erfolgreichen Rückkehr schenken. Ich weiß jetzt, dass er tot ist, und kann es nicht ertragen, es zu sehen.", rewards = "Ihr bekommt:\n\nHandgenähter Umhang"},
[817] = {title = "Praktische Beute", objective = "Bringt Vel'rin Fang in Sen'jin 4 Durotar-Tigerfelle.", description = "Viele der Bälge, die wir benutzen, stammen von den Durotar-Tigern, <Name>. Decken, Rüstungen, Zelte: Es gibt viele Gründe, warum wir Jagd auf die Wildtiere machen, und ebenso viele Gründe, warum wir sie leben lassen.\n\nDie Zeit ist gekommen, dass wir den Bestand dezimieren. Wir werden immer mehr, und unser Bedarf übersteigt bald unsere Bestände. Ich brauche mehr Bälge, wenn ich geeignete Dinge für unser Volk anfertigen möchte.\n\nBringt mir 4 Durotar-Tigerfelle, dann werde ich Euch belohnen. Ihr findet sie auf den Inseln südlich von hier.", progress = "Ich erinnere mich noch an meine erste Tigerjagd, <Name>. Ich hatte mich für die größte der Echoinseln entschieden, um dort zu jagen, und ich saß fast den ganzen Tag lang mucksmäuschenstill im Schatten der Bäume... beobachtete... wartete.\n\nMeine Muskeln waren gespannt und ich war bereit zuzuschlagen. Es war einer meiner größten Triumphe, als der Tiger endlich den Köder nahm.", completion = "Ich freue mich, &lt;Name&gt;! Dank Eurer Hilfe wird unser Volk geschützt sein und in der kalten Jahreszeit nicht frieren müssen.\n\nDanke.", rewards = "Ihr bekommt:\n\n"},
[818] = {title = "Ein geistvolles Getränk", objective = "Bringt Meister Vornal in Sen'jin 4 intakte Makruraaugen und 8 Phiolen Kriechersekret.", description = "Meine Augen sind zwar nicht mehr so scharf, aber ich kann immer noch gut genug sehen. Immer öfter muss ich mich auf meine Alchimie-Fertigkeiten verlassen, um mir bei Dingen, die mir früher leicht fielen, nun mit Magie zu helfen. Ich weigere mich jedoch, einen Lehrling einzustellen - bislang ist mir noch kein Troll oder Orc begegnet, der sich als würdig genug erwiesen hätte.\n\nSeid Ihr dessen würdig? Ja, natürlich seid Ihr das... natürlich glaubt Ihr, dass Ihr es seid.\n\nIch brauche ein paar Dinge. Würdet Ihr sie für mich besorgen?\n\nIch brauche intakte Makruraaugen und Phiolen mit Kriechersekret. Ihr findet das überall in Durotar, wo es Makruras oder Kriecher gibt. Wir sehen uns bald wieder.", progress = "Zeit ist die wahre Prüfung Eurer Kraft und Eures Willens. Verliert Ihr die Geduld oder gebt der Schwäche nach, dann zeigt sich Euer wahres Ich.", completion = "Gut gemacht, junger Freund... wirklich sehr gut.", rewards = "Ihr bekommt:\n\nEcht klebriger Leim"},
[819] = {title = "Chens leeres Fässchen", objective = "Sucht jemanden, der etwas über Chens leeres Fässchen weiß.", description = "Auf einem kleinen Schild an einem Ende des Fässchens steht:\n\n\"Chen Stormstout -\n\nMöge es Euren Geist erheben und Euch Mut machen.\"", progress = "Ja?", completion = "Da brat mir doch einer...\n\nDas war eines von Chen Stormstouts Fässchen. Er reiste vor langer Zeit an Rexxars Seite. Ich habe schon seit Ewigkeiten nichts mehr von ihm gesehen oder gehört. Danke, dass Ihr es mir gebracht habt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[821] = {title = "Chens leeres Fässchen", objective = "Bringt Braumeister Drohn in Ratchet 5 Savannenlöwenhauer, 5 Ebenenschreiternieren und 1 Donnerechsenhorn.", description = "Möchtet Ihr eine Kostprobe von Chens Namensvetter? Ahh, das Stormstout ist ein gehaltvolles Gebräu. Chen gab das Rezept an meinen Mentor weiter und mein Mentor gab es mir. Ich möchte, dass Ihr mir ein paar Dinge besorgt, aber eins möchte ich Euch sagen: Der Kick ist es wert.\n\nBringt mir 5 Savannenlöwenhauer von beliebigen Savannenlöwen, 5 Ebenenschreiternieren von beliebigen Ebenenschreitern und 1 Donnerechsenhorn von einer Sturmschnauze. Das sollte bestens funktionieren.\n\nIhr findet diese Zutaten überall im Brachland.", progress = "Wie läuft Eure Suche?", completion = "Haha... Ich hätte nie gedacht, dass ich noch mal etwas von diesem Zeug brauen würde.\n\nIhr habt nostalgische Gefühle in mir geweckt, &lt;Name&gt;. Erinnert mich irgendwie an das letzte Mal, als ich Trogggebräu gebraut habe. Danke. Die Erinnerungen wärmen mich innerlich.", rewards = "Ihr bekommt:\n\nStormstout"},
[822] = {title = "Chens leeres Fässchen", objective = "Bringt Braumeister Drohn in Ratchet 5 Blitzschlagdrüsen, 1 Donnerfalkenspeicheldrüse und 1 Kodoleber.", description = "Gutes Zeug, dieses Stormstout, was?\n\nIch habe noch ein Rezept, das ich von Chen gelernt habe. Hättet Ihr Interesse? Die Herstellung dauert nicht lange und es könnte Euch nützlich sein, wenn Ihr Eure Abenteuer fortsetzen wollt.\n\nBringt mir 5 Blitzschlagdrüsen einer beliebigen Sturmechse, 1 Donnerfalkenspeicheldrüse von großen Donnerfalken und eine Kodoleber einer beliebigen Kodoart des Brachlandes.\n\nWie ich sagte, das Zeug hat es in sich; das ist das Troggbräu, das ich kürzlich erwähnte.", progress = "Strengt Ihr Euch bei der Suche der Zutaten auch richtig an, <Name>?", completion = "Haha! Ich wusste, dass Ihr diesem Gebräu nicht widerstehen könntet. Kommt wieder, wenn Ihr noch etwas mehr davon möchtet, &lt;Name&gt;. Bringt mir dann noch etwas von den Zutaten, die ich Euch holen ließ.", rewards = "Ihr bekommt:\n\nTrogggebräu"},
[823] = {title = "Bericht an Orgnil", objective = "Sprecht mit Orgnil Soulscar in Klingenhügel.", description = "Auch wir in Sen'jin sind nicht ohne eigene Probleme und wir danken Euch für Eure Hilfe. Aber die Neuigkeiten, die Ihr über die Burning Blade bringt, können Probleme für jedermann bedeuten.\n\nIn Klingenhügel ist ein Orc stationiert, Orgnil Soulscar, der Durotar vor solch Bösem wie den Burning Blade bewacht! Geht zu Orgnil und berichtet ihm von unserer Not sowie von Euren Neuigkeiten über das Tal der Prüfungen. Er wird diese Dinge wissen wollen.\n\nKlingenhügel liegt im Norden.", progress = nil, completion = "Ja? Ihr habt etwas zu berichten? Nun dann, heraus damit!", rewards = "Ihr bekommt:\n\n"},
[824] = {title = "Je'neu vom Irdenen Ring", objective = "Bringt die beschmutzte Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale.", description = "Der Irdene Ring ist eine schamanistische Gruppe, die sich dem Studium und dem Erhalt der Elemente widmet. Sie hat bereits mehr über verrückte alte Götter und uralte Legenden und Lehren vergessen, als die meisten Gelehrten jemals in Erfahrung bringen werden.\n\nZu Eurem Glück kenne ich jemanden hier in Ashenvale, der Mitglied des Irdenen Rings ist. Geht hinüber zum Zoram'gar-Außenposten an der Küste des Zoramstrandes; zeigt Je'neu Sancrea, was Ihr gefunden habt. Wenn überhaupt jemand die Bedeutung dieser Kugel herausfinden kann, dann er.", progress = "Ah, hallo auch. Ich verbringe eine Menge Zeit damit, das Wasser - eigentlich alle Elemente - so intensiv zu studieren, dass ich manchmal nicht einmal die Leute um mich herum wahrnehme.\n\nKann ich Euch irgendwie helfen?", completion = "Diese Kugel... ist sehr beunruhigend. Viele der mächtigeren Elementare beziehen ihre Kraft und Energie aus solchen Gegenständen. Einen davon quasi intakt zu finden, ist eine Sache. Ihn dermaßen besudelt vorzufinden, eine ganz andere.\n\nIch werde dafür Sorge tragen, dass diese Kugel vom Irdenen Ring gründlich untersucht wird. Vielleicht können wir dieser Verderbnis der Elemente ein Ende bereiten. Bitte, nehmt dies zum Tausch dafür, dass Ihr die Aufmerksamkeit des Irdenen Rings auf diese Kugel gelenkt habt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDeftkin-GürtelSchild des MoornebelsWeiches Weidencape\n\nIhr bekommt außerdem:\n\n"},
[825] = {title = "Aus den Wrackteilen geborgen...", objective = "Gar'Thok von Klingenhügel möchte, dass Ihr 3 Gnomen-Werkzeuge aus den Wrackteilen vor der Küste holt.", description = "Einer meiner aufmerksamsten Späher hat mir Kunde gebracht, dass die Trümmer von Proudmoores Flotte immer noch an der Küste Durotars liegen, gleich östlich von Burg Tiragarde.\n\nEs ist kein Geheimnis, dass die Menschen, die sich mit diesen elenden kleinen, als Gnome bekannte Kreaturen verbündet haben, über reichliches Wissen auf dem Gebiet der Mechanik verfügen. Wir müssen so viel wie möglich über unsere potenziellen Feinde in Erfahrung bringen. Dann kann unser Volk von diesem neuen Wissen profitieren.\n\nSchwimmt durch die Wrackteile, <Name>, und bringt mir die Werkzeuge der Allianz.", progress = "Sobald wir wissen, wie die Menschen ihre seltsamen Maschinen bedienen, haben wir eine bessere Chance, sie in zukünftigen Schlachten besiegen zu können.\n\nMit unserem neu gewonnenen Wissen wächst die Kraft der Horde.", completion = "Eure Bergungsmission war ein Erfolg, &lt;Klasse&gt;. Ich werde dafür sorgen, dass diese Werkzeuge mit der nächsten Karawane nach Orgrimmar geschickt werden.\n\nSehr gut gemacht.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchmutzstarrende StiefelSandläuferhandgelenksschützerBreiter Metallgurt\n\nIhr bekommt außerdem:\n\n"},
[826] = {title = "Zalazane", objective = "Besiegt Zalazane.\n\nTötet 8 Voodootrolle und 8 verhexte Trolle.\n\nBringt Gadrin Zalazanes Kopf.", description = "Der Hexendoktor Zalazane lebt auf den Echoinseln im Osten. Das sind die Inseln, die wir einst Heimat nannten.\n\nVon dort aus entsendet er seine Trolle zum Festland, wo sie unser Volk verhexen und immer mehr von uns in ihren Bann ziehen.\n\nEr muss aufgehalten werden.\n\nBesiegt Zalazane und seine Diener - ehemalige Trolle der Darkspear, die jetzt nicht mehr zu uns gehören. Bringt mir seinen Kopf, dann weiß ich, dass seine Schreckensherrschaft vorbei ist.", progress = "Ist Zalazane besiegt, <Name>?", completion = "Jetzt, da Zalazane beseitigt ist, kann unser Stamm wieder ruhig schlafen.\n\nIch danke Euch, &lt;Name&gt;. Der Darkspearstamm schuldet Euch viel. Falls Ihr unter einem Gebrechen leidet, besucht meinen Assistenten Bom'bay, da hinter mir. Sein Voodoo ist stark...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLeichtgewichtige StiefelVerhüllter Handschutz\n\nIhr bekommt außerdem:\n\n"},
[827] = {title = "Die Knochenhöhle", objective = "Besorgt von den Kultisten an der Knochenhöhle ein paar Senghalsbänder.\n\nBringt sie Margoz in seinem Lager.", description = "<Name>. Die Burning Blade haben die Knochenhöhle östlich von Orgrimmar besetzt. Sie führen in dieser Höhle schlimme Rituale durch und fügen sich durch Senghalsbänder selbst Brandwunden zu.\n\nIch glaube, indem sie diese Halsbänder tragen, bringen die Kultisten sich im Einklang mit dämonischen Mächten. Um das zu bestätigen, benötige ich jedoch ein paar dieser Halsbänder, um sie zu studieren.\n\nGeht zur Knochenhöhle und besorgt ein paar Senghalsbänder von den Kultisten, die Ihr dort findet. Bringt sie mir, dann werde ich ihre Geheimnisse enthüllen.", progress = "Wart Ihr schon in der Knochenhöhle, <Name>? Habt Ihr die Senghalsbänder?", completion = "Gut. In diesen Senghalsbändern verbirgt sich das Geheimnis der Burning Blade. Und ich werde dieses Geheimnis lüften...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGezackter DolchStandhaftes BastardschwertStechender Streitkolben\n\nIhr bekommt außerdem:\n\n"},
[828] = {title = "Margoz", objective = "Sprecht mit Margoz.", description = "Margoz, einer unserer Schamanen, weiß mehr über die Verderbnis der Burning Blade. Er sprach von einer Höhle namens Knochenhöhle in den Bergen - gleich vor den Toren Orgrimmars! - dort soll sich eine große Gruppe von Kultisten der Burning Blade eingenistet haben.\n\nBevor Ihr jedoch zur Knochenhöhle geht, sprecht mit Margoz. Er ist weise und sein Rat wird geschätzt.\n\nEr lagert im Nordosten zwischen der Küste und der Staubwindklamm.\n\nFolgt seinem Rat, aber was immer Margoz auch sagt, <Name>, ich möchte, dass Ihr diese Kultisten vernichtet!", progress = nil, completion = "Willkommen, &lt;Name&gt;. Man hat mir Euer Kommen angekündigt und mir von Euren Unternehmungen in Durotar berichtet.\n\nIhr seid ein &lt;Klasse&gt; mit stetig wachsenden Fertigkeiten und Ansehen.\n\nHaltet Euch auf dem reinen Pfad, dann wird Eure Zukunft wahrlich großartig sein.", rewards = "Ihr bekommt:\n\n"},
[829] = {title = "Neeru Fireblade", objective = "Bringt Neeru Fireblade in Orgrimmar ein Senghalsband-Muster.", description = "Die Senghalsbänder, die Ihr mir brachtet, sind mächtige, dämonische Werkzeuge. Ihre Herkunft zu bestimmen liegt jedoch leider außerhalb meiner Künste als Schamane. Wir werden einen Hexenmeister bitten müssen, sie zu studieren.\n\nBringt ein Senghalsband zu Neeru Fireblade. Er ist zwar ein talentierter Hexenmeister, doch nutzt er seine Mächte nur, um Dämonen zu bekämpfen, und er behauptet, dass seine Forschungen auf dem Gebiet des Okkultismus gutartiger Natur sind. Ob es stimmt oder nicht, wir brauchen dennoch seine Hilfe gegen den Dämonenkult in Durotar.\n\nIhr findet Neeru in Orgrimmar in der Kluft der Schatten.", progress = "Meine ergebensten Grüße, <Klasse>. Womit kann ich meinem Bruder heute behilflich sein?", completion = "Ah, und wo habt Ihr das her? Der gute Margoz in Klingenhügel hat Euch zu mir geschickt, richtig?\n\nNun, dann lasst mich mal einen Blick darauf werfen...", rewards = "Ihr bekommt:\n\n"},
[830] = {title = "Die Befehle des Admirals", objective = "Bringt Gar'Thok in Klingenhügel Admiral Proudmoores Befehle.", description = "Ihr öffnet den alten, verwitterten Umschlag und findet darin ein offiziell aussehendes Dokument. Ihr erkennt das Siegel Admiral Proudmoores.\n\nEs sieht wichtig aus. Vielleicht wäre Gar'Thok, Kommandant von Klingenhügel, an diesen Informationen interessiert.", progress = "Ihr seht besorgt aus, <Klasse>. Was habt Ihr da?", completion = "Das sieht gar nicht gut aus. Das war sehr klug von Euch, mir diese Informationen zu bringen.", rewards = "Ihr bekommt:\n\n"},
[831] = {title = "Die Befehle des Admirals", objective = "Bringt Nazgrel in Thralls Kammer in Orgrimmar Admiral Proudmoores Befehle.", description = "Menschen kann man nicht trauen. Wir haben immer mit wachsamen Augen an ihrer Seite gekämpft, weil wir wussten, dass sie uns eines Tages verraten würden.\n\nLeider war Admiral Proudmoores Tod nicht genug, um sein Vermächtnis des Betrugs aufzuhalten. Der Menschenabschaum hatte vor seinem Ableben alles gut durchgeplant.\n\nSeine Herrschaft würde, wie es scheint, nicht einmal mit Benedict enden. Wer weiß, wann die nächste Welle von Proudmoores Männern an unseren Küsten landen wird.\n\nWir müssen diese Befehle sofort zu Nazgrel in Orgrimmar bringen! Man findet ihn in Thralls Kammer.", progress = "Seht Ihr nicht, dass ich beschäftigt bin? Ich hoffe, es ist wichtig...", completion = "Unzählige Male habe ich den Kriegshäuptling gedrängt, den Menschen nicht zu trauen, aber persönlicher Stolz steht jetzt hier nicht zur Debatte.\n\nIhr habt der Horde ehrenvoll gedient, &lt;Klasse&gt;.\n\nUnd jetzt entschuldigt mich bitte, ich muss mich über diese Dinge umgehend mit Thrall beraten ...", rewards = "Ihr bekommt:\n\n"},
[832] = {title = "Brennende Schatten", objective = "Bringt Neeru Fireblade dieses Auge.", description = "<Die Stimme aus dem Anhänger erreicht direkt Euren Verstand.>\n\nGazz'uz?\n\nGazz'uz... Bericht!\n\nMan hat von Eurer Entdeckung in der Knochenhöhle gehört. Ihr müsst Euch auf einen Angriff vorbereiten!\n\nGazz'uz, ich befehle Euch, mir zu antworten! Sagt etwas, sonst werde ich dafür sorgen, dass Neeru Fireblade von Eurer Anwesenheit erfährt, dann wird es Euch schlecht ergehen.\n\nVersucht nicht, Eure Fertigkeiten mit denen Neerus zu messen...\n\n... Gazz'uz, seid Ihr da...?", progress = "Ihr habt etwas höchst Wichtiges zu berichten. Das sehe ich an Euren Augen.", completion = "&lt;Untersucht das Auge des brennenden Schattens.&gt;\n\nFaszinierend. Die Stimme, die Ihr hörtet, nannte meinen Namen? Ich bin dafür bekannt, Feinden unseres Kriegshäuptlings nachzustellen, aber... es ist doch seltsam, dass man gerade mich so hervorhebt. Noch seltsamer, dass die Kultisten der Burning Blade, von denen Ihr diesen Anhänger habt, einen Namen wissen, der meinem so ähnlich ist.\n\nIch muss diesen Anhänger studieren. Ich muss ihn studieren und darüber nachdenken, was diese Nachricht bedeuten könnte.\n\nVielen Dank, dass Ihr ihn mir gebracht habt, &lt;Name&gt;. Ihr habt unserem Volk einen großen Dienst erwiesen.", rewards = "Ihr bekommt:\n\n"},
[833] = {title = "Eine heilige Bestattung", objective = "Der Hüter des Wissens Raintotem möchte, dass Ihr bei den Teufelsfelsen 8 Eindringlinge der Borstennacken tötet.", description = "Nur die tapfersten Tauren werden bei den Teufelsfelsen, unserer heiligen Begräbnisstätte, bestattet. Es ist eine Ehre, die jenen großen Kriegern zuteil wird, die dazu beitrugen, Thunder Bluff zu gründen und zu verteidigen, und jenen, die ihr Leben für das Wohl ihres Stammes und ihrer Häuptlinge gegeben haben.\n\nNun sieht es jedoch so aus, als wäre es einer üblen Bedrohung gelungen, in unser heiliges Land einzudringen. Eine Gruppe Borstennacken-Eindringlinge verheert das Grabmal und ich bin zu alt und gebrechlich, um sie selbst zu vertreiben.\n\nSie müssen mit Gewalt von dort verjagt werden, <Name>.", progress = "Die Eindringlinge der Borstennacken müssen von unserer heiligen Begräbnisstätte vertrieben werden, <Name>.", completion = "Gut gemacht. Ihr habt diesen elenden Borstennacken eine deutliche Warnung erteilt. Sie werden es sich zweimal überlegen, bevor sie erneut versuchen, sich an diesem heiligen Ort einzumischen.", rewards = "Ihr bekommt:\n\n"},
[834] = {title = "Wind in der Wüste", objective = "Holt 5 Säcke Vorräte und bringt sie Rezlak in der Nähe von Orgrimmar.", description = "Ich bin Rezlak, einer von Gazlowes Jungs. Boss hat mich geschickt, den Orcs hier in Durotar unter die Arme zu greifen. Soweit läuft alles klar, abgesehen von den Karawanen. Ich schaff's einfach nicht, sie zu sichern! Das erschwert mir meinen Job ganz schön, wisst Ihr?\n\nDie letzte Lieferung, meine Güte, die hatten garantiert, dass sie durchkommt! Aber sie wurde von den Staubschwingenharpyien von... wo war das noch... in der Klingenschlucht geklaut.\n\nIch muss dieses Zeug zurückhaben, sonst kriege ich hier nie mehr was zu tun! Folgt dem großen Canyon nach Süden, dort findet Ihr eine Klamm direkt westlich und östlich der Wände.", progress = "Ich bin gut, in dem was ich tue, versteht mich jetzt nicht falsch, aber das ist lächerlich! Was soll ich tun, im Sandkasten spielen?", completion = "He, ist das nicht ein Ding? Ihr habt unsere Vorräte zurückgeholt. Is’ ja doll. Jetzt kann ich mich wieder an die Arbeit machen, sobald ich ein paar Leute gefunden habe, die diese Säcke für mich schleppen.", rewards = "Ihr bekommt:\n\n"},
[835] = {title = "Sicherung der Linien", objective = "Tötet für Rezlak in der Nähe der Staubwindklamm 12 Wilde der Staubschwingen und 8 Sturmhexen der Staubschwingen.", description = "Gazlowe sagte mal zu mir: \"Rezlak. Eines musst du im Leben wissen: Wenn du was richtig gemacht haben willst, dann tu's selbst.\"\n\nIch kann es mir nicht leisten, all unsere Karawanen zu verlieren, also muss ich die Sache selbst in die Hand nehmen. Die Staubwindklamm liegt hinter dem Ostteil der Klingenschlucht. Wenn wir alle Harpyien dort töten, ist die Route wieder sicher.\n\nNatürlich gab's da noch was, das Gazlowe mir beigebracht hat, und das ist: \"Wenn die Kohle stimmt, kriegt man alles.\" Also, werdet Ihr mir helfen, <Name>?", progress = "Das traut man einem Typen wie meinem Boss Gazlowe gar nicht zu, aber er scheint immer zu wissen, wie der Hase läuft. \"Keine Angst vor dem großen Schritt\", sagte er.\n\nDie Harpyien werden uns weiterhin belästigen und die Karawanen angreifen, wenn wir nichts unternehmen, oder?", completion = "Ich glaube, ich kann jetzt wieder ruhiger schlafen, da ich weiß, dass die Harpyien unsere Versorgungskarawanen nicht mehr angreifen. Wurde auch langsam Zeit. Wie ich hörte, kommen mit der nächsten Lieferung ein paar nette Spielsachen für mich!\n\nIhr seid ziemlich gut, in dem was Ihr tut, &lt;Name&gt;, solltet mal meinen Boss in Ratchet aufsuchen. Ich wette, er hat ein bisschen Arbeit für Euch.\n\nOh, und macht Euch keine Sorgen, ich vergess nicht, Euch für Eure Dienste zu bezahlen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHarpyienflügelstutzerHickory-KurzbogenVerunstalteter Holzstab\n\nIhr bekommt außerdem:\n\n"},
[836] = {title = "Rettet OOX-09/HL!", objective = "Eskortiert OOX-09/HL zur Küste jenseits der Aussichtsklippen und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay.", description = "Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms:\n\n\"Ich muss OOX-09/HL an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann. Er hat eine eingebaute Tarnvorrichtung, aber ich brauche etwas Zeit, um sie von hier aus wieder funktionstüchtig zu machen. Eskortiert den Roboter von seinem derzeitigen Standort... hmmm, ja, zur Küste jenseits der Aussichtsklippen! Das sollte der perfekte Ort für mein Vorhaben sein, und bis Ihr dort seid, sollte ich auch alles vorbereitet haben und online gehen können.\"\n\n\"Eskortiert ihn sicher bis zur Küste und kommt dann zu mir nach Booty Bay! Oglethorpe Obnoticus - Ende!\"", progress = nil, completion = "Ach, IHR habt so heldenhaft OOX-09/HL gerettet! Ich kann Euch gar nicht sagen, wie dankbar ich für Eure Hilfe bin! In meine Serie von Leitrobotern muss noch viel Entwicklungsaufwand gesteckt werden, aber Eure Bergung des Roboters hat mir zahllose Stunden zusätzlicher Schraubarbeit gespart, ganz zu schweigen von dem vielen Gold, das ich spare, weil ich ihn nicht neu bauen muss!\n\nBitte sucht Euch einen von diesen Gegenständen hier aus. Ich danke Euch nochmals für Eure großzügige Hilfe, &lt;Name&gt;, meine Roboter und ich stehen in Eurer Schuld!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGnomische Erfinder-StiefelGnomisches Wasser-Absenkungsgerät\n\nIhr bekommt außerdem:\n\n"},
[837] = {title = "Übergriff", objective = "Tötet für Gar'Thok in Klingenhügel 4 Stacheleber der Grimmhauer, 4 Späher der Grimmhauer, 4 Staubläufer der Grimmhauer und 4 Schlachtwachen der Grimmhauer.", description = "Als wir hier ankamen, war ein Großteil des Landes im Besitz der Grimmhauerstacheleber, die sich als ein ziemlicher Dorn im Auge erwiesen. Durch unsere Anstrengungen konnten wir einen großen Teil von ihnen vertreiben, aber es gibt doch noch welche, die sich in einigen Gebieten verschanzt haben.\n\nDas geht jetzt jedoch schon viel zu lange so. Zu unserer eigenen Sicherheit dürfen wir nicht zulassen, dass sich die Grimmhauer in unserem Land festsetzen. Ihre Lager befinden sich westlich von hier. Sucht nach dem Dornengestrüpp, dann findet Ihr sie. Heute vertreiben wir sie aus Durotar, morgen vielleicht schon aus Kalimdor.", progress = "Sie sind zwar einiger Intelligenz und Organisation fähig, doch finde ich es immer wieder erstaunlich, dass die Stacheleber so große Territorien in Kalimdor erobern und halten konnten. Vielleicht sind sie doch gerissenere Feinde als wir ihnen zutrauen...", completion = "Ich werde die Kunde verbreiten, dass die Stacheleber aus ihren Unterschlüpfen vertrieben wurden und dass ihre Gebäude in Brand zu setzen sind. Die Entfernung der Grimmhauer aus Durotar bringt uns dem Ziel näher, die Grenzen unseres neuen Heimatlandes vollständig zu sichern.", rewards = "Ihr bekommt:\n\n"},
[838] = {title = "Scholomance", objective = "Sprecht mit Apotheker Dithers am Bollwerk, Westliche Pestländer.", description = "Auf der Insel Caer Darrow liegt die Scholomance - eine Schule, die als Festung für die Geißel dient. Unser Feind haust dort, wo er sicher Forschungen betreiben kann, die seine Macht stärken. Eine Tür versperrt den Weg, und ganz gleich was wir versuchen, der Zutritt ist nur mit dem richtigen Schlüssel möglich.\n\nApotheker Dithers weiß viel über die Scholomance und hat eine Idee, wie ein Schlüssel zu erlangen ist. Ihr habt mir Euren Wert als jemand bewiesen, der knifflige Dinge erledigen kann; ich vertraue Euch nun diese Aufgabe an. Sprecht mit ihm über diese Angelegenheit.", progress = nil, completion = "Ja, &lt;Klasse&gt;, der Hochexekutor erwähnte, dass Ihr möglicherweise der seid, der mit dem Schlüssel betraut werden kann. Ich habe einen Großteil meiner Studien der Scholomance gewidmet und glaube, dass ich eine Möglichkeit kenne, wie Ihr einen erlangen könnt, der Euch nach Belieben durch die Vordertür bringt.\n\nDiese Aufgabe wird nicht einfach sein, aber das sind solche Aufgaben selten. Ihr seht tatsächlich wie jemand aus, dem das nicht fremd ist.", rewards = "Ihr bekommt:\n\n"},
[840] = {title = "Freiwilliger der Horde", objective = "Folgt der westlichen Straße aus Klingenhügel ins Brachland und über die Brücke.\n\nMacht bei dem Außenposten der Orcs auf der anderen Seite Halt.\n\nGebt Kargal Battlescar im Brachlandaußenposten Euren Anwerbungsbrief.", description = "Hmmm, Ihr seht mir recht stark aus.\n\nHört mal, mein guter Freund Kargal braucht ein paar neue Rekruten für den Dienst im Brachland. Ich weiß, dass Ihr immer nur das Richtige für die Horde tun wollt. Das ist jetzt Eure Chance.\n\nBringt Kargal diesen Anwerbungsbrief und seht, ob er ihn unterzeichnet.", progress = "Was wollt Ihr, Jungspund? Wenn Ihr nicht wegen einer Anwerbung hier seid, habe ich keine Zeit für Euch.", completion = "Oh, Takrin schickt Euch also? Er ist ein ausgezeichneter Späher und ich weiß nicht, was ich ohne ihn anfangen sollte.\n\nIch unterzeichne Euren Anwerbungsbrief, aber was wir wirklich brauchen, ist jemand in Crossroads.", rewards = "Ihr bekommt:\n\n"},
[841] = {title = "Eine weitere Kraftquelle?", objective = "Bringt Chefingenieur Bilgewhizzle in Gadgetzan 10 Wasserbeutel eines Wüstenläufers im Austausch gegen eine weitere Kraftquelle.", description = "Ich stelle mal eine Vermutung an - Ihr habt, welch weltbeendende, ruchlose Tat Ihr auch unternommen habt, diese Tat nicht rechtzeitig beendet. Nein, wartet, noch besser... Ihr habt die Sache in den Sand gesetzt! Nun, was auch immer der Grund sein mag, ich verfüge über eine weitere Kraftquelle, die ich Euch verkaufen werde. Dieses Mal wird sie Euch aber zehn, JAWOHL ZEHN Wasserbeutel eines Wüstenläufers kosten!\n\nDie Zeiten hier sind schwer, <Name>, und Kraftquellen wachsen nicht auf Bäumen! Hmm, aber was wäre wohl, wenn sie es täten... Vielleicht könnten wir einen Kraftquellenbaum MACHEN...", progress = "Also, habt Ihr die zehn Wasserbeutel?", completion = "Sehr gut, hier ist eine weitere Kraftquelle. Ich empfehle Euch, sie diesmal weise zu nutzen, falls Ihr nicht erpicht darauf seid, weitere zehn Wasserbeutel für eine weitere Kraftquelle auszugeben.", rewards = "Ihr bekommt:\n\nKraftquelle, Modell 4711-FTZ"},
[842] = {title = "Crossroads-Wehrpflicht", objective = "Folgt der Straße von Kargals fernem Farwatch-Außenposten nach Westen.\n\nWendet Euch bei der Einmündung nach links und folgt dann der Straße in südliche Richtung. \n\nSucht Sergra Darkthorn an der Kreuzung zweier Straßen in Crossroads auf.", description = "Bringt diesen unterzeichneten Anwerbungsbrief nach Crossroads.\n\nSergra Darkthorn, verflucht sei sie, hat dort das Kommando. Sie ist eine grässliche Schamanin, die Euch erst schwindelig redet, bevor Sie Euch etwas Nützliches tun lässt. Thrall ist davon überzeugt, dass sie etwas ganz Besonderes ist, aber ich bin mir da nicht so sicher.\n\nMacht Euch selbst ein Bild davon, Jungspund ...", progress = "Nanu, nanu, nanu, was haben wir denn hier? Hat Kargal mich nun doch endlich für würdig befunden, mir einen neuen Rekruten zu schicken?", completion = "Na gut, &lt;Name&gt;. Ihr wollt also Euren Unterhalt in der Horde verdienen? Hier gibt es eine Menge zu tun, also hört gut zu und tut, was man Euch sagt.\n\nIhr braucht mich gar nicht so ansehen, ich dulde keine Unverschämtheiten. Thrall selbst hat verkündet, dass wir Frauen der Horde Euch Männern gleichgestellt sind. Wenn ihr mir auch nur im geringsten respektlos gegenübertretet, werdet Ihr wahre Schmerzen kennen lernen.", rewards = "Ihr bekommt:\n\n"},
[843] = {title = "Ganns Rekultivierung", objective = "Gann Stonespire möchte, dass Ihr 15 Ausgräber von Bael'dun und 5 Großknechte von Bael'dun tötet.\n\nBringt Gann Stonespire dann Khazgorms Tagebuch.", description = "In Einsamkeit wandere ich auf diesen Straßen.\n\nDie Zwerge Bael Modans haben keinen Respekt vor meinem Land. Entsetzliche Schläge reißen tiefe Wunden in den Boden und brüllende Maschinen zerfetzen die Hügel. Land, das meinem Stamm einst als Heimat und Versorger diente, ist jetzt von zerstörerischen Zwergen durchfurcht.\n\nAlle Versuche, zu einer diplomatischen Einigung zu kommen, sind fehlgeschlagen. Jetzt ist die Zeit für entschlossenes Handeln gekommen.\n\nVertreibt die Zwerge mit Gewalt von der Bael Modan-Ausgrabung und bringt mir das Tagebuch ihres Anführers, Ausgrabungsleiter Khazgorm.", progress = "Viele unschuldige Tauren verloren ihr Leben oder wurden zwangsweise aus ihren Vorfahren-Geburtsorten vertrieben, als die Zwerge von Bael Modan kamen. Mein Land muss zurückerobert werden!", completion = "Khazgorm hat das Schicksal ereilt, das er verdient. Ich habe keine Schuldgefühle wegen dieses Narren. Er war ein Ungläubiger in diesem Land.\n\nMöge sein Tod allen als Warnung dienen, die unsere Lebensart zu zerstören trachten.\n\nUnd jetzt gebt mir einen Moment Zeit, damit ich das Tagebuch des Zwergs lesen kann...", rewards = "Ihr bekommt:\n\n"},
[844] = {title = "Ebenenschreiter-Bedrohung", objective = "Besorgt 7 Ebenenschreiterschnäbel und bringt sie Sergra Darkthorn in Crossroads.", description = "Eure erste Beute wird einfach sein.\n\nDie Ebenenschreiter im Osten fallen immer wieder über unsere Lebensmittelvorräte her und sind zu einer Plage geworden.\n\nVernichtet die Ebenenschreiter und bringt mir ihre Schnäbel.", progress = "Habt Ihr die Ebenenschreiterschnäbel schon?", completion = "Sehr gut, &lt;Name&gt;. Nachdem die Ebenenschreiter jetzt verschwunden sind, ist es für uns einfacher, unsere Nachschubwege intakt zu halten. Und ich hoffe, Ihr habt einige Tricks dort draußen im Brachland gelernt, denn Eure nächste Beute hat etwas mehr Feuer im Blut als die Ebenenschreiter...", rewards = "Ihr bekommt:\n\n"},
[845] = {title = "Die Zhevras", objective = "Erschlagt Zhevra-Läufer, um für Sergra Darkthorn in Crossroads 4 Zhevra-Hufe zu erhalten.", description = "Die Zhevras sind etwas wilder als die Ebenenschreiter, auch wenn sie nicht die stärksten Wildtiere im Brachland sind. Aber macht Euch keine Sorgen - wir werden Euch bei Gelegenheit gegen größere Beute ausschicken. Vorerst könnt Ihr jedoch noch ein bisschen Übung gebrauchen.\n\nJagt die Zhevras im Norden und Süden und sammelt ihre Hufe. Bringt sie mir, und vielleicht werden wir Euch als Nächstes eine schwierigere Aufgabe stellen.", progress = "Wie viele Zhevras habt Ihr schon erschlagen?", completion = "Nicht schlecht, &lt;Name&gt;. Diese Zhevras haben sehr viel Kraft in ihren Beinen. Ein gezielter Tritt von ihnen kann sogar einen Tauren von den Hufen hauen!\n\nSieht aus, als würdet auch Ihr über ein bisschen Kraft verfügen. Seid Ihr bereit für eine wahre Herausforderung?", rewards = "Ihr bekommt:\n\n"},
[846] = {title = "Ganns Rache", objective = "Gann Stonespire möchte, dass Ihr ihm 6 Phiolen Nitroglyzerin, 6 Teile Holzbrei und 6 Proben Natriumnitrat bringt.", description = "Es ist klar, dass ein Ausgrabungsleiter von Sprengstoff und diesen lärmenden Fahrzeugen abhängig ist, um den Boden aufzureißen. Wir müssen damit rechnen, dass schon bald ein neuer Großknecht die Sache übernimmt.\n\nIch möchte den Zwergen ihre eigene Medizin zu schmecken geben. Wenn wir laut diesen Plänen Nitroglyzerin mit Holzbrei und Natriumnitrat mischen, erhalten wir eine Sprengladung. Es ist bekannt, dass die Scharfschützen, Soldaten und Offiziere in der Burg diese Dinge besitzen.\n\nHolt diese Sachen und bringt sie mir; ich werde daraus eine Sprengladung basteln, die die Zwerge so schnell nicht vergessen werden!", progress = "Wie ich sehe, seid Ihr zurück, <Name>.\n\nKhazgorms Tod mag zwar die Grabungen auf dem Land meiner Vorfahren verzögern, aber der Zerstörung ist damit noch nicht vollständig Einhalt geboten.\n\nDie Burg bei Bael Modan stellt eine ständig wachsende militärische Bedrohung dar. Sie wurde ursprünglich zum Schutz der Grabungsstätte errichtet, ist jetzt aber auch Sitz einer offensiven Streitmacht geworden.\n\nWenn Ihr die Zutaten habt, um die ich gebeten hatte, kann ich eine Ladung herstellen, die diese übereifrigen Zwerge noch einmal über ihre Handlungen hier im Brachland nachdenken lassen wird.", completion = "Wie ich sehe, seid Ihr ziemlich emsig gewesen, &lt;Klasse&gt;.\n\nJetzt werden wir zweifellos bald eine angemessene Überraschung für diese Zwerge parat haben.", rewards = "Ihr bekommt:\n\n"},
[847] = {title = "Arglist des Raptors", objective = "Sprecht mit Tor'gan.", description = "Diese... diese Macht... Ist das die Macht der Schamanen, die Tor'gan mir zeigen wollte? Ich muss sagen, das ist wirklich interessant. Sagt Tor'gan, dass er mich überzeugt hat... jedenfalls für den Augenblick. Ich werde mir anhören, was er zu sagen hat.", progress = nil, completion = "Wenn die Verzauberung nachlässt, werde ich mit Gor'mul sprechen. Vielen Dank, dass Ihr geholfen habt, Gor'mul ins Land der Lebenden zurückzuholen. Ich zweifle nicht daran, dass er Euch ebenso dankbar ist.", rewards = "Ihr bekommt:\n\nRuf des Raptors"},
[848] = {title = "Pilzsporen", objective = "Bringt dem Apotheker Helbrim in Crossroads 4 Pilzsporen.", description = "Die Oasen des Brachlandes verbergen ein Mysterium. In ihren Wassern fließt Lebensenergie, die alle Pflanzen und Wildtiere erquickt, die davon trinken.\n\nErquickt und verändert.\n\nEs gibt einen Pilz, der in der Nähe dieser Oasen wächst. Seine Sporen besitzen Eigenschaften, die wir, die Apotheker Lordaerons, sehr nützlich finden.\n\nBringt mir diese Sporen, dann seid Ihr unserer Dankbarkeit gewiss.", progress = "Habt Ihr die Sporen, <Name>? Ich muss meinem Kollegen in Thunder Bluff ein Gebräu schicken, für das diese Sporen benötigt werden...", completion = "Ah, ja. Das sind wirklich Prachtexemplare. Sehr wirksam.\n\nIch bin ein Verlassener und wir halten unsere Versprechen. Hier ist Eure Belohnung, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[849] = {title = "Ganns Rache", objective = "Zerstört den Flugapparat bei Beal Modan und kehrt dann zu Gann Stonespire zurück.", description = "Wenn wir uns an Khazgorms Pläne halten, sollte es eigentlich kein Problem sein, eine Sprengladung herzustellen.\n\nAh, fertig.\n\nAlso, <Name>, ich möchte Euch mit einer besonderen Aufgabe betrauen. Nehmt diese Dynamitstange und jagt damit den Flugapparat bei Bael Modan in die Luft.\n\nDieser Flugapparat ist nicht nur ein wichtiger Bestandteil der Infrastruktur der Grabungsstätte, sondern auch eine Kriegswaffe. Vor allem ist sie aber ein Symbol der Macht und eine Beleidigung des Andenkens an meinen Stamm.\n\nMacht mich stolz, indem Ihr diese heldenhafte Aufgabe erledigt, dann soll es Euer Schaden nicht sein.", progress = "Wenn der Flugapparat der Zwerge erst zerstört ist, werde ich die süße Genugtuung der Rache schmecken.", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Mögt Ihr in Thunder Bluff als Verteidiger des heiligen Tauren-Landes und Champion des verlorenen Stammes verehrt werden.", rewards = "Ihr bekommt:\n\nTotemikerklanring"},
[850] = {title = "Anführer der Kolkar", objective = "Bringt Regthar Deathgate westlich von Crossroads Baraks Kopf.", description = "Die Zentauren haben die Tauren seit Jahren geplagt. Die Kolkarzentauren des Brachlandes sind seit kurzem zu einer echten Bedrohung geworden. Normalerweise sind sie in diesen Landen eher unorganisiert, aber es haben sich unter ihnen neue Anführer erhoben. Sie sammeln sich.\n\nWir müssen diese Zentaurenanführer vernichten, um unsere Position hier zu bewahren.\n\nBringt mir den Kopf von Barak Kodobann. Er lagert in der Nähe der vergessenen Teiche im Norden.\n\nBesiegt ihn und kehrt dann zu mir zurück.", progress = "Hallo, <Name>. Bringt Ihr mir Baraks Kopf?", completion = "Gut gemacht, &lt;Name&gt;. Die Zentauren sind niedere, brutale Kreaturen, aber ein paar von ihnen verfügen doch über genug Verstand und Vorstellungskraft, um sie zu führen. Und das sind die gefährlichsten.\n\nBarak war ein solcher Zentaur. Nur gut, dass er jetzt tot ist.", rewards = "Ihr bekommt:\n\n"},
[851] = {title = "Verog der Derwisch", objective = "Bringt Regthar Deathgate westlich von Crossroads Verogs Kopf.", description = "Der Zentaur Verog der Derwisch durchwandert das Brachland und wird daher schwer auffindbar sein. Er hat jedoch ein Zentaurenkommandozelt bei der brackigen Oase im Südosten. Vielleicht könnt Ihr ihn zu Euch locken.\n\nReist zur brackigen Oase im Südosten und greift Zentauren in der Nähe des Kommandozeltes an. Es wird gefährlich werden, aber wenn Ihr genug Zentauren tötet, werden sie Alarm schlagen. Und Verog wird kommen.\n\nBringt mir seinen Kopf, dann lege ich ihn neben den von Barak Kodobann.", progress = "Habt Ihr Verog gefunden, <Name>?", completion = "Sehr gut. Ihr müsst diese Zentauren wirklich aufgescheucht haben - unsere Wachen haben in der Nähe der brackigen Oase Aktivitäten bemerkt, vielleicht wart Ihr das ja.\n\nIhr könnt stolz auf Eure Taten sein, &lt;Name&gt;. In Euch steckt viel Mut.", rewards = "Ihr bekommt:\n\n"},
[852] = {title = "Hezrul Blutmal", objective = "Bringt Regthar Deathgate westlich von Crossroads Hezruls Kopf.", description = "Hezrul Blutmal ist der Anführer der Kolkarzentauren im Brachland. Er ist wild, brutal und schlau. Könnte man ihn besiegen, würde das die Kolkars spalten und zerschlagen und die Bedrohung durch sie enorm entschärfen.\n\nAlso tötet ihn. Und bringt mir genau wie zuvor bei Barak und Verog Hezruls Kopf.\n\nEr führt sein Volk von der blühenden Oase im Süden aus an.", progress = "Ist Hezrul besiegt, <Name>?", completion = "Ich bewundere Euch, &lt;Name&gt;. Diese Zentauren sind undiszipliniert und können ihre Wut nicht so konzentrieren wie die Orcs, aber sie sind dennoch unerbittlich wild. Ihr habt Euren Wagemut bewiesen, indem Ihr sie besiegtet.", rewards = "Ihr bekommt:\n\nKopfgeldjägerring"},
[853] = {title = "Apothekerin Zamah", objective = "Bringt der Apothekerin Zamah in Thunder Bluff die weiterverarbeiteten Sporen, bevor die Zeit abgelaufen ist.", description = "Ich habe die Sporen, die Ihr mir gabt, zu einer Emulsion verarbeitet. Die muss ich jetzt meiner Kollegin schicken, der Apothekerin Zamah. Wenn Ihr sie ihr bringen könntet, würde sie Euch bestimmt etwas aus ihrem Vorrat alchimistischer Waren anbieten.\n\nSie lebt bei den Teichen der Visionen in einer Höhle unter den Schamanen von Thunder Bluff. Der Pfad zu dieser Höhle ist gut versteckt, aber Ihr könnt ihn am Steilhang der Anhöhe der Geister finden.\n\nBeeilt Euch. Die Emulsion verliert nach einer Weile ihre Wirksamkeit und muss vorher luftdicht verschlossen und weiterverarbeitet sein.", progress = "Habt Ihr etwas von Apotheker Helbrim für mich?", completion = "Ah, die Sporen aus dem Brachland, die Helbrim sammeln wollte. Er hat Euch also gebeten, sie auszuliefern? Gut.\n\nUnd da die Emulsion immer noch wirkungsvoll ist, habt Ihr offenbar keine Zeit verloren, sie mir zu bringen. Gut gemacht, &lt;Klasse&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nElixier der schwachen SeelenstärkeElixier der schwachen BeweglichkeitSchwacher VerjüngungstrankHurtigkeitstrank\n\nIhr bekommt außerdem:\n\nKesselrührer"},
[854] = {title = "Reise nach Crossroads", objective = "Sprecht mit Thork in Crossroads im Brachland.", description = "Ich habe Eure Ankunft vorausgesehen, junger <Klasse>. Aber vielleicht seid Ihr ja gar nicht mehr so jung.\n\nIch glaube, dass es an der Zeit ist, dass Ihr Euch tiefer in dieses Land vorwagt. Ich fühle, dass Ihr zu Größerem berufen seid.\n\nCrossroads wartet auf Euch, denn die Orcs, mit denen wir eng verbunden sind, brauchen Unterstützung. Folgt dieser Straße weiter nach Osten und dann weiter nach Norden bis nach Crossroads. Sucht Thork in seinen Mauern, er hat den Segen der Erdenmutter.", progress = nil, completion = "Es ist schön zu sehen, dass uns noch mehr unserer Verbündeten von so weit entfernt wie Thunder Bluff zu Hilfe kommen, &lt;Volk&gt;. Ich heiße Euch erneut willkommen.", rewards = "Ihr bekommt:\n\n"},
[855] = {title = "Zentaurenarmschienen", objective = "Bringt Regthar Deathgate westlich von Crossroads 15 Zentaurenarmschienen.", description = "Die Kolkar sind eine echte Bedrohung für die Besitzansprüche der Horde im Brachland und wir müssen deren Truppen unbedingt dezimieren. Deshalb habe ich eine lohnenswerte Aufgabe für Euch.\n\nErschlagt ihre Krieger, während Ihr Euch auf dem Territorium der Kolkar befindet, und sammelt Zentaurenarmschienen ein. Kommt zurück, wenn Ihr eine ordentliche Menge Armschienen beisammen habt, dann wird Euch die Horde reich belohnen.", progress = "Wie läuft Eure Jagd, <Name>?", completion = "Sehr gut gemacht. Ihr habt den überlebenden Zentauren bestimmt eine Heidenangst eingejagt, &lt;Name&gt;. Wenn sie klug sind, beruhigen sie sich jetzt und stellen ihre Angriffe ein.\n\nAber ich glaube nicht daran und das ist bedauerlich.\n\nBedauerlich... für sie.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nOrc-KampfbogenSpitze AxtSteinholzhammer\n\nIhr bekommt außerdem:\n\n"},
[857] = {title = "Die Träne der Monde", objective = "Feegly der Verbannte möchte, dass Ihr ihm die Träne der Monde zurückbringt.", description = "Ich hatte die Macht! In diesen meinen Händen! Und ich möchte sie wiederhaben! Wiederhaben möchte ich sie!\n\nDiese dreckigen Ausgräber haben sie entdeckt... sie war so wunderschön. Die Träne der Monde war die erste größere Entdeckung, die wir in Bael Modan gemacht haben.\n\nSie hätte mir gehören sollen! Mir!\n\nGeneral Twinbraid war eifersüchtig auf die Macht, die sie mir verlieh; er sperrte sie weg, in der Burg. Sagte, sie sei verflucht! Dieser Dummkopf!\n\nAndere wollten sie auch haben und sie mussten daran gehindert werden! Dieser Bastard Twinbraid jagte mich weg.\n\nJetzt möchte ich sie wiederhaben. Wiederhaben möchte ich sie!", progress = "Wo ist die Träne der Monde? Ich brauche sie jetzt! Ich brauche sie!", completion = "Endlich, die Macht gehört wieder mir! Mir!", rewards = "Ihr bekommt:\n\n"},
[858] = {title = "Zündung", objective = "Holt den Zündschlüssel und bringt ihn Wizzlecrank.", description = "Euch hat nicht etwa Sputtervale geschickt? Ich stecke hier in der Klemme. Ich bin hier reingesprungen, ohne daran zu denken, dass ich einen Schlüssel brauche, um die Antriebswelle des Schredders aufzuschließen. Einer der anderen Schredderbediener fragte mich, ob alles in Ordnung sei, und da bin ich in Panik geraten! Statt ihm zu sagen, dass ich meinen Schlüssel nicht dabei hatte, sagte ich ihm, dass es irgendeine mechanische Störung gäbe.\n\nWir müssen hier weg, und zwar schnellstens! Geht hinauf zum Kontrollraum oben auf dem Kran, der Vorsteher sollte einen Schlüssel für diesen Schredder haben.\n\nHelft mir hier raus!", progress = "Schnell, wir müssen hier weg, bevor jemand misstrauisch wird!", completion = "Ja, das sieht nach dem richtigen Schlüssel aus. Lasst mich nur kurz sehen, wie dieses Ding funktioniert...\n\nHmm... Rotationssteuerung... Damit werden Tempo und Stabilität reguliert... präzise Auslegersteuerung. Seht Euch das nur mal an! Ich fasse es nicht, dass die Venture Company etwas entwickelt hat, das so viel besser ist als unseres. Ich muss das nach Ratchet bringen!", rewards = "Ihr bekommt:\n\n"},
[860] = {title = "Sergra Darkthorn", objective = "Sprecht in Crossroads mit Sergra Darkthorn.", description = "Wenn Ihr den Pfad der Jäger beschreiten möchtet, dann führt Euch Eure Reise ins Brachland. Die dortigen Wildtiere sind willensstark und unglaublich wild. Ihr werdet beim Jagen dort viel lernen und Euer Geist wird sich entfalten.\n\nSprecht mit Sergra Darkthorn. Sie wird im Brachland Eure Führerin sein.\n\nSergra ist in Crossroads zu finden. Um zu ihr zu gelangen, müsst Ihr von Bloodhoof aus gen Osten ins Brachland reisen und dann an der Weggabelung nach Norden abbiegen. Und seid vorsichtig auf dieser Reise - das Brachland hält für die Unvorbereiteten und Unachtsamen große Gefahren bereit.", progress = nil, completion = "Ihr möchtet im Brachland jagen?\n\nIhr habt eifrige und junge Augen. Sie sind noch nicht ermüdet vom Lesen der Fährten Eurer Beute in den trockenen Ebenen dieses Landes.\n\nAber sorgt Euch nicht. Wir werden Euren Körper und Euren Geist stärken. Und wir werden Euch lehren, dass die Jagd nicht nur darin besteht, Eure Beute aufzustöbern und zu töten.\n\nMacht Euch bereit. Eure Reise beginnt. Jetzt.", rewards = "Ihr bekommt:\n\n"},
[861] = {title = "Der Weg der Jäger", objective = "Bringt Melor Stonehoof in Thunder Bluff 4 Flachlandstreunerklauen.", description = "Euch hat das Jagdfieber gepackt, wie ich sehe. Auch ich war einst wanderlustig...\n\nWollte wandern und jagen. Denn die Jagd ist die größte Ehre für einen Tauren.\n\nWenn Ihr ernsthaft das Leben eines Jägers führen wollt, dann wird Euch Melor Stonehoof den Weg weisen. Er lebt in Thunder Bluff auf der Anhöhe der Jäger.\n\nBringt ihm die Klauen der Flachlandstreuner von Mulgore, um ihm Eure Fertigkeit und Eure Entschlossenheit zu beweisen. Sie sind zäh und schlau - angemessene Beute für einen wie Euch, <Klasse>, der so jung wie Ihr auf dem Pfad der Jäger wandeln möchte.", progress = "Seid gegrüßt. Ihr habt etwas an Euch, das mir viel über Euch verrät. Wollt Ihr etwas von mir?", completion = "Skorn Whitecloud ist ein weiser &lt;Volk&gt;. Jahr um Jahr ging er auf die Jagd, und obwohl sein Körper alt ist, brennt sein Geist doch umso heller. Es ist uns eine Ehre, ihn bei uns zu haben.\n\nWenn Skorn Euch zu mir geschickt hat, dann müsst auch Ihr vom Geist der Jäger erfüllt sein. Und Ihr habt diese Klauen mitgebracht, die Euer wachsendes Können beweisen.\n\nVielleicht seid Ihr schon bereit, den Pfad zu beschreiten.", rewards = "Ihr bekommt:\n\n"},
[862] = {title = "Grubenratteneintopf", objective = "Bringt Grub östlich von Crossroads 8 Grubenratten.", description = "Ein <Klasse> wie Ihr muss hier im Brachland doch ziemlich hungrig sein. Ich bin den ganzen Tag am Verhungern.\n\nIch sag Euch was, ich bereite Euch einen feinen Eintopf zu. Ich brauche nur ein paar Grubenratten.\n\nScheint so, als würden diese dreckigen Zwerge in Bael Modan von unser aller Lieblingsspeise überrannt. Also reist gen Süden nach Bael Modan und bringt mir ein paar Grubenratten.\n\nIhr dürft Euch erst einen erfahrenen Abenteurer nennen, wenn Ihr Euch ein bisschen mit der Rattenjagd beschäftigt habt! Ha!", progress = "Na, schon genug Grubenratten erwischt, <Name>?", completion = "Normalerweise mag ich diese Nagetiere nicht, wenn sie so... abgehangen sind. Ich lasse sie gern ein paar Wochen faulen, bis sich der Geschmack so richtig entwickelt hat. Aber Ihr seht so hungrig aus.\n\nIch werde Euch etwas Grubenratteneintopf zubereiten. Ah, fertig.\n\nBitte sehr!", rewards = "Ihr bekommt:\n\nRezept: GrubenratteneintopfGrubenratteneintopfApotheker-Handschuhe"},
[863] = {title = "Die Flucht", objective = "Schützt Wizzlecrank und den gestohlenen Goblinschredder auf dem Weg zu Sputtervalve in Ratchet.", description = "Ich würde mal sagen, ich kann das nach und nach lernen... Kann ja nicht so schwer sein. Ein paar Knöpfchen hier, ein oder zwei Hebelchen da... Also, seid Ihr bereit zu gehen?", progress = nil, completion = "Hoffentlich liefert uns dieser Prototyp-Schrotthaufen etwas Brauchbares... mir läuft langsam die Zeit davon! Ich schicke schnellstens ein Bergungsteam zu Wizzlecranks Standort.\n\nOh, hier habt Ihr noch etwas für Eure Bemühungen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLeuchtfeuerbatonSchmierige Tüftlerhose\n\nIhr bekommt außerdem:\n\n"},
[864] = {title = "Kehrt zu Apothekerin Zinge zurück", objective = "Bringt das versiegelte Feldtestset nach Undercity zu Apothekerin Zinge.", description = "\"Wir sind so weit, die Kraftquelle ist entfernt und die Daten sind gesichert. Also dann, sichere Reisen und all das. Ich hoffe, das ruchlose Wissenschaftsexperiment hat sich für Euch ausgezahlt.\"\n\nDer Goblin wendet sich von Euch ab, um sich den Belangen der Gadgetzan Water Company zu widmen. Ihr verstaut das versiegelte Testset sicher für die Reise zurück nach Undercity. Dort wartet Apothekerin Zinge auf Euch und das versiegelte Feldtestset.", progress = "Willkommen. Zumindest willkommen, wenn Ihr mit einem versiegelten Testset zurückkehrt. Anderenfalls werde ich so tun, als hätte ich Eure völlige Unfähigkeit nicht bemerkt, und Euch mit meinem Zorn verschonen, bis Ihr getan habt, womit Ihr beauftragt wurdet, und Eure Aufgabe ausgeführt habt.", completion = "Ich werde die Daten sofort analysieren. Vielleicht stellt sich Keevers Wahnsinn doch noch als mein Genie heraus.\n\nWas Euch angeht... Ihr seid nützlich für mich und ich belohne jene fürstlich, die weiterhin nützlich sind. Nehmt diesen Gegenstand, diese Münze, und als Wichtigstes noch meinen Dank dazu.\n\nSchaut von Zeit zu Zeit mal wieder rein - ich wette, dass unsere Zusammenarbeit an diesem Projekt noch nicht zu Ende ist.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGeschickte Abrichtungs-HandschuheApothekermeistercapeSchultern der Gelehrsamkeit\n\nIhr bekommt außerdem:\n\n"},
[865] = {title = "Raptorhörner", objective = "Sammelt 5 intakte Raptorhörner von Bluthornsensenklauen und bringt sie Mebok Mizzyrix in Ratchet.", description = "Die Raptoren des Brachlandes sind intelligenter als die Raptoren anderer Länder. Und ich glaube, dass ihre ganze Intelligenz in ihren Hörnern sitzt! Wenn dem so ist, könnte ich ihre Hörner zu Pulver zermahlen und benutzen, um \"Klugheitstränke\" zu kreieren. Dafür würde ich ein Vermögen bekommen!\n\nUnd Ihr könntet mir helfen; sucht und bringt mir intakte Raptorhörner von Bluthornsensenklauen. Sie durchstreifen den Süden sowie den Norden des Brachlandes an der Grenze zum Wald von Ashenvale.", progress = "Habt Ihr die Hörner, <Name>? Diese Dinger werden mir ein Vermögen einbringen!", completion = "Toll, Ihr habt sie! Jetzt muss ich sie nur noch zermahlen und mit etwas Wein vermischen und...", rewards = "Ihr bekommt:\n\nRaptorpunschBarkeeper-Umhang"},
[866] = {title = "Wurzelproben", objective = "Bringt Mebok Mizzyrix in Ratchet 8 Wurzelproben.", description = "Die Kräuter des Brachlandes sind anders als Kräuter anderer Länder. Ihre Eigenschaften sind zwar fast dieselben, aber das Oasenwasser hier verändert die Pflanzen; sie sind ein klein bisschen anders.\n\nIch möchte diese Unterschiede studieren... um zu sehen, ob man daraus nicht Kapital schlagen kann!\n\nFalls Ihr in der Kräuterkunde bewandert seid, sammelt doch ein paar Wurzelproben der Kräuter, die Ihr im Brachland findet. Bringt mir diese Proben, damit ich sie mit Kräutern aus anderen Regionen vergleichen kann.", progress = "Hallo, <Name>. Habt Ihr die Wurzelproben?", completion = "Ja, ja, die sind wirklich gut! Aus diesen Wurzeln werde ich Pflanzen ziehen, die ich dann studieren kann. Ich erhoffe mir, ein paar neue Eigenschaften daran zu finden. Versteckte, wertvolle Eigenschaften...!\n\nUnd keine Sorge - sollte ich etwas finden, seid Ihr der Erste, der es erfährt. Weil ich dann jemanden brauche, der noch mehr sammelt!", rewards = "Ihr bekommt:\n\nSporenbedeckte Tunika"},
[867] = {title = "Räuberische Harpyien", objective = "Sammelt 8 Krallen der Hexenschwingen.\n\nBringt sie Darsok Swiftdagger in Crossroads.", description = "Die verdammten Harpyien haben unsere Karawanen lang genug geplündert; es ist an der Zeit, dass wir einigen von ihnen die Hälse abschneiden und ihre Anzahl verkleinern.\n\nIch hab mich bei ihren Nestern mal ein bisschen umgeschaut und herausgefunden, wer da wen anführt. Der vernichtendste Angriff wird einen guten Teil ihrer niederen Befehlskette zerstören und dann können wir uns bis zur Spitze vorarbeiten.\n\nWir fangen langsam an; schaltet die Harpyien der Hexenschwingen und Wildfedern der Hexenschwingen im Nordwesten aus und bringt mir 8 Krallen der Hexenschwingen. Das sollte ein guter Anfang sein...", progress = "Na, schon genug davon erledigt? Immer schön aufschlitzen und weitere Trophäen sammeln. Ich möchte 8 Krallen der Hexenschwingen haben.", completion = "Oh, die sind hübsch. Wirklich hübsch... Gut gemacht, &lt;Name&gt;. Ich freue mich schon so darauf, Euch in Zukunft wieder in Aktion zu sehen.", rewards = "Ihr bekommt:\n\n"},
[868] = {title = "Eierjagd", objective = "Bringt Korran in Crossroads 12 Silithideneier und die Grabgabel.", description = "He, <Name>. Man hat mich nach Crossroads geschickt, damit ich über das Land wache und meinen Meistern in Orgrimmar über eventuelle Vorkommnisse berichte.\n\nEines meiner Studienobjekte sind die insektenartigen Kreaturen, die man im Süden auf dem Feld der Riesen findet. Wir wissen nur wenig über diese Kreaturen, also haben wir es uns zur Aufgabe gemacht, mehr über sie zu erfahren. Sie scheinen intelligent zu sein, intelligenter als normale Tiere.\n\nNehmt diese Grabgabel und grabt ein paar ihrer Eier aus den Hügeln aus, aber seid vorsichtig: einmal aufgeschreckt, werden sie Euch angreifen.", progress = "Seid vorsichtig mit den Eiern, die Ihr findet, <Name>. Wenn sie zerbrechen, nützen sie mir nichts mehr.", completion = "Ihr macht mich froh, &lt;Name&gt;. Die Eier und das Werkzeug. Gut gemacht.\n\nUnd was Eure Belohnung betrifft...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHarlekin-RobenViolette Schuppenrüstung\n\nIhr bekommt außerdem:\n\n"},
[869] = {title = "Raptorendiebe", objective = "Bringt Gazrog in Crossroads 12 Raptorenköpfe.", description = "Vor kurzem wurde eine Ladung Silber aus unserem Wachturm entwendet. Sie war als Sold für die Crossroads-Wachen gedacht und wir wollen das Silber zurückhaben.\n\nDas Seltsamste daran ist... wir haben einen der Diebe in der Nacht des Raubes erwischt. Und... es war ein Raptor! Unglaublich!\n\nIch weiß nicht, wofür Raptoren Silber brauchen könnten. Aber das ist mir auch egal - ich will die Raptoren tot sehen, damit sie uns nicht wieder bestehlen!\n\nJagt Raptoren im Brachland. Sammelt ihre Köpfe für mich!", progress = "Habt Ihr die Köpfe, <Name>?", completion = "Ihr habt uns die Raptoren vom Hals geschafft!\n\nDanke, &lt;Name&gt;. Ihr seid ein &lt;Klasse&gt; von hohem Wert.", rewards = "Ihr bekommt:\n\n"},
[870] = {title = "Die vergessenen Teiche", objective = "Berichtet Tonga Runetotem von Euren Entdeckungen.", description = "Vor langer Zeit war das Brachland ein üppiger Ort voller Leben. Aber Krieg und Katastrophen verheerten das Land, verbrannten es und jetzt ist es nur noch eine ausgedörrte Hülse. So ist es nun einmal und es macht mich traurig.\n\nIn den letzten Jahren jedoch sind Oasen im Brachland entstanden und das Leben blüht wieder auf. Und wir Druiden spüren eine Macht von ganz tief unten an die Oberfläche dringen.\n\nWir müssen ihre Quelle finden. Reist zu den vergessenen Teichen nordwestlich von Crossroads. Sucht in den dortigen Gewässern nach einer Quelle der Macht und kommt dann hierher zurück.", progress = nil, completion = "Ihr habt einen Riss in der Erde gefunden, aus dem Gase strömten? Seltsam. Das könnte die Antwort auf unsere Fragen sein, aber das wissen wir nicht sicher.\n\nAber es ist immerhin ein Hinweis. Und ich bin dankbar, dass Ihr ihn gefunden habt.", rewards = "Ihr bekommt:\n\n"},
[871] = {title = "Vereitelung der Angriffe", objective = "Tötet 8 Wassersucher, 8 Dornwirker sowie 3 Jäger des Grimmhauerstamms und kehrt dann zu Thork in Crossroads zurück.", description = "Alle Stacheleber sind unsere Feinde, <Name>. Manche sind nur lästiger als andere.\n\nDer Grimmhauerstamm hat unsere Nachschublinien von Durotar aus angegriffen, was uns nicht wenig Ärger bereitet. Ich habe Späher ausgeschickt, um den Anführer dieser Überfälle zu finden, aber bis es so weit ist, könnte es uns schon helfen, wenn Ihr diese dreckigen Schweinemenschen etwas dezimieren würdet.\n\nBeginnt im Nordosten in Richtung Durotar. Ihr könnt ihre Baue immer an den riesigen, dornigen Ranken erkennen, die aus dem Boden wachsen. Sucht sie und erschlagt sie.", progress = nil, completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Diese unverschämten Stacheleber werden irgendwann lernen, dass mit der Stärke der Horde nicht zu spaßen ist.", rewards = "Ihr bekommt:\n\n"},
[872] = {title = "Das Ende der Unterbrechungen", objective = "Tötet 8 Geomanten der Grimmhauer, 8 Verteidiger der Grimmhauer und Kreenig Grantelschnauze.\n\nBringt dann Thork in Crossroads Kreenig Grantelschnauzes Hauer.", description = "Einer meiner Späher war Zeuge eines Angriffs auf eine Karawane aus Durotar, <Name>. Die Übeltäter waren in der Tat vom Grimmhauerstamm der Stacheleber. Ein ganz bestimmter Stacheleber führte den Überfall an: Kreenig Grantelschnauze. Man hat ihn nordöstlich von hier gesehen, gleich südlich der Straße von Durotar. Wenn diese Bedrohung jemals ein Ende finden soll, dann muss Kreenig sterben.\n\nDamit diese Angriffe auch wirklich aufhören, würde ich sagen, dass wir das Ganze auf die Spitze treiben sollten. Tötet Kreenig und andere seines Stammes und kehrt dann zu mir zurück, wenn Ihr seine Hauer habt.", progress = "Schneidet dem Anführer den Kopf ab, dann bricht das Chaos aus, <Name>. Lernt diese Lektion sorgfältig. Sie wird Euch in der Zukunft helfen.\n\nDie Eber werden ziellos davonstieben und wir können das Brachland zurückerobern.", completion = "Gut gemacht, &lt;Name&gt;. Da Kreenig tot ist, werden die Angriffe auf unsere Karawanen merklich nachlassen.\n\nUnser Volk kann sich stolz schätzen, Euch an unserer Seite zu haben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBindegurtSattelgurt-Gürtel\n\nIhr bekommt außerdem:\n\n"},
[873] = {title = "Isha Awak", objective = "Bringt Mahren Skyseer das Herz von Isha Awak.", description = "Isha Awak ist der Herr über diese Gewässer. Groß ist seine Kraft und edel sein Stolz. Die Menschen an der Küste fürchten ihn, denn er hat großen Schaden unter ihnen angerichtet.\n\nIch jedoch fürchte ihn nicht. Ich bin froh, dass er hier ist. Er ist eine würdige Herausforderung und eine ehrenhafte Beute.\n\nWenn Ihr bereit seid, schwimmt hinaus und sucht nach Isha Awak, der Tiefsten Verdammnis.\n\nSein Geist wohnt in seinem Herzen, und dieses schlagen zu hören heißt, Euer Schicksal zu kennen.", progress = "Fürchtet Euch nicht vor den Gewässern, <Volk>.", completion = "Ihr seid jetzt eins mit Isha Awak, &lt;Name&gt;. Sein Geist ist mit Euch. Er lauert in Euren Augen...\n\nAugen, die eines Tages lernen werden zu sehen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBrandzeichenruteSchutzschild des Tales\n\nDer folgende Zauber wird auf euch gewirkt:\n\nKraft von Isha Awak\n\nIhr bekommt außerdem:\n\nBestienmeistergurt"},
[874] = {title = "Mahren Skyseer", objective = "Sprecht mit Mahren Skyseer.", description = "Ihr habt die Wildtiere des Brachlandes gejagt. Euer Geist ist stark. Ein Jäger muss jedoch immer vorbereitet sein. Ein wahrer Jäger kann auf allen Pfaden seine Beute finden. Weder Berg noch Sumpf wird ihn wanken lassen.\n\nNicht einmal das Meer.\n\nSucht meine Schwester Mahren. Sie jagt die großen Wassertiere entlang der Küste. Sie wird Euch etwas über sie lehren.\n\nSeid jedoch vorsichtig, während Ihr nach ihr sucht, denn die Küste des Brachlandes ist in den Händen der Menschen.", progress = nil, completion = "Mein Bruder hat Euch geschickt, ja? Dann müsst Ihr Euch vor ihm bewiesen haben. Wenn Ihr Jorns Respekt erworben habt, habt Ihr auch meinen Respekt.\n\nSeid Ihr bereit, Euch weiter den Pfad der Jäger entlangzuwagen?", rewards = "Ihr bekommt:\n\n"},
[875] = {title = "Offiziere der Harpyien", objective = "Sammelt 6 Harpyienoffiziersringe von den Tötern der Hexenschwingen und kehrt dann zu Darsok Swiftdagger in Crossroads zurück.", description = "Hahaha, <Name>. Ihr wollt noch mehr? Gut, das hör ich gern.\n\nDieses Mal möchte ich, dass Ihr ein paar der Offiziere der Harpyien in den trockenen Hügeln meuchelt. Nur Töter der Hexenschwingen können Offiziere werden und Ihr erkennt sie an den Ringen, die sie tragen. Sie sind ein übler Haufen, aber sie führen ein paar der Unterlinge in diesem Gebiet an. Schaltet Ihr 6 davon aus, wird das ein Entscheidungsschlag gegen ihr Matriarchat sein.\n\nSorgt dafür, dass sie schmerzvoll sterben, <Name>. Wir möchten, dass diese Dirnen von Harpyien lernen, wie wahnwitzig es ist, sich mit der Horde anzulegen.", progress = "Habt Ihr die 6 Harpyienoffiziersringe schon? Ihnen muss wegen ihrer heimtückischen Angriffe auf die Horde Gerechtigkeit widerfahren.", completion = "Ausgezeichnete Arbeit. Ich glaube, Ihr werdet es in der Horde weit bringen.", rewards = "Ihr bekommt:\n\n"},
[876] = {title = "Serena Blutfeder", objective = "Erschlagt Serena Blutfeder und bringt Darsok Swiftdagger in Crossroads ihren Kopf.", description = "Ihr habt das mit den Offizieren und Unterlingen so gut erledigt, dass ich Euch noch um einen letzten Dienst bitten möchte.\n\nSerena Blutfeder ist die Schwester einer Harpyie namens Blutfeder, die Rexxar vor einer ganzen Weile erschlug. Offensichtlich wurden die Karawanen der Horde angegriffen, um ihre Schwester zu rächen.\n\nIch möchte, dass Ihr ihr die Kehle durchschneidet und mir ihren Kopf bringt. Er soll die nächste Karawane schmücken, die wir losschicken... Gebt diesen Harpyien etwas, über das sie nachdenken können.", progress = nil, completion = "Ha! Gut gemacht, &lt;Name&gt;! Sehr gut gemacht... Ich war mir nicht sicher, ob Ihr der Sache gewachsen seid, aber Ihr habt Euch als ausgezeichneter Halsabschneider erwiesen. Nochmals vielen Dank, dass Ihr uns geholfen habt, die Harpyienepidemie einzudämmen. Hier habt Ihr Eure Belohnung, verwendet sie klug.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nElegantes KurzschwertHarpyienkürschnerZhovur-Axt\n\nIhr bekommt außerdem:\n\n"},
[877] = {title = "Die brackige Oase", objective = "Kehrt zu Tonga in Crossroads zurück, nachdem Ihr die brackige Oase untersucht habt.", description = "Erdrisse wie jene, die Ihr bei den vergessenen Teichen gefunden habt, könnte es auch bei anderen Oasen im Brachland geben. Wenn es so ist, sind diese Risse vielleicht die Lebensquelle dieser Oasen.\n\nWir müssen das überprüfen.\n\nHier, nehmt diese Samen. Sie sind tot und unfruchtbar, aber bringt sie dennoch zur brackigen Oase im Südosten. Falls es dort einen Riss gibt, legt die Samen hinein und ... wartet ab.", progress = "Wart Ihr in der brackigen Oase? Gab es dort einen Riss unterhalb des Gewässers?", completion = "Eure Entdeckungen sind erstaunlich! Die Samen, die ich Euch gab, waren vertrocknet und tot. Was immer auch unter diesen Oasen schlummert, kann aus dem Nichts Leben entstehen lassen!\n\nWir müssen das noch genauer studieren...", rewards = "Ihr bekommt:\n\n"},
[878] = {title = "Stämme im Krieg", objective = "Erledigt 6 Wassersucher der Borstennacken, 12 Dornenwirker der Borstennacken sowie 12 Geomanten der Borstennacken und kehrt zu Quetschzahn im Camp Taurajo im Brachland zurück.", description = "Ihr müsst meine Feinde schlagen. <schnaubt> Ihr müsst Quetschzahn und dem Grimmhauerstamm helfen, indem Ihr die Borstennacken schwächt. Beide Stämme sind sehr spirituell - gebunden an die Erde und ihre Kraft. <schnaubt> Sie gibt uns Stärke in allen Dingen... besonders im Krieg.\n\nWenn ihr herausfinden wollt, wer Thork <schnaubt> und der Horde wirklich solche Angst bereitet, dann helft Quetschzahn! Ihr greift die spirituellen Anführer der Borstennacken im Norden an und schwächt sie, sodass die Grimmhauer sie besiegen und das Brachland beherrschen können.", progress = "Mehr Informationen <schnaubt> für die Horde gibt es, wenn Ihr die Weisen der Borstennacken getötet habt, <Volk>.  Nicht einen Moment früher! Quetschzahn ist kein Narr.", completion = "Ja, ja... viel Freude, da endlich &lt;schnaubt&gt; die Borstennacken den Schmerz meines Stammes kennen, &lt;Volk&gt;. Das sollte ich fühlen, aber das ist nicht  der Fall.\n\nMan hilft seinen Leuten und sie ehren einen. Quetschzahn hilft seinen Leuten, und was tun sie? Sie drehen ihm den Rücken zu. Sie vergessen ihn und lassen ihn in einem Käfig verrotten!\n\nIch helfe ihnen sogar hinter Gittern und sie schicken niemanden, um mich zu retten!", rewards = "Ihr bekommt:\n\n"},
[879] = {title = "Verräter in den eigenen Reihen", objective = "Tötet Nak, Kuz und Lok Orcbane und bringt Quetschzahn im Camp Taurajo im Brachland ihre Schädel.", description = "Drei meines Stammes kamen aus dem Kral, um die Überfälle gegen die Horde anzuführen, <Volk>. <schnaubt> Sie sind ruchlos und schlau und wenn Ihr sie besiegt, dann werden Crossroads und auch der Großteil des Brachlandes Frieden haben... <schnaubt> zumindest vor dem Grimmhauerstamm. <schnaubt>\n\nSucht nach Nak, Kuz und Lok Orcbane. Sie befinden sich weit im Süden des Brachlandes. Einer ist ein Zauberer, ein weiterer ein Fährtenleser und ihr Anführer, den sie Orcbane nennen, <schnaubt> ist ein Krieger. Tötet sie, <Volk>, so wie sie mich töteten.", progress = "Wie läuft Eure Jagd, <Volk>? \n\nThork glaubt, dass er die Wahrheit darüber kennt, wer die Überfälle auf sein Volk angeführt hat,  aber er wird bald erfahren, wie sehr er sich irrt, wenn Ihr erst Erfolg gehabt habt.\n\nMein Tod ist unabwendbar, aber Ihr habt meinen Feinden große Schmerzen bereitet, sodass Quetschzahn nichts bereut.", completion = "Dann ist es vollbracht. Besser, wenn es so endet, sagt Quetschzahn. &lt;schnaubt&gt; Sie hätten &lt;schnaubt&gt; sicherstellen sollen, dass ich tot bin, als sie mir den Rücken zuwendeten, statt mich &lt;schnaubt&gt; in diesem verlassenen Käfig zu lassen.\n\nJetzt gibt es für Euch nur noch eine Aufgabe zu beenden, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"},
[880] = {title = "Veränderte Wesen", objective = "Bringt Tonga Runetotem in Crossroads 8 veränderte Schnappkieferschalen.", description = "Eure Entdeckungen sind erstaunlich, <Name>. Diese Oasen haben Eigenschaften, die von einer Quelle außerhalb stammen müssen. Oder vielleicht von einer inwärtigen.\n\nIch muss wissen, auf welche Weise diese Felsspalten die Wildtiere beeinflussen, die vom Wasser der Oasen trinken.\n\nJagt Oasen-Schnappkiefer in der blühenden Oase und der brackigen Oase. Bringt mir ihre Schalen, damit ich sie untersuchen kann.", progress = "Wie läuft Eure Sammelaktion? Habt Ihr die Schalen?", completion = "Danke, &lt;Name&gt;. Beim Studieren der Wildtiere eines Gebiets kann man viel über das Gebiet selbst herausfinden. Wir werden sehen, welche Geschichte uns diese Schalen erzählen.\n\nBitte lasst mich Euch für Eure Hilfe danken... und vielleicht habt Ihr ja Verwendung für diese Münzen. Ich zumindest brauche sie nicht.", rewards = "Ihr bekommt:\n\n"},
[881] = {title = "Echeyakee", objective = "Bringt Sergra Darkthorn in Crossroads Echeyakees Balg.", description = "Whitemist, Echeyakee in der Sprache der Tauren, ist der König der Savannenkatzen. Er jagt mit solcher Verstohlenheit, dass man sagt, er sei wie ein dünner, weißer Nebel auf der Erde. Und er tötet so schnell, dass seine Beute weder Angst noch Schmerz verspürt.\n\nDie Tauren sagen, er sei sowohl Gnade als auch Tod.\n\nIhr werdet erfahren, ob das wahr ist, denn ich schicke Euch aus, um Echeyakee zu jagen. Sein Unterschlupf befindet sich im Nordosten von Crossroads, zwischen den Knochen des riesigen Kodos.\n\nGeht jetzt. Blast dieses Horn, wenn Ihr seinen Unterschlupf erreicht. Blast das Horn und er wird kommen.", progress = "Die große Katze ruft Euch, <Name>.", completion = "Ihr habt Echeyakee geschlagen und obwohl seine Tage als Jäger vorbei sind... ist sein Geist mit Euch. Er wird Euch die Kraft zeigen, die im Feingefühl liegt, und welche Ehre Gnade birgt.\n\nEuer Weg ist immer noch lang, &lt;Klasse&gt;. Hoffen wir, dass Ihr ihn gut beschreitet.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEcheyakees Anmut\n\nIhr bekommt:\n\n"},
[882] = {title = "Ishamuhale", objective = "Bringt Jorn Skyseer im Camp Taurajo Ishamuhales Fangzahn.", description = "Ishamuhale - Speerzahn - ist der wildeste Bluthornraptor des Brachlandes. Er jagt weder zum Spaß noch für Nahrung. Er jagt, weil Jagen seine Leidenschaft ist. Er tötet, weil Töten seine Natur ist.\n\nUnd Ihr werdet Euch mit seiner Natur vertraut machen, <Name>, denn Euer Weg folgt jetzt den Krallenspuren Ishamuhales.\n\nBeginnt mit der Jagd. Erlegt seine Lieblingsbeute, ein Zhevra, und bringt den Kadaver zum toten Baum im Nordwesten von Ratchet. Ishamuhale wird den Kadaver riechen und von ihm angezogen werden.\n\nSeid bereit, wenn er kommt.", progress = "Habt Ihr Ishamuhale schon besiegt, <Name>?", completion = "Sein Fangzahn ist nur eine Art Andenken, aber von großer Bedeutung.\n\nIhr tragt Ishamuhales Kraft in Euch, &lt;Name&gt;. Mögt Ihr sie mit Mäßigung nutzen. Das ist Eure Bürde.\n\nDas ist Eure Ehre.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nIshamuhales Wut\n\nIhr bekommt:\n\n"},
[883] = {title = "Lakota'mani", objective = "Bringt Jorn Skyseer im Camp Taurajo Lakota'manis Huf.", description = "Lakota'manis Huf ist ein Symbol für die Kraft der großen Kodos.", progress = "Als ich Euch kommen sah, bemerkte ich eine neue Macht in Eurem Gebaren. Sagt mir - hat sich Euer Geist mit dem großen Lakota'mani vereint?", completion = "Lakota'mani wird in unserer Sprache auch 'Erderschütterer' genannt, denn seine Schritte sind wie der geballte Donner. Er ist jetzt mit Euch und sein Mut und seine Beständigkeit verbinden sich mit Euch. So verbunden gibt es keinen Konflikt, dem Ihr Euch nicht stellen könnt.\n\nSchreitet erhobenen Hauptes, &lt;Name&gt;. Schreitet erhobenen Hauptes, Erderschütterer.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLakota'manis Donner\n\nIhr bekommt:\n\n"},
[884] = {title = "Owatanka", objective = "Bringt Jorn Skyseer im Camp Taurajo Owatankas Schwanzstachel.", description = "Wenn man Owatankas Schwanzstachel berührt, stieben Funken auf.", progress = "<Name>, Eure Augen sind von einer neuen Macht erfüllt! Ihr habt Euch mit dem mächtigen Owatanka vereint, nicht wahr?", completion = "Die Donnerechse Owatanka wird von den Tauren auch 'Blauer Blitz' genannt, denn ihm ist eine Schnelligkeit zu Eigen, über die seine Größe hinwegtäuscht. Man sagt, dass der Blaue Blitz vor langer Zeit von einem Blitz getroffen wurde und die Energie der großen Bestie dank der Himmelswut grenzenlos sei.\n\nMöge seine Energie Euch durchströmen, &lt;Name&gt;. Haltet Euren Frieden mit Owatanka.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nTempo von Owatanka\n\nIhr bekommt:\n\n"},
[885] = {title = "Washte Pawne", objective = "Bringt Jorn Skyseer im Camp Taurajo Washte Pawnes Feder.", description = "Eine Berührung mit der Feder von Washte Pawne ist schmerzhaft.", progress = "Ihr seid von neuer Entschlossenheit erfüllt, <Name>. Einer Entschlossenheit, geboren aus Schmerz...\n\nLastet Washte Pawnes Tod auf Euch?", completion = "Der Donnerfalke ist ein seltenes Tier des Brachlandes und sein Tod kann großes Glück oder großes Unheil nach sich ziehen.\n\nWashte Pawne jedoch, auf Taurisch auch 'Geistbeißer' genannt, bedeutet nichts davon... oder beides.\n\nDer Schmerz, den Ihr bei der Jagd auf den Geistbeißer gespürt habt, ist das Schmerzgefühl, das all jene spüren, die unter großen Opfern Großes erreichen. Der Stich, den Ihr gespürt habt, ist der Schmerz des Bedauerns.\n\nIch kann jedoch sehen, dass Ihr ihn überwunden habt. Ihr habt gelernt, dass Bedauern in Weisheit übergeht und dass man durch Schmerz an Kraft gewinnt.\n\nIhr habt viel gelernt, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWashte Pawnes Entschlossenheit\n\nIhr bekommt:\n\n"},
[886] = {title = "Die Oasen des Brachlandes", objective = "Sprecht in Crossroads mit Tonga Runetotem.", description = "Die Druiden von Thunder Bluff spüren eine große Macht, die östlich von Mulgore ins Brachland sickert.\n\nTonga Runetotem wurde entsandt, um die Quelle dieser Macht ausfindig zu machen, aber wir befürchten, dass er Hilfe brauchen wird.\n\nReist ins Brachland und sprecht mit Tonga. Er wird in Crossroads sein. Um dorthin zu gelangen, folgt der Straße von Bloodhoof aus nach Osten. Betretet das Brachland und wendet Euch bei der Weggabelung weiter nach Norden. Geht weiter Richtung Norden, dann gelangt Ihr nach Crossroads.\n\nUnd haltet Euch immer auf der Straße, <Name>, denn das Brachland ist ein raues Land.", progress = nil, completion = "Meine Brüder in Thunder Bluff waren weise, Euch herzuschicken, &lt;Klasse&gt;. Denn das Rätsel des Brachlandes ist eines, das ich nicht lösen kann.\n\nLasst uns hoffen, dass wir mit Eurer Hilfe Antworten auf unsere Fragen finden.", rewards = "Ihr bekommt:\n\n"},
[887] = {title = "Südmeerfreibeuter", objective = "Tötet für Gazlowe in Ratchet 12 Briganten der Südmeerfreibeuter und 6 Kanoniere der Südmeerfreibeuter.", description = "Ich wünschte, Vize-Admiral Grezzlik würde bessere Arbeit bei der Sicherung der Meere für unsere Handelsschiffe leisten. Bei all dem Gold, das die Handelsbarone in die Handelsflotten gesteckt haben, macht es mich rasend zu sehen, wie viele Piraten unbehelligt unterwegs sind, meine Schiffe überfallen und meine Waren stehlen!\n\nMir kam zu Ohren, dass die Südmeerfreibeuter südlich von hier ein Lager aufgeschlagen haben. Sie sind mir ein echter Dorn im Auge, und wenn sich Grezzlik nicht um sie kümmert, könnt Ihr mir vielleicht helfen, sie loszuwerden?", progress = "Ich wage gar nicht daran zu denken, welcher Profit mir durch die Überfälle der Piraten entgeht, und jetzt haben sie auch noch ein Lager direkt vor meiner Haustür aufgeschlagen? Das artet langsam aus, Undermine muss etwas dagegen unternehmen.", completion = "Das habt Ihr gut gemacht. Macht noch ein bisschen so weiter, dann gibt es eine Sache weniger, um die ich mir Sorgen machen muss. Hoffentlich überzeugt es sie davon, woanders ihr Unwesen zu treiben.\n\nIn der Zwischenzeit gäbe es da noch das kleine Problem der mir gestohlenen Waren, die zurückgeholt werden müssen!", rewards = "Ihr bekommt:\n\n"},
[888] = {title = "Gestohlene Beute", objective = "Bringt Gazlowe in Ratchet die Stiefellieferung und die Teleskoplinse zurück.", description = "Ich hätte zwar gern, dass Ihr mir all meine Waren zurückbringt, aber das dürfte wohl unmöglich sein. Es gibt jedoch ein paar Dinge, die ich unbedingt wiederhaben muss!\n\nWie Ihr seht, ist mein Observatorium fast einsatzbereit, aber es fehlt noch die kleinere der zwei Linsen. Die erste Linse ist mit der Karawane aus Durotar gekommen, aber die zweite wurde per Schiff verschickt und ist nie hier eingetroffen. Ebenso ist meine Stiefellieferung von Drizzlik aus Booty Bay nicht hier angekommen!\n\nBegebt Euch zum Piratenlager und seht mal nach, ob Ihr die Dinge dort finden könnt.", progress = "Habt Ihr meine Sachen gefunden, <Name>?", completion = "Was für eine Erleichterung, dass ich all mein Zeug zurückhabe, also danke ich für Eure Hilfe, &lt;Name&gt;. Wisst Ihr, ein &lt;Volk&gt; wie Ihr wäre für meine Unternehmung hier sehr von Nutzen. Solltet Ihr jemals auf Arbeitssuche sein, denkt daran, wie gut Gazlowe für Dienstleistungen zahlt!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWanderer-HandschuheGefütterte Lamellenstiefel\n\nIhr bekommt außerdem:\n\n"},
[889] = {title = "Geist des Windes", objective = "Bringt Tatternack Steelforge in Crossroads 20 Blutsplitter.", description = "Wenn die Ranken aus der Erde brechen, treten oftmals auch Mineralvorkommen an die Oberfläche.\n\nEin ganz spezielles Mineral, das in der Nähe der Ranken zu finden ist, heißt Bluterz; der Borstennackenstamm glaubt, das Bluterz sei heilig und ein Teil von Agammagans Körper. Sie tragen manchmal Splitter davon als Glücksbringer bei sich.\n\nIch glaube, ich könnte aus diesem Erz eine neue Legierung herstellen, wenn ich genug davon hätte. Sucht südlich von hier auf der anderen Seite des ausgetrockneten Flussbetts nach Stammesmitgliedern der Borstennacken und bringt mir so viele Blutsplitter, wie Ihr könnt.", progress = "Bringt Quetschzahn 10 Blutsplitter und ich werde Euch mit großer Geschwindigkeit segnen. Ihr werdet mit den Zhevras laufen und der Wind wird eifersüchtig auf Euch sein.\n\nEs wird nicht lange anhalten, aber es sollte lange genug sein, um Euch zu helfen, durch das Brachland zu reisen.", completion = "Gut. Geht mit Agammagans Geist als Anführer, &lt;Volk&gt;. Kehrt zu mir zurück, wenn Ihr mehr von Agammagans Magie benötigt.", rewards = "Ihr erlernt:\n\nGeist des Windes"},
[890] = {title = "Die verloren gegangene Lieferung", objective = "Bringt Werftmeister DizzywigGazlowes Geschäftsbuch.", description = "Ich warte schon eine Ewigkeit auf meine letzte Warenlieferung aus Booty Bay! Ich bin mir ziemlich sicher, dass die Seeräuber sie gestohlen haben; würdet Ihr wohl, nur um sicher zu sein, zu den Docks gehen und Dizzywig fragen, ob meine Waren vielleicht ohne mein Wissen bereits ins Lagerhaus gebracht wurden?\n\nHier, nehmt mein Geschäftsbuch mit zu Dizzywig, damit er meine Inventaraufzeichnungen mit seinen Büchern gegenprüft.", progress = "Waren, die mit dem nächsten Schiff verschickt werden sollen, <Name>?", completion = "Ah, Gazlowe hat Euch geschickt, was? Einen Moment, ich überprüfe das kurz und vergleiche es mit meinen eigenen Büchern, um sicherzustellen, dass ich Gazlowes Lieferung nicht an den falschen Empfänger geschickt habe.\n\nIch wette, er wartet schon brennend auf die Stiefel von Drizzlek...", rewards = "Ihr bekommt:\n\n"},
[891] = {title = "Die Kanonen von Northwatch", objective = "Kapitän Thalo'thas Brightsun aus Ratchet möchte, dass Ihr 10 Medaillen von Theramore sammelt und Captain Hellstieg, Kanonier Knoch und Kanonier Hecksler tötet.", description = "Wieder ist ein Schiff meiner Flotte diesen übereifrigen Menschen der Feste Northwatch in die Hände gefallen!\n\nMan muss sich um diese Bastarde kümmern. Ihr Verfolgungswahn hat sie in eine Art Raserei versetzt. Diese schießwütigen, rücksichtslosen Rüpel schießen auf alles, was sich bewegt.\n\nReist gen Süden entlang der Händlerküste zur Feste und belagert ihre Streitkräfte. Bringt mir die Medaillen ihrer Soldaten als Beweis. Und erschlagt um meiner Flotte willen Captain Hellstieg und ihre übereifrigen Kanoniere!", progress = "Meine Flotte ist in Gefahr, solange Captain Hellstieg und ihre verdammten Kanoniere von der Feste Northwatch aus feuern. Ich möchte, dass auch ihre Soldaten dafür bezahlen. Füllt meine Hände mit Medaillen ihrer Toten, damit ich weiß, dass meine gefallenen Freibeuter gerächt sind.", completion = "Endlich, die Kanonen der rechtschaffenen Allianz wurden zum Schweigen gebracht. Ihr sollt für Eure Hilfe belohnt werden, &lt;Name&gt;.\n\nWenden wir uns jetzt der traurigen Aufgabe zu, die Körper der Gefallenen zu bergen...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFreibeutermusketeSeebären-Kniehosen\n\nIhr bekommt außerdem:\n\n"},
[892] = {title = "Die verloren gegangene Lieferung", objective = "Bringt Gazlowe in Ratchet sein Geschäftsbuch zurück.", description = "Laut meinen Aufzeichnungen ist alles in Ordnung, <Name>. Geht zurück und sagt Gazlowe, dass er wohl Pech gehabt hat. Es würde mich nicht überraschen, wenn sich die Piraten seine Waren geschnappt hätten.\n\nIch kann leider nicht mehr für ihn tun. Oh... Ihr könnt ihm allerdings sagen, dass ich ein paar Dinge aus Undermine für ihn habe, falls er die Zeit findet, sie abzuholen.", progress = "Also, was hat Dizzywig gesagt?", completion = "Keine Chance, was? Dann müssen es wohl die Freibeuter gewesen sein... Dizzywig ist ein aufrichtiger Kerl, er würde mich nicht auf diese Weise hintergehen. Immerhin steht er auf meiner Gehaltsliste.\n\nDann müssen wohl noch ein paar Sachen abgeholt werden, &lt;Name&gt;. Was meint Ihr?", rewards = "Ihr bekommt:\n\n"},
[893] = {title = "Ausgewählte Waffen", objective = "Bringt Tatternack Steelforge im Camp Taurajo im Brachland einen Grimmhauerrückenstecher, einen verkohlten Grimmhauerzauberstab und einen Grimmhauerkriegsschild.", description = "Die Stacheleber des Grimmhauerstamms im Süden, hinter dem Feld der Riesen, haben keine erfahrenen Schmiede, soweit ich weiß, aber Sie haben anscheinend begonnen, stabilere Waffen zu entwickeln. Ich hätte gern ein paar verschiedene Arten davon, um etwas über ihre Techniken zu erfahren, so möglich.\n\nWenn Ihr der Horde Ehre bringen wollt, dann bringt mir Exemplare von ihren Waffen. Besorgt mir einen Dolch von ihren Schleichern, einen Zauberstab von ihren Sehern und einen Schild von ihren Kriegsberserkern. Das sollte reichen!", progress = "Ich habe ebenso meine Zweifel daran, dass die jämmerlichen Stacheleber irgendeine Stufe auf dem Gebiet der Schmiedekunst erreichen können, aber der Kriegshäuptling hat es mir befohlen, also werde ich so viel wie möglich über den Grimmhauerstamm in Erfahrung bringen.\n\nIch hatte schon niederere Aufgaben, und ich tue es bereitwillig, wenn es den Orcs hilft.", completion = "Ausgezeichnet, das sind wirklich ausgezeichnete Exemplare.\n\nDie Stacheleber sind doch weiter, als ich erwartet hatte.\n\nHier, &lt;Klasse&gt;, nehmt das und verschwindet. Ich sollte mir diese Waffen näher ansehen. Vielleicht haben wir unsere Feinde unterschätzt und das ist ein Fehler, den wir uns nicht leisten können.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDemolierhammerImmerscheinlaterne\n\nIhr bekommt außerdem:\n\n"},
[894] = {title = "Samophlang", objective = "Verschafft Euch Zugang zur Steuerkonsole in der Forschungseinrichtung der Venture Company.\n\nBereitgestellter Gegenstand: \n", description = "Die Venture Company hat weit nördlich von hier, südwestlich des Schlickermoores, eine kleine Forschungseinrichtung errichtet. Was die Leute dort tun, weiß ich nicht genau, aber ich habe herausgefunden, dass sie dort mit etwas experimentieren, das 'Samophlang' genannt wird.\n\nWas zum Teufel ist ein Samophlang? Na ja, was immer es auch ist, ich möchte es untersuchen, also brauche ich jemanden, der eines beschafft.\n\nIch habe ein Exemplar der Bedienungsanleitung für ihr Steuersystem in die Finger bekommen; Ihr solltet also herausfinden können, wie man das Samophlang daraus entfernt.", progress = nil, completion = "Eine Vielzahl von Knöpfen, Hebeln und blinkenden Lampen sind etwas ungeordnet auf der Oberfläche der Steuerkonsole angebracht. Eine kleine Anzeige deutet darauf hin, dass die Apparatur momentan optimal funktioniert und dass die Ventile eins bis drei derzeit geöffnet sind. Rechts oben an der Seite der Steuerkonsole befindet sich ein kleines Schlüsselloch.", rewards = "Ihr bekommt:\n\n"},
[895] = {title = "GESUCHT: Baron Küstenschipper", objective = "Bringt Gazlowe in Ratchet Baron Küstenschippers Kopf.", description = "GESUCHT!\n\nBaron Küstenschipper, Kapitän der GNADENLOS\n\nCaptain Küstenschipper aus Gilneas befehligt Schiffe der Südmeerfreibeuter und wird wegen Piraterie GESUCHT. Seine Überreste müssen in noch erkennbarem Zustand sein!\n\n- Gazlowe", progress = "Was geht ab? Kann ich Euch irgendwie helfen? Habt Ihr Waren zu verschiffen? Oder vielleicht einen Ingenieursjob?", completion = "Ahhhh!!! So eine Art Geschäft also. Wisst Ihr, ich habe die GNADENLOS mal auf offener See gesehen. Furcht erregendes Schiff, oder heißt das Boot... diese Matrosen sind irgendwie anders!\n\nEgal, wie die so übers Wasser gleitet, das war schon sehenswert. Ich bin nur froh, dass ihr berüchtigter Captain keine Gefahr mehr für meine Schiffe ist.", rewards = "Ihr bekommt:\n\n"},
[896] = {title = "Des Minenarbeiters Vermögen", objective = "Beschafft Euch von einem der Vorarbeiter oder Vollstrecker der Venture Company den Katzenaugensmaragd und bringt ihn zu Dizzywig in Ratchet.", description = "Als Werftmeister eines so geschäftigen Hafens wie Ratchet habe ich mein Ohr immer am Puls der Zeit. Ich weiß alles über den Verkehr von Waren und Geld zwischen hier und Booty Bay.\n\nDie jüngste Neuigkeit, die ich erfahren habe, betrifft die Felsadermine der Venture Company nordöstlich des Schlickermoores. Einer der Minenarbeiter hat dort einen faustgroßen Smaragd gefunden. Ich kenne ein paar Käufer, die sich die Finger nach so etwas ablecken würden... und ich würde bei einem Verkauf Halbe-Halbe machen.", progress = "Wenn wir nur wüssten, welcher der Minenarbeiter den Smaragd gefunden hat, wäre das der reinste Spaziergang...", completion = "Seht Euch nur an, wie riesig das Ding ist, &lt;Name&gt;! Wir sind reich! Mal sehen, wenn man nach dem in Undermine gültigen Kurs für Edelsteine geht, sollte ich Euren Anteil berechnen können - fünfzig Prozent, selbstredend!\n\nAlso, dann sehen wir mal... Ich denke, damit sollten wir quitt sein. Es war mir ein Vergnügen, Geschäfte mit Euch zu machen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nEin Sack Münzen"},
[897] = {title = "Der Ernter", objective = "Bringt den Ernterkopf zu Jorn Skyseer.", description = "Diese seltsame, insektenartige Kreatur scheint außerhalb der natürlichen Ordnung zu stehen, so als würde sie nicht ins Brachland gehören.", progress = "Ihr wirkt verstört, <Name>. Wie läuft Euer Unterricht im Brachland? Seid Ihr auf etwas Beunruhigendes gestoßen?", completion = "Ich kann Euch nichts über die Natur dieser Bestie sagen, denn ihr Geist hat sie verlassen. Aber wie Ihr schon vermutet habt, gehört sie nicht ins Brachland. Ich fürchte, sie ist Vorbote einer düsteren Zukunft für unser Volk...\n\nIhr solltet Euch bereitmachen und lasst uns hoffen, dass die Zeit das Rätsel dieser Kreatur löst.", rewards = "Ihr bekommt:\n\n"},
[898] = {title = "Aus der Gefangenschaft befreit", objective = "Begleitet Gilthares Firebough sicher zurück zu Kapitän Brightsun in Ratchet.", description = "Endlich! Jemand rettet mich!\n\nIch kann es nicht glauben, dass Ihr an den Wachen vorbeigekommen seid. Diese Fanatiker aus Theramore müssen verrückt sein. Sie haben unser Schiff versenkt und mich, den einzigen Überlebenden, eingesperrt. Sie nannten mich ihren Feind und eine Gefahr für die Allianz.\n\nIch! Eine Gefahr für diesen Riesenschwindel, den sie Allianz nennen? Ich war Decksmann auf einem Fuseltransporter zwischen Ratchet und Booty Bay.\n\nGenug geredet. Helft Ihr mir, zurückzukommen nach Ratchet, ja? Lasst es mich wissen, wenn Ihr bereit seid, hier auszubrechen.", progress = "Ja?", completion = "Wir dachten, Firebough wäre längst tot!\n\nEure Heldentat hat Euch einen Ehrenplatz unter den Thalo'dan-Freibeutern eingebracht, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchnallenstiefelNietenstulpen\n\nIhr bekommt außerdem:\n\n"},
[899] = {title = "Von Hass zerfressen", objective = "Bringt Mankrik in Crossroads 60 Stacheleberhauer der Borstennacken.", description = "Vielleicht kennt Ihr diesen Schmerz der Ungewissheit, <Klasse>, vielleicht auch nicht. Doch wisset: Ich stehe hier jeden Tag, vom Aufgang der Sonne bis zu ihrem Untergang, und suche den Horizont nach diesen Monstern ab. Ich habe jeden Schweinemenschen getötet, den ich seitdem gesehen habe, doch der Durst nach ihrem Blut ist noch lange nicht gestillt. Vielleicht hätte ich mich nach Taurajo begeben sollen, statt nördlich nach Crossroads.\n\nIhr, <Klasse>, könntet mir helfen.\n\nTötet sie. Tötet so viele Ihr könnt und bringt mir ihre Hauer, dann werden wir ihren Tod miteinander feiern.", progress = "Die Stacheleber werden dafür bezahlen, <Name>. Ich schwöre es.", completion = "&lt;Klasse&gt;, Ihr habt meine Aufgabe ernst genommen und dafür danke ich Euch.\n\nMein Verlangen nach Rache ist zwar noch nicht gestillt, aber ich kann immerhin wieder lächeln, da ich sehe, dass auch die Stacheleber leiden mussten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nEberjägercapeGraslandschärpe\n\nIhr bekommt außerdem:\n\n"},
[900] = {title = "Samophlang", objective = "Schließt das Treibstoffzufuhrventil, das Regelventil und das Hauptsteuerventil, und benutzt dann noch einmal die Steuerkonsole.", description = "Die drei Steuerventile sind momentan geöffnet. Die verschiedenen Anzeigen der Steuerkonsole führen Euch zu der Annahme, dass man sie zunächst schließen muss, bevor der Apparat ausgeschaltet werden kann.", progress = "Blinkende Lampen auf der Steuerkonsole deuten darauf hin, dass die Hauptsteuerventile noch nicht geschlossen wurden.", completion = "Die Lampen erlöschen, sobald die drei Steuerventile geschlossen werden. Grüne Lampen wechseln langsam zu gelb, und der Schalter zur Steuerung des Apparats kann jetzt betätigt werden. Da alle Ventile geschlossen sind, könnt Ihr ihn ausschalten.", rewards = "Ihr bekommt:\n\n"},
[901] = {title = "Samophlang", objective = "Besorgt Euch bei Tüftler Sniggles den Konsolenschlüssel, um damit die Steuerkonsole zu öffnen.", description = "Da der Apparat jetzt ausgeschaltet ist, kann die Steuerkonsole geöffnet und das Samophlang entfernt werden. Alles andere sollte unangetastet bleiben und Ihr benötigt jetzt nur noch den Schlüssel, mit dem die Konsole geöffnet werden kann.", progress = "Die Lampen der Konsole leuchten schwach und sämtliche Anzeigen und Skalen stehen auf Null, alles ist im Leerlauf.", completion = "Kaum wird der Schlüssel herumgedreht, öffnet sich die Steuerkonsole. Oben auf der Konsole erlischt eine rote Lampe und das Terminal führt keinen Strom mehr.", rewards = "Ihr bekommt:\n\n"},
[902] = {title = "Samophlang", objective = "Bringt das Samophlang zu Sputtervalve in Ratchet.", description = "Nach dem Öffnen der Front der Steuerkonsole zeigt sich ein dichtes Gewirr aus Kabeln, Schläuchen und anderen seltsamen, mechanischen Objekten - die meisten davon scheinen keinen praktischen Nutzen zu haben. Ihr schiebt sie beiseite und arbeitet Euch tiefer in die Konsole vor, bis Ihr schließlich das Samophlang gefunden habt. Mit einem Ruck zieht Ihr es aus der Halterung.", progress = "Ihr seid zurück, <Name>! Habt Ihr das Samophlang?", completion = "Das ist... äh... interessant... wirklich. Ich werde es an die Tüftlerverband-Zentrale in Undermine schicken. Ich bin sicher, dass sie dort etwas damit anfangen können, nachdem sie es vorsichtig auseinander genommen und erforscht haben.\n\nAber vielleicht werde ich auch zuerst selbst einen kleinen Blick darauf werfen...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nIngenieurhammerSchweißerschild\n\nIhr bekommt außerdem:\n\n"},
[903] = {title = "Streuner des Brachlandes", objective = "Besorgt für Sergra Darkthorn in Crossroads 7 Streunerklauen von den Savannenstreunern.", description = "Es ist nun an der Zeit, etwas zu jagen, das sich wirklich wehrt. Die Streuner des Brachlandes sind von zäher Art. Zäh, erfinderisch, listig... und tödlich. Ihr findet sie zwischen den hohen Gräsern. Ihr werdet viele südwestlich von Crossroads finden.\n\nSeid vorsichtig, wenn Ihr sie jagt, <Name>, oder Ihr werdet feststellen, dass Ihr nicht mehr Jäger, sondern Gejagter seid.", progress = "Wie läuft Eure Jagd, <Name>? Habt Ihr die Streuner gefunden?", completion = "Ah, ich sehe, Ihr wart damit beschäftigt, im Gras zu lauern und Streuner zu jagen. Glaubt Ihr, dass es an der Zeit ist, einem Champion unter ihnen gegenüberzutreten?", rewards = "Ihr bekommt:\n\n"},
[905] = {title = "Die wütenden Sensenklauen", objective = "Tötet Bluthornraptoren und nehmt ihre Federn mit. Benutzt die Federn bei den drei Sensenklauennestern. Kehrt zu Sergra Darkthorn in Crossroads zurück.", description = "Tja, <Name>, die Jagd wird schwieriger. Jetzt müsst Ihr Eure Beute besiegen und dann Euren Weg zu ihrem Unterschlupf finden.\n\nJagt die Bluthornraptoren im Süden. Erledigt sie und nehmt Euch die Federn, die sie tragen. Legt die Federn in die Sensenklauennester südwestlich der brackigen Oase. Zeigt ihren Brüdern, dass Ihr sie nicht fürchtet!", progress = "Wart Ihr bei den Nestern, <Name>?", completion = "Ihr wart also bei den Nestern und habt die Federn Eurer Beute dort abgelegt. Dafür war zweifellos eine gehörige Portion Mut notwendig.\n\nFühlt Ihr Euch ein bisschen stärker, &lt;Name&gt;? Denn Ihr seht stärker aus als bei Eurem ersten Besuch hier. Ich glaube, das Brachland zeitigt Erfolg bei Euch.", rewards = "Ihr bekommt:\n\n"},
[906] = {title = "Verräter in den eigenen Reihen", objective = "Bringt Loks Kopf zu Thork in Crossroads im Brachland.", description = "Bringt Loks Kopf zu Thork in Crossroads, <Volk>. <schnaubt> Er sollte ohne Worte wissen, was meinem Stamm zugestoßen ist - ha, nicht dass er denken würde, Quetschzahn hätte bei <schnaubt> solchen Dingen geholfen. Aber ich bin sicher, er wird Euch für das Ausführen einer solch großen Tat belohnen. <schnaubt>\n\nIch werde Euch auch weiterhin mit Agammagans Macht segnen, solange ich in diesem Käfig verbleibe, <Volk>. Bis dann, lebt wohl.", progress = "Ja, was gibt's?", completion = "Ihr habt den Anführer der Grimmhauer gefunden und eigenhändig getötet, &lt;Name&gt;? Erstaunlich.\n\nMir fehlen die Worte, aber das bedeutet nicht, dass ich nicht dankbar bin. Die Leute von Crossroads sollten Respekt vor Eurer Kraft haben.\n\nIch muss gestehen, dass ich dachte, der Anführer all dieser Überfälle auf unsere Nachschublinien wäre ebenfalls ein Stacheleber. Nochmals danke, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRindenhüllentunikaTrockenmoostunika\n\nIhr bekommt außerdem:\n\n"},
[907] = {title = "Wütende Donnerechsen", objective = "Bringt das Blut von 3 Donnerechsen ins Camp Taurajo zu Jorn Skyseer.", description = "Nun denn, <Name>, jetzt müsst Ihr den großen Donnerechsen gegenübertreten. Diese Bestien sind so groß, dass der Boden erbebt, wenn sie über die Ebenen stampfen. Seid vorsichtig, wenn Ihr gegen sie kämpft, denn ein einziger falscher Schritt, und schon findet Ihr Euch unter ihren Füßen wieder.\n\nIhr findet die Donnerechsen im südlichen Brachland. Man kennt sie als Sturmschnauzen, Sturmechsen und Donnerköpfe. Kehrt zu mir zurück, nachdem Ihr sie überwältigt habt.", progress = "Sind die Donnerechsen bezwungen, <Name>?", completion = "Es ist gut, Euch mit dem Beweis Eures Sieges zurückkehren zu sehen. Und es ist schön zu wissen, dass Ihr es geschafft habt, Eure Knochen dabei nicht zu brechen.", rewards = "Ihr bekommt:\n\n"},
[908] = {title = "Inmitten der Ruinen", objective = "Bringt den Fathom-Kern zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale.", description = "Die Twilight-Hammer sind in die Mondschreinruinen der Blackfathom-Tiefe eingezogen. Ihre Gegenwart kann nur dazu dienen, die Elemente gegen uns aufzubringen. Wenn dem kein Einhalt geboten wird, gehört ihnen diese Region bald ganz und gar.\n\n<Name>, geht nach Blackfathom und findet den Fathom-Stein der Ruinen. Er dürfte irgendwo in deren Nähe im Wasser liegen. Darin ist ein Fathom-Kern. Das ist ein Gerät, das, wenn man es richtig abliest, eine Aufstellung über alle Aktivitäten der Elementare liefert. Wenn ich es habe, können der Irdene Ring und ich vielleicht etwas tun, um sie aufzuhalten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[909] = {title = "Baron Aquanis", objective = "Bringt die seltsame Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale.", description = "Der besiegte Wasserelementar hat eine seltsame Wasserkugel zurückgelassen. Ihr vermutet, dass das Objekt die Kreatur irgendwie mit Energie versorgte. In der Kugel schwappt eine faulig aussehende Wassergestalt herum. Die Kugel selbst zeigt sich unbeeindruckt von jeder äußerlichen Krafteinwirkung.\n\nWenn irgendwer aus diesem Gegenstand schlau wird, wäre das wohl Je'neu Sancrea vom Irdenen Ring. Er befindet sich im Zoram'gar-Außenposten der Horde in Ashenvale.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesetzlosensäbelHexenfinger\n\nIhr bekommt außerdem:\n\n"},
[910] = {title = "Unten an den Docks", objective = "Bringt Euren Schützling in die Docks von Ratchet im Brachland.", description = "Ich hab' Geschichten gehört von riesigen Schiffen, die zwischen Ratchet und Booty Bay hin- und hersegeln. Es wäre so toll, auf dem Ozean zu segeln und fantastische Seeschlachten erleben zu können. Wenn ich erwachsen bin, werde ich vielleicht auch ein mächtiger Seefahrer der Horde!\n\nKannst du mir bitte die Docks von Ratchet zeigen? Ich verspreche dir, auch nicht ins Wasser zu fallen oder Ärger zu machen. Ich will nur einmal die großen Schiffe sehen und das salzige Meerwasser riechen!", progress = nil, completion = "Wow, das Meer ist RIESIG! Da sind so viele Seemöwen und anderes Zeug - Und es ist wirklich so laut und hektisch, wie ich es mir immer vorgestellt habe. Sogar Piraten gibt es da - der Hammer!\n\nDanke, dass du mich mit nach Ratchet genommen hast, &lt;Name&gt;. Das war einfach nur toll!", rewards = "Ihr bekommt:\n\n"},
[911] = {title = "Das Tor zur Grenze", objective = "Begleitet Euren Schützling zum Mor'shan-Schutzwall im nördlichen Teil des Brachlands, kurz bevor man Ashenvale betritt.", description = "Sie sagen Ashenvale sei das neue Grenzland und das der Mor'shan-Schutzwall im Brachland das Tor dorthin ist. Es wäre so toll ein Pionier zu sein und alles was man zum überleben braucht in der Wildnis zu sammeln! Sie sagen das dies der Ort ist, an welchem in Zukunft die Horde und die Allianz ihre Kämpfe austragen werden. Ich möchte unbedingt dahin!\n\nKönnen wir bitte zum Mor'shan-Schutzwall gehen, ich würde so gerne mal das Grenzland sehen! Ich möchte sehen wie die Horde diese stinkenden Nachtelfen dort vertreibt.", progress = nil, completion = "Wow, in Ashenvale kann man wahre Abenteuer erleben! Hast du schon einmal in Ashenvale gekämpft, &lt;Name&gt;? Wenn ich erstmal erwachsen und ein Held bin, werde ich nach Ashenvale gehen und für die Ehre der Horde kämpfen!\n\nDanke, dass du mir das Grenzland gezeigt hast, &lt;Name&gt;. Du bist der Beste.", rewards = "Ihr bekommt:\n\n"},
[912] = {title = "Splittersteintroggverkleidung", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWissen: Splittersteintroggverkleidung"},
[913] = {title = "Der Ruf des Donnerfalken", objective = "Sucht und erschlagt einen Donnerfalken und bringt Jorn Skyseer in Taurajo seine Flügel.", description = "Der Donnerfalke, <Name>, ist eine ungestümes Wildtier. Es ist an der Zeit für Euch, ihm gegenüberzutreten. Ihr müsst herausfinden, wo er umherstreift, und mir seine Flügel als Beweis für Eure erfolgreiche Jagd bringen.\n\nWenn Ihr das tut, wird Eure Zeit mit mir sich ihrem Ende nähern.", progress = "Ist es vollbracht? Habt Ihr den Donnerfalken getötet?", completion = "Ihr solltet, ebenso wie der Donnerfalke, stolz sein. Ihr habt jeden Feind besiegt, gegen den wir Euch geschickt haben, und Ihr habt es mit Stärke, Mut und Ehre geschafft.\n\nAber Euer Weg ist noch nicht zu Ende, &lt;Name&gt;. Ihr werdet nämlich herausfinden, dass wahre Jäger auf ewig streben, auf ewig mit dem gleichen Stolz, den Ihr mir gezeigt habt, ihren Weg gehen.\n\nNun ist es an der Zeit, nach vorn zu blicken.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKobaltblauer RundschildWindreiterstab\n\nIhr bekommt außerdem:\n\nHandschuhe des Mondes"},
[914] = {title = "Anführer der Giftzähne", objective = "Bringt die Edelsteine von Kobrahn, Anacondra, Pythas und Serpentis nach Thunder Bluff zu Nara Wildmane.", description = "Die Druiden in den Höhlen des Wehklagens, die Druiden des Giftzahns, sind eine Verirrung der Natur. Einst gehörten sie einem Orden edler Druiden an, deren Plan es war, das Brachland zu heilen, doch jetzt trachten sie danach, das Land ihren eigenen verderbten Träumen gleichzumachen.\n\nDie Druiden des Giftzahns haben vier Anführer, und jeder besitzt einen Traumedelstein. Selbst jetzt noch verfolgen mich ihre Gesichter! Besiegt die Anführer und bringt mir ihre Edelsteine, dann wird das Brachland endlich wieder Frieden haben.\n\nGeht, <Name>. Sie halten sich tief in den Höhlen des Wehklagens verborgen.", progress = "Mich verfolgen die Erinnerungen an meine Alpträume, <Name>. Habt Ihr die Anführer der Druiden des Giftzahns besiegt und ihre Edelsteine in Euren Besitz gebracht?", completion = "Ihr habt es geschafft, &lt;Name&gt;. Ihr habt die Anführer der Druiden des Giftzahns getötet. Jetzt werden meine Träume nicht mehr von ihren Fratzen heimgesucht und Ihr habt uns geholfen, das Brachland vor einer schrecklichen Zukunft zu bewahren.\n\nIch danke Euch, &lt;Name&gt;. Ich danke Euch im Namen der Druiden von Thunder Bluff, des ganzen Landes und auch in meinem eigenen Namen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMondsichelstabFlügelklinge\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[915] = {title = "Lecker Eis", objective = "Besorgt für Euren Schützling etwas Erdbeereis. Der Kleine scheint die Marke 'Skippis Eiscreme' zu bevorzugen.", description = "EISCREME! Oh, kannst du mir bitte, bitte, bitte, etwas Eiscreme besorgen? Am liebsten mag ich Erdbeere und es gibt einfach kein besseres Erdbeereis als das von Skippi. Das ist mein liebstes Eis auf der ganzen Welt!\n\nFrüher gab es das immer auf der Rennstrecke in der schimmernden Ebene, aber ich habe mal gehört, dass man es jetzt auch in der Stadt kaufen kann. Kriege ich bitte eins? Bitte? Am liebsten Skippis Eiscreme.", progress = "Ich wünschte sie würden mehr als nur Erdbeereis herstellen, aber Gott sei Dank ist Erdbeere meine Lieblingssorte.", completion = "Mmmmmmmmm! Ich liebe Erdbeereis! Wenn Skippi und Gunni eines können, dann ist das Erdbeereis machen!\n\nVielen Dank, &lt;Name&gt; - Das ist die beste Süßigkeit seit langem!", rewards = "Ihr bekommt:\n\n"},
[916] = {title = "Waldwebergift", objective = "Bringt Gilshalan Windwalker in Aldrassil 10 Waldwebergiftbeutel.", description = "Ich kam nach Shadowglen, um hier die Waldweberspinnen zu beobachten, die in der Schattenweberhöhle leben. Sie sind mit einer wesentlich kleineren Spinnenart verwandt. Ich glaube, der Weltbaum hat einen nicht unerheblichen Effekt auf sie und ich hätte gern ein paar Exemplare von ihnen, um dies zu belegen.\n\nAls Erstes hätte ich gern etwas von ihrem Gift. Sammelt Giftbeutel der Waldweberspinnen, die in und um die Schattenweberhöhle herum zu finden sind. Dann kann ich ihren und das Gift ihrer kleineren Verwandten auf Gemeinsamkeiten hin untersuchen.", progress = "Habt Ihr die Giftbeutel, <Name>?", completion = "Danke, &lt;Name&gt;. Sobald ich wieder in Darnassus bin, werde ich das Gift dieser Drüsenbeutel mit dem Gift anderer Spinnen vergleichen. Ich glaube, dass er Eigenschaften besitzt, die etwas mit dem kürzlichen Wachstumsschub unseres neuen Weltbaums zu tun haben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDistelholzschlägelDistelholzdolchDistelholzstabDistelholzklinge\n\nIhr bekommt außerdem:\n\n"},
[917] = {title = "Waldweberei", objective = "Bringt Gilshalan in Aldrassil ein Waldweberei.", description = "Jetzt, da ich das Spinnengift habe, hätte ich gern auch ein paar lebende Exemplare, um sie zu studieren. Leider kann ich Euch nicht darum bitten, eine lebende Riesenspinne für mich einzufangen, <Klasse>. Eine Riesenspinne kann ich allein sowieso nicht bewältigen!\n\nWenn Ihr mir allerdings ein unausgebrütetes Ei besorgen könntet, wäre es viel einfacher, lebende Exemplare zu bekommen, und ich könnte dafür sorgen, dass die noch nicht ausgeschlüpften Exemplare ordentlich unter Verschluss gehalten werden.\n\nTief in der Schattenweberhöhle gibt es angeblich ein Nest. Bitte, beschafft mir ein Ei aus diesem Nest und bringt es mir.", progress = "Wart Ihr in der Schattenweberhöhle, <Name>? Habt Ihr ein Spinnen-Ei gefunden?", completion = "Ah, sehr gut. Ich lasse dieses Ei und das Gift nach Darnassus bringen und kehre nach dort zurück, sobald ich meine Studien hier abgeschlossen habe. Ich rechne fest damit, anhand dieser Exemplare eine Menge herauszufinden, &lt;Name&gt;. Ihr wart mir eine große Hilfe.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWaldlandschildWaldland-TunikaWaldland-Roben\n\nIhr bekommt außerdem:\n\n"},
[918] = {title = "Bäumlingssamenkörner", objective = "Bringt Denalan am Al'Amethsee 8 Bäumlingssamenkörner.", description = "Die Bäumlinge von Teldrassil sind Naturelementare. In ihnen spiegelt sich in gewisser Weise die natürliche Ordnung von Flora und Fauna unseres großen Baums wider.\n\nDaher ist es höchst beunruhigend zu sehen, dass die Bäumlinge so wütend geworden sind.\n\nIch glaube, es hat etwas mit dem Erdboden zu tun. Ich habe mich viel mit verschiedenen Düngemethoden für Pflanzen beschäftigt und würde sie gern an Bäumlingssamenkörnern ausprobieren. Würdet Ihr bitte in der Gegend des Al'Amethsees ein paar Bäumlingssamenkörner sammeln und mir bringen?", progress = "Habt Ihr die Samen? Ich kann es kaum erwarten, sie einzupflanzen.", completion = "Ihr habt sie. Das ist gut!\n\nIch werde diese Samen in einer speziell vorbereiteten Erde einpflanzen. Ich glaube, aus den Samen werden Bäumlinge wachsen, die viel sanftmütiger sind. Vielleicht könnt Ihr Euch später das Ergebnis ansehen!", rewards = "Ihr bekommt:\n\nWaldpilzkappe"},
[919] = {title = "Bäumlingssprossen", objective = "Bringt Denalan am Al'Amethsee 12 Bäumlingssprossen.", description = "Kleine Bäumlinge sprießen rund um das Wasser des Al'Amethsees. Ich fürchte, dass man diesen Schösslingen nicht mehr helfen kann - wir sollten versuchen, sie auszureißen, bevor sie groß genug sind, um Probleme zu bereiten.\n\nWenn Ihr auf Euren Wanderungen um den See Bäumlingssprossen seht, reißt sie bitte aus. Helft dabei, unser Land rein zu halten!", progress = "Hallo, <Name>. Habt Ihr in der Nähe der Seen Schösslinge gefunden?", completion = "Sind das viele! Ich fürchte, sie verbreiten sich gefährlich schnell. Hoffentlich kann ich den Grund dafür finden, warum sie so besudelt sind.\n\nDanke für Eure Hilfe, &lt;Name&gt;. Dank Euch ist das Land wieder viel sauberer.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGarten-HandschuheGraustein-Armschienen\n\nIhr bekommt außerdem:\n\n"},
[920] = {title = "Tenarons Einladung", objective = "Sprecht in Shadowglen über den Dächern von Aldrassil mit Tenaron Stormgrip.", description = "Ihr seid <Name>, nicht wahr? Ich hörte, dass Tenaron nach Euch gefragt hat. Ihr findet ihn in dem am höchsten gelegenen Raum in Aldrassil.\n\nWir mögen zwar ein langes Leben haben, aber Ihr solltet ihn dennoch nicht allzu lang warten lassen.", progress = nil, completion = "Ah, &lt;Name&gt;. Ich hatte gehofft, Ihr würdet meiner Einladung bald Folge leisten. Ich habe eine wichtige Aufgabe für Euch.", rewards = "Ihr bekommt:\n\n"},
[921] = {title = "Krone der Erde", objective = "Füllt die Kristallphiole und bringt sie Tenaron Stormgrip über den Dächern von Aldrassil.", description = "Es ist an der Zeit herauszufinden, was Euer Schicksal ist, <Name>. Doch bevor Ihr bereit seid, in die Welt hinter unseren verzauberten Wäldern hinauszuziehen, gibt es noch vieles, das Ihr über unsere jüngste Vergangenheit lernen müsst.\n\nSeit der Schlacht am Berg Hyjal hat sich für unser Volk so viel verändert. Nordrassil ist nur noch ein Schatten ihres früheren Selbst, ihre Macht wurde benutzt, um Archimonde in die Knie zu zwingen und die Brennende Legion zurückzutreiben ...\n\nIhr müsst eine Aufgabe erledigen. Geht zum Mondbrunnen nördlich von Aldrassil und bringt mir eine Phiole mit Wasser daraus.", progress = "Die Mondbrunnen enthalten das Wasser des Brunnens der Ewigkeit, die uralte Quelle der Magie, die so viel Schrecken über unsere Welt gebracht hat.\n\nDie Druiden nutzen ihre Eigenschaften und die Schildwachen verehren die Brunnen als Schreine der Elune, doch ist Zauberei allen gleichermaßen verboten.", completion = "Jetzt kennt Ihr also den ersten Teil der Geschichte um die Auswirkungen der Schlacht am Berg Hyjal. Es gibt noch so viel mehr zu erzählen, und die Aufgabe, die Ihr hier begonnen habt, wird Euch den Rest Eurer Reise durch Teldrassil und nach Darnassus begleiten.", rewards = "Ihr bekommt:\n\n"},
[922] = {title = "Rellian Greenspyre", objective = "Bringt Rellian Greenspyre in Darnassus ein Bäumlingssamenkorn.", description = "<Name>, würdet Ihr wohl eines der Samenkörner, die Ihr mir besorgt habt, meinem Freund Rellian Greenspyre bringen? Er ist Druide in Darnassus, und bei unserem letzten Gespräch machte er deutlich, dass er an meiner Arbeit mit den Bäumlingen interessiert sei. Er hatte selbst ein paar Ideen und würde sich über ein Exemplar dieser Samenkörner sicherlich freuen.\n\nDanke, <Name>. Ihr wart mir eine große Hilfe. Ich hoffe, dass ich Euch eines Tages die Früchte meiner Arbeit zeigen kann.\n\nIhr findet Rellian normalerweise die Wege der Enklave des Cenarius in Darnassus entlangwandernd.", progress = "Hallo...\n\nKann ich Euch irgendwie helfen?", completion = "Ah, ein Bäumlingssamenkorn. Ich wollte schon immer eines davon haben, um Denalan bei seinen Studien zu unterstützen.\n\nLeider habe ich jedoch herausgefunden, dass viele der Bäumlinge eine Schädigung aufweisen und dass auch deren Samenkörner mit dieser Besudelung behaftet sind. Es ist mir nicht möglich, dies zu beheben.\n\nDenalan hat einen grünen Daumen mit Pflanzen. Er könnte ein Heilmittel für künftige Bäumlinge finden. Vielleicht ist er ihre einzige Hoffnung.", rewards = "Ihr bekommt:\n\n"},
[923] = {title = "Tumore", objective = "Bringt Rellian Greenspyre in Darnassus 5 moosartige Tumore.", description = "Bosheit wuchert in den Bäumlingen. Wir versuchen, die Ursache dafür zu finden, aber bis dahin... Aus Sorge um Teldrassils Sicherheit müssen wir alle Bäumlinge fällen, denen nicht mehr geholfen werden kann. Diejenigen, die die Gegend um den Wellspringsee im Norden von Teldrassil durchstreifen, sind am schlimmsten betroffen. Sie müssen ausgemerzt werden!\n\nVernichtet alle Bäumlinge, die Ihr dort findet, und sammelt die moosartigen Tumore, die auf ihnen wachsen. Bringt mir die Tumore, damit ich sie verbrennen kann.", progress = "Wart Ihr schon am Wellspringsee, <Name>? Habt Ihr dort Bäumlinge gejagt?", completion = "Gut gemacht! Diese Tumore sind ein Symptom der Bäumlingskrankheit. Sie sind mit einem Gift gefüllt, von dem wir unser neues Land säubern müssen.\n\nIch werde diese Tumore entsorgen. Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nStutzmesser"},
[924] = {title = "Die Dämonensaat", objective = "Nehmt einen fehlerhaften Kraftstein. Bringt ihn zum Altar des Feuers, bevor dessen Wirkung erlischt, und kehrt dann zu Ak'Zeloth zurück.", description = "Die Dämonensaat ist ein mächtiges Werkzeug der Brennenden Legion. Sie lebt in einer Höhle des Glutnebelgipfels, oberhalb eines dämonischen Altars des Feuers.\n\nIch habe Kraftsteine vorbereitet, die, wenn sie in der Nähe der Saat platziert werden, deren Verbindung zur Legion unterbrechen.\n\nNehmt einen Stein vom Tisch und bringt ihn zum Altar des Feuers oben auf dem Glutnebelgipfel. Reist nach Westen und bei der Weggabelung weiter nach Norden. Der Gipfel liegt zu Eurer Linken. Die sicherste Aufstiegsmöglichkeit zur Spitze bietet sich an der Nordseite.\n\nUnd beeilt Euch - die Energie des Steins nimmt mit der Zeit ab.", progress = "Die Dämonensaat existiert immer noch. Ich spüre ihre Macht...", completion = "Eure Aufgabe ist vollbracht. Ihr habt die Dämonensaat vernichtet, wie Neeru Euch geheißen hat. Aber das ist noch nicht das Ende...\n\nDie Vernichtung der Dämonensaat hat Wellen der Macht durch den Äther geschickt, Wellen unglaublicher Stärke. Ich habe sie gespürt und ich bin sicher, dass andere Wesen sie ebenfalls spürten. Andere, die sich fragen werden, warum man ihr Spielzeug zerbrochen hat...\n\nDoch was die Zukunft auch bringen mag, ich habe etwas für Euch. Neeru schickt es, sozusagen als Entlohnung. Und er bat mich, Euch zu danken.\n\nAlso - danke.", rewards = "Ihr bekommt:\n\nBansheerüstung"},
[925] = {title = "Cairnes Hufabdruck", objective = "Reist nach Thunder Bluff und versucht für Euren Schützling einen Hufabdruck von Cairne Bloodhoof zu ergattern.", description = "Ich habe gehört, dass Cairne Bloodhoof einer der größten Helden ist, die die Horde je gesehen hat. Wenn ich mal groß bin, möchte ich auch ein Held der Horde werden!\n\nKennst du Cairne, <Name>? Tust du mir einen gefallen? Kriege ich ein Autogramm von ihm? Ich weiß gar nicht, wie ich ihn ansprechen soll, und wahrscheinlich ist er sowieso viel zu beschäftigt, um mich zu beachten....aber was ist mit dir? Du bist doch genau wie er ein Abenteurer! Dir gibt er bestimmt ein Autogramm!\n\nBitte, <Name>. Bitte...", progress = "Als die Orcs alleine und ohne Freunde waren, hießen die Tauren Sie in einem fremden Land willkommen und teilten mit ihnen, ohne eine Gegenleistung zu erwarten. Das ist Ehre, <Name>.", completion = "WOW! Du hast wirklich Cairnes Hufabdruck für mich bekommen! Vielen, vielen Dank! Und wow... das ist ja sogar eine persönliche Nachricht für mich drauf! Ich wusste doch, dass er total cool ist und vielleicht kann ich ihm sogar eines Tages selber danken... wenn auch ich ein Held der Horde bin!\n\nDu bist einfach der Beste, &lt;Name&gt;. Danke, dass du so gut zu mir bist.", rewards = "Ihr bekommt:\n\n"},
[926] = {title = "Fehlerhafter Kraftstein", objective = "Diese Steine sind von magischer Energie erfüllt, aber absichtlich fehlerhaft. Sie sind nicht sehr stabil, und sobald sie vom Tisch genommen werden, vernichten sie sich schnell selbst.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFehlerhafter Kraftstein"},
[927] = {title = "Das moosumschlungene Herz", objective = "Bringt Denalan am Al'Amethsee das moosumschlungene Herz.", description = "Das Herz von Schwarzmoos dem Stinker ist mit einem dunklen, öligen Moos bedeckt. Dass es sich wirklich um ein Herz handelt, kann man eigentlich nur daran erkennen, dass es langsam und rhythmisch schlägt... Ein Herzschlag, der sogar jetzt noch anhält.\n\nVielleicht würde Denalan dieses Herz gern einmal sehen.", progress = "<Name>! Habt Ihr etwas für mich?", completion = "Was ist das denn? Ein Bäumlingsherz??? Es ist mit widerlichem Moos bedeckt!\n\nDanke, dass Ihr es mir gebracht habt, &lt;Name&gt;. Ich werde das Herz untersuchen, und wenn ich Glück habe, finde ich heraus, was dies für eine Art Moos ist.", rewards = "Ihr bekommt:\n\n"},
[928] = {title = "Krone der Erde", objective = "Bringt Corithras Moonrage in Dolanaar das teilweise gefüllte Gefäß.", description = "Ich könnte Euch zwar noch so viel mehr über die Mondbrunnen und Teldrassil erzählen, doch leider muss ich Euch fortschicken. Corithras Moonrage erwartet Euch. Ich habe das Wasser der Phiole, die Ihr mir brachtet, in dieses Gefäß geschüttet, damit Ihr es ihm bringen könnt.\n\nFragt nach Corithras. Ihr findet ihn am Mondbrunnen in Dolanaar. Folgt der Straße südlich von Aldrassil, die aus Shadowglen hinausführt und dann weiter auf dem Kopfsteinpflaster in Richtung Westen.\n\nBleibt unbedingt immer auf der Straße, <Name>. Es gibt neuerdings ziemlich gefährliche Bestien in den Wäldern.", progress = "Seid gegrüßt, <Klasse>. Wem verdanke ich die Ehre Eures Besuchs?", completion = "Ah, ich verstehe. Tenaron schickt Euch. Nun denn, mir scheint, wir haben viel zu besprechen, viel zu tun und nur wenig Zeit dafür.\n\nWir sollten jetzt besser gleich beginnen.", rewards = "Ihr bekommt:\n\n"},
[929] = {title = "Krone der Erde", objective = "Füllt die Jadephiole und bringt sie Corithras Moonrage in Dolanaar zurück.", description = "Lasst mich Euch zunächst ein bisschen mehr von der Aufgabe erzählen, die Euch erwartet. Die Druiden in Darnassus verbrauchen das Wasser der Mondbrunnen Teldrassils, und deshalb muss ihr Mondbrunnen von Zeit zu Zeit wieder aufgefüllt werden. Ihr könnt mit diesen speziell gefertigten Phiolen Wasser aus den Mondbrunnen schöpfen.\n\nNehmt dieses Gefäß zum Mondbrunnen außerhalb von Starbreeze im Osten mit und füllt es mit Wasser. Kehrt dann zu mir zurück. Wenn Ihr Eure Aufgabe erledigt habt, erzähle ich die Geschichte da weiter, wo Tenaron aufgehört hat ...", progress = "Hallo, <Name>. Habt Ihr Eure Aufgabe erledigt?", completion = "Nach der Schlacht am Berg Hyjal waren wir wie verloren. Nordrassil lag unter einer Rauchwolke der Feuer, die darin loderten, und unsere Unsterblichkeit - die Essenz unseres Seins! - war dahin.\n\nIn dieser schwierigen Zeit wurde der Verräter aus seinem Gefängnis befreit und Shan'do Stormrage verschwand spurlos. Das war eine böse Zeit für uns alle.", rewards = "Ihr bekommt:\n\n"},
[930] = {title = "Die leuchtende Frucht", objective = "Bringt Denalan am Al'Amethsee die leuchtende Frucht.", description = "Unter den Wedeln dieser leuchtenden Pflanze befindet sich eine große, runde Frucht.\n\nDenalan würde diese Frucht bestimmt gern studieren, da seid Ihr Euch sicher.", progress = "<Name>, Ihr seht aus, als wolltet Ihr mir etwas sagen. Habt Ihr Neuigkeiten bezüglich der Bäumlinge?", completion = "Ihr habt das in Teldrassil gefunden? Interessant... eine exotische Frucht. Vielleicht sind ihre Samen von weither hierher gelangt. Vielleicht sogar aus Azeroth! Irgend etwas ist mit dieser Frucht... sie scheint sich auf sehr seltsame Art dem Erdboden Teldrassils angepasst zu haben.\n\nDanke, &lt;Name&gt;. Wenn Ihr mich jetzt bitte entschuldigen wollt, ich muss das hier näher untersuchen...", rewards = "Ihr bekommt:\n\n"},
[931] = {title = "Der schimmernde Wedel", objective = "Bringt Denalan am Al'Amethsee einen der schimmernden Wedel.", description = "Die Wedel der Pflanze schimmern im Dämmerlicht des Waldes und verleihen ihr eine wabernde, pulsierende Aura.\n\nIhr glaubt, dass Denalan bestimmt gern ein Exemplar davon hätte.", progress = "Habt Ihr etwas für mich?", completion = "Wo habt Ihr das her? So eine Pflanze habe ich seit meiner Exkursion in die Sümpfe des Elends nicht mehr gesehen... das ist Jahrzehnte her! Wie erstaunlich, dass ein Exemplar es bis nach Teldrassil geschafft hat. Und wie hochgewachsen sie ist!\n\nDanke, &lt;Name&gt;. Vergebt mir, dass ich so kurz angebunden bin, aber ich würde zu gern etwas mit diesem Wedel testen...", rewards = "Ihr bekommt:\n\n"},
[932] = {title = "Krankhafter Hass", objective = "Tötet Lord Melenas und bringt Tallonkai Swiftroot in Dolanaar seinen Kopf.", description = "Ich muss Euch warnen, <Name>, das hier muss absolut unter uns bleiben. Die Satyrn bereiten uns schon genug Ungelegenheiten, aber dieser eine hier scheint sich zu einer echten Bedrohung zu entwickeln.\n\nLord Melenas ist sein Name. Er lebt in der Nähe des Teufelsfelsens in einer Höhle, in der er ein großes Kontingent Grellkrieger um sich versammelt hat. Sein Herz ist so schwarz wie die Nacht und er führt etwas äußerst Übles im Schilde.\n\nIhr müsst ihn in der nahe gelegenen Höhle gleich nördlich von hier suchen und mir seinen Kopf bringen.", progress = "Habt Ihr Lord Melenas schon getötet? Es ist wichtig, dass man ihn schnell und stillschweigend beseitigt, <Name>. Solange er lebt, wird er uns allen Ungemach bereiten.", completion = "Da Lord Melenas jetzt endlich zur Strecke gebracht ist, kann ich mich anderen Dingen zuwenden. Danke, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWild-ArmschienenFußlappen\n\nIhr bekommt außerdem:\n\n"},
[933] = {title = "Krone der Erde", objective = "Füllt die Turmalinphiole und bringt sie Corithras Moonrage in Dolanaar.", description = "Südöstlich des Ortseinganges von Darnassus, an den Ufern der Teiche von Arlithrien, gibt es noch einen Mondbrunnen. Die Schildwachen können aufgrund von Angriffen und der ständig schlimmer werdenden Hinterhältigkeit der Knarzklauenfurbolgs kaum durch dieses Gebiet patrouillieren.\n\nSeid auf der Hut, wenn Ihr Euch dem Brunnen nähert, und haltet Eure Waffen stets griffbereit.", progress = "Zunächst schenkte man den Berichten wahnsinnig gewordener Furbolgs keinerlei Beachtung. Wer hätte gedacht, dass sich diese sonst so friedliebenden Bärmenschen einmal in hirnlose Furien verwandeln würden? Es gibt jedoch noch ein weiteres Problem, das uns hier in unserer neuen Heimat plagt.", completion = "Shan'do Stormrage tauchte nie wieder auf und die Druiden waren in heller Aufregung. Bis zum heutigen Tag weiß niemand, was aus ihm geworden ist. Da Malfurion unauffindbar war, übernahm der Erzdruide Fandral Staghelm die Führung der Druiden und überzeugte den Kreis der Urtume in Dunkelküste davon, dass es an der Zeit wäre, unser Volk neu zu organisieren und dass es ebenfalls an der Zeit wäre, unsere Unsterblichkeit wiederzuerlangen.\n\nMit Zustimmung des Kreises pflanzten Staghelm und die mächtigsten der Druiden Teldrassil, den neuen Weltbaum.", rewards = "Ihr bekommt:\n\n"},
[934] = {title = "Krone der Erde", objective = "Füllt die Amethystphiole und bringt sie Corithras Moonrage in Dolanaar.", description = "Mit Teldrassil stand es jedoch nicht zum Besten. Staghelms sorgfältig durchdachte Pläne für den neuen Weltbaum entwickelten sich nicht so, wie er gehofft hatte, denn es gab ein kleines Problem. Ein Problem, das die Ursache für viele weitere Probleme Teldrassils ist.\n\nWie dem auch sei, dazu komme ich später. Ihr müsst den letzten Mondbrunnen nordwestlich von hier in der Lichtung des Orakels aufsuchen. Unter den Ästen des Orakelbaums befindet sich der wichtigste und mächtigste unserer Brunnen. Beschafft eine Phiole seines Wassers und bringt sie mir.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[935] = {title = "Krone der Erde", objective = "Bringt dem Erzdruiden Fandral Staghelm in Darnassus das gefüllte Gefäß.", description = "Ohne den Segen Alexstraszas der Lebensbinderin und Nozdormus des Zeitlosen gab es Makel in Teldrassils Wachstum. Man berichtet von seltsamen Wildtieren, die sich buchstäblich aus dem Nährboden des Baums erhoben haben, und von wahnsinnigen Furbolgs, die durchziehende Reisende angreifen.\n\nIch kann nur hoffen, dass der Erzdruide schnellstens eine Lösung für das Problem findet. Ich werde alles Wasser der Phiolen, die Ihr mir brachtet, in dieses Gefäß schütten, damit Ihr es nach Darnassus bringen könnt.\n\nBringt es Fandral Staghelm, Ihr findet ihn im Druidenhain.", progress = "Ich weiß, dass ich Euch nicht zu mir gebeten habe, deshalb frage ich mich, was Euch wohl zu mir führen mag, um mit mir zu sprechen.\n\nWas immer es auch sein mag, fasst Euch kurz.", completion = "Ah ja, das Wasser, um das ich gebeten habe. Tenaron und Corithras haben sich mit der Lieferung wirklich Zeit gelassen... vielleicht haben sie sich nicht gerade den zuverlässigsten Boten ausgesucht... hmmm.\n\nNun denn, jetzt kann ich endlich wieder an meine Arbeit gehen. Das Gewicht von Teldrassils Problemen lastet auf meinen Schultern. Ein Joch, dessen ich mich liebend gern so bald wie möglich entledigen möchte.\n\nNehmt das, Ihr werdet es bestimmt irgendwie gebrauchen können.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nEschenholzbogenDickichthammer\n\nIhr bekommt außerdem:\n\n"},
[936] = {title = "Erzdruide Runetotem helfen", objective = "Sprecht in Thunder Bluff mit Erzdruide Hamuul Runetotem.", description = "Entschuldigung, <Klasse>, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Thunder Bluff ist sehr an erfahrenen Abenteurern wie Euch interessiert, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein Geringerer als Hamuul Runetotem an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm auf der Anhöhe der Ältesten in Thunder Bluff.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;; ich freue mich, dass Ihr daran interessiert seid, an unseren Forschungen teilzunehmen. Es gibt viel zu tun und ich würde Euch einen schlechten Dienst erweisen, wenn ich Euch sagen würde, dass die Arbeit, die dies mit sich bringt, ungefährlich sei. Hoffentlich erschreckt Euch das nicht ... aber so, wie Ihr ausseht, würde ich sagen, dass Ihr schon früher der Gefahr ins Auge geblickt habt.", rewards = "Ihr bekommt:\n\n"},
[937] = {title = "Die verzauberte Lichtung", objective = "Beschafft 6 Blutfedergürtel und bringt sie der Schildwache Arynia Cloudsbreak in der Lichtung des Orakels.", description = "Man hat mich mit einer kleinen Gruppe Schildwachen hierher beordert, um den Orakelbaum vor den Harpyien zu beschützen, die überall im Tal Nester gebaut haben. Wir versuchen, sie langsam aber sicher zurückzudrängen.\n\nBeim Versuch des Orakelbaums, einen Läufer mit einem Bericht nach Darnassus zu entsenden, wurde dieser von einer Gruppe eben jener Harpyien angegriffen und getötet.\n\nWenn Ihr glaubt, dieser Aufgabe gewachsen zu sein, begebt Euch zu ihren Nestern, erschlagt sie und bringt mir zum Beweis Eurer Taten deren Gürtel.", progress = "Ihre scharfen Krallen und spitzen Schnäbel könnten Eure Fähigkeiten auf eine harte Probe stellen, <Name>, aber ich vertraue darauf, dass Ihr bei dieser Aufgabe nicht versagt.", completion = "Ich bin beeindruckt, was Ihr in so kurzer Zeit alles bewerkstelligt habt, &lt;Name&gt;. Ich würde Euch am liebsten bitten, hier zu bleiben und mir bei meinen Pflichten zu helfen... aber tief in meinem Herzen weiß ich, dass größere Aufgaben auf Euch warten.\n\nMir ist aufgefallen, dass der Orakelbaum einen Teil seiner Rinde abgestoßen hat. Zweifellos hat er eine Aufgabe, die er erledigt haben möchte. Ihr solltet mit ihm sprechen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFessel-GurtRegenfleckiges Cape\n\nIhr bekommt außerdem:\n\n"},
[938] = {title = "Nebel", objective = "Begleitet Nebel zur Schildwache Arynia Cloudsbreak beim Mondbrunnen in der Nähe des Orakelbaums.", description = "Das Fell der Säblerkatze ist von einer auffälligen grauen Farbe, die sich nur wenig vom sie umgebenden Wald abhebt. Wie sie da liegt, erkennt Ihr, dass sie schwer verletzt ist und tiefe Wunden an Rücken und Bauchseite aufweist.\n\nSie hebt ihren Kopf und starrt Euch an, ihre glänzenden blauen Augen voll wacher Intelligenz. Sie scheint Euch folgen zu wollen.", progress = nil, completion = "Oh, danke, &lt;Name&gt;! Ich fürchtete schon, dass ich Nebel nie wiedersehen würde. Ich sah sie tot und würde nie wieder mit meiner treuen Begleiterin zusammensein. Ich schulde Euch mehr als Ihr Euch vorstellen könnt und werde Euch auf ewig dankbar sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKordel-ArmschienenKlippen-RundschildSpäherumhang\n\nIhr bekommt außerdem:\n\n"},
[939] = {title = "Flöte des Xavaric", objective = "Bringt die Flöte von Xavaric und 5 Jadefeuerteufelsbinder zu Eridan Bluewind im südlichen Teil des Teufelswalds.", description = "Ihr untersucht die einfache Holzflöte, die Ihr nach dem Sieg über Xavaric aufgehoben habt.\n\nDas knorrige Holz fühlt sich fest an, aber es scheint, als würden sich die Spiralen und Muster auf der Oberfläche bewegen und herumwirbeln, als Ihr sie in den Händen dreht. Plötzlich überkommt Euch ein Gefühl der Furcht...\n\nIhr schüttelt den Kopf, sicher, dass Euch Euer Gehirn einen Streich spielt.\n\nMöglicherweise tragen andere Satyrn Hinweise darüber mit sich, was Ihr da gefunden habt. Bringt Euren Fund zu dem Druiden Eridan Bluewind, der im südlichen Teil des Teufelswalds lebt.", progress = "Was ist, <Klasse>? Ihr seht besorgt aus.", completion = "Ich spüre das Leiden der Uralten, &lt;Name&gt;...\n\nEs ist nahezu unerträglich, diese Gegenstände in der Hand zu halten...", rewards = "Ihr bekommt:\n\n"},
[940] = {title = "Teldrassil", objective = "Überbringt dem Erzdruiden Fandral Staghelm in Darnassus den Bericht des Orakelbaums.", description = "Der Wald flüstert von Euren wagemutigen Heldentaten, <Name>. Sobald die Harpyien aus ihren Nestern vertrieben waren, spürte ich, wie sich große Ruhe im Wald verbreitete, und dass sich die Kreaturen des Waldes wieder sicher fühlten. Ich habe nicht gewagt, noch einen Boten zum Erzdruiden zu schicken, aber ich weiß, dass Ihr dafür sorgen werdet, dass ihn meine Nachricht sicher erreicht.\n\nBringt ihm dies und wisset, dass der Wald Euch auf all seinen Wegen beschützen wird, sodass Ihr den Wald aus Stein sicher erreicht.", progress = "Hmm... Der Geist des Waldes ist stark in Euch, <Klasse>. Was wollt Ihr vom Erzdruiden der Kaldorei?", completion = "Ich habe mich schon gewundert, warum ich so lange nichts mehr vom Orakelbaum gehört hatte... Es scheint, als würden manche Probleme kleiner, während andere wiederum stetig größer werden.\n\nIch fürchte, meine Arbeit an Teldrassil wird nie ein Ende finden und wir werden unsere Unsterblichkeit nie wiedererlangen.\n\nNichtsdestotrotz habt Ihr die Aufgabe des Orakelbaums trefflich erfüllt und sollt für Euren Fleiß belohnt werden.", rewards = "Ihr bekommt:\n\n"},
[941] = {title = "Das Einpflanzen des Herzens", objective = "Pflanzt das besudelte Herz in Denalans Blumentopf ein.", description = "Ich habe das üble Moos von dem Herzen entfernt, aber es bleibt dennoch besudelt...\n\nVersucht, das Herz in meinem Blumentopf einzusetzen. Er ist mit einer nährstoffreichen Krume gefüllt, die das Herz säubern und heilen kann.", progress = "Der Blumentopf ist mit speziell von Denalan vorbereiteter Krume gefüllt.", completion = "Ihr setzt das Herz in den Blumentopf ein, und es beginnt sich im Handumdrehen selbst einzugraben!\n\nNach ein paar Sekunden windet es sich wieder heraus und ist gesäubert. Es pulsiert leicht und bedeutet Euch, es in die Hand zu nehmen.", rewards = "Ihr bekommt:\n\nGesäubertes Bäumlingsherz"},
[942] = {title = "Der geistesabwesende Ausgrabungsleiter", objective = "Bringt das rätselhafte Fossil zum Archäologen Flagongut im Hafen von Menethil.", description = "Dieses Fossil hat eine auffallende Ähnlichkeit mit einem anderen, das ich einst in Ironforge sah. Ein Archäologe namens Flagongut brachte es zur jährlichen Forscherliga-Konferenz mit. Er dachte, das Fossil besäße eine besondere Macht, die man irgendwie freisetzen könnte.\n\nDas Letzte, was ich von Flagongut hörte war, dass er sich in der Deepwater-Taverne im Hafen von Menethil verschanzt hatte und dort auf eine Eskorte zu Whelgars Ausgrabungsstätte wartete. Sucht ihn auf und zeigt ihm Remtravels Fossil. Vielleicht kann er die Geheimnisse der Vergangenheit lüften.\n\nDas Schiff nach Menethil liegt in Auberdine.", progress = "Was habt Ihr da, Freund?", completion = "Oha! Ihr sagt, das da stammt aus dem weit entfernten Land Kalimdor?\n\nErstaunlich! Einfach erstaunlich!", rewards = "Ihr bekommt:\n\n"},
[943] = {title = "Der geistesabwesende Ausgrabungsleiter", objective = "Der Archäologe Flagongut im Hafen von Menethil möchte, dass Ihr ihm den Stein von Relu und Flagonguts Fossil bringt.", description = "Ausgrabungsleiter Whelgar ist jetzt im Besitz des Originalfundstücks. Er hält sich in seiner Ausgrabungsstätte im Sumpfland auf. Als ich den Stein von Relu entdeckte, glaubte ich, dass er der Schlüssel sei, mit dem das Rätsel des Fossils gelöst werden könne.\n\nAuf dem Weg zu Whelgar wurde ich dann von Raptoren angegriffen und das Relikt ging verloren. Ich weiß nicht, welche dieser scheckigen Bestien das Relikt verschlungen hat, aber falls es Euch gelingen sollte, es zurückzuholen, könnte ich die Macht dieser Artefakte freisetzen.\n\nBringt mir den Stein von Relu und das Originalfossil.", progress = "Mit dem Stein von Relu kann ich nicht nur die verborgenen Geheimnisse meines Fossils, sondern auch die von Remtravels Fossil aus Dunkelküste enthüllen, <Name>.", completion = "Sehr eindrucksvoll, &lt;Name&gt;!\n\nLasst uns jetzt sehen, ob ich mit Hilfe des Steins die Macht des Fossils entschlüsseln kann.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nReliktklingeSchädelsplitter\n\nIhr bekommt außerdem:\n\n"},
[944] = {title = "Die Meistergleve", objective = "Tragt Informationen zusammen und benutzt dann die Wahrsagephiole, um eine Wahrsageschale zu erschaffen. Benutzt die Schale, um mit Onu zu sprechen.", description = "Wie seltsam, dass sich Naga hier herumtreiben, hier in Dunkelküste. Aber was noch seltsamer ist... es sind auch welche vom Klan der Twilight-Hammer da. Dieser Kult verehrt die alten, alten Lords der Erde. Lords, die schon vor Unzeiten besiegt wurden.\n\nDie Meistergleve im Süden ist ein Ort, an dem ein solcher Lord einst gefallen ist.\n\nBegebt Euch dorthin und sucht nach weiteren Anhängern der Twilight-Hammer-Kultisten.\n\nNehmt diese Wahrsagephiole. Erschafft damit eine Wahrsageschale, nachdem Ihr die Meistergleve durchsucht habt. Sprecht dann mit mir mittels der Schale.", progress = "Die Meistergleve, <Name>.\n\nBegebt Euch dorthin und sprecht dann noch mal mit mir.", completion = "Der Klan der Twilight-Hammer ist bei der Meistergleve?\n\nDas ist schlecht.\n\nDer alte Lord, der damals bei der Gleve gepfählt wurde, ist schon lange tot, aber das bedeutet nicht, dass nicht noch immer Teile seiner Macht dort verblieben sind.\n\nDer Klan der Twilight-Hammer muss auf diese Macht aus sein.", rewards = "Ihr bekommt:\n\n"},
[945] = {title = "Therylunes Flucht", objective = "Verhelft Therylune zur Flucht und teilt dann Therysil beim Schrein von Aessina mit, dass ihre Schwester in Sicherheit ist.", description = "Hilfe!\n\nDiese dreckigen Kultisten haben mich umzingelt, während ich durch die Meistergleve spazierte. Was für ein Glück, dass ich so gut im Verstecken bin!\n\nKönnt Ihr mir hier raushelfen? Ich sollte auch meiner Schwester Therysil Bescheid geben, dass es mir gut geht. Sie wohnt in Ashenvale im Süden, beim Schrein von Aessina.", progress = nil, completion = "Wo war meine Schwester??? Therylune ist es egal, ob sie sich schmutzig macht, aber jetzt übertreibt sie! Es ist eine ganz schöne Strecke bis dahin und die Meistergleve ist ein zweifelhafter Ort...\n\nTrotzdem vielen Dank, &lt;Name&gt;. Es war sehr freundlich von Euch, mich wissen zu lassen, dass es ihr gut geht.", rewards = "Ihr bekommt:\n\n"},
[947] = {title = "Höhlenpilze", objective = "Bringt Barithras Moonshade in Auberdine 5 Schorfstänglinge und 1 Todeskappe.", description = "Ich entwickle gerade einen Trank, für den rare Pilze erforderlich sind. Pilze, die nur in einer bestimmten Höhle wachsen. Diese Höhle liegt hinter Cliffspring Falls im Osten, leicht nördlich entlang der Berge.\n\nIch würde ja selbst dorthin gehen, aber der Hain der Uralten hat mir geraten, mich von diesem Ort fern zu halten. Unsere altehrwürdigen Verbündeten spüren, dass die Höhle ein Versteck für etwas Neues, Böses in Dunkelküste ist.\n\nBitte, <Name>, sammelt doch ein paar Pilze für mich, und wenn Ihr schon dabei seid, könntet Ihr auch gleich die Höhle erkunden, um die Befürchtungen der Urtume eventuell zu bestätigen.", progress = "Habt Ihr meine Pilze, <Name>? Wart Ihr in der Höhle?", completion = "Vielen Dank, &lt;Name&gt;. Das sind wirklich Prachtexemplare von Pilzen!\n\nHabt Ihr, als Ihr in Cliffspring Falls wart, etwas gefunden, das die Warnungen der Urtume bestätigen könnte?\n\nDie Urtume sind weise, aber dieses Mal hatte ich gehofft, dass sie sich irren würden.", rewards = "Ihr bekommt:\n\nKlippenwindumhangRotgetupfter Pilz"},
[948] = {title = "Onu", objective = "Sprecht im Hain der Uralten mit Onu.", description = "Onu, ein Urtum der Lehren im Hain der Uralten, hat von Eurer Reise nach Cliffwaterfalls erfahren und möchte Euch sprechen. Der Hain liegt im Süden, im Schatten der Berge.\n\nDie Urtume sind geduldig und weise, <Name>. Aber wenn Onu Euch um Rat bezüglich dessen ersucht, was Ihr in den Falls gesehen habt, fürchte ich, dass es wichtig ist.", progress = nil, completion = "&lt;Name&gt;. Da seid Ihr ja.\n\nGut.\n\nWir haben etwas... zu besprechen. Ihr und ich.", rewards = "Ihr bekommt:\n\n"},
[949] = {title = "Das Twilight-Lager", objective = "Sucht im Lager des Klans der Twilight-Hammer in der Meistergleve nach einem Hinweis.", description = "Niemand weiß, was der Klan der Twilight-Hammer in der Meistergleve vorhat. Aber es muss etwas Böses sein.\n\nDurchsucht ihr Lager bei der Meistergleve... Sucht nach etwas, das uns ihre Absichten verraten könnte.\n\nWir müssen unbedingt wissen, was sie im Schilde führen, bevor wir einen Plan schmieden können.", progress = nil, completion = "Dieses Buch wurde von Hand gedruckt und ist in einer uralten Sprache geschrieben sowie von einem großen Künstler illustriert worden.", rewards = "Ihr bekommt:\n\n"},
[950] = {title = "Rückkehr zu Onu", objective = "Bringt Onu das irrsinnige Gekritzel, das Ihr gefunden habt.", description = "Der Blick in den Twilight-Folianten kann einen wahnsinnig machen. Der Text verschwimmt und tanzt vor Euren Augen, kaum dass Ihr ihn einen Moment betrachtet habt, und die einst so wunderschönen Illustrationen verzerren sich zu grotesken Formen und Mustern.\n\nIhr könnt gerade noch eine Seite des irrsinnigen Gekritzels herausreißen, bevor Ihr ohnmächtig werdet.", progress = "<Name>. Ihr seid zurückgekehrt.", completion = "Dieses Pergament voller Gekritzel umgibt eine chaotische, primitive Magie. Ich spüre das Wirken der Altvorderen darin.\n\nHoffen wir, dass es uns Aufschluss über die Absichten des Klans der Twilight-Hammer in Dunkelküste gibt...", rewards = "Ihr bekommt:\n\n"},
[951] = {title = "Mathystra-Relikte", objective = "Bringt 6 Mathystra-Relikte zu Onu in den Hain der Uralten.", description = "Das Pergament, das Ihr in der Meistergleve gefunden habt, ist eine Seite aus einem alten Text... geschrieben von Elfen! Es ist übelst verflucht und besudelt von der Verderbnis des Klans der Twilight-Hammer, aber es scheint, als würde der Kult alte Elfenmagie benutzen, um seine alten Lords in unsere Welt zurückzuholen.\n\nReist zu den Ruinen von Mathystra im Nordosten und sucht nach alten Relikten unter dem Gras und den zerbrochenen Steinen. Indem wir sie studieren, können wir vielleicht herausbekommen, auf welche Weise der Klan der Twilight-Hammer die Magie der Elfen nutzen will.", progress = "<Name>. Hat Eure Suche in den Ruinen von Mathystra etwas ergeben?", completion = "Danke. Diese Relikte stammen aus einer Zeit, als Mathystra noch glanzvoll erstrahlte. Diese einst so große Bastion der Elfen schwand dahin, doch Splitter ihrer Magie sind immer noch dort zu finden. Hoffentlich können wir die Geheimnisse dieses Ortes vor unseren Feinden enthüllen...\n\nSeid wachsam, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHartholzknüppelWaldmannschwert\n\nIhr bekommt außerdem:\n\n"},
[952] = {title = "Der Hain der Uralten", objective = "Bringt Fandrals Nachricht zu Onu in den Hain der Uralten in Dunkelküste, südlich von Auberdine.", description = "Wenn Ihr genug Zeit hattet, um für den Orakelbaum Nachrichten zu übermitteln, kann ich Euch sicherlich dazu bewegen, eine Nachricht in den Hain der Uralten in Dunkelküste zu bringen, südlich von Auberdine.\n\nIhr werdet höchstwahrscheinlich ein sicheres Transportmittel wie einen Hippogryphen benötigen, aber ich baue darauf, dass Ihr das regeln könnt. Bringt dies Onu, dem Urtum der Lehren. Er wartet auf eine Nachricht von mir, so wie ich auf Neuigkeiten aus der Lichtung des Orakels wartete.", progress = "Ah. <Klasse>. Wie kann Onu Euch helfen?", completion = "Ah. Danke, &lt;Name&gt;. Es ist jedoch seltsam. Der Erzdruide scheint immer so in Eile zu sein. Der Wald weiß, dass gut Ding Weile braucht. Shan’do Stormrage hat das verstanden.", rewards = "Ihr bekommt:\n\n"},
[953] = {title = "Der Untergang von Ameth'Aran", objective = "Studiert die Schrifttafeln, die von Ameth'Aran und ihrem Untergang erzählen, und kehrt dann zur Schildwache Tysha Moonblade in Dunkelküste zurück.", description = "Im Osten findet Ihr die Ruinen von Ameth'Aran. Sie werden heute von den ruhelosen Geistern der Hochgeborenen bewohnt, die einst dort lebten. Damals jedoch war es ein Ort, an dem die Diener Azsharas ihre mächtige Magie ungestört praktizieren konnten.\n\nMan hat mich geschickt, die Ruinen zu erkunden und ich stieß auf zwei große Schrifttafeln, auf denen die Geschichten Ameth'Arans und seines Unterganges beschrieben werden. Während ich die Runen las, traten Geister an mich heran und ich floh.\n\nBitte, wenn es Euch möglich ist, begebt Euch zu den Ruinen und entziffert an meiner Statt die Schrifttafeln.", progress = "When you have studied the tablets and learned of Ameth'Aran's fall, I will take the knowledge on to Auberdine, and inform the Circle of Ancients.", completion = "Wir haben nur wenige Aufzeichnungen aus der Zeit des Kriegs der Urtume, speziell aus der Zeit kurz vor der Zerstörung des Brunnens der Ewigkeit. Bedenkt man den Aufruhr und die katastrophalen Ereignisse, die damals stattgefunden haben, ist das keine große Überraschung.\n\nDanke, &lt;Name&gt;. Dank Eurer Hilfe ist meine Arbeit hier beendet und ich kann dem Kreis einen vollständigen Bericht vorlegen.", rewards = "Ihr bekommt:\n\n"},
[954] = {title = "Bashal'Aran", objective = "Sucht in den Ruinen von Bashal'Aran nach der Quelle der seltsamen blauen Aura.", description = "Die Ruinen von Bashal'Aran im Osten sind von dämonischen Dienern überrannt worden. Die Grimmlinge und Satyrn haben sich in dem Gebiet niedergelassen und nähren sich von den magischen Energien dort. Ihre Macht wächst, je länger sie sich dort aufhalten.\n\nDennoch habe ich festgestellt, dass es dort einen Schrein gibt, dem sie nicht zu nahe kommen wollen. An der Westseite der Ruinen auf einem kleinen Steilhang entspringt eine seltsame blaue Aura ... Das muss eine Erklärung für das Widerstreben der Dämonen sein.\n\nIch hätte gern, dass Ihr das untersucht.", progress = nil, completion = "Ahhh... Womit habe ich die außerordentlich große Ehre Eurer Begleitung verdient, oh &lt;Volk&gt;? Wahrlich sagt dies viel über meine momentanen Gefährten aus - ohne meine Gastgeber, die edlen Grells und Satyrn, beleidigen zu wollen -, aber man könnte Eure Anwesenheit durchaus als Verbesserung betrachten.\n\nAber bitte, lasst Euch durch mein unzivilisiertes Gerede nicht von hier vertreiben. Es ist in der Tat schon viele Jahre, sogar Jahrzehnte her, dass ich solch höfliche Begleitung hatte.", rewards = "Ihr bekommt:\n\n"},
[955] = {title = "Bashal'Aran", objective = "Beschafft für Asterion in Bashal'Aran 8 Grell-Ohrringe.", description = "Sollte ich jemals gehalten sein, die Geschichte meines Lebens zu erzählen, würde dies zweifellos die Grenzen Eurer Geduld überstrapazieren. Sagen wir einfach, dass mein Leben lang und schmerzvoll war, und dass diese meine spektrale Gestalt die schlimmste Pein von allem ist.\n\nIch werde durch Magie hier festgehalten. Mögen meine Worte auch unaufrichtig erscheinen, so versichere ich Euch doch, dass ich über die Maßen dankbar wäre, würdet Ihr mir helfen, den Grund für meine Gefangenschaft herauszufinden. Ein Siegel bindet mich, und vielleicht finde ich einen Hinweis darauf, wenn ich den Ohrschmuck der Grimmlinge und Grells nur näher betrachten könnte.", progress = "Sobald ich die Ohrringe habe, werde ich den Zauber wirken, mit dem man den Standort des Siegels, das mich bindet, finden kann. Seit Jahrhunderten denke ich nur noch an die Freiheit, die die Zerstörung des Siegels mir bringen wird... Vielleicht haben all diese Jahrhunderte jedoch ihren Tribut an meinen Geist gefordert, den ich nie wieder beheben kann...", completion = "Wirklich... Die Grells von Bashal'Aran besitzen nicht, wonach ich suche... Sie sind jedoch erst kürzlich damit in Berührung gekommen. Kürzlich... Kürzlich im Sinne Eures Zeitverständnisses, nicht meines. Kürzlich reicht für mich bis in die Schatten der Vergangenheit zurück, fast bis in ein anderes Zeitalter...", rewards = "Ihr bekommt:\n\n"},
[956] = {title = "Bashal'Aran", objective = "Beschafft das alte Mondstein-Siegel und bringt es Asterion in Bashal'Aran.", description = "Wenn die Grells erst kürzlich mit dem Siegel in Berührung gekommen sind, das mich an dieses ewige Gefängnis bindet, glaube ich, den Grund dafür zu wissen. Zweifellos ist das Siegel in den Besitz des Satyrs gelangt, der sie anführt.\n\nIch bin mir ganz sicher, dass es so ist, <Name>. Einer der Satyrn muss es besitzen. Wenn Ihr es an Euch bringen könntet, würde es mich der Überwindung der Gitterstäbe meines Gefängnisses so nahe bringen, dass es mich zu Tränen rühren würde.", progress = "Die Säulen dieses Schreins wirken auf mich wie die Gitterstäbe eines Gefängnisses, <Name>. Keine der Kräfte, die ich noch besitze, könnte sie zerstören, auch keine Magie, derer ich fähig wäre...\n\nTausend Jahre oder länger habe ich sie angestarrt und mich gefragt, ob ich dann frei sein würde, wenn ich schließlich selbst die Steine überlebt hätte? Oder würden es dann unsichtbare Gitterstäbe sein, die mich hielten...", completion = "Es... es fällt mir schwer zu glauben, dass dies, was ich hier in meiner Hand halte, das ist, was mich so lange gebunden hat. Lasst uns keine Zeit verlieren, &lt;Name&gt;. Wenn das Siegel erst zerstört ist, kann ich endlich wieder frei durch die Wälder der Erde streifen.", rewards = "Ihr bekommt:\n\n"},
[957] = {title = "Bashal'Aran", objective = "Zerstört das alte Mondstein-Siegel in der uralten Flamme in Ameth'Aran und kehrt dann zu Asterion in Bashal'Aran zurück.", description = "Es war die Kunst eines der mächtigsten Hochgeborenen, der das Siegel erschuf, das mein Gefängnis war. In Ameth'Aran, den Ruinen im Süden, die diesen hier aufs Haar gleichen, gibt es sogar heute noch eine uralte Flamme, blau ist ihre Farbe. In dieser Flamme könnte man dieses Siegel zerstören.\n\nAchtet auf die Ruinen, <Name>!", progress = nil, completion = "Ich bin frei, &lt;Name&gt;! Jetzt kann ich mit eigenen Augen ansehen, wie sich unsere Welt verändert hat... Ich habe nur Teile davon gekannt. Stellt Euch vor, als ich das letzte Mal frei umherwandeln konnte, stand der Brunnen noch und die Hochgeborenen hielten Hof mit Azshara, unserer geliebten Königin.\n\nIch spüre, dass Athrikus, mein Kerkermeister, mein ehemaliger Meister, noch lebt... Das Gefühl der Hoffnungslosigkeit in mir beginnt jetzt schon, den Gedanken an Rache zu weichen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nForscher-WesteVagabunden-GamaschenElfenzauberstab\n\nIhr bekommt außerdem:\n\n"},
[958] = {title = "Werkzeuge der Hochgeborenen", objective = "Sucht sieben Hochgeborenenrelikte und bringt sie Thundris Windwirker in Auberdine.", description = "<Klasse>. Ich möchte Euch um etwas bitten.\n\nHabt Ihr die Ruinen von Ameth'Aran gesehen? Falls nicht, findet Ihr sie auf der Ostseite der Hauptstraße, ein paar Straßen weiter südlich. Einst waren sie die Heimat vieler mächtiger Hochgeborener, doch heute sind sie Zeugnis der Zerstörung, die sie mit ihrem Dilettantismus angerichtet haben.\n\nDie Schildwachen sagten mir, dass die Geister der Hochgeborenen immer noch umgehen und dass sie ihre alten, magischen Utensilien immer noch benutzen. Wir müssen uns diese Relikte aneignen, damit wir sie zerstören können.", progress = "Wären die Relikte doch auch bei der Katastrophe zerstört worden, die unsere Welt zerstört hat... Wie dem auch sei, wir müssen tun, was wir können, um dafür zu sorgen, dass die Schrecken unserer Vergangenheit sich in der Zukunft nicht wiederholen.", completion = "Auch wenn ich es mir sicherlich nur einbilde, scheint es mir doch, als könnte ich bei ihnen fast die Besudelung mit übler Magie der Hochgeborenen spüren. Ich möchte sie zerstört sehen, damit dieses seit langem schlummernde Böse nie wieder freigesetzt werden kann.", rewards = "Ihr bekommt:\n\nEfeu-Manschetten"},
[959] = {title = "Ärger auf den Docks", objective = "Kranführer Bigglefuzz in Ratchet möchte, dass Ihr Zausel dem Verrückten, der sich in den Höhlen des Wehklagens versteckt, die Flasche mit 99-jährigem Portwein wieder abnehmt.", description = "Upps!\n\nWie Ihr seht, ist mir ein kleines Malheur passiert! Die Morgenlieferung aus Booty Bay war umfangreich. Wirklich gewaltig! Noch nie habe ich so viele Kisten gesehen. Tja, ich wollte die Sache etwas beschleunigen, deshalb habe ich begonnen mehr abzuladen, als ich auf einmal bewältigen konnte. Und dann ist alles zusammengebrochen.\n\nBevor ich wusste, was überhaupt los war, sah ich diese Nervensäge Zausel den Verrückten mit einer Flasche 99-jährigem Portwein wegrennen. Hab ihn bis zu den Höhlen des Wehklagens verfolgt. Da wollte ich auf keinen Fall rein.\n\nVielleicht seid Ihr ja mutig genug, um nach ihm zu suchen?", progress = "Der Dockmeister sitzt mir im Nacken, seit Zausel der Verrückte mit dem 99-jährigen Portwein stiften gegangen ist. Ich glaube, diese Flasche sollte ein Geschenk an Gazlowe von keinem Geringeren als Baron Revilgaz persönlich sein.\n\nWenn Ihr mutig und geduldig genug seid, um Zausel den Verrückten aufzustöbern und ihm diesen Portwein abzunehmen, sorge ich dafür, dass Ihr eine ordentliche Belohnung bekommt.", completion = "Ausgezeichnet! Gerade, als ich dachte, ich würde meinen Job verlieren! Ich werde dafür sorgen, dass Gazlowe umgehend sein Geschenk bekommt.\n\nDanke, &lt;Name&gt;. Das habt Ihr wirklich toll gemacht!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[960] = {title = "Onu meditiert", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWahrsagephiole"},
[961] = {title = "Onu meditiert", objective = "Die Suche nach den Kultisten der Twilight-Hammer ist mühsam. Ich muss über ihre Absichten meditieren...\n\nSprecht mit mir mittels der Schale, sobald Ihr neue Informationen habt. Solltet Ihr eine Wahrsagephiole benötigen, um eine Schale zu erschaffen... nehmt diese hier.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWahrsagephiole"},
[962] = {title = "Schlangenflaum", objective = "Die Apothekerin Zamah in Thunder Bluff möchte, dass Ihr zehn Schlangenflaum für sie sammelt.", description = "Die Königliche Apothekervereinigung, die in der großen Undercity Lordaerons ansässig ist, hat mich geschickt, um eine ganz besondere Aufgabe zu erledigen, <Name>. Vielleicht möchtet Ihr mich und damit auch die dunkle Fürstin bei unseren Bemühungen, die Verlassenen weiterzubringen, unterstützen.\n\nIch studiere seit kurzem eine rare Pflanzenart namens Schlangenflaum. Ich denke, dass dieses Kraut in größeren Mengen außerordentliches Potenzial besitzt.\n\nLeider findet man Schlangenflaum nur in den dunkelsten Winkeln der Höhlen des Wehklagens, einem gefährlichen Höhlensystem im Brachland.", progress = "Ich kann es kaum erwarten zu erfahren, ob Ihr in den Höhlen des Wehklagens genügend Schlangenflaum sammeln konntet. Ich habe schon viele zu diesem Zweck ausgeschickt, doch keiner kam zurück.", completion = "Ah, das sind herrliche Exemplare. Das habt Ihr gut gemacht, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nApotheker-Handschuhe"},
[963] = {title = "In ewiger Liebe", objective = "Befreit den Geist von Anaya Dawnrunner und bringt ihren Anhänger zu Cerellean Whiteclaw in Auberdine.", description = "Nach den Schlachten um den Brunnen der Ewigkeit hörte ich, dass Ameth'Aran zerstört wurde und alle Bewohner ums Leben kamen, darunter auch meine geliebte Anaya.\n\nIch hätte nie gedacht, dass mich noch heute, Tausende von Jahren später, die Erinnerungen an Anaya um den Schlaf bringen würden. Ich wanderte wie in Trance durch die Wälder von Dunkelküste und fand mich schließlich in den Ruinen von Ameth'Aran wieder... wo ich den gequälten Geist meiner Geliebten sah.\n\nSie muss befreit werden, aber ich kann es nicht über mich bringen, dies zu tun. Ihr Geist muss zerstört werden.", progress = "Mit sorgenschwerem Herzen folgte ich Shan'do Stormrage in den Großen Schlaf und nahm meine Sorgen mit hinüber in meine Träume, um Tausende von Jahren zu schlafen.", completion = "Danke, &lt;Name&gt;. Vielleicht wäre es besser gewesen... wenn ich es selbst getan hätte. Aber selbst nach diesen Tausenden von Jahren konnte ich es nicht über mich bringen, die Hand gegen meine Geliebte zu erheben.\n\nBitte, ich möchte mit meiner Trauer allein sein...", rewards = "Ihr bekommt:\n\nTräne des Kummers"},
[964] = {title = "Skelettfragmente", objective = "Bringt 15 Skelettfragmente zu Apotheker Dithers am Bollwerk, Westliche Pestländer.", description = "Der Schlüssel zur Scholomance wird 'Skelettschlüssel' genannt. Er muss aus den Überresten eines Skeletts geschmiedet werden- eigentlich aus mehreren - und er darf nur durch die stärksten Metalle in einer geeigneten Form gehärtet werden. Ein Signet der Macht von einem Wesen, das das Portal zur Scholomance natürlich öffnen kann, gibt dem Schlüssel seine endgültige Funktion.\n\nAber eines nach dem anderen, <Name>. Wir benötigen Skelettfragmente für das Schmieden des Schlüssels. Skelette innerhalb von Andorhal sollten den gewünschten Effekt bringen, aber die außerhalb der Mauern könnten vielleicht auch ausreichen.", progress = "Tötet viele und tötet häufig, <Klasse>... wir werden einen guten Vorrat geeigneter Skelettfragmente benötigen, um die äußere Schicht des Schlüssels herzustellen. Man nennt so etwas nicht umsonst Skelettschlüssel, wisst Ihr.", completion = "Das wird funktionieren, &lt;Name&gt;! Jetzt bin ich dran... ich werde sie mit einem geeigneten Härter tränken, wodurch sie den starken Schmiedeprozess überstehen werden, den sie schließlich durchlaufen müssen.\n\nDer nächste Schritt wird sein, eine geeignete Form für den Schlüssel zu bekommen. Ich kenne einen Goblin-Schmied in Tanaris, der in der Vergangenheit Formen für ähnlich makabre Dinge hergestellt hat. Er arbeitet für den üblichen Auftraggeber der Goblins - den höchsten Bieter.", rewards = "Ihr bekommt:\n\n"},
[965] = {title = "Der Turm von Althalaxx", objective = "Sucht Balthule Shadowstrike in der Nähe des Turms von Althalaxx in Dunkelküste.", description = "Grüße, <Volk>. Ich bin Elissa Starbreeze und es ist meine Aufgabe, Auberdine vor Schaden zu schützen.\n\nAus diesem Grund habe ich Balthule Shadowstrike ausgeschickt, um die seltsamen Vorkommnisse rund um den Turm von Althalaxx im Nordosten zu beobachten.\n\nEr hätte eigentlich schon längst wieder zurück sein sollen. Daher fürchte ich, dass er im Wald auf eine unvorhersehbare Gefahr gestoßen ist. Ich würde es außerordentlich zu schätzen wissen, wenn Ihr nach ihm suchen und dafür sorgen würdet, dass es ihm gut geht.", progress = nil, completion = "Elissa hat Euch geschickt? Dann bringt Ihr also gute Nachrichten. Ich habe ihr beunruhigende Neuigkeiten zu berichten und wusste nicht, wie ich sie ihr übermitteln sollte.", rewards = "Ihr bekommt:\n\n"},
[966] = {title = "Der Turm von Althalaxx", objective = "Sammelt 4 abgenutzte Pergamentfetzen für Balthule Shadowstrike in der Nähe des Turms von Althalaxx.", description = "Eine Gruppe Hexenmeister hat sich in und um den Turm herum niedergelassen. Ich wollte ja schon früher nach Auberdine zurückkehren, um Elissa Bericht zu erstatten, aber ich befürchtete, hier etwas zu verpassen, solange ich fort wäre.\n\nDelgren vermutete, dass sich eine solche Gesellschaft beim Turm versammeln würde, aber er wusste nicht, warum.\n\nEin paar Pergamentfetzen, die die Hexenmeister bei sich führten, sind mir in die Hände gefallen, aber ich brauche noch mehr, um das Rätsel zu lösen. Ich warne Euch jedoch, geht lieber nicht in den Turm hinein, denn die Hexenmeister dort sind noch viel mächtiger!", progress = "Habt Ihr noch mehr von ihren Rollen gefunden? Falls Ihr sie findet, könnte ich die Stücke zusammensetzen und mir so ein besseres Bild dieses Klans machen.", completion = "Vielen Dank, &lt;Name&gt;. Das sollte ein wenig Licht auf diese Hexenmeisterzusammenkunft werfen...\n\nHmmm... der Kult des dunklen Strangs... Von einer solchen Gruppe habe ich noch nie gehört. Da ich nichts über ihren Hintergrund weiß, ist es fast unmöglich etwas darüber zu sagen, was sie planen könnten.\n\nEs darf keine Zeit mehr verschwendet werden. Es muss unverzüglich eine Warnung an Delgren überbracht werden.", rewards = "Ihr bekommt:\n\n"},
[967] = {title = "Der Turm von Althalaxx", objective = "Überbringt Delgren dem Läuterer in Ashenvale Balthules Brief.", description = "Mein Meister, Delgren der Läuterer, ist ein Paladin, der gütigerweise seine Unterstützung bei der Verteidigung unseres Waldes vor den Streitkräften der Dämonen und Untoten angeboten hat. Er hat mich viel über das Heilige Licht und die Kampfkunst gelehrt.\n\nDelgren muss sofort über die Machenschaften des Kults informiert werden.\n\nIhr findet ihn ganz weit südlich von hier in Maestras Posten in Ashenvale. Beeilt Euch, ich fürchte nämlich, dass die Bedrohung durch den dunklen Strangs stündlich größer wird.", progress = "Ihr wolltet mich sprechen, <Klasse>?", completion = "Ihr seid ganz schön gut ausgerüstet für einen Boten, wenn ich das sagen darf, hm? Ich nehme an, Balthule wollte sichergehen, dass mich dieser Brief auch erreicht. Mal sehen, was er schreibt...\n\nDas sind beunruhigende Neuigkeiten. Wenn wirklich untote oder dämonische Streitkräfte entdeckt werden, helfe ich den Schildwachen, sie zu vernichten.\n\nIch musste mich erst an die Umgangsformen der Nachtelfen gewöhnen, aber mittlerweile habe ich vor ihnen als Verbündete größten Respekt.", rewards = "Ihr bekommt:\n\n"},
[968] = {title = "Die Macht in der Tiefe", objective = "Bringt das Buch: 'Die Macht in der Tiefe' zu Gerrig Bonegrip im düsteren Viertel in Ironforge.", description = "Obwohl das Buch ziemlich abgenutzt und zerfleddert ist, ist der Titel auf dem Buchdeckel noch gut lesbar:\n\n'Die Macht in der Tiefe'\n\nIn diesem Buch findet sich eine Auflistung unaussprechlicher Namen mit viel sagenden Betitelungen, Verehrungsmethoden und bevorzugten Opferritualen ... bei denen sehr oft lebende, humanoide Kreaturen verwendet werden.\n\nAuf der Innenseite des Einbands stehen die Worte: 'Bonegrips Runen und Verhängnisse, Düsteres Viertel, Ironforge. Inhaber: Gerrig Bonegrip.'\n\nWenn Bonegrip derartige Bücher verkauft, nimmt er dieses hier vielleicht zurück.", progress = "Hallo, werter Herr.\n\nDarf ich Euch ein paar meiner Folianten zeigen?", completion = "Ah, ein Exemplar von \"Die Macht in der Tiefe\". Ein interessantes Werk, wirklich. Manche könnten es nützlich finden...\n\nAber das hier ist in einem traurigen Zustand. Und seht nur hier! Fast alle Seiten sind mit Randnotizen versehen!\n\nHm... Ich kenne dieses Exemplar. Ich hab es letztes Jahr an Bolgar verkauft. Seid Ihr... ein Freund von ihm? Ja, das dachte ich mir schon. Ihr habt dasselbe Feuer in den Augen!\n\nTja, ich sage immer, Bolgars Freunde sind auch meine Freunde. Und wir halten zusammen, stimmt's?", rewards = "Ihr bekommt:\n\n"},
[969] = {title = "Das Glück sei mit Euch", objective = "Sammelt 10 Frosthagelsplitter für die Hexendoktorin Mau'ari in Everlook.", description = "Ah, ich seh's Euch direkt an: Ihr möchtet, dass ich Euch einen Glücksbringer anfertige. Mau'ari weiß immer Bescheid!\n\nIm Süden, findet Ihr eine Schlucht und Riesen, die komplett aus Eis bestehen. Die Riesen tragen die Splitter manchmal bei sich, aber Ihr könnt sie auch selbst in der Schlucht sammeln. Diese Splitter haben mächtige reflektierende Eigenschaften.\n\nBringt mir 10 Frosthagelsplitter und mein Glücksbringer wird Euch gehören.", progress = "Bringt die Splitter zurück und ich werd Euch mehr erzähl'n!", completion = "Ah, ja... dann werd ich jetzt mal den Glücksbringer für Euch herstell'n. Wartet's ab!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[970] = {title = "Der Turm von Althalaxx", objective = "Beschafft einen leuchtenden Seelenedelstein und bringt ihn Delgren dem Läuterer in Maestras Posten.", description = "Balthules Brief verkündet Unheil. Dieser Kult des dunklen Strangs ist mir ein Dorn im Auge, der entfernt werden muss. Ich hatte nordöstlich von hier in Ordil'Aran schon einmal mit dem Abschaum des dunklen Strangs zu tun. Eines seiner Mitglieder besitzt einen Seelenedelstein, der, wie ich glaube, das Geheimnis der Macht des Kults enthält.\n\nBringt ihn mir, dann kann ich die darin zu findenden Geheimnisse entschlüsseln.", progress = "Habt Ihr den Seelenedelstein?", completion = "Hmm, dieser Seelenstein ist von dunkler Magie verzaubert. Mal sehen, was sich darin verbirgt, ja?", rewards = "Ihr bekommt:\n\n"},
[971] = {title = "Wissen in der Tiefe", objective = "Bringt das 'Lorgalis-Manuskript' zu Gerrig Bonegrip in Ironforge.", description = "Wie Ihr vielleicht wisst, trage ich Lehren zusammen. Alte Lehren. Mächtige Lehren. Lehren, die Portale öffnen, und Lehren, die die Schlafenden erwecken können.\n\nEs kursieren Gerüchte um einen alten Teil einer Lehre, das 'Lorgalis-Manuskript', das sich tief unten in den Blackfathom-Tiefen in Ashenvale befinden soll. Dieser Ort ist die ehemalige Heimat längst verstorbener Elfen. Elfen, die über großes Wissen verfügten, bevor ihre Stadt zerfiel.\n\nSucht in den Blackfathom-Tiefen nach dem Manuskript. Wenn Ihr das tut, werde ich Euch das nie vergessen. Auch nicht ... nach dem Ende aller Tage.", progress = "Die Reise nach Ashenvale ist lang und Eure Aufgabe ist nicht leicht. Aber wenn Ihr mir das Manuskript bringt, <Name>... dann werde ich Euch fürstlich belohnen.", completion = "Ihr habt das Manuskript gefunden! Was für ein Freudentag! Wir werden es nachdrucken und verteilen, und dann können auch meine Brüder und Schwestern endlich des alten Wissens von Lorgalis teilhaftig werden!\n\nIhr habt uns mehr geholfen als Ihr ahnt, &lt;Name&gt;. Ich hoffe jedoch, dass dieses Geschenk Euch zeigt, wie dankbar wir uns unseren Verbündeten erweisen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nErhaltender Ring"},
[972] = {title = "Wassersapta", objective = "Nehmt das Wassersapta und sucht in Silberwald nach dem verderbten Teich, <Name>. Ich habe großes Vertrauen in Eure Fähigkeiten.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWassersapta"},
[973] = {title = "Der Turm von Althalaxx", objective = "Bringt Delgren dem Läuterer in Maestras Posten Ilkrud Magthrulls Folianten.", description = "Ilkrud Magthrull. Ja, ich kenne ihn. Er ist ein mächtiger Orc-Hexenmeister, der im Fire Scar-Schrein lebt, einem äußerst bösen Ort im südwestlichen Ashenvale.\n\nBislang ist er nur ein geringes Ärgernis und ich hatte noch nichts mit ihm zu tun, aber es sieht so aus, als wäre jetzt seine Zeit gekommen.", progress = "Ihr scheint mir ein bisschen aufgewühlt zu sein, <Name>. Seid Ihr wohlauf?", completion = "Ihr habt heute Großes geleistet, &lt;Name&gt;. Ihr könnt sehr stolz auf Euch sein, dass Ihr Euch einem so mächtigen Hexenmeister gestellt habt.\n\nDann sehen wir doch mal, was wir aus Ilkruds Schriften lernen können.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKlerikerringStab des Läuterers\n\nIhr bekommt außerdem:\n\n"},
[974] = {title = "Die Quelle finden", objective = "Krakle im Un'Goro Krater möchte, dass Ihr den heißesten Bereich des Feuerfedergrats findet.\n\nImmer, wenn Ihr eine heiße Stelle findet, klickt Ihr das Thermometer mit der rechten Maustaste an, um die Temperatur zu überprüfen. Sucht, bis Ihr die heißeste Stelle gefunden habt.", description = "Die heißen Quellen hier sind eine Quelle der Geheimnisse für mich. Woher kommt die Hitze?\n\nWenn ich mir überlege, wie nah diese Teiche beim Feuerfedergrat sind, frage ich mich wirklich, ob der Vulkan etwas damit zu tun hat. Ich habe ein Thermometer entwickelt, um die Temperaturen am Vulkan zu messen, und ich würde gern die heißeste Stelle finden. Es zeigt die Messungen in Grad Kraklenheit an!\n\nHier, nehmt es und messt die Temperaturen am Grat, wann immer Ihr eine heiße Stelle seht!", progress = "Ich würde ja selbst gehen, aber... Ich habe ein wenig Angst vor den Feuerelementar dort!", completion = "Ja, ich sehe da ganz klar eine Verbindung zwischen der Temperatur des Vulkans und den heißen Quellen. Ich muss meine Berechnungen noch einmal auf ihre Genauigkeit überprüfen, aber es scheint, als ob die Entfernung und das Maß, mit dem die Hitze übertragen wird ... Hmm ...", rewards = "Ihr bekommt:\n\n"},
[975] = {title = "Behälter von Mau'ari", objective = "Wartet einen Moment und sprecht dann erneut mit Hexendoktorin Mau'ari, um den Glücksbringer zu erhalten.", description = "Also, bevor ich Euch dies'n Glücksbringer geb, erklär ich Euch besser, wie er zu verwenden is'.\n\nWenn Ihr den Glücksbringer bei Euch tragt, werdet Ihr feststell'n, dass die Kreaturen, gegen die Ihr kämpft, bestimmte Gegenstände fallen lassen. Wenn Ihr den Glücksbringer nich' dabei habt, werdet Ihr sie nich' find'n. Kapiert?\n\nIhr erkennt diese speziellen Gegenstände am Namen - sie werden E'ko genannt. Wenn Ihr solche Gegenstände findet, bringt Ihr sie einfach der alten Mau'ari, und sie hilft Euch.\n\nWartet hier, während ich Euren Glücksbringer anfertige.", progress = nil, completion = "Hier, &lt;Name&gt;. Denkt daran, dass Ihr ihn bei Euch tragen müsst. Warum begebt Ihr Euch nicht zurück in die Wildnis und seht, was Ihr dort findet?", rewards = "Ihr bekommt:\n\nBehälter von Mau'ari"},
[976] = {title = "Nachschub für Auberdine", objective = "Sprecht mit Delgren dem Läuterer bei Maestras Posten, nachdem Ihr Feero sicher durch Ashenvale geführt habt.", description = "Delgren hat mich gebeten, der Schildwache Starbreeze in Auberdine Nachrichten und Nachschub zu bringen, aber es schmeckt mir gar nicht, allein dorthin zu gehen. Im Wald sind gefährliche Feinde zugange und ich möchte nicht riskieren, dass der Nachschub und die Informationen in die falschen Hände geraten.\n\nWenn Ihr und ein paar andere als Wachen mit mir kämen, könnte ich sofort gehen. Mit Eurem Schutz zweifle ich nicht daran, dass wir diese Dinge sicher nach Auberdine bringen können.", progress = nil, completion = "Das habt Ihr heute gut gemacht, &lt;Klasse&gt;. Die Gegenstände, die wir Auberdine zu Hilfe geschickt haben, werden umgehend gegen die dunklen Bedrohungen eingesetzt, die den Wald heimsuchen.\n\nNehmt das hier zusammen mit meinem tief empfundenen Dank.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nImmerscheinlaterneBrustplatte von Kor\n\nIhr bekommt außerdem:\n\n"},
[977] = {title = "Sind wir endlich da, Yeti?", objective = "Sammelt 2 makellose Yetihörner für Umi Rumplesnicker in Everlook.", description = "Nachdem ich jetzt alles habe, was ich benötige, um die mechanischen beweglichen Teile abzudecken, benötige ich nur noch eine weitere Sache. Na ja, eigentlich zwei. Zwei Hörner!\n\nDie Eisdistelpatriarchen und -matriarchen haben die größten Hörner, also will ich natürlich diese. Diese Yetiart bewohnt eine Höhle im Südosten. Es gibt viele von ihnen; Ihr solltet keine Probleme haben, sie zu finden.\n\nDenkt daran, ich will nur die bestaussehenden - keine beschädigten oder zerbrochenen Hörner, bitte!", progress = "Ich bin fast fertig mit dem Anbringen des Fells, <Name>. Bitte, kommt schnell mit diesen Hörnern zurück!", completion = "Ich kann es gar nicht erwarten, das meinen Freunden zu zeigen! Also, wartet einen Moment, während ich die hier festmache...\n\nPerfekt!", rewards = "Ihr bekommt:\n\n"},
[978] = {title = "Mondbestrahltes Wildekin", objective = "Sammelt 10 mondbestrahlte Federn aus Winterspring und kehrt dann zu Erelas Ambersky in Rut'theran zurück.", description = "Wildekinfedern aus dem Hinterland scheinen Spuren magischer Fähigkeiten zu enthalten. Diese Kräfte... sie scheinen von den Kreaturen nicht bewusst eingesetzt zu werden, es scheint eher, als wären sie der Art angeboren; ein Teil ihres innersten Wesens.\n\nWährend meiner Studien habe ich gehört, dass eine große Population von Wildekins die schneebedeckten Länder von Winterspring bewohnt. Könnten diese Kreaturen über die gleichen Kräfte verfügen? Helft mir bitte, eine Antwort zu finden, <Name>. Begebt Euch nach Winterspring und sammelt die auf dem Boden gefallenen Federn ein. Kehrt dann zu mir zurück.", progress = "Woher können diese Kräfte stammen? Ich glaube, wir sind auf der richtigen Spur, um die Antwort zu finden, <Name>.", completion = "Jetzt kann ich diese Federn vergleichen... Mal sehen...", rewards = "Ihr bekommt:\n\n"},
[979] = {title = "Ranshalla suchen", objective = "Sucht nach Ranshalla im östlichen Winterspring.", description = "Ja, ja, diese Federn scheinen die gleiche magische Verzauberung zu enthalten, die mir schon zuvor auffiel... Auch wenn ich mir nicht sicher bin, was wir vorfinden werden, solltet Ihr weiterhin nach Antworten suchen, <Name>.\n\nEine meiner Kolleginnen reiste kürzlich nach Winterspring, um die Wildekin dort in ihrer heimischen Umgebung zu beobachten. Warum sucht Ihr sie nicht auf und seht, was sie herausgefunden hat?", progress = nil, completion = "Hallo! Erelas hat Euch geschickt? Sehr gut, ich wollte gerade zu den Höhlen reisen und ich hätte nichts gegen Begleitung.", rewards = "Ihr bekommt:\n\n"},
[980] = {title = "Die neuen Quellen", objective = "Reist nach Winterspring und sprecht mit Donova Snowden.", description = "Tja, ich habe von anderen heißen Quellen an einem Ort namens Winterspring gehört, von hier aus gesehen weit im Norden. Das Merkwürdige ist, dass es dort in der Nähe keine Vulkane gibt. Interessant, ich weiß.\n\nAlso, wenn Ihr mehr herausfinden möchtet, solltet Ihr Euch nach Winterspring begeben und mit einer Freundin von mir sprechen. Ihr Name ist Donova Snowden und sie hält sich derzeit bei den heißen Quellen dort auf.\n\nIch danke Euch erneut, dass Ihr mir mit meinem Thermometer geholfen habt! Auf dann!", progress = nil, completion = "Hallo, &lt;Name&gt;. Ja, es stimmt, was Krakle Euch erzählt hat...", rewards = "Ihr bekommt:\n\n"},
[981] = {title = "Der Turm von Althalaxx", objective = "Sprecht mit Delgren dem Läuterer in Maestras Posten.", description = "Für all das, was Ihr geleistet habt, habt Ihr eine ordentliche Belohnung verdient. Kehrt zu Delgren zurück und sagt ihm, dass Ihr Athrikus Narassin eigenhändig den Garaus gemacht habt, und dass der Kult des dunklen Strangs zerschlagen ist.", progress = nil, completion = "Ich wusste, dass Ihr der Aufgabe gewachsen sein würdet, &lt;Name&gt;.\n\nIch fühle, dass große Taten vor Euch liegen und dass Ihr viel Ungemach beseitigen werdet, das unser Land plagt. Habt meinen Segen, &lt;Name&gt;, und dieses Geschenk.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFromme BeinwickelSeraphs Schlag\n\nIhr bekommt außerdem:\n\n"},
[982] = {title = "Tiefer Ozean, weites Meer", objective = "Beschafft die Schließkassette der SILBERMORGEN und die Schließkassette der NEBELSCHLEIER für Gorbold Steelhand in Auberdine. Beide Gegenstände findet Ihr an Bord der Schiffswracks nördlich des Dorfes.", description = "Nahe der Ufer von Dunkelküste im Norden liegen zwei havarierte Schiffe - die SILBERMORGEN und die NEBELSCHLEIER. Vor einiger Zeit kollidierten die beiden Schiffe wegen der verfluchten Murlocs, als sie über das weite Meer nach Auberdine segelten. Jetzt liegen sie auf dem Grund des Ozeans als Trophäen für diese Satanskreaturen.\n\nBeide Kapitäne haben es in dieser Nacht nicht geschafft, ihre Schiffe zu verlassen. Ihre Logbücher und anderen Habseligkeiten befinden sich immer noch dort unten in Schließkassetten. Ich möchte Euch bitten, sie für uns zu beschaffen; es würde den Mannschaftsmitgliedern, die sich noch hier aufhalten, viel bedeuten.", progress = "Die Kapitäne dieser Schiffe waren gute Nachtelfen und sie haben ein besseres Schicksal als dieses verdient. Vielleicht ist die beste Möglichkeit, ihren Seelen Frieden zu geben, sich um ihr persönliches Eigentum zu kümmern.", completion = "Ihr habt uns hier in Auberdine einen großen Dienst erwiesen, Jungchen. Wir werden dafür sorgen, dass sich jemand ordentlich um ihr Eigentum kümmert.\n\nUnd was Euch angeht, bitte nehmt dies. Es ist das Geringste, das ich für jemanden tun kann, der den Mut hat, etwas in Ordnung zu bringen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWelldrip-HandschuheNoosegrip-Stulpen\n\nIhr bekommt außerdem:\n\n"},
[983] = {title = "Dröhnkiste 827", objective = "Sammelt 6 Kriecherbeine und baut sie in Dröhnkiste 827 ein.", description = "He! Helft mir bei meiner neuesten Erfindung, der Dröhnkiste. Man kann damit mit Leuten sprechen, die weit weg sind!\n\nVielleicht habt Ihr sie schon mal gesehen, das sind kleine Kästchen mit Hebeln daran. Ihr einziges Problem ist, dass sie ständig gewartet werden müssen.\n\nJede hat ein anderes Problem, aber ich hab mir etwas ziemlich Schlaues ausgedacht. Ich habe alle in der Nähe von Kreaturen platziert, die über die passenden Teile verfügen, um die jeweilige Maschine zu reparieren. Momentan hat Dröhnkiste 827 den Geist aufgegeben. Sie steht südlich von Auberdine, also gleich in der Nähe. Es werden sechs Kriecherbeine benötigt, um sie zu reparieren. Ich bezahl Euch auch dafür ...", progress = "Dröhnkiste 827 ist gespenstisch still. Eine einzelne blinkende Lampe zeigt an, dass sechs Kriecherbeine ins Gehäuse eingebaut werden müssen.", completion = "Sobald Ihr die Kriecherbeine in die Maschine eingebaut habt, hört Ihr, wie sich ein Getriebe in Gang setzt. Anhand der Klopfgeräusche, die aus der Dröhnkiste dringen, erkennt Ihr, dass Ihr die Kriecherbeine wohl an den richtigen Stellen eingebaut habt. Bald darauf beginnt die Maschine zu summen und Ihr könnt eine leise Stimme hören, die aus ihrem Inneren dringt.\n\n\"Hallo? Ähhh ... Hallo! Ihr habt sie repariert! Hier ist übrigens Wizbang! Vielen Dank ... He, Ihr habt nicht zufällig Lust, noch eine zu reparieren, was?\"", rewards = "Ihr bekommt:\n\n"},
[984] = {title = "Wie groß ist die Bedrohung?", objective = "Sucht in Dunkelküste nach einem verderbten Furbolglager und kehrt dann zu Terenthis in Auberdine zurück.", description = "Einige meiner Brüder konnten in Teldrassil vor einem verderbten Furbolg gerettet werden und ich habe geschworen, weitere Gräueltaten zu verhindern, bevor noch mehr von uns verletzt werden... oder schlimmer.\n\nIch habe auch in Dunkelküste schon die ersten Anzeichen von Verderbnis entdeckt, jedoch noch nichts gefunden, was auf Ausbreitung hindeutet. Ich denke, es wäre logisch, wenn man die Untersuchungen bei den Furbolgs fortsetzen würde. Würdet Ihr wohl eines ihrer Lager aufsuchen und zu mir zurückkehren, falls Ihr dort irgendwelche Anzeichen von Verderbnis entdeckt?", progress = nil, completion = "Das sind wahrlich schreckliche Neuigkeiten, &lt;Name&gt;.\n\nDa die Furbolgs so nah bei Auberdine leben, müssen wir uns auf das Unausweichliche vorbereiten.\n\nDanke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[985] = {title = "Wie groß ist die Bedrohung?", objective = "Tötet 8 Pfadfinder der Schwarzfelle und 5 Windsprecher und kehrt dann zu Terenthis in Auberdine zurück.", description = "Ihr habt Euer Talent im Ausspähen unserer Feinde bereits unter Beweis gestellt, <Name>. Aber habt Ihr auch das Zeug dazu, sie zu bekämpfen?\n\nNicht alle Abenteurer ziehen ein offenes Gefecht der Kunst der Verstohlenheit und des Ausweichens vor.\n\nWenn Ihr glaubt, der Aufgabe gewachsen zu sein, solltet Ihr Euch das Furbolglager südlich von Auberdine vornehmen. Das stellt momentan die größte Bedrohung für unser Volk dar. Ihr werdet dort ein paar Mitglieder des Schwarzfellstamms finden. Tötet 8 Pfadfinder und 5 Windsprecher und kommt dann zu mir zurück.", progress = nil, completion = "Wascht Euch das Blut von den Gewändern und trauert nicht über das, was Ihr tun musstet, &lt;Name&gt;. Lasst Euch lieber danken. Ihr habt die Bedrohung für unser Volk hier in Auberdine verringert, obwohl Dunkelküste durch die Auswirkungen des Teufelsmooses immer noch in Gefahr ist.", rewards = "Ihr bekommt:\n\n"},
[986] = {title = "Ein verirrter Meister", objective = "Sucht 5 feine Mondpirscherpelze und bringt sie Terenthis in Auberdine.", description = "<Name>, Eure Fertigkeiten haben mir bei meinen Bemühungen sehr geholfen. Kann ich es wagen, Euch dennoch erneut zu bitten, Grimmklaue und seinem Meister Volcor zu helfen? Ich könnte Euch dazu einen magischen Umhang anfertigen, mit dem Ihr ungehindert an den Kreaturen Dunkelküstes vorbeigelangt, während Ihr nach ihm sucht.\n\nUm den Umhang anzufertigen, benötige ich fünf Mondpirscherpelze von einer Mondpirschermatriarchin oder einem Mondpirscherpatriarchen, um genügend Material zur Verfügung zu haben. Die Katzen findet Ihr südlich von hier, in der Nähe des Flusses Wildbend, oder noch weiter im Süden, in der Nähe von Ashenvale.", progress = "Ich kann Euch nicht guten Gewissens erlauben, nach Volcor zu suchen, bevor ich Euren Umhang fertig habe.", completion = "Die eignen sich bestens, &lt;Name&gt;. Ich werde mich sofort an die Arbeit machen.\n\nGebt mir einen Moment Zeit und kommt dann wieder zu mir.\n\nOh, noch eines: sobald Ihr die Verzauberung des Umhanges benutzt, könnt Ihr nur noch eingeschränkt mit anderen interagieren. Ihr solltet, wenn möglich, nur mit ihnen sprechen. Andere Aktionen könnten die Illusion zerstören.", rewards = "Ihr bekommt:\n\n"},
[990] = {title = "Marsch nach Ashenvale", objective = "Sucht Raene Wolfrunner in Ashenvale auf.", description = "<Name>, meine Herrin Raene Wolfrunner erwartet Euch in Astranaar in Ashenvale. Mit Eurer Hilfe könnten wir vielleicht wenigstens eines Teils der Verderbnis Herr werden, die sich dort breit gemacht hat.\n\nGeht von hier aus nach Süden und haltet Euch dicht an der Straße. Wenn Ihr Euch an diese Richtungsangaben haltet, erreicht Ihr problemlos Euer Ziel.", progress = nil, completion = "Ah, ein &lt;Klasse&gt; aus Dunkelküste. Eine gute Entscheidung Selarins, Euch so schnell hierher zu schicken, &lt;Name&gt;. Ich wünschte, Eure Reise hierher hätte unter glücklicheren Umständen stattgefunden. Vielleicht können wir ja mit Eurer Hilfe einige Dinge verbessern.\n\nIch würde meinen Besuch mit einem Gespräch mit den anderen Bürgern von Astranaar beginnen. Einige können sicherlich Eure Hilfe gebrauchen.", rewards = "Ihr bekommt:\n\n"},
[991] = {title = "Raenes Säuberung", objective = "Sucht in Ashenvale nach Teronis.", description = "<Name>, ein alter Freund von mir unterstützt hier in Ashenvale ebenfalls die Schildwachen, aber er ist noch nicht zurückgekehrt.\n\nEr ging einer Spur nach, die zu einem Gegenstand führte, der seiner Meinung nach die Angriffe der Furbolgs auf unser Volk verlangsamen könnte - eine Rute, die von einem mittlerweile verstorbenen, bösen Hexer geschaffen wurde.\n\nVor seiner Abreise erwähnte er, dass er nach einem Edelstein für die Rute suchen wolle.\n\nEr meinte, dass dieser Edelstein möglicherweise in dem Schrein im Falathimsee am Fuße der Berge im Westen versteckt sei. Dort wurde der Edelstein jedenfalls aufbewahrt, bevor der Schrein überrannt worden ist.\n\nBitte, <Name>, findet meinen Freund.", progress = nil, completion = "Teronis' Körper liegt zerschmettert auf der Insel. Aus unbekanntem Grund haben die Murlocs von ihm abgelassen.\n\nDie tiefen Schnittwunden an seinem Kadaver stammen offensichtlich von den Waffen und Klauen der Murlocs.", rewards = "Ihr bekommt:\n\n"},
[992] = {title = "Gadgetzan Wassersondierung", objective = "Benutzt den unangezapften Wünschelrutenapparat in der Nähe des Teichs bei der Sandsorrow-Wache. Bringt den angezapften Wünschelrutenapparat zum Leitenden Feldmesser Fizzledowser nach Gadgetzan zurück, wenn Ihr die Probe entnommen habt.", description = "Wenn Ihr interessiert seid, hätten wir einen offenen Posten im Rang eines temporären Unterfeldmessers in der Gadgetzan Water Company.\n\nDa die Nomaden unsere Brunnen erobern, müssen wir weitere freie Wasserquellen ausschöpfen! Es gibt Wasser in der Wüste, aber nur für die, die klug genug sind, sie erst zu erforschen.\n\nNehmt diesen Wünschelrutenapparat und zapft damit eine Wasserprobe vom Teich in der Nähe der Sandsorrow-Wache. Er befindet sich direkt in Sichtweite der Trolle dort. Bringt mir den angezapften Apparat zurück, wenn Ihr fertig seid!", progress = "Willkommen, Unterfeldmesser <Name>! Habt Ihr Eure Aufgabe schon erfüllt?", completion = "Was ist das? Ihr seid in einen Hinterhalt von bösartigem, gruseligem Kriechgetier geraten? Oh, das sieht nicht gut aus für die Gadgetzan Water Company, nein, wirklich nicht...\n\nIch hätte Euch wohl von den Berichten erzählen sollen, die wir über verrückte Käferkreaturen erhalten, die anscheinend alles Wasser in der Wüste aufsaugen. Zuerst dachte ich, es wäre nur das Geschwafel eines Betrunkenen. Wir haben so schon genug Ärger mit den Nomaden; ich dachte, es wäre nur ein weiterer Schwindel von ihnen. Nun wissen wir wenigstens Bescheid!", rewards = "Ihr bekommt:\n\n"},
[993] = {title = "Ein verirrter Meister", objective = "Sucht Volcor in Dunkelküste und gebt ihm den verzauberten Mondpirscherumhang.", description = "Der Umhang ist fertig, <Name>. Jetzt ist es an der Zeit, Volcor zu suchen. Ich hoffe nur, dass wir es noch rechtzeitig schaffen.\n\nDie Magie des Umhangs hält nicht lang an, nachdem sie herbeigerufen wurde - etwa fünf Minuten. Es liegt an Euch zu entscheiden, wann Ihr sie benutzt: Ich schlage vor, dass Ihr damit wartet, bis Ihr Grimmklaue gefunden habt.\n\nFalls es wahr ist, was er mir erzählte, findet Ihr seinen Meister in einer Höhle südlich von hier. Grimmklaue wird an der Straße auf Euch warten. Gebt ihm ein Signal, indem Ihr winkt, sobald Ihr ihn gesehen habt, dann wird er Euch den Weg zu seinem Meister weisen.", progress = nil, completion = "Großartig! Terenthis hat jemanden gefunden, der mir helfen wird.\n\nUnd seht doch, ein Mondpirscherumhang... &lt;hustet&gt; Oh... das tut weh. Danke, &lt;Name&gt;.\n\nDie Furbolgs haben mich verwundet, bevor ich ihnen entkommen konnte. Lasst mich einen Moment ausruhen, dann sollte es mir wieder besser gehen und wir können uns weiter unterhalten.", rewards = "Ihr bekommt:\n\n"},
[994] = {title = "Flucht durch Gewalt", objective = "Beschützt Volcor, bis Ihr die Straße erreicht habt und sprecht dann mit Terenthis in Auberdine.", description = "Gut, <Name>, dann sei es Gewalt. Lasst uns hier verschwinden, sobald Ihr bereit seid. Wir werden uns unseren Weg hinunter zur Straße erkämpfen - Grimmklaue dürfte immer noch dort sein. Sobald wir sie erreicht haben, können wir uns trennen.\n\nTerenthis wird sofort Eure Version der Geschichte hören wollen, also geht nach Auberdine, sobald wir es hier herausgeschafft haben.", progress = nil, completion = "&lt;Name&gt;! Wie ich mich freue, dass Ihr erfolgreich zurückgekehrt seid. Eure Unterstützung für Volcor hat mich zuversichtlich gemacht, dass wir die bevorstehenden Herausforderungen hier in Dunkelküste und außerhalb meistern können.", rewards = "Ihr bekommt:\n\nUnerschütterlicher Sattelgurt"},
[995] = {title = "Flucht durch Verstohlenheit", objective = "Flieht aus der Furbolghöhle und trefft Euch in Auberdine mit Terenthis.", description = "Na gut... wenn Ihr sicher seid, werden wir uns hier hinausschleichen. Lasst uns verschwinden, sobald Ihr bereit seid.\n\nVergesst nicht, Euch in Auberdine mit Terenthis zu treffen, sobald Euch die Flucht gelungen ist. Ich werde mich auf eigene Faust dort hinbegeben, da ich wahrscheinlich schneller bin als Ihr.", progress = nil, completion = "&lt;Name&gt;! Wie ich mich freue, dass Ihr erfolgreich zurückgekehrt seid. Eure Unterstützung für Volcor hat mich zuversichtlich gemacht, dass wir die bevorstehenden Herausforderungen hier in Dunkelküste und außerhalb meistern können.", rewards = "Ihr bekommt:\n\nSkarabäusbeinkleider"},
[996] = {title = "Verderbte Windblüte", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[997] = {title = "Denalans Erde", objective = "Bringt Denalan am Al'Amethsee das Gebinde rarer Erde.", description = "Seid Ihr nach Süden unterwegs? Zum Al'Amethsee? Wenn dem so ist, möchte ich Euch um einen Gefallen bitten...\n\nMein Kollege Denalan hat am Ostende des Sees ein Lager aufgeschlagen, in dem er die Pflanzenwelt Teldrassils studiert und Experimente betreibt. Er hat in Darnassus ein Gebinde rarer Erde bestellt, und die Lieferung kam erst kürzlich mit Verspätung hier in Dolanaar an.\n\nWürdet Ihr ihm dieses Gebinde wohl bringen?", progress = "Habt Ihr etwas für mich?", completion = "Ah, es ist da! Ich habe schon eine ganze Weile auf diese rare Erde gewartet. Hoffentlich ist sie noch frisch...\n\nDanke, dass Ihr sie mir gebracht habt, &lt;Name&gt;. Ihr seid ein &lt;Volk&gt;, der sich noch die Zeit nimmt.", rewards = "Ihr bekommt:\n\n"},
[998] = {title = "Verderbte Windblüte", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[999] = {title = "Wenn Träume zu Alpträumen werden", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1000] = {title = "Die neue Grenze", objective = "Sprecht auf der Anhöhe der Ältesten in Thunder Bluff mit dem Erzdruiden Hamuul Runetotem über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Weitere Informationen erhaltet Ihr beim Erzdruiden Hamuul Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;.\n\nEs freut mich zu sehen, dass jemandem wie Euch das Wohlergehen der Natur am Herzen liegt. Die Geschichten über Eure großartigen Taten sind Euch vorausgeeilt und Ihr seid hier herzlich willkommen. Wenn ich Euch so sehe, erweckt Ihr in mir ein Gefühl der Zuversicht, dass der Zirkel des Cenarius genau die Hilfe bekommt, die er braucht.\n\nUnsere Verbindung zum Zirkel des Cenarius in Moonglade überwindet selbst völkische und politische Abgründe. Denkt daran, wenn Ihr im Namen des Zirkels agiert, dann wird Euch alles gut gelingen.", rewards = "Ihr bekommt:\n\n"},
[1001] = {title = "Dröhnkiste 411", objective = "Besorgt Euch 3 Drescheraugen von den Dunkelküstendreschern im tiefen Meer in der Nähe der Dröhnkiste 411.", description = "Aus dem Inneren der Maschine ist eine leise Stimme zu hören.\n\n\"Hier spricht Wizbang! Die nächste Dröhnkiste befindet sich nördlich von Auberdine, am Strand.\n\nAlso, es ist die Dröhnkiste mit der Nummer 411 und es werden 3 Drescheraugen benötigt, um sie zu reparieren. Sie befinden sich direkt vor der Küste! Die Dunkelküstendrescher... *Hick*... Tut mir Leid...\n\nÜbrigens, wie beim letzten Mal wird die Dröhnkiste Eure Belohnung ausspucken, sobald Ihr die Sachen in die Maschine eingebaut habt. *Hick*... Was? Nein, mir geht's gut!\"", progress = "Der Deckel der Maschine ist offen und scheint gespannt darauf zu warten, dass drei Drescheraugen eingebaut werden.", completion = "Die Dröhnkiste erwacht summend zum Leben, kaum dass Ihr die Drescheraugen eingebaut habt. Einen Moment lang ist nur statisches Rauschen zu hören, dann erklingt leise eine bekannte Stimme.\n\n\"Kriecherwein ist der Beste...\" *Hick*\n\n\"Was? Oh, Ihr habt sie schon repariert? Mann, Ihr seid abba schnell. Also, möchtet Ihr noch 'ne andere reparier'n?\"\n\nIhr meint zu hören, wie Flüssigkeit in einen Becher gegossen wird, gefolgt von lauten Schluckgeräuschen.", rewards = "Ihr bekommt:\n\n"},
[1002] = {title = "Dröhnkiste 323", objective = "Sammelt 6 Mondpirscherfangzähne und baut sie in Dröhnkiste 323 ein.", description = "Die Dröhnkiste gibt statische Geräusche von sich, als Wizbang zu sprechen beginnt.\n\n\"Die nächste Dröhnkiste ist Nummer 323. Schteht nördlich von Auberdine, aber... wo's das Bier? Wa...? Oh, schteht direkt an der Straße, kann man gar nicht verfehlen, gleich neben der Brücke.\"\n\nWizbang murmelt wirres Zeug vor sich hin, bevor Ihr ein lautes Schluckgeräusch hört.\n\n\"Der da fehlen Mondpirscherfangzähne... sechs davon.\"", progress = "Obwohl Ihr die sechs Mondpirscherfangzähne noch nicht eingebaut habt, meint Ihr doch, statische Geräusche und wirres Goblingebrabbel aus der Maschine dringen zu hören. Ob wohl ein anderer die Maschine bereits repariert hat?", completion = "Die Dröhnkiste wird plötzlich aktiv und Ihr hört das unverwechselbare Geräusch knirschender Zähne aus ihrem Inneren.\n\n\"Ssso, Ihr habt's also geschafft! Dassind ja groooßartige Neuigkeiten... Also... Warum zieht Ihr nich' weiter? Oh! Vielleicht wollt Ihr noch'n Job?\"", rewards = "Ihr bekommt:\n\n"},
[1003] = {title = "Dröhnkiste 525", objective = "Sammelt 4 ergraute Skalps von ergrauten Distelbären südlich von Auberdine und legt sie in die Dröhnkiste 525.", description = "Wizbangs zitternde Stimme übertönt die Blubber- und Tropfgeräusche, die aus dem Inneren der Maschine dringen.\n\n\"Näxte is' die Straße weiter runter nach Süden. Is' leicht zu find'n... direkt am Straßenrand... neben ei'm Sssaun. Glaub, ich hab sie hinner'n paar Büscheln verschteckt... Büschen. Hehehe... Jaaa, Dröhnkiste 525 fehlen ergraute Skalps von dies'n grauhaarigen Dischtelbären. Mann, das schpricht sich blöd. Dissstelbär... Hehehe...\"\n\nIhr hört weitere Schluckgeräusche, dann schaltet sich die Maschine aus. Plötzlich erwacht sie jedoch wieder zum Leben.\n\n\"4!\"", progress = "Ihr hört Gegröle aus der Dröhnkiste 525 dringen.\n\n\"Kriecherwein iss süß unn Drescherbier is toll, abba Mondpirscherfusel iss klasse. Ich mag nix mehr als Bier vom Distelbär unn bald schon krieg ich was davon!\"\n\nDer Deckel ist offen und wartet auf die vier ergrauten Skalps, während immer und immer wieder das Lied zum Besten gegeben wird.", completion = "Ihr habt also die Schkalps eingebaut? Das issja so toll... Wa...? Äh, ja, ich glaub, Ihr habt wohl gemerkt, dassich auch mit Euch schprechen kann, wenn die Dinger noch nich' eingebaut sind. Abba ich hab nich' gelogen, als ich sagte, dass die Maschinen kaputt waren!\n\nWisst Ihr, die Dröhnkisten sind nich' nur Kommunicketionsmittel, sondern brauen und destilliern auch noch guten Allohol. Tut mir Leid, dassich Euch'n bisschen reingelegt hab, abba die Nachtelfen finden's nich' so prickelnd, wenn ich in ihren Städten mit Schnaps handele. Ich hab in diese Kiste was ganz besonners getan, um Euch für Eure Bemüigkeiten zu danken. Prost!", rewards = "Ihr bekommt:\n\nWizbangs RupfensackWizbangs Spezialbräu"},
[1004] = {title = "Die neue Grenze", objective = "Sprecht auf der Anhöhe der Ältesten in Thunder Bluff mit dem Erzdruiden Hamuul Runetotem über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Weitere Informationen erhaltet Ihr beim Erzdruiden Hamuul Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;.\n\nEs freut mich zu sehen, dass jemandem wie Euch das Wohlergehen der Natur am Herzen liegt. Die Geschichten über Eure großartigen Taten sind Euch vorausgeeilt und Ihr seid hier herzlich willkommen. Wenn ich Euch so sehe, erweckt Ihr in mir ein Gefühl der Zuversicht, dass der Zirkel des Cenarius genau die Hilfe bekommt, die er braucht.\n\nUnsere Verbindung zum Zirkel des Cenarius in Moonglade überwindet selbst völkische und politische Abgründe. Denkt daran, wenn Ihr im Namen des Zirkels agiert, dann wird Euch alles gut gelingen.", rewards = "Ihr bekommt:\n\n"},
[1005] = {title = "Was dahinter lauert", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1006] = {title = "Was dahinter liegt", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1007] = {title = "Die antike Statuette", objective = "Bringt Talen im Lager in der Nähe des Zoramstrands die antike Statuette.", description = "Ich würde Euch gern eine Aufgabe übertragen, <Name>.\n\nIch war auf meinem kleinen Schiff und kreuzte über den versunkenen Ruinen von Zoram, als ich plötzlich von Naga angegriffen wurde, die aus dem Wasser stießen und mich mit ihren Klauen beharkten! Ich floh und nahm alle Vorräte mit, die ich tragen konnte, um dieses bescheidene Lager zu errichten.\n\nAls ich jedoch die Küste erreichte und weglief ... verlor ich meinen liebsten Besitz.\n\nBitte, <Name>, geht zu dem Ort vor der Küste im Norden, an dem ich in den Hinterhalt geriet, und sucht dort nach einer antiken Statuette. Sie ist der Grund, warum ich die Gefahren des Zoramstrands auf mich genommen habe.", progress = "Habt Ihr die Statuette gefunden, <Name>?", completion = "Ihr habt sie gefunden! Danke, &lt;Name&gt;!\n\nDie alte Stadt Zoram birgt viele Geheimnisse, und diese Statuette könnte der Schlüssel zu vielen davon sein.", rewards = "Ihr bekommt:\n\n"},
[1008] = {title = "Der Zoramstrand", objective = "Bringt Shindrell Swiftfire in Astranaar 20 Köpfe von Rächerflossen.", description = "Böses lauert an unserer nordwestlichen Küste, die als Zoramstrand bekannt ist.\n\nEs ist die Ruhestätte der untergegangenen Stadt Zoram, die während der großen Teilung zerstört wurde und im Meer versank. Die Nachtelfen verloren sie vor Unzeiten. Sie war verloren und fast vergessen.\n\nJetzt allerdings sind die Naga zurückgekehrt, aber warum, wissen wir nicht. Es ist auch unwichtig. Wir müssen diese Scheusale vernichten und zurück in die Tiefe treiben!\n\nKehrt zu mir zurück, wenn Ihr Eure Mission abgeschlossen habt.", progress = "Wir dürfen nicht zulassen, dass die Naga unsere Küsten besetzen, <Name>. Es ist wichtig, dass Ihr zum Zoramstrand reist und Eure Mission beendet.", completion = "Sehr gut, &lt;Name&gt;. Sehr löblich, was Ihr da am Zoramstrand gegen die Naga ausgerichtet habt.\n\nIch kann mir denken, dass Ihr es nicht leicht hattet, denn die Kraft und Arglist der Naga sind den Nachtelfen wohl bekannt. Wir wissen es, weil wir eine gemeinsame Vergangenheit haben.\n\nEine Vergangenheit, die sich auf keinen Fall wiederholen darf.", rewards = "Ihr bekommt:\n\n"},
[1009] = {title = "Ruuzel", objective = "Bringt Talen im Lager in der Nähe des Zoramstrands den Ring von Zoram.", description = "Ich fürchte, die Geheimnisse der antiken Statuette werden für immer verborgen bleiben, wenn Ihr nicht den Schlüssel zu ihrem antiken Schloss findet.\n\nDieser Schlüssel ist ein Ring, der Ring von Zoram. Er gehörte einst den Herrschern dieser Stadt, bevor sie in den Wellen der großen Teilung unterging.\n\nÜber Jahre hinweg war der Ring verloren, aber die Naga haben ihn vor kurzem gefunden.\n\nRuuzel, ihr Anführer, haust auf einer Insel am Nordrand von Zoram. Bitte, <Name>, holt mir meinen Ring!", progress = "Es heißt, dass der Ring von Zoram der Schlüssel zu allen Schlössern der Stadt sei. Habt Ihr ihn, <Name>?", completion = "Ihr habt den Ring gefunden! Danke, &lt;Name&gt;. Bitte nehmt das hier als Lohn und wisset, dass ich Eure heutige Tat nie vergessen werde.", rewards = "Ihr bekommt:\n\nRoben der Antike"},
[1010] = {title = "Bathranshaar", objective = "Bringt Orendil Broadleaf in Ashenvale 5 Bathranshaar-Pflanzen.", description = "Es gibt eine Pflanze, die früher einmal in den alten Ruinen von Bathrans Schlupfwinkel im Norden wuchs. Die Pflanze namens Bathranshaar war als Heilmittel für Krankheiten des Geistes bekannt.\n\nEin Kind im Dorf ist krank geworden und ich glaube, dass es sich nicht nur um eine körperliche Krankheit handelt. Würdet Ihr wohl zu Bathrans Schlupfwinkel reisen und dort für mich nach Bathranshaar suchen? Ich könnte es brauchen, wenn ich das Kind richtig behandeln soll.\n\nBathrans Schlupfwinkel liegt nördlich von Maestras Posten und gleich südlich der Grenze zu Dunkelküste.", progress = "Habt Ihr das Bathranshaar gefunden, <Name>? Das Kind wird von Stunde zu Stunde schwächer...", completion = "Ah, Ihr habt das Haar! Jetzt kann ich ein Heilmittel für das Kind zusammenmischen und beten, dass mein Gebräu auch wirkt.\n\nUnd... die Verlassenen sind in Bathrans Schlupfwinkel? Das ist höchst beunruhigend. In der Tat höchst beunruhigend...", rewards = "Ihr bekommt:\n\n"},
[1011] = {title = "Verlassenenkrankheit", objective = "Bringt Kayneth Stillwind in Forest Song eine Krankheitsflasche.", description = "Die Verlassenen, der untote Arm der Horde, haben sich in Ashenvale eingeschlichen und treiben sich in unseren Ruinen und Grabhügeln herum. Wir glauben, dass sie die Krankheit im Land der Nachtelfen verbreiten wollen. Wir müssen das genau wissen!\n\nDie Verlassenen haben südlich von hier, in der Nähe des Dor'danil-Grabhügels, ein Lager, in dem sie Gifte und Krankheiten entwickeln und in Flaschen füllen. Kämpft Euch in das Lager hinein und stehlt eine Krankheitsflasche. Bringt mir eine solche Flasche. Ich werde sie testen und herausfinden, was sie bewirkt.", progress = "Habt Ihr das Lager gefunden, <Name>? Habt Ihr eine Krankheitsflasche?", completion = "Sehr gut, &lt;Name&gt;. So... ich teste jetzt den Inhalt dieser Flasche, dann werden wir bald wissen, welche Ziele die Verlassenen verfolgen!", rewards = "Ihr bekommt:\n\n"},
[1012] = {title = "Irrsinnige Druiden", objective = "Tötet die Druiden Taneel Darkwood, Uthil Mooncall und Mavoris Cloudsbreak und kehrt dann zu Kayneth Stillwind in Forest Song zurück.", description = "Als ich mich mit den Giften der Verlassenen abplagte, hatte ich eine Vision. Ich sah die Druiden des Dor'danil-Grabhügels vergiftet... ermordet von den Untoten! Sie sind jetzt Geister, die getrennt von ihren Körpern und in den Wahnsinn getrieben ziellos umherirren.\n\nIhr müsst den Dor'danil-Grabhügel betreten und die früheren großen Anführer vernichten, damit die Geister der Druiden eines Tages wieder Frieden finden: Taneel Darkwood, Uthil Mooncall und Mavoris Cloudsbreak.\n\nTut dies und kehrt dann zu mir zurück.", progress = "Der Zorn der Druiden von Dor'danil verfolgt mich immer noch in meinen Träumen, <Name>. Ihr müsst ihre Anführer vernichten!", completion = "Ich fühlte, dass der Zorn der Dor'danil-Grabhügel nachließ und wusste, dass Ihr Euren Auftrag erfüllt hattet.\n\nWas Ihr tun musstet, war grausam, &lt;Name&gt;, denn die Geister, die Ihr vernichten solltet, waren doch nur unschuldige Opfer der Bösartigkeit der Verlassenen. Hoffen wir, dass auch die anderen wahnsinnigen Geister endlich Ruhe finden, da sie jetzt vernichtet sind.", rewards = "Ihr bekommt:\n\nEmils Marke"},
[1013] = {title = "Das Buch von Ur", objective = "Bringt dem Bewahrer Bel'dugur im Apothekarium in Undercity das Buch von Ur.", description = "<Name>, in der Burg Shadowfang gibt es ein Buch, das Buch von Ur, das ich unbedingt in meiner Sammlung haben möchte. Ur war einst ein großer Magier aus Dalaran bevor die Geißel kam. Seine Studien anderer Welten sind von großem Wert für... bestimmte Kreise der Verlassenen.\n\nBetretet die Burg Shadowfang und sucht das Buch. Bringt es mir, dann kann ich unserer dunklen Fürstin von Euren Diensten berichten...", progress = "Habt Ihr das Buch gefunden, <Name>?", completion = "Sehr gut. Dieses Buch ist eine wunderbare Ergänzung meiner Sammlung der Werke Urs. Er wusste so viel, doch sein Gewissen hielt ihn von der wahren Macht zurück. Und als die Geißel kam und seine Kraft auf die Probe stellte, versagte er.\n\nWir Verlassene können uns eine solche Schwäche nicht leisten, wenn wir überleben wollen ...\n\n... wenn wir erobern wollen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErgraute StiefelStahlschnallenarmschienen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1014] = {title = "Arugal muss sterben", objective = "Tötet Arugal und bringt Dalar Dawnweaver in dem Grabmal seinen Kopf.", description = "Arugal lebt immer noch in der Burg Shadowfang. Wir können Silberwald erst dann als strategische Festung für die dunkle Fürstin beanspruchen, wenn Arugal erschlagen ist.\n\nIch werde mich darum kümmern, seine Magie zu neutralisieren, <Name>. Ich überlasse es jedoch Euch, für Arugals Tod zu sorgen, den er mehr als verdient.\n\nReist zur Burg Shadowfang und setzt Arugals üblen Zaubern ein für alle Mal ein Ende. Bringt mir den Kopf dieses niederträchtigen Hexers!", progress = "Da Arugal jetzt tot ist, können wir die Festung der dunklen Fürstin in Lordaeron stärken.", completion = "Der Silberwald ist jetzt endlich aus den Klauen dieses elenden Arugal befreit. Ihr habt der dunklen Fürstin einen großen Dienst erwiesen, &lt;Name&gt;. Eure Beharrlichkeit soll belohnt werden.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nArkane Intelligenz\n\nIhr bekommt:\n\nSiegel von Sylvanas"},
[1015] = {title = "Die neue Grenze", objective = "Sprecht in der Enklave des Cenarius in Darnassus mit dem Erzdruiden Fandral Staghelm über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Sprecht in Darnassus mit dem Erzdruiden Fandral Staghelm, er hat weitere Informationen!", progress = nil, completion = "Was macht Euch glauben, dass ich mich von Euresgleichen belästigen lasse, &lt;Klasse&gt;? Wartet - lasst mich meine wichtigen Tagesgeschäfte unterbrechen, damit ich Euch helfen kann, irgendwo ein Dingelchen zu finden. Wahrhaftig, das Wohlergehen von Darnassus - ach was, von ganz Teldrassil ist nicht so wichtig wie die Beschaffung von Flitterzeug für Eure Sammlung.\n\nDiese Narren in Moonglade vergeuden meine Zeit mit ihrem Hilferuf, und jetzt muss ich mir das hier antun!", rewards = "Ihr bekommt:\n\n"},
[1016] = {title = "Elementararmschienen", objective = "Sammelt 5 intakte Elementararmschienen und wendet die Rolle der Bestimmung darauf an. Bringt danach der Schildwache Velene Starstrike in der Silberwindzuflucht die Rolle der Bestimmung.", description = "Nehmt diese Rolle der Bestimmung; sie kann den Schöpfer dieser Elementare bestimmen. Aber Ihr werdet etwas von ihnen benötigen, um es als Reagenz zum Fokussieren der Magie dieser Rolle zu verwenden; ihre Armschienen sollten hervorragend dafür geeignet sein.\n\nEin paar wenige intakte Armschienen dieser Kreaturen dürften reichen. Die anderen Armschienen werden für unsere Zwecke nutzlos sein, aber sie könnten einem Händler etwas wert sein, wenn Ihr sie verkaufen wollt. Nachdem Ihr die intakten Armschienen habt, versucht die Rolle zu verwenden. Kehrt mit den Ergebnissen zu mir zurück und dann werden wir weitersehen.", progress = "Da Ihr die Armschienen zerstören müsst, um die Elementare zu töten, wird es möglicherweise schwierig sein, genau jene zu finden, die die Informationen enthalten, die von der Rolle der Bestimmung benötigt werden. Ihr könnt Armschienen auch mit anderen tauschen, um die zu erhalten, die Ihr benötigt, aber vielleicht habt Ihr das bestimmte Dokument ja auch bereits?", completion = "Gut gemacht, &lt;Name&gt;, das sollte uns die Informationen liefern, die wir brauchen, um den Schuldigen zu entlarven. Hättet Ihr nicht Lust, den Magier auszuschalten, der unsere Teiche mit verderbten Elementaren überschwemmt? Die Verderbnis von Ashenvale und darüber hinaus dreht mir ja bereits den Magen um. Dass ein Hexer versucht, es noch weiter zu zerstören, macht mich ganz krank. Wir sollten ihn dafür bezahlen lassen.", rewards = "Ihr bekommt:\n\n"},
[1017] = {title = "Magier-Beschwörer", objective = "Erschlagt Sarilus Foulborne und bringt Schildwache Velene Starstrike in der Silberwindzuflucht seinen Kopf.", description = "Es gibt nur einen untoten Magier im Brachland, der in der Lage wäre, so viele Wasserelementare zu entweihen. Er ist auch der Einzige, der dumm genug wäre, es zu versuchen. Sarilus Foulborne sitzt wahrscheinlich jetzt gerade oben auf dem Glutnebelgipfel und lacht mich aus.\n\n<Name>, Ihr müsst Euch in Feindesland begeben und diesen Übeltäter vernichten. Ich habe genug von seinem Schwachsinn und wir müssen ihm zeigen, was mit jenen geschieht, die die Schildwachen verärgern.\n\nVernichtet ihn und bringt mir seinen Kopf. Vorsicht allerdings, die Horde könnte nach Euch Ausschau halten.", progress = "Ist es vollbracht? Ist Sarilus Foulborne tot?", completion = "Das hat ihm sein widerliches Grinsen ein für alle Mal aus dem Gesicht gewischt. Das habt Ihr sehr gut gemacht, &lt;Name&gt;. Nehmt das hier, das Licht von Elune, und trinkt davon, wenn alles verloren scheint und Ihr dem Tod nahe seid. Es könnte Euch retten, so die Göttin es will.", rewards = "Ihr bekommt:\n\nLicht von Elune"},
[1018] = {title = "Die neue Grenze", objective = "Sprecht auf der Anhöhe der Ältesten in Thunder Bluff mit dem Erzdruiden Hamuul Runetotem über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Weitere Informationen erhaltet Ihr beim Erzdruiden Hamuul Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;.\n\nEs freut mich zu sehen, dass jemandem wie Euch das Wohlergehen der Natur am Herzen liegt. Die Geschichten über Eure großartigen Taten sind Euch vorausgeeilt und Ihr seid hier herzlich willkommen. Wenn ich Euch so sehe, erweckt Ihr in mir ein Gefühl der Zuversicht, dass der Zirkel des Cenarius genau die Hilfe bekommt, die er braucht.\n\nUnsere Verbindung zum Zirkel des Cenarius in Moonglade überwindet selbst völkische und politische Abgründe. Denkt daran, wenn Ihr im Namen des Zirkels agiert, dann wird Euch alles gut gelingen.", rewards = "Ihr bekommt:\n\n"},
[1019] = {title = "Die neue Grenze", objective = "Sprecht in der Enklave des Cenarius in Darnassus mit dem Erzdruiden Fandral Staghelm über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Sprecht in Darnassus mit dem Erzdruiden Fandral Staghelm, er hat weitere Informationen!", progress = nil, completion = "Was macht Euch glauben, dass ich mich von Euresgleichen belästigen lasse, &lt;Klasse&gt;? Wartet - lasst mich meine wichtigen Tagesgeschäfte unterbrechen, damit ich Euch helfen kann, irgendwo ein Dingelchen zu finden. Wahrhaftig, das Wohlergehen von Darnassus - ach was, von ganz Teldrassil ist nicht so wichtig wie die Beschaffung von Flitterzeug für Eure Sammlung.\n\nDiese Narren in Moonglade vergeuden meine Zeit mit ihrem Hilferuf, und jetzt muss ich mir das hier antun!", rewards = "Ihr bekommt:\n\n"},
[1020] = {title = "Orendils Heilmittel", objective = "Bringt Pelturas Whitemoon in Astranaar Orendils Heilmittel.", description = "<Name>, ich habe ein Heilmittel entwickelt, mit dem man dem erkrankten Kind bestimmt helfen kann. Bringt es nach Astranaar und gebt es dem Vater des Kindes, Pelturas Whitemoon.\n\nUm nach Astranaar zu gelangen, folgt der Straße gen Süden und dann gen Osten.", progress = "Ich muss mich entschuldigen, aber ich habe jetzt keine Zeit, um zu plaudern. Meine Tochter Relara ist todkrank!", completion = "Das ist von Orendil?\n\nSeine Fertigkeiten in Kräuter- und Heilkunde sind enorm. Dieses Heilmittel gibt mir Hoffnung, dabei hatte ich schon fast aufgegeben...", rewards = "Ihr bekommt:\n\n"},
[1021] = {title = "Elende Satyrn! Die Dryaden sind in Gefahr!", objective = "Sucht in Xavian nach Anilia.", description = "Ich weiß zwar nicht, wer Ihr seid, aber ich brauche Eure Hilfe. Meine Schwestern wollten den Satyrn den Zweig des Cenarius abnehmen. Sie sagten, dass sie bald zurück sein werden, aber das war vor zwei vollen Tagen!\n\n<Name>, Ihr müsst sie finden! Sie wollten nach den Ruinen eines Nachtelfentempels in Xavian im Nordosten suchen. Ich weiß nicht, was ich davon halten soll. Sucht nach Anilia, sie wollte sie bei der Suche führen.", progress = nil, completion = "Den klaffenden Wunden in ihrer Seite nach zu urteilen, steht Anilia an der Schwelle des Todes.", rewards = "Ihr bekommt:\n\n"},
[1022] = {title = "Das heulende Tal", objective = "Begebt Euch ins heulende Tal, studiert den Folianten von Mel'Thandris und kehrt dann zur Schildwache Melyria Frostshadow beim Schrein von Aessina zurück.", description = "Obwohl wir viele Mittel und große Bemühungen investiert haben, um auch die letzten Dämonen aus dem Teufelswald im Norden zu vertreiben, hatten wir nur wenig Erfolg damit. Wir konnten jedoch einen Großteil der Dämonen von Ashenvale fern halten.\n\nIm Norden, nahe der Grenze zum Teufelswald, wurde der verfallene Mel'Thandris-Schrein von rätselhaften Wolfmenschen übernommen. Ihre Schreie, die einem das Blut in den Adern gerinnen lassen, haben dem als \"Das heulende Tal\" bekannten Gebiet seinen Namen gegeben. Der Foliant von Mel'Thandris, der im Schrein aufbewahrt wird, könnte etwas Licht darauf werfen, warum die Wolfmenschen hier sind.", progress = nil, completion = "Der Foliant von Mel'Thandris funktioniert auf merkwürdige Weise. Die Ereignisse, die er enthält, die Ereignisse, die er zeigt... Niemand versteht wirklich, wie er funktioniert.\n\nDennoch ist es klar, dass man näher untersuchen sollte, was die Priesterin Starsong bekommen hat - die Sense von Elune.", rewards = "Ihr bekommt:\n\n"},
[1023] = {title = "Raenes Säuberung", objective = "Sucht den leuchtenden Edelstein und bringt ihn zusammen mit Teronis' Tagebuch zu Raene Wolfrunner in Astranaar.", description = "Während Ihr Teronis Habseligkeiten durchstöbert, stoßt Ihr auf ein Tagebuch, das noch in gutem Zustand ist.\n\nIhr nehmt das Tagebuch und lasst Teronis' Kadaver so wie er ist zurück.\n\nJetzt müsst Ihr nur noch eines tun: den Edelstein finden, den Teronis suchte. Raene deutete an, dass er sich in diesem Gebiet befinden würde. Vielleicht haben ihn die Murlocs ...", progress = "Ah, willkommen zurück, <Name>.", completion = "Wie schrecklich, &lt;Name&gt;. Teronis ist tot?!\n\nIch werde ihn später betrauern, aber jetzt müssen wir uns zuerst auf unsere Aufgaben konzentrieren. Ich schicke ein paar der Schildwachen aus, um Teronis' Leiche so schnell wie möglich herzubringen.\n\nIhr habt Teronis' Tagebuch und den Edelstein, den er suchte. Denkt Ihr, Ihr seid imstande, diesen Auftrag auszuführen? Es würde mich beruhigen, wenn ich wüsste, dass sein Tod nicht umsonst war.", rewards = "Ihr bekommt:\n\n"},
[1024] = {title = "Raenes Säuberung", objective = "Sucht Shael'dryn beim Mondbrunnen im Nordosten auf.", description = "Ihr werdet selbst Nachforschungen anstellen müssen, aber gemäß Teronis' Notizen scheint es unsere nächste Aufgabe zu sein, die anderen Teile der Rute zu finden, die Dartol erschuf. Ich würde mich zunächst zum Mondbrunnen östlich des Irissees begeben. Wenn Ihr bereit seid, folgt der Straße und wendet Euch gen Norden, wenn Ihr einen kleinen Sitzbereich zu Eurer Linken erreicht.\n\nDort findet Ihr eine Dryade namens Shael'dryn, die Euch eine bessere Führerin sein wird. Sucht sie auf.\n\nBehaltet den Edelstein - Shael'dryn wird ihn brauchen, um Euch bei der Wiederherstellung der Rute zu helfen.", progress = "Hallo. Wie geht es Euch?", completion = "Oh, Raene hat Euch geschickt? Dann muss es wohl wirklich dringlich sein. Wie kann ich Euch helfen?", rewards = "Ihr bekommt:\n\n"},
[1025] = {title = "Eine aggressive Verteidigung", objective = "Tötet 1 Höhlenbehüter, 2 Ursa, 10 Totemiker sowie 12 Krieger der Fäulnisklauen und kehrt dann zu Raene Wolfrunner in Astranaar zurück.", description = "Bevor Ihr zum Mondbrunnen aufbrecht, habe ich noch eine andere Aufgabe für Euch, wenn Ihr gern Eure Fertigkeiten auf die Probe stellen und dem Volk von Ashenvale helfen würdet.\n\nEntlang der Straße, die nach Osten führt, haben Furbolgs kurz vor dem Falfarren Reisende angegriffen. Ihre gequälten Seelen nähren sich von Angst und sie stillen ihren Appetit mit dem Blut Unschuldiger.\n\nHelft den Schildwachen, das Land zu schützen, indem Ihr diesen Monstern dieselbe Gnade zeigt, die sie uns erwiesen haben.\n\nIch glaube, ihre Lager liegen südlich der Straße ... seid vorsichtig.", progress = "Die Furbolgs waren nicht immer unser Feind, <Name>. Aber die Zeiten ändern sich, und die Zeiten hier in diesen dunklen Wäldern sind nicht länger friedlich.", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Danke.", rewards = "Ihr bekommt:\n\nSaftiges MaisbrotMelonensaft"},
[1026] = {title = "Raenes Säuberung", objective = "Sucht den hölzernen Schlüssel und das Teil von Dartols Rute, bevor Ihr zu Shael'dryn beim Mondbrunnen zurückkehrt.", description = "Ich wünschte, Ihr hättet bessere Nachrichten.\n\nRaene hat Recht, ich weiß von Dartols Werk und den Treants, den Baumwesen in diesem Gebiet - zumindest wusste ich es einst. Heute sind sie verderbt, ihre Natur verzerrt.\n\nFalls es Euer Ziel ist, das nächste Teil der Rute zu finden, solltet Ihr zunächst den Schlüssel suchen, mit dem die Truhe geöffnet werden kann, in dem es sich befindet.\n\nEiner der Treants nordöstlich von hier in der Nähe des Teufelswalds hat ihn. Sobald Ihr ihn habt, sucht nach einem kleinen Tal westlich der Straße nahe der Grenze zum Teufelswald... die Truhe ist dort irgendwo versteckt.", progress = "Es bestürzt mich sehr, dass die Treants verderbt wurden. Ich wünschte, ich könnte mehr tun, um ihnen zu helfen.", completion = "Wie ich mich freue, dass Ihr zurück seid, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[1027] = {title = "Raenes Säuberung", objective = "Sucht das letzte Teil von Dartols Rute und bringt es Shael'dryn beim Mondbrunnen.", description = "Das letzte Teil der Rute wurde in die Obhut der Druiden von Dor'danil gegeben. Ich habe keine Ahnung, wo sie es versteckt haben. Es tut mir Leid, dass ich Euch da nicht weiterhelfen kann.\n\nIch kann Euch nur sagen, folgt der Straße, die zum Brachland führt. Die Druiden suchten östlich dieser Straße Zuflucht, aber sie werden Euch nicht viel helfen können: Sie wurden kürzlich getötet ... Ich mag gar nicht darüber nachdenken.\n\nWenn Ihr das letzte Teil gefunden habt, bringt es mir, dann helfe ich Euch, die Rute wieder zusammenzusetzen.", progress = "Habt Ihr das letzte Teil der Rute gefunden, <Name>?", completion = "Ihr habt das letzte Teil gefunden? Wie wunderbar für Euch... und für Raene.\n\nDann sollten wir beginnen, sie zu reparieren, meint Ihr nicht?", rewards = "Ihr bekommt:\n\n"},
[1028] = {title = "Raenes Säuberung", objective = "Sucht den verborgenen Schrein und verzaubert Dartols Rute erneut.", description = "Hier habt Ihr die vollständige Rute, <Name>. Es war nicht schwer, sie wieder zusammenzusetzen... Den Schrein zu finden, der die Kraft hat, sie wieder aufzuladen, ist der schwierige Teil.\n\nMit etwas Konzentration und Einsatz sollte es für jemanden wie Euch, der bereits so viel erreicht hat, allerdings nicht zu schwer sein.\n\nGeht von hier aus nach Südosten - es gibt nur wenige Wege, also seid vorsichtig - und behaltet immer den Norden im Auge. Der Schrein liegt in den Bergen verborgen, die dieses Tal umgeben.\n\nDort angekommen legt Ihr die Rute in den Schrein... der Rest ist Magie. Hehe.", progress = "Ihr spürt eine subtile, doch mächtige Kraft innerhalb des Schreins und zwischen den Bäumen der Umgebung.\n\nKaum legt Ihr die Rute in den Schrein, erwacht ein sanftes Dröhnen um Euch herum und der Schrein beginnt zu glühen...", completion = "Als das Glühen erlischt, seht Ihr die erneut verzauberte Rute im Becken des Schreins liegen.", rewards = "Ihr bekommt:\n\nDartols Rute der Transformation"},
[1029] = {title = "Raenes Säuberung", objective = "Kehrt zu Raene Wolfrunner in Astranaar zurück.\n\nBereitgestellter Gegenstand: \n", description = "Ich schlage vor, dass Ihr Raene aufsucht und sie wissen lasst, dass die Rute fertig gestellt ist. Sie weiß bestimmt, was Ihr als Nächstes tun solltet.\n\nViel Glück, <Name>.", progress = nil, completion = "Ihr habt die Rute wieder zusammengesetzt, die Teronis finden wollte? Wie schön, das zu hören.\n\nTeronis wäre stolz gewesen, wenn er gesehen hätte, dass seine Aufgabe selbst nach seinem tragischen Ende noch fortgeführt wurde.", rewards = "Ihr bekommt:\n\n"},
[1030] = {title = "Raenes Säuberung", objective = "Sucht einen nicht verderbten Furbolg und benutzt die Macht von Dartols Rute der Transformation, um mit ihm zu sprechen.\n\nBereitgestellter Gegenstand: \n", description = "Leider bin ich mir nicht ganz sicher, was er als Nächstes vorhatte.\n\nWenn es wahr ist, was er über die Macht der Rute sagte, könnt Ihr mit ihrer Hilfe eine völlig andere Gestalt annehmen. Welche Gestalt weiß ich allerdings nicht.\n\nVielleicht wollte er ihre Kräfte nutzen, um näher an die besudelten Furbolgs heranzukommen, aber selbst die nicht verderbten Kreaturen hätten ihn getötet, wäre er nicht vorsichtig gewesen. Durch die Rute verwandelt, hätte Dartol wahrscheinlich mit einem Furbolg gesprochen, der gegen die Auswirkungen des Teufelsmooses gefeit ist.\n\nIhr solltet Eure Suche südöstlich des Mystralsees beginnen.", progress = nil, completion = "Ja, ja... Ihr seid von meiner Art, aber immer noch ganz. Immer noch rein.\n\nIch weiß nicht, wie Ihr den Gräueltaten entkommen konntet, die die Nachtelfen an unserem Volk begangen haben, aber es freut mich zu wissen, dass ich nicht mehr allein bin.\n\nVerderbnis pulsiert jetzt in den Adern unseres Volkes. Verderbnis, die die so stolzen Nachtelfen über uns gebracht haben. Sie sind es, die unserem Volk das angetan haben... Sie sind es, denen ich die Schuld dafür gebe, dass ich von meinem Stamm verstoßen wurde.\n\nNachts kann ich immer noch ihre Lagerfeuer in der Dunkelheit brennen sehen.", rewards = "Ihr bekommt:\n\n"},
[1031] = {title = "Der Zweig des Cenarius", objective = "Tötet Geltharis und bringt Illiyana beim Schrein von Aessina den Zweig des Cenarius.", description = "Anilia legt Euch die Hände auf die Schultern und zieht Euch zu sich heran. Nach Luft ringend zeigt sie in Richtung des Bogens im Norden, bevor sich ihre Augen schließen und sie einen letzten, keuchenden Atemzug ausstößt. \"Er hat ihn... Geltharis...\" In Eurem Herzen wisst Ihr, dass es Anilias letzter Wunsch war, den Zweig des Cenarius wieder in den Händen der Dryaden zu sehen.", progress = "Habt Ihr sie gefunden? Was hat Anilia gesagt? Wo ist sie?", completion = "Anilia ist tot? Nein... das kann nicht sein! Noch gestern sind wir zusammen durch die Wälder getollt und haben gespielt.\n\nDiese Zeiten sind wohl jetzt vorbei...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFeen-MantelHellschuppengurt\n\nIhr bekommt außerdem:\n\n"},
[1032] = {title = "Satyrn schlachten!", objective = "Bringt Illiyana im Schrein von Aessina 16 Satyrhörner.", description = "Ich kann nicht glauben, dass Anilia von uns gegangen ist... Wir haben doch immer zusammen in den Wäldern gespielt. Ich fühle beinahe so etwas wie... Trauer.\n\nEs gibt aber etwas, das mich vielleicht aufheitern könnte! Bitte, erschlagt die Satyrn, die mir Anilia genommen haben! Bringt mir ihre Hörner als Beweis Eurer Taten und Ihr könnt Euch auf ewig meines Dankes gewiss sein.", progress = "Bitte, helft mir Anilias Tod zu rächen.", completion = "Danke, &lt;Volk&gt;, Ihr seid sehr freundlich. Der Geist meiner Schwester ist dankbar für Eure Bemühungen.", rewards = "Ihr bekommt:\n\n"},
[1033] = {title = "Elunes Träne", objective = "Bringt Pelturas in Astranaar die Träne von Elune.", description = "Ich hatte gehofft, Orendils Heilmittel würde Relara retten, aber ich fürchte, es hat die Krankheit, die in meinem Kind wütet, nur gedämpft. Wir müssen eine stärkere Medizin finden! Zum Glück hat mir Orendil von weiteren Arzneien erzählt, sollte seine Erste versagen.\n\nTräne von Elune ist eine Gesteinsart, die nur an einem Ort vorkommt: auf der Insel im Irissee, östlich von Astranaar. Orendil sagte, der Stein könne Verderbnis wegwaschen ... Bitte, <Name>, bringt mir eine Träne von Elune und betet, dass sich die Erkrankung meiner Tochter damit heilen lässt!", progress = "Habt Ihr den Irissee gefunden, <Name>? Habt Ihr die Träne?", completion = "Oh, Ihr habt sie gefunden! Ich werde die Träne in einen Eintopf geben und beten, dass meine Tochter davon geheilt wird.\n\nDanke! Danke, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[1034] = {title = "Die Sternenstaubruinen", objective = "Bringt Pelturas in Astranaar 5 Hand voll Sternenstaub.", description = "Die Träne von Elune hat einen Teil der Erkrankung meiner Tochter weggewaschen. Ihre Alpträume haben nachgelassen und ich danke der Göttin für ihren Segen. Aber... immer noch wütet das Fieber in ihr.\n\nOrendil erzählte mir von einem gefrorenen Staub, den man in den Sternenstaubruinen findet. Vielleicht kann man damit Relaras Fieber senken. Sammelt etwas von diesem Staub und kommt dann bitte wieder zu mir zurück.\n\nDie Sternenstaubruinen liegen im Süden, <Name>. Möge Elune Eure Reise beschleunigen.", progress = "Habt Ihr den Sternenstaub schon, <Name>?", completion = "Ihr habt den Staub! Ich werde daraus eine Breipackung machen - vielleicht kann man damit Relaras Fieber senken.\n\nNochmals danke, &lt;Name&gt;. Ohne Eure Hilfe würde mein Kind sicherlich sterben.", rewards = "Ihr bekommt:\n\n"},
[1035] = {title = "Fallenskysee", objective = "Holt von dem Schattendickichtorakel einen gefallenen Mondstein und bringt ihn Pelturas in Astranaar.", description = "Relara hat kein Fieber mehr, aber sie ist immer noch sehr schwach. Ich glaube nicht, dass sie wieder zu Kräften kommt, wenn wir einfach nur abwarten. Ich glaube, dazu bedarf es der Kraft eines Mondsteins.\n\nWir haben Mondsteine früher immer beim Fallenskysee im Südosten gesammelt... bis die Schattendickichtbäumlinge kamen.\n\nIhr Anführer, das Schattendickichtorakel, hat alle gefallenen Mondsteine eingesammelt und hortet sie. Jetzt müsst Ihr Euch einen Mondstein von dem Orakel holen.\n\nUnd dazu werdet Ihr ihn wohl erschlagen müssen, fürchte ich.", progress = "Wart Ihr schon beim Schattendickichtorakel, <Name>? Falls ja, dann gebt mir doch bitte den gefallenen Mondstein. Relaras Kraft reicht nur noch für ein paar Atemzüge!", completion = "Oh, &lt;Name&gt;, Ihr habt meine Tochter gerettet! Ich wusste, dass die Macht des Mondsteins meine Tochter wieder zu Kräften bringen könnte!\n\nKein Schatz der Erde würde ausreichen, um Euch für Eure Hilfe zu entlohnen, aber... bitte nehmt das. Außer Relara ist dies das Liebste, das ich habe.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWildbachrüstungBestienhandfesselnFlimmernde Amicia\n\nIhr bekommt außerdem:\n\n"},
[1036] = {title = "Hierher, Taugenichts", objective = "Sprecht mit Flottenmeister Firallon an Bord der CRIMSON VEIL vor der Küste des Schlingendorntals.", description = "<Name>... Ja, ich habe von Euch gehört. Ich habe gehört, dass Ihr kein Freund von Booty Bay seid - genau wie wir Blutsegelbukaniere. Flottenmeister Firallon sucht nach gesunden und tüchtigen <Männern/Frauen> wie Euch für eine spezielle Mission.\n\nWenn Ihr interessiert seid, begebt Euch zur CRIMSON VEIL und sprecht mit ihm unter Deck. Sie ankert vor der wilden Küste östlich von hier, bei der RIPTIDE und der DAMSEL'S LUCK.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[1037] = {title = "Velinde Starsong", objective = "Sprecht auf der Terrasse der Krieger in Darnassus mit Thyn'tel Bladeweaver.", description = "Velinde Starsong war hier in Ashenvale meine Vorgängerin. Zunächst schien es, als hätte sie die Lage im Teufelswald unter Kontrolle, aber nach und nach ließen ihre Bemühungen nach. Eines Tages verschwand sie einfach.\n\nMan schickte mich hierher, um ihre Arbeit fortzusetzen. Ich fürchte jedoch, dass ich nichts über die Priesterin weiß. Vielleicht weiß Thyn'tel Bladeweaver, eine der Kommandantinnen der Schildwache, mehr über ihr Verschwinden, das ich nicht miterlebt habe.\n\nSie wird sicherlich wissen, wie wichtig diese Informationen sind.", progress = nil, completion = "Velinde Starsong? Dass die Priesterin vor einiger Zeit verschwand, dürfte landläufig bekannt sein. Was weitere Details der Umstände ihres Verschwindens betrifft... Ihr müsstet mir schon einen guten Grund nennen, warum ich solche Informationen preisgeben sollte.", rewards = "Ihr bekommt:\n\n"},
[1038] = {title = "Velindes Besitztümer", objective = "Durchsucht Velindes Truhe nach ihrem Tagebuch und bringt es zusammen mit dem Schlüssel nach Darnassus zu Thyn'tel Bladeweaver.", description = "Der Foliant von Mel'Thandris hat Euch das gezeigt? Dann könnte es wohl nicht schaden, wenn ich Euch erlaubte, ihre Habseligkeiten durchzusehen. Mit diesem Schlüssel könnt Ihr die Truhe öffnen, in der wir ihre Sachen in der Schildwachenbaracke aufbewahren. Sie führte ein Tagebuch über ihre Pflichten und wenn es etwas zu erfahren gibt, dann daraus.\n\nIch sollte Euch noch sagen, dass die Schildwachen denken, dass sie Gründe für ihr Verschwinden hatte und damit rechnen, dass sie jederzeit wieder auftaucht. Die Priesterin hat in der Vergangenheit viel geleistet und unser Vertrauen verdient.", progress = "Was habt Ihr herausgefunden?", completion = "Velindes Verschwinden scheint doch seltsamer zu sein, als wir dachten. Ich kann immer noch nicht glauben, dass es mit ihr ein böses Ende genommen hat. Vielleicht wäre es nützlich für uns, Kontakt zu ihr aufzunehmen.\n\n&lt;Name&gt;, da Ihr ein berechtigtes Interesse an dieser Sache gezeigt habt, würde ich Euch gern mit einbeziehen.", rewards = "Ihr bekommt:\n\n"},
[1039] = {title = "Der Brachlandhafen", objective = "Sprecht in Ratchet mit Werftmeister Dizzywig.", description = "Ratchet ist der einzige Hafen des Brachlandes. Höchstwahrscheinlich hat Velinde in Ratchet ein Handelsschiff gefunden, das sie zur Schwarzmeerbucht in Azeroth brachte. Wir haben nur wenig mit den Goblins zu tun, die den Hafen leiten, aber der Dockmeister sollte über das Kommen und Gehen von Schiffspassagieren informiert sein.\n\nFolgt der Straße in südöstlicher Richtung durch Ashenvale, dann gelangt Ihr irgendwann ins Brachland. Seid auf der Hut, <Name>, Krieger der Horde streifen durch das Land. Im Hafen werdet Ihr jedoch sicher sein.", progress = nil, completion = "&lt;Volk&gt;, hä? Muss gestehen, solche wie Euch sieht man hier nicht oft. Sucht Ihr jemanden, hä? Einen Moment, das steht bestimmt in einer meiner Listen.\n\nHier zieht ein Haufen Volk durch, also gebt mir einen Moment Zeit.", rewards = "Ihr bekommt:\n\n"},
[1040] = {title = "Passage nach Booty Bay", objective = "Nehmt ein Schiff nach Booty Bay und sprecht dort mit dem Karawanenführer Ruzzgot.", description = "Ah ja, da steht's ja. Hättet mir sagen sollen, dass sie vor so langer Zeit hier durchgekommen ist. Mal sehen.\n\nVelinde. Hat eine Passage auf der BLACK OSPREY nach Booty Bay gebucht. Da hier nichts anderes steht, nehme ich an, dass sie den Hafen dort sicher erreicht hat.\n\nViel mehr Hilfe kann ich Euch nicht anbieten, aber sie hat mich nach einem Überlandtransport zur anderen Seite der Welt gefragt und ich habe ihr Ruzzgot vorgeschlagen, einen Karawanenführer aus Booty Bay. Kann sein, dass Velinde mit ihm gereist ist.\n\nUnd jetzt fort mit Euch. Ich hab zu tun.", progress = nil, completion = "Ja? Tja, Ihr seht mir nicht so aus, als hättet Ihr Waren zu befördern, also müsst Ihr wohl entweder auf der Suche nach einem Job in meiner Karawane sein - und ich habe momentan keine Jobs zu vergeben - oder Ihr sprecht mit dem falschen Goblin.\n\nAlso was liegt an?", rewards = "Ihr bekommt:\n\n"},
[1041] = {title = "Die Karawanenstraße", objective = "Sprecht in Dunkelhain mit Amtmann Daltry.", description = "Da hab ich mich wohl in Euch getäuscht und das passiert mir nicht alle Tage.\n\nZufällig erinnere ich mich an diese Velinde, nach der Ihr sucht. Kommt nicht jeden Tag vor, dass eine Nachtelfenpriesterin mit einer schmutzigen alten - aber alle Transportwünsche erfüllenden - Karawane wie der meinigen reisen will.\n\nAuf dem Weg nach Norden trennten wir uns, sie wollte weiter nach Dunkelhain. Der Amtmann dort macht alle möglichen Aufzeichnungen. Kann sein, dass er etwas Nützliches weiß.\n\nSeid im Dschungel vorsichtig, der ist selbst in günstigsten Zeiten tödlich.", progress = nil, completion = "Ich versuche, trotz all der seltsamen Ereignisse der letzten Jahre, so gut ich kann über alle Fremden Buch zu führen. Man weiß ja nie, wann man das mal brauchen könnte... nur ist es meistens wenig erfreulich, wenn es so ist. Nicht, dass ich damit irgendwas über diese Velinde sagen will, die Ihr sucht.", rewards = "Ihr bekommt:\n\n"},
[1042] = {title = "Die Familie Carevin", objective = "Sprecht mit Jonathan Carevin in Dunkelhain.", description = "Nein, ich habe keinen Eintrag über eine Velinde Starsong, die sich in Dunkelhain aufgehalten haben soll... Wenn Ihr erlaubt, ich kann mir auch nicht vorstellen, dass eine Nachtelfenpriesterin sich in einem Gasthaus einquartiert, wenn Ihr wisst, was ich meine.\n\nDiese Wolfmenschen, die Ihr erwähntet, von denen hab ich schon mal gehört. Erst kürzlich kam Calor mit einer ganzen Reihe Köpfe von denen in die Stadt zurück. Er arbeitet für die Familie Carevin. Sie jagen Dämonen, Untote und andere Monster. Sprecht mit Jonathan, er ist der Haushaltsvorstand.", progress = nil, completion = "Das sind wahrlich düstere Zeiten. Jeder Baum und Strauch flüstert schlimme Neuigkeiten und unter jedem Stein findet man etwas Böses.\n\nUnd in solchen Zeiten spaziert ein unbekannter Fremdling in mein Haus und fragt mich nach Worgs... Ich bitte nicht um Verzeihung für meinen Argwohn, sondern um Antworten.\n\nUnd Antworten werde ich bekommen.", rewards = "Ihr bekommt:\n\n"},
[1043] = {title = "Die Sense von Elune", objective = "Sucht nach Hinweisen auf die Sense von Elune und kehrt dann zu Jonathan Carevin in Dunkelhain zurück.", description = "Eure Geschichte klingt glaubhaft... Ich habe Eure Beweggründe zwar noch nicht ganz begriffen, aber wenn es zu Euren Angelegenheiten hier im Dämmerwald gehört, die Worgs im Wald auszurotten, dann können mir Eure Beweggründe auch herzlich egal sein, solange das Ergebnis stimmt.\n\nIm Süden gibt es eine Mine, die von Worgs überrannt wurde... Sie kamen aus dem Nichts, aber nach allem, was wir wissen, hat man sie dort zuerst gesehen.\n\nGeht Ihr nur Euren Angelegenheiten nach, aber ich möchte Euch bitten, dass Ihr mir Bescheid gebt, sobald Ihr etwas Wichtiges entdeckt. Wir sind für jede Hilfe gegen das Böse dankbar.", progress = nil, completion = "Ihr erzählt mir da eine interessante Geschichte, &lt;Name&gt;. Der Einfluss der Familie Carevin reicht zwar nicht so weit, dass wir die Wurzel aller Probleme finden und ein für alle Mal ausrotten könnten, aber wir tun was wir können, um die Zahl der Worgs im Dämmerwald in Grenzen zu halten.\n\nIch habe Calor bereits angewiesen, das zu seinem Hauptanliegen zu machen.", rewards = "Ihr bekommt:\n\n"},
[1044] = {title = "Beantwortete Fragen", objective = "Kehrt nach Darnassus zu Thyn'tel Bladeweaver zurück.", description = "Wir werden das Worgproblem in den Griff bekommen, keine Frage. Das Böse, das Eure Freundin in unseren Wald gebracht hat, wird eingedämmt werden und ich nehme ihr ihre Handlungen nicht übel. In letzter Zeit gehen seltsame Dinge vor sich, <Name>, und die Dunkelheit kennt keine Atempausen.\n\nIch will Euch nicht länger aufhalten. Mir scheint, dass auch andere erfahren sollten, was Ihr in den Minen des Dämmerwalds entdeckt habt.", progress = nil, completion = "Das ist also Velindes Schicksal, was? Die Hohepriesterin wird enttäuscht sein, wenn sie davon erfährt. Sie und Velinde waren vor deren Verschwinden gute Freundinnen. Unsere Göttin hat ihr die Sense von Elune bestimmt als eine Art Wohltat zukommen lassen, und ich bin erschüttert, dass sie nicht mehr in den Händen ihrer Dienerin ist.\n\nAber das ist eine Angelegenheit, um die man sich später kümmern muss. Ich schulde Euch Dank für das, was Ihr geleistet habt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLunaris-BogenMondstrahlzauberstab\n\nIhr bekommt außerdem:\n\n"},
[1045] = {title = "Raenes Säuberung", objective = "Tötet Ran Blutreißer sowie 4 Wachen von Blutreißer und kehrt dann zu Krolg in der Nähe des Mystralsees zurück.", description = "Die Nachtelfen sind so alt wie die Zeit, aber sie zerstören ihre eigene Welt durch ihre Arroganz. Und jetzt zerstören sie auch noch unser Leben. Doch das kann man nicht mehr verhindern...\n\nIch gebe den Elfen für viele Dinge die Schuld, aber wir sind immer noch für unsere Handlungen selbst verantwortlich. Wir sind sogar trotz der Verderbnis noch zu jeder Menge Bösem fähig.\n\nRan Blutreißer ist einer dieser Bösen. Machthungrig, gierig... die Verderbnis hat ihn nur noch stärker gemacht. Mein Hass auf die Elfen lodert, aber ich wünsche ihren Kindern nichts Schlimmes, wir müssen uns selbst im Zaum halten.", progress = nil, completion = "Das habt Ihr gut gemacht.\n\nDer Wald ist zwar immer noch besudelt, aber zumindest wissen wir jetzt, dass wir einen kleinen Beitrag dazu geleistet haben, ihm seine frühere Herrlichkeit zurückzugeben. Solltet Ihr mich wieder besuchen wollen, ich würde mich sehr über die Gesellschaft mit jemandem meiner Art freuen.\n\nGehabt Euch wohl. Vielleicht treffen sich unsere Stämme einst in weniger gewalttätigen Zeiten wieder.", rewards = "Ihr bekommt:\n\n"},
[1046] = {title = "Raenes Säuberung", objective = "Bringt Raene Wolfrunner in Astranaar Ran Blutreißers Schädel und Dartols Rute der Transformation.", description = "Kehrt zu Eurem eigenen Stamm zurück und lasst ihn von Eurem Sieg hier wissen.\n\nZeigt ihm Eure Trophäe und sonnt Euch in Eurem Ruhm...", progress = "Die Schildwachen hier in Ashenvale tun was sie können, aber solchen wie Euch, <Volk>, verdanken wir den Boden, den wir wieder zurückgewonnen haben.", completion = "Das ist also der Schädel des wildesten Furbolg von Ashenvale?\n\nIch bin von Euren Fähigkeiten mehr als angetan, &lt;Name&gt;. Die Schildwachen können Euch nicht genug danken. Ich hoffe, wir können uns auch in Zukunft darauf berufen, dass Ihr unserem Volk helft.\n\nDiesen Schädel und Dartols Rute werde ich an einem Ehrenplatz aufbewahren, damit jeder sie bewundern kann.\n\nTeronis wäre stolz. Nochmals danke.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGletschersteinKlinge des Ausweidens\n\nIhr bekommt außerdem:\n\nRing aus reinem Silber"},
[1047] = {title = "Die neue Grenze", objective = "Sprecht in der Enklave des Cenarius in Darnassus mit dem Erzdruiden Fandral Staghelm über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Sprecht in Darnassus mit dem Erzdruiden Fandral Staghelm, er hat weitere Informationen!", progress = nil, completion = "Was macht Euch glauben, dass ich mich von Euresgleichen belästigen lasse, &lt;Klasse&gt;? Wartet - lasst mich meine wichtigen Tagesgeschäfte unterbrechen, damit ich Euch helfen kann, irgendwo ein Dingelchen zu finden. Wahrhaftig, das Wohlergehen von Darnassus - ach was, von ganz Teldrassil ist nicht so wichtig wie die Beschaffung von Flitterzeug für Eure Sammlung.\n\nDiese Narren in Moonglade vergeuden meine Zeit mit ihrem Hilferuf, und jetzt muss ich mir das hier antun!", rewards = "Ihr bekommt:\n\n"},
[1048] = {title = "In das Scharlachrote Kloster", objective = "Tötet Hochinquisitor Whitemane, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Varimathras in Undercity.", description = "Während die dunkle Fürstin sich um die dringende Angelegenheit des Vormarsches des Lichkönigs im Norden kümmert, sorge ich dafür, dass Dinge, die uns unmittelbar betreffen, entsprechend geregelt werden.\n\nDie Menschenplage, die sich selbst Scharlachroter Kreuzzug nennt, hat sich als der schärfste Dorn in unserem Fleisch erwiesen. Tirisfal wimmelt förmlich von diesen kleinen roten Ameisen.\n\nBegebt Euch zum Kloster, <Klasse>, und vernichtet Hochinquisitor Whitemane und seine obersten Offiziere.", progress = nil, completion = "Ihr habt der dunklen Fürstin gut gedient, &lt;Klasse&gt;. Es war keine leichte Aufgabe, die ich Euch da abverlangt habe.\n\nEure Loyalität gegenüber den Verlassenen ist nicht unbemerkt geblieben. Und an Eure Beharrlichkeit im Kampf wird man sich immer erinnern.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchwert des OmensProphetenkrückstockDrachenblut-Halskette\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1049] = {title = "Kompendium der Gefallenen", objective = "Holt das 'Kompendium der Gefallenen' aus dem Kloster in Tirisfal und bringt es zu Sage Truthseeker in Thunder Bluff.", description = "Der irdene Ring hatte nur die besten Absichten, was unsere geplagten Brüder betraf. Aber wer weiß schon, welche Absichten jene verfolgen, die dem Ältestenrat Dinge einflüstern?\n\nDie Geschichte der Verlassenen, mit denen wir uns verbündet haben, ist von Lug und Trug durchzogen. Zu übereilt gingen wir unseren Pakt ein. Vielleicht hätte Cairne gut daran getan, die Warnungen aus Orgrimmar zu beherzigen.\n\nTief im Inneren des Scharlachroten Klosters liegt das 'Kompendium der Gefallenen' verborgen, das von irren menschlichen Zeloten bewacht wird. Ihr Tun ist von ihrem Wahnsinn geprägt, aber ihre Forschungen könnten nützlich für uns sein.", progress = "Cairne ist ein mutiger und edler Anführer, und ich würde ihm mein eigenes Leben anvertrauen. Es gibt jedoch andere, denen ich in diesem politischen Klima nicht trauen kann.\n\nSobald ich die Möglichkeit habe, alles Wissen zusammenzutragen, dessen ich habhaft werden kann, würde ich dem Häuptling ein solider Ratgeber sein.\n\nWäre es Euch vielleicht möglich, nach Tirisfal zu reisen? Zum Scharlachroten Kloster? Das 'Kompendium der Gefallenen' ist nur ein Teil dieses komplizierten Puzzles...", completion = "Das 'Kompendium der Gefallenen'! Ich begann mich schon zu fragen, ob das Buch überhaupt existiert!\n\nIhr habt den Tauren von Thunder Bluff sehr geholfen, &lt;Name&gt;. Euer Engagement soll belohnt werden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGrässlicher BeschützerZwingstein-RundschildOmegakugel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1050] = {title = "Mythologie der Titanen", objective = "Holt die 'Mythologie der Titanen' aus dem Kloster und bringt die der Bibliothekarin Mae Paledust in Ironforge.", description = "Die Zukunft ist unausweichlich! Wir stürzen ihr entgegen wie Regentropfen, die auf das große Meer prasseln.\n\nAber vielleicht erfahren wir, indem wir die Vergangenheit studieren, was uns erwartet, und könnten uns besser auf das Unbekannte vorbereiten.\n\nBevor Lordaeron von all diesen schrecklichen Dingen heimgesucht wurde, gab es eine Bastion des Wissens, die in Tirisfal versteckt lag. Gerüchten zufolge soll es in der Bibliothek des alten Klosters ein Buch mit dem Titel 'Mythologie der Titanen' gegeben haben.\n\nBringt es mir, dann können wir vielleicht gemeinsam die Geheimnisse der Vergangenheit entschlüsseln!", progress = "Das Kloster war einst ein Seminar für in Ausbildung befindliche Paladine. Die ehemalige Festung des Lichts fiel in die Hände der irren Zeloten des Scharlachroten Kreuzzuges.\n\nDer Kreuzzug hielt das Ziel, das sie verfolgten, für edel: das Land von der Untotenseuche zu läutern. Irrsinn jedoch verzerrte ihren Schwur und jetzt sind sie jedermanns Feind.\n\nBringt mir die 'Mythologie der Titanen', damit ich sie studieren und hier in Ironforge aufbewahren kann.\n\nDie verderbten Hallen des Klosters sind kein Ort für einen solchen historischen Schatz.", completion = "Ihr habt die heiligen Schriften gerettet!\n\nEure Reise war lang, und das Buch zu bekommen, war zweifelsohne keine leichte Aufgabe. Aber die Zwerge von Ironforge werden von Eurem Erfolg sehr profitieren.\n\nIch danke Euch im Namen der Forscherliga, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nForscherliga-Empfehlung"},
[1051] = {title = "Vorrels Rache", objective = "Bringt Monika Sengutz in Tarrens Mühle den Ehering von Vorrel Sengutz.", description = "Trotz meines freien Willens kann ich der dunklen Fürstin nicht mehr dienen. Ich fühle, dass meine Zeit in Azeroth zu Ende geht. Meine Lebenskraft ist zerschmettert.\n\nDas hat mir Befrager Vishas angetan! Wochenlang quälte er mich! Nahm mir meinen Ehering und gab ihn seiner Frau. Dieser Bastard!\n\nRache ... Ich will Rache!\n\nDer eingebildete Narr prahlte immer mit seiner ach so kostbaren Frau Nancy, die am Lordameresee lebte. Spürt diese Frau auf, erschlagt sie und bringt meiner Frau Monika in Tarrens Mühle meinen Ehering.\n\nDies ist mein letzter Wille ...", progress = "Was wollt Ihr, Fremdling?", completion = "Vorrel führte ja so ein bewegtes Leben. Was war er doch für ein guter Gefährte...\n\nVerdammt seien diese dreckigen Menschen!\n\nVorrel ist fort und wird sich nie wieder am untot sein erfreuen. Zumindest finde ich Trost in der Rache, die Ihr in seinem Namen geübt habt. Dafür danke ich Euch.\n\nUnd jetzt überlasst mich meiner Trauer...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMantel des JammersGrimmstahlcape\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\nVorrels Stiefel"},
[1052] = {title = "Auf dem Scharlachroten Pfad", objective = "Bringt Raleigh dem Andächtigen in Southshore Bruder Antons Empfehlungsschreiben.", description = "Wir vom Scharlachroten Kreuzzug erheben Anspruch auf die Festungen zwischen Hearthglen und Tirisfal. Wir sind recht stolz auf unsere Bastionen der Säuberung in ganz Lordaeron.\n\nIhr habt Euch gegen die Untoten in Desolace bewiesen. Doch die wahre Bedrohung durch die Seuche liegt in Lordaeron.\n\nBegebt Euch nach Southshore in den östlichen Königreichen. Sucht dort nach einem Kreuzzügler namens Raleigh der Andächtige. Gebt ihm dieses Empfehlungsschreiben, das mein Siegel trägt, dann wird er Euch zu einem ehrwürdigen Ort in unserem Scharlachroten Kloster führen.", progress = "Wer ist da? Was wollt Ihr von mir?", completion = "Bruder Anton verbreitet immer noch die Lehren des scharlachroten Kreuzzuges? So, so...", rewards = "Ihr bekommt:\n\n"},
[1053] = {title = "Im Namen des Lichts", objective = "Tötet Hochinquisitor Whitemane, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Raleigh dem Andächtigen in Southshore.", description = "Einst diente ich dem Scharlachroten Kreuzzug mit Ehre, Treue und Stolz. Ich hielt das Ziel, das sie verfolgten, für edel: Azeroth von den Untoten befreien.\n\nAls ich jedoch im Kloster in Tirisfal weilte, erkannte ich, dass sie langsam den Bezug zur Wirklichkeit verloren. Jetzt halten sie jeden für verseucht, der nicht das Wams des Kreuzzuges trägt. Unschuldige Männer und Frauen wurden gefoltert, weil sie angeblich verseucht waren. \n\nDer Scharlachrote Kreuzzug muss im Namen des Lichts zerschlagen werden. Ihr, <Name>, müsst ihr wahnwitziges Regime beenden.", progress = nil, completion = "Die Jünger des Lichts sind nicht erpicht darauf, ihr Leben zu lassen, doch müssen wir akzeptieren, dass manche Umstände es erforderlich machen, solche Opfer für das Wohl des Königreiches und des gesamten Planeten zu bringen.\n\nDurch Eure Taten im Kloster habt Ihr vielen Unschuldigen das Leben gerettet, &lt;Name&gt;. Ich verbeuge mich vor Eurer Beharrlichkeit.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchwert der BeschaulichkeitKnochenbeißerSchwarze BedrohungKugel von Lorica\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1054] = {title = "Die Auswahl der Bedrohung", objective = "Bringt Raene Wolfrunner in Astranaar Dal Blutklaues Schädel.", description = "Direkt im Norden Astranaars leben die Furbolgs vom Distelfellstamm. Meine Späher berichten, dass ihre Zahl sich in den letzten Monaten erhöht hat. Sollten es zu viele werden, könnten sie den Mut finden, Astranaar direkt anzugreifen.\n\nTötet so viele von ihnen, wie Ihr könnt, aber bringt mir den Schädel ihres Häuptlings zum Beweis dafür, dass ihr Bemühen im Keim erstickt wurde ... vorläufig.\n\nIch bleibe hier in Astranaar und warte auf Kunde von Euch. Elune sei mit Euch.", progress = "Die Verderbnis der Furbolgs hat aus Ashenvale ein Zerrbild seines einstigen Glanzes gemacht.", completion = "Gut gemacht, &lt;Name&gt;.\n\nDie Furbolgs sind eine ständige Bedrohung. Hoffentlich wird sie das noch eine Weile in Schach halten.", rewards = "Ihr bekommt:\n\nWiederherstellender Balsam"},
[1055] = {title = "Raenes Säuberung", objective = "Kehrt zu Shael'dryn beim Mondbrunnen zurück.", description = "Die Rute, jetzt wieder heil, liegt in Euren Händen. Shael'dryn wird von Eurem Erfolg hören wollen.", progress = nil, completion = "Ihr habt es geschafft, &lt;Name&gt;! Gut gemacht!", rewards = "Ihr bekommt:\n\n"},
[1056] = {title = "Reise zum Steinkrallengipfel", objective = "Reist zu Bewahrer Albagorm auf dem Steinkrallengipfel.", description = "Die Waldgeister sagten mir, dass Ihr mutig und zu reisen gewillt seid.\n\nIm Süden, nicht weit vom Mystralsee entfernt, liegt ein Tunnel namens Steinkrallenpfad. Durch diesen Tunnel gelangt Ihr in ein Gebiet, das im Steinkrallengebirge als Scherwindklippe bekannt ist. Dort angelangt reist südwestlich weiter, am Felskesselsee vorbei und dann nach Norden, den steilen Abhang hinauf, bis Ihr den Steinkrallengipfel erreicht.\n\nDort werdet Ihr von Hüter Albagorm erwartet. Tut, was er sagt, <Volk>.\n\nDie Reise wird gefährlich.", progress = nil, completion = "Endlich seid Ihr da. Ich sehe, Faldreas hat auf die Waldgeister gehört...", rewards = "Ihr bekommt:\n\n"},
[1057] = {title = "Die Rückeroberung des verbrannten Tals", objective = "Bewahrer Albagorm auf dem Steinkrallengipfel möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt.", description = "Als Beschützer der Waldgeister könnt Ihr sicher unschwer erraten, warum ich beunruhigt bin.\n\nIhr seid durch diese Berge gereist, um diesen Gipfel zu erreichen. Sicherlich habt Ihr das Zerrbild gesehen, zu dem das Land geworden ist. Gier hat zur Zerstörung dieser heiligen Hügel geführt.\n\nDie gierige motorisierte Armee der Industrialisten hat das verbrannte Tal im Süden in Brand gesteckt. Was noch schlimmer ist, die Blutfurien, die in unser Land eingedrungen sind, lassen uns nicht dorthin, um mit der Neuanpflanzung zu beginnen.\n\nVertreibt diese elenden Harpyien, <Name>!", progress = nil, completion = "Jetzt, da die Blutfurien einen solch großen Verlust erlitten haben, können wir vielleicht endlich ernsthaft an den Wiederaufbau des Landes gehen...", rewards = "Ihr bekommt:\n\n"},
[1058] = {title = "Jin'Zils Waldmagie", objective = "Hexendoktor Jin'Zil in Malaka'jin möchte 5 Portionen Steinkrallensaft, 5 Schnurrhaare eines Mondlichtläufers, 30 Renner-Augen und die Schuppe eines Siechdrachen.", description = "Ich bin ja so aufgeregt!\n\nDrei kleine Käfige mit drei kleinen Elfen! Aber was tun wir nur mit unseren süßen Baumschützer-Freunden? Na, lassen wir sie doch... wie nennen sie das doch gleich... Waldmagie schmecken!\n\nIch brauche einen ordentlichen Schuss Steinkrallensaft. Dann brauche ich ein paar Mondlichtläuferschnurrhaare von diesen schrecklichen Katzen. Das schreit nach einer Menge Renneraugen - man kann nie genug Augen haben. Oh, und bevor wir es vergessen, die wertvolle Schuppe eines Siechdrachen.\n\nSchnell zum Steinkrallengipfel, <Name>, damit ich etwas Waldmagie zusammenbrauen kann!", progress = "Seht Euch nur unsere armen kleinen Elfenfreunde an. Eingesperrt in einen Käfig und weit und breit kein Wald, in dem sie herumtollen können!\n\nNun, habt Ihr etwas Saft für mich gefunden? Was ist mit den Schnurrhaaren der Mondlichtläufer? Ihr habt nicht zufällig diese Siechdrachen-Schuppe dabei?\n\nUnd die Augen! Ich brauche jede Menge Augen! Ohne eine ordentliche Portion Augen kann man einfach keine starke Waldmagie zusammenbrauen!", completion = "Oh, wie glücklich werden diese kleinen Waldnymphen sein! Mit diesem Spezialgebräu werden sie sich ganz wie zu Hause fühlen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVoodoomantelVerhexte Armschienen\n\nIhr bekommt außerdem:\n\n"},
[1059] = {title = "Die Rückeroberung des verbrannten Tals", objective = "Reist zu Falfindel Waywarder an der Grenze zwischen Tausend Nadeln und Feralas.", description = "Die Blutfurien wurden besiegt. Sie werden sich jedoch schon bald wieder neu gruppieren, wenn wir nichts unternehmen.\n\nGanz weit im Süden des Brachlandes liegt ein Land, das als Tausend Nadeln bekannt ist. Wenn Ihr in Tausend Nadeln nach Westen reist bis zum üppigen Waldrand von Feralas, stoßt Ihr auf einen Druiden namens Falfindel Waywarder.\n\nDieser große und weise Druide kann große Waldgeister herbeirufen, die bei der Rekultivierung des verbrannten Tals helfen können.\n\nErzählt ihm von unserer Notlage! Sucht ihn sofort auf!", progress = nil, completion = "Es war sehr klug von Bewahrer Albagorm, Euch so schnell zu entsenden.\n\nLasst uns sehen, ob wir nicht Hilfe aus dem großen Wald herbeirufen könnten, damit wir zum verbrannten Tal reisen können, bevor es zu spät ist.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAusgehärtete ArmschienenKonstabler-Rundschild\n\nIhr bekommt außerdem:\n\n"},
[1060] = {title = "Brief an Jin'Zil", objective = "Überbringt Jin'Zil in seiner Höhle im Steinkrallengebirge Darsoks Brief.", description = "Ihr habt mir sehr geholfen, <Name>. Ihr seid ein echter Glücksbringer, wie eine Hasenpfote, und ich möchte, dass Ihr Euch das hier einmal anseht.\n\nDie Harpyien stammen nicht aus dem Brachland. Sie kommen aus einem Ort namens Steinkrallengebirge, ganz weit nordwestlich von hier. Dort könnte es möglicherweise gefährlich für Euch sein, aber dieser Brief muss an einen alten Freund von mir überbracht werden, der dort lebt, ein Hexendoktor mit dem Namen Jin'Zil.\n\nEr wird sich freuen zu hören, dass Serena Blutfeder tot ist, und ich glaube, Ihr werdet das Steinkrallengebirge sehr interessant finden.", progress = "Ihr scheint mir ein fragwürdiger Charakter zu sein. Wollt Ihr mir etwas zeigen?", completion = "Ah, ein Brief von Darsok. Ich habe seit Jahren nichts mehr von ihm gehört.\n\nDie letzte Blutfeder ist also tot, was? Das sind gute Neuigkeiten. Ich kann mich noch daran erinnern, als mein Freund Rokhan mit diesem verrückten Mok'Nathal auszog, um ihre ältere Schwester zu töten. Ah, könnte man doch noch mal jung sein.", rewards = "Ihr bekommt:\n\n"},
[1061] = {title = "Die Geister des Steinkrallengebirges", objective = "Sprecht im Steinkrallengebirge mit Seereth Stonebreak.", description = "Die Geister des Steinkrallengebirges sind verärgert, weil Goblins und ihre Gefolgsleute das Land ausplündern und brandschatzen. Das Land rief um Hilfe, und jene, die auf so etwas achten... haben es gehört.\n\nSeereth Stonebreak, eine aufstrebende Schamanin der Horde, wurde in das Steinkrallengebirge geschickt. Sie berichtet von umfangreichen Rodungen durch die Goblins und bittet um Hilfe.\n\nTrefft Euch im Steinkrallengebirge mit Seereth. Um zu ihr zu gelangen, folgt der Straße westlich aus Crossroads im Brachland. Sie hat in der Nähe des Hochwipfeltals ein Lager aufgeschlagen.", progress = nil, completion = "Ah, &lt;Klasse&gt;. Sehr gut. Wir werden Eure Fähigkeiten brauchen, um diese Brandschatzer zu bekämpfen!", rewards = "Ihr bekommt:\n\n"},
[1062] = {title = "Goblin-Eindringlinge", objective = "Tötet 15 Holzfäller der Venture Co. und kehrt dann zu Seereth Stonebreak an der Grenze des Steinkrallengebirges und dem Brachland zurück.", description = "Die von Goblins geleitete Venture Company ist in das Steinkrallengebirge umgezogen, um dort Bäume zu fällen und ganze Waldflächen zu brandroden. Die Geister dort sind außer sich vor Schmerz und Wut. Wir müssen der Venture Company Einhalt gebieten!\n\nBegebt Euch nach Nordwesten, jenseits des Hochwipfeltals, und zur Scherwindklippe. Ihr werdet dort die Goblins und ihre Gefolgsleute bei der Arbeit vorfinden - zeigt ihnen, dass die Horde eine Ausbeutung des Steinkrallengebirges nicht billigt. Zeigt es ihnen in der Sprache, die sie am besten verstehen...\n\nGewalt.", progress = nil, completion = "Tapfer, tapfer, &lt;Name&gt;.\n\nWir werden letztendlich die Weisheit der Taurenältesten benötigen, um die Geister des Steinkrallengebirges zu beschwichtigen, aber...\n\nDer \"Personalabbau\" bei der Venture Company ist schon ein guter Anfang.", rewards = "Ihr bekommt:\n\n"},
[1063] = {title = "Die Ältestengreisin", objective = "Sprecht in Thunder Bluff mit Magatha.", description = "Um die Geister des Steinkrallengebirges wirklich zu beschwichtigen, müssen wir uns an die Taurenältesten wenden.\n\nIch kenne nicht viele ihrer Anführer, aber einen Namen kenne ich: Magatha. Ich habe gehört, dass sie sehr alt sein soll und sehr viel weiß. Wenn jemand die Tauren um geistige Hilfe bitten kann, dann sie.\n\nMagatha lebt in der Tauren-Hauptstadt Thunder Bluff auf der Anhöhe der Ältesten - dem Steilhang im Nordosten der Stadt. Sprecht mit Magatha und berichtet ihr von der Not im Steinkrallengebirge.", progress = nil, completion = "Ich entbiete Euch meinen Gruß. Seid Ihr wegen eines Rates gekommen?", rewards = "Ihr bekommt:\n\n"},
[1064] = {title = "Die Hilfe der Verlassenen", objective = "Sprecht bei den Teichen der Visionen mit der Apothekerin Zamah.", description = "Die Tauren sind mit dem Land verbunden, und es schmerzt mich, von der Not im Steinkrallengebirge zu hören. Ich fürchte jedoch, dass wir zunächst die Krankheit ausmerzen müssen, bevor wir das Land heilen können.\n\nIst es nicht eine glückliche Fügung, dass wir mit den Verlassenen verbündet sind? Sie wissen viel über Krankheiten. Ich glaube, sie werden uns helfen können, was das gegenseitige Vertrauen zwischen unseren Völkern stärken wird.\n\nSprecht mit Apothekerin Zamah. Sie ist eine Gelehrte und Botschafterin der Verlassenen. Ihr findet sie bei den Teichen der Visionen unterhalb der Anhöhe der Geister.", progress = nil, completion = "Magatha hat mir Euer Kommen angekündigt, &lt;Name&gt;. Obwohl mein Herz nicht mehr schlägt, sorge ich mich doch um die Geister des Steinkrallengebirges.\n\nDie Verlassenen brennen darauf, auf jede erdenkliche Weise zu helfen.", rewards = "Ihr bekommt:\n\n"},
[1065] = {title = "Reise nach Tarrens Mühle", objective = "Bringt Apotheker Lydon in Tarrens Mühle Zamahs Notiz.", description = "Um die Venture Company aus dem Steinkrallengebirge zu vertreiben, müssen wir extreme Maßnahmen ergreifen. Extrem, aber ohne Blutvergießen.\n\nEiner meiner Kollegen hat vielleicht genau das Werkzeug, das wir benötigen. Er heißt Lydon und wohnt in Tarrens Mühle im Vorgebirge von Hillsbrad, das im weit entfernten Lordaeron liegt.\n\nUm nach Hillsbrad zu gelangen, reist mit dem Zeppelin in unsere Hauptstadt, nach Undercity. Geht von dort aus nach Norden nach Tirisfal, dann südwestlich nach Silberwald und südlich nach Hillsbrad.\n\nSucht Lydon auf und gebt ihm diese Notiz. Sie wird ihm alles erklären.", progress = "Ah, bringt Ihr mir meine neuesten Versuchskaninchen?", completion = "Eine Notiz von Zamah? Es muss dringend sein, wenn sie mir von so weit her eine Nachricht zukommen lässt. Mal sehen, was sie schreibt...\n\nAh, großartig! Ich weiß genau, was zu tun ist!", rewards = "Ihr bekommt:\n\n"},
[1066] = {title = "Das Blut Unschuldiger", objective = "Bringt Apotheker Lydon in Tarrens Mühle 5 Phiolen mit dem Blut Unschuldiger.", description = "Ich werde ein Toxin herstellen, mit dem wir der Venture Company die Gewalt entziehen und sie schwach und sanftmütig werden lassen. Das sollte das Problem der Horde im Steinkrallengebirge lösen, meint Ihr nicht?\n\nUm das Toxin herzustellen, benötige ich jedoch das Blut Unschuldiger, eine Zutat, an die man nur schwer herankommt.\n\nGlücklicherweise beschäftigt das Syndikat, das ist eine Gruppe menschlicher Briganten in dieser Region, Schattenmagier ... und diese Magier beschaffen sich das Blut Unschuldiger für ihre eigenen unappetitlichen Machenschaften.\n\nIhr finded die Schattenmagier des Syndikats in der Burg Durnholde im Südosten.", progress = "Habt Ihr die Schattenmagier des Syndikats gefunden und von ihnen Blut bekommen?", completion = "Sehr gut! Das Syndikat hat Euch doch hoffentlich nicht allzu viele Schwierigkeiten gemacht?\n\nWie ich erwähnte, kommt man nicht leicht an das Blut Unschuldiger heran. Wir haben Glück, dass die Schattenmagier des Syndikats uns diese schwierige Arbeit abgenommen haben.\n\nWartet bitte einen Moment, während ich mein Gebräu herstelle ...", rewards = "Ihr bekommt:\n\n"},
[1067] = {title = "Rückkehr nach Thunder Bluff", objective = "Bringt Apothekerin Zamah in Thunder BluffLydons Toxin.", description = "Hier habt Ihr das Toxin. Wenn Ihr es gegen die Venture Company einsetzt, sollte es positive, vielleicht sogar ansteckende Ergebnisse erzielen. Ich muss sagen, es ist ziemlich aufregend zu sehen, dass mein Werk tatsächlich eingesetzt wird!\n\nBringt es aber erst der Apothekerin Zamah, bevor Ihr es einsetzt. Sie muss eine Anwendungsmethode für das Toxin entwickeln, um einen größtmöglichen Effekt zu erzielen.", progress = "Ihr seid zurück, <Name>. Bringt Ihr Hilfe von Apotheker Lydon?", completion = "Ein Toxin von Apotheker Lydon? Sehr gut. Wie ich Lydon kenne, wird dieses Toxin äußerst wirkungsvoll gegen die Venture Company sein...", rewards = "Ihr bekommt:\n\n"},
[1068] = {title = "Schreddermaschinen", objective = "Vernichtet die Schredder XT:4 und XT:9 und kehrt dann zu Seereth Stonebreak an der Grenze zwischen dem Steinkrallengebirge und dem Brachland zurück.", description = "Es gibt eine Verbindung zwischen der spirituellen Magie der Schamanen und der natürlichen Magie der Druiden. Deshalb können die Schamanen auch das Flehen der Geister des Steinkrallengebirges hören. Vieles, das sie flüstern, verstehe ich nicht, aber eine Nachricht, eine Vision, ist eindeutig ...\n\nIch hatte die Vision zweier menschenähnlicher Maschinen, die auf der Scherwindklippe nordwestlich des Hochwipfeltals mit ungeheuerlicher Geschwindigkeit Bäume fällten. Diese Metallbestien müssen aufgehalten werden!\n\nIn meiner Vision trugen diese Maschinen seltsame Symbole:\n\nXT:4 und XT:9.", progress = nil, completion = "Die Zerstörung der Maschinen XT:4 und XT:9 hat viele der Geister des Steinkrallengebirges besänftigt, &lt;Name&gt;. Hoffen wir, dass sich die Venture Company aufgrund dieses Verlustes aus diesen Bergen zurückziehen wird.\n\nGeschieht dies nicht, fürchte ich, dass die Gräueltaten, die dieser Ort bereits erleiden musste, nur ein fahler Vorgeschmack auf das sind, was ihm noch bevorsteht.", rewards = "Ihr bekommt:\n\n"},
[1069] = {title = "Eier der Kluftmoosspinnen", objective = "Bringt Mebok Mizzyrix in Ratchet 15 Kluftmooseier.", description = "Omeletts aus Spinneneiern sind der letzte Schrei in Booty Bay! Das Problem ist nur... dass es in Booty Bay keine Eier gibt.\n\nDas riecht nach einer Geschäftsidee!\n\nAn der Scherwindklippe und im Sishircanyon nordwestlich im Steinkrallengebirge, lebt die Kluftmoosspinne. Bringt mir ihre Eier, dann werde ich Euch reichlich entlohnen!\n\nAn der Scherwindklippe sind die Eihaufen unter den noch verbliebenen Bäumen zu finden.\n\nIm Sishircanyon... tja, wenn Ihr einen schwachen Magen habt, solltet Ihr vielleicht nur die Eier an der Scherwindklippe sammeln...", progress = "Habt Ihr die Eier, <Name>? Ich habe mit Werftmeister Dizzywig bereits eine Transportvereinbarung getroffen!", completion = "Ihr habt sie! Danke!\n\nIch werde sie Dizzywig schicken, der sie dann nach Booty Bay verschifft. Ich kann den Profit schon fast schmecken!\n\nHier ist Euer Anteil, &lt;Name&gt;. Ohne Euch hätte ich dieses Geschäft nicht machen können.", rewards = "Ihr bekommt:\n\n"},
[1070] = {title = "Wache halten im Steinkrallengebirge", objective = "Sucht Kaela Shadowspear, die auf der Scherwindklippe im Steinkrallengebirge den Taleingang beobachtet.", description = "Hallo, <Name>.\n\nSo wie Ihr ausseht, scheint Ihr voller Reiselust zu sein. Wart Ihr schon mal im Steinkrallengebirge? Es ist ein Land, das von der Venture Company und anderen Feinden der Nachtelfen heimgesucht wird.\n\nErst neulich schickte Schildwache Wolfrunner meine Freundin Kaela Shadowspear dorthin, um zu untersuchen, was mit dem Land geschehen ist, aber ich habe seitdem nichts mehr von ihr gehört. Was mir noch mehr Sorgen macht ist, dass die Allianz sie zusammen mit einem Gnomen-Magier losgeschickt hat ... das deutet definitiv auf Probleme hin.\n\nWürdet Ihr sie suchen und mir dann Bericht erstatten?", progress = nil, completion = "Ah, Ihr seid auf Taras Geheiß aus Ashenvale gekommen - wie sehr ich sie vermisse, mein Heimatland und meine Freunde. Sie muss mit ihren Schildwachen sehr beschäftigt sein, wenn sie Abenteurer für andere Aufgaben rekrutieren muss. Ich bin sehr stolz auf sie.\n\nEs ist mir eine Freude, Eure Bekanntschaft zu machen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[1071] = {title = "Der Aufschub des Gnoms", objective = "Tötet 10 Holzfäller der Venture Co. und 10 Roder der der Venture Co. und kehrt dann zu Gaxim Rustfizzle im Steinkrallengebirge zurück.", description = "Wisst Ihr, <Name>, ich bin Mitglied der Erleuchteten Vereinigung der Arkanologie, Alchimie und Ingenieurwissenschaften, und es ist mein Ziel... nein, meine PFLICHT!, den Nachtelfen zu zeigen, dass eine Mischung aus Magie, Mixturen und Mechanismen dazu beitragen kann, ihren Wald zu retten.\n\nEs ist jedoch ein Kampf gegen Windmühlen, und die Goblins vermehren sich wie die Kaninchen, wie es scheint. Ich hatte sogar nicht mal Zeit, um meine neuesten Erfindungen zu bauen!\n\nIch brauche etwas Zeit, um zu planen und zu organisieren. Dazu brauche ich jedoch Eure Hilfe bei der Eindämmung der Goblins auf der Scherwindklippe im Osten...", progress = "Wie läuft die Schlacht bei Euch, <Name>?", completion = "Vielen Dank für Eure Hilfe, &lt;Name&gt;. Ihr kommt gerade rechtzeitig zurück.\n\nIch glaube, ich habe den perfekten Plan... Sprengstoff. Nein, das ist noch nicht der Plan, aber ein Teil des Plans.\n\nSeht Ihr, ich habe hochexplosiven Sprengstoff benutzt - keine Sorge, der ist gar nicht so gefährlich, wie alle meinen -, um den Goblins ein bisschen Angst einzujagen. Ich kann sie mit ein paar gezielt platzierten Sprengungen entlang des Gebirgsrandes ziemlich gut zusammentreiben, aber mir gehen langsam die Vorräte aus...", rewards = "Ihr bekommt:\n\n"},
[1072] = {title = "Ein alter Kollege", objective = "Sprecht mit Lomac Gearstrip in Ironforge.", description = "Das Gerät, das mir vorschwebt, wird meine am weitesten entwickelte Erfindung sein. Aber wir brauchen einen speziellen Trank, wenn es funktionieren soll. Ich glaube, wir sollten uns gleich an das gute Zeug halten, immerhin könnte das unsere letzte Mission sein.\n\nUnd deshalb brauchen wir einen hochwirksamen Sprengstoff: Nitromirglyceronium.\n\nDie einzige Person, die NG-5 herstellen kann, ist ein alter Freund von mir: Lomac Gearstrip. Sucht in Tüftlerstadt nach ihm.\n\nWenn Ihr ihn überreden könnt, uns etwas NG-5 herzustellen, kann ich mich an die Platzierung meiner Geräte machen.", progress = nil, completion = "Ahhh... Gaxim hat Euch geschickt? Woher weiß ich, dass Ihr mich nicht belügt? Hmm? Hmm...?", rewards = "Ihr bekommt:\n\n"},
[1073] = {title = "Stümperhaftigkeit + Chemikalien = Riesenspaß!", objective = "Bringt Lomac Ritzeldreh in Eisenschmiede 4 schwache Manatränke und 2 Elixiere der schwachen Seelenstärke.", description = "Hahaha... Ihr braucht Nitromirglyceronium, um Goblins daran zu hindern, einen Wald zu zerstören?!\n\nEs ist mir egal, ob Ihr Gaxim kennt oder nicht... Ich würde Euch das Zeug allein schon deshalb geben, weil ich sehen will, wie Ihr oder sie in klitzekleine Fetzen explodieren.\n\nEs gibt allerdings ein Problem: Ich hab nichts mehr.\n\nAber ich sag Euch was: Bringt mir die richtigen Tränke, dann stelle ich sofort etwas für Euch her.\n\nDas Mindeste, was Ihr tun könnt, ist, mir ein paar Eurer Alchimisten-Fertigkeiten vorzuführen, bevor ich Euch eine Kostprobe meiner größten Erfindung gebe.", progress = "Ohne die Tränke kann ich kein Nitromirglyceronium herstellen... sie sind für die Herstellung unbedingt erforderlich.", completion = "Das sollte klappen.\n\nWenn ich es nicht besser wüsste, Fremdling, würde ich sagen, Ihr kennt Euch ein bisschen mit Alchimie aus. Gut, gut... in der Welt dreht sich nicht alles immer nur um Schwerter oder Zauberei, wisst Ihr?", rewards = "Ihr bekommt:\n\n"},
[1074] = {title = "Stümperhaftigkeit + Chemikalien = Riesenspaß!", objective = "Bringt Gaxim Rustfizzle im Steinkrallengebirge das Nitromirglyceronium.", description = "Bitte sehr, Fremdling. Seid jedoch vorsichtig damit... das Zeug ist hochexplosiv.\n\nFalls Ihr wirklich ein Freund von Gaxim seid, grüßt ihn von mir. Falls nicht, dann viel Spaß beim Selbst-in-die-Luft-jagen.", progress = "Ah, prima, prima, Ihr seid zurück.", completion = "Ihr habt Eure Aufgabe fehlerfrei erledigt, &lt;Name&gt;.\n\nNG-5 ist die wichtigste Komponente in diesem Rezept zur Zündung der Wagen mit Dynamit.\n\nWas? Ja, Dynamit... ganze Wagenladungen. Das ist das perfekte Ablenkungsmanöver... Ihr werdet es schon sehen.", rewards = "Ihr bekommt:\n\n"},
[1075] = {title = "Eine Rolle von Mauren", objective = "Sucht Collin Mauren in Stormwind auf.", description = "Gut, wenden wir uns jetzt dem Teil meines Planes mit der Fernzündung zu... oh, das hab ich ja noch gar nicht erklärt, stimmt's?\n\nAlso dann mal die Kurzversion: Mit etwas Magie kann ich dafür sorgen, dass der Sprengstoff hochgeht, ohne dass Ihr dabei sein müsst. Ich bastele ein Gerät zusammen, bei dem Ihr nur einen Knopf drücken müsst, damit das NG-5 explodiert, wenn Ihr bereit seid.\n\nIch brauche jedoch einen Zauber von einem Freund in Stormwind - er heißt Collin Mauren. Ihr findet ihn im dortigen Magierviertel. Er ist ein Mensch, daher solltet Ihr ihn kaum verfehlen können.", progress = nil, completion = "Tja, dieser Zauber, den Ihr benötigt... einen, mit dem man Sprengstoff aus der Entfernung zünden kann... hmmm.", rewards = "Ihr bekommt:\n\n"},
[1076] = {title = "Teufel in Westfall", objective = "Bringt Collin Mauren in Stormwind die Überreste eines Staubteufels.", description = "Ah, ich glaube, ich hab's. Ein Nachrichtenzauber... Er dürfte den Effekt haben, nachdem er sucht.\n\nIch muss eine Rolle herstellen, auf die der Zauber geprägt ist. Dazu benötige ich die Überreste eines Staubteufels.\n\nWarum geht Ihr nicht nach Westfall und sucht eine dieser elenden Kreaturen, während ich den Rest der Komponenten sammle? Sie sind gefährlich, aber ich bin mir sicher, dass Ihr schon damit klarkommt, zumal Ihr sogar gewillt seid, an einem von Gaxims Experimenten teilzunehmen.\n\nIch werde hier sein, wenn Ihr zurückkommt.", progress = "Hallo, <Name>. Habt Ihr die Komponente gefunden, die ich benötige?", completion = "Einen kleinen Moment noch, dann habe ich die Rolle für Euch fertig.", rewards = "Ihr bekommt:\n\n"},
[1077] = {title = "Speziallieferung für Gaxim", objective = "Bringt Gaxim Rustfizzle im Steinkrallengebirge die Rolle der Nachrichtenübermittlung.", description = "Bitte sehr, <Name>. Das sollte funktionieren.\n\nBitte grüßt Gaxim von mir, wenn Ihr ihn das nächste Mal seht. Ich freue mich schon so darauf, von diesem Abenteuer zu hören, wenn Ihr es überstanden habt.\n\nLebt wohl.", progress = "Haha! Ihr seid zurück! Habt Ihr ihn? Habt Ihr den Zauber?", completion = "Das ist perfekt, &lt;Name&gt;. Gut gemacht.\n\nDieser Zauber in Verbindung mit dem NG-5 ergibt einen perfekten Sprengstoff mit Fernzündung.\n\nWir werden eine perfekte Ablenkung für Euch schaffen, damit Ihr hineinschleichen und alle Briefe und Ingenieurspläne der Venture Company stehlen könnt.\n\nDas wird ihre Rodungsaktionen behindern.", rewards = "Ihr bekommt:\n\n"},
[1078] = {title = "Suche für Mauren", objective = "Bringt Collin Mauren in Stormwind 8 kristallisierte Schuppen.", description = "Immer wieder fragen mich Reisende über das Steinkrallengebirge aus. Scheint ein beliebter Ort unter Abenteurern zu sein; spielt keine Rolle, ob man Flügeldrachen oder Elementare sucht, oder ob man Geschäfte mit der Venture Company machen will.\n\nIm verbrannten Tal tief im Steinkrallengebirge gab es mal eine Basiliskenart, deren Schuppen, wenn man sie zu Staub zermahlte, ein wunderbares Reagenz für einige der Zauber ergab, die ich ersonnen habe.\n\nWenn diese Basilisken noch leben, hätte ich liebend gern ein paar ihrer Schuppen.\n\nLasst Euch Zeit, ich hab keine Eile, aber ich kann Euch gut bezahlen.", progress = "Hallo, <Name>.\n\nSeid Ihr mit den Schuppen schon wieder aus dem Tal im Steinkrallengebirge zurück?", completion = "Das ist perfekt, &lt;Name&gt;. Vielen, vielen Dank.\n\nVielleicht kann ich Euch eines Tages einmal so helfen, wie Ihr mir geholfen habt.", rewards = "Ihr bekommt:\n\nZauberstab des Zauberkundigen"},
[1079] = {title = "Geheimoperation Alpha", objective = "Holt die Ingenieurspläne der Venture Company aus dem Sägewerk auf der Scherwindklippe.", description = "Das ist es, <Name>. Seht genau hin. Die Geräte sind fertig und einsatzbereit.\n\nNehmt diese Blätter - sie erklären mehr über die Zünder und den Sprengstoff und wo Ihr ihn platzieren solltet.\n\nDenkt daran, der Erfolg Eurer Mission hängt nicht davon ab, wie viel Schaden Ihr anrichtet. Der Erfolg von Plan Alpha hängt davon ab, dass Ihr die Ingenieurspläne der Venture Company aus dem Sägewerk südlich des Felskesselsees holt.", progress = "Habt Ihr die Pläne, <Name>?", completion = "Einfach erstaunlich! Das versetzt der Venture Company einen Riesenschlag.\n\nJetzt können wir Schwächen an ihren Maschinen aufdecken und ihre Entwürfe für unsere eigenen Kreationen ausnutzen. Das ist heute wahrlich ein Freudentag.", rewards = "Ihr bekommt:\n\n"},
[1080] = {title = "Geheimoperation Beta", objective = "Holt die Dokumente der Venture Company aus der Scherwindmine am Ostende der Scherwindklippe.", description = "Plan Beta funktioniert genau wie Plan Alpha, <Name>.\n\nWir stiften Verwirrung und stehlen dann ihre wertvollen Dokumente.\n\nWir müssen unbedingt diese Dokumente haben... vergesst das nicht.\n\nDie Blätter, die Ihr bereits habt, zeigen Euch, wo Ihr den Sprengstoff platzieren müsst. Kommt mir nur heil und mit diesen Dokumenten zurück...", progress = "Wie ist es gelaufen, <Name>?", completion = "Unglaublich, &lt;Name&gt;! Kaela und die Schildwachen werden überglücklich sein. Mit Euren Fertigkeiten und meinen Erfindungen sind wir unschlagbar.", rewards = "Ihr bekommt:\n\n"},
[1081] = {title = "Tyrandes Empfang", objective = "Sucht Tyrande Whisperwind in Darnassus auf.", description = "<Name>, ich bin mir sicher, dass Tyrande Whisperwind Euch persönlich für Eure Teilnahme an dieser Mission danken wollen wird.\n\nEs mag auf den ersten Blick zwar nicht so aussehen, aber Ihr habt dazu beigetragen, etwas in Gang zu setzen, das unsere Position im Steinkrallengebirge erheblich stärken wird.\n\nFalls Ihr Euch als unseren Verbündeten im Kampf gegen diese Gräueltaten betrachtet, sucht Tyrande im Tempel des Mondes in Darnassus auf.", progress = nil, completion = "Hallo, &lt;Name&gt;. Ich habe tatsächlich schon von Euch gehört, und obwohl Ihr noch so jung seid, freue ich mich zu sehen, welchen Lebensweg Ihr eingeschlagen habt.\n\nIhr würdet mir eine große Ehre erweisen, wenn Ihr das hier als Zeichen meiner Anerkennung annehmen würdet.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAufblühende RobeGrizzly-TunikaWildwaldkette\n\nIhr bekommt außerdem:\n\nBand der elfischen Anmut"},
[1082] = {title = "Neuigkeiten für Schildwache Thenysil", objective = "Kehrt zu Schildwache Thenysil in Ashenvale zurück.", description = "<Name>, Ihr habt Großes geleistet, indem Ihr uns hier geholfen habt.\n\nDie Schildwachen von Ashenvale werden Euch reichlich belohnen, wenn Ihr ihnen mitteilt, dass Gaxim und ich noch am Leben sind. Sagt ihnen, dass wir beim Aufhalten der Venture Company und der Heilung des Landes gute Fortschritte machen.\n\nSucht Tara Thenysil in Astranaar auf. Sie wird sich freuen, dass Ihr mit guten Neuigkeiten kommt.", progress = nil, completion = "Danke, &lt;Name&gt;. Ihr habt den Schildwachen einen großen Dienst erwiesen.\n\nIch freue mich, dass es Kaela... und auch Gaxim gut geht.\n\nIhr habt Eure Anerkennung verdient.", rewards = "Ihr bekommt:\n\n"},
[1083] = {title = "Wütende Geister", objective = "Bringt Kaela Shadowspear im Steinkrallengebirge 8 glimmende Überreste der Feuerelementare des verbrannten Tals.", description = "Ich weiß nicht genau, was die Venture Company dem Tal angetan hat, aber es ist offensichtlich, dass es von den dortigen Kreaturen überwältigt wurde.\n\nSie steckten den Wald in Brand und benutzten ihre zerstörerischen Erfindungen, um so viel wie möglich des Tals zu zerstören.\n\nIn ihrer Dummheit haben sie jedoch auch noch etwas anderes entfesselt: brennende Geister, Elementare der Flammen, der Steine und der Wut.\n\nDas Land wird Elune nicht mehr lächeln sehen, solange diese Kreaturen frei herumstreifen.\n\nBringt mir ihre glimmenden Überreste, um mir zu zeigen, dass Ihr sie dezimiert habt.", progress = "Als ich das verbrannte Tal zum ersten Mal sah, hätte ich fast geweint, <Name>.", completion = "Die Überreste unseres Feindes... Eure Kraft hat uns gute Dienste geleistet, &lt;Name&gt;. Danke.", rewards = "Ihr bekommt:\n\n"},
[1084] = {title = "Verletzte Urtume", objective = "Bringt Kaela Shadowspear im Steinkrallengebirge ein Stück eines zerfressenen Spans.", description = "Es scheint mir offensichtlich, dass die Beschützer des Tales - die Treants - irgendetwas damit zu tun hatten, dass die Venture Company zurückgeschlagen wurde. Leider wurden selbst diese einst so großen Wächter jetzt verderbt.\n\nGaxim glaubt, dass ihre Verderbnis irgendwie mit den Waffen zusammenhängt, die die Goblins während ihres Rückzuges benutzten.\n\nIch bat ihn, eine Probe von einem verwundeten Treant zu nehmen und sie zu untersuchen, um herauszufinden, ob das wirklich stimmt.\n\nBringt mir ein paar Späne, damit der Gnom mehr darüber herausfinden kann ...", progress = "Ich habe das Gefühl, Gaxim wird einen Verwendungszweck für den Span finden, ungeachtet dessen, wofür die Venture Company ihn in der Vergangenheit benutzt haben mag.", completion = "Danke, &lt;Name&gt;.\n\nDas sollte mehr als ausreichend sein, damit Gaxim herausfinden kann, wie die Treants verderbt wurden. Ich werde ihm das sofort bringen.", rewards = "Ihr bekommt:\n\n"},
[1085] = {title = "Wache halten im Steinkrallengebirge", objective = "Sprecht mit Gaxim.", description = "Die Lage hier im Steinkrallengebirge ist offensichtlich düster, wenn Nachtelfen und Gnome zusammenarbeiten.\n\nDie Venture Company hat das Land verwüstet und ich habe einen Großteil meines Leben damit zugebracht, der Zerstörung ein Ende zu setzen.\n\nMan sollte Gaxim nicht vorschnell beurteilen; er versteht die Notwendigkeit, warum wir zusammenarbeiten müssen.\n\nWenn Ihr uns helfen wollt, sprecht zunächst mit Gaxim.\n\nEs tut mir Leid, dass ich Euch jetzt noch nicht mit guten Neuigkeiten zu Tara zurückschicken kann. Aber vielleicht schon bald.", progress = nil, completion = "Tückisch... tückisch und gefährlich ist das Land.\n\nAber ich bin hier, um den Nachtelfen zu zeigen, dass es durch die gute alte Ingenieurskunst und einen Tick Magie ein bisschen sicherer werden kann.\n\nWisst Ihr, der Magie total abzuschwören, würde den Nachtelfen nicht helfen - sie brauchen sie. Die Welt braucht sie. Und nimmt man Ingenieurskunst und Alchimie noch dazu, kann nichts mehr schiefgehen. Die Möglichkeiten sind endlos.", rewards = "Ihr bekommt:\n\n"},
[1086] = {title = "Der Flugapparathafen", objective = "Bringt den Toxinvernebler zum Flugplatz der Venture Company und kehrt dann zu Apothekerin Zamah zurück.", description = "Das Toxin ist bereit. Jetzt muss es nur noch ausgeliefert werden. Ihr, <Name>, müsst es ausliefern.\n\nDie Venture Company muss irgendwelche Mittel und Wege haben, Nachrichten und leichte Fracht zwischen ihrem Hauptquartier und dem Betrieb im Steinkrallengebirge hin- und herzuschicken. Es könnte ein kleiner Flugplatz sein - nicht groß genug für einen Zeppelin, aber vielleicht für einen Flugapparat. Ihr müsst die Gebiete, die von der Venture Company kontrolliert werden, durchsuchen und diesen Flugplatz finden, falls er existiert. Solltet Ihr ihn finden, platziert das Toxin dort.\n\nPlatziert es und lauft, was Ihr könnt.", progress = nil, completion = "Ihr habt den Flugplatz gefunden? Gut gemacht, &lt;Name&gt;! Die Goblins waren sicher ziemlich überrascht von Eurer Lieferung! Hoffen wir, dass das Toxin den Weg zu ihrem Hauptquartier findet.\n\nIhr habt Eurem Volk gute Dienste geleistet, und ich rate Euch, dass Ihr Euch nicht mit Schuldgefühlen quält, die Ihr vielleicht wegen der Vergiftung der Venture Company hegt. Sie hat noch viel Schlimmeres verdient.\n\nUnd wenn die Verlassenen ihren Verbündeten noch ein Körnchen Wissen vermitteln können, dann dies hier:\n\nScheut Euch nicht, dunkle Wege zu begehen... wenn Euch solche Wege zum Sieg führen.", rewards = "Ihr bekommt:\n\n"},
[1087] = {title = "Cenarius' Vermächtnis", objective = "Tötet für Brealyn Firehand in Sonnenfels 4 Söhne des Cenarius, 4 Töchter des Cenarius und 4 cenarische Botaniker.", description = "Ihr könnt Euch nicht vorstellen, wie groß mein Hass auf dieses elende Land ist. Solche Leute wie Cenarius und die Kaldoreidruiden auf dem Gipfel benutzen ihre lächerlichen Mächte, um den Magiefluss zu stoppen, sogar noch so weit von ihrem lächerlichen Besitz entfernt ... ihren geliebten Wäldern.\n\nIch wünschte, ich könnte nach Jaedenar zurückkehren und im Fluss der Magie baden, aber mein Meister erlaubt mir erst dorthin zurückzukehren, wenn meine Arbeit getan ist.\n\nZweifellos liebt Ihr die Nachtelfen und ihre Verbündeten genauso wenig wie ich. Helft mir, dann haben wir vielleicht beide etwas davon.", progress = "Kanalisieren von Magie ist, als würde man mit einem löcherigen Eimer Wasser aus einem Brunnen schöpfen.", completion = "Ich kann es bereits spüren... ja... oh süße Macht... die rauschende Flut. Die Kaldorei sind töricht, dass sie die Geschenke dieser Welt verschmähen und das Durchströmen der Magie unterbinden, die singend durch unsere Adern fließt.\n\nWas ist das Leben doch für ein fahler Abklatsch ohne ihre brennende Umarmung!", rewards = "Ihr bekommt:\n\n"},
[1088] = {title = "Ordanus", objective = "Bringt Braelyn Firehand in der Nähe von Sonnenfels Ordanus' Kopf.", description = "Sie dachten, dass man den Fluss der Magie zum Erliegen bringen könnte. Sie haben sich geirrt. Sie dachten, dass sie Ordanus verstecken könnten, aber ich will seinen Kopf!\n\nDie Magie gewährt mir Durchblick. Ja... da ist er. Ein Scheideweg... auf dem Wipfel eines großen Baumes in Ashenvale. Ein Name... Raynewood. Einer der ältesten Söhne des Waldgottes. Sie haben ihn aus dem Wipfel geschleust, bevor ich ihn finden konnte, aber ihm läuft langsam die Zeit davon.\n\nBringt ihn mir, dann teile ich ein großes Geschenk mit Euch.", progress = "Als mein Meister mich auf den Gipfel des Steinkrallengebirges beorderte, erwartete ich, dass ich einfach nur die Nachtelfen beseitigen musste, die in den heiligen Ruinen unseres antiken Tempels von Azshara herumwimmelten und seine Heiligkeit plünderten... aber Ordanus schlüpfte mir zwischen den Fingern hindurch.", completion = "Ich kannte Ordanus einst, aber das ist schon lange her. Er besaß die Arroganz seiner Art und stellte sich selbst noch über die Hochgeborenen.\n\nJetzt trägt er seinen Kopf nicht mehr so hoch, nicht wahr, &lt;Name&gt;?\n\nIch versprach Euch eine Belohnung, und die sollt Ihr haben. Kommt mit mir.", rewards = "Ihr bekommt:\n\n"},
[1089] = {title = "Der Höhlenbau", objective = "Begebt Euch zum Höhlenbau auf den Steinkrallengipfel. Benutzt den Torhüterschlüssel, um Euch die versteckten Gegenstände der Druiden zu besorgen. Benutzt diese Gegenstände, um den Hort des Krallenbaus zu öffnen.", description = "Die Druiden errichteten den Krallenbau auf dem Steinkrallengipfel, in dem sie viele mächtige Gegenstände aufbewahren.\n\nSie haben sich ein komplexes Schema ausgedacht, damit sie nicht in die falschen Hände gelangen.\n\nGlücklicherweise konnte ich einem von ihnen... ein paar Details entlocken.\n\nVersteckt in einer kleinen Laterne am Eingang des Baus werdet Ihr den Torhüterschlüssel finden. Damit könnt Ihr die Behälter öffnen, die über den ganzen Bau verteilt sind. Mit den Gegenständen aus diesen Behältern wiederum könnt Ihr ihren Hort öffnen, der sich in einem der zentralen Bereiche befindet.", progress = "In den Stein sind drei Schlüssellöcher eingearbeitet.", completion = "Als die drei Schlüssel in die jeweiligen Öffnungen gesteckt werden, tauchen inmitten des glimmenden Lichtes ein paar Gegenstände auf.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nHeiliges BandPanther-RüstungKampfschiff-Gamaschen"},
[1090] = {title = "Gerenzos Befehle", objective = "Nehmt das rätselhafte Erz, nachdem Piznik es fertig abgebaut hat.", description = "Wisst Ihr, ich war hier einst die zweitwichtigste Person. Das hat sich alles geändert, als Gerenzo hier übernahm. Hat meinen Boss Ziz Fizziks gefeuert und mich zum Arbeiten nach unten in die Minen geschickt. Ziz sagte mir aber, dass ich hier bleiben und Informationen sammeln solle. Sein neuer Boss wird uns gut bezahlen, wenn wir rausfinden, was Gerenzo plant.\n\nEgal, was ich weiß ist, dass Gerenzo befohlen hat, dass Riesenmengen von diesem gold-grünen Erz abgebaut werden sollen. Ich hol Euch eine Probe, damit Ihr sie Ziz bringen könnt, aber Ihr müsst Euch vor Patrouillen hüten, während ich es hole.", progress = nil, completion = "Danke, &lt;Name&gt;. Sah für einen Moment ziemlich riskant aus und wir haben vielleicht etwas zu viel Aufmerksamkeit auf uns gelenkt.\n\nDas Wichtigste ist aber, dass wir eine Erzprobe haben, die wir so schnell wie möglich zu Ziz bringen sollten.", rewards = "Ihr bekommt:\n\n"},
[1091] = {title = "Kaelas Update", objective = "Bringt Kaela Shadowspear die Dokumente der Venture Company.", description = "<Name>, bringt Kaela diese Briefe. Ich bin mir sicher, dass sie das interessiert. Oder zumindest die Schildwachen.\n\nErzählt Ihr unbedingt, wie erfolgreich wir waren und dass wir es ohne ein bisschen Magie nie geschafft hätten.", progress = "Ja, <Name>? Was kann ich für Euch tun?", completion = "Das ist in der Tat interessant.\n\nIhr und Gaxim habt das sehr gut gemacht, &lt;Name&gt;. Danke.", rewards = "Ihr bekommt:\n\n"},
[1092] = {title = "Gerenzos Befehle", objective = "Bringt Ziz Fizziks im Steinkrallengebirge das unbekannte Erz.", description = "Ich glaube, ich sollte auch langsam darüber nachdenken, hier zu verschwinden. Es wird nicht lange dauern, bis die da oben erfahren, was hier gelaufen ist, und ich bin sicher, dass die keinen großen Wert darauf legen, mich wiederzusehen.\n\nIch schleich mich raus und treff mich mit Ziz. Hoffentlich kann er mir einen neuen Job besorgen!\n\nIch werde versuchen, hier ein bisschen Ordnung zu schaffen, aber Ihr solltet die Erzprobe sofort zu Ziz bringen. Er sagte mir, dass er irgendwo an der Westseite der Scherwindklippe sein Lager aufgeschlagen hat. Viel Glück.", progress = "Kann ich Euch irgendwie helfen?", completion = "Ahhh, ich wusste, dass es richtig war, Piznik zu sagen, dass er dort bleiben soll. Die Ingenieure in Undermine werden sich das bestimmt unbedingt ansehen wollen...\n\nNatürlich werde ich ein kleines Stückchen für mich behalten, aber das müssen sie ja nicht unbedingt wissen, was?", rewards = "Ihr bekommt:\n\nBagger-Stiefel"},
[1093] = {title = "Superschnitter 6000", objective = "Besorgt für Ziz Fizziks im Steinkrallengebirge die Blaupausen für den Superschnitter 6000.", description = "Schrecklich, was die Venture Company hier getan hat, was? Was haben die sich dabei gedacht? Eine Goblin-Firma, die einen Gnom anheuert!\n\nEin Glück für mich, dass Sputtervalve ein Genie erkennt, wenn es vor ihm steht. Hat mich eingestellt, gleich nachdem ich gefeuert wurde!\n\nSagte mir, sie wollten eine riesige Holzfällmaschine bauen, und Sput möchte, dass ich für ihn die Pläne dazu stehle. Leider wird Gerenzo - dieser verdammte Gnom - mich umlegen, sobald er mich sieht ... würdet Ihr vielleicht die Pläne für mich stehlen? Ihr solltet sie bei einem ihrer Maschinenführer finden.", progress = "Habt Ihr die Pläne gefunden? Ich brenne darauf, meinen neuen Boss zu beeindrucken. Hoffentlich überzeugt ihn das von meiner Loyalität - soweit man ihn überhaupt überzeugen kann... Goblin-Ehre, Ihr wisst schon. Vielleicht ist er dann geneigt, sich mein ziemlich beeindruckendes Genie zu Nutze zu machen.", completion = "He, ist es das, für was ich es halte? Großartig!\n\nDann sehen wir mal. Ähhh... wie soll denn das jemand verstehen... versteh einer die Denkweise von Gnomen. Ich sag Euch was, ich wundere mich, dass sie Räder bauen können, ganz zu schweigen von diesen Flugapparaten, die sie so sehr lieben.", rewards = "Ihr bekommt:\n\n"},
[1094] = {title = "Weitere Instruktionen", objective = "Bringt Sputtervalve im Brachland den versiegelten Umschlag.", description = "In diesem Umschlag befinden sich alle Informationen, die ich mir schnappen konnte, bevor sie mich vor die Tür setzten... Interne Dokumente der Venture Company, ein paar Handbücher, technisches Zeugs... Oh, und natürlich die Blaupausen für den Superschnitter 6000.\n\nSputtervalve hat sich bei Ratchet im Brachland niedergelassen. Sollte nicht schwer sein, ihn zu finden. Er ist ein kleiner, grüner Kerl.", progress = "Hallo! Wie kann ich Euch helfen?", completion = "Fizziks, hä? Kann nicht sagen, dass ich ihm traue, aber diese Informationen scheinen ganz brauchbar. Was würde ich darum geben, die Venture Company endlich los zu sein.\n\nDie haben sich allerdings ein paar recht gute Maschinen ausgedacht... Ich kann nicht bestreiten, dass wir von ein paar Verbesserungen, die sie entwickelt haben, ganz gut profitiert haben.", rewards = "Ihr bekommt:\n\n"},
[1095] = {title = "Weitere Instruktionen", objective = "Bringt Ziz Fizziks im Steinkrallengebirge die neuen Befehle.", description = "Die Tatsache, dass die Venture Company diesen Gnom angestellt hat, hat in Undermine für einiges Aufsehen gesorgt. Die Handelsbarone finden es nicht gut, dass Razdunk mit Gerenzo gemeinsame Sache macht.\n\nRiddlevox hat mich gebeten, mich um das Problem zu kümmern und ich bin mir sicher, dass einer oder zwei dieser Handelsbarone ihn dazu angewiesen haben. Natürlich hat mir der Direktor das nicht erzählt. Sagen wir einfach, ich hätte so eine Ahnung.\n\nWie dem auch sei, Gerenzo muss entfernt werden und es wäre eine passende Prüfung, das Fizzik erledigen zu lassen.", progress = nil, completion = "Gerenzo eliminieren? Also das ist eine Sache, gegen die ich nichts einzuwenden habe.\n\nGnome an sich sind ja schon schlimm genug, aber was ich alles über Gerenzo gehört habe, schlägt dem Fass den Boden aus. Offenbar war er einer der leitenden Ingenieure in Gnomeregan, wo er an einem Geheimprojekt mitwirkte - wir konnten Dun Morogh nie gut genug infiltrieren, um genauere Einzelheiten darüber herauszufinden. Es war ein Fehlschlag. Unseren Berichten nach soll das, was immer es auch war, ihnen buchstäblich um die Ohren geflogen sein.", rewards = "Ihr bekommt:\n\n"},
[1096] = {title = "Gerenzo Wrenchwhistle", objective = "Bringt Ziz Fizziks im Steinkrallengebirge Gerenzo Wrenchwhistles mechanischen Arm.", description = "Ich habe Gerenzo einmal getroffen, und lasst mich Euch eines sagen, er ist nicht gerade eine Schönheit. Sein Fleisch sieht aus, als würde es faulen. Dazu hat er noch überall an seinem Körper Metallteile und Zeugs angeflanscht und sogar einige seiner Körperteile durch mechanische ersetzt.\n\nNordöstlich von hier, weit oberhalb des Felskesselsees in der Nähe des Wasserrades beaufsichtigt Gerenzo die gesamte Stätte. Ich könnte mich unmöglich bis da hinauf durchkämpfen und schon gar nicht mich mit Gerenzo anlegen ... Aber Ihr seht aus, als könntet Ihr es schaffen.\n\nWenn Ihr ihn für mich tötet, soll es Euer Schaden nicht sein!", progress = "Sputtervalve wird einen Beweis für Gerenzos Tod haben wollen. Ich glaube, dieser mechanische Arm wird reichen.", completion = "Man sehe sich dieses Ding an... so was kann sich auch nur ein Gnom ausdenken. Ich kann nicht verstehen, warum man sich einen Arm abschneidet und durch so was ersetzt, wenn man doch beide Arme behalten und einfach einen dritten ansetzen könnte!\n\nGnome, ich sag's Euch...\n\nZumindest ist Gerenzo jetzt außer Gefecht. Hoffentlich ist das Beweis genug und Sputtervalve bringt mich in einer der Tüftlerverband-Werkstätten in Gadgetzan oder sogar Undermine unter.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nIngenieurs-UmhangZeichner-Stiefel\n\nIhr bekommt außerdem:\n\n"},
[1097] = {title = "Elmores Aufgabe", objective = "Sprecht mit Grimand Elmore.", description = "In Stormwind gibt es einen Zwergen-Waffenschmied namens Grimand Elmore, der mal angedeutet hat, dass er Hilfe bei einer Lieferung bräuchte. Ich glaube, er möchte ein Paket in seine Heimat im Norden schicken.\n\nIhr habt da ein paar schöne kräftige Beine! Falls Ihr also an ein wenig Beinarbeit interessiert seid, sprecht mit Grimand. Wir könnten Euch hier unten brauchen, aber wir müssen auch unsere Bande mit den Zwergen stärken.\n\nIhr findet Grimand Elmore im Waffenladen im Zwergendistrikt von Stormwind, im nordöstlichen Teil der Stadt.", progress = nil, completion = "Ihr seid hier, um mir mit meiner Lieferung zu helfen? Sehr gut!", rewards = "Ihr bekommt:\n\n"},
[1098] = {title = "Todespirscher in Shadowfang", objective = "Sucht die Todespirscher Adamant und Vincent.", description = "Als Vorbereitung auf einen Überfall auf Shadowfang wurden zwei Todespirscher in die Burg geschickt, um Informationen zu sammeln. Das war vor mehreren Tagen und sie sind noch nicht wieder zurück, aber wir brauchen ihren Bericht, wenn wir auf einen erfolgreichen Angriff hoffen wollen!\n\nDas ist Eure Aufgabe, <Name>. Geht zu Burg Shadowfang im Süden und sucht die Todespirscher Adamant und Vincent. Findet sie und helft ihnen, falls es erforderlich ist.\n\nDiese Mission ist nicht nur gefährlich, sondern auch lebenswichtig, <Name>. Versagt bitte nicht.", progress = nil, completion = "Vincents Körper liegt zerschmettert und leblos da.\n\nTodespirscher Adamant wird Hadrec zwar seinen Bericht schicken... aber was immer Vincent zusätzlich noch wusste, wird für immer sein Geheimnis bleiben.\n\nSeine Hand jedoch umklammert ein kleines Stück Plunder...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nGeisterhafter Mantel"},
[1099] = {title = "Die Goblins haben gewonnen!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGoblin-Preiskasten"},
[1100] = {title = "Lonebrows Tagebuch", objective = "Lest Henrig Lonebrows Tagebuch.", description = "Ihr öffnet langsam das verwitterte Tagebuch des Henrig Lonebrow...", progress = "So bekümmert, wie Ihr ausseht, würde ich sagen, dass etwas nicht stimmt...", completion = "Ihr sagt, Ihr habt das Tagebuch bei einem verstorbenen Zwerg gefunden? Gebt mir einen Moment Zeit, um durch die Seiten zu stöbern...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1101] = {title = "Die Greisin des Krals", objective = "Bringt Falfindel Waywarder in Thalanaar Razorflanks Medaillon.", description = "Armer Heralath! Und dieser Zwerg... Lonebrow. Was war er doch für eine mutige Seele.\n\nSo viel Heldenmut darf nicht umsonst gewesen sein. Diese Greisin... Charlga Razorflank... muss aufgehalten werden.\n\nSicher, es wird gefährlich werden, den Kral zu bespitzeln. Wir haben keine Zeit, um Darnassus zu informieren. <Name>, stellt eine Gruppe zusammen, um die Greisin zu erschlagen.\n\nBringt mir Razorflanks Medaillon zum Beweis ihres Ablebens.", progress = "Solange Charlga Razorflank im Kral von Razorfen Truppen rekrutiert, ist dieses Land in großer Gefahr.", completion = "Der Greisin wurde der Garaus gemacht. Das sind phantastische Neuigkeiten, &lt;Name&gt;.\n\nIn diesen gefährlichen Zeiten ist es erfrischend, jemanden zu sehen, der so mutig ist wie Ihr.\n\nDa Razorflanks Diener beseitigt sind, können wir jetzt unsere Studien in diesem Gebiet fortsetzen. Vielleicht erfahren wir ja jetzt mehr darüber, was die Ruhestätte Agammagans verderbt hat.\n\nIch fürchte allerdings, dass die Antwort auf diese Frage auch mit Verrat zu tun hat ...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBeryllpolsterSteinfaustgurtMarmorierter Rundschild\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\nDonnerbüchse \"Magierauge\""},
[1102] = {title = "Ein schreckliches Schicksal", objective = "Bringt Auld Stonespire in Thunder Bluff Razorflanks Herz.", description = "Es war edel von unserem Anführer Cairne, unser Volk hier in Thunder Bluff zu vereinen.\n\nIch kann jenen jedoch nicht vergeben, die uns so leicht aus dem Land unserer Vorfahren vertrieben haben. Jahrhundertelang lebte mein Volk im südlichen Brachland. Das Land war uns heilig. Aber wir wurden von zahllosen Feinden vertrieben.\n\nEin schreckliches Schicksal erwartet die Greisin Charlga Razorflank, die im Kral von Razorfen eine abscheuliche Armee zusammenzieht.\n\nBringt mir Razorflanks Herz, damit ich in Frieden sterben kann, <Name>.", progress = "Sobald ich weiß, dass die elenden Bestien des Krals von Razorfen aus ihrem elenden Unterschlupf vertrieben wurden, kann ich in Frieden ruhen, in dem Wissen, dass Rache geübt wurde. \n\nHabt Ihr die Stacheleber aus dem Kral vertrieben? Bringt Ihr mir gute Neuigkeiten in Form von Razorflanks Herz?", completion = "Wie ich sehe, kennt der widerliche Stamm des Krals von Razorfen jetzt den Schmerz meines Volkes. Das geschieht den elenden Bestien recht.\n\nJemanden von heiligem Boden zu vertreiben ist eine Sünde, die nur durch die schlimmste Form der Rache gesühnt werden kann.\n\nDanke, &lt;Name&gt;, dass Ihr mir in diesen Zeiten der Not geholfen habt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBeryllpolsterSteinfaustgurtMarmorierter Rundschild\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1103] = {title = "Ruf des Wassers", objective = "Bringt Tiev Mordune im Silberwald ein Wassersapta, wenn Ihr nicht mit der schwachen Wassermanifestation gesprochen habt.", description = "Seid gegrüßt, <Bruda/Schwesta>! Seid auch Ihr gekommen, um das Wasser hier zu läutern und Islen Euer Wissen zu beweisen?\n\nIch habe den verderbten Wassergeist gerade selbst bezwungen und bin grad dabei, die Armschienen un' verbleibenden Wassertropfen in die Kohlenpfanne zu geben.\n\nWas'n das? Ahhh. Tiev versteht nur zu gut, wenn wat falsch läuft. Tja, Tiev kann Euch echt helfen, wenn Ihr den Wassergeist wieda seh'n wollt.\n\nBringt mir 'in Wassersapta von Islen als Beweis, dass Ihr bereit seid, un' ich bin bereit, meinen Teil beizutrag'n.", progress = "Habt Ihr dat Sapta, Bruda?\n\nIch kenne noch jemanden, der Probleme hatte, nachdem er den verderbten Wassergeist besiegt hadde - hat wohl zu lange gewartet und kam für seinen Jeschmack zu schnell aus der Geisterwelt. Würde nich gern seh'n, dass dat noch wem passiert, also werde ich hier noch 'ne Weile wart'n und sichergehen, dat sonst keiner meine Hilfe braucht.", completion = "Ahhh, dann seid Ihr bereit...\n\nIch werde dann mal meine Sachen in die Kohlenpfanne leg'n und Ihr könnt denn auch mit'm Geist red'n.\n\nUn' macht Euch keine Sorg'n darüber, mit'm Sapta in die Geisterwelt zu seh'n... der alde Tiev kennt'n Trick oder zwei zur Funktion der Saptamagie.\n\nKommt schon, begebt Euch mit mir zum Schrein und lasst uns zusamm'n mit den Geistern sprech'n, Bruda.", rewards = nil},
[1104] = {title = "Salziges Gift", objective = "Bringt Fizzle Brassbolts in der schimmernden Ebene 6 Einheiten salziges Skorpidgift.", description = "Ich habe so viele Pläne für unseren Raketenwagen! So viele! Und ich muss sie alle ausprobieren!!!\n\nIch arbeite gerade an einem neuen Treibstoff; an einem, der wirklich, wirklich, wirklich heiß ist! Die Mixtur stimmt zwar noch nicht ganz, aber ich glaube, ich weiß, was noch fehlt...\n\nDie Skorpide, die die schimmernde Ebene durchwandern, haben ein Gift mit Unmengen Salz darin. Es ist einzigartig! Und es ist genau das, was ich brauche!\n\nBringt mir das Gift und vertraut mir: unser Wagen wird fliegen!", progress = "Hi, hi, hi! Habt Ihr das Gift???", completion = "Toll! Dieses Gift wird wunderbar funktionieren! Danke, &lt;Name&gt;!\n\nJetzt muss ich ihn nur noch einkochen lassen, Skipper-Otomer und einen Nagakatalysator hinzufügen, und... Mist! Wo sind meine Notizen?!", rewards = "Ihr bekommt:\n\n"},
[1105] = {title = "Gehärtete Schalen", objective = "Bringt Wizzle Brassbolts in der schimmernden Ebene 9 gehärtete Schildkrötenpanzer.", description = "Mein Bruder arbeitet an einem neuen Treibstoff für seinen Raketenwagen. Er ist brillant, ehrlich. So brillant, dass... Ich glaube, der neue Treibstoff, den er da entwickelt, ist stark genug, um sich durch das Chassis des Wagens zu fressen!\n\nIch würde gern die Treibstofftanks verstärken, bevor das passiert.\n\nDie Schildkröten draußen auf der Ebene haben sehr starke Panzer. Ich möchte daraus neue Tanks für unseren Raketenwagen bauen. Tanks, die den neuen Treibstoff meines Bruders aushalten.\n\nIhr seht mir verantwortungsbewusst genug aus. Holt Ihr mir solche Panzer?", progress = "Mein Bruder macht Fortschritte mit seinem neuen Treibstoff, und das macht mir Sorgen. Ich muss so bald wie möglich mit meiner Arbeit mit einem Schildkrötenpanzer-Treibstofftank beginnen!\n\nHabt Ihr die Panzer schon, <Name>?", completion = "Ihr habt sie! Danke, &lt;Name&gt;!\n\nWow, diese Panzer sind härter als ich dachte! He, ich ruiniere mir bestimmt einen ganzen Kasten voller Werkzeuge, wenn ich daran arbeite!", rewards = "Ihr bekommt:\n\n"},
[1106] = {title = "Martek der Verbannte", objective = "Bringt Martek dem Verbannten im Ödland Fizzles Brief.", description = "Ich entwickle einen neuen Motor, mit dem der Wagen so schnell wie der Wind wird! Schnell genug, um zu fliegen, ich weiß es! Ich muss nur ein paar Kolben herstellen, die sehr, sehr große Belastungen aushalten. All meine bisherigen Versuche sind fehlgeschlagen, weil ich die Kolben einfach nicht robust genug herstellen kann!\n\nAber es gibt jemanden, der wissen könnte, wie es geht.\n\nSein Name ist Martek der Verbannte. Er ist ein großartiger Schmied und weiß mehr über Metall als alle anderen. Bringt ihm diesen Brief, ich weiß, dass er helfen kann!\n\nAber er lebt weit, weit weg - in Azeroth, im Ödland, in einem Lager, zusammen mit einem Goblin!\n\nSucht ihn!", progress = "Tja, da habt Ihr mich also gefunden. Schön für Euch.\n\nSeid Ihr wegen der Axt hier, die ich für Gath'Ilzogg geschmiedet habe? Oder seid Ihr hier, um die Ehre der Herzogin Pamay zurückzufordern?\n\nWisst Ihr, es ist mir völlig egal, warum Ihr hier seid. Wenn Ihr hier seid um zu kämpfen, dann bringen wir's hinter uns ...", completion = "Fizzle hat Euch geschickt? Also das ändert die Sachlage! Natürlich helfe ich Euch. Fizzle und sein Bruder sind zwei der wenigen Leute, die mich nicht tot sehen wollen!\n\nFizzle will also Kolben herstellen, was? Kolben, die stark genug sind, um großen Belastungen standhalten zu können; was auch immer ihm vorschweben mag. Und wie ich Fizzle kenne, wird sein neuer Wagen ein Vulkan auf Rädern!", rewards = "Ihr bekommt:\n\n"},
[1107] = {title = "Verkrustete Schwanzflossen", objective = "Bringt Fizzle Brassbolts in der schimmernden Ebene 10 verkrustete Schwanzflossen.", description = "Unser Raketenwagen ist das schnellste, was es auf der Ebene gibt! So schnell, dass... ich fürchte, die Reibung reißt ihn auseinander!\n\nUm das zu verhindern, muss ich einen Stoff entwickeln, der die beweglichen Teile des Wagens überzieht. Er muss hart sein, aber nicht spröde, und er muss resistent gegen Salzkorrosion sein, sonst wird der Wagen, während er sich in der schimmernden Ebene befindet, zerfressen.\n\nHabt Ihr schon mal vom finsteren Riff gehört, <Name>? Es liegt vor der Küste des Schlingendorntals. Dort leben Salzschuppenmurlocs, deren Schwanzflossen unabdingbare Zutaten zu meinem Stoff sind.", progress = "Habt Ihr die Schwanzflossen? Wenn ich unseren Wagen nicht vor seinem eigenen Tempo schützen kann, wird er bei den Rennen nicht lang halten.", completion = "Danke, &lt;Name&gt;! Wenn ich die zermahlen und mit ein paar anderen Zutaten vermischt habe, ist mein Stoff fertig. Danach wird der Wagen vor seinem eigenen Tempo sicher sein.\n\nSofern er nicht mit irgendwas zusammenstößt...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1108] = {title = "Indurium", objective = "Bringt Martek dem Verbannten im Ödland 10 Induriumspäne.", description = "Ich bin nicht hier draußen, weil ich mich vor Leuten verstecken will. Das Ödland ist reich an Metall, <Name>, wenn man den Mut hat, es sich zu holen.\n\nDas Metall heißt Indurium, und wie das Schicksal so spielt, soll es angeblich hohen Widerstand gegen Hitze und Belastung bieten. Das könnte genau das Richtige für Fizzles Wagen sein.\n\nAber wir sollten sichergehen. Bringt mir eine Indurium-Probe, dann kann ich seine Eigenschaften testen.\n\nEchtes Induriumerz liegt tief drinnen in Uldaman, aber die Steingrufttroggs des Ödlandes tragen manchmal Späne davon mit sich herum. Bringt mir diese Späne.", progress = "Habt Ihr Induriumspäne gefunden, <Name>? Meine Schmiede ist aufgeheizt und bereit, sie zu testen.", completion = "Ah ja, ausgezeichnet. Geben wir sie ins Feuer und sehen wir, wie sie sich machen...", rewards = "Ihr bekommt:\n\n"},
[1109] = {title = "Go, Go, Guano!", objective = "Bringt dem Apothekermeister Faranell in Undercity 1 Häufchen Kral-Guano.", description = "Wie Ihr seht, <Name>, befassen wir uns mit einigen sehr... interessanten Experimenten in der Königlichen Apothekervereinigung.\n\nAls Meister hier ist es meine Aufgabe, die anspruchsvollsten unserer alchimistischen Versuche zu überwachen. So viel Arbeit und nur so wenig Zeit!\n\nIhr seht weit gereist aus, <Klasse>. Vielleicht könnt Ihr mir helfen.\n\nIch brauche eine rare Substanz. Es ist dieses widerliche Zeug, das von einer raren Fledermausart stammt, die man nur in einem Dreckloch namens Kral von Razorfen findet. Bringt mir den Guano der Kral-Fledermäuse, damit wir mit unserer Arbeit beginnen können...", progress = "Ah, wie ich sehe, seid Ihr zurückgekehrt. Konntet Ihr etwas Kral-Guano beschaffen?", completion = "Ausgezeichnet! Das ist genau das, was wir brauchen, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1110] = {title = "Raketenwagenteile", objective = "Bringt 30 Raketenwagenteile zu Kravel Koalbeard in der schimmernden Ebene.", description = "Hi-hi, bei den vielen Rennen, die hier stattfinden, ist es nicht verwunderlich, wenn dabei ein paar Unglücksfälle passieren. Wenn man sich in der schimmernden Ebene umschaut, sieht man ständig Spuren vergangener Unfälle - überall liegen Teile von Raketenwagen herum.\n\nUnd diese Teile bedeuten für die Gnome und Goblins bares Geld. Sie suchen ständig nach weiteren neumodischen Apparaten, um sie an ihre Autos anzubauen.\n\nAlso zieht los und bringt mir die Teile. Bringt mir einen Haufen und ich werde Euch gut bezahlen.", progress = "<Name>, seid Ihr in der Ebene gewesen? Habt Ihr mir die Ladung Teile gebracht, die ich wollte?", completion = "Boah, seh sich einer das an! Es sind ein paar echt gute Sächelchen in diesem Schrotthaufen. Ich bin sicher, die kann ich für ein schönes Sümmchen verpfänden.\n\nUnd... sehe ich da ein zerquetschtes Ohr zwischen zwei Metallteilen??? Autsch! He, mit diesem Piloten möchte ich echt nicht tauschen!\n\nDanke, &lt;Name&gt;. Hier ist Eure Bezahlung. Und hier noch ein kostenloser Rat...\n\nWenn man verbissen genug sucht, kann man immer Kapital aus der Tragödie eines anderen schlagen.", rewards = "Ihr bekommt:\n\n"},
[1111] = {title = "Werftmeister Dizzywig", objective = "Bringt Kravels Teile-Bestellung zu Werftmeister Dizzywig in Ratchet.", description = "Mein Job ist es, den Leuten zu beschaffen, was sie möchten, und diese Gnome da drüben möchten Teile bestellen. Ihre Teile wurden vor einer Woche nach Ratchet geschickt, aber es war mir nicht möglich, dorthin zu reisen.\n\nAlso, seid Ihr bereit, mir die Kleinarbeit abzunehmen? Geht nach Ratchet und gebt diese Teile-Bestellung an Werftmeister Dizzywig - er wird wahrscheinlich bei den Docks sein.\n\nWenn Ihr das macht, habe ich weitere Aufträge für Euch.\n\nAufträge, bei denen eine Menge Profit rausspringen kann ...", progress = "Sprecht! Sagt mir, ladet Ihr aus oder ein?", completion = "Oh, ja. Teile für Kravel. Schön, dass Ihr hier seid. Diese Dinger liegen seit Tagen hier, ich fürchtete schon, sie würden Rost ansetzen.", rewards = "Ihr bekommt:\n\n"},
[1112] = {title = "Teile für Kravel", objective = "Bringt Kravels Teile zu Kravel Koalbeard in der schimmernden Ebene.", description = "Hier ist Kravels Paket, <Name>. Und wenn Ihr es zustellt, sagt ihm bitte... wenn er weitere spezielle Lieferungen möchte, dann muss er bezahlen!", progress = "Seid Ihr in Ratchet gewesen und habt die Teile bekommen?", completion = "Prima, Ihr habt sie! Jetzt müssen wir sie zu den Gnomen bringen. Aber vorher...\n\nNehmen wir einen kleinen Gegenstand heraus...", rewards = "Ihr bekommt:\n\n"},
[1113] = {title = "Herzen des Eifers", objective = "Apothekermeister Faranell in Undercity möchte 20 Herzen des Eifers.", description = "Warum ich eine rare Art von Guano benötige, fragt Ihr Euch? Also bei diesem Experiment möchte ich wissen, wie zwei diametral entgegengesetzte chemische Substanzen aufeinander wirken, besonders wenn beide mit einem höchst toxischen Agens kombiniert werden, um die ... garstigsten Resultate zu erzielen.\n\nIn der Nordostspitze von Tirisfal liegt das Scharlachrote Kloster. Dort versammeln sich die wahnsinnigen Jünger des Scharlachroten Kreuzzuges. Tötet sie und bringt mir ihre übereifrigen Herzen.\n\nUnser Gebräu wird äußerst tückisch sein!", progress = "Seid Ihr vom Scharlachroten Kloster zurückgekehrt? Ich brauche viele Herzen für dieses aufregende Experiment!\n\nZweifellos werden Varimathras und die dunkle Fürstin ebenfalls erfreut sein, den Scharlachroten Abschaum loszuwerden...", completion = "Was für eine Unmenge an Gekröse Ihr mir da bringt, &lt;Name&gt;! Eure Bemühungen waren exzellent!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1114] = {title = "Lieferung für die Gnome", objective = "Bringt die empfindlichen Autoteile zu Fizzle Brassbolts.", description = "Jetzt, wo ich habe, was ich brauche, gebt diese Teile Fizzle Brassbolts. Er wartet schon lange darauf - ich bin sicher, das kleine Teil, das ich behalten habe, wird er nicht vermissen...\n\nUnd ich würde ihn auch nicht darauf hinweisen. Es war klein und wertlos.\n\nGlaubt mir.", progress = "Habt Ihr denn etwas für mich? Großartig! Lasst sehen!", completion = "Da sind sie ja! Meine Hydro-Ratschen und Repetierbolzen! Diese genügen voll und ganz. Danke!", rewards = "Ihr bekommt:\n\n"},
[1115] = {title = "Der Gerüchteverbreiter", objective = "Sprecht mit Krazek in Booty Bay.", description = "Jetzt, da wir diesen Dienst für die Gnome geleistet haben, wird es Zeit, den Goblins einen Gefallen zu tun! \n\nIch habe gehört, dass der Goblin-Rennfahrer Nazz Steamboil diesen Namen nicht immer getragen hat. Ich frage mich, weshalb er ihn änderte. Ob es wohl ein Geheimnis ist und... wie viel ihm dieses Geheimnis wert ist.\n\nWenn jemand die Wahrheit kennt, dann Krazek aus Booty Bay an der Südspitze des Schlingendorntals. Sprecht mit Krazek und fragt ihn nach unserem Goblin-Rennfahrer.\n\nWenn Ihr nützliche Informationen aus ihm herausbekommt, springt vielleicht Profit für uns raus.", progress = nil, completion = "Ihr wollt etwas über Nazz Steamboil wissen? Er ist Rennfahrer draußen in der schimmernden Ebene, nicht?\n\nKlar kann ich über den was rauskriegen... aber leicht wird das nicht. Und es dauert.\n\nUnd kostet.", rewards = "Ihr bekommt:\n\n"},
[1116] = {title = "Traumstaub im Sumpf", objective = "Bringt 10 Körnchen Traumstaub zu Krazek in Booty Bay.", description = "Es ist ein großer Gefallen, diese Informationen über Nazz zu beschaffen, <Name>. Ja, ein großer Gefallen. Aber Ihr habt den weiten Weg von der schimmernden Ebene auf Euch genommen... seid Ihr bereit, noch etwas weiter zu reisen?\n\nIhr könntet doch etwas für mich besorgen, während ich Kontakt mit meinen Informanten aufnehme, hm?\n\nHmm... was könnte es denn sein? Wie wäre es mit Traumstaub von den Großdrachenwelpen und Wyrmkin aus den Sümpfen des Elends? Ja, ich hätte gern etwas Traumstaub für meinen Schnupftabakbeutel!\n\nBringt ihn mir, <Name>, und ich gebe Euch die gewünschten Informationen.", progress = "Schon wieder hier? Habt Ihr meinen Traumstaub?", completion = "Seht Euch das an. Ihr habt den Traumstaub gefunden!\n\nUnd Wie hat Euch der Sumpf gefallen, &lt;Name&gt;? Ist nicht leicht, dort eine warme Mahlzeit zu bekommen, hm?", rewards = "Ihr bekommt:\n\n"},
[1117] = {title = "Gerüchte für Kravel", objective = "Bringt die Goblin-Gerüchte zu Kravel Koalbeard in der schimmernden Ebene.", description = "Ich musste einige Gefälligkeiten erweisen, eine rare Flasche Elfenwein herschenken und mir selbst einiges zusammenreimen! Aber ich habe die Informationen, die Ihr sucht.\n\nHier, ich habe einen Brief mit einigen sehr interessanten Infos über Euren Freund Nazz Steamboil verfasst. Macht damit, was Ihr wollt - für mich wäre es zu gefährlich, ihn zu benutzen.\n\nSagt nur keinem, woher Ihr das habt!", progress = "Habt Ihr etwas über Nazz Steamboil? Etwas, das er unbedingt geheim halten möchte?", completion = "Ach nein! Das ist interessant... sehr interessant. He, vielleicht sollte ich mich vor dem Goblin-Rennfahrer verneigen, wenn ich ihn das nächste Mal sehe.\n\nDas ist eine Menge wert, &lt;Name&gt;. Nazz wird ganz bestimmt ein kleines Vermögen bezahlen, damit dieses Geheimnis... ein Geheimnis bleibt.", rewards = "Ihr bekommt:\n\n"},
[1118] = {title = "Zurück nach Booty Bay", objective = "Bringt Kravels Plan zu Crank Fizzlebub in Booty Bay.", description = "<Name>, Ihr seid ein <Klasse>, dem ich trauen kann. Ihr werdet den Auftrag erledigen und die Klappe halten.\n\nIch habe einen neuen Plan geschmiedet. Er ist riskant, aber wenn er funktioniert, könnten wir beide gut absahnen! Und ich glaube, Ihr seid der Richtige, um das durchzuziehen.\n\nAls Erstes müsst Ihr nach Booty Bay zurückkehren. Nun, ich bitte um Verzeihung, <Name>. Ich weiß, meine letzte Aufgabe führte Euch dorthin. Aber sprecht diesmal mit Crank Fizzlebub.\n\nGebt ihm diesen Brief. Und wenn er um Unterstützung bittet, dann tut, was Ihr könnt, um ihm zu helfen. Es wird sich lohnen.", progress = "Hallo, hallo. Und was führt einen so edlen Eurer Art nach Booty Bay, <Volk>?", completion = "Verstehe. Kravel hat einen großen Plan in petto. Er ist ein finsterer Schurke - das mag ich an ihm.\n\nIhr braucht also etwas, das den Geist verwirrt, hm? Etwas Mächtiges...\n\nOb man die Mixtur nehmen könnte, die Zanzil seinen Zombies gibt...", rewards = "Ihr bekommt:\n\n"},
[1119] = {title = "Zanzils Mixtur und Fools Starkbier", objective = "Bringt Fools Starkbier zu Kravel in der schimmernden Ebene zurück.", description = "Ich habe herausgefunden, wie man aus Zanzils Mixtur mit Starkbier ein mächtiges Getränk macht. Fools Starkbier. Und ich glaube, genau das braucht Kravel. Probiert es einfach mal aus und lasst mich wissen, wie es wirkt.\n\nUnd behaltet das Zeug nicht zu lange unbenutzt, <Name>. Zanzils Mixtur hat eine seltsame Wirkung auf die Hefe des Starkbiers und regt sie heftig an. Sie bleibt nicht ewig frisch.", progress = "Hallo, <Name>. Konnte Fizzlebub uns helfen?", completion = "Großartig! Fizzlebub kam durch! Ich werde daran denken, wenn ich ihn wiedersehe.\n\nUnd habt Dank, &lt;Name&gt;. Ihr macht Eure Sache großartig und wir werden beide eine Menge Geld damit verdienen...", rewards = "Ihr bekommt:\n\n"},
[1120] = {title = "Die Gnome betrunken machen", objective = "Bringt Fools Starkbier zum Gnomen-Boxenboss.", description = "Wir müssen Fools Starkbier an einem aus der Boxencrew ausprobieren. Wenn Ihr es an den Gnomen erproben wollt, hier - nehmt das Starkbier und gebt es dem Gnomen-Boxenboss.\n\nUnd wartet nicht zu lange. Das Starkbier wird mit der Zeit schlecht.", progress = "Hallo! Habt Ihr denn etwas für mich?", completion = "Starkbier? Wie aufmerksam! Danke!\n\nWir sollten nicht trinken, da das Rennen bevorsteht, aber... vielleicht können meine Jungs einen Schluck vertragen. Außerdem kann es ja so stark nicht sein, oder?", rewards = "Ihr bekommt:\n\n"},
[1121] = {title = "Die Goblins betrunken machen", objective = "Bringt Fools Starkbier zum Goblin-Boxenboss.", description = "Wir müssen Fools Starkbier an einem aus der Boxencrew ausprobieren. Wenn Ihr es an den Goblins erproben wollt, hier - nehmt das Starkbier und gebt es dem Goblin-Boxenboss.\n\nUnd wartet nicht zu lange. Das Starkbier wird mit der Zeit schlecht.", progress = "Was glotzt Ihr denn so?", completion = "Was haben wir denn da? Fusel, hm?\n\nAlso mich stört es nicht, wenn wir ein klein wenig...", rewards = "Ihr bekommt:\n\n"},
[1122] = {title = "Meldet Euch bei Fizzlebub", objective = "Bringt den Bericht über Fools Starkbier zu Crank Fizzlebub in Booty Bay.", description = "Fools Starkbier hat astrein gewirkt! Ich habe beim nächsten Rennen gesetzt... hoffen wir, das Team, das Ihr betrunken gemacht habt, hat sein Auto nummeriert!\n\nBleibt nur noch eine Aufgabe für Euch - bringt diese Notiz zu Crank Fizzlebub in Booty Bay. Er wird von dem erfolgreichen Test wissen wollen.\n\nHoffentlich bekommen wir mehr von Fools Starkbier für künftige Rennen!", progress = "Hallo, <Name>. Wie hat das Starkbier gewirkt? Starkes Gesöff, was?", completion = "Hier steht, Fools Starkbier war ein Erfolg. Das sind gute Neuigkeiten!\n\nWenn Ihr mehr von dem Zeug wollt, lasst es mich wissen und Ihr könnt mehr von Zanzils Mixtur sammeln.", rewards = "Ihr bekommt:\n\n"},
[1123] = {title = "Rabine Saturna", objective = "Sprecht mit Rabine Saturna im Dorf Nighthaven in Moonglade. Moonglade liegt zwischen dem Teufelswald und Winterspring, und Ihr erreicht es über den Pfad, der aus der Holzschlundfeste herausführt.", description = "Für diese Aufgabe sucht Majordomus Rabine Saturna für Bewahrer Remulos in Moonglade Unterstützung bei der Erforschung des riesigen Ödlandes weit im Westen von Tanaris und Un'Goro. Er lebt in Nighthaven, dem Hauptort von Moonglade.\n\nVorher möchte ich Euch jedoch noch von der Wichtigkeit Eurer Anwesenheit in Kenntnis setzen. Es gibt zunehmend Spannungen zwischen den Nachtelfen von Darnassus und dem Zirkel des Cenarius in Moonglade. Lasst Euch nicht von völkischer Engstirnigkeit beirren und verlasst Euch auf die Weisheit Eurer Vorfahren, wenn Ihr dort mit dem Zirkel zu tun habt, <Name>. Viel Glück.", progress = nil, completion = "Ich bin Rabine Saturna und heiße Euch im Namen von Bewahrer Remulos und allen Bewohnern dieses hochheiligen Tales aufs Herzlichste willkommen.\n\nIch weiß Euer Interesse und Euren Eifer bei der Unterstützung des Zirkels des Cenarius zu schätzen. Die Tauren haben eine unglaubliche Neigung für die Lehren des Cenarius gezeigt, und als Vertreter der Horde seid Ihr in der Sicherheit dieses Tales willkommen. Die Erhaltung Azeroths ist ein gemeinsames Ziel, das wir beide verfolgen.\n\nIhr seid hier unter Freunden, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[1124] = {title = "Einöde", objective = "Sprecht in der Nähe des Friedhofs Heldenwacht in Silithus mit Layo Starstrike und zeigt ihm Rabines Brief.", description = "Westlich des Un'Goro Kraters entlang des nordwestlichen Grats liegt ein raues Ödland - Silithus. Nur wenige wissen, dass sich hier vor Urzeiten ein Krieg zwischen den Nachtelfen und einer bösartigen, außerirdischen Macht abgespielt hat. Das Böse wurde versiegelt, aber jetzt befürchten wir, dass Kräfte am Werk sind, um diesen... unaussprechlichen Horror wieder zu entfesseln.\n\nSprecht mit Layo Starstrike, einem unserer Agenten in Silithus. Sucht nach ihm in Heldenwacht, der letzten Ruhestätte der Gefallenen des Ödlandes. Gebt Ihm diesen Brief, damit erwerbt Ihr sein Vertrauen.", progress = "Das hier ist ein zu gefährliches Land, um hier so sorglos herumzuwandern, <Klasse>. Was führt Euch in die Ödnis von Silithus?", completion = "Rabine schickt Euch also? Tja, dann betrachtet Euch als willkommen... soweit dieses desolate und verlassene Land jemanden willkommen heißen kann.\n\nDamals, als das große Leiden das Land hier beherrschte, war ich noch nicht geboren, aber es gibt Orte in dieser Wüste, die als unheimliches Anschauungsmaterial dieser vergessenen Zeit dienen könnten. Mit Eurer Hilfe könnte es dem Zirkel des Cenarius gelingen, der Gefahr ein für alle Male ein Ende zu bereiten, einer Gefahr, die angeblich schon vor Generationen ausgerottet sein sollte.", rewards = "Ihr bekommt:\n\n"},
[1125] = {title = "Die Geister vom Südwindposten", objective = "Befreit die Geister von 8 gequälten Druiden und 8 gequälten Schildwachen beim Südwindposten und kehrt dann zu Layo Starstrike auf den Friedhof Heldenwacht in Silithus zurück.", description = "Südwestlich von uns liegt ein tragischer Schauplatz - die Ruinen vom Südwindposten. Dort sollten wir mit unserer Arbeit beginnen, <Name>.\n\nNach allem, was wir wissen, war dieses Dorf einst ein Stützpunkt der Nachtelfen für Operationen in Silithus. In der Zwischenzeit wurde es längst von den Silithidschwärmen überrannt, die die Wüsten durchziehen. Ich vermag mir den Horror kaum vorzustellen, als die Zerstörung des Dorfs begann...\n\nDie gequälten Geister gefallener Druiden und Schildwachen wandern ziellos durch die Ruinen. Erforscht diesen Ort und befreit die Seelen dieser unglücklichen Kreaturen, wo immer es erforderlich ist.", progress = nil, completion = "Ich hatte mir schon gedacht, dass dieser riesige quirlige Schwarmbau nahe den Ruinen des Dorfes irgendetwas mit seinem Untergang zu tun hat. Mir scheint, dass Euer Wirken das bestätigt hat. Die unmittelbare Nähe des Schwarmbaus stellt eine Bedrohung für unsere zukünftige Arbeit hier dar.\n\nIch danke Euch für Eure Güte, die Seelen der Gefallenen zu befreien. Das ist keine leichte Arbeit, ich weiß. Wenn Ihr bereit seid, würde ich Euch jedoch gern noch einmal um Eure Unterstützung bitten ...", rewards = "Ihr bekommt:\n\n"},
[1126] = {title = "Schwarmbau im Turm", objective = "Besteigt den Turm beim Südwindposten und findet eine Möglichkeit, den Schwarmbau der Silithiden aufzuscheuchen. Bringt alles Ungewöhnliche, das Ihr dabei entdeckt, zu Layo Starstrike auf den Friedhof Heldenwacht in Silithus.", description = "Wir müssen uns um den Schwarmbau beim Südwindposten kümmern, und ich glaube, ich weiß auch schon, wie wir an ihn herankommen. Meiner Erfahrung nach reagieren die Schwarmbauten der Silithiden empfindlich auf ihre Umgebung. Das erklärt auch ihre Angriffe, als sie die Todesschreie der Geister hörten.\n\nIm Turm sind die Silithiden am stärksten - dort, wo massenweise Wespen herumschwirren. Besteigt den Turm und scheucht den Schwarmbau auf. Meldet Euch zurück, sobald Ihr etwas erfahren habt, aber seid vorsichtig! Wenn Ihr irgendetwas Hilfreiches entdeckt, bringt es zu mir.", progress = "Na, hat es geklappt? Zumindest seid Ihr noch in einem Stück, und das ist gut. Habt Ihr etwas gefunden?", completion = "Was zum... was ist das?\n\nEs hat die Form eines... Kastens...? Total verkrustet. Wartet, da ist eine freie Stelle... ist das etwa ein Buch unter all diesem Dreck?\n\nIch glaube, Ihr habt da einen außergewöhnlichen Fund gemacht, &lt;Name&gt;... zumindest hoffe ich das. Vielleicht ist das ein Tage- oder Logbuch aus alter Zeit, konserviert in dieser Hülle.\n\nIch glaube, ich weiß wie wir herausfinden können was es ist.", rewards = "Ihr bekommt:\n\n"},
[1127] = {title = "Fools Starkbier", objective = "Bringt 12 von Zanzils Mixturen zu Crank Fizzlebub in Booty Bay.", description = "Ihr möchtet also etwas von Fools Starkbier, hm? Denkt Ihr daran, wieder die Rennen zu besuchen...?\n\nGut, bringt mir mehr von Zanzils Mixtur und ich braue noch etwas mehr Starkbier für Euch.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFools Starkbier"},
[1130] = {title = "Melor schickt Kunde", objective = "Sprecht mit Melor Stonehoof in Thunder Bluff.", description = "<Name>, Melor Stonehoof hat von Euren Taten gehört und Euch einen Weg geebnet.\n\nWenn Ihr ihn einschlagen möchtet, dann geht nach Thunder Bluff und sprecht mit Melor. Ihr findet ihn auf der Anhöhe der Jäger.", progress = nil, completion = "So, &lt;Name&gt;, Ihr seid also gekommen. Seid Ihr denn bereit, eine Reise durch ferne Länder zu beginnen?\n\nWenn ja, &lt;Klasse&gt;, dann hört zu...", rewards = nil},
[1131] = {title = "Stahlbiss", objective = "Bringt Stahlbiss' Rippe zu Melor Stonehoof in Thunder Bluff.", description = "Manchmal jagen wir wegen Essen. Manchmal jagen wir wegen der Ehre. Und manchmal jagen wir, um der Lehren der Erdenmutter teilhaftig zu werden.\n\nDoch die Jagd, auf die ich Euch jetzt schicke, hat damit nichts zu tun. Es geht darum, eine Kreatur zu töten, die nicht unter dem Segen der Erdenmutter steht.\n\nDie Hyäne Stahlbiss streift südlich des Brachlandes durch Tausend Nadeln. Sie ist eine Tyrannin, die andere Hyänen anlockt und Furcht und Blutvergießen unter den friedlicheren Wildtieren verbreitet.\n\nSucht Stahlbiss, <Name>. Sucht und besiegt sie.", progress = "Habt Ihr die elende Stahlbiss besiegt, <Name>?", completion = "Durch den Sieg über Stahlbiss habt Ihr Tausend Nadeln von einer schrecklichen Besudelung gesäubert.\n\nUnd das, &lt;Name&gt;, ist Eure Lektion für den heutigen Tag.", rewards = "Ihr bekommt:\n\n"},
[1132] = {title = "Fiora Longears", objective = "Sprecht mit Fiora Longears in Theramore.", description = "Ach, wieder auf See zu sein! Den Kuss des Windes zu spüren und mich von den Wellen wiegen zu lassen wie vor langer Zeit von meiner gesegneten Mutter!\n\nOh, hätte ich doch nur Euer Glück, <Klasse>, denn ich sehe das Meer in Eurer Zukunft!\n\nMeine Aufgabe ist es, eifrige Seelen nach Kalimdor zu bringen, in das Land der unbegrenzten Möglichkeiten! Wenn Ihr Euer Glück in Übersee machen wollt, dann reist von hier mit dem Schiff in den wunderschönen Hafen Theramore. Sprecht mit meiner Partnerin, der Elfin Fiora Longears.\n\nSie wird Euer Abenteuer in Kalimdor beginnen lassen!", progress = nil, completion = "Guten Tag auch! Mr. Flint im Hafen von Menethil hat Euch geschickt? Mr. Flint besitzt eine gute Charakterkenntnis. Wenn er Euch hergeschickt hat, dann gehört Ihr zweifellos nach Kalimdor!", rewards = "Ihr bekommt:\n\n"},
[1133] = {title = "Reise nach Astranaar", objective = "Sprecht mit Shindrell Swiftfire in Astranaar.", description = "Wenn Ihr gerade vom Boot von Menethil kommt, dann solltet Ihr als Erstes nach... Astranaar gehen. Ich bin sicher, ein eifriges Mitglied der Allianz kann dort viel Gutes tun. Sprecht mit Shindrell Swiftfire und bietet Eure Dienste an.\n\nAber erwähnt nicht, wer Euch geschickt hat. Shindrell kennt mich nicht...", progress = nil, completion = "Seid Ihr hier, um der Allianz Eure Dienste anzubieten, &lt;Name&gt;? Wir sind dankbar für die Unterstützung, denn wiewohl seine Schönheit ungebrochen ist... ist Ashenvale nicht mehr so friedlich wie einst.", rewards = nil},
[1134] = {title = "Prachtschwingen des Steinkrallengebirges", objective = "Bringt 12 Prachtschwingengiftbeutel zu Shindrell Swiftfire in Astranaar.", description = "Wir führen keinen offenen Krieg mit der Horde, aber der Frieden ist brüchig. Ihre Agenten gehen häufig gegen uns vor, aber stets heimlich.\n\nEiner dieser Feldzüge wurde uns durch geheime Informanten in Theramore enthüllt, die behaupten, dass die Orcs Gift der Prachtschwingen beim Mirkfallonsee im Steinkrallengebirge im Süden sammeln. Dann benutzen Orc-Auftragsmörder das Gift bei ihren geheimen Feldzügen gegen die Allianz!\n\nWenn das stimmt, dann müssen wir sie aufhalten, <Name>. Wir müssen ihnen den Zugang zu dem Gift versperren.", progress = "Habt Ihr die Prachtschwingengiftbeutel, <Name>. Wir dürfen nicht zulassen, dass die Orcs die Gifte der Bestien gegen uns verwenden!", completion = "Danke, &lt;Name&gt;. Es stimmt mich traurig, Kreaturen abschlachten zu lassen, die unsere Feinde nicht freiwillig unterstützen, und doch ist es meine Pflicht.\n\nEuer Herz mag um die Prachtschwingen trauern, die Ihr abschlachten musstet, aber es dürfte Euch mit Freude erfüllen, dass Eure Verbündeten jetzt vor dem Gift der Prachtschwingen sicher sind.", rewards = "Ihr bekommt:\n\n"},
[1135] = {title = "Steilhanggift", objective = "Bringt 10 Steilhanggiftbeutel zu Fiora Longears in Theramore.", description = "Wie Ihr sicher wisst, werden Flügeldrachen oft von Orcs als Reittiere gezähmt. Weniger bekannt indessen ist, dass das Gift eines Flügeldrachen in manchen Kreisen höher geschätzt wird als die Bestie selbst. Falls Ihr also keine Angst vor einer kleinen Flügeldrachenjagd habt... habe ich einen Job für Euch.\n\nEs gibt einen Ort im Land Tausend Nadeln, er liegt westlich von hier, welcher als der Steilhang bekannt ist. Die dort lebenden Steilhangflügeldrachen haben ein starkes Gift. Stark und kostbar.", progress = "Habt Ihr den Steilhang gefunden, <Name>? Und Glück bei den Flügeldrachen dort gehabt?", completion = "Ah, die meisten platzen förmlich vor Gift, &lt;Name&gt;. Man findet sie normalerweise nur bei jungen Flügeldrachen oder fruchtbaren Weibchen. Das muss ein Gemetzel oben am Steilhang gewesen sein!", rewards = "Ihr bekommt:\n\nWindgetragener Gürtel"},
[1136] = {title = "Frostrachen", objective = "Bringt Frostrachens Mähne zu Melor Stonehoof in Thunder Bluff.", description = "<Name>, jetzt ist es Zeit, weit entfernte Länder zu bereisen. Ihr seid bereit.\n\nIhr jagt jetzt Frostrachen, einen Yeti im Alteracgebirge. Er ist schwer zu erkennen, da sein weißes Fell mit den Schneefeldern seiner Bergheimat verschmilzt. Man bekommt ihn kaum je zu sehen.\n\nAber ich zeige Euch, wie man eines solchen Geschöpfes habhaft wird. Hier, nehmt diese Rolle. Ich habe darauf vermerkt, wie man Frostrachen anlocken kann.\n\nGeht jetzt, <Name>. Eure Reise ist lang und viele Herausforderungen harren Eurer. Erst wenn Ihr mit Frostrachens Mähne zurückkehrt, ist Eure Aufgabe abgeschlossen.", progress = "Seid Ihr im Alteracgebirge gewesen, <Name>? Habt Ihr den scheuen Frostrachen gefunden?", completion = "Kraft und List waren erforderlich, um Frostrachen zu besiegen, &lt;Name&gt;.\n\nEuer Weg führte Euch zu den Tälern von Tausend Nadeln und den hohen Bergen von Alterac. Eines Tages wird er Euch durch alle Länder der Erdenmutter führen, denn das ist das Leben des Jägers.", rewards = "Ihr bekommt:\n\nGeistjägerkopfputz"},
[1137] = {title = "Neuigkeiten für Fizzle", objective = "Sprecht mit Fizzle Brassbolts in der schimmernden Ebene.", description = "Indurium besitzt einen erstaunlichen Hitzewiderstand! Ich bin sicher, es taugt für Fizzles Kolben. Aber er braucht echtes Indurium, nicht nur die Späne.\n\nDas Erz muss tief in den Minen von Uldaman abgebaut werden, an der Nordgrenze des Ödlandes. Das ist die wahre Quelle von Indurium.\n\nBestellt Fizzle Brassbolts Grüße von mir und sagt ihm, was ich Euch gesagt habe.\n\nAngenehme Reise, <Name>. Ich wäre nicht überrascht, wenn wir uns wiedersehen - wenn Fizzle von dem Indurium erfährt, schickt er Euch wahrscheinlich nach Uldaman, um es zu holen!", progress = nil, completion = "&lt;Name&gt;, Ihr seid zurück! Habt Ihr Martek gefunden? Ihr habt mit ihm gesprochen? Was hat er gesagt? Kann er helfen???\n\nSagt es mir, sagt es mir, sagt es mir!!!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFizzles Zippy-AnzünderGnomen-Mechanikerhandschuhe\n\nIhr bekommt außerdem:\n\n"},
[1138] = {title = "Meeresfrüchte", objective = "Sammelt 6 feine Krebsbrocken für Gubber Blump in Auberdine.", description = "Ich liebe Krebse. Krebse sind die Früchte des Meeres! Man kann sie backen, grillen, kochen und braten. Man kann sie in der Pfanne braten, frittieren und kurzbraten. Es gibt Krebssalat, Krebssuppe, Krebseintopf, Pfefferkrebs, Zitronenkrebs, Peitscherwurzelkrebs und Ironforgekrebs à la Surprise. Das ... das war's eigentlich.\n\nIch angle hier gerade und daher kann ich mir keine feinen Krebsbrocken besorgen. Mann kann sie aus Riffkriechern und verkrusteten Gezeitenkriechern kratzen. Man kann viel mit ihnen anstellen. Man kann sie backen, grillen, kochen ...", progress = "... Zitronenkrebs, Peitscherwurzelkrebs und Ironforgekrebs à la Surprise. Das war's eigentlich.\n\nOh, hallo, <Name>. Habt Ihr die feinen Krebsbrocken, von denen ich Euch erzählte?", completion = "Prima, diese feinen Krebsbrocken sind genau, was ich brauche. Danke, &lt;Name&gt;! Ich habe das hier gefunden, als ich vor einiger Zeit geangelt habe, und ich habe keine Verwendung dafür. Vielleicht könnt Ihr etwas damit anfangen. Man kann damit allerdings ganz sicher keine guten Krebsgerichte machen.\n\nIch habe Euch doch alles über Krebse berichtet, oder?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchäl-HandschuheKrustentier-Stiefel\n\nIhr bekommt außerdem:\n\n"},
[1139] = {title = "Die verlorene Tafel des Willens", objective = "Sucht die Tafel des Willens und bringt sie zu Berater Belgrum in Ironforge.", description = "Wir haben den Schattenschmiedeklan ausgebremst, indem wir ihn von der Blackrockspitze abgeschnitten haben, doch Hammertoes Mission wurde noch nicht erfüllt. Sein Tod darf nicht umsonst gewesen sein. Er träumte davon, die Schrifttafel des Willens zu finden: eine Steintafel, graviert mit Magie durch die Titanen selbst, die helfen, ihren Schöpfungen Leben einzuhauchen und ihnen damit einen eigenen Willen ermöglichen. So jedenfalls heißt es in den Legenden.\n\nDennoch müssen wir die Tafel bergen, ehe der Schattenschmiedeklan sie finden kann.\n\nKehrt nach Uldaman zurück, sucht die Tafel und kommt unverzüglich wieder her.", progress = "Hammertoes Auftrag muss aktualisiert werden, <Name>. Das schulde ich ihm.\n\nNicht nur deswegen ist es zwingend, dass Ihr nach Uldaman zurückkehrt, sondern auch für die Sicherheit aller Zwerge. Wenn die Tafel den Dunkeleisenzwergen in die Hände fällt, kann niemand sagen, wie mächtig ihre Golemarmee werden könnte.", completion = "&lt;Berater Belgrum schüttelt ungläubig den Kopf, als Ihr ihm den Steinsplitter gebt.&gt;\n\n&lt;Name&gt;, das ist erstaunlich. Ich muss das schnellstens zu den Magiern des Königs bringen lassen. Sie werden das Teil studieren und herausfinden, ob die Legenden wahr sind. Doch das soll ein andermal diskutiert werden. Ihr habt unserem Volk mehr geholfen, als ich für möglich hielt - danke.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nMedaille des Mutes"},
[1140] = {title = "Der Turm von Althalaxx", objective = "Befreit die Hochgeborenenseelen in Night Run und Satyrnaar und kehrt zu Delgren dem Läuterer in Maestras Posten zurück.", description = "Díe Schrift der Orcs ist kaum mehr als das Gekritzel eines Kindes. Viele meines Ordens spotteten, als ich ihre Sprache lernen wollte, aber ich fand es hilfreich, meine Feinde besser zu verstehen.\n\nIlkruds Gekritzel zufolge scheint Athrikus immer noch zwei Seelenedelsteine zu besitzen, und die werden in Nightrun und Satyrnaar aufbewahrt, Satyrgebiete im nordöstlichen Ashenvale.\n\nSeid vorsichtig da draußen, <Name>, die bluttriefenden Tempel der Satyrn können selbst für abgebrühte <Klasse> wie Euch beängstigend sein.", progress = nil, completion = "Vielleicht hat man die Satyrn schon viel zu lange im Wald geduldet. Ich spreche mit Elissa darüber, wenn ich wieder nach Auberdine reise.\n\nWie auch immer, nachdem die Seelenedelsteine zerstört sind, dürfte Athrikus' Macht sichtlich geschwunden sein. Wir müssen die Gelegenheit nutzen, ihn und seinen Kult auszurotten.", rewards = "Ihr bekommt:\n\n"},
[1141] = {title = "Die Familie und die Angel", objective = "Fangt 6 Dunkelküstenbarsche für Gubber Blump in Auberdine.", description = "Ich liebe das Angeln. Die Blump-Familie ist berühmt fürs Angeln. Mein Name ist Gubber Blump; ich angle.\n\nEs gibt eine Fischart, die ich hier in der Gegend gern fange. Sie heißt Dunkelküstenbarsch. Früher fuhr ich mit einem Boot hinaus, um Barsche zu angeln, aber seitdem die gemeinen Murlocs gekommen sind, fahren keine Boote mehr raus. Ich wette, dass sie auch alle Barsche aufgefressen haben.\n\nSagt, wollt Ihr mir helfen, Dunkelküstenbarsche zu fangen? Ich würde Euch eine echte Blump-Familienangel geben, wenn Ihr es tun würdet! Es ist eine wirklich gute Angel, um damit Fische zu fangen.", progress = "Es gibt sehr viele gute Gerichte, für die man Dunkelküstenbarsche braucht. Man kann sie prima essen, aber ich finde, es macht noch mehr Spaß, sie zu fangen.\n\nHabt Ihr schon ein paar Dunkelküstenbarsche gefangen?", completion = "Das sind echt schöne Zackenbarsche, &lt;Name&gt;! Danke, dass Ihr mir geholfen habt!\n\nIhr könnt mindestens so gut angeln wie meine Cousine Graun Blump. Sie hat auch einen Bart und sie riecht etwas merkwürdig, aber das hält sie nicht vom Angeln ab. Tja, ich denke, Ihr könnt auch eine Blump-Familienangel benutzen.", rewards = "Ihr bekommt:\n\nAngel der Familie Blump"},
[1142] = {title = "Die Sterblichkeit schwindet", objective = "Sucht und bringt Treshalas Anhänger zu Treshala Fallowbrook in Darnassus.", description = "Ich habe nicht mehr lange zu leben... so... so... schwach.\n\n... der t-t-tapfere Zwerg Lonebrow hat jemanden geschickt, Falfindel zu w-w-warnen...\n\nAber bevor ich... s-s-sterbe...\n\n... meine Frau Treshala... ihr Anhänger des Bundes mit mir... gestohlen... von einem der n-n-niederträchtigen Angreifer...\n\nB-B-Bitte sucht ihn... und bringt ihn Treshala in Darnassus zurück...\n\n... mit der Nachricht meines einsamen... Todes.", progress = "Was führt Euch in mein Haus, <Volk>?", completion = "Nein!\n\nDas ist nicht fair. Oh grausame, unerträgliche Welt!\n\nJetzt muss ich diese Last des Kummers tragen und darf Heralaths Werk nicht mit ihm sterben lassen.\n\nEs war tapfer von Euch, von so einem gefährlichen Ort anzureisen, &lt;Name&gt;. Doch bitte lasst mich jetzt allein.\n\nIch will in Abgeschiedenheit trauern.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTrauerschalLanzer-Stiefel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1143] = {title = "Der Turm von Althalaxx", objective = "Tötet Athrikus Narassin und bringt seinen Kopf zu Balthule Shadowstrike nahe des Turms von Althalaxx.", description = "Verstehe. Also wenn das stimmt, was Ihr sagt, dann ist jetzt die Zeit gekommen, endlich zuzuschlagen. Ich glaube, Athrikus residiert in der Turmspitze. Aber seid vorsichtig, er ist von vielen mächtigen Hexenmeistern umgeben, die tödlicher sind als Eure bisherigen Gegner.", progress = "Athrikus Narassin ist ein alter und mächtiger Hexenmeister. Vielleicht sollten wir auf Delgrens Unterstützung warten, aber offenbar setzt er großes Vertrauen in Euch, wenn er Euch allein schickt.", completion = "Ich hoffe, nach dem Tod von Athrikus werden die dämonischen Kräfte in dieser Gegend zurückgedrängt. Ich zweifle nicht, dass sie sich neu formieren und zurückkehren, aber bis dahin werden wir auf die Bedrohung vorbereitet sein.", rewards = "Ihr bekommt:\n\n"},
[1144] = {title = "Willix der Importeur", objective = "Führt Willix den Importeur aus dem Kral von Razorfen hinaus.", description = "Endlich ist Hilfe eingetroffen!\n\nIhr habt keine Ahnung, wie lang ich hier gefangen gehalten wurde. Ich kann mich nicht erinnern, wann ich zum letzten Mal draußen war.\n\nWisst Ihr, ich bin Unternehmer. Immer am abkupfern, wie man so sagt. Ich habe Wind davon bekommen, dass Mebok Mizzyrix gut für Rotlaubknolle aus diesem Schweinepferch hier bezahlt. Ich dachte mir, das würde ein leichtes Spiel werden. Wie Ihr sehen könnt, habe ich mich geirrt!\n\nWie auch immer, wenn Ihr so freundlich wärt, mir hier raus zu helfen, sollte es Euer Schaden nicht sein.", progress = nil, completion = "Nochmals danke, Freund! Ich sagte doch, es würde sich für Euch lohnen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAffenringNatternreifenTigerband\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1145] = {title = "Der Schwarm wächst", objective = "Stellt Korrans versiegelte NotizBelgrom Rockmaul in Orgrimmar zu.", description = "Viele Reisende, die durch Crossroads kamen, halfen mir, Eier vom Feld der Riesen zu sammeln, und viele können Geschichten erzählen, wie tödlich diese Kreaturen sind. Ich habe genug gehört, um diese Insekten als größere Bedrohung einzustufen als meine Meister zuerst dachten.\n\nIch brauche einen Kurier, der nach Orgrimmar reist und sich mit Belgrom Rockmaul trifft. Das dürfte keine Kleinigkeit werden und es sollte nur jemand gehen, der die Aufgabe ernst nimmt.\n\nBelgrom ist für gewöhnlich vor der Halle der Kriegerhelden zu finden.", progress = "Ich beneide Euch, <Klasse>. Ihr seht wie jemand aus, der eine Weile außerhalb der Mauern von Orgrimmar gewesen ist.\n\nIch würde selbst im Namen des Kriegshäuptlings reisen, wenn Thrall nicht hier in der Stadt meiner Fertigkeiten bedürfte. Doch er ist uns ein guter Anführer und ich vertraue seinem Urteil. Ich bleibe hier, solange er mich braucht.", completion = "Ah, eine Notiz von Korran. Er ist schon seit langer Zeit ein treuer Diener. Ich fragte mich schon, wie es um seine Pflichten in Crossroads bestellt ist.", rewards = "Ihr bekommt:\n\n"},
[1146] = {title = "Der Schwarm wächst", objective = "Stellt Belgroms versiegelte NotizMoktar Krin in Tausend Nadeln zu.", description = "Korran ist also zu einer ähnlichen Schlussfolgerung hinsichtlich dieser Insekten gekommen - sie scheinen doch eine größere Bedrohung zu sein, als wir dachten.\n\nVor ein paar Tagen kehrte ein Jäger halbtot aus Tausend Nadeln zurück. Er gehörte zu einem Stoßtrupp, der geschickt wurde, um ein Ausgrabungsteam der Zwerge von der schimmernden Ebene zu verjagen. Während des Angriffs kamen noch mehr von diesen Insekten aus einer Höhle an der Grabungsstätte und hätten die Gruppe fast getötet.\n\nIhr Anführer war Moktar Krin und sie suchten Zuflucht an der Grenze der schimmernden Ebene. Bringt ihm diese Notiz.", progress = "Mich und meine Gruppe führt der Krieg zur schimmernden Ebene, <Klasse>. Was führt Euch her?", completion = "Stört Euch nicht an den hallenden Echos von den Bergwänden. Die Goblins und Gnome sind draußen in der Ebene und rasen in Abscheulichkeiten der, wie sie es nennen, 'Wissenschaft' herum. Es gibt größere Bedrohungen hier in Tausend Nadeln, und eine davon tötete mehr als die Hälfte meiner Gruppe.\n\nAber wir bleiben hier, bis wir von Belgrom in Orgrimmar gehört haben. Bis dahin halten wir unsere Position hier und bleiben wachsam.", rewards = "Ihr bekommt:\n\n"},
[1147] = {title = "Der Schwarm wächst", objective = "Tötet 5 Silithidsucher, 5 Silithidschwarmdrohnen sowie 5 Silithideindringlinge und kehrt zu Moktar Krin in Tausend Nadeln zurück.", description = "Hmm. Offenkundig hält Belgrom die Monster für eine Bedrohung. Er möchte sie in die Tiefen zurückgedrängt haben, aus denen sie gekommen sind.\n\nDie Zwerge zu töten, die von der Forscherliga geschickt wurden, genügte wohl nicht - jetzt muss ich eine Gruppe halbtoter Krieger in einen neuen Kampf führen. Aber selbst können wir das nicht; nicht unter diesen Bedingungen. Die Grabungsstätte liegt südlich von hier. Es sollten keine Zwerge mehr in der Gegend sein. Habt Ihr Lust, Klinge oder Stab in die Hand zu nehmen und uns zu unterstützen?", progress = nil, completion = "Ha! Dieses Sekret, das Euch bedeckt, macht Euch nur hübscher, &lt;Name&gt;! Leider hat es Euren Geruch nicht eben verbessert. Geht nicht zu nahe zu den Kodos; Ihr löst entweder eine Stampede aus oder macht sie lüstern.\n\nIch glaube, meine Gefährten würden zustimmen, dass Euer Geruch allein beweist, welche Hilfe Ihr uns gegen diese Insektenkreaturen wart. Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[1148] = {title = "Teile des Schwarms", objective = "Bringt 1 Silithidenherz, 5 Silithidenkrallen und 3 intakte Silithidenknochenpanzer zu Korran in Crossroads.", description = "Ihr untersucht den Knochenpanzer gründlich. Als Ihr ihn in den Händen dreht, stellt Ihr fest, dass die Chitinplatten derart verflochten sind, dass er dadurch unglaublich hart wird. So etwas habt Ihr noch nie gesehen. Ihr untersucht den Rest des Kadavers und kommt zu dem Schluss, dass diese Kreaturen sehr kräftig und hochentwickelt sind.\n\nAls ihr einen weiteren Blick auf den Knochenpanzer werft, wird Euch klar, dass Korran diese Kreaturen gewiss gern studieren würde. Er könnte dadurch herausfinden, was diese Kreaturen sind und woher sie kommen.", progress = "Ah, es ist lange her, seit Ihr mich besucht habt, <Name>. Was kann ich heute für Euch tun? Ihr seht aus, als hättet Ihr jüngst das Antlitz des Krieges geschaut. Gut... gut für die Horde und gut für Euch. Je mehr Kämpfe Ihr gesehen habt, desto hilfreicher seid Ihr; und stärker.", completion = "Habt Ihr Moktar neuerdings gesehen? Er ist ständig auf der Suche nach mir. Zu meinem Bedauern muss ich hören, dass er lieber über seine kleine Kriegerschar wacht, als in den Kampf zu ziehen, aber ich bin sicher, es würde ihm gefallen, Mitglieder der Forscherliga zu töten.\n\nEs war klug, mir diese Proben zu bringen, &lt;Name&gt;. Zusammen mit den Eiern vom Feld der Riesen sollte ich herausbekommen können, was diese Insekten sind und was sie vorhaben könnten.", rewards = "Ihr bekommt:\n\n"},
[1149] = {title = "Test des Glaubens", objective = "Wenn Ihr festen Glaubens seid, dann springt von den Planken über Tausend Nadeln.", description = "Ihr habt mich also gesucht, oder führt Euch das Schicksal zu mir? Einerlei. Ihr seid jetzt hier, und so wird Eure Reise erneut beginnen.\n\nDas Sein besteht aus vielen Aspekten: Geist, Körper, Verstand. Einige davon kann man anhand der Traditionen einer Kultur bewerten. Von anderen können wir nur hoffen, dass sie in uns selbst existieren. Wenn Ihr einverstanden seid, möchte ich einige der Aspekte in Euch testen.\n\nWenn Ihr besteht, werdet Ihr stärker werden. Wenn Ihr scheitert, werdet Ihr die Weite des Nether begreifen.\n\nAls Erstes ein Test des Glaubens.", progress = "Glauben. Er ist wichtiger als vielen bewusst ist.\n\nManchmal ist es gar nicht wichtig, was man glaubt. Es ist nur wichtig, dass man überhaupt an etwas glaubt.", completion = "Erst wenn wir unvorhergesehenen Widersachern gegenüberstehen, begreifen wir, wie stark unser Geist ist. Ihr habt den Sprung des Glaubens gewagt, obwohl Ihr keine Garantie hattet, dass Ihr überleben würdet. Euer Verstand ist offen und Euer Geist bereit für das, was kommen wird.\n\nWenn Ihr bereit seid, wartet der nächste Test auf Euch.", rewards = "Ihr bekommt:\n\n"},
[1150] = {title = "Test der Belastbarkeit", objective = "Bringt Grenkas Klaue zu Dorn Plainstalker in Tausend Nadeln.", description = "Ich sehe mit Freuden, dass Euer Mut im Lichte Eurer bisherigen Taten unerschütterlich bleibt. Da Euer Glaube stark ist, wird es Zeit, Euren Körper zu testen.\n\nAls Erstes ein Test der Belastbarkeit. Geht mit Freunden zum Bau der Wildfedern westlich vom Freiwindposten. Steigt in die Tiefen ihres Unterschlupfes hinab und zerstört ihre Nahrungsvorräte. Damit solltet Ihr deren Zorn angestachelt haben. Wenn Ihr lange genug überlebt, wird Grenka Blutkreischer Euch persönlich heimsuchen. Tötet sie und bringt mir ihre Klaue, um den Test abzuschließen.", progress = "Ihr müsst spirituell, körperlich und geistig auf die Herausforderungen vorbereitet sein, die vor Euch liegen.\n\nZu oft stürmen wir los, ehe wir bereit sind. Ich betrachte es als meine Pflicht gegenüber der Jugend, ganz gleich welchen Stammes, sie auf die Gefahren vorzubereiten, denen sie sich gegenübersehen könnten, wenn sie ihr Haus verlassen haben.", completion = "Grenka war selbst nach &lt;Volk&gt;-Standards mächtig. Ihr solltet stolz auf Eure heutige Leistung sein.\n\nBeim Test des Glaubens hast du die Kraft des Geistes gezeigt, und jetzt auch Belastbarkeit im Kampf gegen die Harpyien der Wildfedern, doch die Zeit ist reif für einen neuen Test.", rewards = "Ihr bekommt:\n\n"},
[1151] = {title = "Test der Kraft", objective = "Bringt Fragmente von Rok'Alim zu Dorn Plainstalker in Tausend Nadeln.", description = "Zu Zeiten der Alten Götter bewohnten Elementare einen Großteil dieser Welt. Sie beteten die Alten Götter an, und die Götter fesselten die Elementare durch ihre Macht an diese Welt. Als die Alten Götter verbannt wurden, verblassten die Elementare in unserer Welt und kehren jetzt auf Geheiß mächtiger Magier zurück.\n\nAber es gibt Ausnahmen. Einige Elementar waren mächtig genug, aus eigenen Stücken hier zu bleiben. Solch ein Elementar ist Rok'Alim.\n\nSucht Rok'Alim in Tausend Nadeln und tötet ihn, um Eure Kraft zu beweisen.", progress = "Von den Zentaurenstämmen in Tausend Nadeln wird Rok'Alim auch der Trommler genannt, weil er auf alle Kreaturen, die tapfer oder dumm genug sind, sich ihm in den Weg zu stellen, mit den Fäusten eintrommelt.", completion = "Euer Test der Kraft ist beendet. Ihr habt Kraft und Tapferkeit gezeigt und seid jetzt bereit für den letzten Test, bevor diese Rituale abgeschlossen sind.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1152] = {title = "Test der Lehre", objective = "Sucht Braug Dimspirit in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge.", description = "Eure Zeit bei mir neigt sich dem Ende zu. Ich bin wissend, aber den Test der Lehre kann ich Euch nicht stellen. Es gilt, Lektionen zu erlernen und Orte zu besuchen, die in der Zuständigkeit anderer liegen.\n\nWenn Ihr bereit seid, dann sucht Braug Dimspirit auf - er ist ein höchst weiser Schamane. Er wird Euch weiter testen, also achtet auf seine Worte, <Name>.\n\nWenn Ihr bereit seid, dann sucht den Tunnel, der das Steinkrallengebirge mit Ashenvale verbindet. Dort in der Nähe lebt Braug. Und seid vorsichtig, <Name>, die Nachtelfen versuchen vielleicht, Euren Test zu behindern.", progress = nil, completion = "Die Tage und Nächte allerorten auf der Welt werden kälter, da die Goblins das Land vergewaltigen, und die Nachtelfen zeigen mit den Fingern auf die jüngeren Völker. Die Verlassenen und die Orcs sind nicht die Einzigen, die man für die Härten in Kalimdor und Lordaeron verantwortlich machen kann. Viele der intelligenten Völker haben zum Schmerz der Welt beigetragen. Dorn weiß das und hat Euch zu mir geschickt, weil Ihr die erforderlichen Attribute besitzt, das auch zu erkennen.\n\nJetzt steht Ihr vor Braug.", rewards = "Ihr bekommt:\n\n"},
[1153] = {title = "Eine neue Erzprobe", objective = "Sucht eine unbearbeitete Erzprobe bei einem Buddler oder Feldmesser der Bruchschnauzen und bringt sie zu Tatternack Steelforge im Camp Taurajo im Brachland.", description = "<Klasse>, Ihr habt mir auch früher schon geholfen. Der Kriegshäuptling ist mit meinen bisherigen Leistungen zufrieden und bittet mich, mit neuer Entschlossenheit fortzufahren. Meine Ehre gebietet, dass ich den Kriegshäuptling wissen lasse, was Ihr alles vollbracht habt, doch zuvor möchte ich Euch abermals um Hilfe bitten.\n\nJüngst kamen Reisende aus dem Süden von einem Ort namens Tausend Nadeln. Dort töteten sie einen Kobold, der eine außergewöhnliche Erzprobe bei sich hatte, wollten sie aber nicht verkaufen. Ich möchte eine Probe dieses Erzes untersuchen.", progress = "Ich sah jene Reisenden wieder, die mir keine Erzprobe verkaufen wollten. Ich spuckte sie an, weil sie dem Kriegshäuptling nicht halfen.\n\nMögen sie im Kampf wie Feiglinge sterben und nicht wie Krieger, wie es das Recht aller Völker sein sollte, die sich mit der Horde verbünden.", completion = "Gute Probe, &lt;Name&gt;. Wirklich eine gute Probe.\n\nDiese Reisenden können mich nach Eurer erfolgreichen Rückkehr nicht mehr wegen diesem Erz verspotten.\n\nIch werde mich sofort an die Arbeit machen. Wenn das Material stark genug ist, werde ich dem Kriegshäuptling eine daraus gefertigte Waffe schicken, um ihm unsere Erfolge zu zeigen.\n\nIch werde Eure Hilfe nicht vergessen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\nOrc-Kriegsschwert"},
[1154] = {title = "Test der Lehre", objective = "Sucht das 'Vermächtnis der Aspekte' und bringt es zu Braug Dimspirit in der Nähe des Eingangs zum Steinkrallenpfad im Steinkrallengebirge zurück.", description = "Ihr habt Dorns Tests bestanden und wollt jetzt Eure nächste Prüfung absolvieren. Sehr gut. Bisher sind alle Eure Herausforderungen kindisch gewesen. Es ist leicht, Euren Körper zu testen - bei Eurem Verstand sieht das schon anders aus.\n\nIch werde es mit einfachen Worten erklären: sucht das Buch, das ich Euch nenne, lest es und beantwortet meine Fragen nach seinem Inhalt.\n\nWas für ein Buch, werdet Ihr fragen? Das 'Vermächtnis der Aspekte'. Man findet es in den Tiefen des Dor'danil-Grabhügels im südlichen Ashenvale, wo es von den toten Druiden und deren Tötern bewacht wird.", progress = "Bringt mir das Buch, wenn Ihr es gelesen habt. Ich werde Euch erst Fragen stellen, wenn Ihr mir das Buch gegeben habt.", completion = "Das ist das Buch, das ich nannte. Dann besteht die Hoffnung, dass Ihr meine Fragen korrekt beantwortet... wenn Ihr nicht vergessen habt, es zu lesen.\n\nSprecht wieder mit mir, wenn Ihr bereit seid, dann stelle ich Euch eine Frage.", rewards = "Ihr bekommt:\n\n"},
[1159] = {title = "Test der Lehre", objective = "Sucht Parqual Fintallas in Undercity.", description = "Gut gemacht, <Name>. Ihr habt den ersten Teil des Tests der Lehren bestanden, aber es bleibt noch eine Frage zu beantworten. Aber es ist nicht an mir, diese Frage zu stellen.\n\nBesucht Parqual Fintallas in Lordaeron. Er war ein bedeutender Historiker der Menschen, bevor die Seuche ihn erwischte. Jetzt sucht er immer noch Erleuchtung, freilich einer ganz anderen Art.\n\nEr wird eine weitere Forderung an Euch stellen, bevor er Euch etwas fragt, aber Ihr habt Euch bisher meisterhaft geschlagen - ich bin sicher, Ihr werdet dieses Hindernis überwinden.", progress = nil, completion = "Braug schickt Euch? Unmöglich.\n\n&lt;Parqual schaut auf und ab.&gt;\n\nDor'Danil gemeistert, einen Sprung des Glaubens gewagt, einen mächtigen Elementar bekämpft und überwältigt? Pah! Ihr seid vermutlich ein Lügner; ein Abenteurer, der Gerede in einer Taverne mitgehört hat. Und jetzt glaubt Ihr, Ihr könnt meinen Test bestehen. So sei es denn ... &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"},
[1160] = {title = "Test der Lehre", objective = "Sucht Die Anfänge der Bedrohung durch die Untoten und bringt es zu Parqual Fintallas in Undercity.", description = "Ich sage Euch, was Ihr suchen müsst und werde Euch sogar meine Frage stellen, aber nicht, weil Ihr Euch beweisen wollt. Wissen ist weit wichtiger als Kraft. Auch wenn andere Euch in ihren Fähigkeiten überlegen sein mögen, Euer Wissen über die Welt ist wertvoller.\n\nGeht zu dem Kloster im Norden Tirisfals. In der dortigen Bibliothek steht ein Buch mit dem Titel Die Anfänge der Bedrohung durch die Untoten. Es wurde von den jetzt verderbten Paladinen benutzt, um sie in meiner Art des Kampfes auszubilden.\n\nBringt es mir.", progress = "Ich hoffe, Ihr habt den Scharlachroten Kreuzzug ordentlich leiden lassen, bevor Ihr das Buch gestohlen habt.\n\nMeine Ansichten über ihre Art sind nicht unumstritten. Die Kreuzzügler mögen einst Anhänger des Lichtes gewesen sein, aber jetzt möchten sie alle Kreaturen vernichten, die sich nicht ihrer Religion angeschlossen haben. Sie glauben, dass alle Untoten, Verlassene und andere, gesäubert werden müssen und die, die durch ihre Länder reisen, entweder irrsinnig oder Opfer der starken Magie der Untoten sein müssen. Idioten. Idioten und Narren, allesamt.", completion = "Das ist das Buch, das ich Euch suchen schickte.\n\n&lt;Parqual streicht langsam und zärtlich mit der Hand über das Buch, während er es betrachtet.&gt;\n\nJetzt wünscht Ihr also eine Frage, um zu beweisen, dass Euer Verstand so mächtig ist wie Euer Körper und Geist. Wenn Ihr das Buch lange genug studiert habt, dann stelle ich Euch die Frage und Ihr könnt diese Tests abschließen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1164] = {title = "Von Dieben stehlen", objective = "Bringt Kenata, Fardel und Marcel Dabyries Köpfe zu Genavie Callow in Undercity.", description = "Die Hure! Das Flittchen! Kenata lebt noch; ihre Familie blüht und gedeiht, während ich leide. Verlassene, wahrhaftig!\n\nMeine Familie wurde Opfer der Seuche. Unser Besitz ebenfalls dahin, während des Kriegs geplündert und niedergebrannt. Und nach alledem haben sie und ihre lausigen Kinder die Stirn, das einzig Kostbare zu stehlen, das ich noch hatte.\n\nMir sind die Sachen, die sie gestohlen haben, längst einerlei. Ich möchte ihre Köpfe!\n\nTötet sie für mich! Geht zum Bauernhof der Dabyries in Arathi, nordöstlich der Zuflucht.", progress = "Tötet sie alle und bringt mir ihre Köpfe!", completion = "Ihr steht als Racheengel vor mir und ich verneige mich dankbar vor Euch.\n\nNachdem diese Kuh tot ist und ich weiß, dass ihre Brut sich nicht mehr über Azeroth ausbreiten kann, kann ich meine Energie lukrativeren Dingen zuwenden. Ich hoffe, Ihr habt ihren Bauernhof geplündert, als Ihr sie getötet hattet.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDüstere SchulterstückeGallan-Manschetten\n\nIhr bekommt außerdem:\n\n"},
[1166] = {title = "Oberanführer Mok'Morokks Sorgen", objective = "Oberanführer Mok'Morokk in Brackenwall möchte, dass Ihr seinen Grog, seinen Schnupftabak und seine Geldkassette aus dem Dustwallowsumpf holt.", description = "Verbeugen Euch vor Oberanführer Mok'Morokk!\n\nRexxar mich machen zu mächtigem Anführer von Stonemaulklan!\n\nIch gut Anführer. Ich Klan sicher machen.\n\nGroße Drachen kommen und machen Feuer in alte Heimat. Ich klug Oger. Finden neu Heimat für Klan hier.\n\nAlte Heimat so schnell verlassen, ich Sachen vergessen. Winzig <Volk>, gehen mein Sachen holen. Gehen nach Süden und suchen mein lecker Grog, mein Schnupftabak und mein Geldkassette. Ich Euch mögen, wenn Ihr das tun. Ihr in Flammenbau und Stonemaul Ruinen schauen... sie dort sein, ich sicher!", progress = "Ich durstig nach Grog. Ich auch Schnupftabak vermissen. Wo ist Geldkassette? Ihr geht holen für Oberanführer Mok'Morokk!\n\nGeht Süden in alter Heimat suchen. Ich zu beschäftigt, Oger anzuführen.", completion = "Sehr gut, &lt;Volk&gt;. Ich vermissen Sachen sehr. Ich Euch jetzt mögen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nRiesige Ogerstiefel"},
[1167] = {title = "Der Turm von Althalaxx", objective = "Sprecht mit Balthule Shadowstrike beim Turm von Althalaxx.", description = "Bevor Ihr Athrikus konfrontiert, wäre es vermutlich klug, Balthule zu konsultieren. Zweifellos ist er wachsam in seinem Wachturm gewesen und könnte Informationen über jüngste Entwicklungen haben.", progress = nil, completion = "Ah, wie schön, Euch wiederzusehen, &lt;Name&gt;! Hier geschehen die seltsamsten Dinge, ich bin froh, dass Ihr Euch sehen lasst!\n\nEs war sehr seltsam, &lt;Name&gt;. Alles schien normal - jedenfalls so normal, wie es hier sein kann -, und dann schoss plötzlich ein greller Lichtblitz aus dem obersten Turmzimmer. Dann kamen die Schreie. Die Schreie zerrissen die Stille, von Zeit zu Zeit schlugen Blitze in den Boden ein. Was geht hier vor?", rewards = "Ihr bekommt:\n\n"},
[1168] = {title = "Armee des schwarzen Großdrachen", objective = "Tharg in Brackenwall möchte, dass Ihr 15 Späher der Feuermähnen, 10 Aschenschweife der Feuermähnen und 5 Bannschuppen der Feuermähnen tötet.", description = "Mok'Morokk wurde von Rexxar zum Oberanführer gemacht. Ihm liegt mehr an Macht als an den Ogern.\n\nSchwarze Großdrachen töten viele Oger. Töten Thargs Frau. Mok'Morokk sagt uns, wir müssen fliehen. Lässt uns hierher kommen.\n\nOger sollten kämpfen. Oger nicht gut im Weglaufen. Mok'Morokk schert sich nur um Mok'Morokk.\n\nFür mich Stonemaul Ruinen Heimat. Mir gefallen im Süden. Dieser Ort nicht Heimat.\n\nHelft Ogern, Armee der schwarzen Großdrachen zu bekämpfen. Ich wollen Rache. Ich wollen nach Hause.", progress = nil, completion = "Ihr tötet viele der Armee der schwarzen Großdrachen. Ihr Kriegerheld, &lt;Volk&gt;.\n\nMacht Tharg glücklich.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nThargs SchnürsenkelThargs Scheibe\n\nIhr bekommt außerdem:\n\n"},
[1169] = {title = "Die Brut identifizieren", objective = "Draz'Zilb in Brackenwall hätte gern, dass Ihr ihm 15 sengende Zungen und 15 sengende Herzen bringt.", description = "Während der törichte Narr Mok'Morokk seine Macht genießt und Tharg mit den Dämonen des Kummers und der Rache ringt und um die Führerschaft des Klans buhlt, scheine ich der Einzige zu sein, der die Ursache der Aggression in unserer alten Heimat herausfinden möchte.\n\nWarum der verwirrte Blick, <Name>? Erwartet Ihr, dass ich wie ein tumber Grobian spreche, nur weil ich ein Oger bin?\n\nDoch zurück zum Geschäft, bringt mir die Herzen und Zungen der Welpen und Jungtiere. Ich werde die Wurzel dieses Übels finden...", progress = "Mit den Herzen und Zungen versengter Nachkommen der Armee der schwarzen Großdrachen kann ich herausfinden, welche elende Bestie ihre Brut in unsere Heimat einführte. Wenn wir mehr über unsere Angreifer wissen, können wir versuchen, sie ein für allemal zu vernichten und das Dorf Stonemaul zurückzuerobern.\n\nNatürlich wird es an sich schon eine epische Aufgabe sein, Mok'Morokk zu überzeugen, dass er seine fette, träge Masse aus diesem Dreckloch hebt...", completion = "Zweifellos war es eine gefährliche Sache, diese Herzen und Zungen zu sammeln. Ich werde in die Tiefen des Arkanen vorstoßen, um den Ursprung der schwarzen Bedrohung zu finden, die über unsere einstige Heimat kam.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVersengtes CapeHandschuhe des Viehdiebs\n\nIhr bekommt außerdem:\n\n"},
[1170] = {title = "Die Brut von Onyxia", objective = "Sprecht mit Oberanführer Mok'Morokk in Brackenwall.", description = "Das Dorf Stonemaul wurde von der Brut von Onyxia überrannt. Aber warum sollte die Tochter des Schwarzen-Großdrache-Lords Deathwing über unser Land herfallen?\n\nDas ist sehr beunruhigend. Gewiss wurde Onyxia aus einem anderen Grund hergeschickt, als eine kleine Schar von Ogern zu belagern.\n\nVerständigt unverzüglich Mok'Morokk! Es muss gehandelt werden.", progress = nil, completion = "Warum Ihr mir von Großdrachen erzählen? Ich Großdrachen nicht mögen. Mir hier gefallen. Keine Drachen hier.", rewards = "Ihr bekommt:\n\n"},
[1171] = {title = "Die Brut von Onyxia", objective = "Sprecht mit Draz'Zilb in Brackenwall.", description = "Ihr lasst mich jetzt in Ruhe. Sagt Draz'Zilb, wir bleiben hier. Keine schwarzen Großdrachen hier.", progress = nil, completion = "Dieser träge Feigling!\n\nMok'Morokks zeigte Kraft, als Rexxar unser Anführer war. Doch kurz nach Rexxars Verschwinden erlag Mok'Morokk den Verlockungen der Macht. Er führte nicht, er forderte. Er dient nicht seinem Volk, sondern erwartet, dass wir ihm dienen.\n\nEs muss etwas geschehen.", rewards = "Ihr bekommt:\n\n"},
[1172] = {title = "Die Brut von Onyxia", objective = "Draz'Zilb in Brackenwall möchte, dass Ihr 5 Eier von Onyxia zerstört.", description = "Onyxias Brut wurde über das Drachendüster verstreut. Es dürfen auf keinen Fall weitere Welpen schlüpfen.\n\nBegebt Euch eilig zum Drachensumpf in den Marschen von Dustwallow. Gewiss hat sie dort einen Hort angelegt. Sucht die Eier der bösen Großdrachen und vernichtet sie.\n\nWir können das Dorf Stonemaul nie zurückerobern, wenn das Umland eine Brutstätte bleibt.\n\nWas Mok'Morokk angeht ... Für den Jammerlappen habe ich andere Pläne.", progress = nil, completion = "Großartig! Es wird einige Zeit dauern, bis Onyxia wieder Eier legen kann.\n\nIm Namen meines Volkes danke ich Euch, &lt;Name&gt;.\n\nIch habe bislang viel von Euch verlangt. Vielleicht könnt Ihr dem Stonemaulklan einen letzten Dienst erweisen.\n\nMok'Morokk ist uns kein guter Anführer. Tharg wäre ein brillanter Anführer, ist aber durch seine Verletzungen und sein Alter behindert. Vertreibt Mok'Morokk mit Gewalt von hier. Erst dann können wir einen neuen Anführer bestimmen und in unsere angestammte Heimat im Süden zurückkehren.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nEncarmine-StiefelStiefel von Zua'tec\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1173] = {title = "Fordert Oberanführer Mok'Morokk heraus", objective = "Besiegt Mok'Morokk und bringt die Nachricht zu Draz'Zilb in Brackenwall.", description = "Ihr wagt es, Oberanführer Mok'Morokk herauszufordern?\n\nHa!\n\nIch zerschmettern einen Winzling von <Volk>!\n\nIhr mir sagen, wenn bereit für ordentliche Tracht Prügel.", progress = nil, completion = "Dieser feige Fettwanst Mok'Morokk floh wie ein ängstliches Kind. Ihr habt uns einen großen Dienst erwiesen, &lt;Name&gt;.\n\nJetzt kann mein Volk einen neuen Anführer bestimmen, mit dem wir unsere angestammte Heimat ein für allemal zurückerobern.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSatansmesserFröstelnagel-Splinter\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1174] = {title = "Die Gnome gewinnen!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGnomen-Preiskasten"},
[1175] = {title = "Eine Straßenunebenheit", objective = "Tötet 10 Salzsteinbasilisken, 10 Salzsteinkristallhäute und 6 Salzsteinstarrer für Rennsteckenleiter Zherin in der schimmernden Ebene.", description = "Nach dem schweren Zusammenstoß des Red-Thunder-Rennwagen der Goblins und einem Basilisken hat Kronkrider mich angeheuert, um die Strecke zu warten. Keine Ahnung, was die Tiere in der Ebene fressen, dass sie so groß werden, aber wir müssen sie dezimieren, damit sie nicht auf die Fahrbahn laufen, wenn ein Rennen stattfindet.\n\nIch sag Euch was. Wenn ihr ein wenig Profit machen wollt, zieht los und entfernt die Basilisken aus der Gegend.", progress = "Es ist schon schlimm genug, wenn man die Trümmer der Rennwagen beseitigen muss, auch ohne sie aus verbrannten Tierkadavern herauszuklauben.", completion = "Ich hoffe, Ihr habt keine Basilisken auf der Rennstrecke selbst getötet! Es dauert lange, bis die Kadaver in der Sonne verfallen, und ich möchte lieber nicht mit einer Schaufel da raus und sie entsorgen.", rewards = "Ihr bekommt:\n\n"},
[1176] = {title = "Gewicht reduzieren", objective = "Beschafft 10 hohle Geierknochen für Pozzik in der schimmernden Ebene.", description = "Wenn es um Rennen geht, zählt jede Kleinigkeit! Ob es sich nun um ein leises Quietschen der Kraftübertragung, eine geringfügige Schwäche der Stoßdämpfer oder ein leichteres Gewicht der Karosserie handelt, man muss alles berücksichtigen.\n\nWir benutzen Geierknochen für kleinere Modifikationen am Chassis unserer Rennwagen, die das perfekte Gleichgewicht zwischen Stärke und Gewicht haben. Und sie sind, was noch besser ist, leicht zu beschaffen, da es in der Salzwüste von Geiern wimmelt.\n\nBringt mir ein paar und ich zahle einen guten Preis dafür.", progress = "Habt Ihr die Knochen für mich? Ich wollte gerade die Steueraufhängung leichter machen, möchte das Auto aber nicht zerlegen, solange ich nicht alle erforderlichen Teile habe.", completion = "Großartig! Ich lasse die Crew sofort daran arbeiten. Danke, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[1177] = {title = "Hunger!", objective = "Mudcrush Durtfeet im nördlichen Dustwallow möchte 12 Schlammflossenköpfe.", description = "Mud großer Oger.\n\nIch hungrig.\n\nGeht Fische hauen. Bringt Mud Essen.\n\nIhr füttert Mud oder Mud frisst Euch.", progress = "Gebt mir Essen oder ich Euch fressen.", completion = "Ich mag Fischköpfe!\n\nIch Euch jetzt nicht fressen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMuds ZermalmerDurtfeet-Stampfer\n\nIhr bekommt außerdem:\n\n"},
[1178] = {title = "Goblin-Sponsoring", objective = "Sprecht mit Gazlowe in Ratchet.", description = "Unser Rennfahrer-Team ist der Stolz aller Goblins. Ihr wärt überrascht, welche Leute unser Team auf die eine oder andere Weise unterstützen.\n\nKennt Ihr Gazlowe? Er treibt auf der ganzen Welt Ersatzteile für uns auf. Er kam sogar mal her, um an einer unserer Aufhängungen zu arbeiten!\n\nVor ein paar Wochen wollte er uns den Prototyp einer neuen Treibstoffeinspritzpumpe schicken, aber sie ist noch nicht eingetroffen. Sonst ist er immer zuverlässig ... Würde es Euch vielleicht etwas ausmachen, nach Ratchet zu gehen und ihn danach zu fragen? Ich will ja nicht drängen, aber die Gnome holen langsam auf!", progress = nil, completion = "Pozzik hat Euch geschickt? Wisst Ihr, Pozzik war einer der angesehensten Tüftler in Undermine, bevor er sich zurückzog und an Rennwagen bastelte.\n\nAls er dem Team beitrat, entwickelte er als Erstes die zweimotorigen Rennwagen. Könnte sein, dass das Geschäft leidet, wenn er nicht mehr im Tüftlerverband arbeitet, aber wen interessiert das schon, was? Es geht doch nichts über die Rennen!", rewards = "Ihr bekommt:\n\n"},
[1179] = {title = "Die Brüder Brassbolt", objective = "Bringt die Kiste mit Schutzhelmen zu Wizzle Brassbolts in der schimmernden Ebene.", description = "Schon von der schimmernden Ebene gehört, ja? Das ist eine Salzwüste drüben in Kalimdor, direkt südlich vom Canyon der Tausend Nadeln. Der ideale Austragungsort für Rennen, weil es da so flach ist!\n\nDa draußen sind zwei Gnomenbrüder, Freunde von mir, die ihren neuen Raketenwagen erproben, und soweit ich gehört habe, ist er schnell! Hey, so schnell, dass die Fahrer immer verunglücken. Und Gehirnerschütterungen bekommen.\n\nDarum baten sie mich um ein paar Helme für Belagerungsmaschinen, aber ich kann hier nicht weg, meine Pflicht fesselt mich an diesen Ort. Ich kann die Reise also nicht machen!\n\nKönnt Ihr es?", progress = "Passt auf, wo Ihr hintretet! Aufpassen, aufpassen, aufpassen!!! Das hier sind empfindliche Teile, und wenn wir gewinnen wollen, muss alles perfekt funktionieren!", completion = "Ah! Longbeard hat Euch mit den Helmen geschickt! Hurrah!\n\nVielleicht können wir jetzt einen Fahrer überreden, unseren Wagen zu fahren...", rewards = "Ihr bekommt:\n\n"},
[1180] = {title = "Goblin-Sponsoring", objective = "Sprecht mit Werftmeister Lozgil in Booty Bay.", description = "Zurück zum Grund Eures Hierseins. Ich weiß, ich habe Pozzik versprochen, dass ich ihm eine neue Treibstoffeinspritzpumpe schicke, aber ich habe sie selbst noch nicht bekommen. Revilgaz drüben in Booty Bay sagte, er würde sie herschicken, aber irgendwie scheint da was schief gelaufen zu sein.\n\nWenn das stimmt, können wir wenig dagegen tun. Aber wir können wenigstens herausfinden, wann sie von Booty Bay abgeschickt wurde.\n\nFragt drüben bei Werftmeister Lozgil nach, er müsste die Frachtbriefe überprüfen können.", progress = nil, completion = "Lieferungen nach Ratchet? Lasst mich in den Logbüchern nachsehen...\n\nNein, die letzte vermerkte Sendung nach Ratchet waren Stiefel von Drizzlik. Sonst nicht viel, abgesehen von Baustoffen und Werkzeugen. Definitiv keine Rennwagenteile.", rewards = "Ihr bekommt:\n\n"},
[1181] = {title = "Goblin-Sponsoring", objective = "Sprecht mit Baron Revilgaz in Booty Bay.", description = "Ich fürchte, ich kann Euch nicht weiterhelfen, <Name>. Wenn Ihr der Sache weiter nachgehen möchtet, würde ich vorschlagen, Ihr geht zum Baron persönlich. Wenn jemand über die Geschäfte von Revilgaz Bescheid weiß, dann Revilgaz selbst.\n\nIhr findet ihn in der Taverne jenseits des Hafens, Obergeschoss.", progress = nil, completion = "Oh, gewiss, natürlich weiß ich, wovon Ihr redet. Neee, ich kann Euch aber nicht helfen. Einige meiner Männer sollten die Blaupausen für die Treibstoffeinspritzpumpe aufspüren, kamen aber mit leeren Händen zurück.", rewards = "Ihr bekommt:\n\n"},
[1182] = {title = "Goblin-Sponsoring", objective = "Bringt die Treibstoffreglerblaupausen zu Baron Revilgaz in Booty Bay.", description = "Wisst Ihr, die Schredder der Venture Company draußen am Nazferitisee (im Norden des Schlingendorntals) wurden mit einer neuartigen Treibstoffeinspritzpumpe ausgerüstet. Ich dachte mir, Pozzik könnte Kapital daraus schlagen, wenn er einige Einzelheiten erfahren könnte. Leider scheint Cozzle, der dortige Großknecht, etwas schlauer zu sein als ich ihm zugestehen wollte.\n\nAber Ihr seht aus, als könntet Ihr es schaffen, die Blaupausen zu finden. Ich weiß, dass er sie in seinem Haus aufbewahrt, aber mit Sicherheit verschlossen und verriegelt.", progress = "So ungern ich es zugebe, das Gnomen-Team, das Sie da draußen haben, ist ziemlich gut. Unsere Jungs brauchen jeden Vorteil, den sie bekommen können.", completion = "Lasst mich nur rasch eine Kopie dieser Blaupausen für meine eigenen Notizen machen, dann könnt Ihr sie direkt zu Pozzik bringen. Er soll nicht denken, dass ihn einer seiner Sponsoren im Stich lässt.", rewards = "Ihr bekommt:\n\n"},
[1183] = {title = "Goblin-Sponsoring", objective = "Bringt die Blaupausen der Treibstoffeinspritzpumpe zu Pozzik in der schimmernden Ebene.", description = "Ihr solltet zum Aufbruch bereit sein. Bestellt Pozzik schöne Grüße und sagt ihm, wenn er etwas braucht, soll er keine Hemmungen haben, zu fragen. Ich warte auf die baldige Nachricht, dass er den Streckenrekord gebrochen hat!", progress = "<Name>! Habt Ihr die Treibstoffeinspritzpumpe aufspüren können?", completion = "Ich hatte gehofft, sie wäre schon zusammengebaut, aber dies bietet die einmalige Gelegenheit, die Pläne von Grund auf zu verbessern. Danke, &lt;Name&gt;. Ich werde einige verbesserte Baupläne skizzieren, das Ding bauen und es schon bald installieren können.", rewards = "Ihr bekommt:\n\n"},
[1184] = {title = "Teile des Schwarms", objective = "Kehrt zu Belgrom Rockmaul in Orgrimmar zurück.", description = "Geht zurück zu Belgrom in Orgrimmar und sagt ihm, dass Moktar in Tausend Nadeln ganz in seinem Sinne handelt. Sagt ihm auch, dass meine Studien voranschreiten und ich hoffe, dass ich bald mehr gelernt habe. Das sollte ihn freuen.", progress = nil, completion = "Ich weiß Eure Anstrengungen zu schätzen, &lt;Klasse&gt;. Der Kriegshäuptling wird gern hören, wie gewissenhaft Ihr Eure Pflicht erfüllt habt.\n\nOh, gewiss werde ich ihm Euren Namen nennen. Er spricht oft mit mir und schätzt meine Meinung hoch.\n\nGeht jetzt, ich habe viel Arbeit vor mir. Und wenn Ihr demnächst mit Korran sprecht und er Neuigkeiten über diese Kreaturen hat, dann kommt wieder zu mir - ich meine, sie sind eine Bedrohung, die man ernst nehmen muss.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTrockenlaub-HoseBlutende Mondsichel\n\nIhr bekommt außerdem:\n\n"},
[1185] = {title = "Unter dem Chitin war...", objective = "Ah, Ihr seid es wieder! Ja, Euch meine ich - also Euch, <Name>! Ja, Euereiner!\n\nHe, ich fang noch mal von vorn an!\n\nDas Objekt, das Ihr in Silithus fandet - war in der Tat ein Buch. Es war ein in einem sehr alten Dialekt verfasstes Tagebuch, wir nennen die Sprache heute Darnassisch. Es wird eine Weile dauern, aber ich werde es sehr sorgfältig studieren. Ich dachte, Ihr solltet wissen, dass Euer Fund für den Zirkel äußerst wertvoll ist.\n\nDie Höhlenmutter ist völlig aus dem Häuschen!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[1186] = {title = "Der achtzehnte Rennfahrer", objective = "Sprecht mit Razzeric in der schimmernden Ebene.", description = "Ich werde damit beschäftigt sein, diese neue Treibstoffeinspritzpumpe in unsere Rennwagen einzubauen, aber wenn Ihr dem Team noch weiter helfen möchtet, sprecht mit Razzeric. Er ist unser Fahrer - unser achtzehnter Fahrer, um genau zu sein -, und er nimmt selbst gern Veränderungen an den Rennwagen vor.\n\nAber er ist ein wenig daneben, bemüht Euch daher, nicht zu überrascht zu wirken.", progress = nil, completion = "Ihr, &lt;Volk&gt;, habt Pozzik geholfen, richtig? Ich war einst wie Ihr, rannte in der Boxengasse herum und machte jede Arbeit, die die Mechaniker mich tun ließen.\n\nJetzt seht mich an! Der Super-Rennfahrer des Goblin-Teams!", rewards = "Ihr bekommt:\n\n"},
[1187] = {title = "Razzerics Basteln", objective = "Bergt den Zephyriumnachbrenner für Razzeric in der schimmernden Ebene.", description = "Pozzik ist ein toller Mechaniker, das weiß ich, aber er hat Angst davor, einfach was mit viel Power einzubauen und dann loszudüsen. Aber ich nicht.\n\nWenn Pozzik mit einem Rennwagen fertig ist, nehme ich mir die Zeit und baue eigene Veränderungen ein - Ihr wisst schon, die Steuerung lockern, Teile des Rahmens entfernen und ihm mehr Saft geben!\n\nIch habe einen Zephyriumnachbrenner von Shreev im Gizmorium in Gadgetzan bestellt, aber offenbar musste der Zeppelin, mit dem er geschickt wurde, in den Marschen von Dustwallow notlanden! Ich muss das Ding haben, <Name>!", progress = "Wie soll ich mich auf der Rennstrecke blicken lassen, wenn ich nicht ein bisschen extra Power habe? Ich sage Euch, das ist ein Witz.", completion = "Seht Euch nur diese Schönheit an! Fünfzehn Pfund robustes Zephyriumpulver! Wenn ich das an meinen Rennwagen festschnalle, bezwinge ich die Rennstrecke so schnell, dass ich die Gnome zweimal schlage!", rewards = "Ihr bekommt:\n\n"},
[1188] = {title = "Sicherheit zuerst", objective = "Bringt den Zephyriumnachbrenner zu Shreev in Gadgetzan.", description = "Doch wartet, was ist das? Shreev hat die Sicherung aktiviert gelassen. Das reduziert die Menge Energie, die ich aus dem Nachbrenner rausholen kann. Ich sagte ihm, ich wollte sie deaktiviert haben! Das ist nicht gut.\n\nIhr müsst das ins Gadgetzan-Gizmorium in der Tanariswüste bringen und es von Shreev entfernen lassen.", progress = "Wir Ihr sicher wisst, können im Gizmorium all Eure Tüftlerwünsche erfüllt werden! Wie kann ich Euch helfen?", completion = "Nur Razzeric würde einen Blick darauf werfen und sagen, dass ich eine Art Sicherung eingebaut habe. Dieser Nachbrenner besteht fast ausschließlich aus Zephyriumsprengstoff. Ich habe ihn schon so umgebaut, dass mehr von seiner Ladung bei der Benutzung freigesetzt wird, aber Razzeric ist immer erst zufrieden, wenn alles hundertundzehnprozentig ist!", rewards = "Ihr bekommt:\n\n"},
[1189] = {title = "Sicherheit zuerst", objective = "Bringt den umgebauten Zephyriumnachbrenner zu Razzeric in der schimmernden Ebene.", description = "So, ich habe getan, was Razzeric wollte. Sagt ihm nur, er soll vorsichtig sein, wenn er das zündet. Wenn er den kleinsten Fehler macht, fährt er nicht los, sondern ist nur noch ein Brandfleck auf der Rennstrecke.\n\nWäre doch ein Jammer, wenn das passiert. Wer weiß, ob unser neunzehnter Fahrer genauso gut wäre?", progress = "Könnt Ihr glauben, dass Pozzik einen Eimer Sand in dem Rennwagen verstaute? Wie soll ich Höchstgeschwindigkeit erreichen, wenn ich einen Eimer Sand unter dem Sitz habe?", completion = "Ja, das ist schon besser! Könnte ich doch nur die Gesichter der Gnome sehen, wenn ich mit diesem Baby durchstarte.\n\nLeider werde ich voll und ganz damit beschäftigt sein, einen neuen Streckenrekord aufzustellen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRazzerics maßgefertigter SicherheitsgurtRazzerics Rennhandschutz\n\nIhr bekommt außerdem:\n\n"},
[1190] = {title = "Tempo halten", objective = "Lasst Zamek ein Ablenkungsmanöver inszenieren und stehlt dann Rizzles Pläne für Pozzik in der schimmernden Ebene.", description = "Die Brassbolts-Brüder haben einen neuen Baustoff entdeckt, das ist die einzig logische Erklärung. Ihre Rennwagen fahren schneller als vorher, aber Design und alle anderen Daten ihrer Probefahrten sind noch dieselben.\n\nWir wissen, dass Rizzle Brassbolts sich fast ununterbrochen mit den Plänen seiner neuen Entdeckung befasst hat.\n\nZamek kann ein Ablenkungsmanöver inszenieren, damit Ihr diese Pläne von ihnen stehlen könnt.", progress = nil, completion = "Mit einer krakeligen Handschrift hastig hingekritzelte Anmerkungen und eine Notiz-Rolle über die Veredelung eines neuen Rohmaterials.", rewards = "Ihr bekommt:\n\n"},
[1191] = {title = "Zameks Ablenkungsmanöver", objective = "Auf geht’s!", description = nil, progress = nil, completion = nil, rewards = nil},
[1192] = {title = "Induriumerz", objective = "Ich würde gern in verschiedene Teile unserer Rennwagen Indurium integrieren, brauche aber große Mengen Rohindurium, um diese Teile herzustellen.\n\nIhr findet Indurium in der Ausgrabungsstätte Uldaman im Ödland in Khaz Modan, jenseits des Meeres.\n\nDie Gnomen bekommen ihre eigenen Vorräte, wir müssen daher unbedingt selbst welches haben, um mit ihnen Schritt zu halten.", description = nil, progress = "Ich würde gern in verschiedene Teile unserer Rennwagen Indurium integrieren, brauche aber große Mengen Rohindurium, um diese Teile herzustellen.\n\nIhr findet Indurium in der Ausgrabungsstätte Uldaman im Ödland in Khaz Modan, jenseits des Meeres.\n\nDie Gnomen bekommen ihre eigenen Vorräte, wir müssen daher unbedingt selbst welches haben, um mit ihnen Schritt zu halten.", completion = "Exzellent! Ich lasse die Crew sofort an den Teilen arbeiten, die wir für das nächste Rennen brauchen.", rewards = "Ihr bekommt:\n\n"},
[1193] = {title = "Die beschädigte Falle", objective = "Vor Euch liegt eine große, beschädigte Falle. Ihrem Aussehen nach zu urteilen, müssen die Oger versucht haben sie zu reparieren, jedoch ohne Erfolg. Eine hastig geschriebene Notiz liegt neben der Falle. Seltsamerweise beschreibt sie ausführlich was benötigt wird, um die Falle zu reparieren: ein Thoriumapparat und etwas Frostöl. Wäre die Falle wieder repariert, könnte ein verbeikommender Oger darin gefangen und so umgangen werden.\n\nEs ist offensichtlich ein glücklicher Zufall, dass nur die wenigsten Oger lesen können.\n\nOffensichtlich.", description = nil, progress = "Vor Euch liegt eine große, beschädigte Falle. Ihrem Aussehen nach zu urteilen, müssen die Oger versucht haben sie zu reparieren, jedoch ohne Erfolg. Eine hastig geschriebene Notiz liegt neben der Falle. Seltsamerweise beschreibt sie ausführlich was benötigt wird, um die Falle zu reparieren: ein Thoriumapparat und etwas Frostöl. Wäre die Falle wieder repariert, könnte ein verbeikommender Oger darin gefangen und so umgangen werden.\n\nEs ist offensichtlich ein glücklicher Zufall, dass nur die wenigsten Oger lesen können.\n\nOffensichtlich.", completion = "Die Thoriumvorrichtung lässt sich problemlos einfügen, und der so entstehende Hohlkörper eignet sich perfekt, um das Frostöl nach unten abfließen zu lassen. Nachdem der letzte Tropfen Öl hineingeschüttet wurde, lässt sich die Falle wieder einrasten.\n\nWehe dem unvorsichtigen Oger der hier vorbeikommt!", rewards = nil},
[1194] = {title = "Rizzles Baupläne", objective = "Bringt die Induriumerzprobe zu Pozzik in der schimmernden Ebene.\n\nBereitgestellter Gegenstand: \n", description = "Rizzles Baupläne beschreiben den Vorgang der Veredelung von Induriumerz. Man kann dem Gekritzel entnehmen, dass Induriumerz an der Ausgrabungsstätte Uldaman der Zwerge im Ödland zu finden ist.\n\nDie anderen Notizen behandeln fast ausschließlich seinen Hitzewiderstand.\n\nAls Briefbeschwerer der Pläne dient ein Klumpen, der wie unbearbeitetes Induriumerz aussieht.", progress = nil, completion = "Indurium? Interessant... Wenn es wirklich einen so hohen Hitzewiderstand hat, wie Ihr sagt, würde das erklären, warum die Gnome jüngst so deutlich bessere Leistungen erzielten.\n\nDiese Probe, die Ihr mir gebracht habt, ist ebenso von unschätzbarem Wert. Ich werde einige Tests damit durchführen können, aber ich brauche mehr davon, damit es uns tatsächlich von Nutzen ist.", rewards = "Ihr bekommt:\n\n"},
[1195] = {title = "Die heilige Flamme", objective = "Bringt eine gefüllte geätzte Phiole zu Zangen Stonehoof in Thunder Bluff.", description = "Die Galakzentauren von Tausend Nadeln beschützen ein Artefakt aus der Zeit der Erschaffung der Zentauren.\n\nWir würden es gern bergen, benötigen aber eine Phiole Wasser aus einem der Mondbrunnen der Nachtelfen.\n\nUm dieses Wasser zu beschaffen, müsst Ihr zuerst eine Phiole besorgen, wie sie die Dryaden beim Raynewood im Herzen von Ashenvale besitzen. Am Westufer des Falfarren, südlich der Hauptstraße, befindet sich ein Mondbrunnen, in dem Ihr die Phiole füllen könnt.", progress = "Wenn wir die gefüllte Phiole haben, können wir sie zu meinem Mitarbeiter Rau in Tausend Nadeln schicken. Er wollte die Phiole Wasser haben, also sollte er wohl auch wissen, wie wir sie nutzen können.", completion = "Sehr gut. Damit sollte Raus Bitte erfüllt sein. Könntet Ihr dies zu ihm bringen? Vielleicht genießt Ihr ja einen Ausflug nach Tausend Nadeln.", rewards = "Ihr bekommt:\n\n"},
[1196] = {title = "Die heilige Flamme", objective = "Bringt die gefüllte geätzte Phiole zu Rau Cliffrunner im Freiwindposten.", description = "Bringt die gefüllte Phiole zu Rau Cliffrunner beim Freiwindposten im Südosten von Tausend Nadeln. Ihr gelangt nach Tausend Nadeln, wenn Ihr den großen Aufzug am Südrand des Brachlandes benutzt.\n\nIch wäre nicht überrascht, wenn Ihr uns weiter behilflich sein könntet.", progress = "Ich nehme nicht an, dass Zangen Euch geschickt hat, hm?", completion = "Hm, ja, diese Phiole Wasser sollte für unsere Zwecke perfekt genügen. Da Dryaden und Zentauren gemeinsame Vorfahren haben, können wir mit dem Wasser der Mondbrunnen den Schutz der ewigen Flamme durchbrechen, die das Relikt der Zentauren umgibt.", rewards = "Ihr bekommt:\n\n"},
[1197] = {title = "Die heilige Flamme", objective = "Holt den gespaltenen Huf für Rau Cliffrunner im Freiwindposten.", description = "Wenn Ihr das Wasser benutzt, das Ihr mitgebracht habt, könnt Ihr vorübergehend die Flamme löschen, die das Zentaurenrelikt schützt. Aber der Effekt ist nicht von Dauer, daher müsst Ihr rasch handeln.\n\nIhr findet die Spalthufklippe, die Festung der Zentauren, nördlich von hier. Die Flamme wird in der Spalthufhöhle bewahrt, einem schwer bewachten Teil der Klippe.\n\nAber seid vorsichtig, die Zentauren der Galak sind dort in großer Zahl zugegen und dürften etwas, das ihnen so teuer ist, nicht freiwillig hergeben.", progress = "Ich brenne darauf, den gespaltenen Huf in die Finger zu bekommen. Habt Ihr ihn schon genommen?", completion = "Ich spüre eine seltsame Energie aus dem Huf kommen... Zweifellos werden wir durch seine Untersuchung überraschende neue Informationen über die Zentauren erhalten.\n\nMeinen Dank, &lt;Name&gt;. Jetzt muss ich die Mysterien enträtseln, die Ihr mir gebracht habt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nCliffrunners ZielAzurblaue Schärpe\n\nIhr bekommt außerdem:\n\n"},
[1198] = {title = "Auf der Suche nach Thaelrid", objective = "Sucht Argentumwache Thaelrid in der Blackfathom-Tiefe auf.", description = "Heutzutage kursieren viele Gerüchte über die Vereinigung der Twilight-Hammer und Naga in der Blackfathom-Tiefe an den Küsten von Ashenvale.\n\nMeine Rolle hier bei der Argentumdämmerung besteht darin, so viele Informationen wie möglich zu sammeln, damit wir wissen, wann und wo Hilfe erforderlich ist.\n\nEs ist jetzt Wochen her, seit ich einen Späher losschickte, um die Aktivitäten in der Blackfathom-Tiefe auszuspähen. Argentumwache Thaelrid hat sich noch nicht zurückgemeldet.\n\nMeine anderen Späher sind mit dringenden Angelegenheiten beschäftigt.\n\nSucht und unterstützt Thaelrid für mich, <Name>.", progress = nil, completion = "Gut, dass Dämmerungsbehüter Shaedlass Euch geschickt hat. An diesem Ort der Verderbnis wird ein finsterer Plan geschmiedet.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1199] = {title = "Die Twilight fallen", objective = "Bringt 10 Twilight-Anhänger zu Argentumwache Manados in Darnassus", description = "Mit der Macht der uralten Rituale der chaotischen Alten Götter versuchen die Mitglieder der Twilight-Hammer, ihre dunklen Schutzherren zurückzuholen und Tod und Schrecken in der Welt zu verbreiten.\n\nWir glauben, dass die Twilight-Hammer sich mit den Naga verbündet haben und sich in der Blackfathom-Tiefe an den Küsten von Ashenvale zusammenrotten.\n\nWelch schändliche Pläne in den Tiefen des alten Tempels auch immer geschmiedet werden, wir müssen sie vereiteln.\n\nFührt Krieg gegen die Hammer und bringt Beweise Eurer Taten mit. Eure Bemühungen sollen reich belohnt werden.", progress = "Die Blackfathom-Tiefe war einst ein alter Tempel der Nachtelfen. Ehedem befand sich einer der mächtigsten Mondbrunnen darin. Wer weiß, welches Übel die Twilight-Hammer jetzt dort ausbrüten?\n\nHabt Ihr schon Fortschritte bei ihrer Vertreibung erzielt?", completion = "Ihr seid zweifellos von tapferem und edlem Geblüt, &lt;Name&gt;. Die Argentumdämmerung dankt Euch für Euren Einsatz gegen das Böse.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nNimbus-StiefelHerzholzgurt"},
[1200] = {title = "Schurkerei in Blackfathom", objective = "Bringt den Kopf des Twilight-Lords Kelris zu Dämmerungsbehüter Selgorm in Darnassus.", description = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'Mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.\n\nDie Kultisten der Twilight-Hammer haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'Mai, um Macht zu erlangen.\n\nBitte, erschlagt Kelris und bringt Selgorm in Darnassus seinen Kopf, <Name>.", progress = "Zeit ist ein kostbares Gut, <Klasse>.\n\nMeine Rolle hier in Darnassus ist es, sicherzustellen, dass die Argentumdämmerung gedeiht und die bösen Mächte aus Kalimdor vertrieben werden.\n\nSagt rasch, was Euer Begehr ist, oder zieht von dannen.", completion = "Kelris entwischt uns schon seit geraumer Zeit.\n\nOffenbar ist Kelris stets dabei, wenn das Böse in dieser Region sein hässliches Haupt erhebt. Eine Zeit lang hielten wir ihn für tot oder vermisst.\n\nDoch dies scheint logisch zu sein. Als Ihr seine Herrschaft beendet habt, habt Ihr vielen Unschuldigen das Leben gerettet.\n\nBeim Licht! Es ist mehr als schändlich, jemanden den Dienern eines Alten Gottes zu opfern, um persönlich Kapital daraus zu schlagen!\n\nIhr habt eine große Tat vollbracht, &lt;Name&gt;. Ich salutiere im Namen der Argentumdämmerung vor Euch.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGrabsteinszepterArktischer Rundschild\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1201] = {title = "Theramores Spione", objective = "Tötet 9 Spitzel von Theramore und kehrt dann zu Nazeer Bloodpike in Brackenwall zurück.", description = "Die Horde und die Allianz wahren einen brüchigen Waffenstillstand. Beide Seiten liefern sich Scharmützel und heimliche Angriffe. Wir müssen dafür sorgen, dass die Horde stets die Oberhand behält!\n\nJetzt haben wir die Chance, genau das zu tun.\n\nSpitzel der Allianz haben Stellungen östlich des Dorfs Brackenwall bezogen. Sie spionieren das Dorf aus und melden unsere Bewegungen Theramore, was wir nicht dulden können.\n\nJagt die Spitzel und schaltet sie aus. Schickt eine deutliche Botschaft an ihre Vorgesetzten, dass wir die Anwesenheit ihrer Spione nicht dulden!", progress = nil, completion = "Gute Arbeit. Ihre Spitzel sind geschickt, aber nicht gut genug, den wachsamen Blicken der Horde zu entkommen!", rewards = "Ihr bekommt:\n\n"},
[1202] = {title = "Die Docks von Theramore", objective = "Bringt die Dokumente des Kapitäns zu Nazeer Bloodpike in Brackenwall.", description = "<Name>, zwei unserer Spione wurden ausgeschickt, um Dokumente von einem Schiff bei den Docks von Theramore zu stehlen. Sie bekamen die Papiere, wurden aber entdeckt und waren gezwungen, die Dokumente ins Meer zu werfen.\n\nSpäter konnte ein Spion entkommen, die Beute aber nicht bergen. Er informierte mich über sein Scheitern und jetzt gebe ich Euch die Aufgabe.\n\nDie Dokumente sind in einer Schließkiste irgendwo im Wasser unter den Docks von Theramore. Sucht diese Dokumente, <Name>, und bringt sie mir.", progress = "Habt Ihr die Dokumente gefunden, <Name>? Sie enthalten Informationen, die wichtig für die Stabilität der Allianz, und damit auch wichtig für die Sicherheit der Horde sind.", completion = "Ich bewundere Euch, &lt;Name&gt;. Dies war keine leichte Mission. Aber die Dokumente, die Ihr gerettet habt, werden von unseren Vorgesetzten hoch geschätzt.", rewards = "Ihr bekommt:\n\n"},
[1203] = {title = "Jarl braucht eine Klinge", objective = "Bringt ein Mondstahlbreitschwert zu Jarl in den Marschen von Dustwallow.", description = "Ich habe zu schneiden. Ich kann Euch nicht sagen, was ich schneiden werde, aber... Ich brauche eine Klinge. Eine ganz bestimmte Klinge...\n\nManche Leute sprechen von einem Mondstahlbreitschwert. Ich nenne es eine Schwingklinge.\n\nHelft Ihr mir? Vielleicht findet Ihr sie in der Stadt, vielleicht sprecht Ihr mit einem Schmied und er macht sie eigens.\n\nAber schlaft nicht noch darüber. Was ich schneide, das hält nicht ewig...", progress = "Habt Ihr meine Klinge???", completion = "Das ist eine gute Klinge. Sie schwingt gut. Es ist eine gute Schwingklinge. Danke. Danke, danke, danke!!! Jetzt möchte ich sie ausprobieren... \n\nSpäter. Ich probiere sie später aus. Aber wie ich schon sagte... danke.", rewards = "Ihr bekommt:\n\nSchilfknotenringFachmann-Beinkleider"},
[1204] = {title = "Schlammpanzersuppe mit Käfern", objective = "Bringt Morgan Stern in Theramore 8 gespaltene Schlammpanzerzungen.", description = "Ich arbeite an einem Gericht namens \"Schlammpanzersuppe mit Käfern\". Die wichtigsten Zutaten fehlen mir leider noch immer... aber ich glaube nicht, dass ich einen Fußmarsch durch die Dustwallow-Marschen durchhalten könnte.\n\nNun denn, <Name>, könntet Ihr für mich auf die Jagd gehen? Als Erstes brauche ich die Zungen von Schlammpanzerschildkröten. Ihr findet die Schlammpanzer entlang der Küste, hauptsächlich im Bereich der Bucht.\n\nAber ich will nicht jede beliebige Zunge! Ich habe gehört, dass die Zungen von einigen Schlammpanzerschildkröten gespalten sind...\n\nMan sagt, diese gespaltenen Zungen hätten einen charakteristischen Geschmack, und den möchte ich in meinem Gericht...", progress = "Habt Ihr die gespaltenen Zungen gefunden?", completion = "Diese sind ganz exzellent! Danke, &lt;Name&gt;!\n\nJetzt werde ich versuchen, durch verschiedene Kochtechniken herauszufinden, wie ihr Geschmack am besten zur Geltung kommt.\n\nVielleicht werde ich ein Gericht kreieren, das des Blauen Eremiten in Stormwind würdig ist!", rewards = "Ihr bekommt:\n\n"},
[1205] = {title = "Schlammwühler", objective = "Bringt Schlammwühlers Zahn zu Melor in Thunder Bluff.", description = "Schlammwühler ist ein uralter Krokilisk in den Marschen von Dustwallow. Und seine Zeit zum Sterben ist gekommen.\n\nAlte Knochen knirschen, wenn er seinen gewaltigen Leib durch den Sumpf schleppt, und auch wenn er sich noch mit der Kraft und dem Tempo der Jugend bewegt, martert sein alter Körper den großen innewohnenden Geist, ein Geist, dessen Flamme nicht erlischt.\n\nHeutzutage jedoch leidet er unablässig qualvolle Schmerzen. Ihr müsst das Leben dieser edlen Kreatur beenden, <Name>. Ihr müsst Schlammwühler Frieden geben.", progress = "Habt Ihr den Zahn von Schlammwühler, <Name>? Habt Ihr das Leiden der Kreatur beendet?", completion = "Sehr gut, &lt;Name&gt;.\n\nIch bin sicher, die Jagd war nicht leicht, aber es ist gut zu wissen, dass der Schmerz des Tieres ein Ende gefunden hat.", rewards = "Ihr bekommt:\n\n"},
[1206] = {title = "Jarl braucht Augen", objective = "Bringt 40 unzerplatzte Graunebelaugen zu \"Sumpfauge\" Jarl im Swamplight-Anwesen.", description = "Augensaft ist ein guter Saft zum Trinken. Leider haben die meisten Tierwesen nur zwei Augen.\n\nAber Spinnen haben eine Menge Augen. Jede Menge. Und Graunebelaugensaft ist lecker. Samtig und salzig! Unzerplatzte Spinnenaugen... Ich schmecke sie schon förmlich.\n\nGraunebelspinnen leben westlich von hier in den Graunebelhöhlen. Glaubt Ihr, die Spinnen wurden nach der Höhle benannt... oder ist es umgekehrt?", progress = "Wo sind diese Augen?", completion = "Ihr habt die Augen! Ihr habt die Augen! Leckere, leckere Spinnenaugen!\n\nSchöne Augen... wenn man sie anstarrt, starren sie zurück. Die ess ich zuletzt. Sie leisten einem Gesellschaft... draußen im Sumpf.\n\nHallo, kleine Spinnenaugen. Hallo! Ihr seid so lecker wie Hühnchen. Glibberiges, salziges Hühnchen!\n\nMmmh.", rewards = "Ihr bekommt:\n\n"},
[1218] = {title = "Feine Gewürze", objective = "Bringt 3 feine Gewürze zu \"Sumpfauge\" Jarl in den Dustwallow-Marschen.", description = "Ich koche gern. Leckere Sumpfküche. Frittierte grüne Froschschenkel und dergleichen.\n\nUnd zum Kochen brauch ich Gewürze. Feine Gewürze. Dann mache ich einen Eintopf und topfe ihn ein und schlabber ihn aus und geb Euch auch was ab.\n\nMögt Ihr Eintopf?", progress = "Gewürz. Wir könnten alle etwas Würze in unserem Leben brauchen. Meint Ihr nicht auch?", completion = "Ah, das ist ein Gewürz! Also, hier haben wir den leckeren sumpfigen Eintopf.", rewards = "Ihr bekommt:\n\nFroschschenkeleintopf"},
[1219] = {title = "Der Orc-Bericht", objective = "Bringt den Bericht des Spions zu einem Lieutenant in Theramore.", description = "Beim Durchsuchen der lockeren Erde wird die abgetrennte Hand eines Orcs gefunden. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.\n\nDas Pergament ist in der Sprache der Orcs verfasst... und sieht wichtig aus.", progress = "Habt Ihr Bericht zu erstatten?", completion = "Hm... Ich kann die Sprache der Orcs nicht sehr gut lesen, aber es scheint ein wichtiger Bericht zu sein... von einem Orc-Spion geschrieben!", rewards = "Ihr bekommt:\n\n"},
[1220] = {title = "Captain Mumm", objective = "Bringt den Bericht des Spions zu Captain Garran Mumm.", description = "Captain Mumm sollte den Orcbericht sehen, den Ihr gefunden habt, <Name>. Er kennt die Sprache der Orcs besser als die meisten. Und er sollte wissen, dass sich Spione der Horde bei Theramore aufhalten!\n\nDer Captain befindet sich in der Kaserne auf der nordöstlichen Seite der Insel Theramore.", progress = "Habt Ihr etwas für mich?", completion = "Ein Bericht von einem Orc-Spion! Wie habt Ihr den gefunden? Egal - mal sehen, was drin steht...", rewards = "Ihr bekommt:\n\n"},
[1221] = {title = "Blaulaubknollen", objective = "Schnappt Euch eine Kiste mit Löchern.\nSchnappt Euch einen Schnüffelnasenleitstecken.\nSchnappt Euch das Handbuch für Schnüffelnasenbesitzer und lest es.\n\nBenutzt im Kral von Razorfen die Kiste mit Löchern, um ein Schnüffelnasenziesel zu beschwören, und benutzt den Leitstecken bei dem Ziesel, damit es nach Knollen sucht.\n\nBringt 6 Blaulaubknollen, den Schnüffelnasenleitstecken und die Kiste mit Löchern zu Mebok Mizzyrix in Ratchet.", description = "Blaulaubknollen gelten auf der ganzen Welt als Delikatesse! Aber sie sind rar, sehr rar. Man findet sie nur hier im Brachland, tief in der Erde des Krals von Razorfen.\n\nUnd selbst dann sind sie fast nicht zu finden, wenn man nicht weiß, wo man suchen muss! Darum habe ich diese Schnüffelnasenziesel abgerichtet, damit sie sie für mich aufstöbern. Sie haben unheimlich empfindliche Nasen und riechen eine Knolle aus fünfzig Schritt Entfernung.\n\nEs wird nicht einfach sein, aber wenn Ihr mir ein paar Knollen bringt, bezahle ich Euch gut dafür.", progress = "Habt Ihr die Knollen, <Name>?", completion = "Prima, Ihr habt sie! Die kann ich meinen Verbindungsleuten für einen satten Preis verkaufen!\n\nDanke für die Lieferung, &lt;Name&gt;! Ihr seid ein toller Partner.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nEin kleiner Behälter mit Edelsteinen"},
[1222] = {title = "Stinkis Flucht", objective = "Begleitet \"Stinki\" Ignatz und sprecht dann mit Morgan Stern in Theramore.", description = "Klasse, endlich etwas, das mich nicht essen möchte!\n\nIch brauche Hilfe mit den Tierwesen hier, und Ihr kommt gerade recht, <Jungchen/Lady>.\n\nDer Koch Morgan Stern arbeitet an einem neuen Rezept und hat mich hierher geschickt, um Sumpfbohnenblätter zu sammeln. Ich glaube, er findet sie lecker.\n\nWie auch immer, während ich nach einer Sumpfbohnenpflanze suchte ... Wurde ich umzingelt! Könnt Ihr mir hier raus helfen und auf mich aufpassen, während ich nach den Sumpfbohnen suche?", progress = nil, completion = "Mr. Ignatz war gerade mit den Sumpfbohnenblättern hier und sagte mir, dass Ihr ihm echt aus der Klemme geholfen habt.\n\nDanke, &lt;Name&gt;. Ich werde meinen Onkel bitten, dass er Euch ein Festmahl bereitet, wenn Ihr das nächste Mal den Blauen Eremiten in Stormwind besucht.", rewards = "Ihr bekommt:\n\nElixier der Seelenstärke"},
[1238] = {title = "Der verlorene Bericht", objective = "Bringt den Bericht des Spions zu Nazeer Bloodpike in Brackenwall.", description = "Beim Durchsuchen der lockeren Erde wird die abgetrennte Hand eines Orcs gefunden. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.\n\nDas Pergament ist ein Bericht von einem Orc, der die Stadt Theramore über Wochen ausspionierte.\n\nAls Ihr das Pergament überflogen habt, ist klar, dass es zum Orc-Spionagemeister in Brackenwall gebracht werden muss.", progress = "Habt Ihr etwas für mich?", completion = "Gute Arbeit, &lt;Name&gt; . Unser Agent Marg Nighteye war außerhalb von Theramore stationiert. Seine Aufgabe war es, die Stadt auszuspionieren. \n\nDas ist sein jüngster Bericht und könnte sein letzter sein; nach Eurer Aussage fürchte ich, dass Marg im Sumpf sein Ende fand...", rewards = "Ihr bekommt:\n\n"},
[1239] = {title = "Der abgetrennte Kopf", objective = "Bringt den Kopf des aufsässigen Orcs zu Nazeer Bloodpike in Brackenwall.", description = "Ausgiebiges Graben fördert den Kopf eines männlichen Orcs zu Tage, der am Hals abgesägt worden war. Seine Lippen sind zu einer höhnischen Grimasse verzerrt, seine dunklen Augen blicken trotzig.", progress = "Habt ihr noch etwas zu berichten, <Name>?", completion = "Dies ist der Kopf von Marg Nighteye! Er ist tot, wie ich befürchtete.\n\nSeht euch die Wunde an seinem Hals an! Kann eine Waffe diesen ausgefransten Schnitt gemacht haben, oder wurde unser Agent von einer Bestie angefallen?\n\nDas ist ein Rätsel, das wir lösen müssen, &lt;Name&gt;! Wir müssen herausfinden, ob Marg durch die Hände der Allianz starb!", rewards = "Ihr bekommt:\n\n"},
[1240] = {title = "Der Troll-Hexendoktor", objective = "Bringt den Kopf des aufsässigen Orcs zu Kin'weelay im Schlingendorntal im Basislager von Grom'gol.", description = "Wir müssen die Umstände von Margs Tod erfahren! Und das können wir nur, <Name>, durch die Hexenmagie der Trolle.\n\nBringt Margs Kopf zu Kin'weelay im Schlingendorntal im Basislager von Grom'gol.\n\nKin'weelay ist der mächtigste Hexendoktor der Darkspeartrolle. Wenn jemand mit Marg Nighteyes Geist sprechen kann, dann er.", progress = "Ihr habt einen wütenden Geist um Euch, Bruder. Was führt Euch zu Kin'weelay?", completion = "Ah, jetzt verstehe ich. Der Geist dieses Orcs ist an unsere Welt gebunden und kocht vor Wut über eine nicht erledigte Aufgabe.\n\nDann reden wir einmal mit diesem wütenden Orc...", rewards = "Ihr bekommt:\n\n"},
[1241] = {title = "Der vermisste Diplomat", objective = "Sucht Jorgen in der Stadt Stormwind.", description = "Kürzlich wurde ein Diplomat nach Theramore geschickt, um sich mit Jaina Proudmoore zu treffen. Dieser Diplomat kam nie an.\n\nIch glaube, die Defias sind in diese Verschwörung verwickelt, weiß aber nicht, wie. Das Verschwinden des Diplomaten wurde noch nicht publik, aber lange kann das nicht mehr so bleiben.\n\nAgenten des Königs durchkämmen die Stadt bereits nach Hinweisen, aber ich habe eigene Verbindungsleute, die ich gern einschalten würde.\n\nIm Tal der Helden lebt ein alter Freund von mir namens Jorgen. Sucht ihn, gebt ihm diese Notiz und folgt seinen Anweisungen.", progress = "Hmpf, hoffentlich habt Ihr einen guten Grund, einen Mann beim Angeln zu stören. Ich reagiere ungehalten auf Schnüffler, von Bettlern ganz zu schweigen.", completion = "Hmm... &lt;Jorgen schaut mit zusammengekniffenen Augen zu Euch auf.&gt;\n\nNun gut. Ich helfe Euch, aber nicht, weil ich es will, sondern weil ich verpflichtet bin.\n\nUnd lasst uns eines klarstellen: Ihr wisst viel mehr als Ihr eigentlich solltet. Betrachten wir dies als unser kleines Geheimnis. Plappert nicht in irgendwelchen Tavernen über das, was Ihr herausfindet. Kapiert?", rewards = "Ihr bekommt:\n\n"},
[1242] = {title = "Der vermisste Diplomat", objective = "Bringt Jorgens versiegelte Notiz zu Elling Trias in der Stadt Stormwind.", description = "Bringt diese Notiz zu Elling Trias. Sagt sonst nichts zu ihm. Seid nur höflich und wartet auf seine Antwort. Und keine Bange, er wird antworten.\n\nIch sage Euch das nur noch einmal, <Name>: nehmt diese Sache ernst und haltet die Klappe.\n\nIhr findet Trias in seinem Käseladen, Trias' Käse, im Handelsdistrikt. Viel Glück.", progress = "Hallo, <Name>. Kann ich etwas für Euch tun? Vielleicht würdet Ihr gern unseren speziellen Trias-Cheddar kosten? Oder ein Stück Darnassus-Blauschimmelkäse?", completion = "Pardon, ein Brief für mich? Also da soll mich doch... wenn man arbeitet, bekommt man nicht oft eine Zustellung, die keine Kiste oder ein Fass ist. Mal sehen, worum es geht.\n\n&lt;Elling schaut zu Euch auf, während er den Brief öffnet.&gt;\n\nIhr seht ein wenig nervös aus, alles klar, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"},
[1243] = {title = "Der vermisste Diplomat", objective = "Gebt Behüter Backus im Dämmerwald die versiegelte Notiz.", description = "Jorgen, alter Pickel! Aha, so soll es also sein, hm?\n\nNa gut, damit kann ich leben. Ich hoffe, er findet den wirbelnden Nether umso früher!\n\nSo wird es ablaufen, <Name>. Ich werde meine Verbindungsleute hier kontaktieren, aber Ihr werdet den Großteil der Beinarbeit erledigen, damit ich ein wenig spare.\n\nGeht nach Dunkelhain im Dämmerwald und sucht Behüter Backus - er patrouilliert meist auf der Nordstraße vor der Stadt. Sagt ihm nur, dass Ihr für mich die Aktivitäten der Defias untersucht, dann wird er Euch mit allen verfügbaren Informationen weiterhelfen.", progress = "Es ist nicht eben sicher, durch den Wald zu reisen, <Name>. Seid vorsichtig, und wenn Ihr etwas Verdächtiges oder Seltsames seht, meldet es sofort den Behütern. Versucht nicht, auf eigene Faust zu handeln. Wir tragen keine Verantwortung, wenn Euch etwas Schreckliches zustößt.\n\nAber wir wissen beide, dass Ihr nicht auf meine Worte hören und gegen alles kämpfen werdet, was aus der Dunkelheit kommt, nicht? Haha, ja, ihr Abenteurer-Typen ... ihr seid alle gleich.", completion = "Oh, Trias schickt Euch, hm? Das ist etwas anderes.\n\nDann könnt Ihr gegen alle Monster kämpfen, die aus der Dunkelheit kommen mögen. Ich bin sicher, Ihr werdet leicht damit fertig, wenn Ihr der Typ seid, der gern mit seinesgleichen herumhängt.\n\nAlso, was braucht mein Freund an einem so düsteren Tag wie diesem?", rewards = "Ihr bekommt:\n\n"},
[1244] = {title = "Der vermisste Diplomat", objective = "Sucht die Liste der Defias und kehrt zu Behüter Backus im Dämmerwald zurück.", description = "Defiasaktivität? Es gibt immer etwas Aktivität; selbst wenn sie unter sich bleiben, betrachten wir sie als Bedrohung.\n\nAber jetzt, wo ich darüber nachdenke, kam es jüngst zu einer seltsamen Beobachtung. Es muss so zwei Wochen her sein, da hatten sich einige ihrer Agenten in Addles Siedlung versammelt. Dem Bericht glaubte ich zu entnehmen, dass etwas Großes vor sich ging.\n\nWarum seht Ihr da nicht zuerst nach und bringt mir alles, was Ihr findet?\n\nDer Bauernhof liegt südlich der Straße von Westfall direkt am Rand des Dämmerwalds.", progress = "Seid vorsichtig da draußen, <Name>. Ich weiß, dass Trias Euch hergeschickt hat, aber das bedeutet nicht, dass es da draußen im Wald nichts gibt, das Euch Ärger machen könnte... besonders wenn Ihr die Defias untersucht.", completion = "Ihr seid heil und gesund zurück. Mehr konntet Ihr nicht verlangen, meint Ihr nicht auch?\n\nDann sehen wir mal, was wir hier haben. Das sieht ziemlich offiziell aus, wenn mich meine Erfahrung mit Defiasdokumenten nicht trügt. Es könnte jedoch auch eine Finte sein, um Euch von der Fährte abzubringen, auf die Ihr bei Eurer Suche gestoßen seid.", rewards = "Ihr bekommt:\n\n"},
[1245] = {title = "Der vermisste Diplomat", objective = "Bringt die Liste der Defias zu Elling Trias in Stormwind.", description = "Boah, das sieht zu komplex aus, um Euch nur auf eine falsche Fährte zu locken. Ich sollte das nicht einmal ansehen. Sprecht mit Trias - er kann es bestimmt verstehen. Und lasst Euch durch NICHTS aufhalten. Dies ist größer als ich. Vielleicht sogar größer als er, aber wir werden sehen.\n\nUnd tut mir einen Gefallen, <Name>, sagt keinem, dass ich Euch geholfen habe. Wenn meine Vorgesetzten erfahren, dass ich davon wusste und sie nicht informiert habe, hängen sie mich wahrscheinlich.", progress = "Ich sehe, Ihr seid in einem Stück zurück. Wir wissen beide, dass Ihr nicht wegen Käse hier seid, beenden wir also das Plaudern. Konnte Backus Euch helfen oder seid Ihr noch gar nicht im Dämmerwald gewesen?", completion = "Ja... das ist interessant zu lesen. Jorgen und DeLavey waren klug, mich einzuweihen.\n\nOffenbar haben sich die Defias sehr bemüht, ihren Plan hier abzuschließen. Hmm... was ist das? \"Fist\"? Das ist ein vertrauter Name.", rewards = "Ihr bekommt:\n\n"},
[1246] = {title = "Der vermisste Diplomat", objective = "Sprecht mit Dashel Stonefist in Stormwind.", description = "Ja, jetzt, wo ich darüber nachdenke... Dashel... Dashel irgendwas... Wie war sein Name? FIST! Dashel Stonefist. In manchen Kreisen nennen sie ihn Fist - wahrscheinlich, weil er ein Raufbold ist.\n\nIhr könnt ihn normalerweise in der Altstadt finden - direkt mitten im Zentrum. Redet mit ihm. Wenn es sein muss, dann benutzt ein Schwert oder etwas Schweres und Stumpfes, um ihn zum Reden zu bringen. Und zögert nicht. Wenn er so tief drinsteckt, wie diese Papiere andeuten, wird er Euch freiwillig keine Informationen geben.", progress = nil, completion = "Was?!\n\nIhr kommt in meine Gasse und stellt Fragen nach meinen persönlichen Angelegenheiten? Angelegenheiten, mit denen Ihr offenkundig nichts zu tun habt.", rewards = "Ihr bekommt:\n\n"},
[1247] = {title = "Der vermisste Diplomat", objective = "Sprecht mit Elling Trias in Stormwind.", description = "Ja, also... hm... Vielleicht weiß ich was über dieses Treffen in Addles Siedlung. Das war, glaube ich, vor ein paar Wochen. Ich hatte wirklich nichts damit zu tun. Meine Rolle war vorbei, als Plan A schief ging... verdammte Abenteurer.\n\nDer Kerl, den wir für Plan B hatten, kam aus Menethil; ein Typ namens Slim. Mehr weiß ich nicht über ihren Ersatzplan.", progress = nil, completion = "Wie schön, dass Ihr noch am Leben seid, &lt;Name&gt; . Mit Dashel lief demnach alles gut, hm?\n\nIch habe mehr über ihren Plan nachgelesen. Der Name des Diplomaten, auf den sie es abgesehen hatten, wurde zwar nicht genannt, aber es ist von einem Plan B die Rede, der zur Ausführung kam, nachdem der erste Versuch, ihn zu entführen, gescheitert war.\n\nDieser Slim, von dem Dashel sprach, hat hier keinen anderen Namen angegeben, aber wenn Ihr sagt, dass er in Menethil ist, ist das ein Anfang.", rewards = "Ihr bekommt:\n\n"},
[1248] = {title = "Der vermisste Diplomat", objective = "Sprecht mit Mikhail im Sumpfland.", description = "Ein Verbindungsmann von mir verbringt seinen Ruhestand in der Hafenstadt Menethil im Sumpfland. Er sollte Euch auf Euer Wort hin helfen, wenn Ihr ihm sagt, dass Ihr für mich arbeitet. Sein Name ist Mikhail. Bevor er Stormwind vor ein paar Jahren verließ, erwähnte er, dass er Schankkellner werden wollte.\n\nSprecht mit ihm, sucht diesen Slim und findet heraus, ob es noch etwas über diesen entführten Diplomaten zu wissen gibt. Wir müssen herausfinden, wohin sie ihn gebracht haben, oder wenigstens, wer er ist. In der Liste steht nichts von ihren Plänen nach seiner Entführung.", progress = nil, completion = "Willkommen, willkommen, willkommen, &lt;Name&gt;. Schön, dass Ihr Euch uns anschließt. Vielleicht heute ein kühles Bier. Oder etwas Hammel?\n\nNennt mir Euren Wunsch und ich sorge dafür, dass er erfüllt wird. Mein Name ist Mikhail und ich freue mich darauf, Euch zu bedienen.\n\nHmm? Wie war das? Trias? So sprecht doch leiser. Es soll doch nicht die ganze Taverne davon hören.", rewards = "Ihr bekommt:\n\n"},
[1249] = {title = "Der vermisste Diplomat", objective = "Schnappt Tapoke Jahn bevor er entkommt und kehrt dann zu Mikhail in Menethil zurück.", description = "Ihr sagt, Elling hat Euch geschickt? Dann soll Euch meine Gastfreundschaft zehnfach zuteil werden. Wenn Ihr etwas braucht, fragt nur. Ich tue mein Bestes, Euch zu unterstützen.\n\nHmm, Slim sagt Ihr? Bei dem Namen klingelt nichts, aber ich werde nach ihm Ausschau halten.\n\nSchaut jetzt nicht hin, <Name>, aber der Herr dort am Ausgang sieht herüber. Er folgt unserer Unterhaltung etwas zu intensiv, wenn Ihr versteht, was ich meine. Ich an Eurer Stelle würde tun, was ich kann, um ihn zu schnappen, bevor er zur Tür flieht.", progress = "Ist er entronnen? Sah ein wenig zwielichtig aus, wie er uns beobachtet hat.", completion = "Habt ihn erwischt, hm? Gut für Euch. Ich bin überrascht, dass das Slim war.\n\nIch will ehrlich sein, ich hätte nie gedacht, dass ich die Aufregung der unaufrichtigen Untergrundaktivitäten vermissen würde. Alte Gewohnheiten wird man wohl nicht so leicht los. Aber sagt Elling nichts davon - wenn er hört, dass mir die Aufregung fehlt, versucht er wahrscheinlich, mich wieder nach Stormwind zu locken.\n\nIch bin froh, dass ich Euch in Menethil wenigstens ein wenig zu Diensten sein konnte. Wenn Ihr noch etwas braucht, fragt nur.", rewards = "Ihr bekommt:\n\n"},
[1250] = {title = "Der vermisste Diplomat", objective = "Sprecht mit Mikhail im Sumpfland.", description = "Die Defias zahlten mir nicht genug, um für diese Sache zu sterben. Sie entführten den König. Ja, den König von Stormwind, keinen kleinen Diplomaten. Er war auf dem Weg nach Theramore, um sich mit Jaina Proudmoore zu treffen - offenbar eine große Sache und streng geheim. Aber es sind nicht nur die Defias darin verwickelt. Sie arbeiten mit jemandem zusammen. Ich glaube, sie wussten, dass das ihre Kräfte übersteigt.\n\nMeine Aufgabe war es, ihren Mann an Bord des königlichen Schiffes zu bringen, als es im Hafen lag. Der Typ hieß Hendel. Mehr weiß ich nicht. Ich schwöre es!", progress = nil, completion = "DER KÖNIG?! Ich meine... der König? Der echte König? Ist das ein Witz? Ihr habt nicht erwähnt, dass Ihr die Entführer des Königs sucht. Ich habe nicht einmal gehört, dass er vermisst wird - das würde erklären, warum bald sein Sohn gekrönt wird.\n\nIch werde Elling sofort informieren. Er sollte wissen, dass Ihr die Spur verfolgt.\n\nIch hätte nie gedacht, dass Jahn Stormwind nur des Geldes wegen verkaufen würde. In manchen Dingen muss doch selbst ein Schurke Ehrgefühl besitzen.\n\nJetzt ist es entscheidend, diesen Hendel zu finden. Und ich denke, da kann ich Euch helfen.", rewards = "Ihr bekommt:\n\n"},
[1251] = {title = "Der Schwarze Schild", objective = "Bringt den geschwärzten Eisenschild zu Krog in Brackenwall.", description = "Ein Eisenschild, vom Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus Zur süßen Ruh war.\n\nDer Schild lässt sich von den Mauersteinen des Kamins ablösen.", progress = "Was habt Ihr denn da, <Name>? Beweismittel aus den Trümmern des Gasthauses Zur süßen Ruh?", completion = "Ich gebe ja zu, dass Menschen einen merkwürdigen Geschmack bei der Dekoration haben, aber würden sie einen einfachen Eisenschild benutzen, um ihren Feuerplatz zu schmücken? Vielleicht haben jene, die das Gasthaus niederbrannten, den Schild dort befestigt.\n\nEine Warnung? Eine Drohung?", rewards = "Ihr bekommt:\n\n"},
[1252] = {title = "Lieutenant Paval Reethe", objective = "Bringt Reethes Abzeichen zu Captain Garran Mumm in Theramore.", description = "Unter dem Geröll sticht Euch ein Funkeln ins Auge. Kaum sind Schmutz und Asche von dem Objekt gewischt, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.\n\nUnter dem Anker ist der Name \"Lieutenant Paval Reethe\" eingeprägt.", progress = "Habt Ihr etwas Interessantes im Gasthaus Zur süßen Ruh gefunden?", completion = "Es bedeutet selten etwas Gutes, wenn mir das Abzeichen einer Wache gebracht wird.\n\nManchmal bedeutet es, dass ein Mann oder eine Frau im Kampf gefallen ist und ich der trauernden Familie die Nachricht überbringen muss. Manchmal erfahren wir nie, was ihnen zugestoßen ist. Und manchmal ist es sogar noch schlimmer.", rewards = "Ihr bekommt:\n\n"},
[1253] = {title = "Der Schwarze Schild", objective = "Bringt den geschwärzten Eisenschild zu Captain Garran Mumm in Theramore.", description = "Ein Eisenschild, vom Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus Zur süßen Ruh war.\n\nDer Schild lässt sich von den Mauersteinen des Kamins ablösen.", progress = "Habt Ihr Beweise im ehemaligen Gasthaus Zur süßen Ruh gefunden?", completion = "Hm, ich bin kein Experte für die Herstellung von Waffen und Rüstungen. Für ihre Anwendung, ja, aber nicht für die Herstellung.\n\nDer Schild scheint ganz gewöhnlich wie jeder andere zu sein, abgesehen vom Schaden durch das Feuer, das das Gasthaus verwüstete.", rewards = "Ihr bekommt:\n\n"},
[1258] = {title = "...und Käfer", objective = "Bringt 12 makellose Kriecherbeine zu Morgan Stern in Theramore.", description = "Eine weitere Komponente meines neuen Rezepts ist das gepanzerte Bein eines Riesenkrebses. Und die Krebse, die sie in Dustwallow haben - Matschpanzer nennen sie sie -, taugen einfach nichts! Ich fürchte, die einzigen akzeptablen Krebse leben in den Sümpfen des Elends.\n\nDie Schale des Krebsbeins ist das wichtigste Element der Präsentation des Gerichts, daher brauche ich makellose, unverletzte Beine. Ein ausgewachsener Krebs hat möglicherweise nur ein oder zwei Beine, die in Frage kommen, aber ich brauche viel mehr für mein Gericht.\n\nAlso, <Name> ... seid Ihr bereit für eine Reise?", progress = "Meine Experimente mit den Schlammpanzerzungen machen gute Fortschritte. Ich hoffe, Eure Krebssuche kommt voran?", completion = "Das sind wunderbare Exemplare, &lt;Name&gt;! Die Schalen sind in perfektem Zustand, das Fleisch ist rosa und zart. Ich bin sicher, das Blut eines Küchenchefs fließt in Euren Adern!", rewards = "Ihr bekommt:\n\nBarocke Schürze"},
[1259] = {title = "Lieutenant Paval Reethe", objective = "Findet bei Adjudant Tesoran in Theramore mehr über Reethe heraus.", description = "Ich kenne den Namen Lieutenant Paval Reethe nicht. Am besten erkundigt Ihr Euch bei Adjudant Tesoran. Er hat alle Aufzeichnungen über die Wachen von Theramore, vom Personal bis hin zur Ausrüstung.\n\nEr sollte Euch nach einem Blick in seine Bücher sagen können, wer dieser Reethe ist.", progress = nil, completion = "Hallo, &lt;Name&gt;. Ihr möchtet Informationen über ein bestimmtes Mitglied der Wache von Theramore? Reethe, richtig?\n\nBitte habt einen Moment Geduld, bis ich das richtige Buch gefunden habe.", rewards = "Ihr bekommt:\n\n"},
[1260] = {title = "Morgan Stern", objective = "Sprecht mit Morgan Stern in Theramore.", description = "Ich entwickle ein neues Menü für das Restaurant. Es soll aus regionalen Gerichten mit einem Hauch von \"Bayou\" bestehen. Ich glaube, meine Kunden im Blauen Eremiten werden es lieben!\n\nIch schickte meinen Neffen Morgan nach Theramore, einer Stadt am Rand der Dustwallow-Marschen. Er sammelt die Rezepte der Einheimischen und ich muss wissen, was er bisher gefunden hat.\n\nDie Reise nach Theramore ist lang. Zu lang für mich. Aber ich wette, ein <Klasse> wie Ihr einer seid, nutzt jede Chance für eine Reise, ja?", progress = nil, completion = "Oh, mein Onkel hat Euch geschickt, nicht?\n\nIch habe mich um die Rezepte gekümmert und ein paar Hinweise, aber ich brauche Hilfe.\n\nHilfe von jemandem, der keine Angst vor nassen Füßen hat.", rewards = "Ihr bekommt:\n\n"},
[1261] = {title = "Marg spricht", objective = "Bringt den juwelenbesetzten Anhänger zu Nazeer in Brackenwall.", description = "Verfluchter Matschpanzer! Man kann Marg nicht töten! Ah, aber ich bin tot. Also muss er mich getötet haben...\n\nAber meine Mission! Meine Mission! Ihr, <Name>, müsst sie beenden.\n\nIn der Nähe von Theramore sah ich eine Gruppe Soldaten der Allianz am Ufer kampieren. Ein Soldat trug einen Anhänger... einen Anhänger mit mehr Edelsteinen, als ihn sich ein Soldat leisten könnte!\n\nIn jener Nacht schlich ich in ihr Lager und stahl den Anhänger, aber nach meiner Rückkehr zum Stützpunkt tötete mich ein Matschpanzerkrebsmann!\n\n<Name>, Ihr müsst diesen Matschpanzer finden und den Anhänger retten!", progress = "<Name>, habt Ihr etwas über Margs Schicksal erfahren?", completion = "Dieser Anhänger wurde von einem Soldat aus Stormwind getragen???\n\nDanke, &lt;Name&gt;. Ihr habt die Umstände von Margs Tod enträtselt! Doch dieser Anhänger ist ein neues Rätsel, das es zu lösen gilt, und es könnte schlimme Auswirkungen auf die Allianz und die Horde haben.", rewards = "Ihr bekommt:\n\n"},
[1262] = {title = "Bei Zor melden", objective = "Bringt den Edelstein-Anhänger zu Zor Lonetree in Orgrimmar.", description = "Wie seltsam, dass sich der Anhänger, den Marg stahl, in den Händen eines gemeinen Soldaten befand. Vielleicht hatte sich sein Besitzer verkleidet, oder die Soldaten selbst hatten ihn gestohlen!\n\nWas auch immer, dies ist der Anhänger eines Adligen und wir müssen seinen wahren Besitzer finden, wenn wir das Rätsel lösen wollen.\n\nBringt den Anhänger zu Zor Lonetree in Orgrimmar. Er ist mit der Politik der Allianz vertraut und wird wissen, ob dieser Anhänger etwas mit der Geschichte der Adligen von Stormwind zu tun hat.", progress = "Ihr seid von Brackenwall in Dustwallow hierher gereist? Wie geht es Nazeer und wie weit sind seine Bemühungen im Sumpf gediehen?", completion = "Dieser Anhänger wurde mit großem Geschick und Präzision gefertigt, &lt;Name&gt;. Kein Orc würde so ein Schmuckstück begehren...\n\nAber viele Menschen könnten es.\n\nIch werde diesen Anhänger untersuchen lassen. Hoffen wir, dass er uns bald seine Geheimnisse preisgibt...", rewards = "Ihr bekommt:\n\n"},
[1263] = {title = "Das brennende Gasthaus <ZU TRATSCH WECHSELN>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1264] = {title = "Der vermisste Diplomat", objective = "Sucht Kommandant Samaul in den Marschen von Dustwallow.", description = "Am Anfang jedes Monats werden die Marines von Kul Tiras bezahlt und verlassen Theramore meist mit anderen Zielen. Viele kommen hierher, um Frauen aufzureißen, zu zechen und ihren Spaß zu haben. Eine dieser Gruppen betrachte ich als Stammgäste der Taverne, und ich glaube, dieser Hendel ist dabei.\n\nKommandant Samaul in Theramore könnte Euch helfen, ihn zu finden, wenn Hendel noch hier stationiert ist. Er ist Proudmoore treu ergeben, aber wenn Ihr Ellings Namen erwähnt, dürfte er Euch helfen... diskret.", progress = nil, completion = "Welche Freude, Euch zu sehen, &lt;Name&gt;. Ich bin Kommandant Samaul. Ich kommandiere Miss Proudmoores Truppen hier in Theramore.\n\nZur Zeit bin ich zwar ziemlich beschäftigt, aber falls Ihr irgendwelche Fragen habt, sprecht mich ruhig an. Möglicherweise muss ich es kurz machen, aber ich will Euch gern helfen, wenn Ihr Hilfe braucht.\n\nFalls Ihr vorhabt, die Stadt zu verlassen, rate ich Euch, vorsichtig zu sein. Abgesehen von Ogern, Orcs und Murlocs wimmelt es im südlichen Teil des Sumpfs von schwarzen Großdrachen.", rewards = "Ihr bekommt:\n\n"},
[1265] = {title = "Der vermisste Diplomat", objective = "Sucht die Späherwacht nach Spuren des Gefreiten Hendel ab.", description = "Hendel? Ja, ich kenne den Mann. Aber wozu braucht Ihr einen meiner Soldaten?\n\nHat Elling Euch geschickt, ihn zu finden? Hmm, das gefällt mir ganz und gar nicht. Elling hätte Euch nicht zuerst zu mir geschickt, wenn Euer Anliegen nicht beunruhigend wäre. Ich verstehe, wenn Ihr mir nicht sagen könnt, worum es geht, aber denkt daran: Ich muss dieses Land beschützen. Wenn Ihr vorhabt, die Ruhe zu stören, solltet Ihr mich so viel wie möglich wissen lassen.\n\nIch glaube, Hendel war im ersten Turm außerhalb von Theramore stationiert. Seid vorsichtig.", progress = nil, completion = "Der Mann namens Hendel, den Ihr sucht, ist nicht hier. Andere Quellen lieferten Lady Proudmoore Informationen, die Ihr wohl bereits kennt. Sie bat mich, Euch zu suchen und bei Eurer Mission zu unterstützen. Wenn Ihr gestattet, sage ich Euch, wo Ihr den Gefreiten Hendel finden könnt, damit er seine gerechte Strafe erhält.", rewards = "Ihr bekommt:\n\n"},
[1266] = {title = "Der vermisste Diplomat", objective = "Sucht den Gefreiten Hendel in den Marschen von Dustwallow.", description = "Der Gefreite Hendel hält sich westlich von hier auf. Im Augenblick ist er auf Wache und beschützt einige von Theramores Spitzeln, während sie ausruhen. Sie behalten Brackenwall, den Stützpunkt der Horde, im Auge und suchen nach allem, das unsere Grenzen bedrohen könnte.\n\nIhr müsstet ihn problemlos finden können; sucht einfach nach Zelten am Straßenrand.\n\nIch muss mich um andere Dinge kümmern, stoße aber bestimmt bald zu Euch. Ihr könnt mich immer im Turm von Lady Proudmoore in Theramore finden, falls Ihr Probleme habt.", progress = nil, completion = "Seid gegrüßt. Dies ist ein gefährlicher Ort für einen Spaziergang. Ich würde nicht zu lange bleiben, wenn Euch Euer Leben lieb ist.\n\nWenn Ihr Euch auf kurze Fragen beschränkt, will ich sehen, ob ich Euch helfen kann. Haltet nur nach diesen schmutzigen Ogern Ausschau. Gerüchten zufolge gibt es einen Stützpunkt der Horde in den Sümpfen. Die Spitzel tun, was sie können, um ihn zu finden, aber das ist eine langwierige Angelegenheit und wir kommen nicht voran.", rewards = "Ihr bekommt:\n\n"},
[1267] = {title = "Der vermisste Diplomat", objective = "Sprecht mit Jaina Proudmore im Dustwallowsumpf.", description = nil, progress = nil, completion = "Ich möchte der Erste sein, der Euch für all das dankt, was Ihr geleistet habt, &lt;Name&gt;. Erneut wart Ihr ein unglaublicher Segen für mein Volk und die Bewohner von Stormwind. Es tut mir Leid, dass wir uns nicht unter glücklicheren Umständen kennen gelernt haben.\n\nVersteht bitte auch, dass ich Euch nicht offen für Eure Bemühungen danken kann, aber ich möchte Euch nochmals versichern, dass ich sie wohl zu schätzen weiß.\n\nWenn Ihr in Zukunft einmal nach Theramore kommt, schaut unbedingt bei mir herein, dann werde ich versuchen, Euch über die Lage auf dem Laufenden zu halten.\n\nNochmals danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nJainas Siegelring"},
[1268] = {title = "Verdächtige Hufabdrücke", objective = "Berichtet Krog in Brackenwall von den verdächtigen Abdrücken beim Gasthaus Zur süßen Ruh.", description = "Reihen von Hufspuren führen von den noch rauchenden Überresten des Gasthauses Zur süßen Ruh weg. Wenigstens einige Abdrücke sind klar erkennbar, weitere Reihen sind im weichen Schlamm des Sumpfs kaum zu sehen.", progress = nil, completion = "Hufabdrücke... Ich schätze, das könnten die Stacheleber gewesen sein. Oder vielleicht sogar die Zentauren. Sie sind im Brachland durchaus nicht so selten. So eine Tat zu begehen ist für mich kein kleines Delikt.\n\nSagte ich es Euch schon? Nicht nur das Gasthaus war niedergebrannt... Frau und Kind des Besitzers wurden getötet. Das ist eine schlimme Sache.\n\nDennoch werde ich Kagoro schicken, damit er herausfindet, wohin die Spuren führen.", rewards = "Ihr bekommt:\n\n"},
[1269] = {title = "Lieutenant Paval Reethe", objective = "Bringt Reethes Abzeichen zu Krog in Brackenwall.", description = "Unter dem Geröll sticht Euch ein Funkeln ins Auge. Kaum sind Schmutz und Asche von dem Objekt gewischt, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.\n\nUnter dem Anker ist der Name \"Lieutenant Paval Reethe\" eingeprägt.", progress = "Habt Ihr Hinweise gefunden, was im Gasthaus Zur süßen Ruh passiert ist?", completion = "Ich kenne diesen Menschen Paval Reethe. Jämmerlich, selbst für seine Art. Er ließ seine Kameraden im Stich und versteckt sich jetzt im Wald.\n\nIch schicke Gog'ron los, um ihn aufzuspüren. Einige andere vermuten, dass er unsere Vorräte stiehlt. Ich glaube, ich sah Ogron nach Südosten gehen.", rewards = "Ihr bekommt:\n\n"},
[1270] = {title = "Stinkis Flucht", objective = "Begleitet \"Stinki\" Ignatz und sprecht dann mit Mebok Mizzyrix in Ratchet.", description = "Klasse, endlich etwas, das mich nicht essen will!!!\n\nIch brauche Hilfe mit den Tierwesen hier, und Ihr kommt gerade recht, <Jungchen/Mädel>.\n\nEin Goblin aus Ratchet namens Mebok Mizzyrix braucht ein paar Sumpfbohnenblätter für einen Trank oder so... Mir ist ganz ehrlich einerlei, warum - er hat gut bezahlt und ich kenne diesen Sumpf, also bin ich hier.\n\nZu dumm, dass ich umzingelt wurde, bevor ich die Sumpfbohnen fand! Könnt Ihr mir hier raushelfen und auf mich aufpassen, während ich nach Meboks Pflanze suche?", progress = nil, completion = "Stinki war mit den Kräutern hier, die ich wollte, und sagte mir, Ihr habt ihn aus einer misslichen Lage befreit. Gute Arbeit! Ein Freund von Stinki ist ein Freund von mir!\n\nEr bat mich, Euch das zu geben, wenn ich Euch sehen sollte, bevor er wieder nach Süden in die Sümpfe ging.", rewards = "Ihr bekommt:\n\nElixier der Seelenstärke"},
[1271] = {title = "Festmahl im Blauen Eremiten", objective = "Mein Neffe sagte, Ihr habt ihn bei seiner Suche in Dustwallow unterstützt und seinem Assistenten aus der Klemme geholfen. Also wir Sterns halten zusammen und vergessen unsere Freunde nicht!\n\nAlso wascht Eure Hände, <Name>, denn wir geben Euch zu Ehren eine Party!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFeuchtes Handtuch"},
[1272] = {title = "Sucht Reethe <ZU TRATSCH WECHSELN>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1273] = {title = "Befragt Reethe", objective = "Geht mit Ogron und sprecht mit Reethe, dann kehrt zu Krog in Brackenwall zurück.", description = "Es hat lange gedauert, aber ich fand Reethe. Für einen Menschen hatte er sich gut versteckt.\n\nOgron hatte Angst, nach der langen Zeit im Sumpf könnte er verrückt sein. Ihr kommt mit mir, denn wir brauchen Antworten von ihm.", progress = nil, completion = "Hmpf. Es ist gut, dass Reethe nicht mehr im Sumpf herumlungert. Ein Jammer, dass Menschen so empfindlich sind, dass er sich nicht von einer kleinen Pfeilwunde erholen konnte.\n\nScheinbar hat dieser Teil des Rätsels nirgendwohin geführt und wir müssen es anderswo versuchen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAugenschüreisenSchmetter-Schießprügel\n\nIhr bekommt außerdem:\n\n"},
[1274] = {title = "Der vermisste Diplomat", objective = "Sucht Bischof DeLavey in der Burg Stormwind.", description = "Pardon, <werter Herr/holde Dame>. Bischof DeLavey bat mich, Abenteurer zu suchen, die ihm in einer delikaten Angelegenheit helfen könnten.\n\nWenn Ihr so gut sein könntet, heimlich zur Burg Stormwind zu reiten und mit ihm zu sprechen, sobald es Euch genehm ist - er wäre Euch sicherlich für Eure Hilfe dankbar. Und nochmals, bitte seid diskret. Es ist eine wichtige Angelegenheit.", progress = nil, completion = "Hallo, &lt;Name&gt;. Ich bin Bischof DeLavey.\n\nDa Ihr mich nach meinen Angelegenheiten hier in der Burg fragt, hat Euch zweifellos der junge Thomas erfolgreich überredet, unserem Königreich zu helfen. Er verstand es stets meisterlich, meine Bitten zu erfüllen.\n\nIch habe leider keine Zeit für lange Erklärungen, daher fasse ich mich kurz... und bitte behaltet die Angelegenheit für Euch.", rewards = "Ihr bekommt:\n\n"},
[1275] = {title = "Erforschung der Verderbnis", objective = "Gershala Nightwhisper in Auberdine möchte 8 verderbte Hirnstämme.", description = "Törichte Blutelfen spielen mit Dämonenmagie. Wurden sie nicht Zeugen, was mit den Naga und den Satyrn von Kalimdor geschehen ist?\n\nIch fürchte, die Blutelfen werden auf ähnliche Weise deformiert. Azeroth darf kein weiteres Volk abscheulicher Monster hervorbringen.\n\nIch möchte die Hirnstämme der Satyrn und Naga untersuchen, damit ich daraus folgern kann, welches Schicksal die Elfen erwartet. In der Blackfathom-Tiefe, an der Küste von Ashenvale, werdet Ihr sowohl Satyrn als auch Naga finden.\n\nEs ist eine lange Reise, <Name>.", progress = "Wenn ich genügend Proben habe, kann meine wahre Arbeit beginnen. Mit den verderbten Hirnstämmen der Satyrn und Naga der Blackfathom-Tiefe kann ich versuchen, einen Zusammenhang zwischen den Mutationen zu finden.\n\nMit diesem Wissen verhindern wir vielleicht, dass die Blutelfen noch deformierter und böser werden.", completion = "Ihr seid weit gereist und habt zweifellos großen Gefahren getrotzt.\n\nEure Taten waren selbstlos. Es dient ganz Azeroth, wenn Ihr mir bei meinen Forschungen helft. Ich danke Euch für alles, was Ihr getan habt, &lt;Name&gt;.\n\nWenn Ihr mich nun entschuldigen wollt, ich habe viel Arbeit ...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKäferschnallenPrälaturen-Cape\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1276] = {title = "Der Schwarze Schild", objective = "Bringt den geschwärzten Eisenschild zu Mosarn in Thunder Bluff.", description = "Ah, jetzt erinnere ich mich! Mosarn ist ein angesehener Schmied in Thunder Bluff. Ich wusste, ich habe den Namen schon einmal gehört.\n\nAls Dank belohnte mich der irdene Ring mit einem von Mosarn hergestellten Satz Rüstungen. Sehr gute Arbeit.\n\nVielleicht kann er Euch mehr über den Schild sagen, den er anfertigte.\n\nEs ist nicht viel, aber da wir aus Reethe nichts Nützliches herausbekamen, haben wir nichts anderes.", progress = "Guten Tag, <Klasse>. Kann ich Euch mit etwas behilflich sein?", completion = "Ja, Ihr habt gewiss Recht. Das ist ein Schild, den ich gemacht habe.\n\nIch fürchte aber, ich kann Euch nicht viel mehr sagen, &lt;Name&gt;. Ich stelle so viele Schilde und Rüstungen her, ich kann unmöglich über alle Bescheid wissen.", rewards = "Ihr bekommt:\n\n"},
[1281] = {title = "Jims Lied <ZU TRATSCH WECHSELN>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1282] = {title = "Sie nennen ihn den lächelnden Jim", objective = "Sprecht mit Captain Garran Mumm in Theramore.", description = "Ich kann nicht anders, der alte Jim da tut mir Leid. Er war nicht immer so. Hatte eine Zeitlang ein Gasthaus im Sumpf, wunderbares Lokal.\n\nHört zu, ich will wirklich nicht darüber sprechen. Besprecht es mit Captain Mumm, wenn es sein muss.", progress = nil, completion = "James Hyal ist sein richtiger Name. Er eröffnete ein Gasthaus an der Grenze des Brachlandes. Wollte eine hübsche Unterkunft für Reisende daraus machen...\n\nVielleicht war er größenwahnsinnig, aber eine Weile lief das Gasthaus recht gut. Dann verloren wir die Herrschaft über die Straßen im Sumpf und die Oger übernahmen sie.\n\nJames war zu störrisch, seinen Traum aufzugeben und in unsere sicheren Mauern zu kommen, und das Gasthaus Zur süßen Ruh wurde bis auf die Grundmauern niedergebrannt. Wir ermitteln, hatten aber noch kein Glück. Wenn Ihr mir helfen wollt, seht zu, was Ihr in dem Geröll findet.", rewards = "Ihr bekommt:\n\n"},
[1283] = {title = "Feuer im Gasthaus Zur süßen Ruh <ZU TRATSCH WECHSELN>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1284] = {title = "Verdächtige Hufabdrücke", objective = "Berichtet Captain Garran Mumm in Theramore von den verdächtigen Abdrücken beim Gasthaus Zur süßen Ruh.", description = "Reihen von Hufspuren führen von den noch rauchenden Überresten des Gasthauses Zur süßen Ruh weg. Wenigstens einige Abdrücke sind klar erkennbar, weitere Reihen sind im weichen Schlamm des Sumpfs kaum zu sehen.", progress = nil, completion = "Hufabdrücke, hm? Stimmt es, dass es in den Ländern nahe den Marschen von Dustwallow eine außergewöhnlich hohe Zentaurenaktivität gibt? Bei den kurzen Ausflügen ins Brachland fanden wir ihre Lager und Anlagen im gesamten Areal.\n\nIch schicke Falgran Hastil, einen unserer Fährtenleser, damit er feststellt, wohin die Abdrücke führen.", rewards = "Ihr bekommt:\n\n"},
[1285] = {title = "Daelins Männer", objective = "Kehrt mit den Informationen über Reethe zu Captain Garran Mumm in Theramore zurück.", description = "Reddon... Redpath... Oh, da haben wir ihn! Lieutenant Paval Reethe.\n\nTrat den Wachen von Theramore zusammen mit den meisten Rekruten bei, die mit Lady Proudmoore über das Meer kamen. Meldete sich mit sechzehn Jahren zu den Marines in Kul Tiras. Herausragende Dienste, Beförderungen...\n\nIst als vermisst eingetragen.", progress = nil, completion = "Vermisst? Das wäre Tesorans barmherzige Umschreibung für einen Verräter.\n\nZweifellos ist er einer der Narren, die so treu zu Admiral Daelin standen, dass er zum Verräter wurde. Ist das nicht eine köstliche Ironie? Die Deserteure beschuldigen uns, dass wir die Allianz verraten.", rewards = "Ihr bekommt:\n\n"},
[1286] = {title = "Die Deserteure", objective = "Sammelt Informationen über Reethe von Balos Jacken und den Deserteuren in den Marschen von Dustwallow.", description = "Es war ein ständiger Kampf, in den Marschen präsent zu bleiben, aber durch die Kraft unserer Entschlossenheit konnten wir mehrere Wachtürme in diesem Gebiet zur Verteidigung halten.\n\nDie aktuellsten Informationen und Späherberichte, die ich bekam, deuten darauf hin, dass eine Gruppe Deserteure sich in unserem alten Turm bei der verlassenen Wacht, südöstlich des Gasthauses, eingenistet hat.\n\nAnführer der Deserteure ist ein Mann namens Jacken. Seht zu, ob Ihr Informationen über ihn bekommt.\n\nSeid gewarnt, <Name>. Er könnte sich als harte Nuss erweisen.", progress = nil, completion = "Hat Mumm Euch geschickt? Konnte seine Drecksarbeit nicht selbst erledigen, was...", rewards = "Ihr bekommt:\n\n"},
[1287] = {title = "Die Deserteure", objective = "Sprecht mit Captain Garran Mumm in Theramore über Reethe.", description = "Reethe? Dieser Feigling?\n\nWir warfen ihn aus dem Lager hinaus, weil er dauernd die Vorräte der Oger in Brackenwall plündern wollte. So viele sind wir nicht, dass wir es mit diesen hirnlosen Schlägern aufnehmen könnten.\n\nEr hat das Fass zum Überlaufen gebracht, daher haben wir ihn sich selbst überlassen.\n\nAlso ich hab Euch geholfen ... Warum helft Ihr jetzt nicht uns und vergesst, dass Ihr uns gefunden habt?", progress = nil, completion = "Ich schicke Lieutenant Caldwell, damit er sich um die Deserteure bei der verlassenen Wacht kümmert. Darüber hinaus befehle ich ihm Reethe zu suchen. Der Sumpf ist nicht so groß und ungangbar, dass er ihn nicht finden könnte.", rewards = "Ihr bekommt:\n\n"},
[1288] = {title = "Mumms Bericht", objective = "Bringt Mumms Bericht zu Lady Jaina Proudmoore in Theramore.", description = "Ihr habt gute Arbeit geleistet, <Name>, die Beste, die ich je von einem Amateur sah.\n\nLady Proudmoore bat mich, sie über diese delikate Situation auf dem Laufenden zu halten, aber ich habe eine Weile nicht mit ihr gesprochen.\n\nIch wollte ihr meinen Bericht später bringen, aber es scheint mir passender, wenn Ihr mit ihr darüber sprecht. Ihr könnt ihre Fragen wahrscheinlich besser beantworten als ich.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[1301] = {title = "James Hyal", objective = "Sprecht mit Vincent Hyal im Hafen von Menethil.", description = "Bevor ich hier im Blauen Eremiten arbeitete, wurde ich von einem der besten Küchenchefs und Gastwirte ausgebildet, die ich kenne. Sein Name war James Hyal. Alles, was ich besitze und im Leben erreicht habe, verdanke ich ihm.\n\nIch frage mich, was er wohl so treibt... Sein Bruder Vincent und er wollten in einer Taverne im Hafen von Menethil arbeiten, aber ich habe lange nichts von ihm gehört.\n\nWenn Ihr jemals in diese Gegend kommen solltet, könntet Ihr ihm dann Grüße von mir bestellen?", progress = nil, completion = "James? Oh, der ist schon vor einer Weile fort.\n\nIch schätze, er hat seine patriotische Ader entdeckt. Ist auch nicht so schwer zu verstehen. Bei dem ganzen Wahnsinn in Lordaeron folgten viele Leute Jaina Proudmoore, als sie über das Meer kam.", rewards = "Ihr bekommt:\n\n"},
[1302] = {title = "James Hyal", objective = "Sprecht mit Amtmann Lendry in Theramore.", description = "Mein Bruder James fuhr mit Lady Proudmoore über das Meer. Als Letztes hörte ich, dass die Kämpfe dort drüben beigelegt waren und James irgendwo auf dem Kontinent ein Gasthaus eröffnete. Wo immer er sein mag, ich bin sicher, seine Geschäfte blühen. Er war ein verdammt guter Koch.\n\nAber ich habe eine Weile nichts mehr von ihm gehört - zu sehr mit seinem Gasthaus beschäftigt, denke ich. Der Amtmann in Theramore könnte Euch vielleicht zu ihm führen.", progress = nil, completion = "James Hyal, James Hyal... Warum kommt mir der Name so bekannt vor?\n\nNatürlich! Der Vorfall im Gasthaus Zur süßen Ruh. Wenn Ihr Informationen habt, was dort geschehen ist, beschwöre ich Euch, mit Captain Mumm darüber zu sprechen. Er leitet die Ermittlungen.", rewards = "Ihr bekommt:\n\n"},
[1318] = {title = "Die offene Rechnung der Gordok", objective = "Findet die Stulpen der Gordokmacht und bringt sie zu Captain Kromcrush in Düsterbruch.\n\nKromcrush zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat.", description = "Nun Ihr de' König sein, vielleicht Ihr kriegen zurück wertvolles Artefakt der Gordok von gruseligen Elf, der sich selbst nennen Prinz! König vor Euch hat versagt, so wie alle Könige seit Tortheldrin - de' gruselige Elf - es gestohlen hat, von damaligen Gordokkönig!\n\nArtefakt heißen Stulpen der Gordokmacht. Alte Zeit Geschichten sagen, nur wahre König de' Gordok kann sie zurückholen. Alte Zeit Geschichten sagen auch, der gruselige Elf ist immer noch hier - Ihr finden es und es werden Eure mächtigen Stulpen, für immer! Yar, ich zeigen!Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGordoks HandschützerGordoks StulpenGordoks HandschuheGordoks Handlappen\n\nIhr bekommt außerdem:\n\n"},
[1319] = {title = "Der Schwarze Schild", objective = "Zeigt den geschwärzten Eisenschild Caz Twosprocket in Theramore.", description = "Ich kann Euch leider nicht weiterhelfen, <Name>, schicke Euch aber zu jemandem, der es kann. Caz Twosprocket, einer unserer besten Schmiede, arbeitet in der Schmiede.\n\nBringt ihm den Schild und hört Euch an, was er zu sagen hat.", progress = "Etwas, das ich mir ansehen soll?", completion = "Hm... interessantes Stück Eisen habt Ihr da. Definitiv nicht von einem der Schmiede, die ich diesseits des Meeres kenne, und gewiss nicht mein Werk.", rewards = "Ihr bekommt:\n\n"},
[1320] = {title = "Der Schwarze Schild", objective = "Sprecht mit Captain Garran Mumm in Theramore.", description = "Ah, das hätte ich fast übersehen... Der Ledergurt an der Rückseite muss verbrannt sein, aber er war offenbar für eine große Person gemacht. Ich schätze, für einen Tauren.\n\nMehr kann ich Euch nicht sagen. Sagt Captain Mumm, es tut mir Leid, dass ich nicht mehr helfen konnte.", progress = nil, completion = "Das sind keine sehr ergiebigen Informationen, aber wir müssen sie berücksichtigen. Hoffentlich fügen sich noch ein paar Teile dieses Puzzles zusammen und ergeben ein hoffnungsvolleres Bild der Geschehnisse.", rewards = "Ihr bekommt:\n\n"},
[1321] = {title = "Der Schwarze Schild", objective = "Zeigt den geschwärzten Eisenschild Do'gol in Brackenwall.", description = "Hmm... Ich sehe nichts Ungewöhnliches an diesem Schild. Do'gol, der Schmied, sollte ihn sich ansehen. Vielleicht kann er uns mehr sagen, aber große Hoffnungen würde ich mir nicht machen...", progress = "Etwas für mich, <Klasse>?", completion = "Das ist ein guter Schild. Sehr stark, schwer, gut. Aber Do'gol braucht ihn nicht. Ich mache Schilde, ich kaufe sie nicht, &lt;Name&gt;.\n\nDas solltet Ihr wissen.", rewards = "Ihr bekommt:\n\n"},
[1322] = {title = "Der Schwarze Schild", objective = "Bringt 6 säurehaltige Giftbeutel zu Do'gol in Brackenwall.", description = "Hmmm, hier am Rand des Schildes steht etwas geschrieben, aber durch die Brandspuren kann man es kaum lesen.\n\nIch brauche Säure, um ihn zu reinigen. Das Gift der Dunkelzahnspinnen im Sumpf würde helfen. Bringt mir ihre Giftsäcke und ich reinige diesen Schild.", progress = "Habt Ihr die Beutel der Spinnen bekommen?", completion = "Ich mag keine Spinnen, die so groß sind, dass ich mich nicht darauf setzen und sie zerquetschen kann.\n\nDanke, dass Ihr sie geholt habt, &lt;Name&gt;. Jetzt reiße ich sie auf und gieße den Inhalt auf den Schild...", rewards = "Ihr bekommt:\n\n"},
[1323] = {title = "Der Schwarze Schild", objective = "Sprecht mit Krog in Brackenwall.", description = "Oh, ich glaube, ich habe zu viel Säure auf den Schild geschüttet. Lasst mich ein wenig rubbeln...\n\nHm, schwer zu lesen, sieht aber wie der Name Mosarn aus. Nie von ihm gehört. Vielleicht weiß Krog etwas. Krog kennt viele Leute.", progress = nil, completion = "Mosarn? Kommt mir bekannt vor... Ich komm nicht drauf. Vielleicht fällt es mir später wieder ein.\n\nWahrscheinlich ist es nicht wichtig. Ein Schild kann von überall stammen und keine Bedeutung haben...", rewards = "Ihr bekommt:\n\n"},
[1324] = {title = "Der vermisste Diplomat", objective = "Besiegt den Gefreiten Hendel in den Marschen von Dustwallow.", description = "Was?! Ihr kommt hierher und werft mir vor, ich mache mit den Defias gemeinsame Sache und glaubt, ich höre mir diese Beleidigungen an? Etwas sagt mir, dass Ihr das schon lange verdient habt.", progress = nil, completion = "Ich versichere Euch, wir sind alle außer uns wegen der jüngsten Ereignisse, aber lasst ihn uns zum Verhör nach Theramore bringen, dann sehen wir, ob wir den König finden.\n\nIch bin sicher, Milady Proudmoore möchte Euch für Eure Hilfe danken. Sprecht mit Ihr, wenn Ihr einen Moment Zeit habt.", rewards = "Ihr bekommt:\n\n"},
[1338] = {title = "Stormpikes Bestellung", objective = "Bringt Stormpikes Bitte zu Furen Longbeard in Stormwind.", description = "Es gibt einen Rüstungsschmied bei den Zwergen, dessen Arbeit ich sehr bewundere. Sein Name ist Furen Longbeard und seine Fertigkeit unübertroffen. Ich brauche einen neuen Schild und muss einen von ihm haben!\n\nDas Problem ist... Furen lebt weit im Süden im Zwergendistrikt von Stormwind. Im Menschenland! Ich kann mir nicht vorstellen, warum er dort lebt, so weit weg von Ironforge. Die Menschen müssen ihn fürstlich bezahlen, damit er dort bleibt!\n\nWenn Ihr reisen wollt und nichts gegen das Geldverdienen habt, würdet Ihr Furen dann meine Bitte nach einem Schild überbringen?", progress = "Ein Brief aus dem Zwergenland? Ich frage mich, wer von so weit aus dem Norden kommen mag...\n\nBitte lasst mich die Bestellung sehen.", completion = "Ah, eine Bitte von einem der Stormpikes. Das ist ein stolzer Klan erstklassiger Zwerge. Und reich sind sie auch.\n\nDanke, &lt;Name&gt;. Ich werde noch heute Abend mit der Arbeit am Schild von Gebirgsjäger Stormpike beginnen.", rewards = "Ihr bekommt:\n\n"},
[1339] = {title = "Gebirgsjäger Stormpikes Aufgabe", objective = "Sprecht mit Gebirgsjäger Stormpike.", description = "Ich hörte, Gebirgsjäger Stormpike sucht nach einem Läufer. Jemand, der eine Reise für ihn unternimmt. Wie wäre es? Seid Ihr ein <Volk>, der für den Job geeignet ist?\n\nWenn ja, findet Ihr Stormpike auf der Spitze des nördlichen Wachturms.", progress = nil, completion = "Ganz recht. Ich habe eine Aufgabe, die ich auf Wache nicht erledigen kann. Sie wird Euch weit vom Loch Modan wegführen.\n\nDie perfekte Chance auf ein Abenteuer!", rewards = "Ihr bekommt:\n\n"},
[1358] = {title = "Probe für Helbrim", objective = "Bringt die Wolfherzprobe zu Apotheker Helbrim ins Brachland.", description = "Ein Kollege in Kalimdor, Apotheker Helbrim, untersucht die Auswirkungen von Lordaerons Toxinen auf die Wildtiere von Kalimdor. Er wäre an einer Probe der Wolfherzen interessiert, die Renferrel mir geschickt hat.\n\nHelbrim lebt im Brachland in einem Dorf, das Crossroads heißt. Um ihn zu erreichen, müsst Ihr per Zeppelin zur Orc-Hauptstadt Orgrimmar reisen und dann zu Fuß Richtung Süden nach Durotar. Geht durch das Brachland nach Westen und Ihr erreicht bald den Ort Crossroads.", progress = "Habt ihr ein Päckchen für mich?", completion = "Ah, sehr gut. Wenn die ersten Berichte wahr sind, kann die Giftigkeit dieser Herzen uns weiteren Fortschritt im Wissen über Gifte bringen.\n\nDas ist eine willkommene Lieferung, &lt;Name&gt;. Ihr habt Eure Belohnung wohl verdient.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBrauer-HandschuheLanges Schleppen-Cape\n\nIhr bekommt außerdem:\n\n"},
[1359] = {title = "Zinges Lieferung", objective = "Bringt die Wolfherzproben zu Apothekerin Zinge nach Undercity.", description = "Die Wolfherzen, die Ihr beschafft habt, verfügen über ein Merkmal, das es in ähnlichen Proben nicht gibt. Sie verfügen über eine Giftigkeit, die für genau die Wölfe tödlich sein müsste, in denen die Herzen schlagen!\n\nEs ist unglaublich und wir müssen das weiter untersuchen. Ich habe einige Proben der gewonnenen Herzen aufbewahrt. Bringt sie zu meiner Kollegin, Apothekerin Zinge. Ihr findet sie in unserem Hauptquartier in Undercity.", progress = "Habt Ihr etwas für mich?", completion = "Ah ja, die Herzproben, von denen Renferrel sprach. Ich bin ganz erpicht darauf, mit ihnen Experimente durchzuführen... für die Königliche Apothekervereinigung ist es immer von Interesse, wenn neue Toxinformen entdeckt werden.", rewards = "Ihr bekommt:\n\n"},
[1360] = {title = "Wiederbeschaffte Schätze", objective = "Holt Krom Stoutarms wertvollen Besitz aus seiner Truhe in der nördlichen Bankenhalle von Uldaman und bringt den Schatz zu ihm nach Ironforge.", description = "Ich hatte selbst eine gute Arbeitsstelle als Buddler an der Uldaman-Ausgrabungsstätte im Ödland... das heißt, bis diese verfluchten Troggs auftauchten. Ich konnte gerade noch mit heiler Haut entkommen, das war alles. In dem Chaos habe ich meinen wertvollsten Besitz zurückgelassen. Natürlich ist er in meiner Truhe sicher vor den Troggs, aber die befindet sich mitten unter ihnen.\n\nIch wäre in Eurer Schuld, sowohl in Ehre als auch in Münze, wenn Ihr sie für mich besorgen könntet! Eine Truhe mit meinem Namen darauf befindet sich am Ende der nördlichen Bankenhalle. Dorthin müsst Ihr gelangen.", progress = "Na, konntet Ihr die Troggs lange genug in Schach halten, um zu meiner Truhe zu gelangen und Euch meinen Schatz zu schnappen?", completion = "Ah, ich fühle mich wieder komplett - ich danke Euch sehr.\n\nManche Zwerge schätzen den Glanz von Metall und andere schätzen den Glanz von Edelsteinen... aber ein Stoutarm ohne einen liebevoll gehüteten Bierkrug ist kein Stoutarm!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1361] = {title = "Regthar Deathgate", objective = "Sprecht mit Regthar Deathgate.", description = "Ein Krieger der Horde, Regthar Deathgate, rekrutiert Agenten für einen Einsatz im Land Desolace. Sprecht mit ihm, wenn Ihr Euch freiwillig melden wollt. Er lebt im Brachland in einer Reihe von Bunkern westlich von Crossroads.\n\nUnd schärft Eure Waffen. Desolace ist ein vom Krieg zerrissener Ort.", progress = nil, completion = "Ja, ich rekrutiere. Die Mission führt nach Desolace und geht gegen die Zentauren dort. Ich fasse mich kurz, damit Ihr rasch beginnen könnt.", rewards = "Ihr bekommt:\n\n"},
[1362] = {title = "Die Kolkar von Desolace", objective = "Sprecht mit Felgur Twocuts beim Geistwandlerposten in Desolace.", description = "Die Kolkarzentauren leben in Desolace. Ihre Truppen sind in das Brachland vorgestoßen. Das ist bekannt. Agenten der Horde kümmern sich dort um sie.\n\nAber so lange die Zentauren in Desolace so stark sind, werden sie immer eine Bedrohung sein. Mit der Zeit schaffen wir uns diese Bedrohung vom Hals.\n\nSprecht mit Felgur Twocuts beim Geistwandlerposten in Desolace. Seine Aufgabe war es, Informationen über die Zentauren zu sammeln. Er weiß bestimmt, wie man am besten mit den Kolkar von Desolace fertig wird.", progress = nil, completion = "Seid Ihr auf Befehl von Regthar hier? Dann seid Ihr hier, um es den Zentauren zu zeigen. Gut.\n\nIch hoffe, Ihr seid erholt. Ich weiß nicht, wie unsere Kampagne gegen die Zentauren enden wird, aber ich weiß, es wird ein langer Kampf sein.\n\nNehmt Platz und hört zu.", rewards = "Ihr bekommt:\n\n"},
[1363] = {title = "Mazens Befehl", objective = "Sprecht mit Akolyth Dellis in Stormwind.", description = "Als Verwalter der Arbeit hier in der Bibliothek der Akademie der Arkanen Künste und Wissenschaften liegt es in meiner Verantwortung, dafür zu sorgen, dass alle magischen Folianten und Rollen stets erfasst sind. Wer weiß, was Schlimmes geschehen würde, fielen einige dieser verzauberten Texte in die falschen Hände?\n\nDabei fällt mir ein ... mein Assistent Dellis machte letzte Woche einen schrecklichen Fehler. In der Bibliothek ist er recht tüchtig, aber inkompetent, wenn er die Tore von Stormwind hinter sich lässt. Seid ein Held und helft dem alten Dellis, ja?", progress = nil, completion = "Es war nicht meine Schuld. Wirklich nicht.", rewards = "Ihr bekommt:\n\n"},
[1364] = {title = "Mazens Befehl", objective = "Rettet Khadgars 'Abhandlungen über dimensionale Konvergenz' und bringt sie zu Behüter Mahar Ba in der Burg Nethergarde.", description = "Meister Mazens Anweisungen waren ganz klar: Bringt einen sehr wichtigen Essay zu Behüter Mahar Ba in der Burg Nethergarde.\n\nAber ich bin noch nie in den verwüsteten Landen gewesen. Die Reise war beängstigend!\n\nAls ich an die Sümpfe des Elends kam, bog ich falsch ab und war plötzlich von grässlichen pflanzenartigen Sumpfwesen umzingelt. Sie schienen mich angreifen zu wollen, also lief ich weg. Doch in meiner Hast ließ ich den Essay fallen. Ich bin sicher, eine der Bestien hat ihn genommen.\n\nKönntet Ihr bitte versuchen, ihn zu holen und zu Mahar Ba zu bringen?", progress = "Was führt Euch in die Burg Nethergarde, <Volk>?", completion = "Ah, grandios!\n\nIch fürchtete schon geraume Zeit, Meister Mazen in der Akademie der Arkanen Künste und Wissenschaften könnte meine Anfrage nach Khadgars 'Abhandlungen über dimensionale Konvergenz' übersehen haben.\n\nAngesichts der vielen seltsamen Vorkommnisse wird er bestimmt mit Anfragen überschwemmt.\n\nWenn Ihr mich jetzt entschuldigen würdet, ich muss sofort mit meinen Forschungen beginnen. Endlich Einblick in ein Genie wie Khadgar zu bekommen, erfüllt mich mit freudiger Erregung.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLehrerschärpeWanderlust-Stiefel\n\nIhr bekommt außerdem:\n\n"},
[1365] = {title = "Khan Dez'hepah", objective = "Bringt Khan Dez'hepahs Kopf zu Felgur Twocuts in Desolace.", description = "Die Kolkar sind nicht die einzigen Zentauren von Desolace. Viele Klans ziehen durch diese trockenen Ebenen, bekämpfen einander und sterben. Und es ist gut, dass sie sich untereinander bekämpfen, denn sie sind stark und brutal. Vereinten sich die Zentauren gegen uns, wären sie ein schrecklicher Gegner.\n\nWir müssen sie erledigen, bevor sie sich zusammentun.\n\nEuer erster Schritt ist, den Kolkarklan zu schwächen. Macht das, indem Ihr den Anführer Khan Dez'hepah besiegt.\n\nDas Dorf Kolkar liegt nordöstlich von hier. Geht, und möge Euch das Glück hold sein.", progress = "<Name>, habt Ihr Khan Dez'hepah besiegt?", completion = "Gut gemacht. Das rasche Vorgehen gegen die Kolkar zeugt von Kraft, und Kraft verstehen die Zentauren am besten.\n\nDer Tod des Anführers der Kolkar wird diesen Klan nicht schwächen, aber den anderen eine Pause gewähren.", rewards = "Ihr bekommt:\n\n"},
[1366] = {title = "Zentaurenkopfgeld", objective = "Bringt 15 Zentaurenohren zu Felgur Twocuts in Desolace.", description = "Da Ihr die Zentaurenklans jetzt eingeschüchtert habt, wird es Zeit, sie bluten zu lassen. Wenn Ihr durch Desolace reist, jagt Zentauren. Mir ist gleich, welchen Klan Ihr jagt. Sammelt nur Ohren. Bergeweise Ohren.\n\nWenn Ihr ihre Zahl dezimiert, schwächt Ihr ihre Entschlossenheit und macht alle Gedanken an Expansion zunichte.\n\nGute Jagd, <Name>.", progress = "Wie ist Eure Ohrensammlung, <Name>? Groß?", completion = "Inzwischen müssen die Zentauren Euren Namen kennen. Ich bin sicher, sie kennen ihn und respektieren und fürchten ihn. Und genau wie Euch kennen sie das Banner, unter dem Ihr reitet.\n\nDas Banner der Horde.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFliederfarbene SchärpeGeschiente Handschützer\n\nIhr bekommt außerdem:\n\n"},
[1367] = {title = "Allianz mit den Magram", objective = "Baut Euch einen freundlichen Ruf bei den Magram auf und sprecht dann mit Warug.", description = "Um die Zentauren zu schlagen, müssen wir ihren Hass gegen sie wenden. Wir verbünden uns mit einem Klan und lernen durch ihn, wie wir alle Klans besiegen können.\n\nWenn Ihr Euch mit den Magram verbünden wollt, dann tötet ihre Gegner, die Gelkis. Das wird Euch den Respekt der Magram einbringen. Wenn Ihr genug verdient habt, dann trefft Euch mit dem Sprecher der Magram Warug am Rand des Dorfes Magram im Südosten von Desolace.", progress = nil, completion = "Die Gelkis weinen, wenn sie Euren Namen hören, &lt;Name&gt;. Sie fürchten und hassen Euch. Sie hassen Euch so sehr wie die Magram!\n\nVielleicht seid Ihr so stark wie die Magram. Wir werden sehen...", rewards = "Ihr bekommt:\n\n"},
[1368] = {title = "Allianz mit den Gelkis", objective = "Baut Euch einen Ruf als freundliche Person bei den Gelkis auf und sprecht dann mit Uthek der Weisen.", description = "Um die Zentauren zu schlagen, müssen wir ihren Hass gegen sie wenden. Wir verbünden uns mit einem Klan und lernen durch ihn, wie wir alle Klans besiegen können.\n\nWenn Ihr Euch mit den Gelkis verbünden wollt, dann tötet ihre Gegner, die Magram. Wenn Ihr Euch den Respekt der Gelkis verdient habt, dann trefft Euch mit der Schamanin der Gelkis Uthek der Weisen am Rand des Dorfes Gelkis im Südwesten von Desolace.", progress = nil, completion = "Die Erde spricht zu mir. Und sie sagt, Ihr habt viele Magram getötet. Das ist gut.\n\nWenn Ihr ein Freund der Gelkis seid, dann hört zu. Ich habe weitere Aufgaben für Euch.", rewards = "Ihr bekommt:\n\n"},
[1369] = {title = "Zerbrochene Tränen", objective = "Wahrt Euren Ruf bei den Magram und bringt 3 zerbrochene Tränen zu Warug im Dorf Magram.", description = "Die Gelkis glauben, dass unsere Zentaurenmutter Theradras uns beschützt. Sie sind dumm. Niemand beschützt die Zentauren. Die Magram brauchen keinen Schutz! Wir sind die Stärksten!\n\nZeigt den Gelkis, dass sie dumm sind. Geht zu der Höhle in ihrem Dorf. Sie horten Kristalle in dieser Höhle, die Tränen von Theradras. Zerstört die Tränen und bringt mir die zerbrochenen Stücke!", progress = "Wenn Ihr nicht unser Feind seid, dann tut Ihr, was ich verlange!", completion = "Ihr habt die Tränen! Jetzt wissen die Gelkis, dass Theradras ihnen nicht helfen wird. Sie wird nicht weinen, wenn wir sie zerschmettern! Die Magram werden herrschen!\n\nEs war klug, uns zu helfen, &lt;Name&gt;. Wir sind die Stärksten.", rewards = "Ihr bekommt:\n\n"},
[1370] = {title = "Diebstahl von Vorräten", objective = "Bringt 6 Taschen primitiv getrocknetes Fleisch zu Uthek der Weisen im Dorf Gelkis.", description = "Wenn wir nicht im Krieg sind, jagen wir wegen Fleisch. Fleisch gibt uns Kraft und volle Bäuche kämpfen besser als leere.\n\nSo ist es bei den Magram. Sie lagern extra Fleisch ein, damit sie zwischen den Jagdausflügen länger kämpfen können. Wenn man ihr Dorf im Osten überfällt und ihre Fleischvorräte raubt, wird ihre Kraft schwinden.", progress = "Kommt wieder, wenn Ihr Euch der Gelkis abermals als würdig erwiesen habt!", completion = "Gut. Ich kann das laute Magenknurren der Magram aus ihrem weit entfernten Dorf hören!\n\nIch gebe dieses Fleisch den Gelkis. Und wir werden viele Tage ohne Unterbrechung kämpfen können.\n\nWas Ihr getan habt, war gut für die Gelkis, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSilbersternGefiederter PfeilExplosivgeschoss\n\nIhr bekommt außerdem:\n\n"},
[1371] = {title = "Gizmo für Warug", objective = "Wahrt Euren Ruf bei den Magram und bringt eine hochentwickelte Zielattrappe zu Warug im Dorf Magram in Desolace.", description = "Vor langer Zeit kam ein kleiner Gnom nach Desolace. Er hatte Pferde und einen Karren, und auf dem Karren viele seltsame Dinge. Komische Dinge. Dinge, die in verschiedenen Farben brannten. Dinge, die sich bewegten und doch nicht lebten. Ich tötete den kleinen Gnom, aber vorher ... brachte er mich zum Lachen.\n\nIch behielt mein liebstes Ding von dem Wagen. Es war ein Mensch aus Holz, der mir zuwinkte, bis ich ihn schlug und zerbrach.\n\nIch will einen Neuen. Besorgt mir einen Neuen!", progress = "Wenn Ihr nicht unser Feind seid, dann tut Ihr, was ich verlange!", completion = "Ja, genau so etwas hatte ich! Ich bringe sie wieder dazu, sich zu bewegen. Das bringt mich zum Lachen!", rewards = "Ihr bekommt:\n\n"},
[1372] = {title = "Nichts als die Wahrheit", objective = "Sprecht mit Apotheker Faustin im Bettlerschlupfwinkel.", description = "Auf Befehl von Varimathras wurde unsere Expeditionsstreitmacht ausgeschickt, um das untere Azeroth zu vermessen.\n\nBeim Spähen bemerkte ich einen Spitzel der Menschen, der den Bettlerschlupfwinkel ausspionierte. Ehe ich ihn festnehmen konnte, schnappten ihn einige unserer ... Orcbrüder ... und brachten ihn nach Stonard, ihrer Festung in den Sümpfen des Elends.\n\nIch möchte unseren Orcverbündeten ... helfen. Sie sahen unser Lager hier nicht, dennoch wollte ich sie unterstützen.\n\nIch arbeitete hier mit Faustin, um ein ... Wahrheitsserum für unseren Freund in Stonard zu entwickeln.", progress = nil, completion = "Zraedus erzählte mir gerade von dem neugierigen kleinen Spitzel, ehe Ihr gekommen seid.\n\nWirklich ein Problem. Ein Naseweis, der im Bettlerschlupfwinkel herumschnüffelt, hat uns gerade noch gefehlt.\n\nIch bin sicher, die Orcs in Stonard können es kaum erwarten, zu hören, was unser Freund zu sagen hat. Da sie unsere, ähem, Verbündeten sind, müssen wir ihnen helfen, von dem Menschen alle Informationen zu bekommen.\n\nArbeitet mit mir, &lt;Name&gt;, und wir bringen ein Wahrheitsserum nach Stonard.\n\nFür die Horde!\n\n... war das richtig?", rewards = "Ihr bekommt:\n\n"},
[1373] = {title = "Ongeku", objective = "Wahrt Euren Ruf bei den Gelkis und bringt einen Draenethystsplitter zu Uthek der Weisen im Dorf Gelkis in Desolace.", description = "Ihr müsst noch mehr beweisen und Eure nächste Aufgabe führt Euch weit weg, daher werden die Gelkis die Magram vorerst ohne Euch bekämpfen.\n\nDie Erde flüstert jenen, die zuhören, viele Geheimnisse zu. Ein Geheimnis, von dem ich höre, betrifft einen roten Kristall. Er heißt Draenethyst und ist neu auf unserer Erde. Er stammt von einem Ort, wo Berge fliegen und Dämonen herrschen.\n\nBringt mir einen Splitter Draenethyst; er macht meine Magie stark! Der Splitter befindet sich an einem Ort namens Sümpfe des Elends und ist im Besitz von Ongeku, dem Verirrten.", progress = "Zeigt mir, dass Ihr ein Freund der Gelkis seid, <Name>.", completion = "Ja, das ist der Splitter, von dem die Erde flüsterte. Ich spüre starke Magie darin! Ich werde diese Magie gegen die Feinde der Gelkis einsetzen.\n\nIhr habt eine weitere Aufgabe für uns erledigt, &lt;Name&gt;. Vielleicht werden wir Euch bald Freund nennen.", rewards = "Ihr bekommt:\n\n"},
[1374] = {title = "Khan Jehn", objective = "Bringt Khan Jehns Kopf zu Uthek der Weisen im Dorf Gelkis in Desolace.", description = "Die Erde spricht zu mir und sagt, dass die Magram schwach werden. Jetzt ist es Zeit, ihren Khan zu töten!\n\nBringt mir den Kopf des Magramkahns Jehn!", progress = "Zeigt mir, dass Ihr ein Freund der Gelkis seid, <Name>.", completion = "Khan Jehn war stark, aber dumm. Er dachte, seine Kraft wäre groß. Er sah nicht, dass Erdmagie stärker ist. Ohne Anführer werden die Zentauren der Magram fallen und die Gelkis eines Tages herrschen!", rewards = "Ihr bekommt:\n\n"},
[1375] = {title = "Khan Shaka", objective = "Wahrt Euren Ruf bei den Magram und bringt den Kopf von Khan Shaka zu Warug im Dorf Magram in Desolace.", description = "Ihr helft den Magram und ich mag Euch. Tötet jetzt den Khan der Gelkis! Er ist Khan Shaka und ich will seinen Kopf! Ich möchte seinen Kopf ansehen und ihn auslachen!", progress = "Erledigt diese Aufgabe für die Magram und ich helfe Euch.", completion = "Khan Shaka ist tot! Ich stecke seinen Kopf auf eine Lanze und nehme ihn mit, damit Shaka die Kraft der Magram sehen kann!", rewards = "Ihr bekommt:\n\n"},
[1380] = {title = "Khan Hratha", objective = "Wahrt Euren Ruf bei den Gelkis und bringt das Schlüsselfragment der Maraudine zu Uthek der Weisen im Dorf Gelkis.", description = "<Name>, Ihr habt uns gegen die Magram geholfen. Jetzt helft uns dabei, die Maraudine zu schlagen! Tötet den Anführer ihres Klans, Khan Hratha!\n\nUm ihn herauszufordern, blast das Kriegshorn der Maraudine. Es befindet sich auf einem hohen Steilhang im Tal der Speere.\n\nDoch um das Horn zu blasen, müsst Ihr erst ein Kriegshornmundstück erwerben. Diese Teile sind selten und sind ausschließlich im Besitz der vertrauenswürdigsten Maraudinezentauren.\n\nNachdem das Horn geblasen wurde, werden Zentauren kommen. Tötet sie, bis Hratha auftaucht.\n\nKhan Hratha besitzt ein Stück eines... Schlüssels. Bringt es mir...", progress = "Ist Khan Hratha tot? Habt Ihr das Schlüsselfragment?", completion = "Er ist tot! Khan Hratha ist tot! Und jetzt werden die Maraudine untergehen! Wenn die Gelkis dieses Land regieren, &lt;Name&gt;, werden wir uns Euer erinnern. Und die Geister der Erde werden für alle Zeiten Euren Namen singen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMarodeurskette der GelkisUtheks Finger\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1381] = {title = "Khan Hratha", objective = "Wahrt Euren Ruf bei den Magram und bringt das Schlüsselfragment der Maraudine zu Warug im Dorf Magram in Desolace.", description = "Der Khan der Gelkis ist tot, und jetzt werden die Maraudine fallen! Tötet Hratha, den Khan der Maraudine!\n\nUm ihn herauszufordern, blast das Horn auf dem hohen Steilhang im Tal der Speere. Doch um das Horn zu blasen, braucht Ihr erst ein Kriegshornmundstück. Um ein Mundstück zu erwerben, müsst Ihr Zentauren der Maraudine töten. Tötet sie so lange, bis Ihr ein Mundstück findet. Dann blast das Horn.\n\nTut dies, und Zentauren der Maraudine werden zum Turm kommen. Tötet sie, bis Khan Hratha auftaucht. Khan Hratha besitzt ein Stück eines Schlüssels. Gebt mir dieses Stück...", progress = "Tut, was ich verlange. Beweist mir, dass Ihr ein Verbündeter der Magram seid!", completion = "Khan Hratha ist tot! Jetzt sind die Magram die stärksten aller Zentauren! Wir werden die anderen zerschmettern und Desolace beherrschen!\n\nWir werden uns Euer erinnern, &lt;Name&gt;, und unsere Hufen werden Euch verschonen, wenn alle anderen zertrampelt werden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nJägergürtel der MagramZeremonielle Zentaurendecke\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1382] = {title = "Seltsame Allianz", objective = "Baut eine freundliche Beziehung zu den Gelkis auf und sprecht dann mit Uthek der Weisen.", description = "Wir können von Glück reden, dass die Zentauren sich untereinander bekämpfen, denn als vereinigte Kraft könnte sie nichts aufhalten. Ja, das kommt uns zu Gute und wir sollten unseren Vorteil ausbauen.\n\nEiner der Zentaurenklans, der Gelkisklan, führt einen brutalen Krieg gegen den Magramklan. Wenn wir die Magram angreifen, können wir vielleicht eine Allianz mit den Gelkis schmieden.\n\nSprecht mit Uthek der Weisen im Randbezirk der Gelkislager im Südwesten von Desolace. Durch sie könnten wir eine Allianz mit den Gelkis schmieden.", progress = nil, completion = "Unter den Gelkis raunt man erführchtig Euren Namen. Ihr habt viel Blut der Magram an den Händen. Das ist gut.\n\nVielleicht ist es auch gut, wenn wir reden. Erzählt, was Ihr für die Gelkis tun könnt und was wir für Euch tun können..", rewards = "Ihr bekommt:\n\n"},
[1383] = {title = "Nichts als die Wahrheit", objective = "Apotheker Faustin im Bettlerschlupfwinkel braucht 5 Schattenpantherherzen, Morastlordfungus und einen Tiefschreitertumor.", description = "Mir schwebt genau das richtige Serum vor. Es wird die Wahrheit genau so behandeln, wie die Wahrheit behandelt werden sollte.\n\nFür dieses Gebräu brauche ich mehrere Schattenpantherherzen aus dem Sumpf. Außerdem brauche ich den verzauberten Fungus des Morastlords, der dort haust. Ich bin sicher, jemand, der so tüchtig ist wie Ihr, <Name>, kann ihn überreden, sich von einigen zu trennen.\n\nDie schwierigste Aufgabe wird sein, einen Tiefschreitertumor aus dem fernen Desolace zu beschaffen. Nur sehr selten werden die Riesen dort krank, sodass ein Tumor entsteht.\n\nUnd jetzt fort mit Euch!", progress = "Dieser Spitzel in Stonard wird bestimmt ganz... offen... wenn er mein Spezialserum getrunken hat. Ha-ha!\n\nDie erforderlichen Zutaten sind nicht leicht zu beschaffen. Schattenpanther kommen im Sumpf häufig vor, aber genug Herzen für unsere Zwecke zu beschaffen, kann schwierig sein. Und der Morastlord kann so eine heikle Bestie sein.\n\nWas den Tiefschreitertumor angeht, die sind schrecklich schwer zu finden. Aber die chemische Reaktion, die ich damit auslösen kann, ist unübertroffen.", completion = "Großartig, &lt;Name&gt;! Und gerade rechtzeitig. Wie Zraedus mir sagte, hat der Spitzel sich von seinen Verletzungen erholt und kann von den Orcs verhört werden.\n\nGebt mir einen Augenblick, um das Gif..., ich meine das Wahrheitsserum vorzubereiten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerseuchungs-UmhangKlippenholzschlägel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1384] = {title = "Überfall auf die Kolkar", objective = "Wahrt Euren Ruf bei den Gelkis und bringt 10 kunstlose Glücksbringer zu Uthek der Weisen im Dorf Gelkis in Desolace.", description = "Die Kolkarzentauren glauben, ihre Magie sei stark. Die wissen nicht, was Magie ist! Nie und nimmer würden die richtige Magie überhaupt erkennen!\n\nIhr werdet ihnen zeigen, dass ihre Magie schwach ist. Geht zu den Kolkar im Nordosten und tötet sie. Nehmt ihre Glücksbringer. Bringt mir die Glücksbringer und ich werfe sie ins Feuer und lache!", progress = "Habt Ihr die Glücksbringer? Habt Ihr den Kolkar gezeigt, dass sie schwach sind?", completion = "Ihr habt etwas Gutes für die Gelkis getan. Die Kolkar sind schwach und werden sterben. Ihre Magie ist jämmerlich und wird sie nicht retten. Ihr habt ihnen das gezeigt und ihre Angst wird sie noch schwächer machen!\n\nUnd in unserem Land sterben die Schwachen schnell.", rewards = "Ihr bekommt:\n\n"},
[1385] = {title = "Brutale Politik", objective = "Baut Euch einen freundlichen Ruf bei den Magram auf und sprecht dann mit Warug.", description = "Desolace ist ein Land im Krieg. Die Zentauren führen Krieg untereinander und wir glauben, der Sieger wird marschieren und unsere Festungen bedrohen. Das können wir nicht dulden.\n\nWir müssen lernen, wie man die Zentauren schlägt, und dazu... müssen wir uns mit einem der Klans verbünden. Die Zentauren der Magram führen Krieg mit den Gelkis. Wenn Ihr gegen die Gelkis kämpft, dann erwägen die Magram vielleicht eine Allianz.\n\nErringt die Gunst der Magram und sprecht dann mit Warug im Dorf Magram im Südosten von Desolace.", progress = nil, completion = "Viele Gelkis fielen Euch zum Opfer. Das gefällt mir. Vielleicht könnt Ihr noch mehr, das mir gefällt. Vielleicht könnt Ihr und die Magram Freunde sein.", rewards = "Ihr bekommt:\n\n"},
[1386] = {title = "Angriff auf die Kolkar", objective = "Haltet Euren Ruf bei den Magram aufrecht. Tötet 12 Zentauren der Kolkar, 12 Späher der Kolkar sowie 6 Raufer der Kolkar und kehrt dann zu Warug ins Magramdorf in Desolace zurück.", description = "Die Kolkar halten sich für stark, aber wir lachen über sie! Wir lachen und wir töten sie! Tötet auch Ihr sie. Zeigt mir, dass Ihr Kolkar genauso wie wir töten könnt. Geht nach Norden und tötet sie alle!", progress = nil, completion = "Die Kolkar fürchten Euch jetzt! Hoffentlich habt Ihr gelacht, als Ihr sie getötet habt. Es ist gut, wenn man beim Töten lacht, dann sieht der Gegner, dass er schwach ist.", rewards = "Ihr bekommt:\n\n"},
[1387] = {title = "Zentaurenkopfgeld", objective = "Bringt 15 Zentaurenohren zu Corporal Melkins bei der Nijelspitze in Desolace.", description = "Viele Klans bilden das Volk der Zentauren. Jeder hat seinen Anführer und eine Agenda, aber alle Klans haben eines gemeinsam: Grausamkeit.\n\nWenn wir je Frieden finden wollen, müssen die Zentauren entfernt werden. Und ich übertrage Euch die Aufgabe, genau das zu tun.\n\nWenn Ihr durch Desolace zieht, jagt Zentauren und sammelt ihre Ohren. Bringt mir viele, viele Ohren.\n\nMacht das im Dienst der Allianz, <Name>, und wir sind dem Ende des Krieges einen Schritt näher.", progress = "Habt Ihr einen Bericht, <Name>?", completion = "Ah, die Ohren. Gut gemacht.\n\nEure Verdienste um die Allianz stehen außer Frage, &lt;Name&gt;. Das Blut, das Ihr in Desolace vergossen habt, wird zweifellos zahllose Leben retten.", rewards = "Ihr bekommt:\n\nRing der Beruhigung"},
[1388] = {title = "Nichts als die Wahrheit", objective = "Gebt Faustins Wahrheitsserum dem Todespirscher Zraedus im Bettlerschlupfwinkel.", description = "Alles läuft genau nach Plan, <Name>. Ich möchte, dass Ihr dieses Wahrheitsserum dem Todespirscher Zraedus gebt. Er wird Euch zeigen, wie man es richtig... anwendet.\n\nHa-ha!", progress = "Ich hoffe, Ihr habt Euch unserem teuren Freund, dem Apotheker Faustin, als nützlich erwiesen.", completion = "Ich wusste, der alte Faustin würde sich was Gutes ausdenken! Ihr wart zweifellos eine enorme Hilfe.\n\nKommen wir nun zum Geschäft, ja?", rewards = "Ihr bekommt:\n\n"},
[1389] = {title = "Draenethystkristalle", objective = "Bringt 6 Draenethystkristalle zu Magtoor im sicheren Hafen in den Sümpfen des Elends.", description = "Die Verirrten, die im Fallow Heiligtum leben, sehen aus wie wir, aber sie sind Monster... die üblen Unbilden auf unserem Trek nach Azeroth haben sie wahnsinnig gemacht. Einst waren sie unsere Brüder, doch nun leben sie im Fallow Heiligtum im Osten und fangen oder töten alle, die sich in die Nähe wagen.\n\nUnd sie haben uns etwas Heiliges gestohlen - Draenethystkristalle.\n\nUns fehlt die Kraft, das Fallow Heiligtum zu betreten und unseren gestohlenen Draenethyst von ihren Hütten und Lagerfeuern zu holen, aber ohne diese Kristalle... könnten auch wir vom rechten Weg abkommen.", progress = "Habt Ihr die Kristalle?", completion = "Danke, &lt;Name&gt;. Wir stehen in Eurer Schuld.", rewards = "Ihr bekommt:\n\n"},
[1391] = {title = "Nichts als die Wahrheit", objective = "Bringt Zraedus' Bräu zu Spitzel Marksen in Stonard.", description = "Wir müssen mit einer gewissen Diskretion vorgehen. Immerhin werdet Ihr nicht da reinspazieren und den Narren überzeugen, Faustins Gebräu zu trinken, richtig?\n\nAber wenn es eines gibt, zu dem die Menschen nicht nein sagen können, dann ist es Fusel. Ich nehme Faustins Serum und mische es in dieses Bier. Der arme Kerl wird garantiert keine Hemmungen haben, wenn es darum geht, ein Gebräu zu kippen.\n\nGeht hastig nach Stonard in den Sümpfen des Elends, <Name>. Und schweigt schön stille über unsere kleine Mission ...", progress = "Bitte habt Erbarmen mit mir! Ich habe Informationen, die über die Bande der Allianz hinausgehen. Ich hege keine Sympathie für die Horde, aber hier findet ein politischer Verrat statt, der ans Licht gebracht werden muss!", completion = "Ein Getränk für mich? Wie gütig. Sie haben mich seit Tagen nichts mehr trinken lassen. Ich trinke das rasch und dann erzähle ich Euch, was ich herausgefunden habe...", rewards = "Ihr bekommt:\n\n"},
[1392] = {title = "Noboru der Knüppel", objective = "Bringt Noborus Knüppel zum Anführer des sicheren Hafens in den Sümpfen des Elends.", description = "Noboru verseuchte die Draenei des sicheren Hafens seit Monaten; sein Knüppel ist ein Symbol der Brutalität, die sie sich von den Verirrten gefallen lassen mussten.", progress = "Seid gegrüßt. Und willkommen im sicheren Hafen.", completion = "Habt Ihr die Waffe des verhassten Noboru? Ist er denn tot?\n\nDas ist ein Freudentag für den sicheren Hafen. Noboru und seine Bande waren ein Schrecken für uns, denn sie zogen durch die Sümpfe und töteten jeden Draenei, der ihren Weg kreuzte. Er war eine unmittelbare Bedrohung für unser Überleben und wir hatten nicht die Kraft, ihm zu trotzen.\n\nWir sind glücklich, einen Freund in Euch zu haben, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[1393] = {title = "Galens Flucht", objective = "Eskortiert Galen, bis er außer Gefahr ist, sucht dann sein Lager in den Sümpfen des Elends und öffnet seine Geldkassette.", description = "Bitte helft! Diese Kreaturen werden mich fressen!\n\nHelft mir hier raus und ich gebe Euch einen großen Schatz! Er ist in meinem Lager im Sumpf im Norden von Stonard, aber in einer Geldkassette eingeschlossen, die man mit einem Trick öffnet, den nur ich beherrsche.\n\nWenn ihr mir zur Flucht verhelft, zeige ich ihn Euch.", progress = nil, completion = "Das Schlüsselloch dieser Geldkassette ist voll von schwarzem Harz. Man kann sie unmöglich öffnen.\n\nAber Galen erzählte Euch von einem geheimen Schalter an der Unterseite des Kastens... \n\n... Nach einer kurzen Suche findet Ihr den Schalter. Der Schalter kippt und die Geldkassette öffnet sich...", rewards = "Ihr bekommt:\n\nVisionärs-Rundschild"},
[1394] = {title = "Letzte Überfahrt", objective = "Sprecht mit Dorn Plainstalker in Tausend Nadeln.", description = "Ihr habt Eure Sache gut gemacht, <Name>. Ihr habt meinen Test und die Tests vor meinem bestanden. Kehrt zu Dorn in Tausend Nadeln zurück. Er wird die Veränderung in Euch spüren und sehen, dass Euer Verstand, Körper und Geist stark genug sind, dass Ihr für Eure Bemühungen belohnt werden solltet.\n\nBleibt dem Gleichgewicht treu, das Ihr während all dieser Prüfungen gezeigt habt, <Name>. Wenn Ihr das tut, wird Dorn Euch irgendwann noch einmal prüfen.", progress = nil, completion = "Ah, &lt;Name&gt;. Es ist lange her, seit Ihr mein Heim das letzte Mal betreten habt. Anscheinend sind viele Monde vergangen, seit Ihr den ersten Schritt auf Eurem Weg gegangen seid.\n\nUnd jetzt kehrt Ihr stärker als einst zu mir zurück... erleuchteter. Das freut mich. Und Ihr solltet gerecht belohnt werden, weil ihr meine Tests bis zum Ende durchgehalten habt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWindsturmhammerTanzende Flamme\n\nIhr bekommt außerdem:\n\n"},
[1395] = {title = "Vorräte für Nethergarde", objective = "Bringt die Kiste mit den Kraftsteinen zu Rüstmeister Lungertz, bevor die Kraft verbraucht ist.", description = "Diese Kiste mit Kraftsteinen muss in die Burg Nethergarde in den verwüsteten Landen. Sie werden ihre Macht nicht lange halten, daher können wir sie nicht mit der nächsten Karawane aufgeben.\n\nIhr müsst sie nehmen, und zwar schnell.\n\nBringt sie zu Rüstmeister Lungertz in der Burg Nethergarde. Um die Burg zu erreichen, müsst Ihr nach Osten über den Gebirgspass der Totenwinde, dann nach Osten durch die Sümpfe des Elends und dann nach Süden durch die verwüsteten Lande.\n\nSeid vorsichtig, <Name>. Ihr müsst durch gefährliche Länder und dürft doch nicht verzagen.", progress = "Hallo! Stört Euch nicht an dem Durcheinander, so ist das immer in der Burg Nethergarde.\n\nHabt ihr denn etwas für mich?", completion = "Ah, die Kraftsteine! Die Magier werden sich freuen, die zu sehen!\n\nVielen Dank, &lt;Name&gt;. Ich weiß, Eure Reise von Dunkelhain war nicht leicht.", rewards = "Ihr bekommt:\n\n"},
[1396] = {title = "Lauernde Tierwelt", objective = "Tötet 8 junge Sägezahnkrokilisken, 10 Trauerspinner sowie 10 Sumpfjaguare und kehrt dann zu Behüter Biggs in den Sümpfen des Elends zurück.", description = "Meine Karawane sollte zur östlichen Küste ziehen, aber wir erreichten unser Ziel nicht. Verirrte haben uns angegriffen, die Wachen getötet und die Vorräte verstreut.\n\nIch allein habe ihren Angriff überlebt. Ich habe geschworen, die verbliebenen Vorräte zu schützen, aber wilde Kreaturen schleichen in der Nähe herum. Bitte helft mir, mein Lager gegen diese Bestien zu verteidigen!", progress = nil, completion = "Die Geräusche der Tiere klingen jetzt leiser, ferner. Danke, &lt;Name&gt;. Hoffentlich kommen sie nicht zurück!", rewards = "Ihr bekommt:\n\n"},
[1398] = {title = "Treibholz", objective = "Bringt 8 Stücke sonnengetrocknetes Treibholz zu Behüter Biggs in den Sümpfen des Elends.", description = "Ich stehe tief in Eurer Schuld, <Name>. Ein ehrenhaftes Herz schlägt in Eurer Brust. Und jetzt habe ich eine andere Aufgabe, für die ich demütig um Eure Mithilfe bitte.\n\nWenn ich Nethergarde erreichen soll, dann muss ich diesen Wagen reparieren. Und dafür ... brauche ich Holz. Starkes, trockenes Holz - nicht das schimmelige, krumme Holz der Sumpfbäume.\n\n<Name>, geht nach Osten zur Küste und sucht nach in der Sonne getrocknetem Treibholz. Bringt es mir.", progress = "Habt Ihr das Treibholz gefunden, <Name>?", completion = "Dieses Holz ist leicht, aber fest. Danke, &lt;Name&gt;. Es ist genau richtig.", rewards = "Ihr bekommt:\n\n"},
[1418] = {title = "Neeka Bloodscar", objective = "Sprecht mit Neeka Bloodscar.", description = "Das Ödland ist unwirtlich und liegt nahe am Land des Loch Modan, das von der Allianz beherrscht wird, daher wird die Kommunikation zwischen Stonard und den Ödland-Außenposten von Kargath oft unterbrochen.\n\nBeweist Euch, <Name>. Reist ins Ödland und sprecht mit Neeka Bloodscar, der obersten Späherin des Kargath-Außenpostens. Sprecht mit ihr und bringt mir ihren Bericht.", progress = nil, completion = "Helgrum möchte einen Bericht, hm? Ich sandte einen Kundschafter nach Stonard, das ist noch keine drei Tage her. Hat er seine Mission nicht erfüllt? Wenn Stonard meinen Bericht nicht hat, muss er versagt haben.\n\nHoffen wir, dass der nächste Läufer, den ich schicke, mehr Fertigkeiten oder mehr Glück hat.", rewards = "Ihr bekommt:\n\n"},
[1419] = {title = "Kojoten-Diebe", objective = "Bringt 30 Kojotenkieferknochen zu Neeka Bloodscar in Kargath.", description = "Habt Ihr viele Tage im Ödland verbracht, <Klasse>? Habt Ihr sein Herz gespürt? Habt Ihr den Bestien getrotzt, die durch die staubigen Ebenen schleichen? Dann wird es aber höchste Zeit.\n\nKlippenkojoten sind zähe Burschen. Zäh und tollkühn genug, dass sie sich nach Kargath schleichen und unsere Essensvorräte stehlen. Helft mit, den Außenposten von diesen Dieben zu befreien!\n\nJagt Klippenkojoten, <Name>. Jagt sie und bringt mir ihre Kieferknochen. Bringt mir genügend und ich glaube Euch vielleicht, wenn Ihr sagt, dass Ihr das Ödland kennt.", progress = "Habt Ihr die Kieferknochen?", completion = "Das ist eine nette Sammlung Kieferknochen, &lt;Name&gt;. Jetzt werden diese Kojoten nicht mehr unsere Vorräte nach Futter durchwühlen.\n\nGut gemacht. Die Kojoten des Ödlandes sind keine leichte Beute. Eure Tat zeigt mir, dass Ihr hier tatsächlich überleben könntet.", rewards = "Ihr bekommt:\n\n"},
[1420] = {title = "Bericht für Helgrum", objective = "Bringt Neekas Bericht zu Helgrum dem Hurtigen in Stonard.", description = "Ich schrieb einen neuen Bericht für Helgrum in Stonard. Bringt ihn zu ihm.\n\nUnd wenn Ihr Euch als Kundschafter betrachtet, kommt nicht vom Weg ab. Oder fallt einem Feind in die Hände.", progress = "Ihr seid zurück. Habt Ihr einen Bericht?", completion = "Danke, &lt;Name&gt;. Neekas Bericht entnehme ich, dass die Allianz selbst auch Probleme hat. Und wir können feststellen, dass einige Feinde gemeinsame Feinde sind.", rewards = "Ihr bekommt:\n\n"},
[1421] = {title = "Die verlorene Karawane", objective = "Sucht die Karawanentruhe im Fallow Heiligtum, beschafft Euch die Reagenzien der Hexer und bringt sie zu Behüter Biggs.", description = "Ich wurde während des Angriffs der Verirrten betäubt, aber bevor mir schwarz vor Augen wurde, sah ich einen unserer Wagen, der zum Fallow Heiligtum gezerrt wurde, zum Dorf der Verirrten im Norden.\n\nEine Karawanentruhe mit wertvollen Reagenzien war in diesem Wagen, Reagenzien, die unabdingbar für die Studien der Hexer der Burg Nethergarde sind. Sucht die Truhe und holt diese Reagenzien, <Name>. Holt sie und bringt sie mir.", progress = "Habt Ihr die Hexerreagenzien, <Name>?", completion = "Ah, Ihr habt sie gefunden! Damit können die Hexer in Nethergarde ihre Arbeit fortsetzen. Ich weiß nicht, was sie tun, aber es hat mit dem Dunklen Portal in den verwüsteten Landen zu tun und ist wichtig für die Sicherheit der Allianz.", rewards = "Ihr bekommt:\n\n"},
[1422] = {title = "Gefahr aus dem Meer", objective = "Sprecht mit Katar in den Sümpfen des Elends.", description = "Warum unterhaltet Ihr Euch nicht mit Katar, während ich an Eurer Waffe arbeite? Er erwähnte, dass er Hilfe bei Patrouillen am Strand braucht, und mir wäre es lieber, Ihr würdet Euren Geist und Eure Waffen trainieren, anstatt Euch mit den anderen Tunichtguten in diesem Lager zu betrinken.", progress = nil, completion = "Schweigt einen Moment, &lt;Klasse&gt;. Trotz der dumpf tosenden Brandung könnt Ihr das abscheuliche Gluckern der Fischmenschen hören.", rewards = nil},
[1423] = {title = "Die verlorenen Vorräte", objective = "Bringt die verlorenen Vorräte zu Rüstmeister Lungertz.", description = "Dieses Fass ist klein, aber stabil. Seine Ritzen sind mit einem gelben, duftenden Wachs versiegelt. Auf der Unterseite des Fasses stehen die Worte:\n\nRÜSTMEISTER LUNGERTZ\n\nBURG NETHERGARDE", progress = "Habt Ihr etwas für mich?", completion = "Ah, vielen Dank, &lt;Name&gt;! So viele Vorräte gehen auf dem Weg von Dunkelhain hierher verloren. Es tut gut zu sehen, dass einige davon wiederbeschafft werden.", rewards = "Ihr bekommt:\n\nKasten mit Vorräten"},
[1424] = {title = "Tränenteich", objective = "Fel'Zerul in Stonard möchte, dass Ihr 10 Artefakte der Atal'ai sammelt.", description = "Der Kriegshäuptling schickt uns, die seltsamen Vorkommnisse im Tempel von Atal'Hakkar zu untersuchen.\n\nDie Trolle des Stammes der Atal'ai sind ein Stamm dunkler Zauberkundiger, die dafür bekannt sind, verbotene Magie auszuüben. Ihr könnt Euch vorstellen, wie erstaunt wir waren, als wir hier eintrafen und feststellten, dass der Tempel versunken war.\n\nDie grünen Großdrachen hüten nun die Stelle und spielen sich als Beschützer von Azeroth auf.\n\nWir müssen herausfinden, was geschehen ist. Forscht rund um den Tränenteich und sammelt Artefakte der Atal'ai. Damit kann ich dieses Rätsel lösen.", progress = "Niemand weiß, welche dunklen Rituale im Tempel von Atal'Hakkar durchgeführt wurden. Aber wir wissen, dass große und mächtige magische Kräfte benutzt wurden.\n\nWir müssen so viel wir können über diese Magie lernen. Vielleicht erweisen sich die Zauber der Atal'ai als nützlich für die Horde.\n\nWenn Ihr genügend Artefakte der Atal'ai rings um den Tränenteich gesammelt habt, verstehe ich vielleicht, was sich die Trolle erhofften und was so schrecklich schief gegangen ist.", completion = "Euer Geschick beim Aufspüren der Artefakte der Atal'ai verdient höchstes Lob, &lt;Klasse&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1425] = {title = "Überbringen der Lieferung", objective = "Bringt die Ladung für Nethergarde zu Rüstmeister Lungertz in der Burg Nethergarde.", description = "Während ich diesen Wagen repariere, <Name>, habe ich eine letzte Aufgabe für Euch.\n\nIch habe die wichtigsten Vorräte eingepackt, die ich vor den Angriffen der Oger retten konnte. Bringt sie zur Burg Nethergarde. Die Burg schmiegt sich an die nördlichen Hügel der verwüsteten Lande und wacht über das Dunkle Portal.\n\nFolgt der Straße nach Osten, um Nethergard zu erreichen. Geht an der Gabelung nach Süden in die verwüsteten Lande und bei der nächsten Gabelung nach links. Folgt der Straße, <Name>, und seid wachsam.", progress = "Habt Ihr etwas mit mir zu schaffen?", completion = "Was? Ein Päckchen von Briggs' Karawane? Wir dachten, es wäre verloren, genau wie er.\n\nDanke, &lt;Name&gt;. Mit etwas Glück befinden sich bei diesen Vorräten die dringend benötigten Reagenzien Azorankristalle. Unser Vorrat wird knapp...", rewards = "Ihr bekommt:\n\n"},
[1426] = {title = "Gefahr aus dem Meer", objective = "Tötet 10 Marschenmurlocs, 10 Marschentintenspucker und 10 Marschenfleischfresser und kehrt dann zu Katar in den Sümpfen des Elends zurück.", description = "Ich mag weder das Meer noch die Kreaturen, die ich aus seiner Tiefe kommen sah. Es ist eine mächtige, aber blinde Herrin; launisch und brutal. Es wäre mir ein Vergnügen, die Fischmenschen zu Hunderten zu töten, wenn es in meiner Macht stünde. Eine kleine Freude ist es mir wenigstens, sie durch die Hände all derer sterben zu sehen, die den Willen der Horde erfüllen.\n\nUnd damit sind wir bei Euch, <Klasse> . Wie viele könnt Ihr besiegen? Würdet Ihr Euch mit dem Mächtigsten ihrer Art messen?", progress = "Ich bin geduldig. Geduldig und ewig wie ein alter Kankstein von Draenor. Die Fischmenschen werden unsere Grenzen nicht passieren - nicht solange ich stehe. Hätten wir eine Armee, würde ich diese Welt und alle anderen von ihnen säubern. Ich spüre, wie mein Hass lodert, wenn ich nur von ihnen spreche.", completion = "Das Meer wirkt weit und unbarmherzig, doch Ihr habt es mit dem Blut seiner eigenen Brut besudelt. Die Fischmenschen kennen den Schmerz. Durch ihre Dummheit müssen sie ihre Reihen nach der Verheerung, die Ihr über sie brachtet, neu auffüllen, und das ist gut.\n\nSollen ihre gurgelnden Schreie das Brüllen der Brandung noch bis weit in die Nacht übertönen. Ich werde jedes Mal lächeln, wenn einer von ihnen verstummt.\n\nKehrt zu mir zurück, wenn Ihr noch mehr Fischmenschen töten wollt. Ich werde Euch gern abermals belohnen.", rewards = "Ihr bekommt:\n\n"},
[1427] = {title = "Gefahr aus dem Meer", objective = "Sprecht mit Tok'Kar in den Sümpfen des Elends.", description = "Sprecht wieder mit Tok'Kar, bevor Ihr Euch ausruht. Während Ihr fort wart, hat er, glaube ich, ein paar Waffen vollendet. Für Eure Hilfe würde er Euch eine davon anbieten. Ihr tätet gut daran, ihre Kraft an den Fischmenschen zu erproben, wenn Ihr bereit seid ... aber nur, um mich weiterhin zu erfreuen.", progress = nil, completion = "Ah, &lt;Name&gt;, Ihr seid zurück. Gut. Ich habe weitere Waffen für unseren Kampf gegen die Murlocs hergestellt. Da Ihr uns frisches Sägezahnfleisch gebracht und ein Lächeln auf Katars Gesicht gezaubert habt, biete ich Euch eine davon an.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTok'Kars MurlocentbeinerTok'Kars MurlocbersterTok'Kars Murlochackbeil\n\nIhr bekommt außerdem:\n\n"},
[1428] = {title = "Fortwährende Gefahr", objective = "Tötet 10 Marschentintenspucker, 10 Marschenfleischfresser und 10 Marschenorakel und kehrt dann zu Katar in den Sümpfen des Elends zurück.", description = "Freut mich zu sehen, dass Euer Hass auf die Fischmenschen mit meinem wächst.\n\nSucht mehr von ihnen am Strand entlang, und wenn Ihr genug vom Gefecht habt, kommt zu mir zurück. Dann sprechen wir über eine Belohnung für Eure Ausdauer.", progress = "Erst wenn das Meer und all seine Kinder verstummt sind, werde ich zufrieden sein... besonders diese abstoßenden Fischmenschen.", completion = "Gut gemacht, &lt;Klasse&gt;. Ich möchte mehr von ihrem Blut sehen. Mögen alle Fischmenschen verschwinden.", rewards = "Ihr bekommt:\n\n"},
[1429] = {title = "Der Verbannte der Atal'ai", objective = "Bringt das Artefaktbündel der Atal'ai zu dem Verbannten der Atal'ai ins Hinterland.", description = "Während Ihr den Gefahren des Tränenteichs getrotzt habt, kehrte einer meiner Späher mit einer in Blut und auf getrocknetem Fleisch geschriebenen Rolle zurück. Es scheint sich um ein Urteil gegen einen der Priester des Stammes der Atal'ai zu handeln.\n\nDer Priester wurde zu etwas Schlimmerem als dem Tod bei den Atal'ai verurteilt.\n\nEr wurde ins Hinterland zu den Trollen der Witherbark verbannt.\n\nIch bündle diese Artefakte. Ihr müsst den Verbannten suchen und ihren wahren Verwendungszweck herausfinden. Kommt wieder zu mir, wenn Eure Reise beendet ist.", progress = "Ihr seid tapfer, hierher zu kommen. Tapfer oder töricht...", completion = "Bringt Ihr mir die Beschwörungsartefakte der Atal'ai?\n\nIch sehe, dass Jammal'an der Prophet die Schüler der Kammer des Blutes zu ihrem gewählten Schicksal führen wird. Ob Hakkar wohl zum Tempel zurückgekehrt ist? Hat sich ihr Schicksal erfüllt?", rewards = "Ihr bekommt:\n\n"},
[1430] = {title = "Frischfleisch", objective = "Bringt 10 monströse Kriecherbeine zu Dar in den Sümpfen des Elends.", description = "Bei meinen Kunden besteht eine enorme Nachfrage nach dem saftigen Geschmack von Kriecherfleisch; besonders nach dem Fleisch der monströsen Kriecher.\n\nWenn Ihr vorhabt, zur Küste zu reisen, könnte es sich lohnen, wenn Ihr mir einige ihrer Beine bringt, damit ich sie nach Orgrimmar transportieren lassen kann.\n\nDie Küste liegt östlich von hier. Ihr solltet keine Probleme haben, die Kreaturen zu finden, die an den Stränden und im Meer umherhuschen.", progress = "Ich habe ein Fässlein Wein, das auf Euren Erfolg wartet, <Name>. Es ist nur recht und billig, dass ich meine Ware prüfe, bevor ich sie zu den Kunden liefern lasse.", completion = "Ah, das müsste perfekt sein. Ich kann es kaum erwarten, sie zu kosten, wenn sie perfekt über einem offenen Feuer zubereitet wurden. Ihr solltet eine Kostprobe mit auf Eure Reisen nehmen. Es ist wirklich köstlich.", rewards = "Ihr bekommt:\n\nGegrillte KönigskriecherbeineLederner Gürtel des Küchenchefs"},
[1431] = {title = "Allianz-Beziehungen", objective = "Sprecht mit Keldran in Orgrimmar.", description = "Seid still, <Name>, und lasst mich Euch etwas Wichtiges über unser Volk sagen, das nicht auf der Hand liegt.\n\nWir sind ein stolzes Volk und der Krieg gegen die Menschen hat selbst Thralls große Geduld auf die Probe gestellt. Wisst Ihr, unser Kriegshäuptling ist weise und umsichtig und sein Volk kommt stets an erster Stelle. Letztendlich ist er ein Diplomat und hat in seiner Zeit bei den Menschen viel von ihrer Art gelernt.\n\nWenn die Geschichte, die ich begonnen habe, Euer Interesse weckt, dann geht zu Keldran beim westlichen Ausgang der Stadt. Dort steht seine Hütte.", progress = nil, completion = "Putanni, Edler &lt;Klasse&gt;. Ich bin Keldran, Student der Magie... und anderer mystischer Künste.\n\nDie Angelegenheit, in der Craven Euch hergeschickt hat, erfordert ein klein wenig mehr Feinsinnigkeit als bisher erforderlich war, aber das bedeutet nicht, dass Ihr unserer Sache nicht dienlich sein könnt.\n\nBitte macht es Euch bequem, dann sage ich Euch, warum der Kriegshäuptling meine Unterstützung braucht... und Eure.\n\nEs fängt mit Äußerlichkeiten an, &lt;Name&gt;. Wie die Horde sich selbst sieht. Wie unsere Verbündeten uns sehen. Und am wichtigsten, wie unsere Feinde uns sehen.", rewards = "Ihr bekommt:\n\n"},
[1432] = {title = "Allianz-Beziehungen", objective = "Sprecht mit Takata Steelblade in Desolace.", description = "Wenn die Allianz immer tiefer nach Kalimdor vorstößt, könnten falsche Schlussfolgerungen über mögliche Bündnisse der Horde mit der Brennenden Legion gezogen werden. Dazu darf es der Kriegshäuptling nicht kommen lassen. Und mit seinem Segen übernehme ich die Aufsicht darüber, dass alle Missverständnisse ausgeräumt werden.\n\nIch habe Agenten in der Gegend von Desolace am Geistwandlerposten nördlich des großen Kodofriedhofs. Wenn Ihr vom verbrannten Tal im Steinkrallengebirge aus südwärts geht, solltet Ihr dort vorbeikommen. Wenn Ihr eintrefft, sucht Takata Steelblade auf.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;. Ihr bringt Neuigkeiten aus Orgrimmar, das ist gut.\n\nDie Dämonenbrut beherrscht dieses Gebiet noch schlimmer als der Geruch von Zentaurendung. Die Pferdemenschen beanspruchen dieses Land für sich, aber es gibt eindeutig Einflüsse außerhalb ihrer Kontrolle, die sie zerschmettern, hält man sie nicht im Zaum.\n\nEs freut mich nicht, dass wir die Zentauren indirekt unterstützen, aber es dient dem Wohl der Horde, daher erfülle ich meine Pflicht gegenüber dem Kriegshäuptling, auch wenn es bedeutet, dass ich den Hexenmeistern in der Horde helfen muss.", rewards = "Ihr bekommt:\n\n"},
[1433] = {title = "Allianz-Beziehungen", objective = "Sprecht mit Maurin Bonesplitter in Desolace.", description = "Die Burning Blade haben eigene Ziele verfolgt; doch wisst, dass sie bis ins Mark böse sind und ihr Geist verderbt wurde. Sie zu vernichten ist die einzige Möglichkeit, ihnen Einhalt zu gebieten.\n\nKeldran schickte Maurin mit mir, weil er die Klinge und die Arglist ihrer Hexenmeister kennt.\n\nEr leitet unsere Verschwörungen gegen die Klinge, während ich mich um die anderen dämonischen Bedrohungen in Desolace kümmere.\n\nSprecht mit ihm und er wird Euch in seine Pläne einweihen.", progress = nil, completion = "Ah, ja. Hilfe von denen, die dem Kriegshäuptling loyal sind, ist immer willkommen.\n\nMein Name ist Maurin. Ich bin hier auf Geheiß von Keldran und dem jungen Kriegshäuptling Thrall. Es ist mein Wunsch, dem jungen Anführer gegen das Böse beizustehen, das seine Regentschaft zu stören droht.\n\nKommt, kommt näher, &lt;Klasse&gt;. Ich erkläre Euch meinen Plan, wie man die Eiterbeule Burning Blade beseitigen kann.", rewards = "Ihr bekommt:\n\n"},
[1434] = {title = "Beschmutzt durch Satyrn", objective = "Besiegt 7 Schurken der Zornsäer, 7 Teufelsanbeter der Zornsäer, 7 Verräter der Zornsäer sowie 7 Höllenrufer der Zornsäer und kehrt zu Takata Steelblade in Desolace zurück.", description = "Eine Dämonenplage geschieht nicht ohne andere Einflüsse - etwas anderes ermöglicht dem Bösen, Fuß zu fassen.\n\nEs mag mit einem schwachen Geist beginnen, einer unnötigen Gier nach Macht, möglicherweise Rachedurst oder der Verlockung nach höchster Gerechtigkeit. Wenn der Schmerz uns übermannt, dann nutzt uns das Böse aus - das Böse wie die Satyrn.\n\nBande wurden zwischen ihnen und den Burning Blade geknüpft und Thrall hätte sie getötet. Sucht sie nordöstlich von hier und kommt zu mir zurück, wenn Ihr sie zurückgeschlagen habt.", progress = nil, completion = "Ihr habt Eure Sache gut gemacht, &lt;Klasse&gt;. Ihr habt Ehre und Entschlossenheit gezeigt.\n\nWenn Eure Kampagne in Desolace beendet ist, wird der Kriegshäuptling erfahren, dass ihr uns bei unseren Aktionen hier unterstützt und geholfen habt, dass sein Wille geschehe.\n\nIch danke Euch.", rewards = "Ihr bekommt:\n\n"},
[1435] = {title = "Brennender Geist", objective = "Bringt den brennenden Edelstein und 15 erfüllte brennende Edelsteine nach Desolace zu Maurin Bonesplitter.", description = "Für diese abscheulichen Kreaturen, die ihrem Lehen aus so egoistischen Gründen den Rücken kehren, ist der Tod höchst wünschenswert. Doch wenn man es mit denen zu tun hat, die sich der Dunkelheit verschrieben haben, reicht der Tod allein nicht aus.\n\nNehmt diesen Edelstein. Wenn einer der Burning Blade dem Tode nahe ist, aktiviert seine Magie. Der Zauber wird den verderbten Geist aus seinem Opfer herausziehen und einen damit erfüllten Edelstein hinterlassen.\n\nBringt mir diese erfüllten Edelsteine, damit ich sie angemessen entsorgen kann.\n\nGeht jetzt, und möge Euch der Tod meiden.", progress = "Ich habe versucht, die Magie so einfach wie möglich zu machen. Es sollte ein Kinderspiel sein, den Geist Eures Opfers aus seiner verletzten Hülle herauszuziehen. Verlasst Euch aber nicht darauf, dass die Macht des Edelsteins Eure Gegner ganz tötet. Ihr dürft den Edelstein erst aktivieren, wenn sie dem Tode nahe sind, sonst ist er wirkungslos.", completion = "Ah, Ihr seid erfolgreich zurückgekehrt. Das ist gut. Gebt mir die Edelsteine und ich verwahre sie an einem sicheren Ort...\n\nMeine Aufgaben für Euch sind abgeschlossen, &lt;Klasse&gt;. Sprecht mit Takata, wenn Ihr erholt seid. Er hat vielleicht andere Aufgaben für Euch oder bittet Euch nach Orgrimmar zurückzukehren, um Keldran von den Fortschritten hier in Desolace zu informieren.", rewards = "Ihr bekommt:\n\n"},
[1436] = {title = "Allianz-Beziehungen", objective = "Sprecht mit Keldran in Orgrimmar.", description = "Der Kampf läuft gut, <Name>. Vielleicht lässt uns der Kriegshäuptling, bevor die Jahreszeiten wechseln, in unsere Heimat zurückkehren, wenn der Kampf gegen die Dämonen und ihre Unterlinge weiterhin so gute Fortschritte macht.\n\nKehrt zu Keldran zurück und lasst ihn wissen, was wir getan haben. Ich bin sicher, er belohnt Euch für Eure Taten hier. Seine Sache ist ihm wichtig und es wird ihn mit Stolz erfüllen, wenn er weiß, dass der Kriegshäuptling seine Sorgen respektiert.", progress = nil, completion = "Ihr seid mehr als erfolgreich aus Desolace zurückgekehrt, &lt;Name&gt;. Danke.\n\nDanke für Eure Bemühungen, Eure Zeit und Euer Verständnis für meine Bitte. Thrall versteht und wünscht Frieden zwischen der Horde und der Allianz, und wenn wir Maßnahmen ergreifen, um unser Erscheinungsbild zu verbessern, werden wir keine weitere sinnlose Gewalt provozieren.\n\nIch stehe in Eurer Schuld.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHandschuhe des KapelanFlinkläufer-Cape\n\nIhr bekommt außerdem:\n\n"},
[1437] = {title = "Vahlarriels Suche", objective = "Sucht und findet den Wagen von Tyranis und Dalinda Malem in Desolace.", description = "Ich bin Vahlarriel, <Name>. Ich kam her, um mich nach dem Befinden zweier vermisster Adliger einer Kaufmannsfamilie aus Darnassus zu erkundigen - Haus Malem. Der Vater des Hauses fürchtet das Schlimmste. Ich soll tun, was ich kann, um seine vermissten Kinder zu finden. Ich habe noch nicht mit der Suche nach Tyranis und Dalinda begonnen, hoffe aber, ich werde mich nicht lange hier aufhalten.\n\nZuletzt hörte man, dass sie vor wenigen Wochen durch das Steinkrallengebirge gekommen sein sollen.\n\nFalls Ihr ihren Wagen findet, sucht mich bitte unverzüglich auf.", progress = nil, completion = "Als Ihr in den Überresten des Wagens sucht, stellt Ihr fest, dass er mit Zauber und mit Waffen angegriffen wurde. Es scheint ein ungleicher und schneller Kampf gewesen zu sein; Blut ist keines zu sehen, auch keine Toten.\n\nWer immer den Wagen angegriffen hat, war tüchtig und schnell.", rewards = "Ihr bekommt:\n\n"},
[1438] = {title = "Vahlarriels Suche", objective = "Sucht Dalinda Malem in Desolace.", description = "Sucht Dalinda und Tyranis, wenn Ihr könnt, und berichtet mir von Euren Funden. Beginnt Eure Suche in dieser Festung. Ich setze mich sofort mit meinen Vorgesetzten in Darnassus in Verbindung und informiere sie über die Situation.\n\n<Name>, ich möchte Euch noch etwas wissen lassen. Meine Vorgesetzten haben Besorgnis wegen Tyranis und seinen Motiven für diese Reise geäußert. Es ist ihnen wichtiger, dass Dalinda gefunden und wohlbehalten zurückgebracht wird. Tyranis soll ... gefesselt werden, ehe man ihn nach Hause bringt.", progress = nil, completion = "Elune sei Dank, endlich kommt jemand zu Hilfe. Bitte, &lt;Klasse&gt;, ich brauche Eure Hilfe. Mein Bruder Tyranis und ich wurden von den Burning Blade gefangen genommen und hierher gebracht. Ich glaube, sie wollen mich ihren Dämonenmeistern opfern!\n\n Ich weiß, es war ein Fehler, nach Desolace zu kommen, aber Tyranis entwickelte jüngst ein Interesse an allem Arkanen - gegen den Wunsch unserer eigenen Leute. Er beschloss, diese Reise zu machen, als er von der Dämonenplage des Landes erfuhr.\n\nIch fürchte das Schlimmste für ihn.", rewards = "Ihr bekommt:\n\n"},
[1439] = {title = "Suche nach Tyranis", objective = "Sucht Tyranis Malem in Desolace.", description = "Wir wurden hierher gebracht, nachdem die Orcs alle unsere Wachen und Diener abgeschlachtet hatten. Oh, was haben sie ihnen Schreckliches angetan! Ich dachte, sie würden uns auf der Stelle töten, doch dann wurde deutlich, dass sie andere Pläne hatten.\n\nTyranis versuchte, mit ihnen zu reden. Ich glaube, er wollte sie mit seinem arkanen Wissen beeindrucken ... Ich bin nicht sicher, warum.\n\nBitte, ich kann hier nicht weg, bevor ich weiß, was meinem Bruder zugestoßen ist. Sucht ihn und kommt zu mir, wenn Ihr sein Schicksal kennt.", progress = "Ich fürchte, Tyranis wird versuchen, die Geheimnisse der Burning Blade zu erlernen und sich ihnen anschließen, wenn sie ihn lassen - er hat stets die Macht bewundert, die Magie allen bringt, die sich von ihr verführen lassen.\n\nIch bin nicht sicher, ob ich zu meiner Familie zurückkehren und ihnen sagen kann, dass Tyranis' Geist mit solchen Gefahren spielt. Bei meinesgleichen ist es ein schreckliches Verbrechen, so etwas zu suchen, aber das zu werden, wovor wir uns schützen möchten, das ist verständlich.", completion = "Das ist schrecklich! Aber ich denke, es war notwendig. Hättet Ihr es nicht getan, dann gewiss einer meines Volkes. Ich nehme an, ich sollte Euch danken... bitte verzeiht mir, wenn es unaufrichtig wirkt. Es war nicht böse gemeint.\n\nDa ich das Schicksal meines Bruders nun kenne, scheint es mir an der Zeit zu fliehen. Wenn Ihr noch gewillt seid, nehme ich Eure Hilfe an, um von diesem schrecklichen Ort zu fliehen.\n\nSolltet Ihr bereit sein, können wir uns in Sicherheit bringen.", rewards = "Ihr bekommt:\n\n"},
[1440] = {title = "Rückkehr nach Vahlarriel", objective = "Begleitet Dalinda Malem aus der Festung Thunder Axe und kehrt zu Vahlarriel Demonslayer nach Desolace zurück.", description = "Also ist die Zeit gekommen? Ich weiß Eure Bemühungen zu schätzen, und wenn auch die Situation dafür nicht geeignet ist, lasst mich Euch jetzt für alles danken, was Ihr für mich und meine Familie getan habt. Wenn Ihr bereit seid, hier hält mich nichts mehr - wir können aufbrechen, falls es Euch passend erscheint.", progress = nil, completion = "Danke, &lt;Name&gt;. Dalinda hat es wohlbehalten zur Nijelspitze geschafft und in besserer Verfassung, als ich es für möglich gehalten hätte. Allein, dass sie aus eigener Kraft hier eintraf, war ein gutes Zeichen. Ich hoffe, es geht Euch gut.\n\nEs schmerzt mich zu wissen, dass weder Tyranis noch Dalinda zurückgekehrt sind, aber mit der Schande von Tyranis' Entscheidungen muss sie leben. Damit muss sie sich auseinander setzen, wenn sie nach Darnassus zurückkehrt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGreifer-GürtelHandschuhe der EinsichtGarnisons-UmhangMondbeschienene Amicia\n\nIhr bekommt außerdem:\n\n"},
[1442] = {title = "Suche nach dem Kor-Edelstein", objective = "Bringt einen Kor-Edelstein zu Thundris Windwirker in Dunkelküste.", description = "Seid gegrüßt, <Name>. Was kann ich für einen tun, der dem heiligen Weg folgt?\n\nAh ja, Stilwell, der Schmied... das war vor langer Zeit. Ich erinnere mich gut an ihn, doch ich habe seinen Namen schon eine ganze Weile nicht mehr gehört.\n\nEr schien mir nie ein habgieriger Mann zu sein, daher kann ich nur davon ausgehen, dass sein Wunsch nach einem Kor-Edelstein edle Motive hat.\n\nWenn Ihr wirklich so einen Edelstein möchtet, dann müsst Ihr in den Nordwesten von Ashenvale. Dort findet Ihr die Blackfathom-Tiefe mit einigen alten Ruinen. Die Naga, die diese Edelsteine noch immer benutzen, sind dort unten. Geht nicht allein, <Klasse>.", progress = "Bei einem, der nicht dem heiligen Weg folgt, wäre ich nicht so vertrauensselig, wenn er nach einem Kor-Edelstein fragen würde. Aber ich traue Euresgleichen fast mehr als meiner Art. Ich beurteile nicht Euren ganzen Orden nach den Taten eines gefallenen Mitglieds.", completion = "Das ist wahrhaftig der Edelstein, den Stilwell begehrt, doch ehe ich zulassen kann, dass Ihr ihn zu ihm bringt, muss er von Verderbnis geläutert werden - die Frauen der Naga stärken die Edelsteine mit Macht, das stimmt, aber mit ihrer eigenen bösen Macht.\n\nLasst Stilwell wissen, dass die Macht unversehrt ist und bei jedem Ritual, das er durchführen möchte, funktionieren sollte.\n\nIch hoffe nur, Ihr wisst, was Ihr tut, &lt;Klasse&gt;, es ist kein einfacher Gegenstand, den Ihr da besitzt.", rewards = "Ihr bekommt:\n\nGeläuterter Kor-Edelstein"},
[1444] = {title = "Rückkehr zu Fel'Zerul", objective = "Kehrt zu Fel'Zerul in Stonard zurück.", description = "Jammal'an der Prophet verbannte mich aus dem Tempel von Atal'Hakkar. Einst empfand ich den Hohepriester als würdigen Anführer.\n\nSein unerschütterlicher Glaube an seine Prophezeiung wird den Untergang der Atal'ai herbeiführen. Wenn es nicht schon geschehen ist.\n\nAls ich meiner Besorgnis Ausdruck verlieh, hieß man mich einen Ungläubigen und verstieß mich aus dem Tempel.\n\nDie Artefakte, die Ihr zu mir brachtet, sind harmlos. Aber wenn Jammal'an die richtige Fetischverzauberung für das Beschwörungsritual gefunden hat, droht der Welt große Gefahr...", progress = nil, completion = "Es ist eine Weile her, seit wir miteinander sprachen, &lt;Klasse&gt;. Ich hoffe, Eure Reise war erfolgreich.\n\nWelches Wissen habt Ihr von dem verbannten Atal'ai im Hinterland erlernt?", rewards = "Ihr bekommt:\n\n"},
[1445] = {title = "Der Tempel von Atal'Hakkar", objective = "Sammelt 20 Fetische von Hakkar und bringt sie zu Fel'Zerul in Stonard.", description = "Also sprach er von Jammal'ans Prophezeiung?\n\nDer spirituelle Anführer der Atal'ai glaubt, wenn Hakkar aus dem Nether nach Azeroth zurückkehrt, wird der Gott dem Stamm der Atal'ai Unsterblichkeit gewähren.\n\nTörichte Arglist, um den Jüngsten Tag schneller herbeizuführen, wenn Ihr mich fragt.\n\nDoch Ihr sagt, der Verbannte sprach von verzauberten Fetischen? Das erfüllt mich mit großer Sorge. Wenn sie wahrhaftig der Schlüssel zu dem Ritual der Atal'ai sind, das dieses Durcheinander verursachte, müssen wir die Mächte verstehen, die in ihnen wohnen.\n\nBegebt Euch in den Tempel und werdet dieser Fetische habhaft!", progress = "Wenn die Fetische der Atal'ai die Macht besitzen, Hakkar zu beschwören und Jammal'ans Prophezeiung zu erfüllen, müssen wir sie haben. Die Horde muss solche Mächte verstehen!", completion = "Tapferer &lt;Klasse&gt;, Ihr habt Euch als ein großer Held der Horde erwiesen.\n\nWir müssen uns unverzüglich um diese Fetischsammlung von Hakkar kümmern!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nWächtertalisman"},
[1446] = {title = "Jammal'an der Prophet", objective = "Der Verbannte der Atal'ai im Hinterland möchte den Kopf von Jammal'an.", description = "Meine Gefährten aus Witherbark mögen keine Fremden in ihrer Nähe.\n\nIch? Ich habe keine Heimat mehr. Mein Volk, der große Stamm der Atal'ai aus den Sümpfen des Elends, hat mich verbannt.\n\nJammal'an, unser spiritueller Anführer, hatte eine, wie wir uns ausdrücken, Prophezeiung. Er glaubt, die Beschwörung des Gottes Hakkar bringt den Atal'ai Unsterblichkeit.\n\nIch jedoch drängte auf Vorsicht. Wenn die Prophezeiung nun nichts weiter als Manipulation war?\n\nIch will Rache für meine Verbannung. Bringt mir Jammal'ans Kopf. Vielleicht ist mein Volk dann frei.", progress = "Sobald Jammal'an nicht mehr ist, habe ich die Chance, zu meinem Volk zurückzukehren.\n\nMit Jammal'an als ihrem spirituellen Anführer ist der Untergang der Atal'ai gewiss.", completion = "Jammal'ans blindes Vertrauen in falsche Visionen führte mein Volk in die ewige Verdammnis.\n\nIch danke Euch, &lt;Klasse&gt;, dass Ihr meine Verbannung gerächt habt. Ich trauere um mein Volk. Jetzt habe ich keine Heimat mehr.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRegenschreiter-GamaschenHelm des Banns\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1447] = {title = "Der vermisste Diplomat", objective = "Besiegt Dashel Stonefist in Stormwind.", description = "Ja, <Klasse>, Ihr seid offenkundig nicht einer der Klügsten Eurer Art, der je nach Stormwind kam, aber einer der Dümmsten, wenn Ihr nicht wieder fortgeht.\n\nHabt Ihr meine Freunde getroffen?", progress = "Ich dachte mir nichts bei der Bemerkung, dass Ihr dumm seid, <Klasse>. Wir sind Freunde, oder? Nichts für ungut?", completion = "Es gibt also einen Grund, dass Ihr zu mir kommt. Was ist Euer Begehr?", rewards = "Ihr bekommt:\n\n"},
[1448] = {title = "Auf der Suche nach dem Tempel", objective = "Brohann Caskbelly in Stormwind möchte, dass Ihr den Tempel von Atal'Hakkar sucht.", description = "Es gab eine Zeit, da war ich jung und voller Kraft, wie Ihr, <Klasse>.\n\nDoch jetzt bin ich alt und vermag die Welt nicht mehr zu erforschen wie einst. Ach, was habe ich nicht alles gesehen!\n\nAber ein Geheimnis entzog sich mir stets. Als meinen letzten Auftrag schickte mich die Forscherliga auf die Suche nach dem Tempel von Atal'Hakkar. Er sollte Gerüchten zufolge in den Sümpfen des Elends liegen.\n\nMeines gebrechlichen Zustands wegen reiste ich auf einem Greif durch die Lüfte, fand den Tempel aber nie.\n\nHelft Ihr einem alten Zwerg? Vielleicht habt Ihr zu Fuß mehr Glück.", progress = nil, completion = "Der Tempel von Atal'Hakkar ist im Tränenteich versunken? Und vom grünen Drachenschwarm umzingelt?\n\nEine erstaunliche Entdeckung, &lt;Klasse&gt;. Aber offenkundig ist etwas furchtbar schief gegangen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1449] = {title = "Ins Hinterland", objective = "Sprecht mit dem obersten Than, Falstad Wildhammer, in Aerie Peak im Hinterland.", description = "Wie ich schon früher sagte, versuchte ich selbst, den Tempel aus der Luft zu finden. Ganz allein war ich freilich nicht.\n\nIch reiste zu dem berühmten Greifenhorst bei Aerie Peak im Hinterland. Dort versicherte ich mich der Hilfe eines ihrer besten Piloten. Der Pilot fiel von seinem Reittier in den Sumpf ...\n\nDen Namen des armen Burschen habe ich im Alter vergessen. Der Meister des Horsts kennt ihn zweifellos noch.\n\nBegebt Euch dorthin und sucht nach Falstad Wildhammer.\n\nWir müssen herausfinden, was dem Piloten zugestoßen ist.", progress = nil, completion = "Was wollt Ihr, Jüngelchen? Seht Ihr denn nicht, dass ich mich hier um Probleme kümmern muss? Wer hat schon Zeit, hier rumzustehen und mit einer Quasselstrippe von &lt;Volk&gt; zu plaudern?\n\nEs kommen Trolle aus dem Unterholz! Fasst Euch kurz.", rewards = "Ihr bekommt:\n\n"},
[1450] = {title = "Greifenmeister Talonaxe", objective = "Sprecht mit Greifenmeister Talonaxe im Horst bei Aerie Peak.", description = "Ihr seid also nur ein <besserer Botenjunge/besseres Botenmädchen> für einen alten Tattergreis der Forscherliga, hm?\n\nHört mir gut zu, <Klasse>. Ich habe keine Ahnung, mit wem Euer alter Kumpel da unten in Azeroth rumgeflogen ist. Seh ich etwa wie der Greifenmeister Talonaxe aus? Ja?\n\nWenn Ihr Euch für die Flugpläne interessiert, warum fragt Ihr dann nicht den Greifenmeister? Wenn Ihr noch länger untätig hier herumhängt, werde ich Euch richtige Arbeit geben.\n\nUnd jetzt trollt Euch.", progress = nil, completion = "Ah, ja. Natürlich erinnere ich mich, wie ich einen meiner Greifenreiter ausschickte, um Brohann Caskbelly zu helfen.\n\nIch hatte immer schon eine Schwäche für die Forscherliga. Mein Vater half sogar bei der ersten Ausgrabung mit, die Uldaman fand.\n\nIch schickte damals den Greifenreiter mit Brohann, den ich für den besten hielt. Der Bursche hörte auf den Namen Rhapsody Shindigger.\n\nWas war der für ein Greifenreiter! Jedenfalls bis ...", rewards = "Ihr bekommt:\n\n"},
[1451] = {title = "Rhapsody-Shindigger", objective = "Sucht Rhapsody Shindigger im Hinterland.", description = "Rhapsody fand Gefallen am Schnaps. Versteht mich nicht falsch - alle Zwerge hier im Horst wissen ein gutes Bier zur passenden Stunde zu schätzen.\n\nAber der alte Shindigger brauchte den Fusel wie ein Greif den Himmel. Und das war echt ein Jammer. Niemand konnte so fliegen wie Rhapsody.\n\nDie ersten Probleme gab es, als er mit Eurem Freund Brohann von dieser Mission zurückkehrte. Danach ging es rapide bergab. Musste ihn rauswerfen.\n\nZuletzt hörte ich, er habe östlich von hier eine Brauerei eröffnet ...", progress = nil, completion = "Hicks!\n\nIch seh Euch gerade an, aber Ihr hüpft immerzu auf und ab. Das macht mich ganz schwindelig. Hoho!\n\nHicks!\n\nBoah! Habt Ihr das gespürt? Die Erde bebt. Ich muss was trinken.\n\nHicks!", rewards = "Ihr bekommt:\n\n"},
[1452] = {title = "Rhapsodys Kalimdor-Cocktail", objective = "Rhapsody Shindigger im Hinterland möchte, dass Ihr ihm 3 Muskelmägen eines Roc, 3 Groddoc-Lebern und 3 Eisenfelllebern bringt.", description = "Hicks!\n\nDieser irre Narr Brohann schickt Euch also? Wir haben ein tolles Abenteuer zusammen erlebt... Hicks!\n\nWenn ich Euch erzählen soll, was da unten im Sumpf passiert ist, brauch ich was Ordentliches zu trinken. Das war echt kein schöner Anblick. Hicks!\n\nIch sag Euch was... bringt mir, was ich brauche, um einen Kalimdor-Cocktail zu mixen, dann erzähl ich Euch davon.\n\nMan braucht dazu den Muskelmagen eines Roc aus Tanaris... etwas Groddoc- und Eisenfellleber aus Feralas...\n\nEin schöner kräftiger Kalimdor-Cocktail... dann kann ich plaudern!", progress = "Schon mal ein Rhapsody-Malzbier getrunken? Eines meiner besten Gebräue, wenn ich das so sagen darf. Hicks!\n\nAber wenn ich den Schrecken dieses Fluges über... hicks... den Sumpf noch mal durchleben soll, brauch ich was deutlich Stärkeres. Hicks!\n\nIhr habt wohl nicht zufällig die Muskelmägen und Lebern gefunden, die meinem Kalimdor-Cocktail den richtigen Pfiff geben?\n\nHicks!", completion = "Wie ich sehe, habt Ihr mir mühelos beschafft, was ich brauche! War bestimmt nicht leicht für Euch im fernen Kalimdor.\n\nDauert nur einen Moment, bis ich aus den Muskelmägen und Lebern extrahiert habe, was ich brauche. Hicks!\n\nDann kann ich mir einen starken Drink brauen und Euch endlich erzählen, was Ihr wissen wollt.\n\nHicks!\n\nWenn ich nur an den ollen Sumpf denke, krieg ich 'ne Gänsehaut.\n\nHicks!\n\nIch werd den Drink schnell zusammenrühren.", rewards = "Ihr bekommt:\n\n"},
[1453] = {title = "Die Geschäfte der Wiederholer in Desolace", objective = "Sprecht mit Kreldig Ungor in Desolace.", description = "Es gibt Arbeit in Desolace, <Name>. Das ist ein grässlicher Ort, beschmutzt von Zentauren und anderer Unbill. Aber wenn Ihr eine Woche ehrlicher Arbeit sucht, dann geht dorthin, besucht Kreldig Ungor und sagt ihm, ich hab Euch geschickt.\n\nIhr findet ihn an der Nijelspitze - dem gemütlichen kleinen Lager in den Bergen des nördlichen Desolace. Haltet Euch einfach ostwärts, wenn Ihr vom Steinkrallengebirge kommt. Man übersieht es leicht, also seid wachsam.", progress = nil, completion = "Schön zu sehen, dass die Wiederbeschaffer nicht knapp an Arbeit oder Abenteurern sind, die ihnen aushelfen wollen.\n\nIch bin Kreldig, &lt;Name&gt;. Es war eine kluge Entscheidung, den Wiederbeschaffern zu helfen. Heutzutage braucht jeder irgendetwas: Die Leute verlieren ein Familienerbstück, einen magischen Gegenstand oder einen geliebten Menschen. Es ist schon recht erstaunlich. Aber wenn die Wiederbeschaffer in der Gegend sind, gibt es keinen Grund, warum nicht jeder für einen angemessenen Preis wiederbekommen sollte, was er verloren hat.", rewards = "Ihr bekommt:\n\n"},
[1454] = {title = "Karnitols Schiffbruch", objective = "Sucht Karnitols Truhe in Desolace.", description = "Mein erster Auftrag betrifft den Magier Karnitol - eine Art Edelmann in Stormwind. Offenbar wurde sein Schiff vor der Küste im Nordwesten von Meeresriesen angegriffen. Er und seine Gefolgsleute versuchten, eine seiner wertvolleren Truhen an Land zu bringen, aber als die Meeresriesen in Schwärmen angriffen, beschloss er, sie aufzugeben und sich und seine Gefolgsleute in Sicherheit zu teleportieren.\n\nEr möchte, dass wir die Truhe samt ihrem Inhalt finden und zu ihm nach Stormwind bringen.", progress = nil, completion = "Ihr bemerkt, dass die Truhe keine Wasserschäden genommen hat.\n\nAls Zweites bemerkt Ihr, dass der Deckel aufgebrochen wurde. Eventuelle magische Fallen, die der Sicherung dienten, wurden längst ausgelöst - das erkennt man an den Brandspuren an den Kanten.", rewards = "Ihr bekommt:\n\n"},
[1455] = {title = "Karnitols Schiffbruch", objective = "Kehrt zu Kreldig Ungor in Desolace zurück.", description = "Ihr überlegt eine Weile, was die Kiste aufgebrochen haben könnte, und bemerkt an den Seiten und am Deckel lange, tiefe Kratzer, die belegen, dass sich etwas anderes als ein Mensch oder Riese dafür interessierte. Solche Spuren scheinen nicht von einem Dolch oder Schwert verursacht worden zu sein.\n\nIhr werft einen Blick in die Truhe und stellt fest, dass sie leer ist.\n\nDa Ihr nicht wisst, was Ihr sonst tun sollt, klappt Ihr die Truhe zu und rüstet zum Aufbruch. Kreldig wird enttäuscht sein.", progress = nil, completion = "Willkommen in der Nijelspitze, &lt;Name&gt;. Sagt mir, was Ihr gefunden habt.\n\nWas!? Nichts? Ich fürchte, eine leere Truhe bringt uns keinen Lohn ein.\n\nErzählt mir mehr von diesen Spuren, die Ihr gesehen habt... diesen Rillen.", rewards = "Ihr bekommt:\n\n"},
[1456] = {title = "Karnitols Schiffbruch", objective = "Sucht Karnitols Ranzen und bringt ihn zu Kreldig Ungor in Desolace zurück.", description = "Faszinierend.\n\nVielleicht besteht ja doch noch Hoffnung.\n\nAn derselben Küste, aber viel weiter nördlich, nahe der Insel Ranazjar, liegen Ruinen der Nachtelfen auf dem Grund des Meeres. Ein Stamm von Naga, die Zackenkämme, sind dort zu Hause. Das dürfte unsere beste Chance sein.\n\nWenn ein Kundschaftertrupp sich so weit in den Süden wagte, müssen sie sehr mächtig sein. Wenn Ihr Kanitols Habseligkeiten finden wollt, würde ich mit den mächtigeren Naga anfangen: den Gezeitenjägern oder den Meerhexen.", progress = "Nicht, dass ich Nijel zu nahe treten wollte, wer immer das sein mag, aber dieses Lager ist nicht das bequemste, in dem ich je eine Nacht verbrachte, <Name>.", completion = "Das ist toll, &lt;Name&gt;! Ihr habt Karnitols Habseligkeiten gefunden!\n\nDiese elenden Naga machen ständig Ärger. Ich würde lieber mein Leben lang Krieg gegen die Horde führen als gegen ihre Art anzutreten. Ihr habt den Wiederholern einen großen Dienst erwiesen.", rewards = "Ihr bekommt:\n\n"},
[1457] = {title = "Karnitols Schiffbruch", objective = "Bringt Karnitols Ranzen zu Roetten Stonehammer in Ironforge.", description = "Bringt Karnitols Sachen zu Roetten in Ironforge, er wird Euch die gute Arbeit wohl vergelten.\n\nHaha, wenn Ihr nicht aufpasst, wird er so zufrieden sein, dass er Euch bittet, als Festangestellter bei uns zu bleiben.\n\nWieder einmal gut gemacht, <Name>.\n\nSeid auf dem Rückweg vorsichtig und lasst Euch nicht zu viel Zeit - Karnitol ist nicht der Geduldigste, aber dennoch höchst großzügig.", progress = "Das Geschäft blüht, <Name>, und ich habe nicht viel Zeit für Fragen. Wenn Ihr etwas von den Wiederholern wollt, rückt heraus damit. Wenn nicht, muss ich Euch bitten, mit einem meiner Handlanger zu sprechen. Sie sind durchaus imstande, sich um alles hier zu kümmern.", completion = "Ah, die Karnitol-Angelegenheit in Desolace. Exzellent!\n\nDie Truhe wurde also zerstört, aber die Gegenstände sind alle da, hm? Tja, das soll er selbst nachprüfen. Ein Gutes hat das Geschäft, das ich hier betreibe: Wenn er nicht zufrieden ist, kann ich ihm sagen, er soll in den Wind schießen! Die Leute erwarten von uns, dass wir ihr Zeug finden ... und nicht, dass alles in perfektem Zustand ist, wenn sie es zurückerhalten.\n\nGute Arbeit, &lt;Name&gt;. Dann wollen wir Euch mal Euren Lohn geben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHellion-StiefelBlutbadschulterstücke\n\nIhr bekommt außerdem:\n\n"},
[1458] = {title = "Reagenzien für die Wiederholer AG", objective = "Bringt 10 Zornsäerklauen und 10 Zornsäerhörner zu Kreldig Ungor in Desolace.", description = "Zu meinen Pflichten hier gehört, Reagenzien für Leftwitch zu beschaffen, einen Gnomen-Magier in Kharanos. Roetten glaubt, das sei ein Kinderspiel, da wir ohnehin schon hier draußen sind. Ihm ist es gleich, dass wir auch so schon unterbesetzt sind.\n\nDie ersten paar Gegenstände auf seiner Liste sollten leicht zu beschaffen sein, und für alle, die mir helfen, springt eine satte Belohnung raus.\n\nIch brauche einige Hörner und Klauen von den Satyrn der Zornsäer östlich von hier. Bringt sie mir, dann nehmen wir uns den Rest der Liste vor.", progress = "Abscheuliche Kreaturen, die Satyrn. Man sagt, sie seien irgendwie mit den Nachtelfen verwandt, doch das glaube ich nicht.\n\nIch glaube, das liegt nur an dem einen Elfen, der sie vor Jahren überredete, in den Krieg zu ziehen. Das hat die Welt für immer verändert. Heute ist sie viel gefährlicher und Furcht erregender.", completion = "Gut, gut, &lt;Name&gt;. Ich bin nicht sicher, ob die Qualität ausreicht, aber wenn Leftwitch eine bestimmte Art wollte, hätte er es genauer sagen müssen, ehe er die Wiederholer losschickte.\n\nGehen wir zum nächsten Gegenstand auf der Liste, ja?", rewards = "Ihr bekommt:\n\n"},
[1459] = {title = "Reagenzien für die Wiederholer AG", objective = "Bringt 7 Phiolen Skorpashigift und 3 Bälge von gealterten Kodos zu Kreldig Ungor in Desolace.", description = "Als Nächstes steht auf Leftwitchs Liste... mal sehen... hmm. Oh, da haben wir es.\n\nRecht einfach, aber mit sehr expliziten Anweisungen. Er braucht Gift von den Skorpashi und Bälge von Kodos. Im Kleingedruckten steht, beide müssen von bestimmten Kreaturen sein: Das Gift soll von irgendeinem Skorpashi stammen und der Balg muss von einem gealterten Kodo sein, aber keinem sterbenden oder uralten.\n\nMagier, ich sage Euch, was die so alles wollen... abartig.", progress = "Entschuldigt, dass ich Euch nicht sagen konnte, wo man Kodos oder Skorpashi findet. Ich kenne mich in der Gegend nicht gut aus und hatte keine Zeit, sie zu erkunden.", completion = "Eure Hilfe hier ist unschätzbar, &lt;Name&gt;. Durch Euch muss ich nur die halbe Zeit in Desolace verbringen. Mit Eurer Hilfe bin ich im Handumdrehen wieder in Ironforge und wärme mir die Füße.\n\nWenn wir die Liste abgehakt haben und ich wieder zu Hause bin, schaut mal rein, ich spendiere Euch ein Bier.\n\nAber bis dahin sollten wir die restlichen Reagenzien sammeln.", rewards = "Ihr bekommt:\n\n"},
[1462] = {title = "Erdsapta", objective = "Sprecht mit der Seherin Ravenfeather wegen eines weiteren Erdsaptas.", description = nil, progress = nil, completion = "Nehmt dies und vergesst nicht, es ist heilig.", rewards = "Ihr bekommt:\n\nErdsapta"},
[1463] = {title = "Erdsapta", objective = "Sprecht mit Canaga Earthcaller wegen eines weiteren Erdsaptas.", description = nil, progress = nil, completion = "Ich gebe Euch voller Vertrauen einen. Ihr habt Euren Wert schon einmal bewiesen, doch ich finde, künftig solltet Ihr vorsichtiger sein.", rewards = "Ihr bekommt:\n\nErdsapta"},
[1464] = {title = "Feuersapta", objective = "Sprecht mit Telf Joolam wegen eines weiteren Feuersaptas.", description = nil, progress = nil, completion = "Möge Feuer in Eurem Herzen brennen, &lt;Name&gt;.\n\nDie Elemente erwarten Euch.", rewards = "Ihr bekommt:\n\nFeuersapta"},
[1465] = {title = "Vahlarriels Suche", objective = "Kehrt mit dem Malem-Anhänger zu Vahlarriel Demonslayer in Desolace zurück.", description = "Als Ihr Eure Suche nach dem Wagen fortsetzt, findet Ihr nicht nur einen Anhänger, sondern auch Fußspuren, die in Richtung Süden führen. In der Ferne seht Ihr Rauch von einem großen Fort aufsteigen. Der Rauch stammt von einem Lagerfeuer, nicht von brennenden Gebäuden. Euer Instinkt sagt Euch, dass die Malems, wenn sie noch leben, in diese Richtung gebracht wurden.\n\nIhr seid der Ansicht, dass Vahlarriel an der Nijelspitze nicht nur den Anhänger sehen sollte, den Ihr gefunden habt, sondern auch von den Lebenszeichen im Süden wissen sollte.", progress = nil, completion = "Zum Auswachsen! Dieses ganze Fiasko!\n\nDie beiden waren gewarnt, wie gefährlich es sein würde, hierher zu kommen. Nun werden sie vermisst... oder Schlimmeres.\n\nIhr sagt, Ihr habt Spuren zu einem Fort in der Nähe gesehen? Das dürfte unsere beste Chance sein.\n\nSchenkt man den Einheimischen Glauben, wimmelt es in dieser Festung von Orcs der Burning Blade, die sich dämonischen Mächten verschrieben haben. Sie teilen vielleicht nicht die meisten Ansichten der Horde, sind aber böse und töten ohne Umschweife, wenn sie jemanden beim Spionieren erwischen.", rewards = "Ihr bekommt:\n\n"},
[1466] = {title = "Reagenzien für die Wiederholer AG", objective = "Bringt 10 Teufelshundgehirne, 10 Netherflügel und 10 Phiolen Verdammniswächterblut zu Kreldig Ungor in Desolace.", description = "Das ist der letzte Gegenstand und ganz ehrlich, er ist nicht schön. Ich gehe auch davon aus, dass Ihr dafür etwas länger braucht als für die anderen Gegenstände.\n\nDoch genug der Warnungen, fangen wir an. Leftwitch sagt, er braucht Folgendes: zehn Gehirne, entweder von Manafressern, Magierjägern oder Leyjägern, zehn Netherflügel von einer Nethermaid, -Schwester oder -Zauberhexerin. Und... zehn Phiolen Verdammniswächterblut von einem Captain oder Lord der Verdammniswächter.\n\nGanz einfach, hm? Tja... ich hätte Verständnis dafür, wenn Ihr dies ausschlagen wollt.", progress = "Ich wusste nicht einmal, dass es diese Dämonenwesen in Desolace gibt. Zuletzt hörte ich, dass das Land weitgehend den Zentauren gehört, nachdem die Nachtelfen vor Jahren zusammengepackt haben und abgezogen sind.\n\nIch frage mich, warum und wie sie hierher kamen.", completion = "Ehrlich? Das hätte ich nicht gedacht. Ihr seid erstaunlich, &lt;Name&gt;. Es wegen eines Magierexperiments mit Dämonen aufzunehmen und unversehrt zurückzukehren. Gute Arbeit!\n\nWenn ich wieder in Ironforge bin, werde ich Roetten persönlich von Euch berichten.", rewards = "Ihr bekommt:\n\n"},
[1467] = {title = "Reagenzien für die Wiederholer AG.", objective = "Bringt Leftwitchs Päckchen zu Roetten Stonehammer in Ironforge zurück.", description = "Wenn Ihr Eure Bezahlung wollt, müsst Ihr nach Ironforge zurück und persönlich mit Roetten sprechen. Er dürfte froh sein, wenn er Leftwitchs Päckchen vom Hals hat. Gebt ihm das, es müsste genügen, damit Ihr Euren Anteil bekommt.\n\nKeine Bange, ich werde trotzdem ein gutes Wort für Euch einlegen, wenn ich zurück bin. Ich sollte nicht mehr lange in Desolace bleiben müssen.", progress = "Grüße, <Name>. Das Geschäft blüht, die Laute von Hämmern auf Ambossen hallen durch ganz Ironforge, die Blasebälge entfachen das Feuer und meine Frau backt mir einen Kuchen als Dessert nach dem Abendessen. Könnte das Leben schöner sein?", completion = "Ah, das Päckchen für Leftwitch aus Desolace. Exzellent. Ich schätze Eure Arbeit und Eure Pünktlichkeit, &lt;Klasse&gt;. Schön, dass wir Euch wenigstens für diesen kleinen Auftrag an Bord haben.\n\nIch habe Euren Lohn hier. Lasst alle wissen, dass die Wiederholer AG für eine harte Arbeit stets guten Lohn bezahlt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAurum-ArmschienenSturmfeuerstulpen\n\nIhr bekommt außerdem:\n\n"},
[1468] = {title = "Die Kinderwoche", objective = "Benutzt die Pfeife des menschlichen Waisenkindes um während der Kinderwoche mit Eurem Schützling zu sprechen.\n\nBereitgestellter Gegenstand: \n", description = "Ihr wollt uns tatsächlich hier im Waisenhaus zur Hand gehen? Seid gesegnet, Freund. Eure Unterstützung in der Kinderwoche ist für uns von unschätzbarem Wert.\n\nNehmt diese Pfeife. Sie kann sieben Tage lang verwendet werden - über die ganze Dauer der Kinderwoche hinweg. Durch Benutzung der Pfeife, könnt Ihr mit dem Waisenkind sprechen, auf das Ihr aufpasst. Verwendet sie erneut, um das Kind wieder zu entlassen.\n\nDas Kind ist schon ganz aufgeregt und freut sich darauf Euch kennenzulernen. Worauf wartet Ihr noch <Name>, benutzt die Pfeife und trefft Euren Schützling.", progress = nil, completion = "Um... hi. Meine Name ist Randis und ich glaube du suchst nach mir? Ihr seid ein Abenteurer, genauso wie es meine Mama und mein Papa waren. Ich bin so glücklich Euch zu treffen!\n\nHoffentlich erleben wir zusammen viele lustige Sachen. Es gibt so viele Sachen, die ich gerne einmal machen würde und die Matrone hat gesagt, dass Ihr diese Woche so etwas wie mein großer Bruder seid. Das finde ich toll!", rewards = nil},
[1469] = {title = "Rhapsodys Geschichte", objective = "Bringt das Schrifttafelfragment der Atal'ai zu Brohann Caskbelly in Stormwind.", description = "Vor dem Flug trank ich ein ganzes Fass Starkbier. Hicks!\n\nUnd was für ein Flug das war. Ich sauste herum und Brohann folgte mir. Aber ich hab keinen Tempel nicht gesehen. Hicks!\n\nJedenfalls sah ich keinen Tempel, bis mir schwindlig wurde und ich von meinem Reittier fiel. Ich fiel kopfüber ins Wasser und wurde in die Tiefe gesogen. Dort sah ich mich von einer Schar unheimlicher Trolle umringt. Ich schwamm, was das Zeug hielt! Und schaffte es sogar mit diesem Trollsouvenir da raus. Hier, bringt es Brohann und lasst ihn wissen, dass der Tempel tatsächlich da unten ist. Hicks!", progress = "Endlich seid Ihr zurückgekehrt, <Name>. Es ist eine Weile her, seit wir zuletzt miteinander sprachen. Ich dachte schon, Ihr hättet meinen Auftrag an Euch vielleicht vergessen.\n\nHabt Ihr diesen nichtsnutzigen Greifenreiter gefunden? Hatte er etwas zu berichten?", completion = "Rhapsody Shindigger! Genau... wie konnte ich so einen Namen nur vergessen?\n\nEr wusste also die ganze Zeit von dem versunkenen Tempel? Also das hätte Euch gewiss eine Menge Laufarbeit sparen können.\n\nAber dieses Artefakt der Atal'ai! Das nenne ich einen Fund!", rewards = "Ihr bekommt:\n\n"},
[1470] = {title = "Der zerrissene Schleier", objective = "Bringt Venya Marthand 3 Schädel eines klappernden Skeletts.", description = "Seid gegrüßt, Kind. Ich sehe, dass Ihr noch unerfahren in den Dingen der Hexenmeister seid, dass sich die Macht noch Eurem Griff entzieht. Doch ich spüre Euren Eifer zu lernen.\n\nUnd Ihr werdet lernen.\n\nDurch Ignoranz kann man keine Stärke finden. Wissen ist unsere größte Macht. Indem wir es anwenden, können wir die chaotische Magie und die Wesen der Leere kontrollieren und unserem Willen beugen.\n\nIch zeige Euch, wie Ihr einen Diener an Euren Willen bindet, doch zuerst müsst Ihr mir drei Schädel der klappernden Skelette nahe der verlassenen Schmiede bringen.", progress = "Eure Macht ist noch gering, doch ich vermute, Ihr ahnt die Möglichkeiten bereits.\n\nMit der Macht, die uns durchströmt, könnten selbst Tote sich lebendig fühlen.", completion = "Wiewohl Ihr noch unerfahren und am Anfang des Lernens seid, habt Ihr bewiesen, dass Ihr hinreichend Fähigkeiten besitzt, das Beschwören und Binden eines Wichtels zu meistern. Lasst Euch nicht von der Größe eines Wichtels täuschen. Ihm fehlt es zwar an Körperkraft, aber dafür besitzt er Macht und Klugheit, die Euch dienlich sein werden.\n\nHört mir gut zu, &lt;Name&gt;, denn ich werde diese Lektion nicht wiederholen und überlasse es Euch, sie zu meistern.", rewards = "Ihr erlernt:\n\nWichtel beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWichtel beschwören' lehren\n\nIhr bekommt außerdem:\n\n"},
[1471] = {title = "Die Bindung", objective = "Beschwört mit Hilfe der Runen der Beschwörung einen Leerwandler, unterwerft ihn und bringt die Runen der Beschwörung dann zu Carendin Halger im Tempel der Verdammten zurück.", description = "Gewiss habt Ihr den Kreis der Beschwörung unter uns bemerkt. Nur dort könnt Ihr einen ungebundenen Leerwandler herbeirufen.\n\nMit diesen Runen könnt Ihr ihn herbeirufen, dann müsst Ihr ihn durch die Kraft von Waffen und Magie beherrschen.\n\nWenn er unterworfen wurde, wird er Euch ergeben sein. Kommt dann zu mir und ich werde den Beschwörungszauber erklären, damit er Euch in jeder Hinsicht zu Willen ist.", progress = "Ich erwarte, von Eurem Erfolg zu hören, <Name>. Doch solltet Ihr scheitern, wird es Eure geringste Sorge sein, dass Ihr meinen Erwartungen nicht entsprochen habt.", completion = "Ihr habt Eure Sache gut gemacht, &lt;Name&gt;. Jetzt will ich Euch den Zauber verraten, mit dem der Leerwandler beschworen wird.\n\nDie Macht, die er freisetzt, steht nun zu Eurer Verfügung. Benutzt sie weise.", rewards = "Ihr erlernt:\n\nLeerwandler beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\nLeerwandler beschwören' lehren\n\nIhr bekommt außerdem:\n\n"},
[1472] = {title = "Verschlinger der Seelen", objective = "Sprecht mit Godrick Farsan im Tempel der Verdammten.", description = "Ein Sayaad ist ein Verschlinger von Seelen, Bezwinger des Willens, Versucher der Herzen. Eine durch und durch böse und engstirnige Kreatur.\n\nDie Rechtschaffenen wie auch die Boshaften erzählen Geschichten über sie und verwenden dabei ihre bekannteren Namen: Sayaad in weiblicher Gestalt heißen Sukkubus, in männlicher Gestalt Inkubus.\n\nDer Dämon muss mit einem Anreiz in unsere Welt gelockt werden: den Herzen reiner und liebender Sterblicher. Diesen können Sayaad nicht widerstehen. Dann könnt Ihr sie beherrschen und zu Eurem Eigen machen.\n\nSprecht mit meinem Assistenten Godrick Farsan im Tempel. Er hilft Euch bei der Suche nach einem Köder.", progress = nil, completion = "Hat Carendin Euch geschickt? Nun gut, &lt;Name&gt;.\n\nSchätzt mich nicht gering, weil mein Augenlicht erloschen ist. Ich sehe jetzt mit ungeahnter Klarheit Dinge, die mir verborgen waren. Was ich einst als Fluch erachtete, ist jetzt ein Segen.", rewards = "Ihr bekommt:\n\n"},
[1473] = {title = "Kreatur der Leere", objective = "Beschafft Egalins Zauberfolianten und bringt ihn zu Carendin Halgar in den Tempel der Verdammten.", description = "Alle scheinen sich einig, dass Ihr nunmehr bereit seid zu lernen, wie man einen Leerwandler beschwört.\n\nEin aus dem jenseitigen Chaos erschaffenes Wesen - wenn Ihr eines beschwört, es aber nicht kontrollieren könnt, zerreißt es Euch.\n\nEgalin beschwor den ersten Leerwandler und hielt in seinem Zauberfoliant fest, wie es bewerkstelligt wird.\n\nLeider wurde er uns von einem Agenten des Scharlachroten Kreuzzugs gestohlen, der ihn in seinem Stützpunkt in einem Turm im Westen versteckte. Bringt ihn mir und ich lehre Euch das Wissen.", progress = "Egalin war der Lehrmeister, der mich unterrichtete. Er vermochte den Leerwandler, den er beschworen hatte, fast nebenbei zu kontrollieren.\n\nAls ich an der Reihe war, es zu versuchen, überschätzte ich mich. Spielt nicht mit den Mächten, die Ihr besitzt, <Name>, sie können selbst den Wachsamsten verzehren.", completion = "Ah, das ist ausgezeichnet. Vermutlich hatte Perrine keine Ahnung von der wahren Macht des verstaubten Buches, das er uns gestohlen hatte.\n\nEs wird uns nicht noch einmal genommen werden. Studiert die Struktur des Zaubers, &lt;Name&gt;, und die Art und Weise, auf die Eure Macht kanalisiert werden muss.", rewards = "Ihr bekommt:\n\n"},
[1474] = {title = "Die Bindung", objective = "Beschwört mit Hilfe der reinen Herzen einen Sukkubus, unterwerft ihn und bringt die reinen Herzen dann zu Carendin Halger im Tempel der Verdammten zurück.", description = "Benutzt diese Herzen und wirkt einen Zauber am Beschwörungskreis, um eine Tür zu öffnen, durch die der Sukkubus kommen kann. Eure Mächte sind jetzt größer und Ihr werdet sie alle brauchen, um den Sukkubus zu besiegen. \n\nHütet Euch vor seinen Bezauberungen, <Name>, manch starker Geist wurde schon seinem Willen unterworfen. Wenn er überwunden wurde, kehrt der Sukkubus in die Leere zurück, dann lehre ich Euch den Zauber, um ihn nach Eurem Gutdünken zurückzurufen.", progress = "Von den Mächten jenseits der Leere ist der Sukkubus eine der gefährlichsten, da er die Schwachen leicht um den Finger wickeln kann.\n\nDenkt jetzt und immerzu daran.", completion = "Wieder habt Ihr Eure Sache gut gemacht, &lt;Name&gt;. Es ist eine Weile her, seit ich einen jungen &lt;Klasse&gt; mit so viel Potenzial wie Euch gesehen habe. Seid versichert, dass ich Eure Fortschritte im Auge behalten und Euch bei künftigen Prüfungen vorbereiten und unterstützen werde.\n\nJetzt will ich Euch den Beschwörungszauber für den gerade von Euch unterworfenen Sukkubus zeigen.", rewards = "Ihr erlernt:\n\nSukkubus beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSukkubus beschwören' lehren\n\nIhr bekommt außerdem:\n\nKleiner Seelenbeutel"},
[1475] = {title = "Im Tempel von Atal'Hakkar", objective = "Sammelt 10 Schrifttafeln der Atal'ai für Brohann Caskbelly in Stormwind.", description = "Der Legende zufolge ist der Tempel von Atal'Hakkar ein heiliger Schrein, der dem alten Gott Hakkar dem Seelenschinder geweiht ist. Der Tempel, der von einem tückischen Trollstamm namens Atal'ai unterhalten wird, soll angeblich uneinnehmbar sein.\n\nDa der Tempel jetzt im Tränenteich versunken ist, dürfte es noch schwieriger sein, Artefakte zu bergen. Aber genau das müsst Ihr tun, <Name>.\n\nHelft mir dabei, indem Ihr die intakten Schrifttafeln der Atal'ai sammelt. Bringt sie mir und ich schicke der Forschergilde einen Helden zurück. Wir werden uns den Ruhm teilen.", progress = "Da sich langsam das Dunkel über meine Laufbahn senkt, wende ich mich an Euch, <Name>, damit Ihr mir bei meinem letzten Auftrag für die Forscherliga helft. Wenn meine alten Knochen genug Kraft hätten, die Sümpfe des Elends und den versunkenen Tempel zu meistern, würde ich an Eurer Seite kämpfen.\n\nMein Stolz macht es mir schwer, Euch um Eure Hilfe beim Sammeln der Schrifttafeln der Atal'ai zu bitten. Doch das hohe Alter schließt andere Möglichkeiten aus.\n\nBitte helft mir, <Name>. Ich möchte erst aus der Forscherliga ausscheiden, wenn ich ihre letzte Bitte erfüllt habe.", completion = "Die Schrifttafeln der Atal'ai! Ich danke Euch, &lt;Name&gt;!\n\nWenn ich sie der Forscherliga übergeben habe, werden unser beider Namen in die Geschichte eingehen. Ihr habt einem alten Zwerg geholfen, die letzte Verpflichtung seines Lebens zu erfüllen. Dafür bin ich Euch ewig dankbar.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nWächtertalisman"},
[1476] = {title = "Herzen der Reinen", objective = "Bringt die Herzen von Dalin Forgewright und Corma Villard zu Carendin Halgar im Tempel der Verdammten.", description = "Einen Sukkubus anzulocken, erfordert ein reines Herz. Aber gibt es denn Sterbliche, die frei von Sünde sind?\n\nAnhand von Bruchstücken zufällig mitgehörter Geschichten habe ich zwei Menschen gefunden, die genügen sollten.\n\nDer Erste ist Dalin Forgewright, der sich der Fürsorge für die Flüchtlinge von Lordaeron verschrieben hat, die von ihresgleichen am Greymane-Wall verstoßen werden.\n\nDer andere ist Corma Villard, eine Frau, die ihrer verlorenen Liebe treu bleibt und im Sumpfland nach Spuren von ihr sucht.\n\nBringt ihre Herzen zu Carendin. Doch zuvor möchte ich Euch Eure Opfer zeigen.", progress = "Das Tempo Eurer bisherigen Fortschritte überrascht mich angenehm, <Name>. Bringt mir die Herzen und Ihr werdet mich abermals beeindrucken.", completion = "Wenn man das Herz eines gütigen Menschen so sieht, schaut es aus wie alle anderen auch, findet Ihr nicht?\n\nVielleicht haben wir eine... andere... Sichtweise auf die Dinge. Aber diese werden genügen. Ich zweifle nicht, dass ein Sukkubus von ihrer Reinheit angelockt wird.", rewards = "Ihr bekommt:\n\n"},
[1477] = {title = "Überaus wichtige Vorräte", objective = "Sprecht mit Wachhauptmann Sorigal.", description = "Unsere Magier führen Forschungen in der Burg Nethergarde in den verwüsteten Landen durch, die entscheidend für unser Verständnis der dunklen Portale sind. Sie benötigen fast ununterbrochen Nachschub, doch unsere Nachschubwege nach Nethergarde sind dürftig.\n\nIhr müsst helfen sicherzustellen, dass der Nachschub nach Nethergarde gelangt. Meldet Euch bei Wachhauptmann Sorigal in Dunkelhain und tut, was er verlangt. Diese Aufgabe führt Euch in Feindesland, <Name>. Macht Euch bereit.", progress = nil, completion = "Andromath schickt Euch? Sehr gut. Ich habe eine wichtige Aufgabe für Euch...", rewards = "Ihr bekommt:\n\n"},
[1478] = {title = "Halgars Beschwörung", objective = "Sprecht mit Carendin Halgar in Undercity.", description = "Ah, <Name>! Carendin Halgar ließ mich soeben wissen, dass er Euch für weitere Ausbildung sehen möchte.\n\nIhr solltet stolz auf Euch sein, <Name> Es kommt nicht jeden Tag vor, dass Meister Halgar persönlich einen jungen Hexenmeister unterrichtet.\n\nIhr findet ihn im Magieviertel von Undercity nahe des Tempels der Verdammten.", progress = nil, completion = "Gut, wie ich sehe, konnte Ageron Euch finden, &lt;Name&gt;. Vergeuden wir keine Zeit mit müßigem Geplauder und Höflichkeiten, sondern konzentrieren wir uns auf die Ausbildung. Ihr habt immer noch viel zu lernen.", rewards = "Ihr bekommt:\n\n"},
[1479] = {title = "Der Baum der Ewigen", objective = "Begleitet Euren Schützling zur Bank in Darnassus. Die dortige Bank ist in einen Baum gebaut, welcher als der Baum der Ewigen bekannt ist.", description = "Ich habe Geschichten von den Nachtelfen gehört, darüber das sie ihre Bank in einen Baum gebaut haben, der aber wie ein Bär aussieht. Das ist so cool! Nachtelfen sind niedlich wie sie die Natur lieben und so, aber Bären sind der Hammer!\n\nWürdest du bitte mit mir den Bärenbaum in Darnassus angucken gehen? Es gibt ein Boot das uns ganz in die Nähe dorthin bringt und es wird auch bestimmt nicht lange dauern. Bitte, bitte, bitte!", progress = nil, completion = "Wow, der Baum der Ewigen ist wieder krasser als ich ihn mir je vorgestellt habe! Ich hätte nie gedacht, dass er so groß ist und hast du die Bäume auf der Spitze gesehen?! Ich frage mich, wie sie die Äste so formen konnten.\n\nDanke, dass du mich nach Darnassus mitgenommen hast, &lt;Name&gt;. Du bist toll!", rewards = "Ihr bekommt:\n\n"},
[1480] = {title = "Der Verderber", objective = "Bringt die geschundene Dämonenhaut nach Desolace zu Maurin Bonesplitter.", description = "Die zerrissene Haut riecht verfault und ist erstaunlich geschmeidig für etwas, das so trocken und zerbrechlich wirkt.\n\nAls Ihr sie aufrollt, könnt Ihr deutlich die roten Zeichen einer Art Sprache auf der einen Seite erkennen. Am unteren Ende der Haut befindet sich ein sehr deutliches Symbol, das Ihr für eine Art Unterschrift haltet.\n\nVielleicht könnte Maurin Euch mehr darüber erzählen?", progress = "Die Burning Blade begreifen langsam, wie schwach sie wirklich sind. Ihre Magie ist jämmerlich, ihre Stärke lachhaft.\n\nIhre einzige Macht kommt von jenen, denen sie dienen, und nicht von einem Verständnis von wahrer Macht und Wissen.", completion = "Hmm, diese Runen stammen tatsächlich von einer Sprache, &lt;Name&gt;, einer alten Sprache. Sie scheinen vage Ähnlichkeit mit der Sprache der Eredun zu haben, doch die Unterschiede sind gewichtig. Wenn ich mich nicht irre, ist dies eine Art von Vertrag... Hier, ja, dieses Symbol ist die Unterschrift eines Dämons: Lord Azrethoc.", rewards = "Ihr bekommt:\n\n"},
[1481] = {title = "Der Verderber", objective = "Bringt Maurin Bonesplitter in Desolace einen Schattenpirscherskalp.", description = "Ich denke, mit den entsprechenden Reagenzien kann ich diesen Dämonenlord finden.\n\nWenn er wirklich so mächtig ist, wie ich vermute, brauche ich gesammelte Gegenstände von tödlichen Kreaturen. Doch Ihr handelt im Namen des Kriegshäuptlings, daher werdet Ihr die Aufgabe gewiss übernehmen.\n\nAls Erstes muss ich jeden Schutzzauber brechen, den er gegen Wahrsagen hat. Daher brauche ich den Skalp eines Satyrs... aber nicht den eines beliebigen Satyrs. Der Skalp muss von einem Schattenpirscher der Zornsäer stammen.\n\nSucht in den antiken Ruinen nordöstlich von Desolace nach ihnen.", progress = "Bringt mir keinen falschen Skalp, <Klasse>. Die falschen Reagenzien würden unseren Tod bedeuten. Der Dämonenlord könnte Kontingenzzauber besitzen, die alle töten, die ihm wahrsagen.\n\nDas Schicksal hat mir schon genug Schmerzen zugefügt.", completion = "Die Schattenpirscher konnten Euch nicht töten, &lt;Klasse&gt;. Eindrucksvoll... höchst eindrucksvoll.\n\nDieser Skalp wird für meinen Zauber genügen. In Eurer Abwesenheit konnte ich einige andere Reagenzien für den Zauber sammeln.\n\nIch bin fast bereit. Ich brauche nur noch einen Fokus für den Zauber... etwas, um ein Bild des Dämonenlords und seines Aufenthaltsortes zu projizieren.", rewards = "Ihr bekommt:\n\n"},
[1482] = {title = "Der Verderber", objective = "Bringt Maurin Bonesplitter in Desolace einen Orakelkristall.", description = "Ein Orakelkristall wäre genau richtig. Die Naga stellen sie her, damit ihre Orakel sie benutzen können.\n\nNordwestlich von hier liegt ein großes Korallenriff vor der Küste, das die Naga als ihre Heimat nutzen, da es so nahe am Ufer liegt. Dort könnt Ihr ihre Orakel finden. Die Zackenkammnaga sind tödlich und reagieren ungnädig auf Euer Eindringen, seid daher vorsichtig und eilt Euch.\n\nWenn Ihr zurückkehrt, suchen wir diesen Dämonenlord Azrethoc.", progress = "Ich bin bereit für den Orakelkristall, <Klasse>. Wenn wir diesen Lord Azrethoc finden und vernichten könnten, würden wir beide in der Gunst des Kriegshäuptlings steigen. Wir wären gut beraten, wenn wir eiligst zusammenarbeiten würden, damit wir unsere Sache voranbringen und in der Gunst des Kriegshäuptlings steigen.", completion = "Ein kostbarer Orakelkristall... makellos... wunderschön. So ist es.\n\nWir sollten unverzüglich beginnen. Unsere oberste Sorge sollte sein, diesen Dämonenlord zu finden. Unsere ganze Konzentration muss darauf gerichtet sein, ihn zu töten.\n\nTretet einen Schritt zurück, &lt;Klasse&gt;, und lasst uns sehen, was dieser Dämon ist und wo wir ihn finden können.", rewards = "Ihr bekommt:\n\n"},
[1483] = {title = "Ziz Fizziks", objective = "Sprecht mit Ziz Fizziks bei der Scherwindklippe.", description = "Die Venture Company stahl viele meiner besten Goblin-Denker, aber von Zeit zu Zeit bekommen wir Gelegenheit, einige zurückzustehlen.\n\nVor einiger Zeit stellte die Filiale der Venture Company im Steinkrallengebirge Gerenzo Wrenchwhistle ein... einen Gnom! Ihr anderer Ingenieur, Ziz Fizziks, war so erschüttert davon, dass er mich anflehte, ihm eine neue Stelle beim Tüftlerverband zu besorgen. Ich gab ihm einige Aufgaben, aber möglicherweise braucht er dabei Hilfe.\n\nVielleicht könntet Ihr mal nach dem Rechten sehen? Er ist am Westrand der Scherwindklippe stationiert.", progress = nil, completion = "Ich dachte, die Bosse der Venture Company wären Sklaventreiber, doch dann traf ich Sputtervalve, den Grausamsten von ihnen!\n\nHa! Aber immer noch besser als arbeitslos zu sein, denke ich... Oder schlimmer, mit diesem Gerenzo zu arbeiten. Wenn Ihr helfen wollt, habe ich etwas für Euch zu tun.", rewards = "Ihr bekommt:\n\n"},
[1484] = {title = "Der Verderber", objective = "Sprecht mit Takata Steelblade in Desolace.", description = "Diese Kreatur ist weitaus gefährlicher als ich dachte. Zweifellos stellt Takata in Frage, dass ich so einer Kreatur gewachsen bin, und es würde ihn in seiner Ehre kränken, wenn er nicht wüsste, was gerade passierte.\n\nSprecht mit dem Schwertkämpfer, sagt ihm, Ihr seid bereit, den Dämon zu erschlagen, wenn er es erlaubt, aber bedrängt ihn nicht zu sehr. Es ist besser, wenn er denkt, dass es seine Idee war.", progress = nil, completion = "Ich wurde Zeuge, was soeben mit Maurin und dem Dämonenlord geschah. Diese Kreatur scheint selbst als Erscheinung mehr Macht zu haben als mein Hexenmeistergefährte. Ich frage mich, ob er der Aufgabe gewachsen ist, das Monster zu besiegen? Es stünde dem Kriegshäuptling besser zu Gesicht, wenn ich selbst ginge, aber angesichts meiner Verantwortung hier würde ich dem Klan Schande machen, wenn ich meine Pflichten hier vernachlässigen würde, um zur eigenen Ehre gegen das Böse zu kämpfen.", rewards = "Ihr bekommt:\n\n"},
[1485] = {title = "Üble Familiare", objective = "Bringt 6 Köpfe schändlicher Familiare zu Ruzan.", description = "Die Hexenmeister, die vor uns kamen, weckten das Misstrauen der Horde. Man toleriert uns zwar, aber man liebt uns nicht.\n\nDas ließ die Hexenmeister freilich nicht näher zusammenrücken, da viele in Abgeschiedenheit leben und ihre Magie allein erforschen. Ich will Euch nicht auf den einen oder anderen Weg führen, sondern nur helfen, reifer zu werden.\n\nBevor ich Euch die Kunst des Beschwörens lehre, bringt mir sechs Köpfe der schändlichen Familiare aus der Höhle im Nordosten.", progress = "Es ist wichtig, dass Ihr die Wesen kontrollieren könnt, die Ihr durch Eure Magie beschwört. Nur wenige interessieren sich für die Lehren der <Klasse>, daher möchte ich Euer Leben nicht gefährden, indem ich Euch etwas lehre, ehe Ihr dazu bereit seid.", completion = "Während Eurer Ausbildung zum &lt;Klasse&gt; werdet Ihr lernen, Wesen vielerlei Arten herbeizurufen. Manchen sieht man es nicht an, aber alle sind nützliche Werkzeuge.\n\nLasst Euch nicht von der geringen Größe eines Wichtels täuschen. Ihr habt zweifellos bemerkt, dass sie dennoch gefährliche Widersacher sind.", rewards = "Ihr erlernt:\n\nWichtel beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWichtel beschwören' lehren\n\nIhr bekommt außerdem:\n\n"},
[1486] = {title = "Deviatbälge", objective = "Nalpak in den Höhlen des Wehklagens möchte 20 Deviatbälge.", description = "Als Naralex tiefer in seinen Alptraum vorstieß, stieg eine seltsame Schar von Bestien unter dem Brachland in die Höhlen des Wehklagens vor.\n\nDiese Deviatkreaturen haben seltsame, überirdische Eigenschaften. Sie sind zwar von Natur aus böse, doch bin ich der Meinung, dass ihre Existenz hier in Kalimdor auch etwas Gutes haben kann. Ich glaube, ihre Bälge sind besonders gut für die Lederverarbeitung geeignet.\n\nWenn Ihr Euch der Aufgabe gewachsen fühlt, steigt in die Höhlen unter uns hinab und holt einige Deviatschuppen.", progress = "Ich bin sehr daran interessiert, die Bälge der Deviatkreaturen zu untersuchen, die sich in diesen Höhlen eingenistet haben. Konntet Ihr einige beschaffen, <Klasse>?", completion = "Eure Bemühungen bei der Beschaffung dieser Bälge werden nicht unbemerkt bleiben, &lt;Name&gt;.\n\nVielen Dank für Eure Mühe.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nClevere DeviatgamaschenDeviathautpack\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1487] = {title = "Ausrottung der Deviat", objective = "Ebru in den Höhlen des Wehklagens möchte, dass Ihr 7 Deviatverheerer, 7 Deviatvipern, 7 Deviatschlurfer und 7 Deviatschreckensfange tötet.", description = "Naralex hatte ein edles Ziel.\n\nUnser großer Anführer trachtete danach, in den Smaragdgrünen Traum zu gelangen und dabei zu helfen, aus diesem kargen Land wieder den üppigen Wald zu machen, der hier einst wuchs. Aber etwas ist furchtbar schief gegangen.\n\nNaralex' Traum wurde zum Alptraum. Verderbte Kreaturen siedelten sich in den Höhlen an.\n\nWährend einige Jünger von Naralex versuchen, unseren Meister zu wecken, ist es mein Trachten, die Höhlen von diesen bösen Bestien zu befreien.\n\nWagt Euch in die Höhlen, <Name>, und löscht die Deviatbrut aus.", progress = nil, completion = "Als Jünger von Naralex bewundere ich Eure Tapferkeit, &lt;Name&gt;.\n\nEure Unterstützung bei der Befreiung der Höhlen ist der erste Schritt bei unserer schweren Aufgabe, das Brachland wiederherzustellen.\n\nVielen Dank, und möge Euch Wohlstand gewiss sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMuster: DeviatschuppengürtelSchmorsteckenMoorlandstulpen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1488] = {title = "Der Verderber", objective = "Besiegt Lord Azrethoc und Jugkar Grim'rod. Kehrt dann zu Takata Steelblade in Desolace zurück.", description = "Wiewohl ich nichts über diesen Lord Azrethoc weiß, stimme ich mit Maurin überein, er muss aufgehalten werden. Besonders wenn er versucht, Einfluss über die Burning Blade zu bekommen, um seine Ziele voranzutreiben.\n\nIhr habt schon gezeigt, dass Ihr den Kriegshäuptling unterstützen möchtet. Ich verlasse mich darauf, dass Ihr eine Truppe zusammenstellt, die den Dämonenlord und seinen Hexenmeisterdiener besiegt.\n\nWenn Ihr bereit seid, geht direkt nach Süden und kehrt zu mir zurück, wenn die Bedrohung beseitigt wurde.", progress = nil, completion = "Ein großer Sieg für uns alle, &lt;Name&gt;. Feiern wir unseren Erfolg. Ich gehe jetzt davon aus, dass unsere Zukunft hier nicht so trostlos ist, wie ich einst dachte.\n\nDie Dämonen werden besiegt werden, die Bemühungen der Burning Blade sind zum Scheitern verurteilt und wir haben vielleicht eines Tages einen Ort, den wir eine sichere Heimat nennen dürfen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBasalt-RundschildVollstrecker-Schulterstücke\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1489] = {title = "Hamuul Runetotem", objective = "Sprecht mit Hamuul Runetotem.", description = "Die Schalen, die Ihr mir gebracht habt, haben eine Besudelung, eine, die ich nie zuvor gesehen habe. Ich bin mir sicher, dass das Wasser der Oasen der Grund dafür ist. Ich spüre die Verwirrung, die sie über das Land bringen. Es ist, als würde das Land träumen und nicht erwachen können.\n\nDie Höhlen des Wehklagens müssen die Quelle dieser Besudelung sein. Doch ehe Ihr dorthin geht, solltet Ihr mit dem Druidenältesten Hamuul Runetotem sprechen. Ich ließ ihn über die Vorfälle im Brachland informieren. Er ist weise und kann Euch Rat geben.\n\nIhr findet ihn in Thunder Bluff auf der Anhöhe der Ältesten.", progress = nil, completion = "Ich grüße Euch, &lt;Name&gt;. Ihr seid hier willkommen und ich schlage vor, dass Ihr all Eure Kraft zusammennehmt. Denn die Aufgabe, die wir Euch stellen... ist schrecklich.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1490] = {title = "Nara Wildmane", objective = "Sprecht mit Nara Wildmane.", description = "Ich betrat das Land der Träume und träumte von einem Druidenkult, der in den Höhlen des Wehklagens haust. Ich sah, dass ihre Ziele einst edel waren, sie jedoch vom rechten Weg abkamen. Sie sind jetzt Diener der Besudelung, die das Brachland befallen hat.\n\nIch bin alt und meine Kraft verlässt mich. Ich konnte nicht lange an diesem Traumort verweilen und weiß wenig mehr von den besudelten Druiden. Aber Nara ist jung und starken Willens. Sie blieb in dem Traum zurück, als ich floh.\n\nSprecht mit Nara. Sie ist in jenem Zelt da drüben.", progress = nil, completion = "Ja, es stimmt. Ich weiß von den Druiden in den Höhlen des Wehklagens. Ich habe ihre verzerrten schuppigen Gesichter gesehen. Ich kenne ihre Verbrechen ebenso wie ihre Pläne.\n\nIhr müsst sie aufhalten, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1491] = {title = "Klugheitstränke", objective = "Bringt 6 Portionen Klageessenz zu Mebok Mizzyrix in Ratchet.", description = "Nun gut, die Raptorenhörner haben nicht funktioniert. Aber das macht nichts... nicht alles klappt beim ersten Mal! Außerdem habe ich wohl etwas gefunden, das in meinen Klugheitstränken noch besser funktioniert!\n\nEs gibt eine Substanz, die Klageessenz genannt wird. Ich glaube, sie ist die Ursache für die seltsamen Pflanzen und Tiere im Brachland. Bringt mir etwas davon, dann erprobe ich es in meinem Trank!\n\nIch hörte, die Essenz reichert sich in Ektoplasmakreaturen in den Höhlen des Wehklagens im Westen an. Jagt diese Kreaturen und sammelt die Essenz.", progress = "Wo ist meine Klageessenz?", completion = "Prima, Ihr habt sie! Ich kann es kaum erwarten, sie zu erproben. Das wird mir ein Vermögen einbringen, ich weiß es!\n\nDanke, &lt;Name&gt;. Nehmt das. Wenn ich reich bin, schicke ich Euch mehr, versprochen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1492] = {title = "Werftmeister Dizzywig", objective = "Bringt die gesicherte Kiste zu Werftmeister Dizzywig in Ratchet.", description = "Ich muss eine Kiste mit Tränken, Reagenzien und anderen Gegenständen zu meinen Geschäftspartnern in der alten Welt schaffen. Ich habe kaum Zeit, sie selbst zum Dock von Ratchet zu bringen, und die letzte Karawane ist schon aufgebrochen.\n\nKönntet Ihr sie bitte freundlichst zu Werftmeister Dizzywig bringen? Er wird dafür sorgen, dass sie an Bord des nächsten Schiffes zur Schwarzmeerbucht kommt.", progress = "Ihr wollt mit dem nächsten Schiff fahren oder habt einen Gegenstand, der an Bord gebracht werden soll?", completion = "Eine recht kleine Kiste. Ja, dafür müsste ich noch Platz an Bord des Schiffes finden. Es läuft mit der nächsten Flut aus, das dürfte wohl schnell genug sein. Exzellent. Lasst es mich noch eben in mein Geschäftsbuch eintragen.\n\nAlles erledigt! Guten Tag, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"},
[1498] = {title = "Weg der Verteidigung", objective = "Bringt 5 versengte Schuppen zu Uzzek im Farwatch-Posten im Brachland.", description = "Als Krieger ist eine unserer wichtigsten Aufgaben... der Schutz. Wir sind der Schild der Horde und sorgen für die Sicherheit unserer schwächeren Brüder. Wenn Ihr Euch bei uns einreihen möchtet, müsst Ihr mir Eure Tauglichkeit beweisen.\n\nGeht zum Donnergrat in Durotar, wo die Blitzechsen und Donnerechsen hausen. Jagt die Bestien! Zeigt mir, dass Ihr härter als sie seid! Trotzt ihren Angriffen und bringt mir einen Stapel ihrer versengten Schuppen als Beweis.\n\nGelingt Euch das, unterrichte ich Euch.", progress = "Habt Ihr die Schuppen, <Name>? Wenn Ihr den Angriffen der Donner-Echsen nicht trotzen könnt, könnt Ihr von meiner Unterweisung nicht profitieren.", completion = "Ah. Ich sehe, Ihr habt die Donner-Echsen besiegt, was Eure Zähigkeit beweist. Jetzt zeige ich Euch, wie harte Haut und listige Bewegungen zusammen eine undurchdringliche Verteidigungsmauer bilden können.\n\nPrägt Euch das gut ein, &lt;Name&gt;. Und seid bereit für weitere Instruktionen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWeg der Verteidigung\n\nIhr bekommt:\n\n"},
[1499] = {title = "Üble Familiare", objective = "Sprecht mit Zureetha Fargaze.", description = "Zureetha hat Novizen wie Euch geschickt, damit sie helfen, die Zahl der Kreaturen in der Höhle einzudämmen, in deren Nähe Ihr gegen die schändlichen Familiare gekämpft habt.\n\nIch finde, es wäre gut für Euch, wenn Ihr Erfahrung sammelt, indem Ihr ihr helft. Erwähnt unbedingt, dass Ihr mitgeholfen habt, das Wichtel-Problem zu lösen, womöglich hat sie eine Belohnung für Euch.", progress = nil, completion = "Ihr habt Eure Sache gut gemacht, &lt;Name&gt;.\n\nDie abscheulichen Familiare waren zwar nur Schoßtierchen der dunkleren Mächte bei den Burning Blade, doch Euer Erfolg gegen sie lässt kommende Großtaten ahnen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPrimitive HandklingePrimitiver Wanderstecken\n\nIhr bekommt außerdem:\n\n"},
[1500] = {title = "Die Erweckung von Naralex", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[1501] = {title = "Kreatur der Leere", objective = "Holt die Schrifttafel der Verga für Gan'rul Bloodeye in Orgrimmar.", description = "So wenige Hexenmeister sind übrig... Wir riskieren viel, doch die Risiken sind gerechtfertigt. Ihr müsst bald Reife in Eurer Fähigkeit erlangen, wenn Ihr der Horde und dem Kriegshäuptling nützlich sein wollt.\n\nEs ist Zeit, dass Ihr einen neuen Beschwörungszauber lernt.\n\nAls Erstes müsst Ihr die Schrifttafel der Verga wiederbeschaffen, die von Hexenmeistern der Burning Blade gestohlen wurde und nun in ihrem Unterschlupf in der Knochenhöhle verwahrt wird. Mit der Tafel zeige ich Euch die Runen, mit denen ein Leerwandler beschworen wird.", progress = "Habt Ihr die Schrifttafel der Verga, <Name>? Ich wünsche erst wieder mit Euch zu sprechen, wenn Ihr sie habt.", completion = "Gut. Ich hoffe, Ihr habt den Burning Blade weitere Verluste zugefügt, als Ihr dies beschafft habt.\n\nSie sind dem Kriegshäuptling ein Dorn im Auge und eine echte Pest für die &lt;Klasse&gt; im Allgemeinen.", rewards = "Ihr bekommt:\n\n"},
[1502] = {title = "Thun'grim Firegaze", objective = "Sprecht mit Thun'grim Firegaze im Brachland.", description = "Es ist wichtig, dass ein Krieger eine hochwertige Waffe hat. Und wenn es einen Orc gibt, der hochwertige Waffen herstellen kann, dann ist das Thun'grim Firegaze. Er ist ein Einsiedler, der auf den Hügeln östlich von Crossroads haust.\n\nWenn Ihr eine Waffe sucht, Krieger, dann solltet Ihr Euch an Thun'grim wenden. Um ihn zu finden reist Ihr zuerst nach Crossroads im Westen und wendet Euch dann nach Osten in die Berge. Sein Lager liegt hoch auf einem Berggipfel.", progress = nil, completion = "Meine Augen sind schon lange ausgetrocknet, weil ich ins Feuer der Schmiede schaute, aber manches kann ich noch sehen. Ich kann sehen, dass Ihr etwas wollt.\n\nUnd da Ihr den Weg hierher gefunden habt, kann ich mir denken, was Ihr begehrt.", rewards = "Ihr bekommt:\n\n"},
[1503] = {title = "Geschmiedeter Stahl", objective = "Bringt die Schmiedestahlbarren zu Thun'grim Firegaze im Brachland.", description = "Ich gebe Euch eine Waffe, <Name>, doch vorher müsst Ihr mir helfen. Vor einigen Nächten kamen die Grimmhauer von Nordwesten in mein Lager. Sie wollten nicht mit mir kämpfen, wissen aber, wie schlecht es um mein Augenlicht bestellt ist. Einige lenkten mich durch Schnauben ab, während die anderen mich bestahlen. Diese Feiglinge!\n\nSie nahmen eine Eisentruhe mit, in der sich Schmiedestahlbarren befanden. Wenn Ihr sie wiederbeschaffen könnt, bekommt Ihr die Waffe, die Ihr sucht.\n\nSucht im Stacheleberlager nach der Eisentruhe und bringt die Schmiedestahlbarren zurück.", progress = "Habt Ihr meine Stahlbarren?", completion = "Ihr habt sie gefunden! Und alle Stangen sind da, was mich nicht überrascht. Ich glaube nicht, dass die Grimmhauer wussten, was sie mit diesem edlen Stahl anfangen sollten.\n\nDanke, &lt;Name&gt;. Hier ist Eure Belohnung. Möge sie Euch nützlich sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nThun'grims AxtThun'grims StreitkolbenThun'grims DolchThun'grims Schwert\n\nIhr bekommt außerdem:\n\n"},
[1504] = {title = "Die Bindung", objective = "Beschwört mit Hilfe der Glyphen der Beschwörung einen Leerwandler, unterwerft ihn und bringt dann die Glyphen der Beschwörung zu Gan'rul Bloodeye in Orgrimmar zurück.", description = "Nun studiert die Schrifttafel der Verga, denn sie enthält die Glyphen, die Ihr für die Beschwörung braucht. Bringt sie zu dem Kreis in Neeru Fireblades Zelt auf der anderen Seite der Höhle. Dort könnt Ihr den Leerwandler herbeirufen.\n\nIhr müsst ihn mit allen körperlichen und magischen Mitteln besiegen, die Euch zur Verfügung stehen. Wenn das vollendet ist, kommt mit den Glyphen der Beschwörung zu mir zurück und ich führe Euch vor, wie Ihr die Kreatur an Euren Willen bindet.", progress = "Der Leerwandler ist eine mächtige Kreatur. Ich weiß noch, wie ich an Eurer Stelle war, <Name>. Nach diesen vielen Jahren bekämpft mich mein eigener Leerwandler inzwischen etwas weniger stark, aber vermutlich nur, weil er darauf hofft, dass meine Wachsamkeit dann nachlässt.\n\nVergesst das nicht, <Name>.", completion = "Ihr habt Eure Sache gut gemacht, &lt;Name&gt;. Ich werde Euch zeigen, wie man einen Leerwandler beschwört, der dem, den Ihr gerade besiegt habt, sehr ähnlich ist.\n\nIhr solltet wissen, dass wir große Erwartungen in Euch setzen, und bisher habt Ihr sie auch erfüllt.\n\nAber dass Euch das nicht zu Kopf steigt, denn verglichen mit den Aufgaben, die noch vor Euch liegen, war dies hier ein Kinderspiel.", rewards = "Ihr erlernt:\n\nLeerwandler beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\nLeerwandler beschwören' lehren\n\nIhr bekommt außerdem:\n\n"},
[1505] = {title = "Veteran Uzzek", objective = "Sprecht mit Uzzek im Farwatch-Posten.", description = "Die Horde ehrt ihre Krieger, da ihre Kraft außer Frage steht. Doch die wahrhaft großen Helden sind auch große Schüler.\n\nSucht nach Uzzek. Er ist ein Veteran zahlreicher Kämpfe und unterrichtet jetzt junge Krieger in der Gefechtskunst. Ihr findet ihn südlich des Farwatch-Posten, der Orc-Garnison an der Grenze von Brachland und Durotar im Osten.", progress = nil, completion = "Hallo, Jüngelchen. Seid Ihr zur Ausbildung hier, ja?", rewards = "Ihr bekommt:\n\n"},
[1506] = {title = "Gan'ruls Beschwörung", objective = "Sprecht mit Gan'rul Bloodeye in Orgrimmar.", description = "Ihr da. <Name>, richtig?\n\nIch hoffe, Ihr seid nicht zu sehr beschäftigt, denn Gan'rul möchte Euch unverzüglich sprechen. Ihr findet ihn mit den Hexenmeisterältesten in der Kluft der Schatten.\n\nMeinen früheren Erfahrungen mit Gan'rul nach zu urteilen, bedeutet Eure Einbestellung entweder etwas sehr Gutes oder etwas sehr Schlechtes.", progress = nil, completion = "Gut. Ich hatte befürchtet, Ophek würde Euch nicht erreichen.\n\nEs ist Zeit, dass ich Eure Hexenmeisterausbildung fortsetze. Eure aktuellen Angelegenheiten müssen warten.\n\nIch gehe davon aus, dass das kein Problem sein wird.", rewards = "Ihr bekommt:\n\n"},
[1507] = {title = "Verschlinger der Seelen", objective = "Sprecht mit Cazul in der Kluft der Schatten.", description = "Eure Zeit ist gekommen, mehr über die Beschwörungsmagien zu lernen. Ihr werdet lernen, einen Sayaad zu beschwören, eine Kreatur mit unglaublichen geistigen Mächten. Er kann sich schwache Geister zu Diensten machen... doch seid unbesorgt! Ich bin sicher, Ihr seid der Herausforderung gewachsen.\n\nEin Sayaad kann nur beschworen werden, wenn man ihn mit einem Gegenstand ködert, der große Hingabe und Liebe bedeutet. Ich überlasse es Euch, so ein Objekt zu finden.\n\nEin Vorschlag? Sprecht mit Cazul... Es scheint wenig zu geben, das der alte Hexenmeister nicht weiß.", progress = nil, completion = "Hm... &lt;Name&gt;. Ihr seid noch neu auf Eurem Weg, doch ich spüre das Potenzial für Größe in Euch.\n\nIhr wurdet mit Gaben geboren, &lt;Name&gt;. Sorgt dafür, dass Ihr sie nicht vergeudet.", rewards = "Ihr bekommt:\n\n"},
[1508] = {title = "Der blinde Cazul", objective = "Sprecht mit Zankaja in Orgrimmar.", description = "Wenn Gan'rul Euch zu mir geschickt hat, dann gewiss, weil Ihr einen Sukkubus, also einen weiblichen Sayaad, beschwören sollt und einen Gegenstand braucht, um ihn anzulocken.\n\nHmm... Wenn Ihr Euch von einem Blinden führen lassen möchtet, <Name>, dann hört zu. In den Hängen von Orgrimmar, westlich des Himmelsturms im Tal der Stärke, lebt Zankaja. Sie wartet darauf, dass ihr Lebensgefährte zurückkehrt.\n\nGeht zu ihr.", progress = nil, completion = "Seid Ihr mit Neuigkeiten von Dogran gekommen? Er sollte vor Tagen zurück sein und ich habe kein Wort gehört...", rewards = "Ihr bekommt:\n\n"},
[1509] = {title = "Neuigkeiten von Dogran", objective = "Sprecht mit Gazrog in Crossroads.", description = "Dogran, mein Gefährte, wurde jüngst zum Dienst nach Crossroads geschickt. Es war eine Beförderung und er war sehr stolz.\n\nIch war natürlich traurig, ließ es ihn aber nicht wissen. Und auch besorgt. Das Brachland ist gefährlicher als Orgrimmar, daher fürchtete ich das Schlimmste.\n\nSeit einer Woche sollte er nun schon zu Hause sein und ich habe kein Wort von ihm gehört...\n\nVielleicht könntet Ihr nach Crossroads gehen und nachfragen, ob es Neuigkeiten gibt? Er arbeitete mit Gazrog, der noch dort stationiert sein sollte.", progress = nil, completion = "Zankaja? Das ist Dograns Gefährtin, nicht?\n\nJa, ich habe von ihm gehört, aber keine Neuigkeiten, die Ihr ihr überbringen solltet...\n\nNein, er ist nicht tot. Aber er ist verletzt und Gefangener der Stacheleber.", rewards = "Ihr bekommt:\n\n"},
[1510] = {title = "Neuigkeiten von Dogran", objective = "Sprecht mit Ken'zigla am Malaka'jin.", description = "Er war im Camp Taurajo stationiert, wo wir versuchten, die Stacheleber auszurotten. Er führte ein paar Grunzer zu einem ihrer Lager, wo er schwer verwundet wurde. Die anderen schafften es zurück und versuchten, ihn zu retten. Er war in einem schlimmen Zustand, seine Wunden eiterten, daher wollten sie ihn nicht mitnehmen, ohne ihn erst zu versorgen.\n\nSie schickten eine Nachricht hierher und baten um ein Heilgebräu von den Trollen der Malaka'jin im Steinkrallengebirge. Wir schickten Leute, um eines zu holen, aber diese sind noch nicht zurückgekehrt.", progress = nil, completion = "Ein &lt;Volk&gt;, hm? Ich hoffe, Ihr seid nicht wegen ihm gekommen. Er hat es nicht geschafft. Diese Goblins haben ihn alle gemacht.\n\nEr sagte nur, er bräuchte ein Heilgebräu, sonst nichts.", rewards = "Ihr bekommt:\n\n"},
[1511] = {title = "Ken'ziglas Trunk", objective = "Bringt Ken'ziglas Trunk zu Grunzer Logmar im Camp Taurajo.", description = "Ich dachte mir, dass ein anderer kommen würde, um den Trunk zu holen, daher habe ich ihn dennoch vorbereitet.\n\nDa habt Ihr ihn, <Name>. Aber denkt daran, Ihr solltet ihm nur die Hälfte geben! Dadurch bekommt er genug Kraft, sich zu bewegen, ohne dass er verblutet. Wartet eine Nacht und gebt ihm dann die andere Hälfte.\n\nWie auch immer, Ihr solltet dies zu Logmar im Camp Taurajo bringen. Nach allem, was er mir gesagt hat, sollte er wissen, wo dieser Dogran ist.", progress = "Ja, was gibt's?", completion = "Das wurde auch Zeit! Dogran wäre fast gestorben, während er darauf wartete.\n\nWir müssen den Trunk sofort zu ihm bringen, aber die meisten Grunzer, die hier stationiert sind, befinden sich auf Nahrungssuche.", rewards = "Ihr bekommt:\n\n"},
[1512] = {title = "Die Liebesgabe", objective = "Bringt den schmutzverkrusteten Anhänger zu Gan'rul Bloodeye in Orgrimmar.", description = "Zankaja ist jung und wunderschön. An einen Invaliden gekettet zu sein... Ich dulde nicht, dass ihr diese Ungerechtigkeit widerfährt.\n\nLasst mich allein, <Name>. Und habt Dank. Vielleicht beende ich mein Leben im ruhmreichen Kampf statt als leblose Hülle.\n\nUnd bitte erzählt meiner Gefährtin nichts davon... Ich möchte nicht, dass sie sich Schuld auflädt.", progress = "Ihr seid zurückgekehrt. Seid Ihr bereit, gegen einen Sukkubus zu kämpfen?", completion = "Wenn Ihr mir sagt, dass dies genügt, dann vertraue ich Euch, &lt;Name&gt;. Aber erlaubt mir, ihn zu reinigen... Sauber und glänzend dürfte er für einen Sukkubus noch verlockender sein.", rewards = "Ihr bekommt:\n\n"},
[1513] = {title = "Die Bindung", objective = "Beschwört mit Hilfe von Dograns Anhänger einen Sukkubus, unterwerft ihn und bringt dann Dograns Anhänger zu Gan'rul Bloodeye in Orgrimmar zurück.", description = "Bringt dies zum Beschwörungskreis in Neerus Zelt, <Name>. Beschwört einen schändlichen Sukkubus und zeigt ihm Eure Überlegenheit. Ich glaube an die Kraft Eurer Magie. Aber seid wie stets wachsam, denn Stolz und Selbstüberschätzung wurden manchem viel versprechenden Hexenmeister zum Verhängnis.\n\nWenn Ihr ihn besiegt habt, bringt den Anhänger zu mir, damit ich Zankaja die Neuigkeit überbringen kann.", progress = "Wenn ich einen Sukkubus ansehe, geht mir das Herz auf... Aber zugleich kann ich fast meiner Seele Niedergeschlagenheit spüren, die wie die Gezeiten abfließt.\n\nSeid wachsam.", completion = "Erfolg! Seid versichert, dass ich von meinem Musterschüler nichts anderes erwartet habe.\n\nIhr habt Euch als würdig erwiesen, daher zeige ich Euch mit Freuden die Methode, wie Ihr Euren unterworfenen Sukkubus beschwört. Geht jetzt, Ihr habt viel zu lernen. Wenn ich Euch das nächste Mal sehe, erwarte ich, dass Ihr wahre Meisterschaft über Euren Sukkubus erlangt habt.\n\nÜberlasst die Trauer um Dogran und Zankaja denen unter uns, die älter an Jahren sind, aber vergesst sie nicht und bewahrt sie als Schutz gegen die Launen der dunklen Macht, die Ihr heute zu beschwören gelernt habt.", rewards = "Ihr erlernt:\n\nSukkubus beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSukkubus beschwören' lehren\n\nIhr bekommt außerdem:\n\nKleiner Seelenbeutel"},
[1514] = {title = "Verderbte Windblüte", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[1515] = {title = "Dograns Gefangenschaft", objective = "Bringt Ken'ziglas Trunk zu Dogran im Brachland.", description = "Ihr habt es bis hierher geschafft, wenn Ihr es bis zu Ende durchstehen möchtet, werde ich Euch nicht aufhalten. Aber ich kann keine Leute erübrigen, Ihr seid also auf Euch allein gestellt.\n\nDogran wird in einem Lager der Stacheleber nördlich von hier festgehalten. Sucht nach zwei nebeneinander stehenden Hütten. Er wird schwer bewacht... Das heißt, wenn sie ihn noch nicht getötet haben oder er seinen Verletzungen erlegen ist.\n\nViel Glück.", progress = "Urrrghhhh...", completion = "Ein übel schmeckendes Gebräu...\n\nDoch ich spüre genügend Kraft in mir, um wegzuhinken... Aber auf mein Bein werde ich den Rest meines Lebens verzichten müssen. Und auf meinen Arm auch.", rewards = "Ihr bekommt:\n\n"},
[1516] = {title = "Ruf der Erde", objective = "Bringt 2 Teufelspirscherhufe zu Canaga Earthcaller im Tal der Prüfungen.", description = "Die Zeit ist gekommen, junger <Klasse>. Ihr seid stark geworden und Euer Geist ist ausdauernd wie die Erde. Dass Ihr dem Pfad des Schamanen folgt, zeigt, dass Ihr Weisheit besitzt, sogar bevor Ihr Euch selbst beweist.\n\nDas Element der Erde wird über Euer Schicksal wachen und Teil von Euch werden, wenn Ihr bereit seid. Doch Ihr müsst vor der Erde selbst bestehen. Wenn Ihr bereit seid, werdet Ihr Dinge sehen, von denen nur Schamanen wissen.\n\nSucht die Teufelspirscher im Norden und beschafft Euch zwei ihrer Hufe. Kehrt dann zu mir zurück und wir sprechen weiter über Eure Zukunft.", progress = "Geduld ist der Erde größte Tugend. Die Erde sieht den Zyklus aller Dinge: die Berge werden zu Wüsten, Flüsse werden zu Schluchten. Die Erde ist das störrischste und weiseste aller Elemente, sie toleriert keine Ungeduld.\n\nDie Erde ruft Euch nun, denn eine Zeit der Konflikte rückt näher. Wenn Ihr erfolgreich zu mir zurückkehrt, werdet Ihr dem Ziel, ganzheitlich zu werden, sehr viel näher sein.\n\nAndere werden Euch Eure Weisheit neiden und Euch ihrer Unwissenheit wegen hassen.", completion = "Exzellent. Euer Erfolg zeigt, dass Ihr vorbereitet seid.\n\nVon allen Elementen repräsentiert die Erde das Fundament aller Dinge. Sie ist Eure Kraft, Eure Ausdauer und Eure Geduld. Die Erde wird Euch schützen, aber nur, wenn Ihr angemessenen Respekt zeigt. Die Erde kann, wie alle anderen Elemente auch, kleinmütig sein. Die Erde ist die Grundlage des Lebens und wenn Ihr ihre Gesetze achtet, wird Euch größere Weisheit zuteil. Vergesst niemals die Geheimnisse, die die Erde mit Euch teilt.\n\nIch werde jetzt ein Sapta für Euch machen. Wenn Ihr es akzeptiert, werdet Ihr Euren Weg erkennen.", rewards = "Ihr bekommt:\n\n"},
[1517] = {title = "Ruf der Erde", objective = "Sucht den Geisterfelsen und trinkt das Erdsapta.\n\nBereitgestellter Gegenstand: \n", description = "Ein Sapta ist ein Getränk, mit dem unsere Seelen an die Elemente gebunden werden. Mit Magie gestärkt lässt dieser Trank die Willensstarken die Elemente sehen, wie es sonst niemand kann. Euer Geist wird mit dem Element verbunden, für das das Sapta geschaffen wurde. Nur wenige auserwählte Schamanen kennen das Rezept.\n\nDas Sapta wird stets an einem heiligen Ort getrunken, niemals anderswo ... vergesst das nicht.\n\nBesucht den Geisterfelsen südwestlich von hier ... er befindet sich am Ende des verborgenen Pfades. Trinkt Euer Sapta dort und ... tja, Ihr werdet schon sehen.", progress = nil, completion = "Ah... &lt;Name&gt;... die Erde ist erfreut, Euch hier zu sehen.\n\nAn Körper und Geist verbunden werdet Ihr vorwärts schreiten, wissend, dass die Berge Eure Kraft sind, die Ebenen Eure Geduld; die Welt selbst Eure Essenz.\n\nEs ist nur erforderlich, dass Ihr demütig vor der Erde steht, um dieses Ritual zu bestehen. Aber die anderen sind nicht so passiv. Sie können chaotisch und häufig brutal sein, doch das liegt in der Natur der Elemente. Duale Naturen widerstreben einander, diese Dinge müsst Ihr gründlich lernen.", rewards = "Ihr bekommt:\n\n"},
[1518] = {title = "Ruf der Erde", objective = "Bringt den Rohquarz zu Canaga Earthcaller im Tal der Prüfungen.", description = "Nehmt diesen Rohquarz von mir und bringt ihn als Beweis für unsere Begegnung zu Canaga Earthcaller. Er wird ein Totem für Euch anfertigen, dessen Herzstück dieser Kiesel sein soll. So winzig er scheinen mag, Ihr werdet feststellen, dass es nicht auf die Größe ankommt und selbst die kleinsten Dinge viele anderen überdauern können.\n\nHabt Geduld, <Name>. Bleibt stark und sucht Weisheit. Dies verlangt die Erde von Euch. Am Ende solltet Ihr eins mit der Erde werden... respektiert sie so, wie sie Euch respektiert.", progress = "Ich möchte der Erste sein, der Euch auf dem ersten der vier Pfade begrüßt, die Euch für immer Eurem Schicksal zuführen werden.\n\nWenn Ihr den Stein besitzt, den Euch die Erde gab, werde ich Euch das versprochene Totem geben.\n\nWenn nicht, hebt Euch hinfort, bis Ihr Euren Weg gefunden habt.", completion = "Exzellent!\n\nDas Totem, das ich für Euch anfertigen werde, ist mehr als nur ein Symbol für Euren Status unter den Schamanen... es besitzt Fähigkeiten, die darüber hinausgehen. Ein Nutzen des Totems ist, dass es als Fokus für Zauber dient. Diese Zauber sind mit der Erde verbunden. Je mehr Weisheit Ihr erlangt, desto mehr Fähigkeiten der Erde werden Euch zugänglich sein.\n\nDie Lehrer werden wissen, wann Ihr für größeres Wissen bereit seid.\n\nNehmt vorerst dieses Erdtotem...", rewards = "Ihr erlernt:\n\nTotem der Steinhaut\n\nDer folgende Zauber wird auf euch gewirkt:\n\nTotem der Steinhaut\n\nIhr bekommt außerdem:\n\nErdtotem"},
[1519] = {title = "Ruf der Erde", objective = "Bringt 2 Dosen Ritualsalbe zu der Seherin Ravenfeather im Camp Narache.", description = "Die Zeit ist gekommen, <Klasse>. Euer Körper ist ausgereift und stark geworden und Euer Geist ist ausdauernd wie die Erde. Ich sehe es Euch an... Ihr besitzt bereits Weisheit.\n\nDie Erde leitet unser Volk und spricht zu uns... und bald auch zu Euch. Aber Ihr müsst geprüft werden. Wenn Ihr bereit seid, werdet Ihr Dinge sehen, von denen nur unsere Art weiß.\n\nSucht die Schamanen der Borstennacken in ihrer Klamm im Osten auf und beschafft Euch eine ihrer Salben, die sie für ihre Rituale verwenden. Kehrt erst zu mir zurück, wenn Ihr genügend davon für Euren eigenen Trank habt.", progress = "Die Erde ist geduldig und wird auf Euch warten, bis Ihr bereit seid, denn sie weiß, mit der Zeit schwinden alle Dinge und werden wiedergeboren. Das ist der Zyklus des Lebens. Berge werden zu Wüsten. Flüsse werden zu Schluchten. Die Erde ist das störrischste und weiseste aller Elemente.\n\nIhr müsst vor allem Geduld und Ausdauer lernen. Die Erde ruft Euch nun, denn sie spürt, dass Ihr bereit seid. Betrachtet dies als Eure Wiedergeburt, wenn Ihr erfolgreich seid. Hinterher werdet Ihr niemals wieder zur Unwissenheit zurückkehren können.", completion = "Gut, &lt;Name&gt;. Eure Rückkehr hierher zeigt, dass Ihr wahrlich für den nächsten Schritt bereit seid.\n\nVon allen Elementen repräsentiert die Erde das Fundament aller Dinge. Sie ist Eure Kraft, Eure Ausdauer und Eure Geduld. Die Erdenmutter wird Euch schützen, aber nur, wenn Ihr ihr den angemessenen Respekt erweist. Sie ist die Grundlage des Lebens und wenn Ihr ihre Gesetze achtet, wird Euch größeres Wissen zuteil. Vergesst niemals die Geheimnisse, die sie mit Euch teilt.\n\nIch werde jetzt Euer Sapta für Euch machen. Wenn Ihr es akzeptiert, wird sich ein neuer Weg vor Euch auftun.", rewards = "Ihr bekommt:\n\n"},
[1520] = {title = "Ruf der Erde", objective = "Sucht den Kodofels und trinkt das Erdsapta.\n\nBereitgestellter Gegenstand: \n", description = "Ein Sapta ist ein Getränk, mit dem unsere Seelen an die Elemente gebunden werden. Mit Magie gestärkt lässt dieses Elixier die, die offenen Geistes sind, die Elemente sehen, wie sie zuvor noch von niemandem gesehen wurden. Euer Geist wird ewig an das Element gebunden, für das das Sapta geschaffen wurde. Nur wenige Auserwählte unserer Art kennen das Geheimnis seiner Herstellung.\n\nDas Sapta wird stets an einem heiligen Ort getrunken und niemals anderswo.\n\nSucht den Schamanenschrein östlich von hier und trinkt von dem Sapta.", progress = nil, completion = "Ah... &lt;Name&gt;... die Erde ist erfreut, Euch hier zu sehen.\n\nAn Körper und Geist verbunden werdet Ihr vorwärts schreiten, wissend, dass die Berge Eure Kraft sind, die Ebenen Eure Geduld; die Welt selbst Eure Essenz.\n\nEs ist nur erforderlich, dass Ihr demütig vor der Erde steht, um dieses Ritual zu bestehen. Aber die anderen sind nicht so passiv. Sie können chaotisch und häufig brutal sein, doch das liegt in der Natur der Elemente. Duale Naturen widerstreben einander, diese Dinge müsst Ihr gründlich lernen.", rewards = "Ihr bekommt:\n\n"},
[1521] = {title = "Ruf der Erde", objective = "Bringt den Rohquarz zu der Seherin Ravenfeather im Camp Narache.", description = "Nehmt diesen Rohquarz von mir und bringt ihn als Beweis für unsere Begegnung zu der Seherin Ravenfeather. Sie wird ein Totem für Euch anfertigen, dessen Herzstück dieser Kiesel sein soll. So winzig er scheinen mag, Ihr werdet feststellen, dass es nicht auf die Größe ankommt und selbst die kleinsten Dinge Berge überdauern können.\n\nHabt Geduld, <Name>. Bleibt stark und sucht Weisheit. Dies verlangt die Erde von Euch. Am Ende solltet Ihr eins mit der Erde werden... respektiert sie so, wie sie Euch respektiert.", progress = "Seid gegrüßt, <Name>. Ihr würdet nicht zu mir zurückkehren, wenn Ihr Eure Aufgabe nicht bewerkstelligt hättet. Ich möchte der Erste sein, der Euch auf dem ersten der vier Pfade begrüßt, die für immer Eure Reise beherrschen werden.\n\nWenn Ihr den Stein besitzt, den Euch die Erde gab, werde ich Euch das versprochene Totem geben. Wenn nicht, bedauere ich Euch. Mit großem Stolz erfüllt es den, der sich voll und ganz den Elementen verschrieben hat.", completion = "Großartig.\n\nDas Totem, das ich für Euch anfertigen werde, ist mehr als nur ein Symbol... es besitzt Fähigkeiten, die darüber hinausgehen. Ein Nutzen des Totems ist, dass es als Fokus für Zauber dient. Diese Zauber sind mit der Erde verbunden. Je mehr Weisheit Ihr erlangt, desto mehr Fähigkeiten der Erde werden Euch zugänglich sein. Die Lehrer in ganz Kalimdor werden wissen, wann Ihr für größeres Wissen bereit seid und es Euch sagen, wenn Ihr sie besucht.\n\nNehmt vorerst dieses Erdtotem...", rewards = "Ihr erlernt:\n\nTotem der Steinhaut\n\nDer folgende Zauber wird auf euch gewirkt:\n\nTotem der Steinhaut\n\nIhr bekommt außerdem:\n\nErdtotem"},
[1522] = {title = "Ruf des Feuers", objective = "Sucht Kranal Fiss im Brachland.", description = "Feuer sei mit Euch, Mann. Ich sehe, Ihr seid schon bewandert in den Wegen der Erde und scheint mir bereit, mit Kranal zu sprechen.\n\nKranal lebt nördlich von Crossroads im Brachland. Er kennt sich mit den Elementen aus und kann Euch was übers Feuer beibringen ... wenn Ihr denkt, dass Ihr bereit seid.\n\nEr ist leicht zu finden, geht nur nicht zu weit. Wenn Ihr zu weit geht, seid Ihr plötzlich im Elfenland.", progress = nil, completion = "Hmmm, hat Searn Euch geschickt, ja?\n\nAlso Searn kann man immer vertrauen. Er scheint überzeugt, dass Ihr bereit seid, Euer nächstes Sapta zu nehmen, das Feuersapta.\n\nIch sehe es schon in Euren Augen, das Lodern, das Verlangen. Ihr habt von der Macht gekostet und seid jetzt bereit für mehr. Geduld, &lt;Name&gt;. Vergesst nicht, was Euch die Erde lehrte. Macht und Zerstörung werden sicherlich kommen, doch Ihr müsst dennoch wissen, wann Ihr Euch zurückhalten solltet.", rewards = "Ihr bekommt:\n\n"},
[1523] = {title = "Ruf des Feuers", objective = "Sucht Kranal Fiss im Brachland.", description = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, <Name>. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über Zerstörung zu lernen... und über Chaos. Ihr könnt das Element des Feuers verstehen lernen, wenn Ihr bereit seid, dafür zu bezahlen.\n\nSucht nach Kranal Fiss im Brachland. Er lebt in einer kleinen Siedlung nördlich von Crossroads, aber gebt Acht, wenn Ihr das Land der Nachtelfen erreicht, seid Ihr zu weit gegangen.", progress = nil, completion = "Hmmm, hat Xanis Euch geschickt, ja?\n\nAlso Xanis kann man immer vertrauen. Er scheint überzeugt, dass Ihr bereit seid, Euer nächstes Sapta zu nehmen, das Feuersapta.\n\nIch sehe es schon in Euren Augen, das Lodern, das Verlangen. Ihr habt von der Macht gekostet und seid jetzt bereit für mehr. Geduld, &lt;Name&gt;. Vergesst nicht, was Euch die Erde lehrte. Macht und Zerstörung werden sicherlich kommen, doch Ihr müsst dennoch wissen, wann Ihr Euch zurückhalten solltet.", rewards = "Ihr bekommt:\n\n"},
[1524] = {title = "Ruf des Feuers", objective = "Bringt die Fackel der schlafenden Flamme zu Telf Joolam in Durotar.", description = "Ihr seid mächtig genug, das Totem des Feuers zu tragen, doch bedeutet das nicht, dass Ihr bereit seid.\n\nAm Südstromfluss in Durotar, vor dem großen Meer, liegt ein verborgener Pfad zu einem der höchsten Gipfel des Landes. Sucht einen Weg nach oben. Dann werdet Ihr einen unserer heiligen Schreine finden, den Telf Joolam bewacht ... den Schrein der schlafenden Flamme.\n\nBringt ihm diese Fackel ... sie zeigt, dass Ihr versucht, das Feuer zu bändigen. Bringt sie mir zurück, wenn Ihr sie an der Kohlenpfanne des Schreins entzündet habt, und ich sorge dafür, dass Ihr das Totem des Feuers bekommt.", progress = "Seid gegrüßt, <Name>. Ihr befindet Euch am Schrein der schlafenden Flamme. Nur jene, die wahrlich in den schamanistischen Künsten bewandert sind, werden je die Geheimnisse dieses Ortes und der Macht kennen lernen, die er birgt. Tut mir Leid, dass Ihr den weiten Weg auf Euch genommen habt, nur um jetzt abgewiesen zu werden - die Reise hierher ist alles andere als sicher -, aber ich bin der Bewahrer des Schreins und kann nicht jeden hier umherstreifen lassen.", completion = "Ah, mein Fehler, &lt;Name&gt;. Ich muss mich entschuldigen. Mir war nicht klar, dass Ihr die Fackel besitzt. Es freut mich, Eure Bekanntschaft zu machen.\n\nViele Abenteurer finden auf der Suche nach verlorenen Schätzen oder der Jagd auf mystische Kreaturen hierher und werden von einem scheinbar leeren Schrein abgewiesen. Aber wir kennen die Wahrheit, nicht, &lt;Name&gt;?\n\nDieser Schrein verbirgt ein größeres Geheimnis vor den einfachen Mitgliedern der Horde. Für uns ist er heilig.", rewards = "Ihr bekommt:\n\n"},
[1525] = {title = "Ruf des Feuers", objective = "Bringt 1 Feuerteerstück und 1 Reagenzienbeutel zu Telf Joolam in Durotar.", description = "Aber Ihr seid doch nicht zum Geschichtsunterricht hergekommen, oder? Ihr seid wegen der ewigen Flamme und einem Feuertotem gekommen.\n\nZunächst einmal müsst Ihr ein Sapta anfertigen und Euch selbst an das Feuer binden.\n\nIch kann das Feuersapta für Euch herstellen, wenn Ihr mir zwei Gegenstände bringt. Der Erste ist Feuerteer, ein einfacher Gegenstand, den normalerweise die Zauberer der Grimmhauer im östlichen Brachland mit sich führen.\n\nDer zweite Gegenstand dürfte gefährlicher zu bekommen sein: ein Reagenzienbeutel von einem Kultisten der Burning Blade. Ihr findet sie in einer Höhle über den Klammen nordöstlich von Klingenhügel.", progress = "Ich habe genügend Zutaten für ein Feuersapta, wenn Ihr den Reagenzienbeutel und etwas Feuerteer finden könnt. Die Fanatiker der Burning Blade tragen die richtigen Komponenten für die meisten ihrer Zauber in diesen Beuteln und haben meist ausreichend von den Gegenständen, die ich benötige, damit Ihr nicht weiter nach etwas anderem suchen müsst.\n\nDie Saptas werden stets aus Zutaten hergestellt, die in enger Verbindung zu ihrem jeweiligen Element stehen. Es macht unsere Arbeit leichter, da die Hexenmeister mit dem Feuer verbunden sind.", completion = "Diese werden genügen, &lt;Name&gt;.\n\nFeuer ist mehr als Chaos und Zerstörung... Ihr tut gut daran, das nicht zu vergessen. Es dreht sich auch um Leben und Schöpfung. Alle Dinge sind auf diese Weise miteinander verbunden. Kräfte sind einander entgegengesetzt, doch zugleich kann die eine nicht ohne die andere existieren. Beide löschen sich gegenseitig aus, geben einander aber auch erst einen Sinn. Vergesst das niemals.\n\nUnterschiedliche Arten der Magie in Verbindung miteinander zu verwenden, zeigt nicht nur wahre Fertigkeit, sondern große Weisheit.", rewards = "Ihr bekommt:\n\nFeuersapta"},
[1526] = {title = "Ruf des Feuers", objective = "Besiegt die geringe Feuermanifestation und legt Glut in die Kohlenpfanne auf dem Schrein der ewigen Flamme.", description = "Das Feuersapta ist fertig. Die Zeit ist gekommen, dass Ihr Euch der Flamme stellt. Benutzt das Sapta am Schrein und geht zum Berggipfel, um Euch dort der Manifestation zu stellen. Er wird Euch erst angreifen, wenn Ihr bereit seid, wird aber wissen, dass Ihr ihn sehen könnt.\n\nSchlagt ihn schnellstens nieder, <Name>, denn seine Macht wächst, je länger Ihr braucht, um ihn zu besiegen. Wenn er bezwungen wurde, legt seine Glut in die Kohlenpfanne und entzündet die Fackel.", progress = "Die Kohlenpfanne hat etwa ein Drittel Eurer Höhe und sieht normal aus, abgesehen von den Inschriften auf ihrem glatten Metallrand. Das Metall scheint nicht vom Wetter angegriffen zu sein und die Schale, die darauf ruht, fühlt sich kalt an.", completion = "Eine weiß glühende Flamme lodert in der Schale auf, als Ihr die Glut hineinlegt. Ihr könnt spüren, wie die magischen Effekte des Sapta durch Euren Körper strömen und das Feuer rhythmisch vor Euch tanzt.\n\nIhr haltet das Ende der Fackel in die Pfanne und sie fängt sofort Feuer.", rewards = "Ihr bekommt:\n\nFackel der ewigen Flamme"},
[1527] = {title = "Ruf des Feuers", objective = "Bringt die Fackel der ewigen Flamme zu Kranal Fiss im Brachland.", description = "Mit der Fackel fest in der Hand wendet Ihr Euch von der Kohlenpfanne ab und lasst den Blick über Durotar schweifen. Ihr spürt, wie Aufregung Euren Geist erfüllt, als der Wind anschwillt und die Flamme heftig flackern lässt.\n\nAuf der Suche nach Kranal Fiss betretet Ihr den Pfad zurück ins Brachland.", progress = "Ja, <Name>? Was habt Ihr da?", completion = "Euer Geist brennt heller als jede Fackel, die ich je gesehen habe, &lt;Name&gt;, und darauf solltet Ihr stolz sein.\n\nWenn Ihr diesem Weg weiter folgt, werdet Ihr über die Elemente gebieten und unsere Brüder werden Führung und Weisheit bei Euch suchen. Lasst mich der Erste sein, der Euch gratuliert und Euch Euer neuestes Totem überreicht.", rewards = "Ihr erlernt:\n\nTotem der Verbrennung\n\nDer folgende Zauber wird auf euch gewirkt:\n\nTotem der Verbrennung\n\nIhr bekommt außerdem:\n\nFeuertotem"},
[1528] = {title = "Ruf des Wassers", objective = "Sucht Islen Waterseer im Brachland.", description = "Wasser sei in Eurer Zukunft, Mann. Ich sehe, Ihr seid schon bewandert in den Wegen des Feuers und scheint mir bereit, mit Islen zu sprechen.\n\nIslen lebt an der Küste des Brachlandes. Wenn Ihr am Ufer des Südstroms nach Süden geht, könnt Ihr sie gar nicht verfehlen ... achtet auf den großen Hai! Sie kennt sich mit den Elementen aus und kann Euch etwas übers Wasser beibringen ... wenn Ihr denkt, dass Ihr bereit seid.\n\nSie ist leicht zu finden, geht nur nicht zu weit nach Süden ... sie ist gleich hinter Ratchet.", progress = nil, completion = "Der Wind weht heftig vom Horizont her, die Erde unter Euren Füßen ist fest und Euer Geist ist bereits vom Feuer gewärmt... ich würde sagen, es ist an der Zeit, dass Ihr etwas über die Reinheit des Wassers lernt.\n\nEuer Weg hat Euch so weit gebracht und Euer Geist wird Euch die Kraft geben, noch weiter zu gehen. Doch den ersten Schritt müsst Ihr selbst machen.", rewards = "Ihr bekommt:\n\n"},
[1529] = {title = "Ruf des Wassers", objective = "Sucht Islen Waterseer im Brachland.", description = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, <Name>. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über die Reinheit des Wassers zu lernen.\n\nSucht nach Islen Waterseer im Brachland. Sie befindet sich an der Ostküste, südlich von Ratchet und dem Südstrom. Ihr findet sie in ihrer Fischerhütte. Viel Glück, <Name>.", progress = nil, completion = "Der Wind weht heftig vom Horizont her, die Erde unter Euren Füßen ist fest und Euer Geist ist bereits vom Feuer gewärmt... ich würde sagen, es ist an der Zeit, dass Ihr etwas über die Reinheit des Wassers lernt.\n\nEuer Weg hat Euch so weit gebracht und Euer Geist wird Euch die Kraft geben, noch weiter zu gehen. Doch den ersten Schritt müsst Ihr selbst machen.", rewards = "Ihr bekommt:\n\n"},
[1530] = {title = "Ruf des Wassers", objective = "Sucht Brine im südlichen Brachland.", description = "Wenn Ihr eine Lektion über Wasser lernen müsst, dann diese: Wasser bedeutet Wiedergeburt.\n\nSeine Macht fließt, erodiert und reinigt alle Arten von Dingen. Seine Fähigkeit zu heilen und zu regenerieren ist unvergleichlich, jedoch nur, wenn es rein ist.\n\nWenn Ihr begreift, dass verunreinigtes Wasser alles verheeren kann, was es berührt, werdet Ihr schätzen lernen, wie lebenswichtig dieser Rohstoff ist.\n\nWenn Ihr das Wassersapta möchtet, sucht Brine tief im südlichen Brachland. Ihr Heim wird unablässig von den dortigen Stachelebern heimgesucht.", progress = nil, completion = "Ja?\n\nMmm, ich habe das Gefühl, als wüsste ich, was Ihr mich fragen wollt: was veranlasst jemanden, hier im tiefsten Brachland zu leben, ständig von Stachelebern bedroht und ohne Schutz? Wir alle haben unsere Gründe, mit denen wir unser Tun rechtfertigen. Die wahre Frage ist jedoch, was führt einen bescheidenen &lt;Volk&gt; in die entlegensten Winkel des Brachlandes, um mit einer Frau zu sprechen, die sich eindeutig nicht um ihr Wohlergehen schert?\n\nIch wette, die Antwort darauf kennen wir beide.", rewards = "Ihr bekommt:\n\n"},
[1531] = {title = "Ruf der Luft", objective = "Sucht Prate Cloudseer in Tausend Nadeln.", description = "Macht Euch auf den Weg, Mann. Ihr seid bereit, Euch des Lufttotems würdig zu erweisen, aber zuerst müsst Ihr Prate Cloudseer in Tausend Nadeln finden. Wenn Ihr sie mit ausreichend Respekt behandelt, wird sie bereit sein, Euch zu sagen, wie Ihr das Lufttotem bekommen könnt.\n\nGeht durch das Brachland nach Süden und weiter nach Osten, wenn Ihr Tausend Nadeln erreicht habt. Ihr werdet sie verborgen in einem Erdloch mit ihrem Liebsten finden - haha, sagt ihr nicht, dass ich schlecht über sie geredet habe - das mag sie nicht sonderlich.", progress = nil, completion = "Fürs Erste werde ich Euch geben, was Ihr benötigt, um Eure Sprüche zu fokussieren und die Geister der Luft anzurufen. Nehmt dieses Totem, und wenn Ihr bereit seid, übt noch etwas mehr mit mir.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHurtiger Wind\n\nIhr bekommt:\n\nLufttotem"},
[1532] = {title = "Ruf der Luft", objective = "Sucht Prate Cloudseer in Tausend Nadeln.", description = "Die Winde von Kalimdor wehen Euch entgegen und Ihr sollt zu den Mächtigsten unserer <Brüder/Schwestern> gehören. Ich sehe mit Stolz, dass Ihr so weit gekommen seid und so eine viel versprechende Zukunft habt.\n\nDas Luftelement ist schwer zu kontrollieren, doch ich vertraue darauf, dass Eure Fertigkeiten alle Hindernisse überwinden, die Euch den Weg versperren.\n\nGeht zum äußersten Südrand des Brachlandes und betretet Tausend Nadeln. Dort, weit im Osten, werdet Ihr Prate Cloudseer finden. Sie wird Euch mehr beibringen.", progress = nil, completion = "Fürs Erste werde ich Euch geben, was Ihr benötigt, um Eure Sprüche zu fokussieren und die Geister der Luft anzurufen. Nehmt dieses Totem, und wenn Ihr bereit seid, übt noch etwas mehr mit mir.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHurtiger Wind\n\nIhr bekommt:\n\nLufttotem"},
[1534] = {title = "Ruf des Wassers", objective = "Füllt den leeren blauen Wasserschlauch bei den Sternenstaubruinen in Ashenvale und kehrt zu Brine im Brachland zurück.", description = "Nehmt diesen Wasserschlauch und begebt Euch tief in die dichten Wälder, die die Nachtelfen Ashenvale nennen. Sie liegen weit nördlich des Brachlandes.\n\nWenn Ihr den Wald betreten habt, reist nach Westen, an den Bergen entlang, die das Steinkrallengebirge und Ashenvale trennen. Jenseits des Mystralsees findet Ihr einen heiligen Ort: die Sternenstaubruinen. In der Mitte des Sees findet Ihr einen kleinen Brunnen.\n\nBringt mir eine Probe des Brunnenwassers. Das ist die letzte Komponente, die Ihr braucht, ehe ich Euch zu Islen zurückschicke.", progress = "Habt Ihr das Wasser schon, <Name>? Es heißt, die Ruinen werden von riesigen Kreaturen der Natur beschützt, die keine Besucher dulden, doch das könnten Mythen sein, um die Feinde der Nachtelfen einzuschüchtern.\n\nSeid dennoch vorsichtig.", completion = "Großartig, &lt;Name&gt;. Nachdem Ihr alle drei Proben gesammelt habt, kann ich für Euch eine Phiole des reinsten Wassers herstellen, das ein lebendiges Geschöpf finden kann. Es wird bei den nächsten Schritten Eures Initiationsritus Verwendung finden.\n\nEs freut mich, Euch in unserer Mitte begrüßen zu dürfen, &lt;Name&gt;. Ihr gereicht allen Schamanen zum Stolz. Ich kann es kaum erwarten, von Euren zukünftigen Taten zu hören.", rewards = "Ihr bekommt:\n\n"},
[1535] = {title = "Ruf des Wassers", objective = "Füllt den leeren braunen Wasserschlauch im Wasserloch unterhalb von Brines Hütte und kehrt damit zu Brine im Brachland zurück.", description = "Um Wissen zu erlangen und das Sapta von mir zu bekommen, dürft Ihr nur nach den reinsten Formen des Wassers suchen. Doch achtet auf Eure Umgebung, wenn Ihr die Proben für mich beschafft. Hütet Euch vor Kreaturen, die auf das Wasser angewiesen sind, das sie beschützen. Seht, wie es Wälder und Wüsten beeinflusst. Beobachtet, wie die Substanz, die das Leben erhält, Kreaturen dazu zwingt, Leben zu nehmen.\n\nWir beginnen mit einer einfachen Aufgabe: unterhalb meiner Hütte befindet sich ein Tümpel mit der kostbaren Flüssigkeit. Füllt diesen Schlauch damit und kehrt zu mir zurück.", progress = "Ich bin fast bereit, Euch die anderen Aufgaben zu geben. Habt Ihr den Schlauch schon gefüllt?\n\nIch weiß, welche Beschützerinstinkte die Stacheleber entwickeln können. Für sie bedeutet selbst so eine kleine Wasserquelle großen Reichtum. Bei der geringsten Menge Regen im Brachland feiern sie ein großes Fest. Wasser ist ihrer Art heilig, weil es so selten ist. Habt Ihr verstanden?", completion = "Ich dachte mir, dass es zu Blutvergießen kommt, wenn Ihr versucht, Wasser aus dem Teich zu schöpfen. Leider begreifen die Stacheleber nicht, dass alle Lebewesen miteinander verbunden sind; dass ihre Gier nur Leid und Schmerz über ihr Volk bringt. Wie viel könnten sie erreichen, wenn sie ihre Differenzen beilegen und ihre Klans vereinigen würden.\n\nNochmals, ein Jammer, aber vermutlich ein Segen für alle anderen Völker des Brachlandes.", rewards = "Ihr bekommt:\n\n"},
[1536] = {title = "Ruf des Wassers", objective = "Füllt den leeren roten Wasserschlauch am Brunnen in Tarrens Mühle und kehrt zu Brine im Brachland zurück.", description = "Vor langer Zeit folgte ich einigen Gefährten ins Vorgebirge von Hillsbrad. Wir verteidigten uns gegen einige aufmüpfige Menschen, die dort beheimatet sind, und kamen in eine kleine Stadt, die die Verlassenen übernommen hatten: Tarrens Mühle.\n\nDort fand ich etwas höchst Eigentümliches: In der Mitte der Stadt befand sich ein kleiner Brunnen mit frischem Quellwasser. Ich bin nicht sicher, ob die gebeutelten Bewohner der Stadt seinen Wert überhaupt kennen... er ist eine kleine heilige Insel in einem unheiligen Meer.\n\nBringt mir eine Probe dieses Wassers in diesem Wasserschlauch.", progress = "Der Brunnen, der mitten in der Stadt rein bleibt, erinnert mich an Geschichten, die mir in meiner Kindheit erzählt wurden, <Name>. Selbst in Zeiten von großem Schmerz und Kummer kann man ein Fünkchen Hoffnung finden, ein kleines Symbol, um das man sich schart. Das Orc-Volk sieht Thrall auf diese Weise. Er überlebte allen Widrigkeiten zum Trotz, erhob sich und führte unser Volk durch seine Kraft und sein Vorbild.\n\nIch bin nicht sicher, ob je ein Orc so viel gelitten hat wie er, aber gleichzeitig bin ich nicht sicher, ob je ein Orc stärker sein wird als er.", completion = "Das ist gut, &lt;Name&gt;. Ihr geht die vorliegende Aufgabe entschlossen an und seid fähig, das zu suchen, was benötigt wird.\n\nIch benötige nur noch eine Probe, um das Reagenz herzustellen, das für Euer Sapta erforderlich ist. Islen wird ebenfalls zufrieden sein.", rewards = "Ihr bekommt:\n\n"},
[1558] = {title = "Der Stonewroughtdamm", objective = "Begleitet Euren Schützling zum Stonewroughtdamm in Loch Modan. Geht mit ihm zur Mitte des Damms, damit er auf den riesigen Wasserfall heruntersehen kann.", description = "In der Nähe von Ironforge,  wo all die Zwerge und Gnome leben,  gibt es einen Ort namens Loch Modan und die Zwerge haben da einen grooooßen Staudamm gebaut. Ich hab gehört, dass ist eines von den größten Dingen, die je gebaut wurden. Wow!\n\nKannst du mit mir den Damm in Loch Modan zeigen, bitte?! Ich glaube der heißt Stone... äh... Stonewroughtdamm? Er ist riesig, soviel ist klar. Ich würde so gerne auf den großen Wasserfall heruntersehen. Ich verspreche mich auch nicht zu weit vorzulehnen.", progress = "Sind wir bald da?", completion = "WOW - Der Damm war tausendmal größer als ich gedacht habe! Bei dem lauten Rauschen des Wassers konnte ich mich kaum noch selber hören. Hey, glaubst du das dem Wasserfall jemals das Wasser ausgeht? Was passiert bloss wenn der Damm mal bricht? WOW, das wäre gruselig.\n\nDanke, dass du mir den Damm gezeigt hast. Das war sehr lieb von dir. Ich hab dir ja gesagt, dass ich mich nicht zu weit überlehnen werde!", rewards = "Ihr bekommt:\n\n"},
[1559] = {title = "Blitzstrahlbombenanleitung", objective = "Ihr seid also Ingenieur, hm? Als Dank für Eure Hilfe bei der Beschaffung der Perlen bekommt Ihr eine Anleitung für Blitzstrahlbomben.\n\nViel Glück und versucht, Euch nicht selbst zu blenden!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBauplan: Blitzstrahlbombe"},
[1560] = {title = "Toogas Bitte", objective = "Zeigt Tooga den Weg zurück zu seiner Frau Torta.", description = "Ich habe mich vollkommen verirrt!\n\nTorta, meine Frau, schickte mich Essen holen, aber ich muss irgendwo falsch abgebogen sein.\n\nWürdet Ihr so freundlich sein, mich zu Torta zurückzuführen? Sie wartet südlich von Steamwheedle auf mich.", progress = "Wo ist Tooga?", completion = "Er konnte also den Rückweg nicht allein finden? Typisch.\n\nAlso ich finde, Ihr verdient etwas für Eure Mühe...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nChelonische ManschettenBand der Großen Schildkröte\n\nIhr bekommt außerdem:\n\n"},
[1578] = {title = "Nachschub für die Front", objective = "Bringt 6 Kupferäxte und 6 Kupferne Kettengürtel zu Thorvald im südlichen Wachturm des Loch Modan.", description = "Die Gebirgsjäger vom Loch Modan kämpfen gegen Troggs und sind damit schwer beschäftigt! Sie benötigen konstanten Nachschub an neuen Rüstungen und Waffen, wenn wir diese Troggs je bezwingen wollen.\n\nDarum ist mein Kollege Thorvald hier und versucht, die Gebirgsjäger gut ausgerüstet zu halten. Wenn Ihr einige Kupferäxte und Kettengürtel aus Kupfer herstellen und sie Thorvald bringen könntet, wäre er Euch sehr verbunden. Vielleicht weiht er Euch sogar in sein Wissen ein.\n\nThorvald ist im südlichem Wachturm des Loch Modan.", progress = "Ich habe keine Zeit zu plaudern. Haben wir etwas miteinander zu tun?", completion = "Ah, Entschuldigung! Ich wusste nicht, dass Ihr hier seid, um die Truppen auszurüsten. Die Sachen, die Ihr hergestellt habt, werden eine große Hilfe sein!\n\nHier sind Pläne für einige Rüstungen. Ich hoffe, Ihr findet sie nützlich.", rewards = "Ihr bekommt:\n\nPläne: Kupferne Kettenweste"},
[1579] = {title = "Klemm-Muffen", objective = "Bringt 8 Klemm-Muffen zu Wizbang Cranktoggle in Auberdine.", description = "Ich kam nach Auberdine wegen der Ruhe. Ich möchte meine Erfindungen machen, wo es ruhig ist, denn nach einer durchzechten Nacht ertrage ich den Lärm von Ironforge nicht!\n\nDaher nahm ich ein Schiff nach Auberdine, trank aber unterwegs ein bisschen viel. Ich ließ meine Kiste mit Klemm-Muffen über Bord fallen! Ich brauche meine Klemmmuffen!\n\nIch weiß nicht genau, wo ich sie fallen ließ, aber vielleicht habt Ihr ja Glück, wenn Ihr im Meer danach fischt...", progress = "Habt Ihr meine Klemm-Muffen gefunden, <Name>? Ohne meine Klemm-Muffen kann ich meine Stintelpleuel nicht nachziehen!", completion = "Ich kann nicht glauben, dass Ihr sie gefunden habt! Ihr seid der &lt;Volk&gt; mit dem meisten Glück in Kalimdor!", rewards = "Ihr bekommt:\n\n"},
[1580] = {title = "Elektropeller", objective = "Bringt 12 Elektropeller zu Wizbang Cranktoggle in Auberdine.", description = "Wir wissen, dass Ihr Glück habt, aber... wie viel Glück genau, <Name>?\n\nEines Nachts schlenderte ich durch die Straßen von Dunkelküste. Ich suchte nach einem geeigneten Fluss oder See, um meine neuen propellerbetriebenen explodierenden Entenattrappen auszuprobieren. Ich muss wohl etwas beschwipst gewesen sein, denn Stunden später wachte ich in Auberdine auf. Mein Haar war versengt und meine Tasche mit den Elektropellern war weg! Sie müssen mir ins Wasser gefallen sein!\n\nIch brauche diese Elektropeller! Vielleicht könnt Ihr sie aus einem See oder Bach in Dunkelküste fischen...", progress = "Habt Ihr meine Elektropeller gefunden? Ich brauche sie, wenn ich meine Forschungen über Entenattrappen fortsetzen soll...", completion = "Ich kann es nicht glauben! Ihr habt sie gefunden! Ihr seid der beste Angler, den ich je gesehen habe!\n\nDanke, &lt;Name&gt;. Und hier, nehmt dies. Ihr seid so gut und braucht sie wahrscheinlich nicht, aber sie helfen Euch beim Angeln.", rewards = "Ihr bekommt:\n\nAquadynamische Fischlinse"},
[1581] = {title = "Elixiere für die Bladeleafs", objective = "Bringt 6 Elixiere Löwenkraft und 2 Elixiere der schwachen Verteidigung zu Syral Bladeleaf in Dolanaar.", description = "Unser Kräuter- und Alchimie-Laden floriert, aber mein Mann verbringt so viel Zeit damit, Tränke zu mischen, dass wir nie Zeit füreinander haben.\n\nKönnt Ihr uns helfen?\n\nWenn Ihr mir einen Vorrat an vorgefertigten Elixieren bringt, würde ich mit Freuden mit Euch tauschen. Ich besitze gewisse rare Kräuter, die Euch nützlich sein könnten.", progress = "Hallo, <Name>. Habt Ihr die Elixiere zum Tauschen?", completion = "Die sind ordentlich gemischt. Ihr nehmt Euer Handwerk ernst, &lt;Name&gt;, und das ist wichtig für einen Alchimisten.\n\nHier sind Eure frisch gesammelten Kräuter. Benutzt sie mit Umsicht.", rewards = "Ihr bekommt:\n\nErdwurzelMaguskönigskraut"},
[1582] = {title = "Mondscheinweste", objective = "Bringt 1 geprägten Lederhandschuh, 5 geprägte Lederstiefel und 5 geprägte Lederumhänge zu Lotherias in Darnassus.", description = "Wir in Darnassus, besonders wir Handwerker, sind sehr beschäftigt. Junge Abenteurer brennen darauf, sich in der Wildnis zu beweisen, und benötigen unablässig Nachschub.\n\nWenn Ihr mir helft, meine Bestellungen an Lederwaren zu erfüllen, kann ich Euch vielleicht eine hochentwickelte Technik der Lederverarbeitung beibringen.", progress = "Seid gegrüßt, <Name>.", completion = "Ja, das sind gute Stücke. Ihr habt eine geschickte Hand und ein Auge für Details. Eure Zukunft als Lederer scheint viel versprechend.\n\nHier, &lt;Name&gt;. Lasst mich Euch das Muster für eine Mondscheinweste zeigen.", rewards = "Ihr bekommt:\n\nMuster: Mondscheinweste"},
[1598] = {title = "Der gestohlene Foliant", objective = "Holt \"Die Macht der Leere\" für Drusilla La Salle zurück.", description = "Ihr da! <Name>, richtig?\n\nIch hoffe, Ihr seid sicher, dass Ihr ein Hexenmeister werden möchtet, denn wenn Ihr nicht allein besteht, werdet Ihr gewiss untergehen.\n\nIch werde Euch unterrichten, muss aber zuerst sicher sein, dass Ihr stark genug seid.\n\nEin Novize, der an der Abtei studierte, lief weg und schloss sich der Bruderschaft der Defias an. Warum mich das kümmert? Weil er einige wichtige Bücher gestohlen hat.\n\nEines davon war ein Buch, das ich selbst wollte, \"Die Macht der Leere\". Stehlt es für mich, sie haben es in ihrem Zelt in den Weinbergen versteckt.", progress = "Es wäre zu auffällig für mich gewesen, das Buch selbst zu stehlen. Zum Glück hat mir einer ihrer eigenen Trottel die Drecksarbeit abgenommen.", completion = "Exzellent... Ich wäre nie an diesen Text rangekommen. Er wurde in einem gesicherten Flügel der Bibliothek verwahrt und es hätte verdächtig ausgesehen, wenn ich dort herumgeschlichen wäre.\n\nIhr habt Eure Sache gut gemacht, als Ihr das geholt habt. Ich bin überzeugt, Ihr werdet mit einem eigenen Wichtel fertig, daher sehe ich keinen Grund, Euch nicht zu zeigen, wie man einen beschwört.", rewards = "Ihr erlernt:\n\nWichtel beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWichtel beschwören' lehren\n\nIhr bekommt außerdem:\n\n"},
[1599] = {title = "Anfänge", objective = "Bringt 3 Federglücksbringer zu Alamar Grimm in Anvilmar.", description = "Ihr müsst der neue Hexenmeister sein, über den alle tuscheln. Jemand muss Euch sehr mögen, wenn man mich bittet, meine Forschungen aufzuschieben und Eure Ausbildung zu übernehmen.\n\nKeine Bange, ich mache Euch keinen Vorwurf.\n\nDer einfachste Beschwörungszauber, den Ihr lernen werdet, ist der für einen Wichtel. Doch bevor ich ihn Euch beibringe, müsst Ihr beweisen, dass Ihr die notwendigen magischen und körperlichen Fähigkeiten besitzt.\n\nBringt mir drei Federglücksbringer von den Novizen der Frostmane aus der Höhle im Südwesten.", progress = "Diese Federglücksbringer der Novizen besitzen eine Art von magischer Kraft. Es wird interessant sein, sie zu erforschen. Hätte ich von den Trollen gar nicht erwartet.", completion = "Sehr gut, sehr gut! Ihr habt Eure Sache gut gemacht, &lt;Name&gt;. Vielleicht ist das Interesse, das man Euch entgegenbringt, ja doch gerechtfertigt.\n\nAber das müssen andere entscheiden... vorausgesetzt, Euer Wichtel überwältigt Euch nicht und bereitet damit Eurer Karriere ein vorzeitiges Ende. Vorerst bin ich schon damit zufrieden, dass Ihr die ersten Monate als &lt;Klasse&gt; vermutlich überleben werdet.\n\nEin Wort zu dem Wichtel, &lt;Name&gt;. Lasst Euch, wie jeder &lt;Volk&gt; weiß, nicht von der Größe täuschen, seine Magie kann sehr gefährlich sein.", rewards = "Ihr erlernt:\n\nWichtel beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWichtel beschwören' lehren\n\nIhr bekommt außerdem:\n\n"},
[1618] = {title = "Die Aufrüstung im Rotkammgebirge", objective = "Tormus Deepforge möchte, dass Ihr 4 runenverzierte Kupfergürtel und 4 schwere Kupferschlägel zu Verner Osgood ins Rotkammgebirge bringt.", description = "Wir Zwerge sind nicht die Einzigen, die kämpfen. Unsere menschlichen Verbündeten haben auch alle Hände voll zu tun!\n\nDas Rotkammgebirge wird immer wieder von den Blackrockorcs angegriffen und der Vorrat an Ausrüstung ist stets knapp. Ich bin sicher, wenn Ihr ihnen helft, wird der ansässige Schmied, Verner Osgood, Euch den einen oder anderen Trick beibringen.", progress = "Ich hoffe, Ihr bringt gute Nachrichten aus Ironforge. Denn ich bin mit meiner Weisheit am Ende!", completion = "Danke, &lt;Name&gt;. Das wird mir unwahrscheinlich helfen. Da die Orcs der Blackrock von der Burg Steinwacht angreifen und die Rotkammgnolle in den Vorgebirgen im Norden lauern, muss ich ständig Rüstungen ausbessern und neue Waffen für unsere Truppen anfertigen.\n\nDie Vorräte, die Ihr gebracht habt, bescheren mir einen Moment Ruhe. Daher habe ich genug Zeit, Euch etwas beizubringen...", rewards = "Ihr bekommt:\n\nPläne: Ironforgebrustplatte"},
[1638] = {title = "Die Ausbildung eines Kriegers", objective = "Sprecht mit Harry Burlguard.", description = "Ihr habt Euch als fähiger Krieger erwiesen, <Name>. Aber Ihr seid noch jung und müsst noch viel lernen.\n\nSprecht mit Harry Burlguard... er ist meist in der Taverne Zum pfeifenden Schwein in der Altstadt von Stormwind. Harry ist ein alter Veteran und guter Lehrer. Er kann Euch einige Kampftechniken zeigen, die Euer Leben verlängern.", progress = nil, completion = "Oh-ho! Trinkt einen Schluck mit mir, Junge. Äußerlich macht Ihr einen zähen Eindruck. Mal sehen, ob Euer Magen ein paar Krüge vom Stärksten aus dem Pfeifenden Schwein verträgt!!!\n\nOder... seid Ihr wegen einer Lektion hier?", rewards = "Ihr bekommt:\n\n"},
[1639] = {title = "Bartleby der Trunkenbold", objective = "Sprecht mit Bartleby.", description = "Ja, ich kann Euch unterrichten. Aber vorher will ich sehen, welche Kampftechniken Ihr schon beherrscht.\n\nSeht Ihr den Betrunkenen am Ende der Bar? Bartleby? Nehmt ihm seinen Krug weg.\n\nHa, und wenn Ihr Bartleby kennt, dann wisst Ihr, dass er ihn nicht freiwillig rausrückt.", progress = nil, completion = "Hallo, mein Junge! Was hat jemand wie Ihr im Pfeifenden Schwein verloren? Vorsicht, sonst brecht Ihr Euch einen Nagel ab...", rewards = "Ihr bekommt:\n\n"},
[1640] = {title = "Besiegt Bartleby", objective = "Besiegt Bartleby und redet dann mit ihm.", description = "Ihr wollt was??? Ihr seid verrückt!\n\nWenn Ihr diesen Krug wollt, müsst Ihr ihn mir aus den kalten, toten Händen brechen...", progress = "Wenn Ihr diesen Krug wollt, müsst Ihr ihn mir aus den kalten, toten Händen brechen...", completion = "Ihr seid viel zäher als Ihr ausseht!", rewards = "Ihr bekommt:\n\n"},
[1641] = {title = "Der Foliant der Offenbarung", objective = "Hier in Stormwind bin ich dafür verantwortlich, die Paladine auf den Pfad der größten Tugend zu bringen, sobald sie sich dem Weg des Lichts verschreiben und Azeroth vor der Geißel und anderen Bedrohungen verteidigen.\n\nDie Zeit ist gekommen, den ersten Schritt hin zu wahrer Tugend zu tun. Wenn Ihr einverstanden seid, gebe ich Euch das Buch der Offenbarung. Wenn Ihr es studiert, erfahrt Ihr etwas über das Licht und was von Euch erwartet wird. Wenn Ihr es versteht und tüchtig seid, werdet Ihr erfolgreich größere Fähigkeiten erlangen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFoliant der Offenbarung"},
[1642] = {title = "Der Foliant der Offenbarung", objective = "Sprecht mit Duthorian Rall in Stormwind.", description = "Ein Paladin muss in allen Dingen das Licht widerspiegeln, das uns Kraft gibt. Wenn einer unserer Art nach dem Göttlichen strebt, bedeutet das nicht, dass er ein Gott sein möchte... wir trachten nur danach, in allem nur Gutes zu tun.\n\nAuch wenn Ihr in diesen schweren Zeiten berufen seid, das Böse zu zerschmettern, dürft Ihr nicht vergessen, dass die Unterstützung anderer Euch wahrhaft von den Bürgern von Azeroth unterscheidet. Mitgefühl, Geduld, Tapferkeit... das alles bedeutet einem Paladin so viel wie Kraft im Kampf.\n\nBedenket das und vergesst es niemals.", progress = nil, completion = "Abermals hallo, &lt;Name&gt;. Was machen Eure Studien des Folianten der Offenbarung?\n\nDann solltet Ihr bereit sein, Euch prüfen zu lassen. Es gibt in der Stadt und unseren Ländern immer etwas zu tun; barmherzige und verständnisvolle Taten; Menschen, die Hilfe brauchen; Kreaturen, die besiegt werden müssen.\n\nWenn Ihr beweist, dass Ihr die Geduld habt, anderen zu helfen, besonders jenen, die nicht so glücklich sind, beweist Ihr, dass Ihr ein Diener des Lichts und bei klarem Verstand seid.", rewards = "Ihr bekommt:\n\n"},
[1643] = {title = "Der Foliant der Offenbarung", objective = "Sucht im Handelsdistrikt von Stormwind nach Stephanie Turner.", description = "Eure Aufgabe, <Name>, besteht darin, jemanden hier in Stormwind zu finden, der der Hilfe bedarf. Jemanden mit reinem Herzen und edlen Motiven. Vielleicht jemanden, der anderen hilft. Vielleicht jemanden, der einen Führer braucht. Was auch immer, die Person muss edle Absichten haben und auf Eure Güte angewiesen sein.\n\nMacht das und kommt zu mir zurück, wenn Ihr fertig seid. Dann sprechen wir weiter über Euren Weg und was es bedeutet, ein Paladin des Lichts zu sein.", progress = nil, completion = "Ach, hallo. Was machen Eure Abenteuer? Oh, freut mich zu hören, dass alles gut läuft.\n\nOh, ich? Danke der Nachfrage - alles in allem geht es mir ganz gut.\n\nDurch die wachsende Zahl der Händler sind die Leute nicht mehr so bereit, sich von Leder und Tuch zu trennen, Daher ist es schwerer, Kleidung für die Kinder im Waisenhaus zu machen, aber wir bekommen das schon hin. Mit \"wir\" meine ich meinen Mann und mich. Er ist in Ironforge und sucht dort Hilfe bei den Bürgern.", rewards = "Ihr bekommt:\n\n"},
[1644] = {title = "Der Foliant der Offenbarung", objective = "Bringt 10 Stück Leinenstoff zu Stephanie Turner in Stormwind.", description = "Die meisten der guten Seelen haben keine Familien mehr aufgrund der Angriffe der Geißel im letzten Jahrzehnt.\n\nMein Mann John sammelt die Materialien, die ich brauche, um Hemden und Hosen für die Kinder zu machen, aber nicht einmal dafür hatte ich Zeit. Ich war zu sehr damit beschäftigt, ihnen Essen auf ihre Teller und ein Dach über ihre Köpfe zu geben.\n\nWie war das? Ihr wärt bereit, mir zu helfen? Oh, dem Licht sei Dank und Euch ebenfalls, <Name>.\n\nWenn Ihr mir etwas Leinen bringen könntet, damit ich den Kindern Kleidung nähen kann, wäre mir das eine große Hilfe.", progress = "Ich hoffe, John hat in Ironforge mehr Glück. Die Ausflüge dorthin sind ihm so zuwider, weil er mich und die Kinder allein lassen muss, aber er weiß, es geht nicht anders. Er ist so herzensgut.\n\nManche Jahre waren besser als andere, aber dieses war bei weitem das Schlimmste. Es ist fast, als würde eine gewaltige Veränderung in der Luft liegen. Wer weiß?", completion = "Danke &lt;Name&gt;, vielen, vielen Dank!\n\nDie Kinder werden sich freuen und Ihr habt mir so viel Zeit gespart. Jetzt kann ich mich auf die anderen Bedürfnisse der Kinder konzentrieren und mein John hoffentlich früher heimkehren als wir dachten.\n\nNochmals danke, &lt;Name&gt;. Ich wusste, ich kann mich auf die Barmherzigkeit anderer verlassen. Das Licht sei mit Euch.", rewards = "Ihr bekommt:\n\n"},
[1645] = {title = "Der Foliant der Offenbarung", objective = "Welche Freude, Euch zu sehen, <Name>. Ich bringe die Paladine auf den Pfad der Tugend, wenn sie sich dem Weg des Lichts verschreiben und Azeroth vor der Geißel und anderen Bedrohungen beschützen.\n\nDie Zeit ist gekommen, den ersten Schritt hin zu wahrer Tugend zu tun. Wenn Ihr einverstanden seid, gebe ich Euch den Folianten der Offenbarung. Wenn Ihr es studiert, erfahrt Ihr etwas über das Licht und was von Euch erwartet wird. Wenn Ihr es versteht und tüchtig seid, werdet Ihr erfolgreich größere Fähigkeiten erlangen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFoliant der Offenbarung"},
[1646] = {title = "Der Foliant der Offenbarung", objective = "Sprecht mit Tiza Battleforge in Ironforge.", description = "Ein Paladin muss in allen Dingen das Licht widerspiegeln, das uns Kraft gibt. Wenn einer unserer Art nach dem Göttlichen strebt, bedeutet das nicht, dass er ein Gott sein möchte... wir trachten nur danach, in allem nur Gutes zu tun.\n\nAuch wenn Ihr in diesen schweren Zeiten berufen seid, das Böse zu zerschmettern, dürft Ihr nicht vergessen, dass die Unterstützung anderer Euch wahrhaft von den Bürgern von Azeroth unterscheidet. Mitgefühl, Geduld, Tapferkeit... das alles bedeutet einem Paladin so viel wie Kraft im Kampf.\n\nBedenket das und vergesst es niemals.", progress = nil, completion = "Willkommen zurück, &lt;Name&gt;. Ich hoffe, Ihr habt die Zeit genutzt und das Buch gelesen.\n\nDann solltet Ihr bereit sein, Euch prüfen zu lassen. Es gibt in der Stadt und unseren Ländern immer etwas zu tun; barmherzige und verständnisvolle Taten; Menschen, die Hilfe brauchen; Kreaturen, die besiegt werden müssen.\n\nWenn Ihr beweist, dass Ihr die Geduld habt, anderen zu helfen, besonders jenen, die nicht so glücklich sind, beweist Ihr, dass Ihr ein Diener des Lichts und bei klarem Verstand seid.", rewards = "Ihr bekommt:\n\n"},
[1647] = {title = "Der Foliant der Offenbarung", objective = "Sucht im äußeren Ring von Ironforge nach John Turner.", description = "Eure Aufgabe, <Name>, ist es, jemanden hier in Ironforge zu finden, der der Hilfe bedarf. Jemand mit reinem Herzen und edlen Motiven. Vielleicht jemanden, der anderen hilft. Vielleicht jemanden, der einen Führer braucht. Was auch immer, die Person muss edle Absichten haben und auf Eure Güte angewiesen sein.\n\nMacht das und kommt zu mir zurück, wenn Ihr fertig seid. Dann sprechen wir weiter über Euren Weg und was es bedeutet, ein Paladin des Lichts zu sein. Ich warte hier im Tempel auf Eure Rückkehr. Auch andere Paladine brauchen meine Unterstützung.", progress = nil, completion = "DAS WAISENHAUS VON STOR... oh, tut mir Leid, ich wollte Euch nicht anschreien, Sire,\n\nIch heiße John Turner. Wie ist das werte Befinden?\n\nGut, gut, freut mich zu hören, dass alles gut für Euch läuft. Ich hatte schon einen langen Arbeitstag und vermisse meine Frau sehr, aber das ist der Preis, den man zahlt, wenn es Mäuler zu füttern und Leiber zu bekleiden gilt.", rewards = "Ihr bekommt:\n\n"},
[1648] = {title = "Der Foliant der Offenbarung", objective = "Bringt 10 Stück Leinenstoff zu John Turner in Ironforge.", description = "Meine Frau und ich führen das Waisenhaus in Stormwind, das überwiegend Kindern vorbehalten ist, die im letzten Jahrzehnt ihre Eltern bei Angriffen der Geißel verloren haben. Ich komme etwa einmal im Monat nach Ironforge und versuche, bei den Bürgern hier mehr Vorräte zu sammeln und mit den verschiedenen Gruppen zu reden, ob sie irgendwie helfen können.\n\nDieser Ausflug war schrecklich langwierig und nicht sehr ergiebig.\n\nKönnte ich doch nur noch etwas mehr Leinen bekommen, damit meine Frau Kleidungsstücke nähen kann, dann könnte ich endlich eine Ladung nach Hause schicken.", progress = "Bei dem Zustrom von Händlern hier und in ganz Azeroth, sind die Gegenstände knapper, aus denen wir Kleidung für die Kinder in unserem Waisenhaus machen. Es ist sehr anständig von Euch, dass Ihr mir helft, Leinen zu sammeln, damit meine Frau neue Kleidung nähen kann, <Name>. Danke.\n\nHoffentlich kann ich bald zu meiner Frau heimkehren.", completion = "Das ist so wunderbar von Euch, &lt;Name&gt;. Nochmals danke.\n\nEs ist so anständig von Euch, Mann, dass Ihr das für mich tut. Es ist schön zu sehen, dass Ihr dem Licht folgt. Gäbe es doch nur einen Weg, wie ich Euch vergelten könnte, was Ihr getan habt... wie war das? Es war das Mindeste, das Ihr tun konntet? Seht Ihr? Genau das meine ich, &lt;Name&gt;, edel bis zuletzt.\n\nMöget Ihr sicher wandeln und das Licht Euch auf Euren Reisen beschützen.", rewards = "Ihr bekommt:\n\n"},
[1649] = {title = "Der Foliant der Ehre", objective = "Sprecht mit Duthorian Rall in Stormwind.", description = "Ehre, und alle Tugenden, die damit einhergehen, sind wie rare Mineralien: man muss sie ihres Wertes wegen bewundern, wenn man sie findet, aber man muss sich auch die Zeit nehmen, sie aufzuheben... zu veredeln. Mischt man sie richtig, entsteht eine starke Legierung, die manchmal selbst die heftigsten Hiebe nicht zerbrechen können.\n\nDiese Kraft, Euer Glauben, Eure Tapferkeit, müssen geprüft werden. Ihr müsst lernen, niemals den Glauben zu verlieren und erkennen, dass Ihr mit der Macht des Lichts Dinge überwinden könnt, vor denen andere klein beigeben müssen.", progress = nil, completion = "Ah, Ihr möchtet eine Prüfung Eurer Ehre von mir. Großartig.\n\nEs gibt viele Aufgaben in der Stadt und dem Umland, die Herausforderungen bieten und wo Männer mit Euren Fertigkeiten gebraucht werden.\n\nIhr solltet diese Prüfung nicht zu leicht nehmen, &lt;Name&gt;. Dies könnte, wie so vieles auf unserem Weg, unser Leben kosten. Die Kirche möchte ihre Schäflein stets mehren, weiß aber um die Opfer, die gebracht werden müssen, um den Wert der Paladine, die ihr dienen, zu beweisen.\n\nSeid Ihr bereit?", rewards = "Ihr bekommt:\n\n"},
[1650] = {title = "Der Foliant der Ehre", objective = "Sucht Daphne Stilwell in Westfall.", description = "Gut! Da Ihr nicht zögert, seid Ihr gewiss bereit und brennt darauf, Euch zu beweisen. So sei es.\n\nAm äußersten Ende von Longshore in Westfall steht ein kleines Haus über dem Ozean. Dort lebt ein Paar, die Stilwells. Jordan ist ein unglaublicher Schmied und für einige Zeit nach Ironforge gegangen, um sich mit den Zwergen zu treffen. Dadurch ist seine Frau Daphne allein und schutzlos.\n\nEs wird berichtet, dass die Defias fast das gesamte Gebiet übernommen haben. Gut möglich, dass Daphne Schutz vor den Bösewichtern braucht. Geht dorthin.", progress = nil, completion = "Hallo, &lt;Name&gt;. Wenn ich Eure Rüstungen und Waffen sehe, denke ich, dass Ihr mir entweder mein Land wegnehmen wollt oder die Kirche endlich jemanden zu meinem Schutz geschickt hat, so lange Jordan fort ist.\n\nDarf ich mich Euch vorstellen: Ich bin Daphne Stilwell. Ist mir ein Vergnügen.\n\nUnd Ihr kommt nicht zu spät... Seit dem letzten Sonnenaufgang habe ich erst ein halbes Dutzend dieses Abschaums getötet. Sie brauchen eine Weile, bis sie um die Kurve gebogen sind, aber sie haben Euch vermutlich gesehen. Dies bedeutet, dass sie wahrscheinlich jede Minute hier sein werden.", rewards = "Ihr bekommt:\n\n"},
[1651] = {title = "Der Foliant der Ehre", objective = "Verteidigt Daphne Stilwell vor dem Angriff der Defias.\n\nKeiner Eurer Geister darf aus seinen irdischen Fesseln befreit werden, wenn Ihr erfolgreich sein wollt.\n\nSprecht erneut mit Daphne Stilwell, wenn Ihr erfolgreich wart.", description = "Ich wette, die kommen bald wieder, also macht Euch bereit.\n\nIch habe eine Schusswaffe im Haus. Ich hole sie und helfe Euch gern, aber Ihr werdet weitgehend auf Euch gestellt sein.\n\nIch habe keine Ahnung, wie viele sie schicken, aber es werden sicher mehr sein als die paar beim letzten Mal.\n\nBittet das Licht um jeden erdenklichen Segen, denn ... habt Ihr das gehört? Ich glaube, sie kommen.\n\nWir beziehen Position beim Haus!", progress = "Wir werden unsere Position beim Haus beziehen!", completion = "Wir haben es geschafft, &lt;Name&gt;! Danke für Eure Hilfe. Ihr wart wirklich erstaunlich da draußen. Ich hätte nie gedacht, dass es ein &lt;Klasse&gt; mit so vielen Gegnern gleichzeitig aufnehmen kann.\n\nIhr habt wahrlich Tapferkeit im Angesicht einer Übermacht gezeigt.", rewards = "Ihr bekommt:\n\n"},
[1652] = {title = "Der Foliant der Ehre", objective = "Sprecht mit Duthorian Rall in Stormwind.", description = "Kehrt bitte zu Duthorian zurück und lasst ihn wissen, dass ich hier vorerst sicher bin. Dafür muss ich Euch und der Kirche danken.\n\nEr wird eine Nachricht nach Ironforge schicken und meinen Jordan wissen lassen, dass er keinen Grund zur Furcht hat.\n\nOh, ich vermisse meinen Mann so sehr. Ich kann es kaum erwarten, bis er wieder da ist.", progress = nil, completion = "So begegnen wir uns wieder, &lt;Name&gt;, und wie ich sehe, seid Ihr bester Laune.\n\nDas Heim der Stilwells ist wieder einen Tag sicher, und Eurer Geschichte entnehme ich, dass es an Gefahren nicht gemangelt hat. Gut gemacht.\n\nDaphne und Jordan haben der Kirche sehr geholfen. Dass wir ihr Eigentum - und ihr Leben - durch Euch beschützen ließen, war das Geringste, was wir für sie tun konnten.\n\nIhr werdet für Euren Wagemut belohnt werden.", rewards = "Ihr erlernt:\n\nUntote spüren\n\nDer folgende Zauber wird auf euch gewirkt:\n\nUntote spüren\n\nIhr bekommt außerdem:\n\nBastion von Stormwind"},
[1653] = {title = "Die Prüfung der Rechtschaffenheit", objective = "Sprecht mit Jordan Stilwell in Ironforge.", description = "Ich zweifle nicht daran, dass Jordan Euch persönlich danken möchte, und da ich einen Boten brauche, der ihn wissen lässt, dass es seiner Frau gut geht, scheint Ihr mir die perfekte Wahl zu sein.\n\nJordan sollte ein Paladin des Lichts sein, bevor die Liebe zum Beruf seines Vaters ihn einen anderen Weg einschlagen ließ - er ist innig mit unserer Lebensweise vertraut und wird zu unseren Getreuesten gerechnet.\n\nEr müsste noch in Ironforge sein - tagsüber arbeitet er gern vor den Toren, wohl wegen der kühlen Bergluft.", progress = nil, completion = "Guten Tag, &lt;Name&gt;. Das Licht ist mit Euch, nehme ich an?\n\nWie war das? Duthorian hat Euch geschickt!? Meine Frau, wie geht es ihr? Ich wusste, es würde Ärger geben, wenn ich fortgehe. Bitte sagt mir, dass sie... oh, welch ein Glück. Ich bin so froh, dass sie in Sicherheit ist. Die Defias waren lange vor diesen Angriffen eine Bedrohung, aber jetzt können es die Berater des Königs nicht mehr leugnen.\n\nWas hat Duthorian noch gesagt?\n\nIhr wart es, der meine Frau beschützt hat? Dann danke ich Euch nochmals, &lt;Name&gt;. Eine bessere Prüfung der Ehre kann ich mir nicht vorstellen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1654] = {title = "Die Prüfung der Rechtschaffenheit", objective = "Sucht mit Jordans Waffennotizen etwas Weißsteineichenholz, Bailors aufbereitete Erzlieferung, Jordans Schmiedehammer und einen Kor-Edelstein und bringt alles zusammen zu Jordan Stilwell in Ironforge.", description = "Ich würde Euch gern eine Belohnung geben, wenn Ihr bereit seid, eine anzunehmen. Missversteht mich nicht, meine Großzügigkeit hängt davon ab, wie hilfreich Ihr sein könnt, aber ich denke, wir werden beide von einer derartigen Allianz profitieren.\n\nIch werde Euch eine Waffe schmieden, die Eurer Leistung würdig ist, ein Symbol der Paladinschaft und des Lichts, doch zuvor müsst Ihr die Gegenstände sammeln, die ich zu seiner Herstellung brauche. Ich habe schon angefangen, mir Notizen zu den Gegenständen zu machen, und brauche nur jemanden, der tapfer und geschickt genug ist, sie zu beschaffen. Was sagt Ihr dazu, <Klasse>?", progress = "Es dürfte schwer sein, die Gegenstände zu bekommen, die Ihr sucht, aber ich versichere Euch, die Waffe, die ich für Euch anfertige, rechtfertigt den Aufwand.\n\nSie wird meine bis dato beste Arbeit werden, und doch nur ein geringer Lohn für den Dienst, den Ihr mir erwiesen habt.", completion = "Das ist wunderbar! Ihr habt alle Gegenstände bekommen.\n\nDamit müsste ich Euch problemlos eine grandiose Waffe schmieden können. Ích hatte seit langem Pläne dafür, aber bisher nie Gelegenheit gefunden, die Zutaten herbeizuschaffen. Danke, &lt;Name&gt;.\n\nEs tut gut, wieder den Hammer meines Vaters zu schwingen... und einen Edelstein aus Kor, ich dachte nicht, dass ich je selbst einen sehen würde.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1655] = {title = "Bailors Erzlieferung", objective = "Bringt Jordans Erzlieferung zu Bailor Stonehand am Loch Modan.", description = "Ach, Ihr habt mich erschreckt, <Mann/Frau>! Seht Ihr nicht, dass ich nachdenke?\n\nWie war das? Jordans Lieferung... für Ironforge. Ahhh, ja, ich weiß, wovon Ihr sprecht. Oger der Mo'grosh haben die Erzlieferung meines alten Freundes gestohlen. Die Karawane war auf dem Weg vom Sumpfland hierher und geriet in einen Hinterhalt. Die Wache, die den Angriff überlebte, starb vor wenigen Tagen - der Heiler kam nicht schnell genug hin.\n\nWenn Ihr die Lieferung wollt, müsst Ihr über den Loch nach Nordosten. Dort muss sie irgendwo sein.", progress = "Aha, schon Glück gehabt? Ha-ha, diese Oger konnten Euch nichts anhaben, was?", completion = "Woll, woll, das ist es. Ha! Hätte ich gewusst, dass Ihr wirklich da rausgeht und gegen diese Oger kämpft, hätte ich Euch eine ganze Liste von Aufträgen gegeben, nicht nur diesen einen. Aber Ihr seid nicht hier, um Geschäfte für mich zu machen, oder?\n\nAbgemacht ist abgemacht; Jordan wollte eine Lieferung meiner Legierung, und die soll er bekommen.\n\nGrüßt ihn von mir, und gute Reise, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\nJordans aufbereitete Erzlieferung"},
[1656] = {title = "Eine unvollendete Aufgabe", objective = "Bringt das Bündel Felle zu Gastwirt Kauth in Bloodhoof.", description = "<Name>, bitte, ich flehe Euch an, könnt Ihr mir helfen? Ich habe meine Aufgaben hier auf der Mesa noch nicht beendet - ich bin mitten in meinem Ritual der Kraft - und mein Vater bat mich, diese Felle im Gasthaus von Bloodhoof abzuliefern.\n\nIch bin längst nicht erholt genug, mein Ritual und diese Aufgabe für meinen Vater zu beenden. Würdet Ihr an meiner statt gehen?\n\nDas Gasthaus ist angenehm und eine perfekte Oase der Ruhe auf langen Reisen. Ich bin sicher, Ihr stimmt mir zu, wenn Ihr es seht.", progress = "Ja, Kindchen? Was kann Kauth für Euch tun?\n\nDie Reise von der Mesa hierher kann für manche eine enorme Last, aber für andere eine willkommene Abwechslung sein. Was ist sie wohl für Euch, frage ich mich...", completion = "Ah, die Felle, auf die ich gewartet habe! Danke.\n\nSie kamen schneller als ich erwartet hatte. Ich mache gute Decken für meine Logiergäste daraus.\n\nIhr könnt gern bleiben, so lange Ihr möchtet. Mein Gasthaus ist stets offen und alle Eures Volkes sind willkommen. Und unterschätzt eine angenehme Nachtruhe nicht, ihr kann auf Reisen eine große Bedeutung zukommen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZäher Brocken BrotErfrischendes Quellwasser\n\nIhr bekommt außerdem:\n\n"},
[1657] = {title = "Die Verpestung von Southshore", objective = "Werft drei Stinkbomben der Verlassenen ins Herz von Southshore in Hillsbrad und kehrt zu Ruferin der Dunkelheit Yanka beim Fest des Weidenmanns in Tirisfal zurück.", description = "Feiert die Schlotternächte mit Stil... bereitet unseren Feinden in Southshore Kummer!\n\nNehmt eine dieser speziell angefertigten Stinkbomben. Sie sind mit einem derartig furchtbaren Schrecken gefüllt, dessen Geruch kein Mensch - oder anderes Wesen mit schwachem Gemüt - ertragen kann. Ihr müsst die Stinkbombe direkt ins Herz von Southshore werfen, damit sie richtig wirken kann. Seid also auf eine Auseinandersetzung mit der Allianz gefasst!\n\nSolltet Ihr diese Aufgabe bewältigt haben, kehrt zu mir zurück... es ist ein Beitrag zu unserer Befreiung!", progress = nil, completion = "Ah, gut gemacht! Ich hoffe die Allianz erstickt an dem fauligen Gift, das wir ihnen verabreicht haben, genauso wie wir den Witz der Versklavung an die Geißel schlucken mussten!\n\nIhr habt die wahre Bedeutung der Schlotternächte erhalten, &lt;Name&gt;, ich danke Euch dafür. Lasst mich ein paar Schlotternachtssüßigkeiten mit Euch als zusätzliche Belohung teilen. Ihr werdet sie sicher als eine recht angenehme Abwechslung betrachten!", rewards = "Ihr bekommt:\n\nKürbisdrops der Schlotternächte"},
[1658] = {title = "Bespitzelt das Fest des Weidenmanns", objective = "Macht das Fest des Weidenmanns der Verlassenen in Tirisfal ausfindig. Kehrt zu Sergeant Hartman in Southshore zurück, sobald Ihr Eure Mission erfüllt habt.", description = "Ich brauche mutige Freiwillige, die nach Tirisfal ziehen und das Fest des Weidenmanns auskundschaften. Ich möchte nicht lügen - diese Mission ist äußerst gefährlich. Die Wachen des Fests werden besonders bösartig sein. Trotzdem, wir müssen in Erfahrung bringen wie groß das Fest dieses Jahr ist und wieviel Schaden die Verlassenen dieses Mal während der Schlotternächte anrichten.\n\nSolltet Ihr dabei sein, dann geht nach Tirisfal und kundschaftet das Fest aus. Kehrt mit den Informationen zu mir zurück und ich werde für eine angemessene Belohnung sorgen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Das Fest des Weidenmanns wird auch noch zukünftig für Ärger sorgen, wenn die abscheulichen Verlassenen weiterhin die Verbliebenen von Lordaeron jagen dürfen. Es ist KEINE passende Ehrung für dieses einst so stolze Königreich, lasst Euch das gesagt sein...\n\nHier sind ein paar Münzen für eventuell benötigte Reparaturen. Ich habe dem Anlass entsprechend auch ein paar Süßigkeiten, die Ihr mögen könntet, mit hinzugepackt. Gruselige Schlotternächte - lasst es uns dafür sorgen, dass es in Southshore so sicher wie möglich bleibt.", rewards = "Ihr bekommt:\n\nKürbisdrops der Schlotternächte"},
[1661] = {title = "Der Foliant des Adels", objective = "Sprecht mit Duthorian Rall in Stormwind.", description = "Ich grüße Euch erneut, <Name>. Ich bin stolzer als jemals zuvor, Euch <Bruder/Schwester> nennen zu können - Euer Engagement ist ein Tribut an uns alle.\n\nDie Zeit ist für mich gekommen, Euch ein wunderbares Geschenk zu übergeben. Wisset aber, dass ich es Euch fürs Erste zwar frei gebe, später jedoch, falls die Zeit es erlaubt, wird dies eine viel größere Herausforderung für alle Paladine sein, die sich dazu entscheiden, meinen Auftrag anzunehmen.\n\nSprecht erneut mit mir und ich werde Euch einen großen Segen gewähren.", progress = nil, completion = "Herzlichen Glückwunsch und möge das Licht Euch schützen.", rewards = "Ihr erlernt:\n\nSchlachtross beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSchlachtross beschwören"},
[1665] = {title = "Bartlebys Becher", objective = "Bringt Bartlebys Becher zu Burlguard.", description = "Okay, hier ist mein Becher. Wartet! Lasst mich zuerst austrinken... da haben wir es.", progress = "Ich habe Euch mit Bartleby kämpfen gesehen. Ordentlich gemacht! Habt Ihr seinen Becher?", completion = "Da ist er! Er wollte ihn nicht hergeben, aber Ihr wart sehr überzeugend. Gut gemacht.\n\nNun zu Eurer Lektion...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWeg der Verteidigung\n\nIhr bekommt:\n\n"},
[1666] = {title = "Marshal Haggard", objective = "Sprecht mit Marshal Haggard.", description = "Ihr habt einige Kampftechniken gelernt, braucht aber noch eine anständige Waffe. Ich wette, Marshal Haggard könnte Euch helfen, wenn Ihr mit ihm sprecht.\n\nMarshal Haggard lebt in einem Anwesen im Wald von Elwynn, beim Holzfällerlager des Osttals. Er ist jetzt im Ruhestand, hat aber in seiner Laufbahn eine Menge Ausrüstung gesammelt.\n\nLasst ihn wissen, dass ich Euch geschickt habe, und mit etwas Glück hat er eine Waffe für Euch übrig.", progress = nil, completion = "Wer ist das? Burlguard, seid Ihr das? Ihr müsst etwas näher kommen. Meine Augen sind nicht mehr das, was sie einst waren. Euch so anzuschleichen, ich dachte schon, Ihr wärt ein Gnoll!", rewards = "Ihr bekommt:\n\n"},
[1667] = {title = "Stumpfzahn Jack", objective = "Holt Marshal Haggards Abzeichen aus Stumpfzahn Jacks Lager und kehrt zu Marshal Haggard zurück.", description = "Burlguard hat Euch geschickt, nicht? Ja, ich habe Waffen übrig, aber zuerst habe ich eine Aufgabe für Euch...\n\nVor einer Weile überlistete mich ein Bösewicht der Defias, Stumpfzahn Jack. Es war dunkel und er trug ein Stormwindwams, daher dachte ich, er sei Marshal Dughan. Er sagte, er braucht meinen alten Marshalstern aus Stormwind und ich gab ihm diesen... dann lachte er und lief weg, ehe ich ihn packen konnte!\n\nBringt mir meinen Stern! Stumpfzahn Jack hat ihn wahrscheinlich in seinem Lager im Süden versteckt.", progress = "Habt Ihr meinen Stern? Ich will mir gar nicht vorstellen, welche Unbill Stumpfzahn Jack damit hätte anstellen können.", completion = "Prima, Ihr habt ihn! Ich fürchtete, er sei für immer dahin und würde von den Defias benutzt werden, um sich als Beamte von Stormwind ausgeben zu können. Dank Euch wird es dazu jetzt nicht kommen.\n\nHier einige Waffen, die ich benutzt habe, als ich noch Marshal war. Ich habe sie gut in Schuss gehalten - trefft Eure Wahl!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHaggards AxtHaggards HammerHaggards DolchHaggards Schwert\n\nIhr bekommt außerdem:\n\n"},
[1678] = {title = "Vejrek", objective = "Bringt Vejreks Kopf zu Muren Stormpike in Ironforge.", description = "Wenn Ihr es in den Reihen der Krieger zu etwas bringen wollt, müsst Ihr zäh sein. Ich kann Euch neue Kampftechniken beibringen, aber zuvor müsst Ihr mir beweisen, dass Ihr gegen richtige Feinde bestehen könnt.\n\nVejrek ist der härteste Troll, den Ihr in dieser Gegend findet. Ihn müsst Ihr besiegen. Er hat eine Hütte im Vorgebirge südlich der Frostmanehöhle.\n\nBringt mir Vejreks Kopf, dann weiß ich, dass Ihr Mumm habt.", progress = "Seid Ihr in Vejreks Hütte gewesen, <Name>? Rieche ich Trollgestank an Euch?", completion = "Vejrek war ein hässlicher Kerl, was? Ordentlich gemacht, &lt;Name&gt;! Ihr habt eindeutig das Zeug dazu, also fangen wir mit der Lektion an...\n\nIhr wisst es vielleicht nicht, aber eine starke Verteidigung ist sehr wichtig für einen &lt;Klasse&gt;. Damit besteht er noch gegen Feinde, wenn andere schon niedergeschmettert wären, und genau so einen brauchen Eure Verbündeten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWeg der Verteidigung\n\nIhr bekommt:\n\n"},
[1679] = {title = "Muren Stormpike", objective = "Sprecht mit Muren Stormpike.", description = "Hallo, Krieger! Ihr seid viel versprechend, aber dennoch müsst Ihr ein paar Tricks lernen, und Muren Stormpike ist genau der Zwerg, der sie Euch beibringen kann.\n\nIhr findet Muren in der Halle der Waffen im Militärviertel von Ironforge. Sprecht mit ihm, wenn Ihr bereit seid zu lernen, was es heißt, ein Krieger zu sein.", progress = nil, completion = "Ah, &lt;Name&gt;. Ich hörte, wie die &lt;Klasse&gt; von Dun Morogh Euren Namen erwähnten. Ich hoffe, Ihr habt nicht Eure ganze Zeit in den Brauereien verbracht!", rewards = "Ihr bekommt:\n\n"},
[1680] = {title = "Tormus Deepforge", objective = "Sprecht mit Tormus Deepforge.", description = "Jetzt, da Ihr einige Kampftechniken gelernt habt, wird es Zeit, Euch eine anständige Waffe zu beschaffen. Sprecht mit Tormus Deepforge. Er kann Euch eine Waffe machen, die Euch sicher gefallen wird.\n\nIhr findet Tormus hier in Ironforge bei der großen Schmiede.", progress = nil, completion = "Muren hat Euch geschickt, nicht? Ja, ich kann Euch eine hübsche Waffe machen... aber vorher muss ich Euch um einen Gefallen bitten.\n\nSeid unbesorgt. Es ist ziemlich gefährlich und könnte Euren Tod bedeuten; also genau das, was ein &lt;Klasse&gt; sich wünscht.", rewards = "Ihr bekommt:\n\n"},
[1681] = {title = "Ironbands Truppenlager", objective = "Bringt eine Ladung Umbralerz zu Tormus Deepforge in Ironforge.", description = "Mein Mentor Sturgy Ironband hatte ein Lager südlich des Helmsbedsees im östlichen Dun Morogh. Dort lehrte er die Schmiedekunst und er war der Beste.\n\nAber eines Tages brachte ihm einer seiner Schüler eine Ladung mit seltsamem Erz. Meister Ironband nannte es Umbralerz und konnte es kaum erwarten, damit zu arbeiten. Doch kurz nach der Lieferung griff eine Bande Dunkeleisenzwerge sein Lager an. Sie töteten alle!\n\nBegebt Euch zu Ironbands Lager, <Name>, und rächt den Tod meines Meisters. Und bringt mir die Ladung Umbralerz, die all das auslöste.", progress = "Habt Ihr Ironbands Areal betreten? Und habt Ihr das Umbralerz gefunden?", completion = "Ihr habt es gefunden! Gut gemacht!\n\nIch hoffe, Ihr habt im Lauf der Suche eine Menge Dunkeleisenzwerge getötet. Ich fürchte, wir werden sie auf Ironbands Areal nicht zum letzten Mal gesehen haben.\n\nAber danke für das Erz, &lt;Name&gt;. Ich brenne darauf, seine Eigenschaften herauszufinden.", rewards = "Ihr bekommt:\n\n"},
[1682] = {title = "Waffen aus grauem Eisen", objective = "Hier ein paar Waffen, frisch vom Amboss und aus dem neuen Umbralerz gefertigt, das Ihr mir gebracht habt!\n\nBitte, <Name>, sucht Euch eine aus!", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nUmbralaxtUmbralstreitkolbenUmbraldolchUmbralschwert\n\nIhr bekommt außerdem:\n\n"},
[1683] = {title = "Vorlus Elendshuf", objective = "Bringt das Horn von Vorlus zu Elanaria in Darnassus.", description = "Bevor ich Euch unterrichten kann, müsst Ihr mir Eure Entschlossenheit beweisen.\n\nDer Satyr Vorlus Elendshuf hat einen unserer entlegenen Mondbrunnen südöstlich der Grabhügel von Ban'ethil gefunden. Nun planscht er darin und verseucht das reine Wasser mit seinem Schmutz.\n\nSucht Vorlus beim Mondbrunnen und vernichtet ihn. Bringt mir sein Horn als Beweis, dann beginne ich Eure Fortgeschrittenen-Ausbildung zum Krieger.\n\nDer Weg zum Mondbrunnen ist gut verborgen, <Name>, doch wenn Ihr konzentriert und wachsam bleibt, werdet Ihr ihn finden.", progress = "Habt Ihr das Horn, <Name>. Ist unser Mondbrunnen von dem Scheusal Vorlus befreit?", completion = "Gut gemacht, &lt;Name&gt;. Gut zu wissen, dass Vorlus besiegt und unser Mondbrunnen gesäubert ist, und schön zu sehen, dass junge &lt;Klasse&gt; erpicht sind, unser geliebtes Teldrassil frei von Verderbnis zu halten.\n\nBeginnen wir jetzt Eure Ausbildung...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWeg der Verteidigung\n\nIhr bekommt:\n\n"},
[1684] = {title = "Elanaria", objective = "Sprecht mit Elanaria.", description = "Seid gegrüßt, Krieger. Eure Fertigkeiten wachsen, doch Eurer Beruf verlangt mehr, als Ihr für möglich haltet. Um weiter zu kommen müsst Ihr bald einen Lehrer finden.\n\nDie Kriegerin Elanaria weilt in Darnassus auf der Terrasse der Krieger. Sie kann Euch unterweisen.", progress = nil, completion = "Ich entbiete Euch einen Gruß, &lt;Name&gt;. Man hört Euren Namen oft in Darnassus, denn Ihr seid viel versprechend. Doch wir werden sehen, ob Ihr die Willenskraft besitzt, dem Pfad des Kriegers zu folgen.", rewards = "Ihr bekommt:\n\n"},
[1685] = {title = "Gakins Beschwörung", objective = "Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Stormwind.", description = "Läuft es nicht immer so? Ich habe den ganzen Tag nach Euch gesucht und konnte Euch nicht finden, und jetzt, da ich es nicht erwarte, kommt Ihr einfach zu mir spaziert.\n\nIch habe genug Zeit mit der Suche nach Euch vergeudet, daher möchte ich gleich zur Sache kommen. Meister Gakin hat Euch zu weiterer Ausbildung gerufen. Mir scheint, Ihr solltet ihn so rasch wie möglich aufsuchen.\n\nIhr findet ihn im Keller der Taverne Zum geschlachteten Lamm. Übrigens solltet Ihr diesen Treffpunkt nicht an die große Glocke hängen. Muss ja nicht jeder wissen.", progress = nil, completion = "Höchste Zeit, dass Ihr erscheint. Ich hätte vielleicht einen Tüchtigeren als Remen auf die Suche nach Euch schicken sollen.\n\nEinerlei.\n\nIhr wart zu lange ohne Ausbildung, und ein &lt;Klasse&gt; ohne Ausbildung behält den Kopf nicht lange auf den Schultern.", rewards = "Ihr bekommt:\n\n"},
[1686] = {title = "Eluras Schemen", objective = "Bringt 8 Ladungen Eluniterz und das Medaillon von Elura zu Elanaria in Darnassus.", description = "Ihr habt viel gelernt, <Name>. Jetzt fertigen wir Euch eine Waffe an. Die Waffe eines Kriegers.\n\nDazu müsst Ihr nach Dunkelküste reisen.\n\nVor langer Zeit zerschellte ein Schiff auf den Felsen beim Leuchtturm von Auberdine. Viele Kisten Eluniterz sanken auf den Meeresgrund.\n\nAls Erstes müsst Ihr den Wächter des Elunits besiegen, Eluras Schemen. Sie war einst Kapitän des Schiffes und verfluchte sich selbst dazu, für alle Zeiten in der Tiefe zu verweilen und ihre Schiffsladung zu schützen. Besiegt sie, nehmt Ihr das Medaillon ab und sammelt die verlorenen Elunitkisten ein.", progress = "Habt Ihr Eluras Schemen besiegt, <Name>? Und habt Ihr das verlorene Eluniterz?", completion = "Tapfer, tapfer, &lt;Name&gt;.\n\nIhr habt Eluras Schemen den wohlverdienten Frieden gegeben. Aus dem gewonnenen Elunit werden wir eine prima Waffe für Euch machen.", rewards = "Ihr bekommt:\n\n"},
[1687] = {title = "Der gruselige Leuchtturm", objective = "Besucht mit Eurem Schützling den Leuchtturm an der Küste von Westfall.", description = "Abends erzählen uns die Matronen manchmal Gruselgeschichten. Die sind spitze! Einmal haben sie uns von einem Geist erzählt, der in einem Leuchtturm in Westfall spukt. Er soll einmal ein Piratenkapitän gewesen sein, dessen Schiff ihm von anderen Piraten weggenommen wurde. Wow!\n\nKönnen wir uns bitte den Leuchtturm in Westfall anschauen? Ich will nachgucken ob der Geist des Kapitäns noch immer dort ist! Ich bleibe auch immer nah bei dir. Ich renn' auch bestimmt nicht weg oder sowas.", progress = "Sind wir bald da?", completion = "Wow! Das war ja ein richtiger Geist! Das war ja der Hammer - Ich kann es kaum erwarten, das meinen Freunden im Waisenhaus zu erzählen. Captain Grayson... er sah sogar wie ein Pirat aus! Wenn ich mal groß bin, möchte ich auch ein Geisterpirat sein!\n\nDanke, dass du Westfall mit mir besucht hast, &lt;Name&gt;. Ich weiß, da waren viele gefährliche Wesen in der Wildnis von Westfall und ich hoffe das ich dir nicht zuviel Sorgen bereitet habe. Du bist der Beste!", rewards = "Ihr bekommt:\n\n"},
[1688] = {title = "Surena Caledon", objective = "Beschafft Surenas Halsschmuck für Gakin den Dunkelbinder in Stormwind.", description = "Ich hatte eine Studentin namens Surena Caledon. Sie stand da, wo Ihr jetzt steht, und brannte darauf, die Hexenmeistermagie zu lernen, und ihr Talent war nicht von schlechten Eltern. Mehr als das, sie war jung und eine wahre Augenweide. Hätte ich sie doch nur damals schon durchschaut, die falsche Schlange!\n\nDas diebische Weib brannte mit einem der Defias durch, Erlan Drudgemoor. Ihr Verlust ist unbedeutend, aber ich schenkte ihr einen Blutsteinhalsschmuck, den ich wiederhaben muss.\n\nIhr Leben hat keine Bedeutung mehr für mich. Ihr findet sie bei Brackwells Kürbisbeet. Bringt wieder, was mir gehört.", progress = "Selbst die Alten und Weisen können sich von Jugend und Schönheit blenden lassen, <Name>. Ihr tätet gut daran, diesen Rat Euer ganzes Leben lang nicht zu vergessen.", completion = "Surena war begabt, aber nicht so sehr, dass sie die Hexenmeistermagie selbst gemeistert hätte. Ein Jammer, dass ein Talent verschwendet wird, aber manchmal geht es nicht anders.\n\nIch hoffe, meine Investition in Euch wird andere Resultate zeigen.", rewards = "Ihr bekommt:\n\n"},
[1689] = {title = "Die Bindung", objective = "Beschwört mit Hilfe des Blutsteinhalsschmucks einen Leerwandler, unterwerft ihn und bringt dann den Blutsteinhalsschmuck zu Gakin dem Dunkelbinder in Stormwind zurück.", description = "Ihr habt meinen Halsschmuck zurückgebracht und Surena bezwungen, und damit gezeigt, dass Ihr mindestens ebenso begabt seid wie sie es war.\n\nNichtsdestoweniger kann ich Euch versichern, dass Ihr dringend Ausbildung benötigt. Ihr meistert den Fluss der Magie, ja, aber zu einem Hexenmeister gehört viel mehr als das.\n\nIch zeige Euch, wie man einen Leerwandler beherrscht, aber bevor ich das kann, müsst Ihr einen am Beschwörungskreis herbeirufen und mit allen Euch zur Verfügung stehenden Waffen unterwerfen. Benutzt die Magie dieses Halsschmuckes unten am Beschwörungskreis.", progress = "Ich kann Euch erst zeigen, wie man einen Leerwandler kontrolliert, wenn Ihr einen beschworen habt.", completion = "Ihr habt Eure Sache besser als erwartet gemacht, &lt;Name&gt;, aber so gut, wie ich gehofft hatte. Jetzt könnt Ihr lernen, wie Ihr Euren unterworfenen Leerwandler beherrscht, einen Verbündeten, der Euch in den bevorstehenden Prüfungen sicher höchst nützlich ist.\n\nIm Augenblick kann ich Euch nichts mehr beibringen, bin aber noch lange nicht fertig mit Euch, &lt;Name&gt;.", rewards = "Ihr erlernt:\n\nLeerwandler beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\nLeerwandler beschwören' lehren\n\nIhr bekommt außerdem:\n\n"},
[1690] = {title = "Wüstenläufergerechtigkeit", objective = "Erledigt 10 Banditen und Diebe der Wüstenläufer östlich von Gadgetzan und meldet Euch dann wieder bei Chefingenieur Bilgewhizzle.", description = "Ihr da! Für Euch ist es an der Zeit, ein großer Helfer der Gadgetzan Water Company zu sein.\n\nDie Wüstenläufernomaden draußen in der Tanariswüste haben fast alle Wasserbrunnen erobert! Ohne Zugang zu den Brunnen wird unser Wasservorrat im Handumdrehen schwinden. Wenn Ihr Euch unsere Dankbarkeit verdienen wollt, dann helft uns, diese Nomaden der Gerechtigkeit zuzuführen!\n\nBegebt Euch von hier Richtung Osten und schaltet zehn Banditen und Diebe der Wüstenläufer aus und meldet Euch dann umgehend wieder bei mir. Gerechtigkeit wartet auf keinen Mann ... keinen Goblin ... ach, legt einfach los!", progress = nil, completion = "Tja, das nenne ich Effizienz! Ihr habt uns geholfen, die Nomaden so weit zu dezimieren, dass wir uns jetzt überlegen können, wie wir die Wasserbrunnen zurückerobern.\n\nDie Gadgetzan Water Company dankt Euch für Eure Hilfe, aber wir sind mit diesen stinkenden Nomaden noch lange nicht fertig. Hört gut zu - das benötigen wir als Nächstes ...", rewards = "Ihr bekommt:\n\n"},
[1691] = {title = "Noch mehr Wüstenläufergerechtigkeit", objective = "Erledigt 10 Schattenmagier der Wüstenläufer, 8 Schurken der Wüstenläufer und 6 Auftragsmörder der Wüstenläufer für Chefingenieur Bilgewhizzle in Gadgetzan.", description = "Wir müssen uns jetzt die stärkeren Ränge der Wüstenläufernomaden vornehmen. Ihr habt bisher gute Arbeit geleistet, aber wenn wir diese Wasserbrunnen zurückerobern wollen, dann wäre es gut, wenn uns dabei so wenig Nomaden wie möglich gegenüberstünden!\n\nDieses Mal müsst Ihr ihre Schurken, Auftragsmörder und Schattenmagier erledigen. Ihr werdet sie östlich und südöstlich von hier finden.\n\nIch werde Euch nichts vormachen - das ist eine schlimme Bande. Tut dies für uns, dann sind wir auf dem besten Weg, uns das zurückzuholen, was rechtmäßig uns gehört!", progress = "Na, konntet Ihr diese Nomaden ausschalten, wie ich Euch gebeten hatte? Die Gadgetzan Water Company entwickelt Pläne, die auf Eurem Erfolg hier basieren! Lasst uns jetzt nicht im Stich...", completion = "Erstklassige Arbeit, &lt;Name&gt;... erstklassig! Ihr habt die Nomadenbevölkerung so weit dezimiert, dass wir tatsächlich den Kampf gegen sie aufnehmen können!\n\nFalls Ihr es noch nicht getan habt, dann sprecht mit Leitungshahnmaschinist Luglunket hier; er vergibt ein Kopfgeld für jeden Wasserbeutel eines Wüstenläufers, über den Ihr gestolpert seid, während Ihr diese Nomaden der Gerechtigkeit zugeführt habt!", rewards = "Ihr bekommt:\n\n"},
[1692] = {title = "Schmied Mathiel", objective = "Bringt das Behältnis mit Elunit zu Schmied Mathiel.", description = "Ich habe das Elunit, das Ihr gesammelt habt, in eine Kiste gelegt. Bringt sie zum Schmied Mathiel, er wird eine Elunitwaffe für Euch anfertigen.\n\nMathiel ist im Süden, an der anderen Seite dieses Gebäudes zu finden.", progress = "Seid gegrüßt, junger <Klasse>. Wie kann ich Euch mit meinen Fertigkeiten dienlich sein?", completion = "Ah, Eluniterz. Ein Metall, mit dem sich gut arbeiten lässt, denn es wurde von der Göttin Elune persönlich gesegnet. Es wäre mir eine Ehre, Waffen daraus herzustellen.\n\nBitte wartet, während ich arbeite...", rewards = "Ihr bekommt:\n\n"},
[1693] = {title = "Waffen aus Elunit", objective = "<Name>, ich habe mit dem Elunit, das Ihr mir brachtet, diese Waffen hergestellt. Bitte nehmt die, die Euch am angenehmsten ist.\n\nUnd ich muss Euch danken. Es ist eine Ehre und Freude, mit Elunit zu arbeiten.", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nElunitaxtElunithammerElunitdolchElunitschwert\n\nIhr bekommt außerdem:\n\n"},
[1698] = {title = "Yorus Gerstenbräu", objective = "Sprecht mit Yorus Gerstenbräu.", description = "Yorus Gerstenbräu hat eine Herausforderung für alle tüchtigen Krieger der Allianz verkündet. Er wartet im Gasthaus von Seenhain im Rotkammgebirge und verspricht jedem, der seine Prüfung besteht, eine hohe Belohnung.", progress = nil, completion = "Ha! Ihr habt von meiner Herausforderung gehört, richtig?\n\nSetzt Euch und hört zu. Bestellt ein Getränk und genießt es... es könnte Euer Letztes sein.", rewards = "Ihr bekommt:\n\n"},
[1699] = {title = "Der Rethban-Spießrutenlauf", objective = "Betretet die Rethbanhöhlen, geht bis zur ersten Gabelung und kehrt innerhalb der zulässigen Zeit zu Yorus Gerstenbräu zurück.\n\nIhr dürft nicht sterben und Euren Geist befreien.", description = "Ich nenne meine Herausforderung den Rethbanspießrutenlauf. Um die Prüfung zu bestehen, müsst Ihr lediglich die Rethbanhöhlen betreten, bis zur ersten Gabelung gelangen und hierher zurückkehren. Ganz einfach! Aber es gibt da ein paar Hürden...\n\nIhr müsst binnen einer Stunde zurück sein.\n\nGanze Heerscharen von Rotkammgnollen versperren den Weg.\n\nVor dem Start müsst Ihr einen Schluck des Stammgetränks meiner Familie zu Euch nehmen: Gerstenbräu!\n\nWas sagt Ihr dazu? Die Rethbanhöhlen liegen im Vorgebirge nördlich von Seenhain. Seid Ihr bereit, am Rethbanspießrutenlauf teilzunehmen?", progress = nil, completion = "Ihr habt es geschafft! Gut gemacht! Ein dreifach Hoch für &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[1700] = {title = "Grimand Elmore", objective = "Bringt Furens Notizen zu Grimand Elmore.", description = "Ich fertigte eine Kopie meiner Notizen über die Techniken an, die ich lernte, während ich Eure Rüstung herstellte. Sie muss zu Grimand Elmore geschickt werden. Er ist hier im Zwergendistrikt, im Waffenladen.\n\nUnd duckt Euch, wenn Ihr ihm die gebt. Er bildet sich ungeheuer viel auf seine Fertigkeiten ein. Es wird ihm nicht gefallen, etwas von mir zu lernen ...", progress = "Hallo und schönen Tag. Wie kann ich Euch dienlich sein?", completion = "Furen hat das geschrieben? Wie kann er es wagen! Ich habe ihm all das beigebracht, was er weiß! Unerhört, dass er glaubt, er könnte mich etwas lehren! Unerhört!\n\nHm... aber in diesen Notizen steht etwas, das ich gern versuchen würde...", rewards = "Ihr bekommt:\n\n"},
[1701] = {title = "Feuergehärteter Panzer", objective = "Sammelt die Materialien, die Furen Longbeard benötigt, und bringt sie zu ihm nach Stormwind.", description = "Ich gab Euch einen guten Schild, aber dabei muss es nicht bleiben. Ich kenne das Geheimnis, wie man extrem harte Panzerrüstung herstellt. Es ist nicht leicht und erfordert sehr rare Materialien, aber wenn Ihr bereit seid, die Kleinarbeit zu machen, fertige ich ein Teil für Euch an.\n\nWas sagt Ihr dazu, <Name>? Wenn Ihr Euch der Herausforderung gewachsen fühlt, gebe ich Euch eine Liste, was Ihr beschaffen müsst und wo Ihr es bekommt.", progress = "Wie läuft die Suche, <Name>? Habt Ihr die Materialien?", completion = "Ihr habt alles? Erstaunlich! Ich hatte befürchtet, diese Schimären würden Euch fressen!\n\nDann lasst uns mal mit der Rüstung anfangen...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1702] = {title = "Der Schildschmied", objective = "Bringt das Fässlein mit Gerstenbräu zu Furen Longbeard.", description = "Ihr habt echt gezeigt, aus welchem Holz Ihr geschnitzt seid, als Ihr am Rethbanspießrutenlauf teilgenommen habt, <Name>. Und ich stehe zu meinem Wort. Ihr bekommt die versprochene Belohnung...\n\nAber sie ist in Stormwind.\n\nSprecht mit meinem Freund Furen Longbeard im Zwergendistrikt von Stormwind. Er ist der beste Schildschmied, den Ihr je gesehen habt, und er schuldet mir einen großen Gefallen.\n\nHier, bringt Furen dieses Fässlein mit Gerstenbräu und bittet ihn um einen Schild. Er wird Euch einen schönen geben.", progress = "Hallo! Trockene Zeiten, findet Ihr nicht auch?", completion = "Ah, Gerstenbräu. Erstklassiges Gesöff! Ihr seid also bei Yorus gewesen, hm?\n\nIch kann Euch einen Schild machen, ja Sir! Einen Besseren werdet Ihr nicht finden, ungelogen!", rewards = "Ihr bekommt:\n\nFurens Gunst"},
[1703] = {title = "Mathiel", objective = "Bringt Furens Notizen zu Mathiel.", description = "Ich fertigte eine Kopie meiner Notizen über die Techniken an, die ich lernte, während ich Eure Rüstung herstellte. Sie muss zum Schmied Mathiel geschickt werden. Er lebt in Darnassus. Das ist weit weg, aber ich bin sicher, er wird dankbar sein, wenn er erfährt, was ich gelernt habe.", progress = "Ich entbiete Euch einen Gruß, <Klasse>.", completion = "Das ist interessant, wirklich sehr interessant. Mein Zwergen-Kollege Furen hat da eine grandiose Entdeckung gemacht!\n\nDanke, &lt;Name&gt;. Es wäre mir eine Ehre, seine neuen Techniken selbst anzuwenden.", rewards = "Ihr bekommt:\n\n"},
[1704] = {title = "Klockmort Spannerspan", objective = "Bringt Furens Notizen zu Klockmort Spannerspan.", description = "Ich fertigte eine Kopie meiner Notizen über die Techniken an, die ich lernte, während ich Eure Rüstung herstellte, und brauche jemanden, der sie zu Klockmort Spannerspan bringt. Er ist ein Gnomen-Schmied in Ironforge, und wenn er herausfindet, was ich herausgefunden habe ... Ich wette, er reißt sich vor Aufregung selbst den Bart aus.", progress = "Guten Tag, Morgen oder Abend. Ich kann es von hier unten nicht erkennen. Bringt Ihr mir Arbeit?", completion = "Oh je! Diese Notizen sind erstaunlich! Und mehr noch... sie sind unglaublich und phantastisch und machen meine Knie ganz weich!\n\nFuren hatte einen Durchbruch! Einen echten Durchbruch! Ich kann es kaum erwarten, seine neue Technik zu erproben!", rewards = "Ihr bekommt:\n\n"},
[1705] = {title = "Brennendes Blut", objective = "Bringt 20 Phiolen brennendes Blut und 1 brennenden Fels zu Grimand Elmore in Stormwind.", description = "Ich gebe nur ungern zu, dass Furen tatsächlich etwas gefunden haben könnte. Aber um ganz sicher zu sein, muss ich seine Techniken an einem neuen Rüstungsteil erproben. Wenn Ihr mir mit den Materialien helft, <Name>, könnt Ihr die Rüstung haben.\n\nUm die Rüstung herzustellen benötige ich Proben von brennendem Blut und brennendem Felsen.\n\nDie findet man meines Wissens nur im Dämmerwald. Die Worgs der Nachtheuler in der Mine von Rolands Verdammnis haben brennendes Blut, und Gutspill, ihr Anführer, wird den Fels haben.\n\nMöge das Schicksal Euch Schnelligkeit gewähren <Name>.", progress = "<Name>, habt Ihr das brennende Blut und den Fels? Ich brauche sie, um die Rüstung zu vollenden.", completion = "Saubere Arbeit! Wenn Ihr mich jetzt entschuldigen wollt, ich habe zu tun...", rewards = "Ihr bekommt:\n\n"},
[1706] = {title = "Grimands Rüstung", objective = "Ich kann es kaum glauben! Furens Technik war ein Erfolg. Seine Rüstung sollte ungeheuren Belastungen standhalten können.\n\nDa habt Ihr sie, <Name>. Und habt Dank. Ich hätte nicht an Furens Entdeckung geglaubt, wenn Ihr nicht die Materialien gesammelt hättet, die ich für einen Test brauchte.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFeuergehärtete Helmkappe"},
[1707] = {title = "Wasserbeutelkopfgeld", objective = "Bringt Leitungshahnmaschinist Luglunket in Gadgetzan 5 Wasserbeutel eines Wüstenläufers.", description = "Seid gegrüßt, <Name>, mein Name ist Luglunket, und wir haben einen wichtigen Auftrag für Euch, wenn Ihr bereit seid! Hussah!\n\nNichts würde mir als altgedientem Leitungshahnmaschinisten mehr gefallen, als Euch jeden Wasserbeutel eines Wüstenläufers abzunehmen, den Ihr draußen in der Wüste findet. Das ist ja ohnehin unser Wasser - die Nomaden haben es einfach nur gestohlen! Die Gadgetzan Water Company bietet Euch ein offizielles Care-Paket für jeweils fünf, die Ihr abliefert. Am wichtigsten ist aber, dass Ihr Gadgetzan selbst helft!", progress = "Habt Ihr die fünf Wasserbeutel eines Wüstenläufers, die wir benötigen? Falls Ihr sie habt, dann gehört das Gadgetzan Water Company-Care-Paket, Modell 103-XB, Euch!", completion = "Hervorragend - je mehr Wasserbeutel wir wiederbeschaffen können, desto weiter sind wir von einer Katastrophe entfernt! Bringt mir mehr und ich werde Euch für jeweils fünf Wasserbeutel belohnen, die Ihr mir bringt.", rewards = "Ihr bekommt:\n\nGadgetzan Water Co.-Care-Paket"},
[1708] = {title = "Eisenkoralle", objective = "Bringt 20 Ladungen Sengkoralle zu Klockmort Spannerspan in Ironforge.", description = "Ich möchte Furen Longbeards neue Techniken an einer eigenen Rüstung erproben. Und weil Ihr Furen geholfen habt und er mir, sollt Ihr die Rüstung bekommen, wenn sie fertig ist!\n\nUm das Teil zu beenden, brauche ich eine spezielle Koralle, Sengkoralle. Sie wächst nur an einem Ort - an der Küste südlich des Hafens von Menethil im Sumpfland.\n\nBringt mir genügend Sengkoralle und ich mache mich gleich an die Arbeit. Und beeilt Euch, <Name>. Ich brenne so sehr darauf, endlich anzufangen, dass meine Zehen jucken!", progress = "Hallo, hallo, <Name>. Habt Ihr die Sengkoralle? Ich will endlich arbeiten!", completion = "Das sind sie. Gut gemacht! Und jetzt lasst mich dies verhütten und zerhämmern, damit ich Furens Technik selbst anwenden kann. Mal sehen, was dann passiert!\n\nOh je, oh je! Ich weiß genau, diese Rüstung wird sehr, sehr hart!", rewards = "Ihr bekommt:\n\n"},
[1709] = {title = "Klockmorts Kreation", objective = "Hier ist Eure Rüstung, <Name>. Furens Prozess hat ausgezeichnet funktioniert! Perfekt! Wunderbar, ehrlich!\n\nMan könnte mit einer Belagerungsmaschine über diese Rüstung fahren und sie würde wieder ihre alte Form annehmen!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFeuergehärtete Stulpen"},
[1710] = {title = "Sonnenverbrannte Schalen", objective = "Bringt 20 sonnenverbrannte Schalen zu Mathiel in Darnassus.", description = "Mein Kollege, Furen Longbeard, hat eine Entdeckung gemacht, die ich schnellstens ausprobieren möchte. Ich möchte sie an einer neuen Rüstung erproben, an der ich forsche, denn ich glaube, Furens Techniken werden grandiose Ergebnisse erzielen.\n\nWerdet Ihr mir helfen? Wenn Ihr sammelt, was ich zur Herstellung der Rüstung brauche, fertige ich für Euch auch eine an.\n\nIch brauche sonnenverbrannte Eierschalen der Steilhangflügeldrachen, die am Steilhang in Tausend Nadeln hausen. Sucht unter den Nestern nach den Schalen und kommt zu mir zurück, wenn Ihr eine ausreichende Menge habt.", progress = "Habt Ihr die Schalen, <Name>? Sie sind recht stark und können zu einem Lack verarbeitet werden, mit dem ich die Kettenglieder meiner neuen Panzerrüstung überziehe.", completion = "Ah, danke. Dies wird großartig funktionieren!\n\nIch werde sofort mit der Rüstung beginnen...", rewards = "Ihr bekommt:\n\n"},
[1711] = {title = "Mathiels Rüstung", objective = "Ich habe Eure Rüstung vollendet und bin recht zufrieden. Furens neue Techniken passen ausgezeichnet zu meinen. Ich bin sicher, diese Rüstung wird sehr widerstandsfähig sein.\n\nDanke, <Name>. Möge sie Euch in künftigen Kämpfen nützlich sein.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFeuergehärtete Gamaschen"},
[1712] = {title = "Cyclonian", objective = "Bringt die Gegenstände auf Bath'rahs Pergament zu Bath'rah dem Windbehüter in Alterac.", description = "Ich beobachte diesen Ort seit Ewigkeiten. Ich beobachte, damit ich eines Tages den großen Cyclonian fallen sehen kann. Doch ich fand noch keinen Helden, der den Windlord besiegen konnte.\n\nVielleicht seid Ihr dieser Held.\n\nBeweist es mir. Sammelt die Gegenstände, die ich brauche, um Cyclonian zu beschwören, dann weiß ich, dass Ihr ein großer Krieger seid. Vielleicht könnt Ihr ihn besiegen und sein Wirbelherz bekommen.\n\nWenn ja, übertrage ich die Macht des Herzens in eine Waffe und schenke Euch diese Waffe.\n\nHier ein Pergament mit den Gegenständen, die ich benötige.", progress = "Habt Ihr die Gegenstände, <Name>? Wenn Ihr sie sammelt, habe ich den Beweis, dass Ihr genügend Kraft besitzt, um es mit Cyclonian aufzunehmen.", completion = "Ihr habt die Gegenstände für meinen Zauber gesammelt und mir Eure Kraft und Geschicklichkeit bewiesen. Doch das nächste Stadium Eurer Aufgabe ist noch gefährlicher.\n\nHoffen wir, dass Eure Kraft nicht nachlässt.", rewards = "Ihr bekommt:\n\n"},
[1713] = {title = "Die Beschwörung", objective = "Bringt das Wirbelherz zu Bath'rah dem Windbehüter.", description = "Ich bin bereit, das Ritual zur Beschwörung Cyclonians durchzuführen. Wenn er beschworen ist, müsst Ihr ihn besiegen und sein Wirbelherz nehmen. Ich werde es benutzen, um eine Waffe mit Cyclonians Macht zu stärken.\n\n<Name>, seid Ihr bereit, dem Windlord zu trotzen?", progress = "<Name>, ich muss das Wirbelherz haben!", completion = "Ihr habt es geschafft! Ihr habt Cyclonian besiegt und das Wirbelherz bekommen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1714] = {title = "Essenz der Verbannung", objective = "Der Kessel blubbert. Seine Dämpfe locken...", description = nil, progress = "Der Kessel blubbert. Seine Dämpfe locken...", completion = "Die Glücksbringer sinken langsam in die Tiefen des Kessels...\n\nEine große Luftblase steigt zur Oberfläche der Flüssigkeit und zerplatzt...\n\n... Und ein brodelnder Klumpen geschmolzenen Felsens ist zu sehen.", rewards = "Ihr bekommt:\n\nEssenz der Verbannung"},
[1715] = {title = "Zum Geschlachteten Lamm", objective = "Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Stormwind.", description = "Hmph. Früher wurden alle Hexenmeister in Khaz Modan unter der Aufsicht der Meister von Gnomeregan ausgebildet, doch jetzt, wo wir gezwungen wurden, in dieses Rattenloch in Ironforge zu ziehen und Magni beschloss, uns genau zu beobachten, sind wir gezwungen, unsere Novizen zur Ausbildung nach Stormwind zu schicken.\n\nZum Glück ist Gakin kein Tölpel, daher werdet Ihr lernen, was Ihr wissen müsst. Dennoch bringt es mein Blut zum Kochen!\n\nWie auch immer, Ihr findet Gakin im Keller des Geschlachteten Lamms in Stormwind.", progress = nil, completion = "Blackwrench schickt Euch, richtig? Die verdammten &lt;Klasse&gt; in Ironforge sollten mal ihre Köpfe benutzen. Der Platz und die Lehrer in Stormwind sind begrenzt. Durch den ständigen Zustrom werden wir früher oder später Aufmerksamkeit erregen.", rewards = "Ihr bekommt:\n\n"},
[1716] = {title = "Verschlinger der Seelen", objective = "Sprecht mit Takar dem Seher im Brachland.", description = "Ein Sayaad ist ein Verschlinger der Seelen, Bezwinger des Willens, Versucher der Herzen. Er kennt nur das Böse.\n\nSchlüpfrige Geschichten bezeichnen diese Dämonen mit ihren geläufigeren Namen: Sukkubus in der weiblichen und Inkubus in der männlichen Gestalt.\n\nIhr braucht einen Anreiz, um die Kreatur anzulocken. Mit einem Symbol der Liebe als Köder wird sie gewiss auf Euren Ruf reagieren. Besiegt den Dämon und macht ihn zu Eurem Werkzeug.\n\nEs wird allerdings schwer sein, etwas dieser Art zu finden. Ihr solltet mit dem Seher Takar sprechen. Ihr findet ihn im Brachland von Kalimdor nahe dem Camp Taurajo.", progress = nil, completion = "War Eure Reise beschwerlich, &lt;Name&gt;? Ihr kommt von weit her, um mit mir zu sprechen. Doch habt keine Furcht, ich weiß, warum Gakin Euch geschickt hat, und es war weise von ihm, denn ich kann Euch bei der Suche helfen.", rewards = "Ihr bekommt:\n\n"},
[1717] = {title = "Gakins Beschwörung", objective = "Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Stormwind.", description = "<Name>! Ich hätte nicht erwartet, Euch in der Gegend zu sehen, wurde aber angewiesen, nach Euch Ausschau zu halten.\n\nHöchste Zeit, dass Eure Ausbildung fortgesetzt wird. Beim nächsten Besuch in Stormwind solltet Ihr bei Gakin reinschauen. Er wird Euch erwarten.", progress = nil, completion = "Ich bin froh, dass jemand Eurer habhaft wurde, &lt;Name&gt;. Ich fürchtete schon das Schlimmste. Nach der vielen Zeit, die wir in Euch investiert haben, wäre es ein Jammer, Euch zu verlieren.\n\nAber wir können später reden. Wichtig ist jetzt nur Eure Ausbildung.", rewards = "Ihr bekommt:\n\n"},
[1718] = {title = "Der Inselbewohner", objective = "Sprecht mit Klannoc Macleod.", description = "Euer Ruf als Krieger wächst, <Name>. Jetzt ist es Zeit, Euch mit Euresgleichen zu messen und festzustellen, was Ihr könnt.\n\nVor der Küste des Brachlandes, südlich von Ratchet, liegt eine Insel. Sie heißt Prügel-Eiland und ist ein Treffpunkt für Krieger.\n\nGeht dorthin und kämpft.\n\nSprecht mit Klannoc Macleod, dem obersten Krieger der Insel. Wenn er Euch für würdig erachtet, wird Klannoc Euch weiter auf dem Pfad des Kriegers führen.\n\nUm die Prügel-Eiland zu erreichen, müsst Ihr nach den Sandbankuntiefen entlang der Händlerküste suchen.", progress = nil, completion = "Hallo, &lt;Klasse&gt;. Schön, dass Ihr auf das Prügel-Eiland gekommen seid. Hoffentlich gefällt es Euch hier...", rewards = "Ihr bekommt:\n\n"},
[1719] = {title = "Der Ringkampf", objective = "Tötet Big Will und sprecht mit Klannoc Macleod auf dem Prügel-Eiland.", description = "Wenn Ihr von mir lernen wollt, müsst Ihr zuerst den Ringkampf absolvieren. Das ist eine Herausforderung hier auf dem Prügel-Eiland, an der wir aufstrebende Krieger teilnehmen lassen, die sich für gut genug halten. Wenn Ihr gewinnt, dann weiß ich, dass Ihr es tatsächlich seid.\n\nGeht als Erstes mitten in diese Menge dort und stellt Euch auf den Rost. Dadurch weiß Twiggy Flathead, dass Ihr bereit seid, und er schickt Euch Herausforderer.\n\nWenn Ihr alle Herausforderer besiegt habt, ruft er Big Will. Tötet Big Will und kehrt innerhalb der von uns gesetzten Frist zu mir zurück.", progress = "Habt Ihr die Herausforderung absolviert?", completion = "Gut gemacht, &lt;Name&gt;. Ihr habt den Ringkampf bestanden!\n\nIhr seid ein würdiger &lt;Klasse&gt;. Es ist mir eine Ehre, Euch zu unterrichten...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWeg des Berserkers\n\nIhr bekommt:\n\n"},
[1738] = {title = "Herzholz", objective = "Holt das Herzholz aus Ashenvale und bringt es zu Gakin dem Dunkelbinder im Magierviertel von Stormwind.", description = "Als Vorbereitung auf Eure Ankunft nutzte ich mein zweites Gesicht, um über die Welt und hinter die Nebel der Zeit zu schauen. Ich habe herausgefunden, wonach Ihr sucht.\n\nIm Krieg der Urtume fielen zwei Liebende gemeinsam im Kampf. Wo sie ihren letzten Seufzer taten, wuchs ein als Herzholz bekannter Baum als Symbol ihrer unsterblichen Liebe.\n\nEr sollte genügen, um einen Sukkubus anzulocken. Ihr findet ihn in den Ruinen von Ordil'Aran im nordwestlichen Teil des Waldes von Ashenvale.", progress = "War Eure Suche erfolgreich, <Name>?", completion = "Ja, ich sehe, dass das voll und ganz genügt, lasst mich nur einen Moment damit arbeiten...\n\nTakar ist ein recht findiger Bursche, nicht? Wenn ich ihn nur überreden könnte, wieder in die Zivilisation zu kommen.", rewards = "Ihr bekommt:\n\n"},
[1739] = {title = "Die Bindung", objective = "Beschwört mit Hilfe des Herzholzkerns einen Sukkubus, unterwerft ihn und bringt dann den Herzholzkern zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück.", description = "Mit dem Herzholzkern könnt Ihr einen Zauber am Beschwörungskreis unten in der Gruft wirken und ein Portal öffnen, durch das der Sukkubus kommen kann.\n\nSeid vorsichtig, <Name>, Sukkubi haben schon den stärksten Geist unterjocht.\n\nWenn Ihr ihn bezwungen und in die Leere zurückgeschickt habt, kommt wieder zu mir, dann zeige ich Euch, wie Ihr ihn rufen und kontrollieren könnt.", progress = "Manchmal frage ich mich, ob Surena nicht ein verkleideter Sukkubus war, der geschickt wurde, um meinen Geist zu verwirren... Ha! Ich glaube, ich überschätze sie doch ein bisschen...", completion = "Gut gemacht, gut gemacht, &lt;Name&gt;. Wie ich sehe, haben wir gut daran getan, Euch auszubilden. Eure Leistung enttäuschte uns nicht...\n\nIch habe keine Bedenken, Euch zu zeigen, wie Ihr Euren neu gebundenen Sukkubus kontrollieren könnt. Passt gut auf.", rewards = "Ihr erlernt:\n\nSukkubus beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSukkubus beschwören' lehren\n\nIhr bekommt außerdem:\n\nKleiner Seelenbeutel"},
[1740] = {title = "Die Kugel von Soran'ruk", objective = "Sucht 3 Soran'ruk-Fragmente und 1 großes Soran'ruk-Fragment und bringt sie zu Doan Karhan im Brachland.", description = "Wenn Dämonen der Legion in Ungnade fallen, wird ihr Geist in Kugeln gefangen und an ihre Magier und Hexenmeister verteilt.\n\nViele wurden von ihren Bediensteten in Azeroth getragen. Selbst als Bruchstücke besitzen sie die Macht der darin gefangenen Dämonen.\n\nDie Kugel von Soran'ruk wurde in zwei Teile zerbrochen. Eines davon wurde abermals zerbrochen und von den Akolythen der Twilight-Hammer in der Blackfathom-Tiefe benutzt. Das andere, größere Teil besaß ein Hexer in der Burg Shadowfang. Sucht sie, dann kann ich sie zusammenfügen...", progress = "Ich brauchte viele Jahre, um die Teile der Kugel von Zargain zu sammeln, aber sie hat mir gute Dienste geleistet, was die Kugel von Soran'ruk für Euch gewiss auch tun wird.", completion = "Ja... Die Kugel war nicht allzu sehr fragmentiert, fast alle Stücke sind da. Es ist einfach, sie zusammenzufügen und Soran'ruk wieder heil zu machen.\n\nIch habe mein Leben dem Studium der Kugeln der Brennenden Legion und ihrer Neugestaltung gewidmet. Ihr habt mir einen Gefallen damit getan, diese Stücke zum Zweck des Studiums zu sammeln, und ich werde sie Euch zurückgeben - vollständig wiederhergestellt - in einer Gestalt Eurer Wahl.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKugel von Soran'rukStab von Soran'ruk\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[1758] = {title = "Foliant der Kabale", objective = "Sprecht mit Krom Stoutarm in Ironforge.", description = "Mehr als ein einfacher Beschwörungskreis wird erforderlich sein, um einen Teufelsjäger als Herausforderer für Euch herzubringen.\n\nMeine drei Akolythen und ich helfen, die magischen Kreise zu erschaffen. Ihr benötigt eine Kopie des Folianten der Kabale, der seit geraumer Zeit als verschollen gilt. Er wurde von der ersten Gruppe Hexenmeister geschrieben, die ohne Unterstützung einen Teufelsjäger beschwörten.\n\nVielleicht kann Krom Stoutarm Euch dabei helfen. Heute ist er ein fahrender Hexenmeister, hortet alte Schriften und hängt in der Bibliothek von Ironforge herum.", progress = nil, completion = "Foliant der Kabale? Hmm... kommt mir bekannt vor. Aber ich habe ihn noch nie gesehen, und glaubt mir - ich erinnere mich an jedes Buch, das ich gelesen habe.\n\nHmm...\n\nAh, ja! Ich habe Hinweise darauf in Bibliothek-Katalogisierungen gesehen.", rewards = "Ihr bekommt:\n\n"},
[1778] = {title = "Der Foliant der Offenbarung", objective = "Sprecht mit Tiza Battleforge in Ironforge.", description = "Ich werde bald Pläne für meine Heimkehr machen. Hoffentlich geht es Stephanie gut in Stormwind. Ich kann es kaum erwarten, sie wiederzusehen. Auf bald, <Klasse>.", progress = nil, completion = "Ihr seid also so schnell wieder hier, hm? Und was, sagt an, habt Ihr in der Zeit, die Ihr in der Ferne verbrachtet, denn erreicht?\n\nKonntet Ihr bei einem edlen Unterfangen helfen? Vielleicht habt Ihr den Wert der Barmherzigkeit gelernt, oder etwas mehr über Eure Verpflichtung gegenüber den Bürgern von Azeroth erfahren. Sagt mir, wem Ihr geholfen habt, und wie... Beeindruckend, &lt;Name&gt;, das sind gewiss Taten von einem, der dem Licht folgt.\n\nSolche Opfer werden im Laufe der Zeit immer belohnt.", rewards = "Ihr bekommt:\n\n"},
[1779] = {title = "Der Foliant der Offenbarung", objective = "Nehmt das Symbol des Lebens und sprecht mit Muiredon Battleforge in Ironforge.\n\nBereitgestellter Gegenstand: \n", description = "Ich möchte, dass Ihr das nehmt, <Name>. Es heißt Symbol des Lebens.\n\nIhr habt bewiesen, dass Ihr barmherzig und geduldig seid. Jetzt sollt Ihr mir zeigen, wie versiert Ihr geworden seid, was Gefecht und Macht angeht.\n\nMein Mann Muiredon kehrte jüngst von einer Begegnung mit Dunkeleisenzwergen zurück und kam gerade noch mit dem Leben davon - er ist da drüben und einer unserer Priester heilt schon seine Wunden.\n\nNehmt das Symbol und redet mit ihm. Wenn Ihr ihm helfen könnt, dann sprechen wir uns bald wieder. Möge das Licht auf Euch scheinen.", progress = nil, completion = "*husten*\n\nGuten Tag, &lt;Klasse&gt;. Schenkt meinen Wunden keine Beachtung, die guten Priester hier flicken den alten Muiredon schon wieder zusammen. Noch brauche ich die Macht des Symbols des Lebens nicht, das Ihr da habt.\n\nMeine Frau schickt Euch, um mit mir zu sprechen, hm? Schön, schön. Ich werde mit Euch reden und Euch genau schildern, was Muiredon und seinem besten Freund Narm, einem &lt;Klasse&gt; wie Ihr einer seid, zugestoßen ist.", rewards = nil},
[1780] = {title = "Der Foliant der Offenbarung", objective = "Sprecht mit Duthorian Rall in Stormwind.", description = "Ich bringe das noch heute zu den Kindern. Bitte bleibt unversehrt, <Klasse>. Es kommt nicht oft vor, dass <Männer/Frauen> Eures Charakters in der Stadt auftauchen, doch Ihr habt bewiesen, dass die Paladine in Stormwind die Bedürftigen nicht im Stich lassen.\n\nLebt wohl.", progress = nil, completion = "Ihr kehrt so schnell zurück, &lt;Name&gt;. Und was habt Ihr während Eurer Abwesenheit von der Kathedrale erreicht?\n\nHabt Ihr bei einer edlen Sache geholfen? Vielleicht habt Ihr den Wert der Barmherzigkeit gelernt, oder etwas mehr über Eure Verpflichtung gegenüber den Bürgern von Azeroth erfahren. Sagt mir, wem Ihr geholfen habt, und wie ... Ich bin beeindruckt, &lt;Name&gt;, das sind gewiss Taten von einem, der dem Licht folgt und andere höher schätzt als sich selbst.\n\nSolche Opfer werden im Laufe der Zeit immer belohnt.", rewards = "Ihr bekommt:\n\n"},
[1781] = {title = "Der Foliant der Offenbarung", objective = "Bringt das Symbol des Lebens zu Gazin Tenorm in Stormwind.\n\nBereitgestellter Gegenstand: \n", description = "Nehmt das, <Name>. Es heißt Symbol des Lebens.\n\nIhr habt bewiesen, dass Ihr barmherzig und geduldig seid. Jetzt ist die Zeit gekommen, um festzustellen, ob Ihr stark genug seid für die größte Gabe des Lichts.\n\nMein Freund Gazin kehrte jüngst von einer Begegnung mit Defias in Elwynn nahe Heldenwache zurück - er kam gerade so mit dem Leben davon. Er ist in der Nähe des Altars, wo unsere Priester seine Wunden heilen.\n\nNehmt das Symbol und sprecht mit ihm. Wenn Ihr ihm helfen könnt, dann sprechen wir uns bald wieder. Möget Ihr Euch im Schein des Lichts sonnen.", progress = nil, completion = "*husten*\n\nWelch Freude, Euch zu sehen, &lt;Klasse&gt;. Schenkt meinen Wunden keine Beachtung, die guten Priester hier flicken den alten Gazin wieder zusammen. Ich brauche die Macht des Symbols des Lebens nicht, das Ihr da habt... noch nicht.\n\nDuthorian schickt Euch, um mit mir zu sprechen, hm? Schön und gut. Ich werde Euch genau schildern, was mir und meinem Freund Henze zugestoßen ist. Und mit etwas Glück und Geschick Eurerseits könnt Ihr vielleicht doch uns allen helfen.", rewards = nil},
[1782] = {title = "Furens Rüstung", objective = "Hier ist Eure Rüstung, <Name>. Sie wird dem stärksten Angriff standhalten, oder ich will nicht mehr Furen Longbeard heißen!\n\nUnd ich habe Euch zu danken. Ich habe bei der Arbeit mit dem Material, das Ihr mir brachtet, viel gelernt. Ich glaube, eines Tages werde ich einen weiteren Durchbruch schaffen!\n\nIch werde das, was ich gelernt habe, den anderen Schmieden der Allianz schicken.\n\nIch sage ihnen, was für eine große Hilfe Ihr wart. Vielleicht möchten sie den Gefallen erwidern.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFeuergehärtete Halsberge"},
[1783] = {title = "Der Foliant der Offenbarung", objective = "Nehmt das Symbol des Lebens und erweckt Narm Faulk in Dun Morogh wieder zum Leben.", description = "Er spionierte einigen Dunkeleisenzwergen nach, die sich südlich des Helmsbedsees eingebunkert hatten. Wir wussten, dass sie nichts Gutes im Schilde führten, daher dachten Narm und ich, wir sollten der Sache nachgehen - wir sahen, wie ihr Anführer seinen Männern Befehle gab.\n\nNarm und ich wollten einige töten, aber sie waren stärker als wir dachten und es wurden immer mehr. Narm sagte mir, ich solle Verstärkung holen, und hier bin ich.\n\nNarm braucht Hilfe und ich werde erst ruhen, wenn er sie bekommt.\n\nKönnt Ihr helfen, <Name>?", progress = nil, completion = "Ich kann Euch nicht genug danken, Bruder.\n\nDa Ihr das Symbol des Lebens tragt, kann ich nur vermuten, dass Tiza und Muiredon Euch hergeschickt haben.\n\nEs stimmt, ich wurde Opfer der Dunkeleisenzwerge, als ich versuchte, eines der Manuskripte zu bekommen: Es gelang mir so lange durchzuhalten, bis Muiredon entkommen konnte, aber das Licht hätte mich fast in sich aufgenommen, als Ihr gekommen seid. Dass Ihr mächtig genug wart, das Symbol zu benutzen, bedeutet eine große Zukunft für Euch, doch davon wollen wir später sprechen.", rewards = "Ihr bekommt:\n\n"},
[1784] = {title = "Der Foliant der Offenbarung", objective = "Beschafft ein Dunkeleisenmanuskript von den Dunkeleisenzwergen beim Helmsbedsee und kehrt zu Muiredon Battleforge in Ironforge zurück.", description = "Bevor ich im Kampf fiel, hatten Muiredon und ich fast einen der Spione der Dunkeleisenzwerge in der Nähe dieses kleinen Hauses besiegt. Wir wurden Zeugen, wie ihr Captain ihnen Befehle weitergab, und wollten sie töten und die Befehle an uns nehmen.\n\nEinige im Rat von Ironforge glauben nicht, dass sich Dunkeleisenzwerge in Dun Morogh aufhalten. Bekämen wir eines dieser Manuskripte, hätten wir nicht nur den Beweis für ihre Tätigkeiten, sondern möglicherweise auch eine Vorstellung dessen, was sie planen.\n\nBeschafft eines dieser Manuskripte und bringt es zu Muiredon, <Name>.", progress = "Ihr seid zurück! Wie mich das freut, <Name>. Meine Wunden sind verheilt und ich bin bereit, schnellstens zum Helmsbedsee zurückzukehren, sobald ich meine Frau davon überzeugt habe, dass es mir gut geht.", completion = "Ha-ha! Ihr habt es geschafft! Ihr habt Narm gerettet und den Beweis gefunden, den meine Frau braucht, um den Rat zu überzeugen. Einen solchen Segen des Lichts wie Euch sah ich noch nie... natürlich mit Ausnahme meiner Frau.\n\nNochmals danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[1785] = {title = "Der Foliant der Offenbarung", objective = "Sprecht mit Tiza Battleforge in Ironforge.", description = "Ich sehe, meine Frau steht schon da drüben und platzt vor Stolz. Schleppt Euch besser mal hier rüber, aber pronto. Könnte mir denken, dass sie Euch was zu sagen hat.\n\n's Licht soll mit Euch sein, <Klasse>. Wenn die Zeit reif ist, such ich nach Euch auf den Schlachtfeldern, wenn es gegen die Geißel und die Dunkeleisenzwerge geht.", progress = nil, completion = "Heute habt Ihr ganz Ironforge einen großen Gefallen getan, &lt;Name&gt;. Ich bin stolz, dass Ihr zu uns gehört, und wenn Ihr bereit seid, würde ich Euch gern mit dieser Rolle segnen. Das Symbol des Lebens funktioniert nur bei einem &lt;Klasse&gt;, der bereit ist, den größten Segen des Lichts zu empfangen - die Macht, die Toten ins Leben zurückzurufen.\n\nIch lehre Euch die Fähigkeit, Eure Gefährten wiederzubeleben. Nutzt sie weise, &lt;Name&gt;, und habt Dank von mir, meinem Mann und ganz Ironforge.", rewards = "Ihr erlernt:\n\nErlösung\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErlösung\n\nIhr bekommt außerdem:\n\n"},
[1786] = {title = "Der Foliant der Offenbarung", objective = "Nehmt das Symbol des Lebens und erweckt Henze Faulk in Elwynn wieder zum Leben.", description = "Henze und ich schafften es nach Heldenwache, einer Insel inmitten des Steinhügelsees im nordöstlichen Elwynn. Wir hörten, dass Defias unsere Grenzen unterwandert hatten und wollten einen Beweis für die Berater des Königs.\n\nAls wir eine Bande dieses Abschaums sahen, die Dokumente durchlasen, griffen wir an. Leider wurden wir recht schnell durch ihre Magier überwältigt.\n\nHenze wehrte sie ab, derweil ich entkam ... der elende Narr muss immer den Helden spielen.\n\nEr ist jetzt da draußen, der gute Henze. Könnt Ihr uns helfen, <Name>?", progress = nil, completion = "Danke, Bruder.\n\nDa Ihr das Symbol des Lebens tragt, darf ich wohl annehmen, dass Euch Duthorian oder Gazin geschickt hat.\n\nIch wurde Opfer der Zauberer der Defias, als Gazin und ich ihnen ihre Pläne abnehmen wollten. Ich hielt lange genug durch, dass Gazin entkommen konnte, aber am Ende überwältigte mich ihre Magie.\n\nDoch Ihr konntet mich zurückholen: Nicht jeder besitzt die Fähigkeit, das Symbol zu benutzen, &lt;Name&gt;. Es spricht für Euch, dass Ihr fähig wart, es durch Euren eigenen Glauben mächtig werden zu lassen.", rewards = "Ihr bekommt:\n\n"},
[1787] = {title = "Der Foliant der Offenbarung", objective = "Beschafft ein Manuskript der Defias von den abtrünnigen Hexern der Defias in Elwynn und kehrt zu Gazin Tenorm in Stormwind zurück.", description = "Wir müssen uns später ausgiebiger über das Symbol unterhalten. Wichtig ist jetzt, dass wir diese Papiere bekommen, die die Defias studierten. Wenn wir sie in die Finger bekommen, können wir beweisen, dass die Defias Elwynn unterwandert haben und hoffentlich Einblick in ihre weiteren Pläne erhalten.\n\nMomentan bin ich nicht in der Verfassung zu kämpfen, <Name>. Glaubt Ihr, Ihr seid stark genug, den Defias hier auf der Insel diese Papiere abzunehmen?\n\nWenn Ihr sie beschaffen könnt, bringt sie Gazin und lasst ihn wissen, dass ich wohlauf bin.", progress = "Ist Henze in Sicherheit, <Name>? Hattet Ihr Erfolg?\n\nDurch Eure Fertigkeiten im Umgang mit Waffen und der Macht des Lichts sollte Heldenwache vor den Defias sicher sein, doch das müssen der König und seine Berater entscheiden.", completion = "Großartig! Ihr habt es geschafft und Henze gerettet. Das Licht ist eindeutig mit Euch, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[1788] = {title = "Der Foliant der Offenbarung", objective = "Sprecht mit Duthorian Rall in Stormwind.", description = "Ich bringe das Manuskript zu den Beratern des Königs, nachdem Duthorian einen Blick darauf geworfen hat. In der Zwischenzeit solltet Ihr mit Duthorian sprechen. Er wird Euch ganz sicher auf die Schulter klopfen wollen!\n\nNochmals danke, <Name>. Ich hoffe, wir sehen uns wieder. Ihr seid ein Verbündeter, den ich voller Stolz meinen Freund nenne.", progress = nil, completion = "Ihr habt Eure Sache heute gut gemacht, &lt;Name&gt;. Ihr solltet stolz auf Eure Leistungen sein.\n\nUnd noch stolzer solltet Ihr auf Eure Fähigkeiten sein. Nicht jeder kann die Macht des Symbols des Lebens nutzen. Da Ihr das Licht rufen könnt, um die Toten zu erwecken, seid Ihr bereit für eine der größten Ehren eines Paladins: die Macht der Auferstehung.\n\nIhr werdet die Macht haben, gefallene Gefährten zurückbringen zu können, wie das bei Henze geschah.\n\nGehabt Euch wohl, &lt;Name&gt;. Das Licht scheint auf Euch und Ihr solltet dankbar sein.", rewards = "Ihr erlernt:\n\nErlösung\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErlösung\n\nIhr bekommt außerdem:\n\n"},
[1789] = {title = "Das Symbol des Lebens", objective = "Solltet Ihr es nicht schaffen, Narm zu helfen, nachdem Ihr das Symbol des Lebens benutzt habt, <Name>, dann kommt zu mir zurück und ich werde Euch ein weiteres geben.\n\nEs ist sowohl für meinen Ehemann als auch für mich wichtig, dass Ihr erfolgreich zurückkehrt. Bitte sputet Euch.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSymbol des Lebens"},
[1790] = {title = "Das Symbol des Lebens", objective = "Sputet Euch, <Name>, mehr als ein Leben steht auf dem Spiel, wenn Ihr scheitert.\n\nWenn Ihr Gazin und Henze aus irgendeinem Grund nicht helfen könnt, dann kommt zu mir zurück und ich gebe Euch ein weiteres Symbol des Lebens für Eure Reisen.\n\nVersteht meine Unterstützung nicht als reine Wohltätigkeit. Ihr müsst Euch wie jeder andere <Klasse> beweisen, und wenn Ihr ständig scheitert, fällt das später auf Euch zurück.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSymbol des Lebens"},
[1791] = {title = "Der Windbehüter", objective = "Sprecht mit Bath'rah dem Windbehüter.", description = "Jetzt, da Ihr Eure Berserkerhaltung gelernt habt, wollt Ihr bestimmt auch eine hübsche Waffe dazu.\n\nSprecht mit Bath'rah dem Windbehüter. Das ist ein Troll-Einsiedler, der zwischen dem Alteracgebirge und den Westlichen Pestländern lebt. Er ist ein geschickter Waffenmacher und mächtiger Schamane.\n\nUm Bath'rah zu finden, solltet Ihr zu dem Fluss gehen, der an der Ostflanke von Tarrens Mühle entlangfließt. Folgt ihm nach Norden - Bath'rah hat sein Lager nahe den Ruinen am Ostufer des Flusses aufgeschlagen.", progress = nil, completion = "Ihr seid weit gereist, junger &lt;Klasse&gt;. Ich sehe Feuer in Euren Augen. Ihr sucht eine Waffe mit großer Macht, ja?\n\nIch kann Euch bei Eurer Suche helfen. Und Ihr mir bei meiner.", rewards = "Ihr bekommt:\n\n"},
[1792] = {title = "Wirbelwaffe", objective = "Ich habe das Wirbelherz und bin bereit, es in ein Gefäß Eurer Wahl zu legen.\n\nWählt eine Waffe, <Name>, und wisset, dass ihre Macht die Macht des Cyclonian ist.", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWirbelaxtWirbelschwertWirbelkriegshammer\n\nIhr bekommt außerdem:\n\n"},
[1793] = {title = "Der Foliant der Ehre", objective = "Es steht fest, dass das Licht mit Euch ist, <Name>, doch da die Zeiten zunehmend gefährlicher werden, ist es wichtig zu wissen, welche Kräfte dem Fleische innewohnen. Wenn Dämonen, Großdrachen oder ein anderes Übel einen Fuß in unser Land setzen, wird Eure Tapferkeit auf die Probe gestellt. Werdet Ihr stark genug sein?\n\nTapferkeit in jedweder Situation gehört ebenso zu einem <Klasse> wie das Licht, seine Rüstung und seine Waffe. Die Schwachen beschützen und den Glauben nicht verlieren, sind zwei weitere Lektionen, die Ihr meistern müsst, wenn Ihr in der Kathedrale des Lichts studiert.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFoliant der Ehre"},
[1794] = {title = "Der Foliant der Ehre", objective = "Es steht fest, dass das Licht mit Euch ist, <Name>, doch da die Zeiten zunehmend gefährlicher werden, ist es wichtig zu wissen, welche Kräfte dem Fleische innewohnen. Wenn Dämonen, Großdrachen oder ein anderes Übel einen Fuß in unser Land setzen, wird Eure Tapferkeit auf die Probe gestellt. Werdet Ihr stark genug sein?\n\nTapferkeit in jedweder Situation gehört ebenso zu einem <Klasse> wie das Licht, seine Rüstung und seine Waffe. Die Schwachen beschützen und den Glauben nicht verlieren, sind zwei weitere Lektionen, die Ihr meistern müsst, wenn Ihr in der Kathedrale des Lichts studiert.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFoliant der Ehre"},
[1795] = {title = "Die Bindung", objective = "Beschwört mit Hilfe des 'Folianten der Kabale' einen Teufelsjäger, unterwerft ihn und bringt den 'Folianten der Kabale' zu Strahad Farsan in Ratchet zurück.", description = "Wenn Ihr hinreichend vorbereitet seid, sollten wir beginnen. Lasst mich Euch den Vorgang erklären.\n\nIch beginne damit, dass ich den Standard-Beschwörungskreis erstelle. Wenn das geschehen ist, werden meine Akolythen mit den Kanalisierungsruten den größeren Kreis erstellen.\n\nIst das abgeschlossen, lest Ihr die Zauberformel aus dem Folianten der Kabale und der Teufelsjäger erscheint. Seid vorsichtig, <Name>. Ein Teufelsjäger ist ein mächtiger Widersacher. Ich möchte nicht, dass er Euch einen Kopf kürzer macht.", progress = "Jedem <Klasse> sollte ein Teufelsjäger zur Verfügung stehen. Obwohl er schwer zu bändigen ist, macht die Macht, die er seinem Herrn gibt, die Kosten bei weitem wett.", completion = "Ich muss sagen, ich bin beeindruckt, &lt;Name&gt;. Als ich meinen Teufelsjäger unterwarf, kam ich knapp mit dem Leben davon. Ich spüre, Ihr habt das Potenzial, einer der mächtigsten &lt;Klasse&gt; dieser Gegend zu werden.", rewards = "Ihr erlernt:\n\nTeufelsjäger beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\nTeufelsjäger beschwören' lehren\n\nIhr bekommt außerdem:\n\nSeelenkasten"},
[1796] = {title = "Komponenten für die verzauberte Goldblutrobe", objective = "Bringt die Roben von Arcana zu Menara Voidrender im Brachland.", description = "Der erste Gegenstand, bei dessen Erschaffung ich Euch helfen werde, ist eine Robe. Ihr werdet die Gegenstände für mich sammeln und wir werden sie zusammensetzen. Vorausgesetzt Ihr seid erfolgreich, werdet Ihr danach den ersten von vielen Gegenständen haben, die Euch mächtiger machen und Euch bei Eurem Kampf helfen werden.\n\nFür den Anfang müsst Ihr in den Besitz der Roben von Arcana kommen. Ein Schneider kann sie für Euch machen oder vielleicht könnt Ihr eine von jemandem kaufen... am meisten würde es mich beeindrucken, wenn Ihr sie selbst herstellen könntet... aber wie auch immer, bringt mir die Roben und dann machen wir weiter.", progress = "Wie läuft Eure Suche nach den Roben, <Name>? Habt Ihr selbst welche hergestellt? Diese persönlichen Feinarbeiten machen das Erfüllen mit Magie so viel schöner. Sie geben Euch eine große Befriedigung. Aber ich habe Verständnis, wenn Ihr Euch für den schnelleren Weg entschieden habt und sie habt herstellen lassen. Es hat schon was für sich ... ein solcher Ehrgeiz.", completion = "Das dürfte reichen, &lt;Name&gt;.\n\nAlle magischen Gegenstände müssen mit einem Gegenstand von hoher Qualität beginnen. Je mehr Mühe und Können man in einen Gegenstand legt, desto größere Magie kann er aufnehmen. Seltene und teurere Komponenten halten die Magie besser. Ihr werdet nicht bereuen, diese Roben in jene mit einzubringen, die wir später für Euch machen werden.", rewards = "Ihr bekommt:\n\n"},
[1798] = {title = "Die Suche nach Strahad", objective = "Sprecht mit Strahad Farsan im Brachland.", description = "Es ist Zeit, dass Ihr die Beschwörung eines Teufelsjägers lernt, <Name>. Ich habe nicht die erforderlichen Reagenzien und Gegenstände, um Euch hier zu unterrichten, daher müsst Ihr einen anderen aus unserem inneren Kreis aufsuchen, nämlich Strahad Farsan.\n\nEr hat sich im Goblin-Hafen von Ratchet niedergelassen. Ich werde ihn von Eurer Ankunft in Kenntnis setzen lassen.", progress = nil, completion = "&lt;Name&gt;? Ah, natürlich. Unser neuestes Wunderkind. Leider entspricht die Realität nicht ganz der Legende.\n\nWie auch immer, Ihr seid gekommen um zu lernen, und nicht um anzuhören, wie ich Witze über Euch mache.", rewards = "Ihr bekommt:\n\n"},
[1799] = {title = "Fragmente der Kugel von Orahil", objective = "Sprecht mit Menaras Akolythen im Inneren des Turms über Ratchet und wählt einen ihrer Wege, um ihm zu folgen.\n\nBringt danach eine Höllenkugel zu Tabetha in den Marschen von Dustwallow.", description = "Gut, dann können wir beginnen.\n\nIhr müsst als Erstes mit meinen Akolythen im Inneren sprechen. Wählt einen ihrer Wege und folgt ihm - sie werden Euch alles erklären.\n\nAls Zweites müsst Ihr nach Desolace reisen und eine Höllenkugel von einem der Hexenmeister von Mannorocs Koven holen. Diese Kugel werdet Ihr mit der Hilfe einer Magierin namens Tabetha tief in den südlichen Marschen von Dustwallow reinigen. Sie wird Euch aufgrund unserer gemeinsamen Vergangenheit helfen.\n\nKommt erst zurück, wenn Ihr beide Dinge erledigt habt, um die ich Euch gebeten habe.", progress = "Da Ihr offensichtlich kein Magier seid, frage ich mich, ob ich Euch überhaupt trauen kann. Ich kann die Macht des Arkanen an Euch riechen, aber Ihr scheint Euch dem Gestank der Verderbnis entzogen zu haben, der Eurer Art so bereitwillig anhängt.\n\nJa, ein <Klasse> ... ein <Klasse> ist gekommen, um mich um Hilfe zu bitten.\n\nNun, was kann ich für Euch tun, <Name>?", completion = "Oh, Menara schickt Euch also. Nun denn... Ich nehme an, Ihr könnt bis auf weiteres als mein Gast bleiben. Ihr habt aber doch bestimmt dringende Geschäfte zu erledigen - vielleicht seid Ihr hier, um verlorene Macht zu suchen? Vielleicht liege ich falsch. Vielleicht ist die Verderbnis doch nicht so weit entfernt von Euch.", rewards = "Ihr bekommt:\n\n"},
[1800] = {title = "Der Thronsaal von Lordaeron", objective = "Besucht mit Eurem Schützling den alten Thronsaal in Lordaeron. Er befindet sich kurz vor dem Abgang nach Undercity.", description = "Wenn wir brav sind und die Hausarbeiten ordentlich machen, erzählen uns die Waisenmatronen oft Geschichten von großen Schlachten und darüber, wie Lordaeron fiel und wie der böse Arthas seinen eigenen Vater umbrachte, nur um König zu werden.\n\nEr hatte keine Ehre, <Name>! Wenn ich erst einmal groß und ein mächtiger Krieger der Horde bin, wird mein Schwert durch die Ehre geleitet werden; niemals durch das Böse!\n\nWürdest du mit mir den Thronsaal besuchen, bitte? Er befindet sich kurz vor dem Abgang, über den man nach Undercity heruntergeht.", progress = nil, completion = "Der Thronsaal war vielleicht gruselig, &lt;Name&gt;! Obwohl er völlig leer war, konnte man noch fühlen das etwas sehr böses dort passiert ist. Ich fühlte Wut... aber ich war auch traurig. Jetzt verstehe ich, warum uns die Matronen solche Geschichten erzählen. Ich werde niemals mein Volk betrügen!\n\nDanke, dass du mit mir den Thronsaal besucht hast, &lt;Name&gt;. Ich glaube, ich habe viel gelernt.", rewards = "Ihr bekommt:\n\n"},
[1801] = {title = "Foliant der Kabale", objective = "Sprecht mit Jorah Annison in Undercity.", description = "Mehr als ein einfacher Beschwörungskreis wird erforderlich sein, um einen Teufelsjäger als Herausforderer für Euch herzubringen.\n\nMeine drei Akolythen und ich helfen, die magischen Kreise zu erschaffen. Ihr benötigt eine Kopie des Folianten der Kabale, der seit geraumer Zeit als verschollen gilt. Er wurde von der ersten Gruppe Hexenmeister geschrieben, die ohne Unterstützung einen Teufelsjäger beschwörten.\n\nVielleicht kann Jorah Annison Euch dabei helfen. Heute arbeitet er als Kartograf in Undercity, weiß aber dennoch mehr über alte Schriften als ich.", progress = nil, completion = "Karten machen! Bilder, Einschätzungen der Realität. Dafür habe ich keine Verwendung.\n\nIn Büchern, Erzählungen und Beschreibungen! Dort ist die Wahrheit. Ich würde alle Karten in diesem Laden für ein Buch über den Siegeszug der Totenbeschwörung oder eine Geschichte über den Triumph der dunklen Fürstin tauschen.", rewards = "Ihr bekommt:\n\n"},
[1802] = {title = "Foliant der Kabale", objective = "Beschafft den schimmeligen Folianten und das zerlumpte Manuskript für Krom Stoutarm in Ironforge.", description = "Er ist verschollen, aber man glaubt zu wissen, wo man ihn finden könnte.\n\nNur eine Kopie wurde jemals angefertigt, und die wurde einst beschädigt, eine Vielzahl von Seiten herausgerissen. Man munkelt, dass er irgendwie den Zentauren von Tausend Nadeln in die Hände gefallen sein soll.\n\nDer Rest ging an der Küste westlich von Southshore verloren, als er per Schiff zum Hafen von Menethil hätte transportiert werden sollen. Er kam nie an.\n\nAls Gegenleistung für dieses Wissen verlange ich nur, dass Ihr ihn findet und mir zur Ansicht bringt.", progress = "Haben sich die Gerüchte als zutreffend erwiesen, <Name>?", completion = "Phantastisch! Nun gehöre ich zu den Wenigen, die seinen Inhalt gesehen haben.\n\nIch kann es kaum erwarten, den Text weiter zu studieren. Das ist ein großer Tag, &lt;Name&gt;! Wenn Ihr mich nur einen Blick hineinwerfen lassen würdet, bevor Ihr geht. Ich bin sicher, Strahad wird bereit sein, mir eine Kopie zu schicken.", rewards = "Ihr bekommt:\n\n"},
[1803] = {title = "Foliant der Kabale", objective = "Beschafft den schimmeligen Folianten und das zerlumpte Manuskript für Jorah Annison in Undercity.", description = "Ah! Ich sehe, Ihr seid ein Hexenmeister, der meinen Geschmack teilt. Den Folianten der Kabale zu beschaffen ist ein würdiges Ziel. Habt Ihr gewusst, dass er sich einst innerhalb der Mauern von Lordaeron befand? Aber er wurde beschädigt, fast die Hälfte der Seiten herausgerissen. Wer würde so eine abscheuliche Tat begehen?\n\nDiese Hälfte ist verschollen, doch man munkelt, sie soll den Zentauren von Tausend Nadeln in die Hände gefallen sein.\n\nDer Rest des Textes sollte nach Ironforge gebracht werden, ging aber während der Überfahrt an der Westküste von Southshore verloren.", progress = "Mag sein, dass Ihr Hirngespinsten nachjagt, <Name>, aber selbst die wildesten Gerüchte enthalten meist ein Körnchen Wahrheit.", completion = "Ach nein! Was haben wir denn hier?\n\nDas ist beeindruckend, &lt;Name&gt;. Ich hätte es nie für möglich gehalten, aber hier halte ich den vollständigen Folianten der Kabale in Händen.\n\nLasst mich nur kurz die Seiten durchblättern bevor Ihr wieder geht.", rewards = "Ihr bekommt:\n\n"},
[1804] = {title = "Foliant der Kabale", objective = "Bringt den rekonstruierten Folianten und 3 Kanalisierungsruten zu Strahad Farsan in Ratchet.", description = "Ach ja, es ist recht schwer, ihn aus der Hand zu geben. Aber Ihr habt ihn gefunden und natürlich Wichtigeres damit zu tun. Vergesst nur nicht, Strahad zu sagen, dass ich eine Kopie haben möchte.\n\nWährend Ihr fort wart, hat er eine Nachricht für Euch geschickt. Er sagte mir, damit seine Akolythen bei der Beschwörung helfen können, müsst Ihr drei Kanalisierungsruten beschaffen.\n\nEr weiß vielleicht nicht, wo man die findet, aber ich! Sie wurden zuletzt von den Orcs des Dragonmawklans im Sumpfland verwendet. Ich würde mich mal mit ihren Zauberern in Verbindung setzen!", progress = "Ich habe Euch eine Weile nicht in dieser Gegend gesehen. Habt Ihr den Folianten und die Ruten schon gefunden?", completion = "Gut gemacht! Der Foliant der Kabale und drei makellose - vermutlich nur leicht zerkratzte - Kanalisierungsruten.\n\nDas wird interessant. Es ist eine Weile her, seit ein junger &lt;Klasse&gt; sich einen Teufelsjäger zugelegt hat.", rewards = "Ihr bekommt:\n\n"},
[1805] = {title = "Foliant der Kabale", objective = "Bringt den rekonstruierten Folianten und 3 Ruten des Kanalisierens zu Strahad Farsan in Ratchet.", description = "Das ist einer der interessantesten Texte, die ich in den letzten Jahren gelesen habe. Die Auswahl hier ist nicht sonderlich groß - zum Großteil sind es Bücher über Geographie - und ich habe sie schon alle gelesen. Hoffentlich schickt mir Strahad eine Kopie dieses Folianten, wenn er die Chance dazu hat.\n\nDa wir gerade von ihm sprechen: während Ihr fort wart, habe ich eine Nachricht von ihm erhalten. Für Eure Aufgabe müsst Ihr drei Ruten des Kanalisierens beschaffen.\n\nWeil Ihr mir diesen Text gezeigt habt, weihe ich Euch in ein Geheimnis ein: Ihr findet die Ruten bei den Orcs des Dragonmawklans im Sumpfland.", progress = "Ja, <Name>? Wie kann ich Euch behilflich sein?", completion = "Gut gemacht! Der Foliant der Kabale und drei makellose - vermutlich nur leicht zerkratzte - Kanalisierungsruten.\n\nDas wird interessant. Es ist eine Weile her, seit ein junger &lt;Klasse&gt; sich einen Teufelsjäger zugelegt hat.", rewards = "Ihr bekommt:\n\n"},
[1806] = {title = "Die Prüfung der Rechtschaffenheit", objective = "Wartet, bis Jordan Stilwell eine Waffe für Euch geschmiedet hat.", description = "Warum gehen wir nicht rüber zur Schmiede und fangen damit an? Ich treffe schon seit einiger Zeit Vorbereitungen für Eure Ankunft, daher dürfte es nicht allzu lange dauern.\n\nWenn wir fertig sind, werdet Ihr viel besser gerüstet sein, das Licht zu verteidigen, als bisher, das schwöre ich Euch.\n\nIch will ehrlich sein, <Name>, wenn ich die Ergebnisse Eurer Taten sehe, erfüllt mich ein gewisser Neid. Doch das Wissen, dass ich auf meine bedeutende Weise zu Euren Abenteuern beitragen kann, erfüllt mich mit Freude.", progress = nil, completion = "Da ist sie, &lt;Name&gt;. Eine Waffe, wie sie einem Helden des Lichts würdig ist. Ich benannte sie nach einem großen Zwergenpaladin, der ein Freund von mir war. Sein Name war Verigan... Bosch Verigan. Bitte nehmt sie in meinem Namen und dem meiner Frau. Wir stehen tief in Eurer Schuld. Die Welt ist sicherer, wenn einer mit Euren Fähigkeiten durch das Land zieht.", rewards = "Ihr bekommt:\n\nVerigans Faust"},
[1818] = {title = "Gespräch mit Dillinger", objective = "Sprecht mit Todeswache Dillinger in Brill.", description = "Todeswache Dillinger sagte mir, er habe einen Job für jemanden wie Euch. Wenn Ihr bereit seid, den Streitkräften der dunklen Fürstin Euren Wert zu beweisen, dann meldet Euch umgehend bei Dillinger.\n\nTodeswache Dillingers Posten liegt am Westende von Brill, nahe beim Friedhof.", progress = nil, completion = "Seid Ihr wegen einer Mission hier? Gut. Ich habe eine wichtige, die Eure Fertigkeiten im Gefecht auf die Probe stellt... und Eure Entschlossenheit, die Verlassenen zu verteidigen.", rewards = "Ihr bekommt:\n\n"},
[1819] = {title = "Ulag der Spalter", objective = "Tötet Ulag den Spalter und sprecht dann mit Todeswache Dillinger.", description = "Als die Geißel durch Tirisfal zog, konnten wir einen ihrer Angehörigen einfangen, um ihn zu studieren. Er hatte einen freien Geist und nannte sich Ulag der Spalter. Doch obwohl er einen freien Willen besaß, stand er noch immer unter dem Bann des Lichkönigs.\n\nWir hofften, wir könnten den Einfluss des Königs auf Ulag brechen, doch es gelang uns nicht. Jetzt ist die Zeit gekommen, ihn zu befreien. \n\nBefreit und tötet ihn.\n\nAktiviert den Schädelstein-Auslöser beim Mausoleum im Norden. Damit wird das magische Siegel entfernt, das ihn bindet.\n\nUnd dann... seid bereit, <Name>.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ulag war kein unmaßgeblicher Agent der Geißel. Ihr habt den Todeswachen, und damit der dunklen Fürstin, gezeigt, dass Ihr ein geschickter und entschlossener &lt;Klasse&gt; seid, und Euch damit weitere Ausbildung verdient.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWeg der Verteidigung\n\nIhr bekommt:\n\n"},
[1820] = {title = "Gespräch mit Coleman", objective = "Sprecht mit Coleman Farthing.", description = "Ihr habt Euren Wert für die dunkle Fürstin bewiesen, vielleicht könnt Ihr ihn nun an einem ihrer Untertanen beweisen.\n\nColeman Farthing wartet auf einen Krieger, der bereit ist, sein Instrument der Rache gegen die Feinde der Verlassenen zu sein.\n\nIhr findet ihn in der Taverne Zur Galgenschlinge im Osten von Brill.", progress = nil, completion = "Ja, es stimmt. Ich brauche Eure Fertigkeiten im Gefecht. Meine Mittel sind bescheiden, doch meine Aufgabe hilft mir und der Sache der Verlassenen. Macht es, und Ihr werdet zweifache Belohnung erhalten.", rewards = "Ihr bekommt:\n\n"},
[1821] = {title = "Agamand-Erbstücke", objective = "Bringt Coleman Farthing die Axt, das Schwert, den Streitkolben und den Dolch der Familie Agamand.", description = "Zu Lebzeiten war die Familie Agamand mein Arbeitgeber und sie war die Ursache für meinen Tod. Es ist nur recht und billig, dass die Agamands jetzt hirnlose Diener des Lichkönigs sind.\n\nUnd jetzt möchte ich ihnen den letzten Rest Ehre nehmen. Geht in ihre Familiengruft und stehlt ihnen die Familienerbstücke: ein Schwert, eine Axt, einen Dolch und einen Streitkolben. Bringt sie mir!\n\nDie Gruft der Familie Agamand liegt am nördlichen Ende von Agamands Mühlen. Der Ort wird durch lauernde Angehörige der Geißel und tote Agamands bewacht.", progress = "Habt Ihr die Erbstücke, <Name>?", completion = "Ah! Ihr habt sie genommen! Jetzt ist das letzte Restchen Ehre und Andenken vom verfluchten Land der Agamands entfernt. Die Familie existiert wahrlich nicht mehr!", rewards = "Ihr bekommt:\n\n"},
[1822] = {title = "Erbstückwaffe", objective = "Ich behalte drei der Waffen, die Ihr mir gebracht habt, als Andenken an meinen Schmerz und Verlust. Aber bitte, <Name>, wählt Euer Lieblingserbstück und behaltet es für Euch.\n\nMöge es Euch besser dienen als seinen verfluchten vorherigen Besitzern.", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErbstückaxtErbstückhammerErbstückdolchErbstückschwert\n\nIhr bekommt außerdem:\n\n"},
[1823] = {title = "Gespräch mit Ruga", objective = "Sprecht mit Ruga Ragetotem.", description = "Ihr seid ein Krieger mit Fertigkeiten und wachsendem Ansehen. Vielleicht seid Ihr bereit für Ruga Ragetotems Prüfung. Wenn ja, findet Ihr Ruga im Camp Taurajo im Brachland.\n\nEr wartet auf Krieger, die seinem Ruf folgen.", progress = nil, completion = "Seid Ihr wegen meiner Prüfung hier, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"},
[1824] = {title = "Prüfung auf dem Feld der Riesen", objective = "Bringt 5 zuckende Fühler zu Ruga Ragetotem im Camp Taurajo.", description = "Um diese Prüfung zu bestehen, müsst Ihr nach Süden zum Feld der Riesen reisen. Dort findet Ihr einen Schwarm krabbelnder Insektenwesen. Sie sind neu im Brachland und mir gefällt nicht, was sie ankündigen.\n\nBringt mir einen ihrer noch zuckenden Fühler und vergeudet keine Zeit, <Name>, denn abgetrennte Fühler zucken nicht lange. Bringt mir die Fühler in der genannten Zeit und Ihr werdet die Prüfung bestehen.", progress = "Habt Ihr die Fühler? Wenn ja, gebt sie mir schnell, denn zuckende Fühler zucken nicht ewig...", completion = "Ordentlich gemacht, &lt;Name&gt;! Mit der bestandenen Prüfung auf dem Feld der Riesen habt Ihr einen weiteren Schritt auf dem Weg des Kriegers getan.", rewards = "Ihr bekommt:\n\nRugas Bollwerk"},
[1825] = {title = "Gespräch mit Thun'grim", objective = "Sprecht mit Thun'grim Firegaze im Brachland.", description = "Thun'grim Firegaze, ein berühmter Orc-Schmied, hat von Euren fortgesetzten Heldentaten im Dienst der Horde gehört. Er möchte eine Rüstung für Euch anfertigen und bittet, dass Ihr umgehend mit ihm sprecht.\n\nThun'grims Lager liegt östlich von Crossroads im Brachland.", progress = nil, completion = "Ja, Ihr seid gekommen. Das ist gut, denn wir haben viel zu besprechen, wir beide.", rewards = "Ihr bekommt:\n\n"},
[1838] = {title = "Brutale Rüstung", objective = "Bringt Thun'grim Firegaze 15 rauchige Eisenblöcke, 10 pulverisierte Azurite, 10 Eisenbarren und 1 Phiole Phlogiston.", description = "Ich habe Geschichten über Eure Kraft und Tapferkeit gehört und möchte eine Rüstung für Euch anfertigen, eine Unterstützung für Euch, während die Geschichten über Eure Ruhmestaten wachsen.\n\nAber die Herstellung dieser Rüstung wird eine Aufgabe für sich sein, <Name>. Ich werde Eure Hilfe benötigen und die Hilfe der anderen Schmiede der Horde.\n\nHier, nehmt diese Rolle. In vielen Nächten habe ich mit fast blinden Augen aufgeschrieben, was ich für die Rüstung benötige. Bringt mir die Gegenstände auf dieser Rolle und ich fertige das erste Teil der Rüstung für Euch an.", progress = "Habt Ihr die Gegenstände auf meiner Rolle, <Name>?", completion = "Ihr habt alles gebracht, worum ich Euch bat. Jetzt beginnt meine Arbeit...", rewards = "Ihr bekommt:\n\n"},
[1839] = {title = "Ula'elek und die brutalen Stulpen", objective = "Sprecht mit Ula'elek in Durotar.", description = "Der Trollschmied Ula'elek wird die brutalen Stulpen für Euch anfertigen. Er wohnt mit seinen Darkspearbrüdern in Durotar in Sen'jin und erwartet Eure Ankunft.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Der alte Thun'grim ließ mich wissen, dass Ihr kommt, doch hätte er geschwiegen, hätte mich Eure Anwesenheit hier nicht überrascht.\n\nDie Geister wachen über Eure Fortschritte, junger &lt;Klasse&gt;, und sagen mir, dass Ihr viele Feinde beseitigt habt.", rewards = "Ihr bekommt:\n\n"},
[1840] = {title = "Orm Stonehoof und der brutale Helm", objective = "Sprecht mit Orm Stonehoof in Thunder Bluff.", description = "Orm Stonehoof wird ob seiner Fertigkeiten hoch geachtet. Er wird den brutalen Helm für Euch machen.\n\nSucht ihn in Thunder Bluff beim Teich nahe dem großen, zentralen Totem der Stadt.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;. Ich bin Orm. Thun'grim sagte mir, Ihr wünscht einen Helm?", rewards = "Ihr bekommt:\n\n"},
[1841] = {title = "Velora Nitely und die brutalen Beinschützer", objective = "Sprecht in Undercity mit Velora Nitely.", description = "Es heißt, vor ihrem Tod hätte Velora Nitely zu den besten Rüstungsschmieden von Lordaeron gehört. Offenbar konnte der Tod ihrem Talent nichts anhaben. Sprecht mit Velora - sie wird die brutalen Beinschützer für Euch machen.\n\nVelora geht ihrem Gewerbe in Undercity unterhalb von Lordaeron nach, im Handwerksviertel.", progress = nil, completion = "Seid Ihr wegen der Beinrüstung hier? Großartig!\n\nHm... mache ich die Rüstung für Euch oder Ihr sie für mich?\n\nDas war ein Witz. War er komisch? Ich weiß es nicht... Ich habe meinen Sinn für Humor im selben Moment wie meinen Geruchssinn verloren. Das war auch der Moment, als ich aufhörte zu atmen.", rewards = "Ihr bekommt:\n\n"},
[1842] = {title = "Satyrhufe", objective = "Bringt 7 ungespaltene Satyrhufe zu Ula'elek in Sen'jin in Durotar.", description = "Ich kann Euch ein Paar brutale Stulpen machen, denen große Magie innewohnen wird. Doch vorher müsst Ihr diese Magie sammeln und mir bringen.\n\nDie Satyrn halten sich im nordöstlichen Teil von Ashenvale auf wegen der Macht, die dem Wald innewohnt. Sie nähren sich an seiner Reinheit, saugen sie ab und verderben sie. An den geschwollenen, ungespaltenen Hufen erkennt man, welche Satyrn die meiste Magie Ashenvales aufgenommen haben.\n\nDiese Hufe besitzen große Macht. Ich brauche sie, um Eure Stulpen anzufertigen.", progress = "Habt Ihr die Hufe, <Name>? Die Magie in ihnen ist stark.", completion = "Ah, Ihr habt sie! Jetzt werde ich die Macht in diesen Hufen absaugen und in meine Rüstung einfließen lassen, so wie die Satyrn die Stärke von Ashenvale absaugten.", rewards = "Ihr bekommt:\n\n"},
[1843] = {title = "Brutale Stulpen", objective = "Danke, <Name>. Diese Stulpen sind meine beste Arbeit. Nehmt sie. Wenn Ihr sie tragt, bringt es mir und meinen Vorfahren Ehre.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBrutale Stulpen"},
[1844] = {title = "Schimärenhorn", objective = "Bringt ein galvanisiertes Horn zu Orm Stonehoof in Thunder Bluff.", description = "Ich mache Euch den Helm, doch vorher müsst Ihr mir zeigen, dass Ihr würdig seid.\n\nEingebettet in die nordwestlichen Ausläufer des Steinkrallengebirges liegt das verbrannte Tal. Das war einst ein fruchtbarer Ort, ist aber heute besudelt und voll Asche. Die Kreaturen, die dort noch hausen, sind wahnsinnig vor Schmerz und Verzweiflung.\n\nAn diesen Ort schicke ich Euch, <Name>.\n\nIhr müsst zum verbrannten Tal reisen und eine Schimärenmatriarchin suchen. Tötet sie, erlöst sie von ihrem Elend. Bringt mir ihr galvanisiertes Horn als Beweis, dann mache ich den Helm für Euch.", progress = "Habt Ihr das Horn? Ist die Matriarchin von Schmerzen befreit?", completion = "Ihr habt Eure Aufgabe beendet, &lt;Name&gt;, und Euch als würdig und entschlossen erwiesen. Der Helm wird Euch gehören...", rewards = "Ihr bekommt:\n\n"},
[1845] = {title = "Brutaler Helm", objective = "Ich gebe Euch diesen Helm.\n\nGroße Taten brachten Euch zu mir, <Name>, und wenn es der Erdenmutter gefällt... liegen noch größere vor Euch.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBrutaler Helm"},
[1846] = {title = "Schienbeinknochen der Dragonmaw", objective = "Bringt 8 stabile Schienbeinknochen eines Dragonmaw zu Velora Nitely in Undercity.", description = "Um brutale Beinschützer zu machen, brauche ich eine Stütze aus stabilem Schienbeinknochen. Die Orcs des Dragonmawklans im Sumpfland haben hübsche, dicke Schienbeinknochen. Die brauche ich.\n\nAber sie müssen stabil sein. Prüft die Schienbeinknochen unbedingt, wenn Ihr sie einsammelt. Wenn Ihr sie mit bloßen Händen zerbrechen könnt, sind sie nicht stabil genug für mich.", progress = "Ich warte auf diese Schienbeinknochen, <Name>. Sie werden ein prächtiges Gestell für Eure Beinschützer.", completion = "Gut gemacht! Die sehen robust genug aus. Ich glaube, sie sind genau richtig. Wie haben die Orcs reagiert, als Ihr ihnen an die Schienbeinknochen wolltet, &lt;Name&gt;? Haben Sie viel Getue gemacht?\n\nDas war wieder ein Witz. Ihr lacht ja gar nicht.\n\nIch bin heutzutage nicht mehr sehr komisch, oder?", rewards = "Ihr bekommt:\n\n"},
[1847] = {title = "Brutale Beinschützer", objective = "Hier sind Eure Beinschützer, <Name>. Lasst mich wissen, ob sie passen oder geändert werden müssen. Ich möchte zufriedene Kunden! Zumindest früher wollte ich das.\n\nHeutzutage liegt mir nicht mehr viel an meinem Handwerk. Aber immer noch besser, als eine hirnlose Dienerin der Geißel zu sein!\n\nDenke ich.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBrutale Beinschützer"},
[1848] = {title = "Brutale Halsberge", objective = "Ich bin sicher, Ihr habt bei dieser Aufgabe viele Unannehmlichkeiten erduldet und viel Blut vergossen, <Name>. Hier ist das Produkt Eurer Mühsal.\n\nMöge es Euch gute Dienste leisten und möget Ihr eines Tages wiederkommen und erzählen, wie nützlich sie Euch waren.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBrutale Halsberge"},
[1858] = {title = "Die Shattered-Hand", objective = "Stehlt Tazans Schlüssel, öffnet seinen Ranzen damit und bringt den Inhalt zu Therzok in der Kluft der Schatten in Orgrimmar.", description = "Ich überlasse es Euch, Tazans Ranzen zu öffnen und mir seinen Inhalt zu bringen. Der Schlossmechanismus ist komplex, daher wäre es wohl das Beste, wenn Ihr Euch den Schlüssel beschafft.\n\nDa Ihr ihn bei Tazans Leichnam nicht gefunden habt, kann ich nur annehmen, dass er ihn jemandem in Obhut gegeben hat. Ah, ja, ganz recht! Er hatte einen Assistenten namens Gamon. Ein Trunkenbold, vermutlich findet Ihr ihn in der Taverne. Vielleicht könnt Ihr ihm den Schlüssel heimlich abnehmen.", progress = "Ist es nicht verflixt, das Objekt der Begierde in Reichweite zu haben und trotzdem nicht ranzukommen?.", completion = "Hmm, also das ist interessant. Ihr habt Euren Wert damit mehr als bewiesen, &lt;Name&gt;. Ich bin recht beeindruckt. Betrachtet Euch als neuestes Mitglied der Shattered-Hand. Und nehmt dies; ich glaube, es wird Euch in Zukunft eine große Hilfe sein.", rewards = "Ihr bekommt:\n\nKlinge der Geschicklichkeit"},
[1859] = {title = "Therzok", objective = "Sprecht mit Therzok in der Kluft der Schatten in Orgrimmar.", description = "Sprecht leiser, <Name>. Ja, ich kenne Euren Namen. Mir wurde gesagt, ich soll nach einem Orc Ausschau halten, auf den Eure Beschreibung passt.\n\nSoweit wir gehört haben, könnt Ihr im Gefecht bestehen und habt nichts gegen ein wenig Heimlichtuerei von Zeit zu Zeit einzuwenden.\n\nHabe ich Recht?\n\nWie auch immer, Ihr solltet Therzok in Orgrimmar aufsuchen. Er hat ein Angebot, das Ihr Euch anhören solltet.", progress = nil, completion = "Ausgezeichnet, ich bin froh, dass Kaplak Euer habhaft wurde.\n\nWir haben einiges zu besprechen, darunter auch Eure Zukunft bei der Hand.", rewards = "Ihr bekommt:\n\n"},
[1860] = {title = "Gespräch mit Jennea", objective = "Sprecht in Stormwind mit Jennea Cannon.", description = "Wir Magier haben eine Aufgabe, die erledigt werden muss. Sie ist für die Sicherheit von Stormwind und dem Wald von Elwynn von entscheidender Bedeutung.\n\nJennea Cannon kennt die Einzelheiten. Sie studiert im Magiersanktum im Magierviertel von Stormwind. Ihr solltet Euch eiligst zu ihr begeben.", progress = nil, completion = "Wurdet Ihr geschickt, um mich bei meiner Aufgabe zu unterstützen, &lt;Name&gt;? Gut. Schön zu sehen, dass junge &lt;Klasse&gt; darauf brennen, unsere Sache zu unterstützen...\n\nWas für eine Sache, fragt Ihr? Alles zu seiner Zeit. Zu gegebener Zeit werdet Ihr es erfahren.", rewards = "Ihr bekommt:\n\n"},
[1861] = {title = "Spiegelsee", objective = "Bringt eine Probe des Spiegelsee-Wassers zu Jennea Cannon in Stormwind.", description = "Diese Welt ist gewaltigen mystischen Kämpfen zum Opfer gefallen, die magische Ströme aus ihren einst stabilen Kanälen rissen. Wir haben Mühe, die Auswirkungen dieser Veränderungen herauszufinden. Einige von uns fürchten das Schlimmste.\n\nAber davon werde ich Euch später mehr erzählen. Im Augenblick müsst Ihr Informationen für uns sammeln.\n\nHier, nehmt dieses Fläschchen. Geht zum Wasserfall des Spiegelsees, südwestlich der Tore von Stormwind, und holt dort eine Probe des Wassers. Bringt sie mir, damit ich die magische Besudelung messen kann.", progress = "Habt Ihr die Probe, <Name>? Der Fluss der Magie in Stormwind und Elwynn wurde verändert; ich muss wissen, ob sie in das Wasser sickert.", completion = "Danke, &lt;Name&gt;. Ich werde das Wasser auf magische Eigenschaften hin prüfen. Hoffen wir, dass es keine enthält, sonst werden alle, die zu lange aus dem Spiegelsee trinken, negativ beeinflusst.\n\nHier, &lt;Name&gt;. Nehmt diese Kugel oder diesen Stab als Zeichen dafür, dass Ihr mir gute Dienste geleistet habt. Was Ihr auch wählt, es möge Euch nützlich sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLeykugelLeystab\n\nIhr bekommt außerdem:\n\n"},
[1878] = {title = "Wasserbeutelkopfgeld", objective = "Ihr seid ja schon wieder da, <Name>! Wenn Ihr noch fünf Wasserbeutel eines Wüstenläufers für mich habt, dann habe ich hier ein kleines Paket, das nur auf Euch wartet!", description = nil, progress = "Ihr seid ja schon wieder da, <Name>! Wenn Ihr noch fünf Wasserbeutel eines Wüstenläufers für mich habt, dann habe ich hier ein kleines Paket, das nur auf Euch wartet!", completion = "Hervorragend - je mehr Wasserbeutel wir wiederbeschaffen können, desto weiter sind wir von einer Katastrophe entfernt! Bringt mir mehr und ich werde Euch für jeweils fünf Wasserbeutel belohnen, die Ihr mir bringt.", rewards = "Ihr bekommt:\n\nGadgetzan Water Co.-Care-Paket"},
[1879] = {title = "Gespräch mit Bink", objective = "Sprecht mit Bink in Ironforge.", description = "<Name>! Bink, meine Gnomen-Kollegin in Ironforge, hat sich gemeldet. Sie hat eine Aufgabe zu erledigen und will sich dabei nur auf einen Magier verlassen! Seid Ihr <ein Magier/eine Magierin>, <Name>?\n\nWenn ja, sprecht mit Bink. Sie verbringt ihre Zeit in Ironforge in der Halle der Mysterien im mystischen Krieg.", progress = nil, completion = "Oh, ich sehe, dass Ihr viel versprechend seid, ja, so ist es! Aber das reicht nicht für einen guten &lt;Klasse&gt;. Wenn man kein guter &lt;Klasse&gt; ist, dann ist man ein schlechter &lt;Klasse&gt;. Und schlechte &lt;Klasse&gt; sind ein Teil des Problems, so ist es!\n\nUps, ich greife mal wieder vor. Eins nach dem anderen!", rewards = "Ihr bekommt:\n\n"},
[1880] = {title = "Magitastischer Gizmonitor", objective = "Bringt Bink ihren magitastischen Gizmonitor.", description = "Wir Magier machen mehr als nur mit den Fingern schnippen und hübsche Funken regnen lassen. Wir kontrollieren die Magie, die Grundsubstanz unserer Welt! Das erfordert große Umsicht und Entschlossenheit. Und Wissen... viel, viel Wissen!\n\nEines meiner Geräte, der magitastische Gizmonitor, sammelt und speichert dieses Wissen in riesigen Mengen! Aber ich verlor ihn! Als wir aus unserer Heimat Gnomeregan flohen, ließ ich ihn in einer Truhe in einer unserer Hütten vor der Stadt, und jetzt wimmelt es dort von Lepragnomen!\n\nBitte, <Name>, findet meinen Gizmonitor wieder!", progress = "Habt Ihr meinen Gizmonitor gefunden? Ich muss ihn haben, ehe sein Energievorrat aufgebraucht ist!", completion = "Na großartig! Als ich meinen Gizmonitor herstellte, hatte ich keine Ahnung, wie abhängig ich einmal davon werden würde. Jetzt kann ich mit meinen Studien von vorn beginnen!\n\nDanke, &lt;Name&gt;! Und hier - das waren meine allerersten Magierwerkzeuge. Sie sind ein wenig zerkratzt, haben sich aber immer bewährt. Sucht Euch eines davon aus - ich bin sicher, Ihr werdet es nützlich finden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nArkane KugelArkaner Stab\n\nIhr bekommt außerdem:\n\n"},
[1881] = {title = "Gespräch mit Anastasia", objective = "Sprecht mit Anastasia Hartwell.", description = "<Name>, Anastasia Hartwell hat eine Aufgabe für jemanden mit Euren Talenten. Sprecht mit ihr im Magieviertel von Undercity und bereitet Euch auf den ersten Auftrag der Magier der Verlassenen vor.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Ihr wart weise, meinem Ruf zu folgen. Noch weiser wäre es, meine folgenden Worte zu beachten...", rewards = "Ihr bekommt:\n\n"},
[1882] = {title = "Balnirs Bauernhof", objective = "Bringt Balnir-Löwenmäulchen zu Anastasia Hartwell im Magierviertel von Undercity.", description = "Die Pestländer im Osten sind entartet. Der Lichkönig hat sie ersonnen, und jetzt breitet sich ihre Magie im Erdboden aus und verdirbt und tötet alles Leben. Die zerstörerischen Kräfte der Seuche haben zwar eine gewisse Bezauberung, doch wir, die Magier der Verlassenen, sind der Meinung, sie ist ungehörig und muss ausgemerzt werden.\n\nDoch zuerst müssen wir herausfinden, wie weit sie sich nach Tirisfal ausgebreitet hat. Geht zu Balnirs Bauernhof im Osten von Tirisfal. Im Garten blühen Blumen - Löwenmäulchen. Sammelt sie und kehrt zurück.", progress = "Habt Ihr die Löwenmäulchen? Diese Pflanzenart ist höchst empfänglich für magische Energien. Das Studium der Löwenmäulchen aus der unmittelbaren Nähe der Pestländer kann uns sagen, ob die Seuche schon in Tirisfal eingedrungen ist.", completion = "Ah, das ist ein wunderbares Exemplar. Ich schicke es zu unseren Apothekern, damit sie das Ausmaß der Besudelung der Pestländer bestimmen können.\n\nGut gemacht, &lt;Name&gt;. Als Dank für Eure Dienste, habt Ihr die Wahl: Wollt Ihr eine Kugel oder einen Stab? Was auch immer wählt, Ihr werdet es recht nützlich finden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nArkane KugelArkaner Stab\n\nIhr bekommt außerdem:\n\n"},
[1883] = {title = "Gespräch mit Un'thuwa", objective = "Sprecht mit Un'thuwa.", description = "Un'thuwa, Stammesmagier in Sen'jin, spürt eine Störung in den magischen Strömen von Durotar und bittet um Unterstützung. Sprecht mit Un'thuwa und tut, was Ihr könnt, um ihm zu helfen.\n\nGelingt Euch das, werden Euch zu gegebener Zeit weitere Geheimnisse enthüllt.", progress = nil, completion = "Grüße, &lt;Name&gt;. Gelobet seid Ihr, denn meine Bitte um Unterstützung wurde erhört. Hoffen wir, dass Ihr der Aufgabe gewachsen seid...", rewards = "Ihr bekommt:\n\n"},
[1884] = {title = "Jujuhaufen", objective = "Zerstört 4 Jujuhaufen und kehrt dann zu Un'thuwa in Sen'jin zurück.", description = "Der Hexenmeister Zalazane von den Echoinseln hat den normalen Fluss der Magie in Durotar gestört. Das vollbringt er mit besudelten Fetischen, Jujuhaufen, die er auf der Echohauptinsel in seinen Hütten aufgeschichtet hat.\n\nDiese Haufen haben unser Ökosystem verdorben und Hexenmeistern und Höllenkreaturen, die in den dunklen Winkeln des Landes hausen, Macht gegeben.\n\nIhr müsst diese Jujuhaufen zerstören, <Name>, bevor der Fluss der Magie für immer verändert ist.", progress = "Ihr müsst Euch beeilen, <Name>. Zerstört die Jujuhaufen!", completion = "Ich spüre, dass Zalazanes Jujuhaufen zerstört wurden. Mit Zeit und etwas Glück wird sich der Fluss der Magie in Durotar wieder normalisieren.\n\nIhr habt eine Großtat für Euer Volk vollbracht, &lt;Name&gt;. Und Ihr habt Euch unser, der &lt;Klasse&gt; der Horde, als würdig erwiesen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLeykugelLeystab\n\nIhr bekommt außerdem:\n\n"},
[1885] = {title = "Mennet Carkad", objective = "Sprecht mit Mennet Carkad im Schurkenviertel von Undercity.", description = "<Name>? Nicht ganz das, was ich erwartet hatte, wenn man bedenkt, dass Carkad selbst Interesse an Euch gezeigt hat. Aber das Aussehen kann täuschen, nicht?\n\nSo oder so, Ihr solltet ihn schnellstmöglich aufsuchen. Ihr könnt Euch nicht vorstellen, was aus den Letzten geworden ist, die seinem Ruf nicht Folge leisteten.", progress = nil, completion = "Hm. Ihr seid zweifellos in dem Augenblick hierher gekommen, als Ihr meinen Ruf vernommen habt, nicht? Natürlich. Von einem angehenden Todespirscher hätte ich nichts anderes erwartet.", rewards = "Ihr bekommt:\n\n"},
[1886] = {title = "Die Todespirscher", objective = "Beschafft Astors Empfehlungsschreiben und bringt es zu Mennet Carkad im Schurkenviertel.", description = "Wenn Ihr Euch den Todespirschern anschließen möchtet, der Elitewache von Lord Varimathras, müsst Ihr Euren Wert beweisen.\n\nIch will Euch nichts vormachen, <Name>, diese Aufgabe könnte Euren Tod bedeuten.\n\nIch habe ein paar Angelegenheiten, die geregelt werden müssen. Ich benötige die persönlichen Habseligkeiten von Astor Hadren, einem Boten, der zwischen Silberwald und Undercity pendelt. Die Beschaffungsmethode überlasse ich ganz Euch.\n\nJe weniger Ihr über diese Angelegenheit Bescheid wisst, desto besser. Wenn Ihr Erfolg habt, sage ich Euch mehr.", progress = "Erfolgsmeldung?", completion = "Gut gemacht, &lt;Name&gt;. Ihr habt den ersten Teil dieser Prüfung bestanden. Hoffentlich hat Andron keinen Wind von Euren Aktivitäten bekommen, sodass wir ihn davon überzeugen können, dass Ihr wirklich der Bote seid, den er erwartet.", rewards = "Ihr bekommt:\n\n"},
[1898] = {title = "Die Todespirscher", objective = "Sprecht mit Andron Gant in Undercity.", description = "Das Empfehlungsschreiben sollte Andron überzeugen, dass Ihr der Bote seid, auf den er gewartet hat. Ich kenne Andron, er ist nicht so helle im Kopf, dass er Verdacht schöpfen würde.\n\nLord Varimathras vermutet, dass Andron einer anderen Gruppe Unterstützung zuteil werden ließ. Er möchte wissen, was das für eine Organisation ist, und braucht einen Beweis.\n\nIch möchte, dass Ihr mit Andron sprecht und diese Information bekommt. Ihr findet ihn in seinem Geschäft nahe des Apothekariums.", progress = "Hallo. Kann ich etwas für Euch tun?", completion = "Ah, ja, ich habe Euch erwartet. Ich darf davon ausgehen, dass unsere gemeinsamen Bekannten mit den Informationen, die ich bisher lieferte, zufrieden waren?\n\nVermutlich hat es keinen Sinn, Euch zu fragen. Ich bezweifle, dass sie Euch mit diesem Wissen belasten würden. Warum so viel Vertrauen in den Boten setzen, hm?", rewards = "Ihr bekommt:\n\n"},
[1899] = {title = "Die Todespirscher", objective = "Bringt Astors Geschäftsbuch zu Mennet Carkad im Schurkenviertel von Undercity.", description = "Ihr findet das Geschäftsbuch mit den Informationen, die Eure Auftraggeber suchen, auf dem Bücherregal hinter mir. Überbringt es mit meinen besten Wünschen und sagt ihnen, dass ich es bevorzugen würde, wenn sie Euch schicken, sollte unsere Übereinkunft ihnen so lieb und teuer sein, dass sie sie fortsetzen möchten.", progress = "Erfolg, <Name>?", completion = "Das sind eindeutig mehr Informationen, als ich mir je von Andron erhofft hätte. Lasst sie mich einen Moment studieren, bevor ich Euch Eure nächste Aufgabe nenne.", rewards = "Ihr bekommt:\n\n"},
[1918] = {title = "Das beschmutzte Element", objective = "Bringt die beschmutzte Wasserkugel zu Mastok Wrilehiss im Splintertreeposten in Ashenvale.", description = "Der erschlagene Elementar hat eine intensiv glühende Kugel aus Wasser zurückgelassen. Der Inhalt dieser Kugel ist bestenfalls als abstoßend zu bezeichnen. Es ist eine sichere Annahme, dass, was auch immer das Wasser des Mystralsees beschmutzt hat, höchstwahrscheinlich im Wasser dieser Kugel enthalten ist.\n\nEs ist nicht gerade weit bekannt, wer sich für solch einen Fund interessieren könnte. Vielleicht weiß die Person etwas darüber, die Euch ursprünglich zum See hinausgeschickt hatte - Mastok Wrilehiss im Splintertreeposten.", progress = "Ja, was wollt Ihr?", completion = "Ihr findet eine eklige Kugel aus Wasser und beschließt, sie mir zu bringen? Wer bin ich denn, der Irdene Ring oder was?\n\nMoment mal, das bringt mich auf eine Idee... vielleicht braucht Ihr den Irdenen Ring dafür. Ich meine, wenn es dabei hilft, die Situation am See endgültig zu klären, dann bin ich absolut dafür.\n\nIhr wisst, wer der Irdene Ring ist, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"},
[1919] = {title = "Meldung bei Jennea", objective = "Sprecht in Stormwind mit Jennea Cannon.", description = "Euer Wissen über das Handwerk wächst, <Name>. Seid Ihr jetzt bereit, die wahren Lektionen zu beginnen? Seid Ihr bereit, Euren Platz in dem geheimen Krieg einzunehmen, den wir führen?\n\nWenn ja, sprecht mit Jennea Cannon im Magiersanktum im Magierviertel von Stormwind. Sie hat eine Aufgabe für Euch, die Euer erstes Fenster in die Welt des Unsichtbaren öffnen wird.", progress = nil, completion = "&lt;Name&gt;, ich habe eine Mission für Euch hier im Magierviertel. Hört genau zu, denn es gilt, keine Zeit zu verschwenden.", rewards = "Ihr bekommt:\n\n"},
[1920] = {title = "Untersuchungen im Blauen Eremiten", objective = "Nehmt Euch die Inkantation der Manifestation und die Truhe mit Verwahrungskästen vom Tisch, hinter Jennea Cannon. Bringt 3 gefüllte Verwahrungskästen zu Jennea im Magiersanktum.", description = "Es wurde von einer Störung in der Taverne 'Zum blauen Eremiten' im Magierviertel berichtet. Jetzt wandern seltsame unsichtbare Kreaturen durch die Taverne. Ich fürchte, dort hat sich ein Manariss gebildet.\n\nIch möchte, dass Ihr die Taverne untersucht und diese Kreaturen fangt. Benutzt die Inkantation der Manifestation, um die Kreaturen in der Taverne sichtbar zu machen, überwältigt sie und fangt sie dann mit einem Verwahrungskasten ein. Wenn Ihr genug habt, kommt mit den gefüllten Kästen, den leeren Kästen und der Anrufung zu mir zurück.", progress = "Habt Ihr die Kreaturen gefangen, <Name>? Sie müssen untersucht werden, damit wir den Grund für ihr Kommen herausfinden.", completion = "Sehr gut gemacht! Ich werde diese Kreaturen studieren und mit Geschick und Glück herausfinden, wie sie in unsere Welt gelangen konnten.\n\nEuer Wert für die Gesellschaft der &lt;Klasse&gt; wächst, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[1921] = {title = "Materialsammlung", objective = "Bringt 10 Leinentücher und 6 aufgeladene Rissedelsteine zu Wynne Larson in Stormwind.", description = "Ihr habt Euren Magierkollegen gut gedient, jetzt wird es Zeit, die Hexerrobe anzuziehen. Wynne Larson kann Eure Robe nähen, aber Ihr müsst ihr die erforderlichen Materialien bringen. \n\nEure Robe wird aus Leinen bestehen, das leicht zu beschaffen ist, aber Ihr müsst auch aufgeladene Rissedelsteine finden, die nur in der Silberbachmine vom Loch Modan zu finden sind, wo die Minenarbeiterliga der Zwerge sie in Kisten zurückgelassen hat.\n\nBeschafft das Leinen und die Edelsteine und bringt sie zu Wynne Larson in das Konfektionsgeschäft Larson im Magierviertel.", progress = "Hallo, <Name>. Jennea sagte mir, dass Ihr kommt. Habt Ihr etwas für mich?", completion = "Ja, das sind großartige Leinentücher. Daraus kann ich eine prima Robe machen. Und sobald die Rissedelsteine hineingewoben sind, haben wir ein Gewand, das eines Magiers würdig ist!", rewards = "Ihr bekommt:\n\n"},
[1938] = {title = "Urs Abhandlung über Schattenmagie", objective = "Bringt 'Urs Abhandlung über Schattenmagie' zu Zaubermeister Andromath in Stormwind.", description = "Vor langer Zeit studierten drei Magier in diesem Turm, bis einer den dunklen Künsten verfiel. Man bedrängte ihn, von dieser bösen Magie zu lassen, aber er konnte nicht widerstehen. Und so wurde er verbannt.\n\nDas neue Domizil des gefallenen Magiers ist der Turm von Ilgalar im Rotkammgebirge. Er hat ein mächtiges Buch dorthin mitgenommen -'Urs Abhandlung über Schattenmagie'.\n\nWir, die Magier von Stormwind, möchten dieses Buch zurück. Begebt Euch in den Turm von Ilgalar, sucht den Folianten in seiner Bibliothek und bringt ihn mir.", progress = "Habt Ihr das Buch, <Name>? Seine Geheimnisse sind nicht für die Ungeübten bestimmt, das Studium seines Inhalts kann zu Verdammnis und Ruin führen.", completion = "Ich hatte befürchtet, dass Morganth das Buch anderswo versteckt oder einen Weg gefunden haben könnte, es zu öffnen und den Inhalt zu lesen.\n\nEin Glück, dass ihm das nicht gelang und die Siegel, mit denen wir 'Urs Abhandlung über Schattenmagie' sicherten, unversehrt sind.", rewards = "Ihr bekommt:\n\n"},
[1939] = {title = "Zaubermeister Andromath", objective = "Sprecht mit Zaubermeister Andromath.", description = "Der Zaubermeister Andromath wünscht Euch zu sprechen, <Name>. Er ist oben im Magiersanktum im Magierviertel von Stormwind.\n\nEs wäre klug, mit ihm zu sprechen, denn Andromath ist einer der mächtigsten Magier, die nicht in Dalaran eingesperrt sind. Ein Rat von ihm ist in jedem Fall ein guter Rat.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Ich freue mich, Euch zu sehen, und hoffe, Ihr habt Zeit, den Worten eines alten Mannes zu lauschen...", rewards = "Ihr bekommt:\n\n"},
[1940] = {title = "Makellose Spinnenseide", objective = "Bringt 8 Rollen makelloser Spinnenseide zu Wynne Larson in Stormwind.", description = "Eure Treue ist unerschütterlich, <Name>. Ich glaube, es ist an der Zeit, dass Ihr ein besseres Kleidungsstück bekommt, das einem geschickten Magier von Eurem Rang angemessener ist. Wenn Ihr die erforderlichen Materialien sammeln könnt, werde ich veranlassen, dass die Robe angefertigt wird.\n\nIhr müsst in den Dämmerwald und Aaskrabblerspinnen jagen. Extrahiert ihre Seide, aber nur die feinste und makelloseste. Wenn Ihr genug davon habt, bringt sie zu Wynne Larson ins Konfektionsgeschäft Larson hier im Magierviertel. Sie wird Eure Robe anfertigen.", progress = "Ah, ja. Die <Klasse> im Magiersanktum sagten, dass Ihr mit mir sprechen wollt. Habt Ihr die benötigte Seide?", completion = "Das sind herrliche Exemplare. Ich mach mich gleich an die Arbeit!", rewards = "Ihr bekommt:\n\n"},
[1941] = {title = "Managewirkte Robe", objective = "Hier ist Eure Robe. Er ist eine meiner besten bisher! Tragt sie voller Stolz, und wenn die Leute Euch fragen... sagt ihnen, Ihr habt sie vom Konfektionsgeschäft Larson.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nManagewirkte Robe"},
[1942] = {title = "Astralknotengewand", objective = "Euer Gewand ist fertig! Die Seide, die Ihr mir gebracht hattet, war so hübsch... es stört Euch doch nicht, dass ich es etwas kürzer gemacht habe, damit noch etwas Seide für mich übrig bleibt, oder?\n\nDas war nur ein Witz. Das Gewand wird sitzen wie angegossen und es eignet sich gleichermaßen gut, um damit in Abenteuer zu ziehen oder zu einem Empfang zu gehen. Viel Spaß damit!", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAstralknotenrobeAstralknotenbluse\n\nIhr bekommt außerdem:\n\n"},
[1943] = {title = "Gespräch mit Deino", objective = "Sprecht mit Deino.", description = "Die Trollmagierin Deino bedarf Eurer Unterstützung, <Name>. Sie residiert in Orgrimmar im Dunkeldornen-Lodge.", progress = nil, completion = "Gut, Ihr seid gekommen. Meine Aufgabe ist nicht leicht, aber für die Gesellschaft der &lt;Klasse&gt; von entscheidender Bedeutung. Wenn Ihr mich unterstützt, soll es Euer Schaden nicht sein.", rewards = "Ihr bekommt:\n\n"},
[1944] = {title = "Wasser von Xavian", objective = "Bringt die Probe des Wassers von Xavian zu Deino in Orgrimmar.", description = "Die legendäre Stadt Xavian liegt tief im östlichen Ashenvale. Die Geschichten über ihr Wissen aus längst vergangener Zeit sind den Gebildeten wohl bekannt. Man sagt, die Wasser von Xavian bergen enorme magische Kräfte.\n\nBringt mir eine Probe dieses Wassers direkt von der Quelle.\n\nNehmt dieses Fläschchen und reist nach Xavian. Füllt Wasser am höchsten Wasserfall ab und kehrt zu mir zurück. Aber seid vorsichtig in der uralten Stadt - heute hausen Satyrn in den Ruinen, die gar nicht mögen, wenn sich Magier in ihre Angelegenheiten einmischen.", progress = "Ich sehe mit Freuden, dass Ihr mit heiler Haut zurückgekehrt seid, <Name>. Habt Ihr die Wasserprobe? Ich kann es kaum erwarten, ihre Eigenschaften zu studieren.", completion = "Ah, sehr gut. Die Satyrn von Xavian haben Euch doch hoffentlich nicht allzu viele Schwierigkeiten gemacht?\n\nDanke, &lt;Name&gt;. Ich werde diese Wasserprobe aus Xavian unverzüglich untersuchen.", rewards = "Ihr bekommt:\n\n"},
[1945] = {title = "Lachende Schwestern", objective = "Bringt 12 Haarlocken der lachenden Schwestern zu Kil'hala in Crossroads.", description = "Als Dank für Eure Dienste habe ich veranlasst, dass Euch neue Roben angefertigt werden, sofern Ihr die erforderlichen Materialien beschaffen könnt...\n\nFür diese Roben müsst Ihr nach Ashenvale zurückkehren und Locken vom Haar der lachenden Schwestern beschaffen - Dryaden, die sich in der Nähe des Raynewoodes tummeln.\n\nWenn Ihr das Haar habt, bringt es zu Kil'hala, einem Trollschneider in Crossroads im Brachland. Er wird Euch erwarten und Eure Roben zuschneiden.", progress = "Seid gegrüßt, <Name>. Deino sagte, Ihr würdet kommen und die Haare der lachenden Schwestern bringen. Habt Ihr sie?", completion = "Ah, aus diesem Haar lässt sich eine edle Robe wirken, &lt;Name&gt;. Leider mussten die lachenden Schwestern dafür sterben, aber ich fürchte, freiwillig hätten sie sich nie davon getrennt.\n\nEin Verlust, aber kein sehr großer.", rewards = "Ihr bekommt:\n\n"},
[1946] = {title = "Netherspitzengewand", objective = "Hier habt Ihr Euer Gewand aus Netherspitze, <Name>. Es ist bequem und strapazierfähig und enthält die Magie des Haars der lachenden Schwestern.\n\nViel Spaß damit, und wenn Euch das Gewand zusagt, dann lasst es doch bitte auch Deino wissen. Sie ist eine Magierin, mit der ich es mir nicht verderben möchte...", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nNetherspitzenrobeNetherspitzentunika\n\nIhr bekommt außerdem:\n\n"},
[1947] = {title = "Reise in die Marschen", objective = "Sprecht mit Tabetha.", description = "Jetzt ist es an der Zeit, Euch Euren Magierzauberstab zu verdienen. Um diese Aufgabe zu beginnen, solltet Ihr mit der Menschen-Einsiedlerin Tabetha in den Marschen von Dustwallow sprechen. Ihr findet ihre Hütte tief in den Marschen, westlich von Theramore.\n\nSprecht mit ihr, denn sie verfügt über umfangreiches Wissen. Tabethas Hütte befindet sich westlich von Theramore und direkt nördlich der Stonemaul Ruinen.", progress = nil, completion = "Still! Ich bin an einer komplizierten Prozedur und darf nicht gestört werden!\n\nEinen Moment...", rewards = "Ihr bekommt:\n\n"},
[1948] = {title = "Gegenstände der Macht", objective = "Bringt 1 Stück Jade und den vom Blitz aufgeladenen Dornbusch zu Tabetha in den Marschen von Dustwallow.", description = "Es ist nicht leicht, einen Magierzauberstab anzufertigen. Es sind rare Substanzen erforderlich und ein Gefäß muss gemacht werden, das große Mengen magischer Energie speichern kann. Ihr müsst diese Sachen sammeln und mir bringen.\n\nIch habe auf dieses Pergament geschrieben, was Ihr braucht und wie Ihr es bekommt. Bringt mir exakt das, was auf der Liste steht und folgt meinen schriftlichen Anweisungen auf den Buchstaben genau, denn wenn Ihr das nicht macht, geht bei der Herstellung Eures Zauberstabes vielleicht etwas ... schief.", progress = "Hallo, <Name>. Habt Ihr die Gegenstände, die ich benötige?", completion = "Aha! Ihr habt die Jade und den Dornbusch! Gut gemacht!\n\nSehe ich da Rauch aus Euren Ohren aufsteigen? Vielleicht seid Ihr zu nahe rangekommen, als der Blitzschlag in die Totemstecken eingeschlagen hat, aber keine Bange. Vom Blitzschlag getroffen zu werden bringt Glück!", rewards = "Ihr bekommt:\n\n"},
[1949] = {title = "Verborgene Geheimnisse", objective = "Sprecht mit Magus Tirth in der schimmernden Ebene.", description = "Um Euren Zauberstab herzustellen, muss ich einige wichtige Stellen in einem bestimmten Buch lesen. Dieses Buch wurde von dem Magus Tirth geschrieben und heißt 'Rituale der Macht'.\n\nIch besitze kein Exemplar dieses Buchs und es ist in keiner der großen Bibliotheken der Welt zu finden. Daher müsst Ihr mit Tirth sprechen und es von ihm bekommen.\n\nViel Glück. Tirth war ein großer Magier und Gelehrter, aber heute verbringt er seine Zeit bei den Gnomen- und Goblinrennen auf der schimmernden Ebene und trinkt und spielt.", progress = nil, completion = "Was? Sprecht lauter! Diese alten Ohren sind nicht mehr das, was sie mal waren.\n\nIch hoffe, Ihr habt einen Becher frisches Bier oder einen heißen Tipp für das nächste Rennen! Wenn nicht, trollt Ihr Euch besser... denn ich habe einen Zauberstab der Verwandlung, den ich sonst geneigt wäre, an Euch auszuprobieren!", rewards = "Ihr bekommt:\n\n"},
[1950] = {title = "Der Knüller schlechthin", objective = "Bringt den Satz für Tirths Geldkassette in Erfahrung und kehrt zu Tirth zurück.", description = "Ich kann Euch mit dem Buch helfen, doch vorher müsst Ihr mir helfen!\n\nDer Foliant, den Ihr sucht, befindet sich in meiner magisch versiegelten Geldkassette. Um sie zu öffnen, muss ein bestimmter Satz gesprochen werden, aber ich kann mich nicht mehr an ihn erinnern! Normalerweise merkt sich mein Assistent so etwas, aber der ist unauffindbar.\n\nWenn Ihr mein Buch möchtet, sucht meinen Lehrling! Fragt auf der Rennbahn - wenn Ihr Glück habt, hat ihn jemand gesehen. Schleppt ihn entweder hierher oder entlockt ihm wenigstens meinen magischen Satz, damit wir die Kassette aufbekommen!", progress = "Worauf wartet Ihr? Ich brauche meinen magischen Satz!", completion = "Ah, jetzt erinnere ich mich...\n\nIch hatte den kleinen Fluch vergessen, mit dem ich Johnson belegt hatte. Ich kann mich nicht erinnern, warum ich das gemacht habe, aber gewiss geschah es ihm recht, dem kleinen Tunichtgut!", rewards = "Ihr bekommt:\n\n"},
[1951] = {title = "Rituale der Macht", objective = "Bringt das Buch 'Rituale der Macht' zu Tabetha in den Marschen von Dustwallow.", description = "Hm, wenn ich so darüber nachdenke, ich habe mein Buch nicht! Wisst Ihr, ich hatte Spielschulden, und um sie zu bezahlen, verkaufte ich das letzte Exemplar von 'Rituale der Macht' an ein Mitglied der Kleriker...\n\nEin Mitglied der Scharlachroten Bruderschaft. Er muss es zur Bibliothek im Scharlachroten Kloster in Tirisfal gebracht haben!\n\nWenn Ihr das Buch wollt, müsst Ihr in das Kloster gehen und es suchen. Und entschuldigt den ganzen Ärger. Ich bin neuerdings nicht mehr ich selbst...", progress = "Seid gegrüßt, <Name>. Und habt Ihr das Buch 'Rituale der Macht' gefunden?", completion = "Das ist es! Genau das brauche ich, um das Ritual für die Herstellung Eures Zauberstabs vorzubereiten. Ich hoffe, es war nicht allzu schwer zu finden...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1952] = {title = "Der Zauberstab des Magiers", objective = "Sprecht nach ihrem Ritual mit Tabetha.", description = "Ich werde jetzt die Zauberstäbe machen.", progress = nil, completion = "Hier sind die Zauberstäbe, die ich hergestellt habe. Sucht Euch einen aus!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZauberstab des EisfurorsZauberstab der NetherkraftZauberstab des Wutfeuers\n\nIhr bekommt außerdem:\n\n"},
[1953] = {title = "Rückkehr in die Marschen", objective = "Sprecht mit Tabetha.", description = "<Name>, es wird Zeit, dass Ihr mit Tabetha sprecht... der Einsiedlerin in den Marschen von Dustwallow. Sie wird Euch in der Herstellung einer mächtigen Magiergerätschaft unterweisen.\n\nTabethas Hütte liegt tief in den Marschen von Dustwallow, westlich von Theramore.", progress = nil, completion = "Ah, ja. Seid Ihr wegen einer Kugel oder eines Stabs hier, &lt;Name&gt;? Wohlan denn. Ich helfe Euch bei der Konstruktion.\n\nDoch seid gewarnt - der Vorgang ist gefährlich und könnte tödlich für Euch enden.\n\nOder für mich. Für irgendwen könnte er jedenfalls tödlich enden ... \n\nHoffen wir, dass es jemand anderes ist, hm?", rewards = "Ihr bekommt:\n\n"},
[1954] = {title = "Die Höllenkugel", objective = "Bringt eine Höllenkugel zu Tabetha in den Marschen von Dustwallow.", description = "Als ersten Schritt müsst Ihr eine Kugel voll Macht beschaffen. Die Hexenmeister der Burning Blade haben hübsche, hochwertige Kugeln... zu dumm, dass sie Dämonen darin eingebunden haben! Aber das können wir ändern, ja.\n\nGeht nach Desolace und nehmt einem Beschwörer der Burning Blade eine Höllenkugel ab. Beschwörer findet Ihr bei Mannorocs Koven.\n\nKommt zu mir zurück, wenn Ihr die Kugel habt.", progress = "Habt Ihr eine Höllenkugel, <Name>?", completion = "Oh, ist die aber gut! Nein, ich meine nicht \"gut\", wie kühler Saft an einem heißen Tag gut ist.\n\nWenn ich darüber nachdenke, ist das sogar alles andere als gut. Nicht der Saft. Die Kugel!\n\nKonzentriert Euch, &lt;Name&gt;! Ihr müsst konzentriert sein, wenn wir unsere Aufgabe je vollenden sollen!", rewards = "Ihr bekommt:\n\n"},
[1955] = {title = "Die Austreibung", objective = "Tötet den Dämon der Kugel und sprecht dann mit Tabetha.", description = "Jetzt, da wir eine Beschwörerkugel haben, müssen wir den Dämon darin austreiben. Ich kann es machen. Das ist der einfache Teil.\n\nIhr habt die schwere Aufgabe. Ihr müsst den Dämon töten, wenn er draußen ist.\n\nUnd Ihr müsst Euch beeilen. Wenn Ihr zu lange braucht, springt er in die Kugel zurück und wir müssen von vorn anfangen!\n\nAlso macht Euch bereit. Bereitet Eure stärksten Zauber vor, habt Eure Tränke parat und holt einen Freund, wenn Ihr einen habt. Denn das hier wird nicht angenehm.", progress = nil, completion = "Ordentlich gemacht, &lt;Name&gt;! Diese Lektion wird der Dämon nicht so schnell vergessen.\n\nEr wird es sich zweimal überlegen, ehe er seinen hässlichen Kopf noch einmal in diese Welt steckt und nach dem dummen sterblichen Wesen sucht, das ihn besiegt hat. Diesmal wahrscheinlich mit Freunden. Großen, schuppigen Freunden, die nichts lieber machen als Euch in kleine &lt;Volk&gt;-Stücke zu reißen.\n\nIch hab Euch doch keine Angst gemacht, oder ...&lt;Name&gt;?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1956] = {title = "Macht in Uldaman", objective = "Beschafft Euch eine Obsidiankraftquelle und bringt sie in die Marschen von Dustwallow zu Tabetha.", description = "Jetzt, nachdem der Dämon entfernt wurde, müssen wir eine Kraftquelle finden. Leider sind die besten Kraftquellen meistens die ältesten und die, an die man am schwersten rankommt. Ist schon lustig, wie einem das Schicksal manchmal mitspielt, wie?\n\nAlso müsst Ihr nach Uldaman und dort die Obsidianschildwache besiegen. Der Kerl ist groß, er ist zäh und seine Kraftquelle hat ganz schön Pep.\n\nIch wünsche Euch viel Glück, <Name>. Falls Ihr kein Glück haben solltet, tja... dann war es schön, Euch gekannt zu haben.", progress = "Wart Ihr schon in Uldaman, <Name>? Habt Ihr die Obsidianschildwache besiegt?", completion = "Wirklich? Gut gemacht!\n\nIch habe mich mit ein paar Kollegen unterhalten, wir kamen auf Euch zu sprechen und da haben die gesagt: \"Es ist ja allseits bekannt, dass &lt;Name&gt; unter Druck gute Arbeit leistet!\"\n\nAber als ich ihnen erzählt habe, dass ich Euch nach Uldaman geschickt habe, um gegen die Obsidianschildwache anzutreten, da haben die gesagt, ich sei verrückt! Sie haben gesagt: \"Tabetha, du bist verrückt! Nie im Leben wird &lt;Name&gt; mit dieser Schildwache fertig!\"\n\nDa habe ich gesagt: \"Abwarten\", und dann haben die gesagt: \"Ja, abwarten...\"\n\nDenen haben wir es aber gezeigt, was?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[1957] = {title = "Manawogen", objective = "Vernichtet 12 Manawogen innerhalb des Zeitlimits.", description = "Wir sind fast fertig, aber dieser letzte Schritt ist der gefährlichste, <Name>.\n\nIch habe die leere Beschwörerkugel und bin bereit, sie zu ermächtigen. Das machen wir, indem wir die Energie eines Manarisses anzapfen. Ich wirke einen Zauber, der vorübergehend einen Riss auftut, aus dem Kreaturen, Manawogen, herauskommen. Ihr müsst die Manawogen vernichten, damit ihre Macht freigesetzt wird, die ich dann einsammle.\n\nZerschlagt genug Manawogen, bevor sich der Riss schließt, und ich versiegle ihre gesammelte Energie in Eurer Kugel.", progress = nil, completion = "Ihr habt es geschafft! Ich habe keinen Augenblick an Euch gezweifelt! Na gut, vielleicht einen klitzekleinen Augenblick... aber an sich hegte ich wenig Zweifel.\n\nEhrlich.", rewards = "Ihr bekommt:\n\n"},
[1958] = {title = "Himmlische Macht", objective = "Ihr solltet stolz auf Euch sein, <Name>. Viele <Klasse> fielen den Kreaturen zum Opfer, denen Ihr getrotzt habt.\n\nDie Himmelskugel ist fertig. Wenn Ihr möchtet, kann ich sie oben an einem Stab anbringen. Es liegt bei Euch. Mir persönlich wäre die Kugel allein ja lieber, aber wer bin ich, mir ein Urteil zu erlauben?", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHimmlische KugelHimmlischer Stock\n\nIhr bekommt außerdem:\n\n"},
[1959] = {title = "Meldung bei Anastasia", objective = "Sprecht mit Anastasia Hartwell.", description = "Die Magier von Undercity haben eine magische Störung in der Stadt bemerkt und die Magier der Horde um Untersuchung gebeten.\n\nAnastasia Hartwell kann Euch mehr sagen. Sprecht mit Ihr im Magieviertel in Undercity.", progress = nil, completion = "Es stimmt. In unserer Stadt wurde eine magische Störung entdeckt. Wir sind noch nicht sicher, woher sie kommt oder ob sie schädlich oder nützlich ist. Wir müssen mehr Informationen sammeln...\n\nUnd damit, &lt;Name&gt;, sind wir bei Eurer Aufgabe.", rewards = "Ihr bekommt:\n\n"},
[1960] = {title = "Untersuchungen im Alchimistenladen", objective = "Besorgt eine Inkantation der Manifestation und eine Truhe mit Verwahrungskästen von Anastasia Hartwell. Bringt 3 gefüllte Verwahrungskästen, die Truhe mit Verwahrungskästen sowie die Inkantation der Manifestation zu Anastasia in Undercity.", description = "Algernons Alchimistenladen im Apothekarium ist das Zentrum einer seltsamen Störung. Unsichtbare, aus reiner Magie bestehende Kreaturen halten sich in dem Laden auf - dafür muss es einen Grund geben, und den müssen wir herausfinden!\n\nUntersucht die Störung und fangt diese Kreaturen. Nehmt Euch von dort hinten eine Truhe mit Kästen und eine Rolle. Benutzt im Laden die Rolle, um die Kreaturen sichtbar zu machen, überwältigt sie mit Euren Zaubern und fangt sie dann mit einem Kasten ein. Kommt mit den gefüllten Kästen, den leeren Kästen und der Anrufung zu mir zurück.", progress = "Habt Ihr die Störung untersucht, <Name>? Habt Ihr die Kreaturen gefangen?", completion = "Sehr gut, &lt;Name&gt;. Unsere größten Denker werden die Kreaturen in diesen Verwahrungskästen studieren und den Grund für ihre Anwesenheit in Undercity herausfinden.\n\nWenn ihre Anwesenheit auf einem Riss im natürlichen Fluss der Magie beruht, müssen wir herausfinden, ob es ein zufälliger Riss war. Wenn er nicht zufällig, sondern ein Angriff einer magischen Macht ist, müssen wir uns gegen zukünftige, gravierende Störungen wappnen.", rewards = "Ihr bekommt:\n\n"},
[1961] = {title = "Materialsammlung", objective = "Bringt 10 Leinentücher und 6 Manaedelsteine aus Dalaran zu Josef Gregorian.", description = "Jetzt ist es Zeit, Eure erste Magierrobe anzulegen, <Name>. Sie ist ein Zeichen Eures Ranges und ein Zeugnis für Euren Wert.\n\nUm die Robe zu bekommen, müsst Ihr Manaedelsteine von den Magiern von Dalaran im Silberwald sammeln. Ihre Überzeugungen ähneln den unseren, daher ist es ein wenig geschmacklos, sie zu töten, aber wenn sie keine Kraft haben, uns Widerstand zu leisten, verdienen sie es nicht, zu leben.\n\nBringt die Edelsteine und das Leinen zu Josef Gregorian in der Schneiderei im Magieviertel.", progress = "Anastasia sagte, Ihr würdet zu mir kommen. Ich bin bereit, Eure Robe zu schneidern. Habt Ihr die Edelsteine und das Leinen?", completion = "Das ist ausgezeichnetes Material. Mir fehlt das Talent, die Qualität dieser Manaedelsteine abzuschätzen, aber wir werden bald wissen, ob sie die Macht besitzen, die für die Herstellung von Roben des Zauberfeuers erforderlich ist...", rewards = "Ihr bekommt:\n\n"},
[1962] = {title = "Roben des Zauberfeuers", objective = "Hier sind Eure Roben, <Name>. Tragt sie mit Bedacht.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRoben des geringen Zauberfeuers"},
[1963] = {title = "Die Shattered-Hand", objective = "Tötet Tazan und bringt seinen Ranzen zu Therzok in der Kluft der Schatten in Orgrimmar.", description = "Die Methoden des Kriegshäuptlings sind zu zimperlich. Er wagt nicht, die Macht der Horde zu entfesseln. Einst waren wir stärker, allesamt mächtige Eroberer. Diesen Stolz müssen wir zurückerlangen, und der Klan der Shattered-Hand wird dies bewerkstelligen.\n\nWir sammeln Kraft aus den Schatten und schlagen im Verborgenen gegen exponierte Feinde zu. Eine Aufgabe müsst Ihr für mich erledigen, um Euren Wert zu beweisen.\n\nDer Troll Tazan treibt Handel mit den Piraten bei Ratchet. Er hat Informationen, die ich haben muss. Tötet ihn und bringt mir seinen Ranzen.", progress = "Ein Narr, der glaubt, ein Sturmlauf mit erhobener Axt sei gefährlicher als ein Messer im Dunkeln.", completion = "Hm, zwar höre ich erfreut, dass Tazan nicht mehr unter uns weilt, aber ein verschlossener Ranzen nützt uns nichts. Wir brauchen die darin enthaltenen Informationen.\n\nDas sollte eine würdige zweite Herausforderung für einen sein, der sich der Shattered-Hand anschließen möchte.", rewards = "Ihr bekommt:\n\n"},
[1978] = {title = "Die Todespirscher", objective = "Bringt Androns Geschäftsbuch zu Varimathras in der Halle der dunklen Fürstin in Undercity.", description = "Das Syndikat? Darauf wäre ich nie gekommen. Offenbar sind die Lords von Alterac in den Jahren seit ihrem Verrat tief gesunken.\n\nLord Varimathras wird es mit Freuden hören, und da wir diese Entdeckung weitgehend Euch verdanken, ist es nur recht und billig, dass Ihr ihm die Nachricht überbringt.\n\nAh, und wie konnte ich das vergessen?\n\nWillkommen bei den Todespirschern.", progress = "Ja?", completion = "Hmm, das ist interessant. Die Todespirscher haben ihre Pflicht bei der Erledigung dieser Aufgabe meisterlich erfüllt.\n\nSoweit ich informiert bin, verdient Ihr ebenfalls Lob für Eure Leistung. Ich hoffe, dass das bei Euch zur Gewohnheit wird, &lt;Name&gt;, meine Todespirscher haben immer Verwendung für gute Männer.", rewards = "Ihr bekommt:\n\nKlinge der Geschicklichkeit"},
[1998] = {title = "Fenwick Thatros", objective = "Tötet Fenwick Thatros und bringt seinen Kopf zu Mennet Carkad im Schurkenviertel von Undercity.", description = "Lord Varimathras hat mir soeben in einer Botschaft über eine Gefahr für die Verlassenen berichtet, die unverzüglich ausgeschaltet werden muss. Sein Name ist Fenwick Thatros. Lord Varimathras glaubt, dass er einer der Anführer der Untoten sei, die sich im Silberwald angesiedelt haben.\n\nMir kam sofort Euer Name in den Sinn, <Name>. Ich habe Vertrauen in Eure Fähigkeiten und glaube, Ihr werdet diese Mission fehlerfrei abschließen.\n\nDie letzte Meldung von den Todespirschern im Silberwald deutet darauf hin, dass Thatros nahe der verfallenen Fähre am Lordameresee zu finden ist.", progress = "Ich habe größtes Vertrauen darin, dass Ihr diesen Dienst für Lord Varimathras erledigt.", completion = "Ihr habt Eure Sache gut gemacht, &lt;Name&gt;. Mir fällt ein, dass Ihr den Todespirschern viele Dienste geleistet und damit Euren Wert bewiesen habt. Vielleicht ist es an der Zeit, dass wir Eure Ausbildung in den Schattenkünsten fortsetzen.", rewards = "Ihr bekommt:\n\n"},
[1999] = {title = "Werkzeuge des Handwerks", objective = "Sucht den Statusbericht von Dalaran und bringt ihn zu Mennet Carkad im Schurkenviertel von Undercity.", description = "Die Hexer der Kirin Tor bei Ambermill haben wichtige Dokumente eingelagert, die den aktuellen Zustand von Dalaran betreffen. Das wissen wir durch die Aussagen eines unserer Gefangenen. Lord Varimathras hat die Aufgabe, diese zu beschaffen, den Todespirschern übertragen.\n\nDas ist eine Arbeit für Euch, <Name>. Ihr braucht allerdings etwas Ausrüstung und Kenntnisse im Schlossknacken. Sprecht mit Estelle Gendry, unserer Lageristin, und bittet sie um ein Werkzeugset, bevor Ihr aufbrecht.", progress = "Habt Ihr die Dokumente gefunden, <Name>?", completion = "Sehr gut, &lt;Name&gt;! Ihr habt die hohe Kunst des Schlossknackens schnell gelernt... schneller als ich je für möglich gehalten hätte.\n\nMein Vertrauen in Euch war also nicht unbegründet. Glaubt mir, Jungchen, ich sehe eine große Zukunft in diesem Metier für Euch.", rewards = "Ihr bekommt:\n\n"},
[2018] = {title = "Rokars Test", objective = "Tötet Vorarbeiter Glibby und bringt seine Pfeife zu Rokar Klingenschatten in Durotar.", description = "Ah, also schickt mir Therzok jetzt schon seine Studenten-Grünschnäbel, hm? Ja, ich denke, ich kann Euch das eine oder andere beibringen. Nicht, dass mir viel an Eurer Sache gelegen wäre, aber ich möchte mein Gewissen nicht damit belasten, dass ich Euch in den Tod schicke.\n\nAber zuerst müsst Ihr Euch als würdig erweisen.\n\nIch sage es offen und ehrlich, <Name>. Ich mag diese Venture Company nicht besonders. Dieses Land erinnert mich an Draenor und mir gefällt die Vorstellung nicht, dass diese Goblins es zerstören. Wenn ihr Vorarbeiter am Schlickmoor getötet wird, wird das Unternehmen lahm gelegt sein.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[2019] = {title = "Werkzeuge des Handwerks", objective = "Kehrt zu Therzok in der Kluft der Schatten in Orgrimmar zurück.\n\nBereitgestellter Gegenstand: \n", description = "Da habt Ihr sie, <Name>. Sie sollten Euch nützlich sein. Ich habe sie eigenhändig gefertigt und schwöre, Ihr findet keine besseren.\n\nAber sagt mir nichts von Euren Plänen. Therzoks Ränke interessieren mich nicht, ich möchte nur in Frieden meinen Ruhestand genießen.\n\nSolltet Ihr je ein anderes Werkzeugset brauchen, kommt zu mir und ich fertige Euch ein neues an. Aber geht sorgfältig damit um!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[2038] = {title = "Bingles' verschwundene Werkzeuge", objective = "Sucht Bingles' Werkzeuge und bringt sie ihm zurück. Es sind:\n\nBingles' Schraubenschlüssel, Bingles' Schraubendreher, Bingles' Hammer und Bingles' Sprengstofftube.", description = "Als wäre es nicht schlimm genug gewesen, in den Loch zu stürzen, haben mich auch noch Troggs von der nahe gelegenen Insel angegriffen und mir mein Werkzeug und meinen speziellen Sprengstoff \"Superspreng\" aus der Blastenheimer-Sprengstoffstube gestohlen. Ohne Gyrokopter und Sprengstoff hat die Bewegung keine Chance!\n\nBeschafft mir meine Werkzeuge wieder und findet mein Superspreng aus der Sprengstoffstube, <Name>. Für Gnomeregan!", progress = "<Name>! Wo sind meine Sachen?!", completion = "Ihr habt der Bewegung einen großen Dienst erwiesen, &lt;Name&gt;. Die Troggs und Lepragnome, die Gnomeregan verschandeln, werden bald die Wucht eines Gnomenluftangriffs spüren!", rewards = "Ihr bekommt:\n\nBingles Flieger-Handschuhe"},
[2039] = {title = "Sucht Bingles", objective = "Sucht Bingles Blastenheimer am Loch Modan.", description = "Wir haben den Kontakt mit Bingles verloren! Er wurde zu einer Aufklärungsmission über Gnomeregan geschickt und hat sich seit mehr als einer Woche nicht mehr gemeldet. Ich weiß, er hat sich selbst in die Luft gejagt.\n\nZuletzt sah man ihn über dem Loch fliegen. Vielleicht könnt Ihr dies untersuchen, <Name>?", progress = nil, completion = "Gnoarn hat also kein Vertrauen in meine Aufklärungsfähigkeiten? Warum nur...\n\nUnwichtig, ich brauche Eure Unterstützung! Nee! Die Bewegung braucht Eure Unterstützung!", rewards = "Ihr bekommt:\n\n"},
[2040] = {title = "Unterirdischer Angriff", objective = "Holt das Gnoam-Sprecklesprocket aus den Todesminen und bringt es Shoni der Schtillen in Stormwind.", description = "Gnomeregan ist diesen elendigen Troggs in die Hände gefallen! Die Situation ist ernst, aber vielleicht könnt Ihr helfen, <Name>.\n\nTief in den Todesminen gibt es einen funktionierenden Goblinschredder. Sucht diesen Schredder und bringt die intakte Energieversorgung mit. Mit der Energieversorgung des Schredders können wir unseren gyrobohrmatischen Exkavationatoren die erforderliche Energie zuführen, um durch die felsigen, unterirdischen Grenzen von Gnomeregan zu brechen und einem Gnomenangriff den Weg zu ebnen!", progress = "Habt Ihr das Gnoam-Sprecklesprocket gefunden, <Name>?", completion = "Gut gemacht, &lt;Name&gt;. Dank Euch ist Gnomeregan dem Tag der Befreiung einen Schritt näher!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPolarstulpenDüsterer Zauberstab\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[2041] = {title = "Sprecht mit Shoni", objective = "Sprecht mit Shoni der Schtillen in Stormwind.", description = "Vielleicht... Vielleicht könnt Ihr uns im Kampf um Gnomeregan unterstützen.\n\nIn Stormwind findet Ihr den Kommandant unserer Untergrund-Kampftruppe, Shoni die Schtille. Shoni braucht Hilfe für ihre gyrobohrmatischen Exkavationatoren.\n\nIhr findet sie wahrscheinlich bei den Zwergen in Stormwind.\n\nViel Glück, <Name>.", progress = nil, completion = "Bringt Ihr Kunde vom Zentralkommando?", rewards = "Ihr bekommt:\n\n"},
[2078] = {title = "Gyromasts Rache", objective = "Sucht Gelkaks Ersten Maat, den Dreschonator 4100, und führt ihn zu Gelkak zurück.", description = "Landratte, Ihr müsst meinen Ersten Maat finden.\n\nNehmt diesen Schlüssel, steckt ihn in sein' Gulliver und schafft ihn her, dasser seim Käpt’n dient.\n\nDiese Murlocs und ihr Häuptling werden nich so froh sein, wenn der Erste Maat sie zu fassen kriegt!", progress = "Wo is mein Erster Maat, <Name>? Mast und Schotbruch, beeilt Euch gefälligst!", completion = "Harrr... Ihr habt gezeigt, dass Ihr 'n richtiger alter Seebär seid, Landratte.\n\nWenn Ihr so weitermacht, befördert Euch der Käpt’n bald zum Deckschrubber...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nElixier der Wasseratmung"},
[2098] = {title = "Gyromasts Rettung", objective = "Sucht die drei Stücke von Gelkaks Schlüssel und bringt sie Gelkak Gyromast.", description = "Das Piratenleben ist eines der Schwersten, Landratte. Es dreht sich nicht nur um Plündern und Saufen! Wehe, mein Schiff sank vor der Küste! Schuld daran sind diese dreisten Dreschadons.\n\nIch muss mein' Ersten Maat funktionstüchtig wiederham!\n\nAls ich an Land gespült wurde, zerbrach der Schlüssel für meinen Ersten Maat an den Felsen und wurde von den Biesterchen von Dunkelküste geraubt. Aus den Augenwinkeln sah ich tobende Kriecher, riesige Waldschreiter und Murlocs, die das Wrack durchstöberten...", progress = "Habt Ihr meinen zerbrochenen Schlüssel gefunden, Landratte?", completion = "Potzblitz, Ihr elender Seebär! Ihr habt's geschafft! Bald ist mein Erster Maat wieder funktionstüchtig und wird die Biesterchen das Fürchten lehren!\n\nHrm, habt Ihr meinen Ersten Maat gesehen?", rewards = "Ihr bekommt:\n\n"},
[2118] = {title = "Verseuchtes Land", objective = "Fangt einen lebenden tollwütigen Distelbären und bringt ihn zu Tharnariun.", description = "Eine Erkrankung breitet sich in Dunkelküste aus und befällt Körper und Geist aller, die damit in Kontakt kommen.\n\nDie Distelbären wurden am schwersten von der Seuche getroffen. Die einst edlen Tiere sind jetzt ein Instrument der Zerstörung - tollwütig und rasend. Ich habe möglicherweise ein Heilmittel für dieses Leiden.\n\nGeht mit dieser Falle in den Wald und legt sie auf den Boden. Jeder tollwütige Distelbär, der das Licht kreuzt, wird für kurze Zeit friedfertig. Wenn der Bär erst einmal friedfertig ist, wird er Euch folgen. Führt ihn hierher, <Name>.", progress = nil, completion = "Eure Arbeit hat erst begonnen, &lt;Name&gt;. Seid Ihr bereit für die nächste Aufgabe?", rewards = "Ihr bekommt:\n\n"},
[2138] = {title = "Ausrottung der Infizierten", objective = "Befreit den Wald von 20 tollwütigen Distelbären und kehrt dann zu Tharnariun Treetender in Dunkelküste zurück.", description = "Wie ich befürchtete, das Heilmittel wirkt nicht.\n\nEs stimmt mich traurig, Geschöpfe der Natur zum Tode zu verurteilen, aber die kranken und besudelten Distelbären müssen ausgerottet werden.\n\nKehrt in den Wald zurück und vernichtet 20 tollwütige Distelbären, <Name>. Das wird die Seuche sicher nicht stoppen, aber den Schaden, den die Tiere unserem Wald und seinen Bewohnern zufügen, zumindest für kurze Zeit verringern.", progress = nil, completion = "Ihr habt Auberdine einen großen Dienst erwiesen, &lt;Name&gt;, doch Eure Arbeit ist noch nicht getan.\n\nKommt wieder zu mir, wenn Ihr Euch erholt habt.\n\n... und &lt;Name&gt;, bereitet Geist und Seele auf weiteres Blutvergießen vor.", rewards = "Ihr bekommt:\n\n"},
[2139] = {title = "Tharnariuns Hoffnung", objective = "Sucht und tötet die Höhlenmutter.", description = "Das Überleben unseres Volkes und unserer Länder ist mit bedauerlichen Kosten verbunden, <Name>.\n\nIhr habt das Blut der Diener der Natur vergossen; viele kranke Tiere habt Ihr erledigt. Das Volk von Auberdine steht in Eurer Schuld, denn die Qualen des Waldes sind gelindert - wenn auch nur vorübergehend.\n\nIch habe eine letzte Aufgabe für Euch, doch seid gewarnt, Ihr werdet wieder töten müssen. Dies wird hoffentlich das letzte Mal sein, dass ich Euch rufen muss, <Name>.\n\nIn einer Höhle im Nordosten, nahe Bashal'Aran, haust die Höhlenmutter. Tötet sie.", progress = nil, completion = "Ihr habt tapfer und ehrenhaft für Auberdine gekämpft, &lt;Name&gt;. In unserem vom Krieg gebeutelten Land sind Tod und Verzweiflung an der Tagesordnung. Viele werden der Herausforderung, in unserer neuen Heimat zu leben, nicht gewachsen sein und sich stattdessen in ihren Häusern verbergen oder in die wehrhafteren Länder der Allianz abwandern.\n\nDanke, &lt;Name&gt;. Vielleicht werden wir eines Tages als Kameraden gegen einen neuen Feind antreten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nImmergrünhandschuheWaldhaincape\n\nIhr bekommt außerdem:\n\n"},
[2158] = {title = "Ruhe und Entspannung", objective = "Sprecht im Gasthaus Zur Höhle des Löwen mit Gastwirt Farley.", description = "Jeder Abenteurer sollte ausruhen, wenn ihn die Erschöpfung überkommt - und es gibt keinen besseren Platz für Ruhe und Entspannung als das Gasthaus Zur Höhle des Löwen!\n\nGastwirt Farley, der Inhaber der 'Höhle des Löwen', ist mein bester Freund. Wenn Ihr ihm sagt, dass ich Euch geschickt habe, dann gewährt er Euch vielleicht einen Spezialrabatt auf Essen und Trinken.\n\nDas Gasthaus Zur Höhle des Löwen findet Ihr, wenn Ihr auf der Straße nach Süden reist - Ihr könnt es nicht verfehlen!", progress = nil, completion = "Ruhe und Entspannung für die Müden und Frierenden - das ist unser Leitspruch! Bitte setzt Euch ans Feuer und wärmt Eure müden Knochen.\n\nMöchtet Ihr von unseren erlesenen Speisen und Getränken kosten?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKleiner KürbisErfrischendes Quellwasser\n\nIhr bekommt außerdem:\n\n"},
[2159] = {title = "Dolanaar-Lieferung", objective = "Bringt die Dolanaar-Lieferung zu Gastwirt Keldamyr.", description = "Seid mir gegrüßt, <Klasse>. Könnt Ihr mir helfen? Ich habe ein Päckchen Kräuter, das ich in die Stadt Dolanaar liefern muss. Aber ich habe noch etwas mit den Druiden von Shadowglen zu regeln und kann nicht weg.\n\nKönntet Ihr das Päckchen für mich zustellen? Es muss zu Gastwirt Keldamyr im Gasthaus von Dolanaar. Das liegt an der Straße nach Süden.", progress = "Wie vermag ich Euch dienlich zu sein, junger Freund? Seid Ihr hier, um Euch im Gasthaus auszuruhen? Benötigt Ihr einen Ruhestein?", completion = "Ah, ja, die Lieferung Kräuter aus Shadowglen. Ein Jammer, dass Porthannius nicht selbst kommen konnte, denn wir hätten viel zu besprechen. Dennoch bin ich froh, dass ich die Kräuter habe und dass Ihr gekommen seid.\n\nBitte ruht Euch aus solange Ihr hier seid. Helden müssen Körper und Geist fit halten und Ruhe und Entspannung suchen, wann immer sie können. Vernachlässigt man Ruhe für Körper und Geist, wird man keine Leistung bringen können.\n\nAlso ... ruht Euch aus.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDarnassischer BlauschimmelkäseErfrischendes Quellwasser\n\nIhr bekommt außerdem:\n\n"},
[2160] = {title = "Vorräte für Tannok", objective = "Bringt die Kiste mit Gasthausvorräten zu Tannok Frosthammer in Kharanos.", description = "He! Ihr seht wie ein beherzter Abenteurer aus. Wenn Ihr vorhabt, den Pass zu überqueren, könntet Ihr da wohl ein Päckchen ins Gasthaus von Kharanos bringen?\n\nIhr hattet doch vor, im Gasthaus abzusteigen, nicht? Wenn Ihr den Pass bezwungen habt, werdet Ihr Euch dort ganz bestimmt etwas ausruhen wollen.\n\nWie auch immer, bringt das zu Tannok Frosthammer, dem Gehilfen des Gastwirts. Ich selbst kann nicht über den Pass und es dauert Tage, bis wieder eine Gebirgsjägereskorte vorbeikommt!", progress = "Hallo, Ihr da! Kommt herein, setzt Euch ans Feuer und wärmt Euch mit einem Krug Bier.", completion = "Ah, endlich die Vorräte von Hands! Ich hatte mir schon Sorgen gemacht, seit die Troggs den Pass überrannt haben, hören wir kaum etwas aus Anvilmar.\n\nDanke, dass Ihr mir das gebracht habt, &lt;Name&gt;. Und bitte macht es Euch bequem. Ihr müsst nach der langen Reise müde sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZähes StockfleischErfrischendes Quellwasser\n\nIhr bekommt außerdem:\n\n"},
[2161] = {title = "Die Bürde eines Peons", objective = "Bringt Ukors Bürde zu Gastwirt Grosk in Klingenhügel.", description = "Entschuldigung? Könntet Ihr mir helfen?\n\nIch habe hier eine Ladung Essen. Ich bin die Straße entlanggelaufen und habe Skorpiden und Spinnen und Schlimmerem getrotzt! Ich habe das Essen ins Tal der Prüfungen gebracht, weil ich dachte, sie könnten es brauchen und weil ich gern behilflich bin. Aber sie brauchen kein Essen! Jetzt muss ich es nach Klingenhügel zurückbringen und fürchte mich vor den ganzen Bestien unterwegs...\n\nKönnt Ihr es für mich hinbringen? Ich bin nur ein Peon, Ihr aber seid <ein Held/eine Heldin>. Ihr fürchtet nichts!\n\nBringt es zu Gastwirt Grosk im Gasthaus von Klingenhügel. Danke!", progress = "Willkommen in Klingenhügel!", completion = "Ah, das Essen, das Ukor zum Tal der Prüfungen gebracht hat. Haben sie es nicht gebraucht? Na, vermutlich lassen sie Euch Helden in der Ausbildung gern hungern. Ist gut für den Geist, sagt man!\n\nDanke, dass Ihr das Essen zurückgebracht habt. Ich stelle es wieder in die Regale ... aber lasst mich Euch zuvor eine Erfrischung anbieten!\n\nUnd vergesst nicht, hier im Gasthaus auszuruhen. Als &lt;Klasse&gt; mögt Ihr ja vielleicht tapfer sein und es mit aller Welt aufnehmen, aber wenn Eure Energiereserven knapp sind, werdet Ihr Euch selbst und der Horde nicht viel nützen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZäher Brocken BrotErfrischendes Quellwasser\n\nIhr bekommt außerdem:\n\n"},
[2178] = {title = "Schreitereintopf", objective = "Bringt 5 Stücke Schreiterfleisch zu Alanndarian Nightsonng in Auberdine.", description = "Riecht Ihr dieses köstliche Aroma? Das ist mein Geheimrezept, <Name> - frischer Schreitereintopf. Köstlich!\n\nVielleicht möchtet Ihr das Rezept ja wissen?\n\nBevor ich Euch das Rezept verrate, müsst Ihr beweisen, dass Ihr den Wildtieren gewachsen seid.\n\nIch erwarte nicht, dass Ihr loszieht und eines zähmt und darauf zu mir zurückgeritten kommt, aber wenn Ihr einige Wildtiere töten könnt und mir etwas von ihrem saftigen Fleisch bringt, verrate ich Euch vielleicht das Schreiterrezept.", progress = "Der Topf ist leer und ich habe Hunger! Was hat Euch so lange aufgehalten?", completion = "Phantastisch! Kostet und sagt mir, was Ihr davon haltet, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nRezept: SchreitereintopfSchreitereintopf"},
[2198] = {title = "Die zerrissene Halskette", objective = "Sucht nach dem Erschaffer der zerrissenen Halskette, um etwas über ihren möglichen Wert zu erfahren.", description = "Ihr habt eine befleckte Halskette gefunden, doch unter der Stumpfheit des Metalls lässt sich noch die feine und magische Handarbeit erkennen. Die Halskette ist beschädigt, in ihrer Fassung scheinen drei Edelsteine zu fehlen. Auf der Unterseite der Halskette kann man vage den Stempel des Stadtsiegels von Ironforge erkennen. Unter dem Siegel befinden sich drei winzige eingravierte Buchstaben: \"TdK\".\n\nWenn Ihr etwas über die Halskette in Erfahrung bringen wollt, müsst Ihr herausfinden, woher sie stammt. Vielleicht sind das Siegel und die Initialen ein Anfang ...", progress = "Ihr habt den falschen Gnom erwischt, Kumpel! Da bin ich nie gewesen! Ihr könnt gar nichts beweisen!\n\nMoment mal... Wer seid Ihr? Was, zum... Wo habt Ihr diese Halskette gefunden?", completion = "Ja... Ich bin der Juwelier, der die Halskette hergestellt hat. Aber ich betreibe dieses Geschäft nicht, um Informationen ohne jede Gegenleistung herauszugeben. Informationen sind nämlich nie umsonst. Wenn ich Euch helfen soll, müsst Ihr zuerst MIR helfen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2199] = {title = "Lehren haben ihren Preis", objective = "Bringt fünf Silberbarren zu Talvash del Kissel in Ironforge.", description = "Ich genieße als Juwelier hier in Ironforge ein hohes Ansehen! Oder sagen wir besser: Ich genoss es einmal. Dank der gemeinen Tricks eines Konkurrenten mache ich gerade eine schwere Zeit durch. In dieser Branche bedeutet ein schlechter Ruf das finanzielle Desaster. Und so muss ich feststellen, dass mein guter, wenn auch momentan leicht beschmutzter Name keinen roten Heller mehr wert ist.\n\nIch möchte, dass Ihr mir fünf Silberbarren beschafft, die ich für einen Auftrag brauche - den ersten seit einer Ewigkeit.\n\nBringt mir die fünf Silberbarren, dann beantworte ich Eure Fragen über die Halskette.", progress = "Habt Ihr die fünf Silberbarren, um die ich bat? Ich erzähle Euch die traurige Geschichte dieser Halskette in Eurem Besitz... aber erst, wenn ich diese Barren habe! Helft doch einem armen Gnom, ja?", completion = "Also ICH mag Euch, es ist mir ganz egal, was andere sagen... Nur ein Witz, nur ein Witz! Ganz ehrlich, vielen Dank, lieber Freund.\n\nAlso, die Halskette, die Ihr da habt, ist eine meiner edelsten Kreationen, aber es fehlen drei Edelsteine, mit der magische Macht an sie gebunden werden kann. Ich fertigte sie vor geraumer Zeit für einen Paladin an. Er befand sich auf einem selbst auferlegten Kreuzzug, um die \"böse Verseuchung\" auszumerzen, die eine Ausgrabungsstätte namens Uldaman im Ödland befallen hatte.\n\nAber der Paladin starb in Uldaman und das war erst der Anfang meines Elends.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2200] = {title = "Rückkehr nach Uldaman", objective = "Sucht in Uldaman nach Hinweisen auf den momentanen Zustand von Talvashs Halskette. Der getötete Paladin, den Talvash erwähnte, hatte die Kette zuletzt.\n\nBereitgestellter Gegenstand: \n", description = "Einer meiner Konkurrenten brachte das Gerücht in Umlauf, meine Halskette habe den Paladin verflucht. Und natürlich kauft einem Juwelier niemand verfluchte Gegenstände ab.\n\nIch schlag Euch etwas vor, <Name>: Ihr findet die Edelsteine und ich repariere die Halskette - aber nur, wenn Ihr herumerzählt, dass ich KEINE verfluchten Gegenstände herstelle!\n\nFangt am besten an, in Uldaman nach Hinweisen zu suchen; vielleicht liegt der Paladin dort begraben, von ihm wissen wir, dass er die Kette als Letzter hatte! Wenn Ihr die Edelsteine gefunden habt, solltet Ihr dies hier benutzen; dadurch könnt Ihr mit mir in Ironforge Kontakt aufnehmen.", progress = nil, completion = "Beim Lesen des Tagebuchs stellt Ihr fest, dass der Paladin nach großen Mühen den Verbleib aller drei fehlenden Edelsteine der Halskette herausgefunden hatte.\n\nDen Rubin versteckten die Zwerge der Schattenschmiede in ihrer Bastion, als sie mit den Troggs um die Vorherrschaft in Uldaman kämpften.\n\nDen Topas ließen die Troggs verschwinden, und zwar in einer Urne in der Nähe einiger für Uldaman sehr außergewöhnlichen Bewohner: Zwerge der Allianz!\n\nUnd den Saphir schließlich eignete sich der Troggälteste an.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2201] = {title = "Suche nach den Edelsteinen", objective = "Findet den Rubin, den Saphir und den Topas, die in ganz Uldaman verstreut sind. Wenn Ihr sie habt, wendet Euch aus der Ferne an Talvash del Kissel, indem Ihr die Wahrsagephiole nutzt, die er Euch zuvor gegeben hat.\n\nAus dem Tagebuch, wisst Ihr...\n* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.\n* Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz.\n\n* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen.", description = "Das Tagebuch des Paladins liefert Euch die vielleicht einzigen Hinweise darauf, wo sich die Edelsteine aus der Halskette befinden könnten. Wenn der Paladin alles korrekt aufgezeichnet hat, dann müsst Ihr Euch um die Zwerge der Schattenschmiede und die Troggs kümmern, die um die Vorherrschaft über die Grabungsstätte konkurrieren.\n\nMit diesem Wissen bewaffnet, könnt Ihr Eure Suche nach den Edelsteinen jetzt ernsthaft beginnen. Sobald Ihr Euch alle Edelsteine angeeignet habt, solltet Ihr gemäß seinen Anweisungen Talvash in Ironforge mit Hilfe der Wahrsagephiole informieren", progress = "Talvashs Bild nimmt in dem Wasser der Wahrsageschale Kontur an.\n\n\"Hey, Ihr lebt noch! Habt Ihr die Edelsteine gefunden? Könnt Ihr wirklich meinen guten Ruf retten, so wie ich das erhofft habe? Bitte sagt mir, dass Ihr keine Ladung der Phiole verbraucht habt, um mal schnell hallo zu sagen. Diese Dinge sind nicht billig und ich pfeife finanziell gesehen jetzt schon auf dem letzten Loch.\"", completion = "Ja, das sind tatsächlich die drei Edelsteine. Sehr gut! Leider ist Eure Arbeit aber damit noch nicht ganz getan.\n\nNein, ich versuche nicht, Euch über den Tisch zu ziehen. Typisch &lt;Klasse&gt;! Hier geht es um die Herstellung magischen Schmucks - und zwar Schmuck von einer Güte, wie Talvash del Kissel ihn herstellt! Da braucht man schon eine starke Kraftquelle, um dem Ganzen den nötigen Bumms zu geben. Und diese Halskette hat absolut keinen Bumms mehr.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2202] = {title = "Reagenzsuche in Uldaman", objective = "Bringt 12 magenta Funguskappen nach Kargath zu Jarkal Mossmeld.", description = "Ich habe von einer neu entdeckten Pflanze gehört, den magenta Funguskappen. Sie wachsen in Büscheln tief drinnen in der Uldaman-Grabungsstätte; vielleicht kann man sie auch anderswo finden, aber bisher ist das der einzige mir bekannte Ort, an dem sie gedeihen. Ich möchte ihren potenziellen Nutzen für die Alchimie erforschen und dafür brauche ich Euch.\n\nFindet die magenta Funguskappen-Büschel und bringt mir ein Dutzend Kappen. Aber seid gewarnt - die Pflanzen stoßen vielleicht Giftsporen aus, wenn man sie anstößt.\n\nWenn Ihr das für mich tut, dann braue ich Euch einen Schwung von meinem berühmten Regenerierungselixier!", progress = "Habt Ihr die magenta Funguskappen bekommen, die ich für meine alchimistische Arbeit benötige? Keine Kappen - keine Belohnung!", completion = "Gut gemacht, &lt;Name&gt;, Ihr habt mir Euren Wert abermals bewiesen! Es wird interessant sein, die Funguskappen zu studieren, da könnt Ihr drauf wetten.\n\nAber nun, wie versprochen: Genießt eine Kostprobe eines besonders wirksamen Regenerierungsgebräus, das ich normalerweise nur für den Eigengebrauch herstelle ...\n\nFalls Ihr in der Alchimie bewandert seid, dann können wir vielleicht noch weitere Geschäfte miteinander machen. Aber wie dem auch sei, habt Dank für Eure Unterstützung!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nRegenerationstrank"},
[2203] = {title = "Reagenzien-Suche im Ödland II", objective = "Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Jarkal Mossmeld in Kargath.", description = "Ihr seid mir eine große Hilfe gewesen, <Klasse>. Ich würde Euch ja das Rezept des Gebräus geben, das Ihr vorhin gekostet habt... doch zuvor muss ich Euch um einen gefährlichen Gefallen bitten. Hört meine Bitte.\n\nDiese Schließkassette enthält drei leere thaumaturgische Gefäße; sie sind mit einer Aura der Einstimmung magieerfüllt, die einem versengten Behütergroßdrachen das Blut aussaugt. Wenn Ihr sie gegen die Bestie benutzt, wird sie höchst erbost reagieren, also seid gewarnt. Bringt sie mir, wenn Ihr alle drei gefüllt habt.\n\nGelingt Euch das, gehört das Rezept Euch.", progress = "Habt Ihr die Gefäße benutzt, um das Blut versengter Wächtergroßdrachen zu beschaffen, das ich brauche? Ja, ich weiß, es ist eine gefährliche Aufgabe... aber das Rezept für mein Regenerierungsgebräu ist der Lohn Eures Erfolges. Von nichts kommt eben nichts, mein Freund... Von nichts kommt nichts...", completion = "Ich grüße Euch von Alchimist zu Alchimist. Hier, nehmt das Rezept und reiht es Eurem Wissen ein. Möge es Euch denselben Erfolg und die Belohnungen bringen wie mir im Lauf der Jahre.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRegenerationstrank\n\nIhr bekommt:\n\n"},
[2204] = {title = "Restaurierung der Halskette", objective = "Besorgt Euch eine Kraftquelle vom mächtigsten Konstrukt, das Ihr in Uldaman finden könnt, und liefert sie bei Talvash del Kissel in Ironforge ab.", description = "Ihr müsst etwas \"Energie\" für die Halskette finden, und wenn ich es mir recht überlege, dann ist Uldaman sogar der beste Ort dafür. Ich vermute mal, da drinnen laufen eine Menge Konstrukte rum, hab ich Recht?Gut, dann sucht Euch das größte und böseste Konstrukt, das Ihr finden könnt, macht es fertig und schnappt Euch seine Kraftquelle! Ich bin mir ziemlich sicher, dass ich die Kraftquelle mit der Halskette verbinden kann.\n\nOhne die Kraftquelle wird es unmöglich sein, die Halskette zu reparieren! Kommt wieder zu mir nach Ironforge zurück, wenn Ihr die Kraftquelle habt, dann repariere ich die Halskette für Euch.", progress = "Ihr habt Euch nicht mal die Zeit genommen, Euch etwas frisch zu machen, nachdem Ihr Uldaman verlassen hattet, oder? Ihr seid direkt hierher gekommen und pfeift auf die Kerkerdüfte, die Euch anhängen. Na, dann hoffen wir mal, dass dieser Besuch wirklich nur ein geruchvoller ist und nicht ein erfolgloser noch dazu.\n\nHabt Ihr die Kraftquelle für die Halskette?", completion = "Da soll mich doch... Ich freue mich wirklich sehr, Euch und diese Kraftquelle in einem Stück zu sehen! Es dauert einen Moment, bis ich die Kraftquelle auf magische Weise mit der Kette verschmolzen habe, jetzt, da die Edelsteine wieder angebracht sind. Sobald das aber passiert ist, gehört die Halskette Euch!\n\nIhr seid bestimmt aufgeregt, oder? Schon ganz kribbelig vor Erwartung? Wo hab ich denn bloß diesen Zauberfokus hingelegt...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2205] = {title = "Aufsuchen des SI: 7", objective = "Liefert Keryn Sylvius' Päckchen an Meister Mathias Shaw in der Kaserne von Stormwind.", description = "Das Abzeichen? Oh, das ist gar nichts, Dumpfbacke - jedenfalls nichts, mit dem Ihr fertig werden könntet. Wenn ich Euch so ansehe, würde ich sagen, dass Mathias Euch wahrscheinlich statt für einen anständigen Schurken für einen Käselieferanten halten wird. Aber wie dem auch sei, ich habe eine Aufgabe zugewiesen bekommen und ich habe versprochen, sie zu erledigen.\n\nDa wir gerade davon sprechen, bringt Mathias dieses Päckchen, dann gibt er Euch vielleicht eine kleine Aufgabe oder auch zwei.\n\nZischt ab.", progress = "Kann ich Euch helfen, <Klasse>?", completion = "Ihr habt mich gefunden - und wenn ich Euch so ansehe, würde ich sagen, der Lauf und die anschließende Suche sind körperlich wie geistig eine große Belastung für Euch gewesen.\n\nSoll Renzik Euch den Weg zu einem Gasthaus zeigen oder seid Ihr zur Arbeit bereit?", rewards = "Ihr bekommt:\n\n"},
[2206] = {title = "Schneller Eingriff", objective = "Sucht den Dockmeister der Defias und beschafft den Lieferzeitplan für Meister Mathias Shaw.", description = "Unsere Agenten vor Ort melden starke Aktivitäten der Defias südlich von Goldhain. Die Berichte deuten an, dass die Defias Jerods Anlegestelle erobert haben und ihn nun benutzen, um große Mengen Hehlerware vom Rotkammgebirge nach Westfall zu schmuggeln.\n\nIhr müsst das Dockhaus bespitzeln und mir den Lieferzeitplan beschaffen, <Name>. Ihr findet ihn wahrscheinlich tief in den Taschen des Dockmeisters.\n\n... und, <Name>, solltet Ihr entdeckt werden, wird der SI:7 strikt leugnen, dass er Euch kennt.", progress = "Eure Sterblichkeit schwindet mit jedem Moment, den Ihr in der Kaserne verweilt, <Klasse>.", completion = "Ich bin erstaunt... Erstaunt, dass Keryn endlich einen Rekruten gefunden hat, der das Zeug zu einem anständigen Schurken besitzt. Nehmt diese Klinge, &lt;Name&gt;. Es kommt der Tag, da wird man Euch bitten, dem SI:7 zu dienen. Perfektioniert Eure Fähigkeiten, haltet die Augen offen und diese Klinge scharf.\n\nIhr werdet uns nicht kommen sehen, aber Ihr werdet es spüren, wenn wir da sind...", rewards = "Ihr bekommt:\n\nKlinge der Geschicklichkeit"},
[2218] = {title = "Straße der Rettung", objective = "Sprecht mit Hulfdan Blackbeard in Ironforge.", description = "Eine weitere verirrte Seele, die nach Führung sucht, hm? Ich nehme an, Ihr wollt ein Ziel finden - Euer Ziel. Das habe ich schon tausend Mal gesehen, ein Held, der Arbeit sucht.\n\nAber heute ist Euer Glückstag. Hogral hat ein Heilmittel für Eure Leiden.\n\nIhr macht Folgendes: Schlagt diesen Weg nach Ironforge ein und begebt Euch zum düsteren Viertel. Wenn Ihr dort seid, sucht die Diebesgilde und sprecht mit Hulfdan Blackbeard. Er wird Euch den Weg zur Rettung weisen.", progress = nil, completion = "Ihr glaubt also, Ihr seid ein Halunke? Dem es vorbestimmt ist, einer von Blackbeards Auserwählten zu sein - ein Offizier des Verborgenen Kreises?\n\nNur jemand, der gar nichts taugt, hätte so eine hohe Meinung von sich.\n\nGenau nach so einem suchen wir! Willkommen an Bord, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[2238] = {title = "Einfache List", objective = "Sucht Onin MacHammar bei Gnomeregan.", description = "Ihr seht's ja, der König ist dabei, im Steinbruch nach Erz und Edelsteinen graben zu lassen. Mehr Reichtümer, als ein Zwerg normalerweise in zehn Leben zu sehen bekommen würde.\n\nDer Verborgene Kreis hat auch Werte, <Name>. Wertsachen! Versteht Ihr, was ich meine?\n\nWir finden, der König sollte uns was von der Beute abgeben, aber der alte Stinkebart soll nicht erfahren, dass er was abgibt - ich hoffe, Ihr könnt mir folgen.\n\nIhr müsst mit Onin MacHammar drüben bei Gnomeregan reden und 'nen Bericht zurückbringen. Der listige Zwerg hat sich bei den Lepragnomen versteckt. Seid vorsichtig.", progress = nil, completion = "Psst! Leise, elender Narr! Sonst werden sie uns noch hören.", rewards = "Ihr bekommt:\n\n"},
[2239] = {title = "Onins Bericht", objective = "Bringt Onins Bericht zu Hulfdan in Ironforge.", description = "Der Steinbruch? Ja, ich sehe fast jeden Tag diese monströsen Dampfpanzer hier vorbeirollen.\n\nMeine Kontakte im Osten sagen mir, dass der Panzer in Ironforge startet, im Gol'Bolar-Steinbruch seine Ladung abholt, zum Auftanken in Kharanos hält und dann aus einem unerfindlichen Grund den langen Weg um Gnomeregan herum fährt, ehe er seine Ladung in Ironforge ablädt.\n\nEs steht alles in dem Bericht, <Volk>. Bringt ihn zu Hulfdan, damit er den nächsten Schritt planen kann.", progress = "Hat Euch der Gestank des Lepragnoms gefallen? Ich frage nur, weil Ihr so ein irres Lächeln im Gesicht habt.\n\nWelche Neuigkeiten bringt Ihr von Onin?", completion = "Langer Weg? Im Namen meines eigenen Barts!\n\nDas habt Ihr gut gemacht, &lt;Name&gt;. Nehmt diesen Dolch und fort mit Euch. Der Kreis ruft Euch wieder, wenn Stufe drei in Angriff genommen werden kann.\n\nWas Stufe drei ist? Die kommt gleich nach Stufe zwei - dass ich Euch meine Stiefelspitze in den Hintern ramme.\n\nInteressiert?", rewards = "Ihr bekommt:\n\nKlinge der Geschicklichkeit"},
[2240] = {title = "Die geheime Kammer", objective = "Lest Baelogs Tagebuch, erforscht die geheime Kammer und erstattet dann Ausgrabungsleiter Stormpike Bericht.", description = "Jetzt zur anstehenden Aufgabe:\n\nEs gibt eine geheime Kammer, die Kammer von Khaz'mul, die erforscht werden muss. Das Problem dabei ist, dass die Kammer hinter einer riesigen verschlossenen Tür liegt! Glücklicherweise weiß ich, wie man sie öffnet.\n\nIch habe alles in dem Tagebuch hier auf dem Tisch beschrieben. Meine Leute und ich sitzen hier zurzeit fest ... also müsst Ihr die Kammer von Khaz'mul für uns finden, <Name>.\n\nLest mein Tagebuch, erforscht die Kammer und meldet Euch dann bei Ausgrabungsleiter Stormpike in der Forscherliga in Ironforge.", progress = nil, completion = "Ihr habt die Kammer von Khaz'mul gesehen? Erstaunlich! Baelog war sich sicher, dass es sie geben müsse, aber ich muss gestehen, dass ich so meine Zweifel hatte.\n\nDanke, &lt;Name&gt;. Mit etwas Glück wird Euer Fund unsere Anführer dazu bewegen, ihre Anstrengungen zur Wiedereroberung von Uldaman zu verstärken. Und sollte es jemals wieder unter die Kontrolle von Ironforge fallen, dann sind die Geheimnisse der Kammer von Khaz'mul unser!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZwergenstürmerForscherliga-Erzaderstern\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[2241] = {title = "Der Apfel fällt", objective = "Bringt Jannoks Rose zu Syurna in Darnassus.", description = "Sie sagen, ich bin 'liebeskrank', was immer das heißen mag.\n\nKlar, ich denke ununterbrochen an Syurna. Klar, mein Haus ist voll von Bildern und Zeichnungen von Syurna. Klar, es kommt vor, dass ich tagelang nicht esse, schlafe oder trinke, während ich über die Liebe lamentiere, die uns nicht zuteil wurde. Ist das so falsch?\n\nJetzt will sie mich nicht sehen! MICH! Ich habe versucht, ihr Nachrichten zu schicken, aber sie redet mit keinem, es sei denn, er wäre ein Schurke.\n\nKönntet Ihr diese Blume zu ihr bringen? Und vergesst nicht, ihr zu sagen, dass sie von Jannok ist.", progress = "Oh, ist das nicht herrlich. Ihr habt Blumen für Euer eigenes Begräbnis mitgebracht.", completion = "Hätte ich jede Blume aufgehoben, die mir dieser Trottel Jannok schickte, könnte ich einen Blumenladen eröffnen. Allerdings könnte sich Jannoks neuester Kurier als nützlich erweisen.\n\nSeid Ihr an Arbeit interessiert, &lt;Klasse&gt;?", rewards = "Ihr bekommt:\n\n"},
[2242] = {title = "Das Schicksal ruft", objective = "Sucht Sethir den Uralten und bringt alle Hinweise, die Ihr finden könnt, zu Syurna.", description = "Wir glauben, dass es ein Wesen gibt, das uns verstehen helfen könnte, was mit den Wäldern von Teldrassil geschieht. Leider hatte es verheerende Folgen, als wir versuchten, dieses Wesen zur Mitarbeit zu überreden.\n\nEr versteckt sich auf einem Ast am Rand der Lichtung des Orakels. Alle, die sich dem Satyr bisher genähert haben, sei es mit Gewalt oder Diplomatie, fanden ein böses Ende. Vielleicht ist Verstohlenheit die Lösung, <Name>.\n\nFindet heraus, was Sethir der Uralte in seinen Rucksäcken hat und berichtet mir davon.", progress = "Habt Ihr etwas von Sethir dem Urtum zu berichten, <Name>?", completion = "Das sind schlimme Neuigkeiten, &lt;Name&gt;. Es scheint, als würde die Erkrankung, die die Wälder und Flüsse von Dunkelküste besudelt hat, auf unsere Heimat übergreifen.\n\nIhr habt uns gute Dienste geleistet, aber hier könnt Ihr nichts mehr tun. Nehmt diese Klinge als Lohn für Eure Dienste für Teldrassil.", rewards = "Ihr bekommt:\n\nKlinge der Geschicklichkeit"},
[2258] = {title = "Reagenzien-Suche im Ödland", objective = "Bringt Jarkal Mossmeld in Kargath im Ödland 5 Bussard-Mägen, 10 Klippenkojoten-Fangzähne und 5 Felselementarsplitter.", description = "<Name>, ich könnte Eure Hilfe gebrauchen, wenn Ihr Euch dazu in der Lage fühlt. Ich bin ein angesehener Alchimist und benötige Eure Unterstützung, um einige Reagenzien zu beschaffen, die im Ödland zu finden sind.\n\nIch brauche folgende Gegenstände, um meine Vorräte aufzufüllen: 5 Bussard-Muskelmägen, 10 Klippenkojotenfangzähne und 5 Felselementarsplitter. Natürlich könnt Ihr diese Reagenzien direkt von den lieben Tieren selbst bekommen; aber wenn Ihr keine Kämpfernatur seid, dann sucht Euch besser Freunde, die kämpfen können.\n\nBringt mir diese Gegenstände, dann springen ein paar Münzen für Euch dabei raus. Was sagt Ihr?", progress = "Habt Ihr die Sachen schon, die ich brauche? Ihr werdet nur bezahlt, wenn Ihr mir diese Reagenzien bringt.", completion = "Ah, gut gemacht! Damit sollte ich eine Weile hinkommen. Hier ist Eure versprochene Bezahlung.\n\nFalls Ihr interessiert seid: Es gibt noch ein paar Reagenzien, die ich brauchen könnte. Die findet man allerdings nur in den Tiefen der Ausgrabung von Uldaman. Sie werden nicht leicht zu beschaffen sein, aber wenn Ihr mir nochmals helfen wollt, soll es sich für Euch lohnen.\n\nVielleicht etwas mehr als nur glänzende Münzen, hm?", rewards = "Ihr bekommt:\n\n"},
[2259] = {title = "Erion Shadewhisper", objective = "Kontaktiert Erion Shadewhisper in Darnassus.", description = "Keine Bange, <Name>, ich schicke Euch nicht zu Syurna. Erion verlangt nach Eurer Anwesenheit in der Enklave des Cenarius. Beeilung!", progress = nil, completion = "Es wird Zeit, loszuziehen, &lt;Volk&gt; - die Welt wartet.", rewards = "Ihr bekommt:\n\n"},
[2260] = {title = "Erions Befehl", objective = "Reist zur Stadt Stormwind und meldet Euch bei Renzik \"Das Messer\".", description = "Die Kunde von Euren Taten ist in aller Munde, <Name>. Ihr seid so berühmt, dass der Geheimdienst von Stormwind nach Euch persönlich gefragt hat.\n\nDie Reise ist anstrengend und nicht ungefährlich, aber die Gelegenheit einer Ausbildung beim SI:7 sollte man nicht in den Wind schlagen.\n\nEine neue Welt erwartet Euch, <Name>. Begebt Euch in die Altstadt von Stormwind und sprecht mit Renzik \"Das Messer\" im Hauptquartier des SI:7.", progress = nil, completion = "Ihr seid dem Ruf des SI:7 gefolgt, &lt;Name&gt;, und seid von fernen Ufern angereist, um für uns zu arbeiten. Aber es gibt viel zu lernen.", rewards = "Ihr bekommt:\n\n"},
[2278] = {title = "Die Platinscheiben", objective = "Sprecht mit dem Steinbehüter und findet heraus, welche uralten Lehren er aufbewahrt. Sobald Ihr alles erfahren habt, was er weiß, aktiviert die Scheiben von Norgannon.", description = "Die Kernstücke dieser Schatzkammer sind vier riesige Platinscheiben, von denen jede mit zahlreichen Siegelzeichen unbekannter Herkunft bedeckt ist. Als Ihr sie berührt, beginnt Eure Hand zu kribbeln. Unmittelbar, nachdem Ihr die Scheiben berührt habt, erscheint das Gesicht eines großen Steinbeobachters.\n\n\"Willkommen. Ich bin ein Hüter des Wissens. Die Schöpfungssynthese der Irdenen wurde hier in den Scheiben von Norgannon für diese Welt aufgezeichnet und aufbewahrt.\"\n\nIhr habt eine Fülle an bislang unbekanntem Wissen über die Welt entdeckt!", progress = "Die Stimme des Steinbeobachters scheint in jeder Faser Eures Körpers widerzuhallen:\n\n\"Ihr müsst zunächst den Datenaufnahmevoraussetzungen der Scheiben von Norgannon genügen. Sobald Ihr diese Bedingung erfüllt habt, wird es Euch erlaubt werden, eine tragbare Version der hier aufbewahrten Daten an Euch zu nehmen. Bitte stellt erst sicher, dass Ihr die Informationen in diesem Datenspeicher wirklich alle erkundet habt.\"", completion = "Ihr folgt den Anweisungen des Steinbehüters und greift noch einmal auf die Scheiben von Norgannon zu, nachdem Ihr jetzt die Geschichte der Irdenen, der Troggs und der Zwerge kennt. Aus dem Inneren der Scheiben ertönt ein kurzes, fast unhörbares Summen. Dann spricht der Steinbeobachter erneut:\n\n\"Die Scheiben sind jetzt synthetisiert.\" Greift noch einmal auf die Scheiben von Norgannon zu, um Euer persönliches Exemplar zu erhalten.\"", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2279] = {title = "Die Platinscheiben", objective = "Bringt die Miniaturausgabe der Scheiben von Norgannon zur Forscherliga nach Ironforge.", description = "Als Ihr die Scheiben von Norgannon ein weiteres Mal berührt, kribbelt Eure Hand erneut. Jetzt aber ist aus dem Inneren der Scheiben ein seltsames, knirschendes Geräusch zu hören.\n\nPlötzlich ist Euer Rucksack schwerer als noch eine Sekunde vorher. In seinem Inneren findet Ihr eine Miniaturausgabe der Scheiben!\n\nZweifellos wäre ein solcher Gegenstand von unschätzbarem Wert für jeden, der sich für die Frühgeschichte von Azeroth interessiert. Die Forscherliga in Ironforge beispielsweise ist eine solche Gruppe und sie ist in der ganzen Allianz bekannt - vielleicht können die etwas mit diesem Fund anfangen.", progress = "Ja, kann ich Euch behilflich sein? Ich kann Euch versichern, dass ich zurzeit äußerst beschäftigt bin. Wenn es sich jedoch um eine Angelegenheit von großer Wichtigkeit für die Forscherliga handelt, dann bin ich ganz Ohr!", completion = "Was habt Ihr da... ach du liebe Güte. Das habt Ihr wo gefunden?\n\nNein, wirklich?\n\nIhr habt mir wem worüber gesprochen?\n\nNEIN, WIRKLICH?\n\nMein Lieber, Ihr habt gerade den archäologischen Fund des Jahres gemacht! Aber, bei den Göttern, was rede ich da, &lt;Klasse&gt;, das ist der Fund des Jahrhunderts! Wenn diese Scheiben das sind, wofür ich sie halte, dann könnte das genau der Schlüssel sein, nach dem wir schon so lange suchen! Das hier könnte tatsächlich ein für alle Mal und unwiderlegbar beweisen, dass die Erschaffung der Zwerge durch Zauberkraft kein Wunschdenken, sondern die Wahrheit ist!", rewards = "Ihr bekommt:\n\n"},
[2280] = {title = "Die Platinscheiben", objective = "Bringt die Miniaturausgabe der Scheiben von Norgannon zu einem der Weisen von Thunder Bluff.", description = "Als Ihr die Scheiben von Norgannon ein weiteres Mal berührt, kribbelt Eure Hand erneut. Jetzt aber ist aus dem Inneren der Scheiben ein seltsames, knirschendes Geräusch zu hören.\n\nPlötzlich ist Euer Rucksack schwerer als noch eine Sekunde vorher. In seinem Inneren findet Ihr eine Miniaturausgabe der Scheiben!\n\nZweifellos wäre ein solcher Gegenstand von unschätzbarem Wert für jeden, der sich für die Frühgeschichte von Azeroth interessiert. Die Weisen von Thunder Bluff beispielsweise sind solche Historiker und sie sind in der ganzen Horde wohl bekannt - vielleicht können die etwas mit diesem Fund anfangen.", progress = "Ja, Jungchen, ich sehe, wie Ihr mein Zelt betretet: mit Schwung in Eurem Schritt... mit Entschlossenheit in Euren Absichten. Ihr sucht meinen Rat in einer Angelegenheit von höchster Wichtigkeit für die Horde? Ist Euch vielleicht ein Geheimnis des Universums offenbart worden, das Ihr mit mir teilen möchtet?", completion = "Was haben wir denn hier?\n\nIch bin beeindruckt! Drei Scheiben, in denen ich Geheimnisse spüren kann, die die Erde zu viele Jahre lang in ihrem Inneren verborgen hat. Es war sehr klug von Euch, sie zu mir zu bringen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2281] = {title = "Rendezvous im Rotkammgebirge", objective = "Geht nach Seenhain im Rotkammgebirge und sprecht mit Lucius.", description = "Euch jetzt in den Einsatz zu schicken wäre Selbstmord. Renzik braucht nicht noch einen toten Schurken. Aber keine Sorge, <Name>... Renzik wird Euch schon Beine machen.\n\nGeht ins Rotkammgebirge und sprecht mit einem Mitglied des SI:7 namens Lucius. Ihr werdet ihn auf den Docks von Seenhain finden, wo er mit den anderen halbseidenen Taugenichtsen herumhängt.", progress = nil, completion = "Eure Finger sind also ein wenig plump, hm? Keine Bange, &lt;Name&gt;, ich habe schon mehr nutzlose Diebe als Euch zu tüchtigen Schurken gemacht.", rewards = "Ihr bekommt:\n\n"},
[2282] = {title = "Althers Mühle", objective = "Öffnet Lucius' Schließkassette, nehmt die Marke der Diebeskunst heraus und bringt sie zu Lucius nach Seenhain.", description = "Wir bilden hier schon seit Jahren Diebe aus! Schließlich wird nicht jeder Langfinger mit der Anmut und Finesse des alten Lucius geboren.\n\nOben an der Straße findet Ihr Althers Mühle. Ich habe dort oben eine Truhe mit wichtigem Inhalt. Holt sie für mich! Bringt mir diese Marke und Ihr bekommt Euer Zertifikat der Diebeskunst!", progress = "Habe ich vergessen, die Orcs zu erwähnen?\n\nIch habe gehört, dass sie da oben bei der Mühle herumschnüffeln.", completion = "Ihr habt sie aufbekommen? Gute Arbeit, &lt;Name&gt;.\n\nWenn Ihr jetzt sterbt, sind wir wenigstens sicher, dass es an Eurer eigenen Dummheit lag, nicht an Eurer Unerfahrenheit.", rewards = "Ihr bekommt:\n\nZertifikat der Diebeskunst"},
[2283] = {title = "Wiederbeschaffung der Halskette", objective = "Sucht in der Grabungsstätte von Uldaman nach einer wertvollen Halskette und bringt sie nach Orgrimmar zu Dran Droffers. Die Halskette ist vielleicht beschädigt.", description = "Wir haben Arbeit für Euch, falls Ihr den Mut habt, Euch daranzuwagen.\n\nTief im Ödland befindet sich Uldaman, eine Grabungsstätte. Wir haben eine Geschichte gehört von so einem dummen Paladin, der kürzlich dort gestorben ist. Das würde uns ja alles nicht interessieren, aber er hatte eine sehr wertvolle Halskette bei sich. Angeblich sind drei große Edelsteine dabei: ein Rubin, ein Saphir und ein Topas.\n\nKurz gesagt: Wir wollen die Kette haben und wir bezahlen GUTES SILBER, um sie zu kriegen. Vielleicht ist sie beschädigt, aber das tut nichts zur Sache. Wir reparieren sie, wenn Kratzer daran sein sollten.", progress = "Und, habt Ihr die Halskette? Ihr kriegt keinen müden Kupferpfennig von uns, wenn Ihr die Halskette nicht habt!", completion = "Aaaah, geborgenes Gut! Ich kann die Halskette schon riechen. Dann wollen wir uns die Schönheit mal anschauen...\n\nHe, was für ein Spiel wollt Ihr hier spielen? Bei dieser Halskette fehlen die Edelsteine! Habt Ihr etwa gedacht, das würde uns nicht auffallen? Sogar Malton würde es auffallen, dass die Edelsteine weg sind.\n\nNa, vielleicht habt Ihr sie nicht gestohlen... aber ohne die Edelsteine ist die Halskette wertlos! Euer Job ist noch nicht erledigt, noch lange nicht!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2284] = {title = "Wiederbeschaffung der Halskette, Teil 2", objective = "Sucht in den Tiefen von Uldaman nach einem Hinweis auf den Verbleib der Edelsteine.", description = "Genauso sicher, wie Malton ein Idiot ist, sind diese Edelsteine noch irgendwo in Uldaman. Ihr werdet wohl dorthin zurückgehen müssen und nach ihnen suchen.\n\nIch hab's ja schon mal gesagt: Wenn unsere Informationen stimmen, dann gehören zu der Halskette ein Rubin, ein Saphir und ein Topas. Findet sie und fügt sie in die Halskette ein.\n\nAber wo die Edelsteine sind - wer weiß das schon? Vielleicht habt Ihr ja Glück und findet die Leiche dieses Paladins. Wenn er noch nicht völlig ausgeplündert worden ist, dann hat er sie ja vielleicht sogar bei sich.", progress = nil, completion = "Es scheint, als hättet Ihr die Überreste des Paladins gefunden, den Dran erwähnte. Als Ihr die Überreste durchsucht, entdeckt Ihr etwas, das sein Tagebuch zu sein scheint. Das Buch ist in keinem guten Zustand, da der größte Teil des Textes darin von getrocknetem Blut unleserlich gemacht wird. Und was Ihr davon lesen könnt, ist nicht zu entziffern, denn soweit Ihr das beurteilen könnt, ist es in der Menschensprache geschrieben.\n\nIhr müsst das Buch übersetzen lassen, wenn Ihr irgendwelches Wissen daraus ziehen wollt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2298] = {title = "Königliche Erpressung", objective = "Reist nach Stormwind und sucht Renzik \"Das Messer\" auf.", description = "Wir war'n also grade dabei, Phase III zu planen, da platzen 'n paar von Magnis Holzköpfen hier rein, schwafeln was von 'ner Art Razzia und verhaften ein paar vom Verborgenen Kreis.\n\nSo springt keiner mit dem alten Blackbeard um! Die Diskussion wurde immer hitziger und irgendwann fiel Euer Name!\n\nMein Rat? Nehmt den ersten Greif aus Ironforge raus und geht nach Stormwind. Geht in die Altstadt und sprecht dort mit einem alten Freund von mir, der Renzik \"Das Messer\" genannt wird.", progress = nil, completion = "Es ist immer schön, einen von Hulfdans Schurken in unseren Reihen zu haben!", rewards = "Ihr bekommt:\n\n"},
[2299] = {title = "Auf Hulfdan!", objective = "Reist nach Ironforge und sprecht mit Hulfdan Blackbeard.", description = "Wo seid Ihr gewesen, <Name>? Hulfdan sucht schon überall nach Euch. Wir dachten schon, der König hätte Euch in Eisen legen lassen.\n\nGeht so schnell wie möglich nach Ironforge und sprecht mit Hulfdan!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[2300] = {title = "Der SI:7", objective = "Reist nach Stormwind und sucht Renzik \"Das Messer\" auf.", description = "Renzik hat nach Euch gesucht, Dumpfbacke.\n\nIch an Eurer Stelle würde Mathias' Stellvertreter nicht warten lassen.", progress = nil, completion = "Seid Ihr bereit zu arbeiten oder müsst Ihr ein Nickerchen machen, ehe wir anfangen?", rewards = "Ihr bekommt:\n\n"},
[2318] = {title = "Übersetzung des Tagebuchs", objective = "Sucht jemanden, der das Tagebuch des Paladins übersetzen kann. Der nächstgelegene Ort, wo Ihr so jemanden finden könntet, ist Kargath im Ödland.\n\nBereitgestellter Gegenstand: \n", description = "Ihr befindet Euch in einer Art Sackgasse, denn Ihr wisst, dass Ihr das Buch erst in eine Sprache übersetzen lassen müsst, die Ihr versteht. Es gibt etliche Leute auf der Welt, die das machen könnten - der nächste Ort, wo sich vielleicht jemand finden ließe, der dazu in der Lage ist, wäre vermutlich der Kargath-Außenposten im Ödland. Vielleicht wäre das ein guter Ort, um anzufangen.", progress = nil, completion = "&lt;Klasse&gt;, ich weiß, dass Ihr mächtig seid und was Ihr hier draußen im Ödland macht. Ich weiß, dass Ihr meine Gabe der Sprachen sucht. Ihr fahndet nach den fehlenden Teilen für die Halskette, die Ihr in Uldaman gefunden habt.\n\nÜberrascht? Warum?... Es ist meine Aufgabe, solche Dinge zu wissen. Lasst uns stattdessen darüber sprechen, was Ihr für ein übersetztes Tagebuch zu tun bereit seid. Glaubt mir - ich bin der Einzige, der es Euch übersetzen kann.\n\nNoch besser, lasst mich Euch ein besseres Angebot als das von Dran Droffers machen und Ihr könntet immer noch Euer Geschäft mit den Leuten abschließen. Jetzt seid Ihr interessiert, stimmt's?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2338] = {title = "Übersetzung des Tagebuchs", objective = "Leiht Jarkal die Halskette. Im Gegenzug wird er das Tagebuch für Euch übersetzen.", description = "Droffers und Sohn Bergungen' sind nicht schlau genug, die Magie der Halskette wiederherzustellen, aber ich kann es. Ich muss nur die Halskette studieren, damit ich lerne, wie ich selbst solche Ketten herstellen kann. Und dazu benötige ich Eure Halskette. Leiht sie mir, und im Gegenzug für die Zeit, in der ich die Kette studieren kann, werde ich das Tagebuch für Euch übersetzen. Ich sollte genug Zeit haben, alles Nötige zu erfahren, während Ihr nach den Edelsteinen sucht.\n\nEs ist ein einfacher Handel und niemand wird etwas davon erfahren. Also, was sagt Ihr?", progress = "Ihr habt es Euch überlegt, ja? Ihr seid ein schlauer <Klasse>, wenn Ihr dieses Angebot annehmt - Ihr und ich werden beide bekommen, was wir wollen, und 'Droffers und Sohn Bergungen' werden denken, dass sie bekommen, was sie wollen.", completion = "Ihr erkennt ein gutes Angebot, wenn Ihr eines bekommt - ich wusste, dass ich auf Euch zählen kann.\n\nEs dauert nur einen Moment. Ich wirke einen Zauber, der die Menschensprache schnell in etwas übersetzt, das Ihr verstehen könnt. Ich bin ein Troll, der sein Wort hält - Ihr könnt jeden in der Horde auf Jarkal Mossmeld ansprechen. Also, dann wollen wir mal anfangen ...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2339] = {title = "Findet die Edelsteine und die Kraftquelle", objective = "Beschafft in Uldaman alle drei Edelsteine sowie eine Kraftquelle für die Halskette und bringt sie anschließend zu Jarkal Mossmeld nach Kargath. Jarkal glaubt, dass sich eine Kraftquelle vielleicht im stärksten Konstrukt in Uldaman findet.\n\nAus dem Tagebuch, wisst Ihr...\n* Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt.\n* Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz.\n* Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen.", description = "Hier ist das Tagebuch, übersetzt, sodass Ihr es lesen könnt. Kurz gesagt steht darin, dass Zwerge den Rubin versteckt haben, Troggs versteckten den Topas und ein Trogg namens Grimlok hat den Saphir.\n\nEs ist so, Ihr braucht eine Kraftquelle, um die Halskette wieder funktionstüchtig zu bekommen. Dran Droffers weiß das nicht. Um eine Kraftquelle zu finden, würde ich Folgendes tun: Begebt Euch so tief wie möglich nach Uldaman hinein und tötet das stärkste Konstrukt, das Ihr finden könnt. Ich zweifle nicht daran, dass das stärkste Konstrukt dort auch dasjenige ist, das die Kraftquelle hat.\n\nWenn Ihr alles zusammenhabt, dann kommt wieder hierher!", progress = "Euch steht ein weiterer Ausflug in die Tiefen von Uldaman bevor, wenn Ihr nicht die Edelsteine sowie eine Kraftquelle habt, die die magische Kraft wieder zurück in die Halskette kanalisieren kann.\n\n", completion = "Sehr gut, &lt;Klasse&gt;. Jetzt wird sich unser kleines Täuschungsmanöver wunderbar auszahlen. Mit der Halskette selbst bin ich fertig und ich bin mir sicher, dass ich den Herstellungsprozess jederzeit wiederholen kann.\n\nDoch zunächst spreche ich noch eine eigens dafür vorbereitete Zauberformel, um die Edelsteine zu analysieren, ehe Ihr sie und die Halskette nach Orgrimmar zurückbringt. Das dauert auch nur einen kleinen Moment.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2340] = {title = "Ablieferung der Edelsteine", objective = "Liefert die Halskette und die geborgenen Edelsteine bei Dran Droffers in Orgrimmar ab.", description = "Jede Halskettenfassung und jeder Edelstein wird funktionieren, solange sie aus demselben Material bestehen. Doch es ist die Kraftquelle, die der Halskette die Magie wieder zurückgeben wird. Hoffe ich zumindest.\n\nIch werde Euch gern die Edelsteine zur Verfügung stellen, die Ihr für Eure Version der Halskette benötigt, wenn die Kraftquelle einwandfrei funktioniert.\n\nBegebt Euch nach Orgrimmar und haltet Euren Teil der Abmachung mit 'Droffers und Sohn Bergungen' ein. Haltet lediglich den Mund über unser Geschäft, und wenn Ihr zurückkommt, habe ich vielleicht schon eine wundervolle Überraschung für Euch.", progress = nil, completion = "Jawoll, alles da. Sagt mal, macht es Euch was aus, wenn wir auch den Beutel behalten? Nein? Danke, ich weiß das zu schätzen! Haha!\n\nDiese Halskette wird unser bester Fang bisher sein! Aber macht Euch nichts draus. Die Kette würde Euch ja ohnehin nicht passen. Haha!\n\nEin Geschäft ist ein Geschäft, also habt Ihr hier Euren Lohn für die Bergung. Fürs Erste ist unser Handel abgeschlossen, aber kommt ruhig später wieder, dann haben wir vielleicht wieder Arbeit für Euch. Aber bis dahin verschwindet!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2341] = {title = "Wiederbeschaffung der Halskette, Teil 3", objective = "Besucht Jarkal Mossmeld in Kargath, um festzustellen, ob er Erfolg gehabt hat.", description = "Als Dran und Malton Droffers anfangen, sich um ihr neues Bergegut zu zanken, ist die Hälfte des Geschäftes bereits erledigt. Jetzt steht noch eine Reise ins Ödland an, um dort die Sache zum Abschluss zu bringen, denn Jarkal Mossmeld aus Kargath hat eine besondere Belohnung für Euch in petto - oder vielleicht auch nicht.", progress = nil, completion = "Die Kraftquelle, die Ihr mir gegeben habt, hat alle meine Erwartungen übertroffen. Ich konnte sowohl für Euch als auch für mich selbst eine Halskette herstellen und ich habe noch genug übrig, um mindestens drei weitere anfertigen zu können. Sie werden nicht wenig Geld einbringen und 'Droffers und Sohn Bergungen' sind so klug wie zuvor.\n\nBitte sehr, mein Bester. Ich danke Euch von Herzen für Eure ausgezeichnete Arbeit ... Hier habt Ihr etwas ganz Besonderes als Lohn für Eure Mühen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nJarkals intensivierende Halskette"},
[2342] = {title = "Wiederbeschaffte Schätze", objective = "Holt Patrick Garretts Familienschatz aus der Truhe der Familie in der südlichen Bankenhalle von Uldaman und bringt diesen zu ihm nach Undercity.", description = "Die Fledermausgehege mit diesem Besen auszukehren, das ist keine Aufgabe, die eines Garretts würdig wäre! Aber ich habe mit diesem verfluchten Job ein wenig Geld verdient und ich bin bereit, es für Euch auszugeben, wenn ich damit nur meine Situation verbessern kann.\n\nDie Lieblingswaffe der Familie Garrett liegt weggeschlossen in unserer Truhe in der südlichen Bankenhalle von Uldaman. Das rührt noch von den Zeiten her, da wir Garretts dort als Buddler schufteten. Ohne sie werde ich für alle Zeiten hier festsitzen und im wahrsten Sinne des Wortes diesen höllischen Fledermäusen hinterherkehren.\n\nBeschafft den Schatz meiner Familie wieder und bringt ihn mir! Helft mir dabei, mein Geburtsrecht einzufordern!", progress = "Das Kehren nimmt nie ein Ende... Diese Fledermäuse bringen ihre Verachtung für mich und meinen Besen wirklich höchst produktiv zum Ausdruck. Bitte sagt mir, dass Ihr den Schatz meiner Familie wiedererlangt habt! Ich habe Euch all mein Silber angeboten - reicht das nicht?!", completion = "Endlich - ein Besen, der eines Garretts würdig ist. Ihr seid verdammt noch mal jedes Silberstück wert, das ich Euch bezahlt habe!\n\nHabt Ihr das gehört, ihr elenden Fledermäuse? Ich halte jetzt die Lieblingswaffe der Familie Garrett in Händen! Erzittert, ihr Fledermäuse, erzittert!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2358] = {title = "Hörner von Nez'ra", objective = "Bringt die Hörner von Nez'ra zu Arantirs Schatten nach Seenhain.", description = "Vor vielen Jahren wurden die Hörner von Nez'ra aus dem Ravenholdt-Anwesen gestohlen. Über Ozeane und Kontinente hinweg habe ich nach ihnen gesucht, nur um schließlich zu erfahren, dass diese unbedeutenden Bestien sie die ganze Zeit über im Besitz hatten.\n\nErschlagt jeden Blackrockorc, auf den Ihr trefft, bis Ihr die Hörner von Nez'ra wiedererlangt habt. Solltet Ihr die Hörner in Euren Besitz bekommen, dann sucht mich in Seenhain auf.\n\nWenn Ihr dies für mich tut, soll Euer Name in Ravenholdt Bekanntheit erlangen, <Name>.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nDisteltee"},
[2359] = {title = "Klavens Turm", objective = "Stehlt den Turmschlüssel der Defias, brecht in den Turm der Defias ein und stellt fest, was sich in der Dämmerwaldtruhe befindet. Bringt Mathias Shaw in Stormwind dann alle Informationen über das, was Ihr herausgefunden habt. Lest Kearnens Tagebuch, um neue Erkenntnisse über den Turm zu erlangen.", description = "Ich überwache diesen Turm jetzt schon seit Wochen, <Name>. Kürzlich kam eine größere Lieferung aus dem Dämmerwald an und mit dieser Lieferung kamen auch diese Wachen.\n\nWas sie sind? Das weiß ich genauso wenig wie Ihr. Eines kann ich Euch aber sagen: Menschen sind das nicht.\n\nWie dem auch sei, bei der Lieferung war eine Truhe dabei und ich vermute mal, das ist es, was diese Monstrositäten bewachen. Die Kreatur mit den Stacheln hat einen Schlüssel, den wir brauchen.\n\nBeschafft Euch den Schlüssel, dringt in den Turm ein und stellt fest, was in dieser Truhe ist. Berichtet dann Mathias, was Ihr herausgefunden habt.", progress = "Gibt es etwas Neues von Agentin Kearnen?", completion = "Das erklärt die Anwesenheit der Defiasdrohnen, die Ihr und Kearnen vor dem Turm gesehen habt, &lt;Name&gt;. Es würde auch erklären, was die Venture Company mit den Defias zu tun hat und was es mit den seltsamen Lieferungen aus dem Dämmerwald auf sich hat.\n\nIn diesem Buch heißt es, dass die Trolle der Zanzil im Schlingendorntal einen Weg gefunden haben, mit bestimmten Tränken die Toten zu erwecken... oder, um genau zu sein, mit Gift.\n\nOhne ein umfangreiches Wissen über Gifte habt Ihr für den SI:7 keinen großen Nutzen, &lt;Name&gt; - vor allem nicht ohne das Wissen darüber, wie man mit einem einfachen Rezept auf Wunsch Untote erschaffen kann.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGifte\n\nIhr bekommt:\n\nRezept: Disteltee"},
[2360] = {title = "Mathias und die Defias", objective = "Reist nach Westfall und sucht Agentin Kearnen. Sie wird Euch Bericht erstatten.", description = "Keinen Moment zu früh, <Name>. Spähtrupps des SI:7 berichten von ungewöhnlich intensiven Aktivitäten der Defias in Westfall.\n\nEs sieht so aus, als hätten die Defias einen verlassenen Wachturm der Allianz südlich der Späherkuppe übernommen und verwendeten diesen als Operationsbasis, um Güter von der Lieferroute ins Rotkammgebirge hereinzuschmuggeln.\n\nBegebt Euch nach Westfall und kontaktiert Agentin Kearnen. Sie wird Euch Bericht erstatten. Sie hält sich in der Nähe des Turms versteckt; dort findet Ihr sie.\n\n... und, <Name>, solltet Ihr entdeckt werden, wird der SI:7 strikt leugnen, dass er Euch kennt.", progress = nil, completion = "Mathias hat also endlich einen weiteren Agenten zu meiner Unterstützung geschickt, hm? Na, ich hoffe, er ist auf schlechte Nachrichten gefasst.", rewards = "Ihr bekommt:\n\n"},
[2361] = {title = "Restaurierung der Halskette", objective = "Ich gebe Euch diese Halskette gern, <Klasse>. Ihr habt mir einen unschätzbaren Dienst erwiesen und dafür danke ich Euch. Tragt die Kette mit Stolz und vergesst nicht, immer wieder in der gebührenden Lautstärke zu verkünden, wer sie für Euch gemacht hat!\n\nUnd wenn Ihr auch beiläufig erwähnen könntet, dass die Kette nicht verflucht ist, dann wäre das wirklich wunderbar.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nTalvashs verstärkende Halskette"},
[2378] = {title = "Suche nach der Shattered-Hand", objective = "Reist nach Orgrimmar und sprecht an der Kluft der Schatten mit Shenthul.", description = "Ihr habt den Schattenpirschern gut gedient, <Name>, aber vielleicht ist es an der Zeit, dass Ihr Euch nach draußen wagt. Zwar habt Ihr schon gezeigt, dass Ihr in der Kunst der Verstohlenheit und der Täuschung bewandert seid, doch Eure Ausbildung ist noch lange nicht beendet.\n\nDie Schattenpirscher haben Verbündete bei der Shattered-Hand. Sucht jemanden auf, der nichts dagegen hat, uns zu helfen: Shenthul in Orgrimmar.", progress = nil, completion = "Ihr seid also das, was unsere mächtigen Verbündeten zu Shenthul schicken? Wie langweilig...", rewards = "Ihr bekommt:\n\n"},
[2379] = {title = "Zando'zan", objective = "Sprecht an der Kluft der Schatten mit Zando'zan.", description = "Entschlossenheit allein reicht nicht aus, um die Hindernisse zu überwinden, die vor uns liegen.\n\nSprecht mit Zando'zan, um Eure Ausbildung als <Agent/Agentin> der Shattered-Hand zu beginnen.\n\nErst wenn Ihr die Kunst der Verstohlenheit und die Diebeskunst gemeistert habt, könnt Ihr den nächsten Schritt auf Eurem persönlichen Weg des Schicksals gehen.", progress = nil, completion = "Vielleicht hat Zando'zan sich geirrt. Zando'zan bittet um Vergebung.", rewards = nil},
[2380] = {title = "Nach Orgrimmar!", objective = "Sprecht an der Kluft der Schatten in Orgrimmar mit Shenthul.", description = "Noch seid Ihr <kein Meister/keine Meisterin> der Verstohlenheit und der Täuschung, doch das kann und wird sich alles ändern. Ganz offensichtlich habt Ihr die da oben mit Euren dürftigen Fähigkeiten beeindruckt, denn der große Shenthul selbst hat nach Euch gefragt.\n\nReist auf der Straße nördlich von hier nach Orgrimmar und sprecht in der Kluft der Schatten mit Shenthul.", progress = nil, completion = "Es ist wichtig, dass die Shattered-Hand angesichts der Veränderungen, die Thrall bei der Horde herbeiführen will, wachsam bleibt. Rein zahlenmäßig können wir seine Herrschaft nicht beenden - jeder von uns muss die Kunst der Verstohlenheit und der Täuschung meistern.", rewards = "Ihr bekommt:\n\n"},
[2381] = {title = "Das Ausplündern der Plünderer", objective = "Bringt den Schatz der Südmeerfreibeuter zu Wrenix dem Jämmerlichen in Ratchet. Vergesst nicht, einen R.C.V.K. und Diebeswerkzeug von Wrennixs Elektrodingsda-Apparat zu bringen. Ihr werdet diese Dinge brauchen, um Eure Mission zu beenden.\n\nWenn Ihr von ungewöhnlich feindlichen Papageien angegriffen werdet, benutzt Euren R.C.V.K.!", description = "Ich will Euch keine Angst einjagen, <Name>, aber die letzten fünf Diebe, die ich ausgesandt habe, um den Schatz der Südmeerfreibeuter zu stehlen, sind in Stücken zu mir zurückgekommen.\n\nAn der Küste im Süden findet Ihr die Tide Razor, das Schiff der Südmeerfreibeuter. Unten im Laderaum findet Ihr das Gesuchte: den Schatz der Südmeerfreibeuter. Auf dem zweiten Deck des Schiffes findet Ihr die Piratenhöhle, dort bilden sie ihre Diebe aus.\n\nGeht an Bord dieses Schiffes, stehlt den Schatz und bringt ihn mir. Nutzt die Piratenhöhle, wenn Ihr Eure Diebeskunst üben wollt, aber seid vorsichtig!", progress = "Na, wenigstens habt Ihr noch alle Eure Körperteile beisammen. Habt Ihr den Schatz gefunden?", completion = "Unglaublich! Unwahrscheinlich! Einfach erstaunlich! Ihr habt Talent, &lt;Name&gt;. Entweder das oder Ihr habt ein Glück wie niemand sonst auf der Welt!\n\nHier ist Euer Anteil an der ganzen Sache. Ich bin sicher, Ihr könnt das alles besser verwenden als ich.", rewards = "Ihr bekommt:\n\nDisteltee"},
[2382] = {title = "Wrenix aus Ratchet", objective = "Reist nach Ratchet und sprecht mit Wrenix dem Jämmerlichen.", description = "Zando'zan hat es gesehen! Ja, der Tag wird kommen! Thralls Tod... der Dolch in seinem Rücken, das Gift, das durch seine Adern fließt... Zando'zan hat schon zu viel gesagt.\n\n<Name>! Zando'zan hat eine Aufgabe für <Name>! <Name> muss nach Ratchet reisen, im Osten von Crossroads, und mit Wrenix dem Jämmerlichen sprechen. Los!", progress = nil, completion = "Noch einer? Die letzten fünf, die dieser verrückte Troll mir geschickt hat, endeten als Haifutter. Wollen wir hoffen, dass es Euch etwas besser ergeht, wie?", rewards = "Ihr bekommt:\n\n"},
[2383] = {title = "Einfaches Pergament", objective = "Lest das einfache Pergament und sprecht mit Frang im Tal der Prüfungen.", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, <Name>.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Kriegerlehrer Frang. Er würde gern mit Euch sprechen, wenn Ihr bereit seid. Ihr findet ihn außerhalb des Höhlenbaus, wo er sich in den Schatten verbirgt.", progress = "Was habt Ihr denn da? Ein Pergament? Ich hoffe, Ihr seid kein Gelehrter...", completion = "Ach, da ist ja mein Pergament. Ich habe gehört, dass Ihr ins Tal kommen würdet, &lt;Name&gt;. Freut mich zu sehen, dass Ihr es geschafft habt - hoffen wir nur, dass Ihr die Prüfungen überlebt, die vor Euch liegen. Wie ich bereits sagte: Wenn Eure Macht wächst, kommt zu mir - ich werde tun, was ich kann, um Euch weiter in der Kunst eines Kriegers auszubilden.\n\nViel Glück, &lt;Name&gt;. Ihr könnt jederzeit wieder zu mir kommen, wenn Ihr Euch bereit fühlt.", rewards = "Ihr bekommt:\n\n"},
[2398] = {title = "Die verschollenen Zwerge", objective = "Sucht in Uldaman nach Baelog.", description = "Die Grabungsstätte von Uldaman war nicht immer so überlaufen. Wir Zwerge von Ironforge kontrollierten früher das Gebiet, aber... das war, bevor die Troggs kamen. Sie kamen so schnell und waren so zahlreich, dass nicht einmal die Macht der Zwerge sie aufhalten konnte.\n\nUm ehrlich zu sein, kam ihr Angriff so plötzlich, dass ich fürchte, dass vielleicht einige unserer Leute hinter den feindlichen Linien festsitzen.\n\nMein Freund Baelog hatte eine kleine Gruppe Zwerge tief hinunter in die Grabungsstätte geführt, kurz bevor die Troggs auftauchten. Wenn er und seine Gefährten noch leben, dann möchte ich, dass Ihr sie findet.", progress = nil, completion = "Wurde auch Zeit, dass ihr auftaucht! Ich hätte fast meine Wette mit Olaf verloren!\n\nEr hat gewettet, dass ihm sein Bart bis zu den Knien wachsen würde, ehe ihm wieder ein &lt;Volk&gt; vor die Augen kommen würde. Aber jetzt seid Ihr hier, und wie Ihr sehen könnt, fehlen Olafs Bart noch ein paar Zoll.\n\nDanke, &lt;Name&gt;. Ich werde den Gewinn mit Euch teilen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2399] = {title = "Die sprießenden Wedel", objective = "Die Wedel, die Denalan in seinem Garten angepflanzt hat, sind gesprossen und gediehen. Sie zittern leicht, als wollten sie gepflückt werden...", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSprießender Wedel"},
[2418] = {title = "Kraftsteine", objective = "Bringt Rigglefuzz im Ödland 8 Kraftsteine aus Dentrium und 8 Kraftsteine aus An'Alleum.", description = "Vor einiger Zeit hatte ich einen kleinen Zwischenfall mit den Zwergen der Schattenschmiede. Sie brachten mich in die Festung Angor, um dort zwei Arten von seltsamen Steinen zu untersuchen, wie sie in Uldaman vorkommen. Ich habe entdeckt, dass die Steine langlebige und stabile Kraftquellen darstellen, wenn sie richtig behandelt werden. Es ist schon erstaunlich, was man alles in dieser alten Grabungsstätte finden kann!\n\nJedenfalls warfen sie mich aus der Festung Angor raus, nachdem ich ihnen das Geheimnis der Steine verraten hatte, und begannen, in Uldaman nach weiteren Steinen zu graben.\n\nIch will diese Steine für mich! Bringt mir beide Arten von Steinen und ich bezahle Euch gut dafür!", progress = "Habt Ihr die Kraftsteine, <Name>? Ich habe hier ein Robotnagetier, das eine Stromquelle braucht...", completion = "Oh prima, Ihr habt welche gefunden! Vielen Dank, &lt;Name&gt;. Ihr seid der verlässlichste &lt;Volk&gt;, den ich je getroffen habe!\n\nIch kann es kaum erwarten, sie an einigen der Geräte auszuprobieren, an denen ich rumgebastelt habe. Ich wette, dass unter den richtigen Umständen ein Gerät, das mit so einem Stein angetrieben wird, läuft und läuft und läuft ...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nEnergiegeladener SteinkreisDuracin-ArmschienenEwige Stiefel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[2438] = {title = "Der smaragdgrüne Traumfänger", objective = "Bringt den smaragdgrünen Traumfänger zu Tallonkai Swiftroot in Dolanaar.", description = "Einst erhielt ich von Gaerolas Talvethen, dem Bewacher der Druiden im Grabhügel von Ban’ethil, einen smaragdgrünen Traumfänger. Dieses mächtige Amulett ist in der Lage, Energie aus dem Smaragdgrünen Traum abzuziehen und damit denen, die es tragen, Glück zu bringen.\n\nLeider habe ich den Traumfänger nicht mehr aus meiner Kommode in Starbreeze holen können. Starbreeze war einst ein ruhiger Ort, aber jetzt ist er durch die Furbolgs, die sich dort aufhalten, der Verderbnis anheim gefallen.\n\nWärt Ihr vielleicht bereit, mir meinen Traumfänger wiederzubeschaffen, <Klasse>?", progress = "Bitte sputet Euch. Ich kann nur hoffen, dass mein smaragdgrüner Traumfänger von den Furbolgs nicht beschädigt wurde.\n\nHabt Ihr ihn schon zurückgeholt, <Name>?", completion = "Mein smaragdgrüner Traumfänger ist mir äußerst wichtig. Er ist ein Geschenk, das nicht jedem zuteil wird. Danke, dass Ihr ihn zurückgebracht habt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[2439] = {title = "Die Platinscheiben", objective = "Bringt Euren Belohnungsgutschein zu Dinita Stonemantle im Gewölbe von Ironforge.", description = "Dieser Gegenstand ist ein unglaublicher Fund. Die alten Titanen oder 'Schöpfer', wie sie auf diesen Scheiben genannt werden, sind die Verbindung zu unserer verzauberten Erschaffung, wenn das hierin gespeicherte Wissen korrekt ist! Wir werden uns so eingehend wie möglich mit diesen Scheiben beschäftigen.\n\nWas Euch betrifft, <Klasse>: Bringt diesen Gutschein zu Dinita Stonemantle in dem Gewölbe. Für ihn erhaltet Ihr etwas, das meiner Meinung nach eines solch unglaublichen Fundes würdig ist.\n\nKehrt umgehend zu mir zurück, wenn Ihr fertig seid - es gibt noch viel mehr für die Forscherliga zu tun!", progress = "Willkommen im Gewölbe von Ironforge, <Name>. Was kann ich heute für Euch tun?", completion = "Ah ja, ein Gutschein von der Forscherliga... und recht wertvoll, kann man sagen.\n\nEntsprechend dem Auftrag der Forscherliga kann ich Euch bei Eurer Belohnung die Wahl zwischen diversen aus ihrem Gewölbe stammenden Dingen lassen. Zum einen sollt Ihr diesen Gegenstand erhalten, und zum anderen dürft Ihr Euch entscheiden, ob Ihr fünf überragende Heiltränke oder fünf große Manatränke haben möchtet.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nÜberragender HeiltrankGroßer Manatrank\n\nIhr bekommt außerdem:\n\nTaupelzsack"},
[2440] = {title = "Die Platinscheiben", objective = "Bringt den Belohnungsgutschein zu Bena Winterhoof nach Thunder Bluff.", description = "Ich werde all meine Energien auf diese Scheiben fokussieren; wenn die Zeit gekommen ist, werden sie mir ihre Funktionsweise schon verraten.\n\nWas Euch betrifft, <Name>, nun, Ihr sollt dafür belohnt werden, dass Ihr mir diese Sache kundgetan habt. Bringt den Belohnungsgutschein zu Bena Winterhoof, der Alchimielehrerin in Thunder Bluff. Sie wird Euch einen speziellen Gegenstand geben, der Euch bestimmt gefällt, und außerdem erhaltet Ihr von ihr eine Auswahl an Tränken aus meinem persönlichen Vorrat.\n\nKehrt bald zu mir zurück ... ich spüre, dass wir in Bezug auf diesen Fund noch viel mehr zu tun haben.", progress = "Grüße, <Klasse>! Seid Ihr hier, weil Ihr eine Ausbildung in Alchimie wünscht, oder aus einem anderen Grund?", completion = "Na, &lt;Name&gt;, Ihr müsst Sage Truthseeker ja eine große Freude gemacht haben, dass er Euch diesen Gegenstand überlässt. Außerdem sollt Ihr zur Belohnung aus seinem Vorrat an Tränken auswählen dürfen: entweder 5 überragende Heiltränke oder 5 große Manatränke.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nÜberragender HeiltrankGroßer Manatrank\n\nIhr bekommt außerdem:\n\nTaupelzsack"},
[2458] = {title = "Undercover", objective = "Reist zum Turm der Venture Company nördlich des Schlickermoores und kontaktiert dort den Agenten der Shattered-Hand, Zuchtmeister Fizzule.\n\nSobald der Turm in Sichtweite ist, verwendet die Leuchtfeuerwaffe, um Zuchtmeister Fizzule Eure Ankunft anzuzeigen. Feuert ZWEI Leuchtfeuergeschosse ab, nähert Euch dann Zuchtmeister Fizzule und zeigt den Gruß der Shattered-Hand.\n\nEs ist wichtig, dass Ihr diese Aktionen in der richtigen Reihenfolge durchführt, da Fizzule jede Person, die er nicht erkennt, angreift und eliminiert.\n\nBereitgestellter Gegenstand: \n", description = "Die Venture Company... Vielleicht habt Ihr von den Leuten schon gehört?\n\nEin Jahr lang haben wir daran gearbeitet, einen Agenten in ihre Reihen einzuschleusen. Endlich hatten wir - dank harter Arbeit und präziser Planung - Erfolg.\n\nVor kurzem haben wir jetzt gehört, dass die Venture Company irgendetwas Großes plant. Begebt Euch zum Turm der Venture Company nördlich des Schlickermoores und kontaktiert dort unseren Undercover-Agenten, Zuchtmeister Fizzule.\n\nSobald Ihr den Turm gefunden habt, verwendet diese Leuchtfeuerwaffe und grüßt ihn mit dem Gruß der Shattered-Hand.", progress = nil, completion = "Es ist ja schön, einen anderen Agenten der Shattered-Hand hier zu sehen, aber das mit dem Leuchtfeuer war vielleicht etwas zu viel des Guten.\n\nWenn Ihr das nächste Mal mit mir sprechen wollt, blast zweimal auf dieser Pfeife, dann weiß ich, dass Ihr ein Verbündeter seid.", rewards = "Ihr bekommt:\n\nFizzules Pfeife"},
[2459] = {title = "Ferocitas der Traumfresser", objective = "Tallonkai Swiftroot aus Dolanaar möchte, dass Ihr 7 Mystiker der Knarzklauen tötet und das verlorene Juwel findet.", description = "Der Smaragd... Er ist weg! Mein Traumfänger ist beschädigt!\n\nEine Gruppe von Knarzklauenmystikern lebt im Norden von Starbreeze. Ich habe gehört, dass ihr Anführer, Ferocitas der Traumfresser, seit einiger Zeit eine Halskette trägt, die des Nachts grün leuchtet. Jetzt, wo ich meinen Traumfänger sehe, bin ich mir sicher, dass er meinen Smaragd gestohlen hat... Er würde nie verstehen, dass dessen Macht völlig nutzlos für ihn ist.\n\nFindet das verlorene Juwel, <Name>. Und wenn Ihr schon mal dort seid, erledigt auch gleich einige dieser verderbten Mystiker.", progress = "Ferocitas und die Knarzklauenmystiker müssen mir zurückgeben, was mir gehört. Bitte holt den Smaragd zurück, damit ich meinen smaragdgrünen Traumfänger reparieren kann.", completion = "Jetzt kann ich meinen Traumfänger reparieren. Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[2460] = {title = "Der Shattered-Gruß", objective = "Führt Shenthul gegenüber den Shattered-Gruß aus.", description = "Als ein Schurke der Shattered-Hand müsst Ihr unbedingt den Shattered-Gruß erlernen. Dies ist die einzige Methode, mit der man ein anderes Mitglied der Hand zweifelsfrei identifizieren kann.\n\nSchaut zu, lernt, wiederholt.", progress = "Übung macht den Meister!", completion = "Gut gemacht, &lt;Name&gt;. Jetzt kann es weitergehen.", rewards = "Ihr bekommt:\n\n"},
[2478] = {title = "Mission: möglich, aber nicht sehr wahrscheinlich", objective = "Stehlt Silixiz' Turmschlüssel von Großknecht Silixiz. Tötet dann 2 mutierte Drohnen der Venture Co., 2 Patrouillen der Venture Co. und 2 Ausgucker der Venture Co.\n\nEliminiert den obersten Großknecht Gallywix und nehmt seinen Kopf. Knackt dann das Schloss von Gallywix' Schließkassette und stehlt den Vorrat an Zanzils veränderter Mixtur. Bringt den Vorrat und Gallywix' Kopf zu Shentul nach Orgrimmar; er wird Euch weitere Anweisungen geben.", description = "Ihr müsst den Turmschlüssel von Großknecht Silixiz stehlen, <Name>. Sobald sich der Schlüssel in Eurem Besitz befindet, haltet ihn gut fest - ich könnte ihn später brauchen.\n\nVergesst nicht, das Gift hat alles in diesem Turm geschwächt. Wendet Eure Fähigkeiten an, um unter seinen Bewohnern Chaos und Zerstörung zu verbreiten. Erschlagt sie alle - zeigt keine Gnade!\n\nSobald sich dort drinnen nichts mehr rührt, knackt Ihr das Schloss von Gallywix' Schließkassette und stehlt den Vorrat an Zanzils Mixtur, der sich darin befindet. Bringt Shenthul in Orgrimmar sowohl Gallywix' Kopf als auch die Mixtur.", progress = "Was gibt es zu berichten, <Name>?", completion = "Der arme Fizzule. Er war ein guter Agent, einer unserer besten. Doch das ist leider der Preis, den wir zahlen müssen, &lt;Name&gt;. Ein Außenagent der Shattered-Hand zu sein, ist sehr gefährlich.\n\nIhr habt Eure Befehle gut ausgeführt, &lt;Klasse&gt;. Es wäre ein Jammer, wenn Ihr nicht überleben würdet, um uns erneut zu dienen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nRezept: Disteltee"},
[2479] = {title = "Hinotts Hilfe", objective = "Reist nach Tarrens Mühle im Vorgebirge von Hillsbrad und liefert die Probe von Zanzils Mixtur bei Serge Hinott ab.\n\nUm nach Tarrens Mühle zu kommen, müsst Ihr den Zeppelin nach Undercity nehmen und dann auf der Straße nach Süden durch den Silberwald in Richtung Hillsbrad reisen. Folgt den Schildern!", description = "Bringt eine Probe der Mixtur zu Serge Hinott nach Tarrens Mühle.\n\nWenn Euch überhaupt irgendjemand heilen kann, dann ist das Serge. Falls Ihr lange genug lebt, kann Serge Euch in der Kunst der Herstellung und Anwendung von Giften unterweisen.", progress = "Was haben wir denn hier?", completion = "Ihr seht so herrlich blass aus, &lt;Klasse&gt;. Und was für ein fauliger Duft umgibt Euch da? Ich muss es wissen!", rewards = "Ihr bekommt:\n\n"},
[2480] = {title = "Hinotts Hilfe", objective = "Wartet auf Serge Hinott, um das Heilmittel fertig zu stellen.", description = "Noch nie habe ich gesehen, dass ein Gift so wundervolle Auswirkungen hatte! Zanzil, sagt Ihr? Nie von ihm gehört. Aber ich muss ihm zur Kreation dieses Gebräus gratulieren.\n\nTja, ich soll Euch also hiervon heilen und Euch dann beibringen, wie man das Gift anwendet?\n\nGebt mir einen Moment Zeit, damit ich das Toxin untersuchen kann, <Name>.", progress = nil, completion = "Das Heilmittel ist fertig! Trinkt dieses Antitoxin, dann hört der schleichende Wahnsinn auf. Doch gegen den Geruch kann ich nichts tun.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGifte\n\nIhr bekommt:\n\nHinotts Öl"},
[2498] = {title = "Rückkehr zu Denalan", objective = "Rellian Greenspyre möchte, dass Ihr am Al'Amethsee mit Denalan sprecht.", description = "Ich habe gerade erfahren, dass Denalan am Al'Amethsee herausgefunden hat, was der Grund für die Tumore sein könnte, von denen die Bäumlinge befallen sind. Bitte sprecht mit ihm und sagt ihm, dass ich Euch geschickt habe.\n\nSputet Euch, <Name>; er braucht unsere Hilfe.", progress = nil, completion = "Ah, Rellian hat Euch also geschickt. Es freut mich, dass Ihr so schnell gekommen seid.\n\nIch habe eine ziemlich erschreckende Entdeckung gemacht!", rewards = "Ihr bekommt:\n\n"},
[2499] = {title = "Grimmeiche", objective = "Denalan vom Al'Amethsee möchte, dass Ihr den riesengroßen Tumor von Grimmeiche einsammelt.", description = "In einer Höhle am Südufer des Sees überträgt ein Bäumling namens Grimmeiche die Verderbnis auf alle Wesen, die am Al'Amethsee leben.\n\nIch habe mich nicht allzu nah herangewagt, aber selbst aus der Entfernung ist eines ganz klar: Grimmeiche wird von dem größten Tumor vergiftet, den ich je gesehen habe. Ich würde sogar sagen, er ist nicht nur groß, er ist riesengroß.\n\nIhr habt schon viel getan, um mir zu helfen, <Name>, und doch möchte ich Euch um einen weiteren Gefallen bitten. Spürt Grimmeiche auf und holt den Tumor. Entfernt diese Quelle der Verderbnis aus meiner Heimat!", progress = "Habt Ihr Grimmeiche schon gefunden, <Volk>?", completion = "Ich wusste doch, dass Ihr bestens in der Lage sein würdet, den See von dieser schrecklichen Bestie zu befreien.\n\nEs ist schon traurig: Einst war Grimmeiche ein großer Anführer unter seinesgleichen... Aber die Verderbnis unterscheidet leider nicht zwischen dem Geringen und dem Edlen.\n\nDie Größe dieses Tumors ist erschreckend. Aber ich muss ihn studieren, um mehr über diese Seuche herauszufinden, von der alle Bäumlinge betroffen sind.\n\nDanke, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchmutzholz-GürtelMoosbedeckte Stulpen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[2500] = {title = "Reagenzien-Suche im Ödland", objective = "Beschafft die Reagenzien, die Ghak Healtouch aus dem Ödland braucht, und bringt sie ihm nach Thelsamar.", description = "<Klasse>, ich möchte Eure Dienste in Anspruch nehmen. Ich bin ein angesehener Alchimist und benötige Eure Unterstützung, um einige Reagenzien zu beschaffen, die im Ödland zu finden sind.\n\nIch brauche folgende Gegenstände, um meine Vorräte aufzufüllen: 5 Bussard-Muskelmägen, 10 Klippenkojotenfangzähne und 5 Felselementarsplitter. Natürlich könnt Ihr Euch diese Reagenzien von den Viechern selbst holen; aber wenn Ihr keine Kämpfernatur seid, dann sucht Euch besser Freunde, die kämpfen können.\n\nBringt mir diese Gegenstände, dann springen ein paar Münzen für Euch dabei heraus.\n\nAlso, was sagt Ihr?", progress = "Habt Ihr die Sachen schon, die ich brauche? Ihr werdet nur bezahlt, wenn Ihr mir diese Reagenzien bringt.", completion = "Ah, gut gemacht, &lt;Name&gt;. Das sollte eine Weile reichen. Hier ist Eure Bezahlung, wie versprochen.\n\nFalls Ihr interessiert seid: Es gibt da noch ein paar Reagenzien mehr, die ich brauchen könnte. Die findet man allerdings nur in den Tiefen der Ausgrabungstätte von Uldaman. Sie werden nicht leicht zu beschaffen sein, aber wenn Ihr mir nochmals helfen wollt, soll es sich für Euch lohnen.\n\nVielleicht möchtet Ihr ja etwas mehr als nur glänzende Münzen, hm?", rewards = "Ihr bekommt:\n\n"},
[2501] = {title = "Reagenzien-Suche im Ödland II", objective = "Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Ghak Healtouch in Thelsamar.", description = "Ihr seid mir eine große Hilfe gewesen, <Name>. Ich würde Euch gern das Rezept des Gebräus geben, das Ihr vorhin gekostet habt... doch zuvor muss ich Euch um einen recht gefährlichen Gefallen bitten.\n\nDiese Schließkassette enthält drei leere thaumaturgische Gefäße; sie sind mit einer Einstellungs-Aura magieerfüllt, die einem versengten Wächtergroßdrachen das Blut aussaugt. Wenn Ihr ein solches Gefäß gegen die Bestie einsetzt, wird sie höchst erbost reagieren, also seid vorsichtig. Bringt sie mir, wenn Ihr alle drei gefüllt habt.\n\nGelingt Euch das, gehört das Rezept Euch.", progress = "Habt Ihr die Gefäße benutzt, um das Blut versengter Wächtergroßdrachen zu beschaffen, das ich brauche? Ja, ich weiß, es ist eine gefährliche Aufgabe... aber das Rezept für mein Regenerierungsgebräu ist der Lohn Eures Erfolges. Von nichts kommt eben nichts, mein Freund... Von nichts kommt nichts...", completion = "Ich grüße Euch von Alchimist zu Alchimist. Hier, nehmt das Rezept und reiht es Eurem Wissen ein. Möge es Euch denselben Erfolg und dieselben Belohnungen bringen wie mir im Lauf der Jahre!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRegenerationstrank\n\nIhr bekommt:\n\n"},
[2518] = {title = "Tränen des Mondes", objective = "Priesterin A'moora vom Tempel des Mondes in Darnassus möchte, dass Ihr ihr Lady Sathrahs silbrige Spinndrüsen bringt.", description = "Einst wurde Lady Sathrah von Elune geliebt. Grazil und rein spann die Spinne ihre silbernen Fäden im Mondlicht, wo sie den Abendnebel einfingen. Der silbrige Tau hatte starke Heilkräfte und wurde darum hier im Tempel aufbewahrt.\n\nDoch in jüngster Zeit ist Sathrah dem Wahnsinn verfallen. Auch die ihr nachfolgenden Generationen sind nun gefährdet.\n\nFindet Lady Sathrah, <Name>, und beendet ihr Leiden. Sie hält sich an der nördlichen Grenze von Teldrassil auf, in der Nähe des Wellspringsees. Sammelt ihre silbrigen Spinndrüsen und bringt sie mir.", progress = "Ich bedauere, dass ich Euch die Aufgabe stellen musste, die ich Euch gestellt habe, aber für Lady Sathrah gibt es keine Hoffnung mehr.\n\nMit den Spinndrüsen wollen wir Elune ein Opfer bringen. Wir hoffen, dass Elune aufgrund dieses Opfers Sathrah segnen wird, damit sie wiedergeboren werden und endlich Frieden finden kann.", completion = "Der Wald trauert um Lady Sathrah, doch es musste getan werden.\n\nDanke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[2519] = {title = "Der Tempel des Mondes", objective = "Schwester Aquinne möchte, dass Ihr im Tempel des Mondes mit Priesterin A'moora sprecht.", description = "Ein einstmals großes Wesen des Waldes benötigt Hilfe, <Volk>.\n\nEine schwierige Aufgabe muss getan werden.\n\nBitte sucht Priesterin A'moora auf: Sie wird Euch alles erklären. Ihr findet sie südöstlich von hier im Tempel des Mondes.", progress = nil, completion = "Schwester Aquinne hat Euch also geschickt?", rewards = "Ihr bekommt:\n\n"},
[2520] = {title = "Sathrahs Opferung", objective = "Priesterin A'moora möchte, dass Ihr Lady Sathrahs silbrige Spinndrüsen am Brunnen innerhalb des Tempels ablegt und dann zu ihr zurückkehrt.", description = "Jetzt müsst Ihr die Aufgabe vollenden, die Euch auferlegt worden ist. Nehmt die Spinndrüsen und bringt Elune Lady Sathrahs Opfer dar. Verschafft der großen Spinne die ewige Ruhe.\n\nBegebt Euch zum zentralen Brunnen in diesem Tempel. Dort könnt Ihr das Opfer niederlegen. Die heiligen Wasser werden die Verderbnis, durch die Sathrah in den Wahnsinn getrieben wurde, läutern und säubern.\n\nKommt zu mir zurück, sobald Ihr dies erledigt habt.", progress = "Habt Ihr das Opfer am Brunnen abgelegt, <Name>?", completion = "Es stimmt mich traurig, dass wir Lady Sathrah verloren haben, aber nur so kann sie mit erneuertem Geist wiedergeboren werden.\n\nMöge Elune gnädig das Opfer annehmen, das Ihr ihr geweiht habt!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSpitzenhoseGepolsterte Stiefel\n\nIhr bekommt außerdem:\n\n"},
[2521] = {title = "Ein Dienst für Kum'isha", objective = "Falls Ihr auf Euren Reisen durch die verwüsteten Lande je auf eine fehlerlose Draenethystsphäre stoßen solltet, bringt sie zu Kum'isha dem Sammler.\n\nDoch seid gewarnt. Der Edelstein ist einer der rarsten Kristalle von ganz Azeroth. Jedes Wesen in diesem Land könnte eine fehlerlose Draenethystsphäre bei sich haben.\n\nIhr erhaltet eine Belohnung für jede fehlerlose Draenethystsphäre, die Ihr beschaffen könnt.", description = "<Volk>, kann Euer winziges Gehirn überhaupt verstehen, wie selten eine völlig fehlerlose Draenethystsphäre ist? Viele Draenei haben ihr ganzes Leben damit verbracht, auch nur einen einzigen solchen Kristall zu finden, und keiner, der es versuchte, konnte sein Vorhaben je ausführen. Alle sind eines schrecklichen Todes gestorben.\n\nUnd nun steht Ihr vor Kum'isha, wissend, was Kum'isha wünscht, und Ihr möchtet dennoch behilflich sein? Nun gut, <Volk>... Solltet Ihr auf Euren Reisen durch die Lande irgendwann auf eine fehlerlose Draenethystsphäre stoßen, dann bringt sie mir, und ich belohne Euch mit Reichtümern, wie Ihr sie Euch niemals erträumen könnt.", progress = "Ich habe mein Leben der Suche nach fehlerlosen Draenethystsphären gewidmet. Mein ganzes Leben, <Volk>!", completion = "Täuschen mich meine Augen? Unmöglich! Wo habt Ihr... Wie...\n\nVielleicht kann jetzt ein neuer Riss geöffnet werden, der es uns ermöglicht, in unsere Heimat zurückzukehren...", rewards = "Ihr bekommt:\n\nSmaragdbesetzte Truhe"},
[2522] = {title = "Kum'ishas Bemühungen", objective = "Findet eine fehlerlose Draenethystsphäre und bringt sie Kum'isha dem Sammler.", description = "Obwohl die Herbeizauberung des Portals fehlgeschlagen ist, hoffe ich doch weiterhin, dass ich mit meinem nächsten Versuch Erfolg haben werde.\n\nDie Hoffnung der Draenei ist ebenso groß wie Eure Gier nach Tand, <Volk>. Begebt Euch wieder hinaus in dieses verfluchte Land und beschafft mir eine weitere fehlerlose Draenethystsphäre.\n\nNatürlich liegt es ganz allein an Euch, ob Ihr diese Aufgabe annehmen wollt oder nicht... <grinst>.", progress = "Habt Ihr noch eine fehlerlose Draenethystsphäre gefunden?", completion = "Einfach erstaunlich. Ich hatte so meine Zweifel, dass Ihr noch eine Sphäre finden würdet, aber hier ist sie und pulsiert in meinen Händen.\n\nGut gemacht, &lt;Name&gt;!\n\nSolltet Ihr noch weitere Sphären finden - wobei ich glaube, dass das unmöglich ist -, dann bringt sie mir und ich werde Euch erneut belohnen.", rewards = "Ihr bekommt:\n\nSmaragdbesetzte Truhe"},
[2523] = {title = "Verderbte Liedblume", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[2541] = {title = "Der schlafende Druide", objective = "Bringt einen Voodooglücksbringer des Schamanen zu Oben Zornklaue in den Grabhügel von Ban'ethil.", description = "Die hier lebenden Schamanen der Knarzklauen haben einen Weg entdeckt, wie man den Geist eines schlafenden Druiden von seinem Körper trennen kann. Die Furbolgs haben meinen physischen Körper reanimiert und lassen ihn jeden angreifen, der versucht, den Grabhügel von Ban'ethil zu erforschen. Ich selbst bin im Smaragdgrünen Traum gefangen und kann diesem Treiben keinen Einhalt gebieten.\n\nIhr müsst mir helfen. Alle Knarzklauenschamanen tragen einen seltsamen Glücksbringer bei sich, mit dem dieses Ritual durchgeführt wird, und ich würde einen solchen Glücksbringer gern untersuchen. Bitte, <Name>, bringt mir einen.", progress = "Wenn ich den Glücksbringer untersuchen kann, gelingt es mir vielleicht, die Verzauberung zu brechen. Habt Ihr einen gefunden?", completion = "Danke, &lt;Name&gt;.\n\nWas für ein seltsamer Gegenstand das doch ist... Ich kann die üble Aura spüren, die von ihm ausgeht: eine mächtige Verzauberung.", rewards = "Ihr bekommt:\n\n"},
[2561] = {title = "Druide der Klaue", objective = "Oben Zornklaue möchte, dass Ihr seinen seelenlosen Körper tötet und dann den Voodooglücksbringer anwendet.", description = "Nachdem ich den Glücksbringer untersucht habe, weiß ich jetzt, was zu tun ist, <Name>. Bitte nehmt ihn, und tut das, worum ich Euch bitte.\n\nIhr müsst die tiefsten Tiefen des Grabhügels von Ban'ethil erforschen. Dort findet Ihr meinen seelenlosen Körper. Und obwohl es mich sehr schmerzt, Euch das jetzt zu sagen, sehe ich keine andere Möglichkeit, wie ich mich der Kontrolle der Knarzklauen entziehen kann.\n\nDamit ich mich von ihnen befreien kann, müsst Ihr meinen physischen Körper töten. Sobald das getan ist, wendet den Voodooglücksbringer auf meinen gefallenen Körper an. Und wenn Ihr diese Aufgabe erfüllt habt, kommt zu mir zurück.", progress = "<Name>, seid vorsichtig, wenn Ihr Euch meinem Körper nähert: Die Verzauberung, der er unterliegt, ist sehr mächtig.", completion = "Ich habe mich endlich der Kontrolle der Knarzklauen entzogen. Danke, &lt;Name&gt;.\n\nNun kann mein Geist auf immer friedlich im Smaragdgrünen Traum verweilen.\n\nVielleicht treffen wir uns eines Tages wieder, junger Freund. Doch zunächst nehmt bitte diese Belohnung als Zeichen meiner Dankbarkeit an.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchlaf-RobenBuschklinge\n\nIhr bekommt außerdem:\n\n"},
[2581] = {title = "Kicherfangunterkiefer", objective = "Bringt Blutmagier Drazial 3 Kicherfangunterkiefer, 2 feuerverbrannte Eberlungen und 1 Skorpokzange.", description = "Es ist eine wohl bekannte Tatsache, dass Hyänen unglaubliche Kraft in ihrem Unterkiefer haben, aber drei Zoll Thoriumstahl durchbeißen? Unmöglich, völlig unwahrscheinlich, und dennoch habe ich es mit meinen eigenen Augen gesehen.\n\nWagt Euch hinaus in die verwüsteten Lande und bringt mir drei Kicherfangunterkiefer. Und während Ihr nach den Kicherfanghyänen sucht, haltet auch nach Ebern und Skorpoks Ausschau, denn für die erste Zubereitung der Inhaltsstoffprobe benötige ich auch zwei feuerverbrannte Eberlungen und eine Skorpokzange.", progress = "Ihr stinkt, <Name>. Habt Ihr Euch in einem Schwefelfeld herumgetrieben? Und wo sind meine Komponenten?!", completion = "Wie fühlt Ihr Euch, &lt;Name&gt;? Ihr strahlt die Aura der Kicherfanghyänen aus - eine Kraft, die kein Sterblicher erreichen kann!\n\nLeider konnte ich mit den Komponenten, die Ihr mir gebracht habt, nur so viel von der Inhaltsstoffprobe herstellen, dass es gerade für eine Tablette reichte. Falls Ihr eine weitere Tablette benötigt, benötige ich weitere Komponenten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWut der Zeiten\n\nIhr bekommt:\n\nR.O.I.D.S."},
[2582] = {title = "Wut der Zeiten", objective = "Bringt Blutmagier Drazial 3 Kicherfangunterkiefer, 2 feuerverbrannte Eberlungen und 1 Skorpokzange.", description = "Ah, <Name>, willkommen. Es scheint, als habe es Euch gefallen, so von Kraft erfüllt und handlungsfähig zu sein, wie es durch die Wirkung der Kicherfangdroge möglich wurde. Doch seid gewarnt: Zwar zeigt sich unmittelbar nach der Einnahme des Präparates ein gigantischer Stärkeschub, doch auf lange Sicht gesehen könnte das Mittel nachteilige Auswirkungen auf Euren Geist und Eure Intelligenz haben.\n\nUnd jetzt, wo Ihr dies wisst - braucht Ihr noch mehr? Falls ja, dann bringt mir drei weitere Kicherfangunterkiefer, zwei feuerverbrannte Eberlungen und eine Skorpokzange.", progress = "Habt Ihr die Organe der Bestien?", completion = "Bitte sehr... Und verwendet sie sehr sparsam. Falls Ihr noch eine brauchen solltet, dann kommt wieder zu mir, nachdem Ihr die aufgebraucht habt, die sich momentan in Eurem Besitz befindet.", rewards = "Ihr bekommt:\n\nR.O.I.D.S."},
[2583] = {title = "Lebenskraft des Ebers", objective = "Bringt Blutmagier Drazial 3 feuerverbrannte Eberlungen, 2 Skorpokzangen und 1 Basiliskengehirn.", description = "Hier in den verwüsteten Landen leben zwei Arten von Ebern: der Aschmähneneber und der Hölleneber.\n\nEs scheint, als mache die Ausdauer dieser Wildtiere sie so gut wie völlig immun gegen Schaden jeglicher Art, da die anderen Tiere zu große Schwierigkeiten haben, sie zu töten, und daher in Ruhe lassen.\n\nWir müssen weitere Analysen durchführen, <Name>. Wenn Ihr mir drei feuerverbrannte Eberlungen, zwei Skorpokzangen und ein Basiliskengehirn bringt, dann werde ich aus den Überresten der Inhaltsstoffprobe ein himmlisches Elixier kreieren. Und Ihr seid mein erstes Versuchsobjekt!", progress = "Wo sind die Organe, <Name>!?", completion = "Der Geist des Ebers erleuchtet Euer Wesen, &lt;Name&gt;! Ich frage mich, ob Ihr Euch wohl ebenso unverwundbar fühlt wie jene Bestien...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGeist des Ebers\n\nIhr bekommt:\n\nLungensaft-Cocktail"},
[2584] = {title = "Geist des Ebers", objective = "Bringt Blutmagier Drazial 3 feuerverbrannte Eberlungen, 2 Skorpokzangen und 1 Basiliskengehirn.", description = "Schon als ich das Elixier zum ersten Mal einsetzte, konnte ich sehen, dass eine oder zwei Anwendungen Euer Verlangen danach nicht stillen würden, <Name>. Selbst jetzt bleibt mir die Gier in Euren Augen nicht verborgen. Das Gebräu hat suchterzeugende Eigenschaften, denen, so scheint es, noch nicht einmal jemand mit äußerst starkem Willen widerstehen kann.\n\nSo sei es denn! Solltet Ihr mehr von dem Lungensaft-Cocktail benötigen, dann wagt Euch wieder hinaus ins Ödland und besorgt mir drei feuerverbrannte Eberlungen, zwei Skorpokzangen und ein Basiliskengehirn.", progress = "Wo sind die Organe, <Name>!?", completion = "Ich muss Euch warnen, &lt;Name&gt;. Versucht nicht, die Rezepturen, die ich geschaffen habe, miteinander zu vermischen. Die chemischen Eigenschaften des Mittels, das Ihr als Letztes eingenommen habt, werden vorherige Verzauberungen immer neutralisieren, sodass die Wirkung der vorigen Rezeptur umgehend verfliegt.", rewards = "Ihr bekommt:\n\nLungensaft-Cocktail"},
[2585] = {title = "Der Entscheidungsschlag", objective = "Bringt Blutmagier Drazial 3 Skorpokzangen, 2 Geiermuskelmägen und 1 feuerverbrannte Eberlunge.", description = "Habt Ihr jemals gesehen, wie sie kämpfen, <Name>? Die Skorpoks, meine ich. Habt Ihr jemals die Anmut und Gewandtheit ihrer Bewegungen gesehen? Gesehen, wie entschlossen sie zuschlagen?\n\nWenn wir nur irgendwie diese Beweglichkeit einfangen und für uns nutzbar machen könnten, dann würden wir so reich werden, wie... ähem, dann wäre das ein unschätzbarer Segen für die wissenschaftliche Gemeinschaft, meine ich natürlich.\n\nHelft mir, <Name>, dann lasse ich Euch auch von der fertigen Inhaltsstoffprobe kosten.\n\nUm eine reaktionsstabile Probe herzustellen, benötige ich drei Skorpokzangen, zwei Geiermuskelmägen und eine feuerverbrannte Eberlunge.", progress = "Wo sind die Organe, <Name>!?", completion = "Faszinierend. Keine der bisher untersuchten Inhaltsstoffproben war so schwierig zu analysieren.\n\nNehmt eine Prise von dem Salz, das übrig geblieben ist, und streut es unter Eure Zunge. Ihr solltet ein leichtes Hochgefühl verspüren und anschließend einen Zustand von bislang unerreichter Beweglichkeit und Schnelligkeit erlangen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nStoß des Skorpoks\n\nIhr bekommt:\n\nGemahlene Skorpokinhaltsstoffprobe"},
[2586] = {title = "Salz der Skorpok", objective = "Bringt Blutmagier Drazial 3 Skorpokzangen, 2 Geiermuskelmägen und 1 feuerverbrannte Eberlunge.", description = "Ihr lebt noch! Das sind wahrlich gute Neuigkeiten. Ich vermute mal, Ihr seid wieder da, weil Ihr mehr von der Skorpokinhaltsstoffprobe möchtet?\n\nTja, <Name>, dann mal ab ins Ödland mit Euch, und kommt erst zurück, wenn Ihr drei Skorpokzangen, zwei Geiermuskelmägen und eine feuerverbrannte Eberlunge eingesammelt habt.", progress = "Wo sind die Organe, <Name>!?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Hier ist eine Dosis der Inhaltsstoffprobe für Euch. Die übrigen neun werde ich für meine Forschungen nutzen.\n\nFalls Ihr mehr von der gemahlenen Skorpokinhaltsstoffprobe braucht, kommt zu mir zurück. Wir werden uns dann schon handelseinig.", rewards = "Ihr bekommt:\n\nGemahlene Skorpokinhaltsstoffprobe"},
[2601] = {title = "Der Biss des Basilisken", objective = "Bringt Blutmagierin Lynnore 10 Basiliskengehirne und 2 Geiermuskelmägen.", description = "In der Einöde wimmelt es nur so von Rotsteinbasilisken, <Name>. Diese Basilisken haben sich an ihre Umgebung angepasst und sind in ihr gediehen, mehr als jede andere wilde Tierart in diesem Gebiet.\n\nIch habe sie schon oft von weitem beobachtet, wenn sie jagen und ihren täglichen Aktivitäten nachgehen: Diese Wildtiere zeigen Denkprozesse, die komplexer sind als die mancher Humanoiden!\n\nIch muss ihre Gehirne studieren!\n\nBringt mir zehn ihrer Gehirne, <Name>. Doch für das Präparat benötige ich auch zwei Geiermuskelmägen. Diese bilden die Grundlage der Lösung.", progress = "Habt Ihr mir die Organe gebracht, um die ich Euch gebeten hatte?", completion = "Das ist wunderbar, &lt;Name&gt;! Mein Geschenk an Euch ist eine Kostprobe des Innenlebens des Rotsteinbasilisken.\n\nSolltet Ihr das Präparat mögen, kann ich mehr davon herstellen... gegen einen bestimmten Preis.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUnfehlbare Gedanken\n\nIhr bekommt:\n\nZerebralkortexverbund"},
[2602] = {title = "Unfehlbare Gedanken", objective = "Bringt Blutmagierin Lynnore 10 Basiliskengehirne und 2 Geiermuskelmägen.", description = "Eure fokussierte Konzentration hat so schnell nachgelassen? Dann muss unbedingt weitergeforscht werden!\n\nAch ja, und der Preis ist noch immer derselbe, <Name>. Wagt Euch in die verwüsteten Lande hinaus und kommt mit zehn Rotsteingehirnen und zwei Geiermuskelmägen wieder.", progress = "Habt Ihr mir die Organe gebracht, um die ich Euch gebeten hatte?", completion = "Ja, ja, gebt mir noch einen Moment Zeit, dann habe ich gleich wieder etwas von dem Präparat für Euch bereit, &lt;Name&gt;.\n\nHier, bitte schön... und, &lt;Name&gt;, versucht nicht, diese experimentellen Gebräue in zu schneller Folge zu nehmen. Das könnte katastrophale Auswirkungen haben.", rewards = "Ihr bekommt:\n\nZerebralkortexverbund"},
[2603] = {title = "Lebensenergie des Geiers", objective = "Bringt Blutmagierin Lynnore 10 Geiermuskelmägen und 2 Kicherfangunterkiefer.", description = "Hier in den verwüsteten Landen besitzt der Tod tatsächlich Flügel, <Volk>. Ich habe gesehen, wie die schwarzen Töter und die Knochenpflücker sich am Kadaver so manch eines gefallenen Forschers gütlich taten - und manchmal fraßen sie sogar die übelsten, von Seuchen zerfressenen Leichen auf. Da ist es schon ein Wunder, wie ihre inneren Organe die Pestilenz überwinden, die in diesen Landen wütet.\n\nHelft mir bei meinen Studien, <Name>! Ich brauche Muskelmägen! Aber ich benötige auch zwei Kicherfangunterkiefer. Diese stellen die Grundlage für das Gebräu dar.\n\nFür Eure Anstrengungen erhaltet Ihr eine doppelte Belohnung.", progress = "Vergeudet meine Zeit nicht, <Name>. Es gibt nichts zu besprechen, es sei denn, Ihr hättet mir die Dinge gebracht, um die ich Euch gebeten habe.", completion = "Ganz ausgezeichnet! Ich werde mich sofort an die Arbeit machen. Vielleicht lässt sich damit ein Heilmittel für viele Gebrechen auf der Welt finden!\n\nAh, ja, Eure Belohnung... solltet Ihr mehr von der Kaumasse benötigen, dann kommt wieder zu mir, und Ihr erhaltet eine weitere Aufgabe.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHerrschaft des Willens\n\nIhr bekommt:\n\nMuskelmagen-Kaugummi"},
[2604] = {title = "Geistige Beherrschung", objective = "Bringt Blutmagierin Lynnore 10 Geiermuskelmägen und 2 Kicherfangunterkiefer.", description = "Wie ich sehe, ist Euer inneres Feuer erloschen. Was meint Ihr, hat das geistige Hochgefühl etwa eine Stunde angedauert?\n\nFalls Ihr mehr von der Muskelmagen-Kaumasse benötigt, dann benötige ich mehr Muskelmägen. Zurück in die Einöde mit Euch, <Name>. Kommt erst wieder, wenn Ihr zehn Muskelmägen und zwei Unterkiefer beschafft habt.", progress = "Vergeudet meine Zeit nicht, <Name>. Es gibt nichts zu besprechen, es sei denn, Ihr hättet mir die Dinge gebracht, um die ich Euch gebeten habe.", completion = "Vielleicht werde ich eines Tages in der Lage sein, die Enzyme zu isolieren, die den Hauptwirkstoff dieser Inhaltsstoffprobe ausmachen, und somit ein wesentlich potenteres Mittel herzustellen. Doch zunächst müsst Ihr Euch leider mit dem begnügen, was ich zurzeit zubereiten kann. Kommt wieder, falls Ihr mehr von der Muskelmagen-Kaumasse brauchen solltet.", rewards = "Ihr bekommt:\n\nMuskelmagen-Kaugummi"},
[2605] = {title = "Der durstige Goblin", objective = "Beschafft Euch eine volle Taudrüse und bringt sie nach Gadgetzan zu Marin Noggenfogger.", description = "Ich hab da so eine Idee. Ich habe von einigen seltsamen Kreaturen namens 'Tausammler' gehört, die im Südwesten leben. Angeblich können sie in speziellen Drüsen Wasser speichern.\n\nIch glaube, wenn ich eine von diesen Drüsen bekäme, dann könnte ich ein Getränk kreieren, das meinen schrecklichen Durst löschen würde. Könntet Ihr mir vielleicht helfen, <Name>?\n\nSucht bei den Kakteen, <Name>: Dort findet Ihr die Tausammler.", progress = "Bitte sagt mir: Habt Ihr die Tausammler gefunden?", completion = "Wie wundervoll! Gebt schon her - ich hab Durst!", rewards = "Ihr bekommt:\n\n"},
[2606] = {title = "Dem guten Geschmacke", objective = "Marin Noggenfogger möchte, dass Ihr in Gadgetzan mit Sprinkle sprecht.", description = "Bäh! Igitt! Das Zeug schmeckt ja eklig! So viel dazu...\n\nBitte, was meint Ihr? Ja, ich weiß schon, Ihr findet, ich sollte nicht so schnell die Flinte ins Korn werfen. Na dann.\n\nÄhm, da fällt mir was ein! Das ist genial! Bringt diesen Tau meiner Freundin Sprinkle - sie ist eine tolle Küchenchefin. Sagt ihr, was wir vorhaben, und dass wir das Zeug etwas aufpeppen wollen.\n\nIch meine, wenn es schon so fies schmeckt, dann sollte es wenigstens einen kleinen... Kick haben. Und davon kann ich nichts bemerken...", progress = "Der alte Marin kann's nicht lassen, was? Woraus ist dieses Gebräu gemacht?", completion = "Marin ist ein netter Kerl, versteht mich nicht falsch, nur ein bisschen... exzentrisch, würde ich sagen.\n\nUnd natürlich braucht er meine Hilfe, wie so oft.", rewards = "Ihr bekommt:\n\n"},
[2607] = {title = "Die Berührung von Zanzil", objective = "Sprecht im Keller der Kaserne mit Doc Mixilpixil.", description = "Es scheint, als hättet Ihr mehr Informationen bekommen, als selbst ich erwartet hätte. Es ist schon seltsam, wie das Schicksal manchmal spielt, <Name>.\n\nEin Heilmittel? Hmm... Geht hinunter in den Keller und sprecht mit Doc Mixilpixil: Vielleicht kann er Euch helfen.", progress = nil, completion = "Wird auch langsam Zeit! Legt einfach den Käse auf den Tisch und verzieht Euch. Osborne wird Euch auf dem Weg nach draußen bezahlen.", rewards = nil},
[2608] = {title = "Die Berührung von Zanzil", objective = "Ihr solltet Euch /hinlegen, damit Doc Mixilpixil Euch untersuchen kann. Denn wie soll er ein Heilmittel finden, wenn er die Ursache nicht finden kann?", description = "Meine Güte, Ihr seht ja aus wie der Tod. Nein, falsch. Ich habe den Tod schon gesehen - Ihr seht schlimmer aus. Ihr seht aus wie das, was der Tod bei seiner letzten Vorsorgeuntersuchung ausgespuckt hat.\n\nHa! Habt Ihr das gehört, Noarm? Schreibt das auf!\n\n<hustet> Ähem, ja, damit ich Euch helfen kann, muss ich Euch Blut abnehmen. Und keine Sorge, es tut nur die ersten... fünfzig Male oder so weh... Wenn Ihr bereit für die Behandlung seid, <Name>, solltet Ihr Euch bitte /hinlegen.", progress = "Wenn Ihr bereit seid für die Untersuchung, bitte auf den Boden /hinlegen, dann fange ich mit der Phlebotomie an.", completion = "Gebt mir einen Moment Zeit, um mich mit meinen Kollegen zu beraten, &lt;Name&gt;. Dr. Montgomery, Herr Noarm, dann wollen wir uns mal besprechen!", rewards = "Ihr bekommt:\n\n"},
[2609] = {title = "Die Berührung von Zanzil", objective = "Bringt Doc Mixilpixil 1 Bündel einfache Wildblumen, 1 verbleite Phiole, 1 Bronzeröhre und 1 Rolle blassgelben Seidenfaden. So eine 'Itis' heilt sich nicht von selbst, <junger Herr/junge Dame>.", description = "Wir sind einstimmig zu folgendem Schluss gekommen, <Name>... Ihr habt eine 'Itis'.\n\nZum Glück kann ich die 'Itis' heilen.\n\nUnd das brauche ich dafür: ein Bündel einfache Wildblumen, eine verbleite Phiole, eine Bronzeröhre und schließlich und endlich noch eine Rolle blassgelben Seidenfaden. Die alte Emma hat in 'Das feinste Band' eine Rolle davon für mich hinterlassen. Ihr findet den Laden an einem der Kanäle.\n\nBeeilt Euch jetzt, <Name>, und vermeidet es möglichst, jemanden anzufassen, bis Ihr geheilt seid. Dr. Montgomery meint übrigens, Ihr könntet eine Dusche vertragen - das hat er gesagt, nicht ich.", progress = "Wenn Ihr wollt, dass Eure 'Itis' geheilt wird, dann müsst Ihr Euch schon ein bisschen mehr anstrengen, <Name>. Wo sind die Reagenzien für das Heilmittel?", completion = "Was ich mache? Nach was sieht es denn aus? Ich arbeite an einem Heilmittel für Eure 'Itis'! Jetzt werdet mir nur nicht unverschämt, &lt;Name&gt;!\n\nEin paar Sekunden noch. Hier! Sprüht Euch einfach mit dieser, ähm, wunderbar riechenden Arznei ein, und schon seid Ihr so gut wie neu.", rewards = "Ihr bekommt:\n\nEau de Mixilpixil"},
[2621] = {title = "Der Entehrte", objective = "Sprecht in Stonard mit Zentralen-Kommandant Ruag.", description = "Bedauern. Das ist alles, was mir noch geblieben ist. Eine einzige Fehlentscheidung hatte gleich mehrere schreckliche Konsequenzen. Hätte ich doch nur auf meine Befehle gewartet. Vielleicht hätte darin etwas über die Schrecken gestanden, die uns in jenem verfluchten Land erwarteten! Vielleicht hätten sie uns zu einer anderen Abteilung beordert... Letztendlich war es meine Schuld. Es war alles meine Schuld.\n\nUnd so stehe ich hier und warte auf meine Befehle. Ich muss es wissen. Ich muss diese Befehle haben.\n\nZentralenkommandant Ruag lebt in Stonard. Findet ihn und bringt in Erfahrung, was aus den Befehlen geworden ist.", progress = nil, completion = "Thralls Zugriff... Ich erinnere mich noch ganz genau daran.\n\n&lt;Kommandant Ruag schüttelt den Kopf.&gt;\n\nSchreckliche Sache, was da mit diesem Regiment damals passiert ist. Die Horde verlor einige ihrer besten Soldaten, als das Bataillon vernichted wurde.", rewards = "Ihr bekommt:\n\n"},
[2622] = {title = "Die fehlenden Befehle", objective = "Sprecht mit Bengor.", description = "Die Befehle? Jetzt sagt mir doch mal, was Ihr mit diesen Befehlen wollt!\n\nWas wollt Ihr damit andeuten, <Name>? Natürlich habe ich die Befehle weitergegeben! Die Soldaten, denen ich die Befehle mitgab, wurden von Murlocs überfallen und auf brutalste Weise misshandelt. Nur ein Einziger von ihnen hat überlebt... wenn man das überleben nennen kann. Er kann kaum sprechen, kann nicht mehr laufen und muss durch einen Schlauch ernährt werden. Wenn Ihr wissen wollt, was mit diesen Befehlen passiert ist, dann sprecht mit Bengor. Er treibt sich hier mit Sicherheit irgendwo herum... und, <Name>, seid vorsichtig, in was Ihr Eure Nase steckt. Nicht, dass sie Euch abgebissen wird!", progress = nil, completion = "Sumpfre... red... redner...", rewards = "Ihr bekommt:\n\n"},
[2623] = {title = "Der Sumpfredner", objective = "Beschafft die Befehle des Kriegshäuptlings wieder und gebt sie dem gefallenen Helden der Horde zurück.", description = "Befehle... vom Zentral-Kommandanten ausgegeben. Haben Befehle... genommen. Auf dem Weg in die verwüsteten Lande... überfallen...\n\nMurlocs... Viele Murlocs... Einer... hieß Sumpfredner. Nahm mir Befehle ab, als Speer in meinen Schädel fuhr. Osten... Höhle...\n\n<Bengor verliert das Bewusstsein.>", progress = "Warten auf Befehle", completion = "Es ist schlimmer als ich dachte. Neunzehn meiner Männer hätte das entsetzliche Schicksal erspart bleiben können, das ihnen widerfahren ist. Wenn ich nur nicht so unvernünftig gehandelt hätte...\n\nIhr müsst ihnen helfen, &lt;Name&gt;! Ich selbst kann nichts tun.", rewards = "Ihr bekommt:\n\n"},
[2641] = {title = "Sprinkles Geheimzutat", objective = "Sprinkle in Gadgetzan möchte, dass Ihr einen violetten Tragan sucht und ihr bringt.", description = "Als ich noch ein kleines Mädchen war, hat meine Schwester immer gekocht. Es war grauenhaft! Manche ihrer 'Gerichte' konnte ich kaum runterwürgen - bis ich irgendwann meine 'Geheimzutat' entdeckt habe! Egal, zu was man sie hinzufügt... im Nu schmeckt alles toll!\n\nUm was es sich dabei handelt, wollt Ihr wissen? Es ist ein Pilz namens violetter Tragan. Wenn Ihr wollt, dass ich dieses fürchterlich schmeckende Gebräu in etwas Genießbares verwandle, dann begebt Euch ins Hinterland und sucht dort nach einem kleinen See.\n\nUnd vergesst nicht: Violette Tragane findet man nur unter Wasser.", progress = "Sucht unter der Oberfläche jenes Sees; das ist der einzige Ort, wo die violetten Tragane wachsen. Ich hoffe, Ihr könnt Euren Atem lang genug anhalten!", completion = "Genau das wollte ich, &lt;Name&gt;!\n\nDas Zeug sieht so lecker aus, dass ich am liebsten... Ha-ha, reingelegt!", rewards = "Ihr bekommt:\n\n"},
[2661] = {title = "Lieferung für Marin", objective = "Sprinkle möchte, dass Ihr das violette Pulver nach Gadgetzan zu Marin Noggenfogger bringt.", description = "Hier habt Ihr das violette Pulver, <Name>. Bringt es zu Marin und sagt ihm, er schuldet mir was!", progress = "Oh, <Name>, Ihr seid endlich zurück. Was bringt Ihr mit?", completion = "Violettes Pulver, hm? Na, versuchen wir's mal - schlimmer kann es nicht mehr werden, das steht fest!", rewards = "Ihr bekommt:\n\n"},
[2662] = {title = "Noggenfogger-Elixier", objective = "Marin Noggenfogger möchte, dass Ihr ihn nochmals ansprecht, wenn er sein Elixier fertig gestellt hat.", description = "So, jetzt mische ich das Pulver unter den Tau.\n\nSprecht mich in einer Minute noch mal an... wenn ich das fabelhafte Noggenfogger-Elixier perfektioniert habe!", progress = nil, completion = "Trinkt das! Es ist einfach toll!!!\n\nIch wusste, ich würde es schaffen... Ach, nochmals danke für Eure Hilfe, &lt;Name&gt;, aber bitte, tretet doch etwas zur Seite, ja? Ihr behindert meine Geschäfte! Ich werde Millionen an dem fabelhaften Noggenfogger-Elixier verdienen, Millionen!\n\nWie war das? Sprinkle sagt, ich schulde ihr was? Diese Sprinkle, immer einen Scherz auf den Lippen!", rewards = "Ihr bekommt:\n\nNoggenfogger-Elixier"},
[2681] = {title = "Die Steine, die uns binden", objective = "Befreit 9 Diener von Razelikh, 3 Diener von Sevine, 3 Diener von Allistarj und 3 Diener von Grol. Kehrt zum gefallenen Helden zurück, sobald Ihr die Aufgabe erfüllt habt. Ihr müsst nahe bei den Steinen bleiben, sonst habt Ihr keinen Erfolg.", description = "Allein wird es Euch nicht gelingen, die Streitmacht von Razelikh und seinen Untergebenen zu überwinden.\n\nSammelt eine Gruppe von geeigneten Abenteurern um Euch und befreit meine Männer aus der ewigen Qual! Achtzehn Steine müsst Ihr zerschmettern.\n\nKämpft hart und sterbt ehrenvoll, <Name>.", progress = "Die Aufgabe ist nicht leicht, <Name>. Gebt nicht auf!", completion = "Ihr habt es geschafft, &lt;Name&gt;! Die armen gequälten Seelen können endlich ruhen.\n\nDoch unsere Aufgabe ist noch nicht erfüllt, &lt;Name&gt;. Wir haben viel zu besprechen und noch viel mehr zu erledigen.", rewards = "Ihr bekommt:\n\n"},
[2701] = {title = "Helden der Vergangenheit", objective = "Öffnet die Truhe und nehmt Euch Eure Belohnung.", description = "Bitte, nehmt Euch ein Relikt der Vergangenheit. Wir haben für den Gegenstand keine Verwendung mehr.\n\nMöge es Euch in Eurem Kampf gegen die Legion gute Dienste leisten.", progress = nil, completion = "Ihr werdet von dem Glitzern und dem Strahlen darin kurzzeitig geblendet.", rewards = "Ihr bekommt:\n\nSplitter der Spalthufe"},
[2702] = {title = "Helden der Vergangenheit", objective = "Sprecht mit Corporal Thund Splithoof.", description = "Mit Eurem Edelmut und Eurer Heldenhaftigkeit erweist Ihr mir Ehre, <Name>.\n\nUnd auch ihnen habt Ihr Ehre erwiesen...", progress = nil, completion = "Ja, wirklich, Ihr habt uns allen Ehre erwiesen. Worte des Dankes allein reichen nicht aus.", rewards = "Ihr bekommt:\n\n"},
[2721] = {title = "Kirith", objective = "Findet heraus, was aus Lieutenant Kirith geworden ist.", description = "Ein Kapitel Eurer Abenteuer mag jetzt beendet sein, doch ein weiteres Kapitel beginnt gerade, <Name>.\n\nEiner meiner Männer ist noch immer verschollen, irgendwo in den verwüsteten Landen verschwunden. Ich spreche natürlich von Lieutenant Kirith.\n\nWie ich vorhin schon sagte, wurden wir beide von Allistarj gefangen genommen und gefoltert, aber ich fürchte, dass der arme Kirith nicht durchhielt und schwach wurde. Aus meinem Käfig heraus konnte ich die Experimente hören: Die gequälten Schreie hallten in der ganzen Höhle wider. Das war das Letzte, was ich von Kirith gesehen oder gehört habe.", progress = nil, completion = "Trebor? Trebor hat Euch geschickt?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2741] = {title = "Der Super-Ei-O-Mat", objective = "Der Super-Ei-O-Mat ist die neueste Erfindung von Curgle Cranklehop. Es ist eine ziemlich beeindruckende Maschine.\n\nDer Super-Ei-O-Mat fängt wild an zu spucken und zu zischen, als Ihr Euch der Steuerkonsole nähert.", description = nil, progress = "Der Super-Ei-O-Mat ist die neueste Erfindung von Curgle Cranklehop. Es ist eine ziemlich beeindruckende Maschine.\n\nDer Super-Ei-O-Mat fängt wild an zu spucken und zu zischen, als Ihr Euch der Steuerkonsole nähert.", completion = "Ihr legt das Hippogryphen-Ei in die Maschine. Es folgen eine Reihe von Pieptönen sowie ein seltsames Rasseln, Rattern und Klicken.\n\nEs scheint, als hätte das Ei-O-Meter Euer Ei gewogen, vermessen und verpackt. Das ist echt ein zügiger Service!", rewards = "Ihr bekommt:\n\nEierkiste"},
[2742] = {title = "Rin'ji steckt in der Falle!", objective = "Eskortiert Rin'ji aus der Quel'Danil-Hütte heraus und findet dann das, was er bei den Aussichtsklippen im Osten versteckt hat.", description = "He, <Volk>!\n\nBitte, helft Rin'ji flüchten. Ich weiß, Ihr seid <Volk>, mögt Rin'jis Volk nicht, aber Rin'ji bittet und bettelt! Muss hier raus!\n\nHab auch was Schönes für <Volk>, wenn <Volk> nett ist und Rin'ji hier raushilft...\n\nRin'ji hat was Geheimes bei den Aussichtsklippen versteckt.", progress = nil, completion = "Diese Troll-Schrifttafel muss das \"Geheimnis\" sein, von dem Rin'ji gesprochen hat.\n\nDie Schrifttafel ist mit seltsamen Zeichen bedeckt, aber Ihr könnt nicht lesen, was darauf geschrieben steht.", rewards = "Ihr bekommt:\n\n"},
[2743] = {title = "Der Mantel der Dunkelheit", objective = "Kehrt mit Euren neuen Erkenntnissen zum gefallenen Helden der Horde zurück.", description = "Lasst uns nicht um den heißen Brei herumreden, <Volk>; ich habe nicht unbegrenzt Zeit.\n\nIhr müsst das Dreigestirn der Macht vernichten, das den Dämonenlord Razelikh beschützt. Doch das wird nicht ganz so einfach werden wie das Befreien einer verdammten Seele.\n\n<Kirith grinst.>\n\nIhr müsst wissen, dass jeder von Razelikhs Untergebenen ein Drittel eines von Razelikh geschaffenen Amuletts um den Hals trägt. Und genau dieses Amulett braucht Ihr, um den Erzdämon zu beschwören.\n\nGeht zu Trebor und sagt ihm, was benötigt wird, um Razelikh zu beschwören. Er kann Euch weitere Anweisungen geben.", progress = nil, completion = "Der Dämonenlord legt eine Schläue an den Tag, die fast genauso berechnend ist wie seine Grausamkeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[2744] = {title = "Der Dämonenjäger", objective = "Sprecht mit Loramus Thalipedes in Azshara.", description = "Das Dreigestirn wird von Razelikh beschützt.\n\nAls Lohn für ihre Dienste hat Razelikh jeden von ihnen mit schier unbegrenzter Macht in den verwüsteten Landen ausgestattet. Die Teile des Amuletts sind auf die Lebenskraft ihrer jeweiligen Besitzer eingestellt und verleihen diesen Unsterblichkeit. Solange die sich in den verwüsteten Landen aufhalten, können sie nicht getötet werden, und auch ihre Lebensspanne ist bis zum Ende aller Tage ausgedehnt.\n\nDoch einen gibt es, der Euch vielleicht weiterhelfen kann, <Name>. Reist nach Azshara und sucht dort nach dem Dämonenjäger Loramus Thalipedes. Ihr findet ihn vermutlich auf den Inseln.", progress = "Was tut Ihr hier?", completion = "Ich werde Euch helfen, obwohl ich nicht glaube, dass Euch bewusst ist, auf was Ihr Euch da eingelassen habt.", rewards = "Ihr bekommt:\n\n"},
[2745] = {title = "Eindringen ins Schloss", objective = "Sprecht in Schloss Stormwind mit Tyrion.", description = "Hmm, eine interessante Geschichte und eine, die man nicht auf die leichte Schulter nehmen sollte. Ja, ich kann Euch helfen, aber wenn Ihr das wirklich bis zum Ende durchziehen wollt, dann müsst Ihr andere Saiten aufziehen, die... nicht ganz legal sind.\n\nLescovar und Marzon müssen erledigt werden, und zwar schnell. Glaubt Ihr, Ihr seid zu so was fähig?\n\nDie Entscheidung liegt bei Euch. Falls ja, dann geht so schnell wie möglich ins Schloss und redet dort mit einem Freund von mir, einem Gnom namens Tyrion. Er beobachtet Lescovar jetzt schon seit ein paar Wochen. Er sollte Euch dabei helfen können, die Sache zu Ende zu bringen.", progress = nil, completion = "Was zum...?! Schleicht Euch nicht so an mich ran! Und redet leise! Was zum Schatten, schleicht Ihr Euch so an mich ran? Seht Ihr nicht, dass ich beschäftigt bin, blöder Kerl?\n\nDämliche Frage... was werde ich hier schon tun? Ich warte darauf, dass sich das nächste Dunkle Portal öffnet, was glaubt Ihr denn, was ich mache? Also sagt, was Ihr zu sagen habt, und dann haut ab... bevor die Wachen merken, dass wir uns hier in den Büschen rumdrücken. Ich muss schließlich meinen Ruf wahren.", rewards = "Ihr bekommt:\n\n"},
[2746] = {title = "Nicht unwichtige Gegenstände", objective = "Bringt 3 Stück Seidenstoff und 2 frische Äpfel von Clara nach Stormwind zu Tyrion.", description = "Trias will also alles ein bisschen beschleunigen, wie? Na gut, können wir zwar machen, aber ich bin noch nicht bereit. Und damit eines mal klar ist: Ich hab den anstrengenderen Job, aber Ihr seid <derjenige, der/diejenige> die; sich die Hände schmutzig macht, verstanden? Gut.\n\nAlso, Ihr müsst mir ein paar Sachen besorgen, bevor ich meinen Plan in die Tat umsetzen kann. Ich hab schon die perfekte Verkleidung, um den Spionagebot an den Wachen vorbeizubekommen.\n\nBringt mir etwas Seide und ein paar Äpfel. Wo Ihr die Seide herkriegt, ist Eure Sache, aber auf Claras kleinem Hof draußen vor der Stadt gibt es Äpfel in genau der richtigen Größe.", progress = "Ich beobachte Lescovar jetzt schon seit ein paar Wochen. Trias hat ihm zwar noch nie getraut, aber wir hegten nie den Verdacht, dass er mit der Bruderschaft der Defias unter einer Decke stecken könnte. Wir sind nur einigen Spuren gefolgt, die ihn mit dem Twilight-Hammer in Verbindung bringen. Wie dem auch sei, er ist gefährlicher geworden, als diese Stadt das verkraften kann - und da kommen wir ins Spiel.\n\nBeschafft mir diese Gegenstände, dann können wir meinen Plan in die Tat umsetzen.", completion = "Die sind prima, &lt;Name&gt;. Gute Arbeit.\n\nAlles, was ich sonst noch brauche, habe ich im Rucksack... Dem Licht sei's getrommelt und gepfiffen, dass mir ein Freund, ein Schneider, gerade eine Seidentasche gemacht hat. Ich hatte schon gar keinen Platz mehr für all das Zeug, das ich mit mir so rumschleppe.\n\nBevor der Spionagebot sich auf den Weg macht, sollten wir die Details noch mal durchgehen, damit Ihr wisst, was Ihr zu tun habt.", rewards = "Ihr bekommt:\n\n"},
[2747] = {title = "Ein außergewöhnliches Ei", objective = "Ich habe bisher nur sehr wenige Eier gesehen, die in außergewöhnlich gutem Zustand aus Feralas geholt wurden. Diese Eier sind extrem selten...", description = nil, progress = "Ich habe bisher nur sehr wenige Eier gesehen, die in außergewöhnlich gutem Zustand aus Feralas geholt wurden. Diese Eier sind extrem selten...", completion = "Und Ihr habt eins - erstaunlich!\n\nIch hoffe, Ihr vergesst nie, welch gute Tat Ihr heute vollbracht habt.", rewards = "Ihr bekommt:\n\nKasten mit Kram"},
[2748] = {title = "Ein gutes Ei", objective = "Ein gutes Ei ist ein Ei, aus dem idealerweise ein Jungtier schlüpft, das frei von den bösen Auswirkungen der Beschwörungen der Oger der Gordunni ist.", description = nil, progress = "Ein gutes Ei ist ein Ei, aus dem idealerweise ein Jungtier schlüpft, das frei von den bösen Auswirkungen der Beschwörungen der Oger der Gordunni ist.", completion = "Sehr gut, &lt;Name&gt;. Ich werde dieses Ei nach Darnassus schicken, wo dann hoffentlich bald ein Küken schlüpfen wird!\n\nBitte nehmt dies zum Zeichen meiner Dankbarkeit.", rewards = "Ihr bekommt:\n\nKasten mit Zaubern"},
[2749] = {title = "Ein gewöhnliches Ei", objective = "Normalerweise schlüpft etwa aus jedem zweiten Hippogryphen-Ei auch ein Jungtier. Wir hegen und pflegen die Eier nach besten Kräften, und wenn wir Glück haben, dann schlüpft am Ende etwas da raus.", description = nil, progress = "Normalerweise schlüpft etwa aus jedem zweiten Hippogryphen-Ei auch ein Jungtier. Wir hegen und pflegen die Eier nach besten Kräften, und wenn wir Glück haben, dann schlüpft am Ende etwas da raus.", completion = "Ihr habt also ein gewöhnliches Ei gefunden, &lt;Name&gt;, hm? Bitte gebt es mir... Jetzt können wir nur das Beste hoffen.\n\nIch habe nicht viel, aber bitte nehmt diese Belohnung an. Falls Ihr je wieder nach Feralas kommen solltet, dann denkt daran, dass ich immer gern bereit bin, Euch die Eier abzunehmen, die Ihr dort findet.", rewards = "Ihr bekommt:\n\nKasten mit Rationen"},
[2750] = {title = "Ein schlechtes Ei", objective = "Diese Eier können nicht gerettet werden - aus ihnen wird niemals etwas schlüpfen.", description = nil, progress = "Diese Eier können nicht gerettet werden - aus ihnen wird niemals etwas schlüpfen.", completion = "Leider habe ich schlechte Neuigkeiten für Euch, &lt;Name&gt;. Für dieses Ei ist es schon zu spät. Ich kann es Euch abnehmen, damit es richtig entsorgt wird.\n\nLasst Euch bitte nicht entmutigen, wir können eben nicht alle retten. Falls Ihr je nochmals nach Feralas kommen solltet, dann versucht es bitte wieder. Bringt uns ein weiteres Ei für den Super-Ei-O-Mat!", rewards = "Ihr bekommt:\n\n"},
[2751] = {title = "Barbarische Waffenschmiedekunst", objective = "Bringt 2 gemusterte bronzene Armschienen, 2 bronzene Großschwerter und 2 scharfe Klauen zu Orokk Omosh in Orgrimmar.", description = "Zwanzig Generationen von Omoshs haben diesen Hammer bereits in Händen gehalten, <Name>. Hunderttausend Tonnen Metall haben wir geformt. Doch leider, leider endet alles mit Orokk, dem Fehlschlag der Omosh: ohne Verwandte und nicht in der Lage, sich fortzupflanzen.\n\nIch kann nicht zulassen, dass die geheimen Rezepturen der Omosh mit mir sterben! Jemand muss das Werk fortführen, ganz gleich, ob derjenige ein Omosh ist oder nicht!\n\nBeweist Orokk, dass Ihr fähig seid, <Name>. Bringt Orokk die folgenden Dinge: zwei gemusterte bronzene Armschienen, zwei bronzene Großschwerter und zwei scharfe Klauen. Bringt sie Orokk, dann machen wir weiter.", progress = "Bronze, <Name>! Bringt mehr Bronze!", completion = "Die Blutlinie mag vielleicht vergehen, doch die Legende der Omoshs wird weiterleben!\n\nIhr habt bewiesen, dass Ihr ein wahrer Schmied seid, &lt;Name&gt;. Für einen Schmied ist es Belohnung genug, wenn er seine Waffen und seine Rüstungen mit dem Blut der Feinde bedeckt sieht.\n\nMögen die Brustplatten, die Ihr für zukünftige Generationen anfertigt, im Blut Eurer Feinde gebadet werden!", rewards = "Ihr bekommt:\n\nPläne: Barbarische Eisenbrustplatte"},
[2752] = {title = "Über Eisenschulterstücke", objective = "Bringt 4 bronzene Streitäxte und 4 bronzene Kriegshämmer zu Orokk Omosh in Orgrimmar.", description = "Orokk sieht den Eifer in Euren Augen, <Name>. Wie ein Schwamm saugt Ihr das Wissen der Omoshs auf.\n\nDrei Lektionen werde ich Euch lehren.\n\nKehrt zum Amboss zurück, schwitzt in der Hitze der Schmiede und stellt für Orokk vier bronzene Streitäxte und vier bronzene Kriegshämmer her. Erst dann könnt Ihr etwas über Eisenschulterstücke lernen.", progress = "Zeigt mir, dass Ihr es ernst meint, <Volk>.", completion = "Ihr macht Orokk alle Ehre, &lt;Name&gt;. Lest und lernt etwas über Eisenschultern!", rewards = "Ihr bekommt:\n\nPläne: Barbarische Eisenschultern"},
[2753] = {title = "In den Boden getrampelt", objective = "Bringt 4 grüne Eisenhelme, 4 grüne Eisenarmschienen und 2 grüne Eisengamaschen zu Orokk Omosh in Orgrimmar.", description = "Nur zwei Lektionen noch hat Orokk für Euch, <Name>. Eure Muskeln schmerzen, ich weiß, doch macht weiter - für die Omoshs!\n\nBringt Orokk vier grüne Eisenhelme, vier grüne Eisenarmschienen und zwei grüne Eisengamaschen - zur Belohnung werdet Ihr lernen und Eure Feinde werden leiden!", progress = "Ihre Schädel werden unter dem Druck Eurer Stiefel platzen!", completion = "Ihr erinnert Orokk an seinen Großvater, Häuptling Gorokk von Omosh! Lest und lernt etwas über Eisenstiefel!", rewards = "Ihr bekommt:\n\nPläne: Barbarische Eisenstiefel"},
[2754] = {title = "Hörner der Raserei", objective = "Bringt 2 robuste Eisenschlägel, 2 bronzene Stiefel mit Versilberung und 2 bronzene Stulpen mit Versilberung zu Orokk Omosh in Orgrimmar.", description = "Jetzt lehrt Orokk Euch die letzte Lektion, <Name>. Zurück zum heiligen Amboss und der heiligen Schmiede mit Euch! Bringt Orokk zwei robuste Eisenschlägel, zwei bronzene Stiefel mit Versilberung und zwei bronzene Stulpen mit Versilberung.\n\nSeht die Furcht in den Augen der Feinde, wenn Ihr Euch nähert!", progress = "Zeigt dem Eisen, wer der Herr im Hause ist, <Name>!", completion = "Erstaunlich! Ihr habt die Geheimnisse der Omoshs erlernt, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nPläne: Barbarischer Eisenhelm"},
[2755] = {title = "Freude der Omoshs", objective = "Seht zu und lernt den Freudentanz der Omoshs.", description = "Orokk weint nicht, <Name>. Orokk hat Ruß ins Auge bekommen.\n\n<Orokk wischt eine Träne weg.>\n\nNoch ein letztes Familiengeheimnis der Omosh wird Orokk Euch beibringen. Dank <Name> wird Orokk glücklich sterben.\n\nLernt den Freudentanz der Omoshs... und dann lernt Ihr Eisenfaust!", progress = nil, completion = "&lt;Orokk japst.&gt;\n\nLange her, dass Orokk den Freudentanz der Omoshs getanzt hat. Lernt jetzt, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nPläne: Barbarische Eisenhandschuhe"},
[2756] = {title = "Die alten Traditionen", objective = "Bringt 4 Stahlbrustplatten und 4 Stahlplattenhelme zu Aturk dem Amboss in Orgrimmar.", description = "Früher, zur Zeit der Legenden, zerquetschte Aturk die Schädel seiner Feinde und zermahlte die Knochen zu einem feinen Pulver, das er zu Fasern verarbeitete. Diese Tage sind lange vergangen, <Volk>. Der Kriegshäuptling verlangt Frieden unter den Klans. Alte Feinde werden nur noch misstrauisch beäugt!\n\nEs ist unglaublich, ich weiß, doch es ist nun einmal Thralls Wille.\n\nAber genug gejammert! Ihr seid zum Lernen hier, und Ihr werdet etwas lernen! Bringt mir vier Stahlbrustplatten und vier Stahlhelme, dann bekommt Ihr den Geschmack des Krieges zu kosten!", progress = "Wie die Zeit selbst, wartet auch Aturk auf niemanden! Beeilt Euch, Nichtsnutz!", completion = "Wie mir scheint, seid auch Ihr nichts weiter als eine selbstzufriedene Marionette des Kriegshäuptlings, &lt;Name&gt;. Wie enttäuschend.\n\nIch sehne mich so sehr nach einem glorreichen Tod auf dem Schlachtfeld. Aber stattdessen hänge ich auf Befehl von Thrall hier fest und muss Kleinkindern beibringen, wie man Dinge herstellt! Seht zu und lernt, Kind!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nOrc-Kriegsgamaschen lehren\n\nIhr bekommt:\n\n"},
[2757] = {title = "Auf nach Booty Bay!", objective = "Sprecht mit McGavan in Booty Bay.", description = "Hört mal, wenn Ihr hier herumhängt, lernt Ihr nix.\n\nIch kenn da so 'n Typen, der 'n Typen kennt. Der treibt sich bei der Schmiede in Booty Bay rum. Wenn Ihr ihm die Insignie hier zeigt, dann erzählt er Euch alles über Mithril.\n\nAlso, was sagt Ihr? Überlasst diesen Babykram den Kleinkindern, <Name> - für Euch ist es Zeit weiterzuziehen.\n\nFalls Ihr Interesse haben solltet, der Typ heißt McGavan. Zeigt ihm das hier, dann wird er sehen, dass es Euch ernst ist.", progress = "Eure Art is' selten, Kamerad. Zeigt mir ma' die Insignie da.", completion = "Beim Rückenhaar von Blackhoof - endlich jemand, der des Mithrilordens würdig ist!", rewards = "Ihr bekommt:\n\n"},
[2758] = {title = "Die Herkunft der Schmiedekunst", objective = "Bringt 6 goldene Schuppenarmschienen zu Hank dem Hammer in Stormwind.", description = "Als ich etwa so alt war wie Ihr, nahm mich ein Zwerg namens Galvan unter seine Fittiche und bildete mich in der Kunst des Rüstungsschmiedens aus. Bevor er sich nach Booty Bay aufmachte, nahm er mir das Versprechen ab, dass ich all denjenigen ein Lehrer sein würde, die den Wunsch hätten und entschlossen genug wären, selbst eine Schmiedelaufbahn einschlagen zu wollen. Und hier bin ich nun - all die Jahre später.\n\nAlso, es ist jetzt Zeit für Euch, ein bisschen was zu lernen. Stellt mir sechs goldene Schuppenarmschienen her, dann zeige ich Euch, was echte Schmiedekunst ist, <Name>.", progress = "Sollet Ihr vielleicht der nächste Zögling von Galvan sein?", completion = "Sehr gut, &lt;Name&gt;! Hört zu und lernt.\n\nDie wahre Schmiedekunst entsteht niemals hier! \n\nDie wahre Schmiedekunst entsteht niemals hier! \n\nDie wahre Schmiedekunst entsteht nur hier und nirgends sonst! &lt;Hank deutet auf sein Herz.&gt;\n\nJetzt wisst Ihr, wo die wahre Schmiedekunst herkommt.", rewards = "Ihr bekommt:\n\nPläne: Goldene Schuppenstulpen"},
[2759] = {title = "Auf der Suche nach Galvan", objective = "Sprecht in Booty Bay mit McGavan.", description = "Obwohl Galvan Booty Bay schon vor vielen Jahren verlassen hat, leben noch immer Mitglieder des Ordens in der Stadt und hoffen, dass sie eines Tages jemanden finden werden, der der Lehre von Galvan würdig ist.\n\nNehmt diese Insignie und zeigt sie McGavan in Booty Bay.\n\nSolltet Ihr es tatsächlich bis dorthin schaffen, dann weiß er, dass Ihr würdig seid. Ich glaube an Euch, <Name>!", progress = "Eure Art is' selten, Kamerad. Zeigt mir ma' die Insignie da.", completion = "Beim Rückenhaar von Blackhoof - endlich jemand, der des Mithrilordens würdig ist!", rewards = "Ihr bekommt:\n\n"},
[2760] = {title = "Der Mithrilorden", objective = "Sprecht mit Galvan dem Alten im Schlingendorntal.", description = "Die meisten unserer Rekruten schaffen es nicht bis Booty Bay, <Name>. Der Glanz der Insignie reicht normalerweise aus, um selbst im zuverlässigsten Schmied die Beutegier ausbrechen zu lassen. Narren, alle zusammen, denn die Insignie ist nichts als Talmi im Vergleich zum Wert der Gegenstände, die Ihr zu sehen bekommen werdet!\n\nFindet Galvan den Alten und zeigt ihm diese Anstecknadel. Er lebt weit im Norden, zwischen Zul'Gurub und dem Ogerhügel der Mosh'Ogg.", progress = "Seid gegrüßt! Kommt näher und zeigt Galvan, was Ihr da habt.", completion = "Ah, es ist schon viele Jahre her, dass jemand würdig war, in den Mithrilorden aufgenommen zu werden. Wir fangen sofort an!", rewards = "Ihr bekommt:\n\n"},
[2761] = {title = "Hier verhütten, da verhütten", objective = "Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 40 Eisenbarren.", description = "Viele Schmiede glauben, der Bergbau und die Schmiedekunst seien zwei völlig getrennte, voneinander unabhängige Dinge, aber wie kann es Schmiedekunst geben ohne Bergbau? Genau, das ist völlig unmöglich! Und daher muss der vollendete Schmied auch ein tüchtiger Minenarbeiter sein.\n\nZeigt Galvan, dass Ihr fähig seid, <Name>. Bringt mir vierzig Barren Eisen und vierzig Barren Mithril. Dafür sagt Galvan Euch dann alles über verschnörkelte Mithrilhosen!", progress = "Nach so viel Bergbau schwellen die Muskeln an und der ganze Körper tut weh!", completion = "Ihr habt eine ausgezeichnete Arbeitsmoral, &lt;Name&gt;! Langsam beginnt Ihr, Galvans Mineralogielehre zu verstehen! Nehmt dies und lernt alles daraus, was Ihr nur könnt.", rewards = "Ihr bekommt:\n\nPläne: Verschnörkelte Mithrilhose"},
[2762] = {title = "Der große silberne Betrüger", objective = "Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 5 Echtsilberbarren.", description = "Es heißt, dass Echtsilber noch stärker und haltbarer sei als Mithril. Galvan widerspricht dieser Einschätzung der Mineralien zwar nicht, aber Echtsilber trägt seinen Namen zu Unrecht. Echtsilber ist nicht echt! Mithril ist ein wesentlich edleres Mineral! HA! Aber wie dem auch sei ... für diese Lektion müsst Ihr den silbernen Betrüger finden, <Name>.\n\nBringt mir vierzig Barren Mithril und fünf Barren Echtsilber. Im Gegenzug werdet Ihr in das Geheimnis der verschnörkelten Mithrilhandschuhe eingeführt, und, was noch wichtiger ist, Ihr werdet lernen, dass Echtsilber lügt!", progress = "Nach so viel Bergbau schwellen die Muskeln an und der ganze Körper tut weh!", completion = "Es ist ein grausamer Gebieter, nicht wahr, &lt;Name&gt;? Ich rede natürlich von Echtsilber. Jawohl, Galvan hat mehr als zehn Jahre in den Bergen von Alterac verbracht und dort diese Lektion gelernt. Nehmt dies und lernt alles daraus, was Ihr nur könnt.", rewards = "Ihr bekommt:\n\nPläne: Verschnörkelte Mithrilhandschuhe"},
[2763] = {title = "Die Kunst der Magieerfüllung", objective = "Bringt Galvan dem Alten im Schlingendorntal 40 Mithrilbarren und 4 Citrine.", description = "Der Abbau von wertvollen Edelsteinen ist für unsere Zunft von äußerster Wichtigkeit, <Name>. Und nur wenige Edelsteine sind wertvoller als der Citrin. Die magischen Eigenschaften, mit denen wir unsere Waren ausstatten, werden deutlich verstärkt, wenn Citrine im Spiel sind.\n\nIn dieser Lektion verstärken wir vierzig Barren Mithril mit vier Citrinen. So bekommt Ihr ein besseres Verständnis für die magische Edelsteinkunde und lernt außerdem, wie man verschnörkelte Mithrilschultern herstellt.", progress = "Nach so viel Bergbau schwellen die Muskeln an und der ganze Körper tut weh!", completion = "Man kann die Augen kaum von seinem Glanz losreißen, &lt;Name&gt;. Oh ja, der Citrin ist ein herrlicher Edelstein.\n\nPasst gut auf und lernt, was eine solche Entdeckung uns alles beibringen kann!", rewards = "Ihr bekommt:\n\nPläne: Verschnörkelte Mithrilschulter"},
[2764] = {title = "Galvans bester Schüler", objective = "Sprecht in Gadgetzan mit Trenton Lighthammer.", description = "Wenn Ihr bereit seid, Eure Ausbildung bei Galvan abzuschließen, dann solltet Ihr nach Gadgetzan reisen.\n\nDort findet Ihr meinen besten Schüler, Trenton Lighthammer. Er kann Euch viel über verschnörkeltes Mithril beibringen. Ansonsten bleibt hier und lernt weiter!\n\nAch ja, Gadetzan liegt natürlich in Tanaris!", progress = nil, completion = "Galvan der Alte hat Euch geschickt?\n\n&lt;Trenton verneigt sich.&gt;\n\nEs ist eine große Ehre, einen der anderen Schüler des Meisters kennen zu lernen!", rewards = "Ihr bekommt:\n\n"},
[2765] = {title = "Schmiedkunstexperte!", objective = "Fordert Eure Belohnung von Galvan dem Alten ein!", description = "Schon als Ihr das erste Mal zu mir kamt, wusste ich, dass Ihr Euch als einer meiner besten Schüler herausstellen würdet! Ohne zu zögern trenntet Ihr Euch von einem nicht recht mächtigen Gegenstand und gabt ihn McGavan. Ihr tatet dies, nur damit Ihr mich treffen konntet. Solch blindes Vertrauen und Hingabe an unser Handwerk soll nicht unbelohnt bleiben.\n\nIhr seid zu einem wahren Experten der Schmiedekunst geworden, <Name>. Nun erntet den Lohn dafür!", progress = nil, completion = "Es ist nur recht und billig, dass Ihr jetzt einen wesentlich mächtigeren Gegenstand erhaltet als den, den Ihr aufgabt, um hierher zu kommen. Möget Ihr immer bei guter Gesundheit sein, wenn Ihr ihn verwendet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSignet der Expertise"},
[2766] = {title = "Findet OOX-22/FE!", objective = "Bringt das Notrufsignal zu Oglethorpes Leitroboter in einer Höhle in der Nähe des Wildschrammtals.", description = "Ihr habt ein merkwürdiges Gerät aus Metall entdeckt, das die Form eines Eis hat. Als Ihr einen der Knöpfe berührt, erwacht das Ei zu Leben und verwandelt sich in eine Art Gnom-Roboter-Apparat! Aus dem Inneren des Roboteis erklingt eine rasselnde Stimme.\n\n\"Mein Name ist Oglethorpe Obnoticus und mein Leitroboter ist abgestürzt! Ich werde Euch belohnen, wenn Ihr ihn aufspürt. Bringt dem Roboter bitte diesen Signalgeber!\"\n\n\"Ich habe jetzt die Koordinaten des Roboters für Euch berechnet. Er ist in der Nähe des Wildschrammtals abgestürzt!\"", progress = "Ihr habt anscheinend das Wrack eines... Robothuhns entdeckt... Aus dem Ei erklingt wieder die rasselnde Stimme:\n\n\"Ja, hervorragende Arbeit! Das ist tatsächlich mein Leitroboter, aber meine Sensoren zeigen an, dass er Starthilfe benötigt, bevor er zur Reparatur nach Booty Bay zurückfliegen kann. Bitte legt den Signalgeber in den Rover. Der Signalgeber wird den Rest übernehmen!\"", completion = "Ihr legt das Ei... das Notsignal... in das Huhn... den Leitroboter.\n\nAus dem Roboter ertönt ein Brummen und Surren, als er versucht aufzustehen. Nachdem der Roboter zum Leben erwacht ist, ertönt die Stimme von Oglethorpe ein weiteres Mal, diesmal aus dem Inneren des Roboters:\n\n\"OOX-22/FE funktioniert endlich, aber es sind umfangreiche Reparaturen erforderlich! Er ist zu schwer, als dass Ihr ihn tragen könntet... aber ich glaube, ich habe eine Idee. Könntet Ihr noch etwas auf ihn aufpassen?\"", rewards = "Ihr bekommt:\n\n"},
[2767] = {title = "Die Rettung von OOX-22/FE", objective = "Eskortiert OOX-22/FE zum Dock an der Vergessenen Küste und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay.", description = "Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms:\n\n\"Ich muss OOX-22/FE an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann. Er hat eine eingebaute Tarnvorrichtung, aber ich brauche etwas Zeit, um sie von hier aus wieder zum Funktionieren zu bringen. Eskortiert den Roboter von seinem momentanen Standort zu, ach, sagen wir mal, dem Dock an der Vergessenen Küste. Das sollte der perfekte Ort für mein Vorhaben sein, und bis Ihr dort seid, sollte ich auch alles vorbereitet haben und online gehen können.\"\n\n\"Eskortiert ihn sicher bis zum Dock und kommt dann zu mir nach Booty Bay! Oglethorpe Obnoticus - Ende!\"", progress = nil, completion = "Ach, IHR habt so heldenhaft OOX-22/FE gerettet! Ich kann meine Dankbarkeit für Eure Hilfe noch nicht einmal ansatzweise ausdrücken! In meine Serie von Leitrobotern muss noch viel Entwicklungsaufwand gesteckt werden, aber Eure Bergung des Roboters hat mir zahllose Stunden zusätzlicher Schraubarbeit gespart, ganz zu schweigen von dem vielen Gold, das ich spare, weil ich ihn nicht neu bauen muss!\n\nBitte sucht Euch einen von diesen Gegenständen hier aus. Ich danke Euch nochmals für Eure großzügige Hilfe, &lt;Name&gt;, meine Roboter und ich stehen in Eurer Schuld!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFehlgeschlagenes FlugexperimentMaschendrahthandtuch\n\nIhr bekommt außerdem:\n\n"},
[2768] = {title = "Wünschel-mato-Rute", objective = "Bringt die Wünschel-mato-Rute nach Gadgetzan zu Chefingenieur Bilgewhizzle.", description = "Sergeant Bly hat mich bestohlen! Er sagte, er wolle sie sich nur ausleihen, aber er hat meine geliebte Wünschel-mato-Rute gestohlen! Wo soll ich denn bitte ohne diese Rute wissen, wo ich neue Wasserlöcher graben muss?\n\nFindet Bly und bringt mir meine Rute! Ich habe gehört, er hätte seine Bande von zwielichtigen Abenteurern auf eine Schatzsuche nach Zul'Farrak im Westen geführt. Ich möchte wetten, dort findet Ihr ihn.\n\nHoffen wir, dass die Trolle ihn schon erledigt haben, denn falls Ihr Euch wegen der Rute mit ihm anlegen müsst, dann steht Euch ein schwerer Kampf bevor.", progress = "Habt Ihr Sergeant Bly gefunden? Habt Ihr meine Wünschel-mato-Rute bekommen?", completion = "Ihr habt sie gefunden! Gut gemacht, &lt;Name&gt;! Musstet Ihr mit Bly darum kämpfen? Ich hoffe, Ihr habt ihm und seiner Bande kräftig eingeschenkt!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMasons BruderschaftsringIngenieursgildenkopfstück\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[2769] = {title = "Die Brüder Brassbolt", objective = "Sprecht mit Wizzle Brassbolts in der schimmernden Ebene.", description = "Seid Ihr den Gebrüdern Brassbolt schon mal begegnet? Sie sind drüben in der schimmernden Ebene, in Kalimdor, um genau zu sein, und treten dort in Raketenwagenrennen gegen die Goblins an. Normalerweise gewinnen sie, aber das ist keine große Überraschung - der Wagen der Goblins fliegt so oft in die Luft, dass er es kaum jemals über die Ziellinie schafft!\n\nAber trotzdem suchen die Brassbolt-Brüder ständig nach neuen Möglichkeiten, ihren Wagen noch schneller zu machen, und Wizzle hat mir gesagt, dass er für sein nächstes Experiment noch eine sehr seltene Komponente benötigt.\n\nWahrscheinlich kommt er an dieses Ersatzteil nicht allein ran. Sprecht mit ihm, dann erfahrt Ihr mehr darüber.", progress = nil, completion = "Ihr möchtet mir also helfen? Großartig!\n\nEs gibt da so ein bestimmtes Teil, das ich für ein Experiment brauche, an dem ich gerade arbeite. Da kommt mir so ein tapferer &lt;Klasse&gt; wie Ihr gerade recht. Ihr könntet es mir beschaffen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2770] = {title = "Gahz'rilla", objective = "Bringt Wizzle Brassbolts in der schimmernden Ebene Gahz'rillas energiegeladene Schuppe.", description = "Tief im Inneren von Zul'Farrak, der Stadt der Sandtrolle in Tanaris, liegt ein hochheiliger Teich. An diesem Teich beschwören die Trolle eine gewaltige Bestie, Gahz'rilla! Der ist so wild, dass sogar seine Schuppen vor Energie knistern. Und genau diese Energie will ich in meinem Wagen einsetzen.\n\nBringt mir die energiegeladene Schuppe von Gahz'rilla!\n\nWie man Gahz'rilla allerdings beschwört, das verraten die Trolle niemandem. Wenn Ihr ihm begegnen wollt, müsst Ihr daher erst den Trollen das Geheimnis entreißen.", progress = "Habt Ihr die Schuppe? Ich kann es kaum erwarten, die Energie darin auf unterschiedlichste Weise einzusetzen!", completion = "Toll, Ihr habt die Schuppe bekommen! Danke, &lt;Name&gt;. Ich kann es gar nicht erwarten, endlich an die Arbeit zu gehen!\n\nIhr habt Gahz'rilla also gesehen? War er so groß, wie alle sagen?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nKarotte am Stiel"},
[2771] = {title = "Ein schlauer Kopf auf den Schultern", objective = "Bringt Trenton Lighthammer 2 Mithrilhelmkappen und 1 verschnörkelte Mithrilschulter.", description = "Es scheint, als habe der Meister dies von Anfang an geplant. Ich habe nicht gelernt, solche Gegenstände herzustellen, wie Ihr es könnt, und Ihr habt nicht gelernt, solche Gegenstände herzustellen, wie ich es kann.\n\nDer Meister ist klug, <Name>. Wir werden uns gegenseitig etwas beibringen!\n\nZeigt mir, wie man eine Mithrilhelmkappe und verschnörkelte Mithrilschultern herstellt, dann zeige ich Euch, wie man einen verschnörkelten Mithrilhelm macht.", progress = "Habt Ihr die Gegenstände schon alle angefertigt, <Name>?", completion = "Ausgezeichnet! Ein fairer Tausch, wenn ich das sagen darf. Seht zu und lernt, &lt;Name&gt;!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVerschnörkelten Mithrilhelm lehren\n\nIhr bekommt:\n\n"},
[2772] = {title = "Die Welt zu Euren Füßen", objective = "Bringt Trenton Lighthammer 2 schwere Mithrilstiefel und 1 verschnörkelte Mithrilhose.", description = "Bei der Talmeisterschaft der Schmiedekunst letztes Jahr mussten alle, die zusahen, erleben, wie mir so ein feiger Hund von der Gießerei der Venture Company die Beine unter dem Körper wegzog. Aber den Grund, warum ich weitermachen und die Meisterschaft am Ende gewinnen konnte, den wusste niemand. Genau, verschnörkelte Mithrilstiefel!\n\nAber für die Meisterschaft dieses Jahr muss ich lernen, wie man verschnörkelte Mithrilhosen fertigt, denn ich muss gegen einen Schredder der Venture Co. antreten! Bringt mir bei, wie man die Hosen anfertigt, und lernt, was es mit den Stiefeln auf sich hat!", progress = "Habt Ihr die Gegenstände schon alle angefertigt, <Name>?", completion = "Die Welt wird Euch zu Füßen liegen, &lt;Name&gt;! Lasst sie ruhig alle Eure Beine angreifen, kein Fußfeger kann Euch jetzt noch etwas anhaben!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVerschnörkelte Mithrilstiefel lehren\n\nIhr bekommt:\n\n"},
[2773] = {title = "Mithril-Kid", objective = "Bringt Trenton Lighthammer 2 schwere Mithrilbrustplatten und 1 verschnörkelten Mithrilhandschuh.", description = "Hier in der Gegend bin ich als Mithril-Kid bekannt. Ich beliefere Abenteurer aus aller Welt mit verschnörkeltem Mithril.\n\n<Trenton flüstert.>\n\nDie wissen aber nicht, dass ich bisher noch keine verschnörkelten Mithrilhandschuhe herstellen kann. Psst! Das bleibt unser kleines Geheimnis, ja?\n\nBringt mir bei, wie man verschnörkelte Mithrilhandschuhe fertigt, <Name>, dann zeige ich Euch im Gegenzug den Höhepunkt meiner Ausbildung unter Galvan: die verschnörkelte Mithrilbrustplatte.", progress = "Habt Ihr die Gegenstände schon alle angefertigt, <Name>?", completion = "Ich danke Euch für alles, was Ihr mich gelehrt habt, &lt;Name&gt;. Schon bald wird der König aller verschnörkelten Mithrilrüstungsteile in Eurem Besitz sein.\n\nMerkt auf!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVerschnörkelte Mithrilbrustplatte lehren\n\nIhr bekommt:\n\n"},
[2781] = {title = "GESUCHT: Kalif Skorpidstich", objective = "Bringt Chefingenieur Bilgewhizzle in Gadgetzan den Kopf von Kalif Skorpidstich.", description = "GESUCHT: Kalif Skorpidstich!\n\nDie Gadgetzan Water Company aus Gadgetzan in Tanaris ist bereit, eine hohe Belohnung für den Kopf von Kalif Skorpidstich, dem Anführer der Wüstenläufernomaden, zu zahlen. Seine Verbrechen belaufen sich auf:\n\n1. Ermordung von Angestellten der Gadgetzan Water Company!\n2. Stehlen von Rohstoffen der Gadgetzan Water Company!\n3. Besetzen von Eigentum der Gadgetzan Water Company!\n\nBringt Beweise für Kalif Skorpidstichs Untergang zu Chefingenieur Bilgewhizzle und Ihr werdet umgehend belohnt!", progress = "Ja, <Klasse>, ich bin ein Vertreter der Gadgetzan Water Company. Was kann ich für Euch tun?", completion = "Endlich ist der Gerechtigkeit Genüge getan! Ihr habt diesen üblen Nomaden einen mächtigen Schlag versetzt! Skorpidstichs Untergang könnte entscheidend dafür sein, diese Herumtreiber endlich von Gadgetzans Wasserbrunnen zu vertreiben!\n\nIm Namen der Gadgetzan Water Company überreiche ich Euch mit Freuden dieses Kopfgeld. Ihr habt uns allen einen großen Dienst erwiesen.", rewards = "Ihr bekommt:\n\n"},
[2782] = {title = "Rin'jis Geheimnis", objective = "Oran Snakewrithe, eine bekannte Gelehrte auf dem Gebiet der Witherbarktrolle, könnte die Tafel vielleicht übersetzen. Normalerweise hält sie sich im Magierviertel von Undercity auf.", description = "Die Tafel ist mit Schriftzeichen der Witherbarktrolle bedeckt. Rin’jis Geheimnis ist wirklich ein Mysterium... \n\nGut möglich, dass Ihr hier etwas ziemlich Wertvolles in Händen haltet. Andererseits könnte ebenso gut das Gegenteil der Fall sein. Ein Troll der Witherbark in Not würde wahrscheinlich alles tun, um einen Ausweg aus seinen Problemen zu finden...", progress = "Ja, nun, was ist denn das?", completion = "Diese Schrifttafel... Ziemlich ungewöhnlich... Wo habt Ihr die gefunden, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\n"},
[2783] = {title = "Kleinliches Gezänk", objective = "Sprecht mit dem gefallenen Helden der Horde im Grenzgebiet zwischen den verwüsteten Landen und dem Sumpf.", description = "Wir bekämpfen den falschen Feind, <Name>.\n\nDie wahre Macht in diesem Land wird zahlen- und kräftemäßig immer stärker, während wir uns mit den Orcs über verbrannte Erde zanken.\n\nSollen wir wirklich in diesem Land einen Krieg gegen die Horde führen, nur um eines Tages von den Armeen der Brennenden Legion hinweggefegt zu werden? Es ist sinnlos.\n\nBegrabt Eure Streitigkeiten, <Name>, und sprecht mit dem gefallenen Helden der Horde. Er kennt die Wahrheit über die verwüsteten Lande.", progress = nil, completion = "Die Allianz möchte helfen?\n\nIch hätte nicht gedacht, dass ich diesen Tag noch einmal erleben darf. Ein Tag, an dem die Allianz Seite an Seite mit der Horde gegen einen gemeinsamen Feind kämpft.\n\nSo soll es sein... wir werden uns verbünden.", rewards = "Ihr bekommt:\n\n"},
[2784] = {title = "In Ungnade fallen", objective = "Lauscht der Geschichte des gefallenen Helden der Horde.", description = "Hört meine Geschichte, <Volk>.", progress = "Hört, was ich zu sagen habe.", completion = "Als Geist bin ich machtlos, &lt;Name&gt;. Unterstützt mich. Erlaubt es mir, meine Ehre wiederzuerlangen.", rewards = "Ihr bekommt:\n\n"},
[2801] = {title = "Eine Geschichte voller Leid", objective = "Lauscht der Geschichte des gefallenen Helden der Horde.", description = "Bevor wir fortfahren können, müsst Ihr meine Geschichte hören.", progress = "Hört, was ich Euch zu sagen habe, <Name>.", completion = "Es ist an der Zeit zu handeln, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[2821] = {title = "Das Zeichen der Qualität", objective = "Bringt Pratt McGrubben in der Festung Feathermoon 10 dicke Yetibälge.", description = "Meine Einstellung zur Lederverarbeitung verlangt, dass die Arbeit von bestmöglicher Qualität zu sein hat - ohne Kompromisse. Jeder, der behauptet, Qualität sei unwichtig, wird auch versuchen, Euch ein Küstengrundstück in Dun Morogh zu verkaufen!\n\nAuf meiner jüngsten Suche nach hochwertigem Material fand ich dicke Yetibälge. Die Yeti sind in Feralas zuhause und viele findet man im Wildschrammtal. Ich hätte gern welche, und wenn Ihr mir zehn davon bringt, dürft Ihr Euch ein beliebiges Stück meiner Lederwaren aussuchen. Haltet Ihr das für angemessen? Dann sind wir im Geschäft.", progress = "Ein Zehnerstapel dicke Yetibälge bringt Euch eines meiner Handwerksstücke nach Eurer Wahl ein. Da ich auf Qualität achte, kann ich Euch versichern, dass Ihr einen guten Gegenstand erhaltet.\n\nFalls Ihr keine Yetis finden könnt, weiß ich, wo einige sein könnten. Geht von der Vergessenen Küste aus ein Stück ins Landesinnere und schaut Euch dort um, etwa auf Höhe des Wildschrammtals.", completion = "Habt Ihr Euch einmal die Zeit genommen, Euch die Beschaffenheit dieser Bälge anzusehen? Wenn man sie richtig behandelt, könnten sie tatsächlich härter sein als Eisen. Nicht viele Leute wissen von diesen Bälgen. Dazu kommt meine Kenntnis hinsichtlich verschiedener Behandlungsmethoden, die es mir erlauben wird, daraus Gegenstände mit einem echten Zeichen der Qualität herzustellen ... dank Euch natürlich!\n\nUnd jetzt sucht Euch doch bitte etwas von dem aus, was ich Euch für Euren Dienst anbieten kann!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPratts handgefertigte StiefelPratts handgefertigte Handschuhe\n\nIhr bekommt außerdem:\n\n"},
[2822] = {title = "Das Zeichen der Qualität", objective = "Bringt Jangdor Swiftstrider im Camp Mojache 10 dicke Yetibälge.", description = "Ich bin stolz auf meine Lederarbeiten und ich glaube, das sieht man ihnen an; Qualität sollte niemals zweitrangig sein. Jeder, der behauptet, Qualität sei unwichtig, wird Euch wahrscheinlich auch glauben machen wollen, dass die Erde keine Geheimnisse enthält!\n\nAuf meiner jüngsten Suche nach hochwertigem Material habe ich dicke Yetibälge entdeckt. Die Yetis sind in Feralas beheimatet und man findet sie häufig westlich des Wildschrammtals. Ihr dürft Euch ein beliebiges Stück meiner Lederwaren aussuchen für einen Zehnerstapel Yetibälge. Wenn das für Euch akzeptabel ist, dann sind wir im Geschäft!", progress = "Habt Ihr einen Stapel von zehn dicken Yetibälgen beschaffen können? Meine Lederwaren sind die besten und ich überlasse Euch ein solches Teil, wenn Ihr die Bälge beibringen solltet.\n\nFalls Ihr keine Yetis finden könnt, weiß ich, wo einige sein könnten. Schaut Euch im Westen um, landeinwärts von der Vergessenen Küste aus, beim Wildschrammtal.", completion = "Ah, wunderbar! Ich sage Euch, diese Bälge sind so widerstandsfähig wie Eisen, man muss ihnen nur eine besondere Behandlung zuteil werden lassen. Es wird einige Versuche kosten, die richtige Mischung zum Gerben zu finden, aber ich bin zuversichtlich, dass sie mein Zeichen der Qualität noch weiter aufwerten werden.\n\nAber nun zu Euch, &lt;Name&gt;: Eure Hilfe hat sich als unschätzbar für mich erwiesen. Bitte sucht Euch einen der Gegenstände aus, die ich hergestellt habe.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nJangdors handgefertigte StiefelJangdors handgefertigte Handschuhe\n\nIhr bekommt außerdem:\n\n"},
[2841] = {title = "Maschinenkriege", objective = "Besorgt die Maschinenblaupausen und Thermapluggs Safekombination aus Gnomeregan und bringt sie zu Nogg nach Orgrimmar.", description = "Vor zwei Jahren noch hat man sich jedesmal darüber lustig gemacht, wenn die Rede auf Gnomentechnologie kam. Diese Zeiten haben sich definitiv geändert. Jetzt haben sie eine neue Maschine gebaut, die besser ist als all unsere Schreddermodelle zusammen. Ich brauche die Blaupausen dafür, <Name>!\n\nDummerweise sind die Pläne in einem Safe bei Robogenieur Thermaplugg sicher verwahrt. Was die Sache noch erschwert: Nur Robogenieur Thermaplugg kennt die Kombination zu diesem Safe.\n\nTut, was Ihr tun müsst, um diese Kombination zu erlangen, <Name>. Dann öffnet den Safe und bringt mir diese Blaupausen!", progress = "Ich sehe keine Blaupausen. Habt Ihr sie irgendwo unter Euren Kleidern versteckt oder steht Ihr hier nur rum, um mir auf die Nerven zu gehen?", completion = "Ich wusste, Ihr könnt es schaffen, &lt;Name&gt;! Sovik wiederum hatte seine Zweifel.\n\n\n\nJetzt, da wir die Blaupausen besitzen, ist es nur noch eine Frage der Zeit, bis wir alle Gnomeninnovationen enträtselt haben, die beim Bau dieser Maschine gemacht wurden, und sie zu Goblininnovationen für unsere neuen Schreddermodelle machen können.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nCivinad-RobenStolperläufer-LatzhoseZweifach verstärkte Gamaschen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[2842] = {title = "Chefingenieur Scooty", objective = "Sprecht mit Scooty in Booty Bay.", description = "In dem Moment, als wir durch Kernobee von der neuen Gnomen-Maschine hörten, haben Scooty und ich mit der Arbeit am Transpolyporter 6000 begonnen: dem schnellsten und verlässlichsten Weg nach Gnomeregan.\n\nEndlich ist er bereit, Passagiere aufzunehmen, <Name>. Wenn Ihr es einmal versuchen wollt, geht nach Booty Bay und redet mit Scooty am Windreiterhorst. Um nach Booty Bay zu gelangen, nehmt das Boot von Ratchet aus.\n\nNatürlich könnt Ihr auch versuchen, Euch durch die von Zwergen verseuchten Berge von Dun Morogh nach Gnomeregan durchzuschlagen!", progress = nil, completion = "Ist sie nicht eine Schönheit? Ein Meisterstück der Goblin-Transporttechnologie - ist nur ein Dutzend Mal oder so explodiert.\n\nKeine Sorge, &lt;Name&gt;, ich habe sie vollständig repariert. Sie wird Euch nicht um die Ohren fliegen - und falls doch, dann wird es schnell und schmerzlos sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2843] = {title = "Gnomer-weeeeg!", objective = "Wartet, bis Scooty den Goblin-Transponder kalibriert hat.", description = "Solange Ihr den Transponder bei Euch habt, müsst Ihr lediglich auf diese Plattform hier treten und Ihr werdet nach Gnomeregan teleportiert.\n\nIhr werdet vielleicht ein paar ungewöhnliche Nebenwirkungen erleben, aber keine davon sollte dauerhaft sein... zumindest nicht mehr.\n\nIch hätte fast den wichtigsten Teil vergessen - die Rückkehr. Wenn Ihr wieder zurückkommen wollt, tretet einfach auf die Transpolyporter-Plattform in Gnomeregan!\n\nJetzt lasst uns diesen Transponder auf Euer Gewicht und Eure Größe einstellen.", progress = nil, completion = "Das war's! Wenn Ihr so weit seid, tretet einfach auf die Plattform.", rewards = "Ihr bekommt:\n\nGoblin-Transponder"},
[2844] = {title = "Der Riesenwächter", objective = "Findet das verlorene Nachtelfen-Mädchen.", description = "Ich bin so unfähig, <Name>. Ich sollt' auf meine kleine Freundin, Shay, aufpassen, aber irgendwie ist sie mir verlor'n gegangen. Ich kann nicht genau sagen, was passiert ist, ehrlich, aber als ich sie das letzte Mal gesehen habe, lief’n wir durch die Ruinen direkt nördlich von hier.\n\nAlles war wunderbar, aber dann hab ich mich umgedreht, un’ ... sie war weg.\n\nUnd jetz' hab ich keine Ahnung, was ich tun soll. Habt Ihr 'ne Idee, <Name>? Ich mache mir furchtbare Sorgen.\n\nHey, wie wär’s, wenn Ihr nach Shay suchen würdet? Eure Beine sind viel schneller als meine.", progress = nil, completion = "Oh, ich bin ja so froh, dass Ihr mich gefunden habt! Ich muss zugeben, ich habe mich ein bisschen verlaufen... Aber ist das hier nicht ein schöner Ort?", rewards = "Ihr bekommt:\n\n"},
[2845] = {title = "Streunende Shay", objective = "Nehmt Shays Glocke aus der Truhe.\n\nBegleitet Shay Leafrunner zu Felsbeißers Lager.", description = "Glaubt Ihr, Ihr könnt mir helfen, meinen Weg zurück zu meinem Freund, Felsbeißer, zu finden? Er sollte auf mich aufpassen... Aber ich neige dazu, gelegentlich davonzuschlendern. Es gibt immer so viele Dinge zu sehen und ich lasse mich dann ablenken.\n\nEs gibt allerdings etwas, was immer meine Aufmerksamkeit erregt.\n\nIn dieser Truhe findet Ihr eine Glocke, die mir sehr teuer ist. Ich liebe einfach ihren Ton. Ihr habt mein Wort: Wenn ich davonschlendere, müsst Ihr lediglich damit klingeln und ich komme angelaufen.", progress = "Ich hab angefangen, mir um Euch Sorgen zu machen! Vielen Dank, dass Ihr Shay nach Hause gebracht habt, <Name>.", completion = "Was? Ihr sagt, die Glocke hier hilft, wenn Shay davonläuft? Na, wenn das nichts ist!\n\nDa Ihr so viel für mich getan habt, nehmt das, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGranithandschutzRankenhecken-Sattelgurt\n\nIhr bekommt außerdem:\n\n"},
[2846] = {title = "Tiara der Tiefen", objective = "Bringt die Tiara der Tiefen zu Tabetha in den Marschen von Dustwallow.", description = "Vor langer Zeit besaß ich ein wunderschönes Schmuckstück, die Tiara der Tiefen. Diese war nicht nur schön, sondern enthielt auch große Macht für diejenigen, die damit umzugehen wussten.\n\nAls nun die Kunde von der Tiara die Wasserbeschwörerin Velratha erreichte, musste sie sie haben. Sie schickte Handlanger in mein Haus und die stahlen sie, während ich weg war. Diese Diebe!\n\nIch will meine Tiara wiederhaben! Geht nach Zul'Farrak, der Trollstadt in Tanaris, findet Velratha und ringt ihr die Tiara ab. Bringt sie mir zurück und Ihr steht in meiner Gunst.", progress = "Habt Ihr die Tiara, <Name>? Hat Velratha den Preis dafür erfahren, sich mit mir anzulegen?", completion = "Wunderbar! Ihr habt sie gefunden! Und was genauso wichtig ist - Velratha hat sie nicht mehr! Danke, &lt;Name&gt;. Ich stehe für immer in Eurer Schuld.\n\nUnd falls ich zuvor etwas... gemein klang, achtet nicht darauf. Ihr werdet feststellen, dass ich eine viel nettere Person denen gegenüber bin, die mich nicht bestohlen haben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nZauberformerruteEdelsteinschiefer-Schulterstücke"},
[2847] = {title = "Wildlederrüstung", objective = "Bringt Pratt McGrubben in der Festung Feathermoon 10 Stücke dickes Leder.", description = "<Name>, Ihr werdet ziemlich gut als Lederer! Ich kenne da einige Muster, an denen Ihr vielleicht interessiert seid... Wildlederrüstung! Wildleder zieht Kraft aus den mächtigen und chaotischen Eigenschaften von Wildranken, die man in Gegenden mit üppiger Vegetation auf einigen der Kreaturen dort findet. Die daraus gefertigte Rüstung ist garantiert das Beste, was jemand Eures Geschicks herstellen kann.\n\nIch werde es Euch beibringen, aber Ihr werdet dafür eine Weile für mich arbeiten. Das Lehrgeld beträgt nur 10 Stücke dickes Leder. Danach reden wir über Details.", progress = "Wie ich schon sagte, werdet Ihr eine Weile für mich arbeiten, während Ihr alles über die Herstellung von Wildlederrüstungen lernt. Da Wildranken sowohl mächtig als auch chaotisch sind, verbessert sich die Rüstung, die Ihr herstellen werdet, auf zufällige, aber mächtige Art und Weise. Dieses Wissen war jedoch nicht einfach zu erwerben.\n\nDas Lehrgeld für diesen Prozess beträgt 10 Stücke dickes Leder.\n\nSobald das erledigt ist, kommen wir zu der Arbeit, die Ihr erledigen müsst, um die Muster zu erhalten.", completion = "Tja, &lt;Name&gt;, es ist schön, Euch dabeizuhaben. Ihr habt als Lederer eine kluge Entscheidung getroffen; diejenigen, die Lederrüstungen verwenden, werden Euch die Bude einrennen, sobald Ihr gelernt habt, wie man Wildlederrüstungen herstellt.\n\nDann machen wir uns mal an die Arbeit... Womit wollt Ihr anfangen?", rewards = "Ihr bekommt:\n\n"},
[2848] = {title = "Wildlederschultern", objective = "Bringt Pratt McGrubben in der Festung Feathermoon 6 dicke Rüstungssets und eine Wildranke.", description = "Wildlederschultern verstärken den Körper des Trägers unglaublich gut und bieten dabei erstklassigen Schutz für die Oberarme und die Schultern. Wie bei allen Wildlederrüstungen wird auch hier eine mächtige, allerdings zufällige Verbesserung erzeugt, wenn die Wildranke eingearbeitet wird.\n\nFür dieses Muster werde ich 6 dicke Rüstungssets und eine Wildranke benötigen. Das sollte für Euch kein allzu schwer zu erfüllender Auftrag sein.", progress = "Habt Ihr die 6 dicken Rüstungssets und die Wildranke, die ich benötige?\n\nSeht die Anfertigung von Rüstungssets nicht als monotone Arbeit an; der gleichmäßige Stil, den Ihr bei der Ausübung Eures Handwerks entwickelt, hilft dabei, Eure Fertigkeiten so weit zu entwickeln, dass Ihr die aufwändige Arbeit erledigen könnt, die man für die Herstellung von Wildlederrüstungen braucht.\n\nSeht, es gibt einen guten Grund für das, was Ihr für mich macht...", completion = "Diese Rüstungssets sind von robuster Qualität, &lt;Name&gt;. Wenn es etwas gibt, das ich nicht nur von meiner Arbeit erwarte, sondern auch von der Arbeit derer, die für mich arbeiten, dann ist das Qualität.\n\nIhr habt Euch dieses Muster wohlverdient; ich hoffe, es bringt Euch dieselbe Anerkennung, die es mir gebracht hat.", rewards = "Ihr bekommt:\n\nMuster: Wildlederschultern"},
[2849] = {title = "Wildlederweste", objective = "Bringt Pratt McGrubben in der Festung Feathermoon 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke.", description = "Wildlederwesten sind die Grundlage aller Wildlederrüstungssets. Das Gerüst der Weste verbindet sich mit der Wildranke, um ein Produkt zu erzeugen, das sowohl maximalen Schutz für den Torso bietet als auch der mächtigen Magie erlaubt, sich in dem Gewand auszubreiten.\n\nFür dieses Muster werde ich 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke benötigen. Das ist ein großer Auftrag, aber sicher keiner, bei dessen Erfüllung Ihr Schwierigkeiten haben werdet.", progress = "Habt Ihr die beiden Schildkrötenschuppenbrustplatten und -handschuhe, die ich bestellt habe? Und vergesst bitte die Wildranke nicht!\n\nSchon mit den einfachsten Mustern können wir lernen, dass sich die Grundsätze der Formen leicht auf komplexere Gewänder übertragen lassen. Auf verschiedene Weise bereitet Euch die Form der Schildkrötenschuppenbrustplatten auf den Detailreichtum vor, der für die Herstellung von Wildlederwesten benötigt wird.\n\nUnd die Handschuhe... tja, die sind nur für meinen eigenen Bedarf. Vergesst nicht, Ihr arbeitet für mich!", completion = "Das hier sind ein paar sehr schöne Stücke, &lt;Name&gt;. Durch die Handwerkskunst und Sorgfalt, die in ihre Fertigung gesteckt wurden, werden sie einige Silbermünzen mehr einbringen als ein durchschnittlich gefertigtes Stück.\n\nIhr habt meinen Auftrag erledigt und daher erhaltet Ihr Eure Belohnung. Das Wissen um die Herstellung von Wildlederwesten ist jetzt Euer.", rewards = "Ihr bekommt:\n\nMuster: Wildlederweste"},
[2850] = {title = "Wildlederhelm", objective = "Bringt Pratt McGrubben in der Festung Feathermoon 2 Tuniken des Nachtschleichers, 2 Stirnbänder des Nachtschleichers und eine Wildranke.", description = "Ein Wildlederhelm bietet dem Träger verbesserten Kopfschutz, ohne dabei an der Bequemlichkeit zu sparen. Wie bei allen Wildlederrüstungen erzeugt die eingearbeitete Wildranke eine mächtige, aber zufällige Verbesserung der Struktur des Helms. Lederträger werden dieses Stück auf jeden Fall haben wollen!\n\nFür dieses Muster brauche ich 2 Tuniken des Nachtschleichers, 2 Stirnbänder des Nachtschleichers und eine Wildranke. Erfüllt diesen Auftrag und das Muster gehört Euch!", progress = "Ich muss erst diese Tuniken und Stirnbänder gefertigt sehen und benötige außerdem das Stück Wildranke, bevor ich das Wissen von den Wildlederhelmen mit Euch teilen kann.\n\nKopfbedeckungen sind unter Abenteurern sehr begehrt, sei es ein entwaffnend einfaches Stirnband oder ein Vollhelm. Die Grundlagen zur Herstellung wertvoller Kopfbedeckungen bleiben dieselben, welcher Gestalt auch immer letztendlich die Ausrüstung ist.", completion = "Diese Ausrüstung des Nachtschleichers, die Ihr geliefert habt, erfüllt den Auftrag perfekt, &lt;Name&gt;. Ich erwarte nicht weniger von einem Lederer Eures Kalibers.\n\nIhr habt Euch dieses Muster sicherlich verdient. Ich gebe es Euch gern und hoffe, dass Ihr davon entsprechend profitieren werdet.", rewards = "Ihr bekommt:\n\nMuster: Wildlederhelm"},
[2851] = {title = "Wildlederstiefel", objective = "Bringt Pratt McGrubben in der Festung Feathermoon 2 Hosen des Nachtschleichers, 2 Stiefel des Nachtschleichers und 2 Wildranken.", description = "Ihr habt schon eine ganze Menge gelernt, <Name>; dennoch gibt es noch mehr für Euch zu lernen. Als Nächstes sind Wildlederstiefel an der Reihe, der Grundstein eines jeden Sets.\n\nDiese Stiefel werden so gefertigt, dass sie den Fuß in Bequemlichkeit hüllen, während sie ihn gleichzeitig gegen die Gefahren des Abenteuerlebens wappnen. Die weichen Sohlen sind ein Segen für diejenigen, die bei ihrer Fußbekleidung auf leise Bewegung Wert legen.\n\nFür dieses Muster müsst Ihr mir 2 Hosen des Nachtschleichers und 2 Stiefel des Nachtschleichers besorgen. Ich werde außerdem zwei Wildranken benötigen, nicht nur eine. Wenn Ihr all das beisammen habt, gebt mir Bescheid.", progress = "Ihr müsst erst den Auftrag betreffs der Hosen, Stiefel und Wildranken erfüllen, bevor Ihr das Muster erhaltet, <Name>. Seid Ihr fertig?\n\nSchon mit den ersten Stiefeln, die man anzufertigen lernt, beginnt man zu verstehen, dass ein Qualitätsstiefel eine Gratwanderung zwischen Komfort und Funktion darstellt. Dank beider Dinge ist man in der Lage, Gegenstände herzustellen, die es dem Träger erlauben, Erschöpfungszustände zu ignorieren, die diejenigen, die Ware minderer Qualität tragen, lähmen würden.", completion = "Wieder einmal habt Ihr einen aufwändigen Auftrag mit dem Geschick einer erfahrenen Fachkraft erfüllt. Ihr habt Euch dieses Muster genauso verdient wie meinen Dank.", rewards = "Ihr bekommt:\n\nMuster: Wildlederstiefel"},
[2852] = {title = "Wildledergamaschen", objective = "Bringt Pratt McGrubben in der Festung Feathermoon 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken.", description = "Jetzt, nachdem Ihr die Grundlagen beherrscht, seid Ihr bereit, Euch komplexeren Dingen zuzuwenden, <Name>. Wildledergamaschen gehören zur robustesten und stärksten Lederausrüstung überhaupt. Bauch, Hüften, Schenkel und Solarplexus werden ungeheuer gut geschützt. Und wenn dann noch die Verstärkung hinzukommt, die die Wildranke bewirkt, werden Euch die Abenteurer, die diese Rüstung besitzen, jedes Mal danken, wenn sie Euch sehen.\n\nFür dieses Muster müsst Ihr mir 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken besorgen.", progress = "Habt Ihr die Schildkrötenschuppenarmschienen und -helme fertig? Und vergesst bitte nicht die beiden Wildranken, die ich brauche!\n\nInzwischen dürftet Ihr das Potenzial der Macht zu verstehen beginnen, das in Wildlederrüstungen steckt. Eine Rüstung, deren Anwendung keine Grenzen gesetzt sind, ist unschätzbar für einen Lederer. Einschränkungen bestehen lediglich in der Rohstoffmenge, aus der man die Gegenstände herstellen kann, nicht jedoch in der Qualität der Endprodukte!", completion = "Wieder einmal habt Ihr einen Auftrag fehlerlos abgewickelt. Vielleicht komme ich eines Tages ja noch auf der Suche nach Wissen zu EUCH, hm, &lt;Name&gt;?\n\nHier habt Ihr das Muster für die Gamaschen sowie meinen Dank. Nehmt diese Lehre in Euch auf und lasst Eure Endprodukte von Euren beeindruckenden Fähigkeiten profitieren!", rewards = "Ihr bekommt:\n\nMuster: Wildledergamaschen"},
[2853] = {title = "Meister des Wildleders", objective = "Gebt Telonis, dem Lederverarbeitungsmeister von Darnassus, Pratts Brief.", description = "Nun, <Name>, Ihr gebt dem Wort Sorgfalt eine neue Bedeutung. Es steht nur noch ein Wildlederrüstungsmuster aus, denn Ihr habt alle anderen gemeistert. Ich werde nicht von Euch verlangen, Euch unnötig für dieses Muster abzuplagen. Ihr habt es Euch bereits mehr als verdient... Aber ich kann es Euch nicht selbst geben. Mein Lehrer, derjenige, der mich in dieses Handwerk einführte, muss Euch belohnen.\n\nBringt diesen Brief zu Telonis. Er lehrt Lederverarbeitung in Darnassus. Zeigt ihm den Brief und lasst Euch von ihm als Gleichgestellten anerkennen, so wie ich das auch tue.", progress = "Seid gegrüßt, <Volk>... Eurem Aussehen nach seid Ihr ein Lederer wie ich. Seid Ihr hier, um etwas von meinem Geschick zu erlangen, oder habt Ihr vielleicht andere Geschäfte mit mir zu besprechen?", completion = "Ah ja, Pratt hat Euch geschickt. Auch wenn er ein Mensch ist, erinnert er mich doch gelegentlich an uns Nachtelfen. Seine Hingabe und seine Talente im Umgang mit Leder sind beeindruckend. Euch so in diesem Brief zu loben, ist ein Zeichen des Respekts, welches ich anerkenne.\n\nMir ist bewusst, dass er Euch die Kunst des Wildleders beigebracht hat. Erlaubt mir, Eure Ausbildung mit diesem Muster abzuschließen. Macht guten Gebrauch davon. Nur wenige auf der Welt kennen die Geheimnisse der Wildlederumhänge.", rewards = "Ihr bekommt:\n\nMuster: Wildlederumhang"},
[2854] = {title = "Wildlederrüstung", objective = "Bringt Jangdor Swiftstrider im Camp Mojache 10 Stücke dickes Leder.", description = "<Name>, Euer Ruf als Lederer eilt Euch voraus. Ich besitze Wissen über die Lederverarbeitung, das zu erwerben weise von Euch wäre... Wildlederrüstung! Wildleder zieht Kraft aus den mächtigen und chaotischen Eigenschaften von Wildranken, die man in Gegenden mit üppiger Vegetation auf einigen der Kreaturen dort findet. Die daraus gefertigte Rüstung ist garantiert das Beste, was ein Handwerker Eures Geschicks herstellen kann.\n\nIch werde es Euch beibringen, aber Ihr werdet dafür eine Weile für mich arbeiten. Das Lehrgeld beträgt nur 10 Stücke dickes Leder. Danach reden wir über Details.", progress = "Nur um es klarzustellen: Ihr werdet bei mir in die Lehre gehen, während Ihr die Kunst der Herstellung von Wildlederrüstungen erlernt. Da Wildranken sowohl mächtig als auch chaotisch sind, verbessert sich die Rüstung, die Ihr herstellen werdet, auf zufällige, aber mächtige Art und Weise. Dieses Wissen war jedoch nicht einfach zu erwerben.\n\nDas Lehrgeld für diesen Prozess beträgt 10 Stücke dickes Leder.\n\nSobald das erledigt ist, kommen wir zu der Arbeit, die Ihr erledigen müsst, um die Muster zu erhalten.", completion = "Nun, &lt;Name&gt;, ich bin froh, Euch als meinen Lehrling dabeizuhaben. Ihr habt als Lederer eine schlaue Entscheidung getroffen; diejenigen, die Lederrüstungen verwenden, werden Euch die Bude einrennen, sobald Ihr gelernt habt, wie man die Kunst des Wildleders meistert.\n\nLasst uns an die Arbeit gehen - womit wollt Ihr anfangen?", rewards = "Ihr bekommt:\n\n"},
[2855] = {title = "Wildlederschultern", objective = "Bringt Jangdor Swiftstrider im Camp Mojache 6 dicke Rüstungssets und eine Wildranke.", description = "Wildlederschultern verstärken den Körper des Trägers unglaublich gut und bieten dabei besten Schutz für Oberarme und Schultern. Wie bei allen Wildlederrüstungen wird auch hier eine zufällige, aber magieerfüllte Verbesserung erzeugt, wenn die Wildranke eingearbeitet wird.\n\nFür dieses Muster werde ich 6 dicke Rüstungssets und eine Wildranke benötigen. Das sollte für Euch kein allzu schwer zu erfüllender Auftrag sein.", progress = "Habt Ihr die 6 dicken Rüstungssets und die Wildranke, die ich benötige?\n\nSeht die Anfertigung von Rüstungssets als Übung in gleichmäßiger und verlässlicher Herstellung an. Der einheitliche Stil, den Ihr bei der Ausübung Eures Handwerks entwickelt, hilft Euch dabei, Eure Fertigkeiten so weit zu entwickeln, dass Ihr die aufwändige Arbeit erledigen könnt, die man für die Herstellung von Wildlederrüstungen braucht.\n\nJede Lektion hat ihren Sinn, <Name>. Es ist daher wichtig, jede davon bereitwillig anzunehmen.", completion = "Diese Rüstungssets sind von robuster Qualität, &lt;Name&gt;. Wenn es etwas gibt, was ich nicht nur von meiner Arbeit, sondern auch von der Arbeit derer erwarte, die ich unterweise, dann ist das Qualität.\n\nIhr habt Euch dieses Muster wohlverdient; ich hoffe, es bringt Euch dieselbe Anerkennung, die es mir gebracht hat.", rewards = "Ihr bekommt:\n\nMuster: Wildlederschultern"},
[2856] = {title = "Wildlederweste", objective = "Bringt Jangdor Swiftstrider im Camp Mojache 2 Schildkrötenschuppenbrustplatten, 2 Schildkrötenschuppenhandschuhe und eine Wildranke.", description = "Wildlederwesten sind die Grundlage jeglicher Wildlederrüstungssets. Die Struktur der Weste und das Wildrankengeflecht darin erzeugen ein Produkt, das sowohl maximalen Schutz für den Torso bietet, als auch der mächtigen Magie erlaubt, sich in dem Gewand auszubreiten.\n\nFür dieses Muster werde ich 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke benötigen. Dies ist keine einfache Lektion, aber eine, für die Ihr sicherlich das nötige Geschick habt.", progress = "Habt Ihr die beiden Schildkrötenschuppenbrustplatten und -handschuhe? Und vergesst bitte die Wildranke nicht!\n\nSelbst mit den einfachsten Mustern können wir lernen, dass sich die Grundsätze der Formen leicht auf komplexere Gewänder übertragen lassen. Auf verschiedene Weise bereitet Euch die Form der Schildkrötenschuppenbrustplatten auf den Detailreichtum vor, der für die Herstellung von Wildlederwesten benötigt wird.\n\nWährend Ihr in den Lektionen voranschreitet, werden die Fertigkeiten, die ich Euch beibringe, zu einer wahren Kunst werden.", completion = "Das hier sind ein paar sehr schöne Stücke, &lt;Name&gt;. Die Handwerkskunst und Sorgfalt, die in die Herstellung dieser Dinge geflossen sind, zeigen, dass Ihr beschlossen habt, Euch völlig diesen Aufgaben zu widmen.\n\nIhr habt meine Forderungen erfüllt und daher erhaltet Ihr Eure Belohnung. Das Wissen um die Herstellung von Wildlederwesten ist jetzt Euer.", rewards = "Ihr bekommt:\n\nMuster: Wildlederweste"},
[2857] = {title = "Wildlederhelm", objective = "Bringt Jangdor Swiftstrider im Camp Mojache 2 Tuniken des Nachtschleichers, 2 Stirnbänder des Nachtschleichers und eine Wildranke.", description = "Ein Wildlederhelm bietet dem Träger verbesserten Kopfschutz, ohne dabei an der Bequemlichkeit zu sparen. Wie bei allen Wildlederrüstungen erzeugt die eingearbeitete Wildranke eine mächtige, aber zufällige magische Verstärkung der Struktur des Helms. Lederträger werden dieses Stück auf jeden Fall haben wollen!\n\nFür dieses Muster brauche ich 2 Tuniken des Nachtschleichers, 2 Stirnbänder des Nachtschleichers und eine Wildranke. Schließt diese Lektion erfolgreich ab und das Muster gehört Euch!", progress = "Ich muss erst diese Tuniken und Stirnbänder gefertigt sehen und benötige außerdem das Stück Wildranke, bevor ich das Wissen von den Wildlederhelmen mit Euch teilen kann.\n\nKopfbedeckungen sind unter Abenteurern sehr begehrt, sei es ein entwaffnend einfaches Stirnband oder ein Vollhelm. Die Grundlagen zur Herstellung wertvoller Kopfbedeckungen bleiben dieselben, welcher Gestalt auch immer letztendlich die Ausrüstung ist.", completion = "Diese Ausrüstung des Nachtschleichers, die Ihr geliefert habt, entspricht genau den Anforderungen, die ich an Euch gestellt habe, &lt;Name&gt;. Ich erwarte nicht weniger von einem Lederer Eures Kalibers.\n\nIhr habt Euch die Ehre erworben, Wildlederhelme herzustellen. Ich gebe Euch dieses Muster gern und hoffe, dass Ihr davon entsprechend profitieren werdet.", rewards = "Ihr bekommt:\n\nMuster: Wildlederhelm"},
[2858] = {title = "Wildlederstiefel", objective = "Bringt Jangdor Swiftstrider im Camp Mojache 2 Hosen des Nachtschleichers, 2 Stiefel des Nachtschleichers und 2 Wildranken.", description = "Euer Wissen über die Herstellung von Wildlederrüstungen wächst, <Name>, aber trotzdem habt Ihr noch einiges zu lernen.\n\nWildlederstiefel sind die Grundlage eines jeden Sets. Diese Stiefel werden so gefertigt, dass sie den Fuß in Bequemlichkeit hüllen, während sie ihn gleichzeitig gegen die Gefahren des Abenteurerlebens wappnen. Die weichen Sohlen sind ein Segen für diejenigen, die bei ihrer Fußbekleidung auf leise Bewegung Wert legen.\n\nFür dieses Muster müsst Ihr mir 2 Hosen des Nachtschleichers und 2 Stiefel des Nachtschleichers herstellen. Ich werde außerdem zwei Wildranken benötigen, nicht nur eine. Wenn Ihr diese Dinge habt, werden wir weitermachen.", progress = "Ihr müsst mir erst die Hosen, Stiefel und Wildranken liefern, bevor Ihr das Muster erlernt, <Name>. Habt Ihr getan, worum ich Euch gebeten habe?\n\nSchon mit den ersten Stiefeln, die man anzufertigen lernt, beginnt man zu verstehen, dass ein Qualitätsstiefel eine Gratwanderung zwischen Komfort und Funktion darstellt. Dank beider Dinge ist man in der Lage, Gegenstände herzustellen, die es dem Träger erlauben, Erschöpfungszustände zu ignorieren, die diejenigen, die Ware minderer Qualität tragen, lähmen würden.", completion = "Wieder einmal habt Ihr Gegenstände mit dem Geschick einer erfahrenen Fachkraft hergestellt. Ihr habt Euch dieses Muster genauso verdient wie meinen Dank.", rewards = "Ihr bekommt:\n\nMuster: Wildlederstiefel"},
[2859] = {title = "Wildledergamaschen", objective = "Bringt Jangdor Swiftstrider im Camp Mojache 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken.", description = "Ihr seid so weit, komplexere Lektionen zu meistern, <Name>. Wildledergamaschen gehören zur robustesten und stärksten Lederausrüstung überhaupt. Bauch, Hüften, Schenkel und Solarplexus werden ungeheuer gut geschützt. Und wenn dann noch die Verstärkung hinzukommt, die die Wildranke bewirkt, werden Euch die Abenteurer, die diese Rüstung besitzen, jedes Mal danken, wenn sie Euch sehen.\n\nUm Euch dieses Muster zu geben, benötige ich 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken.", progress = "Habt Ihr die Schildkrötenschuppenarmschienen und -helme fertig? Und vergesst nicht die beiden Wildranken, die ich brauche!\n\nInzwischen dürftet Ihr das Potenzial der Macht zu verstehen beginnen, das in Wildlederrüstungen steckt. Eine Rüstung, deren Anwendung keine Grenzen gesetzt sind, ist unschätzbar für einen Lederer. Einschränkungen bestehen lediglich in der Rohstoffmenge, aus der man die Gegenstände herstellen kann, nicht jedoch in der Qualität der Endprodukte!", completion = "Wieder einmal habt Ihr meine Aufgabe fehlerlos bewältigt. Vielleicht komme ich eines Tages ja noch auf der Suche nach Wissen zu EUCH, hm, &lt;Name&gt;?\n\nHier habt Ihr das Muster für die Gamaschen sowie meinen Dank. Nehmt diese Lehre in Euch auf und lasst Eure Endprodukte von Euren beeindruckenden Fähigkeiten profitieren!", rewards = "Ihr bekommt:\n\nMuster: Wildledergamaschen"},
[2860] = {title = "Meister des Wildleders", objective = "Gebt Una, der Lederverarbeitungsmeisterin von Thunder Bluff, Jangdors Schreiben.", description = "<Name>, Ihr habt alles erlernt, was ich Euch lehren kann. Es gibt allerdings noch ein letztes Wildlederrüstungsmuster. Ich werde nicht von Euch verlangen, Euch unnötig dafür abzuplagen. Ihr habt es Euch bereits mehr als verdient. Jedoch kann ich dieses Muster nicht einfach mit Euch teilen.\n\nMein Lehrer, derjenige, der mich in dieses Handwerk einführte, muss Euch belohnen. Bringt diese Notiz zu Una. Sie lehrt Lederverarbeitung in Thunder Bluff. Zeigt ihr den Brief und lasst Euch von ihr als Gleichgestellten anerkennen, so wie ich das auch tue.", progress = "Seid gegrüßt, <Volk>... Eurem Aussehen nach seid Ihr ein Lederer wie ich. Seid Ihr hier, um etwas von meinem Geschick zu erlangen, oder habt Ihr vielleicht andere Geschäfte mit mir zu besprechen?", completion = "Ah, ja, Jangdor hat Euch geschickt. Es freut mich zu sehen, dass einer meiner besten Schüler nun selbst einen Schüler hat.\n\nSeine Hingabe und seine Talente im Umgang mit Leder sind beeindruckend. Euch so in diesem Brief zu loben, ist ein Zeichen des Respekts, das ich anerkenne.\n\nMir ist bewusst, dass er Euch die Kunst der Wildlederbearbeitung gelehrt hat. Erlaubt mir, Eure Ausbildung mit diesem Muster abzuschließen. Macht guten Gebrauch davon. Nur wenige auf der Welt kennen die Geheimnisse der Wildlederumhänge.", rewards = "Ihr bekommt:\n\nMuster: Wildlederumhang"},
[2861] = {title = "Tabethas Aufgabe", objective = "Sprecht mit Tabetha in den Marschen von Dustwallow.", description = "Gerüchte besagen, dass Tabetha, eine Magierkollegin, die tief in den Marschen von Dustwallow lebt, ein Hühnchen mit einem gewissen Sandtroll in Zul’Farrak zu rupfen hat. Wenn Ihr mit Tabetha sprecht, kann sie Euch sicher mehr dazu sagen.\n\nUnd nehmt ein paar Freunde mit, <Name>. Falls Tabetha Euch nach Zul’Farrak schickt, wollt Ihr sicher nicht allein hingehen.\n\nIhr findet Tabethas Hütte westlich von Theramore und direkt nördlich der Stonemaul Ruinen.", progress = nil, completion = "Das ist wahr. Ich habe mit einem Troll ein Hühnchen zu rupfen. Ein großes Hühnchen. Ein wirklich großes!\n\nWollt Ihr mir helfen?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2862] = {title = "Krieg gegen die Waldpfoten", objective = "Bringt Hadoken Swiftstrider im Camp Mojache 10 Mähnen eines Waldpfotengnolls.", description = "Die Gnolle... sie sind mehr als nur ein Ärgernis. Sie sind eine konstante Bedrohung für die Existenz dieses gesamten Lagers! Es ist unwichtig, ob sie Eingeborene des Feralas sind oder nicht. Wenn wir uns nicht gegen sie wappnen, werden wir uns eines Tages aus dem gesamten Gebiet vertrieben sehen.\n\nDie Gnoll-Angriffe auf das Lager wurden in letzter Zeit heftiger. Wir brauchen Eure Hilfe dabei, ihre Anzahl zu reduzieren. Bringt mir zehn ihrer Mähnen und ich werde Euch stattlich für Eure Mühe entlohnen.\n\nLos!", progress = "Wir schlagen sie zurück und trotzdem greifen sie weiter an! Irgendjemand oder irgendetwas muss sie zur Raserei treiben... Oh, Ihr seid wieder da, was, <Name>? Habt Ihr die Mähnen, die ich benötige, um das Kopfgeld auszahlen zu können?", completion = "Dies zeugt von einem guten Anfang, &lt;Name&gt;. Euer Geschick als Soldat verdient Lob.\n\nIhr seid nicht der Einzige, dem ich diesen Auftrag gab. Viele haben bereits vor Euch gegen sie gekämpft und in der Vergangenheit haben unsere Bemühungen sie in Schach gehalten. In letzter Zeit haben jedoch ihre Versuche, nordwärts in unser Einflussgebiet einzudringen, dramatisch zugenommen. Ihre Angriffe sind außerdem wilder geworden ... fast als wären sie verzweifelt.\n\nIch habe allerdings einen Plan, &lt;Name&gt;, der die Sache mit ihnen ein für alle Mal erledigen sollte ...", rewards = "Ihr bekommt:\n\n"},
[2863] = {title = "Schlag gegen die Alphas", objective = "Tötet 5 Alphas der Waldpfoten und kehrt innerhalb einer Stunde zu Hadoken Swiftstrider zurück.", description = "Der Plan besteht darin, verschiedene Anführer der Gnolle - Alphas, wie sie sich selbst nennen - in schneller Folge auszuschalten. Wenn wir einen solch schnellen und präzisen Schlag gegen sie erzielen können, würde es in ihren Rängen zu Chaos führen. Vielleicht würde es dann endlich auch in ihren dicken, von Flöhen zerbissenen Köpfen klar, dass wir sie vernichten können und werden!\n\nIch möchte, dass Ihr der Ausführende meines Willens seid. Eliminiert innerhalb einer Stunde fünf Alphas, wenn das klappen soll, <Name>, sonst bleiben wir in dieser Pattsituation!", progress = nil, completion = "Ihr habt getan, was ich wollte, und dafür beglückwünsche ich Euch. Nehmt diese kleine Belohnung als Entschädigung für Eure Mühen, &lt;Name&gt;.\n\nNachdem ihre Zahl verringert und ihre Anführer erschlagen sind, werden die Gnolle es sich zweimal überlegen, bevor sie unser Lager angreifen. Das löst das derzeitige Problem allerdings nicht...\n\nEs muss einen Grund geben, warum die Gnolle in eine solche Raserei verfallen sind. Bevor sie eine Chance haben, sich erneut zu sammeln, will ich herausfinden, was die Ursache dafür ist.", rewards = "Ihr bekommt:\n\n"},
[2864] = {title = "Tran'rek", objective = "Sprecht mit Tran’rek in Gadgetzan.", description = "Mein Vetter Tran’rek ist in Schwierigkeiten. Er versprach mir vor einer Woche eine Fuhre Skarabäuspanzerschalen und hat bisher nicht geliefert. Er ist mein Vetter, also würde ich es wirklich hassen, wenn ich jemanden nach Gadgetzan schicken müsste, um ihm etwas zu brechen.\n\nKönnt Ihr für mich mit Tran'rek sprechen? Lasst ihn wissen, dass er diese Lieferung zusammenbekommen muss, bevor ich irgendetwas Unüberlegtes mache.\n\nGadgetzan liegt im nördlichen Tanaris, in Kalimdor.", progress = nil, completion = "Hallo!\n\nOh, Ihr habt mit meinem Vetter Krazek gesprochen? Wie geht es ihm? Ich hoffe, Booty Bay bekommt ihm gut...\n\nSkarabäuspanzerschalen, sagt Ihr? Nun... lasst mich Euch eine Geschichte erzählen...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2865] = {title = "Skarabäuspanzerschalen", objective = "Bringt Tran’rek in Gadgetzan 5 unbeschädigte Skarabäuspanzerschalen.", description = "Die Skarabäen von Tanaris haben sehr harte Panzerschalen! Hart genug, um sie als Baumaterial für eine Menge Dinge zu verwenden. So viele Dinge!\n\nTatsächlich sind diese Panzer so nützlich... dass die Skarabäen beinahe bis zur Ausrottung gejagt wurden.\n\nIch weiß, wo es noch mehr Skarabäen gibt, und wenn Ihr mir versprecht, mir Ihre Panzerschalen zu bringen, sage ich Euch, wo sie sind. Versprochen?\n\nO.k., die Skarabäen haben eine Kolonie in Zul’Farrak. Ich schätze, die Trolle jagen sie nicht wegen ihrer Panzerschalen.\n\nAber Ihr könnt das tun! Geht nach Zul’Farrak und besorgt mir unbeschädigte Skarabäuspanzerschalen!", progress = "Habt Ihr die Panzerschalen? Mein Vetter in Booty Bay wartet auf eine Fuhre von ihnen und er wird ungeduldig!", completion = "Oh, wunderbar! Ihr habt sie!\n\nDanke, &lt;Name&gt;. Ihr seid ein echter Lebensretter!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2866] = {title = "Die Ruinen von Solarsal", objective = "Erforscht die Ruinen von Solarsal und findet etwas über die Anwesenheit der Naga dort heraus.", description = "Südlich von uns befinden sich die Ruinen von Solarsal. Dies ist eine Gegend aus längst vergangener Zeit. Wir haben die Ruinen ursprünglich erforscht und nichts Besonderes darin gefunden. Daher sind wir friedlich wieder abgezogen.\n\nVor kurzem haben die Hasskammnaga die Ruinen in alarmierender Anzahl besetzt. Zuerst hielten wir das für die Vorbereitungen auf einen Angriff. Obwohl diese Bedrohung immer noch gegeben ist, glauben wir, dass dort etwas anderes vorgeht.\n\nGeht dorthin, erforscht die Ruinen und achtet auf alles, was Euch ungewöhnlich vorkommt. Viel Glück, <Name>.", progress = nil, completion = "Eine Untersuchung des Pavillons zeigt einige interessante und ungewöhnliche Dinge im Vergleich zu den umstehenden Ruinen auf.\n\nErstens ist der Pavillon eindeutig ein wesentlich jüngeres Bauwerk als die anderen Ruinen. Zweitens sind eine Reihe von Glyphen in seine Seiten eingraviert. Das Muster der Glyphen wiederholt sich, aber sein Ursprung oder seine Bedeutung sind ansonsten unklar. Drittens fühlt sich der Stein, aus dem der Pavillon besteht, warm an.\n\nDas zusammen zählt eindeutig als \"auffällig\" für die Durchsuchung der Ruinen.", rewards = "Ihr bekommt:\n\n"},
[2867] = {title = "Kehrt zur Festung Feathermoon zurück", objective = "Kehrt zu Shandris Feathermoon in der Festung Feathermoon zurück und berichtet von Euren Entdeckungen.", description = "Mit der Entdeckung des seltsamen Pavillons im Herzen der Ruinen von Solarsal ist es an der Zeit, zur Festung Feathermoon zurückzukehren und General Shandris Feathermoon zu berichten, was hier entdeckt wurde.", progress = nil, completion = "Willkommen, &lt;Name&gt;. Euer Bericht über diesen Pavillon ist höchst... Besorgnis erregend. Selbst wenn die Naga dort keinen Angriff geplant hatten, ist ihre fortwährende Gegenwart doch schlecht für unseren Vormarsch nach Feralas. Wie auch immer, hier ist die Entschädigung für Eure Nachforschungen.\n\nEs sieht so aus, als könnte die Festung Feathermoon dringend zusätzliche Hilfe bezüglich der Hasskammnaga gebrauchen. Ich würde Euch diesen Auftrag gern anbieten, wenn Ihr Interesse daran habt. Es gibt viel zu tun.", rewards = "Ihr bekommt:\n\n"},
[2869] = {title = "Gegen die Hasskämme", objective = "Bringt Latronicus Moonspear in der Festung Feathermoon 10 Nagaschuppen der Hasskämme.", description = "Es ist derzeit die beste Handlungsweise, davon auszugehen, dass die Naga, was auch immer sie vorhaben, langfristig versuchen werden, die Insel für sich zu beanspruchen. Wir müssen aktive Schritte unternehmen, um diese Bedrohung auszuschalten, bevor es zu spät ist.\n\nBringt mir 10 Schuppen der Hasskämme in gutem Zustand. Es dürfte offensichtlich sein, wie man an diese herankommt. Ihr werdet Euch an den Naga das erste Mal Eure Sporen verdienen und wir haben dann eine geschwächte Nagapräsenz auf der Sardor-Insel - beides sind Aussichten, die uns zum Vorteil gereichen.", progress = "<Name>, falls Ihr hier seid, um Euch der Aufgabe zu vergewissern, die ich Euch gab, dann ist es gut. Es sind 10 Schuppen der Hasskämme, die ich haben möchte. Falls Ihr jedoch zum Schwatzen hier seid: Ich stehe nicht zur Verfügung für Gehaltlosigkeiten.\n\nWisset dies: Wir Nachtelfen sind keine Kriegstreiber. Unser Volk verschreibt sich dem Erhalt von Frieden und Harmonie. Das heißt aber nicht, dass wir nicht aktiv unsere eigenen Interessen schützen. Das ist meine Pflicht General Feathermoon und der Festung gegenüber!", completion = "Ja, doch, diese Schuppen sind mehr als zufrieden stellend. Tatsächlich denke ich, dass ich sie zu Pratt hinunterschicken werde, damit er einen Blick darauf wirft. Vielleicht kann er etwas Nützliches daraus herstellen.\n\nWas Euch betrifft, ich habe eine weitere Mission, auf die ich Euch schicken möchte. Doch zuerst habt Ihr hier einmal Eure Belohnung für die Schuppen. Dass Ihr weiterhin im Dienste des Generals und der Festung Feathermoon steht, ist ein Segen angesichts so großer Not.", rewards = "Ihr bekommt:\n\n"},
[2870] = {title = "Gegen Lord Shalzaru", objective = "Vernichtet Lord Shalzaru und bringt dann Latronicus Moonspear in der Festung Feathermoon das geheimnisvolle Relikt, das er entdeckt hat.", description = "<Name>, unsere neuesten Spähberichte haben uns einen guten Einblick in die Kommandokette der Naga erlaubt. In ihren Truppen gibt es viele Adlige und die sind es, die den Ton angeben.\n\nUm genau zu sein, wir haben einen der grausameren Adligen als Lord Shalzaru identifiziert. Späher berichten, dass er höchstpersönlich bei einer kürzlich durchgeführten Nagaausgrabung in einer Höhle südlich der eigentlichen Ruinen, jenseits des Wassers, auf der Insel des Schreckens, ein seltsames Relikt gefunden hat.\n\nMacht dem ein Ende, indem Ihr ihm ein Ende macht, und bringt mir dieses Relikt, damit wir es untersuchen können.", progress = "Lord Shalzaru zu verlieren, das würde ihre Pläne sicherlich für Wochen, wenn nicht gar Monate zurückwerfen. Außerdem ist das Relikt, das er gefunden hat, von großem Interesse für uns.\n\nHabt Ihr die Mission ausgeführt, die ich Euch gab, <Name>?", completion = "Gut gespielt, &lt;Name&gt;! Lord Shalzarus Untergang wird die Naga für eine ganze Weile, wenn nicht sogar für immer in Verwirrung stürzen. Die Bedrohung, die sie darstellen, ist nun besser unter unserer Kontrolle als je zuvor und wir haben Euch dafür zu danken.\n\nHier habt Ihr weiteres Kopfgeld aus der Schatzkammer der Festung - Ihr habt Euch jedes Kupferstück davon verdient. Ihr und die Eurigen seid jederzeit in der Festung Feathermoon willkommen, mein Freund.\n\nBevor Ihr abreist, hätte ich da noch eine Kleinigkeit, &lt;Name&gt;... wenn Ihr vielleicht...", rewards = "Ihr bekommt:\n\n"},
[2871] = {title = "Überbringung des Relikts", objective = "Bringt das geheimnisvolle Relikt zu Vestia Moonspear in der Festung Feathermoon.", description = "Wenn Ihr so nett wärt, das Relikt zu meiner Frau Vestia zu bringen, wüsste ich das zu schätzen. Sie ist nicht nur eine gute Priesterin für unsere Gemeinde, sondern auch eine der versiertesten Gelehrten, die es gibt. Ich könnte wahrscheinlich nicht einmal dann herausfinden, wo an diesem Ding oben oder unten ist, wenn mein Leben davon abhinge. Meine Frau wiederum ... Also wenn irgendwer herausfinden kann, was das ist, dann sie ... Und wir müssen es wissen!\n\nSie befindet sich gleich um die Ecke, ohne Zweifel am Studieren. Danke, <Name>.", progress = "Ja, kann ich Euch helfen?\n\nMoment, Ihr seid doch der <Klasse>, der General Feathermoon und Latro mit der Bedrohung durch die Naga geholfen hat, nicht? Ich bin Vestia, Latros - ähm, natürlich Latronicus’ Frau. Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nDoch entschuldigt, Ihr seid sicher geschäftlich hier. Habt Ihr etwas für mich - von ihm vielleicht?", completion = "Interessant... das ist aus den Ruinen von Solarsal, sagt Ihr? Tja, Latro hat Recht, das muss ich mir ansehen. Auf den ersten Blick sieht es nicht so aus, als stamme es aus den Ruinen. Andererseits ist es auch keine Nagamachart... nicht etwas so Fremdartiges wie dies.\n\nEs wird eine Weile dauern, diesen Gegenstand zu erforschen. Wenn meine Nachforschungen abgeschlossen sind, werde ich vielleicht von Euren Talenten Gebrauch machen, solltet Ihr Euch in der Nähe befinden.\n\nHier, nehmt einen der überzähligen Gegenstände, die wir hier haben; ich hoffe, Ihr werdet ihn nutzen können!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSonnenaufgangsreiter-BrustharnischSchildwachenschutz\n\nIhr bekommt außerdem:\n\n"},
[2872] = {title = "Stoleys Schuld", objective = "Sprecht mit Stoley in Steamwheedle.", description = "Mein alter Kumpel Stoley schuldet mir eine ganz bestimmte Flasche Rum. Er schmeißt die Bar in Steamwheedle in Tanaris, Kalimdor, und er versprach mir, dass der Rum dort stärker ist als alles, was man in Booty Bay finden kann. Er ist so davon überzeugt, dass er sagt, wenn ich diesen Rum probiere und ihm nicht zustimme, würde er das Geld, das er mir schuldet, verdoppeln!\n\nNun, ich glaube, er ist nicht mehr so zuversichtlich wie damals, als wir zuletzt miteinander geredet haben, und hat jetzt wohl Angst, mir diesen Rum zu geben. Ich lasse eine Wette aber nicht auf sich beruhen, also wie wäre es, wenn Ihr für mich mit ihm redet?", progress = nil, completion = "Ach, Ihr habt also mit MacKinley gesprochen, ja?\n\nEs ist nicht so, wie er denkt! Ich habe keine Angst, ihm etwas Steamwheedle-Bilge-Rum zu geben...\n\nIch habe nur keinen Rum, den ich ihm geben könnte!", rewards = "Ihr bekommt:\n\n"},
[2873] = {title = "Stoleys Lieferung", objective = "Bringt Stoleys Lieferung zu Stoley nach Steamwheedle.", description = "Ich schulde \"Seewolf” MacKinley in Booty Bay etwas Rum, um eine Wette zu begleichen, aber mir ist der Rum ausgegangen! Kapitän Cuergo hat meine letzte Lieferung gestohlen und lagert sie in dieser ummauerten Piratenstadt im Süden.\n\nWenn Ihr meine Rumlieferung finden und zurückbringen könnt, dann kann ich MacKinley beweisen, dass Kalimdors Drinks die aus Booty Bay um Längen schlagen.", progress = "Habt Ihr meine Rumlieferung gefunden, <Name>?", completion = "Spitze, danke für die Lieferung! Jetzt können MacKinley und ich endlich unsere Wette abschließen.", rewards = "Ihr bekommt:\n\n"},
[2874] = {title = "Lieferung für MacKinley", objective = "Bringt Stoleys Flasche zu \"Seewolf” MacKinley in Booty Bay.", description = "Danke nochmals für Eure Hilfe, <Name>. Hier habt Ihr eine Flasche Steamwheedle-Bilge-Rum. Bringt sie zu MacKinley und er wird endlich seine verrückten Ansichten über Drinks aus Booty Bay über Bord werfen können.", progress = "Hat Stoley meinen Rum ausgespuckt?", completion = "Hm, dann lasst uns mal probieren...\n\nIch kann es nicht glauben! Dieses Zeug ist... schrecklich! Großartig!\n\nNun, ich schätze Stoley kann das Geld behalten, das er mir schuldet. Er hat nicht übertrieben, als er vom Steamwheedle-Bilge-Rum erzählte. Dieses Zeug ist zähflüssig wie Sirup und brennt wie Lava!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchwadroneursschärpeSchienbeintreter-Stiefel\n\nIhr bekommt außerdem:\n\n"},
[2875] = {title = "GESUCHT: Andre Feuerbart", objective = "Bringt Sicherheitschef Bilgewhizzle in Steamwheedle Andres Kopf.", description = "Der niederträchtige Pirat Andre Feuerbart wird aufgrund seiner gegen Steamwheedle und Gadgetzan gerichteten Verbrechen gesucht.\n\nDurch Erlass der Ratsregierung ist hiermit jeder, der dies liest, zu tödlicher Gewaltanwendung bei der Festnahme von Andre und seinen Spießgesellen autorisiert.\n\nDes Weiteren gilt durch zusätzlichen Erlass, dass, sollte Andre verstorben oder anderweitig während seiner Anhörung unpässlich sein, sein Kopf als Ersatz gilt und die Aushändigung dieses Kopfes an Sicherheitschef Bilgewhizzle als vertragsbindend angesehen wird.", progress = "Ihr seht etwas benommen aus. Habt Ihr unsere Rechtsdokumente gelesen?", completion = "Ah, Andres Kopf. Sieht so aus, als käme er letztendlich doch noch rechtzeitig zu seiner Verhandlung!\n\nIch weiß das zu schätzen, &lt;Name&gt;. Wenn Ihr jetzt noch hier unterschreibt, kann ich Euch Eure Bezahlung für die geleisteten Dienste überreichen.\n\nMacht Euch wegen dem Kleingedruckten keinen Kopf. Es ist harmlos und ... ich glaube nicht, dass es eine genügend starke Lupe gibt, mit der man es überhaupt entziffern könnte.", rewards = "Ihr bekommt:\n\n"},
[2876] = {title = "Schiffzeitpläne", objective = "Berichtet den Behörden in Steamwheedle von den Schiffzeitplänen.", description = "Auf dieser Schriftrolle sind die Zeitpläne für Lieferungen zwischen Steamwheedle und Booty Bay verzeichnet. Sowohl vergangene als auch zukünftige Lieferungen sind aufgeführt sowie Schiffsnamen. Große rote Kreuze befinden sich neben einigen der Schiffsreisen und Anmerkungen wie \"Große Beute\" oder \"Harter Kampf\" neben anderen.\n\nJemand in Steamwheedle wird dieses Dokument sicher sehen wollen.", progress = "Ihr seht atemlos aus. Habt Ihr mir etwas mitzuteilen?", completion = "Oh, das sieht nach einer Liste aller ankommenden und ablegenden Schiffe aus, komplett mit den richtigen Terminen und allem! Wenn der Kapitän eines Piratenschiffs das in die Finger bekäme, hätte er seine wahre Freude daran!\n\nIhr sagt, Ihr habt dies von einem Piraten? Hmmm, das sind beunruhigende Neuigkeiten ...\n\nDanke, &lt;Name&gt;. Ich bin froh, dass Ihr es ihm abgenommen habt, und ich bin ebenso froh, dass dieser Pirat ins Gras gebissen hat!", rewards = "Ihr bekommt:\n\n"},
[2877] = {title = "Skulk Rock-Aufräumen", objective = "Tötet 10 grüne Schlämme sowie 10 jadegrüne Brühschlammer und meldet Euch dann wieder bei Fraggar Thundermantle in Aerie Peak.", description = "Wir Wildhammers haben die Vergangenheit besser in Erinnerung als unsere Brüder in Ironforge. Wenn Ihr Euch hier beliebt machen wollt, dann müsst Ihr Euch schon Eure Hände für uns schmutzig machen!\n\nDie Horde hat ihre Stellungen im Hinterland bei Skulk Rock aufgegeben. Jetzt wimmelt es dort von üblen Schlämmen und Brühschlammern. Wir haben Pläne für dieses Gebiet, aber zuerst muss uns eine Aufräummannschaft dort eine Bresche hineinschlagen.\n\nUnd hier kommt Ihr ins Spiel, Sonnenschein! Geht da runter und erledigt 10 grüne Schlämme und 10 jadegrüne Brühschlammer und meldet Euch dann wieder bei mir. Zieht los!", progress = nil, completion = "Ja, schau mal einer an, Ihr habt den Wildhammers geholfen! Ihr seid ein &lt;Klasse&gt; der Tat... und Taten respektieren wir hierzulande.\n\nEure kleine Aufräumaktion ist viel wichtiger, als Ihr vielleicht glaubt. Dank der Leute, die die Brühschlammer und Schlämme reduzieren, können wir unser Einflussgebiet unverzüglich ausdehnen. Hier - nehmt noch eine Kleinigkeit. Und natürlich habt Ihr Euch auf dem Aerie-Gipfel Freunde gemacht.", rewards = "Ihr bekommt:\n\n"},
[2878] = {title = "Verderbte Liedblume", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[2879] = {title = "Der Stock von Equinex", objective = "Aktiviert Troyas Stock und findet den Equinex-Monolithen.", description = "Es sieht so aus, als könnte dieser Stock der Stock von Equinex sein. Der Stock von Equinex ist in Wirklichkeit ein Schlüssel. Mit ihm kann man den Equinex-Monolithen öffnen, der immer noch in den nördlichen Ruinen von Rabenwind steht.\n\nFindet die vier Feuer, die noch immer in den Ruinen brennen: Samha, Imbel, Byltan und Lahassa. Beschafft Euch deren Essenz. Und dann benutzt diese Essenz, während Ihr vor dem Equinex-Monolithen steht, um den Stock zu aktivieren. Wenn dies wirklich der Stock von Equinex ist, dann könnt Ihr den Monolithen öffnen und ein hochheiliges Artefakt daraus bergen.", progress = "Der Equinex-Monolith steht stumm inmitten der Ruinen. Was mag er enthalten?", completion = "Es ist fast unmöglich, den aktivierten Stock festzuhalten. Seine Macht durchfährt Euren Körper.\n\nIhr greift nach der kalten Oberfläche des Equinex-Monolithen...\n\nEine kleine Tür öffnet sich. Ihr könnt hineingreifen und das Artefakt darin an Euch nehmen.\n\nLichtstrahlen erhellen das Gebiet um den Equinex-Monolithen.", rewards = "Ihr bekommt:\n\nEin funkelnder Stein"},
[2880] = {title = "Kopfgeld für Trollhalsketten", objective = "Bringt Fraggar Thundermantle in Aerie Peak 5 Troll-Stammeshalsketten.", description = "Seid Euch darüber im Klaren, <Volk> - wir sind NICHT Teil der Allianz! Die Wildhammer sind unabhängig. Um den Wert einer Person zu beweisen, verlassen sie sich lieber auf Taten und hören nicht auf das Geschwätz derer, die mit ihrem Gequassel versuchen, ihre Untätigkeit zu überspielen.\n\nWenn Ihr hier Freunde sucht, beweist uns erst Euren Wert! Die üblen Trolle, die die Hänge des Hinterlands überrennen, tragen manchmal Stammeshalsketten. Bringt mir 5 davon und wir werden das als einen Schritt in die richtige Richtung für Euch verbuchen.", progress = "Ich will 5 von den Stammeshalsketten, die die Trolle tragen. Wenn Ihr es noch deutlicher erklärt haben wollt: Einen zu töten gibt Euch eine gute Chance, eine davon zu erhalten.\n\nBeweist den Wildhammers Euren Wert!", completion = "Und das ist genau das, wovon ich rede! Seht Ihr, diese Halsketten beweisen, dass Ihr bereit seid, Euch Eure Hände schmutzig zu machen. Wir Wildhammers schätzen dies bei den Leuten, mit denen wir uns abgeben.\n\nWenn Ihr so weitermacht, werdet Ihr bald einen guten Stand bei uns haben.", rewards = "Ihr bekommt:\n\n"},
[2881] = {title = "Kopfgeld für Trollhalsketten", objective = "Ihr habt das zwar bereits erledigt, aber wir nehmen weiterhin alle Troll-Stammeshalsketten an, die Ihr findet und eintauschen wollt. Indem Ihr sie bei mir eintauscht, verbessert Ihr weiter Eure Stellung unter den Wildhammers. Wenn Ihr für uns kämpft, dann kämpfen wir auch für Euch!\n\nIch benötige 5 Troll-Stammeshalsketten, damit ich es gelten lassen kann, <Name>.", description = nil, progress = "Ihr habt das zwar bereits erledigt, aber wir nehmen weiterhin alle Troll-Stammeshalsketten an, die Ihr findet und eintauschen wollt. Indem Ihr sie bei mir eintauscht, verbessert Ihr weiter Eure Stellung unter den Wildhammers. Wenn Ihr für uns kämpft, dann kämpfen wir auch für Euch!\n\nIch benötige 5 Troll-Stammeshalsketten, damit ich es gelten lassen kann, <Name>.", completion = "Ein weiterer Satz Halsketten bedeutet, dass es weniger Trolle im Hinterland gibt, derentwegen man sich Sorgen machen muss! Ihr habt es wieder geschafft, &lt;Name&gt;. Leistet weiter so gute Arbeit!", rewards = nil},
[2882] = {title = "Cuergos Gold", objective = "Findet Cuergos Gold!", description = "Diese Karte zeigt ein Stück Strand an einer Südküste. Unter der Karte stehen elegant geschriebene Worte:\n\n\nSüdlich von Wheedle\nDürft Ihr drauf hoffen\nFindet Flagge, Mast und Knochen\nGrabt dort, wenn Ihr tapfer sein wollt\nGrabt und erbt Cuergos Gold!\nEinen Schlüssel werdet Ihr brauchen, einen Schlüssel werdet Ihr sehen\nDie Mannen dort woll'n als Bezahlung Euer Blut Euch nehm'n.", progress = "Diese Truhe ist verschlossen.", completion = "Captain Cuergos versteckter Schatz erwartet Euch!", rewards = "Ihr bekommt:\n\nCuergos versteckter Schatz"},
[2902] = {title = "Waldpfotennachforschung", objective = "Findet die Gnoll-Schlachtpläne irgendwo in den Gnoll-Lagern südlich vom Camp Mojache.", description = "Gnolle sind zwar nicht die Hellsten, aber sie werden bestimmt die Strategie ihrer jüngsten Aktivitäten irgendwo dokumentiert haben. Wenn wir diese Pläne finden würden, hätten wir eine bessere Vorstellung davon, was sie so aufbringt.\n\nIch möchte, dass Ihr zu den Waldpfoten zurückgeht und nach allem sucht, was Ähnlichkeit mit ihren Schlachtplänen haben könnte. Irgendwas muss es geben, ihre Angriffe waren einfach zu gut koordiniert. Findet diese Schlachtpläne und kommt zu mir zurück, sobald Ihr sie habt.", progress = nil, completion = "Eine Untersuchung der Karte zeigt, dass es sich um die Schlachtpläne handelt, die Hadoken Swiftstrider haben will. Zahlreiche Pfeile, die vielleicht Truppenbewegungen darstellen, befinden sich auf der Karte, allerdings scheinen die meisten nach Süden zu deuten, nicht nach Norden, wo das Camp Mojache liegt.\n\nEin anderer Teil der Karte enthält ein Bild von etwas, das man für irgendein großes Insekt halten könnte. Darunter befindet sich eine Art Strichliste. So, wie die Gnolle aussehen, stellt diese vielleicht ihre Verluste gegen das unbekannte Ungeziefer dar...", rewards = "Ihr bekommt:\n\n"},
[2903] = {title = "Die Schlachtpläne", objective = "Bringt die Schlachtpläne der Waldpfoten zu Hadoken Swiftstrider ins Camp Mojache.", description = "Jetzt, nachdem die Schlachtpläne der Gnolle entdeckt wurden, bleibt nur noch, die Pläne zu Hadoken Swiftstrider ins Camp Mojache zurückzubringen. Vielleicht kann er oder irgendjemand dort besser darauf schließen, was die Gnolle vorhaben.", progress = "Willkommen zurück, <Name>. Habt Ihr ein paar greifbare Hinweise auf die Pläne der Gnolle gefunden?", completion = "Ah, das ist genau, was wir gebraucht haben. Auch wenn ich nicht sehr geschickt darin bin, das ganze Gekritzel auf dieser Karte zu entziffern, so habe ich doch in meinem Leben genug Schlachtpläne gesehen, um zu verstehen, was mit den Gnollen passiert. Es sieht so aus, als würden sie derzeit einen Zwei-Fronten-Krieg führen. Einen mit uns... Aber wie es scheint, konzentrieren sie außerdem einen Großteil ihrer Energie auf einen Feind im Süden.\n\nHier läuft mehr, als auf den ersten Blick zu erkennen ist. Wir sollten möglichst bald herausfinden, wer dieser andere Feind, dem sie gegenüberstehen, wirklich ist.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErdschnallenbarriereRushridge-Stiefel\n\nIhr bekommt außerdem:\n\n"},
[2904] = {title = "Eine schöne Bescherung", objective = "Begleitet Kernobee zur Uhrwerkgasse und meldet Euch dann wieder bei Scooty in Booty Bay.", description = "<Kernobee stöhn.t> Was... Was ist passiert?\n\nDas Letzte, an das ich mich erinnere, ist, wie ich von einer Gruppe Dunkeleisenzwerge gefangen, halb tot geprügelt und dann hier zu diesen schmutzigen Troggs geworfen wurde.\n\nHolt mich hier raus, <Name>!\n\nSo ist der Plan: Bringt mich zum Ausgang; Wenn wir es lebend hier herausschaffen, geht nach Booty Bay und lasst Scooty wissen, dass ich nach Ratchet gegangen bin, um Tinkerwiz zu warnen, dass die Dunkeleisenzwerge in die Herstellung dieser Supermaschine verwickelt sind.\n\nGehen wir!", progress = nil, completion = "Ich schätze, Ihr solltet dafür belohnt werden, Kernobee in einem Stück zurückgebracht zu haben, &lt;Name&gt;. Wenn Ihr nach Gnomeregan zurückkehrt, könnten diese hier Euch den entscheidenden Vorteil liefern, den Ihr benötigt, um diesen nichtsnutzigen Verräter Robogenieur Thermaplugg zu besiegen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFeuergeschmiedete ArmschienenFeenflügel-Mantel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[2922] = {title = "Rettet Techbots Hirn!", objective = "Bringt Techbots Speicherkern zu Tüftlermeister Overspark nach Ironforge.", description = "Als unsere geliebte Stadt Gnomeregan fiel, muss ein verirrter Funke mein armes Geschöpf, Techbot, völlig durcheinander gebracht haben. Früher half er mir und meinen Kollegen mit seinen zahllosen Dingsdas und seiner endlosen Speicherkapazität, aber sein positronisches Gehirn wurde polarisiert. Es ist jetzt negatronisch... und Techbots Verhalten wurde umgekehrt. Er wütet jetzt in ganz Gnomeregan!\n\nDoch vielleicht kann man ihn noch retten. Wenn Ihr seinen Speicherkern auffinden und zu mir bringen könnt, kann ich die Ursache der Polarisierung möglicherweise finden und meinen armen Techbot reparieren.\n\n", progress = "Habt Ihr Techbot gefunden? Habt Ihr seinen Speicherkern gefunden?", completion = "Oh, das ist wunderbar!! Danke, &lt;Name&gt;! Ich mache mich gleich an die Arbeit!!\n\nArmer, armer Techbot... Mach dir nichts daraus. Wir kriegen dich wieder hin.\n\nHm, wo hab ich diesen Aufsatz für meine Hydrowinden-Ratsche hingelegt...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2923] = {title = "Tüftlermeister Overspark", objective = "Sprecht mit Tüftlermeister Overspark in Ironforge.", description = "Tüftlermeister Overspark ist ob des Schicksals seiner mechanischen Schöpfung, Techbot, ziemlich bestürzt. Ich erinnere mich an Techbot als ein freundliches und hilfsbereites Werkzeug der Gnome, aber Overspark erzählte mir, er hätte eine Fehlfunktion.\n\nWirklich traurig. Aber mit etwas Glück kann er vielleicht repariert werden!\n\nSprecht mit Tüftlermeister Overspark in Tüftlerstadt, Ironforge. Er würde sich über Eure Hilfe freuen.", progress = nil, completion = "Ja, es ist wahr. Techbot ist durchgedreht! Könnt Ihr mir bitte helfen?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2924] = {title = "Grundlegende Artifixe", objective = "Bringt Klockmort Spannerspan in Ironforge 12 grundlegende Artifixe.", description = "Ein beinahe universell einsetzbares mechanisches Bauteil - das grundlegende Artifix - war den Tüftlern und Schmieden von Gnomeregan von großem Nutzen. Doch während der panischen Flucht aus unserer Stadt hat niemand daran gedacht, einige von diesen Geräten mitzunehmen! Und ich brauche eine ganze Menge davon für eine Arbeit, die ich in Kürze in Angriff nehmen werde.\n\nBitte, geht nach Gnomeregan und bringt mir einige grundlegende Artifixe. Ihr werdet sie in den tieferen Bereichen unserer Stadt finden, in \"Künstliche Extrapolatoren\" genannten Behältern.\n\nDanke, <Name>, und bitte beeilt Euch!", progress = "Habt Ihr die grundlegenden Artifixe?", completion = "Ihr habt sie! Jetzt kann ich mit meinen neuen Experimenten beginnen!\n\nIch kann Euch gar nicht genug danken, &lt;Name&gt;! Durch Eure Tapferkeit hat die Gnomen-Forschung einen riesigen Schritt nach vorn gemacht.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2925] = {title = "Klockmorts Grundlagen", objective = "Sprecht mit Klockmort Spannerspan in Ironforge.", description = "Ein Gnomen-Freund, Klockmort Spannerspan, hat mich aus Ironforge kontaktiert. Er teilt mir mit, dass er Hilfe bei einer gefährlichen, aber unverzichtbaren Mission nach Gnomeregan braucht, der einst so großen Gnomen-Stadt, die jetzt verseucht und voller verrückter Gnome und ihrer Gerätschaften ist.\n\nIch muss hier bleiben, aber mir blutet das Herz, wenn ich meinem Freund nicht helfen kann. Wenn Ihr an meiner Stelle gehen könnt, dann stünde ich tief in Eurer Schuld.\n\nIhr könnt Klockmort in Tüftlerstadt in Ironforge finden.", progress = nil, completion = "Allerdings! Ich brauche Hilfe bei einer Mission, die nach Gnomeregan hineinführt. Und Ihr seid genau der &lt;Klasse&gt;, der das tun könnte!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2926] = {title = "Gnogaine", objective = "Sammelt mit der leeren bleiernen Sammelphiole radioaktive Ablagerungen bestrahlter Eindringlinge oder Plünderer. Sobald sie voll ist, bringt Ihr sie zu Ozzie Togglevolt nach Kharanos zurück.", description = "Seit dem Unfall redet Gnoarn nur noch davon, Gnomeregan vom Troggbefall zu befreien und ein Heilmittel für die Erkrankung, die die Stadt verseucht, zu finden, <Name>.\n\nZum Glück sind Razzle und ich gerade dabei, ein solches Heilmittel zu entwickeln... oder vielleicht auch ein Rezept für wirklich starken Rum. Genau wissen wir das aber erst, wenn wir es ausprobiert haben! Logischerweise benötigen wir zum Test unserer Theorie ein paar Dinge, vor allem Ablagerungen von den bestrahlten Troggs in Gnomeregan. Füllt diese Phiole mit dem grünen Leuchten und bringt sie zurück!", progress = "Seht Ihr denn nicht, dass wir versuchen, ein ganzes Gnomen-Volk zu heilen?! Wir brauchen mehr von dem grünen Leuchten!", completion = "Ausgezeichnete Arbeit! Es ist an der Zeit, die neue Formel zu testen. Wenn sie funktioniert, sollte nicht nur dieser gefangene Lepragnom bald geheilt sein, sondern ich auch wieder ordentlich Haare auf dem Kopf haben. Tretet zurück!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2927] = {title = "Der Tag danach", objective = "Sprecht mit Ozzie Togglevolt in Kharanos.", description = "Ihr glaubt doch wohl nicht, dass ich schon immer so kahlköpfig war, oder? Nein, <werter Herr/holde Dame>! Das Strahlungsleck in Gnomeregan rief diesen tragischen Haarverlust hervor. Vor jenem Tag hatte ich den einzigen Gnomen-Afro in ganz Azeroth.\n\n<Gnoarn schüttelt drohend die Faust.>\n\nVerdammt seien diese verdammten dreckigen Troggs, verdammt seien sie alle!\n\nVielleicht ist es noch nicht zu spät, <Name>. Wir können sie vielleicht immer noch retten - die Stadt, meine ich! Sprecht mit Ozzie Togglevolt in Kharanos. Er und sein Partner Razzle arbeiten an einer Lösung.", progress = nil, completion = "Ich dachte, dass der Verlust dieses außergewöhnlichen Kopfhaares bestimmt sein Ende sein würde, aber er hat überlebt!\n\nIch stand direkt neben ihm, als er von dem Strahlungsblitz getroffen wurde. Die wunderschönen braunen Locken fielen in Klumpen zu Boden! Büschelweise! Alles wurde noch schlimmer, als Gnoarn dann völlig ausgetickt ist! Oh ja, ausgetickt, sag ich! Gnoarn fasste sich ungläubig an seinen kahlen Kopf und in seinen Augen funkelte die reine Rache, &lt;Name&gt;! Und dann ließ er seinen Ärger an den Troggs aus!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2928] = {title = "Gyrobohrmatische Exkavation", objective = "Bringt 24 robomechanische Innereien zu Shoni nach Stormwind.", description = "Es ist schrecklich, <Name>. Wir werden nicht genug Teile haben, um unsere Flotte aus gyrobohrmatischen Exkavationatoren nach Dun Morogh zu bringen.\n\nWir brauchen Ersatzteile, <Name>. Und welch besseren Ort als Gnomeregan könnte es geben, um Ersatzteile für unsere Fahrzeuge zu besorgen? Es heißt, dass Bots und Mechs dort herumlaufen wie Vieh auf der Weide.\n\nIhr müsst für mich nach Gnomeregan gehen und diese Roboter auseinander nehmen. Bringt mir ihre Innereien. Zwei Dutzend sollten ausreichen.", progress = "Wenn dies ein Wettrennen wäre, hättet Ihr bereits verloren.", completion = "Das dürfte reichen, &lt;Name&gt;. Ein gyrobohrmatischer Exkavationator ist geflickt; fehlen noch 398.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nShonis Entwaffnungs-WerkzeugFäustlinge der Entschlossenheit\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[2929] = {title = "Der große Verrat", objective = "Reist nach Gnomeregan und tötet Robogenieur Thermaplugg. Kehrt zu Hochtüftler Mekkatorque zurück, wenn der Auftrag ausgeführt ist.", description = "Ich habe Thermaplugg vertraut, <Volk>. Ich hätte nie vermutet, dass er mich und das ganze Gnomen-Volk verraten würde. Und wofür? Macht? Reichtum? Alles Dinge, die er mit der Zeit auch so erlangt hätte. Jetzt sind wir aus unserer Heimat verdrängt worden und dieser Wahnsinnige ist dafür verantwortlich. Der König des Nichts ...\n\nWir werden Gnomeregan zurückerobern, <Name>. Wir werden nicht ruhen, bis die Stadt wieder unter unserer Kontrolle steht. Wenn Ihr Euch unserem Kampf anschließen wollt, habe ich eine einfach Bitte an Euch: Tötet den Verräter. Vernichtet Robogenieur Thermaplugg.", progress = nil, completion = "Ich stelle mir gern vor, dass das Letzte, was ihm durch den Kopf ging, bevor er zu Boden sank, Euer Fuß war, &lt;Volk&gt;. Jetzt, da Thermaplugg tot ist, sind wir der Verwirklichung unseres Plans, Gnomeregan wiederzuerobern, einen Schritt näher gekommen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nCivinad-RobenStolperläufer-LatzhoseZweifach verstärkte Gamaschen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[2930] = {title = "Datenrettung", objective = "Bringt Mechanikermeister Castpipe in Ironforge eine Prismalochkarte.", description = "Als wir aus Gnomeregan flohen, haben wir so viele Daten zurückgelassen! Lebenswichtige Informationen!\n\nIch brauche die Daten auf einer Prismalochkarte aus einem Matrix-Prägographen 3005-D, einem Hochsicherheitsterminal, tief in Gnomeregan. Ihr müsst auf dieses Terminal zugreifen, aber dafür braucht Ihr die Zugangsberechtigung ... und um die zu erhalten, müsst Ihr erst Zugang zu den Terminals niedrigerer Sicherheitsstufen - Modelle A, B und C - haben. DAFÜR wiederum braucht Ihr Sicherheitslochkarten, angefangen mit einer weißen ... Und wir haben alle Lochkarten in der Stadt vergessen.\n\nDas ist eine Katastrophe! Könnt Ihr helfen?", progress = "Habt Ihr die Prismalochkarte?", completion = "Ihr habt es geschafft! Ihr habt die Prismalochkarte gefunden und die verlorenen Daten wiederbeschafft! Lebenswichtige, kritische, unvorstellbar wertvolle Daten, ohne die wir keine Minute länger hätten leben können!\n\nDer Dienst, den Ihr den Gnomen erwiesen habt, wird lange in Erinnerung bleiben, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nSchlosser-CapeMechanikerrohrhammer"},
[2931] = {title = "Castpipes Auftrag", objective = "Sprecht mit Mechanikermeister Castpipe in Ironforge.", description = "Mechanikermeister Castpipe in Ironforge sucht Abenteurer! Er organisiert Teams, um Gnomeregan auf einer Datensicherungsmission höchster Sicherheitsstufe und Wichtigkeit zu betreten.\n\nCastpipe mag zwar nicht wie ich ein Mitglied der Erleuchteten Vereinigung für Arkanologie, Alchimie und Ingenieurwissenschaften sein, aber er ist dennoch ein kluger Gnom, und wenn er es für wichtig hält, dann besteht nach meinen Berechnungen eine vierundachtzigprozentige Wahrscheinlichkeit, dass es wirklich wichtig ist.\n\nDas ist eine gute Chance!", progress = nil, completion = "Ich organisiere Datensicherungsmissionen nach Gnomeregan. Wenn Ihr deswegen hier seid, dann hört genau zu!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2932] = {title = "Grausige Botschaft", objective = "Sammelt Schädel der Witherbark und hängt sie an Nimboyas Pike. Platziert Nimboyas behängte Pike in einem der Witherbarkdörfer im Hinterland und kehrt dann zu Nimboya ins Schlingendorntal zurück.", description = "Die Trolle der Witherbark waren einst Verbündete der Horde, aber sie haben Thrall hintergangen... und das muss bestraft werden!\n\nHier, nehmt meine Pike und geht weit gen Norden ins Hinterland. Ihr werdet es nordöstlich von Tarrens Mühle vorfinden, einem Dorf, das von unseren Verbündeten, den Verlassenen, kontrolliert wird.\n\nWenn Ihr ins Hinterland kommt, jagt Trolle der Witherbark. Sammelt ihre Schädel und rammt meine Pike in einem ihrer kleineren Dörfer in den Boden: in Hiri'watha oder Zun'watha.\n\nZeigt ihnen, dass ihre heimtückischen Taten Konsequenzen nach sich ziehen!", progress = nil, completion = "Ich habe von Eurer Tat gehört. Eine grausige Tat, aber eine voller Ehre. Lasst uns hoffen, dass die Witherbarks Eure Nachricht verstehen.", rewards = "Ihr bekommt:\n\n"},
[2933] = {title = "Giftflaschen", objective = "Bringt eine Giftflasche zu einem Apotheker nach Tarrens Mühle.", description = "Diese Flaschen enthalten ein übles grünes Gift.\n\nWenn man die Anzahl der Flaschen in diesem Dorf bedenkt, müssen die Witherbarks ihn für sehr wichtig halten. Vielleicht will einer der Apotheker im nahe gelegenen Tarrens Mühle eine Probe davon.", progress = "Hallo, edler <Klasse>. Der Tag war lang und nicht ein einziges Experiment ist geglückt... Ich hoffe, Ihr bringt mir gute Neuigkeiten.", completion = "Ah, und was ist das? Es sieht aus wie ein Gift... von irgendeiner Spinnenkreatur, schätze ich. Und wo habt Ihr das her?", rewards = "Ihr bekommt:\n\n"},
[2934] = {title = "Unbeschädigter Giftbeutel", objective = "Bringt Apotheker Lydon in Tarrens Mühle einen unbeschädigten Giftbeutel.", description = "Ich benötige eine frische Probe von dem Gift, den Ihr mir gebracht habt. Die Spinnen, von denen er gesammelt wurde, dürften im Hinterland leben. Jagt sie, bis Ihr einen unbeschädigten Giftbeutel findet, und bringt ihn mir. Ihr findet viele Spinnen nahe der Trollstadt Shadra'Alor.\n\nUnd trödelt nicht rum, <Name>, denn der Giftbeutel muss frisch sein, wenn Ihr ihn abliefert.", progress = "Habt Ihr den unbeschädigten Giftbeutel, <Name>? Ich sehne mich danach, Experimente mit diesem frischen Gift anzustellen, und habe eine Ansammlung kleiner, unglaublich süßer Tierchen bestellt, um ihn an ihnen zu testen.", completion = "Oh, prächtig! Das Gift ist ziemlich frisch und sicher extrem tödlich. Danke!", rewards = "Ihr bekommt:\n\n"},
[2935] = {title = "Konsultiert Meister Gadrin", objective = "Sprecht mit Meister Gadrin in Sen'jin.", description = "Das Gift der Brutwachen war nicht so potent wie das Gift, den Ihr mir ursprünglich gebracht habt. Er muss von einer anderen Spinne gewesen sein.\n\nIch will eine frische Probe dieses Gifts. Um herauszufinden, woher er kam, müsst Ihr Euch mit einem Troll unterhalten, der die Witherbark gut kennt - Meister Gadrin im Dorf Sen’jin. Reist nach Durotar und sprecht mit Gadrin. Wenn wir Glück haben, weiß er, woher die Witherbarks ihr Gift bekommen.", progress = nil, completion = "Ah, Ihr wollt also frisches Gift von den Spinnen der Witherbarks, ja? Nun, setzt Euch... Es wird Euch nicht gefallen, was ich Euch sagen muss.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2936] = {title = "Der Spinnengott", objective = "Lest von der Schrifttafel des Theka, um den Namen des Spinnengottes der Witherbark zu erfahren, und kehrt dann zu Meister Gadrin zurück.", description = "Die Witherbarks verehren einen Spinnengott und von ihm bekommen sie ihr wirkungsvolles Gift. Wenn Ihr also ihr Gift wollt, müsst Ihr ihren Gott beschwören!\n\nUm das zu tun, müsst Ihr seinen wahren Namen wissen und dieser Name steht auf einer Tafel, die in Tanaris, in der Trollstadt von Zul’Farrak, in einer Gruft vergraben ist, die von Theka dem Märtyrer bewacht wird.\n\nBesiegt Theka und findet und lest diese Tafel, um den Namen des Spinnengottes herauszufinden. Wenn Ihr ihn kennt, kehrt zu mir zurück.", progress = nil, completion = "Ah, Elortha no Shadra... Flüstert diesen Namen nur, denn seine Aussprache hat in der Welt der Geister großes Gewicht.\n\nIch werde ihn auf ein Pergament schreiben und für Euch einen Beschwörungszauber herstellen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2937] = {title = "Die Beschwörung von Shadra", objective = "Besiegt Shadra am Altar von Shadra’Alor und bringt sein Gift zu Apotheker Lydon nach Tarrens Mühle.", description = "Nehmt dieses Pergament und verlest es am Altar von Shadra'Alor tief in der Welt der Witherbark im Hinterland. Dies wird Shadra, den Spinnengott, beschwören.", progress = "Habt Ihr das Gift bekommen?", completion = "Prima, Ihr habt ihn!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2938] = {title = "Gift für Undercity", objective = "Bringt Faranells Päckchen zu Apothekermeister Faranell nach Undercity.", description = "Das Gift, das Ihr vom Spinnengott der Witherbarks beschafft habt, ist ein großer Fund! Ich konnte mit nur einem Tropfen von dem Zeug fast zwei Dutzend Hasen töten! Na gut, einige dieser Hasen waren sehr jung und klein genug, um auf eine Handfläche zu passen, und daher war ihre Widerstandskraft gegen Toxine bestimmt niedrig, aber man kann nicht leugnen, dass dieses Gift mächtig ist!\n\nIch würde gern eine Probe zu meinem Vorgesetzten, Apotheker Faranell, in das Apothekarium von Undercity entsenden. Ich bin sicher, er würde es gern selbst testen.", progress = "Man hat mich von Eurem Kommen unterrichtet, <Name>. Ihr habt ein Päckchen für mich?", completion = "Ah, sehr gut. Lydon erwähnte, dass das Gift in diesem Päckchen der potenteste ist, der ihm bisher untergekommen ist, und dass er gerade fieberhaft an neuen Anwendungen dafür arbeitet.\n\nWenn wir Glück haben, finden wir eine Menge davon.\n\nDanke, &lt;Name&gt;. Eure Dienste für die königliche Apothekervereinigung können nicht geleugnet werden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKönigliche HochmaltrachtEhrenwache-BrustharnischAegis des Kampfes\n\nIhr bekommt außerdem:\n\n"},
[2939] = {title = "Auf der Suche nach Wissen", objective = "Sprecht mit Daryn Lightwind im Dorf Rut'theran.", description = "Auch wenn die Ruinen von Feralas ziemlich gefährlich sein können, so erzählen sie doch viel darüber, was hier passiert ist...\n\nAls ich vor einigen Tagen das Geröll südlich von hier durchstöberte, fand ich etwas, das wie ein gewöhnlicher Stock aussah. Allerdings werde ich das Gefühl nicht los, dass es mehr damit auf sich hat. Angelas und ich haben über unseren Büchern hier gebrütet, aber wir konnten nichts darüber herausfinden.\n\nIch habe aber eine Kollegin in Darnassus, die uns vielleicht erzählen kann, was das ist, <Name>. Warum sprecht Ihr nicht mit ihr und seht, ob sie uns helfen kann?", progress = nil, completion = "Oh, Troyas Moonbreeze hat Euch also geschickt?\n\n&lt;gemurmelt&gt;... ständig geht er mir mit seinen wilden Hoffnungen auf die Nerven, dass er etwas Wichtiges gefunden hat...\n\nSeht, &lt;Name&gt;, ich sage es Euch ganz unverblümt. Troyas glaubt jedes Mal, dass er in diesen Ruinen etwas Wichtiges gefunden hat. Die Wahrheit ist aber, dass alles, was wirklich wertvoll war, wahrscheinlich vor langer Zeit schon von den Ogern oder Harpyien eingesackt wurde, die jetzt dort leben.\n\nIhr könnt Euch gern umsehen, aber ich weiß nicht, ob Ihr hier irgendwelche Bücher finden werdet, die Euch weiterhelfen.", rewards = "Ihr bekommt:\n\n"},
[2940] = {title = "Feralas: Ein historischer Abriss", objective = "Fragt Daryn Lightwind, ob Ihr Euch ihr Buch ausleihen dürft.", description = "Es sieht so aus, als sei dieses Buch seit langer Zeit von niemandem mehr geöffnet worden. Sein Einband ist ziemlich abgenutzt und seine Seiten sind vergilbt, aber nach einer kurzen Untersuchung stellt Ihr fest, dass es genau das sein könnte, was Troyas sucht.\n\nIhr steckt es ein, aber dann fällt Euch ein, dass Ihr vielleicht vorher fragen solltet, bevor Ihr es ausleiht.", progress = nil, completion = "Ihr wollt Euch also \"Feralas: Ein historischer Abriss\" ausleihen?\n\nLasst mich mal überlegen...\n\nIch werde Euch erlauben, das Buch auszuleihen, &lt;Name&gt;, aber nur, wenn Ihr zuerst etwas für mich erledigt.", rewards = "Ihr bekommt:\n\n"},
[2941] = {title = "Der Borger", objective = "Bringt den Brief zu Curgle Cranklehop nach Tanaris.", description = "Ich habe in meinem Leben viele Dinge studiert und meine jüngste Leidenschaft sind die Schnappkiefer, die den Strand im Hinterland bevölkern. Es gibt einen bestimmten, den ich gern sehen würde, einen Riesenschnappkiefer namens Gammerita. Ich würde gern selbst hingehen, aber meine Forschungen halten mich hier. Ein Bild von Gammerita wäre wohl die nächstbessere Lösung.\n\nBringt diesen Brief zu Curgle Cranklehop nach Tanaris. Sie hat etwas für mich erfunden, das Bilder einfangen kann. Ich glaube, sie nannte es \"Schnappschuss\" ...", progress = "Ein Brief - für mich?", completion = "Seid Ihr auch einer von Daryns Praktikanten? Sie ist eine ziemlich versierte Historikerin, &lt;Name&gt;. Ihr solltet dankbar sein, unter ihrer Leitung zu studieren.\n\nJetzt lasst mich mal den Superschnapper FX holen. Ihr werdet ihn lieben!", rewards = "Ihr bekommt:\n\n"},
[2942] = {title = "Der Morgenstein", objective = "Bringt den funkelnden Stein und den Stock von Equinex zu Troyas Moonbreeze in die Festung Feathermoon.", description = "In dem Moment, in dem das Artefakt vom Monolithen getrennt wird, fühlt Ihr, wie die Energie im Stock von Equinex sich zu verflüchtigen beginnt.", progress = "Ich bin froh, dass Ihr zurück seid, <Name>. Ich brenne darauf zu hören, was Ihr herausgefunden habt.", completion = "Ich habe gelesen, seit Ihr gegangen seid, &lt;Name&gt;. Dieser Stein, den Ihr gefunden habt, wird Morgenstein genannt. Wenn ich auch noch nicht ganz sicher ob seines Zweckes bin, so könnt Ihr doch sicher sein, dass es etwas von großer Wichtigkeit sein muss, so wie er im Equinex-Monolithen versteckt wurde.\n\nIch werde meine Studien fortsetzen und ich hoffe, dass ich in Zukunft auf Euch zählen kann, &lt;Name&gt;. Danke für all Eure Hilfe.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nCairnstone-SpanSaatzeitreifen\n\nIhr bekommt außerdem:\n\n"},
[2943] = {title = "Rückkehr zu Troyas", objective = "Liefert das Buch bei Troyas Moonbreeze in der Festung Feathermoon ab.", description = "Hier, <Name>. Bitte, passt auf mein Buch auf.\n\nNun aber schnell. Troyas wartet bestimmt schon ganz ungeduldig auf Eure Rückkehr.", progress = "Hallo, <Name>. Seid Ihr in Darnassus gewesen?", completion = "Ihr habt ein Buch mitgebracht. Ausgezeichnet!", rewards = "Ihr bekommt:\n\n"},
[2944] = {title = "Der Superschnapper FX", objective = "Benutzt den Superschnapper FX, um einen Schnappschuss von Gammerita zu machen, und kehrt dann zu Daryn Lightwind nach Rut'theran zurück.", description = "Werft erst mal einen Blick auf meine neue Erfindung, <Name>. Visiert einfach an, wovon Ihr ein Bild haben möchtet, und drückt dann auf den Knopf.\n\nWas war das für eine Kreatur aus dem Hinterland, die Ihr erwähnt habt? Gammerita? Tja, viel Erfolg bei der Suche nach ihr. Ich bin sicher, Daryn wird mit dem Schnappschuss, den Ihr ihr zurückbringt, sehr zufrieden sein.\n\nWie auch immer, hier habt Ihr den Superschnapper. Viel Spaß!", progress = "Ach, Ihr seid also endlich wieder da, <Name>. Und Ihr habt den Apparat dabei, den Curgle für mich gebaut hat... perfekt.", completion = "Gut! Curgles Erfindung hat die Erwartungen erfüllt.\n\nWerdet nicht übermütig, aber wisset, dass ich mit Eurer Arbeit zufrieden bin, &lt;Name&gt;.\n\nWo habe ich jetzt nur dieses Buch gelassen...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2945] = {title = "Schmutzverkrusteter Ring", objective = "Findet einen Weg, den schmutzverkrusteten Ring zu säubern.", description = "Ihr habt bei einer der Leichen der Dunkeleisenzwerge etwas entdeckt, das wie ein Ring aussieht. Es ist jedoch schwer zu sagen, was für ein Ring das ist. Das Ding ist derart mit Dreck und Verkrustungen überzogen, dass man es unmöglich an einen Finger stecken kann. Ihr glaubt, unter den Verkrustungen Edelmetall schimmern und vielleicht sogar einen Edelstein glitzern zu sehen.\n\nWenn Ihr diesen Ring verwenden wollt, müsst Ihr nach etwas suchen, das die Verkrustungen entfernt.", progress = "Der Gnomen-Apparat vor Euch trägt eine Plakette mit der Aufschrift \"Der Funkelmat 5200\". Laut der Anleitung unter der Plakette besteht der Sinn dieser Maschine darin, jedweden Schmutz von Gegenständen abzuschrubben. Um den Vorgang zu starten, legt man den Gegenstand in die Maschine und wirft drei Silbermünzen in den Münzschlitz.\n\nEs scheint, als sei der verkrustete Ring, den Ihr gefunden habt, geradezu perfekt, um diese Maschine auszuprobieren.", completion = "Ihr legt den Ring in den Funkelmat 5200 und werft eine Silbermünze in den Schlitz.\n\nFurchtbares Knirschen und Mahlen dringt aus der Maschine, als sie heftig zu ruckeln beginnt. Man kann nur raten, was mit dem Ring in der Maschine passiert...\n\nDann stoppt die Maschine plötzlich, ihren Stillstand mit einem einfachen \"Ding!\" verkündend. Der Aufnahmebehälter öffnet sich und offenbart eine kleine, hübsch verpackte Schachtel mit einer roten Schleife. Es scheint, als würde der Funkelmat 5200 alles auch gleich noch als Geschenk verpacken!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub"},
[2946] = {title = "Mal sehen, was passiert...", objective = "Bringt die Miniaturplatinscheiben zu den Toren von Uldum in Tanaris und sucht nach Hinweisen auf die Verbindung zwischen beidem.", description = "Wir möchten, dass Ihr die Mininaturscheiben, die Ihr gefunden habt, zu den versiegelten Toren von Uldum bringt. Wir... wir sind uns nicht ganz sicher, was dann passieren wird.\n\nEs klingt ein bisschen riskant, sicher, das geben wir auch zu. Es könnte allerdings auch sein, dass überhaupt nichts passiert. Vielleicht müsst Ihr mit den Scheiben irgendetwas anstellen. Vielleicht öffnen sich die Türen, wenn Ihr die Scheiben bei Euch habt. Versucht alles Mögliche und seid offen für alles, was passieren könnte.\n\nWenn Ihr herausgefunden habt, was die Scheiben bewirken, kehrt nach Ironforge zurück. Es wird einiges zu untersuchen geben, wenn Ihr das erledigt habt!", progress = "Dieser vertraut aussehende Sockel ragt aus dem heißen Sand heraus. Vielleicht gibt es einen Grund für sein Hiersein...", completion = "Als Ihr den Sockel berührt, summen und glühen die Miniaturplatten von Uldaman in Eurem Rucksack. Eine vertrautes Kribbeln überzieht Eure Hände, als das Bild eines weiteren Steinbeobachters vor den Toren von Uldum zum Leben erwacht.\n\n\"Willkommen. Ich bin der Behüter des Eingangs. Die Scheiben, die für den Zugang verwendet wurden, beinhalten nicht die korrekten Zugangsscheiben, die Platten von Uldum. Bitte fügt diese Platten der Scheibenstruktur hinzu und wiederholt Eure Zugangssequenz. Danke.\"", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2947] = {title = "Die Rückkehr des Rings", objective = "Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist.", description = "Ihr öffnet die Schachtel, die der Funkelmat 5200 ausgegeben hat, und entdeckt, was Ihr vermutet hattet - einen glänzenden Ring! Beim Anstecken des Rings fühlt Ihr magische Macht durch Euren Körper fließen.\n\nAuf der Innenseite des Rings befindet sich eine kleine, aber dennoch klar erkennbare Gravur des Siegels von Ironforge. Daneben sind drei kleine Initialen eingraviert: \"TdK\". Dies könnten entweder die Initialen des ursprünglichen Besitzers oder die des Herstellers des Rings sein. Den Ring behalten ... oder ihn dieser Person zurückgeben? Entscheidungen über Entscheidungen ...", progress = "He, immer mit der Ruhe, Partner - ich bin ein wichtiger Geschäftsmann! Der Kurier, der die Miete überbringen sollte, ist bestimmt einfach nur spät dran... Moment mal... Ihr seid ja gar nicht mein Vermieter.\n\nNatürlich seid Ihr das nicht - wie dumm von mir! Ihr seid hier, weil Ihr den besten Juwelier in ganz Ironforge sucht, einen, der KEINE VERFLUCHTEN Gegenstände herstellt. Jawohl!\n\nHm... Was braucht Ihr?", completion = "Ein Ring, sagt Ihr? Lasst mich mal sehen... Ja, und wie ich diesen Ring gefertigt habe.\n\nBevor Gnomeregan verloren ging, hatte ich dort einen kleinen Laden. Vielleicht ist es einer von denen, die ich zurückließ, als ich in die Hügel geflohen bin. Er ist recht schlicht gehalten und ich habe mehrere dieser Art hergestellt. Vielleicht gehörte er auch jemandem, der es nicht bis nach draußen geschafft hat.\n\nDunkeleisenzwerge hatten ihn? Tja, das fügt den ganzen Verschwörungstheorien, die bereits herumgeistern, eine weitere Ebene hinzu. Vielleicht interessieren sich offizielle Stellen dafür. Für Leute wie mich ist so etwas unwichtig.\n\nAber jetzt zurück zu diesem Ring...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2948] = {title = "Gnomen-Verbesserungen", objective = "Bringt Talvash del Kissel in Ironforge den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen.", description = "Hört mir zu, <Name>. Dieser Ring gehört Euch, das ist schon richtig... aber ich kann Euch einen besseren machen! Das Design ist, wie ich bereits sagte, wirklich einfach. Ich bin heutzutage wesentlich geschickter und für die läppische Summe von dreißig Silbermünzen werde ich ihn für Euch aufpeppen! Na ja, eigentlich etwas mehr als dreißig...\n\nIch bin derzeit in einer misslichen Lage. Mein ganzer Materialvorrat ist aufgebraucht. Wenn Ihr mir einen Barren Silber und einen Moosachat bringt, verziere ich Euch den Ring damit und peppe ihn richtig schön auf!!\n\nVertraut mir!", progress = "Habt Ihr die Materialien, die ich benötige? Ich würde Euch nicht darum bitten, wenn ich nicht gerade völlig vom Glück verlassen wäre...", completion = "Ah, genau das, was ich brauchte! Eines Tages, wenn ich es aus diesem Loch, in dem ich mich ungerechterweise befinde, herausgearbeitet habe, werde ich für Euch, nein für JEDERMANN die besten Schmuckstücke in ganz Azeroth herstellen! Bis es so weit ist, danke ich Euch, dass Ihr in Bezug auf die Reagenzien so anständig wart. Ich würde normalerweise zehnmal so viel für einen Ring von dieser Qualität verlangen, wie ich Euch abgeknöpft habe ...\n\nWo wir gerade davon sprechen, hier ist Euer neuer Ring!", rewards = "Ihr bekommt:\n\nTalvashs Goldring"},
[2949] = {title = "Die Rückkehr des Rings", objective = "Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist.", description = "Ihr öffnet die Schachtel, die der Funkelmat 5200 ausgegeben hat, und entdeckt einen glänzenden Ring! Beim Anstecken des Rings fühlt Ihr magische Macht durch Euren Körper fließen.\n\nAuf der Innenseite des Rings befindet sich eine kleine, aber dennoch klar erkennbare Gravur des Siegels von Orgrimmar. Daneben sind Buchstaben eingraviert, aber selbst nach der Säuberung sind nur die ersten drei zu erkennen: 'NOG...'\n\nDies könnten entweder die Initialen des ursprünglichen Besitzers oder die des Herstellers des Rings sein. Den Ring behalten ... oder 'NOG' suchen - Entscheidungen, Entscheidungen ...", progress = "Man sollte meinen, wir finden selbst einen Weg, diese dreckigen kleinen Gnome zu übertrumpfen. Ich würde sogar wetten, dass sie uns diese Maschine ursprünglich gestohlen haben! Pah, diese schleimigen, schmutzigen... ähm, ja? Braucht Ihr etwas?", completion = "Ein Ring aus Gnomeregan? Lasst mich mal sehen... nicht von mir, aber interessant.\n\nDiese Sache mit Gnomeregan - das hätte keinen größeren Trotteln passieren können. Jahrelang sind sie ein Witz und auf einmal bauen sie quasi über Nacht bessere Maschinen als wir?\n\nDunkeleisenzwerge hatten den Ring bei sich? Das wird ja immer interessanter! Hmmm, vielleicht haben die Gnome ja deren verrückte Golempläne gestohlen und verändert... Diese Dunkeleisenzwerge, die würden ihnen das bestimmt gern ordentlich heimzahlen. Es lohnt sich ganz sicher, da mal nachzuforschen.\n\nUnd da ist schließlich die Sache mit dem Ring...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2950] = {title = "Noggs Ringerneuerung", objective = "Bringt Nogg in Orgrimmar den glänzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen.", description = "Nein, nein, nein - ich behaupte nicht plötzlich, der Ring sei meiner. Normalerweise mache ich so etwas nicht, aber Eure Information über die Dunkeleisenzwerge war sehr nützlich. Ich werde diesen Ring für Euch so verbessern, dass selbst der, der dieses einfache kleine Ding hergestellt hat, es nicht hätte besser machen können. Wahrscheinlich war es irgendein Gnom ...\n\nWenn Ihr mir einen Barren Silber, einen Moosachat und dreißig Silbermünzen bringt, verziere ich den Ring damit derart, dass seine Magie noch verstärkt wird. Interessiert?", progress = "Habt Ihr die Materialien, die ich benötige? Ich kann dieses Stück nicht ohne die Dinge verbessern, um die ich Euch gebeten habe.", completion = "Hier habt Ihr Euren Ring, besser als je zuvor. Danke nochmals für die Information über diese Dunkeleisenzwerge. Das sieht nach einem vernünftigen Hinweis darauf aus, woher diese Gnome auf einmal mit Inspiration nach Goblin-Art gesegnet wurden.", rewards = "Ihr bekommt:\n\nNoggs Goldring"},
[2951] = {title = "Der Funkelmat 5200!", objective = "Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren.", description = "Dieser Apparat ist etwas ganz Besonderes unter den Gnomen, er bietet dem Wahnsinn außerhalb dieses Raums tapfer die Stirn. Eine kleine Plakette auf dem Gerät besagt: \"Der Funkelmat 5200\", gefolgt von einem kurzen Text:\n\n\"Schmutz und Verkrustungen ruinieren Euer Funkelzeug? Der Funkelmat 5200 definiert das Wort Glanz neu! Gebt den Gegenstand hinein, den Ihr gesäubert haben wollt, und werft drei Silbermünzen in den Münzschlitz. Lasst den Funkelmat 5200 einen Moment arbeiten - und voilà! Eure Wertgegenstände werden sauber und glänzend herauskommen!\"", progress = "Es scheint, als brauche das Gerät irgendein schmutzverkrustetes Objekt zum Säubern sowie drei Silbermünzen, um den Apparat in Gang zu bringen. Ist beides vorhanden, sollte der Funkelmat 5200 funktionieren...", completion = "Ihr füttert den Funkelmat 5200 mit dem schmutzverkrusteten Gegenstand sowie mit drei Silbermünzen. Die Maschine erwacht schlagartig zum Leben und versucht hektisch, den unbekannten Gegenstand vom Schmutz zu reinigen. Laute, heftige, peitschende Geräusche schlagen Euch aus dem Herzen der Maschine entgegen. Der Metallrahmen des Apparates knarrt und ächzt, als er hin und her schlingert...", rewards = nil},
[2952] = {title = "Der Funkelmat 5200!", objective = "Der Funkelmat 5200 stoppt so schnell, wie er losgelegt hat. Ein einfaches \"Ding\" ist aus der Maschine zu hören und der Aufnahmebehälter der Maschine springt auf. Im Funkelmat 5200 liegt eine kleine Schachtel, die von einem Schleifchen umschlungen ist. Offensichtlich verpackt die Maschine ein Objekt, nachdem sie die Schmutzverkrustung entfernt hat. Selbst wenn die Maschine nicht funktioniert hat, ist der Gegenstand jetzt immerhin in einer hübschen Schachtel verpackt.\n\nTja, es gibt nur einen Weg herauszufinden, ob sie den Gegenstand gesäubert hat oder nicht...", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nFunkelmatverpackter Kasten"},
[2953] = {title = "Mehr Spaß mit dem Funkelmaten", objective = "Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!", description = nil, progress = "Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!", completion = "Der Funkelmat 5200 erwacht hin und her schlingernd zum Leben. Innen wird der hilflose Schmutz, der das eingelegte Objekt verkrustet hat, vom Gnomen-Lösungsmittel der Maschine pulverisiert.\n\nDer Funkelmat 5200 kommt zum Stillstand, angekündigt durch ein vertrautes \"Ding!\". Der Aufnahmebehälter der Maschine springt auf und offenbart eine ordentlich eingewickelte Schachtel.", rewards = "Ihr bekommt:\n\nFunkelmatverpackter Kasten"},
[2954] = {title = "Der Steinbehüter", objective = "Findet den Zweck des Steinbehüters von Norgannon heraus und interagiert dann mit dem Uldum-Sockel in der Tanariswüste.", description = "Willkommen - Ich bin der Wächter des Eingangs. Ich werde Euch den Zugang zum Areal von Uldum nur gewähren, wenn Ihr die Platten von Uldum in Euren Scheibensatz integriert habt.\n\nDas Erscheinen des Steinbehüters von Norgannon muss die Reaktion sein, die man sich davon erhoffte, als man Euch mit den Platinscheiben in die Tanariswüste schickte. Wie Euch aufgetragen, werdet Ihr die Geschichte, die hinter dem Steinbehüter steckt, herausfinden müssen, bevor Ihr weitermachen könnt.", progress = "Der Sinn des Steinbehüters muss erst herausgefunden werden, bevor Ihr weitergehen könnt...", completion = "Die Stimme des Steinbeobachters erschallt voller Macht und Autorität:\n\n\"Ihr werdet Eure Scheiben zurückerhalten, wenn Ihr Zugang zum Sockel habt. Wenn Ihr die Platten von Uldum erworben und in Euren bestehenden Scheibensatz eingefügt habt, dann dürft Ihr den Komplex betreten.\"", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2962] = {title = "Das einzige Heilmittel ist mehr grünes Leuchten", objective = "Reist nach Gnomeregan und bringt etwas von der hoch konzentrierten radioaktiven Ablagerung zurück. Seid gewarnt, die Ablagerung ist instabil und wird ziemlich schnell zerfallen.\n\nOzzie wird außerdem Eure schwere bleierne Phiole benötigen, nachdem die Aufgabe erledigt ist.", description = "Eure Probe war nicht nur von unzureichender Menge, sondern auch noch verunreinigt.\n\nWas wir brauchen, ist mehr von dem grünen Leuchten. Die Troggs sind offensichtlich nicht stark genug verstrahlt, um unseren Ansprüchen zu genügen. Ihr werdet nach Gnomeregan gehen und etwas der radioaktiven Ablagerung direkt von der Quelle besorgen müssen. Ich spreche von den bestrahlten Brühschleimern, Lauerern und Schrecken. Seid gewarnt, diese Art von Ablagerung ist schwer abzufüllen. Es könnte Euch mehrere Versuche mit der Phiole kosten, bis Ihr eine geeignete Probe bergen könnt.", progress = "Hm, Ihr leuchtet nicht. Das ist ein gutes Zeichen.", completion = "&lt;Ozzie mustert Euch.&gt; Erstaunlich, Ihr habt noch all Eure Gliedmaßen. Jetzt ist es an der Zeit nachzusehen, was dieses Zeug ausrichten kann!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2963] = {title = "Omen von Uldum", objective = "Sprecht mit Historiker Karnik in der Halle der Forscher in Ironforge.", description = "Seid mir erneut gegrüßt, <Name>! Seit Eurer Entdeckung in Uldaman ist die Forscherliga voller Aufregung. Die Liga hat daran gearbeitet, die Geheimnisse der Miniaturplatinscheiben zu enträtseln, die Ihr gefunden habt. Euer treffliches Erscheinen hier in der Halle erlaubt es mir, Euch mitzuteilen, dass wir ziemlich wahrscheinlich eine Spur haben!\n\nHistoriker Karnik hat einige wichtige Hinweise auf den wahren Ursprung des Tals der Behüter in der Tanariswüste gefunden. Er möchte so schnell wie möglich mit Euch sprechen!", progress = nil, completion = "Ich bin froh, dass Ihr Euer Interesse für die Erforschung behalten habt, &lt;Name&gt;! Mit Eurem naturgegebenen Geschick und Eurer Courage können wir Rätsel knacken, die wir nicht für möglich gehalten hätten!\n\nDie Scheiben von Norgannon in Uldaman waren eine wahre Fundgrube an Informationen. Ihr durftet lediglich an der Oberfläche der Informationen kratzen, die dort gespeichert sind. Die Schöpfer sollen Gerüchten zufolge weitere Speicher überall in Azeroth gehabt haben. Und das bringt uns nach Uldum ...", rewards = "Ihr bekommt:\n\n"},
[2964] = {title = "Eine zukünftige Aufgabe", objective = "Sprecht mit Hochforscher Magellas in Ironforge.", description = "Nun, <Name>... Wir scheinen derzeit in einer temporären Sackgasse zu stecken. Wir wissen, was wir brauchen - die Platten von Uldum -, aber wir haben keinen Schimmer, wo diese sein könnten. Wir müssen eine Menge Nachforschungen anstellen, um einen guten Einsatzplan zusammenzustellen. Ich habe ein paar Ideen, wo man mit der Suche anfangen könnte. Ich hege große Hoffnungen, dass wir Euch bald bitten werden, loszuziehen und sie zu bergen.\n\nDer Hochforscher muss hiervon in Kenntnis gesetzt werden, <Name>. Zweifellos wird er Euch ebenfalls persönlich dafür danken wollen, dass Ihr der Liga wieder einmal geholfen habt.", progress = nil, completion = "Wir sind uns demnach alle einig - die beste Vorgehensweise ist es, diese Angelegenheit erst einmal ruhen zu lassen, bis wir die Gebiete, in denen diese Scheiben versteckt liegen könnten, etwas eingrenzen können. Ihr habt uns so weit gebracht, &lt;Name&gt;, und ich hoffe, dass Ihr derjenige sein werdet, der zurück ins Feld geht und Uldum für uns alle öffnet!\n\nErlaubt mir, Euch zwischenzeitlich dieses Honorar auszuhändigen. Dies sollte alle Ausgaben decken, die bei unserer Unterstützung angefallen sind, inklusive eines kleinen Bonus. Schaut bald wieder bei uns herein ... Uldum ruft!", rewards = "Ihr bekommt:\n\n"},
[2965] = {title = "Omen von Uldum", objective = "Sprecht mit Nara Wildmane auf der Anhöhe der Ältesten in Thunder Bluff.", description = "Ah, <Name>, es ist vortrefflich, dass Ihr erneut zu mir gekommen seid. Eure Funde auf der Uldaman-Grabungsstätte haben uns Gelehrten sicherlich einigen Gesprächsstoff geliefert. Ich unterhielt mich also gerade mit einer der Druiden, Nara Wildmane, als mir dämmerte, dass ihre früheren Erfahrungen als Abenteurer von großer Wichtigkeit für unseren nächsten Schritt sein könnten.\n\nIch möchte, dass Ihr mit ihr über ihre Reisen ins Tal der Behüter in der Tanariswüste sprecht. Sie erwartet Euch auf der Anhöhe der Ältesten.", progress = nil, completion = "Es gibt tief in der Tanariswüste einen Ort, der Tal der Behüter genannt wird. Diese Scheiben, die Ihr geborgen habt... Die Übersetzung ihrer Glyphen erwähnt einen Ort, der Uldum genannt wird. Die meisten denken, dieser Ort sei ein Mythos.\n\nIch weiß, dass dem nicht so ist; Uldum existiert. Ich war dort. Nun... jedenfalls davor.\n\nDas Problem ist Folgendes, &lt;Name&gt;: Wir glauben, es gibt eine Verbindung zwischen den Scheiben und Uldum, und wir wollen, dass Ihr dort hingeht.", rewards = "Ihr bekommt:\n\n"},
[2966] = {title = "Mal sehen, was passiert...", objective = "Bringt die Miniaturplatinscheiben zu den Toren von Uldum in Tanaris und sucht nach Hinweisen auf die Verbindung zwischen beidem.", description = "Sage Truthseeker und ich würden Euch bitten, die Miniaturscheiben, die Ihr gefunden habt, zu den versiegelten Toren von Uldum zu bringen. Wir... wir sind uns nicht ganz sicher, was dann passieren wird.\n\nDas klingt ein wenig riskant, sicher, das geben wir auch zu. Es könnte allerdings auch gar nichts passieren. Vielleicht müsst Ihr die Scheiben mit etwas benutzen. Vielleicht öffnen sich die Türen, wenn Ihr die Scheiben bei Euch habt. Versucht alles Mögliche und seid bereit für alles, was passieren könnte.\n\nFindet alles heraus, was Ihr könnt, und kehrt dann zu mir zurück. Wir werden dann viel zu bereden haben.", progress = "Dieser vertraut aussehende Sockel ragt aus dem heißen Sand heraus. Vielleicht gibt es einen Grund für sein Hiersein...", completion = "Als Ihr den Sockel berührt, summen und glühen die Miniaturplatten von Uldaman in Eurem Rucksack. Eine vertrautes Kribbeln überzieht Eure Hände, als das Bild eines weiteren Steinbeobachters vor den Toren von Uldum zum Leben erwacht.\n\n\"Willkommen. Ich bin der Behüter des Eingangs. Die Scheiben, die für den Zugang verwendet wurden, enthalten nicht die korrekten Zutrittsscheiben, die Platten von Uldum. Bitte fügt diese Platten der Scheibenstruktur hinzu und wiederholt Eure Zugangssequenz. Danke.\"", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2967] = {title = "Rückkehr nach Thunder Bluff", objective = "Sprecht mit Nara Wildmane in Thunder Bluff.", description = "Ihr greift erneut auf den Sockel zu und die Platinscheiben erscheinen plötzlich wieder in Eurem Rucksack.\n\nNachdem Ihr das Wissen des Steinbehüters verinnerlicht habt und die Scheiben wieder in Eurem Besitz sind, ist es jetzt an der Zeit, nach Thunder Bluff zurückzukehren und Nara Wildmane von Eurer Entdeckung in Kenntnis zu setzen.", progress = "Wilkommen zurück, <Name>. Habt Ihr die Scheiben zu Eurem Vorteil nutzen können oder war alles vergebens?", completion = "Euch fehlten einige Scheiben? Interessant, es sieht so aus, als wären die Scheiben von Norgannon nur Teile eines vollständigen Satzes - wie Schlüssel auf einem Schlüsselring, wenn Ihr so wollt.\n\nWenn wir die Platten von Uldum finden könnten, hätten wir tatsächlich Zugang zum Uldum-Komplex selbst. Ich weiß nicht, ob ich mich ob dieser Aussichten freuen oder fürchten soll.\n\nWir müssen vielleicht alles riskieren, um sicherzustellen, dass die Geheimnisse der Erde, die uns alle zerstören könnten, genau das bleiben - nämlich Geheimnisse.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2968] = {title = "Eine zukünftige Aufgabe", objective = "Sprecht mit Sage Truthseeker in Thunder Bluff.", description = "Nun, <Name>... Wir scheinen unglücklicherweise in einer Sackgasse zu stecken. Wir wissen, was wir brauchen - die Platten von Uldum -, aber wir haben keinen Schimmer, wo diese sein könnten. Wir werden Nachforschungen darüber anstellen und dann einen soliden Einsatzplan entwickeln. Ich habe ein paar Ideen, wo man mit der Suche anfangen könnte; Ich hege große Hoffnungen, dass wir Euch bald bitten werden, Euch wieder unseren Bemühungen um die Entdeckung der Wahrheit anzuschließen.\n\nSage Truthseeker muss hiervon in Kenntnis gesetzt werden, <Name>; zweifellos wird er Euch ebenfalls persönlich dafür danken wollen, dass Ihr noch einmal dem Ruf gefolgt seid.", progress = nil, completion = "Wir sind uns demnach alle einig - die beste Vorgehensweise ist es, diese Angelegenheit erst einmal ruhen zu lassen, bis wir die Gebiete, in denen diese Platten versteckt liegen könnten, etwas eingrenzen können. Ihr habt uns so weit gebracht, &lt;Name&gt;, und ich hoffe, dass Ihr derjenige sein werdet, der zurück ins Feld geht und den Geheimnissen von Uldum auf den Grund geht!\n\nErlaubt mir, Euch zwischenzeitlich dieses Honorar auszuhändigen. Dies sollte alle Ausgaben decken, die bei unserer Unterstützung angefallen sind, inklusive eines kleinen Bonus. Schaut bald wieder bei uns herein... Uldum ruft uns alle, junger Freund.", rewards = "Ihr bekommt:\n\n"},
[2969] = {title = "Freiheit für alle Kreaturen", objective = "Befreit mit dem Bambuskäfigschlüssel die Grimmlingflitzer aus dem Pferch im Grimmtotemlager. Kindal Moonweaver sowie mindestens 6 Grimmlingflitzer müssen überleben.\n\nIhr habt 6 Minuten, bis Kindal beschließt, dass es Zeit zum Rückzug und Eure Aufgabe gescheitert ist.", description = "Der dreckige Grimmtotemklan fängt Feendrachen ein, <Name>. Jer’kai und ich haben keine Ahnung, was sie mit ihnen vorhaben, aber es ist bestimmt nichts Gutes.\n\nWir sind nicht stark genug, um uns durch das Lager zu kämpfen und die gefangenen Drachen zu befreien, aber mit Eurer Hilfe...\n\nWenn Ihr willens seid und ein paar starke Freunde habt, dann befreit mit diesem Schlüssel die Kreaturen aus ihrem Käfig und stellt sicher, dass sie mit ihrem Leben davonkommen. Ich werde die ganze Zeit an Eurer Seite sein. Jer'kai wird hier bleiben.", progress = nil, completion = "Dank sei Elune, &lt;Name&gt;! Ihr seid ein großer Segen für uns und für die Flitzer, die Ihr gerettet habt. Jer’kai und ich hätten allein den Drachen nicht helfen können - Eure Einmischung in die Angelegenheiten der Grimmtotem wird nicht vergessen werden.\n\nSprecht jetzt mit Jer’kai... Ich muss unseren Vergeltungsschlag vorbereiten. Dass die Feendrachen frei sind, bedeutet nicht, dass es so bleibt. Jer’kai und ich werden jetzt in die Offensive gehen.", rewards = "Ihr bekommt:\n\n"},
[2970] = {title = "Gerechtigkeit üben", objective = "Tötet 12 Naturalisten der Grimmtotem, 10 Räuber der Grimmtotem sowie 6 Schamanen der Grimmtotem und kehrt dann zu Jer’kai Moonweaver nach Feralas zurück.", description = "Wie sie Euch ja schon mitgeteilt hat, tragen Kindal und ich den Kampf jetzt zu den Grimmtotem. Gemeinsam sollten wir in der Lage sein, einige der Tauren ohne große Gefahr für uns selbst auszuschalten, aber wir würden etwas Hilfe sehr begrüßen, wenn Ihr dazu bereit wärt.\n\nIhr habt das Lager unterhalb von uns ja schon gesehen, aber es gibt mehr davon im Osten. Verwendet Eure eigenen Taktiken, um den Tauren so viel Schaden wie möglich zuzufügen. Wir können uns alle wieder hier treffen, nachdem sie Kindals Pfeile und Eure Waffen geschmeckt haben!", progress = "Kindal benötigt Vorbereitungszeit, aber unsere Verluste gehen bereits in die Dutzende. Der Grimmtotemklan ist sich unserer Anwesenheit in der Gegend wohl bewusst und seine Mitglieder suchen uns wie giftige Vipern.\n\nSie werden alles in ihrer Macht Stehende tun, um uns die Köpfe abzureißen. Seid auf der Hut ... Sie werden jetzt, nachdem Ihr Euch eingemischt habt, auch hinter Euch her sein.", completion = "Kindal hatte Recht, was Euch betrifft, &lt;Name&gt;... Ihr habt das richtige Händchen dafür. Ihr seid ein erfahrenerer Abenteurer als wir beide zusammen und dafür danken wir Euch.\n\nDer Grimmtotemklan ist viel feindseliger als die meisten Tauren... Ich frage mich, ob die Tauren die Taten von ihresgleichen missbilligen. Es würde mich nicht überraschen. Wie Euch wahrscheinlich klar sein dürfte, haben viele Völker Azeroths Verbindungen zu weniger freundlichen Zeitgenossen.\n\nDoch darüber reden wir ein andermal.", rewards = "Ihr bekommt:\n\n"},
[2972] = {title = "Gerechtigkeit üben", objective = "Bringt Jer’kais Siegelring zu Hohepriesterin Tyrande Whisperwind nach Darnassus.", description = "Hier draußen in der Wildnis haben Kindal und ich nur geringe Mittel, um Euch für Eure Hilfe zu entlohnen, aber wir wollen nicht, dass Ihr Euch nicht wertgeschätzt fühlt. Nehmt meinen Siegelring.  Solltet Ihr Euch jemals in Teldrassil wiederfinden, geht zum Tempel des Mondes im Herzen von Darnassus. Dort werdet Ihr meine Hohepriesterin vorfinden, Tyrande Whisperwind. Der Ring wird sie wissen lassen, dass es uns gut geht, und Eure Geschichte untermauern.\n\nWir beide danken Euch, <Name>.", progress = "Hallo, Kindchen. Es freut uns, mächtige Abenteurer hier im Tempel zu haben. Wenn Ihr die Zeit findet, würdet Ihr mit den jüngeren Abenteurern die eine oder andere Geschichte teilen? Ich weiß, dass einige von ihnen von Eurer Weisheit profitieren könnten.\n\nIch bin untröstlich, wie unhöflich von mir. Ihr kamt in den Tempel, um unsere Hilfe zu ersuchen, und ich stelle Ansprüche an Euch. Bitte, verzeiht mir. Sagt mir, was die Diener des Lichts für Euch tun können.", completion = "Das ist eine erstaunliche Geschichte, &lt;Name&gt;. Es freut uns, dass Ihr nicht nur den Drachen, sondern auch einer unserer Priesterinnen geholfen habt. Jer’kai hatte Recht, Euch zu mir zu schicken. Ich werde dafür sorgen, dass sie ihren Ring wiederbekommt - ich entsende ohnehin demnächst einige Späher in Richtung Feralas. Das wird eine weitere Sache sein, die sie auf ihrer Mission überprüfen können.\n\nDanke noch einmal, macht es Euch bitte bequem, solange Ihr hier seit.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFichtenweidengelenkbänderNachtschuppengurt\n\nIhr bekommt außerdem:\n\n"},
[2973] = {title = "Schimmer für einen neuen Umhang", objective = "Bringt 10 regenbogenfarbene Grimmlingflitzerflügel zu Krueg Skullsplitter nach Camp Mojache.", description = "Grüße, <Klasse>. Ich bin mit meinen Gefährten auf einer Mission für unsere Meister aus Orgrimmar hinunter nach Feralas gereist.\n\nMeine Lebensgefährtin Korrin liebt neue Kleider und daher habe ich vor, ihr einen neuen Umhang zu fertigen, der mit den hauchzarten Flügeln von Feendrachen geschmückt ist. Seid Ihr vielleicht in der Lage, mir zu helfen? Grimmlingflitzer mit prachtvollen Flügeln, wie ich sie will, gibt es westlich vom Camp Mojache.", progress = "Die Grimmlingflitzer können gefährliche Tierwesen sein, wenn man sie provoziert. Seid vorsichtig im Umgang mit ihnen, <Klasse>. Und passt noch viel mehr auf etwaige Nachtelfen in der Gegend auf. Diese lästigen Narren überfallen einen gern in den Wäldern.\n\nWenn Ihr genug Flügel habt, lasst es mich wissen, ich werde Euch sicher gut entlohnen!", completion = "Wunderbar, &lt;Klasse&gt;! Die sind perfekt. Das sind genug, um einen Umhang für Korrin zu fertigen und vielleicht noch anderes! Danke.\n\nIch hoffe, die Reise war nicht zu gefährlich... Das Gebiet von Feralas ist nicht gerade als harmlos bekannt, aber Ihr habt Euch offensichtlich recht gut geschlagen.\n\nNochmals danke, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"},
[2974] = {title = "Eine grausige Entdeckung", objective = "Bringt 20 Grimmtotemhörner zu Krueg Skullsplitter nach Camp Mojache.", description = "Was!? Ihr seid in dieser Gegend auf Tauren getroffen? Ihr macht Witze! Wie sahen sie aus?\n\nDer Grimmtotemklan! Ihr habt einige von denen gefunden? Belgrom, einer unserer Meister, interessiert sich für diese Sippe... Er hat sogar ein Kopfgeld auf sie ausgesetzt.\n\nIhr müsst wieder zurückgehen, <Klasse>. Geht zurück und bringt mir ihre Hörner... haufenweise, wenn Ihr könnt. Mit den Grimmtotem ist nicht zu spaßen und man sollte sie nicht unterschätzen. Geht zurück und erschlagt sie; lasst die Flüsse in Feralas rot werden von ihrem dunklen Blut.", progress = "Nehmt meine Worte ernst, <Klasse>, der Grimmtotemklan ist böse. Wenn Ihr seinen Aufenthaltsort herausgefunden habt, dann ist es an Euch, zurückzukehren und den ersten Schlag gegen ihren Klan zu führen... bevor er in unser eigenes Land kommt und unsere Dörfer auslöscht oder unser Land plündert.", completion = "Das sind gute Hörner, &lt;Klasse&gt;. Gut gemacht. Ich nehme sie Euch ab und werde Belgrom garantiert davon berichten, sobald wir nach Orgrimmar zurückkehren. Ihr habt mir jetzt schon zweimal geholfen und dafür habt Ihr meine Anerkennung. Vielleicht kann ich Euch in Zukunft einmal helfen! Viel Glück noch für Euch.", rewards = "Ihr bekommt:\n\n"},
[2975] = {title = "Die Oger von Feralas", objective = "Rok Orhan im Camp Mojache will, dass Ihr 10 Oger der Gordunni, 10 Magier der Gordunni und 5 Schläger der Gordunni tötet.", description = "Der Einfluss des Ogerstamms der Gordunni sind in diesem Gebiet kaum zu übersehen. Schaut Euch mal um, <Name>. Seine bloße Anwesenheit zeichnet das Land. Wir müssen die Gordunni zurückdrängen, bevor sie sich weiter nach Feralas hinein ausbreiten können.\n\nFolgt dem Fluss nach Norden und Ihr werdet ihren Außenposten finden. Verringert ihre Zahl, <Name>. Wir müssen ihnen klar machen, dass ihre Art hier nicht willkommen ist.", progress = nil, completion = "Ausgezeichnet, &lt;Name&gt;. Zur rechten Zeit wird das Land heilen. Wir dürfen nicht aufgeben.", rewards = "Ihr bekommt:\n\n"},
[2976] = {title = "Eine grausige Entdeckung", objective = "Bringt die Kiste mit Grimmtotemhörnern zu Belgrom Rockmaul nach Orgrimmar.", description = "Was?!\n\nHm, ich hab wohl wirklich ein Kopfgeld erwähnt, nicht wahr? Gut, das wird mich lehren, meinen Mund nicht zu weit aufzureißen, oder?\n\nIhr habt die Arbeit gemacht, also ist es wohl nur fair, wenn Ihr den größten Lohn einheimst. Nehmt die Hörner, ich lasse sie für Euch in eine Kiste packen. Findet Belgrom Rockmaul im Tal der Ehre. Er wird wissen wollen, was Ihr gesehen habt, und Euch für Eure harte Arbeit belohnen.\n\nMacht es gut, <Klasse>, und danke noch einmal für alles, was Ihr getan habt.", progress = "Fasst Euch kurz, <Klasse>, ich habe heute noch einiges zu erledigen.", completion = "Die Grimmtotem!? Das ist interessant. Ihr sagt, Ihr seid ihnen auf der Jagd in Feralas begegnet? Wirklich?\n\nMeine Partner werden Eure Neuigkeiten hören wollen, &lt;Klasse&gt;. Erzählt mir mehr und ich werde derweil Eure Münzen abzählen.\n\nUnd bevor Ihr geht, wisset, dass ich Euch für die Informationen danke, die Ihr an diesem Tag an mich weitergegeben habt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKampfgehärtetes CapeJademondkugel\n\nIhr bekommt außerdem:\n\n"},
[2977] = {title = "Rückkehr nach Ironforge", objective = "Sprecht mit Historiker Karnik in Ironforge.", description = "Ihr greift erneut auf den Sockel zu und die Platinscheiben erscheinen plötzlich wieder in Eurem Rucksack.\n\nNachdem Ihr das Wissen des Steinbehüters verinnerlicht habt und die Scheiben wieder in Eurem Besitz sind, ist es jetzt an der Zeit, nach Ironforge zurückzukehren und die Forscherliga von Eurer Entdeckung in Kenntnis zu setzen.", progress = "Willkommen zurück, <Name>. Habt Ihr die Scheiben zu Eurem Vorteil nutzen können oder war alles letzten Endes nur Zeitverschwendung?", completion = "Euch fehlten einige Scheiben? Interessant, es sieht so aus, als wären die Scheiben von Norgannon nur Teile eines vollständigen Satzes - wie Schlüssel auf einem Schlüsselring, wenn Ihr so wollt.\n\nWenn wir die Platten von Uldum finden könnten, hätten wir tatsächlich Zugang zum Uldum-Komplex selbst! Stellt Euch nur vor, den Ort zu erforschen, an dem die Schöpfer gearbeitet haben, und das, ohne eine riesige Schaufel mitzunehmen.\n\nNicht, dass an einer Schaufel etwas falsch wäre ... oder am Graben ...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2978] = {title = "Die Gordunnischriftrolle", objective = "Bringt die Gordunnischriftrolle zu Rok Orhan ins Camp Mojache.", description = "Ihr hebt die verschmutzte Schriftrolle auf und bemerkt, dass sie eine Art Versammlung oder Zermonie darstellt. Rok Orhan wird sich für diese Schriftrolle, und was sie für die Gordunni bedeutet, interessieren.", progress = "Was ist das?", completion = "Diese Schriftrolle... Ihr habt sie im Außenposten der Gordunni gefunden?", rewards = "Ihr bekommt:\n\n"},
[2979] = {title = "Dunkle Zeremonie", objective = "Rok Orhan im Camp Mojache will, dass Ihr eine Gordunnikugel findet.", description = "Dies scheinen Pläne für eine Art dunkle Zeremonie zu sein, <Name>. Soweit ich das erkennen kann, wird dieses Ritual von den Magierlords der Gordunni ausgeführt.\n\nFindet einen dieser Magierlords und sammelt eine Kugel von ihm.\n\nDie Kugel eines Magiers enthält große Macht und wird uns dabei helfen, mehr über diese Zeremonie und die Magie, die die Gordunni beherrschen, herauszufinden.", progress = "Wir müssen mehr darüber herausfinden, warum die Gordunni hier sind, <Name>.", completion = "Diese Kugel wird uns mehr Informationen über die Gordunni geben... die wir dann verwenden werden, um ihren Untergang zu planen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[2980] = {title = "Die Oger von Feralas", objective = "Rok Orhan im Camp Mojache will, dass Ihr 10 Schamanen der Gordunni, 10 Hexenmeister der Gordunni und 5 Raufer der Gordunni tötet.", description = "Jetzt, da Ihr bewiesen habt, dass Ihr ein wahrer Kämpfer seid, vertraue ich darauf, dass Ihr den Mut besitzt, mit der vorliegenden Aufgabe weiterzumachen.\n\nReist in die obere Wildnis südwestlich von hier. Dort gibt es einige verlassene und zerstörte Gebäude auf dem Land, das einst den Nachtelfen gehörte. Sucht nach diesen Ruinen, und wenn Ihr verwelkte Bäume und entweihtes Gelände seht, dann werdet Ihr die Gordunni finden. Drängt sie zurück.\n\nDiese Oger sind viel stärker als diejenigen, denen Ihr bisher entgegengetreten seid, <Name>. Seht Euch vor.", progress = nil, completion = "Ihr habt Euch als ein vertrauenswürdiger und verlässlicher Verbündeter erwiesen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[2981] = {title = "Eine Bedrohung in Feralas", objective = "Belgrom Rockmaul will, dass Ihr mit Rok Orhan im Camp Mojache sprecht.", description = "Feralas ist der ideale Ort für jemanden mit Eurer Erfahrung, <Klasse>, der sich selbst beweisen will. Ein Stamm von Ogern, die sich Gordunni nennen, ist die vorherrschende Militärmacht dort, und ihre Zahl wächst. Sie müssen aufgehalten werden, bevor sie unsere Anwesenheit in Feralas bedrohen.\n\nEine mir bekannte Kriegerin mit Namen Rok Orhan lebt im Camp Mojache in Feralas; geht zu ihr. Sie wird Euch mehr über die Situation erzählen, wenn Ihr dort ankommt.", progress = nil, completion = "Belgrom hat Euch also hergeschickt. Ihr kommt gerade rechtzeitig, &lt;Volk&gt;.\n\nLasst mich die Situation erklären und dann könnt Ihr entscheiden, ob Ihr Euch der Herausforderung gewachsen fühlt... Doch wenn Belgrom Euch geschickt hat, dann besteht sicher kein Zweifel an Eurem Mut.", rewards = "Ihr bekommt:\n\n"},
[2982] = {title = "Die obere Wildnis", objective = "Angelas Moonbreeze will, dass Ihr 8 Hexenmeister der Gordunni, 8 Schamanen der Gordunni und 8 Schläger der Gordunni tötet.", description = "Obwohl es gefährlich ist, haben Troyas und ich die Ruinen erforscht, die in den Wäldern von Feralas zu finden sind.\n\nIn jüngster Zeit ist Troyas jedoch oft allein in die obere Wildnis gegangen und ich mache mir Sorgen um ihn. Die Oger der Gordunni haben dieses Gebiet besetzt und sie reagieren nicht sehr freundlich auf jemanden, der ihr Territorium betritt.\n\nIch hoffte, dass Ihr vielleicht zu den Ruinen im Südosten reisen und einige der Oger beseitigen würdet. Macht es ein wenig sicherer für meinen Troyas und ich werde Euch sehr dankbar sein.", progress = nil, completion = "Ich bin sehr dankbar, dass Ihr das für mich tun konntet.\n\nAber bitte kein Wort darüber zu Troyas...", rewards = "Ihr bekommt:\n\n"},
[2983] = {title = "Ruf des Feuers", objective = "Sucht Kranal Fiss im Brachland.", description = "Es ist eine Weile her, seit Ihr zuletzt geprüft wurdet, <Name>. Ihr wart in Euren Studien bisher sehr geduldig, doch es ist an der Zeit, dass Ihr etwas über größere Mächte erlernt... Es ist an der Zeit, dass Ihr wahre Macht erfahrt. Das Element des Feuers ist Euer, wenn Ihr bereit seid, dafür zu bezahlen.\n\nSucht nach Kranal Fiss im Brachland. Er lebt in einer kleinen Siedlung nördlich von Crossroads, aber gebt Acht... wenn Ihr das Land der Nachtelfen erreicht, seid Ihr zu weit gegangen.", progress = nil, completion = "Hmmm, hat Swart Euch geschickt, ja?\n\nNun denn, Swart kann man immer vertrauen. Das bedeutet, dass Ihr bereit seid, Euer nächstes Sapta zu nehmen, das Feuersapta.\n\nIch sehe es schon in Euren Augen, das Lodern, das Verlangen. Ihr habt von der Macht gekostet und seid jetzt bereit für mehr. Geduld, &lt;Name&gt;. Vergesst nicht, was Euch die Erde lehrte. Macht und Zerstörung werden sicherlich kommen, dennoch müsst Ihr wissen, wann Ihr Euch zurückhalten solltet.", rewards = "Ihr bekommt:\n\n"},
[2984] = {title = "Ruf des Feuers", objective = "Sucht Kranal Fiss im Brachland.", description = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, <Name>. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über Zerstörung zu lernen... und über Chaos. Ihr könnt das Element des Feuers verstehen lernen, wenn Ihr bereit seid, dafür zu bezahlen.\n\nSucht nach Kranal Fiss im Brachland. Er lebt in einer kleinen Siedlung nördlich von Crossroads, aber gebt Acht, wenn Ihr das Land der Nachtelfen erreicht, seid Ihr zu weit gegangen.", progress = nil, completion = "Hmmm, hat Narm Euch geschickt, ja?\n\nNun denn, Narm kann man immer vertrauen. Das bedeutet, dass Ihr bereit seid, Euer nächstes Sapta zu nehmen, das Feuersapta.\n\nIch sehe es schon in Euren Augen, das Lodern, das Verlangen. Ihr habt von der Macht gekostet und seid jetzt bereit für mehr. Geduld, &lt;Name&gt;. Vergesst nicht, was Euch die Erde lehrte. Macht und Zerstörung werden sicherlich kommen, dennoch müsst Ihr wissen, wann Ihr Euch zurückhalten solltet.", rewards = "Ihr bekommt:\n\n"},
[2985] = {title = "Ruf des Wassers", objective = "Sucht Islen Waterseer im Brachland.", description = "Ihr seht aus, als wäret Ihr bereit für die nächste Prüfung, <Name>. Ihr wart bislang geduldig in Euren Studien, doch die Zeit ist gekommen, da Ihr mehr erlernen müsst. Die Zeit ist gekommen, mehr über die Reinheit des Wassers zu erlernen.\n\nSucht nach Islen Waterseer im Brachland. Sie befindet sich an der Ostküste, südlich von Ratchet und dem Südstrom. Ihr findet sie in ihrer Angelhütte. Viel Glück, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[2986] = {title = "Ruf des Wassers", objective = "Sucht Islen Waterseer im Brachland.", description = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, <Name>. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über die Reinheit des Wassers zu lernen.\n\nSucht nach Islen Waterseer im Brachland. Sie befindet sich an der Ostküste, südlich von Ratchet und dem Südstrom. Ihr findet sie in ihrer Fischerhütte. Viel Glück, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[2987] = {title = "Gordunnikobalt", objective = "Orwin Gizzmick im Camp Mojache will 12 Proben Gordunnikobalt.", description = "Ich bin gerade erst hier in Feralas angekommen und habe gehört, dass die Oger der Gordunni, die die Wildnis hier bewohnen, einige interessante Mineralien besitzen. Keiner weiß, was die so vorhaben, aber sie passen höllisch gut auf dieses Zeug auf! Sie lassen es nicht einfach herumliegen. Oh nein, sie vergraben es, damit Leute wie ich es nicht in die Finger bekommen.\n\nWenn Ihr wollt, gebe ich Euch meine Schaufel. Geht zum Außenposten der Gordunni nördlich von hier und grabt mir etwas Gordunnikobalt aus. Haltet nach blauem Glühen Ausschau und fangt dann dort an zu graben!", progress = "Los jetzt, macht Euch auf den Weg und fangt an zu graben!\n\nIch muss noch andere Orte besuchen und andere Leute treffen - Zeit ist Geld!", completion = "Perfekt! Ich werde das auf meinen weiteren Reisen mitnehmen, &lt;Name&gt;. Ich bin sicher, dass ich jemanden finden kann, der eine hübsche Summe für dieses Kobalt zahlen wird.\n\nHier, nehmt dies für Eure Mühen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nStiefel der MaharishiSternenschauer-Umhang\n\nIhr bekommt außerdem:\n\n"},
[2988] = {title = "Käfige der Witherbark", objective = "Durchsucht die Käfige in den beiden Dörfern der Witherbark und kehrt dann zu Greifenmeister Talonaxe zurück.", description = "Der Sohn unseres mächtigsten Greifen ist verschwunden! Sturmschwinges Erbe, Scharfschnabel, ging vor ein paar Tagen bei der Jagd mit seinen Eltern verloren und wir glauben, dass die Trolle ihn geschnappt haben.\n\nIhr müsst uns helfen! Durchsucht die Käfige in den beiden Dörfern der Witherbarktrolle, um herauszufinden, ob Scharfschnabel dort ist.", progress = "Habt Ihr die Käfige durchsucht, <Name>? Wir müssen Scharfschnabel finden!", completion = "Scharfschnabel war nicht in den Dörfern? Hm... Das ist eine schlimme Nachricht. Dieser Greif ist dazu bestimmt, die nächste Greifengeneration anzuführen. Wenn er verloren ist, werden die Stärke und der Geist unserer Flotte deutlich in Mitleidenschaft gezogen.", rewards = "Ihr bekommt:\n\n"},
[2989] = {title = "Der Altar von Zul", objective = "Überprüft die Oberfläche des Altars von Zul und kehrt dann zu Greifenmeister Talonaxe zurück.", description = "Scharfschnabel war nicht bei den Witherbarktrollen. Vielleicht haben ihn die Vilebranchtrolle geholt. Geht zum Altar von Zul am Westrand des Territoriums der Vilebranch und sucht nach dem Greifenjungen.", progress = nil, completion = "Scharfschnabel war nicht dort? Das sind schlechte Nachrichten, aber gleichzeitig auch gute...\n\nEs ist gut, dass er nicht am Altar von Zul war, denn die Trolle der Vilebranch sind dafür bekannt, Opferungen durchzuführen.\n\nIch danke Euch für all Eure Hilfe, aber ich fürchte, ich habe noch eine weitaus größere Aufgabe an der Hand.", rewards = "Ihr bekommt:\n\n"},
[2990] = {title = "Thadius Grimshade", objective = "Bringt Scharfschnabels Feder zu Thadius Grimshade in die verwüsteten Lande.", description = "Bringt diese Feder zum Rutengänger Thadius Grimshade. Er verließ vor Jahren Aerie Peak, um sich dunklerem Wissen zuzuwenden, aber in seinem Herzen ist er immer noch ein Wildhammer!\n\nUnd vielleicht können uns seine Talente dabei helfen, Scharfschnabel zu finden.\n\nDiese Feder stammt aus dem Nest, in dem das Greifenjunge schläft. Wenn Ihr sie Thadius gebt, kann er mit etwas Glück seine Rutengangmagie verwenden, um Scharfschnabel zu finden.\n\nViel Glück, <Name>. Ihr werdet Thadius in den verwüsteten Landen finden, im Magierturm der Burg Nethergarde.", progress = "<Name>, Ihr bringt mir ein Geschenk?", completion = "Oh, ja. Diese Feder gehört einem schönen Greifen. Einem, der für große Taten bestimmt ist... wenn er unbeschadet seine Kindheit übersteht.\n\nIhr wollt ihn finden? Dann hört genau zu, tapferer &lt;Klasse&gt;...", rewards = "Ihr bekommt:\n\n"},
[2991] = {title = "Nekrums Medaillon", objective = "Bringt Thadius Grimshade in den verwüsteten Landen Nekrums Medaillon.", description = "Ich werde herausfinden, wo Euer Greif ist, aber erst müsst Ihr etwas für mich tun. Es gibt da einen Troll in Zul'Farrak, Nekrum der Ausweider, der ein Medaillon besitzt, das ich wirklich gern studieren würde. Bringt mir das Medaillon und ich werde meine Kräfte dafür verwenden, Scharfschnabel zu finden.\n\nZul’Farrak ist jenseits des Ozeans, im Westen, in der Wüste von Tanaris.", progress = "Habt Ihr Nekrums Medaillon, <Name>? In ihm liegen Kräfte, die ich gern enträtseln würde.", completion = "Ah, das Medaillon von Nekrum. Man sagt, es habe dem Troll ein unnatürlich langes Leben beschert - zu einem hohen Preis. Ich hoffe, einen Weg zu finden, die Macht des Medaillons zu nutzen und dabei seine... unangenehmen Nebenwirkungen zu vermeiden.\n\nIhr habt mir einen großen Dienst erwiesen, &lt;Name&gt;. Ich werde jetzt meinen Teil der Abmachung einlösen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2992] = {title = "Der Rutengang", objective = "Wartet, bis Grimshade das Rutengangritual durchgeführt hat.", description = "Lasst mir etwas Platz, während ich ein Rutengangritual durchführe. Ich werde die Verbindung zwischen der Feder, die Ihr mir gebracht habt, und ihrem Besitzer herstellen und dann selbst dieser Verbindung zu Scharfschnabel folgen.\n\nZumindest... wenn alles nach Plan verläuft. Wenn nicht, nun... dann schließt Ihr besser die Augen.", progress = nil, completion = "Das Ritual verlief erfolgreich. Ich habe Scharfschnabel gesehen und kann Euch sagen, wie Ihr ihn findet.", rewards = "Ihr bekommt:\n\n"},
[2993] = {title = "Rückkehr ins Hinterland", objective = "Sprecht mit Greifenmeister Talonaxe.", description = "Scharfschnabel wird in einem Käfig hoch oben auf einer Klippe am Gipfel des Jintha’Alor im Hinterland gefangen gehalten. Der Schlüssel zu diesem Käfig ist im Besitz der Hohepriesterin der Vilebranchtrolle, der üblen Priesterin Hexx.\n\nDa. Ich habe meinen Teil erfüllt. Ich wünsche Euch Glück, <Name>.", progress = nil, completion = "Ihr habt mit Grimshade gesprochen? Was hat er gesagt?\n\n... Was? Die Vilebranchtrolle haben Scharfschnabel? Das ist unerträglich! Wir müssen eine Truppe zusammenstellen, um ihn zurückzuholen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[2994] = {title = "Scharfschnabels Rettung", objective = "Kämpft Euch bis zum Gipfel von Jintha’Alor durch, tötet die üble Priesterin Hexx, um an den Schlüssel zu Scharfschnabels Käfig zu kommen, und rettet Scharfschnabel.", description = "Wir müssen Scharfschnabel retten!\n\nKämpft Euch bis zum Gipfel von Jintha’Alor im Herzen des Vilebranchterritoriums vor, holt Euch den Schlüssel zu Scharfschnabels Käfig von der üblen Priesterin Hexx und dann sucht und befreit Scharfschnabel.", progress = nil, completion = "Swiftwind und Keenclaw sind gerade mit ihrem Jungen zurückgekehrt und machen dabei ein Aufhebens wie frisch gebackene Eltern. Sie wiedervereint zu sehen, das treibt selbst diesem alten Zwerg hier ein paar Tränen in die Augen...\n\nWir können Euch gar nicht genug für das danken, was Ihr getan habt, &lt;Name&gt;. Die Greife vom Aerie Peak und ihre Reiter werden Euren Namen für lange, lange Zeit singen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGreifenreiter-SturmhammerGreifenreiter-Gamaschen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[2995] = {title = "Nachrichtenwege", objective = "Oran Snakewrithe in Undercity will, dass Ihr ins Hinterland reist und die Hochtalaufzeichnungen, Hochtalberichte und Hochtalnotizen verbrennt.", description = "Die Quel'Danil-Hütte ist ein Zentrum der Kommunikation für die Hochelfen des Hinterlands. Ihre Botschafter sind damit beschäftigt, Beziehungen zu anderen Völkern zu knüpfen, mit denen sie ihr Wissen über die Trolle der Witherbark teilen, die das Gebiet im südlichen Hinterland bewohnen. Alle Aufzeichnungen betreffs dieses Nachrichtenaustauschs werden in der Hütte aufbewahrt.\n\nWir können es nicht brauchen, wenn die Hochtalelfen Allianzen mit anderen schließen, <Name>.\n\nVernichtet die Hochtaldokumente. Wir müssen ihre Nachrichtenwege niederbrennen... im wahrsten Sinne des Wortes.", progress = nil, completion = "Perfekt, &lt;Name&gt;. Während die Hochtalelfen damit beschäftigt sind, ihre verlorenen Informationen wiederzuerlangen, können wir sie noch weiter abschotten...", rewards = "Ihr bekommt:\n\n"},
[2996] = {title = "Die Suche nach Strahad", objective = "Sprecht mit Strahad Farsan in Ratchet.", description = "Ich habe Euch in der Vergangenheit viele Fertigkeiten beigebracht, aber es ist an der Zeit, dass Euch ein anderer lehrt. Er lebt in Ratchet und sein Name ist Strahad. Er ist ein Mensch, aber lasst Euch deswegen nicht dazu hinreißen, ihn für schwach zu halten. Er mag klein sein, aber er ist auch mächtig. Er kann Euch mächtigere Beschwörungen lehren - ich fühle, dass Ihr dazu bereit seid. Geht nun zu ihm. Er ist in Ratchet... Über der Hafenstadt gleich bei seinem Turm.", progress = nil, completion = "Ein geschäftiger Tag in Ratchet, nicht wahr? Ich liebe es, dem Treiben einer Hafenstadt zuzusehen. So viel Wundersames, so viel Abenteuer... so viel Ignoranz.\n\nSehe ich da Hass in Euren Augen, &lt;Name&gt;? Gut, wir werden daraus einen Vorteil ziehen.", rewards = "Ihr bekommt:\n\n"},
[2997] = {title = "Foliant der Offenbarung", objective = "Sprecht mit Tiza Battleforge in Ironforge.", description = "Hallo, <Name>. Ich weiß, Ihr seid damit beschäftigt, den Leuten von Dun Morogh zu helfen, aber wenn Ihr etwas Zeit habt, könntet Ihr Euch auf den Weg nach Ironforge hinauf machen, um mit einer unserer am meisten Respektierten zu reden: Tiza Battleforge. Zu ihr kommen die jüngeren Paladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von einem erwartet wird.\n\nIhr könnt sie oben in der Halle der Mysterien finden. Falls Ihr noch nie dort wart, das ist im Mystikerviertel. Viel Glück, <Name>.", progress = nil, completion = "Grüße, &lt;Name&gt;. Ich hoffe, das Licht zeigt Euch den wahren Pfad und schützt Euch vor dem Bösen.", rewards = "Ihr bekommt:\n\n"},
[2998] = {title = "Foliant der Offenbarung", objective = "Sprecht mit Duthorian Rall in Stormwind.", description = "Seid gegrüßt, <Bruder/Schwester>. Duthorian Rall, einer unserer einflussreichsten Paladine, hat kürzlich von Euch gesprochen. Ich habe mitbekommen, wie er darüber sprach, dass es an der Zeit sei, dass Ihr ein wenig getestet würdet... Dabei fielen auch einige Komplimente darüber, wie gut Ihr bisher abgeschnitten habt.\n\nWenn ich Ihr wäre, würde ich nach Stormwind gehen und mit ihm sprechen, sobald Ihr Zeit habt. Ich bin sicher, er ist in der Kathedrale des Lichts - dort verbringt er einen Großteil seiner Zeit.", progress = nil, completion = "Ist es nicht wunderschön hier in Stormwind?\n\nEure Ankunft hätte nicht besser sein können, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[2999] = {title = "Foliant der Offenbarung", objective = "Sprecht mit Tiza Battleforge in Ironforge.", description = "Hallo, <Name>. Ich weiß, Ihr seid damit beschäftigt, den Leuten von Dun Morogh zu helfen, aber wenn Ihr etwas Zeit habt, könntet Ihr nach oben gehen, um mit einer unserer am meisten Respektierten zu reden: Tiza Battleforge. Zu ihr kommen die jüngeren Paladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von einem erwartet wird.", progress = nil, completion = "Grüße, &lt;Name&gt;. Ich hoffe, das Licht zeigt Euch den wahren Pfad und schützt Euch vor dem Bösen.", rewards = "Ihr bekommt:\n\n"},
[3000] = {title = "Foliant der Offenbarung", objective = "Sprecht mit Tiza Battleforge in Ironforge.", description = "Hallo, <Name>. Ich weiß, Ihr seid damit beschäftigt, den Völkern Azeroths zu helfen, aber wenn Ihr etwas Zeit habt, solltet Ihr nach Ironforge zurückkehren, um mit einem der am meisten respektierten Paladine Eurer Heimat zu reden: Tiza Battleforge. Zu ihr kommen die jüngeren Zwergen-Paladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von uns allen erwartet wird.\n\nIhr findet sie im Obergeschoss der Halle der Mysterien, die sich im Mystikerviertel befindet.", progress = nil, completion = "Ich grüße Euch und heiße Euch willkommen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[3001] = {title = "Die Suche nach Strahad", objective = "Findet Strahad Farsan in Ratchet.", description = "Ich habe Euch in der Vergangenheit viele Fertigkeiten beigebracht, aber es ist an der Zeit, dass Euch ein anderer lehrt. Er lebt in Ratchet und sein Name ist Strahad. Er ist ein Mensch, aber lasst Euch deswegen nicht dazu hinreißen, ihn für schwach zu halten oder als Euren Feind anzusehen - zumindest vorerst. Er ist mächtig und sollte respektiert werden. Er kann Euch große Beschwörungen lehren, Beschwörungen, für die Ihr, glaube ich, bereit seid. Geht nun zu ihm.\n\nEr ist in Ratchet... Über der Hafenstadt, gleich bei dem Turm dort.", progress = nil, completion = "Ein geschäftiger Tag in Ratchet, nicht wahr? Ich liebe es, dem Treiben einer Hafenstadt zuzusehen. So viel Wundersames, so viel Abenteuer... so viel Ignoranz.\n\nSehe ich da Hass in Euren Augen, &lt;Name&gt;? Gut, wir werden daraus einen Vorteil ziehen.", rewards = "Ihr bekommt:\n\n"},
[3002] = {title = "Die Gordunnikugel", objective = "Bringt die Gordunnikugel zu Uthel’nay in die Dunkeldornen-Lodge in Orgrimmar.", description = "Obwohl ich meinen Feind genau kenne, bin ich ein Krieger, <Name>. Ich kann Euch nicht sagen, über welche Fähigkeiten diese Kugel verfügt.\n\nIch kenne einen Magier in Orgrimmar, der uns mehr über die Kugel sagen können wird. Bringt sie zu ihm.", progress = "Was habt Ihr mir gebracht, <Volk>?", completion = "Faszinierend, &lt;Name&gt;...\n\nDiese Kugel ist sehr mächtig, aber auch sehr gefährlich.", rewards = "Ihr bekommt:\n\n"},
[3022] = {title = "Vorsichtig behandeln", objective = "Bringt die sorgfältig verpackte Kiste zu Erelas Ambersky in das Dorf Rut'theran.", description = "<Name>, ich sehe deutlich, dass Ihr Euch liebend gern meiner noblen Sache zuwenden möchtet. Ja, natürlich könnt Ihr etwas für mich tun!\n\nBringt diese Kiste mit Eiern zu Erelas Ambersky. Das ist ein Druide, der sich um diese Eier kümmert. Er bebrütet sie und bildet dann die jungen Hippogryphe aus. Ihr findet ihn in Teldrassil, in einem kleinen Dorf im Süden namens Rut'theran.", progress = "Eine weitere Lieferung von Curgle, nicht wahr?", completion = "Danke für Eure Hilfe, &lt;Name&gt;. Die Hippogryph-Population würde ohne uns einfach verkümmern. Aber ich denke, Ihr versteht das nur zu gut, schließlich seid Ihr ja selber nach Feralas gereist und habt die Verwüstung der Gordunni dort gesehen.\n\nNun, wie Ihr seht, bin ich sehr beschäftigt; macht Euch lieber gleich auf den Weg.\n\nNochmals danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[3042] = {title = "Trollaushärter", objective = "Bringt 20 Phiolen Trollaushärter zu Trenton Lighthammer in Gadgetzan.", description = "Die Trolle der Sandfury von Zul'Farrak stellen ein Aushärtungsmittel aus Sandstein her, und ich kann dies verwenden, um die von mir hergestellten Waren auszuhärten, ja, so ist es! Von Kennern wird es hoch gepriesen; wenn Ihr mir also einen guten Vorrat dieses Härters bringt, werde ich Euch reich belohnen.\n\nZul'Farrak liegt nordwestlich von Gadgetzan. Viel Glück.", progress = "Bringt Ihr mir den Härter, <Name>?", completion = "Ah, das ist wirklich guter Härter! Und so viel davon! Ich werde tagelang arbeiten können, bis alles aufgebraucht ist!\n\nDanke, &lt;Name&gt;. Bitte, nehmt dies hier als Bezahlung.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3062] = {title = "Dunkles Herz", objective = "Talo Thornhoof im Camp Mojache will das dunkle Herz von Edana Hasskralle.", description = "Edana Hasskralle ist die Königin der Nordschwingen, die in den Ruinen im Westen zu Hause sind. Sie ist das vollkommen Böse; ich habe gehört, dass sie ein Herz aus Kristall hat. Sie ist bar jeglicher Emotionen außer dem Hass, den sie für alle anderen fühlt. Ihr müsst Euch Edana stellen und mir ihr dunkles Herz zurückbringen.\n\nIch habe von einem Horn gehört, das die Harpyien tragen - wenn es bei den Hasskrallensteinen, im nördlichen Teil der Ruinen, geblasen wird, wird die Königin beschworen.\n\nStellt Euch ihre Überraschung vor, wenn es nicht die ihren sind, die auf sie warten, sondern ihr Tod.", progress = "Der Hass, den Edana über das Land verbreitet, muss gestoppt werden.", completion = "Jetzt weiß ich, dass Edana wahrhaft tot ist. Dieses Herz; ich werde es in Erinnerung dessen behalten, was Ihr hier für mich getan habt, &lt;Name&gt;. Danke.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFlügelwappen-HandschuheStarkhorn-Gurt\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[3063] = {title = "Rache an den Nordschwingen", objective = "Talo Thornhoof möchte, dass Ihr 4 Harpyien der Nordschwingen, 4 Wildfedern der Nordschwingen, 4 Windruferinnen der Nordschwingen und 4 Töter der Nordschwingen erschlagt.", description = "Zu meiner Zeit war ich ein erfahrener Jäger. Es gab keine Kreatur, die ich fürchtete. Bis...\n\nIch war draußen im Wald, um nach einem heftigen Kampf meine Klinge zu schärfen, als ich in einen Hinterhalt geriet. Harpyien umzingelten mich, und ich schaffte es kaum, mich in Sicherheit zu bringen.\n\nSelbst heute noch kann ich das Echo ihrer Schreie vernehmen...\n\nDanach war ich nicht mehr derselbe. Aber der Hass kocht in meinem Inneren - ich will Rache, auch noch nach all diesen Jahren.\n\nDie Harpyien der Nordschwingen leben westlich von hier. <Name>, rächt mich.", progress = nil, completion = "Danke, &lt;Name&gt;. Ihr habt dem Geist eines alten Tauren Ruhe gegeben.", rewards = "Ihr bekommt:\n\n"},
[3065] = {title = "Einfache Schrifttafel", objective = "Lest die einfache Schrifttafel und sprecht mit Frang im Tal der Prüfungen.", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, <Name>.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Kriegerlehrer Frang. Er würde gern mit Euch sprechen, wenn Ihr bereit seid. Ihr findet ihn außerhalb des Höhlenbaus, wo er sich in den Schatten verbirgt.", progress = "<Volk>, noch einer zur Verstärkung unserer Reihen. Mir soll's recht sein.\n\nIhr tut Euch wahrscheinlich schwer damit, eine gute Waffe wie beispielsweise eine Axt zu werfen, aber ein Speer ist genauso gut wie jede andere Waffe.\n\nWillkommen im Tal der Prüfungen.", completion = "Ihr werdet diesen Ort sehr geeignet finden für die weitere Ausbildung auf dem Weg zum &lt;Klasse&gt;. Solltet Ihr Fragen haben, seid so frei und fragt jeden hier. Wenn Ihr bereit seid, kommt zurück und lasst mich Euch ausbilden. Ich habe so viele Situationen und Kämpfe gemeistert, wie jeder andere &lt;Klasse&gt; hier im Tal und kann dieses Wissen an Euch weitergeben ... aber das hat seinen Preis.", rewards = "Ihr bekommt:\n\n"},
[3082] = {title = "Geätzte Schrifttafel", objective = "Sprecht mit Jen'shan im Tal der Prüfungen.", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, <Name>.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Jägerlehrerin Jen'shan. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", progress = "Jen'shan sehen einen mächtigen <Klasse> vor sich und die Geister geben Zustimmung.\n\nDer Weg des Jägers sein eine der ältesten Lebensweisen. Die Horde sich hat an uns gewendet, als sie ums Überleben kämpfen müssen auf Azeroth, und uns gebeten, ihnen in die Geheimnisse vieler Dinge einzuweihen. Sie bereits stark waren: stark als Schamanen; stark als Krieger. Aber Weg des Jägers nicht ihrer ... damals.", completion = "Wir ihnen bringen diese Dingens bei und sie uns lehren andere. Wir ein Volk werden... na ja, fast. Wir jetzt sein eine lange Zeit Verbündete. Ihr also denken dran, ihnen helfen. Und Jen'shan denken daran, Euch helfen.\n\nJen'shan Euch lehren dann Fertigkeiten von &lt;Klasse&gt; - lehren Euch gut. Ihr nie vergessen, &lt;Klasse&gt; viel respektiert von Stamm. Ihr werden spielen große Rolle in Zukunft... Ihr das nie vergessen.\n\nWenn Ihr wollen, kommen zu Jen'shan. Sie Euch lehren, so viel sie kann, wenn sie meinen, dass Ihr sein bereit.", rewards = "Ihr bekommt:\n\n"},
[3083] = {title = "Verschlüsselte Schrifttafel", objective = "Lest die verschlüsselte Schrifttafel und sprecht mit Rwag im Tal der Prüfungen.", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, <Name>.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie vom Schurkenlehrer Rwag. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", progress = "Willkommen im Tal der Prüfungen, <Name>. Ihr wärt nicht hier, wenn Ihr meine Schrifttafel nicht erhalten hättet, daher komme ich gleich auf den Punkt.\n\nIch bin Rwag und zuständig für die Ausbildung der Schurken, Diebe und Taschendiebe hier im Tal. Ich bin derjenige, an den sich die Hand wendet, wenn Ihr nicht bereit seid für das, was auf Euch zukommt. Aber keine Sorge, die Hand kontrolliert nicht alles, was Ihr tut - es wäre jedoch ratsam, mit ihnen zusammenzuarbeiten, sollten sie je Bedarf für Eure Talente haben.", completion = "Bis dahin seid Ihr unter meiner Federführung. Ich werde Euch die Tricks lehren, wie manche dazu sagen. Wenn Ihr meint, dass Ihr vorbereitet seid, kommt zu mir und ich werde Eure Ausbildung fortsetzen. Bis dahin übt Eure Fertigkeiten und verfeinert sie auf's Beste. Man kann nie wissen, wann man selbst die unbedeutendste Fähigkeit benötigt.", rewards = "Ihr bekommt:\n\n"},
[3084] = {title = "Mit Runen beschriftete Schrifttafel", objective = "Sprecht mit Shikrik im Tal der Prüfungen.", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, <Name>.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Schamanenlehrerin Shikrik. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", progress = "Ah, willkommen, <Name>. Schön, dass Ihr eingetroffen seid. Meine Tage sind so lang und geschäftig geworden, mit so vielen Schülern, die ich derzeit lehre - aber der Besuch von einem der Euren erfüllt mich mit tiefer Befriedigung - ich erinnere mich an die Tage, als ich von einem Eurer Schamanen unterrichtet wurde.", completion = "Wie Ihr möglicherweise wisst, geben uns die Elemente unsere Macht. Feuer, Erde, Wasser und Luft - das sind unsere Werkzeuge.\n\nUnsere Kraft erhalten wir von den Geistern unserer Vorfahren. Wir sind die Anführer unseres Volkes. Was Thrall für die Horde ist, werden wir für die Dörfer und Städte sein, die wir aufsuchen. Sie werden sich um Rat und Schutz an uns wenden. Ihr müsst häufig trainieren, um besser vorbereitet zu sein. Wenn Ihr fühlt, dass Ihr mächtiger geworden seid, kommt zu mir und ich werde Euch lehren, was ich vermag.", rewards = "Ihr bekommt:\n\n"},
[3085] = {title = "Geheiligte Schrifttafel", objective = "Lest die geheiligte Schrifttafel und sprecht mit Ken'jai außerhalb des Höhlenbaus im Tal der Prüfungen.", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, <Name>.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie vom Priesterlehrer Ken'jai. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", progress = "So Ihr haben hierher geschafft... gut, gut! Geister mir gesagt, Ihr Ken'jai bald aufsuchen. Lasst mich einer der Ersten sein, der Euch im Tal der Prüfungen willkommen heißen. Diese Ort nicht sein Zuhause für lang, aber während es ist, warum nicht machen das Beste daraus.", completion = "Wenn Ihr Euch prüfen, Ihr werden finden, dass Ihr mehr und mehr Kontrolle über die Geister haben - Ihr können sie beschwören für immer größere Dinge... und da kommen der alte Ken'jai ins Spiel. Ihr kommen und reden mit dem alten Ken'jai, wenn Ihr fühlen, dass bereit sein. Wenn Geister zustimmen, dann wir lernen mächtigere Fähigkeiten... aber nur, wenn Geister zustimmen.\n\nGehen jetzt, reden mit anderen im Tal. Reden später wieder mit mir.", rewards = "Ihr bekommt:\n\n"},
[3086] = {title = "Glyphen-Schrifttafel", objective = "Lest die mit Glyphen versehene Schrifttafel und sprecht mit Mai'ah beim Eingang zum Höhlenbau im Tal der Prüfungen.", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, <Name>.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Magierlehrerin Mai'ah. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", progress = "Ihr Mai'ah schon viel Freude bereiten, <Name>. Das sein gut. Ihr zollen Mai'ah Respekt, und Mai'ah vielleicht auch Euch zollen Respekt. Aber jetzt genug davon, Ihr sein hier, um über Magie zu lernen, nicht um Mai'ah reden zu hören.\n\nEs geben nur eins, was Mai'ah Euch nicht lehren kann über Magie, <Name> - und das sein, wie zu stoppen Verderbnis.", completion = "Ihr werden sein eines der mächtigsten Lebewesen auf dem Planeten, &lt;Name&gt;..., daran bestehen kein Zweifel. Und jeder wird es wissen... und gut wissen!\n\nAber Ihr müssen wachsam sein! Weil sein kein Orc oder Elf oder Zwerg, vor dem Ihr fürchten müsst Euch..., es sein Dinge, die Ihr nicht sehen können. Magie können sein mächtig. Euch Dinge tun lassen, die Ihr nicht tun wollen. Euch denken lassen, Ihr sein mächtiger als Ihr in Wirklichkeit sein. Haben Geduld. Seien schlau.\n\nWenn Ihr denken, dass bereit sein für Unterweisung, kommen zurück zu Mai'ah. Sie Euch lehren, was Ihr wissen müssen, kein Problem.", rewards = "Ihr bekommt:\n\n"},
[3087] = {title = "Geätztes Pergament", objective = "Lest das geätzte Pergament und sprecht mit Jen'shan im Tal der Prüfungen.", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, <Name>.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von der Jägerlehrerin Jen'shan. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", progress = "Ah, da Ihr sein schließlich. Gut. Jen'shan Euch haben erwartet.\n\nViele meinen, das sein ein einfacher Weg, aber Jen'shan Euch sagen, dass nicht stimmen. Die Beherrschung der Bestien von Durotar und darüber hinaus erfordern genauso viel Fertigkeit wie die Beherrschung der arkanen Künste oder das Reden mit unseren Vorfahren.\n\nDas Abfeuern eines Bogens oder eines Gewehres mögen Euch nicht so gefährlich erscheinen wie das Wirken eines Zaubers, es seien jedoch genauso gefährlich für Euren Feind.", completion = "Wenn wir fertig mit reden, Ihr solltet mit anderen Einwohnern des Tals reden. Sie Euch werden bitten, Dinge für sie zu tun... Dinge, mit denen Eure Fertigkeiten geprüft werden und die Euch einige der Gefahren dieses Landes aufzeigen.\n\nWenn Ihr erfahrener und weiser werdet, Ihr werden brauchen Jen'shan, um Euch bessere Techniken und Fertigkeiten zu zeigen. Besucht Jen'shan oft. Ich werde Euch dann mitteilen, was ich Euch lehren kann.", rewards = "Ihr bekommt:\n\n"},
[3088] = {title = "Verschlüsseltes Pergament", objective = "Lest das verschlüsselte Pergament und sprecht mit Rwag im Tal der Prüfungen.", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, <Name>.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Schurkenlehrer Rwag. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", progress = "Schhht, nicht so laut. Ich traue Nartok dort drüben nicht. Mit jedem, der sich tiefer in einer Höhle verbergen muss als ich, ist nicht zu spaßen.\n\nIch vermute, Ihr hattet keine Probleme, Euch zurecht zu finden?", completion = "Jetzt, wo Ihr wisst, wo ich mich aufhalte, solltet Ihr Folgendes wissen: Die Shattered-Hand haben mich beauftragt, Euch zu suchen. Sie wollen, dass ich Euch unterweise und Euch über alles informiere, was sie brauchen können. Selbst falls Ihr noch nicht daran interessiert seid, ihnen zu helfen - obgleich Ihr ein Narr wärt, dies nicht zu tun -, werde ich tun, was immer ich kann, um Euch zu unterweisen ... natürlich gegen eine geringe Gebühr. Kommt zu mir zurück, wann Ihr meint bereit zu sein - und ich werde sehen, welche Lektionen Ihr lernen könnt.", rewards = "Ihr bekommt:\n\n"},
[3089] = {title = "Mit Runen beschriftetes Pergament", objective = "Lest das mit Runen beschriebene Pergament und sprecht mit Shikrik im Tal der Prüfungen.", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, <Name>.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von der Schamanenlehrerin Shikrik. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", progress = "Ihr seid also angekommen. Ich habe mich schon gefragt, ob Ihr wohl auftauchen würdet. Ich habe das Pergament bereits vor einiger Zeit geschickt und war mir nicht sicher, ob es auch angekommen ist.\n\nAber genug geplaudert... Ihr seid hier, weil Ihr auserwählt seid, auserwählt, das spirituelle Leben Eures Volkes zu leiten.", completion = "Ihr werdet der Kanal sein, über den unsere Vorfahren kommunizieren. Ihr werdet die Macht der Elemente zu Eurer Verfügung haben. Die Zerschlagung Eurer Feinde wird ein Kinderspiel sein; die Heilung Eurer Verbündeten so leicht wie das Atmen sein. Behaltet diese Dinge im Gedächtnis, während Ihr neue Herausforderungen meistert, und kehrt so oft zu mir zurück, wie Ihr wollt. Ich werde hier sein, Euch neue Zauber zu lehren, und Euch auf den richtigen Weg bringen, wenn Ihr bereit seid.", rewards = "Ihr bekommt:\n\n"},
[3090] = {title = "Besudeltes Pergament", objective = "Lest das besudelte Pergament und sprecht mit Nartok im Höhlenbau im Tal der Prüfungen.", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, <Name>.\n\nIch versuche normalerweise, jedweden Kontakt mit Hexenmeistern zu vermeiden, aber ich glaube, Ihr solltet es lesen, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von Eurem neuen Lehrer Nartok. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", progress = "Endlich seid Ihr gekommen... und so diskret! Gut.\n\nUnsere Welt ist voller Narren, <Name>. Selbst der mächtige Thrall hat mehr Fehler als die meisten erkennen können. Er wendet der Macht, durch die dieses Land ganz unser werden kann, den Rücken zu! Wir sind nicht dasselbe Volk, das einst von den Kreaturen aus dem Nether manipuliert und benutzt wurde. Wir sind ein eigenes Volk. Wir sind stolz... und wir sind stark.", completion = "Und nun seid auch Ihr unseren Reihen beigetreten. Versteht mich nicht falsch, &lt;Name&gt;. Nur, weil Ihr Zugang zur Macht habt, auf die viele neidisch sind, bedeutet dies nicht, dass Ihr einfach akzeptiert werdet. Thrall lässt einen unserer Art nach Orgrimmar, weil wir noch immer seinesgleichen sind - er kann uns nicht den Rücken zuwenden oder wir würden ebenso pathetisch werden wie die Menschen, die ihn versklavten. Ich sage nur: seid vorsichtig. Ihr mögt mächtig sein, seid Ihr jedoch tollkühn, seid Ihr so gut wie tot.\n\nWenn Ihr eine Unterweisung im Zaubern benötigt, sucht mich wieder auf.", rewards = "Ihr bekommt:\n\n"},
[3091] = {title = "Einfache Notiz", objective = "Lest die einfache Nachricht und sprecht mit Harutt Thunderhorn im Camp Narache.", description = "Gerade eben fragte eine Botin nach Euch, <Name>. Ich glaube, sie wurde vom Kriegerlehrer Harutt geschickt. Wenn diese Nachricht von Harutt ist, würde ich sie schnellstens lesen.", progress = "Ah, <Name>, Ihr seid endlich angekommen. In meiner Nachricht habe ich nicht gelogen, <Name>. Wir sind von besonderer Art, nicht unähnlich den Druiden oder Schamanen unseres Stammes. Ihr seid ebenso wichtig. Wir sind die, die zur Verteidigung unserer Grenzen gerufen werden, zur Jagd auf den Zentauren und um in den Krieg zu ziehen.", completion = "Jeder von uns spielt in unserem Stamm eine Rolle. Jeder von uns muss auch dieselben Riten durchlaufen. Lasst Euch niemals von Eurem Stolz etwas anderes sagen.\n\nIch verbleibe hier, um neue &lt;Klasse&gt; auszubilden, die Ruhm in Schlachten suchen und den Wegen der ältesten unserer Vorfahren folgen. Wenn Ihr Euch bereit fühlt, kommt wieder zu mir und ich werde tun, was ich kann, um Euch weiter auszubilden. Jetzt geht mit dem Segen des Stammes, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[3092] = {title = "Geätzte Notiz", objective = "Lest die geätzte Nachricht und sprecht mit Lanka Farshot in Red Cloud Mesa.", description = "Gerade eben fragte eine Botin nach Euch, <Name>. Ich glaube, sie wurde vom Jägerlehrer Lanka geschickt. Wenn diese Nachricht von Lanka ist, würde ich sie schnellstens lesen.", progress = "Willkommen im Camp Narache, <Name>. Ich höre viel Gutes über Euch. Euer Geschlecht ist stark und viele der Ältesten halten Eure Fertigkeiten bereits für gut. Aber das wird sich in den Prüfungen zeigen.\n\nDie Ebenen von Mulgore werden für einige Zeit Euer Zuhause sein - Ihr solltet Euch bemühen, sie so gut wie möglich kennen zu lernen. Eines Tages werdet Ihr in unbekanntes Land aufbrechen, um größere Fertigkeiten zu erwerben. Dann müsst Ihr bereit sein.", completion = "Und es ist meine Aufgabe sicherzustellen, dass Ihr bereit seid, indem ich Euch die Grundlagen unserer Profession lehre - Euer Tier zu zähmen, Euer Gewehr abzufeuern und viele andere Fertigkeiten, die Ihr brauchen werdet.\n\n&lt;Klasse&gt; sind ein starker Teil unserer Tradition und Geschichte, &lt;Name&gt;. Ihr tätet gut daran, Euch zu erinnern, wie wichtig Ihr für den Stamm seid. Ihr werdet respektiert und verehrt, wenn Ihr unserem Volk gut dient.", rewards = "Ihr bekommt:\n\n"},
[3093] = {title = "Mit Runen beschriftete Notiz", objective = "Lest die mit Runen beschriftete Nachricht und sprecht mit Meela Dawnstrider im Camp Narache.", description = "Gerade eben fragte eine Botin nach Euch, <Name>. Ich glaube, sie wurde von der Schamanenlehrerin Meela geschickt. Wenn diese Nachricht von Meela ist, würde ich sie schnellstens lesen.", progress = "So schnell, wie Wasser vom Himmel fällt, seid Ihr hier eingetroffen. Eure Eile freut mich. Sie bedeutet, dass Ihr die Bedeutung unseres Treffens versteht und auch um die Bedeutung Eures Hierseins wisst. Ich bin kein Anführer, aber ich verstehe die Elemente und ich kann mit den Geistern unseres Volkes reden. Ich werde Euch lehren, es mir gleichzutun.", completion = "In den kommenden Tagen werden wir uns häufig sehen. Jedes Mal verlasst Ihr mich ein wenig mächtiger... ein wenig besser vorbereitet. Wie die ewige Flamme wird Euer Geist hell und heiß lodern.\n\nGeht jetzt, &lt;Name&gt;. Geht und unterzieht Euch den Prüfungen. Ich werde hier sein, wenn Ihr mich braucht.", rewards = "Ihr bekommt:\n\n"},
[3094] = {title = "Tiefgrüne Notiz", objective = "Lest die tiefgrüne Notiz und sprecht mit Gart Mistrunner im Camp Narache.", description = "Gerade eben fragte eine Botin nach Euch, <Name>. Ich glaube, sie wurde vom Druidenlehrer Gart geschickt. Wenn diese Nachricht von Gart ist, würde ich sie schnellstens lesen.", progress = "Ihr seid gekommen. Das ist gut. In letzter Zeit sind die Geister unserer Vorfahren in ganz Mulgore und Umgebung rastlos, ich kann jedoch nicht sagen, warum. Es wird stets Eure Pflicht sein, zu lernen, den Naturgeistern zuzuhören und als ihr Avatar zu fungieren. Denkt stets daran.", completion = "Trotz unseres Bündnisses mit den Nachtelfen solltet Ihr kein herzliches Willkommen von ihnen erwarten. Ihr Stolz begrenzt noch immer ihre Sicht, aber das ist nicht unser Problem. Die Lehren der Erdenmutter sind alles, um was Ihr Euch kümmern müsst, und ich werde Euch lehren, was ich weiß, während Eure Weisheit zunimmt.\n\nSucht mich oft auf, &lt;Name&gt;. Ihr werden feststellen, dass die Erdenmutter Ihren hingebungsvollsten Anhängern unglaubliche Fähigkeiten gewährt.", rewards = "Ihr bekommt:\n\n"},
[3095] = {title = "Einfache Rolle", objective = "Lest die einfache Schriftrolle und sprecht mit Dannal Stern in Deathknell.", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Kriegerlehrers Dannal zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", progress = "Ah, Ihr seid also eingetroffen. Gut. Ich habe mitbekommen, dass einige andere dem 'Tod' entrinnen konnten und in die Stadt flohen. Vielleicht zahlt sich diese Widerstandsfähigkeit künftig ebenfalls aus.\n\nIhr könnt Sylvanas für Eure Freiheit danken... die Freiheit von Geist und Körper. Obgleich Ihr noch immer von der Seuche und ihren Auswirkungen heimgesucht seid, steht es Euch jetzt frei, zu kommen und zu gehen wie es Euch beliebt.", completion = "Ich werde hier sein, Euch zu lehren, während Ihr an Erfahrung gewinnt... sucht mich so oft auf, wie Ihr mögt. Ich verlange eine minimale Gebühr, Ihr werdet jedoch alles, was ich Euch lehren kann, lohnenswert finden.\n\nGeht jetzt und prüft Eure Fertigkeiten. Während Ihr an Erfahrung gewinnt, werden sich Euch viele neue Dinge offenbaren; einige davon kann ich hier jetzt nicht mit Euch besprechen. Wisset nur, dass Sylvanas künftig &lt;Klasse&gt; mit Kraft wie Euresgleichen brauchen wird. Ihr werdet das Rückgrat unserer Rettung sein. Vergesst das nicht.", rewards = "Ihr bekommt:\n\n"},
[3096] = {title = "Verschlüsselte Rolle", objective = "Lest die verschlüsselte Schriftrolle und sprecht mit David Trias in Deathknell.", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Schurkenlehrers David Trias zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", progress = "Ihr habt es also hierher geschafft? Gut, wir brauchen mit der Zeit immer mehr Schurken. Die Schattenpirscher werden wahrscheinlich versuchen, Euch zu finden, wenn die Zeit reif ist; seht also zu, dass Ihr nicht in etwas hineingeratet oder etwas tut, was Ihr später bereut. Sie brauchen fähige Agenten ... keine Taschendiebe und Narren.", completion = "Ich habe die meiste Zeit hier im Gasthaus verbracht, auf neue Gesichter geachtet und nach möglichen künftigen Aspiranten Ausschau gehalten. Haltet die Nase frei und ich tue, was ich kann, um Euch einige Dinge zu lehren. Kommt einfach zu mir zurück, wann immer Ihr wollt und wir werden sehen, ob Ihr bereit seid für eine neue Fertigkeit oder zwei.", rewards = "Ihr bekommt:\n\n"},
[3097] = {title = "Geheiligte Rolle", objective = "Lest die geheiligte Schriftrolle und sprecht mit dem dunklen Kleriker Duesten in der Kirche von Deathknell.", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Priesterlehrers Duesten zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", progress = "Ah, so kommt zwischen Feuer, Seuche, Aufständen und Schlimmerem ein Mal mehr ein 'Getreuer' an meine Tür. Nun, seid gegrüßt, <Klasse>. Und lasst mich Euch kurz ein oder zwei Dinge zu erklären, bevor Ihr Euch auf die Suche nach dem macht, was immer Euch im Leben antreibt: Das Heilige Licht betrifft Euch nicht länger, die Geister Eurer Vorväter sind nurmehr schöne Geschichten und die Kreaturen aus dem Nether wollen Euch nicht.\n\nVersteht Ihr mich so weit?", completion = "Ihr müsst nur eins wissen: Wir haben durch schiere Willenskraft überlebt. Es ist der Glaube an uns selbst, der uns von anderen unterscheidet, und mit unserer Macht werden wir große Veränderungen in gesamt Azeroth herbeiführen. Die Schwachen werden auf Euch angewiesen sein. Die Leprakranken werden Euch Lord nennen. Und die Ignoranten werden Euch um Führung ersuchen. Es ist meine Pflicht sicherzustellen, dass Ihr die nötigen Werkzeuge habt, sodass Ihr bereit seid, wenn die Zeit gekommen ist. Sucht mich auf, während Ihr an Erfahrung gewinnt. Ich werde Euch lehren, wie Ihr noch mächtiger werdet, wenn Ihr dazu bereit seid.", rewards = "Ihr bekommt:\n\n"},
[3098] = {title = "Glyphen-Rolle", objective = "Lest die mit Glyphen versehene Schriftrolle und sprecht mit Isabella in der Kirche von Deathknell.", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel der Magielehrerin Isabella zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", progress = "Ich wusste, Ihr würdet zu mir kommen, <Name>. Nicht, weil Ihr nicht den Willen habt, Eurem eigenen Weg zu folgen, sondern weil wir verwandte Geister sind. Beide haben wir Schmerz gefühlt. Beide haben wir gelitten. Und jetzt wollen wir die Macht, um uns das zurückzuholen, von dem wir wissen, dass es unser ist: dieses Land, unser Leben, unser Schicksal. Aber Ihr müsst noch immer viel lernen.", completion = "Ihr müsst oft zu mir zurückkehren, wenn Ihr mächtig genug werden wollt, um unsere Gegner zu vernichten. Die Regeln der Magie gelten noch immer für Euch, &lt;Name&gt;. Ihr werdet noch immer feststellen, dass Euch die Verderbnis folgt, wie hungrige Wölfe in der Nacht. Ihr werdet ihre sanften Berührungen fühlen und feststellen, dass sie einer Sucht ähnelt, einem alten Liebhaber, dem es noch immer verlangt, an Eurer Seite zu sein. Ihr könnt diese Dinge jedoch abschütteln. Diese Dinge werden Euch nur kontrollieren, wenn Ihr dies zulasst.\n\nGeht jetzt und kehrt zurück, wenn Ihr mächtiger geworden seid.", rewards = "Ihr bekommt:\n\n"},
[3099] = {title = "Besudelte Rolle", objective = "Lest die besudelte Schriftrolle und sprecht mit Maximillion in Deathknell.", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Hexenmeisterlehrers Maximillion zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", progress = "Ich heiße Euch willkommen, Bruder. Ich wusste, Ihr würdet kommen. Es war nur eine Frage der Zeit.\n\nWas ich sagte, hat Euch interessiert, nicht wahr? Es schlug eine Saite an... etwas in Euch wusste, dass meine Worte wahr waren. Gut.\n\nDoch wisset dies: Ich bin kein Verräter an Sylvanas. Wenn überhaupt, würde sie meine Worte zu schätzen wissen, wenn man bedenkt, dass es ihre eigenen Überzeugungen waren, die die Verlassenen in die Situation gebracht haben, in der sie sich jetzt befinden.", completion = "Ich sprach davon, dass ein Sklave immer ein Sklave bleibt, ungeachtet des Meisters. Erinnert Ihr Euch? Wir beide wissen, dass es diese Art von Kontrolle - diese Art von Macht - ist, die uns jetzt antreibt. Wir wollen, dass uns Kreaturen dienen. Wir wissen, dass wir mächtiger sind und mehr Respekt verdienen als andere uns zollen... Und somit streben wir jetzt danach, uns den Respekt zu nehmen.\n\nIch werde in diesem Kampf Euer Verbündeter sein - im Kampf um unsere eigene Freiheit. Die Freiheit, unsere eigenen Zugehörigkeiten wählen zu können. Wenn Ihr bereit seid, kommt zurück zu mir und ich werde Euch alles lehren, was ich weiß.", rewards = "Ihr bekommt:\n\n"},
[3100] = {title = "Einfacher Brief", objective = "Lest den einfachen Brief und sprecht mit Llane Beshere in der Abtei von Nordhain.", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, <Name>. Es scheint sich um einen versiegelten Brief mit den Insignien von Llane, unserem örtlichen Kriegerlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", progress = "Ah, Ihr habt meinen Brief erhalten, <Name>... gut.\n\nIn letzter Zeit gab es einen Zustrom von Kriegern in Elwynn - was gut ist für Stormwind, jedoch schlecht für die Kobolde und Defias in dieser Gegend.", completion = "Messt Euch mit anderen, macht Euch mit den Gegebenheiten dieses Landes vertraut und kommt zu mir zurück, wann immer Ihr weitere Unterweisung wünscht. Ich werde hier sein, bei Tag und Nacht.\n\nDie Ritter der Silberhand haben viel geleistet und dies zu einem recht sicheren Ort gemacht; wenn Ihr aber andere Einwohner trefft, werdet Ihr wohl feststellen, dass sie alle Probleme haben, bei denen sie ein wenig Hilfe gebrauchen könnten - Hilfe, die ihnen ein &lt;Klasse&gt; gewähren kann. Viel Glück.", rewards = "Ihr bekommt:\n\n"},
[3101] = {title = "Geweihter Brief", objective = "Lest den geweihten Brief und sprecht mit Bruder Sammuel in der Abtei von Nordhain.", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, <Name>. Es scheint sich um einen versiegelten Brief mit den Insignien von Bruder Sammuel, unserem örtlichen Paladinlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", progress = "Endlich! Wir stehen uns von Angesicht zu Angesicht gegenüber, Bruder und Bruder. Ich heiße Euch willkommen in Nordhain. Hier wird während der kurzen Zeit Euer Zuhause sein, in der Ihr lernt, wie die Dinge laufen, aber wisset, dass Stormwind nicht weit von hier ist und dass Euer Weg Euch über kurz oder lang dorthin führen wird. Bis dahin, habt Geduld... Ritter der Silberhand.", completion = "In der Zwischenzeit solltet Ihr einige andere Dinge wissen. Ihr seid ein Symbol für viele hier im Land - verhaltet Euch entsprechend. Das Heilige Licht leuchtet in Euch und dies ist sowohl für Eure Verbündeten als auch Eure Feinde offensichtlich.\n\nZudem, wenn Ihr an Weisheit und Macht gewinnt, müsst Ihr trainieren, um neue Fähigkeiten zu erlernen. Und da komme ich ins Spiel. Wenn Ihr denkt, dass Ihr genug Erfahrung hier in Nordhain gesammelt habt, kommt zu mir zurück und ich werde Euch die Dinge lehren, zu denen Ihr meiner Meinung nach bereit seid. Viel Glück... &lt;Klasse&gt;!", rewards = "Ihr bekommt:\n\n"},
[3102] = {title = "Verschlüsselter Brief", objective = "Lest den verschlüsselten Brief und sprecht mit Jorik Kerridan im Stall hinter der Abtei von Nordhain.", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, <Name>. Es scheint sich um einen versiegelten Brief mit den Insignien von Jorik, einem unserer örtlichen Lehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", progress = "Ihr habt es in einem Stück hierher geschafft und es sieht so aus, als ob Ihr nicht von zu vielen Leuten gesichtet wurdet. Das reicht mir. Ich mag es nicht, zu viel Aufmerksamkeit auf mich hier zu lenken... ich bin gern für mich und unbehelligt. Ich bin sicher, Ihr versteht mich.\n\nGab es Ärger bisher? Nicht? Freut mich zu hören. Das wird sich jedoch schon bald ändern.", completion = "Ihr werdet feststellen, dass es eine Reihe von Gruppierungen für Eure Fertigkeiten gibt, &lt;Name&gt;. Abenteurer, SI:7... sogar die Bruderschaft der Defias hätte gern einen Spion oder zwei in Stormwind. Aber vergesst nicht, es ist Eure Entscheidung. Lasst Euch nicht zu etwas drängen, was Ihr nicht tun wollt! Darüber hinaus halten wir alle Trümpfe in der Hand... zumindest werden wir dies, bevor das Spiel vorbei ist. Versteht Ihr, was ich meine?\n\nEgal, ich wollte mich nur kurz vorstellen und Euch wissen lassen, dass ich hier bin, wenn Ihr Unterweisungen wünscht. Ihr seid jederzeit gern gesehen.", rewards = "Ihr bekommt:\n\n"},
[3103] = {title = "Geheiligter Brief", objective = "Lest den geheiligten Brief und sprecht mit Priesterin Anetta in der Abtei von Nordhain.", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, <Name>. Es scheint sich um einen versiegelten Brief mit den Insignien der Priesterin Anetta, unserer örtlichen Priesterlehrerin, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", progress = "Ah, endlich seid Ihr gekommen. Ich wusste, Ihr würdet Euren Weg zu mir finden. Das Heilige Licht scheint auf Euch und den Weg, den Ihr gewählt habt. Die Zeiten sind hart - die Brennende Legion ist auf Azeroth noch immer allgegenwärtig, ganz Kalimdor sucht neue Wege, um sich vor den eigenen Widerwärtigkeiten zu schützen, und es ist an Euch, so vielen wie möglich zu helfen.", completion = "Während Ihr an Erfahrung gewinnt, sucht mich auf und ich werde tun, was in meiner Macht steht, um Euch mein Wissen zu vermitteln. Bis dahin, geht, haltet das Mitgefühl in Eurem Herzen und lasst Euch von der Weisheit leiten. Denkt daran, die Welt wird nur dann zu einem besseren Ort, wenn Ihr sie dazu macht.", rewards = "Ihr bekommt:\n\n"},
[3104] = {title = "Glyphen-Brief", objective = "Lest den mit Glyphen versehenen Brief und sprecht mit Kheldon Bremen in der Abtei von Nordhain.", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, <Name>. Es scheint sich um einen versiegelten Brief mit den Insignien von Kheldon, unserem örtlichen Magierlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", progress = "Hallo, <Name>. Ich bin Kheldon. Kann ich etwas für Euch tun?", completion = "Haha, ich wusste, meine Notiz würde Euch nicht von Eurem Weg abbringen. Ihr seid also bereit, hm? Bereit, Euer Schicksal anzunehmen? Bereit, die Götter herauszufordern und alle anderen Kräfte, die zwischen Euch und dem Erlangen von Wissen und Macht stehen?\n\nIch werde Euch nicht belügen, &lt;Name&gt;, Ihr werdet ebenso gefürchtet wie respektiert werden. Aber wisset auch dies, ich werde hier sein für Euch, wenn Ihr Unterweisung benötigt. Sucht mich einfach auf, während Ihr mächtiger werdet.", rewards = "Ihr bekommt:\n\n"},
[3105] = {title = "Besudelter Brief", objective = "Lest den besudelten Brief und sprecht mit Drusilla La Salle nahe der Abtei von Nordhain.", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr von den Koboldlagern zurückgekehrt seid, <Name>. Es scheint sich um einen versiegelten Brief mit den Insignien von Drusilla, einer unserer örtlichen Lehrerinnen, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", progress = "Ah, Ihr seid eingetroffen, und das keinen Moment zu früh, <Name>. Einige Wachen waren gerade da und sahen mich sehr neugierig an... armselige sterbliche Geschöpfe.", completion = "Während Ihr mächtiger werdet, werdet Ihr in Versuchungen geraten - Ihr müsst stets daran denken die Kontrolle zu bewahren. Ich werde Euch nicht belügen - Verderbnis kann jeden Ausübenden der arkanen Künste ereilen, besonders diejenigen, die sich mit den Kreaturen des wirbelnden Nethers beschäftigen. Habt Geduld und seid vorsichtig... Aber nehmt Euch in Euren Ambitionen nicht zu stark zurück.\n\nWenn Ihr mächtiger werdet, sucht mich erneut auf und ich werde Euch mehr über unsere Lebensart lehren.", rewards = "Ihr bekommt:\n\n"},
[3106] = {title = "Einfache Rune", objective = "Lest die einfache Rune und sprecht mit Thran Khorman im Coldridgetal.", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Kriegerlehrer Thran. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", progress = "Verdammt, ist das kalt heute, was? Es scheint, als ob der Schnee nie schmelzen würde, <Name>.\n\nIhr habt es wahrscheinlich längst gemerkt, dass jetzt Gnome in unserer Stadt leben. Und das nur, weil sie sich selbst das Dach überm Kopf weggesprengt haben. Erzählt das nicht weiter, aber ich kann es ihnen nicht mal verübeln ... wenn Ironforge so schlimm mit Dunkeleisenzwergen oder ähnlichen Kreaturen verseucht wäre, würde ich auch zu Sprengstoff greifen.", completion = "Es gibt noch mehr, was Ihr wahrscheinlich auch sehen werdet: Zwerge, die im Kampf Magie statt Gewehre einsetzen. Einige von uns beten das Heilige Licht an, wie einige der Menschen, und nicht zu vergessen, einige der Troggs. Ihr werdet später mehr über sie erfahren. Was Ihr jedoch wissen müsst, ist, dass ich da bin, um Euch zu helfen.\n\nIch werde Euch lehren, ein richtiger &lt;Klasse&gt; zu werden. Jedes Mal, wenn Ihr meint, mehr Unterweisung zu brauchen, kommt Ihr zu mir und ich werde sehen, was ich tun kann.", rewards = "Ihr bekommt:\n\n"},
[3107] = {title = "Geweihte Rune", objective = "Lest die geweihte Rune und sprecht mit Bromos Grummner im Coldridgetal.", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Paladinlehrer Bromos. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", progress = "Ihr habt es also hierher geschafft! Und das keine Sekunde zu früh. Es gibt viel zu tun im Coldridgetal und in der Umgebung. Ich werde Eure Hilfe brauchen, so wie Ihr die meine!\n\nIhr seid nun ein Ritter der Silberhand, zeigt Euch der Aufgabe gewachsen.", completion = "Die Menschen haben uns viel über das Heilige Licht gelehrt und darüber, wie wichtig der Orden für sie ist... und für den Schutz von ganz Azeroth. Wir haben großen Respekt vor der Bedeutung der Tradition und davor, wie nur ein einziger, eine Opferung, den Unterschied bewirken kann zwischen Schmerz und Erlösung.\n\nWir zwei werden eine Weile zusammenarbeiten. Kommt zu mir zurück, wann immer Ihr meint bereit zu sein, und wir werden ein bisschen üben. Wir können Euch ja nicht unvorbereitet in die Welt hinausziehen lassen, oder?", rewards = "Ihr bekommt:\n\n"},
[3108] = {title = "Geätzte Rune", objective = "Lest die geätzte Rune und sprecht mit Thorgas Grimson im Coldridgetal.", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Jägerlehrer Thorgas. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", progress = "Ihr habt's also hierher geschafft! Das ist eine gute Nachricht! Musstet mich wohl auch nicht verfolgen, um den Ort hier zu finden. Ha-ha!\n\nUnsere Profession ist recht traditionslastig, <Name>. Die Gegebenheiten des Landes lernen. Einen Bären durch die Berge verfolgen lernen. Selbst das einfache Überleben, nur mit Hilfe des Verstandes, erfordert viel Mut und Schläue. Meint Ihr, dass Ihr dazu fähig seid?", completion = "Eines solltet Ihr niemals vergessen: Ihr müsst die Welt respektieren, in der Ihr lebt. Die Wildtiere, die den Kampf an Eurer Seite wählen; den Glanz Eurer Waffe; das Gewicht Eurer Munition; das Beißen eines schneidenden Windes; all diese Dinge müsst Ihr wie Eure Westentasche kennen.\n\nIch werde alles tun, was ich vermag, um Euch zu helfen; die meiste Arbeit müsst Ihr jedoch allein leisten. Sucht mich auf, wann immer Ihr meint, bereit zu sein. Ich bilde Euch aus, wenn ich kann!", rewards = "Ihr bekommt:\n\n"},
[3109] = {title = "Verschlüsselte Rune", objective = "Lest die verschlüsselte Rune und sprecht mit Solm Hargrin im Coldridgetal.", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Schurkenlehrer Solm. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", progress = "Ihr habt es hierher geschafft! Großartig!\n\nWir bemerken in letzter Zeit verstärkte Aktivitäten, daher bin ich froh, ein weiteres Mitglied des Ironforgeklans in unseren Reihen zu wissen. Für meinen Geschmack beschäftigen sich zu viele von uns mit dem Arkanen und Göttlichen. Nichts gegen sie und ihren Glauben, aber es geht doch nichts über eine kalte Klinge in der Hand und einen Schatten, der einen vor dem Licht schützt, wenn Ihr wisst, was ich meine?", completion = "Wie dem auch sei, wenn Ihr Euch in Coldridge umseht, werdet Ihr wahrscheinlich irgendwann in einigen Dingen eine Ausbildung benötigen. Kommt einfach zu mir zurück, wann immer Ihr das Bedürfnis nach Unterweisung verspürt, und ich werde Euch lehren, was ich weiß - einen Trick hier, ein kleines Manöver dort. Ihr wisst schon, alles Mögliche, was einen am Leben erhält und einige Münzen extra einbringt.\n\nHaltet auch Ausschau nach unseren gnomischen Freunden ... bei der Zerstörung von Gnomeregan haben sie wohl ... den Kürzeren gezogen. Sie brauchen unsere Hilfe, um sich hier zu Hause zu fühlen.", rewards = "Ihr bekommt:\n\n"},
[3110] = {title = "Geheiligte Rune", objective = "Lest die geheiligte Rune und sprecht mit Branstock Khalder in Anvilmar.", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir diese Rune für Euch gegeben. Nehmt Euch die Zeit, sie zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, sie kommt vom Priesterlehrer Branstock. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", progress = "Ahh! Ihr habt's also hierher geschafft, <Name>! Großartig!\n\nWas ich sagen wollte, fast hätte ich den Glauben daran verloren, dass Ihr überhaupt erscheint..., versteht Ihr, den Glauben verloren? Nur ein Spaß, Jungchen... äh, ist ja auch egal. Ihr seid ja nicht gekommen, um meine schlechten Witze zu hören.", completion = "Ich kann Euch unterweisen, während Ihr lernt, Euch im Coldridgetal zurechtzufinden. Wenn Ihr Euch bereit fühlt, kommt zurück zu mir und wir werden sehen, ob Ihr schon so weit seid, einen oder zwei neue Zauber zu lernen, um das Tal gegen die verdammten Troggs zu verteidigen.\n\nIhr habt das Licht sowie ganz Ironforge auf Eurer Seite, &lt;Name&gt;, ... kein Druck lastet auf Euch, etwas Besonderes zu werden..", rewards = "Ihr bekommt:\n\n"},
[3112] = {title = "Einfaches Memorandum", objective = "Lest das einfache Memorandum und sprecht mit Thran Khorman im Coldridgetal.", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Kriegerlehrer Thran. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", progress = "Ah, nun, ein weiteres Memorandum von einem <Volk> im Einsatz... ist das nicht kurios.\n\nNein, nein, ich mache mich nicht über Euch lustig, Kleiner. Eure Zähigkeit verdient Respekt, so viel ist sicher. Ich wäre genauso verärgert, wenn Ironforge von Dunkeleisenzwergen eingenommen würde, glaubt also nicht, dass ich kein Mitgefühl verspüre für Eure Not...", completion = "Tja, wie ich sehe, ist dies Eure 'Oberste Direktive', oder wie auch immer Ihr dies heutzutage nennt. Ich habe mein Wort gegeben, dass ich alles in meiner Macht Stehende tun würde, um Euch und die Euren bereit zu machen, Eure Heimat zurückzuerobern... und genau das werde ich jetzt tun.\n\nWann immer Ihr bereit seid, kommt zurück zum alten Thran und ich werde mein Wissen gern mit Euch teilen. Für meine Unterweisungen nehme ich eine geringe Gebühr, aber es wird nicht zu teuer. Viel Glück.", rewards = "Ihr bekommt:\n\n"},
[3113] = {title = "Verschlüsseltes Memorandum", objective = "Lest das verschlüsselte Memorandum und sprecht mit Solm Hargrin im Coldridgetal.", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Schurkenlehrer Solm. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", progress = "Bin froh, dass Ihr meine Nachricht erhalten habt und mich hier aufsucht. Tut mir Leid, dass ich vorgeben musste, das Memorandum stamme von einem Eurer Vorgesetzten... war nicht böse gemeint. Ich weiß einfach, dass wir beide, gemeinsam mit den anderen unserer Art, zusammenhalten müssen.\n\nNicht viele glauben, dass es gut ist, wenn sich Eure Art und meine Art in derselben Stadt verschanzen, aber ich denke, wir bekommen das schon gut hin. Was meint Ihr?", completion = "Ich bin hier in der Gegend ziemlich für mich geblieben, sodass man uns für fehlende Dinge nicht verantwortlich macht; doch wenn Ihr etwas benötigt, Unterweisung oder sonst was, kommt gern auf mich zurück.\n\nIhr und ich, wir verstehen einander. Wir wissen, dass man im Grunde nur der Familie trauen kann - und das ist genau das, was wir hier sein werden, nicht wahr? Ungeachtet dessen, dass Gnomeregan... überrannt wird und was sich uns auch sonst in den Weg stellen mag, wir geben uns gegenseitig Rückendeckung. Nicht wahr?", rewards = "Ihr bekommt:\n\n"},
[3114] = {title = "Glyphen-Memorandum", objective = "Lest das mit Glyphen versehene Memorandum und sprecht mit Marryk Nurribit in Anvilmar oberhalb des Coldridgetals.", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Magielehrer Marryk. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.", progress = "Ja, wie war das, <Volk>? Sprecht lauter, bitte. Nach einigen Bieren höre ich nicht mehr so gut.", completion = "Oh, ja! Arkane Künste... klaro.\n\nDas müsst Ihr wissen, &lt;Name&gt;: Geht Ärger möglichst aus dem Weg. Spart einige Münzen auf, um mir ein Bier zu kaufen... oder irgendwelche Zauber, die Ihr wollt. Und bleibt auf jeden Fall weg von Gnomeregan. Ansonsten wünsche ich Euch einen angenehmen Tag! Ich werde hier sein, wenn Ihr mich braucht oder trainieren wollt... oder was auch immer.", rewards = "Ihr bekommt:\n\n"},
[3115] = {title = "Besudeltes Memorandum", objective = "Lest das besudelte Memorandum und sprecht mit Alamar Grimm in Anvilmar oberhalb des Coldridgetals.", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Hexenmeisterlehrer Alamar. Werft einen Blick darauf und sucht ihn dann in Anvilmar auf, sobald Ihr die Gelegenheit dazu habt.\n\nUnd passt auf Euch auf, <Name>, man traut Leuten wie Euch hierzulande nicht gerade.", progress = "Großartig! Offensichtlich habt Ihr mein Memorandum erhalten.\n\nIgnoriert die Narren um Euch herum, <Name>. Das Heilige Licht?! Das Schwert und Schild?! Dies sind keine Wege für jemanden mit einem so offenen Geist, wie wir ihn haben. Seht, wie \"normale\" Magie Eure Heimat zugerichtet hat. Zusammen mit diesen verdammten Tüftlern wurde unser Volk beinahe ausgerottet! Und jetzt müssen wir auf die Zwerge vertrauen - und die würden sich eher mit den Menschen verbünden, als uns beim Wiederaufbau unserer Heimat zu helfen. Wir sind wie Bürger zweiter Klasse. Habt Ihr gesehen, wie sie uns ansehen?", completion = "Aber nichts davon zählt wirklich. Was zählt ist, dass Ihr Euer eigenes Heiliges Licht gesehen habt! Ihr wisst, woher die Macht wirklich stammt. Ihr erkennt, dass es sehr viel... weiser ist, unsere eigenen Verbündeten zu haben. Spezielle Verbündete. Verbündete, die, ungeachtet der Aufgabe, bis zum letzten Atemzug gehorchen.\n\nUnd da komme ich ins Spiel, &lt;Name&gt;. Ich kann Euch die Anfänge dieser speziellen Mächte lehren. Sucht mich häufig auf und ich werde tun, was in meiner Macht steht, um Euch weitere Zauber zu lehren.", rewards = "Ihr bekommt:\n\n"},
[3116] = {title = "Einfaches Siegelzeichen", objective = "Lest das einfache Siegelzeichen und sprecht mit Alyissia in Shadowglen.", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserer Kriegerlehrerin Alyissia überreicht. Es sieht so aus, als wollte Alyissia ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", progress = "Ihr habt es hierher geschafft. Ich bin so froh.\n\nViel ist in den letzten Jahren geschehen, <Name>: Die Erbauung von Teldrassil, die Verderbnis vieler Kreaturen des Waldes hier und in der Fremde, die Entdeckung von Ländern, von denen wir dachten, sie seien für uns verloren wie Feralas ..., so viel in so kurzer Zeit. Aber dies sind nur einige der Gründe, warum wir hier sind, der wichtigste ist, unsere Art vor weiterem Bösen zu schützen.", completion = "Bald werdet Ihr Angehörige anderer Völker im Geäst unserer Heimat sehen... lasst keine Vorurteile in Euch aufkommen. Sie sind willkommen. Sie werden uns helfen, wenn sie können. Nicht alle von ihnen tun dies aus purer Selbstlosigkeit, es sollte ihnen jedoch ein bisschen Vertrauen entgegengebracht werden.\n\nAber all das ist jetzt nicht wichtig. Jetzt müssen wir uns auf Euch konzentrieren und wie Ihr unserem Volk helfen könnt. Aus diesem Grund bin ich auch hier. Ich werde Euch in den Fertigkeiten eines Kriegers unterweisen, während Ihr stärker und stärker werdet. Kehrt zu mir zurück, wann immer Ihr wollt, und ich werde alles in meiner Macht Stehende tun, um Euch zu helfen.", rewards = "Ihr bekommt:\n\n"},
[3117] = {title = "Geätztes Siegelzeichen", objective = "Lest das geätzte Siegelzeichen und sprecht mit Ayanna Everstride oben auf Aldrassil in Shadowglen.", description = "Dieses Siegelzeichen  wurde mir durch einen Boten von unserer Jägerlehrerin Ayanna überreicht. Es sieht so aus, als wollte Ayanna ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", progress = "Ihr seid im passenden Moment eingetroffen, <Name>. Willkommen in Shadowglen.\n\nIch hoffe, mein Siegelzeichen erreichte Euch bei guter Laune und Gesundheit.\n\nWie ich bereits sagte, bin ich hier, um Euch als geschickten <Klasse> auszubilden. Das bedeutet, Ihr werdet lernen, wie man Wildtiere zähmt, damit sie Euch im Kampf helfen, wie man den Bogen mit unfehlbarer Zielsicherheit einsetzt. Ihr werdet lernen, das Land, das wir Heimat nennen, zu respektieren und ebenso die Länder jenseits davon.", completion = "Während Ihr erlebt was Shadowglen Euch lehren kann, kommt und besucht mich - ich kann Euch dabei behilflich sein, Eure Aufgabe als &lt;Klasse&gt; besser zu verstehen und zu erkennen, zu was Ihr fähig seid.\n\nWir leben in gefährlichen Zeiten, &lt;Name&gt;, nehmt die Fertigkeiten Eurer Tiere nicht als gegeben an - es gibt in dieser Welt gefährlichere Dinge als Ihr Euch vorzustellen vermögt. Geht mit Elune und kommt wieder zu mir zurück.", rewards = "Ihr bekommt:\n\n"},
[3118] = {title = "Verschlüsselte Siegelzeichen", objective = "Lest das verschlüsselte Siegelzeichen und sprecht mit Frahun Shadwhisper in Shadowglen.", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserer Schurkenlehrerin Frahun überreicht. Es sieht so aus, als wollte Frahun ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", progress = "Hallo, <Name>. Ich bin erfreut, dass Ihr mich gefunden habt, ich dachte schon, Ihr hättet Euch vielleicht auf dem Weg hierher verirrt.\n\nSeitdem ich Euch mein Siegelzeichen sandte, ist nicht viel Neues in Shadowglen passiert, aber ich überlasse es Euch, Informationen zu sammeln. Ihr könnt gern mit den anderen Leuten in Aldrassil sprechen, wenn Ihr möchtet.", completion = "Bis dahin solltet Ihr wissen, dass unsere Art in diesen bedrückenden Zeiten mehr als sonst gebraucht wird. Der Frieden mit den anderen Völkern kann jeden Moment zusammenbrechen und es wird häufig von Mitgliedern der Horde berichtet, die sich bemühen, eine immer größere Saat des Misstrauens zu säen. Bedenkt dies.\n\nKommt zu mir zurück, wenn Ihr stärker geworden seid und Euch besser vorbereitet fühlt und ich werde mich um Eure Ausbildung kümmern. Es ist unter anderem sehr wichtig, dass Ihr mit der Waffe Eurer Wahl gut umgehen könnt.", rewards = "Ihr bekommt:\n\n"},
[3119] = {title = "Geheiligtes Siegelzeichen", objective = "Lest das geheiligte Siegel und sprecht mit Shanda in Aldrassil.", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserer Priesterlehrerin Shanda überreicht. Es sieht so aus, als wollte Shanda ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", progress = "Ich bin sehr erfreut, dass Ihr so schnell eingetroffen seid, <Name>. Willkommen.\n\nWie Ihr vielleicht bereits gehört habt, herrscht in ganz Teldrassil ein ständiges Kommen und Gehen von Reisenden. Sogar den Mitgliedern der Allianz wurde der Zutritt zu Teldrassils Ästen erlaubt, um sich mit anderen Kaldorei zu treffen, die sich auf die kommenden Abenteuer vorbereiten.", completion = "Aber im Moment müsst Ihr Euch nicht um die Welt unterhalb von Teldrassil kümmern. Dafür ist später noch Gelegenheit. Geht nun und sprecht mit den anderen in Shadowglen - sie können Euch mehr von den Ereignissen berichten, die sich zugetragen haben. Helft Ihnen so gut Ihr es vermögt, und wenn Ihr das Gefühl habt, weitere Ausbildung zu benötigen, kommt zu mir zurück und ich werde Euch lehren, was ich weiß.", rewards = "Ihr bekommt:\n\n"},
[3120] = {title = "Tiefgrünes Siegelzeichen", objective = "Lest das tiefgrüne Siegel und sprecht mit Mardant Strongoak im großen Baum Aldrassil in Shadowglen.", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserem Druidenlehrer Mardant überreicht. Es sieht so aus, als wollte Mardant ein paar Worte mit Euch wechseln, wenn Ihr einen Moment Zeit habt. Lest es und bringt es dann zu ihm.", progress = "Ah, <Klasse>. Ich sehe, dass Ihr es kaum erwarten könnt, Eure Studien fortzuführen. Gut.\n\nIch frage mich, ob Ihr schon viel Zeit im Smaragdgrünen Traum verbracht habt... Vielleicht seid Ihr darauf noch nicht genügend vorbereitet... Irgendwann wird es so weit sein, ganz sicher.\n\nDoch bis dahin sollten wir andere Dinge besprechen.", completion = "Vorerst werde ich Euer Mentor und Führer sein. Es ist meine Pflicht, Euch nicht nur zu lehren, wie man die Mitteilungen der Geister deutet, sondern auch die Komplexität und Geheimnisse des Smaragdgrünen Traums.\n\nJe mehr Ihr lernt und an Macht gewinnt, desto mehr werdet Ihr auch über unseren tranceähnlichen Schlaf erfahren. Aber bis dahin dürft Ihr so oft Ihr wollt zu mir kommen, und ich werde Euch alles, was ich über die Wege unserer Art weiß, lehren.", rewards = "Ihr bekommt:\n\n"},
[3121] = {title = "Eine seltsame Anforderung", objective = "Bringt den Schrumpfkopf zu Neeru Fireblade in Orgrimmar.", description = "Neeru Fireblade in Orgrimmar hat, was ich brauche, um hier beginnen zu können! Er hat ein Gebräu zusammengemischt, das ich für mein... na, Ihr werdet es schon sehen.\n\nAb mit Euch... nach Orgrimmar. Hier, nehmt das mit. Es ist ein Schrumpfkopf, den ich Neeru im Tausch für die Kräuter versprochen habe. Es ist der Kopf eines armen Zwergs, der mir im Wald über den Weg gelaufen ist. Ich bin sicher, dass Neeru sehr erfreut sein wird.\n\nIhr werdet Neeru in der Kluft der Schatten finden.", progress = "Ja?", completion = "Ich habe schon darauf gewartet, dass Uzer'i mir das bringt...\n\nIch möchte Euch diese Kräutermixtur geben, die ich für seine... ähm, Experimente vorbereitet habe...", rewards = "Ihr bekommt:\n\n"},
[3122] = {title = "Kehrt zu Hexendoktor Uzer'i zurück", objective = "Bringt Neerus Kräuterbeutel zu Hexendoktor Uzer'i in Feralas.", description = "Hier sind die Kräuter, <Name>. Bringt sie zu Hexendoktor Uzer'i.\n\nUnd sagt ihm, dass ich mit dem Schrumpfkopf sehr zufrieden bin.", progress = "Habt Ihr mit Neeru gesprochen?", completion = "Das ist genau das, was ich benötige, um das Muisekgefäß vorzubereiten, &lt;Name&gt;. Bald schon werden wir sehen, ob meine neuesten Beschwörungen so mächtig sind wie ich gehofft hatte.\n\nEinen Moment, bitte. Ich muss das Ritual durchführen und die Kräuter ansetzen.", rewards = "Ihr bekommt:\n\n"},
[3123] = {title = "Das Gefäß wird getestet", objective = "Reist ins Hinterland und spürt die Wildekin auf. Schaltet 10 davon aus und benutzt dann das Muisekgefäß, um die gefallenen Wildekin zu schrumpfen und einzufangen.\n\nBringt anschließend 10 Einheiten Muisek von Wildekins und das Muisekgefäß zu Hexendoktor Uzer'i in Feralas.", description = "Dies ist ein Test, sowohl für das Ritual, das ich durchgeführt habe, als auch für Eure Fähigkeiten. Nehmt dieses Gefäß, <Name>. Damit habt Ihr die Macht, eine Kreatur zu schrumpfen und sie darin gefangen zu nehmen.\n\nReist ins Hinterland und sucht nach Kreaturen, die als Wildekin bekannt sind. Sie waren einst die Tiere der Nachtelfengöttin Elune. Die heimtückischen, primitiven oder wilden Eulenbestien sollen Euer Ziel sein, <Name>. Vernichtet 10 und benutzt dann das Muisekgefäß, um sie zu schrumpfen und einzufangen, bevor ihr Geist flüchten kann.", progress = "Konntet Ihr einen Wildekin einfangen?\n\nWenn Ihr Erfolg habt, sind wir in der Lage, die Kreaturen von Feralas zu schrumpfen und deren Muisek einzufangen.", completion = "Bei einem grausamen Tod ist es möglich, dass das Muisek der Kreatur entkommt und Rache sucht. Durch das Schrumpfen der Kreaturen, wie Ihr es getan habt, &lt;Name&gt;, kann das Muisek nicht entfliehen. Jetzt können wir ihn so benutzen, wie es uns gefällt!", rewards = "Ihr bekommt:\n\n"},
[3124] = {title = "Muisek von Hippogryphen", objective = "Schaltet 10 Fransenfederhippogryphen eines beliebigen Typs aus und benutzt dann das Muisekgefäß, um sie zu schrumpfen und einzufangen.", description = "Da Ihr bewiesen habt, dass Ihr vertrauenswürdig und auch in der Lage seid, das Muisekgefäß zu benutzen, möchte ich, dass Ihr eine weitere Kreatur einfangt.\n\nHippogryphen sind seit vielen Jahren die treuen Gefährten der Nachtelfen. Ihre Geister sind loyal und unerschütterlich.\n\nEure Aufgabe besteht darin, 10 Fransenfederhippogryphen auszuschalten, sie schnell zu schrumpfen und mit dem Gefäß einzufangen, sodass ihr Muisek erhalten bleibt. Ihr findet die Hippogryphen in der oberen Wildnis, südlich von hier.", progress = "Konntet Ihr die Hippogryphen einfangen?", completion = "Wenn wir ein Tier töten und dem Muisek erlauben, zu entfliehen, kann es die Gestalt einer noch größeren Kreatur annehmen. Wir wären niemals sicher vor seiner Rache.\n\nIch hatte Euch mit einer gefährlichen Aufgabe betraut, &lt;Name&gt;. Und wieder habt Ihr sie gut bewältigt.", rewards = "Ihr bekommt:\n\n"},
[3125] = {title = "Muisek von Feendrachen", objective = "Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus. Benutzt das Muisekgefäß, um die gefallenen Feendrachen zu schrumpfen und einzufangen.", description = "<Name>, als Nächstes müsst Ihr für mich eine Kreatur fangen, die vom Aussehen her sehr zerbrechlich scheint, aber ihr mächtiger Geist ist das, was wir eigentlich besitzen wollen. Die Feendrachen, von denen ich spreche, dienen den Nachtelfen als Verbündete. Wir müssen einen von ihnen einfangen, damit auch die Horde von seiner Geisteskraft profitieren kann.\n\nHier ist das Muisekgefäß, <Name>. Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus und fangt ihr Muisek ein. Ihr könnt sie westlich von hier finden.", progress = "Konntet Ihr das Muisek der Feendrachen einfangen?", completion = "Danke, &lt;Name&gt;. Jetzt steht die geistige Macht der Feendrachen auch uns zur Verfügung.\n\nIch hoffe, Ihr seid willens, eine weitere Aufgabe für mich zu vollbringen.", rewards = "Ihr bekommt:\n\n"},
[3126] = {title = "Muisek von Treants", objective = "Schaltet 3 umherwandernde Waldgänger aus. Benutzt das Muisekgefäß, um die gefallenen Treants zu schrumpfen und einzufangen.", description = "Die umherwandernden Waldgänger, die überall im Wald zu finden sind, sind unser nächstes Ziel, <Name>. Nachtelfen haben Treants als Verbündete rekrutiert, um gegen die Horde zu kämpfen. Sie mögen zwar langsam sein, aber als Beschützer sind sie nicht zu unterschätzen.\n\nBald werden wir diese Macht für unsere eigenen Zwecke nutzen können.\n\nFindet 3 umherwandernde Waldgänger, schaltet sie aus und benutzt das Muisekgefäß, um sie zu schrumpfen und einzufangen.", progress = "Konntet Ihr die umherwandernden Waldgänger einfangen?", completion = "Danke, &lt;Name&gt;. Unsere Muiseksammlung ist nahezu vollständig.", rewards = "Ihr bekommt:\n\n"},
[3127] = {title = "Muisek von Bergriesen", objective = "Schaltet 7 Landgänger oder Klippenriesen aus. Benutzt das Muisekgefäß, um die gefallenen Bergriesen zu schrumpfen und einzufangen.", description = "Bei der letzten Aufgabe, die ich Euch stelle, sollt Ihr nach Nordwesten reisen und den letzten Feind finden.\n\nAls die Brennende Legion in der Welt erschien, haben die Bergriesen ihre Berge verlassen, um den Nachtelfen zu helfen. Ihr erkennt sie an ihrer enormen Größe und daran, wie der Boden erzittert, wenn Ihr durch ihr felsiges Gelände reist.\n\nIch kann es kaum erwarten, eine Macht von dieser Größe zu zähmen. Schaltet 7 Bergriesen aus und benutzt dann das Muisekgefäß, um ihr mächtiges Muisek einzufangen.", progress = "Konntet Ihr die Bergriesen einfangen?", completion = "Denkt nur an all die Möglichkeiten, die wir jetzt besitzen, &lt;Name&gt;. Zusammen mit den Materialien, die Ihr gesammelt habt, kann ich nun das Muisek dieser Kreaturen auf ewig in jeglicher Gestalt gefangen halten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3128] = {title = "Natürliche Materialien", objective = "Bringt 2 abgesplitterte Baumstämme, 6 verkrustete Mineralien, 20 Stücke widerstandsfähige Sehne und 40 metallische Fragmente zu Hexendoktor Uzer'i ins Camp Mojache.", description = "Ich benötige bestimmte Materialien, um mein Vorhaben zu vervollständigen... Ihr könnt das für mich erledigen, zusammen mit den anderen Aufgaben, die ich Euch stellen werde.\n\nIch brauche einen abgesplitterten Stamm eines Treants aus Feralas. Verkrustete Mineralien könnt Ihr an den Bergriesen und Feendrachen im Westen finden. Sucht mir einige widerstandsfähige Sehnen von den Eulenbestien im Hinterland oder den Hippogryphs von Feralas. Als Letztes benötige ich eine große Menge metallischer Fragmente von einer der Bestien, die ich erwähnt habe.", progress = "Konntet Ihr die Materialien, die ich benötige, finden?", completion = "Exzellent! Diese Materialien, zusammen mit dem Muisek, sollten uns genau die Ergebnisse liefern, die wir benötigen.", rewards = "Ihr bekommt:\n\n"},
[3129] = {title = "Waffen des Geistes", objective = "Hexendoktor Uzer'i will, dass Ihr einen Moment wartet, während er die Waffen vorbereitet.", description = "Es ist ein äußerst komplizierter Vorgang, die Waffen mit dem Muisek zu erfüllen. Aber da ich jetzt sowohl über alle erforderlichen Materialien als auch über das Muisek der von Euch eingefangenen Kreaturen verfüge, kann ich endlich beginnen. Bitte wartet hier, ich werde gleich zurück sein.", progress = nil, completion = "Wie versprochen, habt Ihr nun die Wahl, &lt;Name&gt;. Das Muisek dieser Kreaturen wurde auf ewig in die Macht dieser Waffen eingeschlossen.\n\nIhre Energie ist nun die Eure. Verwendet sie gut.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGewalt des HippogryphenGeist des FeendrachenKraft des TreantWille des Bergriesen\n\nIhr bekommt außerdem:\n\n"},
[3130] = {title = "Gegen die Hasskämme", objective = "Meldet Euch bei Latronicus Moonspear in der Festung Feathermoon.", description = "Ich werde Euch jetzt zu meinem Stellvertreter Lactronicus schicken. Er hat bisher ein wachsames Auge auf die Nagastreitkräfte gehabt. Ich werde die allgemeine Lage hier in Bezug auf die Naga bewerten. Liebend gern würde ich eine ganze Armee gegen sie aussenden, aber es ist nicht unbedingt ratsam, die Festung einem direkten Angriff der Horde - oder Schlimmerem - schutzlos auszusetzen.\n\nWie dem auch sei, Latronicus erwartet Euch. Gute Arbeit bisher, <Name>. Nur weiter so.\n\nIhr könnt wegtreten.", progress = nil, completion = "Exzellent, &lt;Name&gt;... ich schätze eine \"Geht klar\"-Einstellung bei Leuten, mit denen ich arbeite.\n\nIch wurde von General Feathermoon beauftragt, die Naga direkt anzugehen. Mein Plan besteht aus zwei Teilen: Abschnitt eins sieht vor, dass wir sie sowohl zahlenmäßig als auch hinsichtlich ihrer Befehlshaber schwächen, und danach werden wir herausfinden, was sie in den Ruinen vorhaben. Mit Eurer Hilfe werden wir den Naga entgegentreten, ohne die allgemeine Sicherheit der Festung zu beeinträchtigen.", rewards = "Ihr bekommt:\n\n"},
[3141] = {title = "Loramus", objective = "Lasst Loramus Thalipedes seine Geschichte erzählen.", description = "Ihr wollt also gegen Dämonen kämpfen? Dann tätet Ihr gut daran, Euch meine Geschichte anzuhören.", progress = "Unterbrecht mich nicht, <Volk>.", completion = "So sei es...", rewards = "Ihr bekommt:\n\n"},
[3161] = {title = "Gahz'ridian", objective = "Marvon Rivetseeker in Tanaris möchte, dass Ihr 30 Gahz'ridian-Ornamente sammelt.", description = "<Name>, ich bin zwar Wissenschaftler, aber im Grunde meines Herzens bin ich auch Schatzsucher!\n\nVor langer Zeit, als Trolle dieses Land besetzt hielten, schufen sie eine große Anzahl von Ornamenten nach dem Vorbild der Gahz'rilla, einer Hydra, die sie als Göttin verehrten. Diese Ornamente werden aus einem Element herausgeschnitzt, das ich nach der Hydragöttin \"Gahz'ridian\" nenne.\n\nIch selbst habe schon einige dieser Ornamente gefunden, aber ich hätte gern noch mehr, um sie zu untersuchen - vielleicht findet Ihr ja noch welche ...\n\nIch habe sogar einen Detektor erfunden, der es zu einem Kinderspiel macht, Gahz'ridian zu finden! Legt ihn einfach an und die Suche kann beginnen!", progress = "Habt Ihr Probleme?\n\nIhr könnt Gahz'ridian fast überall in Tanaris finden, <Name>, also sucht weiter!", completion = "Perfekt, diese Ornamente sind einfach perfekt für meine Studien. Ich danke Euch sehr für Eure Hilfe, &lt;Name&gt;.\n\nAch ja, kann ich meinen Helm zurückhaben?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFeldmesser-TunikaStab der Lehre\n\nIhr bekommt außerdem:\n\n"},
[3181] = {title = "Das Horn der Bestie", objective = "Bringt Margols gigantisches Horn zu Gebirgsjägerin Pebblebitty.", description = "Das gigantische Horn hat viele Kratzer und Risse. Ein ungewöhnliches Metallobjekt klemmt in der rauen Oberfläche fest.\n\nBeim näheren Hinschauen entdeckt Ihr, dass das Metall in Wirklichkeit ein zerbrochener Axtkopf ist. In das Metall wurden diese Wörter eingeätzt:\n\nEigentum von Gebirgsjägerin Pebblebitty.\n\nAls Ihr versucht, den zerbrochenen Axtkopf herauszuziehen, zerfällt er in unzählige Teile.\n\nUps!", progress = "Nein, ich werde das Tor nicht öffnen.", completion = "Was habt Ihr denn da? Offensichtlich eine Fälschung!\n\nIch stand Margol von Angesicht zu Angesicht gegenüber und weiß ganz genau, dass das Horn mindestens acht Mal so groß ist wie dasjenige, das Ihr in Euren Händen haltet, &lt;Name&gt;. Das da habt Ihr wahrscheinlich von einer Sturmschnauze aus dem Brachland. Nein, werter Herr, Pebblebitty könnt Ihr nichts vormachen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3182] = {title = "Besitznachweis", objective = "Bringt Margols gigantisches Horn zu Kurator Thorius in Ironforge.", description = "Ihr erwartet wirklich, dass ich eine solche Geschichte glaube? Wenn es das echte Horn wäre, dann würde meine zerbrochene Axt ja immer noch drinstecken.\n\nHört zu, bringt diese dreiste Fälschung zu Kurator Thorius in Ironforge. Falls er Eure Behauptung bestätigt, werdet Ihr eine Beweisurkunde für Eure Tat erhalten. Bringt mir diesen Beweis und ich werde Euch den Schlüssel für die sengende Schlucht geben.\n\nGeht schon!", progress = "Ah, guten Tag, junger Herr. Hättet Ihr gern eine Führung durch das Museum?", completion = "Was ist denn das?\n\nOh nein, das kann ich gar nicht glauben! Wisst Ihr, was Ihr da habt, &lt;Volk&gt;? Dies ist das Horn von Margol! Margol ist der Fluch eines jeden Archäologen, der jemals seinen Fuß in die sengende Schlucht gesetzt hat.\n\nKann ich es behalten?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3201] = {title = "Endlich!", objective = "Bringt die Urkunde für die Tat zurück zu Gebirgsjägerin Pebblebitty.", description = "Ich kann kaum glauben, dass Pebblebitty die Echtheit des Horns angezweifelt hat. Unter uns, ich denke, sie ist einfach nur eifersüchtig. Ich weiß, dass sie diese Bestie gern selbst getötet hätte, nach dem, was bei dem 'Ereignis' so vorgefallen ist.\n\nIhr braucht also eine Urkunde für Eure Tat? Nachdem Ihr nun gerade dem Museum ein solches Geschenk gemacht habt, sollte das kein Problem sein.\n\n<Kurator Thorius fängt an, ein großes Dokument auszufüllen.>\n\nHier bitte! Das könnt Ihr Pebblebitty zurückbringen.", progress = "Ich kann es nicht glauben.", completion = "Ich weiß zwar nicht, wie jemand, der so schwach ist wie Ihr, Margol überwältigen konnte, aber eine Abmachung ist eine Abmachung. Hier habt Ihr den Schlüssel.\n\nSollte Euch jetzt etwas zustoßen, ist es Eure eigene Schuld.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nSchlüssel zur sengenden Schlucht"},
[3221] = {title = "Sprecht mit Renferrel", objective = "Sprecht mit Apotheker Renferrel in dem Grabmal.", description = "Während Ihr fort wart, um unseren Todespirschern zu helfen, hat Apotheker Renferrel Euch eine Einladung geschickt. Er hat mir keinerlei Einzelheiten mitgeteilt, aber er wollte mit Euch über die Wolfherzen sprechen, die Ihr ihm gegeben habt.", progress = nil, completion = "Ah, sehr gut. Es gibt da etwas bezüglich der Wolfherzen, die Ihr mir gebracht habt, das unserer Aufmerksamkeit bedarf.", rewards = "Ihr bekommt:\n\n"},
[3261] = {title = "Jorn Skyseer", objective = "Sprecht im Camp Taurajo mit Jorn Skyseer.", description = "Eure Zeit bei mir ist vorbei, <Name>. Wenn Ihr mehr lernen wollt, müsst Ihr ins Camp Taurajo gehen und mit Jorn Skyseer sprechen. Er wird Eure Weiterbildung übernehmen.", progress = nil, completion = "Seid gegrüßt. Ihr seid hier, um den Pfad des Jägers zu beschreiten?\n\nSehr gut. Lasst uns beginnen.", rewards = "Ihr bekommt:\n\n"},
[3281] = {title = "Gestohlenes Silber", objective = "Bringt das gestohlene Silber zu Gazrog in Crossroads.", description = "Ihr habt zwar die Raptoren getötet, aber das Silber, das sie gestohlen haben, muss wiederbeschafft werden! Ich habe Berichte darüber, dass die Raptoren eine große Ansammlung von Nestern südlich von Ratchet haben, Raptorgründe genannt. Es ist sehr wahrscheinlich, dass sie unser gestohlenes Silber dorthin gebracht haben.\n\nGeht zu dieser Raptorzuflucht und haltet nach dem gestohlenen Silber Ausschau. Wenn Ihr es gefunden habt, kommt damit zu mir zurück.", progress = "Habt Ihr das Silber?", completion = "Aha! Also haben die Raptoren das Silber in ihrem Unterschlupf versteckt. Es ist kaum zu glauben, dass es diese Bestien nach Silber verlangt. Vielleicht sind diese Geschichten über ihre Intelligenz doch nicht so weit von der Wahrheit entfernt, wie ich dachte.\n\nDanke, &lt;Name&gt;. Nehmt dies als Belohnung für Eure uns erwiesenen Dienste und wisset, dass die Wachen am Scheideweg ihren nächsten Monatslohn Euch verdanken.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nStromer-StiefelSiedler-Gamaschen\n\nIhr bekommt außerdem:\n\n"},
[3301] = {title = "Mura Runetotem", objective = "Sprecht mit Mura Runetotem in dem Grabmal.", description = "Meine Klangefährtin, Mura Runetotem, ist nach Silberwald gereist, um unseren untoten Verbündeten zu helfen. Der Silberwald ist ein kranker Wald, ein sterbender Wald, und Muras Hoffnung war, ihm neues Leben zu bringen. Vielleicht kann dieses seltsame Leben, das wir im Brachland gefunden haben, ihr bei ihrer Arbeit im Silberwald helfen.\n\nBringt eine Probe der von Euch gesammelten Schalen zu Mura nach Silberwald. Sie hält sich in dem Grabmal auf. Mit etwas Glück vermittelt ihr das Studium der Schalen den Einblick, den sie benötigt, um diesen sterbenden Ort zu heilen.", progress = "Ich kann den Staub des Brachlandes an Euch riechen, <Klasse>. Ihr seid weit gereist.", completion = "Ah... was ist denn das? Diese Schale glüht von innen, als ob in ihr noch Leben pulsierte. Erstaunlich! Ich muss sie weiter untersuchen.\n\nDanke, &lt;Name&gt;. Wenn wir Glück haben, enthält diese Schale ein Geheimnis, das ich verwenden kann, um dem armen Land Silberwald zu helfen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nJacksaat-GürtelSäer-Umhang\n\nIhr bekommt außerdem:\n\n"},
[3321] = {title = "Habt Ihr das verloren?", objective = "Wartet, bis Trenton seine Arbeit erledigt hat.", description = "Ihr habt viel für den Orden getan, <Name>. Allein die Hingabe, derer es bedarf, um hierher zu gelangen, hätte jede normale Person abgehalten. Galvan und auch ich haben keinerlei Zweifel, dass Ihr einer von uns seid.\n\nAus diesem Grund denke ich, dass Ihr Euch eine kleine Belohnung verdient habt. Es ist nichts Besonderes, nur eine Kleinigkeit. Vielleicht sind Euch seine Eigenschaften vertraut, denn ich glaube, dass es der Grund war, warum Ihr überhaupt zu uns gekommen seid.", progress = nil, completion = "Erhebt Euch und seid gewürdigt, &lt;Name&gt;, Schmied des Mithrilordens.", rewards = "Ihr bekommt:\n\nGleißende Mithrilinsignien"},
[3341] = {title = "Das Ende bringen", objective = "Andrew Brownell will, dass Ihr Amnennar den Kältebringer tötet und ihm dessen Schädel bringt.", description = "Im Brachland liegt ein schreckliches Dickicht aus ineinander verschlungenen Ranken, Hügel von Razorfen genannt. Unsere ersten Beobachtungen haben zwar auf keine große Bedrohung schließen lassen, aber die neuesten Funde geben doch allen Grund zur Sorge...\n\nDie Stacheleber der Hügel von Razorfen haben sich mit der Geißel zusammengetan. Ein Lich namens Amnennar der Kältebringer beherrscht sie jetzt und nutzt die Macht seines riesigen Bewusstseins, um jede ihrer Bewegungen zu kontrollieren.\n\nAmnennar verfügt über eine direkte telepathische Verbindung zu Ner'zhul. Diese Bindung müssen wir durchtrennen, <Name>. Dem Kältebringer muss ein Ende gemacht werden.", progress = "Diese Angelegenheit ist von äußerster Wichtigkeit, <Name>. Wir müssen jeden Versuch der Geißel zunichte machen, ihre Reihen zu vergrößern.", completion = "Die Loyalität eines Lich ist unerschütterlich, &lt;Name&gt;. Lasst sie wissen, dass diese Loyalität ihnen nur Verderben bringt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nBezwingerschwertBernsteinglut-Talisman"},
[3361] = {title = "Dilemma eines Flüchtlings", objective = "Bringt Felix Whindlebolt in Anvilmar den Kasten, die Truhe und den Bolzeneimer von Felix.", description = "Wir haben die Troggs aus Gnomeregan vertrieben, aber dann ist alles schrecklich schief gegangen! Jetzt ist unsere Heimat völlig von Strahlen verseucht und wir Gnome sind überall in Dun Morogh zerstreut.\n\nIn meiner Hast, der Strahlung zu entkommen, habe ich all mein ganzes Hab und Gut und auch meine Werkzeuge verloren. Die Trolle haben sie geholt. Sie haben meine Truhe, meine Kiste, und meinen Bolzeneimer gestohlen! Alles das haben sie in ihre Lager südwestlich von Anvilmar mitgenommen.\n\nIch bin nur leider kein Abenteurer - könntet Ihr bitte meine Sachen suchen und sie mir herbringen?", progress = "Liebe Güte <Name>, diese Stadt ist für Leute wie mich nicht sehr geeignet. Hier gibt es ja ebenso viele widerliche Kreaturen wie in Gnomeregan vor diesem Unfall!\n\nHabt Ihr meine Habseligkeiten? Falls nicht... oje, wer weiß, was die Trolle damit angestellt haben...", completion = "Hurra, Ihr habt sie gefunden! Ihr seid wirklich eine echte Hilfe. Hier, es ist zwar nicht viel, aber doch etwas, um Euch für den Ärger zu entlohnen, den Ihr meinetwegen hattet. Danke!", rewards = "Ihr bekommt:\n\n"},
[3362] = {title = "Disteltal", objective = "Tran'rek in Gadgetzan möchte, dass Ihr 8 knorrige Distelwandler und 8 Distelwurzelformer erledigt.", description = "Habt Ihr jemals das Disteltal gesehen? Es ist ein sehr gefährlicher Ort, <Name>.\n\nDiesen merkwürdigen Bestien dort traue ich nicht für eine Minute! Ich glaube, man nennt sie knorrige Distelwandler und Distelwurzelformer...\n\nIch möchte in das Tal hinein, aber solange es dort von Distelwandlern wimmelt, kehre ich auf keinen Fall dorthin zurück. Und an dieser Stelle kommt Ihr ins Spiel - wenn Ihr einige von ihnen erledigt, würde ich vielleicht doch dorthin zurückkehren. Was meint Ihr, <Name>? Helft Ihr mir?", progress = nil, completion = "So groß sind die? Ich muss meinen Plan vielleicht noch einmal überdenken...\n\nAber Ihr habt Euren Teil der Abmachung gehalten, also bekommt Ihr auch, was ich versprochen habe. Hier, nehmt.", rewards = "Ihr bekommt:\n\n"},
[3363] = {title = "Verderbte Liedblume", objective = "Blah.", description = "Nehmt mich auf.", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[3364] = {title = "Lieferung des kochend heißen Morgengebräus", objective = "Bringt ein kochend heißes Morgengebräu zu Durnan Furcutter ins Anvilmar hinein, bevor es innerhalb von fünf Minuten kalt wird!", description = "Bah! Ich sollte dieses köstliche, kochend heiße Morgengebräu schon vor einer ganzen Weile zu Durnan Furcutter im Anvilmar bringen, aber ich musste erst eine Ladung zu Grelin hier bringen. Ich werde es niemals bis nach Anvilmar schaffen, bevor das Gebräu kalt wird!\n\nIhr seht hurtig aus. Vielleicht könnt Ihr es schaffen. Diese Tasse wird nur noch fünf Minuten lang heiß bleiben, und Durnan bestellte kein \"eisiges\" Morgengebräu, also beeilt Euch. Anvilmar liegt im Nordosten. Es ist eine Siedlung, die in den Berg gebaut wurde.\n\nDanke, <Name>, und vergesst nicht, mir meinen Becher zurückzubringen!", progress = "Jawohl, ich bin Durnan Furcutter. Habt Ihr denn etwas für mich?", completion = "Ah, sehr gut, das trifft sich ja wunderbar. Erlaubt mir eine kleine Pause, um dieses kochend heiße Morgengebräu zu genießen!", rewards = "Ihr bekommt:\n\n"},
[3365] = {title = "Den Becher zurückbringen", objective = "Bringt Nori Pridedrift den Becher zurück.", description = "Das kam genau zur rechten Zeit! Es geht doch nichts über ein heißes - neee, KOCHEND HEISSES Morgengebräu an einem kalten Wintertag, um einem das Herz zu wärmen.\n\nHier, bitte <Name>... seid so nett und bringt für mich den leeren Becher zurück zu Nori, ja?", progress = "Ich hoffe ja, dass das kochend heiße Morgengebräu Durnan rechtzeitig erreicht hat! Habt Ihr daran gedacht, mir meinen Becher zurückzubringen?", completion = "Exzellent, &lt;Name&gt;! Ihr wärt überrascht, wenn ich Euch erzähle, wie viele Kuriere etwas so Einfaches wie das Zurückbringen des Bechers vergessen. Es heißt nicht umsonst, dass Becher nicht auf Bäumen wachsen!\n\nHier habt Ihr etwas für Eure Mühe. Ich danke Euch nochmals für Eure Hilfe.", rewards = "Ihr bekommt:\n\n"},
[3366] = {title = "Der leuchtende Splitter", objective = "Reist nach Ratchet, um die Bedeutung des Alptraum-Splitters herauszufinden.", description = "Der Splitter ist von einem glänzenden Grün und obwohl er fest ist, scheint etwas wie Rauch genau unterhalb der Oberfläche herumzuwirbeln. Ihr möchtet am liebsten in die Tiefen des Kristalls schauen, aber gleichzeitig wisst Ihr, dass es etwas sehr Beunruhigendes damit auf sich hat.\n\nVielleicht solltet Ihr in Ratchet nach jemandem suchen, der Euch mehr über diesen seltsamen Splitter erzählen kann.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[3367] = {title = "Suntara-Steine", objective = "Helft Dorius, zurück nach Ironforge zu kommen.", description = "<Dorius stöhnt.>\n\nIch bin schwer verletzt, <Volk>. Fühle mich... benommen... Alles dreht sich... Innere... Blutungen.\n\nIch muss zurück nach Ironforge. Helft mir, <Name>.", progress = "Ich schaffe es nicht...", completion = "Dorius ließ diesen Brief fallen, als er erschossen wurde.", rewards = "Ihr bekommt:\n\n"},
[3368] = {title = "Suntara-Steine", objective = "Bringt den angesengten Brief zu Thorius in Ironforge. Er befindet sich in der Halle der Forscher.", description = "Bruder,\n\nwenn Du diesen Brief liest, bin ich nicht mehr. Wie er zu dir gelangt, weiß ich nicht, aber danke und belohne denjenigen, der ihn dir bringt.\n\nZu den Steinen: Es gibt sie wirklich und sie befinden sich im Besitz der Dunkeleisenzwerge. Ihr Anführer, Lathoric der Schwarze, benutzt die Kraft der Steine, um mein Ausgrabungsteam zu versklaven. Sie wurden zum Kessel gebracht. Ihre Gedanken wurden verdreht, sie arbeiten Tag und Nacht, um etwas, das Obsidion heißt, zu vollenden.\n\nHilf ihnen, Bruder. Das ist der letzte Wunsch eines toten Mannes.\n\n- Dorius", progress = "<Thorius schluchzt.>", completion = "&lt;Thorius wischt sich sein Gesicht ab.&gt;\n\nIm Namen des Lichts, sein Wunsch soll erfüllt werden. Das schwöre ich.", rewards = "Ihr bekommt:\n\n"},
[3369] = {title = "Alptraum", objective = "Bringt den Alptraum-Splitter zu Hamuul Runtetotem auf der Anhöhe der Ältesten.", description = "Dieser Splitter enthält große Geheimnisse; er ist die pure Essenz des Smaragdgrünen Traums. Was ich jedoch in diesem Splitter sehe, ist kein Traum, diese Art der Vision ist eher ein Alptraum.\n\nIch möchte Euch nicht beunruhigen, <Name>, aber ich denke, es ist am besten, wenn Ihr diesen Splitter so schnell wie möglich in die Hände eines weisen Druiden gebt.\n\nIhr müsst Hamuul Runetotem auf der Anhöhe der Ältesten finden. Geht nach Thunder Bluff. Mehr vermag ich Euch nicht zu sagen.", progress = "Kann ich Euch behilflich sein?", completion = "Falla hat Euch zu mir gesandt? Dann lasst mich mal jenen Splitter sehen, über den sie nur so ungern sprechen mochte, wie Ihr sagt...\n\n&lt;Hamuul sieht in den Splitter&gt;\n\nOh... Ich habe nicht... Nun ja.\n\n&lt;Name&gt;, ich danke Euch, dass Ihr mir das hier gebracht habt. Lasst mich Euch jedoch sagen, dass es nicht sehr klug ist, von Dingen wie diesen zu sprechen. Das sind Dinge, mit denen Ihr Euch nicht beschäftigen solltet.\n\nSagen wir einfach mal, dass die Dinge im Smaragdgrünen Traum nicht so sind, wie wir es dachten...\n\nVielleicht werden wir uns einmal wiedersehen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTalbar-MantelMorastgaloschen\n\nIhr bekommt außerdem:\n\n"},
[3370] = {title = "Alptraum", objective = "Bringt den Alptraum-Splitter zu Mathrengyl Bearwalker in Darnassus.", description = "Dieser Splitter trägt große Geheimnisse in sich; es ist die pure Essenz des Smaragdgrünen Traums. Was ich jedoch in diesem Splitter sehe ist kein Traum, diese Art der Vision ist eher ein Alptraum.\n\nIch möchte Euch nicht beunruhigen, <Name>, aber ich denke, es ist am besten, wenn Ihr diesen Splitter in die Hände eines weisen Druiden gebt, sobald Ihr könnt ... \n\nIhr müsst Mathrengyl Bearwalker im Zirkel des Cenarius finden. Geht nach Darnassus. Mehr vermag ich Euch nicht zu sagen.", progress = "Kann ich Euch behilflich sein?", completion = "Falla hat Euch zu mir gesandt? Dann lasst mich mal jenen Splitter sehen, über den sie nur so ungern sprechen mochte, wie Ihr sagt...\n\n&lt;Mathrengyl sieht in den Splitter&gt;\n\nOh... Ich habe nicht... Nun ja.\n\n&lt;Name&gt;, ich danke Euch, dass Ihr mir das hier gebracht habt. Lasst mich Euch jedoch sagen, dass es nicht sehr klug ist, von Dingen wie diesen zu sprechen. Das sind Dinge, denen sich die cenarischen Druiden allein stellen müssen.\n\nSagen wir einfach mal, dass die Dinge im Smaragdgrünen Traum nicht so sind, wie wir es dachten...\n\nVielleicht werden wir uns einmal wiedersehen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTalbar-MantelMorastgaloschen\n\nIhr bekommt außerdem:\n\n"},
[3371] = {title = "Zwergengerechtigkeit", objective = "Kehrt zur sengenden Schlucht zurück und sucht Dorius' Archäologenteam.", description = "Wo mein Herz einst schlug, ist jetzt ein leeres Loch, <Name>. Über den Verlust von Dorius werde ich so schnell nicht hinwegkommen. Ich muss seinen letzten Wunsch erfüllt sehen - diejenigen, die diesen kaltblütigen Mord durchführten, müssen der Gerechtigkeit zugeführt werden.\n\nKehrt zur sengenden Schlucht zurück und erfüllt seine letzte Bitte. Befreit seine Männer.", progress = nil, completion = "Lasst mich, helft den anderen.", rewards = "Ihr bekommt:\n\n"},
[3372] = {title = "Erlöst sie", objective = "Sucht das mysteriöse Artefakt, das im Norden von den Twilight-Hammer bewacht wird.", description = "Befreit sie, <Volk>. Selbst nachdem ihre Körper aufgegeben haben, zwingt die Macht der Suntara sie, ihre Aufgaben weiter zu erfüllen.\n\nDer Altar von Suntara ist der Schlüssel. Geht nach Norden, in die Hügel oberhalb der Höhle... Die Twilight-Hammer bewachen dort ein Relikt. Bringt es herbei und stellt es auf den Altar von Suntara.\n\n<Der sterbende Archäologe bricht zusammen.>", progress = "Der Altar ist leer.", completion = "Ihr stellt das mysteriöse Artefakt auf den Altar von Suntara.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3373] = {title = "Die Essenz des Eranikus", objective = "Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet.", description = "Als Ihr den Edelstein berührt, ertönt eine tiefe Stimme in Eurem Geist.\n\n\"Sterbliches Wesen, hört diese Bitte. Ich bin Eranikus vom grünen Drachenschwarm, der Hüter dieses verfluchten Tempels. Meine Aufgabe, sicherzustellen, dass die Trolle nie wieder ihre Monstrosität von einem Gott in diese Welt bringen, ist nun fehlgeschlagen. Während ich diesen Edelstein mit einem Teil meiner magischen Essenz fülle, fühle ich, wie mein Traum sich zum Chaos hinbewegt. Ich bitte Euch... legt diesen Edelstein in den Essenzborn in meinem Unterschlupf und lasst unsere Magie dort den Makel von meiner Psyche nehmen, sodass ich endlich ruhen kann.\"", progress = "Während Ihr Euch dem Essenzborn nähert, von dem Eranikus Euch berichtet hat, ertönt seine Stimme erneut in Eurem Kopf.\n\n\"Ja, sterbliches Wesen, dieser Essenzborn wird den reinen Teil meiner Psyche, die sich noch innerhalb dieses Edelsteins befindet, erlösen. Legt den Edelstein in den Born hinein und lasst die Magie des grünen Drachenschwarms Verderbnis und Besudelung von meinem Wesen entfernen. Erst dann werde ich wahre Erlösung finden und erst dann wird der Drachenschwarm in der Lage sein, seine Führung über den Atal'ai wieder zu bestätigen.\"", completion = "Ihr legt den Edelstein in den Essenzborn hinein.\n\n\"Ich danke Euch, sterbliches Wesen, Ihr habt - nein... das, das darf nicht sein! Nein! Die Verderbnis dieses verfluchten Gottes hat sogar die Reinheit eines Essenzborns des grünen Drachenschwarms beschmutzt! Bitte, nein, ich fühle, wie meine Essenz von mir gerissen wird! DER SCHMERZ! Ich fühle, wie mich die Umklammerung eines ewigen Alptraums umschlingt...\"\n\n\"Sterbliches Wesen, ich flehe Euch an! Findet einen vom grünen Drachenschwarm, um dem ein Ende zu bereiten... helft mir... Ich bin in der Dunkelheit gebunden... auf ewig in Schmerzen... bitte nicht... foltern...\"", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nAngekettete Essenz des Eranikus"},
[3374] = {title = "Die Essenz des Eranikus", objective = "Bringt den Schwurstein von Yseras Drachenschwarm sowie die gekettete Essenz von Eranikus zu Itharius in die Sümpfe des Elends. Dort werdet Ihr Eure Entscheidung treffen, ob Ihr Yseras Drachenschwarm helfen wollt oder nicht.", description = "Ihr aktiviert den Schwurstein und Itharius spricht Euren Geist direkt durch den Stein an.\n\n\"Indem Ihr die Ladung dieses Schwursteins angenommen habt, erklärt Ihr Euch einverstanden, meiner Sache und der Sache von Yseras Drachenschwarm behilflich zu sein, und die verderbte Seele von Eranikus zu erlösen. Das erste Opfer, eines von vielen, die Ihr ohne Zweifel bringen müsst, ist, mir den Edelstein zu übergeben, der den Teil von Eranikus' Psyche gefesselt hat, der noch über einen freien Willen verfügt.\"\n\n\"Tut dies, <Name>, und wir werden zusammen an der Erlösung einer Seele arbeiten, die es verdient hat, erlöst zu werden.\"", progress = "Hier sind wir nun, <Name>, wieder an einem Scheideweg. Es ist jetzt an der Zeit, eine weitere Entscheidung zu treffen. Welche Wahl werdet Ihr treffen?", completion = "Ihr habt Eure Wahl getroffen und so beginnt es. Bis jetzt waren Eure Entscheidungen, soweit es mich betrifft, die richtigen. Eure Taten und Aktionen werden nun bestimmen, ob dies weiterhin der Fall sein wird.", rewards = "Ihr bekommt:\n\n"},
[3375] = {title = "Ersatzphiole", objective = "Bringt einen Manatrank, Kohle und Süßen Nektar zu Talvash del Kissel in Ironforge, um einen Ersatz für Talvashs Wahrsagephiole zu bekommen.", description = "Ähm... Ihr braucht eine weitere Wahrsagephiole? Das soll wohl ein Witz sein! Was habt Ihr denn mit der Ersten angestellt?! Wir haben eine Menge Arbeit vor uns, <Volk>. Diese Phiolen wachsen nun mal nicht auf Bäumen! Eigentlich wünschte ich, es wäre so, dann könnte ich nämlich einfach eine pflücken gehen. Ich habe nämlich keine mehr!\n\nUm Euch eine zu machen, brauch ich Folgendes: Einen Manatrank, ein Stück Kohle und etwas süßen Nektar. Fragt mich ja nicht, warum, bringt mir einfach, was ich brauche, und ich werde Euch eine neue Phiole machen.", progress = "Um eine weitere Phiole herzustellen, brauche ich einen Manatrank, ein Stück Kohle und etwas süßen Nektar.\n\nUnd außerdem anscheinend noch jede Menge Geduld.", completion = "Der mächtige Abenteurer bringt die Sachen herbei. Wie schön für mich. Übrigens, ich hab gelogen... ich hatte noch eine Phiole. Hng, nehmt sie.\n\nNa, was habt Ihr denn erwartet? \"Oh, hier, nehmt die hier! Ich bin ja nur ein Idiot, der nichts Besseres zu tun hat, als magische Kommunikationsgeräte an Abenteurer zu verschleudern!\" Eins ist jedoch sicher, das, was Ihr mir gebracht habt, reicht aus, um Euch eine weitere Phiole zu machen, wenn Ihr diese hier auch verlieren solltet.\n\nEs wäre jedoch schön, wenn ich mich irren würde und Ihr die neue nicht verliert, ja?", rewards = "Ihr bekommt:\n\nTalvashs Wahrsagephiole"},
[3376] = {title = "Tötet Spitzhauer!", objective = "Bringt den Kopf von Häuptling Spitzhauer Dornenmantel zu Kriegerheld Windfeather nach Red Cloud Mesa.", description = "<Name>... Ihr seid ein Neuling, ich habe von Euch gehört. Vielleicht könnt Ihr uns ja helfen, wo andere bereits versagt haben.\n\nWir Tauren haben in diesem Land unsere Heimstatt geschaffen, aber nicht, ohne teuer dafür zu bezahlen. Die Stacheleber des Borstennackenstamms aus der Dornrankenklamm, mit Häuptling Spitzhauer Dornenmantel als Anführer, machen uns mit ihrem ständigen Krieg das Leben schwer. Ich beauftrage Euch, mir den Kopf des Häuptlings zu bringen!\n\nIhr könnt ihn in der Klamm östlich von hier in dem heruntergekommenen Dorf finden.", progress = "Spitzhauer wird uns nicht mehr belästigen, sobald Ihr mir den Beweis seines Todes liefert. Ich will seinen Kopf, <Name>.\n\nWir <Volk> leben für die Jagd und es gibt keine größere Jagd als gegen einen, der schlau genug ist, uns vielleicht auch zu jagen. Wenn Ihr in dieser Aufgabe erfolgreich seid, werdet Ihr anfangen zu begreifen, was ich meine.", completion = "Der Gerechtigkeit wurde heute durch Eure schnellen Taten Genüge getan, &lt;Name&gt;. Möge sein Tod allen als Warnung dienen, die unsere Heimat bedrohen.\n\nIhr habt diese Belohnung verdient, die Euch auf Euren Reisen helfen soll, &lt;Klasse&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBemalte KettengamaschenNomadenhandschuhe\n\nIhr bekommt außerdem:\n\n"},
[3377] = {title = "Gebet an Elune", objective = "Hört Zamaels Geschichte.", description = "Werdet Ihr mir helfen, sterbliches Wesen? Hört meine Geschichte.", progress = "Erlaubt mir, meine Geschichte zu beenden.", completion = "Ich habe mich mit meinem Schicksal hier in diesem Käfig abgefunden, aber das Gebet muss gefunden werden.", rewards = "Ihr bekommt:\n\n"},
[3378] = {title = "Gebet an Elune", objective = "Findet das Gebet an Elune und bringt es zu Astarii Starseeker in Darnassus.", description = "Werdet Ihr mir helfen, sterbliches Wesen? Werdet Ihr das Gebet an Elune finden?\n\nWie ich bereits sagte, wurde das Gebet auf eine goldene Schrifttafel geätzt. Einer dieser Götzenanbeter muss sie bei sich tragen.\n\nWenn Ihr mein Gebet wiederfindet, bringt es zu Astarii Starseeker in Darnassus. Dass mein Glauben nach den zahllosen widerwärtigen Aktionen, die ich gegen diese Welt und seine Einwohner begangen habe, wiederbelebt wurde, ist vollkommen unwichtig, aber mein Gebet muss gehört werden. Absolution ist das Letzte, was ich erwarte.", progress = "Was führt Euch in den Tempel des Mondes, <Name>?", completion = "Heute Abend lächelt Elune auf Euch herab, &lt;Name&gt;. Ihr habt ihr eine verlorene Seele zurückgebracht. Bitte nehmt dies als ein Zeichen unserer Dankbarkeit.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKaylari-SchulternRunenstahlunterarmschienen\n\nIhr bekommt außerdem:\n\n"},
[3379] = {title = "Schattenweber", objective = "Tötet die Gruppe der Schattenseidewilderer, die in der sengenden Schlucht umherstreifen. Nilith hat Grund zu der Annahme, dass es fünf von ihnen gibt, die ausgeschaltet werden müssen.", description = "Die Spinnen der sengenden Schlucht sind eine unschätzbare Quelle für Schattenseide. Wie Ihr wisst, ist Schattenseide bei den Fachleuten unseres Gewerbes heiß begehrt.\n\nSeit kurzem hat sich eine Gruppe von Wilderern in diesem Land eingenistet, die achtlos massenhaft Spinnen töten, ohne darüber nachzudenken, welche Auswirkungen ihre Taten auf Dauer haben können. Die erste Aufgabe, die ich von Euch verlange, ist recht einfach: Findet sie... und macht ihnen ein Ende.\n\nBeginnt Eure Suche im Norden.\n\nWenn Ihr Hilfe benötigt, sprecht mit Schleifer.", progress = "Welche Informationen bringt Ihr?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;.\n\nIch bin sicher, dass Ihr ein solches Stück Schattenzwirn bis jetzt noch nicht gesehen habt.", rewards = "Ihr bekommt:\n\nSchattenhafte Armschienen"},
[3380] = {title = "Der versunkene Tempel", objective = "Sucht Marvon Rivetseeker in Tanaris.", description = "Es gibt rastlose Geister in dieser Welt, <Name>. Es sind Geister, die durch ihre Einsamkeit besudelt wurden und an ein altes Übel gebunden sind...\n\nIch habe von einem Ort gehört, der tief unter der Erdoberfläche liegt... größere Mächte als ich jemals gesehen habe, haben ihn dorthin verbannt.\n\nWenn Ihr mehr über diesen Ort, den Versunkenen Tempel, erfahren wollt, sucht einen Goblin namens Marvon Rivetseeker auf. Er hat viele alte Gebiete der Welt erforscht. Zuletzt hieß es, dass er sein Heim in Ratchet verlassen habe, um die Trollruinen von Tanaris zu erforschen.", progress = nil, completion = "Ja, der Versunkene Tempel, ich darf behaupten, dass ich ihn mit meinen eigenen Augen gesehen habe. Vielleicht möchtet Ihr etwas mehr darüber erfahren?\n\nIhr scheint mir von der abenteuerlustigen Sorte zu sein - und ich weiß von Dingen, die Euch interessieren könnten ...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3381] = {title = "Ein Treffen mit dem Meister", objective = "Bringt 2 unbeschädigte Hippogryphenfedern zu Sanath Lim-yo in Azshara, wenn Ihr mit seinem Meister sprechen wollt.", description = "Ah, ein <Volk>, noch dazu jung, der mit Sanath sprechen möchte. Was für ein wundervoller Tag! Ich fühle mich so geehrt, dass Ihr mich mit Eurer Anwesenheit beehrt. Danke!\n\nBitte... seid nicht so arrogant anzunehmen, dass mein Sarkasmus ein Kompliment war. Lasst uns eine Sache klarstellen: Ich mag Euch nicht. Aber diese kleine Unterhaltung hat nichts mit uns zu tun... es geht um meinen Meister.\n\nBringt mir ein Paar Hippogryphenfedern für meine Pfeile und ich werde Euch zu ihm führen. Er bat darum, dass ich ihm Abenteurer schicke, sofern sie sich würdig erweisen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVom Azshara-Turm teleportieren\n\nIhr bekommt:\n\n"},
[3382] = {title = "Eine Mannschaft in Bedrängnis", objective = "Verteidigt Kapitän Vanessa Beltis, ihre Mannschaft und die Passagiere der HERRIN DES HORIZONTS gegen den Angriff der Naga. Captain Vanessa Beltis muss überleben.", description = "Wir waren kurz vor der Küste und suchten nach einem sicheren Hafen, um vor Anker zu gehen. Die Sonne war noch keine Stunde untergegangen, als sie angriffen... diese verdammten Naga!\n\nIch weiß nicht genau, wonach sie gesucht haben, aber sie haben es offensichtlich nicht gefunden - sie sind bereits schon einmal wiedergekommen. Einige meiner Späher stehen am Eingang zum Tal Wache, um uns zu warnen, wenn der nächste Angriff kommt.\n\nEs tut mir Leid, dass Ihr gerade jetzt vorbeikommt, <Name>, aber das liegt nicht in meiner Macht.\n\nSeid Ihr bereit für den Kampf Eures Lebens?", progress = nil, completion = "Ihr habt es geschafft! Danke! Das war mit Sicherheit eine der brutalsten Schlachten, an denen ich jemals teilgenommen habe. Ich kann Euch gar nicht genug danken.\n\nIch wünschte nur, ein größerer Teil meiner Mannschaft hätte diese Prüfung überlebt.\n\nIch möchte Euch bitten, mit den überlebenden Passagieren der HERRIN DES HORIZONTS zu sprechen. Einige von ihnen hatten hier geschäftlich zu tun und haben vielleicht ein oder zwei Aufträge für Euch, wenn Ihr wollt. Nochmals danke für all Eure Hilfe.", rewards = nil},
[3385] = {title = "Der Untermarkt", objective = "Erschlagt Handelsmeister Kovic und seinen Diener Clunk. Nehmt den Händlerranzen von seinem Leichnam und bringt ihn zu Nilith.", description = "Sie bezeichnen sich selbst als den Untermarkt: Halsabschneider von Händlern, die verkaufen, verschieben, handeln und zu fast allem bereit sind, vorausgesetzt, der Preis stimmt.\n\nEs kommt noch schlimmer, <Name>. Sie haben einen Stützpunkt für ihre Operationen hier in der sengenden Schlucht errichtet. Handelsmeister Kovic führt diese Operationen an und hat enge Verbindungen zu den Dunkeleisenzwergen des Gebietes.\n\nWir müssen hart zuschlagen und den Anführern ein Zeichen setzen. Erschlagt Handelsmeister Kovic und seinen Diener Clunk. Bringt seinen Händlerranzen zurück, sobald die Tat ausgeführt ist.\n\nZum Kessel!", progress = "Der Handelsmeister lebt noch?", completion = "Ihr habt einen entscheidenden Schlag gegen den Untermarkt geführt. Seine Anführer werden es sich gut überlegen, bevor sie weitere Übeltäter in die Schlucht schicken.\n\nAch, ich habe auch nichts Nützliches im Händlerranzen finden können. Ihr könnt behalten, was immer Ihr im Innern findet.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nSchattenhafter GürtelKovics Handelsranzen"},
[3402] = {title = "Der Untermarkt", objective = "Sprecht mit Vizzklick in Gadgetzan.", description = "Ich will, dass Ihr Vizzklick in Gadgetzan persönlich die Nachricht von Kovics Niederlage überbringt. Ich bin ziemlich sicher, Kovics Tod wird ihn so erfreuen, dass er Euch eine großartige Belohnung geben wird.", progress = nil, completion = "Kovic ist tot??! Was für ein glorreicher Tag, &lt;Name&gt;! Seit Jahren hat dieser Halunke undurchsichtige Untermarktgeschäfte getätigt und so ehrliche und hart arbeitende Händler in der ganzen Welt unterboten und betrogen.\n\nFür diese Leistung verdient Ihr eine feine Belohnung! Und Ihr werdet eine feine Belohnung erhalten!", rewards = "Ihr bekommt:\n\nMuster: Schattenzwirnmaske"},
[3421] = {title = "Rückreise", objective = "Ich werde Euch jetzt zu Sanaths Lager zurückbringen.\n\nMacht Euch nichts aus seinen schlechten Manieren - er ist zu allen unhöflich, außer zum Meister. Vielleicht wird er seine Lektion eines Tages lernen.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVom Azshara-Turm teleportieren"},
[3441] = {title = "Göttliche Vergeltung", objective = "Lasst Velarok Windblade seine Geschichte erzählen.", description = "Hört meine Geschichte, Abenteurer.", progress = "Lasst mich beenden, w... <Volk>.", completion = "Habt Ihr genug gehört? Seid Ihr bereit zu handeln?", rewards = "Ihr bekommt:\n\n"},
[3442] = {title = "Die fehlerlose Flamme", objective = "Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Velarok Windblade.", description = "Ihr habt die richtige Entscheidung getroffen, <Name>.\n\nWir müssen dort zuschlagen, wo wir den größten Schaden anrichten: an den vier Wachpostentürmen.\n\nWenn die vier Wachpostentürme in Flammen stehen, starten wir eine Offensive, bevor sie reagieren können.\n\nIhr benötigt das passende Werkzeug, um die Türme in Brand zu setzen. Für die Herstellung des Werkzeugs wird einiges an Materialien benötigt.\n\nBringt mir vier Herzen der Flamme und vier Kugeln Golemöl, und ich werde die Fackel der fehlerlosen Flamme herstellen können.\n\nIhr solltet Euch also zuerst die Golems und Elementare dieses Landes vornehmen.", progress = "Habt Ihr die Materialien gesammelt?", completion = "Gut gemacht, &lt;Name&gt;. Wir sind fast so weit.", rewards = "Ihr bekommt:\n\n"},
[3443] = {title = "Das Schmieden des Schafts", objective = "Bringt 8 mit Thorium beschichtete Dolche zu Velarok Windblade.", description = "Um die fehlerlose Flamme halten zu können, brauchen wir noch einen Schaft und eine Ummantelung. Ihr müsst zunächst einen geeigneten Schaft finden.\n\nDie Zuchtmeister und Sklavenhändler der Dunkeleisenzwerge des Kessels benutzen Waffen aus verzaubertem Thorium, eine besonders stabile Legierung. Wenn Ihr mir acht mit Thorium beschichtete Dolche bringen könnt, kann ich die Legierung aufbrechen und einen Schaft schmieden.", progress = "Acht, <Name>. Ich brauche acht!", completion = "Ihr seid ein außergewöhnlicher Arbeiter, &lt;Name&gt;. Habt Ihr jemals darüber nachgedacht, einer anderen Berufung zu folgen? Vielleicht der eines Detektivs? Plundersammlers? Oh, ich weiß, Ihr könntet einer dieser dummen Gnome werden, die über die Strände von Azeroth schleichen und mit ihren Metalldetektor-Apparaten nach verlorenen Schätzen suchen. Ja, das wäre ein idealer Beruf für Euch.", rewards = "Ihr bekommt:\n\n"},
[3444] = {title = "Der runde Stein", objective = "Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet.", description = "Ich habe einst die furchteinflößenden Kammern des Versunkenen Tempels betreten. Das Böse an jenem Ort durchdringt alle, die eintreten. Mit Mühe und Not habe ich es geschafft, irgendwie meinen Weg wieder nach draußen zu finden, indem ich durch den Brühschlamm watete, der jetzt den Boden bedeckt. Ich kann mich nur daran erinnern, dass ich durch einen großen, kreisrunden Raum gestolpert bin, der angefüllt war mit Schlangenstatuen ...\n\nKürzlich habe ich einen runden Stein entdeckt, der anscheinend das gleiche Schlangensymbol trägt. Ich habe ihn verpackt und in meine Werkstatt nach Ratchet geschickt. Bringt ihn her und ich kann Euch vielleicht mehr erzählen.", progress = "Ratchet ist nicht weit von hier, <Name>. Die Reise dürfte nicht lange dauern.", completion = "Ja... Das ist der Stein.\n\nIch erinnere mich jetzt an alles, &lt;Name&gt;...", rewards = "Ihr bekommt:\n\n"},
[3445] = {title = "Der versunkene Tempel", objective = "Sucht Marvon Rivetseeker in Tanaris.", description = "Ich habe von einem Ort gehört, der tief unter der Oberfläche der Erde liegt - dorthin verbannt durch größere Mächte, als ich jemals gesehen habe.\n\nWenn Ihr mehr über diesen Ort, den Versunkenen Tempel, erfahren wollt sucht einen Goblin namens Marvon Rivetseeker auf. Genau wie Troyas und ich hat er viele alte Gebiete der Welt erforscht. Zuletzt hieß es, dass er seine Heimstatt in Ratchet verlassen habe, um die Trollruinen von Tanaris zu erforschen.\n\nViel Glück bei Eurer Suche, man hat schon seit längerem nichts mehr von ihm gehört.", progress = nil, completion = "Ja, der Versunkene Tempel, ich darf behaupten, dass ich ihn mit meinen eigenen Augen gesehen habe. Vielleicht möchtet Ihr etwas mehr darüber erfahren?\n\nIhr scheint mir von der abenteuerlustigen Sorte zu sein - und ich weiß von Dingen, die Euch interessieren könnten ...", rewards = "Ihr bekommt:\n\n"},
[3446] = {title = "In die Tiefen", objective = "Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends.", description = "Im Tempel fand ich einen kreisrunden Raum mit sechs Altaren, und am Rand eines jeden stand eine Schlangenstatue. Neugierig drückte ich gegen eine von ihnen, um zu sehen, was passieren würde. Es war eine Falle! Durch die Explosion wurde ich fast getötet. Als ich da auf einem Vorsprung lag, sah ich nach unten und bemerkte, dass eine weitere Statue unten im Raum stand; es war ein Altar der Art ... Hakkar, ich glaube, so wurde er genannt.\n\nIch denke, dass dieser Altar das Geheimnis ist ... Ihr müsst dieses Zeichen zum Altar in den Versunkenen Tempel bringen.", progress = "Während Ihr die Statue untersucht, bemerkt Ihr eine Vertiefung an ihrer Seite, die genau die Größe des Zeichens hat, das Marvon Euch mitgab...", completion = "Ihr legt den runden Stein in die Öffnung hinein und hört, wie er an seinem Platz einrastet.\n\nNun, da der Stein an seinem Platz ist, könnt Ihr weitermachen... aber was solltet Ihr als Nächstes tun?\n\nVielleicht solltet Ihr diesen Altar etwas näher untersuchen...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3447] = {title = "Das Geheimnis des Kreises", objective = "Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt.", description = "Meine Erinnerungen sind verworren, aber ich werde Euch alles sagen, was ich weiß. Der Kreis der Statuen im Versunkenen Tempel mag ja gefährlich sein, ich glaube dennoch, dass sie das Geheimnis eines noch größeren Schatzes in sich bergen.\n\nVom Hauptaltar aus konnte ich eine Reihe von Lichtern aktivieren. Ich glaube, dass Ihr, wenn Ihr die Bedeutung dieser Lichter herausfindet, auch die weiteren Geheimnisse lüften könnt, die sich in diesem Raum verstecken.\n\nAber ich warne Euch, <Name>. In dem Tempel ist etwas unermesslich Böses. Es ist anzunehmen, dass alles Wertvolle äußerst streng bewacht wird.", progress = nil, completion = "Sogar in dem Halbdunkel des Tempels glitzert das Auge des Götzenbildes hell. Seine Transparenz enthüllt etwas Glänzendes, das dahinter versteckt ist. Ihr schiebt es zur Seite, fasst hinein und ergreift das, was im Inneren der Statue liegt.\n\nDer Schatz der Atal'ai gehört nun Euch.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nUrne der Hakkari"},
[3448] = {title = "Die Bürde weitergeben", objective = "Sprecht mit Magier Tymor in Ironforge.", description = "Kürzlich erhielt ich den Auftrag, Azshara zu untersuchen, einen einst wunderschönen Landstrich, den die Elfen ihr Zuhause nannten. Das war damals, als sie noch Magie praktizierten. Jetzt ist es dort eher gefährlich als schön, aber das hält uns nicht davon ab, jeden Stein umzudrehen, um Hinweise auf unsere Vergangenheit zu erhalten.\n\nEin Gefährte von mir namens Tymor bot mir seine Hilfe bei der Untersuchung dieses Gebietes an, da er ein besonderes Interesse an solchen Dingen hat.\n\nEr besitzt ein kleines Anwesen rechts neben der Halle der Mysterien hier in der Stadt.", progress = nil, completion = "Ah, Karnik hat Euch also geschickt? Ich habe darauf gewartet, bald von ihm zu hören. Ich habe solch wundersame Dinge über Azshara erfahren... Ich weiß zwar, dass Nachtelfen eine unglaubliche Lebensspanne haben, aber jeder vergisst doch einige der... unglücklicheren Geschehnisse in seinem Leben. Das ist jetzt nicht als Kritik zu verstehen, es ist nur eine Beobachtung.\n\nVor langer Zeit schufen die Elfen Städte, die erfüllt waren mit Wissen über Magie und andere verlorene Künste. Da ich nun solche Dinge selbst studiere, habe ich meine eigenen Nachforschungen angestellt. Was ich herausfand, war äußerst fesselnd.", rewards = "Ihr bekommt:\n\n"},
[3449] = {title = "Arkane Runen", objective = "Verwendet das Zeichenset, um Abpausbilder von der Rune von Beth'Amara, der Rune von Jin'yael, der Rune von Markri und der Rune von Sael'hai herzustellen, bevor Ihr Euch zu der kleinen Insel vor der südlichen Halbinsel von Azshara aufmacht und dem Piloten Xiggs Fuselighter signalisiert, dass er sie abholen kann.", description = "Einstmals wurde Magie von einigen Elfen genauso verehrt wie Elune selbst. Einige ihrer mächtigsten Magier erstellten Runen und Schrifttafeln, die die Regeln des Arkanen zitierten und Einsichten in ihre Funde gaben. Sie ließen sie an öffentlichen Plätzen aufstellen, damit jeder darüber nachdenken konnte.\n\nIch hätte sehr gern Abpausbilder dieser Runen aus den Ruinen von Eldarath. Ich habe ein Set für Euch, mit dem Ihr Abpausbilder herstellen könnt, aber Ihr müsst sie selbst finden. Seid aber vorsichtig, die Forscherliga ist nicht die Einzige, die sich dafür interessiert.", progress = "Ach nein, wie schön zu sehen, dass Ihr es hierher geschafft habt, <Name>. Konntet Ihr die Abpausbilder für Tymor machen?\n\nAuch wenn es hier ganz schön gefährlich ist, entlang der Küste war nicht viel los. Das kann natürlich an den Naga liegen, die da unter Wasser herumschwimmen, aber das ist nicht mein Problem ... Ich patrouilliere den Himmel.", completion = "Schön, dass Ihr wohlauf und gesund seid, &lt;Name&gt;. Ich hoffe, es war nicht zu anstrengend für Euch.\n\nIch werde das sofort zu Tymor bringen. Er wird so aufgeregt sein, endlich einen Blick darauf werfen zu können.\n\nLos, werft die Leuchtfeuerwaffe weg... wird Euch wahrscheinlich eh nicht mehr viel nützen, und ich hab auch schon eine neue.", rewards = "Ihr bekommt:\n\n"},
[3450] = {title = "Eine einfache Ladung", objective = "Sprecht mit Xiggs Fuselighter in Ironforge.", description = "Ich will diese Abpausbilder sofort in meinen Turm geliefert haben, aber Ihr müsst nicht den ganzen Weg selbst gehen. Ich werde sie einfach per Luftfracht aus Azshara bringen lassen.\n\nXiggs Fuselighter schuldet mir noch einen oder zwei Gefallen und wird sich bald in der Nähe aufhalten - er wurde zur Küstenpatrouille abkommandiert. Sprecht mit ihm, bevor Ihr weggeht. Er kann Euch eine Leuchtfeuerwaffe geben, damit Ihr ihm signalisieren könnt. Sobald Ihr die Abpausbilder zusammen habt, begebt Euch an den Ort, den er Euch nennt und übergebt sie ihm dann, damit er sie sicher zu meinem Turm bringen kann. Er sollte sich im Hangar im Militärviertel aufhalten.", progress = nil, completion = "Was kann ich für Euch tun, &lt;Name&gt;? Bin ein wenig beschäftigt im Moment, bereite mein Schiff für eine lange Reise vor. Kam gerade nur vorbei, um mit einigen Panzerpiloten zu sprechen - ich brauche einige Wendigomähnen um mein Cockpit auszupolstern, und meist haben sie welche übrig.\n\nIhr habt eine Minute, wenn Ihr Euch kurz fasst... einer der Jungs ist gerade zu Steelgrills Depot, um nachzusehen, ob die Piloten dort Mähnen für mich übrig haben.", rewards = "Ihr bekommt:\n\n"},
[3451] = {title = "Signal zum Abholen", objective = "Sprecht mit Xiggs Fuselighter in Ironforge und erhaltet von ihm eine Standardausrüstung-Leuchtfeuerwaffe.", description = "Ah, Tymor hat Euch also geschickt, hm? Ja, dem schulde ich noch einen oder zwei Gefallen. Wie war das? Nein, der kleine Teufel. Ja, da kann ich ihm helfen. Ihr braucht also eine Leuchtfeuerwaffe und einen Ort... nichts leichter als das.\n\nKurz vor der südlichen Halbinsel von Azshara liegt eine kleine Insel, auf der wir eine Landungsplattform gebaut haben. Ihr nehmt diese Leuchtfeuerwaffe und schießt sie dort ab. Ich sehe dann Euer Signal und werde vorbeikommen, um diese... was auch immer er da haben will, mitzunehmen.", progress = nil, completion = "Hier ist meine Standardausrüstung-Leuchtfeuerwaffe, und habt nach dem Abfeuern der Waffe etwas Geduld - diese Sorte hat nur zwei Aufladungen und ich werde wahrscheinlich etwas Zeit brauchen, um bei Euch zu landen, je nachdem, wie weit draußen ich auf See bin.", rewards = "Ihr bekommt:\n\nStandardausrüstung Leuchtfeuerwaffe"},
[3452] = {title = "Die Ummantelung der Flamme", objective = "Bringt ein Symbol von Ragnaros zu Velarok Windblade.", description = "Wir brauchen noch ein letztes Teil, um die Fackel zu formen.\n\nIn den Bergen nordwestlich von hier könnt Ihr ein großes Lager der Twilight-Hammer finden. Es heißt, dass sie Symbole und Götzenbilder zur Verehrung ihres Gottes mit sich herumtragen. Diese Symbole und Götzenbilder besitzen vielleicht genügend Verzauberung, um daraus eine magische Ummantelung herzustellen. Bringt mir ein einziges Symbol von Ragnaros und ich werde versuchen, die Magie aus dem Gegenstand zu extrahieren, um die Ummantelung zu erschaffen.", progress = "Ohne die geeignete Quelle arkaner Energie kann die Fackel der Vergeltung nicht vollendet werden.", completion = "Das Symbol strahlt elende Magie aus; wunderbar geeignet für unsere Zwecke.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3453] = {title = "Die Fackel der Vergeltung", objective = "Wartet bis Velarok Windblade die Fackel der Vergeltung vollendet hat.", description = "Gebt mir einen Augenblick, um die Teile zusammenzufügen und die notwendigen Verzauberungen anzuwenden.", progress = nil, completion = "Ihr müsst noch eine allerletzte Aufgabe erledigen.", rewards = "Ihr bekommt:\n\n"},
[3454] = {title = "Die Fackel der Vergeltung", objective = "Nehmt die Fackel der Vergeltung.", description = "Die Fackel muss jetzt an ihren Besitzer gebunden werden. Nehmt die Fackel auf, <Name>.", progress = nil, completion = "Ihr greift die Fackel mit beiden Händen, und Wellen von Hass und Wut pulsieren durch Euer ganzes Wesen.", rewards = "Ihr bekommt:\n\nFackel der Vergeltung"},
[3461] = {title = "Rückkehr zu Magier Tymor", objective = "Bringt Magier TymorsZeichenset zu ihm zurück nach Ironforge.", description = "Tymor hat mir nichts gegeben, um Euch zu bezahlen, also schlage ich vor, dass Ihr das mit ihm besprecht, wenn Ihr zurück in Ironforge seid. Ich bin mir sicher, er wird dann immer noch an seiner Wohnung im Mystikerviertel sein. Klopft einfach bei ihm an, und er soll Euch ja gut bezahlen. Das hier ist nicht gerade ein Spaziergang... das ist schon mal sicher.\n\nDanke nochmals für Eure Hilfe und viel Glück.\n\nOh, das Zeichenset brauche ich nicht. Warum bringt Ihr es nicht selbst Tymor zurück, wenn Ihr ihn besucht?", progress = "Ihr seid zurück! Exzellent. Habt Ihr auch mein Zeichenset dabei?", completion = "Großartig! Es freut mich, das zu hören.\n\nIch kann es kaum erwarten, in meinen Turm zu kommen und die ganzen Abpausbilder zu betrachten. Ich beneide Euch sehr... an einen Ort wie Azshara zu reisen. Das ist der Traum eines jeden Arkanen-Schülers, nehme ich an.\n\nNun, wir haben nie über irgendeine Belohnung gesprochen, da Ihr ja gerade für die Forscherliga gearbeitet habt, aber Ihr verdient etwas.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchienbeinschützer des StahlschmiedsSchädelzauberkugel\n\nIhr bekommt außerdem:\n\n"},
[3462] = {title = "Knappe Maltrake", objective = "Sprecht mit dem Knappen Maltrake.", description = "Sprecht mit meinem Gesandten, dem Knappen Maltrake. Er wird Euch weiter unterweisen, wie die Fackel der Vergeltung zu benutzen ist.", progress = nil, completion = "Seid Ihr bereit, Euren Schlag auszuführen?", rewards = "Ihr bekommt:\n\n"},
[3463] = {title = "Setzt sie in Brand!", objective = "Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt.", description = "Hört gut zu, <Name>. Obgleich die vier Türme niemals zerstört werden können, könnt Ihr dennoch die Fackel der Vergeltung benutzen, um sie für lange Zeit in Brand zu setzen. Ein Feuer, das kein Element und keine Macht löschen kann.\n\nWährend sie in Flammen stehen, kann keine Wache oder Wachposteneinheit die Posten besetzen, und so ist ihre erste Verteidigungslinie außer Kraft gesetzt.\n\nIhr müsst in jeden Turm eindringen und die Fackel der Vergeltung innerhalb ihrer Befestigung verwenden. Nehmt Euch in Acht vor den Elitewachposteneinheiten der Dunkeleisenzwerge, <Name>.", progress = "Habt Ihr Euch verlaufen, <Name>?", completion = "Es ist glorreich! Ist es nicht glorreich, Meister?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDrachenschwarm-GamaschenDrachenfeuerkopfschutzAxt des Ebenholzdrachen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[3481] = {title = "Plunder...", objective = "Öffnet die Truhe.", description = "Die Truhe scheint verschlossen zu sein.", progress = nil, completion = "Bei Eurer Berührung öffnet sich die Truhe. Wie viel Käse kann hier wohl drin sein? Es gibt nur einen Weg, das herauszufinden.", rewards = "Ihr bekommt:\n\nHort des schwarzen Drachenschwarms"},
[3483] = {title = "Signal zum Abholen", objective = "Ah, noch eine Leuchtfeuerwaffe, hm? Die kann ich Euch geben.\n\nUnd vergesst nicht, Südspitze von Azshara. Es ist eine kleine Insel, die in eine Landungsplattform verwandelt wurde. Ihr könnt sie gar nicht verfehlen, wenn Ihr an der richtigen Stelle sucht.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStandardausrüstung Leuchtfeuerwaffe"},
[3501] = {title = "Im Dutzend besser", objective = "Bringt Kum'isha unvollständige Draenethystfragmente und Ihr werdet für jedes, das Ihr bringt, belohnt.", description = "Obgleich Ihr wohl niemals eine fehlerlose Draenethystsphäre finden werdet, könnt Ihr zweifelsohne auf Euren Reisen durch dieses Land einige unvollständige Draenethystfragmente entdecken.\n\nEs ist zwar unwahrscheinlich, dass Kum'isha die fehlerhaften Fragmente benutzen kann, um nach Hause zurückzukehren, dennoch können diese Stücke für andere nützliche Zwecke der Draenei dienen.\n\nBringt mir alle fehlerhaften Draenethystfragmente, die Ihr finden könnt, und ich werde Euch belohnen.", progress = "Hattet Ihr Glück bei Euren Forschungen?", completion = "Ihr widert mich an, &lt;Volk&gt;. Ein erwachsener Mann, sabbernd über einem Haufen Plunder? Jämmerlich! Nehmt Eure Belohnung und geht mir aus den Augen.", rewards = "Ihr bekommt:\n\nKum'ishas Plunder"},
[3502] = {title = "Des einen Draeneis Plunder...", objective = "Bringt Kum'isha unvollständige Draenethystfragmente. Jede Art von Monster in den verwüsteten Landen könnte ein Fragment bei sich tragen.", description = "Nach einer solchen Zurschaustellung von ekelhafter Gier ist mir richtig übel.\n\nWie dem auch sei, ich werde mich nicht allzu lange mit Eurer materiellen Abhängigkeit beschäftigen.\n\nFür jedes unvollständige Draenethystfragment, das Ihr mir bringt, werde ich Euch mit weiterem Plunder belohnen. Mein Haufen Plunder wird kleiner werden, und der Eurige dafür anwachsen. Auf Draeneor nennen wir das eine Situation, bei der alle nur gewinnen können.", progress = "Also? Draenethyst? Erinnert Ihr Euch?\n\n<Kum'isha ballt seine Faust und klopft an Euren Kopf.>\n\nJemand zu Hause?", completion = "Ihr widert mich an, &lt;Volk&gt;. Ein erwachsener Mann, sabbernd über einem Haufen Plunder? Jämmerlich! Nehmt Eure Belohnung und geht mir aus den Augen.\n\nKommt Euch das bekannt vor? Das sollte es, denn ich sage das ungefähr tausend Mal am Tag.\n\nOh, wie ich diese Welt verabscheue.", rewards = "Ihr bekommt:\n\nKum'ishas Plunder"},
[3503] = {title = "Treffen mit dem Meister", objective = "Es gab Zeiten, in denen ich alles von denen, die meinen Meister aufsuchen wollten, verlangen konnte. Heute ist es anders, Ihr müsst nur nach ihm fragen und ich schicke Euch zu ihm.\n\nEs ist ärgerlich für mich, aber ich stelle seine Befehle nicht in Frage. Ich kann mich lediglich an Eurer lächerlichen Aufmachung oder Eurem jämmerlichen Gesichtsausdruck erfreuen. Selbst das langweilt mich...\n\nSogar dieses Geschwafel langweilt mich! Möchtet Ihr meinen Meister sehen oder nicht?", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVom Azshara-Turm teleportieren"},
[3504] = {title = "Verraten", objective = "Bringt den versiegelten Brief zu Ag'tor Bloodfist nach Azshara.", description = "Verräterische, diebische Elfin! So nenne ich sie... und genau das wird sie immer sein!\n\nIch habe wahrscheinlich einen großen Fehler gemacht, <Name>. Ich habe einem Blutelfen vertraut.\n\nSie behauptete, in Azshara lägen große Reichtümer... mächtige Gegenstände. Ich sollte ihr nur ein paar Krieger zu ihrem Schutz schicken und dafür würde ich belohnt. Und wer ist jetzt wohl der Dumme - sie hat sie alle umgebracht.\n\nIch will Rache, <Name>, aber ich kann es mir nicht leisten, noch jemanden zu schicken. Sucht Ag'tor bei Valormok auf, nördlich des Lagers der Haldarr. Er kann Euch mehr berichten.", progress = "Ah, Belgrom ist schließlich zur Vernunft gekommen und hat jemanden geschickt, der nicht zu seinesgleichen gehört, um uns zu helfen, wie?\n\nDieses Lager wurde einmal von einem Dutzend Krieger bewohnt, <Name>, aber jetzt sind sie alle tot. Diese Magierin, Rimtori, hat sie alle getötet. Sie hat mit Belgrom gespielt wie mit einer Puppe... hat ihn sogar verführt. Es geht mich zwar nichts an, aber ganz unter uns, sie ist eine ziemliche Verführerin. Das ist wahrscheinlich der Grund, warum ich immer noch hier bin und Belgrom helfe, ich hätte nämlich bestimmt genauso gehandelt.", completion = "Wir haben alles, was wir hatten, gegen sie und ihre Tagelöhner geschickt, aber sie sind sehr stark im Kampf. Keiner ist zurückgekehrt. Ich nehme zwar an, dass einige gestorben sind, aber ich bin sicher, dass andere einfach wegliefen... diese Feiglinge.\n\nAber da nun Verstärkung eingetroffen ist, können wir vielleicht doch noch was ausrichten. Vielleicht können wir sie für ihre Lügen und den Verrat an Belgrom bestrafen.\n\nWas sagt Ihr dazu, seid Ihr dabei?", rewards = "Ihr bekommt:\n\n"},
[3505] = {title = "Verraten", objective = "Tötet 10 Blutelf-Wiederbeschaffer und 10 Blutelf-Feldmesser, bevor Ihr Magus Rimtoris Lager sucht. Sobald Ihr es gefunden habt, sucht nach etwas, das für sie von Bedeutung ist und das wir nehmen können, um sie in einen Kampf zu locken.", description = "Das hatte ich mir gedacht.\n\nWir werden unseren Kreuzzug gegen ihre Tagelöhner entlang der westlichen Steilhänge an der nördlichen Halbinsel von Azshara beginnen. Tötet sie mit blutiger Wut - lasst sie wissen, dass sie die falschen Verbündeten verraten haben.\n\nUm sie selbst müsst Ihr Euch jetzt noch nicht kümmern - sie verbringt die meiste Zeit zusammen mit ihren Leibwachen auf der Suche nach Azshara. Es ist wahrscheinlich am klügsten, erst ihre Tagelöhner zu erschlagen und dann ihr persönliches Lager zu suchen. Es wäre weise auszukundschaften, wo wir sie angreifen können. Vielleicht gibt es ja etwas, womit wir sie provozieren können.", progress = "Der Titel des Buches ist mit Goldbuchstaben in den schwarzen Ledereinband eingeprägt... Kaldorei-Foliant der Beschwörung. Während Ihr die Seiten aufschlagt, erkennt Ihr, dass das Buch zwar sehr alt, aber in einem sehr gut erhaltenen Zustand ist.\n\nIhr geht davon aus, dass der Text in einer uralten Sprache geschrieben wurde... vielleicht Kaldorei?\n\nEuer Instinkt sagt Euch, dass Ihr hierher zurückkehren solltet, sobald Ihr bei den Blutelfen Vergeltung für ihren Verrat geübt habt.", completion = "Ihr blättert einige Seiten durch, bis Ihr an eine Seite kommt, die mit einem dünnen, schwarzen Seidenstreifen markiert wurde.\n\nWährend Ihr versucht, das Manuskript zu entziffern, entdeckt Ihr ein Diagramm unten auf einer der Seiten. Ihr seht Euch kurz um und bemerkt, dass die Kristalle, der Kreis und auch andere Komponenten auf dem Boden ein Muster ergeben, dass dem des Diagramms im Buch sehr ähnlich ist.", rewards = "Ihr bekommt:\n\n"},
[3506] = {title = "Verraten", objective = "Zerstört den arkanen Fokussierkristall, der an Magus Rimtori gebunden ist, und tötet sie danach. Bringt dann den Kopf von Magus Rimtori zu Ag'tor Bloodfist nach Azshara.", description = "Nach einigen Momenten des Nachdenkens kommt Ihr auf ein paar Ideen, eine davon bringt Euch zum Lächeln: Vielleicht würde die Zerstörung der Kristalle die Blutelfin ärgern, die für das Abschlachten so vieler Orcs und den Verrat an Belgrom verantwortlich ist?\n\nIhr fahrt fort, mehr vom Manuskript und den Bildern zu entschlüsseln und erkennt, dass einer der Kristalle an den Schöpfer des Kreises gebunden ist - die anderen sind an etwas weitaus Finstereres gebunden.\n\nIhr schließt das Buch und beginnt Euch zu entscheiden, welchen Kristall Ihr zerstören wollt.", progress = "Wie geht Euer Beseitigen der Blutelfen-Verräter voran, <Name>? Konntet Ihr Fortschritte machen?\n\nIch hoffe, dass Ihr stark genug seid, diese Hündin in die Knie zu zwingen! Sie verdient für das, was sie getan hat, nur eines: einen schmerzhaften Tod!", completion = "RAR!! Unglaublich!\n\nIhr habt es geschafft! Das wird Belgrom erfreuen! Nun endlich können die Geister von Dutzenden unserer Krieger ihren Frieden finden. Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[3507] = {title = "Verraten", objective = "Sprecht mit Belgrom Rockmaul in Orgrimmar.", description = "Kehrt zu Belgrom nach Orgrimmar zurück. Er wird ihren Kopf höchstpersönlich sehen wollen. Wir werden in Kürze dorthin zurückkehren.\n\nAh, dies ist heute wahrlich ein Freudentag. Danke für Eure Hilfe, <Name>.", progress = "Ich erinnere mich an Euch, <Klasse>. Ich habe Euch gebeten, nach Azshara zu gehen und dieses Weib zu erledigen, das mich verraten hat! Das scheint so viele Monde her zu sein. Sagt mir nicht, dass Ag'tor und die anderen auch tot sind!", completion = "HAHA! Sieh dich an, lächerliches Weib! Ich spucke auf deine Überreste!\n\nDanke, &lt;Name&gt;. Ich danke Euch aus tiefstem Herzen! Das ist wirklich ein großer Tag!\n\nWenn es in meiner Macht stünde, würde ich Euch ein Königreich geben! Aber ich hoffe, Ihr seid auch hiermit zufrieden.\n\n\n\nHa-ha! Blöde Blutelfin, schau dich nur mal an... in einem Sackleinenbeutel und ohne Körper! Du hättest Belgrom nicht verraten sollen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPyrosteinkugelBelgroms Hammer\n\nIhr bekommt außerdem:\n\n"},
[3508] = {title = "Den Zauberschutz brechen", objective = "Wartet, bis Loramus den Erleuchtungszauber vollendet hat.", description = "Ihr seid tollkühn, <Name>. Es ist eine bewundernswerte Eigenschaft Eurer Art, sich blind in die Schlacht zu stürzen, auch wenn nur wenig oder gar keine Aussicht auf Erfolg besteht. Ich werde Euch behilflich sein, sei es auch nur, um einen einzigen von Razelikhs Dienern fallen zu sehen.\n\nDen Zauberschutz, der auf Razelikhs Untergebenen liegt, zu brechen, kostet Zeit und macht es nötig, rare Artefakte zu erwerben.\n\nSeid still, ich muss erst das Erleuchtungsritual durchführen. Die Information, die ich dabei erhalte, wird mir helfen, Waffen von großer Macht zu schmieden.", progress = nil, completion = "Der Name der Bestie muss erst gefunden werden.", rewards = "Ihr bekommt:\n\n"},
[3509] = {title = "Der Name der Bestie", objective = "Sprecht mit Lord Arkkoroc in Azshara. Beginnt Eure Suche am Rand des Wassers, um den Tempel von Arkkoran zu finden.", description = "Es gibt nur eine Möglichkeit, den Dämonenlord und seine Diener zu verletzen. Eine Waffe der Macht muss geschmiedet werden, die seinen wahren Namen trägt.\n\nWird eine solche Waffe geschmiedet, sind der Dämon und alle, die unter seinem Kommando stehen, verwundbar.\n\nIn Azshara residiert eine geringe Gottheit: Lord Arkkoroc. Ihn müsst ihr aufsuchen. Aber seid gewarnt - wenn man Euch entdeckt, werden seine Diener alles tun, um Euch zu vernichten.\n\nZweifelsohne müsst Ihr einen Preis für solche Informationen bezahlen.", progress = nil, completion = "Ein Dämonenlord?\n\n&lt;Lord Arkkoroc lacht.&gt;\n\nVielleicht kann der Eine Euch mit der passenden Information helfen, doch vorher müsst Ihr dem Einen helfen.", rewards = "Ihr bekommt:\n\n"},
[3510] = {title = "Der Name der Bestie", objective = "Erschlagt Hetäre und bringt den blutigen Hetärenkopf, den geschlagenen Hetärenkopf und den verwundeten Hetärenkopf zu Lord Arkkoroc.", description = "Sie tötet meine Kinder, sterbliches Wesen. Sie nennt sich selbst die Herrscherin dieser Meere. Eine falsche Göttin, nichts weiter. Zermalmt sie und bringt mir all ihre Köpfe.\n\nDafür erhaltet Ihr den Namen, den Ihr sucht, und etwas anderes von gleicher Bedeutsamkeit.\n\nSie weilt im Gelege... Genannt wird sie Hetäre.\n\n<Lord Arkkoroc zeigt in Richtung Südwesten.>\n\nGeht!", progress = "<Lord Arkkoroc beugt sich nach unten, um Euch zu betrachten.>\n\nWo sind sie?", completion = "Endlich jemand, der der Weisheit von Arkkoroc würdig ist!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3511] = {title = "Der Name der Bestie", objective = "Bringt den Härter zurück zu Loramus Thalipedes.", description = "Wie versprochen, werde ich den Namen des Dämonenlords enthüllen: Es ist Razelikh der Entweiher. Zuerst muss ich jedoch etwas vorbereiten, das für Eure Reise von äußerster Wichtigkeit ist.\n\nDie Waffe, die Ihr herstellen wollt, benötigt einen Härter. Gebt mir einen Moment Zeit, um das Blut aus diesen Köpfen herauszupressen.\n\n<Lord Arkkoroc drückt die Köpfe mit seinen gigantischen Fäusten zusammen, sodass das Blut aus ihnen herausfließt.>\n\nBringt diesen Härter zurück zu Loramus, zusammen mit dem Namen der Bestie: Rakh'likh.", progress = "Ihr seid zurückgekehrt! Erstaunlich, <Volk>. Habt Ihr den wahren Namen erfahren?", completion = "Durch den Härter wird das notwendige Vitriol, das wir zum Schmieden der Waffen benötigen, hinzugefügt. Es fehlt nur noch ein Schritt bis zu ihrer Herstellung.", rewards = "Ihr bekommt:\n\n"},
[3512] = {title = "Mit Eranikus' eigenen Worten", objective = "Reist in den östlichen Teil von Winterspring und sprecht mit Umbranse, dem Geistsprecher.", description = "<Name>, als Erstes werden wir eine Methode ersinnen, um durch den Edelstein mit Eranikus zu sprechen. Zurzeit befindet er sich in einem gefährlichen Zustand zwischen Schlaf und Tod, verstrickt in ein Gewebe aus Alpträumen. Zwar ist die Essenz, die Ihr mir gegeben habt, stark besudelt, aber es gibt dennoch Hoffnung, dass wir zu ihm durchdringen.\n\nReist weit hinaus in das eisige Land des östlichen Winterspring und sucht einen unserer sterblichen Verbündeten, Umbranse den Geistsprecher. Er ist ein menschliches Medium, der für die Toten spricht. Zwar ist Eranikus noch nicht wirklich tot, trotzdem könnte er uns eine Hilfe sein.", progress = nil, completion = "Itharius war sehr weise, Euch zu mir zu senden. Eranikus ist in Eurem Sinne nicht wirklich tot, er wird uns bald mit seinen eigenen Worten Ratschläge erteilen. Im Moment vermag ich Euch nicht direkt zu helfen... zumindest noch nicht.\n\nIch werde Euch meine Fertigkeit des Totensprechens gern zur Verfügung stellen, aber zunächst benötige ich die Hilfe von jemandem, der - im Gegensatz zu mir - nicht durch die Gebrechlichkeit des Alters eingeschränkt ist. Mein machtvollstes Vorzeichengerät wurde mir gegen meinen Willen genommen, und solange ich es nicht wieder zurückerhalten habe, werden wir Eranikus nicht helfen können.", rewards = "Ihr bekommt:\n\n"},
[3513] = {title = "Die runenverzierte Rolle", objective = "Bringt die runenverzierte Rolle zum nördlichen Wachturm des Brachlandes.", description = "Die offiziell aussehende Rolle wurde mit einem silbrigen Band eng verschnürt. Ihr seid Euch sicher, dass jemand das hier sehen möchte, aber wer?\n\nEs gibt einen Außenposten im Norden in der Nähe der Grenze von Ashenvale, und wenn die Informationen auf dieser Rolle die Nachtelfen betreffen, dann sollte die Rolle dorthin gebracht werden.", progress = "Was habt Ihr da?", completion = "Ach... Wo habt Ihr das gefunden?", rewards = "Ihr bekommt:\n\n"},
[3514] = {title = "Hordenpräsenz", objective = "Tötet die Anführerin des Krallenbaus, Rynthariel die Schlüsselmeisterin.", description = "Diese Rolle ist von der Ränke schmiedenden Dryade Rynthariel, Schlüsselmeisterin des Krallenbaus auf dem Steinkrallengipfel.\n\nMit dem Boten, von dem Ihr diese Rolle erbeutet habt, hat sie jetzt ja wohl keinen Kontakt mehr, aber nachgeben dürfen wir trotzdem nicht. Die Horde wird ihre Kundschafter hier nicht tolerieren.\n\n<Name>, reist zum Krallenbau. Tötet Rynthariel und stellt ein Symbol auf, das alle sehen können. Nehmt diese Hordenflagge mit Euch, <Name>. Hisst sie im Krallenbau, damit sie es sich zweimal überlegen, bevor sie einen weiteren Boten durch unser Gebiet schicken.", progress = nil, completion = "Ihr seid ganz schön dreist! Rynthariel aus dem Bau zu beseitigen, ist ein großer Schritt, &lt;Name&gt;. Sie werden sich nur langsam neu formieren und so können wir im Brachland künftig mit weniger Allianzläufern rechnen. Sie werden es sich gut überlegen, bevor sie noch mal einen hier entlangschicken.\n\nDanke.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWegbereiter-StiefelJutezopf-Handschuhe\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[3517] = {title = "Wissen stehlen", objective = "Sucht die Schrifttafel von Beth'Amara, die Schrifttafel von Jin'yael, die Schrifttafel von Markri und die Schrifttafel von Sael'hai, bevor Ihr zu Jediga in Azshara zurückkehrt.", description = "Ich muss zugeben, <Name>, ich habe das Beste aus meiner Situation in Azshara gemacht. Belgroms Bestrafung hatte schon seine Vorteile.\n\nBevor ich wegging, habe ich einige Nachforschungen angestellt. Ihr wärt überrascht darüber, wie viele wertvolle Gegenstände hier einfach so herumliegen.\n\nIch erzähle Euch noch mehr von meinen Geschäften und gebe Euch sogar einen Anteil an meinen Gewinnen, wenn Ihr mir helft, ein paar von den Sachen einzusammeln.\n\nIn den östlichen Ruinen von Eldarath gibt es Schrifttafeln, die ich benötige. Alle vier wurden nach Hochgeborenenhexern benannt. Bringt sie mir und wir können weiterreden.", progress = "Die Schrifttafeln, die Ihr für mich sammeln sollt, dürften den richtigen Leuten ein hübsches Sümmchen einbringen. Ich werde Euch sagen, an wen sie geliefert werden sollen, sobald Ihr sie gefunden habt. Ich bin nicht dumm... Ihr werdet Euren Anteil erst bekommen, wenn ich den Beweis erhalten habe, dass sie geliefert worden sind.\n\nAlso macht Euch an die Arbeit... wir haben nicht den ganzen Tag Zeit. Sonst muss ich vielleicht einen anderen suchen, der mir behilflich ist.", completion = "Wunderbar, &lt;Name&gt;, und auch noch in gutem Zustand. Dies sollte uns von den beteiligten Gruppen einen guten Preis einbringen.\n\nLasst uns hier nicht länger als nötig verweilen. Lasst uns Geld verdienen.", rewards = "Ihr bekommt:\n\n"},
[3518] = {title = "Lieferung an Magatha", objective = "Bringt die Schrifttafel von Beth'Amara zu Magatha in Thunder Bluff.", description = "Die erste Schrifttafel geht an einen weiblichen Tauren... mit Namen Magatha. Sie gehört zu den Ältesten in Thunder Bluff und zu den Befürwortern der Allianz zwischen den Tauren und den Verlassenen. Sie ist mehr als jeder andere der Ältesten der Meinung, dass die Tauren und ihre Lebensart den Verlassenen helfen können, einen Weg zurück zum Menschsein zu finden.\n\nBringt Ihr die Schrifttafel von Beth'Amara. Die Schrifttafel kann das fehlende Glied sein, das sie benötigt, um den Verlassenen zu helfen... das behauptet sie jedenfalls.", progress = "Ja, <Name>. Was kann ich für Euch tun? Ich muss mich um viele Dinge kümmern, also fasst Euch bitte kurz.", completion = "Ah, endlich, die Schrifttafel von Beth'Amara. Ich fragte mich schon, ob meine Zusammenarbeit mit Jediga ein Fehler war oder ob die Arme in Azshara ihren Tod gefunden hat. Ich freue mich, dass sie erfolgreich war.\n\nBeth'Amara war einer der einflussreichsten Alchimisten der Hochgeborenen. Unter anderem wird gesagt, dass der Hexer in der Lage war, Metall zu transmutieren.", rewards = "Ihr bekommt:\n\n"},
[3519] = {title = "Ein Freund in Not", objective = "Sprecht mit Dirania Silvershine in Shadowglen.", description = "Aghhh... Ich wurde ziemlich schlimm von einer Spinne namens Githyiss die Üble gebissen, während ich die Spinnenhöhle ganz in ihrer Nähe erforschte. Ich bin sicher, dass ich ernsthaft vergiftet bin; Ihr müsst mir helfen.\n\nSagt es bitte Dirania Silvershine. Sie wird mir helfen können.\n\nBeeilt Euch... Mir ist so schwindelig...", progress = nil, completion = "Oh nein, ich habe mich schon gefragt, warum ich Iverron heute noch nicht gesehen habe. Dabei habe ich ihn immer vor diesen Spinnen gewarnt.", rewards = "Ihr bekommt:\n\n"},
[3520] = {title = "Kreischergeister", objective = "Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya in Steamwheedle zurück.", description = "Ich suche die Geister der Talkreischer von Feralas. Sie sind die Cousins eines alten, alten Gottes und ihre Geister sind mit ihm verbunden.\n\nNehmt diesen Dornbuschzauberstab und reist nach Feralas. Sucht und besiegt die Talkreischer in Süd- und Mittel-Feralas, und schwingt meinen Dornbuschzauberstab dann über ihre gefallenen Körper. Dadurch wird ihr Geist dazu gebracht, sich zu zeigen. Berührt den Geist und sammelt seine Essenz.\n\nKommt mit meinem Dornbuschzauberstab und der gesammelten Essenz zu mir zurück, und ich werde Euch mehr von dem alten Gott erzählen, von dem ich sprach.", progress = "Habt Ihr die Essenz der Kreischergeister gesammelt, <Name>?", completion = "Ihr habt Eure Sache gut gemacht, &lt;Name&gt;. Vielleicht ist es jetzt an der Zeit, mehr zu erzählen...\n\nEs gibt bei den Trollen eine alte Prophezeiung, laut der der tote Gott Hakkar der Seelenschinder eines Tages auf diese Erde zurückkehren wird. Einige sagen, die Ankunft von Hakkar würde Freude und Ruhm für alle Trolle bringen, andere glauben hingegen, dass seine Auferstehung das Ende aller Dinge bedeutet.\n\nIch glaube diese Geschichten nicht, aber ich weiß, dass die Essenz von Hakkar eine große Macht enthält, und diese Macht sollte von jenen fern gehalten werden, die sie missbrauchen würden...", rewards = "Ihr bekommt:\n\n"},
[3521] = {title = "Iverrons Gegengift", objective = "Sammelt 7 Hyazinth-Pilze, 4 Mondblütenlilien und 1 Waldwebersekret für Dirania Silvershine in Shadowglen.", description = "Wir dürften in der Lage sein, Iverron zu helfen, denn ich kenne ein Gegengift, das gegen das Gift wirkt. Bevor ich es herstellen kann, benötige ich allerdings einige Zutaten.\n\nIch brauche Hyazinth-Pilze. Sie wachsen unter Bäumen. Ihr könnt sie aber auch von den Grell südlich von hier sammeln; sie scheinen sie sehr zu mögen. Außerdem brauche ich noch Mondblütenlilien, die nur an Wasserteichen wachsen.\n\nDie letzte Zutat könnte die Schwierigste sein. Sammelt Waldwebersekret von genau den Spinnen, die Iverron vergiftet haben.", progress = "Bitte sammelt die Zutaten, <Name>. Iverron braucht unsere Hilfe!", completion = "Elune sei Dank, dass Ihr diese Zutaten so schnell gesammelt habt.\n\nEs dauert nur einen Moment, bis ich das Gegengift zubereitet habe.", rewards = "Ihr bekommt:\n\n"},
[3522] = {title = "Iverrons Gegengift", objective = "Bringt Iverrons Gegengift zu Iverron, bevor die Zeit um ist. Ihr findet Iverron bei der Höhle im Norden.", description = "Das Gegengift ist fertig, <Name>. Bitte achtet darauf, dass Iverron es auch trinkt.\n\nEs gibt jedoch etwas, das Ihr wissen sollt: Das Gegengift ist nur 5 Minuten wirksam. Ihr müsst es ihm rechtzeitig bringen.\n\nMögen Eure Füße beflügelt sein, <Name>.", progress = "Oh... <Name>, ich bin so froh, dass Ihr wieder zurückgekommen seid.", completion = "Was ist das, &lt;Name&gt;?\n\nOh, ich wusste, Dirania würde mir helfen können!\n\n\n\nIch gerate ständig in Schwierigkeiten und Dirania, na ja, sie schafft es immer wieder, mir da herauszuhelfen.\n\nIch fühle mich schon viel besser, aber ich denke, ich werde hier noch eine Weile sitzen bleiben, bis ich wieder ganz in Ordnung bin. Na ja, das ist der eine Grund, und ich hoffe außerdem, dass Ihr für mich einen Weg durch diese heimtückischen Waldweberspinnen frei macht...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSeggenried-KniehosenRindenpanzerweste\n\nIhr bekommt außerdem:\n\n"},
[3523] = {title = "Geißel der Niederungen", objective = "Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab.", description = "Phantastisch! Mein Name ist Belnistrasz und ich danke Euch für meine Rettung. Ich hatte mich schon tot gewähnt... oder schlimmer, als Mahlzeit für dieses von der Geißel befallene Gezücht. Ja, richtig gehört, ich sagte Geißel; sie haben anscheinend mit den Stachelebern hier eine Art Vereinbarung getroffen, und dieser Alptraum ist das Ergebnis.\n\nHört mir zu... anstatt einfach wegzulaufen, möchte ich doch uns allen zuliebe versuchen, etwas zu ändern. Könntet Ihr mir dabei helfen? Es ist wahrscheinlich gefährlich, aber Ihr scheint ein Typ zu sein, dem das nicht viel ausmacht.", progress = "Ich schere mich nicht um Politik; mich interessiert nicht, ob Ihr Euch auf die Seite der Horde oder der Allianz schlagt. Ich bin eher daran interessiert, direkte und schreckliche Drohungen gegen alle Völker auszuschalten... und das hier ist eine ziemlich große.\n\nWenn Ihr willens seid, für alle Völker ein wahrer Held zu sein, dann übergebt mir den Schwurstein, den ich Euch gab, als Zeichen der Verpflichtung. Ich bin... nicht aus dieser Gegend, ein Schwurstein bedeutet für Leute wie mich ein Bund der Übereinkunft.", completion = "Phantastisch, ich dachte schon, dass Ihr heldenmutig ausseht! Ich will Euch nicht anlügen, &lt;Name&gt;, wir haben eine Menge Arbeit vor uns. Wenn wir uns auf die vor uns liegende Aufgabe konzentrieren, sollten wir in der Lage sein, als Sieger aus der Sache hervorzugehen.\n\nJetzt will ich Euch auf den neuesten Stand der Dinge bringen ...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3524] = {title = "An Land gespült", objective = "Sammelt Meereskreaturknochen von der gestrandeten Meereskreatur unmittelbar südlich von Auberdine und kehrt dann mit ihnen zu Gwennyth Bly'Leggonde nach Auberdine zurück.", description = "Majestätische Meereskreaturen begeben sich häufig an die Ufer von Dunkelküste, und liegen dort gestrandet, bis sie sterben. Vor kurzem wurden diese Kreaturen in immer größerer Zahl an Land gespült. Ich wurde vom Tempel des Mondes zur Untersuchung dorthin geschickt, aber die Anwesenheit der Murlocs entlang des Wassers hat meine Forschungen schwierig gemacht.\n\nEs gibt eine riesige Kreatur, die unmittelbar südlich von Auberdine an Land gespült wurde und die von den widerlichen Grauflossenmurlocs umringt ist. Könntet Ihr Euch dorthin begeben und Knochen von dieser Kreatur für unsere Studien sammeln?", progress = "Diese Kreaturen begannen erst vor kurzem, in solch alarmierender Zahl an den Ufern von Dunkelküste zu landen. Ich kann mir nicht helfen, aber ich glaube, dass dies irgendein schlechtes Omen ist. Wenn Ihr eine Probe der Knochen dieser Kreatur im Süden beschaffen könntet, würde uns das in Darnassus sehr bei der Einschätzung der Situation helfen!", completion = "Ich hoffe, die Murlocs haben Euch keine allzu großen Schwierigkeiten bereitet, als Ihr das für uns geholt habt! Ich werde das definitiv mit dem nächsten Hippogryph nach Darnassus schicken. Der Tempel des Mondes hat mir einige Geldmittel zur Verfügung gestellt, um damit Hilfe zu belohnen; bitte nehmt dies mit unserem Dank.\n\nAufgrund Eures Erfolges hier wage ich, Euch eine Gelegenheit zu bieten, dem Tempel des Mondes erneut zu helfen, falls Ihr interessiert seid ...", rewards = "Ihr bekommt:\n\n"},
[3525] = {title = "Ausschalten des Götzen", objective = "Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln von Razorfen.\n\nBeschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten.", description = "In der Nähe des Eingangs befindet sich ein Götze, der als makabrer Ofen für die Stacheleber fungiert; die Bestien... verzehren die aus dem Brachland Entführten. Ich kann den Götzen außer Funktion setzen und verhindern, dass sie ihn erneut nutzen, aber ich benötige dabei Eure Hilfe. Mein Plan: Begleitet mich zum Götzen. Wenn wir dort angekommen sind, werde ich das Ritual einleiten. Ich werde kaum in der Lage sein, mit Euch zu kommunizieren, geschweige denn, mich zu verteidigen. Schützt mich, während ich den Götzen außer Funktion setze. Wenn sie mich erschlagen, dann ist alles aus.\n\nSteht Ihr mir bei?", progress = nil, completion = "Belnistrasz' plötzlicher Abgang hat eine brennende Kohlenpfanne hinterlassen. Während Ihr in die Flammen starrt, erfüllt das Bild eines roten Großdrachen mit riesigen Flügeln Euren Geist. Eine rauere Version von Belnistrasz' Stimme spricht direkt zu Euch.\n\n\"Wahrlich, sterbliche Wesen, Ihr seid die Helden, die ich mir erhofft hatte. Dank Euch gehören die Schlächtereien, die diese Bestien begangen haben, der Vergangenheit an. Mein Glaube an sterbliche Wesen wie Euch ist wieder einmal erneuert worden. Nehmt dies als Belohnung, die eines Helden würdig ist.\"", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nDrachenklauenring"},
[3526] = {title = "Goblin-Ingenieurskunst", objective = "Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan.", description = "Bei der Experteningenieurskunst gibt es zwei unterschiedliche Disziplinen: Gnom und Goblin. Natürlich ist die Goblin-Ingenieurskunst die Wahl aller brillanten Ingenieure. Durch den klugen Einsatz von hochempfindlichen Sprengstoffen und phantastischen Ausrüstungsgegenständen lernt Ihr, die Welt zu meistern!\n\n<Name>, lest diese Anleitung. Wenn Ihr etwas über Goblin-Ingenieurskunst wissen wollt, dann bringt sie zu Nixx Sprocketspring nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", progress = "Ich kann neue Schüler genauso gut riechen wie exzellentes Sprengpulver - aus einer Meile Entfernung. Seid Ihr gekommen, um die Beherrschung der Explosion zu erlernen?", completion = "Tja, &lt;Name&gt;, Ihr habt gut daran getan, Unterweisung bei mir zu suchen! Jeder Schmock kann Experte für die Grundlagen der Ingenieurskunst werden - die Gnome und ihre von Strahlen verseuchte Heimat Gnomeregan sind der beste Beweis dafür. Aber es braucht schon klare Gedanken und eine RUHIGE HAND, um die Disziplin der Goblin-Ingenieurskunst zu meistern.\n\nHaltet Eure Ohren offen, &lt;Name&gt;, und Ihr könnt vielleicht was lernen.", rewards = "Ihr bekommt:\n\n"},
[3527] = {title = "Die Prophezeiung von Mosh'aru", objective = "Bringt die erste und die zweite Mosh'aru-Schrifttafel zu Yeh'kinya nach Tanaris.", description = "Die alte Prophezeiung von Mosh'aru berichtet von einer Methode, die Essenz des Gottes Hakkar zu bewahren. Sie wurde auf zwei Schrifttafeln niedergeschrieben und zu der Troll-Stadt Zul'Farrak gebracht, westlich von Gadgetzan.\n\nBringt mir die Mosh'aru-Schrifttafeln!\n\nDie erste Schrifttafel hat der Troll Theka der Märtyrer, der schon lange tot ist. Man sagt, dass seine Verfolger zu Skarabäen verflucht wurden und nun an seinem Schrein herumhuschen.\n\nDie zweite Schrifttafel hat die Wasserbeschwörerin Velratha, in der Nähe des hochheiligen Teiches von Gahz'rilla.\n\nWenn Ihr die Schrifttafeln habt, bringt sie zu mir.", progress = "Habt Ihr die Schrifttafeln der Prophezeiung von Mosh'aru, <Name>?\n\nWenn ich die Schrifttafeln in meinen Besitz bringe, werde ich sie studieren und erfahren, wie die Essenz von Hakkar bewahrt werden kann!", completion = "Ah, das ist gut. Ich kann diese alten Schrifttafeln zusammenfügen und dann ihre verborgenen Geheimnisse studieren.\n\nMeine Schuld Euch gegenüber wächst, &lt;Name&gt;. Und sie wird noch weiter wachsen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3528] = {title = "Der Gott Hakkar", objective = "Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris.", description = "Jetzt wird es Zeit, die Essenz des Avatars von Hakkar einzufangen.\n\nBringt das Ei von Hakkar in das Sanktum des Gefallenen Gottes im Versunkenen Tempel in Azeroth. Ruft die Macht des Eies an, um den toten Gott aufzuwecken.\n\nEr wird seine Diener gegen Euch ausschicken. Besiegt seine Bluttrinker und nehmt ihr Hakkari-Blut an Euch; dann benutzt das Blut, um die ewigen Flammen auszulöschen, die Hakkars Geist halten. Erst wenn alle Flammen gelöscht sind, wird der Avatar von Hakkar unsere Welt betreten.\n\nBesiegt ihn und gebt seine Essenz in das Ei von Hakkar.", progress = "Habt Ihr den Avatar von Hakkar besiegt, <Name>? Hat seine Essenz das Ei, das ich Euch gab, schon ermächtigt?", completion = "Die Essenz von Hakkar wurde eingefangen! Gerade jetzt beginnt sich das Leben im Ei zu regen! Sind die Geschichten von Hakkar doch wahr?\n\nDas darf nicht wahr sein! Ich fürchte mich vor dem, was Hakkar tun könnte, wenn er erneut geboren wird. Ich werde dieses Ei sicher aufbewahren und darauf achten, dass es niemals in böse Hände gerät.\n\nEure Dienste für mich sind nun zu Ende, &lt;Name&gt;. Ihr habt eine Legende berührt und Eure Taten werden eines Tages das Antlitz unserer Erde verändern.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAvenwach-HelmLangdolch der LebenskraftEdelsteinbesetzter Reif\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[3541] = {title = "Lieferung an Jes'rimon", objective = "Bringt die Schrifttafel von Jin'yael zu Jes'rimon nach Orgrimmar.", description = "Ich kenne einen Hehler in Orgrimmar. Er wohnt in der Gasse. Er ist ziemlich schwer zu finden, wenn Ihr nicht wisst, wo Ihr suchen sollt. Wenn Ihr Euch dort in einem der höchsten Gebäude umschaut, solltet Ihr ihn jedoch ohne Probleme finden können.\n\nTut mir aber bitte einen Gefallen und posaunt nicht in ganz Kalimdor herum, dass er dort ist und was er so tut, das wäre schlecht für uns beide.\n\nEr wird uns einen mehr als fairen Preis für die Schrifttafel von Jin'yael geben. Ich weiß zwar nicht genau warum, aber Ihr hättet mal sehen sollen, wie aufgeregt er war, als er von ihrem Aufenthaltsort erfahren hat.", progress = "Ja? Was wollter denn, Mann? Hab heute noch viel zu tun, und Ihr seid in mei'm Terminkalender nich' eingetrag'n. Wenner mich weiter belästigt, kann sich das aber sicherlich noch ändern.", completion = "Ahhh, Jediga hat ihr Päckchen den weit'n Weg von Azshara hergeschickt. Gut. Hab da schon drauf gewartet.\n\nJediga, das is' mal 'ne feine Frau... 'ne tödliche dazu. Was könnt da besser sein?\n\nSeht Euch das an... die Schrifttafel is' in perfekt'm Zustand. Ihr seid 'n guter Bote, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[3542] = {title = "Lieferung an Andron Gant", objective = "Bringt die Schrifttafel von Markri zu Andron Gant nach Undercity.", description = "Andron Gant ist mein nächster Kontakt. Normalerweise hält er sich in Undercity auf... ganz in der Nähe des Apothekariums.\n\nEr war ein bisschen redselig, als das Gespräch darauf kam, warum er die Schrifttafel haben wollte. Anscheinend wollen einige der Magier von Undercity die Arkanzauber studieren, die die Hochgeborenen benutzt haben. Sie glauben, dass ihnen diese Schrifttafel dabei helfen würde. Markri war sehr bewandert im Beschwören von Kreaturen, besonders von Elementaren.\n\nNehmt die Schrifttafel von Markri und kommt zu mir zurück, um Euch Euren Teil der Belohnung abzuholen.", progress = "Nun... <hick>... was für eine Überraschung? Ein Abenteurerererer... <hick>!\n\nWasss k'nn ich für Euch tun... <hick>?", completion = "Hier, nehmt ein paar Münzen... holt Euch'n... &lt;hick&gt;... neue Rüstung oder so was...\n\nDas gibt'n nettes Gold für die richt'gen... &lt;hick&gt; Leute.", rewards = "Ihr bekommt:\n\n"},
[3561] = {title = "Lieferung für Erzmagier Xylem", objective = "Bringt die Schrifttafel von Sael'hai zu Erzmagier Xylem in Azshara.", description = "Die letzte Schrifttafel geht an eine sehr gefährliche Person, <Name>. Hört auf mich, wenn ich Euch sage, dass ich dieser Person viel weniger traue als irgendeiner der anderen, die Ihr in meinem Namen getroffen habt.\n\nErzmagier Xylem hat einen Turm in den Hügeln mit Ausblick auf ganz Azshara. Er ist zwar ein Mensch, aber er benimmt sich wie kein Mensch, den ich jemals getroffen ... oder getötet habe. Er strahlt Macht aus, und ich wage nicht, ihn zu fragen, was er mit der Schrifttafel vorhat.\n\nEr kam zu mir, aber er teilte mir mit, dass seine Leibwache Sanath mir helfen würde, zum Turm zu kommen, wenn ich bereit sei, ihn zu treffen. Sucht nach Sanath im Norden.", progress = "Wie kann ich Euch helfen, <Name>?", completion = "Ah, die Schrifttafel von Sael'hai... wie lange habe ich darauf gewartet, sie zu erforschen.\n\nDanke, &lt;Name&gt;. Ihr könnt Jediga mitteilen, dass sie ihre Sache gut gemacht hat. Das ist mit Sicherheit die Bezahlung wert, die sie gefordert hat.", rewards = "Ihr bekommt:\n\n"},
[3562] = {title = "Magathas Bezahlung für Jediga", objective = "Bringt Magathas Notiz zu Jediga in Azshara.", description = "Bringt diese Notiz zu Jediga. Sagt ihr, dass ihre Bezahlung hier auf sie wartet, wenn sie zurückkommt. Und sagt ihr, dass ich mit ihrer Arbeit zufrieden bin.\n\nBeeilt Euch, <Name>. Sagt Eurer Meisterin, dass ich hier auf sie warten werde.", progress = "Na, was hat Magatha gesagt? Die alte Greisin... Ich wette, sie war nicht sehr höflich.", completion = "Ah, gut. Sie war ja vernünftiger, als ich es erwartet habe... zumindest zu Euch. Ich habe schon fast damit gerechnet, dass sie Euch für meine Ungebührlichkeit, jemand anderes an meiner Stelle zu schicken, bestrafen würde. Sie will diese Schrifttafel anscheinend wirklich dringend haben. Interessant.\n\nIch werde ein anderes Mal darüber nachdenken.", rewards = "Ihr bekommt:\n\n"},
[3563] = {title = "Jes'rimons Bezahlung für Jediga", objective = "Bringt Jes'rimons Notiz zu Jediga in Azshara.", description = "Bringt diesen Brief zu Jediga. Lasst sie wissen, dass unser Handel vorteilhaft ist und ich mit ihrer Arbeit zufrieden bin.\n\nSagt ihr, sie soll schnell nach Orgrimmar zurückkommen, und Jes'rimon würde gut für sie sorgen.\n\nSagt ihr das! Und, vielleicht benötige ich in Zukunft noch einmal Eure Dienste, <Name>.", progress = "Habt Ihr schon mit Jes'rimon gesprochen?\n\nEr ist zwar ein Eber unter Trollen, aber seine Informationen sind eigentlich immer korrekt, und er bezahlt gut.\n\nWenn Ihr mit seinem Benehmen umgehen könnt, habt Ihr einiges an Geld von seinen geschäftlichen Bemühungen zu erwarten.", completion = "Wie ich an seiner Notiz erkennen kann, war er sehr erfreut... vielleicht ein wenig zu sehr.\n\nVielleicht werde ich mir eines Tages die Zeit nehmen, ihn wissen zu lassen, wie sehr ich seine Avancen schätze. Na, das ist immerhin ein Grund, sich auf eine längere Anwesenheit in Azshara zu freuen.\n\nHier habt Ihr Euren Anteil.", rewards = "Ihr bekommt:\n\n"},
[3564] = {title = "Androns Bezahlung für Jediga", objective = "Bringt Androns Notiz zu Jediga in Azshara.", description = "Hier... bringt... <hick> das zu Jediga. Viel Glück!", progress = "Habt Ihr Euch schon mit Andron getroffen? Er verlässt Undercity nur selten, Ihr müsstet ihn leicht finden können.", completion = "Perfekt... moment mal.\n\nHaha! Was habt Ihr ihm gesagt, als Ihr die Schrifttafel gebracht habt, &lt;Name&gt;? Er hat uns viel zu viel bezahlt! Nicht, dass ich mich beschweren wollte. Habt Ihr ihm gesagt, dass der Preis sich geändert hat? Oder war er wieder mal betrunken?\n\nAuch egal... hier, Ihr sollt auch einen Extra-Anteil haben.", rewards = "Ihr bekommt:\n\n"},
[3565] = {title = "Xylems Bezahlung für Jediga", objective = "Bringt Xylems Notiz zu Jediga in Azshara.", description = "Was ist? Oh, ja, Eure Bezahlung. Natürlich.\n\nNehmt das und fort mit Euch. Jediga wartet bestimmt schon voller Geduld auf Eure Rückkehr.", progress = "Nun, was hat Xylem gesagt? Er hat Euch doch nichts getan, oder? Hat er Euch verzaubert? Oder Euch dazu gebracht, für ihn zu arbeiten?", completion = "Keine Probleme? Überhaupt keine? Also das ist ja schon bemerkenswert... Ich habe erwartet, dass er einigen Widerstand zeigt oder zumindest unsere Übereinkunft verrät. Hmm, vielleicht kann man ihm ja doch trauen.\n\nGut, darüber muss ich jetzt nicht nachdenken. Hier ist Euer Anteil. Danke für Eure Hilfe.", rewards = "Ihr bekommt:\n\n"},
[3566] = {title = "Erhebt Euch, Obsidion!", objective = "Tötet Lathoric den Schwarzen und Obsidion. Kehrt zurück zu Thorius nach Ironforge mit dem Kopf von Lathoric dem Schwarzen und dem Herzen von Obsidion.", description = "Es... Es... Es war alles eine Falle.\n\nVergebt... mir.\n\nTötet den Bastard... Tötet ihn für uns... für Thorius.", progress = "Ich glaube Euch nicht! Bringt mir Beweise!", completion = "&lt;Thorius wird ganz blass.&gt;\n\nDas... das darf nicht wahr sein. Mein eigener Bruder? Er hat all das inszeniert?\n\n&lt;Thorius' Gesicht verzerrt sich vor Wut.&gt;\n\nEr hat mich verraten, er hat Ironforge verraten! Es scheint, als sei der Einfluss der alten Götter in diesem Land immer noch sehr stark. Ich fürchte, wenn mein Bruder - ein einst so edler und ehrenwerter Mann - so leicht dem Willen von Ragnaros unterworfen werden konnte, ist hier niemand mehr sicher.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZenturio-BeinplattenLordrec-HelmRing der Seelenstärke\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[3567] = {title = "An die Spitze", objective = "Würdet Ihr den Ausblick von einem der Zwillingskolosse bevorzugen? Ich kann Euch dorthin schicken, <Volk>.\n\nAber überlegt, wie Ihr wieder herunterkommt. Ich kann Euch nur nach oben schicken.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nZwillingskoloss-Teleporter"},
[3568] = {title = "Verbreitete Verderbnis", objective = "Füllt alle 4 leeren Phiolen an den Gezeitenteichen entlang der Küste der Ruinen von Eldarath in Azshara und kehrt dann zu Chemiker Cuely zurück.", description = "Seht Ihr die Tauren hinter mir - diejenige, die aussieht, als müsste sie sich jeden Moment übergeben? Sie war erst vor kurzem in Azshara. Sie behauptet, dass sie von einigen Naga verwundet wurde, als sie sich den Weg durch die Ruinen von Eldarath bahnte.\n\nNachdem sie einige von ihnen zurückschlagen konnte, machte sie eine Pause am Strand und trank aus einem der Gezeitenteiche. Jetzt ist ihr ein wenig übel ... unter anderem.\n\nIch würde gern herausfinden, was sie getrunken hat. Nehmt diesen Kasten, darin befinden sich einige leere Phiolen, die ich mit Etiketten versehen habe. Füllt jede an einem anderen Teich und kehrt dann zurück.", progress = "Ihr wisst, wohin das hier führt, nicht wahr, <Name>? Sie wird dies nicht überleben... seht sie Euch an. Das Beste, was sie jetzt noch tun kann, ist, uns bei der Suche nach einem Heilmittel für die Seuche zu helfen. Das Wasser, das sie getrunken hat, könnte einen Hinweis enthalten, wie wir das anstellen können. Sie wird sowieso sterben; dann könnte sie doch, ehe sie stirbt, etwas Großmütiges für unser Volk tun. Ist es nicht so?", completion = "Großartig. Ihr seid zurück, bevor sie gestorben ist. Gut, gut.\n\nDann lasst uns mal anfangen, ja?\n\nIch habe ihre Symptome nun schon eine Weile beobachtet, und es ist sehr hässlich. Ich bin überrascht, dass sie noch steht. Sie musste sich schon drei oder vier Mal übergeben ... ein sehr angenehmer Geruch.\n\nBitte wartet einen Moment, bis ich etwas zusammengemischt habe, um es an unserer ... Freundin ... zu testen.", rewards = "Ihr bekommt:\n\n"},
[3569] = {title = "Verbreitete Verderbnis", objective = "Gebt Cuelys ElixierThersa Windsong in Undercity.", description = "Gebt das Thersa. Vielleicht wird das hier sie heilen... vielleicht aber auch nicht. Wir werden es nicht wissen, solange sie es nicht getrunken hat.", progress = "Ich kam nach Undercity, weil ich gehört habe, die Alchimisten hätten hier intensiv geforscht, um ein Heilmittel für ihre eigene Krankheit zu finden. Es hieß, dass sie vielleicht auch mir helfen könnten.\n\nObwohl dieser Ort mich alles andere als willkommen heißt, blieb mir keine Wahl - die Erkrankung, die mich befallen hat, zerreißt mich innerlich, und ich benötigte ihre sofortige Hilfe.", completion = "Chemiker Cuely war sehr zuvorkommend... beängstigend zuvorkommend sogar. Aber da er sagt, dass mir das hier helfen wird, habe ich wohl keine andere Wahl. Ich habe keine Zeit, um eine andere Lösung zu suchen. Ich habe bereits mit Priestern und Schamanen gesprochen. Keiner konnte mir helfen.\n\nHoffen wir, dass die Erdenmutter über meinen Geist wacht.", rewards = "Ihr bekommt:\n\n"},
[3570] = {title = "Verbreitete Verderbnis", objective = "Ich hätte mir nie träumen lassen, dass das Elixier so schnell Wirkung zeigen würde. Danke, <Name>. Ich werde mich sofort an die Untersuchung der restlichen Proben machen. Bestimmt werden sie für Lady Silvanas und die Verlassenen schon bald von Nutzen sein.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[3601] = {title = "Kim'jael, fürwahr!", objective = "Durchsucht den Thalassian-Stützpunkt nach Kim'jaels Kompass, Zielfernrohr, ausgestopftem Huhn und Wizzlegoober und bringt ihm dann alles nach Azshara zurück.", description = "Kim'jael, fürwahr! Wisst Ihr, was Kim'jael für die Blutelfen bedeutet, <Name>? Kleine Ratte... oder so etwas in der Art. Diese großen Angeber!\n\nSie haben mich angeworben, damit ich ihnen helfe, das Gebiet auszukundschaften und nach einer Art verlorenen Schatz zu suchen. Natürlich habe ich sofort zugegriffen, als sie das Wort 'Schatz' erwähnten und die Summe, die sie mir bezahlen wollten. Aber dann haben sie sich gegen mich gewandt und versucht, mich zu töten... MICH!\n\nDas zeigt einmal mehr, dass einem Blutelfen nicht zu trauen ist.\n\nMein Problem ist: Sie haben immer noch meine Ausrüstung, und ich kann sie nicht wiederbekommen. Helft Ihr mir?", progress = "Diese stinkenden Blutelfen. Ich sag Euch, wenn ich so stark wäre wie Ihr, würde ich mich dorthin begeben und ihnen selbst ein paar Dinge beibringen! Aber ich muss mich damit begnügen, Euch zu bezahlen, damit Ihr Euch um sie kümmert.", completion = "Haha! Denen habt Ihr's kräftig gezeigt, was?!\n\nDas ist toll! Das wird diese Blutelfen lehren, ihre Partner zu betrügen... besonders jemanden, der so loyal ist wie ein Goblin-Händler! Pah, Blutelfen...!\n\nTja, das Mindeste, was ich für Euch tun kann, ist, für Eure Zeit zu zahlen... so wie ich es gesagt habe.\n\nBitteschön... das hier sollte nützlich sein.", rewards = "Ihr bekommt:\n\nM73 Schrapnellgranate"},
[3602] = {title = "Azsharit", objective = "Sammelt 20 kristallisierte Azsharite im südlichen Azshara. Ihr könnt den Teufelshund benutzen, damit er Euch beim 'Erschnüffeln' der gut versteckten Ablagerungen behilflich ist.\n\nKehrt zu Loramus zurück, sobald Ihr die Aufgabe erfüllt habt.", description = "Die uralten Klippenriesen aus dem südlichen Azshara ernähren sich von Felsen und Gebäuden des Landes. Ihre Ausscheidung ist, bedingt durch die Ernährung, ein höchst formbarer und extrem starker Kristall, der als Azsharit bekannt ist.\n\nDer südliche Bogen ist übersät mit diesen Gebilden, aber es konnten nur wenige geborgen werden, da die Riesen über ein extrem angriffslustiges Naturell verfügen.\n\nIhr sollt nach Süden vorstoßen und genügend Azsharit einsammeln, um den Waffenkörper herzustellen. Meine Teufelshunde werden Euch beim Einsammeln der Kristalle behilflich sein.", progress = "Das Böse schläft nicht, Dummkopf. Ihr werdet genug Zeit zum Ausruhen haben, wenn Ihr erst einmal tot seid. Aber jetzt, bringt mir diese Kristalle.", completion = "Eure Aufgaben in Azshara sind abgeschlossen, sterbliches Wesen. Ich muss nun die notwendigen Komponenten für den nächsten Schritt Eures Abenteuers schmieden.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3621] = {title = "Die Herstellung von Teufelsbann", objective = "Bringt die Lieferung zu Galvan dem Alten im Schlingendorntal.", description = "Die Waffen können jetzt geschmiedet werden. Ihr müsst den ausgehärteten Azsharit zu jemandem bringen, der die Fähigkeit besitzt, Teufelsenergie zu bändigen.\n\nIm Schlingendorntal gibt es einen solchen Schmied. Galvan der Alte, Anführer des Mithrilordens, wird die Waffen nach Euren Angaben fertigen. Ihr könnt sein Lager zwischen Zul'Gurub und dem Ogerhügel der Mosh'Ogg finden.\n\nMögen Eure Entschlossenheit und Euer Glaube Euch durch diese Tortur leiten. Solltet Ihr versagen, wisset, dass Euer Gott auf Euch herablächelt, sterbliches Wesen.", progress = "Loramus, eh? Es ist schon viele Jahre her, dass ich diesen Namen hörte.", completion = "Meine Güte, allein der Gedanke, was Ihr wohl durchmachen musstet, um an dieses Material zu gelangen! Nur wenige wagen sich nach Azshara und kehren lebend zurück, ganz zu schweigen von denen, die sich mit Halbgöttern und Riesen messen!", rewards = "Ihr bekommt:\n\n"},
[3625] = {title = "Verzauberte Azsharit-Teufelswaffe", objective = "Wartet, bis Galvan die Waffen fertig geschmiedet hat.", description = "<Name>, die Herstellung jeder einzelnen Waffe wird einige Zeit in Anspruch nehmen.\n\nAußerdem dürft Ihr die Macht des Teufelsfluchs nur einmal alle drei Minuten verwenden. Seine schwächenden Eigenschaften gegen Razelikh den Entweiher und seine Diener können unterschiedlich lang dauern. Aus diesem Grund dürft Ihr den Teufelsfluch erst dann freigeben, wenn der richtige Zeitpunkt gekommen ist!\n\nGebt mir jetzt einen Moment, damit ich Eure Waffen fertigen kann, <Name>.", progress = "Wenn der Schmiedevorgang unterbrochen wird, könnte die Waffe fehlerhaft sein. Habt Geduld, <Name>.", completion = "&lt;Galvan wischt sich den Schweiß von der Stirn.&gt;\n\nEinen besseren Dämonentöter als diesen hier gab es noch nie, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVerzauberter Azsharit-TeufelsbanndolchVerzauberter Azsharit-TeufelsbannstabVerzaubertes Azsharit-Teufelsbannschwert\n\nIhr bekommt außerdem:\n\n"},
[3626] = {title = "Rückkehr in die verwüsteten Lande", objective = "Kehrt zum Gefallenen Helden der Horde zurück.", description = "Die Stunde der Erlösung rückt näher, <Name>. Ihr müsst mit Eurer neuen Waffe in die verwüsteten Lande zurückkehren und mit dem Gefallenen Helden der Horde sprechen, um Eure letzte Aufgabe zu erhalten.", progress = nil, completion = "Ihr seht aus wie ein erprobter Kämpfer, &lt;Name&gt;. Seid Ihr bereit, Euch Razelikh und seinen Dienern zu stellen?", rewards = "Ihr bekommt:\n\n"},
[3627] = {title = "Das zerbrochene Amulett vereinen", objective = "Tötet Grol den Zerstörer, Lady Sevine und Erzmagier Allistarj. Nehmt das Amulett von Grol, das Amulett von Sevine und das Amulett von Allistarj von ihren Leichen.\n\nDenkt daran, Eure Verzauberte Azsharit-Teufelswaffe zu BENUTZEN, um die Triade zu schwächen. Auf eine andere Weise können sie nicht getötet werden - aber verwendet sie weise...", description = "Um den Entweiher zu erreichen, müsst Ihr zunächst das Dreigestirn der Macht zerstören und die Teile des Amuletts beschaffen. Wenn Ihr alle drei Teile beschafft habt, kommt zu mir zurück, und ich werde Euch weitere Anweisungen geben.\n\nGeht, <Name>! Auf in die verwüsteten Lande! Sevine, Allistarj und Grol müssen fallen!", progress = "Die drei werden das Eine formen, das Eine wird den Weg erhellen.", completion = "Das Amulett von Razelikh dem Entweiher wurde wieder zusammengefügt, aber er spürt die Störung seiner Befehlskette. Er weiß, dass Ihr kommt...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3628] = {title = "Ihr seid Rakh'likh, Dämon", objective = "Vernichtet Razelikh den Entweiher und bringt das abgespaltene Horn des Entweihers zum Gefallenen Helden der Horde. Ihr müsst außerdem den Zauberschutz des Entweihers mit zurückbringen, damit der Gefallene Held ihn zerstören und somit verhindern kann, dass er jemals in die falschen Hände fällt.", description = "Razelikhs Unterschlupf befindet sich auf dem Gipfel des höchsten Berges in den verwüsteten Landen. Einzig durch Einsatz der Teleport-Runen in der Nähe des Berges kann man zu diesem Unterschlupf gelangen. Solange Ihr das Amulett habt, könnt Ihr den Unterschlupf erreichen. Nachdem Ihr erst den Unterschlupf erreicht habt, müsst Ihr die Bestie herbeizaubern. Das Amulett ist Euer Schlüssel, <Name>. Benutzt es auf dem Altar des Entweihers.\n\nFalls Ihr den Entweiher besiegen könnt, bringt sein Horn zurück. Es wird ein Symbol der Hoffnung für alle sein, die es sehen, ein Beweis dafür, dass es tatsächlich Helden in dieser vom Krieg zerrissenen Welt gibt.", progress = "Es gibt nichts mehr zu fürchten.", completion = "Heute ist ein Tag, der bis in alle Ewigkeit unvergessen bleiben wird. Der dämonische Oberanführer der verwüsteten Lande ist endlich gefallen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nHalskette des HeiligtumsDämonenblutDämonenbalgsack"},
[3629] = {title = "Goblin-Ingenieurskunst", objective = "Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan.", description = "Experten-Ingenieurskunst beinhaltet zwei unterschiedliche Disziplinen: für Gnome und für Goblins. Ich erwähne Goblin-Ingenieurskunst nur, weil ich ein fairer Lehrer bin. Sie machen gern Dinge, die in die Luft gehen und es ist ihnen dabei meistens egal, ob was im Weg herumsteht - auch wenn sie es selbst sind.\n\n<Name>, lest diese Anleitung. Wenn Ihr lernen wollt, Euch selbst in die Luft zu jagen, dann bringt sie zu Nixx Sprocketspring nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft, es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", progress = "Ich kann neue Schüler genauso gut riechen wie exzellentes Sprengpulver - aus einer Meile Entfernung. Seid Ihr gekommen, um die Beherrschung der Explosion zu erlernen?", completion = "Tja, &lt;Name&gt;, Ihr habt gut daran getan, Unterweisung bei mir zu suchen! Jeder Schmock kann Experte für die Grundlagen der Ingenieurskunst werden - die Gnome und ihre von Strahlen verseuchte Heimat Gnomeregan sind der beste Beweis dafür. Aber es braucht schon klare Gedanken und eine RUHIGE HAND, um die Disziplin der Goblin-Ingenieurskunst zu meistern.\n\nHaltet Eure Ohren offen, &lt;Name&gt;, und Ihr könnt vielleicht was lernen.", rewards = "Ihr bekommt:\n\n"},
[3630] = {title = "Gnomen-Ingenieurskunst", objective = "Wenn Ihr etwas über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Tüftlermeister Overspark nach Ironforge.", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: für Gnome und für Goblins. Gnomen-Ingenieurskunst ist die weit Überlegenere der beiden! Es geht um die Konstruktion von wunderbaren Apparaten und Geräten, die das Leben schöner machen.\n\n<Name>, lest diese Anleitung. Wenn Ihr mehr über Gnomen-Ingenieurskunst lernen wollt, dann bringt sie zu Tüftlermeister Overspark in Ironforge. Denkt daran - das ist eine dauerhafte Mitgliedschaft und es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr Euch absolut sicher sein, dass Ihr Euch sicher seid, bevor Ihr seine Aufgabe ausführt.", progress = "Ja, ja, um welche Eurer Bedürfnisse darf ich mich heute bemühen? Ich habe ja offensichtlich Zeit dafür, da ich nur hier herumstehe, während unsere geliebte Stadt unter einer Wolke bestrahlten Todes liegt.", completion = "Ah, ein junger Ingenieur, der an der einen, wahren Disziplin der Ingenieurskunst interessiert ist! Entschuldigt meine Dramatik, Freund. Zwar ist unsere Lage immer noch sehr betrüblich, doch es ist immer ein guter Tag, wenn man einen weiteren Ingenieur findet, der dem Ruf der wahren Ingenieurskunst folgt!", rewards = "Ihr bekommt:\n\n"},
[3631] = {title = "Teufelsross beschwören", objective = "Sprecht mit Strahad Farsan im Brachland.", description = "Hmpf. Ich sage, Ihr seid nicht vorbereitet, aber das ist nicht meine Entscheidung. Strahad empfindet das anders und es ist seine Entscheidung... dieses Mal.\n\nEr wünscht mit Euch zu sprechen, und das schnell. Ihr werdet ihn immer noch über Ratchet im Brachland finden, in seinem kleinen Turm dort, mit seinen Akolythen.\n\nTrödelt nicht herum.", progress = nil, completion = "Soso, Ihr habt also beschlossen, mich erneut mit Eurer Anwesenheit zu beehren. Wie nett von Euch.\n\nMeine Akolyten haben sich schon gefragt, ob Ihr jemals auftauchen würdet. Ich habe ihnen gesagt, daran bestünde kein Zweifel. Von der Macht werdet Ihr angezogen wie eine Motte vom Licht.", rewards = "Ihr bekommt:\n\n"},
[3632] = {title = "Gnomen-Ingenieurskunst", objective = "Wenn Ihr etwas über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Tüftlermeister Overspark nach Ironforge.", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: Gnom und Goblin. Gnomen-Ingenieurskunst ist die weit Überlegenere der beiden! Es geht um die Konstruktion von wunderbaren Apparaten und Geräten, die das Leben schöner machen.\n\n<Name>, lest diese Anleitung. Wenn Ihr mehr über Gnomen-Ingenieurskunst lernen wollt, dann bringt sie zu Tüftlermeister Overspark hier in Ironforge. Denkt daran - das ist eine dauerhafte Mitgliedschaft und es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr Euch absolut sicher sein, dass Ihr Euch sicher seid, bevor Ihr seine Aufgabe ausführt.", progress = "Ja, ja, um welche Eurer Bedürfnisse darf ich mich heute bemühen? Ich habe ja offensichtlich Zeit dafür, da ich nur hier herumstehe, während unsere geliebte Stadt unter einer Wolke bestrahlten Todes liegt.", completion = "Ah, ein junger Ingenieur, der an der einen, wahren Disziplin der Ingenieurskunst interessiert ist! Entschuldigt meine Dramatik, Freund. Zwar ist unsere Lage immer noch sehr betrüblich, doch es ist immer ein guter Tag, wenn man einen weiteren Ingenieur findet, der dem Ruf der wahren Ingenieurskunst folgt!", rewards = "Ihr bekommt:\n\n"},
[3633] = {title = "Goblin-Ingenieurskunst", objective = "Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan.", description = "Bei der Experteningenieurskunst gibt es zwei unterschiedliche Disziplinen: Gnom und Goblin. Natürlich ist die Goblin-Ingenieurskunst die Wahl aller brillanten Ingenieure. Durch den klugen Einsatz von hochempfindlichen Sprengstoffen und phantastischen Ausrüstungsgegenständen lernt Ihr, die Welt zu meistern!\n\n<Name>, lest diese Anleitung. Wenn Ihr etwas über Goblin-Ingenieurskunst wissen wollt, dann bringt sie zu Nixx Sprocketspring nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", progress = "Ich kann neue Schüler genauso gut riechen wie exzellentes Sprengpulver - aus einer Meile Entfernung. Seid Ihr gekommen, um die Beherrschung der Explosion zu erlernen?", completion = "Tja, &lt;Name&gt;, Ihr habt gut daran getan, Unterweisung bei mir zu suchen! Jeder Schmock kann Experte für die Grundlagen der Ingenieurskunst werden - die Gnome und ihre von Strahlen verseuchte Heimat Gnomeregan sind der beste Beweis dafür. Aber es braucht schon klare Gedanken und eine RUHIGE HAND, um die Disziplin der Goblin-Ingenieurskunst zu meistern.\n\nHaltet Eure Ohren offen, &lt;Name&gt;, und Ihr könnt vielleicht was lernen.", rewards = "Ihr bekommt:\n\n"},
[3634] = {title = "Gnomen-Ingenieurskunst", objective = "Wenn Ihr etwas über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Tüftlermeister Overspark nach Ironforge.", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: für Gnome und für Goblins. Ich bin zwar der Meinung, dass es Verschwendung ist, aber Ihr solltet doch etwas über die Gnomen-Spezialisierung wissen. Sie machen Geräte und Apparate, die angeblich die Welt verändern, aber meistens gar nicht funktionieren.\n\n<Name>, lest diese Anleitung. Wenn Ihr lernen wollt, wie man Briefbeschwerer aus Metall herstellt, dann bringt sie zu Tüftlermeister Overspark in Ironforge. Denkt daran - das ist eine dauerhafte Mitgliedschaft und es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr Euch absolut sicher sein, dass Ihr Euch sicher seid, bevor Ihr seine Aufgabe ausführt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[3635] = {title = "Gnomen-Ingenieurskunst", objective = "Wenn Ihr mehr über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Oglethorpe Obnoticus nach Booty Bay.", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen: Gnom und Goblin. Ich bin zwar der Meinung, dass es reine Verschwendung ist, aber Ihr solltet doch etwas über die Spezialisierung der Gnome wissen. Sie machen Gegenstände und Apparate, die angeblich die Welt verändern, aber meistens gar nicht funktionieren.\n\n<Name>, lest diese Anleitung. Wenn Ihr lernen wollt, wie man Briefbeschwerer aus Metall herstellt, dann bringt sie zu Oglethorpe Obnoticus in Booty Bay. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", progress = "Hallo! Wenn Ihr gekommen seid, um Euch über einen Leitroboter zu beschweren, der durch eine Wand Eures Domizils gebrochen ist, dann lasst mich Euch gleich zu meinem Anwalt weiterleiten. Anderenfalls, was kann ich heute für Euch tun?", completion = "Ihr seid gekommen, um die Gnomen-Ingenieurskunst zu erlernen, eh? Tja, da seid Ihr hier genau bei dem richtigen Gnom gelandet. Auch wenn die herrschende Fraktion in Gnomeregan die Politik benutzt, um diejenigen, die sie als intellektuelle Bedrohung sieht, zu ächten, wissen sie doch genau, dass Wissen ihrer Kontrolle nicht unterworfen werden kann.\n\nSie und ich wissen, dass sie einen ihrer größten noch lebenden Gnomen-Ingenieure verloren haben, als ich Gnomeregan verlassen habe. Wenn Ihr ein fähiger Student seid, werde ich Euch alles lehren, was ich weiß.", rewards = "Ihr bekommt:\n\n"},
[3636] = {title = "Das Licht bringen", objective = "Erzbischof Benedictus will, dass Ihr Amnennar den Kältebringer in den Hügeln von Razorfen tötet.", description = "Die Geißel ist eine dauerhafte Bedrohung für die Allianz. Ich bin sicher, Euch ist diese Tatsache vertraut. Kürzlich erst stießen wir auf einige sehr seltsame Funde, <Name>.\n\nIm Brachland gibt es ein fürchterliches Dickicht von Dornsträuchern, das Hügel von Razorfen heißt. Früher war es die Heimat von einfachen Stachelebern, aber nun ist offensichtlich, dass ein Pakt mit der Geißel geschlossen wurde, die viel schlimmere Kreaturen hervorbrachte... Sie werden jetzt von dem Lich, Amnennar dem Kältebringer, beherrscht.\n\nStellt Euch auf die Seite des Lichts, <Name>, und macht diesem bösen Verbund ein Ende.", progress = nil, completion = "Danke, &lt;Name&gt;. Die Geißel wird es sich nun zweimal überlegen, bevor sie erneut versucht, ihre Reihen zu verstärken.\n\nMöge das Licht Euch segnen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nBezwingerschwertBernsteinglut-Talisman"},
[3637] = {title = "Gnomen-Ingenieurskunst", objective = "Wenn Ihr mehr über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Oglethorpe Obnoticus nach Booty Bay.", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen: Gnom und Goblin. Ich bin zwar der Meinung, dass es reine Verschwendung ist, aber Ihr solltet doch etwas über die Spezialisierung der Gnomen wissen. Sie machen Gegenstände und Apparate, die angeblich die Welt verändern, aber meistens gar nicht funktionieren.\n\n<Name>, lest diese Anleitung. Wenn Ihr lernen wollt, wie man Briefbeschwerer aus Metall herstellt, dann bringt sie zu Oglethorpe Obnoticus in Booty Bay. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", progress = "Hallo! Wenn Ihr gekommen seid, um Euch über einen Leitroboter zu beschweren, der durch eine Wand Eures Domizils gebrochen ist, dann lasst mich Euch gleich zu meinem Anwalt weiterleiten. Anderenfalls, was kann ich heute für Euch tun?", completion = "Ihr seid gekommen, um die Gnomen-Ingenieurskunst zu erlernen, eh? Tja, da seid Ihr hier genau bei dem richtigen Gnom gelandet. Auch wenn die herrschende Fraktion in Gnomeregan die Politik benutzt, um diejenigen, die sie als intellektuelle Bedrohung sieht, zu ächten, wissen sie doch genau, dass Wissen ihrer Kontrolle nicht unterworfen werden kann.\n\nSie und ich wissen, dass sie einen ihrer größten noch lebenden Gnomen-Ingenieure verloren haben, als ich Gnomeregan verlassen habe. Wenn Ihr ein fähiger Student seid, werde ich Euch alles lehren, was ich weiß.", rewards = "Ihr bekommt:\n\n"},
[3638] = {title = "Der Schwur der Geheimhaltung", objective = "Wenn Ihr ein Goblin-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Nixx Sprocketspring in Gadgetzan sprechen.", description = "Bei der Goblin-Ingenieurskunst geht es um praktische Anwendungen mit hohem Profit und noch höherer Explosionskraft! Unsere Baupläne ermöglichen uns, mächtige Bomben und gewaltige Waffen hervorzubringen. Die Anleitung, die Ihr gelesen habt, berichtet darüber.\n\nDie Anleitung erwähnt auch unser uraltes Gelöbnis der Geheimhaltung unserer Baupläne. Sobald Ihr ein Goblin-Ingenieur geworden seid, war's das. Es gibt keinerlei Zugang zur Gnomen-Ingenieurskunst.\n\nWenn Ihr immer noch ein Goblin-Ingenieur werden wollt, dann unterzeichnet dieses Dokument, mit dem Ihr eine lebenslange Geheimhaltung gelobt, und sprecht dann wieder mit mir. Denkt gut darüber nach, <Name>.", progress = "Wenn Ihr das Dokument unterzeichnet habt und bereit seid, es mir zu übergeben, dann war's das. Ihr wisst, dass diese Reise nur in eine Richtung geht. Wenn Ihr bereit seid, dann kommt an Bord!", completion = "Willkommen an Bord, Goblin-Ingenieur &lt;Name&gt;! Ihr werdet bald Zugang zu den mächtigsten Ingenieurskunst-Schemata in ganz Azeroth haben.\n\nNun, da Ihr Euch dem Erwerb dieses Wissens verschrieben habt, ist es Zeit, Eure Goblin-orientierten Ingenieursarbeiten zu begutachten. Von dort ausgehend, werden wir Euch helfen, einen Plan zu erstellen, Eure Goblin-Ingenieurstalente voll auszuschöpfen!", rewards = "Ihr bekommt:\n\n"},
[3639] = {title = "Zeigt Eure Arbeit", objective = "Bringt 20 große Eisenbomben, 20 robuste Dynamitstangen und 5 explosive Schafe zu Nixx Sprocketspring nach Gadgetzan.", description = "Als Euer Mentor will ich Proben Eurer Arbeit sehen. Ihr seid ein geschickter Ingenieur, das steht ganz außer Frage, <Name>. Ich möchte sie gern analysieren, um Möglichkeiten zu erarbeiten, Goblin-orientierte Techniken in Euren zukünftigen Bemühungen noch weiter zu unterstreichen. Ich brauche Folgendes: Zwanzig große Eisenbomben, zwanzig Stäbe robustes Dynamit und fünf explosive Schafe - und achtet darauf, dass sie gesichert sind!\n\nBringt mir diese Gegenstände und ich werde Euch Eure eigene Goblin-Ingenieur-Mitgliedskarte ausstellen, die notwendig ist, um Zugang zu allen Goblin-Ingenieurskunstlehrern zu erhalten!", progress = "Sobald ich die von Euch gefertigten Ingenieurskunst-Gegenstände zur Ansicht erhalten habe, werde ich Euch eine echte Goblin-Ingenieur-Mitgliedskarte aushändigen. Solange die Karte gültig ist, habt Ihr unbegrenzten Zugang zu jedem Goblin-Ingenieurskunstlehrer auf der ganzen Welt.", completion = "Hier ist Eure erste Goblin-Ingenieur-Mitgliedskarte!\n\nDiese Karte wurde für vierzehn Tage im Voraus bezahlt; alle Karten laufen nach zwei Wochen Aktivität ab. Ist das geschehen, zahlt Ihr Euren nächsten Beitrag bei einem beliebigen Goblin-Ingenieurskunstlehrer ein, um eine weitere Karte zu erhalten. Ohne die Karte wird Eure Mitgliedschaft zeitweilig unterbrochen und Ihr habt keinen Zugriff auf neue Baupläne.\n\nDas hat natürlich keinen Einfluss auf das, was Ihr bereits wisst. Einmal Goblin-Ingenieur, immer Goblin-Ingenieur.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGoblin-Ingenieurskunst\n\nIhr bekommt:\n\nGoblin-Ingenieur-Mitgliedskarte"},
[3640] = {title = "Der Schwur der Geheimhaltung", objective = "Wenn Ihr ein Gnomen-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Tüftlermeister Overspark in Ironforge sprechen.", description = "Die Gnomen-Ingenieurskunst beruht auf der Ingenieurskunsttheorie, die besagt, dass sie unseren Bedürfnissen zu dienen hat! Unsere Baupläne ermöglichen uns, Geräte hervorzubringen, die die Welt um uns kontrollieren. Die Anleitung, die Ihr gelesen habt, berichtet darüber.\n\nDie Anleitung erwähnt auch unser uraltes Gelöbnis der Geheimhaltung unserer Baupläne. Sobald Ihr ein Gnomen-Ingenieur geworden seid, war's das. Es gibt keinerlei Zugang zur Goblin-Ingenieurskunst.\n\nWenn Ihr immer noch ein Gnomen-Ingenieur werden wollt, dann unterzeichnet dieses Dokument, mit dem Ihr eine lebenslange Geheimhaltung gelobt, und sprecht dann wieder mit mir. Denkt gut darüber nach, <Name>.", progress = "Wenn Ihr das Dokument unterzeichnet habt und bereit seid, es mir zu übergeben, dann war's das.\n\nDie Geheimnisse, die ich mit Euch teilen werde, sind von solcher Bedeutung, dass der Schwur der Geheimhaltung ein absolutes Muss ist. Ich habe ein solches Dokument unterschrieben, genau wie alle Gnomeningenieure. Ihr werdet einer viel versprechenden Zunft beitreten, Ingenieur <Name>!", completion = "Willkommen an Bord, &lt;Name&gt;! Ihr werdet bald Zugang zu den am höchsten entwickelten Ingenieurskunst-Schemata in ganz Azeroth haben.\n\nNun, da Ihr Euch dem Erwerb dieses Wissens verschrieben habt, ist es Zeit, Eure Gnomen-orientierten Ingenieursarbeiten zu begutachten. Von dort ausgehend, werden wir Euch helfen, einen Plan zu erstellen, Eure Gnomen-Ingenieurstalente voll auszuschöpfen!", rewards = "Ihr bekommt:\n\n"},
[3641] = {title = "Zeigt Eure Arbeit", objective = "Bringt 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Tüftlermeister Overspark in Ironforge.", description = "Als Euer Mentor will ich einige Proben Eurer Arbeit sehen. Ihr seid ein geschickter Ingenieur, das steht ganz außer Frage, <Name>. Ich möchte Eure Arbeit daher analysieren, um Möglichkeiten zu erarbeiten, Gnomen-orientierte Techniken in Euren zukünftigen Bemühungen noch weiter zu fördern. Ich brauche folgende Proben: 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen.\n\nBringt mir diese Gegenstände und ich werde Euch Eure höchsteigene Gnomen-Ingenieur-Mitgliedskarte ausstellen, die notwendig ist, um Zugang zu allen Gnomen-Ingenieurskunstlehrern zu erhalten!", progress = "Sobald ich Eure gefertigten Ingenieurskunst-Gegenstände zur Ansicht erhalten habe, werde ich Euch eine echte Gnomen-Ingenieur-Mitgliedskarte aushändigen. Solange die Karte gültig ist habt Ihr unbegrenzten Zugang zu jedem Gnomen-Ingenieurskunstlehrer auf der ganzen Welt.", completion = "Hier ist Eure erste Gnomen-Ingenieur-Mitgliedskarte!\n\nDiese Karte wurde für vierzehn Tage im Voraus bezahlt; alle Karten laufen nach zwei Wochen Aktivität ab. Ist das geschehen, zahlt Ihr Euren nächsten Beitrag bei einem beliebigen Gnomen-Ingenieurskunstlehrer ein, um eine weitere Karte zu erhalten. Ohne die Karte wird Eure Mitgliedschaft zeitweilig unterbrochen und Ihr habt keinen Zugriff auf neue Baupläne.\n\nDas hat natürlich keinen Einfluss auf das, was Ihr bereits wisst. Einmal Gnomen-Ingenieur, immer Gnomen-Ingenieur.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGnomen-Ingenieurskunst\n\nIhr bekommt:\n\nGnomen-Ingenieur-Mitgliedskarte"},
[3642] = {title = "Der Schwur der Geheimhaltung", objective = "Wenn Ihr ein Gnomen-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Oglethorpe in Booty Bay sprechen.", description = "Die Gnomen-Ingenieurskunst beruht auf der Ingenieurskunsttheorie, die besagt, dass sie unseren Bedürfnissen zu dienen hat! Unsere Baupläne ermöglichen uns, Geräte hervorzubringen, die die Welt um uns kontrollieren. Die Anleitung, die Ihr gelesen habt, berichtet darüber.\n\nDie Anleitung erwähnt auch unser uraltes Gelöbnis der Geheimhaltung unserer Baupläne. Sobald Ihr ein Gnomen-Ingenieur geworden seid, war's das. Es gibt keinerlei Zugang zur Goblin-Ingenieurskunst.\n\nWenn Ihr immer noch ein Gnomen-Ingenieur werden wollt, dann unterzeichnet dieses Dokument, mit dem Ihr eine lebenslange Geheimhaltung gelobt, und sprecht dann wieder mit mir. Denkt gut darüber nach, <Name>.", progress = "Wenn Ihr das Dokument unterzeichnet habt und bereit seid, es mir zu übergeben, dann war's das.\n\nObwohl meine politische Überzeugung sich extrem von der in Gnomeregan vorherrschenden unterscheidet - besonders von der dieses Dummkopfes, Tüftlermeister Overspark -, geht doch der Schwur der Geheimhaltung über alles! Ihr müsst Euch einem einzigen Weg verschreiben und diesem Weg Euer ganzes Leben lang treu ergeben bleiben.", completion = "Willkommen an Bord, &lt;Name&gt;! Ihr werdet bald Zugang zu den am höchsten entwickelten Ingenieurskunst-Schemata in ganz Azeroth haben.\n\nNun, da Ihr Euch dem Erwerb dieses Wissens verschrieben habt, ist es Zeit, Eure Gnomen-orientierten Ingenieursarbeiten zu begutachten. Von dort ausgehend, werden wir Euch helfen, einen Plan zu erstellen, Eure Gnomen-Ingenieurstalente voll auszuschöpfen!", rewards = "Ihr bekommt:\n\n"},
[3643] = {title = "Zeigt Eure Arbeit", objective = "Bringt 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Oglethorpe Obnoticus in Booty Bay.", description = "Als Euer Mentor will ich einige Proben Eurer Arbeit sehen. Ihr seid ein geschickter Ingenieur, das steht ganz außer Frage, <Name>. Ich möchte Eure Arbeit daher analysieren, um Möglichkeiten zu erarbeiten, Gnomen-orientierte Techniken in Euren zukünftigen Bemühungen noch weiter zu fördern. Ich brauche folgende Proben: 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen.\n\nBringt mir diese Gegenstände und ich werde Euch Eure höchsteigene Gnomen-Ingenieur-Mitgliedskarte ausstellen, die notwendig ist, um Zugang zu allen Gnomen-Ingenieurskunstlehrern zu erhalten!", progress = "Sobald ich Eure gefertigten Ingenieurskunst-Gegenstände zur Ansicht erhalten habe, werde ich Euch eine echte Gnomen-Ingenieur-Mitgliedskarte aushändigen. Solange die Karte gültig ist habt Ihr unbegrenzten Zugang zu jedem Gnomen-Ingenieurskunstlehrer auf der ganzen Welt.", completion = "Hier ist Eure erste Gnomen-Ingenieur-Mitgliedskarte!\n\nDiese Karte wurde für vierzehn Tage im Voraus bezahlt; alle Karten laufen nach zwei Wochen Aktivität ab. Ist das geschehen, zahlt Ihr Euren nächsten Beitrag bei einem beliebigen Gnomen-Ingenieurskunstlehrer ein, um eine weitere Karte zu erhalten. Ohne die Karte wird Eure Mitgliedschaft zeitweilig unterbrochen und Ihr habt keinen Zugriff auf neue Baupläne.\n\nDas hat natürlich keinen Einfluss auf das, was Ihr bereits wisst. Einmal Gnomen-Ingenieur, immer Gnomen-Ingenieur.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGnomen-Ingenieurskunst\n\nIhr bekommt:\n\nGnomen-Ingenieur-Mitgliedskarte"},
[3644] = {title = "Mitgliedskarten-Erneuerung", objective = "Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen.", description = nil, progress = "Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen.", completion = "Da Ihr praktizierender Goblin-Ingenieur seid und einen guten Ruf habt, kann ich eine abgelaufene Mitgliedskarte gegen die Gebühr von zwei Goldstücken erneuern. Sobald diese Gebühr entrichtet wurde, werdet Ihr eine neue Mitgliedskarte erhalten. Diese wird Euch Zugang zu Goblin-Ingenieurskunst-Bauplänen von geeigneten Lehrern gewähren.\n\nDiese Karte ist gültig für zwei Wochen Aktivität, danach wird Eure Mitgliedsgebühr erneut fällig! Wenn Ihr Zugang zu Bauplänen benötigt, müsst Ihr Euren Beitrag begleichen.", rewards = "Ihr bekommt:\n\nGoblin-Ingenieur-Mitgliedskarte"},
[3645] = {title = "Mitgliedskarten-Erneuerung", objective = "Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen.", description = nil, progress = "Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen.", completion = "Da Ihr praktizierender Gnomen-Ingenieur seid und einen guten Ruf habt, kann ich eine abgelaufene Mitgliedskarte gegen die Gebühr von zwei Goldstücken erneuern. Sobald diese Gebühr entrichtet wurde, werdet Ihr eine neue Mitgliedskarte erhalten. Diese wird Euch Zugang zu Gnomen-Ingenieurskunst-Bauplänen von geeigneten Lehrern gewähren.\n\nDiese Karte ist gültig für zwei Wochen Aktivität, danach wird Eure Mitgliedsgebühr erneut fällig! Wenn Ihr Zugang zu Bauplänen benötigt, müsst Ihr Euren Beitrag begleichen.", rewards = "Ihr bekommt:\n\nGnomen-Ingenieur-Mitgliedskarte"},
[3646] = {title = "Mitgliedskarten-Erneuerung", objective = "Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen.", description = "[\n]", progress = "Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen.", completion = "Da Ihr praktizierender Goblin-Ingenieur seid und einen guten Ruf habt, kann ich eine abgelaufene Mitgliedskarte gegen die Gebühr von zwei Goldstücken erneuern. Sobald diese Gebühr entrichtet wurde, werdet Ihr eine neue Mitgliedskarte erhalten. Diese wird Euch Zugang zu Goblin-Ingenieurskunst-Bauplänen von geeigneten Lehrern gewähren.\n\nDiese Karte ist gültig für zwei Wochen Aktivität, danach wird Eure Mitgliedsgebühr erneut fällig! Wenn Ihr Zugang zu Bauplänen benötigt, müsst Ihr Euren Beitrag begleichen.", rewards = "Ihr bekommt:\n\nGoblin-Ingenieur-Mitgliedskarte"},
[3647] = {title = "Mitgliedskarten-Erneuerung", objective = "Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen.", description = nil, progress = "Um Eure Mitgliedskarte zu erneuern, müsst Ihr die Erneuerungsgebühr in Höhe von zwei Goldstücken zahlen.", completion = "Da Ihr praktizierender Gnomen-Ingenieur seid und einen guten Ruf habt, kann ich eine abgelaufene Mitgliedskarte gegen die Gebühr von zwei Goldstücken erneuern. Sobald diese Gebühr entrichtet wurde, werdet Ihr eine neue Mitgliedskarte erhalten. Diese wird Euch Zugang zu Gnomen-Ingenieurskunst-Bauplänen von geeigneten Lehrern gewähren.\n\nDiese Karte ist gültig für zwei Wochen Aktivität, danach wird Eure Mitgliedsgebühr erneut fällig! Wenn Ihr Zugang zu Bauplänen benötigt, müsst Ihr Euren Beitrag begleichen.", rewards = "Ihr bekommt:\n\nGnomen-Ingenieur-Mitgliedskarte"},
[3661] = {title = "Elunes Lieblinge?", objective = "Sammelt 15 Wildekinfedern aus dem Hinterland für Erelas Ambersky in Rut'theran.", description = "Wildekins sind unberechenbare Kreaturen, <Name>. Sie sind zu einer außerordentlichen Zärtlichkeit fähig, aber diese Kreaturen können auch eine enorme Wildheit an den Tag legen, wenn etwas für sie sehr Wichtiges bedroht wird.\n\nDiese Kreaturen wurden angeblich von Elune geschaffen und ich bin daran interessiert herauszufinden, ob dies wirklich der Wahrheit entspricht.\n\nVor kurzem habe ich etwas von einer Population von Wildekins gehört, die im Hinterland leben - heimtückische, primitive und wilde Eulenbestien. Man findet sie unter den wild lebenden Tieren dort. Würdet Ihr einige Wildekin-Federn für mich sammeln?", progress = "Versucht, ihnen möglichst aus dem Weg zu gehen, <Name>. Die Wildekin könnten Euer Interesse missverstehen und denken, Ihr habt vor, sie zu verletzen...", completion = "Danke, dass Ihr sie mir gebracht habt, &lt;Name&gt;.\n\nWas habt Ihr über die Wildekin erfahren können?\n\nVielleicht werden uns diese Federn mehr sagen. Wilde Monster oder einfach fehlgeleitete Tiere? Eines Tage möchte ich die Wahrheit kennen...\n\nIch werde meine Forschungen fortsetzen - kommt zu mir zurück und sprecht erneut mit mir, nachdem einige Zeit vergangen ist.", rewards = "Ihr bekommt:\n\n"},
[3681] = {title = "Foliant der Offenbarung", objective = "Sprecht mit Duthorian Rall in Stormwind.", description = "Verzeiht, dass wir Eure Reise unterbrechen, <Volk>, aber ich dachte, Ihr solltet wissen, dass uns vor kurzem eine Meldung aus Stormwind erreicht hat, dass sich Paladine zum Training dort melden sollen.\n\nWenn ich es nicht besser wüsste, würde ich sagen, dass bald etwas Besonderes geschehen wird und es für Euch an der Zeit ist, die Folianten zu studieren.\n\nSucht Duthorian Rall in Stormwind auf. Er trainiert für gewöhnlich Paladine in der Kathedrale des Lichts.", progress = nil, completion = "Willkommen in der Kathedrale des Lichts, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"},
[3701] = {title = "Die glimmenden Ruinen von Thaurissan", objective = "Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Thaurissan-Relikte. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt.", description = "Begebt Euch zu den glimmenden Ruinen von Thaurissan in der brennenden Steppe und sammelt so viele Informationen wie möglich.\n\nEs heißt, dass geheimnisvolle Relikte in den Ruinen verstreut seien. Vielleicht solltet Ihr Eure Suche dort beginnen, <Name>. Nehmt Euch vor den Thaurissan-Wächtern in Acht: Es sind Auftragsmörder, die die Ruinen bewachen und die dort möglicherweise noch immer begrabenen Geheimnisse beschützen, wie auch immer sie aussehen mögen.", progress = "Bringt Ihr neue Informationen?", completion = "Oh je! Diese Informationen erklären einiges in Bezug auf Thaurissan.\n\nEs gibt ja noch so viel mehr zu erfahren!", rewards = "Ihr bekommt:\n\nRing des Aristokraten"},
[3702] = {title = "Die glimmenden Ruinen von Thaurissan", objective = "Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan.", description = "Würdet Ihr gern einen Überblick über die Geschichte der Dunkeleisenzwerge erhalten?", progress = "Erlaubt mir, Euch die Geschichte von Thaurissan zu Ende zu erzählen.", completion = "Sollen wir fortfahren?", rewards = "Ihr bekommt:\n\n"},
[3721] = {title = "Ein eigener OOX", objective = "Ihr habt drei meiner OOX-Leitroboter gefunden! Ihr habt viel mehr als das getan, worum ich Euch gebeten hatte. Daher will ich Euch etwas Besonderes für Eure Hilfe geben. Dies ist eine Miniaturversion jenes Roboters, den Ihr jetzt kennt und liebt, den OOX!\n\nIch würde normalerweise niemandem solch ein potenziell tödliches Gerät anvertrauen, aber Ihr wart eine wirklich große Hilfe. Außerdem wurden die Kampfmechanismen und die Leitlogik dieses Exemplars deaktiviert.\n\nAber abgesehen davon ist das ein echter OOX!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMechanisches Huhn"},
[3741] = {title = "Hilarys Halskette", objective = "Sucht Hilarys Halskette und bringt sie Hilary in Seenhain zurück.", description = "Meine Freundin Hilary hat ihre Halskette verloren und wir können sie einfach nicht finden. Den ganzen Tag lang fischen wir schon hier und haben auch schon rundum überall gesucht. Ich kann mir nur vorstellen, dass sie in den See gefallen ist. Unsere Eltern möchten nicht, dass wir im See schwimmen... meine Mama sagt, dass es unter Wasser ein paar garstige Dinge gibt, aber Ihr seht aus, als ob Ihr keine Angst vor garstigen Dingen hättet.\n\nKönnt Ihr die Kette bitte für uns suchen?", progress = "Hallo! Ich vermisse meine Halskette. Mein Papa hat sie mir geschenkt. Papa sagt, dass es Monster im See gibt. Habt Ihr irgendwelche Monster verhauen?", completion = "Vielen Dank, dass Ihr meine Halskette gefunden habt, lieber &lt;Klasse&gt;... Ihr seid sehr gütig! Auch mein Kätzchen dankt Euch... nicht wahr, Effsee?", rewards = "Ihr bekommt:\n\n"},
[3761] = {title = "Un'Goro-Erde", objective = "Bringt 20 Un'Goro-Erdproben zu Ghede in Thunder Bluff.", description = "Die Erde des Un'Goro Kraters ist angeblich reich an starken magischen Eigenschaften. Der Zirkel des Cenarius möchte diese Erde in großen Mengen untersuchen; zieht daher in die Wildnis von Un'Goro und sammelt genug davon für unsere ständig laufenden Forschungen.\n\nDie angereicherte Erde ist manchmal zu Haufen aufgeworfen und einige der Wildtiere könnten vielleicht nützliche Proben bei sich haben. Bringt sie raus zu Ghede; sucht einfach nach den Erdhaufen und dem Tauren, der Befehle brüllt. Er ist kein schlechter Kerl, aber verärgert ihn lieber nicht!", progress = "Rühren, Gefreiter. Wenn Ihr hier seid, um Erde aus Un'Goro abzuladen - hervorragend! Anderenfalls verschwindet.", completion = "Oh, macht's Euch ruhig bequem, Gefreiter &lt;Name&gt;. Bemüht Euch bloß nicht, mir zu helfen, diese Erde auf die Haufen da zu schaufeln! Wenn die großen Geister gewollt hätten, dass sie da hinkommt, hätten sie die dort bestimmt hinaufgezaubert, nicht wahr?!\n\nErzdruide Runetotem möchte erneut mit Euch sprechen, aber Ihr werdet feststellen, dass für seine nächste Aufgabe das Wissen eines Gesellen der Kräuterkunde hilfreich wäre. Falls Ihr nicht über dieses Wissen verfügt, wird er trotzdem Verwendung für Euch finden.", rewards = "Ihr bekommt:\n\n"},
[3762] = {title = "Erzdruide Runetotem helfen", objective = "Sprecht in Thunder Bluff mit Erzdruide Hamuul Runetotem.", description = "Entschuldigung, <Klasse>, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Thunder Bluff ist sehr an erfahrenen Abenteurern wie Euch interessiert, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein Geringerer als Hamuul Runetotem an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm auf der Anhöhe der Ältesten in Thunder Bluff.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;; ich freue mich, dass Ihr daran interessiert seid, an unseren Forschungen teilzunehmen. Es gibt viel zu tun und ich würde Euch einen schlechten Dienst erweisen, wenn ich Euch sagen würde, dass die Arbeit, die dies mit sich bringt, ungefährlich sei. Hoffentlich erschreckt Euch das nicht ... aber so, wie Ihr ausseht, würde ich sagen, dass Ihr schon früher der Gefahr ins Auge geblickt habt.", rewards = "Ihr bekommt:\n\n"},
[3763] = {title = "Erzdruide Staghelm helfen", objective = "Sprecht mit Erzdruide Fandral Staghelm in Darnassus.", description = "Entschuldigung, <Klasse>, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Staghelm an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.", progress = nil, completion = "Nun gut, &lt;Klasse&gt;... da Ihr informiert wurdet, dass ich dieses Forschungsprojekt selbst leite, seid Ihr offensichtlich so schnell Ihr konntet gekommen.\n\nNachdem Ihr nun hier seid, folgt meinen Ausführungen, wenn ich die Einzelheiten erläutere, bitte mit voller Konzentration; ich möchte mich nicht wiederholen müssen.", rewards = "Ihr bekommt:\n\n"},
[3764] = {title = "Un'Goro-Erde", objective = "Bringt 20 Un'Goro-Erdproben zu Jenal in Darnassus.", description = "Die Erde des Un'Goro Kraters ist angeblich reich an starken magischen Eigenschaften. Ich möchte Wahrheit von Unwahrheit unterscheiden; begebt Euch daher in die Wildnis von Un'Goro und sammelt ausreichend hochwertige Erdproben für unsere ständig laufenden Studien.\n\nIhr glaubt möglicherweise, dass die Aufgabe, etwas zu sammeln, unter Eurer Würde sei; doch mit solch einer Einstellung macht Ihr Euch weder bei mir noch beim Zirkel des Cenarius beliebt. Bringt die Proben zu Jenal, der zweifellos draußen hinter diesem Baum müßig herumlungert; sucht einfach nach den Erdhaufen. Er wird sich um die Logistik kümmern, nicht ich.", progress = "Ach ja, die Erde. Der Erzdruide möchte zwanzig Ladungen pro Abenteurer, und zwanzig Ladungen wird er bekommen. Lasst die, die gegen uns konspirieren, auf der Strecke bleiben!", completion = "Ladet Eure wertvolle Fracht hier ab, edler &lt;Klasse&gt;. Es muss eine rechte Bürde gewesen sein... ähnlich der Bürde, die ich als Visionär mit mir herumtrage. Hier ist eine Entlohnung für Eure Arbeit, wie es der Erzdruide höchstpersönlich angewiesen hat.\n\nErzdruide Staghelm möchte erneut mit Euch sprechen, &lt;Name&gt;, aber für seine nächste Aufgabe wäre Euch geholfen, wenn Ihr über das Wissen eines Gesellen der Kräuterkunde verfügt. Falls Ihr nicht über dieses Wissen verfügt, werdet Ihr dennoch hilfreich für den Zirkel sein.", rewards = "Ihr bekommt:\n\n"},
[3765] = {title = "Verderbnis in der Fremde", objective = "Reist zu Gershala Nightwhisper in Auberdine.", description = "Stormwind - geschäftiger Dreh- und Angelpunkt der Aktivität.\n\nIch bin weit gereist, um Hilfe zu suchen. Man hört häufig, dass mutige Abenteurer durch die Straßen dieser Stadt ziehen.\n\nMein Bruder Gershala benötigt Hilfe in Dunkelküste. Er lebt in der Küstenstadt Auberdine.\n\nDie Reise ist lang und abenteuerlich. Daher suche ich nach Hilfe. Es sollte ein erfahrener <Klasse> sein, so wie Ihr.", progress = nil, completion = "Ah, mein Bruder Argos hat Euch also zu mir geschickt? Ich nehme an, Ihr seid müde von Eurer Reise. Aber wir müssen über vieles sprechen.", rewards = "Ihr bekommt:\n\n"},
[3781] = {title = "Morgenkornforschung", objective = "Bringt den Samenkorngutschein des Erzdruiden zu Mathrengyl Bearwalker in der Enklave des Cenarius von Darnassus.", description = "Mit dem, was wir einen Immergrünbeutel nennen, haben wir Tharlendrissamenkörner in der Erde vom Un'Goro Krater kultiviert. Diese Samenkörner sind zu einer Ansammlung wirksamer Kräuter erblüht. Ein Ergebnis ist das Morgenkorn, ein rätselhaftes Kraut, von dem wir wenig wissen; ich habe vor, dieses Geheimnis zu enthüllen.\n\nBringt das nach unten zu Mathrengyl, und er wird Euch einige Samenkörner geben, mit denen Ihr beginnen könnt. Wenn Ihr diese verbraucht habt, müsst Ihr weitere von ihm kaufen.", progress = "Friede und Klarheit seien mit Euch, Freund. Ihr seid im Auftrag des Erzdruiden höchstpersönlich hier, nicht wahr?", completion = "Ja, dieser Gutschein ist gültig für zwanzig Pakete mit Samenkörnern. Wenn Ihr die verbraucht habt, kein Problem, bei uns gibt es noch mehr. Leider ist es aber recht kostspielig, Tharlendrissamenkörner in großer Zahl zu produzieren. Daher bittet der Zirkel des Cenarius diejenigen, die uns helfen, einen Teil der Kosten auszugleichen.\n\nDiejenigen, die mit Morgenkorn zurückkehren, werden feststellen, dass die Belohnung, die der Erzdruide bietet, die Kosten mehr als wettmacht.", rewards = "Ihr bekommt:\n\nPaket mit Tharlendrissamenkörnern"},
[3782] = {title = "Morgenkornforschung", objective = "Bringt den Samenkorngutschein zu Bashana Runetotem in Thunder Bluff.", description = "Mit dem, was wir einen Immergrünbeutel nennen, haben wir Tharlendrissamenkörner in der Erde vom Un'Goro Krater kultiviert. Diese Samenkörner sind zu einer Ansammlung wirksamer Kräuter erblüht. Ein Ergebnis ist das Morgenkorn, ein rätselhaftes Kraut, von dem wir wenig wissen; ich hoffe, dieses Geheimnis für den Zirkel zu enthüllen.\n\nBringt diesen Gutschein zu meiner Tochter Bashana, und sie wird Euch einige Samenkörner geben, damit Ihr uns helfen könnt. Wenn Ihr diese verbraucht habt, müsst Ihr weitere von ihr kaufen.", progress = "Friede mit dir, Freund. Ihr seid im Auftrag des Erzdruiden höchstpersönlich hier, nicht wahr?", completion = "Ja, dieser Gutschein ist gültig für zwanzig Pakete mit Samenkörnern. Wenn Ihr die Samenkörner verbraucht habt, habe ich noch mehr, die ich Euch verkaufen kann.\n\nLeider ist es aber recht kostspielig, &lt;Name&gt;, Tharlendrissamenkörner in großer Zahl zu produzieren. Daher bittet der Zirkel des Cenarius diejenigen, die uns helfen, einen Teil der Kosten auszugleichen. Diejenigen, die mit Morgenkorn zurückkehren, werden feststellen, dass die Belohnung, die der Erzdruide bietet, die Kosten mehr als wettmacht.", rewards = "Ihr bekommt:\n\nPaket mit Tharlendrissamenkörnern"},
[3783] = {title = "Sind wir endlich da, Yeti?", objective = "Sammelt 10 dicke Yetifelle für Umi Rumplesnicker in Everlook.", description = "Meine Freunde hatten immerzu tolle Ideen. Ich hatte nie das Gefühl mit ihnen mithalten zu können... bis heute! Gerade habe ich die Pläne für etwas Großes angefertigt! Wenn Ihr versprecht, es nicht zu erzählen, weihe ich Euch in das Geheimnis ein... \n\nIch werde einen mechanischen Yeti herstellen! Meine Freunde werden ganz bestimmt durchdrehen, wenn sie ihn sehen, aber wenn sie darüber hinweg sind, bin ich mir sicher, dass sie beeindruckt sein werden!\n\nFür den Anfang benötige ich dickes Yetifell von Eisdistelyetis. Werdet Ihr helfen? Ihr könnt sie im Südosten finden.", progress = "Ich habe hier viel zu tun. Bitte, besorgt mir diese Felle, so schnell Ihr könnt!", completion = "Diese Felle sind perfekt, &lt;Name&gt;. Damit haben wir einen guten Anfang!", rewards = "Ihr bekommt:\n\n"},
[3784] = {title = "Erzdruide Runetotem helfen", objective = "Sprecht in Thunder Bluff mit Erzdruide Hamuul Runetotem.", description = "Entschuldigung, <Klasse>, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Thunder Bluff ist sehr an erfahrenen Abenteurern wie Euch interessiert, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein Geringerer als Hamuul Runetotem an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm auf der Anhöhe der Ältesten in Thunder Bluff.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;; ich freue mich, dass Ihr daran interessiert seid, an unseren Forschungen teilzunehmen. Es gibt viel zu tun und ich würde Euch einen schlechten Dienst erweisen, wenn ich Euch sagen würde, dass die Arbeit, die dies mit sich bringt, ungefährlich sei. Hoffentlich erschreckt Euch das nicht... aber so, wie Ihr ausseht, würde ich sagen, dass Ihr schon früher der Gefahr ins Auge geblickt habt.", rewards = "Ihr bekommt:\n\n"},
[3785] = {title = "Morgenkornforschung", objective = "Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Un'Goro-Erdproben, um Morgenkorn zu kultivieren.\n\nBringt 10 Einheiten Morgenkorn zu Mathrengyl Bearwalker in Darnassus.", description = "Hier ist Euer Immergrünbeutel, den Ihr für die Nutzung der Tharlendrissamenkörner benötigen werdet. Ihr benötigt außerdem noch Un'Goro-Erdproben als Dünger für die Samenkörner. Verwendet einfach den Beutel, wenn Ihr alles habt; der Beutel wird den Rest erledigen.\n\nWenn Ihr genug Einheiten Morgenkorn habt, bringt sie mir hierher in die Enklave. Und belästigt bitte nicht den Erzdruiden; er ist ein sehr beschäftigter Mann und muss nicht jedes Mal gestört werden, wenn jemand mit einer Ladung Morgenkorn zurückkehrt!", progress = "Also, <Name>, habt Ihr Morgenkorn für die wichtigen Forschungen des Erzdruiden gezüchtet? Die Arbeit, die er für den Zirkel des Cenarius leistet, ist sehr wichtig und Eure Hilfe wird nicht unbemerkt bleiben!", completion = "Gut gemacht, &lt;Name&gt;, ich werde sie dem Erzdruiden geben, wenn er sie benötigt. Nehmt dies in der Zwischenzeit als Zeichen der Wertschätzung des Zirkels des Cenarius.\n\nWir benötigen fortlaufend Morgenkorn; wenn Ihr uns auch weiterhin helfen wollt, dann kehrt bitte zu mir zurück, sobald Ihr weiteres Morgenkorn kultiviert habt.", rewards = "Ihr bekommt:\n\nBehälter des Zirkels des Cenarius"},
[3786] = {title = "Morgenkornforschung", objective = "Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Un'Goro-Erdproben, um Morgenkorn zu kultivieren.\n\nBringt 10 Einheiten Morgenkorn zu Bashana Runetotem in Thunder Bluff.", description = "Hier ist Euer Immergrünbeutel, den Ihr für die Nutzung der Tharlendrissamenkörner benötigen werdet. Ihr benötigt außerdem noch Un'Goro-Erdproben als Dünger für die Samenkörner. Verwendet einfach den Beutel, wenn Ihr alles habt; der Beutel wird den Rest erledigen.\n\nWenn Ihr genug Einheiten Morgenkorn habt, bringt sie zu mir hierher auf die Anhöhe der Ältesten. Belästigt bitte nicht den Erzdruiden; er wird sehr mit den Forschungsarbeiten beschäftigt sein sowie mit den tausend anderen Sorgen, die er hat!", progress = "Also, <Name>, habt Ihr Morgenkorn für die wichtigen Forschungen des Erzdruiden gezüchtet? Die rätselhaften Eigenschaften des Un'Goro Kraters werden dank Eurer Hilfe mit jedem Tag klarer.", completion = "Gut gemacht, &lt;Name&gt;, ich werde sie dem Erzdruiden geben, wenn er sie benötigt. Nehmt dies in der Zwischenzeit als Zeichen der Wertschätzung des Zirkels des Cenarius.\n\nWir benötigen im Moment fortlaufend Morgenkorn; wenn Ihr uns auch weiterhin helfen wollt, dann kehrt bitte zu mir zurück, sobald Ihr weiteres kultiviert habt.", rewards = "Ihr bekommt:\n\nBehälter des Zirkels des Cenarius"},
[3787] = {title = "Jonespyres Bitte", objective = "Sprecht mit Quintis Jonespyre in der Festung Feathermoon.", description = "Entschuldigung...\n\nEin Kollege von mir würde gern mit Euch über die Forschungsarbeiten sprechen, die Ihr zusammen mit dem Zirkel des Cenarius durchführt. Er ist ein Druide namens Quintis Jonespyre und lebt in der Festung Feathermoon in Feralas. Er würde gern mit Euch über Morgenkorn reden... und er würde es vorziehen, wenn unser Gespräch dem Erzdruiden nicht zu Ohren kommt.\n\nFalls Ihr interessiert seid, dann sprecht mit ihm; zweifellos wird alles klargelegt, wenn Ihr es tut.", progress = nil, completion = "Ich danke Euch für Euer Kommen, müder Reisender! Erlaubt mir, mich vorzustellen - ich bin Quintis Jonespyre, Druide und bescheidener Diener von Malfurion und dem Zirkel des Cenarius. Meine Kollegen (General Shandris Feathermoon und das Protektorat - vielleicht habt Ihr schon von uns gehört) und ich möchten mit Euch über die Arbeit sprechen, die Ihr für Fandral Staghelm in Darnassus erledigt.\n\nBevor wir weitermachen, möchte ich Euch jedoch bitten, unser Gespräch für Euch zu behalten. Wenn Ihr damit kein Problem habt, dann können wir fortfahren.", rewards = "Ihr bekommt:\n\n"},
[3788] = {title = "Jonespyres Bitte", objective = "Sprecht mit Quintis Jonespyre in der Festung Feathermoon.", description = "Entschuldigung...\n\nEin Kollege von mir würde gern mit Euch über die Forschungsarbeiten sprechen, die Ihr zusammen mit dem Zirkel des Cenarius durchführt. Er ist ein Druide namens Quintis Jonespyre und lebt hier in der Festung Feathermoon. Er würde gern mit Euch über Morgenkorn reden... und er würde es vorziehen, wenn unser Gespräch dem Erzdruiden nicht zu Ohren kommt.\n\nFalls Ihr interessiert seid, dann sprecht mit ihm; zweifellos wird alles klargelegt, wenn Ihr es tut.", progress = nil, completion = "Ich danke Euch für Euer Kommen, müder Reisender! Erlaubt mir, mich vorzustellen - ich bin Quintis Jonespyre, Druide und bescheidener Diener von Malfurion und dem Zirkel des Cenarius. Meine Kollegen (General Shandris Feathermoon und das Protektorat - vielleicht habt Ihr schon von uns gehört) und ich möchten mit Euch über die Arbeit sprechen, die Ihr für Fandral Staghelm in Darnassus erledigt.\n\nBevor wir weitermachen, möchte ich Euch jedoch bitten, unser Gespräch für Euch zu behalten. Wenn Ihr damit kein Problem habt, dann können wir fortfahren.", rewards = "Ihr bekommt:\n\n"},
[3789] = {title = "Erzdruide Staghelm helfen", objective = "Sprecht mit Erzdruide Fandral Staghelm in Darnassus.", description = "Entschuldigung, <Klasse>, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Staghelm an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.", progress = nil, completion = "Nun gut, &lt;Klasse&gt;... da Ihr informiert wurdet, dass ich dieses Forschungsprojekt selbst leite, seid Ihr offensichtlich so schnell Ihr konntet gekommen.\n\nNachdem Ihr nun hier seid, folgt meinen Ausführungen, wenn ich die Einzelheiten erläutere, bitte mit voller Konzentration; ich möchte mich nicht wiederholen müssen.", rewards = "Ihr bekommt:\n\n"},
[3790] = {title = "Erzdruide Staghelm helfen", objective = "Sprecht mit Erzdruide Fandral Staghelm in Darnassus.", description = "Entschuldigung, <Klasse>, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Staghelm an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.", progress = nil, completion = "Nun gut, &lt;Klasse&gt;... da Ihr informiert wurdet, dass ich dieses Forschungsprojekt selbst leite, seid Ihr offensichtlich so schnell Ihr konntet gekommen.\n\nNachdem Ihr nun hier seid, folgt meinen Ausführungen, wenn ich die Einzelheiten erläutere, bitte mit voller Konzentration; ich möchte mich nicht wiederholen müssen.", rewards = "Ihr bekommt:\n\n"},
[3791] = {title = "Das Geheimnis des Morgenkorns", objective = "Bringt 10 Einheiten Morgenkorn zu Quintis Jonespyre in der Festung Feathermoon.", description = "Lasst mich offen mit Euch sein, <Name>. Ich bin interessiert zu wissen - nein, ich muss es unbedingt wissen, warum der Erzdruide in Darnassus den Namen des Zirkels des Cenarius sowie dessen Mittel benutzt, um große Mengen Morgenkorn zu beschaffen. Ich bin ein Forscher - Flüche sind meine Spezialität. Ich habe gehört, dass Morgenkorn unter den richtigen Bedingungen Fähigkeiten verströmt wie andere Kräuter, die in primitiven Flüchen eingesetzt werden.\n\nIch möchte mehr darüber wissen und bitte Euch um Eure Hilfe. Bringt mir 10 Einheiten Morgenkorn und ich werde mich um Euch kümmern.", progress = "Ich benötige zehn Einheiten Morgenkorn - das sollte genügen, um meine Forschungen zumindest in Gang zu bringen. Zweifellos werde ich etliche davon beim Verfolgen falscher Spuren verbrauchen, aber das liegt in der Natur der Forschung.", completion = "Gah, durch dieses Morgenkorn fühle ich mich... merkwürdig. Was in Elunes Namen will Staghelm mit diesen Dingern?\n\nEgal, nochmals danke für Eure Hilfe. Hier habt Ihr eine Kleinigkeit... Ihr wisst schon, für Eure Mühe. Meine Forschungen zum Thema Morgenkorn werden einige Zeit dauern, und ich werde zweifellos mehr davon benötigen. Wo ich gerade dabei bin: Ich denke, ich könnte die Zeit vielleicht nutzen um herauszufinden, ob Morgenkorn eine brauchbare alchimistische Verwendung hat. Trotzdem fühle ich mich in seiner Umgebung äußerst unwohl.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nQuintis' Forschungs-HandschuheBorkeneisenschulterstücke\n\nIhr bekommt außerdem:\n\n"},
[3792] = {title = "Morgenkorn für die Festung Feathermoon", objective = "Abermals hallo, <Name>. Meine Forschung macht gute Fortschritte, aber wenn Ihr fünf weitere Einheiten Morgenkorn habt, würde ich Euch die sehr gern abnehmen. Na ja... 'gern' ist nicht wirklich der richtige Ausdruck dafür; je länger ich mich in seiner Umgebung befinde, desto unwohler fühle ich mich. Aber für meine Forschungen ist es nun mal nötig, dass ich mich zusammenreiße und weiterarbeite.", description = nil, progress = "Abermals hallo, <Name>. Meine Forschung macht gute Fortschritte, aber wenn Ihr fünf weitere Einheiten Morgenkorn habt, würde ich Euch die sehr gern abnehmen. Na ja... 'gern' ist nicht wirklich der richtige Ausdruck dafür; je länger ich mich in seiner Umgebung befinde, desto unwohler fühle ich mich. Aber für meine Forschungen ist es nun mal nötig, dass ich mich zusammenreiße und weiterarbeite.", completion = "Vielen Dank, &lt;Name&gt;; ich werde das erst einmal zu meinem Vorrat legen. Und wenn ich auch nicht über die Mittel wie Staghelm verfüge, so bin ich doch in der Lage, Euch etwas für Eure Bemühungen zu geben. Denn schließlich, wer kann schon wissen, was geschehen wird, wenn Staghelm Morgenkorn um Morgenkorn bekommt. Hier geht etwas Merkwürdiges vor sich, denkt an meine Worte.\n\nVergesst nicht, dass ich immer nach weiterem Morgenkorn suche. Ich nehme Euch immer jeweils fünf Einheiten ab.", rewards = "Ihr bekommt:\n\nPaket mit Tharlendrissamenkörnern"},
[3801] = {title = "Dunkeleisenerbe", objective = "Sprecht mit Franclorn Forgewright, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten.Seid gegrüßt, <Name>. Ich bin Franclorn Forgewright. Ja, der Franclorn Forgewright, der für die Stonewrought-Methode der Architektur verantwortlich ist. Ihr habt zweifellos während Eurer Abenteuer in unserer vom Krieg zerrissenen Welt eines meiner Werke durchquert oder habt auf einem gestanden.\n\nIhr fragt Euch wahrscheinlich, warum ich hier bin und was ich von Euch möchte - beides berechtigte Fragen.\n\nIch brauche natürlich Eure Hilfe. Im Austausch für Eure Hilfe gewähre ich Euch den Schlüssel zu den Tiefen meiner verfluchten Stadt.", description = "Seid gegrüßt, <Name>. Ich bin Franclorn Forgewright. Ja, der Franclorn Forgewright, der für die Stonewrought-Methode der Architektur verantwortlich ist. Ihr habt zweifellos während Eurer Abenteuer in unserer vom Krieg zerrissenen Welt eines meiner Werke durchquert oder habt auf einem gestanden.\n\nIhr fragt Euch wahrscheinlich, warum ich hier bin und was ich von Euch möchte - beides berechtigte Fragen.\n\nIch brauche natürlich Eure Hilfe. Im Austausch für Eure Hilfe gewähre ich Euch den Schlüssel zu den Tiefen meiner verfluchten Stadt.", progress = nil, completion = "Ganz gleich, ob es Gier oder ein Akt selbstloser Hingabe ist, der Euch hierher geführt hat, was immer Ihr unternehmt, wird zu unserem Wohle sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3802] = {title = "Dunkeleisenerbe", objective = "Erschlagt Fineous Darkvire und bergt den großen Hammer Ironfel. Bringt Ironfel zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Forgewright.", description = "Ihr findet Fineous Darkvire jenseits des Rings des Gesetzes in der Halle des Handwerks. Tötet den elenden Wicht und nehmt Ironfel an Euch.\n\nBringt Ironfel zum Schrein von Thaurissan und legt den Hammer an seinen rechtmäßigen Ort: in die Hände der Statue, die mir zu Ehren aufgestellt wurde.\n\nSobald dieses getan ist, öffnet sich das Fach, in dem ich den Hauptschlüssel verborgen habe. Wichtiger jedoch ist: Ironfel wird für alle Zeiten in meinen Händen bleiben. Sollte jemand versuchen, den Hammer zu entfernen, werden Statue und Hammer bersten und für immer verloren sein.", progress = "Die Statue ragt bedrohlich über Euch auf.", completion = "Der Hammer gleitet sicher an seinen Platz, in greifbarer Nähe des massiven Monuments der Dunkeleisenzwerge. Am Fundament der Statue öffnet sich ein winziges Fach. Darin findet Ihr...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nSchlüssel zur Schattenschmiede"},
[3803] = {title = "Morgenkorn nach Darnassus", objective = "Der Erzdruide sucht ständig nach mehr Morgenkorn für die weiteren Forschungsarbeiten des Zirkels des Cenarius. Wir nehmen jeweils zehn Einheiten ab und belohnen Euch mit umfangreichen Dingen, die Ihr nützlich finden werdet. Wenn Ihr zehn Einheiten habt, lasst es mich wissen, und ich werde Euch entsprechend belohnen.", description = nil, progress = "Der Erzdruide sucht ständig nach mehr Morgenkorn für die weiteren Forschungsarbeiten des Zirkels des Cenarius. Wir nehmen jeweils zehn Einheiten ab und belohnen Euch mit umfangreichen Dingen, die Ihr nützlich finden werdet. Wenn Ihr zehn Einheiten habt, lasst es mich wissen, und ich werde Euch entsprechend belohnen.", completion = "Hervorragend - dieses Morgenkorn wird den Erzdruiden zweifellos erfreuen. Ich muss aber zugeben... allein seine Nähe bereitet mir ein unangenehmes Gefühl. Ich kann mir gar nicht vorstellen, wie schwierig es für den Erzdruiden ist, es in so großer Menge zu ertragen!\n\nDas ist für Euch, &lt;Name&gt;. Der Zirkel des Cenarius dankt Euch für Eure unermüdliche Unterstützung.", rewards = "Ihr bekommt:\n\nBehälter des Zirkels des Cenarius"},
[3804] = {title = "Morgenkorn nach Thunder Bluff", objective = "Der Erzdruide sucht ständig nach mehr Morgenkorn für das Forschungsprojekt des Zirkels des Cenarius über den Un'Goro Krater. Wir nehmen jeweils zehn Einheiten ab und belohnen Euch mit umfangreichen Dingen, die Ihr nützlich finden werdet. Wenn Ihr zehn Einheiten habt, lasst es mich wissen, und ich werde Euch entsprechend belohnen.", description = nil, progress = "Der Erzdruide sucht ständig nach mehr Morgenkorn für das Forschungsprojekt des Zirkels des Cenarius über den Un'Goro Krater. Wir nehmen jeweils zehn Einheiten ab und belohnen Euch mit umfangreichen Dingen, die Ihr nützlich finden werdet. Wenn Ihr zehn Einheiten habt, lasst es mich wissen, und ich werde Euch entsprechend belohnen.", completion = "Hervorragend - dieses Morgenkorn wird zweifellos hilfreich sein, wenn die Zeit kommt. Wir wissen, dass die Nachtelfen ähnliche Forschungen über dieses Kraut durchführen, obwohl es nicht klar ist, wie sie sie nutzen werden, wenn sie etwas herausfinden. Der Erzdruide meint, dass wir so lange Morgenkorn benötigen werden, bis wir das Geheimnis hinter diesem Kraut gelüftet haben.\n\nDas ist für Euch, &lt;Name&gt;. Der Zirkel des Cenarius dankt Euch für Eure unermüdliche Unterstützung.", rewards = "Ihr bekommt:\n\nBehälter des Zirkels des Cenarius"},
[3821] = {title = "Schreckensfels", objective = "Begebt Euch in die brennende Steppe und findet heraus, was aus Sha'ni Proudtusk geworden ist.", description = "Sha'ni wurde ausgeschickt, um Berichte über merkwürdige rituelle Aktivitäten zu untersuchen, die vor mehr als drei Wochen von den Feuermagenogern der brennenden Steppe kamen.\n\nGoretooth sagt mir, dass er noch nichts wieder von dieser Gruppe gehört hätte und dass es am besten sei, wenn ich einfach weitermache und mich auf meine Aufgabe konzentriere. Könnt Ihr Euch das vorstellen? Das ist doch meine Frau!\n\nIch kann meinen Posten nicht verlassen, <Name>, aber ich muss wissen, was aus Sha'ni geworden ist. Reist in die brennende Steppe und sucht nach ihr.", progress = nil, completion = "Mein armer Thal'trak.\n\nWir hatten vor, zu meinen Eltern ins Hinterland zu ziehen, sobald unsere Dienstzeit abgeleistet war. Jetzt sind unsere Pläne ruiniert!", rewards = "Ihr bekommt:\n\n"},
[3822] = {title = "Krom'Grul", objective = "Holt Sha'nis Nasenring von Krom'Grul zurück und bringt ihn zu Thal'trak in Kargath. Durchsucht die verschiedenen Höhlen und Minen im Schreckensfels.", description = "Meine ganze Gruppe wurde gefangen genommen, <Name>. Alle wurden getötet - alle, außer mir.\n\nIhr Anführer Krom'Grul wollte mich für irgendein Ritual aufsparen.\n\nIch wurde von dem Biest an diesen Altar gekettet und brutal misshandelt. Mein körperliches Sein gab nach einer Stunde dieser Folter auf. Die Bestie riss mir dann meinen Ehenasenring aus dem Gesicht und steckte ihn an seinen Finger. Noch niemals habe ich solch eine Rohheit gesehen!\n\nFindet Krom'Grul und erledigt ihn! Bringt meinen Ring zurück zu Thal'trak.\n\nUnd, <Name>, sagt ihm, dass wir uns wiedersehen werden ... in einem anderen Leben.", progress = "Habt Ihr Sha'ni gefunden? Geht es ihr gut?", completion = "&lt;Thal'trak bricht zusammen.&gt;\n\nWir wollten ins Hinterland ziehen. Hat sie Euch das schon erzählt? Das sollte ihre letzte Mission sein.\n\n&lt;Thal'trak schluchzt.&gt;\n\nIch will ihn nicht, &lt;Name&gt;. Behaltet ihn, werft ihn weg, es ist mir egal! Der Ring hat keine Bedeutung mehr für mich. Nicht ohne sie ...", rewards = "Ihr bekommt:\n\nSha'nis Ring"},
[3823] = {title = "Die Feuermagenoger auslöschen", objective = "Tötet 15 Ogermagier der Feuermägen, 7 Oger der Feuermägen sowie 7 Schläger der Feuermägen und kehrt zu Oralius zurück, wenn Ihr fertig seid.", description = "Wir müssen unsere Feinde schlagen, bevor sie uns schlagen!\n\nIch werde es kurz machen, Soldat.\n\nDie Feuermagenoger der brennenden Steppe sind Verbündete der Orcs des Blackrockklans. Sie arbeiten eng mit diesen üblen Orcs zusammen, bewachen den mineralreichen Schreckensfels und halten die Nachschublinien ständig offen.\n\nHinterlasst Euer Zeichen, <Name>. Legt ihre Streitkräfte lahm und kehrt zu mir zurück, wenn der Auftrag erledigt ist.\n\n<Oralius greift in die Luft und macht eine erwürgende Bewegung.>\n\nICH BRING DICH UM, WINKY!", progress = "Es ist nicht annähernd genug Blut auf Eurer Uniform, Soldat!", completion = "Hervorragend, Soldat! Die Orcs und Oger werden von diesem Schlag minutenlang, vielleicht sogar stundenlang gelähmt sein!", rewards = "Ihr bekommt:\n\n"},
[3824] = {title = "Gor'tesh der Schläger-Lord", objective = "Sucht Gor'tesh irgendwo im Westen des Schreckensfelsens. Tötet Gor'tesh und bringt dann seinen abgehackten Kopf zu Oralius in der brennenden Steppe zurück.", description = "Sie sind gelähmt, ich sag's Euch! Unser nächster Schlag muss entscheidend sein.\n\nDer Lord dieser Bestien, Gor'tesh, muss eliminiert werden. Wichtiger noch, sein Kopf muss zu mir zurückgebracht werden, damit ich die dritte Phase unseres Angriffs auf die Feuermagenoger vorbereiten kann.\n\nSeid gewarnt, Soldat, Gor'tesh regiert nicht vom Schreckensfelsen aus. Stattdessen befindet er sich in einem Gebäude der Blackrockorcs westlich vom Schreckensfelsen.\n\nEure Befehle sind daher einfach. Sucht Gor'tesh und hackt ihm seinen fetten Kopf ab. Kommt zurück, wenn Eure Aufgabe erledigt ist.\n\nKLAPPE HALTEN, WINKY!", progress = "Welch wunderbarer Tag! Seid Ihr mit dem Kopf zurückgekehrt?", completion = "Seht Euch das an, Soldat. Widerlich! Wenn die verbleibenden Feuermagenoger diese fette Visage auf einem Pfahl aufgespießt sehen, der auf der Spitze ihres Berges steht, wird es zu einer Massenhysterie kommen!\n\n&lt;Oralius kichert wild.&gt;", rewards = "Ihr bekommt:\n\n"},
[3825] = {title = "Ogerkopf auf einem Pfahl = Party", objective = "Nehmt Gor'teshs abgehackten Kopf und platziert ihn auf dem Gipfel des Schreckensfelsens. Sucht nach einem weichen Erdhügel, um den Pfahl aufzustellen.", description = "Jetzt müsst Ihr nur noch eine Sache erledigen, Soldat.\n\nIch habe mir die Freiheit genommen, Gor'teshs Kopf auf einen Pfahl zu stecken. Ihr sollt jetzt einfach diesen Kopf zur Spitze des Schreckensfelsens bringen und ihn in den Boden rammen. Wenn Ihr das getan habt, seht zu, wie diese feigen Oger um ihr Leben rennen! Nachdem Ihr Euren Spaß hattet, kommt zu mir zurück und ich werde Euch für all Eure harte Arbeit belohnen.\n\n<Oralius scheint seinen Bezug zur Realität zu verlieren.>", progress = "Und? Habt Ihr von dem Ereignis Bilder gemalt?", completion = "Hervorragende Arbeit, Soldat! Einfach unglaublich! Oh, ich werde dafür die Tapferkeitsmedaille bekommen, äh, ich meine, Ihr werdet fürstlich dafür belohnt werden!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nUnerträgliche StulpenWürgeband\n\nIhr bekommt außerdem:\n\n"},
[3841] = {title = "Waise sucht Zuhause", objective = "Sprecht mit Quentin in Tausend Nadeln.", description = "Ach, hallo, <Name>. Ich freue mich sehr, Euch wiederzusehen. Wie war Eure Reise nach Darnassus?\n\nNa, Ihr seid bestimmt froh darüber, dass wir während Eurer Abwesenheit ziemliche Fortschritte gemacht haben. Wir haben sogar ein ganzes Nest voller Eier gerettet. Leider ist die Mutter gestorben, ehe wir sie gefunden haben.\n\nSagt mal, wollt Ihr nicht vielleicht so ein Tierchen haben? Es sieht aus, als würden sie bald schlüpfen, und dann brauchen sie <einen guten Vater/eine gute Mutter>. Was meint Ihr?\n\nWenn Ihr wirklich Interesse habt, dann bringt eines der Eier zu Quentin. Ihr findet ihn an der Rennbahn in der schimmernden Ebene. Er kann Euch mehr darüber sagen.", progress = "Ja, hallo, <Klasse>.\n\nLasst Euch nicht von meinem Aufenthaltsort täuschen, ich bin nicht wegen der Rennen hier... so unterhaltsam sie auch sein mögen.\n\nEigentlich bin ich hier in Tausend Nadeln, um so gut es geht zu untersuchen, was von dem Land hier noch zu retten ist. Es ist gewissermaßen eine heilige Mission geworden, die Gegend mit neuem, fruchtbaren Boden wiederzubeleben. Vielleicht finde ich ja hier in der Nähe eine Wasserquelle.\n\nIst Euch eigentlich aufgefallen, wie eigenartig der Übergang zwischen Feralas und Tausend Nadeln ist? Ganz seltsame Magie muss im Spiel gewesen sein, als das passiert ist.", completion = "Ah, ein Grimmlingflitzerei, und noch dazu eines, dessen Ausreifung bald vollendet sein wird, wenn ich mich nicht irre. Erstaunlich, dass Ihr eines gefunden habt, und noch dazu eines, das sich in einem so guten Zustand befindet. So etwas sieht man in Feralas nur noch selten heutzutage. Wie mir zu Ohren kam, sind etliche Wilderer hier in der Gegend gewesen, um diese Wesen aus den unterschiedlichsten Gründen zu fangen und zu töten. Ich verstehe das nicht... es sind so wunderschöne Geschöpfe, wenn sie ausgewachsen sind.\n\nWie seid Ihr nur an einen solchen Fund geraten?", rewards = "Ihr bekommt:\n\n"},
[3842] = {title = "Kurz vor dem Schlüpfen", objective = "Bringt 2 Elixiere der Seelenstärke zu Quentin in Tausend Nadeln.", description = "Die Moonweavers, wie? Überaus interessant. Schade, dass die Grimmlingflitzer nicht schätzen können, was es bedeutet, wenn diese beiden sich um sie kümmern. Beide sind überaus fähig und gut.\n\nSoso, sie haben Euch das Ei also geschenkt. Tja, dann solltet Ihr auch so lange dafür verantwortlich sein, wie Ihr dies wünscht. Das Junge scheint wohl schon bald zu schlüpfen, aber wir sollten trotzdem sichergehen, dass es gesund ist und keinen Schaden genommen hat.\n\nIch brauche lediglich zwei Elixiere der Seelenstärke für einen kleinen Zauber, der das Ei beschützen wird. Die übrigen Komponenten habe ich bereits hier.", progress = "Je länger ich hier bin, desto mehr überkommt mich die Lust, an diesen Rennen teilzunehmen, <Name>. Einfach überwältigend...\n\nHabt Ihr die Elixiere schon gefunden? Sobald ich sagen kann, ob das Ei gesund ist oder nicht, gebe ich es Euch zurück, damit Ihr es aufbewahrt, bis es schlüpft.\n\nSagt mir einfach Bescheid.", completion = "Großartig. Die sind perfekt. Gebt mir einen Augenblick, damit ich die Komponenten miteinander vermischen kann, und dann werden wir ja sehen, wie sich dieses Ei einmal machen wird.", rewards = "Ihr bekommt:\n\n"},
[3843] = {title = "Das neueste Mitglied der Familie", objective = "Bringt Euer empfindliches Grimmlingflitzerei ins Hinterland und sprecht mit Agnar Beastamer, aber beeilt Euch. Ihr habt nur eine Stunde Zeit, ihn zu finden. Dann stirbt das Jungtier in dem Ei.", description = "Ein prachtvolles Exemplar, <Name>. Wenn dieses Geschöpf das Heranreifen übersteht, dann wird es ein wahrhaft gesundes Tier sein!\n\nAber eines würde ich Euch noch vorschlagen, wenn Ihr es damit wirklich ernst meint - geht zum Aerie Peak im Hinterland. Sprecht dort mit einem Zwerg namens Agnar Beastamer. Er ist ein Tierführermeister und kann Euch bestimmt bei den letzten Stadien der Brutzeit behilflich sein.\n\nAber eilt Euch, <Name>, das Ei ist empfindlich und wird sich ohne die richtige Pflege nicht lange halten.", progress = "Seid gegrüßt, <Name>. Kann ich Euch mit irgendwas helfen?", completion = "Ja, was haben wir denn hier? So etwas hab ich ja schon seit Ewigkeiten nicht mehr gesehen! Feendrache, wenn ich mich nicht irre... und zwar ein Grimmlingflitzer, wie's aussieht. Ausgezeichnet, ganz ausgezeichnet.\n\nNa, wenn der kleine Kerl hier schlüpfen und mal ein starker und gesunder Flitzer werden soll, dann sollten wir ihm was zu essen beschaffen. Gut, dass Ihr's mir grad noch rechtzeitig gebracht habt.", rewards = "Ihr bekommt:\n\n"},
[3844] = {title = "Es ist für jeden ein Geheimnis", objective = "Sucht in dem Tümpel nach einem Hinweis darauf, wem dieses havarierte Floß gehören könnte.", description = "In Ufernähe liegt ein zerstörtes Floß. Das hier ist nur ein kleiner Tümpel, deswegen ist Euch nicht so ganz klar, wie das Floß hier landen konnte. Aber ein Blick auf die Bäume verrät Euch, dass der Wasserstand im Teich nicht unbedingt immer derselbe sein muss.\n\nVielleicht findet Ihr ja mehr heraus, wenn Ihr Euch ein bisschen in der Gegend umschaut ...", progress = nil, completion = "Am Grund des Tümpels liegt ein durchnässtes Bündel.", rewards = "Ihr bekommt:\n\n"},
[3845] = {title = "Es ist für jeden ein Geheimnis", objective = "Untersucht die Gegenstände in dem Bündel und bringt sie zu ihrem Besitzer.", description = "Ihr greift nach dem Bündel und zieht es an Land. Vielleicht findet Ihr heraus, wem es gehört, wenn Ihr die Gegenstände darin untersucht.\n\nIn Marshals Zuflucht halten sich ein paar vereinzelte Reisende auf. Vielleicht lässt sich dort ja mehr herausfinden.", progress = "Hallo, Ihr da! Euch hab ich doch schon mal gesehen... Oder nicht?", completion = "Oh... Ja, die Sachen kommen mir bekannt vor... irgendwie schon...", rewards = "Ihr bekommt:\n\n"},
[3861] = {title = "GLUCK!", objective = "Beschafft Euch etwas Spezial-Hühnerfutter und kehrt zu dem Huhn zurück, das sich mit Euch angefreundet hat. Wenn Ihr es gefunden habt, dann benutzt erst /cheer, ehe Ihr dem Huhn das Spezial-Hühnerfutter gebt.", description = "Gack... gack... gack... GAGGACK!\n\nGack... gack... gack.\n\nDas Huhn sieht zu Euch hinauf und beginnt dann, mit seinen Krallen am Boden zu scharren. Ihr glaubt, dass es ein Wort schreibt, aber Ihr seid Euch nicht sicher, was es ist. Könnte es das sein... S-A-L-D-E-A-N? Bevor Ihr fragen könnt, dreht sich das Huhn weg und kümmert sich um seine Angelegenheiten.", progress = "Das Huhn starrt Euch mit dunklen, kalten Augen an. Hungrig wartet es auf Euch.\n\n\"GAGGAAACK!\n\nGack... gack... gack.\"", completion = "GAGGACK!!!\n\nDas Huhn beginnt gierig, das Futter aufzupicken, das Ihr ihm hingestreut habt.\n\nNach einer kurzen Weile sieht es sich überrascht um. Dann trippelt es unruhig vor und zurück. Ob dieses Huhn vielleicht gleich ein Ei legt? Vielleicht solltet Ihr besser einmal darunter nachsehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHühner-Ei beschwören"},
[3881] = {title = "Rettungsexpedition", objective = "Bringt eine Kiste mit Nahrungsmitteln und Forscherausrüstung zu Williden Marshal im Un'Goro Krater.", description = "Ich weiß zwar nicht, wie Ihr es bis hierher geschafft habt, aber Ihr seid Balsam für meine Augen! Ich heiße Williden Marshal und bin der Leiter eines neutralen Expeditionstrupps. Unsere jüngste und größte Unternehmung wurde von zahllosen Katastrophen begleitet. Die schlimmste davon war, dass wir die Wildheit des Un'Goro Kraters unterschätzt hatten.\n\nAls wir aus unseren Stützpunkten im südwestlichen und nordöstlichen Teil des Kraters flohen, ließen wir lebenswichtige Vorräte zurück. Ihr seht aus, als wärt Ihr recht stark und geschickt ... Könnt Ihr uns vielleicht dabei helfen, sie zurückzubekommen?", progress = "Wenn wir auch nur die geringste Chance haben wollen, hier lebendig rauszukommen, dann brauchen wir unsere große Kiste mit Nahrungsmitteln. Und zumindest einen Teil unserer Forscherausrüstung zurückzubekommen, das wäre ein Segen in diesem Meer des Elends.", completion = "Ihr habt ja sogar beides wiederbeschafft: unsere Nahrungsmittel UND unsere Forscherausrüstung! Ihr habt nicht nur die Expedition gerettet, sondern auch unser aller Leben. Mein Team und ich können Euch gar nicht genug danken; Euretwegen können wir jetzt wenigstens eine Zeit lang weitermachen.\n\nWir haben zwar nicht viel, aber ich werde Euch bestimmt nicht auf dem Trockenen sitzen lassen als Dank für die unschätzbare Hilfe, die Ihr uns erwiesen habt! Danke, &lt;Name&gt;, Ihr habt jetzt einen Freund bei Marshals Expeditionen!", rewards = "Ihr bekommt:\n\n"},
[3882] = {title = "Knochenklappern", objective = "Bringt 8 Dinosaurierknochen zu Spark Nilminer im Un'Goro Krater.", description = "Man sollte meinen, dass ich gern grabe, nur weil ich der Oberbuddler von Marshals Expeditionen bin. Es könnte schlimmere Dinge in der Welt geben... auch wenn mir gerade keines einfällt.\n\nJedenfalls sollten wir eigentlich in der Terrorflucht - PHANTASTISCHER Name übrigens - nach toten Stegodons und Dimetrodons graben. Na ja, es treiben sich von der Sorte auch noch eine Menge lebende Viecher dort herum! Wil und Hol beschäftigen sich immer mit dieser Todesfalle, daher benötigen wir diese Dinosaurierknochen. Obwohl, unter uns gesagt, wenn Ihr mir welche von einem lebenden Exemplar bringt, dann ist das genauso gut.", progress = "Ihr könnt von mir denken, was Ihr wollt, aber denen ist es doch völlig egal, ob die Knochen, die sie zum Erforschen bekommen, von uralten Stegodons und Dimetrodons stammen oder von den Viechern, die uns beinahe zum Frühstück verspeist hätten, als wir gerade unser Lager aufschlugen. Ich wäre schon glücklich, wenn wir hier lebend rauskämen...", completion = "Wunderbar, das sollte funktionieren. Und jetzt, wenn Ihr erlaubt...\n\nDANKE, DASS IHR ALL DIESE KNOCHEN FÜR UNS AUSGEGRABEN HABT, OHNE DEN HIER LEBENDEN TIEREN SCHADEN ZUZUFÜGEN!\n\nOb das wirklich so war oder nicht, das will ich gar nicht wissen. Belassen wir es dabei, in Ordnung? Hier - vielleicht hilft Euch das, über die ganze Angelegenheit Euren Mund zu halten. Jedes Mittel ist recht, wenn wir nur lebendig hier rauskommen, sage ich!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSteinbruchstiefel des ArchäologenAusgräberwerkzeug-Gürtel\n\nIhr bekommt außerdem:\n\n"},
[3883] = {title = "Eine fremdartige Ökologie", objective = "Verwendet die Kratzphiole, um damit eine Schwarmbauwandprobe von einer der Schwarmbrutstätten der Gorishi im Un'Goro Krater zu holen. Sucht nach den Kammern mit der hängenden Larvenbrut.\n\nBringt die Schwarmbauwandprobe zu Hol'anyee Marshal im Un'Goro Krater.", description = "Nur weil wir einen Rückschlag erlitten haben, heißt das noch lange nicht, dass unsere Forschungen ein Ende finden müssen! Bevor wir hier gelandet sind, untersuchten wir die Schwarmbauten der Gorishiinsekten im südlichen Teil des Kraters. Sie sind fremdartig und passen nicht zur ursprünglichen Ökologie des Un'Goro und wir wollen herausfinden, warum das so ist.\n\nIn ihrem Schwarmbauverbund muss es Larvenbrutstätten geben. Ihr könnt diesen Ort an der hängenden Raupenbrut erkennen. Hier, nehmt mit dieser Phiole eine Probe von der Schwarmbauwand in der Nähe der Brutstätten. Bringt sie dann zu mir zurück, damit ich sie untersuchen kann, aber seid vorsichtig!", progress = "Habt Ihr die Probe des Gorishischwarmbaus, damit ich sie untersuchen kann, <Name>?", completion = "Ja, die ist prima. Ihr wart mir eine große Hilfe... Ich wünschte, ich könnte Euch mehr geben als das hier, aber wenn man mitten in einer primitiven Gegend festsitzt, dann schränkt einen das in seinen Möglichkeiten schon ein bisschen ein. Eines ist jedoch sicher: Die Forschungsarbeit, die hier geleistet wird, wäre ohne Eure Hilfe nicht möglich!", rewards = "Ihr bekommt:\n\n"},
[3884] = {title = "Willidens Tagebuch", objective = "Bringt das Tagebuch zu Williden Marshal zurück. Er befindet sich irgendwo im Un'Goro Krater.", description = "Ihr habt ein zerfleddertes Tagebuch zu Tage gefördert. Ein Teil davon ist noch lesbar; es scheint von einem gewissen Williden Marshal verfasst worden zu sein. Wenn das Tagebuch stimmt, dann muss Williden irgendwo im nördlichen Teil des Kraters zu finden sein. Dem Tagebuch zufolge haben er und seine Gefährten in den höheren Lagen des Kraters Schutz gesucht, nachdem ihre tiefer gelegenen Stützpunkte von den wilden Bestien überrannt wurden.", progress = "Hallo! Meine Begleiter und ich sind glücklich, endlich wieder andere lebende Wesen hier zu sehen und nicht nur diese übergroßen wilden Bestien! Was führt Euch in den Un'Goro Krater?", completion = "Na sieh mal einer an - mein Tagebuch! Ich hatte schon gedacht, es sei verloren, genauso wie fast alles andere, das wir zum Un'Goro mitgenommen hatten. Vielen herzlichen Dank, dass Ihr es mir zurückgebracht habt!", rewards = "Ihr bekommt:\n\n"},
[3901] = {title = "Klappernde Skelette", objective = "Tötet 12 klappernde Skelette und kehrt zu Schattenpriester Sarvis in Deathknell zurück, wenn Ihr fertig seid.", description = "Ihr habt den Verlassenen Euer Potenzial unter normalen Umständen gezeigt, <Name>. Jetzt wollen wir mal sehen, wie es damit bestellt ist, wenn Ihr unter Druck steht.\n\nDie klappernden Skelette, weitere hirnlose Diener des Lichkönigs, sind zähere Feinde als die Zombies, mit denen Ihr es bisher zu tun hattet. Auch hier heißt es wieder: Dünnt ihre Reihen aus und beweist den Verlassenen, dass Ihr der Aufgabe gewachsen seid. Frisch ans Werk ... und redet wieder mit mir, wenn Ihr fertig seid.", progress = nil, completion = "Ich bin fertig mit Euch, &lt;Name&gt;. Ihr habt bewiesen, dass Ihr der Freiheit, die Euch gegeben wurde, würdig seid. Viele werden Euch verachten für das, was aus Euch geworden ist. Doch wisset, was auch immer sie versuchen uns anzutun, wir sind frei und werden uns nicht wieder fesseln lassen.\n\nNehmt dies und macht Euch auf den Weg. Es liegt viel Arbeit vor Euch, &lt;Klasse&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFlachsstiefelAasfresser-TunikaStreifer-Gamaschen\n\nIhr bekommt außerdem:\n\n"},
[3902] = {title = "Beutesuche in Deathknell", objective = "Durchsucht Deathknell und Umgebung nach 6 Stücken aufgestöberter Ware und bringt sie zu Todeswache Saltain zurück.", description = "Ihr da! Wenn Ihr Euch irgendwie nützlich machen wollt, dann hört zu!\n\nWir benötigen frisch erweckte Rekruten, die sich nach Deathknell begeben und dort nach allem suchen, was wir irgendwie gebrauchen können. Die Dinge werden sich höchstwahrscheinlich in gestapelten Kästen befinden. Wir rechnen damit, dass sich in Kürze weitere Rekruten erheben werden, und wenn wir nicht wollen, dass die nackt herumtappen, dann müssen wir wohl oder übel was für sie suchen.\n\nAlso, macht Euch an die Arbeit, elendes Knochengestell! Und ohne ein bisschen Eile gibt es auch keine Belohnung.", progress = "Habt Ihr ein paar nützliche Gegenstände für uns aufstöbern können? Es ist keine Schande, das wieder zu verwenden, was von anderen fortgeworfen wurde. Niemand wird uns irgendwelche Almosen geben - wir Verlassenen werden für uns selbst sorgen!", completion = "Gute Arbeit, &lt;Name&gt;, ich wusste, dass Ihr nicht völlig nutzlos seid. Hier, nehmt Euch einen der besseren Gegenstände, die ich aus dem herausgefischt habe, was bisher bereits gesammelt wurde.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFlachs-GürtelRostmetallarmschienenKurzes Nachtsaugercape\n\nIhr bekommt außerdem:\n\n"},
[3903] = {title = "Milly Osworth", objective = "Sprecht mit Milly Osworth.", description = "Ihr habt Euch als verlässlich erwiesen, <Name>. Verlässlich und ohne Angst, Euch auch mal die Hände schmutzig zu machen, wie?\n\nTja, eine Freundin von mir, Milly Osworth, hat ein paar Probleme. Sie ist mit ihrem Wagen auf der anderen Seite der Abtei, in der Nähe des Stalls. Ich bin mir sicher, sie könnte Eure Hilfe gut gebrauchen.", progress = nil, completion = "Ach, Deputy Willem hat Euch also gesagt, Ihr sollt mit mir reden, ja? Er ist ein tapferer Kerl und immer bereit, mir zu helfen, aber seine Pflichten halten ihn in der Abtei von Nordhain fest und ich fürchte, das Problem, das ich heute habe, ist etwas zu groß für ihn.\n\nVielleicht könnt Ihr mir helfen?", rewards = "Ihr bekommt:\n\n"},
[3904] = {title = "Millys Ernte", objective = "Bringt 8 Kisten mit Millys Ernte zu Milly Osworth in der Nähe der Abtei von Nordhain.", description = "Eine Bande von Briganten, die Defias, sind in die Weinberge von Nordhain eingedrungen, als ich gerade bei der Weinlese war! Ich habe es den Wachen von Nordhain gemeldet und sie haben mir auch versprochen, dass sie sich darum kümmern würden, aber... Ich habe Angst um meine Traubenernte! Selbst wenn die Defias sie nicht stehlen, befürchte ich, dass unsere Wachen beim Vertreiben der Rohlinge alles zertrampeln.\n\nBitte, Ihr müsst mir helfen! Die meisten Trauben sind schon in Eimern gesammelt, aber ich habe sie in den Weinbergen im Südosten zurückgelassen.\n\nBringt mir diese Kisten! Rettet meine Ernte!", progress = "Habt Ihr meine Ernte, <Name>?", completion = "Oh, danke, &lt;Name&gt;! Ihr habt meine Ernte gerettet! Und ich hoffe, Ihr habt einigen von diesen Defias gezeigt, dass sie hier nicht so einfach Ärger machen können.\n\nWir sind zur Zeit zwar knapp an Wachen, aber glücklicherweise haben wir Helden wie Euch, die uns beschützen!", rewards = "Ihr bekommt:\n\n"},
[3905] = {title = "Traubenliste", objective = "Bringt die Traubenliste zu Bruder Neals in der Abtei von Nordhain.", description = "Jetzt, wo meine Ernte in Sicherheit ist, bringt diese Traubenliste zu Bruder Neals. Er ist verantwortlich für die Essens- und Getränkevorräte von Nordhain und ich bin mir sicher, er wird hoch erfreut sein zu hören, dass er frische Trauben bekommt.\n\nIhr findet Bruder Neals im Glockenturm der Abtei... wo er gern seinen Wein probiert.", progress = "Ihr seht so frohgemut aus! Kommt! Setzt Euch und trinkt etwas!", completion = "Dann zeigt mal her...\n\nMeine Güte! Millys Trauben sind gerettet! Als sie mir erzählte, dass Briganten ihren Weinberg überfallen haben, wäre ich fast verzweifelt, doch ich habe den Glauben an das Licht nicht verloren!\n\nUnd dank Eures Heldenmutes haben wir jetzt Trauben, um neuen Wein herstellen zu können! Möge das Licht Euch segnen und über Euch wachen, &lt;Name&gt;!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWeinbefleckter UmhangAnhäng-Gürtel\n\nIhr bekommt außerdem:\n\n"},
[3906] = {title = "Disharmonie der Flamme", objective = "Reist zum Steinbruch am Blackrock und tötet Übermeister Pyron. Kehrt zu Thunderheart zurück, sobald Ihr den Auftrag erledigt habt.", description = "Die Ältesten haben eine Störung der Elemente gespürt. Die Dunkeleisenzwerge haben einen üblen Geist in unsere Welt beschworen, durch den unser Land von einer ewigen Dürre heimgesucht werden könnte. Die Disharmonie der Flamme muss untersucht werden.\n\nBegebt Euch zum Blackrock und dann durch die Flammenschlucht in den Steinbruch. Dort werdet Ihr diesen Herrn des Feuers finden: Übermeister Pyron.\n\nMacht der Störung ein Ende und kehrt dann zu mir zurück.", progress = "Die Elemente befinden sich noch immer in einem Zustand der Unordnung, <Name>.", completion = "Das kann nicht sein... es darf nicht sein. Die Vernichtung Pyrons hat lediglich einen Schleier gelüftet. In den Tiefen von Blackrock befindet sich eine noch weit heimtückischere Quelle der Verderbnis.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3907] = {title = "Disharmonie des Feuers", objective = "Betretet die Blackrocktiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Thunderheart.", description = "Ich kann die Verderbtheit in der Luft, die Euch umgibt, riechen, <Name>. Es gibt einen anderen, versteckt in den Tiefen von Blackrock, der diese Verderbtheit kontrolliert.\n\nDer Wind und die Erde schreien seinen Namen hinaus: Lord Incendius. Doch irgendjemand ... irgendetwas ... gebietet über dieses Wesen. Er ist nichts weiter als ein Abgesandter.\n\nSucht ihn und findet heraus, wo sich sein Meister versteckt hält. Kehrt zu mir zurück, sobald Ihr diese Information gesammelt habt.", progress = "Bald schon werden die Flammen dieses Land überwältigen. Sputet Euch, <Name>!", completion = "&lt;Thunderheart umklammert die Schrifttafel von Kurniya.&gt;\n\nRagnaros... hier...\n\nDie Ältesten hatten Recht, die vom Blackrock ausgehende Verderbnis zu fürchten. Ein General der Alten Götter! IN UNSERER WELT! Wir müssen unsere Position hier in Kargath völlig neu überdenken. Wir müssen entscheiden, ob wir bleiben und kämpfen oder ob wir aus Furcht vor einer neuen Teilung flüchten.\n\nHütet Euch vor jeder weiteren Erforschung des Blackrocks, &lt;Name&gt;. Ein Übel, das viel größer ist als alles, was in dieser Welt existiert, haust dort unten in den feurigen Tiefen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSonnentuchcapeNachtlauerhandschuheGruftdämonen-ArmschienenWackere Umklammerung\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[3908] = {title = "Es ist für jeden ein Geheimnis", objective = "Bringt Linkens Schwert zu Donova Snowden in Winterspring.", description = "Seht, ich habe keine Ahnung, wie ich hierher kam. Niemand weiß das - niemand versteht es! Ich kann mich einfach an nichts erinnern...\n\nAber diese Gegenstände, die Ihr mir gebracht habt... Ich erinnere mich an etwas.\n\nMein Schwert. Ich soll es irgendwie stärken, aber ich weiß beim besten Willen nicht, warum. Es tut mir Leid, dass ich Euch nicht mehr sagen kann, aber ich kann mich einfach nicht erinnern!\n\nNa, egal, ich weiß aber, wo Ihr es hinbringen könnt: zu Donova Snowden in Winterspring. Ihr findet sie bei den Thermalquellen. Sie kann das Schwert an den Teichen dort aushärten.", progress = "Sieh an... Hat Linken mir also doch endlich sein Schwert geschickt.", completion = "Aber natürlich kann ich dieses Schwert aushärten. Und während ich arbeite, könnt Ihr mir erklären, warum Linken so lange gebraucht hat, um mir das Schwert zukommen zu lassen. Normalerweise ist er nicht so vergesslich...", rewards = "Ihr bekommt:\n\n"},
[3909] = {title = "Das Videre-Elixier", objective = "Sucht nach Gregan Brewspewer im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Snowden nach Winterspring zurück.", description = "Was sagt Ihr da? Linken... HAT ES VERGESSEN?\n\nAh, verstehe... Hat sein Gedächtnis verloren...\n\nNa gut, hier ist sein Schwert. Es ist aber noch nicht fertig. Ich habe von jemandem gehört, der es fertig stellen kann, aber... tja, es könnte etwas schwierig werden, mit ihm zu reden.\n\nHört mal, ich weiß jemanden, der Euch bestimmt helfen kann. Ich kann Euch jetzt nicht alles erklären, das würde zu lange dauern, aber Ihr müsst Euch irgendwie ein Videre-Elixier beschaffen. Der Einzige, von dem ich weiß, dass er Euch dabei helfen kann, ist Gregan Brewspewer. Er ist ziemlich schwer aufzuspüren, aber zuletzt hatte er ein Lager in der Wildnis von Feralas.", progress = "Schon zurück?", completion = "Eine Phiole davon brauche ich, um sicherzugehen, dass es wirklich das richtige Elixier ist... Ja... Genau das wollte ich.", rewards = "Ihr bekommt:\n\n"},
[3911] = {title = "Das letzte Element", objective = "Begebt Euch in die Schwarzfelstiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hin gemurmelt hat.", description = "Es gibt Arbeit für diejenigen, die sich in die Tiefen wagen, <Name>.\n\nDen Dunkeleisenzwergen ist es gelungen, extrem mächtige Golems zu erschaffen.\n\nErsten Berichten unserer Spione zufolge verwenden die Zwerge eine einzigartige Kraftquelle, die ihren Schöpfungen eine unvergleichliche Kraft zum Töten gibt.\n\nStellt Euch nur einmal vor, was wir mit unseren Monstrositäten tun könnten, wenn wir diese Essenz der Elemente in die Hände bekommen könnten! Stellt die ganze Stadt auf den Kopf, wenn es sein muss, aber kommt nicht wieder, ehe Ihr nicht die Essenz gefunden habt! Die Bezahlung ist es wert, das Risiko einzugehen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nLagraves Siegel"},
[3912] = {title = "Treffen am Grab", objective = "Geht zum Friedhof außerhalb von Gadgetzan und benutzt dort das Videre-Elixier. Befolgt Donovas übrige Anweisungen, um Gaeriyan zu finden.\n\nBereitgestellter Gegenstand: \n", description = "Durch dieses Elixier könnt Ihr mit jemandem sprechen, den Ihr normalerweise nicht einmal sehen würdet...\n\nBringt das Videre-Elixier und Linkens Schwert mit zum Friedhof kurz vor Gadgetzan in Tanaris. Wenn Ihr dort seid, nehmt den Trank zu Euch. Ihr werdet möglicherweise von der Wirkung sehr überrascht sein, aber erschreckt nicht.\n\nGeht in Eurer 'anderen Form' nach Norden, bis Ihr die Berge erreicht. Dort findet Ihr den, mit dem Ihr sprechen müsst, in einer der Felsspalten. Sein Name ist Gaeriyan.\n\nAber vergesst nicht: Nur in dieser Form wird er mit Euch sprechen...", progress = nil, completion = "Es ist lange her, dass jemand gekommen ist, um mit mir zu sprechen...", rewards = "Ihr bekommt:\n\n"},
[3913] = {title = "Grabesstille", objective = "Wenn Ihr auferstanden seid, sucht nach dem Grabstein, von dem Gaeriyan Euch erzählt hat.", description = "Wenn Ihr zum Friedhof zurückkehrt, <Name>, findet Ihr dort einen Grabstein... Nicht einfach nur irgendeinen Grabstein... Dieser hebt sich von all den anderen ab. Geheimnisse liegen darin verborgen.\n\nDrückt gegen den Stein, dann erfahrt Ihr von diesen Geheimnissen...", progress = "Das muss der Grabstein sein, von dem Gaeriyan sprach...", completion = "Ihr drückt fest gegen den Stein und er rutscht zur Seite. Darunter wird eine kleine Vertiefung sichtbar.\n\nAls Ihr Linkens Schwert in die Vertiefung legt, stellt Ihr fest, dass es haargenau hineinpasst...", rewards = "Ihr bekommt:\n\n"},
[3914] = {title = "Linkens Schwert", objective = "Liefert Linkens überragendes Schwert bei Linken im Un'Goro Krater ab.", description = "Ein greller Lichtblitz blendet Euch, dann könnt Ihr das Schwert wieder aufheben. Es hat sich verwandelt!", progress = "Oh! An Euch erinnere ich mich! Ihr seid... Nein, sagt es mir nicht!", completion = "Mein Schwert... Es ist vollendet!\n\nWenn ich mich jetzt doch nur noch daran erinnern könnte, warum ich es brauche...\n\nHier, lasst mich Euch wenigstens für Eure Arbeit bezahlen.", rewards = "Ihr bekommt:\n\n"},
[3921] = {title = "Wenikee Boltbucket", objective = "Bringt das zerbrochene Samophlang zu Wenikee Boltbucket.", description = "Ich glaube, ich habe das Samophlang zerbrochen. Das ist schlecht, denn ich habe schon einigen Kollegen aus Undermine davon erzählt, und die waren äußerst fasziniert. Wir müssen einen Weg finden, es zu reparieren!\n\nBringt das zerbrochene Samophlang zu Wenikee Boltbucket beim Außenposten der Horde, zwischen dem Brachland und Ashenvale. Sie ist sehr schlau und wissbegierig. Wenn Ihr ihr das Samophlang zeigt, dann, wette ich, stürzt sie sich sofort darauf und will es reparieren.", progress = "Ich bin gerade sehr beschäftigt, <Klasse>. Wenn Ihr also nichts für mich habt, dann solltet Ihr am besten einfach wieder gehen...", completion = "Oh, was haben wir denn hier? Ein Samophlang, sagt Ihr? Was ist ein Samophlang?\n\nAh, jetzt schaut doch nur, es bewegt sich, wenn man es anfasst. Und im Inneren ist das Geräusch eines komplizierten Getriebes. Oh Mann! Ich will das Ding unbedingt reparieren und sehen, was es tut, Ihr nicht?", rewards = "Ihr bekommt:\n\n"},
[3922] = {title = "Nugget-Patronen", objective = "Bringt 15 Nugget-Patronen zu Wenikee Boltbucket im Brachland.", description = "Ich möchte das Samophlang reparieren, aber dazu brauche ich ein paar Dinge. Ich habe keine 17,5er Nugget-Patronen mehr, und davon werde ich für meine Arbeit hier eine ganze Menge brauchen.\n\nDer nächstgelegene Ort, an dem man sie bekommen kann, ist das Schlickermoor im Osten. Die Leute von der Venture Company bewahren sie normalerweise in ihren Werkzeugkisten auf. Geht ins Schlickermoor und schaut in den Werkzeugkisten nach, die Ihr dort findet. Kommt zu mir zurück, sobald Ihr genug Nugget-Patronen gesammelt habt.", progress = "Habt Ihr die Nugget-Patronen, <Name>? Ständig muss ich mir dieses Samophlang ansehen - ich kann es gar nicht erwarten, endlich daran herumzubasteln.", completion = "Prima, Ihr habt sie! Jetzt kann ich mich endlich an die Arbeit machen...", rewards = "Ihr bekommt:\n\n"},
[3923] = {title = "Rilli Greasygob", objective = "Bringt das zerbrochene Samophlang nach Orgrimmar zu Rilli Greasygob.", description = "Tja, das hat schon mal nicht funktioniert. Ich habe an dem Samophlang ein paar zusätzliche Messgeräte angebracht, um seine strukturelle Integrität zu messen, und laut der Anzeige war die Integrität am absoluten Tiefpunkt. Ich könnte natürlich noch ein paar Skalen und vielleicht auch den einen oder anderen Hebel anbringen, aber ... ich glaube, das würde alles nur noch schlimmer machen.\n\nIhr solltet das Samophlang zu Rilli Greasygob bringen. Er hat mal für die Venture Company gearbeitet. Wenn irgendjemand weiß, wie man das Ding reparieren kann, dann Rilli.\n\nIhr findet ihn bei 'Noggs Meistermaschinen' in Orgrimmar, im Tal der Ehre.", progress = "Passt auf Euren Kopf auf! Ich will nicht, dass er meiner Arbeit in die Quere kommt!", completion = "Was ist denn das? Aber das ist doch ein Samophlang! Wo habt Ihr das denn her? Habt Ihr etwa in der Anlage der Venture Company im Brachland herumgeschnüffelt?\n\nDann seid Ihr entweder sehr mutig oder sehr dumm.", rewards = "Ihr bekommt:\n\n"},
[3924] = {title = "Samophlang-Handbuch", objective = "Bringt das Samophlang-Handbuch nach Orgrimmar zu Rilli Greasygob.", description = "Ich glaube, ich kann das Samophlang reparieren, aber dazu brauche ich erst einmal das Handbuch. Als ich noch für die Venture Company arbeitete, hatte ich einen Konkurrenten, Boss Copperplug. Der hat das Geheimnis des Samophlangs gehütet wie seinen Augapfel und immer nur kleine Fitzelchen an Informationen an diejenigen verteilt, denen er traute. Zu dieser kleinen, ausgewählten Gruppe habe ich leider nicht gehört...\n\nBoss Copperplug war früher immer in der Felsadermine im Nordosten des Brachlandes. Beschafft Euch das Handbuch von ihm, und falls er irgendjemandem einzelne Seiten davon gegeben hat, dann müsst Ihr diese ebenfalls einsammeln.", progress = "Habt Ihr das Handbuch?", completion = "Ihr habt das Handbuch! Ich kann es kaum erwarten, es zu lesen und herauszufinden, wie man das Samophlang reparieren kann! Ich habe mit Sputtervale in Ratchet gesprochen - er möchte Euch für Eure Hilfe danken und Euch für Eure Mühe belohnen.\n\nIch möchte Euch ebenfalls danken - und falls es mir gelingt, dieses Ding hier jemals zu reparieren, lasse ich es Euch wissen ...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDrehmomentschlüsselSamophlang-Schraubendreher\n\nIhr bekommt außerdem:\n\n"},
[3941] = {title = "Die Hilfe des Gnoms", objective = "Sucht J.D. Collie in der Höhle in Marshals Zuflucht auf.", description = "Ich denke... Ich denke... Ich weiß, dass ich aus irgendeinem wichtigen Grund hergekommen bin...\n\nIch hab da eine Idee, <Name>. In der Höhle dort drüben wohnt eine Gnomin namens J.D. Sie war sehr freundlich zu mir, als ich hier ankam. Vielleicht habe ich in meiner Verwirrung ihr gegenüber irgendwas erwähnt.\n\nWarum fragt Ihr sie nicht, ob sie etwas weiß? Oh, aber seid vorsichtig: Sie spielt immer mit diesen verrückten, leuchtenden Kristallen herum, die ich im Krater gesehen habe. Ich habe keine Ahnung, was sie da drinnen treibt.", progress = nil, completion = "Bleibt mal einen Moment da, wo Ihr seid... Ich probiere gerade eine neue Kristallkombination aus...", rewards = "Ihr bekommt:\n\n"},
[3942] = {title = "Linkens Andenken", objective = "Sucht Eridan Bluewind im südlichen Teil des Teufelswalds.", description = "Oh... Linken? Jaaa, der ist echt witzig. Als er hier ankam, murmelte er ständig irgendwelche seltsamen Dinge. Hat wahrscheinlich einen ziemlich heftigen Schlag auf den Kopf bekommen, würde ich mal sagen.\n\nAber etwas, das er gesagt hat, ist bei mir irgendwie hängen geblieben - dass er dabei war, eine Art Totem herzustellen; er sagte, er müsse mit jemandem namens Eridan Bluewind sprechen... an einem Ort namens Teufelswald, glaube ich.\n\nAber ich bezweifle, dass Linken Euch jetzt noch viel darüber sagen kann. Wenn Ihr mehr wissen wollt, solltet Ihr diesen Eridan vielleicht selbst suchen gehen...", progress = nil, completion = "Hallo, &lt;Klasse&gt;. Kann ich Euch irgendwie helfen?", rewards = "Ihr bekommt:\n\n"},
[3961] = {title = "Linkens Abenteuer", objective = "Bringt das Silbertotem von Aquementas zu Linken in Marshals Zuflucht.", description = "Wenn man sich überlegt, dass Linken nur hergekommen ist, um uns von Sturmflamme zu befreien... Er scheint so gar nichts Außergewöhnliches an sich zu haben, aber mir ist aufgefallen, dass er sich überhaupt nicht für meine Experimente oder Geräte interessiert hat, wie das bei den meisten Gnomen sonst der Fall ist. Er muss im Herzen ein echter Krieger sein.\n\nBringt ihm das Totem. Vielleicht hilft ihm das, sich zu erinnern, warum er hergekommen ist.", progress = "Ach, hallo, <Name>!", completion = "Konnte J. D. Euch helfen?", rewards = "Ihr bekommt:\n\n"},
[3962] = {title = "Allein ist es gefährlich", objective = "Begebt Euch zum Feuerfedergrat südlich von Marshals Zuflucht.\n\nSucht Sturmflamme und verwendet das Totem, um die schützende Aura, die ihn umgibt, zu entfernen. Sobald er besiegt ist, holt die Goldene Flamme aus der Höhle.", description = "<Name>, ich fange endlich an, mich zu erinnern! Ich bin hergekommen, um gegen Sturmflamme zu kämpfen. Ich war auf einer Reise und das hätte der letzte Schritt sein sollen.\n\nAber ich bin kein Held mehr... sondern Ihr. Alles, was Ihr getan habt... Ihr müsst dies jetzt zu Ende bringen, nicht ich.\n\nFindet Sturmflamme und besiegt ihn. Er bewacht ein Artefakt, das die Goldene Flamme genannt wird. Es verleiht mehr Macht als alles, was ich je zuvor gesehen habe, und in den Händen von jemandem, dessen Herz böse ist, ist es äußerst gefährlich.\n\nIhr solltet aber unbedingt Verstärkung mitnehmen - es ist gefährlich, allein zu gehen.", progress = "Hinter der Aura, die er mit Hilfe der Goldenen Flamme um sich herum erzeugt hat, ist Sturmflamme fast unbesiegbar. Nur Ihr habt die Macht, diese Aura mit dem Silbertotem von Aquementas zu entfernen.", completion = "Ich danke Euch, &lt;Name&gt;.\n\nDie Goldene Flamme wird jetzt in meine Heimat zurückgebracht, wo sie beschützt werden wird, damit sie niemals wieder für das Böse eingesetzt werden kann.\n\nDa Ihr so viel für mich getan habt, möchte ich, dass Ihr dies nehmt... Sucht Euch aus, was immer Ihr wollt. Ohne Euch wüsste ich noch immer nicht, wer ich eigentlich bin!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLinkens MeisterschwertGeist von Aquementas\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\nLinkens Bumerang"},
[3981] = {title = "Kommandant Gor'shak", objective = "Sucht Kommandant Gor'shak in den Blackrocktiefen.\n\nIhr erinnert Euch, dass auf dem primitiv gezeichneten Bild des Orcs auch Gitter vor dem Gesicht zu sehen waren. Vielleicht solltet Ihr nach einer Art Gefängnis suchen.", description = "Der arme Gargal... er wurde davon völlig überrascht. BUMM! Der tödliche Pfeil traf ihn genau oben an seinem Kopf. Er war vorher schon kein Genie, aber jetzt...\n\n<Galamav zieht eine Grimasse.>\n\nAls wir den Pfeil herauszogen, sahen wir, dass eine zusammengerollte Notiz an seinem Schaft befestigt war. Die Notiz war ein primitiv gezeichnetes Bild eines Orcs hinter Gittern mit der Unterschrift von Commander Gor'shak.\n\nFalls er noch am Leben sein sollte, dort unten in den Tiefen, dann müsst Ihr ihn finden.\n\nEine Falle, sagt Ihr? Ach nee, Dumpfhuf! Deswegen geht ja auch Ihr und nicht wir!", progress = nil, completion = "Wir haben nicht viel Zeit. Hört gut zu, &lt;Volk&gt;. Was ich Euch zu sagen habe, ist vertraulich und nur für Eure Ohren bestimmt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[3982] = {title = "Was ist los?", objective = "Verteidigt Gor'shak.", description = "Ich wurde unter der Schirmherrschaft von Thrall hierher geschickt. Glaubt Ihr wirklich, diese Clowns könnten mich fangen? Ich habe mich fangen lassen, um so Informationen sammeln zu können.\n\n<Gor'shak flüstert.>\n\nDie Prinzessin von Ironforge wurde von Imperator Thaurissan entführt. Prinzessin Bronzebeard befindet sich in dieser Stadt! Ich wette, dem alten Magni ist fast das Herz stehen geblieben, als er diese Neuigkeiten gehört hat.\n\n<Gor'shak lacht.>\n\nPssst! Hört Ihr das? Es kommen Wachen! VERTEIDIGT EUCH!", progress = "Verteidigt Euch, Dummkopf!", completion = "Das war knapp. Sie wissen jetzt, dass Ihr hier seid... bestimmt kommen bald mehr von ihnen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4001] = {title = "Was ist los?", objective = "Sprecht mit Kharan Mighthammer und sammelt Informationen über die Entführung von Prinzessin Moira Bronzebeard. Bringt diese Informationen dann zu Thrall nach Orgrimmar.\n\nIhr erinnert Euch, dass Gor'shak gesagt hat, Kharan werde in einer Zelle in seiner Nähe festgehalten.", description = "Bisher war meine Kommunikation mit dem Zwerg Kharan in der Zelle auf der anderen Seite der Halle nur sehr eingeschränkt möglich. Doch ich konnte ihn immerhin davon überzeugen, dass ich - oder besser - dass wir ihm nichts Böses wollen.\n\nGeht und redet mit ihm und erfahrt so viel über die Prinzessin und ihre Entführer wie nur möglich. Bringt diese Informationen dann dem Kriegshäuptling.\n\nThrall will nicht, dass der Prinzessin ein Leid geschieht. Er hat irgendeinen großen Plan, und der umfasst auch, dass sie wieder sicher nach Ironforge zurückgebracht wird. Kharan weiß das alles schon ... Geht!", progress = "Was führt Euch auf diesen geheiligten Boden?", completion = "Dies ist eine Chance für die Horde, das politische Klima in unserer vom Krieg zerrissenen Welt für immer zu verändern. Hört gut zu, &lt;Name&gt;.\n\nEinen Fehlschlag dieser Mission werde ich nicht akzeptieren.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4002] = {title = "Das östliche Königreich", objective = "Sprecht mit Thrall, wenn Ihr bereit seid, die von ihm geplante Mission zu übernehmen.", description = "Ihr bringt ganz ausgezeichnete Nachrichten, <Name>.\n\nAls Kriegshäuptling ist es meine Aufgabe, das zu tun, was das Beste für die Horde ist. Zu garantieren, dass die nachfolgenden Generationen nicht in einer hoffnungslosen Existenz gefangen sein werden.\n\nJetzt ist uns die einzigartige Chance, die Allianzen der Zukunft zu formen, in den Schoß gefallen. Wenn wir jetzt den Zwergen helfen, könnte dies unsere Beziehungen zum östlichen Königreich enorm verbessern. Und aus genau diesem Grund dürft Ihr nicht versagen!\n\nSeid Ihr bereit?", progress = nil, completion = "Jetzt könnt Ihr nicht mehr zurück, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4003] = {title = "Die königliche Rettung", objective = "Tötet Imperator Dagran Thaurissan und befreit Prinzessin Moira Bronzebeard von seinem bösen Zauber.", description = "Der Schlag gegen die Dunkeleisenzwerge wird, wenn er denn erfolgreich verläuft, eine Schockwelle durch ihr ganzes Königreich jagen.\n\nPrinzessin Bronzebeard ist unter der Kontrolle von Imperator Thaurissan. Um sie zu befreien, müsst Ihr den Imperator töten. Doch seid gewarnt, denn Eure Aufgabe ist doppelt gefährlich. Zweifellos wird Euch Prinzessin Bronzebeard angreifen, solange sie noch der Kontrolle des Imperators unterliegt.\n\nIHR DÜRFT IHR KEIN LEID ZUFÜGEN!", progress = nil, completion = "Was habt Ihr getan!!!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4004] = {title = "Ist die Prinzessin gerettet?", objective = "Kehrt zu Thrall zurück!", description = "Ihr habt meinen Ehemann erschlagen, <Volk>! Mein Kind wird ohne Vater in diese Welt geboren werden.\n\n<Prinzessin Moira zeigt direkt auf Euch.>\n\nIch versichere Euch, dieses Kind wird der nächste Herrscher des Königreichs von Ironforge sein. Ihr und Eure Art solltet für diese ungerechte Tat bis ans Ende aller Tage gejagt werden.\n\n<Ihr denkt, dass Prinzessin Moira vielleicht unter den Nachwirkungen von Thaurissans Zauber leidet.>\n\nLasst mich in Ruhe, <Volk>. Ich bin sicher, Euer Kriegshäuptling ist erpicht darauf, vom Ergebnis seiner Einmischung zu erfahren.", progress = nil, completion = "&lt;Thrall ist bestürzt über die Informationen, die Ihr ihm präsentiert habt.&gt;\n\nJetzt dräut eine neue Bedrohung am Horizont. Da Magnis Jahre sich dem Ende neigen, wird der Weg für diesen ungeborenen Dunkeleisenzwerg geöffnet, um Herrscher von Ironforge zu werden.\n\nIhr habt erreicht, worum ich Euch gebeten habe, und dafür sollt Ihr belohnt werden.\n\nVerlasst mich nun, &lt;Name&gt;. Ich muss mich mit Sylvanas und Cairne beraten.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nThralls EntschlossenheitAuge von Orgrimmar\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[4005] = {title = "Aquementas", objective = "Bringt das Buch von Aquor, die silbrigen Klauen und das Eisenstammherz nach Tanaris.\n\nBenutzt das Buch von Aquor, um Aquementas zu beschwören.\n\nWenn Ihr das vollständige Totem habt, bringt es zu J.D. Collie in Marshals Zuflucht zurück.", description = "Nehmt diese Tasche mit Vorräten mit Euch nach Tanaris. Begebt Euch zur Lost Rigger-Bucht und sucht dort einen Kreis aus Steinen.\n\nIn der östlichsten Halbinsel liegt das Geheimnis...\n\nLest aus dem Buch von Aquor vor - aber nur innerhalb dieses Kreises - und beschwört das einzige Wesen, das die Gegenstände, die Ihr gesammelt habt, in ein Totem verwandeln kann, mit dem Ihr Sturmflamme bekämpfen könnt.\n\nEs wird Aquementas nicht gefallen, dass Ihr ihn aufweckt, doch vergesst nicht: Ihr müsst unbedingt in dem Kreis bleiben, damit er die Gegenstände transformieren kann.", progress = "Ihr seid also zurück, wie? Hmmm... Lasst mich das mal sehen, <Name>.", completion = "Sturmflamme, sagt Ihr...\n\nJa, ich weiß, dass sich ein starker Elementar im verkohlten Zentrum des Kraters aufhält. Wir halten uns einfach alle davon fern, denn noch niemand war in der Lage, die mächtige Aura zu durchdringen, die ihn umgibt. Viele schon wurden von den felsigen Pfaden auf den Grund des Kraters hinabgestürzt, als sie versuchten, sich ihm zu stellen.", rewards = "Ihr bekommt:\n\n"},
[4021] = {title = "Gegenangriff!", objective = "Bringt ein Teil von Krom'zars Flagge zu Regthar Deathgate, westlich von Crossroads.", description = "Die Horde lobt Euch für Eure Erfolge gegen die Kolkar, doch die Kolkar kochen vor Wut. Ich habe Berichte erhalten, denen zufolge ein Kontingent Kolkar ihr Zuhause in Desolace verlassen hat und ins Brachland gezogen ist, um dort Rache zu üben. Den letzten Berichten nach, rücken Sie in diesem Moment von Westen her gegen diese Bunker vor!\n\nStellt Euch den Eindringlingen der Kolkar und bereitet der Bedrohung, die sie für das Brachland darstellen, ein Ende. Tötet sie, bis ihr Anführer, Kriegsherr Krom'zar, erscheint. Besiegt ihn und bringt mir ein Teil seiner Flagge als Beweis.\n\nWir zählen auf Euch, <Name>.", progress = "Habt Ihr die Flagge?", completion = "Ihr habt es geschafft! Ihr habt die Kolkar besiegt!\n\nIch werde dafür sorgen, dass Thrall von Euren Taten hier erfährt, &lt;Name&gt;.\n\nSchreitet erhobenen Hauptes dahin. Ihr und die Horde könnt stolz auf Euch sein.", rewards = "Ihr bekommt:\n\n"},
[4022] = {title = "Eine Kostprobe der Flamme", objective = "Zeigt Cyrus Therepentous die abgestreifte Haut des schwarzen Drachenschwarms, die Ihr von Velarok Windblade erhalten habt.", description = "Der Klan ist sich Eurer Arbeit in der sengenden Schlucht bewusst.\n\nZeigt sie mir, <Volk>. Die abgestreifte Drachenhaut, Schwachkopf!", progress = "<Cyrus' Augen beginnen zu glühen.>", completion = "&lt;Cyrus untersucht die Drachenhaut.&gt;\n\nDamit beweist Ihr, dass Ihr nicht völlig nutzlos seid, sterbliches Wesen.", rewards = "Ihr bekommt:\n\n"},
[4023] = {title = "Eine Kostprobe der Flamme", objective = "Zeigt Cyrus Therepentous einen Beweis für Eure Nützlichkeit.\n\nIhr habt so ein Gefühl, dass Cyrus bereits weiß, dass Ihr unwürdig seid.", description = "Ihr sucht nach dem Klan? Zeigt mir einen Beweis für Eure Nützlichkeit, sterbliches Wesen.", progress = "<Cyrus' Augen beginnen zu glühen.>", completion = "&lt;Cyrus untersucht die Drachenhaut.&gt;\n\nDamit beweist Ihr, dass Ihr nicht völlig nutzlos seid, sterbliches Wesen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4024] = {title = "Eine Kostprobe der Flamme", objective = "Begebt Euch in die Blackrocktiefen und tötet Bael'Gar.\n\nIhr wisst lediglich, dass der Riese irgendwo in den Blackrocktiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen.\n\nBringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück.", description = "Ich möchte die sengenden Flammen des Feuerberges schmecken. Die flüssigen Feuer des Blackrock über mich strömen lassen. Diese Essenz, diese sengende Hitze ist es, nach der ich mich sehne.\n\nIn den Tiefen des Blackrock haust Bael'Gar: ein Wesen aus reinstem Feuer, geboren aus den Flammen des Ragnaros. Tötet Bael'Gar und bringt mir aus seinen glimmenden Überresten einen Teil seines inneren Feuers.\n\nVerwendet die Drachenhaut für seine Überreste, um die innere Flamme sicher entnehmen zu können.\n\nSeid erfolgreich und Ihr werdet belohnt.", progress = "Habt Ihr den Riesen niedergestreckt?", completion = "&lt;Cyrus reißt Euch die feurige Essenz aus der Hand.&gt;\n\nJA!\n\nNehmt Euren Lohn und hebt Euch hinfort! Geht mir unverzüglich aus den Augen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchieferhautcapeWyrmbalg-SchiftungValconische Schärpe\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[4041] = {title = "Das Videre-Elixier", objective = "Klar, wenn Ihr mir eine Evowurzel bringt, dann kann ich Euch auch das Videre-Elixier machen.\n\nIch weiß alle möglichen Dinge über Kräuter und Alchimie... Ich könnte Euch Geschichten erzählen... zum Beispiel, wie ich mal Gold aus dem Käse gemacht habe, den ich eigentlich zum Mittagessen... he! Wo wollt Ihr hin?", description = nil, progress = "Klar, wenn Ihr mir eine Evowurzel bringt, dann kann ich Euch auch das Videre-Elixier machen.\n\nIch weiß alle möglichen Dinge über Kräuter und Alchimie... Ich könnte Euch Geschichten erzählen... zum Beispiel, wie ich mal Gold aus dem Käse gemacht habe, den ich eigentlich zum Mittagessen... he! Wo wollt Ihr hin?", completion = "Soso, Ihr habt also den alten Miblon reingelegt, wie?", rewards = "Ihr bekommt:\n\nVidere-Elixier"},
[4061] = {title = "Aufstieg der Maschinen", objective = "Begebt Euch in die brennende Steppe und beschafft für Theodora Mulvadania 10 gerissene Elementarsplitter.\n\nEuch fällt ein, dass Theodora gesagt hat, die Golems und Elementare in der Gegend seien eine gute Quelle für solche Splitter.", description = "Wir stießen bereits bei unseren ersten Streifzügen in der sengenden Schlucht auf die Maschinen. Weitere Nachforschungen ergaben, dass sie aus der brennenden Steppe, eventuell auch aus den Blackrocktiefen, stammen. Und dafür brauchen wir Euch, <Name>.\n\nEure erste Aufgabe besteht darin, Euch in die brennende Steppe zu begeben und dort einige Elementarsplitter von den Felsautomatons und den geringen Felsgeschöpfen der Gegend zu beschaffen. Sobald Ihr eine ausreichende Menge gesammelt habt, kehrt zu mir zurück, dann werde ich herausfinden, woher sie wirklich stammen.", progress = "Nehmt diese Aufgabe nicht zu leicht, <Name>!", completion = "&lt;Theodora legt die Fragmente vor sich hin.&gt;\n\n&lt;Theodora untersucht die Fragmente sorgfältig mit einem riesigen Monokel.&gt;\n\nInteressant. In die strukturelle Basis jedes dieser Fragmente sind... Initialen eingeätzt.", rewards = "Ihr bekommt:\n\n"},
[4062] = {title = "Aufstieg der Maschinen", objective = "Bringt die Elementarsplitterprobe zu Lotwil Veriatus.\n\nIhr erinnert Euch, dass Theodora sagte, Lotwil sei in einem Lager im Osten stationiert.", description = "G.L.A.\n\nDas sind die Buchstaben, die in die Elementarsplitter eingeprägt sind. Unter den Initialen findet sich eine Markierung für einen Rang oder etwas in der Art. Die Maschinen, die Ihr in der brennenden Steppe zerstört habt, hatten den 'Rang IV'. Ich nehme an, das ist ein eher niedriger Rang.\n\nBringt diese Splitterprobe in das Lager im Osten zu Lotwil Veriatus. Er ist ein Gelehrter und vor allem für seine Arbeit auf dem Gebiet der Elementarforschung bekannt. Vielleicht kann er uns bei unserer Suche helfen.", progress = "Was habt Ihr denn da, <Volk>?", completion = "&lt;Lotwil erbleicht.&gt;\n\nIch... Ich kenne diese Markierungen.", rewards = "Ihr bekommt:\n\n"},
[4063] = {title = "Aufstieg der Maschinen", objective = "Sucht und tötet Golemlord Argelmach. Bringt Lotwil seinen Kopf. Außerdem müsst Ihr 10 intakte Elementarkerne von den Wuthäschergolems und Kriegshetzerkonstrukten, die Argelmach beschützen, beschaffen. Das wisst Ihr, weil Ihr übernatürliche Fähigkeiten habt.", description = "Das kann doch nicht Argelmach sein... Argelmach wurde vor zehn Jahren getötet. Warum ich das so genau weiß? Weil ich derjenige war, der ihn getötet hat.\n\nEr war ein abscheulicher Zwerg und wild entschlossen, mein Lebenswerk zu verderben und es für seine teuflischen Zwecke zu benutzen. Wie es scheint, finden die Tückischen immer einen Weg, ihrer gerechten Strafe zu entgehen.\n\nWenn dies Argelmachs Werk ist, dann muss er zerstört werden. Ich brauche Proben seiner jüngsten Schöpfungen. Mit den richtigen Proben kann ich vielleicht diesem Aufstand ein Ende machen. Die Schöpfungen bewachen Argelmach in den Blackrocktiefen.", progress = "War er es? War er wirklich am Leben?", completion = "Was ist das? Dieser Kopf besteht nicht aus Fleisch und Blut! Es muss eine Schöpfung der Dunkeleisenzwerge sein: ein Schatten Argelmachs - NOCH EINE Maschine! Ich fürchte, Eure Vernichtung Argelmachs wird nicht von Dauer sein und bald wird eine weitere Kopie seinen Platz einnehmen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAzurblaue MondamiciaRegenzauberertuchBasaltschuppenrüstungLavaplattenstulpen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[4081] = {title = "SOFORT TÖTEN: Dunkeleisenzwerge", objective = "Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren!\n\nKriegsherr Goretooth möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt.", description = "Auf Befehl von Kriegsherr Goretooth, Kommandant des Expeditionskorps von Kargath:\n\nAlle Streitkräfte, über die General Zornesschmied in den Blackrocktiefen verfügt, müssen ausgelöscht werden.\n\nZornesschmieds Männer sind rücksichtslose Killer und verantwortlich für den Massenmord an der 109. Division des Expeditionskorps von Kargath. Alle Helden, die diesen gefühllosen Bestien gegenübertreten wollen, werden aufgefordert, extreme Vorsicht walten zu lassen.\n\nJede Person, die die erste Kampfreihe von General Zornesschmieds Streitkräften in den Blackrocktiefen vernichtet, wird einen Tribut erhalten.", progress = nil, completion = "Dieser erste Schlag sollte Zornesschmied schon ein bisschen die Laune vermiesen. Und jetzt, bewegt Euch, Soldat. Ich muss arbeiten, Schlachten planen, Feinde vernichten!\n\nSchaut Euch die Plakate an, wenn Ihr noch etwas tun wollt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4082] = {title = "SOFORT TÖTEN: Hochrangige Führungskräfte der Dunkeleisenzwerge", objective = "Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren!\n\nKriegsherr Goretooth möchte, dass Ihr 10 Sanitäter der Zorneshämmer, 10 Soldaten der Zorneshämmer und 10 Offiziere der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt.", description = "Auf Befehl von Kriegsherr Goretooth, Kommandant des Expeditionskorps von Kargath:\n\nDer Leiter der Aufklärungseinheit des KEK, Großmeister Lexlort, kam mit Neuigkeiten über den Verbleib einiger hochrangiger Führungskräfte der Dunkeleisenzwerge zurück. Hinter dem verschlossenen Tor, nahe dem Herzen der Stadt, bilden sie ihre Streitkräfte darin aus, unsere Männer auszulöschen. Geht in die Blackrocktiefen und vernichtet sie!\n\nWer diese Mission erfüllt, erhält einen Tribut.", progress = nil, completion = "Ganz zweifellos ist der Zornesschmied jetzt... wütend. Kommt wieder zu mir, wenn Ihr einen dritten Tribut erhaltet, dann können wir mit der Operation 'Tod dem Zornesschmied' beginnen. Ich kann nicht darüber sprechen, was das im Detail bedeutet, aber seid gewiss: jemand wird sterben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4083] = {title = "Der spektrale Kelch", objective = "Der spektrale Kelch schwebt in der Luft, leicht ansteigend und dann absinkend, so, als bewege er sich im Takt eines sterbenden Herzens.", description = nil, progress = "Der spektrale Kelch schwebt in der Luft, leicht ansteigend und dann absinkend, so, als bewege er sich im Takt eines sterbenden Herzens.", completion = "Geräuschlos fallen die Edelsteine in die Tiefen des Kelchs...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4084] = {title = "Silberherz", objective = "Beschafft 11 silbrige Klauen und 1 Eisenstammherz für Eridan Bluewind im Teufelswald.", description = "Ich kenne denjenigen nicht, von dem Ihr sprecht, <Name>.\n\nDoch keine Sorge, wenn Euer Freund auf der Suche nach mir war, dann weiß ich, was er von mir wollte.\n\nIm Herzen des Un'Goro Kraters lebt das Böse in seiner reinsten Form. Dort manifestiert es sich in der Gestalt eines Elementars namens Sturmflamme. Er wird wird von einer Aura beschützt, die niemand durchdringen kann.\n\nNiemand... außer denen, die über genügend Macht verfügen. Diese Macht kann ich Euch lehren, <Name>.\n\nDoch zunächst müsst Ihr mir eine Bitte erfüllen. Beschafft 11 silbrige Klauen und 1 Eisenstammherz von den Kreaturen im Teufelswald und kommt dann zu mir zurück.", progress = "Ich kann Euch mehr über die Macht sagen, die Ihr benötigt, um Sturmflamme zu besiegen, doch zunächst müsst Ihr die Dinge besorgen, die ich brauche.", completion = "Nun gut, &lt;Name&gt;. Wie ich sehe, ist es Euch ernst damit, Eurem Freund zu helfen.", rewards = "Ihr bekommt:\n\n"},
[4101] = {title = "Den Teufelswald säubern", objective = "Bringt 15 Einheiten Blutharz zu Arathandris Silversky im Teufelswald.", description = "Die Pflanzen schenken dem Teufelswald Leben, doch sogar sie leiden unter der Besudelung der Verderbnis. Ich kenne Wege, um sie zu säubern, doch dieses Wissen kann ich an niemanden weitergeben, den ich nicht kenne oder dem ich nicht vertraue. Beweist mir, dass Ihr der Sache des Zirkels des Cenarius wirklich helfen wollt!\n\nNördlich von hier liegen die Eisenstammhöhlen. Für die Wucherborkenelementare, die sich dort aufhalten, gibt es keine Hoffnung mehr auf Säuberung. Ich bitte Euch, bringt mir ihren Saft, er wird Blutharz genannt, damit ich ihn studieren kann. Vielleicht gelingt es mir so, die anderen Lebensformen hier zu retten.", progress = "Ich weiß, dass der Teufelswald leidet, <Name>, denn ich leide mit ihm! Doch ich muss standhaft bleiben; fiele mein Wissen in die falschen Hände, dann wäre dies eine Katastrophe für den ganzen Teufelswald.\n\nBringt mir das Blutharz der getöteten Wucherborkenelementare, dann vertraue ich Euch genug, um mir von Euch dabei helfen zu lassen, ein Mittel gegen die Verderbnis herzustellen.", completion = "Mit dem Blutharz werden wir einen Weg finden, die Verderbnis hier im Teufelswald zu besiegen. Ihr habt mir bewiesen, dass Ihr bereit seid, alles zu tun, was notwendig ist, um dem Zirkel des Cenarius zu helfen. Ich vertraue Euch jetzt.\n\nEs mag Euch seltsam erscheinen, dass Ihr Euch mir gegenüber durch die Tötung der Elementare beweisen musstet, doch die Rettung des Lebens von unzähligen intelligenten Wesen rechtfertigt die Mittel, die wir ergriffen haben. Jetzt können wir uns auf die Bewahrung des Lebens konzentrieren... mit den Salben, die ich herzustellen weiß.\n\n&lt;Name&gt;, endlich ist die Zeit gekommen, den Teufelswald zu säubern.", rewards = "Ihr bekommt:\n\n"},
[4102] = {title = "Den Teufelswald säubern", objective = "Bringt 15 Einheiten Blutharz zu Maybess Riverbreeze im Teufelswald.", description = "Die Pflanzen schenken dem Teufelswald Leben, doch sogar sie leiden unter der Besudelung der Verderbnis. Ich kenne Wege, um sie zu säubern, doch dieses Wissen kann ich an niemanden weitergeben, den ich nicht kenne oder dem ich nicht vertraue. Beweist mir, dass Ihr der Sache des Zirkels des Cenarius wirklich helfen wollt!\n\nNördlich von hier liegen die Eisenstammhöhlen. Für die Wucherborkenelementare, die sich dort aufhalten, gibt es keine Hoffnung mehr auf Säuberung. Ich bitte Euch, bringt mir ihren Saft, er wird Blutharz genannt, damit ich ihn studieren kann. Vielleicht gelingt es mir so, die anderen Lebensformen hier zu retten.", progress = "Ich weiß, dass der Teufelswald leidet, <Name>, denn ich leide mit ihm! Doch ich muss standhaft bleiben; fiele mein Wissen in die falschen Hände, dann wäre dies eine Katastrophe für den ganzen Teufelswald.\n\nBringt mir das Blutharz der getöteten Wucherborkenelementare, dann vertraue ich Euch genug, um mir von Euch dabei helfen zu lassen, ein Mittel gegen die Verderbnis herzustellen.", completion = "Mit dem Blutharz werden wir einen Weg finden, die Verderbnis hier im Teufelswald zu besiegen. Ihr habt mir bewiesen, dass Ihr bereit seid, alles zu tun, was notwendig ist, um dem Zirkel des Cenarius zu helfen. Ich vertraue Euch jetzt.\n\nEs mag Euch seltsam erscheinen, dass Ihr Euch mir gegenüber durch die Tötung der Elementare beweisen musstet, doch die Rettung des Lebens von unzähligen intelligenten Wesen rechtfertigt die Mittel, die wir ergriffen haben. Jetzt können wir uns auf die Bewahrung des Lebens konzentrieren... mit den Salben, die ich herzustellen weiß.\n\n&lt;Name&gt;, endlich ist die Zeit gekommen, den Teufelswald zu säubern.", rewards = "Ihr bekommt:\n\n"},
[4103] = {title = "Salbe durch Jagd", objective = "Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.\n\nIm Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", description = nil, progress = "Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.\n\nIm Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr Eure cenarischen Pflanzensalben. Durchsucht den Teufelswald nach verderbten Pflanzen, &lt;Name&gt;! Wo auch immer sie sind, benutzt die Salbe, die ich Euch gab, um sie zu läutern.", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"},
[4104] = {title = "Salbe durch Bergbau", objective = "Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.\n\nWenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", description = nil, progress = "Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.\n\nWenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr etwas cenarische Pflanzensalbe. Wenn Ihr beim Bergbau im Teufelswald noch mehr Vitriol findet, dann hebt es auf jeden Fall für mich auf! Je mehr Ihr davon findet, desto mehr Salbe kann ich herstellen.", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"},
[4105] = {title = "Salbe durch Sammlung", objective = "Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Säuberungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.\n\nWenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben.", description = nil, progress = "Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Säuberungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.\n\nWenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;, jedes Teilchen hiervon wird, sobald wir es geläutert haben, dabei helfen, den Teufelswald zurückzugewinnen. Hier, nehmt einige Dosen der cenarischen Pflanzensalbe und begebt Euch in den Wald. Wir dürfen nicht damit zögern, das Land der Verderbnis zu entreißen, &lt;Volk&gt;!", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"},
[4106] = {title = "Salbe durch Kürschnerei", objective = "Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.\n\nSobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch etwas cenarische Pflanzensalbe dafür, die ich bereits hergestellt habe.", description = nil, progress = "Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.\n\nSobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch etwas cenarische Pflanzensalbe dafür, die ich bereits hergestellt habe.", completion = "Genau das brauche ich. Hier, nehmt diese Pflanzensalben und verwendet sie, um den Teufelswald der Verderbnis zu entreißen. Wir müssen beharrlich bleiben, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"},
[4107] = {title = "Salbe durch Entzauberung", objective = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", description = nil, progress = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", completion = "Hier sind einige cenarische Pflanzensalben - ich brauche nur eine geringe Netheressenz, um sie herzustellen, &lt;Name&gt;. Die Essenz ist bei weitem der wirksamste Gegenstand, um Schwerter zu Pflugscharen zu machen, wenn man so sagen will. Wenn Ihr mehr Salbe braucht, dann kommt wieder zu mir!", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"},
[4108] = {title = "Salbe durch Jagd", objective = "Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.\n\nIm Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", description = nil, progress = "Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.\n\nIm Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr Eure cenarischen Pflanzensalben. Durchsucht den Teufelswald nach verderbten Pflanzen, &lt;Name&gt;! Wo auch immer sie sind, benutzt die Salbe, die ich Euch gab, um sie zu läutern.", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"},
[4109] = {title = "Salbe durch Bergbau", objective = "Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.\n\nWenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", description = nil, progress = "Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.\n\nWenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr etwas cenarische Pflanzensalbe. Wenn Ihr beim Bergbau im Teufelswald noch mehr Vitriol findet, dann hebt es auf jeden Fall für mich auf! Je mehr Ihr davon findet, desto mehr Salbe kann ich herstellen.", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"},
[4110] = {title = "Salbe durch Sammlung", objective = "Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Läuterungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.\n\nWenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben.", description = nil, progress = "Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Läuterungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.\n\nWenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;, jedes Teilchen hiervon wird, sobald wir es geläutert haben, dabei helfen, den Teufelswald zurückzugewinnen. Hier, nehmt einige Dosen der cenarischen Pflanzensalbe und begebt Euch in den Wald. Wir dürfen nicht damit zögern, das Land der Verderbnis zu entreißen, &lt;Volk&gt;!", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"},
[4111] = {title = "Salbe durch Kürschnerei", objective = "Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.\n\nSobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch einige cenarische Pflanzensalben dafür, die ich bereits hergestellt habe.", description = nil, progress = "Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.\n\nSobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch einige cenarische Pflanzensalben dafür, die ich bereits hergestellt habe.", completion = "Genau das brauche ich. Hier, nehmt diese Pflanzensalben und verwendet sie, um den Teufelswald der Verderbnis zu entreißen. Wir müssen beharrlich bleiben, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"},
[4112] = {title = "Salbe durch Entzauberung", objective = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", description = nil, progress = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", completion = "Hier sind einige cenarische Pflanzensalben - ich brauche nur eine geringe Netheressenz, um sie herzustellen, &lt;Name&gt;. Die Essenz ist bei weitem der wirksamste Gegenstand, um Schwerter zu Pflugscharen zu machen, wenn man so sagen will. Wenn Ihr mehr Salbe braucht, dann kommt wieder zu mir!", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"},
[4113] = {title = "Verderbte Liedblume", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[4114] = {title = "Verderbte Liedblume", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[4115] = {title = "Verderbte Windblüte", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[4116] = {title = "Verderbte Liedblume", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[4117] = {title = "Verderbte Peitscherwurzel", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet drei cenarische Pflanzensalben auf die Peitscherwurzel an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[4118] = {title = "Verderbte Liedblume", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[4119] = {title = "Verderbter Nachtdrache", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Nachtdrachenpflanze aussieht. Die Früchte, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, was wie eine Nachtdrachenpflanze aussieht. Die Früchte, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet vier cenarische Pflanzensalben auf die Nachtdrachenpflanze an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[4120] = {title = "Die Kraft der Verderbnis", objective = "Talo Thornhoff im Camp Mojache in Feralas möchte, dass Ihr 12 Wutklauengrizzlys und 12 Teufelspfotenverheerer im Teufelswald erledigt.", description = "Als Jäger strebe ich danach, die Stärken nachzuahmen, die ich bei meinen Gegnern sehe. Man kann den Kampf zu seinen Gunsten wenden, indem man einfach seinen Feind gut kennt, <Name>.\n\nAn einem Ort namens Teufelswald, nördlich von Ashenvale, wurden die Kreaturen durch eine Substanz, das so genannte Fel, verderbt. Die Bären und Wölfe wurden von ihr verrückt, allerdings glaube ich, dass sie dadurch auch noch stärker geworden sind.\n\nGeht, <Name>. Reist zum Teufelswald und tretet den Bestien gegenüber. Erfahrt selbst, ob sie wirklich so stark sind, wie ich glaube.", progress = nil, completion = "Nach Euren Beschreibungen klingt es, als würden die Kreaturen eine gedankenlose Wildheit an den Tag legen...\n\nBleibt wachsam, &lt;Name&gt;! Es könnte in Eurem Interesse sein, mehr über diese Verderbnis zu erfahren. Kennt immer Euren Feind.", rewards = "Ihr bekommt:\n\n"},
[4121] = {title = "Gefährliche Zwickmühle", objective = "Eskortiert Euren Gefangenen, Grark Lorkrub, durch die brennende Steppe und durch den Blackrock in die sengende Schlucht.\n\nEuch fällt ein, dass Lexlort gesagt hat, seine Männer würden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen.\n\nIhr werdet außerdem Eure Thoriumfesseln an Lexlort übergeben müssen.", description = "Glaubt Ihr wirklich, dass Ihr es mit mir als Gefangenem zum vereinbarten Treffpunkt schafft? Habt Ihr wirklich gedacht, Ihr könntet in eine schwer bewachte Festung der Blackrock eindringen und völlig unbemerkt ihren wertvollsten Besitz entführen?\n\nMan wird Euch vernichten!", progress = "Ich übernehme diesen dreckigen Verräter, <Name>.", completion = "Eure Heldentaten sollen nicht unbeachtet bleiben, &lt;Name&gt;. Diesen Tribut habt Ihr Euch verdient. Der Kriegsherr wird jetzt mit Euch über die letzte Aufgabe sprechen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4122] = {title = "Grark Lorkrub", objective = "Begebt Euch in die brennende Steppe und sucht Grark Lorkrub. Ihr erinnert Euch, dass Lexlort gesagt hat, er sei zuletzt in einer großen Festung der Blackrock gesehen worden.\n\nWenn Ihr Grark Lorkrub gefunden habt, verwendet die Thoriumfesseln, um ihn zu binden, und bringt ihn dann über den Blackrock in die sengende Schlucht zurück. Lexlorts Männer werden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen.\n\nBereitgestellter Gegenstand: \n", description = "Ich habe ihn durch die ganze sengende Schlucht, durch den Berg und in die brennende Steppe hinein verfolgt. Der Verräter wurde auf frischer Tat dabei ertappt, wie er den Blackrockorcs wichtige Informationen über die tagtäglichen Vorgänge bei uns lieferte. Ich spreche von Grark Lorkrub.\n\nEr sitzt jetzt in der brennenden Steppe, sicher unter deren Schutz - glaubt er jedenfalls.\n\nNehmt diese Fesseln, <Name>. Findet Grark, legt ihm die Fesseln an und führt ihn durch den Blackrock. Wenn Ihr das tut, ist ein Tribut Euer.", progress = nil, completion = "Seht Ihr denn nicht, welche Macht wir gewinnen, wenn wir uns der Blackrocklegion anschließen?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4123] = {title = "Das Herz des Berges", objective = "Bringt das 'Herz des Berges' zu Maxwort Uberglint in der brennenden Steppe.", description = "Schon seit Jahren suche ich einen ganz bestimmten Edelstein. Er wird das 'Herz des Berges' genannt und ist so groß wie Eure Faust! Die Dunkeleisenzwerge haben den Stein in ihrem Gewölbe weggeschlossen und ich kann machen, was ich will, sie wollen ihn mir einfach nicht verkaufen!\n\nAlso muss ich Gewalt anwenden.\n\nKämpft Euch zum unteren Gewölbe der Blackrocktiefen durch, brecht in den geheimen Safe dort ein und holt Euch das Herz. Dazu müsst Ihr den Wachmann Stahlgriff besiegen, aber der taucht erst auf, wenn Ihr jeden Reliktkasten im Gewölbe geöffnet habt!\n\nViel Glück.", progress = "Habt Ihr das 'Herz des Berges'? Für mich ist der Edelstein unendlich wertvoll.", completion = "Ihr habt das Herz! Erstaunlich! Es ist sogar noch schöner, als ich es mir vorgestellt hatte!\n\nBitte, &lt;Name&gt;, nehmt dies als Bezahlung an!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4124] = {title = "Der vermisste Kurier", objective = "Sprecht mit Ginro Hearthkindle in der Festung Feathermoon.", description = "Einer meiner Kollegen, Ginro Hearthkindle, braucht Hilfe und Informationen über den Aufenthaltsort eines Kuriers und der Pakete, die er bei sich hatte. Es ist etwa eine Woche her, dass der Kurier verschwunden ist; unsere eigene Suche hat nichts ergeben und wir wissen nicht, was wir noch tun sollen. Leider musste ich den Kurier für vermisst erklären.\n\nWenn Ihr freie Zeit und Kapazitäten habt, dann sprecht doch bitte mit Ginro. Er sollte irgendwo hier in der Festung sein, vielleicht in seinem Quartier.", progress = nil, completion = "Ich nehme an, Latro hat Euch geschickt. Ich glaube zwar inzwischen, dass es aussichtslos ist, aber ich nehme trotzdem gern jede Hilfe in Anspruch, die Ihr mir geben könnt. Ich muss zugeben... ich werde erleichtert sein, wenn ich diese Sache endlich vergessen kann. Jeden Tag gehe ich in die Wildnis Feralas' hinaus und suche dort nach einem Zeichen von Raschal. Und jeden Abend komme ich heim mit nichts in der Hand als Gnollzähnen und Enttäuschung.", rewards = "Ihr bekommt:\n\n"},
[4125] = {title = "Der vermisste Kurier", objective = "Sucht das Boot des Kuriers irgendwo entlang der Küste von Feralas.", description = "Es ist etwa eine Woche her, seit der Kurier Raschal sich nach Thalanaar aufgemacht hat. Er kennt Feralas gut; er ist schon bei uns, seit General Feathermoon das Exeditionskorps hergeführt hat. Ich weiß, dass er vorhatte, mit einem Ruderboot die Küste entlangzufahren und Feralas im Süden zu durchqueren, um das Lager der Horde zu umgehen.\n\nIch konnte sein Boot nicht finden, aber vielleicht findet Ihr es ja. Vielleicht liegt es irgendwo versteckt ... oder vielleicht wurde es auch versenkt. Wie dem auch sei, möglicherweise enthält es einen Hinweis darauf, wo Raschal ist. Wenn Ihr irgendetwas entdeckt, lasst es mich bitte wissen.", progress = nil, completion = "Ihr habt etwas gefunden, das wie ein havariertes Ruderboot aussieht. Durch das etwas schlammige Wasser seht Ihr backbords etliche klaffende Löcher: Das ganze Boot ist fast bis auf sein einfaches hölzernes Grundgerüst zerfetzt. Was auch immer dieses Boot so zugerichtet hat, muss versucht haben, es entzweizubrechen. Steuerbords ist das Boot mit einem kleinen Wappen der Festung Feathermoon bemalt.\n\nIm Matsch am Boden des Bootes seht Ihr etwas metallisch aufblitzen ...", rewards = "Ihr bekommt:\n\n"},
[4126] = {title = "Hurley Pestatem", objective = "Bringt Ragnar Donnerbräu in Kharanos das gestohlene Donnerbräurezept.", description = "Die Dunkeleisenzwerge, angeführt von dem Bösewicht Hurley Pestatem, haben eines der besten Rezepte der Donnerbräus gestohlen, jenes für das Donnerbräu Lagerbier. Diese Schurken! Sie verdienen ein solch edles Gebräu nicht!\n\n<Name>, ich habe eine schwierige Aufgabe für Euch. Geht zu den Blackrocktiefen in der brennenden Steppe, zerstört alle Fässer mit Donnerbräu Lagerbier, die Ihr finden könnt, und bringt unser Donnerbräurezept zurück!\n\nBitte, bringt das Rezept unbedingt zurück, und wenn Ihr dafür die ganzen Blackrocktiefen umkrempeln müsstet!", progress = "Habt Ihr das Rezept, <Name>? Ich kann es nicht ertragen, dass diese Dunkeleisenzwerge sich an dem Stammgetränk meiner Familie laben!", completion = "Ihr habt es gefunden! Gut gemacht! Und ich hoffe, dass Ihr diesen Dunkeleisenzwergen und Hurley Pestatem eine ordentliche Abreibung verpasst habt!\n\nDie Donnerbräus stehen Euch jederzeit zu Diensten, &lt;Name&gt;! Ihr seid der Held des Tages!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHurtigschlagknüppelGliedmaßenspaltbeil\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\nDunkles zwergisches Lagerbier"},
[4127] = {title = "Havarie", objective = "Kehrt zur Festung Feathermoon zurück und zeigt Ginro Hearthkindle das gefundene Messer.", description = "Als Ihr mit der Hand durch den Matsch fahrt, fühlt Ihr plötzlich den Griff eines Messers unter Euren Fingern. Es sieht gut gepflegt aus und dürfte mit Sicherheit jemandem gehört haben, der auf dem Boot gewesen ist. Vielleicht hat das große Stück des verschwundenen Bootes irgendetwas mit seinem Verschwinden zu tun.\n\nIhr nehmt das Messer an Euch, denn Ginro Hearthkindle in der Festung Feathermoon hatte Euch angewiesen, ihm jegliche Hinweise sofort zu bringen. Allerdings werdet Ihr das ungute Gefühl nicht los, dass Ihr in diesem Gewässer nicht allein seid ...", progress = "Ah, da seid Ihr ja wieder, <Name>. Ich hoffe, dass Ihr etwas über Raschals Schicksal erfahren habt, so tragisch es auch sein mag.", completion = "Interessant... Ich glaube, das ist Raschals Messer. Ihr sagt, Ihr habt es auf dem Grund des Gewässers zusammen mit seinem Boot entdeckt? Tja, die Entdeckung des Messers allein wird nicht reichen, um Raschals Verschwinden zu erklären. Uns steht jedoch noch eine etwas unkonventionelle Methode zur Verfügung, mit der wir versuchen können, etwas herauszufinden.\n\nHabt Ihr schon mal von Psychometrie gehört?", rewards = "Ihr bekommt:\n\n"},
[4128] = {title = "Ragnar Donnerbräu", objective = "Sprecht mit Ragnar Donnerbräu.", description = "Hallo, <Name>. Wie ich hörte, soll Ragnar Donnerbräu außer sich vor Wut sein, dass jemand sein Bier gestohlen hat. Er sucht nach wackeren Abenteurern und ist gewillt, sie reichlich zu entlohnen.\n\nSprecht mit Ragnar, wenn Ihr Interesse habt. Ihr findet ihn in der Brauerei Donnerbräu in Kharanos in Dun Morogh.", progress = nil, completion = "Ich bin in der Tat fuchsteufelswild! Man hat mich beraubt! Eines der Rezepte unserer Familie wurde gestohlen! Wie können sie es wagen! Als hätte ich nicht schon Grund genug, die Dunkeleisenzwerge zu hassen! Aber jetzt, oh... jetzt sind sie dran!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4129] = {title = "Das wieder aufgetauchte Messer", objective = "Bringt Quintis Jonespyre in der Festung Feathermoon das gefundene Messer.", description = "Der Hausdruide der Festung, Quintis Jonespyre, verfügt über ein paar... ungewöhnliche Fertigkeiten. Eine davon ist die Psychometrie - die Fähigkeit, durch Berührung eines Objekts etwas über seine Geschichte zu erfahren. Fragt mich nicht, wie er das bewerkstelligt. Es muss etwas mit Magie zu tun haben, wovon ich nichts verstehe und womit ich auch nichts zu tun haben will. Zwei Dinge weiß ich jedoch: Erstens, ich habe gesehen, dass es funktioniert, und zweitens, der Gauner schuldet mir etwas.\n\nQuint lebt in einem kleinen Baumhaus. Bringt ihm das Messer und richtet ihm von mir aus, dass seine Kalimdor-Poker-Schulden bei mir beglichen sind, wenn er seinen Hokuspokus bei dem Messer wirkt.", progress = "Ach nein, also Ginro schickt Euch? Na ja...\n\nPsychometrie zehrt ziemlich an der Psyche... aber meine Verluste beim Kalimdor-Poker auch. Hier in der Festung nennt man mich den 'König der schlechten Karten'. Pech im Spiel... Glück im Umgang mit den Geheimnissen der Natur, könnte man sagen.\n\nWie dem auch sei, natürlich tu ich es. Das könnte genau der Durchbruch sein, den wir brauchen, um etwas über Raschals Schicksal in Erfahrung zu bringen. Wenn Ihr mir das Messer gebt, können wir gleich anfangen.", completion = "Ich danke Euch, &lt;Name&gt;.\n\nPsychometrie ist zwar nicht einmal im weitläufigsten Sinn eine exakte Kunst, doch habe ich mich ihrer manchmal bedient, um in Situationen, in denen andere schon längst aufgegeben haben, Erleuchtung zu finden. Ich glaube, wenn ich sie bei dem Messer anwende, das Ihr gefunden habt, könnte uns das einen Hinweis darauf geben, was aus Raschal geworden ist.\n\nEs wird nur einen Moment dauern, aber es ist eine für den Zaubernden nicht gerade angenehme Angelegenheit. Habt Nachsicht mit mir.", rewards = "Ihr bekommt:\n\n"},
[4130] = {title = "Psychometrie-Sitzung", objective = "Sprecht mit Ginro Hearthkindle in der Festung Feathermoon.", description = "Entschuldigt bitte, mir ist immer noch ein bisschen schwummrig. Wie dem auch sei, ich hatte ein paar nützliche Visionen.\n\nRaschal nimmt zwei lederne Rucksäcke aus seinem Boot und geht landeinwärts. Dann jedoch kehrt er zu seinem Boot zurück. Ich sehe Gnollskalps ... er ist auf ein paar Gnolle gestoßen - Waldpfoten nennt man sie, glaube ich. Er ist sehr besorgt - fast schon panisch - wegen etwas. Und das so sehr, dass er nicht bemerkt, wie sich Wasserelementare hinter seinem Rücken manifestieren. Hier enden die Visionen.\n\nIch muss mich ausruhen, tut mir Leid, <Name>. Erzählt Gin, was ich gesehen habe. Er muss das wissen.", progress = nil, completion = "Vielen Dank, dass Ihr mir von Quints Visionen berichtet habt, &lt;Name&gt;. Ich werde vielleicht ein bisschen großzügiger bei ihm sein, wenn wir uns das nächste Mal zu einem Kartenspiel zusammensetzen.\n\nRaschal kann in einem Kampf seinen Mann stehen und Gnolle sind nichts, was ihm Sorgen bereiten oder gar in Panik versetzen könnte. Vielleicht ist diese neue Information ja hilfreich für Euch und bringt Euch den Durchbruch, den wir so dringend benötigen.", rewards = "Ihr bekommt:\n\n"},
[4131] = {title = "Die Waldpfotengnolle", objective = "Durchsucht die Lager der Waldpfotengnolle im Süden Feralas nach Hinweisen auf den Verbleib des Kuriers oder seiner Habseligkeiten.", description = "Unsere 'Freunde', die Waldpfoten, mögen Raschal am Ende vielleicht zwar erwischt haben, aber irgendwie habe ich das Gefühl, als hätte sich da etwas anderes ereignet. Wie dem auch sei, es dürfte allerdings der beste Anhaltspunkt sein, um mit der Suche zu beginnen.\n\nIch wünschte nur, ich wüsste genauer, was zu tun ist, aber momentan kann ich lediglich sagen: 'Durchsucht die Lager der Waldpfoten. Macht Euch auf den Weg.' Ich weiß, dass Gnolle Gegenstände, die sie ergattern, behalten und um sie zanken. Vielleicht haben sie ja auch die Rucksäcke gefunden, die Quint erwähnte. Ohne Quints Visionen hätte ich bei früheren Suchaktionen niemals eine direkte Konfrontation mit ihnen gesucht, aber jetzt würde ich sagen: Auf sie mit Gebrüll!", progress = nil, completion = "An einen Baum in der Nähe sind zwei große Lederrucksäcke genagelt. Beide tragen auf der Vorderseite klein die Insignien der Festung Feathermoon...", rewards = "Ihr bekommt:\n\n"},
[4132] = {title = "Operation: Tod dem Zornesschmied", objective = "Begebt Euch zu den Blackrocktiefen und eliminiert General Zornesschmied! Kehrt zum Kriegsherrn Goretooth zurück, sobald Ihr diese Aufgabe erledigt habt.", description = "Ihr habt bemerkenswerte Arbeit geleistet, <Name>. Jetzt ist es an der Zeit, Euch auf Eure letzte Mission zu schicken.\n\nGeneral Zornesschmied, der für die Koordination der Angriffe auf die 109. Division des KEK und die massive Dezimierung unserer Truppen verantwortliche Dunkeleisenzwerg, muss zur Rechenschaft gezogen werden.\n\nDies wird zweifellos Eure schwerste Mission werden, aber solltet Ihr erfolgreich sein, wird man Euch reich entlohnen.", progress = nil, completion = "Endlich! Der Bösewicht hat seine gerechte Strafe erhalten! Ihr seid ein bemerkenswertes Individuum, &lt;Name&gt;. Tragt dieses Medaillon als Symbol Eures unerschütterlichen Engagements zum Wohle der Horde und des KEK.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nMedaillon des Eroberers"},
[4133] = {title = "Vivian Lagrave", objective = "Sprecht mit Schattenmeisterin Vivian Lagrave in Kargath.", description = "Schattenmeisterin Vivian Lagrave benötigt Eure Dienste. Sie lebt im Ödland, im Orc-Außenposten Kargath, wo sie dem Gerücht nachgeht, nach dem die Dunkeleisenzwerge der Blackrocktiefen angeblich ein bestimmtes Gebräu herstellen.\n\nSprecht mit Vivian. Sie erwartet Euch.", progress = nil, completion = "Vielen Dank, dass Ihr gekommen seid, &lt;Name&gt;. Dieser Ort entbehrt nicht eines gewissen rauen Charmes, aber es mangelt an den Annehmlichkeiten des Apothekariums.\n\nDoch genug geplaudert. Kommen wir zum Geschäft, ja?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4134] = {title = "Verlorenes Donnerbräurezept", objective = "Bringt Vivian Lagrave in Kargath das gestohlene Donnerbräurezept.", description = "Es geht das Gerücht umher, dass der Dunkeleisenzwerg Hurley Pestatem ein Rezept zum Brauen von Bier gestohlen habe. Dieses Bier, das Donnerbräu Lagerbier, soll angeblich jeden, der es trinkt, mit großer Kraft und Mut erfüllen. Wir möchten dieses Getränk gern untersuchen. Vielleicht finden wir ja noch andere Anwendungsgebiete für seine Vorzüge... Anwendungsgebiete, die eher im Einklang mit den Zielen der Verlassenen sind.\n\nDurchforstet die Blackrocktiefen, findet Hurley, nehmt das Donnerbräurezept von ihm und bringt es mir.\n\nUnd um ihn zu finden, müsst Ihr ihn möglicherweise locken, indem Ihr sein wertvolles Bier bedroht.", progress = "Habt Ihr das Donnerbräurezept, <Name>?", completion = "Sehr gut. Ich schicke dieses Rezept zu Studienzwecken zum Apothekarium, wo man ihm schon bald seine Geheimnisse entlocken wird. Eines Tages werden die Zwerge der Allianz die Vorzüge dieses Getränks am eigenen Leib zu spüren bekommen!\n\nIch finde das höchst amüsant. Vielleicht hat der Tod Auswirkungen auf den Sinn für Humor ... was meint Ihr?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHurtigschlagknüppelGliedmaßenspaltbeil\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\nÜberragender HeiltrankGroßer Manatrank"},
[4135] = {title = "Die verwundene Tiefe", objective = "Da Ihr jetzt Raschals letzten bekannten Aufenthaltsort in Erfahrung gebracht habt, setzt Ihr die Suche nach ihm oder seinen sterblichen Überresten in der verwundenen Tiefe fort. Laut Notiz soll dieser Ort südlich der Lager der Waldpfotengnolle liegen.\n\nBereitgestellter Gegenstand: \n", description = "In den Rucksäcken befinden sich zwei Gegenstände: Der erste ist ein für Thalanaar bestimmtes Paket mit Waren, der zweite eine hastig hingekritzelte Notiz, die an einen unbekannten Empfänger gerichtet ist.\n\nDie Notiz spricht von der Entdeckung heimtückischer käferartiger Kreaturen südlich des Gnoll-Lagers an einem Ort der verwundene Tiefe genannt wird. Der Verfasser wollte die Sache persönlich untersuchen, da er dies als ernsthafte Bedrohung für ganz Feralas befand. Die Notiz ist mit 'Raschal aus Feathermoon' unterzeichnet.\n\nOffenbar habt Ihr jetzt herausgefunden, wohin Raschal letztlich verschwunden ist.", progress = nil, completion = "Ihr habt eine große Kapsel fremdartigen Ursprungs entdeckt. Die Oberfläche der Kapsel wirkt schleimig, doch an manchen Stellen ragen gehärtete Vorsprünge heraus. Die Kapsel selbst ist hoch und tief genug, dass ein humanoides Wesen leicht darin Platz finden könnte ... und anhand des humanoid anmutenden Umrisses der Gestalt darin, die durch die dünne Haut der Kapsel sichtbar ist, nehmt Ihr an, dass es tatsächlich ein solches Wesen ist, das darin verborgen liegt.", rewards = "Ihr bekommt:\n\n"},
[4136] = {title = "Ribbly Screwspigot", objective = "Bringt Yuka Screwspigot in der brennenden Steppe Ribblys Kopf.", description = "Mein Bruder Ribbly hat unserer Familie schon immer auf der Tasche gelegen, unser Geld genommen und es für eine Dummheit nach der anderen ausgegeben.\n\nTja, seine letzte Dummheit muss wohl seine bislang schlimmste gewesen sein, denn Baron Revilgaz von Booty Bay hat ein Kopfgeld auf den armen Ribbly ausgesetzt. Ich kann Euch gar nicht sagen, wie glücklich das die Screwspigots macht! Endlich ist unser kleiner Ribbly mal etwas wert!\n\nEr versteckt sich jetzt allerdings ganz weit unten in den Blackrocktiefen. Sucht ihn doch bitte und bringt ihn zu mir!\n\nUnd falls er nicht mitkommen will, ist das auch kein Problem ... bringt mir einfach seinen Kopf.", progress = "Habt Ihr Ribbly mitgebracht? Oder zumindest einen Teil von ihm?", completion = "Aha! Ihr habt ihn gefunden! Und wie mir scheint, wollte mein kleiner Bruder offenbar nicht freiwillig mitkommen. Wie schade. Ich hätte zu gern sein Gesicht gesehen, wenn ich ihm von unserem Plan, ihn Revilgaz auszuliefern, erzählt hätte.\n\nDanke, &lt;Name&gt;. Ihr habt meine Familie sehr glücklich gemacht. Und Ribbly hat nie so friedlich ausgesehen wie jetzt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGroll-StiefelBußwerk-SchiftungStahlschienenrüstung\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[4141] = {title = "Muigin und Larion", objective = "Sammelt 15 Blutblüten und kehrt zu Muigin zurück.", description = "Seht Ihr Larion da drüben? Es ist SEINE Schuld, dass wir hier sind!\n\nIch hab ihm noch gesagt, dass wir in die falsche Richtung gehen, aber hat er auf mich gehört? Und stellt Euch vor, jetzt spricht er nicht mehr mit mir. Na ja, erlauben wir uns doch ein kleines Späßchen mit ihm, bis er es sich anders überlegt.\n\nSind Euch die seltsamen pflanzenartigen Kreaturen in dieser Gegend hier aufgefallen? Die machen nichts als Ärger, wirklich, aber ich glaube, wenn man sie ordentlich abrichten würde, könnte man sie dazu bringen, Befehlen zu gehorchen.\n\nAls Erstes bräuchte ich allerdings ein paar davon, um sie zu studieren. Meint Ihr, Ihr könntet mir ein paar bringen?", progress = "Larion kann sich auf was gefasst machen, das steht mal fest!", completion = "Ich hoffe, sie haben Euch nicht zu viel Ärger bereitet, &lt;Name&gt;. Ich versuche immer, ihnen aus dem Weg zu gehen - sie sind mir einfach zu wild!\n\nEinmal wollte ich über eine drüberspringen... Da griff sie mich an. Das ist doch kein Benehmen für eine Pflanze!", rewards = "Ihr bekommt:\n\n"},
[4142] = {title = "Ein Besuch bei Gregan", objective = "Bringt Gregan Brewspewer in Feralas eine Blutblüte.", description = "Ich weiß nicht so recht, was ich davon halten soll, <Name>. Die Pflanzen... sie scheinen ein gewisses Maß an Intelligenz zu besitzen.\n\nAllerdings bin ich auf diesem Gebiet kein Experte. Aber ich kenne einen!\n\nGeht nach Nord-Feralas und sucht einen Freund von mir auf, er heißt Gregan Brewspewer. Er kennt sich mit solchen Dingen bestens aus.\n\nGregan kann uns bestimmt weiterhelfen. Ihr findet ihn draußen in der Wildnis, denn für das Großstadtleben hat er nicht viel übrig.", progress = "Ich lebe hier draußen im Wald... Es ist so friedlich hier.\n\nNa, wenigstens dachte ich das. Ich bekomme hier draußen mehr Besuch als damals, als ich noch in Ironforge wohnte!", completion = "Eine Blutblüte was? Hmmm... Tja, Ihr solltet mir lieber mal erklären, was Ihr vorhabt, dann sage ich Euch, ob ich Euch helfen kann oder nicht.", rewards = "Ihr bekommt:\n\n"},
[4143] = {title = "Der Dunst des Bösen", objective = "Sammelt 5 Proben Dunst der Atal'ai und bringt sie Muigin im Un'Goro Krater.", description = "Um ehrlich zu sein, <Name>, solche Pflanzen habe ich auf meinen Reisen noch nie gesehen. Vielleicht sollte ich mal einen Ausflug zu diesem Krater machen...\n\nEgal, ich weiß vermutlich, was Muigin benötigt - Dunst der Atal'ai. Das ist ein abscheuliches Zeug, sehr schwer zu sammeln, aber es ist genau das, was er benötigt, um diese kleinen Monster unter Kontrolle zu bringen.\n\nIhr müsst zum Tempel von Atal'Hakkar in den Sümpfen des Elends gehen. Den Dunst der Atal'ai bekommt Ihr von Tieflauerern, Düsterwürmern oder Brühschlammern, die man dort findet. Viel Glück, <Name>!", progress = "Larion spricht immer noch nicht mit mir! Wie kann man nur so nachtragend sein!", completion = "Ich muss gestehen, dass ich das Zeug nur sehr ungern anfasse, &lt;Name&gt;! Aber wenn Gregan sagt, dass es funktioniert, dann will ich es mal ausprobieren!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4144] = {title = "Blutblütensprösslinge", objective = "Das ist mein Plan, <Name>: Zieht los und sammelt ein paar Blutblütensprösslinge - Ihr wisst schon, das sind Pflanzen, die noch nicht ganz ausgetrieben haben, und bringt sie mir. Dann werde ich sehen, was man mit dem Dunst der Atal'ai anfangen kann.\n\nIhr haltet mich vielleicht für rachsüchtig... Und damit liegt Ihr absolut richtig! \n\nDie Wahrheit ist, ich weiß, wie man hier wegkommt, aber solange Larion nicht zugibt, dass ich Recht habe, rühre ich mich nicht von der Stelle!\n\nUnd nun hinfort mit Euch. Sucht diese Blutblütensprösslinge, dann gönnen wir uns ein bisschen Spaß!", description = nil, progress = "Das ist mein Plan, <Name>: Zieht los und sammelt ein paar Blutblütensprösslinge - Ihr wisst schon, das sind Pflanzen, die noch nicht ganz ausgetrieben haben, und bringt sie mir. Dann werde ich sehen, was man mit dem Dunst der Atal'ai anfangen kann.\n\nIhr haltet mich vielleicht für rachsüchtig ... Und damit liegt Ihr absolut richtig! \n\nDie Wahrheit ist, ich weiß, wie man hier wegkommt, aber solange Larion nicht zugibt, dass ich Recht habe, rühre ich mich nicht von der Stelle!\n\nUnd nun hinfort mit Euch. Sucht diese Blutblütensprösslinge, dann gönnen wir uns ein bisschen Spaß!", completion = "Dann mal los, &lt;Name&gt;! Damit werden wir Larions Aufmerksamkeit erringen!", rewards = "Ihr bekommt:\n\n"},
[4145] = {title = "Larion und Muigin", objective = "Jagt 5 Blutblütenpeitscher, 5 Blutblütendrescher, 5 Blutblütenschinder und 5 Blutblütenfallen für Larion in Marshals Zuflucht.", description = "Seht Ihr Muigin da drüben? Es ist SEINE Schuld, dass wir uns verirrt haben!\n\nIch kannte den richtigen Weg, aber er bestand darauf, eine Abkürzung zu nehmen, und so sind wir hier gelandet!\n\nUnd um die Lage noch zu verschlimmern, schickt er mir jetzt auch noch seine verrückten Pflanzen, um mich zu ärgern. Ich bin so wütend, dass ich bis auf weiteres kein Wort mehr mit ihm reden werde, aber diese Quälgeister sind wirklich unerträglich.\n\nWarum versuchen wir nicht als Erstes, seinen Bestand ein bisschen zu dezimieren? Geht hinaus und jagt einige Blutblüten und kehrt dann zu mir zurück.", progress = nil, completion = "Danke für Eure Hilfe, &lt;Name&gt;, aber ich fürchte, ich habe schlechte Neuigkeiten...", rewards = "Ihr bekommt:\n\n"},
[4146] = {title = "Schrumpf-Treibstoff", objective = "Bringt Larion in Marshals Zuflucht den ungeladenen Schrumpfer und 5 Proben Dunst der Atal'ai.", description = "Ihr habt Glück, <Name>! Während Marvon fort war, habe ich an einigen meiner eigenen Experimente gearbeitet, eines davon ist ein Käferschrumpfer mit kurzer Reichweite. Nur noch ein paar kleine Änderungen, dann ist er perfekt, um damit diese Blutblütenplagen zu beseitigen.\n\nIhr könnt gern einen meiner Schrumpfer-Prototypen haben, aber Ihr benötigt noch etwas Treibstoff dafür. Den für den Schrumpfer benötigten Dunst der Atal'ai findet Ihr im Tempel von Atal'Hakkar. Ihr bekommt ihn von Tieflauerern, Düsterwürmern oder Brühschlammern.", progress = "Das kann einen echt fertig machen, <Name>. Diese Biester lassen mich einfach nicht in Ruhe!", completion = "Marvon war also nicht da, eh? Na ja, zeigt mir trotzdem, was Ihr da habt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4147] = {title = "Marvons Werkstatt", objective = "Reist zu Marvon Rivetseekers Werkstatt in Ratchet.", description = "Ich habe herausgefunden, was Muigin so treibt. Er züchtet da drüben doch tatsächlich diese verdammten Dinger!\n\nIch glaube, die einzige Lösung des Problems besteht darin, mit... nein, nicht mit ihm zu sprechen... Was für ein Blödsinn! Die Lösung ist zurückzuschlagen!\n\nWir brauchen die Hilfe meines Freundes Marvon, der in Ratchet eine Werkstatt hat. Er kann bestimmt irgendein Gerät zusammenbasteln, das uns helfen wird.", progress = nil, completion = "Marvon ist schon eine ganze Weile fort, &lt;Name&gt;. Er wollte nach Tanaris, um dort ein paar der alten Troll-Ruinen zu untersuchen.\n\nAlso, was wolltet Ihr doch noch gleich?", rewards = "Ihr bekommt:\n\n"},
[4148] = {title = "Blutblütenschrumpfer", objective = "Damit der Schrumpfer funktioniert, brauchen wir ein Exemplar der Kreaturen, für die er eingestellt werden soll. Geht zum Krater und holt einen Blutblütensprössling. Dann kann ich ihn so einstellen, dass er bei Muigins kleinen Freunden funktioniert...\n\nWenn der Typ nicht so stur wäre, könnten wir alle schon längst auf dem Heimweg sein. Aber jetzt muss ich ihm erst einmal beweisen, dass mir seine Faxen nicht das Geringste ausmachen!", description = nil, progress = "Damit der Schrumpfer funktioniert, brauchen wir ein Exemplar der Kreaturen, für die er eingestellt werden soll. Geht zum Krater und holt einen Blutblütensprössling. Dann kann ich ihn so einstellen, dass er bei Muigins kleinen Freunden funktioniert...\n\nWenn der Typ nicht so stur wäre, könnten wir alle schon längst auf dem Heimweg sein. Aber jetzt muss ich ihm erst einmal beweisen, dass mir seine Faxen nicht das Geringste ausmachen!", completion = "Sieht aus, als würde es perfekt funktionieren, &lt;Name&gt;. Und nicht vergessen: Benutzt diesen Schrumpfer, sobald Ihr auf einen dieser Plagegeister stoßt!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nBlutblütenschrumpfer"},
[4161] = {title = "Rezept der Kaldorei", objective = "Sammelt 7 kleine Spinnenbeine für Zarrin in Dolanaar.", description = "Vor langer Zeit nannte man die Nachtelfen 'Kaldorei', was übersetzt 'Kinder der Sterne' bedeutet. Für Euch als <Klasse> ist es besonders wichtig etwas über die Vergangenheit zu erfahren, also hört gut zu, was ich Euch zu sagen habe, <Name>.\n\nDie Kaldorei waren schon immer stolz auf ihre harmonische Beziehung zur Natur. Das bedeutet, dass wir von der Natur nur nehmen, was notwendig ist, und es in gleichem Maße vergelten. Dieses Gleichgewicht bedeutet uns viel, <Name>.\n\nGeht und sammelt sieben kleine Spinnenbeine - und nicht mehr, und kommt dann zu mir zurück.", progress = "Denkt an das Gleichgewicht, <Name>. Ich möchte, dass Ihr das Leben im Wald verstehen lernt und Einfühlungsvermögen dafür entwickelt.", completion = "Denkt immer an das, was ich Euch heute gezeigt habe, &lt;Name&gt;. Ihr seid Teil des Gleichgewichts, das die Nachtelfen auch in schweren Zeiten aufrechtzuerhalten bestrebt sind.", rewards = "Ihr bekommt:\n\nRezept: Kaldorei-SpinnenkebabKaldorei-Spinnenkebab"},
[4181] = {title = "Goblin-Ingenieurskunst", objective = "Wenn Ihr mehr über die Goblin-Ingenieurskunst wissen wollt, dann bringt das Handbuch der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan.", description = "Bei der Experteningenieurskunst gibt es zwei unterschiedliche Disziplinen: Gnom und Goblin. Ich erwähne die Ingenieurskunst der Goblins nur, weil ich ein fairer und unvoreingenommener Lehrer bin. Sie machen gern Dinge, die in die Luft gehen, und es ist ihnen dabei meistens egal, ob dabei was im Weg herumsteht - auch wenn sie es selbst sind.\n\nLest dieses Handbuch, <Name>. Wenn Ihr lernen wollt, wie Ihr Euch selbst in die Luft jagt, dann bringt es zu Nixx Sprocketspring nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", progress = "Ich kann neue Schüler genauso gut riechen wie exzellentes Sprengpulver - aus einer Meile Entfernung. Seid Ihr gekommen, um die Beherrschung der Explosion zu erlernen?", completion = "Tja, &lt;Name&gt;, Ihr habt gut daran getan, Unterweisung bei mir zu suchen! Jeder Schmock kann Experte für die Grundlagen der Ingenieurskunst werden - die Gnome und ihre von Strahlen verseuchte Heimat Gnomeregan sind der beste Beweis dafür. Aber es braucht schon klare Gedanken und eine RUHIGE HAND, um die Disziplin der Goblin-Ingenieurskunst zu meistern.\n\nHaltet Eure Ohren offen, &lt;Name&gt;, und Ihr könnt vielleicht was lernen.", rewards = "Ihr bekommt:\n\n"},
[4182] = {title = "Drachkin-Bedrohung", objective = "Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen. Kehrt zu Helendis Riverhorn zurück, sobald die Aufgabe erledigt ist.", description = "Das Leben in der brennenden Steppe ist voller Konflikte.\n\nSeht Euch nur mal diesen Ort an! Wir wissen nur sehr wenig darüber, was mit diesen Gebäuden geschehen ist, aber wir wissen, dass all das hier irgendwann vor der großen Explosion einmal Teil der Rotkammbergkette war.\n\nAber genug gejammert! Wir haben ein Problem, <Name>. Vielleicht sind Euch die Drachkin am Fuß dieses Bergkamms aufgefallen. Wir brauchen Hilfe, um sie zurückzuschlagen. Tötet so viele, wie Ihr könnt, und kommt dann zu mir zurück. Wenn Ihr erfolgreich seid, können wir uns vielleicht noch über andere Dinge unterhalten.", progress = "Wie läuft die Drachenjagd?", completion = "Ausgezeichnete Jagd, &lt;Name&gt;. Da wir jetzt wissen, dass Ihr Euch gegenüber den Drachkin behaupten könnt, können wir uns über dringendere Angelegenheiten unterhalten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4183] = {title = "Die wahren Meister", objective = "Reist nach Seenhain und händigt Magistrat SolomonHelendis Riverhorns Brief aus.", description = "Bislang nahmen wir an, dass die Blackrockorcs das Ergebnis ihrer primitiven Erziehung seien. Was wir jedoch hier, in ihrem Heimatland, entdeckt haben, erzählt uns eine ganz andere Geschichte.\n\nAngetrieben werden sie zwar tatsächlich von Kampfrausch und Streitlust, aber der schwarze Drachenschwarm ist es, der die Orcs von Blackrock beherrscht. Wir vermuten, dass es auch der schwarze Drachenschwarm ist, der ihre Wut und Feindseligkeit schürt.\n\nBringt diesen Brief zu Magistrat Solomon. Er wird wissen, was zu tun ist.\n\n<Helendis gibt Euch einen versiegelten Brief.>", progress = "Seid gegrüßt, <Name>. Sind wir uns schon einmal begegnet? Ihr kommt mir irgendwie bekannt vor.", completion = "&lt;Magistrat Solomon öffnet den versiegelten Brief von Helendis und beginnt zu lesen.&gt;", rewards = "Ihr bekommt:\n\n"},
[4184] = {title = "Die wahren Meister", objective = "Reist nach Stormwind und tragt Solomons Hilfegesuch dem Hochlord Bolvar Fordragon vor.\n\nBolvar residiert in der Burg Stormwind.", description = "Das sind schlimme Neuigkeiten, <Name>. Zu entdecken, dass unsere Todfeinde nicht mehr als Marionetten einer viel größeren Bedrohung sind, ist wahrlich entmutigend. Es ist unmöglich, dass Seenhain einen Angriff durch die Blackrockorcs UND den schwarzen Drachenschwarm überleben könnte. Wenn Seenhain dieser Gefahr anheim fällt, dann fällt bald auch Dunkelhain, und was dann? Goldhain? Auch Stormwind?\n\nIhr müsst diese Information unbedingt sofort Hochlord Bolvar Fordragon in Stormwind überbringen! Wenn dies nicht die Unterstützung Stormwinds rechtfertigt, dann ist alles verloren.", progress = "Was führt Euch zur Burg Stormwind?", completion = "Großdrachen? Unmöglich!", rewards = "Ihr bekommt:\n\n"},
[4185] = {title = "Die wahren Meister", objective = "Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon.", description = "Solomon malt da ein recht düsteres Bild aus. Aber wir können es uns leider nicht leisten, unsere dünn gesäten Truppen aufgrund von reinen Vermutungen nach Seenhain zu schicken. Ich brauche einen Beweis für diese Behauptungen, bevor ich handeln kann.\n\nSprecht mit Lady Prestor, <Name>. Sie ist eine kluge Frau und weiß viel über Großdrachen und Drachkin. Vielleicht kann sie ein bisschen Licht in die Sache bringen.", progress = "<Bolvar betrachtet Euch eindringlich.>", completion = "&lt;Bolvar reibt sein Kinn, als wäre er tief in Gedanken versunken.&gt;\n\nIch respektiere zwar Lady Prestors Haltung, doch glaube ich, dass es für dieses Dilemma eine Lösung gibt, die all unsere Sorgen beseitigen wird.", rewards = "Ihr bekommt:\n\n"},
[4186] = {title = "Die wahren Meister", objective = "Händigt Bolvars Erlass an Magistrat Solomon in Seenhain aus.", description = "Ich ernenne Euch hiermit zum kommissarischen Deputy von Stormwind, <Name>.\n\nKehrt zu Magistrat Solomon in Seenhain zurück und übergebt ihm diesen Erlass.", progress = "Irgendwelche Neuigkeiten von Bolvar?", completion = "Es hätte noch schlimmer kommen können, denke ich...\n\n&lt;Magistrat Solomon betrachtet Euch eingehend.&gt;\n\nEs scheint, als würde Seenhains Schicksal nun allein auf Euren Schultern lasten.\n\n&lt;Ihr bemerkt, dass Magistrat Solomon heftig blinzelt. Er scheint zu weinen.&gt;", rewards = "Ihr bekommt:\n\n"},
[4201] = {title = "Der Liebestrank", objective = "Bringt 4 Gromsblut-Kräuter, 10 Riesensilbervenen und Nagmaras gefüllte Phiole zu Herrin Nagmara in den Blackrocktiefen.", description = "Oh, wie schmerzhaft doch die Liebe ist! Mein geliebter Gefreiter Rocknot ist immun gegen meinen Charme. Er verschmäht mich! Es ist zum Verrücktwerden!\n\nIhr müsst mir helfen! Wir Sukkubi wissen viel über die Liebe und ich kann einen Trank herstellen, der den eisernen Panzer um Rocknots Herz erweichen könnte. Dazu benötige ich folgende Dinge: das Kraut Gromsblut, Riesensilbervenen von den Klippenriesen Azsharas sowie Wasser aus dem Golakka-Quellen-Krater in Un'Goro. Ihr könnt das Wasser in diese Phiole füllen.\n\nBitte, <Name>, verhelft einer armen Seele zum Glück!", progress = "Habt Ihr die Zutaten? Die Leere in meinem Herzen verschlingt mich noch!", completion = "Oh, Ihr habt es geschafft! Jetzt kann ich meinen Trank brauen und ihn Rocknot geben. Endlich wird er meinem Charme verfallen!\n\nIch danke Euch, &lt;Name&gt;. Ihr seid ein wahrer Verfechter der Liebe!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHandfessel-ManschettenNagmaras Peitschen-Gürtel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[4221] = {title = "Verderbte Windblüte", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[4222] = {title = "Verderbte Windblüte", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[4223] = {title = "Die wahren Meister", objective = "Sprecht mit Marshal Maxwell in der brennenden Steppe.", description = "<Magistrat Solomon seufzt.>\n\nIhr müsst in die brennende Steppe zurückkehren, <Name>. Als Deputy von Stormwind erwartet man von Euch, dass Ihr Euch bei Marshal Maxwell meldet. Viel Glück.", progress = nil, completion = "&lt;Marshal Maxwell lacht.&gt;", rewards = "Ihr bekommt:\n\n"},
[4224] = {title = "Die wahren Meister", objective = "Sprecht mit dem struppigen John, um etwas über Marshal Windsors Schicksal zu erfahren, und kehrt dann zu Marshal Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt.\n\nIhr erinnert Euch daran, dass Marshal Maxwell Euch geraten hat, ihn in einer Höhle im Norden zu suchen.", description = "Was? Ihr dachtet, Ihr wärt der Erste? Wie viele Soldaten müssen wir noch verlieren, bevor Stormwind handelt?\n\nWir hatten riesige Mengen an Informationen über die Blackrockbedrohung zusammengetragen, doch dann verloren wir unseren befehlshabenden Offizier, Marshal Windsor. Zusammen mit Marshal Windsor gingen auch all unsere wertvollen Informationen verloren.\n\nWas wir brauchen, ist diese Dokumentation. Sprecht mit dem struppigen John, <Name>. Er war mit Windsor zusammen, als sie von einem Stoßtrupp der Blackrock überfallen wurden. Er wurde zuletzt in einer Höhle im Norden gesehen.", progress = "Habt Ihr schon mit John gesprochen?", completion = "Ich hätte Euch warnen können, aber das wäre nur der halbe Spaß gewesen.", rewards = "Ihr bekommt:\n\n"},
[4241] = {title = "Marshal Windsor", objective = "Reist zum Blackrock im Nordwesten und dann weiter zu den Blackrocktiefen. Findet heraus, was aus Marshal Windsor geworden ist.\n\nIhr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt.", description = "Dieser nichtsnutzige Feigling behauptet also, Windsor sei noch am Leben, was?\n\nMacht Euch bereit, Deputy, Ihr werdet ausziehen, um ihn zu suchen. Falls Windsor noch am Leben ist, müsst Ihr ihn zurückholen. Sollte er tot sein, brauche ich einen Beweis dafür.\n\n<Maxwell lacht.>\n\nIch wette, das könnt Ihr langsam schon nicht mehr hören, was?", progress = nil, completion = "Wo ist er? Ich bringe ihn um!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4242] = {title = "Verlorene Hoffnung", objective = "Überbringt Marshal Maxwell die schlechten Neuigkeiten.", description = "Bolvar ist ein Dummkopf. Ich war gerade dabei, ihm seinen kostbaren 'Beweis' zu beschaffen, um ihm diesen in den Hals stopfen zu können.\n\nEr ist ein blinder Blödmann. Selbst wenn der Beweis ihn in die Nase beißt, würde er ihn nicht sehen.\n\nWas meine Informationen angeht, die sind verloren. Unwiderbringlich.\n\nSollte ich Ironfoe jemals finden und es aus diesem Labyrinth herausschaffen, wird mein erster Halt Stormwind sein, damit ich diesem Reptil meinen Hammer über den Schädel ziehen kann.\n\nGeht jetzt, <Name>.", progress = nil, completion = "Er ist offensichtlich verrückt geworden.\n\n&lt;Maxwell senkt sorgenvoll den Kopf.&gt;\n\nEs ist bedauerlich, dass ein einst so stolzer und edler Krieger zu solch einem kompletten Schwachkopf mutiert ist. Ich schätze, wir sind in einer Sackgasse...\n\nDennoch muss ich Euch für Eure bisherigen Bemühungen entlohnen, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKonservator-HelmSchildplattensabatonsScherwindgamaschen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[4243] = {title = "Chasing A-Me 01", objective = "Sucht im Un'Goro Krater nach A-Me 01.", description = "Irgendetwas muss meiner bislang besten Erfindung zugestoßen sein. Ihr habt doch schon mal mechanische Eichhörnchen gesehen, richtig? Tja, um näher an die Affen des Un'Goro Kraters heranzukommen, habe ich eine mechanische Äffin geschaffen, die sich unbemerkt unter sie mischen kann - ich nenne sie A-Me 01.\n\nSie hat Wahrsagesteine als Augen, so konnte ich alles sehen, was auch sie sah. Den Fungal Rock hat sie wohlbehalten erreicht - das ist das Versteck der Affen, gleich nördlich von hier. Und dort habe ich dann den Kontakt zu ihr verloren. Das Letzte, was ich sah, war eines der Alphamännchen, das auf sie zugestürmt kam, um sie zu begrüßen!\n\nKönntet Ihr mir wohl helfen, sie zu finden?", progress = nil, completion = "Als Ihr A-Me 01 eingehend betrachtet, entdeckt Ihr zwei gewaltige Beulen, die Karnas Meisterwerk der Ingenieurskunst verunzieren. Eine Beule befindet sich an der Schulter von A-Me 01, die andere an ihrem Kopf.\n\nDurch ihre Bauteile scheint kein Strom zu fließen, wie Ihr nach weiterer Untersuchung feststellt.", rewards = "Ihr bekommt:\n\n"},
[4244] = {title = "Chasing A-Me 01", objective = "Sucht ein Mithrilgehäuse und bringt es zu A-Me 01 im Un'Goro Krater.", description = "Ihr setzt Eure Untersuchungen fort und findet eine Abdeckung, die sich aufschieben lässt. Oberhalb der Verkabelung steht in gut lesbarer Schrift geschrieben: 'Mithrilgehäuse ersetzen und Strom erst ausschalten, dann einschalten.'\n\nEs dauert einen Moment, bis Ihr die Abdeckung wieder angebracht habt, und Ihr fragt Euch, ob es wirklich so einfach ist, A-Me 01 zu reparieren und zurück zu Karna Remtravel in der Nähe von Marshals Zuflucht zu bringen.\n\nTja, probieren geht über studieren ...", progress = "Die Abdeckung, in die das Mithrilgehäuse gehört, ist immer noch verschlossen. Der Rest von A-Me 01 bleibt reglos.", completion = "Ihr entfernt wieder die Abdeckung im Rücken von A-Me 01 und nehmt das alte Mithrilgehäuse heraus, das offensichtlich durchgebrannt ist. Das neue klickt problemlos an seinen Platz. Vorausgesetzt, das Mithrilgehäuse war die Ursache des Problems, müsst Ihr jetzt nur noch den Schalter auf 'Aus' und dann wieder auf 'Ein' stellen.", rewards = "Ihr bekommt:\n\n"},
[4245] = {title = "Chasing A-Me 01", objective = "Begleitet A-Me 01 zu Karna Remtravel im Un'Goro Krater.", description = "Nachdem Ihr Euch vergewissert habt, dass Ihr bereit seid, A-Me 01 zu Karna Remtravel zurückzubringen, knipst Ihr den Schalter auf 'Aus'. Ihr seht Euch nochmals um, um sicherzugehen, dass sich keine Gorillas nähern, und fragt Euch, was wohl geschieht, wenn Ihr den Schalter wieder auf die 'Ein'-Position stellt.\n\nDas ist Eure letzte Chance ... wollt Ihr das wirklich tun?", progress = nil, completion = "Oh, Ihr habt es geschafft! Großartig! Ich danke Euch, &lt;Name&gt;.\n\nOh, meine arme A-Me. Diese Beulen, oh nein! Aber mit Geduld und Spucke werden wir sie im Handumdrehen wieder voll funktionsfähig haben.\n\nNochmals danke, &lt;Name&gt;. Ich weiß das wirklich zu schätzen.", rewards = "Ihr bekommt:\n\n"},
[4261] = {title = "Alter Geist", objective = "Bringt Arei in Sicherheit und sprecht dann mit Kayneth Stillwind in Forest Song, im Osten von Ashenvale.", description = "Der Teufelswald war einst ein friedliches und ruhiges Land... bis die Legion hier eingefallen ist. Die Höllenbestien, Zerstörung, Chaos...\n\nDer Schädel des Gul'dan hat dafür gesorgt, dass hier niemand ungeschoren davonkam. Alles fiel der Verderbnis zum Opfer.\n\nSogar jetzt, da ich ein Geist bin, bin ich immer noch gefangen und muss die Leiden dieses Landes ertragen. Helft mir, den Weg nach Hause zu finden. Bitte, <Name>, sagt mir, dass Ihr einen alten Geist weg von hier führen werdet, dorthin, wo ich endlich ruhen kann.\n\nSobald ich frei sein werde, solltet Ihr Kayneth Stillwind aufsuchen, einen Druiden, der in Forest Song im Osten lebt.", progress = nil, completion = "Ja, &lt;Name&gt;. Der Teufelswald hat eine Menge durchgemacht. Vielen Dank für Eure Mühen.\n\nEines Tages werden wir den Teufelswald den Klauen der Verderbnis entreißen können. Jede gute Tat trägt dazu bei.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAstralnebelcapeMantel des Wolkengestöbers\n\nIhr bekommt außerdem:\n\n"},
[4262] = {title = "Übermeister Pyron", objective = "Erschlagt Übermeister Pyron und kehrt dann zu Jalinda Sprig zurück.\n\nIhr erinnert Euch an Jalindas Worte, dass Pyron den Steinbruch bewachen würde. Vielleicht solltet Ihr dort nachsehen?", description = "Die letzten fünf meiner Magier, die ausgezogen waren, um sich auf dem Blackrock umzusehen, kamen knusprig geröstet zurück, mit einem dauerhaften orangefarbenen Gnomen-Afro - oder noch schlimmer.\n\n<Jalinda nimmt etwas Asche vom Boden auf und lässt sie vom Wind davontragen.>\n\nEin besonders mieses Individuum, Übermeister Pyron, scheint hier eine Menge Ärger zu verursachen. Dieser Elementar muss vernichtet werden, damit unser Expeditionsteam in die Blackrocktiefen reisen kann!\n\nEr bewacht den Eingang am Blackrocksteinbruch.", progress = nil, completion = "Incendius? Oje...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4263] = {title = "Incendius!", objective = "Sucht Lord Incendius in den Blackrocktiefen und vernichtet ihn!", description = "Seid Ihr sicher, dass Pyron 'Incendius' sagte, als er starb?\n\n<Jalinda schluckt schwer.>\n\nLord Incendius soll angeblich einer von Ragnaros Dienern sein! Oje, oje... was sollen wir jetzt nur tun?\n\nMeint Ihr, Ihr könntet noch eine weitere Mission bewältigen? Ich habe niemand anderen, den ich schicken könnte, <Name>!\n\nWir werden niemals eine Gruppe hineinbringen, solange Incendius Pyron aus der Asche immer wieder neu erstehen lässt.\n\nIhr müsst Lord Incendius suchen und vernichten!", progress = nil, completion = "Oje! Seid Ihr sicher, dass Incendius 'Ragnaros' sagte?\n\n&lt;Jalinda gibt Euch etwas und tätschelt Euer Handgelenk, während sie tief in Gedanken versinkt.&gt;", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSonnentuchcapeNachtlauerhandschuheGruftdämonen-ArmschienenWackere Umklammerung\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[4264] = {title = "Eine zusammengeknüllte Notiz", objective = "Soeben seid Ihr auf etwas gestoßen, das Marshal Windsor mit Sicherheit sehr interessiert. Vielleicht besteht ja doch noch Hoffnung.", description = "Die Notiz ist mit Flecken übersät. Der Text ist kaum noch lesbar, aber Ihr könnt Folgendes erkennen:\n\n... süße Ironie...\n\n... der Sturz der zerbrochenen Allianz...\n\n... ohne General Angerfords Sorgfalt hätten wir das Schema der Verschlüsselung niemals herausgefunden...\n\n... Argelmach hat Windsors Notizen fast entschlüsselt.\n\nUnser Lord wird sich aus den Tiefen erheben und alle zerschmettern, die noch übrig sind...\n\nImperator Dagran Thaurissan", progress = "<Marshal Windsor betrachtet die Notiz in Eurer Hand.>\n\nWas bringt Ihr mir da, <Name>?", completion = "&lt;Marshal Windsor nimmt die Notiz und beginnt zu lesen.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4265] = {title = "Flucht aus dem Schwarmbau", objective = "Begleitet Raschal sicher aus dem Schwarmbau der Zukk'ash hinaus.\n\nKehrt zu Ginro Hearthkindle in der Festung Feathermoon zurück und lasst ihn wissen, dass Raschal am Leben ist und dass es ihm gut geht.", description = "Die Kapsel platzt auf, als Ihr sie berührt, und zum Vorschein kommt ein Nachtelf, der überraschenderweise noch am Leben ist. Er scheint bei guter Gesundheit zu sein, ist jedoch sehr benommen. Als Ihr ihm aus der Kapsel heraushelft, regt sich Leben in ihm.\n\n\"Elune sei Dank! Ihr habt mich gerettet! Ich... Mein Name ist Raschal. Ich erwachte völlig gelähmt in dieser Kapsel, nachdem mich diese Käfer überwältigt hatten. Wurdet Ihr von der Festung geschickt?\"\n\nAnscheinend habt Ihr den vermissten Kurier gefunden!", progress = nil, completion = "Willkommen daheim, &lt;Name&gt;. Raschal hat mich vor kurzem aufgesucht und erzählt, was ihm zugestoßen ist.\n\nIch... nein, die gesamte Festung kann Euch gar nicht genug für Eure großartige Tat danken. Raschal wäre ohne Euer rechtzeitiges Einschreiten jetzt tot und Ihr habt uns geholfen, ohne auch nur den Hauch eines Söldnerlohns dafür zu verlangen. Ihr tragt das Zeichen eines wahren Helden. Wisset, dass Ihr in Ginro Hearthkindle einen Freund fürs Leben gefunden habt.", rewards = "Ihr bekommt:\n\n"},
[4266] = {title = "Der Empfang eines Helden", objective = "Sprecht mit Shandris Feathermoon in der Festung Feathermoon.", description = "<Name>, General Shandris Feathermoon möchte unter vier Augen mit Euch sprechen. Sie möchte Euch bestimmt für Eure Dienste zum Wohle der Festung danken, aber ich weiß auch, dass sie außerdem mit Euch über diese Insektenwesen sprechen will, auf die Ihr und Raschal im Süden von Feralas gestoßen seid. Die Berichte, die diese Insekten der Zukk'ash betreffen, sind ... mehr als beängstigend.\n\nGeneral Feathermoon wartet im Haupttruppenlager auf Euch.", progress = nil, completion = "&lt;Name&gt;, meinen allerherzlichsten Dank für Eure Hilfe. Eure Tapferkeit angesichts widrigster Umstände verlangt nach einer Belohnung, die tausend Mal größer ist. Ich hoffe dennoch, dass Ihr dies im Namen der gesamten Festung annehmt.\n\nUnd jetzt, wenn Ihr gestattet ... Ich möchte Euch um einen weiteren Gefallen bitten. Angesichts der Entdeckung des Schwarmbaus der Zukk'ash hier in Feralas denke ich, dass Ihr die richtige Wahl für diese Mission seid.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZeremonielle ElfenklingeScheinheilige Rute\n\nIhr bekommt außerdem:\n\n"},
[4267] = {title = "Aufstieg der Silithid", objective = "Bringt Raschals Bericht zu Gracina Spiritmight in Darnassus.", description = "Ich vertraue Euch eine Kopie des Berichts an, den Raschal über die Plage im Südosten Feralas angefertigt hat. Der eigentliche Bericht befindet sich in den Akten in Darnassus, aber ich möchte, dass Ihr diese Kopie an eine Vertraute des Protektorats überbringt. Ihr Name lautet Gracina Spiritmight. Sie ist eine Priesterin, die im Tempel des Mondes in Darnassus lebt. Sie verfügt über großes Wissen, solche Kreaturen betreffend, und wenn sie diesen Bericht erhalten würde, käme es uns allen sehr zugute.\n\nMacht Euch auf den Weg, und viel Glück, <Name>. Möge Elune über uns alle wachen.", progress = "Willkommen in diesem gesegneten Tempel. Die Festung Feathermoon hat mich über Euer Kommen informiert. Habt Ihr den Bericht, den Shandris Feathermoon Euch gebeten hat mir zu bringen?", completion = "Wir Nachtelfen wissen um den Schrecken, von dem in diesem Bericht die Rede ist. Shandris hat gut daran getan, dies und Euch zu mir zu schicken.\n\nDiese Kreaturen werden Feralas schnell verzehren; sie stellen so ziemlich die größte Bedrohung dar, der wir uns je gegenübersehen werden. Die Insekten, auf die Ihr und der Kurier gestoßen seid, sind als Silithiden bekannt. Sie sind die Werkzeuge der größten Bedrohung, der sich die Horde und die Allianz gegenübersehen.\n\nIch bete darum, dass wir die Entschlossenheit besitzen, sie zu besiegen, bevor sie uns vernichten.", rewards = "Ihr bekommt:\n\n"},
[4281] = {title = "Thalanaar-Lieferung", objective = "Bringt das nicht ausgelieferte Paket zu Falfindel Waywarder in Thalanaar.", description = "Dieses Paket mit Waren, das Ihr in den Lagern der Waldpfotengnolle gefunden habt, war für den kleinen Streckenposten Thalanaar im Südosten Feralas' bestimmt. Das Paket, ungeachtet des Schicksals des vermissten Kuriers, harrt immer noch der Auslieferung.\n\nIhr untersucht das Paket genauer und entdeckt den Namen 'Falfindel Waywarder' handschriftlich auf der Verpackung vermerkt. Vielleicht ist er der eigentliche Empfänger des Pakets.", progress = "Willkommen in Thalanaar, <Klasse>. Kann ich Euch irgendwie behilflich sein?", completion = "Elune sei gepriesen, die Lieferung von der Festung Feathermoon ist endlich eingetroffen!\n\nEure Anwesenheit hier sagt mir, dass Raschal, unseren eigentlichen Kurier, wohl ein böses Schicksal ereilt hat. Ich hoffe, dass sich alles zum Guten wenden wird. Ich weiß, dass die Waldpfoten seit kurzem wegen irgendetwas, das sich südlich von ihnen ereignet hat, äußerst aufgebracht sind. Vielleicht ist er dort der Wildnis zum Opfer gefallen. Ich an Eurer Stelle wäre vorsichtig.\n\nNun denn, nochmals danke. Hier ist Eure Entlohnung für die Auslieferung des Pakets.", rewards = "Ihr bekommt:\n\n"},
[4282] = {title = "Ein Funken Hoffnung", objective = "Holt Marshal Windsors verloren gegangene Informationen zurück.\n\nMarshal Windsor glaubt, dass sich die Informationen in den Händen des Golemlords Argelmach und des Generals Zornesschmied befinden.", description = "<Marshal Windsor wedelt aufgeregt mit der Notiz herum.>\n\nWisst Ihr, was das bedeutet, <Name>?\n\nVielleicht ist doch noch nicht alles verloren! Soweit ich das erkennen kann, wird die Information von zwei Dunkeleisenzwergen verwahrt: General Zornesschmied und dem Golemlord Argelmach. Ich habe das Gefühl, als würden sie die Information nicht einfach so herausrücken, wenn wir sie freundlich darum bitten.\n\nAlso hoffe ich, dass Ihr auf einen Kampf vorbereitet seid.\n\nZieht aus und findet die beiden Bösewichte! Vernichtet sie und bringt mir meine verloren gegangenen Informationen zurück.", progress = "Schon bald wird es mit dieser grandiosen Täuschung ein Ende haben.", completion = "&lt;Marshal Windsor reißt die zwei Schrifttafeln aus Eurer Hand.&gt;\n\nWir müssen hier raus!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4283] = {title = "FÜNFZIG! Jawoll!", objective = "Oralius will 50 Medaillons der Blackrock haben. Die Chancen stehen gut, dass man die Medaillons bei den Orcs in der brennenden Steppe findet.", description = "Ich werde Euch ein kleines Geheimnis verraten, Soldat: Kommt näher.\n\nICH BIN HIER DER EINZIGE, DER NOCH BEI VERSTAND IST!\n\nSeht Euch nur all diese Leute an! Ist es zu fassen, dass sie alle irre sind!? Oh ja, das sind sie! DURCHGEDREHT! WAHNSINNIG!\n\n<Oralius senkt die Stimme.>\n\nDas bleibt aber unter uns: mir, Euch und meinem Kumpel Käpt'n Winky.\n\n<Oralius greift in die Luft und drückt zu.>\n\nWie auch immer ... Ich sammle Abzeichen, die gut zu meiner Sammlung Ogerohren passen. Orcs sind der letzte Schrei. Fünfzig. LOS!\n\n<Oralius stößt in ein Horn.>\n\nAB DAMIT!", progress = "<Oralius spricht mit einem ziemlich großen, abgetrennten Ogerohr.>\n\nBrennende Steppe an Zentrale. Zentrale, bitte kommen.", completion = "Ihr habt es geschafft! Und das ist Eure Belohnung: STREICHELT MEINEN BAUCH! LOS DOCH! STREICHELT IHN!", rewards = "Ihr bekommt:\n\n"},
[4284] = {title = "Machtkristalle", objective = "Sammelt 7 Machtkristalle von jeder Farbe: rot, blau, gelb und grün. Bringt sie zu J. D. Collie in Marshals Zuflucht.", description = "Ich bin sicher, Ihr habt sie bemerkt, <Name>. Sie sind überall!\n\nWovon ich rede? Na, von den Kristallen natürlich!\n\nDie Kristalle... Sie liegen überall im Krater herum. Die meisten Leute ignorieren sie, aber ich habe das seltsame Gefühl, als besäßen sie eine gewisse Macht. Ich habe eine Weile mit ihnen herumexperimentiert, aber ich habe noch nichts herausgefunden. Tja, bis jetzt jedenfalls.\n\nAber hört mal, mir gehen langsam die Kristalle aus - meint Ihr, Ihr könntet noch ein paar für mich sammeln?", progress = "Ich weiß, dass ich hier irgendetwas auf der Spur bin, <Name>!", completion = "Jetzt werde ich meine Experimente fortsetzen! Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[4285] = {title = "Der Nordpylon", objective = "Findet den Standort des nördlichen Kristallpylonen im Un'Goro Krater.", description = "Wofür die wohl gut sind? Ich muss ständig daran denken!\n\nEs macht mich verrückt, dass all die Gerüchte über die Kristallpylonen wahr sind. Nennt mich leichtgläubig, aber ich glaube gewöhnlich, was mir die Leute erzählen.\n\nWie dem auch sei, ich habe gehört, dass sich einer dieser Kristallpylonen hier ganz in der Nähe befinden soll. Irgendwo im Norden ... Sucht ihn doch bitte, <Name>. Ich weiß genau, dass es die Dinger gibt.", progress = nil, completion = "Ich weiß, dass die Geschichten wahr sind, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[4286] = {title = "Feine Sachen", objective = "Reist in die Blackrocktiefen und holt 20 Dunkeleisengürteltaschen. Kehrt zu Oralius zurück, sobald die Aufgabe erledigt ist. Ihr nehmt an, dass die Dunkeleisenzwerge in den Blackrocktiefen diese 'Gürteltaschen'-Dinger tragen.", description = "Käpt'n Winky sagt mir, dass die Dunkeleisenzwerge in den Tiefen das ganze gute Zeug haben. Stimmt's nicht, Winky?\n\n<Oralius versucht, so gut es geht, einen Piraten zu imitieren.>\n\nHARRR, KUMPEL! DAS STIMMT!\n\nDa hört Ihr's. Ihr müsst Euch dorthin begeben und mir etwas von dem guten Zeug besorgen.\n\nGeht da rein und holt es Euch!", progress = "Ich kann jetzt nicht, <Name>. Ich und Winky müssen zu einer Konferenz.", completion = "&lt;Oralius beginnt, in den hoch aufgetürmten Gürteltaschen herumzuwühlen.&gt;\n\nOH, WUNDERBAR!\n\n&lt;Oralius steckt seine lange Nase in den Berg und nimmt einen tiefen Atemzug.&gt;\n\nKÖSTLICH! Seht Euch nur all die schönen Sachen an!\n\nDa, nehmt Euch auch so'n Ding, &lt;Name&gt;. Es sind genug davon da.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nEine schmuddelige Gürteltasche"},
[4287] = {title = "Der Ostpylon", objective = "Findet den Standort des östlichen Kristallpylonen im Un'Goro Krater.", description = "Während meines Aufenthaltes hier sind mir seltsame Gerüchte über rätselhafte Pylonen zu Ohren gekommen, die es angeblich draußen in der Wildnis des Kraters geben soll, <Name>. Ich nehme an, sie sind ziemlich groß, mit Kristallen an den Innenseiten.\n\nIch habe zwar noch nie welche gesehen, aber ich komme nicht umhin zu glauben, dass die Gerüchte wahr sind - und dass die Pylonen irgendetwas mit all den Kristallen zu tun haben, die wir gefunden haben.\n\nAlso, warum helft Ihr mir nicht, meine Neugier zu stillen? Angeblich soll es einen im östlichen Teil des Kraters geben. Meint Ihr, Ihr könntet ihn finden?", progress = nil, completion = "Un'Goro ist ein sehr seltsamer Ort, &lt;Name&gt;. Wenn man den Krater betritt, kommt es einem so vor, als wäre man in einer ganz anderen Welt...", rewards = "Ihr bekommt:\n\n"},
[4288] = {title = "Der Westpylon", objective = "Findet den Standort des westlichen Kristallpylonen.", description = "Meine Experimente haben bis jetzt noch keine positiven Ergebnisse erzielt, <Name>. Ich kann nur hoffen, dass Ihr eine Lösung findet, indem Ihr einen der Pylonen entdeckt, von denen ich gehört habe.\n\nWas, wenn wir bestimmte Farben mit ihnen kombinieren würden ... ach, eines nach dem anderen. Zuerst müssen wir sie finden!\n\n<Name>, sucht im westlichen Teil des Kraters. In diesem Gebiet soll sich irgendwo ein Pylon befinden.", progress = nil, completion = "Entlang der Ränder des Kraters gibt es viele verborgene Bereiche. Erkundet die gewundenen Pfade, wenn Ihr nicht mehr wisst, wo Ihr noch suchen sollt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[4289] = {title = "Die Affen von Un'Goro", objective = "Bringt Torwa Pathfinder am Eingang zum Un'Goro Krater 2 Un'Goro-Gorillapelze, 2 Un'Goro-Stampferpelze und 2 Un'Goro-Donnererpelze.", description = "In diesem Krater gibt es viele seltsame Kreaturen - sie scheinen edler zu sein als ihre Verwandten, die man überall in meinem Heimatland und jenseits davon findet. Ich habe keine Erklärung dafür, aber dieser Ort trägt die Handschrift der Erdenmutter. Immer, wenn ich auf eines ihrer wundervollen Geschöpfe in diesem Krater stoße, erweise ich ihr meine Ehrerbietung.\n\nWenn auch Ihr diese Erleuchtung spüren möchtet, die eine solche Tat begleitet, dann geht nach Norden. Dort findet Ihr große Affen, die die Kraft eines jeden Sterblichen auf eine harte Probe stellen. Bringt mir ihre Pelze ... beweist mir Eure Kraft.", progress = "Haben Euch die Kreaturen hier bereits besiegt, <Name>?\n\nLasst Euch doch nicht so leicht entmutigen. Die Un'Goro-Affen aufzuspüren und sie zu besiegen ist keine einfache Aufgabe, auch nicht für einen großen Jäger.", completion = "Ihr habt also Eure Kraft bewiesen und dass Ihr kräftig genug seid, um sogar die großen Affen von Un'Goro zu besiegen - das ist gut. Im Vergleich zu Lar'korwi war das zwar nur eine kleine Herausforderung, aber ich will Euch Euren großen Sieg nicht nehmen.\n\nDiese Pelze werden herrliche Kleidung für meinen Stamm abgeben. Ihr habt mir geholfen und Euch als würdig erwiesen.\n\nBevor Ihr Euch einer anderen Aufgabe annehmt, lasst uns noch der Erdenmutter huldigen und den Geistern der Affen danken, die Ihr getötet habt, damit sie wissen, dass ihr Tod nicht umsonst gewesen ist.", rewards = "Ihr bekommt:\n\n"},
[4290] = {title = "Lar'korwis Mahl", objective = "Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes; kehrt dann zu Torwa Pathfinder im Un'Goro Krater zurück.", description = "Einst, vor sehr langer Zeit, stahl einer meiner Brüder ein Stück Fleisch aus Lar'korwis Jagdbeute. Damals wusste er es nicht, aber Lar'korwi hat ihn vom Wald aus beobachtet. Lar'korwi folgte meinem Bruder tagelang und vernichtete alles, was er berührte. Mein Bruder, von Angst erfüllt, entschloss sich schließlich, aus dem Krater zu fliehen, um Lar'korwi zu entkommen.\n\nLar'korwi tötete ihn, nicht weit von dieser Stelle entfernt.\n\nWenn Ihr Lar'korwi provozieren wollt, sucht nach seiner letzten Jagdbeute und stehlt ihm etwas Fleisch.\n\nKommt dann zu mir zurück.", progress = "Hört auf meine Worte, <Name>. Wenn Ihr Euch dieser Kreatur wirklich stellen wollt, dann müsst Ihr vorsichtig sein... und klug. Es bedarf viel Kraft und Kenntnis, um Lar'korwi aus der Reserve zu locken und zu besiegen.", completion = "Das dürfte reichen, &lt;Name&gt;. Mir scheint, Lar'korwi scheint dieser Tage gut zu speisen. Allerdings stellt sich mir dabei die Frage, wo er in dieser Gegend einen Dreschadon gefunden haben könnte. Merkwürdig.\n\nWie auch immer, ich werde das behalten, bis Ihr für eine Konfrontation mit der Bestie bereit seid. Macht Euch keine Sorgen um meine Sicherheit - ich bin mir gewiss, Ihr habt Lar'korwi wütend genug gemacht, dass er mich in Ruhe lässt, bis er Euer Fleisch gekostet hat.", rewards = "Ihr bekommt:\n\n"},
[4291] = {title = "Lar'korwis Fährte", objective = "Bringt Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater 2 Ravasaurus-Pheromondrüsen.", description = "Ich bin wirklich erstaunt, dass er noch nicht hinter Euch her ist, <Name>. Alles läuft jedoch gut, denn ich habe einen letzten Plan, mit dem wir das Monster zu uns locken können.\n\nAls dominantem Männchen steht es Lar'korwi zu, sich mit jedem Weibchen zu paaren, das ihm gefällt - und ihm gefallen viele. Westlich von hier werdet Ihr eine Menge Ravasaurus-Eier finden. Tretet dicht an sie heran, um damit einen Angriff seiner Artgenossen zu provozieren. Die Weibchen produzieren in einer Drüse an ihrem Kopf einen abscheulichen Gestank, der die Männchen wissen lässt, dass sie paarungsbereit sind. Bringt mir zwei dieser Drüsen.", progress = "Seid vorsichtig, <Name>. Wenn Ihr Euch einem Gelege mit Eiern nähert, wird das die Mütter garantiert provozieren... selbst wenn Ihr bereits eine dieser Drüsen habt. Die Mütter können genauso tödlich sein wie Lar'korwi selbst, wenn sie kämpfen, um ihre Jungen zu beschützen. Aber wenn Ihr Erfolg habt, haben wir definitiv das Mittel, um Lar'korwi aus seinem Versteck zu locken.", completion = "Ah, sehr schöne Exemplare, &lt;Name&gt;. Die zwei Teile, die Ihr gefunden habt, eignen sich perfekt, um Lar'korwi zu ködern. Ich kann es kaum erwarten, den Ausgang des Kampfs zwischen Euch und dem Monster zu sehen. Es ist ein riesiges Ungetüm mit Klauen so scharf wie die edelsten Klingen. Wenn Ihr ihm in die Augen seht, blickt Ihr direkt in das Antlitz des Todes.", rewards = "Ihr bekommt:\n\n"},
[4292] = {title = "Ein Köder für Lar'korwi", objective = "Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater.", description = "Das hier wird der schwierigste Teil werden, denn der Plan ist etwas kompliziert. Nördlich von hier findet Ihr einen kleinen Pfad, der in die Berge hinaufführt. Dort habe ich Lar'korwi zuletzt gesehen. Ihr werdet wissen, dass Ihr im richtigen Gebiet seid, wenn Ihr all die Knochen der großen Kreaturen findet, die es dort einst gab. Nehmt das Fleisch, das Ihr Euch besorgt habt, und legt es dort ab. Reibt das Fleisch dann mit der Drüse ein. Wenn es mit beiden Lockmitteln zusammen nicht gelingt, Lar'korwi zu Euch zu locken, dann weiß ich auch nicht weiter.", progress = "Lasst Euch nicht von Furcht überwältigen, <Name>. Es gibt keinen größeren Verräter als Furcht... Ihr müsst stark bleiben!\n\nNehmt das Fleisch, legt es in dem kleinen Tal ab und reibt es dann mit der Drüse ein. Nur so wird der Tod zu Euch kommen.", completion = "Gelobt sei die Erdenmutter! Ihr habt es geschafft! Hut ab, &lt;Name&gt;. Ihr habt Euch wahrlich als großartiger Jäger bewiesen. Euer Geist ist stark. Eure Tapferkeit unerreicht. Und Eure Kraft ist noch gewachsen. Ich verbeuge mich vor Eurer Fertigkeit.\n\nNur die größten meiner Vorfahren hätten etwas so Unglaubliches bewerkstelligen können. Herzlichen Glückwunsch.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nEbenenpirschertunikaVorhut-Gamaschen\n\nIhr bekommt außerdem:\n\n"},
[4293] = {title = "Eine Brühschleimerprobe...", objective = "Sammelt Teufelswaldschleimproben von den Brühschlammern im Teufelswald. Verwendet dann die Testausrüstung neben Chemiker Fuely in Undercity, um zu sehen, welche Eurer Proben am verderbtesten sind. Bringt 5 der verderbten Teufelswaldproben, die Ihr findet, zu Chemiker Fuely.", description = "Der Teufelswald ist ein Wald weit im Norden des Brachlandes, sogar noch weiter weg als Ashenvale. Dort kann man an durch die Berührung von Fel gesegneten Teichen überall Brühschlammer finden. Die Geißel hat mit den Angriffen von Höllenbestien und anderer Dämonenmagie die Gegend stark verwüstet - die Brühschlammer sind angeblich während dieser Angriffe aus der Erde an die Oberfläche gekrochen.\n\nSammelt einige Proben von Teufelswaldbrühschlammern, dann verwenden wir die Testausrüstung hier neben mir, um eine Kontrollgruppe zusammenzustellen, mit der wir die anderen Proben, die Ihr einsammelt habt, vergleichen können.", progress = "Für unsere Kontrollgruppe brauche ich mindestens fünf verderbte Proben, <Name>. Sammelt weiter Teufelswaldschleimproben, bis Ihr mir das geben könnt, was wir brauchen. Lady Sylvanas hat es verfügt...", completion = "Ah, wunderbar. Diese Proben sind genau richtig. Ich danke für Eure Hilfe.\n\nSobald wir alle Brühschleimerproben zusammenhaben, können wir mehr sagen. Langsam fange ich an zu glauben, dass Lady Sylvanas mit ihrer Ahnung nicht nur Recht hatte, sondern dass diese auch noch mit mehr Einsicht gesegnet war, als sogar sie gedacht hätte. Diese Proben sind sehr interessant. Allein zu sehen, wie sie auf meine Präparate reagiert haben ... hmm, ja, ganz zweifellos müssen wir noch weitere Untersuchungen anstellen.", rewards = "Ihr bekommt:\n\n"},
[4294] = {title = "...und eine Menge Brühschlammer", objective = "Sammelt Un'Goro-Brühschleimerproben von jedem der Brühschleimer im Un'Goro Krater. Verwendet dann die Testausrüstung neben Chemiker Fuely in Undercity, um zu sehen, welche Eurer Proben am reinsten sind. Bringt 5 der reinen Un'Goro-Proben, die Ihr findet, zu Chemiker Fuely.", description = "Habt Ihr schon einmal vom Un'Goro Krater gehört, <Name>? Er liegt in der Nähe der Tanariswüste und es ist ein großartiger Ort: üppig, von Leben sprühend, voller Kreaturen und Pflanzen.\n\nDorthin müsst Ihr Euch begeben. Ich habe mir sagen lassen, dass der Krater noch völlig unbesudelt und frei von Einflüssen von außen sei. Erst jetzt beginnen Forscher, seine Geheimnisse zu entdecken.\n\nIch würde die dortigen Brühschleimer und Brühschlammer gern testen. Wenn es stimmt, dass sie nicht verderbt sind, dann würde ich gern wissen, wie sich solche Kreaturen entwickelt haben.", progress = "Ja, <Name>? Wie läuft Eure Suche?", completion = "Einfach erstaunlich, &lt;Name&gt;. Dieser Un'Goro Krater birgt wesentlich mehr Geheimnisse als ich dachte. Ich frage mich, was wir noch alles entdecken werden, wenn wir unsere Tests fortsetzen.\n\nWirklich erstaunlich... seht Euch nur an, wie rein diese Proben sind! Hmm... ich frage mich, was das bedeuten könnte. Es scheint sich bei ihnen um Elementare zu handeln, aber... auch noch um mehr. Sie erinnern mich an... die Alten Götter. Deren Spuren haben wir in ganz Azeroth gefunden und jetzt frage ich mich, ob diese Wesen nicht irgendwie mit ihnen verwandt sind.\n\nWir müssen weitere Tests durchführen.", rewards = "Ihr bekommt:\n\n"},
[4295] = {title = "Rocknots Bier", objective = "Oh, Bier! Was würde ich nicht für etwas Dunkeleisenbier geben! Schnell, ich werde langsam nüchtern! Das weiß ich, weil mir die Nüchternheit die Sinne trübt... und weil es Euch aussehen lässt wie der <Volk>, den ich letzte Woche erschlagen habe!", description = nil, progress = "Oh, Bier! Was würde ich nicht für etwas Dunkeleisenbier geben! Schnell, ich werde langsam nüchtern! Das weiß ich, weil mir die Nüchternheit die Sinne trübt... und weil es Euch aussehen lässt wie der <Volk>, den ich letzte Woche erschlagen habe!", completion = "Was ist denn das? Ah! Das riecht wie Dunkeleisenbier! Das Trinken verschleiert meine Sicht, aber ich sehe, dass Ihr, werter Herr, ein echter Freund seid!", rewards = nil},
[4296] = {title = "Schrifttafel der Sieben", objective = "Bringt Maxwort Uberglint in der brennenden Steppe die Abschrift der Schrifttafel.", description = "Die Legenden der Sieben führten mich in die brennende Steppe. Sie waren hoch gebildete und mächtige Zwerge, und wenn man über Wissen und Macht verfügt, so ist das der Schlüssel zum Reichtum.\n\nUnd genau das ist es, was ich will. Reichtum!\n\nWenn wir mehr über die Sieben in Erfahrung bringen könnten, würde das uns beide vielleicht reich machen. In den Ruinen von Thaurissan soll sich angeblich die Schrifttafel der Sieben befinden, auf der das Wissen über die alten Zwerge geschrieben steht. Sucht diese Schrifttafel, kopiert den Text und bringt ihn mir. Lasst uns deren Geheimnisse gemeinsam entschlüsseln!", progress = "Habt Ihr die Schriften der Sieben, <Name>? Kennt Ihr jetzt die Geheimnisse dieser Schrifttafel?", completion = "Ah, Ihr habt die Schrifttafel gefunden! Und Eure Abschrift ist erstklassig! Seid Ihr sicher, dass Ihr ein &lt;Klasse&gt; seid und kein Schreiber?\n\nHier, bitte sehr, &lt;Name&gt;. Nehmt hier die Bezahlung, die ich Euch versprochen habe.", rewards = "Ihr bekommt:\n\n"},
[4297] = {title = "Essen für das Baby", objective = "Bringt Agnar Beastamer im Hinterland 5 Silbermähnenpirscherflanken.", description = "Grimmlingflitzer sind Allesfresser - das bedeutet, dass sie sowohl Fleisch als auch Grünzeug fressen. Wenn dieses Junge hier schlüpft, sollten wir vorbereitet sein. Es ist kaum zu glauben, aber diese kleinen Kerlchen ernährt man am besten mit Fleischstücken, roh und saftig. Ich habe nie herausgefunden, warum das so ist, aber es muss wohl etwas mit Elunes Plan für die Elfen zu tun haben ... vielleicht waren sie als Beschützer oder so etwas vorgesehen, ich weiß es nicht.\n\nIch kümmere mich vorerst um das Ei. Warum besorgt Ihr nicht ein paar Silbermähnenpirscherflanken, mit denen wir das Junge füttern können, sobald es geschlüpft ist?", progress = "Habt Ihr das Fleisch, <Name>? Euer Kleines hier wird bald schlüpfen. Wenn seine erste Mahlzeit nicht ausreicht, wird er die erste Woche vielleicht nicht überleben, und ich möchte nicht, dass das geschieht.\n\nIch will ehrlich zu Euch sein, <Name>. Ich bin neidisch, weil Ihr so ein Ei habt und ich nicht. Und ich möchte es nicht bereuen, Euch hier ausgeholfen zu haben.", completion = "Das wird reichen, und wenn ich mich nicht irre, wird Euer Kleines bald schlüpfen. Wie ist das so? Ihr wisst schon, bald Vater zu sein? Haha, Ihr habt wohl nicht damit gerechnet, einmal solche Verantwortung übernehmen zu müssen, was?", rewards = "Ihr bekommt:\n\n"},
[4298] = {title = "Elternfreuden", objective = "Sprecht mit Agnar Beastamer im Hinterland.", description = "He, es war wohl schon weiter, als ich dachte...", progress = nil, completion = "Hier, nehmt das Ei... besser, Ihr habt es in der Hand, damit das Junge gleich eine Bindung zu Euch aufbaut und glaubt, Ihr wärt sein Papa.\n\nGlückwunsch, &lt;Name&gt;. Ihr habt jetzt ein Kind... sozusagen.", rewards = "Ihr bekommt:\n\nGrimmlingflitzerei"},
[4300] = {title = "Knochenklingenwaffen", objective = "Bringt Jes'rimon in Orgrimmar 8 weiße Ravasaurusklauen.", description = "Hmm, jetzt, wo ich darüber nachdenke, könnte es doch etwas geben, das Ihr für die Hand erledigen könntet. Ja, Jes'rimon könnte bestimmt Eure Hilfe brauchen.\n\nIm Un'Goro Krater gibt es Raptoren mit tödlichen Klauen. Manche dieser Raptoren haben weiße Klauen statt schwarze wie der Tod. Die Mitglieder der Hand haben ... Kunden ..., denen aus diesen Klauen gefertigte Waffen gefallen. Bringt mir reichlich von diesen weißen Klauen, dann werde ich Euch gut entlohnen. Wenn Ihr das schnell genug tut, dann kann ich Euch vielleicht noch auf andere Weise helfen.", progress = "Meine Kunden sind nicht sehr geduldig, <Name>. Habt Ihr schon irgendwelche Klauen?", completion = "Ah, die sind hervorragend. Danke, &lt;Name&gt;. Und Ihr seid zurück, bevor sie benötigt werden... sehr gut.\n\nVielleicht fertigen wir ja eine Waffe für Euch aus diesen Klauen an. Was meint Ihr?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWeißknochenbandWeißknochenschredderWeißknochenspeer\n\nIhr bekommt außerdem:\n\n"},
[4301] = {title = "Der mächtige U'cha", objective = "Bringt U'chas Pelz zu Torwa Pathfinder am Eingang des Un'Goro Kraters.", description = "Während Ihr Un'Goro erkundet habt, sind mir ein paar andere Dinge aufgefallen, die einem mächtigen Jäger wie Euch sicher gefallen würden. Zum Beispiel gibt es da einen gewaltigen Affen unter den Gorillas im Norden. Ihr seid schon einmal in dieser Höhle gewesen, aber dieses Mal frage ich mich doch, ob Ihr die Begegnung mit ihm wohl überleben würdet, solltet Ihr meine Aufgabe annehmen.\n\nIch nenne ihn U'cha und er ist einer der größten Söhne der Erdenmutter, da könnt Ihr sicher sein. Besiegt U'cha und bringt mir seinen Pelz. Wenn Euch das gelingt, habt Ihr das Recht darauf, ein großer Jäger genannt zu werden.", progress = "U'cha... was für ein großartiges Tier. Riesig und rot, mit Zähnen so lang wie Dolche. Arme so dick wie Baumstämme und so schnell wie der schnellste Berglöwe, den ich je gesehen habe. Ihr solltet Euch glücklich schätzen, ein solches Objekt für die Prüfung Eures Mutes vorzufinden - mein Volk hat seit Generationen keine derartige Kreatur mehr zu sehen bekommen.", completion = "Gut gemacht, &lt;Name&gt;. Ich bin erfreut. Heute habt Ihr hier Großes geleistet.\n\nU'cha war einer der größten Affen, die ich je gesehen habe. Die Tatsache, dass Ihr seine Kraft bezwungen habt, zeugt von Eurer eigenen Kraft... und Eurem Mut.\n\nDaher ist es nur angemessen, dass ich Euch dies hier als Zeichen meines Respekts überreiche. Ihr habt es Euch verdient.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWildtierzerhackerWildtiertöter\n\nIhr bekommt außerdem:\n\n"},
[4321] = {title = "Die Sache verstehen", objective = "Sprecht demnächst mit J. D. Collie.", description = "Die Information über die Pylonen, die Ihr mir gabt, ist sehr interessant...\n\nGebt mir einen Moment Zeit, um ein paar Berechnungen anzustellen, <Name>. Sprecht mich demnächst noch einmal an, dann sollte ich Euch die Antwort geben können, nach der wir gesucht haben.", progress = nil, completion = "So, &lt;Name&gt;. Das ist echt faszinierend... Ich kann nur hoffen, dass meine Diagramme korrekt sind! Ich habe alles in dieser Anleitung zusammengefasst, die ich Euch überlassen werde.\n\nJetzt sollte ich all Eure Fragen zu den Kristallen beantworten können, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nHandbuch für Kristallpylonen"},
[4322] = {title = "Gefängnisausbruch!", objective = "Helft Marshal Windsor, seine Ausrüstung zurückzuholen und seine Freunde zu befreien. Kehrt zu Marshal Windsor zurück, wenn Ihr Erfolg hattet.", description = "Wir müssen hier weg, <Name>. Helft mir, meine Ausrüstung aus dem Vorratsbereich zu holen und meine Freunde zu befreien. Falls wir hier rauskommen, dann müsst Ihr Euch weiter nach Morgans Wacht durchschlagen und mit Marshal Maxwell sprechen. Er wird Euch weitere Anweisungen geben.", progress = nil, completion = "Erstaunlich, &lt;Name&gt;. Einfach erstaunlich. Windsor ist vor nicht einmal fünf Minuten hier durchgestürmt. Er spuckte große Töne, behauptete jedoch, alles mit Beweisen untermauern zu können. Jetzt ist er auf dem Weg nach Stormwind, um Bolvar und... Lady Prestor damit zu konfrontieren.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKlinge der AbrechnungGeschickte Kampfklinge\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\nBarriere der Elemente"},
[4324] = {title = "Yuka Screwspigot", objective = "Sprecht mit Yuka Screwspigot in der brennenden Steppe.", description = "Mein Bruder Ribbly war sein ganzes Leben lang zu nichts nütze; aber jetzt, glaube ich, hat er endlich einen gewissen Wert! Aber... wir werden Eure Hilfe brauchen, um aus Ribblys Wert Kapital zu schlagen.\n\nMeine Schwester Yuka hat ihn wochenlang gesucht und endlich in der brennenden Steppe gefunden. Sie hat mich wissen lassen, dass sie ein paar Helfer brauchen könnte.\n\nAlso, was meint Ihr? Wollt Ihr uns helfen? Falls ja, sprecht mit meiner Schwester. Ihr findet sie im Flammenkamm versteckt, in einer Höhle nordwestlich des Schreckensfelsens.", progress = nil, completion = "Ja, ich suche meinen Bruder. Wir müssen ihn finden und zurückbringen, gesegnet sei sein Herz.\n\nAber wenn wir ihn nicht im Ganzen zurückbringen können... dann reicht auch sein Kopf.", rewards = nil},
[4341] = {title = "Kharan Mighthammer", objective = "Begebt Euch in die Blackrocktiefen und findet Kharan Mighthammer.\n\nDer König erwähnte, dass Kharan dort gefangen sei - vielleicht solltet Ihr nach einem Gefängnis Ausschau halten.", description = "Seid Ihr in den rauchenden Ruinen von Thaurissan gewesen? Seid Ihr dort zufällig einem erbärmlichen Tölpel namens Kharan Mighthammer begegnet? Dem Zwerg, der eigentlich über mein kleines Mädchen wachen sollte?\n\n<Der König schluchzt.>\n\nUnd jetzt ist sie verschwunden, <Name>!\n\nIch habe meine Leute die gesamte Steppe durchkämmen lassen. Doch der einzige Hinweis, den sie über den Verbleib meiner Tochter finden konnten, war, dass sie vielleicht in den Tiefen ist. Möglicherweise ist sie sogar schon tot!\n\nAngeblich wird Kharan dort als Gefangener festgehalten ... findet ihn! Ich will Antworten!", progress = nil, completion = "Bitte, lasst es mich erklären.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4342] = {title = "Kharans Geschichte", objective = "Lasst Kharan Mighthammer seine Geschichte erzählen.", description = "Bitte hört mich an, ehe Ihr ein Urteil fällt!", progress = "Erlaubt mir, meine Geschichte zu beenden.", completion = "Wie Ihr seht, gab es nichts, was ich hätte tun können.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4343] = {title = "Verderbte Windblüte", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[4361] = {title = "Der Überbringer schlechter Botschaften...", objective = "Kehrt nach Ironforge zurück und überbringt König Magni Bronzebeard die schlechten Nachrichten.", description = "Ihr müsst König Magni diese Informationen bringen, <Name>. Er wird wissen, was zu tun ist!", progress = nil, completion = "&lt;Wütend schlägt König Magni mit der Faust auf den Tisch.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4362] = {title = "Das Schicksal des Königreichs", objective = "Kehrt in die Blackrocktiefen zurück und rettet Prinzessin Moira Bronzebeard aus den Fängen des bösen Imperators Dagran Thaurissan.", description = "Es scheint, als habe mein alter Widersacher, Dagran Thaurissan, mich und das ganze Königreich Ironforge in seiner Gewalt.\n\nVielleicht seid Ihr meine letzte Hoffnung, <Name>. Ihr müsst meine Tochter Moira retten!\n\nEs gibt nur einen Weg, wie der Zauber, mit dem Thaurissan Moira belegt hat, wirklich zuverlässig gebrochen werden kann: Ihr müsst ihn töten.\n\nAber, <Name>, meiner Tochter dürft Ihr kein Leid zufügen! Vergesst nicht, dass sie Thaurissans Kontrolle unterliegt! Alles, was sie vielleicht sagt oder tut, geschieht aufgrund von Thaurissans bösem Zauber!", progress = nil, completion = "&lt;Prinzessin Bronzebeard weint bitterlich über den Verlust von Imperator Dagran Thaurissan.&gt;\n\nWarum???", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[4363] = {title = "Die Überraschung der Prinzessin", objective = "Kehrt nach Ironforge zurück und sprecht mit König Magni Bronzebeard.", description = "Thaurissan war ein großer und ehrenhafter Zwerg. Ihr habt mein Leben zerstört - meines und das meines ungeborenen Kindes!\n\n<Ihr habt den Eindruck, als leide Prinzessin Bronzebeard noch immer unter den letzten Auswirkungen des vom Imperator gewirkten Zaubers.>\n\nKehrt nach Ironforge zurück und sagt meinem Vater, dass der Erbe des Königreichs Ironforge ein Dunkeleisenzwerg sein wird.\n\nOb er dies billigt oder nicht, so wird es sein.", progress = nil, completion = "&lt;König Magni Bronzebeard ist sichtlich erschüttert.&gt;\n\nEs scheint, als habe Thaurissan gewonnen - sogar im Tode.\n\nIhr seid entlassen, &lt;Name&gt;. Doch ehe Ihr geht, dürft Ihr Euch Eure Belohnung aus dem königlichen Gewölbe auswählen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMagnis WilleLiedstein von Ironforge\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[4381] = {title = "Kristallflicker", objective = "Mit Hilfe der Pylon-Tafel könnt Ihr grüne und gelbe Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination Euch oder Eure Verbündeten heilen.", description = nil, progress = "Mit Hilfe der Pylon-Tafel könnt Ihr grüne und gelbe Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination Euch oder Eure Verbündeten heilen.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch.", rewards = "Ihr bekommt:\n\nKristallflicker"},
[4382] = {title = "Kristallkraft", objective = "Mit Hilfe der Pylon-Tafel könnt Ihr grüne und blaue Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination Euren Geist steigern.", description = nil, progress = "Mit Hilfe der Pylon-Tafel könnt Ihr grüne und blaue Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination Euren Geist steigern.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch.", rewards = "Ihr bekommt:\n\nKristallkraft"},
[4383] = {title = "Kristallbarriere", objective = "Mit Hilfe der Pylon-Tafel könnt Ihr grüne und rote Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination Euren Schutz vor körperlichem Schaden stärken.", description = nil, progress = "Mit Hilfe der Pylon-Tafel könnt Ihr grüne und rote Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination Euren Schutz vor körperlichem Schaden stärken.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch.", rewards = "Ihr bekommt:\n\nKristallbarriere"},
[4384] = {title = "Kristallschwächer", objective = "Mit Hilfe der Pylon-Tafel könnt Ihr rote und blaue Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination die Verteidigung eines Gegners schwächen.", description = nil, progress = "Mit Hilfe der Pylon-Tafel könnt Ihr rote und blaue Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination die Verteidigung eines Gegners schwächen.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch.", rewards = "Ihr bekommt:\n\nKristallschwächer"},
[4385] = {title = "Kristallsprengladung", objective = "Mit Hilfe der Pylon-Tafel könnt Ihr rote und gelbe Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination eine starke Explosion auslösen, die Euren Feinden Schaden zufügt.", description = nil, progress = "Mit Hilfe der Pylon-Tafel könnt Ihr rote und gelbe Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination eine starke Explosion auslösen, die Euren Feinden Schaden zufügt.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch.", rewards = "Ihr bekommt:\n\nKristallsprengladung"},
[4386] = {title = "Kristallspitze", objective = "Mit Hilfe der Pylon-Tafel könnt Ihr blaue und gelbe Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination einen Schild erschaffen, der Euren Feinden Schaden zufügt.", description = nil, progress = "Mit Hilfe der Pylon-Tafel könnt Ihr blaue und gelbe Machtkristalle miteinander verbinden.\n\nLaut J.D.s Handbuch könnt Ihr mit dieser Kombination einen Schild erschaffen, der Euren Feinden Schaden zufügt.", completion = "Ihr ordnet die Kristalle auf der Tafel an, die einzelnen Farben sorgfältig ausgerichtet. Als Ihr den letzten Kristall an den richtigen Platz legt, verbinden sich die Kristalle in einer Lichtexplosion miteinander.\n\nDie daraus entstandene Kombination gehört nun Euch.", rewards = "Ihr bekommt:\n\nKristallspitze"},
[4401] = {title = "Verderbte Liedblume", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Liedblumenpflanze aussieht. Ein stechender, ungesunder Geruch geht von der Pflanze aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet ein wenig cenarische Pflanzensalbe auf die Liedblume an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[4402] = {title = "Galgars Kaktusapfel Surprise", objective = "Bringt Galgar 10 Kaktusäpfel. Ihr erinnert Euch, dass er gesagt hat, man fände sie in der Nähe von Kakteen.", description = "Hier im Tal der Prüfungen wird es ganz schön heiß.\n\n<Galgar wischt sich den Schweíß von der Stirn.>\n\nWenn ich doch nur ein paar Kaktusäpfel hätte, dann könnte ich meinen berühmten Kaktusapfel Surprise machen! Nichts kühlt einen schneller ab als ein Stück dieser leckeren Spezialität.\n\nIch sag Euch was, <Name>. Wenn Ihr mir 10 Kaktusäpfel bringt, dann mache ich Euch ein paar Portionen Kaktusapfel Surprise, die Ihr mit auf Eure Abenteuer nehmen könnt. Falls Ihr daran interessiert seid, findet Ihr Kaktusäpfel bei den Kaktuspflanzen, die hier in der Gegend wachsen.", progress = "Habt Ihr schon genug Kaktusäpfel eingesammelt?", completion = "Wunderbar, &lt;Name&gt;! Wie versprochen, habt Ihr hier Euren Kaktusapfel Surprise - und noch ein bisschen was dazu.", rewards = "Ihr bekommt:\n\nKaktusapfel Surprise"},
[4403] = {title = "Verderbte Windblüte", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[4421] = {title = "Die Verderbnis der Jadefeuer", objective = "Tötet Xavathras sowie 11 Jadefeuerteufelsanbeter, 9 Jadefeuerschattenpirscher und 9 Jadefeuerschurken. Kehrt zu Eridan Bluewind im Teufelswald zurück, sobald die Aufgabe erledigt ist.", description = "Nicht viele kommen hierher und suchen das Abenteuer... Die Verderbnis hat sich im Teufelswald überall ausgebreitet und macht vor nichts Halt.\n\nAls Mitglied des Smaragdkreises trachte ich danach, dieses Land zu heilen. Doch es gibt andere, die wünschen, dass es weiter schwärt.\n\nIch spreche von den Jadefeuersatyrn, die sich südwestlich von hier aufhalten, bei den Ruinen von Constellas. Ihr Anführer ist ein besonders grausamer Satyr namens Xavathras und unter seiner Führung übertragen sie die Krankheit auf alle Wesen, denen sie begegnen.\n\nWir müssen dieses Land, das einst das unsrige war, verteidigen. Besiegt Xavathras und vernichtet seine Diener.", progress = nil, completion = "Den Teufelswald von Xavathras zu befreien, ist nur der erste Schritt auf einem langen Weg. Es wird viel Arbeit vonnöten sein, um den Schaden zu beheben, der hier angerichtet worden ist.\n\nIch spüre, dass hier mehr am Werk ist als nur die Satyrn allein, aber die Wahrheit werden wir wohl erst im Lauf der Zeit herausfinden...", rewards = "Ihr bekommt:\n\n"},
[4441] = {title = "Gebundene Urtume", objective = "Begebt Euch nach Darnassus und verwendet Eridans Phiole, um Euch im Tempel des Mondes eine Phiole mit gesegnetem Wasser zu holen. Kehrt mit der gefüllten Phiole zu Eridan zurück.", description = "Die Flöte, die Ihr gefunden habt, wurde aus einem Urtumbeschützer geschnitzt, den Treantverbündeten, die schon immer treu über die Nachtelfen gewacht haben.\n\nEs ist den Satyrn gelungen, alles zu verderben, mit dem sie in Kontakt kommen, einschließlich der Urtume, die im Teufelswald lebten. Mit Hilfe der teuflischen Verderbnis wurde der Geist des Urtums gefangen und gefoltert und nie wieder völlig freigegeben. Der Teufelsbinder, den Ihr gefunden habt, hängt ganz ohne Zweifel damit zusammen.\n\nWir müssen versuchen, die Flöte zu läutern, <Name>. Bringt mir gesegnetes Wasser vom Tempel des Mondes in Darnassus.", progress = "Hoffentlich wird das Wasser den Geist des Urtums freisetzen, sodass er von nun an in Frieden ruhen kann.", completion = "Danke, &lt;Name&gt;. Und jetzt müssen wir hoffen und beten, dass wir den Schaden beheben können, der hier angerichtet worden ist...", rewards = "Ihr bekommt:\n\n"},
[4442] = {title = "Geläutert!", objective = "Sprecht Eridan gleich noch einmal an.", description = "Ich werde jetzt versuchen, die Flöte mit dem Wasser von Elune zu läutern. Wir müssen diesem Leiden ein Ende machen...\n\nMöge Elune meine Hände und mein Herz leiten.\n\nSprecht mich gleich noch einmal an.", progress = nil, completion = "Mit dem gesegneten Wasser konnte ich die Verbindung zwischen der Flöte und dem Geist des Urtums unterbrechen. Aber ich glaube, dass Ihr, wenn Ihr diese Flöte an einem heiligen Ort verwendet, vielleicht die Geister der Urtume beschwören könnt.\n\nIhr könntet es einmal in den Ruinen im südlichen Teil der Ruinen des Eisenwaldes versuchen. Einst bewohnten viele verderbte Treants diese Gegend und es ist möglich, dass sie sich noch immer dort aufhalten, und sei es auch nur in Geistgestalt.", rewards = "Ihr bekommt:\n\nFlöte der Urtume"},
[4443] = {title = "Verderbte Peitscherwurzel", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet drei cenarische Pflanzensalben auf die Peitscherwurzel an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
[4444] = {title = "Verderbte Peitscherwurzel", objective = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", description = nil, progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Peitscherwurzelpflanze aussieht. Die sichtbaren Wurzeln der Pflanze sehen zäh und ledrig aus und ein schleimiger Film tropft von der Pflanze. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet drei cenarische Pflanzensalben auf die Peitscherwurzel an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze.", rewards = nil},
