[5891] = {title = "Salbe durch Entzauberung", objective = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", description = nil, progress = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", completion = "Hier sind einige cenarische Pflanzensalben - ich brauche nur eine geringe Netheressenz, um sie herzustellen, &lt;Name&gt;. Die Essenz ist bei weitem der wirksamste Gegenstand, um Schwerter zu Pflugscharen zu machen, wenn man so sagen will. Wenn Ihr mehr Salbe braucht, dann kommt wieder zu mir!", rewards = "Ihr bekommt:\n\nCenarische Pflanzensalbe"},
[5892] = {title = "Irondeep-Vorräte", objective = "Bringt 10 Irondeep-Vorräte zum Rüstmeister der Allianz in Dun Baldar.", description = "Bevor die Schlacht begann, lagerten wir Vorräte für Dun Baldar in der Irondeep-Mine. Die Troggs, die dort hausten, waren kein Problem solange wir Ersatztruppen hatten, die die Mine bewachen konnten, aber da wir nun gegen die Horde kämpfen, können wir sie nicht mehr kontrollieren.\n\nWir brauchen die Vorräte in Irondeep, <Name>. Betretet die Mine und bring mir eine Ladung.", progress = "Habt Ihr die Vorräte, <Name>? Wir können nicht genug davon haben!", completion = "Danke, &lt;Name&gt;! Ich werde sie einem guten Zweck zuführen.", rewards = "Ihr bekommt:\n\n"},
[5893] = {title = "Coldtooth-Vorräte", objective = "Bringt 10 Coldtooth-Vorräte zum Rüstmeister der Horde in die Burg Frostwolf.", description = "Die Coldtooth-Mine im Norden war einst ein idealer Ort um zusätzliche Vorräte zu lagern, aber da die Kämpfe mit den Stormpikes nun härter werden, haben wir nicht immer die notwendigen Soldaten über, um sie an der Mine zu positionieren und diese zu bewachen. Daher fällt die Kontrolle über diese Mine oft an die Allianz oder an Untergrundvölker...\n\nAber wir benötigen dennoch unsere Vorräte, <Name>! Geht zu der Coldtooth-Mine und bringt mir eine Ladung. Seid wachsam was unsere Feinde anbelangt, die Übermacht in der Schlacht kann sich an jenem Ort schnell ändern...", progress = "Wart Ihr in der Coldtooth-Mine, <Name>? Habt Ihr die Vorräte nach denen ich fragte?", completion = "Ah, Ihr habt Sie bekommen. Gute Arbeit, &lt;Name&gt;! Die Vorräte sind schon etwas moderig, nachdem sie so lange in der Mine lagerten. Ich denke, sie werden uns dennoch sehr weiterhelfen.\n\nVielen Dank, &lt;Name&gt;. Eure Anstrengungen sind lebenswichtig für die Versorgung unserer Streitkräfte.", rewards = "Ihr bekommt:\n\n"},
[5901] = {title = "Eine Plage komme über Euch", objective = "Wendet den leeren Termitenkrug auf die Termitenhügel in den östlichen Pestländern an. Sobald Ihr 100 Pestland-Termiten gesammelt habt, kehrt zu Mickey Levine am Bollwerk in Tirisfal zurück.", description = "Also, um Schmerz und Unfrieden über den Scharlachroten Kreuzzug zu bringen, möchte ich ihnen ihr wertvolles Sägewerk wegnehmen. Ich bin mir sicher, der Verlust einer solchen Ressource wird ihnen ziemlichen Schaden in Bezug auf Verteidigung und Wiederaufbau der Stadt für ihre Zwecke zufügen. Werdet Ihr mir helfen, <Name>?\n\nFangt an, indem Ihr diesen Krug zum Pestwald in den östlichen Pestländern bringt. Füllt ihn mit den Termiten, die Ihr in ihren Hügeln überall im Wald findet. Kommt wieder, wenn Ihr eine ausreichende Menge habt.", progress = "Habt Ihr die Termiten schon, <Name>? Ich bin sicher, dass es für jemanden, der so schlau ist wie Ihr, <Klasse>, ganz einfach ist.\n\nSobald wir genug davon haben, sorgen wir dafür, dass niemand dieses Sägewerk je wieder verwenden kann!", completion = "Die sind prima, &lt;Name&gt;. Danke.\n\nWenn Ihr bereit seid, können wir uns dem nächsten Schritt zuwenden.", rewards = "Ihr bekommt:\n\n"},
[5902] = {title = "Eine Plage komme über Euch", objective = "Sucht Euch einen geeigneten Ort in der Mitte des Northridge-Sägewerks in den Westlichen Pestländern, um das Fass mit den Pestland-Termiten abzustellen.\n\nBereitgestellter Gegenstand: \n", description = "Da wir jetzt jede Menge Termiten haben, bringt dieses stahlverstärkte Fass zum Northridge-Sägewerk südlich von Hearthglen. Ihr werdet es westlich der Straße finden, die Euch in die Stadt hinauf führt.\n\nWenn Ihr dort seid, stellt Ihr das Fass in die Mitte des Sägewerkes, irgendwo weit oben, vielleicht auf eine Kiste oder sowas.\n\nNachdem Ihr es geöffnet habt, sollte sich der Rest von selbst erledigen. Kommt einfach hierher zurück und ich werde Euch dafür belohnen, dass Ihr mir geholfen habt.", progress = nil, completion = "Die Termiten werden offensichtlich unruhig, als Ihr das Fass auf die Kiste stellt.", rewards = "Ihr bekommt:\n\n"},
[5903] = {title = "Eine Plage komme über Euch", objective = "Wendet den leeren Termitenkrug auf die Termitenhügel in den Östlichen Pestländern an. Sobald Ihr 100 Pestland-Termiten gesammelt habt, kehrt zu Nathaniel Dumah am Chillwindposten in den Westlichen Pestländern zurück.", description = "Ich habe bereits viele Male versucht, den Scharlachroten Kreuzzug allein mit Gewalt auszulöschen, doch ohne Erfolg. Daher habe ich mich entschlossen, ihnen das Leben schwer zu machen.\n\nWenn Ihr bereit seid zu helfen, möchte ich, dass Ihr dieses Sägewerk mit der übelsten Termitenart verseucht, die je gefunden wurde.\n\nIm Pestwald, nahe dem einst großen Stratholme, gibt es eine Spezies, die die Seuche und auch die Geißel überlebt hat. Sucht ihre Hügel und füllt diesen Krug mit ihnen, damit wir sie darauf vorbereiten können, auf den Kreuzzug losgelassen zu werden.", progress = "Habt Ihr die Termitenhügel gefunden, <Name>? Ich habe gehört, es gibt sie überall im Pestwald.", completion = "Die sind prima, &lt;Name&gt;. Danke. Schaut sie Euch nur an... so viele von ihnen, alle auf einem Haufen. Ich habe schon beinahe Mitleid mit dem Kreuzzug, aber es war ja schließlich niemals ihre Mühle, nicht wahr?", rewards = "Ihr bekommt:\n\n"},
[5904] = {title = "Eine Plage komme über Euch", objective = "Sucht Euch einen geeigneten Ort in der Mitte des Northridge-Sägewerks in den Westlichen Pestländern, um das Fass mit den Pestland-Termiten abzustellen.\n\nBereitgestellter Gegenstand: \n", description = "Da wir jetzt die Termiten haben, bringt dieses stahlverstärkte Fass zum Northridge-Sägewerk südlich von Hearthglen. Ihr werdet es westlich der Straße finden, die Euch in die Stadt hinauf führt.\n\nWenn Ihr dort seid, stellt Ihr das Fass in die Mitte des Sägewerkes. Findet einen geeigneten Ort, vielleicht eine Kiste, und öffnet es dann. Die Termiten dürften dann ihre Arbeit tun und die Mühle für den Kreuzzug unbrauchbar machen.", progress = nil, completion = "Die Termiten werden offensichtlich unruhig, als Ihr das Fass auf die Kiste stellt.", rewards = "Ihr bekommt:\n\n"},
[5921] = {title = "Moonglade", objective = "Benutzt den Zauber 'Teleportation: Moonglade', um nach Moonglade zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Starblaze in Nighthaven.", description = "Alle Druiden sind in den hochheiligen Landen von Moonglade willkommen, ungeachtet der derzeitigen Spannungen im Zirkel des Cenarius zwischen dem Erzdruiden Staghelm und dem Bewahrer Remulos, dem Wächter von Moonglade. Jetzt, da Ihr den Weg der Klaue lernt, bringe ich Euch den Zauber bei, der es Euch ermöglicht, Euch selbst dorthin zu befördern. Wirkt ihn, wann immer Ihr Moonglades Wissen oder Zuflucht sucht.\n\nAls Eure erste Lektion müsst Ihr nach Moonglade reisen und mit Dendrite Starblaze in Nighthaven über den Pfad sprechen, auf dem Ihr jetzt wandelt. Viel Glück, <junger Druide/junge Druidin>.", progress = nil, completion = "Und so beginnt es, Vater Cenarius. Und so beginnt es.\n\nDendrite macht eine schnelle, unsichtbare Geste in die Luft über ihm. Eine leichte Aura der Macht fällt über ihn.\n\nDie erste Perspektive der Natur, die Ihr Euch aneignen müsst, ist die des Bären. Ich werde Euch auf den Weg bringen, um diesen Aspekt des Druidenlebens zu verstehen, aber Ihr müsst ihn Euch zu Eigen machen und pflegen - von nun an und für immer!", rewards = "Ihr bekommt:\n\n"},
[5922] = {title = "Moonglade", objective = "Benutzt den Zauber 'Teleportation: Moonglade', um nach Moonglade zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Starblaze in Nighthaven.", description = "Alle Druiden sind in den hochheiligen Landen von Moonglade willkommen, Tauren wie Nachtelfen. Bewahrer Remulos - Moonglades Wächter - wacht über allen Druiden, die hier ihren Winterschlaf halten. Jetzt, da Ihr den Weg der Klaue lernt, bringe ich Euch den Zauber bei, der es Euch ermöglicht, Euch selbst dorthin zu befördern. Wirkt ihn, wann immer Ihr Moonglades Wissen oder Zuflucht sucht.\n\nAls Eure erste Lektion müsst Ihr nach Moonglade reisen und mit Dendrite Starblaze in Nighthaven über den Pfad sprechen, auf dem Ihr jetzt wandelt. Viel Glück, <junger Druide/junge Druidin>.", progress = nil, completion = "Und so beginnt es, Vater Cenarius. Und so beginnt es.\"\n\nDendrite macht eine schnelle, unsichtbare Geste in die Luft über ihm. Eine leichte Aura der Macht fällt über ihn.\n\n\"Die erste Perspektive der Natur, die Ihr Euch aneignen müsst, ist die des Bären. Ich werde Euch auf den Weg bringen, um diesen Aspekt des Druidenlebens zu verstehen, aber Ihr müsst ihn Euch zu Eigen machen und pflegen - von nun an und für immer!", rewards = "Ihr bekommt:\n\n"},
[5923] = {title = "Dem Ruf folgen", objective = "Sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius in Darnassus.", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Mathrengyl Bearwalker bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.\n\nEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Staghelms Baum.", progress = nil, completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!", rewards = "Ihr bekommt:\n\n"},
[5924] = {title = "Dem Ruf folgen", objective = "Sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius in Darnassus.", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Mathrengyl Bearwalker bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.\n\nEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Staghelms Baum.", progress = nil, completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!", rewards = "Ihr bekommt:\n\n"},
[5925] = {title = "Dem Ruf folgen", objective = "Sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius in Darnassus.", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Mathrengyl Bearwalker bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.\n\nEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Staghelms Baum.", progress = nil, completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!", rewards = "Ihr bekommt:\n\n"},
[5926] = {title = "Dem Ruf folgen", objective = "Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Turak Runetotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.\n\nEr befindet sich in Thunder Bluff, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.", progress = nil, completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!", rewards = "Ihr bekommt:\n\n"},
[5927] = {title = "Dem Ruf folgen", objective = "Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Turak Runetotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.\n\nEr befindet sich in Thunder Bluff, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[5928] = {title = "Dem Ruf folgen", objective = "Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Turak Runetotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.\n\nEr befindet sich in Thunder Bluff, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.", progress = nil, completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!", rewards = "Ihr bekommt:\n\n"},
[5929] = {title = "Großer Bärengeist", objective = "Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück.", description = "Im nordwestlichen Teil von Moonglade liegt das Zuhause eines weisen und edlen Wesens, das wir den großen Bärengeist nennen. Er hat allen Druiden als Tutor und Mentor zur Seite gestanden, die das erste Mal wahres und natürliches Verständnis für den Bären entwickeln wollten. Alle Druiden suchen an irgendeinem Punkt ihres Lebens die Weisheit des Geistes und auch Ihr werdet keine Ausnahme sein.\n\nGeht nun zum großen Bärengeist und lernt, was er Euch beibringen wird. Wenn er mit Euch zufrieden ist, kehrt zu mir hier nach Nighthaven zurück. Wir werden dann sehen, ob Ihr die Lektionen, die er Euch gelehrt hat, wirklich verinnerlicht habt.", progress = "Kehrt erst zurück, wenn der große Bärengeist Euch wieder zu mir zurückschickt. Eure Ausbildung kann ohne seinen Segen nicht weitergehen.", completion = "Dendrite macht eine weitere unsichtbare Geste in der Luft über ihm, als Ihr Euch ihm nähert. Eine erneute Aura der Macht legt sich auf ihn und er lächelt ein wenig.\n\n\"Ich spüre Weisheit in Euch, Weisheit, die nicht zugegen war, als wir uns das erste Mal trafen. Ihr blickt mit Stärke und verständnisvollem Eifer zu mir auf, auch wenn dieser Eifer noch nicht sehr zielgerichtet ist. Ihr werdet nun lernen, Eure Stärke zu fokussieren und das Wesen des Bären in Eure Arbeit anzuwenden.\"", rewards = "Ihr bekommt:\n\n"},
[5930] = {title = "Großer Bärengeist", objective = "Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück.", description = "Im nordwestlichen Teil von Moonglade liegt das Zuhause eines weisen und edlen Wesens, das wir den großen Bärengeist nennen. Er hat allen Druiden als Tutor und Mentor zur Seite gestanden, die das erste Mal wahres und natürliches Verständnis für den Bären entwickeln wollten. Alle Druiden suchen an irgendeinem Punkt ihres Lebens die Weisheit des Geistes und auch Ihr werdet keine Ausnahme sein.\n\nGeht nun zum großen Bärengeist und lernt, was er Euch beibringen wird. Wenn er mit Euch zufrieden ist, kehrt zu mir hier nach Nighthaven zurück. Wir werden dann sehen, ob Ihr die Lektionen, die er Euch gelehrt hat, wirklich verinnerlicht habt.", progress = "Kehrt erst zurück, wenn der große Bärengeist Euch wieder zu mir zurückschickt. Eure Ausbildung kann ohne seinen Segen nicht weitergehen.", completion = "Dendrite macht eine weitere unsichtbare Geste in der Luft über ihm, als Ihr Euch ihm nähert. Eine erneute Aura der Macht legt sich auf ihn und er lächelt ein wenig.\n\n\"Ich spüre Weisheit in Euch, Weisheit, die nicht zugegen war, als wir uns das erste Mal trafen. Ihr blickt mit Stärke und verständnisvollem Eifer zu mir auf, auch wenn dieser Eifer noch nicht sehr zielgerichtet ist. Ihr werdet nun lernen, Eure Stärke zu fokussieren und das Wesen des Bären in Eure Arbeit anzuwenden.\"", rewards = "Ihr bekommt:\n\n"},
[5931] = {title = "Zurück nach Darnassus", objective = "Kehrt nach Darnassus zurück und sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius.", description = "Es ist an der Zeit für uns, getrennte Wege zu gehen, denn die Anwendung Eurer Lektionen bringt Euch zurück zu demjenigen, der Euch zu mir geschickt hat. Mathrengyl Bearwalker bewegt sich wirklich im Einklang mit der Natur, selbst wenn er gefährlich nahe der Orte ist, an denen das Gleichgewicht zusammengebrochen ist. Achtet auf seine Anweisungen und Ihr werdet bald die ersten Lektionen Eurer Rolle als Beschützer des Gleichgewichts beenden.\n\nGeht jetzt. Wir sehen uns wieder.", progress = nil, completion = "Willkommen, &lt;Name&gt;. Ich spüre, dass Eure erste Begegnung mit dem großen Bärengeist genauso verlief wie bei allen Druiden, wenn sie die ersten Schritte auf dem Pfad der Klaue tun... etwas verwirrend, aber sehr eindrucksvoll. Ich weiß, dass es für mich damals auch so war.\n\nDer große Bärengeist ist schon so lange ein Teil von Azeroth wie Azeroth in den Himmeln existiert. Wir verlassen uns heute auf seine Weisheit und seine Macht, um unseren Absichten Antrieb zu verleihen. Nun ist es an der Zeit für Eure erste Prüfung dieser Absichten. Hört mir gut zu...", rewards = "Ihr bekommt:\n\n"},
[5932] = {title = "Zurück nach Thunder Bluff", objective = "Kehrt nach Thunder Bluff zurück und sprecht mit Turak Runetotem auf der Anhöhe der Ältesten.", description = "Es ist an der Zeit für uns, getrennte Wege zu gehen, denn die Anwendung Eurer Lektionen bringt Euch zurück zu demjenigen, der Euch zu mir geschickt hat. Auch wenn die Tauren auf den Wegen des Cenarius als jung angesehen werden, wandelt Turak Runetotem doch mit großem Gleichgewicht in Gegenwart der Natur. Achtet auf seine Anweisungen und Ihr werdet bald die ersten Lektionen Eurer Rolle als Beschützer des Gleichgewichts beenden.\n\nGeht jetzt. Wir sehen uns wieder.", progress = nil, completion = "Willkommen, &lt;Name&gt;. Ich spüre, dass Eure erste Begegnung mit dem großen Bärengeist genauso verlief wie bei allen Druiden, wenn sie die ersten Schritte auf dem Pfad der Klaue tun... etwas verwirrend, aber sehr eindrucksvoll. Ich weiß, dass es für mich damals auch so war.\n\nDer große Bärengeist ist schon so lange ein Teil von Azeroth wie Azeroth in den Himmeln existiert. Wir &lt;Volk&gt; hören solchen Geistern genau zu und wir alle profitieren von deren Absichten. Nun ist es an der Zeit für Eure erste Prüfung dieser Absichten. Hört mir gut zu...", rewards = "Ihr bekommt:\n\n"},
[5941] = {title = "Rückkehr zu Chromie", objective = "Bringt das Reliktbündel zu Chromie nach Andorhal.", description = "Ihr habt viele Relikte der Schlacht von Darrowshire gesammelt. Jedes Mal, wenn Ihr mit weiteren zurückgekehrt seid, sehnte sich mein Herz nach meinem Dorf... sehnte es sich danach, es vor seinem Schicksal zu bewahren.\n\nIch weiß, dass das nicht sein kann, aber Chromie, diese seltsame Gnomin in Andorhal, behauptet, es wäre möglich. Sie sagt, dass Ihr Darrowshire retten könnt!\n\nSie hat mich gebeten, die Relikte zu sammeln und sie von Euch zu ihr bringen zu lassen. Sie sagte, dass sie Euch im zerstörten Gasthaus von Andorhal erwartet.", progress = "Ich stand in Kontakt mit Eurem Freund Carlin. Er leidet sehr unter dem Untergang seines Dorfes, doch er spricht sehr gut von Euch und weiß, dass Ihr die Dinge richten könnt.\n\nOh, ich fürchte ich schweife vom Thema ab... <Name>, habt Ihr die Relikte, um die ich gebeten habe?", completion = "Ach ja, da sind sie ja. Gemeinsam weben sie einen mächtigen Zauber, einen, der die Geister von Darrowshire wiedererwecken wird.\n\nMit diesem Zauber und etwas Glück können wir Joseph Redpath retten!", rewards = "Ihr bekommt:\n\n"},
[5942] = {title = "Versteckte Schätze", objective = "Bringt Josephs Schlüssel zu Josephs Truhe.", description = "Papa sagte, ich solle Euch diesen Schlüssel geben. Er sagte, er öffnet eine Truhe draußen hinter dem Haus.\n\nEr wollte außerdem, dass ich Euch danke. Habt Ihr ihm einen Gefallen getan? Habt Ihr ihm gesagt, dass Ihr meine Puppe gefunden habt?\n\nNun, hier ist jedenfalls der Schlüssel. Und habt Dank, <Name>. Danke! Ihr seid <ein sehr netter Mann/eine sehr nette Dame>!", progress = "Diese Truhe ist alt und rußverschmiert.", completion = "Der Schlüssel passt in das Schloss, und die Truhe öffnet sich...", rewards = "Ihr bekommt:\n\nRing des SchutzesErzlicht-TalismanMagierbann-Spross"},
[5943] = {title = "Gizeltons Karawane", objective = "Geleitet Gizeltons Karawane durch Mannorocs Koven. Sprecht in Scrabblescrews Lager mit Smeed, um Eure Belohnung zu erhalten.", description = "Ihr seht fähig aus, <Volk>. Vielleicht wollt Ihr Euch etwas Geld verdienen? Cork und ich haben mit dieser Karawane angefangen, um einen Haufen Geld zu scheffeln. Doch wir hatten keine Ahnung von den Gefahren, die das schnelle Geld mit sich bringen würde!\n\nDa vor uns liegt Mannorocs Koven ... normalerweise ignorieren die Dämonen uns, aber dieses Mal verängstigt irgendetwas die Kodos. Ich werde Euch dafür bezahlen, wenn Ihr die Karawane auf dem Weg an Mannorocs Koven vorbei beschützt. Sobald wir sicher daran vorbei sind, könnt Ihr Euch Eure Belohnung bei unserem Geschäftspartner Smeed in Scrabblescrews' Lager abholen.", progress = nil, completion = "Ich bin mir nicht sicher, ob es zu ihrem Erfolg beiträgt, Euch so viel Geld für den Schutz von Gizeltons Karawane zu bezahlen. Cork und Rigger verdienen gerade mal ein Goldstück pro Woche, doch solange sie schön meine Kodos bezahlen, kann es mir eigentlich egal sein, wie sie ihre Geschäfte machen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMinischrotflinteKodobränderBeschlagener Ringschild\n\nIhr bekommt außerdem:\n\n"},
[5944] = {title = "In den Träumen", objective = "Geleitet Taelan Fordring aus Hearthglen hinaus.", description = "Über so lange Zeit war ich eine Marionette des Obersten Kreuzzüglers. Welchen Grund gab es, gegen das anzukämpfen, was aus dem Scharlachroten Kreuzzug geworden ist? Es ist Jahrzehnte her, doch die Erinnerungen an meinen Vater - diese kostbaren Erinnerungen - waren es, die mich am Leben erhielten.\n\nIch habe Träume, <Fremder/Fremde>. In diesen Träumen ist mein Vater bei mir. Er steht stolz an meiner Seite, während ich in den Orden aufgenommen werde. Wir bekämpfen Legionen der Geißel, Seite an Seite. Wir bringen der Allianz und Lordaeron Ehre.\n\nIch möchte nicht mehr träumen.\n\nBringt mich zu ihm.", progress = nil, completion = "Der Tod meines Sohnes durch die Hand dieser Monster wird nicht ungestraft bleiben. Findet Trost in dem Wissen, dass der Orden wiedergeboren wurde.\n\nIch nehme jetzt meinen Platz als Hochlord des neuen Orden der Silberhand ein.\n\nNehmt diese Besitztümer aus meiner Vergangenheit ... sie sind alles, was ich Euch für all das anbieten kann, was Ihr getan habt. Bitte, nehmt sie als ein Zeichen meiner Dankbarkeit. Sie haben mir all die Jahre gut gedient.\n\nAuf dass wir uns in besseren Zeiten wiedersehen und uns lang vergangener Tage, hart erkämpfter Schlachten und verblasster Träume erinnern.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMal von FordringVerschnörkelte AdamantbrustplatteSchimmernder PlatinkriegshammerTuch der VerbannungFordrings Siegel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[5961] = {title = "Der Champion der Bansheekönigin", objective = "Sprecht mit Nathanos Blightcaller in den Östlichen Pestländern. Es heißt, dass er sich in Marris Siedlung niedergelassen hätte.", description = "Es freut mich sehr, dass sich die Kampferprobten unserer Sache anschließen. Unsere Schar gewinnt mit jedem Tag an Größe und Stärke. Vielleicht seid Ihr bereit, Euren Mut auf die Probe zu stellen, <Klasse>?\n\nZu den ersten meiner Helden gehörte Nathanos, der heute Blightcaller genannt wird. In unseren Reihen gibt es kaum einen mit mehr Entschlossenheit oder Eifer.\n\nSucht in den Östlichen Pestländern nach ihm. Er wohnt in Marris Siedlung; ab und an streift er durch die dezimierten Ödländer und tötet jeden Abschaum der Geißel und der Allianz, den er aufspüren kann.", progress = nil, completion = "Gewiss hält Euch die Dunkle Fürstin nicht für würdig, ihren Champion zu treffen. Seid Ihr hier, um meine Hunde zu füttern, ja? Einen anderen Grund für diese Unterbrechung kann es nicht geben.", rewards = "Ihr bekommt:\n\n"},
[5981] = {title = "Tobende Riesen", objective = "Rivern Frostwind möchte, dass Ihr 4 Frosthagelriesen und 4 Frosthagelbewahrer besiegt.", description = "Vor rund 4000 Jahren rettete Tyrande Whisperwind die Frostsäblerkönigin aus den Händen tobender Riesen. Seither sind die Frostsäbler Verbündete der Nachtelfen.\n\nDoch die Riesen, die einst eine Gefahr für die Frostsäbler waren, gibt es noch immer, und das nicht allzu weit von hier entfernt. Man nennt sie Frosthagelriesen und sie haben das große Tal südlich von hier für sich beansprucht.\n\nBeweist Eure Treue zu den Frostsäblern. Tötet diese Riesen im Namen der Frostsäblerkönigin Shy-Rotam!Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil},
[6001] = {title = "Körper und Herz", objective = "Benutzt den Mondstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.\n\nSprecht mit Mathrengyl Bearwalker in Darnassus, wenn Ihr fertig seid.", description = "Unmittelbar östlich von Auberdine liegen viele Moonkinhöhlen. In der Auberdine am nächsten gelegenen Höhle befindet sich ein Moonkinstein. Mondklaue, der Verteidiger des Steins, stellt sich Euch nur, wenn Mondstaub des Cenarius darauf angewendet wird. Mondklaue besitzt eine innere Stärke, die Ihr als einer der Klaue benutzen müsst.\n\nIhr habt Euch das Recht verdient, diesen Mondstaub des Cenarius zu benutzen, <Name>... jetzt zeigt mir, dass Ihr Euch das Recht verdient habt, die Kraft des Körpers und des Herzens zu besitzen, die man als Druide braucht!", progress = nil, completion = "Endlich habt Ihr den Schritt in eine viel größere Welt getan, &lt;Name&gt;. Ich spüre die Lehre des großen Bärengeistes in Euch, und auch, dass Ihr die Kraft erhalten habt, die Mondklaue besaß.\n\nKein weiteres Hindernis versperrt Euren Weg... lasst mich Euch jetzt lehren, was es bedeutet, ein &lt;Klasse&gt; der Klaue zu sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBärengestalt\n\nIhr bekommt:\n\n"},
[6002] = {title = "Körper und Herz", objective = "Benutzt den Lunarstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.\n\nSprecht mit Turak Runetotem in Thunder Bluff, wenn Ihr fertig seid.", description = "Auf Land westlich von Taurajo im Brachland - kurz bevor es in Mulgore übergeht - liegt ein Moonkinstein. Moonkin sind besondere Tiere, die nicht in diesen Breiten heimisch sind. Mondklaue, der Verteidiger des Steins, stellt sich Euch, wenn Lunarstaub des Cenarius darauf angewendet wird. Mondklaue besitzt eine innere Stärke, die Ihr als einer der Klaue benutzen müsst.\n\nIhr habt Euch das Recht verdient, diesen Lunarstaub des Cenarius zu benutzen, <Name>... jetzt zeigt mir, dass Ihr Euch das Recht verdient habt, die Kraft des Körpers und des Herzens zu besitzen, die man als Druide braucht!", progress = nil, completion = "Endlich habt Ihr den Schritt in eine viel größere Welt getan, &lt;Name&gt;. Ich spüre die Lehre des großen Bärengeistes in Euch, und auch, dass Ihr die Kraft erhalten habt, die Mondklaue besaß.\n\nKein weiteres Hindernis versperrt Euren Weg... lasst mich Euch jetzt lehren, was es bedeutet, ein &lt;Klasse&gt; der Klaue zu sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBärengestalt\n\nIhr bekommt:\n\n"},
[6004] = {title = "Offene Rechnungen", objective = "Tötet 2 scharlachrote Sanitäter, 2 scharlachrote Jäger, 2 scharlachrote Magi und 2 scharlachrote Ritter, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt.", description = "Ich wurde als Späher ausgeschickt, um etwas Schaden anzurichten und die Kraft von Hearthglens Verteidigung auszukundschaften. Einige Leute der Allianz sind der Meinung, die kleine Stadt habe mehr als nur eine historische Bedeutung. Meine Aufgabe ist es nicht, diese Bedeutung in Frage zu stellen, aber dennoch sollte ich mich in meiner Verfassung erst erholen, bevor ich weitermache.\n\nWenn Ihr wollt, zahle ich Euch ein hübsches Sümmchen für Eure Hilfe. Fangt südlich von hier in dem Lager an, das sie in der Nähe des kleinen Bollwerks aufgeschlagen haben. Wenn Ihr stark genug seid, könnt Ihr mir vielleicht bei meinem vordringlichen Ziel helfen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ich bin erstaunt, dass Ihr so schnell mit ihnen fertig geworden seid. Danke.\n\nIch habe noch niemanden getroffen, der den Scharlachroten Kreuzzug und dessen Methoden gutgeheißen hätte. Ich glaube so sehr wie jeder andere in Stormwind an das Licht, sie aber haben bewiesen, dass sie nur alle töten wollen, die nicht treu zu ihrer Bewegung stehen ... selbst Unschuldige.", rewards = "Ihr bekommt:\n\n"},
[6021] = {title = "Zaeldarr der Ausgestoßene", objective = "Bringt Zaeldarrs Kopf zu Verwalter Alen in der Kapelle des hoffnungsvollen Lichts.", description = "Könnt Ihr Euch vorstellen, dass wir uns nach dem ganzen Ärger in den Pestländern... jetzt auch noch um Diebe sorgen müssen? Nicht einfach gewöhnliche Diebe, Troll-Diebe.\n\nUnd nicht einfach gewöhnliche Troll-Diebe. Tote Troll-Diebe!\n\nSie werden von diesem großen toten Troll namens Zaeldarr dem Ausgestoßenen angeführt, kommen nachts hierher und stehlen Leichen aus der Grube unten. Dann schaffen sie sie zu ihrem üblen Versteck für tote Trolle - dem Tiefgewölbe im Westen.\n\nGeht dorthin und schaltet Zaeldarr aus, <Name>. Ich habe seine Schandtaten satt!", progress = "Habt Ihr das Versteck gefunden, <Name>? Habt Ihr Zaeldarr ausgeschaltet?", completion = "Sehr schön, Ihr habt ihn! Und ich hoffe, Ihr habt auch seiner Bande eine Lektion erteilt!", rewards = "Ihr bekommt:\n\n"},
[6022] = {title = "Töten zu einem bestimmten Zweck", objective = "Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis.", description = "Ihr tötet zu einem bestimmten Zweck, solange Ihr in meiner Siedlung seid.\n\nEure erste Aufgabe ist es, meine Hunde zu füttern.\n\nNehmt diesen Mörser nebst Stößel und begebt Euch zu Corins Kreuzung. Dort angekommen findet Ihr Mitglieder der Geißel, die Ihr töten könnt, in recht großer Anzahl.. Aus ihren frischen Kadavern benötige ich lebendige Fäulnis. Nehmt diese lebendige Fäulnis, zermahlt sie im Mörser und lasst sie ruhen, bis sie gerinnt. Bringt die geronnene Fäulnis hierher.\n\nUnd bedenkt, Schwachkopf, dass lebendige Fäulnis der Untoten nicht lange 'lebendig' bleibt. Ihr müsst sie schnell töten!", progress = "Weint Ihr etwa? Wenn Euch das zu 'anstrengend' ist, oh 'Held', dann rate ich Euch, kehrt zur Dunklen Fürstin zurück und erzählt ihr von der schrecklichen Behandlung, die Euch auf meinem Bauernhof zuteil wurde.\n\nUnd jetzt geht mir aus den Augen!", completion = "Enttäuschend. Ich hatte gehofft, ich würde stattdessen Euch an meine Hunde verfüttern können.\n\n&lt;Nathanos seufzt.&gt;\n\nNa, wenigstens haben sie etwas zu fressen.", rewards = "Ihr bekommt:\n\n"},
[6023] = {title = "Offene Rechnungen", objective = "Besiegt Jägerin Radley und Chevalier Durgen, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt.", description = "Meine wahre Mission bestand darin, die äußeren Kräfte des Scharlachroten Kreuzzugs zu schwächen und dann Hearthglen zu infiltrieren, damit ich ihre Zahl abschätzen kann. In meiner Verfassung kann ich das immer noch nicht allein, vielleicht dürfte ich Euch ja erneut um Eure Unterstützung bitten, <Name>? Bevor ich entdeckt wurde, konnte ich die Informationen sammeln, dass der Kreuzzug zwei wichtige Mitglieder hat, die das Rückgrat ihrer Streitkräfte außerhalb der Stadt bilden: Jägerin Radley und Chevalier Durgen. Tötet sie, das bringt uns schon weiter. Sie müssten am Pass von Hearthglen außerhalb der Stadtgrenze sein.", progress = nil, completion = "Danke, &lt;Name&gt;. Ihr habt mir mehr geholfen als ich hoffen durfte. Die Luft hier scheint mir die Willenskraft auszusaugen. Ich bin müde und spüre, dass es sich nicht bessern wird, solange ich hier bin.\n\nIch habe wirklich keine Ahnung, wie ich nach Hearthglen hineingelangen und melden soll, wie stark die Präsenz des Scharlachroten Kreuzzugs dort ist.\n\nAber das ist ein anderes Thema. Bevor Ihr geht, hier, nehmt dies... als Bezahlung für Eure Hilfe. Nochmals danke.", rewards = "Ihr bekommt:\n\n"},
[6024] = {title = "Hameyas Bitte", objective = "Tötet Spitzel Hameya. Benutzt seinen Schlüssel bei dem Erdhaufen hinter dem Tiefgewölbe.", description = "Tötet mich. Bevor es zu spät ist.\n\nIch bin Hameya. Auf der Reise nach Zul'Mashar aßen meine Geschwister und ich verdorbenes Fleisch... und wir veränderten uns. Wir sind infiziert.\n\nIch spüre bereits die Worte des Lichs, der mich bedrängt, dass ich nach Zul'Mashar gehen und noch mehr von meinem Volk infizieren soll. Ich kann nicht widerstehen, daher verfasste ich diese Schriftrolle, ehe es um meine Willenskraft geschehen ist.\n\nIch habe hinter dieser Gruft eine Truhe neben einem Wagen in der Erde vergraben, aber nur mein Schlüssel kann sie öffnen. Ich habe den Schlüssel. Wenn Ihr meinen Schatz möchtet, sucht mich.\n\nTötet mich. Bevor es zu spät ist.", progress = "Die hier vergrabene Truhe ist fest verschlossen.", completion = "Hameyas Truhe wurde geöffnet!!!", rewards = "Ihr bekommt:\n\nHameyas TöterHameyas Umhang"},
[6025] = {title = "Offene Rechnungen", objective = "Geht nach Hearthglen, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Deepshadow in den Westlichen Pestländern zurück.", description = "Was? Wirklich? Ihr möchtet noch mehr wissen? Aber Ihr habt bereits so viel für mich getan, <Name>. Ich kann Euch unmöglich darum bitten, an meiner statt nach Hearthglen zu gehen.\n\nSeid Ihr sicher, <Name>? Hearthglen ist viel gefährlicher als der Pass - ich kann Euch weder Schutz noch Informationen geben, was Ihr da vorfinden könntet.\n\nAlso, wenn Ihr wirklich bereit seid, mir zu helfen, dann geht in die Stadt und sucht eine erhöhte Stelle, von der aus Ihr einen guten Überblick habt. Dort könnt Ihr ihre Zahl abschätzen und mir dann Bericht erstatten. Aber seid vorsichtig...", progress = nil, completion = "Ihr habt es geschafft, &lt;Name&gt;! Danke!\n\nIch kehre zu Elling zurück... Ich meine nach Stormwind, so schnell ich kann. Hier, nehmt diese Münze, das ist das Mindeste, was ich für Euch tun kann. Ihr macht Eurem Volk Ehre, &lt;Name&gt;. Habt Dank, und viel Glück.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6026] = {title = "Das ist viel verlangt", objective = "Smokey LaRue möchte, dass Ihr 2 Thoriumbarren, 1 Goldrute, 8 hochexplosive Bomben und 8 instabile Auslöser beschafft.\n\nFür diese Gegenstände müsst Ihr einen Schmied und einen Ingenieur finden.", description = "Diese Leute von der Argentumdämmerung haben den alten Smokey beauftragt, ein paar Abrissarbeiten für sie durchzuführen. Smokeys Mama hat keinen Trottel großgezogen. Wenn bares Gold auf den Tisch gelegt wird, ist Smokey stets zu Diensten. Das ist mein Motto!\n\nIch wäre bereit, den Profit mit Euch zu teilen, wenn Ihr mir ein wenig zuarbeiten wollt. Das ist der Plan: Ich geh rüber in den Pestwald und kennzeichne die Gebäude, die abgerissen werden müssen. Ihr sammelt die Komponenten für die Bomben. Wir treffen uns hier wieder, wenn Ihr alles habt. Abgemacht?", progress = "Vertraut dem alten Smokey, <Volk>. Es wird sich lohnen. Die Leute von der Argentumdämmerung machen kein Gewese, was Bezahlung angeht.", completion = "Ich bezahle Euch eine Hälfte gleich und die andere, wenn die Aufgabe erledigt ist.", rewards = "Ihr bekommt:\n\n"},
[6027] = {title = "Buch der Uralten", objective = "Beschafft das 'Buch der Uralten' und kehrt zu Azore Aldamort im Turm von Ethel Rethor zurück.", description = "<Name>, ich vertraue Euch den Edelstein der Schlange an. Legt diesen Edelstein auf der Insel Ranazjar nordwestlich von hier in die Hand der Schlangenstatue. Dadurch wird jener gerufen, der das 'Buch der Uralten' beschützt. Dieses Buch birgt die Geheimnisse der Naga. Geheimnisse, die seit Jahrhunderten gewahrt werden. Bringt mir dieses Buch, dann werden wir mehr über unsere schuppigen Widersacher erfahren!", progress = "Ah, <Name>! Schön, Euch zu wiederzusehen. Habt Ihr das 'Buch der Uralten'?", completion = "Das lange verschollene 'Buch der Uralten'! Ich werde dafür sorgen, dass der Hohe Rat dieses Buch bekommt. Ihr habt heute Großes vollbracht, und dafür muss man Euch danken... wie man einem Helden dankt!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSeidenbandmanschettenRundgeschliffene Metallschiftung\n\nIhr bekommt außerdem:\n\n"},
[6028] = {title = "Der Everlook-Bericht", objective = "Bringt den Everlook-Bericht zu Argentumoffizier Pureheart im Chillwind-Lager in den westlichen Pestländern.", description = "Ich suche ein verantwortungsbewusstes Individuum, das mir in einer kleinen, aber dennoch wichtigen Angelegenheit hilft. Ich bin hier als Vertreter der Argentumdämmerung und ihrer Interessen in der Lokalverwaltung von Everlook. Ich muss Argentumoffizier Pureheart im Chillwind-Lager einen Fortschrittsbericht zukommen lassen. Das ist weit entfernt von hier am südlichen Rand der Westlichen Pestländer.\n\nWenn ich so kühn sein darf - dies wäre eine perfekte Möglichkeit, Euch meiner Vorgesetzten vorzustellen und vielleicht etwas Arbeit von ihr zu bekommen!", progress = "Seid gegrüßt, <Klasse>. Im Namen der Argentumdämmerung biete ich Euch Sicherheit und Unterkunft, solange Ihr hier im Chillwind-Lager seid. Vielleicht habe ich auch ein bisschen Arbeit für Euch...", completion = "Gregor ist außerordentlich findig. Er hat schon seit geraumer Zeit mit dem Steamwheedle-Kartell zu tun und ist ein Experte in der 'Kunst' von Goblin-Verhandlungen geworden. Es stimmt zwar, dass die Goblins weitgehend denen mit den größten Geldbörsen gegenüber loyal sind, aber sie kennen und achten auch den Wert der Diplomatie. Sie bringt ihnen immerhin Kunden ein, die wiederkommen ...\n\nWie auch immer, die Argentumdämmerung dankt Euch für Eure Bemühungen. Bitte nehmt dies mit unserem Dank.", rewards = "Ihr bekommt:\n\n"},
[6029] = {title = "Der Everlook-Bericht", objective = "Bringt den Everlook-Bericht zu Argentumoffizier Garush im Bollwerk in den Westlichen Pestländern.", description = "Ich suche ein verantwortungsbewusstes Individuum, das mir in einer kleinen, aber dennoch wichtigen Angelegenheit hilft. Ich bin hier als Vertreter der Argentumdämmerung und ihrer Interessen in der Lokalverwaltung von Everlook. Ich muss Argentumoffizier Garush beim Bollwerk einen Fortschrittsbericht zukommen lassen; das ist weit entfernt von hier am westlichen Rand der Westlichen Pestländer, östlich von Tirisfal.\n\nWenn ich so kühn sein darf - dies wäre eine perfekte Möglichkeit, Euch meinem Vorgesetzten vorzustellen und vielleicht etwas Arbeit von ihm zu bekommen!", progress = "Seid gegrüßt, <Klasse>. Im Namen der Argentumdämmerung biete ich Euch Sicherheit und Unterkunft, solange Ihr hier im Bollwerk seid. Ich könnte Euch auch die Möglichkeit bieten, für eine Sache zu kämpfen, für die es sich zu kämpfen lohnt!", completion = "Gregor ist außerordentlich findig für einen Menschen. Er hat schon seit geraumer Zeit mit dem Steamwheedle-Kartell zu tun und ist ein Experte in der 'Kunst' von Goblin-Verhandlungen geworden. Es stimmt zwar, dass die Goblins weitgehend denen mit den größten Geldbörsen gegenüber loyal sind, aber sie kennen und achten auch den Wert der Diplomatie. Sie bringt ihnen immerhin Kunden ein, die wiederkommen ...\n\nWie auch immer, die Argentumdämmerung dankt Euch für Eure Bemühungen. Bitte nehmt dies mit unserem Dank.", rewards = "Ihr bekommt:\n\n"},
[6030] = {title = "Fürst Nicholas Zverenhoff", objective = "Bringt das Buch 'Studien zur Geistersuche' zu Fürst Nicholas Zverenhoff in der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Ein einsiedlerisches Medium namens Umbranse, das in dieser Gegend ansässig ist, hat der Argentumdämmerung ein literarisches Meistwerk geschenkt... es handelt sich vermutlich um die größte Sammlung mündlicher Überlieferungen, die je zu Papier gebracht wurde.\n\nFürst Nicholas Zverenhoff, einer der angesehensten Anführer der Dämmerung, ist ein brillanter Sprachwissenschaftler. Könntet Ihr ihm das für mich bringen - natürlich gegen eine Belohnung? Bei der Kapelle des hoffnungsvollen Lichts, tief im östlichen Teil der Östlichen Pestländer - da hält er sich gerade auf.", progress = "Möge das Licht Euch in diesen gefährlichen Zeiten leiten, <Klasse>. Was führt Euch zu diesem Fanal der Hoffnung inmitten von Dunkelheit und Verzweiflung?", completion = "Das... ist ein ganz besonderes Buch, das Ihr mir da gebracht habt. Ich würde Euch gern sagen, dass 'besonders' in diesem Fall 'einzigartig und höchstwahrscheinlich lehrreich' bedeutet, doch das wird man sehen.\n\n\"Ooooooh?\" Wer sich so etwas ausdenkt, kann doch nicht bei klarem Verstand sein?\n\nAber ich habe von diesem Umbranse gehört, von dem Gregor sprach, daher ist das hier nicht ganz wertlos. Ich tue mein Bestes, es zu entziffern. Und was Euch angeht... bitte nehmt dies... mit freundlichen Grüßen der Argentumdämmerung. Da Ihr schon mal hier seid, vielleicht könnt Ihr uns noch bei anderen Dingen unterstützen.", rewards = "Ihr bekommt:\n\n"},
[6031] = {title = "Runenstoff", objective = "Bringt 30 Runenstoff zu Meilosh in der Holzschlundfeste.", description = "Wir in der Holzschlundfeste sind eigentlich ganz zufrieden. Wir mögen keine Fremden. Das ist gut für uns, aber schlecht für das Geschäft.\n\nEs ist noch nicht lange her, da kam eine Nachtelfenfreundin, die einen Runenumhang trug, auf die Holzschlundfeste. Runenstoff ist bei uns selten, aber der Umhang war so edel, dass mein Volk jetzt von mir verlangt, mehr Runenstoffkleidung zu fertigen.\n\nWerdet Ihr mir Runenstoff bringen? Wenn Ihr mir ausreichend beschafft, gebe ich Euch etwas im Tausch dafür.", progress = "Habt Ihr den Runenstoff? Mein Volk ist ganz gierig nach weiteren Kleidungsstücken aus Runenstoff!", completion = "Ah, Ihr habt den Stoff. Was für ein herrliches Material!\n\nDanke, &lt;Name&gt;. Ihr seid ein wahrer Freund. Bitte nehmt dies als Gegenleistung.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchattenhautschiftungBricksteel-Stulpen\n\nIhr bekommt außerdem:\n\n"},
[6032] = {title = "Hochheiliger Stoff", objective = "Bringt 2 Mondstoff zu Meilosh in der Holzschlundfeste.", description = "Die Einwohner der Holzschlundfeste mögen das Gefühl von Runenstoff auf der Haut, aber er ist nichts Hochheiliges für uns. Mondstoff dagegen ist hochheilig.\n\nBringt mir einen kleinen Vorrat dieses heiligen Stoffs und ich lehre Euch eine geheime Schneidertechnik.", progress = "Habt Ihr den Mondstoff dabei, <Name>?", completion = "Ah, sehr gut. Dieser Mondstoff wird für Gewänder benutzt, die für unser Volk hochheilig sind. Danke, &lt;Name&gt;. Jetzt werde ich Euch ausbilden.", rewards = "Ihr erlernt:\n\nMondstoffstiefel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nMondstoffstiefel\n\nIhr bekommt außerdem:\n\n"},
[6041] = {title = "When Smokey Sings, I Get Violent", objective = "Reist in den Pestwald, nordwestlich der Hoffnung des Lichts. Zerstört 8 Geißelbauwerke, indem Ihr Smokeys spezielles Präparat am Mal der Zerstörung in jedem Bauwerk benutzt. Smokey hat die Ziggurats und Schlachthäuser markieren lassen.\n\nWenn ihr die Bombe gelegt habt, dann verlasst das Bauwerk und staunt über Euer Geschick.\n\nÜbrigens, Smokeys spezielles Präparat ist recht... instabil.", description = "Während Ihr die Vorräte gesammelt habt, habe ich einige meiner Leute die Geißelbauwerke kennzeichnen lassen, die wir abreißen müssen.\n\nSo ist der Plan: Ich gebe Euch zehn Stecken meines speziellen Präparats. Ihr bringt sie rüber in den Pestwald und platziert sie in den Geißelbauwerken, die für die Sprengung markiert wurden.\n\n<Smokey schnippt mit den Fingern.>\n\nBing! So einfach ist das.", progress = nil, completion = "Ihr seid viel dunkler als ich in Erinnerung habe. Der Look steht Euch nicht schlecht, ein Look, der sagt: 'Ich wurde von einer hochexplosiven Bombe angesengt.'\n\n&lt;Smokey lacht.&gt;\n\nNa, egal! Hier ist Euer Anteil an der Beute. Ich habe noch eine Kleinigkeit dazu gelegt, die die Verbrennungen lindert.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSmokeys Sprengstoff-SchleuderSmokeys Feuerspucker\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\nFeuchtes HandtuchSmokeys Tuch"},
[6042] = {title = "Die kleinen Ärgernisse des Un-Lebens", objective = "Erschlagt 20 giftige Seuchenfledermäuse und 10 monströse Seuchenfledermäuse. Kehrt zu Nathanos Blightcaller zurück, wenn Ihr fertig seid.", description = "Man kann keine zwei Schritte von diesem Hof runter, ohne auf eine dieser grässlichen Fledermäuse zu stoßen. Ich möchte die Hunde ausführen und die Geißel abschlachten können, ohne dass mich diese elenden, schmutzigen Fledermäuse behelligen. Ich habe Wichtigeres mit meiner Zeit anzufangen, als tagein, tagaus sinnlos Fledermäuse zu töten. Ihr allerdings nicht.\n\nWas? Eure Ausbildung? Das ist Eure Ausbildung! Jetzt geht mir aus den Augen und kommt erst zurück, wenn Ihr eine ordentliche Menge dieser geflügelten Dämonen getötet habt! Enttäuscht mich nicht.", progress = nil, completion = "Unglaublich, was ein wenig Zorn und Wut doch bewirken können.", rewards = "Ihr bekommt:\n\n"},
[6061] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen ausgewachsenen Ebenenschreiter zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.", description = "Für uns als Tauren ist es wichtig, dass wir den Traditionen unserer Vorfahren folgen und gegen mächtige Kreaturen kämpfen. Wenn wir diese Kreaturen bezwingen, können wir ihre Geister aufnehmen und näher bei der Erdenmutter sein.\n\nAuf dieselbe Weise hilft es uns, eins mit der Natur zu werden, wenn wir ein Tier zähmen, damit es an unserer Seite kämpft. Ihr werdet auch irgendwann lernen, ein Tier Eurer Wahl zu zähmen. Aber alles erfordert Übung und Ihr müsst noch viel lernen. Nehmt als erstes diese Zähmrute. Ihr müsst einen ausgewachsenen Ebenenschreiter zähmen.", progress = "Übt Eure Fertigkeiten, <Name>. Zähmt den ausgewachsenen Ebenenschreiter.", completion = "Die Erdenmutter hat mir Zeichen geschickt. Ihr habt Eure Sache gut gemacht.", rewards = "Ihr bekommt:\n\n"},
[6062] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen scheckigen Terroreber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", description = "Es ist eine bewundernswerte Fertigkeit, wenn man über die Natur gebietet. Als Jäger müsst Ihr lernen, wie man Macht und Kraft benutzt, die jeder Kreatur Eurer Wahl innewohnt.\n\nEs ist nicht einfach, Kontrolle über ein Tier zu erlangen. Ihr müsst diese Aufgabe mit großer Entschlossenheit verfolgen.\n\nAls erste Aufgabe nehmt diese Zähmrute und zähmt damit einen scheckigen Terroreber. Ihr findet sie in der Nähe von Klingenhügel. Übt Eure Fertigkeiten im Kampf mit dem Eber an Eurer Seite und kommt dann zu mir zurück.", progress = "Viel Glück, junger <Klasse>.", completion = "Ihr habt Eure Sache gut gemacht, &lt;Name&gt;. Ich glaube, Ihr seid bereit für die nächste Aufgabe.", rewards = "Ihr bekommt:\n\n"},
[6063] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen Waldweberlauerer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", description = "Als Jäger dürft Ihr niemals die Verantwortung vergessen, die Ihr tragt. Die Natur ist eine Kraft, die sich nicht Euren Wünschen beugt. Man muss sie respektieren und anerkennen als etwas Stärkeres als die eigene Existenz.\n\n<Name>, Ihr müsst beweisen, dass Ihr das verstanden habt, bevor Ihr die Fähigkeit erwerben könnt, Euch ein Tier als Gefährten zu zähmen.\n\nEure erste Aufgabe ist es, diese Zähmrute zu nehmen. Mit ihr könnt Ihr einen Waldweberlauerer zähmen. Zähmt ihn und übt Eure Fertigkeiten als Jäger.", progress = "Ihr werdet lernen, <Name>, und eines Tages ein großer <Klasse> sein.", completion = "Exzellent, &lt;Name&gt;! Ihr lernt wirklich sehr schnell.", rewards = "Ihr bekommt:\n\n"},
[6064] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen großen Klippeneber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildheart in Kharanos.", description = "Hallo, <Bursche/Mädchen>! Ihr wollt also wissen, wie Ihr ein eigenes Tier bekommen könnt?\n\nGut, dann lasst uns anfangen. Wenn es um das Jagen geht, dann ist nichts wichtiger als Eure Ausrüstung, aber wir können ein andermal über meinen neuen Schrapnell-Blaster sprechen. Konzentrieren wir uns vorerst auf etwas, das Euch gewiss interessiert: ein Tier!\n\nAm besten lernt Ihr, wenn Ihr verschiedene Kreaturen als Gefährten ausprobiert und herausfindet, welche Ihr mögt. Sucht also einen großen Klippeneber und benutzt dann diese Zähmrute, um ihn zu zähmen.", progress = "Keine Bange, Bursche! Ihr könnt ein paar ausprobieren, ehe Ihr Euch für eines entscheiden müsst.", completion = "Ich weiß, ich weiß, Ihr fragt Euch, was als nächstes kommt, was?!", rewards = "Ihr bekommt:\n\n"},
[6065] = {title = "Der Weg des Jägers", objective = "Sprecht mit Yaw Sharpmane in Bloodhoof.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Yaw Sharpmane in Bloodhoof aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[6066] = {title = "Der Weg des Jägers", objective = "Sprecht mit Yaw Sharpmane in Bloodhoof.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Yaw Sharpmane in Bloodhoof aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[6067] = {title = "Der Weg des Jägers", objective = "Sprecht mit Yaw Sharpmane in Bloodhoof.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Yaw Sharpmane in Bloodhoof aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[6068] = {title = "Der Weg des Jägers", objective = "Sprecht mit Thotar in Klingenhügel.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Thotar in Klingenhügel besuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", progress = nil, completion = "Ja, ich glaube auch, Ihr seid bereit...", rewards = "Ihr bekommt:\n\n"},
[6069] = {title = "Der Weg des Jägers", objective = "Sprecht mit Thotar in Klingenhügel.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Thotar in Klingenhügel besuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", progress = nil, completion = "Ja, ich glaube, Ihr seid bereit für die Ausbildung...", rewards = "Ihr bekommt:\n\n"},
[6070] = {title = "Der Weg des Jägers", objective = "Sprecht mit Thotar in Klingenhügel.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Thotar in Klingenhügel besuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", progress = nil, completion = "Ja, ich glaube, es ist an der Zeit, dass ich Euch ausbilde...", rewards = "Ihr bekommt:\n\n"},
[6071] = {title = "Der Weg des Jägers", objective = "Sprecht mit Dazalar in Dolanaar.", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", progress = nil, completion = "Ja, es ist an der Zeit, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"},
[6072] = {title = "Der Weg des Jägers", objective = "Sprecht mit Dazalar in Dolanaar.", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[6073] = {title = "Der Weg des Jägers", objective = "Sprecht mit Dazalar in Dolanaar.", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", progress = nil, completion = "Ja, es ist an der Zeit, Euch auszubilden...", rewards = "Ihr bekommt:\n\n"},
[6074] = {title = "Der Weg des Jägers", objective = "Sprecht mit Grif Wildheart in Kharanos.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Grif Wildheart in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[6075] = {title = "Der Weg des Jägers", objective = "Sprecht mit Grif Wildheart in Kharanos.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Grif Wildheart in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", progress = nil, completion = "Ja, ich glaube, es ist an der Zeit, dass Ihr ausgebildet werdet...", rewards = "Ihr bekommt:\n\n"},
[6076] = {title = "Der Weg des Jägers", objective = "Sprecht mit Grif Wildheart in Kharanos.", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Grif Wildheart in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", progress = nil, completion = "Ja, &lt;Klasse&gt;, es ist Zeit...", rewards = "Ihr bekommt:\n\n"},
[6081] = {title = "Die Ausbildung des Tiers", objective = "Sprecht mit Ormak Grimshot in Orgrimmar.", description = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es auszubilden.\n\nReist nach Orgrimmar. Dort müsst Ihr mit Ormak Grimshot sprechen, einem unserer angesehensten Jäger. Er wird Euch die Fähigkeit verleihen, Euer neues Tier auszubilden. Ihr findet ihn nahe der Halle der Kriegerhelden.\n\nViel Glück, <Name>.", progress = nil, completion = "Ein junger &lt;Klasse&gt; seid Ihr, ich verstehe. Ja, ich gewähre Euch die Fertigkeiten, die Ihr braucht, um Euer neues Tier auszubilden und zu führen. Ihr werdet Eurem Tier nicht nur neue Fähigkeiten beibringen können, sondern Ihr könnt es auch füttern und wiederbeleben, sollte es im Kampf fallen.\n\nGeht jetzt, &lt;Klasse&gt;. Wir sprechen uns zu einem späteren Zeitpunkt wieder.", rewards = "Ihr erlernt:\n\nAusbildungsstunde\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWildtierausbildung\n\nIhr bekommt außerdem:\n\n"},
[6082] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen gepanzerten Skorpid zu zähmen. Übt Eure Fertigkeiten und kehrt zu Thotar in Klingenhügel zurück.", description = "Die letzte Kreatur, die Ihr zähmen müsst, wird dasselbe mit Euch versuchen: der gepanzerte Skorpid. Er schlägt schnell und selbstbewusst zu. Eine solche Macht zu kontrollieren ist Euer Schicksal als Jäger.\n\nWenn Ihr zurückkehrt verleihe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl zu zähmen. Diese Kreatur wird Euren Befehlen gehorchen. Unter Eurer Kontrolle wird Euer Tier an Eurer Seite Erfahrung sammeln. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.", progress = "Konntet Ihr den Skorpid zähmen?", completion = "Ihr habt gelernt, was ich Euch beibringen konnte, &lt;Name&gt;. Es ist Zeit, dass Ihr das Gelernte anwendet und Euch ein eigenes Tier wählt.\n\nHier, bitte schön, &lt;Name&gt;. Ich gebe Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken. Benutzt Eure neuen Fertigkeiten voller Stolz; Ihr habt sie Euch verdient.", rewards = "Ihr erlernt:\n\nZähmen- Unterrichtsstunde\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWildtier zähmen\n\nIhr bekommt außerdem:\n\n"},
[6083] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen Brandungskriecher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", description = "Der Vorteil, den Euch ein Tier gegen Eure Rivalen bietet, wird zur Kenntnis genommen, <Name>! Wenn Ihr Kontrolle über eine andere Kreatur erlangt, erhöht Ihr Eure eigene Kraft. Euer Tier muss sozusagen Euer verlängerter Arm werden.\n\nDie nächste Aufgabe führt Euch vom Land weg. Ihr findet die nächste Kreatur in den Gewässern vor der Küste. Sucht jenseits von Sen'jin nahe den Echoinseln. Sucht nach einem lebhaften Krebs, der Brandungskriecher genannt wird. Benutzt die Zähmrute, um ihn zu zähmen und übt dann Eure Fertigkeiten.", progress = "Ihr müsst üben, damit Ihr die Fertigkeiten erlangt, die Ihr braucht, um Euer Tier wirksam zu kontrollieren. Habt Ihr schon einen Brandungskriecher gezähmt?", completion = "Ihr lernt schnell, &lt;Name&gt;. Das habt Ihr gut gemacht.", rewards = "Ihr bekommt:\n\n"},
[6084] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen Schneeleoparden zu zähmen. Übt Eure Fertigkeiten und kehrt dann zu Grif Wildheart in Kharanos zurück.", description = "Diese Klippeneber sind recht bullig. Vielleicht möchtet Ihr etwas mit ein wenig mehr Grazie? Na gut, da hab ich genau das Richtige. Südlich und östlich von hier findet Ihr große weiße Katzen, die man Schneeleoparden nennt. Genau wie bei einem elegant geschnitzten Gewehr verbirgt sich hinter dem wunderschönen Äußeren ein kräftiger Kämpfer, der extremen Schaden zufügen kann. Ihr werdet feststellen, dass sie wesentlich agiler und schneller als Euer gezähmter Eber sind.\n\nNehmt diese Zähmrute und findet heraus, wie Euch der Schneeleopard gefällt.", progress = "Was haltet Ihr von dem Schneeleoparden, <Name>?", completion = "Wenn ich glaube, dass Ihr genug gelernt habt, gewähre ich Euch die Fähigkeit, jedes Tier zu wählen, das Euch gefällt.", rewards = "Ihr bekommt:\n\n"},
[6085] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen Eisklauenbären zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildheart in Kharanos.", description = "Vielleicht hättet Ihr gern eine Kreatur, die etwas mehr besitzt als nur rohe Kraft? Der Eisklauenbär ist ein ausgezeichneter Gefährte für einen angehenden Jäger wie Euch und östlich von Kharanos zu finden. Hier ist die Zähmrute. Probiert dieses Geschöpf als Euer Tier aus und findet heraus, wie es Euch gefällt!\n\nWenn Ihr zurückkehrt, gebe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man sie ganz nach Belieben ruft und wegschickt.", progress = "Habt Ihr den Eisklauenbären schon gezähmt?", completion = "Hier, bitte schön, &lt;Name&gt;. Ich geb Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken.\n\nSucht Euch ein gutes, treues Tier und genießt die Jagd!", rewards = "Ihr erlernt:\n\nZähmen- Unterrichtsstunde\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWildtier zähmen\n\nIhr bekommt außerdem:\n\n"},
[6086] = {title = "Die Ausbildung des Tiers", objective = "Sprecht mit Belia Thundergranite in Ironforge.", description = "<Name>, Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr müsst die Fertigkeiten erlangen, es auszubilden.\n\nReist nach Ironforge und sucht die Halle der Waffen. Dort müsst Ihr mit Belia Thundergranite sprechen, einer unserer angesehensten Jägerinnen. Sie gibt Euch die Macht, Euer neues Tier auszubilden, also macht Euch auf den Weg, <Bursche/Mädchen>.\n\nBelia ist recht umgänglich, Ihr findet gewiss ihre Zustimmung. Viel Glück, <Name>.", progress = nil, completion = "Ein neuer Rekrut, hm? Ich sehe, Ihr seid auf dem Weg, ein großer &lt;Klasse&gt; zu werden.\n\nJa, ich kann Euch die Fertigkeiten verleihen, die Ihr braucht, um Euer Tier auszubilden und zu führen. Ihr werdet Eurem Tier nicht nur neue Fähigkeiten beibringen können, sondern Ihr könnt es auch füttern und wiederbeleben, sollte es im Kampf fallen.\n\nVergesst nicht, Euer neues Tier wird Euch stets zu Diensten sein, wenn Ihr es respektiert und gut behandelt. Dann wird Euer Tier Euer treuester Freund.", rewards = "Ihr erlernt:\n\nAusbildungsstunde\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWildtierausbildung\n\nIhr bekommt außerdem:\n\n"},
[6087] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen Präriepirscher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.", description = "Ihr besitzt einen feurigen Geist, Jäger, und brennt schon auf Eure nächste Herausforderung.\n\nAls nächste Aufgabe müsst Ihr einen Wolf, der als Präriepirscher bekannt ist, zum Gefährten gewinnen. Diese Kreatur ist flink und furchtlos. Wenn Ihr diese Bestie als Euer Tier wollt, müsst Ihr diese Eigenschaften ebenfalls erlangen.\n\nIm Kampf werdet Ihr lernen, wie Ihr und Euer Tier ein Team werdet. Letztendlich müsst Ihr wie ein Wesen handeln, Muskel an Muskel.\n\nHier habt Ihr die Zähmrute, <Name>. Zähmt einen Präriepirscher und übt Eure Fertigkeiten.", progress = "Habt Ihr schon einen Präriepirscher gefunden?", completion = "Ja... Die Erdenmutter glaubt, Ihr seid bereit für die nächste Lektion.", rewards = "Ihr bekommt:\n\n"},
[6088] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen Sturzflieger zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.", description = "Die letzte Aufgabe, die ich für Euch habe, verlangt von Euch, dass Ihr eine Kreatur zähmt, die den Himmel bewohnt. Der Sturzflieger ist ein schwieriger Gegner, aber als Euer Verbündeter gibt er Euch seine scharfen Angriffe und seine bedrohliche Präsenz.\n\nWenn Ihr zurückkehrt gebe ich Euch durch den Willen der Erdenmutter die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl als Gefährten zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.", progress = "Ihr werdet bald bereit sein, <Name>.", completion = "Ihr habt gelernt, was ich Euch beibringen konnte, &lt;Name&gt;. Möge der Segen der Erdenmutter Euch bei der Wahl Eures Tiers leiten.\n\nHier, bitte schön, &lt;Name&gt;. Ich gebe Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken. Benutzt Eure neuen Fertigkeiten voller Stolz und ehrt die Erdenmutter.", rewards = "Ihr erlernt:\n\nZähmen- Unterrichtsstunde\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWildtier zähmen\n\nIhr bekommt außerdem:\n\n"},
[6089] = {title = "Die Ausbildung des Tiers", objective = "Sprecht mit Holt Thunderhorn auf der Anhöhe der Jäger in Thunder Bluff.", description = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es zu trainieren.\n\nReist nach Thunder Bluff. Dort müsst Ihr mit Holt Thunderhorn sprechen, einem unserer angesehensten Jäger. Wenn er Euch für würdig befindet, gibt er Euch die Fähigkeit, Euer neues Tier auszubilden.\n\nHolt hat die mächtigsten und gefürchtetsten Bestien von Azeroth bezwungen und befehligt selbst viele starke Kreaturen. Seine Verbundenheit mit der Erdenmutter ist stark. Ihr könnt viel von ihm lernen. Viel Glück, <Name>.", progress = nil, completion = "Ein junger &lt;Klasse&gt; seid Ihr, ich verstehe. Ja, ich kann Euch die Fertigkeiten verleihen, die Ihr braucht, um Euer Tier auszubilden und zu führen. Ihr werdet Eurem Tier nicht nur neue Fähigkeiten beibringen können, sondern Ihr könnt es auch füttern und wiederbeleben, sollte es im Kampf fallen.\n\nGeht jetzt. Möge die Erdenmutter Euch auf Eurem Weg geleiten. Wir sprechen uns zu einem späteren Zeitpunkt wieder.", rewards = "Ihr erlernt:\n\nAusbildungsstunde\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWildtierausbildung\n\nIhr bekommt außerdem:\n\n"},
[6101] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmerrute, um einen pirschenden Nachtsäbler zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", description = "Auf die Vielfalt der Natur kann man sich verlassen, <Name>. Sie ist insofern vorhersehbar, dass sie niemals gleich bleibt. Sie ist in konstantem Wandel.\n\nDie Aufgaben, die ich Euch gebe, werden Euch helfen, die enormen Unterschiede der Kreaturen zu erkennen, die Ihr als Eure Gefährten wählen könnt.\n\nNehmt diese Zähmrute und zähmt damit einen der pirschenden Nachtsäbler, die im Süden zu finden sind. Übt Eure Fertigkeiten als Jäger. Dann werdet Ihr die Übereinstimmungen und Unterschiede der Natur begreifen.", progress = "Es liegt in der Natur jedes Nachtelfen, dass er das Gleichgewicht zwischen der Natur und sich selbst begreift.", completion = "Ich sehe, dass Ihr entschlossen seid und verstanden habt, was ich Euch gelehrt habe, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[6102] = {title = "Die Zähmung der Bestie", objective = "Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", description = "Ihr habt zwei Kreaturen gezähmt, die am Boden leben, jetzt müsst Ihr eine zähmen, die am Himmel dahinzieht. Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen, die man westlich von hier findet. Übt Eure Fertigkeiten mit dieser mächtigen Eule an Eurer Seite.\n\nWenn Ihr zurückkehrt gebe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl als Gefährten zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.", progress = "Ich bin stolz auf Eure Leistungen, <Name>. Habt Ihr die letzte Aufgabe vollendet, die ich Euch gab?", completion = "Ihr habt gelernt, was ich Euch beibringen konnte, &lt;Name&gt;. Lasst mich Euch noch einen Rat geben: Seid umsichtig, wenn Ihr Euer erstes Tier wählt. Soll es eine Kreatur des Landes, des Wassers oder des Himmels sein? Was auch immer, Euer Tier wird zweifellos eine ganze Weile bei Euch sein.\n\nHier, bitte schön, &lt;Name&gt;. Ich gebe Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken. Benutzt Eure neuen Fertigkeiten voller Stolz; Ihr habt sie Euch verdient.", rewards = "Ihr erlernt:\n\nZähmen- Unterrichtsstunde\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWildtier zähmen\n\nIhr bekommt außerdem:\n\n"},
[6103] = {title = "Die Ausbildung des Tiers", objective = "Sprecht mit Jocaste in der Enklave des Cenarius in Darnassus.", description = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es zu trainieren.\n\nReist nach Darnassus. Dort müsst Ihr mit Jocaste sprechen, einer unserer angesehensten Jägerinnen. Sie gibt Euch die Fähigkeit, Euer neues Tier auszubilden, also sputet Euch.\n\nJocaste mag einen strengen Eindruck machen, freut sich aber stets, wenn sie den Aufstieg eines neuen Jägers verfolgen kann. Behandelt sie mit Respekt, dann wird sie Euch ebenso begegnen. Viel Glück, <Name>.", progress = nil, completion = "Ein angehender &lt;Klasse&gt; seid Ihr, ich verstehe. Ja, ich kann Euch die Fertigkeiten verleihen, die Ihr braucht, um Euer Tier auszubilden und zu führen. Ihr werdet Eurem Tier nicht nur neue Fähigkeiten beibringen können, sondern Ihr könnt es auch füttern und wiederbeleben, sollte es im Kampf fallen.\n\nDenkt daran, &lt;Name&gt;, respektiert stets das Gleichgewicht und lebt in Ehrfurcht vor der Natur ringsum. Geht jetzt. Wir sprechen uns zu einem späteren Zeitpunkt wieder.", rewards = "Ihr erlernt:\n\nAusbildungsstunde\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWildtierausbildung\n\nIhr bekommt außerdem:\n\n"},
[6121] = {title = "Neue Lektionen", objective = "Reist nach Moonglade und sprecht mit Dendrite Starblaze im Dorf Nighthaven.", description = "Ihr seid jetzt bereit, alles über Gifte und die Macht zu lernen, die wir Druiden darüber haben, <Name>. Cenarius hat uns mit der Fähigkeit gesegnet, selbst die abscheulichsten Gifte mit einer Beschwörung auszutreiben. Mit dieser Gabe geht man nicht leichtfertig um... und damit Ihr diese Lektion lernt, müsst Ihr die Wirkung von Giften behandeln wie es ein Laie tun würde.\n\nReist nach Moonglade und sprecht mit Dendrite Starblaze. Er erwartet Eure Ankunft, um die Lektion zu beginnen.", progress = nil, completion = "Seid gegrüßt, junger &lt;Klasse&gt;, ich sehe mit Freuden, dass Ihr begierig seid, etwas über die Heilung von Vergiftungen zu lernen.\n\nFrüher wurden die meisten Druiden vorab geplanten Prüfungen unterzogen, doch das trifft auf Euch nicht zu. In Auberdine traten vermehrt Fälle von Tiervergiftungen auf und die Dorfbewohner konnten sie nicht heilen. Aus diesem Grund bat ein Repräsentant Moonglade um Hilfe. Wir schicken Euch zu ihrer Unterstützung dorthin. Dies ist keine Übung - es handelt sich um eine echte Aufgabe. Vergesst das nicht.", rewards = "Ihr bekommt:\n\n"},
[6122] = {title = "Die eigentliche Ursache", objective = "Benutzt das leere Gefäß bei Cliffspring Falls und nehmt eine Wasserprobe vom Höhleneingang bei den Wasserfällen.\n\nBringt das gefüllte Gefäß von Cliffspring Falls zu Alanndarian Nightsong nach Auberdine in Dunkelküste.", description = "Cliffspring Falls in Dunkelküste dient als wichtigste Trinkwasserquelle in der Region. Ich fürchte, jetzt ist es die primäre Ursache des Gifts, das der dortigen Fauna schadet, besonders dem Wild. Holt mit diesem Gefäß etwas Wasser vom Höhleneingang, aber seid vorsichtig, inzwischen hausen gefährliche Naga in einer Höhle bei den Wasserfällen.\n\nWenn Ihr es gefüllt habt, bringt es zu Alanndarian Nightsong in Auberdine. Sie bat um unsere Hilfe und Ihr werdet Euch gemeinsam mit ihr dieses Übels annehmen.", progress = "Seid Ihr vom Zirkel des Cenarius in Moonglade geschickt worden? Das ist wunderbar! Wir haben hier eine echte Krisensituation, was das Wild angeht, und sind dankbar für jedwede Hilfe.\n\nHabt Ihr die Probe des Wassers, wie Dendrite Starblaze sagte? Er informierte mich, dass Ihr eine besorgen würdet, damit wir gemeinsam ein Heilmittel finden ...", completion = "Bei Elune, dieses Wasser ist widerwärtig! Kein Wunder, dass das Wild krank ist.\n\nEtwas verunreinigt das Wasser und damit Dunkelküstes gesamten Wasservorrat. Man hat überall in der Gegend krankes Wild gesehen, nicht nur am Fluss. Das Wasser ist wahrscheinlich der Hauptgrund für die Ausbreitung der Krankheit, aber hier wirkt noch etwas anderes.\n\nDieses Wasser wird uns, ob Ihr es glaubt oder nicht, ein Heilmittel finden helfen. Während ich dieses Wasser untersuche benötige ich einige Zutaten für ein Heilmittel...", rewards = "Ihr bekommt:\n\n"},
[6123] = {title = "Das Heilmittel sammeln", objective = "Bringt 5 Erdwurzeln und 12 Lunarfungi zu Alanndarian Nightsong in Auberdine, damit sie eine Heilsalbe machen kann.", description = "Das Wasser wird Grundlage einer Heilsalbe sein, die ich für das Wild anrühre. Für die Heilwirkung benötige ich etwas Erdwurzel. Kräuterkundige wissen, wo man sie finden kann. Wenn wir Pech haben und Ihr keiner seid, müsst Ihr einen suchen, der uns weiterhilft.\n\nUnd der besseren Wirksamkeit wegen brauche ich etwas Lunarfungus. Es ist recht leicht, Lunarfungusblüten zu finden. In den Höhlen östlich von hier gedeihen sie reichlich. Moonkin, die neuerdings recht gereizt sind, hausen in diesen Höhlen, also seid vorsichtig.", progress = "Habt Ihr die Reagenzien bekommen, die ich für meine Salbe brauche? Das Wild wird von allein ganz bestimmt nicht wieder gesund, daher sollten wir uns besser beeilen!", completion = "Das ist gut, &lt;Name&gt;, so sehr, dass es für eine gehörige Portion Salbe reichen müsste - wenigstens so viel, dass eine Wirkung zu spüren ist.\n\nManchmal kann es recht schwer sein, ein Heilmittel für Gifte herzustellen, da nicht selten jedes einzelne ein ganz bestimmtes Gegenmittel erfordert. Stellt Euch vor, man könnte ein Gift durch Willenskraft heilen, ohne dass man sich Gedanken über die exakte Zusammensetzung des Gegenmittels machen müsste!\n\nUnd jetzt lasst mich daran arbeiten!", rewards = "Ihr bekommt:\n\n"},
[6124] = {title = "Heilung der Kranken", objective = "Benutzt die Tier-Heilsalbe bei 10 kranken Wildtieren rund um Dunkelküste. Das müsste sie heilen. Es wurde berichtet, dass krankes Wild südlich des Cliffspring, im Norden von Auberdine und bis hinunter in die südlichen Regionen von Dunkelküste, wo Ashenvale beginnt, aufgetaucht ist.", description = "Die Salbe, die ich aus den Reagenzien herstellen konnte, die Ihr mir gebracht habt, reicht für zehn Dosen, <Name>. Ich arbeite weiter mit den Dorfbewohnern zusammen und versuche mehr Salbe herzustellen. Derweil möchte ich, dass Ihr uns einen Vorsprung verschafft. Rund um Dunkelküste wimmelt es von krankem Wild. Heilt es mit der Salbe von seinem Übel.\n\nDendrite Starblaze in Moonglade wird ganz sicher mit Euch reden wollen, wenn Ihr fertig seid. Bitte übermittelt dem Zirkel des Cenarius Auberdines Dank... und lasst mich Euch persönlich für Eure Hilfe danken!", progress = nil, completion = "Ihr habt bei der Heilung des kranken Wilds von Dunkelküste wahre Wunder gewirkt. Es war das arglose Opfer einer größeren Besudelung und Verderbnis geworden, die sich über das Land ausbreitete. In Darnassus gibt es welche, die die Bedrohung ernst nehmen... und es gibt welche, die ignorieren die zunehmenden Zeichen... Ich hoffe, Ihr werdet nicht die Augen vor dem Offensichtlichen verschließen, &lt;Name&gt;.\n\nWie auch immer, Ihr habt Euren Wert als Freund der Natur und des Zirkels unter Beweis gestellt - nehmt dies als Symbol dafür.", rewards = "Ihr bekommt:\n\nSchleierstaub-Medizinbeutel"},
[6125] = {title = "Macht über Gift", objective = "Kehrt zu Mathrengyl Bearwalker in der Enklave des Cenarius in Darnassus zurück.", description = "Ihr habt gelernt, was es heißt, Vergiftungen ohne spirituelle Unterstützung zu heilen. Vergesst nicht, was andere auf sich nehmen müssen, wenn sie gegen Vergiftungen ankämpfen, wenn Ihr Eure neu erlangte Macht über Gift erhaltet.\n\nIhr solltet jetzt zu Mathrengyl Bearwalker in Darnassus zurückkehren, <Name>. Zweifellos hat er Euch wichtige Zauber beizubringen, da Ihr nun die Lektionen begriffen habt, die Ihr erhieltet.\n\nLebt wohl, junger Druide. Wir sprechen uns wieder.", progress = nil, completion = "Willkommen - ich verfolge Eure Fortschritte in dieser Lektion seit Eurem Aufbruch und muss gestehen, ich war überrascht, als ich von der Situation in Auberdine erfuhr. Dies erfordert weitere Untersuchungen, da die Freisetzung solcher Gifte in die Umwelt das Gleichgewicht empfindlich stört.\n\nIhr habt Euch unter großem Druck wacker gehalten. Dafür finde ich keine bessere Möglichkeit, als Euch mit permanenter Macht über Gift zu belohnen. Verwendet sie weise, &lt;Name&gt;... verwendet sie weise.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVergiftung heilen\n\nIhr bekommt:\n\n"},
[6126] = {title = "Neue Lektionen", objective = "Reist nach Moonglade und sprecht mit Dendrite Starblaze im Dorf Nighthaven.", description = "Ihr seid jetzt bereit, alles über Gifte und die Macht zu lernen, die wir Druiden darüber haben, <Name>. Cenarius hat uns mit der Fähigkeit gesegnet, selbst die abscheulichsten Gifte mit einer Beschwörung auszutreiben. Mit dieser Gabe geht man nicht leichtfertig um ... und damit Ihr diese Lektion lernt, müsst Ihr die Wirkung von Giften behandeln wie es ein Laie tun würde.\n\nReist nach Moonglade und sprecht mit Dendrite Starblaze. Er erwartet Eure Ankunft, um die Lektion zu beginnen.", progress = nil, completion = "Seid gegrüßt, junger &lt;Klasse&gt;, ich sehe mit Freuden, dass Ihr begierig seid, etwas über die Heilung von Vergiftungen zu lernen.\n\nFrüher wurden die meisten Druiden vorab geplanten Prüfungen unterzogen, doch das trifft auf Euch nicht zu. Bei Crossroads im Brachland traten vermehrt Fälle von Tiervergiftungen auf, die nicht unter Kontrolle zu bringen sind. Jemand dort bat Moonglade um Hilfe. Wir schicken Euch zu ihrer Unterstützung dorthin. Dies ist keine Übung - es handelt sich um eine echte Aufgabe. Vergesst das nicht.", rewards = "Ihr bekommt:\n\n"},
[6127] = {title = "Die eigentliche Ursache", objective = "Benutzt die leere Glutnebelgipfelprobe beim Glutnebelgipfel und nehmt eine Wasserprobe vom Teich auf der Spitze des Gipfels.\n\nBringt das gefüllte Behältnis vom Glutnebelgipfel zu Tonga Runetotem in Crossroads im Brachland.", description = "Der Glutnebelgipfel nordwestlich von Crossroads ist höchstwahrscheinlich die Quelle, von wo aus sich das Gift verbreitet. Auf seinen luftigen Höhen gibt es Teiche, die das Wetter beeinflussen. Dieses Wasser wurde vermutlich durch Dämonen anbetende Burning Blade verunreinigt.\n\nEntnehmt dem Teich auf der Spitze des Gipfels mit diesem Behältnis eine Probe. Wenn es gefüllt ist, bringt es zu Tonga Runetotem in Crossroads. Er bat um unsere Hilfe und Ihr werdet Euch gemeinsam mit ihm dieses Übels annehmen.", progress = "Seid Ihr vom Zirkel des Cenarius in Moonglade geschickt worden, ja? Das ist ein Glück für uns! Unsere Bemühungen, den kranken Gazellen im nördlichen Brachland Gleichgewicht zu bringen, haben nichts genutzt. Wir sind für jede Hilfe dankbar.\n\nHabt Ihr die Probe des Wassers, wie Dendrite Starblaze sagte? Er informierte mich, dass Ihr eine besorgen würdet, damit wir gemeinsam ein Heilmittel finden...", completion = "Bei meinen Vorfahren, dieses Wasser ist widerwärtig! Kein Wunder, dass die Gazellen krank sind.\n\nEtwas verunreinigt das Wasser und zerstört damit langsam das Ökosystem im nördlichen Brachland. Überall nördlich der Ost-West-Straße wurden kranke Gazellen gesehen. Das Wasser ist wahrscheinlich der Hauptgrund für die Ausbreitung der Krankheit, aber hier wirkt noch etwas anderes.\n\nDieses Wasser wird uns, ob Ihr es glaubt oder nicht, ein Heilmittel finden helfen. Während ich dieses Wasser untersuche benötige ich einige Zutaten für ein Heilmittel...", rewards = "Ihr bekommt:\n\n"},
[6128] = {title = "Das Heilmittel sammeln", objective = "Bringt 5 Erdwurzeln und 5 Kodohörner zu Tonga Runetotem in Crossroads, damit er eine Heilsalbe machen kann.", description = "Das Wasser wird Grundlage einer Heilsalbe sein, die ich für die Gazellen herstelle. Für die Heilwirkung benötige ich etwas Erdwurzel. Kräuterkundige wissen, wo man sie finden kann. Wenn Ihr nicht mit dieser Kunst vertraut seid, müsst Ihr einen suchen, der uns weiterhilft.\n\nDer Wirksamkeit wegen brauche ich zuletzt Kodohörner - Splitter und Bruchstücke reichen aber nicht aus. Kodos, mit denen Ihr fertig werdet, streifen durch den nördlichen Teil des Brachlands. Erlegt welche zum Wohle des Gleichgewichts, <Name>, und bringt mir die Hörner.", progress = "Habt Ihr die Reagenzien bekommen, die ich für meine Salbe brauche? Die Gazellen werden von allein ganz bestimmt nicht wieder gesund, daher sollten wir nicht zaudern im Bemühen, sie zu retten!", completion = "Das ist gut, &lt;Name&gt;, so sehr, dass es für eine gehörige Portion Salbe reichen müsste - wenigstens so viel, dass eine Wirkung zu spüren ist.\n\nManchmal kann es recht schwer sein, ein Heilmittel für Gifte herzustellen, da nicht selten jedes einzelne ein ganz bestimmtes Gegenmittel erfordert. Stellt Euch vor, man könnte ein Gift durch Willenskraft heilen, ohne dass man sich Gedanken über die exakte Zusammensetzung des Gegenmittels machen müsste!\n\nUnd jetzt lasst mich daran arbeiten!", rewards = "Ihr bekommt:\n\n"},
[6129] = {title = "Heilung der Kranken", objective = "Benutzt die heilende Tiersalbe bei 10 kränklichen Gazellen im nördlichen Teil des Brachlandes. Das müsste sie heilen. Kränkliche Gazellen wurden überall nördlich der Ost-West-Straße durch Crossroads gesehen.", description = "Ich konnte genügend Salbe für zehn heilende Dosen machen, <Name>. Ich arbeite weiter mit den hiesigen Behörden zusammen und versuche, mehr Salbe herzustellen. Derweil möchte ich, dass Ihr uns einen Vorsprung verschafft. Rund um das nördliche Brachland wimmelt es von kranken Gazellen. Heilt sie mit der Salbe von ihrem Übel.\n\nDendrite Starblaze in Moonglade wird ganz sicher mit Euch reden wollen, wenn Ihr fertig seid. Bitte übermittelt dem Zirkel des Cenarius unseren Dank... und lasst mich Euch persönlich für Eure Hilfe danken!", progress = nil, completion = "Ihr habt bei der Heilung der kranken Gazellen des Brachlands wahre Wunder gewirkt. Sie waren das arglose Opfer einer größeren Besudelung und Verderbnis geworden, die sich über das Land ausbreitete. Ihr &lt;Volk&gt; brennt darauf, die Wege des Cenarius zu verstehen. Ihr habt, wie Eure Ältesten in Thunder Bluff, den Beweis angetreten, dass die Notwendigkeit des Gleichgewichts künstliche Barrieren zwischen den Völkern überwindet.\n\n&lt;Name&gt;, Ihr habt Euren Wert als Freund der Natur und des Zirkels unter Beweis gestellt - nehmt dies als Symbol dafür.", rewards = "Ihr bekommt:\n\nSchleierstaub-Medizinbeutel"},
[6130] = {title = "Macht über Gift", objective = "Kehrt zu Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff zurück.", description = "Ihr habt gelernt, was es heißt, Vergiftungen ohne spirituelle Unterstützung zu heilen. Vergesst nicht, was andere auf sich nehmen müssen, wenn sie gegen Vergiftungen ankämpfen, wenn Ihr Eure neu erlangte Macht über Gift erhaltet.\n\nIhr solltet jetzt zu Turak Runetotem in Thunder Bluff zurückkehren, <Name>. Zweifellos hat er Euch wichtige Zauber beizubringen, da Ihr nun die Lektionen begriffen habt, die Ihr erhieltet.\n\nLebt wohl, junger Druide. Wir sprechen uns wieder.", progress = nil, completion = "Willkommen - ich verfolge Eure Fortschritte in dieser Lektion seit Eurem Aufbruch und muss gestehen, ich war überrascht, als ich von der Situation in Crossroads erfuhr. Dies erfordert weitere Untersuchungen, da die Freisetzung solcher Gifte in die Umwelt das Gleichgewicht empfindlich stört.\n\nIhr habt Euch unter großem Druck wacker gehalten. Dafür finde ich keine bessere Möglichkeit, als Euch mit permanenter Macht über Gift zu belohnen. Verwendet sie weise, &lt;Name&gt;... verwendet sie weise.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVergiftung heilen\n\nIhr bekommt:\n\n"},
[6131] = {title = "Verbündeter der Holzschlundfeste", objective = "Grazle möchte, dass Ihr Euch beweist, indem Ihr 5 Krieger der Totenwaldfelle, 5 Pfadfinder der Totenwaldfelle und 5 Gärtner der Totenwaldfelle besiegt.", description = "Die Einwohner der Holzschlundfeste sind die einzigen Furbolgs, die von der Verderbnis verschont blieben. Aber viele andere Völker töten die Furbolgs jetzt blindwütig und scheren sich nicht darum, ob sie Freund oder Feind sind. Deswegen trauen die Furbolgs der Holzschlundfeste auch kaum jemandem.\n\nSeid Ihr daran interessiert, Euch zu beweisen? Treibt den verderbten Stamm der Totenwaldfelle vom Teufelswald zurück, dann betrachten wir Euch eines Tages vielleicht als Verbündeten. Ihr findet den ersten Stamm der Totenwaldfelle - Krieger, Pfadfinder und Gärtner - westlich von hier.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil},
[6132] = {title = "Holt mich hier raus!", objective = "Eskortiert Melizza Brimbuzzle und sprecht anschließend mit Hornizz Brimbuzzle beim Kodofriedhdof Desolace.", description = "Holt mich hier raus!\n\nIch kam ins Tal der Speere, um mit den Maraudines zu sprechen. Ich dachte, ich könnte Geschäfte mit ihnen machen... aber sie reden einfach nicht mit mir! Ich glaube, sie möchten mich eher verspeisen!\n\nHolt mich hier raus, mein Bruder Hornizz wird es Euch reich vergelten! Er ist in unserem Lager neben dem Kodofriedhdof im Osten.\n\nBeeilen wir uns, <Name>. Es ist keine zwei Minuten her, da hörte ich einige Zentauren sagen, dass sie Holz für ihren Kochtopf sammeln möchten...", progress = nil, completion = "Meine Schwester Melizza sagte, dass Ihr kommen würdet. Danke, dass Ihr sie aus dieser misslichen Lage befreit habt. Vermutlich steckt sie leider schon wieder in einer neuen.", rewards = "Ihr bekommt:\n\n"},
[6133] = {title = "Das Ersuchen des Waldläuferlords", objective = "Begebt Euch zur nördlichsten Grenze der Östlichen Pestländer und bringt die Quel'Thalas-Registratur zurück. Der Gegenstand befindet sich irgendwo in der Quel'Lithien-Lodge.\n\nAußerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten.", description = "Die Hochelfen der Quel’danil-Lodge haben etwas, das mir gehört, <Klasse>: Ein Dokument, das mein Leben als Sterblicher schildert.\n\nBevor Ihr fragt, Ihr seid wahrscheinlich nicht befugt, derlei Informationen zu bekommen. Macht einfach, was ich Euch sage, Wurm: Holt den Lebenslauf zurück.\n\nUnd, Schwachkopf, richtet so viel Not und Elend an, wie Ihr könnt. Lasst sie leiden ...", progress = "Lasst mich nicht warten, <Klasse>.", completion = "Ich gehe davon aus, dass Ihr den Lebenslauf nicht gelesen habt. Nicht einmal Ihr würdet etwas so Idiotisches machen...", rewards = "Ihr bekommt:\n\n"},
[6134] = {title = "Geisterplasmasuche", objective = "Bringt 8 Einheiten Geisterplasma und die Kiste mit den Geistermagneten zu Hornizz Brimbuzzle in Desolace.", description = "Im Südosten liegt ein Tal, das Tal der Knochen, das von den Geistern der Magram heimgesucht wird. Klingt gruselig, nicht wahr? Stellt Euch mal vor, wie sich die Magram erst gruseln müssen! Wenn wir Geisterenergie an jenem Ort einfangen könnten, wäre das den Zentauren sicher einiges wert.\n\nHier, nehmt diese Kiste mit Geistermagneten. Wenn Ihr einen zwischen den beiden großen Skeletten im Tal aufstellt, den toten Goliaths, dann werden sich Geister materialisieren und dorthin gehen. Nehmt Abstand, schaltet die Geister aus und holt Euch ihr Geisterplasma - das verkaufen wir den Magram.", progress = "Wo ist mein Geisterplasma, <Name>?", completion = "Da ist es! Sieht aus, als hättet Ihr auch etwas davon abbekommen. Irgendwie schleimig, hm?\n\nJedenfalls vielen Dank für Eure Mühe, &lt;Name&gt;. Dieses Zeug ist ein Vermögen wert... wenn ich die Zentauren überzeugen kann, dass es echt ist!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKondor-ArmschienenAnkerpfahl-Rundschild\n\nIhr bekommt außerdem:\n\n"},
[6135] = {title = "Dämmerschwinge, oh, wie ich Euch hasse...", objective = "Sucht Dämmerschwinge und tötet ihn. Nehmt ein Büschel vom Fell Dämmerschwinges und bringt es zu Nathanos Blightcaller.\n\nMan sagt, dass Dämmerschwinge nördlich von hier durch das Land streift.", description = "Bisher habt Ihr die Missionen abgeschlossen, die ich Euch aufgab, wenn Ihr auch nicht unbedingt ein Ausbund an Pünktlichkeit seid.\n\nIhr denkt wahrscheinlich, dass Ihr bereit für eine Herausforderung seid. Ja... ja, Schwachkopf, vielleicht seid Ihr wirklich für anspruchsvollere Missionen bereit.\n\nDämmerschwinge, der Albinofledermausdämon, streift nördlich von hier durch das Land. Spürt ihn auf und besiegt ihn. Kehrt mit einem Büschel seines weißen Fells zu mir zurück und Ihr sollt eine Belohnung erhalten.", progress = "Ich würde Euch nicht raten, dass Ihr Euch dieser Herausforderung allein stellt, <Klasse>.", completion = "Gut gemacht, Schwachkopf. Ich fertige aus diesem Fell etwas an, das Ihr brauchen könnt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDämmerschwingenhandschuheDämmerschwingenmantel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[6136] = {title = "Der Korpulente", objective = "Sucht in den nördlichen Wüsten der Östlichen Pestländer nach Blutschlinger und vernichtet ihn. Kehrt zu Nathanos Blightcaller zurück, sobald Ihr diese Mission erledigt habt.", description = "Hinter der Hoffnung des Lichts, dem Lager der Argentumdämmerung, und westlich von Northdale, findet Ihr die wohlbeleibte Madenbestie Blutschlinger.\n\nIch habe ganze Regimenter an dieses Monster verloren. Sein Leibesumfang ist gewaltig! Je mehr er frisst, desto größer wird sein Appetit ...\n\nEs würde mir keine schlaflosen Nächte bereiten, sollte die Bestie Euch verschlingen, dennoch sähe ich es lieber, wenn Ihr der Sieger sein würdet. Ich empfehle, dass Ihr Euch in dieser Angelegenheit der Hilfe anderer versichert. Man weiß, dass Blutschlinger kleine Bataillone verschlungen hat, die töricht genug waren, ihn anzugreifen.", progress = nil, completion = "Macht weiter so und ich muss Euch vom Schwachkopf zum Hirnamputierten erster Klasse befördern.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGiftspeierSchädelsteinhammerSarahs Wegweiser\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[6141] = {title = "Bruder Anton", objective = "Sprecht mit Bruder Anton in Desolace.", description = "Bruder Anton, mein Waffenbruder, hörte Gerüchte über einen Angriff der Untoten im fernen Kalimdor, in einem Land, das Desolace genannt wird. Anton buchte sofort eine Überfahrt dorthin, um die Bedrohung durch die Untoten zu lokalisieren und zu beseitigen!\n\nEr sucht Leute mit viel Tapferkeit und Entschlossenheit, die ihm dabei helfen. Wenn Ihr aufrichtigen Herzens seid, dann sprecht mit Anton. Er befindet sich in Desolace in einer Stadt der Allianz namens Nijelspitze.", progress = nil, completion = "Ich habe Kunde erhalten, dass Unterstützung von Osten kommt. Stammen diese Gerüchte vielleicht von Euch? Seid Ihr hierher gekommen, um dem Scharlachroten Bruder bei seinem Kreuzzug zu helfen?\n\nWenn ja, dann hört gut zu...", rewards = "Ihr bekommt:\n\n"},
[6142] = {title = "Muschelköder", objective = "Sucht 10 Teile Fleisch der weichschaligen Muschel und bringt sie zu Mai'Lahii im Dorf Shadowprey.", description = "Ihr seht wahrlich aus wie ein Angler, <Klasse>! Ich angle zu gern - schon mein Leben lang. Als Köder eignet sich das Fleisch der weichschaligen Muschel am besten. Die Fische können ihm einfach nicht widerstehen. Wisst Ihr, was ich meine?\n\nOben im Norden findet Ihr ein Schiffswrack vor der Küste. In der Gegend wimmelt es von weichschaligen Muscheln. Wenn Ihr mir 10 Teile Fleisch der weichschaligen Muschel bringt, werde ich Euch etwas dafür geben.", progress = "Ich kann es kaum erwarten, mit etwas frischem Fleisch der weichschaligen Muschel angeln zu gehen. Habt Ihr mir die 10 Teile gebracht, die ich brauche?", completion = "Perfekt, Mann, genau das hat mir der Hexendoktor gegen meine Kopfschmerzen verschrieben. Er sagt: 'Mai'Lahii - geh angeln. Dann geht es dir besser.'\n\nAlso, mir geht es jetzt schon besser, danke, Mann!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPardochandschutzRingtail-GurtBracesteel-Gürtel\n\nIhr bekommt außerdem:\n\n"},
[6143] = {title = "Andere Fische zu grillen", objective = "Tötet 7 Myrmidonen der Zackenkämme, 7 Naga der Zackenkämme und 5 Zauberhexerinnen der Zackenkämme, dann sprecht in Desolace mit Drulzegar in Shadowprey.", description = "Vielleicht habt Ihr es ja gehört, vielleicht auch nicht... meine Besatzung und ich waren vor der Insel Ranazjar fischen, nördlich des Schiffswracks vor der Küste im Norden. Wir haben immer dort gefischt, jetzt suche ich nur eine Möglichkeit, wie ich meine gefallenen Kameraden rächen kann.\n\nDie Naga haben uns eines Morgens angegriffen und alle außer mir getötet.\n\nDie Schuld lastet mir schwer auf der Seele, <Klasse>; ihr müsst losziehen und diese Naga für mich grillen. Ich werde Euch für die Mühe belohnen. Meint Ihr, Ihr könnt mir behilflich sein?", progress = nil, completion = "So süß die Neuigkeit ist, dass die Naga ausgelöscht wurden, mein Herz ist immer noch schwer. Ich werde den Rest meines Lebens danach trachten, sie alle auszurotten.\n\nHier, wie versprochen Eure Belohnung. Eine Kleinigkeit im Vergleich zu der Genugtuung, dass die Naga für ihre abscheuliche Untat an meiner Mannschaft büßen mussten.", rewards = "Ihr bekommt:\n\n"},
[6144] = {title = "Der Befehl", objective = "Reist in die Undercity und sprecht mit Varimathras.", description = "Der Befehl ist gekommen, <Klasse>. Varimathras selbst hat verlangt, dass ich meine 'tüchtigsten' Agenten auf eine höchst diffizile taktische Mission in die Undercity schicke.\n\nLeider wurden meine tüchtigsten Agenten alle vor drei Jahren getötet. An ihrer Stelle habe ich eine Bande hirntoter Trottel.\n\n<Nathanos schaut Euch kalt an.>\n\nReist sofort zur Undercity und erstattet Varimathras Bericht. Macht mir keine Schande, <Klasse>!", progress = nil, completion = "Der oberste Kreuzzügler sitzt wohlbehalten in der Scharlachroten Bastion, während seine Streitkräfte in unser Land einfallen, unsere Gebäude und Denkmäler entweihen und unser Volk ermorden.\n\nDie Dunkle Fürstin hat befohlen, dass ich mich ein für alle Mal um dieses Insekt kümmere. Ihr sollt zum Instrument der Abrechnung mit den Verlassenen werden.", rewards = "Ihr bekommt:\n\n"},
[6145] = {title = "Der Purpurrote Kurier", objective = "Kehrt in die östlichen Pestländer zurück und spürt den Purpurroten Kurier auf. Tötet den Kurier und schnappt Euch den Befehl des obersten Kreuzzüglers.\n\nBringt den Befehl zu Nathanos Blightcaller und wartet auf weitere Anweisungen.", description = "So wie niemand ohne den Kopf überleben kann, kann der Kopf nicht ohne den Körper überleben. Die Verteidigungsanlagen des Scharlachroten Kreuzzugs in Stratholme sind fast unüberwindbar. Stattdessen müssen wir den Körper unter dem Kopf abschneiden.\n\nMeine Todespirscher haben Daten über die Aktivitäten des Kreuzzugs außerhalb von Stratholme gesammelt. Jeden Tag wird ein Bericht aus ihrer Befehlszentrale in Tyrs Hand geschickt. Dieser Bericht ist der Schlüssel, <Volk>! Sucht den Purpurroten Kurier und beschafft diesen Bericht. Bringt ihn zu Nathanos.", progress = "Wenn Euch das gelingt, habt Ihr Euch fast meinen Respekt verdient, <Klasse>.", completion = "&lt;Nathanos lacht.&gt;\n\nExzellent! Endlich! Eine Gelegenheit, das Scharlachrote Orakel zu vernichten!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6146] = {title = "Nathanos' List", objective = "Reist nach Tyrs Hand, südöstlich der Siedlung Marris. Dort angekommen beißt in den faulen Apfel. In der Verkleidung des Scharlachroten Kreuzzugs überbringt Ihr Lord Valdelmar den Befehl des obersten Kreuzzüglers.", description = "Ich habe diesen Befehl etwas modifiziert. Sollte unsere kleine List wirken, wird das Scharlachrote Orakel schutzlos sein und wir schlagen zu!\n\nPasst jetzt genau auf, <Klasse>. Ihr werdet diesen Befehl dem Kreuzzüglerlord Valdelmar überbringen.\n\nWie? Ihr drückt ihm das Ding in die Hand, Schwachkopf.\n\nBringt den Befehl und diesen faulen Apfel nach Tyrs Hand. Wenn Ihr in der Stadt seid, dann esst den Apfel. Ihr werdet Euch in etwas verwandeln, das für Menschen ... verträglicher ist. Nehmt den Befehl und übergebt ihn dem Kreuzzüglerlord Valdelmar.", progress = "Das ist nicht akzeptabel, Soldat!", completion = "Wo seid Ihr gewesen? Wir dachten schon, die Geißel hätte Euch erwischt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6147] = {title = "Kehrt zu Nathanos zurück.", objective = "Kehrt mit der neuen Information zu Nathanos Blightcaller zurück.", description = "Der oberste Kreuzzügler bringt eine ungewöhnliche Bitte vor. Hrm, wie dem auch sei... was er verlangt, soll geschehen. Kehrt zur Scharlachroten Bastion zurück und lasst ihn wissen, dass das Orakel sich bald auf den Weg machen wird.\n\nWir werden alle Vorsichtsmaßnahmen treffen, damit sie es unbeschadet nach Stratholme schafft.", progress = nil, completion = "Diese Narren! Meine Täuschung ist nicht aufgefallen! Macht Euch bereit, &lt;Klasse&gt;. Wir müssen mit kalter List zuschlagen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6148] = {title = "Das Scharlachrote Orakel Demetria", objective = "Der Scharlachrote Kreuzzug ist unterwegs. Irgendwo auf der Straße von Tyrs Hand nach Stratholme findet Ihr das Orakel Demetria und ihr Gefolge. Jagt sie und tötet sie. Kehrt zu Nathanos Blightcaller zurück, wenn Ihr erfolgreich wart.", description = "Demetria ist die oberste Beraterin des obersten Kreuzzüglers. Ihrer 'überirdischen' Sinne wegen nennt man sie das Orakel. Sie hat den Kreuzzug erfolgreich zu mehreren Siegen gegen die Geißel geführt.\n\nWir konnten sie zwar mit dieser List herauslocken, aber wenn sie wirklich eine übersinnliche Begabung besitzt, wird sie zweifellos mit Ärger rechnen. Ihr werdet für diesen 'Ärger' sorgen.\n\nSpürt das Orakel auf und beendet ihre Existenz. Sie müssten in diesem Moment von Tyrs Hand aufbrechen. Macht mich stolz, Wurm.", progress = nil, completion = "Von diesem Schlag werden sie sich jahrelang nicht erholen! Gut gemacht, &lt;Name&gt;! Ihr habt Euch nicht nur meinen Respekt verdient, sondern auch diese Belohnung.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGorewood-BogenSturmwüterHochheiliger Beschützer\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[6161] = {title = "Nehmt Rackmores Schatz!", objective = "Sucht Rackmores Silberschlüssel. Sucht Rackmores Goldschlüssel. Sucht und öffnet Rackmores Truhe.", description = "Aus Rackmores Logbuch geht hervor, dass sein Schiff zur Festung Feathermoon segelte, als es von seefahrenden Kreaturen angegriffen wurde. Er versteckte seine Truhe auf der Insel Ranazjar, damit sein Schatz dem Feind nicht in die Hände fallen sollte.\n\nZwei Schlüssel, ein silberner und ein goldener, sind erforderlich, um die Truhe zu öffnen. Diese Schlüssel gingen verloren, doch wenn Schlüssel und Truhe gefunden werden, winkt ein Schatz!", progress = "Diese Truhe ist sicher verschlossen.", completion = "Die Truhe geht auf und gibt Rackmores Schatz preis!", rewards = "Ihr bekommt:\n\nKäpt'n Rackmores SteuerruderKäpt'n Rackmores Pinne"},
[6162] = {title = "Eines Ehemanns letzter Kampf", objective = "Tötet Oberanführer Ror und bringt seine Klaue zu Dreka'Sur beim Blutgiftposten im Teufelswald.", description = "Mein Gatte reiste unserem Klan zu Ehren durch den Teufelswald und kämpfte gegen den Schattenrat und andere verderbte Monstrositäten!\n\nAls er dem Tod viele Male entronnen war, erhielt ich einen Brief von ihm, in dem stand, dass ein Druide ihn um Beistand gegen einen großen beschmutzten Furbolg namens Oberanführer Ror gebeten hatte - man hörte nie wieder etwas von ihnen.\n\nIch möchte die Klauenhand dieses Ror, <Name>. Er soll dafür büßen, dass er mich zur Witwe gemacht hat! Ich glaube, die Kreatur ist im Süden... nahe der Grenze von Ashenvale.", progress = "Habt Ihr den Kopf der Bestie schon, <Name>? Sie wird für ihre Verbrechen büßen. Mir ist egal, ob sie verderbt oder nur wütend ist, weil sie in diesem garstigen Wald hausen muss. Kein Furbolg, der solche Verbrechen an meiner Familie begeht, darf überleben!", completion = "Ihr macht mir Ehre, indem Ihr zu Eurem Wort steht. Mein Mann fiel im Kampf - er wäre stolz darauf gewesen. Aber ich könnte keine Ruhe finden, wenn ich nicht wüsste, dass die Kreatur, die mich zu meinem Witwendasein verdammte, nicht für ihre Tat bezahlt hätte.\n\nNochmals danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[6163] = {title = "Ramstein", objective = "Reist nach Stratholme und tötet Ramstein den Würger. Bringt seinen Kopf als Souvenir zu Nathanos.", description = "Ich war überwältigt. Ich stand in dieser Siedlung... und blieb standhaft bei der Verteidigung von Lordaeron. Der Hof und alles darauf wurde von einer gigantischen Welle der Geißel belagert.\n\nDer Dreck. Der Schmutz. Er stand über mir und die Eingeweide hingen ihm aus einem klaffenden Loch in der Brust.\n\nIch erwachte als Geißel. Lange Zeit war ich hilflos. Meine Gedanken waren mit denen des Lichkönigs verschmolzen.\n\nSie kam zu mir... irgendwo, irgendwie wusste ich es. Frei.\n\nDoch jetzt muss ich meine Rache haben - Rache an dem, der mir das Leben genommen hat. Vernichtet ihn.", progress = "Als Sylvanas mich befreit hatte, jagte ich die Bestie monatelang durch diese Wüste. Er floh ins sichere Stratholme. Der Bastard...", completion = "Ich frage mich... hat es um Gnade gewinselt? Wusste es überhaupt, was Gnade ist?\n\n&lt;Nathanos spuckt aus.&gt;\n\nIch werde den Kopf dieser Bestie an meine Wand hängen.\n\nIhr habt Euch einen Platz unter meinen Helden verdient, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKönigliches Siegel von AlexisElementarkreis\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[6164] = {title = "Augustus' Rezeptbuch", objective = "Bringt Augustus' Quittungsbuch zu Augustus dem Meschuggenen im Schreckenstal.", description = "Ich bin jetzt bereit für's Geschäftliche! Was wollt Ihr?\n\nOh, Moment mal... ohne mein Quittungsbuch kann ich kein Geschäft eröffnen. Wie soll ich ohne mein Quittungsbuch den Überblick behalten?\n\nIch muss es in der Stadt gelassen haben. Ich hatte ein Zimmer im Gasthaus... dort muss das Buch sein.\n\nBringt mir mein Buch. Bitte, bringt es mir! Bringt mir mein Buch und Ihr werdet sehen! Ich eröffne mein Geschäft und Ihr werdet sehen, dass meine Preise der WAHNSINN sind!", progress = "Habt Ihr mein Quittungsbuch? Ich will endlich wieder an die Arbeit gehen!", completion = "Da ist es! Oh meine Güte! Ich hatte vergessen, wie voll es war!\n\nDies ist ein glorreicher Tag, &lt;Name&gt;! Toll! Wahnsinnig gut, sage ich Euch!", rewards = "Ihr bekommt:\n\n"},
[6181] = {title = "Eine eilige Nachricht", objective = "Bringt Lewis' Notiz zu Thor dem Greifenmeister.", description = "Wir bekommen zwar nicht viel Unterstützung von Stormwind direkt, aber ich habe einen Kontaktmann in der Stadt, der uns mit Rüstungen versorgt. Sein Name ist Osric Strang. Sein Geschäft, Begrenzte Immunität, liegt in der Altstadt von Stormwind.\n\nUnser Vorrat an Rüstung schwindet, ich muss bei Osric mehr bestellen. Könnt Ihr ihm diese Notiz bringen?\n\nDer schnellste Weg nach Stormwind führt über Thor, unseren Greifenmeister. Er ist unten am Hügel; bringt ihm meine Notiz und nehmt dann einen Greifen nach Stormwind.", progress = "Ihr seht aus, als hättet Ihr es eilig. Tja, dann seid Ihr hier genau richtig!", completion = "Ihr müsst diese Notiz nach Stormwind bringen? Das ist kein Problem, Ihr könnt einen meiner Greifen nehmen!", rewards = "Ihr bekommt:\n\n"},
[6182] = {title = "Der Erste und Letzte", objective = "Sprecht mit Meister Mathias Shaw in der Altstadt von Stormwind. Er wohnt in der Kaserne.", description = "Nathanos Marris war der erste und letzte Waldläuferlord der Menschen. Ein Schüler von Sylvanas Windrunner, die heute Bansheekönigin der Verlassenen ist.\n\nWir dachten, Nathanos sei fünf Jahre zuvor bei der Verteidigung von Lordaeron in der Schlacht gefallen. Sein Leichnam wurde zwar nie gefunden, aber man ging davon aus, dass er es nicht aus den östlichen Pestländern hinaus geschafft hatte.\n\nMathias Shaw hat sein Verschwinden untersucht und könnte neue Informationen haben. Meldet Euch sofort bei ihm. Er lebt in der Altstadt, in der Kaserne.", progress = nil, completion = "Nach einigen Berichten über ungewöhnliche Aktivität der Verlassenen in den östlichen Pestländern wurden Agenten von SI:7 zu Ermittlungen hingeschickt. Die Resultate dieser Ermittlungen sind beunruhigend.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6183] = {title = "Ehret die Toten", objective = "Sprecht wieder mit Mathias Shaw, wenn Ihr seine Aufgabe annehmen wollt.", description = "Fünf meiner besten Agenten wurden dem Fall Marris zugeteilt. Einer kam zurück und starb drei Tage später im Schlaf.\n\nDie wenigen Informationen, die wir aus ihm herausbekamen, waren unverständliches Gestammel. Wir haben zwei Worte verstanden: 'Nathanos' und 'Blightcaller'.\n\nIch habe nicht genügend Leute, um die Ermittlungen fortzusetzen, und Ravenholdt ist uns nicht behilflich. Wir müssen der Sache auf den Grund gehen, und wenn es nur ist, damit wir den Familien der Verstorbenen Trost spenden können. Werdet Ihr helfen?", progress = nil, completion = "&lt;Mathias nickt.&gt;\n\nIch war gewiss, dass Bolvar mir ehrenhafte Männer und Frauen schicken würde - die treuesten Soldaten der Allianz.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6184] = {title = "Flint Shadowmore", objective = "Reist zur Chillwindspitze in den Westlichen Pestländern und trefft Euren Kontaktmann Flint Shadowmore.", description = "Die einzige Information, die wir bislang haben, ist die, dass Nathanos Marris von diesem Blightcaller ermordet worden sein könnte. Wir gehen davon aus, dass Blightcaller derselbe Teufel ist, der meine Agenten beseitigt hat.\n\nFlint Shadowmore, ein weiterer Agent des SI:7, ist im Lager der Allianz an der Chillwindspitze, westliche Pestländer, stationiert. Sucht ihn auf. Er wird Euch in die aktuelle Situation in den Pestländern einweihen und Euch einen Auftrag erteilen.\n\nViel Glück, <Name>.", progress = nil, completion = "Eure erste Mission ist kurz und knapp, &lt;Name&gt;. Ihr geht rein, ihr geht raus. Aufklären...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6185] = {title = "Die östlichen Pestländer", objective = "Sucht in den östlichen Pestländern nach Hinweisen auf den 'Blightcaller' und die vermissten SI:7-Agenten. Wenn Ihr SI:7-Insignien findet, bringt sie zu Flint Shadowmore an der Chillwindspitze.", description = "Wie gesagt, Eure erste Mission ist eine Aufklärungsmission. Nichts Kompliziertes, <Name>. Ihr müsst in die östlichen Pestländer reisen und nach Hinweisen auf diesen Blightcaller suchen.\n\nHaltet nach Informationen über unsere vermissten Agenten Ausschau. Wir müssen davon ausgehen, dass sie tot sind, und wenn sie tot sind, muss es Leichen geben ... irgendwo.\n\n<Flint schluckt schwer.>\n\nAlle SI:7-Agenten tragen diese Insignien.\n\n<Flint zeigt Euch seine SI:7-Insignien.>\n\nBringt alle zu mir zurück, die Ihr finden könnt.", progress = "G... Glück gehabt???", completion = "Rutger. Fredo. Turyen. Alle... tot...\n\n&lt;Flint umklammert die Insignien.&gt;\n\nWo waren sie? Habt Ihr weitere Informationen über diesen Dreckskerl, diesen Blightcaller, gefunden?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6186] = {title = "Der Blightcaller kommt", objective = "Kehrt nach Stormwind zurück und informiert Hochlord Bolvar Fordragon über das Schicksal von Nathanos Marris.", description = "<Flints Gesicht wird schlagartig leichenblass.>\n\nNa... Nathanos ist das gewesen? Nathanos ist der Blightcaller?\n\nWarum? Er war... war so edel – ein Waldläuferlord, den alle geachtet haben. Der einzige Mensch, der je bei den Hochelfen ausgebildet wurde. Der soll jetzt ein ruchloser Agent der Verlassenen sein?\n\nIch... Ich bin untröstlich, dass ich das von Euch verlangen muss, <Name>, aber Hochlord Fordragon muss unverzüglich über diese Wendung der Ereignisse informiert werden. Bitte kehrt nach Stormwind zurück und überbringt diese Nachricht.", progress = nil, completion = "Nein. Es... NEIN! Wie? Ein Agent der Verlassenen? Der HELD der Bansheekönigin???\n\n&lt;Hochlord Bolvar Fordragon sackt geknickt in sich zusammen.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6187] = {title = "Ordnung muss wieder hergestellt werden", objective = "Stellt eine Armee auf und reist zu den östlichen Pestländern. Beginnt einen gnadenlosen Angriff auf Nathanos Blightcaller und jeden Abschaum der Horde, der ihn beschützen mag.\n\nBewahrt einen klaren Kopf, <Name>. Die Horde wird den Waldläuferlord mit dem Leben verteidigen.", description = "Wisst Ihr, wie viele Waldläuferlords es auf dieser Welt gibt? Wie viele menschliche Waldläuferlords jemals existiert haben?\n\nNathanos' Errungenschaften waren beispiellos. Er war ein taktisches Genie und führte die Allianz in einem Jahrzehnt der Konflikte zu vielen Siegen.\n\nUnd jetzt... der Held der Verlassenen.\n\nNein. Das darf nicht sein. Die Ordnung muss wieder hergestellt werden.\n\nVersammelt eine Armee, <Name>. Kehrt mit Eurer Armee in die Pestländer zurück und vernichtet Blightcaller.\n\nIch wünsche Euch Glück, <Name>. Das werdet Ihr für diesen Kampf wahrlich brauchen.", progress = nil, completion = "Das ist eine Tragödie. Ich glaube... Ich glaube, unsere Art ist verflucht, &lt;Name&gt;. Wir sind verflucht, unsere größten Krieger zu verlieren, unsere edelsten Helden, unsere begabtesten Gelehrten.\n\nWir stehen in Eurer Schuld und ich versichere Euch, &lt;Name&gt;, dass Nathanos Marris auf Euch herablächeln wird, wo immer er jetzt sein mag.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGorewood-BogenSturmwüterHochheiliger Beschützer\n\nIhr bekommt außerdem:\n\n"},
[6241] = {title = "Aktivität der Winterfelle", objective = "Salfa möchte, dass Ihr 6 Totemiker der Winterfelle, 6 Höhlenbehüter der Winterfelle und 6 Pfadfinder der Winterfelle erledigt.", description = "Die Furbolgs der Holzschlundfeste bleiben meist unter sich, <Name>. Wir gewähren allen, die ihre Vertrauenswürdigkeit unter Beweis gestellt haben, freies Geleit, meiden aber wenn möglich andere Furbolgstämme.\n\nIn letzter Zeit ist mir aufgefallen, dass der Winterfellstamm uns gegenüber immer größere Feindseligkeit zeigt. Sie scheinen in Rage zu sein, und ganz von ihrem Hass auf alles beseelt, das sie nicht verstehen.\n\nWenn Ihr ihre Anzahl reduzieren könntet, würde uns das sehr helfen, <Name>.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil},
[6261] = {title = "Dungar Longdrink", objective = "Bringt Osrics Kiste zu Dungar Longdrink dem Greifenmeister.", description = "<Name>, ich habe alles, worum Lewis gebeten hat, in diese Kiste gepackt. Würdet Ihr sie ihm bringen?\n\nWenn Ihr bereits mit Thor in Westfall gesprochen habt, dann könnt Ihr einen Greif zurück zu ihm nehmen. Dungar Longdrink ist unser Greifenmeister drüben im Handelsdistrikt.\n\nSprecht mit Dungar, dann bringt diese Kiste auf dem schnellsten Weg zu Lewis. Wir möchten nicht, dass unsere kämpfenden Männer und Frauen in Westfall ohne neue Ausrüstung sind!", progress = "Ist das Schweiß auf Eurer Stirn, der Herr? Ihr habt Euch beim Laufen zu sehr verausgabt. Nehmt nächstes Mal einen Greifen!", completion = "Eine Kiste für Westfall, eh? Seid Ihr schon mal in Westfall gewesen? Falls ja, ist das kein Problem. Ich habe viele Greifen ausgebildet, damit sie diese Route fliegen können!", rewards = "Ihr bekommt:\n\n"},
[6281] = {title = "Weiter nach Stormwind", objective = "Bucht einen Greifenritt bei Greifenmeister Thor, dann bringt Lewis' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in Stormwind.", description = "Gegen eine geringe Gebühr könnt Ihr einen Greifen nach Stormwind nehmen und so Lewis' Notiz zu Osric bringen. Einen schnelleren Weg gibt es nicht.\n\nWenn Euch das akzeptabel erscheint, sprecht mich wieder an, sobald Ihr bereit seid für den Flug. Das kostet eine Kleinigkeit, aber glaubt mir, es lohnt sich!", progress = "Ihr seid gereist, ja? Seid Ihr an irgendwelchen interessanten Orten gewesen?", completion = "Ah, eine Notiz von Quartiermeister Lewis? Es überrascht mich gar nicht, dass er mehr Ausrüstung braucht. Die Späherkuppe ist weit entfernt in einem Land, das Stormwind fast vergessen hat.\n\nIch danke Euch, &lt;Name&gt;. Hier habt Ihr etwas Geld für Eure Reisespesen.", rewards = "Ihr bekommt:\n\n"},
[6282] = {title = "Harpyien drohen", objective = "Maggran Earthbinder in Sonnenfels möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt.", description = "Tauren sind die stolzen Beschützer dieser Länder. Zweifellos könnt Ihr erraten, warum mich die Anzahl der Harpyien hier im Steinkrallengebirge so beunruhigt.\n\nDie Blutfurien sind die Ursache für die zunehmende Zahl von Harpyien in Kalimdor. Sie bedrängen jede Lebensform und hindern Unschuldige daran, ihre Grenzen zu verlassen.\n\nIhr müsst die Harpyen für mich dezimieren, <Name>!", progress = nil, completion = "Das sind wirklich ganz ausgezeichnete Nachrichten! Erzählt mir noch einmal, wie Ihr in den kalten Herzen dieser schändlichen Harpyien Furcht gesät habt. Die Blutfurien haben einen schweren Schlag erlitten!", rewards = "Ihr bekommt:\n\n"},
[6283] = {title = "Blutfuriengeschlecht", objective = "Maggran in Sonnenfels möchte, dass Ihr die Zerfetzerin der Blutfurien beseitigt und ihre sterblichen Überreste als Beweis für Eure Tat mitbringt.", description = "Es genügt nicht, die Anzahl der Blutfurienharpyien zu verringern. Die einzig wahre Kur für ihre Krankheit wäre es, ihre Anführerin zu beseitigen, die Zerfetzerin der Blutfurien!\n\nFür diese dreckigen Kreaturen ist sie so etwas wie eine Königin. Tötet sie und ihre Zahl wird ganz gewiss abnehmen.\n\nGeht zurück zum verbrannten Tal, dort findet Ihr sie in den westlichen Hügeln. Sie wird nicht leicht zu bezwingen sein, aber die Belohnung ist groß.", progress = "Die Zerfetzerin der Blutfurien ist ein garstiges Geschöpf! Ihr findet sie bestimmt entlang der westlichen Hügelkette im verbrannten Tal.\n\nDie Blutfurien werden ohne sie hilflos sein... gewiss können wir sie für alle Zeiten loswerden!", completion = "Ich spüre bereits, wie die Wut von mir weicht. Was soll ich mit meiner Zeit anfangen? Das Wissen, dass das Böse um mein Land schleicht, hielt meine Gedanken wach, doch nun sind sie verstummt. Vielleicht ist das ja gut so... vielleicht kann ich mich jetzt auf das Gute konzentrieren, was alle Tauren tun sollten.\n\nBitte nehmt das als Belohnung für Eure Mühe an.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGrimmlingumhangKreischergürtel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[6284] = {title = "Arachnophobie", objective = "Tötet Besseleth und bringt Besseleths Fangzahn zu Maggran in Sonnenfels.", description = "Warnung: Betretet Sishir Canyon westlich von hier auf eigene Gefahr.\n\nBesseleth und ihre achtbeinigen Kinder des Waldes haben diesen Canyon zu ihrem eingesponnen Unterschlupf erkoren.\n\nMaggran Earthbinder in Sonnenfels hat ein Kopfgeld auf Besseleth ausgesetzt. Tötet sie und bringt einen Beweis Eurer Tat zu Maggran. Dort werdet Ihr eine Belohnung erhalten, wenn Ihr der achtbeinigen Gefahr ein Ende gemacht habt.", progress = "Besseleth ist ein ruchloses Raubtier... Ich fürchte um alle, die nachts auf dem Weberpass reisen. Dann nämlich lauern sie und ihre Kinder arglosen Reisenden auf. Ich selbst wurde schon Opfer ihres tödlichen Fangzahns, der eine Elle lang ist, aber zum Glück konnte ich sie abwehren und mich in Sicherheit bringen. Ich würde alles dafür geben, wenn dieses Monster vernichtet würde.", completion = "Gute Jagd, &lt;Name&gt;! Besseleth ist ein altes Raubtier in dieser Gegend... Ich werde sie nicht vermissen. Nehmt diese Belohnung als Zeichen dafür, dass Ihr der Held des Waldes seid.\n\n\n\nVielleicht werden jetzt viele nach Sonnenfels kommen und sich nicht mehr vor dem fürchten müssen, was in der Dunkelheit lauert.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTonsteinkurzschwertKlare Kristallrute\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[6285] = {title = "Zurück zu Lewis", objective = "Bucht einen Greifenritt zur Späherkuppe bei Greifenmeister Dungar Longdrink, dann bringt Osrics Kiste zu Lewis an der Späherkuppe.", description = "Der Greifenmeister in Westfall heißt Thor. Falls Ihr schon mit ihm gesprochen habt, dann könnt Ihr einen meiner Greifen zu ihm bringen.\n\nDas hier sollte man unbedingt wissen: Greifen sind stets so ausgebildet, dass sie in ihre Hauptstadt fliegen, aber sie bringen Euch nur zu einem außerörtlichen Greifenmeister, wenn Ihr schon einmal dort gewesen seid.\n\nIhr seid bereits bei Thor gewesen, sprecht daher einfach wieder mit mir, wenn Ihr bereit seid, einen Greifen nach Westfall zu nehmen. Dort könnt Ihr Osrics Kiste bei Rüstmeister Lewis abliefern.", progress = "Ihr seid aus Stormwind zurück? Hat Osric die Rüstungen geschickt?", completion = "Großartig, Ihr habt die Rüstungen! Wir verteilen sie unverzüglich an alle, die sie brauchen.\n\nDanke, &lt;Name&gt;. Ihr wart uns mit Euren Bemühungen eine große Hilfe. Jetzt, da Euch Greife nicht mehr fremd sind, kommt Ihr hoffentlich öfter und helft den Bewohnern der Späherkuppe!", rewards = "Ihr bekommt:\n\n"},
[6301] = {title = "Zyklus der Wiedergeburt", objective = "Tammra Windfield in Sonnenfels möchte, dass Ihr 10 Gaeasamenkörner sammelt.", description = "Industrielle Gier und ständige Kriege haben die Länder des Steinkrallengebirges verwüstet. Nur der Segen der Erdenmutter kann solch eine Verletzung heilen.\n\n<Name>, Ihr müsst für mich ein spezielles Samenkorn suchen, Gaeasamenkorn. Man findet diese Samenkörner nur hier im Steinkrallengebirge, nördlich von Sonnenfels am Mirkfallonsee, in der Nähe des Ufers.\n\nWenn Ihr mir die Samenkörner bringt, werde ich sie mit schamanistischer Macht magieerfüllen, um ihr Wachstum zu beschleunigen.", progress = "Die ständige Zerstörung durch den Krieg und alle, die mit Holz Profit machen möchten, bekümmert mich zutiefst. Um den Zyklus der Wiedergeburt zu unterstützen und die Länder wieder zu bewalden, benötige ich Gaeasamenkörner. Habt Ihr sie, <Klasse>?", completion = "Ah, &lt;Name&gt;, Ihr habt die Gaeasamenkörner. Schaut zu und seht, wie der Segen der Erdenmutter sogar diese kleinen Samenkörner des Lebens blühen und gedeihen lassen kann.", rewards = "Ihr bekommt:\n\n"},
[6321] = {title = "Nachschub für das Grabmal", objective = "Bringt Podrigs Liste zu Karos Razok.", description = "Exekutor Hadrec bat mich, eine Inventur unserer Ausrüstung beim Grabmal durchzuführen. Da die Geißel und Schlimmeres in den Wäldern lauert, möchte er nicht, dass den Todeswachen Ausrüstung fehlt, die sie brauchen.\n\nIch habe festgestellt, dass wir im Großen und Ganzen gut bestückt sind, aber wir brauchen mehr Waffen als Ersatz für die, die wir auf dem Feld verloren haben.\n\nHier eine Anforderungsliste der benötigten Dinge für den Waffenhändler Gordon Wendham in Undercity. Bringt die Anforderungsliste zum Fledermausmeister Karos Razok und sprecht mit ihm über den Transport zur Undercity.", progress = "Ihr scheint in einer offiziellen Angelegenheit hier zu sein...", completion = "Ah, eine Anforderungsliste für Vorräte. Die solltet Ihr wohl in die Undercity bringen. Und zwar rasch, denn das Grabmal darf nicht unterversorgt sein.", rewards = "Ihr bekommt:\n\n"},
[6322] = {title = "Michael Garrett", objective = "Bringt Gordons Kiste zu Michael Garret.", description = "Ich habe den Nachschub für das Grabmal in diese Kiste getan. Wenn Ihr das Grabmal schon besucht und mit dem Fledermausmeister gesprochen habt, könnt Ihr mit einer Fledermaus zu ihm reiten.\n\nSprecht mit Michael Garret, dem Fledermausmeister von Undercity. Er kann Euch eine Fledermaus zum Grabmal zur Verfügung stellen.", progress = "Wenn Ihr weite Strecken reisen müsst, dann ist eine Fledermaus das ideale Transportmittel.", completion = "Diese Kiste muss zum Grabmal im Silberwald? Nichts leichter als das, unsere Fledermäuse fliegen täglich dorthin.", rewards = "Ihr bekommt:\n\n"},
[6323] = {title = "Flug nach Undercity", objective = "Bucht einen Fledermausritt zur Undercity bei Fledermausmeister Karos Razok und bringt dann Podrigs Anforderungsliste zu Gordon Wendham in Undercity.", description = "Gegen eine geringe Gebühr kann Euch eine meiner Fledermäuse zur Undercity bringen. Sprecht mich wieder an, wenn Ihr bereit seid, damit wir Euren Transport vereinbaren können.\n\nIhr findet Gordon Wendham im Handwerksviertel von Undercity. In diesem Viertel landet auch meine Fledermaus.", progress = "Ich halte meine Waffen in einem Top-Zustand. Sie sind gereinigt und einsatzbereit.", completion = "Eine Anforderungsliste vom Grabmal? Wohlan denn. Es ist eine Ehre, denen zu dienen, die unserer Dunklen Fürstin dienen.", rewards = "Ihr bekommt:\n\n"},
[6324] = {title = "Rückkehr zu Podrig", objective = "Bucht einen Fledermausritt zum Grabmal bei Fledermausmeister Michael Garret und bringt dann Gordons Kiste zu Todeswache Podrig beim Grabmal.", description = "Der Fledermausmeister im Grabmal ist Karos Razok. Wenn Ihr schon bei ihm gewesen seid, dann gebe ich Euch eine Fledermaus, damit Ihr zu ihm fliegen könnt.\n\nUnsere Fledermäuse fliegen stets zur Undercity, aber um zu entlegeneren Orten zu reisen, muss ihr Reiter zuerst die Gegend besuchen und mit dem dortigen Fledermausmeister sprechen.\n\nIhr habt Karos im Grabmal getroffen, daher könnt Ihr jetzt mit Fledermäusen dorthin fliegen. Sprecht wieder mit mir, wenn Ihr bereit seid.", progress = "<Name>, Ihr kehrt zurück. Habt Ihr unseren Nachschub aus Undercity?", completion = "Gute Arbeit, &lt;Name&gt;. Diese Waffen gewährleisten, dass unsere Todeswachen nicht unvorbereitet überrascht werden.\n\nIhr habt der Dunklen Fürstin einen wertvollen Dienst erwiesen.", rewards = "Ihr bekommt:\n\n"},
[6341] = {title = "Die Arten von Teldrassil", objective = "Bringt Nessas Sammlung zu Vesprystus.", description = "Den Anglern des Dorfes Rut'theran geht es sehr gut, denn die Fische dort sind extrem groß und zahlreich. Ich würde die hier vorkommenden Arten gern mit denen des Festlandes vergleichen.\n\nIch habe eine Sammlung von Fischgräten und Schuppen, die ich gern zu einem Kollegen von mir in Dunkelküste bringen würde. Er heißt Laird und ist ein Fischverkäufer im Dorf Auberdine.\n\nBringt meine Sammlung zu unserem Hippogryphenmeister Vesprystus und besprecht mit ihm, wie Ihr am besten nach Auberdine kommt.", progress = "Wie kann ich Euch helfen? Benötigt Ihr ein Transportmittel?", completion = "Ah, Ihr möchtet, dass dies nach Auberdine gebracht wird? Nun gut...", rewards = "Ihr bekommt:\n\n"},
[6342] = {title = "Flug nach Auberdine", objective = "Bucht bei Hippogryphenmeister Vesprystus einen Hippogryphen nach Auberdine und bringt dann Nessas Sammlung zu Laird.", description = "Von Rut'theran gibt es zwei Reisemöglichkeiten nach Auberdine: mit der Fähre und mit einem Hippogryphen. Beide sind schnell und zuverlässig, aber wenn Ihr noch nicht mit dem Hippogryphen nach Auberdine geflogen seid, solltet Ihr das schleunigst nachholen.\n\nEin guter Rat: Sprecht in jeder Stadt, in der es einen gibt, mit dem Hippogryphenmeister. Sobald Ihr mit dem Meister gesprochen habt, könnt Ihr von anderen Städten aus dorthin fliegen.\n\nHier ist Nessas Sammlung. Sprecht wieder mit mir, wenn Ihr bereit seid, nach Auberdine zu fliegen und Nessas Sammlung bei Laird abzuliefern.", progress = "Kommt Ihr aus Teldrassil? Erzählt mir, wie angelt es sich dort?", completion = "Ein Päckchen von Nessa? Danke, &lt;Name&gt;! Sie sagte mir, sie würde mir Exemplare der Fische schicken, die in der Nähe von Rut'theran gefangen werden. Sie glaubt, die könnten sich von den hiesigen Fischen unterscheiden...\n\nHerrje! Der Kieferknochen ist fast doppelt so groß wie beim gleichen Fisch hier. Und diese Schuppen sind so groß wie eine geballte Faust! Erstaunlich!", rewards = "Ihr bekommt:\n\n"},
[6343] = {title = "Rückkehr zu Nessa", objective = "Bringt Lairds Antwort zu Nessa Shadowsong.", description = "Ich muss Nessa eine Antwort schicken. Sie interessiert sich bestimmt dafür, wie sehr sich die Fische hier von denen an der Küste Teldrassils unterscheiden. Wir können nur vermuten, was die Ursache sein mag, ich persönlich hege jedoch die Befürchtung, dass der Weltbaum die Natur um sich herum beeinflusst!\n\nBitte bringt Nessa diese Antwort. Wenn Ihr einen Hippogryphen zurück nach Rut'theran nehmen wollt, dann sprecht mit der Hippogryphenmeisterin Caylais Moonfeather. Wenn Ihr die Fähre nehmen wollt, so ist auch das kein Problem: Es legt regelmäßig eine vom Dock im Nordwesten ab.", progress = "<Name>, Ihr seid aus Auberdine zurück? Habt Ihr mit Laird gesprochen?", completion = "Das ist sehr interessant. Die Fische hier sind riesig, aber ich hätte nicht gedacht, dass der Unterschied der Arten zwischen hier und dem Festland so groß ist. Dafür muss es einen Grund geben...\n\nIch danke Euch, &lt;Name&gt;. Ich werde die Nachrichten, die Ihr gebracht habt, mit den Dorfbewohnern besprechen. Vielleicht finden wir eines Tages die Ursache dieser Kuriosität. Doch bis dahin wollen wir nutzen, was sie uns beschert!", rewards = "Ihr bekommt:\n\n"},
[6344] = {title = "Nessa Shadowsong", objective = "Sprecht mit Nessa Shadowsong.", description = "Eine Freundin von mir, Nessa Shadowsong, ist Anglerbedarfshändlerin in Rut'theran. Sie muss ein Päckchen nach Dunkelküste bringen und sucht jemanden, der ihr hilft.\n\nWenn Ihr zu Nessa wollt, dann müsst Ihr in Darnassus das Portal nach Rut'theran benutzen. Ihr findet das Portal westlich der Tempelgärten.", progress = nil, completion = "Ja, ich brauche einen Kurier, der ein Päckchen nach Dunkelküste bringt. Werdet Ihr mir helfen?", rewards = "Ihr bekommt:\n\n"},
[6361] = {title = "Ein Bündel Bälge", objective = "Bringt das Bündel Bälge zu Windreitermeister Devrak in Crossroads.", description = "Ich habe ein Bündel Bälge von Tieren des Brachlands und muss es nach Thunder Bluff bringen. Dort fertigt Ahanu, ein Kollege, Lederwaren aus diesen Häuten an.\n\nBringt Ihr ihm die Bälge für mich?\n\nDer schnellste Weg nach Thunder Bluff ist auf dem Rücken eines Windreiters. Bringt das Bündel Bälge zu Devrak, unserem Windreitermeister in Crossroads, und sprecht mit ihm über den Transport nach Thunder Bluff.", progress = "Seid Ihr wegen eines Windreiters hier? Habt Ihr etwas zu transportieren?", completion = "Wenn Ihr diese Bälge nach Thunder Bluff bringen müsst, dann sprecht Ihr mit dem richtigen Orc!", rewards = "Ihr bekommt:\n\n"},
[6362] = {title = "Flug nach Thunder Bluff", objective = "Bucht einen Windreiter nach Thunder Bluff bei Windreitermeister Devrak und bringt dann das Bündel Bälge zu Ahanu in Thunder Bluff.", description = "Für ein kleines Entgelt gebe ich Euch einen Windreiter nach Thunder Bluff. Es gibt kein schnelleres Transportmittel in die Stadt!\n\nSollte das akzeptabel sein, sprecht wieder mit mir, wenn Ihr abreisefertig seid.\n\nWenn Ihr diese Bälge zu Ahanu bringen wollt, dann schätze ich, er ist in Hewas Waffenkammer am Fundament des Windreiterturms in Thunder Bluff. Und genau dort werdet Ihr landen!", progress = "Ihr habt Staub auf den Schultern, der aus dem Brachland sein muss. Habt Ihr mit meinem Freund Jahan gesprochen?", completion = "Ah, ein neues Bündel Bälge. Ich werde mich sofort damit an die Arbeit machen!\n\nDanke, Bruder. Ihr habt mir einen großen Dienst erwiesen. Hier habt Ihr ein paar Münzen für eure Zeit und Reisekosten.", rewards = "Ihr bekommt:\n\n"},
[6363] = {title = "Tal der Windreitermeister", objective = "Bringt Ahanus Lederwaren zu Tal in Thunder Bluff.", description = "Ich habe Lederwaren für Jahan zum Verkauf in Crossroads vorbereitet. Würdet Ihr sie ihm bringen?\n\nWenn Ihr schon in Crossroads gewesen seid und mit dem dortigen Windreitermeister gesprochen habt, dann könnt Ihr mit einem unserer Thunder-Bluff-Windreiter zu ihm zurück.\n\nBringt die Lederwaren zu Tal, unserem Windreitermeister in Thunder Bluff, und sprecht mit ihm über den Transport nach Crossroads.", progress = "Seid gegrüßt, <Klasse>. Was kann ich für Euch tun?", completion = "Ihr müsst das nach Crossroads bringen, hm? Das ist kein Problem. Wenn Ihr schon einmal dort gewesen seid und mit Devrak gesprochen habt, dann könnt Ihr einen meiner Windreiter zurück zu ihm nehmen.", rewards = "Ihr bekommt:\n\n"},
[6364] = {title = "Rückkehr zu Jahan", objective = "Bucht einen Windreiter nach Crossroads bei Windreitermeister Tal und bringt dann Ahanus Lederwaren zu Jahan Hawkwing.", description = "Um zu einer Stadt zu fliegen, müsst Ihr schon einmal dort gewesen sein und mit dem Windreitermeister dieser Stadt gesprochen haben. Ihr seid in Crossroads gewesen und habt mit dem Windreitermeister Devrak gesprochen, daher könnt Ihr gegen ein geringes Entgelt von hier mit einem unserer Windreiter zu ihm.\n\nSprecht wieder mit mir, wenn Ihr bereit seid. In Crossroads könnt Ihr die Lederwaren zu Jahan Hawkwing bringen.", progress = "<Name>, Ihr seid aus Thunder Bluff zurück? Habt Ihr die Bälge zu Ahanu gebracht?", completion = "Ahanu schickt mir fertige Produkte? Sehr gut. In Crossroads wimmelt es gerade von Jägern und Abenteurern und die Geschäfte gehen blendend. Ich bin sicher, ich kann diese Waren im Handumdrehen an den Mann bringen.\n\nVielen Dank für all Eure Bemühungen, &lt;Name&gt;. Ich stehe in Eurer Schuld.", rewards = "Ihr bekommt:\n\n"},
[6365] = {title = "Fleisch für Orgrimmar", objective = "Bringt Zarghs Fleisch zu Devrak in Crossroads.", description = "Ich habe hier ausgewählte Fleischstücke, die ich einer Freundin schicken möchte. Ihr Name ist Gryshka, sie ist die Gastwirtin in Orgrimmar. Würdet Ihr das Fleisch für mich abliefern?\n\nDas schnellste Transportmittel nach Orgrimmar ist ein Windreiter. Bringt das Fleisch zu Crossroads Windreitermeister Devrak und sprecht mit ihm über den Transport nach Orgrimmar.", progress = "Ihr wollt schnell irgendwohin? Tja, dann sprecht Ihr mit dem richtigen <Volk>!", completion = "Ihr müsst dieses Fleisch nach Orgrimmar bringen? Das ist kein Problem. Für ein bescheidenes Sümmchen kann mein Windreiter Euch hinbringen.", rewards = "Ihr bekommt:\n\n"},
[6381] = {title = "Neues Leben", objective = "Pflanzt 10 Gaeasamenkörner in Gaeaerdhügel und sprecht dann mit Tammra in Sonnenfels.", description = "Wie Ihr sehen könnt, <Klasse>, ist der Zyklus des Lebens eine mächtige Sache, auch wenn das Land Schmerzen leidet. Jetzt müssen wir unseren Teil leisten, um ihm zu helfen. Ihr müsst diese Samen im Zentrum der Zerstörung pflanzen, im Westen, im verbrannten Tal. Aber seid wachsam, denn Harpyien und Feuerelementare verseuchen das vernarbte Land noch immer.\n\nNehmt diese verzauberten Gaeasamenkörner und pflanzt sie in fruchtbare Erdhügel, <Name>. Der Zyklus des Lebens muss weitergehen!", progress = "Diese Samenkörner, die Ihr pflanzt, sind stark, widersetzen sich der Verderbnis und schaffen neuen Platz für anderes Leben. Sie werden wachsen und wachsen, zuerst die Verderbnis verhindern und das vernarbte Land heilen, und dann werden sie eines Tages das Steinkrallengebirge wieder zu einem üppigen Wald machen.\n\nHabt Ihr alle Gaeasamenkörner gepflanzt?", completion = "Das ist ein großer Sieg für das Land. Mit der Zeit werden auch andere Dinge geschehen: Die Venture Company wird die Kreissägen und Äxte zusammenpacken, die wütenden Feuergeister werden sich beruhigen und die Harpyien werden vom Land vertrieben.\n\nErst dann, &lt;Name&gt;, wird das Steinkrallengebirge wirklich Frieden finden.\n\nIhr habt Eure Sache gut gemacht, &lt;Klasse&gt;. Nehmt einen dieser Gegenstände als Dank für das neue Leben, das Ihr heute hier geschaffen habt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWindsucher-StiefelSandspitzen-Handschuhe\n\nIhr bekommt außerdem:\n\n"},
[6382] = {title = "Die Jagd in Ashenvale", objective = "Sprecht mit Seneni Thunderheart im Splintertreeposten in Ashenvale.", description = "Eure Kraft beeindruckt mich, <Klasse>. Die Entschlossenheit, mit der Ihr Euch der Jagd zuwendet, erfüllt mich mit der Gewissheit, dass Ihr Euch größerem Wild... und größeren Herausforderungen zuwenden könnt.\n\nDer Wald von Ashenvale ist eine große, ungezähmte Wildnis, der die Horde ihren Willen aufzuzwingen trachtet, sowohl politisch wie auch spirituell. Wenn Ihr Euch in einem unerforschten Land beweisen wollt, dann sucht die Führung von Senani Thunderheart im Splintertreeposten. Der Außenposten liegt nördlich des Pfads, der aus dem Brachland führt.", progress = nil, completion = "Willkommen an der neuen Grenze, &lt;Name&gt;. Ashenvale ist ein Land der unbegrenzten Möglichkeiten, eines, in dem jemand Eurer Art, &lt;Klasse&gt;, jede Menge Gelegenheiten finden wird, seinen Mumm unter Beweis zu stellen. Schaut Euch hier im Außenposten um und begebt Euch auf jeden Fall auch einmal hinaus zum Zoramstrand, denn die Horde hat dort noch einen weiteren Außenposten.\n\nEure Anwesenheit hier sagt mir, dass Ihr gekommen seid, um mehr über die Jagd zu lernen. Hört mir genau zu, und ich werde euch gern mitteilen, was Ihr wissen müsst.", rewards = "Ihr bekommt:\n\n"},
[6383] = {title = "Die Jagd in Ashenvale", objective = "Es gibt drei legendäre Kreaturen, die die Jagd in Ashenvale bilden. Ihr könnt sie suchen und Euch mit ihrer List und Kraft messen. Dabei werdet Ihr hoffentlich auch etwas über Euch selbst lernen. Die Kreaturen sind: der Bär Ursangus, die Nachtsäblerkatze Schattumbra und der Hippogryph Scharfkralle.\n\nDie Kreaturen der Jagd in Ashenvale sind mächtig; möglicherweise benötigt Ihr Unterstützung, um sie zu bezwingen. Wenn Ihr sie besiegt habt, dann bringt mir Beweise Eurer Tat.", description = nil, progress = nil, completion = nil, rewards = nil},
[6384] = {title = "Flug nach Orgrimmar", objective = "Bucht einen Windreiter nach Orgrimmar bei Windreitermeister Devrak und bringt dann Zarghs Fleisch zu Gryshka in Orgrimmar.", description = "Für eine Handvoll Münzen lasse ich Euch mit einem Windreiter nach Orgrimmar bringen. Wenn Ihr dort eintrefft, bringt Zarghs Fleisch zu Gryshka. Ihr Gasthaus liegt im Tal der Stärke, nicht weit vom Himmelsturm entfernt, wo mein Windreiter Euch absetzen wird.\n\nSprecht wieder mit mir, wenn Ihr bereit für die Reise seid.", progress = "Irgendwas riecht lecker! Ihr habt nicht zufällig rohes Fleisch bei Euch, oder?", completion = "Wie wundervoll! Das ist bestes Filet! Es ist von Zargh, richtig? Dieser &lt;Volk&gt; versteht es, das Herz einer Dame zu betören...\n\nOh, ich kann es kaum erwarten, das zuzubereiten. Aber nicht zu viel! Fleisch serviert man am besten selten, findet Ihr nicht auch?", rewards = "Ihr bekommt:\n\n"},
[6385] = {title = "Doras der Windreitermeister", objective = "Bringt Gryshkas Brief zu Doras in Orgrimmar.", description = "Ich habe Zargh einen Dankesbrief geschrieben. Könnt Ihr ihn für mich zustellen? Wenn Ihr schon in Crossroads gewesen seid und mit dem dortigen Windreitermeister gesprochen habt, dann könnt Ihr mit einem Windreiter dorthin zurück fliegen.\n\nBringt meinen Brief zu Forak, dem Windreitermeister von Orgrimmar, und sprecht mit ihm über den Transport nach Crossroads.", progress = "Braucht Ihr einen meiner Windreiter?", completion = "Ihr müsst das nach Crossroads im Brachland bringen? Ja, ich kann Euch dorthin bringen...", rewards = "Ihr bekommt:\n\n"},
[6386] = {title = "Kehrt nach Crossroads zurück", objective = "Bucht einen Windreiter nach Crossroads bei Windreitermeister Doras und bringt dann Gryshkas Brief zu Zargh in Crossroads.", description = "Meine Windreiter wurden ausgebildet, an viele verschiedene Orte zu fliegen, wenn Ihr schon an diesem Ort gewesen seid und mit dem Windreitermeister dort gesprochen habt.\n\nIhr seid in Crossroads gewesen und habt mit dem Windreitermeister Devrak gesprochen, daher könnt Ihr jetzt direkt zu ihm fliegen. Wenn Ihr in Crossroads seid, könnt Ihr Gryshkas Brief zu Zargh bringen.\n\nSprecht wieder mit mir, wenn Ihr bereit zum Aufbruch seid.", progress = "Seid Ihr von Orgrimmar zurück? Hat Gryshka das Fleisch geschmeckt, das ich ihr geschickt habe?", completion = "Ha! Natürlich hat es ihr geschmeckt! Nichts macht die Wangen einer Dame so rot wie ein großes, saftiges Steak!\n\nDanke, &lt;Name&gt;. Ihr habt mir einen großen Dienst erwiesen. Hier habt Ihr etwas Geld für Eure Mühe, und seid nicht überrascht, wenn ich Euch zu meiner Hochzeit einlade!", rewards = "Ihr bekommt:\n\n"},
[6387] = {title = "Ehrenstudenten", objective = "Bringt Brocks Liste zu Thorgrum Borrelson in Thelsamar.", description = "Ich sehe viele junge Zwerge vor meiner Tür, die begierig sind, den Bergbau zu erlernen. Und wenn ein Minenarbeiter eines mehr als alles andere braucht, dann ist das eine Hacke!\n\nIch habe eine Liste von Bergbaustudenten mit vorzüglichen Abschlussprüfungen, die sich eine Ehrenhacke verdient haben. Bringt meine Liste zu Golnir Bouldertoe in Ironforge. Er wird die Hacken fertigmachen.\n\nDas schnellste Transportmittel nach Ironforge ist ein Greif, also bringt die Liste Thorgrum Borrelson, unserem Greifenmeister, und sprecht mit ihm über den Transport nach Ironforge.", progress = "Habt Ihr schon so bald die Nase voll von Thelsamar? Seid Ihr bereit, in eine andere Stadt abzureisen?", completion = "Ihr müsst das nach Ironforge bringen, hm? Für ein geringes Entgelt setze ich Euch auf den Rücken eines meiner Greife, der Euch dorthin bringt. Na, was sagt Ihr dazu?", rewards = "Ihr bekommt:\n\n"},
[6388] = {title = "Gryth Thurden", objective = "Bringt die Ehrenhacken zu Gryth Thurden in Ironforge.", description = "Hier sind die Ehrenhacken für Brocks Studenten. Wenn Ihr schon in Thelsamar gewesen seid, dann solltet Ihr mit einem Greifen dorthin zurückfliegen!\n\nBringt die Hacken zu unserem Greifenmeister Gryth Thurden und sprecht mit ihm über die Rückreise nach Thelsamar.", progress = "Ihr seht aus, als müsstet Ihr irgendwohin. Braucht Ihr einen meiner Greifen?", completion = "Ihr müsst das nach Thelsamar bringen, hm? Das wird gar kein Problem sein. Wenn Ihr schon in Thelsamar gewesen seid und mit Thorgrum Borrelson gesprochen habt, dann könnt Ihr einen meiner Greifen zurück zu ihm nehmen.", rewards = "Ihr bekommt:\n\n"},
[6389] = {title = "Eine Plage komme über Euch", objective = "Befreit die Pestländer-Termiten im Sägewerk von Northridge, dann kehrt mit dem Fass Pestländer-Termiten zu Nathaniel Dumah im Chillwind-Posten in den westlichen Pestländern zurück.", description = "Ihr seht Euch in dem Sägewerk nach etwas um, mit dem Ihr das Fass öffnen könnt. Ihr findet ein Stemmeisen, das aussieht, als würde es damit gehen.\n\nIhr nehmt die Beine in die Hand und betet, dass Ihr aus dem Sägewerk entwischen könnt, bevor die Termiten Euch erwischen.", progress = "Habt Ihr es geschafft, <Name>? Habt Ihr die Termiten freigelassen? Das Licht stehe uns bei, wenn der Scharlachrote Kreuzzug sowohl das Werk wie auch Hearthglen halten könnte. Beides hätte nicht gelingen sollen. Sie beuten lediglich die Opfer des letzten Kriegs aus und sollten erlegt werden wie tollwütige Tiere!", completion = "Haha! Danke, &lt;Name&gt;! Ihr habt es geschafft! Meines Vaters Geist findet jetzt Ruhe und ich kann in Frieden leben.\n\nNochmals danke. Wenn ich etwas für Euch tun kann, so sagt es bitte.", rewards = "Ihr bekommt:\n\n"},
[6390] = {title = "Eine Plage komme über Euch", objective = "Befreit die Pestländer-Termiten im Sägewerk von Northridge, dann kehrt mit dem Fass Pestländer-Termiten zu Mickey Levine im Bollwerk in Tirisfal zurück.", description = "Ihr seht Euch in dem Sägewerk nach etwas um, mit dem Ihr das Fass öffnen könnt. Ihr findet ein Stemmeisen, das aussieht, als würde es damit gehen.\n\nIhr nehmt die Beine in die Hand und betet, dass Ihr aus dem Sägewerk entwischen könnt, bevor die Termiten Euch erwischen.", progress = "Habt Ihr es geschafft, <Name>? Habt Ihr die Termiten im Sägewerk freigelassen?\n\nEs war schlimm genug, dass meine Familie Arbeit und Leben verlor, aber dann mit anzusehen, wie der Ort, wo ich meine Kindheit verbrachte, von diesen widerwärtigen sogenannten heiligen Männern übernommen wurde ... bäh!!!", completion = "Danke, &lt;Name&gt;. Hier, nehmt diese Münze. Leider habe ich nicht mehr, aber freut Euch wenigstens darüber, dass Ihr die Bemühungen des Scharlachroten Kreuzzugs durchkreuzt habt!", rewards = "Ihr bekommt:\n\n"},
[6391] = {title = "Flug nach Ironforge", objective = "Bucht einen Greifen nach Ironforge von Greifenmeister Thorgrum Borrelson, dann bringt Brocks Liste zu Golnir Bouldertoe in Ironforge.", description = "Für nur ein paar Münzen bringt Euch einer meiner Greifen nach Ironforge. Bringt dann Brocks Liste zu Golnir Bouldertoe. Ihr findet ihn in der Deepmountain-Bergbaugilde. Sie liegt im Distrikt der Großen Schmiede von Ironforge, und genau dort setzt Euch mein Greif ab!\n\nSprecht wieder mit mir, wenn Ihr bereit für die Reise seid.", progress = "Womit kann ich Euch dienen, werter Herr?", completion = "Ah, die neueste Liste von Brocks Meisterschülern. Ich habe schon ein paar Ehrenhacken bereit. Ich muss nur noch die Namen der Studenten eingravieren...", rewards = "Ihr bekommt:\n\n"},
[6392] = {title = "Rückkehr zu Brock", objective = "Bucht einen Greifen nach Thelsamar bei Greifenmeister Gryth Thurden, dann bringt die Ehrenhacken zu Brock Stoneseeker in Thelsamar.", description = "Für ein geringes Entgelt könnt Ihr einen Greifenritt nach Thelsamar buchen... wenn Ihr schon einmal dort gewesen seid. Greifen fliegen nur zu Orten, an denen Ihr schon einmal gewesen seid, sprecht also mit jedem Greifenmeister, den Ihr seht, dann könnt Ihr später direkt zu ihm fliegen.\n\nIhr seid schon bei Thorgrum, dem Greifenmeister von Thelsamar, gewesen, daher könnt Ihr jetzt zu ihm zurückkehren. Wenn Ihr in Thelsamar seid, könnt Ihr Brock Stoneseeker die Hacken bringen.\n\nSprecht mit mir, wenn Ihr bereit zum Aufbruch seid.", progress = "Ah, <Name>. Ihr seid aus Ironforge zurück.", completion = "Ihr habt die Hacken. Großartig! Ich werde sie meinen Bergbaustudenten bringen. Sie können es sicher kaum erwarten, sich damit auf die Erzvorkommen von Loch Modan zu stürzen.\n\nDanke für Eure Hilfe, &lt;Name&gt;. Ich stehe in Eurer Schuld, hoffe jedoch, dieses Geld wird wenigstens Eure Reisekosten decken.", rewards = "Ihr bekommt:\n\n"},
[6393] = {title = "Krieg der Elementare", objective = "Bringt 10 Pyrophore zu Tsunaman in Sonnenfels.", description = "Das Tribunal der Gezeiten hat mich geschickt, um den Feuerelementaren hier im Steinkrallengebirge den Krieg zu erklären. Neptulon der Gezeitenjäger, der Lord aller Wasserelementare hier, hat ein persönliches Interesse daran, dass unsere feurigen Vettern ausgelöscht werden.\n\n<Name>, Ihr könnt mir helfen, die Gunst des Tribunals zu erringen, indem Ihr die Feuerelementare im verbrannten Tal vernichtet. Wenn Feuerelementare zerstört werden, hinterlassen sie Pyrophore. Bringt sie mir, dann werde ich Euch belohnen.", progress = "Das Tribunal der Gezeiten wird ungeduldig. Es will diesen Krieg beenden, der seit Äonen durch alle Dimensionen wütet. Meine Brüder brennen darauf, dass man ihnen endlich den ruhmreichen Sieg über die verhassten Feuerelementare meldet. Habt Ihr die Pyrophore, die ich benötige?", completion = "Die Wassergeister in mir prickeln vor Aufregung. &lt;Name&gt;, durch Euren Einsatz kann ich dem Tribunal der Gezeiten nun einen glorreichen Sieg vermelden.", rewards = "Ihr bekommt:\n\n"},
[6394] = {title = "Thazz'rils Hacke", objective = "Bringt Thazz'rils Hacke zu Großknecht Thazz'ril.", description = "<Name>, Ihr seid ein <Volk>, auf den man sich verlassen kann. Würdet Ihr wohl eine weitere Aufgabe für mich erledigen?\n\nVor einiger Zeit suchte ich in einer Höhle im Norden nach Mineralien und vergaß dort meine Lieblingshacke. Als ich später dorthin zurückkehrte, hausten tückische Bestien in dieser Höhle! Würdet Ihr diese Höhle aufsuchen, es ist der Koven der Burning Blade, und meine Hacke holen?\n\nIch habe sie in einer Kammer mit Wasserfällen gelassen. Meine Hacke ist verzaubert, daher könnt Ihr sie im Dunkeln sehen und müsst Euch keine Sorgen machen, wie Ihr sie findet ... nur diejenigen, die sie bewachen, müsst Ihr fürchten!", progress = "Habt Ihr den Koven der Burning Blade betreten, <Name>? Und habt Ihr meine Hacke gefunden?", completion = "Prima, Ihr habt sie! Vielen Dank, &lt;Name&gt;. Das ist meine Lieblingshacke! Wenn meine Peons irgendwann einmal fertig sind, diese Bäume zu fällen, finden wir vielleicht eine hübsche Höhle für den Bergbau!", rewards = "Ihr bekommt:\n\n"},
[6395] = {title = "Marlas letzter Wunsch", objective = "Bringt Samuel Fipps' sterbliche Überreste zu Marlas Grab und kehrt dann zu Novize Elreth zurück.", description = "Meine Freundin Marla Fipps lebte vor der Seuche mit ihrem Mann Samuel zusammen, doch als die Seuche kam, erlag Samuel ihr und lief zur Geißel über.\n\nMarla wurde der Untod erspart, doch sie starb durch die Hand ihres jetzt hirnlosen Mannes. Aber ihre Liebe war so stark, dass sie sterbend den letzten Wunsch äußerte, zusammen mit ihrem geliebten Samuel begraben zu werden.\n\nSamuel Fipps streift durch ein verwüstetes Lager nordöstlich von Deathknell. Besiegt ihn und erfüllt Marlas Wunsch: Begrabt ihn in ihrem Grab in der ersten Reihe unseres Friedhofs.", progress = "Wir müssen unsere Toten achten, <Name>. Darin unterscheiden wir uns von der Geißel...", completion = "Ihr habt heute eine gute Tat vollbracht, &lt;Name&gt;. Der Kampf gegen die Geißel geht zwar weiter, aber hoffen wir, dass Marla und Samuel gemeinsam Frieden in ihrer letzten Ruhestätte finden.", rewards = "Ihr bekommt:\n\n"},
[6401] = {title = "Kaya lebt", objective = "Teilt Tammra Windfield, die in Sonnenfels lebt, die gute Nachricht mit.", description = "Teilt Tammra Windfield, Kayas Tante, die in Sonnenfels lebt, die gute Nachricht mit! Kaya lebt! Wir hatten sie nach dem brutalen Angriff auf unser Dorf schon verloren geglaubt. Folgt dem Pfad nach Westen, um nach Sonnenfels zu gelangen.", progress = nil, completion = "Dem Himmel sei Dank, meine Nichte Kaya lebt! Das sind wahrlich gute Neuigkeiten. Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[6402] = {title = "Treffen in Stormwind", objective = "Reist nach Stormwind und begebt Euch zu den Stadttoren. Sprecht mit Knappe Rowe, damit er Marshal Windsor über Eure Ankunft informiert.", description = "Ihr sollt Euch an den Toren von Stormwind mit Windsor treffen.\n\nWas Windsor Euch eröffnen wird, wird das gesamte Königreich in den Grundfesten erschüttern!\n\nVersucht aber nicht, allein dorthin zu gehen, <Name>. Ihr müsst eine ganze Armee zusammenscharen! Versammelt Eure Mitstreiter. Zu den Waffen!", progress = nil, completion = "Bevor wir beginnen, bitte ich Euch, dass Ihr zuerst eine Armee zusammenzieht. Wir haben es hier schließlich mit einem Drachen zu tun!", rewards = "Ihr bekommt:\n\n"},
[6403] = {title = "Die große Maskerade", objective = "Folgt Reginald Windsor durch Stormwind. Schützt ihn vor Gefahren!", description = "Das war vielleicht ein Abenteuer. Ich schulde Euch großen Dank. Vielleicht, wenn alles gesagt und getan ist...\n\nWie Ihr zweifellos schon bemerkt haben werdet, sind Lady Prestor und Onyxia ein und dieselbe Person. Sie ist die Brut von Deathwing, Zwillingsschwester des Tyrannen der Spitze, Nefarian.\n\nViel zu lange schon hat sie ihren gierigen Blick auf unser Königreich gerichtet. Sogar der Hochlord steht schon unter dem Bann ihrer Zaubertricks - eine Marionette. Heute wird damit Schluss gemacht... Der Bann wird gebrochen.\n\nSorgt Euch nicht, denn gemeinsam werden wir siegen!\n\nSeid Ihr bereit?", progress = "Ich... Ich... Ich war machtlos.", completion = "&lt;Bolvar hält das zertrümmerte Medaillon in den Händen.&gt;\n\nDie Magie darin muss wieder entfacht werden. Das Großdrachenauge muss eingestellt werden.\n\nWindsors Opfer hat unser Königreich befreit, aber die Bedrohung durch Onyxia und ihresgleichen besteht immer noch.\n\nDieses Medaillon hielt meinen Geist und meinen Körper gefangen. Es ließ mich jedoch auch in Onyxias Geist blicken - zeigte mir ihre Geheimnisse. Die Visionen sind zwar jetzt etwas verschwommen, aber an manche Dinge erinnere ich mich doch.", rewards = "Ihr bekommt:\n\n"},
[6421] = {title = "Steinschlagklamm", objective = "Erkundet die Tiefen der Höhle in der Steinschlagklamm und bringt Mor'rogal in Sonnenfels 10 Resonitkristalle, damit er sie untersuchen kann.", description = "Irgendetwas stimmt hier im Steinkrallengebirge nicht. Spürt Ihr die Spannung, die in der Luft liegt, <Name>?\n\nSüdlich von hier liegt eine tiefe Höhle in der Steinschlagklamm. Die Kobolde dort schürfen wie wild nach einem seltenen Kristall, dem so genannten Resonit. Ich möchte, dass Ihr mir ein paar Erzproben bringt, damit ich herausfinden kann, was in dieser Höhle vor sich geht. Ich hätte auch gern, dass Ihr die Tiefen dieser Höhle untersucht.\n\nGeht nun, <Klasse>, es ist von größter Bedeutung, dass ich in Erfahrung bringe, welche Bösartigkeiten unter diesen Bergen lauern.", progress = "Was habt Ihr in der Steinschlagklamm in Erfahrung bringen können? Ich erinnere mich an eine Legende, die irgendwas mit Resonit zu tun hatte... Ich komme nur nicht darauf. Vielleicht wird es etwas Licht auf ihre verschlagenen Absichten werfen, wenn wir erst wissen, was auf dem Grund der Höhle liegt.", completion = "Ah... ja! Das ist es. Die Resonitkristalle enthalten eine Spur Erdmagie. Die Kobolde müssen sehr tief gegraben haben, um einen Irdenen zu finden.\n\nDen Legenden nach sind die Irdenen Kreaturen, die von den Titanen geschaffen wurden. Sie erschufen das Land, auf dem wir heute stehen. Das ist wahrlich eine Bedrohung, die wir nicht ignorieren dürfen.\n\n&lt;Mor'rogal schüttelt seinen Kopf.&gt;\n\nVielleicht kann ich diese Erzproben verzaubern, um sie gegen die üblen Pläne der Kobolde zu verwenden.", rewards = "Ihr bekommt:\n\n"},
[6441] = {title = "Satyrhörner", objective = "Sammelt für Pixel im Splintertreeposten 16 Satyrhörner.", description = "He! Ich bin auf der Durchreise nach Ratchet, habe ganz Ashenvale durchquert und mich entschlossen, hier in Splintertree Rast zu machen. Ich suche immer nach guten Gelegenheiten und es scheint mir, dass in Ratchet zurzeit Satyrhörner sehr gefragt sind.\n\nNachdem ich mich hier ein bisschen umgehört habe, glaube ich, dass die Satyrn in Night Run, Satyrnaar und Xavian genau die Art Hörner besitzen, die ich suche. Ich kann mich mit diesen Satyrn nicht messen... aber Ihr!\n\nIch sag Euch was: Wenn Ihr mir die Hörner bringt, soll es Euer Schaden nicht sein.", progress = "Ich hoffe, Ihr könnt mir bald ein paar dieser Hörner besorgen, <Name>. Ich muss in Kürze nach Ratchet zurück!", completion = "Die sind perfekt, &lt;Name&gt;! Danke, dass Ihr mir geholfen habt!\n\nOh, und das hier ist für Eure Mühen...", rewards = "Ihr bekommt:\n\n"},
[6442] = {title = "Die Naga am Zoramstrand", objective = "Bringt Marukai am Zoramstrand 20 Köpfe von Rächerflossen.", description = "Entlang der Küste hier lauert das Böse, <Volk>.\n\nEs ist die Ruhestätte der untergegangenen Stadt Zoram, die vor langer Zeit zerstört wurde und im Meer versank. Sie war verloren und fast vergessen.\n\nJetzt allerdings sind die Naga zurückgekehrt, aber warum, wissen wir nicht. Die Gründe sind jedoch auch nicht weiter wichtig. Wir müssen das Land verteidigen, um das wir so hart gekämpft haben.\n\nBringt mir 20 ihrer Köpfe! Treibt die Naga in die Tiefen zurück!", progress = "Die Naga werden immer mehr, <Name>. Bitte erledigt diese Aufgabe für mich.", completion = "Wir könnten mehr Eures Schlags hier brauchen, &lt;Name&gt;. Danke für Eure Hilfe.", rewards = "Ihr bekommt:\n\n"},
[6461] = {title = "Blutfresser", objective = "Xen'zilla am Malaka'jin möchte, dass Ihr 10 Kluftmooskrabbler und 7 Kluftmoosgiftspucker tötet.", description = "Wir Trolle hier am Malaka'jin haben von dem Land profitiert. Das Steinkrallengebirge bietet reiche Jagdgründe, von denen wir leben können.\n\nIn letzter Zeit jedoch scheinen wir die falschen Gäste angezogen zu haben... Die Spinnen in diesen Bergen haben nachts unsere Lager überfallen, um uns unsere Jagdbeute zu stehlen.\n\nWenn Ihr uns helfen könntet, diese schrecklichen Bestien zu töten, würden wir hier am Malaka'jin zutiefst in Eurer Schuld stehen. Die Spinnen sind überall im Steinkrallengebirge - geht einfach von hier aus nach Norden, dann werdet Ihr sehen, was ich meine.", progress = nil, completion = "Toll! Gute Neuigkeiten: Vielleicht haben wir heute Nacht ein paar ungebetene Tafelgäste weniger.\n\nVielen Dank, &lt;Name&gt;. Wir stehen für immer in Eurer Schuld.", rewards = "Ihr bekommt:\n\n"},
[6462] = {title = "Troll-Glücksbringer", objective = "Bringt Mitsuwa im Zoram'gar-Außenposten 8 Troll-Glücksbringer.", description = "Meine Leute waren mit vielen hochheiligen Troll-Glücksbringern im Gepäck unterwegs, aber dann wurden sie von Distelfellfurbolgs angegriffen und getötet, bevor sie Zoram'gar erreichen konnten! Diese elenden Furbolgs!\n\nIch vermisse meine getöteten Brüder und Schwestern, aber wir werden uns im Jenseits wiedersehen. Die Troll-Glücksbringer haben in dieser Welt jedoch hohen Wert. Es ist eine Schande, dass sie jetzt in den Händen der Furbolgs sind!\n\n<Name>, Ihr müsst diese Glücksbringer zurückholen! Sie befinden sich in Kisten in der Höhle, einer Höhle der Distelfelle am Ende des Lagers der Distelfelle nördlich von Astranaar.", progress = "Habt Ihr die Glücksbringer gefunden, <Name>? Jede Sekunde, die die Furbolgs im Besitz dieser heiligen Gegenstände sind, bringt mein Blut mehr zum Kochen!", completion = "Ihr habt sie gefunden! Danke! Danke, &lt;Name&gt;! Ihr wisst ja gar nicht, welch großen Dienst Ihr mir erwiesen habt.\n\nEin Troll ohne Glücksbringer ist wie ein Orc ohne Kampfnarben...\n\nWertlos.", rewards = "Ihr bekommt:\n\n"},
[6481] = {title = "Der Irdene erhebt sich", objective = "Öffnet das Resonitfässlein mit dem verzauberten Resonitkristall und tötet Goggeroc. Kehrt mit der Vollzugsmeldung und dem verzauberten Resonitkristall zu Mor'rogal zurück.", description = "Ihr habt eine dunkle Bedrohung für das Land entdeckt, <Klasse>. Das Resonitfässlein, das Ihr in der Höhle gefunden habt, birgt einen schlummernden Irdenen namens Goggeroc.\n\nIch habe die Mixtur der Resonitkristalle, die Ihr gesammelt habt, mit Hilfe meiner Schamanenkräfte verändert. Nehmt den verzauberten Resonitkristall und zerschmettert das Resonitfässlein, in dem sich der Irdene befindet.\n\nWenn Goggeroc erwacht, wird er noch geschwächt sein... erschlagt ihn, <Name>!", progress = nil, completion = "Das sind gute Neuigkeiten, &lt;Klasse&gt;! Ich fürchte mich vor dem, was ein Irdener in Kalimdor anrichten könnte.\n\nGoggeroc zu töten war eine Tat, die eines Helden würdig ist. Das habt Ihr gut gemacht. Die Bewohner des Steinkrallengebirges und Kalimdors stehen in Eurer Schuld, &lt;Klasse&gt;.\n\nNehmt dies als Belohnung, oh Ehrwürdiger.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nEulenbarts ArmschienenHandgelenksschutz der Wolfsmähne\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[6482] = {title = "Freiheit für Ruul", objective = "Begleitet Ruul und sprecht dann mit Yama Snowhoof im Splintertreeposten.", description = "Huch? Wer seid Ihr?\n\n<Name>? Ihr seid kein Furbolg. Sie sind verflucht! Sie hielten mich für einen Bären und fingen mich. Jetzt lassen sie mich verhungern! Meine Kraft schwindet...\n\nHelft mir zu entkommen, dann sprecht mit meiner Schwester Yama im Splintertreeposten im Osten.\n\n<Name>! Ich muss entkommen!", progress = nil, completion = "Ihr habt meinen Bruder gefunden! Er wurde vom Distelfellstamm gefangen? Das ist ja schrecklich, denn viele Furbolgs sind zwar edle Kreaturen, aber die Distelfelle sind verderbt.\n\nVielen Dank, dass Ihr meinen Bruder gerettet habt, &lt;Name&gt;. Ich wage gar nicht darüber nachzudenken, wie sie den armen Ruul wohl behandelt haben. Er wird nach diesem Martyrium bestimmt eine ganze Weile schlafen ...", rewards = "Ihr bekommt:\n\n"},
[6501] = {title = "Das Großdrachenauge", objective = "Ihr müsst die Welt nach jemandem absuchen, der fähig ist, die Macht des Fragments des Großdrachenauges wieder herzustellen. Die einzige Information, die Ihr über ein solches Wesen besitzt ist, dass es existiert.", description = "Ich habe leider nicht mehr als ein Fragment des zertrümmerten Medaillons zu bieten.\n\nIhr müsst einen anderen aus dem Geblüt der Großdrachen finden, der bereit ist, Euch zu helfen, einen neuen Schlüssel zu schmieden. Sobald Ihr diesen Schlüssel habt, müsst Ihr zum Drachensumpf in den Marschen von Dustwallow reisen. Dort findet Ihr ihr Lager, <Name>.\n\nWo Ihr weitere Klans finden könnt, die gewillt wären, Euch zu helfen? Das weiß ich leider nicht ... Es soll angeblich welche geben. Einige sollen sogar unter uns leben und arbeiten, getarnt als Angehörige der humanoiden Völker. Ich wünsche Euch Glück.", progress = "Ich spüre eine Aura des Bösen, die von Euch ausgeht, <Volk>. Was könntet Ihr besitzen, das eine solche Aura ausstrahlt?", completion = "Ich hätte es wissen müssen... ein Stück der schwarzen Großdrachenbrutmutter Onyxia. Wie widerlich...", rewards = "Ihr bekommt:\n\n"},
[6502] = {title = "Drachenfeueramulett", objective = "Ihr müsst das Blut des schwarzen Großdrachen-Helden von General Drakkisath bekommen. Ihr findet Drakkisath in seinem Thronsaal hinter den Hallen des Aufstiegs auf der Blackrockspitze.", description = "Das ist ein Stück des Großdrachen. Eine Schuppe - verzaubert und transformiert. Als Ganzes hätte sie Zugang zum Hort der Bestie verschafft. Zertrümmert ist sie nutzlos.\n\nEs ist möglich, den Gegenstand zu reparieren, aber dazu wäre das Blut eines schwarzen Großdrachenhelden erforderlich. Es gibt einen... Er ist bekannt als General Drakkisath, Herrscher über die Drachenbrutarmeen von Nefarian. Vielleicht habt Ihr schon von ihm gehört?\n\nBringt mir sein Blut, <Volk>, dann verzaubere ich das Fragment in etwas, das Euch Zugang zu Onyxias Hort verschaffen wird.", progress = "Der Fluss der Zeit hält niemals an oder wird auch nur um etwas langsamer, <Volk>. Mein Leben dauert ewig, Eures jedoch nicht. Vergeudet die Zeit nicht, die Euch noch bleibt...", completion = "Dieses Amulett gewährt Euch den Zugang, auf den Ihr aus seid. Onyxias Hort befindet sich in den Marschen von Dustwallow. Solange Ihr das Amulett habt, können ihre Zauberschütze Euch nicht am Eintreten hindern.\n\nDer blaue Drachenschwarm wünscht Euch Glück, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nDrachenfeueramulett"},
[6503] = {title = "Die Kundschafter von Ashenvale", objective = "Tötet 9 Kundschafter von Ashenvale und kehrt dann zu Kuray'bin im Splintertreeaußenposten zurück.", description = "Es wurde uns berichtet, dass Kundschafter Ashenvales vor nicht langer Zeit den Außenposten der Silverwing verlassen haben und sich jetzt in der Nähe unserer Territorien im Wald herumtreiben. Wir möchten nicht, dass sie unsere Verteidigung ausspionieren!\n\nSchleicht durch den Wald südlich unseres Postens und östlich des Außenpostens der Allianz von Silverwing. Findet und tötet die Kundschafter und kehrt dann zu mir zurück.", progress = nil, completion = "Sehr gut, &lt;Name&gt;. Eure Jagdkünste sind beeindruckend...\n\nDer Verlust dieser Kundschafter wird helfen, die Allianz ihrer Augen zu berauben, und wenn sie keine Informationen mehr bekommt, wird sie wohl kaum weiter angreifen.", rewards = "Ihr bekommt:\n\n"},
[6504] = {title = "Die verlorenen Seiten", objective = "Findet die 12 fehlenden Seiten der Schredderanleitung und fügt sie zu den Kapiteln 1, 2 und 3 zusammen.", description = "Ich habe gerade diesen Schredder in Ratchet abgeholt und war auf dem Heimweg ins Holzfällerlager der Warsong, in dem ich eigentlich Dienst verrichten sollte. Man hat mir eine Anleitung zur Bedienung des Schredders mitgegeben, aber auf dem Rückweg hat ein starker Windstoß sie mir aus den Händen geweht. Die Seiten sind überallhin geflogen und mir blieb nur noch der Einband.\n\nDie Seiten könnten mittlerweile überall sein, nehme ich an ... aber ich weiß nicht, wie ich den Schredder ohne sie benutzen soll! Würdet Ihr sie für mich suchen?", progress = "Hoffentlich findet Ihr die Seiten bald, <Name>! Ich muss wirklich wieder zurück an die Arbeit!", completion = "Lesen ist nicht gerade meine Stärke... aber jetzt kann ich endlich wieder zurück an die Arbeit! Danke, &lt;Name&gt;!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchredderbedienungshandschuheÖlige Handlappen\n\nIhr bekommt außerdem:\n\n"},
[6521] = {title = "Eine unheilige Allianz", objective = "Bringt den Kopf von Botschafter Malcin zu Varimathras nach Undercity.", description = "Malcin behauptet, dass er sich abseits der Hügel von Razorfen aufhalte. Dieser Botschafter muss getötet werden - seine Mission in den Augen des Lichkönigs ein glatter Fehlschlag sein.\n\nSeine Anwesenheit dort erklärt vieles von dem, was wir über diese Gegend herausgefunden haben - einige der Stacheleber sind beängstigend stark geworden und zeigen erste Symptome der Seuche. Das muss in der Tat ein Anzeichen dafür sein, dass sie irgendeine Übereinkunft getroffen haben.\n\nSucht Malcin und tötet ihn, <Name>. Kommt zurück, wenn Ihr das erledigt habt.", progress = "Habt Ihr den Botschafter gefunden, <Name>? Ist er tot?\n\nWir können es uns nicht leisten, dass die Geißel in Kalimdor Fuß fasst. Sie ist bereits schon gefährlich genug für unsere eigenen Grenzen, ein Zweifrontenkrieg wäre zu gefährlich.\n\nDas einzig Positive an den Ereignissen, von denen Ihr mir erzähltet, ist, dass die Greisin nicht verderbt zu sein scheint. Sie muss tief in ihrem Herzen wissen, dass die Geißel große Macht bringen kann, dass das Brachland jedoch nicht wirklich ihr gehören würde, wenn sie sich auf den Handel einließe.", completion = "Gut. Gut gemacht, &lt;Klasse&gt;.\n\nDa Malcin jetzt tot ist, wissen wir zumindest, dass der Vormarsch der Geißel aufgehalten wird. Die Dunkle Fürstin dankt Euch für Eure Bemühungen und möchte Euch zur Belohnung ein Geschenk machen.\n\nWir wissen zwar nicht, wie groß der Einfluss der Geißel in den Hügeln ist, aber wir werden bestimmt schon bald einiges über ihre Pläne herausfinden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchädelbrecherNagelspeierZelotenrobe\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[6522] = {title = "Eine unheilige Allianz", objective = "Bringt die kleine Rolle zu Varimathras nach Undercity.", description = "Milady,\n\nIhr wisst sehr genau, was wir Euch anbieten. Die Gelegenheit, das Brachland und das dahinter liegende Gebiet zu erobern, ist nicht zu verachten. Wir verlangen dafür nur Eure Hilfe. Mit Hilfe meinen wir nicht weniger, als dass Ihr uns die Freiheit zugesteht, in dem Gebiet aktiv zu werden.\n\nErlaubt uns bitte, dies weiter auszuführen. Wir haben große Macht und sind gewillt, sie mit jenen zu teilen, die weise genug sind, sich uns anzuschließen. Ich werde mich bis auf weiteres abseits der Hügel von Razorfen aufhalten.\n\nHochachtungsvoll,\nBotschafter Malcin", progress = "Worüber wollt Ihr mit mir sprechen, <Name>? Es muss wohl wichtig für Euch sein, wenn Ihr mich ständig belästigt.", completion = "Ich erkenne die Insignien auf dieser Rolle, &lt;Name&gt;. Ihr habt dies bei der Greisin gefunden, die über den Kral von Razorfen herrscht? Interessant.\n\nDie Geißel scheint sich also offenbar nicht mit einem Kontinent zufrieden zu geben. Dieser Botschafter Malcin - der diese Notiz geschrieben hat - ist einer der von der Geißel verseucht wurde. Er war ein menschlicher Diplomat des Königreichs Lordaeron, bevor sich alles ... verändert hat.\n\nFalls die Geißel versucht, in Kalimdor Fuß zu fassen, liegt es an uns zu handeln.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6523] = {title = "Schützt Kaya", objective = "Begleitet Kaya Flathoof zum Camp Aparaje und kehrt dann zu Makaba Flathoof am südöstlichen Rand des Steinkrallengebirges zurück.", description = "Habt Dank für meine Rettung! Wir müssen schnell fort von hier, ehe man bemerkt, dass ich frei bin. Bitte begleitet mich zum Camp Aparaje. Von dort aus kenne ich den Weg.\n\nMein Vater Makaba Flathoof wird unbedingt wissen wollen, dass ich in Sicherheit bin.", progress = nil, completion = "Kaya lebt! Ich habe Euch für ihre Rettung zu danken, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[6541] = {title = "Meldung bei Kadrak", objective = "Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak.", description = "Seid Ihr jemals im Norden von Ashenvale gewesen? Die Horde hat dort vor kurzem einen Außenposten am Zoramstrand errichtet und wir können immer ein paar neue Rekruten gebrauchen, die uns helfen, unsere neuen Grenzen zu verteidigen.\n\nWenn Ihr der Meinung seid, dass Ihr dafür in Frage kommt, sucht Kadrak im Wachturm im Norden des Brachlands auf. Er leitet die Ashenvalekampagne und kann Euch weitere Befehle geben.", progress = nil, completion = "Ashenvale ist ein geteiltes Land, aber unsere jüngsten Bemühungen waren sehr erfolgreich. Wir haben jetzt nicht nur einen Außenposten am Zoramstrand, sondern noch einen weiteren nördlich von hier. Er heißt Splintertree.", rewards = "Ihr bekommt:\n\n"},
[6542] = {title = "Meldung bei Kadrak", objective = "Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak.", description = "Seid Ihr jemals im Norden von Ashenvale gewesen? Die Horde hat dort vor kurzem einen Außenposten am Zoramstrand errichtet und wir können immer ein paar neue Rekruten gebrauchen, die uns helfen, unsere neuen Grenzen zu verteidigen.\n\nWenn Ihr der Meinung seid, dass Ihr dafür in Frage kommt, sucht Kadrak im Wachturm im Norden des Brachlands auf. Er leitet die Ashenvalekampagne und kann Euch weitere Befehle geben.", progress = nil, completion = "Ashenvale ist ein geteiltes Land, aber unsere jüngsten Bemühungen waren sehr erfolgreich. Wir haben jetzt nicht nur einen Außenposten am Zoramstrand, sondern noch einen weiteren nördlich von hier. Er heißt Splintertree.", rewards = "Ihr bekommt:\n\n"},
[6543] = {title = "Die Warsongberichte", objective = "Bringt die Warsongberichte dem Warsongspäher, dem Warsongläufer und der Warsongvorhut. Meldet die Neuigkeiten, die Ihr von ihnen erfahrt, Kadrak im nördlichen Wachturm des Brachlands.", description = "Ich habe kürzlich ein paar Späher nach Ashenvale entsandt und brauche jetzt einen Läufer, der ihnen neue Befehle übermittelt und mir einen Bericht über deren Entdeckungen bringt.\n\nEuer erster Halt sollte der Zoram'gar-Außenposten an der Küste Richtung Westen sein. Dort solltet Ihr den ersten Läufer finden. Ihr müsst weiterhin beim Splintertreeposten im Norden und an der Straße nach Osten, die nach Azshara führt, Halt machen. Dort findet Ihr einen Späher und einen Vorreiter.\n\nErstattet allen Bericht und lasst Euch von ihnen über ihre Entdeckungen informieren.", progress = "Beeilt Euch, <Name>. Sie müssen die Berichte erhalten, es ist wichtig.", completion = "Wie ich sehe, kann ich auf Euch zählen. Diese Neuigkeiten sind unerlässlich für unsere Pläne, unsere Position in Ashenvale zu festigen. Jetzt können wir unseren nächsten Schritt planen.", rewards = "Ihr bekommt:\n\n"},
[6544] = {title = "Toreks Angriff", objective = "Eskortiert Torek bei seinem Angriff auf den Außenposten der Silverwing und Duriel Moonfire. Erstattet dann Ertog Ragetusk im Splintertreeposten Bericht.", description = "He! <Klasse>! Kommt mal her!\n\nMeine Räuber und ich wollten gerade den Außenposten der Silverwing im Westen angreifen. Unser Ziel ist der dortige Anführer, Duriel Moonfire. Späher berichten, dass der Außenposten durch Schildwachen und Krieger stark verteidigt wird. Das wird ein ruhmreicher Kampf!\n\nWollt Ihr an dem Ruhm teilhaben und uns helfen, <Name>? Falls ja, könnt Ihr meinem Vorgesetzten Ertog Ragetusk in Splintertree später davon berichten.\n\nWas meint Ihr? Seid Ihr dabei?", progress = nil, completion = "Toreks Angriff war also erfolgreich! Gut gemacht, &lt;Name&gt;. Nachtelfen sind angemessene Feinde. Ein bisschen mager zwar, aber stark und wild! Die Schlacht war bestimmt eine Augenweide...\n\nUnd ich hoffe, Ihr habt Euch ein paar Narben verdient!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPolierter WanderstabSchichtmetallentersäbel\n\nIhr bekommt außerdem:\n\n"},
[6545] = {title = "Warsongläufer-Update", objective = "Ihr bringt mir also meine Befehle? Es ist immer wieder schön, einen neuen Rekruten mit Temperament und starkem Willen kennen zu lernen.\n\nIhr solltet besser schnell lernen, wenn Ihr hier am Leben bleiben wollt. Die Gefahr durch die Naga wächst, <Name>. Ich habe alles beobachtet und mich, seit ich hier in diesem Außenposten eintraf, gegen mehrere Angriffe verteidigen müssen.\n\nWenn Ihr Euch entschließen wollt, uns bei unseren Bemühungen beizustehen, sprecht mit einem der anderen hier im Außenposten.", description = nil, progress = "Ihr bringt mir also meine Befehle? Es ist immer wieder schön, einen neuen Rekruten mit Temperament und starkem Willen kennen zu lernen.\n\nIhr solltet besser schnell lernen, wenn Ihr hier am Leben bleiben wollt. Die Gefahr durch die Naga wächst, <Name>. Ich habe alles beobachtet und mich, seit ich hier in diesem Außenposten eintraf, gegen mehrere Angriffe verteidigen müssen.\n\nWenn Ihr Euch entschließen wollt, uns bei unseren Bemühungen beizustehen, sprecht mit einem der anderen hier im Außenposten.", completion = "So, mein neuer Bericht wird Kadrak alles erklären. Ihr müsst dies so schnell wie möglich zu ihm zurückbringen.", rewards = "Ihr bekommt:\n\nWarsongläufer-Update"},
[6546] = {title = "Warsongvorhut-Update", objective = "Auf diesem Weg lauern viele Gefahren, <Name>. Daran solltet Ihr immer denken, wenn Ihr diese Lande bereist. Die Bedrohung durch die Allianz ist nahe.\n\nWir sehen uns an allen Fronten dem Feind gegenüber. Die Satyrn sind eine ernsthafte und verbreitete Macht im östlichen Ashenvale. Ich habe weiterhin herausgefunden, dass die Naga ein großes Gebiet von Azshara übernommen haben.\n\nEs ist schön zu sehen, dass wir unsere Reihen immer noch aufstocken können... seid auf das gefasst, was vor Euch liegt, <Name>.", description = nil, progress = "Auf diesem Weg lauern viele Gefahren, <Name>. Daran solltet Ihr immer denken, wenn Ihr diese Lande bereist. Die Bedrohung durch die Allianz ist nahe.\n\nWir sehen uns an allen Fronten dem Feind gegenüber. Die Satyrn sind eine ernsthafte und verbreitete Macht im östlichen Ashenvale. Ich habe weiterhin herausgefunden, dass die Naga ein großes Gebiet von Azshara übernommen haben.\n\nEs ist schön zu sehen, dass wir unsere Reihen immer noch aufstocken können ... seid auf das gefasst, was vor Euch liegt, <Name>.", completion = "Bringt Kadrak meinen neuen Bericht. Schnellstens, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nWarsongvorhut-Update"},
[6547] = {title = "Warsongspäher-Update", objective = "Haltet die Augen offen, <Volk>. Oftmals verstecken sich Elfen in den Schatten...\n\nWir müssen immer wachsam sein. Wir haben sehr hart daran gearbeitet, dieses Land zu erobern, und die Elfen suchen nur nach einer Gelegenheit, es uns abzunehmen.\n\nIch nehme an, Ihr habt neue Befehle von Kadrak für mich?", description = nil, progress = "Haltet die Augen offen, <Volk>. Oftmals verstecken sich Elfen in den Schatten...\n\nWir müssen immer wachsam sein. Wir haben sehr hart daran gearbeitet, dieses Land zu erobern, und die Elfen suchen nur nach einer Gelegenheit, es uns abzunehmen.\n\nIch nehme an, Ihr habt neue Befehle von Kadrak für mich?", completion = "Berichtet Kadrak, wie erfolgreich wir die Nachtelfen hier aufgehalten haben. Unsere Pläne laufen gut.", rewards = "Ihr bekommt:\n\nWarsongspäher-Update"},
[6548] = {title = "Rächt mein Dorf", objective = "Tötet 8 Grobiane der Grimmtotem und 6 Söldner der Grimmtotem. Kehrt dann zu Makaba Flathoof am südöstlichen Rand des Steinkrallengebirges zurück.", description = "Der Grimmtotemklan hat mein Dorf überfallen und fast alle getötet. Ich habe so viele ich konnte niedergestreckt, bin aber nur um Haaresbreite lebend entkommen.\n\nJetzt wünsche ich mir nichts mehr, als noch mehr von ihnen tot zu sehen, <Name>. Ihr findet sie gleich westlich von hier.", progress = "Habt Ihr sie schon getötet?", completion = "Ich danke Euch, &lt;Name&gt;... aber ich werde niemals vergessen, was die Grimmtotem meinem Dorf angetan haben.", rewards = "Ihr bekommt:\n\n"},
[6561] = {title = "Blackfathom-Schurkerei", objective = "Bringt den Kopf des Twilight-Lords Kelris zu Bashana Runetotem in Thunder Bluff.", description = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'Mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.\n\nDie Kultisten der Twilight-Hammer haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'mai, um Macht zu erlangen.\n\nBitte, erschlagt Kelris und bringt Bashana in Thunder Bluff seinen Kopf, <Name>.", progress = "Möge die Erdenmutter mit Euch sein, <Name>.\n\nUnser Ziel sollte Friede auf der Erde sein und unter denen, die sie bewohnen. Sie hat große Pläne mit der Natur und wir alle müssen unsere Rolle in diesem Plan spielen.", completion = "Kelris hat sich der Argentumdämmerung eine ganze Weile entzogen.\n\nEine Zeit lang galt er sogar als tot oder vermisst.\n\nIndem Ihr seinem Regime ein Ende gemacht habt, habt Ihr die Leben vieler Unschuldiger gerettet, &lt;Name&gt;.\n\nGelobt sei die Erdenmutter! Jemanden einem Diener eines Alten Gottes zu opfern, um persönlich davon zu profitieren, ist mehr als verachtenswert!\n\nHeute habt Ihr etwas Großes geleistet! Kelris war eine Kreatur des Bösen und trachtete danach, die Welt wieder in eine Zeit des Chaos zu stürzen, indem er einem der alten Götter huldigte. Danke, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGrabsteinszepterArktischer Rundschild\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[6562] = {title = "Ärger in der Tiefe", objective = "Sprecht in Ashenvale mit Je'neu Sancrea.", description = "Je'neu Sancrea braucht Hilfe. Er befindet sich im Zoram'gar-Außenposten in Ashenvale. Der Nachtelfenwald liegt im Norden des Steinkrallengebirges. Ihr erreicht ihn, indem Ihr über die Scherwindklippe oder nördlich durchs Brachland reist. Der Zoramstrand liegt weit im Westen des Waldes. Seid vorsichtig, <Name>. Dort gibt es Mächte, denen Eure Anwesenheit nicht gefallen wird.", progress = nil, completion = "Tsunaman schickt Euch? Ausgezeichnet. Dann haben wir einiges zu besprechen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6563] = {title = "Die Essenz von Aku'mai", objective = "Bringt 20 Saphire von Aku'mai zu Je'neu Sancrea nach Ashenvale.", description = "Im Eingangsbereich des Tunnels der Blacktfathom-Tiefe findet man überall an den Höhlenwänden große Saphiransammlungen. Kürzlich ist aufgefallen, dass die Naga diese Kristalle abbauen. Bis wir herausgefunden haben, warum sie das tun, sollten wir die Naga einstweilen davon abhalten. Die Kristalle besitzen große Elementarkraft und wenn sie unangemessen eingesetzt werden, könnte man daraus eine mächtige arkane Komponente herstellen.\n\nWerdet Ihr mir helfen, <Name>? Die Blackfathom-Tiefe liegt am Zoramstrand nördlich unseres Außenpostens.", progress = "Wie läuft Eure Suche nach den Kristallen, <Name>? Habt Ihr die Naga beim Abbau der Steine gesehen? Ich bete zu meinen Vorfahren, dass wir den Grund dafür herausfinden, warum sie diese Dinge sammeln.", completion = "Gut gemacht, &lt;Name&gt;. Das sind die Kristalle, von denen ich sprach. Faszinierend...\n\nIch kann die Macht in ihnen spüren. Die Geister des Wassers hängen an ihnen. Was immer die Naga mit ihnen vorhatten... tja, seien wir nur froh, dass sie nicht mehr in ihren Händen sind.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6564] = {title = "Treue zu den Alten Göttern", objective = "Bringt die durchfeuchtete Notiz zu Je'neu Sancrea nach Ashenvale.", description = "Die zerknitterte Notiz trägt eine kaum leserliche Handschrift:\n\n\"Ja, sagt allen Priesterinnen, dass sie mir die Kristalle bringen sollen. Die Wasserelementare sind stark in ihnen und sie werden unseren Aquamanten bei ihren Beschwörungen ungemein dienlich sein.\n\nIndem wir die Kraft dieser Kristalle beherrschen, beschwichtigen wir Aku'mai. Eines Tages werden wir genug Macht haben, um Aku'mai zu uns zurückzuholen. Dann wird die Welt wieder zur Ära ihrer einstigen Größe zurückkehren! Eine Ära, in der die Alten Götter herrschen!\"", progress = "Ja, <Name>? Was ist Euer Begehr? Ich muss noch so viel über die Kristalle lernen, die die Naga zusammentragen.", completion = "Das ist in der Tat interessant. Ich bin froh, dass Ihr mich davon in Kenntnis gesetzt habt.\n\nJetzt können wir unseren Problemen auch einen Namen geben... Lorgus Jett.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6565] = {title = "Treue zu den Alten Göttern", objective = "Tötet Lorgus Jett in der Blackfathom-Tiefe und kehrt dann zu Je'neu Sancrea nach Ashenvale zurück.", description = "Dieser Anhänger der Twilight-Hammer darf seinen Plan nicht in die Tat umsetzen. Die Twilight-Hammer verstehen die Geister der Natur nicht. Sie glauben an die Alten Götter - Kreaturen des Chaos und der Zerstörung, die vor langer Zeit besiegt wurden. Dieser Lorgus darf keinen Erfolg haben. Ihr müsst ihn aufhalten, <Name>. Ich kann mich leider nicht selbst darum kümmern ... ich bin zu schwach.\n\nGeht zur Blackfathom-Tiefe, findet ihn und tötet ihn. Kommt zu mir nach Zoram'gar zurück, wenn Ihr es geschafft habt.", progress = nil, completion = "Sehr gut! Danke, &lt;Name&gt;. Wir mögen zwar die Twilight-Hammer nicht vollständig aufgehalten haben, aber zumindest habt Ihr einen weiteren ihrer Pläne durchkreuzt, die Alten Götter wieder mächtig zu machen.\n\nWer weiß, welche Pläne sie sonst noch verfolgen mochten, aber wir können vorerst beruhigt sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand der FaustKastanienbrauner Mantel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[6566] = {title = "Was der Wind erzählt", objective = "Hört Thrall zu.", description = "Schön, Euch wiederzusehen, <Name>. Der Wind führt Kunde aus den östlichen Königreichen mit sich.\n\nSetzt Euch und lauscht.", progress = "Geduld, <Name>. Passt gut auf!", completion = "Seid Ihr bereit, diese Aufgabe anzunehmen?", rewards = "Ihr bekommt:\n\n"},
[6567] = {title = "Der Champion der Horde", objective = "Sucht Rexxar auf. Der Kriegshäuptling hat Euch erklärt, wo Ihr ihn finden könnt. Sucht die Wege von Desolace zwischen dem Steinkrallengebirge und Feralas ab.", description = "Ich habe Kunde von einem meiner Helden erhalten, dass es einen Weg zum Hort des Großdrachen geben könnte. Ihr müsst ihn suchen.\n\nRexxar streift durch die wüste Einöde von Desolace, immer auf Reisen zwischen dem Steinkrallengebirge und Feralas. Er erwartet Euch.", progress = nil, completion = "Es gibt nur einen Weg in den Hort des Großdrachen, &lt;Volk&gt;.\n\nWisst Ihr, nur die Stärksten des schwarzen Drachenschwarms dürfen den Hort der Brutmutter betreten. Es müssen viele Prüfungen überwunden werden und der Schlüssel, mit dem man hineingelangt, wurde von General Drakkisath persönlich zeremoniell verzaubert!\n\nDa Ihr nicht zu den schwarzen Großdrachen gehört, werdet Ihr wohl auf einige Schwierigkeiten stoßen, wenn Ihr Einlass verlangt.", rewards = "Ihr bekommt:\n\n"},
[6568] = {title = "Nachricht von Rexxar", objective = "Überbringt Myranda der Vettel in den westlichen Pestländern Rexxars Nachricht.", description = "Was wisst Ihr über Illusionen, <Name>? Denn wisset, Ihr müsst eine Illusion erschaffen, um die Verteidigungslinien des schwarzen Drachenschwarms zu umgehen.\n\nIch kenne jemanden, der vielleicht bereit ist, Euch bei Eurem Täuschungsmanöver zu helfen. Sie hat unsereins in der Vergangenheit geholfen, wenn sie ein Unterfangen für würdig erachtete.\n\nIn den Westlichen Pestländern findet Ihr Myranda die Vettel, eine Meisterin der Illusionen... und eine Verbannte der Lordaeron-Allianz. Reist dorthin und nehmt diese Nachricht mit.", progress = "In diesem Teil Lordaerons sieht man nur selten einen aus der Horde. Was habt Ihr für Myranda?", completion = "&lt;Myranda hält die Notiz, schweigt eine Weile, dann lächelt sie.&gt;\n\nWie geht es ihm? Rexxar, meine ich. Oh, bitte, schaut nicht so überrascht drein. Der Brief besteht absichtlich nur aus einem leeren Blatt. Er trägt die Absichten und Gedanken des Schreibers. Angesichts des Inhalts ist es kein Wunder, dass Rexxar so verfahren ist. Stellt Euch vor, man hätte Euch gefangen oder getötet und diese Informationen entdeckt!\n\nAch, wie dem auch sei! Myranda wird Euch helfen, &lt;Volk&gt;. Ich schulde dem Kriegshäuptling noch einen oder zwei Gefallen.", rewards = "Ihr bekommt:\n\n"},
[6569] = {title = "Oculus-Illusionen", objective = "Reist zur Blackrockspitze und sammelt 20 schwarze Drachenbrutaugen. Kehrt zu Myranda der Vettel zurück, sobald Ihr die Aufgabe erfüllt habt.", description = "Ihr möchtet also einer vom schwarzen Drachenschwarm werden, was, <Volk>?\n\nDie Erschaffung einer Illusion, wie Ihr sie wünscht, ist eine Kleinigkeit, aber die für den Zauber erforderlichen Komponenten sind ziemlich schwierig zu beschaffen. Rexxar und der Kriegshäuptling haben Euch mit dieser Mission betraut, also muss Myranda wohl annehmen, dass Ihr fähig dazu seid.\n\nReist zur oberen Zitadelle der Blackrockspitze und tötet genug Mitglieder der schwarzen Drachenbrut, um eine Eurer Taschen mit deren Augen zu füllen.\n\nKehrt zu Myranda zurück, wenn Ihr genügend von dem Reagenz gesammelt habt.", progress = "Die Augen derer, die wir verkörpern möchten, sind die wichtigste Zutat für jede Illusion, <Name>.", completion = "Lasst Myranda mal sehen, &lt;Volk&gt;.\n\nAh ja, ausgezeichnet.\n\nAus diesen Reagenzien wird Myranda ein Medaillon für Euch fertigen, mit dem Ihr eine Illusion erzeugen könnt, die den Torhüter des schwarzen Drachenschwarms täuschen wird.", rewards = "Ihr bekommt:\n\n"},
[6570] = {title = "Aschenschwinge", objective = "Reist zum Drachensumpf in den Marschen von Dustwallow und begebt Euch in Aschenschwinges Bau. Sobald Ihr darin seid, tragt das Amulett der drachischen Subversion und sprecht mit Aschenschwinge.\n\nBereitgestellter Gegenstand: \n", description = "Ich habe dieses Medaillon mit der Magie versehen, die notwendig ist, um eine Illusion zu erschaffen und sie innerhalb der Einfriedung des Höhlenbaus von Aschenschwinge aufrechtzuerhalten.\n\nAschenschwinge ist ein uralter Drache, ein alter Torhüter Nefarians, der die schwere Bürde auf seinen Schultern trägt, jene der Drachenbrut auf die Probe zu stellen, die in den Rang einer Elitewache Onyxias aufsteigen wollen.\n\nReist zum Drachensumpf in den Marschen von Dustwallow und begebt Euch in Aschenschwinges Bau. Sobald Ihr dort seid, legt Ihr das Amulett an und folgt Eurem Schicksal, wo immer es Euch auch hinführen mag!", progress = nil, completion = "Haben wir nur noch so wenige Soldaten, dass Nefarian mir schon Welpen schickt? Du wirst meine Prüfungen nie bestehen, Brutling.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6571] = {title = "Warsongnachschub", objective = "Tragt den Warsongnachschub zusammen: Warsongsägeblätter, Holzfäller-Seil, Warsongöl und die Warsongaxtlieferung für Locke Okarr im Splintertreeposten.", description = "Uns hier im Holzfällerlager der Warsong gehen langsam einige Dinge aus!\n\nUnsere Lieferung Sägeblätter liegt bei Pixel im Splintertreeposten. Jemand muss auch nach Booty Bay reisen, um eine Kiste mit Äxten bei Werftmeister Lozgil abzuholen.\n\nBei unserer Öl- und Seillieferung sieht es jedoch schon schwieriger aus. Die Furbolgs haben die Seile geraubt und die Satyrn haben das Öl abgefangen und nutzen es jetzt für abscheuliche Rituale in Night Run und Satyrnaar!\n\nIch komme in große Schwierigkeiten, wenn ich die Sachen nicht bald ausliefere... könnt Ihr mir helfen?", progress = "Hoffentlich kommt Ihr mit dem Nachschub durch!", completion = "Exzellent, &lt;Name&gt;. Ihr habt mir eine Menge Arbeit erspart!\n\nAber glaubt nicht, dass ich mich nicht erkenntlich zeige!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nWarsongschärpeWarsongstiefelWarsongstulpen\n\nIhr bekommt außerdem:\n\n"},
[6581] = {title = "Warsongsägeblätter", objective = "Direkt aus Ratchet, die Warsongsägeblätter! Jau, die hab ich hier...\n\nAber womit wollt Ihr das bezahlen? Ihr könnt sie nicht einfach so mitnehmen, wisst Ihr! Meine Zeit ist kostbar!\n\nWas ich wirklich brauche, ist eine gute Schusswaffe, die ich auf meine Reisen mitnehmen kann. Ein Mädchen muss sich doch schließlich verteidigen können, wisst Ihr? Es gibt da eine Schusswaffe, die mir wirklich gefällt, und ich bin mir sicher, dass ein Ingenieur kein Problem hätte, so eine anzufertigen.\n\nWenn Ihr mir also eine dieser tödlichen Donnerbüchsen bringen würdet, gebe ich Euch die Sägeblattlieferung. Abgemacht?", description = nil, progress = "Direkt aus Ratchet, die Warsongsägeblätter! Jau, die hab ich hier...\n\nAber womit wollt Ihr das bezahlen? Ihr könnt sie nicht einfach so mitnehmen, wisst Ihr! Meine Zeit ist kostbar!\n\nWas ich wirklich brauche, ist eine gute Schusswaffe, die ich auf meine Reisen mitnehmen kann. Ein Mädchen muss sich doch schließlich verteidigen können, wisst Ihr? Es gibt da eine Schusswaffe, die mir wirklich gefällt, und ich bin mir sicher, dass ein Ingenieur kein Problem hätte, so eine anzufertigen.\n\nWenn Ihr mir also eine dieser tödlichen Donnerbüchsen bringen würdet, gebe ich Euch die Sägeblattlieferung. Abgemacht?", completion = "Das ist perfekt - genau das, was ich wollte! Und hier habt Ihr die Lieferung.", rewards = "Ihr bekommt:\n\nWarsongsägeblätter"},
[6582] = {title = "Die Prüfung der Schädel, Scryer", objective = "Ihr müsst Scryer, den Champion der blauen Großdrachen, finden und ihn töten. Schlagt seinem Kadaver den Schädel ab und bringt ihn zu Aschenschwinge.\n\nIhr wisst, dass Scryer in Winterspring zu finden ist.", description = "Wir alle sind Kinder der Deathwing, Welpe. Wir müssen die Herrschaft über die niederen Aspekte durchsetzen.\n\nWenn Ihr wirklich eines Aufstiegs würdig seid, werden die Geringeren des Drachenschwarms vor Euch niedersinken.\n\nFindet deren Champions und vernichtet sie im Namen unseres Vaters!\n\nBegebt Euch nach Winterspring und spürt den mächtigen Blaudrachen Scryer auf. Zerschmettert ihn und alle anderen des blauen Drachenschwarms, die sich Euch in den Weg stellen. Entreißt ihm seinen Schädel und bringt ihn mir.", progress = "<Aschenschwinge faucht.>", completion = "Eine von etlichen Prüfungen überssstanden...", rewards = "Ihr bekommt:\n\n"},
[6583] = {title = "Die Prüfung der Schädel, Somnus", objective = "Vernichtet den Drachenchampion des grünen Drachenschwarms, Somnus. Nehmt seinen Schädel und bringt ihn zu Aschenschwinge zurück.", description = "Genau wie unser Vater die Aspekte zerschmettert, müssen wir danach trachten, Chaos und Zerstörung unter ihren Kindern anzurichten.\n\nIhr müsst Eure Leistungsfähigkeit im Kampf gegen die schlaflosen Träumer auf die Probe stellen: die Kinder des Gründrachenschwarms.\n\nBegebt Euch zu den Sümpfen des Elends und spürt Somnus auf, den Drachenchampion des Gründrachenschwarms. Lasst Eurem Hass freien Lauf und bezwingt das Insekt ... Kommt mit seinem Schädel zu mir zurück ...", progress = "Kommt erst wieder, wenn Ihr im Blut unserer Feinde gebadet und Euch an ihrem Leiden gelabt habt.", completion = "Eine weitere bestanden...", rewards = "Ihr bekommt:\n\n"},
[6584] = {title = "Die Prüfung der Schädel, Chronalis", objective = "Chronalis, ein Kind Nozdormus, bewacht die Höhlen der Zeit in der Tanariswüste. Vernichtet ihn und bringt seinen Schädel zu Aschenschwinge.", description = "Die Zeitbehüter, Kinder Nozdormusss - Lord der Jahrhunderte...\n\nEs sind derer drei, die die Höhlen der Zeit bewachen, aber nur einer, an dem der schwarze Drachenschwarm interessiert ist: Chronalisss, der Zeitverschieber, bevorzugter Drachling Nozdormusss.\n\nBesssiegt diesssen Champion, denn das wäre ein Schlag, der sssogar den stoischen Sand der Zzzeit erschüttern würde. Kehrt mit seinem Schädel zu mir zzzurück.", progress = "Ironischerweissse ist hier die Zzzeit entscheidend, Welpe.", completion = "Der am meisssten Verhasssssste fehlt Euch noch...", rewards = "Ihr bekommt:\n\n"},
[6585] = {title = "Die Prüfung der Schädel, Axtroz", objective = "Begebt Euch nach Grim Batol und spürt Axtroz auf, den Drachenchampion des Roten Drachenschwarms. Vernichtet ihn und nehmt seinen Schädel. Bringt den Schädel zu Aschenschwinge zurück.", description = "Es war in den Bergen von Grim Batol, wo unser Vater gegen die vereinte Macht der Aspekte wütete. Die feige Tat des Verräters Alexstrasza verschaffte den übrigen Aspekten genug Zeit, um dem Zorn des Vaters zu entkommen.\n\nWasss für ein schändlicher Akt ...\n\nDer Rotdrachenschwarm bewacht heute Grim Batol und ihr Lieutenant Axtroz muss vernichtet werden. Bringt mir Axtroz' Schädel. Für den Vater, Welpe!", progress = "Veränderungen... Ich spüre sie schon in Euch, Welpe. Besteht diese Prüfung, dann wartet nur noch eine Zeremonie auf Euch.", completion = "Ich habe mich in Eurem Engagement getäuscht, Welpe. Ihr wart beharrlich, habt unsere Feinde bezwungen und unserem Klan Ehre gemacht.\n\nJetzt muss ich die Schädel für Euren Aufstieg vorbereiten.", rewards = "Ihr bekommt:\n\n"},
[6601] = {title = "Aufstieg...", objective = "Mir scheint, als sei die Charade jetzt vorüber. Ihr wisst, dass das Amulett der drachischen Unterwanderung, das Myranda die Vettel für Euch erschuf, auf der Blackrockspitze nicht funktioniert. Vielleicht solltet Ihr Rexxar aufsuchen und ihm Eure Notlage erklären. Zeigt ihm das glanzlose Drachenfeueramulett. Er wird hoffentlich wissen, was als Nächstes zu tun ist.", description = "Ein Medaillon, aus den Schädeln Eurer Feinde gefertigt. Ihr kennt dieses Medaillon, nicht wahr? Zweifellos habt Ihr gesehen, wie Eure Ältesten es trugen.\n\nNehmt es, Welpe. Begebt Euch zur Spitze zurück und zeigt es General Drakkisath. Der General wird das Medaillon mit der letzten Verzauberung versehen und das Schmuckstück auf Euren Geist abstimmen.\n\nIhr werdet das fertige Medaillon als Ehrenabzeichen tragen, als Symbol für Euren Aufstieg in unsere am höchsten geschätzten Reihen: Wächter der Brutmutter.\n\nGeht!", progress = "Keine Panik, <Name>!", completion = "Das ist reines Drachengeschwätz, &lt;Name&gt; - viel heiße Luft und keine greifbaren Informationen. Was soll man von ihnen auch anderes erwarten als aufgeblasenes, aggressives Verhalten.", rewards = "Ihr bekommt:\n\n"},
[6602] = {title = "Blut des schwarzen Großdrachen-Helden", objective = "Begebt Euch zur Blackrockspitze und tötet General Drakkisath. Sammelt sein Blut und bringt es zu Rexxar.", description = "Ihr werdet dem General einen Besuch abstatten, jawohl, aber nicht als einer des schwarzen Drachenschwarms.\n\nWisst Ihr, Zeremonie ist für den schwarzen Drachenschwarm nur ein anderer Begriff für Aderlass.\n\nDas ruhende Amulett benötigt nur das Blut des Generals, um wieder aktiv zu sein. Das ist einer ihrer primitiven, ausfallsicheren Mechanismen.\n\nKehrt zur Blackrockspitze zurück und vernichtet Drakkisath. Bringt sein Blut hierher zurück, dann aktiviere ich den Schlüssel zu Onyxias Hort.", progress = "Man darf Drakkisath nicht unterschätzen, <Name>. Er hat den Tod von Tausenden auf dem Gewissen.", completion = "&lt;Rexxar grinst.&gt;\n\nDie Geschichte Eurer Heldentaten wird man sich noch jahrelang erzählen, &lt;Name&gt;. Das Drachenfeueramulett ist der Schlüssel zu Onyxias Hort. Sammelt Eure Streitmacht und erobert ihn im Namen der Horde!", rewards = "Ihr bekommt:\n\nDrachenfeueramulett"},
[6603] = {title = "Probleme in Winterspring", objective = "Findet Donova Snowden bei den Thermalquellen in Winterspring.", description = "In Winterspring gibt es Probleme!\n\nSicher, ich habe einige Zeit da draußen in der Wildnis zugebracht und weiß um diese Dinge... Es macht mich immer ganz stolz, das zu sagen. Für mich waren die Stunden, die ich dort draußen in den Hügeln verbrachte, etwas ganz Besonderes. Es hilft einem, blitzschnelle Reflexe zu entwickeln, einen kühlen Kopf und ein wachsames Auge zu bewahren...\n\nMan braucht Urteilsvermögen, Grips und Reife, um die Wildnis so schätzen zu können, wie ich es tue.\n\nAlso, worüber wollte ich eigentlich sprechen?\n\nAch ja, Probleme. Sprecht mit Donova Snowden bei den Thermalquellen. Sie wird Euch mehr sagen können.", progress = nil, completion = "Hallo, Ihr da! Meggi hat Euch also schon von den Problemen erzählt, auf die ich hier gestoßen bin?", rewards = "Ihr bekommt:\n\n"},
[6604] = {title = "Wütende Wildekin", objective = "Sprecht mit Jaron Stoneshaper in Starfall.", description = "Ist Euch das verlassene Lager südlich von hier aufgefallen? Es scheint, als wären die Wildekin verrückt geworden und haben so gut wie alles zerstört, was sie finden konnten!\n\nIch hab Gerüchte gehört, wonach einer der Überlebenden des Angriffs sich in Starfall aufhalten soll, das liegt westlich von hier. Ich bin neugierig, was wohl geschehen sein mag ... Ihr nicht auch?", progress = nil, completion = "Aye, was kann ich für Euch tun?", rewards = "Ihr bekommt:\n\n"},
[6605] = {title = "Eine seltsame Person", objective = "Sprecht im Teufelswald mit Winna Hazzard.", description = "Ich bin gerade erst vom Teufelswald zurückgekehrt, <Name>. Unterwegs habe ich im Blutgiftposten Halt gemacht und eine wirklich eigenartige Bekanntschaft gemacht... Sie schien ganz besessen von einer Sache gewesen zu sein, und ich könnte Euch wohl erzählen, um was es sich handelt, aber ich denke, das sollte sie Euch selbst erklären.\n\nGeht zum Blutgiftposten im Westen des Teufelswalds und fragt nach Winna Hazzard, falls Ihr Interesse habt.\n\nWer weiß, vielleicht braucht sie ja Eure Hilfe...", progress = nil, completion = "Ah, &lt;Klasse&gt;. Also gibt es wohl doch noch Hoffnung. Seid Ihr hier, um mir zu helfen?", rewards = "Ihr bekommt:\n\n"},
[6606] = {title = "Ein bisschen Glück", objective = "Sprecht in Everlook mit Hexendoktorin Mau'ari.Ein bisschen Glück kann man immer gebrauchen, nicht wahr? Ein kleiner Vorteil ist alles, was man braucht, um eine günstige Wendung herbeizuführen...\n\nIch habe vor einiger Zeit eine ziemlich exzentrische Hexendoktorin kennen gelernt. Sie fertigte einen Glücksbringer für mich... nicht gerade billig. Aber ich sage Euch, er war es auch wert!\n\nMöchtet Ihr vielleicht selbst gern einen haben? Sucht Hexendoktorin Mau'ari in Everlook auf. Meinen bekommt Ihr nämlich nicht!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ein bisschen Glück kann man immer gebrauchen, nicht wahr? Ein kleiner Vorteil ist alles, was man braucht, um eine günstige Wendung herbeizuführen...\n\nIch habe vor einiger Zeit eine ziemlich exzentrische Hexendoktorin kennen gelernt. Sie fertigte einen Glücksbringer für mich... nicht gerade billig. Aber ich sage Euch, er war es auch wert!\n\nMöchtet Ihr vielleicht selbst gern einen haben? Sucht Hexendoktorin Mau'ari in Everlook auf. Meinen bekommt Ihr nämlich nicht!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[6607] = {title = "Nat Pagle, Extremangler", objective = "Nat Pagle möchte, dass Ihr folgende Fische fangt:\n\nNebelschilf-Mahi Mahi vom Nebelschilfstrand in den Sümpfen des Elends.\n\nEinen Sar'theris-Barsch vom Sar'theris-Strand in Desolace.\n\nFeralas-Ahi aus dem Verdantis in Feralas.\n\nBlauwimpel von der ungezähmten Küste im Schlingendorntal.\n\nKehrt zu Nat Pagle zurück, wenn Ihr alle an Land gezogen habt!", description = "Ich kann nicht behaupten, dass ich gern angele. Ich glaub, ich mach das jetzt seit gut 20 oder 30 Jahren.\n\nEs gibt wohl viele Gründe, die einen dazu treiben, etwas zu tun.\n\nIch will damit jetzt nicht sagen, dass Ihr 30 Jahre lang angeln oder jeden einzelnen Fisch im Meer fangen müsst, um ein Meisterangler zu werden. Man muss einfach nur entschlossen sein - entschlossen genug, um stundenlang auf dem Hintern zu sitzen und nichts zu tun.\n\nIch sag Euch was: Fangt mir ein paar seltene Fische, dann bring ich Euch das eine oder andere bei. Hier habt Ihr eine Liste:", progress = "Na, hat heute schon einer angebissen?", completion = "Also das nenn ich einen tollen Fang!\n\nKommt hier rüber, dann zeig ich Euch, wie man die Leinen auswirft.", rewards = "Ihr erlernt:\n\nAngeln\n\nDer folgende Zauber wird auf euch gewirkt:\n\nFachmännisches Angeln\n\nIhr bekommt außerdem:\n\n"},
[6608] = {title = "Ihr zu gut", objective = "Ihr nehmt an, dass Lumak Euch zu erklären versucht, dass er nicht mehr tun kann, um Eure Angelfertigkeit zu verbessern. Ihr solltet seinen Freund aufsuchen, diesen Nat Pagle, einen Menschen, der auf einer der Inseln südlich von Theramore (jedenfalls glaubt Ihr, dass Lumak das gemeint hat) auf Fischfang geht.", description = "Lumak können <Name> nix mehr beibringen. Ihr zu gut! Finden Freund von Lumak, Nat Pagle. Er sein Mensch, aber nix Futter! Ist Freund von Lumak! Nat Euch zeigen, wie besserer angeln.\n\nIhr finden Nat in Marschen von Dustwallow, Süden von Thermoro-odersoähnlich. Nat bestimmt angeln. Ihr jetzt gehen!", progress = nil, completion = "Klar, Ihr müsst ein Freund von Lumak sein.\n\nAngeln? Ich kann Euch alles übers Angeln erzählen.", rewards = "Ihr bekommt:\n\n"},
[6609] = {title = "Ich hab nix mehr!", objective = "Reist nach Kalimdor zur Küstenstadt Theramore. Dort müsst Ihr nach einer Insel suchen, die südlich der Hauptstadt liegt. Nat Pagle erwartet Euch!", description = "Ich bin ein Zwerg, zum Donnerwetter nochmal, <Jungchen/junge Dame>! Ich hab mit Angeln nichts am Hut! Ich meine, seht mich doch mal an! Ich bestehe doch praktisch ganz aus Stein.\n\nIch hab nichts mehr - Ihr habt mich ausgelaugt. Ich hab Euch alles beigebracht, was ich weiß, flipflop!\n\nKapiert Ihr's nicht? Ah, gut. Ich hab in Kalimdor einen alten Freund, der Euch weiterhelfen kann. Heißt Nat Pagle, guter Junge. Findet ihn auf den Inseln südlich von Theramore. Jetzt verfatzt Euch!", progress = nil, completion = "Ich hab auf meiner Insel immer Platz für Besucher... Würde ich sagen...", rewards = "Ihr bekommt:\n\n"},
[6610] = {title = "Muschelette Surprise", objective = "Dirge Quikcleave möchte, dass Ihr folgende Dinge besorgt:\n\n12 Rieseneier. Ihr findet sie bei den Rocs, die Tanaris durchstreifen, oder anderen Großvogelarten.\n\n10 Stück scharfes Muschelfleisch. Die findet Ihr natürlich in Muscheln!\n\n20 Stück Alteraclochkäse. Begebt Euch zu einer Käserei!\n\nSammelt all diese Gegenstände und kehrt dann zu Dirge zurück.", description = "Schon mal von einem Muschelette gehört? Natürlich nicht! Das ist mein neuestes kulinarisches Meisterwerk. Oh, <Name>, mir läuft das Wasser im Mund zusammen, wenn ich nur an ein Muschelette denke.\n\nLeider habe ich nichts mehr hier, um eins zu machen! Wie wär's mit einem Handel? Ihr besorgt die Zutaten für ein Muschelette und ich bring Euch die Feinheiten der exotischen Küche bei und leg' sogar noch ein paar Muschelettes drauf! Abgemacht?\n\nUnd das brauche ich dafür:", progress = "Meine Gelüste bringen mich noch mal um! Schnell, <Name>, bevor ich den Kitt aus den Fenstern futtere.", completion = "Freut Euch auf ein ganz besonderes Vergnügen, &lt;Name&gt;. Seht zu und lernt!", rewards = "Ihr erlernt:\n\nKochkunst\n\nDer folgende Zauber wird auf euch gewirkt:\n\nKochfachmann\n\nIhr bekommt außerdem:\n\nMuschelette Surprise"},
[6611] = {title = "Ab mit Euch nach Gadgetzan!", objective = "Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Quikcleave über den Ausbau Eurer Kochkarriere.", description = "Erwartet Ihr etwa, dass Zamja Euch noch irgendwas beibringt? Ihr kennt schon alle von Zamjas Küchentricks und verlangt immer noch nach mehr!\n\nZamja kann nicht helfen. Fetter <Volk> muss nach Gadgetzan gehen. Dort findet Ihr einen kleinen Goblin namens Dirge - er wird Euch helfen, Dickerchen.\n\nWenn Ihr dann ein richtiger Sternekoch seid, kommt Ihr zurück und gebt Zamja Unterricht, okay? Und jetzt geht!", progress = nil, completion = "&lt;Dirge spuckt ein paar Fetzen der Ledersandale aus.&gt;\n\nPfui...\n\n&lt;Dirge hustet laut.&gt;\n\nWas? Ihr müsst wissen, dass Leder erstaunlich reich an Proteinen und arm an Kohlehydraten ist.", rewards = "Ihr bekommt:\n\n"},
[6612] = {title = "Ich kenne einen Typen...", objective = "Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Quikcleave über den Ausbau Eurer Kochkarriere.", description = "Das seh ich doch an Eurem Kochlöffel, dass Ihr wisst, was Ihr tut. Leider kann ich Euch nichts beibringen.\n\nGlück für Euch, ich kenn da einen Typen. Er ist ein Goblin und wahrscheinlich der beste Koch von ganz Kalimdor.\n\nHajo, und jetzt die schlechte Nachricht, <Jungchen/Mädel> - Ihr müsst nach Kalimdor reisen. Geht nach Gadgetzan und sucht nach Dirge Quikcleave. Er wird's Euch beibiegen.", progress = nil, completion = "&lt;Dirge spuckt Leder aus.&gt;\n\nPfft...\n\n&lt;Dirge hustet laut.&gt;\n\nWas? Ihr müsst wissen, dass Leder erstaunlich reich an Proteinen und arm an Kohlehydraten ist, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"},
[6621] = {title = "König der Fäulnisklauen", objective = "Platziert Karangs Banner auf dem Totemhügel der Fäulnisklauen. Die Furbolgs dürfen das Banner nicht zerstören. Besiegt Häuptling Murgut und bringt Murguts Totem zu Karang Amakkar in Zoram'gar.", description = "<Name>, südöstlich von Astranaar lebt noch ein anderer Stamm Furbolgs, die Fäulnisklauen. Es gibt zwar nicht so viele von ihnen wie das bei den Distelfellen der Fall ist, aber ihre Wildheit könnte sich in der Zukunft zu einem Problem auswachsen. Wir könnten diese Bedrohung durch eine Demonstration der Macht beseitigen.\n\nNehmt dieses Banner, geht ins Dorf der Fäulnisklauen und platziert es auf ihrem Totemhügel. Sie werden versuchen, das Banner zu zerstören, aber Ihr müsst Eure Stellung halten, bis ihr Häuptling Murgut auftaucht, um das Gesicht seines Stammes zu wahren. Bringt mir das Totem, das er trägt.\n\nVersammelt Eure Verbündeten, <Name>. Dies ist keine Aufgabe für einen einzelnen <Klasse>.", progress = "Habt Ihr Häuptling Murgut besiegt, <Name>? Habt Ihr das Fäulnisklauentotem?", completion = "Gute Arbeit, &lt;Name&gt;. Indem wir die Fäulnisklauen herausgefordert und ihren Anführer besiegt haben, haben wir ihnen eine nachdrückliche Warnung erteilt:\n\nMan darf die Horde nicht unterschätzen.\n\nIch glaube, dass uns dieser Stamm für lange Zeit keine Scherereien mehr machen wird.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLandgardentunikaKobaltblaue Beinschützer\n\nIhr bekommt außerdem:\n\n"},
[6622] = {title = "Triage", objective = "Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen.\n\nDenkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt.", description = "Guten Tag, Doktor. Heute Nachmittag werden wir Eure Fähigkeit auf die Probe stellen, Patienten auszuwählen. Solltet Ihr das Examen bestehen, gehört Ihr zu den angesehenen Traumachirurgen der Horde.\n\nUnd jetzt passt gut auf! Die Schwerstverletzten müssen zuerst versorgt werden. Nach den Schwerstverletzten kommen die Schwerverletzten. Die einfach Verletzten kommen zuletzt an die Reihe. Ihr müsst 15 Patienten retten, um dieses Examen zu bestehen. Ihr fallt durch, wenn 6 Eurer Patienten durch Eure falsche Wahl sterben.\n\nVerbände werden gestellt.\n\nViel Glück, Doktor.", progress = nil, completion = "Doktor &lt;Name&gt;, willkommen bei den Traumachirurgen der Horde.", rewards = "Ihr erlernt:\n\nErste Hilfe\n\nDer folgende Zauber wird auf euch gewirkt:\n\nFachmann für Erste Hilfe\n\nIhr bekommt außerdem:\n\n"},
[6623] = {title = "Traumachirurg der Horde", objective = "Reist nach Hammerfall im Arathihochland und sprecht mit Doktor Gregory Victor darüber, dass Ihr auch ein Traumachirurg der Horde werden wollt.", description = "Doktor <Name>, nehme ich an. Es ist mir eine Freude, Euch wiederzusehen.\n\nIch habe wunderbare Neuigkeiten für Euch! Doktor Gregory Victor, Chefarzt der Traumachirurgen der Horde, hat Euch persönlich angefordert, damit Ihr Euch ihm in Hammerfall anschließt. Das könnte eine einmalige Gelegenheit sein! Ich würde alles darum geben, bei dem großen Doktor Gregory Victor studieren zu dürfen! Diese Gelegenheit dürft Ihr Euch nicht entgehen lassen!", progress = nil, completion = "Großartig. Zieht Eure Operationskluft an, dann werden wir sogleich beginnen!", rewards = "Ihr bekommt:\n\n"},
[6624] = {title = "Triage", objective = "Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen.\n\nDenkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt.", description = "Guten Tag, Doktor. Heute Nachmittag werden wir Eure Fähigkeit auf die Probe stellen, Patienten auszuwählen. Solltet Ihr das Examen bestehen, gehört Ihr zu den angesehenen Traumachirurgen der Allianz.\n\nUnd jetzt passt gut auf! Die Schwerstverletzten müssen zuerst versorgt werden. Nach den Schwerstverletzten kommen die Schwerverletzten. Die einfach Verletzten kommen zuletzt an die Reihe. Ihr müsst 15 Patienten retten, um dieses Examen zu bestehen. Ihr fallt durch, wenn 6 Eurer Patienten durch Eure falsche Wahl sterben.\n\nViel Glück, Doktor.", progress = nil, completion = "Doktor &lt;Name&gt;, willkommen bei den Traumachirurgen der Allianz.", rewards = "Ihr erlernt:\n\nErste Hilfe\n\nDer folgende Zauber wird auf euch gewirkt:\n\nFachmann für Erste Hilfe\n\nIhr bekommt außerdem:\n\n"},
[6625] = {title = "Traumachirurg der Allianz", objective = "Reist nach Theramore in den Marschen von Dustwallow und sprecht mit Doktor Gustaf van Howzen darüber, dass Ihr auch ein Traumachirurg der Allianz werden wollt.", description = "Doktor <Name>, nehme ich an. Es ist mir eine Freude, Euch zu sehen.\n\nIch habe wunderbare Neuigkeiten für Euch! Gustaf van Howzen, Chefarzt der Traumachirurgen der Allianz, hat Euch persönlich angefordert, damit Ihr Euch ihm in Theramore anschließt. Das könnte eine einmalige Gelegenheit sein! Ich würde alles darum geben, bei dem großen Doktor Gustav van Howzen studieren zu dürfen! Diese Gelegenheit dürft Ihr Euch nicht entgehen lassen, Doktor!", progress = nil, completion = "Großartig. Zieht Eure Operationskluft an, dann werden wir sogleich beginnen!", rewards = "Ihr bekommt:\n\n"},
[6626] = {title = "Ein Hort des Bösen", objective = "Tötet 8 Schlachtwachen von Razorfen, 8 Dornenwirker von Razorfen und 8 Kultistinnen der Totenköpfe und kehrt dann zu Myriam Moonsinger nahe dem Eingang zu den Hügeln von Razorfen zurück.", description = "Die Verlassenen geben ihre... Krankheit... nicht weiter, soweit ich das sehe. Dieser Diplomat scheint Untote als Möchtegernanhänger zu betrachten. Ich glaube langsam, dass er der Geißel angehört.\n\nUm ihn mache ich mir allerdings momentan keine Gedanken, sondern um die wachsende Schar um ihn herum. Tag für Tag kriechen sie aus den Schatten und betteln ihn nahezu um mehr Macht an.\n\nIch bin nicht stark genug, um sie allein zu bekämpfen, <Name>. Was meint Ihr? Hättet Ihr Lust, auf die Jagd zu gehen?", progress = "Wie läuft die Jagd, <Name>? Wenn ich nur dieses kleine Beispiel der Macht dieses Diplomaten hier sehe, zweifle ich nicht mehr daran, dass die Geißel eine der größten Bedrohungen ist, die die Welt je gesehen hat.", completion = "Danke, &lt;Name&gt;! Die Arbeit, die Ihr geleistet habt, wird eine große Hilfe sein, da bin ich mir sicher.\n\nIch werde meine Studien über diesen Diplomaten und den Rest der Stacheleber hier fortsetzen. Wenn Ihr auf größere Abenteuer aus seid, würde ich ein paar Freunde zusammentrommeln und in die Höhle da drüben gehen, die wie ein riesiges Ebermaul aussieht. Ich bin sicher, dass Ihr dort drinnen noch auf viel größere Herausforderungen stoßen werdet.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6627] = {title = "Test der Lehre", objective = "Beantwortet Braug Dimspirits Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch im Steinkrallengebirge sein, wenn Ihr bereit seid.", description = "Ihr habt mir das Buch gebracht, und jetzt ist es an der Zeit für Eure Befragung. Seid Ihr bereit?\n\nZeit spielt keine Rolle, <Klasse>, also fühlt Euch nicht unter Druck gesetzt. Ihr könnt Euch mit der Antwort so viel Zeit lassen, wie Ihr möchtet.", progress = "Das Leben ist voller Fragen, <Klasse>. Ihr werdet sie niemals alle beantworten können, aber mit der Zeit und durch Studien werdet Ihr Euch bestimmt weiteres Wissen aneignen.", completion = "Gut gemacht, &lt;Klasse&gt;. Ihr habt den Text studiert, wie ich Euch gebeten habe, und jetzt habt Ihr eine weitere unserer Prüfungen bestanden.", rewards = "Ihr bekommt:\n\n"},
[6628] = {title = "Test der Lehre", objective = "Beantwortet Parqual Fintallas' Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch in Undercity sein, wenn Ihr bereit seid.", description = "Die Zeit ist also wieder einmal gegen uns. Für einen Studenten der Lehre habt Ihr große Hartnäckigkeit bewiesen, indem Ihr meine Aufgabe erledigt habt.\n\nUnd deshalb werde ich Euch eine Frage anbieten. Wenn Ihr bereit seid, sprecht mich wieder an, und lasst Euch so viel Zeit, wie Ihr braucht, <Name> - es besteht keine Notwendigkeit, schnell zu antworten.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ich hatte meine Zweifel, ob Ihr den Text studieren würdet, den ich Euch gebeten habe zu holen, aber Ihr habt richtig geantwortet.", rewards = "Ihr bekommt:\n\n"},
[6629] = {title = "Tötet Grundig Finsterwolke", objective = "Tötet Grundig Finsterwolke und 6 Schläger der Grimmtotem und kehrt dann zu Makaba Flathoof am südöstlichen Rand des Steinkrallengebirges zurück.", description = "<Name>, Ihr habt gute Arbeit geleistet, indem Ihr Grimmtotem tötetet. Grundig Finsterwolke und seine persönliche Schlägerbande sind bei weitem die Schlimmsten von allen, wenn Ihr Euch traut. Er war einer derjenigen, die den brutalen Angriff auf mein Dorf anführten.\n\nIhr findet ihn im Grimmtotemposten ein Stück weiter den Weg nach Westen hinauf. Tötet ihn, dann werde ich Euch immer dankbar sein.", progress = "Habt Ihr Grundig Finsterwolke und seine persönliche Schlägerbande getötet?", completion = "Grundig Finsterwolke ist tot! &lt;Name&gt;, ich werde immer für das dankbar sein, was Ihr heute hier geleistet habt.", rewards = "Ihr bekommt:\n\n"},
[6641] = {title = "Vorsha die Peitscherin", objective = "Beschützt Muglash, wenn er zu der Kohlenpfanne reist. Helft ihm, indem Ihr die Kohlenpfanne löscht, und beschützt ihn dann, während Ihr gegen die Naga kämpft.\n\nWenn Ihr erfolgreich gewesen seid, kehrt zum Zoram'garposten zurück und informiert den Warsongläufer über den Tod von Vorsha der Peitscherin.", description = "Vorsha die Peitscherin... die satanische Hydra, die die Meere durchstreift...\n\nSie hat unseren Außenposten angegriffen, völlig ohne Grund, und dabei alles verheert, was auf ihrem Weg lag.\n\nAber ich bin bereit, <Name>. Ich bin bereit, die Hydra zu besiegen und den Angriffen auf Zoram'gar ein Ende zu setzen.\n\nDie Naga verehren die tückische Natur dieser Bestie mit einer Kohlenpfanne, die auf einer Insel gleich vor der Küste immer am Brennen gehalten wird. Ich denke, dass Vorsha erzürnt auftauchen wird, wenn wir sie löschen.\n\nWir werden jedoch Hilfe brauchen, also solltet Ihr ein paar starke Verbündete mitbringen.", progress = nil, completion = "Ich habe schon viele Nagaangriffe miterlebt, seit ich hier bin. Es beruhigt mich, dass Vorsha nicht mehr ihr Unwesen treibt.\n\nWir stehen in Eurer Schuld, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nHornring"},
[6642] = {title = "Gunst der Bruderschaft, Dunkeleisenerz", objective = "Dunkeleisen, das in der Tiefe zwar reichlich vorkommt, ist innerhalb der Bruderschaft dennoch ein hoch geschätztes Gut. Für die hochheiligen Waffen und Ausrüstungen von Ragnaros wird bevorzugt Dunkeleisen verwendet.\n\nFür 10 Stück Dunkeleisenerz, die Ihr anbietet, steigt Ihr in der Gunst der Bruderschaft.", description = nil, progress = "Dunkeleisen, das in der Tiefe zwar reichlich vorkommt, ist innerhalb der Bruderschaft dennoch ein hoch geschätztes Gut. Für die hochheiligen Waffen und Ausrüstungen von Ragnaros wird bevorzugt Dunkeleisen verwendet.\n\nFür 10 Stück Dunkeleisenerz, die Ihr anbietet, steigt Ihr in der Gunst der Bruderschaft.", completion = "Eure Gabe wurde angenommen. Ihr seid in der Gunst gestiegen. Macht so weiter, dann dürft Ihr Euch bald mit den uralten Handwerken beschäftigen.", rewards = nil},
[6643] = {title = "Gunst der Bruderschaft, Feuerkern", objective = "Wehe denen, die im geschmolzenen Kern das Schicksal herausfordern. Der Tod kommt schnell - die Strafe erfolgt ohne Gnade.\n\nViele Anhänger der Bruderschaft sind auf der Suche nach Feuerkernen gefallen.\n\nBietet einen Feuerkern an, dann steigt Ihr in der Gunst der Bruderschaft.", description = nil, progress = "Wehe denen, die im geschmolzenen Kern das Schicksal herausfordern. Der Tod kommt schnell - die Strafe erfolgt ohne Gnade.\n\nViele Anhänger der Bruderschaft sind auf der Suche nach Feuerkernen gefallen.\n\nBietet einen Feuerkern an, dann steigt Ihr in der Gunst der Bruderschaft.", completion = "Eure Gabe wurde angenommen. Ihr seid in der Gunst gestiegen. Macht so weiter, dann dürft Ihr Euch bald mit den uralten Handwerken beschäftigen.", rewards = nil},
[6644] = {title = "Gunst der Bruderschaft, Lavakern", objective = "Die Thoriumbruderschaft versteht Eure Notlage, <Volk>. Deshalb haben wir Lokthos zu einem Handel ermächtigt.\n\nBietet 4 Lavakerne an, dann steigt Ihr in der Gunst der Bruderschaft.", description = nil, progress = "Die Thoriumbruderschaft versteht Eure Notlage, <Volk>. Deshalb haben wir Lokthos zu einem Handel ermächtigt.\n\nBietet 4 Lavakerne an, dann steigt Ihr in der Gunst der Bruderschaft.", completion = "Eure Gabe wurde angenommen. Ihr seid in der Gunst gestiegen. Macht so weiter, dann dürft Ihr Euch bald mit den uralten Handwerken beschäftigen.", rewards = nil},
[6645] = {title = "Gunst der Bruderschaft, Kernhäute", objective = "Für viele der hochheiligen Rezepte ist die Haut von Ragnaros' Lieblingstieren erforderlich.\n\nBietet 4 Kernhäute an, die Ihr den glimmenden Kadavern der Kernhunde des geschmolzenen Kerns abgezogen habt, dann steigt Ihr in der Gunst der Bruderschaft.", description = nil, progress = "Für viele der hochheiligen Rezepte ist die Haut von Ragnaros' Lieblingstieren erforderlich.\n\nBietet 4 Kernhäute an, die Ihr den glimmenden Kadavern der Kernhunde des geschmolzenen Kerns abgezogen habt, dann steigt Ihr in der Gunst der Bruderschaft.", completion = "Eure Gabe wurde angenommen. Ihr seid in der Gunst gestiegen. Macht so weiter, dann dürft Ihr Euch bald mit den uralten Handwerken beschäftigen.", rewards = nil},
[6646] = {title = "Gunst der Bruderschaft, Blut des Berges", objective = "Die Tränen des Feuerlords sind wahrlich ein seltener Fund.\n\nBietet 1 Blut des Berges an, dann steigt Ihr in der Gunst der Bruderschaft.", description = nil, progress = "Die Tränen des Feuerlords sind wahrlich ein seltener Fund.\n\nBietet 1 Blut des Berges an, dann steigt Ihr in der Gunst der Bruderschaft.", completion = "Eure Gabe wurde angenommen. Ihr seid in der Gunst gestiegen. Macht so weiter, dann dürft Ihr Euch bald mit den uralten Handwerken beschäftigen.", rewards = nil},
[6661] = {title = "Tiefenbahn-Ratten-Razzia", objective = "Fangt mit Hilfe der Rattenfängerflöte 5 Untergrundratten in der Tiefenbahn. Führt die Ratten zu Monty. Und vergesst nicht, die Flöte zurückzugeben, wenn Ihr fertig seid.", description = "Haltet ein, Taugenichts. Arrrr... Sucht Ihr Arbeit? Wir ha'm hier ein echtes Rattenproblem und nicht genügend Leute auf dem Hüttendeck.\n\nWas sagt Ihr? Ihr müsst nur diese Rattenfängerflöte nehmen und dem Ungeziefer ein Liedchen vorspielen. Die folgen Euch dann bis ans Ende der Welt!\n\nFangt mir fünf von den kleinen Mistviechern und bringt sie mir. Ich brauch sie lebendig.\n\nArrrrr...", progress = "Harrr... Deckschrubber, was dauert das so lange?", completion = "Die sind ausgezeichnet, Kumpel. Mein Bruder braucht sie quietschlebendig und zappelig, sonst verderben sie... Ihr wollt doch wohl keinen verdorbenen Rattenkebab probieren, was?", rewards = "Ihr bekommt:\n\n"},
[6662] = {title = "Mein Bruder Nipsy...", objective = "Bringt den Karton mit eigenartigem Fleisch zu Nipsy im Tiefenbahndepot von Stormwind.", description = "Mein Bruder Nipsy hat 'n Rattengeschäft auf der anderen Seite der Tiefenbahn. Ihr müsst die Kiste mit Ratten hier zu ihm bringen, bevor sie schlecht werden. Zackig!\n\nIhr seid doch wohl schon mal mit 'ner Bahn gefahren, oder? Ganz einfach. Steigt einfach ein, wenn sie kommt, und genießt die Fahrt. Und haltet Eure Arme und Beine während der Fahrt drinnen, wenn Ihr keine Holzgräten haben wollt.", progress = "<Nipsy steckt seinen Zeigefinger in eines der Luftlöcher des Kartons.>\n\nQuietschlebendig und zappelig... und genau zur richtigen Zeit!", completion = "Armer Monty. Seit dem Gnomeregan-Vorfall ist er ein anderer Mensch. Der Junge hat in seinem ganzen Leben noch kein Meer gesehen, ganz zu schweigen von irgendwelchen Piraten.\n\n&lt;Nipsy seufzt.&gt;\n\nZumindest sorgt er dafür, dass es immer Nachschub an quirligen Viechern gibt.", rewards = "Ihr bekommt:\n\nUntergrundratten-Kebab"},
[6681] = {title = "Das Anwesen, Ravenholdt", objective = "Bringt das Ravenholdt-Siegel zu Fahrad im Ravenholdt-Anwesen, das versteckt in den Hügeln von Hillsbrad liegt.\n\nUnterwegs wird man Eure Schlauheit testen. Seid darauf gefasst.", description = "<Name>,\n\nRavenholdt interessiert sich für Euch, junger Dieb. Wir haben Euch beobachtet. Euer Stil ist ein bisschen unbeholfen, aber daran können wir arbeiten.\n\nWenn Ihr bereit seid, eine Karriere als Schüler von Meister Ravenholdt in Angriff zu nehmen und Mitglied der Auftragsmörderliga zu werden, müsst Ihr nur das Ravenholdt-Siegel (diesem Brief beigefügt) zum Ravenholdt-Anwesen bringen.\n\nEure erste Aufgabe ist es, das Anwesen zu finden, das versteckt in den Hügeln von Hillsbrad liegt, um Eure Schlauheit zu demonstrieren.\n\nHochachtungsvoll,\n\nFahrad", progress = "Habt Ihr Milton getroffen?\n\n<Fahrad lacht.>", completion = "Äußerst exzellent, junger Dieb.\n\nIhr seht etwas mitgenommen aus, aber das wird schon wieder.\n\nEine lange Reise erwartet Euch - lang und profitabel. Seid Ihr bereit, Euer Schicksal unter den Meistern von Ravenholdt zu schmieden?\n\nSprecht mit den Wachen da draußen. Sie werden Euch einweisen.", rewards = "Ihr bekommt:\n\n"},
[6701] = {title = "Syndikatsembleme", objective = "Wir liegen schon seit Jahren mit dem Syndikat im Clinch. Was denen an Fertigkeit mangelt, machen sie durch ihre große Zahl wett. Es ist unmöglich, sie schnell genug zu töten, um auch nur den geringsten Rückgang ihrer Population feststellen zu können!\n\nWir haben herausgefunden, dass die beste Möglichkeit, ihrer großen Zahl Herr zu werden, darin besteht, ihnen die Embleme zu stehlen. Hat man einem das Emblem gestohlen, 'kümmern' sie sich intern um das mit Schande bedeckte Mitglied.\n\nRaubt Ihnen die Taschen aus und bringt die Embleme mir oder einer der anderen Wachen.\n\nBeginnt in Durnholde südlich von hier.", description = nil, progress = "Wir liegen schon seit Jahren mit dem Syndikat im Clinch. Was denen an Fertigkeit mangelt, machen sie durch ihre große Zahl wett. Es ist unmöglich, sie schnell genug zu töten, um auch nur den geringsten Rückgang ihrer Population feststellen zu können!\n\nWir haben herausgefunden, dass die beste Möglichkeit, ihrer großen Zahl Herr zu werden, darin besteht, ihnen die Embleme zu stehlen. Hat man einem das Emblem gestohlen, 'kümmern' sie sich intern um das mit Schande bedeckte Mitglied.\n\nRaubt Ihnen die Taschen aus und bringt die Embleme mir oder einer der anderen Wachen.\n\nBeginnt in Durnholde südlich von hier.", completion = "He, gute Arbeit! Macht so weiter, dann hören die anderen Schurken vielleicht auf, Euch zu bespucken.", rewards = nil},
[6721] = {title = "Der Weg des Jägers", objective = "Sprecht mit Dazalar in Dolanaar.", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[6722] = {title = "Der Weg des Jägers", objective = "Sprecht mit Dazalar in Dolanaar.", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[6741] = {title = "Mehr Beute!", objective = "Wenn Ihr gegen den Feind kämpft, sammelt die Stücke seiner Rüstung und bringt sie mir. Ich werde diese Stücke nutzen, um Rüstungen für unsere eigenen Truppen herzustellen!", description = nil, progress = "Wenn Ihr gegen den Feind kämpft, sammelt die Stücke seiner Rüstung und bringt sie mir. Ich werde diese Stücke nutzen, um Rüstungen für unsere eigenen Truppen herzustellen!", completion = "Und wieder muss ich euch danken, &lt;Name&gt;.  Ihr macht der Horde alle Ehre...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPolierte Rüstung"},
[6761] = {title = "Die neue Grenze", objective = "Sprecht mit Mathrengyl Bearwalker in der Enklave des Cenarius von Darnassus.", description = "Ich habe meinen Stellvertreter Mathrengyl Bearwalker beauftragt, sich um Moonglades Bitte um Unterstützung zu kümmern. Sprecht mit ihm über diese Angelegenheit - NICHT mit mir.\n\nLasst mich Euch einen... gut gemeinten... Rat geben. ICH habe uns aus der Dunkelheit geführt - NICHT der Zirkel des Cenarius in Moonglade -, als für unser Volk alles verloren war. Teldrassil gibt uns allen neues Leben! Sie wollen Euch anderes glauben machen, und ihre Propaganda zu glauben, wäre reine Blauäugigkeit.\n\nIch werde es Euch überlassen, ob Ihr ein Narr sein wollt oder nicht.", progress = nil, completion = "Vielen Dank, dass Ihr gekommen seid, &lt;Klasse&gt;. Ich entschuldige mich für das Missverständnis... es gibt viel Misstrauen zwischen dem Erzdruiden hier und dem Bewahrer Remulos in Moonglade. Jeder verdächtigt den anderen der Schikane und die Tatsache, dass die merkwürdige Verderbnis von Teldrassil auch weiterhin nicht nachlässt, ist hier immer noch ein Thema. Das trägt wenig dazu bei, das Misstrauen zu lindern.\n\nTrotzdem bleibt unsere Pflicht gegenüber dem Zirkel des Cenarius bestehen... auch wenn diejenigen, die ihn leiten, untereinander uneins sind.", rewards = "Ihr bekommt:\n\n"},
[6762] = {title = "Rabine Saturna", objective = "Sprecht mit Rabine Saturna im Dorf Nighthaven in Moonglade. Moonglade liegt zwischen dem Teufelswald und Winterspring, und Ihr erreicht es über den Pfad, der aus der Holzschlundfeste herausführt.", description = "Für diese Aufgabe sucht Majordomus Rabine Saturna für Bewahrer Remulos in Moonglade Unterstützung bei der Erforschung des riesigen Ödlandes weit im Westen von Tanaris... und noch weiter im Westen von Un'Goro. Ihr solltet ihn in Nighthaven finden, dem Hauptort von Moonglade.\n\nEure Arbeit wird zwar zweifellos sehr vorteilhaft für uns sein, dennoch rate ich Euch, Vorsicht walten zu lassen. Es gibt Spannungen zwischen Darnassus und Moonglade... Spannungen, die im Laufe der Zeit wachsen könnten.", progress = nil, completion = "Ich bin Rabine Saturna und heiße Euch im Namen von Bewahrer Remulos und allen Bewohnern dieses hochheiligen Tales aufs Herzlichste willkommen.\n\nIch weiß Euer Interesse und Euren Eifer bei der Unterstützung des Zirkels des Cenarius zu schätzen. Ich weiß außerdem, dass der Erzdruide von Darnassus sein Missfallen darüber ausgedrückt hat, dass Ihr uns unterstützt. Seid versichert, dass es zum Guten ist und dass Ihr gegen alle schlechten Auswirkungen gefeit seid, deren Ziel Ihr sein mögt.\n\nIhr seid hier unter Freunden, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[6781] = {title = "Mehr Rüstungsfetzen", objective = "Im Alteractal wird ständig gekämpft und der Nachschub, den wir aus Ironforge bekommen, reicht nicht, um unsere erfahrenen Truppen auszustatten.\n\nWenn Ihr Rüstungsfetzen auf dem Schlachtfeld findet, dann helft den Kriegsbemühungen und bringt mir diese Stücke!", description = nil, progress = "Im Alteractal wird ständig gekämpft und der Nachschub, den wir aus Ironforge bekommen, reicht nicht, um unsere erfahrenen Truppen auszustatten.\n\nWenn Ihr Rüstungsfetzen auf dem Schlachtfeld findet, dann helft den Kriegsbemühungen und bringt mir diese Stücke!", completion = "Das sind ein paar recht gute Stücke, &lt;Name&gt;. Ich kann sie nutzen, um neue Ausrüstung für unsere Truppen herzustellen.\n\nWenn ich genug davon bekomme, dann können vielleicht sogar unsere bewährten Kampfeinheiten in den Kampf eintreten!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPolierte Rüstung"},
[6801] = {title = "Lokholar der Eislord", objective = "Ich komme aus Thunder Bluff, <Volk>. Cairne selbst hat dafür gesorgt, dass ich den Frostwolfklan in diesen schrecklichen Zeiten unterstütze.\n\nDoch lasst uns nicht noch mehr Zeit verschwenden. Ihr müsst unsere Feinde niederstrecken und mir ihr Blut bringen. Wenn Ihr ausreichend Blut gesammelt habt, dann kann das Ritual der Beschwörung beginnen.\n\nDer Sieg ist uns sicher, wenn der Lord der Elementare auf die Stormpike-Armee losgelassen wird.", description = nil, progress = "Ich komme aus Thunder Bluff, <Volk>. Cairne selbst hat dafür gesorgt, dass ich den Frostwolfklan in diesen schrecklichen Zeiten unterstütze.\n\nDoch lasst uns nicht noch mehr Zeit verschwenden. Ihr müsst unsere Feinde niederstrecken und mir ihr Blut bringen. Wenn Ihr ausreichend Blut gesammelt habt, dann kann das Ritual der Beschwörung beginnen.\n\nDer Sieg ist uns sicher, wenn der Lord der Elementare auf die Stormpike-Armee losgelassen wird.", completion = "Das Blut unserer Feinde wurde vergossen. Ich werde nun dieses Blut, mit dem restlichen gesammelten Blut vermischen. Sobald unser Opfer abgeschlossen ist, wird der Eislord diesen Hunden von den Stormpikeden ganzen Zorn des Frostwolfklans vor Augen führen!", rewards = nil},
[6804] = {title = "Vergiftetes Wasser", objective = "Wendet den Aspekt von Neptulon auf die vergifteten Elementare der östlichen Pestländer an. Bringt 12 disharmonische Armschienen, sowie den Aspekt von Neptulon zu Fürst Hydraxis in Azshara.", description = "Eine Truppe von Elementarspähern wurde in die östlichen Pestländer von Lordaeron entsandt und die Krankheit dieses Orts verdrehte und infizierte sie. Die Wasserlords können diese Beleidigung unserer Reinheit nicht dulden!\n\nNehmt diese Phiole. Darin befindet sich ein Quäntchen eines Aspekts von Neptulon. Wenn das auf die verseuchten Elementare angewendet wird, bekämpft es das Gift in ihren Körpern und heilt sie! Ihr innerer Konflikt wird sie allerdings in den lodernden Wahnsinn treiben.\n\nBesiegt die disharmonischen Wogen und bringt mir ihre Armschienen der Bindung.", progress = "Habt Ihr die Armschienen?", completion = "Ihr habt Eure Sache gut gemacht, &lt;Klasse&gt;. Die verderbten Elementare, die Ihr geheilt habt, waren ein Frevel für alle Gewässer. Unsere Kraft liegt in unserer Reinheit und wenn wir unseren Krieg mit den anderen gewinnen wollen, müssen wir stark bleiben.", rewards = "Ihr bekommt:\n\n"},
[6805] = {title = "Stürmer und Rumpler", objective = "Tötet 15 Staubstürmer und 15 Wüstenrumpler und kehrt dann zu Fürst Hydraxis in Azshara zurück.", description = "Wir, die Elementare des Wassers, führen Krieg mit den Wesen der niederen Elemente. Wenn Ihr in diesem Konflikt wirklich unser Verbündeter seid, dann beweist mir Eure Überzeugung!\n\nWeit im Süden, im Wüstenland Silithus, treiben sich die Diener der Luft und Erde in einer Felsenecke herum, die Kristalltal genannt wird. Sie schützen Gegenstände der Macht vor kleineren Wesen und Sterblichen, und obwohl ich nicht weiß, warum sie das tun, will ich ihre Bemühungen zunichte machen.\n\nBegebt Euch zum Kristalltal in Silithus und besiegt unsere Feinde. Kehrt danach zu mir zurück.", progress = "Feigheit ist keine Sache, die wir begrüßen, <Klasse>. Begebt Euch nach Silithus und beweist Euren Mut.", completion = "Euer Mut ist bewiesen, ebenso wie Euer Wert für uns. Vielleicht habe ich in der Zukunft Aufgaben für Euch, die sich eher eines geschätzten Verbündeten der Wasserlords ziemen.", rewards = "Ihr bekommt:\n\n"},
[6821] = {title = "Auge des Glutsehers", objective = "Bringt das Auge des Glutsehers zu Fürst Hydraxis in Azshara.", description = "Ihr habt mir gezeigt, dass Ihr unsere Feinde besiegen und Missionen ausführen könnt, um die Sache der Wasserlords weiter voranzutreiben. Aber bisher seid Ihr nur niederen Feinden gegenübergetreten... wenn Ihr gegen einen mächtigen Feind geschickt werdet, könnt Ihr dann siegen?\n\nDas ist Eure neue Aufgabe.\n\nHoch droben auf der Blackrockspitze haben die Orcs einen Diener des Feuers gefangen genommen, die Feuerwache Glutseher. Sucht den Ort seiner Gefangenschaft, erschlagt seine Häscher und erschlagt dann den Glutseher. Bringt mir sein Auge. Das wird mir Euren Wert zeigen.", progress = "Habt Ihr das Auge, <Klasse>? Seid Ihr stark genug, die Blackrockspitze zu betreten?", completion = "Ah, Ihr habt also die Kraft. Und Ihr habt auch die benötigte Schlauheit, denn die Blackrockspitze erfordert mehr als rohe Gewalt.\n\nIn der Tat, &lt;Name&gt;, Ihr könntet Euch für uns noch als geschätzter Verbündeter erweisen...", rewards = "Ihr bekommt:\n\n"},
[6822] = {title = "Der geschmolzene Kern", objective = "Tötet 1 Feuerlord, 1 geschmolzenen Riesen, 1 uralten Kernhund sowie 1 Lavawoger und kehrt dann zu Fürst Hydraxis in Azshara zurück.", description = "<Name>, vielleicht ist es jetzt an der Zeit, Euch einem echten Test zu unterziehen. Seid Ihr bereit?\n\nAm Fuß der Blackrocktiefen befindet sich ein Durchgang zum geschmolzenen Kern. Er ist eine Festung unseres Feindes, in der Hand des mächtigsten Dieners des Feuers in dieser Welt.\n\nBegebt Euch zum geschmolzenen Kern, <Name>. Zeigt mir, dass Ihr über die Kraft und den Willen verfügt, das zu besiegen, was Ihr dort finden werdet.\n\nUnd wenn Ihr Verbündete in Eurem Volk habt, dann versammelt sie. Nichts Geringeres als eine Armee kann hoffen, den geschmolzenen Kern zu betreten und zu überleben.", progress = nil, completion = "Ihr habt getan, was die meisten Eurer Art für unmöglich halten würden. Ihr seid den Wesen des geschmolzenen Kerns gegenübergetreten und habt triumphiert!\n\nFür eine so kleine Kreatur habt Ihr großes Potenzial gezeigt.\n\nEines Tages erreichen wir möglicherweise ein echtes Bündnis zwischen Eurer Art und den Wasserlords.", rewards = "Ihr bekommt:\n\n"},
[6823] = {title = "Agent von Hydraxis", objective = "Verdient Euch eine geehrte Fraktion bei den hydraxianischen Wasserlords und sprecht dann mit Fürst Hydraxis in Azshara.", description = "Wenn Ihr wirklich ein Bündnis mit uns wünscht, dann schlage ich vor, dass Ihr Krieg gegen unsere Feinde führt, die Diener von Luft und Erde und Feuer. Jede Niederlage, die Ihr Ihnen beibringt, wird ihren Stand hier schwächen und Eure Verbindung zu unserer Sache weiter untermauern.\n\nVor Euch liegen lange und harte Schlachten, doch wenn Ihr diese übersteht, so winken Euch Ruhm und Ehre.", progress = nil, completion = "Die Kunde Eurer Heldentaten gegen unsere Feinde hallt in der Kammer der Wasserlords wider, &lt;Name&gt;. Einige waren der Meinung, dass Eure Gestalt zu klein und zerbrechlich sei, um in unserem Krieg zu kämpfen, aber Ihr habt viel gewonnen. Ihr habt Euch unter uns Respekt verdient, ein unglaubliches Kunststück.", rewards = "Ihr bekommt:\n\n"},
[6824] = {title = "Hände des Feindes", objective = "Bringt die Hände von Lucifron, Sulfuron, Gehennas und Shazzrah zu Fürst Hydraxis in Azshara.", description = "<Name>, Euer Dienst ist für uns von großem Wert, und daher zögern wir, Euch auf diese letzte Mission zu schicken, denn wir wollen einen solch nützlichen Agenten nicht verlieren.\n\nAber der Erfolg würde unsere Kriegsbemühungen ungeheuer voranbringen und... das wird als ausreichend erachtet, Euer Leben zu riskieren.\n\nWir wollen, dass diese Captains im geschmolzenen Kern vernichtet werden: Lucifron, Sulfuron, Gehennas und Shazzrah. Tötet sie und bringt mir ihre Hände!\n\nDiese Aufgabe wird Euer ganzes Können erfordern, <Name>, aber wenn Ihr erfolgreich seid, dann wird den Feuerlords ein schrecklicher Schlag versetzt.", progress = "Habt Ihr Lucifron und die anderen besiegt, <Name>? Habt Ihr die Hände des Feindes?", completion = "Ihr habt die Hände! Die besiegten Feuer-Captains! Ich hätte es nicht für möglich gehalten, wenn ich Euch nicht kennen würde und wüsste, wozu Ihr fähig seid.\n\n&lt;Name&gt;, Eure Heldentaten sind ohne Zahl, aber die Kunde von dieser letzten Heldentat wird unter den Wasserlords Wellen schlagen. Euer Name könnte eines Tages eine Legende unter uns sein.\n\nSprecht wieder mit mir, &lt;Name&gt;. Ich habe möglicherweise noch eine weitere Aufgabe ...", rewards = "Ihr bekommt:\n\n"},
[6825] = {title = "Ruf der Lüfte - Guses Luftflotte", objective = "Wir müssen die neue Flotte von Kriegsreitern vorbereiten, <Volk>! Meine Reiter sind bereit, einen Schlag auf dem zentralen Schlachtfeld zu landen, aber zuerst muss ich ihnen den Mund wässrig machen - sie auf den Angriff vorbereiten.\n\nIch benötige ausreichend Soldatenfleisch der Allianz, um eine Flotte zu ernähren! Hunderte Pfund! Ihr könnt das doch sicherlich übernehmen, nicht wahr? Geht schon!", description = nil, progress = "Wir müssen die neue Flotte von Kriegsreitern vorbereiten, <Volk>! Meine Reiter sind bereit, einen Schlag auf dem zentralen Schlachtfeld zu landen, aber zuerst muss ich ihnen den Mund wässrig machen - sie auf den Angriff vorbereiten.\n\nIch benötige ausreichend Soldatenfleisch der Allianz, um eine Flotte zu ernähren! Hunderte Pfund! Ihr könnt das doch sicherlich übernehmen, nicht wahr? Geht schon!", completion = "Die Flotte ernährt sich von ihrem Fleisch. Sie verzehrt den Feind.\n\nDer Flug steht unmittelbar bevor!", rewards = nil},
[6826] = {title = "Ruf der Lüfte - Jeztors Luftflotte", objective = "Ihr habt hart gearbeitet, <Name>, aber wir haben gerade erst begonnen!\n\nMeine Kriegsreiter müssen das Fleisch ihrer Ziele schmecken. Damit wird ein chirurgischer Schlag gegen unsere Feinde sichergestellt!\n\nMeine Flotte ist die zweitmächtigste in unserem Luftkommando. Daher wird sie beim mächtigsten unserer Gegner zuschlagen. Und dafür benötigt sie das Fleisch der Lieutenants der Allianz.\n\nSputet Euch!", description = nil, progress = "Ihr habt hart gearbeitet, <Name>, aber wir haben gerade erst begonnen!\n\nMeine Kriegsreiter müssen das Fleisch ihrer Ziele schmecken. Damit wird ein chirurgischer Schlag gegen unsere Feinde sichergestellt!\n\nMeine Flotte ist die zweitmächtigste in unserem Luftkommando. Daher wird sie beim mächtigsten unserer Gegner zuschlagen. Und dafür benötigt sie das Fleisch der Lieutenants der Allianz.\n\nSputet Euch!", completion = "Mehr! Mehr! Bringt mehr, denn sie müssen bald bereit sein!", rewards = nil},
[6827] = {title = "Ruf der Lüfte - Mulvericks Luftflotte", objective = "Ich war tagelang in einem Höllenloch der Zwerge eingesperrt. Und das schreit geradezu nach Rache!\n\nWir müssen alles sorgfältig planen.\n\nZuerst benötigen meine Kriegsreiter Ziele, auf die sie sich konzentrieren können - Ziele von hoher Priorität. Ich muss das Fleisch der Kommandanten der Allianz an sie verfüttern. Leider haben sich diese kleinen Mistkerle tief hinter den feindlichen Linien verschanzt! Diese Arbeit ist wahrlich wie geschaffen für Euch.", description = nil, progress = "Ich war tagelang in einem Höllenloch der Zwerge eingesperrt. Und das schreit geradezu nach Rache!\n\nWir müssen alles sorgfältig planen.\n\nZuerst benötigen meine Kriegsreiter Ziele, auf die sie sich konzentrieren können - Ziele von hoher Priorität. Ich muss das Fleisch der Kommandanten der Allianz an sie verfüttern. Leider haben sich diese kleinen Mistkerle tief hinter den feindlichen Linien verschanzt! Diese Arbeit ist wahrlich wie geschaffen für Euch.", completion = "Nicht genug! Solch eine Arbeit würde ich von einem Initianden erwarten, aber von Euch, &lt;Name&gt;? Kommt schon! LASST KNACKEN! Es wird mehr Fleisch benötigt!", rewards = nil},
[6843] = {title = "Da Foo", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[6844] = {title = "Umber, Archivar", objective = "Bringt das verkrustete Silithidenobjekt zu Umber, dem Archivar des Zirkels des Cenarius, ins Dorf Nighthaven in Moonglade.", description = "Hier gibt es immer noch viel zu tun, aber ich denke, es ist wichtig, dies zur Analyse zum Zirkel zurückzubringen. Vertraut mir - es wird immer noch Arbeit geben, wenn das alles erledigt ist. Wenn sich in diesem klebrigen Chitin ein Tagebuch befindet, hätte der Zirkel endlich ein Fenster zur Vergangenheit geöffnet!\n\nBringt dies zum Archivar des Zirkels in Nighthaven. Sein Name ist Umber und er ist brillant. Er ist etwas eigenartig, sicher, aber trotzdem brillant! Umber hat schon Folianten gerettet, die in wesentlich schlechterem Zustand waren als dieser hier. Wenn dieser gerettet werden kann, dann schafft er es.", progress = "Oh, hallo! Hrmm...\n\nLasst mich ehrlich zu Euch sein... Ihr riecht ein wenig streng. Abgestanden, könnte man sagen. Aber ich möchte Eure Person nicht angreifen. Ich sage nur... in Zukunft solltet Ihr Euch ein wenig frisch machen, wenn Ihr vom Schlachtfeld kommt. Damit könnte der erste Eindruck wesentlich positiver ausfallen!\n\nAber egal... was kann ich für Euch tun?", completion = "Heiliger Bimbam! Was habt Ihr denn da? Ich würde sagen, es hat die Form eines Buches... Ich werde versuchen, die Schale darum aufzubrechen.\n\nLayo hat Euch aus Silithus zu mir geschickt? Ich habe nur ein paar geflüsterte Gerüchte gehört - die ja wohl nicht unbedingt geflüstert sind, wenn man's genau nimmt - über die Schrecken, die dort draußen vor sich gehen. Verbindet das mit meiner Abneigung gegen alles Käferähnliche und Ihr habt ein Rezept, damit ich hier bei diesen Büchern bleibe!", rewards = "Ihr bekommt:\n\n"},
[6845] = {title = "Enthüllung von Geheimnissen der Vergangenheit", objective = "Sprecht mit Rabine Saturna im Dorf Nighthaven in Moonglade.", description = "Tja, Ihr solltet möglichst bald wieder zu mir kommen... falls Ihr wissen wollt, was sich hier drinnen befand. Sobald ich herausfinde, was es ist, und falls es in der Tat ein Buch ist, werde ich diese Informationen gern mit Euch teilen.\n\nIn der Zwischenzeit solltet Ihr Euch an die Höhlenmutter dieses kleinen Bärenlagers wenden, Rabine. Es ist bestimmt für alle interessant zu wissen, was für verrückte Dinge Ihr so erlebt habt. Lasst die Höhlenmutter niemals warten, <Name>... zumindest nicht, wenn Ihr nicht in Honig getaucht werden wollt.\n\nDas ist schon passiert, glaubt mir.", progress = nil, completion = "Ah, &lt;Name&gt;... ich hatte gehofft, dass Ihr vorbeikommen würdet. Es ist schön, Euch gesund und munter zu sehen.\n\nIch hatte Nachricht erhalten, dass Ihr vom Schlachtfeld herkommen würdet, und ich wollte persönlich die Dankbarkeit des Zirkels des Cenarius für die Unterstützung zum Ausdruck bringen, die Ihr uns bisher angedeihen ließet. Zweifellos gibt es noch weitere Geheimnisse über die Silithus zu enthüllen. Eure Lieferung an Umber sollte sich als sehr interessant erweisen, wenn sie erst enthüllt ist. Nehmt dies bitte als Zeichen unserer kontinuierlichen Wertschätzung für Eure Hilfe.\n\nDanke, &lt;Klasse&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRing des lebenden SteinsLeuchtender Kristallring\n\nIhr bekommt außerdem:\n\n"},
[6846] = {title = "Der Angriff soll beginnen!", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[6847] = {title = "Meister Rysons Allsehendes Auge", objective = "Holt das allsehende Auge von Meister Ryson aus den Höhlen der Winterax und kehrt damit zu Meister Ryson zurück.\n\nSeid gewarnt, man sagt, dass das allsehende Auge von Meister Ryson einen schrecklicken Fluch mit sich brächte!", description = "Euer Kampf im Herzen von Alterac bedeutet dem Syndikat nichts, <Klasse>. Wir werden so handeln, wie wir es immer getan haben: Warten, bis sich ein klarer Sieger aus der Asche und dem Geröll des Wahnsinns erhebt, und dann zuschlagen.\n\nAber darum sind wir nicht hier. Das allsehende Auge ging verloren - es wurde von den Winteraxtrollen der Region gestohlen.\n\nBeschafft das Auge wieder und unsere Dienste werden Euch gehören - für die Zeit, die Eurer Seite noch verbleibt.\n\nKehrt zu mir zurück, wenn Ihr das Auge beschafft habt, damit ich es untersuchen kann.\n\n<Meister Ryson grinst.>Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil},
[6848] = {title = "Meister Rysons Allsehendes Auge", objective = "Holt das allsehende Auge von Meister Ryson aus den Höhlen der Winterax und kehrt damit zu Meister Ryson zurück.\n\nSeid gewarnt, man sagt, dass das allsehende Auge von Meister Ryson einen schrecklicken Fluch mit sich brächte!", description = "Euer Kampf im Herzen von Alterac bedeutet dem Syndikat nichts, <Klasse>. Wir werden so handeln, wie wir es immer getan haben: Warten, bis sich ein klarer Sieger aus der Asche und dem Geröll des Wahnsinns erhebt, und dann zuschlagen.\n\nAber darum sind wir nicht hier. Das allsehende Auge ging verloren - es wurde von den Winteraxtrollen der Region gestohlen.\n\nBeschafft das Auge wieder und unsere Dienste werden Euch gehören - für die Zeit, die Eurer Seite noch verbleibt.\n\nKehrt zu mir zurück, wenn Ihr das Auge beschafft habt, damit ich es untersuchen kann.\n\n<Meister Ryson grinst.>Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil},
[6861] = {title = "Zinfizzlex's tragbare Schreddereinheit", objective = "Meisteringenieur Zinfizzlex möchte, dass Ihr ihm Folgendes bringt:\n\n*30 Thoriumbarren.\n\n*50 Mithrilbarren.\n\n*75 Eisenbarren.\n\n*1 Dampfsäge.", description = "Ich bin ebenso begierig wie Ihr darauf, meine tragbare Schreddereinheit auszuprobieren, <Volk>, aber bevor ich das Set herstellen kann, benötige ich Material - viel Material!\n\nUm genau zu sein, benötige ich einen Berg aus Thorium, Mithril und Eisen. Ich benötige außerdem eine Dampfsäge pro Einheit. Diese müsst Ihr beim Sägewerk beschaffen.\n\nAls ich mich hier umgesehen habe (vor meiner Gefangennahme), ist mir ein Stapel Dampfsägen im Holzlager von Stormpike aufgefallen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZinfizzlexs tragbare Schreddereinheit"},
[6862] = {title = "Zinfizzlex's tragbare Schreddereinheit", objective = "Meisteringenieur Zinfizzlex möchte, dass Ihr ihm Folgendes bringt:\n\n*30 Thoriumbarren.\n\n*50 Mithrilbarren.\n\n*75 Eisenbarren.\n\n*1 Dampfsäge.", description = "Ich bin ebenso begierig wie Ihr darauf, meine tragbare Schreddereinheit auszuprobieren, <Volk>, aber bevor ich das Set herstellen kann, benötige ich Material - viel Material!\n\nUm genau zu sein, benötige ich einen Berg aus Thorium, Mithril und Eisen. Ich benötige außerdem eine Dampfsäge pro Einheit. Diese müsst Ihr beim Sägewerk beschaffen.\n\nAls ich mich hier umgesehen habe (vor meiner Gefangennahme), ist mir ein Stapel Dampfsägen im Holzlager von Frostwolf aufgefallen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZinfizzlexs tragbare Schreddereinheit"},
[6881] = {title = "Ivus der Waldfürst", objective = "Der Frostwolfklan wird durch eine Besudelung aus Elementarenergie geschützt. Ihre Schamanen stümpern mit Mächten herum, die uns sicherlich alle vernichten werden, wenn sie nicht im Zaum gehalten werden.\n\nDer Schaden ist zu groß geworden, als dass der Kreis ihn noch kontrollieren kann! Wir müssen Ivus zu Hilfe rufen.\n\nDie Soldaten der Frostwolf tragen Elementarglücksbringer, die Sturmkristalle genannt werden. Wir können diese Glücksbringer nutzen, um Ivus zu beschwören. Zieht los und holt die Kristalle, <Name>!", description = nil, progress = "Der Frostwolfklan wird durch eine Besudelung aus Elementarenergie geschützt. Ihre Schamanen stümpern mit Mächten herum, die uns sicherlich alle vernichten werden, wenn sie nicht im Zaum gehalten werden.\n\nDer Schaden ist zu groß geworden, als dass der Kreis ihn noch kontrollieren kann! Wir müssen Ivus zu Hilfe rufen.\n\nDie Soldaten der Frostwolf tragen Elementarglücksbringer, die Sturmkristalle genannt werden. Wir können diese Glücksbringer nutzen, um Ivus zu beschwören. Zieht los und holt die Kristalle, <Name>!", completion = "Gut gemacht, &lt;Name&gt;. Ich werde diese Kristalle dafür benutzen, die bereits angesammelte Magie noch weiter zu verstärken. Wenn sich am Ende genug Kraft gesammelt hat, werde ich die gesammelten Energien bündeln, um den Waldfürsten herbeizurufen.", rewards = nil},
[6901] = {title = "Startet den Angriff!", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[6921] = {title = "Inmitten der Ruinen", objective = "Bringt den Fathom-Kern zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale.", description = "Die Twilight-Hammer sind in die Mondschreinruinen der Blackfathom-Tiefe eingezogen. Ihre Gegenwart kann nur dazu dienen, die Elemente gegen uns aufzubringen. Wenn dem kein Einhalt geboten wird, gehört ihnen diese Region bald ganz und gar.\n\n<Name>, geht nach Blackfathom und findet den Fathom-Stein der Ruinen. Er dürfte irgendwo in deren Nähe im Wasser liegen. Darin ist ein Fathom-Kern - ein Gerät, das, wenn man es richtig abliest, eine Aufstellung über alle Aktivitäten von Elementaren liefert. Wenn ich es habe, können der Irdene Ring und ich vielleicht etwas tun, um sie aufzuhalten.", progress = "Konntet Ihr den Fathom-Kern finden? Ohne ihn haben wir keine Ahnung, was genau die Twilight-Hammer da unten vorhaben.", completion = "Genau das brauche ich! Ein Fathom-Kern ist ein unglaublicher Quell an Informationen, aus denen wir guten Nutzen ziehen können. Was auch immer die Twilight-Hammer da unten im Schilde führen - und glaubt mir, wenn ich sage, dass es nichts Gutes sein kann -, meine Kollegen und ich werden es jetzt aufdecken.\n\nIhr habt Eure Sache hier heute gut gemacht. Der Irdene Ring ist Euch sehr dankbar für Eure Hilfe. Ihr habt außerdem der Horde als Ganzes geholfen, und darauf solltet Ihr stolz sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6922] = {title = "Baron Aquanis", objective = "Bringt die seltsame Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale.", description = "Der besiegte Wasserelementar hat eine seltsame Wasserkugel zurückgelassen. Ihr vermutet, dass das Objekt die Kreatur irgendwie mit Energie versorgte. In der Kugel schwappt eine faulig aussehende Wassergestalt herum. Die Kugel selbst zeigt sich unbeeindruckt von jeder äußerlichen Krafteinwirkung.\n\nWenn irgendwer aus diesem Gegenstand schlau wird, wäre das wohl Je'neu Sancrea vom Irdenen Ring. Er befindet sich im Zoram'gar-Außenposten der Horde in Ashenvale.", progress = "Ach, hallo, <Name>. Ich habe gerade in den Wellen der See gelesen, wie ich es immer tue. Was führt Euch in den Außenposten?", completion = "Das... das ist ein wichtiger Fund, &lt;Name&gt;.\n\nIhr habt dies von Baron Aquanis aus Blackfathom, sagt Ihr? Man hatte Baron Aquanis schon lange im Verdacht, eine verderbte Elementarkraft zu sein. Diese Kugel wird zeigen, was genau ihn verdorben hat. Es würde mich nicht im Geringsten überraschen, wenn es sich dabei um die Twilight-Hammer handelt. Aber unsere Studien werden auch aufzeigen, wie sie das getan haben.\n\nIhr habt das Richtige getan, indem Ihr dies zu mir brachtet. Bitte, nehmt dies zusammen mit den wärmsten Empfehlungen des Irdenen Rings.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesetzlosensäbelHexenfinger\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[6941] = {title = "Ruf der Lüfte - Vipores Luftflotte", objective = "Die Eliteeinheiten der Horde, die die Linien bewachen, müssen erledigt werden! Ich vertraue Euch die Aufgabe an, diese Herde von Wilden auszudünnen. Kehrt mit den Medaillen ihrer Offiziere und Legionäre zu mir zurück. Wenn ich das Gefühl habe, dass ausreichend Gesindel erledigt wurde, werde ich den Luftschlag anordnen.", description = nil, progress = "Die Eliteeinheiten der Horde, die die Linien bewachen, müssen erledigt werden! Ich vertraue Euch die Aufgabe an, diese Herde von Wilden auszudünnen. Kehrt mit den Medaillen ihrer Offiziere und Legionäre zu mir zurück. Wenn ich das Gefühl habe, dass ausreichend Gesindel erledigt wurde, werde ich den Luftschlag anordnen.", completion = "Der Klan wird bald bereit sein. Setzt Eure Bemühungen fort!", rewards = nil},
[6942] = {title = "Ruf der Lüfte - Slidores Luftflotte", objective = "Meine Greifen sind bereit, an den Frontlinien zuzuschlagen, können den Angriff aber erst vornehmen, wenn die Linien ausgedünnt sind.\n\nDie Krieger der Horde, die mit dem Halten der Frontlinien betraut sind, tragen stolz Verdienstmedaillen an ihrer Brust. Reißt diese Medaillen von ihren verfaulten Körpern und bringt sie mir.\n\nWenn die Frontlinie ausreichend ausgedünnt wurde, werde ich den Luftschlag anordnen! Tod von oben!", description = nil, progress = "Meine Greifen sind bereit, an den Frontlinien zuzuschlagen, können den Angriff aber erst vornehmen, wenn die Linien ausgedünnt sind.\n\nDie Krieger der Horde, die mit dem Halten der Frontlinien betraut sind, tragen stolz Verdienstmedaillen an ihrer Brust. Reißt diese Medaillen von ihren verfaulten Körpern und bringt sie mir.\n\nWenn die Frontlinie ausreichend ausgedünnt wurde, werde ich den Luftschlag anordnen! Tod von oben!", completion = "Immer her damit, Soldat! Die Aerie-Greifen werden im Handumdrehen bereit sein zuzuschlagen!", rewards = nil},
[6943] = {title = "Ruf der Lüfte - Ichmans Luftflotte", objective = "Ihr Mut ist auf einem Tiefpunkt, Soldat. Nach unserem letzten fehlgeschlagenen Luftschlag gegen die Horde wollten sie nicht mehr fliegen! Es liegt an Euch, ihre Moral wieder aufzubauen.\n\nKehrt zum Schlachtfeld zurück und schlagt im Herzen des Befehlsstabs der Horde zu. Erledigt ihre Kommandanten und Wächter. Kehrt mit so vielen ihrer Medaillen zu mir zurück, wie Ihr in Eurem Beutel unterbringen könnt! Ich verspreche Euch, wenn meine Greifen die Beute sehen und das Blut unserer Feinde riechen, werden sie wieder fliegen! Geht jetzt!", description = nil, progress = "Ihr Mut ist auf einem Tiefpunkt, Soldat. Nach unserem letzten fehlgeschlagenen Luftschlag gegen die Horde wollten sie nicht mehr fliegen! Es liegt an Euch, ihre Moral wieder aufzubauen.\n\nKehrt zum Schlachtfeld zurück und schlagt im Herzen des Befehlsstabs der Horde zu. Erledigt ihre Kommandanten und Wächter. Kehrt mit so vielen ihrer Medaillen zu mir zurück, wie Ihr in Eurem Beutel unterbringen könnt! Ich verspreche Euch, wenn meine Greifen die Beute sehen und das Blut unserer Feinde riechen, werden sie wieder fliegen! Geht jetzt!", completion = "Seht Ihr es? Schaut sie Euch an! Sie rappeln sich wieder auf... Bald wird Ichmans Klan erneut im Herzen des Tales zuschlagen! Stormpike wird den Himmel beherrschen!", rewards = nil},
[6961] = {title = "Altvater Winter ist hier!", objective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar.", description = "Ich wünsche ein wunderbares Winterhauchfest! Vergesst nicht, Altvater Winter zu begrüßen! Wenn Ihr dieses Jahr brav wart, werdet Ihr am Tag des Winterhauchfestes wunderbare Leckereien erhalten. Denkt daran, ihm zu sagen, was Ihr Euch dieses Jahr wünscht!\n\nAchtet außerdem darauf, Euch mit Leckereien für die einzudecken, die in diesem Jahr brav waren. Wir haben ein großes Angebot zur Auswahl. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost!", progress = nil, completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... ''Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\n Wenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien von Kokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!", rewards = "Ihr bekommt:\n\n"},
[6962] = {title = "Leckereien für Altvater Winter", objective = "Bringt 5 Lebkuchen und etwas eiskalte Milch zu Altvater Winter in Orgrimmar.", description = "He, könnt Ihr Altvater Winter einen Gefallen tun, ähm, <Kleiner/Kleines>?\n\nIch will ja nicht überflüssigerweise über mich selbst in der dritten Person sprechen, aber Altvater Winter arbeitet schon den ganzen Tag hier und könnte selbst eine kleine Leckerei brauchen. Ein paar Lebkuchen und etwas eiskalte Milch, um sie runterzuspülen, wären genau das Richtige. Glaubt Ihr, Ihr könntet dem Altvater eine Freunde machen und das für mich besorgen?", progress = "Durch diese ganze Rederei über Leckereien bin ich langsam schon selbst ganz wild darauf. Mmmm... Lebkuchen und Milch...", completion = "Ihr seid ein wahrer Helfer für den alten Altvater Winter, &lt;Name&gt;. Ich wünsche Euch ein wunderbares Winterhauchfest.\n\nHier habt Ihr eine Kleinigkeit... Ihr wisst schon, für Eure Mühe.", rewards = "Ihr bekommt:\n\nKokelwälder Geschenkpackung"},
[6963] = {title = "Gestohlene Winterhauch-Leckereien", objective = "Sucht den Ermittler von Kokelwälder, der im Alteracgebirge vermisst wird.", description = "Hört zu... ich will Euch ja den Zauber der Feiertage nicht verderben, aber Kokelwälder könnte etwas Hilfe brauchen... von der Art, für die Ihr Abenteurer bekannt seid.\n\nUns ist eine wichtige Lieferung mit Leckereien abhanden gekommen, mit der wir die Vorräte für diese Feiertage aufstocken wollten, und jetzt ist auch noch der Agent von Kokelwälder verschwunden, den wir losgeschickt haben, um sie zu suchen! Also - die letzten Informationen über die Lieferung stammen aus dem Alteracgebirge, und dort wollte unser Mann danach suchen.\n\nSeht nach, ob sowohl Mann als auch Material dort zu finden sind, und zwar gesund und munter.", progress = nil, completion = "I-I-Ihr könnt mich h-h-hören! G-G-Gott sei Dank!\n\nIch bin nicht wirklich ein S-S-Schneemann - mein N-N-Name ist Sacks und ich a-a-arbeite für die N-N-Niederlassung von Kokelwälder in Orgrimmar. Ich w-w-wurde hierher geschickt, um n-n-nach einem vermissten Paket zu suchen, als ich von einer K-K-Kreatur angegriffen wurde, die ich n-n-noch nie gesehen habe!\n\nSo k-k-kalt ...", rewards = "Ihr bekommt:\n\n"},
[6964] = {title = "Der Anlass für die Feiertage", objective = "Sprecht mit Sagorne Crestrider im Tal der Weisheit von Orgrimmar über das Winterhauchfest.", description = "Gaben, Leckereien, Geschenke, pah!\n\nDiese Goblins beschmutzen die wahre Bedeutung dieser Feiertage - des Winterhauchfests. Dies ist eine Zeit der Erneuerung. Das Land schlummert unter einer Schneedecke, die Altvater Winter gebracht hat, und das ist NICHT der Wichtigtuer da drüben in dem roten Aufzug!\n\nFalls Ihr erfahren wollt, worum es bei dem Fest wirklich geht, dann fragt Sagorne Crestrider. Es dürfte ihn bestimmt überraschen, dass sich jemand für Geschichte statt für Geschenke interessiert.", progress = nil, completion = "Das Winterhauchfest, sagt Ihr? Ach ja, in vergangenen Zeiten hatte es für uns Tauren eine wirkliche Bedeutung. Heutzutage hingegen haben andere die Legende dieser Feiertage der Erneuerung zur verkaufsfördernden Maßnahme für Bonbons und Geschenke gemacht.\n\nEs ist nicht verwunderlich, dass Furmund diese Veränderung bitter aufstößt. Er und andere Tauren wie er hängen an unserer Vergangenheit wie an einem Kriegsbanner. Ich denke zwar, dass ein bisschen Feiern immer gut ist, aber es ist auch wichtig, sich an die Ursprünge des Festes zu erinnern.", rewards = "Ihr bekommt:\n\n"},
[6981] = {title = "Der leuchtende Splitter", objective = "Begebt Euch nach Ratchet, um jemanden zu finden, der Euch mehr über den leuchtenden Splitter sagen kann.\n\nLiefert dann den Splitter ab, wie Ihr angewiesen wurdet.", description = "Der Splitter ist von einem glänzenden Grün, und obwohl er massiv ist, scheint etwas wie Rauch knapp unterhalb der Oberfläche herumzuwirbeln. Ihr fühlt den Zwang, in die Tiefen des Kristalls zu schauen, aber gleichzeitig fühlt Ihr auch, dass etwas sehr Beunruhigendes von ihm ausgeht.\n\nVielleicht solltet Ihr in Ratchet nach jemandem suchen, der Euch mehr über diesen seltsamen Splitter erzählen kann.", progress = "Hallo, <Volk>. Was kann ich für Euch tun?", completion = "Oh... So etwas habe ich noch nie gesehen...", rewards = "Ihr bekommt:\n\n"},
[6982] = {title = "Coldtooth-Vorräte", objective = "Bringt 5 Coldtooth-Vorräte zum Rüstmeister der Allianz in Dun Baldar.", description = "Die Coldtooth-Mine ist ein Vorratslager für die Horde. Ich vertrage das Essen nicht, das sie ihren Truppen reichen und der Zustand ihrer Waffen und Rüstungen ist grauenhaft! Aber... in Zeiten wie diesen, in denen Vorräte so wichtig sind, können wir wirklich alles verwenden, was sie haben. \n\nBetretet die Coldtooth-Mine und bringt mir ihre Vorräte. Dies sollte der Allianz helfen sich weiterhin gut im Kampf zu bewähren und die Soldaten der Horde schwächen.\n\nViel Erfolg, <Name>. Die Mine ist im entfernten Süden, tief im Territorium der Horde.", progress = "Habt Ihr die Coldtooth-Mine im Gebiet der Horde betreten, <Name>? Habt Ihr die Vorräte?", completion = "Ihr habt sie! Gut gemacht, &lt;Name&gt;! Ich werde dann mal durch die Vorräte durchgehen und sehen was wir für unsere Truppen gebrauchen können!", rewards = "Ihr bekommt:\n\n"},
[6983] = {title = "So was Gemeines...", objective = "Sucht die gestohlenen Leckereien und bringt sie zu Kaymard Copperpinch nach Orgrimmar. Zuletzt befanden sie sich im Besitz des monströsen Griesgrams, der sich in den Schneegebieten der Arathi-Berge befindet.", description = "Eine K-K-Kreatur namens \"Der monströse Griesgram\" hat u-u-unsere Lieferung mit L-L-Leckereien gestohlen, <Name>. Seid a-a-aber vorsichtig! Er hat m-m-mich in dieses S-S-Schneeschlamassel verwandelt!\n\nIhr w-w-werdet Hilfe brauchen, wenn Ihr ihm g-g-gegenübertretet. Ich habe gesehen, w-w-wie er dort herumzieht, wo die Y-Y-Yetis sind. Er ist s-s-sicherlich irgendwo h-h-hier! F-F-Findet die Leckereien, <Name>, bringt sie zu K-k-k-kokelwälder in Orgrimmar z-z-zurück und s-s-sagt ihnen, dass ich a-a-aufgetaut werden muss!", progress = "<Name> - unser Winterhauchfest ist ruiniert, wenn wir unsere Lager nicht mit diesen Leckereien auffüllen können! Graccu kommt bestimmt zu kurz, wenn er dieses Mal seine köstlichen Fleischpasteten mit all den braven Jungs und Mädchen teilen muss...", completion = "Ihr habt es gefunden! Ihr habt das Winterhauchfest für Kokelwälder gerettet!\n\nArmer Sacks... wir werden ein Team rausschicken und uns eine Möglichkeit überlegen, wie wir ihn wieder auftauen. Hoffentlich ist er rechtzeitig zum Festtag zurück. Allerdings muss er noch die ganze Arbeit aufholen, die inzwischen liegen geblieben ist. Aber ohne Euch wäre auch das nicht möglich!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[6984] = {title = "Ein Dankeschön von Kokelwälder!", objective = "Sprecht mit Altvater Winter in Orgrimmar.", description = "Wir von Kokelwälder sind dankbar für die Wiederbeschaffung der gestohlenen Leckereien, <Name>. Dafür möchten wir Euch ein besonderes Geschenk anbieten... präsentiert von niemand Geringerem als Altvater Winter persönlich!\n\nBitte, sprecht mit Altvater Winter und er wird Euch Euer Geschenk zum Winterhauchfest von uns hier bei Kokelwälder überreichen. Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost... dank Euch natürlich!", progress = nil, completion = "Ho, ho, hallo!\n\nDie Goblins haben mir gesagt, dass Ihr in dieser Feiertagszeit ein besonderes Geschenk verdient habt, und ich freue mich, es Euch überreichen zu dürfen. Bitte schön - ich wünsche Euch für dieses Jahr und für alle kommenden Jahre ein wunderbares Winterhauchfest.", rewards = "Ihr bekommt:\n\nKokelwälder Spezialgeschenk"},
[6985] = {title = "Irondeep-Vorräte", objective = "Bringt 10 Irondeep-Vorräte zum Rüstmeister der Horde in die Burg Frostwolf.", description = "Die Zwerge von Stormpike benutzen die Irondeep-Mine als ein Vorratslager. Ich möchte, dass Ihr diese Mine überfallt und mir ihre Vorräte bringt. Dies sollte die Bemühungen der Stormpikes im Alteractal behindern und uns mit der nötigen Ausrüstung versorgen!\n\nSeid vorsichtig, <Name>. Die Irondeep-Mine liegt tief im Territorium der Allianz, und die Kontrolle über die Mine ändert sich so oft wie neuer Schnee in Alterac fällt.", progress = "Wart Ihr in der Irondeep-Mine, <Name>? Habt Ihr die Vorräte geplündert?", completion = "Ihr habt Sie! Gute Arbeit, &lt;Name&gt;! Hoffentlich habt Ihr unterwegs noch ein paar Zwerge getroffen und ihr Blut im Namen der Frostwolf vergossen!", rewards = "Ihr bekommt:\n\n"},
[7001] = {title = "Verwaiste Ställe", objective = "Findet einen Frostwolf im Alteractal. Wenn Ihr Euch in der Nähe eines Frostwolfs befindet, benutzt den Frostwolfmaulkorb um das Tier einzufangen. Nach erfolgreicher Zähmung, folgt Euch der Frostwolf bis zum Stallmeister zurück. Sprecht mit dem Stallmeister um für Euren Fang belohnt zu werden.", description = "Der Krieg hier im Tal hat viele Opfer gefordert. Unsere Streitkräfte müssen dringend wieder aufgebaut werden!\n\nWenn wir es schaffen unsere Ställe wieder zu füllen, können unsere glorreichen Wolfsreiter wieder in die Schlacht reiten.\n\nNehmt diesen Maulkorb und begebt Euch in die nahegelegenen Wälder. Sucht in der Umgebung nach herumstreifenden Frostwölfen und fangt sie mit dem Maulkorb ein. Wenn Ihr einen Wolf gezähmt habt, bringt ihn zu mir und ich werde ihn in unseren Ställen unterbringen.\n\nSobald wir wieder über ausreichend Wölfe verfügen, werden die Wolfsreiter ihre Frontpatrouillen fortsetzen.", progress = "Ohne Eure Hilfe, hätten die Frostwolfreiter keine Reittiere um in die Schlacht zu ziehen. Ihr erweist uns einen großen Dienst!", completion = "Ich kann nur hoffen das andere die mit dem Sammeln von Widderbälgern beauftragt wurden, ebenso motiviert sind wie Ihr, &lt;Name&gt;.\n\nBei diesem Arbeitstempo, werden die Ställe in wenigen Stunden wieder voll sein!", rewards = nil},
[7002] = {title = "Widderledernes Zaumzeug", objective = "Während einige unserer Soldaten damit beschäftigt sind, Wölfe für den Stallmeister einzufangen, müssen andere für die einfachsten Sachen sorgen, die man beim Reiten braucht. Ich meine Geschirre, klar?\n\nIhr müsst die einheimischen Widder jagen. Genau die Widder, die die Stormpike-Kavallerie als Reittiere benutzt.\n\nTötet sie und bringt mir ihre Häute. Sobald wir genug Häute gesammelt haben, können wir daraus Geschirre für unsere Reiter machen. Die Frostwolfreiter werden wieder reiten!", description = nil, progress = "Während einige unserer Soldaten damit beschäftigt sind, Wölfe für den Stallmeister einzufangen, müssen andere für die einfachsten Sachen sorgen, die man beim Reiten braucht. Ich meine Geschirre, klar?\n\nIhr müsst die einheimischen Widder jagen. Genau die Widder, die die Stormpike-Kavallerie als Reittiere benutzt.\n\nTötet sie und bringt mir ihre Häute. Sobald wir genug Häute gesammelt haben, können wir daraus Geschirre für unsere Reiter machen. Die Frostwolfreiter werden wieder reiten!", completion = "Gut gemacht, Soldat. Ich werde Euch benachrichtigen, sobald wir genug Bälger eingelagert haben.\n\nWeiter so!", rewards = nil},
[7003] = {title = "Geschrumpfte Riesen", objective = "Benutzt Zorbins Super-Schrumpfer um jegliche Art von Riesen in Feralas in eine handlichere Form zu schrumpfen. Bringt Zorbin Fandazzle 15 Schrumpf-Überreste von diesen Riesen. Ihr findet Ihn bei den Docks, an der vergessenen Küste in Feralas.", description = "Ich muss etwas gegen die Riesen unternehmen, wenn ich hier draußen bleibe! Sie sind sicherlich nicht gut fürs Geschäft, oder nicht?\n\nIch habe mich an einer Variante von Gnomischen Schrumpfstrahlen versucht, benutze jetzt aber überlegene GOBLIN Technologien für die Herstellung! Im Zuge von Bemühungen, Unannehmlichkeiten wie meinen Tod beispielsweise zu vermeiden, möchte ich Euch bitten es einmal an diesen Riesen in Feralas zu testen. Ihr solltet nach dem Prozess Schrumpf-Überreste auf ihnen finden, bringt mir bitte etwas davon!", progress = "Schrumpf-Überreste, versichere Ich Euch, sind eine wertvolle Handelsware, was das Ingenieurswesen angeht! Nunja, es ist insofern schon wertvoll, als dass es mir hilft den Schrumpfer zu kontrollieren, sodass er nicht beim Benutzen explodiert.\n\nOh, natürlich meine ich andere Schrumpfer als den, den ich Euch gab. Natürlich ist es ein anderer!", completion = "Großartig! Wie ich sehe, habt Ihr nicht nur die Überreste mitgebracht, sondern seid sogar noch in einem Stück! Äh,... natürlich gab es nie irgendwelche Gefahren bei der Verwendung des Ultra-Schrumpfers.\n\nIch muss mich bei Euch für Eure Bemühungen bedanken, &lt;Name&gt;. Ihr seid ein wirklicher Freund der Goblins. Akzeptiert dies als Zeichen meiner Dankbarkeit!", rewards = "Ihr bekommt:\n\nZorbins Mega-Schnitzler"},
[7021] = {title = "Altvater Winter ist hier!", objective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar.", description = "Ich wünsche ein wunderbares Winterhauchfest! Ihr müsst unbedingt Altvater Winter begrüßen, der sich derzeit in Orgrimmar befindet! Wenn Ihr dieses Jahr brav wart, werdet Ihr am Tag des Winterhauchfestes wunderbare Leckereien erhalten. Denkt daran, ihm zu sagen, was Ihr Euch dieses Jahr wünscht!\n\nAchtet außerdem darauf, Euch mit Leckereien für die einzudecken, die in diesem Jahr brav waren. Wir haben ein großes Angebot zur Auswahl. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost!", progress = nil, completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... 'Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\nWenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien von Kokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!", rewards = "Ihr bekommt:\n\n"},
[7022] = {title = "Altvater Winter ist hier!", objective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Ironforge.", description = "Ich wünsche ein wunderbares Winterhauchfest! Vergesst nicht, Altvater Winter zu begrüßen! Wenn Ihr dieses Jahr brav wart, werdet Ihr am Tag des Winterhauchfestes wunderbare Leckereien erhalten. Denkt daran, ihm zu sagen, was Ihr Euch dieses Jahr wünscht!\n\nAchtet außerdem darauf, Euch mit Leckereien für die einzudecken, die in diesem Jahr brav waren. Wir haben ein großes Angebot zur Auswahl. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost!", progress = nil, completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... 'Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\nWenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien von Kokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!", rewards = "Ihr bekommt:\n\n"},
[7023] = {title = "Altvater Winter ist hier!", objective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Ironforge.", description = "Ich wünsche ein wunderbares Winterhauchfest! Ihr müsst unbedingt Altvater Winter begrüßen, der sich derzeit in Ironforge befindet! Wenn Ihr dieses Jahr brav wart, werdet Ihr am Tag des Winterhauchfestes wunderbare Leckereien erhalten. Denkt daran, ihm zu sagen, was Ihr Euch dieses Jahr wünscht!\n\nAchtet außerdem darauf, Euch mit Leckereien für die einzudecken, die in diesem Jahr brav waren. Wir haben ein großes Angebot zur Auswahl. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost!", progress = nil, completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... 'Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\nWenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien vonKokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!", rewards = "Ihr bekommt:\n\n"},
[7024] = {title = "Altvater Winter ist hier!", objective = "Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar.", description = "Ich wünsche ein wunderbares Winterhauchfest! Ihr müsst unbedingt Altvater Winter begrüßen, der sich derzeit in Orgrimmar befindet! Wenn Ihr dieses Jahr brav wart, werdet Ihr am Tag des Winterhauchfestes wunderbare Leckereien erhalten. Denkt daran, ihm zu sagen, was Ihr Euch dieses Jahr wünscht!\n\nAchtet außerdem darauf, Euch mit Leckereien für die einzudecken, die in diesem Jahr brav waren. Wir haben ein großes Angebot zur Auswahl. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost!", progress = nil, completion = "Ho, ho, hallo! Ich bin Altvater Winter und ich - mit den besten Wünschen von Kokelwälder... 'Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost' - möchte Euch ein phantastisches Winterhauchfest wünschen.\n\nWenn Ihr in diesem Jahr brav wart, dann erhaltet Ihr vielleicht Leckereien von Kokelwälder als Gaumenfreuden zum Winterhauchfest. Hussah!", rewards = "Ihr bekommt:\n\n"},
[7025] = {title = "Leckereien für Altvater Winter", objective = "Bringt 5 Lebkuchen und etwas eiskalte Milch zu Altvater Winter in Ironforge.", description = "He, könnt Ihr Altvater Winter einen Gefallen tun, ähm, <Kleiner/Kleines>?\n\nIch will ja nicht überflüssigerweise über mich selbst in der dritten Person sprechen, aber Altvater Winter arbeitet schon den ganzen Tag hier und könnte selbst eine kleine Leckerei brauchen. Ein paar Lebkuchen und etwas eiskalte Milch, um sie runterzuspülen, wären genau das Richtige. Glaubt Ihr, Ihr könntet dem Altvater eine Freunde machen und das für mich besorgen?", progress = "Durch diese ganze Rederei über Leckereien bin ich langsam selbst schon ganz wild darauf. Mmmm... Lebkuchen und Milch...", completion = "Ihr seid ein wahrer Helfer für den alten Altvater Winter, &lt;Name&gt;. Ich wünsche Euch ein wunderbares Winterhauchfest.\n\nHier habt Ihr eine Kleinigkeit... Ihr wisst schon, für Eure Mühe.", rewards = "Ihr bekommt:\n\nKokelwälder Geschenkpackung"},
[7026] = {title = "Widderzaumzeug", objective = "Die Stormpikegarde kann sich nicht ohne Sättel in die Schlacht stürzen! Wir brauchen Geschirre für unsere Reittiere, schließlich sind wir keine Wilden!\n\nWir könnten zwar einfach die Widder jagen, die in der Nähe unserer Basis herumstreifen, aber das wäre idiotisch. Wenn wir aus ihrem Leder die Geschirre machen, dann haben wir keine Reittiere mehr.\n\nIhr müsst zur Basis des Feindes vorrücken und dort die Frostwölfe töten, die sie als Reittiere benutzen. Bringt mir ihre Häute, damit wir daraus die Geschirre für unsere Kavallerie fertigen können. Geht!", description = nil, progress = "Die Stormpikegarde kann sich nicht ohne Sättel in die Schlacht stürzen! Wir brauchen Geschirre für unsere Reittiere, schließlich sind wir keine Wilden!\n\nWir könnten zwar einfach die Widder jagen, die in der Nähe unserer Basis herumstreifen, aber das wäre idiotisch. Wenn wir aus ihrem Leder die Geschirre machen, dann haben wir keine Reittiere mehr.\n\nIhr müsst zur Basis des Feindes vorrücken und dort die Frostwölfe töten, die sie als Reittiere benutzen. Bringt mir ihre Häute, damit wir daraus die Geschirre für unsere Kavallerie fertigen können. Geht!", completion = "Gut gemacht, Soldat. Ich werde Euch benachrichtigen, sobald wir genug Bälger eingelagert haben.\n\nWeiter so!", rewards = nil},
[7027] = {title = "Verwaiste Ställe", objective = "Findet einen Alteracwidder im Alteractal. Wenn Ihr Euch in der Nähe eines Alteracwidders befindet, benutzt das Stormpike Zähmungshalsband um das Tier einzufangen. Nach erfolgreicher Zähmung, folgt Euch der Alteracwidder bis zum Stallmeister zurück. Sprecht mit dem Stallmeister um für Euren Fang belohnt zu werden.", description = "Seht Euch nur unsere Ställe an, <Name>! Völlig leer! Die Stormpikegarde hat keine Widder mehr, die sie reiten könnte, die Kavallerie ist praktisch nicht mehr existent.\n\nIhr müsst uns helfen, Soldat. Nehmt dieses Zähmungshalsband und begebt Euch in die Wildnis dieses Tals. Sucht in der Umgebung nach herumstreifenden Alteracwiddern und fangt sie mit dem Zähmungshalsband ein. Wenn Ihr einen Widder eingefangen habt, bringt ihn zu mir und ich werde ihn in unseren Ställen unterbringen. Sobald wir wieder über ausreichend Widder verfügen, werde ich den Kommandanten der Widderreiter informieren.\n\n Mit Eurer Hilfe wird die Kavallerie neu entstehen!", progress = "Ohne Eure Hilfe hätten die Stormpike Widderreiter jetzt keine Reittiere, um in die Schlacht zu ziehen. Ihr habt uns einen großen Dienst erwiesen!", completion = "Nicht mehr lange und die Ställe sind wieder voll! Macht weiter so!", rewards = nil},
[7028] = {title = "Dunkles Böses", objective = "Sammelt 25 theradrische Kristallschnitzereien für Willow in Desolace.", description = "Die Kristallhöhlen von Terramok liegen im Westen, tief in Maraudon... Das ist ein uralter Ort mit einer langen Geschichte. Und ich will einiges davon in die Hände bekommen, <Klasse>. Relikte alter Götter liegen hinter den riesigen Türen verborgen.\n\nWenn Ihr bereit seid, dem dunklen Bösen zu trotzen, das sich in Maraudon findet, wird es Euer Schade bestimmt nicht sein. Sammelt die theradrischen Kristallschnitzereien ein, die Ihr aufstöbern könnt, und bringt sie mir.\n\nSobald ich die Schnitzereien habe, kann ich sie... studieren. Diese Mächte haben schon zu lange geruht...", progress = "Stellt keine Fragen!\n\nIhr wisst, was ich will.", completion = "Ha ha ha! Ich wusste, Ihr würdet zurückkehren.\n\n&lt;Willow murmelt vor sich hin.&gt;\n\n... So leicht zu überzeugen.\n\n... Würde alles tun, solange der Preis stimmt. Hi, hi, hi…", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nScharfsinn-RobenRüstringhelmUnerbittliche KetteSchulterstücke des Steinkolosses\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[7029] = {title = "Schlangenzunges Verderbnis", objective = "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.\n\nBenutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxious-Spross herausgezwungen wird.\n\nHeilt 8 Pflanzen, indem Ihr diesen Noxxious-Spross tötet und kehrt dann zu Vark Battlescar in Shadowprey zurück.", description = "Ein Satyr, der unter dem Namen Schlangenzunge bekannt ist, hat die Höhlen von Maraudon verderbt und so das Wachstum vieler Pflanzen im Inneren behindert.\n\nNehmt diese Phiole, <Name>. Füllt sie am orangefarbenen Kristallteich, den Ihr in den Höhlen findet. Die Beschichtung in der Phiole wird den Toxinen entgegenwirken und sie in einen Heilstoff verwandeln.\n\nSucht die Schlangenstrunkranken in den orangefarbenen Höhlen und wendet die geläuterte Flüssigkeit auf sie an. Die Pflanze wird damit von der Verderbnis gereinigt, doch Ihr müsst wissen, dass Schlangenzunge sie immer noch kontrolliert. Er kann sie gegen Euch einsetzen...", progress = "Wenn Ihr die Pflanze heilen könnt, wird sie erneut zu wachsen beginnen. Wir müssen tun, was wir können, <Name>...", completion = "Danke, dass Ihr das zurückgebracht habt, &lt;Name&gt;. Mit der verbleibenden Flüssigkeit, die Ihr mir gebracht habt, kann ich meine Studien fortsetzen.\n\nEs gibt zwar immer noch viel zu tun, aber Ihr habt geholfen, einen Teil der Verderbnis zu heilen, die Schlangenzunge über Maraudon gebracht hat. Nehmt dies bitte zusammen mit meiner Dankbarkeit an.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRing der WaldsaatWeisenblattgurtAstkrallenstulpen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[7041] = {title = "Schlangenzunges Verderbnis", objective = "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.\n\nBenutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxious-Spross herausgezwungen wird.\n\nHeilt 8 Pflanzen, indem Ihr diesen Noxxious-Spross tötet und kehrt dann zu Talendria an der Nijelspitze zurück.", description = "Ein Satyr, der unter dem Namen Schlangenzunge bekannt ist, hat die Höhlen von Maraudon verderbt und so das Wachstum vieler Pflanzen im Inneren behindert.\n\nNehmt diese Phiole, <Name>. Füllt sie am verderbten orangefarbenen Kristallteich, den Ihr in den Höhlen findet. Die Beschichtung in der Phiole wird den Toxinen entgegenwirken und sie in einen Heilstoff verwandeln.\n\nSucht die Schlangenstrunkranken in den orangefarbenen Höhlen und wendet die geläuterte Flüssigkeit auf sie an. Die Pflanze wird damit von der Verderbnis gereinigt, doch Ihr müsst wissen, dass Schlangenzunge sie immer noch kontrolliert. Er kann sie gegen Euch einsetzen...", progress = "Wenn Ihr die Pflanze heilen könnt, wird sie erneut zu wachsen beginnen. Wir müssen tun, was wir können, <Name>...", completion = "Danke, dass Ihr das zurückgebracht habt, &lt;Name&gt;. Mit der verbleibenden Flüssigkeit, die Ihr mir gebracht habt, kann ich meine Studien fortsetzen.\n\nEs gibt zwar immer noch viel zu tun, aber Ihr habt geholfen, einen Teil der Verderbnis zu heilen, die Schlangenzunge über Maraudon gebracht hat. Nehmt dies bitte zusammen mit meiner Dankbarkeit an.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRing der WaldsaatWeisenblattgurtAstkrallenstulpen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[7042] = {title = "Gestohlene Winterhauch-Leckereien", objective = "Sucht den Ermittler von Kokelwälder, der im Alteracgebirge vermisst wird.", description = "Hört zu... ich will Euch ja den Zauber der Feiertage nicht verderben, aber Kokelwälder könnte etwas Hilfe brauchen - von der Art, für die Ihr Abenteurer bekannt seid.\n\nUns ist eine wichtige Lieferung mit Leckereien abhanden gekommen, mit der wir die Vorräte für diese Feiertage aufstocken wollten, und jetzt ist auch noch der Agent von Kokelwälder verschwunden, den wir losgeschickt haben, um sie zu suchen! Also - die letzten Informationen über die Lieferung stammen aus dem Alteracgebirge, und dort wollte unser Mann danach suchen.\n\nSeht nach, ob sowohl Mann als auch Material dort zu finden sind, und zwar gesund und munter.", progress = nil, completion = "I-I-Ihr könnt mich h-h-hören! G-G-Gott sei Dank!\n\nIch bin nicht wirklich ein S-S-Schneemann - mein N-N-Name ist Sacks und ich a-a-arbeite für die N-N-Niederlassung von Kokelwälder in Ironforge. Ich w-w-wurde hierher geschickt, um n-n-nach einem vermissten Paket zu suchen, als ich von einer K-K-Kreatur angegriffen wurde, die ich n-n-noch nie gesehen habe!\n\nSo k-k-kalt ...", rewards = "Ihr bekommt:\n\n"},
[7043] = {title = "So was Gemeines...", objective = "Sucht die gestohlenen Leckereien und bringt sie zu Wulmort Jinglepocket nach Ironforge. Zuletzt befanden sie sich im Besitz des monströsen Griesgrams, der sich in den Schneegebieten der Arathi-Berge befindet.", description = "Eine K-K-Kreatur namens \"Der monströse Griesgram\" hat u-u-unsere Lieferung mit L-L-Leckereien gestohlen, <Name>. Seid a-a-aber vorsichtig! Er hat m-m-mich in dieses S-S-Schneeschlamassel verwandelt!\n\nIhr w-w-werdet Hilfe brauchen, wenn Ihr ihm g-g-gegenübertretet. Ich habe gesehen, w-w-wie er dort herumzieht, wo die Y-Y-Yetis sind. Er ist s-s-sicherlich irgendwo h-h-hier! F-F-Findet die Leckereien, <Name>, bringt sie zu Kokelwälder in Ironforge z-z-zurück und s-s-sagt ihnen, dass ich a-a-aufgetaut werden muss!", progress = "<Name> - unser Winterhauchfest ist ruiniert, wenn wir unsere Lager nicht mit diesen Leckereien auffüllen können! Graccu kommt bestimmt zu kurz, wenn er dieses Mal seine köstlichen Fleischpasteten mit all den braven Jungs und Mädchen teilen muss...", completion = "Ihr habt es gefunden! Ihr habt das Winterhauchfest für Kokelwälder gerettet!\n\nArmer Sacks... wir werden ein Team rausschicken und uns eine Möglichkeit überlegen, wie wir ihn wieder auftauen. Hoffentlich ist er rechtzeitig zum Festtag zurück. Allerdings muss er noch die ganze Arbeit aufholen, die inzwischen liegen geblieben ist. Aber ohne Euch wäre auch das nicht möglich!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[7044] = {title = "Legenden von Maraudon", objective = "Beschafft die beiden Teile des Szepters von Celebras: den Celebriangriff und den Celebriandiamanten.\n\nFindet einen Weg, um mit Celebras zu sprechen.", description = "Ein dunkler Satyr namens Lord Schlangenzunge hat sein Böses in diesen verschlungenen Höhlen verbreitet und die Gedanken aller im Inneren vergiftet. Er residiert noch jenseits der lila Kristalle.\n\nSchlangenzunge hat des Weiteren ein lebendes Symbol seiner Verderbnis namens Noxxion geschaffen, das sich hinter den orangefarbenen Kristallen befindet. Zusammen haben sie die beiden Teile des Szepters meines Bruders gestohlen. Celebras, mein Bruder ... wandert blind im Inneren umher, verflucht durch die Verderbnis.\n\nIhr müsst ihm helfen! Findet die Stücke und sprecht mit meinem Bruder ... irgendwie.", progress = "Ich bin aus einem Alptraum erwacht, der niemals enden wollte...", completion = "Da Ihr nun die beiden Teile meines Szepters zurückgeholt habt, hoffe ich, dass Maraudon eines Tages von der Vyle-Verderbnis befreit ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[7045] = {title = "Ein Dankeschön von Kokelwälder!", objective = "Sprecht mit Altvater Winter in Ironforge.", description = "Wir von Kokelwälder sind dankbar für die Wiederbeschaffung der gestohlenen Leckereien, <Name>. Dafür möchten wir Euch ein besonderes Geschenk anbieten... präsentiert von niemand Geringerem als Altvater Winter persönlich!\n\nBitte, sprecht mit Altvater Winter und er wird Euch Euer Geschenk zum Winterhauchfest von uns hier bei Kokelwälder überreichen. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost... dank Euch natürlich!", progress = nil, completion = "Ho, ho, hallo!\n\nDie Goblins haben mir gesagt, dass Ihr in dieser Feiertagszeit ein besonderes Geschenk verdient habt, und ich freue mich, es Euch überreichen zu dürfen. Bitte schön - ich wünsche Euch für dieses Jahr und für alle kommenden Jahre ein wunderbares Winterhauchfest.", rewards = "Ihr bekommt:\n\nKokelwälder Spezialgeschenk"},
[7046] = {title = "Das Szepter von Celebras", objective = "Helft Celebras dem Erlösten, während er das Szepter von Celebras herstellt.\n\nSprecht mit ihm, nachdem das Ritual vollendet ist.", description = "Mein Szepter war einst eine Quelle der Hoffnung für mich. Seine Macht ermöglichte mir die Freiheit, schnell durch diese Höhlen zu reisen. Ich hatte gehofft, dem Geist meines Onkels Frieden bringen zu können... Das ist eine Aufgabe, die ich nun an Euch übergebe.\n\nDamit die beiden Teile wieder eins werden können, benötige ich Eure Hilfe bei der Durchführung des Rituals. Folgt mir bitte und hört auf meine Anweisungen, während ich die Energie kanalisiere, die erforderlich ist, um den Griff wieder mit dem Diamanten zu vereinigen.\n\nZusammen werden wir das Szepter von Celebras wieder erschaffen!", progress = nil, completion = "Bitte nehmt dies und wisset, dass die Macht, die Euch zugeteilt wurde, nur genutzt werden darf, um Gutes zu tun. Setzt Eure Reise durch diese Höhlen fort, und vielleicht werdet Ihr die Überreste meines Onkels finden. Große Gefahren liegen vor Euch, &lt;Name&gt;.\n\nSprecht erneut mit mir, falls es nötig ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nSzepter von Celebras"},
[7061] = {title = "Das Winterhauchfest", objective = "Ihr könnt gern das Buch 'Das Winterhauchfest' lesen, um mehr über diesen Feiertag zu erfahren. Wenn Ihr das Buch gelesen habt, bringt es zu Cairne Bloodhoof in Thunder Bluff.", description = "Hier - wenn Ihr daran interessiert seid, mehr über das Winterhauchfest zu erfahren, dann lest dieses Buch. Ich glaube zwar, dass unser Verständnis der Legende zutreffend ist, aber als jemand, der Legenden studiert, weiß ich durchaus eine Sammlung aller Informationen in einer einzelnen Quelle zu schätzen.\n\nWenn Ihr fertig seid, bringt das Buch zu Cairne Bloodhoof in Thunder Bluff. Ich weiß mit Bestimmtheit, dass es ihm nicht gleichgültig ist, wenn auch andere sich für die Lehre unseres Volkes interessieren.", progress = "Ich heiße Euch in Mulgore und unserem bescheidenen Gemeinwesen Thunder Bluff willkommen. Ich interessiere mich immer für Leute, die Interesse für die Belange des Königreichs und seine Lehre zeigen. Steht Ihr aus diesem Grund vor mir?", completion = "Die Legenden und die Lehre, die das Winterhauchfest umgeben, sind im Lauf der Jahre bei den Leuten in den Hintergrund gerückt. Ja, ich weiß, dass die Goblins aus recht eigennützigen Motiven dazu beitragen, die Feiertage wiederzubeleben, aber die Tatsache, dass sich unser Volk zumindest auf eine Art damit beschäftigt, hilft, diese Lehre am Leben zu erhalten.\n\nEuer Wunsch, hinter das Materielle zu sehen und mehr über unsere Vergangenheit zu erfahren, ist ein bewundernswerter Zug, &lt;Klasse&gt;. Ich verbeuge mich vor Eurer Weisheit.", rewards = "Ihr bekommt:\n\n"},
[7062] = {title = "Der Anlass für die Feiertage", objective = "Sprecht mit dem Historiker Karnik in der Forscherliga von Ironforge über das Winterhauchfest.", description = "Gaben, Leckereien, Geschenke, pah!\n\nDiese Goblins beschmutzen die wahre Bedeutung dieser Feiertage - des Winterhauchfests. Dies ist eine Zeit der Erneuerung. Das Land schlummert unter einer Schneedecke, die Altvater Winter gebracht hat, und das ist NICHT der Wichtigtuer da drüben in dem roten Aufzug!\n\nFalls Ihr erfahren wollt, worum es bei dem Fest wirklich geht, dann befragt den Historiker Karnik in der Forscherliga. Es dürfte ihn bestimmt überraschen, dass sich jemand für Geschichte statt für Geschenke interessiert.", progress = nil, completion = "Das Winterhauchfest, sagt Ihr? Ach ja, in vergangenen Zeiten hatte es für uns Zwerge eine wirkliche Bedeutung. Heutzutage hingegen haben andere die Legende von Altvater Winter zu einer verkaufsfördernden Maßnahme für Bonbons und Geschenke gemacht.\n\nEs ist nicht verwunderlich, dass Goli diese Veränderung bitter aufstößt. Er und andere Zwerge wie er hängen an unserer Vergangenheit wie an einem Kriegsbanner. Ich denke zwar, dass ein bisschen Feiern immer gut ist, aber es ist auch wichtig, sich an die Ursprünge des Festes zu erinnern.", rewards = "Ihr bekommt:\n\n"},
[7063] = {title = "Das Winterhauchfest", objective = "Ihr könnt gern das Buch 'Das Winterhauchfest' lesen, um mehr über diesen Feiertag zu erfahren. Wenn Ihr das Buch gelesen habt, dann bringt es zu König Magni Bronzebeard nach Ironforge.", description = "Hier - wenn Ihr daran interessiert seid, mehr über das Winterhauchfest zu erfahren, dann lest dieses Buch. Ich glaube zwar, dass unser Verständnis der Legende zutreffend ist, aber als Gelehrter, der Legenden studiert, weiß ich durchaus eine Sammlung aller Informationen in einer einzelnen Quelle zu schätzen.\n\nWenn Ihr fertig seid, dann bringt das Buch zu König Magni Bronzebeard. Ich weiß mit Bestimmtheit, dass es ihn sehr interessieren wird, wenn auch andere Interesse für die alten Legenden an den Tag legen.", progress = "Ich heiße Euch im Königreich Ironforge willkommen. Ich interessiere mich immer für Leute, die Interesse für die Belange des Königreichs und seine Lehre zeigen. Steht Ihr aus diesem Grund vor mir?", completion = "Die Legenden und die Lehre, die das Winterhauchfest umgeben, sind im Lauf der Jahre bei den Leuten in den Hintergrund gerückt. Mir ist durchaus bewusst, dass die Goblins, wenn auch aus recht eigennützigen Motiven, dazu beitragen, die Feiertage wiederzubeleben, aber die Tatsache, dass sich unsere Bevölkerung zumindest auf eine gewisse Art mit dieser Lehre beschäftigt, hilft, sie lebendig zu erhalten.\n\nEuer Wunsch, hinter das Materielle zu sehen und mehr über unsere Vergangenheit zu erfahren, ist ein bewundernswerter Zug, &lt;Klasse&gt;. Ich verneige mich vor Eurem gelehrten Wesen.", rewards = "Ihr bekommt:\n\n"},
[7064] = {title = "Verderbnis von Erde und Samenkorn", objective = "Tötet Prinzessin Theradras und kehrt zu Selendra in der Nähe von Shadowprey in Desolace zurück.", description = "Tief in Maraudon lebt eine böse Kreatur des Chaos - Prinzessin Theradras ist eine Naturgewalt der Erde, die mit den alten Göttern verwandt ist. Vor langer Zeit gingen sie und Zaetar, der erstgeborene Sohn von Cenarius, eine Beziehung ein. Aus ihrer gemeinsamen Zeit entsprangen Wesen, die unter den Menschen von Kalimdor als Zentauren bekannt wurden. Diese undankbaren Kreaturen töteten Zaetar und bewachen nun seine Überreste. Meine Aufgabe besteht darin, jemanden zu finden, der mächtig genug ist, um Theradras zu erschlagen, damit wir Zaetars Überreste holen können, bevor wir in das Steinkrallengebirge zurückkehren.", progress = nil, completion = "Das sind wirklich ganz wunderbare Nachrichten, &lt;Name&gt;! Danke!\n\nIch werde mit Marandis sprechen und um sein Wissen zum Thema Zaetars Überreste bitten, aber zumindest habt Ihr die schwierigste der Aufgaben bereits bewältigt.\n\nMir wurde gesagt, dass ich diejenigen belohnen darf, die uns geholfen haben, wenn wir bei unserer Mission erfolgreich sein sollten. Als Geschenk unseres Volkes habe ich diese Gegenstände erhalten - wählt einen davon.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHauklingeRute der WiederauferstehungZiel des tiefgrünen Bewahrers\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[7065] = {title = "Verderbnis von Erde und Samenkorn", objective = "Erschlagt Prinzessin Theradras und kehrt zum Bewahrer Marandis an der Nijelspitze in Desolace zurück.", description = "In den Tiefen von Maraudon lebt eine Kreatur des Chaos und des Bösen, <Name>. Prinzessin Theradras ist eine Naturgewalt der Erde, die mit den alten Göttern verwandt ist. Vor langer Zeit stattete Zaetar, der erstgeborene Sohn von Cenarius, ihr einen Besuch ab. Die Nachkommen ihrer ... Beziehung sind jene Kreaturen, die unter dem Namen Zentauren bekannt sind. Diese undankbaren Kreaturen töteten Zaetar und Theradras bewacht nun seine Überreste. Meine Aufgabe besteht darin, jemanden zu finden, der mächtig genug ist, um Theradras zu erschlagen, damit wir Zaetars Überreste holen können, bevor wir in das Steinkrallengebirge zurückkehren.", progress = nil, completion = "Das sind wirklich ganz wunderbare Nachrichten, &lt;Name&gt;! Danke!\n\nEs beunruhigt mich zwar, dass Ihr die Überreste von Zaetar nicht zurückbringen konntet, aber wer bin ich, dass ich den Willen des Erstgeborenen von Cenarius in Frage stelle? Vielleicht wird der Wille der Zentauren nun brechen und ihr Blutdurst versiegen - wir können es nur hoffen.\n\nFür den Fall, dass unsere Mission von Erfolg gekrönt sein sollte, habe ich diese Gegenstände erhalten, um jene zu belohnen, die uns halfen. Ihr dürft einen dieser Gegenstände als Zeichen der Dankbarkeit wählen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHauklingeRute der WiederauferstehungZiel des tiefgrünen Bewahrers\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[7066] = {title = "Samenkorn des Lebens", objective = "Sucht Remulos in Moonglade auf und gebt ihm das Samenkorn des Lebens.", description = "Diese missratenen Zentauren - meine Söhne und Töchter - brauchen ihren Vater.\n\nSeht Euch um - dieser Ort hallt wider von Hoffnung und all jenem, was mein Vater Cenarius predigt. All das entsprang aus mir! Und ich kann ihnen das nicht nehmen... nicht einmal ob ihrer Verbrechen gegen mich.\n\nEines jedoch möchte ich von Euch erbitten, damit mein Bruder Ruhe findet. Nehmt dies... es ist das erste Samenkorn, das aus dem Leben entstand, das meine Überreste nährten. Sagt ihm, dass mein Geist hier bleibt und dass ich weiterlebe. Er wird es sicherlich verstehen.", progress = "Euch haftet der Geruch der Verderbnis an, <Name>... wie so vielen Abenteurern in diesen Tagen. Aber etwas an Euch ist anders. Gibt es etwas, über das Ihr mit mir sprechen wollt? Ihr seid von einer Aura umgeben, die vertraut scheint, aber ich kann sie nicht einordnen.\n\nBitte, ich flehe Euch an, sagt mir, warum Ihr mich sehen wolltet.", completion = "Mein Bruder hat also endlich seinen Frieden gefunden? Ich bin stolz, dass ich diesen Tag erleben darf. In seiner ganzen Arroganz und seiner Wut dachte ich wahrlich, er wäre für uns verloren, aber dieses... dieses Symbol seines Opfers beweist eindeutig, dass er nicht verloren ist - er wurde nur neu geboren. Er nimmt seinen Platz in der Natur ein, wie es seine Pflicht war.\n\nIch danke Euch, &lt;Name&gt;. Indem Ihr mir dies brachtet, habt Ihr mir ein wenig Hoffnung geschenkt, die ich schon für vergeblich hielt. Dieses Samenkorn wird für die Menschen in diesem vom Krieg zerrissenen Land eines Tages wichtig sein... Das kann ich spüren.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[7067] = {title = "Die Anweisungen des Pariahs", objective = "Lest die Anweisungen des Pariahs. Beschafft Euch danach das Amulett der Vereinigung von Maraudon und bringt es dem Zentaurenpariah im südlichen Desolace.", description = "Obwohl ich als Ketzer verbannt wurde, bleibe ich meinem Glauben treu - das allein treibt mich voran. Aber damit mein Schicksal sich erfüllt, benötige ich die Hilfe eines Außenstehenden... jemanden, der keinem Zentaurenstamm angehört.\n\nFür diese Aufgabe muss jemand die heiligen Hallen von Maraudon betreten - das ist ein Tempel, den mein Volk schützt, und nur die Gläubigsten dürfen ihn betreten.\n\nWenn Ihr einwilligt, mir zu helfen, dann müsst Ihr nur nicken. Ich werde Euch ein Pergament mit meinen Anweisungen geben. Lest es durch und denkt über meine Worte nach.", progress = "Wie habt Ihr Euch entschieden, <Name>? Könntet Ihr mir helfen? Werdet Ihr Euren Fuß auf heiligen Boden setzen, um mir zu helfen, einen großen Zentaurenstamm zu schmieden!?", completion = "Das ist es, &lt;Volk&gt;! Das ist es! Jetzt kann ich die große Aufgabe der Vereinigung der Stämme angehen. Seid bedankt.\n\nNehmt bitte dies für Eure Bemühungen. Ich hoffe, dass über unserem nächsten Treffen ein glücklicherer Stern stehen wird.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nMal der Auserwählten"},
[7068] = {title = "Schattensplitter", objective = "Sammelt 10 Schattensplitter aus Maraudon und bringt sie zu Uthel'nay nach Orgrimmar.", description = "Man findet starke Magie am heiligen Ort der Zentauren... dem heiligen Ort von Maraudon. Die Desolace-Stämme der Zentauren schützen diesen Ort mit ihrem Leben, aber sie können uns nicht davon abhalten, das zu nehmen, was wir brauchen.\n\nBegebt Euch zu diesem Maraudon-Ort und sucht nach den Felskreaturen, die aus Schattenstein bestehen. Bringt mir die lila Kristalle und Uthel'nay wird Euch Eure Mühe vergelten.\n\nDer Ort ist gefährlich, daher solltet Ihr einige Freunde mitnehmen.", progress = "Habt Ihr die Kristalle schon gefunden? Rituale der Macht, Zauber von großer Kraft - diese Schattensplitter könnten bei allen Arten arkaner Magie hilfreich sein.", completion = "Ah, diese sind perfekt für meine Magie. Hier, nehmt eines dieser Schmuckstücke und macht Euch auf den Weg... ich habe hier viel zu tun.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchattensplitteranhänger des EifersVorwarnender Schattensplitteranhänger\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[7070] = {title = "Schattensplitter", objective = "Sammelt 10 Schattensplitter in Maraudon und bringt sie zu Erzmagier Tervosh in den Marschen von Dustwallow.", description = "Ich habe kürzlich begonnen, verschiedene Kristalle und ihre arkanen Eigenschaften zu testen. Lady Proudmoore hat mir die Erlaubnis erteilt, Reisende, die nach Desolace ziehen, zu bitten, einen Ort zu suchen, der Maraudon genannt wird. In dem zerfallenen Tempel dort gibt es große Elementare, die aus lila Steinen bestehen. Ich habe sie Schattensplitter getauft.\n\nFalls Ihr beschließt, diese Richtung einzuschlagen, und dort einige dieser Kristalle findet, wäre ich sehr dankbar. Ich würde Euch sogar ein Schmückstück daraus herstellen, wenn Ihr dies wünscht.", progress = "Habt Ihr die Reise schon unternommen? Ich weiß, dass es recht gefährlich ist, aber wenn Ihr Erfolg habt, soll es Euer Schaden nicht sein.", completion = "Die sind perfekt, &lt;Name&gt;. Es sind bereits andere Abenteurer von dort zurückgekehrt, und dadurch konnte ich dies herstellen... bitte, nehmt eines der Stücke für Eure harte Arbeit. Und ich danke Euch nochmals, dass Ihr mir weitere Proben für meine Studien besorgt habt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchattensplitteranhänger des EifersVorwarnender Schattensplitteranhänger\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[7081] = {title = "Die Friedhöfe im Alteractal", objective = "Erobert einen Friedhof und kehrt zu Sergeant Durgen Stormpike im Alteracgebirge zurück.", description = "Die Friedhöfe im Alteractal sind äußerst wertvolle Gebiete. Beide Seiten, die Horde und die Allianz, kämpfen verbissen um diese geheiligten Stätten. <Name>, seid Ihr bereit die Kämpfe zu unterstützen?\n\nIch möchte, dass Ihr einen gegnerischen Friedhof besetzt. Sucht einen Friedhof mit einem Hordenbanner in seiner Mitte und reißt es heraus! Wenn Ihr das schafft, ist meine Aufgabe an Euch erfüllt...\n\nSolltet Ihr es schaffen, den Friedhof für einige Minuten zu halten, werden unsere Verstärkungstruppen eintreffen, um Euch bei der Verteidigung zu unterstützen.", progress = "<Name>, Ihr habt noch keinen Friedhof erobert. Kommt zu mir zurück, wenn Ihr Erfolg hattet.", completion = "Gute Arbeit! Friedhöfe sind lebenswichtig für unseren Einfluß im Alteractal. Mit jedem Friedhof den Ihr erobert, helft Ihr der Allianz dabei, ihre Herrschaft im Tal zu sichern. \n\nGeht nun, &lt;Name&gt;.  Zieht wieder in die Schlacht, und falls Ihr einen von der Horde besetzten Friedhof seht... Ihr wißt ja was zu tun ist!", rewards = "Ihr bekommt:\n\n"},
[7082] = {title = "Die Friedhöfe von Alterac", objective = "Erobert einen Friedhof und kehrt zu Corporal Teeka Bloodsnarl im Alteracgebirge zurück.", description = "Die Frontlinien in diesem Tal sind in ständiger Bewegung. Die Gebietsgrenzen bewegen sich hin und her, während wir unseren Feinden in tödlichen Schlachten gegenüber treten. Doch um die Friedhöfe, <Name>, wird am grimmigsten gekämpft.\n\nIch möchte, dass Ihr einen von der Allianz besetzten Friedhof angreift! Sucht einen Friedhof mit einem Allianzbanner in seiner Mitte und reißt es aus dem Boden.\n\nWenn Ihr das schafft, ist meine Aufgabe an Euch erfüllt...\n\nSolltet Ihr es außerdem schaffen, den Friedhof für einige Minuten zu halten, wird dieser uns gehören und unsere Truppen werden kommen, um Euch bei der Verteidigung dieser wichtigen Position zu unterstützen.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;! Mit jedem weiteren Friedhof den wir kontrollieren, wandern die Geister unserer Feinde mehr und mehr verloren und ziellos herum.", rewards = "Ihr bekommt:\n\n"},
[7101] = {title = "Türme und Bunker", objective = "Erobert einen gegnerischen Turm und kehrt anschließend zu Corporal Teeka Bloodsnarl in Frostwolf zurück.", description = "Die Türme und Bunker in diesem Tal sind wichtige Stellungen und daher müssen wir sie möglichst alle erobern und halten! Genug geredet... Erobert einen vom Feind kontrollierten Turm oder Bunker.\n\nBetretet dafür einen mit einem Allianzbanner. Im Inneren befindet sich ein weiteres Banner. Zieht das Banner heraus und ein weißes Hordenbanner wird an seiner Stelle erscheinen.\n\nDamit habt Ihr meinen Auftrag erfüllt. Wenn Ihr das eroberte Gebäude lange genug haltet, ohne dass die Allianz es zurückgewinnt, gehört es uns!", progress = nil, completion = "Ich habe von Eurer erfolgreichen Mission gehört! So gefällt mir das...\n\nunsere Truppen nun ungehindert die feindlichen Stellungen stürmen. Bald werden diese Schwächlinge einsehen das, dass Alteractal kein Ort für sie ist!", rewards = "Ihr bekommt:\n\n"},
[7102] = {title = "Türme und Bunker", objective = "Zerstört das Banner im Inneren eines gegnerischen Bunkers oder Turms. Kehrt anschließend zu Sergeant Durgen Stormpike im Alteracgebirge zurück.", description = "Die Türme und Bunker in diesem Tal sind Schlüsselverteidigungspositionen und daher sollten wir soviele wie möglich davon unter Kontrolle halten! Geht und erobert einen vom Feind kontrollierten Turm oder Bunker.\n\nBetretet dafür einen mit einem Hordebanner. Im Inneren befindet sich ein weiteres Banner. Zieht das Banner heraus und ein weißes Allianzbanner wird an seiner Stelle erscheinen.\n\nDamit habt Ihr meinen Auftrag erfüllt. Wenn Ihr das eroberte Gebäude lange genug haltet, ohne dass die Horde es zurückgewinnt, gehört es uns!", progress = nil, completion = "Ich habe eine Feldnachricht erhalten, nach der Ihr dabei geholfen habt ein feindliches Banner zu sichern. Gute Arbeit, &lt;Name&gt;! Nach der Vernichtung der feindlichen Schützen können wir weiter ins Feindesland vordringen!", rewards = "Ihr bekommt:\n\n"},
[7121] = {title = "Der Rüstmeister", objective = "Sprecht mit dem Rüstmeister der Stormpike.", description = "<Name>, unser Rüstmeister hat mich angewiesen, die neuen Rekruten direkt zu ihm zu schicken. Er benötigt dringend Vorräte aus Kisten, die in den Minen von Alterac eingelagert sind und aller Wahrscheinlichkeit nach wird er Euch entsenden, um sie zu beschaffen.\n\nFolgt einfach der Straße. Ihr findet den Rüstmeister im Westen.", progress = nil, completion = "Ah, endlich sind frische Truppen eingetroffen, &lt;Name&gt;. Mit etwas Glück könnt Ihr hier schnell was erleben und an Erfahrung gewinnen!\n\nSprecht noch einmal mit mir! Ich habe da ein paar Aufgaben, die ich gerne mit Euch besprechen würde....", rewards = "Ihr bekommt:\n\n"},
[7122] = {title = "Mine besetzen", objective = "Erobert eine Mine, die die Stormpike noch nicht kontrollieren, und kehrt dann zu Sergeant Durgen Stormpike im Alteracgebirge zurück.", description = "In den Minen des Alteractals ist noch weit mehr zu finden als bloßes Erz. Sowohl die Frostwolf, als auch die Stormpike, haben große Mengen ihrer Ausrüstung in der Irondeep- und der Coldtooth-Mine untergebracht... was eigentlich keine schlechte Idee ist, solange wir die Kontrolle über sie behalten!\n\nBesetzt eine Mine und kehrt zu mir zurück! Um eine Mine zu erobern, betretet eine vom Feind kontrollierte Mine und tötet den dortigen Anführer. Nachdem Ihr das getan habt, gehört die Mine uns und wir werden Truppen zu ihrem Schutz entsenden!", progress = nil, completion = "Ihr habt es geschafft! Gut gemacht, &lt;Name&gt;!\n\nWenn wir erstmal eine Mine kontrollieren und dort Truppen stationiert haben, wird es viel einfacher die dortige Ausrüstung und Mineralien einzusammeln.", rewards = "Ihr bekommt:\n\n"},
[7123] = {title = "Sprecht mit unserem Rüstmeister", objective = "Sprecht mit dem Rüstmeister der Frostwolf.", description = "<Name>, der Frostwolf Rüstmeister sucht nach Lehrlingen für Aufgaben, die in die Minen des Tals von Alterac führen. Sprecht mit ihm; er wird Euch mehr berichten.\n\nFolgt der Strasse westlich in den Bunker, dann nehmt den westlichen Ausgang und Ihr findet unseren Rüstmeister.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;! Es ist immer wieder eine Freude, einen &lt;Klasse&gt; wie Euch zu treffen, der bereit ist, seinen Beitrag für die Horde zu leisten. Sprecht also noch einmal mit mir. Ich habe äußerst wichtige Aufgaben für Euch...", rewards = "Ihr bekommt:\n\n"},
[7124] = {title = "Eine Mine besetzen", objective = "Erobert eine Mine und kehrt zu Corporal Teeka Bloodsnarl im Alteracgebirge zurück.", description = "So wie Kämpfe im Gebiet des Alteractals wüten, so wüten sie auch durch die Coldtooth- und Irondeep-Minen. Beide bedeuten enorme Ressourcen an Mineralien und beide werden als Lager genutzt; daher ist es kein Wunder, dass sie so heiß begehrt sind!\n\nHelft uns in der Schlacht, <Name>! Erobert für die Horde eine Mine! Begebt Euch zu einer Mine, die noch nicht von uns kontrolliert wird und tötet den dortigen Anführer! Sobald Ihr das geschafft habt, schicken wir Truppen aus, um die Mine zu bewachen!", progress = nil, completion = "Ihr habt eine Mine erobert! Jetzt wo unsere Krieger die Mine vor Angriffen beschützen, wird es uns viel leichter fallen dort Mineralien abzubauen und die dort eingelagerten Vorräte zu bergen.\n\nHervorragende Arbeit, &lt;Name&gt;. Diese Tat ist ein großer Gewinn für unsere Kriegsanstrengungen.", rewards = "Ihr bekommt:\n\n"},
[7141] = {title = "Die Schlacht um Alterac", objective = "Betretet das Alteractal, bezwingt den Hordegeneral Drek'thar und kehrt dann zu Ausgrabungsleiter Stonehewer im Alteracgebirge zurück.", description = "Die Forscherliga glaubt, dass es im Alteractal einige Artefakte von Interesse gibt. Allerdings werden uns die Frostwolforcs wohl kaum danach forschen lassen. Wir können es der Horde jedoch nicht erlauben, unseren Forschungsbemühungen im Weg zu stehen! Vernichet den General der Frostwolf, Drek'Thar. Mit seinem Tod werden die Orcs ihren Vorteil verlieren.\n\nDrek'Thar hält sich in der Burg Frostwolf auf, im Süden des Alteractals. Bezwingt ihn und kehrt dann zu mir zurück.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Jetzt wo die Horde sich mit den Tod Ihres Generals eine blutige Nase geholt hat, haben wir die Atempause, die wir für unsere Forschungsarbeiten brauchen!", rewards = "Ihr bekommt:\n\n"},
[7142] = {title = "Die Schlacht um Alterac", objective = "Betretet das Alteractal und bezwingt den Zwergengeneral, Vanndar Stormpike. Kehrt anschließend zu Voggah Deathgrip im Alteracgebirge zurück.", description = "Die Stormpike-Zwerge und ihre Verbündeten sind in das Alteractal eingefallen und wir müssen sie vertreiben! Um die Schlacht um Alterac gewinnen zu können, müssen wir ihren General töten, Vanndar Stormpike!\n\nIhr werdet Vanndar in Dun Baldar, im Norden des Alteractals finden.\n\nTötet ihn, <Name>, und kehrt dann zu mir zurück.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;! Die Stormpikes haben ihre närrische Invasion bereits verloren.\n\nHah! Das Einzige was sie bisher erreicht haben, ist ihr toter General!", rewards = "Ihr bekommt:\n\n"},
[7161] = {title = "Flaggenjagd", objective = "Begebt euch in die Höhle der Wildpfoten südöstlich vom Hauptstützpunkt und findet das Banner der Frostwolf. Bringt anschließend Kriegsmeister Laggrond das Banner.", description = "Seid gegrüßt, <Klasse>. Es scheint eine Ewigkeit her, seit wir zuletzt dem Ruf des Krieges gefolgt sind. Die alten Gefühle erwachen nur langsam. Doch sind sie erst einmal erwacht, beginnt das Blut erneut zu kochen. Die Kampfeslust kehrt zurück...\n\nAlle Neuankömmlinge im Tal müssen sich zuerst dem Ritus des Kampfes unterziehen.\n\nTief in der nahegelegenen Höhle der Wildpfoten findet Ihr ein Banner der Frostwolf. Zieht los und holt es für uns zurück. Bringt es zu mir und ich gewähre Euch das Abzeichen eines Frostwolfinitiaten.", progress = "Wacht auf! Wacht endlich auf, <Name>! Dies ist kein Traum. Ihr befindet euch tatsächlich inmitten einer tobenden Schlacht!", completion = "Das brennende Gefühl in Euch ist Eure Seele, die langsam erwacht! Euer Geist hat den Ruf zu den Waffen akzeptiert!\n\nIhr gehört nun zu den Frostwolf, &lt;Name&gt;. Ich gratuliere.\n\nTragt dieses Abzeichen immer bei Euch. Mit der Zeit werdet Ihr in den Rängen der Frostwolf aufsteigen und ich werde Euer Abzeichen gegen andere, ranghöhere Abzeichen eintauschen.\n\nVielleicht wird man Euch eines Tages, innerhalb des Frostwolfklans mit Ehrfurcht begegnen. Sollte dieser Tag jemals kommen, werdet Ihr möglicherweise sogar das Auge der Führung erhalten.", rewards = "Ihr bekommt:\n\nAbzeichen der Frostwolf Rang 1Schrittweise zum Sieg"},
[7162] = {title = "Flaggenjagd", objective = "Begebt euch in die Icewinghöhle südwestlich von Dun Baldar und findet das Banner der Stormpike. Bringt anschließend Lieutenant Haggerdin im Alteracgebirge das Banner.", description = "Ihr seid genau zur rechten Zeit eingetroffen, <Klasse>. Diese Wilden der Frostwolf wollen einfach nicht aufgeben! Wir müssen ihnen die Macht der Stormpike vor Augen führen! Am Ende müssen sie sich unserer Überlegenheit beugen.\n\nDoch bevor Ihr Euch auf das Schlachtfeld begebt, solltet Ihr den Reihen der Stormpike beitreten.\n\nSüdwestlich von Dun Baldar befinden sich die Icewinghöhlen. Tief in ihrem Inneren werdet Ihr ein Banner der Stormpike finden. Begebt Euch dorthin und holt das Banner zurück. Bringt es anschließend zu mir und ich werde Euch mit dem Abzeichen eines Stormpikeinitianten auszeichnen.", progress = "Hütet Euch vor den Harpyien in der Gegend, <Klasse>. Die werden nicht zögern Euch die Kehle herauszureissen!", completion = "Nehmt dieses Abzeichen und tragt es mit Stolz, &lt;Name&gt;. Mit der Zeit werdet Ihr in den Rängen der Stormpikegarde aufsteigen. Kehrt dann zu mir zurück und ich werde Euer Abzeichen gegen andere, ranghöhere Abzeichen eintauschen.\n\nVielleicht werdet Ihr eines Tages zu einer Legende dieses Schlachtfeldes heranwachsen. Sollte dieser Tag jemals kommen, wird man Euch mit Sicherheit das Auge der Führung verleihen.", rewards = "Ihr bekommt:\n\nAbzeichen der Stormpike Rang 1Frostwölfe abserviert"},
[7163] = {title = "Aufstieg und Anerkennung", objective = "<Kriegsmeister Laggrond salutiert vor Euch.>\n\nJetzt ist eure Zeit gekommen, <Name>. Ihr habt viel für den Frostwolfklan getan und habt Euch dabei nicht nur als ein Soldat der Frostwolf, sondern auch als Freund bewiesen. \n\nGut gemacht! Zeigt mir Euer Abzeichen!", description = nil, progress = "<Kriegsmeister Laggrond salutiert vor Euch.>\n\nJetzt ist eure Zeit gekommen, <Name>. Ihr habt viel für den Frostwolfklan getan und habt Euch dabei nicht nur als ein Soldat der Frostwolf, sondern auch als Freund bewiesen. \n\nGut gemacht! Zeigt mir Euer Abzeichen!", completion = "Dieses neue Abzeichen zeigt Euren Rang bei den Frostwolf. Tragt es immer bei Euch\n\nUnd &lt;Klasse&gt;... Sterbt mit Ehre.", rewards = "Ihr bekommt:\n\nAbzeichen der Frostwolf Rang 2"},
[7164] = {title = "Ehre innerhalb des Klans", objective = "Es ist gut, Euch wiederzusehen, <Klasse>. Ich hatte nicht erwartet, dass Ihr zurückkehren würdet. Ihr habt Euch als tapferer und ehrbarer Soldat der Frostwolf erwiesen.\n\nWieder ist eure Zeit gekommen, <Name>. Ihr hab einen neuen Rang verdient und damit auch ein neues Abzeichen, das diesen Aufstieg anzeigt.\n\nZeigt mir euer Abzeichen!", description = nil, progress = "Es ist gut, Euch wiederzusehen, <Klasse>. Ich hatte nicht erwartet, dass Ihr zurückkehren würdet. Ihr habt Euch als tapferer und ehrbarer Soldat der Frostwolf erwiesen.\n\nWieder ist eure Zeit gekommen, <Name>. Ihr hab einen neuen Rang verdient und damit auch ein neues Abzeichen, das diesen Aufstieg anzeigt.\n\nZeigt mir euer Abzeichen!", completion = "&lt;Kriegsmeister Laggrond salutiert.&gt;\n\nGeht, &lt;Name&gt;! Setzt Eure Verteidigung der Frostwolf fort. Dieser Krieg muss gewonnen werden! Für Drek'Thar! Für den Kriegshäuptling!", rewards = "Ihr bekommt:\n\nAbzeichen der Frostwolf Rang 3"},
[7165] = {title = "Verdiente Ehrerbietung", objective = "So viele Gefallene. Blut tränkt die Felder. Aber... Ihr lebt... Ihr habt durchgehalten. Ihr habt unsere Armee zu vielen Siegen geführt. Dafür, Soldat, habt Ihr einen neuen Rang verdient..\n\nZeigt mir euer Abzeichen!", description = nil, progress = "So viele Gefallene. Blut tränkt die Felder. Aber... Ihr lebt... Ihr habt durchgehalten. Ihr habt unsere Armee zu vielen Siegen geführt. Dafür, Soldat, habt Ihr einen neuen Rang verdient..\n\nZeigt mir euer Abzeichen!", completion = "&lt;Kriegsmeister Laggrond Brüllt.&gt;\n\nSie haben schon angefangen, Geschichten über Eure Taten zu erzählen, Soldat. Die Stormpikes zittern vor Angst, wenn man euren Namen ausspricht. Weiter so!", rewards = "Ihr bekommt:\n\nAbzeichen der Frostwolf Rang 4"},
[7166] = {title = "Legendäre Helden", objective = "Ihr strahlt Macht und Befehlsgewalt aus, <Klasse>. Erhaben in den Augen der Frostwolf - der Feind duckt sich, wenn Euer Name genannt wird.\n\nErhebt Euch, Held der Frostwolf. Erhebt Euch und lasst Euch ehren!\n\nZeigt mir euer Abzeichen!", description = nil, progress = "Ihr strahlt Macht und Befehlsgewalt aus, <Klasse>. Erhaben in den Augen der Frostwolf - der Feind duckt sich, wenn Euer Name genannt wird.\n\nErhebt Euch, Held der Frostwolf. Erhebt Euch und lasst Euch ehren!\n\nZeigt mir euer Abzeichen!", completion = "Schon bald wird das ganze Schlachtfeld unter eurem wachsamen Auge liegen. Die Führung über das Tal und seine Truppen wird Euer sein!", rewards = "Ihr bekommt:\n\nAbzeichen der Frostwolf Rang 5"},
[7167] = {title = "Das Auge der Führung", objective = "Drek'Thar singt Euch zu Ehren Heldenweisen und in ganz Kalimdor erzählt man sich von Euren Heldentaten. Der Kriegshäuptling blickt stolz auf Euch herab - Eure unerschütterliche Verteidigung unseres Klans hat ihn tief berührt.\n\nIhr habt Euch das Auge der Führung redlich verdient.\n\nPräsentiert Eure Abzeichen, Kommandant <Name>.", description = nil, progress = "Drek'Thar singt Euch zu Ehren Heldenweisen und in ganz Kalimdor erzählt man sich von Euren Heldentaten. Der Kriegshäuptling blickt stolz auf Euch herab - Eure unerschütterliche Verteidigung unseres Klans hat ihn tief berührt.\n\nIhr habt Euch das Auge der Führung redlich verdient.\n\nPräsentiert Eure Abzeichen, Kommandant <Name>.", completion = "Sammelt die Kraft dieser Auszeichnung. Lasst unsere Feinde Eure Worte hören. Die Macht der Horde ist und bleibt unantastbar!", rewards = "Ihr bekommt:\n\nAbzeichen der Frostwolf Rang 6"},
[7168] = {title = "Aufstieg und Anerkennung", objective = "Die Meisten leben nicht lange genug um sich aus ihrer eigenen Mittelmäßigkeit zu erheben. Ihr habt euch als ein mustergültiger Soldat erwiesen, <Klasse>. Die Zeit ist da!\n\nPräsentiert Euer Abzeichen!", description = nil, progress = "Die Meisten leben nicht lange genug um sich aus ihrer eigenen Mittelmäßigkeit zu erheben. Ihr habt euch als ein mustergültiger Soldat erwiesen, <Klasse>. Die Zeit ist da!\n\nPräsentiert Euer Abzeichen!", completion = "Lasst unsere Feinde sehen, dass ein angesehener Soldat sie besiegt hat! Kämpft für den Ruhm der Stormpike!", rewards = "Ihr bekommt:\n\nAbzeichen der Stormpike Rang 2"},
[7169] = {title = "Ehre innerhalb der Garde", objective = "Die ganze Basis spricht von Euren Taten auf dem Feld der Ehre! Ihr habt dem Feind schwere Treffer zugefügt und ihre Moral zerschmettert! Dafür habt Ihr einen Ehrenplatz unter den Stormpike verdient\n\nPräsentiert Euer Abzeichen!", description = nil, progress = "Die ganze Basis spricht von Euren Taten auf dem Feld der Ehre! Ihr habt dem Feind schwere Treffer zugefügt und ihre Moral zerschmettert! Dafür habt Ihr einen Ehrenplatz unter den Stormpike verdient\n\nPräsentiert Euer Abzeichen!", completion = "Der König hat von Euren Heldentaten an der Frontlinie gehört, &lt;Klasse&gt;. Macht weiter so in Eurer wackeren Verteidigung der Stormpikegarde!", rewards = "Ihr bekommt:\n\nAbzeichen der Stormpike Rang 3"},
[7170] = {title = "Verdiente Ehrerbietung", objective = "Ich muss es wissen, <Name>. Wenn Ihr dem Feind direkt ins Auge blickt, seht Ihr dort Furcht? Ducken sie sich in Eurer Gegenwart? Ihnen muss klar sein, dass sie verloren sind!\n\nIhr habt Euch die Ehrerbietung der Garde verdient. Präsentiert Euer Abzeichen!", description = nil, progress = "Ich muss es wissen, <Name>. Wenn Ihr dem Feind direkt ins Auge blickt, seht Ihr dort Furcht? Ducken sie sich in Eurer Gegenwart? Ihnen muss klar sein, dass sie verloren sind!\n\nIhr habt Euch die Ehrerbietung der Garde verdient. Präsentiert Euer Abzeichen!", completion = "Als wir uns zum ersten Mal trafen hätte ich nie geahnt, dass ein werdender Held vor mir steht. Weiter so, Soldat!", rewards = "Ihr bekommt:\n\nAbzeichen der Stormpike Rang 4"},
[7171] = {title = "Legendäre Helden", objective = "Vor mir steht ein erhabener Held der Allianz.\n\n<Lieutenant Haggerdin salutiert.>\n\nWenige haben solch einen Rang unter den Stormpike verdient. Ich habe gesehen wie der Feind vor Euch fiel. Ich habe ihre Entschlossenheit wanken sehen in Eurer Gegenwart. Wenn Ihr Euch ins Kampfgetümmel stürzt, seid ihr ein leuchtendes Fanal der Hoffnung für unsere Streitkräfte!\n\nPräsentiert Euer Abzeichen!", description = nil, progress = "Vor mir steht ein erhabener Held der Allianz.\n\n<Lieutenant Haggerdin salutiert.>\n\nWenige haben solch einen Rang unter den Stormpike verdient. Ich habe gesehen wie der Feind vor Euch fiel. Ich habe ihre Entschlossenheit wanken sehen in Eurer Gegenwart. Wenn Ihr Euch ins Kampfgetümmel stürzt, seid ihr ein leuchtendes Fanal der Hoffnung für unsere Streitkräfte!\n\nPräsentiert Euer Abzeichen!", completion = "Sicherlich werdet Ihr es sein, der das Auge der Führung trägt!", rewards = "Ihr bekommt:\n\nAbzeichen der Stormpike Rang 5"},
[7172] = {title = "Das Auge der Führung", objective = "Lasst sie Eure Stimme hören, KommandantOverthere! Lasst Sie wissen was Angst bedeutet. Zeigt dem Gegner, über welche Macht die Stormpike in ihren Reihen verfügen!\n\nPräsentiert Euer Abzeichen.", description = nil, progress = "Lasst sie Eure Stimme hören, KommandantOverthere! Lasst Sie wissen was Angst bedeutet. Zeigt dem Gegner, über welche Macht die Stormpike in ihren Reihen verfügen!\n\nPräsentiert Euer Abzeichen.", completion = "Ihr seid der Richtige, um unsere Truppen zum Sieg zu führen, Kommandant! Die Soldaten stehen nun unter Eurem Kommando. Sie werden Euren direkten Befehlen Folge leisten. Führt sie an... Vernichtet die Frostwolf.", rewards = "Ihr bekommt:\n\nAbzeichen der Stormpike Rang 6"},
[7181] = {title = "Die Legende von Korrak", objective = "Tief in den Winteraxhöhlen versteckt sich Korrak der Blutrünstige. Den Legenden nach, wird der mächtige Anführer der Winteraxtrolle nur erscheinen, wenn 500 seiner Männer getötet wurden.\n\nBegebt Euch zu den Winteraxhöhlen und vernichtet alles was sich Euch in den Weg stellt, solange bis Korrak selbst auftaucht. Tötet Korrak und kehrt zu Kriegsmeister Laggrond zurück.", description = "Die angreifenden Stormpike sind nicht die einzige Bedrohung in dieser Region, Soldat. Der Krieg in diesem Tal tobt an zwei Fronten. Den kannibalistischen Winteraxtrollen dürstet es ebenso nach Macht.\n\nAngeführt werden sie von Korrak dem Blutrünstigen - einem grausamen und verschlagenen Biest.\n\nEin Streich gegen Korrak könnte sich als vernichtender Schlag für den Winteraxklan erweisen. Tötet diesen Bastard und Ihr werdet entlohnt.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBlutsucherEisstachelspeerZauberstab der beißenden Kälte\n\nIhr bekommt außerdem:\n\nRune des Rückrufs"},
[7201] = {title = "Das letzte Element", objective = "Begebt Euch in die Blackrocktiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hingemurmelt hat.", description = "Es gibt Arbeit für diejenigen, die sich in die Tiefen wagen, <Name>.\n\nDen Dunkeleisenzwergen ist es gelungen, extrem mächtige Golems zu erschaffen.\n\nErsten Berichten unserer Spione zufolge verwenden die Zwerge eine einzigartige Kraftquelle, die ihren Schöpfungen eine unvergleichliche Kraft zum Töten gibt.\n\nStellt Euch nur einmal vor, was wir mit unseren Monstrositäten tun könnten, wenn wir diese Essenz der Elemente in die Hände bekommen könnten! Stellt die ganze Stadt auf den Kopf, wenn es sein muss, aber kommt nicht wieder, ehe Ihr nicht die Essenz gefunden habt! Die Bezahlung ist es wert, das Risiko einzugehen.", progress = "<Sie reibt sich die Hände.>\n\nZeigt sie mir!", completion = "Großartig! Ich werde das sofort mit einem Kurier nach Undercity schicken lassen.\n\nUnd was Euch angeht: Hier ist die versprochene Bezahlung. Behaltet den Rest, dreckige Bestie!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nLagraves Siegel"},
[7202] = {title = "Korrak der Blutrünstige", objective = "Tief in den Winteraxhöhlen versteckt sich Korrak der Blutrünstige. Den Legenden nach, wird der mächtige Anführer der Winteraxtrolle nur erscheinen, wenn 500 seiner Männer getötet wurden.\n\nBegebt Euch zu den Winteraxhöhlen und vernichtet alles was sich Euch in den Weg stellt, solange bis Korrak selbst auftaucht. Tötet Korrak und kehrt zu Lieutenant Haggerdin zurück.", description = "Die eingeborenen Winteraxtrolle dieser Region sind unbarmherzige Wilde, die nichts lieber täten, als unsere Knochen in einer ihrer widerlichen Mahlzeiten zu sehen.\n\nWir müssen ihnen unsere Macht vor Augen führen!\n\nWir konnten einige Schriftstücke aus ihren Höhlen entwenden, die Aufzeichnungen über Ihre Führungshierarchie enthalten. Diese Schriftstücke lassen vermuten, dass ihr Anführer, Korrak der Blutrünstige, sich solange versteckt hält, bis er einen Grund hat sich zu zeigen.\n\nDer Tod Korraks, würde den Tod des Winteraxklans bedeuten! Tötet ihn und kehrt zu mir zurück.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBlutsucherEisstachelspeerZauberstab der beißenden Kälte\n\nIhr bekommt außerdem:\n\nRune des Rückrufs"},
[7221] = {title = "Sprecht mit Ausgrabungsleiter Stonehewer", objective = "Sprecht mit Ausgrabungsleiter Stonehewer in der Garnison von Dun Baldar.Ah, <Name>, Ihr wollt Euch zum Dienst melden, oder? Großartig, die Stormpikes können jeden, der sich freiwillig mustern lässt, gebrauchen!\n\nSprecht mit Ausgrabungsleiter Stonehewer in Dun Baldar. Momentan sucht sie nach Freiwilligen für eine entscheidende Mission im Feindesland. Ihr findet sie unterhalb der Dun Baldar Garnison.\n\nUnd haltet ein Auge offen während Ihr durch Dun Baldar geht. Für einen hart arbeitenden <Klasse> gibt es viel zu tun, sofern Ihr nicht davor zurückscheut Euch die Hände schmutzig zu machen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ah, <Name>, Ihr wollt Euch zum Dienst melden, oder? Großartig, die Stormpikes können jeden, der sich freiwillig mustern lässt, gebrauchen!\n\nSprecht mit Ausgrabungsleiter Stonehewer in Dun Baldar. Momentan sucht sie nach Freiwilligen für eine entscheidende Mission im Feindesland. Ihr findet sie unterhalb der Dun Baldar Garnison.\n\nUnd haltet ein Auge offen während Ihr durch Dun Baldar geht. Für einen hart arbeitenden <Klasse> gibt es viel zu tun, sofern Ihr nicht davor zurückscheut Euch die Hände schmutzig zu machen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7222] = {title = "Sprecht mit Voggah Deathgrip", objective = "Sprecht mit Voggah in Burg Frostwolf.Ah, ein <Klasse>! Wir sind alle hoch erfreut Euch hier in Alterac anzutreffen, <Name>. Zwergische Eindringlinge und ihre Verbündeten sind in unser Tal einmarschiert und wir sind froh über jedes Mitglied der Horde, das uns in dieser gerechten Schlacht zur Seite steht!\n\nSprecht mit Voggah Deathgrip. Er sucht nach Freiwilligen für eine wichtige Mission. Es geht um die Allianzfestung hier im Alteractal!\n\nIhr findet Voggah in Burg Frostwolf.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ah, ein <Klasse>! Wir sind alle hoch erfreut Euch hier in Alterac anzutreffen, <Name>. Zwergische Eindringlinge und ihre Verbündeten sind in unser Tal einmarschiert und wir sind froh über jedes Mitglied der Horde, das uns in dieser gerechten Schlacht zur Seite steht!\n\nSprecht mit Voggah Deathgrip. Er sucht nach Freiwilligen für eine wichtige Mission. Es geht um die Allianzfestung hier im Alteractal!\n\nIhr findet Voggah in Burg Frostwolf.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7223] = {title = "Rüstungsfetzen", objective = "Bringt Murgot Deepforge in Dun Baldar 20 Rüstungsfetzen.", description = "Im Alteractal wird ständig gekämpft und der Nachschub, den wir aus Ironforge bekommen, reicht nicht, um unsere erfahrenen Truppen auszustatten.\n\nWenn Ihr Rüstungsfetzen auf dem Schlachtfeld findet, dann unterstützt unsere Kriegsbemühungen und bringt mir diese Stücke!", progress = "Habt ihr mir Rüstungsfetzen mitgebracht, <Name>?", completion = "Das sind ein paar recht gute Stücke, &lt;Name&gt;. Ich kann sie nutzen, um neue Ausrüstung für unsere Truppen herzustellen.\n\nWenn ich genug davon bekomme, dann können vielleicht sogar unsere bewährten Kampfeinheiten in den Kampf eintreten!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPolierte Rüstung\n\nIhr bekommt:\n\n"},
[7224] = {title = "Beutezug im Feindesland", objective = "Bringt 20 Rüstungsfetzen zu Schmied Regzar in Frostwolf.", description = "Wenn Ihr gegen den Feind kämpft, sammelt die Fetzen seiner Rüstungen ein und bringt sie zu mir. Aus den Fetzen werde ich neue Rüstungen für unsere eigenen Truppen herstellen!", progress = "Wie läuft die Jagd, <Name>.  Habt Ihr irgendwelche Rüstungsfetzen für mich?", completion = "Die werden ihren Zweck erfüllen. Ich werde sie einschmelzen und reparieren und niemand wird je merken, dass sie von diesen feigen Stormpikes stammen!\n\nDanke, &lt;Name&gt;. Und lasst mich Eure Rüstung aufbessern...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPolierte Rüstung\n\nIhr bekommt:\n\n"},
[7241] = {title = "Die Verteidigung von Frostwolf", objective = "Reist ins Alteractal im Vorgebirge von Hillsbrad. Sucht dort Kriegsmeister Laggrond auf und beginnt Eure Karriere als Soldat der Frostwolf.", description = "In der Ferne kann man den Klang der Kriegstrommeln vernehmen, <Klasse>. Die ehrlose Stormpikegarde aus Ironforge greift den Klan Eures Kriegshäuptlings an.\n\nIhr seid kampfgestählt, das verrät mir Euer Auftreten. Es scheint, dass Ihr wahrlich bereit seid, der Sache der Frostwolf zu dienen.\n\nEs liegt nun an Euch, den nächsten Schritt in Eurer Entwicklung zu gehen.\n\nReist in das Vorgebirge von Hillsbrad, dort befindet sich der Zugang zum Alteractal. Betretet das Tal und sucht Kriegsmeister Laggrond auf. Beeilung <Klasse>, die Schlacht hat bereits begonnen!", progress = nil, completion = "Um ein Soldat der Frostwolf zu werden, muss man sich erst beweisen...", rewards = "Ihr bekommt:\n\n"},
[7261] = {title = "Die hoheitliche Anordnung", objective = "Reist ins Alteractal im Vorgebirge von Hillsbrad. Wenn Ihr dort angekommen seid, meldet Euch umgehend bei Leutnant Haggerdin.\n\nFür den Ruhm von Bronzebeard!", description = "Wir kämpfen eine blutige Schlacht in den Tälern von Alterac. Auf der einen Seite werden wir von den kannibalischen Winteraxtrollen angegriffen, auf der anderen bedrängt uns der grausame Frostwolfklan. Beide müssen im Namen unseres König Magni Bronzebeard ausgelöscht werden! Die Eroberung und Säuberung dieses Landes ist eine herrschende und territoriale Notwendigkeit für das Königreich von Ironforge.\n\nLeider wachsen gute Soldaten nicht auf Bäumen! Meldet Euch bei Leutnant Haggerdin im Alteractal, um Euren ehrenvollen Pflichten bei den Stormpike nachzukommen.", progress = nil, completion = "An die Arbeit!", rewards = "Ihr bekommt:\n\n"},
[7281] = {title = "Bruderliebe", objective = "Begebt euch ins Gebiet der Stormpike und tötet Kommandant Karl Philips. Kehrt zu Kommandant Louis Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt.", description = "Welch' tragische Fügung... Mein Bruder steht mir auf dem Schlachtfeld gegenüber: Er ist einer der Stormpike-Kommandanten.\n\nVon allen vier Kommandanten stellt er zweifellos die größte Gefahr dar. Falls man ihn tötet, würde die Bashee Königin ihn vielleicht wiedererwecken, so wie sie es mit mir getan hat - und ihm die Irrtümer seines bisherigen Handelns vor Augen führen...\n\nTief im feindlichen Gebiet werdet Ihr meinen Bruder finden. Tötet ihn und bring ihn zu mir zurück. Ich vertraue darauf, dass Ihr diese Mission erfolgreich zu Ende bringt, Soldat. \n\nUnd Soldat... geht nicht alleine.", progress = nil, completion = "Eure Heldentat wird nicht unbemerkt bleiben, &lt;Name&gt;.\n\n Ich darf keine Zeit verlieren, wenn er gerettet werden soll. Sylvanas muss kontaktiert werden!", rewards = "Ihr bekommt:\n\n"},
[7282] = {title = "Bruderliebe", objective = "Begebt euch ins Frostwolfgebiet und tötet Kommandant Louis Philips. Kehrt zu Kommandant Karl Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt.", description = "Er muss aus seinem Elend befreit werden, Soldat! Mein Bruder weiß nicht mehr, was er tut. Er ist nur noch eine willenlose Marionette der grausamen Bansheekönigin.\n\nBegebt Euch, über das Feld des Kampfes, in die Tiefen des Gebiets der Frostwolf. Findet meinen Bruder und zerstört, was von ihm übrig ist. Seine Qualen sollen endlich ein Ende haben.", progress = nil, completion = "Ihr habt doch daran gedacht den Leichnam zu verbrennen, oder?", rewards = "Ihr bekommt:\n\n"},
[7301] = {title = "Gefallene Himmelsstürmer", objective = "Begebt Euch ins Frostwolf Territorium und sucht nach Schwadronskommandant Slidore, Schwadronskommandant Vipore und Schwadronskommandant Ichman. Meldet Euch bei Kommandant Duffy, sobald Ihr Eure Mission erfüllt habt.", description = "Wir konnten sie gefangennehmen, <Volk>. Ich rede von ihren Schwadronskommandanten. Es war eine wilde Himmelsschlacht, doch letztendlich haben wir sie geschlagen! Sie fielen wie Steine vom Himmel! Leider hat es auch viele unserer besten Piloten erwischt, als Sie die Burg Frostwolf angriffen. Ihr müsst herausfinden was aus ihnen geworden ist.\n\nDurchkämmt das Gebiet der Westturmstellung und Burg Frostwolf. Dort wurden Sie das letzte Mal gesehen. Und geht gründlich vor!", progress = nil, completion = "Unglaublich! Ihr habt Sie doch befreit oder? Oder??? Nun gut, immerhin kennen wir jetzt ihren Aufenthaltsort.", rewards = "Ihr bekommt:\n\n"},
[7302] = {title = "Gefallene Himmelsstürmer", objective = "Findet heraus was aus Schwadronskommandant Guse, Schwadronskommandant Jeztor, und Schwadronskommandant Mulverick geworden ist. Wenn Eure Mission erfüllt ist, kehrt zu Kommandant Mulfort zurück.", description = "Unsere Luftunterstützung musste einen schweren Schlag hinnehmen, <Name>. Sämtliche Schwadronskommandanten wurden über feindlichem Gebiet abgeschossen. Ihr müsst herausfinden was aus ihnen geworden ist, sodass wir einen Rettungsversuch unternehmen können!\n\nGuse wurde das letzte Mal gesehen, als er über den Icewing-Bunker hinwegflog. Jetzors Reittier wurde zuletzt am Stormpike-Sägewerk gesichtet. Mulverick... dieser waghalsige Narr, stürzte in der Nähe des Nordbunkers von Dun Baldar ab.\n\nDas sind alle Informationen die ich habe. Schwärmt aus und durchsucht das Gebiet gründlich!", progress = nil, completion = "Gut gemacht! Eure Informationen sind von umschätzbarem Wert für unsere Sache.", rewards = "Ihr bekommt:\n\n"},
[7321] = {title = "Milde Schildkrötensuppe", objective = "Bringt 10 Stücke Schildkrötenfleisch und einige feine Gewürze zu Christoph Jeffcoat in Tarrens Mühle.", description = "Wer sagt denn, dass Untote keine Ahnung vom Kochen haben? Nehmt als Beispiel nur mal mein Rezept für Schildkrötensuppe. Ich habe Leute getroffen, die sogar von den Toten zurückgekehrt sind, nur um eine Schüssel voll davon zu kosten. Da wir gerade davon sprechen, in letzter Zeit konnte ich keine mehr kochen. Ich bin früher selbst bis zum Lordameresee gereist, um Schnappkiefer zu jagen, aber meine Arbeit hier beschäftigt mich mittlerweile einfach zu sehr. Wenn Ihr mir etwas Schildkrötenfleisch von den Schnappkiefern bringt und dazu noch feine Gewürze, dann werd ich Euch in das Geheimnis meines Rezepts einweihen!", progress = "Hattet Ihr Erfolg bei der Suche nach den Zutaten? Ich sag Euch, dieses Gebiet ist nicht mehr der friedliche Ort, der er einst war. Wenn nur diese Aufstände niemals stattgefunden hätten...", completion = "Meine milde Schildkrötensuppe wird Euch in einer kalten Nacht warm halten... falls es Euch überhaupt interessiert.", rewards = "Ihr bekommt:\n\nRezept: Milde SchildkrötensuppeMilde Schildkrötensuppe"},
[7341] = {title = "Ein fairer Handel", objective = "Seid gegrüßt, <Volk>. Ich bin Kolark, Kopfgeldjäger aus Thunder Bluff. Ich habe viele Teile der Welt bereist und so manches erlebt. \n\nAuf meinen Reisen über die südlichen Meere entdeckte ich diese wunderbaren Thoriumpfeile. Zwar besitze ich einen endlosen Vorrat dieser Pfeile, aber dafür keine einzige Patrone mehr. Bah, kein Tauren mit Selbstachtung würde sich je dabei erwischen lassen, wie er einen dieser dürren Bögen benutzt. Die Pfeile sind nutzlos!\n\nIch schlage Euch einen Handel vor: Einen eins zu eins Tausch von Thoriumpatronen gegen meine Thoriumpfeile. Sind wir im Geschäft?", description = nil, progress = "Seid gegrüßt, <Volk>. Ich bin Kolark, Kopfgeldjäger aus Thunder Bluff. Ich habe viele Teile der Welt bereist und so manches erlebt. \n\nAuf meinen Reisen über die südlichen Meere entdeckte ich diese wunderbaren Thoriumpfeile. Zwar besitze ich einen endlosen Vorrat dieser Pfeile, aber dafür keine einzige Patrone mehr. Bah, kein Tauren mit Selbstachtung würde sich je dabei erwischen lassen, wie er einen dieser dürren Bögen benutzt. Die Pfeile sind nutzlos!\n\nIch schlage Euch einen Handel vor: Einen eins zu eins Tausch von Thoriumpatronen gegen meine Thoriumpfeile. Sind wir im Geschäft?", completion = "Excellent! Ich bin ein Tauren, der sein Wort hält, &lt;Volk&gt;. Die Pfeile gehören Euch.", rewards = "Ihr bekommt:\n\nThoriumpfeile"},
[7342] = {title = "Pfeile sind was für Memmen", objective = "Habt Ihr schon einmal so einen verdammten Mist erlebt?! Die letzte Munitionslieferung aus Kharanos ist völlig verbockt worden. Alles was wir jetzt noch an Munition haben, sind diese schwachen, nutzlosen Pfeile! Was zur Hölle soll ich mit 500.000 Thoriumpfeilen anfangen?\n\nIch sag dir was, Kind. Wenn du es schaffst mir Thoriumpatronen zu bringen, gebe ich dir im Austausch dafür Thoriumpfeile. Sind wir im Geschäft?", description = nil, progress = "Habt Ihr schon einmal so einen verdammten Mist erlebt?! Die letzte Munitionslieferung aus Kharanos ist völlig verbockt worden. Alles was wir jetzt noch an Munition haben, sind diese schwachen, nutzlosen Pfeile! Was zur Hölle soll ich mit 500.000 Thoriumpfeilen anfangen?\n\nIch sag dir was, Kind. Wenn du es schaffst mir Thoriumpatronen zu bringen, gebe ich dir im Austausch dafür Thoriumpfeile. Sind wir im Geschäft?", completion = "Abmachung ist Abmachung! Die Pfeile gehören Euch.", rewards = "Ihr bekommt:\n\nThoriumpfeile"},
[7361] = {title = "Die Gunst der Dunkelspeere", objective = "Ihr wurdet beauftragt gegnerische Nachtelfenspieler im Alteractal zu töten.\n\nTötet einen Nachtelfen und bringt einen abgeschlagenen Nachtelfenkopf zu Najak Hexxen in Burg Frostwolf.", description = "<Najak knurrt.>\n\nBevor die Nachtelfen waren, waren die Trolle. Erst von den Trollen sind Nachtelfen gekommen.\n\nIhre aufrührerischen Angriffe gegen mein Volk können nicht toleriert werden. Hirschhaupt will uns auslöschen - sämtliche Spuren derer vernichten, die ihn und seines Gleichen ausgetragen haben. Das wird nie geschehen!\n\nFür jeden Nachtelfen, den Ihr tötet und enthauptet, wird Najak Euch die Gunst der Dunkelspeere sichern. Die Kunde Eurer Taten wird sich über ganz Kalimdor und den Östlichen Königreichen verbreiten. Geht nun und dient den Dunkelspeeren!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7362] = {title = "Verbündeter der Tauren", objective = "Ihr wurdet beauftragt gegnerische Gnomspieler im Alteractal zu töten.\n\nTötet einen Gnom und bringt ein Büschel Gnomhaar zu Ravak Grimmtotem in Burg Frostwolf.", description = "Die Älteste hat mich in dieses Kriegsgebiet geschickt um die anderen Völker zu erforschen. Genau genommen bin ich hier, um Proben von den Gnomen zu nehmen. Magatha interessiert sich insbesondere für ihre Überlebensfähigkeit. Die Gnome - obwohl erbärmlich schwach und winzig - scheinen sowohl im Kampf als auch körperlich äußerst widerstandsfähig zu sein.\n\nZum Glück für Euch, suche ich nach Freiwilligen, die Magathas Anweisungen in die Tat umsetzen. Bringt mir Gnomhaarbüschel und die Tauren werden Euch als Verbündeten anerkennen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7363] = {title = "Die menschliche Existenz", objective = "Ihr wurdet beauftragt gegnerische Menschenspieler im Alteractal zu töten.\n\nTötet einen Menschen und bringt dessen Knochensplitter zu Kommandant Louis Philips (er bewegt sich zwischen den Frontlinien und Burg Frostwolf hin und her).\n\nDie Heilung für die menschliche Existenz ist zum Greifen nahe!", description = "Menschen sind schlichtweg verabscheuenswert.\n\n<Kommandant Philips schneidet eine Grimasse.>\n\nZwar entspricht es den Tatsachen, dass ich ein Soldat der Frostwölfe bin, dennoch bleibe ich ein Diener Sylvanas.\n\nNeben der Ausübung meiner Pflichten, arbeite ich auch für die Dunklen Apotheker von Unterstadt.\n\nIch bin damit beauftragt worden menschliche Knochensplitter einzusammeln, die helfen sollen, uns von der menschlichen Existenz zu befreien.\n\nMan hat mich außerdem dazu berechtigt, diese Aufgabe an meine Untergebenen weiterzureichen.\n\nFindet sie. Tötet sie. Bringt mir ihre Knochensplitter.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7364] = {title = "Gnomeregan Kopfgeld", objective = "Ihr wurdet beauftragt gegnerische Taurenspieler im Alteractal zu töten.\n\nTötet einen Tauren und bringt dessen Taurenhuf zu Dirk Schwindel in Dun Baldar.", description = "Der Hochtüftler persönlich hat mich auf dieses Schlachtfeld beordert, um meinen Brüdern und Schwestern beizustehen. Es ist uns zu Ohren gekommen, dass die Tauren sich einzelne Gnome herauspicken und töten. Noch viel schlimmer ist, dass sie den Leichen ihr prächtiges Gnomhaar büschelweise abschneiden. Diese Greultaten müssen aufgehalten werden. Wir müssen Vergeltung üben!\n\nIch will sie alle enthuft sehen, <Klasse>. Bringt mir ihre Hufe! Erweist euch als Verbündeter der Gnome.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7365] = {title = "Hirschhaupts Requiem", objective = "Ihr wurdet beauftragt gegnerische Trollspieler im Alteractal zu töten.\n\nTötet einen Troll und bringt Athramanis in Dun Baldar etwas Trollmojo der Dunkelspeere.", description = "Hirschhaupt hat uns Anweisung gegeben, alle Trolle auf dem Schlachtfeld auszulöschen. Ihrer lächerlichen Behauptung die Nachtelfen erschaffen zu haben, kann nur mit aller Macht und militärischen Mitteln entgegengewirkt werden.\n\nTötet sie alle und bringt mir ihr Mojo. Ich wiederhole: Stehlt ihnen ihr Mojo.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7366] = {title = "Die Gnade des Erzbischofs", objective = "Ihr wurdet beauftragt gegnerische Verlassenen-Spieler im Alteractal zu töten.\n\nTötet einen Verlassenen und bringt dessen Herz zu Kommandant Karl Philips (er bewegt sich zwischen dem Sägewerk und der Mine hin und her).", description = "Der Erzbischof ist so gütig wie er weise ist. Dass ein Mann wie er derartig gnädig zu einer solch elenden Bande sein kann...\n\n<Kommandant Philips schüttelt ungläubig den Kopf.>\n\nZu gütig... einfach zu gütig.\n\nDer Erzbischof möchte, dass wir uns der Untoten erbarmen und ihnen einen schnellen und endgültigen Tod gewähren. Für diesen großen Akt der Gnade benötigen wir nur ihre schwarzen, von Krankheit besessenen Herzen.\n\nBringt mir die Herzen der Verlassenen, sodass wir sie in der Kathedrale des Lichts zeremoniell verbrennen können. Eilt euch, <Name>!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7367] = {title = "Die Gefahr bannen", objective = "Findet den Sprengmeister der Frostwolf und tötet ihn. Kehrt nach Abschluss des Auftrags zum Sprengmeister der Stormpike zurück.", description = "Die Frostwolf haben ihre Frontlinien und Basen allesamt vermint, <Klasse>. Achtet darauf wohin Ihr tretet, wenn Ihr in feindliches Territorium eindringt.\n\nWenn wir dem Feind einen entscheidenden Schlag versetzten wollen, müsst Ihr seine Quelle für Sprengwaffen zum Versiegen bringen - Ich rede vom feindlichen Sprengmeister! Tötet ihn und wir können alle Minen sicher entschärfen. Solange er ausfällt, fallen auch seine Minen aus.\n\nVermutlich befindet er sich in einem Turm, nahe der Iceblood-Garnison. Viel Glück, Soldat!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7368] = {title = "Die Gefahr bannen", objective = "Findet den Sprengmeister der Stormpike und tötet ihn. Kehrt nach Abschluss des Auftrags zum Sprengmeister der Frostwolf zurück.", description = "Ich weiß alles über Landminen. Immerhin habe ich alle Minen an unseren Frontlinien selbst verlegt.\n\nWenn Ihr das Stormpike Minenfeld unschädlich machen wollt, braucht Ihr nur eines zu tun - Tötet den feindichen Sprengmeister! Zweifellos versteckt sich der feige Zwerg im ersten Turm, auf dem Feld des Kampfes. Schaltet ihn aus und die Landminen werden nicht zurückkommen, nachdem sie von Euch entschärft wurden.\n\n Falls Ihr es schaffen solltet den Sprengmeister zu töten, kommt zu mir zurück und lasst es mich wissen. Keine gute Tat soll unbelohnt bleiben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7381] = {title = "Korraks Rückkehr", objective = "Sollte Korrak der Blutrünstige wieder in den Winteraxhöhlen auftauchen, sucht ihn auf und tötet ihn.\n\nBringt Korraks Schädel zu Kriegsmeister Laggrond auf Burg Frostwolf.", description = "Es ist zwar eine Tatsache, dass Korrak gefallen ist, jedoch bleibt eine Frage offen: Wird er auch tot bleiben? Trolle sind berüchtigt für ihre außerweltliche Stammesmagie. Mich würde es nicht überraschen, wenn ihr toter Anführer wiedererweckt würde, um wieder einmal über seinen Klan zu herrschen.\n\nIhr wisst ja was in einem solchen Fall zu tun ist.\n\n<Kriegsmeister Laggrond deutet mit seinem Finger eine Schneidebewegung an seinem Hals an.>\n\nUnd nächstes mal möchte ich seinen Schädel. Haltet einfach die Augen offen, Soldat.\n\nWegtreten!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRune des Rückrufs"},
[7382] = {title = "Korrak der Unsterbliche", objective = "Sollte Korrak der Blutrünstige wieder in den Winteraxhöhlen auftauchen, sucht ihn auf und tötet ihn.\n\nBringt Korraks Schädel zu Leutnant Haggerdin in Dun Baldar.", description = "Irgendetwas stimmt an dieser Sache nicht... Hat jemand daran gedacht, Korraks Körper zu verbrennen? Diese Trolle werden vor nichts haltmachen, um ihren gefallenen Anführer wiederzubeleben – so wie es die blauhäutigen Heiden des öfteren tun.\n\nHaltet immer ein Auge offen, <Name>. Seid nicht beunruhigt, wenn Karrak überraschend wieder auftaucht. Und wenn er das tut, will ich ihn tot sehen – seinen Körper zu Asche verbrannt.\n\nObendrein, schlagt ihm seinen Kopf ab und bringt mir seinen Schädel, bevor Ihr seinen leblosen Körper verbrennt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRune des Rückrufs"},
[7383] = {title = "Krone der Erde", objective = "Füllt die Amethystphiole und bringt sie Corithras Moonrage in Dolanaar.", description = "Mit Teldrassil stand es jedoch nicht zum Besten. Staghelms sorgfältig durchdachte Pläne für den neuen Weltbaum entwickelten sich nicht so, wie er gehofft hatte, denn es gab ein kleines Problem. Ein Problem, das die Ursache für viele weitere Probleme Teldrassils ist.\n\nWie dem auch sei, dazu komme ich später. Ihr müsst den letzten Mondbrunnen nordwestlich von hier in der Lichtung des Orakels aufsuchen. Unter den Ästen des Orakelbaums befindet sich der wichtigste und mächtigste unserer Brunnen. Beschafft eine Phiole seines Wassers und bringt sie mir.", progress = "Die Druiden, unter Mitwirkung des Orakelbaums und des Erzdruiden, haben sich sorgsam um die Hege Teldrassils gekümmert. Wir haben jetzt zwar eine neue Heimat, doch unsere Unsterblichkeit haben wir noch nicht wiedererlangt.", completion = "In der Nähe des Orakelbaums... kann man fast spüren, wie die Weisheit Gestalt annimmt. Lasst mich mit der Geschichte fortfahren...\n\nTeldrassil wuchs und gedieh, und der Erzdruide wandte sich an die Großdrachen, um deren Segen zu erhalten, den sie in längst vergangenen Zeiten über Nordrassil verbreitet hatten. Nozdormu jedoch, der Lord der Zeit, weigerte sich, seinen Segen zu spenden und tadelte den Druiden wegen seiner Arroganz. Einig mit Nozdormu widersetzte sich auch Alexstrasza Staghelm und ohne ihren Segen entartete Teldrassil und wuchs auf unvorhersehbare Weise...", rewards = "Ihr bekommt:\n\n"},
[7384] = {title = "Die Schuppenmacher", objective = "Sammelt für Karana im Sicheren Hafen, in den Sümpfen des Elends einige Schuppen.", description = "Gebt mir einige Schuppen.", progress = nil, completion = nil, rewards = nil},
[7385] = {title = "Eine Gallone Blut", objective = "Wenn Ihr Euch nützlich machen wollt, spendet mir große Mengen Feindesblut. Ich wäre hocherfreut, Gallonen von Blut entgegen zu nehmen, <Name>.", description = nil, progress = "Wenn Ihr Euch nützlich machen wollt, spendet mir große Mengen Feindesblut. Ich wäre hocherfreut, Gallonen von Blut entgegen zu nehmen, <Name>.", completion = "Das Blut unserer Feinde wurde vergossen. Ich werde nun dieses Blut, mit dem restlichen gesammelten Blut vermischen. Sobald unser Opfer abgeschlossen ist, wird der Eislord erscheinen und diesen Hunden von den Stormpike den ganzen Zorn des Frostwolfklans vor Augen führen!", rewards = nil},
[7386] = {title = "Haufenweise Kristalle", objective = "Es gibt hier Zeiten, in denen Ihr Tage oder sogar Wochen auf den Schlachtfeldern zubringt. Vielleicht könnt Ihr während dieser Zeit nach größeren Gruppen von Frostwolf Sturmkristallen Ausschau halten.\n\nDer Zirkel wäre hocherfreut über derartige Spenden, <Name>.", description = nil, progress = "Es gibt hier Zeiten, in denen Ihr Tage oder sogar Wochen auf den Schlachtfeldern zubringt. Vielleicht könnt Ihr während dieser Zeit nach größeren Gruppen von Frostwolf Sturmkristallen Ausschau halten.\n\nDer Zirkel wäre hocherfreut über derartige Spenden, <Name>.", completion = "Gut gemacht, &lt;Name&gt;. Ich werde diese Kristalle dafür benutzen, die bereits angesammelte Magie noch weiter zu verstärken. Wenn sich am Ende genug Kraft gesammelt hat, werde ich die gesammelten Energien bündeln, um den Waldfürsten herbeizurufen.", rewards = nil},
[7401] = {title = "GESUCHT: Zwerge!", objective = "Ihr wurdet damit beauftragt, alle feindlichen Zwergenspieler im Alteractal zu töten.\n\nTötet einen Zwerg und schneidet ihm sein Rückgrat heraus. Bringt anschließend das Zwergenrückgrat zu Unteroffizierin Yazra Murrblut in Burg Frostwolf.", description = "Auf Befehl von Unteroffizierin Yazra Murrblut sind alle Zwerge auf dem Schlachtfeld umgehend zu töten.\n\nSolltet Ihr einen Zwerg im Kampf töten, schneidet ihm sein Rückgrat heraus und lasst den rückgratlosen Fleischhaufen als Mahnmal für alle zurück, die sich gegen die Frostwölfe stellen.\n\nKehrt anschließend mit dem Beweis Eurer Heldentat zu Unteroffizierin Yazra Murrblut zurück.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7402] = {title = "GESUCHT: Orcs!", objective = "Ihr wurdet damit beauftragt, alle feindlichen orcischen Spieler im Alteractal zu töten.\n\nTötet einen Orc und bringt seinen Zahn zurück zu Korporal Noreg Sturmlanze in Dun Baldar.", description = "Auf Befehl von Korporal Noreg Sturmlanze sind alle verfügbaren Soldaten dazu aufgefordert, jeden gegnerischen Orc auf dem Schlachtfeld umgehend zu töten.\n\nDie Soldaten sind weiterhin dazu aufgefordert, einen Hauer oder Zahn aus dem Maul des Feindes zu entfernen, um diese als Beweis für ihre Tat vorzeigen zu können.\n\nBitte tragt dafür Schutzhandschuhe.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7421] = {title = "Verteidigung der Dunkelspeere", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7422] = {title = "Mehr Gnomhaar", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7423] = {title = "Knochensplitterjagd", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7424] = {title = "Was zum Huf?", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7425] = {title = "Hirschhaupts Mojo-Fete", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7426] = {title = "Die Liebe eines Mannes", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7427] = {title = "GESUCHT: MEHR ZWERGE", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7428] = {title = "GESUCHT: MEHR ORCS!", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7429] = {title = "Befreit Knot!", objective = "Sie nennen ihn den Gordokfesselschlüssel - Naja, zumindest tun es diese \"Tonnenweise Spaß auf zwei Beinen\"-Oger. Ich denke einer der Oger müsste ihn haben, leider weiß ich nicht genau welcher. Möglicherweise ist die Chance größer, dass einer der Wachen ihn hat...\n\nWas erzähle ich da? - sicher habt Ihr ihn schon, oder? Ist es der da??!", description = nil, progress = "Sie nennen ihn den Gordokfesselschlüssel - Naja, zumindest tun es diese \"Tonnenweise Spaß auf zwei Beinen\"-Oger. Ich denke einer der Oger müsste ihn haben, leider weiß ich nicht genau welcher. Möglicherweise ist die Chance größer, dass einer der Wachen ihn hat...\n\nWas erzähle ich da? - sicher habt Ihr ihn schon, oder? Ist es der da??!", completion = "Vielen Dank, dass Ihr mich befreit habt! Ihr seid meine Nummer eins.\n\n Ich hab's doch gewusst, dass ich mein Leben nicht als Ogerhappen beende!", rewards = nil},
[7441] = {title = "Pusillin und der Älteste Azj'Tordin", objective = "Reist nach Düsterbruch und macht den Dämonen Pusillin ausfindig. Überzeugt ihn mit allen Mitteln davon, Euch Azj'Tordin's Buch der Zauberformeln zu geben.\n\nKehrt mit dem Buch zu Az'Tordin, an Lariss' Pavillon in Feralas, zurück.", description = "Ich habe nur einen Moment nicht aufgepasst, Fremder. In meiner Eile, dem Griff des gefallenen Prinzen zu entkommen, wurde ich ausgeraubt. Ein besonders widerlicher Dämon, namens Pusillin, stahl mir mein Buch der Zauberformeln und den Schlüssel zu den einstmals großen Hallen von Eldre'Thalas.\n\nMein Interesse am Schlüssel ist verloschen als ich meine Unsterblichkeit gegen die Freiheit eingetauscht habe. Doch ich benötige unbedingt mein Buch der Zauberformeln.\n\nFindet den Dämon Pusillin und bringt mir mein Buch.\n\nSucht Pusillin im Wucherborkenviertel von Düsterbruch.", progress = "Ich bereue nichts, Fremder. Die Königin ist schon lange tot. Die Arbeiten der Shen'dralar sind seit langem durch Prinz Tortheldrins Wahnsinn zerstört worden. Ich suche nur noch die Freiheit... Flucht...", completion = "Ihr habt es gefunden! Ich verfluche diesen verdammten Dämonen. Leider sind meine Vorräte fast aufgebraucht. Doch sucht Euch nur etwas von meinen Sachen aus.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFlotte StiefelSprinterschwert\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[7461] = {title = "Der innere Wahnsinn", objective = "Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen.\n\nBetretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten.\n\nKehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück.", description = "Habt Ihr genug gehört? Seid Ihr <ein Mann/eine Frau> der Tat?\n\nDieser Wahnsinn muss ein Ende haben. Das Zeitalter der Unsterblichen ist lange vergangen. Vernichtet die Wächter rings um die Pylonen herum, um das Kraftfeld zu senken. Habt Ihr das erst einmal geschafft, könnt Ihr Immol'thar vernichten. Die Macht des Prinzen wird stark geschwächt sein, greift ihn an und beendet seine Existenz. Gewährt den Geistern dieser Stadt ihre letzte Ruhe, Abenteurer.", progress = "Seid wachsam Abenteurer. Der Prinz ist... überzeugend.", completion = "Ihr seid ein Held, wir sind Euch zu ewigen Dank verpflichtet!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[7462] = {title = "Der Schatz der Shen'dralar", objective = "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!In der Bücherei, dem Athenaeum, werdet Ihr unter dem Treppenaufgang eine uralte Truhe finden. Nehmt Euch aus der Truhe was Ihr wollt.Auf Euch wartet eine dieser Belohnungen:\n\n", description = "In der Bücherei, dem Athenaeum, werdet Ihr unter dem Treppenaufgang eine uralte Truhe finden. Nehmt Euch aus der Truhe was Ihr wollt.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKnochenzermalmerHinterwaldhelmSeggenstiefel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[7463] = {title = "Arcane Erfrischung", objective = "Reist nach Düsterbruch in das Wucherborkenviertel und besiegt den Wasserelementar Hydrobrut. Kehrt anschließend mit der Hydrobrutessenz, zum Hüter des Wissens Lydros im Athenaeum zurück.", description = "Ein <Volk> Magiekundiger! Wie wunderbar. Ich habe jemanden wie Euch schon seit... wie lange ist es nun schon her?... 500 Jahren nicht mehr gesehen!\n\nIch habe da etwas, dass Euren Durst zu löschen vermag, doch zuerst müsst Ihr etwas für mich erledigen.\n\n<Lydros kichert.>\n\nEs gibt eine Anomalie in Eldre'Thalas. Ein Wasserelementar hat sich im östlichen Flügel niedergelassen. Seine Anwesenheit muss unbedingt katalogisiert werden!\n\nReist nach Düsterbruch in das Wucherborkenviertel und sammelt etwas von der elementaren Essenz der Hydrobrut. Bringt Sie anschließend zu mir zurück und ich werde Euch einen äußerst nützlichen Zauberspruch beibringen.", progress = "Ja bitte? Kennen wir uns?", completion = "Wundervoll!...Wer wart Ihr doch gleich nochmal? Ach, ist auch egal. Hmm... Ihr seid ein &lt;Klasse&gt;, also werdet Ihr das hier vielleicht nützlich finden.", rewards = "Ihr erlernt:\n\nWasser herbeizaubern\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWasser herbeizaubern\n\nIhr bekommt außerdem:\n\n"},
[7481] = {title = "Elfische Legenden", objective = "Sucht in Düsterbruch nach Telmius Dreamseeker. Meldet Euch anschließend bei Sage Korolusk in Camp Mojache.", description = "Vor vielen Jahren entkam ein einzelner Elfenmeister namens Telmius Dreamseeker der Vernichtung seines Heimatlandes. Bei sich trug er einige uralte Artefakte der Elfen.\n\nUnsere Suche nach dem verschwundenen Meister führte uns von den Ruinen Quel'Thalas, durch die brennende Steppe, über die großen Weiten der See, hinüber nach Feralas.\n\nWir nehmen an, dass der Elf in den Hallen von Eldre'Thalas, die nun als Düsterbruch bekannt sind, Schutz suchte.\n\nIhr müsst ihn finden, Abenteurer. Ob er nun lebt oder schon lange tot ist, das Wissen, welches er bei sich trug, muss gerettet werden!", progress = nil, completion = "Eine Schande... eine Tragödie. Die Artefakte sind verloren, sagt Ihr? Keine Spur von ihnen, was?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[7482] = {title = "Elfische Legenden", objective = "Sucht in Düsterbruch nach Telmius Dreamseeker. Meldet Euch anschließend bei der Gelehrten Runethorn in Feathermoon.", description = "Vor vielen Jahren entkam ein einzelner Elfenmeister namens Telmius Dreamseeker der Vernichtung seines Heimatlandes. Bei sich trug er einige uralte Artefakte der Elfen.\n\nUnsere Suche nach dem verschwundenen Meister führte uns von den Ruinen Quel'Thalas, durch die brennende Steppe, über die großen Weiten der See, hinüber nach Feralas.\n\nWir nehmen an, dass der Elf in den Hallen von Eldre'Thalas, die nun als Düsterbruch bekannt sind, Schutz suchte.\n\nIhr müsst ihn finden, Abenteurer. Ob er nun lebt oder schon lange tot ist, das Wissen, welches er bei sich trug, muss gerettet werden!", progress = nil, completion = "Eine Schande... eine Tragödie. Die Artefakte sind verloren, sagt Ihr? Keine Spur von ihnen, was?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[7483] = {title = "Buchband der Schnelligkeit", objective = "Bringt ein Buchband der Schnelligkeit, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 2 mal das Blut von Helden, zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum der Schnelligkeit zu erhalten.", description = "Meister Dreamseeker verlor den Buchband der Schnelligkeit im Ostflügel. Mit dem Buchband kann ein Zauber der geringen Hast auf Eure Ausrüstung gewirkt werden. Ein einfacher Trick...\n\nWie auch immer... Falls Ihr Interesse habt, bringt mir den Buchband und einige grundlegende Reagenzien.\n\nHrm... Ich glaube man benötigt das Blut von Helden, einen makellosen schwarzen Diamanten und große glänzende Splitter. Ich mag mich natürlich Irren...\n\n<Lydros zuckt mit den Achseln.>", progress = "Was gibt es? Seht Ihr nicht, dass ich arbeite!", completion = "&lt;Lydros gähnt.&gt;\n\nWie versprochen, das Arkanum der Schnelligkeit. Verbraucht nicht gleich alles auf einmal.\n\n&lt;Lydros kichert.&gt;", rewards = "Ihr bekommt:\n\nArkanum der Schnelligkeit"},
[7484] = {title = "Buchband des Fokus", objective = "Bringt ein Buchband des Fokus, 1 makellosen schwarzen Diamanten, 4 große glänzende Splitter und 2 mal Schattenhaut, zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum des Fokus zu erhalten.", description = "Dieser Buchband erweckte die Neugierde eines jungen Familiars, welcher einem der Hüter gehörte. Das arme Ding wurde nur ein paar Wochen alt\n\nDiejenigen unter Euch, die sich mit Magie beschäftigen, dürften dieser Gegenstand interessieren.\n\nDas Buchband des Fokus ging in diesem Flügel verloren. Ich kann nur annehmen, dass einer der Geister der Hochgeborenen es in Besitz genommen hat.\n\nBringt mir den Buchband, zusammen mit einen makellosen schwarzen Diamanten, einigen großen glänzenden Splittern und etwas Schattenhaut, und ich werde das Arkanum herbeizaubern.", progress = "Ihr nun wieder? Was könntet Ihr jetzt schon wieder wollen?", completion = "Achtet darauf, Euch während der Verzauberung nicht selbst weh zu tun, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\nArkanum des Fokus"},
[7485] = {title = "Buchband des Schutzes", objective = "Bringt ein Buchband des Schutzes, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 1 ausgefranste Monstrositätenstickerei zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum des Schutzes zu erhalten.", description = "Als er von dem Verlust dieses Buchbands hörte, weinte er wie ein kleines Kind. Wohlgemert, Ich selbst habe schon über derartige Verluste getrauert - und kein Verlust wiegt mehr, als der Verlust von Wissen und Geschichte- aber wegen diesem Haufen nutzloser Zauberformeln? Lächerlich! Mir scheint, der Prinz hat ihm wohl einen Gefallen getan, als er Ihm das Fleisch von den Knochen riss.\n\nBringt mir den Buchband, zusammen mit einen makellosen schwarzen Diamanten, einigen großen glänzenden Splittern und eine ausgefranste Monstrositätenstickerei, und ich werde das Arkanum wiederherstellen.\n\nAch ja, sucht im Nordflügel.", progress = "Meine Geduld, verhindert euer Leiden.", completion = "Ja, ja... Beruhigt Euch wieder. Wie versprochen, ist hier Euer Arkanum.", rewards = "Ihr bekommt:\n\nArkanum des Schutzes"},
[7486] = {title = "Die Belohnung eines Helden", objective = "Nehmt Eure Belohnung aus Hydraxis' Kasten.", description = "<Name>, Euer Dienst für die Kriegsherrn hat alles übertroffen, was wir je von den Einwohnern dieser Welt erwartet haben.\n\nWir kennen zwar nicht die Vorstellung Eures Volkes, von Dankbarkeit oder wie Ihr gute Arbeit bei Euch belohnt, aber in diesem Fall...ist eine Belohnung mehr als angebracht.\n\nUnter der Brandung an der südlichen Basis der Insel, findet Ihr einen Kasten. In diesem werdet Ihr Eure... Belohnung finden.\n\nGeht, <Name>. Nehmt Euch Eure Belohnung.", progress = nil, completion = "Hydraxis Stimme erklingt von der Wasseroberfläche aus...\n\n\"Wählt was am besten zu Euch passt, &lt;Name&gt;. Möge es Euch vor den Feinden des Wasserlords schützen.\"", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMeeresbriseGezeitenschleife\n\nIhr bekommt außerdem:\n\n"},
[7487] = {title = "Abstimmung mit dem Kern", objective = "Begebt Euch zum Portal in den Blackrocktiefen, das in den geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Riftwaker am Blackrock zurück.", description = "Risse und Abgründe bilden sich um uns herum und kollabieren wieder, <Volk>. Keine zwei Schritte von mir entfernt, ist ein Riss, der hinab in die tiefsten Tiefen des Blackrock führt, bis in die Ruhestätte des Feuerfürsten.\n\nÜberrascht? Wie bedauerlich... Ihr sterblichen Völker versteht einfach nichts, was Ihr nicht sehen, anfassen oder fühlen könnt.\n\nIch versichere Euch, das Portal ist da und es ist passierbar.\n\nHabe ich Euer Interesse geweckt? Eine Anpassung ist simpel. Begebt Euch in die Blackrocktiefen und findet ein Kernfragment. Bringt es zu mir zurück und ich werde Eure Essenz mit dem Portal abstimmen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEinstimmung auf den Kern\n\nIhr bekommt:\n\n"},
[7488] = {title = "Lethtendris' Netz", objective = "Bringt Lethtendris' Netz zu Latronicus Moonspear in der Festung Feathermoon, in Feralas.", description = "Die Magierin Lethtendris, eine bösartige Blutelfe, deren Brutalität nur durch ihre pervertiere Hingabe zur Magie in den Schatten gestellt wird, ist nach Düsterbruch geflüchtet. Sie hat eine Apparatur entwickelt, ein Netz, um die magischen Energien dieses Ortes einzufangen und wir fürchten, dass wenn Sie niemand aufhält, sie der Welt einen unwiderruflichen Schaden zufügen wird!\n\nStoppt Sie, <Name>. Findet Sie und nehmt das Netz an Euch. Am ehesten werdet Ihr sie nahe den Satyrn, im Wucherborkenviertel von Düsterbruch, finden. Bringt das Netz anschließend zu mir und ich werde versuchen, dessen Kräfte wieder der Wildnis zurückzugeben...", progress = "Habt Ihr das Netz, <Name>?  Seine konzentrierten magischen Energien müssen wieder freigelassen werden!", completion = "Ihr habt also das Netz!  Hervorragende Arbeit, &lt;Name&gt;!  Lethtendris ist, genau wie viele andere ihrer Art, blind für die Gefahren, die der Missbrauch von Magie unserer Welt hinzufügen kann. Sie alle halten sich für Meister der Magie und dabei bemerken sie nicht, wie sie zum Sklaven ihrer eigenen Hingabe werden. Ihr Tod erfüllt mich mit Trauer, aber er war notwendig.\n\nDanke,  &lt;Name&gt;. Ich werde die Energien des Netzes sicher über ein größeres Gebiet freilassen und es anschließend zerstören, um den weiteren Missbrauch seiner Kräfte zu verhindern.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nLehrenspinner"},
[7489] = {title = "Lethtendris' Netz", objective = "Bringt Lethtendris' Netz zu Talo Thornhoof im Camp Mojache in Feralas.", description = "Die Blutelfe Lethtendris hat ihre Grenzen überschritten. So versessen war sie darauf magische Macht zu erlangen, das sie ihre Brüder verraten und eine teuflische Apparatur gebaut hat, ein Netz welches in der Lage ist, die verdorbenen magischen Energien von Düsterbruch einzufangen. Selbst jetzt sammelt sie diese Energien und plant, sie gegen ihre Feinde einzusetzen. \n\nLethtendris muss aufgehalten werden. Sucht sie im Wucherborkenviertel von Düsterbruch, besiegt sie und bringt anschließend ihr Netz zu mir. So kann es vielleicht wieder in die Hände einiger Blutelfen übergeben werden, die dieses Artefakt mit klarem Verstand untersuchen können.", progress = "<Name>, habt Ihr Lethtendris' Netz?", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Dieses Netz enthält in seinem Inneren einen riesigen Vorrat der Magie von Düsterbruch, und ich fürchte um den Schaden, der von jemanden so unverantwortlichen wie Lethtendris angerichtet werden könnte. Ihr Tod erfüllt mich mit Trauer, aber ich weiß, dass sie sich solange sie am Leben war nie freiwillig von ihrem Netz getrennt hätte.\n\nVielen Dank, &lt;Name&gt;. Ich werde das Netz an einige weitaus verantwortungsbewusstere Schüler der Magie übergeben. Sie werden die neuen Wächter seiner Magie sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nLehrenspinner"},
[7490] = {title = "Sieg für die Horde", objective = "Bringt Onyxias Kopf zu Thrall in Orgrimmar.", description = "Ihr habt das Unmögliche vollbracht. Die Brutmutter des schwarzen Drachenschwarms liegt tot zu Euren Füßen. Nehmt ihren Kopf und präsentiert ihn Eurem Kriegshäuptling.", progress = "<Thralls stoische Mine verschwindet für den Bruchteil einer Sekunde, als er den riesigen Kopf von Onyxia erblickt. Beinahe hätte er den mächtigen Doomhammer gezogen.>", completion = "Dies ist ein großartiger Sieg für die Horde, &lt;Name&gt;. So viele male habt Ihr Euren Kriegshäuptling geehrt. Nun ist es an der Zeit, dass der Kriegshäuptling Euch seine Ehre erweist.", rewards = "Ihr bekommt:\n\n"},
[7491] = {title = "Für alle sichtbar", objective = "Sucht Oberanführer Runthak im Tal der Stärke auf.", description = "Oberanführer Runthak erwartet Eure Ankunft im Tal der Stärke.\n\n<Thrall salutiert euch.>\n\nLasst Euer Publikum nicht warten, großer Held.", progress = nil, completion = "Wählt Eure Belohnung und lasst die Feierlichkeiten anlässlich Eures großen Sieges beginnen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTalisman mit OnyxiablutDrachentötersignetZahn Onyxias\n\nIhr bekommt außerdem:\n\n"},
[7492] = {title = "Camp Mojache", objective = "Sprecht mit Talo Thornhoof in Camp Mojache, in Feralas.", description = "Talo Thornhoof, ein Taurenältester in Feralas, hat uns um Hilfe gebeten. Er hat nur wenige Einzelheiten verraten, doch wie es scheint sucht er nach Agenten für eine Angelegenheit, die sowohl heikel als auch dringend ist.\n\nDient der Horde, <Name>.  Begebt Euch ins Camp Mojache in Feralas und sprecht mit Talo.", progress = nil, completion = "Ah, es ist freut mich einen &lt;Klasse&gt; zu sehen, der meinem Ruf gefolgt ist. Ich benötige Eure Dienste, &lt;Name&gt; und ich befürchte, Sie werden euch auf einen gefährlichen Pfad führen... \n\nEinen Pfad nach Düsterbruch.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[7493] = {title = "Die Reise beginnt erst", objective = "Ein Drachentöter und erfahrener Lederer? Ihr erstaunt mich immer wieder. Ich fühle mich geehrt.\n\nBitte akzeptiert, was ich Euch jetzt beibringen werde. Wenn Ihr die letzten Überbleibsel des schwarzen Drachenschwarms vernichtet, wird dieses Wissen von unschätzbarem Wert sein.\n\n Stellt den Umhang aus den Schuppen der Brutmutter her. Er wird Euch und Eure Verbündeten vor dem feurigen Atem des Lords von Blackrock schützen... Nefarian.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMuster: Onyxiaschuppenumhang"},
[7494] = {title = "Die Festung Feathermoon", objective = "Sprecht mit Latronicus Moonspear in der Festung Feathermoon, in Feralas.", description = "<Name>! Man braucht Euch in Feralas!\n\nEine abtrünniger Magierin, Lethtendris, ist in die uralten Elfenruinen von Eldre'thalas, vielen bekannt als Düsterbruch, geflohen. Es wird angenommen, dass Sie einen gefährlichen Gegenstand voller magischer Energien bei sich trägt, der dringend wiederbeschafft werden muss.\n\nLatronicus Moonspear hat Agenten angefordert, die in Düsterbruch eindringen und den Gegenstand von Lethtendris zurückholen sollen.\n\nDient der Allianz! Sucht Latronicus in der Festung Feathermoon, in Feralas auf.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Ich bin erfreut Euch hier zu sehen. Nur schade, dass unser Treffen unter diesen Umständen stattfindet\n\nHört mir genau zu, ich habe eine Aufgabe von größter Wichtigkeit für Euch...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[7495] = {title = "Sieg für die Allianz", objective = "Bringt Onyxias Kopf zu Hochlord Bolvar Fordragon in Stormwind.", description = "Ihr habt das Unmögliche vollbracht. Die Brutmutter des schwarzen Drachenschwarms liegt tot zu Euren Füßen. Nehmt ihren Kopf und präsentiert ihn dem Hochlord.", progress = "Bei Uthers Bart!", completion = "Für so viele Jahre habe ich unter ihrem Bann gestanden. Endlich wurde Gerechtigkeit geübt und die Ehre von Stormwind wieder hergestellt! Heute werden wir diesen glorreichen Sieg feiern!", rewards = "Ihr bekommt:\n\n"},
[7496] = {title = "Gute Zeiten feiern", objective = "Sucht Major Mattingly im Tal der Helden auf.", description = "Sucht Major Mattingly im Tal der Helden auf, <Name>. Er erwartet Euch bereits...", progress = nil, completion = "Nur wenige wurden bisher mit einer solchen Zeremonie geehrt, &lt;Name&gt;. Bitte wählt Eure Belohnung aus, damit wir mit den Feierlichkeiten beginnen können.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTalisman mit OnyxiablutDrachentötersignetZahn Onyxias\n\nIhr bekommt außerdem:\n\n"},
[7497] = {title = "Die Reise beginnt erst", objective = "Ein Drachentöter und erfahrener Lederer? Ihr erstaunt mich immer wieder. Ich fühle mich geehrt.\n\nBitte akzeptiert, was ich Euch jetzt beibringen werde. Wenn Ihr die letzten Überbleibsel des schwarzen Drachenschwarms vernichtet, wird dieses Wissen von unschätzbarem Wert sein.\n\n Stellt den Umhang aus den Schuppen der Brutmutter her. Er wird Euch und Eure Verbündeten vor dem feurigen Atem des Lords von Blackrock schützen... Nefarian.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMuster: Onyxiaschuppenumhang"},
[7498] = {title = "Garona: Eine Studie über Heimlichkeit und Verrat", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, &lt;Volk&gt;. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nKönigliches Siegel von Eldre'Thalas"},
[7499] = {title = "Kodex der Verteidigung", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, &lt;Volk&gt;. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nKönigliches Siegel von Eldre'Thalas"},
