[7674] = {title = "Austausch Eures schwarzen Widders", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchneller brauner WidderSchneller grauer WidderSchneller weißer Widder"},
[7675] = {title = "Eisblauer Roboschreiter-Austausch", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchneller grüner RoboschreiterSchneller weißer RoboschreiterSchneller gelber Roboschreiter"},
