[7826] = {title = "Spendet Wolle", objective = "Wir nehmen zur Zeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung von Orgrimmar einbringen. Unsere Vorräte würden lediglich 60 Stücke Wollstoff von Euch benötigen; mit der Unterstützung anderer sollten wir unsere Sammelaktion dann erfolgreich vervollständigen können.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Wir nehmen zur Zeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung von Orgrimmar einbringen. Unsere Vorräte würden lediglich 60 Stücke Wollstoff von Euch benötigen; mit der Unterstützung anderer sollten wir unsere Sammelaktion dann erfolgreich vervollständigen können.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Fabelhaft! Wir danken Euch für Eure großzügige Spende, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[7827] = {title = "Spendet Seide", objective = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in der Gemeinschaft mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in der Gemeinschaft mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Lasst Euch für Eure großzügige Spende gedankt sein, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[7828] = {title = "Die Pirsch auf die Pirscher", objective = "Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr 15 Silbermähnenpirscher und 15 Silbermähnenheuler tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.\n\nMarkhor erwähnte, dass sich die Wölfe in der Wildnis des Hinterlands verstecken.", description = "Viele mutige Trolle haben wir in der rauhen Wildnis der Hinterlands verloren, <Volk>. Die Silbermähnenwölfe stellen eine der größten Bedrohungen für unsere Jäger dar. Sie lauern versteckt in den Büschen und schlagen zu, sobald sie eine Möglichkeit dazu sehen.\n\nDiese Art von Gewalt wird nicht länger geduldet!\n\nIhr müsst wie die Silbermähnen denken. Lauert den Pirschern auf! Tötet sie alle!", progress = nil, completion = "Ah, gute Arbeit &lt;Volk&gt;. Die Revantusk danken Euch für Euren Beitrag.", rewards = "Ihr bekommt:\n\n"},
[7829] = {title = "Jagt die Wilden", objective = "Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr 20 Wilde Eulenbestien tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.\n\nMarkhor erwähnte, dass sich die Eulenbestien in der Wildnis des Hinterlands befinden.", description = "Unter all den bösartigen Tieren der Wildnis des Hinterlandes, sind auch die Eulenbestien zu finden. Schon so manche gute Krieger der Revantusk verloren wir an die grausamen Krallen und die Schnäbel der Biester.\n\nTötet jede wilde Eulenbestie, die Ihr finden könnt, <Volk>. Kehrt zu mir zurück, sobald Ihr von dem Blutbad genug habt. Euer Beitrag wird dann genau gewogen, abgemessen und bewertet.", progress = nil, completion = "Ihr habt Euch als ein wahrer Revantusk erwiesen, &lt;Name&gt;. Gut gemacht.", rewards = "Ihr bekommt:\n\n"},
[7830] = {title = "Die Gefallenen rächen", objective = "Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr einen Klingenschnabelhimmelsfürsten tötet und dessen Federbusch an Euch nehmt. Kehrt zu ihm zurück sobald Ihr diese Aufgabe erledigt habt.\n\nDie Klingenschnabelhimmelsfürsten sind eine recht seltene Spezies und nisten meist in der Wildnis des Hinterlands.", description = "Dieser Abschaum namens Wildhammer trainiert Greifen, um Trolle abzuschlachten. Schrecklich, Ich weiß, aber sorgt Euch nicht denn ihnen wird bald Gerechtigkeit wiederfahren.\n\nFür den Moment möchte ich, dass Ihr Euch auf die Ausrottung der Greifen in dieser Region konzentriert, die auch als Himmelsfürsten bekannt sind.\n\nTötet einen und bringt mir seinen Federbusch!", progress = "Die Klingenschnabelhimmelsfürsten sind eine recht seltene Greifenspezies: Bekannt für Ihre enorme Fortpflanzungsfähigkeit und mörderische Nachkommen.", completion = "&lt;Markhor untersucht den Federbusch.&gt;\n\nIch frage mich, wieviele unserer Jäger dieses Biest erlegt hat, bevor ihm Gerechtigkeit wiederfuhr.", rewards = "Ihr bekommt:\n\n"},
[7831] = {title = "Spendet Magiestoff", objective = "Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit in Orgrimmar nicht unbeachtet bleiben würde!\n\nWenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit in Orgrimmar nicht unbeachtet bleiben würde!\n\nWenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Wir danken Euch für Eure großzügige Spende, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[7832] = {title = "Noch mehr Runenstoff", objective = "Seid gegrüßt, <Name>! Wir benötigen auch weiterhin noch Runenstoff. Zusätzliche Mittel sind daher jederzeit willkommen, solltet Ihr welche entbehren können. Liefert Ihr uns eine weitere Spende von 20 Stück Runenstoff, so werde ich dafür sorgen, dass Ihr die gebührende Anerkennung für Eure anhaltenden Bemühungen gegenüber Orgrimmar erhaltet.\n\nWann auch immer Ihr die erforderte Menge abgeben könnt, ich werde sie jederzeit entgegennehmen.", description = nil, progress = "Seid gegrüßt, <Name>! Wir benötigen auch weiterhin noch Runenstoff. Zusätzliche Mittel sind daher jederzeit willkommen, solltet Ihr welche entbehren können. Liefert Ihr uns eine weitere Spende von 20 Stück Runenstoff, so werde ich dafür sorgen, dass Ihr die gebührende Anerkennung für Eure anhaltenden Bemühungen gegenüber Orgrimmar erhaltet.\n\nWann auch immer Ihr die erforderte Menge abgeben könnt, ich werde sie jederzeit entgegennehmen.", completion = "&lt;Name&gt; - ohne Helden, die sich wie Ihr für Orgrimmar einsetzen, müssten wir so einiges in Kauf nehmen. Danke für Eure redlichen Bemühungen!", rewards = nil},
[7833] = {title = "Spendet Wolle", objective = "Wir nehmen zur Zeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung der Darkspeartrolle einbringen. Unsere Vorräte würden lediglich 60 Stücke Wollstoff von Euch benötigen; mit der Unterstützung anderer sollten wir unsere Sammelaktion dann erfolgreich vervollständigen können.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Wir nehmen zur Zeit Spenden für Wolle entgegen. Spendet Ihr 60 Stücke, so wird Euch diese großzügige Tat die volle Anerkennung der Darkspeartrolle einbringen. Unsere Vorräte würden lediglich 60 Stücke Wollstoff von Euch benötigen; mit der Unterstützung anderer sollten wir unsere Sammelaktion dann erfolgreich vervollständigen können.\n\nWenn Ihr die 60 Stücke Wollstoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Fabelhaft! Wir danken Euch für Eure großzügige Spende, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[7834] = {title = "Spendet Seide", objective = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in der Gemeinschaft mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Unsere Vorräte an Seide sind, wie fast alle anderen Stoffe auch, so knapp wie nie zuvor. Unterstützen uns noch andere, so bräuchten wir derzeit eine Spende von nicht mehr als 60 Stücken Seide von Euch, um unser Ziel umsetzen zu können.\n\nEine wohlwollende Gabe, sagen wir Seide, könnte Euren hiesigen Ruf in der Gemeinschaft mit Sicherheit verbessern! Wenn Ihr die 60 Stücke Seide bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Lasst Euch für Eure großzügige Spende gedankt sein, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[7835] = {title = "Spendet Magiestoff", objective = "Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit bei den Trollen der Darkspear nicht unbeachtet bleiben würde!\n\nWenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", description = nil, progress = "Unsere Vorräte an Magiestoff gehen zur Neige und wir könnten Eure Hilfe gebrauchen, um unsere Bestände wieder aufzufüllen! Wenn wir uns auf die Gemeinschaft im Ganzen verlassen, bräuchten wir lediglich eine Spende von 60 Stücken Magiestoff von Euch, um unser Ziel umsetzen zu können. Ich versichere Euch, dass eine derartige Großzügigkeit bei den Trollen der Darkspear nicht unbeachtet bleiben würde!\n\nWenn Ihr die 60 Stücke Magiestoff bei Euch habt und zu deren Spende bereit seid, dann kann ich sie jetzt entgegennehmen.", completion = "Wunderbar! Wir danken Euch für Eure großzügige Spende, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[7836] = {title = "Spendet Runenstoff", objective = "<Name>, Ihr wart eine enorme Unterstützung bei unserer Stoffsammelaktion. Da wir sehr hart am Aufstocken unserer Vorräte arbeiten, muss ich Euch wohl auch von unserem neusten und schwerwiegendsten Mangel berichten: Runenstoff. Wir brauchen ihn ganz dringend und hoffen, dass Ihr uns hierbei, wie schon zuvor, wieder unterstützen könnt.\n\nSolltet Ihr gewillt sein, so bringt mir bitte all den Runenstoff, den Ihr entbehren könnt. Für den Anfang wären wir mit 60 Stücken einverstanden, dann sehen wir weiter.", description = nil, progress = "<Name>, Ihr wart eine enorme Unterstützung bei unserer Stoffsammelaktion. Da wir sehr hart am Aufstocken unserer Vorräte arbeiten, muss ich Euch wohl auch von unserem neusten und schwerwiegendsten Mangel berichten: Runenstoff. Wir brauchen ihn ganz dringend und hoffen, dass Ihr uns hierbei, wie schon zuvor, wieder unterstützen könnt.\n\nSolltet Ihr gewillt sein, so bringt mir bitte all den Runenstoff, den Ihr entbehren könnt. Für den Anfang wären wir mit 60 Stücken einverstanden, dann sehen wir weiter.", completion = "Fantastisch - Ich kann Euch versichern, dass wir sofort Gebrauch davon machen werden. Lasst Euch erneut für Eure Mithilfe gedankt sein! Ohne Euch wären wir mit Sicherheit verloren.\n\nDa ihr schon so viel gespendet habt, wäre ich natürlich bereit, mich auch um jede weitere Spende Runenstoff zu kümmern, die Ihr in Zukunft tätigen wollt. Kommt einfach zu mir, ich werde dann persönlich dafür sorgen, dass Eure guten Taten nicht unbeachtet bleiben!", rewards = "Ihr bekommt:\n\n"},
[7837] = {title = "Noch mehr Runenstoff", objective = "Seid gegrüßt, <Name>! Wir benötigen auch weiterhin noch Runenstoff. Zusätzliche Mittel sind daher jederzeit willkommen, solltet Ihr welche entbehren können. Liefert Ihr uns eine weitere Spende von 20 Stück Runenstoff, so werde ich dafür sorgen, dass Ihr die gebührende Anerkennung für Eure anhaltenden Bemühungen gegenüber der Darkspeartrolle erhaltet.\n\nWann auch immer Ihr die erforderte Menge abgeben könnt, ich werde sie jederzeit entgegennehmen.", description = nil, progress = "Seid gegrüßt, <Name>! Wir benötigen auch weiterhin noch Runenstoff. Zusätzliche Mittel sind daher jederzeit willkommen, solltet Ihr welche entbehren können. Liefert Ihr uns eine weitere Spende von 20 Stück Runenstoff, so werde ich dafür sorgen, dass Ihr die gebührende Anerkennung für Eure anhaltenden Bemühungen gegenüber der Darkspeartrolle erhaltet.\n\nWann auch immer Ihr die erforderte Menge abgeben könnt, ich werde sie jederzeit entgegennehmen.", completion = "&lt;Name&gt; - ohne Helden, die sich wie Ihr für die Trolle der Darkspear einsetzen, müssten wir so einiges in Kauf nehmen. Danke für Eure redlichen Bemühungen!", rewards = nil},
[7838] = {title = "Großmeister der Arena", objective = "Aye, Landratte! Bringt mir 12 Schmuckstücke des hiesigen Meisters der Arena und Ihr seid der neue Großmeister der Arena der Gurabashi! Arrrr!", description = nil, progress = "Aye, Landratte! Bringt mir 12 Schmuckstücke des hiesigen Meisters der Arena und Ihr seid der neue Großmeister der Arena der Gurabashi! Arrrr!", completion = "Ihr habt viel Blut in der Arena vergossen! Ich bin stolz darauf, Euch hiermit zum Großmeister der Arena zu ernennen!", rewards = "Ihr bekommt:\n\nGroßmeister der Arena"},
[7839] = {title = "Schläger der Vilebranch", objective = "Schmied Slagtree aus Revantusk im Hinterland möchte, dass Ihr seine verlorenen Werkzeuge ausfindig macht und dann zu ihm zurückkehrt.\n\nIhr erinnert Euch an Schmied Slagtrees Worte, dass die Werkzeuge möglicherweise bei einem der Tempel der Vilebranch zu finden seien, im Nordosten des Hinterlands. Ihr solltet auch Skulk Rock absuchen.", description = "Der Vilebranchabschaum ist in unser Dorf eingedrungen und hat mein Werkzeug gestohlen! Ich habe zwar Ersatz, aber das Set, das sie mir geraubt haben, war das Geschenk eines gutherzigen Gnoms, der mir als junger Orc das Leben gerettet hat.\n\nIch möchte dieses Werkzeug wieder haben, <Name> - es bedeutet mir ungeheuer viel.\n\nMarkhor berichtete, dass die Wekzeuge nahe der Tempel von Agol'watha und Shaol'watha gesichtet wurden.\n\nDiese Tempel liegen im Nordosten des Hinterlands.\n\nFindet meine Werkzeuge!", progress = "Nehmt Euch vor den Trollen der Vilebranch dieser Gegend in Acht, <Name>. Sie sind unbarmherziger, mörderischer Abschaum.", completion = "Mein Werkzeug! Ihr habt es gefunden! Was für ein glorreicher Tag! Ich danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[7840] = {title = "Lards vergessene Brotzeit", objective = "Lard aus Revantusk im Hinterland möchte, dass Ihr Lards Brotzeit wieder findet. Kehrt nach Erfüllung dieser Aufgabe zu ihm zurück.\n\nLard erwähnte, dass er es auf der Insel im Norden vergessen habe. Achtet auf die Trolle der Vilebranch.", description = "Lard Picknick gemacht hat, an geheimen Geheimplatz, als hässlicher, fieser Vilebranch Lard mit großem Stock geschlagen hat. Lard zurück nach Revantusk gerannt sein, aber Lard Brotzeit vergessen hat. Lard hungrig. Ihr vielleicht zurück gehen zu geheimen Geheimplatz und holen Brotzeit von Lard? Lard hat Angst. Gehen Norden! Insel dort im Norden seien geheimer Geheimplatz.", progress = "<Lard streicht sich über seinen riesigen Bauch.>\n\nLard so hungrig.", completion = "&lt;Lard nimmt die riesige Fleischkeule von Euch und stopft sie sich in den Mund.&gt;\n\nErste Sahne! Schön'n Dank.\n\nLard Euch machen tollen Picknickkorb für helfen Lard.", rewards = "Ihr bekommt:\n\nLards besonderer Picknickkorb"},
[7841] = {title = "Eine Botschaft an die Wildhammer", objective = "Otho Moji'ko aus Revantusk im Hinterland möchte, dass Ihr 15 Hochtalkundschafterinnen, 15 Hochtalspäher, 15 Hochtalschützen und 15 Hochtalwaldläuferinnen tötet. Kehrt nach vollendeten Taten zu ihm zurück.\n\nIhr findet die Hochtalelfen bei der Quel'Danil-Hütte im Nordwesten des Hinterlands.", description = "Die Wildhammer fangen Geschäfte mit unseren Feinden an, Mann, schmieden neue Bündnisse. Diesmal sind es die Hochelfen, Mann.\n\n<Otho spuckt.>\n\nWir werden diesen Wildhammer-Zwergen wohl 'ne Botschaft überbringen müssen - 'ne Botschaft geschrieben mit dem Blut unserer Feinde. Tötet alle Hochtalelfen, alle die Euch über den Weg laufen, klar? Un' lasst ihre Leichen als Warnung zurück.\n\nVerscherzt es Euch niemals mit den Trollen!", progress = nil, completion = "Sieht ganz so aus, als ob die Revantusk nun auch neue Verbündete haben, Mann. Ihr wart gründlich.", rewards = "Ihr bekommt:\n\n"},
[7842] = {title = "Eine weitere Botschaft an die Wildhammer", objective = "Otho Moji'ko aus Revantusk im Hinterland möchte, dass Ihr ihm 10 lange elegante Federn von Greifen besorgt, die das Hinterland bewohnen. Kehrt mit den Federn zu ihm zurück.\n\nEs ist bekannt, dass Greifen überall im Hinterland zu finden sind.", description = "Man sagt, dass die Wildhammer den Greifen so nahe stehen wie die Trolle ihren Gefährten. Widerlich, aber wir können das zu unserem Vorteil nutzen, Mann. Wir senden ihnen eine weitere Botschaft.\n\nTötet alle Greifen, die Ihr im Hinterland seht und sammelt ihre Federn ein. Daraus machen wir dann die letzte Botschaft.", progress = "Die letzte Botschaft wird ihnen eine Heidenangst einjagen... oder sie verdammt wütend machen.", completion = "Oh Mann, das wird richtig gut werden. Nur noch ein Schritt und die Wildhammer werden sehen, dass sie es nicht mit den Trollen aufnehmen können!", rewards = "Ihr bekommt:\n\n"},
[7843] = {title = "Die letzte Botschaft an die Wildhammer", objective = "Otho Moji'ko aus Revantusk im Hinterland möchte, dass Ihr zum Aerie Peak im Westen des Hinterlands reist und die letzte Botschaft an die Wildhammer beim Brunnen im Stadtzentrum platziert. Kehrt nach Vollendung der Aufgabe zu ihm zurück.\n\nHütet Euch vor zornigen Wildhammer-Zwergen und niederträchtigen Mitgliedern der Allianz.", description = "<Otho überreicht Euch einen langen, blutverschmierten Speer, den mehrere Greifenfedern umhüllen.>\n\nNehmt den hier, Mann. Geht damit zum Aerie Peak, zum toten Stadtzentrum beim Brunnen. Platziert ihn dort! Rammt ihn richtig in den Boden und zeigt diesen Zwergen, dass die Trolle es ernst meinen! Kommt danach zu mir zurück... hoffentlich noch in einem Stück.", progress = "Was wartet Ihr noch, Mann?", completion = "Ich wünschte, ich wär' dort gewesen, hätt' ihre Gesichter gesehen, Mann. Packen sie zusammen? Hau'n ab?\n\nKlasse Arbeit, &lt;Name&gt;. Wirklich gut. Otho entlohnt Euch mit großem Mojo.", rewards = "Ihr bekommt:\n\nEulenbestienbalg-Handschuhe"},
[7844] = {title = "Kannibalistische Vettern", objective = "Mystikerin Yayo'jin aus Revantusk im Hinterland möchte, dass Ihr 30 Skalpierer der Vilebranch und 15 Sterndeuter der Vilebranch tötet. Kehrt nach Vollendung dieser Aufgabe zu ihr zurück.\n\nYayo'jin deutete an, dass man diese Trolle nahe der Tempel von Shaol'watha und Agol'watha finden könnte. Sie liegen im Nordosten des Hinterlands.", description = "Drei verschiedene Troll-Stämme bewohnen das Hinterland, <Name>. Soviel zu den Gemeinsamkeiten der Stämme: Wir sind alle Trolle und wir leben im Hinterland.\n\nDie Vilebranch sind eine verkommene Bande, die sich an anderen Trollen und Humanoiden nährt.\n\nWäre Zul'jin hier, hätte er sie alle mit einem einzigen Faustschlag niedergeschmettert - ach, Zul'jin ist noch immer nicht zurückgekehrt und wir sind unseren eigenen Mitteln überlassen.\n\nEs liegt nun an Euch diese Gegend zu säubern!", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;. Zul'jin selbst hätte es nicht besser machen können!", rewards = "Ihr bekommt:\n\n"},
[7845] = {title = "Die Entführung des Älteren Torntusk", objective = "Primal Torntusk aus Raventusk im Hinterland möchte, dass Ihr ihren Gefährten, den Älteren Torntusk, aus Jintha'Alor befreit.\n\nMan sagte Euch, dass er hoch oben in Jintha'Alor gefangen gehalten wird - der Hauptstadt der Vilebranch im Süden des Hinterlands.", description = "Mein Gefährte wurde von den wilden Vilebranch bei einem dreisten Überfall um Mitternacht verschleppt. Unsere Spione haben mir berichtet, dass er noch am Leben ist und hoch oben in Jintha'Alor gefangen gehalten wird. Man sagt, dass die üble Priesterin Hexx ihn als Opfer für den gesichtslosen Blutgott Hakkar vorbereiten lässt.\n\nIhr müsst ihn retten, <Name>! Unser Dorf könnte einen so großen Verlust nicht verschmerzen.", progress = nil, completion = "Ihr müsst schnell handeln, &lt;Name&gt;. Eure Anwesenheit hat bestimmt schon die Wachen alarmiert.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[7846] = {title = "Erlangt den Schlüssel!", objective = "Der Ältere Torntusk in Jintha'Alor möchte, dass Ihr Hitah'ya die Bewahrerin tötet, um in den Besitz des Fesselnschlüssels zu kommen. Kehrt zum Älteren Torn'tusk zurück, wenn Ihr den Schlüssel habt.", description = "Der Schlüssel zu meinen Fesseln ist im Besitz von Hitah'ya der Bewahrerin. Sie hält sich in der nahegelegenen Höhle auf. Seid vorsichtig, <Klasse>, sie wird äußerst gut bewacht.\n\nTötet sie und bringt dann den Schlüssel zurück, um meine Fesseln zu öffnen. Erst dann werde ich frei und in der Lage sein, nach Hause zurückzukehren.", progress = "Ihr müsst Euch beeilen!", completion = "Endlich frei! Danke, &lt;Name&gt;. In Revantusk wird man von Euren Taten erzählen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[7847] = {title = "Rückkehr zu Primal Torntusk", objective = "Der Ältere Torntusk in Jintha'Alor möchte, dass Ihr Primal Torntusk in Revantusk die Neuigkeit von seiner Befreiung überbringt.", description = "Kehrt zu meiner Gefährtin Primal Torntusk in Revantusk zurück. Richtet ihr aus, dass ich heimkehren werde! Sie wird Euch sicherlich belohnen.", progress = nil, completion = "Ihr habt den Revantusk einen großen Dienst erwiesen, &lt;Name&gt;! Wir schulden Euch sehr viel Dankbarkeit.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHochlandbogenFläschchen mit Waldmojo\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[7848] = {title = "Abstimmung mit dem Kern", objective = "Begebt Euch zum Portal in den Blackrocktiefen, das in den geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Riftwaker am Blackrock zurück.", description = "Risse und Abgründe bilden sich um uns herum und kollabieren wieder, <Volk>. Keine zwei Schritte von mir entfernt, ist ein Riss, der hinab in die tiefsten Tiefen des Blackrock führt, bis in die Ruhestätte des Feuerfürsten.\n\nÜberrascht? Wie bedauerlich... Ihr sterblichen Völker versteht einfach nichts, was Ihr nicht sehen, anfassen oder fühlen könnt.\n\nIch versichere Euch, das Portal ist da und es ist passierbar.\n\nHabe ich Euer Interesse geweckt? Eine Anpassung ist simpel. Begebt Euch in die Blackrocktiefen und findet ein Kernfragment. Bringt es zu mir zurück und ich werde Eure Essenz mit dem Portal abstimmen.", progress = "Ihr müsst Eure Seele mit dem geschmolzenen Kern abstimmen, bevor Ihr Zugang erhaltet.", completion = "Ich bin jetzt in der Lage, Euch zum geschmolzenen Kern zu transportieren. Ihr braucht nur zu fragen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEinstimmung auf den Kern\n\nIhr bekommt:\n\n"},
[7849] = {title = "Die getrennten Brüder", objective = "Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr die Überreste seines Zwillingsbruders bergt. Findet den Schädel und die Knochen des Jägers Malkhor und bringt sie zu Jäger Markhor zurück.\n\nMarkhor erwähnte, dass die Überreste seines Bruders an die Brühschlammer und Wölfe der Vilebranch verfüttert wurden. Er sagte weiterhin, dass es in Jintha'Alor eine Grube mit Brühschlammern gibt, sowie einen Wolfsbau. Beide liegen in der Nähe der Tempelspitze.", description = "Wie viele in unserem Dorf, habe auch ich einen Nahestehenden verloren. Ach, es war mein Zwillingsbruder Malkhor - er wurde beim selben Überfall wie Torntusks Gefährte von den Vilebranch verschleppt.\n\nDas Schicksal sollte ihn traurigerweise nicht vom Tod verschonen und er wurde schnell und brutal hingerichtet. Seine Überreste wurden an die Brühschlammer und Wölfe der Vilebranch verfüttert.\n\nWir können zwar nicht mehr sein Leben retten, aber es ist noch nicht zu spät, um seine Seele zu befreien. Bergt seine Überreste, <Name>.", progress = "Wenn Ihr seine Überreste geborgen habt, werde ich sie zu Yayo'jin bringen und sie für eine gebührliche Bestattung vorbereiten lassen.", completion = "Mein geliebter Bruder, wie sehr ich dich vermissen werde...\n\nDanke für Eure Hilfe, &lt;Name&gt;. Ihr seid ein wahrer Held für mich.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVersiegelte HolzplattenbeinschienenGrünblatthandlappen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[7850] = {title = "Dunkle Gefäße", objective = "Primal Torntusk aus Revantusk im Hinterland möchte, dass Ihr Euch 10 Gefäße mit besudeltem Blut aus Jintha'Alor beschafft. Kehrt dann damit zu Primal Torntusk zurück.", description = "Die Vilebranch kämpfen mit übernatürlicher Wildheit. Dies liegt an der elenden Magie, die von der üblen Priesterin Hexx gewirkt wird.\n\nIhr werdet in ganz Jintha'Alor dunkle Gefäße mit besudeltem Blut finden. Die Gefäße verstrahlen die elende Magie des gesichtslosen Blutgottes, verleihen den Vilebranch Macht und treiben sie zusätzlich in den Wahnsinn.\n\nStehlt diese Gefäße und bringt sie zu mir, damit ich sie von der Besudelung reinigen und letztendlich die Gewalt des Blutgottes zerschlagen kann.", progress = "Seid beim Kampf mit den Vilebranch auf der Hut, <Name>. Ihre Gedanken sind nicht klar - sie kämpfen bis zum Tod.", completion = "Die dunkle Energie, die die Vilebranch gefügig macht, wurde aufgelöst - für's Erste. Wir müssen bei unserem Kampf gegen das Böse stets wachsam bleiben, denn auch wenn die üble Priesterin vernichtet wurde, so wird doch bald ein anderer ihren Platz einnehmen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nZauberstab des Naturodems"},
[7861] = {title = "GESUCHT: Üble Priesterin Hexx und ihre Diener", objective = "Ihr habt die Anweisung erhalten die üble Priesterin Hexx und 20 Aman'zasiwachen der Vilebranch zu töten. Habt Ihr Eure Aufgabe erfüllt, so sprecht mit Primal Torntusk aus Revantusk im Hinterland.\n\nDie üble Priesterin Hexx und die Aman'zasiwachen halten sich hoch oben in Jintha'Alor im Hinterland auf.", description = "Der üblen Priesterin Hexx und ihren Dienern soll im Namen von Primal Torntusk Gerechtigkeit widerfahren!\n\nWer auch immer die üble Priesterin Hexx und alle ihre Aman'zasiwachen vernichten möge, soll eine bedeutende Entlohnung erhalten.", progress = nil, completion = "Das war in der Tat ein lähmender Schlag für die Vilebranch. Ihr sollt reichlich entlohnt werden, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGewobene EfeuhalsketteUmhang des tiefen Waldlands\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[7862] = {title = "Offener Posten: Wachbefehlshaber von Revantusk", objective = "Ihr wurdet mit der Vernichtung von 20 Berserkern der Vilebranch, 20 Schattenjägern der Vilebranch, 20 Bluttrinkern der Vilebranch und 20 Seelenfressern der Vilebranch beauftragt.\n\nKehrt nach Beendigung dieser Aufgabe zu Primal Torntusk aus Revantusk im Hinterland zurück.", description = "Mit dem Verlust von Malkhor ist auch wieder der Posten des Wachbefehlshabers von Revantusk unbesetzt. Sollte es Euch interessieren Befehlshaber der Wachen von Revantusk zu werden, so erfüllt die folgenden Aufgaben und reicht Eure Bewerbung bei Primal Torntusk ein:\n\nRottet die Berserker der Vilebranch aus.\n\nRottet die Schattenjäger der Vilebranch aus.\n\nRottet die Bluttrinker der Vilebranch aus.\n\nRottet die Seelenfresser der Vilebranch aus.", progress = nil, completion = "Ihr seid wirklich ein würdiger Kandidat für den neuen Posten, &lt;Name&gt;. Nehmt dieses Schmuckstück als Zeichen unserer Anerkennung für Eure harte Arbeit. Ich werde mir sämtliche Bewerbungen nächstes Jahr durchsehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nRune des Wachbefehlshabers"},
[7863] = {title = "Basisüberlebenspaket der Schildwache", objective = "Ihr habt zweifellos begonnen, Euch bei uns als würdig zu erweisen, <Name>. Bitte, nehmt dieses Überlebenspaket als Gegenleistung an! Ihr findet darin Rationen und Verbände, die nur innerhalb der Warsongschlucht verwendet werden können.\n\nBewährt Ihr Euch noch weiter in der Schlucht, werdet Ihr auch mehr dieser Gegenstände erwerben können. Ihr erhaltet die Rationen, wenn unsere Einstellung Euch gegenüber freundlich ist, sowie Verbände, wenn Ihr unser Wohlwollen erlangt habt.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBasisüberlebenspaket der Schildwache"},
[7864] = {title = "Standardüberlebenspaket der Schildwache", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStandardüberlebenspaket der Schildwache"},
