[7870] = {title = "test quest2 - do not use", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7871] = {title = "Besiegt die Eindringlinge!", objective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Warsongschlucht und kehrt zur Schildwache Farsong am Hain der Silverwing zurück.", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, junger <Klasse>. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Warsongschlucht und verteidigt die Feste Silverwing. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, <Name> und ich werde Euch belohnen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7872] = {title = "Besiegt die Eindringlinge!", objective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Warsongschlucht und kehrt zur Schildwache Farsong am Hain der Silverwing zurück.", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, junger <Klasse>. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Warsongschlucht und verteidigt die Feste Silverwing. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, <Name> und ich werde Euch belohnen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7873] = {title = "Besiegt die Eindringlinge!", objective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Warsongschlucht und kehrt zur Schildwache Farsong am Hain der Silverwing zurück.", description = "Jenseits dieses Tunnels werdet Ihr ein Feld des Kampfes und der Aufruhr finden, junger <Klasse>. Die Horde hört nicht auf, unseren heiligen Wald zu roden und benutzt unser immergrünes Blattwerk, um ihre Maschinen anzutreiben.\n\nBetretet die Warsongschlucht und verteidigt die Feste Silverwing. Schlagt die eingefallenen Kräfte der Horde zurück.\n\nEin Erfolg würde Euch ein Verdienstabzeichen einbringen. Bringt mir eines dieser Abzeichen, <Name> und ich werde Euch belohnen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7874] = {title = "Bezwingt die Eindringlinge der Silverwing", objective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Warsongschlucht und kehrt anschließend zu Captain Shatterskull im Mor'shan-Stützpunkt zurück.", description = "Die Wildnis von Ashenvale wird sich der Macht der Horde ergeben, <Volk>. Nichts, was die Silverwing tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silverwing und erlangt ein Ehrenabzeichen der Warsong. Kehrt zu mir zurück <Name>, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7875] = {title = "Bezwingt die Eindringlinge der Silverwing", objective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Warsongschlucht und kehrt anschließend zu Captain Shatterskull im Mor'shan-Stützpunkt zurück.", description = "Die Wildnis von Ashenvale wird sich der Macht der Horde ergeben, <Volk>. Nichts, was die Silverwing tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silverwing und erlangt ein Ehrenabzeichen der Warsong. Kehrt zu mir zurück <Name>, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7876] = {title = "Bezwingt die Eindringlinge der Silverwing", objective = "Betretet die Warsongschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Warsongschlucht und kehrt anschließend zu Captain Shatterskull im Mor'shan-Stützpunkt zurück.", description = "Die Wildnis von Ashenvale wird sich der Macht der Horde ergeben, <Volk>. Nichts, was die Silverwing tun oder sagen, wird uns daran hindern, unseren territorialen Herrschaftsanspruch durchzusetzen. Kalimdor gehört der Horde. Wie können sie es wagen, uns davon abzuhalten, das zu ernten, was rechtens unser ist!\n\nLasst Eure Brust vor Stolz erbeben, während Ihr ihre schwachen Versuche unseren Fortschritt zu behindern, zunichte macht. Zerstört die Schildwachen der Silverwing und erlangt ein Ehrenabzeichen der Warsong. Kehrt zu mir zurück <Name>, wenn Ihr im Besitz eines Ehrenabzeichens seid und ich werde Euch belohnen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7877] = {title = "Der Schatz der Shen'dralar", objective = "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!", description = "In der Bücherei, dem Athenaeum, werdet Ihr unter dem Treppenaufgang eine uralte Truhe finden. Nehmt Euch aus der Truhe was Ihr wollt.", progress = nil, completion = "Ihr öffnet die Truhe und findet...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKnochenzermalmerHinterwaldhelmSeggenstiefel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[7881] = {title = "Jahrmarktsstiefel", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7882] = {title = "Jahrmarktswämser", objective = "Unsere Arbeiter vom Jahrmarkt machen weitaus mehr als Dreck wegzufegen und Bolzen einzuschlagen! Sie helfen auch den Jahrmarkt auf Reisen zu bewachen und benötigen dafür stets robuste und rüstungsstarke Wämser.\n\nWenn Ihr etwas strapazierfähige Rüstung herstellt und zu mir bringt, dann werde ich dies sicherlich an die richtigen Leute weiterleiten. Ich werde Euch im Austausch dafür auch ein paar Lose des Dunkelmond-Jahrmarkts geben.", description = nil, progress = "Unsere Arbeiter vom Jahrmarkt machen weitaus mehr als Dreck wegzufegen und Bolzen einzuschlagen! Sie helfen auch den Jahrmarkt auf Reisen zu bewachen und benötigen dafür stets robuste und rüstungsstarke Wämser.\n\nWenn Ihr etwas strapazierfähige Rüstung herstellt und zu mir bringt, dann werde ich dies sicherlich an die richtigen Leute weiterleiten. Ich werde Euch im Austausch dafür auch ein paar Lose des Dunkelmond-Jahrmarkts geben.", completion = "Ah, Ihr habt die Wämser. Wunderbar. Darf ich fragen welches Tierleder Ihr für die Herstellung verwendet habt? Die Nähte sind erstklassig verarbeitet worden und die Struktur des Leders scheint ebenfalls sehr robust. Ihr seid ein begabter Handwerker!\n\nDankeschön, &lt;Name&gt;, hier sind Eure Lose.", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7883] = {title = "Der größte Gnom der Welt!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7884] = {title = "Der Krokilisken-Junge und der bärtige Murloc", objective = "Yebb arbeitet an einer weiteren Attraktion für sein Kuriositätenkabinett. Es handelt sich dabei um eine nasse und sumpfige Behausung für einen Jungen, der von Krokilisken aufgezogen wurde und vielleicht auch für einen Murloc. Wir werden schöne, wasserdichte Beinkleider brauchen, damit  wir während dem Auf- und Abbauen nicht pitschnass werden. Schildkrötenschuppengamaschen würden sich dafür bestens eignen.\n\n<Name>, könnt Ihr solche für uns anfertigen? Wenn ja, dann wird Euch ein dicker Stapel Lose des Dunkelmond-Jahrmarkts erwarten.", description = nil, progress = "Yebb arbeitet an einer weiteren Attraktion für sein Kuriositätenkabinett. Es handelt sich dabei um eine nasse und sumpfige Behausung für einen Jungen, der von Krokilisken aufgezogen wurde und vielleicht auch für einen Murloc. Wir werden schöne, wasserdichte Beinkleider brauchen, damit  wir während dem Auf- und Abbauen nicht pitschnass werden. Schildkrötenschuppengamaschen würden sich dafür bestens eignen.\n\n<Name>, könnt Ihr solche für uns anfertigen? Wenn ja, dann wird Euch ein dicker Stapel Lose des Dunkelmond-Jahrmarkts erwarten.", completion = "Klasse, Ihr habt sie hergestellt! Die werden ihren Zweck erfüllen... Ich hoffe nur, dass nicht ich es bin, der den Krokiliskenkäfig reinigen darf, wenn es soweit ist. Diese Viecher können ganz schön fies sein, findet Ihr nicht?\n\nHier Eure Lose, &lt;Name&gt;.  Viel Spaß damit und auf dem Jahrmarkt!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7885] = {title = "Rüstungssets", objective = "Es mag Euch vielleicht nicht bewusst sein, aber die Unterhaltung eines fahrenden Jahrmarkts ist kostspielig! Alles nutzt sich so schnell ab, es ist erstaunlich, dass wir überhaupt Gewinne machen.\n\nWegen all dieser versteckten Kosten, suchen wir immer nach Möglichkeiten, wie wir unsere Ausrüstung so günstig wie möglich instandhalten lassen können. Unsere Zelte reißen zum Beispiel regelmäßig, aber ich habe gemerkt, dass Lederrüstungssets gute Flicken abgeben. Könnt Ihr mir ein paar Rüstungssets besorgen? Das würde uns den Kauf von einigen neuen Zelten ersparen! Wenn Ihr uns damit aushelfen könntet, dann würde Euch eine Hand voller Lose des Dunkelmond-Jahrmarkts erwarten...", description = nil, progress = "Es mag Euch vielleicht nicht bewusst sein, aber die Unterhaltung eines fahrenden Jahrmarkts ist kostspielig! Alles nutzt sich so schnell ab, es ist erstaunlich, dass wir überhaupt Gewinne machen.\n\nWegen all dieser versteckten Kosten, suchen wir immer nach Möglichkeiten, wie wir unsere Ausrüstung so günstig wie möglich instandhalten lassen können. Unsere Zelte reißen zum Beispiel regelmäßig, aber ich habe gemerkt, dass Lederrüstungssets gute Flicken abgeben. Könnt Ihr mir ein paar Rüstungssets besorgen? Das würde uns den Kauf von einigen neuen Zelten ersparen! Wenn Ihr uns damit aushelfen könntet, dann würde Euch eine Hand voller Lose des Dunkelmond-Jahrmarkts erwarten...", completion = "Sehr schön! Das wird uns weiterhelfen! Ich habe gerade einen Riss im Zelt dort drüben entdeckt und eines dieser Rüstungssets ist genau das, was ich zum Flicken brauchen kann!\n\nVielen Dank, &lt;Name&gt;. Diese Rüstungssets werden uns eine Menge an Reparaturkosten einsparen. Hier sind die Lose - Ihr habt sie Euch verdient!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7886] = {title = "Verdienstabzeichen", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7887] = {title = "Verdienstabzeichen", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7888] = {title = "Verdienstabzeichen", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7889] = {title = "Grober Gewichtsstein", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7890] = {title = "Schwerer Schleifstein", objective = "Ich würde gerne einen Stab zwischen schweren Schleifsteinen befestigen und ihn dann über meinen Kopf stemmen, um mein Training zu verbessern. Es ist nicht einfach, aber man wird schließlich nicht durch bloßes Herumsitzen zur stärksten Frau der Welt - so wie ich es bin!\n\nKönnt Ihr mir helfen? Ich brauche mehr Schleifsteine - bringt mir ein paar und ich tausche sie gegen Lose des Dunkelmond-Jahrmarkts ein.", description = nil, progress = "Ich würde gerne einen Stab zwischen schweren Schleifsteinen befestigen und ihn dann über meinen Kopf stemmen, um mein Training zu verbessern. Es ist nicht einfach, aber man wird schließlich nicht durch bloßes Herumsitzen zur stärksten Frau der Welt - so wie ich es bin!\n\nKönnt Ihr mir helfen? Ich brauche mehr Schleifsteine - bringt mir ein paar und ich tausche sie gegen Lose des Dunkelmond-Jahrmarkts ein.", completion = "Ihr habt die Steine bekommen! Sie sind auch noch richtig schwer! Ich kann schon fühlen wie meine Muskeln anschwellen.  Danke &lt;Name&gt;!\n\nHier, nehmt diese Lose - und achtet darauf nicht zu viele Süßigkeiten während des Jahrmarkts zu essen. Ein großer starker &lt;Klasse&gt; wie ihr muss sich schließlich kämpferisch in Form halten!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7891] = {title = "Grüne Eisenarmschienen", objective = "Ich arbeite an einem neuen Kostüm für später, wenn ich einmal meinen eigenen Stand als stärkste Frau der Welt habe! Ich suche gerade nach ein paar Armschienen, die ich tragen könnte. Sie dürfen nicht zu viel bedecken, da die Leute meine Muskeln sehen möchten, aber ich möchte trotzdem etwas Farbe ins Spiel bringen, versteht Ihr?\n\nWie wäre es mit grünen Eisenarmschienen, <Name>? Könnt Ihr mir solche herstellen? Wenn ja, dann hätte ich einen ganzen Haufen Lose des Dunkelmond-Jahrmarkts für Euch.", description = nil, progress = "Ich arbeite an einem neuen Kostüm für später, wenn ich einmal meinen eigenen Stand als stärkste Frau der Welt habe! Ich suche gerade nach ein paar Armschienen, die ich tragen könnte. Sie dürfen nicht zu viel bedecken, da die Leute meine Muskeln sehen möchten, aber ich möchte trotzdem etwas Farbe ins Spiel bringen, versteht Ihr?\n\nWie wäre es mit grünen Eisenarmschienen, <Name>? Könnt Ihr mir solche herstellen? Wenn ja, dann hätte ich einen ganzen Haufen Lose des Dunkelmond-Jahrmarkts für Euch.", completion = "Ja! Das sind genau die Richtigen! Sie haben so eine wunderschöne Farbe und lassen meine Arme ausreichend frei, damit man sehen kann wie stark ich bin! Perfekt!\n\nHier, &lt;Name&gt;. Hier sind Eure Lose - amüsiert Euch schön!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7892] = {title = "Großer schwarzer Streitkolben", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7893] = {title = "Rituale der Stärke", objective = "<Name>, in meinem Bestreben die stärkste Frau der Welt zu werden, bin ich auf meinen Reisen bereits weit umher gekommen und habe geheime Trainingstechniken von Gewichthebern, Kraftgurus und uralten Handbüchern erlernt. Ich kenne verbotene Übungen, die  Schwache töten und Unerfahrene verkrüppeln könnten!\n\nDiese Leistung von Stärke und Konditionierung erfordert ein Training mit den schwersten aller Schleifsteine überhaupt. <Name>, könnt Ihr mir diese Steine besorgen oder für mich herstellen? Ich würde Euch dafür auch Lose geben...", description = nil, progress = "<Name>, in meinem Bestreben die stärkste Frau der Welt zu werden, bin ich auf meinen Reisen bereits weit umher gekommen und habe geheime Trainingstechniken von Gewichthebern, Kraftgurus und uralten Handbüchern erlernt. Ich kenne verbotene Übungen, die  Schwache töten und Unerfahrene verkrüppeln könnten!\n\nDiese Leistung von Stärke und Konditionierung erfordert ein Training mit den schwersten aller Schleifsteine überhaupt. <Name>, könnt Ihr mir diese Steine besorgen oder für mich herstellen? Ich würde Euch dafür auch Lose geben...", completion = "Ich danke Euch, &lt;Name&gt;. Ich werde diese Steine bei einem kräftebringenden Ritual verwenden, das ich von einer uralten Schrifttafel im tiefsten Dschungel des Schlingendorntals erlernt habe.\n\nMan sagt, dass derjenige, die das heilige Ritual korrekt ausführt, die Stärke und Ausdauer von zehn Tauren besitzen wird!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7894] = {title = "Kupfermodulator", objective = "Yebb arbeitet an einer neuen Attraktion für das Kuriositätenkabinett, eine, die die Leute vor Verwunderung und Erstaunen begeistern wird! Es wird allerdings eine Menge an Arbeit und bedeuten und viel Material benötigen...\n\nUnter anderem Kupfermodulatoren. Wir brauchen zahlreiche Modulatoren für die mechanischen Teile der Attraktion.  Bringt mir Kupfermodulatoren und ich werde sie gegen ein Los des Dunkelmond-Jahrmarkts einlösen.", description = nil, progress = "Yebb arbeitet an einer neuen Attraktion für das Kuriositätenkabinett, eine, die die Leute vor Verwunderung und Erstaunen begeistern wird! Es wird allerdings eine Menge an Arbeit und bedeuten und viel Material benötigen...\n\nUnter anderem Kupfermodulatoren. Wir brauchen zahlreiche Modulatoren für die mechanischen Teile der Attraktion.  Bringt mir Kupfermodulatoren und ich werde sie gegen ein Los des Dunkelmond-Jahrmarkts einlösen.", completion = "Aha! Die Modulatoren! Herrlich!\n\nIch kann Euch zwar nicht genau sagen an was wir arbeiten, aber dies wird für dessen Konstruktion von unschätzbarem Wert sein. Ich stehe in Eurer Schuld, &lt;Name&gt;, bitte, nehmt dieses Los des Dunkelmond-Jahrmarkts als Zeichen meiner Wertschätzung.", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7895] = {title = "Surrendes bronzenes Dingsda", objective = "Mein neuer Stand wird etwas, das man sehen muss, ja! Etwas, das man sehen muss und... für ein paar Glückliche ist es auch etwas zum Anfassen!\n\nIch kann schon das mechanische Entzücken der surrenden kleinen Dingsdas hören und sehe schon die Kunden vor mir, wie sie näher an meinen Stand treten, um ihre Fähigkeiten zu testen!\n\nAh... jetzt brauche ich die Dingsdas selbst, um meinem Traum ein Stückchen näher zu kommen. Bitte, <Name>, bringt mir surrende bronzene Dingsdas... und ein paar Lose des Dunkelmond-Jahrmarkts werden Euer sein!", description = nil, progress = "Mein neuer Stand wird etwas, das man sehen muss, ja! Etwas, das man sehen muss und... für ein paar Glückliche ist es auch etwas zum Anfassen!\n\nIch kann schon das mechanische Entzücken der surrenden kleinen Dingsdas hören und sehe schon die Kunden vor mir, wie sie näher an meinen Stand treten, um ihre Fähigkeiten zu testen!\n\nAh... jetzt brauche ich die Dingsdas selbst, um meinem Traum ein Stückchen näher zu kommen. Bitte, <Name>, bringt mir surrende bronzene Dingsdas... und ein paar Lose des Dunkelmond-Jahrmarkts werden Euer sein!", completion = "Ihr habt die Dingsdas! Wunderbar! Ich kann schon jetzt das melodische Summen und Surren in meinem Kopf hören! Oh, wenn dieser Stand erst einmal fertig ist, dann wird er ein Weltwunder sein, das mich zeichnen wird!\n\nHier sind Eure Lose, &lt;Name&gt;. Bitte amüsiert Euch auf dem Jahrmarkt!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7896] = {title = "Grünes Feuerwerk", objective = "Wenn ich meinen Stand endlich fertig habe, möchte ich auch dafür werben! Was würde sich dafür schon besser eignen als Feuerwerk?\n\nNun, manch einer würde sagen, dass sich der Geruch eines Kessels, in dem die Köpfe unserer Feinde köcheln, besser zum Anziehen von Massen eignet, aber... wir sind eine gemischte Gesellschaft. Es muss also Feuerwerk sein!\n\nBringt mir grünes Feuerwerk, <Name>, und ich werde Euch eine Hand voller Lose des Dunkelmond-Jahrmarkts geben.", description = nil, progress = "Wenn ich meinen Stand endlich fertig habe, möchte ich auch dafür werben! Was würde sich dafür schon besser eignen als Feuerwerk?\n\nNun, manch einer würde sagen, dass sich der Geruch eines Kessels, in dem die Köpfe unserer Feinde köcheln, besser zum Anziehen von Massen eignet, aber... wir sind eine gemischte Gesellschaft. Es muss also Feuerwerk sein!\n\nBringt mir grünes Feuerwerk, <Name>, und ich werde Euch eine Hand voller Lose des Dunkelmond-Jahrmarkts geben.", completion = "Ihr habt das Feuerwerk. Wunderbare Arbeit, &lt;Name&gt;! Ich kann nicht erwarten es zu zünden und damit allen zu sagen, dass mein Stand eröffnet ist! Ich muss noch warten, sogar noch ziemlich lange fürchte ich, aber... ich werde bereit sein, wenn ich bereit bin, richtig?\n\nHier sind die Lose, &lt;Name&gt;. Viel Spaß!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7897] = {title = "Mechanische Repariersets", objective = "Der hauptsächliche Grund, weshalb ich meinen Stand nicht eröffnen kann, ist... weil alles kaputt ist! Ich brauche mechanische Repariersets, um alles wieder herrichten zu können!\n\nKönnt Ihr mir diese Sets besorgen, <Name>? Ich tausche sie gegen... Sets von Losen des Dunkelmond-Jahrmarkts. Was denkt Ihr?", description = nil, progress = "Der hauptsächliche Grund, weshalb ich meinen Stand nicht eröffnen kann, ist... weil alles kaputt ist! Ich brauche mechanische Repariersets, um alles wieder herrichten zu können!\n\nKönnt Ihr mir diese Sets besorgen, <Name>? Ich tausche sie gegen... Sets von Losen des Dunkelmond-Jahrmarkts. Was denkt Ihr?", completion = "Danke! Jetzt kann ich wieder für Ordnung sorgen.\n\nIch werde eine Menge Repariersets brauchen und oft bis spät in die Nacht arbeiten, um alles wieder zum Laufen bringen zu können.  Manchmal glaube ich, dass es besser wäre, wenn ich wieder zu meinen Wurzeln zurückkehren und meine Laufbahn als Kopfgeldjäger weiterverfolgen würde, aber... der Jahrmarkt tut mir gut.\n\nNehmt diese Lose, &lt;Name&gt;, viel Spaß damit!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7898] = {title = "Thoriumapparat", objective = "Yebb Nebblegear arbeitet wie ich an einer zukünftigen Attraktion. Nebb sagt, dass die Attraktion so aufregend ist, dass es Besucher aus der ganzen Welt anziehen wird...und uns alle sehr, sehr reich!\n\nEr meint, dass er Thoriumapparate für dieses Projekt benötigt und ich soll sie für ihn sammeln. Na, was sagt Ihr; <Name>? Wisst Ihr, wo man Thoriumapparate bekommt? Solltet ihr Ingenieur sein, könntet Ihr dann welche herstellen? Wollt Ihr sie gegen Lose des Dunkelmond-Jahrmarkts einlösen?", description = nil, progress = "Yebb Nebblegear arbeitet wie ich an einer zukünftigen Attraktion. Nebb sagt, dass die Attraktion so aufregend ist, dass es Besucher aus der ganzen Welt anziehen wird...und uns alle sehr, sehr reich!\n\nEr meint, dass er Thoriumapparate für dieses Projekt benötigt und ich soll sie für ihn sammeln. Na, was sagt Ihr; <Name>? Wisst Ihr, wo man Thoriumapparate bekommt? Solltet ihr Ingenieur sein, könntet Ihr dann welche herstellen? Wollt Ihr sie gegen Lose des Dunkelmond-Jahrmarkts einlösen?", completion = "Ah, vielen Dank &lt;Name&gt;! Yebb wird sich über diese Apparate freuen. Ich weiß nicht, was er damit vorhat, aber Yebb ist ein cleverer kleiner Gnom. Er ist clever und vielleicht auch ein bisschen verschlagen...\n\nWenn er doch nur den Geschmack menschlichen Fleisches mögen würde, dann würde er einen großartigen Troll abgeben!\n\nHier &lt;Name&gt;, Geschäft ist Geschäft! Diese Lose gehören Euch.", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7899] = {title = "Kleine pelzige Tatzen", objective = "Will man eine große Masse herbeilocken, sollte man vor allem eines wissen: wie man mit kleinen Anreizen und Krimskrams ihr Interesse weckt! Könnt Ihr mir dabei helfen?\n\nIch brauche kleine pelzige Tatzen, die ich als Preise verwenden kann. Ihr könnt dergleichen von den Katzen des Brachlands oder der Dunkelküste erhalten...\n\nBringt mir ein paar Tatzen und ich tausche sie gegen ein Los des Dunkelmond-Jahrmarkts ein.", description = nil, progress = "Will man eine große Masse herbeilocken, sollte man vor allem eines wissen: wie man mit kleinen Anreizen und Krimskrams ihr Interesse weckt! Könnt Ihr mir dabei helfen?\n\nIch brauche kleine pelzige Tatzen, die ich als Preise verwenden kann. Ihr könnt dergleichen von den Katzen des Brachlands oder der Dunkelküste erhalten...\n\nBringt mir ein paar Tatzen und ich tausche sie gegen ein Los des Dunkelmond-Jahrmarkts ein.", completion = "Großartig, Ihr habt sie! Wir können daraus Spielsachen und anderen Schnickschack herstellen und damit bei mehr und mehr Leuten Interesse für den Jahrmarkt wecken!\n\nHier ist Euer Los, &lt;Name&gt;.  Ihr habt es Euch verdient!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7900] = {title = "Zerrissene Bärenpelze", objective = "Kinder lieben Spielsachen! Egal was für Kinder, ich habe herausgefunden, dass alle Kinder pelzige und kuschelige Spielsachen lieben, die aus zerrissenem Bärenpelz angefertigt wurden!\n\nIhr könnt diese Pelze von Bären aus Ashenvale oder Hillsbrad bekommen.  Bringt mir einen Haufen davon und verdient Euch damit eine Menge Lose des Dunkelmond-Jahrmarkts!", description = nil, progress = "Kinder lieben Spielsachen! Egal was für Kinder, ich habe herausgefunden, dass alle Kinder pelzige und kuschelige Spielsachen lieben, die aus zerrissenem Bärenpelz angefertigt wurden!\n\nIhr könnt diese Pelze von Bären aus Ashenvale oder Hillsbrad bekommen.  Bringt mir einen Haufen davon und verdient Euch damit eine Menge Lose des Dunkelmond-Jahrmarkts!", completion = "Schöne Pelze, &lt;Name&gt;! Ich werde daraus eine Menge Kuscheltiere nähen lassen. Mit Hilfe von etwas Füllmaterial und Farbe, könnte daraus eines der begehrtesten Spielsachen in ganz Azeroth werden!\n\nLose? Ach ja, Euer Entgelt!  Hier sind sie!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7901] = {title = "Weiche buschige Schweife", objective = "Es ist unglaublich was Leute so alles schätzen! Wie wäre es zum Beispiel mit einem Stock, an dem man einen weichen buschigen Schwanz hängt. Ihr und ich mögen nun denken, dass derartiges keinerlei Wert hat... aber verpasst man so einem Quatsch einen netten Namen wie \"Wilder Wuschelschwanz\" und packt das Ganze in eine hübsche Schachtel, dann erscheint es den Leuten plötzlich wertvoll. Aus Tand werden heiß begehrte Objekte!\n\nBesorgt mir ein paar weiche buschige Schwänze von Wölfen aus Desolace und dem Ödland, dann werde ich Euch dafür Lose des Dunkelmond-Jahrmarkts geben.", description = nil, progress = "Es ist unglaublich was Leute so alles schätzen! Wie wäre es zum Beispiel mit einem Stock, an dem man einen weichen buschigen Schwanz hängt. Ihr und ich mögen nun denken, dass derartiges keinerlei Wert hat... aber verpasst man so einem Quatsch einen netten Namen wie \"Wilder Wuschelschwanz\" und packt das Ganze in eine hübsche Schachtel, dann erscheint es den Leuten plötzlich wertvoll. Aus Tand werden heiß begehrte Objekte!\n\nBesorgt mir ein paar weiche buschige Schwänze von Wölfen aus Desolace und dem Ödland, dann werde ich Euch dafür Lose des Dunkelmond-Jahrmarkts geben.", completion = "Gut gemacht, &lt;Name&gt;! Diese buschigen Schwänze werden unseren Besuchern gefallen - und das bedeutet sogleich glückliche Besucher... Besucher, die ihren Freunden vom Jahrmarkt erzählen und somit für noch mehr Publikum sorgen!\n\nHier sind Eure Lose! Viel Spaß auf dem Dunkelmond-Jahrmarkt... und vergesst nicht Euren Freunden von uns zu erzählen!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7902] = {title = "Farbenprächtige Federbüsche", objective = "Das Vorstellungsvermögen einer Person ist etwas Unglaubliches. Es kann aus einem kleinen Hügel einen riesigen Berg machen und aus einem harmlosen Schatten einen furchtbaren Alptraum!\n\nWir vom Dunkelmond-Jahrmarkt erwecken die Fantasien unserer Besucher zum Leben! Allerdings müssen wir uns manchmal schlaue Tricks einfallen lassen, um ihren Vorstellungen etwas auf die Sprünge zu helfen...\n\nIch brauche farbenprächtige Federbüsche für eine meiner Attraktionen. Ihr könnt sie von den Vögeln der etwas gefährlicheren Gegenden Azeroths bekommen. Bringt mir diese Federn und zahlreiche Lose werden Euer Eigen sein!", description = nil, progress = "Das Vorstellungsvermögen einer Person ist etwas Unglaubliches. Es kann aus einem kleinen Hügel einen riesigen Berg machen und aus einem harmlosen Schatten einen furchtbaren Alptraum!\n\nWir vom Dunkelmond-Jahrmarkt erwecken die Fantasien unserer Besucher zum Leben! Allerdings müssen wir uns manchmal schlaue Tricks einfallen lassen, um ihren Vorstellungen etwas auf die Sprünge zu helfen...\n\nIch brauche farbenprächtige Federbüsche für eine meiner Attraktionen. Ihr könnt sie von den Vögeln der etwas gefährlicheren Gegenden Azeroths bekommen. Bringt mir diese Federn und zahlreiche Lose werden Euer Eigen sein!", completion = "Ah, die Federn! Sie sind atemberaubend, findet Ihr nicht! Mit diesen Schönheiten dürfte das Entfachen der Fantasie ein einfaches sein!\n\nIhr leistet so wohltätige Arbeit, &lt;Name&gt;. Das Leuchten in den Augen der Besucher, wenn sie unsere Attraktionen bestaunen, ist bereits ein hoher Lohn, aber bitte, nehmt auch diese Lose.", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7903] = {title = "Böse Fledermausaugen", objective = "Kommt es vor, dass Ihr spät in der Nacht in einer Höhle umherwandert und nach Abenteuern sucht? Ja? Wirklich? Nun, dann habt Ihr die gruseligen Fledermausaugen gesehen, die Euch von hoch oben anstarren und nur darauf warten, dass Ihr unachtsam werdet, damit sie Euch Euer Blut aussaugen können!\n\nEin schauriger Gedanke, nicht wahr? Natürlich - Fledermausaugen sind ohne Frage gruselig!\n\nKönnt Ihr mir ein paar böse Fledermausaugen besorgen, <Name>? Ich brauche sie für... für etwas, das ich entwerfe. Etwas Gruseliges.\n\nIhr könnt sie von den Fledermäusen der östlichen Pestländer bekommen.", description = nil, progress = "Kommt es vor, dass Ihr spät in der Nacht in einer Höhle umherwandert und nach Abenteuern sucht? Ja? Wirklich? Nun, dann habt Ihr die gruseligen Fledermausaugen gesehen, die Euch von hoch oben anstarren und nur darauf warten, dass Ihr unachtsam werdet, damit sie Euch Euer Blut aussaugen können!\n\nEin schauriger Gedanke, nicht wahr? Natürlich - Fledermausaugen sind ohne Frage gruselig!\n\nKönnt Ihr mir ein paar böse Fledermausaugen besorgen, <Name>? Ich brauche sie für... für etwas, das ich entwerfe. Etwas Gruseliges.\n\nIhr könnt sie von den Fledermäusen der östlichen Pestländer bekommen.", completion = "Großartig! Ihr habt die Augen! Ich hoffe die Jagd nach den Fledermäusen war furchterregend für Euch, denn wenn sie einen mutigen &lt;Klasse&gt; wie Ihr es seid ängstigen konnten, dann werden diese Augen ganz sicher auch unseren Jahrmarktsbesuchern einen Schrecken einjagen können.\n\nNehmt diese Lose, &lt;Name&gt;, danke für Eure Dienste.", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7905] = {title = "Der Dunkelmond-Jahrmarkt", objective = "Bringt den Gutschein zu Gelvas Grimgate, der sich innerhalb des Dunkelmond-Jahrmarkts aufhält.", description = "Der Dunkelmond-Jahrmarkt kommt! Lasst Euch beim Besuch in Eurer Stadt nicht all die Wunder und Attraktionen entgehen!\n\nZögert nicht und Ihr werdet diesen Gutschein für kostenfreie Gewinnlose einlösen können! Bringt Euren Gutschein einfach zu Gelvas Grimgate, der sich innerhalb des Jahrmarkts aufhält.\n\nMomentan hat der Jahrmarkt seine Zelte außerhalb von Goldhain im Wald von Elwynn aufgeschlagen. Lasst Euch diese Gelegenheit nicht entgehen! Heute ist Euer Tag!", progress = "Ja, kann ich Euch vielleicht behilflich sein? Habt Ihr einen Gutschein zum Einlösen?", completion = "Willkommen beim Dunkelmond-Jahrmarkt! Dieser Gutschein ist gültig für FÜNF, ja, FÜNF Gewinnlose!\n\nHabt Ihr Gewinnlose angesammelt, dann werdet Ihr mit mir sprechen wollen, um sie gegen wertvolle Preise einzutauschen. Je mehr Lose Ihr bekommt, umso mehr Preise könnt Ihr gewinnen. Huzzah!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7906] = {title = "Dunkelmond-Karten: Bestien", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7907] = {title = "Bestienkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Bestienkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt wo Ihr alle Karten des Bestienkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", progress = "Wie ich sehe habt Ihr es geschafft ein Set der Bestienkarten zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft das Bestienkartenset zu komplettieren. Das Ihr uns die Karten zurückgebt wird ein Band zwischen Euch und denen des Dunkelmonds schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten als Zeichen unserer Dankbarkeit zu schenken.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Blauer Drache"},
[7908] = {title = "Meister der Arena", objective = "Begebt Euch in die Arena des Schlingendorntals und sprecht mit Short John Mithril.\n\nBereitgestellter Gegenstand: \n", description = "Um der Meister der Arena zu werden, bedarf es bestimmt noch weiterer Taten! Vielleicht weiß der Pirat, der das Ereignis in Gurubashi veranstaltet, mehr.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[7921] = {title = "Verdienstabzeichen", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7922] = {title = "Ehrenabzeichen", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7923] = {title = "Ehrenabzeichen", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7924] = {title = "Ehrenabzeichen", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7925] = {title = "Ehrenabzeichen", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[7926] = {title = "Der Dunkelmond-Jahrmarkt", objective = "Bringt den Gutschein zu Gelvas Grimgate, der sich innerhalb des Dunkelmond-Jahrmarkts aufhält.", description = "Der Dunkelmond-Jahrmarkt kommt! Lasst Euch beim Besuch in Eurer Stadt nicht all die Wunder und Attraktionen entgehen!\n\nZögert nicht und Ihr werdet diesen Gutschein für kostenfreie Gewinnlose einlösen können! Bringt Euren Gutschein einfach zu Gelvas Grimgate, der sich innerhalb des Jahrmarkts aufhält.\n\nMomentan hat der Jahrmarkt seine Zelte außerhalb von Thunder Bluff in Mulgore aufgeschlagen. Lasst Euch diese Gelegenheit nicht entgehen! Heute ist Euer Tag!", progress = "Ja, kann ich Euch vielleicht behilflich sein? Habt Ihr einen Gutschein zum Einlösen?", completion = "Willkommen beim Dunkelmond-Jahrmarkt! Dieser Gutschein ist gültig für FÜNF, ja, FÜNF Gewinnlose!\n\nHabt Ihr Gewinnlose angesammelt, dann werdet Ihr mit mir sprechen wollen, um sie gegen wertvolle Preise einzutauschen. Je mehr Lose Ihr bekommt, umso mehr Preise könnt Ihr gewinnen. Huzzah!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7927] = {title = "Portalkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Portalkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt wo Ihr alle Karten des Portalkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Wirbelnder Nether"},
[7928] = {title = "Kriegsherrenkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Kriegsherrenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt wo Ihr alle Karten des Kriegsherrenkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", progress = "Ah, Ihr habt das Kriegsherrenkartenset nun vollständig beisammen! Glückwunsch!", completion = "Ihr habt es also geschafft das Kriegsherrenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Heldentum"},
[7929] = {title = "Elementarkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Elementarkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt wo Ihr alle Karten des Elementarkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", progress = "Ah, Ihr habt das Elementarkartenset nun vollständig beisammen! Glückwunsch!", completion = "Ihr habt es also geschafft das Elementarkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Maelstrom"},
[7930] = {title = "5 Lose - Dunkelmond-Blume", objective = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", description = nil, progress = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", completion = "Bitteschön, bitteschön! Ein passender Preis für einen König!  Meinen Glückwunsch!\n\nSolltet Ihr noch mehr Lose haben, die Ihr einlösen möchtet, dann lasst es mich bitte wissen!  Solange der Dunkelmond-Jahrmarkt hier ist, werde ich Eure Lose entgegennehmen.", rewards = "Ihr bekommt:\n\nDunkelmond-Blume"},
[7931] = {title = "5 Lose - Kleiner Dunkelmond-Preis", objective = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", description = nil, progress = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", completion = "Bitteschön, bitteschön! Ein passender Preis für einen König!  Meinen Glückwunsch!\n\nSolltet Ihr noch mehr Lose haben, die Ihr einlösen möchtet, dann lasst es mich bitte wissen!  Solange der Dunkelmond-Jahrmarkt hier ist, werde ich Eure Lose entgegennehmen.", rewards = "Ihr bekommt:\n\nKleiner Dunkelmond-Preis"},
[7932] = {title = "12 Lose - Geringer Dunkelmond-Preis", objective = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", description = nil, progress = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", completion = "Bitteschön, bitteschön! Ein passender Preis für einen König!  Meinen Glückwunsch!\n\nSolltet Ihr noch mehr Lose haben, die Ihr einlösen möchtet, dann lasst es mich bitte wissen!  Solange der Dunkelmond-Jahrmarkt hier ist, werde ich Eure Lose entgegennehmen.", rewards = "Ihr bekommt:\n\nGeringer Dunkelmond-Preis"},
[7933] = {title = "40 Lose - Großer Dunkelmond-Preis", objective = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", description = nil, progress = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", completion = "Bitteschön, bitteschön! Ein passender Preis für einen König!  Meinen Glückwunsch!\n\nSolltet Ihr noch mehr Lose haben, die Ihr einlösen möchtet, dann lasst es mich bitte wissen!  Solange der Dunkelmond-Jahrmarkt hier ist, werde ich Eure Lose entgegennehmen.", rewards = "Ihr bekommt:\n\nGroßer Dunkelmond-Preis"},
[7934] = {title = "50 Lose - Dunkelmond-Lagerbehälter", objective = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", description = nil, progress = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", completion = "Bitteschön, bitteschön! Ein passender Preis für einen König!  Meinen Glückwunsch!\n\nSolltet Ihr noch mehr Lose haben, die Ihr einlösen möchtet, dann lasst es mich bitte wissen!  Solange der Dunkelmond-Jahrmarkt hier ist, werde ich Eure Lose entgegennehmen.", rewards = "Ihr bekommt:\n\nDunkelmond-Lagerbehälter"},
[7935] = {title = "10 Lose - Hammel des letzten Monats", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHammel des letzten Monats"},
[7936] = {title = "50 Lose - Hammel des letzten Jahres", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHammel des letzten Jahres"},
[7937] = {title = "Euer Schicksal erwartet Euch...", objective = "Reist zum Holzfällerlager des Osttals im Wald von Elwynn und sucht nach Eurem Schicksal.", description = "\"Euer Schicksal erwartet Euch im Osttal.\"\n\nDas Horoskop, das Sayge Euch überreicht hat, fühlt sich beim Berühren leicht warm an. Haltet Ihr es etwas fester in der Hand, so seht Ihr das Holzfällerlager des Osttals im Wald von Elwynn vor Euch. Beim Fokussieren auf dieses Bild, seht Ihr einen Heuhaufen neben einem Stall.", progress = "Dieser Heuhaufen sieht aus wie der aus Eurer Vision.", completion = "Eine rasche Durchsuchung des Heuhaufens bringt eine Schließkassette ans Licht! Es scheint als hättet Ihr Euer Schicksal gefunden!", rewards = "Ihr bekommt:\n\nMysteriöse Schließkassette"},
[7938] = {title = "Euer Schicksal erwartet Euch...", objective = "Reist zu den Todesminen in Westfall und sucht nach Eurem Schicksal.", description = "\"Euer Schicksal erwartet Euch in den Todesminen.\"\n\nDas Horoskop, das Sayge Euch überreicht hat, fühlt sich beim Berühren leicht warm an. Haltet Ihr es etwas fester in der Hand, so seht Ihr die Todesminen in Westfalls Ruinen von Moonbrook. Beim Fokussieren auf dieses Bild, windet Ihr Euch durch verwinkelte Passagen bis Ihr ein schimmerndes Portal erreicht... eines, das in das Herz der Minen selbst führt. Beim Durchschreiten taucht eine seltsame Truhe aus dem Nichts auf.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMysteriöse Schließkassette"},
[7939] = {title = "Mehr verdichtete Schleifsteine", objective = "<Name>, ich danke Euch für all Eure Hilfe. Ich kann Euch wirklich nicht genug danken!\n\nIch brauche jetzt zwar nichts mehr wirklich... aber solltet Ihr mir mehr verdichtete Schleifsteine bringen, so habe ich auch noch einige Lose des Dunkelmond-Jahrmarkts für Euch.", description = nil, progress = "<Name>, ich danke Euch für all Eure Hilfe. Ich kann Euch wirklich nicht genug danken!\n\nIch brauche jetzt zwar nichts mehr wirklich... aber solltet Ihr mir mehr verdichtete Schleifsteine bringen, so habe ich auch noch einige Lose des Dunkelmond-Jahrmarkts für Euch.", completion = "Nochmals danke, &lt;Name&gt;. Viel Spaß mit diesen Losen, und erzählt Euren Freunden vom Dunkelmond-Jahrmarkt!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7940] = {title = "1200 Lose - Kugel des Dunkelmonds", objective = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", description = nil, progress = "Kommt näher, kommt näher! Wenn ihr Lose vom Dunkelmond-Jahrmarkt habt, die ihr einlösen möchtet, dann sagt nur Bescheid! Ihr könnt Lose gegen zahlreiche, wundersame und fantastische Preise einlösen. Scheut euch nicht, probiert es aus!", completion = "Bitteschön, bitteschön! Ein passender Preis für einen König!  Meinen Glückwunsch!\n\nSolltet Ihr noch mehr Lose haben, die Ihr einlösen möchtet, dann lasst es mich bitte wissen!  Solange der Dunkelmond-Jahrmarkt hier ist, werde ich Eure Lose entgegennehmen.", rewards = "Ihr bekommt:\n\nKugel des Dunkelmonds"},
[7941] = {title = "Mehr Rüstungssets", objective = "<Name>, ich muss mich für all Eure Hilfe bedanken. Ich verfüge jetzt über eine Menge an Vorräten, dank Eurer Bemühungen, aber wenn Ihr mir noch mehr Rüstungssets bringen möchtet, dann werde ich sie gerne gegen ein paar Lose des Dunkelmond-Jahrmarkts eintauschen.", description = nil, progress = "<Name>, ich muss mich für all Eure Hilfe bedanken. Ich verfüge jetzt über eine Menge an Vorräten, dank Eurer Bemühungen, aber wenn Ihr mir noch mehr Rüstungssets bringen möchtet, dann werde ich sie gerne gegen ein paar Lose des Dunkelmond-Jahrmarkts eintauschen.", completion = "Hier, &lt;Name&gt;. Ein fairer Tausch. Viel Vergnügen.", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7942] = {title = "Mehr Thoriumapparate", objective = "<Name>, Ihr wart so gut zu uns, indem Ihr uns ohne Unterlass Waren beschafft habt. Ich bin Euch dafür unendlich dankbar!\n\nAuch wenn wir einen nicht mehr so großen Bedarf an Thoriumapparaten wie zuvor haben, so könnt Ihr mir doch jederzeit weitere bringen. Ich tausche sie dann gegen Lose des Dunkelmond-Jahrmarkts ein.", description = nil, progress = "<Name>, Ihr wart so gut zu uns, indem Ihr uns ohne Unterlass Waren beschafft habt. Ich bin Euch dafür unendlich dankbar!\n\nAuch wenn wir einen nicht mehr so großen Bedarf an Thoriumapparaten wie zuvor haben, so könnt Ihr mir doch jederzeit weitere bringen. Ich tausche sie dann gegen Lose des Dunkelmond-Jahrmarkts ein.", completion = "Hier, &lt;Name&gt;. Nehmt diese Lose des Dunkelmond-Jahrmarkts und vergnügt Euch damit. Gebt sie nicht alle auf einmal aus, wie man so schön sagt!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7943] = {title = "Mehr Fledermausaugen", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[7944] = {title = "Euer Schicksal erwartet Euch...", objective = "Reist zu den Höhlen des Wehklagens im Brachland und sucht nach Eurem Schicksal.", description = "\"Euer Schicksal erwartet Euch in den Höhlen des Wehklagens.\"\n\nDas Horoskop, das Sayge Euch überreicht hat, fühlt sich beim Berühren leicht warm an. Haltet Ihr es etwas fester in der Hand, so seht Ihr eine Höhle im Südwesten von Crossroads im Brachland. Beim Fokussieren auf dieses Bild, windet Ihr Euch durch gewundene Passagen bis Ihr ein schimmerndes Portal erreicht... eines, das in das Herz der Höhlen selbst führt. Beim Durchschreiten taucht eine seltsame Truhe aus dem Nichts auf.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMysteriöse Schließkassette"},
[7945] = {title = "Euer Schicksal erwartet Euch...", objective = "Reist zum Bleichmähnenfels in Mulgore und sucht nach Eurem Schicksal.", description = "\"Euer Schicksal erwartet Euch außerhalb des Bleichmähnenfelsens.\"\n\nDas Horoskop, das Sayge Euch überreicht hat, fühlt sich beim Berühren leicht warm an. Haltet Ihr es etwas fester in der Hand, so seht Ihr den Bleichmähnenfels von Mulgore. Beim Fokussieren auf dieses Bild seht Ihr einen Baumstumpf in der Nähe des Höhleneingangs.", progress = "Dieser Baumstumpf sieht aus wie der aus Eurer Vision.", completion = "Eine rasche Untersuchung des Baumstumpfs bringt eine Schließkassette ans Licht! Es scheint als hättet Ihr Euer Schicksal gefunden!", rewards = "Ihr bekommt:\n\nMysteriöse Schließkassette"},
[7946] = {title = "Jubjubs Nachwuchs", objective = "Ich bin so froh, dass Jubjub wieder da ist. Die Kleine liebt Dunkeleisenbier so sehr, dass sie, als mein Vorrat zuneige ging, weggerannt ist, um mehr davon zu suchen.\n\nJetzt, da Jubjub zurück ist, versuche ich, soviel Bier wie möglich zu kriegen! Ich möchte nicht, dass sie wieder wegläuft, wisst Ihr?\n\nHabt Ihr vielleicht etwas Dunkeleisenbier dabei? Wenn ja, gebe ich Euch eines von Jubjubs Froscheiern für einen Krug Dunkeleisenbier...", description = nil, progress = "Ich bin so froh, dass Jubjub wieder da ist. Die Kleine liebt Dunkeleisenbier so sehr, dass sie, als mein Vorrat zuneige ging, weggerannt ist, um mehr davon zu suchen.\n\nJetzt, da Jubjub zurück ist, versuche ich, soviel Bier wie möglich zu kriegen! Ich möchte nicht, dass sie wieder wegläuft, wisst Ihr?\n\nHabt Ihr vielleicht etwas Dunkeleisenbier dabei? Wenn ja, gebe ich Euch eines von Jubjubs Froscheiern für einen Krug Dunkeleisenbier...", completion = "Vielen Dank, &lt;Name&gt;. Hier ist Euer Ei! Es wird noch etwas dauern bevor es ausgebrütet werden kann, doch wenn es soweit ist habt Ihr ein großartiges Haustier!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAbklingzeit für Jubling\n\nIhr bekommt:\n\nUnausgebrütetes Jubling-Ei"},
[7961] = {title = "Waskily Wabbits!", objective = "Kill 5 rabbits and return to Jon LeCraft by the forge on Designer Island.", description = "These rabbits are breeding uncontrollably.  Something must be done!\n\nHelp us <Name>, you're our only hope.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHasenpfoteHasenkäfig (Schneehase)"},
[7962] = {title = "Kaninchenfelle", objective = "Bringt 3 LeCraft-Kaninchenfelle zu Jon LeCraft.", description = "Ich brauche einige LeCraft-Kaninchenfelle. Besorgt mir einige von den LeCrafty-Kaninchen.\n\nEine wichtige Aufgabe!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMal der Wildnis\n\nIhr bekommt:\n\n22-pfündiger Hummer"},
[7981] = {title = "1200 Lose - Amulett des Dunkelmonds", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAmulett des Dunkelmonds"},
