[8041] = {title = "Stärke des Bergs Mugamba", objective = "Seid gegrüßt, <Klasse>. Ich bin Jin'rokh der Zerstörer, Troll von Mugamba. Wir vom Stamm der Zandalar erkennen Eure Leistungen an. Wir begrüßen Eure Hartnäckigkeit und Willenskraft.\n\nTragt diesen Talisman um Euren Hals, <Klasse>. Lasst die Stärke des Bergs Mugamba durch Euch hindurch fließen. Fühlt die Macht, wenn Ihr unsere Feinde niederstreckt!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStärke von Mugamba"},
[8042] = {title = "Stärke des Bergs Mugamba", objective = "Gut zu sehen, dass Ihr wohlauf seid, <Name>. Die glorreichen Schlachten, in denen Ihr Euch geschlagen habt, wirken sich auf das Leben des gesamten Planeten aus. Hakkar darf die Grenzen von Zul'Gurub niemals überschreiten, da die Welt seinem immensen Hunger mit Sicherheit nicht standhalten könnte.\n\nGebt mir Euren Talisman und ich werde seine Stärke noch mächtiger machen. Setzt die Stärke von Mugamba zum Bestrafen unserer Feinde ein!", description = nil, progress = "Gut zu sehen, dass Ihr wohlauf seid, <Name>. Die glorreichen Schlachten, in denen Ihr Euch geschlagen habt, wirken sich auf das Leben des gesamten Planeten aus. Hakkar darf die Grenzen von Zul'Gurub niemals überschreiten, da die Welt seinem immensen Hunger mit Sicherheit nicht standhalten könnte.\n\nGebt mir Euren Talisman und ich werde seine Stärke noch mächtiger machen. Setzt die Stärke von Mugamba zum Bestrafen unserer Feinde ein!", completion = "Unsere Wege werden sich erneut kreuzen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\nStärke von Mugamba"},
[8043] = {title = "Stärke des Bergs Mugamba", objective = "Meister <Name>, Ihr kehrt zurück! Molthor hat bereits Kunde von Euren Taten zum König geschickt. Euer Name ist sogar in den südlichen Meeren bekannt. Vielleicht werdet Ihr eines Tages ein legendärer <Klasse> sein... eine Legende für die Ewigkeit.\n\nGebt mir Euren Talisman, damit ich seine Macht noch einmal verstärken kann.", description = nil, progress = "Meister <Name>, Ihr kehrt zurück! Molthor hat bereits Kunde von Euren Taten zum König geschickt. Euer Name ist sogar in den südlichen Meeren bekannt. Vielleicht werdet Ihr eines Tages ein legendärer <Klasse> sein... eine Legende für die Ewigkeit.\n\nGebt mir Euren Talisman, damit ich seine Macht noch einmal verstärken kann.", completion = "Nutzt Eure wiedererlangte Stärke, um die Gurubashi zu vernichten!", rewards = "Ihr bekommt:\n\nStärke von Mugamba"},
[8044] = {title = "Die Wut Mugambas", objective = "König Rastakhan sendet Euch seine Grüße, Meister <Name>. Eine solche Ehre wurde noch nie jemanden zuteil, der nicht zum Stamm der Zandalar gehört.\n\n\n\nGebt mir Euren Talisman, damit ich ihn noch einmal verstärken kann. Ihr sollt wissen, dass die Wut Mugambas jetzt untrennbar mit Eurer Seele verbunden ist.", description = nil, progress = "König Rastakhan sendet Euch seine Grüße, Meister <Name>. Eine solche Ehre wurde noch nie jemanden zuteil, der nicht zum Stamm der Zandalar gehört.\n\n\n\nGebt mir Euren Talisman, damit ich ihn noch einmal verstärken kann. Ihr sollt wissen, dass die Wut Mugambas jetzt untrennbar mit Eurer Seele verbunden ist.", completion = "Zul'jin würde Euch beneiden, &lt;Klasse&gt;. Zieht hinfort und siegt!", rewards = "Ihr bekommt:\n\nWut Mugambas"},
[8045] = {title = "Das Emblem des Ungläubigen", objective = "Wisset, Ungläubiger: eine Katastrophe hat uns vereint. Eure heidnischen Wege werden von den Zandalarianern weder verstanden, noch geschätzt, aber wir sind ein faires Volk. Tragt dieses Emblem um Euren Hals. Es soll unseren Feinden als Warnung und den Zandalarianern als Zeichen der Freundschaft dienen.\n\nDient auch weiterhin unserem Stamm und ich werde die Macht des Emblems verstärken.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEmblem des Ungläubigen"},
[8046] = {title = "Das Emblem des Ungläubigen", objective = "Ich war vielleicht etwas zu vorschnell mit meinem Urteil, <Klasse>. Es scheint, als wäre Euer blindes Vertrauen in das Licht nach all dem doch noch von Wert.\n\nGebt mir Euer Emblem, damit ich seine Macht verstärken kann.", description = nil, progress = "Ich war vielleicht etwas zu vorschnell mit meinem Urteil, <Klasse>. Es scheint, als wäre Euer blindes Vertrauen in das Licht nach all dem doch noch von Wert.\n\nGebt mir Euer Emblem, damit ich seine Macht verstärken kann.", completion = "Tut, was Ihr tun müsst, um unsere Feinde zu vernichten, &lt;Klasse&gt;. Selbst wenn Ihr dafür das Licht kanalisieren müsst.", rewards = "Ihr bekommt:\n\nEmblem des Ungläubigen"},
[8047] = {title = "Das Emblem des Ungläubigen", objective = "Ich muss gestehen, dass ich nicht daran geglaubt habe, dass Ihr die Entschlossenheit besitzt, um dieser Sache Herr zu werden, <Klasse>. Für Zandalar seid Ihr jetzt ein Verbündeter von unschätzbarem Wert. Gut gemacht, in der Tat.\n\nGebt mir Euer Emblem und und ich werde seine Macht noch einmal verstärken.", description = nil, progress = "Ich muss gestehen, dass ich nicht daran geglaubt habe, dass Ihr die Entschlossenheit besitzt, um dieser Sache Herr zu werden, <Klasse>. Für Zandalar seid Ihr jetzt ein Verbündeter von unschätzbarem Wert. Gut gemacht, in der Tat.\n\nGebt mir Euer Emblem und und ich werde seine Macht noch einmal verstärken.", completion = "Unsere Überzeugungen unterscheiden sich zwar, aber unsere Gründe sind gerechtfertigt. Bezwingt unsere Feinde, edler &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\nEmblem des Ungläubigen"},
[8048] = {title = "Das Emblem des Helden", objective = "Der König nimmt Eure Existenz zur Kenntnis, <Klasse>. Ihr seid der erste Eurer Art, der von Rastakhan als wahrer Verbündeter der Zandalarianer akzeptiert wird.\n\nIhr werdet für Eure Bemühungen reichlich belohnt werden. Zeigt Euer Emblem vor und ich werde auch noch dessen letzte Verstärkung vornehmen.", description = nil, progress = "Der König nimmt Eure Existenz zur Kenntnis, <Klasse>. Ihr seid der erste Eurer Art, der von Rastakhan als wahrer Verbündeter der Zandalarianer akzeptiert wird.\n\nIhr werdet für Eure Bemühungen reichlich belohnt werden. Zeigt Euer Emblem vor und ich werde auch noch dessen letzte Verstärkung vornehmen.", completion = "Wachsamkeit, Ehre, Treue, Mut... Ihr verkörpert alle diese Eigenschaften und so soll es auch Euer Emblem tun.", rewards = "Ihr bekommt:\n\nEmblem des Helden"},
[8049] = {title = "Das Auge von Zuldazar", objective = "Nehmt diesen Talisman als Zeichen unserer Wertschätzung an, <Klasse>.\n\nDas Auge von Zuldazar wird umso mächtiger, je stärker Euer Bund mit den Trollen von Zandalar wird. Kommt von Zeit zu Zeit zu mir zurück und ich werde das Juwel mit Macht erfüllen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nDas Auge von Zuldazar"},
[8050] = {title = "Das Auge von Zuldazar", objective = "Willkommen <Klasse>. Das Auge von Zuldazar pulsiert voller Energie. Ihr seid für die nächste Stufe bereit. Überreicht mir den Talisman, damit ich ihn mit Macht erfüllen kann.", description = nil, progress = "Willkommen <Klasse>. Das Auge von Zuldazar pulsiert voller Energie. Ihr seid für die nächste Stufe bereit. Überreicht mir den Talisman, damit ich ihn mit Macht erfüllen kann.", completion = "Führt Euren Kampf gegen den Seelenschinder und seine Diener fort, &lt;Name&gt;. Er darf die Grenzen Zul'Gurubs niemals überschreiten.", rewards = "Ihr bekommt:\n\nDas Auge von Zuldazar"},
[8051] = {title = "Das Auge von Zuldazar", objective = "Überall verbreiten sich Geschichten von Euren Schlachtzügen gegen die Gurubashi, <Klasse>. Sogar im Königshaus wird jetzt von Euren Heldentaten gesprochen. Man sagt, dass König Rastakhan sogar Euren Namen erwähnt hat.\n\nNun ist es an der Zeit das Auge zu erfüllen. Reicht mir den Talisman und ich werde Euch diesen Dienst erweisen.", description = nil, progress = "Überall verbreiten sich Geschichten von Euren Schlachtzügen gegen die Gurubashi, <Klasse>. Sogar im Königshaus wird jetzt von Euren Heldentaten gesprochen. Man sagt, dass König Rastakhan sogar Euren Namen erwähnt hat.\n\nNun ist es an der Zeit das Auge zu erfüllen. Reicht mir den Talisman und ich werde Euch diesen Dienst erweisen.", completion = "Geht entschlossen bei Euren Bestrebungen vor, &lt;Name&gt;. Der Seelenschinder wird versuchen Euch Euren Lebenswillen zu entziehen.", rewards = "Ihr bekommt:\n\nDas Auge von Zuldazar"},
[8052] = {title = "Das allsehende Auge von Zuldazar", objective = "Wenn wir nur zehntausend mehr wie Euch hätten, <Name>. Die Armeen Hakkars würden in kürzester Zeit niedergeschmettert werden.\n\n\n\nAch, das Auge ist nun für die Erfüllung seines wahren Potentials bereit. Gebt es mir.", description = nil, progress = "Wenn wir nur zehntausend mehr wie Euch hätten, <Name>. Die Armeen Hakkars würden in kürzester Zeit niedergeschmettert werden.\n\n\n\nAch, das Auge ist nun für die Erfüllung seines wahren Potentials bereit. Gebt es mir.", completion = "Tötet sie alle und überlasst Hakkar das Aufräumen...", rewards = "Ihr bekommt:\n\nDas allsehende Auge von Zuldazar"},
[8053] = {title = "Symbole der Macht: Die Armschützer des Freidenkers", objective = "Bringt urzeitliche Hakkaribindungen zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Ihr seid ungläubig. Ungläubige haben einen Platz in unserem Stamm. Ungläubige sind Freidenker der Zandalar. Freidenker fürchten sich nicht vor Unterdrückung und sterben für das, an was sie glauben. Wir wissen, dass Ihr für das, an was Ihr glaubt, sterben würdet. Dies verdient unsere Anerkennung. Ihr dürft Euch uns auch weiterhin als würdig erweisen.\n\nWir brauchen die Symbole der Macht. Geht nach Zul'Gurub. Tötet die Diener Hakkars. Sobald Ihr habt, wonach ich verlange, kommt zu mir zurück. Strebt nach der ersten Kampfausrüstung eines zandalarianischen Freidenkers.\n\nUnd nun geht.", progress = "Ihr seid zurück? Habt Ihr das Symbol der Macht? Wollt Ihr meine Zeit verschwenden?\n\nIch hoffe doch nicht.", completion = "Ihr ehrt uns sehr. Eure Hände sind mit dem Blut der Diener Hakkars befleckt. Ihr seid ein Freund unseres Stammes.\n\nTragt diese Armschienen. Es sind Armschützer des Freidenkers. Das war es, was ich mit wahrer Macht meinte.", rewards = "Ihr bekommt:\n\nZandalarianische Armschützer des Freidenkers"},
[8054] = {title = "Symbole der Macht: Der Gürtel des Freidenkers", objective = "Bringt einen urzeitlichen Hakkarischal zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Eure Überzeugungen sind uns fremd, <Ungläubiger/Ungläubige>. Die Uralten von Zandalar wurden einst als Heiden gebrandmarkt. Dies war in der Zeit als das Imperium der Gurubashi noch mächtig war. Ungläubige wagten es, den Priester Hakkars herauszufordern. Sie wurden daraufhin gejagt und wie Ungeziefer vernichtet. Diese Ungläubigen wankten niemals in ihrem Kampf gegen den Blutgott. Wir wissen den Preis, den sie dafür bezahlen mussten, zu schätzen. Sie sind die Freidenker.\n\nMacht den Dienern Hakkars in Zul'Gurub den Garaus. Bringt mir das Symbol der Macht, nach denen ich verlange. Erfolgreiche Taten sollen großzügig belohnt werden.\n\nUnd nun geht.", progress = "Eure Anwesenheit kündet von Erfolg? Habt Ihr das Symbol? Badet Ihr bereits im Blut Eurer Feinde?", completion = "Das Wohlwollen in unserem Stamm ist Euch sicher. Zahlreiche Tote in Zul'Gurub gehen auf Euer Konto. Viele Feinde wurden von Euch gerichtet.\n\nDies ist der Gürtel des Freidenkers. Er steht für Ehre und ist mächtiges Mojo. Jetzt ist er Euer Eigen.", rewards = "Ihr bekommt:\n\nZandalarianischer Gürtel des Freidenkers"},
[8055] = {title = "Symbole der Macht: Die Brustplatte des Freidenkers", objective = "Bringt einen urzeitlichen Hakkariwappenrock zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Im Stamm verleiht die Kampfausrüstung Macht. Die Freidenker sind auf diese Weise geehrt. Sie sind Zeloten. Sie tränken ihre Brustplatten mit mächtigem Mojo. Wenn ihr Glaube im Angesicht des Feindes zu wanken beginnt, so werden ihre Brustplatten dennoch standhalten.\n\nIhr müsst von uns respektiert werden, um solch eine Brustplatte zu besitzen. Geht nach Zul'Gurub. Ihr müsst das von mir benötigte Symbol der Macht beschaffen. Entwendet es den Narren auf schmerzlichste Art und Weise. Bringt es zu mir. Beweist Euch ein für alle Mal als Freidenker würdig.", progress = "Habt Ihr das Symbol? Es beinhaltet Mojo. Wir müssen es haben. Ihr werdet uns helfen.", completion = "Ihr habt vollbracht, was nur wenige hätten tun können. Ihr habt die Diener Hakkars in die Knie gezwungen. Ihr habt ihnen gezeigt, zu was ein Freidenker fähig ist. Ihr habt uns bewiesen, dass auch ein Ungläubiger in diesem Stamm anerkannt werden kann. Ihr seid mehr als mächtig. Ihr SEID die Macht.\n\nNehmt die Brustplatte, Freidenker. Zerstört diejenigen, die sich Euch in den Weg stellen.", rewards = "Ihr bekommt:\n\nZandalarianische Brustplatte des Freidenkers"},
[8056] = {title = "Symbole der Macht: Die Armschienen des Weissagers", objective = "Bringt urzeitliche Hakkariarmsplinte zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Die Weissager unseres Stammes werden für ihre Gaben der göttlichen Sicht respektiert, ja wirklich. Sie sind nicht etwa eine Art Hexendoktor, nein, sie verbringen ihre Zeit mit dem Beschwören von Knochen oder dem Lesen von Blättern der Einsicht, und nicht mit dem Verhexen anderer. Als Schamane wisst Ihr bereits etwas über die Macht der Weissagung; wir Zandalarianer würdigen die Einsicht, die unserem Stamm gegeben wird.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Helft Ihr uns, werde ich Euch Armschienen geben, die unsere Weissager mehr als alles andere verehren!", progress = "Habt Ihr das von mir benötigte Symbol der Macht von Zul'Gurub? Diese Armschienen sind die Bemühungen Eurerseits wahrlich wert!", completion = "Es scheint als würdet Ihr etwas von der zandalarianischen Weissagung in Euch tragen. Wir wissen von Euren Taten in Zul'Gurub, die Ihr für uns vollbracht habt. Dieses Symbol der Macht wird einen langen Weg gehen, um dem Stamm der Zandalar zu helfen - einem Stamm, wenn ich hinzufügen darf, mit dem Ihr Euch als befreundet betrachten dürft. Nehmt die Armschienen, &lt;Name&gt;; Ihr habt sie Euch verdient!", rewards = "Ihr bekommt:\n\nZandalarianischer Armschienen des Weissagers"},
[8057] = {title = "Symbole der Macht: Die Haruspexarmschienen", objective = "Bringt eine urzeitliche Hakkaristütze zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Ein Haruspex ist ein wichtiges Mitglied in unserem Stamm, ihr tut gut daran auf ihr Omen zu hören. Mittels spiritueller Vereinigung mit den Tieren und deren Opferung, falls nötig, schenken sie uns göttliche Leitung. In der Vergangenheit verschaffte uns die Einsicht und Weisheit der Haruspex einen Vorteil in den Kämpfen gegen die zersplitterten Stämme der Gurubashi.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Solltet Ihr erfolgreich sein, so werde ich Euch mit Armschienen belohnen, die selbst ein Haruspex der Zandalar begehrt.", progress = "Habt Ihr das erforderliche Symbol der Macht von Zul'Gurub beschaffen können? Diese Armschienen sind die Bemühungen mehr als wert, <Name>. Glaubt mir!", completion = "Ah, ich kann die Macht, die von den Symbolen ausgeht, spüren, &lt;Name&gt;. Ihr habt Euch in den Augen des Stammes als jemanden, den man einen \"Freund\" nennt, bewiesen. Geschäft ist Geschäft, &lt;Name&gt;... spürt die Macht der Haruspexarmschienen!", rewards = "Ihr bekommt:\n\nZandalarianische Haruspexarmschienen"},
[8058] = {title = "Symbole der Macht: Die Armschützer des Vollstreckers", objective = "Bringt urzeitliche Hakkariarmsplinte zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Rache ist Macht. Der zandalarianische Vollstrecker ist solch eine Macht. Unser Stamm hat viele Feinde. Der Vollstrecker fordert Vergeltung von ihnen ein. Kein Verbrechen gegen uns bleibt unbestraft und der Vollstrecker sorgt für diese Bestrafung. Unsere Feinde fürchten sich vor unserer Rache. Das sollen sie auch, und sie werden es auch für immer tun.\n\nWerdet einer unserer Vollstrecker. Sucht nach den Symbolen der Macht in Zul'Gurub. Tötet die Diener Hakkars und sorgt im Namen unseres Stammes für Vergeltung. Ihr werdet belohnt werden.", progress = "Habt Ihr das Symbol der Macht bekommen? Wurde im Namen der Zandalar Vergeltung geübt?", completion = "Ihr habt heute ausreichend Rache walten lassen. Ihr habt das Antlitz des Vollstreckers angenommen und die Diener des Blutgottes in die Knie gezwungen.\n\nNehmt dies. Eure Rache wird damit für die Zukunft geschürt. Ihr seid nun ein Freund der Zandalar.", rewards = "Ihr bekommt:\n\nZandalarianische Armschützer des Vollstreckers"},
[8059] = {title = "Symbole der Macht: Die Handlappen des Besessenen", objective = "Bringt eine urzeitliche Hakkaristütze zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Hexenmeister begeben sich bei ihrem Umgang mit Dämonen auf ein gefährliches Terrain, unsere Besessenen gehen jedoch noch einen Schritt weiter. Mit Hilfe eines uralten, arkanen Rituals erlauben sie es einem Dämon, in ihre Gestalt zu schlüpfen. Anstelle von ihm besessen zu werden, versklaven sie den Dämon von innen heraus und absorbieren die Macht des Ungetüms für ihre eigenen Zwecke. Es ist eine Fähigkeit, die nur wenige zu meistern verstehen.\n\nDamit Ihr von der Macht der Besessenen lernen könnt, müsst Ihr mir ein Symbol der Macht von Zul'Gurub beschaffen. Geht und bringt mir, wonach ich verlange.", progress = "Habt Ihr das Symbol der Macht? Indem Ihr die teuflischen Diener Hakkars vernichtet, beweist Ihr Euch nicht nur uns, sondern Ihr zeigt auch Euren Willen, die Wege der Besessenen erlernen zu wollen.", completion = "Gut gemacht... keine Frage, dass die Rückgabe des Symbols der Macht von ihnen mit qualvollen Schmerzen bezahlt werden musste. Nehmt dies - die Handlappen des Besessenen. Hergestellt aus mächtigem Mojo, das bei der Beschwörung der Beute von Besessenen verwendet wurde. Sie sind ein mächtiges Instrument bei dem Erwerb der Macht.", rewards = "Ihr bekommt:\n\nZandalarianische Handlappen des Besessenen"},
[8060] = {title = "Symbole der Macht: Die Handlappen des Illusionisten", objective = "Bringt urzeitliche Hakkaribindungen zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Magier sind in unserem Stamm als Illusionisten bekannt. Sie setzen bei ihren Beschwörungen mächtiges Mojo ein, bringen die Feinde des Stamms oft durcheinander und machen sie konfus!\n\n<Al'tabim lacht gehässig.>\n\nEs ist schon ein ziemliches Spektakel, wenn man einem mächtigen Illusionisten bei der Arbeit zusieht und beobachtet wie er unsere Feinde mit Hilfe ihres eigenen Wahnsinns in die Knie zwingt!\n\nWenn Ihr mehr über den Weg unserer Illusionisten lernen möchtet, dann geht nach Zul'Gurub und bringt ein bestimmtes Symbol der Macht zu mir zurück. Ich werde Euch dafür mit Handlappen belohnen, die unsere Illusionisten zum Weben ihrer Zauber verwenden.", progress = "<Name> - schon wieder zurück? Konntet Ihr das Symbol der Macht, welches ich benötige, beschaffen?", completion = "Beeindruckend... konntet Ihr das Mojo durch diesen Gegenstand fließen spüren? Die Symbole der Macht wurden in den Zeiten, als das Imperium der Gurubashi noch vorherrschte, als eine Art Währung verwendet. Jetzt werden wir Zandalarianer das in ihnen schlummernde latente Mojo nutzen, um die zweite Auferstehung des Blutgottes Hakkar niederzukämpfen!\n\nIhr habt Euch heute tapfer geschlagen - betrachtet Euch als Freund der Zandalarianer. Hier, nehmt die Handlappen des Illusionisten wie versprochen als Belohnung!", rewards = "Ihr bekommt:\n\nZandalarianische Handlappen des Illusionisten"},
[8061] = {title = "Symbole der Macht: Die Handlappen des Glaubenshüters", objective = "Bringt eine urzeitliche Hakkaristütze zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Wir Zandalarianer investieren Macht in diejenigen, die mit der Gewalt des Göttlichen sprechen. Unsere Priester sind mehr als nur Heiler; sie sind auch unsere Hüter des Glaubens. Das Böse kommt von äußeren Bedrohungen, wie zum Beispiel Hakkar, wie auch von innerhalb des Stammes. Unsere Glaubenshüter agieren wie die Richter unter uns, sie schützen uns vor dem gleichen Übel, das bereits die Gurubashi sich selbst hat zerstören lassen.\n\nGeht nach Zul'Gurub und bringt die Symbole der Macht von den Gurubashi zurück. Lernt, was es heißt, ein Glaubenshüter zu sein, und schützt uns vor dem Bösen.", progress = "Zurück von Zul'Gurub, ja? Wart Ihr bei der Wiederbeschaffung des Symbols der Macht von den Dienern Hakkars erfolgreich?", completion = "Hervorragend, &lt;Name&gt;! Diese Aufgabe war nicht gerade eine Kleinigkeit. Es besteht kein Zweifel daran, dass Ihr heute wie einer unserer Glaubenshüter gehandelt habt und uns somit vor der Bedrohung Hakkars beschützt habt. Diese Handlappen sind für einen Freund des Stammes, so wie Ihr einer seid, nur angemessen!", rewards = "Ihr bekommt:\n\nZandalarianische Handlappen des Glaubenshüters"},
[8062] = {title = "Symbole der Macht: Die Armschienen des Raubtiers", objective = "Bringt das folgende Symbol der Macht aus Zul'Gurub zu Falthir dem Blinden: Urzeitliche Hakkaribindungen. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "In den dunklen Zeiten nach dem Fall des Imperiums der Gurubashi, setzten die zandalarianischen Jäger ihre Tapferkeit ein, um den Lebensunterhalt für den Stamm zu sichern. Man vergleicht sich gerne mit den Jägern unseres Stammes: das Streben nach der Jagd bedeutet das Einswerden mit der Essenz des Jägers, ja. Eure Jagd in Zul'Gurub wird uns zeigen, in welchem Verhältnis Ihr zu unseren besten Jägern steht.\n\nBringt mir ein Muster der Symbole der Macht aus Zul'Gurub. Ihr werdet damit Eure ersten Schritte tun, die es zum Werden des vorletzten Jägers braucht.", progress = "Jagt in Zul'Gurub nach denjenigen, die im Besitz eines Symbols der Macht sein könnten, <Name>. Sie sind Eure Beute; sie besitzen das, nach dem wir beide verlangen.", completion = "Ja... ich brauche kein Augenlicht, um die Anwesenheit eines Symbols der Macht zu spüren. Euer Erfolg in Zul'Gurub hat viele in unserem Stamm beeindruckt. Wir betrachten Euch nicht nur als einen Freund der Zandalar, sondern auch als würdig genug die Raubtierarmschienen zu besitzen, einen mächtigen Gegenstand und ein Symbol dessen, was es bedeutet ein &lt;Klasse&gt; zu sein. Gut gemacht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nZandalarianische Armschienen des Raubtiers"},
[8063] = {title = "Symbole der Macht: Die Armschienen des Wildfangs", objective = "Bringt urzeitliche Hakkariarmsplinte zu Falthir dem Blinden. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Die Wildfänge von Zandalar ähneln den Schurken, vertraut sind sie vor allem aber mit dem Wahnsinn... dem Chaos... der Unberechenbarkeit des Lebens. Als unvergesslicher Anblick des Terrors auf dem Schlachtfeld, säten sie in den wilden Zeiten nach Aufsplittung der Stämme Verwirrung und Chaos unter unseren Feinden. Ohne sie, würde es uns heute nicht geben.\n\nBringt mir das gewünschte Symbol der Macht von Zul'Gurub und ich werde Euch mit den so begehrten Armschienen des Wildfangs belohnen. Gebt Euch dem Wahnsinn hin!", progress = "Sucht nach dem Wahnsinn aus Zul'Gurub und überschattet ihn mit Eurem eigenen, <Name>! Diese Tat bedeutet Erfolg und Erfolg bedeutet Belohnung! Überlasst dem Blutgott nicht wieder die totale Herrschaft!", completion = "Sehr schön, &lt;Name&gt;... mit Euren Leistungen in Zul'Gurub habt Ihr Euch das Recht verdient, den Stamm der Zandalar Euren Freund nennen zu dürfen. Ich werde mich um die Symbole kümmern; nehmt diese Belohnung bitte als Dank für Eure Bemühungen an!", rewards = "Ihr bekommt:\n\nZandalarianische Armschienen des Wildfangs"},
[8064] = {title = "Symbole der Macht: Der Haruspexgürtel", objective = "Bringt eine urzeitliche Hakkarischärpe zu Maywiki von Zuldazar. Maywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal. Die Einstellung des Stammes der Zandalar muss Euch gegenüber außerdem wohlwollend sein.", description = "Die Zandalar kennen die Wege der Druiden nicht; die Natur soll nach unseren Bedürfnissen geformt werden und nicht umgekehrt. Dennoch gehören die Haruspex zu denen, die am meisten mit der Natur im Einklang leben, und das mit Recht. Den Geist eines Wildtiers zu opfern, bedeutet zu wissen, wie es ist einer von ihnen zu sein. Das ist die wahre Macht der Natur.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Solltet Ihr erfolgreich sein, so werde ich Euch mit einem mächtigen Gegenstand belohnen: einem Gürtel, wie ihn viele Haruspex der Zandalar verwenden.\n\nStarkes Mojo, ja!", progress = "Habt Ihr das erforderliche Symbol der Macht von Zul'Gurub beschaffen können? Wenn ja, so wird der Haruspexgürtel Euer Eigen sein.", completion = "Ich danke Euch - die latente Macht in diesem Gegenstand ist der eigentliche Schatz in ihm selbst, darauf könnt Ihr Gift nehmen. Ihr habt nicht nur das erforderliche Symbol der Macht erfolgreich beschafft, ihr habt Euch auch bei unserem Stamm als ehrbar erwiesen. Hier, nehmt wie versprochen Eure Belohnung!", rewards = "Ihr bekommt:\n\nZandalarianischer Haruspexgürtel"},
[8065] = {title = "Symbole der Macht: Die Haruspextunika", objective = "Bringt einen urzeitlichen Hakkariwaffenrock zu Maywiki von Zuldazar. Maywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal. Die Einstellung des Stammes der Zandalar muss Euch gegenüber außerdem respektvoll sein.", description = "Das ultimative Symbol der Macht eines Haruspex ist die Kleidung, die er trägt, <Name>. Die Tunika symbolisiert die Verbindung zwischen ihnen selbst und der göttlichen Weisheit, nach der sie streben. Oft werden in die Tunika Teile der geopferten Tiere eingewoben, die sie an die Verbundenheit mit deren Talenten erinnern.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Solltet Ihr erfolgreich sein, so wird Euch eine wie von mir beschriebene Tunika gehören.", progress = "Habt Ihr das erforderliche Symbol der Macht von Zul'Gurub beschaffen können? Die Haruspextunika ist jede Mühe, die Ihr dafür erbringen müsst, wert.", completion = "Beeindruckend... Ihr habt das erforderliche Symbol der Macht erfolgreich beschafft, &lt;Name&gt;. Eure vollbrachten Taten in Zul'Gurub im Namen der Zandalar sind sagenhaft; von nun an werdet Ihr in unserem Stamm angesehen werden. Hier ist Eure Tunika, mächtiger &lt;Klasse&gt;!", rewards = "Ihr bekommt:\n\nZandalarianische Haruspextunika"},
[8066] = {title = "Symbole der Macht: Der Gürtel des Raubtiers", objective = "Bringt das folgende Symbol der Macht aus Zul'Gurub zu Falthir dem Blinden: Einen urzeitlichen Hakkarischal. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Ein Raubtier weiß, wie es sich an seine Beute heranschleicht, ein erfolgreiches Raubtier weiß aber auch, wie es seine Beute schlägt, sobald es zu ihr aufgeschlossen hat. Ihr müsst beides beherrschen, wenn Ihr in Zul'Gurub erfolgreich sein wollt... und wenn Ihr Euch mit den Jägern der Zandalar vergleichen wollt.\n\nBringt mir ein ausgesuchtes Teil der Symbole der Macht aus Zul'Gurub. Meine Belohnung wird die Macht sein, die diese Schmuckstücke enthalten, Eure wird dagegen der zandalarianische Gürtel des Raubtiers sein, ein Gegenstand, der den Tausch sehr wohl wert ist, glaubt mir.", progress = "Vernichtet die verrückten Diener Hakkars in Zul'Gurub - sie sind es, die im Besitz der Symbole der Macht sind, <Name>. Beweist ihnen und dem Stamm Eure Überlegenheit als hoffnungsvoller <Klasse>.", completion = "Ich habe Euer Kommen bereits gespürt, &lt;Name&gt;, wenn auch beschwerlich. Was Euch verraten hat, war das Symbol der Macht, welches Ihr bei Euch tragt. Ich muss es nicht einmal sehen, ich kann seine Macht spüren; das in ihm ruhende Mojo - rohe Magie, könnte man sagen - schürt auch weiterhin unser Streben nach Vereitelung der teuflischen Pläne des Blugottes Hakkar an.\n\nMan kann Euch weiterempfehlen, und für Euren Erfolg belohnen. Im Stamm sieht man Euch mit Wohlwollen entgegen, ebenso verdient Ihr es, den Raubtiergürtel zu tragen.", rewards = "Ihr bekommt:\n\nZandalarianischer Gürtel des Raubtiers"},
[8067] = {title = "Symbole der Macht: Der Mantel des Raubtiers", objective = "Bringt das folgende Symbol der Macht aus Zul'Gurub zu Falthir dem Blinden: Eine urzeitliche Aegis der Hakkari. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Wir Zandalarianer schätzen unsere Kleidung als eine Art Symbol für vollbrachte Taten. Man muss nicht sehen können, was jemand trägt, um zu spüren, was davon ausgeht. Macht geht über die Sicht hinaus. Die Bekleidung zandalarianischer Jäger ist von dieser Art, und der wohl am meisten verehrte Teil davon ist der Mantel, den sie tragen. Er hilft ihnen ihr Erscheinungsbild zu verschleiern... und ihre Gegenwart dann bekannt zu geben, wenn sie es möchten.\n\nDie Symbole der Macht warten in Zul'Gurub darauf, von Euch zurückerobert zu werden. Bringt mir, nach was ich verlange, und der Mantel des Raubtiers soll Euer Eigen sein.", progress = "War Euer Anschlag auf Zul'Gurub erfolgreich, <Name>? Nur wenn Ihr mir gebracht habt, wonach ich verlange und Ihr Euch dem Stamm ganz und gar würdig erwiesen habt, werdet Ihr den Mantel erhalten, der wie kein anderer der Zandalarianer ist.", completion = "Erfolg... Ihr werdet vom Stamm respektiert werden, &lt;Name&gt;. Die Beschaffung des Symbols der Macht, welches für den Mantel von Nöten ist, war eine waghalsige Leistung, die Ihr auf tödlichste Art und Weise unserer &lt;Klasse&gt; gemeistert habt. Ihr habt Euch Euren Platz unter ihresgleichen verdient und sicherlich auch das Recht, ihren Mantel tragen zu dürfen.", rewards = "Ihr bekommt:\n\nZandalarianischer Mantel des Raubtiers"},
[8068] = {title = "Symbole der Macht: Der Mantel des Illusionisten", objective = "Bringt einen urzeitlichen Hakkarischal zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Magie ist eine rohe, uralte Kraft, die von denen beherrscht werden muss, die stark genug dafür sind. Mojo ist unsere Ausdehnung dieser Macht; eine der mächtigsten Manipulationen davon ist die Form der Illusion. Wie kann man sich ernsthaft erhoffen einen Feind zu schlagen, der nicht einmal wirklich da ist? Wir Zandalarianer wissen von dieser Macht und daher wird den Illusionisten eine besondere Stellung in unserem Stamm zuteil.\n\nBeschafft das notwendige Symbol der Macht von Zul'Gurub... dafür werdet Ihr mit dem Wohlwollen unseres Stammes und einem mächtigen Mantel, wie er von unseren besten Illusionisten verwendet wird, belohnt werden!", progress = "Wie war Euer Ausflug nach Zul'Gurub? Habt Ihr Eure Feinde mit der Macht der Illusion in den Wahnsinn getrieben? Illusion ja oder nein, ihr Tod - und die von ihnen wiedererlangten Symbole der Macht - werden die Auferstehung Hakkars vereiteln.", completion = "Erfolg! Man wird Euch von jetzt an in unserem Stamm mit Wohlwollen entgegenkommen! Zul'Gurub hat heute mit Sicherheit die Macht der Zandalarianer zu spüren bekommen, dank Euch, &lt;Name&gt;.\n\nIhr habt den Segen unseres Stammes, bitte nehmt den zandalarianischen Mantel des Illusionisten. Möge er Euch gut dienen.", rewards = "Ihr bekommt:\n\nZandalarianischer Mantel des Illusionisten"},
[8069] = {title = "Symbole der Macht: Die Roben des Illusionisten", objective = "Bringt einen urzeitlichen Hakkarikosak Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Im Stamm wird Stellung und Macht durch das ausgezeichnet, was man trägt. Unsere Kleidung wird aus den feinsten Materialien hergestellt und mit Mojo verwoben, mit dessen Hilfe wir uns Macht verleihen. Illusionisten sind keine Ausnahme; man sagt, dass ihre Roben mittels ihres Aussehens die Essenz der Illusion verkörpern. Legenden besagen, dass ihre uralten Roben niemals gleich aussahen.\n\nIch werde Euch die Robe eines Illusionisten geben, <Name>... aber zuerst müsst Ihr Euch in unserem Stamm Respekt verdienen! Bringt mir ein Symbol der Macht von Zul'Gurub!", progress = "Seid Ihr mit dem Symbol der Macht, das wir benötigen, zurückgekehrt? Ich weiß, dass es nicht einfach sein wird... aber ich habe schon seit langem prophezeit, dass ein Außenseiter kommen würde und uns bei unserem Kampf gegen Hakkar zur Seite stehen würde. Ich denke Ihr solltet es sein!", completion = "Wenigsten jemand, der würdig ist die Robe des Illusionisten zu tragen! Euer Erfolg in Zul'Gurub hat Euch für alle Zeit Respekt von unserem Stamm eingebracht. Tragt sie mit Stolz, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nZandalarianische Robe des Illusionisten"},
[8070] = {title = "Symbole der Macht: Die Bindungen des Glaubenshüters", objective = "Bringt eine urzeitliche Hakkarischärpe zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Kurze Zeit nach dem Fall der Gurubashi wurden wir Zandalarianer fast endgültig vom Bösen innerhalb unseres Stammes besiegt. Es war zu dieser Zeit, dass die Glaubenshüter unter uns hervorkamen, um den Stamm zu schützen und diejenigen dabei zu verbannen, die unsereins zu zerstören gedachten. Sie erhalten nicht nur den Einklang zwischen uns und den Geistern, sie erhalten auch unsere Hülle.\n\nReist weit nach Zul'Gurub und werdet selbst Zeuge von der Verdorbenheit Hakkars und der der Gurubashi. Entringt ihnen die Symbole der Macht, nach denen wir suchen, und Euer Erfolg soll belohnt werden!", progress = "Das Symbol der Macht... Habt Ihr es? Nur wenn wir es haben, werden wir in der Lage sein, die in ihm schlummernde, latente Macht zu nutzen. Es wird nur gut sein den Spieß für die Diener des Blutgottes einmal umzudrehen...", completion = "Erfolg! Es wird noch eine Zeit brauchen, um Macht gegen die Auferstehung Hakkars aufzubauen. Mit Eurer Hilfe konnten wir einen ausschlaggebenden Schritt vorangehen und somit sicherstellen, dass der Blutgott uns nicht alle zerstören wird.\n\nIhr habt Euch heute das Wohlwollen unseres Stammes verdient, &lt;Name&gt;. Nehmt dies hier, die Bindungen des Glaubenshüters, als Zeichen unseres Dankes.", rewards = "Ihr bekommt:\n\nZandalarianische Bindungen des Glaubenshüters"},
[8071] = {title = "Symbole der Macht: Der Mantel des Glaubenshüters", objective = "Bringt eine urzeitliche Aegis der Hakkari zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Alle Glaubenshüter der Zandalar tragen einen bestimmten Mantel, der sie als Beschützer des Stammes auszeichnet. Diese Mäntel werden aus mächtigem Mojo gewoben, das beim Beurteilen derjenigen behilflich ist, die eine Bedrohung für unseren Stamm darstellen. Auch Ihr müsst als Priester Zeit aufwenden, um zu beurteilen, wer würdig ist und wer nicht; ein solcher Mantel wäre zweifellos ein Segen für Euch.\n\nWenn Ihr Hakkars Diener in Zul'Gurub besiegt und mir das benötigte Symbol der Macht besorgt, werde ich Euch im Austausch dafür einen Mantel geben, der unter unseren Glaubenshütern als hoch und heilig gilt.", progress = "Habt Ihr das Symbol der Macht von Zul'Gurub?", completion = "Gut gemacht, &lt;Name&gt; - die Diener Hakkars haben heute dank Euch zweifellos die Vergeltung der Zandalarianer zu spüren bekommen. Eure Taten haben Euch auf Dauer zu Respekt in unserem Stamm verholfen. Ihr habt unseren Segen, betrachtet den Mantel des Glaubenshüters bitte als den Eurigen!", rewards = "Ihr bekommt:\n\nZandalarianischer Mantel des Glaubenshüters"},
[8072] = {title = "Symbole der Macht: Der Mantel des Wildfangs", objective = "Bringt einen urzeitlichen Hakkarigurt zu Falthir dem Blinden. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Khar'vaxal der Irrsinnige war einer der legendären Wildfänge der Zandalar. Legenden zufolge benutze er seinen Mantel, der speziell aus \"Stoff des Wahnsinns\" gewoben wurde, als er den Feinden des Stammes zum ersten Mal gegenübertrat. Seine Gestalt wurde nicht nur von dem Mantel, sondern auch dank der blendenden Geschwindigkeit seiner Zwillingsdolche verschleiert. Heute verehren die Wildfänge ihren Mantel als Zeichen der Stammeszugehörigkeit und der Stellung, die ihnen zusteht.\n\nBringt mir das gewünschte Symbol der Macht und ein derartiger Mantel wird Euch gehören und Eure Feinde in Wahnsinn hüllen.", progress = "Ihr seid zurück - habt Ihr das von mir benötigte Symbol der Macht?\n\nDie Legende von Khar'vaxal dem Irrsinnigen dient uns heute als Erinnerung dafür, dass kein Feind unbesiegbar ist, egal wie groß dessen Bedrohung auch sein mag. Chaos zwingt alles und jeden in die Knie, so viel ist sicher... vielleicht sogar einige der unchaotischen Elemente des Chaos selbst.", completion = "Heute ist der Sieg auf unserer Seite, dank des Wahnsinns, den Ihr über unsere gemeinsamen Feinde habt hereinbrechen lassen! Das Wohlwollen der Zandalar ist Euch sicher und wir könnten unserem Dank für Eure Taten nicht besser Ausdruck verleihen, als wenn wir Euch den Mantel des Wildfangs überreichen würden!", rewards = "Ihr bekommt:\n\nZandalarianischer Mantel des Wildfangs"},
[8073] = {title = "Symbole der Macht: Die Tunika des Wildfangs", objective = "Bringt eine urzeitliche Aegis der Hakkari zu Falthir dem Blinden. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Meine Augen haben mich schon seit langem im Stich gelassen, aber ich trauere ihnen nicht nach. Selbst in einem Stamm wie dem unsrigen, in dem die Kleidung Rang und Bestimmung vermittelt, strahlen die einflußreichsten aller Gewänder eine Macht aus, die für normale Augen nicht sichtbar ist. Die zandalarianische Tunika des Wildfangs ist keine Ausnahme, sie strahlt die rohe Macht des Chaos und des Wahnsinns aus, die mit ihr kanalisiert werden kann.\n\nDie Symbole der Macht, die ich benötige, befinden sich in Zul'Gurub; bringt mir eines und ich werde Euch mit Eurer eigenen legendären Tunika belohnen... eine, die einem Säer des Wahnsinns gerecht wird.", progress = "Nochmals willkommen auf der Insel, <Name>... seid Ihr triumphierend mit dem Symbol der Macht zurückgekehrt?", completion = "Beeindruckend... Ihr habt heute vollbracht, was kaum für möglich gehalten wurde. Ihr könnt Euch dem Respekt unseres Stammes auf Lebenszeit sicher sein, &lt;Name&gt;. Nehmt die Tunika des Wildfangs entgegen, Ihr habt sie Euch verdient. Ihr habt unseren Segen.", rewards = "Ihr bekommt:\n\nZandalarianische Tunika des Wildfangs"},
[8074] = {title = "Symbole der Macht: Der Gürtel des Weissagers", objective = "Bringt einen urzeitlichen Hakkarigurt zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Die Weissager kennen das Mojo der Elemente, das ist wahr. Sie setzen es ein, um den Stamm zu Ruhm und Ehre zu führen. In den dunklen Zeiten, nachdem das Imperium der Gurubashi sich selbst zersplitterte, führten uns unsere Weissager in den sicheren Hafen der südlichen See. Sie haben uns auch wieder zurück hierher ins Tal geführt, genau ins Herz des Bösen, das in Zul'Gurub schwelt.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und beweist Euch als uns würdig. Solltet Ihr dabei Erfolg haben, werde ich Euch einen Gürtel geben, wie ihn unsere Weissager verwenden, einen mit mächtigem Mojo!", progress = "Das Symbol der Macht ist genau das, was wir brauchen, Mann. Wir werden ihm die Macht während unseres Kampfes gegen das Böse von Zul'Gurub entreißen. Habt Ihr es bei Euch?", completion = "Ich kann den Sieg über das Böse wittern, &lt;Name&gt;. Es ist ein süßer Duft... einer, der Euch sicherlich vertraut ist.\n\nIch weiß, dass die Beschaffung des Symbols, das für den Gürtel benötigt wird, nicht gerade einfach war. Eure Taten haben nicht nur unseren Stamm, sondern auch Euch selbst zu Ehren gebracht. Hier - nehmt den Gürtel des Weissagers und macht weiter so!", rewards = "Ihr bekommt:\n\nZandalarianischer Gürtel des Weissagers"},
[8075] = {title = "Symbole der Macht: Die Halsberge des Weissagers", objective = "Bringt einen urzeitlichen Hakkariwaffenrock zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Die Weissager der Zandalar tragen einen bestimmten Brustschmuck, der Halsberge genannt wird. Er wird aus feinster Seide und Stoffen zusammengefügt und mit starken Ketten verwoben.  Es ist nicht nur ein Symbol für ihre Göttlichkeit, sondern auch für ihre Autorität. Es ist niemals sehr weise den Weg von jemanden zu kreuzen, der sein Leben der Zwiesprache mit den Geistern gewidmet hat...\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und beweist Euch als uns würdig. Solltet Ihr dabei Erfolg haben, werde ich Euch eine der feinsten Halsbergen geben, die sich selbst einer der unsrigen Weissager zu tragen erhofft!", progress = "Die Symbole der Macht sind die ausschlaggebende Quelle magischer Macht... die gleiche Art Macht, die in die Herstellung der Halsberge des Weissagers einfließt. Bringt mir was ich brauche und ich werde Euch ein Bekleidungsstück geben, das selbst ein Weissager der Zandalar noch begehrt.", completion = "Ich weiß, was Ihr durchgemacht habt, um mir das Symbol der Macht zu beschaffen, &lt;Name&gt;. Es war nicht einfach das Böse zu bezwingen, das aus Zul'Gurub wie fauler Schlick sickert, ja - jetzt, nachdem alles gesagt und getan ist, kann ich Euch jedoch als im Stamm der Zandalar respektiert bezeichnen - und das für Lebzeiten!\n\nHier - nehmt die Halsberge des Weissagers und tragt sie mit Stolz!", rewards = "Ihr bekommt:\n\nZandalarianische Halsberge des Weissagers"},
[8076] = {title = "Symbole der Macht: Der Mantel des Besessenen", objective = "Bringt eine urzeitliche Hakkarischärpe zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Der Besessene möchte Macht geradewegs verkörpern und nicht nur besitzen. Mehr als ein Besessener hat bereits den Kampf gegen einen Dämonen verloren; die Feinde, die uns bedrohen, besonders in Zul'Gurub, und die Macht, die ein Besessener auf unsere Feinde loslassen kann, sind das Opfer jedoch wert. Unser Überleben hängt von der Zerstörung derer ab, die nach unserem Ende trachten; das hat uns der Fall des Imperiums der Gurubashi gelehrt.\n\nReist nach Zul'Gurub und beschafft uns das von uns benötigte Symbol der Macht. Solltet Ihr dabei Erfolg haben, soll ein wertvoller Gegenstand eines Besessenen Euer Eigen sein.", progress = "Habt Ihr das Symbol der Macht von Zul'Gurub beschafft? Wenn wir diesem Gegenstand die latente Macht entnehmen und zu unserem Eigen machen, werden wir Euch Eure eigene Belohnung der Macht aushändigen... solltet Ihr erfolgreich gewesen sein...", completion = "Gut gemacht, &lt;Name&gt;. Die Symbole der Macht von Zul'Gurub sollten als Beweis für verschwendete Macht dienen. Die Gurubashi waren zu ihren Hochzeiten stark, aber sie gestatteten sich selbst davon aufgezehrt zu werden. Der Besessene weiß, dass die Spiele, die von ihm gespielt werden, ähnlich sind, jedoch ist die Macht, die dabei freigegeben wird, oft das Ausschlaggebende zum Überleben.\n\nVerwendet diesen Mantel als jemand, der von den Zandalar mit Wohlwollen als Verbündeter betrachtet wird... er wird Euch noch nützlich sein.", rewards = "Ihr bekommt:\n\nZandalarianischer Mantel des Besessenen"},
[8077] = {title = "Symbole der Macht: Die Roben des Besessenen", objective = "Bringt einen urzeitlichen Hakkarikosak zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Im Stamm ist das ultimative Zeichen für Macht die Kleidung, die im Kampf getragen wird. Die Roben des Besessenen vereinen feinen Runenstoff und verheerend mächtiges Mojo. Man sagt, dass das Aussehen dieser Roben allen Angst einflößt, die sie erblicken... besonders den Dämonen, die der Besessene eventuell beherrschen möchte.\n\nIhr müsst mir von Zul'Gurub ein besonderes Symbol der Macht besorgen. Es wird nicht einfach sein... Euer erfolgreiches Handeln wird Euch jedoch den Besitz einer der besagten Roben sichern.", progress = "Das Symbol der Macht... habt Ihr es bei Euch? Erst wenn wir es haben, werden wir das ultimative Zeichen besessener Macht mit Euch teilen, <Name>.", completion = "Beeindruckend - Euer Sieg in Zul'Gurub hat uns bewiesen - ach, was sage ich denn da, der ganzen Welt - dass Hakkar sich nicht durchsetzen wird. Die Zeit, in der Ihr dem Blutgott direkt gegenüberstehen werdet, wird noch kommen... sollte es soweit sein, dann wisst, dass Euch der Respekt der Zandalar sicher ist.\n\nOh, ich denke Euch wird auch diese einfache Robe behilflich sein.\n\n&lt;Al'tabim zwinkert Euch wissend zu.&gt;", rewards = "Ihr bekommt:\n\nZandalarianische Robe des Besessenen"},
[8078] = {title = "Symbole der Macht: Der Gürtel des Vollstreckers", objective = "Bringt einen urzeitlichen Hakkarigurt zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Die ultimative Rache wartet innerhalb Zul'Gurubs. Hakkar darf nicht mehr auferstehen. Hakkar hat das Imperium der Gurubashi von innen heraus zerstört. Kein Opfer war ihm dafür zu schade. Die Trolle sind nur noch ein Schatten ihrer glorreichen Zeiten. Ich weiß, dass all dies auf Hakkar beruht.\n\nWerdet der Vollstrecker, zu dem Ihr bestimmt wart. Bringt Zerstörung über die Diener des Bösen herein. Zul'Gurub muss den Rachedurst der Zandalar zu spüren bekommen. Bringt mir ein Symbol der Macht als Beweis. Ihr werdet dafür den Gürtel des Vollstreckers bekommen. Ihr werdet wahre Macht erhalten.\n\nUnd nun geht.", progress = "Habt Ihr das Symbol der Macht? Habt Ihr die Feinde des Stammes niedergestreckt? Hakkar muss den Zorn des Vollstreckers kennenlernen!", completion = "Der Weg des Vollstreckers ist Euch jetzt bekannt. Ihr habt dem Stamm und Euch selbst Ehre eingebracht und Schmerz unter unseren Feinden gesät.\n\nDer Gürtel des Vollstreckers ist jetzt Euer Eigen. Ihr werdet mit Sicherheit eins mit dem Weg des Vollstreckers werden.", rewards = "Ihr bekommt:\n\nZandalarianischer Gürtel des Vollstreckers"},
[8079] = {title = "Symbole der Macht: Die Brustplatte des Vollstreckers", objective = "Bringt einen urzeitlichen Hakkarikosak zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Die Brustplatte ist das Symbol der Macht eines Vollstreckers. Sie wird mit mächtigem Mojo geschmiedet. Sie wird nur denen anvertraut, die wir ehren. Es ist das Symbol der Rache der Zandalar.\n\nEin Vollstrecker zu werden, bedeutet ein Rächer zu werden. Beschafft das benötigte Symbol der Macht von Zul'Gurub. Bringt es zu uns. Wir werden uns das von uns gestohlene Mojo zurückholen. Die Diener Hakkars werden bezahlen müssen. Eure Belohnung wird die Brustplatte des Vollstreckers sein.\n\nGeht. Seid unser Rächer, <Name>.", progress = "Eure Anwesenheit kündet von Erfolg? Habt Ihr das Symbol der Macht? Erzählt mir von der Rache, die Ihr heute habt walten lassen!", completion = "Ihr habt Euch für Eure Taten Respekt verdient. Der Stamm belohnt seine Helden. Zul'Gurub hat die Rache der Zandalar wie niemals zuvor zu spüren bekommen.\n\nEure Errungenschaften künden von Taten, die noch andere erbringen werden. Sie werden Euch als Zeichen wahrer Macht ansehen, als Personifizierung der Rache!", rewards = "Ihr bekommt:\n\nZandalarianische Brustplatte des Vollstreckers"},
[8080] = {title = "Die Ressourcen des Arathibeckens", objective = "Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Sergeant Maclear in der Zuflucht.", description = "Eine Schlacht muss mit Soldaten gewonnen werden, das wird Euch jeder Soldat gerne bestätigen. Man sagt auch, dass eine Schlacht auf leeren Magen und mit schlechter Ausrüstung bereits eine verlorene Schlacht ist!\n\nDeshalb ist das Arathibecken so wichtig. Es gibt dort Schlüsselregionen, die essentielle Ressourcen bergen. Metalle, Waffen, Holz, ja, alles wird gebraucht und kann dort gefunden werden.\n\nDaher brauche ich Euch, <Name>. Begebt Euch ins Arathibecken und entscheidet die Schlacht für Euch, indem Ihr mehr Stützpunkte haltet als der Feind. Bringt mir als Beweis Eurer Taten eine Vorratskiste.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[8081] = {title = "Noch mehr Vorratskisten", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8101] = {title = "Der Stein des Kajaro", objective = "<Volk>, der Stein, der von diesem Talisman umrahmt wird, kommt vom Berg Kajaro in den südlichen Meeren. Das Gebiet rund um den Berg Kajaro wird von Unbeständigkeit geplagt; insbesondere durch heftige und oft auch magische Vulkanausbrüche.\n\nJe stärker Euer Bund mit den Trollen Zandalars wird, umso mächtiger wird dieser Stein. Nutzt die Macht des Steins, um unsere Feinde zu vernichten. Seid wie der Berg: schnell, explosiv, tödlich...", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStein des Kajaro"},
[8102] = {title = "Der Stein des Kajaro", objective = "Willkommen zurück, <Klasse>. Ich kann sehen, dass der Stein häufig Anwendung fand. Viele unserer Feinde wurden Opfer Eurer jenseitigen Fähigkeiten. Ihr Leiden war groß. Es ist an der Zeit, dass ich die Macht des Steins verstärke. Gebt ihn mir.", description = nil, progress = "Willkommen zurück, <Klasse>. Ich kann sehen, dass der Stein häufig Anwendung fand. Viele unserer Feinde wurden Opfer Eurer jenseitigen Fähigkeiten. Ihr Leiden war groß. Es ist an der Zeit, dass ich die Macht des Steins verstärke. Gebt ihn mir.", completion = "Seid unaufhaltsam, wie die geschmolzenen Wogen des Kajaro.", rewards = "Ihr bekommt:\n\nStein des Kajaro"},
[8103] = {title = "Der Stein des Kajaro", objective = "Die Hakkari fürchten Euch, <Name>. Sie sprechen von Grausamkeiten, die sie bis jetzt nur ihrem gesichtslosen Gott zutrauten. Ihr habt sie mit der Macht des Kajaro gezeichnet. Sie kennen jetzt die beiden Seiten der Furcht.\n\nEs ist an der Zeit, den Stein noch weiter zu stärken. Gebt mir den Talisman.", description = nil, progress = "Die Hakkari fürchten Euch, <Name>. Sie sprechen von Grausamkeiten, die sie bis jetzt nur ihrem gesichtslosen Gott zutrauten. Ihr habt sie mit der Macht des Kajaro gezeichnet. Sie kennen jetzt die beiden Seiten der Furcht.\n\nEs ist an der Zeit, den Stein noch weiter zu stärken. Gebt mir den Talisman.", completion = "Führt Eure Vernichtung der Trolle von Zul'Gurub noch weiter fort. Hakkar muss erkennen, dass die Welt sich nicht seinem unbezwingbaren Willen beugt.", rewards = "Ihr bekommt:\n\nStein des Kajaro"},
[8104] = {title = "Das Juwel von Kajaro", objective = "Gebt mir den Talisman, <Name>. Ich muss Euch etwas zeigen.", description = nil, progress = "Gebt mir den Talisman, <Name>. Ich muss Euch etwas zeigen.", completion = "&lt;Al'tabim erschüttert den Juwel mit einer mächtigen, bisher ungesehenen Kraft.&gt;\n\nSeht Ihr? Der Stein ist das, was wir eine kristallgefüllte Hohlkugel nennen. In ihm befinden sich mächtige Kristalle, die mit den latenten Energien dieser Welt getränkt sind. Indem ich das Juwel entzwei schnitt, ließ ich ihn endlich sein wahres Potential entfalten. Nutzt ihn, um Vernichtung über unsere Feinde zu bringen.", rewards = "Ihr bekommt:\n\nJuwel von Kajaro"},
[8105] = {title = "Die Schlacht um das Arathibecken!", objective = "Erobert die Mine, das Sägewerk, die Schmiede und die Farm und meldet Euch anschließend bei Feldmarschall Onslight in der Zuflucht.", description = "<Name>, die Schlacht im Arathibecken ist ein Kampf um Ressourcen und Territorien. Um unsere Truppen mit den dringend benötigten Rohstoffen und Vorräten zu versorgen, gilt es bestimmte Schlüsselpositionen zu besetzen und deren Ressourcen zu nutzen. Ich erteile Euch hiermit den Auftrag, die von unserem Stützpunkt am weitesten entfernten Schlüsselpostionen anzugreifen.\n\nErobert den Hof, die Mine, das Sägewerk und die Schmiede, sofern der Feind diese Positionen unter seiner Kontrolle hat. Sucht an jedem dieser Orte nach dem gegnerischen Banner und reißt es aus seiner Halterung!\n\nMeldet Euch wieder bei mir, wenn Euch das an allen vier Schlüsselpostionen gelungen ist.", progress = nil, completion = "&lt;Name&gt;, Ich erhielt Kunde von Euren Heldentaten im Arathibecken. Hervorragende Arbeit! Wenn sich noch mehr Freiwillige als ebenso fähig erweisen wie Ihr, bin ich zuversichtlich, dass wir eines Tages unsere Heimat zurückerobern werden.", rewards = "Ihr bekommt:\n\n"},
[8106] = {title = "Kezans Schmach", objective = "Bitte nehmt diesen Talisman, <Klasse>. Nutzt seine Macht, um unsere gemeinsamen Feinde niederzuschmettern.\n\nSeid Euch bewusst, dass Ihr ein Stück Geschichte um Euren Hals tragt. Kezan war einst ein großes Territorium des Imperiums von Zandalar. Doch im Laufe der Zeit zwang der schändliche Einfluss der Goblin-Handelsfürsten meine stolzen Brüder und Schwestern, Kezan den Rücken zu kehren.\n\nKezan beherbergt jetzt Undermine, die Hauptstadt der Goblins; doch wisset, dass sie einst wahre Größe ausstrahlte. Noch heute gilt Kezan meinem Volk als heiliges Land.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKezans Schmach"},
[8107] = {title = "Kezans Schmach", objective = "Ihr habt Euch bei den Trollen Zandalars Ehre verdient, <Name>. Mit Ehre kommt auch Entlohnung, Freundschaft, Verbundenheit...\n\nGebt mir den Talisman, damit ich seine Macht verstärken kann.", description = nil, progress = "Ihr habt Euch bei den Trollen Zandalars Ehre verdient, <Name>. Mit Ehre kommt auch Entlohnung, Freundschaft, Verbundenheit...\n\nGebt mir den Talisman, damit ich seine Macht verstärken kann.", completion = "Der Dunkelheit entsprungen, &lt;Klasse&gt;. Begrüßt den Schatten. Lasst Kezans Schmach Eure dunkle Einmischung ergänzen.", rewards = "Ihr bekommt:\n\nKezans Schmach"},
[8108] = {title = "Kezans Schmach", objective = "Ich bin für euch bereit, <Klasse>. Noch einmal werde ich Euren Talisman verstärken. Ich bitte Euch nur mit Eurer Zerstörung von Hakkar und seinen Dienern fortzufahren.\n\nGebt mir den Talisman.", description = nil, progress = "Ich bin für euch bereit, <Klasse>. Noch einmal werde ich Euren Talisman verstärken. Ich bitte Euch nur mit Eurer Zerstörung von Hakkar und seinen Dienern fortzufahren.\n\nGebt mir den Talisman.", completion = "Wir werden den Seelenschinder nur mit vereinten Kräften aufhalten können.", rewards = "Ihr bekommt:\n\nKezans Schmach"},
[8109] = {title = "Kezans unaufhaltsame Schmach", objective = "Ruft Eure Dämonen hervor, <Klasse>. Lasst sie in der Energie von Kezans Schmach schwelgen. Führt sie auf's Schlachtfeld! Vernichtet den Feind!\n\nJa... die Zeit ist gekommen, um Kezans Schmach endgültig zu verstärken. Gebt mir den Talisman.", description = nil, progress = "Ruft Eure Dämonen hervor, <Klasse>. Lasst sie in der Energie von Kezans Schmach schwelgen. Führt sie auf's Schlachtfeld! Vernichtet den Feind!\n\nJa... die Zeit ist gekommen, um Kezans Schmach endgültig zu verstärken. Gebt mir den Talisman.", completion = "Reißt das Fleisch von ihren Körpern. Beobachtet, wie die Schatten die Hakkari verzehren. Zieht Macht aus ihrer Furcht, &lt;Klasse&gt;. Lasst Kezans Schmach mächtiger werden...", rewards = "Ihr bekommt:\n\nKezans unaufhaltsame Schmach"},
[8110] = {title = "Verzauberter Südmeertang", objective = "Unglaublich! Ihr habt sie gefunden! Ihr seid ein wahrer Held, <Name>!\n\nDas ist eine gute Sache, denn ich habe die Schrifttafeln gelesen, die Ihr mir zuvor gebracht habt, und nach dem, was ich herausgefunden habe... tja, da werden wir wohl einen Helden brauchen, der aufhält, was kommt...", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nVerzauberter Südmeertang"},
[8111] = {title = "Verzauberter Südmeertang", objective = "Hey Ihr! Gut Euch wieder zu sehen. Der Stamm spricht von Eurer Vernichtung der Hakkari und all dem. Molthor hat mir zugesichert, dass ich Eurem Talisman mehr Mojo hinzufügen kann. Gebt ihn einfach her und Maywiki wird ihn besser machen.", description = nil, progress = "Hey Ihr! Gut Euch wieder zu sehen. Der Stamm spricht von Eurer Vernichtung der Hakkari und all dem. Molthor hat mir zugesichert, dass ich Eurem Talisman mehr Mojo hinzufügen kann. Gebt ihn einfach her und Maywiki wird ihn besser machen.", completion = "Hey, der Halsschmuck ist nicht zum Rauchen gedacht! Ihr müsst ihn im Kampf gegen das Böse einsetzen.", rewards = "Ihr bekommt:\n\nVerzauberter Südmeertang"},
[8112] = {title = "Verzauberter Südmeertang", objective = "Wie ist der Talisman? Es sieht aus, als wäre es an der Zeit dem Tang etwas mehr Magie und Mojo zuzufügen. Er benötigt eine kleine Auffrischung. Gebt in her und Maywiki wird's schon machen.", description = nil, progress = "Wie ist der Talisman? Es sieht aus, als wäre es an der Zeit dem Tang etwas mehr Magie und Mojo zuzufügen. Er benötigt eine kleine Auffrischung. Gebt in her und Maywiki wird's schon machen.", completion = "Jetzt nehmt Ihr Euch die bösen Trolle in Zul'Gurub vor und zeigt ihnen, was Eure Naturkräfte so alles können!", rewards = "Ihr bekommt:\n\nVerzauberter Südmeertang"},
[8113] = {title = "Reiner verzauberter Südmeertang", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nReiner verzauberter Südmeertang"},
[8114] = {title = "Kontrolliert vier Stützpunkte", objective = "Betretet das Arathibecken, erobert und kontrolliert gleichzeitig vier Stützpunkte im Arathibecken und kehrt danach zu Feldmarschall Oslight in der Zuflucht zurück.", description = "<Name>, Ihr habt unseren Feinden im Arathibecken den Krieg gebracht und auf dem Schlachtfeld große Ehre erlangt. Ihr habt bewiesen, wie wertvoll Ihr als <Klasse> für uns seid, und unseren Feinden gezeigt, dass wir uns ihren Streitkräften gegenüber nicht beugen werden!\n\nDa Ihr Euren Wert unter Beweis gestellt habt, habe ich einen besonders schwierige Auftrag für Euch. Ich möchte, dass Ihr mindestens vier der Stützpunkte im Arathibecken besetzt und haltet. Wenn Euch das gelingt, sichern wir uns nicht nur kritische Ressourcen, sondern zeigen der Horde auch unsere Überlegenheit!\n\nGeht nun, <Name>, und viel Glück!", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;! Ein begeisterter Späher kam zu mir und berichtete mir von Euren Erfolgen!\n\nWir, der Bund von Arathor, sind mehr als zufrieden!\n\nInnerhalb kürzester Zeit seid Ihr zu einem Helden unserer Soldaten geworden. Eure heutigen Taten unterstreichen nur die Rechtmäßigkeit Eures heldenhaften Rufs!", rewards = "Ihr bekommt:\n\n"},
[8115] = {title = "Kontrolliert fünf Stützpunkte", objective = "Kontrolliert gleichzeitig fünf Stützpunkte im Arathibecken und kehrt danach zu Feldmarschall Oslight in der Zuflucht zurück.", description = "<Name>, es ist ein blutiges Unterfangen um die Ressourcen von Arathor zu kämpfen. Eure Dienste für den Bund von Arathor werden genauso dringend gebraucht, wie sie honoriert werden.\n\nWIr haben eine weitere Aufgabe für Euch.\n\nDer Bund möchte einen Schlag gegen die Okkupation der Entweihten im Arathibecken vollbringen. Wir möchten sie von jedem strategischen Punkt des Schlachtfelds vertreiben!\n\nEs wird nicht leicht werden, aber wenn es überhaupt jemand schaffen kann, dann Ihr.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWappenrock der Arathor"},
[8116] = {title = "Vision von Voodress", objective = "Ihr und Maywiki haben etwas gemeinsam. Wir sind beide Schamanen! Auch wenn Maywiki eher geheimnisvoll ist und Ihr vielmehr grob daher kommt. Trotzdem, wir wissen beide von der Macht der Geister.\n\nIch gebe Euch diese Kugel als Geschenk, tragt sie um den Hals. Schaut tief in sie hinein und seht die Stadt von Voodress in den südlichen Meeren! Lasst sie Eure Geister beflügeln!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nVision von Voodress"},
[8117] = {title = "Vision von Voodress", objective = "Sha-mann! Maywiki macht Witze!\n\n<Maywiki lacht.>\n\nSo, Ihr habt also die Geister und Elemente gegen unsere Feinde in Zul'Gurub eingesetzt, hä? Die Geister seien gelobt!\n\nMaywiki wird Eure Kugel aufpolieren. Gebt sie mir, <Name>.", description = nil, progress = "Sha-mann! Maywiki macht Witze!\n\n<Maywiki lacht.>\n\nSo, Ihr habt also die Geister und Elemente gegen unsere Feinde in Zul'Gurub eingesetzt, hä? Die Geister seien gelobt!\n\nMaywiki wird Eure Kugel aufpolieren. Gebt sie mir, <Name>.", completion = "Seht sie Euch jetzt an, &lt;Name&gt;. Noch mehr sichtbare Voodress, oder? Lasst die urzeitliche Macht durch Euch fließen.", rewards = "Ihr bekommt:\n\nVision von Voodress"},
[8118] = {title = "Vision von Voodress", objective = "Gute Neuigkeiten, <Name>. Molthor hat Lob über Euch verkündet. Er erzählte, wie Ihr Euch in einen wahren Helden der Zandalar verwandelt habt.\n\nEr wies mich auch an, Eure Kugel noch etwas aufzupolieren! Gebt sie her, damit Maywiki die Vision noch weiter aufhellen kann.", description = nil, progress = "Gute Neuigkeiten, <Name>. Molthor hat Lob über Euch verkündet. Er erzählte, wie Ihr Euch in einen wahren Helden der Zandalar verwandelt habt.\n\nEr wies mich auch an, Eure Kugel noch etwas aufzupolieren! Gebt sie her, damit Maywiki die Vision noch weiter aufhellen kann.", completion = "Hütet Euch vor den bösen Geistern der Hakkari. Sie sind wirklich unheimlich.", rewards = "Ihr bekommt:\n\nVision von Voodress"},
[8119] = {title = "Die unversehrte Vision von Voodress", objective = "<Maywiki zeigt auf Euren Talisman.>\n\nSchaut, <Name>! Er ist zum Leben erwacht. Die Geister tanzen um die Kugel.\n\nGebt ihn Maywiki, damit sie die letzte Anpassung vornehmen kann.", description = nil, progress = "<Maywiki zeigt auf Euren Talisman.>\n\nSchaut, <Name>! Er ist zum Leben erwacht. Die Geister tanzen um die Kugel.\n\nGebt ihn Maywiki, damit sie die letzte Anpassung vornehmen kann.", completion = "Eines Tages, &lt;Name&gt;, werdet Ihr diese Kugel nutzen können, um direkt mit mir zu kommunizieren. Wann auch immer der Kampf gegen Hakkar vorüber sein wird und Maywiki nach Hause zurückkehrt. Lasst uns die Geister anrufen und darum bitten, dass dieser Tag bald sein wird.", rewards = "Ihr bekommt:\n\nUnversehrte Vision von Voodress"},
[8120] = {title = "Die Schlacht um das Arathibecken!", objective = "Erobert die Mine, das Sägewerk, die Schmiede, die Farm und die Ställe und kehrt dann zu Todesmeister Dwire in Hammerfall zurück.", description = "Wie Ihr sicherlich schon gehört habt, entsendet der Bund von Arathor seine Truppen ins Arathibecken. Versessen auf Nahrung und Vorräte, können diese Idioten der Allianz es kaum erwarten, die riesigen Ressourcen des Beckens zu kontrollieren. Wir müssen ihnen zeigen, dass Arathi niemals wieder das Zuhause der Menschen sein wird!\n\nGeht ins Arathibecken und greift die Mine, das Sägewerk, die Schmiede und die Ställe an. Reißt die feindlichen Banner herunter und besetzt das Gebiet für die Horde.\n\nGeht, <Name>. Kehrt zu mir zurück, sobald Ihr Eure Aufgabe erfüllt habt.", progress = nil, completion = "Ein Späher der Entweihten hat mir bereits von Eurem Erfolg berichtet, &lt;Name&gt;. Gut gemacht.\n\nSo wie Ihr lernen werdet, die Schlacht ums Arathibecken zu gewinnen, müsst Ihr lernen, immer wachsam zu sein und jeden Expansionsversuch der Allianz zu zerschlagen. Wenn Ihr dies verinnerlicht, wird der Sieg unser sein.", rewards = "Ihr bekommt:\n\n"},
[8121] = {title = "Erobert vier Stützpunkte", objective = "Haltet vier Stützpunkte zurselben Zeit im Arathibecken und kehrt danach zu Todesmeister Dwire nach Hammerfall zurück.", description = "<Name>, während die Schlachten über das Arathibecken wüten, haben sich die Neuigkeiten über Eure Taten wie ein Lauffeuer verbreitet. Wir schätzen Euch hier sehr und daher hoffe ich, dass Ihr die Mission erfüllen könnt, die ich Euch nun gebe.\n\nEs ist Zeit dem Bund von Arathor eine Nachricht zu senden. Wir müssen Ihnen zeigen, dass ihre Stellungen im Arathibecken leicht angreifbar und schnell verloren sind. Das werden wir ihnen beweisen, indem wir gleichzeitig vier strategische Punkte im Arathibecken erobern und kontrollieren.\n\nSeid erfolgreich, <Name> und erntet mehr Respekt unter den Entweihten.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;! Eure letzten Missionen im Arathibecken waren ziemlich schwierig und daher ist Euer Erfolg so rühmenswert. Der Bund von Arathor wird sich sicher gerade von den letzten Kämpfen seine Wunden lecken, und lasst es uns hoffen, sicher darüber nachdenken, ob es sich lohnt hier zu kämpfen.", rewards = "Ihr bekommt:\n\n"},
[8122] = {title = "Erobert fünf Stützpunkte", objective = "Haltet fünf Stützpunkte zurselben Zeit im Arathibecken und kehrt danach zu Todesmeister Dwire nach Hammerfall zurück.", description = "Es ist schwer an Informationen zu gelangen, jetzt da wir so tief in diesem Konflikt stecken. Doch unsere Spione berichten, dass die Entschlossenheit des Bundes von Arathor schwindet. Wir sollten diesen Moment ausnutzen und eine große Offensive starten! Kehrt in das Arathibecken zurück und werft Euch unserem Feind entgegen. Verflucht und vernichtet sie, bis Ihr fünf strategische Punkte kontrolliert! Ihre Soldaten sollen blutend und schreiend in die Flucht geschlagen werden und ganz Azeroth mit zitternder Stimme von Eurer Grausamkeit berichten.\n\nGeht jetzt und erringt einen großen Sieg für die Entweihten.", progress = nil, completion = "&lt;Name&gt;, selbst von hier aus, konnte ich noch die Schreie der sterbenden Allianzsoldaten hören, als Ihr sie zusammen mit Euren Gefährten angegriffen habt. Ich empfinde beinahe schon so etwas wie Mitleid, für all die Schmerzen und das Leid, welches Ihr in ihre Reihen gebracht habt.\n\nEure Nützlichkeit für die Entweihten steht für mich außer Frage. Euer Vorgehen im Arathibecken war mehr als beeindruckend und wurde selbst in den Hallen Varimathras vernommen... sogar von der dunklen Fürstin selbst.", rewards = "Ihr bekommt:\n\nWappenrock der Entweihten"},
[8123] = {title = "Zerschlagt die Versorgungslinien Arathors", objective = "Entscheidet die Schlacht um das Arathibecken für Euch, erbeutet eine Arathivorratskiste und bringt sie Todespirscher Mortis in Hammerfall.", description = "Der Bund von Arathor scheut keine Mühen, um Arathi sein Eigen zu nennen. Sie und all die anderen Völker der Allianz strömen nun in diese entfernte Region, versessen darauf, ihren Gebietsanspruch von der Zuflucht aus zu erweitern. Wir müssen sie aufhalten, und das beste Mittel dies zu tun, ist ihre Vorräte zu stehlen.\n\nIhr könnt uns helfen, <Name>. Betretet das Arathibecken, das für seine reichen Minen, sein fruchtbares Land und seine geschickten Handwerker bekannt ist, und erobert jeden Stützpünkt, den Ihr könnt. Entscheidet die Schlacht auf diese Weise für Euch und kehrt dann mit den Ressourcen, die Ihr erbeuten konntet, zu mir zurück.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[8124] = {title = "Noch mehr Vorratskisten", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8141] = {title = "Zandalarianischer Schattentalisman", objective = "Ihr macht rasch Fortschritte, <Klasse>. Vielleicht ist es an der Zeit Euch in Shera Ali'kh einzuweihen - zandalarianisch für die Hand des Todes. Tausende von Jahren übernahmen wir die Rolle der Meuchelmörder für das Imperium der Zandalar. Zu lange saßen wir untätig herum und erlaubten es den Hakkari an Macht zu gewinnen. Noch einmal stehen wir Hakkar gegenüber, aber diesmal ohne die Unterstützung einer vereinten Trollfront. Ihr und Eure Verbündeten müssen uns dabei helfen den Blutgott und seine Diener zu vernichten!\n\nTragt diesen Talisman und lasst ihn Euch bei Euren Taten unterstützen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZandalarianischer Schattentalisman"},
[8142] = {title = "Zandalarianischer Schattentalisman", objective = "Ich spüre, dass Ihr zahlreiche Todesopfer unter den Hakkari gefordert habt, <Name>. Ihr tragt den Geruch ihres Mojos.\n\nIch vermute, dass Euch der Schattentalisman beim Ausmerzen behilflich war? Gebt ihn mir, ich werde seine Macht noch einmal verstärken.", description = nil, progress = "Ich spüre, dass Ihr zahlreiche Todesopfer unter den Hakkari gefordert habt, <Name>. Ihr tragt den Geruch ihres Mojos.\n\nIch vermute, dass Euch der Schattentalisman beim Ausmerzen behilflich war? Gebt ihn mir, ich werde seine Macht noch einmal verstärken.", completion = "Einem Meuchelmörder von Eurem Kaliber sollte man besser aus dem Weg gehen. Eure Feinde müssen Euch zu respektieren lernen! Ihr werdet genau das bekommen, sobald der Feind die Hand des Todes wahrnimmt... zu spät...", rewards = "Ihr bekommt:\n\nZandalarianischer Schattentalisman"},
[8143] = {title = "Zandalarianischer Schattentalisman", objective = "Beeindruckend, <Name>. Ihr habt ein Händchen für's Töten, so etwas ist mir schon seit Jahren nicht mehr untergekommen. Sogar Molthor hat von Euren Taten für Zandalar Notiz genommen. Lasst mich Euren Talisman weiter verstärken, es ist an der Zeit... gebt ihn mir.", description = nil, progress = "Beeindruckend, <Name>. Ihr habt ein Händchen für's Töten, so etwas ist mir schon seit Jahren nicht mehr untergekommen. Sogar Molthor hat von Euren Taten für Zandalar Notiz genommen. Lasst mich Euren Talisman weiter verstärken, es ist an der Zeit... gebt ihn mir.", completion = "Es gibt nur noch eine weitere Verstärkung für den Talisman, &lt;Klasse&gt;. Wenn die Zeit dafür gekommen ist, werde ich auch diese anwenden.", rewards = "Ihr bekommt:\n\nZandalarianischer Schattentalisman"},
[8144] = {title = "Zandalarianischer Schattentalisman der Beherrschung", objective = "Er sehnt sich nach Wachstum, <Name>. Der Talisman hat all das in sich aufgenommen, was Ihr vollbracht habt. Die unzähligen Trollkadaver, die Zul'Gurub beschmutzen, haben seine Macht angeheizt. Gebt ihn mir und ich werde ihn endgültig verstärken.", description = nil, progress = "Er sehnt sich nach Wachstum, <Name>. Der Talisman hat all das in sich aufgenommen, was Ihr vollbracht habt. Die unzähligen Trollkadaver, die Zul'Gurub beschmutzen, haben seine Macht angeheizt. Gebt ihn mir und ich werde ihn endgültig verstärken.", completion = "Dies ist das letzte Mal, dass wir unter der Schirmherrschaft von Shera Ali'kh miteinander sprechen. Ihr wisst alles, was Ihr wissen müsst. Nehmt den Talisman und setzt Eurer Schlachten fort. Hakkar darf Zul'Gurub niemals verlassen.", rewards = "Ihr bekommt:\n\nZandalarianischer Schattentalisman der Beherrschung"},
[8145] = {title = "Die Maelstromranke", objective = "Unter den Zandalarianern wird der Stand des Jägers hoch verehrt. Die mächtigsten unserer <Klasse> reisen bis an den Rand des Maelstroms, um ihre Entschlossenheit unter Beweis zu stellen.\n\nAus dem tiefsten Herzen der See, ernten sie eine seltene Seetangart, die Maelstromranke. Die Seetangstränge werden in einen Talisman gewoben, welcher anschließend verzaubert wird, um die Treffsicherheit und Macht des Trägers zu verstärken.\n\nIch werde Euch jetzt die erste Maelstromranke in einen Talisman einweben. Wenn Euer Bund mit den Zandalar stärker wird, werde ich Euch mehr Ranken in den Talisman weben und so dessen Macht verstärken.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMaelstroms Ranke"},
[8146] = {title = "Die Maelstromranke", objective = "Ah, <Name>, es ist schön Euch mal wieder zu riechen.\n\n\n\nIhr müsst meinen Humor entschuldigen, zuweilen nimmt er abstruse Formen an.\n\nIch fühle, dass Ihr unter unseren Feinden Angst und Schrecken verbreitet habt. Hakkars Gefolgsleute sprechen Euren Namen nur noch im Zorn aus. Hervorragend.\n\nIhr habt es verdient, dass ich Euch eine weitere Ranke in Euren Talisman einwebe. Gebt ihn mir.", description = nil, progress = "Ah, <Name>, es ist schön Euch mal wieder zu riechen.\n\n\n\nIhr müsst meinen Humor entschuldigen, zuweilen nimmt er abstruse Formen an.\n\nIch fühle, dass Ihr unter unseren Feinden Angst und Schrecken verbreitet habt. Hakkars Gefolgsleute sprechen Euren Namen nur noch im Zorn aus. Hervorragend.\n\nIhr habt es verdient, dass ich Euch eine weitere Ranke in Euren Talisman einwebe. Gebt ihn mir.", completion = "Mögen Sie am spitzen Ende Eurer Klinge Sühne finden.", rewards = "Ihr bekommt:\n\nMaelstroms Ranke"},
[8147] = {title = "Die Maelstromranke", objective = "Selbst jetzt höre ich noch, wie Eure Geschosssalven unter Euren Feinden ein Blutbad anrichten. Ich vernehme das Echo der Todesqualen in ihren Schreien.\n\nIch habt Euch wahrlich einen Namen unter den Trollen der Zandalar gemacht, <Name>. Wir sind Euch für Eure Taten sehr dankbar.\n\nGebt mir Euren Talisman, damit ich eine weitere Ranke hineinweben kann.", description = nil, progress = "Selbst jetzt höre ich noch, wie Eure Geschosssalven unter Euren Feinden ein Blutbad anrichten. Ich vernehme das Echo der Todesqualen in ihren Schreien.\n\nIch habt Euch wahrlich einen Namen unter den Trollen der Zandalar gemacht, <Name>. Wir sind Euch für Eure Taten sehr dankbar.\n\nGebt mir Euren Talisman, damit ich eine weitere Ranke hineinweben kann.", completion = "Es kann nur noch eine weitere Ranke in Euren Talisman gewoben werden, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\nMaelstroms Ranke"},
[8148] = {title = "Maelstroms Zorn", objective = "<Name>, Molthor brachte uns eine Botschaft von König Rastakhan. Der königliche Hof ist beeindruckt davon, wie sehr Ihr die Hakkaristreitkräfte dezimiert habt. Ich bin ermächtigt worden, die letzte Verstärkung in Euren Talisman einzuweben. Gebt ihn mir.", description = nil, progress = "<Name>, Molthor brachte uns eine Botschaft von König Rastakhan. Der königliche Hof ist beeindruckt davon, wie sehr Ihr die Hakkaristreitkräfte dezimiert habt. Ich bin ermächtigt worden, die letzte Verstärkung in Euren Talisman einzuweben. Gebt ihn mir.", completion = "Eure Reise hat gerade erst begonnen, junger &lt;Klasse&gt;. Vielleicht werdet Ihr eines Tages selbst den Maelstrom besuchen und in das Herz der Welt blicken.\n\nIch wünsche Euch innere Stärke und Tapferkeit, mein Freund!", rewards = "Ihr bekommt:\n\nMaelstroms Zorn"},
[8149] = {title = "Die Ehrung eines Helden", objective = "Reist zu Uthers Grabmal in den westlichen Pestländern und benutzt Uthers Tribut an seiner Statue. Kehrt zu Wagner Hammerstrike außerhalb von Ironforge zurück, bevor das Erntedankfest endet.\n\nBereitgestellter Gegenstand: \n", description = "Während des Erntedankfests in Azeroth danken wir unseren Helden für all die Opfer, die sie in unserem Namen dargebracht haben. Für einige war es gar das höchste aller Opfer, ihr Leben. Die Allianz kennt viele Helden, doch keine Heldensage und kein Lebensweg ist so tragisch, wie der von Uther Lightbringer.\n\nHelft uns Uther zu ehren, indem Ihr diese Opfergabe zu seinem Grabmal in den westlichen Pestländern bringt. Legt sie an seiner Statue nieder und kehrt zu mir zurück. Lasst Euch nicht zuviel Zeit, denn ich bin nur bis zum Ende des Erntedankfests hier.", progress = "Seid Ihr zu Uthers Grabmal gereist und habt den Tribut dort abgelegt?\n\nIch weiß, dass die Reise dorthin für weniger erfahrene Abenteuerer recht gefährlich sein kann. Um relativ sicher dorthin zu gelangen, reist nördlich von dem Fluss, welcher durch Hillsbrad in die Pestländer fließt. Er entspringt dort einem See, der an Sorrow Hill grenzt. Reist nach Westen durch die Hügel und seid in der Nähe des Grabmals vorsichtig... es ist von der Geißel verseucht.", completion = "Uther war selbst unter Helden ein Held. Ich vermag es mir kaum vorstellen, welche Qualen er erlitten hat, als Arthas, Uthers bester Schüler und von ihm geliebt wie seinen eigenen Sohn, Verrat an ihm und der ganzen Menschheit beging. Dennoch besaß er die Stärke sich zu erheben und zu versuchen, Arthas aufzuhalten. Für diese Selbstlosigkeit wird er uns immer als wahrer Paladin in Erinnerung bleiben. Er kämpfte bis zum bitteren Ende und dachte dabei nur an all diejenigen, die er retten würde.\n\nHabt Dank, &lt;Name&gt;. Heute habt Ihr einem großen Helden Tribut gezollt und so seinem Geist und dem Geist des Erntedankfests alle Ehre erwiesen.", rewards = "Ihr bekommt:\n\nFür das Licht!"},
[8150] = {title = "Die Ehrung eines Helden", objective = "Reist zu Groms Monument im Demonfall-Canyon in Ashenvale und benutzt Groms Tribut am Fuße seines Monuments. Kehrt zu Javnir Nashak außerhalb von Orgrimmar zurück, bevor das Erntedankfest endet.\n\nBereitgestellter Gegenstand: \n", description = "Während des Erntedankfests in Azeroth danken wir unseren Helden für all die Opfer, die sie in unserem Namen dargebracht haben. Für einige war es gar das höchste aller Opfer, ihr Leben. Die Horde kennt viele Helden, doch niemand verkörpert Stärke und Opferbereitschaft so sehr, wie Grom Hellscream.\n\nHelft uns Grom zu ehren, indem Ihr diese Opfergabe zu seinem Monument im Demonfall-Canyon in Ashenvale bringt. Legt sie an seinem Monument nieder und kehrt zu mir zurück. Lasst Euch nicht zuviel Zeit, denn ich bin nur bis zum Ende des Erntedankfests hier.", progress = "Seid Ihr zu Groms Grabmal gereist und habt den Tribut dort abgelegt?\n\nDie Umgebung des Monuments ist immer noch durch die Macht der Brennenden Legion verseucht. Wenn Ihr ein noch recht unerfahrener Abenteurer seid, solltet Ihr Euch dem Monument nur mit größter Vorsicht nähern.", completion = "Groms vollständer Name lautet Grommash und bedeutet \"Großes Herz\". Das und noch viel mehr war nötig, um alleine gegen Mannoroth zu bestehen.\n\nIch denke der Kriegshäuptling hat es am besten formuliert, als der Fluch der Orcs mit Grom begann und auch wieder mit ihm endete. Groms Opfer oder vielmehr, seine Erlösung, ist die Lebensquelle, welche die heutige Horde erblühen lässt und ihr Fortbestehen nährt.\n\nHabt Dank, &lt;Name&gt;. Heute habt Ihr einem großen Helden Tribut gezollt und so seinem Geist und dem Geist des Erntedankfests alle Ehre erwiesen.", rewards = "Ihr bekommt:\n\nHellscream, Held der Horde"},
[8151] = {title = "Der Talisman des Jägers", objective = "Sprecht mit Ogtinc in Azshara.", description = "Ogtinc von Azshara sucht nach erfahrenen Jägern, genau wie Ihr es seid. Er ist ein Furbolg-Jäger, der seinen Stamm verlassen hat, um dem Zirkel des Cenarius zu helfen. Seine Lehren sollen das Wissen anderer, die sein Geschick teilen, bereichern und ihnen dabei helfen, das Gleichgewicht zu bewahren. Ihr würdet gut daran tun, mit ihm zu sprechen.\n\nOgtinc hält sich auf den Klippen von Azshara, nordöstlich der Ruinen von Eldarath, auf.", progress = nil, completion = "Ich beabsichtige nicht länger selbst zu jagen, jedoch möchte ich &lt;Klasse&gt; unterrichten. Das ist mein Weg des Schicksals.\n\nStellt mit mir einen Talisman des Jägers her -- eine Kollektion von Trophäen gefallener Beute wird Euch an die Versuche und Siege Eurer Vergangenheit erinnern. Letztendlich werde ich den Talisman zwar behalten, Euch dafür aber mit etwas anderem belohnen.", rewards = "Ihr bekommt:\n\n"},
[8152] = {title = "REUSE", objective = "Sprecht mit Ogtinc in Azshara.In Azshara lebt ein Furbolg namens Ogtinc, er ist ein mächtiger und weiser Jäger. Besucht ihn, wenn Ihr Euch stark genug fühlt. Er sollte in der Lage sein, Euch weiter in den Künsten der Jagd zu unterweisen und Eure Fähigkeiten weiter zu verbessern.\n\nOgtinc lebt oben auf den Klippen, nordöstlich der Ruinen von Eldarath in Azshara.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "In Azshara lebt ein Furbolg namens Ogtinc, er ist ein mächtiger und weiser Jäger. Besucht ihn, wenn Ihr Euch stark genug fühlt. Er sollte in der Lage sein, Euch weiter in den Künsten der Jagd zu unterweisen und Eure Fähigkeiten weiter zu verbessern.\n\nOgtinc lebt oben auf den Klippen, nordöstlich der Ruinen von Eldarath in Azshara.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil},
[8153] = {title = "Gehörnte Renner", objective = "Bringt ein perfektes Rennergeweih zu Ogtinc nach Azshara. Er befindet sich auf den Klippen nordöstlich der Ruinen von Eldarath.", description = "Die Renner tragen die gewaltigsten Geweihe die es in der bekannten Welt zu finden gibt. Solche Geweihe nutzt der Renner, um sich selbst zu verteidigen, indem er Feinde damit aufspießt. Meistens brechen sie dadurch die Spitzen der Geweihe ab. Perfekte, natürliche Geweihe sind das Zeichen für ein extrem selbstsicheres Tier.\n\nEin solches Geweih zu erlangen, würde auch in Euch das selbe Selbstvertrauen fließen lassen.\n\nJagt nach dem Mooshufrenner, findet das perfekte Geweih und bringt es zu mir.", progress = "Habt Ihr die Geweihe?", completion = "Ihr müsst einen äußerst scharfen Blick und enorme Geduld besitzen, um dies erlangt zu haben. Gut gemacht.", rewards = "Ihr bekommt:\n\n"},
[8154] = {title = "Die Ressourcen des Arathibeckens", objective = "Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Sergeant Maclear in der Zuflucht.", description = "Eine Schlacht muss mit Soldaten gewonnen werden, das wird Euch jeder Soldat gerne bestätigen. Man sagt auch, dass eine Schlacht auf leeren Magen und mit schlechter Ausrüstung bereits eine verlorene Schlacht ist!\n\nDeshalb ist das Arathibecken so wichtig. Es gibt dort Schlüsselregionen, die essentielle Ressourcen bergen. Metalle, Waffen, Holz, ja, alles wird gebraucht und kann dort gefunden werden.\n\nDaher brauche ich Euch, <Name>. Begebt Euch ins Arathibecken und entscheidet die Schlacht für Euch, indem Ihr mehr Stützpunkte haltet als der Feind. Bringt mir als Beweis Eurer Taten eine Vorratskiste.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[8155] = {title = "Die Ressourcen des Arathibeckens", objective = "Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Sergeant Maclear in der Zuflucht.", description = "Eine Schlacht muss mit Soldaten gewonnen werden, das wird Euch jeder Soldat gerne bestätigen. Man sagt auch, dass eine Schlacht auf leeren Magen und mit schlechter Ausrüstung bereits eine verlorene Schlacht ist!\n\nDeshalb ist das Arathibecken so wichtig. Es gibt dort Schlüsselregionen, die essentielle Ressourcen bergen. Metalle, Waffen, Holz, ja, alles wird gebraucht und kann dort gefunden werden.\n\nDaher brauche ich Euch, <Name>. Begebt Euch ins Arathibecken und entscheidet die Schlacht für Euch, indem Ihr mehr Stützpunkte haltet als der Feind. Bringt mir als Beweis Eurer Taten eine Vorratskiste.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[8156] = {title = "Die Ressourcen des Arathibeckens", objective = "Gewinnt die Schlacht um das Arathibecken, raubt eine Arathivorratskiste und bringt sie Sergeant Maclear in der Zuflucht.", description = "Eine Schlacht muss mit Soldaten gewonnen werden, das wird Euch jeder Soldat gerne bestätigen. Man sagt auch, dass eine Schlacht auf leeren Magen und mit schlechter Ausrüstung bereits eine verlorene Schlacht ist!\n\nDeshalb ist das Arathibecken so wichtig. Es gibt dort Schlüsselregionen, die essentielle Ressourcen bergen. Metalle, Waffen, Holz, ja, alles wird gebraucht und kann dort gefunden werden.\n\nDaher brauche ich Euch, <Name>. Begebt Euch ins Arathibecken und entscheidet die Schlacht für Euch, indem Ihr mehr Stützpunkte haltet als der Feind. Bringt mir als Beweis Eurer Taten eine Vorratskiste.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[8157] = {title = "Noch mehr Vorratskisten", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8158] = {title = "Noch mehr Vorratskisten", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8159] = {title = "Noch mehr Vorratskisten", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8160] = {title = "Zerschlagt die Versorgungslinien Arathors", objective = "Entscheidet die Schlacht um das Arathibecken für Euch, erbeutet eine Arathivorratskiste und bringt sie Todespirscher Mortis in Hammerfall.", description = "Der Bund von Arathor scheut keine Mühen, um Arathi sein Eigen zu nennen. Sie und all die anderen Völker der Allianz strömen nun in diese entfernte Region, versessen darauf, ihren Gebietsanspruch von der Zuflucht aus zu erweitern. Wir müssen sie aufhalten, und das beste Mittel dies zu tun, ist ihre Vorräte zu stehlen.\n\nIhr könnt uns helfen, <Name>. Betretet das Arathibecken, das für seine reichen Minen, sein fruchtbares Land und seine geschickten Handwerker bekannt ist, und erobert jeden Stützpünkt, den Ihr könnt. Entscheidet die Schlacht auf diese Weise für Euch und kehrt dann mit den Ressourcen, die Ihr erbeuten konntet, zu mir zurück.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[8161] = {title = "Zerschlagt die Versorgungslinien Arathors", objective = "Entscheidet die Schlacht um das Arathibecken für Euch, erbeutet eine Arathivorratskiste und bringt sie Todespirscher Mortis in Hammerfall.", description = "Der Bund von Arathor scheut keine Mühen, um Arathi sein Eigen zu nennen. Sie und all die anderen Völker der Allianz strömen nun in diese entfernte Region, versessen darauf, ihren Gebietsanspruch von der Zuflucht aus zu erweitern. Wir müssen sie aufhalten, und das beste Mittel dies zu tun, ist ihre Vorräte zu stehlen.\n\nIhr könnt uns helfen, <Name>. Betretet das Arathibecken, das für seine reichen Minen, sein fruchtbares Land und seine geschickten Handwerker bekannt ist, und erobert jeden Stützpünkt, den Ihr könnt. Entscheidet die Schlacht auf diese Weise für Euch und kehrt dann mit den Ressourcen, die Ihr erbeuten konntet, zu mir zurück.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[8162] = {title = "Zerschlagt die Versorgungslinien Arathors", objective = "Entscheidet die Schlacht um das Arathibecken für Euch, erbeutet eine Arathivorratskiste und bringt sie Todespirscher Mortis in Hammerfall.", description = "Der Bund von Arathor scheut keine Mühen, um Arathi sein Eigen zu nennen. Sie und all die anderen Völker der Allianz strömen nun in diese entfernte Region, versessen darauf, ihren Gebietsanspruch von der Zuflucht aus zu erweitern. Wir müssen sie aufhalten, und das beste Mittel dies zu tun, ist ihre Vorräte zu stehlen.\n\nIhr könnt uns helfen, <Name>. Betretet das Arathibecken, das für seine reichen Minen, sein fruchtbares Land und seine geschickten Handwerker bekannt ist, und erobert jeden Stützpünkt, den Ihr könnt. Entscheidet die Schlacht auf diese Weise für Euch und kehrt dann mit den Ressourcen, die Ihr erbeuten konntet, zu mir zurück.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[8163] = {title = "Noch mehr Vorratskisten", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8164] = {title = "Noch mehr Vorratskisten", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
