[8166] = {title = "Die Schlacht um das Arathibecken!", objective = "Erobert die Mine, das Sägewerk, die Schmiede und die Farm und meldet Euch anschließend bei Feldmarschall Onslight in der Zuflucht.", description = "<Name>, die Schlacht im Arathibecken ist ein Kampf um Ressourcen und Territorien. Um unsere Truppen mit den dringend benötigten Rohstoffen und Vorräten zu versorgen, gilt es bestimmte Schlüsselpositionen zu besetzen und deren Ressourcen zu nutzen. Ich erteile Euch hiermit den Auftrag, die von unserem Stützpunkt am weitesten entfernten Schlüsselpostionen anzugreifen.\n\nErobert den Hof, die Mine, das Sägewerk und die Schmiede, sofern der Feind diese Positionen unter seiner Kontrolle hat. Sucht an jedem dieser Orte nach dem gegnerischen Banner und reißt es aus seiner Halterung!\n\nMeldet Euch wieder bei mir, wenn Euch das an allen vier Schlüsselpostionen gelungen ist.", progress = nil, completion = "&lt;Name&gt;, Ich erhielt Kunde von Euren Heldentaten im Arathibecken. Hervorragende Arbeit! Wenn sich noch mehr Freiwillige als ebenso fähig erweisen wie Ihr, bin ich zuversichtlich, dass wir eines Tages unsere Heimat zurückerobern werden.", rewards = "Ihr bekommt:\n\n"},
[8167] = {title = "Die Schlacht um das Arathibecken!", objective = "Erobert die Mine, das Sägewerk, die Schmiede und die Farm und meldet Euch anschließend bei Feldmarschall Onslight in der Zuflucht.", description = "<Name>, die Schlacht im Arathibecken ist ein Kampf um Ressourcen und Territorien. Um unsere Truppen mit den dringend benötigten Rohstoffen und Vorräten zu versorgen, gilt es bestimmte Schlüsselpositionen zu besetzen und deren Ressourcen zu nutzen. Ich erteile Euch hiermit den Auftrag, die von unserem Stützpunkt am weitesten entfernten Schlüsselpostionen anzugreifen.\n\nErobert den Hof, die Mine, das Sägewerk und die Schmiede, sofern der Feind diese Positionen unter seiner Kontrolle hat. Sucht an jedem dieser Orte nach dem gegnerischen Banner und reißt es aus seiner Halterung!\n\nMeldet Euch wieder bei mir, wenn Euch das an allen vier Schlüsselpostionen gelungen ist.", progress = nil, completion = "&lt;Name&gt;, Ich erhielt Kunde von Euren Heldentaten im Arathibecken. Hervorragende Arbeit! Wenn sich noch mehr Freiwillige als ebenso fähig erweisen wie Ihr, bin ich zuversichtlich, dass wir eines Tages unsere Heimat zurückerobern werden.", rewards = "Ihr bekommt:\n\n"},
[8168] = {title = "Die Schlacht um das Arathibecken!", objective = "Erobert die Mine, das Sägewerk, die Schmiede und die Farm und meldet Euch anschließend bei Feldmarschall Onslight in der Zuflucht.", description = "<Name>, die Schlacht im Arathibecken ist ein Kampf um Ressourcen und Territorien. Um unsere Truppen mit den dringend benötigten Rohstoffen und Vorräten zu versorgen, gilt es bestimmte Schlüsselpositionen zu besetzen und deren Ressourcen zu nutzen. Ich erteile Euch hiermit den Auftrag, die von unserem Stützpunkt am weitesten entfernten Schlüsselpostionen anzugreifen.\n\nErobert den Hof, die Mine, das Sägewerk und die Schmiede, sofern der Feind diese Positionen unter seiner Kontrolle hat. Sucht an jedem dieser Orte nach dem gegnerischen Banner und reißt es aus seiner Halterung!\n\nMeldet Euch wieder bei mir, wenn Euch das an allen vier Schlüsselpostionen gelungen ist.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[8169] = {title = "Die Schlacht um das Arathibecken!", objective = "Erobert die Mine, das Sägewerk, die Schmiede, die Farm und die Ställe und kehrt dann zu Todesmeister Dwire in Hammerfall zurück.", description = "Wie Ihr sicherlich schon gehört habt, entsendet der Bund von Arathor seine Truppen ins Arathibecken. Versessen auf Nahrung und Vorräte, können diese Idioten der Allianz es kaum erwarten, die riesigen Ressourcen des Beckens zu kontrollieren. Wir müssen ihnen zeigen, dass Arathi niemals wieder das Zuhause der Menschen sein wird!\n\nGeht ins Arathibecken und greift die Mine, das Sägewerk, die Schmiede und die Ställe an. Reißt die feindlichen Banner herunter und besetzt das Gebiet für die Horde.\n\nGeht, <Name>. Kehrt zu mir zurück, sobald Ihr Eure Aufgabe erfüllt habt.", progress = nil, completion = "Ein Späher der Entweihten hat mir bereits von Eurem Erfolg berichtet, &lt;Name&gt;. Gut gemacht.\n\nSo wie Ihr lernen werdet, die Schlacht ums Arathibecken zu gewinnen, müsst Ihr lernen, immer wachsam zu sein und jeden Expansionsversuch der Allianz zu zerschlagen. Wenn Ihr dies verinnerlicht, wird der Sieg unser sein.", rewards = "Ihr bekommt:\n\n"},
[8170] = {title = "Die Schlacht um das Arathibecken!", objective = "Erobert die Mine, das Sägewerk, die Schmiede, die Farm und die Ställe und kehrt dann zu Todesmeister Dwire in Hammerfall zurück.", description = "Wie Ihr sicherlich schon gehört habt, entsendet der Bund von Arathor seine Truppen ins Arathibecken. Versessen auf Nahrung und Vorräte, können diese Idioten der Allianz es kaum erwarten, die riesigen Ressourcen des Beckens zu kontrollieren. Wir müssen ihnen zeigen, dass Arathi niemals wieder das Zuhause der Menschen sein wird!\n\nGeht ins Arathibecken und greift die Mine, das Sägewerk, die Schmiede und die Ställe an. Reißt die feindlichen Banner herunter und besetzt das Gebiet für die Horde.\n\nGeht, <Name>. Kehrt zu mir zurück, sobald Ihr Eure Aufgabe erfüllt habt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[8171] = {title = "Die Schlacht um das Arathibecken!", objective = "Erobert die Mine, das Sägewerk, die Schmiede, die Farm und die Ställe und kehrt dann zu Todesmeister Dwire in Hammerfall zurück.", description = "Wie Ihr sicherlich schon gehört habt, entsendet der Bund von Arathor seine Truppen ins Arathibecken. Versessen auf Nahrung und Vorräte, können diese Idioten der Allianz es kaum erwarten, die riesigen Ressourcen des Beckens zu kontrollieren. Wir müssen ihnen zeigen, dass Arathi niemals wieder das Zuhause der Menschen sein wird!\n\nGeht ins Arathibecken und greift die Mine, das Sägewerk, die Schmiede und die Ställe an. Reißt die feindlichen Banner herunter und besetzt das Gebiet für die Horde.\n\nGeht, <Name>. Kehrt zu mir zurück, sobald Ihr Eure Aufgabe erfüllt habt.", progress = nil, completion = "Ein Späher der Entweihten hat mir bereits von Eurem Erfolg berichtet, &lt;Name&gt;. Gut gemacht.\n\nSo wie Ihr lernen werdet, die Schlacht ums Arathibecken zu gewinnen, müsst Ihr lernen, immer wachsam zu sein und jeden Expansionsversuch der Allianz zu zerschlagen. Wenn Ihr dies verinnerlicht, wird der Sieg unser sein.", rewards = "Ihr bekommt:\n\n"},
[8181] = {title = "Konfrontiert Yeh'kinya", objective = "Sprecht mit Yeh'kinya.", description = "Meine eingehende Beschäftigung mit den Mosh'aru-Schrifttafeln bestätigt den Verdacht auf schlechte Neuigkeiten, <Name>. Hakkars wahre Gestalt, der Gott selbst, kann mit genau dem Ei wiedergeboren werden, in dem Ihr ihn gefangen habt. Yeh'kinya sagte Euch, dass es seiner Macht Einhalt gebiete, aber eigentlich dient es seiner Wiederherstellung! Der Troll hat Euch in die Irre geführt!\n\nGeht zu Yeh'kinya und verlangt das Ei von ihm. Betet, dass wir Hakkars Rückkehr noch rechtzeitig verhindern können!", progress = nil, completion = "So, Ihr habt also mit dem alten Zwerg Ironboot gesprochen und die verlorenen Schrifttafeln von Mosh'aru entdeckt, ja? Dieser sich überall einmischende Schnüffler...\n\nEgal. Es ist zu spät, um diese Welt noch retten zu können.  Hakkar wurde wiedergeboren und seine Macht wächst weiter... tief in dem uralten Königreich der Trolle, Zul'Gurub! Er ist zurück! Und er wird Blut und Terror über die Welt bringen!\n\nIch danke Euch, &lt;Name&gt;. Mittels Eurer Hilfe wurde die Rückkehr des Seelenschinders beschleunigt!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAusgeblichener HakkariumhangZerlumptes Hakkaricape\n\nIhr bekommt außerdem:\n\n"},
[8182] = {title = "Die Hand von Rastakhan", objective = "Sprecht mit Molthor im Schlingendorntal.", description = "<Name>, unsere schlimmsten Befürchtungen sind eingetroffen. Laut der Legende herrschte der Seelenschinder in der alten Welt der Trolle mit uneingeschränkter Macht und ließ das Böse und Terror walten. Wenn er jetzt nicht aufgehalten werden kann, dann könnte sich seine neue Schreckensherrschaft in ganz Azeroth verbreiten!\n\nEs gibt eine Gesandtschaft zandalarianischer Trolle, die uns beim Eindämmen dieser finsteren Flut behilflich sein könnte. Sie kampieren auf der Insel Yojamba, fern der Küste des Schlingendorntals, westlich der Ruinen von Zul'Kunda. Sprecht mit ihrem Anführer Molthor und betet dafür, dass er weiß wie man Hakkar bezwingen kann.", progress = nil, completion = "Ihr wurdet von Ausgrabungsleiter Ironboot hierher gesandt? Seinesgleichen ist weise, es ist sogar noch weiser Euch zu mir zu senden, weil ich und die zandalarianischen Trolle möglicherweise wissen, wie man den Seelenschinder besiegt.\n\nSprecht mit den Trollen dieser Insel, beherzigt ihre Worte und bereitet Euch auf die Aufgabe vor &lt;Name&gt;, bevor Ihr in Blut baden werdet.", rewards = "Ihr bekommt:\n\n"},
[8183] = {title = "Das Herz von Hakkar", objective = "Bringt das Herz von Hakkar zu Molthor auf die Insel Yojamba.", description = "Das Herz von Hakkar brennt noch immer im Inneren. Obwohl der Seelenschinder besiegt ist, bleibt das Wesen seiner Macht doch noch in dem verfluchten Organ enthalten.", progress = "<Name>, der Gestank einer üblen Seelen umgibt Euch. Wurdet Ihr vom Seelenschinder verflucht?", completion = "Ah, das Herz von Hakkar. Also wurde der Seelenschinder besiegt! Die Welt ist gerettet!\n\n&lt;Name&gt;, Euer Dienst für uns kann nicht genug gerühmt werden. Ihr seid wahrlich ein Held!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZandalarianisches HeldenabzeichenZandalarianisches HeldenamulettZandalarianisches Heldenmedallion\n\nIhr bekommt außerdem:\n\n"},
[8184] = {title = "Präsenz der Macht", objective = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", description = nil, progress = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", completion = "Nutzt es weise, &lt;Klasse&gt;. Zeigt keine Gnade mit den Hakkari!", rewards = "Ihr bekommt:\n\nPräsenz der Macht"},
