[8381] = {title = "Kriegsausrüstung", objective = "Ein Krieg wird kommen, <Name>, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.\n\nSollte diese… diese Prophezeiung jemals wahr werden…\n\n\n\nDas könnte das Ende für unser aller Zukunft bedeuten.\n\nDiese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nCenarische ReservistenhoseSandwurmhauthandschuhe"},
[8382] = {title = "Kriegsausrüstung", objective = "Ein Krieg wird kommen, <Name>, und mit ihm unbeschreibliches Leiden. Ihr habt alles getan, um was man Euch hätte bitten können, dafür sollt Ihr belohnt werden.\n\nSollte diese… diese Prophezeiung jemals wahr werden…\n\n\n\nDas könnte das Ende für unser aller Zukunft bedeuten.\n\nDiese Ausrüstung wird von unschätzbarem Wert für Euren Feldzug in der Wüste sein.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nCenarische ReservistengamaschenSandsturmstiefel"},
[8383] = {title = "Vergesst das Alteractal nicht!", objective = "Die Schlacht im Alteractal tobt noch immer, <Name>! Habt Ihr schon Euren Teil zum Sieg beigetragen, <Name>?", description = nil, progress = "Die Schlacht im Alteractal tobt noch immer, <Name>! Habt Ihr schon Euren Teil zum Sieg beigetragen, <Name>?", completion = "Wieder einmal ehrt Ihr die Allianz, &lt;Name&gt;! Wenn wir so weiter machen, wird es nicht mehr lange dauern, bis die Horde vernichtet ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +398"},
[8384] = {title = "Inbesitznahme des Arathibeckens", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +82"},
[8385] = {title = "Gemeinsames Bestreben", objective = "Ah, <Name>. Ich hoffe Ihr gebt Eure Erfahrung auch noch auf weiteren Schlachtfeldern weiter. Viele unserer Jungens und Mädels sehen mit Ehrfurcht zu erfahrenen Veteranen wie Euch auf.", description = nil, progress = "Ah, <Name>. Ich hoffe Ihr gebt Eure Erfahrung auch noch auf weiteren Schlachtfeldern weiter. Viele unserer Jungens und Mädels sehen mit Ehrfurcht zu erfahrenen Veteranen wie Euch auf.", completion = "Ihr werdet Eurem Ruf gerecht, &lt;Name&gt;. Ohne Kämpfer wie Euch, würde die Allianz keine Chance gegen die barbarischen Streitkräfte der Horde haben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +2388"},
[8386] = {title = "Kampf um die Warsongschlucht", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +50"},
[8387] = {title = "Die Invasoren des Alteractals", objective = "Die Schlacht im Alteractal tobt noch immer, <Name>! Ihr müsst schnellstmöglich in das Alteractal zurückkehren und die Invasoren aus dem Gebiet der Frostwolf vertreiben.", description = nil, progress = "Die Schlacht im Alteractal tobt noch immer, <Name>! Ihr müsst schnellstmöglich in das Alteractal zurückkehren und die Invasoren aus dem Gebiet der Frostwolf vertreiben.", completion = "Gute Arbeit, &lt;Name&gt;! Ihr könnt stolz auf Euch sein. Die Invasoren der Allianz müssen aus dem Alteractal getrieben werden, koste es, was es wolle!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +398"},
[8388] = {title = "Große Ehre", objective = "Viele mutige Kämpfer sehen zu Euch auf, <Name>. Ihr seid auch weiterhin ein Vorbild für alle, die sich in den Schlachten gegen die Allianz schlagen. Welche Neuigkeiten bringt Ihr mir von Euren Reisen?", description = nil, progress = "Viele mutige Kämpfer sehen zu Euch auf, <Name>. Ihr seid auch weiterhin ein Vorbild für alle, die sich in den Schlachten gegen die Allianz schlagen. Welche Neuigkeiten bringt Ihr mir von Euren Reisen?", completion = "Ihr ehrt die Horde auch weiterhin, &lt;Name&gt;. Ich freue mich zu sehen, dass Ihr nicht nachgebt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +2388\n\nIhr bekommt:\n\n"},
[8389] = {title = "Schlacht der Warsongschlucht", objective = "Der Kampf um die Warsongschlucht geht weiter, <Name>. Tut alles, was in Eurer Macht steht, um die Schildwachen der Silverwing aus unserem Land zu vertreiben!", description = nil, progress = "Der Kampf um die Warsongschlucht geht weiter, <Name>. Tut alles, was in Eurer Macht steht, um die Schildwachen der Silverwing aus unserem Land zu vertreiben!", completion = "Gut gemacht, &lt;Klasse&gt;! Ihr habt der Horde geholfen ihr Eigentumsrecht an der Warsongschlucht zu sichern!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +50"},
[8390] = {title = "Eroberung des Arathibeckens", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +82"},
[8391] = {title = "Inbesitznahme des Arathibeckens", objective = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", description = nil, progress = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", completion = "Hervorragende Arbeit, &lt;Klasse&gt;. Eure Anstrengungen werden dazu beitragen, dass der Allianz auch weiterhin dringend benötigte Ressourcen zur Verfügung stehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +138"},
[8392] = {title = "Inbesitznahme des Arathibeckens", objective = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", description = nil, progress = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", completion = "Hervorragende Arbeit, &lt;Klasse&gt;. Eure Anstrengungen werden dazu beitragen, dass der Allianz auch weiterhin dringend benötigte Ressourcen zur Verfügung stehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +228"},
[8393] = {title = "Inbesitznahme des Arathibeckens", objective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen.", description = "Es gehört viel mehr dazu, einen Krieg zu gewinnen, als das bloße Überlisten des Gegners oder siegreiche Schlachten. Vielmehr erringt die Seite den Sieg, welche dauerhaft mehr Kriegsgüter als der Gegner produziert.\n\nDas Arathibecken, könnte sich als eine potentielle und äußerst ergiebige Ressourcenquelle für die Seite erweisen, die das Becken zuerst für sich beansprucht. Falls die Allianz den Sieg erringt, könnte man aus den Ressourcen hunderte neuer Waffen herstellen. Sollte allerdings die Horde gewinnen, würden diese Waffen zwar hergestellt, doch würde man sie anschließend auf uns richten! Jetzt ist es an der Zeit, die Allianz im Kampf um das Arathibecken zu unterstützen!", progress = "Sagt mir, welche Neuigkeiten gibt es von der Front?", completion = "Gute Arbeit, Soldat. Macht so weiter und die Horde wird schon bald die Flucht Richtung Orgrimmar antreten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +138\n\nIhr bekommt:\n\n"},
