[8395] = {title = "Inbesitznahme des Arathibeckens", objective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen.", description = "Es gehört viel mehr dazu, einen Krieg zu gewinnen, als das bloße Überlisten des Gegners oder siegreiche Schlachten. Vielmehr erringt die Seite den Sieg, welche dauerhaft mehr Kriegsgüter als der Gegner produziert.\n\nDas Arathibecken, könnte sich als eine potentielle und äußerst ergiebige Ressourcenquelle für die Seite erweisen, die das Becken zuerst für sich beansprucht. Falls die Allianz den Sieg erringt, könnte man aus den Ressourcen hunderte neuer Waffen herstellen. Sollte allerdings die Horde gewinnen, würden diese Waffen zwar hergestellt, doch würde man sie anschließend auf uns richten! Jetzt ist es an der Zeit, die Allianz im Kampf um das Arathibecken zu unterstützen!", progress = "Sagt mir, welche Neuigkeiten gibt es von der Front?", completion = "Gute Arbeit, Soldat. Macht so weiter und die Horde wird schon bald die Flucht Richtung Orgrimmar antreten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +378\n\nIhr bekommt:\n\n"},
[8396] = {title = "Inbesitznahme des Arathibeckens", objective = "Bringt 3 Ehrenabzeichen des Arathibeckens zu einem der Brigadegeneräle der Allianz, die außerhalb der Schlachtfelder stehen.", description = "Es gehört viel mehr dazu, einen Krieg zu gewinnen, als das bloße Überlisten des Gegners oder siegreiche Schlachten. Vielmehr erringt die Seite den Sieg, welche dauerhaft mehr Kriegsgüter als der Gegner produziert.\n\nDas Arathibecken, könnte sich als eine potentielle und äußerst ergiebige Ressourcenquelle für die Seite erweisen, die das Becken zuerst für sich beansprucht. Falls die Allianz den Sieg erringt, könnte man aus den Ressourcen hunderte neuer Waffen herstellen. Sollte allerdings die Horde gewinnen, würden diese Waffen zwar hergestellt, doch würde man sie anschließend auf uns richten! Jetzt ist es an der Zeit, die Allianz im Kampf um das Arathibecken zu unterstützen!", progress = "Sagt mir, welche Neuigkeiten gibt es von der Front?", completion = "Gute Arbeit, Soldat. Macht so weiter und die Horde wird schon bald die Flucht Richtung Orgrimmar antreten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +398\n\nIhr bekommt:\n\n"},
[8397] = {title = "Inbesitznahme des Arathibeckens", objective = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", description = nil, progress = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", completion = "Hervorragende Arbeit, &lt;Klasse&gt;. Eure Anstrengungen werden dazu beitragen, dass der Allianz auch weiterhin dringend benötigte Ressourcen zur Verfügung stehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +378"},
[8398] = {title = "Inbesitznahme des Arathibeckens", objective = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", description = nil, progress = "Der Krieg gegen die Horde verbraucht zusehends unsere Vorräte, <Name>. Es ist lebenswichtig, dass wir die Kontrolle über das Arathibecken halten können, um den Ressourcennachschub für unsere Kriegsproduktion aufrechtzuerhalten! Unsere Truppen im Arathibecken können jederzeit Eure Hilfe brauchen.", completion = "Hervorragende Arbeit, &lt;Klasse&gt;. Eure Anstrengungen werden dazu beitragen, dass der Allianz auch weiterhin dringend benötigte Ressourcen zur Verfügung stehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +398"},
[8399] = {title = "Kampf um die Warsongschlucht", objective = "Bringt 3 Ehrenabzeichen der Warsongschlucht zu einem Brigadegeneral der Allianz, außerhalb der Schlachtfelder.", description = "Die Schildwachen der Silverwing sind auf Grund der Zerstörung, die die Orcs im Wald anrichten, im Krieg mit der Warsongvorhut. Allerdings gibt es noch andere Gründe, als die bloße Liebe zu der Natur, für die Verteidigung von ausgerechnet diesem Wald.\n\nDer Wald bildet eine strategische Barriere, die es einfach macht, Ashenvale gegen jegliche Art von Großangriffen zu verteidigen. Ohne den Wald, würde Astranaar lediglich ein oder zwei Tage standhalten, bevor es vom Brachland einverleibt werden würde.\n\nSeid tapfer und schlagt Euch gegen die Warsongvorhut, <Name>! Für die Allianz!", progress = "Kehrt Ihr mit Neuigkeiten von der Front zurück, <Name>?", completion = "Gute Arbeit, &lt;Name&gt;. Dank Euch wird unsere natürliche Verteidigung in Ashenvale einen weiteren Tag überstehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +82\n\nIhr bekommt:\n\n"},
[8400] = {title = "Kampf um die Warsongschlucht", objective = "Bringt 3 Ehrenabzeichen der Warsongschlucht zu einem Brigadegeneral der Allianz, außerhalb der Schlachtfelder.", description = "Die Schildwachen der Silverwing sind auf Grund der Zerstörung, die die Orcs im Wald anrichten, im Krieg mit der Warsongvorhut. Allerdings gibt es noch andere Gründe, als die bloße Liebe zu der Natur, für die Verteidigung von ausgerechnet diesem Wald.\n\nDer Wald bildet eine strategische Barriere, die es einfach macht, Ashenvale gegen jegliche Art von Großangriffen zu verteidigen. Ohne den Wald, würde Astranaar lediglich ein oder zwei Tage standhalten, bevor es vom Brachland einverleibt werden würde.\n\nSeid tapfer und schlagt Euch gegen die Warsongvorhut, <Name>! Für die Allianz!", progress = "Kehrt Ihr mit Neuigkeiten von der Front zurück, <Name>?", completion = "Gut gemacht, &lt;Name&gt;! Ihr habt viel für die Allianz geleistet.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +138\n\nIhr bekommt:\n\n"},
[8401] = {title = "Kampf um die Warsongschlucht", objective = "Bringt 3 Ehrenabzeichen der Warsongschlucht zu einem Brigadegeneral der Allianz, außerhalb der Schlachtfelder.", description = "Die Schildwachen der Silverwing sind auf Grund der Zerstörung, die die Orcs im Wald anrichten, im Krieg mit der Warsongvorhut. Allerdings gibt es noch andere Gründe, als die bloße Liebe zu der Natur, für die Verteidigung von ausgerechnet diesem Wald.\n\nDer Wald bildet eine strategische Barriere, die es einfach macht, Ashenvale gegen jegliche Art von Großangriffen zu verteidigen. Ohne den Wald, würde Astranaar lediglich ein oder zwei Tage standhalten, bevor es vom Brachland einverleibt werden würde.\n\nSeid tapfer und schlagt Euch gegen die Warsongvorhut, <Name>! Für die Allianz!", progress = "Kehrt Ihr mit Neuigkeiten von der Front zurück, <Name>?", completion = "Gut gemacht, &lt;Name&gt;! Ihr habt viel für die Allianz geleistet.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +228\n\nIhr bekommt:\n\n"},
[8402] = {title = "Kampf um die Warsongschlucht", objective = "Bringt 3 Ehrenabzeichen der Warsongschlucht zu einem Brigadegeneral der Allianz, außerhalb der Schlachtfelder.", description = "Die Schildwachen der Silverwing sind auf Grund der Zerstörung, die die Orcs im Wald anrichten, im Krieg mit der Warsongvorhut. Allerdings gibt es noch andere Gründe, als die bloße Liebe zu der Natur, für die Verteidigung von ausgerechnet diesem Wald.\n\nDer Wald bildet eine strategische Barriere, die es einfach macht, Ashenvale gegen jegliche Art von Großangriffen zu verteidigen. Ohne den Wald, würde Astranaar lediglich ein oder zwei Tage standhalten, bevor es vom Brachland einverleibt werden würde.\n\nSeid tapfer und schlagt Euch gegen die Warsongvorhut, <Name>! Für die Allianz!", progress = "Kehrt Ihr mit Neuigkeiten von der Front zurück, <Name>?", completion = "Gut gemacht, &lt;Name&gt;! Ihr habt viel für die Allianz geleistet.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +378\n\nIhr bekommt:\n\n"},
[8403] = {title = "Kampf um die Warsongschlucht", objective = "Bringt 3 Ehrenabzeichen der Warsongschlucht zu einem Brigadegeneral der Allianz, außerhalb der Schlachtfelder.", description = "Die Schildwachen der Silverwing sind auf Grund der Zerstörung, die die Orcs im Wald anrichten, im Krieg mit der Warsongvorhut. Allerdings gibt es noch andere Gründe, als die bloße Liebe zu der Natur, für die Verteidigung von ausgerechnet diesem Wald.\n\nDer Wald bildet eine strategische Barriere, die es einfach macht, Ashenvale gegen jegliche Art von Großangriffen zu verteidigen. Ohne den Wald, würde Astranaar lediglich ein oder zwei Tage standhalten, bevor es vom Brachland einverleibt werden würde.\n\nSeid tapfer und schlagt Euch gegen die Warsongvorhut, <Name>! Für die Allianz!", progress = "Kehrt Ihr mit Neuigkeiten von der Front zurück, <Name>?", completion = "Gut gemacht, &lt;Name&gt;! Ihr habt viel für die Allianz geleistet.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +398\n\nIhr bekommt:\n\n"},
[8404] = {title = "Kampf um die Warsongschlucht", objective = "Vergesst nicht, dass es bei dem Kampf um die Warsongschlucht um mehr als das Beschützen von Bäumen geht. Es gilt eine natürliche Barriere zwischen Ashenvale und dem Brachland zu erhalten. Habt Ihr Neuigkeiten vom Schlachtfeld, <Name>?", description = nil, progress = "Vergesst nicht, dass es bei dem Kampf um die Warsongschlucht um mehr als das Beschützen von Bäumen geht. Es gilt eine natürliche Barriere zwischen Ashenvale und dem Brachland zu erhalten. Habt Ihr Neuigkeiten vom Schlachtfeld, <Name>?", completion = "Gute Arbeit, &lt;Name&gt;. Dank Euch wird unsere natürliche Verteidigung in Ashenvale einen weiteren Tag überstehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +82"},
[8405] = {title = "Kampf um die Warsongschlucht", objective = "Vergesst nicht, dass es bei dem Kampf um die Warsongschlucht um mehr als das Beschützen von Bäumen geht. Es gilt eine natürliche Barriere zwischen Ashenvale und dem Brachland zu erhalten. Habt Ihr Neuigkeiten vom Schlachtfeld, <Name>?", description = nil, progress = "Vergesst nicht, dass es bei dem Kampf um die Warsongschlucht um mehr als das Beschützen von Bäumen geht. Es gilt eine natürliche Barriere zwischen Ashenvale und dem Brachland zu erhalten. Habt Ihr Neuigkeiten vom Schlachtfeld, <Name>?", completion = "Gute Arbeit, &lt;Name&gt;. Dank Euch wird unsere natürliche Verteidigung in Ashenvale einen weiteren Tag überstehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +138\n\nIhr bekommt:\n\n"},
