[8408] = {title = "Kampf um die Warsongschlucht", objective = "Vergesst nicht, dass es bei dem Kampf um die Warsongschlucht um mehr als das Beschützen von Bäumen geht. Es gilt eine natürliche Barriere zwischen Ashenvale und dem Brachland zu erhalten. Habt Ihr Neuigkeiten vom Schlachtfeld, <Name>?", description = nil, progress = "Vergesst nicht, dass es bei dem Kampf um die Warsongschlucht um mehr als das Beschützen von Bäumen geht. Es gilt eine natürliche Barriere zwischen Ashenvale und dem Brachland zu erhalten. Habt Ihr Neuigkeiten vom Schlachtfeld, <Name>?", completion = "Gute Arbeit, &lt;Name&gt;. Dank Euch wird unsere natürliche Verteidigung in Ashenvale einen weiteren Tag überstehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +398"},
[8409] = {title = "Verdorbenes Bier", objective = "Kehrt zur Ruferin der Dunkelheit Yanka beim Fest des Weidenmanns in Tirisfal zurück.", description = "Die faulen Eier wurden wie geplant in den Braukessel geworfen. Zukünftige Ladungen Bier des Gasthauses von Southshore sind somit erfolgreich verdorben worden!\n\nIhr solltert jetzt zurück zu Ruferin der Dunkelheit Yanka beim Fest des Weidenmanns in Tirisfal gehen und ihr von Eurem Erfolg berichten.", progress = nil, completion = "Ah, Erfolg! Ihr habt wahren Schlotternachtsgeist bewiesen - Geist eines VERLASSENEN sollte ich wohl eher sagen!\n\n&lt;Ruferin der Dunkelheit Yanka lacht und reibt sich die Hände.&gt;\n\nIch lache mir ins Fäustchen, dass Southshore sich jetzt an verdorbenem Bier erfeuen darf! Hier habt Ihr Eure Süßigkeiten. Ich bin mir sicher, dass Ihr eine gute Verwendung dafür finden werden!", rewards = "Ihr bekommt:\n\nKürbisdrops der Schlotternächte"},
[8410] = {title = "Elementarbeherrschung", objective = "Bath'rah der Windbehüter möchte, dass Ihr jeweils eine Probe Luft, Feuer, Erde und Wasser für ihn sammelt.", description = "Bath'rah der Windbehüter sucht nach einem Schamanen von Eurer Weisheit. Als Zeichen Eurer Bereitschaft bittet er Euch, ihm Proben eines jeden Elements zu bringen.\n\nUm Bath'rah zu finden, begebt Euch zu dem Fluss östlich von Tarrens Mühle. Folgt seinem Verlauf Richtung Norden, irgendwann trefft Ihr auf die Ruinen, in denen sich Bath'rah niedergelassen hat.", progress = "Was habt Ihr mir mitgebracht, <Klasse>?", completion = "Hey, gut gemacht. Unterhalten wir uns jetzt…", rewards = "Ihr bekommt:\n\n"},
[8411] = {title = "Die Beherrschung der Elemente", objective = "Bringt Bath'rah dem Windbehüter die Elemente Erde, Luft, Feuer und Wasser.", description = "Willkommen, mein Freund. Bringt mir zuerst die Elemente und dann unterhalten wir uns.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[8412] = {title = "Geistertotem", objective = "Bringt Bath'rah dem Windbehüter die Komponenten für das Geistertotem.", description = "Die Elementare an diesem Ort haben sich gegen mich gewendet.\n\nIhr kennt Euch mit den Mächten der Totems besser als jeder andere aus und ich brauche jetzt ein Geistertotem zu meinem Schutz. Wir haben bereits die Elemente, jetzt brauchen wir etwas mit noch mehr Natur. Etwas noch Wilderes.\n\nIn den westlichen Pestländer könnt Ihr Bären für Klauen und Spinnen für Augen töten. Mit etwas Glück, könnt Ihr beides auch bei den dort lebenden Aasgeiern finden, sie fressen alles.", progress = "Die Geister wissen, was wir vorhaben und haben versucht, mich zu töten! Ich hoffe Ihr habt die Komponenten.", completion = "Gut, mein Freund! Versuchen wir es…", rewards = "Ihr bekommt:\n\n"},
[8413] = {title = "Die Macht des Voodoos", objective = "Bringt Bath'rah dem Windbehüter die Voodoofedern.", description = "Das Geistertotem alleine ist nicht stark genug. Um erfolgreich zu sein, benötigen wir noch etwas Voodoomagie.\n\nDie Trolle im versunkenen Tempel besitzen Federn, die von mächtiger Voodoomagie erfüllt sind. Begebt Euch dorthin und besiegt Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Mit Ihren Federn haben wir genug Macht, um ein starkes Geistertotem zu formen.", progress = "Wo sind die Federn, mein Freund?", completion = "Es ist Zeit, dass dieser Troll eine ganze Nacht Ruhe bekommt! Das Geistertotem wird über mich wachen\n\nIch habe eine ganze Weile Dinge gesammelt, vielleicht möchtet Ihr ja was für all' Eure Mühe?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAzuritfäusteEntzückter WassergeistWildstab\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[8414] = {title = "Austreibung des Bösen", objective = "Sammelt 20 Geißelsteine des Dieners und bringt sie zu Hohepriester Thel'danis in den westlichen Pestländern.", description = "Seid gegrüßt, <Klasse>. Kreuzfahrer wie Ihr werden in solch abgeschiedenen Gegenden gerne gesehen.\n\nEure heilige Stärke wird gebraucht, um uns bei der Vernichtung der unzähligen Untoten hier zu helfen. Genau genommen bräuchten wir Euch, um eine große Anzahl von Geißelsteinen zu sammeln und sie anschließend zu Hohepriester Thel'danis zu bringen. Der Hohepriester bewacht Uthers Grabmal in Sorrow Hill, nicht weit von hier.\n\nNur jemand mit einer Anstecknadel der Argentumdämmerung kann darauf hoffen Geißelsteine zu finden, sprecht also mit Offizier Pureheart, wenn Ihr noch keine besitzt.", progress = "Habt Ihr mir Böses gebracht?", completion = "Es ist ein Risiko Böses aus einem Geißelstein zu treiben, da es die Aufmerksamkeit von Untoten bis auf unzählige Kilometer erweckt. Ihr seid jedoch stark im Licht, &lt;Name&gt;, und ich sorge mich nicht um Euch...", rewards = "Ihr bekommt:\n\n"},
[8415] = {title = "Chillwindspitze", objective = "Sprecht mit Kommandanten Ashlam Valorfist an der Chillwindspitze.", description = "Kommandant Ashlam Valorfist sucht nach einem Paladin Euer Reinheit und Euren Mutes, <Name>. Ihr könnt ihn an der Chillwindspitze im Süden der westlichen Pestländer finden. Sucht nach ihm und helft ihm im Namen des Lichts!", progress = nil, completion = "Na dann, &lt;Klasse&gt;! Jetzt zeigt mal, was Ihr könnt.", rewards = "Ihr bekommt:\n\n"},
[8416] = {title = "Gereinigte Geißelsteine", objective = "Bringt den gereinigten Geißelstein zu Kommandant Ashlan Valorfist an der Chillwindspitze.", description = "Das Böse wurde aus diesen Steinen getrieben, <Name>.\n\nIch weiß über Kommandant Ashlams Pläne Bescheid, er wird nur nach einem einzigen, gereinigten Geißelstein verlangen. Bringt ihn zu ihm, damit wir die Geißel ins Feuer der Gerechtigkeit tauchen können.", progress = "Konnte Thel'danis die Geißelsteine reinigen?", completion = "Ihr habt meine Befehle ohne weiteres Fragen befolgt, &lt;Name&gt;.\n\nIhr scheint Vertrauen bewiesen zu haben. Vielleicht kann ich Euch jetzt mehr über unsere Pläne verraten.", rewards = "Ihr bekommt:\n\n"},
[8417] = {title = "Ein geplagter Geist", objective = "Sprecht mit dem gefallenen Helden der Horde am Eingang zu den verwüsteten Landen.", description = "In den verwüsteten Landen gibt es einen geplagten Geist, der einst ein großer Held der Horde war. Die Ehre eines Kriegers stirbt nicht mit seinem Körper und es würde für Euch von Wert sein mit ihm zu sprechen.", progress = nil, completion = "So, Ihr seid also gekommen um meinen Schmerz zu lindern. Ich wünschte, Ihr könntet mich einfach niederstrecken, aber es ist nicht so simpel...", rewards = "Ihr bekommt:\n\n"},
[8418] = {title = "Erschaffung des Steins der Macht", objective = "Bringt die Voodoofedern zu Ashlam Valorfist.", description = "Jetzt müssen wir die gereinigten Geißelsteine kombinieren und eine Waffe herstellen, die die Reihen der Untoten erschüttert. Das ist keine einfache Aufgabe, <Name>. Nur die Trolle des versunkenen Tempels besitzen diese Art seltener Magie, die fähig ist, das Böse von etwas gegen sich selbst zu richten.\n\nIm Tempel sind die Trolle bekannt als Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Verspürt keine Reue für ihre verderbten Seelen... sie sind nicht frei von Bösem.", progress = "Habt Ihr die elenden Trolle getötet?", completion = "Das ist ausgezeichnet, &lt;Name&gt;. Ich könnte sagen, dass ich überrascht bin, allerdings habe nicht daran gezweifelt, dass Ihr uns nicht enttäuschen werdet.\n\nEs ist mir eine Ehre Euch einen der heiligen Steine der Macht zu überreichen. Verwendet ihn weise.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLichtgeschmiedete KlingeGeweihte KugelSiegelring der Ritterlichkeit\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\nHeiliger Stein der Macht"},
[8419] = {title = "Die Bitte eines Wichtels", objective = "Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald.", description = "<Name>, ein Wichtel im Teufelswald namens Impsy hat nach Euch verlangt. Seine Bitte ist etwas merkwürdig, da er möchte, dass Ihr ihm ein Stück Teufelsstoff als Zeichen des \"guten Willens\" bringt. Bedenkt man die Macht, die Ihr bereits als Hexenmeister besitzt, kann ich nur vermuten, dass Ihr wisst, dass die Satyrn des Teufelswalds diesen Teufelsstoff bei sich tragen.\n\nIhr findet Impsy nördlich der Blutgiftfälle, von denen ich hörte, dass sie um diese Jahreszeit recht schön sein sollen.", progress = "Habt Ihr den Teufelsstoff?", completion = "Ah, wie großartig Ihr doch seid!\n\n&lt;Impsy drückt den Teufelsstoff an sein Gesicht.&gt;\n\nOh, wie sehr ich dieses Gefühl liebe, dieses sanfte Brennen auf der Haut und diese Wallungen des Bösen, die durch den Geist huschen...", rewards = "Ihr bekommt:\n\n"},
[8420] = {title = "Heiß und brennend", objective = "Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald.", description = "Vielleicht klingt es ja etwas komisch bei einem Wichtel, aber ich würde gerne meinen eigenen Begleiter haben. Das hätte ich wirklich gerne. Es ist nicht fair, dass Niby mich hat und ich niemanden!\n\nEs braucht ja gar nicht lebendig zu sein. Ich bräuchte etwas, um mit der Anfertigung beginnen zu können, zum Beispiel etwas Teufelsstoff. Die Satyrn hier im Teufelswald haben manchmal Teufelsstoff, Ihr müsstet also nur genug von ihnen töten, um welchen zu finden. Das hört sich doch gut an, oder?", progress = "Habt Ihr den Teufelsstoff?", completion = "Wow! Ihr seid wirklich total freundlich. Besonders für einen &lt;Klasse&gt;!\n\n\n\nOh, wie sehr ich dieses Gefühl liebe, dieses sanfte Brennen auf der Haut und diese Wallungen des Bösen, die durch den Geist huschen...", rewards = "Ihr bekommt:\n\n"},
[8421] = {title = "Das richtige Zeug", objective = "Bringt 10 Stück faules Holz und 4 Blutgiftessenzen zu Impsy im Teufelswald.", description = "Jetzt, da ich meinen Teufelsstoff habe, kann ich wirklich mit der Anfertigung *meines* Begleiters beginnen.\n\nIch werde etwas für die Augen brauchen. Vielleicht könnt Ihr mir etwas faules Holz vom Stamm der Eisenstämme besorgen, damit ich daraus ein Paar wunderschöne Augen schnitzen kann. Ihr findet sie im Norden, im Eisenwald.\n\nIch brauche auch etwas Blutgiftessenz, um meinem Begleiter diesen neuen dämonischen Duft zu verleihen. Die besudelten Brühschlammer haben diese Essenz und Ihr könnt sie gleich hier in der Nähe von Niby und mir finden.", progress = "Habt Ihr das Zeug?", completion = "Dies wird seinen Zweck bestens erfüllen.", rewards = "Ihr bekommt:\n\n"},
[8422] = {title = "Federn von Trollen", objective = "Bringt 6 Voodoofedern von den Trollen aus dem versunkenen Tempel.", description = "Mein Begleiter ist fast fertig. Jetzt brauche ich nur noch etwas als Füllmaterial.\n\nNur die Voodoofedern von den Trollen aus dem versunkenen Tempel sind dafür geeignet. Sie heißen Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Tötet sie. Tötet sie alle.\n\nDies ist keine gewöhnliche Aufgabe <Name>, also werde ich Eure Bemühungen belohnen, indem ich Euch etwas von Niby gebe -- er wird es sowieso nicht mehr brauchen.", progress = "Habt Ihr die Federn? Mein Begleiter braucht eine Füllung!", completion = "Wunderbar, jetzt ist mein Begleiter komplett!\n\n&lt;Impsy stopft die Puppe schnell aus und umarmt sie auf dämonische Weise.&gt;\n\nOh, was für einen merwürdigen Nebeneffekt diese Voodoofedern doch haben...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSeelenernterAbysssplitterRoben der Knechtschaft\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[8423] = {title = "Kriegerverwandtschaft", objective = "Tötet 7 Hölleneber in den verwüsteten Landen und kehrt zu dem gefallenen Helden der Horde zurück.", description = "<Der Held betrachtet Euch.>\n\nIhr seid ein <Klasse>, ohne Zweifel. Ich würde Euch um eine ehrenhafte Aufgabe bitten, aber zuerst muss ich Eure Stärke testen.\n\nMan sagt, dass Rexxar die Schärfe seiner Klingen misst, indem er einen Hölleneber mit nur einem einzigen, schnellen Schlag erlegt. Jetzt werde ich Eure Stärke auf die gleiche Art messen.", progress = nil, completion = "Ich brauche keinen Beweis für Eure Taten, &lt;Klasse&gt;. Ich kann es an dem entschlossenen Ausdruck in Eurem Gesicht erkennen.", rewards = "Ihr bekommt:\n\n"},
[8424] = {title = "Krieg den Schattenanbetern", objective = "Merzt die Schattenanbeter in den verwüsteten Landen aus und kehrt zum gefallenen Helden der Horde zurück.", description = "Die weiterhin bestehende Gegenwart der Schattenanbeter in den verwüsteten Landen ist schmerzhaft für mich. Ihre dunklen Rituale und Zauber bereiten mir heute mehr Qualen als es zu meinen Lebzeiten je etwas hätte tun können.\n\nIch kann ihnen mit Eurer Hilfe eine schmerzhafte Botschaft überbringen. Zieht hinfort und lasst meinen Zorn sprechen.", progress = "Die Schattenanbeter lassen sich nicht so leicht unterkriegen, nicht wahr? Ihr seid jedoch ein <Klasse> und werdet entweder triumphieren oder zumindest bei dem Versuch sterben.", completion = "Ihr habt meinen Schmerz bereits überwältigt und mich geehrt. Ich danke Euch, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"},
[8425] = {title = "Voodoofedern", objective = "Bringt die Voodoofedern der Trolle im versunkenen Tempel zu dem gefallenen Helden der Horde.", description = "Eure Ehre hat mir zu ein wenig Frieden verholfen. Es ist mehr als gerecht, dass ich Euch etwas im Gegenzug dafür gebe.\n\nMeine Waffen und meine Rüstung waren zu meinen Lebzeiten prächtig, aber jetzt habe ich keine Verwendung mehr dafür. In Euren Händen würden sie einem besseren Zweck dienen.\n\nReist zu dem versunkenen Tempel und tötet die Trollwächter Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Sie tragen magische Federn, die meinen physikalischen Körper lange genug neubilden können, damit ich Euch belohnen kann.", progress = "Seid Ihr schon zurück? Zeit ist für mich nicht mehr, was sie einst für mich war, vielleicht habt Ihr ja wirklich schon einen langen Ausflug hinter Euch...", completion = "Endlich kann ich die kalte Berührung von Stahl wieder spüren, auch wenn es nur für einen Moment ist.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVisier des ZornsDiamantenfläschchenKlingenstahlschultern\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[8426] = {title = "Schlacht der Warsongschlucht", objective = "Bringt 3 Ehrenabzeichen der Warsongschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", description = "Der Kampf gegen die Schildwachen der Silverwing in der Warsongschlucht ist von großer Bedeutung. Unter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die Allianz der Horde eines unserer größten Holzvorkommen streitig zu machen.\n\nLasst dies nicht zu, <Name>! Kommt zu mir mit einem Beweis für ehrvolle Taten im Namen der Horde zurück!", progress = "Überbringt Ihr Neuigkeiten von der Warsongschlucht, <Name>?", completion = "Ausgezeichnet! Ihr habt Euch als ehrvoll erwiesen, indem Ihr unsere Unternehmungen in der Warsongschlucht verteidigt habt! Möge sich die Kunde von Eurer Ehrenhaftigkeit weit in unserem Land verbreiten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +82\n\nIhr bekommt:\n\n"},
[8427] = {title = "Schlacht der Warsongschlucht", objective = "Bringt 3 Ehrenabzeichen der Warsongschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", description = "Der Kampf gegen die Schildwachen der Silverwing in der Warsongschlucht ist von großer Bedeutung. Unter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die Allianz der Horde eines unserer größten Holzvorkommen streitig zu machen.\n\nLasst dies nicht zu, <Name>! Kommt zu mir mit einem Beweis für ehrvolle Taten im Namen der Horde zurück!", progress = "Überbringt Ihr Neuigkeiten von der Warsongschlucht, <Name>?", completion = "Ausgezeichnet! Ihr habt Euch als ehrvoll erwiesen, indem Ihr unsere Unternehmungen in der Warsongschlucht verteidigt habt! Möge sich die Kunde von Eurer Ehrenhaftigkeit weit in unserem Land verbreiten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +138\n\nIhr bekommt:\n\n"},
[8428] = {title = "Schlacht der Warsongschlucht", objective = "Bringt 3 Ehrenabzeichen der Warsongschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", description = "Der Kampf gegen die Schildwachen der Silverwing in der Warsongschlucht ist von großer Bedeutung. Unter dem Vorwand einen Wald zu beschützen, der ihnen nicht gehört, versucht die Allianz der Horde eines unserer größten Holzvorkommen streitig zu machen.\n\nLasst dies nicht zu, <Name>! Kommt zu mir mit einem Beweis für ehrvolle Taten im Namen der Horde zurück!", progress = "Bringt 3 Ehrenabzeichen der Warsongschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder.", completion = "Ausgezeichnet! Ihr habt Euch als ehrvoll erwiesen, indem Ihr unsere Unternehmungen in der Warsongschlucht verteidigt habt! Möge sich die Kunde von Eurer Ehrenhaftigkeit weit in unserem Land verbreiten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +228\n\nIhr bekommt:\n\n"},
