[8431] = {title = "Schlacht der Warsongschlucht", objective = "Der Kampf um die Warsongschlucht geht weiter, <Name>. Tut alles, was in Eurer Macht steht, um die Schildwachen der Silverwing aus unserem Land zu vertreiben!", description = nil, progress = "Der Kampf um die Warsongschlucht geht weiter, <Name>. Tut alles, was in Eurer Macht steht, um die Schildwachen der Silverwing aus unserem Land zu vertreiben!", completion = "Gut gemacht, &lt;Klasse&gt;! Ihr habt der Horde geholfen ihr Eigentumsrecht an der Warsongschlucht zu sichern!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEhrenpunkte +82"},
