[8569] = {title = "Vergangene Bemühungen in der Warsongschlucht", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEhrenabzeichen der Warsongschlucht"},
[8570] = {title = "Vergangene Bemühungen in der Warsongschlucht", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEhrenabzeichen der Warsongschlucht"},
[8572] = {title = "Schlachtrüstung des Veteranen", objective = "Bringt 7 cenarische Gefechtsabzeichen, 4 cenarische Versorgungsabzeichen und 4 cenarische Strategieabzeichen zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Burg Cenarius erhalten habt, dienen zu weit mehr als der Angeberei, <Name>.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErdanmutBand der ErdmachtErdmachtweste"},
[8573] = {title = "Schlachtrüstung des Feldherrn", objective = "Bringt 15 cenarische Gefechtsabzeichen, 20 cenarische Versorgungsabzeichen, 20 cenarische Strategieabzeichen und 1 Mal des Cenarius zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Burg Cenarius erhalten habt, dienen zu weit mehr als der Angeberei, <Name>.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.", progress = "Es ist unsere beste Absicht, unsere treuesten Verbündeten gut mit Ausrüstung zu versorgen, <Name>.", completion = "Gute Arbeit, &lt;Name&gt;. Bitte nehmt dies im Namen des Zirkels des Cenarius an. Ihr habt es Euch wahrhaftig verdient!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFaust des CenariusZorn des CenariusErdschlag\n\nIhr bekommt außerdem:\n\n"},
[8574] = {title = "Schlachtrüstung des Gefolgsmanns", objective = "Bringt 15 cenarische Gefechtsabzeichen, 20 cenarische Versorgungsabzeichen, 17 cenarische Strategieabzeichen und 1 Mal von Remulos zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Windruferin Proudhorn erhalten habt, dienen zu weit mehr als der Angeberei, <Name>.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.", progress = "Es ist unsere beste Absicht, unsere treuesten Verbündeten gut mit Ausrüstung zu versorgen, <Name>.", completion = "Gute Arbeit, &lt;Name&gt;. Bitte nehmt dies im Namen des Zirkels des Cenarius an. Ihr habt es Euch wahrhaftig verdient!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTiefsteinarmschienenKugel der ErdruheFelszornarmschienenMacht des Cenarius"},
[8575] = {title = "Azuregos' magisches Buch", objective = "Bringt Azuregos' magisches Buch zu Narain Soothfancy in Tanaris.", description = "Ihr könnt kein einziges Wort in diesem Buch verstehen. Ihr wisst nicht einmal in welcher Sprache es geschrieben wurde!", progress = "Ooooh! Ein vor Magie pulsierendes Ding! Für mich?", completion = "&lt;Narain studiert eifrig das Geschriebene.&gt;\n\nAußerordentlich, &lt;Volk&gt;! Was ist das? Ich kann kein Wort Drachisch lesen.", rewards = "Ihr bekommt:\n\n"},
[8576] = {title = "Übersetzung des Buchs", objective = "Eins nach dem anderen, <Name>! Wir müssen herausfinden was Azuregos in dieses Buch geschrieben hat.\n\nEr hat Euch also gesagt, dass Ihr eine Arkanitboje herstellen sollt und dass dies hier der Bauplan dafür ist? Komisch, dass er das in Drachisch schreiben würde. Der alte Fuchs weiß doch, dass ich diesen Quatsch nicht lesen kann.\n\nWenn das klappen soll, dann werde ich meine Wahrsagebrille, ein 500 Pfund-Hühnchen und Band 2 von \"Drachisch für Dummies\" benötigen. Nicht unbedingt in dieser Reihenfolge.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[8577] = {title = "Stewvul, Ex-B.F.F.I.", objective = "Narain Soothfancy möche, dass Ihr seinen Ex-'Besten Freund für immer' (B.F.F.I.) Stewvul ausfindig macht. Nehmt ihm die gestohlene Wahrsagerbrille ab und bringt sie Narain zurück.", description = "Tja, um irgendetwas übersetzen zu können, brauche ich meine Wahrsagerbrille. Unglücklicherweise wurde sie vor einiger Zeit von meinem Ex-'Besten Freund für immer', Stewvul gestohlen. Er hat mir mein Herz fünffach gebrochen und mich dann hier verrotten lassen.\n\nMit Hilfe meiner Kristallkugel konnte ich seinen momentanen Aufenthaltsort einigermaßen genau bestimmen. Er ist entweder am Greymane-Wall im Silberwald oder in irgend so einer Portaldimension in der Scherbenwelt, die 'grad von der brennenden Legion überrannt wird. Schätze, es liegt jetzt an Euch, ihn ausfindig zu machen und mir meine Brille zurückzubringen, <Name>!", progress = nil, completion = "Ich kann es nicht glauben, dass er mich gefunden hat. Dabei war ich mir so sicher, dass er meine Spur verloren hat, als ich in der Scherbenwelt war. Ich gehe nicht zu ihm zurück, &lt;Volk&gt;! Niemals und nie wieder! Ich habe genug davon, sein 'Bester Freund für immer' zu sein, oder sollte ich besser sagen, sein Vollzeitsklave.", rewards = "Ihr bekommt:\n\n"},
[8578] = {title = "Wahrsagerbrille? Kein Problem!", objective = "Findet Narains Wahrsagerbrille und bringt sie Narain Soothfancy in Tanaris.", description = "<Ihr hört einen erleichterten Seufzer aus der Kiste.>\n\nIhr wollt nur seine Wahrsagerbrille? Großartig! Kein Problem, gebt mir kurz 'ne Minute, um… Hey! Wo zur verdammten…!\n\nEs gibt eine schlechte und eine verdammt schlechte Nachricht. Die Schlechte ist, dass ich die Brille verloren habe. Die viel schlimmere Nachricht ist, ich habe sie letzten Monat beim Herumstreifen im geschmolzenen Kern irgendwo liegen lassen. Japp, der geschmolzene Kern... Tja, so etwas passiert. Tschüss!", progress = "Der geschmolzene Kern, huh? Hoffentlich kriege ich die Brille in einem Stück wieder!", completion = "Fantastisch! Mhmm, wo habe ich das 500 Pfund-Hühnchen schon wieder hingetan und Band 2 von 'Drachisch für Dummies'??? Oh, hier ist eine kleine Belohnung für Eure harte Arbeit!", rewards = "Ihr bekommt:\n\nErheblicher Verjüngungstrank"},
[8579] = {title = "Sterbliche Helden", objective = "Wir spüren die Anwesenheit unserer versklavten Brüder tief im Innern von Ahn'Qiraj; dennoch wäre selbst eine Armee von Drachen nicht genug, um sie zu befreien, <Volk>.\n\nDer gleiche Zauber, der sie gefangen hält, würde uns der Gewalt C'Thuns unterwerfen, sobald wir ihm näher kämen.\n\nDer alte Gott hat unser Kommen vorhergesehen. All unsere Hoffnung ist dahin. Was könnte ein bloßer Sterblicher wie Ihr daran wohl ändern?", description = nil, progress = "Wir spüren die Anwesenheit unserer versklavten Brüder tief im Innern von Ahn'Qiraj; dennoch wäre selbst eine Armee von Drachen nicht genug, um sie zu befreien, <Volk>.\n\nDer gleiche Zauber, der sie gefangen hält, würde uns der Gewalt C'Thuns unterwerfen, sobald wir ihm näher kämen.\n\nDer alte Gott hat unser Kommen vorhergesehen. All unsere Hoffnung ist dahin. Was könnte ein bloßer Sterblicher wie Ihr daran wohl ändern?", completion = "Ihr werdet den Qiraji innerhalb der Behausung des alten Gottes entgegentreten? Ist das eine Art von Galgenhumor, dessen ich mir nicht bewusst bin?\n\nIch kann sehen, dass Ihr es ernst meint, &lt;Name&gt;. Also bitte. Eure Chancen, auch wenn sie noch so gering sein mögen, sind momentan dennoch größer als unsere.\n\nGenau wie Nozdormu und Staghelm die Qiraji vor tausend Jahren dank des Bündnisses zwischen den Sterblichen und der Drachen besiegt haben, so sollen auch wir uns zusammenschließen. Gewinnt das Vertrauen des bronzenen Drachenschwarms und somit das unsere. Nur so können wir einen wahren Helden aus Euch machen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRuf - Ahn'Qiraj Tempelendgegner\n\nIhr bekommt:\n\n"},
[8580] = {title = "Die Horde braucht Feuerblüten!", objective = "Bringt 20 Feuerblüten zu Fledermausreiter Pele'keiki im Tal der Geister in Orgrimmar.", description = "Hey, <Klasse>! Ja, Ihr da! Es gibt da massenhaft Feuerblüten, die von der Horde für die Vorbereitungen des Krieges von Ahn'Qiraj benötigt werden. Vielleicht werden sie ja in so nette Dinge verarbeitet, die dann in die Luft gehen? Vielleicht geben sie sie der Allianz aber auch als Treibstoff für ihre Dampfpanzer? Wer weiß? Nicht Pele'keiki!\n\nPele'keiki weiß nur eines... er weiß, dass Ihr ihm helfen und einen Haufen Feuerblüten für ihn sammeln werdet! Oder?", progress = "Ihr wollt doch nicht, dass Pele'keiki böse wird. Ihr macht Pele'keiki glücklich, wenn Ihr ihm schon ganz bald ganz viele Feuerblüten bringt.", completion = "&lt;Klasse&gt;! Pele'keiki ist dank Euch sehr glücklich. Er wird diese Feuerblüten in eine Kiste packen, damit sie frisch bleiben. Aus all diesen Pflanzen werden sie sicherlich eine ganze Menge gutes Kriegsmaterial herstellen. Kommt zurück, falls Ihr noch mehr davon gefunden habt. Pele'keiki kann davon nicht genug kriegen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8581] = {title = "Die Horde braucht mehr Feuerblüten!", objective = "Pele'keiki weiß, dass Ihr gekommen seid, um zu helfen. Bringt viele Feuerblüten und macht ihn damit sehr glücklich. Pele'keiki kann aus Feuerblüten große Bomben machen. Er wird sie auf Insekten von seiner Fledermaus aus abwerfen, wenn der Krieg in Ahn'Qiraj anbricht. Pele'keiki braucht aber noch mehr dieser Pflanzen, <Klasse>!\n\nBringt Pele'keiki die Feuerblüten jetzt ganz schnell. Kommt mit mindestens so vielen wie letztes Mal zurück und Pele'keiki wird zufrieden sein.", description = nil, progress = "Pele'keiki weiß, dass Ihr gekommen seid, um zu helfen. Bringt viele Feuerblüten und macht ihn damit sehr glücklich. Pele'keiki kann aus Feuerblüten große Bomben machen. Er wird sie auf Insekten von seiner Fledermaus aus abwerfen, wenn der Krieg in Ahn'Qiraj anbricht. Pele'keiki braucht aber noch mehr dieser Pflanzen, <Klasse>!\n\nBringt Pele'keiki die Feuerblüten jetzt ganz schnell. Kommt mit mindestens so vielen wie letztes Mal zurück und Pele'keiki wird zufrieden sein.", completion = "Kein Scherz, &lt;Klasse&gt;? Ihr bringt Pele'keiki so schnell Feuerblüten? Pele'keiki wird sie direkt zählen! Ihr macht Pele'keiki sehr glücklich und er wird jedem erzählen, was für ein fantastischer Feuerblütensammler &lt;Name&gt; ist. Pele'keiki kann es kaum erwarten, dass der Krieg beginnt. Wir werden den Himmel über Silithus erhellen, richtig, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8582] = {title = "Die Horde braucht lila Lotus!", objective = "Bringt 20 lila Lotus zu Apothekerin Jezel im Tal der Geister in Orgrimmar.", description = "Lila Lotus, <Klasse>, ist eine Zutat für nicht wenige Tränke, Elixire und Öle, von denen uns einige im Krieg von Ahn'Qiraj von Nutzen sein werden. Wir werden eine stattliche Menge dieser Tränke für die Kriegsanstrengungen herstellen müssen. Ich werde zusätzlich noch experimentieren, um weitere Verwendungsmöglichkeiten für Lila Lotus zu finden. Allerdings werde ich dafür eine große Anzahl dieser Pflanzen benötigen.\n\nJetzt zu Eurer Aufgabe. Zieht durch die Felder und sammelt so viel Lila Lotus ein, wie Ihr könnt. Wärt Ihr dazu in der Lage?", progress = "Schon wieder mit dem benötigten lila Lotus zurück, <Klasse>? Es ist entscheidend, dass Ihr so schnell wie möglich handelt, da sonst all mein Bestreben hier umsonst war.", completion = "Ein beachtlicher Erfolg, &lt;Klasse&gt;. Ich werde diese Pflanzen für Ihre endgültige Verwendung vorbereiten und Eure Spende entsprechend vermerken. Erst danach kann ich den lila Lotus ordnungsgemäß einlagern. Was Euch betrifft: Wenn Ihr noch etwas Zeit habt, könnte ich noch mehr lila Lotus gebrauchen. In diesem Fall meldet Euch einfach wieder bei mir.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8583] = {title = "Die Horde braucht mehr lila Lotus!", objective = "Wie es aussieht, brauchen wir noch mehr lila Lotus, <Klasse>. Während meine eigenen Studien erst einen neuen nützlichen Verwendungszweck für diese Pflanze nachweisen müssen, gibt es bereits bekannte und bewährte Methoden, die angewendet werden können.\n\nIhr müsst noch einmal für mich losziehen und mindestens zwanzig lila Lotus sammeln. Bringt sie dann hierher zu mir.", description = nil, progress = "Wie es aussieht, brauchen wir noch mehr lila Lotus, <Klasse>. Während meine eigenen Studien erst einen neuen nützlichen Verwendungszweck für diese Pflanze nachweisen müssen, gibt es bereits bekannte und bewährte Methoden, die angewendet werden können.\n\nIhr müsst noch einmal für mich losziehen und mindestens zwanzig lila Lotus sammeln. Bringt sie dann hierher zu mir.", completion = "Eine hervorragende und präzise Arbeit, &lt;Name&gt;. Euer Fleiß und Eure Schnelligkeit sind beispiellos. Ich werde dafür sorgen, dass nicht eine der lila Lotuspflanzen verloren geht.\n\nIch danke Euch. Solltet Ihr noch mehr lila Lotus auftreiben können, zögert nicht lange und bringt ihn mir vorbei.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8584] = {title = "Fragt mich nie nach meinen Angelegenheiten", objective = "Narain Soothfancy in Tanaris möchte, dass Ihr mit Dirge Quikcleave in Gadgetzan sprecht.", description = "Wenn es eine Sache gibt, die Ihr von mir wissen solltet, dann ist es das: Fragt mich NIEMALS nach meinen Angelegenheiten! Ich arbeite mit Dingen, die Ihr einfach nicht verstehen könnt. Zum Beispiel: Wisst Ihr was ein psychotronischer Muzzledorf ist? Natürlich nicht! Genau deshalb überlassen wir das Planen auch mir und das Beschaffen Euch.\n\nWie ich schon sagte, wenn es funktionieren soll, dann brauchen wir ein 500 Pfund-Hühnchen.\n\nGeht nach Gadgetzan und sprecht mit Dirge Quikcleave - er kann Euch bei der Suche nach dem passenden Exemplar auf die Sprünge helfen.", progress = nil, completion = "&lt;Dirge kratzt sich am Kopf.&gt;\n\nEin 500 Pfund-Hühnchen? Sowas gibt es nicht! Nicht mehr, zumindest. Ich weiß von so einem Hühnchen... das schwarze Huhn des Todes...\n\n&lt;Dirges Stimme verhallt.&gt;\n\nAber nun ja, niemand, der dieses Hühnchen je zu Gesicht bekommen hat, lebt noch um diese Geschichte zu erzählen. Ich hätte da eine Idee, von der wir beide profitieren könnten, mein Kind.", rewards = "Ihr bekommt:\n\n"},
[8585] = {title = "Die Insel des Schreckens!", objective = "Dirge Quikcleave in Tanaris möchte, dass Ihr Lakmaerans Kadaver, sowie 20 Chimaeroklenden beschafft.", description = "Der Legende nach haben die Chimaerok von der Insel des Schreckens in Feralas das saftigste und zarteste Fleisch weit und breit! Nun kommt es, dass diese Chimaerok ein Familienoberhaupt haben, das, nach entsprechender Zubereitung, wie ein 500 Pfund-Hühnchen aussehen könnte... oder auch nicht.\n\nGeht zu der Insel des Schreckens, tötet Lord Lakmaeran und bringt mir seinen frischen Kadaver. Das sollte den Gnom zufrieden stellen. Um mich zufrieden zu stellen, müsst Ihr ein paar Chimaeroklenden in Eure Finger bekommen.\n\nSollte Euch das gelingen, bekommt Ihr Euer 500 Pfund-Hühnchen und ein kleines Extra.", progress = "Mmmmm... Chimaerok...", completion = "Seht Euch nur die Marmorierung dieser Lenden an! Fantastisch!\n\nJetzt zu dem Hühnchen... hm, lasst mal sehen. Ich werde ein paar Minuten brauchen, um das Rezept auszuarbeiten.", rewards = "Ihr bekommt:\n\n"},
[8586] = {title = "Dirges abgefahrene Chimaerokkoteletts", objective = "Dirge Quikcleave in Gadgetzan möchte, dass Ihr ihm 20 Einheiten Goblin-Raketentreibstoff und 20 Einheiten Tiefsteinsalz bringt.", description = "Mein Rezept is fertig! Was ich jetzt von Euch brauche ist Raketentreibstoff und Tiefsteinsalz. Ich kümmere mich um die Gewürze und das Fleisch, das Ihr mir gebracht habt, sorgt für den Rest.\n\nSobald Ihr mir die benötigten Zutaten gebracht habt, könnt Ihr das fertige Hühnchen zu Narain bringen.", progress = "Beeilt Euch, Kind. Wir möchten doch nicht, dass das Fleisch schlecht wird.", completion = "Es ist fertig! Ich präsentiere Euch meine beste Kreation: Dirges abgefahrene Chimaerokkoteletts!", rewards = "Ihr bekommt:\n\nRezept: Dirges abgefahrene ChimaerokkotelettsDirges abgefahrene Chimaerokkoteletts"},
[8587] = {title = "Rückkehr zu Narain", objective = "Bringt das 500 Pfund-Hühnchen zu Narain Soothfancy in Tanaris.", description = "Ich bin ein Goblin, der sein Wort hält, Kind. Hier ist Euer 500 Pfund-Hühnchen.\n\nWas ein Gnom mit einem 500 Pfund-Hühnchen möchte, werde ich wohl nie verstehen...\n\n<Dirge grummelt etwas Unverständliches.>\n\nWahrscheinlich um darin zu schlafen... schmutzige Gnome...", progress = "Woher kommt dieser köstliche Geruch?", completion = "&lt;Narain greift mit seinen Fäusten in das riesige Hühnchen und stopft seinen Mund voll mit Dirges köstlicher Delikatesse.&gt;\n\nMMmmm... das ist unglaublich! Das beste Hühnchen, das ich jemals gekostet habe!", rewards = "Ihr bekommt:\n\n"},
[8588] = {title = "Die Horde braucht schweres Leder!", objective = "Bringt 10 Einheiten schweres Leder zu Kürschner Jamani im Tal der Geister in Orgrimmar.", description = "Da wir uns gerade auf den bevorstehenden Krieg vorbereiten, wäre es wahrscheinlich das Beste, wenn wir alle benötigten Güter zuerst beschaffen, meint Ihr nicht? Einer der benötigten Vorräte besteht aus schwerem Leder. Wir verwenden es für fast alles, von Verstärkungen bis hin zu Rüstungen und guten alten Planen.\n\nAllerdings brauchen wir erst einmal mehr davon. Das ist Eure Aufgabe, <Klasse>. Wetzt Euer Messer und bringt mir ein Bündel schweres Leder. Alles weitere besprechen wir dann.", progress = "Solltet Ihr nur zum Plaudern hier sein, dann habe ich keine Zeit für Spielchen, <Klasse>. Es gibt zu viele Stapel schweren Leders, die noch ausgehärtet werden müssen. Kommt wieder, wenn Ihr mindestens zehn für mich beisammen habt.", completion = "Oh, Ihr habt also das schwere Leder, das ich benötige. Eure Klinge ist wirklich scharf, &lt;Klasse&gt;; das sind gute Häute! Da wir uns jetzt zu verstehen scheinen, werde ich dafür sorgen, dass Eure Beisteuerung einer angebrachten Verwendung zu Gute kommt. Solltet Ihr über noch mehr schweres Leder stolpern, dann bringt es zu mir.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8589] = {title = "Die Horde braucht mehr schweres Leder!", objective = "Es ist wahr, <Klasse>, ich benötige noch mehr schweres Leder. Die Nachfrage von den Generalen und ihren Rüstmeistern scheint endlos zu sein - und das ist noch gar nichts im Vergleich zu dem, was die Zeppelinmeister verlangen!\n\nDie Sammelaktion muss jetzt doppelt so schnell vorangehen. <Name>, bringt mir, so bald Ihr könnt, noch mehr Stapel schweren Leders!", description = nil, progress = "Es ist wahr, <Klasse>, ich benötige noch mehr schweres Leder. Die Nachfrage von den Generalen und ihren Rüstmeistern scheint endlos zu sein - und das ist noch gar nichts im Vergleich zu dem, was die Zeppelinmeister verlangen!\n\nDie Sammelaktion muss jetzt doppelt so schnell vorangehen. <Name>, bringt mir, so bald Ihr könnt, noch mehr Stapel schweren Leders!", completion = "Fantastisch! Vielen Dank für das ganze schwere Leder. Jede Spende bringt uns einen Schritt nach vorn. Ich werde Eure Ladung eben einlagern, damit unsere Lederer alles weiterverarbeiten können.\n\nNochmals danke, &lt;Name&gt;! Wenn Ihr noch mehr schweres Leder auftreibt, wisst Ihr ja, wo Ihr mich finden könnt.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8590] = {title = "Die Horde braucht dickes Leder!", objective = "Bringt 10 Einheiten dickes Leder zu Sergeant Umala im Tal der Geister in Orgrimmar.", description = "Ich bin froh, dass Ihr darüber mit mir sprechen möchtet, <Klasse>. Es sieht ganz so aus, als ob die Vorbereitungen der Horde für den Krieg in Ahn'Qiraj in vollem Gange sind. Ihr und ich müssen aber noch unseren Teil leisten.\n\nIch wurde mit der Sammlung einer großen Menge dicken Leders beauftragt, das für die Herstellung von allerlei Kriegsmaterialien benötigt wird. Ich brauche Euch, um für mich loszuziehen und mir welches zu besorgen. Ihr würdet Euch Ehre und das Wohlwollen der Horde verdienen können. Würdet Ihr uns also helfen?", progress = "<Klasse>, seid Ihr schon wieder mit den angeforderten zehn Einheiten dicken Leders zurück?", completion = "Gute Arbeit, &lt;Klasse&gt;. Dieses dicke Leder wird sicherlich eine gute Verwendung bei der Rüstungsherstellung oder der Panzerung unserer Zeppeline finden. Ihr habt meinen Dank und den der Horde redlich verdient. Falls Ihr auf Euren Reisen noch mehr dickes Leder auftreiben könnt, besucht mich doch. Alles Gute!", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8591] = {title = "Die Horde braucht mehr dickes Leder!", objective = "<Klasse>, wie Ihr sehen könnt, brauche ich noch mehr dickes Leder. Noch einmal möchte ich Euch um Eure Hilfe bitten. Ich verspreche Euch, dass Ihr bei Erfüllung Eurer Aufgabe große Anerkennung finden werdet.\n\nDie Zeit ist ausschlaggebend! Kehrt mit dem dicken Leder zu mir zurück, damit wir unsere Vorbereitungen abschließen und in den Krieg ziehen können, Held!", description = nil, progress = "<Klasse>, wie Ihr sehen könnt, brauche ich noch mehr dickes Leder. Noch einmal möchte ich Euch um Eure Hilfe bitten. Ich verspreche Euch, dass Ihr bei Erfüllung Eurer Aufgabe große Anerkennung finden werdet.\n\nDie Zeit ist ausschlaggebend! Kehrt mit dem dicken Leder zu mir zurück, damit wir unsere Vorbereitungen abschließen und in den Krieg ziehen können, Held!", completion = "Ihr habt es wieder einmal geschafft, &lt;Name&gt;! Wieder einmal muß ich Euch im Namen der ganzen Horde danken. Eure Anstrengungen wurden wohlwollend zur Kenntnis genommen. Wenn Ihr auf Euren Reisen noch weitere Ladungen an dickem Leder auftreiben könnt, zögert nicht lange und bringt es zu mir!\n\nLok'tar Ogar, &lt;Klasse&gt;!", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8592] = {title = "Tiara des Orakels", objective = "Bringt Vek'nilashs Reif, 2 Götzen der Weisen, 5 Silberskarabäen und 5 Knochenskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", description = "Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.\n\nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.\n\nBringt mir die benötigten Bestandteile, <Name>. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, <Name>?", completion = "Ihr seid erfolgreich gewesen! Das Flüstern der Zwillingsimperatoren ist verstummt.\n\nNehmt dies als Belohnung. Der bloße Anblick hiervon wird Furcht in die Herzen der Qiraji treiben... es soll sie an ihre gefallenen Anführer erinnern und an den Sterblichen, der sie niederstreckte.", rewards = "Ihr bekommt:\n\nTiara des Orakels"},
[8593] = {title = "Beinkleider des Orakels", objective = "Bringt Ouros intakte Haut, 2 Götzen der Wiedergeburt, 5 Goldskarabäen und 5 Tonskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", description = "Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.\n\nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem alten Gott selbst als Gespött des Lebens erschaffen wurde.\n\nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.\n\nBringt mir eine Probe seiner Haut, sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, <Name>?", completion = "Ja... die Haut des Wurms wird eine wunderbar schützende Schicht abgeben. In Verbindung mit den stärksten Teilen der Qiraji, die wir auf unserem Weg hierher zerstört haben, sollte dies eine prächtige Rüstung abgeben. Möge sie Euch bei der Begegnung des unaussprechlichen Grauens helfen, das Euch im Innern erwarten wird!", rewards = "Ihr bekommt:\n\nBeinkleider des Orakels"},
[8594] = {title = "Mantel des Orakels", objective = "Bringt die Befehlsbindungen der Qiraji, 2 Götzen der Wiedergeburt, 5 Silberskarabäen und 5 Elfenbeinskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.", description = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.\n\nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMantel des Orakels"},
[8595] = {title = "Sterbliche Helden", objective = "Einen Qirajilord zu töten ist eine bemerkenswerte Tat für einen Sterblichen, <Name>. Allerdings sind sie zahlreich und mächtig. Bezwingt sie auch weiterhin und erweist Euch als unser Held.", description = nil, progress = "Einen Qirajilord zu töten ist eine bemerkenswerte Tat für einen Sterblichen, <Name>. Allerdings sind sie zahlreich und mächtig. Bezwingt sie auch weiterhin und erweist Euch als unser Held.", completion = "Ihr dient uns auch weiterhin tapfer, &lt;Name&gt;. Unser Bündnis bleibt bestehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRuf - Ahn'Qiraj Tempelendgegner"},
[8596] = {title = "Fußlappen des Orakels", objective = "Bringt die Befehlsbindungen der Qiraji, 2 Götzen des Todes, 5 Bronzeskarabäen und 5 Goldskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.", description = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.\n\nBringt mir die Befehlsbindungen der Qiraji, sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.\n\nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFußlappen des Orakels"},
[8597] = {title = "Drachisch für Dummies", objective = "Findet Narain Soothfancys Buch, das auf einer Insel der südlichen Meere vergraben ist.", description = "Ich wusste, dass dieses Buch eines Tages nützlich sein würde! Glücklicherweise war ich clever und vorausschauend genug und habe es an einem sicheren Ort verstaut.\n\nKeine Angst, es befindet sich an einem Platz, auf den niemand kommen würde! Ich brauchte einen Gyrokopter, um das erste Mal dorthin zu gelangen. Bedauerlicherweise musste ich auf meinem Rückweg am Strand bruchlanden. Ich verdanke es diesem Unfall, dass ich diese gnomischen Superpsychokräfte erlangt habe!\n\nHaltet nach meinem verunglückten Gyrokopter irgendwo am Landendestrand Ausschau und schwimmt von da aus in Richtung Süden! Ihr werdet die Stelle erkennen, wenn Ihr sie seht!", progress = nil, completion = "Das Buch ist verschwunden! Auf der aufgewühlten Erde liegt eine Nachricht.", rewards = "Ihr bekommt:\n\n"},
[8598] = {title = "lÖsEGeLd", objective = "Bringt die Lösegeldforderung zu Narain Soothfancy in Tanaris.", description = "<Der Text der Nachricht wurde aus unterschiedlichen, ausgeschnittenen Buchstaben zusammengesetzt und auf das Papier geklebt.>\n\nWir haben dein kostbares Buch, Gnom. Wenn du es jemals wiedersehen willst, dann machst du genau das, was wir dir sagen.\n\n<Dem Ganzen folgt eine ausführliche Liste von Anweisungen, die sich über 3 Seiten zieht.>\n\nBringt das Geld und kommt alleine!", progress = "Sagt schon, was ist los?", completion = "&lt;Narains Gesicht wird rot vor Zorn.&gt;\n\nMein Buch... buchnappen, wollen die!? Ich werde denen zeigen, was es heißt sich mit einem übersinnlichen Gnom anzulegen!", rewards = "Ihr bekommt:\n\n"},
[8599] = {title = "Liebesbrief für Narain", objective = "Bringt Meridiths Liebesbrief zu Narain Soothfancy in Tanaris.", description = "Es kommt nicht häufig vor, dass ich Besuch bekomme. Genaugenommen hatte ich das letzte Mal einen Besucher, als ich diesen liebreizenden, süßen Gnom nach dem Absturz mit seiner Flugmaschine gerettet habe.\n\n<Meridith starrt gedankenverloren ins Nichts.>\n\nKennt Ihr ihn? Narain? Narain Soothfancy? Oh, es würde mir so viel bedeuten, wenn ihm jemand eine Nachricht von mir überbringen würde. Ich muss ihm mitteilen, was ich empfinde! Ich weiß, dass es Liebe ist! Ich weiß es einfach!\n\nKönntet Ihr Narain vielleicht eine Nachricht zustellen? Ich wäre Euch für immer zu Dank verpflichtet!", progress = "Ihr stinkt nach Fisch!", completion = "Was!?\n\n&lt;Narain fängt an herum zu zappeln.&gt;\n\nNaja, hm... was soll ich machen??? Sie ist ein Fisch! EIN FISCH sage ich Euch! Und ich ein Gnom. Das würde niemals gutgehen.", rewards = "Ihr bekommt:\n\n"},
[8600] = {title = "Die Horde braucht unverwüstliches Leder!", objective = "Bringt 10 Einheiten unverwüstliches Leder zu Doktor Serratus im Tal der Geister in Orgrimmar.", description = "Ich glaube, dass die richtige Handhabung eines Messers wichtiger ist als dessen Schneide. Beherrscht man sein Handwerk, kann man auch mit der stumpfesten Klinge schneiden, oder <Klasse>? Ihr und ich, wir haben solche Probleme aber nicht, da wir im Besitz der schärfsten Klingen sind.\n\nNaja, egal. Ich habe eine Aufgabe für Euch. Im Auftrag der Horde und im Namen der Kriegsvorbereitungen von Ahn'Qiraj, möchte ich Euch bitten, mir eine gewisse Anzahl unverwüstliches Leder zu besorgen. Wäre das möglich?", progress = "Ihr werdet doch wohl nicht so lange brauchen, um mir 10 Einheiten unverwüstliches Leder zu bringen! Vielleicht solltet Ihr noch einmal Euer Messer schleifen? Oder vielleicht bin ich im Unrecht und Ihr habt das Leder bereits in Eurem Rucksack?", completion = "Nun gut, es scheint als wäre das nur eine vorübergehende Arbeit für Euch, da einige Ränder dieser Häute etwas zerfetzt aussehen. Egal, die Aufgabe wurde erfüllt und Ihr habt Euch Eure Gegenleistung verdient. Ich werde Euren Namen neben dem Leder notieren; ich bin mir sicher, dass die Horde Eure Bemühungen zu schätzen wissen wird. Solltet Ihr auf einen weiteren Stapel unverwüstlichen Leders stoßen, dann bringt ihn bitte schnellstens zu mir.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8601] = {title = "Die Horde braucht mehr unverwüstliches Leder!", objective = "Die Vorbereitungen für den bevorstehenden Krieg in Ahn'Qiraj machen Fortschritte, <Klasse>. Um sicher zu gehen, dass wir nicht hinterherhängen oder dass es dann zumindest nicht an mir liegt, möchte ich Euch um eine weitere Ladung unverwüstliches Leder bitten. Ein schnelles Handeln Eurerseits wird hoch geschätzt werden, <Name>.", description = nil, progress = "Die Vorbereitungen für den bevorstehenden Krieg in Ahn'Qiraj machen Fortschritte, <Klasse>. Um sicher zu gehen, dass wir nicht hinterherhängen oder dass es dann zumindest nicht an mir liegt, möchte ich Euch um eine weitere Ladung unverwüstliches Leder bitten. Ein schnelles Handeln Eurerseits wird hoch geschätzt werden, <Name>.", completion = "Übung, Übung, Übung. Ein fein geschliffenes Messer und die richtige Anwendung dessen wird Euch in dieser Welt weit bringen, &lt;Name&gt;. Es sieht aus, als ob die Ränder dieser Häute diesmal feiner wären als das letzte Mal. Habt Ihr Euch ein neues Messer geleistet?\n\nWie dem auch sei, wir danken Euch für Eure Mühen. Eure Spende wurde registriert und wir werden dafür sorgen, dass sie eine gute Verwendung findet. Solltet Ihr im Besitz von weiterem unverwüstlichen Leder sein, dann kommt bitte hierher zurück und sprecht mit mir. Ich werde es höchstwahrscheinlich brauchen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8602] = {title = "Schulterstücke des Sturmrufers", objective = "Bringt die Dominanzbindungen der Qiraji, 2 Götzen des Lebens, 5 Goldskarabäen und 5 Kristallskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.", description = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.\n\nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchulterstücke des Sturmrufers"},
[8603] = {title = "Gewänder des Orakels", objective = "Bringt die Hülle des alten Gottes, 2 Götzen des Todes, 5 Steinskarabäen und 5 Kristallskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.", description = "Der unaussprechliche alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.\n\nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.\n\nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!", progress = "Der furchtbare C'Thun wartet ruhend in seiner Behausung in Ahn'Qiraj.", completion = "Ich habe nicht erwartet, dass Ihr von Eurer Unternehmung zurückkehrt, &lt;Name&gt;.\n\nIhr habt eine größere Vorsehung erfüllt als die der meisten sterblichen Wesen.\n\nIndem Ihr C'Thun bezwungen habt, habt Ihr nicht nur ganz Azeroth gerettet, sondern auch kosmische Ereignisse in Gang gesetzt, die weit über Eurem Vorstellungsvermögen liegen.\n\nNehmt diese Gewänder als Zeichen des Ruhms und der Bürde an, die Euch in Folge Eurer Taten erwarten werden.\n\nMöge ihre Macht bei Euren zukünftigen Herausforderungen mit Euch sein, Göttertöter!", rewards = "Ihr bekommt:\n\nTunika des Orakels"},
[8604] = {title = "Die Horde braucht Wollverbände!", objective = "Bringt 20 Wollverbände zu Heiler Longrunner im Tal der Geister in Orgrimmar.", description = "Seid gegrüßt, <Klasse>. Während der Vorbereitungen für den Krieg in Ahn'Qiraj, bin ich hier, um die Bemühungen der Horde beim Zusammentragen von Wollverbänden zu koordinieren. Auf dem Schlachtfeld können sich unsere Soldaten nicht auf die Gegenwart eines Heilers verlassen, der sie am Leben hält. Glaubt mir, ich weiß das. Daher stellen wir all diese Sanitätskästen für sie zusammen.\n\nSolltet Ihr Zeit haben: Ich brauche sehr viele Wollverbände. Bringt sie hierher zu mir und ich werde sehen, dass Ihr dafür ordnungsgemäß entlohnt werdet.", progress = "Ah, <Klasse>, seid Ihr schon wieder mit den Wollverbänden zurück?", completion = "Ihr habt meinen Dank und den der Horde redlich verdient, &lt;Klasse&gt;! Solltet Ihr noch mehr Wollverbände spenden wollen, zögert nicht lange und kommt zu mir. Auf bald. Mögen Eure Vorfahren über Euch wachen!", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8605] = {title = "Die Horde braucht mehr Wollverbände!", objective = "Schön Euch wiederzusehen, <Klasse>. Wir arbeiten hier noch immer an den Kriegsvorbereitungen und ich kann auch weiterhin all die Hilfe gebrauchen, die Ihr mir hinsichtlich der Sammlung von Wollverbänden geben könnt. Jegliche Unterstützung wird hoch geschätzt werden. Ich hoffe nur, dass unsere Bemühungen ausreichen. Ich habe schon zu viele ehrenhafte Seelen auf den Schlachtfeldern verloren und werde sehen, was ich tun kann, um so etwas noch einmal zu verhindern.", description = nil, progress = "Schön Euch wiederzusehen, <Klasse>. Wir arbeiten hier noch immer an den Kriegsvorbereitungen und ich kann auch weiterhin all die Hilfe gebrauchen, die Ihr mir hinsichtlich der Sammlung von Wollverbänden geben könnt. Jegliche Unterstützung wird hoch geschätzt werden. Ich hoffe nur, dass unsere Bemühungen ausreichen. Ich habe schon zu viele ehrenhafte Seelen auf den Schlachtfeldern verloren und werde sehen, was ich tun kann, um so etwas noch einmal zu verhindern.", completion = "Ihr seid ein ehrenhafter &lt;Klasse&gt;, &lt;Name&gt;! Ich werde dafür sorgen, dass Eure Spende an die richtige Stelle weitergeleitet wird. Ihr habt meinen Dank und den der Horde.\n\nGeht in Frieden und kehrt zu mir zurück, falls Ihr wieder einige Wollverbände für uns übrig habt. Wir können hier jede Hilfe gebrauchen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8606] = {title = "Lockvogel!", objective = "Narain Soothfancy in Tanaris möchte, dass Ihr nach Winterspring reist und die Tasche voller Gold, so wie es die Buchnapper angegeben haben, am Übergabepunkt platziert.", description = "Ich hab's! Wir werden Folgendes tun. Ich werde einen Sack mit Steinen füllen und Ihr werdet ihn überbringen. Ich weiß, dass man die Übergabe von mir verlangt und das werde ich auf gewisse Weise auch tun.\n\n<Narain sieht Euch von oben bis unten an.>\n\nJa, das dürfte passen. Nehmt diesen Turban, diese Robe und den Sack voller Steine, geht dann zu dem Übergabepunkt in Winterspring.\n\nAlles, was Ihr benötigen werdet, befindet sich in diesem Spezialset. Sobald sie auftauchen, um die Ware abzuholen, macht Ihr sie fertig! Das wird ihnen lehren, was es heißt, sich mit Narain anzulegen!", progress = nil, completion = "Ich glaube, wir haben diese Buchnapper unterschätzt.", rewards = "Ihr bekommt:\n\n"},
[8607] = {title = "Die Horde braucht Magiestoffverbände!", objective = "Bringt 20 Magiestoffverbände zu Lady Callow im Tal der Geister in Orgrimmar.", description = "Ich nehme doch hoffentlich richtig an, dass Ihr mit mir sprecht, weil Ihr mich bei dem Sammelauftrag unterstützen wollt, der mir anvertraut wurde? Gut! Mir ist es egal wie, aber ich wünsche mir wirklich, dass Ihr einige Magiestoffverbände für mich zusammentragt. Ganz frisch hergestellte wären wunderbar, aber nicht unbedingt zwingend. Bringt sie hierher zu mir <Klasse>, dann werde ich sehen, dass Ihr ordnungsgemäß dafür entlohnt werdet.", progress = "Enttäuscht mich nicht, <Klasse>! Kommt so schnell wie möglich hierher mit den angeforderten Magiestoffverbänden zurück.", completion = "Überraschend, dennoch akzeptabel. Vielleicht habe ich Eure 'Fähigkeiten' ein wenig unterschätzt, &lt;Klasse&gt;. Vielleicht. Wie auch immer, Ihr habt eine mehr als einfache Aufgabe erfolgreich ausgeführt und ich nehme an, man wird Euch eine weitaus größere Belohnung zusprechen, als Ihr sie eigentlich verdient hättet. Lasst Euch das nicht gleich zu Kopfe steigen. Wenn Ihr Euch wirklich beweisen wollt, solltet Ihr wieder losziehen und mir eine weitere Ladung Magiestoffverbände bringen!", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8608] = {title = "Die Horde braucht mehr Magiestoffverbände!", objective = "Ihr seid wieder da? Interessant. Wie Ihr sehen könnt, sammle ich noch immer für die Kriegsvorbereitungen von Ahn'Qiraj. Das bedeutet, dass ich Euch noch einmal brauchen werde, um einen weiteren Haufen Magiestoffverbände für mich zu beschaffen. Ich bin schon auf Eure Rückkehr gespannt, <Klasse>.", description = nil, progress = "Ihr seid wieder da? Interessant. Wie Ihr sehen könnt, sammle ich noch immer für die Kriegsvorbereitungen von Ahn'Qiraj. Das bedeutet, dass ich Euch noch einmal brauchen werde, um einen weiteren Haufen Magiestoffverbände für mich zu beschaffen. Ich bin schon auf Eure Rückkehr gespannt, <Klasse>.", completion = "Erstaunlich, &lt;Klasse&gt;, Ihr habt es mal wieder geschafft! Nun ja, man sagt, ich hätte ein gutes Händchen, immer die tüchtigsten Männer und Frauen für eine Aufgabe auszuwählen. Wie auch immer, Eure Spende wurde zur Kenntnis genommen und Eure Mühen werden sich noch bezahlt machen. Ich würde vorschlagen, dass Ihr noch einmal loszieht und weitere Magiestoffverbände besorgt, sofern Ihr Euren Wert tatsächlich beweisen wollt.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8609] = {title = "Die Horde braucht Runenstoffverbände!", objective = "Bringt 20 Runenstoffverbände zu Steinwache Clayhoof im Tal der Geister in Orgrimmar.", description = "Für viele scheint es unausweichlich, dass die Streitkräfte von Horde und Allianz bei Ahn'Qiraj aufeinander treffen werden. Interessanterweise handelt es sich dabei nicht um einen Krieg gegeneinander, sondern vielmehr gegen die Silithiden, oder was auch immer sie kontrolliert. Beide Seiten leisten ihren Teil, um die nötigen Ressourcen für eine erfolgreiche Kriegsführung aufzubringen.\n\nIch sammle Runenstoffverbände, die an die Soldaten ausgeteilt werden. Ich bräuchte dabei allerdings Unterstützung. Könntet Ihr mir dabei helfen, <Klasse>?", progress = "Der Krieg naht, <Klasse>. Ich bin Euch sehr dankbar für Eure Hilfe. Habt Ihr die Runenstoffverbände von denen wir gesprochen haben?", completion = "Ihr seid ein Segen für die Horde, &lt;Klasse&gt;. Eure Bemühungen werden von uns sehr geschätzt und sie sind mehr als willkommen! So, jetzt muss ich erst einmal die frischen Verbände verstauen und die neuesten Bestandszahlen ermitteln. Falls Ihr noch mehr Runenstoffverbände sammeln wollt, könnt Ihr sie mir später einfach vorbeibringen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8610] = {title = "Die Horde braucht mehr Runenstoffverbände!", objective = "Der Moment, in dem wir uns in die Wogen des Krieges von Ahn'Qiraj stürzen werden, rückt immer näher, <Klasse>. Jedoch sollten wir unsere Kräfte vorerst dazu nutzen, um uns vorzubereiten, damit wir den Angriff auf die Insekten und ihre Meister überleben können.\n\nDa Ihr wieder hier seid, bedeutet das bestimmt, dass Ihr uns mit einer weiteren Ladung an Runenstoffverbänden aushelfen wollt. Bitte macht das so bald wie möglich und kehrt dann noch einmal zu mir zurück.", description = nil, progress = "Der Moment, in dem wir uns in die Wogen des Krieges von Ahn'Qiraj stürzen werden, rückt immer näher, <Klasse>. Jedoch sollten wir unsere Kräfte vorerst dazu nutzen, um uns vorzubereiten, damit wir den Angriff auf die Insekten und ihre Meister überleben können.\n\nDa Ihr wieder hier seid, bedeutet das bestimmt, dass Ihr uns mit einer weiteren Ladung an Runenstoffverbänden aushelfen wollt. Bitte macht das so bald wie möglich und kehrt dann noch einmal zu mir zurück.", completion = "Wie bereitwillig Ihr uns unterstützt, das ist wahrlich selbstlos von Euch, &lt;Name&gt;! Diese Großzügigkeit wird sicherlich das Leben vieler Kombattanten in Ahn'Qiraj retten. Vielen Dank, und seid Euch sicher, dass die gesamte Horde Eure Spende zu schätzen weiß. Solltet Ihr noch mehr Runenstoffverbände herstellen oder ausfindig machen, so kommt doch bitte nochmal vorbei.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8611] = {title = "Die Horde braucht magere Wolfsteaks!", objective = "Bringt 20 magere Wolfsteaks zu Blutwache Rawtar im Tal der Geister in Orgrimmar.", description = "Ich stehe hier nicht nur herum, um etwas Farbe abzubekommen, <Klasse>. Es gilt Kriegsvorbereitungen zu treffen. Wenn wir diese Viecher in Ahn'Qiraj niederschmettern möchten, dann müssen wir bereit sein, und dazu gehört auch Proviant!\n\nIch sammle und salze hier magere Wolfsteaks für den anstehenden Krieg ein. Da ich hier bleiben muss, um mich um alles zu kümmern, bräuchte ich Eure Hilfe. Zieht aus, um Wölfe zu töten, bereitet ihr Fleisch zu mageren Wolfsteaks zu und bringt diese dann zu mir. Alles klar?Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8612] = {title = "Die Horde braucht mehr magere Wolfsteaks!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8613] = {title = "Die Horde braucht Tüpfelgelbschwänze!", objective = "Bringt 20 Tüpfelgelbschwänze zu Angler Lin'do im Tal der Geister in Orgrimmar.", description = "Wär' heute nicht ein guter Tag zum Angeln? Praktisch, denn es sieht aus, als würde ich hier noch 'ne Menge Fisch brauchen. Die Horde hat mich mit der Sammlung von einem Haufen Tüpfelgelbschwänzen beauftragt. Sie sagen, dass sie sie für ihre Vorbereitungen für den Krieg in Ahn'Qiraj benötigen. Ich hab' gesagt, dass ich mein Bestes geben werde. Ich brauche also etwas Unterstützung. Ihr werdet mir doch helfen, <Klasse>, oder?", progress = "Schon wieder zurück mit den Tüpfelgelbschwänzen, <Klasse>? Habt Ihr auch nicht vergessen sie zu kochen? Wir setzen unseren Soldaten keinen rohen Fisch bei der Gluthitze vor, die in der Wüste herrscht.", completion = "Oh ja, das sieht gut aus. Ich werde alles hübsch verpacken, damit nichts verloren geht. Habt vielen Dank für Eure Hilfe. In meinen Augen seid Ihr die absolute Nummer eins, wenn es um das Angeln von Tüpfelgelbschwänzen geht! Tja, und falls Ihr noch mehr angelt und kocht, scheut Euch nicht, sie mir zu bringen. Ich werde dann sicherstellen, dass jeder von Eurer Spende erfährt.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8614] = {title = "Die Horde braucht mehr Tüpfelgelbschwänze!", objective = "Ja, in der Tat, wir brauchen hier noch mehr Fisch. Unsere Kämpfer werden in Ahn'Qiraj eine Menge an Essen brauchen. Ich benötige daher alle Tüpfelgelbschwänze, die ich bekommen kann. Fangt sie, kocht sie und bringt sie dann zu mir. Ich werde Euch dafür in meinem und im Namen der Horde danken.", description = nil, progress = "Ja, in der Tat, wir brauchen hier noch mehr Fisch. Unsere Kämpfer werden in Ahn'Qiraj eine Menge an Essen brauchen. Ich benötige daher alle Tüpfelgelbschwänze, die ich bekommen kann. Fangt sie, kocht sie und bringt sie dann zu mir. Ich werde Euch dafür in meinem und im Namen der Horde danken.", completion = "Das ist der bisher beste Fang, &lt;Name&gt;! Da habt Ihr gute Arbeit geleistet. Ihr habt sogar alle Gräten entfernt! Vielen Dank für diese Tüpfelgelbschwänze, verehrter Freund. Kommt wieder, wenn Ihr mal wieder einige Fische gekocht habt!", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8615] = {title = "Die Horde braucht gebackenen Lachs!", objective = "Bringt 20 Stück gebackenen Lachs zu Häuptling Sharpclaw im Tal der Geister in Orgrimmar.", description = "Die Vorbereitungen für den Krieg von Ahn'Qiraj sind ein immenses Unterfangen, <Klasse>. All die Materialien, die hier gesammelt werden, sind gleichermaßen wichtig - ob es Metall für Waffen oder Proviant zum Essen ist. Hat man seit Tagen nichts gegessen, so kann man, wenn es darauf ankommt, auch nicht mehr seine Axt schwingen.\n\nDafür sammeln wir hier so viele Nahrungsmittel wie wir können. Ich sammle zum Beispiel gebackenen Lachs, ein Gericht, das wegen seiner Nahrhaftigkeit und guten Lagerbedingungen gewählt wurde. Könnt Ihr mir bei dieser Aufgabe helfen, <Klasse>?Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8616] = {title = "Die Horde braucht mehr gebackenen Lachs!", objective = "Die letzte Ladung gebackener Lachs, die Ihr mir gebracht habt, sah sehr lecker aus, <Klasse>. Ich muss zugeben, dass ich sehr versucht war, einige für mich selbst beiseite zu legen. Bis jetzt haben wir unser Soll allerdings noch nicht erreicht. Ich hoffe Ihr seid wieder da, weil Ihr mehr gebackenen Lachs dabei habt.", description = nil, progress = "Die letzte Ladung gebackener Lachs, die Ihr mir gebracht habt, sah sehr lecker aus, <Klasse>. Ich muss zugeben, dass ich sehr versucht war, einige für mich selbst beiseite zu legen. Bis jetzt haben wir unser Soll allerdings noch nicht erreicht. Ich hoffe Ihr seid wieder da, weil Ihr mehr gebackenen Lachs dabei habt.", completion = "Ihr habt soviel Zeit und Energie in die Kriegsvorbereitungen gesteckt, wie kein Zweiter, &lt;Name&gt;! Ich kann Euch versichern, dass Eure Mühen an den richtigen Stellen zur Kenntnis genommen wurden. Ihr habt meinen Dank und den der Horde. Ich hoffe Ihr kehrt zu mir zurück, wenn Ihr mehr gebackenen Lachs dabei habt.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen der HordeKriegsmaterial für Ahn'Qiraj"},
[8617] = {title = "Die Horde braucht sengende Kernsteine!", objective = "Bringt 50 sengende Kernsteine zu General Zog in Durotar.", description = "Es ist an der Zeit, dass Ihr etwas zu den Kriegsanstrengungen von Ahn'Qiraj beitragt, <Klasse>. Die ruhigen Tage, an denen Ihr Eure Zeit mit Vergnügen verbracht habt, sind vorbei. Jetzt sollt Ihr mir und der Horde dienen... und ich versichere Euch, dass ich nicht so nachsichtig wie der Kriegshäuptling bin.\n\nSammelt Eure Kräfte, Eure Gilde, wenn möglich, und dringt in den geschmolzenen Kern vor. Ihr werdet feststellen, dass man dort an etlichen Stellen sengende Kernsteine finden kann. Bringt mir davon eine auseichend große Menge.", progress = nil, completion = nil, rewards = nil},
[8618] = {title = "Die Horde braucht mehr sengende Kernsteine!", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[8619] = {title = "Urahne Morndeep", objective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, <Name>. Nehmt dies als Zeichen meiner Dankbarkeit.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der Urahnen"},
[8620] = {title = "Der einzige Weg", objective = "Findet die 8 verlorenen Kapitel von Drachisch für Dummies und vereint sie mit dem magischen Bucheinband. Bringt das vollständige Buch \"Drachisch für Dummies: Band 2\" zu Narain Soothfancy in Tanaris.", description = "Ich hätte es wissen müssen. Mein Erzfeind, Doktor Weavil, hat wieder seine dreckigen Finger im Spiel! Jetzt, nach Eurem Versagen in Winterspring, hat Doktor Weavil mein Buch zerstört! Wie wollt Ihr jetzt die Welt retten, Held?\n\nDie Nachricht die ich erhalten habe, gab an, dass die einzig bekannte Kopie von \"Drachisch für Dummies: Band 2\" in 8 Teile zerissen und im Wind zerstreut wurde! Solltet Ihr diese fehlenden Kapitel irgendwie finden können, dann verwendet diesen magischen Bucheinband, um sie wieder zusammen zu flicken. Kehrt dann zu mir zurück.", progress = "Ich mach's genauso wie Ihr - und wenn, dann mache ich es richtig... und sollte es sich anbieten, dann mache ich Arkanitbojen. Arkanitbojen, Baby!", completion = "Fantastisch! Ich kann nicht glauben, dass Ihr dieses Dilemma überstanden habt! Seid Ihr so eine Art Maschine? Wenn es nach mir ginge, hätte ich die Welt wahrscheinlich ganz einfach implodieren lassen.\n\nIch ziehe meinen Turban vor Euch, Sire. Keine gute Tat soll unbezahlt bleiben.", rewards = "Ihr bekommt:\n\nTurban der gnomischen Superpsychokräfte"},
[8621] = {title = "Fußschützer des Sturmrufers", objective = "Bringt die Dominanzbindungen der Qiraji, 2 Götzen der Weisen, 5 Bronzeskarabäen und 5 Tonskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.", description = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.\n\nBringt mir die Dominanzbindungen der Qiraji, sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.\n\nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.", progress = "Habt Ihr die von mir benötigten Gegenstände erlangt, <Name>?", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Ihr habt bewiesen, dass Ihr kein gewöhnlicher Sterblicher seid.\n\nIch gebe Euch dies hier mit Zuversicht, auf dass sie Euch beim Niederschmettern der bösartigen Qiraji behilflich sein werden.", rewards = "Ihr bekommt:\n\nFußschützer des Sturmrufers"},
[8622] = {title = "Halsberge des Sturmrufers", objective = "Bringt den Knochenpanzer des alten Gottes, 2 Götzen der Weisen, 5 Silberskarabäen und 5 Knochenskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.", description = "Der unaussprechliche alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.\n\nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.\n\nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!", progress = "Der furchtbare C'Thun wartet ruhend in seiner Behausung in Ahn'Qiraj.", completion = "Ich habe nicht erwartet, dass Ihr von Eurer Unternehmung zurückkehrt, &lt;Name&gt;.\n\nIhr habt eine größere Vorsehung erfüllt als die der meisten sterblichen Wesen.\n\nIndem Ihr C'Thun bezwungen habt, habt Ihr nicht nur ganz Azeroth gerettet, sondern auch kosmische Ereignisse in Gang gesetzt, die weit über Eurem Vorstellungsvermögen liegen.\n\nNehmt diese Brustplatte als Zeichen des Ruhms und der Bürde an, die Euch in Folge Eurer Taten erwarten werden.\n\nMöge ihre Macht bei Euren zukünftigen Herausforderungen mit Euch sein, Göttertöter!", rewards = "Ihr bekommt:\n\nHalsberge des Sturmrufers"},
[8623] = {title = "Diadem des Sturmrufers", objective = "Bringt Vek'lors Diadem, 2 Götzen der Wiedergeburt, 5 Steinskarabäen und 5 Kristallskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", description = "Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.\n\nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.\n\nBringt mir die benötigten Bestandteile, <Name>. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, <Name>?", completion = "Ihr seid erfolgreich gewesen! Das Flüstern der Zwillingsimperatoren ist verstummt.\n\nNehmt dies als Belohnung. Der bloße Anblick hiervon wird Furcht in die Herzen der Qiraji treiben... es soll sie an ihre gefallenen Anführer erinnern und an den Sterblichen, der sie niederstreckte.", rewards = "Ihr bekommt:\n\nDiadem des Sturmrufers"},
[8624] = {title = "Gamaschen des Sturmrufers", objective = "Bringt die Haut des großen Sandwurms, 2 Götzen des Kampfes, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", description = "Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.\n\nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem alten Gott selbst als Gespött des Lebens erschaffen wurde.\n\nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.\n\nBringt mir eine Probe seiner Haut, sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGamaschen des Sturmrufers"},
[8625] = {title = "Schulterpolster des Mysteriums", objective = "Bringt die Dominanzbindungen der Qiraji, 2 Götzen der Wiedergeburt, 5 Silberskarabäen und 5 Elfenbeinskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.", description = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.\n\nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!", progress = "Habt Ihr die von mir benötigten Bestandteile gesammelt?", completion = "Ich werde diese Schulterstücke aus dem Material, das Ihr mir gebracht habt, und den Schuppen der gefallenen Qirajifeinde herstellen, Sterblicher. Mögen sie Euch den Schutz geben, den Ihr braucht, und möge ihr Anblick unseren Feinden Furcht einflößen.", rewards = "Ihr bekommt:\n\nSchulterpolster des Mysteriums"},
[8626] = {title = "Fußschützer des Hetzers", objective = "Bringt die Dominanzbindungen der Qiraji, 2 Götzen des Lebens, 5 Steinskarabäen und 5 Knochenskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.", description = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.\n\nBringt mir die Befehlsbindungen der Qiraji, sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.\n\nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.", progress = "Habt Ihr die von mir benötigten Gegenstände erlangt, <Name>?", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Ihr habt bewiesen, dass Ihr kein gewöhnlicher Sterblicher seid.\n\nIch gebe Euch dies hier mit Zuversicht, auf dass sie Euch beim Niederschmettern der bösartigen Qiraji behilflich sein werden.", rewards = "Ihr bekommt:\n\nFußschützer des Hetzers"},
[8627] = {title = "Brustplatte des Rächers", objective = "Bringt den Knochenpanzer des alten Gottes, 2 Götzen der Weisen, 5 Silberskarabäen und 5 Knochenskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.", description = "Der unaussprechliche alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.\n\nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.\n\nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBrustplatte des Rächers"},
[8628] = {title = "Krone des Rächers", objective = "Bringt Vek'lors Diadem, 2 Götzen der Wiedergeburt, 5 Steinskarabäen und 5 Kristallskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", description = "Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.\n\nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.\n\nBringt mir die benötigten Bestandteile, <Name>. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKrone des Rächers"},
[8629] = {title = "Beinschützer des Rächers", objective = "Bringt die Haut des großen Sandwurms, 2 Götzen des Kampfes, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", description = "Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.\n\nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem alten Gott selbst als Gespött des Lebens erschaffen wurde.\n\nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.\n\nBringt mir eine Probe seiner Haut, sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeinschützer des Rächers"},
[8630] = {title = "Schulterstücke des Rächers", objective = "Bringt die Dominanzbindungen der Qiraji, 2 Götzen des Lebens, 5 Kristallskarabäen und 5 Goldskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.", description = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.\n\nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchulterstücke des Rächers"},
[8631] = {title = "Gamaschen des Mysteriums", objective = "Bringt Ouros intakte Haut, 2 Götzen der Weisen, 5 Silberskarabäen und 5 Knochenskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", description = "Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.\n\nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem alten Gott selbst als Gespött des Lebens erschaffen wurde.\n\nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.\n\nBringt mir eine Probe seiner Haut, sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, <Name>?", completion = "Ja... die Haut des Wurms wird eine wunderbar schützende Schicht abgeben. In Verbindung mit den stärksten Teilen der Qiraji, die wir auf unserem Weg hierher zerstört haben, sollte dies eine prächtige Rüstung abgeben. Möge sie Euch bei der Begegnung des unaussprechlichen Grauens helfen, das Euch im Innern erwarten wird!", rewards = "Ihr bekommt:\n\nGamaschen des Mysteriums"},
[8632] = {title = "Reif des Mysteriums", objective = "Bringt Vek'nilashs Reif, 2 Götzen der Nacht, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", description = "Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.\n\nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.\n\nBringt mir die benötigten Bestandteile, <Name>. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, <Name>?", completion = "Ihr seid erfolgreich gewesen! Das Flüstern der Zwillingsimperatoren ist verstummt.\n\nNehmt dies als Belohnung. Der bloße Anblick hiervon wird Furcht in die Herzen der Qiraji treiben... es soll sie an ihre gefallenen Anführer erinnern und an den Sterblichen, der sie niederstreckte.", rewards = "Ihr bekommt:\n\nReif des Mysteriums"},
[8633] = {title = "Roben des Mysteriums", objective = "Bringt die Hülle des alten Gottes, 2 Götzen der Sonne, 5 Goldskarabäen und 5 Tonskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.", description = "Der unaussprechliche alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.\n\nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.\n\nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!", progress = "Der furchtbare C'Thun wartet ruhend in seiner Behausung in Ahn'Qiraj.", completion = "Ich habe nicht erwartet, dass Ihr von Eurer Unternehmung zurückkehrt, &lt;Name&gt;.\n\nIhr habt eine größere Vorsehung erfüllt als die der meisten sterblichen Wesen.\n\nIndem Ihr C'Thun bezwungen habt, habt Ihr nicht nur ganz Azeroth gerettet, sondern auch kosmische Ereignisse in Gang gesetzt, die weit über Eurem Vorstellungsvermögen liegen.\n\nNehmt diese Roben als Zeichen des Ruhms und der Bürde an, die Euch in Folge Eurer Taten erwarten werden.\n\nMöge ihre Macht bei Euren zukünftigen Herausforderungen mit Euch sein, Göttertöter!", rewards = "Ihr bekommt:\n\nRoben des Mysteriums"},
[8634] = {title = "Stiefel des Mysteriums", objective = "Bringt die Dominanzbindungen der Qiraji, 2 Götzen der Sonne, 5 Silberskarabäen und 5 Kristallskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.", description = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.\n\nBringt mir die Dominanzbindungen der Qiraji, sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.\n\nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.", progress = "Habt Ihr die von mir benötigten Gegenstände erlangt, <Name>?", completion = "Das habt Ihr gut gemacht, &lt;Name&gt;. Ihr habt bewiesen, dass Ihr kein gewöhnlicher Sterblicher seid.\n\nIch gebe Euch dies hier mit Zuversicht, auf dass sie Euch beim Niederschmettern der bösartigen Qiraji behilflich sein werden.", rewards = "Ihr bekommt:\n\nStiefel des Mysteriums"},
[8635] = {title = "Urahne Splitrock", objective = "Die Kämpfe vergangener Zeiten sind die Saat aus der Legenden entstehen. Eure Zeit ist die der Helden, mein Kind. Möge Eure Legende Wurzeln fassen und gedeihen.\n\nIch wünsche Euch viel Glück, <Name>, und bitte, nehmt dies als Zeichen meiner Dankbarkeit...", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der Urahnen"},
[8636] = {title = "Urahne Rumblerock", objective = "Die Dinge des Lebens sind zum Sterben verdammt und kehren zur Erde zurück. Das Geistliche lebt jedoch für immer weiter. Ich wünsche Euch viel Glück, <Name>, und bitte, nehmt dies als Zeichen meiner Dankbarkeit...", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der Urahnen"},
[8637] = {title = "Stiefel des Todesboten", objective = "Bringt die Befehlsbindungen der Qiraji, 2 Götzen des Kampfes, 5 Kristallskarabäen und 5 Knochenskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.", description = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.\n\nBringt mir die Befehlsbindungen der Qiraji, sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.\n\nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nStiefel des Todesboten"},
[8638] = {title = "Weste des Todesboten", objective = "Bringt den Knochenpanzer des alten Gottes, 2 Götzen des Kampfes, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.", description = "Der unaussprechliche alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.\n\nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.\n\nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWeste des Todesboten"},
[8639] = {title = "Helm des Todesboten", objective = "Bringt Vek'lors Diadem, 2 Götzen des Krieges, 5 Goldskarabäen und 5 Tonskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", description = "Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.\n\nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.\n\nBringt mir die benötigten Bestandteile, <Name>. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, <Name>?", completion = "Ihr seid erfolgreich gewesen! Das Flüstern der Zwillingsimperatoren ist verstummt.\n\nNehmt dies als Belohnung. Der bloße Anblick hiervon wird Furcht in die Herzen der Qiraji treiben... es soll sie an ihre gefallenen Anführer erinnern und an den Sterblichen, der sie niederstreckte.", rewards = "Ihr bekommt:\n\nHelm des Todesboten"},
[8640] = {title = "Gamaschen des Todesboten", objective = "Bringt Ouros intakte Haut, 2 Götzen der Nacht, 5 Steinskarabäen und 5 Kristallskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", description = "Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.\n\nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem alten Gott selbst als Gespött des Lebens erschaffen wurde.\n\nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.\n\nBringt mir eine Probe seiner Haut, sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGamaschen des Todesboten"},
[8641] = {title = "Schiftung des Todesboten", objective = "Bringt die Befehlsbindungen der Qiraji, 2 Götzen der Sonne, 5 Silberskarabäen und 5 Tonskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.", description = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.\n\nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!", progress = "Habt Ihr die von mir benötigten Bestandteile gesammelt?", completion = "Ich werde diese Schulterstücke aus dem Material, das Ihr mir gebracht habt, und den Schuppen der gefallenen Qirajifeinde herstellen, Sterblicher. Mögen sie Euch den Schutz geben, den Ihr braucht, und möge ihr Anblick unseren Feinden Furcht einflößen.", rewards = "Ihr bekommt:\n\nSchiftung des Todesboten"},
[8642] = {title = "Urahne Silvervein", objective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, <Name>. Nehmt dies als Zeichen meiner Dankbarkeit.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der Urahnen"},
