[8685] = {title = "Urahnin Mistwalker", objective = "Ich spüre das Feuer des Lebens in Euch, <Klasse>. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...Der folgende Zauber wird auf euch gewirkt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der Urahnen"},
[8686] = {title = "Urahne High Mountain", objective = "Ich spüre das Feuer des Lebens in Euch, <Klasse>. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der Urahnen"},
[8687] = {title = "Ziel: Tunnelgräber des Zoraschwarms", objective = "Tötet 30 Tunnelgräber des Zoraschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz VII, um diese Aufgabe abschließen zu können.", description = "Es wurde Verstärkung für den Angriff auf den Bau des Zoraschwarms angefordert. Man hat Euch ausgewählt, um die Tunnelgräber des Zoraschwarms anzugreifen. Erstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", progress = "Ihr habt etwas, das Ihr mir erzählen wollt, <Klasse>?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Die Silithiden werden ohne ihre Tunnelgräber Schwierigkeiten haben, all die Schäden zu reparieren, die ihre Baustruktur erlitten hat. Ich vermute, dass Ihr nach einer neuen Aufgabe sucht.", rewards = "Ihr bekommt:\n\nCenarisches Gefechtsabzeichen"},
[8688] = {title = "Urahne Windrun", objective = "Der Himmel, mit seinen unzähligen Sternen, bietet die Antworten auf alle irdenen Fragen, <Name>. Mag es sein, dass wenn der Weise und Glückliche zu ihnen aufblickt, er die tiefere Wahrheit findet?", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der Urahnen"},
[8689] = {title = "Schleier der unendlichen Weisheit", objective = "Bringt 1 Kampftuch der Qiraji, 2 Jaspisgötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, <Name>. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, <Klasse>.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchleier der unendlichen Weisheit"},
[8690] = {title = "Umhang der aufziehenden Stürme", objective = "Bringt 1 Hoheitstuch der Qiraji, 2 Obsidiangötzen, 5 Tonskarabäen und 5 Goldskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, <Name>. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, <Klasse>.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nUmhang der aufziehenden Stürme"},
[8691] = {title = "Tuch der behüteten Geheimnisse", objective = "Bringt 1 Kampftuch der Qiraji, 2 Alabastergötzen, 5 Steinskarabäen und 5 Kristallskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, <Name>. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, <Klasse>.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", progress = "Habt Ihr mir die Materialien für den Umhang gebracht, <Name>?", completion = "Ah ja... dieses Tuch ist perfekt.\n\nNehmt diesen Umhang, &lt;Name&gt;. Möge er Euch vor der üblen Magie der Qiraji schützen.", rewards = "Ihr bekommt:\n\nTuch der behüteten Geheimnisse"},
[8692] = {title = "Umhang des endlosen Lebens", objective = "Bringt 1 Hoheitstuch der Qiraji, 2 Zinnobergötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, <Name>. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, <Klasse>.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nUmhang des endlosen Lebens"},
[8693] = {title = "Umhang der Schattenschleier", objective = "Bringt 1 Kampftuch der Qiraji, 2 Azurgötzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, <Name>. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, <Klasse>.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", progress = "Habt Ihr mir die Materialien für den Umhang gebracht, <Name>?", completion = "Ah ja... dieses Tuch ist perfekt.\n\nNehmt diesen Umhang, &lt;Name&gt;. Möge er Euch vor der üblen Magie der Qiraji schützen.", rewards = "Ihr bekommt:\n\nUmhang der Schattenschleier"},
[8694] = {title = "Schleier der ungesagten Namen", objective = "Bringt 1 Hoheitstuch der Qiraji, 2 Bernsteingötzen, 5 Elfenbeinskarabäen und 5 Bronzeskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, <Name>. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, <Klasse>.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchleier der ungesagten Namen"},
[8695] = {title = "Cape der ewigen Gerechtigkeit", objective = "Bringt 1 Hoheitstuch der Qiraji, 2 Obsidiangötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, <Name>. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, <Klasse>.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nCape der ewigen Gerechtigkeit"},
[8696] = {title = "Umhang des unsichtbaren Pfads", objective = "Bringt 1 Hoheitstuch der Qiraji, 2 züngelnde Götzen, 5 Steinskarabäen und 5 Kristallskarabäen zu Keyl Swiftclaw in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, <Name>. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, <Klasse>.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", progress = "Habt Ihr mir die Materialien für den Umhang gebracht, <Name>?", completion = "Ah ja... dieses Tuch ist perfekt.\n\nNehmt diesen Umhang, &lt;Name&gt;. Möge er Euch vor der üblen Magie der Qiraji schützen.", rewards = "Ihr bekommt:\n\nUmhang des unsichtbaren Pfads"},
[8697] = {title = "Ring der unendlichen Weisheit", objective = "Bringt 1 Zeremonienring der Qiraji, 2 Obsidiangötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", description = "Man sagt, dass die Ringe, die von den Lieutenants der Qiraji getragen werden, ungeheuere Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, <Klasse>.", progress = "Habt Ihr mir den Ring und die Gegenstände besorgt, <Name>?", completion = "Ich werde den Edelstein auf dem Ring für Euch austauschen. Ihr werdet sehen, dass der Effekt viel... angenehmer ist.", rewards = "Ihr bekommt:\n\nRing der unendlichen Weisheit"},
[8698] = {title = "Ring der aufziehenden Stürme", objective = "Bringt 1 Gebieterring der Qiraji, 2 Zinnobergötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", description = "Man sagt, dass die Ringe, die von den Lieutenants der Qiraji getragen werden, ungeheuere Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, <Klasse>.", progress = "Habt Ihr mir den Ring und die Gegenstände besorgt, <Name>?", completion = "Ich werde den Edelstein auf dem Ring für Euch austauschen. Ihr werdet sehen, dass der Effekt viel... angenehmer ist.", rewards = "Ihr bekommt:\n\nRing der aufziehenden Stürme"},
[8699] = {title = "Band des behüteten Geheimnisse", objective = "Bringt 1 Gebieterring der Qiraji, 2 Azurgötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", description = "Man sagt, dass die Ringe, die von den Lieutenants der Qiraji getragen werden, ungeheuere Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, <Klasse>.", progress = "Habt Ihr mir den Ring und die Gegenstände besorgt, <Name>?", completion = "Ich werde den Edelstein auf dem Ring für Euch austauschen. Ihr werdet sehen, dass der Effekt viel... angenehmer ist.", rewards = "Ihr bekommt:\n\nBand der behüteten Geheimnisse"},
[8700] = {title = "Band des endlosen Lebens", objective = "Bringt 1 Gebieterring der Qiraji, 2 Alabastergötzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", description = "Man sagt, dass die Ringe, die von den Lieutenants der Qiraji getragen werden, ungeheuere Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, <mein getreuer Druide/meine getreue Druidin>.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBand des endlosen Lebens"},
[8701] = {title = "Band der Schattenschleier", objective = "Bringt 1 Zeremonienring der Qiraji, 2 Onyxgötzen, 5 Steinskarabäen und 5 Kristallskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", description = "Man sagt, dass die Ringe, die von den Lieutenants der Qiraji getragen werden, ungeheuere Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, <Klasse>.", progress = "Habt Ihr mir den Ring und die Gegenstände besorgt, <Name>?", completion = "Ich werde den Edelstein auf dem Ring für Euch austauschen. Ihr werdet sehen, dass der Effekt viel... angenehmer ist.", rewards = "Ihr bekommt:\n\nBand der Schattenschleier"},
