[8713] = {title = "Urahnin Starsong", objective = "Der Himmel, mit seinen unzähligen Sternen, bietet die Antworten auf alle irdenen Fragen, <Name>. Mag es sein, dass wenn der Weise und Glückliche zu ihnen aufblickt, er die tiefere Wahrheit findet?", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der Urahnen"},
