[8761] = {title = "Der große Herbeirufer", objective = "Selten habe ich solch eine Hingabe, solch ein Durchhaltevermögen gesehen! Der bronzene Drachenschwarm gewährt Euch die mächtigste Verzauberung. Der Zeitlose selbst, hat es befohlen!\n\nÜbergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", description = nil, progress = "Selten habe ich solch eine Hingabe, solch ein Durchhaltevermögen gesehen! Der bronzene Drachenschwarm gewährt Euch die mächtigste Verzauberung. Der Zeitlose selbst, hat es befohlen!\n\nÜbergebt mir Euren Siegelring, damit ich seine Kräfte verstärken kann.", completion = "Erhebt Euch, großer Herbeirufer! Zeigt Euch und lasst Euch huldigen!", rewards = "Ihr bekommt:\n\nSiegelring des bronzenen Drachenschwarms"},
[8762] = {title = "Metzen das Rentier", objective = "Findet Metzen das Rentier. Lest Euch die erhaltenen Notizen durch, um Tipps über seinen Aufenthaltsort zu erhalten.\n\nWenn Ihr Metzen findet, solltet Ihr den Beutel mit Rentierstaub dabeihaben. Berieselt Ihr Metzen mit dem Staub, sollte dies ihn aus seiner Gefangenschaft befreien.\n\nBringt den Beutel zu Wulmort Jinglepocket in Ironforge zurück, sobald Ihr Metzen befreit habt.", description = "Es ist eine KATASTROPHE! Metzen das Rentier wurde entführt!\n\nMetzen ist eines von Altvater Winters acht Rentieren - und Eigentum von Kokelwälder. Wir haben nicht nur einen, sondern ZWEI Erpresserbriefe von Gruppen erhalten. Beide behaupten, Metzen in ihrer Gewalt zu haben. Gerade jetzt zur Festtagszeit haben wir hier ein echtes Problem. Bitte findet Metzen und bringt ihn zurück!\n\nSchaut Euch die Erpresserbriefe an, vielleicht findet Ihr darin ja Hinweise. Streut diesen Rentierstaub über ihn, wenn Ihr ihn findet, er wird ihn aus sämtlichen Fesseln befreien!\n\nBitte, beeilt Euch!", progress = "<Name>! Habt Ihr ihn gefunden? Konntet Ihr den Notizen, die ich Euch mitgegeben habe, genug Informationen entnehmen, um ihn ausfindig zu machen? Mir wird ganz schlecht wenn ich daran denke, was diese fiesen Strolche ihm antun könnten… Ein so hohes Lösegeld können wir uns einfach nicht leisten.", completion = "Ihr habt es geschafft! Hurra!\n\nMetzen ist gerade eben erst zurück zu den Ställen von Altvater Winter geflogen. Ja, Metzen kann wirklich fliegen! Der Staub hat ganze Arbeit geleistet, ich wusste, das würde funktionieren. Ihr habt das Winterhauchfest und Kokelwälder vor dem Untergang bewahrt. Danke, &lt;Name&gt;.\n\nHört mal, weil Ihr das für uns getan habt, möchte ich Euch das hier geben. Das ist etwas GANZ Besonderes. Wenn Ihr ein Reittier habt, werdet Ihr bestimmt eine Menge Spaß damit haben. Frohes Winterhauchfest!", rewards = "Ihr bekommt:\n\nKonservierter Tannenzweig"},
[8763] = {title = "Der Held des Tages", objective = "Bringt 1 Tiefsteinsalz und 5 Goldstücke zum Tannenzweigkonservierer. Ihr werdet 5 konservierte Tannenzweige erhalten.", description = "Eigentlich darf ich Euch das gar nicht sagen, aber da Ihr ja der Held des Tages seid, mach ich mal 'ne Ausnahme.\n\nUm diese Jahreszeit gibt es überall frische Tannenzweige, aber die Zweige bleiben nicht lange frisch. Wir haben eine Maschine, die Tannenzweige konserviert - die bleiben dann für immer frisch! Wir benutzen sie um die Festtage etwas aufzupeppen... und unsere Profite im Sommer zu steigern!\n\nIch lasse Euch den Konservierer benutzen, aber nur, wenn Ihr ein Meisterkoch seid. Ihr werdet etwas Tiefsteinsalz und etwa zwei, drei, ach, sagen wir einfach fünf Goldstücke brauchen. Damit solltet Ihr ein nettes Bündel konservieren können, das Ihr behalten könnt.", progress = "Der Tannenzweigkonservierer sieht auf den ersten Blick wie eine Art Destillierapparat aus, bei genauerer Betrachtung werden allerdings einige goblinartige Veränderungen offensichtlich. Eure Fähigkeiten in der Kochkunst erlauben es Euch allerdings zu verstehen, wie die Maschine funktioniert.\n\nEs sind schon frische Tannenzweige in der Maschine - Ihr müsst nur noch Tiefsteinsalz dazugeben und fünf Goldstücke einwerfen, um sie ans Laufen zu bringen.", completion = "Die Maschine fängt an zu rumpeln und Dampf auszuspeien, während sie mit der Arbeit beginnt. Schon kurz darauf ist sie fertig. Sie spuckt noch etwas Dampf aus und eine Klappe öffnet sich. In der Öffnung befindet sich ein Bündel konservierter Tannenzweige.", rewards = "Ihr bekommt:\n\nKonservierter Tannenzweig"},
[8764] = {title = "Den Pfad wechseln - Kein Beschützer mehr", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSiegelring des bronzenen DrachenschwarmsSiegelring des bronzenen Drachenschwarms"},
[8765] = {title = "Den Pfad wechseln - Kein Herbeirufer mehr", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSiegelring des bronzenen DrachenschwarmsSiegelring des bronzenen Drachenschwarms"},
[8766] = {title = "Den Pfad wechseln - Kein Eroberer mehr", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSiegelring des bronzenen DrachenschwarmsSiegelring des bronzenen Drachenschwarms"},
[8767] = {title = "Ein leicht geschütteltes Geschenk", objective = "Dieses Geschenk sieht aus, als wäre es schon ein paar Mal geschüttelt worden. Auf dem Kärtchen steht:B\nFür <Name>, einen ganz besonderen Helden.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nLeicht geschütteltes Geschenk"},
[8768] = {title = "Ein fröhlich verpacktes Geschenk", objective = "Auf diesem festlich verpackten Geschenk steht Euer Name!\n\n Hat sich das etwa gerade bewegt?", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFröhlich verpacktes Geschenk"},
[8769] = {title = "Ein tickendes Geschenk", objective = "Ein wundervolles Winterhauchfest wünschen Euch Eure Freunde bei Kokelwälder.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTickendes Geschenk"},
[8770] = {title = "Ziel: Verteidiger des Ashischwarms", objective = "Tötet 30 Verteidiger des Ashischwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz I, um diese Aufgabe abschließen zu können.", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Ashischwarms teilzunehmen. Eure Hauptziele sind die Verteidiger des Ashischwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", progress = "Ihr habt etwas, das Ihr mir erzählen wollt, <Klasse>?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Euer Eifer ist bemerkenswert!", rewards = "Ihr bekommt:\n\nCenarisches Gefechtsabzeichen"},
[8771] = {title = "Ziel: Sandpirscher des Ashischwarms", objective = "Tötet 30 Sandpirscher des Ashischwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz II, um diese Aufgabe abschließen zu können.", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Ashischwarms teilzunehmen. Eure Hauptziele sind die Sandpirscher des Ashischwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", progress = "Ihr habt etwas, das Ihr mir erzählen wollt, <Klasse>?", completion = "Exzellente Arbeit, &lt;Name&gt;. Eure Leistungen beim Angriff auf den Bau des Ashischwarms wurden zur Kenntnis genommen.", rewards = "Ihr bekommt:\n\nCenarisches Gefechtsabzeichen"},
[8772] = {title = "Ziel: Wegbehüter des Zoraschwarms", objective = "Tötet 30 Wegbehüter des Zoraschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz VI, um diese Aufgabe abschließen zu können.", description = "Es wurde Verstärkung für den Angriff auf den Bau des Zoraschwarms angefordert. Man hat Euch ausgewählt, um die Wegbehüter des Zoraschwarms anzugreifen. Erstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", progress = "Ihr habt etwas, das Ihr mir erzählen wollt, <Klasse>?", completion = "Exzellente Arbeit, &lt;Name&gt;. Eure Leistungen beim Angriff auf den Bau des Zoraschwarms wurden zur Kenntnis genommen.", rewards = "Ihr bekommt:\n\nCenarisches Gefechtsabzeichen"},
[8773] = {title = "Ziel: Häscher des Zoraschwarms", objective = "Tötet 30 Häscher des Zoraschwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz IV, um diese Aufgabe abschließen zu können.", description = "Es wurde Verstärkung für den Angriff auf den Bau des Zoraschwarms angefordert. Man hat Euch ausgewählt, um die Häscher des Zoraschwarms anzugreifen. Erstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", progress = "Ihr habt etwas, das Ihr mir erzählen wollt, <Klasse>?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Ich habe nur Gutes über Eure Teilnahme an dem Angriff gegen den Zoraschwarm gehört. Macht so weiter und der Sieg wird schon bald unser sein.", rewards = "Ihr bekommt:\n\nCenarisches Gefechtsabzeichen"},
[8774] = {title = "Ziel: Wegelagerer des Regalschwarms", objective = "Tötet 30 Wegelagerer des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz VIII, um diese Aufgabe abschließen zu können.", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt, je weiter die Kriegsvorbereitungen voranschreiten, eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Wegelagerer des Regalschwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", progress = "Ihr wollt mir etwas mitteilen, <Name>?", completion = "Exzellente Arbeit, &lt;Name&gt;. Eure Leistungen beim Angriff auf den Bau des Regalschwarms wurden zur Kenntnis genommen.", rewards = "Ihr bekommt:\n\nCenarisches Gefechtsabzeichen"},
[8775] = {title = "Ziel: Feuerspucker des Regalschwarms", objective = "Tötet 30 Feuerspucker des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz IX, um diese Aufgabe abschließen zu können.", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Feuerspucker des Regalschwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", progress = "Ihr wollt mir etwas mitteilen, <Name>?", completion = "Exzellente Arbeit, &lt;Name&gt;. Eure Leistungen beim Angriff auf den Bau des Regalschwarms wurden zur Kenntnis genommen.", rewards = "Ihr bekommt:\n\nCenarisches Gefechtsabzeichen"},
[8776] = {title = "Ziel: Sklavenjäger des Regalschwarms", objective = "Tötet 30 Sklavenjäger des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz X, um diese Aufgabe abschließen zu können.", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt, je weiter die Kriegsvorbereitungen voranschreiten, eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Sklavenjäger des Regalschwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", progress = "Ihr wollt mir etwas mitteilen, <Name>?", completion = "Exzellente Arbeit, &lt;Name&gt;. Eure Leistungen beim Angriff auf den Bau des Regalschwarms wurden zur Kenntnis genommen.", rewards = "Ihr bekommt:\n\nCenarisches Gefechtsabzeichen"},
[8777] = {title = "Ziel: Einbuddler des Regalschwarms", objective = "Tötet 30 Einbuddler des Regalschwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz XI, um diese Aufgabe abschließen zu können.", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Regalschwarms teilzunehmen. Eure Hauptziele sind die Einbuddler des Regalschwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", progress = "Ihr wollt mir etwas mitteilen, <Name>?", completion = "Exzellente Arbeit, &lt;Name&gt;. Eure Leistungen beim Angriff auf den Bau des Regalschwarms wurden zur Kenntnis genommen.", rewards = "Ihr bekommt:\n\nCenarisches Gefechtsabzeichen"},
[8778] = {title = "Die Ironforgebrigade braucht Sprengstoff!", objective = "Bringt Arkanist Nozzlespring nahe des Zoraschwarmbaus in Silithus 6 Öle des Feuerbrandes, 5 Einheiten Goblin-Raketentreibstoff und 10 Einheiten dichtes Sprengpulver. Ihr benötigt auch Logistikeinsatz IV, um diese Aufgabe abschließen zu können.", description = "Uns liegt eine Anforderung der Ironforgebrigade vor, die eine Menge… na sagen wir, recht explosive Komponenten umfasst. Beschafft diese Komponenten und bringt sie zu einem Kerl namens Nozzlespring, einem Mitglied der Ironforgebrigade.", progress = "Habt Ihr die Materialien, <Name>?", completion = "Ah, sehr gut. Das kommt mir alles sehr gelegen! Ich muss Euch danken, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenNachfolgender Logistikauftrag"},
[8779] = {title = "Magische Materialien", objective = "Bringt 1 großen glänzenden Splitter, 1 großen strahlenden Splitter und einen gewaltigen Smaragd zu Geologin Larksbane auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz V, um diese Aufgabe abschließen zu können.", description = "Geologin Larksbanes Studien haben sich für unsere Operationen in Silithus als sehr wertvoll erwiesen. Vor kurzem hat sie eine Ladung magischer Materialien angefordert, die sie für ihre weiteren Forschungen dringend benötigt.\n\nBeschafft die notwendigen Materialien und liefert sie direkt an sie aus, damit Geologin Larksbane ihre Forschungen ungestört fortsetzen kann.", progress = "Ihr habt etwas für mich, <Name>?", completion = "Ah, diese hier sind mir von großem Nutzen! Wisst Ihr &lt;Name&gt;, in dieser Wüste ist es sehr schwer an derartige Materialien zu kommen. Vielen Dank.", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenNachfolgender Logistikauftrag"},
[8780] = {title = "Rüstungssets für den Feldeinsatz", objective = "Bringt 8 unverwüstliche Rüstungssets und 8 schwere Rüstungsset zu Janela Stouthammer am Posten der Ironforgebrigade beim Zoraschwarmbau in Silithus. Ihr benötigt auch Logistikeinsatz VII, um diese Aufgabe abschließen zu können.", description = "Der Ironforgebrigade gehen im Feld die Rüstungssets aus. Schnappt Euch eine Ladung und bringt sie zu Janela Stouthammer am Posten der Ironforgebrigade beim Zoraschwarmbau.", progress = "Ihr habt etwas für mich, <Name>?", completion = "Vielen Dank, ich werde alles direkt an unsere Truppen ausgeben.", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenNachfolgender Logistikauftrag"},
[8781] = {title = "Waffen für den Feldeinsatz", objective = "Bringt 2 Mondstahlbreitschwerter zu Janela Stouthammer am Posten der Ironforgebrigade beim Zoraschwarmbau. Ihr benötigt auch Logistikeinsatz VI, um diese Aufgabe abschließen zu können.", description = "Die Ironforgebrigade hat sich in den Kämpfen von Silithus als ein würdiger Verbündeter erwiesen. Unglücklicherweise hat sie auf dem Weg hierher die meisten ihrer Vorräte eingebüßt. Beschafft eine Ladung Waffen und bringt sie zu Janela Stouthammer nahe des Baus des Zoraschwarms.", progress = "Ihr habt etwas für mich, <Name>?", completion = "Oh, fantastisch! Endlich muss ich mir kein Gemaule über stumpfe Waffen mehr anhören. Vielen Dank, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenNachfolgender Logistikauftrag"},
[8782] = {title = "Uniformnachschub", objective = "Bringt 1 Einheit Mondstoff, 2 Runenstoffballen und 1 Einheit Eisenweberseide zu Windruferin Proudhorn auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz VIII, um diese Aufgabe abschließen zu können.", description = "Die letzte Ladung neuer Rekruten hat uns einen Engpass an Uniformen beschert. Beschafft uns eine Ladung Schneiderwaren, damit wir mehr Uniformen herstellen können. Bringt alles zur Windruferin Proudhorn.", progress = "Ihr habt etwas für mich, <Name>?", completion = "Ah, genau was wir jetzt brauchen. Wir wissen Eure Arbeit sehr zu schätzen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenLogistikauftrag"},
[8783] = {title = "Besondere Materialien", objective = "Bringt Vargus auf Burg Cenarius in Silithus 2 verzauberte Thoriumbarren und 2 Einheiten verzaubertes Leder. Ihr benötigt auch Logistikeinsatz IX, um diese Aufgabe abschließen zu können.", description = "Vargus, der Schmied von Burg Cenarius, hat verzauberte Materialien zur Herstellung von stärkeren Waffen angefordert. Beschafft die benötigten Materialien und bringt sie direkt zu Vargus, um den hohen Ausrüstungsstand unserer Truppen auf Burg Cenarius aufrechtzuerhalten.", progress = "Ihr habt etwas für mich, <Name>?", completion = "Ah, sehr gut. Dieses Material ist von hervorragender Qualität. Vielen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenLogistikauftrag"},
[8784] = {title = "Geheimnisse der Qiraji", objective = "Bringt das uralte Qirajiartefakt zu den Drachen, die sich nahe des Tempeleingangs versteckt halten.", description = "Ihr habt ein uraltes Artefakt der Qiraji entdeckt! Vielleicht interessiert sich einer der Drachen am Eingang des Tempels für dieses Relikt.", progress = "Ihr glüht! Ich weiß, was das bedeutet…", completion = "Ein einmaliger Fund, &lt;Name&gt;. Einfach fantastisch! Mit Hilfe dieses Artefakts, erhalten wir sicherlich einen Einblick in die verquerte Denkensweise des Feindes.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBrut Nozdormus Fraktion +1000"},
[8785] = {title = "Die Orgrimmarlegion braucht Mojo!", objective = "Bringt Schattenpriesterin Shai nahe des Regalschwarmbaus in Silithus 6 Einheiten mächtiges Mojo, 6 Fläschchen großes Mojo und 8 Öle des Feuerbrandes. Ihr benötigt auch Logistikeinsatz IV, um diese Aufgabe abschließen zu können.", description = "Uns liegt eine Anforderung der Orgrimmarlegion vor, die eine Menge recht ungewöhnliche Materialien umfasst. Aber in Anbetracht ihrer jüngsten Leistungen in Silithus, möchten wir dieser Anfrage so schnell wie möglich nachkommen. Beschafft die notwendigen Materialien und bringt sie einer Trollfrau namens Shai.", progress = "Habt Ihr die Materialien, <Name>?", completion = "Ah, sehr gut. Genau, was ich gebraucht habe. Aus diesen Zutaten werde ich ein ganz spezielles Gebräu mischen. Den Silithiden wird es bestimmt nicht gut bekommen!", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenNachfolgender Logistikauftrag"},
[8786] = {title = "Waffen für den Feldeinsatz", objective = "Bring 3 massive Eisenäxte zu Merok Longstride im Lager der Orgrimmarlegion außerhalb des Regalschwarmbaus. Ihr benötigt auch Logistikeinsatz VI, um diese Aufgabe abschließen zu können.", description = "Die Orgrimmarlegion hatte bereits vor einiger Zeit zusätzliche Waffen angefordert, die wir bisher noch nicht liefern konnten. Beschafft die notwendigen Waffen und bringt sie zu Merok Longstride außerhalb des Regalschwarmbaus.", progress = "Ihr habt etwas für mich, <Name>?", completion = "Ausgezeichnete Arbeit. Unsere Vorräte gingen gerade zur Neige, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenNachfolgender Logistikauftrag"},
[8787] = {title = "Rüstungssets für den Feldeinsatz", objective = "Bringt 8 unverwüstliche Rüstungssets und 8 schwere Rüstungsset zu Merok Longstride nahe des Regalschwarmbaus. Ihr benötigt auch Logistikeinsatz VII, um diese Aufgabe abschließen zu können.", description = "Die Orgrimmarlegion ist zu unserer Unterstützung in Silithus eingetroffen. Unglücklicherweise hat sie auf dem Weg hierher die meisten ihrer Rüsstungssets eingebüßt. Beschafft eine Ladung und bringt sie zu Merok Longstride im Lager der Orgrimmarlegion.", progress = "Ihr habt etwas für mich, <Name>?", completion = "Ah, ja… Ich werde alles direkt an die Truppe ausgeben, &lt;Name&gt;. Die Orgrimmarlegion ist Euch zu Dank verpflichtet.", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenNachfolgender Logistikauftrag"},
[8788] = {title = "Ein leicht geschütteltes Geschenk", objective = "Dieses Geschenk sieht aus, als wäre es schon ein paar Mal geschüttelt worden. Auf dem Kärtchen steht:\n\nFür <Name>, einen ganz besonderen Helden.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nLeicht geschütteltes Geschenk"},
[8789] = {title = "Imperiale Qirajiwaffen", objective = "Arygos im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen, wenn Ihr ihm imperiale Qirajiwaffen und 3 Einheiten Elementiumerz bringt.", description = "Wir haben hier nicht ein Jahrtausend in völliger Untätigkeit verbracht, <Name>. Wir sahen mit eigenen Augen, wie sich diese Biester an ihren eigenen Artgenossen gütlich taten, nachdem diese ihre Nützlichkeit für den Schwarm verloren hatten. Wir lauschten, als sie ihre Pläne schmiedeten, diese Welt in Schutt und Asche zu legen. Und wir lernten, wie sich Verrat und Missgunst in ihren Reihen ausbreiten.\n\nSie haben Schwächen und wir wissen nun, wie wir diese zu unserem Vorteil nutzen können.\n\nFindet und bringt mir ihre Zeremonienwaffen. Zusammen, mit dem durch ihren Gott erschaffenen Element, werden wir daraus mächtige Instrumente der Zerstörung erschaffen.", progress = "Findet, worum ich Euch gebeten habe und Ihr werdet weit mehr als nur die Summe Eurer Teile werden, großer Held.", completion = "Jetzt, da diese Waffen mit Elementium erfüllt sind, werden sie sich mit Leichtigkeit durch jeden Qiraji und ihren Gott schneiden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesegnete QirajikriegsaxtGesegnete QirajimusketeGesegneter QirajipugioGesegneter Qirajischild"},
[8790] = {title = "Imperiale Qirajiinsignien", objective = "Merithra des Traums im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen. Bringt ihr dazu imperiale Qirajiinsignien und 3 Einheiten Elementiumerz.", description = "Arygos hat die Theorie aufgestellt, dass das Element, welches während des Konflikts zwischen den uralten Göttern und ihren Anhängern entstanden ist, unter den richtigen Bedingungen für sie tödlich ist. Ich spreche vom Elementium, <Sterblicher/Sterbliche>.\n\nFindet und bringt mir imperiale Qirajiinsignien sowie das giftige Element, dann werde ich Euch Waffen von größter Macht erschaffen!", progress = "Ihr werdet sie niederstrecken und uns von diesen Fesseln befreien.", completion = "Nutzt diesen Gegenstand weise, &lt;Name&gt;. Lasst sie den Schmerz ihrer Opfer am eigenen Leib erfahren.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesegneter Akolythenstab der QirajiGesegneter Weissagungsstab der QirajiGesegneter Qirajikriegshammer"},
[8791] = {title = "Der Untergang von Ossirian", objective = "Bringt den Kopf von Ossirian dem Narbenlosen zu Kommandant Mar'alith auf Burg Cenarius in Silithus.", description = "Eine schreckliche Bedrohung hat ihr Ende gefunden. Der grausame Ossirian existiert nicht mehr.\n\nDie Bewohner Kalimdors werden aufatmen, wenn sie von diesem glorreichen Sieg erfahren. Nehmt Ossirians Kopf und bringt ihn zu Kommandant Mar'alith auf Burg Cenarius.", progress = "Ah, <Name>. Wie ich sehe, seid Ihr zurückgekehrt und sogar in einem Stück! Welche Neuigkeiten bringt Ihr aus Ahn'Qiraj?", completion = "Ich entbiete Euch meine höchste Anerkennung und erlaube es Euch, einen Gegenstand von höchster Macht auszuwählen, &lt;Name&gt;! Ihr habt den Bewohnern von Kalimdor einen großen Dienst erwiesen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGlücksbringer der SandstürmeAmulett der SandstürmeHalsschmuck der SandstürmeAnhänger der Sandstürme\n\nIhr bekommt außerdem:\n\n"},
[8792] = {title = "Die Horde braucht Euch!", objective = "Sprecht mit Kriegsherr Gorchuk im Tal der Geister in Orgrimmar.", description = "Hallo, schön das Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Horde braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Horde braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, <Name>! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Kriegsherr Gorchuk. Können wir auf Euch zählen, <Klasse>? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?", progress = nil, completion = "Throm'ka, &lt;Klasse&gt;! Es ist schön zu sehen, dass Ihr uns in dieser dunklen Stunde zur Seite steht, &lt;Name&gt;! So viele Mitglieder der Horde haben sich bereits freiwillig verpflichtet, uns bei den Vorbereitungen für den aufziehenden Krieg in Ahn'Qiraj zu unterstützen. Unsere Anstrengungen hier, werden der Garant für den Sieg über die Silithiden und Ihre dunklen Meister sein!\n\nNun, jetzt da Ihr hier seid, solltet Ihr Euch mit den örtlichen Sammlern unterhalten und sehen, welche Materialien Ihr am besten beschaffen könnt.", rewards = "Ihr bekommt:\n\n"},
[8793] = {title = "Die Horde braucht Euch!", objective = "Sprecht mit Kriegsherr Gorchuk im Tal der Geister in Orgrimmar.", description = "Hallo, schön das Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Horde braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Horde braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, <Name>! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Kriegsherr Gorchuk. Können wir auf Euch zählen, <Klasse>? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?", progress = nil, completion = "Throm'ka, &lt;Klasse&gt;! Es ist schön zu sehen, dass Ihr uns in dieser dunklen Stunde zur Seite steht, &lt;Name&gt;! So viele Mitglieder der Horde haben sich bereits freiwillig verpflichtet, uns bei den Vorbereitungen für den aufziehenden Krieg in Ahn'Qiraj zu unterstützen. Unsere Anstrengungen hier, werden der Garant für den Sieg über die Silithiden und Ihre dunklen Meister sein!\n\nNun, jetzt da Ihr hier seid, solltet Ihr Euch mit den örtlichen Sammlern unterhalten und sehen, welche Materialien Ihr am besten beschaffen könnt.", rewards = "Ihr bekommt:\n\n"},
[8794] = {title = "Die Horde braucht Euch!", objective = "Sprecht mit Kriegsherr Gorchuk im Tal der Geister in Orgrimmar.", description = "Hallo, schön das Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Horde braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Horde braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, <Name>! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Kriegsherr Gorchuk. Können wir auf Euch zählen, <Klasse>? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?", progress = nil, completion = "Throm'ka, &lt;Klasse&gt;! Es ist schön zu sehen, dass Ihr uns in dieser dunklen Stunde zur Seite steht, &lt;Name&gt;! So viele Mitglieder der Horde haben sich bereits freiwillig verpflichtet, uns bei den Vorbereitungen für den aufziehenden Krieg in Ahn'Qiraj zu unterstützen. Unsere Anstrengungen hier, werden der Garant für den Sieg über die Silithiden und Ihre dunklen Meister sein!\n\nNun, jetzt da Ihr hier seid, solltet Ihr Euch mit den örtlichen Sammlern unterhalten und sehen, welche Materialien Ihr am besten beschaffen könnt.", rewards = "Ihr bekommt:\n\n"},
[8795] = {title = "Die Allianz braucht Euch!", objective = "Sprecht mit Feldmarschall Snowfall im Militärviertel von Ironforge.", description = "Hallo, schön das Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Allianz braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Allianz braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, <Name>! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Feldmarschall Snowfall. Können wir auf Euch zählen, <Klasse>? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;! Es ist schön zu sehen, dass Ihr uns in dieser dunklen Stunde zur Seite steht, &lt;Name&gt;! So viele Mitglieder der Allianz haben sich bereits freiwillig verpflichtet, uns bei den Vorbereitungen für den aufziehenden Krieg in Ahn'Qiraj zu unterstützen. Unsere Anstrengungen hier, werden der Garant für den Sieg über die Silithiden und Ihre dunklen Meister sein!\n\nNun, jetzt da Ihr hier seid, solltet Ihr Euch mit den örtlichen Sammlern unterhalten und sehen, welche Materialien Ihr am besten beschaffen könnt.", rewards = "Ihr bekommt:\n\n"},
[8796] = {title = "Die Allianz braucht Euch!", objective = "Sprecht mit Feldmarschall Snowfall im Militärviertel von Ironforge.", description = "Hallo, schön das Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Allianz braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Allianz braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, <Name>! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Feldmarschall Snowfall. Können wir auf Euch zählen, <Klasse>? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;! Es ist schön zu sehen, dass Ihr uns in dieser dunklen Stunde zur Seite steht, &lt;Name&gt;! So viele Mitglieder der Allianz haben sich bereits freiwillig verpflichtet, uns bei den Vorbereitungen für den aufziehenden Krieg in Ahn'Qiraj zu unterstützen. Unsere Anstrengungen hier, werden der Garant für den Sieg über die Silithiden und Ihre dunklen Meister sein!\n\nNun, jetzt da Ihr hier seid, solltet Ihr Euch mit den örtlichen Sammlern unterhalten und sehen, welche Materialien Ihr am besten beschaffen könnt.", rewards = "Ihr bekommt:\n\n"},
[8797] = {title = "Die Allianz braucht Euch!", objective = "Sprecht mit Feldmarschall Snowfall im Militärviertel von Ironforge.", description = "Hallo, schön das Ihr Euch entschieden habt, mir zuzuhören, was ich zu sagen habe. Die Allianz braucht jede Hilfe, die sie kriegen kann, um sich auf den Krieg in Ahn'Qiraj vorzubereiten. Die Allianz braucht Euch! Während wir uns unterhalten, haben die offiziellen Sammler bereits damit begonnen, kriegstaugliche Materialien aller Art zu sammeln. Doch ohne Eure Mithilfe sind all diese Mühen vergebens, <Name>! Wir brauchen Eure Unterstützung!\n\nAm besten unterhaltet Ihr Euch mit dem verantwortlichen Offizier, Feldmarschall Snowfall. Können wir auf Euch zählen, <Klasse>? Werdet Ihr uns bei den Kriegsvorbereitungen zur Seite stehen?", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;! Es ist schön zu sehen, dass Ihr uns in dieser dunklen Stunde zur Seite steht, &lt;Name&gt;! So viele Mitglieder der Allianz haben sich bereits freiwillig verpflichtet, uns bei den Vorbereitungen für den aufziehenden Krieg in Ahn'Qiraj zu unterstützen. Unsere Anstrengungen hier, werden der Garant für den Sieg über die Silithiden und Ihre dunklen Meister sein!\n\nNun, jetzt da Ihr hier seid, solltet Ihr Euch mit den örtlichen Sammlern unterhalten und sehen, welche Materialien Ihr am besten beschaffen könnt.", rewards = "Ihr bekommt:\n\n"},
[8798] = {title = "Euer eigener Yeti", objective = "Hey! Wisst Ihr was?! Ihr seid auch Ingenieur! So, da Ihr mir dabei geholfen habt meinen Freunden eine Lektion zu erteilen, werde ich Euch jetzt lehren, wie Ihr Euren eigenen mechanischen Yeti herstellt! Jetzt kann der Spaß für immer weitergehen und Ihr könnt wem immer Ihr wollt einen Schrecken einjagen! Vorausgesetzt Ihr treibt die benötigten Teile dafür auf.\n\nNa, was sagt Ihr, <Name>? Wollt Ihr, dass ich Euch in das Geheimnis der Herstellung eines mechanischen Yetis einweihe?", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRuhiger mechanischer Yeti"},
[8799] = {title = "Der Held des Tages", objective = "Bringt 1 Tiefsteinsalz und 5 Goldstücke zum Tannenzweigkonservierer. Ihr werdet 5 konservierte Tannenzweige erhalten.", description = "Eigentlich darf ich Euch das gar nicht sagen, aber da Ihr ja der Held des Tages seid, mach ich mal 'ne Ausnahme.\n\nUm diese Jahreszeit gibt es überall frische Tannenzweige, aber die Zweige bleiben nicht lange frisch. Wir haben eine Maschine, die Tannenzweige konserviert - die bleiben dann für immer frisch! Wir benutzen sie um die Festtage etwas aufzupeppen... und unsere Profite im Sommer zu steigern!\n\nIch lasse Euch den Konservierer benutzen, aber nur, wenn Ihr ein Meisterkoch seid. Ihr werdet etwas Tiefsteinsalz und etwa zwei, drei, ach, sagen wir einfach fünf Goldstücke brauchen. Damit solltet Ihr ein nettes Bündel konservieren können, das Ihr behalten könnt.", progress = "Der Tannenzweigkonservierer sieht auf den ersten Blick wie eine Art Destillierapparat aus, bei genauerer Betrachtung werden allerdings einige goblinartige Veränderungen offensichtlich. Eure Fähigkeiten in der Kochkunst erlauben es Euch allerdings zu verstehen, wie die Maschine funktioniert.\n\nEs sind schon frische Tannenzweige in der Maschine - Ihr müsst nur noch Tiefsteinsalz dazugeben und fünf Goldstücke einwerfen, um sie ans Laufen zu bringen.", completion = "Die Maschine fängt an zu rumpeln und Dampf auszuspeien, während sie mit der Arbeit beginnt. Schon kurz darauf ist sie fertig. Sie spuckt noch etwas Dampf aus und eine Klappe öffnet sich. In der Öffnung befindet sich ein Bündel konservierter Tannenzweige.", rewards = "Ihr bekommt:\n\nKonservierter Tannenzweig"},
[8800] = {title = "Schlachtrüstung des Cenarius", objective = "Sprecht mit Vargus auf Burg Cenarius in Silithus.", description = "Zwischen dem Erledigen der Euch im Krieg zugeteilten Aufträge, solltet Ihr ab und an mit Vargus dem Schmied sprechen. Zeigt ihm Eure erworbenen Abzeichen und er wird Euch im Gegenzug mit der Eurem Einsatz entsprechenden Ausrüstung versorgen.", progress = nil, completion = "Kaldon schickt Euch? Nun gut, lasst uns sehen, was ich für Euch tun kann.", rewards = nil},
[8801] = {title = "C'Thuns Vermächnis", objective = "Bringt Caelestrasz im Tempel von Ahn'Qiraj das Auge von C'Thun.", description = "Die Mauern von Ahn'Qiraj erbeben. Eine finstere Macht, älter noch als die Welt, wurde vernichtet.\n\nAls Ihr auf die Überreste der gigantischen Scheußlichkeit hinab blickt, scheint Euer Herz fast zu gefrieren. Selbst im Tod könnt Ihr das böse Erbe C'Thuns um Euch herum spüren.\n\nIhr habt das Unmögliche vollbracht.\n\nEines seiner Augen scheint Euch noch immer anzustarren. Ihr nehmt es auf und verstaut es in Eurem Gepäck.\n\nBringt den Drachen im nächsten Raum das Auge von C'Thun.", progress = "<Caelastrasz kniet vor Euch.>\n\nLord <Name>, Ihr habt uns aus seinem Griff befreit.", completion = "Lord &lt;Name&gt;, wir werden diesen Ort aus eigener Kraft verlassen, sobald wir sicher sind, dass alles Böse in diesen Mauern vernichtet wurde. Eure sagenumwobene Reise nähert sich ihrem Ende.", rewards = "Ihr bekommt:\n\n"},
[8802] = {title = "Der Retter von Kalimdor", objective = "Bringt Anachronos in den Höhlen der Zeit das Auge von C'Thun.", description = "Begebt Euch zu den Höhlen der Zeit, <Lord/Lady> <Name>. Anachronos erwartet Eure Rückkehr. Übergebt ihm das Auge von C'Thun. Sicherlich wird er es der Sammlung seines Meisters hinzufügen wollen.", progress = "Lord <Name>! Es ist vollbracht...", completion = "Der Meister hat dies für Euch zurückgelassen, großer Held. Aus dem zeitlosen Schatz: Eine Sammlung veschiedenster Artefakte, über tausende von Jahren zusammengetragen. Ihr habt die Wahl!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAmulett des gefallenen GottesUmhang des gefallenen GottesRing des gefallenen Gottes\n\nDer folgende Zauber wird auf euch gewirkt:\n\nBrut Nozdormus Fraktion +1000\n\nIhr bekommt außerdem:\n\n"},
[8803] = {title = "Ein Festtagsgeschenk", objective = "Auf dem Schildchen des Geschenks steht:\n\nFür <Name>,\n\nIch hoffe, dieses Geschenk wird Euch dabei helfen, einen Hauch von Gemütlichkeit und Festtagsfreude in ganz Azeroth zu verbreiten.\n\nAltvater Winter", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFesttagsgeschenk"},
[8804] = {title = "Wüstenüberlebenspaket", objective = "Bringt 4 Kugeln des Wassers, 4 mächtige Gegengifte und 4 geräucherte Wüstenknödel zu Calandrath in der Taverne von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz I, um diese Aufgabe abschließen zu können.", description = "Seitdem ständig neue Rekruten auf Burg Cenarius eintreffen, stehen wir vor dem Problem, sie in der Wüste am Leben zu erhalten. Der ständige Wasserentzug und die zahlreichen giftigen Kreaturen in dieser Gegend sind eine ernstzunehmende Gefahr für die unerfahren Soldaten. Sammelt alles, was notwendig ist, um ein Wüstenüberlebenspaket zusammenzustellen und bringt die erforderlichen Vorräte zu Calandrath auf Burg Cenarius.", progress = "Ihr habt etwas für mich?", completion = "Ausgezeichnet. Diese Pakete haben wir wirklich dringend benötigt, &lt;Name&gt;. Gute Arbeit.", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenLogistikauftrag"},
[8805] = {title = "Stiefel für die Wache", objective = "Bringt 3 Paar verschnörkelte Mithrilstiefel zu Vish Kozus, Captain der Wache von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz II, um diese Aufgabe abschließen zu können.", description = "Die berittene Einheit der Wache von Burg Cenarius hat kaum noch Vorräte an verschnörkelten Mithrilstiefeln. Beschafft Euch eine Ladung und bringt sie sofort zu Captain Vish Kozus auf Burg Cenarius.", progress = "Ihr habt etwas für mich?", completion = "Ausgezeichnet. Wir hatten diese Stiefel wirklich dringend benötigt, &lt;Name&gt;. Gute Arbeit.", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenLogistikauftrag"},
[8806] = {title = "Schleifsteine für die Wache", objective = "Bringt 10 verdichtete Schleifsteine, 10 robuste Schleifsteine und 10 schwere Schleifsteine zu Vish Kozus, Captain der Wache von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz III, um diese Aufgabe abschließen zu können.", description = "Die Wache von Burg Cenarius hat kaum noch Vorräte an Schleifsteinen. Beschafft Euch eine Ladung und bringt sie sofort zu Captain Vish Kozus auf Burg Cenarius.", progress = "Ihr habt etwas für mich?", completion = "Ausgezeichnet. Wir hatten diese Schleifsteine wirklich dringend benötigt, &lt;Name&gt;. Gute Arbeit.", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenLogistikauftrag"},
[8807] = {title = "Magische Materialien", objective = "Bringt 1 großen glänzenden Splitter, 1 großen strahlenden Splitter und 1 gewaltigen Smaragd zu Geologin Larksbane auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz V, um diese Aufgabe abschließen zu können.", description = "Geologin Larksbanes Studien haben sich für unsere Operationen in Silithus als sehr wertvoll erwiesen. Vor kurzem hat sie eine Ladung magischer Materialien angefordert, die sie für ihre weiteren Forschungen dringend benötigt.\n\nBeschafft die notwendigen Materialien und liefert sie direkt an sie aus, damit Geologin Larksbane ihre Forschungen ungestört fortsetzen kann.", progress = "Ihr habt etwas für mich, <Name>?", completion = "Ah, diese hier sind mir von großem Nutzen! Wisst Ihr &lt;Name&gt;, in dieser Wüste ist es sehr schwer an derartige Materialien zu kommen. Vielen Dank.", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenNachfolgender Logistikauftrag"},
[8808] = {title = "Uniformnachschub", objective = "Bringt 1 Einheit Mondstoff, 2 Runenstoffballen und 1 Einheit Eisenweberseide zu Windruferin Proudhorn auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz VIII, um diese Aufgabe abschließen zu können.", description = "Die letzte Ladung neuer Rekruten hat uns einen Engpass an Uniformen beschert. Beschafft uns eine Ladung Schneiderwaren, damit wir mehr Uniformen herstellen können. Bringt alles zur Windruferin Proudhorn.", progress = "Ihr habt etwas für mich, <Name>?", completion = "Ah, genau was wir jetzt brauchen. Wir wissen Eure Arbeit sehr zu schätzen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenLogistikauftrag"},
[8809] = {title = "Besondere Materialien", objective = "Bringt Vargus auf Burg Cenarius in Silithus 2 verzauberte Thoriumbarren und 2 Einheiten verzaubertes Leder. Ihr benötigt auch Logistikeinsatz IX, um diese Aufgabe abschließen zu können.", description = "Vargus, der Schmied von Burg Cenarius, hat verzauberte Materialien zur Herstellung von stärkeren Waffen angefordert. Beschafft die benötigten Materialien und bringt sie direkt zu Vargus, um den hohen Ausrüstungsstand unserer Truppen auf Burg Cenarius aufrechtzuerhalten.", progress = "Ihr habt etwas für mich, <Name>?", completion = "Ah, sehr gut. Dieses Material ist von hervorragender Qualität. Vielen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenLogistikauftrag"},
[8810] = {title = "Verbände für den Feldeinsatz", objective = "Bringt 30 schwere Runenstoffverbände, 30 schwere Seidenverbände und 30 schwere Magiestoffverbände zu Windruferin Proudhorn auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz X, um diese Aufgabe abschließen zu können.", description = "Nach den neusten Verlusten, die wir hinnehmen mussten, gehen unsere Vorräte an Verbänden für das Schlachtfeld gefährlich zur Neige. Besorgt Euch eine Ladung an Vorräten für Erste Hilfe und bringt sie zu Windruferin Proudhorn auf Burg Cenarius.", progress = "Ihr habt etwas für mich, <Name>?", completion = "Gerade rechtzeitig. Dieser Nachschub wird Leben retten, &lt;Name&gt;. Man schätzt Eure Arbeit. Hier ist Eure nächste Aufgabe.", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenNachfolgender Logistikauftrag"},
[8811] = {title = "Ein Belobigungsabzeichen", objective = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf in Darnassus ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf in Darnassus würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", description = nil, progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf in Darnassus ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf in Darnassus würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", completion = "Sehr gut! Eure glorreichen Taten wurden verzeichnet und Ihr habt Eure verdiente Anerkennung erhalten. Macht so weiter, &lt;Klasse&gt;!\n\nIch stehe Euch auch in Zukunft zur Verfügung, falls Ihr weitere Abzeichen abgeben möchtet.", rewards = nil},
[8812] = {title = "Ein Belobigungsabzeichen", objective = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf bei den Gnomereganverbannten ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf bei den Gnomereganverbannten würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", description = nil, progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf bei den Gnomereganverbannten ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf bei den Gnomereganverbannten würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", completion = "Sehr gut! Eure glorreichen Taten wurden verzeichnet und Ihr habt Eure verdiente Anerkennung erhalten. Macht so weiter, &lt;Klasse&gt;!\n\nIch stehe Euch auch in Zukunft zur Verfügung, falls Ihr weitere Abzeichen abgeben möchtet.", rewards = nil},
[8813] = {title = "Ein Belobigungsabzeichen", objective = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf in Ironforge ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf in Ironforge würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", description = nil, progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf in Ironforge ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf in Ironforge würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", completion = "Sehr gut! Eure glorreichen Taten wurden verzeichnet und Ihr habt Eure verdiente Anerkennung erhalten. Macht so weiter, &lt;Klasse&gt;!\n\nIch stehe Euch auch in Zukunft zur Verfügung, falls Ihr weitere Abzeichen abgeben möchtet.", rewards = nil},
