[8815] = {title = "Ein Belobigungsabzeichen", objective = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf in Orgrimmar ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf in Orgrimmar würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", description = nil, progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf in Orgrimmar ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf in Orgrimmar würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", completion = "Sehr gut! Eure glorreichen Taten wurden verzeichnet und Ihr habt Eure verdiente Anerkennung erhalten. Macht so weiter, &lt;Klasse&gt;!\n\nIch stehe Euch auch in Zukunft zur Verfügung, falls Ihr weitere Abzeichen abgeben möchtet.", rewards = nil},
[8816] = {title = "Ein Belobigungsabzeichen", objective = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf beim Darkspearstamm ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf beim Darkspearstamm würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", description = nil, progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf beim Darkspearstamm ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf beim Darkspearstamm würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", completion = "Sehr gut! Eure glorreichen Taten wurden verzeichnet und Ihr habt Eure verdiente Anerkennung erhalten. Macht so weiter, &lt;Klasse&gt;!\n\nIch stehe Euch auch in Zukunft zur Verfügung, falls Ihr weitere Abzeichen abgeben möchtet.", rewards = nil},
[8817] = {title = "Ein Belobigungsabzeichen", objective = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf in Undercity ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf in Undercity würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", description = nil, progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf in Undercity ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf in Undercity würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", completion = "Sehr gut! Eure glorreichen Taten wurden verzeichnet und Ihr habt Eure verdiente Anerkennung erhalten. Macht so weiter, &lt;Klasse&gt;!\n\nIch stehe Euch auch in Zukunft zur Verfügung, falls Ihr weitere Abzeichen abgeben möchtet.", rewards = nil},
[8818] = {title = "Ein Belobigungsabzeichen", objective = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf in Thunder Bluff ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf in Thunder Bluff würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", description = nil, progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf in Thunder Bluff ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf in Thunder Bluff würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", completion = "Sehr gut! Eure glorreichen Taten wurden verzeichnet und Ihr habt Eure verdiente Anerkennung erhalten. Macht so weiter, &lt;Klasse&gt;!\n\nIch stehe Euch auch in Zukunft zur Verfügung, falls Ihr weitere Abzeichen abgeben möchtet.", rewards = nil},
[8819] = {title = "Zehn Belobigungsabzeichen", objective = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf in Darnassus sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf in Darnassus nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", description = nil, progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf in Darnassus sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf in Darnassus nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Hervorragend! Ihr musstet so einiges auf Euch nehmen, um diese Abzeichen zu erhalten. Von jetzt an wird man Euch eine Menge Respekt entgegen bringen! Wie es sich für Eure großartige Pflichterfüllung und Hingabe gehört! Es sind Abenteurer von Eurem Kaliber, &lt;Name&gt;, die etwas in der Welt bewirken!\n\nLasst es mich wissen, wenn Ihr noch weitere Abzeichen zur Hand habt. Ich werde sie gerne entgegennehmen.", rewards = nil},
[8820] = {title = "Zehn Belobigungsabzeichen", objective = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf bei den Gnomereganverbannten sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf bei den Gnomereganverbannten nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", description = nil, progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf bei den Gnomereganverbannten sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf bei den Gnomereganverbannten nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Hervorragend! Ihr musstet so einiges auf Euch nehmen, um diese Abzeichen zu erhalten. Von jetzt an wird man Euch eine Menge Respekt entgegen bringen! Wie es sich für Eure großartige Pflichterfüllung und Hingabe gehört! Es sind Abenteurer von Eurem Kaliber, &lt;Name&gt;, die etwas in der Welt bewirken!\n\nLasst es mich wissen, wenn Ihr noch weitere Abzeichen zur Hand habt. Ich werde sie gerne entgegennehmen.", rewards = nil},
