[8845] = {title = "Zehn Belobigungsabzeichen", objective = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf beim Darkspearstamm sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf beim Darkspearstamm nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", description = nil, progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe Ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf beim Darkspearstamm sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf beim Darkspearstamm nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Hervorragend! Ihr musstet so einiges auf Euch nehmen, um diese Abzeichen zu erhalten. Von jetzt an wird man Euch eine Menge Respekt entgegen bringen! Wie es sich für Eure großartige Pflichterfüllung und Hingabe gehört! Es sind Abenteurer von Eurem Kaliber, &lt;Name&gt;, die etwas in der Welt bewirken!\n\nLasst es mich wissen, wenn Ihr noch weitere Abzeichen zur Hand habt. Ich werde sie gerne entgegennehmen.", rewards = nil},
[8846] = {title = "Fünf Abzeichen gegen Kriegsmaterial tauschen", objective = "Ah, sicherlich seid Ihr gekommen, um zusätzliches Kriegsmaterial für Euch anzufordern. Nun, ich kann das sehr gut nachvollziehen, im Krieg mangelt es ständig an allem… Ihr braucht Euch bloß hier umzusehen, dann wißt Ihr was ich meine!\n\nIch bin bevollmächtigt zusätzliches Kriegsmaterial an Euch auszugeben, allerdings müsst Ihr mir dafür eine entsprechende Anzahl Belobigungsabzeichen überlassen. Durch diesen Tausch wird zwar Euer Ruf nicht weiter verbessert werden, doch möglicherweise findet Ihr etwas brauchbares für die Schlacht und rettet so vielleicht Euer Leben.", description = nil, progress = "Ah, sicherlich seid Ihr gekommen, um zusätzliches Kriegsmaterial für Euch anzufordern. Nun, ich kann das sehr gut nachvollziehen, im Krieg mangelt es ständig an allem… Ihr braucht Euch bloß hier umzusehen, dann wißt Ihr was ich meine!\n\nIch bin bevollmächtigt zusätzliches Kriegsmaterial an Euch auszugeben, allerdings müsst Ihr mir dafür eine entsprechende Anzahl Belobigungsabzeichen überlassen. Durch diesen Tausch wird zwar Euer Ruf nicht weiter verbessert werden, doch möglicherweise findet Ihr etwas brauchbares für die Schlacht und rettet so vielleicht Euer Leben.", completion = "Nun, dann sind wir uns ja einig. Hier sind die von Euch angeforderten Kriegsmaterialien, &lt;Klasse&gt;. Wenn Ihr wieder einmal etwas brauchen solltet, kommt direkt zu mir. Ich werde Eure Anforderung dann schnellstmöglich bearbeiten.\n\nLeistet weiter so gute Arbeit, &lt;Name&gt;! Wir können jeden Mann und jede Frau gebrauchen, um diesen Krieg zu gewinnen. Wenn alle ihre Pflicht so gewissenhaft erfüllen, sollten wir aus dieser Schlacht als Sieger hervorgehen.", rewards = "Ihr bekommt:\n\nKriegsmaterial für Ahn'Qiraj"},
[8847] = {title = "Zehn Abzeichen gegen Kriegsmaterial tauschen", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKriegsmaterial für Ahn'Qiraj"},
