[8856] = {title = "Wüstenüberlebenspaket", objective = "Bringt 4 Kugeln des Wassers, 4 mächtige Gegengifte und 4 gebackene Lachse zu Calandrath in der Taverne von Burg Cenarius in Silithus.", description = "Seitdem ständig neue Rekruten auf Burg Cenarius eintreffen, stehen wir vor dem Problem, sie in der Wüste am Leben zu erhalten. Der ständige Wasserentzug und die zahlreichen giftigen Kreaturen in dieser Gegend sind eine ernstzunehmende Gefahr für die unerfahren Soldaten. Sammelt alles, was notwendig ist, um ein Wüstenüberlebenspaket zusammenzustellen und bringt die erforderlichen Vorräte zu Calandrath auf Burg Cenarius.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenNachfolgender Logistikauftrag"},
[8857] = {title = "Geheimnisse des Kolosses - Ashi", objective = "Bringt das Fragment vom Koloss des Ashischwarms zu Oglethorpe Obnoticus in Booty Bay.", description = "Ich suche nach schlachterprobten Abenteurern, die für mich eine Fragmentprobe vom Koloss des Ashischwarms zu Oglethorpe in Booty Bay bringen. Nein, nein, Ihr braucht Euch nicht einmal in die Nähe dieses Giganten zu wagen. Nehmt einfach eine von meinen Proben und beeilt Euch. Verrottet nutzt sie Onglethorpe nicht viel!", progress = "Ja? Was habt Ihr für mich?", completion = "Oh, was für tolle Hühnchen ich aus diesem wundervollen Fragment basteln werde! Vielen Dank, mein Junge!", rewards = "Ihr bekommt:\n\nRiesige Beutetasche"},
[8858] = {title = "Geheimnisse des Kolosses - Regal", objective = "Bringt das Fragment vom Koloss des Regalschwarms zu Aufseher Oilfist in die sengenden Schlucht.", description = "Ich würde nichts lieber tun, als Oilfist dieses verdammte Fragment in sein fettes Maul zu stopfen. Stattdessen stecke ich hier fest und sammle Proben von dieser zu groß geratenen Kakerlake! In Anbetracht ihrer Größe, werde ich hier wohl noch eine Weile beschäftigt sein.\n\nNehmt diese Probe und bringt sie für mich zu Oilfist... und beeilt Euch, <Klasse>. Er zahlt auch sehr gut!\n\nAlso, ab zur Thoriumspitze in die sengende Schlucht.", progress = "Hmmm...", completion = "Hervorragend! Aus diesem Chitinfragment können wir sicherlich einige sehr mächtige Rüstungen herstellen. Hier ist Eure Belohnung!", rewards = "Ihr bekommt:\n\nRiesige Beutetasche"},
[8859] = {title = "Geheimnisse des Kolosses - Zora", objective = "Bringt das Fragment vom Koloss des Zoraschwarms zu Lord Maxwell Tyrosus an der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Meine Leute hätte es beinahe erwischt, als sie diese Probe beschafft haben. Ihr müsst Euch unbedingt beeilen! Lord Maxwell Tyrosus wartet bereits voller Ungeduld auf eine frische Fragmentprobe. Er geht davon aus, dass uns die Geheimnisse dieses Kolosses im Kampf gegen die Geißel sehr von Nutzen sein werden!\n\nWieso seid Ihr noch hier!? Zur Hoffnung des Lichts! Ja, ja, man wird Euch für diese Aufgabe großzügig entlohnen...", progress = "Ihr seht ein wenig schwerfällig aus, mein Freund.", completion = "Exzellent und genau zur rechten Zeit! Gut gemacht, Junge.", rewards = "Ihr bekommt:\n\nRiesige Beutetasche"},
[8860] = {title = "Neujahrsfeier!", objective = "Bringt die Vorräte von Kokelwälder zu Gastwirtin Allison in Stormwind.", description = "In Stormwind wird das neue Jahr ganz groß gefeiert! Den ganzen Tag lang gibt es kostenlos was Hochprozentiges zu trinken und nachts eine fantastische Feuerwerksschau! Das wird sicherlich ein Riesenspaß… allerdings findet auch in Booty Bay eine Neujahrsfeier statt. Ich wette, dort ist noch viel mehr los!\n\nEgal! Jedenfalls braucht Gastwirtin Allison eine Ladung Kokelwälder Festtagsspeisen, um alle Partylöwen satt in das neue Jahr zu bringen. Würdet Ihr mir den Gefallen tun und die Vorräte für mich abliefern?\n\nDanke, <Name>! Ihr findet Gastwirtin Allison in der Taverne zur güldenen Rose, drüben im Handelsdistrikt von Stormwind.", progress = "Hallo! Seid Ihr wegen der Party hier? Oder wollt Ihr nur ein wenig Eure müden Füße ausruhen?", completion = "Oh, meine Vorräte von Kokelwälder! Großartig! Die brauche ich dringend, um all die hungrigen Mäuler während der Feierlichkeiten zu stopfen!\n\nVielen Dank für Eure Hilfe, &lt;Name&gt;. Bitte, nehmt dies als Belohnung an und vergesst nicht mit den anderen draußen zu trinken und zu tanzen!", rewards = "Ihr bekommt:\n\n"},
[8861] = {title = "Neujahrsfeier!", objective = "Bringt die Vorräte von Kokelwälder zu Gastwirtin Pala in Thunder Bluff.", description = "In Thunder Bluff wird das neue Jahr ganz groß gefeiert! Den ganzen Tag lang gibt es kostenlos was Hochprozentiges zu trinken und nachts eine fantastische Feuerwerksschau! Das wird sicherlich ein Riesenspaß… allerdings findet auch in Booty Bay eine Neujahrsfeier statt. Ich wette, dort ist noch viel mehr los!\n\nEgal! Jedenfalls braucht Gastwirtin Pala eine Ladung Kokelwälder Festtagsspeisen, um alle Partylöwen satt in das neue Jahr zu bringen. Würdet Ihr mir den Gefallen tun und die Vorräte für mich abliefern?\n\nDanke, <Name>! Ihr findet Gastwirtin Pala in der Taverne nahe der Brücke zur Anhöhe der Jäger.", progress = "Guten Tag, <Klasse>! Seid Ihr wegen den Feierlichkeiten nach Thunder Bluff gekommen? Oder wollt Ihr nur ein wenig Eure von der Jagd müden Hufe ausruhen?", completion = "Oh, sehr gut! Mit diesen Vorräten sollte ich alle Feiernden auf dem Neujahrsfest bewirten können!\n\nIch danke Euch, &lt;Name&gt;. Ich stehe in Eurer Schuld. Bitte, nehmt diese Münzen als Dankeschön... und befolgt meinen Rat - nehmt einen herzhaften Schluck aus dem Fass draußen und schließt Euch den anderen beim Feiern des neuen Jahres an!", rewards = "Ihr bekommt:\n\n"},
[8862] = {title = "Elunes Kerze", objective = "Elunes Kerze ist für die Anhänger des Mondfests ein Artefakt der großen Verehrung. Die Kerze beinhaltet wahres Mondlicht, bereit zur Freigabe!\n\nDieses Licht ist für die meisten Kreaturen harmlos, aber Ihr werdet sehen, dass Omen und seine Diener davon Verbrennungen erleiden und geblendet werden.", description = nil, progress = "Elunes Kerze ist für die Anhänger des Mondfests ein Artefakt der großen Verehrung. Die Kerze beinhaltet wahres Mondlicht, bereit zur Freigabe!\n\nDieses Licht ist für die meisten Kreaturen harmlos, aber Ihr werdet sehen, dass Omen und seine Diener davon Verbrennungen erleiden und geblendet werden.", completion = "Nun gut - ich akzeptiere diese Münzen der Urahnen. Bitte nehmt Elunes Kerze mit meinen besten Wünschen. Erfreut Euch auch an diesem zusätzlichen Feuerwerk.\n\nMöge Euer Mondfest freudig und voller Heiterkeit sein, &lt;Name&gt;.\n\nMöchtet Ihr Euch Omen und seinen Dienern wirklich stellen, so werdet Ihr Elunes Kerze recht nützlich finden...", rewards = "Ihr bekommt:\n\nElunes KerzeFeuerwerkspaket des Mondfests"},
[8863] = {title = "Festtagsklöße", objective = "Wenn Ihr hungrig seid, dann solltet ihr zu der richtigen Adresse kommen!\n\nKlöße sind das traditionelle Gericht des Mondfests; man serviert es bereits seit den Zeiten des ersten Mondfests und ich bin stolz, dass ich diese Köstlichkeit während der diesjährigen Feierlichkeiten anbieten kann. Im Austausch gegen eine einzige Münze der Urahnen werde ich Euch von einer Probe dieses unvergleichlich genüsslichen Gerichts kosten lassen!", description = nil, progress = "Wenn Ihr hungrig seid, dann solltet ihr zu der richtigen Adresse kommen!\n\nKlöße sind das traditionelle Gericht des Mondfests; man serviert es bereits seit den Zeiten des ersten Mondfests und ich bin stolz, dass ich diese Köstlichkeit während der diesjährigen Feierlichkeiten anbieten kann. Im Austausch gegen eine einzige Münze der Urahnen werde ich Euch von einer Probe dieses unvergleichlich genüsslichen Gerichts kosten lassen!", completion = "Ausgezeichnet - bitte genießt diese Klöße mit meinen besten Wünschen. Auch wenn sie nur ein kleines Zeichen der Anerkennung für Eure Ehre sind, die Ihr Euch mittels Eurer Taten verdient habt, so denke ich doch, dass Ihr sie alle gleichermaßen genießen werdet.\n\nSolltet Ihr noch mehr Münzen der Urahnen besitzen, so bin ich gewillt Euch ein reiches Angebot an Gegenständen im Austausch dafür anzubieten.", rewards = "Ihr bekommt:\n\nFesttagsklöße"},
[8864] = {title = "Festtagskleider des Mondfests", objective = "Ich habe eine Auswahl an Kleidern, die Euch interessieren könnte. Derartige Gewänder wurden in vergangenen Zeiten während des Mondfests getragen. Die Auswahl, die ich heute zu bieten habe, ist vielleicht die beste, die ich jemals gesehen habe. Jedes Stück ist aus den feinsten und geschmeidigsten Materialien handgefertigt worden.\n\nIch lasse Euch im Tausch gegen ein paar Münzen der Urahnen unter den drei Kleidungsstilen einen für Euch selbst auswählen. Ist das annehmbar für Euch?", description = nil, progress = "Ich habe eine Auswahl an Kleidern, die Euch interessieren könnte. Derartige Gewänder wurden in vergangenen Zeiten während des Mondfests getragen. Die Auswahl, die ich heute zu bieten habe, ist vielleicht die beste, die ich jemals gesehen habe. Jedes Stück ist aus den feinsten und geschmeidigsten Materialien handgefertigt worden.\n\nIch lasse Euch im Tausch gegen ein paar Münzen der Urahnen unter den drei Kleidungsstilen einen für Euch selbst auswählen. Ist das annehmbar für Euch?", completion = "Nun gut - ich akzeptiere diese Münzen der Urahnen. Bitte nehmt dieses Kleid mit meinen besten Wünschen. Erfreut Euch auch an diesem zusätzlichen Feuerwerk.\n\nDa Ihr unsere Urahnen geehrt habt, ehrt Ihr mich mit Eurer bloßen Anwesenheit. Ich danke Euch, möge Euer Mondfest freudig sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGrünes FesttagskleidRosa FesttagskleidLila Festtagskleid\n\nIhr bekommt außerdem:\n\nFeuerwerkspaket des Mondfests"},
[8865] = {title = "Festliche Hosenanzüge des Mondfests", objective = "Ich freue mich Euch mitteilen zu können, dass ich über eine feine Auswahl an festlichen Hosenanzügen verfüge, die ich Euch anbieten kann... aber nur im Tausch gegen Münzen der Urahnen. Wenn Ihr Wert auf Eure Erscheinung legt, dann ist dies genau das Richtige für Euch! Ich kann Euch versichern, dass Ihr keine vergleichbaren Hosenanzüge finden werdet.\n\nIch lasse Euch im Tausch gegen ein paar Münzen der Urahnen unter den drei Kleidungsstilen einen für Euch selbst auswählen. Ist das annehmbar für Euch?", description = nil, progress = "Ich freue mich Euch mitteilen zu können, dass ich über eine feine Auswahl an festlichen Hosenanzügen verfüge, die ich Euch anbieten kann... aber nur im Tausch gegen Münzen der Urahnen. Wenn Ihr Wert auf Eure Erscheinung legt, dann ist dies genau das Richtige für Euch! Ich kann Euch versichern, dass Ihr keine vergleichbaren Hosenanzüge finden werdet.\n\nIch lasse Euch im Tausch gegen ein paar Münzen der Urahnen unter den drei Kleidungsstilen einen für Euch selbst auswählen. Ist das annehmbar für Euch?", completion = "Nun gut - ich akzeptiere diese Münzen der Urahnen. Bitte nehmt diesen Hosenanzug mit meinen besten Wünschen. Erfreut Euch auch an diesem zusätzlichen Feuerwerk.\n\nSolltet Ihr noch mehr Münzen der Urahnen zum Tauschen haben, dann sprecht noch einmal mit mir. Ich habe während des gesamten Mondfests zahlreiche Gegenstände in meinem Angebot.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFestlicher schwarzer HosenanzugFestlicher blauer HosenanzugFestlicher mintgrüner Hosenanzug\n\nIhr bekommt außerdem:\n\nFeuerwerkspaket des Mondfests"},
[8866] = {title = "Urahne Bronzebeard", objective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, <Name>. Nehmt dies als Zeichen meiner Dankbarkeit.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der Urahnen"},
[8867] = {title = "Mondfeuerwerk", objective = "Zündet 8 Raketen und 2 Raketenbündel und kehrt dann zu einer Botin des Mondfests in irgendeiner Hauptstadt zurück.", description = "Die Druiden von Moonglade feiern jedes Jahr den großen Triumph unserer Stadt über ein uraltes Übel.\n\nWir ehren die Weisheit unserer Urahnen, nehmen an herrlichen Festgelagen teil und... schießen natürlich Feuerwerk ab!\n\nFür eine kleine Spende könnt Ihr bei unserem Verkäufer farbenfrohe Raketen erwerben. Versucht doch mal einen der hier herumstehenden Zünder, <Name>.", progress = "Konntet Ihr die Zünder finden, <Name>?", completion = "Gut gemacht, &lt;Name&gt;.\n\nDa Ihr jetzt in der richtigen Stimmung seid, nehmt doch diese Einladung zu dem Fest in Moonglade an.\n\nEs sind recht unterhaltsame Feierlichkeiten, falls Ihr etwas Zeit haben solltet. Wir teilen dort miteinander gutes Essen, Getränke, Geschichten und natürlich... noch mehr Feuerwerk!\n\nÖffnet die Einladung, während Ihr innerhalb des Mondlichtkreises steht und Ihr werdet nach Moonglade transportiert.", rewards = "Ihr bekommt:\n\nMondfesteinladung"},
[8868] = {title = "Elunes Segen", objective = "Beschwört Omen, besiegt ihn und erlangt Elunes Segen. Kehrt anschließend zu Valadar Starsong in Nighthaven zurück.", description = "Das Biest Omen war einstmals ein bekannter Held. Als ein Wolf von großer Stärke und Geschicklichkeit, kämpfte er im Krieg der Urtume Seite an Seite mit den Helden dieser Zeit, bis er den dämonischen Mächten verfiel. Sein Hass richtete sich gegen seine einstigen Verbündeten und auf seinem Rachefeldzug durch Azeroth verbreitete er Tod und Verderben.\n\nLetztlich besiegte man ihn hier, in Moonglade, wo er bis heute auf dem Grund des Elune'ara Sees ruht. Doch jedes Jahr, während des Neujahrfests, erwacht er zu neuem Leben...\n\nSchart Eure Freunde um Euch! Zieht los, beschwört und besiegt das Biest Omen. Erlangt Elunes Segen!", progress = "Tief, tief im Elune'ara See lauert Omen, <Name>...", completion = "Das habt Ihr sehr gut gemacht, &lt;Name&gt;. Der Sieg über Omen hat seinen Geist wieder in die Tiefen des Elune'ara Sees verbannt. Obwohl das Biest durch Elune selbst gesegnet wurde und es dadurch unsterblich ist, wird sein Zorn für ein weiteres Jahr besänftigt sein.\n\nEuer Sieg ist eine Feier, &lt;Name&gt; – eine Feier zu Ehren der Macht Omens, Eurer Stärke und der Ausdauer Eurer Verbündeten und nicht zuletzt des Friedens, den Ihr diesem tragischen Held der Vergangenheit geschenkt habt.", rewards = "Ihr bekommt:\n\nElunes LaterneFeuerwerkspaket des MondfestsRobuster Stein"},
[8869] = {title = "Süße Beschaulichkeit", objective = "Begebt Euch nach Stratholme und tötet den purpurroten Hammerschmied. Nehmt die Schürze des purpurroten Hammerschmiedes und kehrt zu Lilith zurück.", description = "In den Grenzen der Scharlachroten Bastion liegt die süße Beschaulichkeit. Der purpurrote Hammerschmied bewacht das Rezept mit seinem Leben. Besiegt ihn und bringt mir seine Schürze. Dafür werde ich Euch zu einem Hammerschmied ausbilden.\n\nIhr müsst eines wissen: Wenn Ihr Euch für den Weg des Hammerschmieds entschieden habt, sind die Wege des Schwertschmieds und des Axtschmieds nicht mehr verfügbar.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHammerschmiedemeister\n\nIhr bekommt:\n\nPläne: Verzauberter Kampfhammer"},
[8870] = {title = "Das Mondfest", objective = "Sprecht mit der Botin des Mondfests im Mystikerviertel von Ironforge. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", description = "Es ist mal wieder soweit, <Name>! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", rewards = nil},
[8871] = {title = "Das Mondfest", objective = "Sprecht mit der Botin des Mondfests im Parkviertel von Stormwind. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", description = "Es ist mal wieder soweit, <Name>! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", rewards = nil},
[8872] = {title = "Das Mondfest", objective = "Sprecht mit der Botin des Mondfests in der Enklave des Cenarius in Darnassus. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", description = "Es ist mal wieder soweit, <Name>! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", rewards = nil},
[8873] = {title = "Das Mondfest", objective = "Sprecht mit der Botin des Mondfests im Tal der Weisheit in Orgrimmar. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", description = "Es ist mal wieder soweit, <Name>! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", rewards = nil},
[8874] = {title = "Das Mondfest", objective = "Sprecht mit der Botin des Mondfests am Eingang zur Undercity. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", description = "Es ist mal wieder soweit, <Name>! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", rewards = nil},
[8875] = {title = "Das Mondfest", objective = "Sprecht mit der Botin des Mondfests auf der Anhöhe der Ältesten in Thunder Bluff. Die Boten in den anderen Hauptstädten können Euch ebenfalls weiterhelfen.", description = "Es ist mal wieder soweit, <Name>! Der Zirkel des Cenarius lädt alle Bewohner Azeroths dazu ein, gemeinsam mit uns, das Mondfest zu feiern. Der Ort, an dem Ihr die örtliche Botin des Mondfests finden könnt, wird durch einen Kreis aus heiligem Mondlicht markiert. Sie vermag Euch ausführlicher über dieses Fest zu berichten.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Seid Ihr gekommen, um an den Festlichkeiten teilzunehmen?", rewards = nil},
[8876] = {title = "Kleine Raketen", objective = "Ich hüte das Geheimnis zur Herstellung der Mondfestraketen und freue mich, mein Wissen mit den Würdigen zu teilen.\n\nIch kann Euch im Tausch gegen Münzen der Urahnen das Rezept zur Herstellung einer kleinen Rakete anbieten...", description = nil, progress = "Ich hüte das Geheimnis zur Herstellung der Mondfestraketen und freue mich, mein Wissen mit den Würdigen zu teilen.\n\nIch kann Euch im Tausch gegen Münzen der Urahnen das Rezept zur Herstellung einer kleinen Rakete anbieten...", completion = "Ah, sehr schön. Hier ist Euer Rezept, &lt;Name&gt;, möge Elune Euch segnen.", rewards = "Ihr bekommt:\n\nRezepte für kleine RaketenFeuerwerkspaket des Mondfests"},
[8877] = {title = "Zünder für Feuerwerk", objective = "Auch wenn Raketen wunderbar zum Feiern sind, so müssen sie doch von einem richtigen Zünder abgefeuert werden, damit man ihre wahre Herrlichkeit sehen kann...\n\nBringt mir Münzen der Urahnen und ich lehre Euch die Herstellung von Feuerwerkszündern, wie man sie in Moonglade sieht.", description = nil, progress = "Auch wenn Raketen wunderbar zum Feiern sind, so müssen sie doch von einem richtigen Zünder abgefeuert werden, damit man ihre wahre Herrlichkeit sehen kann...\n\nBringt mir Münzen der Urahnen und ich lehre Euch die Herstellung von Feuerwerkszündern, wie man sie in Moonglade sieht.", completion = "Da seid Ihr ja, &lt;Name&gt;. Hier ist der Bauplan zur Herstellung von Feuerwerkszündern. Platziert die Zünder dort, wo Ihr feiern möchtet, und ladet Eure Freunde dazu ein!", rewards = "Ihr bekommt:\n\nBauplan: Zünder für FeuerwerkFeuerwerkspaket des Mondfests"},
[8878] = {title = "Festtagsrezepte", objective = "Die Kleider und Hosenanzüge, die Ihr hier sehen könnt, sind traditionelle Gewänder vergangener Zeiten. Sie werden zu Ehren alter Gebräuche und geliebter Vorfahren getragen.\n\nBringt Ihr mir Münzen der Urahnen, <Name>, werde ich Euch das Muster zur Herstellung traditioneller roter Kleider oder Hosenanzüge geben.", description = nil, progress = "Die Kleider und Hosenanzüge, die Ihr hier sehen könnt, sind traditionelle Gewänder vergangener Zeiten. Sie werden zu Ehren alter Gebräuche und geliebter Vorfahren getragen.\n\nBringt Ihr mir Münzen der Urahnen, <Name>, werde ich Euch das Muster zur Herstellung traditioneller roter Kleider oder Hosenanzüge geben.", completion = "Hier sind die Muster, &lt;Name&gt;. Ich bin mir sicher, dass Ihr die Ergebnisse dieses Herstellungsgeheimnisses wunderschön finden werdet.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMuster: FesttagskleidMuster: Festtagsanzug\n\nIhr bekommt außerdem:\n\nFeuerwerkspaket des Mondfests"},
[8879] = {title = "Große Raketen", objective = "Große Festtagsraketen erhellen den Himmel sternengleich - nur die Raketenbündel können mit ihrer Schönheit rivalisieren!\n\nBringt mir Münzen der Urahnen und ich lehre Euch ihre Herstellung.", description = nil, progress = "Große Festtagsraketen erhellen den Himmel sternengleich - nur die Raketenbündel können mit ihrer Schönheit rivalisieren!\n\nBringt mir Münzen der Urahnen und ich lehre Euch ihre Herstellung.", completion = "Nun gut - ich akzeptiere diese Münzen der Urahnen. Hier ist Euer Rezept, &lt;Name&gt;. Verwendet sie, um Elunes Herrlichkeit zu verbreiten!", rewards = "Ihr bekommt:\n\nRezepte für große RaketenFeuerwerkspaket des Mondfests"},
[8880] = {title = "Raketenbündel", objective = "Raketenbündel bestehen aus einer Anzahl unterschiedlicher Raketen. Ihre Schönheit ist überwältigend! Bringt mir Münzen der Urahnen und ich werde das Wissen ihrer Herstellung mit Euch teilen…", description = nil, progress = "Raketenbündel bestehen aus einer Anzahl unterschiedlicher Raketen. Ihre Schönheit ist überwältigend! Bringt mir Münzen der Urahnen und ich werde das Wissen ihrer Herstellung mit Euch teilen…", completion = "Bitte sehr, &lt;Name&gt;. Nehmt diesen Bauplan und erlernt seine Geheimnisse. Ich wünsche Euch alles Gute und freue mich schon auf Eure Kreationen!", rewards = "Ihr bekommt:\n\nRezepte für RaketenbündelFeuerwerkspaket des Mondfests"},
[8881] = {title = "Große Raketenbündel", objective = "Die Herstellung großer Raketenbündel erfordert viel Erfahrung und noch mehr Ressourcen, doch ihre Schönheit ist die Mühen wert! Bringt mir Münzen der Urahnen und ich werde das Wissen ihrer Herstellung mit Euch teilen.", description = nil, progress = "Die Herstellung großer Raketenbündel erfordert viel Erfahrung und noch mehr Ressourcen, doch ihre Schönheit ist die Mühen wert! Bringt mir Münzen der Urahnen und ich werde das Wissen ihrer Herstellung mit Euch teilen.", completion = "Vielen Dank, &lt;Name&gt;. Hier ist der Bauplan zur Herstellung von großen Raketenbündeln. Möge Euer Feuerwerk allen Zuschauern viel Freude und Glück bereiten.", rewards = "Ihr bekommt:\n\nRezepte für große RaketenbündelFeuerwerkspaket des Mondfests"},
[8882] = {title = "Zünder für Raketenbündel", objective = "Die schönsten Feuerwerke erfordern ganze Bündel an Feuerwerksraketen! Um diese abzufeuern, benötigt man Zünder für Raketenbündel! Wäre es dann nicht logisch für Euch, wenn Ihr das Geheimnis der Herstellung solcher Zünder von mir erlernen würdet? Bringt mir Münzen der Urahnen und ich werde mein Wissen mit Euch teilen…", description = nil, progress = "Die schönsten Feuerwerke erfordern ganze Bündel an Feuerwerksraketen! Um diese abzufeuern, benötigt man Zünder für Raketenbündel! Wäre es dann nicht logisch für Euch, wenn Ihr das Geheimnis der Herstellung solcher Zünder von mir erlernen würdet? Bringt mir Münzen der Urahnen und ich werde mein Wissen mit Euch teilen…", completion = "Hier ist Euer Bauplan. Studiert ihn ausführlich und lernt…\n\nViel Glück, &lt;Name&gt;. Mögen Eure Feuerwerke den Nachthimmel noch heller erleuchten, als die Feierlichkeiten des Mondfests selbst!", rewards = "Ihr bekommt:\n\nBauplan: Zünder für RaketenbündelFeuerwerkspaket des Mondfests"},
[8883] = {title = "Valadar Starsong", objective = "Verwendet die Mondfesteinladung im Mondlicht und reist somit nach Moonglade. Sprecht nach Eurer Ankunft in Nighthaven mit Valadar Starsong.", description = "Jetzt, da Ihr in Besitz der Mondfesteinladung seid, könntet Ihr doch einmal nach Moonglade reisen - Ihr werdet dort viele Feiernde vorfinden! In Nighthaven erwarten Valadar Starsong und seine Schwester Fariel bereits diejenigen, die die Feierlichkeiten kaum erwarten können.\n\nReist nach Moonglade mit Hilfe des Mondlichts und sprecht mit Valadar Starsong; schaut Euch um und erfahrt welche Preise Ihr während des Fests gewinnen könnt!", progress = nil, completion = "&lt;Name&gt;, willkommen in Nighthaven, Gastgeber des Mondfests! Wenngleich unser Dorf normalerweise etwas entlegen und abgesondert von den Bewohner Azeroths liegt, so öffnen wir während der Festtage doch allen unsere Arme und Herzen.\n\nAmüsiert Euch gut, solange Ihr hier seid, &lt;Name&gt;, und sprecht wieder mit mir oder meiner Schwester, wenn Ihr bereit seid.", rewards = "Ihr bekommt:\n\n"},
[8884] = {title = "Fischköpfe, Fischköpfe...", objective = "Sammelt 8 Köpfe von Grimmschuppenmurlocs und bringt sie zu Hathvelion Sonnenblick im Immersangwald auf der Klippe, die die Stille Küste überblickt.", description = "Seid gegrüßt, <Klasse>. Was, frage ich Euch, könnt Ihr erkennen, wenn Ihr in Richtung Küste seht? Richtig, unser Strand... unsere Stille Küste wurde vom Übel, den Murlocs, befallen.\n\nDieser Makel darf nicht bestehen bleiben!\n\nIch habe eine Aufgabe für Euch. Solltet Ihr bereit dazu sein, so würde ich ihre Köpfe haben wollen! Mal sehen, ob wir ihre Zahl derart verringern können, dass sie nicht mehr anders können, als in die dunklen Tiefen zurückzukehren, aus denen sie gekommen sind!", progress = "Wir Waldläufer von der Zuflucht der Weltenwanderer haben uns der Wiedergutmachung aller Schäden gewidmet, die unser schönes Land so schrecklich verheert haben. Egal, wie lange es auch dauern mag.\n\nIch kann mich doch darauf verlassen, dass Ihr mit den Murlocköpfen zurückgekehrt seid, die ich von Euch verlangt habe?", completion = "Gute Arbeit, &lt;Klasse&gt;. Dem Gestank nach zu urteilen, seid Ihr mit der von mir geforderten Beute zurückgekehrt, vielleicht sogar mit mehr. Ich bin mir sicher, dass wir dafür Verwendung haben werden, sei es in einem Eintopf oder etwas Ähnlichem.\n\nLeider scheinen Eure Bemühungen den Zweck nicht erfüllt zu haben; die Murlocs ziehen sich noch immer nicht zurück. Wir müssen noch tatkräftiger handeln!", rewards = "Ihr bekommt:\n\n"},
[8885] = {title = "Mmmrrrgggllls Ring", objective = "Erlangt Mmmrrrgggllls Ring von dem Häuptling der Grimmschuppen und kehrt damit anschließend zu Hathvelion Sonnenblick im Immersangwald auf der Klippe, die die Stille Küste überblickt, zurück.", description = "Die Grimmschuppenmurlocs haben sich durch Eure Taten nicht vertreiben lassen. Ich glaube aber zu wissen, was sie endlich in die Flucht schlagen wird, und wie ich mich gleichzeitig persönlich an ihnen rächen kann.\n\nSie haben einen Murlochäuptling, der sich selbst Mmmrrrggglll nennt. Er wandert entlang des Goldenen Strandes südlich der Flussmündung umher. Dies Biest hat einst einen meiner Kameraden getötet und trägt seitdem seinen Ring als offenes Zeichen der Verachtung und des Spotts.\n\nVernichtet Mmmrrrggglll und bringt mir den Ring meines Freundes wieder. Das sollte diese Monster ein für alle Mal einschüchtern!", progress = "Ihr verhelft mir zu Erfolg und Rache, <Klasse>. Habt Ihr den Ring?", completion = "Endlich! Die Grimmschuppen sind zwar noch immer nicht gewichen, wie erhofft, aber es war ein herrliches Schauspiel, als sie nach dem Tod ihres Anführers in Panik und Verwirrung umhergeirrt sind. Ihr habt meinen Dank und den der Sin'dorei von Silbermond!\n\nBitte, nehmt eine dieser Belohnungen für Eure Mühen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGegenstand #23395Gegenstand #23396Gegenstand #23397Gegenstand #23398Gegenstand #133694\n\nIhr bekommt außerdem:\n\n"},
[8886] = {title = "Piraten der Grimmschuppen!", objective = "Erlangt 6 Stücke von Kapitänin Kelisendras Fracht wieder und bringt sie zu Kapitänin Kelisendra beim befestigten Lager direkt östlich des Ankerplatzes der Sonnensegel im Immersangwald zurück.", description = "Wie gut, dass Ihr hier seid, <Klasse>! Diese schleimigen Grimmschuppenmurlocs haben meine Fracht gestohlen! Als wenn es nicht schon schlimm genug wäre, dass die Getriebenen mir meine letzten magischen Güter geraubt haben - und jetzt das! Was ist nur aus diesem Land geworden?\n\nKönnt Ihr mir meine Fracht wiederbeschaffen? Ich erwarte zwar nicht, dass Ihr alles zurückerlangt, bin aber für jedes Stück dankbar. Es waren die Grimmschuppenmurlocs in den Hütten im Westen, südlich des Ankerplatzes am Goldenen Strand. Ich bin mir ganz sicher!", progress = "Ich bin dankbar für die Unterstützung von jemandem wie Euch, <Name>. Es stimmt mich fast schon wieder fröhlich. Allerdings erinnert es mich auch daran, was diese Monster meinem Schiff angetan haben und was mit Quel'Thalas geschieht.\n\nHabt Ihr es geschafft, Teile meiner Fracht wiederzuerlangen?", completion = "Ihr habt es geschafft! Ihr habt mich vor dem Ruin bewahrt und die scheußlichen Kreaturen meine Vergeltung spüren lassen!\n\nWenn ich es jetzt noch schaffe, dass mir diese hübschen Waldläufer mit meiner Fracht helfen, dann komme ich endlich weg von hier! Ich muss noch einmal zurückkehren, wenn Velendris die Schiffswerft zurückerobert hat.\n\nHier, nehmt diese Münze. Ich kann Euch leider nicht mehr geben, aber ich hoffe, es entlohnt Eure Mühen.", rewards = "Ihr bekommt:\n\n"},
[8887] = {title = "Kapitänin Kelisendras verlorene Seekarten", objective = "Bringt Kapitänin Kelisendras verlorene Seekarten zu Kapitänin Kelisendra beim befestigten Lager direkt östlich des Ankerplatzes der Sonnensegel im Immersangwald zurück.", description = "Interessant... was Ihr hier gefunden habt, ist eine wasserdichte Lederhülse, die ein paar Seiten Pergamentpapier enthält. Nach den Kennzeichnungen zu urteilen, handelt es sich eindeutig um Seekarten. Jede dieser Karten trägt das Siegel von Kapitänin Kelisendra.\n\nIhr habt sicher schon von einem kleinen, befestigten Lager östlich des nahegelegenen Ankerplatzes der Sonnensegel gehört. Vielleicht findet Ihr die Kapitänin ja dort?", progress = "Hallo, <Klasse>, Euer Anblick ist ein gutes Zeichen. Ich weiß, es ist verrückt, dass ich überhaupt hier bin, wo der Ankerplatz doch von den Getriebenen überfallen wurde. Velendris und seine Waldläufer haben geschworen mich zu beschützen, unter der Bedingung, dass ich von hier verschwinde, sobald ich meine Fracht wiedererlangt habe.\n\nWas habt Ihr da... das kommt mir so bekannt vor?", completion = "Oh, Ihr herzensguter, herzensguter &lt;Klasse&gt;! Ich hatte ja keine Ahnung, dass diese widerlichen Grimmschuppenmurlocs auch noch meine Seekarten entwendet hatten! Ohne diese Karten hätte ich niemals wieder in See stechen können, sobald wir den Ankerplatz zurückerobert und das Schiff repariert haben.\n\nIch bin Euch zutiefst dankbar! Hier, nehmt diese Münze als Zeichen meiner Anerkennung.", rewards = "Ihr bekommt:\n\n"},
[8888] = {title = "Der Lehrling des Magisters", objective = "Sprecht mit Lehrling Loralthalis nahe des Nachtschimmerturms im Immersangwald.<Klasse>, hört Euch mein Anliegen an. Auf Grund von Dingen, die ich jetzt nicht weiter erklären kann, habe ich beschlossen, meine nahegelegene Schule zu schließen. Vor ein paar Tagen habe ich eine meiner Schülerinnen, Lehrling Loralthalis, mit diesem Auftrag dorthin geschickt. Seitdem habe ich nichts mehr von ihr gehört.\n\nWerdet Ihr zum Nachtschimmerturm gehen und nachsehen, ob alles mit ihr in Ordnung ist? Ihr werdet den Turm finden, indem Ihr dem Pfad, der von der Zuflucht der Weltenwanderer aus nach Norden führt, folgt und dann bei der Weggabelung rechts abbiegt.", description = "<Klasse>, hört Euch mein Anliegen an. Auf Grund von Dingen, die ich jetzt nicht weiter erklären kann, habe ich beschlossen, meine nahegelegene Schule zu schließen. Vor ein paar Tagen habe ich eine meiner Schülerinnen, Lehrling Loralthalis, mit diesem Auftrag dorthin geschickt. Seitdem habe ich nichts mehr von ihr gehört.\n\nWerdet Ihr zum Nachtschimmerturm gehen und nachsehen, ob alles mit ihr in Ordnung ist? Ihr werdet den Turm finden, indem Ihr dem Pfad, der von der Zuflucht der Weltenwanderer aus nach Norden führt, folgt und dann bei der Weggabelung rechts abbiegt.", progress = nil, completion = "Der Magister sorgt sich um mein Wohlergehen? Wie süß von ihm; ich wünschte, er hätte ein derartiges Interesse etwas früher gezeigt, als wir noch im Turm waren.\n\nNaja, das tut jetzt nichts zur Sache. Hört gut zu, &lt;Klasse&gt;, ich muss Euch um einen Gefallen bitten.", rewards = "Ihr bekommt:\n\n"},
[8889] = {title = "Deaktivierung des Turms", objective = "Deaktiviert 3 Kraftquellen des Nachtschimmerturms im Nachtschimmerturm. Bringt anschließend das Deaktivierungsjuwel zu Lehrling Loralthalis im Immersangwald.", description = "Wie Ihr wisst, hat mich Magister Nachtschimmer hierher zurückgeschickt, damit ich die Kraftquellen, die den Turm versorgen, deaktiviere. Es gibt drei davon, sie befinden sich an unterschiedlichen Stellen im Innern des Turms.\n\nUnglücklicherweise scheine ich zu spät zu sein, denn der Nachtschimmerturm wurde von seltsamen, magischen Kreaturen überrannt. Ich habe nicht das benötigte Wissen, um diese Aufgabe zu erfüllen, aber <ein/eine:c> <Klasse> wie Ihr könnte es doch sicherlich ohne größere Probleme?", progress = "Ich kann es aus dieser Entfernung nicht mit Sicherheit sagen... habt Ihr den Nachtschimmerturm bereits deaktiviert?", completion = "Ich bin Euch für Eure Hilfe dankbar, aber es betrübt mich zu hören, dass einige meiner Lehrlingsfreunde der Abhängigkeit verfallen sind.\n\nJetzt, da die Kraftquellen des Turms deaktiviert wurden, werde ich wohl noch eine Weile hier bleiben. Ich möchte sehen, ob sich die Lage beruhigt, damit ich mich hineinschleichen kann, um ihre Überreste zu bergen.", rewards = "Ihr bekommt:\n\n"},
[8890] = {title = "Nachricht vom Turm", objective = "Kehrt zu Magister Nachtschimmer bei der Zuflucht der Weltenwanderer im Immersangwald zurück.<Name>, ich hätte noch eine letzte Bitte an Euch. Würdet Ihr Magister Nachtschimmer bei der Zuflucht der Weltenwanderer über die Ereignisse berichten, die hier vorgefallen sind? Sagt ihm, dass es mir gut geht, aber betont bitte auch, dass einige Lehrlinge zu Getriebenen geworden sind.\n\nVielen Dank für Eure Hilfe!", description = "<Name>, ich hätte noch eine letzte Bitte an Euch. Würdet Ihr Magister Nachtschimmer bei der Zuflucht der Weltenwanderer über die Ereignisse berichten, die hier vorgefallen sind? Sagt ihm, dass es mir gut geht, aber betont bitte auch, dass einige Lehrlinge zu Getriebenen geworden sind.\n\nVielen Dank für Eure Hilfe!", progress = nil, completion = "Nein! Ich war zu spät. Es ist alles meine Schuld.\n\nMeine Untersuchungen hinsichtlich der Aufbereitung alternativer Magiequellen sind mir außer Kontrolle geraten und ich konnte nichts mehr tun, was dies hätte aufhalten können. Wäre ich nur selbst gegangen... oder hätten sie auf mich gehört und meine Warnungen befolgt!\n\nMeine Hände sind mit Blut befleckt, &lt;Klasse&gt;. Ich danke Euch dennoch, dass Ihr diese armen Seelen meiner ehemaligen Lehrlinge erlöst habt. Es ist ein kleiner Trost zu wissen, dass sie nicht länger in dem Zustand verweilen müssen, an dessen Stelle ein &lt;Volk&gt; besser tot wäre.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGegenstand #23399\n\nIhr bekommt außerdem:\n\n"},
[8891] = {title = "Aufgegebene Untersuchungen", objective = "Bringt Magister Nachtschimmers Tagebuch zu Magister Nachtschimmer bei der Zuflucht der Weltenwanderer im Immersangwald zurück.", description = "Ihr habt ein Buch mit Untersuchungsberichten gefunden, das offenbar von Magister Nachtschimmer zurückgelassen wurde. Ihr überfliegt rasch den Inhalt und stellt mit Entsetzen fest, dass man versucht hat, verderbte magische Ströme zu filtern, was womöglich eine Erklärung für die Ereignisse hier beim Nachtschimmerturm sein könnte. Der Magister möchte dies sicherlich zurück.", progress = "Was ist das? Es kommt mir bekannt vor. Oh nein, dieses Tagebuch... meine Untersuchungen... dies hat all die schrecklichen Ereignisse verursacht.", completion = "Hier ist er also, &lt;Name&gt;, der Beweis für mein Verbrechen. Dieses Tagebuch enthält all meine schlecht durchdachten Studien.\n\nIch schenkte den Warnungen keine Beachtung und führte meine Untersuchungen fort, bis es schon fast zu spät war. Als ich endlich meine Fehler einsah, tat ich alles in meiner Macht Stehende. Allerdings sind einige meiner Schüler zu diesem Zeitpunkt bereits zu weit gegangen. Ich evakuierte den Turm, um sie vor der Verderbnis in Schutz zu bringen. Jedoch vergaß ich in meiner Eile, die Kraftquellen zu deaktivieren.\n\nIch werde diese Aufzeichnungen verbrennen, damit sie zukünftig keinen Schaden mehr anrichten können. Ich wollte den Sin'dorei doch nur helfen.", rewards = "Ihr bekommt:\n\n"},
[8892] = {title = "Vorfall beim Ankerplatz der Sonnensegel", objective = "Tötet 5 getriebene Rohlinge und 5 getriebene Straßendiebe und erstattet Waldläufer Degolien im Immersangwald Bericht.", description = "Der Ankerplatz der Sonnensegel wurde von einem Haufen Getriebener überrannt. Sobald wir Verstärkung erhalten, werden wir diesen Verbrechern schon zeigen, wer hier das Sagen hat, <Name>.\n\nIn der Zwischenzeit könntet Ihr uns helfen, indem Ihr ihnen etwas Disziplin beibringt. Geht zu ihnen und macht deutlich, dass man mit uns keine Spielchen treibt. Der Ankerplatz der Sonnensegel liegt genau westlich von Morgenluft.", progress = nil, completion = "Das wird ihnen zeigen, dass man es sich mit uns besser nicht verscherzt. Gute Arbeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[8893] = {title = "Der Super-Ei-O-Mat", objective = "Der Super-Ei-O-Mat ist die neueste Erfindung von Curgle Cranklehop. Es ist eine ziemlich beeindruckende Maschine.\n\nDer Super-Ei-O-Mat fängt wild an zu spucken und zu zischen, als Ihr Euch der Steuerkonsole nähert.", description = nil, progress = "Der Super-Ei-O-Mat ist die neueste Erfindung von Curgle Cranklehop. Es ist eine ziemlich beeindruckende Maschine.\n\nDer Super-Ei-O-Mat fängt wild an zu spucken und zu zischen, als Ihr Euch der Steuerkonsole nähert.", completion = "Ihr legt das Hippogryphen-Ei in die Maschine. Es folgen eine Reihe von Pieptönen sowie ein seltsames Rasseln, Rattern und Klicken.\n\nEs scheint, als hätte das Ei-O-Meter Euer Ei gewogen, vermessen und verpackt. Das ist echt ein zügiger Service!", rewards = "Ihr bekommt:\n\nEierkiste"},
[8894] = {title = "Sicherung des Grunds", objective = "Tötet 6 Manaschlangen und 6 Ätherbestien. Kehrt anschließend zu Grundbewahrer Wyllithen beim Nachtschimmergrund im Immersangwald zurück.", description = "Ich kann Euch sagen, es ist furchtbar! Seltsame Dinge gehen im Turm vor sich, der Magister und seine Lehrlinge sind weggelaufen und wie Ihr wisst, wurde der gesamte Grund von magischen Bestien überrannt! Und wer sagte Wyllithen Bescheid? Niemand, so sieht es aus!\n\n<Klasse>, Ihr müsst mir helfen, hier wieder für Ordnung zu sorgen... ich kann nicht länger über den Grund wachen, solange diese 'Anomalien' hier in blinder Wut herumlaufen!", progress = "Habt Ihr Euch darum gekümmert? Ist Euch eine ausreichende Zahl dieser magischen Anomalien zum Opfer gefallen? Was würde ich nur tun, wenn Magister Nachtschimmer zurückkäme und all diese Bestien wären noch hier?", completion = "Nun, ich denke, das dürfte fürs Erste genügen, oder nicht? Danke für die Hilfe, &lt;Klasse&gt;. Ich hoffe nur, dass ich hier alles rechtzeitig absichern kann, bevor der Magister zum Nachtschimmerturm zurückkommt.\n\nNehmt dies bisschen Kleingeld; es ist nicht viel, aber ich habe im Moment nicht mehr. Ihr könnt ruhig noch ein paar Bestien mehr töten, wenn Ihr hier unterwegs seid, das wäre nett von Euch.", rewards = "Ihr bekommt:\n\n"},
[8895] = {title = "Lieferung an das Sanktum des Nordens", objective = "Überbringt den unbeschrifteten Brief an Leybewahrer Caidanis beim Sanktum des Nordens im Immersangwald.", description = "Es freut mich, dass Ihr Euch zumindest in gewissen Hinsichten als fähig erweist, <Name>. Ich gebe Euch eine weitere Aufgabe, da Ihr so begierig scheint, Euch beweisen zu wollen.\n\nDies ist ein Brief für Leybewahrer Caidanis, der Arkanist, der für die Aufrechterhaltung des Sanktums des Nordens verantwortlich ist. Geht vom Falkenplatz Richtung Südwesten und Ihr werdet ihn finden. Er ist eine sehr wichtige Persönlichkeit, ich hoffe also, dass Ihr ihn nicht mit zu belanglosem Geschwätz belästigt.", progress = "Ja, <Klasse>?", completion = "Vielen Dank, &lt;Name&gt;. Ich habe diesen Brief bereits erwartet.", rewards = "Ihr bekommt:\n\n"},
[8896] = {title = "Der Zwergenspion", objective = "Findet und tötet Ausgrabungsleiter Ambossel im Sanktum des Nordens und berichtet anschließend Aeldon Sonnenmal im Immersangwald.Seid Ihr sicher, dass Ihr diese Notizen bei einer Nachtelfe gefunden habt? Das meiste davon wurde in Zwergisch verfasst...\n\nAusgrabungsleiter Ambossel! Er wurde von Eisenschmiede wegen eines diplomatischen Auftrags hierher geschickt. Ich hätte es wissen müssen, sein Interesse an unseren arkanen Sankten war etwas zu groß. <Name>, findet den Zwerg im Sanktum des Nordens und kümmert Euch um ihn. Oh, bitte geht diskret dabei vor.", description = "Seid Ihr sicher, dass Ihr diese Notizen bei einer Nachtelfe gefunden habt? Das meiste davon wurde in Zwergisch verfasst...\n\nAusgrabungsleiter Ambossel! Er wurde von Eisenschmiede wegen eines diplomatischen Auftrags hierher geschickt. Ich hätte es wissen müssen, sein Interesse an unseren arkanen Sankten war etwas zu groß. <Name>, findet den Zwerg im Sanktum des Nordens und kümmert Euch um ihn. Oh, bitte geht diskret dabei vor.", progress = nil, completion = nil, rewards = nil},
[8897] = {title = "Liebste Colara", objective = "Bringt Lieutenant Heldrics sorgfältig verfasste Notiz zu Colara Dean außerhalb der Bank von Stormwind.", description = "Wenn ich das Tor bewache muss ich ständig an meine geliebte Colara denken. Ich kann sie immer nur für ein paar kurze Stunden sehen, wenn ich Glück habe. Ach, seht mich doch an. Ich erhalte nur einen niederen Offizierssold und jeden Tag könnte ich an die Front abberufen werden.\n\nWürde sie mich dann einfach vergessen? Ich meine, es gibt so viele wohlhabende Männer in der Stadt.\n\nHier, ich habe einige Dinge aufgeschrieben... Nicht viel, aber vielleicht könntet Ihr diese Nachricht meiner Liebsten überbringen. Mein Dank wäre Euch gewiss.", progress = "Hallo, Süßer. Kann ich dir irgendwie helfen?", completion = "Oh, ist das nicht süß! Es ist das erste Mal, dass er mir überhaupt etwas schickt. Glaubt Ihr, er meint es ernst?\n\nColara Heldric? Das hat etwas Klangvolles, findet Ihr nicht? Oh, vielleicht bin ich etwas zu voreilig. Vielen Dank!", rewards = nil},
[8898] = {title = "Liebste Colara", objective = "Bringt den zerknitterten Brief zu Colara Dean außerhalb der Bank in Stormwind.", description = "Als ich geschäftlich mit der Bank in Stormwind zu tun hatte, traf ich ein Mädchen. Sie hat mir auf Anhieb mein Herz gestohlen. Ich kann einfach nicht mehr aufhören, an sie zu denken! Ich würde Ihr gerne diese Nachricht schicken. Ganze Zwölfmal musste ich sie neu schreiben!\n\nJetzt möchte ich sicherstellen, dass sie meinen Brief auch erhält.\n\nVielleicht reist Ihr ja nach Stormwind und könnt mir weiterhelfen?", progress = "Hallo, Süßer. Kann ich dir irgendwie helfen?", completion = "Tormek? Oh ja, ich erinnere mich an ihn. Er hatte einen sehr gepflegten Bart und obendrein ein recht ansehnliches Lächeln.\n\nIch kann es kaum fassen, dass er sich noch an mich erinnert!", rewards = nil},
[8899] = {title = "Liebste Colara", objective = "Bringt den makellosen Brief zu Colara Dean außerhalb der Bank von Stormwind.", description = "Wie soll ich Ihre Schönheit nur beschreiben? Tausende Jahre voll der Poesie und mir fehlen die Worte.\n\nDiese Sterblichen verwässern den Geist und am Ende bleiben wir als plappernde Narren zurück.\n\nZu lange habe ich diese Worte immer und immer wieder in mich aufgenommen. Es ist mir unmöglich sie weiter zu verfeinern. Nein, sie muss diese Nachricht noch heute erhalten, oder ein anderer Verehrer wird sie für sich einnehmen.", progress = "Hallo, Süßer. Kann ich dir irgendwie helfen?", completion = "Ich habe noch nie etwas Derartiges erhalten. Wie liebenswert!", rewards = nil},
[8900] = {title = "Liebste Elenia", objective = "Bringt die leicht zerknitterte Notiz zu Elenia Haydon nahe der Bank in Undercity.", description = "Sie war so traurig. Ich habe es genau gespürt, trotz Ihrer Versuche es zu verbergen. Ich meine, sie wirkte so traurig, versteht Ihr?\n\nDa war diese Verbindung zwischen uns beiden, als ich mit ihr sprach. Niemand hatte mich bisher verstanden, doch sie tat es auf Anhieb.\n\nAls ich es den anderen erzählte, lachten sie nur über mich und so habe ich nie wieder mit ihr gesprochen. Doch ich vermisse sie. Würdet Ihr mir einen Gefallen tun und ihr diesen Brief von mir geben? Ich will sicher sein, dass sie ihn auch erhält.", progress = "Oh, und welchen Umständen verdanke ich dieses Vergnügen?", completion = "Man mag es kaum glauben, dass ein Orc derart wortgewandt sein kann. Natürlich hatten wir bisher kaum Chancen, die Orcs im Allgemeinen besser kennenzulernen. Vielen Dank, für das Überbringen dieses Briefs.", rewards = nil},
[8901] = {title = "Liebste Elenia", objective = "Bringt den sorgfältig verfassten Brief zu Elenia Haydon nahe der Bank in Undercity.", description = "Habt Ihr jemals wahre Liebe erfahren, <junger Herr/junge Dame>? Noch vor kurzem war dies ein Fremdwort für mich, doch dann traf ich dieses junge Mädchen aus Undercity, Elenia. Es ist selten für einen Angehörigen meiner Art, sich mit den anderen Völker einzulassen, ganz besonders mit den Verlassenen.\n\nDoch jetzt sind meine Gedanken Tag und Nacht von ihr erfüllt.\n\nWäre es Euch vielleicht möglich, ihr diesen Brief zu überbringen? Ich möchte, dass sie hierher nach Mulgore kommt. Hoffentlich sagt sie ja.", progress = "Oh, und welchen Umständen verdanke ich dieses Vergnügen?", completion = "Welch liebliche Worte Temma für mich fand. Doch, soviel mich seine Verse auch bewegen, ich könnte niemals einen &lt;Volk&gt; lieben. Wir leben in verschiedenen Welten, unsere Gedanken, unser Äußeres unterscheiden sich zu sehr.\n\nEs ist gut, dass er mir diesen Brief nicht persönlich überbracht hat. Ich könnte es nicht ertragen, sein Herz auf diese Weise zu brechen.", rewards = nil},
[8902] = {title = "Liebste Elenia", objective = "Bringt den liebevoll verfassten Brief zu Elenia Haydon nahe der Bank in Undercity.", description = "Zu Lebzeiten hatte ich geschworen, Elenia, meine Jugendliebe, zu meiner Frau zu nehmen. Es ist schon Jahre her, seit ich das letzte Mal an sie denken musste. Doch seit einiger Zeit beherrschen mehr und mehr Gedanken an sie meinen Verstand.\n\nObwohl es eine Ewigkeit her ist, sollte es in unser beider Leben noch etwas Raum für unsere Liebe geben.\n\nIch bin sicher, auch sie wird sich verändert haben. Sei es drum! Wäre es Euch vielleicht möglich, ihr diesen Brief zu überbringen? Ich selbst bin zu nervös, um ihr selbst gegenüberzutreten.", progress = "Oh, und welchen Umständen verdanke ich dieses Vergnügen?", completion = "Dieser Brief weckt Erinnerungen an ein längst vergangenes Leben, &lt;Name&gt;. Elenia Tor. Einst war dies mein Name, wisst Ihr. Eine wundervolle Zeremonie an den Ufern des Sees sollte es werden. Er wollte sich zur Ruhe setzen und gemeinsam wollten wir uns auf einem Bauernhof niederlassen.\n\nEs waren einfache Träume, die wir hatten.\n\nDoch wenn er mich nun sehen könnte, ich glaube kaum, dass er die alte Elenia in mir wiedererkennen würde. Nur kaltes Fleisch und ein totes Herz...", rewards = nil},
[8903] = {title = "Gefährliche Liebschaft", objective = "Besorgt die Karte einer Wache von Stormwind und bringt sie zu Aristan Mottar in Stormwind.", description = "Diese Liebesepidemie hat etwas unnatürliches an sich. Die ganze Situation ist ungebührlich, ja ein Schandfleck, und im schlimmsten Fall eine Bedrohung für die Sicherheit der gesamten Allianz.\n\nDenkt doch nur: Was passiert, wenn sämtliche Wachen von dieser seltsamen Krankheit betroffen werden? Irgendetwas muss geschehen.\n\nGeht zu einer der Wachen hier in Stormwind und seht, ob sie von dieser törichten Epidemie befallen wurde.", progress = "Waren meine Sorgen berechtigt? Stehen unsere Wachen bereits unter dem Einfluss dieser Liebeskrankheit?", completion = "Es ist also wahr! Das ist unglaublich, wie konnte das nur passieren? Lasst mich einen Moment nachdenken. Es muss doch eine Ursache für all das geben.", rewards = nil},
[8904] = {title = "Gefährliche Liebschaft", objective = "Besorgt eine modrige Karte des Wächters und bringt sie zu Fenstad Argyle in Undercity.", description = "Diese Liebesepidemie hat etwas unnatürliches an sich. Die ganze Situation ist abscheulich, und wenn sie erst einmal unsere Verteidigung schwächt, könnte dies zu einer ernsten Bedrohung für uns alle werden.\n\nSchlimm genug, dass bereits ein Großteil unserer Bevölkerung dieses lächerlich säuselnde Verhalten an den Tag legt. Ich denke, selbst unsere Wächter hat es bereits erwischt, dabei sollten sie gegen derartige Einflüsse immun sein.\n\nGeht zu einem der Wächter und seht, ob er von dieser törichten Epidemie befallen wurde.", progress = "Waren meine Sorgen berechtigt? Wurden unsere idiotischen Wachen überwältigt?", completion = "Es ist also wahr! Das ist unglaublich, wie konnte das nur passieren? Lasst mich einen Moment nachdenken. Es muss doch eine Ursache für all das geben.", rewards = nil},
[8905] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Blutproben aus Winterspring und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Wildherzens zu Deliana in Ironforge.", description = "Seid gegrüßt, <Klasse>. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterspring heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", progress = "Habt Ihr mitgebracht, worum ich Euch gebeten habe, <Name>?", completion = "Exzellent! Dann lasst uns den Austausch vornehmen. Es fällt mir nicht leicht, mich von dieser ausgezeichneten Rüstung zu trennen, aber ich fürchte, ich werde sie in nächster Zeit nicht brauchen.\n\nWenn Ihr daran interessiert sein solltet, mehr Arbeit für mich zu erledigen, wäre ich gewillt auch die anderen Teile aufzugeben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nArmschienen des ungezähmten Herzens"},
[8906] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Blutproben aus Winterspring und bringt sie zusammen mit 20 Gold und einem Paar Bestienjägerbindungen zu Deliana in Ironforge.", description = "Seid gegrüßt, <Klasse>. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterspring heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", progress = "Habt Ihr mitgebracht, worum ich Euch gebeten habe, <Name>?", completion = "Exzellent! Dann lasst uns den Austausch vornehmen. Es fällt mir nicht leicht, mich von dieser ausgezeichneten Rüstung zu trennen, aber ich fürchte, ich werde sie in nächster Zeit nicht brauchen.\n\nWenn Ihr daran interessiert sein solltet, mehr Arbeit für mich zu erledigen, wäre ich gewillt auch die anderen Teile aufzugeben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nBindungen der Tierherrschaft"},
