[8912] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Blutproben aus Winterspring und bringt sie zusammen mit 20 Gold und einem Paar Armschienen der Ehre zu Deliana in Ironforge.", description = "Seid gegrüßt, <Klasse>. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterspring heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", progress = "Habt Ihr mitgebracht, worum ich Euch gebeten habe, <Name>?", completion = "Exzellent! Dann lasst uns den Austausch vornehmen. Es fällt mir nicht leicht, mich von dieser ausgezeichneten Rüstung zu trennen, aber ich fürchte, ich werde sie in nächster Zeit nicht brauchen.\n\nWenn Ihr daran interessiert sein solltet, mehr Arbeit für mich zu erledigen, wäre ich gewillt auch die anderen Teile aufzugeben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nArmschienen des Heldentums"},
[8913] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Wildherzens zu Mokvar in Orgrimmar zurück.", description = "Ich grüße Euch, <Klasse>. Eure Haltung verrät mir, dass Ihr bereits ganz schön herumgekommen seid. Ich würde allerdings darauf wetten, dass Euch noch keine Rüstung wie diese untergekommen ist.\n\nWenn Ihr mir einen kleinen Gefallen tut, wäre ich bereit, diese Rüstung gegen ein normales Paar Armschienen einzutauschen.\n\nIch bräuchte eine ziemlich große Menge an Giftproben von den Spinnen und Skorpionen aus Silithus. Bringt es mir zusammen mit einigen Goldmünzen und ich werde den Tausch vornehmen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nArmschienen des ungezähmten Herzens"},
[8914] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Bestienjägerbindungen zu Mokvar in Orgrimmar zurück.", description = "Ich grüße Euch, <Klasse>. Eure Haltung verrät mir, dass Ihr bereits ganz schön herumgekommen seid. Ich würde allerdings darauf wetten, dass Euch noch keine Rüstung wie diese untergekommen ist.\n\nWenn Ihr mir einen kleinen Gefallen tut, wäre ich bereit, diese Rüstung gegen ein normales Paar Armschienen einzutauschen.\n\nIch bräuchte eine ziemlich große Menge an Giftproben von den Spinnen und Skorpionen aus Silithus. Bringt es mir zusammen mit einigen Goldmünzen und ich werde den Tausch vornehmen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nBindungen der Tierherrschaft"},
[8915] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Bindungen des Magisters zu Mokvar in Orgrimmar zurück.", description = "Ich grüße Euch, <Klasse>. Eure Haltung verrät mir, dass Ihr bereits ganz schön herumgekommen seid. Ich würde allerdings darauf wetten, dass Euch noch keine Rüstung wie diese untergekommen ist.\n\nWenn Ihr mir einen kleinen Gefallen tut, wäre ich bereit, diese Rüstung gegen ein normales Paar Armschienen einzutauschen.\n\nIch bräuchte eine ziemlich große Menge an Giftproben von den Spinnen und Skorpionen aus Silithus. Bringt es mir zusammen mit einigen Goldmünzen und ich werde den Tausch vornehmen.", progress = "Habt Ihr die von mir benötigten Gegenstände beisammen, <Name>?", completion = "Ja, Mux sollte damit hochzufrieden sein.\n\nDiese Armschienen sind ein Teil eines vollständigen Rüstungssets. Solltet Ihr gewillt sein, mich weiterhin zu unterstützen, würde ich es in Betracht ziehen, mich auch von den anderen Teilen zu trennen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nBindungen der Zauberkünste"},
[8916] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Gläubigen zu Mokvar in Orgrimmar zurück.", description = "Ich grüße Euch, <Klasse>. Eure Haltung verrät mir, dass Ihr bereits ganz schön herumgekommen seid. Ich würde allerdings darauf wetten, dass Euch noch keine Rüstung wie diese untergekommen ist.\n\nWenn Ihr mir einen kleinen Gefallen tut, wäre ich bereit, diese Rüstung gegen ein normales Paar Armschienen einzutauschen.\n\nIch bräuchte eine ziemlich große Menge an Giftproben von den Spinnen und Skorpionen aus Silithus. Bringt es mir zusammen mit einigen Goldmünzen und ich werde den Tausch vornehmen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nArmschienen des Tugendhaften"},
