[8918] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Bindungen der Elemente zu Mokvar in Orgrimmar zurück.", description = "Ich grüße Euch, <Klasse>. Eure Haltung verrät mir, dass Ihr bereits ganz schön herumgekommen seid. Ich würde allerdings darauf wetten, dass Euch noch keine Rüstung wie diese untergekommen ist.\n\nWenn Ihr mir einen kleinen Gefallen tut, wäre ich bereit, diese Rüstung gegen ein normales Paar Armschienen einzutauschen.\n\nIch bräuchte eine ziemlich große Menge an Giftproben von den Spinnen und Skorpionen aus Silithus. Bringt es mir zusammen mit einigen Goldmünzen und ich werde den Tausch vornehmen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nBindungen der fünf Donner"},
[8919] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Armschienen der Furcht zu Mokvar in Orgrimmar zurück.", description = "Ich grüße Euch, <Klasse>. Eure Haltung verrät mir, dass Ihr bereits ganz schön herumgekommen seid. Ich würde allerdings darauf wetten, dass Euch noch keine Rüstung wie diese untergekommen ist.\n\nWenn Ihr mir einen kleinen Gefallen tut, wäre ich bereit, diese Rüstung gegen ein normales Paar Armschienen einzutauschen.\n\nIch bräuchte eine ziemlich große Menge an Giftproben von den Spinnen und Skorpionen aus Silithus. Bringt es mir zusammen mit einigen Goldmünzen und ich werde den Tausch vornehmen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nArmschienen des Todesnebels"},
[8920] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Giftproben aus Silithus und bringt es zusammen mit 20 Gold und einem Paar Armschienen der Ehre zu Mokvar in Orgrimmar zurück.", description = "Ich grüße Euch, <Klasse>. Eure Haltung verrät mir, dass Ihr bereits ganz schön herumgekommen seid. Ich würde allerdings darauf wetten, dass Euch noch keine Rüstung wie diese untergekommen ist.\n\nWenn Ihr mir einen kleinen Gefallen tut, wäre ich bereit, diese Rüstung gegen ein normales Paar Armschienen einzutauschen.\n\nIch bräuchte eine ziemlich große Menge an Giftproben von den Spinnen und Skorpionen aus Silithus. Bringt es mir zusammen mit einigen Goldmünzen und ich werde den Tausch vornehmen.", progress = "Habt Ihr die von mir benötigten Gegenstände beisammen, <Name>?", completion = "Ja, Mux sollte damit hochzufrieden sein.\n\nDiese Armschienen sind ein Teil eines vollständigen Rüstungssets. Solltet Ihr gewillt sein, mich weiterhin zu unterstützen, würde ich es in Betracht ziehen, mich auch von den anderen Teilen zu trennen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nArmschienen des Heldentums"},
[8921] = {title = "Der Ektoplasmadestillierer", objective = "Kehrt mit einem empfindlichen Arkanitwandler, 4 großen ewigen Essenzen, 10 Flaschen Steinschuppenöl, 25 Einheiten Vulkanasche und 40 Gold im Gepäck zu Mux Manascrambler in Gadgetzan zurück.", description = "Ah, Ihr seid an meinem letzten Projekt interessiert... Dem extradimensionalen Geisterdetektor! Dummerweise sind mir die Geldmittel und Hilfskräfte ausgegangen\n\nIhr sagt, dass Ihr mir aushelfen wollt? Sehr gut! Zunächst müssen wir einen Apparat bauen, der die Essenz des Todes absaugen kann! Einen Ektoplasmadestillierer zu konstruieren wird allerdings nicht ganz einfach sein, <Name>.\n\nIhr müsst mir einen Arkanitwandler, einige große ewige Essenzen und Steinschuppenöl bringen. Außerdem brauche ich noch Vulkanasche aus den Lavatümpeln in der brennenden Steppe, um einen Filter zu konstruieren.", progress = "Ich verstehe schon, dass diese Materialien etwas teuer sind... Aber ich kann Euch garantieren, dass sie alle dringend benötigt werden.", completion = "Das sind genau die Materialien, die ich benötige. Und genau zur rechten Zeit, &lt;Name&gt;!\n\nIn wenigen Momenten werde ich den Destillierapparat fertig haben! Aber nehmt schon mal diese Belohnung dafür, dass Ihr mir bei meinem Projekt behilflich seid.", rewards = "Ihr bekommt:\n\nMux' Qualitätswaren"},
[8922] = {title = "Ein übernatürlicher Apparat", objective = "Bringt den versiegelten Blutbehälter zu Mux Manascrambler in Gadgetzan.", description = "Ich muss einen Weg finden, mit Anthion Harmon zu sprechen... Oder genauer gesagt mit seinem Geist!\n\nIch kenne da einen Ingenieur, der eine gewisse Faszination für das Übernatürliche hegt. Er behauptet eine Maschine konstruieren zu können, die es ihm erlaubt mit den Toten zu kommunizieren!\n\nDas Blut, dass Ihr gesammelt habt, war für ihn bestimmt. Reist nach Gadgetzan und bringt es ihm als Bezahlung für seine Dienste!", progress = "Habt Ihr etwas für mich?", completion = "Exzellent! Gerade als mir die Vorräte anfingen auszugehen. Ihr sagt Deliana schickt Euch?", rewards = "Ihr bekommt:\n\n"},
[8923] = {title = "Ein übernatürlicher Apparat", objective = "Bringt den versiegelten Giftbehälter zu Mux Manascrambler in Gadgetzan.", description = "Ihr müsst wirklich verdammt mutig sein. Respekt, dass Ihr immer noch an der Sache dran seid. Oder vielleicht haben die Rüstungsteile, die ich Euch gegeben habe, ja Euer Interesse geweckt. Wo die herkamen gibt's noch mehr, wenn Ihr daran interessiert seid, mir erneut auszuhelfen.\n\nDie Giftproben, die Ihr gesammelt habt, sind für einen Bekannten von mir bestimmt, Mux Manascrambler, ein Ingenieur mit einem gewissen Interesse für das Übernatürliche. Seine neueste Erfindung soll es angeblich ermöglichen, mit den Toten zu kommunizieren! Meine letzte Hoffnung ist es, Anthion zu kontaktieren und mehr über meine Situation herauszufinden.", progress = "Ihr wünscht, mit mir reden?", completion = "Exzellent! Gerade als mir die Vorräte anfingen auszugehen. Ihr sagt Mokvar schickt Euch?", rewards = "Ihr bekommt:\n\n"},
[8924] = {title = "Ektoplasmajagd", objective = "Benutzt den Ektoplasmadestillierer in der Nähe von schemenhaften Untoten, um 12 Einheiten versengtes Ektoplasma in Silithus, 12 Einheiten gefrorenes Ektoplasma in Winterspring und 12 Einheiten stabiles Ektoplasma in den östlichen Pestländern zu erhalten. Bringt das Ektoplasma dann mitsamt des Ektoplasmadestillierers zu Mux Manascrambler in Gadgetzan zurück.", description = "Ein hervorragendes Stück Ingenieurarbeit, wenn ich das mal selbst so sagen darf! Ich fürchte allerdings, dass Ihr weit umherreisen werden müsst, um die Art schemenhafter Untoten zu finden, die wir benötigen.\n\nIhr müsst verstehen, dass verschiedenen Klimabedingungen Einfluss auf die spektrale Struktur der Toten haben. Die gequälten Nachtelfen in Silithus, die Geister der Hochgeborenen in Winterspring und die Geister und Banshees in den östlichen Pestländern sollten uns mit den verschiedenen Sorten von Ektoplasma versorgen, die wir benötigen. Stellt auf jeden Fall den Destillierer in der Nähe auf, bevor Ihr sie bekämpft.", progress = "Habt Ihr das Ektoplasma schon zusammengesammelt, <Name>?", completion = "Ja, die sind perfekt!\n\nWenn wir uns die in diesen Substanzen beinhalteten übernatürlichen Energien zunutze machen, werden wir in der Lage sein mit den Seelen jener zu kommunizieren, die diese Welt noch nicht ganz verlassen haben.", rewards = "Ihr bekommt:\n\n"},
[8925] = {title = "Eine portable Energiequelle", objective = "Findet Magmafürst Bokk in der brennenden Steppe, nehmt seinen Magmakern an Euch und bringt ihn zu Mux Manascrambler in Gadgetzan.", description = "Jetzt brauchen wir nur noch eine stabile und portable Energiequelle, um das Ektoplasma aktiv zu halten. Ich habe Gerüchte über einen machtvollen Elementar namens Magmafürst Bokk gehört, dessen Herz ein mächtiger Magmakern ist - eine schier unerschöpfliche Hitzequelle!\n\nMan sagt, dass er sich irgendwo in der brennenden Steppe südlich des Blackrock herumtreibt. Bringt mir den Magmakern und wir werden genug Saft haben, um den extradimensionalen Geisterdetektor zu betreiben!", progress = "Habt Ihr den Magmafürsten gefunden, <Name>?", completion = "Ihr habt es geschafft! Jetzt haben wir bestimmt genug Energie für den extradimensionalen Geisterdetektor!", rewards = "Ihr bekommt:\n\n"},
[8926] = {title = "Die angemessene Entlohnung", objective = "Bringt Deliana in Ironforge einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens.", description = "Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrechtzuerhalten. Bringt mir den Gürtel und die Handschuhe, von denen Ihr eine verbesserte Version wünscht. Ich kann Euch versichern, dass die Rüstung, die ich Euch geben werde, von weit höherer Qualität sein wird.", progress = "Seid Ihr bereit, den Handel einzugehen?", completion = "Ihr habt Euren Teil der Abmachung eingehalten, also werde ich auch meinen einhalten.\n\nDenkt nur daran, dass ich Euch die besten Teile erst dann gebe, wenn Eure Arbeit vollbracht ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nGürtel des ungezähmten HerzensHandschuhe des ungezähmten Herzens"},
[8927] = {title = "Die angemessene Entlohnung", objective = "Bringt Mokvar in Orgrimmar einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens.", description = "Ihr habt große Verlässlichkeit bewiesen, <Name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nGürtel des ungezähmten HerzensHandschuhe des ungezähmten Herzens"},
[8928] = {title = "Ein verschlagener Händler", objective = "Sucht den Wichtel in der Höhle in der Nähe der flüsternden Schlucht im Süden von Winterspring. Kauft ihm einen teufelselementaren Brennstab ab und kehrt zu Mux Manascrambler in Gadgetzan zurück.", description = "Der Kern sollte uns mit genügend Energie zum Betreiben des Apparates versorgen, jetzt brauchen wir nur noch einen Brennstab, der diese Energie auch weiterleiten kann, ohne dabei zu schmelzen.\n\nIch habe in Winterspring mal einen Wichtel getroffen, der allerlei exotische Waren im Angebot hatte. Er hatte einen elementaren Brennstab, der einfach perfekt gewesen wäre. Ich könnte mich schwarzärgern, dass ich den nicht gekauft habe.\n\nEr lebt in einer Höhle nahe dem Zugang zur flüsternden Schlucht. Schleicht Euch hinein und seht zu, dass Ihr ihn findet.\n\nLasst Euch aber nicht von ihm übers Ohr hauen, zahlt ihm nicht mehr als 40 Goldstücke. Den Preis hat er mir damals angeboten!", progress = "Habt Ihr den Wichtel in der flüsternden Schlucht gefunden?", completion = "Ihr habt es geschafft! Dieser Brennstab ist einfach perfekt! Jetzt müssen wir nur noch alles zusammenfügen...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[8929] = {title = "Suche nach Anthion", objective = "Benutzt den extradimensionalen Geisterdetektor am Eingang zu Stratholme und sprecht mit dem Geist von Anthion Harmon.\n\nBereitgestellter Gegenstand: \n", description = "Tja, wir haben wohl keine andere Wahl, als die Erfindung des Goblins auszuprobieren. Man sagt, dass Anthion von den untoten Horden Stratholmes niedergemetzelt wurde, als er versuchte, durch dessen Tore zu schreiten.\n\nVersucht den Apparat dort zu benutzen und herauszufinden, was auch immer Anthion wusste.", progress = nil, completion = "Deliana wollte, dass Ihr mich kontaktiert? Ich werde mein Bestes tun, um Euch zu helfen, aber zunächst muss ich Euch um einen großen Gefallen bitten.", rewards = "Ihr bekommt:\n\n"},
[8930] = {title = "Suche nach Anthion", objective = "Benutzt den extradimensionalen Geisterdetektor am Eingang zu Stratholme und sprecht mit dem Geist von Anthion Harmon.\n\nBereitgestellter Gegenstand: \n", description = "Nun denn, <Name>. Jetzt müssen wir wohl die Erfindung des Goblins ausprobieren. Man sagt, dass Anthion von den untoten Horden Stratholmes niedergemäht wurde, als er versuchte, durch die Tore zu schreiten.\n\nVersucht den Apparat dort zu benutzen und findet heraus, was Anthion wusste.", progress = nil, completion = "Mokvar wollte, dass Ihr mich kontaktiert? Ich werde Euch nach meinen besten Möglichkeiten aushelfen, aber zuerst muss ich Euch um einen großen Gefallen bitten.", rewards = "Ihr bekommt:\n\n"},
[8931] = {title = "Die angemessene Entlohnung", objective = "Bringt Deliana in Ironforge einen Bestienjägergürtel und ein Paar Bestienjägerhandschuhe.", description = "Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrecht zu erhalten. Bringt mir den Gürtel und die Handschuhe, von denen Ihr eine verbesserte Version wünscht.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nGürtel der TierherrschaftHandschuhe der Tierherrschaft"},
[8932] = {title = "Die angemessene Entlohnung", objective = "Bringt Deliana in Ironforge einen Gürtel des Magisters und ein Paar Handschuhe des Magisters.", description = "Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrecht zu erhalten. Bringt mir den Gürtel und die Handschuhe, von denen Ihr eine verbesserte Version wünscht.", progress = "Seid Ihr bereit, den Austausch vorzunehmen?", completion = "Ihr habt Euren Teil der Abmachung eingehalten, also werde ich auch meinen einhalten.\n\nDenkt nur daran, dass ich Euch die besten Teile erst dann gebe, wenn Eure Arbeit vollbracht ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nGürtel der ZauberkünsteHandschuhe der Zauberkünste"},
