[9013] = {title = "Das Beste gibt's zum Schluss", objective = "Gebt Mokvar Euren Helm der Ehre und Eure Brustplatte der Ehre.", description = "Das ist ja eine unglaubliche Geschichte, <Name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Ihr habt durch Eure Taten die Sünden unserer Vergangenheit gesühnt.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nHelm des HeldentumsBrustplatte des Heldentums"},
[9014] = {title = "Das Beste gibt's zum Schluss", objective = "Gebt Mokvar Eure Krone des Magisters und Eure Roben des Magisters.", description = "Das ist ja eine unglaubliche Geschichte, <Name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nKrone der ZauberkünsteRoben der Zauberkünste"},
[9015] = {title = "Die Herausforderung", objective = "Reist zum Ring des Gesetzes der Blackrocktiefen und errichtet das Banner der Provokation in dessen Mitte, während Ihr von Oberrichter Grimmstein verurteilt werdet. Tötet Theldren und seine Gladiatoren und kehrt dann mit dem ersten Stück von Lord Valthalaks Amulett zu Anthion Harmon in den östlichen Pestländern zurück.", description = "Hört mir gut zu, <Name>. Damit das Banner die gewünschte Wirkung erzielen kann, werdet Ihr Euch in den Ring des Gesetzes der Blackrocktiefen begeben müssen. Lasst Euch von Oberrichter Grimmstein verurteilen und errichtet das Banner als Zeichen der Herausforderung.\n\nEuer Opfer wird sich nicht zurückhalten können und sich, von dem Wunsch Euch zu bekämpfen beseelt, in den Kampf stürzen. Kehrt zu Anthion zurück, sobald Ihr das habt, wonach es Euch begehrt.", progress = "Ihr seid zurück, <Name>!", completion = "Ihr habt einen Teil des Amuletts wiederbeschafft, &lt;Name&gt;?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[9016] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Stiefel des Wildherzens, einem Kilt des Wildherzens und einer Schiftung des Wildherzens zu Mokvar in Orgrimmar zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nStiefel des ungezähmten HerzensKilt des ungezähmten HerzensSchiftung des ungezähmten Herzens"},
[9017] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Bestienjägerstiefeln, einer Bestienjägerhose und einem Bestienjägermantel zu Mokvar in Orgrimmar zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nStiefel der TierherrschaftHose der TierherrschaftMantel der Tierherrschaft"},
