[9060] = {title = "Gurt des Gruftpirschers", objective = "Jäger Leopold bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch einen Gurt des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Gurt, 8 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 3 Nexuskristalle.", description = "Ich habe eine Verwendung für den Panzer der Gruftsatanskreatur gefunden. Ich bin in der Lage ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente der Gruftsatanskreaturen mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", progress = "Habt Ihr die Gegenstände, um die ich Euch gebeten habe, <Klasse>?", completion = "Ein Gurt, der eines Königs würdig wäre! Angefertigt für Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nGurt des Gruftpirschers"},
[9061] = {title = "Handgelenksschutz des Gruftpirschers", objective = "Jäger Leopold bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch einen Handgelenksschutz des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Handgelenksschutz, 6 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 2 geschmeidige unverwüstliche Bälge.", description = "Ich habe eine Verwendung für den Panzer der Gruftsatanskreatur gefunden. Ich bin in der Lage ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente der Gruftsatanskreaturen mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", progress = "Habt Ihr die Gegenstände, um die ich Euch gebeten habe, <Klasse>?", completion = "Der Handgelenksschutz ist fertig. Viel Spaß damit!", rewards = "Ihr bekommt:\n\nHandgelenksschutz des Gruftpirschers"},
[9063] = {title = "Torwa Pathfinder", objective = "Sprecht im Un'Goro Krater mit Torwa Pathfinder.", description = "Ein Jäger names Torwa Pathfinder hat die Hilfe eines Druiden angefordert. Er sagte, dass nur einer von uns über den nötigen Respekt für die Natur und die Fähigkeiten verfügen würde, um ihm zu helfen.\n\nEs gibt einen Pfad, der den Un'Goro Krater und die Tanariswüste verbindet. Ihr werdet Torwa nahe dem Punkt finden, an dem der Pfad in den Krater hineinführt.", progress = nil, completion = "Ihr seid weit gereist, um mich zu treffen, &lt;Klasse&gt;, und Ihr kommt genau zur rechten Zeit.", rewards = "Ihr bekommt:\n\n"},
[9065] = {title = "The \"Chow\" Quest (123)aa", objective = "Kill Kobold Vermin, 2 of em.$Tpunk;!  Kill Kobold Vermin, 2 of em.Ihr erlernt:\n\n", description = "$Tpunk;!  Kill Kobold Vermin, 2 of em.Ihr erlernt:\n\n", progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nHeilen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nJahr des Huhns\n\nIhr bekommt außerdem:\n\nErfrischendes QuellwasserSchwacher Heiltrank"},
[9068] = {title = "Tunika des Erdspalters", objective = "Rimblat Erdspalter bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch eine Tunika des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Kettenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", description = "Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?\n\nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.\n\nBringt mir die Überbleibsel der Gefallenen, sowie die läuternden Materialien, dann soll Erdspalter Euer sein.\n\nSucht in Naxxramas.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTunika des Erdspalters"},
[9069] = {title = "Beinschützer des Erdspalters", objective = "Rimblat Erdspalter bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Beinschützer des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinschützer, 20 kampfzerschlissene Kettenstücke, 3 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.", description = "Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?\n\nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.\n\nBringt mir die Überbleibsel der Gefallenen, sowie die läuternden Materialien, dann soll Erdspalter Euer sein.\n\nSucht in Naxxramas.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeinschützer des Erdspalters"},
