[9102] = {title = "Frostfeuerbindungen", objective = "Erzmagierin Angela Dosantos bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Frostfeuerbindungen anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 Paar entweihte Bindungen, 6 kampfzerschlissene Stoffstücke, 1 Arkankristall und 1 Nexuskristall.", description = "Als Behüterin hatte ich Zugang zu Vielem von Medivhs persönlicher Habe. Die Folianten waren für micht die aufschlussreichsten Gegenstände. Während die Mehrheit der Bücher aus - sagen wir es ganz offen - Schund bestand, gab es auch einige Schmuckstücke darunter. Einer dieser Folianten beschrieb die Herstellung eines Rüstungssets, passend für einen Erzmagier: Frostfeuer.\n\n<Angela deutet auf ihren Kopf.>\n\nEs ist alles hier drin und ich bin bereit, die Früchte dieses Wissens mit Euch zu teilen, solange Ihr mir die nötigen Materialien besorgt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFrostfeuerbindungen"},
[9103] = {title = "Robe des verseuchten Herzens", objective = "Mataus der Zornwirker bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch eine Robe des verseuchten Herzens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Robe, 25 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.", description = "Ich mache Euch nichts vor, Wurm. Die Finsternis, die die Rüstung des verseuchten Herzens erfüllt, könnte uns beide mit Leichtigkeit zerstören. Dies erklärt den äußerst hohen Preis. Sollte ich sterben, so werde ich zumindest als reicher Mann dahinscheiden.\n\nEs kümmert mich einen Ogerdreck als was Ihr sterbt, Hauptsache Ihr macht, was ich von Euch verlange. Bringt mir die benötigten Dinge und wir werden beide davon profitieren - oder sterben; aber das habe ich ja bereits erklärt...", progress = "Der verlorene Hamster kehrt zurück! Habt Ihr die von mir benötigten Dinge?", completion = "Seht Ihr? Versteht Ihr jetzt die Macht? Läuterung... welch' Narren...\n\n&lt;Mataus schüttelt missbilligend seinen Kopf.&gt;\n\nNehmt jetzt Euer Zeug und geht mir aus den Augen.", rewards = "Ihr bekommt:\n\nRobe des verseuchten Herzens"},
[9104] = {title = "Gamaschen des verseuchten Herzens", objective = "Mataus der Zornwirker bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Gamaschen des verseuchten Herzens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Gamaschen, 20 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.", description = "Ich mache Euch nichts vor, Wurm. Die Finsternis, die die Rüstung des verseuchten Herzens erfüllt, könnte uns beide mit Leichtigkeit zerstören. Dies erklärt den äußerst hohen Preis. Sollte ich sterben, so werde ich zumindest als reicher Mann dahinscheiden.\n\nEs kümmert mich einen Ogerdreck als was Ihr sterbt, Hauptsache Ihr macht, was ich von Euch verlange. Bringt mir die benötigten Dinge und wir werden beide davon profitieren - oder sterben; aber das habe ich ja bereits erklärt...Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGamaschen des verseuchten Herzens"},
[9105] = {title = "Reif des verseuchten Herzens", objective = "Mataus der Zornwirker bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch einen Reif des verseuchten Herzens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Reif, 15 kampfzerschlissene Stoffstücke, 3 Einheiten Mondstoff und 3 Nexuskristalle.", description = "Ich mache Euch nichts vor, Wurm. Die Finsternis, die die Rüstung des verseuchten Herzens erfüllt, könnte uns beide mit Leichtigkeit zerstören. Dies erklärt den äußerst hohen Preis. Sollte ich sterben, so werde ich zumindest als reicher Mann dahinscheiden.\n\nEs kümmert mich einen Ogerdreck als was Ihr sterbt, Hauptsache Ihr macht, was ich von Euch verlange. Bringt mir die benötigten Dinge und wir werden beide davon profitieren - oder sterben; aber das habe ich ja bereits erklärt...Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nReif des verseuchten Herzens"},
[9106] = {title = "Schulterpolster des verseuchten Herzens", objective = "Mataus der Zornwirker bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Schulterpolster des verseuchten Herzens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Schulterpolster, 12 kampfzerschlissene Stoffstücke, 2 Einheiten Mondstoff und 3 geschmeidige unverwüstliche Bälge.", description = "Ich mache Euch nichts vor, Wurm. Die Finsternis, die die Rüstung des verseuchten Herzens erfüllt, könnte uns beide mit Leichtigkeit zerstören. Dies erklärt den äußerst hohen Preis. Sollte ich sterben, so werde ich zumindest als reicher Mann dahinscheiden.\n\nEs kümmert mich einen Ogerdreck als was Ihr sterbt, Hauptsache Ihr macht, was ich von Euch verlange. Bringt mir die benötigten Dinge und wir werden beide davon profitieren - oder sterben; aber das habe ich ja bereits erklärt...", progress = "Der verlorene Hamster kehrt zurück! Habt Ihr die von mir benötigten Dinge?", completion = "Seht Ihr? Versteht Ihr jetzt die Macht? Läuterung... welch' Narren...\n\n&lt;Mataus schüttelt missbilligend seinen Kopf.&gt;\n\nNehmt jetzt Euer Zeug und geht mir aus den Augen.", rewards = "Ihr bekommt:\n\nSchulterpolster des verseuchten Herzens"},
