[9111] = {title = "Robe des Glaubens", objective = "Vater Inigo Montoy bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch eine Robe des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Robe, 25 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, Kind?", completion = "Die Ausrüstung ist fertig, &lt;Name&gt;. Vernichtet diejenigen mit Eurem Feuer der Rechtschaffenheit, die unserer Welt schaden wollen.", rewards = "Ihr bekommt:\n\nRobe des Glaubens"},
[9112] = {title = "Gamaschen des Glaubens", objective = "Vater Inigo Montoy bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Gamaschen des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Gamaschen, 20 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, Kind?", completion = "Die Ausrüstung ist fertig, &lt;Name&gt;. Vernichtet diejenigen mit Eurem Feuer der Rechtschaffenheit, die unserer Welt schaden wollen.", rewards = "Ihr bekommt:\n\nGamaschen des Glaubens"},
[9113] = {title = "Reif des Glaubens", objective = "Vater Inigo Montoy bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch einen Reif des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Reif, 15 kampfzerschlissene Stoffstücke, 3 Einheiten Mondstoff und 3 Nexuskristalle.", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nReif des Glaubens"},
[9114] = {title = "Schulterpolster des Glaubens", objective = "Vater Inigo Montoy bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Schulterpolster des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Schulterpolster, 12 kampfzerschlissene Stoffstücke, 2 Einheiten Mondstoff und 3 geschmeidige unverwüstliche Bälge.", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, Kind?", completion = "Die Ausrüstung ist fertig, &lt;Name&gt;. Vernichtet diejenigen mit Eurem Feuer der Rechtschaffenheit, die unserer Welt schaden wollen.", rewards = "Ihr bekommt:\n\nSchulterpolster des Glaubens"},
[9115] = {title = "Sandalen des Glaubens", objective = "Vater Inigo Montoy bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Sandalen des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Sandalen, 12 kampfzerschlissene Stoffstücke, 2 Einheiten Mondstoff und 3 geschmeidige unverwüstliche Bälge.", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, Kind?", completion = "Die Ausrüstung ist fertig, &lt;Name&gt;. Vernichtet diejenigen mit Eurem Feuer der Rechtschaffenheit, die unserer Welt schaden wollen.", rewards = "Ihr bekommt:\n\nSandalen des Glaubens"},
[9116] = {title = "Handschuhe des Glaubens", objective = "Vater Inigo Montoy bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Handschuhe des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Handschuhe, 8 kampfzerschlissene Stoffstücke und 4 Einheiten Mondstoff.", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, Kind?", completion = "Die Ausrüstung ist fertig, &lt;Name&gt;. Vernichtet diejenigen mit Eurem Feuer der Rechtschaffenheit, die unserer Welt schaden wollen.", rewards = "Ihr bekommt:\n\nHandschuhe des Glaubens"},
[9117] = {title = "Gürtel des Glaubens", objective = "Vater Inigo Montoy bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch einen Gürtel des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Gürtel, 8 kampfzerschlissene Stoffstücke, 2 Arkankristalle und 2 Einheiten Mondstoff.", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, Kind?", completion = "Die Ausrüstung ist fertig, &lt;Name&gt;. Vernichtet diejenigen mit Eurem Feuer der Rechtschaffenheit, die unserer Welt schaden wollen.", rewards = "Ihr bekommt:\n\nGürtel des Glaubens"},
[9118] = {title = "Bindungen des Glaubens", objective = "Vater Inigo Montoy bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Bindungen des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Bindungen, 6 kampfzerschlissene Stoffstücke, 1 Arkankristall und 1 Nexuskristall.", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, Kind?", completion = "Die Ausrüstung ist fertig, &lt;Name&gt;. Vernichtet diejenigen mit Eurem Feuer der Rechtschaffenheit, die unserer Welt schaden wollen.", rewards = "Ihr bekommt:\n\nBindungen des Glaubens"},
[9120] = {title = "Der Niedergang Kel'Thuzads", objective = "Bringt Kel'Thuzads Phylakterium zu der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Das Phylakterium ist alles, was vom Herrscher Naxxramas' übrig bleibt. Nach Eurem pflichtgemäßen Ermessen, müsstet Ihr das Phylakterium zerstören, um somit einem erneuten Aufbäumen des Lichs vorzubeugen. Glücklicherweise hört Ihr nur selten auf Eure innere Stimme der Vernunft.\n\nBei der Kapelle des hoffnungsvollen Lichts wird Euch irgendjemand mit Sicherheit ein Vermögen für dieses Artefakt bezahlen. Wen kümmert es schon, ob Kel'Thuzad eines Tages wieder von Neuem erstarkt?", progress = "HEILIGES LICHT! Was ist denn in Euch gefahren, Junge?", completion = "Ich hätte mir nie erträumt, dass ich das eines Tages mal zu Gesicht bekommen sollte...\n\n&lt;Vater Montoy scheint lüstern zu geifern.&gt;\n\nOh ja, Ihr sollt entlohnt werden, mein Junge. Reichlich entlohnt. Gebt es mir. Jetzt!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMal des HeldenMal des Helden\n\nIhr bekommt außerdem:\n\n"},
[9121] = {title = "Die Zitadelle des Schreckens - Naxxramas", objective = "Erzmagierin Angela Dosantos bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 5 Arkankristalle, 2 Nexuskristalle, 1 rechtschaffene Kugel und 60 Goldstücke. Euer Ruf bei der Argentumdämmerung muss außerdem wohlwollend sein.", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch dort hineinzugelangen von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichte gemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mit Hilfe von arkaner Tarnung Zugang verschaffen können - einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Da es an Eurer Hingabe für die Ziele der Argentumdämmerung noch etwas mangelt, <Name>, wird der Preis hoch sein. Es steht Euch frei abzulehnen und noch einmal für einen günstigeren Preis wiederzukehren, sobald Euer Ruf respektvoll oder ehrfürchtig ist.", progress = "Keiner von denen, die Naxxramas betreten haben, hat überlebt, um davon berichten zu können.", completion = "Ihr werdet ein leichtes Prickeln verspüren, &lt;Name&gt;. Dieses Gefühl ist das Zeichen dafür, dass es funktioniert. Sobald das Ganze abgeschlossen ist, werdet Ihr Naxxramas durch das Runenportal im Pestwald betreten können.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nArkane Tarnung"},
[9122] = {title = "Die Zitadelle des Schreckens - Naxxramas", objective = "Erzmagierin Angela Dosantos bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 2 Arkankristalle, 1 Nexuskristall und 30 Goldstücke. Euer Ruf bei der Argentumdämmerung muss außerdem respektvoll sein.", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch dort hineinzugelangen von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichte gemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mit Hilfe von einer Art dauerhaften arkanen Tarnung Zugang verschaffen können - einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Diese Tarnung ist allerdings sehr kostspielig. Da Eure Hingabe für die Ziele der Argentumdämmerung bewundernswert ist, sind wir gewillt, einige dieser Kosten für Euch zu übernehmen.", progress = "Keiner von denen, die Naxxramas betreten haben, hat überlebt, um davon berichten zu können.", completion = "Ihr werdet ein leichtes Prickeln verspüren, &lt;Name&gt;. Dieses Gefühl ist das Zeichen dafür, dass es funktioniert. Sobald das Ganze abgeschlossen ist, werdet Ihr Naxxramas durch das Runenportal im Pestwald betreten können.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nArkane Tarnung"},
[9123] = {title = "Die Zitadelle des Schreckens - Naxxramas", objective = "Erzmagierin Angela Dosantos bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird Euch die arkane Tarnung kostenfrei gewähren. Euer Ruf bei der Argentumdämmerung muss ehrfürchtig sein.", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch dort hineinzugelangen von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichte gemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mit Hilfe von einer Art dauerhaften arkanen Tarnung Zugang verschaffen können - einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Diese Tarnung ist allerdings sehr kostspielig. Da Eure Hingabe für die Ziele der Argentumdämmerung jedoch unerschütterlich ist, werden wir Euch sämtliche Kosten erlassen.", progress = nil, completion = "Ihr werdet ein leichtes Prickeln verspüren, &lt;Name&gt;. Dieses Gefühl ist das Zeichen dafür, dass es funktioniert. Sobald das Ganze abgeschlossen ist, werdet Ihr Naxxramas durch das Runenportal im Pestwald betreten können.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nArkane Tarnung"},
[9124] = {title = "Was man für Gruftpirscherrüstung braucht...", objective = "Jäger Leopold bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 30 Teile einer Gruftsatanskreatur.", description = "Würdet Ihr Euch gerne eine dieser glänzenden Münzen verdienen?\n\n<Leopold hält eine Insignie des Kreuzzugs in die Höhe.>\n\nIch habe ein kleines Problem, bei dem Ihr mir vielleicht behilflich sein könntet, <Name>. Seht Ihr, ich fertige Gruftpirscherrüstung für diejenigen an, die dämlich genug sind, um sich nach Naxxramas zu wagen. Während sie mich mit den wichtigsten Bestandteilen für die Rüstung versorgen, gehen mir dennoch ständig die Teile von Gruftsatanskreaturen aus. Bringt mir einen Schwung dieser Teile und ich werde Euch dafür mit einer Insignie bezahlen - einlösbar bei dem Rüstmeister.", progress = "Wie geht es mit der Jagd voran?", completion = "Ah, die werden sich gut eignen, &lt;Name&gt;. Vergesst nicht, ich nehme jederzeit noch mehr Teile entgegen. Für jede Ladung, die Ihr mir bringt, belohne ich Euch mit einer Insignie.", rewards = "Ihr bekommt:\n\nInsignie des Kreuzzugs"},
[9125] = {title = "Teile einer Gruftsatanskreatur", objective = "Ihr habt mit dem ersten Schwung vorbildliche Arbeit geleistet, <Name>. Solltet Ihr noch mehr Teile haben, nehme ich sie Euch jetzt ab. Für jede abgelieferte Ladung werde ich Euch mit einer Insignie belohnen.", description = nil, progress = "Ihr habt mit dem ersten Schwung vorbildliche Arbeit geleistet, <Name>. Solltet Ihr noch mehr Teile haben, nehme ich sie Euch jetzt ab. Für jede abgelieferte Ladung werde ich Euch mit einer Insignie belohnen.", completion = "Ausgezeichnet, &lt;Name&gt;! Hierfür wird man mit Sicherheit gute Verwendung finden.", rewards = "Ihr bekommt:\n\nInsignie des Kreuzzugs"},
[9126] = {title = "Knochensensenjagd", objective = "Rohan der Assassine bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 30 Knochenfragmente.", description = "Don Julios Muster für die Rüstung der Knochensense benötigt Knochenfragmente - ein Menge Knochenfragmente. Diejenigen, die verrückt genug sind, um sich nach Naxxramas zu wagen, versorgen mich bereits mit den wichtigsten Bestandteilen für die Rüstung. Allerdings halte ich stets nach weiteren Knochenfragmenten Ausschau.\n\nWas denkt Ihr? Würdet Ihr Euch gerne die Hände schmutzig machen und dabei ein paar Anhänger der Geißel vernichten? Hierbei kommt jeder gut davon.", progress = "Ich kann Euch die Richtung zu Orten weisen, die von Skeletten heimgesucht werden, <Klasse>.", completion = "Ihr seid schnell, &lt;Name&gt;. Schnell wie der Wind... Sagt mal, habe ich Euch schon von meiner Zeit in dem Barbershop-Quartett erzählt?\n\nErinnert mich das nächste Mal daran, Euch davon zu berichten.", rewards = "Ihr bekommt:\n\nInsignie des Kreuzzugs"},
[9127] = {title = "Knochenfragmente", objective = "Ein Mann meines Berufsstandes kann niemals zu viele Knochenfragmente besitzen, <Name>. Kommt zu mir, wann immer Ihr einen Überschuss an Fragmenten habt, ich tausche sie dann gegen eine weitere Insignie ein.", description = nil, progress = "Ein Mann meines Berufsstandes kann niemals zu viele Knochenfragmente besitzen, <Name>. Kommt zu mir, wann immer Ihr einen Überschuss an Fragmenten habt, ich tausche sie dann gegen eine weitere Insignie ein.", completion = "Mein Traum von einer Karriere als professioneller Tänzer in der Disko von Gadgetzan wird sich schon bald verwirklichen! Gute Arbeit, weiter so, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nInsignie des Kreuzzugs"},
[9128] = {title = "Die Elementargleichung", objective = "Erzmagierin Angela Dosantos bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 30 Kerne der Elemente.", description = "Seid gegrüßt, Abenteurer! Hättet Ihr Interesse an Arbeit? Wer für mich arbeitet, wird mit Insignien bezahlt. Diese Insignien können beim Rüstmeister für mächtige Gegenstände eingetauscht werden.\n\nEure Aufgabe besteht darin, mir so viele Kerne der Elemente zu bringen, wie Ihr tragen könnt. Je mehr, umso besser!\n\nIhr findet sie bei Elementaren verschiedenster Form und Größe, wie es sie überall in unserer Welt gibt.", progress = "Ich kann Euch lediglich die Richtung weisen, <Name>.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Hier, wie versprochen Eure Insignie. Vergesst nicht, wo das hier herkommt, gibt es noch mehr...", rewards = "Ihr bekommt:\n\nInsignie der Dämmerung"},
[9129] = {title = "Kern der Elemente", objective = "Glaubt mir, ich verwende diese Kerne zum Anfertigen von Frostfeuerrüstungen. Es ist die Rüstung, die von Magiern getragen wird, die in Naxxramas kämpfen. Ohne Euch und Euresgleichen, würden wir diesen Krieg höchstwahrscheinlich verlieren.\n\nBringt Ihr mir auch weiterhin mehr Kerne, so werde ich Euch dafür wieder mit Insignien entlohnen.", description = nil, progress = "Glaubt mir, ich verwende diese Kerne zum Anfertigen von Frostfeuerrüstungen. Es ist die Rüstung, die von Magiern getragen wird, die in Naxxramas kämpfen. Ohne Euch und Euresgleichen, würden wir diesen Krieg höchstwahrscheinlich verlieren.\n\nBringt Ihr mir auch weiterhin mehr Kerne, so werde ich Euch dafür wieder mit Insignien entlohnen.", completion = "Ihr erweist uns einen großen Dienst, &lt;Name&gt;. Gut gemacht!", rewards = "Ihr bekommt:\n\nInsignie der Dämmerung"},
[9131] = {title = "Bindung des Schreckenspanzers", objective = "Korfax bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 30 Dunkeleisenfragmente.", description = "Habt Ihr jemals eine Rüstung des Schreckenspanzers zu Gesicht bekommen, <Klasse>? Nein, natürlich nicht. Ihr seid immer noch ein <Junge/Mädchen> - ein Dreikäsehoch eben. Ich muss Euch sagen, es ist herrlich.\n\nIhr fragt Euch wahrscheinlich was all das mit Euch zu tun haben soll, richtig? Hört gut zu, Anfänger; ich brauche Dunkeleisenfragmente und bin bereit zu zahlen, um an so viele Stücke wie möglich zu kommen.\n\nIch benötige die Fragmente für das Zusammensetzen der Schreckenspanzer für unsere Helden. Bringt mir Fragmente, dann werdet Ihr bezahlt.", progress = "<Korfax faucht Euch an.>\n\nWas wollt Ihr? Eine Wegbeschreibung? Wenn es weiter nichts ist...", completion = "Das sollte genügen, zumindest vorläufig. Solltet Ihr mehr haben... Ihr wisst, wo Ihr mich finden könnt.", rewards = "Ihr bekommt:\n\nInsignie der Dämmerung"},
[9132] = {title = "Dunkeleisenfragmente", objective = "Ich gebe Euch für jede Ladung Dunkeleisenfragmente eine Insignie - je mehr, umso besser. Geht mir jetzt aus den Augen, bevor ich Euch noch zweiteile!", description = nil, progress = "Ich gebe Euch für jede Ladung Dunkeleisenfragmente eine Insignie - je mehr, umso besser. Geht mir jetzt aus den Augen, bevor ich Euch noch zweiteile!", completion = "Das ist alles, was Ihr mir gebracht habt? Vielleicht habt Ihr mich das erste Mal ja nicht richtig verstanden. Ich brauche MEHR!", rewards = "Ihr bekommt:\n\nInsignie der Dämmerung"},
[9136] = {title = "Wildpflanzen", objective = "Rayne bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 30 Wildwedel.", description = "Ich fertige für die mutigen Helden, die sich nach Naxxramas begeben, eine spezielle Rüstung an - die Rüstung des Traumwandlers. Sie versorgen mich zwar schon mit den meisten Materialien, die ich dafür benötige, aber ich halte dennoch nach jenen Ausschau, die in der Lage sind, mir Wildwedel aus dem Pflanzenreich unserer Welt zu besorgen.\n\nIhr denkt vielleicht, dass diese Aufgabe unter Eurer Würde ist, aber ohne diese Wedel kann die Rüstung nun mal nicht hergestellt werden.\n\nIch bin außerdem in der einzigartigen Lage, Euch mit einer Insignie Eurer Wahl zu bezahlen, da mich die Argentumdämmerung und der Kreuzzug mit den entsprechenden Mitteln unterstützen.", progress = "Ich bin mit dem Pflanzenreich unserer Welt sehr vertraut. Braucht Ihr Richtungsangaben?", completion = "Ich bin Euch sehr verbunden, &lt;Name&gt;.\n\n\n\nBitte denkt daran, dass ich jederzeit Wedel entgegennehme.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung\n\nIhr bekommt außerdem:\n\n"},
[9137] = {title = "Wildwedel", objective = "Für jeden Bündel Wildwedel, den Ihr bei mir abliefert, werde ich Euch mit einer von Euch gewählten Insignie, die der Dämmerung oder die des Kreuzzugs, bezahlen.\n\nDie Insignien können beim Rüstmeister für vielerlei Belohnungen eingetauscht werden.", description = nil, progress = "Für jeden Bündel Wildwedel, den Ihr bei mir abliefert, werde ich Euch mit einer von Euch gewählten Insignie, die der Dämmerung oder die des Kreuzzugs, bezahlen.\n\nDie Insignien können beim Rüstmeister für vielerlei Belohnungen eingetauscht werden.", completion = "Danke, &lt;Name&gt;. Eure Arbeit ist für den Erfolg unseres Feldzugs gegen die Geißel unerlässlich.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie der DämmerungInsignie des Kreuzzugs\n\nIhr bekommt außerdem:\n\n"},
[9141] = {title = "Sie nennen mich \"den Schleifer\"", objective = "Einsatzkommandant Metz in der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte eine Ehrenmarke der Argentumdämmerung.", description = "Ihr wollt eine Verfügung? Ihr erwartet von mir, Euch eine heißbegehrte Arbeitsanweisung einfach so auszuhändigen? Ich glaube nicht, Knirps. Handwerker aus der ganzen Welt bewerben sich um Aufträge hier an der Front.\n\nWenn Ihr eine Arbeitsanweisung wollt, zeigt mir, dass Ihr gewillt seit, für die Sache zu bluten! Bringt mir eine Ehrenmarke, dann können wir darüber reden.\n\nUnd es gibt nur einen Weg, so eine Marke in Eure schmutzigen kleinen Pfoten zu bekommen - geht kämpfen.", progress = "<Einsatzkommandant Metz kaut auf seiner Zigarre.>\n\nWas gibt's? Ich bin ein vielbeschäftigter Mann.", completion = "In Ordnung, so funktioniert's: Für jede Ehrenmarke, die Ihr abgebt, gebe ich Euch eine Verfügung. Ihr führt die Anweisung auf dieser Verfügung aus und liefert die Waren an Rottenkommandant Stonebruiser. Kapiert? Dann raus mit Euch.", rewards = "Ihr bekommt:\n\nVersiegelte Handwerksverfügung"},
[9142] = {title = "Handwerksverfügung", objective = "Ihr wisst wie's geht, Kind. Für eine Ehrenmarke bekommt Ihr eine Handwerksverfügung.", description = nil, progress = "Ihr wisst wie's geht, Kind. Für eine Ehrenmarke bekommt Ihr eine Handwerksverfügung.", completion = "Ihr habt's verdient, Anfänger. Beschwert Euch also nicht. Erfüllt Euren Auftrag oder lasst es bleiben.", rewards = "Ihr bekommt:\n\nVersiegelte Handwerksverfügung"},
[9153] = {title = "Bedrohliche Schatten", objective = "Seht auf Eure Karte, um von der Geißel angegriffene Gebiete ausfindig zu machen. Geht dorthin und beschädigt eine Nekropole, indem Ihr die sie umgebenden Truppen der Geißel besiegt. Bringt 10 ihrer nekrotischen Runen zu Kommandant Thomas Helleran bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Die schwebenden Nekropolen der Geißel belagern gleichermaßen die Territorien der Horde und der Allianz. Tanaris, die verwüsteten Lande, Winterspring und die brennende Steppe erzittern unter den Schatten der fliegenden Festungen.\n\nNur durch unser gemeinsames Handeln, können wir sie zurückschlagen.\n\nDie Nekropolen werden durch magische Zirkel unterstützt, die sich an verschiedenen Punkten in den angegriffenen Gebieten befinden. Wir haben herausgefunden, dass wir die Verteidigung rund um die Zirkel zerstören können, indem wir die geistlosen Horden, die diese Zirkel umringen, vernichten.", progress = "Es wird einige Zeit dauern, bis wir diese Bedrohung überwunden haben. Wie ist es Euch ergangen, <Name>?", completion = "Ihr habt Euch sehr gut geschlagen, &lt;Name&gt;. Die vielen Niederlagen werden letztlich den Fall der Geißel herbeiführen.\n\nRuht Euch etwas aus und erholt Euch. Schon bald müsst Ihr wieder an die Front zurückkehren, damit wir unsere gerade gewonnene Stellung nicht wieder verlieren.\n\nUm Euch bei Euren zukünftigen Kämpfen zu unterstützen, werden wir Euch einen unserer speziellen Gegenstände zur Verfügung stellen, sobald Ihr uns mehr nekrotische Runen bringt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesegnetes ZauberölGeweihter Wetzstein"},
[9154] = {title = "Kapelle des hoffnungsvollen Lichts", objective = "Bringt den Ruf zu den Waffen zum Bewahrer der Schriften in die Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Die Geißel ist in größerer Anzahl zurückgekehrt, als wir es jemals zuvor gesehen haben. Deshalb rekrutiert die Argentumdämmerung alle Männer und Frauen, die fähig und dazu bereit sind, unsere Länder zu verteidigen.\n\nFalls Ihr unserer Sache dienen wollt, bringt dieses Dokument zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr seid also gekommen, unserem Orden beizutreten?", completion = "Die Argentumdämmerung hat um Hilfe gebeten, und Ihr seid unserem Ruf gefolgt. Wir haben keine Zeit, Euch angemessen auszubilden, aber wir glauben an Eure Fähigkeiten und daran, dass Ihr gemeinsam mit uns die Geißel zurückdrängen werdet.", rewards = nil},
[9165] = {title = "Verfügung des freien Geleits", objective = "Bringt die unterschriebene Verfügung des freien Geleits zu Einsatzkommandant Metz an der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Ohne die Hilfe von Euch Abenteurern, hätte meine Karawane es niemals geschaft! Die Geißelsoldaten, die uns im Unterholz aufgelauert haben, wollten wohl nicht, dass wir hier in einem Stück eintreffen.\n\n<Wache Didier wischt sich den Schweiß von der Stirn.>\n\nJetzt werden wir erst einmal hier warten, bis Feldmarschall Chambers eintrifft. Er wird Eure Verfügung für freies Geleit unterzeichnen, die Ihr dann zu Einsatzkommandant Metz an der Kapelle des hoffnungsvollen Lichts bringen könnt.\n\nUnd <Name>, achtet in der Gegenwart von Chambers auf Eure Worte. Er ist ein Mensch der Sorte 'Ich reiße Euch den Kopf ab und breche Euch sämtliche Knochen'... mit dem Unterschied, dass er es auch wirklich tut...Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie der DämmerungInsignie des Kreuzzugs"},
[9178] = {title = "Handwerksverfügung - Verdichteter Gewichtsstein", objective = "Bringt 120 verdichtete Gewichtssteine und die Handwerksverfügung für die verdichteten Gewichtssteine zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-091:\n\n120 verdichtete Gewichtssteine.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Jawohl, die werden sich für die schonungslosen Waffen der Infanterie noch als nützlich erweisen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9179] = {title = "Handwerksverfügung - Imperiale Plattenrüstung", objective = "Bringt 3 imperiale Plattenrüstungen und die Handwerksverfügung für die imperialen Plattenrüstungen zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-428:\n\n3 imperiale Plattenrüstungen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die ArgentumdämmerungAuf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9181] = {title = "Handwerksverfügung - Vulkanischer Hammer", objective = "Bringt 3 vulkanische Hämmer und die Handwerksverfügung für die vulkanischen Hämmer zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-697:\n\n3 vulkanische Hämmer.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die ArgentumdämmerungAuf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9182] = {title = "Handwerksverfügung - Gewaltige Thoriumstreitaxt", objective = "Bringt 3 gewaltige Thoriumstreitäxte und die Handwerksverfügung für die gewaltigen Thoriumstreitäxte zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-6020:\n\n3 gewaltige Thoriumstreitäxte.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Die sind nicht halb so groß, wie ich es erwartet habe. Wie auch immer, Geschäft ist Geschäft.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9183] = {title = "Handwerksverfügung - Strahlender Reif", objective = "Bringt 3 strahlende Reifen und die Handwerksverfügung für die strahlenden Reifen zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-80:\n\n3 strahlende Reifen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Ich kann es nicht fassen, dass Metz ernsthaft erwartet, dass unsere Truppen diesen minderwertigen Mist tragen, um sich gegen die eisigen Angriffe der Geißel zu verteidigen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9184] = {title = "Handwerksverfügung - Tückisches Lederstirnband", objective = "Bringt 10 tückische Lederstirnbänder und die Handwerksverfügung für die tückischen Lederstirnbänder zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer LW-971:\n\n10 tückische Lederstirnbänder.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Ganz schön tückisch, diese Dinger...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9185] = {title = "Handwerksverfügung - Unverwüstliches Rüstungsset", objective = "Bringt 25 unverwüstliche Rüstungssets und die Handwerksverfügung für die unverwüstlichen Rüstungssets zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer LW-448:\n\n25 unverwüstliche Rüstungssets.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Unverwüstliche Rüstungssets sind vielseitig einsetzbar, &lt;Name&gt;. Sie taugen nicht nur als zusätzliche Rüstungsschicht, sondern geben auch hervorragende Teekannenwärmer ab.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9186] = {title = "Handwerksverfügung - Tückischer Ledergürtel", objective = "Bringt 9 tückische Ledergürtel und die Handwerksverfügung für die tückischen Ledergürtel zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer LW-736:\n\n9 tückische Ledergürtel.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die ArgentumdämmerungAuf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9187] = {title = "Handwerksverfügung - Runenverzierte Lederhose", objective = "Bringt 4 runenverzierte Lederhosen und die Handwerksverfügung für die runenverzierten Lederhosen zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer LW-8485:\n\n4 runenverzierte Lederhosen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Die Druiden werden den Aufwand zu Schätzen wissen, welcher zur Herstellung dieser Hosen notwendig war. Vielen Dank, &lt;Klasse&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9188] = {title = "Handwerksverfügung - Hellstoffhose", objective = "Bringt 6 Hellstoffhosen und die Handwerksverfügung für die Hellstoffhosen zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-95:\n\n6 Hellstoffhosen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Bei allen guten Geistern, diese Dinger blenden mich ja fast schon! Verrückt, oder?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9190] = {title = "Handwerksverfügung - Runenstoffstiefel", objective = "Bringt 8 Runenstoffstiefel und die Handwerksverfügung für die Runenstoffstiefel zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-635:\n\n8 Runenstoffstiefel.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Bei Bronzebeards Bart! Ihr habt mir tatsächlich Runenstoffstiefel gebracht... Schätze, ich habe diese Wette verloren.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9191] = {title = "Handwerksverfügung - Runenstofftasche", objective = "Bringt 8 Runenstofftaschen und die Handwerksverfügung für die Runenstofftaschen zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-9999:\n\n8 Runenstofftaschen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Heiliger Schnürsenkel! Ist es das, was ich denke? Unsere Soldaten beschweren sich immer wieder über den Mangel an Taschen, um ihre ganze Ausrüstung zu verstauen. Einer hat sogar seine Feldrationen in seinen Backen verstaut... verdammter Nager.\n\nDas wird die Gemüter bestimmt abkühlen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9194] = {title = "Handwerksverfügung - Runenstoffrobe", objective = "Bringt 8 Runenstoffroben und die Handwerksverfügung für die Runenstoffroben zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer TR-7229:\n\n8 Runenstoffroben.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Das war doch völlig unnötig! Nein wirklich, wer hat sich das denn einfallen lassen? Keiner von uns wird ernsthaft beim Sturm auf Naxxramas eine Robe tragen wollen. Was hat Metz sich bloß dabei gedacht?\n\n&lt;Rottenkommandant Stonebruiser seufzt.&gt;\n\nBah, nur wieder eine weitere Ladung unnützes Zeug, das ich an die Front schaffen muss.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9195] = {title = "Handwerksverfügung - Goblin-Randalieraufladung", objective = "Bringt 20 Goblin-Randalieraufladungen und die Handwerksverfügung für die Goblin-Randalieraufladungen zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-11:\n\n20 Goblin-Randalieraufladungen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Jetzt kommen wir der Sache schon näher, &lt;Klasse&gt;. Sachen die ordentlich Krach machen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9196] = {title = "Handwerksverfügung - Thoriumgranate", objective = "Bringt 20 Thoriumgranaten und die Handwerksverfügung für die Thoriumgranaten zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-7:\n\n20 Thoriumgranaten.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Die Herstellung dieser Dinger muss ganz schön kostspielig gewesen sein. Hab ich Recht, &lt;Name&gt;?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9197] = {title = "Handwerksverfügung - Gnomen-Kampfhuhn", objective = "Bringt 4 Gnomen-Kampfhühner und die Handwerksverfügung für die Gnomen-Kampfhühner zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-0:\n\n4 Gnomen-Kampfhühner.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die ArgentumdämmerungAuf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9198] = {title = "Handwerksverfügung - Thoriumröhre", objective = "Bringt 14 Thoriumröhren und die Handwerksverfügung für die Thoriumröhren zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer EN-558:\n\n14 Thoriumröhren.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Thoriumröhren? Wow, danke.\n\n&lt;Rottenkommandant Stonebruiser wirft den Stapel Thoriumröhren auf einen der vielen Schrotthaufen.&gt;", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9200] = {title = "Handwerksverfügung - Erheblicher Manatrank", objective = "Bringt 10 erhebliche Manatränke und die Handwerksverfügung für die erheblichen Manatränke zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer AL-473:\n\n10 erhebliche Manatränke.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Die Nützlichkeit hiervon steht wohl außer Frage.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9201] = {title = "Handwerksverfügung - Großer Arkanschutztrank", objective = "Bringt 15 große Arkanschutztränke und die Handwerksverfügung für die großen Arkanschutztränke zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer AL-1420:\n\n15 große Arkanschutztränke.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "&lt;Rottenkommandant Stonebruiser öffnet einen der großen Arkanschutztränke und nimmt einen kräftigen Schluck.&gt;\n\nWooohooo! Das geht richtig ab, Baby! Aber richtig!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9202] = {title = "Handwerksverfügung - Erheblicher Heiltrank", objective = "Bringt 20 erhebliche Heiltränke und die Handwerksverfügung für die erheblichen Heiltränke zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer AL-169110:\n\n20 erhebliche Heiltränke.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Wisst Ihr wie die hier von den Truppen an der Front genannt werden? Priester in der Flasche...\n\n&lt;Rottenkommandant Stonebruiser singt.&gt;\n\n\"I'm your priest in a bott-le baby... you gotta drink me the right way...\"\n\nWas glotzt Ihr so Junge? Der Titel war hier monatelang auf Platz Eins!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9203] = {title = "Handwerksverfügung - Fläschchen der Versteinerung", objective = "Bringt 1 Fläschchen der Versteinerung und die Handwerksverfügung für das Fläschchen der Versteinerung zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer AL-90:\n\n1 Fläschchen der Versteinerung.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die ArgentumdämmerungAuf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9204] = {title = "Handwerksverfügung - Steinschuppenaal", objective = "Bringt 40 Steinschuppenaale und die Handwerksverfügung für die Steinschuppenaale zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer FS-5:\n\n40 Steinschuppenaale.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Hier hättet hierfür eine andere Verwendung gehabt, nicht wahr? Nun ja, dem Ganzen nachzuweinen hilft auch nicht mehr, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9205] = {title = "Handwerksverfügung - Panzerfisch", objective = "Bringt 30 Panzerfische und die Handwerksverfügung für die Panzerfische zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer FS-12:\n\n30 Panzerfische.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Ihr wisst wirklich nicht, wofür man die hier braucht?\n\n&lt;Rottenkommandant Stonebruiser lacht.&gt;\n\nAls ob ich Euch das verraten würde!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9206] = {title = "Handwerksverfügung - Zitteraal", objective = "Bringt 30 Zitteraale und die Handwerksverfügung für die Zitteraale zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer FS-9:\n\n30 Zitteraale.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", progress = "Ihr führt einen Auftrag aus, <Klasse>?", completion = "Aus denen macht man die besten Aalröllchen in der ganzen Welt. Richtig gehört - IN DER GANZEN WELT.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInsignie des KreuzzugsInsignie der Dämmerung"},
[9208] = {title = "Der Greuelwächter - Arkanum des Schutzes", objective = "Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum des Schutzes.", description = "Zanza kann viele antike Trollverzauberungen mit den richtigen Komponenten herstellen! Habt Ihr von dem Greuelwächter gehört? Nein, natürlich nicht. Euer Geist wurde mit jämmerlicher Elfenmagie verwirrt.\n\nBringt mir ein Arkanum, wie es die Elfen herstellen, damit ich das Böse zerstören kann. Seid Ihr erfolgreich, so soll der Greuelwächter Euch gehören.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGreuelwächter"},
[9209] = {title = "Der Greuelwächter - Arkanum der Schnelligkeit", objective = "Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum der Schnelligkeit.", description = "Zanza kann viele antike Trollverzauberungen mit den richtigen Komponenten herstellen! Habt Ihr von dem Greuelwächter gehört? Nein, natürlich nicht. Euer Geist wurde mit jämmerlicher Elfenmagie verwirrt.\n\nBringt mir ein Arkanum, wie es die Elfen herstellen, damit ich das Böse zerstören kann. Seid Ihr erfolgreich, so soll der Greuelwächter Euch gehören.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGreuelwächter"},
[9210] = {title = "Der Greuelwächter - Arkanum des Fokus", objective = "Zanza der Ruhelose in Zul'Gurub möchte ein Arkanum des Fokus.", description = "Zanza kann viele antike Trollverzauberungen mit den richtigen Komponenten herstellen! Habt Ihr von dem Greuelwächter gehört? Nein, natürlich nicht. Euer Geist wurde mit jämmerlicher Elfenmagie verwirrt.\n\nBringt mir ein Arkanum, wie es die Elfen herstellen, damit ich das Böse zerstören kann. Seid Ihr erfolgreich, so soll der Greuelwächter Euch gehören.", progress = "Habt Ihr das Arkanum?", completion = "Die wertlose Magie in diesen Verzauberungen verstärkt meinen Ärger. Mein Zorn gibt mir Stärke.\n\nBringt mir mehr davon und Ihr werdet einen weiteren Greuelwächter erhalten.", rewards = "Ihr bekommt:\n\nGreuelwächter"},
[9211] = {title = "Der Eiswächter", objective = "Mataus der Zornwirker bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 10 Insignien des Kreuzzugs und 30 Gold.", description = "Ah, der Eiswächter. Es ist ein leichter Hauch schützender Magie, der bestimmte Teile der Ausrüstung bedeckt. Der Eiswächter verleiht jenen, die gegen Kreaturen von Frost und Eis kämpfen, erhöhten Schutz vor deren Angriffen.\n\nWie bei allem anderen auch, das vom Zornwirker hergestellt wird, so hat auch dieses Stück seinen Preis - einen Preis, der nicht diskutiert werden kann, wieviel Ihr Euch auch beklagen mögt. Interesse?", progress = "Wäre es nicht für diese Argentumwachen, so wärt Ihr bereits ein Fleck auf diesem Boden.", completion = "&lt;Mataus steckt das Gold in seine Taschen.&gt;\n\nViel Spaß mit den Reparaturkoten, &lt;Volk&gt;. Naxxramas geht recht 'lieblos' mit Außenstehenden um.", rewards = "Ihr bekommt:\n\nEiswächter"},
[9213] = {title = "Der Schattenwächter", objective = "Mataus der Zornwirker bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 10 Insignien des Kreuzzugs und 30 Gold.", description = "Das Machwerk eines Genies! Wie beim Eiswächter, ist es auch beim Schattenwächter ein leichter Hauch schützender Magie, der bestimmte Teile der Ausrüstung bedeckt. Der Schattenwächter wird Euch genauso wie der Eiswächter einen guten Batzen Geld kosten.\n\n<Mataus streckt seine Hand aus und reibt seine Finger aneinander.>\n\nInteresse?Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchattenwächter"},
[9221] = {title = "Überragende Kampfausrüstung - Freund der Dämmerung", objective = "Für 30 Insignien der Dämmerung und 30 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen freundlichen Ruf genießt, muss sich bei Käufen mit einem hohen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand der FrömmigkeitBand der ResolutionVerimondes letzter AuswegVorratstascheGamaschen des SeuchenjägersGeweihter Lederhelm"},
[9222] = {title = "Epische Kampfausrüstung - Freund der Dämmerung", objective = "Für 110 Insignien der Dämmerung und 110 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen freundlichen Ruf genießt, muss sich bei Käufen mit einem extrem hohen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAmulett der DämmerungArmschienen der HoffnungArmschienen der TäuschungMedaillon der DämmerungTalisman der ÜberlegenheitDer Läuterer"},
[9223] = {title = "Überragende Kampfausrüstung - Wohlwollen der Dämmerung", objective = "Für 20 Insignien der Dämmerung und 20 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen wohlwollenden Ruf genießt, muss sich bei Käufen mit einem ziemlich unerschwinglichen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand der FrömmigkeitBand der ResolutionVerimondes letzter AuswegVorratstascheGamaschen des SeuchenjägersGeweihter Lederhelm"},
[9224] = {title = "Epische Kampfausrüstung - Wohlwollen der Dämmerung", objective = "Für 75 Insignien der Dämmerung und 75 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen wohlwollenden Ruf genießt, muss sich bei Käufen mit einem extrem unerschwinglichen Aufpreis abfinden. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAmulett der DämmerungArmschienen der HoffnungArmschienen der TäuschungMedaillon der DämmerungTalisman der ÜberlegenheitDer Läuterer"},
[9225] = {title = "Epische Kampfausrüstung - Respekt der Dämmerung", objective = "Für 45 Insignien der Dämmerung und 45 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nIch muss Euch warnen, wer bei der Argentumdämmerung einen respektvollen Ruf genießt, muss für epische Gegenstände noch immer einen sehr hohen Preis bezahlen. Ich würde Euch raten, Euren Ruf bei der Argentumdämmerung erst einmal zu verbessern, bevor Ihr Eure Pläne weiterverfolgt.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAmulett der DämmerungArmschienen der HoffnungArmschienen der TäuschungMedaillon der DämmerungTalisman der ÜberlegenheitDer Läuterer"},
[9226] = {title = "Überragende Kampfausrüstung - Respekt der Dämmerung", objective = "Für 7 Insignien der Dämmerung und 7 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen respektvollen Ruf genießt, kann Gegenstände zu einem recht angemessenem Preis erwerben. Ich würde Euch zu einem Geschäft raten!", progress = "Wählt mit Bedacht. Es gibt keine Rückerstattung.", completion = "Schönen Tag noch, &lt;Name&gt;. Es war ein Vergnügen mit Euch Geschäfte zu machen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand der FrömmigkeitBand der ResolutionVerimondes letzter AuswegVorratstascheGamaschen des SeuchenjägersGeweihter Lederhelm"},
[9227] = {title = "Überragende Kampfausrüstung - Ehrfurcht der Dämmerung", objective = "Für 6 Insignien der Dämmerung und 6 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen ehrfürchtigen Ruf genießt, erhält bei Käufen einen Preisnachlass. Ich würde Euch zu einem Geschäft raten!", progress = "Wählt mit Bedacht. Es gibt keine Rückerstattung.", completion = "Schönen Tag noch, &lt;Name&gt;. Es war ein Vergnügen mit Euch Geschäfte zu machen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand der FrömmigkeitBand der ResolutionVerimondes letzter AuswegVorratstascheGamaschen des SeuchenjägersGeweihter Lederhelm"},
[9228] = {title = "Epische Kampfausrüstung - Ehrfurcht der Dämmerung", objective = "Für 27 Insignien der Dämmerung und 27 Insignien des Kreuzzugs dürft Ihr Euch einen Gegenstand aus den Schatzkammern der Argentumdämmerung aussuchen.", description = "Seid gegrüßt, Freund. Besitzt Ihr Insignien der Dämmerung oder des Kreuzzugs, die Ihr gerne für sehr mächtige Gegenstände einlösen würdet?\n\nWer bei der Argentumdämmerung einen ehrfürchtigen Ruf genießt, erhält bei Käufen garantiert den besten Preisnachlass. Ich würde Euch zu einem Geschäft raten.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAmulett der DämmerungArmschienen der HoffnungArmschienen der TäuschungMedaillon der DämmerungTalisman der ÜberlegenheitDer Läuterer"},
[9229] = {title = "Ramaladnis Schicksal", objective = "Betretet Naxxramas und bringt Ramaladnis Schicksal in Erfahrung.", description = "Ramaladni war ein Krieger der Bruderschaft; er war ein Schüler von Hochlord Mograine bevor die Dämmerung überhaupt existierte! Als ihn die Nachricht von Mograines Tod erreichte, wurde er von Wut und Hass überwältigt.\n\nVersteht bitte, <Name>, wenn Wut und der Drang nach Vergeltung von jemandem Besitz ergreifen, hört er auf, ein Mensch zu sein, und wird stattdessen zur Verkörperung der Emotionen, die ihn beherrschen. Und so geschah es, dass Ramaladni, beseelt vom Geist der Vergeltung, Naxxramas betrat um Rache zu üben... und niemals zurückkehrte.\n\nBetretet Naxxramas und findet heraus, was mit Ramaladni geschah.", progress = "Gibt es Neuigkeiten über Ramaladni?", completion = "Es ist sein Ring! Aber er ist zerstört. Ihr habt keine weiteren Hinweise auf Ramaladni gefunden?\n\n&lt;Korfax verzieht das Gesicht.&gt;\n\nDas verheißt nichts Gutes für Ramaladni. Der Ring jedoch ... er könnte noch nützlich sein.", rewards = "Ihr bekommt:\n\n"},
[9230] = {title = "Ramaladnis eisiger Griff", objective = "Korfax in der Kapelle des hoffnungsvollen Lichtes möchte, dass Ihr ihm 1 gefrorene Rune, 1 blauen Saphir und 1 Arkanitbarren bringt.", description = "Den Ring wiederherzustellen, scheint eine ziemliche Herausforderung zu sein, <Name>. Seht ihr, er wurde hergestellt aus Runen, die sich in Bauwerken der Geißel finden - in Bauwerken wie Naxxramas. Es könnten noch weitere Materialien gebraucht werden, aber Eure Hauptsorge sollte es sein, diese gefrorenen Runen zu beschaffen. Ich kann dem Ring seinen alten Glanz zurückgeben, wenn ihr mir bringt, was ich dazu benötige.", progress = "Gefrorene Runen findet man wahrscheinlich in Naxxramas.", completion = "Ramaladni selbst könnte es nicht besser gemacht haben! Hier ist der Ring, wie versprochen.", rewards = "Ihr bekommt:\n\nRamaladnis eisiger Griff"},
[9232] = {title = "Das Einzige, das ich kann...", objective = "Handwerker Wilhelm in der Kapelle des hoffnungsvollen Lichts möchte, dass Ihr ihm 2 gefrorene Runen, 2 Essenzen des Wassers, 2 blaue Saphire und 30 Goldstücke bringt.", description = "Ihr haltet Euch für einen Helden der Dämmerung, ja? Ich habe gesehen, wie unsere besten Soldaten von Kel'Thuzads Gefolgsleuten überrannt wurden. Wie könnte jemand, der so ahnungslos ist wie Ihr, in Naxxramas bestehen?\n\n<Wilhelm seufzt.>\n\nPah, was für eine Wahl habe ich denn? Ihr seid das Beste, das ich zur Verfügung habe; warum sollte ich Euch nicht helfen?\n\nOmarion hat mir einen Plan hinterlassen. Es ist das Einzige, das ich kann... Ich kann ein paar Varianten dieser Hosen herstellen, Ihr müsst mich nur mit den Materialien versorgen.", progress = "Ihr habt nicht zufällig Omarion getroffen?", completion = "&lt;Wilhelm wischt sich den Schweiß von der Stirn.&gt;\n\nDas war ein hartes Stück Arbeit! Ich hoffe, die Hose gefällt Euch, &lt;Klasse&gt;. Zumindest werdet ihr jetzt in einer sauberen Hose sterben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGletschergamaschenEisfluchgamaschenEisschuppengamaschenPolargamaschen"},
[9233] = {title = "Omarions Leitfaden", objective = "Bringt Omarions Leitfaden zu Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Wilhelm,\n\nsolltet Ihr das hier lesen, bin ich bereits tot - endlich. Ihr sollt wissen, dass meine letzten Gedanken vor dem Tod Euch und Eurer Unfähigkeit als Handwerker galten. Unglücklicherweise besitzt der Überbringer dieses Leitfadens noch weniger Geschick als Ihr.\n\nZu dem Buch: Es beinhaltet meine letzten Anleitungen. Fertigt dem Überbringer dieses Leitfadens an, was immer dieser wünschen mag. Ich bin mir sicher, dass Ihr ein saftiges Honorar für Eure Dienste verlangen werdet, denn im Grunde seid Ihr nun mal ein Mistkerl.\n\nVerachtungsvoll,\n\nOmarion", progress = "Ist es das, was ich denke?\n\n<Wilhelm scheint begierig zu sein.>", completion = "Hey, der muss ja nicht ganz dicht gewesen sein, als er das geschrieben hat! Omarion und ich - wir waren die dicksten Freunde!\n\nEgal, dies hier eröffnet mit Sicherheit ein paar neue Möglichkeiten, &lt;Name&gt;. Ich kann jetzt mehr Gegenstände anfertigen - natürlich gegen eine kleine Gebühr und Kosten für das Material.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nOmarions Geheimnisse"},
[9234] = {title = "Eisfluchstulpen", objective = "Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 5 gefrorene Runen, 12 Thoriumbarren, 2 Arkanitbarren, 2 Essenzen des Wassers und 200 Gold.", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, Eisfluchstulpen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisfluchstulpen"},
[9235] = {title = "Eisflucharmschienen", objective = "Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 4 gefrorene Runen, 12 Thoriumbarren, 2 Arkanitbarren, 2 Essenzen des Wassers und 200 Gold.", description = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, Eisflucharmschienen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisflucharmschienen"},
