[9244] = {title = "Eisschuppenarmschienen", objective = "Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 4 gefrorene Runen, 16 schwere Skorpidschuppen, 5 Essenzen des Wassers, 3 geschmeidige unverwüstliche Bälge und 200 Gold.", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, Eisschuppenarmschienen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisschuppenarmschienen"},
[9245] = {title = "Eisschuppenstulpen", objective = "Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 5 gefrorene Runen, 16 schwere Skorpidschuppen, 5 Essenzen des Wassers, 3 geschmeidige unverwüstliche Bälge und 200 Gold.", description = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, Eisschuppenstulpen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisschuppenstulpen"},
[9246] = {title = "Eisschuppenbrustplatte", objective = "Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 8 gefrorene Runen, 24 schwere Skorpidschuppen, 7 Essenzen des Wassers, 5 geschmeidige unverwüstliche Bälge und 300 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein.", description = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, eine Eisschuppenbrustplatte herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisschuppenbrustplatte"},
[9247] = {title = "Der Ruf des Bewahrers", objective = "Bringt den Brief vom Bewahrer der Schriften zu ihm, in die Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "<Name>,\n\nIn der Vergangenheit habt Ihr die Interessen der Argentumdämmerung nach bestem Gewissen und Können gewahrt. In einer Zeit der größten Not, ertönt wieder einmal der Ruf zu den Waffen.\n\n<Name>, solltet Ihr uns unterstützen wollen, meldet Euch bitte bei dem Bewahrer der Schriften an der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ah, <Name>, es ist schön Euch zu sehen.", completion = "Schon dadurch, dass Ihr unseren Ruf beantwortet habt, stehen wir in Eurer Schuld, &lt;Name&gt;. Die Argentumdämmerung ist sich sicher, dass Euer leuchtendes Beispiel auch den anderen Kämpfern gezeigt hat, wie man die Geißel zurückwirft!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesegnetes ZauberölGeweihter Wetzstein\n\nIhr bekommt außerdem:\n\n"},
[9248] = {title = "Eine bescheidene Darbringung", objective = "Aurel Goldleaf auf Burg Cenarius in Silithus möchte, dass Ihr ihr 1 abyssisches Szepter bringt. Euer Ruf bei dem Zirkel des Cenarius muss außerdem wohlwollend sein.", description = "Ishnu-alah, <Volk>. Bringt mir den Beweis für den Tod eines Lords des abyssischen Rates und ich werde Euch mit einem Gegenstand entlohnen, der Euch bei Euren Kämpfen gegen die Qiraji von großem Nutzen sein wird.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBand des Cenarius"},
[9249] = {title = "40 Lose - Bauplan: Dampfpanzersteuerung", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBauplan: Dampfpanzersteuerung"},
[9250] = {title = "Grundstab von Atiesh", objective = "Findet jemanden, der Euch dabei hilft, die letzten beiden Teile des Stabs zu finden und das Böse daraus zu vertreiben.", description = "Mit dem Grundstab ist bereits der wichtigste Teil von Atiesh vervollständigt worden. Es fehlen lediglich noch Stabkopf und -fuß. Außerdem gibt es noch ein kleineres Problem bezüglich des Stabs und seiner Rolle hinsichtlich Sargeras' Lenkung zum Bösen.\n\nFindet jemanden, der Euch beim Aufspüren der noch fehlenden Teile und beim Austreiben alles Verderbten aus dem Hohestab zur Seite steht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[9251] = {title = "Atiesh, der korrumpierte Hohestab", objective = "Anachronos in den Höhlen der Zeit in Tanaris möchte den Stabkopf und -fuß von Atiesh.", description = "Ihr fragt Euch, warum Ihr noch immer am Leben seid? Schließlich haltet Ihr einen Gegenstand in Euren Händen, der vom Bösen erfüllt ist. Die Antwort ist nicht eindeutig, <Name>. Ich tue nur, was ich tun muss.\n\nKel'Thuzad sitzt auf seinem Thron hoch oben in Naxxramas, konspiriert... Er sucht was Ihr besitzt und besitzt was Ihr sucht.\n\nWas den Stabfuß angeht, er wurde von dem Zwerg, Brann Bronzebeard, gehalten, als er Ahn'Qiraj betrat. Er hat Ahn'Qiraj zwar verlassen, den Stabfuß von Atiesh jedoch zurückgelassen.\n\nSolltet Ihr beim Wiedererlangen der Stücke Erfolg haben, kehrt mit ihnen zu mir zurück.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[9257] = {title = "Atiesh, Hohestab des Wächters", objective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, <Name>. Ihr seid einem alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert and kehrt zu mir zurück.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAtiesh, Hohestab des Wächters"},
[9259] = {title = "Verrat am Blutsegel", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRuf - Booty Bay +500"},
[9260] = {title = "Erforscht die Geißel von Stormwind", objective = "Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren Stormwinds. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an.", description = "Die Geißel hat genau vor unserer Nase Stellung genommen; wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Stormwind gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren Energie genauso leuchtet wie die, die die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Merzt diese entarteten Kreaturen aus, wenn Ihr schon mal dabei seid. Ich erwarte Euch mit Beweisen für Eure Taten und Neuigkeiten von Euren Erkundungen zurück. Ihr werdet nicht leer ausgehen. Zieht jetzt los!", progress = "Habt Ihr bereits Nachforschungen angestellt? Uns bleibt keine Zeit zum Trödeln!", completion = "Hmm. Was Eure Nachforschungen betrifft, so scheinen diese Stimmen in den Kreisen... sie scheinen einer Art Kommunikation zu dienen. Mich schaudert es bei dem Gedanken, welch abartige Geister mit Hilfe dieser Magie angerufen werden. Nun ja, Ihr scheint ja in einem Stück davongekommen zu sein. Die Argentumdämmerung schätzt Eure Bemühungen.", rewards = "Ihr bekommt:\n\n"},
[9261] = {title = "Erforscht die Geißel von Ironforge", objective = "Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren von Ironforge. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an.", description = "Die Geißel hat genau vor unserer Nase Stellung genommen; wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Ironforge gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren Energie genauso leuchtet wie die, die die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Merzt diese entarteten Kreaturen aus, wenn Ihr schon mal dabei seid. Ich erwarte Euch mit Beweisen für Eure Taten und Neuigkeiten von Euren Erkundungen zurück. Ihr werdet nicht leer ausgehen. Zieht jetzt los!", progress = "Habt Ihr bereits Nachforschungen angestellt? Uns bleibt keine Zeit zum Trödeln!", completion = "Hmm. Was Eure Nachforschungen betrifft, so scheinen diese Stimmen in den Kreisen... sie scheinen einer Art Kommunikation zu dienen. Mich schaudert es bei dem Gedanken, welch abartige Geister mit Hilfe dieser Magie angerufen werden. Nun ja, Ihr scheint ja in einem Stück davongekommen zu sein. Die Argentumdämmerung schätzt Eure Bemühungen.", rewards = "Ihr bekommt:\n\n"},
[9262] = {title = "Erforscht die Geißel von Darnassus", objective = "Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren von Darnassus. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an.", description = "Die Geißel hat genau vor unserer Nase Stellung genommen; wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Darnassus gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren Energie genauso leuchtet wie die, die die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Merzt diese entarteten Kreaturen aus, wenn Ihr schon mal dabei seid. Ich erwarte Euch mit Beweisen für Eure Taten und Neuigkeiten von Euren Erkundungen zurück. Ihr werdet nicht leer ausgehen. Zieht jetzt los!", progress = "Habt Ihr bereits Nachforschungen angestellt? Uns bleibt keine Zeit zum Trödeln!", completion = "Hmm. Was Eure Nachforschungen betrifft, so scheinen diese Stimmen in den Kreisen... sie scheinen einer Art Kommunikation zu dienen. Mich schaudert es bei dem Gedanken, welch abartige Geister mit Hilfe dieser Magie angerufen werden. Nun ja, Ihr scheint ja in einem Stück davongekommen zu sein. Die Argentumdämmerung schätzt Eure Bemühungen.", rewards = "Ihr bekommt:\n\n"},
[9263] = {title = "Erforscht die Geißel von Orgrimmar", objective = "Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren von Orgrimmar. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an.", description = "Die Geißel hat genau vor unserer Nase Stellung genommen; wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Orgrimmar gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren Energie genauso leuchtet wie die, die die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Merzt diese entarteten Kreaturen aus, wenn Ihr schon mal dabei seid. Ich erwarte Euch mit Beweisen für Eure Taten und Neuigkeiten von Euren Erkundungen zurück. Ihr werdet nicht leer ausgehen. Zieht jetzt los!", progress = "Habt Ihr bereits Nachforschungen angestellt? Uns bleibt keine Zeit zum Trödeln!", completion = "Hmm. Was Eure Nachforschungen betrifft, so scheinen diese Stimmen in den Kreisen... sie scheinen einer Art Kommunikation zu dienen. Mich schaudert es bei dem Gedanken, welch abartige Geister mit Hilfe dieser Magie angerufen werden. Nun ja, Ihr scheint ja in einem Stück davongekommen zu sein. Die Argentumdämmerung schätzt Eure Bemühungen.", rewards = "Ihr bekommt:\n\n"},
[9264] = {title = "Erforscht die Geißel von Thunder Bluff", objective = "Beschafft Euch drei dunkle nekrotische Steine von der Geißel außerhalb von Thunder Bluff. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an.", description = "Die Geißel hat genau vor unserer Nase Stellung genommen; wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Thunder Bluff gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren Energie genauso leuchtet wie die, die die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Merzt diese entarteten Kreaturen aus, wenn Ihr schon mal dabei seid. Ich erwarte Euch mit Beweisen für Eure Taten und Neuigkeiten von Euren Erkundungen zurück. Ihr werdet nicht leer ausgehen. Zieht jetzt los!", progress = "Habt Ihr bereits Nachforschungen angestellt? Uns bleibt keine Zeit zum Trödeln!", completion = "Hmm. Was Eure Nachforschungen betrifft, so scheinen diese Stimmen in den Kreisen... sie scheinen einer Art Kommunikation zu dienen. Mich schaudert es bei dem Gedanken, welch abartige Geister mit Hilfe dieser Magie angerufen werden. Nun ja, Ihr scheint ja in einem Stück davongekommen zu sein. Die Argentumdämmerung schätzt Eure Bemühungen.", rewards = "Ihr bekommt:\n\n"},
[9265] = {title = "Erforscht die Geißel von Undercity", objective = "Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren von Undercity. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an.", description = "Die Geißel hat genau vor unserer Nase Stellung genommen; wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Undercity gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren Energie genauso leuchtet wie die, die die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Merzt diese entarteten Kreaturen aus, wenn Ihr schon mal dabei seid. Ich erwarte Euch mit Beweisen für Eure Taten und Neuigkeiten von Euren Erkundungen zurück. Ihr werdet nicht leer ausgehen. Zieht jetzt los!", progress = "Habt Ihr bereits Nachforschungen angestellt? Uns bleibt keine Zeit zum Trödeln!", completion = "Hmm. Was Eure Nachforschungen betrifft, so scheinen diese Stimmen in den Kreisen... sie scheinen einer Art Kommunikation zu dienen. Mich schaudert es bei dem Gedanken, welch abartige Geister mit Hilfe dieser Magie angerufen werden. Nun ja, Ihr scheint ja in einem Stück davongekommen zu sein. Die Argentumdämmerung schätzt Eure Bemühungen.", rewards = "Ihr bekommt:\n\n"},
[9266] = {title = "Wiedergutmachung", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRuf - Everlook +500"},
[9267] = {title = "Heilen alter Wunden", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRuf - Ratchet +500"},
[9268] = {title = "Krieg zur See", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRuf - Gadgetzan +500"},
[9269] = {title = "Atiesh, Hohestab des Wächters", objective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, <Name>. Ihr seid einem alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert and kehrt zu mir zurück.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAtiesh, Hohestab des Wächters"},
[9270] = {title = "Atiesh, Hohestab des Wächters", objective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, <Name>. Ihr seid einem alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert and kehrt zu mir zurück.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAtiesh, Hohestab des Wächters"},
[9271] = {title = "Atiesh, Hohestab des Wächters", objective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, <Name>. Ihr seid einem alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert and kehrt zu mir zurück.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAtiesh, Hohestab des Wächters"},
[9272] = {title = "Kleider machen Seebären", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nUniform der Bukaniere"},
[9273] = {title = "Redeem iCoke Prize Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisbärenhalsband"},
[9292] = {title = "Gesprungener nekrotischer Kristall", objective = "Bringt den gesprungenen nekrotischen Kristall zu Lieutenant Orrin außerhalb der Tore von Stormwind.", description = "Ihr entdeckt beim Körper der toten Monstrosität einen gesprungenen Kristall, der langsam mit nekrotischer Energie pulsiert.", progress = "Ja, was gibt's?", completion = "Hm, Ihr habt das beim Körper einer der Monstrositäten gefunden?\n\nWir haben von Basislagern der Nekropole gehört, die die Geißel heraufbeschworen hat. Ich vermute, dass sie eines davon innerhalb von Stormwind errichten wollten. Es ist gut, dass sie damit erfolglos waren.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesegnetes ZauberölGeweihter Wetzstein"},
[9295] = {title = "Brief von der Front", objective = "Bringt den zerfledderten Brief zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", rewards = "Ihr bekommt:\n\n"},
[9296] = {title = "reuse", objective = "Deliver the Dim Necrotic Stone to SOMEONE.", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", progress = nil, completion = nil, rewards = nil},
[9297] = {title = "reuse", objective = "Deliver the Dim Necrotic Stone to SOMEONE.", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", progress = nil, completion = nil, rewards = nil},
[9298] = {title = "reuse", objective = "Deliver the Dim Necrotic Stone to SOMEONE.", description = "This stone radiates a dark energy. You should deliver it to SOMEONE.", progress = nil, completion = nil, rewards = nil},
