[9300] = {title = "Seite von der Front", objective = "Bringt die zerfranste Seite zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", rewards = "Ihr bekommt:\n\n"},
[9301] = {title = "Umschlag von der Front", objective = "Bringt den blutbefleckten Umschlag zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", rewards = "Ihr bekommt:\n\n"},
[9302] = {title = "Schreiben von der Front", objective = "Bringt das zerknitterte Schreiben zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", rewards = "Ihr bekommt:\n\n"},
[9304] = {title = "Dokument von der Front", objective = "Bringt das verschmierte Dokument zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", rewards = "Ihr bekommt:\n\n"},
[9310] = {title = "Schwacher nekrotischer Kristall", objective = "Bringt den schwachen nekrotischen Kristall zu Lieutenant Rukag im Hof von Undercity.", description = "Ihr findet beim Körper der toten Kreatur einen Kristall, der schwache nekrotische Energie ausstrahlt.", progress = "Kann ich Euch irgendwie weiterhelfen?", completion = "Ihr sagt, dass Ihr das bei einer der Kreaturen gefunden habt, die die Stadt angreifen?\n\nWir haben von Basislagern der Nekropole gehört, die die Geißel heraufbeschworen hat. Ich vermute, dass sie eines davon innerhalb von Undercity errichten wollten. Wir müssen zukünftig sehr vorsichtig sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesegnetes ZauberölGeweihter Wetzstein"},
[9317] = {title = "Geweihte Wetzsteine", objective = "Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein.", description = nil, progress = "Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein.", completion = "Danke, &lt;Name&gt;. Hier ist Euer geweihter Wetzstein. Verwendet ihn weise.", rewards = "Ihr bekommt:\n\nGeweihter Wetzstein"},
[9318] = {title = "Gesegnetes Zauberöl", objective = "Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben.", description = nil, progress = "Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben.", completion = "Ich hoffe, dass Ihr in Euren zukünftigen Schlachten davon Gebrauch machen könnt.", rewards = "Ihr bekommt:\n\nGesegnetes Zauberöl"},
[9319] = {title = "Licht im Dunkeln", objective = "Findet und berührt die Freudenfeuer innerhalb der Blackrockspitze, dem Düsterbruch, Scholomance und Stratholme. Kehrt dann zum Flammenbewahrer zurück.", description = "Wir sind nicht die Einzigen, die dieses Fest feiern, <Name>. Die Flamme ist ein wichtiger Bestandteil aller Lebewesen, aller Kulturen. Selbst an den dunkelsten Orten beginnen die Feuer zu leuchten.\n\nWenn Ihr dergleichen sehen möchtet, so wagt Euch in die Tiefe. Sucht nach den Freudenfeuern in Stratholme, Scholomance, bei den Ogern des Düsterbruchs und in den Hallen der Blackrockspitze selbst. Ich erwarte Eure Rückkehr.", progress = "Habt Ihr Euch im Dunkeln zurechtgefunden?", completion = "Euer Wesen erstrahlt mit der Energie der Flammen, die Ihr gefunden habt, &lt;Name&gt;. Das Feuer, mit dem Ihr in Berührung gekommen seid,  ist mächtig. Mit dem richtigen Wissen, kann man sich diese Macht zu Nutzen machen...\n\n\n\nAh! Soweit so gut. Ich hoffe dies wird Euren Weg erleuchten, wohin immer Ihr auch gehen mögt.", rewards = "Ihr bekommt:\n\nEingefangene FlammeBrandblüte"},
[9320] = {title = "Erheblicher Manatrank", objective = "Neben unseren anderen Vorräten verfügen wir auch über eine gewisse Zahl an erheblichen Manatränken, die für Euch von Nutzen sein könnten. Ich werde Euch einen im Tausch gegen fünfzehn nekrotische Runen geben.", description = nil, progress = "Neben unseren anderen Vorräten verfügen wir auch über eine gewisse Zahl an erheblichen Manatränken, die für Euch von Nutzen sein könnten. Ich werde Euch einen im Tausch gegen fünfzehn nekrotische Runen geben.", completion = "Bitte sehr, &lt;Name&gt;. Seid vorsichtig da draußen. Wir sind zu wenige, als dass wir uns viele Verluste auf dem Schlachtfeld leisten könnten.", rewards = "Ihr bekommt:\n\nErheblicher Manatrank"},
[9321] = {title = "Erheblicher Heiltrank", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nErheblicher Heiltrank"},
[9322] = {title = "Glühende Feuer in Kalimdor", objective = "Sucht die Lager des Sonnenwendfests in Azshara, Silithus, dem Un'Goro-Krater und Winterspring auf. Kehrt dann zum Flammenbewahrer zurück.", description = "Die Freudenfeuer des Sonnenwendfests werden überall in Azeroth gefeiert, die mannigfaltigen Länder Kalimdors sind dabei keine Ausnahme. Ihr scheint mir tauglich für eine Reise -- wie wäre es mit einem Ausflug?\n\nDas Sonnenwendfest ist erst dann ein Ereignis, wenn man die blau glühenden Feuer in der Welt gesehen hat. Die Feiernden haben Feuer im eisigen Westen von Winterspring, im Nordosten von Azshara, in der Nähe der Heldenwacht in Silithus und beim Eingang zum üppigen Un'Goro-Krater entzündet. Kehrt zu mir zurück, sobald Ihr die Reise beendet habt.", progress = nil, completion = "Euer Geist erstrahlt mit der Wärme der Feuer Kalimdors. Ist die Hitze nicht anregend?\n\nWenn die Macht von Euch schwindet, könnte Euch dies hier vielleicht dabei helfen, das Ganze wieder aufleben zu lassen.", rewards = "Ihr bekommt:\n\nAschenarmschienenBrandblüte"},
[9323] = {title = "Glühende Feuer in den östlichen Königreichen", objective = "Reist zu den Lagern des Sonnenwendfests in den verwüsteten Landen, den östlichen Pestländern, dem Hinterland und der sengenden Schlucht. Kehrt dann zum Flammenbewahrer zurück.", description = "Das Fest der Flamme ist im ganzen Land verbreitet, <Klasse>. Kein Ort bleibt von der Wärme dieses Ereignisses unberührt, und die prächtigsten Feuer lodern in einem strahlenden Blau. Sucht nach ihnen.\n\nEines befindet sich genau nördlich von der Blackrockspitze. Die anderen liegen tief im Innern der östlichen Pestländer, in der Nähe eines verfallenen Dorfes; entlang der Straße, die zu den Klippen im bergigen Hinterland führt, und auf dem Weg zu dem Dunklen Portal in den verwüsteten Landen.\n\nKehrt anschließend zu mir zurück.", progress = nil, completion = "Ah, da seid Ihr also. Etwas erschöpfter, ein wenig schmutziger, aber erleuchtet! Die Wärme berührt und vereint uns alle während dieser Zeit. Euer Wesen erstrahlt mit der Macht der Feuer, die Ihr berührt habt.\n\nAh, ich vermute, dass Erleuchtung heutzutage wohl eher als eine armselige Belohnung für eine Aufgabe wie diese angesehen wird. Nehmt dies hier, bitte, und genießt das Fest.", rewards = "Ihr bekommt:\n\nMantel des FeuerfestsBrandblüte"},
[9324] = {title = "Raubt die Flamme von Orgrimmar", objective = "Bringt die Flamme von Orgrimmar zu dem Meister der Lehren.", description = "Die Flamme, die aus dem Zentrum von Orgrimmar entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", progress = "Ihr glüht ja förmlich, <Volk>. Was habt Ihr da?", completion = "Was ist das? Sollte ich mich nicht täuschen, so wurde diese Flamme aus dem Herzen Orgrimmars entwendet! Die sengende Hitze spiegelt die kämpferischen Herzen der Orcs und Trolle wider. Was für ein Gewinn für unsere Sammlung! Wie mutig Ihr doch seid - sich in den Bau des Feindes einzuschleichen, um die heilige Flamme zu erlangen!\n\nIch frage mich, welch' Mächte sich in den anderen Städten versteckt halten...", rewards = "Ihr bekommt:\n\nBrandblüte"},
[9325] = {title = "Raubt die Flamme von Thunder Bluff", objective = "Bringt die Flamme von Thunder Bluff zu dem Meister der Lehren.", description = "Die Flamme, die dem Schamanen von Thunder Bluff entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", progress = "Ihr glüht ja förmlich, <Volk>. Was habt Ihr da?", completion = "Sollte mich meine Vermutung nicht täuschen, so wurde diese Flamme aus Thunder Bluff entwendet! Die Macht der Geister ist deutlich hörbar! Ihr seid ganz schön gerissen, &lt;Name&gt;. Nehmt dies als gerechte Anerkennung Eures Könnens. Hm, hätten wir doch auch all die Flammen von den anderen Städten...", rewards = "Ihr bekommt:\n\nFeuriges FestgebräuBrandblüte"},
[9326] = {title = "Raubt die Flamme von Undercity", objective = "Bringt die Flamme von Undercity zu dem Meister der Lehren.", description = "Die Flamme, die aus den Ruinen über Undercity entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", progress = "Ihr glüht ja förmlich, <Volk>. Was habt Ihr da?", completion = "Hm... was für ein seltsames Feuer! Es flackert schwach, ist fast nur noch ein Glühen, aber die Hitze ist stark. Ihr sagt, dass Ihr es aus Undercity entwendet habt? Faszinierend. Wer weiß, was wir mit den Flammen aller drei Städte erreichen könnten?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHolunderbeerenkuchenFeuergeröstetes BrötchenSonnenwendwürstchenGetoastetes Smorc\n\nIhr bekommt außerdem:\n\nBrandblüte"},
[9330] = {title = "Raubt die Flamme von Stormwind", objective = "Bringt die Flamme von Stormwind zu dem Geschichtenerzähler.", description = "Die Flamme, die aus dem Zentrum von Stormwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", progress = "Ihr glüht ja förmlich, <Volk>. Was habt Ihr da?", completion = "Also dieses hell leuchtende Feuer... Ihr sagt es kommt aus Stormwind? Bemerkenswert! Das muss ein ziemliches Abenteuer gewesen sein! Ich werde Euch dafür natürlich entlohnen. Solltet Ihr etwas Ähnliches finden, kommt bitte sofort zu mir.", rewards = "Ihr bekommt:\n\nFeuriges FestgebräuBrandblüte"},
[9331] = {title = "Raubt die Flamme von Ironforge", objective = "Bringt die Flamme von Ironforge zu dem Geschichtenerzähler.", description = "Die Flamme, die aus dem Zentrum von Ironforge entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", progress = "Ihr glüht ja förmlich, <Volk>. Was habt Ihr da?", completion = "Diese kraftvolle Flamme muss aus den Hallen von Ironforge stammen; sie ist so unerschütterlich wie die Zwege selbst. Gute Beute, &lt;Name&gt;. Hätte ich nur die Flammen der anderen Städte... naja, macht Euch nichts draus. Hier ist Euer Lohn.", rewards = "Ihr bekommt:\n\nBrandblüte"},
[9332] = {title = "Raubt die Flamme von Darnassus", objective = "Bringt die Flamme von Darnassus zu dem Geschichtenerzähler.", description = "Die Flamme, die von der Küste Teldrassils entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", progress = "Ihr glüht ja förmlich, <Volk>. Was habt Ihr da?", completion = "Dieses Feuer ist mit uraltem Kummer erfüllt, &lt;Name&gt;. Ihr habt es aus dem Herzen Teldrassils, ja? Unglaublich! Hier, als Anerkennung für Euer Können. Kehrt zu mir zurück, falls Ihr etwas Ähnliches finden solltet - ich könnte Verwendung dafür haben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHolunderbeerenkuchenFeuergeröstetes BrötchenSonnenwendwürstchenGetoastetes Smorc\n\nIhr bekommt außerdem:\n\nBrandblüte"},
[9333] = {title = "Handschuhe der Argentumdämmerung", objective = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", description = nil, progress = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Nehmt den von Euch gewählten Handschutz als Dank für Eure Mühen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHandschuhe der UntotenbekämpfungHandlappen des UntotenschlachtensHandschützer des UntotenschlachtensStulpen des Untotenschlachtens"},
[9334] = {title = "Gesegnetes Zauberöl", objective = "Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben.", description = nil, progress = "Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben.", completion = "Ich hoffe, dass Ihr in Euren zukünftigen Schlachten davon Gebrauch machen könnt.", rewards = "Ihr bekommt:\n\nGesegnetes Zauberöl"},
[9335] = {title = "Geweihte Wetzsteine", objective = "Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein.", description = nil, progress = "Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein.", completion = "Danke, &lt;Name&gt;. Hier ist Euer geweihter Wetzstein. Verwendet ihn weise.", rewards = "Ihr bekommt:\n\nGeweihter Wetzstein"},
[9336] = {title = "Erheblicher Heiltrank", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nErheblicher Heiltrank"},
[9337] = {title = "Erheblicher Manatrank", objective = "Neben unseren anderen Vorräten verfügen wir auch über eine gewisse Zahl an erheblichen Manatränken, die für Euch von Nutzen sein könnten. Ich werde Euch einen im Tausch gegen fünfzehn nekrotische Runen geben.", description = nil, progress = "Neben unseren anderen Vorräten verfügen wir auch über eine gewisse Zahl an erheblichen Manatränken, die für Euch von Nutzen sein könnten. Ich werde Euch einen im Tausch gegen fünfzehn nekrotische Runen geben.", completion = "Bitte sehr, &lt;Name&gt;. Seid vorsichtig da draußen. Wir sind zu wenige, als dass wir uns viele Verluste auf dem Schlachtfeld leisten könnten.", rewards = "Ihr bekommt:\n\nErheblicher Manatrank"},
[9338] = {title = "Treue zum Zirkel des Cenarius", objective = "Selbst wenn Ihr keinen Bedarf an unseren materiellen Belohungen habt, sind diese Abzeichen ein Symbol für gegenseitiges Vertrauen und Freundschaft.\n\nBringt sie mir. Außerordentliche Dienste von Euch werde ich sorgsam vermerken.", description = nil, progress = "Selbst wenn Ihr keinen Bedarf an unseren materiellen Belohungen habt, sind diese Abzeichen ein Symbol für gegenseitiges Vertrauen und Freundschaft.\n\nBringt sie mir. Außerordentliche Dienste von Euch werde ich sorgsam vermerken.", completion = "Ihr ehrt uns, &lt;Name&gt;. Eure fortgesetzten Anstrengungen helfen uns, alle Hindernisse zu überwinden.", rewards = nil},
[9339] = {title = "Der Lohn des Diebes", objective = "Bringt die Flamme von Stormwind zu (NAME).Die Flamme, die aus dem unmittelbaren Zentrum von Stormwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber (NAME) könnte vielleicht mehr darüber wissen...", description = "Die Flamme, die aus dem unmittelbaren Zentrum von Stormwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber (NAME) könnte vielleicht mehr darüber wissen...", progress = nil, completion = "Ihr habt Euch heute bewiesen, &lt;Name&gt;.\n\nIch habe zwar nicht viel, das ich Euch geben könnte, aber bitte nehmt diese Krone, eine passende Belohnung für einen Eroberer. Möge sie Euren Weg erleuchten.", rewards = "Ihr bekommt:\n\nKrone des Feuerfests"},
[9341] = {title = "Wappenrock der Argentumdämmerung", objective = "Ihr habt unserer Sache sehr gedient, <Name>. Wenn ihr wollt, kann ich Euch einen Wappenrock der Argentumdämmerung zur Verfügung stellen. Wir sind stolz, Euch zu unseren Verbündeten zu zählen.", description = nil, progress = "Ihr habt unserer Sache sehr gedient, <Name>. Wenn ihr wollt, kann ich Euch einen Wappenrock der Argentumdämmerung zur Verfügung stellen. Wir sind stolz, Euch zu unseren Verbündeten zu zählen.", completion = "Nehmt diesen Wappenrock und tragt ihn mit Stolz. Vielleicht regen Eure Taten auch andere dazu an, zu den Waffen zu greifen und an unserem Kampf gegen die Geißel teilzunehmen.", rewards = "Ihr bekommt:\n\nWappenrock der Argentumdämmerung"},
[9343] = {title = "Wappenrock der Argentumdämmerung", objective = "Ihr habt unserer Sache sehr gedient, <Name>. Wenn ihr wollt, kann ich Euch einen Wappenrock der Argentumdämmerung zur Verfügung stellen. Wir sind stolz, Euch zu unseren Verbündeten zu zählen.", description = nil, progress = "Ihr habt unserer Sache sehr gedient, <Name>. Wenn ihr wollt, kann ich Euch einen Wappenrock der Argentumdämmerung zur Verfügung stellen. Wir sind stolz, Euch zu unseren Verbündeten zu zählen.", completion = "Nehmt diesen Wappenrock und tragt ihn mit Stolz. Vielleicht regen Eure Taten auch andere dazu an, zu den Waffen zu greifen und an unserem Kampf gegen die Geißel teilzunehmen.", rewards = "Ihr bekommt:\n\nWappenrock der Argentumdämmerung"},
[9353] = {title = "Redeem iCoke Gift Box Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSummer Gift Package"},
[9362] = {title = "Kriegsherr Krellian", objective = "Beschafft die prismatische Muschel für Erzmagier Xylem. Der Erzmagier befindet sich in einem Turm auf den Klippen von Azshara.", description = "Die Zeit drängt, <Name>! Meine Orakelsprüche haben eine machtvolle Quelle der Magie offenbart. Ich kann den Turm nicht verlassen und bitte Euch deshalb, diese bösartige Kreatur, die im Besitz dieses Artefakts ist, zu töten.\n\nDer erbärmliche Schwachkopf ist bekannt als Kriegsherr Krellian und versteckt sich hinter seinen Wachen im Tempel von Zin-Malor. Verbrennt ihn zu Asche und nehmt die prismatische Muschel, die er so begehrt, an Euch.", progress = "Es ist keine Zeit zu verlieren! Habt Ihr die Muschel?", completion = "Mh, diese Muschel wird wahrlich von einer seltsamen Aura umgeben. Es scheint geradezu angebracht, dass Eure Belohnung für die Wiederbeschaffung zum Teil daraus besteht, diese magischen Fähigkeiten zu testen...", rewards = "Ihr bekommt:\n\n"},
[9364] = {title = "Gespaltene Magie", objective = "Verwandelt die Grollflossen von Azshara und tötet die Kopien, die einige Sekunden später auftauchen. Wenn Ihr 50 verwandelte Kopien vernichtet habt, kehrt zu Erzmagier Xylem in Azshara zurück.", description = "Meine Untersuchungen haben den einzigartigen Zweck für die prismatische Muschel enthüllt.\n\nGreift die Grollflossen von Azshara mit Verwandlungszaubern an und tragt dabei diese Muschel bei Euch. Wenn Ihr einen Moment wartet, wird die chaotische Aura der Muschel dafür sorgen, dass sie sich für eine kurze Zeit in mehrere kleinere Versionen aufspalten. Tötet diese Kopien so schnell wie möglich, und deren gespaltene Essenzen werden in der Muschel gesammelt.\n\nKehrt zu mir zurück, sobald die Muschel gefüllt ist.", progress = "Habt Ihr die Magie eingesammelt?", completion = "Wunderbar! Prächtig!\n\nNun sind wir in der Lage, diese Magie zu einem neuen Zauber zu formen. Seht!", rewards = "Ihr erlernt:\n\nVerwandlung\n\nDer folgende Zauber wird auf euch gewirkt:\n\nVerwandlung: Schwein\n\nIhr bekommt außerdem:\n\n"},
[9365] = {title = "Der Lohn des Diebes", objective = "Bringt die Flamme von Stormwind zu (NAME).Die Flamme, die aus dem unmittelbaren Zentrum von Stormwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber (NAME) könnte vielleicht mehr darüber wissen...Ihr bekommt:\n\n", description = "Die Flamme, die aus dem unmittelbaren Zentrum von Stormwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber (NAME) könnte vielleicht mehr darüber wissen...Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKrone des Feuerfests"},
[9367] = {title = "Das Fest des Feuers", objective = "Wärmt Euch an den Freudenfeuern in Stormwind, Ironforge und Darnassus. Sprecht anschließend mit einem Meister der Lehren innerhalb der Hauptstädte.", description = "Die Zeit des Sonnenwendfests ist wieder angebrochen!\n\nJedes Jahr werden, wie die Tradition es verlangt, Flammenbewahrer auserkoren, die die Freudenfeuer in unseren Hauptstädten hüten. Auch wenn Feuer in ganz Azeroth brennen, so müssen unsere stets die heißesten und hellsten von allen sein, um dieser Zeit im Jahr ausreichend Ehrerbietung zu erweisen.\n\nIch hätte da übrigens eine Aufgabe für Euch. Mir ist noch nicht zu Ohren gekommen, ob die Feuer in allen Hauptstädten auch wirklich ordentlich brennen. Reist selbst dorthin und wärmt Euch im Schein der Flammen - überzeugt Euch, dass sie ausreichend heiß sind!", progress = nil, completion = "Ausgezeichnet! Scheinbar haben wir dieses Jahr pflichtgetreue Flammenbewahrer ernannt, wenn die Freudenfeuer so herrlich brennen, wie Ihr es berichtet. Danke, dass Ihr der Sache für mich nachgegangen seid. Hier, nehmt dies als kleines Zeichen für meine Wertschätzung.", rewards = "Ihr bekommt:\n\nBrandblüteFeuriges Festgebräu"},
[9368] = {title = "Das Fest des Feuers", objective = "Wärmt Euch an den Freudenfeuern in Orgrimmar, Thunder Bluff und Undercity. Sprecht anschließend mit einem Geschichtenerzähler innerhalb der Hauptstädte.", description = "Die Zeit des Sonnenwendfests ist wieder angebrochen!\n\nJedes Jahr werden, wie die Tradition es verlangt, Flammenbewahrer auserkoren, die die Freudenfeuer in unseren Hauptstädten hüten. Auch wenn Feuer in ganz Azeroth brennen, so müssen unsere stets die heißesten und hellsten von allen sein, um dieser Zeit im Jahr ausreichend Ehrerbietung zu erweisen.\n\nIch hätte da übrigens eine Aufgabe für Euch. Mir ist noch nicht zu Ohren gekommen, ob die Feuer in allen Hauptstädten auch wirklich ordentlich brennen. Reist selbst dorthin und wärmt Euch im Schein der Flammen - überzeugt Euch, dass sie ausreichend heiß sind!", progress = "Brennen alle Feuer?", completion = "Ausgezeichnet! Scheinbar haben wir dieses Jahr pflichtgetreue Flammenbewahrer ernannt, wenn die Freudenfeuer so herrlich brennen, wie Ihr es berichtet. Danke, dass Ihr der Sache für mich nachgegangen seid. Hier, nehmt dies als kleines Zeichen für meine Wertschätzung.", rewards = "Ihr bekommt:\n\nBrandblüteFeuriges Festgebräu"},
[9386] = {title = "Licht im Dunkeln", objective = "Findet und berührt die Freudenfeuer innerhalb der Blackrockspitze, dem Düsterbruch, Scholomance und Stratholme. Sprecht dann mit dem Flammenbewahrer.", description = "Ihr seid ziemlich eifrig, oder? Solltet Ihr Euch noch einmal in die Tiefen wagen, so bin ich gerne bereit, Euch dafür zu belohnen.\n\nSucht die Freudenfeuer in Stratholme, Scholomance, dem Düsterbruch und den Hallen der Blackrockspitze auf. Ich erwarte Eure Rückkehr, <Name>.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBrandblüte"},
[9388] = {title = "Lodernde Flammen in Kalimdor", objective = "Sucht die Freudenfeuer in Ashenvale, dem Brachland, der Dunkelküste und dem Steinkrallengebirge auf. Sprecht anschließend mit dem Flammenbewahrer.", description = "Heute lodern zahlreiche Flammen in der Welt, <Name>. Die Feuer, die am schwierigsten zu unterhalten sind, leuchten grün; werden sie nicht ständig beaufsichtigt, brennen sie nicht lange. Versichert Euch für unseren Flammenbewahrer, dass die Smaragdfeuer in Kalimdor auch weiterhin lodern, eh?\n\nIhr findet sie in der Nähe von Ratchet im Brachland, unweit der Meistergleve in Dunkelküste, im Wald von Ashenvale bei der Brücke nahe des Außenpostens der Silverwing und entlang der Hauptstraße im Steinkrallengebirge, in der Nähe der Straße, die zur Scherwindklippe führt.", progress = nil, completion = "Ahhh, sie brennen also noch. Das freut mich; es wäre nicht gut, wenn die Feuer vorzeitig erlöschen würden. Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Nehmt dies mit meinem Segen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHolunderbeerenkuchenFeuergeröstetes BrötchenSonnenwendwürstchenGetoastetes Smorc\n\nIhr bekommt außerdem:\n\n"},
[9389] = {title = "Lodernde Flammen in den östlichen Königreichen", objective = "Sucht die Freudenfeuer im Vorgebirge von Hillsbrad, im Silberwald, in Westfall und dem Sumpfland auf. Sprecht anschließend mit dem Flammenbewahrer.", description = "Die Feuer des Sonnenwendfests lassen das Land traditionsgemäß im Licht unzähliger Flammen erstrahlen. Manche behaupten, dass die grünen Flammen die besten seien, da sie so schwierig zu unterhalten sind und eine solch ungewöhnliche Farbgebung haben.\n\nVersichert Euch für unseren Flammenbewahrer, dass die Feuer in den östlichen Königreichen auch weiterhin lodern. Ihr findet sie in der Nähe von Dun Modr im Sumpfland, unweit von Pyrewood im Silberwald, bei den Klippen zum Leuchtturm in Westfall und nahe dem zerstörten Turm im Vorgebirge von Hillsbrad.", progress = nil, completion = "Ihr seid also wieder da und habt die Smaragdflammen dieser Welt gesehen. Was sagt Ihr, mh? Ein mit Sicherheit seltener und wunderschöner Anblick. Natürlich weiß ich, dass eine handfeste Belohnung mehr Anklang findet... also bitte, nehmt dies für Eure Mühen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHolunderbeerenkuchenFeuergeröstetes BrötchenSonnenwendwürstchenGetoastetes Smorc\n\nIhr bekommt außerdem:\n\n"},
[9415] = {title = "Meldung bei Marschall Bluewall", objective = "Sprecht mit Marschall Bluewall beim Lager der Allianz in der Nähe des Zoraschwarmbaus.", description = "Gehört Ihr zu Marschall Bluewalls neuen Rekruten? Natürlich.\n\nAuf was wartet Ihr noch? Gute Soldaten verlieren ihr Leben in der Wüste. Freut es Euch nicht, bald dazuzugehören?\n\nLos jetzt, macht Euch auf den Weg... und trocknet dabei nicht aus.", progress = nil, completion = "Die Allianz braucht jeden tauglichen Rekrut, den sie bekommen kann. Die Horde hat ständig Verstärkung vom nördlichen Kontinent bekommen, wir mussten kämpfen, um überhaupt standzuhalten.\n\nLasst Euch die Lage von mir schildern.", rewards = nil},
[9416] = {title = "Meldung bei General Kirika", objective = "Sprecht mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus.", description = "Ihr müsst zu General Kirikas neuen Rekruten gehören. Es wurde Zeit, dass Ihr kommt. Der Truppenverschleiß in der Wüste ist hoch.\n\nDie Zwerge haben tagtäglich Verstärkung bekommen, wir können es uns nicht leisten in unserem Kampf um Ressourcen in Silithus an Boden zu verlieren.\n\nLasst Euch vom General weitere Anweisungen geben. Ich muss Euch Rekruten lediglich finden, nicht ausbilden.", progress = nil, completion = "Es ist gut, dass Ihr hier seid, aber wir haben keine Zeit für überflüssige Worte. Was Ihr braucht, sind Anweisungen, und dann müsst Ihr losziehen.\n\nHört gut zu.", rewards = nil},
[9419] = {title = "Durchkämmen der Wüste", objective = "Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit Marschall Bluewall beim Lager der Allianz in der Nähe des Zoraschwarmbaus.", description = "Wir hatten vor kurzem herausgefunden, dass die Horde die Wüste von Silithus nach Ressourcen abgesucht hat, schenkten dem Ganzen aber keine besondere Beachtung. Wir dachten, es wäre die Sache nicht wert, eine größere Anzahl von Soldaten in dieser Bruthitze zu stationieren.\n\nWie dem auch sei, wir haben die Wichtigkeit dieser Ressourcen erkannt und versuchen nun, um jeden Preis aufzuholen.\n\nWenn Ihr uns unterstützen wollt, müsst Ihr in die Wüste gehen, dort nach Silithyst suchen und diesen anschließend hierher bringen.", progress = nil, completion = "Dem Licht sei Dank, Eure Suche war erfolgreich.\n\nHätten wir nur eher damit begonnen, dann wären wir jetzt nicht in einer so verzweifelten Notlage. Wir müssen verhindern, dass die Schätze der Wüste in die Hände der Horde fallen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErheblicher HeiltrankErheblicher Manatrank\n\nIhr bekommt außerdem:\n\n"},
[9422] = {title = "Durchkämmen der Wüste", objective = "Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus.", description = "Wir haben die Wüste von Silithus bereits seit einiger Zeit nach Kristallressourcen durchkämmt. Die einzigen Gefahren, die sich uns dabei in den Weg gestellt haben, waren die Kreaturen, die dort heimisch sind, sowie Sand, Staub und Hitze.\n\nDie Allianz scheint nun aber Wind von unserem Unterfangen bekommen zu haben. Ein Rennen hat begonnen. Ein Rennen um die natürlichen Ressourcen und um deren Verteidigung.\n\nWir brauchen jede helfende Hand, die wir bekommen können. Ich hoffe Ihr werdet uns unterstützen.", progress = "Hütet Euch vor den Gefahren der Wüste, <Name>. Die Allianz könnte hinter jeder Düne lauern und jeder Schritt könnte somit Euer letzter sein.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Diese Ressourcen kommen sofort zum Rest der Vorräte. Jedes Bisschen trägt zu unserem Sieg und zur Schwächung unserer Feinde bei.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErheblicher HeiltrankErheblicher Manatrank\n\nIhr bekommt außerdem:\n\n"},
[9556] = {title = "Dem Sieger...", objective = "Sucht nach einer Phiole mit heiligem Wasser in Stratholme und bringt sie zu dem Magier von Lordaeron im Magierviertel von Stormwind oder in Undercity, falls Eure Seite in den östlichen Pestländern erfolgreich war.", description = "Ihr habt zweifellos lange und hart um die Verteidigung der Türme gekämpft, <Volk>. Wir würden Euch gerne etwas im Gegenzug für Euren tapferen Einsatz geben, allerdings müsst Ihr uns zuerst beweisen, dass Ihr die Gewichtigkeit dieser hier stattgefundenen Tragödien auch versteht.\n\nLauft durch Stratholme und sucht nach einer Phiole mit dem heiligen Wasser. Sobald Ihr sie gefunden habt, reist zum Magierviertel in Stormwind oder nach Undercity... Dort werdet Ihr, insofern Ihr in diesen Landen siegreich wart, auf meinen Kollegen treffen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[9664] = {title = "Mehr Befestigungen", objective = "Erobert den Turm der Kronenwache, den Ostwallturm, den Nordpassturm und den Pestwaldturm in den östlichen Pestländern. Kehrt anschließend zum Abgesandten Whitebeard bei der Kapelle des hoffnungsvollen Lichts zurück.", description = "Willkommen in den Pestländern, <Name>. Wie Ihr wisst, behaupten sich die Verlassenen und ihre Verbündeten entgegen all unserer Anstrengungen in den von hier aus westlich gelegenen Ländern. Die Kommandanten der Allianz haben beschlossen, dass hier im Osten neue Befestigungen errichtet werden sollen, um die Schlinge um unseren Feind noch etwas enger zu schnüren.\n\nLange seit den Tagen Lordaerons verlassene und herrenlose Türme müssen für diesen Zweck erobert und wieder aufgebaut werden. Diese Länder hier ist gefährlich, wir berauchen Eure Hilfe", progress = nil, completion = "Sehr gut, &lt;Name&gt;. Es ist äußerst wichtig, dass wir diese Türme halten. Wir müssen sie vor zukünftigen Angriffen schützen und brauchen noch so lange Eure Hilfe, bis Verstärkung zur Sicherung dieses Gebiets eintrifft.", rewards = "Ihr bekommt:\n\n"},
[9665] = {title = "Verstärkung der Verteidigung", objective = "Erobert den Turm der Kronenwache, den Ostwallturm, den Nordpassturm und den Pestwaldturm in den östlichen Pestländern. Kehrt anschließend zum Abgesandten Gormok bei der Kapelle des hoffnungsvollen Lichts zurück.", description = "Agenten der Verlassenen sind hinter das Vorhaben der Allianz gekommen. Sie wollen neue Stützpunkte bei verlassenen Türmen hier in den östlichen Pestländern einrichten.\n\nWir dürfen auf keinen Fall zulassen, dass sie sich an unserer östlichen Grenze dauerhaft festsetzen, wir müssen den Einfall der Allianz abwehren. Wir beabsichtigen sie aus jeglichen Türmen, die sie bereits besetzt haben, zu vertreiben. Dann gilt es diese Türme zu verteidigen und weitere Eroberungsversuche abzuwehren.", progress = nil, completion = "Das sind gute Neuigkeiten, &lt;Name&gt;. Bis wir die Kräfte der Allianz gänzlich vertrieben haben, wird es hier in den Pestländern dauerhaft zu Kämpfen kommen.\n\nIch hoffe, dass Ihr uns bis zu diesem Tag auch noch weiterhin unterstützt.", rewards = "Ihr bekommt:\n\n"},
[65593] = {title = "Herzen der Liebenden", objective = "Bringt die Herzen von Avelina Lilly und Isaac Pearson zu Carendin Halgar im Tempel der Verdammten.", description = "Ein Inkubus wird von den Herzen Liebender angelockt. Die sehnlichste Liebe erschafft einen unwiderstehlichen Köder.\n\nMeine Wahrsagung hat mir zwei Personen gezeigt, die ganz besonders geeignet sein sollten.\n\nIm Silberwald bietet Avelina Lilly den gefallenen Magiern von Ambermill ihre Dienste als Schneiderin an. Im Brachland hofft Isaac Pearson, sich im Küstendorf Ratchet einen Namen zu machen.\n\nSie arbeiten an entgegengesetzten Enden der Welt, doch ihre Herzen sehnen sich nur nach einander. Bringt ihre Herzen zu Carendin.", progress = "Ah, <Name>, Ihr seid zurückgekehrt. Konntet Ihr die Herzen der Liebenden beschaffen?", completion = "Hervorragend gemacht, wie erwartet, &lt;Name&gt;.\n\n\n\nTrottel.", rewards = "Ihr bekommt:\n\n"},
[65597] = {title = "Die Bindung", objective = "Beschwört mit den Herzen der Liebenden einen Inkubus, unterwerft ihn und bringt die Herzen der Liebenden dann zu Carendin Halgar im Magieviertel von Undercity zurück.", description = "Endlich ist es so weit. Bringt die Herzen zum Beschwörungskreis dort unten. Legt sie in die Mitte und ruft den Inkubus herbei.\n\nDer Dämon wird wenig erfreut sein, wenn er merkt, dass Ihr ihn in eine Falle gelockt habt. Lasst Euch nicht von ihm bezaubern, <Name>. Ihr müsst ihn vollständig unterwerfen.\n\nErst dann kann ich Euch den Zauber lehren, mit dem Ihr ihn an Euren Willen bindet.", progress = "Der Inkubus beherrscht durchaus Kampfkünste, doch seine stärkste Waffe ist sein täuschender Charme. Ein Augenblick der Schwäche reicht, um von diesem Dämon betört zu werden.\n\nLasst das nicht zu, <Name>.", completion = "Beeindruckend. Wirklich beeindruckend. Die Sayaad sind darauf spezialisiert, Sterbliche zu ihren Opfern zu machen. Viele &lt;Klasse&gt;, die sich stark genug wähnten, um einen zu beherrschen, wurden stattdessen beherrscht.\n\nIhr habt der Prüfung standgehalten, &lt;Name&gt;, und Euch Eure Belohnung verdient. Ich werde Euch den Zauber zur Beschwörung eines Inkubus lehren.", rewards = "Ihr erlernt:\n\nInkubus beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\n'Inkubus beschwören' lehren\n\nIhr bekommt außerdem:\n\nKleiner Seelenbeutel"},
[65601] = {title = "Liebe kann schmerzhaft sein", objective = "Sprecht mit Magar in Orgrimmar.", description = "Einen männlichen Sayaad nennt man einen Inkubus. Eine äußerst boshafte Kreatur, die nur eines im Sinn hat.\n\nDer Dämon muss mit einem Köder in unsere Welt gelockt werden, mit einem Gegenstand, der starke Liebe und Hingabe verkörpert.\n\nWenn Ihr Euch von einem Blinden führen lassen möchtet, <Name>, dann hört zu. Östlich von der Kluft der Schatten, in der Gasse von Orgrimmar, lebt Magar. Er wartet darauf, dass sein Lebensgefährte Krilge zurückkehrt.\n\nGeht zu ihm. Er wird Euch bitten, etwas Wertvolles zu suchen. Dies wird der Schlüssel sein, den Ihr dann Gan'rul bringen müsst.", progress = nil, completion = "Wer hat Euch von Krilge erzählt? Habt Ihr Neuigkeiten? Ihr treibt hoffentlich keine Spielchen mit mir...", rewards = "Ihr bekommt:\n\n"},
[65602] = {title = "Alles aus Liebe", objective = "Beschafft die Holzstatuette und bringt sie zu Gakin dem Dunkelbinder im Magierviertel von Stormwind.", description = "Ihr werdet ein mächtiges Reagenz brauchen, um einen Inkubus anzulocken. Ein Objekt, das große Hingabe und Liebe verkörpert.\n\nDurch Wahrsagung habe ich eine kleine Statuette ausfindig gemacht, die für Euer Ritual geeignet sein sollte.\n\nVor Jahrtausenden gehörte die Figur einem jungen Paar. Die ursprünglichen Eigentümer sind verstorben, doch dieses Andenken besteht bis heute.\n\nFolgt der Straße nach Norden ins Ashenvale, dann Richtung Westen und an Maestras Posten vorbei. Ihr werdet ein Haus zwischen den Bäumen sehen. Dort findet Ihr, was Ihr sucht.", progress = "Ihr seid zurück. Darf ich davon ausgehen, dass Ihr Erfolg hattet?", completion = "&lt;Gakin dreht und wendet die Holzstatuette in seiner Hand.&gt;\n\nIch kann die Energie der Emotionen in diesem Artefakt spüren. Die Zeit konnte ihm nichts anhaben. Es wird den Inkubus anlocken wie eine Blüte die Biene.\n\nAuf Takar kann man sich verlassen.", rewards = "Ihr bekommt:\n\n"},
[65603] = {title = "Die Bindung", objective = "Beschwört mit Hilfe der Holzstatuette einen Inkubus, unterwerft ihn und bringt dann die Holzstatuette zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück.", description = "Es ist so weit. Nehmt die Statuette und steigt in die Gruft hinab. Ein Beschwörungskreis ist bereits vorbereitet. Ihr müsst die Statuette in der Mitte platzieren.\n\nDann wird sich das Tor öffnen und der Inkubus wird in unsere Welt kommen.\n\nIhr dürft einen Sayaad nicht unterschätzen. Der Dämon wird Euch angreifen, sobald er Eure Täuschung bemerkt. Ihr müsst alles einsetzen, was Ihr gelernt habt, um ihn zu besiegen.\n\nWenn Ihr Erfolg habt, kehrt zu mir zurück und ich unterwerfe die Kreatur Eurem Willen. Wenn Ihr versagt, ist Eure Seele verwirkt.", progress = "Der Inkubus wird versuchen, Euch zu betören, zu täuschen und so zu überrumpeln. Der Dämon weiß genau, wie er die Herzen Sterblicher für sich gewinnt.\n\nDenkt daran, dass alle seine Versprechen Lügen sind. Für diesen Dämon seid Ihr nichts als Beute.", completion = "Nicht übel, &lt;Name&gt;. Ihr habt das Scheusal bezwungen und Euer Wille blieb ungebrochen.\n\nManch ein &lt;Klasse&gt; hielt sich schon für stark genug, einen Sayaad an sich zu binden, und endete stattdessen als nächste Mahlzeit des Dämons. Es freut mich, dass Ihr nicht so töricht seid.\n\nSeht genau zu, dann lehre ich Euch die Anrufung, mit der Ihr Euren jetzt unterworfenen Inkubus beschwört.", rewards = "Ihr erlernt:\n\nInkubus beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\n'Inkubus beschwören' lehren\n\nIhr bekommt außerdem:\n\nKleiner Seelenbeutel"},
[65604] = {title = "Die Bindung", objective = "Beschwört mithilfe des abgetragenen Schals einen Inkubus, unterwerft ihn und bringt dann den abgetragenen Schal zu Gan'rul Bloodeye in Orgrimmar zurück.", description = "Ja... verstehe. Ich kann die verbleibenden Emotionen spüren, die in diesem Stoff enthalten sind. Er ist mit Liebe verwoben. Dem wird der Inkubus nicht widerstehen können.\n\nBringt dies zum Beschwörungskreis in Neerus Zelt, <Name>. Beschwört einen boshaften Inkubus und zeigt ihm, dass Ihr Eure Fähigkeiten gemeistert habt. Rechnet damit, dass er sich nicht still und leise unterwerfen lässt. Haltet Eure Magie bereit und macht Euch auf einen Kampf gefasst. Schon so mancher Hexenmeister hat seinen letzten Fehler begangen, indem er einen Dämon unterschätzt hat.\n\nBringt den Stoff zu mir zurück, sobald Ihr ihn bezwungen habt. Ich werde Magar sagen, was Ihr herausgefunden habt.", progress = "Die Sayaad unterwerfen den Verstand und quälen Seelen. Ihr Antlitz erfreut das Herz, sodass Ihr wehrlos seid, wenn sie mit Peitschen und Klauen in Euer Fleisch reißen.\n\nLasst Euch vom Inkubus nicht betören, <Name>. Tötet ihn schnell und bringt es zu Ende.", completion = "Ha! Siegreich, wie ich es erwartet hatte!\n\nDer Inkubus wurde bezwungen, und ich werde Euch mit Freuden lehren, wie man den Dämon beschwört. Ihr werdet stärker und steht zweifelsohne davor, noch größere Macht zu erschließen.\n\nIch werde Magar den Schal zurückbringen. Ich kenne diesen Orc schon seit vielen Jahren und hätte nie gedacht, dass ihm einmal jemand so wie Krilge am Herzen liegen würde.\n\nDas erinnert uns daran, was uns von den Dämonen unterscheidet. Wir nutzen ihre Dunkelheit, lassen uns aber niemals von ihnen nutzen.", rewards = "Ihr erlernt:\n\nInkubus beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\n'Inkubus beschwören' lehren\n\nIhr bekommt außerdem:\n\nKleiner Seelenbeutel"},
[65610] = {title = "Irgendwo anders", objective = "Untersucht den Fallenskysee in Ashenvale und erstattet Gan'rul Bloodeye in Orgrimmar Bericht.", description = "Ich habe Krilge bei der Herstellung von Mondstoff im Ashenvale kennengelernt. Er war dort stationiert, um Zivilisten vor Gefahren zu beschützen, bis er dann verschwand...\n\nSie haben die Suche aufgegeben und sehen ihn als Deserteur, aber das glaube ich nicht.\n\nWir haben uns oft am Fallenskysee getroffen, bevor der von diesen aggressiven Sumpfmonstern überrannt wurde.\n\nIch bitte nur ungern andere um Gefallen, aber wenn Ihr ins Ashenvale gehen und nach ihm Ausschau halten könntet, wäre ich Euch dankbar.", progress = "Ja, was gibt's?", completion = "Was habt Ihr da, &lt;Name&gt;? Einen Schal aus... Mondstoff? Ihr wollt mich doch hoffentlich nicht bezirzen.", rewards = "Ihr bekommt:\n\n"},
[76156] = {title = "Schleicht mit der Erdenmutter", objective = "Schleicht Euch in die Mine der Venture Company südöstlich von Thunder Bluff und sammelt 5 Zephyriumbergbauladung aus Loren mit Sprengvorräten, dann kehrt zu Eberton Schattentotem in Thunder Bluff zurück.", description = "Ich spüre ein verborgenes Talent für die subtilen Künste in Euch, <Schamane/Schamanin>. Nutzt diese Maske, um die nahegelegene Mine der Venture Company zu infiltrieren und ihre Vorräte zu stehlen. Das mag nicht nach einer überzeugenden Verkleidung aussehen, aber ein fähiger Schurke kann sich mit so wenig wie einem charmanten Lächeln und einer klugen Ablenkung an jeder Wache vorbeischleichen. Ich bin überzeugt, Ihr besitzt diese Fähigkeit ebenfalls.", progress = "Wir müssen an Euren Schleichfähigkeiten arbeiten, <Klasse>. Ich konnte Euch hören, sobald Ihr die Ebene betreten habt.", completion = "Hmm... Vielleicht sind Verkleidungen nicht Eure Stärke.", rewards = "Ihr bekommt:\n\n"},
[76160] = {title = "Schleicht mit der Erdenmutter", objective = "Sammelt 8 Windzornzapfen nördlich von Thunder Bluff, zerstampft sie mit Mörser und Stößel und kehrt mit dem Ergebnis zu Eberton Schattentotem in Thunder Bluff zurück.", description = "Ich spreche aus einer Zukunft zu Euch, in der die Horde vor Bedrohungen steht, die Ihr Euch nicht vorstellen könnt. Da die anderen mich nicht sehen können, muss ich mich darauf verlassen, dass Ihr meine Fähigkeiten lernt und sie an den Stamm weitergebt.\n\nVielleicht könnt Ihr besser mit Giften umgehen als mit Verkleidungen. Die Harpyien im Norden nisten in einem Baum, der ein stark toxisches Harz produziert. Sammelt die heruntergefallenen Zapfen um die Nester herum auf, dann zerstampft sie zu einer Salbe. Wenn Ihr sie auf eine Klinge auftragt, wird sie sich in das Fleisch Eurer Feinde brennen und ihr Blut in Salz verwandeln.", progress = "Passt mit der fertigen Salbe gut auf, <Klasse>. Jeder Hautkontakt könnte sehr schmerzhaft sein.", completion = "&lt;Klasse&gt;, das ist nicht die giftige Salbe, um die ich Euch gebeten habe. Was Ihr mir gebracht habt, ist nichts weiter als Piniennussbutter. Seid Ihr sicher, dass Ihr meinen Anweisungen gefolgt seid?\n\nDas eignet sich mehr als Brotaufstrich und weniger als Waffengift. Es sei denn, Euer Gegner hat zufällig eine schwere Nussallergie.", rewards = "Ihr bekommt:\n\nPinienkernbutter"},
[76240] = {title = "Schleicht mit der Erdenmutter", objective = "Kauft oder fangt einen rohen glänzenden Kleinfisch, dann nutzt das Messerset, um ihn vor Eberton Schattentotem in Thunder Bluff zu filetieren.", description = "Ich habe noch eine letzte Idee, die uns zum Erfolg führen könnte. Ich spüre immer noch ein verborgenes Talent in Euch, aber vielleicht müssen wir es indirekter herauslocken.\n\nGeht und besorgt einen rohen glänzenden Kleinfisch. Bringt ihn her und nutzt diese Dolche, um ihn zu säubern und zu filetieren. Denkt nicht zu viel darüber nach. Tut einfach, was sich natürlich anfühlt.", progress = "Habt Ihr etwas für mich?", completion = "Das war eine starke Leistung, &lt;Klasse&gt;. Nicht ganz die schurkische Präzision, die ich mir erhofft hatte, aber Ihr besitzt eine beeindruckende Fingerfertigkeit.\n\nJetzt sehe ich, dass nicht Ihr mein Volk in den subtilen Künsten ausbilden werdet, aber es gibt eine Sache, die ich Euch beibringen kann. Viel Glück auf Euren Reisen, &lt;Klasse&gt;. Die Horde wird Helden wie Euch brauchen.", rewards = "Ihr erlernt:\n\nBeidhändigkeit\n\nDer folgende Zauber wird auf euch gewirkt:\n\nHandschuhe prägen - Lavapeitsche\n\nIhr bekommt außerdem:\n\n"},
[77568] = {title = "Die Stärke eines Jägers", objective = "Besiegt Githyiss die Üble in der Schattenweberhöhle und bergt die verlorene Rune. Lernt die Rune, dann erstattet Ayanna Everstride in Shadowglen Bericht.", description = "Ein Jäger zieht seine Kraft nicht nur aus seinen Begleitern, sondern aus der Verbindung mit allen Wesen und dem Respekt für sie. Ihr werdet viele Tiere im Dienst für die Allianz jagen und erlegen, aber selbst im Kampf müsst Ihr Euren Gegner respektieren.\n\nMein letzter Lehrling nutzte eine mystische Rune, um ihre Fähigkeiten zu verstärken, aber leichtsinnigerweise wollte sie sie gleich an der größten Spinne der Höhle im Norden ausprobieren: einer Kreatur, die wir Githyiss die Üble nennen. Ihre Respektlosigkeit hatte ihr Ableben zur Folge.\n\nTötet Githyiss, aber unterschätzt ihre Stärke nicht.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nGesprungene Lederhandschuhe"},
[77571] = {title = "Relikte der Kaldorei", objective = "Bergt das Relikt von den Grellkin in Shadowglen. Folgt der Führung des Relikts und lernt eine neue Fähigkeit, dann erstattet Mardant Strongoak Bericht.", description = "Die Kaldorei sind ein uraltes Volk und unsere verlorenen Relikte können auf ganz Azeroth gefunden werden. Mithilfe dieser Relikte können die Geister Euch beibringen, wie Ihr Eure Verbindung zum Traum stärken könnt.\n\nDie Grellkin haben ein solches Relikt gestohlen. Tötet sie und bergt das Relikt. Dann folgt seiner Führung und erlernt eine neue Kampftechnik. Kehrt zu mir zurück, wenn Ihr fertig seid.", progress = "Was hat das Relikt Euch gelehrt?", completion = "Gut gemacht, &lt;Name&gt;. Die Rune, die Ihr erlernt habt, auf Eure Ausrüstung anzuwenden, wird Euch mächtige neue Fähigkeiten verleihen.\n\nHaltet auf Euren Reisen Ausschau nach weiteren unserer verlorenen Relikte.", rewards = "Ihr bekommt:\n\nGesprungene Lederweste"},
[77573] = {title = "Zweistöckige Arbeit", objective = "Bergt die Rune aus dem versteckten Götzen und nutzt sie, um eine neue Fähigkeit zu lernen. Kehrt danach zu Frahun Shadewhisper zurück.", description = "Ich habe eine Übung für Euch vorbereitet, <Name>. Auf dem Dach dieses Gebäudes befindet sich ein Eulengötze. Ihr solltet ihn vom Südeingang aus sehen können. Der Götzen hat ein Geheimfach mit einer geschnitzten Rune.\n\nKlettert auf das Dach, findet und lernt die Rune, die im Götzen versteckt ist, dann kommt zu mir zurück.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nGesprungene Lederhandschuhe"},
[77574] = {title = "Meditation über Elune", objective = "Kniet im Mondbrunnen nieder und meditiert über Elune, dann nutzt die Erinnerung, um eine neue Fähigkeit zu lernen. Kehrt anschließend zu Shanda in Shadowglen zurück.", description = "Der Allianz beizutreten, hat unser Volk gestärkt, aber wir dürfen nicht vergessen, dass wir Kaldorei sind. Unsere Verbindung zu Elune ist der Kern unseres Wesens.\n\nBefreit Euren Geist, <Name>, und konzentriert Euch ganz auf meine Stimme. Ich werde eine uralte Erinnerung unseres Volkes mit Euch teilen. Geht zum Mondbrunnen im Norden und kniet im heiligen Wasser nieder, um über Elunes Geheimnisse zu meditieren. Wenn Ihr Eure Gedanken fokussiert habt, werdet Ihr diese Erinnerung verstehen und eine neue Technik lernen. Kommt zu mir zurück, wenn Ihr fertig seid.", progress = nil, completion = "Elune wird Euch auf Euren Reisen wahrscheinlich weitere Erinnerungen offenbaren. Ihr könnt an allen Mondbrunnen in Azeroth meditieren, um Eure Gedanken zu klären und diese Erinnerungen zu interpretieren.\n\nKomplexere Visionen zu verstehen, könnte Hilfe von anderen Priestern der Allianz erfordern. Schämt Euch nicht, von ihrem Glauben zu lernen, &lt;Name&gt;. Tyrande lehrt uns, dass das heilige Licht, das die Menschen verehren, und das Licht von Elune eng miteinander verwandt sind.", rewards = "Ihr bekommt:\n\nZerlumpte Stoffhandschuhe"},
[77575] = {title = "Unter den Schattenweben", objective = "Tötet Waldweberspinnen in der Schattenweberhöhle und bergt die verlorene Rune. Erlernt die Rune und erstattet Alyissia in Shadowglen Bericht.", description = "Die Krieger der Allianz haben Euch viel zu lehren, aber Ihr müsst auch selbst neue Techniken suchen.\n\nIm Norden gibt es eine Höhle, die von Waldweberspinnen befallen ist. Ein anderer Jungkrieger ist vor Kurzem in die Höhle gereist, aber nie zurückgekehrt. Er hat damit experimentiert, mystische Runen in seine Ausrüstung zu gravieren, um seine Kampffertigkeiten zu verbessern.\n\nFindet die Rune bei den Spinnen und lernt die Technik selbst.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nBefleckte Kettenhandschuhe"},
[77582] = {title = "Eignungsprüfung", objective = "Findet die versteckte Truhe in den Klippen hinter Frang. Lernt die Rune, die sich darin befindet, und erstattet Frang im Tal der Prüfungen Bericht.", description = "Ein Krieger der Horde muss vor allem körperliche Stärke besitzen. Auf Eurer Reise werdet Ihr viele Prüfungen Eurer Ausdauer überstehen müssen.\n\nZu diesem Zweck habe ich eine Truhe an den Klippen hinter mir versteckt. Ihr könnt sie vom Feuer in der Mitte des Dorfes aus sehen. Sie zu erreichen, wird nicht so einfach werden. In der Truhe befindet sich eine mächtige Rune.\n\nEure Prüfung besteht darin, die Rune zu finden und zu mir zurückzukehren, nachdem Ihr ihre Geheimnisse entschlüsselt habt.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nBefleckte Kettenhandschuhe"},
[77583] = {title = "Oben auf den Klippen", objective = "Findet die versteckte Truhe in den Klippen um das Tal der Prüfungen. Lernt die Rune, die sich darin befindet, und erstattet Rwag im Höhlenbau Bericht.", description = "Ich habe eine Übung für Euch vorbereitet, <Name>. Ich habe eine Truhe an den Klippen hinter mir versteckt. Ihr könnt sie vom Feuer in der Mitte des Dorfes aus sehen. In der Truhe befindet sich eine mächtige Rune.\n\nEure Prüfung besteht darin, die Rune zu bergen und zu mir zurückzukehren, nachdem Ihr ihre Geheimnisse entschlüsselt habt.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nGesprungene Lederhandschuhe"},
[77584] = {title = "Jagd auf die Rune", objective = "Findet die verlorene Rune, indem Ihr Skorpiden im Tal der Prüfungen tötet. Erlernt die Macht der Rune, dann erstattet Jen'shan Bericht.", description = "Ein Jäger zieht seine Stärke aus seiner Verbindung mit der Natur. Auf Eurer Reise werdet Ihr viel unwegsames Terrain durchqueren müssen und mithilfe Eures Verstandes überleben.\n\nVor Kurzem ist leider ein Jungjäger daran gescheitert. Er ging auf die Jagd nach Skorpiden, doch er kehrte nie zurück. Er hat damit experimentiert, mystische Runen in seine Ausrüstung zu gravieren, um seine Kampffertigkeiten zu verbessern.\n\nFindet die Rune bei den Skorpiden in der Nähe und kehrt zu mir zurück, wenn Ihr ihre Geheimnisse entschlüsselt habt.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nGesprungene Lederhandschuhe"},
[77585] = {title = "Symbole der Macht", objective = "Findet das gestohlene Symbol, indem Ihr Skorpiden im Tal der Prüfungen tötet. Erlernt seine Macht, dann erstattet Shikrik Bericht.", description = "Schamanismus ist eine uralte Kunst, <Name>. Viele Artefakte voll spiritueller Energie können auf ganz Azeroth gefunden werden. Ich habe vor Kurzem selbst ein Symbol bemerkenswerter Macht gefunden, aber diese lästigen Skorpiden haben es gestohlen.\n\nEiner von ihnen trägt es wahrscheinlich noch mit sich herum und hält es für funkelnde Nestdekoration.\n\nWenn Ihr das Symbol findet, erlernt seine Macht und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nGesprungene Lederweste"},
[77586] = {title = "Gestohlene Macht", objective = "Findet die gestohlene Rune im Koven der Burning Blade. Erlernt ihre Macht, dann erstattet Nartok im Höhlenbau Bericht.", description = "Ich habe mit einer neuen Art von Magie experimentiert, mit einer Rune, die Teufelsenergie kanalisieren kann, um mächtige Zauber zu wirken. Ich würde diese Macht mit Euch teilen, aber sie wurde mir von einem dieser lästigen Familiaren der Burning Blade gestohlen.\n\nGeht zu ihrem Koven im Norden und seht nach, ob Ihr meine Rune irgendwo zwischen ihren Habseligkeiten findet. Meiner Erfahrung nach verstecken die Familiare ihre Beute sehr gut.\n\nMeldet Euch wieder bei mir, sobald Ihr sie gefunden und ihre Magie gelernt habt. Es würde mir Freude bereiten zu sehen, dass mein Experiment genutzt wird.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nZerlumpte Stoffhandschuhe"},
[77587] = {title = "Symbole der Macht", objective = "Findet das gestohlene Symbol, indem Ihr Skorpiden im Tal der Prüfungen tötet. Erlernt seine Macht, dann erstattet Shikrik Bericht.", description = "Schamanismus ist eine uralte Kunst, <Name>. Viele Artefakte voll spiritueller Energie können auf ganz Azeroth gefunden werden. Ich habe vor Kurzem selbst ein Symbol bemerkenswerter Macht gefunden, aber diese lästigen Skorpiden haben es gestohlen.\n\nEiner von ihnen trägt es wahrscheinlich noch mit sich herum und hält es für funkelnde Nestdekoration.\n\nWenn Ihr das Symbol findet, erlernt seine Macht und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nGesprungene Lederweste"},
[77588] = {title = "Eignungsprüfung", objective = "Findet die versteckte Truhe in den Klippen hinter Frang. Lernt die Rune, die sich darin befindet, und erstattet Frang im Tal der Prüfungen Bericht.", description = "Ein Krieger der Horde muss vor allem körperliche Stärke besitzen. Auf Eurer Reise werdet Ihr viele Prüfungen Eurer Ausdauer überstehen müssen.\n\nZu diesem Zweck habe ich eine Truhe an den Klippen hinter mir versteckt. Ihr könnt sie vom Feuer in der Mitte des Dorfes aus sehen. Sie zu erreichen, wird nicht so einfach werden. In der Truhe befindet sich eine mächtige Rune.\n\nEure Prüfung besteht darin, die Rune zu finden und zu mir zurückzukehren, nachdem Ihr ihre Geheimnisse entschlüsselt habt.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nBefleckte Kettenhandschuhe"},
[77590] = {title = "Unwegsames Terrain", objective = "Findet die verlorene Rune, indem Ihr Skorpiden im Tal der Prüfungen tötet. Erlernt die Macht der Rune, dann erstattet Jen'shan Bericht.", description = "Ein Jäger zieht seine Stärke aus seiner Verbindung mit der Natur. Auf Eurer Reise werdet Ihr viel unwegsames Terrain durchqueren müssen und mithilfe Eures Verstandes überleben.\n\nVor Kurzem ist leider ein Jungjäger daran gescheitert. Er ging auf die Jagd nach Skorpiden, doch er kehrte nie zurück. Er hat damit experimentiert, mystische Runen in seine Ausrüstung zu gravieren, um seine Kampffertigkeiten zu verbessern.\n\nFindet die Rune bei den Skorpiden in der Nähe und kehrt zu mir zurück, wenn Ihr ihre Geheimnisse entschlüsselt habt.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nGesprungene Lederhandschuhe"},
[77592] = {title = "Oben auf den Klippen", objective = "Findet die versteckte Truhe in den Klippen um das Tal der Prüfungen. Lernt die Rune, die sich darin befindet, und erstattet Rwag im Höhlenbau Bericht.", description = "Ich habe eine Übung für Euch vorbereitet, <Name>. Ich habe eine Truhe an den Klippen hinter mir versteckt. Ihr könnt sie vom Feuer in der Mitte des Dorfes aus sehen. In der Truhe befindet sich eine mächtige Rune.\n\nEure Prüfung besteht darin, die Rune zu bergen und zu mir zurückzukehren, nachdem Ihr ihre Geheimnisse entschlüsselt habt.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nGesprungene Lederhandschuhe"},
[77616] = {title = "Die verlorene Rune", objective = "Findet die verlorene Rune in der Echokammmine und nutzt sie, um eine neue Fähigkeit zu lernen. Erstattet anschließend Llane Beshere in Nordhain Bericht.", description = "Die Krieger der Allianz haben Euch viel beizubringen, aber Ihr müsst auch selbst nach neuen Techniken suchen.\n\nEine andere junge Kriegerin ist vor Kurzem in die Echokammmine gereist. Sie hat damit experimentiert, mystische Runen in ihre Ausrüstung zu gravieren, um ihre Kampffertigkeiten zu verbessern.\n\nIch fürchte, sie wurde überwältigt, als die Kobolde die Mine eingenommen haben. Findet die Rune bei den Kobolden und lernt die Technik selbst.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nBefleckte Kettenhandschuhe"},
[77617] = {title = "Relikte des Lichts", objective = "Findet den Buchband und folgt seiner Anleitung, um eine neue Fähigkeit zu lernen, dann kehrt zu Bruder Sammuel in Nordhain zurück.", description = "Relikte des Lichts können auf ganz Azeroth gefunden werden. Diese Relikte, vor allem die Buchbände, die unseren Orden seit seiner Gründung geleitet haben, können Euch helfen, Eure Verbindung zum Licht zu stärken.\n\nEin solcher Buchband war in den Archiven der Abtei gelagert, aber er wurde von den Banditen der Defias im Osten gestohlen. Holt den Buchband zurück, dann studiert seine Anleitungen, um eine neue Kampftechnik zu lernen. Kehrt zu mir zurück, wenn Ihr fertig seid.", progress = "Was hat der Buchband Euch beigebracht, <Name>?", completion = "Gut gemacht, &lt;Name&gt;. Die Rune, die Ihr erlernt habt, auf Eure Ausrüstung anzuwenden, wird Euch mächtige neue Fähigkeiten verleihen.\n\nHaltet auf Euren Reisen Ausschau nach weiteren dieser verlorenen Relikten.", rewards = "Ihr bekommt:\n\nBefleckte Kettenhandschuhe"},
[77618] = {title = "Dreimal geklaut", objective = "Findet die verlorene Rune in den Lagern der Defias und lernt mit ihr eine neue Fähigkeit. Kehrt danach zu Jorik Kerridan in Nordhain zurück.", description = "Ich schäme mich, das zuzugeben, <Name>, aber diese Idioten der Defias haben mich übers Ohr gehauen. Sie haben eine magische Rune gestohlen, die ich mir... ähm, aus der Abtei \"geliehen\" habe. Ich dachte, damit könnte ich mir einen schnellen Vorteil verschaffen, aber ich konnte sie nicht zum Funktionieren bringen.\n\nGeht nach Osten und versucht, sie unter ihrer Beute zu finden, ja? Und dann versucht selbst Euer Glück mit der Rune. Ihr seht mir aus wie ein Bücherwurm. Nicht böse gemeint.", progress = nil, completion = "Ihr habt flinke Finger, &lt;Name&gt;. Seht diese Rune als ein Geschenk.\n\nWenn Bruder Paxton fragt, haben wir uns nie gesprochen, alles klar?", rewards = "Ihr bekommt:\n\nGesprungene Lederhandschuhe"},
[77619] = {title = "Meditation über das Licht", objective = "Tötet Kobolde in der Echokammmine, um eine Erinnerung zu erhalten. Kniet in der Abtei von Nordhain nieder, um über das Licht zu meditieren, dann nutzt die Erinnerung, um eine neue Fähigkeit zu lernen. Kehrt anschließend zu Priesterin Anetta zurück.", description = "Das Licht hat mir Eure Zukunft gezeigt. Ihr werdet gegen die Kobolde in der Echokammmine kämpfen. In der Mine wird das Licht Euch eine Erinnerung der Vergangenheit offenbaren. Nachdem das geschehen ist, kehrt zur Abtei zurück und kniet in diesen Hallen nieder und meditiert über die Mysterien des Lichts.\n\nWenn Ihr Eure Gedanken fokussiert habt, werdet Ihr diese Erinnerung entziffern und eine neue Technik lernen können. Kehrt zu mir zurück, wenn Ihr fertig seid.", progress = "Was hat Euch das Licht gezeigt?", completion = "Wenn das Licht Euch weitere Visionen offenbart, könnt Ihr jederzeit an heiligen Orten meditieren, um Eure Gedanken zu klären und über diese Geheimnisse nachzudenken.\n\nIch habe auch gesehen, dass Euer Weg Euch zu einem Gespräch mit unseren elfischen Verbündeten in Kalimdor führen wird. Mehr über ihre merkwürdigen Rituale der Mondanbetung zu erfahren, könnte uns von Nutzen sein, um auch ihnen eines Tages den Weg zum Licht zu zeigen.", rewards = "Ihr bekommt:\n\nZerlumpte Stoffhandschuhe"},
[77620] = {title = "Zauberforschung", objective = "Holt die Forschungsnotizen von den Banditen der Defias zurück und nutzt sie, um einen neuen Zauber zu lernen. Kehrt anschließend zu Khelden Bremen in Nordhain zurück.", description = "Ich werde Euch beibringen, was ich weiß, <Name>, aber Eure eigenen Forschungen anzustellen, kann Euch unfassbar mächtig machen. Aufzeichnungen zu studieren, die Azeroths größte Erzmagier hinterlassen haben, ist ein guter Anfang. Die Archive der Abtei bargen eine Vielfalt an arkanen Forschungsnotizen, aber sie wurden von Agenten der Defias gestohlen.\n\nFindet die Zaubernotizen bei den Banditen im Osten und nutzt diese Fibel, um sie zu entziffern. Kehrt zu mir zurück, wenn Ihr Erfolg hattet.", progress = "Wie kommen Eure Forschungen voran?", completion = "Gut gemacht, &lt;Name&gt;. Nehmt diese Verständnisamulette. Sie werden Euch dabei helfen, weitere arkane Schriften zu entziffern.\n\nSucht weiter nach Zaubernotizen in ganz Azeroth und nutzt sie, um Eure Forschung voranzubringen. Wenn Ihr mehr Amulette braucht, könnt Ihr diese bei einem Reagenzienverkäufer erwerben.", rewards = "Ihr bekommt:\n\nVerständnisamulettZerlumpte Stoffhandschuhe"},
[77621] = {title = "Gestohlene Macht", objective = "Findet die Rune in den Lagern der Defias im Osten und lernt mit ihr eine neue Fähigkeit. Kehrt danach zu Drusilla La Salle in Nordhain zurück.", description = "Ich habe mit einer neuen Art von Magie experimentiert, mit einer Rune, die Teufelsenergie kanalisieren kann, um mächtige Zauber zu wirken. Ich würde diese Macht mit Euch teilen, aber meine Notizen wurden mir letzte Nacht gestohlen. Ich verdächtige die Banditen, die sich \"Defias\" nennen.\n\nGeht nach Osten und seht nach, ob Ihr meine Rune irgendwo zwischen ihren Habseligkeiten findet. Meldet Euch wieder bei mir, sobald Ihr sie gefunden und ihre Magie gelernt habt. Es würde mir Freude bereiten zu sehen, dass mein Experiment genutzt wird.", progress = nil, completion = "Ihr scheint Euch gut an diese neue Magie gewöhnt zu haben, &lt;Name&gt;. Findet mehr dieser Runen und prägt sie in Eure Ausrüstung, um neue Fähigkeiten gegen diejenigen einzusetzen, die sich Euch widersetzen.\n\nEines Tages wird Eure Macht vielleicht selbst die meinige übertreffen.", rewards = "Ihr bekommt:\n\nZerlumpte Stoffhandschuhe"},
[77642] = {title = "Weisheit der Loa", objective = "Kniet am Loaaltar in Sen'jin nieder und haltet mit dem Loageist Zwiesprache. Nutzt die Erinnerung, um eine neue Fähigkeit zu lernen, dann kehrt zu Ken'jal im Tal der Prüfungen zurück.", description = "Der Beitritt zur Horde hat unserem Volk eine sichere Heimat gegeben, <Name>, aber wir müssen uns daran erinnern, dass es die Loa sind, die immer über uns wachen.\n\nKlärt Euren Geist, und ich werde eine uralte Erinnerung mit Euch teilen. Geht zum Loaaltar in Sen'jin und kniet davor nieder, um mit dem großen Loageist Zwiesprache zu halten. Wenn Ihr die Weisheit der Loa empfangen habt, werdet Ihr die Erinnerung verstehen, die ich Euch gegeben habe. Mit diesem Verständnis werdet Ihr eine neue Kraft entdecken.\n\nKehrt zu mir zurück, wenn Ihr fertig seid.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Rune auf Eure Ausrüstung anzuwenden, wird Euch mächtige neue Fähigkeiten verleihen.\n\nDie Loa werden Euch auf Euren Reisen viele weitere Erinnerungen offenbaren. Ihr könnt an Loaaltären auf ganz Azeroth beten, um Euren Geist zu klären und sie zu interpretieren, wie Ihr es gerade getan habt.\n\nUm komplexere Visionen zu verstehen, braucht Ihr vielleicht die Hilfe der &lt;Klasse&gt; der Horde. Schämt Euch nicht, von ihrem Glauben zu lernen, &lt;Name&gt;. Die Weisheit der Loa kann in allen Dingen gefunden werden.", rewards = "Ihr bekommt:\n\nZerlumpte Stoffhandschuhe"},
[77643] = {title = "Zauberforschung", objective = "Findet die gestohlenen Zaubernotizen im Koven der Burning Blade, dann nutzt sie, um eine neue Fähigkeit zu lernen. Kehrt anschließend zu Mai'ah im Tal der Prüfungen zurück.", description = "Als <Magier/Magierin> werden Euch die arkanen Forschungen zu außerordentlicher Macht führen. Die Notizen zu studieren, welche die größten Magier Azeroths hinterlassen haben, ist ein großartiger Anfang. Ich hatte vor Kurzem selbst einige entdeckt, aber sie wurden von diesen lästigen Familiaren der Burning Blade gestohlen.\n\nHolt die Zaubernotizen aus dem Koven im Norden und benutzt diese Fibel, um sie zu entziffern. Kehrt zurück, wenn Ihr Eure Untersuchung abgeschlossen habt.", progress = "Wie kommen Eure Forschungen voran, <Name>?", completion = "Gut gemacht, &lt;Name&gt;. Nehmt diese Verständnisamulette. Sie werden Euch dabei helfen, weitere arkane Schriften zu entziffern.\n\nSucht weiter nach Zaubernotizen in ganz Azeroth und nutzt sie, um Eure Forschung voranzubringen. Wenn Ihr mehr Amulette braucht, könnt Ihr diese bei einem Reagenzienverkäufer erwerben.", rewards = "Ihr bekommt:\n\nVerständnisamulettZerlumpte Stoffhandschuhe"},
[77648] = {title = "Relikte der Tauren", objective = "Bergt das gestohlene Relikt aus der Dornrankenklamm. Folgt der Führung des Relikts und lernt eine neue Fähigkeit, dann erstattet Gart Mistrunner im Camp Narache Bericht.", description = "Die Tauren sind ein uraltes Volk, <Name>, und unsere verlorenen Relikte können auf ganz Azeroth gefunden werden. Mithilfe dieser Relikte können die Geister Euch beibringen, wie Ihr Eure Verbindung zum Traum stärken könnt.\n\nDie Stacheleber der Borstennacken haben ein solches Relikt von uns gestohlen. Sie haben es bestimmt in die Dornrankenklamm gebracht. Bergt das Relikt und folgt seiner Führung, um eine neue Kampftechnik zu lernen. Kehrt zu mir zurück, wenn Ihr fertig seid.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Rune, die Ihr erlernt habt, auf Eure Ausrüstung anzuwenden, wird Euch mächtige neue Fähigkeiten verleihen.\n\nHaltet auf Euren Reisen Ausschau nach weiteren unserer verlorenen Relikte.", rewards = "Ihr bekommt:\n\nGesprungene Lederweste"},
[77649] = {title = "Die Stärke eines Jägers", objective = "Findet die vermisste Rune, indem Ihr Kampfeber der Borstennacken in der Dornrankenklamm tötet. Nutzt die Rune, um eine neue Fähigkeit zu lernen, dann erstattet Lanka Farshot im Camp Narache Bericht.", description = "Jäger sind für die Lebensart der Tauren sehr wichtig, <Name>. Unser Volk sieht zu uns als Wächter und Ernährer auf. Auf Euren Reisen werdet Ihr Euch häufig allein in feindlichen Gebieten wiederfinden und müsst Euch zum Überleben auf Eure Gerissenheit verlassen.\n\nVor Kurzem hat ein Jungjäger mit mystischen Runen experimentiert, um seine Kampffertigkeiten zu verbessern. Er ist ausgezogen, um sein Können an den Kampfebern der Borstennacken im Osten zu erproben, doch er kehrte nie zurück.\n\nFindet seine Rune und nutzt sie, um eine neue Kampftechnik zu lernen. Kehrt zu mir zurück, wenn Ihr fertig seid.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nGesprungene Lederhandschuhe"},
[77651] = {title = "In die Dornenranken", objective = "Findet die verlorene Rune in der Dornrankenklamm. Nutzt die Rune, um eine neue Fähigkeit zu lernen, dann erstattet Harutt Thunderhorn im Camp Narache Bericht.", description = "Die Krieger der Horde haben Euch viel zu lehren, <Name>, aber Ihr müsst auch selbst neue Techniken suchen.\n\nWie Ihr vielleicht wisst, gibt es eine Rotte feindlicher Stacheleber im Osten. Ein anderer Jungkrieger ist vor Kurzem in ihr Territorium vorgedrungen, aber nie zurückgekehrt. Er hat damit experimentiert, mystische Runen in seine Ausrüstung zu gravieren, um seine Kampffertigkeiten zu verbessern.\n\nFindet die Rune bei den Stachelebern und lernt die Technik selbst. Kehrt zu mir zurück, wenn Ihr fertig seid.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nBefleckte Kettenhandschuhe"},
[77652] = {title = "Symbole der Macht", objective = "Bergt das verlorene Symbol von den Schamanen der Borstennacken in der Dornrankenklamm. Erlernt seine Macht und erstattet Harutt Thunderhorn im Camp Narache Bericht.", description = "Schamanismus ist eine uralte Kunst, <Name>. Viele Artefakte voll spiritueller Energie können auf ganz Azeroth gefunden werden. Ich habe vor Kurzem selbst ein Symbol bemerkenswerter Macht gefunden, aber einige Stacheleber haben es gestohlen.\n\nGeht in ihr Territorium im Osten und findet das gestohlene Symbol. Einer ihrer Schamanen trägt es wahrscheinlich noch mit sich herum und versucht, seine Geheimnisse zu entschlüsseln.\n\nWenn Ihr das Symbol findet, erlernt seine Macht und kehrt zu mir zurück.", progress = "Habt Ihr das Symbol gefunden, <Name>?", completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nGesprungene Lederweste"},
[77655] = {title = "Die verlorene Rune", objective = "Findet die verlorene Rune bei den Frostmanetrollen im Coldridgetal. Nutzt sie, um eine neue Fähigkeit zu lernen, dann erstattet Thran Khorman in Anvilmar Bericht.", description = "Die Krieger der Allianz haben Euch viel zu lehren, <Name>, aber Ihr müsst auch selbst neue Techniken suchen.\n\nEs gibt eine Höhle voller Frostmanetrolle südlich von hier. Ein anderer Jungkrieger ist vor Kurzem hineingegangen, aber nie zurückgekehrt. Er hat damit experimentiert, mystische Runen in seine Ausrüstung zu gravieren, um seine Kampffertigkeiten zu verbessern.\n\nFindet die Rune bei den Trollen, einer von ihnen trägt sie wahrscheinlich mit sich herum, und lernt die Technik selbst. Kehrt zu mir zurück, wenn Ihr fertig seid.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nBefleckte Kettenhandschuhe"},
[77656] = {title = "Die verlorene Rune", objective = "Findet die verlorene Rune bei den Frostmanetrollen im Coldridgetal. Nutzt sie, um eine neue Fähigkeit zu lernen, dann erstattet Thran Khorman in Anvilmar Bericht.", description = "Die Krieger der Allianz haben Euch viel zu lehren, <Name>, aber Ihr müsst auch selbst neue Techniken suchen.\n\nEs gibt eine Höhle voller Frostmanetrolle südlich von hier. Ein anderer Jungkrieger ist vor Kurzem hineingegangen, aber nie zurückgekehrt. Er hat damit experimentiert, mystische Runen in seine Ausrüstung zu gravieren, um seine Kampffertigkeiten zu verbessern.\n\nFindet die Rune bei den Trollen, einer von ihnen trägt sie wahrscheinlich mit sich herum, und lernt die Technik selbst. Kehrt zu mir zurück, wenn Ihr fertig seid.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBefleckte Kettenhandschuhe"},
[77657] = {title = "Relikte des Lichts", objective = "Holt den gestohlenen Buchband von den Frostmanetrollen im Coldridgetal zurück. Folgt seinen Anleitungen, um eine neue Fähigkeit zu lernen, dann kehrt zu Bromos Grummner in Anvilmar zurück.", description = "Relikte des Lichts können auf ganz Azeroth gefunden werden. Diese Relikte, vor allem die Buchbände, die unseren Orden seit seiner Gründung geleitet haben, können Euch helfen, Eure Verbindung zum Licht zu stärken.\n\nEin solcher Buchband war in unseren Archiven gelagert, aber er wurde von Frostmanetrollen gestohlen. Der Dieb hat ihn wahrscheinlich noch bei sich. Holt den Buchband zurück, dann folgt seinen Anleitungen, um eine neue Kampftechnik zu lernen. Kehrt zu mir zurück, wenn Ihr fertig seid.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Rune, die Ihr erlernt habt, auf Eure Ausrüstung anzuwenden, wird Euch mächtige neue Fähigkeiten verleihen.\n\nHaltet auf Euren Reisen Ausschau nach weiteren dieser verlorenen Relikten.", rewards = "Ihr bekommt:\n\nBefleckte Kettenhandschuhe"},
[77658] = {title = "Dreimal geklaut", objective = "Holt die gestohlene Rune aus der Höhle der Frostmanetrolle im Coldridgetal. Setzt sie ein, um eine neue Fähigkeit zu lernen und kehrt zu Solm Hargrin in Anvilmar zurück.", description = "Ich schäme mich, das zuzugeben, <Name>, aber diese Frostmanetrottel haben mich übers Ohr gehauen. Sie haben eine magische Rune gestohlen, die ich mir... ähm, aus der Schatzkammer \"geliehen\" habe. Ich dachte, das könnte mir sozusagen eine Starthilfe verschaffen, aber ich konnte sie nicht zum Funktionieren bringen.\n\nGeht in ihre Höhle im Süden und versucht, sie unter ihrer Beute zu finden, ja? Und dann versucht selbst Euer Glück mit der Rune. Ihr seht mir aus wie ein Bücherwurm. Nicht böse gemeint.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGesprungene Lederhandschuhe"},
[77659] = {title = "Dreimal geklaut", objective = "Holt die gestohlene Rune aus der Höhle der Frostmanetrolle im Coldridgetal. Setzt sie ein, um eine neue Fähigkeit zu lernen und kehrt zu Solm Hargrin in Anvilmar zurück.", description = "Ich schäme mich, das zuzugeben, <Name>, aber diese Frostmanetrottel haben mich übers Ohr gehauen. Sie haben eine magische Rune gestohlen, die ich mir... ähm, aus der Schatzkammer \"geliehen\" habe. Ich dachte, das könnte mir sozusagen eine Starthilfe verschaffen, aber ich konnte sie nicht zum Funktionieren bringen.\n\nGeht in ihre Höhle im Süden und versucht, sie unter ihrer Beute zu finden, ja? Und dann versucht selbst Euer Glück mit der Rune. Ihr seht mir aus wie ein Bücherwurm. Nicht böse gemeint.", progress = nil, completion = "Ihr habt flinke Finger, &lt;Name&gt;. Seht diese Rune als ein Geschenk.\n\nWenn irgendjemand fragt, haben wir uns nie gesprochen, alles klar?", rewards = "Ihr bekommt:\n\nGesprungene Lederhandschuhe"},
[77660] = {title = "Erkundung der Höhlen", objective = "Holt die gestohlene Rune aus der Höhle der Frostmanetrolle im Coldridgetal. Setzt die Rune ein, um eine neue Fähigkeit zu lernen und erstattet dann Thorgas Grimson in Anvilmar Bericht.", description = "Jäger sind ein rauer Haufen, <Name>, sogar unter Zwergen. Wir reisen durch ganz Azeroth, um unerforschte Lande zu erkunden, und jagen alle mögliche gefährliche und exotische Beute. Auf Euren Reisen werdet Ihr Euch häufig allein in feindlichen Gebieten wiederfinden und müsst Euch zum Überleben auf Eure Gerissenheit verlassen.\n\nDie Frostmanetrolle haben eine mächtige Rune von uns gestohlen. Sie haben sie bestimmt in ihrer Höhle im Süden verstaut. Findet die Rune und nutzt sie, um eine neue Kampftechnik zu lernen. Kehrt zu mir zurück, wenn Ihr fertig seid.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nGesprungene Lederhandschuhe"},
[77661] = {title = "Meditation über das Licht", objective = "Findet eine Erinnerung an die Vergangenheit in einer Truhe beim Trogglager in der Nähe von Anvilmar. Kniet Euch dann am Altar des Lichts in Anvilmar nieder und meditiert über das Licht. Benutzt die Erinnerung, um eine neue Fähigkeit zu erlernen. Sprecht danach mit Branstock Khalder.", description = "Das Licht hat mir Eure Zukunft gezeigt, <Name>. Ich habe gesehen, wie Ihr gegen die Troggs im Südwesten kämpft. In einer Truhe werdet Ihr eine Erinnerung aus der Vergangenheit finden. Kehrt hierher zurück und kniet Euch vor den Altar des Lichts, sobald sie sich in Eurem Besitz befindet. Meditiert über ihre Geheimnisse.\n\nWenn Ihr Eure Gedanken gesammelt habt, wird diese Erinnerung für Euch Sinn ergeben und Ihr werdet eine neue Technik erlernen. Sprecht mit mir, wenn Ihr damit fertig seid.", progress = nil, completion = "Wenn das Licht Euch weitere Visionen offenbart, könnt Ihr jederzeit an heiligen Orten meditieren, um Eure Gedanken zu klären und über diese Geheimnisse nachzudenken.\n\nIch habe auch gesehen, dass Euer Weg Euch zu einem Gespräch mit unseren elfischen Verbündeten in Kalimdor führen wird. Mehr über ihre merkwürdigen Rituale der Mondanbetung zu erfahren, könnte uns von Nutzen sein, um auch ihnen eines Tages den Weg zum Licht zu zeigen.", rewards = "Ihr bekommt:\n\nZerlumpte Stoffhandschuhe"},
[77666] = {title = "Gestohlene Macht", objective = "Findet die Rune bei der Gruppe Troggs südwestlich von Anvilmar und benutzt sie, um eine neue Fähigkeit zu lernen. Kehrt danach zu Alamar Grimm in Anvilmar zurück.", description = "Ich habe mit einer neuen Art von Magie experimentiert, mit einer Rune, die Teufelsenergie kanalisieren kann, um mächtige Zauber zu wirken. Ich würde diese Macht mit Euch teilen, aber sie wurde mir von einem dieser lästigen Troggs gestohlen.\n\nIm Südwesten befindet sich ein Lager dieses Felsenkieferungeziefers. Seht nach, ob Ihr meine Rune irgendwo zwischen ihren Habseligkeiten findet, vermutlich ist sie in einer Art Truhe oder so. Meldet Euch wieder bei mir, sobald Ihr sie gefunden und ihre Magie gelernt habt. Es würde mir Freude bereiten zu sehen, dass mein Experiment genutzt wird.", progress = "Nun, <Name>? Kommt Ihr voran?", completion = "Ihr scheint Euch gut an diese neue Magie gewöhnt zu haben, &lt;Name&gt;. Findet mehr dieser Runen und prägt sie in Eure Ausrüstung. Setzt diese Macht gegen diejenigen ein, die sich Euch widersetzen.\n\nEines Tages wird Eure Macht vielleicht selbst die meinige übertreffen.", rewards = "Ihr bekommt:\n\nZerlumpte Stoffhandschuhe"},
[77667] = {title = "Zauberforschung", objective = "Findet die gestohlenen Zaubernotizen im Trogglager südwestlich von Anvilmar und benutzt sie, um eine neue Fähigkeit zu lernen. Kehrt danach zu Marryk Nurribit in Anvilmar zurück.", description = "Als <Magier/Magierin> werden Euch die arkanen Forschungen zu außerordentlicher Macht führen. Die Notizen zu studieren, welche die größten Magier Azeroths hinterlassen haben, ist ein großartiger Anfang. Ich hatte vor Kurzem selbst einige entdeckt, aber sie wurden von diesen lästigen Troggs im Südwesten gestohlen.\n\nHolt die Zaubernotizen aus dem Trogglager und benutzt diese Fibel, um sie zu entziffern. Kehrt zurück, wenn Ihr Eure Untersuchung abgeschlossen habt.", progress = "Wie kommen Eure Forschungen voran, <Name>?", completion = "Gut gemacht, &lt;Name&gt;. Nehmt diese Verständnisamulette. Sie werden Euch dabei helfen, weitere arkane Schriften zu entziffern.\n\nSucht weiter nach Zaubernotizen in ganz Azeroth und nutzt sie, um Eure Forschung voranzubringen. Wenn Ihr mehr Amulette braucht, könnt Ihr diese bei einem Reagenzienverkäufer erwerben.", rewards = "Ihr bekommt:\n\nVerständnisamulettZerlumpte Stoffhandschuhe"},
[77668] = {title = "Die verlorene Rune", objective = "Findet die Rune, die im Nachtwebergrund verborgen liegt, und benutzt sie, um eine neue Technik zu lernen. Meldet Euch dann wieder bei Dannal Stern in Deathknell.", description = "Die Krieger der Dunklen Fürstin können Euch einiges beibringen, aber Ihr müsst auch selbst nach neuen Techniken suchen.\n\nEin anderer Krieger ist vor Kurzem in den Nachtwebergrund vorgedrungen. Er experimentierte damit, Runen in seine Ausrüstung zu prägen, um seine Kampffähigkeiten zu verbessern.\n\nIch vermute, dass er von den Spinnen überwältigt wurde, die sich in der Mine eingenistet haben. Findet die Rune in ihren Netzen und erlernt selbst diese Technik.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBefleckte Kettenhandschuhe"},
[77669] = {title = "Die scharlachrote Rune", objective = "Bestehlt die scharlachroten Konvertiten oder tötet sie, um eine Rune zu finden, und benutzt sie, um eine neue Fähigkeit zu lernen. Kehrt danach zu David Trias in Deathknell zurück.", description = "Wer wart Ihr im Leben, <Name>? <Ein Spion/Eine Spionin>? <Ein Dieb/Eine Diebin>? <Ein Koch/Eine Köchin>, <der/die> besonders geschickt mit dem Messer war? Wie auch immer Eure Vergangenheit aussieht, es ist an der Zeit, neue Taktiken zu entwickeln. Die Diebe der Verlassenen ergreifen jede Gelegenheit, die sich ihnen bietet.\n\nDie scharlachroten Konvertiten östlich von hier kämpfen, als hätten sie noch nie eine Schlacht gesehen, aber der Kreuzzug hat ihnen mystische Runen gegeben, um ihre Fähigkeiten zu verbessern. Stehlt eine dieser Runen und lernt ihre Magie. Kehrt dann zu mir zurück.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", rewards = "Ihr bekommt:\n\nGesprungene Lederhandschuhe"},
[77670] = {title = "Meditation über den Untod", objective = "Kniet auf dem Friedhof nieder, um über den Untod zu meditieren, und benutzt dann die Rune, um eine neue Fähigkeit zu lernen. Kehrt danach zum Dunklen Kleriker Duesten in der Kapelle von Deathknell zurück.", description = "Ich werde in Euren Gedanken eine Erinnerung der Lebenden hervorrufen, vielleicht ist es sogar Eure eigene Erinnerung. Geht zum Friedhof neben der Kapelle und findet heraus, wo die Kälte des Todes am stärksten ist, dann kniet nieder und sammelt Eure Gedanken. Durch Konzentration auf die Geheimnisse des Untodes werdet Ihr Klarheit in dieser Erinnerung finden und eine neue Technik erlernen. Kehrt zu mir zurück, wenn Ihr damit fertig seid.", progress = nil, completion = "Die Lebenden klammern sich aus einem Grund an das Licht: Sie fürchten in die Vergessenheit des Todes zu geraten. Als Verlassener hat diese Furcht keine Macht mehr über Euch. Obwohl das Licht nun sogar diejenigen unter uns zurückweist, die einst seine größten Verehrer waren, befehligen wir dunkle Mächte, die jenseits des Schattens des Todes liegen.\n\nWenn Ihr stärker werdet, empfehle ich Euch einige Zeit mit den Trollen der Horde zu verbringen. Obwohl ihre Kultur primitiv ist, haben die \"Loa\", die sie verehren, eine Verbindung zum Untod. Sie könnten Euch einen Einblick in unser Wesen verschaffen.", rewards = "Ihr bekommt:\n\nZerlumpte Stoffhandschuhe"},
[77671] = {title = "Zauberforschung", objective = "Tötet Initianden des Scharlachroten Kreuzzugs, um Zaubernotizen zu finden, und benutzt diese, um einen neuen Zauber zu lernen. Kehrt dann zu Isabella in Deathknell zurück.", description = "Die Arkanisten der königlichen Apothekervereinigung widmen ihr Leben der Zauberforschung im Dienst der Verlassenen. Eure Berufung mag das Abenteuer sein, aber Ihr könnt der Dunklen Fürstin dienen, indem Ihr die Zaubernotizen, die Ihr auf Euren Reisen findet, sicherstellt und studiert.\n\nTötet die Initianden des Scharlachroten Kreuzzugs, die in der Nähe von Deathknell ihr Lager aufgeschlagen haben, und sammelt ihre Zaubernotizen. Benutzt die Fibel, um die Notizen zu entschlüsseln, und lernt einen neuen Zauber. Dann kehrt zu mir zurück.", progress = "Was habt Ihr erfahren, <Name>?", completion = "Gut gemacht, &lt;Name&gt;. Nehmt diese Verständnisamulette. Sie werden Euch dabei helfen, weitere arkane Schriften zu entziffern.\n\nSucht weiter nach Zaubernotizen in ganz Azeroth und nutzt sie, um Eure Forschung voranzubringen. Wenn Ihr mehr Amulette braucht, könnt Ihr diese bei einem Reagenzienverkäufer erwerben.", rewards = "Ihr bekommt:\n\nVerständnisamulettZerlumpte Stoffhandschuhe"},
[77672] = {title = "Die verlorene Rune", objective = "Bergt die Rune aus dem Nachtwebergrund und benutzt sie, um eine neue Fähigkeit zu lernen. Kehrt dann zu Maximillion in Deathknell zurück.", description = "Ich habe mit einer neuen Art von Magie experimentiert, mit einer Rune, die Teufelsenergie kanalisieren kann, um mächtige Zauber zu wirken. Ich habe einen Lehrling ausgesandt, um die Rune an den Spinnen in der Mine im Norden auszuprobieren, aber er ist nicht zurückgekehrt. Ich vermute, wir werden ihn nicht wiedersehen.\n\nVielleicht werdet Ihr Euch als standhafter erweisen. Geht zur Mine und bergt die Rune aus den Spinnweben. Lernt ihre Magie und meldet Euch dann wieder bei mir.", progress = nil, completion = "Ihr scheint Euch gut an diese neue Magie gewöhnt zu haben, &lt;Name&gt;. Findet mehr dieser Runen und prägt sie in Eure Ausrüstung, um neue Fähigkeiten gegen diejenigen einzusetzen, die sich Euch widersetzen.\n\nEines Tages wird Eure Macht vielleicht selbst die meinige übertreffen.", rewards = "Ihr bekommt:\n\nZerlumpte Stoffhandschuhe"},
[78088] = {title = "Ein seltsames Artefakt", objective = "Habt Ihr in dem Turm etwas gefunden?", description = nil, progress = "Habt Ihr in dem Turm etwas gefunden?", completion = "Ihr habt gut daran getan, das zu mir zu bringen, &lt;Name&gt;.", rewards = nil},
[78089] = {title = "Rat aus Stormwind", objective = "Fragt die Paladine von Stormwind um Rat für die Kugel.", description = "Ich spüre eine dunkle Macht in dieser Kugel, aber ihre Quelle entzieht sich mir. Wir brauchen den Rat der Paladine von Stormwind. Bringt die Kugel zu ihnen.", progress = "Bringt Ihr Neuigkeiten aus Kalimdor?", completion = "&lt;Untersucht die Kugel mit beunruhigtem Gesichtsausdruck.&gt;", rewards = nil},
[78090] = {title = "Eine zweite Meinung", objective = "Findet das Sanktum der Hexenmeister in Stormwind und bittet sie um Rat zur Kugel.", description = "Ich bin mir nicht sicher, was diese Kugel beinhaltet, <Name>. Ich denke, wir brauchen die Hilfe... eines Spezialisten.\n\nWir haben Kenntnis von einer Hexenmeistersekte, die aus Stormwind heraus operiert. Offiziell lehnen wir den Aufenthalt von Hexenmeistern in der Stadt ab. Inoffiziell kann ihr Wissen nützlich sein, wenn wir es mit dämonischen Kräften zu tun haben.\n\nFindet einen Abgesandten dieser Hexenmeister und fragt nach seiner Meinung zur Kugel.", progress = "Ihr seid weit von der Kathedrale entfernt, <Klasse>. Ich hoffe, es ist Euch bewusst, dass Ihr hier über keinerlei Befugnisse verfügt.", completion = "Die Silberne Hand benötigt also meine Hilfe? Das wird nicht billig.", rewards = nil},
[78091] = {title = "Verdient Euch Euer Salz", objective = "Sammelt 14 Beschwörersalze von den Beschwörern der Blackrock im Rotkammgebirge. Kehrt dann zu Ursula Deline in Stormwind zurück.", description = "Ich werde die Kugel untersuchen und Euch sagen, was ich herausfinde, aber zuerst müsst Ihr etwas für mich tun.\n\nDie Hexenmeister des Blackrockklans benutzen spezielle Salze, um ihre Beschwörungsrituale zu verstärken. Sammelt ein paar von den Orcs im Rotkammgebirge.\n\nWenn Ihr zurückkehrt, werde ich Euch die Ergebnisse meiner Untersuchungen mitteilen.", progress = "<Die Hexenmeisterin studiert die Kugel eindringlich.>", completion = "Ah... die Salze. Ich hatte sie ganz vergessen.\n\nDiese Kugel gleicht nichts, was ich zuvor gesehen habe, &lt;Name&gt;.", rewards = nil},
[78092] = {title = "Sie muss zerstört werden", objective = "Findet eine Möglichkeit, die Kugel zu zerstören.", description = "Diese Kugel ist in der Tat mit einer mächtigen Entität verbunden, irgendwo jenseits des Wirbelnden Nethers. Ich kann ihr Wesen nicht erahnen, aber ich fühle, wie ihre eigene Wahrnehmung durch die Kugel hindurch reicht... und mich ebenfalls studiert.\n\nIch gebe es nur ungern zu, <Name>, aber die Kugel muss zerstört werden.\n\nSie scheint unempfindlich gegenüber den meisten Schadensarten zu sein, aber vielleicht kann die Waffe eines mächtigen Dämonenfürsten ihr etwas anhaben. Ich bin mir nicht sicher, wo Ihr eine solche Waffe finden könnt, aber es erscheint mir, Eure beste Möglichkeit zu sein.\n\nViel Glück, <Name>.", progress = "<Euch stehen die Haare zu Berge, als teuflische Energien Euch umgeben.>", completion = "&lt;Ihr hebt die Kugel in Richtung des Speers.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKugel zerschmettern"},
[78093] = {title = "Kehrt zu Delgren zurück", objective = "Bringt die Splitter der Kugel zu Delgren.", description = "<Die geborstenen Reste der Kugel liegen vor Euren Füßen. Delgren wird sicher sehen wollen, was Euch gelungen ist.>", progress = "Habt Ihr einen Weg gefunden, die Kugel zu zerstören?", completion = "Das ist eine Erleichterung, &lt;Name&gt;. Aber was immer Azeroth durch die Kugel hindurch beobachtet hat... Ich habe das Gefühl, es wird nicht sehr erfreut darüber sein, dass die Kugel zerstört wurde.\n\nNehmt dies als Dank für Eure Bemühungen. Und... seid vorsichtig.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGöttlicher Sturm"},
[78114] = {title = "Bändigung wilder Flügeldrachen", objective = "Bringt einen hypnotischen Kristall und einen knorrigen Zauberstab der wilden Magie zu Jixo Wahnrakete im Steinkrallengebirge.", description = "Habt Ihr diese Prachtschwingenflügeldrachen gesehen, die hier herumfliegen? Ich würde darauf wetten, dass es den Leuten eine gute Stange Geld wert wäre, mir dabei zuzusehen, wie ich auf diesen Dingern einen Salto schlage!\n\nSie sind aber ein störrischer Haufen. Ich bring es nicht fertig, auf einem zu reiten, geschweige denn in luftiger Höhe einige Tricks durchzuführen.\n\nIch habe gehört, dass es möglich ist, einen speziellen Stab anzufertigen, um sie zu besänftigen. Wahrscheinlich könnte ich ihn sogar selbst herstellen. Alles, was ich dazu benötige, ist ein hypnotischer Kristall und ein knorriger Zauberstab der wilden Magie.\n\nNun bin ich mir nicht ganz sicher, wo es die gibt, aber wir können die Details später besprechen.", progress = "Hattet Ihr Erfolg mit den Materialien?", completion = "Gut gemacht! Nun ist es an der Zeit für einen kleinen Feldversuch.", rewards = "Ihr bekommt:\n\n"},
[78121] = {title = "Einen wilden Flügeldrachen bändigen", objective = "Folgt Jixo Wahnrakete und seht zu, wie er einen Flügeldrachen zähmt.", description = "Nun, da der Zauberstab hergestellt ist, gibt es nur noch eine Sache zu erledigen. Ich werde selbst einen Flügeldrachen zähmen!\n\nIhr solltet mitkommen, <Name>. Ihr werdet für mein neuestes Kunststück einen Platz in erster Reihe haben!", progress = nil, completion = "Lasst mich Euch sagen, &lt;Name&gt;, dieser Sturz war noch schmerzhafter, als er ausgesehen hat. Das wird schon wieder, aber ich glaube nicht, dass der alte Jixo in der Zukunft noch Flügeldrachen bändigen wird.\n\nVielleicht sollte ich einfach beim Altbewährten bleiben, wisst Ihr? Stunts, wie mit einem Chopper über zwanzig aufgereihte Gnome springen. Auf sowas stehen die Leute.\n\nNehmt den Zauberstab. Ich habe keine Verwendung mehr dafür. Und hier ist noch ein kleiner Bonus für die ganzen Unannehmlichkeiten.", rewards = "Ihr bekommt:\n\nZauberstab des FlügeldrachenzähmersRune des Tötungsbefehls"},
[78124] = {title = "Almanach von Nar'thalas", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[78127] = {title = "Die Dalaranauswahl", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[78132] = {title = "Helm des Drachentöters", objective = "Der Helm des Drachentöters gehörte einst einem großen Kommandanten, der im Kampf fiel. Es heißt, seine gepeinigte Seele würde noch immer am Ort seines Ablebens umhergeistern.", description = nil, progress = "Der Helm des Drachentöters gehörte einst einem großen Kommandanten, der im Kampf fiel. Es heißt, seine gepeinigte Seele würde noch immer am Ort seines Ablebens umhergeistern.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Damit bin ich auf meinem Weg zu Ruhm und Ehre einen Schritt weiter.", rewards = "Ihr bekommt:\n\n"},
[78133] = {title = "Schild des Drachentöters", objective = "Gerüchten zufolge befindet sich der Schild des Drachentöters im Besitz eines orcischen Kriegsfürsten. Er nahm ihn während eines Überfalls auf eine Menschensiedlung an sich.", description = nil, progress = "Gerüchten zufolge befindet sich der Schild des Drachentöters im Besitz eines orcischen Kriegsfürsten. Er nahm ihn während eines Überfalls auf eine Menschensiedlung an sich.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Damit bin ich auf meinem Weg zu Ruhm und Ehre einen Schritt weiter.", rewards = "Ihr bekommt:\n\n"},
[78134] = {title = "Lanze des Drachentöters", objective = "Die Lanze des Drachentöters hat mehrmals den Besitzer gewechselt. Von Zeit zu Zeit sprechen Gerüchte davon, sie auf einem Schwarzmarkt gesehen zu haben. Vielleicht ist der derzeitige widerwärtige Eigentümer bereit, sich von ihr zu trennen... gegen Bezahlung.", description = nil, progress = "Die Lanze des Drachentöters hat mehrmals den Besitzer gewechselt. Von Zeit zu Zeit sprechen Gerüchte davon, sie auf einem Schwarzmarkt gesehen zu haben. Vielleicht ist der derzeitige widerwärtige Eigentümer bereit, sich von ihr zu trennen... gegen Bezahlung.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Damit bin ich auf meinem Weg zu Ruhm und Ehre einen Schritt weiter.", rewards = "Ihr bekommt:\n\n"},
[78142] = {title = "Betörungen und Verzauberungen", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[78143] = {title = "Geheimnisse der Träumer", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[78144] = {title = "Alonso der Drachenschlächter", objective = "Begleitet Alonso, um den Drachen niederzustrecken.", description = "Die Zeit ist gekommen, <Name>. Ich trage die Rüstung, die einem wahren Drachentöter zusteht! Ihr wart mir eine große Hilfe.\n\nIch sollte Euch anbieten, mich als <mein Ehrenknappe/meine Ehrengehilfin> zu begleiten und mir dabei zuzusehen, wie ich den großen Drachen ein für alle Mal niederstrecke.", progress = nil, completion = "Ich habe es geschafft, &lt;Name&gt;! Endlich ist mein Gegner besiegt!\n\nOh, der Klang von Fangzahn auf Metall, von Schuppe auf Klinge. Welch Gefahr, welch Nervenkitzel! Und nach all dem erhebe ich mich als Champion.\n\nUnd lasst uns nicht Euren bescheidenen Beitrag vergessen! Ohne die Rüstung, die Ihr mir gebracht habt, hätte ich das Ungeheuer sicher niemals bezwingen können.\n\nIhr habt Euch als exzellenter Knappe erwiesen, &lt;Name&gt;. Vielleicht werdet auch Ihr eines Tages auf dem glorreichen Pfad des Ritters wandeln.", rewards = "Ihr bekommt:\n\nRune des wütenden Schlags"},
[78145] = {title = "Handbuch arkanischer Systeme", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[78146] = {title = "Goaz' Schriftrollen", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[78147] = {title = "Verbrechen gegen die Anatomie", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[78148] = {title = "Runen der Zaubererkönige", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[78149] = {title = "Zorn des Landes", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[78150] = {title = "Freund der Bibliothek", objective = "Dank Eurer Spenden entwickelt sich die Bibliothek prächtig.\n\nBitte, nehmt das.", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nHosen prägen - Eisige Adern\n\nDer folgende Zauber wird auf euch gewirkt:\n\nEisige Adern"},
[78192] = {title = "Geheimnisse des Lichts", objective = "Tötet 7 Kräuterkundige der Verlassenen und 9 Sucher der Verlassenen im Nordwesten Ashenvales und kehrt dann zu Maethra Schlackherz in Darnassus zurück.", description = "Ihr wollt also mehr über das Licht erfahren? Dann seid Ihr bei mir genau richtig! Ich bringe Heilung, Pein UND Schutz!\n\nWie wäre es mit einer kleinen Übung? Begebt Euch nach Ashenvale und zeigt einem dieser Hordenzombies, die denken, ihnen würde alles gehören, was eine Harke ist. Das Licht ist für vieles gut, aber Untoten Feuer unterm Hintern machen ist mein Liebling!", progress = nil, completion = nil, rewards = nil},
[78193] = {title = "Geheimnisse des Lichts", objective = "Reist nach Stormwind und sprecht mit Hohepriesterin Laurena in der Kathedrale des Lichts.", description = "Also gut, <Name>, seien wir mal für einen Augenblick ernst. Das Licht ist nicht irgendeine Göttin, die es zu beeindrucken gilt, oder ein Geist, dem man die Freundschaft anbietet. Es ist in uns allen! Man muss nur lernen, es zu fühlen.\n\nBelohnt Euch mit einer Reise nach Stormwind und besucht die Kathedrale des Lichts. Ein wunderbarer Ort, um zu beten und um sich mit dem Licht vertraut zu machen. Und die Architektur ist ein wahrer Augenschmaus!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGeheimnisse des Lichts"},
[78194] = {title = "Geheimnisse von Elune", objective = "Sammelt 10 Terrorwolftatzen von Wölfen im Dämmerwald.", description = "Es tut gut, zu sehen, dass Euresgleichen sich für Elune interessiert. Obschon die Kaldorei ihre liebsten Kinder sind, sorgt sie sich doch um alle Völker Azeroths. Im Gegenzug für ihre Segnungen kümmern wir uns in ihrem Namen um das Land.\n\nKürzlich hat man mich auf Störungen im Gleichgewicht der Natur hingewiesen: tollwütige Terrorwölfe, die im Dämmerwald gesichtet wurden. Zollt Elunes Gleichgewicht Respekt, indem Ihr ihre Zahl dezimiert, und kehrt dann mit Beweisen Eurer Taten zu mir zurück.", progress = "Was für Neuigkeiten bringt Ihr mir?", completion = "Ich danke Euch, &lt;Name&gt;. Dank Eurer Anstrengungen ist das Gleichgewicht stärker.", rewards = nil},
[78195] = {title = "Geheimnisse von Elune", objective = "Bringt die Phiole zu Syrnoya beim Mondbrunnen von Auberdine.", description = "Die Mondbrunnen enthalten Elunes Segen, aber sie sind auch ein Symbol der Verbindungen, die wir alle teilen. Bringt diese Phiole mit Wasser aus Stormwinds Mondbrunnen zu dem in Auberdine, an der Küste Kalimdors. Wenn sich die Wasser verbinden, verbindet sich auch Euer Geist mit dem der Kaldorei.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGeheimnisse von Elune"},
[78196] = {title = "Geheimnisse des Untodes", objective = "Sammelt 12 Schattenblätter von Schattendickichtelementaren in Ashenvale.", description = "Wenn Ihr Glaube oder Huldigung unter den Priestern der Verlassenen sucht, so werdet Ihr enttäuscht werden. Wir haben über den Tod hinausgeblickt und wir wissen, dass uns dort nichts erwartet. Unsere Religiosität entspringt eiskalter Erfahrung, nicht naiver Hoffnung.\n\nErfahrung... Das ist es, was Ihr braucht. Sammelt Schattenblätter von den Sumpfwesen in Ashenvale und kehrt dann zu mir zurück. Ich habe eine Idee, die Eure Fragen beantworten könnte.", progress = nil, completion = nil, rewards = nil},
[78197] = {title = "Geheimnisse des Untodes", objective = "Reist zum Friedhof von Brill in Tirisfal und benutzt die Tinktur des Wachtods.", description = "Alle Verlassenen haben einmal am Rande des Todes gestanden. Zu erleben, wie die Existenz endet, ohne Götter auf der anderen Seite... das mag sich furchterregend anhören, aber in Wahrheit ist es befreiend. Unser Wille gehört uns und ist keinen Mächten verpflichtet außer uns selbst.\n\nBegebt Euch zum Friedhof von Brill und trinkt diese Tinktur. Sie wird Euch an den Rand des Todes bringen und Euch dort halten. Stellt Euch dem Vergessen mit Entschlossenheit und Ihr werdet einen Weg zurück zu den Lebenden finden. Mir fällt kein besserer Weg ein, um mit Euch zu teilen, was es bedeutet, ein Verlassener zu sein.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGeheimnisse des Untodes"},
[78198] = {title = "Geheimnisse der Loa", objective = "Sammelt 14 menschliche Knochen von Hillsbrad von Menschen des Vorgebirges von Hillsbrad, kehrt dann zu Baj'ura in Undercity zurück.", description = "Die mächtigen Trollreiche unserer Vorfahren wurden erbaut auf der Stärke der Loa, Geister mit großer Macht, die Azeroth beherrschen. Wir verehren viele Loa im Darkspearstamm, aber wenn Ihr interessiert daran seid, unseren Glauben zu teilen, dann gibt es einen, der bereit sein könnte, mit Euch zu handeln.\n\nZuerst müsst Ihr eine Opfergabe vorbereiten. Reist nach Tarrens Mühle und greift die Menschen an, die sich dem Anspruch der Horde auf das Gebiet widersetzen. Sammelt die Knochen Eurer Opfer und kehrt zu mir zurück.", progress = "Wie läuft Euer Kampf gegen die Menschen?", completion = "Ausgezeichnet... Die eignen sich für eine gute Opfergabe.", rewards = nil},
[78199] = {title = "Geheimnisse der Loa", objective = "Reist zu den Echoinseln und setzt die Opfergabe bei Bwonsamdis Schrein ein.", description = "Bringt die Opfergabe in den Süden, zu den Echoinseln. An den Stränden werdet Ihr einen Schrein finden, der Bwonsamdi, dem Loa des Todes, geweiht ist. Ein Opfer eines Verlassenen wird zweifelslos seine Aufmerksamkeit auf sich ziehen.\n\nIch muss Euch aber warnen, <Name>. Der Handel mit einem Loa fordert immer einen Preis. Es mag sein, dass Ihr noch nicht wisst, was Ihr aufgebt, aber Bwonsamdi treibt letztendlich immer seine Schulden ein.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGeheimnisse der Loa"},
[78229] = {title = "Prüfung der Eulen", objective = "Bringt die Symbole der drei Eulen zu Loganaar in Moonglade.", description = "Lasst mich das Symbol sehen, das Ihr da habt, <Name>.\n\nEs scheint, als hättet Ihr mit der Prüfung der Eulen begonnen. Dies markiert einen Schlüsselmoment auf Eurem Weg als Druide.\n\nEs gibt weitere Symbole wie dieses, zu finden sind sie in ganz Azeroth. Um sie zu verdienen, müsst Ihr Meisterleistungen mit Geist und Körper vollbringen.\n\nEine Eule sitzt unter einem großen Baum in den Östlichen Königreichen. Eine weitere befindet sich in der Nähe eines großen Baums hier in Kalimdor. Und eine letzte ist dem Wasser zugeneigt und wartet in der Nähe der Küste von Hillsbrad.\n\nBegebt Euch zu diesen Eulen, <Name>, und bringt mir ihre Symbole.", progress = "Wie kommt Ihr voran mit der Prüfung, <Name>?", completion = "Ich möchte Euch gratulieren, &lt;Name&gt;. Was Ihr vollbracht habt, ist keine Kleinigkeit.\n\nDas Bestehen der Prüfung der Eulen beweist die Einstimmung auf alle Aspekte Eurer druidischen Bestimmung.\n\nNehmt diese Rune als Zeichen Eures Triumphs. Ich hoffe, es wird Euch gute Dienste leisten bei Eurer Aufgabe als Wächter des Smaragdgrünen Traums.", rewards = "Ihr bekommt:\n\nRune des Wildwuchses"},
[78261] = {title = "Das Horn von Xelthos", objective = "Findet das Horn von Xelthos in der Burg Schattenfang. Kehrt dann zum toten Briefkasten von C bei Pyrewood zurück. Diesen Auftrag müsst Ihr alleine erledigen.", description = "<Ein Zettel liegt in der Kiste>\n\nIch grüße Euch, <Name>.\n\nIch begehre einen Schatz, bekannt als Horn von Xelthos, der sich irgendwo in der Burg Shadowfang befindet.\n\nNormalerweise fordert ein Besuch dieser Burg Verstärkung. Für diesen Auftrag ist es jedoch äußerst wichtig, dass so wenige wie möglich davon wissen.\n\nIhr müsst ihn alleine erledigen.\n\nIch habe einen Kontakt namens Veenix, der sich im Steinkrallengebirge aufhält. Er sollte in der Lage sein, Euch am Tor des Hofes vorbeizuschmuggeln. Von da an seid Ihr auf Euch gestellt.\n\nBringt das Horn hierher zurück, und die Bezahlung wird bald danach an Euch gehen.\n\n- C", progress = "<Die Kiste ist leer.>", completion = "&lt;Ihr platziert das Horn von Xelthos in der Kiste&gt;", rewards = nil},
[78265] = {title = "Fischöl", objective = "Ich werde Fischöl brauchen - und zwar eine ganze Menge davon!", description = nil, progress = "Ich werde Fischöl brauchen - und zwar eine ganze Menge davon!", completion = "Vielen Dank, &lt;Name&gt;. Ich weiß das gut einzusetzen.", rewards = nil},
[78266] = {title = "Verordnung der Dunkeleisenzwerge", objective = "Ich brauche eine Verordnung der Dunkeleisenzwerge. Wo man Dunkeleisenzwerge findet? Das ist Euer Problem!", description = nil, progress = "Ich brauche eine Verordnung der Dunkeleisenzwerge. Wo man Dunkeleisenzwerge findet? Das ist Euer Problem!", completion = "Vielen Dank, &lt;Name&gt;. Ich weiß das gut einzusetzen.", rewards = nil},
[78267] = {title = "Schredderturbolader", objective = "Ich brauche ein paar der Schredderturbolader der Venture Company. Sie sind fest mit den Schreddersystemen verbunden, Ihr werdet also Spezialausrüstung brauchen, um sie zu bergen.\n\nNein, von mir bekommt Ihr diese Ausrüstung nicht.", description = nil, progress = "Ich brauche ein paar der Schredderturbolader der Venture Company. Sie sind fest mit den Schreddersystemen verbunden, Ihr werdet also Spezialausrüstung brauchen, um sie zu bergen.\n\nNein, von mir bekommt Ihr diese Ausrüstung nicht.", completion = "Vielen Dank, &lt;Name&gt;. Ich weiß das gut einzusetzen.", rewards = nil},
[78270] = {title = "Goblinischer Schlossknacker", objective = "Findet das Horn von Xelthos in der Burg Schattenfang. Kehrt dann zum toten Briefkasten von C bei Pyrewood zurück.", description = "<Ein Zettel liegt in der Kiste>\n\nIch grüße Euch erneut, <Name>.\n\nIch begehre einen Schatz, bekannt als Horn von Xelthos, der sich irgendwo in der Burg Schattenfang befindet.\n\nNormalerweise fordert ein Besuch dieser Burg Verstärkung. Für diesen Auftrag ist es jedoch äußerst wichtig, dass so wenige wie möglich davon wissen.\n\nIhr müsst ihn alleine erledigen.\n\nIch habe einen Kontakt namens Veenix, der sich im Steinkrallengebirge aufhält. Er sollte in der Lage sein, Euch am Tor des Hofes vorbeizuschmuggeln. Von da an seid Ihr auf Euch gestellt.\n\nBringt das Horn hierher zurück, und die Bezahlung wird bald danach an Euch gehen.\n\n- C", progress = "Ihr sagt, Ihr wollt in die Burg Schattenfang... alleine? Ihr habt Mumm!\n\nIch kann Euch Sprengstoff besorgen, um Euch auf die andere Seite des Tors zu bringen, aber ich brauche einen Arbeitsauftrag, damit ich das einigermaßen korrekt verbuchen kann. Einer der Angestellten hier sollte einen dabei haben. Vermutlich einer, der an irgendwas tüftelt oder baut.", completion = "Gut gemacht, &lt;Name&gt;. Ich schätze, das war ein Kinderspiel für jemanden wie Euch.\n\nWie versprochen, hier ist, was Ihr benötigt.", rewards = "Ihr bekommt:\n\nSprengladung"},
[78277] = {title = "Ein Zeichen der Dankbarkeit", objective = "Es mag töricht gewesen sein, aber Thule, Gunther und ich waren wie eine Familie... wie Brüder. Wir haben niemals erwartet, dass unsere Welt in Stücke gerissen würde oder dass Thule sich auf die Seite des Lichkönigs schlagen würde. Und dass Gunthar und ich um unsere Menschlichkeit würden kämpfen müssen...\n\nIch kann spüren, wie der Makel der Geißel in Thules Teil des Zauberstabs hineinsickert. Er wird für immer ruiniert sein, korrumpiert durch seinen Verrat, aber ich bin nicht bereit, loszulassen... Vielleicht irgendwann.\n\nBitte, akzeptiert dieses Symbol des Wissens als meinen Dank.", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nHandschuhe prägen - Lebende Bombe\n\nDer folgende Zauber wird auf euch gewirkt:\n\n'Lebende Bombe' lehren\n\nIhr bekommt außerdem:\n\n"},
[78287] = {title = "Ich habe ein Angebot für Euch", objective = "Bringt Meister Holz in Stormwind die Waffenlieferung.", description = "Es ist alles zusammengepackt, <Name>. Bringt dies nach Stormwind und zeigt es einem der höheren Tiere dort. Jemandem, der heute noch unterschreiben kann!", progress = "Eine Lieferung aus Ratschet? Ich habe nichts aus Ratschet bestellt.", completion = "Ein Waffenlieferant in Ratchet? Nun... die Allianz braucht alle Vorräte, die sie bekommen kann. Und wir wollen nicht, dass die Horde einen Vertrag unterzeichnet. Wir sollten schnell handeln.", rewards = nil},
[78288] = {title = "Ich habe ein Angebot für Euch", objective = "Bringt Zel'mak in Orgrimmar die Waffenlieferung.", description = "Es ist alles zusammengepackt, <Name>. Bringt dies nach Orgrimmar und zeigt es einem der höheren Tiere dort. Jemandem, der heute noch unterschreiben kann!", progress = "Eine Lieferung aus Ratschet? Ich habe nichts aus Ratschet bestellt.", completion = "Ein Waffenlieferant in Ratchet? Hmm... die Horde versucht seit geraumer Zeit, Geschäfte mit den Goblins weg von der Allianz und stattdessen zu uns zu leiten. Wir sollten schnell handeln und uns diese neue Gelegenheit sichern.", rewards = nil},
[78297] = {title = "Vertragsabschluss", objective = "Kehrt mit dem unterschriebenen Beschaffungsvertrag zu Grizzby in Ratschet zurück.", description = "Ich habe an den entsprechenden Stellen unterschrieben, <Name>. Bringt das zurück nach Ratchet und erklärt dem Lieferanten, dass die Allianz sich darüber freut, Geschäfte mit ihm zu machen.", progress = "Habt Ihr den Handel abgeschlossen?", completion = "Sie haben unterschrieben ohne zu verhandeln? Ha! Läuft für den guten alten Grizzby!\n\nUnd Ihr, &lt;Name&gt;, Ihr habt Euch als Goldstück erwiesen. Hier, bitte, ein kleines Zeichen meiner Dankbarkeit.\n\nUnd da wir nun offiziell Geschäftspartner sind, schaut Euch ruhig ein bisschen um und lasst mich wissen, wenn Euch etwas anlacht. Ich gebe Euch sogar einen Mitarbeiterrabatt!", rewards = "Ihr bekommt:\n\nGründerzertifikat von Grizzwerks Verteidigungsvertrieb"},
[78304] = {title = "Vertragsabschluss", objective = "Kehrt mit dem unterschriebenen Beschaffungsvertrag zu Grizzby in Ratschet zurück.", description = "Ich habe den Vertrag unterschrieben und versiegelt, <Name>. Sagt diesem Goblin, dass er ab sofort ausschließlich mit der Horde zu tun hat.", progress = "Habt Ihr den Handel abgeschlossen?", completion = "Sie haben unterschrieben ohne zu verhandeln? Ha! Läuft für den guten alten Grizzby!\n\nUnd Ihr, &lt;Name&gt;, Ihr habt Euch als Goldstück erwiesen. Hier, bitte, ein kleines Zeichen meiner Dankbarkeit.\n\nUnd da wir nun offiziell Geschäftspartner sind, schaut Euch ruhig ein bisschen um und lasst mich wissen, wenn Euch etwas anlacht. Ich gebe Euch sogar einen Mitarbeiterrabatt!", rewards = "Ihr bekommt:\n\nGründerzertifikat von Grizzwerks Verteidigungsvertrieb"},
[78307] = {title = "Das Horn von Xelthos", objective = "Log", description = "Beschreibung", progress = nil, completion = "&lt;Ein Zettel liegt in der Kiste&gt;\n\nFür &lt;Name&gt;. Wir sehen uns.\n\n- C", rewards = "Ihr bekommt:\n\nRune der tödlichen Mischung"},
[78506] = {title = "Elementare Not", objective = "Sammelt Partikel elementaren Zorns und bringt sie zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental.", description = "Hört zu, <Name>. Die Korruption, von der ich zuvor gesprochen habe, betrifft mehr als nur Baron Aquanis. Ich spüre schon seit geraumer Zeit eine gewisse Unruhe in der Welt der Elementare. Ich fürchte, dass etwas im Argen liegt, und die Korruption von Baron Aquanis bestätigt lediglich meine Vermutungen.\n\nFindet hier im Eschental und dem Steinkrallengebirge in der Nähe mehr von diesen leidenden Elementaren. Bringt mir Partikel ihrer Essenz. Vielleicht kann ich sie analysieren und dadurch langsam verstehen, worin ihr Zorn gründet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[78537] = {title = "Elixier der Einsicht", objective = "Bringt ein Elixier der Wasseratmung und ein Elixier der Weisheit zu Je'neu Sancrea beim Außenposten von Zoram'gar in Eschental.", description = "Die Partikel, die Ihr gesammelt habt, sind ein bedeutender Hinweis, <Name>, doch wir werden etwas spirituelle Weisung benötigen, wenn wir die Situation komplett verstehen wollen.\n\nEs gibt ein Ritual, das ich häufig durchführe, für das ein Elixier der Einsicht benötigt wird. Die Visionen, die es gewährt, werden uns den weiteren Weg aufzeigen, den wir gehen müssen.\n\nIch kann das Elixier aus zwei anderen Elixieren brauen. Ein Elixier der Wasseratmung, um den Körper zu befreien, und ein Elixier der Weisheit, um den Geist zu öffnen.\n\nBringt sie mir, dann können wir mit dem Ritual beginnen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[78561] = {title = "Elixier der Einsicht", objective = "Trinkt das Elixier der Einsicht in der Nähe des Freudenfeuers am Außenposten von Zoram'gar und werdet Zeuge der Vision, die es Euch offenbart.\n\nBereitgestellter Gegenstand: \n", description = "Das Elixier ist bereit, <Name>. Geht runter zum Freudenfeuer am Strand und trinkt davon. Vernehmt die Vision, die die Geister Euch offenbaren, und kehrt dann mit Euren Erkenntnissen zurück zu mir.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[78575] = {title = "Hirzek", objective = "Tötet Hirzek im Schwarzdorngrat im Brachland und bringt seinen Stab zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental.", description = "Der Stacheleber, den Ihr in Eurer Vision gesehen habt. Ich glaube, das war Hirzek.\n\nDer Irdene Ring weiß schon seit geraumer Zeit von der vulgären Variante des Schamanismus der Stacheleber. Es gibt jedoch Gerüchte, dass einige von ihnen vor Kurzem beunruhigende Fortschritte erzielt haben. Hirzek ist einer dieser Stacheleber.\n\nVon dem, was Ihr gesehen habt, können wir schließen, dass er Elementare versklavt, statt mit ihnen zusammenzuarbeiten, wie wir beide es tun würden. Das sorgt auf der Ebene der Elementare zweifelsohne für Aufruhr.\n\nIhr müsst ihn aufhalten, <Name>. Zum Wohle der Schamanen und Elementare gleichermaßen.", progress = "Hirzeks Taten sind eine Beleidigung gegenüber den schamanistischen Bräuchen und den Elementen selbst. Er muss aufgehalten werden.", completion = "&lt;Je'neu nimmt den Stab in seine Hände.&gt;\n\nDas war eine große Tat von Euch, &lt;Name&gt;. Ich bin erleichtert, zu wissen, dass Hirzeks Quälereien ein Ende gefunden haben. Ich fürchte jedoch, dass er lediglich symptomatisch für eine größere Krankheit war. Es gibt noch viele weitere Elementare in Azeroth, die vor Pein nach Hilfe schreien.\n\nEs bleiben viele Fragen, die es zu beantworten gilt. Vermutlich sogar mehr, als zu Beginn unseres Unterfangens. So oder so, ich danke Euch für die Dienste, die Ihr dem Irdenen Ring erbracht habt.", rewards = "Ihr bekommt:\n\nRune des Erdschilds"},
[78611] = {title = "Eine abgefangene Lieferung", objective = "Bei dieser Lieferung fehlen einige Gegenstände, aber sie wird sich dennoch als nützlich erweisen. Vielen Dank, <Name>.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUnvollständige Vorräte aufzehren\n\nIhr bekommt:\n\n"},
[78612] = {title = "Eine komplette Lieferung", objective = "Habt Ihr etwas für mich?", description = nil, progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, &lt;Name&gt;. Diese Vorräte sind an vorderster Front unentbehrlich.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nReputation - Merchant Faction\n\nIhr bekommt:\n\n"},
[78676] = {title = "Das Auge von Bhossca", objective = "Findet das Auge von Bhossca im Scharlachroten Kloster. Kehrt dann zum toten Briefkasten von C bei Pyrewood zurück. Diesen Auftrag müsst Ihr alleine erledigen.", description = "<Eine Notiz liegt in der Truhe.>\n\nIch bin froh, dass Ihr zurück seid, <Name>.\n\nDas neueste Objekt meines Begehrens ist ein Artefakt, das als das Auge von Bhossca bekannt ist. Meine Quellen deuten darauf hin, dass das Auge irgendwo im Scharlachroten Kloster verborgen liegt. Wie bei Burg Shadowfang müsst Ihr Euch auch alleine in das Kloster schleichen.\n\nMöglicherweise müsst Ihr Euch eine Verkleidung suchen, bevor Ihr hineingeht. Damit kommt Ihr Euch etwas einfacher bewegen. Ich bin sicher, Ihr könnt etwas auf dem Klostergelände finden.\n\nBringt das Auge hierher und Eure Bezahlung wird wie gewohnt geliefert.\n\n- C", progress = "<Die Kiste ist leer.>", completion = "&lt;Ihr legt das Auge von Bhossca in die Truhe.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n[DNT] S03 - Rogue 35 Quest - Remove Quest Items"},
[78680] = {title = "Gerüchten zufolge", objective = "Über die Aufenthaltsorte dieser zertrümmerten Waffenfragmente ist nur wenig bekannt. Nur, dass die beiden Fragmente im Besitz einst großer Magier in bedeutsamen Türmen aufbewahrt werden sollen. Einer soll sich nördlich von hier auf Kalimdor und der andere soll sich nahe des Herzens der Östliche Königreiche befinden.\n\nSeht, ob die Gerüchte wahr sind... Sucht nach den beiden vermissten Hälften der Waffe und bringt sie zu mir.", description = "In den Schatten wird von einer Waffe gemunkelt, die die Seele eines mächtigen dämonischen Wesens enthält. Niedere Dämonen wie Soran'ruk sind eine Sache, doch deutlich mächtigere Entitäten, die als Bestrafung für ihr Verfehlen gebunden wurden, können unvorstellbare Macht bieten.\n\nDiese Waffe ging vor Ewigkeiten verloren. Zerschmettert während des Dritten Kriegs.\n\nNeuerdings sprechen die Gerüchte von Magiern, die sich mit dunkler Magie jenseits ihres Verständnisses einlassen und Fragmente der Waffe geborgen haben sollen. Sie sollen jedoch nicht in der Lage sein, die Mächte im Inneren freizusetzen, ohne die Waffe wiederherzustellen.", progress = "Immer noch keine Spur von den Waffenfragmenten? Ich schätze, ich habe Euch vergeblich losgeschickt.", completion = "Es gibt noch einiges zu tun, bevor ich eine Waffe dieser Macht wiederherstellen kann. Wir haben uns auf diesen Pfad begeben und nun gibt es kein Zurück mehr.", rewards = nil},
[78681] = {title = "Die Beschwörung", objective = "Sammelt 10 Einheiten Blut der Legion und führt das Ritual durch, um Des'Altek zu beschwören und dessen Seele erneut einzufangen.", description = "Der Dämon, Des'Altek, scheint aus seinem Gefängnis ausgebrochen zu sein, doch er ist nach wie vor daran gebunden, wie ein Gefangener an seine Zelle. Wir müssen den Dämon beschwören, um seine Seele erneut einzufangen.\n\nWeiter nördlich, in Ashenvale, wo große Dämonen einst fielen, gibt es einen Ort am Kamm, den die Legion einst für Opferungen genutzt hat. Der Boden ist von den grauenhaften Ereignissen, die sich dort zugetragen haben, dauerhaft gebrandmarkt. Doch wenn wir von den Dämonen, die dieses Land nach wie vor plagen, das Blut der Legion zusammentragen können... das wäre der Schlüssel.", progress = "Reicht eine Opfergabe des Blutes dar.", completion = "Benutzt den dunklen Ritualstein, um das dunkle Ritual zu beginnen. Jetzt gibt es kein Zurück...", rewards = nil},
[78684] = {title = "Geheimnisvoller Reisender", objective = "Trefft Euch mit Doan Karhan und dem geheimnisvollen Reisenden im Brachland.", description = "Was? Wo bin ich? Wie... bin ich hierhergekommen?\n\n<Der Mann vor Euch stolpert herum, als wäre er seekrank. Seine Augen weiten sich und seine Hände zittern, als Ihr Euch für einen Moment gegenseitig verwirrt anstarrt.>\n\nAh... <ein Hexenmeister/eine Hexenmeisterin>, wie ich sehe. Vieleicht besprechen wir, wie es zu dieser Reihe an Ereignissen kam, und möglicherweise finden wir heraus, was schiefgelaufen ist?\n\n<Unsicher, was Ihr als Nächstes tun sollt, schlagt Ihr vor, mit Doan Karhan zu sprechen.>", progress = nil, completion = "Interessant, in der Tat... Ich habe Euch losgeschickt, um einen Dämon zu töten, ich hätte im Leben nicht gedacht, dass Ihr mit einem Freund zurückkehrt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRaszel Ander"},
[78699] = {title = "Das Auge von Bhossca", objective = "Log", description = "Beschreibung", progress = nil, completion = "&lt;Ein Zettel liegt in der Kiste&gt;\n\nFür &lt;Name&gt;. Ich halte ein \"Auge\" nach Euch offen.\n\n- C", rewards = "Ihr bekommt:\n\nRune des Schattenschritts"},
[78702] = {title = "Raszel Ander", objective = "Raszel war ein Freund... einer, von dem ich dachte, ich hätte ihn vor langer Zeit verloren... Damals waren wir junge Lehrlinge... Vieles hat sich geändert.\n\nDer Ausgang des Rituals mag ein Rückschlag gewesen sein, aber ich glaube, wir können die Waffe immer noch rekonstruieren.\n\nRaszel und ich haben viel zu besprechen, gemeinsam werden wir einen Plan schmieden. Ich lasse nach Euch schicken, wenn wir wissen, wie wir weitermachen.\n\nIn der Zwischenzeit, nehmt das. Ich glaube, Ihr könntet daran interessiert sein.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRune der Metamorphose"},
[78823] = {title = "Schrecken des Wüstenhimmels", objective = "Bring die einfache Zeichnung zu Hemet Nesingwary im Schlingendorntal.", description = "Die Zeichnung besteht aus groben, breiten Strichen und schient einen großen Raubvogel darzustellen. Trotz der einfachen Darstellung hat der Künstler diese Kreatur eindeutig mir Furcht und Bewunderung betrachtet. Ein Experte für Großwild könnte Euch bestimmt mehr verraten.", progress = nil, completion = "Aber hallo. Das ist mal interessant...", rewards = "Ihr bekommt:\n\n"},
[78830] = {title = "Schrecken des Wüstenhimmels", objective = "Holt Euch eine blutrote Trophäenfeder von Gharrik im Ödland. Kehrt anschließend zu Hemet Nesingwary im Schlingendorntal zurück.", description = "Diese Zeichnung erinnert mich an eine Geschichte, die ich auf einer anderen Expedition vor nicht allzu langer Zeit gehört habe. Man erzählte mir von einem großen Vogel, Gharrik, der als Alpharaubtier über die Ödlande herrscht.\n\nEr wurde zuletzt nordöstlich von Camp Cagg gesehen. Vielleicht ist sein Nest irgendwo in der Nähe?\n\nIhr werdet Lebendköder brauchen, wenn Ihr ihn hervorlocken wollt. Ich werde Euch einen Käfig leihen, um welchen zu fangen. Kleine Wildtiere sind im Ödland selten, ihr werdet Euren Köder also anderswo suchen müssen.\n\nEine Feder von Gharrik wäre eine gute Trophäe. Man würde sich sicherlich Geschichten von Euch im Lager erzählen.", progress = "Wie läuft die Jagd? Der Vogel hat Euch doch sicher nicht überlistet!", completion = "Jetzt habt Ihr eine Feder für Eure Kappe! Gut gemacht, &lt;Name&gt;.\n\nIhr könnt Euch hier eine Weile ausruhen, wenn Ihr wollt. Ich bin sicher, Eure Wanderung durch die Wüste war beschwerlich.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n[DNT] S03 - 40 - Hunter 40 Quest - Remove Quest Items\n\nIhr bekommt:\n\nRune der aufgedeckten Schwäche"},
[78872] = {title = "Eine komplette Lieferung", objective = "Habt Ihr etwas für mich?", description = nil, progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, &lt;Name&gt;. Diese Vorräte sind an vorderster Front unentbehrlich.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nReputation - Merchant Faction\n\nIhr bekommt:\n\n"},
[78909] = {title = "Veränderlicher Schuppentalisman", objective = "Bringt N'ora Jederherz die folgenden Materialien und eine Handvoll veränderliche Schuppen, um den Talisman fertigzustellen: 1 Beutel mit seltsamem Staub, 5 große Magieessenzen, 2 kleine gleißende Splitter und 5 Goldstücke.", description = "Ich brauche eine... erhebliche Menge Materialien für den Talisman.\n\n<N'ora lächelt euch verschlagen an>", progress = "Ich gebe zu, dass ich mich nicht besonders gut in Verzauberkunst auskenne, aber ich glaube, ich verstehe ungefähr, wie der Prozess funktioniert. In der Theorie zumindest.", completion = "Ich wünsche Euch alles Gute auf Euren Abenteuern und hoffe, Ihr findet den Weg zu mir zurück, solltet Ihr weitere wundersame Entdeckungen wie diese machen!", rewards = "Ihr bekommt:\n\nVeränderlicher Schuppentalisman"},
[78914] = {title = "Seelengefäß", objective = "Jetzt, da wir einen Weg kennen, den Dämon zu schwächen, brauchen wir ein Gefäß, in das wir ihn binden können. Die Brennende Klinge hat antike elfische Ruinen im Süden von Desolace überrannt und nutzt sie jetzt als Beschwörungsplatz, um Dämonen nach Azeroth zu rufen.\n\nWenn Ihr ein Seelengefäß gefunden habt, trefft uns in Desolace. Dort werden wir das Ritual vollenden.", description = "Gobliningenieure haben versucht, einen synthetischen Seelenstein herzustellen, aber ihre Methoden waren plump, gelinde gesprochen. Doch trotz ihrer Fehler sind sie auf der richtigen Spur.\n\nIch habe gehört, dass die Goblins einer Fraktion von Händlern die Rechte für das Rezept abgeluchst haben. Es ist unwahrscheinlich, dass sie wissen, dass das Seelengefäß an sich keine magischen Kräfte birgt. Jemand will das Muster bestimmt gegen einige Münzen loswerden wollen.", progress = "Mit dem Zweig der Schatten und dem Seelengefäß können wir das Ritual beginnen.", completion = "Ah, ja... ja! Das ist genau, was wir brauchen!", rewards = "Ihr bekommt:\n\n"},
[78916] = {title = "Herz der Leere", objective = "Bringt die Blackfathom-Perle zu Dämmerungsbehüter Selgorm in Darnassus.", description = "Die Schreckensbestie Aku'mai wurde getötet. In den Eingeweiden ihres angeschwollenen Leichnams ist eine gewaltige schillernde Perle versteckt, die geradezu vor roher Leerenenergie strotzt.", progress = "<Name>, welche Neuigkeiten bringt Ihr aus Blackfathom?", completion = "Aku'mai, Dienerin der Alten Götter, ist tot. Eine Errungenschaft, wie sie nur wahre Helden vollbringen können.\n\nDieser Gegenstand könnte uns zu einem deutlich besseren Verständnis der Beschaffenheit der Leere und ihrer Auswirkungen auf unsere Welt verhelfen. Wir müssen ihn umgehend erforschen. Vielen Dank, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLeerenperle des AkolythenLeerenperle des HerbeirufersLeerenperle des Rächers"},
[78917] = {title = "Herz der Leere", objective = "Bringt die Blackfathom-Perle zu Bashana Runetotem in Thunder Bluff.", description = "Die Schreckensbestie Aku'mai wurde getötet. In den Eingeweiden ihres angeschwollenen Leichnams ist eine gewaltige schillernde Perle versteckt, die geradezu vor roher Leerenenergie strotzt.", progress = "<Name>, welche Neuigkeiten bringt Ihr aus Blackfathom?", completion = "Aku'mai, Dienerin der Alten Götter, ist tot. Ihr habt den Einwohnern Kalimdors mit dieser Tat einen enormen Dienst erwiesen.\n\nDie Perle könnte uns zu einem deutlich besseren Verständnis der Beschaffenheit der Leere und ihrer Auswirkungen auf unsere Welt verhelfen. Wir müssen sie umgehend erforschen. Geht mit der Erdenmutter, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLeerenperle des AkolythenLeerenperle des HerbeirufersLeerenperle des Rächers"},
[78920] = {title = "Baron Aquanis", objective = "Bringt die seltsame Wasserkugel zu Je'neu Sancrea beim Zoram'gar-Außenposten in Ashenvale.", description = "Der besiegte Wasserelementar hat eine seltsame Wasserkugel zurückgelassen. Ihr vermutet, dass das Objekt die Kreatur irgendwie mit Energie versorgte. In der Kugel schwappt eine faulig aussehende Wassergestalt herum. Die Kugel selbst zeigt sich unbeeindruckt von jeder äußerlichen Krafteinwirkung.\n\nWenn irgendwer aus diesem Gegenstand schlau wird, wäre das wohl Je'neu Sancrea vom Irdenen Ring. Er befindet sich beim Zoram'gar-Außenposten der Horde in Ashenvale.", progress = "Ach, hallo, <Name>. Ich habe gerade in den Wellen der See gelesen, wie ich es immer tue. Was führt Euch in den Außenposten?", completion = "Das... Das ist ein wichtiger Fund, &lt;Name&gt;.\n\nIhr habt dies von Baron Aquanis aus Blackfathom, sagt Ihr? Man hatte Baron Aquanis schon lange im Verdacht, eine verderbte Elementarkraft zu sein. Diese Kugel wird zeigen, was genau ihn verdorben hat. Es würde mich nicht im Geringsten überraschen, wenn es sich dabei um die Twilight-Hammer handelt. Aber unsere Studien werden auch aufzeigen, wie sie das getan haben.\n\nIhr habt das Richtige getan, indem Ihr dies zu mir brachtet. Bitte, nehmt dies zusammen mit den wärmsten Empfehlungen des Irdenen Rings.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesetzlosensäbelHexenfinger\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[78921] = {title = "Schurkerei in Blackfathom", objective = "Bringt den Kopf von Twilight-Lord Kelris zu Dämmerungsbehüter Selgorm in Darnassus.", description = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.\n\nDie Kultisten der Twilight-Hammer haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'mai, um Macht zu erlangen.\n\nBitte, tötet Kelris und bringt Selgorm in Darnassus seinen Kopf, <Name>.", progress = "Zeit ist ein kostbares Gut, <Klasse>.\n\nMeine Rolle hier in Darnassus ist es, sicherzustellen, dass die Argentumdämmerung gedeiht und die bösen Mächte aus Kalimdor vertrieben werden.\n\nSagt rasch, was Euer Begehr ist, oder zieht von dannen.", completion = "Kelris entwischt uns schon seit geraumer Zeit.\n\nOffenbar ist Kelris stets dabei, wenn das Böse in dieser Region sein hässliches Haupt erhebt. Eine Zeit lang hielten wir ihn für tot oder vermisst.\n\nDoch dies scheint logisch zu sein. Als Ihr seine Herrschaft beendet habt, habt Ihr vielen Unschuldigen das Leben gerettet.\n\nBeim Licht! Es ist mehr als schändlich, jemanden den Dienern eines Alten Gottes zu opfern, um persönlich Kapital daraus zu schlagen!\n\nIhr habt eine große Tat vollbracht, &lt;Name&gt;. Ich salutiere im Namen der Argentumdämmerung vor Euch.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGraviertes GrabsteinszepterUralter arktischer Rundschild\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[78922] = {title = "Schurkerei in Blackfathom", objective = "Bringt den Kopf von Twilight-Lord Kelris zu Bashana Runetotem in Thunder Bluff.", description = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.\n\nDie Kultisten der Twilight-Hammer haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'mai, um Macht zu erlangen.\n\nBitte, tötet Kelris und bringt Bashana in Thunder Bluff seinen Kopf, <Name>.", progress = "Möge die Erdenmutter mit Euch sein, <Name>.\n\nUnser Ziel sollte Friede auf der Erde sein und unter denen, die sie bewohnen. Sie hat große Pläne mit der Natur und wir alle müssen unsere Rolle in diesem Plan spielen.", completion = "Kelris hat sich der Argentumdämmerung eine ganze Weile entzogen.\n\nEine Zeit lang galt er sogar als tot oder vermisst.\n\nIndem Ihr seinem Regime ein Ende gemacht habt, habt Ihr die Leben vieler Unschuldiger gerettet, &lt;Name&gt;.\n\nGelobt sei die Erdenmutter! Jemanden einem Diener eines Alten Gottes zu opfern, um persönlich davon zu profitieren, ist mehr als verachtenswert!\n\nHeute habt Ihr etwas Großes geleistet! Kelris war eine Kreatur des Bösen und trachtete danach, die Welt wieder in eine Zeit des Chaos zu stürzen, indem er einem der Alten Götter huldigte. Danke, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGraviertes GrabsteinszepterUralter arktischer Rundschild\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[78923] = {title = "Wissen in der Tiefe", objective = "Bringt das Manuskript von Lorgalis zu Gerrig Bonegrip in Ironforge.", description = "Wie Ihr vielleicht wisst, trage ich Lehren zusammen. Alte Lehren. Mächtige Lehren. Lehren, die Portale öffnen, und Lehren, die die Schlafenden erwecken können.\n\nEs kursieren Gerüchte um einen alten Teil einer Lehre, das \"Manuskript von Lorgalis\", das sich tief unten in der Blackfathom-Tiefe in Ashenvale befinden soll. Dieser Ort ist die ehemalige Heimat längst verstorbener Elfen. Elfen, die über großes Wissen verfügten, bevor ihre Stadt zerfiel.\n\nSucht in der Blackfathom-Tiefe nach dem Manuskript. Wenn Ihr das tut, werde ich Euch das nie vergessen. Auch nicht... nach dem Ende aller Tage.", progress = "Die Reise nach Ashenvale ist lang und Eure Aufgabe ist nicht leicht. Aber wenn Ihr mir das Manuskript bringt, <Name>...dann werde ich Euch fürstlich belohnen.", completion = "Ihr habt das Manuskript gefunden! Was für ein Freudentag! Wir werden es nachdrucken und verteilen, und dann können auch meine Brüder und Schwestern endlich des alten Wissens von Lorgalis teilhaftig werden!\n\nIhr habt uns mehr geholfen, als Ihr ahnt, &lt;Name&gt;. Ich hoffe jedoch, dass dieses Geschenk Euch zeigt, wie dankbar wir uns unseren Verbündeten erweisen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nEwig erhaltender Ring"},
[78924] = {title = "Auf der Suche nach Thaelrid", objective = "Sucht Argentumwache Thaelrid in der Blackfathom-Tiefe auf.Heutzutage kursieren viele Gerüchte über die Vereinigung der Twilight-Hammer und Naga in der Blackfathom-Tiefe an den Küsten von Ashenvale.\n\nMeine Rolle hier bei der Argentumdämmerung besteht darin, so viele Informationen wie möglich zu sammeln, damit wir wissen, wann und wo Hilfe erforderlich ist.\n\nEs ist jetzt Wochen her, seit ich einen Späher losschickte, um die Aktivitäten in der Blackfathom-Tiefe auszuspähen. Argentumwache Thaelrid hat sich noch nicht zurückgemeldet.\n\nMeine anderen Späher sind mit dringenden Angelegenheiten beschäftigt.\n\nSucht und unterstützt Thaelrid für mich, <Name>.Der folgende Zauber wird auf euch gewirkt:\n\n", description = "Heutzutage kursieren viele Gerüchte über die Vereinigung der Twilight-Hammer und Naga in der Blackfathom-Tiefe an den Küsten von Ashenvale.\n\nMeine Rolle hier bei der Argentumdämmerung besteht darin, so viele Informationen wie möglich zu sammeln, damit wir wissen, wann und wo Hilfe erforderlich ist.\n\nEs ist jetzt Wochen her, seit ich einen Späher losschickte, um die Aktivitäten in der Blackfathom-Tiefe auszuspähen. Argentumwache Thaelrid hat sich noch nicht zurückgemeldet.\n\nMeine anderen Späher sind mit dringenden Angelegenheiten beschäftigt.\n\nSucht und unterstützt Thaelrid für mich, <Name>.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[78925] = {title = "Die Twilight fallen", objective = "Bringt 10 Twilight-Anhänger zu Argentumwache Manados in Darnassus.", description = "Mit der Macht der uralten Rituale der chaotischen Alten Götter versuchen die Mitglieder der Twilight-Hammer, ihre dunklen Schutzherren zurückzuholen und Tod und Schrecken in der Welt zu verbreiten.\n\nWir glauben, dass die Twilight-Hammer sich mit den Naga verbündet haben und sich in der Blackfathom-Tiefe an den Küsten von Ashenvale zusammenrotten.\n\nWelch schändliche Pläne in den Tiefen des alten Tempels auch immer geschmiedet werden, wir müssen sie vereiteln.\n\nFührt Krieg gegen die Hammer und bringt Beweise Eurer Taten mit. Eure Bemühungen sollen reich belohnt werden.", progress = "Die Blackfathom-Tiefe war einst ein alter Tempel der Nachtelfen. Ehedem befand sich einer der mächtigsten Mondbrunnen darin. Wer weiß, welches Übel die Twilight-Hammer jetzt dort ausbrüten?\n\nHabt Ihr schon Fortschritte bei ihrer Vertreibung erzielt?", completion = "Ihr seid zweifellos von tapferem und edlem Geblüt, &lt;Name&gt;. Die Argentumdämmerung dankt Euch für Euren Einsatz gegen das Böse.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nNimbusstiefel der EinsichtHerzholzgurt des Pflegers\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[78926] = {title = "Erforschung der Verderbnis", objective = "Gershala Nightwhisper in Auberdine möchte 8 verderbte Hirnstämme.", description = "Törichte Blutelfen spielen mit Dämonenmagie. Wurden sie nicht Zeugen, was mit den Naga und den Satyrn von Kalimdor geschehen ist?\n\nIch fürchte, die Blutelfen werden auf ähnliche Weise deformiert. Azeroth darf kein weiteres Volk abscheulicher Monster hervorbringen.\n\nIch möchte die Hirnstämme der Satyrn und Naga untersuchen, damit ich daraus folgern kann, welches Schicksal die Elfen erwartet. In der Blackfathom-Tiefe an der Küste Ashenvales werdet Ihr sowohl Satyrn als auch Naga finden.\n\nEs ist eine lange Reise, <Name>.", progress = "Wenn ich genügend Proben habe, kann meine wahre Arbeit beginnen. Mit den verderbten Hirnstämmen der Satyrn und Naga der Blackfathom-Tiefe kann ich versuchen, einen Zusammenhang zwischen den Mutationen zu finden.\n\nMit diesem Wissen verhindern wir vielleicht, dass die Blutelfen noch deformierter und böser werden.", completion = "Ihr seid weit gereist und habt zweifellos großen Gefahren getrotzt.\n\nEure Taten waren selbstlos. Es dient ganz Azeroth, wenn Ihr mir bei meinen Forschungen helft. Ich danke Euch für alles, was Ihr getan habt, &lt;Name&gt;.\n\nWenn Ihr mich nun entschuldigen wollt, ich habe viel Arbeit...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZirpende KäferschnallenAbgenutztes Prälaturencape\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[78927] = {title = "Treue zu den Alten Göttern", objective = "Tötet Lorgus Jett in der Blackfathom-Tiefe und kehrt dann zu Je'neu Sancrea in Ashenvale zurück.", description = "Dieser Anhänger der Twilight-Hammer darf seinen Plan nicht in die Tat umsetzen. Die Twilight-Hammer verstehen die Geister der Natur nicht. Sie glauben an die Alten Götter - Kreaturen des Chaos und der Zerstörung, die vor langer Zeit besiegt wurden. Dieser Lorgus darf keinen Erfolg haben. Ihr müsst ihn aufhalten, <Name>. Ich kann mich leider nicht selbst darum kümmern... ich bin zu schwach.\n\nGeht zur Blackfathom-Tiefe, findet ihn und tötet ihn. Kommt zu mir nach Zoram'gar zurück, wenn Ihr es geschafft habt.", progress = nil, completion = "Sehr gut! Danke, &lt;Name&gt;. Wir mögen zwar die Twilight-Hammer nicht vollständig aufgehalten haben, aber zumindest habt Ihr einen weiteren ihrer Pläne durchkreuzt, die Alten Götter wieder mächtig zu machen.\n\nWer weiß, welche Pläne sie sonst noch verfolgen mochten, aber wir können vorerst beruhigt sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand der EisenfaustZerfetzter kastanienbrauner Mantel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[78994] = {title = "Eine solide Grundlage", objective = "Die Smaragddrachen schützen mehrere Portale in den Smaragdgrünen Traum in ganz Azeroth. An einem dieser Orte ist sicher zu finden, was wir brauchen.\n\nWenn Ihr einen Zweig der Schatten gefunden habt, kommt so schnell wie möglich hierher zurück.", description = "Die Waffe neu zu schmieden, hat sich als Herausforderung herausgestellt, und es ist immer noch unklar, wie das Ritual scheitern konnte, aber ich glaube, wir haben eine alternative Lösung gefunden.\n\nUm anzufangen, brauchen wir eine solide Basis, einen Zweig der Schatten.\n\nDiese Bäume sind bösartige Gewächse, die aus dem Smaragdgrünen Alptraum in unsere Welt herübersickern. Es heißt, sie schwächen den Willen derer in ihrer Umgebung. Diese magische Eigenschaft wird die Grundlage für den Bau dieser Waffe sein.\n\nDieser Trank wird Euch bei Eurer Suche helfen. Er wird Euch vor den Dienern der Smaragddrachen verbergen.", progress = "Niemand hat behauptet, es wäre ein einfaches Unterfangen, aber das sind die wenigsten Dinge, die es wert sind.", completion = "Ah, ja, Ihr habt ihn gefunden! Euer Verstand scheint auch noch intakt zu sein. So weit, so gut.", rewards = "Ihr bekommt:\n\n"},
[79007] = {title = "...und diese Notiz, die Ihr gefunden habt.", objective = "Die verkohlten Überreste der Notiz dienen Euch als einziger Wegweiser.", description = "Ihr stolpert über die noch frischen Überreste eines Feuers, dessen schwaches Leuchten der Glut weiter nachlässt.\nInmitten der verstreuten Vorräte entdeckt Ihr eine fast verbrannte Notiz.\n\"Nicht alles, was brennt, ist verloren. Findet das Zwillingsland, findet den Ort.\"", progress = nil, completion = "Als Ihr über die Überreste einer weiteren verkohlten Leiche stolpert, fällt Euer Blick auf eine Notiz, die an einer Holzplanke befestigt ist.", rewards = "Ihr bekommt:\n\nHurtigkeitstrankStarker Trollbluttrank"},
[79008] = {title = "...und diese Notiz, die Ihr gefunden habt.", objective = "Die verkohlten Überreste der Notiz dienen Euch als einziger Wegweiser.", description = "Ihr stolpert über die noch frischen Überreste eines Feuers, dessen schwaches Leuchten der Glut weiter nachlässt.\nInmitten der verstreuten Vorräte entdeckt Ihr eine fast verbrannte Notiz.\n\"Nicht alles, was brennt, ist verloren. Findet das Zwillingsland, findet den Ort.\"", progress = nil, completion = "Als Ihr über die Überreste einer weiteren verkohlten Leiche stolpert, fällt Euer Blick auf eine Notiz, die an einer Holzplanke befestigt ist.", rewards = "Ihr bekommt:\n\nHurtigkeitstrankStarker Trollbluttrank"},
[79077] = {title = "Gemeinsamer Glaube", objective = "Meditiert über das Licht und betet dann mit dem knieenden Elfen, um Eure Meditation zu teilen.", description = "Das Licht ruft uns zu Gerechtigkeit und Schutz auf, aber auch zu Barmherzigkeit. Unsere Verbündeten sind fremd in diesen Landen und wir haben die Pflicht, ihnen unsere Gepflogenheiten näherzubringen.\nDieser Nachtelf sucht das Licht, hat jedoch Probleme bei der Meditation. Würde Ihr ihm helfen?", progress = nil, completion = "Das Licht bringt seine Segen durch Euch zum Vorschein, &lt;Name&gt;. Ehrt das, indem Ihr Eure Weisheit mit allen Bittstellern teilt, die Euch auf Euren Reisen begegnen.", rewards = "Ihr bekommt:\n\n"},
[79078] = {title = "Gemeinsamer Glaube", objective = "Meditiert über Elune und betet dann mit dem knieenden Menschen, um Eure Meditation zu teilen.", description = "Dieser Mensch greift nach Elunes Licht, doch seine Sicht ist getrübt. Könntet Ihr ihm helfen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[79079] = {title = "Gemeinsamer Glaube", objective = "Meditiert über die Loa und betet dann mit dem knieenden Verlassenen, um Eure Meditation zu teilen.", description = "Dieser arme Priester der Verlassenen scheint keinen Loa zu finden, der mit ihm handeln möchte. Vielleicht könntet Ihr ihm stattdessen einen Segen geben?", progress = nil, completion = "Die Untoten sind bei den Loa nicht sonderlich beliebt, aber es ist gut von Euch, diesem auszuhelfen. Versucht, etwas Mitgefühl zu zeigen, wenn Ihr unterwegs mehr von ihnen trefft, okay?", rewards = "Ihr bekommt:\n\n"},
[79080] = {title = "Gemeinsamer Glaube", objective = "Meditiert über den Untod und betet dann mit dem knieenden Troll, um Eure Meditation zu teilen.", description = "Dieser Troll versucht, über den Tod zu reflektieren, allerdings fehlt es ihm an einer gewissen... Vertrautheit mit der Thematik. Helft ihm bitte dabei, es besser zu verstehen.", progress = nil, completion = "Meiner Erfahrung nach, ist unser Volk bestenfalls eine Kuriosität für den Rest der Horde. Dennoch, unser Wissen zu Teilen, ist eine einfache Methode, uns ihr Vertrauen zu verdienen. Behaltet das auf Euren Reisen im Kopf.", rewards = "Ihr bekommt:\n\n"},
[79090] = {title = "Eindringlinge abwehren", objective = "Bringt das Abzeichen der Warsongvorhut zur Mondpriesterin Felore Mondschein in der Mondbrunnenbasis in Ashenvale.", description = "Einige Mitglieder der Warsongvorhut wurden besiegt, doch die Schlacht geht weiter...", progress = "<Name>, welche Neuigkeiten bringt Ihr von der Front?", completion = "Die Eindringlinge der Horde beschmutzen nach wie vor unsere Lande und stehlen von unserer heiligen Wildnis. Werft sie weiterhin hinaus!\n\nDiese heilige Kampfeshymne kann Euch inspirieren, sie mit noch größerer Entschlossenheit zu bekämpfen. Vielen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSchlachthymne der Silverwing"},
[79091] = {title = "Erzmagier Antonidas: Die ungekürzte Autobiografie", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Vielen Dank, &lt;Name&gt;. Ihr sagtet, das sei aus der Bibliothek in Ironforge? ...Ich bin sicher, sie werden es nicht vermissen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[79092] = {title = "Forschungsaufzeichnungen von Erzmagier Theocritus", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[79093] = {title = "Rumi von Gnomeregan: Die gesammelten Werke", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[79094] = {title = "Die Lehren von Ta'zo", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[79095] = {title = "Metaphysische Fibel des Apothekers", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[79096] = {title = "Ataeric: Arkane Merkwürdigkeiten", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[79097] = {title = "Baxtan: Über zerstörerische Magie", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[79098] = {title = "Haltet den Wald frei!", objective = "Bringt das Amulett der Schildwache der Silverwing zu Scharfseher Kazragore in der Freudenfeuerbasis in Ashenvale.", description = "Der hier wurde besiegt, doch diese ärgerliche Allianz kämpft nach wie vor weiter... Was ist das für ein Amulett?", progress = "<Name>, welche Neuigkeiten bringt Ihr von der Front?", completion = "Diese Hunde von der Allianz halten uns weiterhin davon ab, die Ressourcen für Orgrimmar zu sammeln. Treibt sie weiterhin hinaus!\n\nDiese Warsongkampftrommel wird Euch inspirieren, mit noch größerer Entschlossenheit gegen sie anzukämpfen. Lok'tar ogar, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nWarsongkampftrommel"},
[79099] = {title = "Baron Aquanis", objective = "Bringt die seltsame Wasserkugel zu Davius Leerenstern in Auberdine an der Dunkelküste.", description = "Seid gegrüßt, <Klasse>. Ich habe von den Ortsansässigen überaus kuriose Geschichten über einen großen, verderbten Wasserelementar namens Baron Aquanis gehört, der in der Nähe des Eingangs der als Blackfathom-Tiefe bekannten Nachtelfenruine Wache steht. Ich bin hier, um Abenteurer anzuheuern, die genug Mumm haben, den Kern von Baron Aquanis zu bergen, eine Kugel verderbten Wassers. Im Austausch wäre ich bereit, Euch Zugang zu einem Portal direkt an den Zoramstrand zu gewähren, das ich zur Erkundung der Landschaft um die Ruinen herum nutze... aus sicherer Distanz, natürlich.", progress = "Ah, hallo, <Name>. Konntet Ihr die Kugel bergen?", completion = "Hmm, überaus kurios. Das... ist nicht, was ich erwartet hatte. Nun, dennoch vielen Dank. Versprochen ist versprochen. Ihr dürft ab sofort mein Portal an den Zoramstrand verwenden.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[79100] = {title = "Eine abgefangene Lieferung", objective = "In dieser Lieferung fehlen einige Gegenstände, aber sie wird sich dennoch als nützlich erweisen. Vielen Dank, <Name>.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUnvollständige Vorräte aufzehren\n\nIhr bekommt:\n\n"},
[79101] = {title = "Eine komplette Lieferung", objective = "Habt Ihr etwas für mich?", description = nil, progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, &lt;Name&gt;. Diese Vorräte sind an vorderster Front unentbehrlich.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nReputation - Merchant Faction\n\nIhr bekommt:\n\n"},
[79102] = {title = "Eine komplette Lieferung", objective = "Habt Ihr etwas für mich?", description = nil, progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, &lt;Name&gt;. Diese Vorräte sind an vorderster Front unentbehrlich.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nReputation - Merchant Faction\n\nIhr bekommt:\n\n"},
[79103] = {title = "Eine komplette Lieferung", objective = "Habt Ihr etwas für mich?", description = nil, progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, &lt;Name&gt;. Diese Vorräte sind an vorderster Front unentbehrlich.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nReputation - Merchant Faction\n\nIhr bekommt:\n\n"},
[79192] = {title = "Trittsteine", objective = "Ihr reißt die Notiz von der Planke und lest die verschmierte Schrift.", description = "Die Notiz beginnt folgendermaßen: \"Die Mission besagt, dass sie beide Lieferungen für die neue Seuche erledigt hätten. Auf mich haben sie jedoch eher wie einfache Apothekerunfälle gewirkt. Findet meinen gemütlichen Platz in den Bergen zwischen dem Brachland und Desolace, wenn Ihr einen sicheren Ort zum Reden sucht.\"", progress = nil, completion = "Zweifellos schlagen Abenteurer und Söldner aus dem Hinterland hier ihr Lager auf. Die Ecke einer im Wind flatternden Notiz fällt Euch ins Auge und Ihr greift danach.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSpitzhackeBauernschaufel\n\nIhr bekommt außerdem:\n\nStabile VesperdoseEinfaches HolzFeuerstein und ZunderStabile Vesperdose"},
[79229] = {title = "Straßenraub", objective = "Findet jemanden in Desolace, der etwas über das geplünderte Lager weiß.", description = "Der Lagerplatz vor Euch sieht grausig aus. Den Überresten nach zu schließen, waren die Opfer zwei Menschen und ein Zwerg. Spuren auf den Knochen deuten auf einen schweren Angriff hin, aber die gestohlenen Vorräte sagen Euch, dass es keine wilden Tiere waren. Die Wunden passen auch nicht zu den Waffen der Zentauren.\n\nVielleicht weiß ein erfahrener Plünderer dieses Landes mehr.", progress = nil, completion = "Ah, Ihr habt also noch eine gefunden...", rewards = "Ihr bekommt:\n\n"},
[79235] = {title = "Auf der Flucht", objective = "Findet einen der Plünderer von Desolace.", description = "Ich habe einige Szenen, wie Ihr sie beschreibt, gefunden, <Name>. Es sind immer Lager von Menschen und Zwergen. Es gibt Gerüchte unter den Karawanen, dass es eine Gruppe von Plünderern der Horde war. Den Opfern und der Brutalität der Angriffe nach zu urteilen, scheint das wahrscheinlich.\n\nAnscheinend sind die Banditen nach Desolace geflohen, nachdem ein Marschall der Allianz ihnen auf die Spur gekommen ist.\n\nIch würde es mit einer Hafenstadt versuchen, wenn Ihr einen von ihnen aufspüren wollt. Da wimmelt es immer von zwielichtigen Gestalten. Vielleicht erwischt Ihr einen beim Versuch, ein Boot nach irgendwo zu bekommen.", progress = nil, completion = "Braucht ihr etwas? Macht es kurz.", rewards = "Ihr bekommt:\n\n"},
[79236] = {title = "Eine Kirsche für Eure Gedanken", objective = "Bringt einen Kirschgrog zu Tokal in Booty Bay, um den Rest ihrer Geschichte zu hören.", description = "Gehört Ihr zu dem Marschall? Nein, so seht Ihr nicht aus.\n\nDie Gerüchte, die Ihr gehört habt, sind nur zur Hälfte wahr. Ja, wir haben Lager der Menschen und Zwerge geplündert, aber wir haben es nicht für die Horde getan. Wir wurden privat angeheuert.\n\nIch erzähle Euch die ganze Geschichte, wenn Ihr mir einen Grog ausgebt.", progress = "Wo bleibt mein Grog?", completion = "Ah, genau das brauche ich jetzt. Also, wo war ich?", rewards = "Ihr bekommt:\n\n"},
[79242] = {title = "Keine Ehre unter Dieben", objective = "Findet Illari Dämmerfeder in der Nähe des Arathihochlands und erhaltet Zugriff auf ihre Sammlung gestohlener Beute.", description = "Wie gesagt...\n\nUnser Boss war nicht von der Horde. Sie war eine Nachtelfe namens Illari Dämmerfeder. Sie hat uns Informationen zu den Lagern gegeben und uns das meiste der Beute behalten lassen. Sie hat nur einige der wertvolleren Funde behalten.\n\nAls der Marschall uns auf die Spur gekommen ist, hat sie uns zurückgelassen. Ich kenne ihre Motive nicht, aber ich glaube, wir sollten als Sündenbock herhalten.\n\nIch bin nicht nachtragend, aber ich würde niemanden aufhalten, der sie finden will. Wenn Ihr sie sucht, sie hat einmal von einem Versteck irgendwo in der Nähe des Arathihochlands gesprochen.", progress = "<Benutzt Illaris Schlüssel, um die Truhe aufzuschließen.>", completion = "&lt;Im Inneren der Truhe findet Ihr eine kleine Schatulle und einige Münzen.&gt;", rewards = "Ihr bekommt:\n\nJuwelenbesetzte Schatulle"},
[79298] = {title = "Das Schicksal herausfordern", objective = "Unterstützt Raszel Ander und Doan Karhan beim Beschwörungsritual und schließt Des'Altek im Stab ein.", description = "Ihr könnt die üble Magie sehen, die das Wasser vergiftet und ihm einen violetten Schimmer verleiht. Die Brennende Klinge hat dieses Gebiet mit dunkler Magie überwältigt.\n\nWir werden diesen Opferaltar verwenden, den sie für ihre Beschwörungsrituale nutzen. Wir können die dunkle Energie in der Gegend nutzbar machen, um unser Ritual zu verstärken.", progress = nil, completion = "Von all den Dingen, die Raszel Ander war, hätte ich ihn am wenigsten als herrisch bezeichnet. Für einen &lt;Klasse&gt; war er immer eher auf der sanftmütigen Seite. Ich dachte mir bereits, dass etwas nicht stimmt, als dieser Betrüger während Eures Beschwörungsrituals zurückkam. Das war auch der Grund, weshalb ich weitere Akolythen zur Unterstützung herbeigerufen habe, doch es waren nicht genug... Erneut haben wir versagt, unsere Beute zu fangen.\n\nLeider ist der Stab während Eures Kampfes zerbrochen und alles, was ich tun konnte, war hilflos dazustehen und zuzuschauen... Doch in den Trümmern habe ich das hier gefunden.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDesolaceritual\n\nIhr bekommt:\n\nEndloses SeelengefäßRune der Synergie"},
[79348] = {title = "Das verlorene Urtum", objective = "Findet jemanden, der Euch etwas zum verdorbenen Samen erzählen kann.", description = "Ein fauliger Samen ist alles, was von dem wandernden Urtum übrig ist. Seine äußere Hülle ist brüchig und das Innere gibt einen fauligen Geruch von sich.\n\nGemessen an seiner Größe, muss das Urtum, von dem dieser Samen stammt, recht jung gewesen sein. Zumindest für ein Urtum. Da stellt sich einem die Frage, weshalb ein solches Geschöpf durch den Morast wandelt.\n\nUm Antworten zu bekommen, solltet Ihr Euch an jemanden wenden, der sich mit der Geschichte der Urtume auskennt.", progress = nil, completion = "Ah, ein weiteres junges Leben verloren...", rewards = "Ihr bekommt:\n\n"},
[79358] = {title = "Zerfledderte Notiz", objective = "Warnt die Einwohner von Tausend Nadeln davor, was Ihr in Erfahrung gebracht habt.", description = "<Ihr entfaltet ein zerfleddertes Pergament, auf dem steht:>\n\nDie Tunnel haben die Klippen oberhalb von Tausend Nadeln erreicht und unsere Vorbereitungen blieben unbemerkt. Doch wir müssen rasch handeln. Entsendet Eure Schamanen. Nach allem, was Hirzek erreicht hat, sind wir bereit, zu beginnen.\n\nDer Sturm wird toben, der Boden wird erbeben und die Flut werde ansteigen, auf dass nur Leichen zurückbleiben, die wir auf unserem Pfad wiederbeleben können. Ihre Knochen werden einen Pfad in...\n\n<Die Nachricht endet mitten im Satz, weil der Rest der Seite fehlt.>", progress = nil, completion = "&lt;Hrmpf... Der große Tauren schnaubt, während er das Pergament liest.&gt;\n\nEins ist sicher... Wer immer diese Notiz geschrieben hat, hatte recht: Wir haben nichts von ihren Vorbereitungen mitbekommen. Wir haben mit den Zentauren und Harpyien schon genug zu tun, als dass wir Windreiter entsenden könnten, um jede Schlucht und Klippe im Auge zu behalten.\n\nDanke, dass Ihr uns über die Bedrohung unterrichtet habt, aber vielleicht brauchen wir weiter Eure Hilfe.", rewards = nil},
[79360] = {title = "Elementare Hilfe", objective = "Viele Bewohner von Tausend Nadeln mögen unsere Feinde sein, aber wir können nicht tatenlos zusehen, wie sie fortgespült werden. Die Nachricht war eindeutig: Sie planen, aus den Nachwehen eine untote Armee zu erwecken, die eine Bedrohung für uns alle werden könnte.\n\nWir sind kaum imstande, ihren Plänen etwas entgegenzusetzen, aber ich hörte von einem Schamanen in den Östlichen Königreichen, der in der elementaren Verzauberung von Waffen geübt ist. Er könnte vielleicht helfen.\n\nSucht diesen Schamanen auf und bittet ihn um seine Hilfe.", description = "Ich hörte von Hirzek und den barbarischen Mühen, die sie aufgebracht haben, um die Elemente zu manipulieren.\n\n<Raus Blick wandert, während er über die Notiz nachdenkt und laut mit sich selbst spricht.>\n\nDer Sturm wird toben, der Boden wird erbeben und die Flut wird ansteigen...\n\n<Rau blickt Euch an und seine Augen weiten sich, als es ihm klar wird.>\n\nSie wollen irgendeine finstere Zauberei einsetzen, die sie von Hirzek gelernt haben. Sie haben vor, die Schlucht zu fluten, um uns alle als Untote wiederzuerwecken.\n\nIch fürchte, um das Ziel zu erreichen, brauchen sie verheerende elementare Kräfte.", progress = nil, completion = "&lt;Ihr überreicht Bath'rah die Notiz. Er überfliegt sie und schmunzelt halbherzig.&gt;\n\nAh, es stimmt also, Mann... Ich hab die Unruhe in den Elementarebenen schon gespürt, und das is' wohl 'ne Ursache davon.\n\nUm ganz Tausend Nadeln zu flut'n, bräuchte man 'nen gewaltigen Sturm, viele würden sterb'n.\n\nIch glaub, ich hab genau das, was Ihr braucht, aber es wird nich' leicht.", rewards = nil},
[79361] = {title = "Die Macht des Windes", objective = "Sammelt 5 wirbelnde Essenzen von den Wirbelwindelementaren in Desolace und bringt sie Bath'rah dem Windbehüter im Alteracgebirge.", description = "'N gewaltiger Sturm von dieser Größe braucht die Macht vom Wind, um das ganze Land heimzusuch'n. Was immer dieses Ritual is', wir müss'n Euch vor dem Element schütz'n.\n\nDie Wirbelwindelementare hab'n Desolace zerstört und gehören zu den wenig'n Elementaren, die das Land noch bewohn'n könn'. Bringt mir ihre Essenz.", progress = "Ah, seid Ihr da drauß'n 'n bisschen angestaubt?", completion = "Oh, ja, ja! Damit sind wir im Geschäft.", rewards = nil},
[79362] = {title = "Die Macht der Erde", objective = "Sammelt 5 bebende Essenzen von den Felselementaren im Ödland und bringt sie Bath'rah dem Windbehüter im Alteracgebirge.", description = "Um den Boden zum Beben zu bring'n, braucht man 'ne starke Verbindung zur Erde. Das Ödland ist voller Steine und Felsbrocken, die von der Zeit gehärtet wurd'n. Die Verkörperung der Erde treibt sich in diesen Ländern rum und nennt sie ihr Zuhause.", progress = "Ihr seht 'was wacklig auf den Beinen aus. Hat der Boden ordentlich gezittert?", completion = "'N steiniger Weg kann Euch nich' aufhalt'n, was?", rewards = nil},
[79363] = {title = "Die Macht des Wassers", objective = "Sammelt 5 rauschende Essenzen von den verdorrten Elementaren in den Marschen von Dustwallow und bringt sie Bath'rah dem Windbehüter im Alteracgebirge.", description = "Diese Flut, die ist echt das Schlimmste, Mann. Die Schlucht ist staubtrocken und das Wasser fließt tagelang auf diesem harten brüchigen Bod'n, da ist das Becken im Nu weg.\n\nIch kenne nich' viele Elementare, die solche Macht in sich trag'n, aber...\n\n<Bath'rah schaut Euch mit einem gerissenen Lächeln an.>\n\nKeine Sorge, ich weiß, wie ich Euch helf'n kann.\n\nDer Morast der Marschen von Dustwallow, da solltet Ihr hin. Auch wenn die nich' reine Wasserelementare sind, diese Verdorrten haben Geheimnisse.", progress = "Habt Ihr Euch 'was nass gemacht?", completion = "Schüttelt den Schlamm ab, Mann, wir hab'n's fast geschafft.", rewards = nil},
[79364] = {title = "Ein einfacher Behälter", objective = "Ihr habt doch nich' gedacht, dass ich irgend'ne verrückte Waffe für Euch entwickle, hm? Nee, nee, nee, <mein Freund/meine Liebe>, das ist 'n Schutztrank.\n\nFeuer mit Feuer zu bekämpfen, ist nicht immer der richtige Weg, Mann.\n\nBringt eine Kristallphiole zu Bath'rah dem Windbehüter im Alteracgebirge.", description = "Gut gemacht, Mann. Ich weiß zwar nich', was Euch in Tausend Nadeln erwartet, aber das bietet Euch auf jeden Fall Schutz gegen die Elemente, die das Land bedroh'n.\n\n<Bath'rah sucht in seinen Sachen nach etwas und wirkt immer frustrierter, während er verzweifelt alles durchstöbert. Schließlich blickt er Euch kleinlaut an.>\n\nDa ist doch noch 'ne Sache, die ich von Euch brauch.\n\n<Er lächelt breit, bevor er weiterspricht.>\n\nIch hab offenbar meine Trankphiolen verlegt...", progress = "Wir brauch'n 'ne größere Phiole, und zwar eine von kristallener Klarheit, um diese Elemente zu bewahr'n.", completion = "Ich wusste, ich kann auf Euch zähl'n.", rewards = nil},
[79365] = {title = "Mit Wind unter Euren Schwingen", objective = "Kehrt zu Rau Cliffrunner im Freiwindposten in Tausend Nadeln zurück.\n\nBereitgestellter Gegenstand: \n", description = "Hier, Mann, 'n Böenbrechertrank ist genau, was Ihr braucht. Trinkt ihn, um Euch vor den Elementen des Sturms zu schütz'n, aber denkt dran: Die Wirkung hält nur kurz an.\n\nAlso los, kehrt zu Euren Freund'n in Not zurück. Ich kann nichts weiter für Euch tun.", progress = nil, completion = "Unsere Windreiter haben etwas entdeckt, aber sie kamen nicht nah genug heran, um die Situation zu beurteilen. Habt Ihr etwas entdeckt, was uns womöglich hilft?", rewards = nil},
[79366] = {title = "Die Ruhe vor dem Sturm", objective = "Wagt Euch ins Auge des Sturms und stellt die Stacheleber.", description = "Wir haben ungewöhnlich starke Sturmaktivitäten entdeckt, die auf die Klippen im Nordosten nahe des Territoriums der Razorfen beschränkt sind.\n\nDie Winde waren so heftig, dass die Reiter nicht näher herankamen, und im dichten Regen konnten sie unmöglich sehen, was im Auge des Sturms vor sich geht. Aber vielleicht gelangt Ihr mit diesem Trank auf die andere Seite.\n\nSprecht mit Nyse, der Windreitermeisterin, wenn Ihr bereit seid. Sie stellt Euch einen Flügeldrachen bereit, um in den Sturm zu reiten.", progress = "Was habt Ihr gefunden?", completion = "Das Grollen der Erde verstummte und in meinem Herzen wusste ich, dass Ihr uns gerettet habt. Ich schulde Euch Dank, &lt;Name&gt;.\n\nBitte akzeptiert eines dieser Geschenke als Ausdruck unserer Verbundenheit.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBindungen des SturmjägersBindungen des BlitzrufersBindungen des Gezeitenrufers\n\nDer folgende Zauber wird auf euch gewirkt:\n\nEnde der Stürme"},
[79377] = {title = "Die verlorenen Schösslinge", objective = "Findet die vier verlorenen Schösslinge in den Östlichen Königreichen und gebt ihnen das Wasser aus Elune'ara. Kehrt anschließend mit ihnen wieder zu Orokai in Moonglade zurück.", description = "In unruhigen Zeiten können die Samen von Urtumen ihre Wurzeln in bitterer Erde schlagen. Urtume, die auf diese Weise geboren werden, sind anfällig, der Verderbnis zu verfallen. Sie durchschreiten feindselige Lande und finden nie Frieden.\n\nIch habe vier Schösslinge aufgespürt, denen ein solches Schicksal möglicherweise erspart bleiben kann. Sie sind in den Östlichen Königreichen verloren gegangen und tragen Blätter wie die der vier Jahreszeiten.\n\nBitte, bringt ihnen dieses Wasser, auf dass sie geheilt werden mögen.\n\nVorsicht, die Magie des Wassers ist empfindlich. Teleportation zerstört sie. Seine Wirksamkeit wird darüber hinaus mit der Zeit abnehmen.", progress = nil, completion = "Eure Taten haben Jahrhunderte des Lebens erhalten, &lt;Name&gt;. Ich bin Euch unermesslich dankbar. Möget Ihr noch mehr Heilung ins Land tragen in den Zeiten, die uns bevorstehen.", rewards = "Ihr bekommt:\n\nRune der Pflege"},
[79442] = {title = "Aufholen", objective = "Kehrt zu Bath'rah dem Windbehüter im Alteracgebirge zurück und seht, ob er etwas mit dem Auge des Gewittersturms anfangen kann.", description = "Unsere Leute können Euch nicht genug danken, doch ich habe keinen wirklichen Nutzen für dieses Auge. Vielleicht kann der alte Windbehüter etwas damit anfangen.", progress = "Ahh! Ihr habt's also unversehrt zurückgeschafft! Also, erzählt, wie hat sich der Trank gemacht?\n\nZum Glück hab ich an Euch geglaubt. Weil der Trank ist nur ein feiner Punsch, Kollege. Lecker, aber nich' sehr effektiv geg'n solche Stürme.\n\nNa, na... nicht böse werd'n. Ihr habt nur 'n bisschen Ermutigung gebraucht. Lief doch alles wie geplant.\n\nAber wo Ihr schon mal hier seid... Mir ist das schöne Auge aufgefall'n, das Ihr da habt.", completion = "Ich sag Euch was. Keine Tricks mehr, keine Spielchen. Ich hab da was, was Euch interessier'n könnte.\n\nGebt mir das Auge und ich geb Euch diese schicke Rune, die Euch neue Tricks beibring'n kann.\n\nWas meint Ihr?", rewards = "Ihr bekommt:\n\nRune des Stroms"},
[79482] = {title = "Gestohlene Winterhauch-Leckereien", objective = "Sucht den Ermittler von Kokelwälder, der im Alteracgebirge vermisst wird.", description = "Hört zu... ich will Euch ja den Zauber der Feiertage nicht verderben, aber Kokelwälder könnte etwas Hilfe brauchen... von der Art, für die Ihr Abenteurer bekannt seid.\n\nUns ist eine wichtige Lieferung mit Leckereien abhandengekommen, mit der wir die Vorräte für diese Feiertage aufstocken wollten, und jetzt ist auch noch der Agent von Kokelwälder verschwunden, den wir losgeschickt haben, um sie zu suchen! Also, die letzten Informationen über die Lieferung stammen aus dem Alteracgebirge, und dort wollte unser Mann danach suchen.\n\nSeht nach, ob sowohl Mann als auch Material dort zu finden sind, und zwar gesund und munter.", progress = nil, completion = "I-I-Ihr könnt mich h-h-hören! G-G-Gott sei Dank!\n\nIch bin nicht wirklich ein Sch-Sch-Schneemann - mein N-N-Name ist Sacks und ich a-a-arbeite für die N-N-Niederlassung von Kokelwälder in Ironforge. Ich w-w-wurde hierher geschickt, um n-n-nach einem vermissten Paket zu suchen, als ich von einer K-K-Kreatur angegriffen wurde, die ich n-n-noch nie gesehen habe!\n\nSo k-k-kalt...", rewards = "Ihr bekommt:\n\n"},
[79483] = {title = "Gestohlene Winterhauchleckereien", objective = "Sucht den Ermittler von Kokelwälder, der im Alteracgebirge vermisst wird.", description = "Hört zu... ich will Euch ja den Zauber der Feiertage nicht verderben, aber Kokelwälder könnte etwas Hilfe brauchen... von der Art, für die Ihr Abenteurer bekannt seid.\n\nUns ist eine wichtige Lieferung mit Leckereien abhanden gekommen, mit der wir die Vorräte für diese Feiertage aufstocken wollten, und jetzt ist auch noch der Agent von Kokelwälder verschwunden, den wir losgeschickt haben, um sie zu suchen! Also - die letzten Informationen über die Lieferung stammen aus dem Alteracgebirge, und dort wollte unser Mann danach suchen.\n\nSeht nach, ob sowohl Mann als auch Material dort zu finden sind, und zwar gesund und munter.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[79484] = {title = "So was Gemeines...", objective = "Sucht die gestohlenen Leckereien und bringt sie zu Wulmort Jinglepocket nach Ironforge. Zuletzt befanden sie sich im Besitz des monströsen Griesgrams, der sich in den Schneegebieten des Alteracgebirges befindet.", description = "Eine K-K-Kreatur namens \"Der monströse Griesgram\" hat u-u-unsere Lieferung mit L-L-Leckereien gestohlen, <Name>. Seid a-a-aber vorsichtig! Er hat m-m-mich in dieses Sch-Sch-Schneeschlamassel verwandelt!\n\nIhr w-w-werdet Hilfe brauchen, wenn Ihr ihm g-g-gegenübertretet. Ich habe gesehen, w-w-wie er dort herumzieht, wo die Y-Y-Yetis sind. Er ist s-s-sicherlich irgendwo h-h-hier! F-F-Findet die Leckereien, <Name>, bringt sie zu Kokelwälder in Ironforge z-z-zurück und s-s-sagt ihnen, dass ich a-a-aufgetaut werden muss!", progress = "<Name>, unser Winterhauchfest ist ruiniert, wenn wir unsere Lager nicht mit diesen Leckereien auffüllen können! Graccu kommt bestimmt zu kurz, wenn er dieses Mal seine köstlichen Fleischpasteten mit all den braven Jungs und Mädchen teilen muss...", completion = "Ihr habt sie gefunden! Ihr habt das Winterhauchfest für Kokelwälder gerettet!\n\nArmer Sacks... Wir werden ein Team rausschicken und uns eine Möglichkeit überlegen, wie wir ihn wieder auftauen. Hoffentlich ist er rechtzeitig zum Festtag zurück. Allerdings muss er noch die ganze Arbeit aufholen, die inzwischen liegen geblieben ist. Aber ohne Euch wäre auch das nicht möglich!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[79485] = {title = "So was Gemeines...", objective = "Sucht die gestohlenen Leckereien und bringt sie zu Kaymard Copperpinch nach Orgrimmar. Zuletzt befanden sie sich im Besitz des monströsen Griesgrams, der sich in den Schneegebieten des Alteracgebirges befindet.", description = "Eine K-K-Kreatur namens \"Der monströse Griesgram\" hat u-u-unsere Lieferung mit L-L-Leckereien gestohlen, <Name>. Seid a-a-aber vorsichtig! Er hat m-m-mich in dieses Sch-Sch-Schneeschlamassel verwandelt!\n\nIhr w-w-werdet Hilfe brauchen, wenn Ihr ihm g-g-gegenübertretet. Ich habe gesehen, w-w-wie er dort herumzieht, wo die Y-Y-Yetis sind. Er ist s-s-sicherlich irgendwo h-h-hier! F-F-Findet die Leckereien, <Name>, bringt sie zu K-k-k-kokelwälder in Orgrimmar z-z-zurück und s-s-sagt ihnen, dass ich a-a-aufgetaut werden muss!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[79486] = {title = "Ein Dankeschön von Kokelwälder!", objective = "Sprecht mit Altvater Winter in Ironforge.", description = "Wir von Kokelwälder sind dankbar für die Wiederbeschaffung der gestohlenen Leckereien, <Name>. Dafür möchten wir Euch ein besonderes Geschenk anbieten... präsentiert von niemand Geringerem als Altvater Winter persönlich!\n\nBitte, sprecht mit Altvater Winter und er wird Euch Euer Geschenk zum Winterhauchfest von uns hier bei Kokelwälder überreichen. Frisch von unserem Hof auf Euren Tisch: beste Kokelwälder Vollwertkost... dank Euch natürlich!", progress = nil, completion = "Ho, ho, hallo!\n\nDie Goblins haben mir gesagt, dass Ihr in dieser Feiertagszeit ein besonderes Geschenk verdient habt, und ich freue mich, es Euch überreichen zu dürfen. Bitte schön - ich wünsche Euch für dieses Jahr und für alle kommenden Jahre ein wunderbares Winterhauchfest.", rewards = "Ihr bekommt:\n\nKokelwälder Spezialgeschenk"},
[79487] = {title = "Ein Dankeschön von Kokelwälder!", objective = "Sprecht mit Altvater Winter in Orgrimmar.", description = "Wir von Kokelwälder sind dankbar für die Wiederbeschaffung der gestohlenen Leckereien, <Name>. Dafür möchten wir Euch ein besonderes Geschenk anbieten... präsentiert von niemand Geringerem als Altvater Winter persönlich!\n\nBitte, sprecht mit Altvater Winter und er wird Euch Euer Geschenk zum Winterhauchfest von uns hier bei Kokelwälder überreichen. Frisch von unserem Hof auf Euren Tisch - beste Kokelwälder Vollwertkost... dank Euch natürlich!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKokelwälder Spezialgeschenk"},
[79492] = {title = "Metzen das Rentier", objective = "Findet Metzen das Rentier. Lest Euch die erhaltenen Notizen durch, um Tipps über seinen Aufenthaltsort zu erhalten.\n\nWenn Ihr Metzen findet, solltet Ihr den Beutel mit Rentierstaub dabeihaben. Berieselt Ihr Metzen mit dem Staub, sollte dies ihn aus seiner Gefangenschaft befreien.\n\nBringt den Beutel zu Wulmort Jinglepocket in Ironforge zurück, sobald Ihr Metzen befreit habt.", description = "Es ist eine KATASTROPHE! Metzen das Rentier wurde entführt!\n\nMetzen ist eines von Altvater Winters acht Rentieren - und Eigentum von Kokelwälder. Wir haben nicht nur einen, sondern ZWEI Erpresserbriefe von Gruppen erhalten. Beide behaupten, Metzen in ihrer Gewalt zu haben. Gerade jetzt zur Festtagszeit haben wir hier ein echtes Problem. Bitte findet Metzen und bringt ihn zurück!\n\nSchaut Euch die Erpresserbriefe an, vielleicht findet Ihr darin ja Hinweise. Streut diesen Rentierstaub über ihn, wenn Ihr ihn findet, er wird ihn aus sämtlichen Fesseln befreien!\n\nBitte, beeilt Euch!", progress = "<Name>! Habt Ihr ihn gefunden? Konntet Ihr den Notizen, die ich Euch mitgegeben habe, genug Informationen entnehmen, um ihn ausfindig zu machen? Mir wird ganz schlecht wenn ich daran denke, was diese fiesen Strolche ihm antun könnten... Ein so hohes Lösegeld können wir uns einfach nicht leisten.", completion = "Ihr habt es geschafft! Hurra!\n\nMetzen ist gerade eben erst zurück zu den Ställen von Altvater Winter geflogen. Ja, Metzen kann wirklich fliegen! Der Staub hat ganze Arbeit geleistet, ich wusste, das würde funktionieren. Ihr habt das Winterhauchfest und Kokelwälder vor dem Untergang bewahrt. Danke, &lt;Name&gt;.\n\nHört mal, weil Ihr das für uns getan habt, möchte ich Euch das hier geben. Das ist etwas GANZ Besonderes. Wenn Ihr ein Reittier habt, werdet Ihr bestimmt eine Menge Spaß damit haben. Frohes Winterhauchfest!", rewards = "Ihr bekommt:\n\nKonservierter Tannenzweig"},
[79495] = {title = "Metzen das Rentier", objective = "Findet Metzen das Rentier. Lest Euch die erhaltenen Notizen durch, um Tipps über seinen Aufenthaltsort zu erhalten.\n\nWenn Ihr Metzen findet, solltet Ihr den Beutel mit Rentierstaub dabeihaben. Berieselt Ihr Metzen mit dem Staub, sollte dies ihn aus seiner Gefangenschaft befreien.\n\nBringt den Beutel zu Kaymard Copperpinch in Orgrimmar zurück, sobald Ihr Metzen befreit habt.", description = "Es ist eine KATASTROPHE! Metzen das Rentier wurde entführt!\n\nMetzen ist eines von Altvater Winters acht Rentieren - und Eigentum von Kokelwälder. Wir haben nicht nur einen, sondern ZWEI Erpresserbriefe von Gruppen erhalten. Beide behaupten, Metzen in ihrer Gewalt zu haben. Gerade jetzt zur Festtagszeit haben wir hier ein echtes Problem. Bitte findet Metzen und bringt ihn zurück!\n\nSchaut Euch die Erpresserbriefe an, vielleicht findet Ihr darin ja Hinweise. Streut diesen Rentierstaub über ihn, wenn Ihr ihn findet, er wird ihn aus sämtlichen Fesseln befreien!\n\nBitte, beeilt Euch!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKonservierter Tannenzweig"},
[79501] = {title = "Der Held des Tages", objective = "Bringt 1 Tiefsteinsalz und 5 Goldstücke zum Tannenzweigkonservierer. Ihr werdet 5 konservierte Tannenzweige erhalten.", description = "Eigentlich darf ich Euch das gar nicht sagen, aber da Ihr ja <der Held/die Heldin> des Tages seid, mach ich mal 'ne Ausnahme.\n\nUm diese Jahreszeit gibt es überall frische Tannenzweige, aber die Zweige bleiben nicht lange frisch. Wir haben eine Maschine, die Tannenzweige konserviert. Die bleiben dann für immer frisch! Wir benutzen sie, um die Festtage etwas aufzupeppen... und unsere Profite im Sommer zu steigern!\n\nIch lasse Euch den Konservierer benutzen, aber nur, wenn Ihr <ein Meisterkoch/eine Meisterköchin> seid. Ihr werdet etwas Tiefsteinsalz und etwa zwei, drei, ach, sagen wir einfach fünf Goldstücke brauchen. Damit solltet Ihr ein nettes Bündel konservieren können, das Ihr behalten könnt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKonservierter Tannenzweig"},
[79502] = {title = "Der Held des Tages", objective = "Bringt 1 Tiefsteinsalz und 5 Goldstücke zum Tannenzweigkonservierer. Ihr werdet 5 konservierte Tannenzweige erhalten.", description = "Eigentlich darf ich Euch das gar nicht sagen, aber da Ihr ja <der Held/die Heldin> des Tages seid, mach ich mal 'ne Ausnahme.\n\nUm diese Jahreszeit gibt es überall frische Tannenzweige, aber die Zweige bleiben nicht lange frisch. Wir haben eine Maschine, die Tannenzweige konserviert. Die bleiben dann für immer frisch! Wir benutzen sie, um die Festtage etwas aufzupeppen... und unsere Profite im Sommer zu steigern!\n\nIch lasse Euch den Konservierer benutzen, aber nur, wenn Ihr <ein Meisterkoch/eine Meisterköchin> seid. Ihr werdet etwas Tiefsteinsalz und etwa zwei, drei, ach, sagen wir einfach fünf Goldstücke brauchen. Damit solltet Ihr ein nettes Bündel konservieren können, das Ihr behalten könnt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKonservierter Tannenzweig"},
[79535] = {title = "Basilisken: Muss man Angst vor der Versteinerung haben?", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[79536] = {title = "Großer Freund der Bibliothek", objective = "Dank Eurer Spenden entwickelt sich die Bibliothek prächtig.\n\nBitte, nehmt das.", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nStiefel prägen - Zaubermacht\n\nDer folgende Zauber wird auf euch gewirkt:\n\nZaubermacht"},
[79588] = {title = "Kleine pelzige Tatzen", objective = "Will man eine große Masse herbeilocken, sollte man vor allem eines wissen: wie man mit kleinen Anreizen und Krimskrams ihr Interesse weckt! Könnt Ihr mir dabei helfen?\n\nIch brauche kleine pelzige Tatzen, die ich als Preise verwenden kann. Ihr könnt dergleichen von den Katzen des Brachlands oder der Dunkelküste erhalten...\n\nBringt mir ein paar Tatzen und ich tausche sie gegen ein Los des Dunkelmond-Jahrmarkts ein.", description = nil, progress = "Will man eine große Masse herbeilocken, sollte man vor allem eines wissen: wie man mit kleinen Anreizen und Krimskrams ihr Interesse weckt! Könnt Ihr mir dabei helfen?\n\nIch brauche kleine pelzige Tatzen, die ich als Preise verwenden kann. Ihr könnt dergleichen von den Katzen des Brachlands oder der Dunkelküste erhalten...\n\nBringt mir ein paar Tatzen und ich tausche sie gegen ein Los des Dunkelmond-Jahrmarkts ein.", completion = "Großartig, Ihr habt sie! Wir können daraus Spielsachen und anderen Schnickschack herstellen und damit bei mehr und mehr Leuten Interesse für den Jahrmarkt wecken!\n\nHier ist Euer Los, &lt;Name&gt;.  Ihr habt es Euch verdient!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[79589] = {title = "Zerrissene Bärenpelze", objective = "Kinder lieben Spielsachen! Egal was für Kinder, ich habe herausgefunden, dass alle Kinder pelzige und kuschelige Spielsachen lieben, die aus zerrissenem Bärenpelz angefertigt wurden!\n\nIhr könnt diese Pelze von Bären aus Ashenvale oder Hillsbrad bekommen.  Bringt mir einen Haufen davon und verdient Euch damit eine Menge Lose des Dunkelmond-Jahrmarkts!", description = nil, progress = "Kinder lieben Spielsachen! Egal was für Kinder, ich habe herausgefunden, dass alle Kinder pelzige und kuschelige Spielsachen lieben, die aus zerrissenem Bärenpelz angefertigt wurden!\n\nIhr könnt diese Pelze von Bären aus Ashenvale oder Hillsbrad bekommen.  Bringt mir einen Haufen davon und verdient Euch damit eine Menge Lose des Dunkelmond-Jahrmarkts!", completion = "Schöne Pelze, &lt;Name&gt;! Ich werde daraus eine Menge Kuscheltiere nähen lassen. Mit Hilfe von etwas Füllmaterial und Farbe, könnte daraus eines der begehrtesten Spielsachen in ganz Azeroth werden!\n\nLose? Ach ja, Euer Entgelt!  Hier sind sie!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[79590] = {title = "Schwerer Schleifstein", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[79591] = {title = "Surrendes bronzenes Dingsda", objective = "Mein neuer Stand wird etwas, das man sehen muss, ja! Etwas, das man sehen muss und... für ein paar Glückliche ist es auch etwas zum Anfassen!\n\nIch kann schon das mechanische Entzücken der surrenden kleinen Dingsdas hören und sehe schon die Kunden vor mir, wie sie näher an meinen Stand treten, um ihre Fähigkeiten zu testen!\n\nAh... jetzt brauche ich die Dingsdas selbst, um meinem Traum ein Stückchen näher zu kommen. Bitte, <Name>, bringt mir surrende bronzene Dingsdas... und ein paar Lose des Dunkelmond-Jahrmarkts werden Euer sein!", description = nil, progress = "Mein neuer Stand wird etwas, das man sehen muss, ja! Etwas, das man sehen muss und... für ein paar Glückliche ist es auch etwas zum Anfassen!\n\nIch kann schon das mechanische Entzücken der surrenden kleinen Dingsdas hören und sehe schon die Kunden vor mir, wie sie näher an meinen Stand treten, um ihre Fähigkeiten zu testen!\n\nAh... jetzt brauche ich die Dingsdas selbst, um meinem Traum ein Stückchen näher zu kommen. Bitte, <Name>, bringt mir surrende bronzene Dingsdas... und ein paar Lose des Dunkelmond-Jahrmarkts werden Euer sein!", completion = "Ihr habt die Dingsdas! Wunderbar! Ich kann schon jetzt das melodische Summen und Surren in meinem Kopf hören! Oh, wenn dieser Stand erst einmal fertig ist, dann wird er ein Weltwunder sein, das mich zeichnen wird!\n\nHier sind Eure Lose, &lt;Name&gt;. Bitte amüsiert Euch auf dem Jahrmarkt!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[79592] = {title = "Jahrmarktswämser", objective = "Unsere Arbeiter vom Jahrmarkt machen weitaus mehr als Dreck wegzufegen und Bolzen einzuschlagen! Sie helfen auch den Jahrmarkt auf Reisen zu bewachen und benötigen dafür stets robuste und rüstungsstarke Wämser.\n\nWenn Ihr etwas strapazierfähige Rüstung herstellt und zu mir bringt, dann werde ich dies sicherlich an die richtigen Leute weiterleiten. Ich werde Euch im Austausch dafür auch ein paar Lose des Dunkelmond-Jahrmarkts geben.", description = nil, progress = "Unsere Arbeiter vom Jahrmarkt machen weitaus mehr als Dreck wegzufegen und Bolzen einzuschlagen! Sie helfen auch den Jahrmarkt auf Reisen zu bewachen und benötigen dafür stets robuste und rüstungsstarke Wämser.\n\nWenn Ihr etwas strapazierfähige Rüstung herstellt und zu mir bringt, dann werde ich dies sicherlich an die richtigen Leute weiterleiten. Ich werde Euch im Austausch dafür auch ein paar Lose des Dunkelmond-Jahrmarkts geben.", completion = "Ah, Ihr habt die Wämser. Wunderbar. Darf ich fragen welches Tierleder Ihr für die Herstellung verwendet habt? Die Nähte sind erstklassig verarbeitet worden und die Struktur des Leders scheint ebenfalls sehr robust. Ihr seid ein begabter Handwerker!\n\nDankeschön, &lt;Name&gt;, hier sind Eure Lose.", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[79593] = {title = "Grober Gewichtsstein", objective = "Es kostet einiges die stärkste Frau der Welt zu sein! Mein Gewichtsset wird langsam zu leicht für mich und wenn ich in Form bleiben möchte, brauche ich mehr Gewichte!\n\nKönnt Ihr mir vielleicht ein paar Gewichtssteine besorgen? Wenn ja, werde ich Euch ein Los des Dunkelmond-Jahrmarkts geben.", description = nil, progress = "Es kostet einiges die stärkste Frau der Welt zu sein! Mein Gewichtsset wird langsam zu leicht für mich und wenn ich in Form bleiben möchte, brauche ich mehr Gewichte!\n\nKönnt Ihr mir vielleicht ein paar Gewichtssteine besorgen? Wenn ja, werde ich Euch ein Los des Dunkelmond-Jahrmarkts geben.", completion = "Großartig! Diese werden ihren Zweck erfüllen! Sie sind nicht zu schwer, aber auch nicht zu leicht. Sie eignen sich perfekt zum Aufbau von Muskelmasse!\n\nIch danke Euch, &lt;Name&gt;.  Hier ist Euer Los!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[79594] = {title = "Kupfermodulator", objective = "Yebb arbeitet an einer neuen Attraktion für das Kuriositätenkabinett, eine, die die Leute vor Verwunderung und Erstaunen begeistern wird! Es wird allerdings eine Menge an Arbeit und bedeuten und viel Material benötigen...\n\nUnter anderem Kupfermodulatoren. Wir brauchen zahlreiche Modulatoren für die mechanischen Teile der Attraktion.  Bringt mir Kupfermodulatoren und ich werde sie gegen ein Los des Dunkelmond-Jahrmarkts einlösen.", description = nil, progress = "Yebb arbeitet an einer neuen Attraktion für das Kuriositätenkabinett, eine, die die Leute vor Verwunderung und Erstaunen begeistern wird! Es wird allerdings eine Menge an Arbeit und bedeuten und viel Material benötigen...\n\nUnter anderem Kupfermodulatoren. Wir brauchen zahlreiche Modulatoren für die mechanischen Teile der Attraktion.  Bringt mir Kupfermodulatoren und ich werde sie gegen ein Los des Dunkelmond-Jahrmarkts einlösen.", completion = "Aha! Die Modulatoren! Herrlich!\n\nIch kann Euch zwar nicht genau sagen an was wir arbeiten, aber dies wird für dessen Konstruktion von unschätzbarem Wert sein. Ich stehe in Eurer Schuld, &lt;Name&gt;, bitte, nehmt dieses Los des Dunkelmond-Jahrmarkts als Zeichen meiner Wertschätzung.", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[79595] = {title = "Jahrmarktsstiefel", objective = "Wir vom Dunkelmond-Jahrmarkt sind sehr viel zu Fuß unterwegs. Wir laufen von einer Attraktion zur nächsten... eigentlich werdet Ihr uns niemals während der Arbeit sitzen sehen! Es ist also nicht überraschend, dass wir viel Schuhwerk verschleißen! Wir brauchen Stiefel, die belastbar und gleichzeitig modisch sind. Geprägte Lederstiefel sind da genau das Richtige.\n\nHey! Ihr seid Lederverarbeiter, macht mir ein Paar Geprägte Lederstiefel und ich gebe Euch für Eure Arbeit ein Los des Dunkelmond-Jahrmarkts.", description = nil, progress = "Wir vom Dunkelmond-Jahrmarkt sind sehr viel zu Fuß unterwegs. Wir laufen von einer Attraktion zur nächsten... eigentlich werdet Ihr uns niemals während der Arbeit sitzen sehen! Es ist also nicht überraschend, dass wir viel Schuhwerk verschleißen! Wir brauchen Stiefel, die belastbar und gleichzeitig modisch sind. Geprägte Lederstiefel sind da genau das Richtige.\n\nHey! Ihr seid Lederverarbeiter, macht mir ein Paar Geprägte Lederstiefel und ich gebe Euch für Eure Arbeit ein Los des Dunkelmond-Jahrmarkts.", completion = "Danke, &lt;Name&gt;. Eine wirklich gute Verarbeitung! Euer handwerkliches Können ist erstklassig! Hier ist Euer Los... viel Spaß damit, mein Herr.", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[79624] = {title = "Kochen kann jeder", objective = "Findet einen Oger, der das unleserliche Rezept entziffern kann.", description = "Das Rezept scheint für eine Art Fleischgericht gedacht zu sein. Es ist in einer Sprache verfasst, die Ihr nicht versteht. Vermutlich die der Oger, so schätzt Ihr, wenn man von der Quelle und Themengebiet ausgeht.\n\nOger sind nicht gerade dafür bekannt, Feinschmecker zu sein, aber wenn Ihr einen kennt, auf den das doch zutrifft, dann könnte dieser Oger das Rezept für Euch übersetzen.", progress = nil, completion = "Ihr habt Rezept? Skonk interessiert.", rewards = "Ihr bekommt:\n\n"},
[79626] = {title = "Der Wiederverwertungsmat 9000!", objective = "Gebt ein schmutzverkrustetes Bergungsgut in den Wiederverwertungsmat 9000 und stellt sicher, dass Ihr dreißig Silbermünzen habt, um die Maschine zu aktivieren.", description = "Dieser Apparat scheint mit Energie versorgt so werden, wenn auch gerade so eben. Auf einer kleinen Plakette steht: \"Der Wiederverwertungsmat 9000\", gefolgt von ein wenig Text, der nicht zu entziffern ist, da ihn eine dicke Schicht aus verkrustetem Dreck überdeckt. Die Maschine verfügt über einen riesigen Zulaufbehälter sowie einen Münzeinwurf.", progress = "Die Maschine sieht aus, als bräuchte sie sehr schnell eine sehr umfassende Generalüberholung. Es scheint, als könntet Ihr weiterhin etwas schmutzverkrustetes Bergungsgut hineingeben, aber Ihr seid nicht sicher, was dann passieren wird.", completion = "Ihr füttert den Wiederverwertungsmat 9000 mit dem schmutzverkrusteten Bergungsgut sowie mit dreißig Silbermünzen. Es gehen kurz ein paar Lichter an der Maschine an, dann rüttelt und schüttelt sie sich. Anschließend spuckt sie Euer nach wie vor schmutzverkrustetes Bergungsgut aus und kommt wieder zur Ruhe. Sie scheint kaputt zu sein.", rewards = "Ihr bekommt:\n\nSchmutzverkrustetes Bergungsgut"},
[79637] = {title = "Ein tickendes Geschenk", objective = "Ein wundervolles Winterhauchfest wünschen Euch Eure Freunde bei Kokelwälder.Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTickendes Geschenk"},
[79677] = {title = "Ein kurzer Blick auf die Liste", objective = "Sammelt die Zutaten für Skonks Gericht und bringt sie ihm im Arathihochland.", description = "Andere Oger lachen über Skonk, weil Skonk kleiner als sie. Sie sagen, kleiner Oger schwach, also Skonk kochen gelernt statt kämpfen. Dadurch nur mehr Spott, also Skonk auf und davon, um Traum zu folgen.\n\nSkonk kann Gericht kochen, aber braucht Zutaten. Nicht sicher, wo sie sind. Skonk mehr Blick für Kochkunst, weniger für Beschaffung.", progress = "Habt Ihr Zutaten? Fast Abendessenzeit.", completion = "Gute Arbeit, &lt;Volk&gt;. Wir jetzt richtig kochen!", rewards = "Ihr bekommt:\n\n"},
[79678] = {title = "Geschmacksprobe", objective = "Probiert das Rezept mit Skonk.", description = "Gut, <Volk>, es Zeit für Skonks Lieblingsteil. Skonk hat Feuer lichterloh und möchte neues Gericht mit neuem Freund teilen. Ihr so große Gefallen für Skonk getan, nur richtig, dass Ihr auch was bekommt!\n\nLasst Skonk wissen, wenn bereit, zu probieren.", progress = nil, completion = "Mmm, Rezept köstlich!\n\nSkonk ein bisschen verloren in Begeisterung, aber Ihr gute Hilfe!\n\nHier Euer Anteil. Skonk sogar etwas dazugegeben für Eure Mühen.", rewards = "Ihr bekommt:\n\nSchawarmageddonRune der Blutwoge"},
[79704] = {title = "Der Wiederverwertungsmat 9000!", objective = "Gebt ein schmutzverkrustetes Bergungsgut in den Wiederverwertungsmat 9000 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren.", description = "Gebt Euer Bergungsgut in die Maschine, erhaltet im Gegenzug fantastische Preise! Wahrscheinlich. Möglicherweise.", progress = "Die Maschine zittert und wackelt, bevor sie einen Haufen geborgene Teile ausspuckt.", completion = "Ihr füttert den Funkelmat 5200 mit dem schmutzverkrusteten Gegenstand sowie mit drei Silbermünzen. Die Maschine erwacht schlagartig zum Leben und versucht hektisch, den unbekannten Gegenstand vom Schmutz zu reinigen. Laute, heftige, peitschende Geräusche schlagen Euch aus dem Herzen der Maschine entgegen. Der Metallrahmen des Apparates knarrt und ächzt, als er hin und her schlingert...", rewards = "Ihr bekommt:\n\nKiste mit Bergungsgut aus Gnomeregan"},
[79705] = {title = "Wiederverwertung des Wiederverwertungsmats", objective = "Bringt Ziri \"Schraubenschlüssel\" 10 Mithrilbarren, 5 große Mystikeressenzen, 3 GG12-082-Sicherungseinsätze und einen makellosen G-7-K.E.R.N.-Prozessor, dann kann sie den Wiederverwertungsmat 9000 wieder auf Vordermann bringen. Wahrscheinlich. Möglicherweise.", description = "Ich glaube, das Ding pfeift aus dem letzten Loch. Ich könnte es vielleicht noch mal reparieren, aber das wird nicht einfach... oder billig. Ich sag Euch was, Ihr besorgt mir 10 Mithrilbarren, 5 große Mystikeressenzen, 3 GG12-082-Sicherungseinsätze und einen makellosen G-7-K.E.R.N.-Prozessor, dann kann ich es für Euch wahrscheinlich wieder startklar machen. Die Sicherungseinsätze sollten hier in Gnomeregan einfach zu finden sein, doch so ein Prozessorkern ist ein ziemlich seltener Gegenstand und nicht ganz so leicht zu bekommen. Ihr wirkt aber recht einfallsreich, ich denke, Euch fällt da bestimmt was ein! Viel Glück!", progress = "Holla! Ihr habt diesen ganzen Schrott tatsächlich angeschleppt? Eigentlich wollte ich Euch ja bloß ein bisschen auf den Arm nehmen, aber hey, eine Gnomin, ein Wort, und ich bin niemand, der gute Materialien vor die Hunde gehen lässt. Gebt mir ein paar der Dinge und ich mach Euch das Baby hier wieder einsatzbereit!", completion = "Ein einsatzfähiger Wiederverwertungsmat 9000, ganz wie versprochen. Wenn Ihr da draußen irgendwas Tolles findet, dann kommt wieder und zeigt es mir. Möglicherweise kann ich Euch die ein oder andere Sache beibringen, für den richtigen Preis, natürlich!\n\n&lt;Ziri grinst über beide Ohren und stopft etwas in ihre hintere Tasche.&gt;", rewards = nil},
[79731] = {title = "Die Trollschriftrolle", objective = "Löst das Rätsel der Schriftrolle. Sobald Ihr das getan habt, wird Hemet Nesingwary vermutlich davon hören wollen.", description = "<Die uralten Glyphen werden vor Euren Augen zu Worten.>\n\nWenn der Brunnen von Zul'Kunda von den Wassern der heiligen Quelle gespeist wird, gewähren die Götter ihren Segen.", progress = nil, completion = "Ein magischer Brunnen im Dschungel? Was für eine Geschichte, &lt;Name&gt;!\n\nDa kommt mir eine Idee für ein weiteres Kapitel in meinem Buch! Schauen wir mal, wo habe ich denn das Manuskript hingelegt...", rewards = "Ihr bekommt:\n\n"},
[79939] = {title = "Der kaputte Hammer", objective = "Sucht nach Hinweisen darauf, was sich in Mannorocs Koven in Desolace zugetragen hat, und findet jemanden, der möglicherweise mehr über den kaputten Hammer weiß.", description = "Ein kaputter verzierter Kriegshammer liegt umgeben von toten Kultisten der Burning Blade und Kriegern des Scharlachroten Kreuzzugs. Hier hat sich offensichtlich vor nicht allzu langer Zeit ein Kampf zugetragen. Ihr erkennt außerdem, dass dies die Waffe eines Paladins der Silbernen Hand ist. Obwohl Ihr zahlreiche Hämmer wie diesen gesehen habt, macht ihn seine Qualität und Verarbeitung durchaus einzigartig. Ihr solltet die Umgebung nach Hinweisen absuchen und jemanden finden, der möglicherweise mehr über diese Waffe weiß.", progress = "Was habt Ihr da bei Euch, mein Freund?", completion = "&lt;Katharina seufzt schwer.&gt; Ja, &lt;Name&gt;, ich kenne diese Waffe. Ich nahm an, ihr Besitzer wäre bereits vor langer Zeit gestorben.", rewards = "Ihr bekommt:\n\n"},
[79940] = {title = "Ein verlorener Bruder", objective = "Sprecht mit Katharina der Reinen und bringt mehr über den kaputten Hammer in Erfahrung.", description = "<Katharina zuckt zusammen, als sie die zerschmetterten Fragmente des kaputten Hammers aufhebt.>\n\nIch werde nicht zu viele Einzelheiten über denjenigen teilen, der diese Waffe führte, da mich das Gesagte mit Scham erfüllen würde, aber ich erzähle Euch, was ich kann.", progress = nil, completion = "Es bieten sich Euch nicht viele Hinweise, weshalb es sich als schwierig erweisen könnte, Aeonas zu finden, doch Ihr solltet es versuchen.", rewards = nil},
[79945] = {title = "Befehle des Obersten Kreuzzüglers", objective = "Bringt die Befehle des Obersten Kreuzzüglers zurück zu Katharina der Reinen.", description = "Dies scheinen die Befehle des Obersten Kreuzzüglers selbst zu sein, Dathrohan. Anscheinend ist Aeonas mit dem Kreuzzug aneinandergeraten. Wenn wir aus dem Rückschlüsse ziehen wollen, was wir vor uns sehen, dann sieht es so aus, als hätte der Kreuzzug Aeonas bis hierher verfolgen und ihn stellen können. Er hat er sich offenbar nicht kampflos ergeben.\n\nEs sind ernste Vorwürfe, die gegen Aeonas erhoben wurden. Aber das würde einiges von dem erklären, was Ihr in Desolace gesehen habt.", progress = "Bringt Ihr Nachricht von Aeonas?", completion = "&lt;Katherinas Stirn legt sich in tiefe Falten, während sie den Brief liest.&gt;\n\nAeonas vertrat ein paar radikale Ansichten, als er den Orden verließ, aber es fällt mir schwer zu glauben, dass seine Aktivitäten in Desolace den Umgang mit Dämonen oder Untoten eingeschlossen haben sollen. Wir müssen ihn finden und uns seine Version der Geschichte anhören. Ich bin mir sicher, dass hinter der ganzen Sache noch mehr steckt.", rewards = "Ihr bekommt:\n\n"},
[79946] = {title = "Ein Bruder in Not", objective = "Sprecht mit Katharina, um mehr über Aeonas zu erfahren und findet ihn dann im Scharlachroten Kloster.", description = "Aufgrund der... unglücklichen Umstände, unter denen er den Orden verließ, wäre es wahrlich ein schlechter Witz, wenn Aeonas nun durch die Hand des Scharlachroten Kreuzzugs sterben würde. Der Kreuzzug ist eine Organisation von Fanatikern und Wahnsinnigen, und ihre Gewalt gegenüber allen, die sie als Feinde des Lichts betrachten, hat immer unverfrorenere Züge angenommen. Geht zum Scharlachroten Kloster in Tirisfal und findet Aeonas, wenn er denn noch am Leben ist.", progress = nil, completion = "&lt;Aeonas scheint ernsthaft verwundet zu sein. Es fällt ihm schwer, ein paar Worte zu sprechen.&gt; Sie haben... mir gar keine Fragen gestellt...", rewards = "Ihr bekommt:\n\n"},
[79947] = {title = "Geomantie: Der steinige Weg zur Wahrheit", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[79948] = {title = "Das Einmaleins der Verteidigungsmagie", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[79949] = {title = "Ein Netz aus Lügen: Die Entzauberung von Mythen und Legenden", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[79950] = {title = "Dämonen und Ihr", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[79951] = {title = "Mumien: Ein Ratgeber zu unappetitlichen Untoten", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[79952] = {title = "RwlRwlRwlRwl!", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[79953] = {title = "Anleitung zur Pflege eines dämonischen Begleiters für Anfänger", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[79963] = {title = "Bei der Anmut des Lichts", objective = "Heilt Aeonas.", description = "Aeonas bedarf sofortiger Heilung, sonst stirbt er. Ruft das Licht an und rettet ihn.", progress = nil, completion = "&lt;Aeonas scheint das Atmen leichter zu fallen. Er wirkt immer noch sehr schwach, aber er schafft es, Euch seinen Kopf zuzuwenden, um zu sprechen.&gt;\n\nIhr sagt, dass Katherina Euch schickt? Gesegnet sei sie. Ich danke Euch, &lt;Klasse&gt;. Ich stehe in Eurer Schuld.", rewards = "Ihr bekommt:\n\n"},
[79970] = {title = "Aeonas der Verteidigte", objective = "Trefft Euch mit Aeonas an der Kathedrale des Lichts in Stormwind.", description = "Danke, dass Ihr mich gerettet habt, <Klasse>. Es scheint, als wäre ich nicht mehr ganz so jung, wie ich es einst war. Und es scheint auch, als würde ich für das, was noch kommt, einige Verbündete brauchen. Trefft mich, sobald Ihr könnt, in Stormwind bei der Kathedrale des Lichts.\n\nMacht Euch um mich keine Sorgen, ich finde schon selbst den Weg zurück. Ich brauche nur einen Moment, um wieder zu Kräften zu kommen.", progress = nil, completion = "Ich kann Euch nicht genug danken, dass Ihr mich aus diesem lichtverlassenen Ort gerettet habt. Leider glaube ich, dass das erst der Anfang unserer Reise war und der Rest nicht leichter wird. Unterhalten wir uns und planen wir unsere nächsten Schritte.\n\nOh, zuallererst jedoch... erlaubt diesem alten Mann, etwas von seinem Wissen an die jüngere Generation weiterzugeben. Es ist keine große Belohnung, doch ich hoffe, dass es sich Euch dennoch als nützlich erweist.", rewards = "Ihr erlernt:\n\nGürtel prägen - Ummantelung des Lichts\n\nDer folgende Zauber wird auf euch gewirkt:\n\nUmmantelung des Lichts\n\nIhr bekommt außerdem:\n\n"},
[79974] = {title = "Feuchte Angelegenheit", objective = "Beim Abstauben einer vom Boden aufgelesenen Kuriertasche findet Ihr zwischen den Vorräten ein Pergament.", description = "Ich habe gerne einen Reservevorrat in der Nähe, falls ich mich doch mal schnell aus dem Staub machen muss.\n\nDas Antlitz dieses Berghangs ist so wunderschön, man könnte sagen, dass es aus den Wasserfällen der Zeit geschnitzt wurde.\nDas ist der Adlerhorst, der Ort, nach dem Ihr sucht.", progress = nil, completion = "Die Ingenieurskunst der Zwerge, ein Wunderwerk wie eh und je.", rewards = "Ihr bekommt:\n\nHickory-PfeifeRumsey-Rum Light"},
[79975] = {title = "Adlerfaust", objective = "Spritzendes Wasser befeuchtet die Luft, der Ausblick ist unglaublich.", description = "Ihr findet einen sorgfältig gefalteten Brief im Werkzeugkasten. Ihr stellt Euch eine Stimme vor und lest: \"Von hier aus habt Ihr das Sagen, vorausgesetzt, Ihr habt das richtige Werkzeug. Das ist ein toller Ort, um einen Paragleiter zu starten.\n\nMeine Loyalität zu Adler und Faust benötigt Distanz, um ihnen so gut wie möglich zu dienen. Diese Barrikade hat schon bessere Tage gesehen, genau wie die Alten Königreiche, die sie einst verteidigt hat, aber ich werde sie nie verlassen.\"", progress = nil, completion = "Ein Lagerfeuer, bei dem vor Kurzem Holz nachgelegt wurde. Es gibt deutliche Anzeichen eines zügigen Aufbruchs.", rewards = "Ihr bekommt:\n\n"},
[79976] = {title = "Das muss der Ort sein", objective = "Wer auch immer hier war, Ihr habt die Person nur knapp verpasst.", description = "\"Ich habe mich dazu entschlossen, meine Arbeit wieder unter Tage weiterzuführen, damit sie auch ja nicht in die falschen Hände gerät.\"\n\nDas Papier wurde so abgerissen, dass die Nachricht gerade so darauf Platz findet. Ihr seid Euch nicht sicher, ob das die letzten Worte sind, die Ihr vom Verfasser lesen werdet, oder ob sie ein Hinweis auf das nächste Versteck sind. Ein unzureichend gesicherter Schlafsack rollt sich vor Euren Füßen aus...", progress = nil, completion = "Allerlei Gerätschaften befinden sich versteckt unter einer schweren Plane. Ihr bedient Euch am Gepäck.", rewards = "Ihr bekommt:\n\nGemütlicher SchlafsackStudentenfutter"},
[79980] = {title = "Weg hier", objective = "Findet, was Euch erwartet.", description = "Gar nicht so übel, was? Dass Ihr das lest, bedeutet, dass mein Vorrat immer noch da ist. Geht hundert Schritte nach Norden und brecht Euch nicht die Beine, wenn Ihr die steile Klippe hinuntersteigt. Das sollte genügen, um Euch auf der Spur zu halten.", progress = nil, completion = "Ihr zieht eine Kuriertasche aus dem Boden. Neben den Vorräten findet Ihr darin auch ein schmutziges Pergament.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSilbersternMondsichtgewehrPräzisionsbogen\n\nIhr bekommt außerdem:\n\nGefiederter PfeilExplosivgeschossStudentenfutter"},
[79981] = {title = "Der korrodierte Kern", objective = "Findet jemanden, der den korrodierten G-7-K.E.R.N.-Prozessor reparieren kann.", description = "Diese K.E.R.N.-Einheit passt definitiv zu der Beschreibung, die Ziri Euch gegeben hat, doch sie ist schwer beschädigt und verdreckt. Ihr könnt gerade so ein verblasstes Etikett ausmachen, auf dem sich allem Anschein nach die Kontaktinformationen für eine Art Garantie befinden. Es lassen sich nur ein paar wenige Buchstaben ausmachen.\n\n\"Beschr... ...rantieanspruch: Bit... ...enden Sie ...ich an Wi... ...nder...ad\"", progress = "Wenn jemand einen Turm und eine Werkstatt auf einer gewaltigen Spitze mitten im Nirgendwo baut, könnte man fast meinen, dass die Person keine unerwarteten Besucher wünscht. Wer hätte es gedacht?", completion = "&lt;Wirdals Vergrößerungsbrille gibt ein tiefes, mechanisches Surren von sich, während sie sich auf den korrodierten G-7-K.E.R.N.-Prozessor in Eurer Hand fokussiert.&gt; Tatsache, das ist einer von meinen.\n\nIch rate Euch dringend, das Ding ins Meer zu schmeißen und keinen weiteren Gedanken daran zu verschwenden.", rewards = nil},
[79982] = {title = "Garantieanspruch", objective = "Bringt Wirdal Wunderrad einen aufgeladenen Leerenkern.", description = "Ich kann den Prozessor für Euch reparieren, doch dafür brauche ich einen Gegenstand, der eher schwer in die Finger zu kriegen ist: einen aufgeladenen Leerenkern. Nagazauberer sollen die gerne bei sich tragen. Ich bin mir nicht ganz sicher, wo die Naga sie herbekommen oder wie sie hergestellt werden, doch sie werden oft als mächtige Fokusse für bestimmte Arten von magischen Ritualen verwendet. Sie sind die Schlüsselkomponente für meine G-7-K.E.R.N.-Prozessoreinheit. Sie sind aber auch nicht sehr geläufig, es wird also kein Leichtes, einen aufzutreiben.", progress = "Ich will gar nicht erst wissen, wie viele Naga Ihr vermöbeln musstet, um an das Teil zu gelangen.", completion = "Nun, wird schon schiefgehen.\n\nIch sehe mich dazu veranlasst, Euch darüber zu informieren, dass ich für keinerlei elektrische Brände, elektromagnetische Impulsexplosionen, dämonische Manifestationen oder interdimensionale Strudel hafte, die sich durch Installation und Verwendung dieses Prozessors ergeben.", rewards = "Ihr bekommt:\n\nMakelloser G-7-K.E.R.N.-Prozessor"},
[79984] = {title = "Quadrangulation", objective = "Findet Wirdal Wunderrads Quadrangulationssignalgeber und stimmt Euch auf sie ein. Es gibt vier von ihnen und sie befinden sich irgendwo in Kalimdor.", description = "Wirdal? Ja, den kenne ich. Ist ein Gnom, aber das kreide ich ihm nicht an, schließlich ist er genau wie ich ebenfalls ein bekennender Liebhaber von Transpolyportationen. Er hat sich vor ein paar Monaten von hier verabschiedet und sich was irgendwo in Kalimdor gesucht, doch hin und wieder portet er vorbei und schnappt sich ein paar Vorräte. Ich könnte Euch vermutlich zu ihm transpolyportieren, doch dafür bräuchten wir seine Koordinaten, sonst teleportiere ich Euch noch in einen Berg oder so. Wenn Ihr seine Quadrangulationssignalgeber in Kalimdor aufspürt und Euch auf diese einstimmt, könnte das funktionieren!", progress = nil, completion = "Wow, Ihr habt sie gefunden. Gebt mir einen Moment, ich muss nur die Koordinaten eingeben und den Transponder kalibrieren...\n\n...und schon haben wir's! Ich glaube, das könnte sogar funktionieren.", rewards = nil},
[79985] = {title = "Eine schöne Bescherung", objective = "Begleitet Kernobee zur Uhrwerkgasse und meldet Euch dann wieder bei Scooty in Booty Bay.", description = "<Kernobee stöhnt.> Was... Was ist passiert?\n\nDas Letzte, an das ich mich erinnere, ist, wie ich von einer Gruppe Dunkeleisenzwerge gefangen, halb tot geprügelt und dann hier zu diesen schmutzigen Troggs geworfen wurde.\n\nHolt mich hier raus, <Name>!\n\nSo ist der Plan: Bringt mich zum Ausgang. Wenn wir es lebend hier herausschaffen, geht nach Booty Bay und lasst Scooty wissen, dass ich nach Ratchet gegangen bin, um Tinkerwiz zu warnen, dass die Dunkeleisenzwerge in die Herstellung dieser Supermaschine verwickelt sind.\n\nGehen wir!", progress = nil, completion = "Ich schätze, Ihr solltet dafür belohnt werden, Kernobee in einem Stück zurückgebracht zu haben, &lt;Name&gt;. Wenn Ihr nach Gnomeregan zurückkehrt, könnten diese hier Euch den entscheidenden Vorteil liefern, den Ihr benötigt, um diesen nichtsnutzigen Verräter Robogenieur Thermaplugg zu besiegen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFeuergeschmiedete ArmschienenFeenflügel-Mantel\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[79986] = {title = "Schmutzverkrusteter Ring", objective = "Findet einen Weg, den schmutzverkrusteten Ring zu säubern.", description = "Ihr habt bei einer der Leichen der Dunkeleisenzwerge etwas entdeckt, das wie ein Ring aussieht. Es ist jedoch schwer zu sagen, was für ein Ring das ist. Das Ding ist derart mit Dreck und Verkrustungen überzogen, dass man es unmöglich an einen Finger stecken kann. Ihr glaubt, unter den Verkrustungen Edelmetall schimmern und vielleicht sogar einen Edelstein glitzern zu sehen.\n\nWenn Ihr diesen Ring verwenden wollt, müsst Ihr nach etwas suchen, das die Verkrustungen entfernt.", progress = "Der Gnomenapparat vor Euch trägt eine Plakette mit der Aufschrift \"Der Funkelmat 5200\". Laut der Anleitung unter der Plakette besteht der Sinn dieser Maschine darin, jedweden Schmutz von Gegenständen abzuschrubben. Um den Vorgang zu starten, legt man den Gegenstand in die Maschine und wirft drei Silbermünzen in den Münzschlitz.\n\nEs scheint, als sei der verkrustete Ring, den Ihr gefunden habt, geradezu perfekt, um diese Maschine auszuprobieren.", completion = "Ihr legt den Ring in den Funkelmat 5200 und werft eine Silbermünze in den Schlitz.\n\nFurchtbares Knirschen und Mahlen dringt aus der Maschine, als sie heftig zu ruckeln beginnt. Man kann nur raten, was mit dem Ring in der Maschine passiert...\n\nDann stoppt die Maschine plötzlich, ihren Stillstand mit einem einfachen \"Ding!\" verkündend. Der Aufnahmebehälter öffnet sich und offenbart eine kleine, hübsch verpackte Schachtel mit einer roten Schleife. Es scheint, als würde der Funkelmat 5200 alles auch gleich noch als Geschenk verpacken!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub"},
[79987] = {title = "Die Rückkehr des Rings", objective = "Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist.", description = "Ihr öffnet die Schachtel, die der Funkelmat 5200 ausgegeben hat, und entdeckt, was Ihr vermutet hattet - einen glänzenden Ring! Beim Anstecken des Rings fühlt Ihr magische Macht durch Euren Körper fließen.\n\nAuf der Innenseite des Rings befindet sich eine kleine, aber dennoch klar erkennbare Gravur des Siegels von Ironforge. Daneben sind drei kleine Initialen eingraviert: \"TdK\". Dies könnten entweder die Initialen des ursprünglichen Besitzers oder die des Herstellers des Rings sein. Den Ring behalten...oder ihn dieser Person zurückgeben? Entscheidungen über Entscheidungen...", progress = "He, immer mit der Ruhe, Partner - ich bin ein wichtiger Geschäftsmann! Der Kurier, der die Miete überbringen sollte, ist bestimmt einfach nur spät dran... Moment mal... Ihr seid ja gar nicht mein Vermieter.\n\nNatürlich seid Ihr das nicht - wie dumm von mir! Ihr seid hier, weil Ihr den besten Juwelier in ganz Ironforge sucht, einen, der KEINE VERFLUCHTEN Gegenstände herstellt. Jawohl!\n\nHm... Was braucht Ihr?", completion = "Ein Ring, sagt Ihr? Lasst mich mal sehen... Ja, und wie ich diesen Ring gefertigt habe.\n\nBevor Gnomeregan verloren ging, hatte ich dort einen kleinen Laden. Vielleicht ist es einer von denen, die ich zurückließ, als ich in die Hügel geflohen bin. Er ist recht schlicht gehalten und ich habe mehrere dieser Art hergestellt. Vielleicht gehörte er auch jemandem, der es nicht bis nach draußen geschafft hat.\n\nDunkeleisenzwerge hatten ihn? Tja, das fügt den ganzen Verschwörungstheorien, die bereits herumgeistern, eine weitere Ebene hinzu. Vielleicht interessieren sich offizielle Stellen dafür. Für Leute wie mich ist so etwas unwichtig.\n\nAber jetzt zurück zu diesem Ring...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[79990] = {title = "Holz aus dem Schlingendorntal", objective = "Beschafft Sergeant Maclear eine Lieferung Schlingendornholz.", description = "Wir suchen händeringend nach weiteren Ressourcen und Verstärkungen, um unsere Ziele im Arathibecken zu erreichen. Insbesondere Holz ist fast unmöglich zu bekommen und wir sind gezwungen, bis ganz zum Schlingendorntal zu blicken, um das zu besorgen, was wir brauchen. Bringt mir eine Lieferung Schlingendornholz und Eure Unterstützung wird nicht unbemerkt bleiben.", progress = "Habt Ihr frische Vorräte für uns?", completion = "Habt Dank, &lt;Klasse&gt;. Das wird uns helfen, das Blatt im Arathibecken zu wenden.", rewards = nil},
[79991] = {title = "Holz aus dem Schlingendorntal", objective = "Beschafft Todespirscher Mortis eine Lieferung Schlingendornholz.", description = "Wir suchen händeringend nach weiteren Ressourcen und Verstärkungen, um unsere Ziele im Arathibecken zu erreichen. Insbesondere Holz ist fast unmöglich zu bekommen und wir sind gezwungen, bis ganz zum Schlingendorntal zu blicken, um das zu besorgen, was wir brauchen. Bringt mir eine Lieferung Schlingendornholz und Eure Unterstützung wird nicht unbemerkt bleiben.", progress = "Habt Ihr frische Vorräte für uns?", completion = "Habt Dank, &lt;Klasse&gt;. Das wird uns helfen, das Blatt im Arathibecken zu wenden.", rewards = nil},
[80001] = {title = "Neu entfachen", objective = "Eine erloschene Feuerstelle. Das Holz ist sogar trocken genug, um eine Flamme zu entzünden.", description = nil, progress = "Eine erloschene Feuerstelle. Das Holz ist sogar trocken genug, um eine Flamme zu entzünden.", completion = "Ihr setzt Eure Späherfähigkeiten ein.", rewards = "Ihr bekommt:\n\nFeuerstein und Zunder"},
[80098] = {title = "Eigentümliches Relikt aus Dalaran", objective = "Habt Ihr eines der gestohlenen Relikte geborgen?", description = nil, progress = "Habt Ihr eines der gestohlenen Relikte geborgen?", completion = "Vielen Dank, &lt;Name&gt;. Ich werde dafür sorgen, dass es seinen Weg in die Stadt sicher zurückfindet.", rewards = "Ihr bekommt:\n\n"},
[80120] = {title = "Dienst für Dalaran", objective = "Ihr habt Dalaran und Azeroth einen großen Dienst erwiesen.\n\nUnsere Gesetze verbieten es mir, die Geheimnisse Dalarans mit Außenstehenden zu teilen, aber ich denke, ich kann die Regeln ein wenig beugen, um Euch für Eure Bemühungen zu entlohnen. Bitte nehmt dies.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nVorratstasche"},
[80131] = {title = "Gnomenverbesserungen", objective = "Bringt Talvash del Kissel in Ironforge den blitzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen.", description = "Hört mir zu, <Name>. Dieser Ring gehört Euch, das ist schon richtig... aber ich kann Euch einen besseren machen! Das Design ist, wie ich bereits sagte, wirklich einfach. Ich bin heutzutage wesentlich geschickter und für die läppische Summe von dreißig Silbermünzen werde ich ihn für Euch aufpeppen! Na ja, eigentlich etwas mehr als dreißig...\n\nIch bin derzeit in einer misslichen Lage. Mein ganzer Materialvorrat ist aufgebraucht. Wenn Ihr mir einen Barren Silber und einen Moosachat bringt, verziere ich Euch den Ring damit und peppe ihn richtig schön auf!!\n\nVertraut mir!", progress = "Habt Ihr die Materialien, die ich benötige? Ich würde Euch nicht darum bitten, wenn ich nicht gerade völlig vom Glück verlassen wäre...", completion = "Ah, genau das, was ich brauchte! Eines Tages, wenn ich es aus diesem Loch, in dem ich mich ungerechterweise befinde, herausgearbeitet habe, werde ich für Euch, nein für JEDERMANN die besten Schmuckstücke in ganz Azeroth herstellen! Bis es so weit ist, danke ich Euch, dass Ihr in Bezug auf die Reagenzien so anständig wart. Ich würde normalerweise zehnmal so viel für einen Ring von dieser Qualität verlangen, wie ich Euch abgeknöpft habe...\n\nWo wir gerade davon sprechen, hier ist Euer neuer Ring!", rewards = "Ihr bekommt:\n\nTalvashs blitzender Goldring"},
[80132] = {title = "Maschinenkriege", objective = "Besorgt die Maschinenblaupausen und Thermapluggs Safekombination aus Gnomeregan und bringt sie zu Nogg nach Orgrimmar.", description = "Vor zwei Jahren noch hat man sich jedes Mal darüber lustig gemacht, wenn die Rede auf Gnomentechnologie kam. Diese Zeiten haben sich definitiv geändert. Jetzt haben sie eine neue Maschine gebaut, die besser ist als all unsere Schreddermodelle zusammen. Ich brauche die Blaupausen dafür, <Name>!\n\nDummerweise sind die Pläne in einem Safe bei Robogenieur Thermaplugg sicher verwahrt. Was die Sache noch erschwert: Nur Robogenieur Thermaplugg kennt die Kombination zu diesem Safe.\n\nTut, was Ihr tun müsst, um diese Kombination zu erlangen, <Name>. Dann öffnet den Safe und bringt mir diese Blaupausen!", progress = "Ich sehe keine Blaupausen. Habt Ihr sie irgendwo unter Euren Kleidern versteckt oder steht Ihr hier nur rum, um mir auf die Nerven zu gehen?", completion = "Ich wusste, Ihr könnt es schaffen, &lt;Name&gt;! Sovik wiederum hatte seine Zweifel.\n\n\n\nJetzt, da wir die Blaupausen besitzen, ist es nur noch eine Frage der Zeit, bis wir alle Gnomeninnovationen enträtselt haben, die beim Bau dieser Maschine gemacht wurden, und sie zu Goblininnovationen für unsere neuen Schreddermodelle machen können.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMakellose Civinad-RobenBehände Latzhose des StolperläufersDreifach verstärkte Gamaschen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[80133] = {title = "Chefingenieur Scooty", objective = "Sprecht mit Scooty in Booty Bay.", description = "In dem Moment, als wir durch Kernobee von der neuen Gnomenmaschine hörten, haben Scooty und ich mit der Arbeit am Transpolyporter 6000 begonnen: dem schnellsten und verlässlichsten Weg nach Gnomeregan.\n\nEndlich ist er bereit, Passagiere aufzunehmen, <Name>. Wenn Ihr es einmal versuchen wollt, geht nach Booty Bay und redet mit Scooty am Windreiterhorst. Um nach Booty Bay zu gelangen, nehmt das Boot von Ratchet aus.\n\nNatürlich könnt Ihr auch versuchen, Euch durch die von Zwergen verseuchten Berge von Dun Morogh nach Gnomeregan durchzuschlagen!", progress = nil, completion = "Ist sie nicht eine Schönheit? Ein Meisterstück der Goblintransporttechnologie - ist nur ein Dutzend Mal oder so explodiert.\n\nKeine Sorge, &lt;Name&gt;, ich habe sie vollständig repariert. Sie wird Euch nicht um die Ohren fliegen - und falls doch, dann wird es schnell und schmerzlos sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[80134] = {title = "Gnomer-weeeeg!", objective = "Wartet, bis Scooty den Goblintransponder kalibriert hat.", description = "Solange Ihr den Transponder bei Euch habt, müsst Ihr lediglich auf diese Plattform hier treten und Ihr werdet nach Gnomeregan teleportiert.\n\nIhr werdet vielleicht ein paar ungewöhnliche Nebenwirkungen erleben, aber keine davon sollte dauerhaft sein... zumindest nicht mehr.\n\nIch hätte fast den wichtigsten Teil vergessen - die Rückkehr. Wenn Ihr wieder zurückkommen wollt, tretet einfach auf die Transpolyporter-Plattform in Gnomeregan!\n\nJetzt lasst uns diesen Transponder auf Euer Gewicht und Eure Größe einstellen.", progress = nil, completion = "Das war's! Wenn Ihr so weit seid, tretet einfach auf die Plattform.", rewards = "Ihr bekommt:\n\nGoblin-Transponder"},
[80135] = {title = "Klockmorts Grundlagen", objective = "Sprecht mit Klockmort Spannerspan in Ironforge.", description = "Ein Gnomenfreund, Klockmort Spannerspan, hat mich aus Ironforge kontaktiert. Er teilt mir mit, dass er Hilfe bei einer gefährlichen, aber unverzichtbaren Mission nach Gnomeregan braucht, der einst so großen Gnomenstadt, die jetzt verseucht und voller verrückter Gnome und ihrer Gerätschaften ist.\n\nIch muss hierbleiben, aber mir blutet das Herz, wenn ich meinem Freund nicht helfen kann. Wenn Ihr an meiner Stelle gehen könnt, dann stünde ich tief in Eurer Schuld.\n\nIhr könnt Klockmort in Tüftlerstadt in Ironforge finden.", progress = nil, completion = "Allerdings! Ich brauche Hilfe bei einer Mission, die nach Gnomeregan hineinführt. Und Ihr seid genau der &lt;Klasse&gt;, der das tun könnte!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[80136] = {title = "Grundlegende Artifixe", objective = "Bringt Klockmort Spannerspan in Ironforge 12 grundlegende Artifixe.", description = "Ein beinahe universell einsetzbares mechanisches Bauteil - das grundlegende Artifix - war den Tüftlern und Schmieden von Gnomeregan von großem Nutzen. Doch während der panischen Flucht aus unserer Stadt hat niemand daran gedacht, einige von diesen Geräten mitzunehmen! Und ich brauche eine ganze Menge davon für eine Arbeit, die ich in Kürze in Angriff nehmen werde.\n\nBitte, geht nach Gnomeregan und bringt mir einige grundlegende Artifixe. Ihr werdet sie in den tieferen Bereichen unserer Stadt finden, in \"Künstliche Extrapolatoren\" genannten Behältern.\n\nDanke, <Name>, und bitte beeilt Euch!", progress = "Habt Ihr die grundlegenden Artifixe?", completion = "Ihr habt sie! Jetzt kann ich mit meinen neuen Experimenten beginnen!\n\nIch kann Euch gar nicht genug danken, &lt;Name&gt;! Durch Eure Tapferkeit hat die Gnomenforschung einen riesigen Schritt nach vorn gemacht.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[80137] = {title = "Rettet Techbots Hirn!", objective = "Bringt Techbots Speicherkern zu Tüftlermeister Overspark nach Ironforge.", description = "Als unsere geliebte Stadt Gnomeregan fiel, muss ein verirrter Funke mein armes Geschöpf, Techbot, völlig durcheinandergebracht haben. Früher half er mir und meinen Kollegen mit seinen zahllosen Dingsdas und seiner endlosen Speicherkapazität, aber sein positronisches Gehirn wurde polarisiert. Es ist jetzt negatronisch... und Techbots Verhalten wurde umgekehrt. Er wütet jetzt in ganz Gnomeregan!\n\nDoch vielleicht kann man ihn noch retten. Wenn Ihr seinen Speicherkern auffinden und zu mir bringen könnt, kann ich die Ursache der Polarisierung möglicherweise finden und meinen armen Techbot reparieren.\n\n", progress = "Habt Ihr Techbot gefunden? Habt Ihr seinen Speicherkern gefunden?", completion = "Oh, das ist wunderbar!! Danke, &lt;Name&gt;! Ich mache mich gleich an die Arbeit!!\n\nArmer, armer Techbot... Mach dir nichts daraus. Wir kriegen dich wieder hin.\n\nHm, wo hab ich diesen Aufsatz für meine Hydrowinden-Ratsche hingelegt...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[80138] = {title = "Tüftlermeister Overspark", objective = "Sprecht mit Tüftlermeister Overspark in Ironforge.", description = "Tüftlermeister Overspark ist ob des Schicksals seiner mechanischen Schöpfung, Techbot, ziemlich bestürzt. Ich erinnere mich an Techbot als ein freundliches und hilfsbereites Werkzeug der Gnome, aber Overspark erzählte mir, er hätte eine Fehlfunktion.\n\nWirklich traurig. Aber mit etwas Glück kann er vielleicht repariert werden!\n\nSprecht mit Tüftlermeister Overspark in Tüftlerstadt, Ironforge. Er würde sich über Eure Hilfe freuen.", progress = nil, completion = "Ja, es ist wahr. Techbot ist durchgedreht! Könnt Ihr mir bitte helfen?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[80139] = {title = "Gnogaine", objective = "Sammelt mit der leeren bleiernen Sammelphiole radioaktive Ablagerungen bestrahlter Eindringlinge oder Plünderer. Sobald sie voll ist, bringt Ihr sie zu Ozzie Togglevolt nach Kharanos zurück.", description = "Seit dem Unfall redet Gnoarn nur noch davon, Gnomeregan vom Troggbefall zu befreien und ein Heilmittel für die Erkrankung, die die Stadt verseucht, zu finden, <Name>.\n\nZum Glück sind Razzle und ich gerade dabei, ein solches Heilmittel zu entwickeln... oder vielleicht auch ein Rezept für wirklich starken Rum. Genau wissen wir das aber erst, wenn wir es ausprobiert haben! Logischerweise benötigen wir zum Test unserer Theorie ein paar Dinge, vor allem Ablagerungen von den bestrahlten Troggs in Gnomeregan. Füllt diese Phiole mit dem grünen Leuchten und bringt sie zurück!", progress = "Seht Ihr denn nicht, dass wir versuchen, ein ganzes Gnomenvolk zu heilen?! Wir brauchen mehr von dem grünen Leuchten!", completion = "Ausgezeichnete Arbeit! Es ist an der Zeit, die neue Formel zu testen. Wenn sie funktioniert, sollte nicht nur dieser gefangene Lepragnom bald geheilt sein, sondern ich auch wieder ordentlich Haare auf dem Kopf haben. Tretet zurück!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[80140] = {title = "Die Rückkehr des Rings", objective = "Ihr könnt den Ring entweder behalten oder die Person finden, die für die Prägung und Gravuren auf der Innenseite des Rings verantwortlich ist.", description = "Ihr öffnet die Schachtel, die der Funkelmat 5200 ausgegeben hat, und entdeckt einen glänzenden Ring! Beim Anstecken des Rings fühlt Ihr magische Macht durch Euren Körper fließen.\n\nAuf der Innenseite des Rings befindet sich eine kleine, aber dennoch klar erkennbare Gravur des Siegels von Orgrimmar. Daneben sind Buchstaben eingraviert, aber selbst nach der Säuberung sind nur die ersten drei zu erkennen: 'NOG...'\n\nDies könnten entweder die Initialen des ursprünglichen Besitzers oder die des Herstellers des Rings sein. Den Ring behalten...oder 'NOG' suchen - Entscheidungen, Entscheidungen...", progress = "Man sollte meinen, wir finden selbst einen Weg, diese dreckigen kleinen Gnome zu übertrumpfen. Ich würde sogar wetten, dass sie uns diese Maschine ursprünglich gestohlen haben! Pah, diese schleimigen, schmutzigen... ähm, ja? Braucht Ihr etwas?", completion = "Ein Ring aus Gnomeregan? Lasst mich mal sehen... nicht von mir, aber interessant.\n\nDiese Sache mit Gnomeregan - das hätte keinen größeren Trotteln passieren können. Jahrelang sind sie ein Witz und auf einmal bauen sie quasi über Nacht bessere Maschinen als wir?\n\nDunkeleisenzwerge hatten den Ring bei sich? Das wird ja immer interessanter! Hmmm, vielleicht haben die Gnome ja deren verrückte Golempläne gestohlen und verändert... Diese Dunkeleisenzwerge, die würden ihnen das bestimmt gern ordentlich heimzahlen. Es lohnt sich ganz sicher, da mal nachzuforschen.\n\nUnd da ist schließlich die Sache mit dem Ring...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[80141] = {title = "Noggs Ringerneuerung", objective = "Bringt Nogg in Orgrimmar den blitzenden Goldring, einen Silberbarren, einen Moosachat und 30 Silbermünzen.", description = "Nein, nein, nein - ich behaupte nicht plötzlich, der Ring sei meiner. Normalerweise mache ich so etwas nicht, aber Eure Information über die Dunkeleisenzwerge war sehr nützlich. Ich werde diesen Ring für Euch so verbessern, dass selbst der, der dieses einfache kleine Ding hergestellt hat, es nicht hätte besser machen können. Wahrscheinlich war es irgendein Gnom...\n\nWenn Ihr mir einen Barren Silber, einen Moosachat und dreißig Silbermünzen bringt, verziere ich den Ring damit derart, dass seine Magie noch verstärkt wird. Interessiert?", progress = "Habt Ihr die Materialien, die ich benötige? Ich kann dieses Stück nicht ohne die Dinge verbessern, um die ich Euch gebeten habe.", completion = "Hier habt Ihr Euren Ring, besser als je zuvor. Danke nochmals für die Information über diese Dunkeleisenzwerge. Das sieht nach einem vernünftigen Hinweis darauf aus, woher diese Gnome auf einmal mit Inspiration nach Goblinart gesegnet wurden.", rewards = "Ihr bekommt:\n\nNoggs blitzender Goldring"},
[80142] = {title = "Castpipes Auftrag", objective = "Sprecht mit Mechanikermeister Castpipe in Ironforge.Mechanikermeister Castpipe in Ironforge sucht Abenteurer! Er organisiert Teams, um Gnomeregan auf einer Datensicherungsmission höchster Sicherheitsstufe und Wichtigkeit zu betreten.\n\nCastpipe mag zwar nicht wie ich ein Mitglied der Erleuchteten Vereinigung für Arkanologie, Alchemie und Ingenieurwissenschaften sein, aber er ist dennoch ein kluger Gnom, und wenn er es für wichtig hält, dann besteht nach meinen Berechnungen eine vierundachtzigprozentige Wahrscheinlichkeit, dass es wirklich wichtig ist.\n\nDas ist eine gute Chance!Der folgende Zauber wird auf euch gewirkt:\n\n", description = "Mechanikermeister Castpipe in Ironforge sucht Abenteurer! Er organisiert Teams, um Gnomeregan auf einer Datensicherungsmission höchster Sicherheitsstufe und Wichtigkeit zu betreten.\n\nCastpipe mag zwar nicht wie ich ein Mitglied der Erleuchteten Vereinigung für Arkanologie, Alchemie und Ingenieurwissenschaften sein, aber er ist dennoch ein kluger Gnom, und wenn er es für wichtig hält, dann besteht nach meinen Berechnungen eine vierundachtzigprozentige Wahrscheinlichkeit, dass es wirklich wichtig ist.\n\nDas ist eine gute Chance!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[80143] = {title = "Datenrettung", objective = "Bringt Mechanikermeister Castpipe in Ironforge eine Prismalochkarte.", description = "Als wir aus Gnomeregan flohen, haben wir so viele Daten zurückgelassen! Lebenswichtige Informationen!\n\nIch brauche die Daten auf einer Prismalochkarte aus einem Matrix-Prägographen 3005-D, einem Hochsicherheitsterminal, tief in Gnomeregan. Ihr müsst auf dieses Terminal zugreifen, aber dafür braucht Ihr die Zugangsberechtigung...und um die zu erhalten, müsst Ihr erst Zugang zu den Terminals niedrigerer Sicherheitsstufen - Modelle A, B und C - haben. DAFÜR wiederum braucht Ihr Sicherheitslochkarten, angefangen mit einer weißen...Und wir haben alle Lochkarten in der Stadt vergessen.\n\nDas ist eine Katastrophe! Könnt Ihr helfen?", progress = "Habt Ihr die Prismalochkarte?", completion = "Ihr habt es geschafft! Ihr habt die Prismalochkarte gefunden und die verlorenen Daten wiederbeschafft! Lebenswichtige, kritische, unvorstellbar wertvolle Daten, ohne die wir keine Minute länger hätten leben können!\n\nDer Dienst, den Ihr den Gnomen erwiesen habt, wird lange in Erinnerung bleiben, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nSchlossercapeMechanikerrohrhammer"},
[80147] = {title = "Eigentümliches Relikt aus Dalaran", objective = "Habt Ihr eines der gestohlenen Relikte geborgen?", description = nil, progress = "Habt Ihr eines der gestohlenen Relikte geborgen?", completion = "Vielen Dank, &lt;Name&gt;. Ich werde dafür sorgen, dass es seinen Weg in die Stadt sicher zurückfindet.", rewards = "Ihr bekommt:\n\n"},
[80148] = {title = "Eigentümliches Relikt aus Dalaran", objective = "Habt Ihr eines der gestohlenen Relikte geborgen?", description = nil, progress = "Habt Ihr eines der gestohlenen Relikte geborgen?", completion = "Vielen Dank, &lt;Name&gt;. Ich werde dafür sorgen, dass es seinen Weg in die Stadt sicher zurückfindet.", rewards = "Ihr bekommt:\n\n"},
[80149] = {title = "Eigentümliches Relikt aus Dalaran", objective = "Habt Ihr eines der gestohlenen Relikte geborgen?", description = nil, progress = "Habt Ihr eines der gestohlenen Relikte geborgen?", completion = "Vielen Dank, &lt;Name&gt;. Ich werde dafür sorgen, dass es seinen Weg in die Stadt sicher zurückfindet.", rewards = "Ihr bekommt:\n\n"},
[80150] = {title = "Eigentümliches Relikt aus Dalaran", objective = "Habt Ihr eines der gestohlenen Relikte geborgen?", description = nil, progress = "Habt Ihr eines der gestohlenen Relikte geborgen?", completion = "Vielen Dank, &lt;Name&gt;. Ich werde dafür sorgen, dass es seinen Weg in die Stadt sicher zurückfindet.", rewards = "Ihr bekommt:\n\n"},
[80151] = {title = "Eigentümliches Relikt aus Dalaran", objective = "Habt Ihr eines der gestohlenen Relikte geborgen?", description = nil, progress = "Habt Ihr eines der gestohlenen Relikte geborgen?", completion = "Vielen Dank, &lt;Name&gt;. Ich werde dafür sorgen, dass es seinen Weg in die Stadt sicher zurückfindet.", rewards = "Ihr bekommt:\n\n"},
[80152] = {title = "Eigentümliches Relikt aus Dalaran", objective = "Habt Ihr eines der gestohlenen Relikte geborgen?", description = nil, progress = "Habt Ihr eines der gestohlenen Relikte geborgen?", completion = "Vielen Dank, &lt;Name&gt;. Ich werde dafür sorgen, dass es seinen Weg in die Stadt sicher zurückfindet.", rewards = "Ihr bekommt:\n\n"},
[80153] = {title = "Der Funkelmat 5200!", objective = "Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren.", description = "Dieser Apparat ist etwas ganz Besonderes unter den Gnomen, er bietet dem Wahnsinn außerhalb dieses Raums tapfer die Stirn. Eine kleine Plakette auf dem Gerät besagt: \"Der Funkelmat 5200\", gefolgt von einem kurzen Text:\n\n\"Schmutz und Verkrustungen ruinieren Euer Funkelzeug? Der Funkelmat 5200 definiert das Wort Glanz neu! Gebt den Gegenstand hinein, den Ihr gesäubert haben wollt, und werft drei Silbermünzen in den Münzschlitz. Lasst den Funkelmat 5200 einen Moment arbeiten - und voilà! Eure Wertgegenstände werden sauber und glänzend herauskommen!\"", progress = "Es scheint, als brauche das Gerät irgendein schmutzverkrustetes Objekt zum Säubern sowie drei Silbermünzen, um den Apparat in Gang zu bringen. Ist beides vorhanden, sollte der Funkelmat 5200 funktionieren...", completion = "Ihr füttert den Funkelmat 5200 mit dem schmutzverkrusteten Gegenstand sowie mit drei Silbermünzen. Die Maschine erwacht schlagartig zum Leben und versucht hektisch, den unbekannten Gegenstand vom Schmutz zu reinigen. Laute, heftig peitschende Geräusche schlagen Euch aus dem Herzen der Maschine entgegen. Der Metallrahmen des Apparats knarrt und ächzt während er hin und her schlingert...", rewards = nil},
[80155] = {title = "Funkelmatastisch", objective = "Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!", description = nil, progress = "Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!", completion = "Der Funkelmat 5200 erwacht hin und her schlingernd zum Leben. Innen wird der hilflose Schmutz, der das eingelegte Objekt verkrustet hat, vom Gnomenlösungsmittel der Maschine pulverisiert.\n\nDer Funkelmat 5200 kommt zum Stillstand, angekündigt durch ein vertrautes \"Ding!\". Der Aufnahmebehälter der Maschine springt auf und offenbart eine ordentlich eingewickelte Schachtel.", rewards = "Ihr bekommt:\n\nFunkelmatverpackter Kasten"},
[80157] = {title = "Der Funkelmat 5200!", objective = "Der Funkelmat 5200 stoppt so schnell, wie er losgelegt hat. Ein einfaches \"Ding\" ist aus der Maschine zu hören und der Aufnahmebehälter der Maschine springt auf. Im Funkelmat 5200 liegt eine kleine Schachtel, die von einem Schleifchen umschlungen ist. Offensichtlich verpackt die Maschine ein Objekt, nachdem sie die Schmutzverkrustung entfernt hat. Selbst wenn die Maschine nicht funktioniert hat, ist der Gegenstand jetzt immerhin in einer hübschen Schachtel verpackt.\n\nTja, es gibt nur einen Weg herauszufinden, ob sie den Gegenstand gesäubert hat oder nicht...", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nFunkelmatverpackter Kasten"},
[80158] = {title = "Der Funkelmat 5200!", objective = "Gebt einen schmutzverkrusteten Gegenstand in den Funkelmat 5200 und stellt sicher, dass Ihr drei Silbermünzen habt, um die Maschine zu aktivieren.", description = "Dieser Apparat ist etwas ganz Besonderes unter den Gnomen, er bietet dem Wahnsinn außerhalb dieses Raums tapfer die Stirn. Eine kleine Plakette auf dem Gerät besagt: \"Der Funkelmat 5200\", gefolgt von einem kurzen Text:\n\n\"Schmutz und Verkrustungen ruinieren Euer Funkelzeug? Der Funkelmat 5200 definiert das Wort Glanz neu! Gebt den Gegenstand hinein, den Ihr gesäubert haben wollt, und werft drei Silbermünzen in den Münzschlitz. Lasst den Funkelmat 5200 einen Moment arbeiten - und voilà! Eure Wertgegenstände werden sauber und glänzend herauskommen!\"", progress = "Es scheint, als brauche das Gerät irgendein schmutzverkrustetes Objekt zum Säubern sowie drei Silbermünzen, um den Apparat in Gang zu bringen. Ist beides vorhanden, sollte der Funkelmat 5200 funktionieren...", completion = "Ihr füttert den Funkelmat 5200 mit dem schmutzverkrusteten Gegenstand sowie mit drei Silbermünzen. Die Maschine erwacht schlagartig zum Leben und versucht hektisch, den unbekannten Gegenstand vom Schmutz zu reinigen. Laute, heftige, peitschende Geräusche schlagen Euch aus dem Herzen der Maschine entgegen. Der Metallrahmen des Apparats knarrt und ächzt, als er hin und her schlingert...", rewards = nil},
[80160] = {title = "Funkelmatastisch", objective = "Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!", description = nil, progress = "Der Funkelmat 5200 ist leer und wartet auf ein schmutzverkrustetes Objekt zum Säubern sowie auf drei Silbermünzen, um loszulegen!", completion = "Der Funkelmat 5200 erwacht hin und her schlingernd zum Leben. Innen wird der hilflose Schmutz, der das eingelegte Objekt verkrustet hat, vom Gnomenlösungsmittel der Maschine pulverisiert.\n\nDer Funkelmat 5200 kommt zum Stillstand, angekündigt durch ein vertrautes \"Ding!\". Der Aufnahmebehälter der Maschine springt auf und offenbart eine ordentlich eingewickelte Schachtel.", rewards = "Ihr bekommt:\n\nFunkelmatverpackter Kasten"},
[80161] = {title = "Der Funkelmat 5200!", objective = "Der Funkelmat 5200 stoppt so schnell, wie er losgelegt hat. Ein einfaches \"Ding\" ist aus der Maschine zu hören und der Aufnahmebehälter der Maschine springt auf. Im Funkelmat 5200 liegt eine kleine Schachtel, die von einem Schleifchen umschlungen ist. Offensichtlich verpackt die Maschine ein Objekt, nachdem sie die Schmutzverkrustung entfernt hat. Selbst wenn die Maschine nicht funktioniert hat, ist der Gegenstand jetzt immerhin in einer hübschen Schachtel verpackt.\n\nTja, es gibt nur einen Weg herauszufinden, ob sie den Gegenstand gesäubert hat oder nicht...", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nFunkelmatverpackter Kasten"},
