[80168] = {title = "Zünder für Feuerwerk", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBauplan: Zünder für FeuerwerkFeuerwerkspaket des Mondfests"},
[80169] = {title = "Zünder für Raketenbündel", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBauplan: Zünder für RaketenbündelFeuerwerkspaket des Mondfests"},
[80170] = {title = "Festtagsmuster", objective = "Die Kleider und Hosenanzüge, die Ihr hier sehen könnt, sind traditionelle Gewänder vergangener Zeiten. Sie werden zu Ehren alter Gebräuche und geliebter Vorfahren getragen.\n\nBringt Ihr mir Münzen der Urahnen, <Name>, werde ich Euch das Muster zur Herstellung traditioneller roter Kleider oder Hosenanzüge geben.", description = nil, progress = "Die Kleider und Hosenanzüge, die Ihr hier sehen könnt, sind traditionelle Gewänder vergangener Zeiten. Sie werden zu Ehren alter Gebräuche und geliebter Vorfahren getragen.\n\nBringt Ihr mir Münzen der Urahnen, <Name>, werde ich Euch das Muster zur Herstellung traditioneller roter Kleider oder Hosenanzüge geben.", completion = "Hier sind die Muster, &lt;Name&gt;. Ich bin mir sicher, dass Ihr die Ergebnisse dieses Herstellungsgeheimnisses wunderschön finden werdet.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMuster: FesttagskleidMuster: Festtagsanzug\n\nIhr bekommt außerdem:\n\nFeuerwerkspaket des Mondfests"},
[80180] = {title = "Der große Verrat", objective = "Reist nach Gnomeregan und tötet Robogenieur Thermaplugg. Kehrt zu Hochtüftler Mekkatorque zurück, wenn der Auftrag ausgeführt ist.", description = "Ich habe Thermaplugg vertraut, <Volk>. Ich hätte nie vermutet, dass er mich und das ganze Gnomenvolk verraten würde. Und wofür? Macht? Reichtum? Alles Dinge, die er mit der Zeit auch so erlangt hätte. Jetzt sind wir aus unserer Heimat verdrängt worden und dieser Wahnsinnige ist dafür verantwortlich. Der König des Nichts...\n\nWir werden Gnomeregan zurückerobern, <Name>. Wir werden nicht ruhen, bis die Stadt wieder unter unserer Kontrolle steht. Wenn Ihr Euch unserem Kampf anschließen wollt, habe ich eine einfache Bitte an Euch: Tötet den Verräter. Vernichtet Robogenieur Thermaplugg.", progress = nil, completion = "Ich stelle mir gern vor, dass das Letzte, was ihm durch den Kopf ging, bevor er zu Boden sank, Euer Fuß war, &lt;Volk&gt;. Jetzt, da Thermaplugg tot ist, sind wir der Verwirklichung unseres Plans, Gnomeregan wiederzuerobern, einen Schritt näher gekommen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMakellose Civinad-RobenBehände Latzhose des StolperläufersDreifach verstärkte Gamaschen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[80181] = {title = "Gyrobohrmatische Exkavation", objective = "Bringt 24 robomechanische Gedärme zu Shoni nach Stormwind.", description = "Es ist schrecklich, <Name>. Wir werden nicht genug Teile haben, um unsere Flotte aus gyrobohrmatischen Exkavationatoren nach Dun Morogh zu bringen.\n\nWir brauchen Ersatzteile, <Name>. Und welch besseren Ort als Gnomeregan könnte es geben, um Ersatzteile für unsere Fahrzeuge zu besorgen? Es heißt, dass Bots und Mechs dort herumlaufen wie Vieh auf der Weide.\n\nIhr müsst für mich nach Gnomeregan gehen und diese Roboter auseinandernehmen. Bringt mir ihre Gedärme. Zwei Dutzend sollten ausreichen.", progress = "Wenn dies ein Wettrennen wäre, hättet Ihr bereits verloren.", completion = "Das dürfte reichen, &lt;Name&gt;. Ein gyrobohrmatischer Exkavationator ist geflickt; fehlen noch 398.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nShonis ZerlegungswerkzeugFäustlinge der Entschlossenheit\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[80182] = {title = "Das einzige Heilmittel ist mehr grünes Leuchten", objective = "Reist nach Gnomeregan und bringt etwas von der hochwirksamen radioaktiven Ablagerung zurück. Seid gewarnt, die Ablagerung ist instabil und wird ziemlich schnell zerfallen.\n\nOzzie wird außerdem Eure schwere bleierne Sammelphiole benötigen, nachdem die Aufgabe erledigt ist.", description = "Eure Probe war nicht nur von unzureichender Menge, sondern auch noch verunreinigt.\n\nWas wir brauchen, ist mehr von dem grünen Leuchten. Die Troggs sind offensichtlich nicht stark genug verstrahlt, um unseren Ansprüchen zu genügen. Ihr werdet nach Gnomeregan gehen und etwas der radioaktiven Ablagerung direkt von der Quelle besorgen müssen. Ich spreche von den bestrahlten Schleimen, Lauerern und Schrecken. Seid gewarnt, diese Art von Ablagerung ist schwer abzufüllen. Es könnte Euch mehrere Versuche mit der Phiole kosten, bis Ihr eine geeignete Probe bergen könnt.", progress = "Hm, Ihr leuchtet nicht. Das ist ein gutes Zeichen.", completion = "&lt;Ozzie mustert Euch.&gt; Erstaunlich, Ihr habt noch all Eure Gliedmaßen. Jetzt ist es an der Zeit nachzusehen, was dieses Zeug ausrichten kann!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[80241] = {title = "Die Herkunft der Schmiedekunst", objective = "Bringt 6 goldene Schuppenarmschienen zu Hank dem Hammer in Stormwind.", description = "Als ich etwa so alt war wie Ihr, nahm mich ein Zwerg namens Galvan unter seine Fittiche und bildete mich in der Kunst des Rüstungsschmiedens aus. Bevor er sich nach Booty Bay aufmachte, nahm er mir das Versprechen ab, dass ich all denjenigen ein Lehrer sein würde, die den Wunsch hätten und entschlossen genug wären, selbst eine Schmiedelaufbahn einschlagen zu wollen. Und hier bin ich nun - all die Jahre später.\n\nAlso, es ist jetzt Zeit für Euch, ein bisschen was zu lernen. Stellt mir sechs goldene Schuppenarmschienen her, dann zeige ich Euch, was echte Schmiedekunst ist, <Name>.", progress = "Sollet Ihr vielleicht der nächste Zögling von Galvan sein?", completion = "Sehr gut, &lt;Name&gt;! Hört zu und lernt.\n\nDie wahre Schmiedekunst entsteht niemals hier! \n\nDie wahre Schmiedekunst entsteht niemals hier! \n\nDie wahre Schmiedekunst entsteht nur hier und nirgends sonst! \n\nJetzt wisst Ihr, wo die wahre Schmiedekunst herkommt.", rewards = "Ihr bekommt:\n\nPläne: Goldene Schuppenstulpen"},
[80307] = {title = "Eine komplette Lieferung", objective = "Habt Ihr etwas für mich?", description = nil, progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, &lt;Name&gt;. Diese Vorräte sind an vorderster Front unentbehrlich.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRuf - Händlerfraktion\n\nIhr bekommt:\n\n"},
[80308] = {title = "Eine komplette Lieferung", objective = "Habt Ihr etwas für mich?", description = nil, progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, &lt;Name&gt;. Diese Vorräte sind an vorderster Front unentbehrlich.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRuf - Händlerfraktion\n\nIhr bekommt:\n\n"},
[80309] = {title = "Eine komplette Lieferung", objective = "Habt Ihr etwas für mich?", description = nil, progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, &lt;Name&gt;. Diese Vorräte sind an vorderster Front unentbehrlich.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRuf - Händlerfraktion\n\nIhr bekommt:\n\n"},
[80324] = {title = "Der irre König", objective = "Bringt Thermapluggs Ingenieursnotizen zu Hochtüftler Mekkatorque in der Tüftlerstadt von Ironforge.", description = "Ihr findet ein schmutziges, zerfleddertes Notizbuch, das mit Bauplänen und Notizen vollgekritzelt ist. Nach einem kurzen, oberflächlichen Blick wird Euch bereits klar, dass jede dieser Kreationen verheerendes Unheil anrichten könnte, sollte jemand so närrisch sein, sie tatsächlich zu bauen.", progress = "<Name>, was habt Ihr da?", completion = "Ich kann Euch nicht genug dafür danken, diese Baupläne zurückgebracht zu haben. Ich möchte nicht mal daran denken, was mit Ironforge passiert wäre, wenn Thermaplugg diese Kreationen gegen uns gerichtet hätte.\n\nDas schreit nach einer Feier!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAnhänger der HeimkehrKolbenanhängerHalsreif des Gesetzeshüters von GnomereganJustizabzeichen"},
[80325] = {title = "Der irre König", objective = "Bringt Thermapluggs Ingenieursnotizen zu Nogg im Tal der Ehre in Orgrimmar.", description = "Ihr findet ein schmutziges, zerfleddertes Notizbuch, das mit Bauplänen und Notizen vollgekritzelt ist. Nach einem kurzen, oberflächlichen Blick wird Euch bereits klar, dass jede dieser Kreationen verheerendes Unheil anrichten könnte, sollte jemand so närrisch sein, sie tatsächlich zu bauen.", progress = "Was habt Ihr für mich?", completion = "&lt;Noggs Augen leuchten auf, während er durch die Sammlung aus Notizen und Bauplänen blättert.&gt;\n\nDamit werde ich so viel Zeug in die Luft jagen.\n\nGute Arbeit, &lt;Name&gt;. Ich glaube, das schreit nach einer Feier!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAnhänger der HeimkehrKolbenanhängerHalsreif des Gesetzeshüters von GnomereganJustizabzeichen"},
[80411] = {title = "Der Talisman von Kazdor", objective = "Findet den Talisman von Kazdor in Zul'Farrak. Bringt ihn anschließend zu Fahrad im Ravenholdt-Anwesen. Ihr müsst diese Aufgabe alleine erledigen.", description = "Aus dem jüngsten Brief schließen wir, dass es sich bei dem letzten Artefakt, das Caius begehrt, um den Talisman von Kazdor handelt. Im Brief wird erwähnt, dass dieser Talisman sich irgendwo in Zul'Farrak befindet.\n\nIch möchte Euch bitten, Caius' Auftrag zu beenden, um nicht seinen Verdacht zu erregen. Das bedeutet, Ihr werdet alleine nach Zul'Farrak gehen müsst, wie immer.\n\nDoch bevor Ihr den Talisman übergebt, bringt ihn hierher. Wie werden Caius mehr überbringen, als er sich erhofft.", progress = "Geht jetzt, wir haben keine Zeit zu verlieren.", completion = "Ihr habt flinke Finger, &lt;Name&gt;. Also, auf zu Schritt zwei.", rewards = "Ihr bekommt:\n\n"},
[80417] = {title = "Weiche buschige Schweife", objective = "Es ist unglaublich was Leute so alles schätzen! Wie wäre es zum Beispiel mit einem Stock, an dem man einen weichen buschigen Schwanz hängt. Ihr und ich mögen nun denken, dass derartiges keinerlei Wert hat... aber verpasst man so einem Quatsch einen netten Namen wie \"Wilder Wuschelschwanz\" und packt das Ganze in eine hübsche Schachtel, dann erscheint es den Leuten plötzlich wertvoll. Aus Tand werden heiß begehrte Objekte!\n\nBesorgt mir ein paar weiche buschige Schwänze von Wölfen aus Desolace und dem Ödland, dann werde ich Euch dafür Lose des Dunkelmond-Jahrmarkts geben.", description = nil, progress = "Es ist unglaublich was Leute so alles schätzen! Wie wäre es zum Beispiel mit einem Stock, an dem man einen weichen buschigen Schwanz hängt. Ihr und ich mögen nun denken, dass derartiges keinerlei Wert hat... aber verpasst man so einem Quatsch einen netten Namen wie \"Wilder Wuschelschwanz\" und packt das Ganze in eine hübsche Schachtel, dann erscheint es den Leuten plötzlich wertvoll. Aus Tand werden heiß begehrte Objekte!\n\nBesorgt mir ein paar weiche buschige Schwänze von Wölfen aus Desolace und dem Ödland, dann werde ich Euch dafür Lose des Dunkelmond-Jahrmarkts geben.", completion = "Gut gemacht, &lt;Name&gt;! Diese buschigen Schwänze werden unseren Besuchern gefallen - und das bedeutet sogleich glückliche Besucher... Besucher, die ihren Freunden vom Jahrmarkt erzählen und somit für noch mehr Publikum sorgen!\n\nHier sind Eure Lose! Viel Spaß auf dem Dunkelmond-Jahrmarkt... und vergesst nicht Euren Freunden von uns zu erzählen!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[80421] = {title = "Grüne Eisenarmschienen", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[80422] = {title = "Grünes Feuerwerk", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[80423] = {title = "Der größte Gnom der Welt!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[80453] = {title = "Beste ausgeheckte Pläne", objective = "Bringt den Talisman von Kazdor zu Zan Shivsproket im Keller des Ravenholdt-Anwesens.", description = "Bringt den Talisman zu Zan Shivsproket im Keller. Ich habe ihn gebeten, das Artefakt mit einem Mechanismus zu verbinden, der jeden Versuch nachweisen kann, Magie in es oder aus ihm heraus zu kanalisieren.\n\nDer Mechanismus ist mit bloßem Auge nicht zu sehen und explodiert, wenn er ausgelöst wird. Mit etwas Glück wird Caius bei der Explosion getötet. Aber zumindest werden seine Pläne mit dem Talisman durchkreuzt werden.", progress = "Ja, <Klasse>? Braucht Ihr etwas von mir?", completion = "Ihr macht also bei Fahrads Auftrag mit? Nun gut. Gebt mir den Talisman und ich mache mich an die Arbeit.", rewards = nil},
[80454] = {title = "Eine letzte Lieferung", objective = "Bringt den angepassten Talisman zu Caius totem Briefkasten in der Nähe von Pyrewood.", description = "Der Köder ist bereit, jetzt müssen wir die Falle auslegen. Ich habe den Talisman nach Fahrads Anweisungen angepasst. Alles, was Ihr nun tun müsst, ist, ihn auszuliefern, wie Ihr es mit den anderen Artefakten getan habt.\n\nGeht zur Hütte in der Nähe von Pyrewood und werft den Talisman in Caius' toten Briefkasten.\n\nWas danach passiert, liegt nicht in unseren Händen, vorerst.", progress = "<Die Kiste ist leer.>", completion = "&lt;Ihr legt den angepassten Talisman in die Kiste.&gt;", rewards = nil},
[80455] = {title = "Sich Zeit nehmen", objective = "Erstattet Fahrad am Ravenholdt-Anwesen Bericht.", description = "Der Auftrag ist erledigt. Kehrt besser nach Ravenholdt zurück und gebt Fahrad Bescheid.", progress = nil, completion = "Alles scheint nach Plan gelaufen zu sein. Gute Arbeit.\n\nJetzt können wir nur noch abwarten, bis Caius den nächsten Schritt macht. Ich werde Euch benachrichtigen, wenn es so weit ist. Euer Einsatz für das Anwesen ist noch nicht ganz abgeschlossen.\n\nDoch für den Moment könnt Ihr Euch zurücklehnen.", rewards = "Ihr bekommt:\n\nRune des ZirkelsDiebesgugel"},
[80526] = {title = "Schande über mich", objective = "Sprecht mit Fahrad, wenn Ihr bereit seid, seinen Plan anzuhören.", description = "Keinen Augenblick zu früh, <Name>.\n\nDas Anwesen hat diesen \"C\" beobachtet, mit dem Ihr es zu tun habt.\n\nSeine wahre Identität ist Caius Schwarzholz, ein mächtiger Nutzer der Magie, der mit dem Syndikat zusammenarbeitet. Unsere Quellen sagen, dass er aus unbekanntem Grund Artefakte ansammelt. Wir haben erst vor Kurzem erfahren, dass *Ihr* ihn damit versorgt habt.\n\nCaius muss aufgehalten werden und ich glaube, Ihr solltet Euch darum kümmern. Zum Glück habe ich einen Plan. Sprecht mit mir, wenn Ihr bereit seid, Euren Namen reinzuwaschen.", progress = nil, completion = "Gut, dann lasst uns zum Geschäft kommen.", rewards = nil},
[81570] = {title = "Jarl braucht eine Klinge", objective = "Bringt ein Mondstahlbreitschwert zu Jarl in den Marschen von Dustwallow.", description = "Ich habe zu schneiden. Ich kann Euch nicht sagen, was ich schneiden werde, aber... ich brauche eine Klinge. Eine ganz bestimmte Klinge...\n\nManche Leute nennen sie Mondstahlbreitschwert. Ich nenne sie eine Schwingklinge.\n\nHelft Ihr mir? Vielleicht findet Ihr sie in der Stadt. Wenn Ihr mit einem Schmied sprecht, macht er sie vielleicht besonders.\n\nAber schlaft nicht noch darüber. Was ich schneide, das hält nicht ewig...", progress = "Habt Ihr meine Klinge???", completion = "Das ist eine gute Klinge. Sie schwingt gut. Es ist eine gute Schwingklinge. Danke. Danke, danke, danke!!! Jetzt möchte ich sie ausprobieren... \n\nSpäter. Ich probiere sie später aus. Aber wie ich schon sagte... danke.", rewards = "Ihr bekommt:\n\nSchilfknotenringFachmann-Beinkleider"},
[81682] = {title = "Der alte Champion", objective = "Sucht nach Kajind in Azshara.", description = "Diese Arena mag unscheinbar wirken, aber ich sage Euch, sie war einst eine große Attraktion. Preiskämpfer, Abenteurer und sogar ein paar Kartellanhänger sind dort für Geld und Glorie in den Ring gestiegen.\n\nMit den Wetten und Lizenzen habe ich ein Vermögen verdient!\n\nDie Sache ging aber den Bach runter, als der alte Champion Kajind sich aufs Altenteil zurückzog. Er war eher in sich gekehrt und verließ Azshara eines Tages, ohne einen Ton zu sagen. Wenn Ihr ihn findet, könnten wir den Arenabetrieb wiederaufnehmen.", progress = nil, completion = "&lt;Ein Anflug von Wehmut legt sich kurz auf Kajinds Gesicht&gt;\n\nIch bin in der Tat der sogenannte \"Champion\", den Ihr sucht.", rewards = nil},
[81697] = {title = "Entzahnt", objective = "Beschafft Kajinds Klinge von dem blauen Drachen in der Gegend südöstlich des Einsamen Grats in Azshara.", description = "Ich kenne nur den Kampf, <Name>. Während des Dritten Krieges sind zahllose Gegner durch meine Klinge gefallen. Als er vorbei war, schlug ich mich als Preiskämpfer durch. So bin ich auf die Arena von Gadgetzan gestoßen.\n\nIch habe dort ruhmreiche Tage erlebt, wurde des Lebens eines Champions jedoch bald müde. Nach Azshara kam ich auf der Suche nach einer größeren Herausforderung, einem Blaudrachen, der die Gegend südöstlich von hier durchstreift. Leider besiegte mich die Kreatur. Ich kam mit dem Leben davon, doch meine Klinge nahm sie in ihren Hort mit.\n\nWenn Ihr mein Schwert wiederbeschafft, kehre ich mit Euch nach Gadgetzan zurück.", progress = "Ich mache Euch Euer Zögern nicht zum Vorwurf, <Volk>. Der Drache ist ein furchterregender Gegner.", completion = "Wo ich einst versagte, habt Ihr Erfolg gehabt. Ihr verdient meine tiefste Hochachtung und Dankbarkeit, &lt;Name&gt;. Vielleicht besiegt Ihr mich auch in der Arena.", rewards = "Ihr bekommt:\n\n"},
[81716] = {title = "Feldbericht zum Einfall beschaffen: Dämmerwald", objective = "Tötet Dämonen und bringt den Feldbericht zu Feldhauptmann Palandar.", description = "Elune sei Dank, dass Ihr hier seid, <Name>. Wir werden von Dämonen überrannt, die durch das Tor des Smaragdgrünen Traums kommen. Ich habe den Kontakt zu meiner Späherin dort verloren. Sie heißt Charla. Bitte sucht sie am Traumtor und kehrt mit ihrem Feldbericht zurück. Und tötet auf Eurem Weg ein paar dieser schwärmenden Dämonen. Sobald Ihr mir den Bericht überreicht habt, erteile ich Euch einen Folgeauftrag, je nach den daraus gewonnenen Erkenntnissen.", progress = "Ihr habt den Bericht?", completion = "Danke, &lt;Name&gt;! Auf der Grundlage der von Euch beschafften Informationen habe ich diesen Folgeauftrag für Euch. Danke für Eure Hilfe!", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81727] = {title = "Feldbericht zum Einfall beschaffen: Ashenvale", objective = "Tötet Dämonen und bringt den Feldbericht zu Feldhauptmann Hannalah.", description = "Elune sei Dank, dass Ihr hier seid, <Name>. Wir werden von Dämonen überrannt, die durch das Tor des Smaragdgrünen Traums kommen. Ich habe den Kontakt zu meinem Späher dort verloren. Er heißt Gemeron. Bitte sucht ihn am Traumtor und kehrt mit seinem Feldbericht zurück. Und tötet auf Eurem Weg ein paar dieser schwärmenden Dämonen. Sobald Ihr mir den Bericht überreicht habt, erteile ich Euch einen Folgeauftrag, je nach den daraus gewonnenen Erkenntnissen.", progress = "Ihr habt den Bericht?", completion = "Danke, &lt;Name&gt;! Auf der Grundlage der von Euch beschafften Informationen habe ich diesen Folgeauftrag für Euch. Danke für Eure Hilfe!", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Ashenvale"},
[81728] = {title = "Feldbericht zum Einfall beschaffen: Hinterland", objective = "Tötet Dämonen und bringt den Feldbericht zu Feldhauptmann Korlian.", description = "Elune sei Dank, dass Ihr hier seid, <Name>. Wir werden von Dämonen überrannt, die durch das Tor des Smaragdgrünen Traums kommen. Ich habe den Kontakt zu meiner Späherin dort verloren. Sie heißt Fallia. Bitte sucht sie am Traumtor und kehrt mit ihrem Feldbericht zurück. Und tötet auf Eurem Weg ein paar dieser schwärmenden Dämonen. Sobald Ihr mir den Bericht überreicht habt, erteile ich Euch einen Folgeauftrag, je nach den daraus gewonnenen Erkenntnissen.", progress = "Ihr habt den Bericht?", completion = "Danke, &lt;Name&gt;! Auf der Grundlage der von Euch beschafften Informationen habe ich diesen Folgeauftrag für Euch. Danke für Eure Hilfe!", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Hinterland"},
[81729] = {title = "Feldbericht zum Einfall beschaffen: Feralas", objective = "Tötet Dämonen und bringt den Feldbericht zu Feldhauptmann Arunnel.", description = "Elune sei Dank, dass Ihr hier seid, <Name>. Wir werden von Dämonen überrannt, die durch das Tor des Smaragdgrünen Traums kommen. Ich habe den Kontakt zu meinem Späher dort verloren. Er heißt Thandros. Bitte sucht ihn am Traumtor und kehrt mit seinem Feldbericht zurück. Und tötet auf Eurem Weg ein paar dieser schwärmenden Dämonen. Sobald Ihr mir den Bericht überreicht habt, erteile ich Euch einen Folgeauftrag, je nach den daraus gewonnenen Erkenntnissen.", progress = "Ihr habt den Bericht?", completion = "Danke, &lt;Name&gt;! Auf der Grundlage der von Euch beschafften Informationen habe ich diesen Folgeauftrag für Euch. Danke für Eure Hilfe!", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Feralas"},
[81730] = {title = "Dämmerwaldmission I: Worgen besiegen", objective = "Besiegt 10 Alptraumläufer und 10 Alptraumwirker im Dämmerwald-Alptraumeinfall im Verlassenen Obstgarten und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall im Verlassenen Obstgarten. Besiegt dort Worgen und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81731] = {title = "Dämmerwaldmission II: Oger besiegen", objective = "Besiegt 3 verwirrte Oger und 3 wahnsinnige Feuerwirker im Dämmerwald-Alptraumeinfall beim Ogerhort Vul'Gol und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall im Ogerhort Vul'Gol. Besiegt dort Oger und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81732] = {title = "Dämmerwaldmission III: Drachkin besiegen", objective = "Besiegt 3 Terrorwandlerwyrmkin und 10 Nachtterrorwelpen im Dämmerwald-Alptraumeinfall bei Yorgens Bauernhof und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall bei Yorgens Bauernhof. Besiegt dort Drachkin und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81733] = {title = "Dämmerwaldmission IV: Oger ausspionieren", objective = "Beschafft einen Bericht von Traumwächter Thalinar im Dämmerwald-Alptraumeinfall tief im Ogerhort Vul'Gol und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall im Ogerhort Vul'Gol. Beschafft dort einen Geheimdienstbericht von Traumwächter Thalinar und kehrt zu mir zurück.", progress = "Ihr habt den Bericht?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81734] = {title = "Dämmerwaldmission V: Worgen ausspionieren", objective = "Beschafft einen Bericht von Traumwächter Dorilar im Dämmerwald-Alptraumeinfall in der Scheune des Verlassenen Obstgartens und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall im Verlassenen Obstgarten. Beschafft dort einen Geheimdienstbericht von Traumwächter Dorilar und kehrt zu mir zurück.", progress = "Ihr habt den Bericht?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81735] = {title = "Dämmerwaldmission VI: Drachen ausspionieren", objective = "Beschafft einen Bericht von Traumwächterin Amalia im Dämmerwald-Alptraumeinfall im Haus von Yorgens Bauernhof und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall bei Yorgens Bauernhof. Beschafft dort einen Geheimdienstbericht von Traumwächterin Amalia und kehrt zu mir zurück.", progress = "Ihr habt den Bericht?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81736] = {title = "Dämmerwaldmission VII: Schattensichel beschaffen", objective = "Beschafft die Schattensichel aus dem Dämmerwald-Alptraumeinfall im Obergeschoss des Bauernhauses im Verlassenen Obstgarten und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall im Verlassenen Obstgarten. Beschafft dort ein mächtiges Artefakt namens Schattensichel und bringt es mir.", progress = "Ihr habt die Schattensichel?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81737] = {title = "Dämmerwaldmission VIII: Ogermagiertext beschaffen", objective = "Beschafft einen Ogermagiertext aus dem Dämmerwald-Alptraumeinfall im Ogerhort Vul'Gol und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall im Ogerhort Vul'Gol. Beschafft dort einen Ogermagiertext und bringt ihn mir.", progress = "Ihr habt den Text?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81738] = {title = "Dämmerwaldmission IX: Drachenei beschaffen", objective = "Beschafft ein ungeschlüpftes grünes Drachenei aus dem Dämmerwald-Alptraumeinfall neben dem großen Stumpf auf dem Feld von Yorgens Bauernhof und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall bei Yorgens Bauernhof. Beschafft dort ein ungeschlüpftes grünes Drachenei und bringt es mir.", progress = "Ihr habt das Ei?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81739] = {title = "Dämmerwaldmission X: Alptraummoos", objective = "Sammelt 10 Stück Alptraummoos in den Dämmerwald-Alptraumeinfällen und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und beschafft Alptraummoos aus den Alptraumeinfällen. Wir können seine Magie zur Schadensumkehr nutzen. Ihr werdet die Hilfe eines Kräuterkundigen brauchen.", progress = "Ihr habt das Alptraummoos?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81740] = {title = "Dämmerwaldmission XI: Kalteisenerz", objective = "Sammelt 10 Stück Kalteisenerz in den Dämmerwald-Alptraumeinfällen und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und beschafft Kalteisenerz aus den Alptraumeinfällen. Wir können seine Magie zur Schadensumkehr nutzen. Ihr werdet die Hilfe eines Minenarbeiters brauchen.", progress = "Ihr habt das Kalteisenerz?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81741] = {title = "Dämmerwaldmission XII: Traumberührte Drachenschuppe", objective = "Sammelt 10 traumberührte Drachenschuppen in den Dämmerwald-Alptraumeinfällen und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und beschafft traumberührte Drachenschuppen von Drachkin aus den Alptraumeinfällen. Wir können ihre Magie zur Schadensumkehr nutzen. Ihr werdet die Hilfe eines Kürschners brauchen.", progress = "Ihr habt die Drachenschuppen?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81742] = {title = "Dämmerwaldmission XIII: Ylanthrius besiegen", objective = "Besiegt Ylanthrius im Dämmerwald-Alptraumeinfall beim Feld von Yorgens Bauernhof und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall bei Yorgens Bauernhof. Besiegt dort den Drachen Ylanthrius und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81743] = {title = "Dämmerwaldmission XIV: Vvarc'zul besiegen", objective = "Besiegt Vvarc'zul im Dämmerwald-Alptraumeinfall tief im Ogerhort Vul'Gol und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall im Ogerhort Vul'Gol. Besiegt dort den Kriegsfürsten Vvarc'zul und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81744] = {title = "Dämmerwaldmission XV: Amokarok besiegen", objective = "Besiegt Amokarok im Dämmerwald-Alptraumeinfall auf einem Lagerplatz neben der Scheune des Verlassenen Obstgartens und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall im Verlassenen Obstgarten. Besiegt dort den Worgenanführer Amokarok und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81745] = {title = "Dämmerwaldmission XVI: Kroll Bergschatten retten", objective = "Rettet Kroll Bergschatten aus dem Dämmerwald-Alptraumeinfall im Gasthaus des Verlassenen Obstgartens und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall im Verlassenen Obstgarten. Findet dort den schlafenden Druiden Kroll Bergschatten und bringt ihn in Sicherheit. Kehrt dann zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81746] = {title = "Dämmerwaldmission XVII: Alara Hainheiler retten", objective = "Rettet Alara Hainheiler im Dämmerwald-Alptraumeinfall im Stall von Yorgens Bauernhof und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall bei Yorgens Bauernhof. Findet dort die schlafende Druidin der Klaue Alara Hainheiler und bringt sie in Sicherheit. Kehrt dann zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81747] = {title = "Dämmerwaldmission XVII: Elenora Marschenläufer retten", objective = "Rettet Elenora Marschenläufer aus dem Dämmerwald-Alptraumeinfall in den Ruinen eines Bauernhauses nahe des Ogerhorts Vul'Gol und kehrt zu Feldhauptmann Palandar zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums im Zwielichtshain und reist zum Alptraumeinfall im Ogerhort Vul'Gol. Findet dort die schlafende Druidin der Klaue Elenora Marschenläufer und bringt sie in Sicherheit. Kehrt dann zu mir zurück.", progress = "Ihr habt Elenora gerettet?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Dämmerwald"},
[81762] = {title = "Gute Nachrichten", objective = "Sprecht mit Katharina der Reinen in der Kathedrale des Lichts in Stormwind.", description = "Seid gegrüßt, <Name>. Ich habe gute Nachrichten: Ich habe meinen Freund kontaktiert und werde bald aufbrechen, um mich mit ihm zu treffen. Außerdem ist in Kalimdor eine weitere Kugel aufgetaucht. Ich kann nicht an zwei Orten gleichzeitig sein, deswegen würde ich Euch bitten, dass Ihr Euch statt meiner um diese neue Kugel kümmert, wenn Ihr wollt. Sprecht mit Katharina, sie hat weitere Anweisungen für Euch.", progress = nil, completion = "Schön, Euch wiederzusehen, &lt;Name&gt;. Bringen wir Euch auf den neuesten Stand.", rewards = "Ihr bekommt:\n\n"},
[81764] = {title = "Der rätselhafte Händler", objective = "Reist nach Theramore und findet den rätselhaften Händler.", description = "Ich grüße Euch erneut, <Name>. Shaw und seine Spione haben uns berichtet, dass ein rätselhafter Händler gerade in Kalimdor eingetroffen ist, der eine Sammlung gefährlicher Artefakte loswerden möchte. Wir glauben jetzt, dass sich darunter eine Echokugel befindet. Der Mann hat sich im Gasthaus von Theramore in den Marschen von Dustwallow einquartiert. Begebt Euch schnell dorthin, beschafft die Kugel und sprecht mit niemandem darüber. Wir schicken Euch alleine los, damit unsere Gegner nicht auf Euch aufmerksam werden.\n\nSeid vorsichtig und geht mit dem Licht.", progress = nil, completion = "Ah, Ihr habt es geschafft! Katharina hat mich losgeschickt, damit ich Euch unterstütze. Doch wir müssen uns beeilen, unsere Beute ist entkommen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nS03 - Flag Tracking Quest - Paladin 50 Quest - Aeonas Traveling (DNT\n\nIhr bekommt:\n\n"},
[81765] = {title = "Elrick, Paladin der Silbernen Hand", objective = "Sprecht mit Elrick, um mehr zu erfahren.", description = "Der vor Euch stehende Paladin ist Euch unbekannt. Sprecht mit ihm und findet heraus, was er über den Händler und die momentane Lage weiß.", progress = nil, completion = "Dem Licht sei Dank für Euch, &lt;Klasse&gt;! Ich hatte solche Angst. Ich dachte, diese Halunken bringen uns um!", rewards = "Ihr bekommt:\n\n"},
[81766] = {title = "Das blutige Schreiben", objective = "Bringt das Schreiben zu Katharina der Reinen in der Kathedrale des Lichts in Stormwind.", description = "Ihr findet ein Schreiben bei der Leiche des \"Paladins\". Es ist blutverschmiert und schwierig zu lesen, doch Ihr könnt eine Botschaft auf dem Pergament ausmachen. Lest sie Euch durch und kehrt für weitere Anweisungen zu Katharina zurück.", progress = "Es war also eine Falle... Das ist sehr besorgniserregend.", completion = "Welch ein Segen, dass Ihr unversehrt seid, &lt;Name&gt;. Ich hoffe, dass Aeonas, wo auch immer er hingegangen sein mag, sich nicht in ähnliche Gefahr begeben hat. Er ist einfallsreich, daher muss ich glauben, dass es ihm gut geht. Wenn ich etwas von ihm höre, werde ich Euch umgehend benachrichtigen. Danke, &lt;Name&gt;.\n\nOh, und noch etwas: Er hat mir aufgetragen, Euch dies zu geben, wenn Ihr zurückkehrt. Setzt es überlegt ein und geht mit dem Licht.", rewards = "Ihr erlernt:\n\nHelm prägen - Fanatismus\n\nDer folgende Zauber wird auf euch gewirkt:\n\nFanatismus\n\nIhr bekommt außerdem:\n\n"},
[81768] = {title = "Ashenvale-Mission I: Satyrn besiegen", objective = "Besiegt 10 Traumfeuerverräter und 10 Traumfeuerhöllenrufer im Ashenvale-Alptraumeinfall in Satyrnaar und kehrt zu Feldhauptmann Hannalah zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und reist zum Alptraumeinfall in Satyrnaar. Besiegt dort Satyrn und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Ashenvale"},
[81769] = {title = "Ashenvale-Mission II: Treants besiegen", objective = "Besiegt 7 rachsüchtige Urtume im Ashenvale-Alptraumeinfall im Holzfällerlager der Warsong und kehrt zu Feldhauptmann Hannalah zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und reist zum Alptraumeinfall am Holzfällerlager der Warsong. Besiegt dort Treants und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Ashenvale"},
[81770] = {title = "Ashenvale-Mission III: Drachkin besiegen", objective = "Besiegt 3 Nachtpirscherwyrmkin und 10 Terrorwelpen im Ashenvale-Alptraumeinfall in Forest Song und kehrt zu Feldhauptmann Hannalah zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und reist zum Alptraumeinfall in Forest Song. Besiegt dort Drachkin und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Ashenvale"},
[81771] = {title = "Ashenvale-Mission IV: Drachen ausspionieren", objective = "Beschafft einen Bericht von Traumwächter Ellodar auf der Brücke zum alten Turm im Ashenvale-Alptraumeinfall von Forest Song und kehrt zu Feldhauptmann Hannalah zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und reist zum Alptraumeinfall in Forest Song. Beschafft dort einen Geheimdienstbericht von Traumwächter Ellodar und kehrt zu mir zurück.", progress = "Ihr habt den Bericht?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Ashenvale"},
[81772] = {title = "Ashenvale-Mission V: Satyrn ausspionieren", objective = "Beschafft einen Bericht von Traumwächter Mandoran im Ashenvale-Alptraumeinfall beim Ritualkreis in Satyrnaar und kehrt zu Feldhauptmann Hannalah zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und reist zum Alptraumeinfall in Satyrnaar. Beschafft dort einen Geheimdienstbericht von Traumwächter Mandoran und kehrt zu mir zurück.", progress = "Ihr habt den Bericht?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Ashenvale"},
[81773] = {title = "Ashenvale-Mission VI: Treants ausspionieren", objective = "Beschafft einen Bericht von Traumwächterin Lanaria im Ashenvale-Alptraumeinfall in der Burg Kargathia beim Holzfällerlager der Warsong und kehrt zu Feldhauptmann Hannalah zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und reist zum Alptraumeinfall im Holzfällerlager der Warsong in Satyrnaar. Beschafft dort einen Geheimdienstbericht von Traumwächterin Lanaria und kehrt zu mir zurück.", progress = "Ihr habt den Bericht?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Ashenvale"},
[81774] = {title = "Ashenvale-Mission VII: Traummotor beschaffen", objective = "Beschafft den Traummotor aus dem Ashenvale-Alptraumeinfall in der Schmiede des Holzfällerlagers der Warsong und kehrt zu Feldhauptmann Hannalah zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und reist zum Alptraumeinfall im Holzfällerlager der Warsong. Beschafft dort ein mächtiges Artefakt namens Traummotor und bringt es mir.", progress = "Ihr habt den Traummotor?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Ashenvale"},
[81775] = {title = "Ashenvale-Mission VIII: Azsharische Prophezeiung beschaffen", objective = "Beschafft die Azsharische Prophezeiung aus dem Ashenvale-Alptraumeinfall im kleinen Zelt in Satyrnaar und kehrt zu Feldhauptmann Hannalah zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und reist zum Alptraumeinfall in Satyrnaar. Beschafft dort eine verschollene Schriftrolle namens Azsharische Prophezeiung und bringt sie mir.", progress = "Ihr habt die Azsharische Prophezeiung?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Ashenvale"},
[81776] = {title = "Ashenvale-Mission IX: Traumberührtes Drachenei beschaffen", objective = "Beschafft ein traumberührtes Drachenei aus dem Ashenvale-Alptraumeinfall in der zentralen Ruine von Forest Song und kehrt zu Feldhauptmann Hannalah zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und reist zum Alptraumeinfall in Forest Song. Beschafft dort ein traumberührtes Drachenei und bringt es mir.", progress = "Ihr habt das Ei?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Ashenvale"},
[81777] = {title = "Ashenvale-Mission X: Traumwurzeln", objective = "Sammelt 10 Traumwurzeln in den Ashenvale-Alptraumeinfällen und kehrt zu Feldhauptmann Hannalah zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und beschafft Traumwurzeln aus den Alptraumeinfällen. Wir können ihre Magie zur Schadensumkehr nutzen. Ihr werdet die Hilfe eines Kräuterkundigen brauchen.", progress = "Ihr habt die Traumwurzeln?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Ashenvale"},
[81778] = {title = "Ashenvale-Mission XI: Katzengoldstaub", objective = "Sammelt 10 Stück Katzengoldstaub in den Ashenvale-Alptraumeinfällen und kehrt zu Feldhauptmann Hannalah zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und beschafft Katzengoldstaub aus den Alptraumeinfällen. Wir können seine Magie zur Schadensumkehr nutzen. Ihr werdet die Hilfe eines Minenarbeiters brauchen.", progress = "Ihr habt den Katzengoldstaub?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Ashenvale"},
[81779] = {title = "Ashenvale-Mission XII: Traumerfüllte Drachenschuppe", objective = "Sammelt 10 traumerfüllte Drachenschuppen in den Ashenvale-Alptraumeinfällen und kehrt zu Feldhauptmann Hannalah zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und beschafft traumerfüllte Drachenschuppen von Drachkin aus den Alptraumeinfällen. Wir können ihre Magie zur Schadensumkehr nutzen. Ihr werdet die Hilfe eines Kürschners brauchen.", progress = "Ihr habt die traumerfüllten Drachenschuppen?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Ashenvale"},
