[81781] = {title = "Ashenvale-Mission XIV: Zalius besiegen", objective = "Besiegt Zalius im Ashenvale-Alptraumeinfall an der Basis der Ziggurat in Satyrnaar und kehrt zu Feldhauptmann Hannalah zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Bough Shadow und reist zum Alptraumeinfall in Forest Song. Besiegt dort den Satyr Zalius und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Ihr bekommt:\n\nEinsatzanweisung: Ashenvale"},
