[81789] = {title = "Hinterlandmission IV: Drachen ausspionieren", objective = "Beschafft einen Bericht von Traumwächter Laninar im Hinterland-Alptraumeinfall am Bogen von Agol'watha und kehrt zu Feldhauptmann Korlian zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall in Agol'watha. Beschafft dort einen Geheimdienstbericht von Traumwächter Laninar und kehrt zu mir zurück.", progress = "Ihr habt den Bericht?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Hinterland"},
[81790] = {title = "Bedeutende Materialien", objective = "Findet die in Gregorys Notiz aufgeführten Materialien und bringt sie zu Gregory an der Quelle der Blutgiftfälle im Teufelswald.", description = "Jede der Echokugeln ist auf einen anderen Aspekt ihres Meisters abgestimmt, und die Methode, auf die Ihr in Ashenvale zur Zerstörung der Kugel von Althalaxx gesetzt habt, wird bei der in unserem Besitz nicht funktionieren. Ich kenne ein Ritual, mit dem wir die Kugel möglicherweise erst destabilisieren und dann zerstören können, doch dafür sind Komponenten von bestimmter magischer Bedeutung erforderlich. Wir haben zwar bereits einige davon, doch die restlichen müsst Ihr beschaffen. Nehmt dies, es wird Euch bei Eurer Suche helfen.", progress = "Die Beschaffung dieser Gegenstände war bestimmt ganz schön abenteuerlich. Gut gemacht.", completion = "Da wir die Materialien jetzt haben, muss ich das Ritual vorbereiten. Meldet Euch erst einmal bei Aeonas. Er möchte mit Euch sprechen.", rewards = "Ihr bekommt:\n\n"},
[81801] = {title = "Rückkehr in die Arena", objective = "Kehrt zu Fizbuz Mithril in Gadgetzan in Tanaris zurück.", description = "Als Orc stehe ich zu meinem Wort. Ihr habt mich gerächt, und ich werde mich bei Euch revanchieren. Geht nach Gadgetzan und sagt Fizbuz, dass sein Champion zurückkommt.\n\nIch hoffe, wir zwei sehen uns im Ring.", progress = nil, completion = "Fantastisch! Die werden alle durchdrehen, wenn sie erfahren, dass der alte Kajind wieder da ist.\n\nUnd Ihr habt tatsächlich einen Drachen für den Kerl getötet?! Dann könntet Ihr ja fast selbst in den Ring steigen.\n\nIch spüre es schon, &lt;Name&gt;. Hier findet bald ein absoluter Jahrhundertkampf statt!", rewards = nil},
[81817] = {title = "Hinterlandmission V: Schildkröte ausspionieren", objective = "Beschafft einen Bericht von Traumwächterin Sanathel im Hinterland-Alptraumeinfall hinter der Trommel in Shaol'watha und kehrt zu Feldhauptmann Korlian zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall in Shaol'watha. Beschafft dort einen Geheimdienstbericht von Traumwächterin Sanathel und kehrt zu mir zurück.", progress = "Ihr habt den Bericht?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Hinterland"},
[81820] = {title = "Hinterlandmission VI: Mondkin ausspionieren", objective = "Beschafft einen Bericht von Traumwächterin Valori im Hinterland-Alptraumeinfall am unterirdischen See von Skulk Rock und kehrt zu Feldhauptmann Korlian zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall am Skulk Rock. Beschafft dort einen Geheimdienstbericht von Traumwächterin Valori und kehrt zu mir zurück.", progress = "Ihr habt den Bericht?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Hinterland"},
[81826] = {title = "Hinterlandmission VII: Sternenberührtes Drachenei beschaffen", objective = "Beschafft ein sternenberührtes Drachenei im Hinterland-Alptraumeinfall aus der zentralen Hütte von Agol'watha und kehrt zu Feldhauptmann Korlian zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall in Agol'watha. Beschafft ein sternenberührtes Drachenei und bringt es mir.", progress = "Ihr habt das Ei?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Hinterland"},
[81830] = {title = "Hinterlandmission VIII: Elunarisches Relikt beschaffen", objective = "Beschafft ein elunarisches Relikt im Hinterland-Alptraumeinfall von dem hohen Vorsprung in Skulk Rock und kehrt zu Feldhauptmann Korlian zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall am Skulk Rock. Beschafft ein elunarisches Relikt, das die Mondkin dort versteckt haben, und bringt es mir.", progress = "Ihr habt das Relikt?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Hinterland"},
[81832] = {title = "Hinterlandmission IX: Traumperle beschaffen", objective = "Beschafft eine Traumperle im Hinterland-Alptraumeinfall aus einem Schlangenbrunnen in Shaol'watha und kehrt zu Feldhauptmann Korlian zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall in Shaol'watha. Beschafft eine Traumperle, die die Schildkröten dort versteckt haben, und bringt sie mir.", progress = "Ihr habt die Perle?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Hinterland"},
[81833] = {title = "Hinterlandmission X: Sternenlotus", objective = "Sammelt 10 Sternenlotus in den Hinterland-Alptraumeinfällen und kehrt zu Feldhauptmann Korlian zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und beschafft Sternenlotus aus den Alptraumeinfällen. Wir können seine Magie zur Schadensumkehr nutzen. Ihr werdet die Hilfe eines Kräuterkundigen brauchen.", progress = "Ihr habt den Sternenlotus?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Hinterland"},
[81834] = {title = "Hinterlandmission XI: Sternensilbererz", objective = "Sammelt 10 Stück Sternensilbererz in den Hinterland-Alptraumeinfällen und kehrt zu Feldhauptmann Korlian zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und beschafft Sternensilbererz aus den Alptraumeinfällen. Wir können seine Magie zur Schadensumkehr nutzen. Ihr werdet die Hilfe eines Minenarbeiters brauchen.", progress = "Ihr habt das Sternensilbererz?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Hinterland"},
[81835] = {title = "Hinterlandmission XII: Sternenmuscheln", objective = "Sammelt 10 Sternenmuscheln in den Hinterland-Alptraumeinfällen und kehrt zu Feldhauptmann Korlian zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und beschafft Sternenmuscheln von den Riesenschildkröten in den Alptraumeinfällen. Wir können ihre Magie zur Schadensumkehr nutzen. Ihr werdet die Hilfe eines Kürschners brauchen.", progress = "Ihr habt die Sternenmuscheln?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Hinterland"},
[81837] = {title = "Hinterlandmission XIII: Florius besiegen", objective = "Besiegt Florius im Hinterland-Alptraumeinfall beim Hof von Agol'watha und kehrt zu Feldhauptmann Korlian zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall in Agol'watha. Besiegt dort den Drachen Florius und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Hinterland"},
[81838] = {title = "Hinterlandmission XIV: Verdammniskin besiegen", objective = "Besiegt den Verdammniskin im Hinterland-Alptraumeinfall auf dem breiten Vorsprung von Skulk Rock und kehrt zu Feldhauptmann Korlian zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall am Skulk Rock. Besiegt dort den riesigen Mondkin, der als der Verdammniskin bekannt ist, und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Hinterland"},
[81839] = {title = "Hinterlandmission XV: Ghamoo-Raja besiegen", objective = "Besiegt Ghamoo-Raja im Hinterland-Alptraumeinfall beim Hof von Shaol'watha und kehrt zu Feldhauptmann Korlian zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall in Shaol'watha. Besiegt dort den \"Schildkrötenkönig\" Ghamoo-Raja und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Hinterland"},
[81850] = {title = "Hinterlandmission XVI: Elianar Schattentrinker retten", objective = "Rettet Elianar Schattentrinker aus dem Hinterland-Alptraumeinfall bei der Trollfeste in der Nähe von Agol'watha und kehrt zu Feldhauptmann Korlian zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall in Agol'watha. Findet dort den schlafenden Druiden Elianar Schattentrinker und bringt ihn in Sicherheit. Kehrt dann zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Hinterland"},
