[81852] = {title = "Hinterlandmission XVIII: Veanna Wolkenschläfer retten", objective = "Rettet Veanna Wolkenschläfer aus dem Hinterland-Alptraumeinfall in der Hängematte über Skulk Rock und kehrt zu Feldhauptmann Korlian zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Seradane und reist zum Alptraumeinfall im Skulk Rock. Findet dort die schlafende Druidin der Klaue Veanna Wolkenschläfer und bringt sie in Sicherheit. Kehrt dann zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Hinterland"},
[81855] = {title = "Feralasmission I: Kinder von Cenarius besiegen", objective = "Besiegt 10 verlorene Töchter und 10 rachsüchtige Söhne im Feralas-Alptraumeinfall bei den Zwillingskolossen und kehrt zu Feldhauptmann Arunnel zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und reist zum Alptraumeinfall bei den Zwillingskolossen. Besiegt dort die wahnsinnigen Söhne und Töchter des Cenarius und kehrt zu mir zurück.", progress = "Ihr habt die Kinder von Cenarius erledigt?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Feralas"},
[81856] = {title = "Feralasmission II: Harpyien besiegen", objective = "Besiegt 10 Wildfedern und 10 Sturmrufer der Traumquelle im Feralas-Alptraumeinfall bei den Ruinen von Rabenwind und kehrt zu Feldhauptmann Arunnel zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und reist zum Alptraumeinfall bei den Ruinen von Rabenwind. Besiegt dort die Harpyien und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Feralas"},
[81857] = {title = "Feralasmission III: Drachkin besiegen", objective = "Besiegt 10 rasende Welpen und 3 Berserkerwyrmkin im Feralas-Alptraumeinfall bei Oneiros und kehrt zu Feldhauptmann Arunnel zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und reist zum Alptraumeinfall bei Oneiros. Besiegt dort Drachkin und kehrt zu mir zurück.", progress = "Ihr habt die Drachkin erledigt?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Feralas"},
