[81861] = {title = "Feralasmission VII: Mondscheindrachenei beschaffen", objective = "Beschafft ein Mondscheindrachenei im Feralas-Alptraumeinfall aus dem Pavillon bei Oneiros und kehrt zu Feldhauptmann Arunnel zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und reist zum Alptraumeinfall bei Oneiros. Holt ein Mondscheindrachenei und bringt es zu mir.", progress = "Ihr habt das Ei?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Feralas"},
[81863] = {title = "Feralasmission VIII: Notizen des Bewahrers beschaffen", objective = "Beschafft die Notizen des wahnsinnigen Bewahrers im Feralas-Alptraumeinfall vom östlichen Hang des westlichen Kolosses der Zwillingskolosse und kehrt zu Feldhauptmann Arunnel zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und reist zum Alptraumeinfall bei den Zwillingskolossen. Beschafft dort die Notizen des wahnsinnigen Bewahrers und bringt sie mir.", progress = "Ihr habt die Notizen?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Feralas"},
[81864] = {title = "Feralasmission IX: Harpyienschrift beschaffen", objective = "Beschafft eine Harpyienschrift im Feralas-Alptraumeinfall aus dem südwestlichen Pavillon bei den Ruinen von Rabenwind und kehrt zu Feldhauptmann Arunnel zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und reist zum Alptraumeinfall bei den Ruinen von Rabenwind. Holt eine Harpyienschrift und bringt sie zu mir.", progress = "Ihr habt die Schrift?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Feralas"},
[81865] = {title = "Feralasmission X: Mondwurzel", objective = "Sammelt 10 Mondwurzeln in den Feralas-Alptraumeinfällen und kehrt zu Feldhauptmann Arunnel zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und beschafft Mondwurzeln aus den Alptraumeinfällen. Wir können ihre Magie zur Schadensumkehr nutzen. Ihr werdet die Hilfe eines Kräuterkundigen brauchen.", progress = "Ihr habt die Mondwurzeln?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Feralas"},
[81866] = {title = "Feralasmission XI: Großer Mondstein", objective = "Sammelt 10 große Mondsteine in den Feralas-Alptraumeinfällen und kehrt zu Feldhauptmann Arunnel zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und beschafft große Mondsteine aus den Alptraumeinfällen. Wir können ihre Magie zur Schadensumkehr nutzen. Ihr werdet die Hilfe eines Minenarbeiters brauchen.", progress = "Ihr habt die großen Mondsteine?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Feralas"},
[81867] = {title = "Feralasmission XII: Monddrachenschuppen", objective = "Sammelt 10 Monddrachenschuppen in den Feralas-Alptraumeinfällen und kehrt zu Feldhauptmann Arunnel zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und beschafft Monddrachenschuppen von den Drachkin aus den Alptraumeinfällen. Wir können ihre Magie zur Schadensumkehr nutzen. Ihr werdet die Hilfe eines Kürschners brauchen.", progress = "Ihr habt die Drachenschuppen?", completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Feralas"},
[81868] = {title = "Feralasmission XIII: Tyrannikus besiegen", objective = "Besiegt Tyrannikus im Feralas-Alptraumeinfall beim zerstörten Tempel in Oneiros und kehrt zu Feldhauptmann Arunnel zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und reist zum Alptraumeinfall in Oneiros. Besiegt dort den Drachen Tyrannikus und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Feralas"},
[81870] = {title = "Feralasmission XIV: Alondrius besiegen", objective = "Besiegt Alondrius im Feralas-Alptraumeinfall auf der Straße bei den Zwillingskolossen und kehrt zu Feldhauptmann Arunnel zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und reist zum Alptraumeinfall bei den Zwillingskolossen. Besiegt dort den Bewahrer des Hains Alondrius und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Feralas"},
[81871] = {title = "Feralasmission XV: Slirena besiegen", objective = "Besiegt Slirena im Feralas-Alptraumeinfall in der Nähe der Zikkurat in den Ruinen von Rabenwind und kehrt zu Feldhauptmann Arunnel zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und reist zum Alptraumeinfall bei den Ruinen von Rabenwind. Besiegt dort die \"Harpyienkönigin\" Slirena und kehrt zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Feralas"},
[81872] = {title = "Feralasmission XVI: Mellias Erdpfleger retten", objective = "Rettet Mellias Erdpfleger im Feralas-Alptraumeinfall an der Treppe beim Jademirsee in Oneiros und kehrt zu Feldhauptmann Arunnel zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und reist zum Alptraumeinfall in Oneiros. Findet dort den schlafenden Druiden der Klaue Mellias Erdpfleger und bringt ihn in Sicherheit. Kehrt dann zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Feralas"},
[81873] = {title = "Feralasmission XVII: Nerene Bachsänger retten", objective = "Rettet Nerene Bachsänger im Feralas-Alptraumeinfall vom Lagerfeuer bei den Zwillingskolossen und kehrt zu Feldhauptmann Arunnel zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und reist zum Alptraumeinfall bei den Zwillingskolossen. Findet dort die schlafende Druidin der Klaue Nerene Bachsänger und bringt sie in Sicherheit. Kehrt dann zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Feralas"},
[81874] = {title = "Feralasmission XVIII: Jamniss Baumheiler retten", objective = "Rettet Jamniss Baumheiler im Feralas-Alptraumeinfall beim nördlichen Rand der Ruinen von Rabenwind und kehrt zu Feldhauptmann Arunnel zurück.", description = "Während uns diese Dämonen hier ablenken, wird der Smaragdgrüne Traum zu einem Alptraum verderbt. Schnell, nutzt das Portal des Smaragdgrünen Traums in Traum-Geäst und reist zum Alptraumeinfall bei den Ruinen von Rabenwind. Findet dort die schlafende Druidin der Klaue Jamniss Baumheiler und bringt sie in Sicherheit. Kehrt dann zu mir zurück.", progress = nil, completion = "Gut gemacht! Eure Dienste verdienen eine großzügige Belohnung. Noch eine Mission gefällig?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMission abgeschlossen\n\nIhr bekommt:\n\nSmaragdsplitterEinsatzanweisung: Feralas"},
[81877] = {title = "Kampfnacht", objective = "Erringt den Sieg in der Arena von Gadgetzan.", description = "Alles steht für die große Neueröffnung der Arena von Gadgetzan bereit!\n\nDie Regeln sind einfach: Ihr habt drei Kämpfe und am Schluss den Champion. Zwischen den Kämpfen dürft Ihr eine kurze Pause machen, aber zu keiner Zeit die Arena verlassen. Wenn Ihr das tut, gilt es als Kapitulation.\n\nWenn Ihr bereit seid, geht der Kampf los!", progress = nil, completion = "Ihr habt da wirklich eine gute Show abgeliefert. Ich konnte mich kaum halten, kann ich Euch sagen! Die Einnahmen waren auch nicht zu schäbig.\n\nAls Champion bekommt Ihr einen Anteil davon und noch einen kleinen Bonus, weil Ihr all das möglich gemacht habt. Dem Sieger die Beute, wie man sagt.", rewards = "Ihr bekommt:\n\nRune des GladiatorsZorn des Klingenmeisters"},
[81885] = {title = "Das Ritual", objective = "Sprecht mit Gregory, um das Ritual zu beginnen.", description = "Ich wollte Euch für Eure Mühen danken, <Name>. Ohne Euch wäre ich sicherlich tot und die Diener der Legion immer noch im Besitz dieses gefährlichen Artefakts. Ich weiß, es ist schwierig, einem Agenten des Lichkönigs zu trauen, aber ich hoffe, dass wir meinen Freund wieder zum Licht bekehren können, wenn all das hier vorbei ist. Es ist deutlich zu erkennen, dass der Mann, den ich kannte, in seinem Inneren immer noch existiert. Er braucht vielleicht nur einen Anstoß.\n\nKommt, Gregory braucht unsere Hilfe beim Abschluss des Rituals. Wir sprechen danach weiter.", progress = "<Aeonas starrt leer die Klippe hinab, sichtlich schockiert von den Ereignissen.>", completion = "Mir fehlen die Worte, &lt;Name&gt;. Dass ich Gregory nun wiedergesehen habe, erfüllt mich mit einer gefährlichen Hoffnung. Seit dem Augenblick unserer erneuten Verbindung ist sein Wesen offenbart, und es gab viele Anzeichen darauf, wie er wirklich ist, doch ich wollte sie nicht sehen.\n\nNehmt bitte diese verfluchte Kugel und lasst mich in Ruhe. Ich muss über vieles nachdenken.", rewards = "Ihr erlernt:\n\nArmschienen prägen - Hammer der Rechtschaffenen\n\nDer folgende Zauber wird auf euch gewirkt:\n\nHammer der Rechtschaffenen\n\nIhr bekommt außerdem:\n\n"},
[81900] = {title = "Die brennende Bestie", objective = "Findet einen Experten für die Tiere in den Verwüsteten Landen.", description = "Das Relief vor Euch zeigt eine Bestie mit zwei Köpfen, die Feuer speiend aus dem Dunklen Portal tritt. Auf einer Tafel unter der Darstellung steht: \"Calefactus der Entfesselte\".\n\nEure Intuition sagt Euch, dass die Twilightkultisten planen könnten, die zerstörerische Macht dieser Kreatur für ihre eigenen Zwecke einzusetzen.\n\nIhr vermutet, dass der nächste Schritt Eurer Jagd Euch in die Verwüsteten Lande führt. Dort könnte es jemanden geben, der mehr über diese Höllenbestie weiß.", progress = nil, completion = "Erzählt mir mehr über diese Bestie, &lt;Volk&gt;. Wir könnten dasselbe Ziel verfolgen.", rewards = nil},
[81917] = {title = "Bindende Ketten", objective = "Bringt 5 höllische Kettenverbunde zu Blutmagierin Lynnore in den Verwüsteten Landen.", description = "Ich habe die Kreatur, die Ihr \"Calefactus\" nennt, während meinen Feldstudien oft gesehen. Sie scheint ein nahezu unverwundbarer Kernhund zu sein, der aus reinen Teufelsenergien besteht.\n\nWenn das, was Ihr sagt, aber wahr ist, und der Twilight-Hammer plant, sie zu versklaven, dann gibt es vielleicht einen Weg, die Bestie zu bezwingen.\n\nDie Schattenanbeter im Südosten sind dafür bekannt, dunkle Rituale zu vollziehen, wie auch die Versklavung von Teufelskreaturen. Vielleicht kennen die Mitglieder ihres Ordens den Schlüssel, wie Calefactus zu schwächen ist?", progress = "Habt Ihr einen Weg gefunden, Calefactus zu schwächen, <Volk>?", completion = "Interessant... Ja, damit kann ich arbeiten.", rewards = nil},
[81919] = {title = "Unter Kontrolle", objective = "Bringt das teuflische Lebensblut von Calefactus dem Entfesselten zu Blutmagierin Lynnore in den Verwüsteten Landen.", description = "Ich habe ein Werkzeug aus den Kettenverbunden hergestellt, die Ihr gefunden habt. Leute wie Ihr würden es wohl eine Art \"Lasso\" nennen.\n\nDie Energie in dieser Kette ist besonders dafür geeignet, Dämonen zu binden, aber da Calefactus möglicherweise von der anderen Seite des Dunklen Portals kommt, glaube ich, sie wird auch bei ihm funktionieren.\n\nWenn Ihr ihn bezwingt, bringt mir eine Probe seines teuflischen Lebensblutes. So ein besonderes Geschöpf muss näher studiert werden.\n\nDie aktuelle Position von Calefactus innerhalb dieser Ödnis ist nicht bekannt, aber ich bin sicher, Ihr werdet ihn aufspüren, <Klasse>.", progress = "Findet diesen Kernhund schnell, <Name>, bevor der Twilight-Hammer Euch zuvorkommt.", completion = "So eine exquisite Probe! Wer weiß, welche Geheimnisse in der Essenz einer Bestie von hinter dem Portal liegen?\n\nAls Dank möchte ich Euch mein Lasso überlassen. Ich bezweifle sowieso, dass ich so etwas je brauchen werde.", rewards = "Ihr bekommt:\n\nHöllenlassoRune des Gefräßigen"},
[81924] = {title = "Weisheit der Wächter", objective = "Bewährt Euch vor den Schutzgeistern von Azshara, des Hinterlands und von Feralas und kehrt dann zu Tyrisius in Feralas zurück.", description = "Welch Wissen der Kaldorei Ihr auch sucht, <Klasse>, Ihr werdet es in diesen Ruinen nicht finden. Nicht mehr.\n\nDoch auch wenn das Körperliche vernichtet wurde, ist das Geistige geblieben.\n\nSucht die Schutzgeister von Azshara, des Hinterlands und von Feralas auf. Ihr werdet sie an ihren Schreinen erkennen. Bewährt Euch vor ihnen und lauscht ihren Worten. Ihre Weisheit wird auf Euch übertragen werden, damit sie nicht wie die vielen anderen Dinge hier an die Zeit verloren geht.", progress = nil, completion = "Ihr habt Euch als gelehriger Schüler erwiesen, &lt;Name&gt;. Das Bewahren uralten Wissens ist oft mühselig, doch Ihr habt diese Aufgabe bewundernswert gelöst.\n\nEs gibt noch zahlreiche weitere Geheimnisse in dieser Welt, die es aufzudecken gilt. Ich hoffe, diese Werkzeuge werden Euch auf dieser Reise helfen.", rewards = "Ihr bekommt:\n\nRune des ErblühensSaat der Erneuerung"},
[81944] = {title = "Eine neu entdeckte Bestimmung", objective = "Ich... kann das nicht erklären, <Volk>, aber ich glaube, ich habe etwas, das Ihr braucht. Ich kam in dieses Land, um Wissen zu finden, und meine Suche führte mich jenen Berg dort hinten hinauf bis zu einem riesigen Fels aus Licht, der aus dem Himmel gefallen war. Als ich neben ihm sinnierte, beschenkte mich An'she mit vielen Dingen, und eins davon war eine neue Bestimmung in meinem Leben. Ein weiteres war eine Vision, wie Ihr und ich an diesem Ort diese Unterhaltung führten. Ich glaube, ich habe Euch das hier gegeben.\n\nBitte nimmt dieses Totem. Nutzt es überlegt im Dienste an An'she... und am Licht.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSymbol des Glaubens"},
[81947] = {title = "Blutige Zauberei", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[81949] = {title = "Legenden der Gezeitenweisen", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[81951] = {title = "Die Schwelle und das Arkane", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[81952] = {title = "Alltägliche Etikette", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[81953] = {title = "Steinwerkentwürfe", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[81954] = {title = "Giftige Reisen", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[81955] = {title = "Möglichkeiten des Metalls", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[81956] = {title = "Beschwörerkodex", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[81960] = {title = "Klären der Luft", objective = "Findet den besudelten Geisterfelsen und trinkt das düstere Luftsapta.", description = "Die unleserlichen Notizen sind um eine Art Sapta geschlagen. Es ist düsterer, als Ihr es in Erinnerung habt, scheint aber von derselben Magie erfüllt zu sein. Ihr fühlt Euch unwohl, während Ihr es betrachtet, als wäre es von irgendeinem Übel besudelt worden. In der Nähe muss es einen Geisterfelsen geben, obwohl Euch kein heiliger Ort in dieser Gegend bekannt ist. Vielleicht könnt Ihr Euch diese seltsame Begebenheit erklären, wenn Ihr ihn findet.", progress = nil, completion = "Ihr gebt Leben zurück. Ihr seid stark genug. Verstehe... ja... Ihr haltet die Verderbnis auf.\n\n\nSucht die Verderbnis und haltet sie auf.", rewards = "Ihr bekommt:\n\n"},
[81967] = {title = "Überirdischer Schatz", objective = "Bitteschön, Boss!Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nÜberirdischer Schatz"},
[81968] = {title = "Antwort auf den Ruf der Luft", objective = "Sammelt 3 Elementaressenzen von den Wasserelementaren an der Vergessenen Küste gegenüber der Insel Sardor in Feralas und kombiniert sie mit dem Luftfragment, um den verderbten Schrein dort aufzudecken.", description = "Ihr seid stark genug. Verstehe... ja. Ihr haltet die Verderbnis auf.\n\n<Der Elementar windet sich vor Unbehagen.>\n\nElemente in Feralas. Nutzt Essenz, um den Schrein zu finden.\n\nNehmt das Fragment. Es wird gegen die Verderbnis helfen.", progress = "Ihr habt den Schrein gefunden. Säubert ihn.", completion = "Verderbnis... muss jetzt gesäubert werden. Hilfe wird benötigt. Vielleicht... ja... Vielleicht helfen andere Elemente.", rewards = "Ihr bekommt:\n\n"},
[81974] = {title = "Mehr Schrott für Ziri", objective = "Sprecht mit Ziri \"Schraubenschlüssel\" Miniritzel in Gnomeregan.", description = "Ihr habt noch einen G-7-K.E.R.N.-Prozessor gefunden. Diese Einheit scheint in schlechterer Verfassung als die letzte zu sein. Aus ihr tropft eine sehr ätzend wirkende, tintenähnliche schwarze Flüssigkeit. Wahrscheinlich ist das Ding Schrott, doch Ziri könnte es vielleicht noch gebrauchen.", progress = "Was habt Ihr da, <Name>?", completion = "Oha! Ein G-7-K.E.R.N.-Prozessor. So einen habe ich noch nie gesehen, glaube ich. Am besten werft Ihr ihn einfach weg. Ich habe gehört, dass die Dinger sehr gefährlich sind.", rewards = "Ihr bekommt:\n\n"},
[81975] = {title = "Ein beunruhigender Austausch", objective = "Sprecht mit Ziri.", description = "Moment, bitte, was?. Habt Ihr Euch den Kopf gestoßen? Warum sollte ich Euch bitten, mir eins dieser Teile zu bringen, um diesen Schrotteimer zu reparieren? Der Wiederverwertungsmat brauchte nur ein paar Sicherungseinsätze und Mithrilstreben und ein bisschen Verzauberungsessenz. Wenn ich eine voll funktionierende G-7-Einheit in das Ding einbauen würde... nicht auszudenken, was dann passieren könnte. Auf jeden Fall nichts Gutes. Explosionen, Feuer, interdimensionale Monster. Wahrscheinlich gäbe es eine echte Horrorvorstellung.", progress = nil, completion = "Stellt Euch mal vor, ich würde einen G-7 in den Wiederverwertungsmat einbauen! Ich bin doch nicht lebensmüde!\n\n&lt;Ziri kichert vor sich hin und wendet sich wieder ihrer Arbeit zu.&gt;", rewards = "Ihr bekommt:\n\n"},
[81986] = {title = "Den Alptraum schwächen", objective = "Vernichtet die Alptraumverschmelzung und bringt der schattenhaften Gestalt alles an Beute, was Ihr findet.", description = "Da Ihr Ziris Gerät jetzt habt, müsstet Ihr über alles verfügen, was Ihr braucht, um die Alptraumverschmelzung zu erledigen. Versammelt so viele Verbündete wie möglich und begebt Euch durch das Portal von Bough Shadow in Ashenvale wieder in den Alptraum. Findet und zerstört die Alptraumverschmelzung in ihren Versteck.\n\nAch, und noch etwas... Die Bestie besitzt einen besonderen Gegenstand, der für mich von größtem Interesse ist. Bringt mir alles, was Ihr bei ihrer Leiche findet, dann werde ich Euch großzügig entlohnen.", progress = "Wie läuft die Jagd?", completion = "Fantastische Arbeit, &lt;Name&gt;. Jetzt zu Eurer Belohnung!\n\nWisst Ihr, ich wollte nur ein winziges Fragment eines Traums, der sich in diesem Mantel versteckt hatte, doch die Hülle an sich ist schon ein Schatz, und die gehört nun Euch. Ich glaube, Ihr werdet schon bald bemerken, dass sie gewisse einzigartige Eigenschaften hat, und wenn Ihr über die entsprechenden Fähigkeiten verfügt, sprecht mich noch einmal an. Dann kann ich Euch sicher sagen, wie Ihr die Hülle richtig nutzt.", rewards = "Ihr bekommt:\n\nTräger Mantel der Alpträume"},
[81987] = {title = "Goblinische Lösungen", objective = "Bringt 5 goblinische Landminen zu Maximillian \"Dem Schmierer\" auf der Schimmernden Ebene.", description = "Hey Ihr, kommt her und lasst Euch anschauen. Ja, das dachte ich mir, ich erkenne meilenweit, ob sich jemand den goblinischen Künsten verschrieben hat. Wir alle haben rußgeschwärzte Knöchel. Hört mal, ich brauche Eure Hilfe.\n\nIch wurde beauftragt, andere Goblins zu beraten, damit sie hier draußen die Nase vorn haben. Doch diese Gnome haben auch einen Experten herangezogen und überholen uns langsam. Ich möchte ein paar Ideen umsetzen, doch unterdessen bringt mir doch ein paar goblinische Landminen! Die könnt Ihr doch bauen, oder?", progress = "Meine Mama hat immer gesagt: \"Wenn du einen fairen Kampf nicht gewinnen kannst, kämpfe keinen fairen Kampf.\" Deshalb werden wir dieses Problem so lösen, wie meine Vorfahren es getan haben. Wir spicken das Gelände mit hochempfindlichen Sprengkörpern!", completion = "Man stelle sich vor, die Dinger wurden von den Verteidigern am Hyjal zur Verteidigung gegen die Brennende Legion eingesetzt. Hier scheinen sie ähnlich gut zu passen.", rewards = "Ihr bekommt:\n\n"},
[82001] = {title = "Gnomenprobleme erwünscht", objective = "Bringt das Horn eines Donnerstampferstegodons zu Maximillian \"Dem Schmierer\".", description = "Schlechte Nachrichten. Dieser gnomische Berater von denen ist mir einen Schritt voraus. Ihr Rennfahrer wird nicht mal den Boden berühren, habe ich gehört.\n\nDie versehen die Rennstrecke mit so Dingern namens \"Magneten\", über die man einfach nur gleitet, und das heißt: keine Explosion! Wenn der Kerl nicht auf die Mine tritt, müssen wir die Mine eben zu ihm bringen.\n\nIch glaube, wenn wir eine genügend starke elektrische Ladung haben, dürfte das unser Problem lösen. Geht nach Südwest-Un'Goro und beschafft mir das Horn eines Donnerstampferstegodons!", progress = "Ich werde Euch nicht detailliert erklären, wie Magnete funktionieren, weil das ehrlich gesagt niemand weiß.", completion = "Ja, das dürfte reichen! Der perfekte natürliche Leiter, den wir brauchen! Späne davon werden als perfekter Zünder für die Minen fungieren.", rewards = "Ihr bekommt:\n\n"},
[82002] = {title = "Was ist rot und riecht nach Lack?", objective = "Begebt Euch nach Hearthglen und findet eine Kiste mit scharlachrotem Farbstoff.", description = "Diese neuen Landminen funktionieren perfekt, aber wir können die Sache nicht einfach nur sabotieren. Wir brauchen ein paar Verbesserungen für unsere eigenen Fahrzeuge, damit wir nicht als unehrlich gelten.\n\nDeswegen machen wir in dieser Hinsicht etwas ganz Offensichtliches: Wir lackieren die Dinger um! Und jetzt ratet mal, welche Farbe wir nehmen? Hotrod-Rot natürlich! Die schnellste Farbe der Welt!\n\nStellt sich die Frage: Wer hat den perfekten roten Lack? Diese Trottel vom Scharlachroten Kreuzzug natürlich! Schleicht Euch doch mal nach Hearthglen und holt mir was von diesem Rot.", progress = "Es muss das Rot des Scharlachroten Kreuzzugs sein. Kein Blutrot, kein Feuerballrot, kein dämonisches Orcrot. Nein, das Rot des Scharlachroten Kreuzzugs und sonst nichts!", completion = "Dieser geschmackvolle Ton, der perfekte Farbverlauf. Und kein Hauch von Pink oder Orange! Einfach nur das beste Rot überhaupt. Oh ja, ich spüre jetzt schon, wie wir schneller werden.", rewards = "Ihr bekommt:\n\n"},
[82003] = {title = "Siegesrunde für die Goblins!", objective = "Sprecht mit Fizzbizz Kupferspule über eine Auszahlung.", description = "Ha! Ich hab's geschafft! Äh... natürlich wir zusammen!\n\nDieser Amateurberater der Gnome da drüben wirft das Handtuch! Er zahlt uns aus, damit wir die Stadt verlassen! Übernehmt Ihr die Sache doch, ja? Das habt Ihr Euch verdient.", progress = nil, completion = "Ich habe einen Vorschlag, der für uns beide von Interesse sein dürfte.", rewards = "Ihr bekommt:\n\n"},
[82004] = {title = "Schweigegeld", objective = "Nehmt die Bestechung von Fizzbizz Kupferspule an.", description = "Ich kann mir den Gesichtsverlust oder den finanziellen Verlust nicht leisten, den Ihr und Euer Goblinfreund mir verursacht. Folgender Vorschlag: Ich verrate Euch, wie gnomische Ingenieure bei ihrer Arbeit vorgehen. Als Gegenleistung macht Ihr Euch rar! Ich will Euch hier nicht mehr sehen!", progress = nil, completion = "Mehr kriegt Ihr erst einmal nicht! Kommt in einer Woche wieder, dann habe ich noch mehr für Euch.", rewards = "Ihr bekommt:\n\nGutscheintausch für Ingenieure"},
[82008] = {title = "Gnomische Lösungen", objective = "Bringt Fizzbizz Kupferspule 2 Gnomenunglücksverhinderungsgürtel.", description = "Seid gegrüßt, <geschätzter Kollege/geschätzte Kollegin>! Ich sehe schon, dass Ihr intellektuell auf höchstem Niveau seid! Doch nun zur Sache: Entlang der ganzen Rennstrecke scheinen Explosionen aufzutreten! Ein wenig verdächtig, findet Ihr nicht? Die Sicherheit unserer Fahrer steht an oberster Stelle. Bringt mir ein paar Gnomenunglücksverhinderungsgürtel! Hoffentlich löst das unser Problem auf kurze Sicht.", progress = "Habt Ihr die Gürtel? Hier startet gleich ein Rennen, und wir brauchen die Teile SOFORT!", completion = "Sehr gut! Hoffentlich kommt unser Fahrer in einem Stück über die Ziellinie. Jetzt kümmern wir uns um ein größeres Problem.", rewards = "Ihr bekommt:\n\n"},
[82009] = {title = "Goblinprobleme erwünscht", objective = "Bringt Fizzbizz Kupferspule ein Horn eines Donnerstampferstegodons.", description = "Hört Ihr die Explosionen auf der Rennstrecke? Jetzt mal im Ernst? Weil ich nämlich fast taub bin. Egal...\n\nMagnete! Wenn wir Magnete vorsichtig entlang der Strecke platzieren und welche mit der umgekehrten Polarität unten an unseren Fahrzeugen anbringen, schweben wir einfach über die Minen! Nehmt das, ihr Goblins!\n\nUnd für das letzte Teil des Rätsels brauchen wir etwas, das eine elektrische Ladung halten kann, um die komplizierte elektrische Schalttafel zu versorgen.\n\nBegebt Euch nach Südwest-Un'goro und bringt mir von dort das Horn eines Donnerstampferstegodons!", progress = "Das Horn eines Donnerstampferstegodons ist die perfekte organische Verbindung zur Versorgung der elektrischen Felder, die diese Magnete funktionieren lassen. Das hoffe ich zumindest, denn ich weiß nicht genau, was dahinter steckt.", completion = "Das wird reichen! Das Ding knistert noch vor Energie! Wenn ich noch Haare hätte, würden die mir alle zu Berge stehen!", rewards = "Ihr bekommt:\n\n"},
[82010] = {title = "Verwässern der Konkurrenz", objective = "Begebt Euch nach Hearthglen und findet eine Kiste mit scharlachrotem Farbstoff.", description = "Die Zeit der reinen Verteidigung ist vorbei! Wir können nur gewinnen, wenn wir die Konkurrenz sabotieren! Ihren Treibstoff! Feuerblüte und Rum? DAGEGEN VERLIERT DIE GNOMISCHE GENIALITÄT? GEGEN PARFÜRMIERTEN ALKOHOL?\n\nWir müssen den Treibstoff unseres Gegner irgendwie unbemerkt sabotieren. Es gibt eine Blume mit einem unglaublichen Rotton. Die Verbindungen ihrer Blütenblätter werden instabil, wenn man sie auch nur leicht erhitzt.\n\nDer Scharlachrote Kreuzzug nutzt diese Blume für seine Farben. Geht nach Hearthglen und holt mir die Dinger.", progress = "Nur der Scharlachrote Kreuzzug weiß, wo diese Blume wächst! Die Verbindungen sind stabil genug, um sie in den Farben ausreichend zu konzentrieren.", completion = "Ihr habt sie gefunden! Ja, wenn wir die Farbe einfach in den Treibstofftank unserer Gegner werfen, wird das ein schönes Spektakel! Eine Explosion? Schlimmer! Die fahren dann nur mit 76 % Prozent ihrer Kapazität! Und merken es nicht mal!", rewards = "Ihr bekommt:\n\n"},
[82011] = {title = "Siegesrunde für die Gnome!", objective = "Sprecht mit Maximillian \"Dem Schmierer\".", description = "Wir haben es geschafft! Die Goblins werfen das Handtuch. Und der von den Goblins angeheuerte Berater will sogar mit Euch persönlich sprechen! Aber gebt bitte nicht allzu sehr an, sonst macht der Euch noch einen Kopf kürzer!", progress = nil, completion = "Ich bin alt genug, um zu wissen, wann ich verloren habe. Oder zumindest, wann man sich geschlagen geben sollte.", rewards = "Ihr bekommt:\n\n"},
[82013] = {title = "Schweigegeld", objective = "Nehmt die Bestechung von Maximillian \"Dem Schmierer\" an.", description = "Ich sag Euch jetzt mal, wie das ablaufen wird. Ich kann mir Eure Präsenz hier nicht mehr leisten, also werdet Ihr sofort verschwinden. Als Gegenleistung für Euer großzügig abgepasstes Abrauschen dürft Ihr einmal in der Woche wiederkommen.\n\nDann schaut Ihr mal bei mir vorbei. Ihr werdet etwas Kleines auf dem Boden liegen sehen, das Ihr gerne aufheben könnt. Und aus Dankbarkeit dafür, dass Ihr mir diesen Dienst erweist, kann ich gar nicht anders, als Euch irgendwie zu belohnen.", progress = nil, completion = "Wir sehen uns nächste Woche.", rewards = "Ihr bekommt:\n\nGutscheintausch für Ingenieure"},
[82016] = {title = "Wirksame Tränke aus Atal'ai", objective = "Ich hab 'n ziemlich gutes Angebot für Euch! Ihr bringt mir Mojo, dass es nur von den Atal'ai gibt, und ich mach Euch 'nen Vorschlag: Ihr erhaltet Macht jenseits Eurer wildesten Vorstellungen. Aber Achtung, Mann, diese Macht nur kann in den Sümpfen genutzt werd'n, wo sie gefund'n wird. Angeblich soll'n die Atal'ai verbotene Hexerei praktizieren, und ich kenn' mich da gut aus.\n\nKlingt das gut? Hab'n wir 'nen Handel?", description = nil, progress = "Ich hab 'n ziemlich gutes Angebot für Euch! Ihr bringt mir Mojo, dass es nur von den Atal'ai gibt, und ich mach Euch 'nen Vorschlag: Ihr erhaltet Macht jenseits Eurer wildesten Vorstellungen. Aber Achtung, Mann, diese Macht nur kann in den Sümpfen genutzt werd'n, wo sie gefund'n wird. Angeblich soll'n die Atal'ai verbotene Hexerei praktizieren, und ich kenn' mich da gut aus.\n\nKlingt das gut? Hab'n wir 'nen Handel?", completion = "Ey, Ihr werdet diesen Handel nicht bereu'n!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAtal'aimojo des LebensAtal'aimojo des KriegesAtal'aimojo der verbotenen Magie"},
[82017] = {title = "Eine Verschmelzung von Alpträumen", objective = "Sucht Loganaar in Moonglade auf", description = "Die Aura des Schreckens, die Ihr erlebt habt, stammt nicht von einem Ort, sondern von einer Kreatur, einer besonders tödlichen Kreatur der Finsternis, einer verzerrten Schattenreflexion der schlimmsten Aspekte unserer Welt, die zu einem reinem Alptraum verschmolzen sind. Ich kann nicht sagen, woher ich das weiß, aber... ich habe davon geträumt. Oder besser gesagt: Es wurde mir gezeigt. Das ist schwer zu erklären. Bitte geht nach Moonglade und sprecht mit dem Druiden Loganaar. Vielleicht können wir die Kreatur noch aufhalten, bevor sie zu mächtig wird.", progress = nil, completion = "Das sind höchst beunruhigende Nachrichten. Wenn es so ist, wie Hannalah gesagt hat, wird die aktuelle Krise im Traum noch viel schlimmer werden.", rewards = "Ihr bekommt:\n\n"},
[82018] = {title = "Itharius", objective = "Sucht Itharius irgendwo in den Sümpfen des Elends auf.", description = "Ist Euch der Tempel von Atal'Hakkar ein Begriff? Er hat eine sagenumwobene Geschichte, die ich hier nicht ausführen will, doch er steht im Augenblick unter der Verwaltung einer großen Gruppe mächtiger grüner Drachen. Der Hauptwächter des Tempels ist ein großer Drache namens Eranikus, der besonders auf den Traum eingestimmt ist. Ich hoffe, dass er uns helfen kann. Geht in die Sümpfe des Elends und sucht dort den Waldläufer Itharius auf. Er mag wissen, wie wir Eranikus um Hilfe ansprechen können.", progress = "Seid gegrüßt, <Volk>.", completion = "Ihr wollt Eranikus aufsuchen? Eure Ankunft ist womöglich schlecht abgepasst, &lt;Klasse&gt;. Ich fürchte, im Tempel von Atal'Hakkar stimmt etwas nicht. Kommt, unterhalten wir uns weiter.", rewards = "Ihr bekommt:\n\n"},
[82019] = {title = "Untergehen", objective = "Findet mehr darüber hinaus, was im Tempel von Atal'Hakkar vor sich geht.", description = "Zu seiner Zeit war der sogenannte Versunkene Tempel die Heimat einer Trollsekte, die es sich zum Ziel gesetzt hatte, ihre uralte Blutgottheit Hakkar den Seelenschinder wiederzuerwecken. Ehe die Atal'ai diese furchtbaren Ambitionen erkennen konnten, stieß Yseras Zorn den Tempel in den Schlamm und ließ den Drachen Eranikus mit seiner Gruppe als Wächter zurück. In letzter Zeit habe ich viel darüber gehört, dass die Trolle dort wieder aktiv geworden sein sollen, und frage mich, was den Drachen zugestoßen sein könnte.\n\nBitte dringt in den Tempel vor und versucht, so viel wie möglich herauszufinden.", progress = "Welche Neuigkeiten bringt Ihr mir über Eranikus?", completion = "Was Ihr beschreibt, ist geradezu entsetzlich. Es ist deutlich schlimmer, als ich befürchtet hatte. Ich kann nur hoffen, dass einige der Drachen dort noch leben und sich versammeln lassen.", rewards = "Ihr bekommt:\n\n"},
[82020] = {title = "Kehrt nach Moonglade zurück", objective = "Kehrt zu Loganaar in Moonglade zurück.", description = "Kehrt zu Loganaar zurück und sagt ihm, was wir herausgefunden haben. Ich werde selbst versuchen, den Tempel auszukundschaften, um hoffentlich Kontakt zu den Drachen herzustellen oder wenigstens weitere Erkenntnisse zu gewinnen.", progress = nil, completion = "&lt;Loganaar seufzt tief.&gt;\n\nNoch mehr schlechte Nachrichten. Gut, ich danke Euch, dass Ihr Euer Leben auf Spiel gesetzt habt, um diese Erkenntnisse aus dem Tempel zu beschaffen und sie mir zu überbringen. Ich muss die anderen Druiden informieren, damit wir unsere nächsten Schritte planen können.\n\nDanke erst einmal. Vielleicht wende ich mich bald erneut an Euch.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDNT SF Phase\n\nIhr bekommt:\n\n"},
[82021] = {title = "Eine zufällige Wende der Ereignisse", objective = "Hört Euch an, was die schattenhafte Gestalt zu sagen hat.", description = "Na, guten Tag, <Name>! Ich habe hier nur gestanden und die Landschaft genossen und konnte nicht umhin, Euer Dilemma mitanzuhören. Zufälligerweise kann ich wohl genau das besorgen, was Ihr zur Bekämpfung Eures \"Alptraumproblemchens\" braucht.", progress = "Ich muss schon sagen, das hätte nicht besser funktionieren können, wenn ich es geplant hätte. Das Schicksal ist Euch wohlgesonnen.\n\n<Ihr habt den Eindruck, dass die schattenhafte Gestalt vor Euch schmunzelt.>", completion = "Ist es nicht ermutigend, jemanden wie mich zu haben, mit immer genau dem parat, was Ihr braucht? Und genau, wann Ihr es braucht?", rewards = "Ihr bekommt:\n\n"},
[82022] = {title = "Die schlechte Nachricht...", objective = "Findet den von der schattenhaften Gestalt beschriebenen Abenteuer und beschafft die leerenaufgeladenen Unterarmschienen.", description = "Die gute Nachricht ist: Es gibt eine Lösung. Die schlechte ist, dass die Beschaffung der Dinge, die erforderlich sind, um den Schrecken zu überleben, ein wenig aufwendig sein wird. Ich weiß, dass es heutzutage schwierig ist, gute Hilfe zu bekommen. Wenn dieser Abenteuer damals einfach nur das getan hätte, worum ich ihn gebeten hatte, würdet Ihr jetzt vor einer heißen Mahlzeit und einem kalten Bier in einem Gasthaus sitzen und müsstet Euch nicht mit dieser Sache herumplagen.", progress = "Wie läuft die Suche?", completion = "Ah, die haben anscheinend keinen Saft mehr. Schade, aber das lässt sich leicht beheben. Um sie aufzuladen, müsst Ihr eine dichte Konzentration an Nagazauberern finden und sie massenhaft abschlachten. Manchmal haben sie etwas dabei, das sich \"Leerenkern\" nennt, also filzt die Leichen, bringt mir so ein Ding und... Ha! War nur ein Witz! Wenn Ihr Euch jetzt sehen könntet...\n\nGebt mir einen Augenblick, dann sollte ich etwas Energie reinleiten können... und bitte! Jetzt seid Ihr bereit, einen Alptraum zu töten.", rewards = "Ihr bekommt:\n\nLeerenaufgeladene Unterarmschienen"},
[82023] = {title = "Die verlorenen Unterarmschienen", objective = "Findet den Bau \"Bestie\", die der verletzte Gnom beschriebenen hat, und beschafft die leerenaufgeladenen Unterarmschienen.", description = "Wisst Ihr, ich bin ein einigermaßen anerkannter Ritter und habe mir vor Kurzem die Befreiung des Landes von einem besonders schrecklichen Bösen auferlegt, das sich auf einer östlich von uns gelegenen Insel niedergelassen hatte. Als ich die widerliche Kreatur fand, folgte darauf ein wahrhaft epischer Kampf, der stundenlang andauerte, bis ich die Bestie endlich in die Flucht schlagen konnte, wonach sie zweifelsohne ihren Wunden erlag. Ich habe es gerade noch zurück geschafft und brach dann vor Erschöpfung zusammen. Während des Kampfes muss ich meine Unterarmschienen verloren haben.", progress = "<Der junge Murloc schaut Euch an und gibt ein süßes Gurgeln von sich.>\n\nEuch fällt ein Häuflein Erde neben dem Murloc auf. Vielleicht solltet Ihr darin nach den Unterarmschienen schauen?", completion = "Ihr habt einen kleinen Bau gefunden, der einem entzückenden und offenbar sehr freundlichen kleinen Murloc gehört. Das kann doch unmöglich die von dem Gnom beschriebene Bestie sein?\n\n&lt;Der winzige Murloc gibt ein leises Gurgeln von sich und erbricht ein Paar schleimbedeckte Unterarmschienen vor Eure Füße.&gt;", rewards = "Ihr bekommt:\n\nEntladene leerenaufgeladene Unterarmschienen"},
[82043] = {title = "Die wilden Götter", objective = "Sammelt ein Wildgeflüstergebräu aus Jintha'Alor im Hinterland und verwendet es auf dem Gipfel der Hügel von Razorfen, um mit dem Geist von Agamaggan zu sprechen.", description = "Irgendwas stimmt mit dem Loa vom Hyjal nich'. Die mächtigsten Naturgeister wach'n schon seit Tausenden von Jahr'n über diesen Berg, doch sie verschwinden langsam einer nach 'm andren.\n\nAgamaggan, der größte der uralten Loa, ist schon vor langer Zeit gestorb'n. Aber die Amanitrolle haben Wege, mit den Toten zu sprech'n! Findet das Voodoo, das sie nutz'n, und bringt es dann zu den Razorfen. Sprecht mit Agamaggan und fragt ihn, was mit seinesgleichen passiert ist.", progress = nil, completion = "Selbst jenseits des Schleiers des Todes spüre ich diesen Schatten, der sich auf den Hyjal und meine Sippe legt.\n\nNehmt dies, Sterblicher. Ihr werdet es brauchen für das, was bald kommt.", rewards = "Ihr bekommt:\n\nAgamaggans Gebrüll"},
[82044] = {title = "Die wilden Götter", objective = "Bringt wilde Opfergaben zur Abgesandten des Schattenzahns im Teufelswald. Setzt Agamaggans Gebrüll bei einem wahnbesessenen Uralten ein und besiegt ihn, um Euch wilde Opfergaben zu verdienen.", description = "Eine Finsternis hat im Smaragdgrünen Traum Fuß gefasst und die uralten Geister des Hyjal mit Verwirrung und Furcht belegt.\n\nFindet diese wahnbesessenen Geister, <Sterblicher/Sterbliche>, und lockt sie mit meinem Gebrüll in den Kampf.\n\nWenn Ihr ihre verderbten Gestalten vernichtet, werden Ihre Geister geläutert und sie werden neu geboren.", progress = "Ich spür 'ne Veränderung am Berg, <Name>. Was bringt Ihr mir?", completion = "Ihr habt den Loa 'nen groß'n Dienst erweis'n, &lt;Name&gt;. Ich werd die Opfergab'n einsetz'n, um sie zurück zum Hyjal zu führ'n.\n\nBringt mir mehr Opfergab'n, dann werd ich Euch vielleicht 'nen Teil von unsrem Klanschatz zukommen lass'n.", rewards = "Ihr bekommt:\n\nWeisheit des Hyjal"},
[82055] = {title = "Dünenkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Dünenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Dünenkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Wochen abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Set aus Dünenkarten zusammenzubekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Dünenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Sandsturm"},
[82056] = {title = "Alptraumkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Alptraumkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Alptraumkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Wochen abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Qual"},
[82057] = {title = "Seuchenkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Seuchenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Seuchenkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Wochen abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Set aus Seuchenkarten zusammenzubekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Seuchenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Verfall"},
[82058] = {title = "Wildniskartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Wildniskartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Wildniskartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Wochen abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Set aus Wildniskarten zusammenzubekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Wildniskartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Wildes Wachstum"},
[82062] = {title = "Mehr denn je", objective = "<Euch wird ein kleines Paket überreicht, auf dem ein ordentlich gefaltetes Hemd liegt.>", description = "Wir mussten sicherstellen, dass wir Euch vertrauen können. Solche Freunde sind rar gesät.\n\nEin Übel wächst heran, eine dritte Fraktion innerhalb von Azeroth. Sowohl die Horde als auch die Allianz arbeiten ahnungslos auf ihr eigenes Ende hin. Wir haben lediglich die Ressourcen, um ihr Vorrücken zu verlangsamen und Informationsverbünde zu bilden.\n\nNehmt dies, bringt Eure Lebensgeister in Schwung und blickt auf bessere Tage zurück. Bald kommt die Zeit, in der wir unsere verstärkten Reihen zur Abschreckung präsentieren müssen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nPremos haltungswahrende UniformStudentenfutterRegenbogengenerator"},
[82068] = {title = "Alptraumeinfälle abwehren", objective = "Schließt noch heute einen Alptraumeinfall im Hinterland oder in Feralas ab und meldet Euch bei Feldhauptmann Korlian oder Feldhauptmann Arunnel.", description = "Schließt noch heute einen Alptraumeinfall im Hinterland oder in Feralas ab, um eine zusätzliche Belohnung zu erhalten.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"},
[82071] = {title = "Reinigendes Feuer", objective = "Findet den besudelten Geisterfelsen und trinkt das düstere Feuersapta.", description = "In die verkohlten Notizen ist irgendetwas eingewickelt. Eine Art Sapta. Ihr könnt Euch nicht daran erinnern, dass es so ausgesehen oder gerochen hat, doch ansonsten wirkt es authentisch. Irgendetwas stimmt aber nicht. Könnte es von einer anderen Magie besudelt worden sein. In der Nähe muss sich ein Geisterfelsen befinden, obwohl Ihr Euch an keinen erinnern könnt. Wenn Ihr ihn findet, könnt Ihr vielleicht ergründen, was hier so seltsam ist.", progress = nil, completion = "Ihr seid stark. Ihr läutert das Feuer. Ihr haltet die Verderbnis auf.\n\n\nIhr findet die Verderbnis und haltet sie auf.", rewards = "Ihr bekommt:\n\n"},
[82072] = {title = "Läuternde Erde", objective = "Findet den besudelten Geisterfelsen und trinkt das düstere Erdsapta.", description = "Eine vertraut aussehende Flasche Sapta wurde in verschmierte Zettel eingewickelt und liegt vor Euch. Das Zeug wirkt seltsam düster, doch seine Magie kommt Euch größtenteils bekannt vor. Der Hauch eines fremdartigen Zaubers verdirbt die Mixtur. Euer Instinkt sagt Euch, dass es in der Nähe einen Geisterfelsen geben muss, doch Ihr könnt Euch an keinen erinnern. Wenn Ihr ihn findet, könnt Ihr diesem Mysterium vielleicht auf den Grund gehen.", progress = nil, completion = "Das Leben gedeiht wieder. Stärke ist erforderlich.\n\n\nVerderbnis ist woanders. Findet sie und haltet sie auf.", rewards = "Ihr bekommt:\n\n"},
[82073] = {title = "Säuberndes Wasser", objective = "Findet den besudelten Geisterfelsen und trinkt das düstere Wassersapta.", description = "Ausgeblichene und durchweichte Zettel wurden um eine Flasche mit trübem Inhalt gewickelt. Ihr könnt Euch nicht daran erinnern, dass sie jemals so ausgesehen haben könnte, aber doch recht ähnlich. Der Geruch ist allerdings komisch, als wäre er besudelt. In der Nähe muss sich ein Geisterfelsen befinden, der aber wahrscheinlich schon lange aufgegeben wurde. Wenn Ihr ihn findet, habt Ihr vielleicht das fehlende Teil zu diesem seltsamen Puzzle.", progress = nil, completion = "Ihr habt geläutert. Ihr habt wiederhergestellt. Ihr habt einen starken Geist. Ihr helft.\n\n\nDie Verderbnis lebt noch. Haltet sie auf.", rewards = "Ihr bekommt:\n\n"},
[82074] = {title = "Antwort auf den Ruf des Feuers", objective = "Sammelt 3 Elementaressenzen von den Wasserelementaren an der Vergessenen Küste gegenüber der Insel Sardor in Feralas und kombiniert sie mit dem Feuerfragment, um den verderbten Schrein dort aufzudecken.", description = "Ihr seid stark. Stark genug.\n\n<Der Elementar funkelt und flackert.>\n\nElemente von Feralas. Essenz. Findet den Schrein.\n\nNehmt ein Fragment. Das wird helfen.", progress = "Das wird den Schrein läutern.", completion = "Hilfe ist nötig. Andere Elemente sind stark. Bringt sie her.", rewards = "Ihr bekommt:\n\n"},
[82075] = {title = "Antwort auf den Ruf der Erde", objective = "Sammelt 3 Elementaressenzen von den Wasserelementaren an der Vergessenen Küste gegenüber der Insel Sardor in Feralas und kombiniert sie mit dem Erdfragment, um den verderbten Schrein dort aufzudecken.", description = "Das Leben gedeiht nun. Wir brauchen mehr. Die Verderbnis muss aufgehalten werden.\n\n<Als sich der Elementar bewegt, schaben die Felsen aneinander.>\n\nFeralas. Elementare. Essenz und Schrein.\n\nFindet den Schrein. Nutzt das Fragment und findet ihn. Helft dabei, das Leben gedeihen zu lassen.", progress = "Das Leben gedeiht hier nun.", completion = "Das Leben gedeiht hier nun. Wir brauchen mehr. Andere Elemente. Hilfe.", rewards = "Ihr bekommt:\n\n"},
[82076] = {title = "Antwort auf den Ruf des Wassers", objective = "Sammelt 3 Elementaressenzen von den Wasserelementaren an der Vergessenen Küste gegenüber der Insel Sardor in Feralas und kombiniert sie mit dem Wasserfragment, um den verderbten Schrein dort aufzudecken.", description = "Starker Geist. Ihr helft, die Verderbnis aufzuhalten.\n\n<Wasser wirbelt brausend um den Elementar.>\n\nGeschwister. Elementare von Feralas helfen. Die Essenz wird den Schrein finden.\n\nAuch das Fragment wird helfen. Läutert die Verderbnis.", progress = "Werde Schrein säubern.", completion = "Säubere Schrein jetzt. Nicht stark genug. Brauche andere. Andere Elemente.", rewards = "Ihr bekommt:\n\n"},
[82081] = {title = "Ein zerbrochenes Ritual", objective = "Bringt das Schulterblatt des gefallenen Avatars zu Molthor auf der Insel Yojamba.", description = "Dieses makellose Schulterblatt ist eindeutig identifizierbar: Hakkar ist in die körperliche Welt beschworen und bezwungen worden. Die Trolle auf der Insel Yoyomba werden mehr darüber erfahren wollen, was im Inneren des Versunkenen Tempels geschehen ist.", progress = "<Name>, welche Neuigkeiten bringt Ihr aus dem Tempel von Atal'Hakkar?", completion = "Das kann nich' sein... Die Gerüchte über den Tempel von Atal'Hakkar sind wahr?\n\nEuer Sieg im Inneren des Versunkenen Tempels wird lange im Gedächtnis der Zandalari verbleib'n. Dieser Knochen... 'ne seltsame Entscheidung, uns das zu überbring'n... Aber ohne Zweifel wurde einer gebraucht, um Hakkar in die körperliche Welt zu beschwör'n. Er wird hier in guten Händen sein, &lt;Name&gt;. Dank Eurer Anstrengungen müss'n wir uns nich' länger Sorgen mach'n, ob Hakkar zurückkehrt... Richtig?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDrachenklauenband des VorbotenDrachenklauenband des BlutprophetenDrachenklauenband des BerserkersDrachenklauenband des MolochsDrachenklauenband des Pirschers"},
[82083] = {title = "Ein zerbrochenes Ritual", objective = "Bringt das Schulterblatt des gefallenen Avatars zu Molthor auf der Insel Yojamba.", description = "Dieses makellose Schulterblatt ist eindeutig identifizierbar: Hakkar ist in die körperliche Welt beschworen und bezwungen worden. Die Trolle auf der Insel Yoyomba werden mehr darüber erfahren wollen, was im Inneren des Versunkenen Tempels geschehen ist.", progress = "<Name>, welche Neuigkeiten bringt Ihr aus dem Tempel von Atal'Hakkar?", completion = "Das kann nich' sein... Die Gerüchte über den Tempel von Atal'Hakkar sind wahr?\n\nEuer Sieg im Inneren des Versunkenen Tempels wird lange im Gedächtnis der Zandalari verbleib'n. Dieser Knochen... 'ne seltsame Entscheidung, uns das zu überbring'n... Aber ohne Zweifel wurde einer gebraucht, um Hakkar in die körperliche Welt zu beschwör'n. Er wird hier in guten Händen sein, &lt;Name&gt;. Dank Eurer Anstrengungen müss'n wir uns nich' länger Sorgen mach'n, ob Hakkar zurückkehrt... Richtig?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDrachenklauenband des VorbotenDrachenklauenband des BlutprophetenDrachenklauenband des BerserkersDrachenklauenband des MolochsDrachenklauenband des Pirschers"},
[82084] = {title = "Eine Lektion in Sachen Schriftkundigkeit", objective = "Euer Fortschritt in den arkanen Künsten ist wirklich vorbildlich, <Name>. Ich denke, Ihr seid nun so weit, ein eigenes Zauberbuch zu verfassen.\n\nLasst mich überlegen... Ein Federkiel von den Eulenbestien des Hinterlands und eine Tinte aus Silithidenarz... Ja, das dürfte funktionieren. Und als Schreibpapier, das feinste Papyrus der Farraki.", description = nil, progress = "Euer Fortschritt in den arkanen Künsten ist wirklich vorbildlich, <Name>. Ich denke, Ihr seid nun so weit, ein eigenes Zauberbuch zu verfassen.\n\nLasst mich überlegen... Ein Federkiel von den Eulenbestien des Hinterlands und eine Tinte aus Silithidenarz... Ja, das dürfte funktionieren. Und als Schreibpapier, das feinste Papyrus der Farraki.", completion = "Euer Zauberbuch ist fertig, &lt;Name&gt;. Möget Ihr seine Seiten mit arkanen Geheimnissen füllen, die es mit jenen in den uralten Bibliotheken von Elun'dris und Zuldazar aufnehmen können.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n[DNT] Temporal Anomaly\n\nIhr bekommt:\n\nPersönliches Zauberbuch"},
[82086] = {title = "Eine Lektion in Sachen Schriftkundigkeit", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nPersönliches Zauberbuch"},
[82089] = {title = "Meister der Transmutation", objective = "Bringt Crimeon Lablade drei Arkanitbarren.", description = "Transmutation ist eine einzigartige Fähigkeit, die alle talentierten Alchemisten beherrschen, aber nur jene, die sich der Kunst voll und ganz ergeben, werden zu wahren Meistern darin. Ihr mögt das Zeug dazu haben, aber Ihr müsst mir beweisen, dass es Euch wirklich ernst damit ist, den Weg zu größerem Wissen und Begreifen zu beschreiten.\n\nBringt mir drei Arkanitbarren als Zeichen Eurer Hingabe an diese Kunst.", progress = "Drei läppische Arkanitbarren sind doch sicherlich nichts im Austausch gegen dieses Wissen?", completion = "Sehr gut, ich erkenne Eure Hingabe.\n\n&lt;Crimeon stopft sich die Barren hastig in seinen Rucksack&gt;\n\nJa? Oh, Transmutation. Natürlich. Rührt Euch nicht, hierfür werde ich meine ganze Konzentration benötigen.\n\n&lt;Crimeon wedelt dramatisch mit seinen Händen und ein winziger Funke schießt aus seinem rechten Zeigefinger&gt;\n\nNun, äh, ja. Das sollte reichen. Vermutlich.", rewards = nil},
[82090] = {title = "Ein Mix aus Spaß und Profit", objective = "Bringt Mischmeister Blix 10 Unsichtbarkeitstränke, 10 Elixiere des Dämonentötens und 5 Elixiere der Weisen.", description = "Jeder Alchemist, der etwas taugt, wird Euch erzählen, dass es in der Kunst immer darum geht, die Gewinnspanne zu maximieren. Es geht immer darum, die Materialien günstig zu erwerben, in großen Mengen zu produzieren und dann zum bestmöglichen Preis zu verkaufen. Was, wenn ich Euch erzählen würde, dass es einen Weg gibt, Materialien sehr, sehr weit zu strecken? Nun, als selbsternannter \"Meister der Mixologie\" habe ich genau das, was Ihr benötigt, um Euch auf ein ganz neues Niveau in Sachen Elixiere und Tränke zu bringen. Bringt mir 10 Unsichtbarkeitstränke, 10 Elixiere des Dämonentötens und 5 Elixiere der Weisen, dann zeige ich Euch, wie der Hase läuft.", progress = "Hört mal, ich habe jede Menge potenzielle Schüler, die nur darauf warten, etwas von mir zu lernen. Habt Ihr, worum ich Euch gebeten habe? Wenn nicht, dann zieht Leine.", completion = "Oh, wow, Ihr habt die Sachen wirklich dabei? Nun gut. Dann wollen wir mal Wasser aufsetzen und Euch zu einem richtigen Mixologen machen.", rewards = nil},
[82093] = {title = "Dschungeldurian", objective = "Diese kräftig und penetrant riechende Frucht wird Euch helf'n, bei bester Laune zu bleib'n, während Ihr die Sümpfe des Elends durchquert und den Tempel von Atal'Hakkar erkundet. Lasst Euch von dem Geruch nicht in die Irre führ'n, mein Volk schätzt diese Frucht sehr!\n\nWenn Ihr mir was Schönes von Euren Abenteuern mitbringt, werde ich Euch dafür belohn'. Ein paar unsrer besten Durianfrüchte sollt Ihr für Eure Anstrengungen bekomm'! Hand drauf?", description = nil, progress = "Diese kräftig und penetrant riechende Frucht wird Euch helf'n, bei bester Laune zu bleib'n, während Ihr die Sümpfe des Elends durchquert und den Tempel von Atal'Hakkar erkundet. Lasst Euch von dem Geruch nicht in die Irre führ'n, mein Volk schätzt diese Frucht sehr!\n\nWenn Ihr mir was Schönes von Euren Abenteuern mitbringt, werde ich Euch dafür belohn'. Ein paar unsrer besten Durianfrüchte sollt Ihr für Eure Anstrengungen bekomm'! Hand drauf?", completion = "Taz'dingo! Genießt die leck're, süße Durian, aber denkt immer dran... Keine Erstattungen!", rewards = "Ihr bekommt:\n\nDschungeldurian"},
[82094] = {title = "Siegel des verlorenen Tempels", objective = "Dem allerstärkst'n Abenteurer biete ich die allerbest'n Angebote. Ich hab da was, was Eure Schultergegenstände verbessert: die Macht der Atal'ai selbst! <Name>, wenn Ihr Mojo von den Allerstärkst'n der Atal'ai im Tempel gefund'n habt, dann geb ich Euch was dafür.\n\nEs muss dabei keine vorschnelle Entscheidung getroff'n werd'n, meine Angebote sind einfach die best'n...", description = nil, progress = "Dem allerstärkst'n Abenteurer biete ich die allerbest'n Angebote. Ich hab da was, was Eure Schultergegenstände verbessert: die Macht der Atal'ai selbst! <Name>, wenn Ihr Mojo von den Allerstärkst'n der Atal'ai im Tempel gefund'n habt, dann geb ich Euch was dafür.\n\nEs muss dabei keine vorschnelle Entscheidung getroff'n werd'n, meine Angebote sind einfach die best'n...", completion = "Zieht ruhig weiter. Wenn Ihr noch was braucht, dann wisst Ihr, wo Ihr mich findet, &lt;Name&gt;!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAtal'aisiegel der MachtAtal'aisiegel des MojoAtal'aisiegel der inneren Ruhe"},
[82095] = {title = "Der Gott Hakkar", objective = "Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris.", description = "Jetzt wird es Zeit, die Essenz des Avatars von Hakkar einzufangen.\n\nBringt das Ei von Hakkar in das Sanktum des Gefallenen Gottes im Versunkenen Tempel in Azeroth. Ruft die Macht des Eies an, um den toten Gott aufzuwecken.\n\nSeid gewarnt: Sogar im Entstehen wird er schon über unfassbare Macht verfügen und er wird sich Euch mit der ganzen Kraft seiner Wut widersetzen.\n\nBesiegt ihn und gebt seine Essenz in das Ei von Hakkar.", progress = "Habt Ihr den Avatar von Hakkar besiegt, <Name>? Hat seine Essenz das Ei, das ich Euch gab, schon ermächtigt?", completion = "Die Essenz von Hakkar wurde eingefangen! Gerade jetzt beginnt sich das Leben im Ei zu regen! Sind die Geschichten von Hakkar doch wahr?\n\nDas darf nicht wahr sein! Ich fürchte mich vor dem, was Hakkar tun könnte, wenn er erneut geboren wird. Ich werde dieses Ei sicher aufbewahren und darauf achten, dass es niemals in böse Hände gerät.\n\nEure Dienste für mich haben nun ein Ende, &lt;Name&gt;. Ihr habt eine Legende berührt, und Eure Taten werden eines Tages das Antlitz unserer Erde verändern.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAvenwachthelmLangdolch der LebenskraftEdelsteinbesetzter Reif\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[82096] = {title = "In die Tiefen", objective = "Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends.", description = "Im Tempel fand ich einen kreisrunden Raum mit sechs Balkonen, und am Rand eines jeden stand eine Schlangenstatue. Neugierig drückte ich gegen eine von ihnen, um zu sehen, was passieren würde. Es war eine Falle! Durch die Explosion wurde ich fast getötet. Als ich da auf einem Vorsprung lag, sah ich nach unten und bemerkte, dass eine weitere Statue unten im Raum stand. Es war eine Art Altar... Hakkar, ich glaube, so wurde er genannt.\n\nIch denke, dass dieser Altar das Geheimnis ist... Ihr müsst dieses Zeichen zum Altar in den Versunkenen Tempel bringen.", progress = "Während Ihr die Statue untersucht, bemerkt Ihr eine Vertiefung an ihrer Seite, die genau die Größe des Zeichens hat, das Marvon Euch mitgab...", completion = "Ihr legt den Steinreif in die Öffnung und hört, wie er an seinem Platz einrastet.\n\nNun, da der Stein an seinem Platz ist, könnt Ihr weitermachen... aber was solltet Ihr als Nächstes tun?\n\nVielleicht solltet Ihr diesen Altar etwas näher untersuchen...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[82097] = {title = "Das Geheimnis des Kreises", objective = "Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich im Kreis der Statuen verbirgt.", description = "Meine Erinnerungen sind verworren, aber ich werde Euch alles sagen, was ich weiß. Der Kreis der Statuen im Versunkenen Tempel mag ja gefährlich sein, ich glaube dennoch, dass sie das Geheimnis eines noch größeren Schatzes in sich bergen.\n\nVom Hauptaltar aus konnte ich eine Reihe von Lichtern aktivieren. Ich glaube, dass Ihr, wenn Ihr die Bedeutung dieser Lichter herausfindet, auch die weiteren Geheimnisse lüften könnt, die sich in diesem Raum verstecken.\n\nAber ich warne Euch, <Name>. In dem Tempel ist etwas unermesslich Böses. Es ist anzunehmen, dass alles Wertvolle äußerst streng bewacht wird.", progress = nil, completion = "Das Auge des Götzen glitzert an der Spitze des Trümmerhaufens. Seine Transparenz enthüllt etwas Glänzendes, das sich dahinter versteckt. Ihr bewegt einige größere Brocken Geröll zur Seite und befreit, was sich darunter befindet.\n\nDer Schatz der Atal'ai ist nun Euer.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nUrne der Hakkari"},
[82098] = {title = "Im Tempel von Atal'Hakkar", objective = "Sammelt 10 Schrifttafeln der Atal'ai für Brohann Fassbauch in Stormwind.", description = "Der Legende zufolge ist der Tempel von Atal'Hakkar ein heiliger Schrein, der dem alten Gott Hakkar dem Seelenschinder geweiht ist. Der Tempel, der von einem tückischen Trollstamm namens Atal'ai unterhalten wird, soll angeblich uneinnehmbar sein.\n\nDa der Tempel jetzt im Tränenteich versunken ist, dürfte es noch schwieriger sein, Artefakte zu bergen. Aber genau das müsst Ihr tun, <Name>.\n\nHelft mir dabei, indem Ihr die intakten Schrifttafeln der Atal'ai sammelt. Bringt sie mir und ich schicke der Forschergilde <einen Helden/eine Heldin> zurück. Wir werden uns den Ruhm teilen.", progress = "Da sich langsam das Dunkel über meine Laufbahn senkt, wende ich mich an Euch, <Name>, damit Ihr mir bei meinem letzten Auftrag für die Forscherliga helft. Wenn meine alten Knochen genug Kraft aufbringen würden, die Sümpfe des Elends und den Versunkenen Tempel zu meistern, würde ich direkt an Eurer Seite kämpfen.\n\nMein Stolz macht es mir schwer, Euch um Eure Hilfe beim Sammeln der Schrifttafeln der Atal'ai zu bitten. Doch das hohe Alter schließt andere Möglichkeiten aus.\n\nBitte helft mir, <Name>. Ich möchte erst aus der Forscherliga ausscheiden, wenn ich ihre letzte Bitte erfüllt habe.", completion = "Die Schrifttafeln der Atal'ai! Ich danke Euch, &lt;Name&gt;!\n\nWenn ich sie der Forscherliga übergeben habe, werden unser beider Namen in die Geschichte eingehen. Ihr habt einem alten Zwerg geholfen, die letzte Verpflichtung seines Lebens zu erfüllen. Dafür bin ich Euch ewig dankbar.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nWächtertalisman"},
[82099] = {title = "Der Dunst des Bösen", objective = "Sammelt 5 Proben Dunst der Atal'ai und bringt sie Muigin im Krater von Un'Goro.", description = "Um ehrlich zu sein, <Name>, solche Pflanzen habe ich auf meinen Reisen noch nie gesehen. Vielleicht sollte ich mal einen Ausflug zu diesem Krater machen...\n\nEgal, ich weiß vermutlich, was Muigin benötigt: Dunst der Atal'ai. Das ist ein abscheuliches Zeug, sehr schwer zu sammeln, aber es ist genau das, was er benötigt, um diese kleinen Monster unter Kontrolle zu bringen.\n\nIhr müsst zum Tempel von Atal'Hakkar in den Sümpfen des Elends gehen. Den Dunst der Atal'ai bekommt Ihr von Tiefenlauerern, Düsterwürmern oder Schlammen, die man dort findet. Viel Glück, <Name>!", progress = "Larion spricht immer noch nicht mit mir! Wie kann man nur so nachtragend sein!", completion = "Ich muss gestehen, dass ich das Zeug nur sehr ungern anfasse, &lt;Name&gt;! Aber wenn Gregan sagt, dass es funktioniert, dann will ich es mal ausprobieren!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[82100] = {title = "Der Tempel von Atal'Hakkar", objective = "Sammelt 20 Fetische von Hakkar und bringt sie zu Fel'Zerul in Stonard.", description = "Also sprach er von Jammal'ans Prophezeiung?\n\nDer spirituelle Anführer der Atal'ai glaubt, wenn Hakkar aus dem Nether nach Azeroth zurückkehrt, wird der Gott dem Stamm der Atal'ai Unsterblichkeit gewähren.\n\nTörichte Arglist, um den Jüngsten Tag schneller herbeizuführen, wenn Ihr mich fragt.\n\nDoch Ihr sagt, der Verbannte sprach von verzauberten Fetischen? Das erfüllt mich mit großer Sorge. Wenn sie wahrhaftig der Schlüssel zu dem Ritual der Atal'ai sind, das dieses Durcheinander verursacht hat, müssen wir die Mächte verstehen, die ihnen innewohnen.\n\nBegebt Euch in den Tempel und werdet dieser Fetische habhaft!", progress = "Wenn die Fetische der Atal'ai die Macht besitzen, Hakkar zu beschwören und Jammal'ans Prophezeiung zu erfüllen, müssen wir sie haben. Die Horde muss solche Mächte verstehen!", completion = "Tapferer &lt;Klasse&gt;, Ihr habt Euch heldenhaft für die Horde eingesetzt.\n\nWir müssen uns unverzüglich um diese vielen Fetische von Hakkar kümmern!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nWächtertalisman"},
[82101] = {title = "Treibstoff für die Unkrautvernichtung", objective = "Bringt den ungeladenen Unkrautvernichter und 5 Proben Dunst der Atal'ai zu Larion in Marschalls Zuflucht.", description = "Ihr habt Glück, <Name>! Während Marvon fort war, habe ich an einigen meiner eigenen Experimente gearbeitet. Eines davon ist ein Unkrautvernichter auf kurze Reichweite. Nur noch ein paar kleine Änderungen, dann ist er perfekt, um damit diese Blutblütenplagen zu beseitigen.\n\nIhr könnt gern einen meiner Prototypen haben, aber Ihr benötigt noch etwas Treibstoff dafür. Den für den Vernichter benötigten Dunst der Atal'ai findet Ihr im Tempel von Atal'Hakkar. Ihr bekommt ihn von Tiefenlauerern, Düsterwürmern oder Schlammen.", progress = "Das kann einen echt fertigmachen, <Name>. Diese Biester lassen mich einfach nicht in Ruhe!", completion = "Marvon war also nicht da, eh? Na ja, zeigt mir trotzdem, was Ihr da habt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\n"},
[82102] = {title = "Die Essenz des Eranikus", objective = "Legt die Essenz des Eranikus in den Essenzborn, der sich in seinem Unterschlupf im Versunkenen Tempel befindet.", description = "Als Ihr den Edelstein berührt, ertönt eine tiefe Stimme in Eurem Geist.\n\n\"Sterbliches Wesen, hört diese Bitte. Ich bin Eranikus vom grünen Drachenschwarm, der Hüter dieses verfluchten Tempels. Meine Aufgabe, sicherzustellen, dass die Trolle nie wieder ihre Monstrosität von einem Gott in diese Welt bringen, ist nun fehlgeschlagen. Während ich diesen Edelstein mit einem Teil meiner magischen Essenz erfülle, fühle ich, wie mein Halt im Traum sich zum Chaos bewegt. Ich bitte Euch... legt diesen Edelstein in den Essenzborn in meinem Unterschlupf und lasst unsere Magie dort den Makel von meiner Psyche nehmen, sodass ich endlich ruhen kann.\"", progress = "Während Ihr Euch dem Essenzborn nähert, von dem Eranikus Euch berichtet hat, ertönt seine Stimme erneut in Eurem Kopf.\n\n\"Ja, sterbliches Wesen, dieser Essenzborn wird den reinen Teil meiner Psyche, der sich noch in diesem Edelstein befindet, erlösen. Legt den Edelstein in den Born hinein und lasst die Magie des grünen Drachenschwarms Verderbnis und Besudelung von meinem Wesen entfernen. Erst dann werde ich wahre Erlösung finden und erst dann wird der Drachenschwarm in der Lage sein, seine Führung über die Atal'ai wieder zu bestätigen.\"", completion = "Ihr legt den Edelstein in den Essenzborn hinein.\n\n\"Ich danke Euch, sterbliches Wesen, Ihr habt... nein... das, das darf nicht sein! Nein! Die Verderbnis dieses verfluchten Gottes hat sogar die Reinheit eines Essenzborns des grünen Drachenschwarms beschmutzt! Bitte, nein, ich fühle, wie meine Essenz von mir gerissen wird! DIESER SCHMERZ! Ich fühle, wie mich die Umklammerung eines ewigen Alptraums umschlingt...\"\n\n\"Sterbliches Wesen, ich flehe Euch an! Findet jemanden vom grünen Drachenschwarm, um dem ein Ende zu bereiten... Helft mir... Ich bin in der Dunkelheit gebunden... auf ewig in Schmerzen... bitte nicht... foltern...\"", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nGebundene Essenz des Eranikus"},
[82104] = {title = "Jammal'an der Prophet", objective = "Der Verbannte der Atal'ai im Hinterland möchte den Jammal'ans Kopf.", description = "Meine Begleiter von den Witherbark mögen keine Fremden in ihrer Nähe ihrer Heimat.\n\nIch? Ich habe keine Heimat mehr. Mein Volk, der große Stamm der Atal'ai aus den Sümpfen des Elends, hat mich verbannt.\n\nJammal'an, unser spiritueller Anführer, hatte eine, wie er es ausdrückt, Prophezeiung. Er glaubt, die Beschwörung des Gottes Hakkar bringt den Atal'ai Unsterblichkeit.\n\nIch jedoch drängte auf Vorsicht. Wenn die Prophezeiung nun nichts weiter als Manipulation war?\n\nIch will Rache für meine Verbannung. Bringt mir Jammal'ans Kopf. Vielleicht ist mein Volk dann frei.", progress = "Sobald Jammal'an nicht mehr ist, habe ich die Chance, zu meinem Volk zurückzukehren.\n\nMit Jammal'an als ihrem spirituellen Anführer ist der Untergang der Atal'ai gewiss.", completion = "Jammal'ans blindes Vertrauen in falsche Visionen führte mein Volk in die ewige Verdammnis.\n\nIch danke Euch, &lt;Klasse&gt;, dass Ihr meine Verbannung gerächt habt. Ich trauere um mein Volk. Jetzt habe ich keine Heimat mehr, in die ich zurückkehren könnte.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRegenschreitergamaschenHelm des Banns\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[82106] = {title = "Erschaffung des Steins der Macht", objective = "Bringt die Voodoofedern zu Ashlam Valorfist.", description = "Jetzt müssen wir die gereinigten Geißelsteine kombinieren und eine Waffe herstellen, die die Reihen der Untoten erschüttert. Das ist keine einfache Aufgabe, <Name>. Nur die Trolle des Versunkenen Tempels besitzen diese Art seltener Magie, die fähig ist, das Böse von etwas gegen sich selbst zu richten.\n\nIm Tempel sind die Trolle bekannt als Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Verspürt keine Reue für ihre verderbten Seelen... Sie sind nicht frei von Bösem.", progress = "Habt Ihr die elenden Trolle getötet?", completion = "Das ist ausgezeichnet, &lt;Name&gt;. Ich könnte sagen, dass ich überrascht bin, allerdings habe nicht daran gezweifelt, dass Ihr uns nicht enttäuschen werdet.\n\nEs ist mir eine Ehre, Euch einen der heiligen Steine der Macht zu überreichen. Verwendet ihn überlegt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nHeiliger Stein der MachtGeweihte KugelSiegelring der RitterlichkeitLichtgeschmiedete Klinge"},
[82107] = {title = "Voodoofedern", objective = "Bringt die Voodoofedern der Trolle im Versunkenen Tempel zum gefallenen Helden der Horde.", description = "Eure Ehre hat mir zu ein wenig Frieden verholfen. Es ist mehr als gerecht, dass ich Euch etwas im Gegenzug dafür gebe.\n\nMeine Waffen und meine Rüstung waren zu meinen Lebzeiten prächtig, aber jetzt habe ich keine Verwendung mehr dafür. In Euren Händen würden sie einem besseren Zweck dienen.\n\nReist zum Versunkenen Tempel und tötet die Trollwächter Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Sie tragen magische Federn, die meinen physikalischen Körper lange genug neue Gestalt verleihen können, damit ich Euch belohnen kann.", progress = "Seid Ihr schon zurück? Zeit ist für mich nicht mehr, was sie einst war. Vielleicht habt Ihr ja wirklich schon eine lange Reise hinter Euch...", completion = "Endlich kann ich die Kälte von Stahl wieder spüren, auch wenn es nur für einen Moment ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nVisier des ZornsDiamantenfläschchenKlingenstahlschultern"},
[82108] = {title = "Der grüne Drache", objective = "Bringt Morphaz' Zahn zu Ogtinc in Azshara. Ogtinc wohnt oberhalb der Klippen nordöstlich der Ruinen von Eldarath.", description = "Ich entsende Euch nun auf eine gefährliche Jagd. Es gilt, den grünen Drachen Morphaz zu bezwingen und mir seinen Zahn zu bringen. Morphaz haust tief im Tempel von Atal'Hakkar, dessen Eingang in den Sümpfen des Elends liegt.\n\nWenn Ihr ihn besiegen möchtet, solltet Ihr nicht alleine gehen. Dieser Drache ist der Feind von vielen. Sucht nach anderen, die ihn ebenfalls zu vernichten suchen.\n\nDer Zahn des Drachen steht für die Macht, die ein Jäger in der Gesellschaft anderer findet. Bringt ihn zu mir, dann werdet Ihr viel gelernt haben.", progress = "Ich sehe Weisheit in Euren Augen, <Name>. Ist Eure Jagd beendet?", completion = "Ihr habt die alten Wege erlernt, &lt;Name&gt;, dafür belohne ich Euch mit einem Geschenk, das aus meinen Zeiten als &lt;Klasse&gt; stammt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nJagdspeerAuge eines TeufelssauriersZahn eines Teufelssauriers"},
[82110] = {title = "Der azurblaue Schlüssel", objective = "Bringt den azurblauen Schlüssel zu Lord Jorach Ravenholdt.", description = "Es wird einige Zeit dauern, die Fragmente zu entschlüsseln und den Zauber zu bannen. Sobald ich mein Werk vollendet habe, werde ich die Tasche Lord Ravenholdt persönlich übergeben.\n\nAllerdings gibt es da noch das Problem mit dem Schlüssel, von dem gesagt wird, er befände sich im Besitz von Morphaz, einem grünen Drachen. Er haust tief im Tempel von Atal'Hakkar, dessen Eingang in den Sümpfen des Elends liegt.\n\nVersammelt Eure Getreuen und begebt Euch zu seinem Hort. Lord Ravenholdt erwartet Euch bei Eurer Rückkehr mit dem Schlüssel.", progress = "Die Tasche ist von Erzmagier Xylem bereits angekommen. Habt Ihr den Schlüssel finden können?", completion = "Der Schlüssel! Und ich dachte schon, er sei für immer verloren. Bitte nehmt eines der verzauberten Gewänder aus meinem Lager. Die sind nur für Schurken von außergewöhnlichem Talent und enormer Loyalität bestimmt. Es sollte schon offenkundig sein, dass Ihr, &lt;Name&gt;, nicht zu unterschätzen seid!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nEbenholzmaskeLeisetreterNachtsaugertuch"},
[82111] = {title = "Morphaz' Blut", objective = "Tötet Morphaz im Versunkenen Tempel von Atal'Hakkar und bringt sein Blut zu Greta Mosshoof im Teufelswald. Der Eingang zum Versunkenen Tempel liegt in den Sümpfen des Elends.", description = "Jetzt zum letzten Teil, dem zweiten Heilmittel.\n\nDer grüne Drache Morphaz ist dafür bekannt, gegen alle Formen von Krankheit und Gift immun zu sein. Viele Druiden erlitten den Tod, um uns diese Nachricht zu übermitteln. Es gibt keinen Zweifel, dass sein Blut die für uns nötige Wirkung hat.\n\nEin Kurier des Zirkels des Cenarius wird die von Euch bereits beschafften Zutaten übernehmen, während Ihr nach der letzten sucht. Versammelt Eure Verbündeten und sucht den Unterschlupf des Drachen im Versunkenen Tempel von Atal'Hakkar auf. Bringt sein Blut anschließend zu Greta Mosshoof im Teufelswald.", progress = "Habt Ihr das Blut von Morphaz?", completion = "Ihr habt Morphaz besiegt und uns sein Blut gebracht... Ich kann diese gute Nachricht kaum fassen!\n\nWir werden sofort mit der Verarbeitung der Zutaten beginnen und die Tiere und Bäume des Teufelswalds endlich heilen. Es wird sicherlich ein ganzes Leben lang dauern, das hier Geschehene rückgängig zu machen, aber dank Eurer Hilfe verfügen wir nun über die entsprechenden Mittel.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMal der Wildnis\n\nIhr bekommt:\n\nGesegnete GebetsperlenStab des LeidensReif der Hoffnung"},
[82112] = {title = "Eine bessere Zutat", objective = "Besorgt eine Fäulnisranke von dem Wächter auf dem Grund des Versunkenen Tempels und kehrt zu Torwa Pathfinder zurück.", description = "Genau wie ich befürchtet hatte. Das Gift ist einfach zu schwach für eine solch mächtige Kreatur.\n\nUm ein Gift von ausreichender Potenz zu entwickeln, werdet Ihr Euch auf den Grund des Tempels von Atal'Hakkar begeben müssen. Lüftet dort das Geheimnis des Altars und nehmt dem Wächter eine Fäulnisranke ab. Der Tempel ist gefährlich und es wird vermutlich erforderlich sein, Gefährten mitzubringen.\n\nKehrt zu mir zurück, wenn Ihr fertig seid.", progress = "Habt Ihr die Fäulnisranke?", completion = "Endlich werde ich ein wirksames Gift herstellen können. Ich will es Euch nicht erneut auferlegen, die Kreatur damit zu vergiften, da ich schon zu tief in Eurer Schuld stehe.\n\nSeid Euch meines Danks und meines Respekts gewiss. Mögen Eure Reisen immer gut verlaufen, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nErgrauter PelzUmarmung des WaldesMondschattenstock"},
[82113] = {title = "Die Macht des Voodoos", objective = "Bringt die Voodoofedern zu Bath'rah dem Windbehüter.", description = "Das Geistertotem alleine ist nicht stark genug. Um erfolgreich zu sein, benötigen wir noch etwas Voodoomagie.\n\nDie Trolle im Versunkenen Tempel besitzen Federn, die von mächtiger Voodoomagie erfüllt sind. Begebt Euch dorthin und besiegt Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Mit Ihren Federn haben wir genug Macht, um ein starkes Geistertotem zu formen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nAzuritfäusteEntzückter WassergeistWildstab"},
[82114] = {title = "Morphaz vernichten", objective = "Beschafft den arkanen Splitter von Morphaz und kehrt mit ihm zu Erzmagier Xylem zurück.", description = "Es gibt einen grünen Drachen, tief im Versunkenen Tempel von Atal'Hakkar, der sich Morphaz nennt.\n\nVor Jahren überwältigte er mich aus einem kühnen Hinterhalt heraus und verschlang meinen Lehrling mit Haut und Haaren. Der Verlust eines Lehrlings ist mir zwar nicht unbekannt, allerdings trug dieser einen arkanen Splitter von unübertroffener Größe und Qualität.\n\nBitte versammelt Eure mächtigsten Verbündeten und dringt in die Tiefen des Tempels vor. Vernichtet Morphaz und entreißt ihm den arkanen Splitter aus seinem Magen.", progress = "Habt Ihr meinen alten Feind besiegt?", completion = "Unglaublich. Der Splitter ist sogar noch mächtiger geworden. Er scheint über all die Jahre die Energie des Drachen absorbiert zu haben.\n\nEs gibt nichts mehr, worum ich Euch nun bitten könnte. Meine Fähigkeit, das Arkane zu wirken, ist mit der Rückkehr dieses Splitters komplett wiederhergestellt. Meine erste Kreation sei die Eure, &lt;Name&gt;, und Ihr müsst lediglich wählen...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nGletscherstachelArkankristallanhängerFeuerrubin"},
[82115] = {title = "Federn von Trollen", objective = "Bringt 6 Voodoofedern von den Trollen aus dem Versunkenen Tempel.", description = "Mein Begleiter ist fast fertig. Jetzt brauche ich nur noch etwas als Füllmaterial.\n\nNur die Voodoofedern von den Trollen aus dem Versunkenen Tempel sind dafür geeignet. Sie heißen Schlitzer, Mijan, Zolo, Hukku, Zul'lor und Loro. Tötet sie. Tötet sie alle.\n\nDies ist keine gewöhnliche Aufgabe, <Name>, also werde ich Eure Bemühungen belohnen, indem ich Euch etwas von Niby gebe. Er wird es sowieso nicht mehr brauchen.", progress = "Habt Ihr die Federn? Mein Begleiter braucht eine Füllung!", completion = "Wunderbar, jetzt ist mein Begleiter komplett!\n\n&lt;Impsy stopft die Puppe schnell aus und umarmt sie auf dämonische Weise.&gt;\n\nOh, was für einen merkwürdigen Nebeneffekt diese Voodoofedern doch haben...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nSeelenernterAbysssplitterRoben der Knechtschaft"},
[82135] = {title = "Der Preis der Hoffnung", objective = "Bringt die Echokugel der Mannoroc zu Katharina der Reinen in Stormwind.", description = "<Aeonas sagt nichts, sondern reicht Euch nur die Kugel und wendet sich ab.>", progress = "Willkommen zurück, <Name>. Was habt Ihr da...\n\nAu weh.", completion = "Diese Geschichte bereitet mir wahrlich Sorgen. Der &lt;Klasse&gt; in mir kann sich unmöglich damit abfinden, dass er bereitwillig Umgang mit einem Mitglied der Geißel hatte... doch der menschliche Teil in mir versteht, wie stark die Bande der Freundschaft sein können.\n\nIch danke Euch, dass Ihr die Kugel hergebracht habt. Ich werde dafür sorgen, dass sie in dem tiefsten uns bekannten Verlies aufbewahrt wird.\n\nAch, und eins noch: Ich habe das hier reparieren lassen und wollte es eigentlich Aeonas bei seiner Rückkehr überreichen. Sicher würde er wollen, dass Ihr es an seiner Stelle führt.", rewards = "Ihr bekommt:\n\nFlüstern"},
[82208] = {title = "Großer Freund der Bibliothek", objective = "Dank Eurer Spenden entwickelt sich die Bibliothek prächtig.\n\nBitte, nehmt das.", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nHelm prägen - Tieffrieren\n\nDer folgende Zauber wird auf euch gewirkt:\n\n[DNT] Deep Freeze"},
[82209] = {title = "Wasserbeutelkopfgeld", objective = "Ihr seid ja schon wieder da, <Name>! Wenn Ihr noch fünf Wasserbeutel eines Wüstenläufers für mich habt, dann habe ich hier ein kleines Paket, das nur auf Euch wartet!", description = nil, progress = "Ihr seid ja schon wieder da, <Name>! Wenn Ihr noch fünf Wasserbeutel eines Wüstenläufers für mich habt, dann habe ich hier ein kleines Paket, das nur auf Euch wartet!", completion = "Hervorragend - je mehr Wasserbeutel wir wiederbeschaffen können, desto weiter sind wir von einer Katastrophe entfernt! Bringt mir mehr und ich werde Euch für jeweils fünf Wasserbeutel belohnen, die Ihr mir bringt.", rewards = "Ihr bekommt:\n\nGadgetzan Water Co.-Care-Paket"},
[82210] = {title = "Kopfgeld für Trollhalsketten", objective = "Ihr habt das zwar bereits erledigt, aber wir nehmen weiterhin alle Troll-Stammeshalsketten an, die Ihr findet und eintauschen wollt. Indem Ihr sie bei mir eintauscht, verbessert Ihr weiter Eure Stellung unter den Wildhämmern. Wenn Ihr für uns kämpft, dann kämpfen wir auch für Euch!\n\nIch benötige 5 Troll-Stammeshalsketten, damit ich es gelten lassen kann, <Name>.", description = nil, progress = "Ihr habt das zwar bereits erledigt, aber wir nehmen weiterhin alle Troll-Stammeshalsketten an, die Ihr findet und eintauschen wollt. Indem Ihr sie bei mir eintauscht, verbessert Ihr weiter Eure Stellung unter den Wildhämmern. Wenn Ihr für uns kämpft, dann kämpfen wir auch für Euch!\n\nIch benötige 5 Troll-Stammeshalsketten, damit ich es gelten lassen kann, <Name>.", completion = "Ein weiterer Satz Halsketten bedeutet, dass es weniger Trolle im Hinterland gibt, derentwegen man sich Sorgen machen muss! Ihr habt es wieder geschafft, &lt;Name&gt;. Leistet weiter so gute Arbeit!", rewards = nil},
[82271] = {title = "Mehr leuchtendes Skorpidblut", objective = "Die Idee mit dem Skorpidblut hat funktioniert, <Name>! Es ist unglaublich wie viel man mit einem bisschen Leuchten hier und etwas Glitzern da erreichen kann. In null Komma nichts wird so aus einem Haufen Schrott eine preisgekrönte Attraktion. Meine Kunden lieben das Zeug und wenn etwas wichtig ist im Leben, dann ist es Liebe... findet Ihr nicht auch!\n\nIhr wart mir eine große Hilfe, <Name>! Mein Bedarf ist zwar vorerst gedeckt, doch wenn Ihr mehr leuchtendes Skorpidblut findet, bringt es mir und ich tausche es gegen einige Lose ein.", description = nil, progress = "Die Idee mit dem Skorpidblut hat funktioniert, <Name>! Es ist unglaublich wie viel man mit einem bisschen Leuchten hier und etwas Glitzern da erreichen kann. In null Komma nichts wird so aus einem Haufen Schrott eine preisgekrönte Attraktion. Meine Kunden lieben das Zeug und wenn etwas wichtig ist im Leben, dann ist es Liebe... findet Ihr nicht auch!\n\nIhr wart mir eine große Hilfe, <Name>! Mein Bedarf ist zwar vorerst gedeckt, doch wenn Ihr mehr leuchtendes Skorpidblut findet, bringt es mir und ich tausche es gegen einige Lose ein.", completion = "Danke nochmals, &lt;Name&gt;. Hier sind Eure Lose!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[82272] = {title = "Leuchtendes Skorpidblut", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[82273] = {title = "Mehr Fledermausaugen", objective = "<Name>, die Attraktion, an der ich arbeite, wird das schaurigste Ereignis seit dem Sturm auf Gnomeregan werden! Dies verdanke ich hauptsächlich Euch und all dem Tand, den Ihr mir gebracht habt. Vielen, vielen Dank!\n\nIch brauche nicht viel mehr, aber... solltet Ihr mir noch mehr böse Fledermausaugen von Fledermäusen der Östlichen Pestländer bringen... dann könnte ich noch weitere Lose des Dunkelmond-Jahrmarkts für Euch haben.", description = nil, progress = "<Name>, die Attraktion, an der ich arbeite, wird das schaurigste Ereignis seit dem Sturm auf Gnomeregan werden! Dies verdanke ich hauptsächlich Euch und all dem Tand, den Ihr mir gebracht habt. Vielen, vielen Dank!\n\nIch brauche nicht viel mehr, aber... solltet Ihr mir noch mehr böse Fledermausaugen von Fledermäusen der Östlichen Pestländer bringen... dann könnte ich noch weitere Lose des Dunkelmond-Jahrmarkts für Euch haben.", completion = "Danke nochmals, &lt;Name&gt;. Hier sind Eure Lose!", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
