[82307] = {title = "Eine komplette Lieferung", objective = "Habt Ihr etwas für mich?", description = nil, progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, &lt;Name&gt;. Diese Vorräte sind an vorderster Front unentbehrlich.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRuf - Händlerfraktion\n\nIhr bekommt:\n\n"},
