[82316] = {title = "Sieben Augen suche ich...", objective = "Sieben verborgene Augen suche ich... Bringt sie zu mir, dann werdet auch Ihr sehen.", description = nil, progress = "Sieben verborgene Augen suche ich... Bringt sie zu mir, dann werdet auch Ihr sehen.", completion = "Ihr werdet gesehen...", rewards = "Ihr erlernt:\n\nHelm prägen - Auge der Leere\n\nDer folgende Zauber wird auf euch gewirkt:\n\nDNT Teach EoV"},
[82323] = {title = "Farbenprächtige Federbüsche", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"},
[82656] = {title = "Wildlederweste", objective = "Bringt Jangdor Swiftstrider im Camp Mojache 2 Schildkrötenschuppenbrustplatten, 2 Schildkrötenschuppenhandschuhe und eine Wildranke.", description = "Wildlederwesten sind die Grundlage jeglicher Wildlederrüstungssets. Die Struktur der Weste und das Wildrankengeflecht darin erzeugen ein Produkt, das sowohl maximalen Schutz für den Torso bietet als auch der mächtigen Magie erlaubt, sich in dem Gewand auszubreiten.\n\nFür dieses Muster werde ich 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke benötigen. Dies ist keine einfache Lektion, aber eine, für die Ihr sicherlich das nötige Geschick habt.", progress = "Habt Ihr die beiden Schildkrötenschuppenbrustplatten und -handschuhe? Und vergesst bitte die Wildranke nicht!\n\nSelbst mit den einfachsten Mustern können wir lernen, dass sich die Grundsätze der Formen leicht auf komplexere Gewänder übertragen lassen. Auf verschiedene Weise bereitet Euch die Form der Schildkrötenschuppenbrustplatten auf den Detailreichtum vor, der für die Herstellung von Wildlederwesten benötigt wird.\n\nWährend Ihr in den Lektionen voranschreitet, werden die Fertigkeiten, die ich Euch beibringe, zu einer wahren Kunst werden.", completion = "Das hier sind ein paar sehr schöne Stücke, &lt;Name&gt;. Die Handwerkskunst und Sorgfalt, die in die Herstellung dieser Dinge geflossen sind, zeigen, dass Ihr beschlossen habt, Euch völlig diesen Aufgaben zu widmen.\n\nIhr habt meine Forderungen erfüllt und daher erhaltet Ihr Eure Belohnung. Das Wissen um die Herstellung von Wildlederwesten ist jetzt Euer.", rewards = "Ihr bekommt:\n\nMuster: Wildlederweste"},
[82657] = {title = "Wildlederweste", objective = "Bringt Pratt McGrubben in der Festung Feathermoon 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke.", description = "Wildlederwesten sind die Grundlage aller Wildlederrüstungssets. Das Gerüst der Weste verbindet sich mit der Wildranke, um ein Produkt zu erzeugen, das sowohl maximalen Schutz für den Torso bietet als auch der mächtigen Magie erlaubt, sich in dem Gewand auszubreiten.\n\nFür dieses Muster werde ich 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke benötigen. Das ist ein großer Auftrag, aber sicher keiner, bei dessen Erfüllung Ihr Schwierigkeiten haben werdet.", progress = "Habt Ihr die beiden Schildkrötenschuppenbrustplatten und -handschuhe, die ich bestellt habe? Und vergesst bitte die Wildranke nicht!\n\nSchon mit den einfachsten Mustern können wir lernen, dass sich die Grundsätze der Formen leicht auf komplexere Gewänder übertragen lassen. Auf verschiedene Weise bereitet Euch die Form der Schildkrötenschuppenbrustplatten auf den Detailreichtum vor, der für die Herstellung von Wildlederwesten benötigt wird.\n\nUnd die Handschuhe... tja, die sind nur für meinen eigenen Bedarf. Vergesst nicht, Ihr arbeitet für mich!", completion = "Das hier sind ein paar sehr schöne Stücke, &lt;Name&gt;. Durch die Handwerkskunst und Sorgfalt, die in ihre Fertigung gesteckt wurden, werden sie einige Silbermünzen mehr einbringen als ein durchschnittlich gefertigtes Stück.\n\nIhr habt meinen Auftrag erledigt und daher erhaltet Ihr Eure Belohnung. Das Wissen um die Herstellung von Wildlederwesten ist jetzt Euer.", rewards = "Ihr bekommt:\n\nMuster: Wildlederweste"},
[82662] = {title = "Der Weg des Waffenschmieds...", objective = "Um <Waffenschmied/Waffenschmiedin> zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Ironus bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben.", description = "Als <Waffenschmied/Waffenschmiedin> werdet Ihr feststellen, dass sehr häufig Helden und Abenteurer der Ausrüstung wegen zu Euch kommen werden. Wenn die viele Arbeit manchmal auch unerträglich sein kann, macht der Wohlstand aber doch die Rückenschmerzen und die Aschenlunge wett.\n\nOh ja, <Name>, Waffenschmiede sind die mit dem ganzen Gold!\n\nWenn Ihr unseren Rängen beitreten wollt, müsst Ihr mir zeigen, dass Ihr mir ein Silberstück oder zwei einbringen könnt. Ich meine, zeigt mir, dass Ihr es draufhabt, wenn Menschen Waffen überragender Qualität benötigen. An die Arbeit!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWaffenschmiedekunstfachmann\n\nIhr bekommt:\n\n"},
[82665] = {title = "Der Weg des Waffenschmieds...", objective = "Um <Waffenschmied/Waffenschmiedin> zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Borgosh bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben.", description = "Eines Tages werde ich einen legendären Hammer erschaffen. Einen Hammer, der eines Kriegshäuptlings würdig ist!\n\nDas ist mein Lebenswerk, <Name>. Meine Leidenschaft. Ich erkenne, dass Ihr das Potenzial habt, zu uns zu gehören, einer von uns zu sein, <ein Waffenschmied/eine Waffenschmiedin>. Ich bin derjenige, der Euch helfen kann, dieses Potenzial nutzbar zu machen.\n\nAlles, was Ihr dafür erledigen müsst, ist eine einfache Aufgabe. Einfach für jemanden von Eurer außergewöhnlichen Fertigkeit.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWaffenschmiedekunstfachmann\n\nIhr bekommt:\n\n"},
[82850] = {title = "Fischöl", objective = "Fischöl hält die Räder des Krieges am Laufen! Wenn Ihr welches für mich habt, werde ich Euch dafür reichlich entlohnen.", description = nil, progress = "Fischöl hält die Räder des Krieges am Laufen! Wenn Ihr welches für mich habt, werde ich Euch dafür reichlich entlohnen.", completion = "Vielen Dank, &lt;Name&gt;. Ich weiß das gut einzusetzen.", rewards = "Ihr bekommt:\n\n"},
[82851] = {title = "Verordnung der Dunkeleisenzwerge", objective = "Wusstet Ihr, dass es bei den Dunkeleisenzwergen Tradition ist, dass der Senat Gesetzesvorschläge zu explosiven Geschossen verfasst? Und wenn die Gesetze dem Imperator nicht gefallen, nun, dann... BUMM!\n\nWas schaut Ihr mich so an? Vertraut Ihr Eurem alten Kumpel Grizzby etwa nicht?", description = nil, progress = "Wusstet Ihr, dass es bei den Dunkeleisenzwergen Tradition ist, dass der Senat Gesetzesvorschläge zu explosiven Geschossen verfasst? Und wenn die Gesetze dem Imperator nicht gefallen, nun, dann... BUMM!\n\nWas schaut Ihr mich so an? Vertraut Ihr Eurem alten Kumpel Grizzby etwa nicht?", completion = "Vielen Dank, &lt;Name&gt;. Ich weiß das gut einzusetzen.", rewards = "Ihr bekommt:\n\n"},
[82853] = {title = "Schredderturbolader", objective = "Schade, dass die Schifffahrtswege zurück nach Kezan mittlerweile so unzuverlässig sind. Zuhause bekommt man für ein paar Kupferstücke Turbolader im Überfluss. In den Maschinenläden fallen sie schon aus den Regalen. Die wissen nicht, wohin mit dem Zeug.\n\nWie auch immer, wenn Ihr ein paar Turbolader habt, mit denen Ihr nichts anzufangen wisst, nehme ich sie Euch nur zu gerne ab!", description = nil, progress = "Schade, dass die Schifffahrtswege zurück nach Kezan mittlerweile so unzuverlässig sind. Zuhause bekommt man für ein paar Kupferstücke Turbolader im Überfluss. In den Maschinenläden fallen sie schon aus den Regalen. Die wissen nicht, wohin mit dem Zeug.\n\nWie auch immer, wenn Ihr ein paar Turbolader habt, mit denen Ihr nichts anzufangen wisst, nehme ich sie Euch nur zu gerne ab!", completion = "Vielen Dank, &lt;Name&gt;. Ich weiß das gut einzusetzen.", rewards = "Ihr bekommt:\n\n"},
[83188] = {title = "Überirdischer Schatz", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nÜberirdischer Schatz"},
[83189] = {title = "Überirdischer Schatz", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nÜberirdischer Schatz"},
[83190] = {title = "Überirdischer Schatz", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nÜberirdischer Schatz"},
[83191] = {title = "Überirdischer Schatz", objective = "Bitteschön, Boss!Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nÜberirdischer Schatz"},
[83192] = {title = "Überirdischer Schatz", objective = "Bitteschön, Boss!Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nÜberirdischer Schatz"},
[83808] = {title = "In der Klemme", objective = "Findet das Schwert des Knappen Cuthbert auf dem Feld im Süden und bringt es ihm.", description = "Ihr habt mich fast zu Tode erschreckt! Ich habe Euch kommen gehört und war überzeugt, dass die Toten mich endlich aufgespürt hätten! Doch Ihr seid eine wahre Augenweide. Bitte, ich muss von diesem Ort verschwinden und meinen Herrn, Sir Dalton, finden. Würdet Ihr meine Waffe für mich holen? Sie wurde mir draußen auf dem Schlachtfeld entrissen und ich war gezwungen, in diese Scheune zu fliehen.", progress = "Habt Ihr das Schwert gefunden?", completion = "Danke, &lt;Klasse&gt;. Ich kann Euch nicht genug für Eure Hilfe danken.\n\nIch brauche einen Moment, um mich zu sammeln. Ich habe einen üblen Hieb auf den Kopf eingesteckt und bin nicht sicher, wie gut ich schon kämpfen kann. Oh, das Licht helfe mir, ich hoffe, Sir Dalton ist in Sicherheit.", rewards = "Ihr bekommt:\n\n"},
[83822] = {title = "Der gefallene Ritter", objective = "Führt den Knappen Cuthbert zur Leiche des gefallenen Ritters, den ihr zuvor gefunden habt, und helft ihm, sie zu verbrennen.\n\nWenn Ihr Cuthbert aus den Augen verliert, wird er sich zu seinem Versteck in der Scheune bei Dalsons Tränenfeld zurückziehen und dort auf Euch warten.", description = "Ihr sagtet, Ihr habt seine... Leiche gefunden? Nein... mein Herr darf nicht tot sein. Unsere Aufgabe ist noch nicht erfüllt.\n\nIch... danke Euch, <Klasse>. Ich habe mit dem Schock zu kämpfen, doch ich bin froh, dass Ihr ihn gefunden habt.\n\nWie es scheint, liegt seine Queste nun an mir. Doch zuerst muss ich zu seiner Leiche zurückkehren und sie verbrennen, damit er nicht Teil desselben Unheils wird, dass er vernichten wollte. Wenn ich noch eine Bitte an Euch richten dürfte, würdet Ihr mich an den Ort führen, wo Sir Dalton gefallen ist?", progress = nil, completion = "Ich stehe wohl erneut in Eurer Schuld, &lt;Klasse&gt;. Sogar im Angesicht seiner Leiche ist es schwer zu glauben, dass es wahr ist. Ich stand in Sir Daltons Diensten, seit ich ein kleiner Junge war, aber ich habe das Gefühl, noch so viel lernen zu müssen, wenn ich beenden will, was Sir Dalton begonnen hat.\n\nIch kann Euch nicht länger aufhalten. Ihr habt mir bereits übermäßig viel Ehre mit Eurer zuvorkommenden Hilfe erwiesen. Bitte, lasst mich Euch nicht länger zur Last fallen. Ich werde hier rausfinden, irgendwie.", rewards = "Ihr erlernt:\n\nUmhang prägen - Rechtschaffene Vergeltung\n\nDer folgende Zauber wird auf euch gewirkt:\n\nRechtschaffene Vergeltung\n\nIhr bekommt außerdem:\n\n"},
[83823] = {title = "Eine Lektion in Sachen Gewalt", objective = "Euer Knappe hat seine Fähigkeiten im Verlauf des Abenteuers an Eurer Seite verbessert!", description = "Eure Technik ist sehr interessant, <Name>. Sie hat mehr Ecken und Kanten als die von Sir Dalton, aber auch eine \"weltlichere\" Art, die gut zu mir passt, glaube ich. Ich danke Euch vielmals. Ich habe schon so viel von Euch gelernt!", progress = "Eure Technik ist sehr eindrucksvoll! Sie hat mehr Ecken und Kanten als die von Sir Dalton, aber auch eine \"weltlichere\" Art, die gut zu Euch passt. Ich danke Euch vielmals. Ich habe schon so viel von Euch gelernt und kann es kaum erwarten, es gegen unseren Feind anzuwenden!", completion = "Euer Knappe hat seine Fähigkeiten im Verlauf des Abenteuers an Eurer Seite verbessert!", rewards = "Ihr bekommt:\n\nDaltons Horn"},
[83934] = {title = "Her mit dem Geld!", objective = "Bringt einen angelaufenen Real aus Undermine zu Pix Xizzix in Booty Bay.", description = "Heda! Ihr sehr aus wie <ein \"findiger Abenteurer\"/eine \"findige Abenteurerin\">, vielleicht könnt Ihr mir helfen. Seht Ihr, meine Brüder und ich kamen von den Verlorenen Inseln auf der Suche nach einem neuen Geschäftsmodell, aber wir sind auf einige Piraten getroffen, die unser Startgeld gestohlen haben. Die Leute, die unsere Operation in der Heimat finanzieren, sind nicht gerade verständnisvoll, also würde es sich für Euch lohnen, wenn Ihr uns etwas des verlorenen Geldes zurückbringt. Es ist kein gewöhnliches Gold, aber Ihr werdet es erkennen, wenn Ihr es seht.", progress = "Was habt Ihr für mich, <Volk>?", completion = "He! Das ist großartig!\n\nWenn Ihr mehr von unserem Geld findet, kommt zu mir. Wir haben eine große Auswahl an Waren, die wir gerne mit Euch tauschen!", rewards = nil},
[83935] = {title = "Den Weg frei machen", objective = "Tötet 5 verseuchte Zombies, 10 Skelettschrecker und 10 faulende Kadaver, um den Weg für Knappen Cuthberts Flucht freizumachen.", description = "Das Pochen in meinem Kopf hat etwas nachgelassen, aber ich glaube nicht, dass ich mich hier alleine rauskämpfen kann. Ich bitte Euch nur ungerne erneut, aber würdet Ihr mir helfen, die Reihen zu lichten und mir einen Fluchtweg freizuräumen?", progress = nil, completion = "Habt erneut Dank, &lt;Klasse&gt;. Wenn wir jemanden wie Euch bei uns gehabt hätten, als wir überfallen wurden, bin ich sicher, dass wir das Blatt im Nu gegen unsere Angreifer gewendet hätten!\n\nIch habe jetzt etwas Rückenwind und muss Sir Dalton finden. Er ist ein fähiger Ritter, aber er braucht sicherlich meine Hilfe. Sagt, habt Ihr ihn da draußen gesehen? In seiner strahlend weißen Plattenrüstung ist er schwer zu übersehen.", rewards = "Ihr bekommt:\n\n"},
[83936] = {title = "Daltons Queste", objective = "Sprecht mit Knappe Cuthbert, um mehr über Sir Daltons Queste zu erfahren.", description = "<Knappe Cuthbert starrt leer auf die brennende Leiche von Dalton. Er steht sichtlich unter Schock. Ihr könnt sehen, dass er nicht in der Verfassung ist, die Queste fortzuführen, für die er mit seinem Herrn ausgezogen ist. Vielleicht solltet Ihr mit ihm sprechen, um zu sehen, wie Ihr ihm noch helfen könnt?>", progress = nil, completion = "Ich... weiß nicht, was ich sagen soll. Trotz der tristen Umstände kann ich mein Glück kaum fassen, mich im Dienst eines anderen Helden der Allianz wiederzufinden. Ich kann nur hoffen, dass ich Euch besser dienen werde, als ich es für Sir Dalton tat.\n\nGeht voran, Held.", rewards = nil},
[84008] = {title = "Eine Lektion in Sachen Anmut", objective = "Euer Knappe hat seine Fähigkeiten im Verlauf des Abenteuers an Eurer Seite verbessert!", description = "Eure Technik ist sehr interessant, <Name>. Sie hat mehr Ecken und Kanten als die von Sir Dalton, aber auch eine \"weltlichere\" Art, die gut zu mir passt, glaube ich. Ich danke Euch vielmals. Ich habe schon so viel von Euch gelernt!", progress = "Dank Eurer Lehren fühle ich mich dem Licht näher als je zuvor. Ich beginne zu verstehen, dass die Rolle eines Paladins ist, ebenso die Gnade zu empfangen, wie das eigene Kampfgeschick zu verbessern. Ich werde diese Lektion verinnerlichen und das, was ich gelernt habe, anwenden, um unsere Verbündeten zu stärken!", completion = "Dank Eurer Lehren fühle ich mich dem Licht näher als je zuvor. Ich beginne zu verstehen, dass die Rolle eines Paladins ist, ebenso das Licht zu empfangen, wie das eigene Kampfgeschick zu verbessern. Ich werde diese Lektion gut verinnerlichen und anwenden, was ich gelernt habe, um unsere Verbündeten zu stärken!", rewards = "Ihr bekommt:\n\nDaltons Horn"},
[84011] = {title = "Mehr Sternenlotus", objective = "Sammelt 10 Sternenlotus in den Hinterland-Alptraumeinfällen und kehrt dann zu Feldhauptmann Korlian zurück.", description = "Wir brauchen noch mehr Sternenlotus, um die Alptraumeinfälle umzukehren. Reist durch das Smaragdportal in Seradane und bringt mir welche.", progress = "Habt Ihr den Sternenlotus?", completion = "Gut gemacht! Danke. Eure Dienste werden nicht vergessen werden.", rewards = "Ihr bekommt:\n\nSmaragdsplitter"},
[84012] = {title = "Mehr Sternensilbererz", objective = "Sammelt 10 Stücke Sternensilbererz in den Hinterland-Alptraumeinfällen und kehrt dann zu Feldhauptmann Korlian zurück.", description = "Wir brauchen noch mehr Sternensilbererz, um die Alptraumeinfälle umzukehren. Reist durch das Smaragdportal in Seradane und bringt mir welches.", progress = "Habt Ihr das Sternensilbererz?", completion = "Gut gemacht! Danke. Eure Dienste werden nicht vergessen werden.", rewards = "Ihr bekommt:\n\nSmaragdsplitter"},
[84013] = {title = "Mehr Sternenmuscheln", objective = "Sammelt 10 Sternenmuscheln in den Hinterland-Alptraumeinfällen und kehrt zu Feldhauptmann Korlian zurück.", description = "Wir brauchen noch mehr Sternenmuscheln, um die Alptraumeinfälle umzukehren. Reist durch das Smaragdportal in Seradane und bringt mir welche.", progress = "Habt Ihr die Sternenmuscheln?", completion = "Gut gemacht! Danke. Eure Dienste werden nicht vergessen werden.", rewards = "Ihr bekommt:\n\nSmaragdsplitter"},
[84014] = {title = "Mehr Mondwurzel", objective = "Sammelt 10 Mondwurzeln in den Feralas-Alptraumeinfällen und kehrt zu Feldhauptmann Arunnel zurück.", description = "Wir brauchen noch mehr Mondwurzel, um die Alptraumeinfälle umzukehren. Reist durch das Smaragdportal im Traum-Geäst und bringt mir welche.", progress = "Habt Ihr die Mondwurzel?", completion = "Gut gemacht! Danke. Eure Dienste werden nicht vergessen werden.", rewards = "Ihr bekommt:\n\nSmaragdsplitter"},
[84015] = {title = "Mehr große Mondsteine", objective = "Sammelt 10 große Mondsteine in den Feralas-Alptraumeinfällen und kehrt zu Feldhauptmann Arunnel zurück.", description = "Wir brauchen noch mehr große Mondsteine, um die Alptraumeinfälle umzukehren. Reist durch das Smaragdportal im Traum-Geäst und bringt mir welche.", progress = "Habt Ihr die großen Mondsteine?", completion = "Gut gemacht! Danke. Eure Dienste werden nicht vergessen werden.", rewards = "Ihr bekommt:\n\nSmaragdsplitter"},
[84016] = {title = "Mehr Monddrachenschuppen", objective = "Sammelt 10 Monddrachenschuppen in den Feralas-Alptraumeinfällen und kehrt zu Feldhauptmann Arunnel zurück.", description = "Wir brauchen noch mehr Monddrachenschuppen, um die Alptraumeinfälle umzukehren. Reist durch das Smaragdportal im Traum-Geäst und bringt mir welche.", progress = "Habt Ihr die Monddrachenschuppen?", completion = "Gut gemacht! Danke. Eure Dienste werden nicht vergessen werden.", rewards = "Ihr bekommt:\n\nSmaragdsplitter"},
[84017] = {title = "Zeit zu töten", objective = "Findet Arkonos und bereitet ihm ein Ende.Ich habe das Gefühl, so viel in so kurzer Zeit gelernt zu haben. Ich glaube nicht, dass irgendjemand je bereit sein könnte, sich dem zu stellen, was vor mir liegt. Aber ich fühle mich so bereit wie nur möglich. Was sagt Ihr, <Name>? Wollen wir gehen und diesen Kampf beenden?\n\nIch bin nicht sicher, wo wir anfangen sollten, aber ich schätze wir werden irgendwo in den Östlichen Pestländern Hinweise finden. Wir sollten vielleicht in Gebieten anfangen, wo sich der Kult der Verdammten versammelt.", description = "Ich habe das Gefühl, so viel in so kurzer Zeit gelernt zu haben. Ich glaube nicht, dass irgendjemand je bereit sein könnte, sich dem zu stellen, was vor mir liegt. Aber ich fühle mich so bereit wie nur möglich. Was sagt Ihr, <Name>? Wollen wir gehen und diesen Kampf beenden?\n\nIch bin nicht sicher, wo wir anfangen sollten, aber ich schätze wir werden irgendwo in den Östlichen Pestländern Hinweise finden. Wir sollten vielleicht in Gebieten anfangen, wo sich der Kult der Verdammten versammelt.", progress = "Vergeltung ist nah, ich kann es spüren!", completion = "Wie es scheint, haben wir unseren Gegner gefunden, aber wir können ihn nicht erreichen. Wir müssen einen Weg zu ihm finden, sodass wir zuschlagen können.", rewards = "Ihr bekommt:\n\n"},
[84124] = {title = "Vermächtnis der Ehre", objective = "Kehrt zum Altar der Ehrerbietung zurück", description = "Der spektrale Champion gibt auf und deutet auf den Altar.", progress = nil, completion = "Auf dem von Euch geehrten Altar ruht eine majestätische, schwarz-goldene Zweihandaxt neben einem Folianten mit Legenden des Schlachtfelds.", rewards = "Ihr bekommt:\n\nRune des ersten KriegersVergelter der alten Wache"},
[84125] = {title = "Dem Ziel so nah", objective = "Tötet Schattenmagier und Schreckenswirker im Giftigen Tal und durchsucht ihre Leichen nach etwas, mit dem Ihr den Schild durchdringen könnt, der Arkonos schützt.", description = "Diese niederträchtigen Nekromanten und ihre Tricks sind abstoßend. Wir müssen einen Weg finden, die Barriere zu Arkonos zu durchbrechen und ihm ein Ende zu machen!\n\nViele Zauberwirker des Kultes der Verdammten und der Geißel sind dafür bekannt, eine Vielfalt an Teufelsinstrumenten und Fokussen der dunklen Magie zu besitzen. Vielleicht haben einige der Schattenmagier oder Schreckenswirker in der Nähe etwas, womit wir den Schild durchdringen können?", progress = "Was habt Ihr gefunden, <Name>?", completion = "Ja! Das könnte funktionieren. Gehen wir schnell zurück zum Schlachthaus und stellen dieses Gerät auf die Probe!", rewards = "Ihr bekommt:\n\n"},
[84126] = {title = "Den Kampf beenden", objective = "Tötet Arkonos den Verfluchten", description = "So könnte es gehen, <Name>. Dalton hat den Kult der Verdammten lange studiert und mir eine Reihe an Segen beigebracht, um ihre Magie abzuwehren. Dank Eurer Sorgfalt im Abschluss meiner Ausbildung glaube ich nun, dass ich stark genug bin, um einen dieser Segen auf das Gerät zu sprechen, der dessen Magie läutert, damit es die Barriere um Arkonos durchbrechen kann.\n\nKommt, brennen wir den Schild dieses Feiglings nieder und machen ihm endgültig den Garaus!", progress = "Endlich Rache.", completion = "Kaum zu fassen, dass wir es geschafft haben. Ich kann Euch nicht genug für die Hilfe danken, die Ihr mir in dieser Sache habt zukommen lassen, &lt;Name&gt;.\n\nDa es jetzt vollbracht ist... weiß ich nicht wirklich etwas mit mir anzufangen. Ich war so besessen von unserer Mission, dass ich überhaupt nicht darüber nachgedacht habe, was danach kommt. Für den Moment würde ich gerne unsere gemeinsamen Abenteuer fortführen, wenn Ihr es mir erlaubt. Ich habe viel gelernt, aber ich glaube, ich kann noch mehr von Euch lernen.", rewards = "Ihr erlernt:\n\nUmhang prägen - Schockierende Ehrfurcht\n\nDer folgende Zauber wird auf euch gewirkt:\n\nVerteidiger\n\nIhr bekommt außerdem:\n\nTestament der zornigen Vergeltung"},
[84135] = {title = "Strandbot", objective = "Nutzt einen Stein oder etwas Ähnliches, um Teile vom Mech zu lösen.", description = "An der Küste, halb von der Nachmittagsgischt verschlungen, liegt eine seltsame Metallkonstruktion. Sie sieht ein wenig auch sie ein Mech, aber Ihr habt noch nie einen solchen gesehen. Euch fällt ein Schild an seiner Seite auf, auf dem steht: \"Eigentum von T.H.E.T.A: TiefseeHydraulik- und ErforschungsTechnik-Allianz\". Ihr entdeckt außerdem ein kleines Fach, das Ihr vielleicht öffnen könnt.", progress = nil, completion = "Mithilfe Eurer Waffen- und Feldfähigkeiten könnt Ihr das Fach aufbiegen und eine Phiole mit einer leuchtenden Flüssigkeit freilegen.", rewards = "Ihr bekommt:\n\nGelenkter Auftriebbeschleuniger"},
[84136] = {title = "Die Tierherrschaftsmeisterin von Moonglade", objective = "Reist nach Nighthaven in Moonglade auf Kalimdor. Sucht nach Banteazo, einer Trolljägerin, und fragt sie nach ihren Erkenntnissen zur Tierherrschaft.", description = "Während ich Van Amburgh aufspüre, könntet Ihr eine alte Bekannte von mir kontaktieren. Banteazo ist gerade in Moonglade, wo sie mit den Druiden das Verhalten der Tiere beobachtet, um die Begleiterausbildung zu optimieren. Sie hat außerdem bereits gegen Van Amburgh gekämpft und hat möglicherweise einige Hinweise. Grüßt sie von mir!\n\nWenn Ihr fertig seid, trefft mich in Winterspring, ich möchte dort einigen Spuren nachgehen. Ich habe ein altes Lager in den Hügeln im Norden, dort könnten wir uns unter vier Augen unterhalten.", progress = nil, completion = "Ihr sagt, Estelenn lässt Grüße ausricht'n? Seltsam, ich hab diese Allianzflatter zuletzt geseh'n, als wir im Schlingendorntal Pfeile austauscht'n... Tja, dieser Ort is' neutraler Bod'n. Wenn sie Euch zu mir geschickt hat, dann wollt Ihr wohl über Tiere red'n, was?", rewards = "Ihr bekommt:\n\n"},
[84137] = {title = "Mechanische Romanze", objective = "Findet einen Nutzen für den gelenkten Auftriebsbeschleuniger.\n\nBereitgestellter Gegenstand: \n", description = "Ihr fragt Euch, warum dieser Mech hier liegengeblieben ist und wofür diese Flüssigkeit sein könnte. Vielleicht könnt Ihr sie nutzen, um die nahe gelegenen Inseln und die Ölplattform zu erreichen, die mit dieser geheimnisvollen Organisation zusammenzuhängen scheinen. Wenn Ihr eines wisst, dann dass magische Tränke ziemlich gut schmecken.", progress = nil, completion = "Als Ihr die Ölplattform erreicht, entdeckt Ihr einen Mann in einem Laborkittel, der an einigen Robotern herumschraubt. Er bemerkt Euch und, immer noch mit der Steuerung beschäftigt, ruft: \"Fantastisch! Ihr kommt gerade rechtzeitig. Ich habe Euch erwartet. Ihr habt meinen wunderbaren Trank getrunken, stimmt's? Ich bin Dr. Jürgens und ich habe Euch einen Vorschlag zu machen.\"", rewards = "Ihr bekommt:\n\n"},
[84138] = {title = "Frostige Gefallen", objective = "Erklärt Numi in Winterspring die Situation um das Buch von Dr. Jürgens.", description = "Ich bin leitender Ingenieur, Gründer und Meistertechniker der TiefseeHydraulik- und ErforschungsTechnik-Allianz. Ich habe mein neuestes Experiment fast beendet und ich brauche Eure Hilfe! Ich arbeite an einem speziellen Gerät, das ressourcenreiche Dimensionen ortet. Um meine Konstruktion zu vollenden, brauche ich etwas: ein Buch mit arkanen Formeln, das ich einer alten Kollegin geliehen habe. Sie heißt Numi und arbeitet in Winterspring. Bringt mir das Buch, ich werde Euch großzügig belohnen!", progress = nil, completion = "Sebastian braucht es? Er ist wirklich eine Nervensäge. Ihr verschwendet Eure Zeit mit der Frage nach dem Buch. Ich werde es Euch nicht geben oder Euch sagen, wo es ist. Aber vielleicht können wir einen Handel abschließen.", rewards = nil},
[84146] = {title = "Roter Taschenblues", objective = "Findet die rote Tasche, die Numi in Everlook bei einem Zeppelinabsturz über der Brennenden Steppe verloren hat.", description = "Was Ihr sucht, ist gut versteckt, und ich kann nur hoffen, dass das auch auf das zutrifft, was ich suche. Ich hatte eine rote Tasche mit einigen wertvollen, exotischen Dingen, die ich für optische Elektronik benutze. Aber ich habe sie bei einem Zeppelinunfall über der Brennenden Steppe verloren! Die Tasche könnte immer noch dort sein, aber bei den ganzen Orcs, Ogern und Plünderern musste ich meine Arbeit pausieren. Wenn Ihr die Tasche finden und mir wiederbringen könnt, werde ich Euch Jürgens' Buch überlassen.", progress = nil, completion = "Ihr findet die Tasche simpel und sorglos auf einem Tisch liegend vor.", rewards = "Ihr bekommt:\n\n[Red Bag]"},
[84147] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Blutproben aus Winterspring und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Wildherzens zu Deliana in Ironforge.", description = "Seid gegrüßt, <Klasse>. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterspring heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHandgelenksschützer des ungezähmten HerzensBänder des ungezähmten HerzensBindungen des ungezähmten HerzensWickeltücher des ungezähmten Herzens\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub"},
[84148] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Blutproben aus Winterspring und bringt sie zusammen mit 20 Gold und einem Paar Bestienjägerbindungen zu Deliana in Ironforge.", description = "Seid gegrüßt, <Klasse>. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterspring heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nArmschienen der TierherrschaftBindungen der Tierherrschaft\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub"},
[84149] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Blutproben aus Winterspring und bringt sie zusammen mit 20 Gold und einem Paar Bindungen des Magisters zu Deliana in Ironforge.", description = "Seid gegrüßt, <Klasse>. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterspring heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", progress = "Habt Ihr mitgebracht, worum ich Euch gebeten habe, <Name>?", completion = "Exzellent! Dann lasst uns den Austausch vornehmen. Es fällt mir nicht leicht, mich von dieser ausgezeichneten Rüstung zu trennen, aber ich fürchte, ich werde sie in nächster Zeit nicht brauchen.\n\nWenn Ihr daran interessiert sein solltet, mehr Arbeit für mich zu erledigen, wäre ich gewillt auch die anderen Teile aufzugeben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBindungen der Zauberkünste\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub"},
