[84162] = {title = "Ein aufrichtiges Angebot", objective = "Sammelt 15 Giftproben aus Silithus und bringt es zusammen mit 20 Gold und einem Paar Armschienen der Ehre zu Mokvar in Orgrimmar zurück.", description = "Ich grüße Euch, <Klasse>. Eure Haltung verrät mir, dass Ihr bereits ganz schön herumgekommen seid. Ich würde allerdings darauf wetten, dass Euch noch keine Rüstung wie diese untergekommen ist.\n\nWenn Ihr mir einen kleinen Gefallen tut, wäre ich bereit, diese Rüstung gegen ein normales Paar Armschienen einzutauschen.\n\nIch bräuchte eine ziemlich große Menge an Giftproben von den Spinnen und Skorpionen aus Silithus. Bringt sie mir zusammen mit einigen Goldmünzen und ich werde den Tausch vornehmen.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nArmschienen des HeldentumsHandgelenksschützer des Heldentums\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[84163] = {title = "Die angemessene Entlohnung", objective = "Bringt Deliana in Ironforge einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens.", description = "Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrechtzuerhalten. Bringt mir einen gewöhnlichen Gürtel und Handschuhe, von denen Ihr eine verbesserte Version wünscht. Ich kann Euch versichern, dass die Rüstung, die ich Euch geben werde, von weit höherer Qualität sein wird.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSet: Handschuhe und Gürtel der KatzeSet: Handschuhe und Gürtel des AstralenSet: Handschuhe und Gürtel des WächtersSet: Handschuhe und Gürtel des Heilers\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[84164] = {title = "Die angemessene Entlohnung", objective = "Bringt Deliana in Ironforge einen Bestienjägergürtel und ein Paar Bestienjägerhandschuhe.", description = "Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrecht zu erhalten. Bringt mir einen gewöhnlichen Gürtel und Handschuhe, von denen Ihr eine verbesserte Version wünscht.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSet: Handschuhe und Gürtel des VerfolgersSet: Handschuhe und Gürtel des Pirschers\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[84165] = {title = "Die angemessene Entlohnung", objective = "Bringt Deliana in Ironforge einen Gürtel des Magisters und ein Paar Handschuhe des Magisters.", description = "Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrecht zu erhalten. Bringt mir einen gewöhnlichen Gürtel und Handschuhe, von denen Ihr eine verbesserte Version wünscht.", progress = "Seid Ihr bereit, den Handel einzugehen?", completion = "Ihr habt Euren Teil der Abmachung eingehalten, also werde ich auch meinen einhalten.\n\nDenkt nur daran, dass ich Euch die besten Teile erst dann gebe, wenn Eure Arbeit vollbracht ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nGürtel der ZauberkünsteStulpen der Zauberkünste"},
[84166] = {title = "Die angemessene Entlohnung", objective = "Bringt Deliana in Ironforge einen Gürtel des Lichts und ein Paar Stulpen des Lichts.", description = "Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrechtzuerhalten. Bringt mir den Gürtel und die Handschuhe, von denen Ihr eine verbesserte Version wünscht. Ich kann Euch versichern, dass die Rüstung, die ich Euch geben werde, von weit höherer Qualität sein wird.", progress = "Seid Ihr bereit, den Handel einzugehen?", completion = "Ihr habt Euren Teil der Abmachung eingehalten, also werde ich auch meinen einhalten.\n\nDenkt nur daran, dass ich Euch die besten Teile erst dann gebe, wenn Eure Arbeit vollbracht ist.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSet: Handschuhe und Gürtel der GnadeSet: Handschuhe und Gürtel der StrahlenSet: Handschuhe und Gürtel des göttlichen Willens\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
