[84170] = {title = "Die angemessene Entlohnung", objective = "Bringt Deliana in Ironforge einen Gürtel der Ehre und ein Paar Stulpen der Ehre.", description = "Ihr habt Euer Wort gehalten und den von Mux konstruierten Apparat beschafft. Ich denke, eine Belohnung wäre nun angebracht, um Euer Interesse daran, meine Haut zu retten, aufrechtzuerhalten. Bringt mir den Gürtel und die Handschuhe, von denen Ihr eine verbesserte Version wünscht. Ich kann Euch versichern, dass die Rüstung, die ich Euch geben werde, von weit höherer Qualität sein wird.", progress = "Seid Ihr bereit, den Handel einzugehen?", completion = "Ihr habt Euren Teil der Abmachung eingehalten, also werde ich auch meinen einhalten.\n\nDenkt nur daran, dass ich Euch die besten Teile erst dann gebe, wenn Eure Arbeit vollbracht ist.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSet: Handschuhe und Gürtel der UnnachgiebigkeitSet: Handschuhe und Gürtel der Unaufhaltsamkeit\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[84171] = {title = "Die angemessene Entlohnung", objective = "Bringt Mokvar in Orgrimmar einen Gürtel des Wildherzens und ein Paar Handschuhe des Wildherzens.", description = "Ihr habt große Verlässlichkeit bewiesen, <Name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSet: Handschuhe und Gürtel der KatzeSet: Handschuhe und Gürtel des AstralenSet: Handschuhe und Gürtel des WächtersSet: Handschuhe und Gürtel des Heilers\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[84172] = {title = "Die angemessene Entlohnung", objective = "Bringt Mokvar in Orgrimmar einen Bestienjägergürtel und ein Paar Bestienjägerhandschuhe.", description = "Ihr habt große Verlässlichkeit bewiesen, <Name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.", progress = "Seid Ihr bereit, den Austausch vorzunehmen?", completion = "Unsere Vereinbarung steht. Denkt nur daran, dass dies nur ein Vorgeschmack dessen ist, was Euch erwartet. Befreit mich von diesem verfluchten Schicksal und ich werde Euch mit Gegenständen von wahrer Macht belohnen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSet: Handschuhe und Gürtel des PirschersSet: Handschuhe und Gürtel des Verfolgers\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[84173] = {title = "Die angemessene Entlohnung", objective = "Bringt Mokvar in Orgrimmar einen Gürtel des Magisters und ein Paar Handschuhe des Magisters.", description = "Ihr habt große Verlässlichkeit bewiesen, <Name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nGürtel der ZauberkünsteStulpen der Zauberkünste"},
