[84175] = {title = "Die angemessene Entlohnung", objective = "Bringt Mokvar in Orgrimmar einen Gürtel der Schattenkunst und ein Paar Handschuhe der Schattenkunst.", description = "Ihr habt große Verlässlichkeit bewiesen, <Name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.", progress = "Seid Ihr bereit, den Austausch vorzunehmen?", completion = "Unsere Vereinbarung steht. Denkt nur daran, dass dies nur ein Vorgeschmack dessen ist, was Euch erwartet. Befreit mich von diesem verfluchten Schicksal und ich werde Euch mit Gegenständen von wahrer Macht belohnen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSet: Handschuhe und Gürtel der SchlachtSet: Handschuhe und Gürtel des Rauschs\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[84176] = {title = "Die angemessene Entlohnung", objective = "Bringt Mokvar in Orgrimmar eine Kordel der Elemente und ein Paar Stulpen der Elemente.", description = "Ihr habt große Verlässlichkeit bewiesen, <Name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.", progress = "Seid Ihr bereit, den Austausch vorzunehmen?", completion = "Unsere Vereinbarung steht. Denkt nur daran, dass dies nur ein Vorgeschmack dessen ist, was Euch erwartet. Befreit mich von diesem verfluchten Schicksal und ich werde Euch mit Gegenständen von wahrer Macht belohnen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSet: Handschuhe und Gürtel der LinderungSet: Handschuhe und Gürtel der EruptionSet: Handschuhe und Gürtel des EinschlagsSet: Handschuhe und Gürtel der Entschlossenheit\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[84177] = {title = "Die angemessene Entlohnung", objective = "Bringt Mokvar in Orgrimmar einen Gürtel der Furcht und ein Paar Wickeltücher der Furcht.", description = "Ihr habt große Verlässlichkeit bewiesen, <Name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSet: Handschuhe und Gürtel der VerderbnisSet: Handschuhe und Gürtel der Boshaftigkeit\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[84178] = {title = "Die angemessene Entlohnung", objective = "Bringt Mokvar in Orgrimmar einen Gürtel der Ehre und ein Paar Stulpen der Ehre.", description = "Ihr habt große Verlässlichkeit bewiesen, <Name>. So sehr ich auch darauf vertraue, dass Ihr mir durch diese missliche Situation hindurchhelft, wäre es dennoch weiser, Euch zunächst Euren bisherigen Taten entsprechend zu entlohnen.\n\nIch werde zunächst Euren Gürtel und Eure Handschuhe austauschen. Wenn wir dies bis zum Ende durchstehen, werde ich Euch den Rest der Rüstung übergeben.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSet: Handschuhe und Gürtel der UnnachgiebigkeitSet: Handschuhe und Gürtel der Unaufhaltsamkeit\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[84179] = {title = "Anthions Abschiedsworte", objective = "Kehrt mit einem Paar Stiefel des Wildherzens, einem Kilt des Wildherzens und einer Schiftung des Wildherzens zu Deliana in Ironforge zurück.", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt, ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin, das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Sprecht auch mit ihr über etwaige Belohnungen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSet: Stiefel, Beine und Schultern der KatzeSet: Stiefel, Beine und Schultern des AstralenSet: Stiefel, Beine und Schultern des WächtersSet: Stiefel, Beine und Schultern des Heilers\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
