[84210] = {title = "Das Beste gibt's zum Schluss", objective = "Gebt Mokvar Euren Helm der Ehre und Eure Brustplatte der Ehre.", description = "Das ist ja eine unglaubliche Geschichte, <Name>! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Ihr habt durch Eure Taten die Sünden unserer Vergangenheit gesühnt.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSet: Helm und Brustteil der UnnachgiebigkeitSet: Helm und Brustteil der Unaufhaltsamkeit\n\nDer folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt außerdem:\n\n"},
[84211] = {title = "Plündererhöhle", objective = "Verteidigt Euch gegen Plünderer und bergt den Rest von Numis Materialien.", description = "Als Ihr die Tasche aufhebt, fällt Euch sofort auf, dass sie so gut wie leer ist. Irgendwie habt Ihr das Gefühl, dass Numi das Buch nicht gegen eine leere Tasche eintauschen wird. Das Lager ist hingegen alles andere als leer. Verteidigt Euch und haltet die Augen nach weiteren ihrer Sachen offen.", progress = "Habt Ihr die rote Tasche schon gefunden? Ich brauche das Zeug zurück, wenn ich mit den Teleskopaufrüstungen rechtzeitig zur Meteoritensaison fertig werden will!", completion = "Nun, Ihr habt Euch als ganz schön findig herausgestellt! Diese Materialien sind für mich unersetzlich. Ich kann Euch nicht genug danken! Hier, wie versprochen bekommt Ihr das Buch, das Jürgens zurückhaben möchte. Und nehmt noch ein heißes Getränk, bevor Ihr geht. Es ist kalt da draußen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBoss Kill Tracking [DNT]\n\nIhr bekommt:\n\nStrukturelle Flussdynamiken"},
[84212] = {title = "Rückbuchung", objective = "Kehrt mit dem Buch, das Jürgens haben wollte, in das T.H.E.T.A-Labor zurück.", description = "Numi überreicht Euch Jürgens' Buch. Ihr verstaut es sicher und macht Euch auf den Rückweg auf die andere Seite der Welt.", progress = "Hat sie das Buch behalten?", completion = "Wie ich sehe, habt Ihr mir mein gesuchtes Buch zurückgebracht. Ausgezeichnet! Euer Dienst ist von höchster wissenschaftlicher Bedeutung! Wir sind fast bereit, die geomantische Energie zu nutzen und ein stabiles Tor in eine andere Dimension zu öffnen.", rewards = "Ihr bekommt:\n\n"},
[84213] = {title = "Fortgerissen", objective = "Helft Dr. Jürgens beim Öffnen des Risses in Tirisfal oder Westfall.", description = "Schließt Euch mir in diesem historischen Experiment an und bezeugt die Wunder meiner Erfindung! Ich habe zwei Orte mit passenden geothermischen Bioflussenergien berechnet. Mit manuellen selbstzielenden Phasern kann ich uns direkt an die Koordinaten innerhalb kompatibler Regionen schicken.", progress = nil, completion = "Jürgens ist im Chaos verloren gegangen. Ihr seht eine schillernde Scheibe in einem länglichen Kristallbehälter. Darin befinden sich die zertrümmerten Überreste der inneren Mechanik des Golems. Ihr greift hinein, löst die Kabel vom Gehäuse und öffnet es.", rewards = "Ihr bekommt:\n\n[Sun Shades]Vorahnung und Voraussicht im Kampf"},
[84235] = {title = "Sturzflug!", objective = "Reist in die Hügel im Süden von Moonglade auf Kalimdor. Sucht nach einem Luftstrudel östlich der Hügel in der Nähe des Holzschlundtunnels. Nutzt die Sturzflugfähigkeit eines Tierbegleiters, um den Wirbelsturm zu durchdringen, und bergt ein Fragment elementarer Luft.", description = "Ihr sagt, Ihr sucht nach Van Amburgh? Wir könn' uns vielleicht geg'nseitig helf'n.\nDie Druiden hier mach'n sich Sorg'n weg'n einiger Fälle erhöhter elementarer Aktivität. Die Elementare umschwärmen 'n Fragment reiner elementarer Luft, das südlich des Sees einen Wirbelwind um sich herum manifestiert.\n\nGeht zu den Hügeln und holt Euch das elementare Fragment. Nehmt meinen Fledermausbegleiter, Zotl, um durch die Winde zu flieg'n, wenn Ihr keinen eigenen fliegend'n Begleiter habt. Zotl hängt in den Bäumen in der Nähe.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[84317] = {title = "Ewige Mitternacht", objective = "Erlangt astrale Einsichten", description = "Der gewaltige Titan umhüllt Euch mit einer Ätherurora, und die Weisheit und die Erfahrungen der Jahrhunderte verbinden sich mit Euren Erinnerungen.", progress = nil, completion = "Magisch gebunden und schimmernd schwebt der Foliant vor Euch.", rewards = "Ihr bekommt:\n\nErkenntnisse des Zeitlosen Wanderers"},
[84318] = {title = "Ey!", objective = "Findet Orthas' fehlenden Hammer bei Corrins Kreuzung.", description = "Ey! <Klasse>! Ja, Ihr da! Ihr habt mir einen Gefallen getan, als ihr diesen deprimierenden Fleischanzug zerschlagen habt, in dem ich all die Jahre unterwegs war, aber ich fühle keinen großen Drang, weiterzuziehen. Das liegt sicher daran, dass ich noch ein paar \"Angelegenheiten\" zu klären habe, bevor ich mich auf den Weg machen kann. Tja, Dummkopf, Ihr wurdet soeben zur Hilfe verpflichtet!\n\nIhr müsst mir meinen Hammer bringen. Er sollte irgendwo bei Corrins Kreuzung sein und ist kaum zu übersehen. \n\nEy, nehmt das hier auch mit. Das ist mein Lieblingsgoldzahn. Reibt ihn, wenn Ihr meine Waffe gefunden habt.", progress = "Was gibt's?", completion = "Ja, ich bin Euch sehr dankbar! Wo das jetzt geklärt ist, können wir den Rest zusammensetzen, damit ich mich auf den Weg machen kann!", rewards = "Ihr bekommt:\n\n"},
[84319] = {title = "Oh nein, nichts da!", objective = "Orthas möchte, dass Ihr seine verschwundene Rüstung aus der Leiche einer Monstrosität irgendwo im Pestwald bergt.", description = "Gute Arbeit mit dem Hammer, <Klasse>. Als Nächstes ist meine Rüstung dran. Die brauche ich auf jeden Fall wieder, um ins Jenseits zu gelangen. \n\nDas einzige Problem ist, sie steckt in den Eingeweiden einer dieser Monstrositäten. Ich weiß, ich weiß, das ist viel verlangt, aber Ihr müsst verstehen, dass ich einst ein mächtiger Than unter dem Berg war. Ich kann einfach nicht weiterziehen, wenn ich weiß, dass sich diese Ahnenrüstung meines Klans in den Eingeweiden eines riesigen verrottenden Fleischbergs auflöst!", progress = "Was gibt's?", completion = "Oh, sehr schön! Ein bisschen abgenutzt, aber das wird schon gehen. Wir haben noch eine letzte Sache zu erledigen. Ich brauche ein kleines Ritual. Nur etwas, das meinen verwirrten Geist wieder in Ordnung bringt, damit ich mich auf den Weg machen kann. Der letzte Teil ist vielleicht etwas unangenehm für Euch, weil Ihr ein &lt;Klasse&gt; seid und so, aber glaubt mir, es muss sein! \n\nZumindest wird's nicht unappetitlicher, als meine Hosen in dieser Monstrositätensuppe zu suchen! Haha!", rewards = "Ihr bekommt:\n\n"},
[84320] = {title = "Verlorenes Erbstück", objective = "Holt die Erbstücke aus der Krypta von Trauerhügel in den westlichen Pestländern und kehrt dann zur Hohepriesterin Laurena in der Kathedrale von Sturmwind zurück.", description = "Ich bin als Flüchtling nach Sturmwind gekommen, auf der Flucht vor der Verwüstung, die die Geißel über Lordaeron gebracht hat. Ich danke dem Licht, dass meine Familie und ich entkommen konnten, aber einige unserer wertvollen Erbstücke befinden sich noch immer in den Pestländern.\n\nWenn Ihr diese Erbstücke aus ihrer Ruhestätte in der Krypta von Trauerhügel holen könntet, damit ich sie sicher in den Katakomben der Kathedrale beisetzen kann, wäre ich Euch zutiefst dankbar.", progress = "Seid Ihr aus den Pestländern zurück?", completion = "Danke, &lt;Name&gt;. Ihr sagt, Ihr habt ein Tagebuch gefunden?", rewards = nil},
[84321] = {title = "Relikt des Lichts", objective = "Reist nach Hearthglen in den westlichen Pestländern und sucht nach Informationen über das im Tagebuch beschriebene Artefakt.", description = "Ich bin fasziniert von dem Artefakt, das in dem von Euch gefundenen Tagebuch erwähnt wird. Es könnte das sein, dass es genau das ist, was wir im Kampf gegen die Geißel brauchen.\n\nDie meisten der noch erhaltenen Aufzeichnungen aus Andorhal befinden sich unter dem Schutz des Scharlachroten Kreuzzugs in Hearthglen. Durchsucht sie und versucht, weitere Informationen zu finden.", progress = nil, completion = "Dieses Geschäftsbuch scheint Aufzeichnungen über die Aktivitäten des Scharlachroten Kreuzzugs in den Pestländern zu enthalten.", rewards = nil},
[84322] = {title = "Scharlachrote Forschung", objective = "Sucht nach dem Artefakt in der Festung des Scharlachroten Kreuzzugs bei Tyrs Hand in den östlichen Pestländern.", description = "Eine Seite des Geschäftsbuchs fällt Euch ins Auge:\n\n\"Artefakt, in der Nähe der Krypta von Trauerhügel gefunden. Starke Abstimmung auf das Licht. Schlechter Kandidat für das LW-Projekt aufgrund der Schutzwirkung und des Widerstands gegen Verstärkungszauber. Zur weiteren Untersuchung nach Tyrs Hand gebracht.\"", progress = nil, completion = "Beim Öffnen des Spinds findet Ihr eine kleine Kiste. Ist es das, wonach Ihr gesucht habt?", rewards = nil},
[84323] = {title = "Der Preis im Inneren", objective = "Findet einen Weg, die Kiste zu öffnen und das Artefakt zu bergen. Bringt es dann zur Hohepriesterin Laurena in der Kathedrale von Sturmwind.", description = "Aus der Kiste dringt Energie nach außen. Das muss das Artefakt sein! Jetzt müsst Ihr die Kiste nur noch öffnen...", progress = "Was habt Ihr gefunden, <Name>?", completion = "Die Geschichte war also wahr... Ich werde das hier aufbewahren und sein Potenzial untersuchen. Das könnte die Verteidigung gegen die Geißel sein, die wir brauchen.\n\nNehmt dies, &lt;Name&gt;. Ich danke Euch.", rewards = "Ihr bekommt:\n\nFrohlockende Offenbarung"},
[84324] = {title = "Diplomatische Annäherungsversuche", objective = "Holt die Vorräte und bringt sie zur Hohepriesterin Laurena in der Kathedrale von Sturmwind.", description = "<Name>, als ich den Lichtsplitter untersuchte, den Ihr mitgebracht habt, gewährte er mir Visionen. Ich sehe einen Priester der Horde, der einen ähnlichen Splitter findet, und ich sehe die Allianz und die Horde in einer Lichtwelle zusammenkommen.\n\nLeider haben sich unsere Beziehungen zur Horde weiter verschlechtert.\n\nIch schlage vor, ein diplomatisches Geschenk als Geste des guten Willens zusammenzustellen. Bringt mir diese Waren und wir werden sehen, ob wir einen Dialog zwischen unseren Völkern beginnen können.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAltruistenschutz"},
[84325] = {title = "Schrein der Zusammenarbeit", objective = "Überbringt der Hohepriesterin Laurena in der Kathedrale von Sturmwind den Kristall.", description = "Am Fuß der Statue lässt sich eine Platte herausschieben, die ein Stück Pergament und einen strahlenden Kristall freigibt, der dem ähnelt, den Ihr bei Tyrs Hand entdeckt habt.", progress = nil, completion = nil, rewards = nil},
[84326] = {title = "Diplomatenring", objective = "Überbringt der Hohepriesterin Laurena in der Kathedrale von Sturmwind die gewünschten Materialien.", description = "Das diplomatische Geschenk, das Ihr zusammengestellt habt, ist beim Priester der Verlassenen Dietrich Praice angekommen, und ich habe diskret Kontakt mit ihm aufgenommen. Wir sind uns beide einig, dass diese Suche unter den Gläubigen bleiben sollte. Wenn die Splitter als Waffe verwendet werden können, ist es am besten, wenn sie nicht in die Hände der Anführer einer der Fraktionen fallen.\n\nWir haben eine geheime Erkennungsmethode für diejenigen entwickelt, die nach den Splittern suchen. Bringt mir Materialien, um einen Ring zu schmieden, der ein Fragment von einem der Splitter enthält.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nDiplomatenring"},
[84327] = {title = "Eine diplomatische Mission", objective = "Nehmt Kontakt mit einem Priester der Horde an den Toren von Orgrimmar auf und erlangt diplomatische Immunität, indem beide Seiten ihre Diplomatenringe verwenden. Begebt Euch dann nach Orgrimmar und sprecht mit Dietrich Praice. Ihr verliert die diplomatische Immunität, wenn Ihr Euch zu weit von dem Euch begleitenden Priester entfernt oder in einen Kampf verwickelt werdet.", description = "Eure nächste Aufgabe wird recht schwierig, <Name>. \n\nIhr müsst Kontakt mit einem Priester der Horde aufnehmen, der die Splitter sucht. Anhand der Ringe könnt Ihr einander erkennen. Man wird Euch nach Orgrimmar begleiten, wo Ihr mit Dietrich Praice sprechen müsst.\n\nWenn Ihr die Priester der Horde davon überzeugen könnt, dass unsere Absichten friedlich sind, haben wir vielleicht eine Chance, die Splitter wieder zu vereinen.", progress = nil, completion = nil, rewards = nil},
[84328] = {title = "Reparatur des Splitters", objective = "Holt das Buch \"Angewandte Göttlichkeit\" aus Düsterbruch und kehrt dann zu Dietrich Praice in Orgrimmar zurück.\n\nUm Orgrimmar zu betreten und diplomatische Immunität zu erlangen, benötigt Ihr die Hilfe eines Hordenpriesters mit einem Diplomatenring. Ihr verliert die diplomatische Immunität, wenn Ihr Euch zu weit von dem Euch begleitenden Priester entfernt oder in einen Kampf verwickelt werdet.", description = "Ich bin bereit, zu glauben, dass Ihr mit guten Absichten hier seid, <Klasse>.\n\nWir sind für ein Treffen zwischen unseren Völkern offen. Aber der Lichtsplitter, den wir besitzen, ist in schlechtem Zustand. Wir müssen ihn aufladen, bevor wir versuchen, ihn mit den anderen zu vereinen.\n\nDie alten Hochgeborenen des heutigen Düsterbruchs waren Experten im Manipulieren arkaner und heiliger Energien. Geht dorthin und findet alle Informationen, die Ihr über Artefakte des Lichts finden könnt. Kehrt dann zu mir zurück.", progress = nil, completion = nil, rewards = nil},
[84329] = {title = "Die Synode kommt zusammen", objective = "Sprecht mit Maethra Schlackherz auf dem Gebirgspass der Totenwinde.", description = "Glaubensvertreter von Allianz und Horde haben vereinbart, sich zu treffen und die Splitter zu vereinen. Es gibt eine Kapelle neben der Turmruine von Karazhan, die als neutraler Ort dienen wird. \n\nEuer Ring enthält den letzten Splitter. Wenn Ihr da seid, kann die Beschwörung beginnen.", progress = nil, completion = nil, rewards = nil},
[84330] = {title = "Ein kleines bisschen Nekromantie", objective = "Besorgt Euch einen nekrotischen Runenstein von Maleki dem Leichenblassen in Stratholme und findet dann die verwesende Zwergenleiche in der Nähe des Tiefgewölbes im südwestlichen Teil der östlichen Pestländer.", description = "Ihr seht also, wir müssen eine passende Zwergenleiche finden und ein kleines Ritual mit ihr durchführen, um meinen Geist zu erden, damit ich meinen Weg finden kann! Alles ganz normale Dinge! Wir brauchen natürlich auch einen Teil eines nekrotischen Runensteins von einem Nekromanten. Ich hörte, es gibt einen in Stratholme. Er nennt sich Maleki der Leichenblasse oder so ähnlich. Ich kann mir nicht vorstellen, dass er ihn freiwillig hergibt, aber dafür gibt es eine Lösung!\n\nGebt mir den Stein und geht dann zum Tiefgewölbe. Dort findet Ihr eine passende Leiche!", progress = "...", completion = "&lt;Ihr greift nach der Leiche und Euch stellen sich die Nackenhaare auf... Ihr habt ein ungutes Gefühl bei der ganzen Sache.&gt;", rewards = "Ihr bekommt:\n\n"},
[84331] = {title = "Das Wunder", objective = "Wendet Euren Diplomatenring auf die Scherben an.", description = "Die Splitter sind vollständig, <Name>. Nun fehlt nur noch Euer Ring.", progress = nil, completion = nil, rewards = nil},
[84332] = {title = "Die Dankbarkeit eines Thans", objective = "Ihr findet einen kleinen Runenstein auf dem Boden der Truhe...", description = "<Ihr hört eine geisterhafte Stimme in Eurem Kopf, als Ihr die kleine Truhe berührt> \n\nKann Euch nicht genug danken, <Name>. So habt Ihr Euch das sicher nicht vorgestellt! Damit Ihr nicht zu sauer seid, habe ich etwas für Euch, das ich nicht mehr brauche und das Euch von Nutzen sein könnte.\n\nViel Glück, <Name>. Ach, eins noch... Wenn Ihr eines Tages eine riesige schwimmende Nekropole in der Ferne seht, würde ich an Eurer Stelle die Flucht ergreifen. Hah!Ihr erlernt:\n\n", progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nUmhang prägen - Schild der Rechtschaffenheit\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSchild der Rechtschaffenheit\n\nIhr bekommt außerdem:\n\nHammer des gefallenen Thans"},
[84338] = {title = "Ein verbindlicher Vertrag", objective = "Bringt den Vertrag der Thoriumbruderschaft zu Lokhtos Düsterfeilsch, wenn Ihr die Pläne für das Sulfuron erhalten möchtet.", description = "<Der Unterzeichner/Die Unterzeichnerin> bestätigt hiermit die Echtheit des Sulfuronblocks, der an die Thoriumbruderschaft (TB Ltd.) geliefert wird. <Der Unterzeichner/Die Unterzeichnerin> erkennt ebenso an, dass TB Ltd. keinerlei Verantwortung oder Haftung für jeglichen Schaden übernimmt, der <ihm/ihr> infolge des Versuchs, Sulfuras herzustellen, zu schmieden, verkaufen oder zu essen, widerfahren könnte.\n\nMit Unterzeichnung dieses Vertrags wird allen darin aufgeführten Bedingungen zugestimmt.\n\n_________________\n\nUnterschriftIhr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nPläne: Sulfuronhammer"},
[84348] = {title = "Primärziel: Herzog Tektonis", objective = "Hansel Bleihand in Thoriumspitze möchte, dass Ihr Herzog Tektonis vernichtet. Herzog Tektonis befindet sich in einem kleinen Tal westlich des Eingangs der sengenden Schlucht, nahe des Eingangs zum Schwarzfels.", description = "Ein besonders fieser Elementar namens Tektonis hat am Fuße des Schwarzfelsens das Sagen, und er muss einfach verschwinden! Erledigt diesen Steinhaufen und meldet Euch bei mir, wenn es vollbracht ist!\n\nIhr findet Herzog Tektonis in einem Tal im Südosten, nahe dem Eingang zum Schwarzfels.", progress = nil, completion = "Das wird ein herber Schlag für unsere Feinde sein, &lt;Name&gt;! Huzzah!", rewards = "Ihr bekommt:\n\nFeuerlandglut"},
[84349] = {title = "Primärziel: Herzog Sengbrand", objective = "Hauptmann des Ausgucks Lolo Langhieb will, dass Ihr Herzog Sengbrand vernichtet. Herzog Sengbrand befindet sich in den tiefsten Höhlen der Schlackengrube, direkt südlich von Thoriumspitze.", description = "Unsere Späher berichten, dass ein Feuerlord, der sich selbst Herzog Sengbrand nennt, in den Tiefen des Kessels nach Kräften versucht, weitere Feuerelementare aus den Feuerlanden zu beschwören! Ihr müsst dort hineingehen und der Sache Einhalt gebieten, bevor sie außer Kontrolle gerät.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Nach der ganzen Anstrengung brauche ich einen Drink! Hah!", rewards = "Ihr bekommt:\n\nFeuerlandglut"},
[84350] = {title = "Zermalmung", objective = "Evonice Sootsmoker möchte, dass Ihr 10 Obsidianhäscher in der Sengenden Schlucht tötet. Die Obsidianhäscher sind im gesamten südlichen Teil der Sengenden Schlucht und in der Nähe des Eingangs zum Blackrock zu finden.", description = "Diese Erdelementare sind überall! Verpasst ihnen eine ordentliche Tracht Prügel und schickt sie zurück in die Feuerlande!", progress = nil, completion = "Hah! Das wird ihnen eine Lehre sein!", rewards = "Ihr bekommt:\n\nFeuerlandglut"},
[84351] = {title = "Effizienz ist Trumpf", objective = "Zuchtmeister Skrange möchte, dass Ihr Obsidianwoger in der sengenden Schlucht tötet und ihre Kraftkerne zu ihm bringt. Obsidianwoger findet Ihr im südlichen Teil der sengenden Schlucht, in der Nähe des Eingangs zum Schwarzfels.", description = "Seit die Ausbrüche begonnen haben, kämpfen wir mit allen Mitteln gegen diese verfluchten Elementare, und die Anstrengungen fordern ihren Tribut von unseren Handwerkern. Offensichtlich ist es eine Menge Arbeit, die Ausrüstung der Truppen in einem tadellosen Zustand zu halten. Glücklicherweise sind wir Zwerge Meister darin, unsere Effizienz zu steigern, und wir haben herausgefunden, dass die Energiekerne in den Obsidianwogern südöstlich von Thoriumspitze als Schleifsteine für unsere Klingen verwendet werden können! \n\nWürdet Ihr mehr für uns holen?", progress = "Hm?", completion = "Das wird reichen, &lt;Klasse&gt;. Danke!", rewards = "Ihr bekommt:\n\n"},
[84355] = {title = "Flammenbringer auf Sparflamme", objective = "Zuchtmeister Skrange möchte, dass Ihr die Verteidiger und Elementarmagier der Flammenbringer auf dem Feuerwachtgrat westlich von Thoriumspitze tötet.", description = "Als hätten wir hier nicht schon genug zu tun, herrscht auch noch in der Enklave Schattenhammer westlich von Thoriumspitze emsiges Treiben, seit der Berg in die Luft geflogen ist. Soweit wir das beurteilen können, haben die neuen Flammenbringer jetzt das Sagen. \n\nSchaut doch mal dort vorbei und legt so viel um, wie Ihr könnt.", progress = nil, completion = "Auf Nimmerwiedersehen!", rewards = "Ihr bekommt:\n\nFeuerlandglut"},
[84356] = {title = "Oh, welch Glanz!", objective = "Meisterschmied Burninate in Thoriumspitze möchte, dass Ihr 8 Flammensteinsplitter von den Sklaventreibern der Dunkeleisenzwerge in der Schlackengrube sammelt. Den Eingang zur Schlackengrube findet Ihr im Kessel, südöstlich von Thoriumspitze.", description = "Vor Kurzem wurde eine Gruppe von Dunkeleisenzwergen gefangen genommen, die einige ausgesprochen seltsame verzauberte Edelsteine bei sich trugen. Diese Edelsteine scheinen in Azeroth nicht heimisch zu sein, und ich MUSS sie einfach weiter erforschen! Ihre Sklaven graben das Zeug jetzt tief im Kessel aus, und Ihr müsst Euch so schnell wie möglich auf den Weg dorthin machen und mir ein paar zusätzliche Proben bringen. Es wird sich für Euch lohnen!", progress = "Was habt Ihr für mich?", completion = "Sie sind wunderschön! Ich kann es kaum erwarten, sie unter mein Monoskop zu legen. Vielen Dank, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\nFeuerlandglut"},
[84359] = {title = "Schlaflose Nächte", objective = "Evonice Rußraucher bittet Euch, den speziell zubereiteten Traumsaft zu trinken und 5 Flammenbringerpirscher in der Nähe von Thoriumspitze in der sengenden Schlucht zu töten.", description = "Es reicht nicht, dass diese Hunde uns angreifen, wenn wir wach sind, sie müssen uns auch angreifen, wenn wir schlafen! Der neue Zwielichtfürst hat eine besondere Vorliebe für Traumschwindeleien, also schickt er Attentäter, die uns in unseren Träumen angreifen! Ich möchte, dass Ihr ein paar Schlucke von meinem speziell zubereiteten, regional bezogenen, nicht gentechnisch veränderten \"Traumsaft\" zu Euch nehmt. Der sollte es Euch ermöglichen, die Grenze zwischen der Wach- und der Traumwelt zu überqueren und diese Attentäter aufzuhalten.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Jetzt überlegen sie es sich bestimmt zweimal, bevor sie sich wieder nach Thoriumspitze schleichen!", rewards = "Ihr bekommt:\n\nFeuerlandglut"},
[84360] = {title = "Brandbekämpfung", objective = "Aufseher Schlickfaust möchte, dass Ihr 15 Feuerlandeindringlinge im Kessel, südlich von Thoriumspitze, tötet.", description = "Ihr da, Ihr wurdet gerade einberufen! Die Feuerelementare strömen unaufhörlich aus dem Kessel. Ihr musst da reingehen und die Wunde ausbrennen, wenn Ihr versteht, was ich meine. Reißt Euch zusammen, Soldat!", progress = "Ja?", completion = "Gut gemacht, &lt;Name&gt;. Ihr habt Mumm, das muss ich Euch lassen.", rewards = "Ihr bekommt:\n\nFeuerlandglut"},
[84369] = {title = "Die Heilung des Heilers", objective = "Holt Euch das ungewöhnliche Fläschchen von den Eisenwaldstampfern und bringt es zu den Frostfeuerquellen in Winterspring.", description = "Ich brauche Eure Hilfe. Mein Fläschchen wurde mir von den verderbten Treants des Eisenwalds innerhalb des Teufelswalds gestohlen. Die Kräutermischung sollte mir bei meinen Wunden helfen, aber sie allein wird nicht ausreichen. Bringt sie zu den heißen Quellen von Winterspring. Das heilende Wasser dort wird meine Genesung unterstützen.", progress = "Ihr habt es geschafft, <Name>.", completion = "Ich danke Euch, &lt;Klasse&gt;. Ihr habt mir viel Zeit erspart, indem Ihr mir mein Fläschchen gebracht habt. Damit wird sich die Verderbnis wesentlich schneller ausbreiten.\n\nLeider wird dies das letzte Mal sein, dass Ihr gebraucht werdet.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n[DNT] Calyx - Complete Quest\n\nIhr bekommt:\n\n"},
[84372] = {title = "Lavatauchen", objective = "Bringt Hansel Bleihand einen Brocken schimmerndes geschmolzenes Mineral. Ihr könnt das schimmernde geschmolzene Gestein in den Lavabecken der Schlackengrube tief im Kessel finden.", description = "Unsere Späher sagen mir, dass ein großer glühender Stein aus dem tiefsten Teil der Lavabecken unter dem Kessel ragt. Die Elementare scheinen auf dieses Material zu reagieren, also müsst Ihr Euch dort hineinschleichen und mir ein Stück von diesem Felsen holen. Da es dort unten in mehrfacher Hinsicht ziemlich heiß ist, solltet Ihr einen ordentlichen Vorrat an Feuerschutztränken mitnehmen!", progress = "Was habt Ihr denn da?", completion = "Wir hoffen, dass wir auf diese Weise ein wenig mehr darüber erfahren können, womit wir es zu tun haben.", rewards = "Ihr bekommt:\n\nFeuerlandglut"},
[84377] = {title = "Das Ende der Dunklen Horde", objective = "Bringt den Kopf von Rend Blackhand zu Meister Mathias Shaw in Stormwind.", description = "Die Tat ist vollbracht. Dal'rend Blackhand, Kriegshäuptling der Dunklen Horde, liegt tot zu Euren Füßen. Nehmt seinen Kopf und zeigt ihn Meister Shaw.", progress = "Beim Licht!", completion = "Gut gemacht, Champion. Der Kriegshäuptling der Dunklen Horde ist tot, und damit endet ein Zeitalter des Schreckens in unserem Land. Lasst ganz Sturmwind von Eurem Sieg wissen!", rewards = "Ihr bekommt:\n\n"},
[84384] = {title = "Dämonische Täuschungen", objective = "Sammelt 6 Zirbeldrüsen von Eulenbestien in Winterspring und kehrt dann zum Schattenzahn-Abgesandten im Teufelswald zurück.", description = "Ich habe von einem Gift gehört, das im Eschental an Kraft gewinnt, auf dem verdorbenen Land, wo der große Dämon Mannoroth getötet wurde. Jemand zieht Kraft aus den Überresten des Grubenlords.\n\nSie müssen Illusionen verwenden, um ihre Rituale zu verbergen. Wenn Ihr sie aufhalten wollt, müsst Ihr Euch vor ihren Täuschungen schützen.\n\nMein Stamm verwendet einen Extrakt aus Eulenbestiendrüsen in einem Zauber, um Wahrheit von Lüge zu unterscheiden. Sammelt diese Drüsen von den Eulenbestien in Winterspring.", progress = "Die Verzauberung ist fast fertig, <Name>. Habt ihr mitgebracht, worum ich Euch gebeten habe?", completion = "&lt;Der Troll spricht einen Zauberspruch über einem Gegenstand und gibt ihn Euch dann.&gt;\nNehmt das, &lt;Name&gt;. Dieser Gegenstand wird Euch vor den Illusionen der Dämonen schützen.", rewards = "Ihr bekommt:\n\nSchattenzahnillusionsschutz"},
[84394] = {title = "Großer Freund der Bibliothek", objective = "Dank Eurer Spenden entwickelt sich die Bibliothek prächtig.\n\nBitte, nehmt das.", description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nUmhang prägen - Arkanbeschuss\n\nDer folgende Zauber wird auf euch gewirkt:\n\n[DNT] Arcane Barrage"},
[84395] = {title = "Untote Kartoffeln", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen wächst durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[84396] = {title = "Magma oder Lava?", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen wächst durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[84397] = {title = "Nordkalimdor - ein umfassender Reiseführer", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen wächst durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
