[84399] = {title = "Krabumm!", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen wächst durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[84400] = {title = "Der Ritter und die Dame", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen wächst durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[84401] = {title = "Die Geißel: Untote Plage oder bloß missverstanden?", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen wächst durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[84402] = {title = "Einmaleins der Nekromantie", objective = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", description = nil, progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, &lt;Name&gt;. Unser Wissen wächst durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte.", rewards = "Ihr bekommt:\n\nVerständnisamulett"},
[84405] = {title = "Verlorenes Erbe", objective = "Holt die Erbstücke aus der Krypta von Trauerhügel in den westlichen Pestländern zurück und bringt sie zu Dietrich Praice in Orgrimmar.", description = "Bevor mich die Geißel verwandelte, war ich ein bedeutender Kaufmann in Andorhal. Die Stadt hat wahrscheinlich meine damaligen Reichtümer und meine Familienaufzeichnungen in der Krypta von Trauerhügel vergraben, als man mich für tot hielt.\n\nWärt Ihr so freundlich, meine Besitztümer aus der Krypta zu holen und sie mir zurückzugeben?", progress = nil, completion = nil, rewards = nil},
[84406] = {title = "Relikt des Lichts", objective = "Reist nach Hearthglen in den westlichen Pestländern und sucht nach Informationen über das im Tagebuch beschriebene Artefakt.", description = "Diese im Tagebuch beschriebene Waffe des Lichts bereitet mir Sorgen. Wenn der Scharlachrote Kreuzzug oder die Allianz so etwas in die Hände bekommen, könnte dies eine ernsthafte Bedrohung für die Verlassenen darstellen.\n\nDie meisten der noch existierenden Aufzeichnungen aus Andorhal stehen in Hearthglen unter dem Schutz des Scharlachroten Kreuzzugs. Durchsucht sie und findet weitere Informationen.", progress = nil, completion = nil, rewards = nil},
[84407] = {title = "Der Preis im Inneren", objective = "Findet einen Weg, die Kiste zu öffnen und das Artefakt zu bergen. Bringt es dann zu Dietrich Praice in Orgrimmar.", description = "Aus der Kiste dringt Energie nach außen. Das muss das Artefakt sein! Jetzt müsst Ihr die Kiste nur noch öffnen...Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFrohlockende Offenbarung"},
[84408] = {title = "Diplomatische Annäherungsversuche", objective = "Holt die Waren und bringt sie zu Dietrich Praice in Orgrimmar.", description = "<Name>, als ich den Lichtsplitter untersuchte, den Ihr mitgebracht habt, gewährte er mir Visionen. Ich sehe einen Priester der Allianz, der einen ähnlichen Splitter findet, und ich sehe die Allianz und die Horde in einer Lichtwelle zusammenkommen.\n\nLeider behandelt uns die Allianz weiterhin wie Ungeziefer.\n\nIch schlage vor, ein diplomatisches Geschenk als Geste des guten Willens zusammenzustellen. Bringt mir diese Waren und wir werden sehen, ob wir einen Dialog zwischen unseren Völkern beginnen können.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAltruistenschutz"},
[84410] = {title = "Schrein der Zusammenarbeit", objective = "Bringt den Kristall zu Dietrich Praice in Orgrimmar.", description = "Am Fuß der Statue lässt sich eine Platte herausschieben, die ein Stück Pergament und einen strahlenden Kristall freigibt, der dem ähnelt, den Ihr bei Tyrs Hand entdeckt habt.", progress = nil, completion = nil, rewards = nil},
[84411] = {title = "Diplomatenring", objective = "Bringt die gewünschten Materialien zu Dietrich Praice in Orgrimmar.", description = "Das diplomatische Geschenk, das Ihr zusammengestellt habt, ist bei Hohepriesterin Laurena in Sturmwind angekommen, und ich habe diskret Kontakt mit ihr aufgenommen. Wir sind uns beide einig, dass diese Suche unter den Gläubigen bleiben sollte. Wenn die Splitter als Waffe verwendet werden können, ist es am besten, wenn sie nicht in die Hände der Anführer einer der Fraktionen fallen.\n\nWir haben eine geheime Erkennungsmethode für diejenigen entwickelt, die nach den Splittern suchen. Bringt mir Materialien, um einen Ring zu schmieden, der ein Fragment von einem der Splitter enthält.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nDiplomatenring"},
[84412] = {title = "Eine diplomatische Mission", objective = "Nehmt Kontakt mit einem Priester der Allianz an den Toren von Sturmwind auf und erlangt diplomatische Immunität, indem beide Seiten ihre Diplomatenringe verwenden. Betretet dann die Kathedrale von Sturmwind und sprecht mit Hohepriesterin Laurena. Ihr verliert die diplomatische Immunität, wenn Ihr Euch zu weit von dem Euch begleitenden Priester entfernt oder in einen Kampf verwickelt werdet.", description = "Eure nächste Aufgabe wird recht schwierig, <Name>.\n\nIhr müsst Kontakt mit einem Priester der Allianz aufnehmen, der die Splitter sucht. Anhand der Ringe könnt Ihr einander erkennen. Man wird Euch in die Kathedrale von Sturmwind begleiten, wo Ihr mit Hohepriesterin Laurena sprechen müsst.\n\nWenn Ihr die Priester der Allianz davon überzeugen könnt, dass unsere Absichten friedlich sind, haben wir vielleicht eine Chance, die Splitter wieder zu vereinen.", progress = nil, completion = nil, rewards = nil},
[84413] = {title = "Reparatur des Splitters", objective = "Holt das Buch \"Angewandte Göttlichkeit\" aus Düsterbruch und kehrt dann zu Hohepriesterin Laurena in der Kathedrale von Sturmwind zurück.\n\nUm Sturmwind zu betreten und diplomatische Immunität zu erlangen, benötigt Ihr die Hilfe eines Allianzpriesters mit einem Diplomatenring. Ihr verliert die diplomatische Immunität, wenn Ihr Euch zu weit von dem Euch begleitenden Priester entfernt oder in einen Kampf verwickelt werdet.", description = "Ich bin bereit, zu glauben, dass Ihr mit guten Absichten hier seid, <Klasse>.\n\nWir sind für ein Treffen zwischen unseren Völkern offen. Aber der Lichtsplitter, den wir besitzen, ist in schlechtem Zustand. Wir müssen ihn aufladen, bevor wir versuchen, ihn mit den anderen zu vereinen.\n\nDie alten Hochgeborenen des heutigen Düsterbruchs waren Experten im Manipulieren arkaner und heiliger Energien. Geht dorthin und findet alle Informationen, die Ihr über Artefakte des Lichts finden könnt. Kehrt dann zu mir zurück.", progress = nil, completion = nil, rewards = nil},
[84414] = {title = "Bringt mich auf den Weg!", objective = "Beobachtet Orthas, während er diese Welt verlässt.", description = "<Ihr hört die körperlose Stimme von Orthas in Eurem Kopf.>\n\nDa wären wir. Ziehen wir's durch, ja?", progress = nil, completion = "Euch fehlen die Worte für das gerade Geschehene. Was habt Ihr getan? \n\nHoffentlich findet sich in dieser Truhe wenigstens gute Beute.", rewards = "Ihr bekommt:\n\n"},
[84418] = {title = "Der vermisste Ritter", objective = "Ein gemeinsamer Freund von uns hat kürzlich um Hilfe bei der Suche nach einem vermissten Ritter namens Dalton gebeten. Er und sein junger Knappe wurden zuletzt in den Pestländern gesehen und man hat schon seit einiger Zeit nichts mehr von ihnen gehört. Falls Euch Eure Reisen dorthin führen, haltet bitte nach ihnen Ausschau.\n\nEs gibt nicht gerade viele Hinweise, aber Ihr habt die Gabe, in alle möglichen interessanten Situationen zu geraten. Wenn jemand inmitten dieser höllischen Pestländer über einen vermissten Ritter und seinen Knappen stolpern könnte, dann Ihr.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTestament des göttlichen Streitrosses"},
[84495] = {title = "Feurige Plattenstulpen", objective = "Bringt Malyfous Düsterhammer 6 verzauberte Thoriumbarren, 2 Essenzen des Feuers und 4 Sternrubine. Ihr müsst außerdem Eure ungebrannten Plattenstulpen abgeben.", description = "Beim Barte Thaurissans!\n\nWo habt Ihr sie gefunden?\n\nNoch wichtiger: Seid Ihr bereit, Euch von ihnen zu trennen? Natürlich würde ich solch eine noble Geste belohnen.\n\nIch sag Euch was, <Name>. Wenn Ihr mir diese ungebrannten Stulpen gebt, werde ich Euch beibringen, wie Ihr selbst welche herstellen könnt. Ihr müsst nur die Teile für mich besorgen, damit ich das genaue Rezept benutzen kann.\n\nAbgemacht?\n\nHier ist die Liste dessen, was ich benötige. Ich werde das nicht-verzauberte Thorium selbst übernehmen, da Ihr ja die Stulpen liefert.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nPläne: Feurige Plattenstulpen der verborgenen TechnikFeurige Plattenstulpen der verborgenen Technik"},
[84496] = {title = "Süße Beschaulichkeit", objective = "Begebt Euch nach Stratholme und tötet den purpurroten Hammerschmied. Nehmt die Schürze des purpurroten Hammerschmiedes und kehrt zu Lilith zurück.", description = "In den Grenzen der Scharlachroten Bastion liegt die süße Beschaulichkeit. Der purpurrote Hammerschmied bewacht das Rezept mit seinem Leben. Besiegt ihn und bringt mir seine Schürze. Dafür werde ich Euch zu einem Hammerschmied ausbilden.\n\nIhr müsst eines wissen: Wenn Ihr Euch für den Weg des Hammerschmieds entschieden habt, sind die Wege des Schwertschmieds und des Axtschmieds nicht mehr verfügbar.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHammerschmiedemeister\n\nIhr bekommt:\n\nPläne: Sorgsam verzauberter Kampfhammer"},
[84525] = {title = "Überirdischer Schatz", objective = "Bitteschön, Boss!Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nÜberirdischer Schatz"},
[84545] = {title = "Die Belohnung eines Helden", objective = "Nehmt Eure Belohnung aus Hydraxis' Truhe.", description = "<Name>, Euer Dienst für die Kriegsherrn hat alles übertroffen, was wir je von den Einwohnern dieser Welt erwartet haben.\n\nWir kennen zwar nicht die Vorstellung Eures Volkes, von Dankbarkeit oder wie Ihr gute Arbeit bei Euch belohnt, aber in diesem Fall... ist eine Belohnung mehr als angebracht.\n\nUnter der Brandung an der südlichen Basis der Insel findet Ihr einen Kasten. In diesem werdet Ihr Eure... Belohnung finden.\n\nGeht, <Name>. Nehmt Euch Eure Belohnung.", progress = nil, completion = "Hydraxis' Stimme erklingt von der Wasseroberfläche aus...\n\n\"Wählt was am besten zu Euch passt, &lt;Name&gt;. Möge es Euch vor den Feinden des Wasserlords schützen.\"", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMeeresbriseGezeitenschleife\n\nIhr bekommt außerdem:\n\n"},
[84546] = {title = "Holzstab der Uralten", objective = "Ihr müsst die vier dämonischen Verderber ausfindig machen und zerstören:\n\nSimone die Verführerin.\n\nKlinfran der Wahnsinnige.\n\nSolenor der Schlächter.\n\nArtorius der Verhängnisvolle.\n\nVernichtet diese Kreaturen und kehrt zu Vartrus dem Uralten im Teufelswald zurück.\n\nHaltet Euch an die versteinerte Rinde in Eurem Inventar, um Hinweise zu ihren Aufenthaltsorten zu erhalten.\n\nIhr MÜSST diese Aufgabe eigenständig erledigen.", description = "Agenten der Brennenden Legion sind noch immer in unserer Welt aktiv, <Klasse>. Diese Agenten verderben alles, was ihnen unterkommt. Die Natur welkt und siecht in ihrer Gegenwart dahin.\n\nIhr müsst diese dämonischen Verderber aufspüren und zerstören, <Name>. Seid gewarnt, Ihr müsst sie selbst angreifen, andernfalls werden sie fliehen. Solange Ihr alleine seid, werden sie versuchen Euch zu zerstören. Ihr müsst sie bekämpfen und ihren Hochmut zu ihrem Verderben werden lassen.\n\nIch gewähre Euch ein Stück meiner Rinde, mögen die Inschriften Euch zu Eurem Ziel führen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAntiker runenverzierter Stab"},
[84548] = {title = "Garona: Eine Studie über Heimlichkeit und Verrat", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, &lt;Volk&gt;. Solltet Ihr noch weitere Folianten finden, zögert nicht sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nKönigliches Siegel von Eldre'Thalas"},
[84549] = {title = "Das Arkanistenkochbuch", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nKönigliches Siegel von Eldre'Thalas"},
[84550] = {title = "Kodex der Verteidigung", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.", progress = "Ihr habt einen Folianten wiedergefunden.", completion = "Gut gemacht, &lt;Volk&gt;. Solltet Ihr noch weitere Folianten finden, zögert nicht, sie uns zurückzubringen.\n\nNatürlich erhaltet Ihr eine Belohnung, wenn Ihr uns einen vermissten Folianten zurückbringt. Mit der Zeit ändern wir die Belohnungen oder fügen neue hinzu.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nKönigliches Siegel von Eldre'Thalas"},
[84551] = {title = "Vom Licht und wie man es schwingt", objective = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.", description = "Der Foliant trägt das Zeichen des Athenaeums.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nErfahrungsschub\n\nIhr bekommt:\n\nKönigliches Siegel von Eldre'Thalas"},
[84555] = {title = "Nostros Kompendium", objective = "Bringt Nostros Kompendium des Drachentötens zum Athenaeum zurück.", description = "Ihr habt etwas von großer Bedeutung entdeckt. Dieses Buch ist nicht wie all die anderen, die Ihr gesehen habt.\n\nEs scheint, als hätte jemand... oder etwas... es geschafft, das Siegel des Athenaeums zu brechen. Die Schrift im Inneren ist wirr und lässt sich kaum lesen.", progress = "Ah, eines unsere größten Sammelwerke. Das hat schon seit Ewigkeiten gefehlt.", completion = "Auf dem Schwarzmarkt hättet Ihr für dieses Buch ein hübsches Sümmchen kassiert, &lt;Name&gt;. Insbesondere, da das Schutzsiegel gebrochen wurde, wodurch die Geheimnisse des Drachentötens allen zugänglich wäre, die über den nötigen Intellekt verfügen, das Wissen auf diesen heiligen Seiten in sich aufzunehmen.\n\nEs ist wohl eine große Belohnung fällig... Nun, eine Belohnung, die gewaltiger Mühen bedarf, um sie Euch zu verdienen.", rewards = "Ihr bekommt:\n\n"},
[84556] = {title = "Das Schmieden von Quel'Serrar", objective = "Gebt Hüter des Wissens Lydros die stumpfe und glanzlose Elfenklinge.", description = "Wenn Ihr diesen Auftrag annehmen möchtet, dann präsentiert Lydros die stumpfe Klinge.", progress = "Exzellent, lasst uns beginnen...", completion = "Wenn Ihr es schafft, den Drachenhort zu betreten, die Klinge unter ihrem feurigen Atem zu erhitzen und sie anschließend in ihrem Blut zu härten, dann werde ich sie für Euch binden.", rewards = nil},
[84557] = {title = "Das Schmieden von Quel'Serrar", objective = "Ihr müsst Onyxia dazu bringen, ihren Feueratem auf die unbefeuerte uralte Klinge zu richten. Sobald das erledigt ist, könnt ihr die nun erhitzte uralte Klinge wieder aufnehmen. Aber seid gewarnt, die erhitzte uralte Klinge wird nicht ewig heiß bleiben... es ist also Eile geboten.\n\nFür den letzten Schritt müsst Ihr die Bestie töten und die erhitzte uralte Klinge in ihren Leichnam versenken, bevor Ihr zu mir zurückkehren könnt.\n\nTut das, und Quel'Serrar wird Euer sein.", description = "Nehmt die unbefeuerte uralte Klinge zu Onyxias Hort und stellt Euch ihr im Kampf.\n\nEs bedarf einer List, um die Klinge zu erhitzen. Während Ihr Euch im Kampf befindet, wird sie mit Sicherheit versuchen, Euch mit ihrem Feueratem einzuäschern. Platziert die unbefeuerte Klinge in der Nähe und hofft, dass der Feueratem die Klinge erhitzt. Wenn Ihr all das überlebt, dann nehmt die uralte Klinge und erlegt den Drachen.\n\nTaucht die erhitzte uralte Klinge anschließend in Onyxias schwelenden Leichnam, um die behandelte uralte Klinge zu erhalten.", progress = "Möglicherweise wird eines Tages jemand anderes die prismatische Klinge führen.", completion = "&lt;Lydros murmelt unverständlich vor sich hin.&gt;\n\nWie versprochen, &lt;Klasse&gt;, die Klinge von Quel'Serrar.", rewards = "Ihr bekommt:\n\nQuel'Serrar"},
[84560] = {title = "Gute Zeiten feiern", objective = "Sucht Major Mattingly im Tal der Helden auf.", description = "Sucht Major Mattingly im Tal der Helden auf, <Name>. Er erwartet Euch bereits...Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTalisman mit OnyxiablutDrachentötersignetZahn Onyxias\n\nIhr bekommt außerdem:\n\n"},
[84561] = {title = "Für alle sichtbar", objective = "Sucht Oberanführer Runthak im Tal der Stärke auf.", description = "Oberanführer Runthak erwartet Eure Ankunft im Tal der Stärke.\n\n<Thrall salutiert Euch.>\n\nLasst Euer Publikum nicht warten, großer Held.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTalisman mit OnyxiablutDrachentötersignetZahn Onyxias\n\nIhr bekommt außerdem:\n\n"},
[84590] = {title = "Die Waage von Licht und Schatten", objective = "Rettet 50 Arbeiter, bevor 15 getötet werden. Sprecht mit Eris Himmelsfeuer, falls Ihr diesen Auftrag erfolgreich zu Ende bringen solltet.\n\nKonsultiert den Todesposten, um zu sehen, wie viele Arbeiter bereits getötet wurden.", description = "Ihr müsst tun, was ich nicht konnte: Rettet die Arbeiter, die während ihrer Flucht von Stratholme niedergemäht wurden.\n\nSie werden dem Licht entgegenlaufen, sorgt für ihr Überleben. Sollten zu viele von ihnen fallen, wird unsere Existenz auch weiterhin verdammt sein - und Ihr habt versagt.\n\nAlle von Euch gelernten Fähigkeiten, Gebete und Zauber werden auf die Probe gestellt werden. Möge das Licht Euch beschützen, <Name>.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSplitter von Nordrassil"},
[84636] = {title = "Streuner", objective = "Reist zu den Grabhügeln im Osten von Moonglade auf Kalimdor. Steigt in den südöstlichsten Grabhügel des Stormrage hinab und sucht in den Tiefen nach dem Erdelementarfragment. Verwendet die Fertigkeit 'Schleichen' Eures Tierbegleiters, um an den Wächtern vorbeizukommen und ein Fragment eines Erdelementar zu bergen.", description = "Die Druiden mach'n sich Sorg'n wegen eines Erdfragments in den Grabhügeln östlich des Sees. Es wird von wütenden Erdelementaren bewacht, die die Druiden davon abhalt'n, ihre Riten durchzuführ'n.\n\nSteigt in die Grabhügel hinab und holt Euch das Elementarfragment. Nehmt meine Katze, Siopi, mit, um an den Elementaren vorbeizuschleich'n, falls Ihr selbst keinen Katzenbegleiter habt. Siopi liegt wahrscheinlich irgendwo in der Nähe im Gras und schläft.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[84777] = {title = "Federn für Nafien", objective = "Ihr habt Euch mir gegenüber mehr als bewiesen, doch um das Vertrauen meiner misstrauischen Brüder und Schwestern zu gewinnen, ist es noch ein weiter Weg. Keine Sorge, ich werde Euch dabei behilflich sein, auch diese letzte Hürde zu überwinden.\n\nEinige Furbolgs der Totenwaldfelle tragen einen auffälligen Kopfschmuck. Dieser wäre ein ausreichender Beweis, für Euren Kampf gegen unsere verderbten Geschwister. Bringt mir die Federn der von Euch erbeuteten Kopfschmucke. Für jeweils fünf Federn die Ihr bei mir abgebt, wird sich Euer Ruf unter den Einwohnern der Holzschlundfeste verbessern.", description = nil, progress = "Ihr habt Euch mir gegenüber mehr als bewiesen, doch um das Vertrauen meiner misstrauischen Brüder und Schwestern zu gewinnen, ist es noch ein weiter Weg. Keine Sorge, ich werde Euch dabei behilflich sein, auch diese letzte Hürde zu überwinden.\n\nEinige Furbolgs der Totenwaldfelle tragen einen auffälligen Kopfschmuck. Dieser wäre ein ausreichender Beweis, für Euren Kampf gegen unsere verderbten Geschwister. Bringt mir die Federn der von Euch erbeuteten Kopfschmucke. Für jeweils fünf Federn die Ihr bei mir abgebt, wird sich Euer Ruf unter den Einwohnern der Holzschlundfeste verbessern.", completion = "Gut gemacht, &lt;Name&gt;! Ich werde dafür Sorgen, dass alle Furbolgs der Holzschlundfeste von Euren Taten erfahren.\n\nVergesst nicht, mir alle Federn zu bringen, die Ihr findet.", rewards = nil},
[84853] = {title = "Spuren im Schnee", objective = "Reist zu den Hügeln in Winterspring im Norden von Kalimdor, nördlich von Everlook, und trefft Euch dort mit Estelenn, um zu erfahren, wie Ihr ihr helfen könnt.", description = "Ihr habt gute Arbeit geleistet. Ich werd' Euch helf'n. Als ich Van Amburgh das letzte Mal geseh'n hab, hatte er 'ne Menagerie aus drei Tier'n bei sich, 'ne Großkatze, 'nen Raptor und 'nen monströs'n Käfer. Er hält sie in Käfigen, peitscht sie aus, macht sie richtig wütend. Grausamkeit und Hunger sind seine Erziehungsmaßnahmen. Hab vor 'ner Weile in Feralas geg'n ihn gekämpft, keine Ahnung, wo er grade is'.\n\nIhr solltet Euch mit Estelenn treff'n un' seh'n, ob sie Eure Hilfe braucht. Und richtet ihr Grüße von mir aus.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[84870] = {title = "Der dunkle Hort", objective = "Brecht in das Lager von Blackrockspitze ein und stehlt alle Wertsachen, die sich dort befinden. Ihr müsst den Auftrag alleine abschließen.", description = "Das Dokument ist ein Bericht von einem von Razorgores Untergebenen. Es gibt Gerüchte, dass einige der Blackrock-Orcs verbotene magische Artefakte im Lagerhaus verstecken. Es ist ungewiss, ob es sich um eine einfache Schmuggelaktion handelt oder ob mehr dahintersteckt.\n\nWie dem auch sei, es hört sich nach einer lukrativen Sache an. Geht lieber allein, damit Ihr nicht entdeckt werdet. Dann braucht Ihr auch die Beute nicht teilen.", progress = nil, completion = "Ich kann sehen, dass Ihr nicht zu ihnen gehört. Ich bitte um Verzeihung.", rewards = "Ihr bekommt:\n\n"},
[84880] = {title = "Der Feind meines Feindes", objective = "Im Syndikat braut sich eine schreckliche Bedrohung zusammen. Jemand in Rabenholdt könnte wissen, was zu tun ist.", description = "Ich wurde zusammen mit einem Magier hierhergeschickt, um die Klinge des Verschlingens für das Syndikat zu stehlen. Aber als ich die Schlösser geknackt hatte, hat er mich angegriffen. Er hat sich die Klinge geschnappt und mich dem Tod überlassen.\n\nDer Name des Magiers war Caius. Er ist vor nicht allzu langer Zeit zu uns gestoßen und versprach, dass er sein Wissen über ein mächtiges Ritual mit uns teilen würde, wenn wir ihm im Gegenzug dabei helfen, die letzte Reagenz zu stehlen.\n\nDiese verräterische Schlange und sein Ritual müssen aufgehalten werden. Er darf damit nicht durchkommen!", progress = nil, completion = "Ich kann verstehen, warum Ihr mir das gebracht habt, &lt;Klasse&gt;. Das sind wahrlich beunruhigende Neuigkeiten. Wir müssen unseren nächsten Schritt genau durchdenken. Lasst mich kurz allein, damit ich in Ruhe nachdenken kann.", rewards = "Ihr bekommt:\n\n"},
[84881] = {title = "In die Feste des Schattens", objective = "Findet Caius in der Schattenfeste im Teufelswald und haltet sein Ritual auf. Bringt außerdem einen Beweis seines Ablebens zu Fahrad im Rabenholdtanwesen. Ihr müsst alleine gehen und unentdeckt bleiben, bis Ihr Caius findet.", description = "Caius' Verrat bereitet mir echte Sorgen. Er deutet darauf hin, dass es eine weitere, noch gefährlichere Organisation gibt.\n\nUnsere Geheimdienstinformationen lassen vermuten, dass es sich dabei um den Schattenrat handelt.\n  \nDas Hauptquartier des Rats befindet sich in der Schattenfeste im Teufelswald. Ihr müsst die Schattenfeste infiltrieren, Caius finden und ihn aufhalten.\n\nEs ist zwingend erforderlich, dass Ihr unentdeckt bleibt. Sollte Caius von Eurer Anwesenheit erfahren, wird er wahrscheinlich fliehen oder Euch töten lassen.", progress = "Habt Ihr Caius schon gefunden?", completion = "Caius war also in der Tat ein Verbündeter des Schattenrats. Die Konsequenzen einer solchen Verschwörung könnten gigantisch sein.\n\nDer erfolgreiche Abschluss Eurer Mission hat wertvolle Informationen zutage gebracht und eine noch größere Gefahr für Azeroth abgewendet. Herausragende Arbeit, &lt;Name&gt;.   \n\nWas den von Euch gefundenen \"Traumfresser\" betrifft: Mich schaudert es bei dem Gedanken daran, was hätte passieren können, wenn Caius das Ritual beendet hätte. Setzt ihn mit Geschick ein und wählte Eure Ziele weise.", rewards = "Ihr bekommt:\n\nTraumfresser"},
[84950] = {title = "Hinaus in die Kälte", objective = "Verwendet Eure Überlebensvorräte, um ein Fundament für einen Lagerplatz und ein einfaches Zelt zu errichten.\n\nWenn Ihr Euer Fundament verliert, dann errichtet mit Euren Überlebensvorräten ein neues und bringt die Materialien an den neuen Ort.", description = "Beim alten Lager gibt es noch etwas Holz, das nützlich sein könnte, und einen beeindruckenden Feuerstein. Wenn Ihr weitere Spuren von Estelenn finden oder auf ihre Rückkehr warten wollt, müsst Ihr Material einsammeln, um ein eigenes Lager aufzuschlagen, damit Ihr den kommenden Schneesturm überstehen könnt.\n\nIhr könnt den Sturm natürlich auch ganz vermeiden, indem Ihr die Hügel verlasst. Dann müsst Ihr allerdings zurückkommen und die nötigen Hinweise finden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[85030] = {title = "Uthers Grabmal", objective = "Nehmt das Blut des Lichtbringers und sprecht mit Hohepriester Thel'danis, um die Authentizität des Relikts zu bestimmen.", description = "Bevor wir überstürzte Behauptungen über die Authentizität der Probe machen, sollten wir zuerst feststellen, ob sie echt ist. Es wird gewiss nicht leicht sein, das mit Sicherheit zu sagen, doch möglicherweise erhalten wir ein paar Erkenntnisse, wenn wir die Probe zu Uthers Grabmal in den Westlichen Pestländern bringen. Sprecht dort mit dem ansässigen Priester, Thel'danis. Er ist ein gewissenhafter Gelehrter, was das Leben des Lichtbringers betrifft. Mit etwas Glück kann er die Authentizität der Probe feststellen.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil},
[85034] = {title = "Die Ruinen von Andorhal", objective = "Nehmt das Blut des Lichtbringers und erkundet Andorhal.", description = "Überreste wie die, die Ihr bei Euch tragt, haben oft geheimnisvolle Eigenschaften. Manche besonders mächtigen Relikte können sogar empfindsam wirken oder eine Persönlichkeit haben, insbesondere, wenn sie sich in der Nähe von Individuen und Orten befinden, denen sie im Leben eng verbunden waren.\n\nWenn das wirklich Uthers Blut ist, dann reagiert es möglicherweise in der Nähe des Ortes, an dem Uther starb. Erkundet die Stadt und seht, was passiert.", progress = "Habt Ihr Andorhal bereits erkundet? Hat das Blut auf irgendeine Weise reagiert?", completion = "Dann besteht kein Zweifel, das Blut ist echt. Was Ihr da habt, ist ein wahrer Schatz, &lt;Klasse&gt;. Passt auf Euch auf und beschützt es mit Eurem Leben.", rewards = nil},
[85061] = {title = "Käferjagd", objective = "Reist zur Burg Cenarius in Silithus auf Kalimdor und sprecht mit den Druiden dort über die Entwicklung der Silithiden. Helft ihnen wie verlangt, währen Ihr Eure Schießkünste trainiert.", description = "Ich bin Euren Spuren gefolgt und froh zu sehen, dass Ihr noch lebt! In den Überlebenskünsten seid Ihr wohl wirklich so versiert wie ich dachte. Entschuldigt, dass ich Euch warten ließ.\n\nIch habe weitere Hinweise auf unsere Beute gefunden. Van Amburgh ist irgendwo im Südwesten von Kalimdor. Ich werde dort weiter nach Spuren suchen. In der Zwischenzeit könntet Ihr Eure Schießkünste auffrischen.\n\nReist nach Silithus. Ihr könnt den Druiden der Burg Cenarius helfen, während Ihr Eure Trickschüsse übt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[85063] = {title = "Höhepunkt", objective = "Verteidigt Gregory, während er das Ritual abschließt, um die Echokugel der Mannoroc zu zerstören.", description = "Ich bin mir nicht sicher, was passiert, sobald wir das Ritual beginnen. Dieser Ort wimmelt nur so vor Dämonen und wenn sie unser Ritual entdecken, müssen wir uns vermutlich verteidigen. Ihr und Ada müsst Euch darum kümmern, während ich den Zauber kanalisiere. Doch bleibt in der Nähe, da Ihr selbst bedeutend für diese Magie seid.", progress = "Seid auf der Hut, <Klasse>!", completion = "Nein... nein. Das kann nicht sein! Wir waren so kurz davor!\n\nMeine Mission ist gescheitert. Azgaloth wurde befreit. Wir müssen uns wieder sammeln und unsere nächsten Schritte planen.", rewards = "Ihr bekommt:\n\nAdas Amulett"},
[85064] = {title = "Der schlimmste Fall", objective = "Reist nach Andorhal und findet Gregory, um herauszufinden, was als Nächstes zu tun ist.", description = "Es ist nun ein Rennen gegen die Zeit. Der Schreckenslord hat den Demonfall-Canyon erwähnt, die gute Nachricht ist also, dass wir wissen, wohin er geht. Die schlechte Nachricht ist, dass wir vermutlich Azgaloths Verbindung zu Azeroth gestärkt haben. Selbst wenn wir jetzt Azgaloth töten, würde er sich bald selbst manifestieren.\n\nIch habe eine Idee. Sie ist verzweifelt, aber sie ist unsere einzige Hoffnung. Es gibt jemanden in Andorhal mit besonderen Fähigkeiten, die uns möglicherweise weiterhelfen können, doch wir müssen erst ihr Vertrauen gewinnen.", progress = "Ihr habt es geschafft. Gut.", completion = "Das Reliquiar mit Uthers Blut war der Schlüssel für das Ritual, aber es ging während des Angriffs leider verloren. Wie ich schon sagte, geht es bei dieser Magie darum, Verbindungen aufzubauen und zu brechen. Wenn wir eine weitere Probe des Blutes finden könnten, könnten wir es gegen Azgaloths physische Form verwenden und ihn töten, um seine Seele ein für alle mal von Azeroth zu bannen.\n\nWie viel wisst Ihr über Bronzedrachen?", rewards = nil},
[85065] = {title = "Eine äußerst merkwürdige Gnomin", objective = "Sprecht mit Chromie in Andorhal und überzeugt sie, Euch zu helfen.", description = "Was wir zum Abschluss dieser Mission brauchen, existiert genau hier in Andorhal, auch wenn es gerade nicht hier ist.\n\nIm Raum hinter mir befindet sich eine \"Gnomin\" namens Chromie. Sie ist eine recht kuriose Kreatur, die dafür bekannt ist, eine ganz besondere Form der Drachenmagie zu verwenden. Und zwar Zeitmagie.\n\nWenn wir sie überzeugen können, ihre Magie zu verwenden, um uns zu helfen, können wir vermutlich in der Zeit zurückreisen und holen, was wir brauchen. Es ist riskant, doch es ist möglicherweise unsere einzige Option. Schaut, ob Ihr sie überzeugen könnt, uns zu helfen.", progress = nil, completion = "Schön, Euch wiederzusehen, &lt;Name&gt;! Zumindest meine ich, dass wir uns bereits begegnet sind. Das haben wir doch, oder? Es ist nicht gerade schwer, bei all den verschiedenen Versionen aller Personen durcheinanderzukommen, die ich so treffe... oder noch treffen werde.", rewards = nil},
[85066] = {title = "Vorbereitungen", objective = "Sprecht mit Gregory in Andorhal und bittet ihn, Euch zum Brand von Andorhal zu begleiten.", description = "Einfallende Dämonen und Todesrituale! Das klingt alles ziemlich gruselig. Glücklicherweise macht diese kleine Zeitblase, in der wir gerade stehen, es einfach, uns mit einem spezifischem Zeitpunkt zu verbinden.\n\nDoch das wird nicht gerade ungefährlich. Gebt mir Bescheid, sobald Ihr und Euer Freund bereit seid.", progress = nil, completion = "Dann passiert es wirklich... \n\nSo sehr es mir auch missfällt, muss ich doch gestehen, dass ich vermutlich nicht die beste Person bin, um Euch zurückzubegleiten. Mein Körper hat durch das heilige Feuer von Aeonas und den Dämonenangriff einfach zu viel Schaden genommen. In meinem aktuellen Zustand halte ich Euch eher zurück, als Euch eine Hilfe zu sein. Und nach dem Tod von Ada brauchen wir vermutlich Hilfe von außen.", rewards = nil},
[85067] = {title = "Ein Paladin der Silbernen Hand", objective = "Begebt Euch zu Uthers Grabmal und erklärt Aeonas die Situation.", description = "Ich habe gesagt, dass ich nicht ans Schicksal glaube, doch ich bin mir nicht ganz sicher, ob das ganz der Wahrheit entsprach. Meine Sichtweise hat sich so sehr verändert, seitdem mein sterbliches Leben sein Ende fand, doch je länger ich auf dieser Mission verbringe, desto mehr erkenne ich Muster und Verbindungen in Dingen. Ich glaube, Ihr wisst es bereits, doch es ist Aeonas, der mit Euch gehen muss.\n\nGlaubt mir, wenn ich Euch sage, dass ich nichts lieber tun würde, als meinem alten Freund seinen Frieden zu lassen, doch das ist größer, als es mir lieb ist. Begebt Euch zu Uthers Grabmal und erklärt die Situation.", progress = nil, completion = "&lt;Gregory nickt erst Euch und dann Aeonas zu.&gt;\n\nEs wird Zeit. Sprecht mit Chromie, sobald Ihr bereit seid, &lt;Name&gt;.", rewards = nil},
[85068] = {title = "Wer sagt, es gäbe keinen Weg zurück?", objective = "Nehmt das Portal zum Brand von Andorhal.", description = "Das Portal ist bereit.\n\nSobald Ihr eintretet, werdet Ihr zu Andorhal kurz nach dessen Fall transportiert. Damit Ihr nicht so herausstecht, habe ich ein paar magische Verkleidungen für Euch vorbereitet. Die sollten für die meisten Bewohner der Vergangenheit ausreichen, doch Ihr solltet dennoch vorsichtig vorgehen und versuchen, unbemerkt zu bleiben. Sobald Ihr habt, was Ihr braucht, müsst Ihr in der Vergangenheit nur noch an diesen Ort zurückkehren. Das Portal sollte dort auf Euch warten.", progress = nil, completion = "Wir haben es geschafft. Macht Euch auf alles gefasst, &lt;Name&gt;.", rewards = nil},
[85074] = {title = "Der Brand von Andorhal", objective = "Erreicht Euer Ziel und entkommt dem Brand von Andorhal.", description = "Ich bin mir nicht sicher, was uns dort drinnen erwartet, aber es wird nicht angenehm.\n\nWir müssen da rein, den Ort ausfindig machen, an dem Uther fiel, und ein paar Tropfen seines Blutes sammeln. Anschließend müssen wir uns einen Weg zurück zum Gasthaus auf der westlichen Seite der Stadt bahnen und entkommen. Wir sollten uns beeilen, doch wir müssen auch mit Respekt und Sorgfalt an die Sache herangehen, wie es meinem Lord Uther gebührt. Der Gedanke, ihn an dem Ort zu stören, an dem er sein Leben ließ, ist für mich zutiefst unangenehm.\n\nBringen wir das hinter uns.", progress = "So unappetitlich das auch war, wir haben das getan, weswegen wir hergekommen sind.", completion = "Ich vermute, dass wir nicht damit rechnen können, dass die Verkleidungen zurückkommen, daher bleibt uns wohl keine andere Wahl, als uns hier raus zu kämpfen. Macht Euch bereit, &lt;Name&gt;.", rewards = nil},
[85087] = {title = "Eine verzweifelte Flucht", objective = "Kämpft Euch einen Weg zum Gasthaus und entkommt zurück in Eure eigene Zeit. Wenn Ihr von Aeonas getrennt werdet, dann lasst das befleckte Horn ertönen, um ihn wieder an Eure Seite zu rufen.", description = "Die Untoten sind durchgebrochen und haben die Westseite der Stadt befallen. Das wird ein harter Kampf, <Name>. Die Zeit sitzt uns jetzt im Nacken, daher sollten wir die Gebiete mit den größten Zahlen der Geißel vermeiden.\n\nOh, fast hätte ich es vergessen, nehmt das. Wenn wir aus irgendeinem Grund voneinander getrennt werden, dann lasst dieses Horn ertönen. So sollte ich wieder zu Euch finden.", progress = "Es ist... nichts, nur ein Kratzer. Ich muss nur erst einmal zu...", completion = "&lt;Aeonas dämmert allmählich weg, als seine Augen sich plötzlich wieder öffnen und Euch anblicken.&gt;", rewards = nil},
[85090] = {title = "Zurück in die Zukunft", objective = "Nehmt das Portal zurück in Eure Zeit und übergebt den Wahrheitsbringer an Gregory.", description = "<Aeonas zuckt zusammen. Er ist schwer verletzt.> Ich glaube... weiter schaffe ich es nicht, <Name>. Es ist... okay. Das hier... war immer, wo ich hätte sein sollen. Ich bin froh, hier zu sein... mit meinen Freunden... am Ende.\n\nHier, nehmt das. Ich habe es geschmiedet... um mich zu erinnern. Um sicherzustellen, dass ich niemals die Freunde vergesse, die ich hier verlor, und dass ich ihnen stets treu bleibe... Wahrheitsbringer.\n\nTut mir den Gefallen und übergebt ihn Gregory. Vielleicht hilft er ihm dabei, sich daran zu erinnern, wer er ist. Euch ist es, denke ich, auch schon aufgefallen... er hat sich... verändert...\n\nIch...", progress = "Wo ist Aeonas? Was ist passiert?", completion = "Erzählt mir alles.", rewards = nil},
[85091] = {title = "Der Preis des Sieges", objective = "Weiht Eure Waffe mit dem Blut des Lichtbringers und besiegt Azgaloth im Demonfall-Canyon.", description = "Danke... dass Ihr mir das gebracht habt. Die Klinge ist geweiht und wird mir beim Führen beträchtlichen Schmerz zufügen, doch das ist ein kleines Opfer für... meinen Freund.\n\nWir können später trauern. Jetzt müssen wir all dem ein Ende setzen. Versammelt Eure treusten Verbündeten und begebt Euch zum Demonfall-Canyon. Azgaloth wird sich Euch möglicherweise nicht sofort offenbaren, aber wenn Ihr eine angemessene Herausforderung aussprecht, wird er antworten.\n\nNehmt das Blut und verwendet es, um Eure Waffe zu weihen und ihn zu vernichten. Für Aeonas und Ada. Es wird Zeit, das zu beenden.", progress = "...", completion = "Meine Mission ist endlich abgeschlossen.\n\nDas hat mich so lange beschäftigt, dass ich noch gar nicht richtig begriffen habe, was der Sieg wirklich bedeutet. Ich schätze, er bedeutet, dass unsere Allianz zu Ende geht und ich mich zurück auf den Weg nach Northrend machen sollte...\n\n&lt;Eine unangenehme Stille breitet sich zwischen Euch aus.&gt;", rewards = nil},
[85092] = {title = "Wahrheitsbringer", objective = "Verabschiedet Euch von Gregory.Aeonas hat dies schon lange vor mir realisiert. Er hat gesehen, wie ich mich auf dieser Mission verändert habe. Tatsächlich fühle ich... Traurigkeit, Reue... und wieder Liebe. Traurigkeit wegen Ada, Reue wegen meines Betrugs und Liebe für meinen Freund. Ich weiß nicht genau, was das bedeutet, aber ich weiß, dass ich nicht nach Northrend zurückgehen kann.\n\nVielleicht nach Lordaeron? Vielleicht gibt es dort andere wie mich. Andere, die sich vom Licht abgewendet haben... und langsam wieder ihren Weg zurück finden. Vielleicht kann ich ihnen helfen, wie mein Freund auch mir geholfen hat.", description = "Aeonas hat dies schon lange vor mir realisiert. Er hat gesehen, wie ich mich auf dieser Mission verändert habe. Tatsächlich fühle ich... Traurigkeit, Reue... und wieder Liebe. Traurigkeit wegen Ada, Reue wegen meines Betrugs und Liebe für meinen Freund. Ich weiß nicht genau, was das bedeutet, aber ich weiß, dass ich nicht nach Northrend zurückgehen kann.\n\nVielleicht nach Lordaeron? Vielleicht gibt es dort andere wie mich. Andere, die sich vom Licht abgewendet haben... und langsam wieder ihren Weg zurück finden. Vielleicht kann ich ihnen helfen, wie mein Freund auch mir geholfen hat.", progress = nil, completion = "Die Tatsache, dass ich keine Schmerzen mehr verspüre, wenn ich Wahrheitsbringer halte, verrät mir, dass ich alles über den Pfad weiß, den ich nun beschreiten muss.\n\nIch glaube allerdings, dass die Klinge bei Euch bleiben sollte. Aeonas würde das verstehen, und ich bin sicher, er würde das gutheißen. Der größte Teil meiner kämpferischen Tage liegt wohl hinter mir, und eine Waffe wie diese verdient es, im Dienste des Lichts eingesetzt zu werden.\n\nLebt wohl, &lt;Name&gt;. Möge das Licht mit Euch sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n[DNT] Cancel Aura\n\nIhr bekommt:\n\nWahrheitsbringer"},
[85112] = {title = "Die erschöpfte Sense", objective = "Bringt den Stab zu Doan Karhan im Brachland.", description = "Die Sense ist verdreht und strahlt eine dämonische Aura aus. Dennoch fühlt sie sich spröde an und Ihr habt Angst, dass sie bei Nutzung zerbrechen würde. Sie zerrt an Eurer Energie, als würde sie Euch auf die Probe stellen. Ein unbändiger Hunger regt sich tief in Euch, wenn Ihr nur an die Sense denkt. Vielleicht weiß jemand mit Kenntnissen über dämonische Artefakte mehr darüber.", progress = nil, completion = "Ihr habt da ein wirklich bemerkenswertes Artefakt gefunden, &lt;Name&gt;. Ich glaube, dass dieser Stab noch gerettet werden kann... aber das verlangt einiges an Arbeit. \n\nHmm, das könnte auch ein hervorragender Kandidat für ein paar offene Angelegenheiten sein, die wir noch erledigen müssen.", rewards = nil},
[85150] = {title = "Nur ein toter Käfer ist ein guter Käfer", objective = "Findet und besiegt 4 Silithidflitzer. Das sind schnelle, kleine Silithidwespen mit einem blauen Exoskelett.", description = "Die Silithiden verändern sich ständig, und aufeinanderfolgende Generationen nehmen neue Eigenschaften an, um ihre Überlebensfähigkeit zu verbessern. Wir haben nördlich von hier, in der Nähe des Baus des Ashischwarms, eine neue Art von Silithidfliegern entdeckt. Es sind Flieger, die einigen anderen Silithidwespen ähneln, aber sie sind kleiner, schneller und haben ein blaues Exoskelett.\n\nIch will wissen, ob von diesen Flitzern Gefahr ausgeht. Erledigt ein paar von ihnen und berichtet, wie stark sie sind.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[85248] = {title = "Jeder weiß, dass Käfer nicht fliegen können", objective = "Kämpft gegen einen Silithidflitzer, bis er geschwächt ist, setzt dann Eure Fähigkeit 'Erschütternder Schuss' ein, um ihn zu verlangsamen. Sollte er in Raserei verfallen, macht ihn mit 'Einlullender Schuss' bewusstlos. Fesselt ihn, schleppt ihn zur Burg Cenarius zurück und sichert ihn für weitere Untersuchungen am Anbindepfosten vor dem Kriegsraum von Kommandant Mar'alith.\n\nKehrt zu Kommandant Mar'alith in der Burg Cenarius zurück, wenn Ihr fertig seid.\n\nIhr erlernt 'Einlullender Schuss' während des Schlachtzugs im Geschmolzenen Kern.", description = "Aus Euren Berichten geht hervor, dass die Flitzer definitiv schneller sind, aber wir müssen mehr über sie wissen. Wenn wir einen studieren können, finden wir vielleicht heraus, wie wir sie effektiver neutralisieren können.\n\nMit Euren Jagdfähigkeiten sollte es möglich sein, einen der Flitzer kampfunfähig zu machen und ihn hierher zurückzubringen, damit wir mehr über ihn erfahren können. Spürt einen auf, verwundet ihn, fesselt ihn und bringt ihn hierher in den Käfig, den wir für Studienzwecke aufgestellt haben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[85250] = {title = "Begegnung mit der Menagerie", objective = "Reist zum Krater von Un'Goro im Süden von Kalimdor und sucht dort nach Hinweisen zu Van Amburgh.", description = "Während Ihr unterwegs wart, hat uns ein Irrwisch besucht und nach Euch gesucht. Der Irrwisch gab an, dass Ihr im Krater von Un'Goro gebraucht werdet. Der Irrwisch sagte, dass einer Eurer Gefährten den Aufenthaltsort eines Feindes entdeckt hat, den Ihr schon seit einiger Zeit verfolgt.\n\nNochmals vielen Dank für Eure Hilfe hier. Wie es scheint, ist es für Euch an der Zeit, weiterzuziehen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[85251] = {title = "Entscheidungskampf im Krater von Un'Goro", objective = "Reist zum Lager von Van Amburgh im Un'Goro-Krater im Süden von Kalimdor und besiegt den Zwerg und seine Menagerie.", description = "Endlich ist es so weit. Es hat mich alles gekostet, das Lager von Van Amburgh hier zu finden. Zudem war ich noch durch eine seiner Fallen verwundet. Er hat seine Bestien bei sich. Seid Ihr bereit, dies zu beenden?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[85304] = {title = "Essenz des Feuers", objective = "Findet heraus, was es mit der ungewöhnlichen Schriftrolle auf sich hat, und teilt Eure Erkenntnisse mit einem Bibliothekar in Stormwind oder Undercity.", description = "Die Schriftrolle strahlt ungleich allen anderen, die Ihr gefunden habt, eine feurige Energie aus. In der Nähe von Draco'dar in der Brennenden Steppe gibt es einen magischen Stein, der den Zweck der Schriftrolle offenbaren könnte. Übersetzt die Rolle und erlernt ihren Zweck, bevor Ihr Eure Erkenntnisse den Bibliothekaren von Stormwind oder Undercity mitteilt.", progress = nil, completion = "Da habt Ihr etwas wirklich Interessantes gefunden, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"},
[85385] = {title = "Der Lehrling des Bibliothekars", objective = "Sprecht mit Valxx Cracklequil in der Ewigen Warte, um mehr über die Gerüchte zu erfahren.", description = "Eure Entdeckung der Essenz des Feuers hat unser Wissen über das Arkane stark erweitert. Ich habe Gerüchte über eine ähnliche Macht in Winterspring gehört, allerdings ist sie von frostiger Natur. Mein Partner in der Ewigen Warte wird mehr Informationen darüber haben.", progress = nil, completion = "Die alten Käuze aus der Bibliothek haben Euch also geschickt, was? Sie mögen mich nicht besonders. Sie behaupten, dass Schießpulver und Magie nicht zusammenpassen. Pah. \n\nJa, ich weiß ein oder andere über das, wonach Ihr fragt. Glücklicherweise bin ich zu beschäftigt, um mich selbst darum zu kümmern.", rewards = "Ihr bekommt:\n\n"},
[85386] = {title = "Essenz des Frosts", objective = "Untersucht die Frosthauchschlucht nach einer mysteriösen Frostmacht.", description = "Vor einiger Zeit hörte ich von seltsamen Vorgängen in der Frosthauchschlucht. Es scheint, als hätten diese Eisriesen eine alte Macht gefunden. Ich würde selbst nachforschen, aber ich bin hier zu beschäftigt. Bringt mir alles Interessante mit, ja? Das heißt, falls Ihr lebendig zurückkehrt.", progress = nil, completion = "Was ist denn das? Da unten war tatsächlich etwas?! Ich bin überrascht, dass diese Eisriesen Euch nicht in einen Eiszapfen verwandelt haben, &lt;Name&gt;. Gut gemacht.", rewards = "Ihr bekommt:\n\n"},
[85388] = {title = "Eine schändliche Störung", objective = "Gebietet der Verderbnis in Mazthoril Einhalt.", description = "Während Eurer Abwesenheit habe ich gehört, dass drüben in Mazthoril etwas Übles vor sich geht. Das scheint Euer Ding zu sein, also seht zu, was Ihr tun könnt, um es zu lösen. Diese blauen Drachen kennen sich gut mit dem Arkanen aus, vielleicht geben sie Euch ja etwas dafür.", progress = "Ihr seid noch nicht tot? Interessant.", completion = "Ihr habt mir sehr geholfen, &lt;Name&gt;. Auch wenn ich fürchte, dass es im Vergleich zu den Heldentaten, die Ihr für uns vollbracht habt, verblasst, möchte ich Euch dies geben. Dieser Stab ist unvollständig, kann aber vielleicht wiederhergestellt werden.", rewards = "Ihr bekommt:\n\nUnvollständiger Stab der Ordnung"},
[85401] = {title = "Das eisige Grab", objective = "Findet Nandieb im Grabhügel in der Nähe von Starfall in Winterspring und bergt seinen Stab. Ihr müsst dies alleine erledigen.", description = "Genau wie Leben aus dem Verfall entspringt, so mag auch das Unnatürliche dem Natürlichen dienen können.\n\nDas Herz kann in einem Stab von wechselnder Gestalt umgewandelt werden, aber ich brauche ein Gefäß, das stark genug ist, seine Macht aufzunehmen.\n\nEs gibt in Winterspring in der Nähe von Starfall einen Grabhügel. Der echte Eingang offenbart sich nur, wenn Ihr alleine seid.\n\nDarin befindet sich ein Bewahrer, der vor langer Zeit vom Weg abgekommen ist: Nandieb. Sein Stab soll das Gefäß für das Herz werden. Es schmerzt mich, dies vorzuschlagen, aber er ist nicht mehr der große Bewahrer, den ich einst kannte.", progress = "Habt Ihr den Stab bekommen?", completion = "Das chromatische Herz und Nandiebs Stab: Zusammen bilden sie die wechselnden Stäbe Gla'sir und Rae'lar. Zwei Objekte der Bösartigkeit und der Zerstörung, transformiert für den Dienst an Schöpfung und Leben.\n\nIch verleihe Euch diese Macht, &lt;Name&gt;, in der Hoffnung, dass Ihr Euch weiterhin als ehrenhafte Verwalterin allen Lebens auf Azeroth erweist.", rewards = "Ihr bekommt:\n\nGla'sir"},
[85441] = {title = "Donneraan der Windsucher", objective = "Um die Macht des Windsuchers zu nutzen, müsst Ihr Hochlord Demitrian im Kristalltal die rechten und linken Hälften der Fesseln des Windsuchers, 10 Elementiumbarren und die Essenz des Feuerfürsten bringen.", description = "Ich habe Euch alles gesagt, was ich weiß, <Name>. Es ist nun Eure Aufgabe Elementium zu finden. Ihr seid es, der die körperliche Form des Feuerfürsten zerstören muss.\n\nGewinnt dadurch den Segen von Donneraan.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[85442] = {title = "Untersuchung des Gefäßes", objective = "Untersucht das Gefäß der Wiedergeburt und bringt es zu Hochlord Demitrian.", description = "Untersucht das Gefäß, mit dem der flüchtige Sturm ausgelöst wurde. Aus diesem wurde der Windsucher wiedergeboren, der nun neue Kraft aus dem Kristalltal schöpft.", progress = nil, completion = nil, rewards = nil},
[85443] = {title = "Donnerzorn erwache!", objective = "Präsentiert Hochlord Demitrian die schlummernde vom Wind berührte Klinge.", description = "Ihr habt den Windsucher bezwungen. Nehmt die schlummernde Klinge und zwingt den Anhänger, Demitrian, die Materialien einzusetzen, um Donnerzorn zu erwecken.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nDonnerzorn, gesegnete Klinge des Windsuchers"},
[85445] = {title = "Die goldene Scheibe", objective = "Findet jemanden, der Euch etwas zur schimmernden goldenen Scheibe erzählen kann.", description = "Ihr habt keine Ahnung, was dieser Gegenstand sein könnte, aber es ist eindeutig ein Artefakt von großer Macht. Ihr solltet jemanden finden, der Euch mehr über dieses Artefakt und seinen wahren Zweck sagen kann.", progress = "Bitte beeilt Euch, <Name>.", completion = "Wartet, was habt Ihr da? Das sieht aus wie... Nein, das kann nicht sein. Ich habe es nur in Büchern gesehen, aber... es wurde zerstört. Das ist doch nicht...\n\n&lt;Gareks Fixierung auf den Gegenstand an Eurem Gürtel wird kurz unterbrochen und seine Augen treffen die Euren.&gt;\n\nWoher habt Ihr diesen Gegenstand, &lt;Klasse&gt;? Bitte, erzählt mir alle Details!", rewards = nil},
[85446] = {title = "Schuppe des Drachenlords", objective = "Sprecht mit Riosus und entwerft einen Plan, wie Ihr das Simulakrum der Drachenseele loswerden könnt.", description = "<Riosus lauscht, während Ihr Eure Geschichte erzählt.>\n\nJa, Garek hatte Recht, dies ist nicht die wahre Drachenseele... und den Titanen sei Dank. Hielte <ein minderbemittelter Sterblicher/eine minderbemittelte Sterbliche> wie Ihr ein so mächtiges Artefakt in Händen, wäre ich kaum zuversichtlicher als hätte es der Herrscher des Blackrock selbst. Trotzdem ist es gefährlich, und wir sollten uns um seine Beseitigung kümmern. Die ursprüngliche Drachenseele war nicht leicht zu zerstören. Kommt, lasst uns über die Möglichkeiten zur Beseitigung dieses geringeren Simulakrums sprechen.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil},
[85447] = {title = "Grim Batol", objective = "Bringt das Simulakrum der Drachenseele zum Anführer der Drachenschar in der Nähe des Eingangs zur Festung von Grim Batol.", description = "Nefarian experimentiert schon lange mit den fünf Drachenschwärmen, und es scheint, dass dieses 'Simulakrum' der Drachenseele ein solches Experiment war. Ich erschaudere bei dem Gedanken, was passieren könnte, wenn es ihm gelingt, auch nur einen Bruchteil der Macht der wahren Drachenseele zu emulieren. Bitte, sucht Agenten der roten Drachen in der Nähe der Ruinen von Grim Batol auf. \n\nIch werde das Simulakrum verzaubern, um Euch als Freund des roten Schwarms zu kennzeichnen.", progress = "Wer bist du, und wie kannst du es wagen, vor mich zu treten, Sterblicher?", completion = "Ihr tragt das Zeichen eines Agenten von Korialstrasz, aber als Fremder habe ich dennoch keine andere Wahl, als Euch zu misstrauen, Sterblicher. Ob mit oder ohne Zeichen, ich rate Euch, vorsichtig zu sein, damit ich Euch nicht von meinen Drachkin rösten und verschlingen lasse.", rewards = nil},
[85453] = {title = "Keine gute Tat bleibt unbestraft", objective = "Verteidigt Euch gegen Riosustrasz!", description = "Und damit, fürchte ich, habt Ihr Eure Nützlichkeit verloren. Aber keine Sorge, ich würde nicht davon träumen, Eure Dienste unbelohnt zu lassen. Lasst mich Euch die Ehre erweisen, von meiner wahren Gestalt verschlungen zu werden. Das ist wahrhaftig eine Ehre, <Klasse>.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil},
[85454] = {title = "Eine faire Belohnung", objective = "Sprecht mit Krasus, um das Simulakrum der Drachenseele zu zerstören und Eure Belohnung zu erhalten.", description = "Ihr habt viel getan, um unsere Brut zu verteidigen, <Klasse>. Es scheint mir passend, Euch mit einem Geschenk zu entlohnen, mit dem Ihr auch in Zukunft andere verteidigen könnt. Sprecht mit mir, sobald Ihr bereit seid, dann zerstören wir diese falsche Drachenseele gemeinsam. Ich glaube, dass ich mir einen Teil der Energie, die freigesetzt wird, während die Magie des Simulakrums sich verflüchtigt, zunutze machen kann, um zusammen mit einem Teil meiner eigenen Magie etwas Besonderes für Euch zu schaffen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSuzerain, Verteidiger der Drachenschwärme"},
[85455] = {title = "Das Blut des Lichtbringers", objective = "Findet jemanden, der Euch mehr über das Blut des Lichtbringers erzählen kann. \n\n(Hinweis: Zunächst muss die Quest \"Pestlandtreffen\" abgeschlossen werden, damit diese Quest abgegeben werden kann.)", description = "Eure Hand zittert leicht, während Ihr die kleine Phiole mit Blut haltet. Abgesehen von der Inschrift auf dem Etikett, könnt Ihr eine Wärme und Energie spüren, die von der Probe ausgestrahlt wird. Könnte das wirklich das Blut Uthers des Lichtbringers, des legendären Helden, sein? Ihr solltet jemanden finden, der die Authentizität dieser Probe bestätigen kann.", progress = "Friede sei mit Euch, <Klasse>.", completion = "Wartet, was habt Ihr da?\n\n&lt;Die Augen von Hohepriester Thel'danis weiten sich, während er das Reliquiar untersucht.&gt;\n\nDas kann doch nicht sein, oder? Wie sollten die schwarzen Drachen an eine Probe von Lord Uthers Blut gelangen?\n\nWenn sie sich als echt herausstellen sollte, wäre das ein Relikt unfassbarer Bedeutung. Lasst uns mehr darüber sprechen.", rewards = nil},
[85457] = {title = "Genau das Richtige", objective = "Bringt das Blut des Lichtbringers zu Gregory nach Caer Darrow in den Westlichen Pestländern.", description = "Ich sehe schon, Ihr wollt das Blut zu Gregory bringen. Gut. Mein Urteil war bestenfalls fragwürdig und es war schon immer das Spiel eines jüngeren Paladins, auf das ich mich eingelassen habe.\n\nIch bin mir nach wie vor nicht sicher, wie ich mich fühlen soll, aber ich bin auf jeden Fall froh, zu sehen, dass Ihr zu dem Paladin herangewachsen seid, der Ihr schon immer sein solltet.", progress = "Ja, <Name>?", completion = "Ich hatte nicht erwartet, Euch hier wiederzusehen, zumindest nicht so schnell. Was gibt es?", rewards = nil},
[85458] = {title = "Die Flüsternde Schlucht", objective = "Trefft Gregory in der Flüsternden Schlucht in Winterspring.", description = "Das ist... unglaublich. Ich bin viel zu pragmatisch, um an Schicksal zu glauben, doch das ist durchaus mal eine glückliche Wende des Schicksals. Damit sollten wir alles haben, was wir zur Vervollständigung des Rituals und endgültigen Vernichtung der Kugel benötigen. Doch wie bei jedem guten Ritual, kommt es auf den Ort an. Sagt Euch die Flüsternde Schlucht in Winterspring etwas? Das ist ein verfluchter, dämonenverseuchter Ort, doch genau dort müssen wir das zu Ende führen.\n\nIch schnappe mir die Kugel und die verbleibenden Materialien und treffe Euch dort. Meine Mission hat bald ein Ende!", progress = "Ihr habt es geschafft, gut. Seid auf der Hut, <Name>.", completion = "Ich weiß, dass das etwas abseits des Weges ist, doch wir brauchen einen Ort, wo die Barriere zwischen unserer Realität und dem Nether dünn ist und eine hohe Konzentration an latenter Arkanenergie vorliegt. Wir haben uns für den Teufelswald aufgrund seiner Nähe zum Hyjal entschieden. Bei diesem Ritual werde ich nichts dem Zufall überlassen und ich wollte so nah wie möglich an den inaktiven Brunnen der Ewigkeit kommen wie möglich.\n\nIch sehe schon, dass dies der perfekte Ort ist. Ich kann die Energie in der Luft förmlich spüren. Kommt, lasst uns beginnen.", rewards = nil},
[85468] = {title = "Seele des Unheils", objective = "Überzeugt Xirath in der Nähe von Northdale in den Östlichen Pestländern, Euch dabei zu helfen, eine Seele des Unheils zu erhalten und sie auf die erschöpfte Sense des Chaos anzuwenden.", description = "Wenn ich mir die seltsame Sense anschaue, die Ihr mitgebracht habt, glaube ich, dass wir sie mit Seelen füllen müssen, um sie wiederherzustellen. Fangen wir mit Wichteln an. Ich habe einen Kollegen in den Östlichen Pestländern, in der Nähe von Northdale, der Euch helfen können sollte. Erwähnt meinen Namen, dann sollte er etwas empfänglicher sein. Ich treffe Euch in der Kapelle des hoffnungsvollen Lichts, sobald Ihr fertig seid.", progress = nil, completion = "Großartige Arbeit, &lt;Name&gt;, die Sense scheint wieder an Kraft zu gewinnen. Oh, Xirath? Eine Schande, dass er uns am Ende hintergangen hat. Dann muss ich wohl einen neuen Kollegen finden. Versuchen wir beim nächsten Mal, die Macht der Seele zu steigern.", rewards = nil},
[85480] = {title = "Prokrastimunds Dankbarkeit", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nCassandras Foliant"},
[85485] = {title = "Seele der Leere", objective = "Findet den Leerwandler in der Nähe von Corins Kreuzung in den Östlichen Pestländern und fügt seine Seele der Sense hinzu.", description = "Die Sense kommt schön voran. Die nächste Seele, die Ihr hinzufügen solltet, ist die eines Leerwandlers. Ich kenne da einen, der besonders mächtig ist und der noch verweilt, obwohl sein Meister in der Nähe gestorben ist. Der sollte eine gute Ergänzung sein.", progress = nil, completion = "Exzellent, &lt;Name&gt;. Seid Ihr für die nächste Phase in der Wiederherstellung der Sense bereit?", rewards = nil},
[85486] = {title = "Seele der Betörung", objective = "Verwendet eine leuchtende Schriftrolle der räumlichen Heilung an einem großen Teufelsriss, um einen teuflischen Eindringling zu beschwören und seine Seele zu erhalten.", description = "Eure nächste Aufgabe ist deutlich kniffliger und dreht sich um diese Teufelsportale, die hier immer wieder auftauchen. Ich habe gehört, dass sie mächtige teuflische Eindringlinge beschwören, wenn Magier besondere Schriftrollen einsetzen. Die Geißel im Pestwald scheint etwas Ähnliches vorzuhaben. Verwendet den Dämon, den sie beschwören wollen, auf dieselbe Art für den Seelensplitter.", progress = nil, completion = "Ihr habt wirklich alle Erwartungen übertroffen, &lt;Name&gt;. Nur noch eine Seele, dann sollte die Sense für ihren finalen Test bereit sein.", rewards = nil},
[85501] = {title = "Das Herz von Chromaggus", objective = "Findet jemanden, der die Macht des chromatischen Herzens versteht.", description = "Das Herz des einst furchteinflößenden Chromaggus ruht in Euren Händen. Die kaleidoskopischen Farben sind so exquisit wie grotesk. Ihr spürt eine große Macht im Inneren des Herzens. Etwas, dass sich Eurem Verständnis entzieht. Um mehr zu erfahren, bedarf es der Hilfe von jemandem, der deutlich mächtiger und älter ist als Ihr.", progress = "Was habt Ihr mir da gebracht, Kleine?", completion = "Dieses Herz ist eine schreckliche Anomalität. Wie auch immer, seine Macht könnte möglicherweise reformiert werden, um besseren Zwecken zu dienen.", rewards = "Ihr bekommt:\n\n"},
[85505] = {title = "Seele des Verzehrens", objective = "Findet die Magier in der Nähe des Blackwoodsees und lasst sie Zauber auf Euch wirken, bis der Teufelshund erscheint.", description = "Diese Seele sollte interessant sein. Während Ihr weg wart, ist mir zu Ohren gekommen, dass ein streunender Teufelshund einigen Magiern in der Nähe des Blackwoodsees aufgelauert ist. Nehmt diesen besonderen Seelensplitter. Er sollte die Effekte der arkanen Magie verstärken, die auf Euch gewirkt wird. Der Teufelshund wird dem nicht widerstehen können.", progress = nil, completion = nil, rewards = nil},
[85506] = {title = "Die letzte Prüfung", objective = "Erhaltet die Seele von Des'Altek im Demonfall-Canyon und verwendet sie, um die Wiederherstellung der Sense abzuschließen.", description = "Ich werde Euch nun meine wahren Absichten offenbaren, <Name>. Ich glaube, dass diese Sense dabei helfen kann, Des'Altek ein für alle Mal ein Ende zu setzen. Trefft mich beim Demonfall-Canyon in Ashenvale, dann können wir ihn als die finale Seele nutzen, die wir brauchen, um der Sense wieder ihre volle Macht zu verleihen.", progress = nil, completion = nil, rewards = nil},
[85507] = {title = "Unser verlorener Freund", objective = "Findet Aeonas in der Nähe von Sorrow Hill in den Westlichen Pestländern.", description = "Ich bin froh, dass Ihr hier seid, <Name>. Uns wurde mitgeteilt, dass in der Nähe des Zugwindlagers ein Reisender gesehen wurde, der auf die Beschreibung Eures Freundes Aeonas passt. Er soll sich in Richtung Trauerhügel begeben haben.\n\nNach allem, was sich im Teufelswald zugetragen hat, wollte ich ihm etwas Freiraum lassen, doch es gibt noch Leute im Orden, die ihm nach wie vor nicht trauen. Und irgendwann muss er aus der Kälte zurückkehren und erklären, warum er seinen anhaltenden Kontakt zu einem bekannten Agenten des Lichkönigs verschwiegen hat. Geht und findet ihn. Vielleicht könnt Ihr ihn ja überzeugen, zurückzukommen.", progress = nil, completion = "Ich hatte das Gefühl, dass Ihr früher oder später auftauchen würdet. Tut mir leid, Euch enttäuschen zu müssen, doch es ist für mich noch nicht an der Zeit, zurückzukehren. Das ist der beste Teil daran, ein \"ehemaliges\" Mitglied der Silbernen Hand zu sein. Ich bin gegenüber niemandem im Orden mehr Rechenschaft schuldig.\n\nAn einem gewissen Punkt werde ich zurückkehren, aber für den Moment könnt Ihr Katharina bitte sagen, dass ich Ihr Gesuch vernommen habe, aber einfach noch nicht bereit bin.", rewards = nil},
[85508] = {title = "Unser verlorener Freund", objective = "Sprecht mit Aeonas, bevor Ihr nach Stormwind zurückkehrt, um Katharina seine Antwort zu übermitteln.", description = "Ihr seht aus, als wärt ihr richtig stark geworden, seit wir uns das letzte Mal gesehen haben. Das freut mich wirklich. Wenn es etwas gibt, dass ich in meinem Leben richtig gemacht habe, dann, Euch im Teufelswald das Leben zu retten. Und das gibt mir Trost.\n\nEgal, Ihr solltet jetzt besser wieder zu Katharina zurückkehren, oder gibt es noch etwas anderes, das Ihr mich fragen wolltet?", progress = nil, completion = "&lt;Name&gt;, dem Licht sei Dank, dass Ihr hier seid! Die Kammer wurde gerade überfallen und die Echokugel der Mannoroc entwendet!", rewards = nil},
[85509] = {title = "Sondereinsatz Echokugel", objective = "Sprecht mit Faranister dem Kammerhüter im Kanaldistrikt von Stormwind und kehrt anschließend zu Katharina zurück, sobald Ihr so viel wie möglich in Erfahrung gebracht habt.", description = "Begebt Euch bitte zum südöstlichen Bereich des Kanals und sprecht mit dem dortigen Kammerhüter, Julien Faranister. Er kann Euch erzählen, was er weiß. Bringt über das Verbrechen so viel wie möglich in Erfahrung. Es gibt viele Leute, die an der Kugel Interesse haben, daher ist es umso wichtiger, jetzt so viele Indizien wie möglich zu sammeln, solange der Tatort noch frisch ist.", progress = "Warum sprecht Ihr mit mir, <Name>! Geht so schnell wie möglich zum Kammerhüter.", completion = "Das ist nicht gerade viel, aber immer noch besser als nichts, schätze ich.\n\nIch würde gerne hören, was Ihr während Eures Treffens mit Aeonas in Erfahrung bringen konnten, aber ich fürchte, dass dieses Anliegen gerade Priorität hat. Sprechen wir über unseren aktuellen Anhaltspunkt.", rewards = nil},
[85510] = {title = "Eine mögliche Spur", objective = "Erkundet einige der weniger ruhmreichen Teile Stormwinds und sucht dort nach Informationen dazu, wer möglicherweise geplant hatte, die Kammer auszurauben.", description = "Das ist zweifelsohne ein Medaillon der Brennenden Klinge, was auf eine Beteiligung des Kults der Legion hindeutet. Was den Start Eurer Untersuchung betrifft... vielleicht solltet Ihr den Tavernen in der Stadt einen Besuch abstatten und versuchen, den verruchteren Gästen einige Informationen zu entlocken. \n\nEs ist nicht viel, aber einen Anfang ist es wert.", progress = nil, completion = "Ihr seht wie jemand aus, der gerade etwas verloren hat...\n\nIch hatte bereits vermutet, dass Ihr hier früher oder später auftauchen würdet, um danach zu suchen. Ihr habt es schneller hergeschafft, als ich vermutet hätte. Hut ab.", rewards = nil},
[85511] = {title = "Pestlandtreffen", objective = "Sucht Ada Dunkelhardt in Caer Darrow in den Westlichen Pestländern.", description = "Natürlich habe ich damit gerechnet, dass Ihr mich hier findet. Was dachtet Ihr denn, weshalb ich Euch all die Kultistenleichen in der Kammer hinterlassen habe?\n\nBevor Ihr Euch zu sehr aufregt: Ja, die Kugel ist sicher. Allem Anschein nach sogar sicherer als diese Stadt. Wäre ich nur etwas später in die Kammer gekommen, wäre die Kugel bereits längst weg gewesen.\n\nIch habe bereits genug gesagt und diese Taverne hat zu viele Ohren. Trefft mich auf der Insel Caer Darrow in den Westlichen Pestländern. Dort sollt Ihr Eure Antworten bekommen.", progress = nil, completion = "Ich kann spüren, dass das Ende bevorsteht. Hoffentlich können wir einen angemessenen Ersatz für Euer Blut finden und diese Angelegenheit ein für alle Mal hinter uns lassen.\n\nSo oder so, Ihr habt den langen Weg auf Euch genommen und nicht versucht, mich umzubringen. Das weiß ich wirklich zu schätzen. Hier, nehmt das hier als Zeichen meiner Dankbarkeit an. Es ist nicht viel, aber es hat mir gute Dienste erwiesen... in einem anderen Leben zumindest. Hoffentlich kann es auch Euch eine Hilfe sein.", rewards = nil},
[85521] = {title = "Dem Fallensteller auf der Spur", objective = "Findet das verlassene Lager an der westlichen Seite der Brennenden Steppe, südlich der Straße zum Altar der Stürme, und untersucht das Gebiet.", description = "Die Notiz, die Ihr gefunden habt, scheint ein Beleg für die Unterdrückungsfallen zu sein, die sich um das Lager von Brutwächter Dreschbringer befinden. Die Notiz beschreibt, dass wenn der Brutwächter mehr Unterdrückungsfallen braucht, er sie vom Lager des Verkäufers kaufen kann, das sich in der Nähe der westlichen Seite der Brennende Steppe südlich der Straße zum Altar der Stürme befindet. In der Notiz steht auch, dass der Verkäufer bald weiterzieht, weshalb der Brutwächter sich beeilen sollte, wenn er mehr Fallen braucht.", progress = "Das verlassene Lager sollte einige Hinweise bieten.", completion = "Vielleicht können wir zusammenarbeiten. Ich gehe gerade noch ein paar anderen Spuren nach, doch wir können unsere Aufzeichnungen miteinander teilen, um diesen Verbrecher gegen die Natur aufzuhalten, bevor er noch mehr Schaden verursacht.", rewards = "Ihr bekommt:\n\n"},
[85525] = {title = "Eine Nacht in Winterspring", objective = "Sammelt Bärenfleisch, warmes Fell und trockenes Holz. Bringt die Materialen zu Eurem Lager, um einen Unterschlupft zu bauen, damit Ihr den Sturm überstehen könnt.\n\nWenn Ihr das Fundament verliert, errichtet Ihr mit Euren Überlebensvorräten ein neues und bringt die Materialien dorthin.", description = "Ein Zelt allein wird nicht genug sein, um eine stürmische Nacht in Winterspring zu überleben. Ihr braucht Essen, Felle und Feuer, um Euch warm zu halten, sonst friert Ihr noch zu Tode. Glücklicherweise bietet Euch die Natur alles, was Ihr braucht, und Ihr könnt das alles hier finden.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLagerplatzzubehör erschaffen\n\nIhr bekommt:\n\n"},
[85555] = {title = "Schwermetall", objective = "Findet jemanden, der exotische Metalle verarbeiten kann und bereit ist, Euch zu helfen, etwas Besonderes aus diesem Elementiumklumpen herzustellen.", description = "Die große flache Scheibe aus Elementium, die Ihr in den Händen haltet, scheint vor elementarer Energie zu brummen. Ihr könnt schon fast hören, wie die Elementargeister Euch etwas zuflüstern. Ihr seid nicht sicher, was Ihr damit anstellen sollt, aber die Verbindung, die Ihr spürt, ist unmittelbar vorhanden.\n\nWenn sich ein ausreichend talentierter Schmied, der sich mit diesem mysteriösen, als Elementium bekannten Metall auskennt, ein wenig damit beschäftigt, könnte eine Waffe oder ein Rüstungsteil daraus entstehen. Das vermutet Ihr zumindest.", progress = nil, completion = nil, rewards = nil},
[85556] = {title = "Eine besondere Sammlung an Fertigkeiten", objective = "Findet einen Weg, um in den Pechschwingenhort zu gelangen und mit Meisterelementarformer Krixix zu sprechen, ohne ihn in einen Kampf zu verwickeln.", description = "Krixix ist sicherlich ein Genie, aber möglicherweise ist er nicht allzu freundlich gestimmt, wenn Ihr einfach in den Berg stürmt und nach seiner Hilfe verlangt. Ganz zu schweigen von den Schlägern, von denen es da vermutlich wimmelt. Ihr solltet versuchen, einen Weg zu finden, wie Ihr zu ihm gelangt, ohne alles unterwegs abzufackeln, was wahrscheinlich ziemlich knifflig werden könnte.\n\nWenn Ihr einen Weg da rein finden könnt, ohne unterwegs Leute zu erstechen, zu verbrennen oder sonst wie zu erledigen, ist das wahrscheinlich schon ein guter Anfang. Ich selbst habe keine gute Idee, wie das funktionieren soll, also viel Glück dabei!", progress = nil, completion = nil, rewards = nil},
[85557] = {title = "Effizienz hat oberste Priorität", objective = "Findet eine geeignete Energiequelle, um die Elementiumschmiede von Meisterelementarformer Krixix effizienter zu machen.", description = "Tatsächlich ist mir da gerade eine Idee gekommen. Seht mal, das größte Problem bei der Verarbeitung von Elementium besteht darin, die Schmiede heiß genug zu halten. Wenn ich etwas hätte, womit ich das Feuer länger bei voller Stärke halten könnte, müsste ich nicht so viel Zeit damit verschwenden, es zu schüren.\n\nWenn Ihr mir ein magisches Mittelchen bringt, das meine Schmiede heiß hält, könnte ich mich ein wenig für etwas nebenher freimachen, wie für Euren kleinen Auftrag. Jetzt verschwindet. Seht zu, was Ihr für mich auftreiben könnt.", progress = nil, completion = nil, rewards = nil},
[85558] = {title = "Qualität ist eine Verpflichtung", objective = "Seht zu, wie Meisterelementarformer Krixix Euren Gegenstand herstellt.", description = "Ich habe darüber nachgedacht, was wir mit diesem Klumpen Metall anfangen sollen, und ich glaube, ich habe genau die richtige Idee. Gebt mir ein paar Minuten, dann dengel ich das für Euch zusammen.", progress = nil, completion = "Da ist sie. Ist sie nicht eine Schönheit? Lasst Euch nicht davon täuschen, wie lange ich gebraucht habe, das hier zusammenzuhauen. Ich lasse es nur einfach aussehen. Ich versichere Euch, das ist ein Meisterstück.\n\nIch denke sogar, dass dies meine beste Arbeit sein könnte. Natürlich ist alles, was ich mache, meine beste Arbeit. Nun, was für eine lustige kleine Ablenkung, aber jetzt muss ich wieder an die Arbeit. Wir sehen uns.", rewards = "Ihr bekommt:\n\nTerrestris"},
[85559] = {title = "Einbruch der Nacht", objective = "Begleitet Estelenn und seht Euch an, was sie Euch zeigen möchte.", description = "Wenn Ihr mich bitte begleitet? Ich muss Euch noch eine letzte Sache zeigen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTurmfalkeWanderfalke"},
[85595] = {title = "Präsenz der Macht", objective = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", description = nil, progress = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", completion = "Nutzt es weise, &lt;Klasse&gt;. Zeigt keine Gnade mit den Hakkari!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPräsenz der MachtPräsenz der Tapferkeit"},
[85596] = {title = "Umarmung des Todes", objective = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", description = nil, progress = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", completion = "Nutzt es weise, &lt;Klasse&gt;. Zeigt keine Gnade mit den Hakkari!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVorstoß des TodesUmarmung des Todes"},
