[85600] = {title = "Allgegenwärtige Sicht", objective = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", description = nil, progress = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", completion = "Nutzt es weise, &lt;Klasse&gt;. Zeigt keine Gnade mit den Hakkari!", rewards = "Ihr bekommt:\n\nAllgegenwärtige Sicht"},
[85601] = {title = "Siegelzeichen des Synkretisten", objective = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", description = nil, progress = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", completion = "Nutzt es weise, &lt;Klasse&gt;. Zeigt keine Gnade mit den Hakkari!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSiegelzeichen des SynkretistenWappen des SynkretistenSiegel des SynkretistenEmblem des Synkretisten"},
[85602] = {title = "Liebkosung des Animisten", objective = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", description = nil, progress = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", completion = "Nutzt es weise, &lt;Klasse&gt;. Zeigt keine Gnade mit den Hakkari!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nJähzorn des AnimistenBrüllen des AnimistenGleichgewicht des AnimistenLiebkosung des Animisten"},
[85603] = {title = "Vodouisants wachsame Umarmung", objective = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", description = nil, progress = "Zanza kann die antiken Trollverzauberungen mit den richtigen Komponenten herstellen.\n\nDie erste Zutat ist ein urzeitlicher Hakkarigötze, der von den mächtigsten Hakkari erlangt werden muss, von Jin'do und dem Blutfürsten.\n\nDie zweite Zutat ist eine durchstochene Voodoopuppe. Beide Komponenten findet Ihr in den Abfallhaufen, die diesen verdorbenen Ort bedecken. Schaut in den verwunschenen Hoodoohaufen nach.\n\nBringt mir diese Dinge und ich erschaffe eine mächtige Verzauberung für Euch!", completion = "Nutzt es weise, &lt;Klasse&gt;. Zeigt keine Gnade mit den Hakkari!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVodouisants UmarmungVodouisants WachsamkeitVodouisants SchleierVodouisants Amulett"},
[85604] = {title = "Die unversehrte Vision von Voodress", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nUnversehrte Vision von Voodress"},
[85605] = {title = "Symbole der Macht: Die Armschienen des Weissagers", objective = "Bringt urzeitliche Hakkariarmsplinte zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Die Weissager unseres Stammes werden für ihre Gaben der göttlichen Sicht respektiert, ja wirklich. Sie sind nicht etwa eine Art Hexendoktor, nein, sie verbringen ihre Zeit mit dem Beschwören von Knochen oder dem Lesen von Blättern der Einsicht, und nicht mit dem Verhexen anderer. Als Schamane wisst Ihr bereits etwas über die Macht der Weissagung; wir Zandalari würdigen die Einsicht, die unserem Stamm gegeben wird.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Helft Ihr uns, werde ich Euch Armschienen geben, die unsere Weissager mehr als alles andere verehren!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nArmschienen des Zandalariweissagers"},
[85606] = {title = "Symbole der Macht: Der Gürtel des Weissagers", objective = "Bringt einen urzeitlichen Hakkarigurt zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Die Weissager kennen das Mojo der Elemente, das ist wahr. Sie setzen es ein, um den Stamm zu Ruhm und Ehre zu führen. In den dunklen Zeiten, nachdem das Imperium der Gurubashi sich selbst zersplitterte, führten uns unsere Weissager in den sicheren Hafen der Südlichen Meere. Sie haben uns auch wieder zurück hierher ins Tal geführt, genau ins Herz des Bösen, das in Zul'Gurub schwelt.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und beweist Euch als uns würdig. Solltet Ihr dabei Erfolg haben, werde ich Euch einen Gürtel geben, wie ihn unsere Weissager verwenden, einen mit mächtigem Mojo!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGürtel des Zandalariweissagers"},
[85607] = {title = "Symbole der Macht: Die Halsberge des Weissagers", objective = "Bringt einen urzeitlichen Hakkariwappenrock zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Die Weissager der Zandalari tragen einen bestimmten Brustschmuck, der Halsberge genannt wird. Er wird aus feinster Seide und Stoffen zusammengefügt und mit starken Ketten verwoben. Es ist nicht nur ein Symbol für ihre Göttlichkeit, sondern auch für ihre Autorität. Es ist niemals sehr weise den Weg von jemanden zu kreuzen, der sein Leben der Zwiesprache mit den Geistern gewidmet hat...\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und beweist Euch als uns würdig. Solltet Ihr dabei Erfolg haben, werde ich Euch eine der feinsten Halsbergen geben, die sich selbst einer der unsrigen Weissager zu tragen erhofft!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHalsberge des Zandalariweissagers"},
[85608] = {title = "Reiner verzauberter Südmeertang", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nReiner verzauberter Südmeertang"},
[85609] = {title = "Symbole der Macht: Die Haruspexarmschienen", objective = "Bringt eine urzeitliche Hakkaristütze zu Maywiki von Zuldazar. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nMaywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Ein Haruspex ist ein wichtiges Mitglied in unserem Stamm, ihr tut gut daran auf ihr Omen zu hören. Mittels spiritueller Vereinigung mit den Tieren und deren Opferung, falls nötig, schenken sie uns göttliche Leitung. In der Vergangenheit verschaffte uns die Einsicht und Weisheit der Haruspex einen Vorteil in den Kämpfen gegen die zersplitterten Stämme der Gurubashi.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Solltet Ihr erfolgreich sein, so werde ich Euch mit Armschienen belohnen, die selbst ein Haruspex der Zandalari begehrt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHaruspex' Zandalariarmschienen"},
[85610] = {title = "Symbole der Macht: Der Haruspexgürtel", objective = "Bringt eine urzeitliche Hakkarischärpe zu Maywiki von Zuldazar. Maywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal. Die Einstellung des Stammes der Zandalari muss Euch gegenüber außerdem wohlwollend sein.", description = "Die Zandalari kennen die Wege der Druiden nicht; die Natur soll nach unseren Bedürfnissen geformt werden und nicht umgekehrt. Dennoch gehören die Haruspex zu denen, die am meisten mit der Natur im Einklang leben, und das mit Recht. Den Geist eines Wildtiers zu opfern, bedeutet zu wissen, wie es ist, einer von ihnen zu sein. Das ist die wahre Macht der Natur.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Solltet Ihr erfolgreich sein, so werde ich Euch mit einem mächtigen Gegenstand belohnen: einem Gürtel, wie ihn viele Haruspex der Zandalari verwenden.\n\nStarkes Mojo, ja!", progress = "Habt Ihr das erforderliche Symbol der Macht von Zul'Gurub beschaffen können? Wenn ja, so wird der Haruspexgürtel Euer Eigen sein.", completion = "Ich danke Euch - die latente Macht in diesem Gegenstand ist der eigentliche Schatz in ihm selbst, darauf könnt Ihr Gift nehmen. Ihr habt nicht nur das erforderliche Symbol der Macht erfolgreich beschafft, ihr habt Euch auch bei unserem Stamm als ehrbar erwiesen. Hier, nehmt wie versprochen Eure Belohnung!", rewards = "Ihr bekommt:\n\nHaruspex' Zandalarigürtel"},
[85611] = {title = "Symbole der Macht: Die Haruspextunika", objective = "Bringt einen urzeitlichen Hakkariwappenrock zu Maywiki von Zuldazar. Maywiki von Zuldazar befindet sich auf der Insel Yojamba im Schlingendorntal. Die Einstellung des Stammes der Zandalari muss Euch gegenüber außerdem respektvoll sein.", description = "Das ultimative Symbol der Macht eines Haruspex ist die Kleidung, die er trägt, <Name>. Die Tunika symbolisiert die Verbindung zwischen ihnen selbst und der göttlichen Weisheit, nach der sie streben. Oft werden in die Tunika Teile der geopferten Tiere eingewoben, die sie an die Verbundenheit mit deren Talenten erinnern.\n\nBringt mir ein Opfer der Symbole der Macht aus Zul'Gurub und erweist Euch als uns würdig. Solltet Ihr erfolgreich sein, so wird Euch eine wie von mir beschriebene Tunika gehören.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHaruspex' Zandalaritunika"},
[85612] = {title = "Die Wut Mugambas", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWut Mugambas"},
[85613] = {title = "Symbole der Macht: Die Armschützer des Vollstreckers", objective = "Bringt urzeitliche Hakkariarmsplinte zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Rache ist Macht. Der Vollstrecker der Zandalari ist solch eine Macht. Unser Stamm hat viele Feinde. Der Vollstrecker fordert Vergeltung von ihnen ein. Kein Verbrechen gegen uns bleibt unbestraft und der Vollstrecker sorgt für diese Bestrafung. Unsere Feinde fürchten sich vor unserer Rache. Das sollen sie auch, und sie werden es auch für immer tun.\n\nWerdet einer unserer Vollstrecker. Sucht nach den Symbolen der Macht in Zul'Gurub. Tötet die Diener Hakkars und sorgt im Namen unseres Stammes für Vergeltung. Ihr werdet belohnt werden.", progress = "Habt Ihr das Symbol der Macht bekommen? Wurde im Namen der Zandalari Vergeltung geübt?", completion = "Ihr habt heute ausreichend Rache walten lassen. Ihr habt das Antlitz des Vollstreckers angenommen und die Diener des Blutgottes in die Knie gezwungen.\n\nNehmt dies. Eure Rache wird damit für die Zukunft geschürt. Ihr seid nun ein Freund der Zandalari.", rewards = "Ihr bekommt:\n\nArmschützer des Zandalarivollstreckers"},
[85614] = {title = "Symbole der Macht: Der Gürtel des Vollstreckers", objective = "Bringt einen urzeitlichen Hakkarigurt zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Die ultimative Rache wartet innerhalb Zul'Gurubs. Hakkar darf nicht mehr auferstehen. Hakkar hat das Imperium der Gurubashi von innen heraus zerstört. Kein Opfer war ihm dafür zu schade. Die Trolle sind nur noch ein Schatten ihrer glorreichen Zeiten. Ich weiß, dass all dies auf Hakkar beruht.\n\nWerdet der Vollstrecker, zu dem Ihr bestimmt wart. Bringt Zerstörung über die Diener des Bösen herein. Zul'Gurub muss den Rachedurst der Zandalari zu spüren bekommen. Bringt mir ein Symbol der Macht als Beweis. Ihr werdet dafür den Gürtel des Vollstreckers bekommen. Ihr werdet wahre Macht erhalten.\n\nUnd nun geht.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGürtel des Zandalarivollstreckers"},
[85615] = {title = "Symbole der Macht: Die Brustplatte des Vollstreckers", objective = "Bringt einen urzeitlichen Hakkarikosak zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Die Brustplatte ist das Symbol der Macht eines Vollstreckers. Sie wird mit mächtigem Mojo geschmiedet. Sie wird nur denen anvertraut, die wir ehren. Es ist das Symbol der Rache der Zandalari.\n\nEin Vollstrecker zu werden, bedeutet ein Rächer zu werden. Beschafft das benötigte Symbol der Macht von Zul'Gurub. Bringt es zu uns. Wir werden uns das von uns gestohlene Mojo zurückholen. Die Diener Hakkars werden bezahlen müssen. Eure Belohnung wird die Brustplatte des Vollstreckers sein.\n\nGeht. Seid unser Rächer, <Name>.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBrustplatte des Zandalarivollstreckers"},
[85616] = {title = "Das allsehende Auge von Zuldazar", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nDas allsehende Auge von Zuldazar"},
[85617] = {title = "Das Emblem des Helden", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEmblem des Helden"},
[85618] = {title = "Symbole der Macht: Die Armschützer des Freidenkers", objective = "Bringt urzeitliche Hakkaribindungen zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Ihr seid ungläubig. Ungläubige haben einen Platz in unserem Stamm. Ungläubige sind Freidenker der Zandalari. Freidenker fürchten sich nicht vor Unterdrückung und sterben für das, woran sie glauben. Wir wissen, dass Ihr für das, woran Ihr glaubt, sterben würdet. Dies verdient unsere Anerkennung. Ihr dürft Euch uns auch weiterhin als würdig erweisen.\n\nWir brauchen die Symbole der Macht. Geht nach Zul'Gurub. Tötet die Diener Hakkars. Sobald Ihr habt, wonach ich verlange, kommt zu mir zurück. Strebt nach der ersten Kampfausrüstung eines Zandalarifreidenkers.\n\nUnd nun geht.", progress = "Ihr seid zurück? Habt Ihr das Symbol der Macht? Wollt Ihr meine Zeit verschwenden?\n\nIch hoffe doch nicht.", completion = "Ihr ehrt uns sehr. Eure Hände sind mit dem Blut der Diener Hakkars befleckt. Ihr seid ein Freund unseres Stammes.\n\nTragt diese Armschienen. Es sind Armschützer des Freidenkers. Das war es, was ich mit wahrer Macht meinte.", rewards = "Ihr bekommt:\n\nArmschützer des Zandalarifreidenkers"},
[85619] = {title = "Symbole der Macht: Der Gürtel des Freidenkers", objective = "Bringt einen urzeitlichen Hakkarischal zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Eure Überzeugungen sind uns fremd, Ungläubiger:Ungläubige;. Die Uralten von Zandalar wurden einst als Heiden gebrandmarkt. Dies war in der Zeit als das Imperium der Gurubashi noch mächtig war. Ungläubige wagten es, den Priester Hakkars herauszufordern. Sie wurden daraufhin gejagt und wie Ungeziefer vernichtet. Diese Ungläubigen wankten niemals in ihrem Kampf gegen den Blutgott. Wir wissen den Preis, den sie dafür bezahlen mussten, zu schätzen. Sie sind die Freidenker.\n\nMacht den Dienern Hakkars in Zul'Gurub den Garaus. Bringt mir das Symbol der Macht, nach denen ich verlange. Erfolgreiche Taten sollen großzügig belohnt werden.\n\nUnd nun geht.", progress = "Eure Anwesenheit kündet von Erfolg? Habt Ihr das Symbol? Badet Ihr bereits im Blut Eurer Feinde?", completion = "Das Wohlwollen in unserem Stamm ist Euch sicher. Zahlreiche Tote in Zul'Gurub gehen auf Euer Konto. Viele Feinde wurden von Euch gerichtet.\n\nDies ist der Gürtel des Freidenkers. Er steht für Ehre und ist mächtiges Mojo. Jetzt ist er Euer Eigen.", rewards = "Ihr bekommt:\n\nGürtel des Zandalarifreidenkers"},
[85620] = {title = "Symbole der Macht: Die Brustplatte des Freidenkers", objective = "Bringt einen urzeitlichen Hakkariwappenrock zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nJin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Im Stamm verleiht die Kampfausrüstung Macht. Die Freidenker sind auf diese Weise geehrt. Sie sind Zeloten. Sie tränken ihre Brustplatten mit mächtigem Mojo. Wenn ihr Glaube im Angesicht des Feindes zu wanken beginnt, so werden ihre Brustplatten dennoch standhalten.\n\nIhr müsst von uns respektiert werden, um solch eine Brustplatte zu besitzen. Geht nach Zul'Gurub. Ihr müsst das von mir benötigte Symbol der Macht beschaffen. Entwendet es den Narren auf schmerzlichste Art und Weise. Bringt es zu mir. Beweist Euch ein für alle Mal als Freidenker würdig.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBrustplatte des Zandalarifreidenkers"},
[85622] = {title = "Symbole der Macht: Die Handlappen des Glaubenshüters", objective = "Bringt eine urzeitliche Hakkaristütze zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Wir Zandalari investieren Macht in diejenigen, die mit der Gewalt des Göttlichen sprechen. Unsere Priester sind mehr als nur Heiler; sie sind auch unsere Hüter des Glaubens. Das Böse kommt von äußeren Bedrohungen, wie zum Beispiel Hakkar, wie auch von innerhalb des Stammes. Unsere Glaubenshüter agieren wie die Richter unter uns, sie schützen uns vor dem gleichen Übel, das bereits die Gurubashi sich selbst hat zerstören lassen.\n\nGeht nach Zul'Gurub und bringt die Symbole der Macht von den Gurubashi zurück. Lernt, was es heißt, ein Glaubenshüter zu sein, und schützt uns vor dem Bösen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHandlappen des Zandalariglaubenshüters"},
[85623] = {title = "Symbole der Macht: Die Bindungen des Glaubenshüters", objective = "Bringt eine urzeitliche Hakkarischärpe zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Kurze Zeit nach dem Fall der Gurubashi wurden wir Zandalari fast endgültig vom Bösen innerhalb unseres Stammes besiegt. Es war zu dieser Zeit, dass die sich Glaubenshüter unter uns erhoben, um den Stamm zu schützen und diejenigen zu verbannen, die unsereins zu zerstören trachteten. Sie erhalten nicht nur den Einklang zwischen uns und den Geistern, sie erhalten auch unsere Leiber.\n\nReist weit nach Zul'Gurub und werdet selbst Zeuge von der Verdorbenheit Hakkars und der Gurubashis. Entringt ihnen die Symbole der Macht, nach denen wir suchen, und Euer Erfolg soll belohnt werden!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBindungen des Zandalariglaubenshüters"},
[85624] = {title = "Symbole der Macht: Der Mantel des Glaubenshüters", objective = "Bringt eine urzeitliche Aegis der Hakkari zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Alle Glaubenshüter der Zandalari tragen einen bestimmten Mantel, der sie als Beschützer des Stammes auszeichnet. Diese Mäntel werden aus mächtigem Mojo gewoben, das beim Beurteilen derjenigen behilflich ist, die eine Bedrohung für unseren Stamm darstellen. Auch Ihr müsst als Priester Zeit aufwenden, um zu beurteilen, wer würdig ist und wer nicht; ein solcher Mantel wäre zweifellos ein Segen für Euch.\n\nWenn Ihr Hakkars Diener in Zul'Gurub besiegt und mir das benötigte Symbol der Macht besorgt, werde ich Euch im Austausch dafür einen Mantel geben, der unter unseren Glaubenshütern als hoch und heilig gilt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMantel des Zandalariglaubenshüters"},
[85625] = {title = "Kezans unaufhaltsame Schmach", objective = "Ruft Eure Dämonen hervor, <Klasse>. Lasst sie in der Energie von Kezans Schmach schwelgen. Führt sie aufs Schlachtfeld! Vernichtet den Feind!\n\nJa... die Zeit ist gekommen, um Kezans Schmach endgültig zu verstärken. Gebt mir den Talisman.", description = nil, progress = "Ruft Eure Dämonen hervor, <Klasse>. Lasst sie in der Energie von Kezans Schmach schwelgen. Führt sie aufs Schlachtfeld! Vernichtet den Feind!\n\nJa... die Zeit ist gekommen, um Kezans Schmach endgültig zu verstärken. Gebt mir den Talisman.", completion = "Reißt das Fleisch von ihren Körpern. Beobachtet, wie die Schatten die Hakkari verzehren. Zieht Macht aus ihrer Furcht, &lt;Klasse&gt;. Lasst Kezans Schmach mächtiger werden...", rewards = "Ihr bekommt:\n\nKezans unaufhaltsame Schmach"},
[85626] = {title = "Symbole der Macht: Die Handlappen des Besessenen", objective = "Bringt eine urzeitliche Hakkaristütze zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Hexenmeister begeben sich bei ihrem Umgang mit Dämonen auf ein gefährliches Terrain, unsere Besessenen gehen jedoch noch einen Schritt weiter. Mithilfe eines uralten, arkanen Rituals erlauben sie es einem Dämon, in ihre Gestalt zu schlüpfen. Anstelle von ihm besessen zu werden, versklaven sie den Dämon von innen heraus und absorbieren die Macht des Ungetüms für ihre eigenen Zwecke. Es ist eine Fähigkeit, die nur wenige zu meistern verstehen.\n\nDamit Ihr von der Macht der Besessenen lernen könnt, müsst Ihr mir ein Symbol der Macht von Zul'Gurub beschaffen. Geht und bringt mir, wonach ich verlange.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHandlappen des Zandalaribesessenen"},
[85627] = {title = "Symbole der Macht: Der Mantel des Besessenen", objective = "Bringt eine urzeitliche Hakkarischärpe zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Der Besessene möchte Macht geradewegs verkörpern und nicht nur besitzen. Mehr als ein Besessener hat bereits den Kampf gegen einen Dämonen verloren; die Feinde, die uns bedrohen, besonders in Zul'Gurub, und die Macht, die ein Besessener auf unsere Feinde loslassen kann, sind das Opfer jedoch wert. Unser Überleben hängt von der Zerstörung derer ab, die nach unserem Ende trachten; das hat uns der Fall des Imperiums der Gurubashi gelehrt.\n\nReist nach Zul'Gurub und beschafft uns das von uns benötigte Symbol der Macht. Solltet Ihr dabei Erfolg haben, soll ein wertvoller Gegenstand eines Besessenen Euer Eigen sein.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMantel des Zandalaribesessenen"},
[85628] = {title = "Symbole der Macht: Die Roben des Besessenen", objective = "Bringt einen urzeitlichen Hakkarikosak Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Im Stamm ist das ultimative Zeichen für Macht die Kleidung, die im Kampf getragen wird. Die Roben des Besessenen vereinen feinen Runenstoff und verheerend mächtiges Mojo. Man sagt, dass das Aussehen dieser Roben allen Angst einflößt, die sie erblicken... besonders den Dämonen, die der Besessene eventuell beherrschen möchte.\n\nIhr müsst mir von Zul'Gurub ein besonderes Symbol der Macht besorgen. Es wird nicht einfach sein... Euer erfolgreiches Handeln wird Euch jedoch den Besitz einer der besagten Roben sichern.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRobe des besessenen Zandalari"},
[85629] = {title = "Das Juwel von Kajaro", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nJuwel von Kajaro"},
[85630] = {title = "Symbole der Macht: Die Handlappen des Illusionisten", objective = "Bringt urzeitliche Hakkaribindungen zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Magier sind in unserem Stamm als Illusionisten bekannt. Sie setzen bei ihren Beschwörungen mächtiges Mojo ein, bringen die Feinde des Stamms oft durcheinander und machen sie konfus!\n\n<Al'tabim lacht gehässig.>\n\nEs ist schon ein ziemliches Spektakel, wenn man einem mächtigen Illusionisten bei der Arbeit zusieht und beobachtet wie er unsere Feinde mithilfe ihres eigenen Wahnsinns in die Knie zwingt!\n\nWenn Ihr mehr über den Weg unserer Illusionisten lernen möchtet, dann geht nach Zul'Gurub und bringt ein bestimmtes Symbol der Macht zu mir zurück. Ich werde Euch dafür mit Handlappen belohnen, die unsere Illusionisten zum Weben ihrer Zauber verwenden.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHandlappen des Zandalari-Illusionisten"},
[85631] = {title = "Symbole der Macht: Der Mantel des Illusionisten", objective = "Bringt einen urzeitlichen Hakkarischal zu Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Magie ist eine rohe, uralte Kraft, die von denen beherrscht werden muss, die stark genug dafür sind. Mojo ist unser verlängerter Arm dieser Macht; eine der mächtigsten Manipulationen davon ist die Form der Illusion. Wie kann man sich ernsthaft erhoffen einen Feind zu schlagen, der nicht einmal wirklich da ist? Wir Zandalari wissen von dieser Macht und daher wird den Illusionisten eine besondere Stellung in unserem Stamm zuteil.\n\nBeschafft das notwendige Symbol der Macht von Zul'Gurub... dafür werdet Ihr mit dem Wohlwollen unseres Stammes und einem mächtigen Mantel, wie er von unseren besten Illusionisten verwendet wird, belohnt werden!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMantel des Zandalari-Illusionisten"},
[85632] = {title = "Symbole der Macht: Die Roben des Illusionisten", objective = "Bringt einen urzeitlichen Hakkarikosak Al'tabim dem Allsehenden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nAl'tabim der Allsehende befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Im Stamm wird Stellung und Macht durch das ausgezeichnet, was man trägt. Unsere Kleidung wird aus den feinsten Materialien hergestellt und mit Mojo verwoben, mit dessen Hilfe wir uns Macht verleihen. Illusionisten sind keine Ausnahme; man sagt, dass ihre Roben mittels ihres Aussehens die Essenz der Illusion verkörpern. Legenden besagen, dass ihre uralten Roben niemals gleich aussahen.\n\nIch werde Euch die Robe eines Illusionisten geben, <Name>... aber zuerst müsst Ihr Euch in unserem Stamm Respekt verdienen! Bringt mir ein Symbol der Macht von Zul'Gurub!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRobe des Zandalari-Illusionisten"},
[85633] = {title = "Zandalarischattentalisman der Beherrschung", objective = "Er sehnt sich nach Wachstum, <Name>. Der Talisman hat all das in sich aufgenommen, was Ihr vollbracht habt. Die unzähligen Trollkadaver, die Zul'Gurub beschmutzen, haben seine Macht vergrößert. Gebt ihn mir und ich werde ihn endgültig verstärken.", description = nil, progress = "Er sehnt sich nach Wachstum, <Name>. Der Talisman hat all das in sich aufgenommen, was Ihr vollbracht habt. Die unzähligen Trollkadaver, die Zul'Gurub beschmutzen, haben seine Macht vergrößert. Gebt ihn mir und ich werde ihn endgültig verstärken.", completion = "Dies ist das letzte Mal, dass wir unter der Schirmherrschaft von Shera Ali'kh miteinander sprechen. Ihr wisst alles, was Ihr wissen müsst. Nehmt den Talisman und setzt Euer Schlachten fort. Hakkar darf Zul'Gurub niemals verlassen.", rewards = "Ihr bekommt:\n\nZandalarischattentalisman der Beherrschung"},
[85634] = {title = "Symbole der Macht: Die Armschienen des Wildfangs", objective = "Bringt urzeitliche Hakkariarmsplinte zu Falthir dem Blinden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Die Wildfänge von Zandalar ähneln den Schurken, vertraut sind sie vor allem aber mit dem Wahnsinn... dem Chaos... der Unberechenbarkeit des Lebens. Als unvergesslicher Anblick des Terrors auf dem Schlachtfeld, säten sie in den wilden Zeiten nach Aufsplittung der Stämme Verwirrung und Chaos unter unseren Feinden. Ohne sie, würde es uns heute nicht geben.\n\nBringt mir das gewünschte Symbol der Macht von Zul'Gurub und ich werde Euch mit den so begehrten Armschienen des Wildfangs belohnen. Gebt Euch dem Wahnsinn hin!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nArmschienen des Zandalariwildfangs"},
[85635] = {title = "Symbole der Macht: Der Mantel des Wildfangs", objective = "Bringt einen urzeitlichen Hakkarigurt zu Falthir dem Blinden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Khar'vaxal der Irrsinnige war einer der legendären Wildfänge der Zandalari. Legenden zufolge benutze er seinen Mantel, der speziell aus \"Stoff des Wahnsinns\" gewoben wurde, als er den Feinden des Stammes zum ersten Mal gegenübertrat. Seine Gestalt wurde nicht nur von dem Mantel, sondern auch dank der blendenden Geschwindigkeit seiner Zwillingsdolche verschleiert. Heute verehren die Wildfänge ihren Mantel als Zeichen der Stammeszugehörigkeit und der Stellung, die ihnen zusteht.\n\nBringt mir das gewünschte Symbol der Macht und ein derartiger Mantel wird Euch gehören und Eure Feinde in Wahnsinn hüllen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMantel des Zandalariwildfangs"},
[85636] = {title = "Symbole der Macht: Die Tunika des Wildfangs", objective = "Bringt eine urzeitliche Aegis der Hakkari zu Falthir dem Blinden. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Meine Augen haben mich schon seit langem im Stich gelassen, aber ich trauere ihnen nicht nach. Selbst in einem Stamm wie dem unsrigen, in dem die Kleidung Rang und Bestimmung vermittelt, strahlen die einflussreichsten aller Gewänder eine Macht aus, die für normale Augen nicht sichtbar ist. Die Tunika des Zandalariwildfangs ist keine Ausnahme, sie strahlt die rohe Macht des Chaos und des Wahnsinns aus, die mit ihr kanalisiert werden kann.\n\nDie Symbole der Macht, die ich benötige, befinden sich in Zul'Gurub; bringt mir eines und ich werde Euch mit Eurer eigenen legendären Tunika belohnen... eine, die einem Säer des Wahnsinns gerecht wird.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTunika des Zandalariwildfangs"},
[85637] = {title = "Mahlstroms Zorn", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMahlstroms Zorn"},
[85638] = {title = "Symbole der Macht: Die Armschienen des Raubtiers", objective = "Bringt das folgende Symbol der Macht aus Zul'Gurub zu Falthir dem Blinden: Urzeitliche Hakkaribindungen. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens freundlich oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "In den dunklen Zeiten nach dem Fall des Imperiums der Gurubashi setzten die Jäger der Zandalari ihre Tapferkeit ein, um den Lebensunterhalt für den Stamm zu sichern. Man vergleicht sich gerne mit den Jägern unseres Stammes: Das Streben nach der Jagd bedeutet das Einswerden mit der Essenz des Jägers, ja. Eure Jagd in Zul'Gurub wird uns zeigen, in welchem Verhältnis Ihr zu unseren besten Jägern steht.\n\nBringt mir ein Muster der Symbole der Macht aus Zul'Gurub. Ihr werdet damit Eure ersten Schritte tun, die es braucht, um vorletzter Jäger zu werden.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nArmschienen des Zandalariraubtiers"},
[85639] = {title = "Symbole der Macht: Der Gürtel des Raubtiers", objective = "Bringt das folgende Symbol der Macht aus Zul'Gurub zu Falthir dem Blinden: Einen urzeitlichen Hakkarischal. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens wohlwollend oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Ein Raubtier weiß, wie es sich an seine Beute heranschleicht, ein erfolgreiches Raubtier weiß aber auch, wie es seine Beute schlägt, sobald es zu ihr aufgeschlossen hat. Ihr müsst beides beherrschen, wenn Ihr in Zul'Gurub erfolgreich sein wollt... und wenn Ihr Euch mit den Jägern der Zandalari vergleichen wollt.\n\nBringt mir ein ausgesuchtes Teil der Symbole der Macht aus Zul'Gurub. Meine Belohnung wird die Macht sein, die diese Schmuckstücke enthalten, Eure wird dagegen der Gürtel des Zandalariraubtiers sein, ein Gegenstand, der den Tausch sehr wohl wert ist, glaubt mir.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGürtel des Zandalariraubtiers"},
[85640] = {title = "Symbole der Macht: Der Mantel des Raubtiers", objective = "Bringt das folgende Symbol der Macht aus Zul'Gurub zu Falthir dem Blinden: Eine urzeitliche Aegis der Hakkari. Die Einstellung des Stammes der Zandalari muss Euch gegenüber wenigstens respektvoll oder höher sein.\n\nFalthir der Blinde befindet sich auf der Insel Yojamba im Schlingendorntal.", description = "Wir Zandalari schätzen unsere Kleidung als eine Art Symbol für vollbrachte Taten. Man muss nicht sehen können, was jemand trägt, um zu spüren, was davon ausgeht. Macht geht über die Sicht hinaus. Die Bekleidung von Zandalarijägern ist von dieser Art, und der wohl am meisten verehrte Teil davon ist der Mantel, den sie tragen. Er hilft ihnen ihr Erscheinungsbild zu verschleiern... und ihre Gegenwart dann bekannt zu geben, wenn sie es möchten.\n\nDie Symbole der Macht warten in Zul'Gurub darauf, von Euch zurückerobert zu werden. Bringt mir, wonach ich verlange, und der Mantel des Zandalariraubtiers soll Euer Eigen sein.", progress = "War Euer Anschlag auf Zul'Gurub erfolgreich, <Name>? Nur wenn Ihr mir gebracht habt, wonach ich verlange, und Ihr Euch dem Stamm ganz und gar würdig erwiesen habt, werdet Ihr den Mantel erhalten, der wie kein anderer der Zandalari ist.", completion = "Erfolg... Ihr werdet vom Stamm respektiert werden, &lt;Name&gt;. Die Beschaffung des Symbols der Macht, welches für den Mantel von Nöten ist, war eine waghalsige Leistung, die Ihr auf tödlichste Art und Weise unserer Jäger gemeistert habt. Ihr habt Euch Euren Platz unter ihresgleichen verdient und sicherlich auch das Recht, ihren Mantel tragen zu dürfen.", rewards = "Ihr bekommt:\n\nMantel des Zandalariraubtiers"},
[85643] = {title = "Der Herrscher des Schwarzfels", objective = "Reist in Sturmwind in das Tal der Helden und sprecht mit Feldmarschall Steinsteg.", description = "Begebt Euch in das Tal der Helden und sprecht mit Feldmarschall Steinsteg.", progress = nil, completion = "&lt;Feldmarschall Steinsteg verbeugt sich.&gt;\n\nSucht Euch eine Belohnung aus und lasst die Feierlichkeiten beginnen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMedaillon des MeisterdrachentötersKugel des MeisterdrachentötersRing des Meisterdrachentöters\n\nIhr bekommt außerdem:\n\n"},
[85644] = {title = "Der Herrscher des Schwarzfels", objective = "Sprecht mit Hochfürst Saurfang in Orgrimmar. Er wartet im Tal der Stärke auf Euch.", description = "Sucht Hochfürst Saurfang im Tal der Stärke auf.", progress = nil, completion = "Sucht Euch eine Belohnung aus. Anschließend werde ich den Kopf des Biests für alle sichtbar zur Schau stellen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMedaillon des MeisterdrachentötersKugel des MeisterdrachentötersRing des Meisterdrachentöters\n\nIhr bekommt außerdem:\n\n"},
[85658] = {title = "Für alle sichtbar", objective = "Sucht Oberanführer Runthak im Tal der Stärke auf.", description = "Oberanführer Runthak erwartet Eure Ankunft im Tal der Stärke.\n\n<Thrall salutiert Euch.>\n\nLasst Euer Publikum nicht warten, großer Held.", progress = nil, completion = "Wählt Eure Belohnung und lasst die Feierlichkeiten anlässlich Eures großen Sieges beginnen.", rewards = nil},
[85659] = {title = "Gute Zeiten feiern", objective = "Sucht Major Mattingly im Tal der Helden auf.", description = "Sucht Major Mattingly im Tal der Helden auf, <Name>. Er erwartet Euch bereits...", progress = nil, completion = "Nur wenige wurden bisher mit einer solchen Zeremonie geehrt, &lt;Name&gt;. Bitte wählt Eure Belohnung aus, damit wir mit den Feierlichkeiten beginnen können.", rewards = nil},
[85660] = {title = "Das Herz von Hakkar", objective = "Bringt das Herz von Hakkar zu Molthor auf die Insel Yojamba.", description = "Das Herz von Hakkar brennt noch immer im Inneren. Obwohl der Seelenschinder besiegt ist, bleibt das Wesen seiner Macht doch in dem verfluchten Organ enthalten.", progress = nil, completion = "Ah, das Herz von Hakkar. Also wurde der Seelenschinder besiegt! Die Welt ist gerettet!\n\n&lt;Name&gt;, Euer Dienst für uns kann nicht genug gerühmt werden. Ihr seid wahrlich ein Held!", rewards = nil},
[85699] = {title = "Schlangenstein der Schattenjägerin", objective = "Begebt Euch zur Schwarzfelsspitze und erschlagt Schattenjägerin Vosh'gajin. Holt Vosh'gajins Schlangenstein und kehrt zu Kilram zurück.", description = "Lasst Euch von ihrer Schönheit nicht narren, <Klasse>. Die Schattenjägerin Vosh'gajin ist todbringend und wahnsinnig.\n\n<Kilram zeigt auf die Narbe in seinem Gesicht.>\n\nJa, die habe ich von ihr - eine Liebkosung, wie sie es nannte.\n\nJetzt endlich ist die Zeit der Rache gekommen.\n\nIhr könnt Vosh'gajin in der Schwarzfelsspitze finden. Erschlagt sie und kehrt mit ihrem Schlangenstein zu mir zurück. Erledigt das und ich werde Euch das Geheimnis des Axtschmiedens beibringen!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAxtschmiedemeister\n\nIhr bekommt:\n\nPläne: Dämmerungsschneide"},
[85700] = {title = "Verderbnis", objective = "Findet den Schwertschmied der schwarzen Wache in Stratholme und vernichtet ihn. Holt die Insignien der schwarzen Wache und kehrt zu Seril Geißelbann zurück.", description = "Wenn ich mit Euch kurz angebunden bin, dann gibt es einen Grund dafür. Die Pläne für die Erschaffung der großen Klinge, der Verderbnis, wurden von der schwarzen Wache gestohlen: den Skeletteliteeinheiten von Baron Totenschwur.\n\nJa, Baron Totenschwur von Stratholme.\n\nDer Schwertschmied der schwarzen Wache bewacht diese Pläne nun mit seinem...Untod.\n\nErschlagt ihn, kehrt mit einem Beweis für diese Tat zurück und ich werde Euch das Schwertschmieden beibringen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSchwertschmiedemeister\n\nIhr bekommt:\n\nPläne: Loderflammenrapier"},
[85701] = {title = "Drachenlederverarbeitung", objective = "Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Peter Galen in Azshara.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.\n\nIhr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", description = "Drachenlederverarbeitung ist nicht einfach, aber sie ist sehr einträglich. Ich werde Euch beibringen, wie man diese feine Panzerrüstung fertigt, aber nur, wenn Ihr bestimmten Bedingungen zustimmt.\n\nMit der Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Elementarlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. An der Spitze des Handwerks ist nur Platz für eine der drei. Des Weiteren werde ich eine Probe Eurer besten Arbeit aus dem Bereich der Skorpidrüstung benötigen. Schließlich benötige ich noch einen Beweis für Eure Fähigkeit, die Hauptzutat des Handwerks zu erlangen: Schuppen der Drachkin.", progress = "Wenn Ihr bereit seid, eine dauerhafte Entscheidung zu treffen, indem Ihr ein Drachenlederer werdet, dann bin ich bereit, Euch als Schüler aufzunehmen. Bringt mir einfach die Dinge, um die ich gebeten habe und wir werden mit Eurer Ausbildung beginnen.", completion = "Ich muss Euch loben... es bedarf eines starken Willens, eine dauerhafte Entscheidung zu treffen, wie Ihr es gerade getan habt. Ich versichere Euch, Drachenlederverarbeitung wird sich als profitabler und lohnender Weg für Euch erweisen.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDrachenlederverarbeitung\n\nIhr bekommt:\n\n"},
[85702] = {title = "Drachenlederverarbeitung", objective = "Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Thorkaf Drachenaug im Ödland.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten.\n\nIhr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", description = "Drachenlederverarbeitung ist nicht einfach, aber sie ist sehr einträglich. Ich werde Euch beibringen, wie man diese feine Panzerrüstung fertigt, aber nur, wenn Ihr bestimmten Bedingungen zustimmt.\n\nMit der Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Elementarlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. An der Spitze des Handwerks ist nur Platz für eine der drei. Des Weiteren werde ich eine Probe Eurer besten Arbeit aus dem Bereich der Skorpidrüstung benötigen. Schließlich benötige ich noch einen Beweis für Eure Fähigkeit, die Hauptzutat des Handwerks zu erlangen: Schuppen der Drachkin.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDrachenlederverarbeitung\n\nIhr bekommt:\n\n"},
[85703] = {title = "Elementarlederverarbeitung", objective = "Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Sarah Gerber in die sengende Schlucht.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", description = "Elementarlederverarbeitung ist, was ich kann, und wenn Ihr bereit seid, Eure Gedanken den größeren Mächten der Substanz zu öffnen, werde ich mit Euch alles teilen, was es zu lernen gibt.\n\nDoch wisset dies, <Klasse>: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Des Weiteren benötige ich einen angemessenen Beweis, dass Ihr im Einklang mit den Elementen der Natur steht. Bringt mir dafür die reinsten Essenzen von Feuer, Wasser, Erde und Wind.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nElementarlederverarbeitung\n\nIhr bekommt:\n\n"},
[85704] = {title = "Elementarlederverarbeitung", objective = "Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Brumn Winterhuf in den Arathibergen.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", description = "Elementarlederverarbeitung ist, was ich kann, und wenn Ihr bereit seid, Eure Gedanken den größeren Mächten der Substanz zu öffnen, werde ich mit Euch alles teilen, was es zu lernen gibt.\n\nDoch wisset dies, <Klasse>: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Stammeslederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Des Weiteren benötige ich einen angemessenen Beweis, dass Ihr im Einklang mit den Elementen der Natur steht. Bringt mir dafür die reinsten Essenzen von Feuer, Wasser, Erde und Wind.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nElementarlederverarbeitung\n\nIhr bekommt:\n\n"},
[85705] = {title = "Stammeslederverarbeitung", objective = "Bringt eine Wildlederweste und einen Wildlederhelm zu Caryssia Jägermond in Feralas.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", description = "Um die Kunst der Stammeslederverarbeitung zu erlernen, müsst Ihr verstehen, wie urzeitlich die Natur wirklich ist; ich weiß, dass Ihr bereits die Kunst der Herstellung von Wildlederrüstungen gemeistert habt, und ich bin bereit, Eure Ausbildung abzuschließen.\n\nDoch wisset dies, <Klasse>: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Elementarlederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Bringt mir des Weiteren die feinsten Proben Eurer Wildlederrüstungen. Von diesem Punkt aus werden wir dann beginnen, an Eurem Können zu arbeiten.", progress = "Die Natur ist eine Kraft, die besänftigt werden muss, bevor Ihr hoffen könnt zu lernen, wie ihr Wille für Eure Ledergewänder zu beugen ist. Bringt mir Euer Geschenk für diese Kraft und ich werde sicherstellen, dass Ihr erhört werdet.", completion = "Ihr habt Eure besten Geschenke gebracht und die Natur wird bald zulassen, dass Ihr sie Eurem Willen entsprechend beugt. Wenn ich meine Unterweisung beendet habe, wird Eure Arbeit eine Naturgewalt in sich selbst sein.\n\nUm in Zukunft die Kunst zu trainieren, sprecht einfach mit mir, und ich werde Euch das Wissen verfügbar machen, das Ihr noch als das Eure erwerben müsst.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nStammeslederverarbeitung\n\nIhr bekommt:\n\n"},
[85706] = {title = "Stammeslederverarbeitung", objective = "Bringt eine Wildlederweste und einen Wildlederhelm zu Se'Jib im Schlingendorntal.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten.\n\nWenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.", description = "Um die Kunst der Stammeslederverarbeitung zu erlernen, müsst Ihr verstehen, wie urzeitlich die Natur wirklich ist; ich weiß, dass Ihr bereits die Kunst der Herstellung von Wildlederrüstungen gemeistert habt, und ich bin bereit, Eure Ausbildung abzuschließen.\n\nDoch wisset dies, <Klasse>: Durch die Wahl dieses Weges erklärt Ihr Euch einverstanden, niemals die Kunst der Drachenlederverarbeitung oder der Elementarlederverarbeitung zu erlernen. Ihr könnt nur eine dieser drei Künste erlernen. Bringt mir des Weiteren die feinsten Proben Eurer Wildlederrüstungen. Von diesem Punkt aus werden wir dann beginnen, an Eurem Können zu arbeiten.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nStammeslederverarbeitung\n\nIhr bekommt:\n\n"},
[85712] = {title = "Die Kunst des Rüstungsschmiedes", objective = "Um Rüstungsschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Okothos bringen: 4 verschnörkelte Mithrilhelme, 2 verschnörkelte Mithrilstiefel, 1 verschnörkelte Mithrilbrustplatte.", description = "Zufriedenheit. Das bekomme ich von Hammer und Amboss. Einen stolzen Krieger der Horde zu sehen, der von meinem Stahl geschützt ist, erinnert mich daran, was es heißt, am Leben zu sein. Das ist eine Sucht, die ich niemals ablegen werde, <Name>.\n\nIch kann Euch diese Zufriedenheit nicht garantieren, Euch nur auf den Weg dazu bringen. Wie bei allen Bestrebungen des Lebens ist auch der Weg des Rüstungsschmieds eine Reise.\n\nWenn Ihr einer der wenigen Erwählten sein wollt, müsst Ihr nur fragen und ich werde Euch ausbilden, aber zuerst müsst Ihr eine Aufgabe erledigen.", progress = "Ich werde den Stahl schlagen, bis mir selbst der Atem genommen wird.", completion = "Dies ist der letzte Schritt, bevor Ihr Eure neue Karriere als Rüstungsschmied beginnen könnt, &lt;Name&gt;. Solltet Ihr Euch dazu entscheiden abzuspringen, ist jetzt Eure letzte Gelegenheit dazu. Anderenfalls bereitet Euch auf ein Leben voller Ruhm und Glorie vor.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRüstungsschmiedekunstfachmann\n\nIhr bekommt:\n\n"},
[85713] = {title = "Die Kunst des Rüstungsschmiedes", objective = "Um Rüstungsschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Grumnus bringen: 4 verschnörkelte Mithrilhelme, 2 verschnörkelte Mithrilstiefel, 1 verschnörkelte Mithrilbrustplatte.", description = "Tja, Ihr habt 'ne kluge Entscheidung getroffen.\n\nWir haben nix füreinander übrig, ich und der alte Ironus hier. Dieser nichtsnutzige Spielzeughersteller weiß, wer die wahren Handwerker hier sind.\n\nDie wirklich großen Kriege werden mit 'ner guten Verteidigung gewonnen. Wenn's losgeht, wird Euch kein Angriff helfen.\n\nAlso dann, ran an die Arbeit! Ihr müsst mir nur zeigen, dass Ihr über Talent verfügt. Danach reiß ich alle Unreinheiten, die noch in Euch sind, raus und mach einen Rüstungsschmied aus Euch. Ihr wisst doch, wie man verschnörkeltes Mithril herstellt, nicht wahr?Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRüstungsschmiedekunstfachmann\n\nIhr bekommt:\n\n"},
[85772] = {title = "Elementare Not", objective = "Sammelt Partikel elementaren Zorns und bringt sie zu Je'neu Sancrea beim Zoram'gar-Außenposten in Ashenvale.", description = "Hört zu, <Name>. Die Korruption, von der ich zuvor gesprochen habe, betrifft mehr als nur Baron Aquanis. Ich spüre schon seit geraumer Zeit eine gewisse Unruhe in der Welt der Elementare. Ich fürchte, dass etwas im Argen liegt, und die Korruption von Baron Aquanis bestätigt lediglich meine Vermutungen.\n\nFindet hier in Ashenvale und dem Steinkrallengebirge in der Nähe mehr von diesen leidenden Elementaren. Bringt mir Partikel ihrer Essenz. Vielleicht kann ich sie analysieren und dadurch langsam verstehen, worin ihr Zorn gründet.", progress = nil, completion = nil, rewards = nil},
[85798] = {title = "Waffen für den Feldeinsatz", objective = "Bringt 2 Mondstahlbreitschwerter zu Janela Stouthammer am Posten der Ironforgebrigade beim Bau des Zoraschwarms. Ihr benötigt auch Logistikeinsatz VI, um diese Aufgabe abschließen zu können.", description = "Die Ironforgebrigade hat sich in den Kämpfen von Silithus als ein würdiger Verbündeter erwiesen. Unglücklicherweise hat sie auf dem Weg hierher die meisten ihrer Vorräte eingebüßt. Beschafft eine Ladung Waffen und bringt sie zu Janela Stouthammer nahe des Baus des Zoraschwarms.", progress = "Ihr habt etwas für mich, <Name>?", completion = "Oh, fantastisch! Endlich muss ich mir kein Gemaule über stumpfe Waffen mehr anhören. Vielen Dank, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nCenarisches VersorgungsabzeichenNachfolgender Logistikauftrag"},
[85882] = {title = "Das Ende der Dunklen Horde", objective = "Bringt den Kopf von Rend Blackhand zu Meister Mathias Shaw in Stormwind.", description = "Die Tat ist vollbracht. Dal'rend Blackhand, Kriegshäuptling der Dunklen Horde, liegt tot zu Euren Füßen. Nehmt seinen Kopf und zeigt ihn Meister Shaw.", progress = nil, completion = "Gut gemacht, Champion. Der Kriegshäuptling der Dunklen Horde ist tot, und damit endet ein Zeitalter des Schreckens in unserem Land. Lasst ganz Stormwind von Eurem Sieg wissen!", rewards = "Ihr bekommt:\n\n"},
[85883] = {title = "Für die Horde!", objective = "Begebt Euch zur Blackrockspitze und tötet den Kriegshäuptling Rend Blackhand. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück.", description = "Nur weil der schwarze Drachenschwarm hinter ihm steht, wagt Rend es, solche Ansprüche zu stellen.\n\nIhr, <Name>, müsst einen Weg finden, die Hallen des Aufstiegs zu durchqueren. Dahinter findet Ihr den \"Kriegshäuptling\" Rend Blackhand. Ihr müsst ihn vernichten... FÜR DIE HORDE!\n\n<Thrall schlägt mit der Faust auf seinen Thron.>\n\nWenn Ihr meine Gemächer das nächste Mal betretet, werdet Ihr seinen Kopf triumphierend in die Höhe halten und ihn Eurem Kriegshäuptling präsentieren. Gelingt Euch das, wird man Euch als <Held/Heldin> der Horde ehren.", progress = nil, completion = "Ihr habt der Streitmacht von Blackrock einen schweren Schlag versetzt, &lt;Name&gt;. Da ihr Kriegshäuptling jetzt tot ist, wird die Blackrocklegion erneut im Sumpf des Chaos versinken.\n\nZu Ehren Euer Heldentaten wird Euch das Volk von Kalimdor belohnen!", rewards = "Ihr bekommt:\n\n"},
[85963] = {title = "Ein Belobigungsabzeichen", objective = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf bei der Argentumdämmerung ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", description = nil, progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf bei der Argentumdämmerung ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf würde sich stark verbessern.\n\nGenug geredet! Wollt Ihr nun Abzeichen eintauschen oder nicht?", completion = "Sehr gut! Eure glorreichen Taten wurden verzeichnet und Ihr habt Eure verdiente Anerkennung erhalten. Macht so weiter, &lt;Klasse&gt;!\n\nIch stehe Euch auch in Zukunft zur Verfügung, falls Ihr weitere Abzeichen abgeben möchtet.", rewards = nil},
[85964] = {title = "Zehn Belobigungsabzeichen", objective = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf bei der Argentumdämmerung sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", description = nil, progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf bei der Argentumdämmerung sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Hervorragend! Ihr musstet so einiges auf Euch nehmen, um diese Abzeichen zu erhalten. Von jetzt an wird man Euch eine Menge Respekt entgegenbringen! Wie es sich für Eure großartige Pflichterfüllung und Hingabe gehört! Es sind Abenteurer von Eurem Kaliber, &lt;Name&gt;, die etwas in der Welt bewirken!\n\nLasst es mich wissen, wenn Ihr noch weitere Abzeichen zur Hand habt. Ich werde sie gerne entgegennehmen.", rewards = nil},
[85965] = {title = "Ein Belobigungsabzeichen", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
