[85983] = {title = "Ein Belobigungsabzeichen", objective = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf beim Stamm der Zandalari ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf würde sich stark verbessern.\n\nSo oder so, ich nehme eure Abzeichen nur zu gerne an.", description = nil, progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf beim Stamm der Zandalari ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf würde sich stark verbessern.\n\nSo oder so, ich nehme eure Abzeichen nur zu gerne an.", completion = "Also gut, Eure Taten haben bei den Zandalari Anerkennung gefunden. Immer weiter so, &lt;Klasse&gt;.\n\nWenn Ihr weitere Abzeichen abgeben möchtet, dann immer her damit.", rewards = nil},
[85984] = {title = "Ein Belobigungsabzeichen", objective = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf beim Stamm der Zandalari ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf würde sich stark verbessern.\n\nSo oder so, ich nehme eure Abzeichen nur zu gerne an.", description = nil, progress = "Alle Abenteurer, die Belobigungsabzeichen besitzen, können diese bei mir abgeben, um Ihren Ruf beim Stamm der Zandalari ein wenig zu verbessern.\n\nDoch überlegt es Euch gut! Wenn Ihr mir stattdessen zehn Abzeichen auf einmal übergebt, würdet Ihr dadurch wesentlich mehr Anerkennung erhalten und Euer Ruf würde sich stark verbessern.\n\nSo oder so, ich nehme eure Abzeichen nur zu gerne an.", completion = "Also gut, Eure Taten haben bei den Zandalari Anerkennung gefunden. Immer weiter so, &lt;Klasse&gt;.\n\nWenn Ihr weitere Abzeichen abgeben möchtet, dann immer her damit.", rewards = nil},
[85985] = {title = "Zehn Belobigungsabzeichen", objective = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf beim Stamm der Zandalari sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf beim Darkspearstamm nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", description = nil, progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf beim Stamm der Zandalari sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf beim Darkspearstamm nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Ausgezeichnet! Ihr habt Opfer gebracht, um diese Abzeichen zu verdienen, und dafür sollt Ihr auch entsprechend Anerkennung finden. Abenteurer wie Ihr, &lt;Name&gt;, machen einen wahren Unterschied.\n\nKommt zu mir, wenn Ihr weitere Abzeichen abgeben möchtet, ich helfe Euch gerne dabei, sie einzutauschen.", rewards = nil},
[85986] = {title = "Zehn Belobigungsabzeichen", objective = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf beim Stamm der Zandalari sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf beim Darkspearstamm nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", description = nil, progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Abenteurer im Laufe ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass ein jeder von Euren Taten erfährt und sich Euer Ruf beim Stamm der Zandalari sehr stark verbessert. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf beim Darkspearstamm nur geringfügig verbessern.\n\nGenug geredet! Es wäre mir nun eine Freude, Eure Abzeichen entgegenzunehmen.", completion = "Ausgezeichnet! Ihr habt Opfer gebracht, um diese Abzeichen zu verdienen, und dafür sollt Ihr auch entsprechend Anerkennung finden. Abenteurer wie Ihr, &lt;Name&gt;, machen einen wahren Unterschied.\n\nKommt zu mir, wenn Ihr weitere Abzeichen abgeben möchtet, ich helfe Euch gerne dabei, sie einzutauschen.", rewards = nil},
[85987] = {title = "Ein Belobigungsabzeichen", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[85988] = {title = "Ein Belobigungsabzeichen", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[86160] = {title = "Zehn Belobigungsabzeichen", objective = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Außenseiter im Laufe ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass Ihr beträchtliches Ansehen bei der Holzschlundfeste erhaltet. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf nur geringfügig verbessern.\n\nGenug geredet! Ich würde nur zu gerne Eure Abzeichen entgegennehmen.", description = nil, progress = "Ich nehme Belobigungsabzeichen entgegen, die sich tapfere Außenseiter im Laufe ihrer Pflichterfüllung verdient haben. Für je zehn Abzeichen sorge ich dafür, dass Ihr beträchtliches Ansehen bei der Holzschlundfeste erhaltet. Zwar nehme ich auch einzelne Belobigungsabzeichen entgegen, doch würde das Euren Ruf nur geringfügig verbessern.\n\nGenug geredet! Ich würde nur zu gerne Eure Abzeichen entgegennehmen.", completion = "Ausgezeichnet! Ihr habt Opfer gebracht, um diese Abzeichen zu verdienen, und dafür sollt Ihr auch entsprechend Anerkennung finden. Außenseiter wie Ihr, &lt;Name&gt;, können einen echten Unterschied machen.\n\nKommt zu mir, wenn Ihr weitere Abzeichen abgeben möchtet, ich tausche sie gerne gegen mehr Ansehen ein.", rewards = nil},
[86161] = {title = "Zehn Belobigungsabzeichen", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil},
[86326] = {title = "Wüstenmacht", objective = "Sprecht mit Selestrasza, um Euren Qirajiresonanzkristall zu erhalten.", description = "Die tiefen und finsteren Tunnel zu den uralten Orten der Welt eignen sich nur schlecht für Eure Reise.", progress = nil, completion = "Eure Macht ist nicht unbemerkt geblieben, sterbliches Wesen. Nutzt diesen gezähmte Silithiden, um Eure Reise in das uralte Reich der Qiraji zu beschleunigen.", rewards = "Ihr bekommt:\n\nGezähmte Silithidendrohne"},
[86442] = {title = "Nefarians Verderbnis", objective = "Tötet Nefarian und bringt den roten Szeptersplitter wieder in Euren Besitz. Bringt den roten Szeptersplitter zu Anachronos in den Höhlen der Zeit in Tanaris. Euch bleiben 5 Stunden, um diese Aufgabe zu erfüllen.", description = "Held, seid Ihr es? Es ist tausend Jahre her, seitdem man mir den Splitter anvertraut hat. Jetzt, in meiner finstersten Stunde soll jemand erscheinen, um ihn mir zu nehmen... aber was wäre eine Tragödie ohne Grausamkeit?\n\n<Vaelastrasz hustet geschwächt.>\n\nNe... Nefarian besitzt nun den Szeptersplitter.\n\nDie Zeit ist knapp. Nefarian hat vor, den Splitter zu zerstören. Ihr müsst Euch beeilen!Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGamaschen mit OnyxeinbettungAmulett der Schattenabwehr\n\nIhr bekommt außerdem:\n\n"},
[86443] = {title = "Der Alptraum offenbart sich", objective = "Verteidigt Nighthaven gegen Eranikus. Bewahrer Remulos darf dabei nicht ums Leben kommen und Eranikus darf nicht getötet werden. Verteidigt Euch. Erwartet Tyrande.", description = "Wir müssen gegen Eranikus mit Bedacht vorgehen. Wir sollen ihn erlösen, nicht vernichten.\n\nTyrande ist bereits auf dem Weg, um uns bei dieser Aufgabe zu unterstützen. Wir müssen die Attacken des Drachen überstehen und Nighthaven vor der sicheren Zerstörung bewahren.\n\nSeid auf der Hut! Ihr und Eure Verbündeten seid unsere einzige Hoffnung.", progress = nil, completion = "Er ist erlöst, &lt;Name&gt;. Jetzt kehrt er in den Traum zurück, um zu richten, was er alleine zerstört hat. Eranikus wird ein mächtiger Verbündeter Malfurions und meines Vaters sein.\n\nDiese Rüstungsteile sind für Euch, &lt;Name&gt;; Ysera selbst hat sie mir gegeben. Ihr würdet gut daran tun, wenn Ihr sie bei Euren Kämpfen gegen die Qiraji einsetzen würdet.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nDrachenzahnhalsketteZwangsarbeiterstiefel\n\nIhr bekommt außerdem:\n\n"},
[86444] = {title = "Der einzige Weg", objective = "Findet die 8 verlorenen Kapitel von \"Drachisch für Dummies\" und vereint sie mit dem magischen Bucheinband. Bringt das vollständige Buch \"Drachisch für Dummies: Band 2\" dann zu Narain Soothfancy in Tanaris.", description = "Ich hätte es wissen müssen. Mein Erzfeind, Doktor Weavil, hat wieder seine dreckigen Finger im Spiel! Jetzt, nach Eurem Versagen in Winterspring, hat Doktor Weavil mein Buch zerstört! Wie wollt Ihr jetzt die Welt retten?\n\nDie Nachricht, die ich erhalten habe, gab an, dass die einzig bekannte Kopie von \"Drachisch für Dummies: Band 2\" in 8 Teile zerrissen und im Wind zerstreut wurde! Solltet Ihr diese fehlenden Kapitel irgendwie finden können, dann verwendet diesen magischen Bucheinband, um sie wieder zusammenzuflicken. Kehrt dann zu mir zurück.", progress = "Ich mach's genauso wie Ihr - und wenn, dann mache ich es richtig... und sollte es sich anbieten, dann mache ich Arkanitbojen. Arkanitbojen, Baby!", completion = "Fantastisch! Ich kann nicht glauben, dass Ihr Euch diese Mühe gemacht habt! Seid Ihr so eine Art Maschine? Wenn es nach mir ginge, hätte ich die Welt wahrscheinlich ganz einfach implodieren lassen.\n\nIch ziehe meinen Turban vor Euch, holde Dame. Keine gute Tat soll unbezahlt bleiben.", rewards = "Ihr bekommt:\n\nTurban der gnomischen Superpsychokräfte"},
[86445] = {title = "Der Zorn von Neptulon", objective = "Benutzt die Arkanitboje am wirbelnden Maelstrom in der Bucht der Stürme in Azshara.", description = "Hatte ich die schlechte Neuigkeit schon zur Sprache gebracht? Sein Name ist \"Der weiße Riese\": Einhundert Meter Tod und Zerstörung pur. Den kleinen Leckerbissen hatte ich glatt vergessen.\n\nMeinen gnomischen Superpsychokräften nach zu urteilen, befindet sich der beste Ort, um diese Boje zu platzieren, an der Küste Azsharas in der Bucht der Stürme.\n\nHaltet nach einem wirbelnden Strudel Ausschau. Vermutlich ist die ganze Gegend mit Wrackteilen übersät.\n\nMacht es gut und nehmt ein paar Freunde mit.\n\nFalls Ihr die ganze Sache wie durch ein Wunder überleben solltet, bringt den Szeptersplitter zu Anachronos.", progress = "Die Zeit läuft uns davon, große Heldin!", completion = "Gut gemacht, &lt;Name&gt;. Schon bald werde ich das Szepter der Sandstürme wieder zusammensetzen können.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand der eisigen TiefenDunkelwasserroben\n\nIhr bekommt außerdem:\n\n"},
[86449] = {title = "Der Schatz des Zeitlosen", objective = "Seid gegrüßt, große Heldin! Ich bin Jonathan, der Bewahrer des heiligen Gongs und ewige Wächter des bronzenen Drachenschwarms.\n\nDer Zeitlose hat mich dazu ermächtigt, Euch aus seinem Schatz einen Gegenstand Eurer Wahl zu gewähren. Möge er Euren Kampf gegen C'Thun erleichtern.", description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFangzahn von KorialstraszShadowsongs KummerRunenschwert des RotenRavencrests Vermächtnis\n\nIhr bekommt außerdem:\n\n"},
[86670] = {title = "Der Retter von Kalimdor", objective = "Bringt das Auge von C'Thun zu Anachronos in den Höhlen der Zeit.", description = "Begebt Euch zu den Höhlen der Zeit, <Lord/Lady> <Name>. Anachronos erwartet Eure Rückkehr. Übergebt ihm das Auge von C'Thun. Sicherlich wird er es der Sammlung seines Meisters hinzufügen wollen.", progress = "Lord <Name>! Es ist vollbracht...", completion = "Der Meister hat dies für Euch zurückgelassen, großer Held. Aus dem zeitlosen Schatz: Eine Sammlung verschiedenster Artefakte, über Tausende von Jahren zusammengetragen. Ihr habt die Wahl!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAmulett des gefallenen GottesUmhang des gefallenen GottesRing des gefallenen Gottes\n\nDer folgende Zauber wird auf euch gewirkt:\n\nBrut Nozdormus Fraktion +1000\n\nIhr bekommt außerdem:\n\n"},
[86671] = {title = "Imperiale Qirajiinsignien", objective = "Merithra des Traums im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen. Bringt ihr dazu imperiale Qirajiinsignien und 3 Einheiten Elementiumerz.", description = "Arygos hat die Theorie aufgestellt, dass das Element, welches während des Konflikts zwischen den Alten Göttern und ihren Anhängern entstanden ist, unter den richtigen Bedingungen für sie tödlich ist. Ich spreche vom Elementium, <Sterblicher/Sterbliche>.\n\nFindet und bringt mir imperiale Qirajiinsignien sowie das giftige Element, dann werde ich Euch Waffen von größter Macht erschaffen!Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesegneter Akolythenstab der QirajiGesegneter Weissagungsstab der QirajiGesegneter Qirajikriegshammer"},
[86672] = {title = "Imperiale Qirajiwaffen", objective = "Arygos im Tempel von Ahn'Qiraj wird Euch mit Elementium erfüllte Ausrüstung herstellen, wenn Ihr ihm imperiale Qirajiwaffen und 3 Einheiten Elementiumerz bringt.", description = "Wir haben hier nicht ein Jahrtausend in völliger Untätigkeit verbracht, <Name>.\n\nWir sahen mit eigenen Augen, wie sich diese Biester an ihren eigenen Artgenossen gütlich taten, nachdem diese ihre Nützlichkeit für den Schwarm verloren hatten. Wir lauschten, als sie ihre Pläne schmiedeten, diese Welt in Schutt und Asche zu legen. Und wir lernten, wie sich Verrat und Missgunst in ihren Reihen ausbreiten.\n\nSie haben Schwächen und wir wissen nun, wie wir diese zu unserem Vorteil nutzen können.\n\nFindet und bringt mir ihre Zeremonienwaffen. Zusammen mit dem durch ihren Gott erschaffenen Element werden wir daraus mächtige Instrumente der Zerstörung erschaffen.", progress = "Findet, worum ich Euch gebeten habe, und Ihr werdet weit mehr als nur die Summe Eurer Teile werden, großer Held.", completion = "Jetzt, da diese Waffen mit Elementium erfüllt sind, werden sie sich mit Leichtigkeit durch jeden Qiraji und ihren Gott schneiden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGesegnete QirajikriegsaxtGesegnete QirajimusketeGesegneter QirajipugioGesegneter Qirajischild"},
[86673] = {title = "Der Untergang von Ossirian", objective = "Bringt den Kopf von Ossirian dem Narbenlosen zu Kommandant Mar'alith auf Burg Cenarius in Silithus.", description = "Eine schreckliche Bedrohung hat ihr Ende gefunden. Der grausame Ossirian existiert nicht mehr.\n\nDie Bewohner Kalimdors werden aufatmen, wenn sie von diesem glorreichen Sieg erfahren. Nehmt Ossirians Kopf und bringt ihn zu Kommandant Mar'alith auf Burg Cenarius.", progress = "Ah, <Name>. Wie ich sehe, seid Ihr zurückgekehrt und sogar in einem Stück! Welche Neuigkeiten bringt Ihr aus Ahn'Qiraj?", completion = "Ich entbiete Euch meine höchste Anerkennung und erlaube es Euch, einen Gegenstand von höchster Macht auszuwählen, &lt;Name&gt;! Ihr habt den Bewohnern von Kalimdor einen großen Dienst erwiesen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nGlücksbringer der SandstürmeAmulett der SandstürmeHalsschmuck der SandstürmeAnhänger der Sandstürme\n\nIhr bekommt außerdem:\n\n"},
[86674] = {title = "Das perfekte Gift", objective = "Dirk Thunderwood in der Burg Cenarius will, dass Ihr ihm Venoxis' Giftbeutel und Kurinnaxx' Giftbeutel bringt.", description = "Mein Bruder und ich sind im Ravenholdt-Anwesen für den Giftbedarf zuständig.\n\nLord Ravenholdt hat mich damit beauftragt, eine neue und extrem effektive Giftmischung zusammenzustellen, die aus den Giftbeuteln der Bewohner von Zul'Gurub und den Ruinen von Ahn'Qiraj gewonnen werden kann.\n\nEs gibt in diesen verfluchten Ruinen zwei ganz besonders giftige Bestien, die vielleicht genau das haben, wonach wir suchen, <Klasse>. Bringt mir einen Giftbeutel der Bestien Kurinnaxx und Venoxis und wir wären Euch ewig dankbar.", progress = "Alleine packt Ihr das nicht, <Name>. Ihr werdet Kameraden mitbringen müssen.", completion = "Ravenholdt dankt Euch, Held! Sucht Euch was aus!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRavenholdtschnitzlerShivsprokets MesserDonnerholzschüreisenSchicksalsbringerFahrads selbstladende RepetierarmbrustSimones Hammer der Kultivierung\n\nIhr bekommt außerdem:\n\n"},
[86675] = {title = "Schlachtrüstung des Kriegsfreiwilligen", objective = "Bringt 5 cenarische Gefechtsabzeichen, 3 cenarische Versorgungsabzeichen und 7 cenarische Strategieabzeichen zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf beim Zirkel des Cenarius.", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Burg Cenarius erhalten habt, dienen zu weit mehr als der Angeberei, <Name>.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHandschuhe der ErdstärkeBand des ErdzornsErdgewebeumhang"},
[86676] = {title = "Schlachtrüstung des Veteranen", objective = "Bringt 7 cenarische Gefechtsabzeichen, 4 cenarische Versorgungsabzeichen und 4 cenarische Strategieabzeichen zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Burg Cenarius erhalten habt, dienen zu weit mehr als der Angeberei, <Name>.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nErdanmutBand der ErdmachtErdmachtweste"},
[86677] = {title = "Schlachtrüstung des Gefolgsmanns", objective = "Bringt 15 cenarische Gefechtsabzeichen, 20 cenarische Versorgungsabzeichen, 17 cenarische Strategieabzeichen und 1 Mal von Remulos zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Windruferin Proudhorn erhalten habt, dienen zu weit mehr als der Angeberei, <Name>.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTiefsteinarmschienenKugel der ErdruheFelszornarmschienenMacht des Cenarius"},
[86678] = {title = "Schlachtrüstung des Feldherren", objective = "Bringt 15 cenarische Gefechtsabzeichen, 20 cenarische Versorgungsabzeichen, 20 cenarische Strategieabzeichen und 1 Mal des Cenarius zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Burg Cenarius erhalten habt, dienen zu weit mehr als der Angeberei, <Name>.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFaust des CenariusZorn des CenariusErdschlag\n\nIhr bekommt außerdem:\n\n"},
[86679] = {title = "Eingehüllt in Alpträume", objective = "Sucht nach jemandem, der die Bedeutung des in Alpträume gehüllten Gegenstands entschlüsseln kann.\n\nVielleicht kann Euch ein Druide von großer Macht weiterhelfen.", description = "Verderbtheit umgibt dieses Objekt.\n\nVielleicht gibt es eine Verbindung zwischen diesem Gegenstand und den aus dem Traum vordringenden Drachen. Sucht nach jemandem, der die Bedeutung dieses Gegenstands entschlüsseln kann. Vielleicht können Euch die Druiden aus Moonglade oder auf Burg Cenarius weiterhelfen.", progress = "Ja, <Volk>?", completion = "Ich muss diesen Gegenstand zuerst von seiner Verderbnis reinigen. Möglicherweise gibt er mir Aufschluss darüber, warum es mir zuletzt unmöglich war, in den Smaragdgrünen Traum einzutauchen. Bitte, gebt ihn mir.", rewards = "Ihr bekommt:\n\n"},
[86680] = {title = "Legenden erwachen", objective = "Wartet, bis Bewahrer Remulos in Moonglade den von Alpträumen eingehüllten Gegenstand gereinigt hat.", description = "Das Wasser des Elune'ara Sees wird die Alpträume auflösen, die den Gegenstand umgeben. Bitte, gebt mir einen Moment, um die Reinigung durchzuführen, <Name>.", progress = "Ihr habt gesehen, was Ihr sehen müsst!", completion = "Nehmt diesen Ring, &lt;Name&gt;. Er hat seinen Zweck für Malfurion erfüllt. Er soll nun Euch dienen...", rewards = "Ihr bekommt:\n\nMalfurions Siegelring"},
[86724] = {title = "Staub zu Staub", objective = "Findet 5 Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit Apotheker Quinard beim Lager der Horde in der Nähe des Regalschwarmbaus.", description = "Leiht mir Euer Ohr, <Name>. Die Wunden des Captains werden immer schwerer. Das Lager feiert jeden Sieg mit dem üblichen Jubel, doch ich kann mich dieser Freude nicht anschließen. Nicht, wenn ich die Wunden sehe, die er unter seiner Rüstung verbirgt.\n\nEine Infektion? Nein, ich würde sagen, dass viel eher einer... einer Infestation gleicht. Ich arbeite an einer Zubereitung, doch eine letzte, aber wichtige Zutat fehlt mir: Silithyst.\n\nIch brauche es. Und zwar schnell. Wenn ich mir den Zustand des Captains so ansehe, fürchte ich, dass er ohne ein Heilmittel nicht mehr lange durchhält.", progress = nil, completion = "Exzellent. Ihr habt alles gefunden. Und zwar gerade noch rechtzeitig. Ich werde mich sofort daran setzen, das Mittel für Captain Krug zuzubereiten.\n\nIch kann Euren Wagemut leider nicht mit Münzen belohnen, doch ich kann Euch an meinem Wissen teilhaben lassen. Ich bin gewillt, Euch gegen einen kleinen Preis die Notizen zu überlassen, mit deren Hilfe ich die Soldaten verarztet und ihre Bäuche gefüllt habe.", rewards = nil},
[86725] = {title = "Staub zu Staub", objective = "Findet 5 Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit Chefexpeditionslieferant Enkles beim Lager der Allianz in der Nähe des Zoraschwarmbaus.", description = "Ach ja, die Gefahren der Wüste. Nein, nicht die Bullenhitze, nicht die gnadenlosen Sonnenstrahlen, nicht der Sand, der in alle Ritzen und Falten Eurer Roben kriecht, nicht die klirrend kalten Nächte.\n\nDie anderen Gefahren! Die Käfer und jetzt noch diese lästigen Grobiane. Unsere Aufklärungstrupps berichten, dass die Horde Dreck sammelt.\n\nNormalerweise wäre das nichts Besonderes für sie, aber Silithyst? Es wäre mir lieber, wenn sie die Geheimnisse des Sandes nicht ergründen. Als Chefexpeditionslieferant beantrage ich eine konkurrierende Lieferung! Besorgt mir diesen Dreck!", progress = "Was macht Ihr hier noch, <Name>? Mein Voraussichtsstrank hat mir gezeigt, dass Ihr die Person für diesen Auftrag seid!\n\nWir haben es geschafft, die Essenz der Silithuskristalle in einen Trank zu destillieren, der dem Anwender für kurze Zeit die Fähigkeit der Voraussicht verleiht.\n\nAch, entschuldigt bitte, doch ich habe noch nicht die Befugnis, Euch diese Tränke zur Verfügung zu stellen.", completion = "Sehr gut, &lt;Name&gt;! Erlaubt mir kurz, diese Transaktion in meinen Büchern festzuhalten...\n\nUnd das wäre es. Falls wir andere Lieferprobleme haben, werde ich sie an Euch weiterleiten. Und als Chefexpeditionslieferant erwarte ich Unterstützung.\n\nIch habe leider nicht die Befugnis, Euch zu bezahlen, doch ich habe mir diese Position nicht verdient, indem ich meine Untergebenen nicht anständig entlohne! In meinem Besitz befinden sich viele Rezepte, die angefordert, aber nie ausgeliefert wurden. Als Belohnung genehmige ich Euch, Exemplare aus meinem Bestand an Lektüren mit verlorenem Wissen käuflich zu erwerben.", rewards = nil},
[86760] = {title = "Bestienkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Bestienkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt wo Ihr alle Karten des Bestienkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Blauer Drache"},
[86761] = {title = "Kriegsherrenkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Kriegsherrenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt wo Ihr alle Karten des Kriegsherrenkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Heldentum"},
[86762] = {title = "Elementarkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Elementarkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt wo Ihr alle Karten des Elementarkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Maelstrom"},
[86763] = {title = "Portalkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Portalkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt wo Ihr alle Karten des Portalkartensets beisammen habt, erscheint urplötzlich eine neunte Karte, die in ihrem Aussehen den anderen acht sehr ähnlich ist. Auf der Vorderseite ist folgender Satz zu lesen: \"Gebt diese Karten auf dem Dunkelmond-Jahrmarkt ab und Ihr werdet reich belohnt.\" Soweit Ihr es wisst, gastiert der Jahrmarkt alle paar Monate abwechselnd in Mulgore und in Goldhain, also werdet Ihr erst einmal warten müssen, bis dieser wieder stattfindet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nDunkelmond-Karte: Wirbelnder Nether"},
[86964] = {title = "Für Gold und Ehre!", objective = "Offenbar sucht jemand nach Abenteurern, die etwas Wertvolles aus den Karazhangruften am Gebirgspass der Totenwinde bergen können. Es ist nicht bekannt, wer diesen Aushang gemacht hat oder wo man die Auftraggeber finden kann, aber die Aussicht auf eine beträchtliche Belohnung von einer angesehenen und finanzstarken Gruppe wie den Kirin Tor sowie auf einen Schatz, der nur darauf wartet, geborgen zu werden, ist zugegebenermaßen sehr reizvoll.\n\nReist zum Gebirgspass der Totenwinde und untersucht die Gruften hinter dem Karazhan-Turm.", description = "An alle Abenteurer und Schatzsucher! Hiermit wird bekannt gegeben, dass die Kirin Tor die Auszahlung beträchtlicher Gelder an all jene genehmigt hat, die imstande sind, in die Gruften unter Karazhan hinabzusteigen und ein bestimmtes magisches Artefakt zu bergen. Alle anderen geborgenen Schätze, Kuriositäten oder Münzen haben für den Orden keine Bedeutung und können als zusätzliche Entschädigung behalten werden. Interessenten melden sich bitte bei... \n\n<Der untere Teil dieser Notiz wurde abgerissen und die restlichen Details fehlen.>", progress = nil, completion = "Diese vor Euch liegende Person ist tatsächlich ziemlich tot. Sie scheint keine offensichtlichen Wunden oder andere Verletzungen aufzuweisen. Das einzig Auffällige an der Leiche ist der Ausdruck höchster Furcht in ihrem Gesicht. Fast so, als wäre diese Frau vor Schreck gestorben...", rewards = nil},
[86965] = {title = "Keine natürlichen Schatten", objective = "Die vom Eingang der Gruft eindringende Finsternis scheint sich allen Gesetzen von Logik und Vernunft zu entziehen. Keinerlei Licht dringt ein oder kann diese Finsternis vertreiben, und kein Licht im Inneren scheint ihr entkommen zu können. Ihr habt den dringenden Verdacht, dass Euer eigentlich geplantes Betreten der Gruft auf direktem Wege Euer Ende sein könnte.\n\nIhr müsst einen Weg finden, diese Dunkelheit zu überwinden, wenn Ihr vorankommen wollt. Ihr erinnert Euch, dass sich in einem Lager im Norden eine Agentin von Dalaran befindet. Vielleicht weiß sie mehr über den toten Abenteurer und diese merkwürdige Dunkelheit?", description = "Eine plötzliche und beklemmende Dunkelheit legt sich über Euch, als ihr Euch hinkniet. Ihr bemerkt, dass alles Licht in der Nähe dunkler und schwächer zu werden scheint, als würde die Dunkelheit nach Euch greifen. Dies sind keine natürlichen Schatten. \n\nEin kurzer Blick zum Eingang der nahe gelegenen Gruft genügt, um zu erkennen, dass diese bösartige Dunkelheit von der Gruft selbst ausgeht und sie mit ihren tintenschwarzen Ranken nach mehr Licht sucht, das sie auslöschen kann. Ihr erschaudert, und Euch stellen sich die Nackenhaare auf.", progress = nil, completion = "&lt;Agentin Keanna schaut zu Euch auf und runzelt etwas die Stirn.&gt;\n\nSchaut, ich habe der letzten Gruppe, die hierher kam, schon gesagt, dass ich keine Informationen über die Gruften habe. Und das gleiche gilt für die Belohnung, die mein Orden auf den verfluchten Schatz ausgesetzt hat, der unter dem alten Turm liegt. Diese Angelegenheiten liegen nicht in meinem Fachgebiet, und ich bin nicht befugt, im Namen des Ordens größere Ausgaben zu leisten.\n\nWenn es sonst nichts gibt, würde ich gerne zu meiner Forschung zurückkehren.", rewards = nil},
[86966] = {title = "Die Überlebenden suchen", objective = "Sucht nach eventuellen Überlebenden der unseligen Abenteurergruppe und versucht, so viel wie möglich über die Geschehnisse in der Gruft herauszufinden.", description = "Oh, ich verstehe. Ja, die Leiche, die Ihr gefunden haben wollt, scheint tatsächlich meiner Erinnerung einer der Abenteurer zu entsprechen, die vor Kurzem hier vorbeigekommen sind. Soweit ich mich erinnere, waren sie zu fünft. Ich habe ihnen dringend davon abgeraten, noch weiter zu gehen, aber sie ließen sich nicht davon abbringen. Offenbar waren meine Warnungen begründet, denn seitdem habe ich keinen von ihnen mehr gesehen. Ich befürchtete das Schlimmste und, nun ja...\n\nIhr sagt, sie war die einzige Leiche, die Ihr gefunden habt? Wenn das wahr ist, gibt es vielleicht doch noch andere Überlebende irgendwo auf dem Pass?", progress = nil, completion = "Der Mann rührt sich leicht, als Ihr Euch nähert. Er öffnet fast unmerklich ein einzelnes Augenlid, um Euch anzusehen. Zunächst schien er schwer verletzt zu sein, aber jetzt seid Ihr Euch nicht mehr ganz sicher...", rewards = nil},
[86967] = {title = "Zur Hilfe", objective = "Findet den Schlüssel zum Käfig in der Höhle der Totenwindoger und befreit den verletzten Abenteurer darin.", description = "<Das geöffnete Auge des Mannes sieht Euch direkt an.>\n\nPst, hey Ihr. Ja, Ihr! Glaubt Ihr, Ihr könnt mich hier rausholen? Ich liege hier schon seit Stunden herum und stelle mich tot. Aber es ist nur eine Frage der Zeit, bis diese verdammten Oger sich daran erinnern, dass ich hier bin, und dann kommen, um mich aufzufressen oder mir noch Schlimmeres anzutun!\n\nDieser Käfig ist ziemlich gut verriegelt, aber einer dieser Grobiane müsste einen Schlüssel haben. Seht doch mal nach, ob Ihr einen finden könnt, und lasst mich dann raus. Ich würde dann auf jeden Fall in Eurer Schuld stehen.\n\nIch werde mich weiter tot stellen, während Ihr Euch an die Arbeit macht. Und jetzt geht... Aber leise!", progress = nil, completion = "Wie um Azeroths willen bin ich, blutend und mit einer Gehirnerschütterung, vor Euch hier angekommen?\n\n&lt;Harrison Jones schüttelt den Kopf.&gt;\n\nSeid Ihr sicher, dass Ihr dem gewachsen seid?", rewards = nil},
[86968] = {title = "Angst vor der Dunkelheit?", objective = "Hört Harrison Jones zu, während er Euch erzählt, was sich in den Karazhangruften zugetragen hat.", description = "Ich kann Euch wirklich nicht genug für Eure Hilfe danken. Ihr habt mir wirklich den Allerwertesten gerettet.\n\nIch habe mich mit dieser netten jungen Dame unterhalten, während ich auf Euch gewartet habe. Und ich glaube, sie weiß vielleicht, wie Ihr in diese trostlose Gruft gelangen könnt, wenn Ihr unbedingt Euer Glück herausfordern wollt.\n\nAber ich greife gerade etwas vor. Ich glaube, ich schulde Euch zunächst noch ein paar Informationen.", progress = nil, completion = "Offenbar ist es Jones' Gruppe also gelungen, in die Gruft einzudringen und dort einen beträchtlichen Schatz zu finden. Die Dunkelheit, die Ihr beide beschrieben habt, scheint tatsächlich magischer Natur zu sein. Ganz offensichtlich haben ihre stümperhaften Plünderungsaktivitäten etwas Bösartiges zum Leben erweckt.\n\nIch habe in meinem Zauberfolianten nachgeschlagen und glaube, dass ich Euch vielleicht einen Weg durch die Dunkelheit zeigen kann, falls Ihr Euch immer noch mutig genug fühlt, weiterzumachen. Kommt, lasst uns diese Angelegenheit näher besprechen.", rewards = nil},
[86969] = {title = "Die Hypothese", objective = "Seht Euch die Liste der benötigten Materialien an und bringt Agentin Keanna die erforderlichen Komponenten.", description = "Ich denke, ich kann eine Art magisches Totem herstellen, mit dem Ihr diese bösartige Dunkelheit durchdringen und zumindest die Gruften erkunden könnt. Ich habe jedoch nicht alle Komponenten zur Hand. Einige davon sind vielleicht schwer zu finden, aber nach dem, was ich bisher von Euch gesehen habe, vertraue ich darauf, dass Ihr findig genug seid, das Benötigte zu beschaffen.", progress = "Habt Ihr die benötigten Komponenten finden können?", completion = "Ausgezeichnet. Diese Bindung ist ziemlich simpel, ich muss nur kurz... So! Ich denke, das sollte gehen.\n\nDiese magische Fackel sollte es Euch ermöglichen, die bösartige Dunkelheit zu durchdringen, um zumindest die Gruft zu sehen und zu erkunden. Seid jedoch gewarnt, denn das Irrlicht, das diesem Gegenstand innewohnt, hat seinen eigenen Willen. Ich habe es zwar an dieses Objekt und diesen bestimmten Zweck gebunden, aber ich vermag nicht vorherzusagen, wie es sich verhalten wird, wenn Ihr die Gruft erreicht.\n\nSeid auf der Hut, wenn Ihr ankommt. Niemand weiß, was geschehen wird.", rewards = nil},
[86970] = {title = "Überprüfung der Hypothese", objective = "Begebt Euch zum Eingang der Karazhangruften, benutzt die verzauberte Feuerbrandfackel und schaut, was passiert. Kehrt zu Agentin Keanna zurück, nachdem Ihr den Test abgeschlossen habt.", description = "Ich denke, es ist klug, dass wir dieses Gerät erst einmal testen, bevor Ihr in die Dunkelheit der Gruften eintaucht. Bringt die Fackel an den Rand der magischen Dunkelheit und aktiviert sie. Findet heraus, ob sie ihren Zweck erfüllt und für Beleuchtung sorgt. Und findet vor allem heraus, wie sie sich verhält, wenn sie dieser Magie ausgesetzt ist.\n\nDieses Totem ist an einen bestimmten Zweck gebunden und sollte somit gezwungen sein, sich an diesen Zweck zu halten. Aber das lässt sich erst betätigen, wenn wir dort sind und diese Hypothese überprüfen.", progress = "Was hat der Test ergeben?", completion = "Das sind doch gute Nachrichten. Die Fackel hat nicht nur erfolgreich die schwächere Dunkelheit außerhalb der Gruft vertrieben, sondern durch die Bindung wurde sie auch in die Gruft getrieben, um dort weiter ihren Zweck zu erfüllen.\n\nNachdem die bösartige Dunkelheit außerhalb der Gruft verschwunden ist, könnt Ihr sie sicher betreten. Der Geschichte dieses Mannes nach zu urteilen, ist ungewiss, was Ihr im Inneren vorfinden werdet, also seid vorsichtig.\n\nViel Glück.", rewards = nil},
[86971] = {title = "Kuriose Karazhankuriositäten!", objective = "Bringt Harrison Jones am Gebirgspass der Totenwinde eine Karazhankuriosität.", description = "Jetzt, da Ihr einen Weg in die Gruft gefunden habt, möchte ich Euch um einen Gefallen bitten. Nur zum Verständnis: Ich bin Archäologe und arbeite für die Königliche Bibliothek von Sturmwind. Ich sammle Artefakte und Relikte aus aller Welt für akademische Zwecke und Studien und bin sehr an jeglichen Kuriositäten interessiert, die Ihr in den Tiefen der Gruft finden könntet. Bringt mir alles, was Ihr als interessant erachtet, und ich werde Euch gut entlohnen.", progress = "Was habt Ihr für mich, <Name>?", completion = "Das ist ein großartiges Fundstück! Für den Fall, dass Ihr noch mehr solcher Artefakte findet, bringt sie mir hierher. Ich werde dafür sorgen, dass Ihr für Eure Bemühungen angemessen entschädigt werdet.", rewards = "Ihr bekommt:\n\nVorratstasche"},
[86972] = {title = "Kuriose Karazhankuriositäten!", objective = "Bringt Harrison Jones am Gebirgspass der Totenwinde eine Karazhankuriosität.", description = "Jetzt, da Ihr einen Weg in die Gruft gefunden habt, möchte ich Euch um einen Gefallen bitten. Nur zum Verständnis: Ich bin Archäologe und arbeite für die Königliche Bibliothek von Sturmwind. Ich sammle Artefakte und Relikte aus aller Welt für akademische Zwecke und Studien und bin sehr an jeglichen Kuriositäten interessiert, die Ihr in den Tiefen der Gruft finden könntet. Bringt mir alles, was Ihr als interessant erachtet, und ich werde Euch gut entlohnen.", progress = "Denkt daran: Ich bin auf der Suche nach allen Artefakten oder Schätzen, die Ihr finden könnt. In dieser Gruft gibt es unermessliche Kostbarkeiten, also haltet die Augen offen!", completion = "Das ist ein großartiges Fundstück! Für den Fall, dass Ihr noch mehr solcher Artefakte findet, bringt sie mir hierher. Ich werde dafür sorgen, dass Ihr für Eure Bemühungen angemessen entschädigt werdet.", rewards = "Ihr bekommt:\n\nVorratstasche"},
[87283] = {title = "Die lila Tasche", objective = "Sucht Erzmagier Tarsis Kir-Moldir auf und bringt ihm die lila Tasche zurück.", description = "Ihr habt eine kleine lila Tasche gefunden, die das Zeichen der Kirin Tor aufweist. Trotz Eurer Anstrengungen scheint es unmöglich, die Tasche zu öffnen und zu sehen, was sich darin befindet. Der Zettel, den Ihr bei dem Abenteurer gefunden habt, deutet darauf hin, dass sie dem Erzmagier Kir-Moldir von Dalaran gehört. Es könnte sich für Euch lohnen, den Erzmagier aufzusuchen und ihm seinen Besitz zurückzugeben... und die versprochene Belohnung einzufordern.", progress = "Der Erzmagier scheint Euch nicht zu hören...", completion = "Was habt Ihr da? Ist das... Ist das möglich?\n\n&lt;Der Erzmagier entreißt Euch hastig die Tasche. Er flüstert eine Beschwörungsformel und leert den Inhalt in seine Hände. Dabei kommen zwei kleine rote Edelsteine zum Vorschein.&gt;\n\nDie Augen! Ja, die Augen! Ich habe sie! Danke. Bitte, lasst mich jetzt allein... Jetzt geht schon! Verschwindet, bevor ich gezwungen bin, Euch zu vernichten!\n\n&lt;Der entschlossene Blick in seinen Augen verrät Euch, dass er es ernst meint. Während Ihr Euch zurückzieht, wendet sich der Erzmagier ab, beugt sich vor und drückt die Edelsteine fest an seine Brust.&gt;", rewards = nil},
[87360] = {title = "Der Niedergang Kel'Thuzads", objective = "Bringt Kel'Thuzads Phylakterium zur Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Das Phylakterium ist alles, was vom Herrscher Naxxramas' übrig bleibt. Nach Eurem pflichtgemäßen Ermessen, müsstet Ihr das Phylakterium zerstören, um somit einem erneuten Aufbäumen des Lichs vorzubeugen. Glücklicherweise hört Ihr nur selten auf Eure innere Stimme der Vernunft.\n\nBei der Kapelle des hoffnungsvollen Lichts wird Euch irgendjemand mit Sicherheit ein Vermögen für dieses Artefakt bezahlen. Wen kümmert es schon, ob Kel'Thuzad eines Tages wieder von Neuem erstarkt?", progress = "HEILIGES LICHT! Was ist denn in Euch gefahren, Junge?", completion = "Ich hätte mir nie erträumt, dass ich das eines Tages mal zu Gesicht bekommen sollte...\n\n&lt;Vater Montoy scheint lüstern zu geifern.&gt;\n\nOh ja, Ihr sollt entlohnt werden, mein Junge. Reichlich entlohnt. Gebt es mir. Jetzt!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMal des HeldenMal des Helden\n\nIhr bekommt außerdem:\n\n"},
[87361] = {title = "Zur Ruhe gebettet", objective = "Findet heraus, ob Euch jemand in der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern helfen kann.", description = "Das dem Schatten der Verdammnis entnommene Herz pulsiert schwach und vibriert.\n\nAls Ihr es in Eure Tasche stecken wollt, überkommt Euch ein überwältigendes Gefühl von Wut, Angst, Furcht und dann... Traurigkeit.\n\nWährend diese Gefühle abklingen, habt Ihr das Gefühl, als hättet Ihr gerade ein anderes Leben gelebt.\n\nVielleicht kann jemand in der Kapelle des hoffnungsvollen Lichts etwas Licht in das bringen, was Ihr gerade gefühlt habt.", progress = "Ihr müsst nichts erklären, <Name>.\n\nEure Anwesenheit hier und diese Kugel sagen mir alles, was ich wissen muss.\n\nDie Dunkelheit hat Euch auf die Probe gestellt, <Name>.\n\nIhr habt Glück gehabt. Mit der Geißel und ihren Flüchen ist nicht zu spaßen.\n\nDas Licht folgt Euch.", completion = "So gut wie niemand, der diese verfluchten Gegenstände berührt, ist noch im Besitz seiner geistigen Kräfte.\n\n&lt;Obwohl sein Gesichtsausdruck unverändert bleibt, laufen ihm Tränen über das Gesicht, als Ihr ihm das Herz überreicht.&gt;\n\nAh... Hier will jemand nicht loslassen. Diese Person entstammt der &lt;Klasse&gt;-Klasse... so wie Ihr...\n\n&lt;Name&gt;, wenn Ihr bereit seid, eine solche Bürde zu tragen, kann ich Euch vielleicht helfen. Ich kann diese unruhige Seele in Eure Rüstung eingravieren...\n\nGenau wie das Gewicht der Welt trägt sich eine Seele am besten auf den Schultern.", rewards = "Ihr bekommt:\n\nÜberreste der Tapferkeit"},
[87362] = {title = "Hoffnung beginnt in der Dunkelheit", objective = "Erhaltet das Siegel der Dämmerung.", description = "Naxxramas stellt eine Bedrohung dar, wie Ihr sie nie zuvor erlebt habt. Es ist der Sitz der Macht Kel'Thuzads und birgt Schrecken, die selbst den kampferprobtesten Kriegern der Argentumdämmerung unbekannt sind.\n\nNehmt dieses Siegel.\n\nWenn Ihr Euch in die Nekropole wagt, tragt Ihr die Last unserer Hoffnungen, <Name>. Es ist also nur recht, dass Ihr auch unsere Stärke tragt.", progress = nil, completion = "Dieses Siegel verstärkt die Ausrüstung, die ihr in Naxxramas erbeutet.\n\nVerliert es nicht aus den Augen und nutzt es gut.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAspirantensiegel der DämmerungAspirantensiegel der DämmerungAspirantensiegel der Dämmerung"},
[87364] = {title = "Den Sack zumachen", objective = "Sammelt die Überreste des Heldenmuts in Naxxramas ein.", description = nil, progress = "Ehrlich gesagt gibt es vielleicht eine Möglichkeit, die Kraft Eures Siegels zu steigern, <Name>.\n\nWenn man die Überreste mächtiger Gefolgsleute der Geißel aufbereitet, wird ein kleiner Teil der heiligen Energie nicht nur bewahrt, sondern auch verarbeitungsfähig gemacht. Diese Energie kann zu Stärke geschmiedet werden.\n\nDringt tiefer in Naxxramas ein und bringt mir die Überreste dieser Gefolgsleute der Geißel. Im Gegenzug kann ich Euer Siegel stärken.", completion = "Das war gute Arbeit, &lt;Name&gt;.\n\nIch frage mich, wie viele davon von unseren gefallenen Brüdern stammen? Waren sie noch irgendwo da drin? Ich tröste mich mit der Annahme, dass es ihr Wunsch wäre, dass wir andere davon abhalten, so zu werden wie sie. Auch wenn das nur ein schwacher Trost ist.\n\nLast mich jetzt Euer Siegel stärken.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nInitiandensiegel der DämmerungInitiandensiegel der DämmerungInitiandensiegel der Dämmerung"},
[87365] = {title = "Mut erwächst durch Wagemut", objective = "Sammelt die Überreste des Heldenmuts in Naxxramas ein.", description = nil, progress = "Es ist noch ein langer Weg, bis Euer Siegel sein volles Potenzial erreicht. Bringt mir mehr Überreste des Heldenmuts, und ich werde Euch weiterhin mit der Kraft versorgen, unsere Welt zu beschützen.\n\nDenkt daran, dass die Toten keine Gerechtigkeit einfordern können. Es ist die Pflicht der Lebenden, dies für sie zu tun.", completion = "Gut gemacht. Das wird auch dieses Mal nicht lange dauern.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKnappensiegel der DämmerungKnappensiegel der DämmerungKnappensiegel der Dämmerung"},
[87366] = {title = "Ritterzeit", objective = "Sammelt die Überreste des Heldenmuts in Naxxramas ein.", description = nil, progress = "Jeder getötete Diener der Geißel ist eine befreite Seele, <Name>. Vergesst niemals, dass Ihr das Richtige tut. Selbst wenn, nein, besonders dann, wenn der Kampf hoffnungslos erscheint. Solange wir uns widersetzen, können die Armeen des Lichkönigs uns nicht aufhalten.\n\nIhr scheint das Vorgehen verinnerlicht zu haben. Besorgt mir mehr Überreste, und ich werde Euer Siegel erneut stärken.", completion = "Die Gerechtigkeit trachtet nicht nach Belohnung, &lt;Name&gt;.\n\nAber Ihr schon. Bitte nehmt dies.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRittersiegel der DämmerungRittersiegel der DämmerungRittersiegel der Dämmerung"},
[87367] = {title = "Ein neues Licht", objective = "Erhaltet das Siegel der Dämmerung.", description = nil, progress = "Jedes Mal, wenn wir Euer Siegel stärken, kommen wir dem Ende von Kel'Thuzads Vorstoß einen Schritt näher.\n\nWenn Ihr stark bleibt, werden wir Azeroth im Handumdrehen vom Lichkönig und seinen Gefolgsleuten befreit haben.", completion = "Ihr seid eine Heldenlegende, &lt;Name&gt;. Der Aschenbringer selbst wäre beeindruckt.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nTemplersiegel der DämmerungTemplersiegel der DämmerungTemplersiegel der Dämmerung"},
[87368] = {title = "Ein Produkt des Glaubens", objective = "Erhaltet das Siegel der Dämmerung.", description = nil, progress = "Mich schaudert es bei dem Gedanken an die Schrecken, denen Ihr ausgesetzt wart, um so weit zu kommen. Ihr seid ein Vorbild für die Argentumdämmerung, und ich kann nur beten, dass Ihr uns weiterhin auf diese Weise unterstützt.\n\nBringt mir mehr Überreste des Heldenmuts und ich werde Euer Siegel stärken. Ich glaube, es liegt noch ein weiter Weg vor Euch, bevor Ihr Euer volles Potenzial ausschöpfen könnt.", completion = "Gut gemacht, &lt;Name&gt;. Die Gefallenen zu läutern, wäre für sich genommen schon die Mühe wert, selbst wenn keine Belohnung versprochen wäre.\n\nAber das gilt natürlich nicht für Euch! Nehmt Euer frisch gestärktes Siegel.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nChampionsiegel der DämmerungChampionsiegel der DämmerungChampionsiegel der Dämmerung"},
[87369] = {title = "Kultivierter Glaube", objective = "Erhaltet das Siegel der Dämmerung.", description = nil, progress = "Ich hätte nie gedacht, dass der Scharlachrote Kreuzzug und die Argentumdämmerung ihre Differenzen beilegen und für ein gemeinsames Ziel kämpfen könnten. Und doch sind wir hier.\n\nIhr habt wieder und wieder bewiesen, dass sich das Risiko gelohnt hat. Bringt mir mehr Überreste des Heldenmuts, Champion. Ich habe das Gefühl, dass wir kurz davor stehen, Kel'Thuzad und seinen Schergen den Todesstoß zu versetzen.", completion = "Ich kann Euch nicht genug danken. Aber ich beweise meine Dankbarkeit, indem ich Euer Siegel stärke.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nVorhutsiegel der DämmerungVorhutsiegel der DämmerungVorhutsiegel der Dämmerung"},
[87377] = {title = "Keine Zeit der Ruhe", objective = "Bringt Bruder Luctus in der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern ein weiteres Herz der Verdammnis.", description = "Bringt mir alle verlorenen Seelen, die Euren Weg kreuzen, <Name>.\n\nOder besser gesagt: Ihr MÜSST sie mir bringen.\nMEINE Pflicht ist es, hierzubleiben und die Seelen der Verlorenen zu führen. EURE Pflicht ist es, sie mir zu bringen.\n\nUnd lasst Euch gesagt sein: Kümmert Euch nie um mehr als eine Seele auf einmal. Glaubt mir, Eure Seele kann nur eine bestimmte Menge von ihnen verkraften, und Euer Verstand... nun ja... noch weniger.\n\nDiese Bürde lastet nun auf Euch. Weil Ihr es könnt, müsst Ihr es tun.\n\nBetrachtet es als moralische Verpflichtung.", progress = "Da die Geißel niemals ruht, dürfen wir es auch nicht, <Name>.", completion = "&lt;Name&gt;, jedes wiedergefundene Herz erfüllt mich mit Demut. Einige dieser Seelen stammen von mächtigen Kriegern. Einige schienen unbesiegbar zu sein... und doch... sind sie gefallen.\n\nDie Geißel hat sie überwältigt, die Verderbnis hat sich in ihren Köpfen festgesetzt, und in einigen Fällen haben sie sich ihr sogar bereitwillig unterworfen.\n\nEine so große Stärke... einfach ausgemerzt.\n\nAber jetzt wahren sie dank Eurer Hilfe ihren letzten Rest an Tapferkeit.\n\nOhne Euch würden die Schrecken ihres Todes die Heldentaten ihres Lebens überwiegen.", rewards = "Ihr bekommt:\n\nÜberreste der Tapferkeit"},
[87433] = {title = "Plattenhandschuhe der Argentumdämmerung", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nStulpen des UntotenschutzesStulpen der UntotenläuterungStulpen des Untotenschlachtens"},
[87434] = {title = "Plattenhandschuhe der Argentumdämmerung", objective = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", description = nil, progress = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Nehmt den von Euch gewählten Handschutz als Dank für Eure Mühen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nStulpen des UntotenschutzesStulpen der UntotenläuterungStulpen des Untotenschlachtens"},
[87435] = {title = "Kettenhandschuhe der Argentumdämmerung", objective = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", description = nil, progress = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Nehmt den von Euch gewählten Handschutz als Dank für Eure Mühen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHandschützer der UntotenläuterungHandschützer des UntotenschutzesHandschützer der UntotenbekämpfungHandschützer des Untotenschlachtens"},
[87436] = {title = "Kettenhandschuhe der Argentumdämmerung", objective = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", description = nil, progress = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Nehmt den von Euch gewählten Handschutz als Dank für Eure Mühen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHandschützer der UntotenläuterungHandschützer des UntotenschutzesHandschützer der UntotenbekämpfungHandschützer des Untotenschlachtens"},
