[89262] = {title = "Zeigt, was Ihr könnt: Stiefel", objective = "Stellt scharlachrote Stiefel mit einem beliebigen Handwerksberuf her oder spendet ein beliebiges Teil einer Scharlachroten Uniform.\n\nWenn Ihr etwas spenden wollt, könnt Ihr eine Kiste in der Nähe des Rüstmeisters in der Kaserne finden. Bringt das Ausrüstungsteil zu Byron Steelblade, um Anerkennung zu erhalten.", description = "Immer auf dem neuesten Stand zu sein, ist wichtig, wenn man eine hohe Qualität beibehalten will. Unsere Soldaten vertrauen ihre Leben namenlosen Handwerkern an, und damit mir, denn ich stelle die Qualität jedes Rüstungsteils sicher.\n\nIch habe eine ganz simple Aufgabe für Euch: Wenn Ihr geübt in Schneiderei, Lederverarbeitung oder Schmiedekunst seid, dann stellt ein Paar Schuhe her, einfach für Euch selbst. Ihr könnt das Ergebnis behalten.\n\nWenn Euch das Können fehlt, dann könnt Ihr ein beliebiges Stück der Uniform des Kreuzzugs in Auftrag geben und es stattdessen spenden.", progress = "Stellt selbst etwas her oder spendet etwas, die Wahl liegt bei Euch. Unsere Waffenkammer ist prall gefüllt und wir sind auf das Schlimmste vorbereitet, aber das Wichtigste ist, dass unsere Handwerker genug Gelegenheit zum Üben und Verfeinern ihrer Technik haben.", completion = "Ausgezeichnete Arbeit.\n\nWir haben damit begonnen, konfiszierten Schrott in diesen alten Truhen zu lagern, aber langsam geht mir der Platz hier aus. Ihr seht mir wie jemand aus, der Wert auf die kleinen Dinge im Leben legt. Für Euren kleinen Beitrag dürfte dies eine angemessene Belohnung sein.\n\nOh, und einige davon enthalten eine kostbare Überraschung. Vielleicht ist das Glück Euch ja hold?", rewards = "Ihr bekommt:\n\nScharlachrote Plunderkiste"},
[89310] = {title = "Schreckenstal", objective = "Reist nach Schreckenstal und findet Leonid Barthalomew in einem der Häuser dort.", description = "Es dauerte viele Jahre, bis ich mich von meiner Schuld erholen konnte, nachdem mein Geist aus den Fesseln des Lichkönigs gelöst wurde. Nachdem Sylvanas mich befreite, lehnte ich das Angebot der Dunklen Fürstin ab und ging allein in die Pestländer. Ich wanderte monatelang, ziellos. Ich bin nicht sicher, wie es dazu kam, aber letztendlich zog es mich zum Zuhause meiner Familie zurück, und was ich dort fand, war... unerwartet.\n\nReist zum Geisterdorf Schreckenstal und trefft mich dort im nördlichsten Haus. Dort werdet Ihr alles erfahren.", progress = nil, completion = "Es widert mich an, wozu mein Heim verkommen ist.", rewards = nil},
[89328] = {title = "Verlust", objective = "Hört Euch das Ende von Leonids Geschichte an.", description = "Ihr könnt Euch sicher vorstellen, wie überrascht ich war, als ich ihn nach all den Jahren des ziellosen Herumirrens hier fand, vor allem lebendig und wohlauf. Im Gegensatz zu den anderen Lebenden verstieß er mich nicht, sondern hieß mich willkommen. Er war ein Heiler geworden, der die Untoten studierte, und er war überzeugt, dass er ein Heilmittel finden könnte, um den Untod nicht nur zu verhindern, sondern ihn sogar rückgängig machen zu können. \n\nFür kurze Zeit waren wir zusammen und glücklich. Ich half meinem Sohn bei seinen Forschungen, und er gab mir die Hoffnung, die ich brauchte.\n\nZumindest bis Baelin Caldoran sich wieder in unser Leben einmischte.", progress = nil, completion = "Zu meiner Schande habe ich überlebt. Es hat nicht lange gedauert, bis Lord Tyrosus mich fand und wieder zusammenflickte.\n\nZweimal war Baelin Caldoran verantwortlich für den Tod von jemandem, der mir sehr nahe stand. Seine Art von überheblichem Eifer und Fanatismus bezeichnet das Herz der Korruption, die den Scharlachroten Kreuzzug plagt.\n\nIch werde mich nie mehr von dem Schmerz erholen, doch ich ehre meinen Sohn, indem ich seine Hoffnung und Vision für eine Zukunft forttrage, in der der Fluch des Untods geheilt werden kann. Ich muss hoffen, dass eines Tages jemand die Arbeit meines Sohnes vollenden kann.", rewards = "Ihr bekommt:\n\n"},
[89329] = {title = "Den Befall niederstampfen", objective = "Erschlagt 5 Gruftwandler und 8 Gruftbestien und kehrt dann zu Leonid Barthalomew dem Geachteten in seinem ehemaligen Zuhause im Schreckenstal zurück.", description = "Widerwärtig. Dieser Ort ist von verrottenden Neruberdrohnen befallen. Sie sollten vernichtet werden.", progress = nil, completion = "Es ist höchstwahrscheinlich nur eine bedeutungslose Geste, aber ich fühle mich wenigstens ein winziges Bisschen besser.", rewards = "Ihr bekommt:\n\n"},
[89340] = {title = "Bescheuert beschrifteter Brief", objective = "Überbringt die letzte Lieferung.", description = "An die verehrte Chefköchin von Neu-Avalon, Carrie Herdfeuer. \n\nIch hoffe, dieser Brief erreicht Euch frohen Mutes! Eure Abreise aus Hearthglen hinterließ eine große Leere in unseren Herzen und unseren Bäuchen. Es vergeht kein Tag ohne Beschwerde über den Haferbrei und die Sehnsucht nach der nächsten köstlichen Mahlzeit.\n\nDaher planen wir ein Bankett, eines, auf dem wir nur die besten Gerichte von ganz Lordaeron servieren: Eure.\n\nEine bewachte Karawane wird in zwei Wochen eintreffen, damit Ihr und Eure Gerichte bestmöglich vorbereitet seid.", progress = nil, completion = "&lt;Carrie nimmt auf Euer Drängen hin endlich den Brief und überfliegt den Inhalt. Ihre Augen werden groß.&gt;\n\nWie soll ich für ein ganzes Bataillon des Scharlachroten Kreuzzugs die Zutaten sammeln und Mahlzeiten zubereiten? Und dazu noch in nur zwei Wochen? Das kommt wirklich zur schlechtesten Zeit.\n\nSo oder so, die Bürger von Neu-Avalon gehen vor. Bis dahin muss ich wohl auf eine helfende Hand hoffen.\n\n&lt;Sie macht eine Pause.&gt;\n\nMoment, warum war der schon geöffnet?", rewards = nil},
[89341] = {title = "Das große Festmahl", objective = "Helft Carrie Herdfeuer in Neu-Avalon ein letztes Mal, indem Ihr die folgenden Zutaten sammelt:", description = "Eure Unterstützung ist unbezahlbar. Die Bürger und Soldaten von Neu-Avalon können sich heute Abend und viele weitere Abende auf ein warmes Essen freuen. Ich danke Euch von Herzen.\n\nDoch wie Ihr offensichtlich selbst gelesen habt, muss ich mich noch um eine weitere Aufgabe kümmern, bevor ich die Füße hochlegen kann. Das meiste davon schaffe ich selbst, aber wenn Ihr mir noch einen Gefallen tun möchtet, würde ich Euch zum Lohn meine berühmtesten Rezepte beibringen.\n\nIhr werdet jeden Abend wie ein Hochlord speisen.", progress = "Ah, wie schön Euch wiederzusehen! Habt Ihr die letzte Zutatenlieferung dabei, die ich brauche?", completion = "Schnell und zuverlässig wie immer. Ich hätte nie an Euch zweifeln dürfen. Lasst mich Euch das abnehmen.\n\nIch weiß zwar noch immer nicht, was Euch dazu antreibt, aber Ihr habt auf jeden Fall ein gütiges Herz. Wie versprochen habt Ihr hier mein Kochbuch. Ich brauche es nicht mehr, ich kenne alle meine Rezepte schon lange auswendig!\n\nDanke vielmals, kommt jederzeit wieder vorbei!\n\n&lt;Carrie schenkt Euch ein aufrichtiges, entspanntes Lächeln und macht sich wieder an die Arbeit.&gt;", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFleckfinnenfestmahlGroßes Hummerbankett\n\nIhr bekommt außerdem:\n\nCarries KochbuchWeihsalzErlesene Gewürze"},
[89342] = {title = "VIP-Mitgliedschaft im Gourmetclub", objective = "Bereitet eigenhändig ein Morgengrauenomelett und ein Pirschersteak zu und serviert beides Devon Woods vor dem Gasthaus von Neu-Avalon.", description = "He, Ihr da!\n\nIhr seht aus, wie die Person, von der Carrie in letzter Zeit so viel redet. Sie hat nur Gutes über Euch gesagt. Nun, anfangs noch nicht, aber sie hat schnell ihre Meinung geändert.\n\nWie auch immer, Freunde der Köchin sind auch meine Freunde. Ich möchte Euch eine dauerhafte Mitgliedschaft anbieten, dann müsst Ihr auch diese Karte nicht immer herumtragen.\n\nAls Gegenleistung bitte ich Euch nur um ein Morgengrauenomelett und ein Pirschersteak. Beides von Euch zubereitet, versteht sich.", progress = "Habt Ihr mein Essen?", completion = "&lt;Ohne Umschweife nimmt er einen Bissen von beiden Gerichten.&gt;\n\nOha, Carrie hat Konkurrenz. Sie muss Euch alle ihre Techniken beigebracht haben. Das überrascht mich, ich konnte sie nie dazu bewegen, mir irgendetwas beizubringen.\n\nDanke. Ich habe Euren Namen bereits zu den permanenten VIP-Gästen unserer Einrichtung hinzugefügt. Ihr könnt von nun an kommen und gehen, wie es Euch beliebt, und ganz ohne Mitgliedskarte. Vorausgesetzt, Ihr tut nichts, was unsere Gäste verschrecken könnte.", rewards = nil},
[89381] = {title = "Nadelkissen", objective = "Sammelt Pfeile auf dem Schießplatz südlich vom Stadtplatz von Neu-Avalon. Ihr könnt auch Pfeile im Kampf mit Waldläufern erbeuten.", description = "Oooh! Ganz schön mutig von Euch, während unseres Trainings auf dem Schießplatz herumzulaufen. Ihr fordert es ja geradezu heraus, ein Geschoss ins Knie zu bekommen, oder vielleicht ins Hinterteil, so wie Ihr hier herumtanzt.\n\nAber Eure Sicherheit ist Eure Sache. Da Ihr offenbar das Risiko sucht, wollt Ihr uns vielleicht zur Hand gehen? Das Aufsammeln der Pfeile nach jeder Runde kostet viel wertvolle Übungszeit.\n\nWir wäre es, wenn Ihr ein paar für mich einsammelt?Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMuster: Scharlachroter Köcher"},
[89421] = {title = "Kugelhimmel", objective = "Stellt Thoriumpatronen her oder kauft welche von einem Spielercharakter mit Ingenieursberuf, und bringt sie zu Kyndra Swiftarrow beim Schießplatz von Neu-Avalon.", description = "Ihr denkt vielleicht: \"Aber was, wenn ich lieber einen Munitionsbeutel hätte\", oder \"wenn ich etwas sage, wird sie mich dann auch in einen Kugelhagel stellen?\" Ich kann zwar nicht Eure Gedanken lesen, aber ein guter Waldläufer muss vorausschauend denken.\n\nDie Wahrheit ist, dass wir hier keine Kugeln verschießen, obwohl ich mich stets dafür ausspreche. Aber falls, sagen wir, ein Haufen Patronen vor meinen Füßen erscheinen würde, hätte ich wohl keine andere Wahl, als einen angemessenen Beutel für deren Aufbewahrung zu entwerfen.\n\nWenn doch nur...Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMuster: Scharlachroter Munitionsbeutel"},
[89445] = {title = "Klingen des Lichts", objective = "Findet einen Schmied, der Euch mehr über die zerstörte lichtgeschmiedete Klinge sagen kann.", description = "Selbst zerstört und zerbrochen erkennt Ihr, dass Ihr ein wahrhaft beeindruckendes Schwert vor Euch habt. Wenn Ihr das Material versteht, aus dem diese Klinge geschmiedet wurde, könntet Ihr möglicherweise eine wahrhaft einzigartige Waffe daraus herstellen. Doch erst müsst Ihr einen fähigen Schmied finden, der seine Eigenschaften bestimmen und einen Weg finden kann, das Material zu bearbeiten.", progress = "Wie? Ich habe keine Zeit, mit Euch zu plaudern! Diese Brustpanzer hämmern sich nicht von selbst!", completion = "Oooh! Das ist aber mal ein beeindruckendes Schwert, das Ihr da habt!\n\nIhr sucht nach jemandem, der dieses Material bearbeiten kann? Hm, nun, ich sage es nur ungern, aber die Geheimnisse dieses Materials zu lüften, übersteigt vermutlich meine Fähigkeiten. Wenn nur Omarion hier wäre. Er war der hiesige Handwerksmeister und absoluter Experte in Sachen exotische Materialien und Legierungen. Er wäre perfekt für sowas. Das einzige Problem ist, dass er verschwunden ist!\n\nSollte er noch am Leben sein, wäre er Eure beste Adresse!", rewards = "Ihr bekommt:\n\n"},
[89446] = {title = "Der verschwundene Handwerker", objective = "Findet Meisterhandwerker Omarion", description = "<Handwerker Wilhem scheint Euch nicht helfen zu können, aber er empfahl Euch seinen früheren Meister, einen Mann namens Omarion. Solltet Ihr ihn finden, könnte er vielleicht mehr über dieses Material wissen.>", progress = "<Omarion starrt ausdruckslos an Euch vorbei.>", completion = "Ich verstehe. Niemand sucht nach mir, außer sie brauchen etwas. Schon gut, schon gut. Ich muss ohnehin nicht gerettet werden. Ich sterbe gerne genau hier, an diesem lichtverlassenen Ort. Lasst mich einfach hier zurück.", rewards = "Ihr bekommt:\n\n"},
[89447] = {title = "Extravaganter Geschmack", objective = "Bringt Meisterhandwerker Omarion in Naxxramas zehn Portionen \"Dirges abgefahrene Chimaerokkoteletts\".", description = "Ihr habt also ein ziemlich ungewöhnliches Stück Metall. Wen interessiert's?\n\nOh, ich soll Euch mehr darüber erzählen? Nun, es ist ein Schwert, und es ist kaputt. War es das jetzt?\n\n<Omarion starrt Euch finster an, dann seufzt er tief, als Ihr keine Anstalten macht, zu gehen.>\n\nNa gut. Lasst das Schwert hier, dann sehe ich es mir an. Während ich das tue, könnte ich vielleicht etwas zu Essen vertragen. Ich kannte einst einen Goblin, Dirge Quikcleave. Er macht die besten Chimaerokkoteletts. Bringt mir einige.", progress = "Wie sich herausstellt, ist es nicht gerade eine Priorität untoter Entführer, einen zu ernähren. Nicht, dass es mich kümmern würde. Ich wäre hier gut und gerne verhungert, aber da Ihr mich nicht in Frieden lassen wollt, könntet Ihr mir wenigstens eine ordentliche Henkersmahlzeit bringen.", completion = "Das war genau das Richtige, &lt;Klasse&gt;.\n\nAlso, zu dem Schwert. Es ist... tatsächlich sehr eindrucksvoll. Es strahlt Hitze aus, die Schneide behält ihre Schärfe beinahe übernatürlich gut, und sie scheint die Untoten abzuschrecken, was man daran sieht, dass kein einziger Zombie mehr vorbei kam und versucht hat, mich zu essen, seit Ihr mich damit allein gelassen habt.\n\nZu schade, wirklich. Zombies sind nicht die besten Gesprächspartner, aber an einem Ort wie diesem nimmt man, was man kriegen kann.", rewards = "Ihr bekommt:\n\n"},
[89448] = {title = "Sammeln des Lichts", objective = "Bringt zwölf Barren lichtgeschmiedetes Eisen zu Meisterhandwerker Omarion in Naxxramas und deckt auf, wo der Scharlachrote Kreuzzug diese neuen Waffen herstellt.", description = "<Omarion wirkt erheblich lebendiger als bei Eurer ersten Begegnung mit ihm.>\n\nAlso gut, <Klasse>, Ihr habt mein Interesse geweckt. Dieses Metall ist absolut einzigartig und ich würde gerne weiter damit experimentieren. Aber dafür brauche ich weitere Proben des Rohmaterials. Bringt mir etwa ein Dutzend Barren von diesem \"lichtgeschmiedeten\" Eisen und versucht, mehr darüber herauszufinden, wo diese Waffen hergestellt werden. Ein Schmied ist immerhin nur so gut wie sein Werkzeug und seine Werkstatt.", progress = "Ich wünschte, ich hätte etwas Kaja'Cola zu diesen Koteletts. Oh, Ihr habt noch nie von Kaja'Cola gehört? Solltet Ihr je die Gelegenheit haben, welche zu probieren, wird das Euer Leben verändern.", completion = "Die sollten genügen. Was habt Ihr noch auf Eurem Ausflug erfahren?\n\n&lt;Ihr erzählt Omarion von der Strahlenden Schmiede, die Ihr in der Scharlachroten Enklave gefunden habt.&gt;\n\nSehr interessant, es gibt also einen lichterfüllten Amboss in der Scharlachroten Enklave, wo sie diese Waffen herstellen?\n\nNun, dann führt nichts daran vorbei. Ich werde mir diese Schmiede persönlich ansehen müssen. Ich werde wohl davon absehen müssen, an diesem grässlichen Ort zu sterben.", rewards = "Ihr bekommt:\n\n"},
[89463] = {title = "Verschwiegenheitserklärung", objective = "Zischlunte in Neu-Avalon hat nach einer Schreibfeder und etwas, das sein Versteck gemütlicher macht, gebeten. Eine schicke Schreibfeder kann im Rathaus von Neu-Avalon gefunden werden, und in der Nähe von Scholomance oder den Karazhangruften könnt Ihr ein Requisitenhaus finden.", description = "Ich bin kein solcher Goblin, der seine Geheimnisse mit irgendwelchen dahergelaufenen Abenteurern teilen. Aber ich BIN einer, der die Geheimnisse eines Gnoms teilt! Zufälligerweise konnte ich auf meinem Weg hierher einige Baupläne in die Finger bekommen und ich arbeite daran, die Mängel in den Entwürfen auszuarbeiten. Sie nutzen immer noch Sicherheitslunten! Könnt Ihr das fassen? SICHERHEITSLUNTEN!\n\nWie dem auch sei, ich teile meine Fortschritte gerne mit Euch, aber ich brauche eine Schreibfeder, wenn ich den ganzen Kram aufschreiben soll. Und ich könnte ein gemütliches Fleckchen brauchen, an dem ich in Ruhe nachdenken kann. Was sagt Ihr dazu?", progress = "Ah, Ihr seid es! Ich bin schon gespannt, was Ihr mir gebracht habt.", completion = "Wisst Ihr, ich weiß nicht ganz, was ich erwartet habe, aber gewiss nicht... das. Ich schätze, es passt zu den Bäumen. Ich sollte mich nicht beschweren, hauptsächlich, weil ich am Schluss anfangen würde zu schreien, und das will keiner von uns beiden.\n\nViel wichtiger ist die Feder! Ich habe vergessen zu erwähnen, dass mir die Tinte ausgegangen ist, aber ein wenig Motoröl sollte da Wunder wirken.\n\n&lt;Zischlunte prüft die Tauglichkeit der Feder mit einem grob skizzierten Bauplan.&gt;\n\nSo, bitte sehr.", rewards = "Ihr bekommt:\n\nBauplan: Aufstellbäumchen"},
[89471] = {title = "Goblin-Tüftelei", objective = "Zischlunte in Neu-Avalon hat Euch eine Einkaufsliste mit technischen Teilen für seine Erfindungen gegeben. Besorgt diese und bringt sie zu ihm.", description = "Ich würde sagen, unsere Geschäftsbeziehung ist inzwischen fest etabliert. Ich hab den Grips, Ihr habt die Muckis. Das ist großartig, weil ich vor dreißig Sekunden gemerkt habe, dass mir einige wichtige Teile fehlen!\n\nHier habt Ihr eine Liste von Dingen, die ich diesen Plänen zufolge brauche, abgesehen von dem ganzen Gnomenschrott. Bis dahin kümmere ich mich darum, diese Pläne zu überarbeiten. Sobald Ihr zurück seid, können wir loslegen!", progress = "Ihr habt Euch Zeit gelassen, ich dachte schon, dieser Scharlachrote Kreuzzug hätte Euch erwischt. Habt Ihr alles, worum ich gebeten habe?", completion = "Ich hätte wissen sollen, dass Ihr meine Einkaufsliste auf eine geschickte Weise ignoriert. Wie soll ein Goblin hierzulande etwas zwischen die Zähne bekommen? Egal.\n\nIhr freut Euch sicher zu hören, dass ich den Bauplan für meine neueste Erfindung fertiggestellt habe: Die Tüftlerkiste! Dieses Gerät an sich ist unscheinbar, aber das ist ja der Sinn der Sache! Ihr müsst nur einige sorgfältig kalibrierte Teile in die hintere Schalttafel einsetzen und dann, wenn Ihr bereit seid, drückt Ihr auf den großen, roten Knopf!\n\nWas dann passiert? Das findet Ihr am besten selbst heraus!", rewards = "Ihr bekommt:\n\nBauplan: Tüftelkiste"},
[89485] = {title = "Launische Schrecken", objective = "Schleicht Euch verkleidet an Bürger von Neu-Avalon an und gebt ihnen einen Portiporter. Sobald Ihr Euch davon überzeugt habt, dass es nicht zum sofortigen Tod führt, nutzt das Gerät selbst, um das Problem zu identifizieren, von dem Zischlunte gesprochen hat.", description = "So sehr mir der Gedanke auch gefällt, Euch als Versuchsobjekt für meine Erfindungen zu nutzen, bin ich mir bei dieser nicht ganz sicher. Sie sollte Euch eigentlich einige Meter nach vorn teleportieren, aber als ich den ersten Prototyp mit einem Stock gepikst hatte, ist er einfach verschwunden und hat den Stock mitgenommen!\n\nIch habe seitdem einige Anpassungen an mehreren Geräten gemacht. Ich habe gesehen, wie Ihr Euch unter die Einheimischen hier gemischt habt. Vielleicht könnt Ihr sie ja dazu überreden, ihn auszuprobieren. Und wenn Ihr Euch dann mutig genug fühlt, testet ihn gerne selbst.", progress = nil, completion = "Wie... bitte?! Könnt Ihr das wiederholen?\n\n&lt;Zischluntes Augen werden trüb, nicht vor Schrecken, sondern vor Langeweile.&gt;\n\nIhr sagt also, das Gerät funktioniert, es wird nur irgendwie gestört? Warum bin ich da nicht selbst drauf gekommen! Das ergibt total Sinn. Ich habe keine Ahnung, wie es zu reparieren ist, aber es ergibt Sinn.\n\nHier ist der Bauplan, bastelt ruhig daran herum. Ich bin sicher, er beschreibt schon fast das großartigste Kurzstrecken-Transportgerät aller Zeiten.", rewards = "Ihr bekommt:\n\nBauplan: Tüftelkiste: Teleportation"},
[89486] = {title = "Eine Prise Schießpulver", objective = "Erreicht die folgenden Orte in Neu-Avalon innerhalb des Zeitlimits.", description = "Ich bin sicher, Ihr wollt dringend wissen, was ich mit dem Schießpulver vorhabe.\n\nHabt Ihr je von Nitroboostern gehört? Nicht Nitropuster. Sondern Booster. Wenn Ihr ja sagt, seid Ihr ein Lügner, weil sie noch nicht erfunden wurden. Bis jetzt!\n\nIch möchte Euch die Ehre erweisen, sie auszutesten. Ihr müsst nur hier ein wenig Schießpulver reintun und den Knopf drücken. Wenn Ihr noch schneller sein wollt, nehmt mehr Schießpulver!\n\nTestet sie auf jeden Fall auf unterschiedlichem Untergrund, bevor Ihr zurückkommt.", progress = nil, completion = "Schön! Ihr habt es bis auf einige Verbrennungen unversehrt zurückgeschafft. Ich glaube, wir sind uns einig, dass dieser Testlauf ein voller Erfolg war. Ich würde sogar sagen, wir können das mit mehr Schießpulver noch verbessern!\n\nDanke für die Daten. Ich wusste, Ihr enttäuscht mich nicht. Hier ist der Plan für Eure ganz eigenen Nitrobooster. Ich bestehe darauf, dass Ihr Euren Schießpulververbrauch niedrig haltet. Sonst bekomme ich noch Konkurrenz.", rewards = "Ihr bekommt:\n\nBauplan: Tüftelkiste: Nitrobooster"},
[89487] = {title = "Viel Lärm um Magneten", objective = "Nutzt den Magnetprototyp in Neu-Avalon, um magnetische Teile zu entdecken und anzuziehen. Wenn Ihr Zischluntes Theorie ausreichend bewiesen habt, kehrt zu ihm zurück.", description = "Sogar mit den Vorräten, die Ihr gesammelt habt, kann ich ohne meine Werkstatt nicht viel ausrichten. Ich habe einen Plan ausgeheckt, einen genialen noch dazu, wie wir endlich die Funktionsweise dieser seltsamen Magnetfelder verstehen können. Ich vermute, dass ich mit genug präziser Gobliningenieurskunst eine Methode entwickeln kann, den Abstand zwischen zwei Personen auf ein permanentes Minimum zu reduzieren! Niemand wird mich je wieder ohne ein Geschäft stehen lassen.\n\nUm meine Theorie zu testen, nehmt diesen Prototyp und wedelt ein wenig in Neu-Avalon damit herum. Mit ein wenig Glück findet Ihr vielleicht etwas!", progress = "Wisst Ihr, es ist erfrischend, an etwas zu arbeiten, das mich nicht mit einer signifikanten Chance in ein Häufchen Asche verwandelt. Vielleicht sind die Gnome da doch etwas auf der Spur.", completion = "Es hat funktioniert!? Ich meine, es hat funktioniert! Natürlich hat es das... Uff, ich sollte lernen, immer auf meinen Bauch zu vertrauen.\n\nIhr habt so lange gebraucht, dass ich schon dachte, meine Theorie wäre falsch. Anstatt das Gerät auf die Nutzung gegensätzlicher Polaritäten zu kalibrieren, ist es darauf ausgelegt, einen Energieschub derselben Polarität auszustoßen.\n\nAber zurück ans Zeichenbrett. Hier ist der Plan, falls es zu Eurer Geschäftsstrategie passt, die Leute abzustoßen.", rewards = "Ihr bekommt:\n\nBauplan: Tüftelkiste: Magnetversetzung"},
[89489] = {title = "Erhöhte Beuterate", objective = "Zischlunte in Neu-Avalon verlangt nach vielen Gürteln, und das aus gutem Grund. Die Soldaten von Neu-Avalon könnten eine gute Beschaffungsquelle sein.", description = "Jetzt, da wir wissen, dass meine Erfindungen als eigenständige Geräte funktionieren, ist der nächste logische Innovationsschritt, ihre Wiederverwendbarkeit und Lebensdauer zu verbessern! Ich glaube, dass keiner von uns jedes Mal eine ganze Handvoll Gold wegwerfen will, nur um sich über eine Pfütze zu teleportieren.\n\nIch habe wie immer eine Idee.\n\nGürtel sind ein leidig unterschätzter Ausrüstungsgegenstand und dazu auch noch leicht zu erreichen. Es ergibt Sinn, sie durch wiederverwendbare Geräte zu verbessern, aber erst brauche ich einige Testexemplare. Geht und stehlt ein paar für mich.", progress = "Ich bin bereit loszutüfteln, sobald Ihr mir ein paar Gürtel bringt.\n\nWas? Nein, mein eigener kommt nicht in Frage!", completion = "Während Ihr fort wart, konnte ich ALLE DREI Baupläne für die Gürteltüfteleien fertigstellen! Das ist einerseits sehr beeindruckend, was mich angeht, aber andererseits ziemlich beschämend für Euch.\n\nMir ist auch klar geworden, dass wir bislang ziemliches Glück hatten, dass unser Chaos nicht mehr Aufmerksamkeit von diesen lästigen Menschen auf sich gezogen hat. Jetzt bin ich mir nicht mehr sicher, ob ich diese Gürtel überhaupt noch brauchen werde, da ich mich von nun an ganz auf meine Flucht konzentrieren werde. Aber ich nehme sie trotzdem, um damit eine Sammlung anzufangen. Wer weiß, wozu sie noch gut sein werden.", rewards = "Ihr bekommt:\n\nZischluntes Tüftelhandbuch"},
[89491] = {title = "Ein komplizierter Fluchtplan", objective = "Benutzt das Triangulationssamophlang an drei unpraktischen Orten und verwendet dann Euren extrem sicheren Transporter: Gadgetzan oder Euren Dimensionszerfetzer - Everlook, während Ihr auf der Teleportationsplattform steht, um die Kalibrierung abzuschließen. Kehrt dann zu Zischlunte in Neu-Avalon zurück.", description = "Nun, das hat Spaß gemacht, aber ich glaube, dass unsere Anwesenheit hier nicht mehr erwünscht ist. Ich wollte im Notfall meine neuen Geräte nutzen, um mich aus dem Staub zu machen, aber ich kann nicht mein ganzes neues Zeug auf einmal tragen!\n\nWie Ihr gesehen habt, konnte ich hier nach meiner Ankunft eine Transporterplattform einrichten. Sie muss nur ein wenig kalibriert werden.\n\nNehmt dieses Gerät und verwendet es in der Nähe der Tore, des Bogenschießplatzes und innerhalb des Gasthauses. Dann und nur dann könnt Ihr Euch auf meinen Teleporter stellen und Euren Teleporter nach Gadgetzan oder Everlook nutzen, um ihn anzuwerfen.", progress = nil, completion = "Ihr seid in einem Stück zurück und der Teleporter schnurrt wie ein Orc! Ein Zeugnis wahrer goblinscher Brillanz.\n\nÜbrigens... also ähm... ich war so aufgeregt, den Teleporter zum Laufen zu bringen, dass ich vergessen habe, Euch den Bauplan für eine einfache Rückreise zu geben, als Ihr gegangen seid. Ihr nehmt mir das nicht übel, oder?\n\nWie dem auch sei, jetzt müsst Ihr nur noch Euer eigenes Modul zusammenbauen, um die Rückreisefunktion zu nutzen. Ich selbst gehe zurück, sobald ich meine Sachen gepackt habe. In der Zwischenzeit könnt Ihr jederzeit zu mir kommen, wenn Ihr Teile braucht.\n\nDanke für all Eure Hilfe!", rewards = "Ihr bekommt:\n\nBauplan: Halbwegs sicherer Transporter: Neu-Avalon"},
[89562] = {title = "Mein alter Feind", objective = "Erfahrt mehr über Baelin Caldoran von Leonid Barthalomew dem Geachteten.", description = "Ich hatte gehört, Caldoran wäre in Naxxramas, und befürchtet, dass ich an seiner Seite an die Front gezwungen werden würde, falls die Schlacht eine ungünstige Wendung nehmen sollte.\n\nDie Argentumdämmerung unterstützt zwar Eure Hilfe für die Streitkräfte der Scharlachroten Rückeroberung, aber ich muss Euch dennoch eindringlich warnen: Nehmt Euch vor Baelin Caldoran in Acht. Meine Hände zittern vor Zorn, allein wenn ich daran denke, welche Gräueltaten dieser Mann an den Unschuldigen verübt hat. Ihr dürft ihm NICHT trauen. Bitte, ich flehe Euch an, hört auf meine Worte.", progress = nil, completion = "Das ist alles, was ich im Moment zu dieser Angelegenheit sagen kann. Ich habe Jahre gebraucht, um aus dem dunklen Loch im Inneren meiner Seele hervorzukriechen, nachdem dieser Mann mit mir fertig war.\n\nIm Moment mögen wir vorläufige Verbündete sein, aber ich werde dafür sorgen, dass Caldoran für seine Verbrechen bezahlt... eines Tages. Dieser Schwur bleibt ungebrochen. In der Zwischenzeit seid extrem vorsichtig in Eurem Umgang mit ihm.", rewards = "Ihr bekommt:\n\n"},
[89563] = {title = "Leonids Bürde", objective = "Erhaltet Anweisungen von Lord Maxwell Tyrosus.", description = "Ich habe zufällig Euer Gespräch mit Leonid über Inquisitor Caldoran belauscht. Die wenigen Einzelheiten, die Leonid Euch mitgeteilt hat, sind nur ein mickriger Fetzen der Geschichte, die diese beiden verbindet. Dazu zählt auch das Leid, das Caldoran ihm zugefügt hat. Ich war da, als Leonid an seinem absoluten Tiefpunkt war, und habe ihm geholfen, die Stärke zu finden, sich wieder aufzuraffen.\n\nIch fürchte mich davor, was unsere fortlaufende Zusammenarbeit mit dem Scharlachroten Kreuzzug in Leonid anrichten wird, vor allem wenn er dadurch diesem Mann näherkommen wird.", progress = nil, completion = "Ich behalte die Dinge hier in meinem noch funktionierenden Auge, und Ihr solltet Caldoran nicht aus dem Blick lassen, während Ihr mit den Rückeroberungstruppen zusammenarbeitet. Ich traue keinem unserer \"Verbündeten\", und ich vertraue ihm am wenigsten.\n\nSprecht auch noch einmal mit Leonid. Ich habe ihn um eine Mission gebeten, und es wäre gut, wenn Ihr ihn begleiten könntet. Ich denke, ein wenig Ablenkung von diesem Ort könnte ihm guttun.", rewards = "Ihr bekommt:\n\n"},
[89567] = {title = "Die verunglückte Karawane", objective = "Untersucht Karawanenüberreste des Scharlachroten Kreuzzugs im Pestwald entlang der Straße nach Stratholme und sprecht dort mit Leonid Barthalomew dem Geachteten, wenn Ihr mehr herausgefunden habt.", description = "Lord Tyrosus hat mich gebeten, die Karawanenüberreste des Scharlachroten Kreuzzugs im Pestwald entlang der Straße nach Stratholme zu untersuchen.\n\nJüngsten Berichten zufolge gab es kurz vor dem Schisma in Tyrs Hand großflächige Bewegungen des Kreuzzugs in den gesamten Pestländern. Diese Karawane könnte Hinweise auf ihren Zweck bergen.\n\nUntersucht vor meiner Ankunft die Karawane und versucht herauszufinden, welchen Zweck sie hatte. Ich treffe Euch dort und wir werden das gemeinsam untersuchen.", progress = "An dieser Sache ist definitiv etwas merkwürdig. Konntet Ihr etwas Interessantes in Erfahrung bringen?", completion = "Diese Karawane transportierte also... Seuchenproben aus Naxxramas? Aber warum? Zu welchem Zweck? Wollte der Scharlachrote Kreuzzug die Seuche studieren, um sie zu bekämpfen?", rewards = "Ihr bekommt:\n\n"},
[89568] = {title = "Etwas Neues", objective = "Setzt die neuen Seuchenproben gegen geschwächte Menschenfresserghule, Stichelnarbenschrecken, verfluchte Magier sowie Soldaten und Wärter der Geißel im Pestwald ein und beobachtet ihre Wirkung.", description = "Ich denke, wir müssen mehr über diese neue Seuche erfahren. Sie scheint darauf abzuzielen... Untote und Lebende zu töten? Die Untoten haben eine natürliche Immunität gegen die Seuche des Untodes, zumal sie ihr Ergebnis sind. Aber wenn meine Vermutung stimmt, könnte das hier etwas Neues und Furchtbares sein.\n\nIch verabscheue es, die Untoten hier noch mehr zu quälen, aber wir müssen mehr erfahren, bevor wir zur Kapelle des hoffnungsvollen Lichts zurückkehren.", progress = "So nahe an Stratholme zu sein, gibt mir ein ungutes Gefühl. Nach allem...\n\n<Leonid Barthalomew der Geachtete hält kurz inne und blickt in Richtung Stratholme. Ihr bemerkt, dass seine Hand leicht zittert.>\n\nVergesst es. Es ist nichts.\n\nLasst uns schnell unsere Angelegenheiten hier erledigen, <Name>.", completion = "Die Wirkung dieser Seuchenproben auf die Untoten ist stark und beängstigend. Wenn sie gegen die Verlassenen in den Ruinen von Lordaeron eingesetzt werden würden, könnte das katastrophale Folgen haben.\n\nEs gibt noch einen weiteren Test, den wir durchführen müssen.", rewards = "Ihr bekommt:\n\n"},
[89574] = {title = "Diener des Todes", objective = "Setzt die neuen Seuchenproben gegen die dunklen Beschwörer und Totenbeschwörer in den Östlichen Pestländern ein und beobachtet ihre Wirkung.", description = "Für mich gibt es nichts Verachtenswerteres als die lebenden Agenten des Lichkönigs. Ich verabscheue und verurteile alle, die Recht von Unrecht unterscheiden können und dennoch freien Willens beschließen, dem Tod zu dienen. Nehmt noch einmal die Seuchenproben und testet sie an den lebenden Mitgliedern des Kults der Verdammten in der Nähe.\n\nHabt kein Mitleid mit diesen Monstern und zeigt ihnen kein Erbarmen. Sie haben sich auf die Seite der Verdammnis gestellt, und verdammt sollen sie sein.", progress = "Ich habe diese Forschungsnotizen studiert, und was ich sehe, ist furchterregend.\n\nDer Scharlachrote Kreuzzug hat diese Seuche entwickelt.", completion = "Es ist genau, wie ich vermutet hatte. Diese Seuche hat eine ähnliche Wirkung auf die Lebenden wie auch auf die Toten. Ich befürchte, das verspricht nichts Gutes. Für niemanden.\n\nDie Frage, die sich mir stellt, ist, wie ist es den Scharlachroten Kreuzzüglern gelungen, so eine Seuche zu entwickeln? Sie müssten dazu ein tiefes Verständnis der ursprünglichen Seuche des Untodes haben, und die Forschung an solchen Seuchen ist für die Lebenden... schwierig. Das ist überaus besorgniserregend.\n\nIch nehme an, wir haben hier alles erfahren, was wir konnten. Doch bevor wir zurückkehren... könnte ich Euch um einen Gefallen bitten?", rewards = "Ihr bekommt:\n\n"},
[90107] = {title = "Die neu geformte Klinge", objective = "Tretet etwas zurück, während Meisterhandwerker Omarion versucht, die neugeschmiedete Klinge des Aschenbringers herzustellen.", description = "Ich denke, ich bin mit der Legierung jetzt so weit, dass wir sie zuverlässig für die Herstellung des Klingenrohlings benutzen können. Zum Glück sollten wir mit allem, was Ihr für mich gesammelt habt, reichlich Rohmaterialien dafür haben.\n\nTretet bitte einen Schritt zurück. Die Arbeit in der Schmiede kann... dramatisch sein.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nNeugeschmiedete Klinge des Aschenbringers"},
[90116] = {title = "Heilige Fäden", objective = "Erhaltet Morgengespinststoffe, indem Ihr Stoff in Ballen webt, während Ihr Euch in der Nähe des Webstuhls des Kreuzzüglers aufhaltet. Kehrt zu Taylor zurück, sobald Ihr genug habt.", description = "Dieser Webstuhl ist etwas Besonderes. Wusstet Ihr das? Alle Werkzeuge unserer Handwerker werden von unseren Hohepriestern gesegnet. \n\nBesonders der Webstuhl zieht abtrünnige Stoffe und Fäden an, die für die Verarbeitung zu den heiligsten unserer Zeremoniengewändern bestimmt sind. Mit genügend Zeit sammeln wir genügend davon, um eine neue Robe herzustellen und solche Tage sind Grund zum Feiern, zumindest für mich.\n\nWenn Ihr aus eigener Neugier an dem Prozess interessiert seid, webt einige Stoffballen in der Nähe des Webstuhls und seht, wie das Licht die Arbeit voranführt.", progress = "Normalerweise erfordert es einige größere Projekte wie Hemden oder Hosen, um genug Morgengespinststoffe anzusammeln, aber zu Vorführungszwecken sollten einfache Stoffballen genügen.", completion = "Ausgezeichnet! Natürlich ist das nur ein kleiner Teil einer Robe eines Scharlachroten Abtes, aber ich könnte mir vorstellen, dass Ihr von nun an ein besseres Verständnis Eurer eigenen Handwerkskunst habt.\n\nIch nehme Euch die hier ab und bewahre sie auf. Die Vorlage für die heiligen Roben ist ein streng gehütetes Geheimnis, aber ich möchte Euch stattdessen dieses hier geben. Große und robuste Taschen sind heutzutage ein Luxus, aber die Investition lohnt sich. Wer weiß, vielleicht könnt Ihr mit dem Verkauf der Taschen ein gutes Geschäft machen?", rewards = "Ihr bekommt:\n\nMuster: Kreuzzüglerknappsack"},
[90120] = {title = "Rot ist nicht tot", objective = "Sammelt eine Vielfalt an Materialien, die als kräftiges, rotes Färbemittel dienen könnten. Roter Farbstoff und rote Rosen können bei Händlern erstanden werden. Feuerblüten könnt Ihr von Kräuterkundlern erhalten. Blut von Helden könnt Ihr in den Pestländern finden. Blutrote Klingenblätter zur Herstellung von Farbstoff könnt Ihr in der Nähe des Mennarsees in Azshara sammeln.", description = "Hm, apropos Geheimnisse, ich habe an einem neuen Projekt gearbeitet: Luxustaschen für unsere höchstrangigen Soldaten. Sie müssen groß sein, aus der feinsten Seide bestehen und vor allem so rot strahlen wie das Wappen des Scharlachroten Kreuzzugs.\n\nDas Material ist der einfachste Teil, denn ich möchte Eure Morgengespinstfäden dafür benutzen. Doch die perfekte Farbe zu finden, liegt weit außerhalb meiner Fähigkeiten. Sucht in der Welt nach dem perfekten Rotton, dann erkenne ich Euch als Partner in diesem Vorhaben an, indem ich die endgültige Vorlage mit Euch teile.", progress = "Lasst Euch ruhig Zeit. Das ist nur ein Leidenschaftsprojekt von mir. Es geht mir viel mehr darum, die passendste rote Farbe zu finden, anstatt die Regale damit zu füllen. Und es wäre mir lieber, wenn Ihr dieselbe Sorgfalt an den Tag legt, anstatt Euch meinetwillen zu beeilen.\n\nIch warte hier.", completion = "Ihr habt ein gutes Auge für Schönheit! Nicht, dass ich je daran gezweifelt hätte, aber ich habe nicht damit gerechnet, dass Ihr sofort einen Rotton findet, der mich so sehr anspricht. Und dann habt Ihr gleich mehrere mitgebracht! \n\n&lt;Taylor bewundert Eure vorgeschlagenen Färbemittel nacheinander, unberührt davon, dass eines davon eine Phiole voll Blut ist.&gt;\n\nDie beiden mit der Bezeichnung \"Blut von Helden\" und \"Blutrotes Klingenblatt\" sind meine Favoriten, das ist eine schwierige Entscheidung. Ich glaube, es ergibt Sinn, wenn wir beide unterschiedliche Farben verwenden. Deshalb nehme ich das Klingenblatt.", rewards = "Ihr bekommt:\n\nMuster: Blutrote Morgengespinsttasche"},
[90510] = {title = "Neu-Avalon", objective = "Nutzt die scharlachrote Insignie, sobald Ihr genug Verkleidungsteile gesammelt habt, um den Scharlachroten Kreuzzug in Neu-Avalon zu täuschen, und sprecht wieder mit Inquisitorin Jociphine. Spielercharaktere mit Handwerksberufen können Rezepte und Vorlagen für scharlachrote Rüstungsteile nutzen, die Ihr von gegnerischen Kreuzzüglern in Tyrs Hand und Neu-Avalon bekommen könnt.", description = "Wie Ihr gesehen habt, weist Neu-Avalon eine erhebliche militärische Präsenz auf, bietet Zivilisten aber auch Sicherheit und Schutz.\n\nWenn Ihr eine etwas dauerhaftere Verkleidung zusammenstellen könnt, denkt doch darüber nach, Eure Hilfe anzubieten. Euch bei den Leuten hier beliebt zu machen, könnte unserem Ziel, die Enklave zurückzuerobern, zuträglich sein, ganz zu schweigen von den ganzen Materialien und Ressourcen, derer Ihr Euch dort \"bemächtigen\" könntet. Bereichert Euch selbst und raubt ihrer Kriegsmaschinerie wichtige Vorräte.", progress = nil, completion = "Überzeugend genug, würde ich sagen.\n\nNeu-Avalon hat vor ein paar Jahren einige seiner Meisterhandwerker an eine Karawane nach Hearthglen verloren, aber wie ich sehe, sind nicht alle ihrer Vorlagen verloren gegangen.\n\nWenn Ihr nicht im Handwerk geübt seid, wird es Euch schwer fallen, in Neu-Avalon voranzukommen. Aber obgleich Ihr wisst, mit einem Hammer oder einer Nadel umzugehen, solltet Ihr zumindest dem Rüstmeister in der Kaserne einen Besuch abstatten. Vielleicht dürft Ihr Euch dort sogar im Lagerraum umsehen.", rewards = nil},
[90518] = {title = "Von Äpfeln und Untoten", objective = "Findet die Apfelplantage im Süden von Neu-Avalon und sammelt einige Äpfel. Kehrt zu Carrie Herdfeuer im Gasthaus von Neu-Avalon zurück, wenn Ihr Erfolg hattet. Wenn Ihr die Äpfel für zu teuer haltet, seht Euch nach alternativen Wegen um, sie zu bekommen.", description = "Wie schön, Euch wiederzusehen. Ich hatte keine Schwierigkeiten, die Vorratsschränke während Eurer Abwesenheit gefüllt zu halten, doch heute Morgen ist mir aufgefallen, dass ich nicht ganz genug Äpfel habe, um einen Kuchen zu backen. Ich dachte mir, es wäre an der Zeit, mir selbst etwas zu gönnen.\n\nWenn Ihr ein paar Minuten übrig habt, würdet Ihr einen Abstecher zur Plantage machen und einige pflücken? Leider habe ich Johnnys Kuchen auch noch nicht gebacken, aber ohne Äpfel kein Kuchen und ich werde bestimmt keine Äpfel an Johnnys Kuchen verschwenden!\n\nEuch werde ich aber selbstverständlich ein Stück abgeben.", progress = "Denkt daran, dass Johnny Euch seine besten Äpfel vielleicht extra berechnen will, aber Ihr findet bestimmt eine kreative Lösung, wenn Ihr ihm nicht die Taschen füllen wollt.", completion = "Wundervoll, ich werde sofort anfangen! Diese Äpfel sehen sogar noch schöner aus, als die letzte Lieferung von Euch, ich habe fast das Gefühl, Ihr wollt Euch bei mir anbiedern...\n\n&lt;Während Carrie die Arbeitsfläche zum Backen des Kuchens vorbereitet, macht sie eine überschwängliche Geste, mit der sie unmissverständlich ihren Ehering zur Schau stellt.&gt;\n\nDanke, dass Ihr vorbeigekommen seid und unser Abendessen aufgewertet habt. Markus und ich freuen uns schon auf Euren nächsten Besuch!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPirschersteakFilet aus der FlankeMorgengrauenomelettWeihsalz\n\nIhr bekommt außerdem:\n\nStück von Carries ApfelkuchenErlesene Gewürze"},
[90519] = {title = "Fisch auf Abruf", objective = "Untersucht das Boot, das südlich von Neu-Avalon angelegt hat, auf die Fischlieferung und bringt Carrie eine Ladung davon.", description = "Ich hasse Fisch. Ich kann den Geruch nicht ertragen. Ich finde sie unheimlich. Einfach grässlich.\n\nDa das hier meine Küche ist, kann ich meine Autorität beweisen und NEIN zu Fischimporten sagen, aber manchmal setzen unsere Soldaten sich in den Kopf, sie bräuchten unbedingt ein Fischfestmahl!\n\nHeute ist wieder einer dieser Abende, wie es scheint. Ich brauche Fisch, und zwar schnell!", progress = "Bringt mir bitte keine unvollständige Lieferung. Ich will alles auf einmal hinter mich bringen.\n\nWenn Ihr nicht genug Fisch für den Abend auftreiben könnt, könnt Ihr ja wieder nach Resten suchen. Das wäre sogar vorzuziehen, ehrlich gesagt.", completion = "Ah, ich hatte die Hoffnung, Ihr hättet heute Besseres zu tun, aber Ihr habt es Euch wohl zur Aufgabe gemacht, besonders verlässlich zu werden, seit wir uns kennengelernt haben.\n\nTja. Ich fange wohl besser an.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPirschersteakFilet aus der FlankeMorgengrauenomelettWeihsalz\n\nIhr bekommt außerdem:\n\nErlesene Gewürze"},
[90520] = {title = "Lebensmittelsicherheit", objective = "Besorgt Fleisch, das für Menschen genießbar ist. Wenn Ihr in Neu-Avalon keines findet, könnt Ihr bestimmt (irgendwann) von getöteten Tieren in den Östlichen Pestländern genug erbeuten.", description = "Ich erinnere mich, dass eine der ersten Zutaten, die für mich zu sammeln ich Euch bat, Fleisch war. Ich erinnere mich auch an viele Beschwerden an diesem Abend über Übelkeit nach dem Essen. Wirklich außerordentlich seltsam.\n\nAber egal, der Speisekammer fehlt es mal wieder an Fleisch und es wäre schön, wenn jemand Vertrauenswürdiges es auffüllen könnte. Ich kann es mir jetzt nicht leisten, auf eine Lieferung zu warten und dann eine Woche später herauszufinden, dass der Kurier gestorben ist!", progress = "Wenn Ihr so weiter trödelt, wird es das Abendessen heute verspätet geben.", completion = "Eure Hingabe zur Beständigkeit ist unglaublich, mein Herz. Diese Portionen sind professionell geteilt und besitzen dieselbe Farbe und Textur wie Eure letzte Lieferung. Sollte ich mich je in einer Situation wiederfinden, in der ich mein eigenes Essen erlegen muss, steht Ihr mir dann hoffentlich zur Seite.\n\nUnd Markus natürlich.\n\nLasst mich Euch das abnehmen und anfangen. Neu-Avalon wird heute Abend vorzüglich speisen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPirschersteakFilet aus der FlankeMorgengrauenomelettWeihsalz\n\nIhr bekommt außerdem:\n\nErlesene Gewürze"},
[90560] = {title = "Vertraute Fäule", objective = "Sammelt verfärbte Tierherzen von Kreaturen in den Pestländern und bringt sie und den misslungenen Heiltrank zu einem interessierten Mitglied der Königlichen Apothekervereinigung.", description = "<Ihr habt eine Phiole mit einer widerlichen, zähen Flüssigkeit auf einem Labortisch gefunden. Sie war umgeben von verschiedenen Zutaten, die sorgfältig abgemessen und in akkurate Portionen geteilt wurden. Obwohl die Kräuter für Euch nicht identifizierbar sind, liegt ein unbeschädigtes und verfärbtes Tierherz in der Nähe.\n\nDie Mischung kommt Euch bekannt vor und erinnert Euch an die jüngeren Experimente der Königlichen Apothekervereinigung. Wenn Eure Neugier Euren Ekel übersteigt, könnte vielleicht eines ihrer Mitglieder Interesse an Eurer Entdeckung zeigen.>", progress = nil, completion = nil, rewards = nil},
[90566] = {title = "Oh, meine blutenden Herzen!", objective = "Bringt den Korb mit verfärbten Tierherzen und einige blutende Herzen der Pestländer zu Apotheker Renferrel beim Grabmal im Silberwald.", description = "Von der beeindruckenden Verderbnis auszugehen, die Eure Proben aufweisen, scheint Ihr Euch in den Pestländern gut auszukennen. Zweifellos versteht Ihr, wie unpraktisch es für ein einsames Mitglied der Königlichen Apothekervereinigung ist, das Bollwerk für Vorräte zu durchqueren.\n\nRenferrel ist an blutenden Herzen interessiert, der Blume. Und dazu an einst schlagenden Herzen. Ich weiß nicht genau, ob es ihm um alchemistische Forschung oder persönliche Vorlieben geht, aber ich bin sicher, er würde sich über eine Lieferung diverser Herzen freuen.", progress = "Ob ich eine Lieferung erwarte?\n\n<Apotheker Renferrel überprüft seine Notizen.>\n\nIhr seht nicht aus wie das Testobjekt, das ich bestellt habe...", completion = "Oh. Meine blutenden Herzen. Nachdem ich monatelang auf Faranell gewartet habe, kommen sie an, als ich die Forschung schon längst aufgegeben habe. Ausgezeichnet.\n\nAber was auch immer Ihr da in diesem Korb habt, weckt mein Interesse. Es erinnert mich an die Herzen der hiesigen Worgen, aber diese hier scheinen mehr Widerstandskraft gegen Fäule und Verderbnis aufzuweisen.\n\nHier, dieses Rezept ist von einer älteren Mischung inspiriert, die ich in der Vergangenheit entwickelt habe. Probiert sie aus und lasst mich wissen, wie es lief.", rewards = "Ihr bekommt:\n\nRezept: Erheblicher verfärbter Heiltrank"},
[90567] = {title = "Unvertraute Fäule", objective = "Sammelt verfärbte Tierherzen und blutende Herzen in den Pestländern. Bringt sie und den misslungenen Heiltrank zu einem interessierten Alchimisten in Darnassus.", description = "<Ihr habt eine Phiole mit einer widerlichen, zähen Flüssigkeit auf einem Labortisch gefunden. Sie war umgeben von verschiedenen Zutaten, die sorgfältig abgemessen und in akkurate Portionen geteilt wurden. Obwohl die Kräuter für Euch nicht identifizierbar waren, lag ein unbeschädigtes und verfärbtes Tierherz in der Nähe.\n\nAlchemisten in Darnassus könnten eine Idee haben, wie sie die möglicherweise heilenden Eigenschaften dieses Trankes nutzbar machen können. Ihr solltet ihnen außerdem Blumen mitbringen. Es wäre unhöflich, mit nur einem Haufen Herzen in ein Geschäft zu platzen.>", progress = "Ishnu-alah, Reisender. Seid Ihr gekommen, um die Kunst der Alchemie zu studieren, oder womit kann ich Euch sonst helfen?", completion = "Das hatte ich fast vermutet. Kaum zu glauben, aber Ihr seid nicht die erste Person, die mir exakt diese Enthüllung vorlegt. Wären die Umstände nicht so finster, würde ich alles für einen ausgefeilten Scherz auf meine Kosten halten.\n\nDie Effekte der Pestländer zu studieren ist zwar interessant, aufgrund der großen Entfernung aber nicht immer machbar. Dennoch konnte ich mit Proben, die mir vor einer Weile überreicht wurden, schon Fortschritte machen und würde meine Erkenntnisse gerne mit Euch teilen.\n\nDenkt bitte an mich, wenn Ihr weitere Exemplare findet.", rewards = "Ihr bekommt:\n\nRezept: Verfärbter HeiltrankRezept: Erheblicher verfärbter Heiltrank"},
[90625] = {title = "Auf unheilvollen Flügeln", objective = "Bringt den Flügel Balnazzars zur Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Ein zerrissener Flügel des Schreckenslords Balnazzar ist alles, was von dem gestürzten Nathrezim übrig geblieben ist.\n\nJemand in der Kapelle des hoffnungsvollen Lichts könnte daran interessiert sein.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[90626] = {title = "Sehne des Lichts", objective = "Besiegt Solistrasza und erlangt eine Sehne eines ausgewachsenen Lichtdrachen. Dann bringt sie zu Grok'lo in die Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", description = "Grok'lo wird Treffen mit seinem speziellen Handwerker arrangieren, sobald Ihr geeignete Sehne für Flügel von Riesenfledermaus gefunden habt.\n\nGrok'lo empfiehlt, bestmögliche Sehne zu finden.\n\n<Grok'lo lächelt unter seinem Helm.>\n\nDrachensehnen definitiv am Besten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"},
[90627] = {title = "Der gewiefte Handwerker", objective = "Trefft Mizzle den Gewieften im Norden von Düsterbruch.\n\nStellt sicher, dass er nicht abgelenkt ist, also keine wichtigen Oger auf dem Weg töten, sonst er muss sie ersetzen und kann Euch nicht helfen.\n\nUnd geht alleine.", description = "In Ordnung, Name meines Handwerkers ist Mizzle der Gewiefte.\n\nIst so offensichtlich, selbst Grok'lo kann sehen! Aber alle denken, Name ist, weil er clever ist. NEIN! Ist Oger, ist alles andere als clever! Ist einfach nur gewieft beim Handwerken!\n\n<Grok'lo nickt.>\n\nGeht in Norden von Düsterbruch und trefft ihn. Aber stellt sicher, dass er nicht abgelenkt ist, wenn Ihr ihn seht.\n\nUnd geht alleine.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchwinge und Faden"},
}
